INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a7fce510-b287-41bd-8817-358c74b3b926', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Why should we avoid repeatedly washing raw rice and pulses with large amounts of water before cooking?', 'Frequent vigorous washing leaches out water-soluble micronutrients like thiamine, niacin, and essential minerals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd9566c6-ee2e-4ff6-95f6-cb863086550a', 'It dissolves water-soluble vitamins (like Vitamin B complex and C) and minerals, washing them away', true, 'a7fce510-b287-41bd-8817-358c74b3b926');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca4eacd9-8161-44dd-aead-35d03c4f65ee', 'It converts carbohydrates into harmful toxins', false, 'a7fce510-b287-41bd-8817-358c74b3b926');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25307a20-db53-478b-af29-8249334bc77f', 'It increases fat content', false, 'a7fce510-b287-41bd-8817-358c74b3b926');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea9d7de4-3a8e-417d-8396-11aaad082fc2', 'It prevents food from getting cooked', false, 'a7fce510-b287-41bd-8817-358c74b3b926');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5976fbb1-3886-44d9-937c-47233e254d86', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'What physical symptoms are exhibited by a child suffering from Kwashiorkor (protein deficiency)?', 'Severe protein malnutrition leads to hypoalbuminemia causing abdominal edema (pot belly) and depigmented hair.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('695d9bcd-fbc1-49cf-be7b-76d655533f12', 'Swollen swollen belly (pot belly), discoloured hair, stunted growth, and skin diseases', true, '5976fbb1-3886-44d9-937c-47233e254d86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8df02f6c-64e8-4444-bffa-1164c68973fb', 'Extremely soft bones bending into bow legs', false, '5976fbb1-3886-44d9-937c-47233e254d86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bdb1fa5-f418-4513-aaef-d9af0e616715', 'Bleeding gums and loose teeth', false, '5976fbb1-3886-44d9-937c-47233e254d86');
