INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f5919030-ecfd-49ac-8657-de09d0265b08', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'A diet containing excessive fat-rich fried foods, samosas, and sweets over long periods can lead to a condition called:', 'Unburned surplus dietary calories from saturated fats get stored as adipose tissue, resulting in clinical obesity.', NOW()) ON CONFLICT DO NOTHING;
