INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9585e8f8-7df9-4aea-8f16-f93a945752c8', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Why does our body need roughage (dietary fibre) even though it provides zero energy and no nutrients?', 'Cellulose fibres stimulate intestinal peristaltic contractions, facilitating efficient transit of fecal bolus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b07cd1b-00f0-4f5a-86e1-099f53c2d5cf', 'It adds bulk to the food, aids normal peristalsis, and helps our body expel undigested waste smoothly', true, '9585e8f8-7df9-4aea-8f16-f93a945752c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edf26a8a-29e9-423b-840a-b23ae31320ad', 'It fights bacterial infections directly', false, '9585e8f8-7df9-4aea-8f16-f93a945752c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65023286-7d86-441d-9c16-a73b3da3cb8a', 'It builds muscular tissues', false, '9585e8f8-7df9-4aea-8f16-f93a945752c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01824eaa-944a-4fd4-ac5a-2a08e8076f69', 'It produces red blood cells', false, '9585e8f8-7df9-4aea-8f16-f93a945752c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d2b595a-b3ac-4dcd-8cea-099ae16c56a6', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Which mineral works in synergy with Vitamin D to maintain mineralized bone density and strong enamel on teeth?', 'Hydroxyapatite crystals of bones and teeth are composed primarily of calcium phosphate complexes.', NOW()) ON CONFLICT DO NOTHING;
