INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d8ca0b2-617c-4637-8a0c-10050d6df6d0', 'Sodium', false, '9d2b595a-b3ac-4dcd-8cea-099ae16c56a6');
