INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36d2e6a9-28e1-429f-a97c-ac0cc8d6358f', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'What happens during a severe deficiency of Vitamin B1 (Thiamine)?', 'Thiamine deficiency impairs carbohydrate metabolism and neurological signaling, causing peripheral neuromuscular weakness (Beri-beri).', NOW()) ON CONFLICT DO NOTHING;
