INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3c9c9c4-1e80-43e3-adc2-3e559fb709c9', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Why is drinking 2 to 3 litres of clean water every day essential for human physiological health?', 'Water serves as the biological universal solvent, regulating thermoregulation and renal clearance of toxins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('668a97a8-68aa-4794-b473-aff09596bb61', 'Water absorbs nutrients from food into the bloodstream and helps excrete metabolic wastes as urine and sweat', true, 'd3c9c9c4-1e80-43e3-adc2-3e559fb709c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e67e621a-5ca7-45a2-8d9d-b623ee421d99', 'Water replaces the need for carbohydrates', false, 'd3c9c9c4-1e80-43e3-adc2-3e559fb709c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2c62459-a00a-4243-94b4-13b277b563fd', 'Water generates body heat during cold weather', false, 'd3c9c9c4-1e80-43e3-adc2-3e559fb709c9');
