INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e140909b-ae27-4adf-96ba-939b18eddbc1', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Which symptom specifically characterizes Rickets in growing children?', 'Lack of Vitamin D impairs calcium absorption, leading to defective osteoid mineralization that deforms weight-bearing leg bones.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1a19e7b-edbc-4ebd-8a64-f9f2ec96d189', 'Bones become soft, fragile, and bend into bow legs or knock knees', true, 'e140909b-ae27-4adf-96ba-939b18eddbc1');
