INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f34c24f9-4347-49a6-bf5a-2bb54184bb40', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Which of the following foods is the richest source of animal protein containing all essential amino acids?', 'Animal proteins like ovalbumin in eggs and casein in milk provide high biological value complete amino acid profiles.', NOW()) ON CONFLICT DO NOTHING;
