INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64fd5e38-7b9a-4936-b29d-5d6c6a2dcf12', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Why do athletes and physical labourers require higher amounts of carbohydrate-rich foods compared to sedentary desk workers?', 'Glycolysis of carbohydrate substrates provides the fastest fuel pathway for high-output skeletal muscle work.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('582f7c77-f18c-4a42-bfa7-0242e09833e7', 'Carbohydrates are rapidly broken down into glucose, providing immediate ATP energy for strenuous muscular contractions', true, '64fd5e38-7b9a-4936-b29d-5d6c6a2dcf12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fddfa16-cf28-448a-be63-a8519f302dca', 'Carbohydrates repair broken bone joints', false, '64fd5e38-7b9a-4936-b29d-5d6c6a2dcf12');
