INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a76b3b25-0791-4785-ab1d-2924fe324f1e', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Which pair of food items is predominantly rich in starch?', 'Tubers (potatoes) and cereal grains (rice) store excess photosynthetic energy primarily in the form of amylose/amylopectin starch granules.', NOW()) ON CONFLICT DO NOTHING;
