INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c1f5f59-655e-40a8-aab6-45a9539aabff', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'What is a ''Balanced Diet''?', 'A balanced diet supplies macro and micronutrients in physiological proportions to sustain metabolic requirements without deficits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d7f74be-66ab-4a03-ace0-c33d2817ea0b', 'A diet providing all essential nutrients in proper proportions, along with adequate roughage and water for optimal health', true, '1c1f5f59-655e-40a8-aab6-45a9539aabff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e9a443e-2747-4235-9a81-25e0cf6d9e21', 'A diet composed only of fruits and green salad', false, '1c1f5f59-655e-40a8-aab6-45a9539aabff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7496c08b-b664-4e94-957e-c1b119bca4b6', 'A diet containing equal weights of butter and sugar', false, '1c1f5f59-655e-40a8-aab6-45a9539aabff');
