INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c369008f-e37f-46f3-b619-6674c1b018ce', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Why does the government mandate the iodization of common edible table salt (NaCl)?', 'Universal salt iodization with potassium iodate is an effective public health intervention preventing iodine deficiency disorders (IDD).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d912054d-6423-40ed-be55-c78027a44662', 'To ensure regular microscopic intake of iodine across all populations to prevent goitre and mental impairment in children', true, 'c369008f-e37f-46f3-b619-6674c1b018ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dad1637-eb38-42eb-85b0-a9aa98eb4c00', 'To make table salt white in color', false, 'c369008f-e37f-46f3-b619-6674c1b018ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edcd0ffd-ae69-491c-82f1-ba3522411907', 'To prevent table salt from absorbing moisture', false, 'c369008f-e37f-46f3-b619-6674c1b018ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('215f27c2-e2a9-4718-b0c4-b1029df61eb6', 'To improve salt sweetness', false, 'c369008f-e37f-46f3-b619-6674c1b018ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('51dc041b-f02d-4e4d-a12d-454024935530', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Which symptom indicates a clinical deficiency of Iron (Anemia)?', 'Decreased erythrocyte haemoglobin reduces systemic tissue oxygenation, causing chronic fatigue and pallor (Anemia).', NOW()) ON CONFLICT DO NOTHING;
