INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5027c4d-23af-4dbf-b5cb-7a0e2e9a36fc', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Which of the following citrus fruits provides the highest concentration of natural Vitamin C?', 'Amla is one of the richest botanical sources of ascorbic acid, packing up to 600 mg of Vitamin C per 100 g.', NOW()) ON CONFLICT DO NOTHING;
