INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a3ffadd5-9c5d-4d16-a251-930c7c152374', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Medium', 'Why is deep-frying vegetables at high temperatures considered nutritionally detrimental?', 'Prolonged thermal stress degrades heat-sensitive vitamins (C, B-complex) and generates free fatty acid radicals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f693a25-4fe7-4f4c-a736-6705acbcfbdb', 'High heat oxidizes and destroys delicate vitamins while loading the food with unhealthy oxidized fats', true, 'a3ffadd5-9c5d-4d16-a251-930c7c152374');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84287066-4013-4236-a924-d3e6528c91de', 'It turns starch into stone', false, 'a3ffadd5-9c5d-4d16-a251-930c7c152374');
