INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f95b9a17-5956-4dde-b0c1-b11388f93246', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Hard', 'Match Column I with Column II:
(a) Vitamin A  -> (i) Bleeding gums
(b) Vitamin B1 -> (ii) Rickets (bowed bones)
(c) Vitamin C  -> (iii) Poor vision in dim light
(d) Vitamin D  -> (iv) Beri-beri (weak muscles)', 'Vit A deficiency causes nyctalopia; Vit B1 causes Beri-beri; Vit C causes Scurvy; Vit D causes Rickets.', NOW()) ON CONFLICT DO NOTHING;
