INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f2505f2-3fa3-4a7e-b09c-0d3e958b6900', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Hard', 'Why do sailors on ancient long-distance wooden ships historically suffer from loose teeth, joint pain, and bleeding skin lesions after months at sea?', 'Non-perishable ship rations (hardtack, salted meat) lacked fresh produce, inducing severe scorbutic collagen breakdown (James Lind''s trials).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a035838c-b266-403a-a394-04abe2662988', 'Absence of fresh fruits and green vegetables on long voyages resulted in severe nutritional Scurvy (Vitamin C depletion)', true, '7f2505f2-3fa3-4a7e-b09c-0d3e958b6900');
