INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('461c24de-25f5-48ae-9be9-18fef16098cb', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Hard', 'A student adds 2 drops of Copper Sulphate and 10 drops of Caustic Soda to a test tube containing crushed soybean powder mixed with water. What sequence of physical observations confirms protein presence?', 'Biuret test: Cu2+ ions coordinate with unprotonated peptide nitrogen atoms in alkaline conditions, forming a violet chelate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9766264-253e-4196-8b80-12dfb895227d', 'The white suspension turns distinct violet/purple after shaking and standing for a few minutes', true, '461c24de-25f5-48ae-9be9-18fef16098cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5f2df56-3676-46f1-b78b-081e210f6880', 'The solution immediately turns deep blue-black', false, '461c24de-25f5-48ae-9be9-18fef16098cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04b5abee-de45-4817-9f99-fe826259a497', 'The test tube gets freezing cold with gas bubbles', false, '461c24de-25f5-48ae-9be9-18fef16098cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a64c4ca-a3c4-444e-9f80-bf394b04326b', 'A yellow precipitate settles down', false, '461c24de-25f5-48ae-9be9-18fef16098cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c283bb0f-ab0d-406f-92da-2232a7f39cbe', 'Class 6', 'Science', 'Chapter 1: Components of Food', 'Hard', 'Why are sprouted seeds (like sprouted moong and chana) significantly more nutritious than raw dry seeds?', 'Germination activates endogenous hydrolytic enzymes, deactivating anti-nutrients (phytates) and bio-synthesizing vitamins and bioactive peptides.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d37d651b-c42e-44ad-93a0-cbf3fdcabb76', 'Sprouting triggers enzymatic synthesis of vitamins (especially Vitamin C and B-complex) and converts complex starches into easily digestible nutrients', true, 'c283bb0f-ab0d-406f-92da-2232a7f39cbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3df0682b-8431-4320-8e73-87303fe66360', 'Sprouting multiplies fat percentage by 100 times', false, 'c283bb0f-ab0d-406f-92da-2232a7f39cbe');
