INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4aaaee92-5bf6-4298-863e-1cacdc32a4f4', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Easy', 'What is the smallest 4-digit number using the digits 5, 0, 8, and 2 without repetition?', 'A 4-digit number cannot start with 0; hence place the smallest non-zero digit (2) first, followed by 0, 5, 8 giving 2058.', NOW()) ON CONFLICT DO NOTHING;
