INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1617c479-fd1f-454c-8f4d-dcd984e40e67', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Easy', 'How many millilitres (mL) make 1 Litre?', 'The metric prefix ''milli'' denotes one-thousandth (1/1000); hence 1 L = 1000 mL.', NOW()) ON CONFLICT DO NOTHING;
