INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8e2203e-bd8e-464f-a3ec-9106fa6eee22', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'A vessel has 4 litres and 500 mL of curd. In how many glasses, each of 25 mL capacity, can it be filled?', 'Total capacity = 4,500 mL. Number of glasses = 4,500 ÷ 25 = 180 glasses.', NOW()) ON CONFLICT DO NOTHING;
