INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3bf3010b-abc1-41b5-af36-d86a745e583c', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'Estimate the product 578 × 161 by rounding off each factor to its greatest place:', '578 rounds to 600 (hundreds place); 161 rounds to 200 (hundreds place). Estimated product = 600 × 200 = 1,20,000.', NOW()) ON CONFLICT DO NOTHING;
