INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc88cd18-c786-4c2a-a00a-54374f5ebb59', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'To stitch a shirt, 2 m 15 cm cloth is needed. Out of 40 m cloth, how many shirts can be stitched and how much cloth will remain?', 'Cloth per shirt = 215 cm. Total cloth = 4,000 cm. 4000 ÷ 215 = 18 shirts with remainder 130 cm = 1 m 30 cm.', NOW()) ON CONFLICT DO NOTHING;
