INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5064bdf8-290e-4f4c-940e-0a4d23b1a5b6', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'What is the Hindu-Arabic numeral value of the Roman expression LXXIX + XLIV?', 'LXXIX = 70 + 9 = 79. XLIV = 40 + 4 = 44. Sum = 79 + 44 = 123 (CXXIII).', NOW()) ON CONFLICT DO NOTHING;
