INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc8764f2-d476-4600-ba35-dfd240bd268a', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'A merchant had ₹ 78,592 with her. She placed an order for purchasing 40 radio sets at ₹ 1,200 each. How much money will remain with her after the purchase?', 'Cost of 40 radios = 40 × 1,200 = ₹ 48,000. Remaining balance = 78,592 - 48,000 = ₹ 30,592.', NOW()) ON CONFLICT DO NOTHING;
