INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e66e2fc-8e64-4d39-bdc0-fcbe45df72a8', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'In the numeral 7,89,34,521, what is the place value and face value of the digit 8?', 'The digit 8 occupies the Ten Lakhs place; its place value is 8 × 10,00,000 = 80,00,000 while its face value is the digit itself (8).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7d11c06-f116-4fd8-8668-2a1c07429fa3', 'Place value = 80,00,000 (Eighty Lakhs); Face value = 8', true, '6e66e2fc-8e64-4d39-bdc0-fcbe45df72a8');
