INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('86b69aaa-ea19-4cfd-9a93-fbc7202a07e2', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'Estimate the sum 5,290 + 17,986 by rounding off to the nearest thousands:', '5,290 rounds to 5,000; 17,986 rounds to 18,000. Sum = 5,000 + 18,000 = 23,000.', NOW()) ON CONFLICT DO NOTHING;
