INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e27cf126-f5ab-4504-8e23-9d744911458c', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'Write 7,452 in expanded form:', 'Expanded form represents the sum of the products of each digit with its corresponding place value.', NOW()) ON CONFLICT DO NOTHING;
