INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4705a94-55b1-4eea-a412-a0c31a5b37dd', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'A medicine box contains 2,00,000 tablets each weighing 20 mg. What is the total weight of all tablets in grams and in kilograms?', 'Total weight = 200,000 × 20 mg = 4,000,000 mg = 4,000,000 ÷ 1,000 g = 4,000 g = 4 kg.', NOW()) ON CONFLICT DO NOTHING;
