INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb91def3-bc3e-45f4-b67c-bb0c509210f9', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'The distance between a school and a student''s house is 1 km 875 m. Every day she walks both ways. Find the total distance covered by her in 6 days.', 'Daily round trip = 2 × 1,875 m = 3,750 m. 6 days = 6 × 3,750 m = 22,500 m = 22 km 500 m.', NOW()) ON CONFLICT DO NOTHING;
