INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e43843a-f666-4f75-a7bb-cc3737fcd67d', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'What is the Roman numeral for 69?', '69 = 60 + 9 = (50 + 10) + (10 - 1) = LX + IX = LXIX.', NOW()) ON CONFLICT DO NOTHING;
