INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3da115b8-1784-450d-9094-3f444242782e', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Medium', 'Find the difference between the place values of two 7s in the number 57,34,725:', 'First 7 is at Ten Lakhs place (7,00,000); second 7 is at Hundreds place (700). Difference = 7,00,000 - 700 = 6,99,300.', NOW()) ON CONFLICT DO NOTHING;
