INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('707a5dc0-74f8-4c95-a297-82dac7b73e5e', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Hard', 'How many total 7-digit numbers exist in all of mathematics?', 'Largest 7-digit number = 99,99,999; Smallest 7-digit number = 10,00,000. Total = (99,99,999 - 10,00,000) + 1 = 90,00,000.', NOW()) ON CONFLICT DO NOTHING;
