INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1cb66143-ee14-4a91-a4db-bf52729f65fc', 'Class 6', 'Mathematics', 'Chapter 1: Knowing Our Numbers', 'Hard', 'What is the Roman numeral for 495?', '495 = 400 + 90 + 5 = CD + XC + V = CDXCV.', NOW()) ON CONFLICT DO NOTHING;
