INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6116ee8f-26f4-4459-8dc1-c50cc584f977', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Easy', 'What promise did the elf make to Patrick in exchange for saving him from the cat?', 'The frightened elf promised to grant Patrick one wish if he didn''t give him back to the cat.', NOW()) ON CONFLICT DO NOTHING;
