INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b379662-7892-465c-a989-3cfa937ccff6', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'Why did the little elf constantly squeak and demand Patrick''s help in Mathematics?', 'The elf exclaimed that elves never needed times tables, addition, or division, forcing Patrick to sit beside him and guide every step.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('038c7888-6202-46e5-83b7-97ce11adbc7b', 'Elves knew nothing of human timetables, addition, subtraction, fractions, and division', true, '6b379662-7892-465c-a989-3cfa937ccff6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0d03d29-a6cf-4f50-8f9e-077d863f63c5', 'The elf had broken his glasses', false, '6b379662-7892-465c-a989-3cfa937ccff6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e277c564-780b-4aee-b22e-d480f6bc44a7', 'The elf wanted to play video games', false, '6b379662-7892-465c-a989-3cfa937ccff6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73f59f35-df31-49d2-b631-fd6ce6a5efcc', 'The math book was written in secret code', false, '6b379662-7892-465c-a989-3cfa937ccff6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed7b0f39-85e2-411a-999c-f198a91f0bd3', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'How did the elf behave when it came to reading Human History?', 'To the elf, human history was an utter mystery, so he ordered Patrick to go to the library and read books aloud to him.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d33a2d7-6199-4fd6-8a6b-ce4e43f0a408', 'He considered human history ''a mystery'' and shrieked for Patrick to fetch more books from the library and read them aloud', true, 'ed7b0f39-85e2-411a-999c-f198a91f0bd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('307b49af-9ab6-48dc-a8e2-b1a0b4aa15e5', 'He knew everything and finished it in one minute', false, 'ed7b0f39-85e2-411a-999c-f198a91f0bd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('205e78f5-cb25-42d8-8d05-9839d2e2126f', 'He tore up the history textbook', false, 'ed7b0f39-85e2-411a-999c-f198a91f0bd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7924b27-a61b-4f48-846c-9b47ff582f27', 'He fell asleep immediately', false, 'ed7b0f39-85e2-411a-999c-f198a91f0bd3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7570bafd-b03e-4d2c-8964-421f79f6dfc8', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What real transformation took place in Patrick''s daily habits and attitude by the end of the semester?', 'Patrick developed self-discipline: cleaning his room, doing daily chores, staying cheerful, and developing a completely new positive attitude.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29097ca3-7f92-45bf-9573-6356bde45075', 'He became a model kid who cleaned his room, did his chores, stayed cheerful, and never lost his temper', true, '7570bafd-b03e-4d2c-8964-421f79f6dfc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15fa849c-976e-4975-a00c-4d413471a601', 'He became lazy and hired more elves', false, '7570bafd-b03e-4d2c-8964-421f79f6dfc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ed0e1d7-3a14-400c-b985-61e5c5b84cd1', 'He dropped out of school to play sports', false, '7570bafd-b03e-4d2c-8964-421f79f6dfc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a6f8f08-6654-4b93-9a21-3b6536b721f5', 'He stopped talking to his teachers', false, '7570bafd-b03e-4d2c-8964-421f79f6dfc8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4f6e3fa-98fd-453a-99b8-d925397eab06', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What is the fundamental difference between a ''House'' and a ''Home'' as described in the poem ''A House, A Home''?', 'Poet Lorraine M. Halli distinguishes physical inanimate construction (house) from the emotional bond of loving family (home).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('064e1b2b-dd37-44b8-aabe-45a50b921ae0', 'A house is made of lifeless brick, stone, and wood; a home is made of loving family members caring selflessly for one another', true, 'd4f6e3fa-98fd-453a-99b8-d925397eab06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82e09aa2-115f-4863-b9b9-b4b247cb2fd1', 'A house has two floors; a home has only one room', false, 'd4f6e3fa-98fd-453a-99b8-d925397eab06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6ddbbde-a5c4-4a79-90b9-7d41204aefcd', 'A home has expensive furniture; a house is empty', false, 'd4f6e3fa-98fd-453a-99b8-d925397eab06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5d3673c-98d4-41e4-9f0b-28c7d80f4393', 'There is no difference between them', false, 'd4f6e3fa-98fd-453a-99b8-d925397eab06');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41f4b57b-d1bb-4730-92dc-977f30d3915a', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'Why did the elf slip out quietly through the back door on the last day of the semester?', 'On the 35th day, the semester ended with zero remaining homework; free from his pledge, the elf slipped away quietly.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af2420cb-3e0c-4f25-84f0-780e1989fc73', 'There was no more homework left to do, and his contracted promise was fulfilled', true, '41f4b57b-d1bb-4730-92dc-977f30d3915a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81d87da4-b05b-4760-b357-d789e54ef56f', 'He was terrified of Patrick''s parents', false, '41f4b57b-d1bb-4730-92dc-977f30d3915a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d13a049-b5b0-45d9-b14f-dd1f77202413', 'The cat attacked him again', false, '41f4b57b-d1bb-4730-92dc-977f30d3915a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e116b239-6878-45c4-86d8-019223b1d549', 'He stole Patrick''s Nintendo console', false, '41f4b57b-d1bb-4730-92dc-977f30d3915a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b2ec849-975b-490d-a0bd-1ff48e3c7b05', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'Choose the correct synonym for the phrase ''a nagging person'' as depicted by the elf in the story:', 'A ''nag'' is one who persistently annoys, complains, or urges someone to do continuous work.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d14e954c-a5c2-40f4-a972-5ecf2be11414', 'A nag', true, '3b2ec849-975b-490d-a0bd-1ff48e3c7b05');
