INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcf3f140-f165-48aa-b1f5-07b6e723dd23', 'A scholar', false, '3b2ec849-975b-490d-a0bd-1ff48e3c7b05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d66c9206-b59d-4c7c-b9e6-52202d839405', 'A pioneer', false, '3b2ec849-975b-490d-a0bd-1ff48e3c7b05');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b1cb50d-6896-42b8-abb9-54a847007bf9', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What figure of speech / literary device is used in the line: ''His face wrinkled like a dishcloth thrown in the hamper''?', 'The explicit comparison using ''like'' between the elf''s wrinkled face and a dishcloth is a Simile.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57f82826-e7e6-4bae-989d-2b8e2288fede', 'Simile', true, '2b1cb50d-6896-42b8-abb9-54a847007bf9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e364841-a96e-4651-b99a-623d24b247eb', 'Metaphor', false, '2b1cb50d-6896-42b8-abb9-54a847007bf9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f61ff70-05e8-4705-84af-ffe819f45fc6', 'Personification', false, '2b1cb50d-6896-42b8-abb9-54a847007bf9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf12ab12-c8ff-4c07-8c41-8cf14466c8c3', 'Alliteration', false, '2b1cb50d-6896-42b8-abb9-54a847007bf9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd12f6fc-739a-47e9-aadd-fac48f21df23', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What moral lesson does the story ''Who Did Patrick''s Homework?'' impart to young learners?', 'The narrative illustrates that self-reliance, diligent effort, and intrinsic motivation create true personal excellence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b23382c-3466-4876-ab7d-3b61c989b629', 'Self-help and persistent hard work are the true secrets to academic success, not magical shortcuts', true, 'fd12f6fc-739a-47e9-aadd-fac48f21df23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fbdec10-cca2-4cc9-af5f-fcc970c7745d', 'Elves are dangerous creatures to keep as pets', false, 'fd12f6fc-739a-47e9-aadd-fac48f21df23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc4c40c9-b8bd-404e-aad0-2ec5327f6887', 'Homework should be banned in schools', false, 'fd12f6fc-739a-47e9-aadd-fac48f21df23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c893485a-fc5c-47f2-aa3c-88142549f4c8', 'Video games are better than studies', false, 'fd12f6fc-739a-47e9-aadd-fac48f21df23');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4aa45945-d1b1-4fb6-9b74-d6e05d21cd6e', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'In the supplementary reader tale ''A Tale of Two Birds'', why did the two young birds behave so completely differently?', '''One is known by the company one keeps.'' Environmental conditioning and peer company shaped their distinct characters.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80f70ecf-5e1c-4d71-90cf-318889ca64d1', 'One lived with robbers and learned abusive language; the other lived near a Rishi''s ashram and learned courteous hospitality', true, '4aa45945-d1b1-4fb6-9b74-d6e05d21cd6e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f40a2af-a2d2-48d9-89ac-9c97536aef5c', 'They belonged to different biological species', false, '4aa45945-d1b1-4fb6-9b74-d6e05d21cd6e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e150026-7b7e-4070-9083-506d369c305e', 'One was blind and the other was deaf', false, '4aa45945-d1b1-4fb6-9b74-d6e05d21cd6e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f97c100c-1dce-4139-afe0-9f85144ca62b', 'One was fed meat and the other ate grains', false, '4aa45945-d1b1-4fb6-9b74-d6e05d21cd6e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7dfaf794-facb-4213-b5bd-5e81e6e7d855', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What phrase did the King utter upon hearing the ashram bird welcome him so gently?', 'The King was amazed by how two identical sibling birds displayed opposite behavioral temperaments due to their company.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2eae8053-41d2-4609-ae65-61701e528458', '"This bird looks just like the other outside the cave, but how different their talk is!"', true, '7dfaf794-facb-4213-b5bd-5e81e6e7d855');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a17561e-731c-49a9-bb7f-51c647999de6', '"I will shoot this bird for dinner."', false, '7dfaf794-facb-4213-b5bd-5e81e6e7d855');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b65cd6bb-0383-4b9d-a12b-085fee779ae9', '"This bird is an imposter."', false, '7dfaf794-facb-4213-b5bd-5e81e6e7d855');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0eb3868a-9f95-4c15-abb7-c4e105ba82e2', '"Take me to the robbers'' den."', false, '7dfaf794-facb-4213-b5bd-5e81e6e7d855');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8039b670-de8b-4bb9-83a5-33090b194b0d', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What is the meaning of the word ''Britches'' in the description of the elf?', '''Britches'' (or breeches) are old-fashioned short trousers fitting snugly just below the knee.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ea2da6d-f7a7-4240-a8ca-0d3835d163b0', 'Short trousers / breeches', true, '8039b670-de8b-4bb9-83a5-33090b194b0d');
