INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9e6a713-dfd4-40c5-a6a4-5bf582507485', 'A magical cape', false, '8039b670-de8b-4bb9-83a5-33090b194b0d');
