INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a3749f04-abd2-4d1d-823c-b81614f68df8', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'Fill in the blank: ''Patrick stayed up nights, feeling ______ and tired, yet went to school with his eyes puffed and bleary.''', '''Weary'' expresses extreme physical and mental fatigue resulting from late-night studying.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90d5d1fb-62b2-412c-b12a-fd94d376d32a', 'weary', true, 'a3749f04-abd2-4d1d-823c-b81614f68df8');
