INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('181292e3-126d-4961-8506-0d5c758da402', 'frightened', false, 'a3749f04-abd2-4d1d-823c-b81614f68df8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0043140-85fd-4b6d-a004-bdb117ba3fb5', 'amused', false, 'a3749f04-abd2-4d1d-823c-b81614f68df8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0950aa40-8888-4edb-b913-089533418697', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What did Patrick''s teachers do when he started scoring top grades?', 'His teachers were genuinely pleased, admiring his transformed dedication and academic turnaround.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfa97dfe-59cc-4090-a611-81793f5c7330', 'They smiled, praised him, and were full of sincere appreciation', true, '0950aa40-8888-4edb-b913-089533418697');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec6033b9-00cb-4ef1-9937-6c2ca7766eaa', 'They accused him of cheating with an elf', false, '0950aa40-8888-4edb-b913-089533418697');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5e173ca-e51c-498e-aada-68937748d062', 'They gave him twice as much homework', false, '0950aa40-8888-4edb-b913-089533418697');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eca530cd-9be3-4778-97c9-73ee362e847e', 'They called his parents to complain', false, '0950aa40-8888-4edb-b913-089533418697');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2dc3986e-5b53-4770-b41f-6270b776bf77', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'Which of the following describes Patrick''s eyes on the morning after studying all night?', 'Working late hours with the elf left Patrick''s eyes visibly swollen (''puffed'') and exhausted (''bleary'').', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eeb22064-94c9-48b1-b2a7-47dd05374b95', 'Puffed and bleary', true, '2dc3986e-5b53-4770-b41f-6270b776bf77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('673e756f-19b7-42eb-8e74-70af4f471522', 'Bright and shining', false, '2dc3986e-5b53-4770-b41f-6270b776bf77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5df860f-c7c8-41ee-9304-285bb98f9773', 'Red with anger', false, '2dc3986e-5b53-4770-b41f-6270b776bf77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88abd7d1-72c5-45b6-9992-d6e4b51cb44c', 'Shut tight', false, '2dc3986e-5b53-4770-b41f-6270b776bf77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b15a3d3b-e9fe-4afb-8877-ffec7dbc0cc8', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What is the meaning of ''Glitch'' in the context of the elf''s homework trouble?', 'A glitch refers to a sudden malfunction, hindrance, or flaw that stops progress.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89ad5fcc-e79f-41b7-b03b-e404ff78b490', 'A problem or fault in an operation preventing smooth working', true, 'b15a3d3b-e9fe-4afb-8877-ffec7dbc0cc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3cceb87-2b24-4e9e-af4b-fbac9c7b191c', 'A magical spell', false, 'b15a3d3b-e9fe-4afb-8877-ffec7dbc0cc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e813e5bc-fe04-467b-aa95-513982e3ce0c', 'A musical instrument', false, 'b15a3d3b-e9fe-4afb-8877-ffec7dbc0cc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66e99803-600d-426d-a9c3-65ab77e3126c', 'A small animal', false, 'b15a3d3b-e9fe-4afb-8877-ffec7dbc0cc8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('28c4105e-364b-4233-a4c6-c7090d384f1d', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Medium', 'What did Patrick think his cat was playing with before discovering it was an elf?', 'Patrick mistook the minuscule man for a child''s toy doll when grabbing it from the cat.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b296ef13-05dc-4f00-9e3d-1bff2f8e4ba8', 'A little doll', true, '28c4105e-364b-4233-a4c6-c7090d384f1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8cf3299-b832-4147-b11d-b21b88cbf735', 'A feather', false, '28c4105e-364b-4233-a4c6-c7090d384f1d');
