INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eeba15a5-ef17-4ddb-8501-a36a2ba8647f', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Hard', 'What profound psychological technique did the elf unwittingly use on Patrick to make him study?', 'By constantly claiming ignorance, the elf compelled Patrick into active reading, calculation, and self-directed study.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06b06d16-6181-499e-acbf-707ad105ea25', 'Reverse scaffolding / forced active learning (acting helpless so Patrick took full ownership of the problem-solving)', true, 'eeba15a5-ef17-4ddb-8501-a36a2ba8647f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a4a47e1-7f73-4f11-82bc-3c3adfaa17f2', 'Hypnotic mind control', false, 'eeba15a5-ef17-4ddb-8501-a36a2ba8647f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9cc21e4-83ee-45ba-81b1-304232a90ff4', 'Threat of physical punishment', false, 'eeba15a5-ef17-4ddb-8501-a36a2ba8647f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b44db80-5c6c-4aa3-9543-b0e1cdcc2a89', 'Bribery with magical coins', false, 'eeba15a5-ef17-4ddb-8501-a36a2ba8647f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6671f54f-d099-4c9f-aa61-f8d97fb1fda5', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Hard', 'In ''A Tale of Two Birds'', the Rishi summarized the ultimate lesson of the story as:', 'The sage explains that association and environment define social temperament and speech habits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d41d8955-ca26-4527-9777-47cf9240013b', '"One is known by the company one keeps. That bird repeated the robbers'' talk, but this one repeats what he hears at the ashram."', true, '6671f54f-d099-4c9f-aa61-f8d97fb1fda5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31de70ca-7884-419a-a990-a42ac6d5d079', '"Never trust a wild bird in a storm."', false, '6671f54f-d099-4c9f-aa61-f8d97fb1fda5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21fd3eb9-74e1-4268-ab67-5b7fadf9e271', '"Kings must always hunt in thick forests."', false, '6671f54f-d099-4c9f-aa61-f8d97fb1fda5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87c8e3c9-f4c2-489a-abd0-07915323e102', '"All birds in a forest possess evil minds."', false, '6671f54f-d099-4c9f-aa61-f8d97fb1fda5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73ecfebb-39a7-4050-8aa6-623436820d9a', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Hard', 'Match the words from the story with their exact contextual meanings:
(a) Slyly      -> (i) Shrieked high-pitched
(b) Bleary     -> (ii) Secretly / cunningly
(c) Squeaked   -> (iii) Dim / dull from tiredness
(d) Semester   -> (iv) School academic term', 'Slyly = Secretly; Bleary = Dull from exhaustion; Squeaked = High-pitched cry; Semester = Academic period.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8189513-2e97-4a24-81f9-0ec09651b581', 'a-(ii), b-(iii), c-(i), d-(iv)', true, '73ecfebb-39a7-4050-8aa6-623436820d9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ca8200a-7a85-4fd5-aacc-f2f1073d1cd4', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '73ecfebb-39a7-4050-8aa6-623436820d9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b3bc63b-8227-4c9d-bd54-5326f35be92c', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '73ecfebb-39a7-4050-8aa6-623436820d9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9abfa1a4-26e6-4bde-a680-4b8853923710', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '73ecfebb-39a7-4050-8aa6-623436820d9a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2bc3dfb2-f60a-4cab-a16d-b8cbc35baef3', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Hard', 'Read the statements from ''A House, A Home'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1ec6915-8bdb-4dc5-a1ad-02a334f4db28', 'Statements 1 and 2 only', true, '2bc3dfb2-f60a-4cab-a16d-b8cbc35baef3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cf71a55-088f-46b6-8f6a-aaef260b67a3', 'Statements 2 and 3 only', false, '2bc3dfb2-f60a-4cab-a16d-b8cbc35baef3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a26fcba2-3ab5-44d1-a299-6b91239f9905', 'Statements 1 and 3 only', false, '2bc3dfb2-f60a-4cab-a16d-b8cbc35baef3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8560e97c-1985-4227-829e-d73092e5a28b', 'All Statements 1, 2, and 3', false, '2bc3dfb2-f60a-4cab-a16d-b8cbc35baef3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82884da5-36ae-4f37-8ba0-239c7f917fce', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Hard', 'Consider the elf''s physical reaction: ''He kicked his legs and doubled his fists and he grimaced and scowled and pursed his lips.'' What emotion is depicted?', 'The vivid bodily gestures (grimacing, scowling, kicking) express violent displeasure and resentment toward doing homework.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf90da84-fb12-4eea-b893-9c35d60fde33', 'Intense frustration and reluctance at being trapped into doing school homework', true, '82884da5-36ae-4f37-8ba0-239c7f917fce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f641558f-aec8-45ce-980a-d576695f2bdb', 'Joyful excitement at solving puzzles', false, '82884da5-36ae-4f37-8ba0-239c7f917fce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93ebb842-d3ba-441d-ad07-65b644079ebe', 'Deep peaceful sleep', false, '82884da5-36ae-4f37-8ba0-239c7f917fce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08bd492d-9f03-4dbd-852c-df57953504b9', 'Fear of the dark', false, '82884da5-36ae-4f37-8ba0-239c7f917fce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('197021bb-4c17-4d21-a122-aba8efd9c7b5', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Hard', 'Why did Patrick keep the truth a ''secret'' between himself and the reader at the end of the story?', 'Author Carol Moore writes: ''You think Patrick''s elf did his homework; but I''ll share a secret between you and me: Patrick had done it himself!''', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e756596-cc65-4b36-bf38-6563e94da1ab', 'Patrick still believed in his own heart that the tiny elf had performed the miracle', true, '197021bb-4c17-4d21-a122-aba8efd9c7b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e8d653e-d61d-4cce-966f-a7733f9d7c3a', 'He was ashamed of his ''A'' grade', false, '197021bb-4c17-4d21-a122-aba8efd9c7b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e997e74-6a8a-43a6-8122-471e6c018db8', 'His parents forbid him from talking', false, '197021bb-4c17-4d21-a122-aba8efd9c7b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e130b8a-b2bf-40ac-8381-3a74fbfdaf29', 'The teachers threatened him', false, '197021bb-4c17-4d21-a122-aba8efd9c7b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e065de1-57ed-46a0-8527-6983216a3610', 'Class 6', 'English', 'Chapter 1: Who Did Patrick''s Homework?', 'Hard', 'In ''A Tale of Two Birds'', how did the strong thunderstorm initially separate the mother bird and her two fledglings?', 'The storm''s violent winds blew the fledglings away, landing one near a robber''s cave and the other beside a peaceful hermitage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2db1ab11-e26e-41eb-869c-9c621604854f', 'A heavy branch struck the nest, killing the mother, while fierce gale winds blew the two young birds to opposite sides of the forest', true, '5e065de1-57ed-46a0-8527-6983216a3610');
