INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a75d98ab-9f51-4bb6-865c-dd12c13de3aa', 'Class 6', 'GK', 'Chapter 1: India - Our Country & Heritage', 'Hard', 'Why was 26th January chosen as the Republic Day of India?', 'The 1929 Lahore Congress resolved 26 January 1930 as Purna Swaraj Day; the Constitution was brought into effect on this historical date in 1950.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d100212c-8cb8-4434-bf65-f0cc160fd482', 'To commemorate the declaration of Purna Swaraj (Complete Independence) by the Indian National Congress on 26 January 1930', true, 'a75d98ab-9f51-4bb6-865c-dd12c13de3aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4357b77-c1d9-40ce-8026-cd6053607c82', 'It was the birthday of Mahatma Gandhi', false, 'a75d98ab-9f51-4bb6-865c-dd12c13de3aa');
