INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b033126-dd2d-4201-95f3-5122fa60dedf', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Easy', 'What is the unique spherical shape of planet Earth (slightly flattened at the poles and bulged at the equator) called?', '''Geoid'' literally means ''Earth-shaped'', describing an oblate spheroid flattened at poles due to axial rotation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f5ad60a-12db-460b-83c3-fe0ae7f64140', 'Geoid (Earth-like shape)', true, '4b033126-dd2d-4201-95f3-5122fa60dedf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa6cfcff-bd55-4f50-be6c-78772d8a4d38', 'Perfect Sphere', false, '4b033126-dd2d-4201-95f3-5122fa60dedf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ba1bc11-5bd3-4110-8e78-64ff9f170885', 'Cube', false, '4b033126-dd2d-4201-95f3-5122fa60dedf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('454a3b69-09e5-4562-996d-fdd723235aea', 'Oval', false, '4b033126-dd2d-4201-95f3-5122fa60dedf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53e31b4c-3815-415a-9079-b5a4c1f50a0b', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Easy', 'Why is planet Earth uniquely known as the ''Blue Planet'' when viewed from outer space?', 'Rayleigh scattering off expansive oceanic hydrosphere gives Earth its brilliant azure appearance from space.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b17209b8-c682-458b-8ba3-3087360f31cd', 'Two-thirds (around 71%) of its surface is covered by liquid water in oceans and seas', true, '53e31b4c-3815-415a-9079-b5a4c1f50a0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f46b882-6175-4976-8baf-513c5de1c1b8', 'Its atmosphere is made of blue smoke', false, '53e31b4c-3815-415a-9079-b5a4c1f50a0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71dd0931-83ec-4bd1-8fe1-6e5a25be4e13', 'Earth is covered with blue soil', false, '53e31b4c-3815-415a-9079-b5a4c1f50a0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69bce5d2-dfec-46d7-bfc1-a29a4381229b', 'Sunlight reflects blue from mountains', false, '53e31b4c-3815-415a-9079-b5a4c1f50a0b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad0283df-fac3-4428-8650-19d92497a132', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Easy', 'How long does the Moon take to complete one revolution around the Earth?', 'Synchronous tidal locking causes the Moon''s orbital period (~27.3 days) to match its axial rotation period.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a07fab0-dc75-4c81-967b-374a559faeed', 'About 27 days (and takes exactly the same time to complete one rotation on its axis)', true, 'ad0283df-fac3-4428-8650-19d92497a132');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccc68da6-d32a-486d-82be-6eb60c065915', '365 days', false, 'ad0283df-fac3-4428-8650-19d92497a132');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42c0c80f-ee26-408e-8afe-aed88268d3ba', '24 hours', false, 'ad0283df-fac3-4428-8650-19d92497a132');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19ed03c2-2130-4c8a-81c4-6ad910d65ae6', '30 days', false, 'ad0283df-fac3-4428-8650-19d92497a132');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87013aee-99fb-42d2-b6a3-d96df034bff3', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Easy', 'The tiny rocky celestial objects that revolve around the Sun primarily between the orbits of Mars and Jupiter are called:', 'The Main Asteroid Belt is a circumstellar disc located between the orbital paths of terrestrial Mars and gas giant Jupiter.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('076ed620-dd22-4d8e-9426-a3212144a93e', 'Asteroids', true, '87013aee-99fb-42d2-b6a3-d96df034bff3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e608c4cf-5f62-4578-99e8-da12c8caf09a', 'Meteoroids', false, '87013aee-99fb-42d2-b6a3-d96df034bff3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fc16fef-fdb5-4064-9269-61dc6705f145', 'Comets', false, '87013aee-99fb-42d2-b6a3-d96df034bff3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ae62e5c-0cd0-4bdd-be0d-c3c95c8f3a82', 'Dwarf Stars', false, '87013aee-99fb-42d2-b6a3-d96df034bff3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10a8c0fc-ffb8-4c67-ba03-083301aa141e', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Easy', 'Small chunks of rock and metallic debris that travel around the Sun and sometimes enter Earth''s atmosphere causing a streak of light are:', 'Frictional atmospheric compression heats falling meteoroids, creating incandescent trails (meteors / shooting stars).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fc50b65-819f-4e32-870f-9092ab2308cf', 'Meteoroids (Shooting stars)', true, '10a8c0fc-ffb8-4c67-ba03-083301aa141e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93658650-8f7e-4c8b-86da-c25b47cfe129', 'Asteroids', false, '10a8c0fc-ffb8-4c67-ba03-083301aa141e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec37193a-16e4-42c8-ad09-9fbc3142aa9c', 'Satellites', false, '10a8c0fc-ffb8-4c67-ba03-083301aa141e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de4629ae-6983-413e-9158-0895163e8afe', 'Constellations', false, '10a8c0fc-ffb8-4c67-ba03-083301aa141e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19248d1e-480b-4eaf-80d7-808fc4535d16', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Easy', 'What is our home spiral galaxy called, which appears as a faint glowing band of stars across the clear night sky?', 'Our solar system resides inside the Orion Arm of the Milky Way barred spiral galaxy, traditionally called Akash Ganga.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63d86a44-2d4b-4966-91b7-20f897a3268f', 'Milky Way Galaxy (Akash Ganga)', true, '19248d1e-480b-4eaf-80d7-808fc4535d16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a798981-63f6-4cc3-891c-fff25e707b29', 'Andromeda Galaxy', false, '19248d1e-480b-4eaf-80d7-808fc4535d16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b550dc5-e657-4a96-8073-62447fdef8e5', 'Triangulum', false, '19248d1e-480b-4eaf-80d7-808fc4535d16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b41987a6-931c-4732-b9f4-44732b682385', 'Whirlpool Galaxy', false, '19248d1e-480b-4eaf-80d7-808fc4535d16');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf5a8e44-62c6-4ce4-a92e-2f9145e42b11', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'Why do we always see only ONE side of the Moon from the Earth?', 'Gravitational tidal lock equalizes orbital revolution and axial spin, keeping the lunar near-side permanently facing Earth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa7b36c1-c625-47ea-8624-a49a046b444e', 'Because the Moon takes exactly the same time (~27 days) to complete one rotation on its axis as it takes to revolve once around the Earth (Synchronous Rotation)', true, 'cf5a8e44-62c6-4ce4-a92e-2f9145e42b11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f196c7a9-43e3-41ae-bd05-4105f4520984', 'The other side of the Moon is pitch dark without light', false, 'cf5a8e44-62c6-4ce4-a92e-2f9145e42b11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63a3d383-82e3-4105-8307-de67a91c1493', 'The Moon does not rotate at all', false, 'cf5a8e44-62c6-4ce4-a92e-2f9145e42b11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e43d3132-7ceb-4991-9ec7-a0a14cbfd754', 'Clouds block the other side', false, 'cf5a8e44-62c6-4ce4-a92e-2f9145e42b11');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c140f44-922d-4c72-bd97-b328e65a5a25', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'Why is Earth considered the only unique planet in the Solar System capable of supporting biological life?', 'Earth sits squarely inside the circumstellar Goldilocks Habitable Zone, sustaining liquid water and breathable N2-O2 atmosphere.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6114f412-31c2-4b41-b04a-a11c9692bb05', 'It has moderate temperature conditions, life-supporting oxygen gas in atmosphere, and abundant liquid water in hydrological cycles', true, '1c140f44-922d-4c72-bd97-b328e65a5a25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('025d681c-787c-40fe-b7ec-7f8a7a3fd1cb', 'It has zero gravity', false, '1c140f44-922d-4c72-bd97-b328e65a5a25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1105e9c2-a25c-41c9-8b90-636893c65086', 'It is the closest planet to the Sun', false, '1c140f44-922d-4c72-bd97-b328e65a5a25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0ff3f90-8778-420b-b3ec-39ec98326bed', 'It is made entirely of gold and diamonds', false, '1c140f44-922d-4c72-bd97-b328e65a5a25');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d432ef1-7749-4b76-b91e-f5a8ee61b941', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'How long does light from the Sun take to reach the surface of planet Earth?', 'At light speed c = 300,000 km/s across 150,000,000 km distance: time t = 150,000,000 ÷ 300,000 = 500 seconds = 8 min 20 sec.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95bc8f61-3820-49f4-b3e9-b4edeb2eb468', 'About 8 minutes and 20 seconds', true, '9d432ef1-7749-4b76-b91e-f5a8ee61b941');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4028827c-75ab-4fc5-8748-04f7212b1568', '1 minute', false, '9d432ef1-7749-4b76-b91e-f5a8ee61b941');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3019bed-8e45-48d8-a643-aad4245acdd6', '24 hours', false, '9d432ef1-7749-4b76-b91e-f5a8ee61b941');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('851c4cc5-2cde-4f45-862c-9d87932e07aa', 'Instantaneously in 1 second', false, '9d432ef1-7749-4b76-b91e-f5a8ee61b941');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4fd2bfa-9200-4095-aa94-2f437d5f133f', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'Who was the first human astronaut to step onto the surface of the Moon on 20 July 1969?', 'American Apollo 11 astronaut Neil Armstrong made historic first contact on the lunar Mare Tranquillitatis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eba50b85-641c-43e2-a753-b6b2c27eb048', 'Neil Armstrong', true, 'd4fd2bfa-9200-4095-aa94-2f437d5f133f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ab92d8c-abef-4625-9464-2d08f41bb454', 'Yuri Gagarin', false, 'd4fd2bfa-9200-4095-aa94-2f437d5f133f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55aacf13-1912-4be3-8371-3a9b17fd2bbd', 'Rakesh Sharma', false, 'd4fd2bfa-9200-4095-aa94-2f437d5f133f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('738158c5-09ab-4f05-8bc7-5dc80819066c', 'Buzz Aldrin', false, 'd4fd2bfa-9200-4095-aa94-2f437d5f133f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a5cc166-d068-4be9-8da2-e02202b8fbd8', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'What is a ''Human-made (Artificial) Satellite''?', 'Spacecraft like INSAT, IRS, and EDUSAT are engineered payloads injected into orbit for communications and remote sensing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a93f2c8-a406-4f5c-942f-4ff164c32863', 'An artificial body designed by scientists to gather information about the universe or for telecommunication, placed in Earth''s orbit by rockets', true, '9a5cc166-d068-4be9-8da2-e02202b8fbd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab5c3c7d-926a-4874-8c9e-789e0ae211d3', 'A natural rock orbiting Mars', false, '9a5cc166-d068-4be9-8da2-e02202b8fbd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e90eb23-a0b2-4651-8ac6-f80e886529dc', 'A telescope on a mountain', false, '9a5cc166-d068-4be9-8da2-e02202b8fbd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00b51466-538c-47a0-95ce-c416765f9c67', 'An aeroplane flying in clouds', false, '9a5cc166-d068-4be9-8da2-e02202b8fbd8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6205cd7-e697-4a81-8e2d-4faa1684fab0', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'Why was Pluto reclassified from a major planet to a ''Dwarf Planet'' by the International Astronomical Union (IAU) in August 2006?', 'IAU planetary criteria require a planet to: orbit the Sun, attain hydrostatic equilibrium, and have cleared its orbital neighborhood.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f57b697a-970e-4038-831e-e15f9223c482', 'Pluto failed to clear its orbital neighborhood of other icy trans-Neptunian Kuiper belt debris', true, 'd6205cd7-e697-4a81-8e2d-4faa1684fab0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7751d3b5-1207-4980-8615-d7343ca146b2', 'Pluto melted into water', false, 'd6205cd7-e697-4a81-8e2d-4faa1684fab0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b3c80d3-89b0-4daa-87ce-7d475b6fc7c1', 'Pluto collided with the Sun', false, 'd6205cd7-e697-4a81-8e2d-4faa1684fab0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fd62f06-7e95-4908-a030-b7750f51ce80', 'Pluto stopped revolving', false, 'd6205cd7-e697-4a81-8e2d-4faa1684fab0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d9f3b17-6daa-46a3-a369-4f6179667740', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'What are the four ''Inner Planets'' of the Solar System?', 'Inner planets are dense, rocky silicates situated inside the main asteroid belt, unlike outer gas/ice giants.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a9dbdf6-94c7-4d9f-a516-c7ca50d0ef90', 'Mercury, Venus, Earth, and Mars (terrestrial rocky planets close to the Sun)', true, '0d9f3b17-6daa-46a3-a369-4f6179667740');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('535ee8c6-fa97-483f-ae07-663f3fd5ffb1', 'Jupiter, Saturn, Uranus, and Neptune', false, '0d9f3b17-6daa-46a3-a369-4f6179667740');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('356dd976-3b9a-4929-93ea-7ad529598735', 'Earth, Moon, Sun, and Mars', false, '0d9f3b17-6daa-46a3-a369-4f6179667740');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81bda633-c2aa-4abf-b00e-a82441b9827e', 'Pluto, Ceres, Eris, and Haumea', false, '0d9f3b17-6daa-46a3-a369-4f6179667740');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('adce80c6-b817-4429-840d-06225c888aa4', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'Which outer planet in the Solar System possesses the most spectacular and prominent system of rings composed of ice and dust chunks?', 'Saturn''s extensive ring system spans up to 282,000 km, composed of reflective water-ice particles and rocky debris.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f31b447f-ab68-42fa-97f4-234c204189a6', 'Saturn', true, 'adce80c6-b817-4429-840d-06225c888aa4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aac29891-71a7-4640-bb96-7985e5e2f28a', 'Jupiter', false, 'adce80c6-b817-4429-840d-06225c888aa4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e5054e9-a23e-4d51-a6b5-d1b0253b0ce9', 'Neptune', false, 'adce80c6-b817-4429-840d-06225c888aa4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b990a580-955c-4033-b5f8-de2c741bb588', 'Mars', false, 'adce80c6-b817-4429-840d-06225c888aa4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ba74490-9b11-4acc-bcee-30380dd64b76', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'What is the famous seven-star constellation known as ''Saptarishi'' in Indian astronomy?', 'The Saptarishi asterism (Big Dipper) forms the prominent tail and body of the constellation Ursa Major.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60dfcf00-a1bc-47d5-8fe7-3efc65a31bcb', 'A group of seven prominent stars that forms part of the Ursa Major (Great Bear) constellation', true, '3ba74490-9b11-4acc-bcee-30380dd64b76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('192872f8-66dc-48f8-aefa-9c9df9fda536', 'A cluster of seven planets', false, '3ba74490-9b11-4acc-bcee-30380dd64b76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c2adde8-d03f-42f0-a71e-7d897fc44fa0', 'The seven moons of Jupiter', false, '3ba74490-9b11-4acc-bcee-30380dd64b76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52258cd0-75a6-4283-a955-c1fbc3d2ce2a', 'The Orion Hunter belt', false, '3ba74490-9b11-4acc-bcee-30380dd64b76');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('26b58d26-8266-4a3d-b8cf-ad09202506f3', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'How can one locate the position of the North Pole Star in the night sky using the Saptarishi constellation?', 'Extending the line connecting pointer stars Merak and Dubhe northward leads directly to Polaris.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0a058ad-0963-4d42-88d2-5a2766c5a064', 'By drawing an imaginary straight pointer line through the two forward pointer stars of Saptarishi and extending it northward', true, '26b58d26-8266-4a3d-b8cf-ad09202506f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f5fb1c5-ba5f-4580-8325-3987bc623dcf', 'By looking directly behind the Moon', false, '26b58d26-8266-4a3d-b8cf-ad09202506f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b81322a5-d9d0-4f9a-b280-9f7a81112f47', 'By pointing toward the southern horizon', false, '26b58d26-8266-4a3d-b8cf-ad09202506f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3243c9c1-584d-4ba0-9552-f606895a7171', 'By tracking the movement of Mars', false, '26b58d26-8266-4a3d-b8cf-ad09202506f3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('92714f6a-369c-47da-a2ad-eb51a025bc18', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'What happens when a large meteoroid does not burn up completely in Earth''s atmosphere and crashes onto the Earth''s surface?', 'Surviving solid fragments that strike planetary crust are termed meteorites, forming impact structures (e.g., Lonar Crater).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5311909-b087-4768-aad6-0185b1386c43', 'It is called a Meteorite and creates a hollow impact crater in the ground', true, '92714f6a-369c-47da-a2ad-eb51a025bc18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0696cbac-913a-43fd-8d24-a1dff07ee009', 'It turns into a new planet', false, '92714f6a-369c-47da-a2ad-eb51a025bc18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14cc1de1-30de-47d7-b702-80fd6140f6c2', 'It bounces back to outer space', false, '92714f6a-369c-47da-a2ad-eb51a025bc18');
