INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93bdfd76-7f34-4183-a891-372c6f170f7e', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'Which is the fastest planet to complete one revolution around the Sun (taking only 88 days)?', 'By Kepler''s Third Law, Mercury''s closest orbital proximity (57.9 million km) results in a brief 88-day sidereal year.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5eac6ec-26c1-4d33-bbd2-96505b5a3605', 'Mercury', true, '93bdfd76-7f34-4183-a891-372c6f170f7e');
