INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a3c81cd2-9fb9-49a5-81f4-e2eaedd17aa7', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'What is the primary source of all heat and light energy throughout our Solar System?', 'Thermonuclear fusion of hydrogen into helium in the Sun''s core generates the solar irradiance powering the entire system.', NOW()) ON CONFLICT DO NOTHING;
