INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d2f9d21-1324-4201-892c-a7ac40b822c7', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'What is a ''New Moon'' night known as in the Indian calendar?', 'During Amavasya (New Moon), the Moon sits between Earth and Sun, presenting its unilluminated shadowed face toward Earth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfe8127d-353c-49c0-8f01-04d439f7a74b', 'Amavasya (when the Moon is not visible at all)', true, '6d2f9d21-1324-4201-892c-a7ac40b822c7');
