INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f0bdd3f6-38c1-4582-9ac5-3e1485fa5e5a', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Medium', 'What is a ''Full Moon'' night known as in the Indian calendar?', 'Poornima occurs when Earth lies between Sun and Moon, allowing the full hemisphere of lunar reflection to be viewed.', NOW()) ON CONFLICT DO NOTHING;
