INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('29764fc2-b8bc-42c8-a033-862bab6b1a14', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'Arrange the planets in order of their increasing distance from the Sun:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7434514-ca25-44f5-a75d-2187220167a8', '2 -> 4 -> 3 -> 1 (Mercury -> Venus -> Earth -> Mars)', true, '29764fc2-b8bc-42c8-a033-862bab6b1a14');
