INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e42c2eeb-d4d3-4218-9516-6ecedcca2a18', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'What is the fundamental scientific difference between a Planet and a Star?', 'Self-luminous stars undergo stellar nucleosynthesis, whereas non-luminous planets shine solely via reflected starlight.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1bef5e8-85e4-42f9-9315-172fa46cb9b2', 'Stars generate their own heat and light through nuclear fusion; planets have no internal fusion and only reflect light from stars', true, 'e42c2eeb-d4d3-4218-9516-6ecedcca2a18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a127ec7-351d-48e6-b1f0-c8d5343d2525', 'Planets are always bigger than stars', false, 'e42c2eeb-d4d3-4218-9516-6ecedcca2a18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be6dedd6-992b-4f6e-835c-7ce6de6eb0ad', 'Stars revolve around planets', false, 'e42c2eeb-d4d3-4218-9516-6ecedcca2a18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d9c41b7-eabd-4ab5-8a89-a1f1d6b94de3', 'Stars are made of liquid water', false, 'e42c2eeb-d4d3-4218-9516-6ecedcca2a18');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('024bed3e-cc7d-4e7e-a27f-0073def1a893', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'Read the statements regarding the Solar System:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85d45e49-8799-4ae6-9075-fccecf7238ac', 'Statements 1 and 3 only', true, '024bed3e-cc7d-4e7e-a27f-0073def1a893');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c2e2969-03f7-4b25-966f-2b0b8b8f9d55', 'Statements 1 and 2 only', false, '024bed3e-cc7d-4e7e-a27f-0073def1a893');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('725a091c-0a9e-485a-a18a-f827eb05a21d', 'Statements 2 and 3 only', false, '024bed3e-cc7d-4e7e-a27f-0073def1a893');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3783e68d-c4fe-4917-89eb-b14c43069cd3', 'All Statements 1, 2, and 3', false, '024bed3e-cc7d-4e7e-a27f-0073def1a893');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9ce69f3-e84a-4c63-a0ce-1f00e2b25768', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'Match the celestial bodies with their distinctive characteristics:
(a) Venus     -> (i) Red Planet (iron oxide dust)
(b) Mars      -> (ii) Earth''s Twin
(c) Jupiter   -> (iii) Ringed Gas Giant
(d) Saturn    -> (iv) Largest planet in solar system', 'Venus = Earth''s Twin; Mars = Red planet; Jupiter = Largest planet; Saturn = Prominent ring system.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f42aa0ae-4aad-48cb-adf4-09bee7324325', 'a-(ii), b-(i), c-(iv), d-(iii)', true, 'e9ce69f3-e84a-4c63-a0ce-1f00e2b25768');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('670d100a-c842-4798-a397-de875540cb30', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'e9ce69f3-e84a-4c63-a0ce-1f00e2b25768');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7d29579-14ea-4744-b08e-eb9db024683a', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'e9ce69f3-e84a-4c63-a0ce-1f00e2b25768');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1d9475b-7cc0-47ad-b68d-fd88d0db263f', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'e9ce69f3-e84a-4c63-a0ce-1f00e2b25768');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1bbc7b5a-3f0c-4835-a292-cc0a25c7dba1', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'Why does the Moon have extreme surface temperatures (100°C+ during lunar day and -170°C at lunar night) with zero liquid water?', 'Lunar vacuum exosphere offers zero greenhouse buffering, subjecting the regolith to brutal unshielded solar irradiance and radiative cooling.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95cd58f3-c593-4861-9ea5-5c4290e2391b', 'The Moon lacks a protective blanket of atmosphere to trap or shield solar radiation and regulate heat', true, '1bbc7b5a-3f0c-4835-a292-cc0a25c7dba1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c7c5f41-8e33-4508-8f01-72e60749223b', 'The Moon is made of radioactive fire', false, '1bbc7b5a-3f0c-4835-a292-cc0a25c7dba1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49164703-8abc-4c8d-ab6e-f82f28403344', 'The Moon is too close to the Sun', false, '1bbc7b5a-3f0c-4835-a292-cc0a25c7dba1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('853edc36-422a-4a7a-a80c-02c063c46cca', 'The Moon is surrounded by ice clouds', false, '1bbc7b5a-3f0c-4835-a292-cc0a25c7dba1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2fdc56b8-4c0a-41cf-9dd6-890e4c8115af', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'Why is the word ''Planet'' derived from the ancient Greek word ''Planetai''?', 'Ancient astronomers tracked planets drifting apparent retrograde loops relative to background stellar coordinates, naming them wanderers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55182ee2-b4c8-4341-bbe9-28388496d558', 'Because ''Planetai'' means ''Wanderers'', describing how planets appeared to wander across fixed stellar constellations', true, '2fdc56b8-4c0a-41cf-9dd6-890e4c8115af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43177e27-319a-47a6-9caf-287571e556be', 'Because it means ''Giant Stone''', false, '2fdc56b8-4c0a-41cf-9dd6-890e4c8115af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1845ff79-c97f-4a51-9e84-b3be27aff6d0', 'Because it means ''Water Carrier''', false, '2fdc56b8-4c0a-41cf-9dd6-890e4c8115af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('584ea515-90ed-4cec-8745-fe2bc848f259', 'Because it means ''King of Sky''', false, '2fdc56b8-4c0a-41cf-9dd6-890e4c8115af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6bd457a8-9c9f-438a-a154-15aadc43283d', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'Consider four celestial objects:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcfe2f9f-442a-4a1a-ba89-2b1b89ce2e56', '1 only (Sirius)', true, '6bd457a8-9c9f-438a-a154-15aadc43283d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50af7de0-056f-46ea-8c0b-765dce799155', '2 and 3 only', false, '6bd457a8-9c9f-438a-a154-15aadc43283d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcb3b279-85f6-4c33-99cc-fcdbae68d5a0', '1 and 4 only', false, '6bd457a8-9c9f-438a-a154-15aadc43283d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ee92193-0434-4340-ae12-40eae2c897ab', 'All 1, 2, 3, and 4', false, '6bd457a8-9c9f-438a-a154-15aadc43283d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab848577-1385-4018-8014-36fa7e998d1f', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'What is the speed of light in vacuum, and how is it used to define astronomical distances (Light Years)?', 'Light speed c = 3 × 10⁸ m/s in vacuum; 1 light year = c × 31,557,600 s ≈ 9.46 × 10¹² km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec73c719-fb22-456a-b5a5-b581f8a038d1', '300,000 km per second (3 × 10⁸ m/s); a light year is the total distance light travels in one full year (~9.46 trillion km)', true, 'ab848577-1385-4018-8014-36fa7e998d1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f04377dd-47aa-4a4f-909a-df8ddfdf1be9', '1,000 km per hour', false, 'ab848577-1385-4018-8014-36fa7e998d1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cdcc10b-fc91-40a2-b1d7-abad3fb9a25d', '30,000 km per second', false, 'ab848577-1385-4018-8014-36fa7e998d1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22d0ca66-2628-4d55-a86d-0b25b58eb376', '150 million km per second', false, 'ab848577-1385-4018-8014-36fa7e998d1f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b6091606-61db-41c3-8a11-48dfe2e68561', 'Class 6', 'Social Science', 'Chapter 1: The Earth in the Solar System', 'Hard', 'Why do astronauts floating in the International Space Station or standing on the Moon see the outer space sky as pitch BLACK even in broad daylight?', 'Without air molecules to scatter blue optical wavelengths, the vacuum of space appears pitch black even when the Sun blazes brightly.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46a8b25f-ce69-4291-b9e1-c1faa2b41c38', 'There is no atmospheric medium in space to scatter incoming sunlight (Rayleigh scattering does not occur in vacuum)', true, 'b6091606-61db-41c3-8a11-48dfe2e68561');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de649558-9e87-4acb-86de-c1f4686b4ccd', 'The Sun is turned off in space', false, 'b6091606-61db-41c3-8a11-48dfe2e68561');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd4325be-5121-41a2-96ca-68b2b95a11e6', 'Space helmets have black glass', false, 'b6091606-61db-41c3-8a11-48dfe2e68561');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('377f91ef-078a-47aa-bde5-ccd586b53061', 'Earth blocks all light', false, 'b6091606-61db-41c3-8a11-48dfe2e68561');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67cc4855-8c6c-4732-aa84-3f5e0b0c7632', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'मनुष्य अपने भावों और विचारों को बोलकर या लिखकर दूसरों तक पहुँचाने के साधन को क्या कहते हैं?', 'भाषा वह सक्षम माध्यम है जिसके द्वारा मनुष्य अपने मनोभावों एवं विचारों का पारस्परिक आदान-प्रदान करता है।', NOW()) ON CONFLICT DO NOTHING;
