INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d9623b48-f6e1-4aff-acb8-58c35cb6e348', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'भाषा के मुख्य रूप से कितने भेद होते हैं?', 'भाषा के मुख्य दो रूप होते हैं: 1. मौखिक भाषा (बोलकर व्यक्त) तथा 2. लिखित भाषा (लिखकर व्यक्त)।', NOW()) ON CONFLICT DO NOTHING;
