INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7138032c-7ede-4c76-8647-75f3287836ce', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'टेलीफ़ोन पर बातचीत करना या रेडियो पर समाचार सुनना भाषा का कौन-सा रूप है?', 'ध्वनि उच्चारण द्वारा विचारों का श्रवण एवं संप्रेषण मौखिक भाषा के अंतर्गत आता है।', NOW()) ON CONFLICT DO NOTHING;
