INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34c039fb-a0aa-4ca9-b5e2-64d46e7cb55e', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'समाचार-पत्र पढ़ना या परीक्षा में उत्तर-पुस्तिका लिखना भाषा का कौन-सा रूप है?', 'लिपिबद्ध वर्णों के माध्यम से विचारों की अभिव्यक्ति एवं पठन लिखित भाषा कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
