INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f70c4161-1e4f-4d89-a3fa-7fd923a167d2', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'बच्चा अपने परिवार तथा माता-पिता से जो भाषा सर्वप्रथम सहज रूप से सीखता है, उसे क्या कहते हैं?', 'मातृभाषा वह स्वाभाविक भाषा है जिसे बालक अपने शैशवकाल में माता-पिता एवं घरेलू परिवेश से ग्रहण करता है।', NOW()) ON CONFLICT DO NOTHING;
