INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('478ef432-b446-4266-bbb8-3357a12e363f', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'किसी सीमित क्षेत्रीय भूभाग में जनसामान्य द्वारा बोली जाने वाली स्थानीय भाषा को क्या कहते हैं?', 'बोली (जैसे भोजपुरी, अवधी, हरियाणवी) किसी सीमित क्षेत्र में प्रयुक्त होने वाला मौखिक रूप है, जिसका अपना स्वतंत्र व्याकरण नहीं होता।', NOW()) ON CONFLICT DO NOTHING;
