INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1eedc7a1-7e1d-4f39-836c-f06c9c33c29b', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'व्याकरण के मुख्य रूप से कितने अंग / विभाग होते हैं?', 'व्याकरण के तीन मूलभूत अंग होते हैं: वर्ण-विचार (Phonology), शब्द-विचार (Morphology) तथा वाक्य-विचार (Syntax)।', NOW()) ON CONFLICT DO NOTHING;
