INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e7fe39fb-35b4-41f1-b571-531ca5c69ef1', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'किसी भाषा के ज्ञान के संचित एवं व्यवस्थित कोष को क्या कहा जाता है?', 'युगों-युगों से संचित ज्ञान, उत्कृष्ट विचारों तथा अनुभूतियों के लिखित संग्रह को ''साहित्य'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
