INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5ebcbb4a-848c-4c5a-8ade-51a2413ca43d', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'सरकारी कार्यालयों तथा प्रशासनिक राजकाज के कार्यों में प्रयुक्त होने वाली भाषा क्या कहलाती है?', 'राजभाषा वह संवैधानिक भाषा है जिसमें देश के शासकीय एवं कानूनी कार्य संपन्न किए जाते हैं।', NOW()) ON CONFLICT DO NOTHING;
