INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc5a7657-3630-47e1-b47b-fce7574bce4b', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'निम्नलिखित में से कौन-सा वाक्य व्याकरण की दृष्टि से पूर्णतः शुद्ध है?', 'सर्वनाम संबंधी अशुद्धि ''मेरे को'' के स्थान पर मानक रूप ''मुझे घर जाना है'' व्याकरणसम्मत शुद्ध प्रयोग है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91006fb6-1ddb-45f8-8157-5513585a3eda', 'मेरे को घर जाना है। -> अशुद्ध; ''मुझे घर जाना है।'' -> शुद्ध', true, 'fc5a7657-3630-47e1-b47b-fce7574bce4b');
