INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('42a1aa45-90b0-441d-8b25-513345a2b8d5', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'पद्य साहित्य के अंतर्गत निम्नलिखित में से कौन-सी विधा आती है?', 'लय, तुक, छंद तथा गेयता से युक्त भावात्मक रचनाएँ पद्य साहित्य कहलाती हैं।', NOW()) ON CONFLICT DO NOTHING;
