INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23e78107-810a-436b-8f07-c26b0f2c5fa7', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'ट्रैफ़िक पुलिस का सिपाही हाथ के इशारे से वाहनों को रुकने का संकेत देता है। यह किसका उदाहरण है?', 'संकेतों द्वारा भाव व्यक्त करना सांकेतिक संप्रेषण है; निश्चित नियम न होने से व्याकरण में इसका अध्ययन नहीं होता।', NOW()) ON CONFLICT DO NOTHING;
