INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f8801f85-3368-4c66-a01a-d585f3770b46', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'व्याकरण के किस अंग में वर्णों के आकार, उच्चारण, भेद तथा उनके मेल की संधि का अध्ययन किया जाता है?', 'वर्ण-विचार में स्वर, व्यंजन, उनके उच्चारण स्थान, मात्रा तथा वर्ण-संयोजन का विधिवत विवेचन होता है।', NOW()) ON CONFLICT DO NOTHING;
