INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e0a00f37-900e-41f5-85c9-724f930f5f46', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'व्याकरण के किस अंग में संज्ञा, सर्वनाम, विशेषण, क्रिया तथा शब्द रचना (उपसर्ग, प्रत्यय, समास) का अध्ययन किया जाता है?', 'शब्द-विचार में शब्दों के भेद, व्युत्पत्ति, रूपांतरण तथा अर्थ का विश्लेषणात्मक अध्ययन होता है।', NOW()) ON CONFLICT DO NOTHING;
