INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('747c0fbd-d319-4727-9e8b-e9feb66f3f66', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'व्याकरण के किस अंग में वाक्य की रचना, वाक्य के अंग (उद्देश्य और विधेय) तथा विराम-चिह्नों का अध्ययन किया जाता है?', 'वाक्य-विचार के अंतर्गत वाक्य के भेद, पदक्रम, अन्वय, रूपांतरण तथा विराम चिह्नों का अध्ययन किया जाता है।', NOW()) ON CONFLICT DO NOTHING;
