INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a351c4d2-22ff-4e76-bb46-6b78073c6809', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ade1237f-78eb-47b8-b6c6-4458e520c9a6', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'a351c4d2-22ff-4e76-bb46-6b78073c6809');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4e13f90-17bc-408a-910f-92551b9f05f8', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'a351c4d2-22ff-4e76-bb46-6b78073c6809');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b97402b-d919-416e-8f11-568ab0713fd6', '(A) सही है, परन्तु (R) गलत है।', false, 'a351c4d2-22ff-4e76-bb46-6b78073c6809');
