INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06bd05fb-a96a-4e1f-89be-8ee37c833bfb', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'भाषा और बोली में मूलभूत वैज्ञानिक अंतर क्या है?', 'भाषा विस्तृत भौगोलिक क्षेत्र में परिनिष्ठित व्याकरणसम्मत मानक रूप है, जबकि बोली अंचल विशेष की स्थानीय मौखिक अभिव्यक्ति है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15413311-3260-4ff9-9f00-677cc0fabc35', 'भाषा का क्षेत्र व्यापक होता है, उसका लिखित साहित्य और मानक व्याकरण होता है; जबकि बोली का क्षेत्र सीमित होता है और वह मुख्य रूप से मौखिक होती है', true, '06bd05fb-a96a-4e1f-89be-8ee37c833bfb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b60357c-7c7b-402b-a5dd-e9580c3887a8', 'बोली केवल विदेशों में बोली जाती है', false, '06bd05fb-a96a-4e1f-89be-8ee37c833bfb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2e63c07-3086-47aa-995c-191fefaaf05a', 'भाषा में वर्ण नहीं होते', false, '06bd05fb-a96a-4e1f-89be-8ee37c833bfb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5eab376c-e6b4-45d8-aa98-b471486597e7', 'बोली का व्याकरण बहुत कठिन होता है', false, '06bd05fb-a96a-4e1f-89be-8ee37c833bfb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba9ff430-7705-4cf4-88df-3a898ddf3dc7', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'सुमेलित कीजिए (Match the Columns):
(क) कबीर के दोहे      -> (i) देवनागरी लिपि
(ख) मुंशी प्रेमचंद के उपन्यास -> (ii) पद्य साहित्य
(ग) हिंदी की लिपि     -> (iii) 14 सितंबर 1949
(घ) हिंदी को राजभाषा  -> (iv) गद्य साहित्य', 'कबीर के दोहे = पद्य; प्रेमचंद के उपन्यास = गद्य; हिंदी लिपि = देवनागरी; राजभाषा स्वीकृति = 14 सितंबर 1949।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b276d28-6d97-476b-b225-3be56802c6f4', 'क-(ii), ख-(iv), ग-(i), घ-(iii)', true, 'ba9ff430-7705-4cf4-88df-3a898ddf3dc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f149099-46b7-4672-8aa8-b8e04ac7c309', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, 'ba9ff430-7705-4cf4-88df-3a898ddf3dc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb67056d-ce2b-470e-b110-fdabb90e9058', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, 'ba9ff430-7705-4cf4-88df-3a898ddf3dc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f77a203-5add-4840-93cc-d1be25c65f1d', 'क-(iii), ख-(i), ग-(iv), घ-(ii)', false, 'ba9ff430-7705-4cf4-88df-3a898ddf3dc7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd736fee-50a9-438b-8554-ba1f681cd72d', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'निम्नलिखित कथनों पर विचार कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e187ae28-85a2-4179-85f3-df21ca7d3ed6', 'कथन 1 और 2 केवल', true, 'fd736fee-50a9-438b-8554-ba1f681cd72d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('886bafe4-1a3e-4884-a065-40cd9592193d', 'कथन 2 और 3 केवल', false, 'fd736fee-50a9-438b-8554-ba1f681cd72d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5247e91e-3f67-4674-a349-fafbb4f8dd33', 'कथन 1 और 3 केवल', false, 'fd736fee-50a9-438b-8554-ba1f681cd72d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecdc34fa-80d2-4430-80c7-50661cbb4a18', 'सभी कथन 1, 2 और 3', false, 'fd736fee-50a9-438b-8554-ba1f681cd72d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ba5925e-4371-4093-8ca7-00414731fb6a', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'निम्नलिखित वाक्यों में से पदक्रम और कारक की दृष्टि से शुद्ध वाक्य का चयन कीजिए:', 'तीनों वाक्यों में विशेषण एवं क्रिया का पदक्रम दोषपूर्ण था; तीनों का शुद्ध रूप पदक्रम सुधारने से ही बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bd0f8fd-cd54-44fe-873e-3502030cfe25', 'खरगोश को काटकर गाजर खिलाओ। -> अशुद्ध; ''गाजर काटकर खरगोश को खिलाओ।'' -> शुद्ध पदक्रम', false, '8ba5925e-4371-4093-8ca7-00414731fb6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d5385b0-6a65-4f9f-892d-eae28f6f95ed', 'बच्चे को प्लेट में रखकर खाना दो। -> अशुद्ध; ''प्लेट में रखकर बच्चे को खाना दो।'' -> शुद्ध', false, '8ba5925e-4371-4093-8ca7-00414731fb6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9a89369-a2dc-4ce9-8ac9-9a85cb8890ed', 'यहाँ ताज़ा गाय का दूध मिलता है। -> अशुद्ध; ''यहाँ गाय का ताज़ा दूध मिलता है।'' -> शुद्ध', false, '8ba5925e-4371-4093-8ca7-00414731fb6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b71d748-2bb9-415b-8981-e2503936ffb9', 'उपर्युक्त सभी विकल्पों में शुद्धिकरण की आवश्यकता है।', true, '8ba5925e-4371-4093-8ca7-00414731fb6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59512d16-bfbb-442e-a84f-a613e3332e27', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'प्राचीन भारत की अधिकांश आधुनिक लिपियों (जैसे देवनागरी, बांग्ला, गुजराती) की जननी किस ऐतिहासिक लिपि को माना जाता है?', 'सम्राट अशोक के शिलालेखों में प्रयुक्त ''ब्राह्मी लिपि'' से ही कालांतर में गुप्त लिपि और तत्पश्चात् देवनागरी का विकास हुआ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cff377d0-75ee-47e5-8d47-9ed70a68bb48', 'ब्राह्मी लिपि (Brahmi Script)', true, '59512d16-bfbb-442e-a84f-a613e3332e27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ae61d2b-9582-453b-88a4-dd64e16b3050', 'खरोष्ठी लिपि', false, '59512d16-bfbb-442e-a84f-a613e3332e27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c34012ac-145f-4c3c-b386-250e8ddde56e', 'सिंधु घाटी लिपि', false, '59512d16-bfbb-442e-a84f-a613e3332e27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ded40555-15be-4aa5-b0d8-7ee2875d9020', 'आरामाइक लिपि', false, '59512d16-bfbb-442e-a84f-a613e3332e27');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c0a1c66-5c8b-4405-9061-a3dbafcbe45c', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'यदि किसी व्यक्ति को भाषा का व्याकरण ज्ञात न हो, तो उसके संप्रेषण में क्या प्रमुख दोष उत्पन्न होगा?', 'व्याकरणहीन भाषा में अन्वय और पदक्रम का नियमन न होने से संप्रेषण में गंभीर अर्थभ्रम पैदा होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eed04448-09e3-4672-988c-9f012dd0c87e', 'लिंग, वचन, कारक, काल तथा पदक्रम की अशुद्धियों के कारण अर्थ का अनर्थ हो सकता है', true, '9c0a1c66-5c8b-4405-9061-a3dbafcbe45c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('213dcd3e-70fc-4ad4-9c16-a0c261391d80', 'व्यक्ति कभी बोल नहीं पाएगा', false, '9c0a1c66-5c8b-4405-9061-a3dbafcbe45c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d394976-27cc-4eb8-8329-97947592f826', 'व्यक्ति की आवाज़ बदल जाएगी', false, '9c0a1c66-5c8b-4405-9061-a3dbafcbe45c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a914ceb-becd-4e40-9194-c5239de82f89', 'लिपि नष्ट हो जाएगी', false, '9c0a1c66-5c8b-4405-9061-a3dbafcbe45c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('104728ad-bf4a-4522-bad9-11b5cfc57752', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'निम्नलिखित 4 भाषाओं में से कौन-सी भाषा भारतीय संविधान की 8वीं अनुसूची में सम्मिलित 22 भाषाओं में शामिल नहीं है?', 'मैथिली, डोगरी, बोडो और संथाली 92वें संविधान संशोधन (2003) द्वारा 8वीं अनुसूची में शामिल हैं, जबकि भोजपुरी अभी तक शामिल नहीं है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a13b201-961c-4fb6-a486-e6b01d1cd7c3', 'भोजपुरी (Bhojpuri - बोली स्तर)', true, '104728ad-bf4a-4522-bad9-11b5cfc57752');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29e69edf-c140-4a63-bc04-2ad5c4bbe995', 'मैथिली', false, '104728ad-bf4a-4522-bad9-11b5cfc57752');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0facabcc-24d9-4811-a414-8bd02a4bd826', 'डोगरी', false, '104728ad-bf4a-4522-bad9-11b5cfc57752');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bf476da-d224-4ebd-af51-f768233aaf57', 'संथाली', false, '104728ad-bf4a-4522-bad9-11b5cfc57752');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('257c5021-4c49-4e22-978a-7310a3c55872', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'किसी भी भाषा के मानक (Standard) रूप का क्या महत्व होता है?', 'मानक भाषा क्षेत्रीय भिन्नताओं से परे एक सर्वस्वीकृत, व्याकरणसम्मत तथा प्रामाणिक रूप प्रस्तुत करती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fb31cb6-6153-4679-b923-32e883e41e7e', 'मानक रूप पूरे देश में शिक्षा, शासन, न्यायालय तथा जनसंचार में एकरूपता और स्पष्टता बनाए रखता है', true, '257c5021-4c49-4e22-978a-7310a3c55872');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a25c9cc0-b248-4dc1-8baf-bc0bec1db026', 'मानक रूप भाषा को केवल कुछ लोगों तक सीमित करता है', false, '257c5021-4c49-4e22-978a-7310a3c55872');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7a9cf1a-e9c0-462d-bffb-726ea909954d', 'मानक रूप से भाषा कठिन हो जाती है', false, '257c5021-4c49-4e22-978a-7310a3c55872');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81281110-080c-4360-b2fc-2472ba571e70', 'मानक रूप केवल प्राचीन काल में प्रयुक्त होता था', false, '257c5021-4c49-4e22-978a-7310a3c55872');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e367ff0a-030e-445b-af58-b1faa549652c', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'वाक्य के दो अनिवार्य घटक (अंग) कौन-से होते हैं?', 'प्रत्येक वाक्य में जिसके विषय में कुछ कहा जाए वह ''उद्देश्य'' तथा उद्देश्य के बारे में जो कहा जाए वह ''विधेय'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8bbf5c2-251e-42ae-b8fb-75979dccf488', 'उद्देश्य (Subject) और विधेय (Predicate)', true, 'e367ff0a-030e-445b-af58-b1faa549652c');
