INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38c3c30b-477a-4200-9e5e-4805584c1c17', 'गद्य और पद्य', false, 'e367ff0a-030e-445b-af58-b1faa549652c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afea29c1-9bba-4ac9-bd9d-2515ef7e7128', 'उपसर्ग और प्रत्यय', false, 'e367ff0a-030e-445b-af58-b1faa549652c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d028a7b1-af52-4a7e-bd35-a7841da087f8', 'Class 6', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'देवनागरी लिपि की सर्वप्रमुख वैज्ञानिक विशेषता क्या है?', 'देवनागरी में 1-to-1 ध्वनि-वर्ण सामंजस्य है; इसमें रोमन लिपि की भाँति अनिश्चित मूक (silent) अक्षरों का भ्रम नहीं होता।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('840b4254-586c-45c1-a3d6-5967b167e768', 'यह एक अक्षरात्मक (Syllabic) एवं ध्वन्यात्मक लिपि है जिसमें प्रत्येक उच्चरित ध्वनि के लिए एक विशिष्ट और निश्चित वर्ण चिह्न होता है', true, 'd028a7b1-af52-4a7e-bd35-a7841da087f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fbc7aa6-30be-4317-81fb-c1b2d86764a0', 'इसमें साइलेंट लेटर्स बहुत अधिक होते हैं', false, 'd028a7b1-af52-4a7e-bd35-a7841da087f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('219aa14f-6799-4734-afa7-2b23ba49b1a0', 'यह केवल दाएँ से बाएँ लिखी जाती है', false, 'd028a7b1-af52-4a7e-bd35-a7841da087f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bed90d8-85ea-4406-a39a-e8dd2650186b', 'इसमें केवल 10 वर्ण होते हैं', false, 'd028a7b1-af52-4a7e-bd35-a7841da087f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1fd4c973-62ab-41c3-8ae2-f4f74b3a64ed', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Easy', 'Materials through which things can be seen clearly are called:', 'Transparent materials (like clear glass, water, and clean air) transmit almost all incident light without scattering.', NOW()) ON CONFLICT DO NOTHING;
