INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('816bf85f-7219-4845-85ae-648b10cf9ee2', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Easy', 'Which of the following substances is completely INSOLUBLE in water?', 'Insoluble wood sawdust does not dissolve and remains suspended or floats on the surface of water.', NOW()) ON CONFLICT DO NOTHING;
