INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf6483eb-16f6-4059-8613-00703574f23c', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Easy', 'Which of the following objects will SINK in water?', 'Dense metals like iron have a specific gravity greater than 1, causing them to sink immediately.', NOW()) ON CONFLICT DO NOTHING;
