INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('995ed448-6f0a-4584-af1e-5c4219706405', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Easy', 'Why are cooking utensils (pans, kettles) made of metals while their handles are made of plastic or wood?', 'Metals efficiently conduct thermal energy for cooking; plastic/wood handles insulate hands from heat.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac2686b4-4135-4086-81b7-51119d4a65f5', 'Metals are good conductors of heat, while plastic and wood are insulators that do not burn our hands', true, '995ed448-6f0a-4584-af1e-5c4219706405');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('607dcd83-cf9f-4dba-80d7-9eeeae5791b1', 'Metals are transparent', false, '995ed448-6f0a-4584-af1e-5c4219706405');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f69630a9-ac23-46d2-b995-38d75d05688c', 'Wood melts faster than metal', false, '995ed448-6f0a-4584-af1e-5c4219706405');
