INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d5a6f6e8-bcb7-46f8-92a0-54d3a2c5c4f6', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Easy', 'Which of the following is a natural, organic material?', 'Cotton is a natural plant cellulose fiber harvested from the seed bolls of the Gossypium plant.', NOW()) ON CONFLICT DO NOTHING;
