INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f44278cd-2438-425c-bcd4-44cd8a095cfc', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Easy', 'Which liquid completely mixes (is miscible) with water?', 'Vinegar (aqueous acetic acid) is polar and forms a single homogenous miscible phase with water.', NOW()) ON CONFLICT DO NOTHING;
