INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1df82842-e59e-4e16-9e54-fcc5c9c57a08', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Easy', 'Why do shopkeepers usually prefer to keep sweets, biscuits, and toffees in transparent glass or plastic jars?', 'Optical transparency enables effortless visual inspection and attractive merchandising without opening containers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('746268aa-0f77-47fb-8671-33d0aa57c04e', 'So that buyers can easily see and identify the items without opening the containers', true, '1df82842-e59e-4e16-9e54-fcc5c9c57a08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09d65c9f-bfc3-4cab-88ce-25fe1df5ba56', 'To protect items from getting heavy', false, '1df82842-e59e-4e16-9e54-fcc5c9c57a08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d13d065-4d54-4c52-8b20-eea5e21c98e7', 'Because glass is the cheapest material', false, '1df82842-e59e-4e16-9e54-fcc5c9c57a08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bdfe2e2-2de9-45fd-b859-1209f215f0e9', 'Because glass absorbs all sugar', false, '1df82842-e59e-4e16-9e54-fcc5c9c57a08');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e0a5c79-27ed-4d75-9d58-6702e6ed17a5', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Why do shiny iron rods or copper vessels lose their metallic lustre and appear dull and tarnished over time?', 'Surface oxidation and corrosion from ambient humidity and air form dull passivation films, masking intrinsic lustre.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a14dfd3-82ea-4e40-b75f-942c5485fad2', 'They react chemically with moisture and atmospheric gases (oxygen) to form a thin surface oxide layer', true, '9e0a5c79-27ed-4d75-9d58-6702e6ed17a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4081b092-4e87-4c39-b8f6-c08ae44a5e6f', 'Light stops shining on old metals', false, '9e0a5c79-27ed-4d75-9d58-6702e6ed17a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99dcf95a-5137-4e79-928a-c33036240a4e', 'The atoms inside metals disappear', false, '9e0a5c79-27ed-4d75-9d58-6702e6ed17a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('504dfa92-1061-436b-8bf7-f34b08dc5d0c', 'Metals turn into wood', false, '9e0a5c79-27ed-4d75-9d58-6702e6ed17a5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4ef777d-c2ea-49bd-82f7-49f09ff83b93', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'What happens when mustard oil or cooking oil is vigorously stirred into a glass of water?', 'Non-polar lipids are hydrophobic (immiscible) and have lower density (~0.92 g/cm³), floating atop water.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c785e57-749b-435e-9f52-20cab01371ac', 'It forms a separate upper layer because oil is immiscible in water and less dense than water', true, 'e4ef777d-c2ea-49bd-82f7-49f09ff83b93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d9367df-ffab-499a-938c-8031a3d46adf', 'It dissolves completely to form a transparent solution', false, 'e4ef777d-c2ea-49bd-82f7-49f09ff83b93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('958f3b63-0910-4bf5-ab11-a2993b55f8c8', 'It turns into hard plastic', false, 'e4ef777d-c2ea-49bd-82f7-49f09ff83b93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b06d1be2-3de3-4dd2-afee-a8be26706a2c', 'It sinks to the bottom as heavy mud', false, 'e4ef777d-c2ea-49bd-82f7-49f09ff83b93');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d276fb89-c6ae-46a2-b074-f402f0311e4d', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Why is a tumbler / drinking cup NEVER made out of a piece of cloth?', 'Woven textiles possess microscopic permeable pores between yarn threads through which liquids immediately leak.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('462ace7d-77b9-4c5f-ac44-fbd5fd62626f', 'Cloth is porous with spaces between interwoven threads and cannot hold or retain liquid water', true, 'd276fb89-c6ae-46a2-b074-f402f0311e4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48d92808-0960-4010-869b-9f55677dd062', 'Cloth is too heavy to lift', false, 'd276fb89-c6ae-46a2-b074-f402f0311e4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2231e2a3-1af2-4c06-ab65-b4d505ca9cc1', 'Cloth turns water into acid', false, 'd276fb89-c6ae-46a2-b074-f402f0311e4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc7b0909-614c-4419-8e6b-2440566a7f14', 'Cloth is transparent', false, 'd276fb89-c6ae-46a2-b074-f402f0311e4d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('861c5bad-c9bc-47dc-a786-a27f19b05fdc', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Why is sorting materials into groups (Classification) scientifically useful in everyday life?', 'Taxonomic categorization organizes entities by shared physical/chemical traits, optimizing identification and retrieval.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b820ace6-6d88-4f89-b8fa-3fe2fd46a433', 'It allows systematic study of material properties, saves time in locating objects, and aids structured analysis', true, '861c5bad-c9bc-47dc-a786-a27f19b05fdc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('126eda45-a4cc-400c-bf2c-ce00fcf84cbb', 'It makes all objects colorful', false, '861c5bad-c9bc-47dc-a786-a27f19b05fdc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fb41cb3-148a-408a-924b-01ef6d4d1eb9', 'It eliminates the need for cleaning', false, '861c5bad-c9bc-47dc-a786-a27f19b05fdc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0c1782a-3083-4211-a2b7-8f771486a9f8', 'It prevents objects from breaking', false, '861c5bad-c9bc-47dc-a786-a27f19b05fdc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0bea6756-48ee-47cd-9eda-e9a73a9508e8', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Which of the following gases is dissolved in natural water bodies, enabling aquatic animals and fish to breathe?', 'Oxygen partially dissolves in water (~7-10 mg/L), which fish extract across gill membranes for aerobic respiration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54bcdcaf-f6f8-458d-8de8-e5a436fe3c70', 'Dissolved Oxygen (O₂)', true, '0bea6756-48ee-47cd-9eda-e9a73a9508e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6637e508-a248-493e-b249-38330e32f14f', 'Nitrogen gas', false, '0bea6756-48ee-47cd-9eda-e9a73a9508e8');
