INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14bf080d-0282-4e05-b864-753c78671f2f', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'A material which can be easily compressed, scratched, or bent with fingers is classified as:', 'Materials with low structural indentation resistance and deformability are defined as soft materials.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb2ac9a7-3699-499e-b076-25d5f7980f45', 'Soft material (e.g., sponge, cotton)', true, '14bf080d-0282-4e05-b864-753c78671f2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60590ca3-5689-4afe-b8ca-5f63226d953b', 'Hard material', false, '14bf080d-0282-4e05-b864-753c78671f2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3defb698-9d28-4a34-b12b-efde2bafa6c1', 'Lustrous metal', false, '14bf080d-0282-4e05-b864-753c78671f2f');
