INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1be201a0-9f0a-4edc-9feb-cb06999382f9', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'A material which is difficult to compress, scratch, or deform is classified as:', 'Hardness is the measure of resistance to localized surface plastic deformation, scratching, or abrasion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02121efc-de21-4e95-a39f-1c453fdd0182', 'Hard material (e.g., iron, stone, diamond)', true, '1be201a0-9f0a-4edc-9feb-cb06999382f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8283c2a-de1d-4584-bc11-33411770e4d8', 'Soft material', false, '1be201a0-9f0a-4edc-9feb-cb06999382f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a3b294e-5006-4b56-bab1-8f97f4776b02', 'Translucent material', false, '1be201a0-9f0a-4edc-9feb-cb06999382f9');
