INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('151ca808-0366-4b47-abc9-9895cd4d7d4d', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Which pair of materials can be used to make a single everyday object like a chair?', 'The same functional object (chair) can be manufactured from various solid structural materials (timber, polymer, metal).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c672d3a-26f3-4f48-8426-7916aa45c028', 'Wood, Plastic, or Iron', true, '151ca808-0366-4b47-abc9-9895cd4d7d4d');
