INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed73a774-6464-472d-8927-2e52e85629cc', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'What happens when a drop of oil falls on a clean sheet of white writing paper?', 'Oil fills the air voids between cellulose fibers, matching refractive indices and rendering the paper translucent.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5a815ff-3e73-4b7f-b90e-aa982274f021', 'The paper becomes translucent at that spot, allowing light to pass through diffusely', true, 'ed73a774-6464-472d-8927-2e52e85629cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9d9f9e1-7451-40f0-8617-22c3c3931ed3', 'The paper catches fire instantly', false, 'ed73a774-6464-472d-8927-2e52e85629cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99efa39b-bf35-4443-82ec-8317ba301d1e', 'The paper becomes 100% transparent like clear glass', false, 'ed73a774-6464-472d-8927-2e52e85629cc');
