INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9b757d6-383f-4566-bbe4-a6190fbc8dfb', 'Aluminium wire and Gold ring', true, '1a1da0a5-7360-4677-832a-a6862cf66bbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bec14ae-c6a7-4c62-82e2-87db48a06d09', 'Cardboard and Wooden block', false, '1a1da0a5-7360-4677-832a-a6862cf66bbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ce65335-10c1-4616-a8c1-775dcc92a0a9', 'Chalk stick and Plastic toy', false, '1a1da0a5-7360-4677-832a-a6862cf66bbb');
