INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b773bd0d-3904-445e-8fa4-86193b51329f', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Why do coins and iron nails sink in water whereas a large wooden log of greater mass floats?', 'Flotation depends on relative density (mass per unit volume), not on total absolute mass.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4f64294-0bda-4d69-9bf3-25dfe926d780', 'Density of iron is greater than water, while overall density of wood is lower than that of water', true, 'b773bd0d-3904-445e-8fa4-86193b51329f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a46c2c4b-f56b-4b30-a8ce-3a18c1636ad1', 'Iron is magnetic and pulled by Earth', false, 'b773bd0d-3904-445e-8fa4-86193b51329f');
