INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1cb99a9d-8b20-4e63-a390-d8ed106ba00e', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Which of the following is a man-made (synthetic) material?', 'Polyethylene is a synthetic petrochemical polymer produced via artificial chemical polymerization.', NOW()) ON CONFLICT DO NOTHING;
