INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f396ac44-6db9-4775-b97e-8b0fd3c46bbf', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Which of the following liquids is IMMISCIBLE with water?', 'Lipids (coconut oil) do not mix with polar water molecules and form a separate distinct meniscus layer.', NOW()) ON CONFLICT DO NOTHING;
