INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad14ddc8-5d2a-48f1-b3c9-630d4b83c351', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Medium', 'Why are windows in bathrooms often fitted with frosted (ground) glass instead of clear transparent glass?', 'Diffused surface textures scatter transmitted light rays, ensuring illumination while maintaining visual privacy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da28e03b-cdbb-4b48-baf4-32d1d42935c6', 'Frosted glass is translucent, allowing sunlight to enter while obscuring clear vision for privacy', true, 'ad14ddc8-5d2a-48f1-b3c9-630d4b83c351');
