INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93da278a-9e78-4474-ad49-324d8c8de0e4', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Hard', 'Why does a hollow plastic toy boat weighing 500 grams float on water, while a solid lead pellet weighing only 5 grams sinks immediately?', 'Archimedes'' principle: hollow geometry displaces volume with low mean density (mass/volume < 1 g/cm³), enabling flotation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f011eb06-7e7b-4c82-8cfa-2e0638a19803', 'The boat encloses a large volume of air, making its overall average density much less than water, while dense lead has higher density than water', true, '93da278a-9e78-4474-ad49-324d8c8de0e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5245e8dc-fcd3-4cec-83b2-2e3919147c9b', 'Lead is poisonous to water', false, '93da278a-9e78-4474-ad49-324d8c8de0e4');
