INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('821404da-c1dd-4317-a9c8-889a5d89f062', 'Class 6', 'Science', 'Chapter 2: Sorting Materials into Groups', 'Hard', 'Why is sorting waste into Biodegradable (green bin) and Non-Biodegradable (blue bin) materials recommended at municipal levels?', 'Source segregation isolates organic matter for aerobic composting while diverting recyclable synthetic polymers and metals from landfills.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a748c82b-a0ca-4f7e-99b0-e3edc53516e4', 'It allows organic waste to be composted into soil manure and non-biodegradable plastics/metals to be recycled efficiently', true, '821404da-c1dd-4317-a9c8-889a5d89f062');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2807e279-b917-4788-9c1e-98568b858a2f', 'To make waste colorful', false, '821404da-c1dd-4317-a9c8-889a5d89f062');
