INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6d567ae-ca97-4f69-813c-16bff8fdfbdc', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Easy', 'What is the smallest natural number?', 'Natural numbers (counting numbers) start from 1, 2, 3, 4... Hence, 1 is the smallest natural number.', NOW()) ON CONFLICT DO NOTHING;
