INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19f7024c-b713-4cf3-bcb7-f4bcb3b96a3d', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Easy', 'What is the smallest whole number?', 'Whole numbers include 0 along with all natural numbers (0, 1, 2, 3...). 0 is the smallest whole number.', NOW()) ON CONFLICT DO NOTHING;
