INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7221827-f404-411d-9aa4-146a8321fb27', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Easy', 'What is the predecessor of the whole number 1?', 'Predecessor of 1 in the whole number system is 1 - 1 = 0.', NOW()) ON CONFLICT DO NOTHING;
