INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e181926c-173a-4b93-b3cb-00f19cb81f47', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'Which property is demonstrated by: (a × b) × c = a × (b × c)?', 'Regrouping factors does not change the final product (Associative Property).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6947d6ff-80d7-4c11-ba55-b512b8a9c88a', 'Associative property of multiplication', true, 'e181926c-173a-4b93-b3cb-00f19cb81f47');
