INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('313c45a7-5db9-431a-8a86-269ebfdcfa85', 'Distributive property', false, 'e181926c-173a-4b93-b3cb-00f19cb81f47');
