INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa8b7123-314b-4c3e-8d05-bc9aa0595fc1', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'Which of the following whole numbers can be arranged as a square pattern using dots?', 'Square numbers n² (2²=4, 3²=9, 4²=16, 5²=25) form symmetrical square dot lattices.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d91e17f-b2c5-4ea6-a950-08963515fbfe', '4, 9, 16, 25', true, 'fa8b7123-314b-4c3e-8d05-bc9aa0595fc1');
