INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6a1cbf90-e9db-424a-87dd-e486c44d41b7', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'Which of the following whole numbers can be arranged as a triangular pattern using dots?', 'Triangular numbers T_n = n(n+1)/2 (T₂=3, T₃=6, T₄=10, T₅=15) form equilateral triangular dot grids.', NOW()) ON CONFLICT DO NOTHING;
