INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7c3cb123-a104-4d77-9b2e-791d667ad915', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'Find the product: 4 × 166 × 25', '(4 × 25) × 166 = 100 × 166 = 16,600.', NOW()) ON CONFLICT DO NOTHING;
