INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94bd63a3-018f-4183-938d-5eb77ca0d32a', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'Solve using suitable properties: 854 × 102', '854 × (100 + 2) = 85,400 + 1,708 = 87,108.', NOW()) ON CONFLICT DO NOTHING;
