INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62401221-672c-4bfb-8bc5-3fc4eb1823fe', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'If the product of two whole numbers is zero, what can we definitively conclude?', 'By the Zero Product Property: if a × b = 0, then a = 0, or b = 0, or a = b = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2c57f78-cae5-4351-b151-8f5d7a4d0afd', 'At least one of the numbers (or both) must be zero', true, '62401221-672c-4bfb-8bc5-3fc4eb1823fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3389c590-ee1e-470c-a3bc-3968bc770e39', 'Both numbers must be equal to 1', false, '62401221-672c-4bfb-8bc5-3fc4eb1823fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e93096b-8048-4a41-b3f4-c4a22d265963', 'Both numbers must be greater than 10', false, '62401221-672c-4bfb-8bc5-3fc4eb1823fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80a2f09a-67d1-4b13-941d-d1e7a0d13db3', 'Neither number can be zero', false, '62401221-672c-4bfb-8bc5-3fc4eb1823fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9bf6349a-b6f8-4665-aaef-d5d97a0f3bcf', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Medium', 'If the product of two whole numbers is 1, what can we conclude?', 'In whole numbers, the only factors of 1 are 1 × 1 = 1; hence both numbers must be 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e17995d2-8d35-4f75-840d-cf61fcdba1c0', 'Both numbers must be equal to 1', true, '9bf6349a-b6f8-4665-aaef-d5d97a0f3bcf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('badf950c-47d5-4a56-8ad1-d13a3483b367', 'One number is 0 and the other is 1', false, '9bf6349a-b6f8-4665-aaef-d5d97a0f3bcf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e519e61-9392-42d6-aff9-a9c887cf4880', 'Both numbers can be any prime number', false, '9bf6349a-b6f8-4665-aaef-d5d97a0f3bcf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ea2c141-b94b-4202-afb9-df952b8998f4', 'Their sum is 1', false, '9bf6349a-b6f8-4665-aaef-d5d97a0f3bcf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb92cd78-bd81-4127-b38f-76f0eea29cd3', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ec871ee-0755-4c65-86e5-1249d9bb4642', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'bb92cd78-bd81-4127-b38f-76f0eea29cd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34a4551c-f953-4790-9ae1-04b0beb41eb6', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'bb92cd78-bd81-4127-b38f-76f0eea29cd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab4aced6-f7cd-4420-bebd-6a56b22411c1', '(A) is true, but (R) is false.', false, 'bb92cd78-bd81-4127-b38f-76f0eea29cd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c36b2f0-17f2-496e-9e4a-9a4c19828a82', '(A) is false, but (R) is true.', false, 'bb92cd78-bd81-4127-b38f-76f0eea29cd3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8db1ce32-7a0b-4108-a310-5354c23f3c35', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'Spot the IMPOSTER in the following mathematical properties of whole numbers:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96afff8d-55a1-484f-91c4-2f9de9f78cdf', 'Closure under Addition', false, '8db1ce32-7a0b-4108-a310-5354c23f3c35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('333b2b7a-3227-4f6b-9ff2-ba21063dd166', 'Commutativity of Multiplication', false, '8db1ce32-7a0b-4108-a310-5354c23f3c35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8661fe26-e116-4578-be40-74934085ad35', 'Associativity of Addition', false, '8db1ce32-7a0b-4108-a310-5354c23f3c35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('931fd961-fb96-485e-86ab-a5e099ab196a', 'Commutativity of Subtraction', true, '8db1ce32-7a0b-4108-a310-5354c23f3c35');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('33297304-f19a-4e64-aaf7-2a71d67a1bbf', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'Find the value of: 125 × 40 × 8 × 25 using optimal grouping:', 'Group (125 × 8) × (40 × 25) = 1,000 × 1,000 = 1,000,000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('037c6081-1eb0-4653-abfd-52eba2a58dfa', '10,00,000 (1 Million)', true, '33297304-f19a-4e64-aaf7-2a71d67a1bbf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c4927e3-a277-4549-88c9-06153ef82c79', '1,00,000', false, '33297304-f19a-4e64-aaf7-2a71d67a1bbf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04573e18-6c8d-4264-be1a-3c588ce6315d', '5,00,000', false, '33297304-f19a-4e64-aaf7-2a71d67a1bbf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94e616da-35c8-4e31-ac07-8ca08d7e871a', '10,000', false, '33297304-f19a-4e64-aaf7-2a71d67a1bbf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8de21851-28a5-4993-ac9d-0ab993d47f21', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'If a = 5, b = 3, c = 2, verify the Distributive Property of multiplication over subtraction: a × (b - c) = ?', 'Distributive property holds over subtraction: a(b - c) = ab - ac.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('950d2da7-a8a2-469c-b4af-fa2b1a0aea82', 'a × b - a × c = 5 × 3 - 5 × 2 = 15 - 10 = 5', true, '8de21851-28a5-4993-ac9d-0ab993d47f21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02eaf4cd-b04c-4660-9a0a-c97341baafcf', 'a × b + a × c = 25', false, '8de21851-28a5-4993-ac9d-0ab993d47f21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('586f6d47-0f13-4cac-8110-6cca67aa917a', 'a × (b + c) = 25', false, '8de21851-28a5-4993-ac9d-0ab993d47f21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49a973ed-009b-4cef-b33d-4199ee0aa2c5', '10', false, '8de21851-28a5-4993-ac9d-0ab993d47f21');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ae75bc0-bca6-4edc-a388-b3e37962a413', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'Match the following operations with their properties:
(a) 425 × 136 = 425 × (6 + 30 + 100) -> (i) Commutativity under multiplication
(b) 2 × 49 × 50 = 2 × 50 × 49          -> (ii) Commutativity under addition
(c) 80 + 2005 + 20 = 80 + 20 + 2005      -> (iii) Distributivity of multiplication over addition', 'a is Distributive property; b is Commutativity of multiplication; c is Commutativity of addition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('410d50b0-7bb0-428b-850d-b3fd99d60b6c', 'a-(iii), b-(i), c-(ii)', true, '2ae75bc0-bca6-4edc-a388-b3e37962a413');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03f710d8-5771-4643-9fed-243201bfe81a', 'a-(i), b-(ii), c-(iii)', false, '2ae75bc0-bca6-4edc-a388-b3e37962a413');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b122520-d669-4bb4-8359-8edbaadb46c9', 'a-(ii), b-(iii), c-(i)', false, '2ae75bc0-bca6-4edc-a388-b3e37962a413');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3531a75a-ac76-42e7-892f-bd95352a2db9', 'a-(iii), b-(ii), c-(i)', false, '2ae75bc0-bca6-4edc-a388-b3e37962a413');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('834480c9-5e4a-4edf-a588-df9027c81ff1', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'Read the statements:
