INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46401491-c599-42c4-8835-7e4dfec02409', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'Solve using pattern: 111 × 111 = 12,321. What is the value of 11,111 × 11,111?', 'Product of n ones with n ones ascends from 1 to n then descends back to 1: for n=5 -> 123454321.', NOW()) ON CONFLICT DO NOTHING;
