INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c63621b1-638c-4ae3-bf53-593f1072ef27', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'What is the sum of the first 10 odd natural numbers (1 + 3 + 5 + ... + 19)?', 'The sum of the first n odd natural numbers is always equal to n²; for n = 10, sum = 10² = 100.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ba789c2-de44-4f96-8633-524319a1df9c', '100 (= 10²)', true, 'c63621b1-638c-4ae3-bf53-593f1072ef27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d821487c-9c8b-4519-96a6-0e94cbef142c', '90', false, 'c63621b1-638c-4ae3-bf53-593f1072ef27');
