INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dcdaffe5-6513-4085-b201-4e2c89d15bd2', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'A school canteen charges ₹ 25 for lunch and ₹ 6 for milk each day. How much money does a student spend in 5 days on these items?', 'Total spent = 5 × (25 + 6) = 5 × 31 = ₹ 155.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45343dfa-86de-4171-af69-333d8875ccf7', '₹ 155', true, 'dcdaffe5-6513-4085-b201-4e2c89d15bd2');
