INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('713e586a-dc9b-410f-a6e0-f24d8f531b5e', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'Find the value of (3845 × 5 × 782) + (769 × 25 × 218):', 'Notice 769 × 25 = 769 × 5 × 5 = 3845 × 5 = 19,225. Expression = 19,225 × (782 + 218) = 19,225 × 1,000 = 1,92,25,000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfdba0e2-0142-49cb-bebf-023093be0fe9', '1,92,25,000', true, '713e586a-dc9b-410f-a6e0-f24d8f531b5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7ad1abf-3d7f-40dd-9ad9-aa9441c3e342', '1,92,00,000', false, '713e586a-dc9b-410f-a6e0-f24d8f531b5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c900047f-19d6-494f-a1bc-16324d786a78', '1,85,25,000', false, '713e586a-dc9b-410f-a6e0-f24d8f531b5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f3701b1-2d4e-4ed3-839c-e925df190267', '2,00,00,000', false, '713e586a-dc9b-410f-a6e0-f24d8f531b5e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5bfed924-7635-44b9-a840-5df565e05d92', 'Class 6', 'Mathematics', 'Chapter 2: Whole Numbers', 'Hard', 'If x is any whole number, which of the following expressions is ALWAYS equal to x?', '1 is the multiplicative identity: x × 1 = x for every whole number x.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1737bd78-8d60-4fd2-a3ef-8c380a6a3259', 'x × 1', true, '5bfed924-7635-44b9-a840-5df565e05d92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7938bb0-960a-4267-bfbc-1b22e7887b4e', 'x ÷ 0', false, '5bfed924-7635-44b9-a840-5df565e05d92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ec07e09-af18-45a5-b5d8-13bc47519d7d', 'x - 1', false, '5bfed924-7635-44b9-a840-5df565e05d92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09c03187-4cae-44bc-bedc-07a4936a3852', 'x + 1', false, '5bfed924-7635-44b9-a840-5df565e05d92');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c43150fc-4b6e-4f7c-8301-14c640c9c8f9', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Long ago, how did dogs live before deciding to find a master?', 'Dogs once lived as wild beasts in full freedom, being their own masters until one dog grew tired of hunting.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5fbc3a4-9fae-40ef-a85e-32c12eb2cf44', 'They lived in freedom, like wolves, being their own masters', true, 'c43150fc-4b6e-4f7c-8301-14c640c9c8f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be1cb84c-69a3-4159-b366-9304a3120787', 'They lived in zoos', false, 'c43150fc-4b6e-4f7c-8301-14c640c9c8f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1780beda-19d6-476b-8e9f-6af950b9f6e1', 'They were kept as farm cattle', false, 'c43150fc-4b6e-4f7c-8301-14c640c9c8f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6393361b-6d3c-4c59-8461-bc5c166ef8eb', 'They lived only in cold caves', false, 'c43150fc-4b6e-4f7c-8301-14c640c9c8f9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c03d9cb3-0cd4-4d4e-8611-b035b1d3ba2f', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Why was the dog sick and tired of his free, wild way of life?', 'The dog was tired of hunting alone and living in constant fear of more powerful predators.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f22ba0cb-f7a6-4b96-be1a-c145f8c907f1', 'He was tired of wandering about alone looking for food and being frightened of stronger animals', true, 'c03d9cb3-0cd4-4d4e-8611-b035b1d3ba2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d1cac6c-3397-4208-8263-650f185daefa', 'He wanted to sleep in a warm house', false, 'c03d9cb3-0cd4-4d4e-8611-b035b1d3ba2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e234904-074b-4226-99d3-5ae0da9ed91d', 'He hated running in forests', false, 'c03d9cb3-0cd4-4d4e-8611-b035b1d3ba2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('089b41d4-3130-42b8-9c9e-642ea55d447e', 'He wanted to eat cooked meat only', false, 'c03d9cb3-0cd4-4d4e-8611-b035b1d3ba2f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('08d2d1f1-534d-4808-9dd6-cb0d379ba083', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'What decision did the dog make to solve his problem?', 'He decided to seek service under the absolute strongest being on Earth to secure safety and food.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1803709d-0c12-43f6-b112-add7583ed603', 'To become the loyal servant of someone who was stronger than anyone on Earth', true, '08d2d1f1-534d-4808-9dd6-cb0d379ba083');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2db9e0cd-b133-4760-baba-694c4d099d88', 'To hide underground forever', false, '08d2d1f1-534d-4808-9dd6-cb0d379ba083');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e3281c7-400d-4ff9-a976-8eda43e8eb95', 'To become a vegetarian', false, '08d2d1f1-534d-4808-9dd6-cb0d379ba083');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09055a75-a2a2-431d-8567-89d8e54b182c', 'To fly in the sky like birds', false, '08d2d1f1-534d-4808-9dd6-cb0d379ba083');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('86b180ca-148a-4691-bb8e-3a90b248f062', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Who was the FIRST creature the dog chose as his master?', 'The dog first met a big, fierce wolf and agreed to serve him as master.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d89d537-24ef-40c4-bede-5d4762c47ad4', 'A big, fierce Wolf (his kinsman)', true, '86b180ca-148a-4691-bb8e-3a90b248f062');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3bf14bc-1720-49c5-a20d-f57332343c40', 'A Bear', false, '86b180ca-148a-4691-bb8e-3a90b248f062');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffde9a32-ea56-4c2f-85c5-575e9e92a109', 'A Lion', false, '86b180ca-148a-4691-bb8e-3a90b248f062');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e39079a-809a-47ff-aa25-e1dae4867b15', 'A Man', false, '86b180ca-148a-4691-bb8e-3a90b248f062');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd2237d9-dc69-481d-bcf5-b8d123106d52', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Why did the dog leave the Wolf?', 'Seeing the wolf terrified of the bear, the dog realized the wolf was not the strongest and left him.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3beb895-7d82-4f28-a1bf-2562c4e97f56', 'Because the Wolf was afraid of the Bear, who could eat them both', true, 'fd2237d9-dc69-481d-bcf5-b8d123106d52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8d4ebc6-79c7-458b-be4b-4eb2f3efb15a', 'The Wolf refused to share food', false, 'fd2237d9-dc69-481d-bcf5-b8d123106d52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63c689c8-4746-45f0-b1f8-0309563e9a4c', 'The Wolf bit the dog', false, 'fd2237d9-dc69-481d-bcf5-b8d123106d52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be3de33e-c343-46a3-955f-72e2bbc2fa1b', 'The Wolf ran away to another country', false, 'fd2237d9-dc69-481d-bcf5-b8d123106d52');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c54eee1a-809a-43eb-8556-dbb208ef3bcb', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Who was the SECOND master chosen by the dog?', 'After leaving the wolf, the dog offered his service to the Bear.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06e3e415-afe1-48a6-b287-940349190f24', 'The Bear', true, 'c54eee1a-809a-43eb-8556-dbb208ef3bcb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8066065d-e78a-451b-9f11-d179a1a8b50f', 'The Wolf', false, 'c54eee1a-809a-43eb-8556-dbb208ef3bcb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f40ed882-fcb8-4303-b8d0-ce38233e7330', 'The Lion', false, 'c54eee1a-809a-43eb-8556-dbb208ef3bcb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58844ea5-55df-475d-aecb-10558211ada6', 'The Elephant', false, 'c54eee1a-809a-43eb-8556-dbb208ef3bcb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37168b80-d4b5-4ea7-823b-0b5ec20b6bf5', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Why did the Bear run away into the deep forest while hunting a herd of cows?', 'The bear panicked upon hearing a lion, confessing that the Lion is the strongest beast in the forest.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b1e2b28-b983-4c38-8081-d7b6414426f1', 'He heard the loud, terrifying roar of a Lion', true, '37168b80-d4b5-4ea7-823b-0b5ec20b6bf5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f9e4e78-8c33-4b85-9e3c-86de7628b978', 'A thunderstorm started', false, '37168b80-d4b5-4ea7-823b-0b5ec20b6bf5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('936ac6c3-0459-46fa-8a59-66f2f2e95b19', 'The cows attacked the bear', false, '37168b80-d4b5-4ea7-823b-0b5ec20b6bf5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fb99d75-6ae4-4b4c-9672-d0a8575173d5', 'He smelled fire in the woods', false, '37168b80-d4b5-4ea7-823b-0b5ec20b6bf5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('059e04fb-aa64-47f5-8497-86953f62823a', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Who was the THIRD master chosen by the dog?', 'The dog left the bear and stayed with the Lion for a very long, comfortable time.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b003ccc-843d-4899-a628-9be2831fb04a', 'The Lion', true, '059e04fb-aa64-47f5-8497-86953f62823a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea68717a-9580-4726-8417-32098720db64', 'The Bear', false, '059e04fb-aa64-47f5-8497-86953f62823a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4550dc5-f61f-4074-a93f-9aaf0d281007', 'The Wolf', false, '059e04fb-aa64-47f5-8497-86953f62823a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a82db997-83cd-4f9d-bcbc-d6d0e3134894', 'The Tiger', false, '059e04fb-aa64-47f5-8497-86953f62823a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dac42e92-ff90-40da-b633-9df805acfc14', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Why did the Lion suddenly stop, give a great roar, and strike the ground angrily while walking near a cliff?', 'The lion caught the scent of human presence and warned the dog that they must flee or face trouble.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35ce769d-1ce1-47fb-8dbb-fd2a2a0d084b', 'He smelled the scent of a Man approaching and warned the dog to run away', true, 'dac42e92-ff90-40da-b633-9df805acfc14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea2f5a3d-fb0c-4064-982a-f3d1fc789566', 'He stepped on a sharp thorn', false, 'dac42e92-ff90-40da-b633-9df805acfc14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('016aadd4-440e-4c7b-b4cb-890b262c34c8', 'He saw an elephant coming', false, 'dac42e92-ff90-40da-b633-9df805acfc14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35de8d81-6c36-430e-939d-281e4333a222', 'He was hungry', false, 'dac42e92-ff90-40da-b633-9df805acfc14');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca22a4be-69a0-46b3-a370-83aca6bb8820', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'Who did the dog finally choose as his ULTIMATE and permanent master?', 'Realizing that Man is stronger than all wild beasts, the dog chose Man as his ultimate master.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6c84ff6-1b93-4cbb-85a0-e2e6d44c978f', 'Man (Human)', true, 'ca22a4be-69a0-46b3-a370-83aca6bb8820');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f948469-14b2-4354-89e7-23ae607d79db', 'The Lion', false, 'ca22a4be-69a0-46b3-a370-83aca6bb8820');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aeb27d8b-9b35-4acb-b794-9b13e87dfefb', 'The Tiger', false, 'ca22a4be-69a0-46b3-a370-83aca6bb8820');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('999887e3-b622-4e99-8a3c-6fdb55f92f73', 'The Elephant', false, 'ca22a4be-69a0-46b3-a370-83aca6bb8820');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96f05300-482c-4b0a-bd75-73e6c179ead1', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'In the poem ''The Kite'' by Harry Behn, how does a new kite look in the blue sky?', 'Poet Harry Behn opens: ''How bright on the blue is a kite when it''s new! With a dive and a dip it snaps its tail...''', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3beea92e-e0b0-476d-bc67-3aa65c1452bb', 'Bright and beautiful as it dives and dips', true, '96f05300-482c-4b0a-bd75-73e6c179ead1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4513714-c373-478c-a59f-e99718b03b71', 'Dark and dusty', false, '96f05300-482c-4b0a-bd75-73e6c179ead1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8233b16f-6564-4830-bcbf-6e36ec054555', 'Heavy and clumsy', false, '96f05300-482c-4b0a-bd75-73e6c179ead1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('798a72b4-7522-469d-9cc0-3ebf1a0f51ad', 'Faded and torn', false, '96f05300-482c-4b0a-bd75-73e6c179ead1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('08f263f6-b3e7-425c-b624-73786d8fcf9a', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Easy', 'In the supplementary story ''The Friendly Mongoose'', why did the farmer bring a baby mongoose home?', 'The farmer wished to provide his infant son with a loyal companion as the child grew up.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92214a31-e3b5-4e0c-87b9-f7737d91a7b0', 'To be a companion and protective pet for their infant son', true, '08f263f6-b3e7-425c-b624-73786d8fcf9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16adf124-5393-4d61-8e9a-c70ce7b7e0ab', 'To sell it in the market', false, '08f263f6-b3e7-425c-b624-73786d8fcf9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06d827d3-4a9b-4fd9-ab30-045e055b5153', 'To guard the crops from thieves', false, '08f263f6-b3e7-425c-b624-73786d8fcf9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f42bde30-22d1-46e5-92ca-5d29bbdb235c', 'To hunt birds in the garden', false, '08f263f6-b3e7-425c-b624-73786d8fcf9a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d11869c9-9143-496f-a847-98328296b3e1', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What is the chronological sequence of masters tested by the dog in his quest for the strongest leader?', 'The dog successively evaluated and transitioned from Wolf to Bear, then Lion, and finally Man.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46959097-2f87-44fa-98fe-a26b935f44d5', 'Wolf -> Bear -> Lion -> Man', true, 'd11869c9-9143-496f-a847-98328296b3e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5e5f2ec-8ec6-4789-ad2f-ccf1394926a1', 'Bear -> Wolf -> Lion -> Man', false, 'd11869c9-9143-496f-a847-98328296b3e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63c9f6b2-8e26-4063-8761-b6a443226f2e', 'Lion -> Bear -> Wolf -> Man', false, 'd11869c9-9143-496f-a847-98328296b3e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5154bfbf-27e0-4a5b-8fa7-d738f7321f2b', 'Wolf -> Lion -> Bear -> Man', false, 'd11869c9-9143-496f-a847-98328296b3e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('09001af4-de33-405f-9790-85bfe95bcec2', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What figure of speech / simile is used in the poem ''The Kite'' to describe the flight of a kite soaring on a gust of wind?', 'The poet compares the effortless aerodynamic riding of the kite to a ship gliding over ocean waves with a single sail.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9243fda6-573b-4cfe-adb9-4c92c7bdb8b1', '"Then soars like a ship with only a sail"', true, '09001af4-de33-405f-9790-85bfe95bcec2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b3ceb46-9c62-4f9b-9a5b-3030c44b9faf', '"Dives like an eagle"', false, '09001af4-de33-405f-9790-85bfe95bcec2');
