INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36bd12b3-e889-451c-ae53-32c4cb5f2922', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What makes a soaring kite become a ''raggedy thing'' according to Harry Behn''s poem?', 'The poem laments the pathetic sight of a trapped kite fluttering and tearing apart upon tree branches.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a2b1a6b-a495-4f1c-a3bb-33ea1a6eb40a', 'When its string gets tangled in the branches of a tree, flapping helplessly until torn', true, '36bd12b3-e889-451c-ae53-32c4cb5f2922');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6282c526-92f5-4667-8650-b81b12aa86d1', 'When it gets wet in rain', false, '36bd12b3-e889-451c-ae53-32c4cb5f2922');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26f1b19f-8994-4443-8c36-0099fca1195e', 'When the sun sets', false, '36bd12b3-e889-451c-ae53-32c4cb5f2922');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2ecb3a8-2785-4cc8-bbb0-3ec4ddbac5fb', 'When children cut the tail', false, '36bd12b3-e889-451c-ae53-32c4cb5f2922');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4e12d9c-9ced-4621-901a-0e733d48e764', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'In ''The Friendly Mongoose'', why did the farmer''s wife kill the loyal mongoose with a heavy water pot?', 'She jumped to a hasty, tragic conclusion without inspecting the cradle inside the room.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e80e9b8-4a73-4097-ad9d-ee704bb0a967', 'She acted in hasty blind rage, seeing blood on the mongoose''s mouth and assuming it had harmed her sleeping baby', true, 'd4e12d9c-9ced-4621-901a-0e733d48e764');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f2b0a46-b5a3-4cfb-a0e9-f2f8a52452ed', 'The mongoose bit her leg', false, 'd4e12d9c-9ced-4621-901a-0e733d48e764');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89691e5b-6d67-4b5c-80e5-c5efc58aea05', 'The mongoose stole her food', false, 'd4e12d9c-9ced-4621-901a-0e733d48e764');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edc5f75a-40f3-4be3-b641-e076fab91027', 'She wanted a dog instead', false, 'd4e12d9c-9ced-4621-901a-0e733d48e764');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('958fa0e6-7296-4ca3-b3d9-e19c127526c1', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What did the farmer''s wife find inside the room AFTER she struck down the mongoose?', 'The brave mongoose had fought and killed the venomous snake to defend the sleeping infant.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2443ccc9-346c-42a6-94d8-8bbf40fbf94f', 'Her baby sleeping peacefully in the cradle, and a black venomous cobra lying torn and bleeding dead on the floor', true, '958fa0e6-7296-4ca3-b3d9-e19c127526c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('098c710a-6ac3-4782-ab97-2f25c91b337e', 'The baby was missing', false, '958fa0e6-7296-4ca3-b3d9-e19c127526c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a075898-649c-4d64-a3b9-94d42c0b6bf6', 'The cradle was on fire', false, '958fa0e6-7296-4ca3-b3d9-e19c127526c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5cabc21-0cfc-4ab2-9785-e97ce2334f35', 'Another snake inside the bed', false, '958fa0e6-7296-4ca3-b3d9-e19c127526c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac864b6c-716b-4707-8c58-e1b8fbc96d90', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What profound moral lesson is taught by the Panchatantra tale ''The Friendly Mongoose''?', 'Hasty, unthinking emotional action leads to irreversible tragedy and lifelong remorse.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4de607ac-f45c-4033-b9ab-2cc3946914a5', 'Never act in hasty anger or make irreversible decisions without verifying facts first (''Look before you leap'')', true, 'ac864b6c-716b-4707-8c58-e1b8fbc96d90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b554b438-3f50-499e-af3f-ba0a6f981163', 'Never keep any animals as pets', false, 'ac864b6c-716b-4707-8c58-e1b8fbc96d90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c7e76bd-9c2f-4f56-9e1c-c9f99a56f24b', 'Mongoose and snakes are best friends', false, 'ac864b6c-716b-4707-8c58-e1b8fbc96d90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27d47cf5-36b9-4ed1-a5b0-e48fc9c0779b', 'Women should never fetch water', false, 'ac864b6c-716b-4707-8c58-e1b8fbc96d90');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('079471bf-5987-425c-8e09-05ba5798c4dc', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'Choose the correct meaning of the collective noun ''a herd'' as used in the chapter:', '''Herd'' denotes a collective assemblage of herbivorous domestic or wild ungulates (cows, deer, elephants).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f73e744f-2fba-443e-80cb-19483439ff44', 'A group of cattle / grazing animals', true, '079471bf-5987-425c-8e09-05ba5798c4dc');
