INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5a819115-0679-4181-a1af-495d1cc4eadb', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What is the collective noun used for a group of Wolves in English grammar?', 'In standard grammatical nomenclature, wolves hunt and travel socially in ''a pack''.', NOW()) ON CONFLICT DO NOTHING;
