INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cca6d1b8-df09-490f-bb15-106d6fde1456', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What does the word ''Kinsman'' mean in the sentence: ''The dog met a wolf who was his kinsman''?', 'A kinsman is a blood relative; canids (dogs, wolves, jackals) share direct evolutionary kinship.', NOW()) ON CONFLICT DO NOTHING;
