INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b23bea6-22fe-4135-bab7-8f9c7a9826d0', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What does the word ''Fierce'' mean in the context of the Wolf''s description?', '''Fierce'' describes an intimidating, menacing, and ferocious disposition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c69afd94-dea9-4456-b203-e083b0c5ebb0', 'Violent, aggressive, and frightening', true, '8b23bea6-22fe-4135-bab7-8f9c7a9826d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e31778a4-e441-429f-82cd-ea3f330349e7', 'Gentle and calm', false, '8b23bea6-22fe-4135-bab7-8f9c7a9826d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e527a7ba-cb19-457c-82d4-796decbd23cb', 'Tiny and weak', false, '8b23bea6-22fe-4135-bab7-8f9c7a9826d0');
