INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49d22482-9a86-47ae-84d3-635651843783', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What does ''sniff the air'' mean as done by the Bear and the Lion in the forest?', 'Olfactory tracking enables wild animals to detect chemical pheromones and potential threats.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ba9ccf2-9324-4e23-a787-f7250de45fde', 'To draw in air through the nose to detect the scent of other animals or danger', true, '49d22482-9a86-47ae-84d3-635651843783');
