INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c722fbaf-d2d2-48c1-a8bc-84be35a0284d', 'To blow cold wind', false, '49d22482-9a86-47ae-84d3-635651843783');
