INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e15f285-9fef-426d-a990-3c327a01efd1', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What does the phrase ''to take up service with someone'' mean in the story?', 'The idiom denotes pledging one''s labor, allegiance, and dutiful service to a designated superior.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aee1269-9bd8-4294-8263-acadea54a914', 'To become someone''s loyal servant or employee', true, '8e15f285-9fef-426d-a990-3c327a01efd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('427eb555-623d-426a-983a-ba842a030949', 'To fight against someone', false, '8e15f285-9fef-426d-a990-3c327a01efd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('134e9eeb-1b39-4770-a6ce-5bf3666f5e80', 'To invite someone for dinner', false, '8e15f285-9fef-426d-a990-3c327a01efd1');
