INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5a7e5bf4-6be4-40b6-a4cc-549b362b24fb', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'How long did the dog serve the Lion before deciding to leave him?', 'The dog enjoyed a long, tranquil life with the Lion because no other beast dared offend the King of the forest.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f295c8b8-2084-4ae1-89ed-9a8396523ba1', 'For a long, long time with great peace and satisfaction, until a man passed by', true, '5a7e5bf4-6be4-40b6-a4cc-549b362b24fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('becb42ae-94db-4a38-a732-889928a35f68', 'Only for one afternoon', false, '5a7e5bf4-6be4-40b6-a4cc-549b362b24fb');
