INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b8cf696a-7a87-4f72-96a6-2c3bd42262ca', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What does ''cliff'' mean in the line: ''They walked on until the lion stopped near a bare cliff''?', 'A cliff is an exposed vertical or near-vertical rocky precipice.', NOW()) ON CONFLICT DO NOTHING;
