INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c546fcdf-987d-4070-82d3-ed1b0cbd4e84', 'A river bridge', false, 'b8cf696a-7a87-4f72-96a6-2c3bd42262ca');
