INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('033350fa-06cf-489d-8b1b-53748e8dcbee', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'In ''The Kite'', when the wind falls, what happens to the kite''s string?', 'As aerodynamic lift drops, the tethering line loses tension, requiring the flier to wind the spool.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e075ffd-52b4-4d70-8124-6edf4446e17d', 'The string goes slack, and the child winds it back on the reel', true, '033350fa-06cf-489d-8b1b-53748e8dcbee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a83d92f9-eb00-45f8-b599-3204bb8f4aa2', 'The kite snaps into space', false, '033350fa-06cf-489d-8b1b-53748e8dcbee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0e52de3-33b0-44ae-bd34-937f07ee1e27', 'The kite turns into a bird', false, '033350fa-06cf-489d-8b1b-53748e8dcbee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('478dd7ab-9370-4706-85a2-542875a22169', 'The string catches fire', false, '033350fa-06cf-489d-8b1b-53748e8dcbee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d90e3201-1b84-4a8b-a98f-780089c891b5', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Medium', 'What is the relationship between dogs and humans since the events of the folk legend?', 'The tale concludes that canine domestication established an enduring bond of unparalleled fidelity to humanity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55fbd288-6852-4b09-9c41-9083c38713f1', 'The dog serves Man faithfully and knows no other master to this day', true, 'd90e3201-1b84-4a8b-a98f-780089c891b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef354bbc-8f09-45b4-86b6-f8c79e92f883', 'Dogs returned to live in the wild as wolves', false, 'd90e3201-1b84-4a8b-a98f-780089c891b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eac0c086-dce7-4b9c-a567-2442d9297605', 'Dogs became wild enemies of humans', false, 'd90e3201-1b84-4a8b-a98f-780089c891b5');
