INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9df0bb64-daec-4da1-b902-5158b46b76c2', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Hard', 'Match the following actions from the story with the emotions they express:
(a) Lion strikes ground and roars -> (i) Frantic panic & self-preservation
(b) Bear runs hastily into forest  -> (ii) Alarm at detecting human threat
(c) Dog wags tail before man       -> (iii) Submission & lifelong loyalty
(d) Wolf hides behind bushes      -> (iv) Fear of a larger predator (Bear)', 'Accurately maps behavioral physical cues of wild predators to their internal psychological motivations in the text.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cca09f50-c8d9-4a56-b8fd-4ca998e2368c', 'a-(ii), b-(i), c-(iii), d-(iv)', true, '9df0bb64-daec-4da1-b902-5158b46b76c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec8c610b-3a19-429f-8fba-fcff292acf3d', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '9df0bb64-daec-4da1-b902-5158b46b76c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20887c4a-0589-4ecf-ba7f-32344238024e', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '9df0bb64-daec-4da1-b902-5158b46b76c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('955c52d1-c052-4607-bc62-a84f59935ff9', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '9df0bb64-daec-4da1-b902-5158b46b76c2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06ddec08-f6f0-4a31-9eb5-dcf23495f6b2', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Hard', 'In the poem ''The Kite'', what is the poetic significance of comparing a kite''s flight to a ship riding the ''crest of a gust''?', 'Harry Behn evokes fluid dynamics: airflow lift beneath the paper sail mimics buoyant hydrodynamic waves beneath a schooner.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3918074e-22a5-4015-b7b0-fb3a20c7232f', 'It captures the majestic, buoyant rhythm of soaring high over atmospheric thermal currents, mimicking a nautical vessel riding ocean swells', true, '06ddec08-f6f0-4a31-9eb5-dcf23495f6b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('834430a7-476a-417f-9038-c672c95f1bf9', 'It shows that kites can float on ocean water', false, '06ddec08-f6f0-4a31-9eb5-dcf23495f6b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3000289-73ee-4e17-b498-4765cec3d6d4', 'It means kites are made of heavy ship timber', false, '06ddec08-f6f0-4a31-9eb5-dcf23495f6b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6ece2a7-9b8f-459c-b38f-666118af2e6c', 'It proves kites are used as anchors', false, '06ddec08-f6f0-4a31-9eb5-dcf23495f6b2');
