INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88894eac-0915-42e9-b212-993a3246bb9a', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Hard', 'Which of the following proverbs encapsulates the core theme of the folk tale ''How the Dog Found Himself a New Master!''?', 'The dog exercises pragmatic social intelligence to secure lifelong survival and protection.', NOW()) ON CONFLICT DO NOTHING;
