INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa9e1205-c152-4870-af12-1382a8ececaf', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Hard', 'Why did the Lion express genuine fear of Man, despite being the crowned King of Beasts?', 'Human technology, fire, and strategic cooperative hunting historically subdued even the fiercest megafauna.', NOW()) ON CONFLICT DO NOTHING;
