INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62e9cea2-f5f6-4479-817a-e6396e60064a', 'Class 6', 'English', 'Chapter 2: How the Dog Found Himself a New Master!', 'Hard', 'What literary device is present in the line: ''With a dive and a dip it snaps its tail''?', 'The rhythmic repetition of the initial consonant sound /d/ in ''dive and dip'' is classical Alliteration.', NOW()) ON CONFLICT DO NOTHING;
