INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60c87752-b120-477e-9a75-64447f1c15d5', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'Why are the Frigid Zones (beyond Arctic and Antarctic Circles) extremely cold throughout the year?', 'High-angle obliquity spreads incoming solar flux over wide surface areas, generating minimal surface warming.', NOW()) ON CONFLICT DO NOTHING;
