INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64ef436d-77a8-4df2-bfab-2d0993f0ab26', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'How does the distance between two meridians of longitude change as one travels from the Equator towards the Poles?', 'Meridians are semi-circles converging at the poles; inter-meridian distance is maximum at Equator (~111 km) and 0 at poles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('111d79cc-d36b-454c-9d78-ece75e896ecf', 'The distance steadily decreases until it becomes zero at the poles where all meridians converge', true, '64ef436d-77a8-4df2-bfab-2d0993f0ab26');
