INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af37989d-65b0-4632-bb62-882952094f60', 'It doubles at 45° latitude', false, '64ef436d-77a8-4df2-bfab-2d0993f0ab26');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ba23b8f-f3af-449d-a825-937cbfe032b1', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'As the Earth rotates 360° on its axis in 24 hours, how many degrees of longitude does it rotate in ONE hour?', 'Earth rotates 360° in 24 hours = 15° longitude per 60 minutes = 1° longitude every 4 minutes.', NOW()) ON CONFLICT DO NOTHING;
