INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9fe027e-8d9b-4267-9cda-fc2926f59832', '10° per hour', false, '1ba23b8f-f3af-449d-a825-937cbfe032b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cc37209-5e0e-4898-b9f0-305430643d87', '20° per hour', false, '1ba23b8f-f3af-449d-a825-937cbfe032b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fc2589c-f9d5-4c37-b242-be09e2fe0b7d', '1° per hour', false, '1ba23b8f-f3af-449d-a825-937cbfe032b1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63e55c41-4901-472e-9b6a-9a1ff704a723', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'How much time difference corresponds to a difference of 1° of longitude?', '60 minutes ÷ 15° = 4 minutes per 1° change in terrestrial longitude.', NOW()) ON CONFLICT DO NOTHING;
