INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20b93f20-8665-4613-8a0d-52296af0a5de', '15 minutes', false, '63e55c41-4901-472e-9b6a-9a1ff704a723');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16be847c-4ebb-45d3-b7ed-f38d1938b643', '1 hour', false, '63e55c41-4901-472e-9b6a-9a1ff704a723');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d36d0f33-09d0-4193-a51f-d97cfe834bb2', '1 minute', false, '63e55c41-4901-472e-9b6a-9a1ff704a723');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f1f1fd5-9894-421d-8ed7-9fe8d2bc8f2f', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'What is the official Standard Meridian of India chosen to fix the Indian Standard Time (IST)?', '82°30'' E passing through Mirzapur/Prayagraj is the official Standard Meridian of India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('580ad6dc-04d0-4169-b806-7239c3c86ccb', '82° 30'' E (82½° East passing through Mirzapur, UP)', true, '2f1f1fd5-9894-421d-8ed7-9fe8d2bc8f2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb69f955-4f7c-413c-a442-18048ace2648', '80° E', false, '2f1f1fd5-9894-421d-8ed7-9fe8d2bc8f2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a01d169-ec6a-4cae-9ff3-207ce3fae5bd', '75° E', false, '2f1f1fd5-9894-421d-8ed7-9fe8d2bc8f2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b98a3f3f-ba30-45ed-8994-c62b7c8ec4d6', '90° E', false, '2f1f1fd5-9894-421d-8ed7-9fe8d2bc8f2f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31b2cb68-f791-4b00-987a-a64f3d9bda82', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'How much is Indian Standard Time (IST) ahead of Greenwich Mean Time (GMT)?', '82.5° × 4 minutes = 330 minutes = +5 hours 30 minutes ahead of Greenwich (0°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b66d5c55-d223-4909-a1f3-cb61ad5ba78e', '5 hours and 30 minutes ahead (+5:30)', true, '31b2cb68-f791-4b00-987a-a64f3d9bda82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b166be57-3fc5-4889-82b5-283b02caa40f', '5 hours behind', false, '31b2cb68-f791-4b00-987a-a64f3d9bda82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08812ae9-8ee3-4eca-ba0f-31f09e7e1283', '6 hours ahead', false, '31b2cb68-f791-4b00-987a-a64f3d9bda82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b32260b2-f530-4e0f-bf87-5032b5c574a7', '4 hours and 30 minutes ahead', false, '31b2cb68-f791-4b00-987a-a64f3d9bda82');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('21e68adb-8e16-4655-aeb3-f01111dd0e16', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'What is the approximate local time difference between Dwarka in Gujarat (western tip) and Dibrugarh in Assam (eastern tip) of India?', 'India spans ~30° longitude (68°7'' E to 97°25'' E); 30° × 4 min = 120 min ≈ 1 hr 45 min local solar time difference.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4528658f-3aa0-4cde-a5ed-1c2c54402414', 'About 1 hour and 45 minutes', true, '21e68adb-8e16-4655-aeb3-f01111dd0e16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('719f7d79-07fa-45e1-b3a2-f8789752b66d', '30 minutes', false, '21e68adb-8e16-4655-aeb3-f01111dd0e16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7733d042-c75a-4fe0-959f-d965a4e55050', '3 hours', false, '21e68adb-8e16-4655-aeb3-f01111dd0e16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28d17cae-6516-4d77-b304-696566500113', 'Zero minutes', false, '21e68adb-8e16-4655-aeb3-f01111dd0e16');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd438604-994a-433a-a091-f409b063c0f0', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'Why do places situated to the EAST of Greenwich gain time and are ahead of GMT?', 'Prograde west-to-east axial spin brings eastern longitudes into solar view ahead of western coordinates.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42bbd967-883f-4deb-8a2c-40672629fb9e', 'Because Earth rotates on its axis from West to East, so eastern places experience sunrise earlier', true, 'dd438604-994a-433a-a091-f409b063c0f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3430ccf7-4f1c-4a58-b6cb-9b8ec2f3660b', 'Because the Sun rotates from East to West', false, 'dd438604-994a-433a-a091-f409b063c0f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d15f73b-1f1e-495c-95ab-fd0f17e67220', 'Because Greenwich is at the highest mountain', false, 'dd438604-994a-433a-a091-f409b063c0f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c82390b8-f889-40a6-84fd-985803797cca', 'Because clocks run faster in the east', false, 'dd438604-994a-433a-a091-f409b063c0f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f891b1f0-1174-4e67-b991-cc159aa84401', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'Which of the following thermal zones lies between the Tropic of Cancer (23½° N) and the Arctic Circle (66½° N)?', 'The Temperate Zones experience moderate temperatures with neither extreme tropical heat nor polar freezing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('341da2d0-93b1-48fe-b8fd-886445d02b26', 'North Temperate Zone (moderate climate)', true, 'f891b1f0-1174-4e67-b991-cc159aa84401');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('554f7100-9676-4b01-821f-99a2cf294926', 'Torrid Zone', false, 'f891b1f0-1174-4e67-b991-cc159aa84401');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be276495-e5dc-4bf1-9ee7-ff5cd4699fce', 'North Frigid Zone', false, 'f891b1f0-1174-4e67-b991-cc159aa84401');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f3feb28-db5d-4a4a-aee0-c2fca82ec5aa', 'South Temperate Zone', false, 'f891b1f0-1174-4e67-b991-cc159aa84401');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('152834af-1518-4430-96d8-374b28ef1a2a', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'What happens to the size / circumference of the parallels of latitude as we move from the Equator towards the poles?', 'Parallels are small circles of radius R·cos(θ); circumference shrinks to zero at θ = 90° (poles).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba5c7480-5d26-47f4-9629-c3943872597b', 'The length of the parallel circles decreases progressively until they become mere points at the poles', true, '152834af-1518-4430-96d8-374b28ef1a2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ce522d6-3c64-4239-9a1c-6fd237fc0348', 'They become larger', false, '152834af-1518-4430-96d8-374b28ef1a2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c134565-337d-48ed-a450-7d777e0fe710', 'They stay the exact same size', false, '152834af-1518-4430-96d8-374b28ef1a2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5831f94-0aeb-4a23-b7f8-ecdc2e99157d', 'They become straight lines', false, '152834af-1518-4430-96d8-374b28ef1a2a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2622892f-2491-4ff5-8a1e-1b66ac10b877', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'If it is 12:00 Noon at Greenwich (0°), what will be the local solar time at 15° East longitude?', '15° East is ahead by 15 × 4 min = 60 min (1 hour); 12:00 Noon + 1 hour = 1:00 PM.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a94339dd-5f46-4f28-b12d-2ae3f3a4e638', '1:00 PM (13:00 hours)', true, '2622892f-2491-4ff5-8a1e-1b66ac10b877');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c6a9fc0-7b4c-4313-be41-4f1e91fc910e', '11:00 AM', false, '2622892f-2491-4ff5-8a1e-1b66ac10b877');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d652b6c-3933-4a35-a57a-78ec32a65893', '2:00 PM', false, '2622892f-2491-4ff5-8a1e-1b66ac10b877');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c16d1f5-1991-4af9-ab5d-619ac4d0217e', '12:15 PM', false, '2622892f-2491-4ff5-8a1e-1b66ac10b877');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b60beda6-01c0-4c2c-a28d-dfee22b12e25', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'If it is 12:00 Noon at Greenwich (0°), what will be the local solar time at 15° West longitude?', '15° West is behind by 15 × 4 min = 60 min (1 hour); 12:00 Noon - 1 hour = 11:00 AM.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09c4900e-e937-41d7-b4a7-90ae44d96772', '11:00 AM', true, 'b60beda6-01c0-4c2c-a28d-dfee22b12e25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c59cf33-2f70-433b-ae93-fdfca1fe8bac', '1:00 PM', false, 'b60beda6-01c0-4c2c-a28d-dfee22b12e25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('294e6ecc-641f-442b-a862-f4a508cc91e2', '10:00 AM', false, 'b60beda6-01c0-4c2c-a28d-dfee22b12e25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aed21f54-9830-4338-a20d-a1573607b8a3', '12:15 PM', false, 'b60beda6-01c0-4c2c-a28d-dfee22b12e25');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62976c5f-68d6-4319-962a-eec96698e4c9', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'How many standard time zones has the world been divided into, each spanning 15° of longitude?', 'The planet is divided into 24 standard 1-hour time zones of 15° longitudinal width each (24 × 15° = 360°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54f06846-ac0d-4969-99a8-5486d2383b43', '24 standard time zones', true, '62976c5f-68d6-4319-962a-eec96698e4c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e998727d-026c-45f9-9c9e-d381fc7706ef', '12 time zones', false, '62976c5f-68d6-4319-962a-eec96698e4c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('863de838-db7b-4a9a-9548-07df97e447ff', '36 time zones', false, '62976c5f-68d6-4319-962a-eec96698e4c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1760aac0-e72a-45e1-ba83-acb8a02f5965', '10 time zones', false, '62976c5f-68d6-4319-962a-eec96698e4c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('341dc677-0e3b-4859-9cd9-179f7cce197b', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'Which country has the maximum number of standard time zones (11 time zones) due to its vast longitudinal extent?', 'Spanning over 160° of longitude across Eurasia, Russia is divided into 11 official standard time zones.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7348a8e-c38d-4ae0-a3c1-d0d9384dd4a1', 'Russia', true, '341dc677-0e3b-4859-9cd9-179f7cce197b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('033f20de-9df5-40d5-9f74-23c0f14460fb', 'India', false, '341dc677-0e3b-4859-9cd9-179f7cce197b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b068f103-b3b0-4942-a387-af916693d815', 'China', false, '341dc677-0e3b-4859-9cd9-179f7cce197b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be6e2017-bf2a-4805-9a2a-a67a9e62b96b', 'Australia', false, '341dc677-0e3b-4859-9cd9-179f7cce197b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('efa48762-7ccb-4154-9de4-5ef1fb043e54', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'What is the angle of tilt of the Earth''s rotational axis from its orbital plane vertical?', 'Earth''s rotational axis maintains a fixed 23.5° obliquity tilt from the perpendicular to its ecliptic orbital plane.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc0c1fa6-7494-4555-be1b-d2e7c85d798f', '23½° (making an angle of 66½° with its orbital plane)', true, 'efa48762-7ccb-4154-9de4-5ef1fb043e54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cc3da62-75f3-46b3-a667-5a89bf8d74c6', '45°', false, 'efa48762-7ccb-4154-9de4-5ef1fb043e54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3d3915f-b88c-4f81-8a07-3adb37741bac', '0°', false, 'efa48762-7ccb-4154-9de4-5ef1fb043e54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93a3909d-4b52-4284-b822-db35f0312e78', '90°', false, 'efa48762-7ccb-4154-9de4-5ef1fb043e54');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e438b9c4-1637-4484-964f-e223a17f61ef', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Medium', 'If a cricket match starts in London at 2:00 PM GMT, at what time will Indian viewers watch it live on TV (IST = GMT + 5:30)?', '2:00 PM + 5 hours 30 minutes = 7:30 PM IST in the evening.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb660cd0-cab2-4e21-847c-404dc01897ae', '7:30 PM IST', true, 'e438b9c4-1637-4484-964f-e223a17f61ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27bfb014-e322-4f8b-9c57-6de86fc95650', '5:30 PM IST', false, 'e438b9c4-1637-4484-964f-e223a17f61ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ce76f4b-f9b8-4763-85cc-75a61df89497', '8:00 PM IST', false, 'e438b9c4-1637-4484-964f-e223a17f61ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdbe4c21-cbfe-496b-aa4b-092355b56162', '12:30 PM IST', false, 'e438b9c4-1637-4484-964f-e223a17f61ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c8fe503-a892-4bf4-b351-78abc8c7c0c7', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7626b42d-84ee-49ae-9271-e26b93b4460a', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '5c8fe503-a892-4bf4-b351-78abc8c7c0c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f5289b4-ffd4-4785-97ad-80ab040d7b45', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '5c8fe503-a892-4bf4-b351-78abc8c7c0c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e359adc3-6bc9-4ea9-a095-0e347ec65b59', '(A) is true, but (R) is false.', false, '5c8fe503-a892-4bf4-b351-78abc8c7c0c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccbfefd0-f489-459c-81af-ec56be3a1076', '(A) is false, but (R) is true.', false, '5c8fe503-a892-4bf4-b351-78abc8c7c0c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc306158-b5ef-43c1-acff-6ea41a8121c4', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Spot the IMPOSTER in the following list of important parallels of latitude and their values:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9a58d3e-3da7-4c8d-82dd-7d198e4122b0', 'Tropic of Cancer - 23½° N', false, 'dc306158-b5ef-43c1-acff-6ea41a8121c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0931554b-5e93-4926-b811-c3239efa3009', 'Tropic of Capricorn - 23½° S', false, 'dc306158-b5ef-43c1-acff-6ea41a8121c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('877478bb-367c-449e-bb56-02fd9ab85b7a', 'Arctic Circle - 66½° N', false, 'dc306158-b5ef-43c1-acff-6ea41a8121c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b26b3060-86e8-471e-a243-3d20b42cedb4', 'Antarctic Circle - 66½° N', true, 'dc306158-b5ef-43c1-acff-6ea41a8121c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d0f2b1a-20d1-4540-add4-f387139398a9', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'A ship captain reports his position as 0° Latitude and 0° Longitude. Where is this vessel located on Earth?', 'The intersection of the Equator (0° Lat) and the Prime Meridian (0° Long) is located in the Gulf of Guinea (Null Island) in the Atlantic Ocean.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94e211d3-3620-4214-9943-d87229af5997', 'In the Atlantic Ocean off the coast of West Africa (Gulf of Guinea)', true, '0d0f2b1a-20d1-4540-add4-f387139398a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0da9c6b-2d68-4e78-918b-bc423dd53178', 'In the middle of the Indian Ocean', false, '0d0f2b1a-20d1-4540-add4-f387139398a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0f176df-a2e6-43f4-af74-df2bbff1cba9', 'On the top of Mount Everest', false, '0d0f2b1a-20d1-4540-add4-f387139398a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51af3011-7707-4875-8549-8c9b22bc72e5', 'In the Pacific Ocean', false, '0d0f2b1a-20d1-4540-add4-f387139398a9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dbb1e40d-6ef4-4e39-b5e3-3b6e7b1ca6f6', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Why does the mid-day sun NEVER shine directly overhead on any latitude beyond the Tropic of Cancer and Tropic of Capricorn?', 'Declination of the Sun is limited by Earth''s 23.5° axial obliquity; hence zenith sun is impossible at latitudes > 23.5°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0b251a8-8546-4334-873e-7409f59ecab2', 'Because the maximum axial tilt of the Earth is 23½°, so subsolar point oscillations are bounded strictly between 23½° N and 23½° S', true, 'dbb1e40d-6ef4-4e39-b5e3-3b6e7b1ca6f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('209e783c-38a2-448e-9762-441d06d20146', 'Because poles are too cold for sunlight', false, 'dbb1e40d-6ef4-4e39-b5e3-3b6e7b1ca6f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3176647b-ca9b-4b26-ab49-9abaeefe4f65', 'Because Earth is flat at the edges', false, 'dbb1e40d-6ef4-4e39-b5e3-3b6e7b1ca6f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d81ccbf-1bfb-478b-a071-a494ed6121da', 'Because the Sun shrinks in winter', false, 'dbb1e40d-6ef4-4e39-b5e3-3b6e7b1ca6f6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fb279dec-246f-441f-9105-2fcdca3e9284', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Match Column I (Locations) with Column II (Coordinates):
(a) Equator          -> (i) 90° S
(b) South Pole       -> (ii) 0° Longitude
(c) Prime Meridian   -> (iii) 0° Latitude
(d) 180° Meridian    -> (iv) International Date Line line of longitude', 'Equator = 0° Lat; South Pole = 90° S; Prime Meridian = 0° Long; 180° Meridian = Antimeridian/Date Line.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea9acd2c-6540-40ed-92e8-d86c6832ebb3', 'a-(iii), b-(i), c-(ii), d-(iv)', true, 'fb279dec-246f-441f-9105-2fcdca3e9284');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47ebccc9-89ea-413f-a2a3-54c712464eb9', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'fb279dec-246f-441f-9105-2fcdca3e9284');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23f513a0-fe0f-4abd-ba9c-e03c89b8a593', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'fb279dec-246f-441f-9105-2fcdca3e9284');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97222814-f7ed-4df7-8343-5bfc9d1905c4', 'a-(ii), b-(iv), c-(i), d-(iii)', false, 'fb279dec-246f-441f-9105-2fcdca3e9284');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f72e418e-1ba7-44e3-af6a-1622dd9f85fb', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a262ae13-4f2c-448c-bc43-3760319160ae', 'Statements 1 and 2 only', true, 'f72e418e-1ba7-44e3-af6a-1622dd9f85fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbd79744-4f89-48cc-8e70-b6019c1e8f4d', 'Statements 2 and 3 only', false, 'f72e418e-1ba7-44e3-af6a-1622dd9f85fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3267b68c-4219-4c32-8d15-043ebd03b63a', 'Statements 1 and 3 only', false, 'f72e418e-1ba7-44e3-af6a-1622dd9f85fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f79ebed-cc2b-43e5-8497-72f65a9adf40', 'All Statements 1, 2, and 3', false, 'f72e418e-1ba7-44e3-af6a-1622dd9f85fb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab83c002-dbc6-4387-bded-0977b53c42cb', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Town X is located at 30° East longitude and Town Y is located at 60° West longitude. What is the total time difference between Town X and Town Y?', 'Longitudinal separation = 30° + 60° = 90°. Time difference = 90 × 4 min = 360 minutes = 6 hours.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab2c1df1-635f-41fb-93fd-061889b90c0e', '6 hours (90° total difference × 4 min = 360 min)', true, 'ab83c002-dbc6-4387-bded-0977b53c42cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('220b0d7b-73a3-4eb8-bce6-bd3653143d7b', '2 hours', false, 'ab83c002-dbc6-4387-bded-0977b53c42cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb327276-38e4-4306-9325-59025074cc53', '4 hours', false, 'ab83c002-dbc6-4387-bded-0977b53c42cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ea8ea19-e374-4d55-8efb-a7a64ffe0e24', '8 hours', false, 'ab83c002-dbc6-4387-bded-0977b53c42cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('904e4c44-db36-43c9-b8df-1938039e6360', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Why did India adopt ONE single Standard Time (IST) across the entire country instead of multiple local time zones?', 'A uniform national reference meridian (82.5° E) harmonizes logistical schedules across transport, administration, and commerce.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12fe50f5-71c8-470f-b581-f1f1161f800a', 'To avoid immense confusion in nationwide railway timetables, flights, banking, and television broadcasts', true, '904e4c44-db36-43c9-b8df-1938039e6360');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41a8f0aa-c226-4526-a572-0e3821c021f6', 'Because India is only 1 km wide', false, '904e4c44-db36-43c9-b8df-1938039e6360');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df17691d-453e-4fa6-b89b-49511432348a', 'Because clocks cannot be changed', false, '904e4c44-db36-43c9-b8df-1938039e6360');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe15f8b0-a567-4644-a04c-64dbc338f203', 'Because the Sun rises at the same minute across India', false, '904e4c44-db36-43c9-b8df-1938039e6360');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b9b85da7-4d35-4da8-bd9c-b3320b4a1492', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Both Tonga Islands (in Pacific Ocean) and Mauritius Islands (in Indian Ocean) are situated on 20° S latitude. How do navigators distinguish their exact positions?', 'A 2D coordinate fix requires BOTH latitude (Y-axis parallel) AND longitude (X-axis meridian) coordinates.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3d628f0-3221-47f8-88a2-012bbf907c87', 'By referencing their specific longitudes (East or West of the Prime Meridian)', true, 'b9b85da7-4d35-4da8-bd9c-b3320b4a1492');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb55be7d-a16c-4263-842c-e2c4290aedfb', 'By looking at ocean waves', false, 'b9b85da7-4d35-4da8-bd9c-b3320b4a1492');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94a64822-8f3b-4eae-9375-c4a65f3900bb', 'By measuring air temperature only', false, 'b9b85da7-4d35-4da8-bd9c-b3320b4a1492');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b7b364c-b92f-4813-bfa6-6177bd885549', 'They cannot be distinguished', false, 'b9b85da7-4d35-4da8-bd9c-b3320b4a1492');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('efe91923-90d9-4d55-b884-836eab20a566', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'What is the key difference between the Torrid Zone and the Frigid Zone regarding insolation?', 'Lambert''s cosine law: vertical rays deliver concentrated flux per unit area, while acute slanting rays dilute radiative heating.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d26edd59-d1c4-4d69-a1b9-84af10cb1591', 'Torrid Zone receives direct vertical solar rays with high energy density; Frigid Zone receives oblique slanting rays spread over vast areas with severe reflection', true, 'efe91923-90d9-4d55-b884-836eab20a566');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b21659c-7c24-479d-92ae-51839298ec13', 'Torrid Zone has no night', false, 'efe91923-90d9-4d55-b884-836eab20a566');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('898370fa-8545-422b-9b20-13e1a9737c18', 'Frigid Zone is closer to the Sun', false, 'efe91923-90d9-4d55-b884-836eab20a566');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c526a1c0-570f-4276-a50d-950dedc70102', 'Torrid Zone is in outer space', false, 'efe91923-90d9-4d55-b884-836eab20a566');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91688995-937d-431f-bea7-af79dbfc5e28', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'Which of the following continents does the Equator, Tropic of Cancer, AND Tropic of Capricorn ALL pass through?', 'Africa is the only continent on Earth traversed by all three primary latitude lines: Cancer (N), Equator, and Capricorn (S).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06aab02b-c4bd-4625-948a-11351bc69cf2', 'Africa', true, '91688995-937d-431f-bea7-af79dbfc5e28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c36d3ba6-353b-4470-a9be-a90355994b05', 'Asia', false, '91688995-937d-431f-bea7-af79dbfc5e28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('271db745-8644-4535-acec-f40089a23f64', 'South America', false, '91688995-937d-431f-bea7-af79dbfc5e28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d0988fd-92af-4c6f-912e-f3e4e28e651b', 'Australia', false, '91688995-937d-431f-bea7-af79dbfc5e28');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a938606-e1f3-4bba-94e9-044b40f4f71c', 'Class 6', 'Social Science', 'Chapter 2: Globe: Latitudes and Longitudes', 'Hard', 'If a traveler crosses the 180° International Date Line traveling from West to East (e.g. from Japan to USA), what calendar adjustment must they make?', 'Crossing eastward into the Western Hemisphere steps back across the antimeridian, repeating that calendar date.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bf3b0df-dba9-4628-b885-243eda54ffdd', 'They repeat one calendar day (gain a day / subtract 24 hours from date)', true, '1a938606-e1f3-4bba-94e9-044b40f4f71c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b331f2c-b4b0-45c4-b268-99a0e882dcfd', 'They lose one calendar day (add 24 hours)', false, '1a938606-e1f3-4bba-94e9-044b40f4f71c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce3817ca-3df3-4ce7-8685-3f08856a8089', 'Clocks stop working', false, '1a938606-e1f3-4bba-94e9-044b40f4f71c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c18ac1a2-8e35-4414-9f19-35359b12eb03', 'They travel 100 years into the future', false, '1a938606-e1f3-4bba-94e9-044b40f4f71c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49f58d71-d8c6-4517-a670-b2c54cea4183', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'भाषा की वह सबसे छोटी मूल ध्वनि जिसके और टुकड़े (खंड) नहीं किए जा सकते, उसे क्या कहते हैं?', 'वर्ण (जैसे अ, आ, क, ख) भाषा की अविभाज्य लघुतम इकाई है जिसके खंड नहीं किए जा सकते।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('335f2aad-4508-4947-bb4a-cda5c4147c8b', 'वर्ण या अक्षर (Letter / Phoneme)', true, '49f58d71-d8c6-4517-a670-b2c54cea4183');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5985417a-30ba-4eed-8190-a7d2d6abf8fb', 'शब्द', false, '49f58d71-d8c6-4517-a670-b2c54cea4183');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ceb74322-182b-4085-a3cd-fa6d104d96fa', 'वाक्य', false, '49f58d71-d8c6-4517-a670-b2c54cea4183');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d636de6e-4e2b-4167-ae57-022bf2e8457d', 'पद', false, '49f58d71-d8c6-4517-a670-b2c54cea4183');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9fbf3b2d-15eb-4914-be01-83fb16b8a3ae', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'वर्णों के व्यवस्थित और क्रमबद्ध समूह को क्या कहते हैं?', 'वर्णों का मानक क्रमबद्ध एवं व्यवस्थित समूह ''वर्णमाला'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53ecb78c-20fb-48fa-86a3-cb0b5380887c', 'वर्णमाला (Alphabet)', true, '9fbf3b2d-15eb-4914-be01-83fb16b8a3ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bb03a53-4d71-4b52-bded-a6010c5829c9', 'शब्दकोश', false, '9fbf3b2d-15eb-4914-be01-83fb16b8a3ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3470ebae-db58-4a18-8ce9-34c479b95128', 'वाक्य', false, '9fbf3b2d-15eb-4914-be01-83fb16b8a3ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('418b928e-67dd-4d4a-a5c6-6d8b45758d05', 'व्याकरण', false, '9fbf3b2d-15eb-4914-be01-83fb16b8a3ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b609bcb8-6fac-46f4-95f9-830e46b5009b', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'हिंदी वर्णमाला में वर्णों को मुख्य रूप से कितने भागों (भेदों) में बाँटा गया है?', 'हिंदी वर्णमाला के मुख्य दो भेद हैं: 1. स्वर (Vowels) तथा 2. व्यंजन (Consonants)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4a9da06-0784-4d79-b9ab-e8b16155480e', 'दो भागों में (स्वर और व्यंजन)', true, 'b609bcb8-6fac-46f4-95f9-830e46b5009b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('229b179a-bcab-4654-8911-cca3ce0cc29a', 'तीन भागों में', false, 'b609bcb8-6fac-46f4-95f9-830e46b5009b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b79f17d3-27eb-49f6-a670-984243a400ed', 'चार भागों में', false, 'b609bcb8-6fac-46f4-95f9-830e46b5009b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b70276aa-abe1-4c5c-aee7-1097639ef737', 'पाँच भागों में', false, 'b609bcb8-6fac-46f4-95f9-830e46b5009b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f388e804-909a-47d3-b50d-4bea42c109fc', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'जिन वर्णों का उच्चारण स्वतंत्र रूप से बिना किसी अन्य वर्ण की सहायता से होता है, उन्हें क्या कहते हैं?', 'स्वर निर्बाध एवं स्वतंत्र रूप से उच्चरित होने वाली ध्वनियाँ हैं (अ, आ, इ, ई, उ, ऊ, ऋ, ए, ऐ, ओ, औ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1cca79d-e978-4b3c-85d7-fe6ce0a8045e', 'स्वर (Vowels)', true, 'f388e804-909a-47d3-b50d-4bea42c109fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc4ccdbd-51d6-4f3f-b9a9-b52a9aa63e27', 'व्यंजन', false, 'f388e804-909a-47d3-b50d-4bea42c109fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28991d0a-df7e-4ed2-a7fa-f36af78e2a6f', 'संयुक्त व्यंजन', false, 'f388e804-909a-47d3-b50d-4bea42c109fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82bb46af-8323-49d9-a218-d6e9e546ee48', 'अयोगवाह', false, 'f388e804-909a-47d3-b50d-4bea42c109fc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('602a9179-d91a-441c-8db4-330f958b1355', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'मानक हिंदी वर्णमाला में कुल कितने मूल स्वर (Vowels) होते हैं?', 'हिंदी वर्णमाला में 11 स्वर होते हैं: अ, आ, इ, ई, उ, ऊ, ऋ, ए, ऐ, ओ, औ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2ce0e00-50f4-4827-afd0-41d9b1fb270c', '11 स्वर', true, '602a9179-d91a-441c-8db4-330f958b1355');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1d01345-4a26-4dde-88a9-339bff909e7b', '13 स्वर', false, '602a9179-d91a-441c-8db4-330f958b1355');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('461d94e6-ab39-4a25-8755-a2a54c02d514', '10 स्वर', false, '602a9179-d91a-441c-8db4-330f958b1355');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('438b386f-b1a3-49a0-b1ae-c3160629846d', '12 स्वर', false, '602a9179-d91a-441c-8db4-330f958b1355');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ce703c09-c31f-4383-955a-e504f0f587ae', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'जिन वर्णों का उच्चारण स्वरों की सहायता से किया जाता है, उन्हें क्या कहते हैं?', 'व्यंजनों के पूर्ण उच्चारण हेतु स्वर (मुख्यतः ''अ'') का संयोग अनिवार्य होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e159100-504e-4336-98e7-787d51f3e83e', 'व्यंजन (Consonants)', true, 'ce703c09-c31f-4383-955a-e504f0f587ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6687b2af-df17-4455-b161-d5ac7733babf', 'स्वर', false, 'ce703c09-c31f-4383-955a-e504f0f587ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa167a48-9743-4130-8642-4a3270dcbf90', 'मात्रा', false, 'ce703c09-c31f-4383-955a-e504f0f587ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b5780a0-b913-4928-bb25-888106c82c26', 'अनुस्वार', false, 'ce703c09-c31f-4383-955a-e504f0f587ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3f51694-721f-41c2-8d44-68f9e23c41f4', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'उच्चारण में लगने वाले समय (मात्रा) के आधार पर स्वर के कितने भेद होते हैं?', 'मात्रा काल के आधार पर स्वर तीन प्रकार के होते हैं: ह्रस्व (1 मात्रा), दीर्घ (2 मात्रा), तथा प्लुत (3 मात्रा)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7b21404-bcfe-4ffa-8d4d-2f96b7bef626', 'तीन भेद (ह्रस्व स्वर, दीर्घ स्वर, प्लुत स्वर)', true, 'd3f51694-721f-41c2-8d44-68f9e23c41f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e774069-cc81-4f9c-b397-8db9e82d02f2', 'दो भेद', false, 'd3f51694-721f-41c2-8d44-68f9e23c41f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63243131-39ae-4142-8a91-d34d4f44dc0f', 'चार भेद', false, 'd3f51694-721f-41c2-8d44-68f9e23c41f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e3011b0-b542-4ac5-915f-3303222efe09', 'पाँच भेद', false, 'd3f51694-721f-41c2-8d44-68f9e23c41f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1dd6f2d2-7d71-4251-8fbe-54bd3fc99c46', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'हिंदी वर्णमाला में ह्रस्व स्वर (Short Vowels) कुल कितने हैं?', 'ह्रस्व स्वर (मूल स्वर) जिनके उच्चारण में न्यूनतम एक मात्रा का समय लगता है, संख्या में 4 हैं: अ, इ, उ, ऋ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5292b66a-59eb-48fa-b4f5-acc9661ca5e7', 'चार (अ, इ, उ, ऋ)', true, '1dd6f2d2-7d71-4251-8fbe-54bd3fc99c46');
