INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('502c6398-1245-4e44-b796-fa88c17a93eb', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'हिंदी वर्णमाला में दीर्घ स्वर (Long Vowels) कुल कितने हैं?', 'दीर्घ स्वर जिनके उच्चारण में ह्रस्व से दोगुना समय लगता है, संख्या में 7 हैं: आ, ई, ऊ, ए, ऐ, ओ, औ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc93b10b-fdeb-4725-9578-eaa9fe14c018', 'सात (आ, ई, ऊ, ए, ऐ, ओ, औ)', true, '502c6398-1245-4e44-b796-fa88c17a93eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c77b23b9-0ba8-4702-8922-089ce62d7e76', 'चार', false, '502c6398-1245-4e44-b796-fa88c17a93eb');
