INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('813939df-6f32-4ab3-bc94-17211d7cf140', 'पाँच', false, '502c6398-1245-4e44-b796-fa88c17a93eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dbde65aa-9b2e-48e2-8c42-9ba77bfaf074', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'अं (ं) और अः (ः) को हिंदी व्याकरण में क्या कहा जाता है?', 'अं (अनुस्वार) और अः (विसर्ग) न तो पूर्ण स्वर हैं और न पूर्ण व्यंजन; अतः इन्हें ''अयोगवाह'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5dd4af2-e7c0-46d8-850e-7c4313aef221', 'अयोगवाह (अनुस्वार और विसर्ग)', true, 'dbde65aa-9b2e-48e2-8c42-9ba77bfaf074');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40700f7b-7401-465b-89df-1e728203f624', 'मूल स्वर', false, 'dbde65aa-9b2e-48e2-8c42-9ba77bfaf074');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3532ad2a-e398-409b-a459-3b22d3ec59b7', 'स्पर्श व्यंजन', false, 'dbde65aa-9b2e-48e2-8c42-9ba77bfaf074');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca69f754-fe0a-46de-acdf-85a01a3de459', 'अन्तःस्थ व्यंजन', false, 'dbde65aa-9b2e-48e2-8c42-9ba77bfaf074');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ff3c746-f477-4cf6-a5a6-4a9225647bcc', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'हिंदी में संयुक्त व्यंजन (क्ष, त्र, ज्ञ, श्र) की कुल संख्या कितनी है?', 'दो भिन्न व्यंजनों के परस्पर मेल से बनने वाले 4 संयुक्त व्यंजन हैं: क्ष (क्+ष), त्र (त्+र), ज्ञ (ज्+ञ), श्र (श्+र)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32bce76c-acd1-4de0-ab94-3926d686b1a8', 'चार (4 संयुक्त व्यंजन)', true, '3ff3c746-f477-4cf6-a5a6-4a9225647bcc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63809f8c-be20-4eae-a1b4-cabde3013c8f', 'तीन', false, '3ff3c746-f477-4cf6-a5a6-4a9225647bcc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40a53424-f818-4994-aba0-d3921585082c', 'पाँच', false, '3ff3c746-f477-4cf6-a5a6-4a9225647bcc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('763350da-d12a-44f4-924b-7bedf1d442bd', 'दो', false, '3ff3c746-f477-4cf6-a5a6-4a9225647bcc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a4ad9ad-e863-4f09-8a51-9b2163b274b5', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Easy', 'स्वरों के जो निश्चित चिह्न व्यंजनों के साथ जोड़े जाते हैं, उन्हें क्या कहते हैं?', 'व्यंजनों के साथ प्रयुक्त होने वाले स्वरों के प्रतीकात्मक लिखित चिह्नों को ''मात्रा'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e841ed2-79cc-44e0-a6e1-b66af5e119eb', 'मात्रा (Matra)', true, '1a4ad9ad-e863-4f09-8a51-9b2163b274b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dac9f37-dca0-4354-9561-5eeea3dc3ecc', 'वर्ण', false, '1a4ad9ad-e863-4f09-8a51-9b2163b274b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb4d22da-7485-4e98-88b8-26f6a072867a', 'ध्वनि', false, '1a4ad9ad-e863-4f09-8a51-9b2163b274b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a438103-e5b1-4bac-8bc6-44f20f61a0c2', 'हलंत', false, '1a4ad9ad-e863-4f09-8a51-9b2163b274b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d0d04e7-3955-475b-87cf-bc4884b062a4', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'संयुक्त व्यंजन ''क्ष'' किन दो वर्णों के संयोग से बनता है?', 'क् + ष् = क्ष (जैसे: कक्षा, क्षत्रिय, रक्षा)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e3ea2a6-298f-4428-8361-9f8058cdeff1', 'क् + ष् + अ', true, '5d0d04e7-3955-475b-87cf-bc4884b062a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffb66f62-b0d2-4320-8a21-55cbd2c6d3a9', 'क् + छ् + अ', false, '5d0d04e7-3955-475b-87cf-bc4884b062a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a42aa89-9ada-4d8c-b106-136256246ab1', 'क् + स् + अ', false, '5d0d04e7-3955-475b-87cf-bc4884b062a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6620903d-ac4f-4d5a-8802-1864212fcea4', 'ख् + श् + अ', false, '5d0d04e7-3955-475b-87cf-bc4884b062a4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4dbd9987-7f33-4d6f-a515-f4ecb201bcf0', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'संयुक्त व्यंजन ''ज्ञ'' किन दो वर्णों के संयोग से बनता है?', 'ज् + ञ् = ज्ञ (जैसे: ज्ञान, ज्ञानी, अज्ञात)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2140742-115f-4d08-bcb7-59fd084b30da', 'ज् + ञ् + अ', true, '4dbd9987-7f33-4d6f-a515-f4ecb201bcf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17844a4d-26e6-48a0-83f3-a5a5a991bb5a', 'ग् + य् + अ', false, '4dbd9987-7f33-4d6f-a515-f4ecb201bcf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('177146bc-d3d2-48ce-9d2f-20345f424a4e', 'ग् + न् + अ', false, '4dbd9987-7f33-4d6f-a515-f4ecb201bcf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dfd74bf-1327-4ee6-a5c0-65770a33d634', 'द् + य् + अ', false, '4dbd9987-7f33-4d6f-a515-f4ecb201bcf0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecb6470d-d1e4-4758-af62-b7a966a34481', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'संयुक्त व्यंजन ''त्र'' और ''श्र'' क्रमशः किन वर्णों के संयोग से बनते हैं?', 'त् + र् = त्र (छात्र, पत्र) तथा श् + र् = श्र (श्रम, विश्राम)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ad6ab9e-ce3f-4907-a9bb-c083c6431479', 'त्र = त् + र् + अ ; श्र = श् + र् + अ', true, 'ecb6470d-d1e4-4758-af62-b7a966a34481');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26835cd8-7721-4b1e-aad3-0e837c76b07e', 'त्र = ट् + र् ; श्र = स् + र्', false, 'ecb6470d-d1e4-4758-af62-b7a966a34481');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66360d74-edc2-443c-94ad-c018ccda8c00', 'त्र = थ् + र् ; श्र = ष् + र्', false, 'ecb6470d-d1e4-4758-af62-b7a966a34481');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef413fd4-35d4-4a1b-a03c-cdb141c12721', 'त्र = त् + ऋ ; श्र = श् + ऋ', false, 'ecb6470d-d1e4-4758-af62-b7a966a34481');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff2fa3ad-8682-43dd-b5c1-272342214f61', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'स्पर्श व्यंजन (क से म तक) कुल कितने होते हैं और इन्हें कितने वर्गों में बाँटा गया है?', 'क-वर्ग से प-वर्ग तक 5×5 = 25 स्पर्श व्यंजन होते हैं जिनका उच्चारण जिह्वा के मुख-स्थान स्पर्श से होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('736bde75-8733-4033-9a3a-1e995308ff33', '25 स्पर्श व्यंजन, 5 वर्गों में (क-वर्ग, च-वर्ग, ट-वर्ग, त-वर्ग, प-वर्ग)', true, 'ff2fa3ad-8682-43dd-b5c1-272342214f61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('430d5715-98a3-4f82-9a0e-ef7743e73ece', '20 स्पर्श व्यंजन, 4 वर्गों में', false, 'ff2fa3ad-8682-43dd-b5c1-272342214f61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3da5df1-d5e8-475e-9bac-1e9e90457c09', '33 स्पर्श व्यंजन, 6 वर्गों में', false, 'ff2fa3ad-8682-43dd-b5c1-272342214f61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9066cde4-6ce2-46f2-a8f1-8aa43c7ea970', '15 स्पर्श व्यंजन, 3 वर्गों में', false, 'ff2fa3ad-8682-43dd-b5c1-272342214f61');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c823eed-595a-4ce1-8f22-76f08dbe04ae', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'अन्तःस्थ व्यंजन (Semivowels) कौन-से चार वर्ण होते हैं?', 'य, र, ल, व का उच्चारण स्वर और व्यंजन के मध्यवर्ती (अन्तःस्थ) रूप में होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('233fe197-a0b0-447d-9e24-d708f851890a', 'य, र, ल, व', true, '0c823eed-595a-4ce1-8f22-76f08dbe04ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8894de5f-a991-4c11-a0d4-a9026b126e81', 'श, ष, स, ह', false, '0c823eed-595a-4ce1-8f22-76f08dbe04ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a027a26e-8f7b-4c9e-8760-7c750d2752cd', 'क, ख, ग, घ', false, '0c823eed-595a-4ce1-8f22-76f08dbe04ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17a74f7e-3e0b-4f90-851d-270788802cb7', 'क्ष, त्र, ज्ञ, श्र', false, '0c823eed-595a-4ce1-8f22-76f08dbe04ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8bdd83ee-00a1-4265-87ab-bb52f1c77649', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'ऊष्म व्यंजन (Sibilants) कौन-से चार वर्ण होते हैं जिनके उच्चारण में मुख से ऊष्मा (गर्म हवा) निकलती है?', 'श (तालव्य), ष (मूर्धन्य), स (दंत्य), ह (कंठ्य/काकल्य) के घर्षण जनित उच्चारण से वायु ऊष्मित होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8c341db-bfdf-407c-ae89-3f17c2065e60', 'श, ष, स, ह', true, '8bdd83ee-00a1-4265-87ab-bb52f1c77649');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93ca3a82-25bf-44cf-aace-b3bf2a5190e1', 'य, र, ल, व', false, '8bdd83ee-00a1-4265-87ab-bb52f1c77649');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9918ff3a-8f6e-48fa-849d-b5aa43db44ac', 'क, च, ट, त', false, '8bdd83ee-00a1-4265-87ab-bb52f1c77649');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3de4150e-1c62-4201-a959-d49db9e3679d', 'ड़, ढ़, अं, अः', false, '8bdd83ee-00a1-4265-87ab-bb52f1c77649');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('107236c8-9096-4c12-90e0-7c9f0ece5d3a', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'जब एक ही व्यंजन ध्वनि अपने ही समान व्यंजन ध्वनि से संयुक्त होती है (जैसे: पक्का, बिल्ली, दिल्ली), तो उसे क्या कहते हैं?', 'समान व्यंजनों का परस्पर युग्मन ''द्वित्व व्यंजन'' कहलाता है (क्+क = क्क, ल्+ल = ल्ल)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('878d766c-78b1-4a3c-8758-05082b8b0289', 'द्वित्व व्यंजन (Geminate Consonants)', true, '107236c8-9096-4c12-90e0-7c9f0ece5d3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f95cda7-cddf-4a95-8e8a-290a3811189d', 'संयुक्त व्यंजन', false, '107236c8-9096-4c12-90e0-7c9f0ece5d3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43dab52e-eecf-490d-954d-ffca05188f70', 'संयुक्ताक्षर', false, '107236c8-9096-4c12-90e0-7c9f0ece5d3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('248a2b9d-c82a-4759-8cdf-645a2f5abdbf', 'अन्तःस्थ व्यंजन', false, '107236c8-9096-4c12-90e0-7c9f0ece5d3a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('65f0d111-6a5f-4b05-9f4e-2a355dad7f3d', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'जब दो अलग-अलग व्यंजन परस्पर जुड़ते हैं (जैसे: विद्या, स्थान, पुस्तक), तो उन्हें क्या कहते हैं?', 'दो भिन्न व्यंजनों का स्वर-रहित मेल ''संयुक्ताक्षर'' कहलाता है (स्+थ = स्थ, स्+त = स्त)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('135960c3-7b37-450f-9054-556748a1734f', 'संयुक्ताक्षर (Conjunct Consonants)', true, '65f0d111-6a5f-4b05-9f4e-2a355dad7f3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e11bc96-68e0-4302-9009-149e7e62de85', 'द्वित्व व्यंजन', false, '65f0d111-6a5f-4b05-9f4e-2a355dad7f3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a59d6791-3101-4481-8747-a5832b8420d8', 'ह्रस्व स्वर', false, '65f0d111-6a5f-4b05-9f4e-2a355dad7f3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47bac0ab-a45a-4ae9-ab69-7d892ce93217', 'विसर्ग', false, '65f0d111-6a5f-4b05-9f4e-2a355dad7f3d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55c8ebb7-8555-4b6a-b88d-90373c2675a7', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'हिंदी वर्णमाला में किस स्वर की अपनी कोई लिखित मात्रा नहीं होती?', '''अ'' स्वर प्रत्येक अ-कारान्त व्यंजन में अंतर्निहित होता है; इसका कोई अलग मात्रा चिह्न नहीं होता।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d44d121-7976-4666-b11c-0ef1d2fe8b50', '''अ'' स्वर', true, '55c8ebb7-8555-4b6a-b88d-90373c2675a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f92b65c-b5bb-4dad-9f7c-5f34156bea5b', '''आ'' स्वर', false, '55c8ebb7-8555-4b6a-b88d-90373c2675a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd5a92a6-1669-45b7-ab2f-141c5f35f603', '''इ'' स्वर', false, '55c8ebb7-8555-4b6a-b88d-90373c2675a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef4efed9-85a1-4894-b5e1-42daf58e3c26', '''ऋ'' स्वर', false, '55c8ebb7-8555-4b6a-b88d-90373c2675a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34e1acce-88eb-4646-b954-08cad411c84e', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'अनुनासिक (ँ - चंद्रबिंदु) का उच्चारण मुख और नाक में किस प्रकार होता है?', 'अनुनासिक स्वरों की वायु उच्चारण के समय मुख और नासिका दोनों से एक साथ निःसृत होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee174df3-3a0e-4c95-ba0c-23a64c21686f', 'इसका उच्चारण मुख और नासिका दोनों की सहायता से एक साथ होता है (जैसे: आँख, चाँद, गाँव)', true, '34e1acce-88eb-4646-b954-08cad411c84e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97fc7b5d-aff0-498d-99b6-9a26b35aa118', 'केवल नाक से होता है', false, '34e1acce-88eb-4646-b954-08cad411c84e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('830ce8a6-a4b6-4f39-b98d-686a10528932', 'केवल गले से होता है', false, '34e1acce-88eb-4646-b954-08cad411c84e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8777f8df-223b-4fb4-a6e2-8c96f01c8b6e', 'केवल होंठों से होता है', false, '34e1acce-88eb-4646-b954-08cad411c84e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c303bc27-3c96-40f9-af02-ea27ea90ae9d', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'अनुस्वार (ं - बिंदु) का उच्चारण किसकी सहायता से होता है?', 'अनुस्वार नासिक्य व्यंजन ध्वनि है जो पंचमाक्षरों (पंत, गंगा, चंचल) के स्थानापन्न प्रयुक्त होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5942f766-3a4e-466c-8344-f0a5bd8a22e0', 'इसका उच्चारण केवल नासिका (नाक) से होता है और यह प्रत्येक वर्ग के पंचम वर्ण (ङ, ञ, ण, न, म) के स्थान पर आता है', true, 'c303bc27-3c96-40f9-af02-ea27ea90ae9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7aadfce4-9b26-42f5-9aa2-e78fc23bf00b', 'केवल होंठों से', false, 'c303bc27-3c96-40f9-af02-ea27ea90ae9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe7aee6a-17b0-467c-876a-987a48441145', 'केवल दाँतों से', false, 'c303bc27-3c96-40f9-af02-ea27ea90ae9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab2c6066-e732-44c4-8afb-e2d618cee097', 'केवल जीभ से', false, 'c303bc27-3c96-40f9-af02-ea27ea90ae9d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cfc98987-84a4-49b2-9235-6b366bf4081d', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'विसर्ग (ः) का उच्चारण किस ध्वनि के समान हल्का और फुसफुसाहट भरा होता है?', 'संस्कृत मूल के विसर्ग (ः) का उच्चारण अघोष काकल्य ध्वनि /h/ (ह्) के सदृश होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('332996b9-b973-4136-9e35-070840019ef9', '''ह्'' ध्वनि के समान (जैसे: प्रातः, अतः, नमः)', true, 'cfc98987-84a4-49b2-9235-6b366bf4081d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('434a8469-9001-454c-bceb-bacb66a1f302', '''म्'' ध्वनि के समान', false, 'cfc98987-84a4-49b2-9235-6b366bf4081d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e65c6275-3454-48fc-a964-25aa4c2d087c', '''न्'' ध्वनि के समान', false, 'cfc98987-84a4-49b2-9235-6b366bf4081d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9850715b-5756-4a80-ac50-8a08ab801101', '''स्'' ध्वनि के समान', false, 'cfc98987-84a4-49b2-9235-6b366bf4081d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa1c6c7f-4986-4872-97a1-db636bf9c809', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'क-वर्ग (क, ख, ग, घ, ङ) का उच्चारण स्थान मुख का कौन-सा भाग है?', 'क-वर्ग के वर्ण कंठ्य (Throat/Velar) ध्वनियाँ कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28cc0fe8-e94e-4fb1-bc68-1b256bdcaf1a', 'कंठ (गला / Velar)', true, 'fa1c6c7f-4986-4872-97a1-db636bf9c809');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edaf9f62-6745-4202-9005-0ed1353cf692', 'तालु', false, 'fa1c6c7f-4986-4872-97a1-db636bf9c809');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('890713ad-1e8a-4e2a-bb49-772922c82278', 'मूर्धा', false, 'fa1c6c7f-4986-4872-97a1-db636bf9c809');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2b7cacb-6a8a-4fd8-9bd5-24d0f9df64e4', 'दाँत', false, 'fa1c6c7f-4986-4872-97a1-db636bf9c809');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('581ae614-ffeb-43af-b767-88e671b2a3ab', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'च-वर्ग (च, छ, ज, झ, ञ) तथा इ, ई, य, श का उच्चारण स्थान क्या है?', 'जिह्वा तालु के कठोर भाग को स्पर्श करती है, अतः ये ''तालव्य'' वर्ण कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4b008e0-9bbb-4f9b-b837-b7c5b9e73b86', 'तालु (तालव्य / Palatal)', true, '581ae614-ffeb-43af-b767-88e671b2a3ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77b50227-f2da-4261-90f9-61db63ff6112', 'ओष्ठ', false, '581ae614-ffeb-43af-b767-88e671b2a3ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d36bdcd7-6ce5-41bc-a7ec-9ef15e23cde9', 'दंत', false, '581ae614-ffeb-43af-b767-88e671b2a3ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10a62fa5-13f9-4618-8336-de2ce46f424c', 'मूर्धा', false, '581ae614-ffeb-43af-b767-88e671b2a3ab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c70c2d26-456c-4d94-a766-8b9dd7642f04', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'प-वर्ग (प, फ, ब, भ, म) तथा उ, ऊ का उच्चारण स्थान क्या है?', 'दोनों होंठों के परस्पर मिलन से उच्चरित होने के कारण इन्हें ''ओष्ठ्य'' वर्ण कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5831746d-5462-4b97-b837-386069a465fa', 'ओष्ठ (ओष्ठ्य / Labial - दोनों होंठ)', true, 'c70c2d26-456c-4d94-a766-8b9dd7642f04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e2ea1fa-a4b7-4a03-8faf-466032467d3a', 'कंठ', false, 'c70c2d26-456c-4d94-a766-8b9dd7642f04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a1a9b7e-debf-45f1-b698-791d46cf8d31', 'तालु', false, 'c70c2d26-456c-4d94-a766-8b9dd7642f04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72aaf21b-ef70-432d-a564-ef3f7cf3730a', 'दंत', false, 'c70c2d26-456c-4d94-a766-8b9dd7642f04');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('012b1480-5d87-4738-99fa-c96c2e4eac1b', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Medium', 'ड़ और ढ़ को हिंदी में कौन-से व्यंजन कहा जाता है?', 'ड़ और ढ़ उत्क्षिप्त (ताड़नजात) वर्ण हैं, जिनका उच्चारण जिह्वा को झटके से नीचे गिराकर किया जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('532d54c4-a511-49d8-89f1-bf2be7524302', 'उत्क्षिप्त या विकसित अतिरिक्त व्यंजन (Flap Consonants)', true, '012b1480-5d87-4738-99fa-c96c2e4eac1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64e0d572-1c07-4ca2-96df-d229e64803f5', 'मूल स्वर', false, '012b1480-5d87-4738-99fa-c96c2e4eac1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0517490b-7548-4247-ad90-386d7950b48a', 'ऊष्म व्यंजन', false, '012b1480-5d87-4738-99fa-c96c2e4eac1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3ef5a3b-d39c-4fed-92f3-8e7973009448', 'संयुक्त व्यंजन', false, '012b1480-5d87-4738-99fa-c96c2e4eac1b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4256c472-9a77-4449-8b31-5b0a83d2e0ca', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('027a3d3a-06d3-4463-acfb-3c62cc273cce', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '4256c472-9a77-4449-8b31-5b0a83d2e0ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ca2a8f0-c2cc-40eb-b325-182bdb50b42f', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '4256c472-9a77-4449-8b31-5b0a83d2e0ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5cab80a-6131-44a6-9fa7-2c588b7273f5', '(A) सही है, परन्तु (R) गलत है।', false, '4256c472-9a77-4449-8b31-5b0a83d2e0ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a195fc77-a563-4e94-af2e-4c854b08b004', '(A) गलत है, परन्तु (R) सही है।', false, '4256c472-9a77-4449-8b31-5b0a83d2e0ca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61532942-8529-4cd3-aec7-2332c9ebbf2f', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'वर्ण-विच्छेद (Phonetic Decomposition) की दृष्टि से ''विद्यार्थी'' शब्द का सही विच्छेद कौन-सा है?', 'वि-द्या-र्-थी = (व्+इ) + (द्+य्+आ) + (र्+थ्+ई)। रेफ (र्) थ से पूर्व उच्चरित होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('944be381-afbe-4a69-a07a-e98aa64c2ced', 'व् + इ + द् + य् + आ + र् + थ् + ई', true, '61532942-8529-4cd3-aec7-2332c9ebbf2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca2c610e-a326-443a-b7b3-797ad9906e00', 'व् + ई + द् + य् + आ + थ् + ई + र्', false, '61532942-8529-4cd3-aec7-2332c9ebbf2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a43b4fe-4620-45e1-90a4-9a654d8f6e95', 'व् + इ + द् + य् + आ + र् + थ् + इ', false, '61532942-8529-4cd3-aec7-2332c9ebbf2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be21c6d1-0844-44a6-a953-f19bae732588', 'व् + इ + द्या + र्थी', false, '61532942-8529-4cd3-aec7-2332c9ebbf2f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c14d70af-daa2-47e6-ad3b-040a250da315', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'Spot the IMPOSTER in the following group of वर्ण based on their उच्चारण स्थान:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('335c32e8-e0a4-4275-8125-dccb462996d6', 'क', false, 'c14d70af-daa2-47e6-ad3b-040a250da315');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6986323f-3d1e-4a7b-b5f0-8080888fbaca', 'ख', false, 'c14d70af-daa2-47e6-ad3b-040a250da315');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c7e88ad-f94e-4b3b-84c7-0b2342714035', 'ग', false, 'c14d70af-daa2-47e6-ad3b-040a250da315');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b31e89de-ff05-414c-a735-3c48781a93ae', 'च', true, 'c14d70af-daa2-47e6-ad3b-040a250da315');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('348aee8c-93a2-41ce-bc05-0e712646cd46', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'सुमेलित कीजिए (Match the Columns):
(क) क-वर्ग (क, ख, ग, घ) -> (i) मूर्धन्य
(ख) च-वर्ग (च, छ, ज, झ) -> (ii) ओष्ठ्य
(ग) ट-वर्ग (ट, ठ, ड, ढ) -> (iii) कंठ्य
(घ) प-वर्ग (प, फ, ब, भ) -> (iv) तालव्य', 'क-वर्ग = कंठ्य; च-वर्ग = तालव्य; ट-वर्ग = मूर्धन्य; प-वर्ग = ओष्ठ्य।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b7d2554-524f-4484-bb07-622c6e88b712', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', true, '348aee8c-93a2-41ce-bc05-0e712646cd46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e1aa42f-e9b9-44f4-b7b2-95451ec4bd47', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, '348aee8c-93a2-41ce-bc05-0e712646cd46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cee40e3-f28c-47d7-b3ba-18dc7292581d', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '348aee8c-93a2-41ce-bc05-0e712646cd46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c241b1e-9b1e-4fb4-addc-ce7e045317b9', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '348aee8c-93a2-41ce-bc05-0e712646cd46');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('918ba8dc-0232-432b-853e-4d70f585ad22', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', '''र'' के विभिन्न रूपों के संबंध में सही कथन चुनिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b1ac2f8-0c26-4cdf-887b-aaa101a967e1', 'सभी कथन 1, 2 और 3 सत्य हैं', true, '918ba8dc-0232-432b-853e-4d70f585ad22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8a3c86c-f183-4619-8342-d72ff1709066', 'कथन 1 और 2 केवल', false, '918ba8dc-0232-432b-853e-4d70f585ad22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3db5763-5189-4533-a850-37e65f3c254a', 'कथन 2 और 3 केवल', false, '918ba8dc-0232-432b-853e-4d70f585ad22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('128ff625-f473-4f40-aaa5-5c527e0c8a4e', 'कथन 1 और 3 केवल', false, '918ba8dc-0232-432b-853e-4d70f585ad22');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99f33336-4779-4be0-ae93-f130cabd8622', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'शब्द ''श्रृंगार'' अथवा ''कृष्ण'' में ''ऋ'' की मात्रा का सही वर्ण-विच्छेद क्या है?', '''कृ'' में व्यंजन ''क्'' के साथ ''ऋ'' स्वर जुड़ा है: क् + ऋ + ष् + ण् + अ = कृष्ण।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef419303-f8dd-4a9c-a84c-2eefc7e54882', 'कृष्ण = क् + ऋ + ष् + ण् + अ', true, '99f33336-4779-4be0-ae93-f130cabd8622');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d268eda-337b-46ed-abe3-1c1d7fb69b25', 'कृष्ण = क् + र् + इ + ष् + ण् + अ', false, '99f33336-4779-4be0-ae93-f130cabd8622');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25e4a32d-0185-42f3-bdb9-5c75b314c840', 'कृष्ण = क् + ऋ + ष् + ण्', false, '99f33336-4779-4be0-ae93-f130cabd8622');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a6b893b-2cfa-4bd9-8cf9-e91cd9f056a2', 'कृष्ण = क + ऋ + ष + ण', false, '99f33336-4779-4be0-ae93-f130cabd8622');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20113957-6463-4e3c-a4db-26e736828023', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'आगत ध्वनि ''ऑ'' (जैसे: डॉक्टर, कॉलेज, बॉल, कॉफी) किस विदेशी भाषा से हिंदी में समाहित हुई है?', 'अंग्रेज़ी के ''o'' स्वर के शुद्ध उच्चारण (Doctor, College) हेतु अर्ध-चंद्र ''ऑ'' आगत स्वर स्वीकृत किया गया है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7806d59d-62f5-4a51-be99-8b47a77fccf7', 'अंग्रेज़ी भाषा (English)', true, '20113957-6463-4e3c-a4db-26e736828023');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e2339ce-1f6a-4b3b-990b-a28fb261f7be', 'फारसी', false, '20113957-6463-4e3c-a4db-26e736828023');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f4d7e41-907c-4bda-a75e-8ed231a5efea', 'पुर्तगाली', false, '20113957-6463-4e3c-a4db-26e736828023');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ba00812-fc38-46d3-841f-d5c220eb1286', 'तुर्की', false, '20113957-6463-4e3c-a4db-26e736828023');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d95318c5-808f-4c92-9bbc-8b673c1c4056', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'नुक्ता (़) लगे आगत व्यंजन ''फ़'' और ''ज़'' (जैसे: फ़र्क, ज़माना) मुख्यतः किस भाषा से हिंदी में आए हैं?', 'अरबी-फारसी की ध्वनियों के शुद्ध उच्चारण हेतु वर्ण के नीचे अधोबिंदु (नुक्ता) लगाया जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee4c5a28-7fec-458b-af2b-0a4751854e68', 'अरबी और फारसी (Arabic & Persian)', true, 'd95318c5-808f-4c92-9bbc-8b673c1c4056');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('468e0126-ccde-49a0-9fe4-59cb3e511090', 'अंग्रेज़ी', false, 'd95318c5-808f-4c92-9bbc-8b673c1c4056');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3611ec5a-27a5-44bf-a54f-16bbd050b282', 'संस्कृत', false, 'd95318c5-808f-4c92-9bbc-8b673c1c4056');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adc92c9b-ef14-40c8-8212-e4700952509c', 'फ्रेंच', false, 'd95318c5-808f-4c92-9bbc-8b673c1c4056');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c25804f-1e8a-4a59-ab03-cb4b532119d9', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'अल्पप्राण और महाप्राण के वर्गीकरण में ''महाप्राण'' ध्वनियों की क्या विशेषता होती है?', 'महाप्राण (ख, घ, छ, झ, ठ, ढ, थ, ध, फ, भ + श, ष, स, ह) के उच्चारण में तीव्र उच्छ्वास प्राणवायु निकलती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5f37394-357c-4620-b9f0-a9c69e29e64c', 'इनके उच्चारण में अधिक श्वास वायु बाहर निकलती है और ''ह'' जैसी ध्वनि सुनाई देती है (प्रत्येक वर्ग का दूसरा और चौथा वर्ण तथा ऊष्म व्यंजन)', true, '9c25804f-1e8a-4a59-ab03-cb4b532119d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('defff1d1-9789-4553-968f-e59889b49d6e', 'इनमें बहुत कम हवा निकलती है', false, '9c25804f-1e8a-4a59-ab03-cb4b532119d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd217276-9a63-4c15-adbb-5c00513a0dd2', 'इनमें कोई आवाज़ नहीं होती', false, '9c25804f-1e8a-4a59-ab03-cb4b532119d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6011fe0-2070-4485-ae41-f7c2acd17e82', 'ये केवल रात में बोले जाते हैं', false, '9c25804f-1e8a-4a59-ab03-cb4b532119d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38f5cee7-2b57-4595-98b2-ba4343301330', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'अल्पप्राण (Non-aspirated) ध्वनियों के अंतर्गत कौन-से वर्ण आते हैं?', 'अल्पप्राण (क, ग, ङ, च, ज, ञ...) के उच्चारण में सीमित एवं सामान्य प्राणवायु प्रयुक्त होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f76bbc2-a3b4-49c3-a8b4-2c9bd16119e5', 'प्रत्येक वर्ग का पहला, तीसरा, पाँचवाँ वर्ण (1, 3, 5) तथा अन्तःस्थ व्यंजन (य, र, ल, व) एवं सभी स्वर', true, '38f5cee7-2b57-4595-98b2-ba4343301330');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('093b9c0c-1ec3-4b41-adca-9a5663beb316', 'दूसरा और चौथा वर्ण', false, '38f5cee7-2b57-4595-98b2-ba4343301330');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3038589-f1ee-41e9-96b8-52ed2121a917', 'केवल ऊष्म व्यंजन', false, '38f5cee7-2b57-4595-98b2-ba4343301330');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a86906a7-b9a1-4771-8706-e3d6ee85b6b1', 'केवल संयुक्त व्यंजन', false, '38f5cee7-2b57-4595-98b2-ba4343301330');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9eb8544-738a-48be-ba81-5031c317f992', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'प्लुत स्वर (जैसे: ''ओ३म्'' या किसी को दूर से पुकारने में) के उच्चारण में ह्रस्व स्वर की तुलना में कितना समय लगता है?', 'प्लुत स्वर त्रैमात्रिक होते हैं (३ चिह्न द्वारा दर्शाए जाते हैं), जो दीर्घ से भी अधिक समय तक उच्चरित होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bc00856-c7cc-4e6c-a3a4-9f5c0bb0ebc5', 'तीन गुना समय (तीन मात्राओं का काल)', true, 'a9eb8544-738a-48be-ba81-5031c317f992');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43cf4323-09a7-425d-96a6-ee93c98c8b25', 'दोगुना समय', false, 'a9eb8544-738a-48be-ba81-5031c317f992');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0896433c-2f11-4f6e-b355-4417df8381b1', 'बराबर समय', false, 'a9eb8544-738a-48be-ba81-5031c317f992');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d53e24c8-2dd0-458b-942d-4f5df097ca93', 'आधा समय', false, 'a9eb8544-738a-48be-ba81-5031c317f992');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('beac8db5-f9c9-448a-9d1e-07eb916ca64f', 'Class 6', 'Hindi Grammar', 'Chapter 2: वर्ण-विचार', 'Hard', 'निम्नलिखित में से मानक वर्तनी के अनुसार पंचमाक्षर के स्थान पर अनुस्वार का शुद्ध प्रयोग कौन-सा है?', 'केंद्रीय हिंदी निदेशालय के मानक वर्तनी नियमों के अनुसार पंचमाक्षरों के स्थान पर शिरोरेखा के ऊपर अनुस्वार (ं) का प्रयोग मानक है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4edffdf4-8d1e-41a5-815b-764c80005fa3', 'गङ्गा -> गंगा ; चञ्चल -> चंचल ; कण्ठ -> कंठ ; सम्बन्ध -> संबंध', true, 'beac8db5-f9c9-448a-9d1e-07eb916ca64f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99e5c637-f368-48db-92c4-56b972c7d809', 'सभी अशुद्ध हैं', false, 'beac8db5-f9c9-448a-9d1e-07eb916ca64f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10f6d002-131e-47d6-9cc5-2581e5711b47', 'केवल गङ्गा शुद्ध है', false, 'beac8db5-f9c9-448a-9d1e-07eb916ca64f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b33d719-6255-4f15-a669-272bd3ab0602', 'केवल चञ्चल शुद्ध है', false, 'beac8db5-f9c9-448a-9d1e-07eb916ca64f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07a180be-7d5c-4636-9cfb-05214fbd82db', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Easy', 'The method of separating slightly larger sized impurities like pieces of dirt, stones, and husk from wheat, rice, or pulses using hands is called:', 'Handpicking is used when impurities differ in size, color, or shape and are present in small quantities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('753ecb81-549c-433c-8c47-addd37174f70', 'Handpicking', true, '07a180be-7d5c-4636-9cfb-05214fbd82db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f34ca9b9-b001-4b58-a989-44718d7f4b55', 'Threshing', false, '07a180be-7d5c-4636-9cfb-05214fbd82db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62e72c89-c0f5-471b-b11f-8504e79e3c5f', 'Winnowing', false, '07a180be-7d5c-4636-9cfb-05214fbd82db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc64f9ef-9c26-4694-b060-aec5103bc3e9', 'Sieving', false, '07a180be-7d5c-4636-9cfb-05214fbd82db');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('728c788d-7550-47e8-a913-df8418d39dda', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Easy', 'The process of beating harvested stalks on a hard stone surface to free the edible grains is called:', 'Threshing separates grain seeds from the dry stalks using mechanical beating, bullocks, or motorized threshers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ee00344-841a-48fa-9542-94aebf494a55', 'Threshing', true, '728c788d-7550-47e8-a913-df8418d39dda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('138c28e9-b56f-478d-8a7b-7208529e8749', 'Winnowing', false, '728c788d-7550-47e8-a913-df8418d39dda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('943626bc-f6b0-4a9e-b386-314290f4298a', 'Sieving', false, '728c788d-7550-47e8-a913-df8418d39dda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('078420dd-a5f7-4fff-a5e4-c860a01fd9aa', 'Filtration', false, '728c788d-7550-47e8-a913-df8418d39dda');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae2fa816-9017-4a01-b774-3761e735e8d4', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Easy', 'The method of separating heavier grain seeds from lighter husk particles using blowing wind or air currents is called:', 'Winnowing relies on the density difference where wind blows away lighter husk while heavier grains fall vertically.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('947a3f10-def1-4b5e-8ab7-dc5c9b0e3876', 'Winnowing', true, 'ae2fa816-9017-4a01-b774-3761e735e8d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fe0e330-4208-4048-bc0b-38d68b0ffed0', 'Threshing', false, 'ae2fa816-9017-4a01-b774-3761e735e8d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dadb9ddb-9207-4f17-8cd5-89130cf8f865', 'Sieving', false, 'ae2fa816-9017-4a01-b774-3761e735e8d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cfbb922-230a-4542-b523-9892d03a99f1', 'Sedimentation', false, 'ae2fa816-9017-4a01-b774-3761e735e8d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1aec789-1115-4e09-a9f1-2e42fa74964a', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Easy', 'The method used to separate components of a mixture that have different particle sizes using a mesh or perforated screen is:', 'Sieving allows fine flour particles to pass through wire mesh while retaining larger bran impurities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cb25bfa-128b-4e4d-b0c5-c891bed4af76', 'Sieving', true, 'c1aec789-1115-4e09-a9f1-2e42fa74964a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc7bc8de-2c6f-468c-b694-65c5be7cae9e', 'Handpicking', false, 'c1aec789-1115-4e09-a9f1-2e42fa74964a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('313dce33-dbcf-432c-a913-5d530c815f45', 'Evaporation', false, 'c1aec789-1115-4e09-a9f1-2e42fa74964a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1e95036-db20-4c40-a294-1c6acfa1a765', 'Decantation', false, 'c1aec789-1115-4e09-a9f1-2e42fa74964a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9fb14507-28ac-4e5a-8739-39bd97e607b6', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Easy', 'When the heavier insoluble component in a liquid mixture settles to the bottom of the container after standing undisturbed, the process is called:', 'Gravitational settling of denser suspended particles (like sand in water) at the bottom is sedimentation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e68af9c-c5ca-4b65-afac-c4437341792b', 'Sedimentation', true, '9fb14507-28ac-4e5a-8739-39bd97e607b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6d423f2-1588-4357-8e71-92d2ddbab785', 'Decantation', false, '9fb14507-28ac-4e5a-8739-39bd97e607b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('291acf76-aad3-44eb-977e-9af79d47d51a', 'Filtration', false, '9fb14507-28ac-4e5a-8739-39bd97e607b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a3c8b99-f5b7-400e-bb9e-b80842212912', 'Evaporation', false, '9fb14507-28ac-4e5a-8739-39bd97e607b6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e602606f-e027-4f0f-8123-1c6aa5f72ba7', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Easy', 'The process of gently pouring out the clear top liquid without disturbing the settled sediment at the bottom is called:', 'Decantation transfers the supernatant liquid layer into another vessel leaving the settled sediment behind.', NOW()) ON CONFLICT DO NOTHING;
