INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73ba10e9-e7fa-47bd-b105-6fa763f52958', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Easy', 'How is common edible table salt (NaCl) commercially obtained on a large scale from seawater?', 'Solar evaporation in shallow coastal salt pans vaporizes water, leaving behind crude solid sodium chloride crystals.', NOW()) ON CONFLICT DO NOTHING;
