INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87858b92-cb5c-41bd-afe1-a94aeb42a9c2', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Easy', 'Which of the following implements is used in kitchens to separate used tea leaves from brewed liquid tea?', 'A tea strainer acts as a sieve/filter, retaining insoluble boiled tea leaves while letting the aromatic beverage flow.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('267089ca-1f11-4bbd-badb-946b2d9cb7d9', 'A fine wire strainer (Filter)', true, '87858b92-cb5c-41bd-afe1-a94aeb42a9c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ee00e2e-156f-4924-8be9-5d7e0ed8725a', 'A winnowing basket', false, '87858b92-cb5c-41bd-afe1-a94aeb42a9c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5443cac1-c9a1-430c-b4a1-42c87c218630', 'A wooden thresher', false, '87858b92-cb5c-41bd-afe1-a94aeb42a9c2');
