INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dcd6e6d3-27d9-4772-8832-2fe3530d14de', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'What happens to the solubility of solid sugar or salt in water when the temperature of the water is increased by heating?', 'Thermal energy expands intermolecular spaces between water molecules and supplies endothermic dissolution energy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('504d1fab-82b4-4819-a29f-625953d94e43', 'Its solubility increases, allowing more solid to dissolve', true, 'dcd6e6d3-27d9-4772-8832-2fe3530d14de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64576967-cd75-4d10-b744-0b5bc48936ae', 'Its solubility decreases', false, 'dcd6e6d3-27d9-4772-8832-2fe3530d14de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7e03a77-d3c5-43a1-942b-e43c099bbba0', 'The dissolved sugar turns into gas', false, 'dcd6e6d3-27d9-4772-8832-2fe3530d14de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('179bc7ce-16ab-4321-ac87-227c6d1b0899', 'The solubility remains unchanged', false, 'dcd6e6d3-27d9-4772-8832-2fe3530d14de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4ac1b821-8cbf-4cbc-97e0-0d7d5a1d0280', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'Why can a mixture of wheat flour and iron fillings be easily separated using a magnet?', 'Magnetic separation exploits the ferromagnetic property of iron to selectively extract filings without touching the flour.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66da8aca-72b0-42a8-a277-25a294db8148', 'Iron is a magnetic material attracted by magnets, whereas wheat flour is non-magnetic', true, '4ac1b821-8cbf-4cbc-97e0-0d7d5a1d0280');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb4569c6-5d31-4108-aa1d-2b45395729b6', 'Iron melts near magnets', false, '4ac1b821-8cbf-4cbc-97e0-0d7d5a1d0280');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fe8abc8-4c74-4c46-9b35-15dfb3c79e1a', 'Wheat flour is poisonous to magnets', false, '4ac1b821-8cbf-4cbc-97e0-0d7d5a1d0280');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7392ecd4-8430-431c-be53-78bf85ad2874', 'Magnets blow air like wind', false, '4ac1b821-8cbf-4cbc-97e0-0d7d5a1d0280');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3a4a591b-2d70-4581-a944-2e6278020f7b', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'Why is water commonly referred to as a ''Universal Solvent'' in chemistry?', 'Water''s high dielectric constant and polar dipole moments readily hydrate and break ionic lattices.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('826143ac-b3b2-4271-ac88-533c4e542b2c', 'Because its polar molecular structure can dissolve a wider variety of solutes than any other known liquid', true, '3a4a591b-2d70-4581-a944-2e6278020f7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df77ac10-f34b-4cd2-8c27-d5725ac55055', 'Because it exists in all galaxies', false, '3a4a591b-2d70-4581-a944-2e6278020f7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('065df71c-a5b3-4b23-a478-3c786c76b551', 'Because it has zero boiling point', false, '3a4a591b-2d70-4581-a944-2e6278020f7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('629612e2-c100-42d1-a180-e851bc6de99e', 'Because it never turns into ice', false, '3a4a591b-2d70-4581-a944-2e6278020f7b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43b11378-16d9-4a8e-adde-61bb944ec556', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'Which combined sequence of separation techniques is used to separate a mixture of Sand and Salt completely?', 'Salt dissolves in water while sand remains insoluble; filtering removes sand residue, and evaporating the filtrate yields dry salt.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('732574c6-7f8f-4594-909c-789cd44dcb3b', 'Dissolution in water -> Sedimentation & Filtration (separates sand) -> Evaporation / Condensation (recovers salt & water)', true, '43b11378-16d9-4a8e-adde-61bb944ec556');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4859661b-8862-48a1-b7bb-98ab496b7177', 'Threshing followed by Winnowing', false, '43b11378-16d9-4a8e-adde-61bb944ec556');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08b2a414-c1e2-4241-8259-54083677a030', 'Handpicking followed by Sieving', false, '43b11378-16d9-4a8e-adde-61bb944ec556');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c76410f-ad98-4db0-b729-1c4fa08f2928', 'Direct Sieving through cloth', false, '43b11378-16d9-4a8e-adde-61bb944ec556');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aba9a764-2f39-4bf9-83fa-ebb6f1c36632', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'Why is churning (centrifugation) of whole milk or curd practiced in Indian households?', 'Mechanical churning agitates emulsified fat globules, causing them to coalesce and float as lighter butter.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9a985be-ab28-4ae3-952b-cf6461cf2439', 'To separate less dense butter (fats) which float to the top from denser liquid buttermilk', true, 'aba9a764-2f39-4bf9-83fa-ebb6f1c36632');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e664770-607d-4607-81ff-0da8fe07d924', 'To change the color of milk to red', false, 'aba9a764-2f39-4bf9-83fa-ebb6f1c36632');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60808901-542c-4e77-a0ec-737ec6f727a6', 'To evaporate all liquid', false, 'aba9a764-2f39-4bf9-83fa-ebb6f1c36632');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c770d8f-a221-40fd-a07e-d8bd127ae9f6', 'To dissolve sugar', false, 'aba9a764-2f39-4bf9-83fa-ebb6f1c36632');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64acfc1f-cafb-4b02-9825-94ee6cf9c270', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'What is the solid material retained on the filter paper after filtration called?', 'The trapped insoluble solid retained on the filter is the Residue, while the clear collected liquid is the Filtrate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b806fd41-bd61-4fba-9cca-281e0a886553', 'Residue', true, '64acfc1f-cafb-4b02-9825-94ee6cf9c270');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f94f3206-e43f-4485-94f4-33bfde964d0d', 'Filtrate', false, '64acfc1f-cafb-4b02-9825-94ee6cf9c270');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('361d8c44-c811-4ab3-a03a-90e435dc4520', 'Solvent', false, '64acfc1f-cafb-4b02-9825-94ee6cf9c270');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad191035-7e74-48f5-9e84-6a27f32f4204', 'Sediment', false, '64acfc1f-cafb-4b02-9825-94ee6cf9c270');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d022eb38-be51-4b06-aaa6-5c859c3e8bcd', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'What is the clear liquid that passes through the filter paper and collects in the beaker called?', 'The liquid that successfully passes through the microscopic pores of the filtration filter is called the Filtrate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0454ac3f-65bc-4f42-ae9c-5532506935d0', 'Filtrate', true, 'd022eb38-be51-4b06-aaa6-5c859c3e8bcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e7656b5-64f4-4add-b69a-27b88fe316b4', 'Residue', false, 'd022eb38-be51-4b06-aaa6-5c859c3e8bcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e2cb038-7dbe-4071-80b7-a8d3c57d9933', 'Solute', false, 'd022eb38-be51-4b06-aaa6-5c859c3e8bcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c6fb94b-db76-45b3-87b8-9d003bcc20ff', 'Precipitate', false, 'd022eb38-be51-4b06-aaa6-5c859c3e8bcd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8c77f9ed-c60d-472a-9d96-da241535687e', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'How can muddy river water be rapidly cleared of fine suspended colloidal clay particles in village households?', 'Alum releases trivalent Al³⁺ ions that neutralize negative surface charges on colloidal clay, causing rapid flocculation (loading).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80ba6c20-9d06-461b-8c53-5210d842300b', 'By swirling a piece of Alum (Phitkari) in the water to cause coagulation (Loading)', true, '8c77f9ed-c60d-472a-9d96-da241535687e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ecfbd59-1fe5-4cda-99b5-9b09ae0928fe', 'By adding salt', false, '8c77f9ed-c60d-472a-9d96-da241535687e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d2e0ce1-aa57-4b79-aa95-beab31d3e9fb', 'By blowing air', false, '8c77f9ed-c60d-472a-9d96-da241535687e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c474c8c3-ebbb-4810-b7a6-ca86eb7b6cb0', 'By freezing into ice', false, '8c77f9ed-c60d-472a-9d96-da241535687e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30315faa-84c4-499e-ab5a-3dc8d56cc112', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'Why can''t a mixture of sugar dissolved in water be separated by using filter paper?', 'Dissolved solute particles in a true solution have molecular dimensions (< 1 nm) and pass through filter pores unimpeded.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e52ffde1-8845-4686-a6d3-fecd49ab920a', 'Sugar dissolves into individual molecules/ions that are much smaller than the microscopic pores of the filter paper', true, '30315faa-84c4-499e-ab5a-3dc8d56cc112');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7c76248-565f-4637-9003-211d928111a8', 'Sugar tears the filter paper', false, '30315faa-84c4-499e-ab5a-3dc8d56cc112');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba8d38bf-096c-407d-8bbe-c08df24d3a53', 'Sugar turns into water vapor', false, '30315faa-84c4-499e-ab5a-3dc8d56cc112');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a9f4086-fb87-4d88-ab29-b38ac492fbde', 'Filter paper dissolves sugar', false, '30315faa-84c4-499e-ab5a-3dc8d56cc112');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e5caadd-49bf-4941-bc4f-eb48510fefa4', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'Which of the following mixtures CANNOT be separated by winnowing?', 'Both iron pins and sand grains are dense solids that fall straight down; winnowing requires a light, wind-blowable fraction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b40c5e4e-9c43-4c98-a5c5-ac4fcdba14f1', 'Iron pins mixed with sand', true, '7e5caadd-49bf-4941-bc4f-eb48510fefa4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('603a2542-ea1b-4cb9-89d1-b41f5391c992', 'Wheat grains mixed with dry husk', false, '7e5caadd-49bf-4941-bc4f-eb48510fefa4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45751a16-99d9-4fee-88cc-13c8439ce93e', 'Paddy grains mixed with dry chaff', false, '7e5caadd-49bf-4941-bc4f-eb48510fefa4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b463740b-7cc9-41d9-be39-6d51aeb67961', 'Groundnut seeds mixed with dry leaves', false, '7e5caadd-49bf-4941-bc4f-eb48510fefa4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('213799e5-bbac-4784-8881-f86f09101170', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'What is the primary scientific reason for separating substances from a mixture?', 'Separation isolates useful components (e.g. butter from milk) and purges harmful or unwanted contaminants (e.g. stones from grains).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd455d03-93f6-4dcc-9da0-b705300ea542', 'To remove harmful or undesirable impurities and to recover valuable pure components for use', true, '213799e5-bbac-4784-8881-f86f09101170');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dadffa60-47ff-4805-b5ca-ed41b65497f2', 'To make food taste bitter', false, '213799e5-bbac-4784-8881-f86f09101170');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97a0d2ed-c95f-4c25-89a4-4d2061265e83', 'To destroy the chemical elements', false, '213799e5-bbac-4784-8881-f86f09101170');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6794ef5f-d9cf-41de-86f9-ea6f6ee58c1b', 'To increase the weight of the mixture', false, '213799e5-bbac-4784-8881-f86f09101170');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e83bf7d8-b7e9-47cd-aa22-1be77af1fe15', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'In construction sites, why do builders pass sand through large inclined wire mesh sieves?', 'Sieving isolates particle sizes, filtering out oversized aggregate stones to ensure smooth plastering cement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('208c6453-ca45-4efc-80d8-8ed8bfd0ce54', 'To separate coarse gravel and pebbles from fine sand needed for masonry mortar', true, 'e83bf7d8-b7e9-47cd-aa22-1be77af1fe15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49b83b73-f909-4aa5-b9e4-2372f0bb51cd', 'To dry the sand', false, 'e83bf7d8-b7e9-47cd-aa22-1be77af1fe15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6dca4b29-0215-4702-b663-d61c636f6aee', 'To change the color of sand', false, 'e83bf7d8-b7e9-47cd-aa22-1be77af1fe15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05e66809-9a12-48df-b80f-f2b302588176', 'To cool the sand', false, 'e83bf7d8-b7e9-47cd-aa22-1be77af1fe15');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73ef6c1d-d3c4-4e80-9d93-30cdd63af7fd', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'How can one prepare a saturated solution of salt in a glass of water at room temperature?', 'Dynamic saturation is reached when the dissolution rate equals crystallization rate, leaving visible solid solute.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8757f81-d58a-44d7-b0af-98f23c94c453', 'Keep adding salt spoon by spoon with continuous stirring until no more salt dissolves and excess crystals settle at the bottom', true, '73ef6c1d-d3c4-4e80-9d93-30cdd63af7fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f7cc12e-ec57-4d4e-9b5f-48753ec6a68e', 'Add 1 gram of salt and boil for 2 hours', false, '73ef6c1d-d3c4-4e80-9d93-30cdd63af7fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ca19c0c-2d6d-449f-9a4d-4b350e1c5fb1', 'Add ice to water', false, '73ef6c1d-d3c4-4e80-9d93-30cdd63af7fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83556e8f-d40a-4565-94e7-cb6ebedc044e', 'Keep the water in the dark', false, '73ef6c1d-d3c4-4e80-9d93-30cdd63af7fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b05b3c59-f0d1-4e4a-a0eb-81049839da23', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'What is the role of the condensation process in the water cycle of nature?', 'Adiabatic cooling of rising warm moist air condenses vapor onto cloud condensation nuclei, generating precipitation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bc180f6-df6c-4562-a62a-a17ac6e3b2f5', 'It converts rising atmospheric water vapor into liquid water droplets, forming clouds and bringing rain', true, 'b05b3c59-f0d1-4e4a-a0eb-81049839da23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f49a8c1-22b9-429f-b430-4243d56fec90', 'It absorbs sunlight', false, 'b05b3c59-f0d1-4e4a-a0eb-81049839da23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a99f676-af01-44da-b10a-31441b745730', 'It turns rain into dry air', false, 'b05b3c59-f0d1-4e4a-a0eb-81049839da23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6136fe33-0a11-4d6b-aa1f-486ab63f52dd', 'It creates ocean salt', false, 'b05b3c59-f0d1-4e4a-a0eb-81049839da23');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d9169ad-8c43-4863-bec6-b672024b6057', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'If a saturated solution of salt is cooled down from 60°C to 10°C, what observation will be made?', 'Lowering temperature reduces solute saturation capacity, forcing excess solute out of solution as recrystallized solids.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d441d805-2619-4e70-b0e4-d3508095cc6a', 'Excess dissolved salt will precipitate out and crystallize at the bottom of the beaker', true, '3d9169ad-8c43-4863-bec6-b672024b6057');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11572a27-5d11-43ee-9ab4-d3cbee3fb63f', 'The water will turn into gas', false, '3d9169ad-8c43-4863-bec6-b672024b6057');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a2aa758-41bd-4741-a68d-b37ad07f7ae1', 'The salt will disappear permanently', false, '3d9169ad-8c43-4863-bec6-b672024b6057');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96db4ec6-7b0d-4e36-918a-6e544f7ec0ba', 'The solution will become unsaturated', false, '3d9169ad-8c43-4863-bec6-b672024b6057');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f0379dfc-26c1-428f-ab90-2b64728e9e68', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Medium', 'Which of the following processes involves BOTH evaporation and condensation working consecutively?', 'Distillation vaporizes the volatile solvent (evaporation) and then cools the pure vapor through a condenser (condensation).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d97637c3-6dc5-4bb9-a414-aaaede668fa1', 'Distillation (producing pure distilled water)', true, 'f0379dfc-26c1-428f-ab90-2b64728e9e68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc05658c-327c-465f-80b6-c7349dc955a8', 'Handpicking', false, 'f0379dfc-26c1-428f-ab90-2b64728e9e68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f7fff8e-7b3c-4ba8-9785-25e55e1047a7', 'Sieving', false, 'f0379dfc-26c1-428f-ab90-2b64728e9e68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('780896b4-2af7-4e67-b6c1-cde348389a01', 'Threshing', false, 'f0379dfc-26c1-428f-ab90-2b64728e9e68');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f973ce5d-a1d1-421e-bac9-31071605872d', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'Read the statements:
