INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('587901a1-7f9e-409e-99c4-82c1cdeb07ce', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'Spot the IMPOSTER in the following group of separation techniques based on the physical state of the mixtures they separate:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82449030-67e6-4fd7-ba67-4951006c29d5', 'Handpicking', false, '587901a1-7f9e-409e-99c4-82c1cdeb07ce');
