INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9371945-3d5b-4a24-a6ec-ce2429d25483', 'Winnowing', false, '587901a1-7f9e-409e-99c4-82c1cdeb07ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c01620d8-1a55-4f7a-a849-3c461bf88651', 'Decantation', true, '587901a1-7f9e-409e-99c4-82c1cdeb07ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53f8485f-0179-49e5-b22d-2bfb5e0a233a', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'A student accidentally mixes Sand, Salt, and Iron filings in a beaker. What is the scientifically correct step-by-step procedure to recover all three components pure and dry?', 'Magnetic extraction isolates iron; aqueous dissolution exploits differential solubility; filtration isolates sand; evaporation yields salt.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d0cc773-34f6-4f0c-9d34-920fecf6a6c6', '1. Use a Magnet to extract iron filings -> 2. Add water to dissolve salt -> 3. Filter to separate sand residue -> 4. Evaporate filtrate to recover dry salt crystals', true, '53f8485f-0179-49e5-b22d-2bfb5e0a233a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('898d80cd-ac13-4b8e-90cb-4f31e6c56598', '1. Evaporate first -> 2. Filter -> 3. Handpick', false, '53f8485f-0179-49e5-b22d-2bfb5e0a233a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ef65a12-7dd5-4718-932f-3a26bec8a6c7', '1. Winnow the mixture -> 2. Sieve through wire mesh', false, '53f8485f-0179-49e5-b22d-2bfb5e0a233a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('858a7782-39b1-4b06-87e4-0713ddb267e4', '1. Thresh the beaker -> 2. Add acid', false, '53f8485f-0179-49e5-b22d-2bfb5e0a233a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18c994f8-d257-4ef3-8d7b-a87936581564', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'In an experiment, water containing steam is held beneath a cold metal plate holding ice cubes. Drops of liquid water form and drip into a beaker. What two physical processes are operating?', 'Thermal vaporization generates steam (evaporation), which gives up its latent heat of condensation upon contact with the chilled ice plate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86b96b0c-f28a-46d4-94de-457ff3022647', 'Evaporation (from the hot liquid) and Condensation (on the cold metal plate)', true, '18c994f8-d257-4ef3-8d7b-a87936581564');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74debb51-c671-4c94-90af-ae7ed96fd2dc', 'Sedimentation and Decantation', false, '18c994f8-d257-4ef3-8d7b-a87936581564');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35bcab3c-3106-40bd-82cc-c8c36bf281eb', 'Sieving and Threshing', false, '18c994f8-d257-4ef3-8d7b-a87936581564');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1424fb2-8348-41fd-8826-d78a6a10ffb4', 'Sublimation and Freezing', false, '18c994f8-d257-4ef3-8d7b-a87936581564');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d30d533-1283-459f-9373-e812f1087ae0', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'Match the following mixtures with their optimal method of separation:
(a) Grain seeds from stalks       -> (i) Filtration
(b) Husk from grain seeds        -> (ii) Threshing
(c) Fine clay from muddy water   -> (iii) Evaporation
(d) Salt from sea water          -> (iv) Winnowing', 'Grain from stalks = Threshing; Husk from grain = Winnowing; Fine clay = Filtration; Salt from seawater = Evaporation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e568b9d-085a-4bf0-aa8d-eb89abb5313f', 'a-(ii), b-(iv), c-(i), d-(iii)', true, '1d30d533-1283-459f-9373-e812f1087ae0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd6c78ed-80d5-4fb5-8452-0a4259bf0274', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '1d30d533-1283-459f-9373-e812f1087ae0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1121edee-e9e3-466d-8789-8795c6162103', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '1d30d533-1283-459f-9373-e812f1087ae0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cedc0ab4-5196-4b9b-be2e-1972c89a015b', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '1d30d533-1283-459f-9373-e812f1087ae0');
