INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1773cec-c79a-4d61-9678-0a7f8f3faa9f', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'Why does the rate of evaporation of water increase significantly on a hot, windy, and dry sunny afternoon?', 'Evaporation rate is directly proportional to temperature, surface area, and wind speed, and inversely proportional to relative humidity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('034db9dd-894b-4ff4-ab73-ec480bfcf3f1', 'Higher temperature increases thermal kinetic energy, wind swiftly removes saturated vapor boundary layers, and low humidity enhances vapor gradient', true, 'c1773cec-c79a-4d61-9678-0a7f8f3faa9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2de26b5-4500-44ce-b720-9592920a94ad', 'Wind blows the water molecules into outer space', false, 'c1773cec-c79a-4d61-9678-0a7f8f3faa9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61c8cee5-6d61-4b47-9f30-8fcc28c52c98', 'Sunlight freezes water molecules', false, 'c1773cec-c79a-4d61-9678-0a7f8f3faa9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c286e04f-69fa-45fa-b91e-09b4200f1cc3', 'Atmospheric air turns into pure salt', false, 'c1773cec-c79a-4d61-9678-0a7f8f3faa9f');
