INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f47f5cb2-c0bd-4756-aeb5-1ca8584cf6a9', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'Why is folded cone-shaped filter paper moistened with a few drops of water before placing it in the glass funnel?', 'Capillary wetting seals the paper against the glass conical wall, creating continuous hydrostatic suction and preventing bypass channels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bf6f267-ba39-4690-9eb4-f8d81d39da8a', 'To ensure the filter paper adheres tightly to the glass funnel walls without air pockets, preventing unfiltered liquid from bypassing the filter', true, 'f47f5cb2-c0bd-4756-aeb5-1ca8584cf6a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('791a9790-2cf0-40bc-a38a-b849337cb357', 'To make the paper change color', false, 'f47f5cb2-c0bd-4756-aeb5-1ca8584cf6a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcb1ea63-8cf4-4d40-99e8-63540ebd556d', 'To burn impurities', false, 'f47f5cb2-c0bd-4756-aeb5-1ca8584cf6a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f94d0eb-ae83-46e9-9170-eba0d9a7d90e', 'To block water from passing', false, 'f47f5cb2-c0bd-4756-aeb5-1ca8584cf6a9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a60fc08e-1967-47f6-942c-54261a127e22', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'A beaker contains 100 mL of water saturated with salt at 25°C (containing 36 g salt). What happens if another 10 g of salt is stirred in at 25°C?', 'At 25°C, water''s solubility limit for NaCl is ~36 g/100 mL; any additional solute remains in dynamic equilibrium as undissolved precipitate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2082910-038a-4423-a07d-b85c1b1f5d40', 'The extra 10 g of salt will remain completely undissolved at the bottom of the beaker', true, 'a60fc08e-1967-47f6-942c-54261a127e22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13753a8f-4479-4f4a-accd-d52e379c7925', 'The water will freeze instantly', false, 'a60fc08e-1967-47f6-942c-54261a127e22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b49e7e82-de35-4297-af4a-ca0c48bbcbc0', 'The extra salt will dissolve and make the solution cold', false, 'a60fc08e-1967-47f6-942c-54261a127e22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bb19511-3f30-466c-866b-29c0d5e1de9d', 'The solution will evaporate completely', false, 'a60fc08e-1967-47f6-942c-54261a127e22');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a49204b8-261f-49b3-8115-9296f039b69c', 'Class 6', 'Science', 'Chapter 3: Separation of Substances', 'Hard', 'Which of the following describes the physicochemical principle underlying ''Loading'' using Alum in water treatment?', 'Coagulation/loading collapses the electrical double layer of colloidal clay particulates, enabling rapid gravity sedimentation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32512f17-31cc-486c-9783-97ec6cb2a01c', 'Alum hydrolyzes to provide multivalent positive aluminium ions that neutralize negative zeta potentials on suspended clay particles, causing rapid aggregation and precipitation', true, 'a49204b8-261f-49b3-8115-9296f039b69c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('540d80e7-4997-4a26-a421-79cca4385038', 'Alum boils the water', false, 'a49204b8-261f-49b3-8115-9296f039b69c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfda220d-2572-40b0-a6b4-8ee0cf533ddd', 'Alum turns dirt into oxygen gas', false, 'a49204b8-261f-49b3-8115-9296f039b69c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ed07ba5-4f18-4300-a495-296aa3143d13', 'Alum magnifies light rays', false, 'a49204b8-261f-49b3-8115-9296f039b69c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('804afab2-c02c-4f2a-ac0c-153fc31c2e43', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'A number which has only two distinct factors, 1 and the number itself, is called a:', 'Prime numbers (2, 3, 5, 7, 11...) have exactly two positive factors: 1 and the number itself.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2b9506f-b5b9-42b4-83ab-3413b0cfda92', 'Prime Number', true, '804afab2-c02c-4f2a-ac0c-153fc31c2e43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91a9fa25-12ae-43c8-ae7d-24a931fc4baf', 'Composite Number', false, '804afab2-c02c-4f2a-ac0c-153fc31c2e43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72a239fa-f3da-4dc4-ac8e-9e107358d2a8', 'Even Number', false, '804afab2-c02c-4f2a-ac0c-153fc31c2e43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f450b7e9-952b-4879-b372-8a74960029cc', 'Odd Number', false, '804afab2-c02c-4f2a-ac0c-153fc31c2e43');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('046fd3d4-5abc-47a1-8bc2-870a3fab945d', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'Numbers having more than two factors are called:', 'Composite numbers (4, 6, 8, 9, 10...) can be divided evenly by numbers other than 1 and themselves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbddd60d-de6e-4342-a0a6-8c68fcd4dc3a', 'Composite Numbers', true, '046fd3d4-5abc-47a1-8bc2-870a3fab945d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cd5cfc5-e5f8-4e6f-a0dd-4bb522701f1e', 'Prime Numbers', false, '046fd3d4-5abc-47a1-8bc2-870a3fab945d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7a3d806-3823-4b96-81cf-d051d3beacc4', 'Odd Numbers', false, '046fd3d4-5abc-47a1-8bc2-870a3fab945d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c94f836-dd1f-4916-a962-16d12f6c47db', 'Twin Primes', false, '046fd3d4-5abc-47a1-8bc2-870a3fab945d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c342dd1b-68ac-4934-855e-61e662b9ff56', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'Which unique number is NEITHER a prime number NOR a composite number?', 'The number 1 has only one single factor (1); hence it is neither prime (2 factors) nor composite (> 2 factors).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('780928b1-692b-4f67-9950-9e3d3c021b56', '1', true, 'c342dd1b-68ac-4934-855e-61e662b9ff56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d962e9f-0cb5-4aed-b2fd-b19d51206f68', '0', false, 'c342dd1b-68ac-4934-855e-61e662b9ff56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('716197fe-551a-42f1-8434-6986adf57ef6', '2', false, 'c342dd1b-68ac-4934-855e-61e662b9ff56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9769709-6047-4323-bfbd-41936bddb440', '3', false, 'c342dd1b-68ac-4934-855e-61e662b9ff56');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('44564d8e-48c2-418b-ad6c-564d20e0aab9', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'What is the smallest and ONLY EVEN prime number?', '2 is the smallest prime number and the only even prime, as all other even numbers are divisible by 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c88b09e-036a-463d-b3d7-5e80f84be471', '2', true, '44564d8e-48c2-418b-ad6c-564d20e0aab9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46b626a1-d418-457b-b8e4-7ba7ccb16b2e', '4', false, '44564d8e-48c2-418b-ad6c-564d20e0aab9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18ed5fd8-7969-4341-ac88-48f93d65c7a7', '0', false, '44564d8e-48c2-418b-ad6c-564d20e0aab9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7f2f927-c83a-4e5b-9040-8974ef9b7da5', '1', false, '44564d8e-48c2-418b-ad6c-564d20e0aab9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3034469e-ed18-4680-8b2f-2cc903550a89', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'Two prime numbers whose difference is exactly 2 (such as 3 and 5, or 5 and 7) are called:', 'Twin primes are pairs of prime numbers differing by 2: (3, 5), (5, 7), (11, 13), (17, 19).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('957d44a9-d906-4f7a-a2f9-f844c090ae54', 'Twin Primes', true, '3034469e-ed18-4680-8b2f-2cc903550a89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('713a15f9-c5b7-4c81-8018-cda236a6a6a4', 'Co-primes', false, '3034469e-ed18-4680-8b2f-2cc903550a89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0d627e5-3791-44f1-bbb9-4553cdb14843', 'Perfect Numbers', false, '3034469e-ed18-4680-8b2f-2cc903550a89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('907562cd-7237-4a73-8212-450831856e93', 'Composite Numbers', false, '3034469e-ed18-4680-8b2f-2cc903550a89');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c924f9e8-74bb-404b-94de-bdfa462cbe54', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'Two numbers having only 1 as their common factor (such as 4 and 15) are called:', 'Two integers a and b are co-prime if their Highest Common Factor HCF(a, b) = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3686171-8d1b-451e-88a9-d3cf64d8915a', 'Co-prime Numbers (Relatively Prime)', true, 'c924f9e8-74bb-404b-94de-bdfa462cbe54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea18b779-7acf-4edf-8db0-cc2e8b4bc2a7', 'Twin Primes', false, 'c924f9e8-74bb-404b-94de-bdfa462cbe54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('beccc3e3-1054-4f62-9bc4-fbf8934243b0', 'Composite Numbers', false, 'c924f9e8-74bb-404b-94de-bdfa462cbe54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfaa8688-c844-4b92-a9d9-c7dd3cf3714a', 'Even Numbers', false, 'c924f9e8-74bb-404b-94de-bdfa462cbe54');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('617e2d9d-60d8-4fa7-9e7c-136ad9545734', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'What is a number for which the sum of all its factors is equal to twice the number called?', 'For 6: factors are 1, 2, 3, 6; sum = 1+2+3+6 = 12 = 2 × 6; hence 6 is a perfect number.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05f0b118-4c7f-4c47-be8e-d07e626329a9', 'A Perfect Number (e.g., 6 and 28)', true, '617e2d9d-60d8-4fa7-9e7c-136ad9545734');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74339b1b-16ff-4df4-8a8e-b65488972a7a', 'A Prime Number', false, '617e2d9d-60d8-4fa7-9e7c-136ad9545734');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c24c75bd-b9b9-426f-bbe0-3734e4363bbf', 'A Composite Number', false, '617e2d9d-60d8-4fa7-9e7c-136ad9545734');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa2a05a7-f1ee-40f8-b3fb-0d205c331056', 'A Twin Prime', false, '617e2d9d-60d8-4fa7-9e7c-136ad9545734');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('673d554e-d10e-4aba-9fc8-afb7a5ce6dae', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'A number is divisible by 2 if its units digit is:', 'Divisibility by 2 requires the last digit to be an even number (0, 2, 4, 6, 8).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae2384a9-3485-44ce-b797-860e210dd98e', '0, 2, 4, 6, or 8 (Even digit)', true, '673d554e-d10e-4aba-9fc8-afb7a5ce6dae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fafd30a-5b6a-4aaa-a615-8b8a36e6f07e', '1, 3, 5, 7, 9', false, '673d554e-d10e-4aba-9fc8-afb7a5ce6dae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be2fb9b2-e272-4256-94d5-8086fe23d1c5', '0 or 5 only', false, '673d554e-d10e-4aba-9fc8-afb7a5ce6dae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32c875ad-1adb-4116-945b-2794ceeef32b', 'Divisible by 3', false, '673d554e-d10e-4aba-9fc8-afb7a5ce6dae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e80c695-fd89-471f-93c4-b34946cb7fec', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'A number is divisible by 3 if:', 'In base-10, since 10 ≡ 1 (mod 3), a number is divisible by 3 if and only if the sum of its digits is divisible by 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c2939be-b380-4402-b173-8b84d0b6a589', 'The sum of all its digits is a multiple of 3 (divisible by 3)', true, '2e80c695-fd89-471f-93c4-b34946cb7fec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c14a13c2-b003-4712-8343-8ccff55ed9a7', 'Its last digit is 3', false, '2e80c695-fd89-471f-93c4-b34946cb7fec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d22f1a23-216c-4969-9dae-1a5d0daf592d', 'Its last two digits are divisible by 3', false, '2e80c695-fd89-471f-93c4-b34946cb7fec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e06d5a8c-cb22-4c5b-880b-1f8301fda0ad', 'It is an odd number', false, '2e80c695-fd89-471f-93c4-b34946cb7fec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('840a5dcd-8534-4b80-aac8-bfb56144e414', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'A number is divisible by 5 if its units digit is:', 'Multiples of 5 always terminate in either 0 or 5 in the standard decimal numeral system.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f884056a-6fce-49c6-a618-34194e39d7cb', '0 or 5', true, '840a5dcd-8534-4b80-aac8-bfb56144e414');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99c047e9-92a2-47ad-8a0f-7444a8461708', '0, 2, 4, 6, 8', false, '840a5dcd-8534-4b80-aac8-bfb56144e414');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4a8563f-fbd0-44d5-a304-0eb0a2b47530', '5 only', false, '840a5dcd-8534-4b80-aac8-bfb56144e414');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40f65842-59a2-485d-b619-fde404cd48ed', 'Any odd digit', false, '840a5dcd-8534-4b80-aac8-bfb56144e414');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ab4a2bc-3d91-4485-b3ac-0af257038e64', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'What is the Highest Common Factor (HCF) of two consecutive numbers (like 8 and 9)?', 'Any two consecutive integers are always co-prime; therefore their HCF is strictly 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('980b7f7b-238b-4de3-b34d-987481cc4f77', '1', true, '6ab4a2bc-3d91-4485-b3ac-0af257038e64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be9850c8-8487-477d-9f07-8a6f89543846', '2', false, '6ab4a2bc-3d91-4485-b3ac-0af257038e64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cb16953-6787-4ad1-b64e-dcfbbccd0713', 'Their product', false, '6ab4a2bc-3d91-4485-b3ac-0af257038e64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91fe2750-d8a2-4f98-9a6a-322c5a5e36bf', '0', false, '6ab4a2bc-3d91-4485-b3ac-0af257038e64');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27e11c04-18b6-4129-a332-9cb5733774bf', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Easy', 'What is the Lowest Common Multiple (LCM) of two co-prime numbers a and b?', 'Since HCF(a, b) = 1 and HCF × LCM = a × b, the LCM of co-prime numbers is their product a × b.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a521b9e5-cf61-4ab2-8dfe-a571ca8eb444', 'a × b (Their product)', true, '27e11c04-18b6-4129-a332-9cb5733774bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6081e402-4581-4d60-a72c-5b3db98271c2', '1', false, '27e11c04-18b6-4129-a332-9cb5733774bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1547d440-824b-45bc-97ce-2533cbf91a73', 'a + b', false, '27e11c04-18b6-4129-a332-9cb5733774bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30dbfaa3-0159-42f9-9f8f-1fa12b596fa9', 'a - b', false, '27e11c04-18b6-4129-a332-9cb5733774bf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1dd55c7b-fa9a-4053-829f-f1657b4741f6', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'A number is divisible by 6 if it satisfies which condition?', 'Since 6 = 2 × 3 and 2, 3 are co-prime, divisibility by 6 requires the number to be even and have a digit sum divisible by 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8afc476-57fe-450e-b2f5-d9642d513c24', 'It is divisible by BOTH 2 and 3 simultaneously', true, '1dd55c7b-fa9a-4053-829f-f1657b4741f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ebaa22f-204a-403d-bec8-bcbe7dda9d16', 'It is divisible by 2 only', false, '1dd55c7b-fa9a-4053-829f-f1657b4741f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75c0bb79-9f2a-4a90-b1e6-1790d3da0a7f', 'It is divisible by 3 only', false, '1dd55c7b-fa9a-4053-829f-f1657b4741f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('921eacb5-9243-452c-9a8d-a7bc3d808e42', 'Its last digit is 6', false, '1dd55c7b-fa9a-4053-829f-f1657b4741f6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c9f4e759-e647-4f1f-99ff-99151ec4dba1', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'A number with 3 or more digits is divisible by 4 if:', 'Since 100 is divisible by 4, only the last two digits determine divisibility by 4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a92bbca-66c2-418a-9b63-716e1728adeb', 'The number formed by its last two digits (tens and units) is divisible by 4', true, 'c9f4e759-e647-4f1f-99ff-99151ec4dba1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07850d89-0d21-410d-9419-efdd553c53d7', 'Its units digit is 4', false, 'c9f4e759-e647-4f1f-99ff-99151ec4dba1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f293f9ea-9fb2-4f77-be8c-394c8e23410f', 'The sum of its digits is divisible by 4', false, 'c9f4e759-e647-4f1f-99ff-99151ec4dba1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ba02da2-62fe-4d94-8fe7-4de62ec8f6b2', 'It ends in an odd number', false, 'c9f4e759-e647-4f1f-99ff-99151ec4dba1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1ff7a18-df58-4e06-ab79-d50bacf3e344', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'A number with 4 or more digits is divisible by 8 if:', 'Since 1000 is divisible by 8, divisibility depends entirely on the last 3 digits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4075823e-5ed0-4249-a939-3e21c26d4a8a', 'The number formed by its last three digits (hundreds, tens, and units) is divisible by 8', true, 'f1ff7a18-df58-4e06-ab79-d50bacf3e344');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06756b4a-94ad-4a9c-85a5-76d2eb642710', 'Its last digit is 8', false, 'f1ff7a18-df58-4e06-ab79-d50bacf3e344');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('677dfa58-a346-443f-b17d-30075b23f1f1', 'The sum of its digits is 8', false, 'f1ff7a18-df58-4e06-ab79-d50bacf3e344');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09654794-e83d-4461-89ad-e74b1e6c1d10', 'It is divisible by 4 only', false, 'f1ff7a18-df58-4e06-ab79-d50bacf3e344');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67b4ade7-97d6-4cc2-9319-ea82a08be6eb', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'A number is divisible by 9 if:', 'Since 10 ≡ 1 (mod 9), a number n is divisible by 9 if the sum of its decimal digits is a multiple of 9.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8776a16-26b2-4780-81e5-2ce59f6eabf2', 'The sum of all its digits is divisible by 9', true, '67b4ade7-97d6-4cc2-9319-ea82a08be6eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aec104df-e0ad-439b-98e4-e4f9af275707', 'Its last digit is 9', false, '67b4ade7-97d6-4cc2-9319-ea82a08be6eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb2ae153-dfb7-4dd7-8430-322b2994347c', 'Its last two digits are 99', false, '67b4ade7-97d6-4cc2-9319-ea82a08be6eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0000686-125f-4960-8995-36ce54858742', 'It is an odd number', false, '67b4ade7-97d6-4cc2-9319-ea82a08be6eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38da44fc-3d26-47dd-9c13-5f01d1eb27f9', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'What is the divisibility test for 11?', 'Alternating sum of digits modulo 11 determines divisibility because 10 ≡ -1 (mod 11).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('463825d6-11db-447a-b725-7b8fab343837', 'The difference between the sum of the digits at odd places (from right) and the sum of digits at even places is either 0 or divisible by 11', true, '38da44fc-3d26-47dd-9c13-5f01d1eb27f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb79576c-621f-4eea-97a2-4576a40d14a9', 'The sum of all digits is 11', false, '38da44fc-3d26-47dd-9c13-5f01d1eb27f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('713343cf-bad1-4e39-a099-9b766d976f54', 'The last two digits are identical', false, '38da44fc-3d26-47dd-9c13-5f01d1eb27f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82674163-e76a-4de4-817a-bee686206d61', 'The units digit is 1', false, '38da44fc-3d26-47dd-9c13-5f01d1eb27f9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('547948a0-22e4-4ae8-a47c-b48917217de0', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'Find the Prime Factorisation of the number 980:', '980 ÷ 2 = 490; 490 ÷ 2 = 245; 245 ÷ 5 = 49; 49 ÷ 7 = 7; 7 ÷ 7 = 1 -> 2² × 5 × 7².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62444511-f024-453d-a704-b1e4413a35fa', '2 × 2 × 5 × 7 × 7 (2² × 5 × 7²)', true, '547948a0-22e4-4ae8-a47c-b48917217de0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adef386f-33f3-423e-8b6c-9f3b8ba29422', '2 × 5 × 7 × 14', false, '547948a0-22e4-4ae8-a47c-b48917217de0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb5bf4ca-3d88-4628-a6e2-ce736c97c5ac', '4 × 5 × 49', false, '547948a0-22e4-4ae8-a47c-b48917217de0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f08f097d-b48c-442c-aea7-313f07d7b288', '2 × 2 × 2 × 5 × 7', false, '547948a0-22e4-4ae8-a47c-b48917217de0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac6e1cb7-7639-4bf9-9c2f-5a82e3267e88', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'Find the HCF of 18, 54, and 81:', '18 = 2 × 3²; 54 = 2 × 3³; 81 = 3⁴. Common prime factors with lowest powers = 3² = 9.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fdcdb41-6895-43a6-ab27-2c39b6744a46', '9', true, 'ac6e1cb7-7639-4bf9-9c2f-5a82e3267e88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20e2bade-6143-4d2e-b873-96127e595a6a', '18', false, 'ac6e1cb7-7639-4bf9-9c2f-5a82e3267e88');
