INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ad30fae-1bda-4e34-ab2b-058206790cd1', '27', false, 'ac6e1cb7-7639-4bf9-9c2f-5a82e3267e88');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f62fc7d-839a-43cd-bc2b-20a4c37dfc22', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'Find the LCM of 12, 16, and 24:', '12 = 2² × 3; 16 = 2⁴; 24 = 2³ × 3. LCM = highest powers of primes = 2⁴ × 3 = 16 × 3 = 48.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b10a07f5-a38c-4934-9d60-0a05baa1d5fc', '48', true, '5f62fc7d-839a-43cd-bc2b-20a4c37dfc22');
