INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6d0321c-f0c9-40a4-9f81-7a6dedf01740', '72', false, '5f62fc7d-839a-43cd-bc2b-20a4c37dfc22');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a727434-37ab-41b8-bbc3-0adcafe5fa51', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'What is the HCF of two consecutive EVEN numbers (like 6 and 8, or 10 and 12)?', 'Consecutive even numbers are 2k and 2k + 2 = 2(k + 1). Since k and k + 1 are co-prime, HCF = 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68c1f7d9-de42-4f4c-9f41-95bd7eed5ccf', '2', true, '1a727434-37ab-41b8-bbc3-0adcafe5fa51');
