INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('317a8396-ff68-45eb-872d-84d30b5d3791', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'What is the HCF of two consecutive ODD numbers (like 7 and 9, or 15 and 17)?', 'Consecutive odd numbers share no common factor greater than 1; their HCF is always 1.', NOW()) ON CONFLICT DO NOTHING;
