INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6bb0c0a6-a463-4a95-8636-8f4947ea3afd', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'Which of the following numbers is divisible by 11: 61809 or 1331?', 'For 1331: (1+3)-(3+1)=0 (div by 11). For 61809: (9+8+6)-(0+1)=23-1=22 (div by 11). Both are divisible.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31e233b8-675b-4ace-a4fb-4fcc7c76a344', 'Both 61809 and 1331', true, '6bb0c0a6-a463-4a95-8636-8f4947ea3afd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe9de3b6-da37-47b9-b5e0-63103c2e902e', '1331 only', false, '6bb0c0a6-a463-4a95-8636-8f4947ea3afd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e00c3f9b-4e7c-450f-be1e-cf0a470d7fc8', '61809 only', false, '6bb0c0a6-a463-4a95-8636-8f4947ea3afd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea354d7b-2635-4dae-bdc3-7a69a0d5f7fc', 'Neither of them', false, '6bb0c0a6-a463-4a95-8636-8f4947ea3afd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb993215-2ae8-4b08-9fd2-c79b97531288', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'Two tankers contain 850 litres and 680 litres of kerosene oil respectively. Find the maximum capacity of a container which can measure the kerosene of both tankers when used an exact number of times:', '850 = 170 × 5; 680 = 170 × 4. HCF(850, 680) = 170 litres.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0266526b-5dc0-4540-bd24-9f23c093588b', '170 litres (HCF of 850 and 680)', true, 'cb993215-2ae8-4b08-9fd2-c79b97531288');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9911873-48fb-48c0-840e-355b8098a8c0', '85 litres', false, 'cb993215-2ae8-4b08-9fd2-c79b97531288');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('743375a9-e6ac-479e-a7db-56eeb05f49b7', '340 litres', false, 'cb993215-2ae8-4b08-9fd2-c79b97531288');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d00064b-e42d-41e7-ae3f-6c87519de25e', '100 litres', false, 'cb993215-2ae8-4b08-9fd2-c79b97531288');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5905748d-35a0-41b2-82e8-9ea87da1f946', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'Three boys step off together from the same spot. Their steps measure 63 cm, 70 cm, and 77 cm respectively. What is the minimum distance each should cover so that all can cover the distance in complete steps?', 'Minimum distance = LCM(63, 70, 77) = 7 × 9 × 10 × 11 = 6,930 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e40a8c2d-1194-4b1b-9818-effbf6acc120', '6,930 cm (= 69 m 30 cm)', true, '5905748d-35a0-41b2-82e8-9ea87da1f946');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4bafe86-f245-4e3a-958b-183cca9ffdb3', '6,300 cm', false, '5905748d-35a0-41b2-82e8-9ea87da1f946');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2be1ec50-991b-4ac4-aa38-9d2a419bd2d5', '7,700 cm', false, '5905748d-35a0-41b2-82e8-9ea87da1f946');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64d61b11-73b3-4d49-ad93-1580f3187af5', '5,400 cm', false, '5905748d-35a0-41b2-82e8-9ea87da1f946');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6947bb35-f4c3-4a77-9319-cbb397b69a13', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'What is the smallest 3-digit number which is exactly divisible by 6, 8, and 12?', 'LCM(6, 8, 12) = 24. Smallest 3-digit multiple of 24 = 24 × 5 = 120.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('436084b2-d898-4771-8b15-735ba511f08c', '120', true, '6947bb35-f4c3-4a77-9319-cbb397b69a13');
