INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77625c49-b8fa-4564-884f-4a6e92ac5db7', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'Find the least number which when divided by 6, 15, and 18 leaves a remainder of 5 in each case:', 'LCM(6, 15, 18) = 90. Required number = LCM + remainder = 90 + 5 = 95.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edf6a11e-618d-44ee-8aa0-e6e73cc4f9bb', '95', true, '77625c49-b8fa-4564-884f-4a6e92ac5db7');
