INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19a8078d-2c37-4455-92ed-d2cc2204cf17', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Medium', 'Which of the following pairs of numbers are Co-prime?', 'HCF(18, 35) = 1; HCF(15, 37) = 1; HCF(81, 16) = 1. All three pairs share no common factor other than 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('692753c4-6162-4549-8fb0-33d529a9ad92', '18 and 35', false, '19a8078d-2c37-4455-92ed-d2cc2204cf17');
