INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6e4ebd4-61b9-4519-bef4-2ababb32644e', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Hard', 'The traffic lights at three different road crossings change after every 48 seconds, 72 seconds, and 108 seconds respectively. If they change simultaneously at 7:00 AM, at what time will they change simultaneously again?', 'LCM(48, 72, 108) = 432 seconds = 7 minutes 12 seconds. Time = 7:07:12 AM.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('287cea16-fd7f-4383-a7dc-0028aca4f8ff', '7:07:12 AM (7 hours 7 minutes 12 seconds AM)', true, 'f6e4ebd4-61b9-4519-bef4-2ababb32644e');
