INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a559ad2e-851a-4542-abec-40b01b1e6219', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Hard', 'Determine the greatest 3-digit number which is exactly divisible by 8, 10, and 12:', 'LCM(8, 10, 12) = 120. Largest 3-digit number 999 ÷ 120 = 8 with remainder 39. Greatest multiple = 999 - 39 = 960.', NOW()) ON CONFLICT DO NOTHING;
