INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fbd78892-339e-4c71-88ac-4980f53106e3', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Hard', 'Match the numbers in Column I with their properties in Column II:
(a) 35 -> (i) Multiple of 8
(b) 15 -> (ii) Factor of 30
(c) 16 -> (iii) Multiple of 7
(d) 20 -> (iv) Factor of 20', '35 = multiple of 7 (7×5); 15 = factor of 30 (30÷15=2); 16 = multiple of 8 (8×2); 20 = factor of 20.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0e82bf6-69ab-4b49-833c-11167f1fadab', 'a-(iii), b-(ii), c-(i), d-(iv)', true, 'fbd78892-339e-4c71-88ac-4980f53106e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70d64611-a7a9-4077-b8d9-4f5895684edc', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'fbd78892-339e-4c71-88ac-4980f53106e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d62c779-052e-47fb-b366-4b2ba1207746', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'fbd78892-339e-4c71-88ac-4980f53106e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50cd4e9e-83a0-493f-8a13-a9b6795dffd5', 'a-(ii), b-(iv), c-(i), d-(iii)', false, 'fbd78892-339e-4c71-88ac-4980f53106e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6932633f-a720-4e25-a6ec-3b3c86372f60', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Hard', 'In the 6-digit number 92_389, replace the blank (_) with the smallest digit so that the number becomes divisible by 11:', 'Odd place sum = 9 + 3 + 2 = 14. Even place sum = 8 + _ + 9 = 17 + _. (17 + _) - 14 = 3 + _ must equal 11 -> _ = 8.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('470a13db-7f0d-4dc0-98af-e961fb82d0c1', '8', true, '6932633f-a720-4e25-a6ec-3b3c86372f60');
