INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7dd75a23-d7a1-434d-ba87-1324c4f4cede', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Hard', 'What is the Prime Factorisation of the smallest 5-digit number (10,000)?', '10,000 = 10⁴ = (2 × 5)⁴ = 2⁴ × 5⁴ = 16 × 625 = 10,000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3bf9d2f-9c3f-4151-abaa-fa514321d7c5', '2⁴ × 5⁴ (2 × 2 × 2 × 2 × 5 × 5 × 5 × 5)', true, '7dd75a23-d7a1-434d-ba87-1324c4f4cede');
