INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4245972d-b8ca-450e-85b4-432fd66ec2a0', '2³ × 5⁴', false, '7dd75a23-d7a1-434d-ba87-1324c4f4cede');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2562972-c0ee-4cd6-b50a-68d68cc5d3a4', '10⁴', false, '7dd75a23-d7a1-434d-ba87-1324c4f4cede');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da15b04d-2cef-44fe-a70b-d889ec2cca3d', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Hard', 'The HCF and LCM of two numbers are 12 and 240 respectively. If one of the numbers is 48, what is the other number?', 'Product of two numbers = HCF × LCM -> 48 × y = 12 × 240 = 2,880 -> y = 2,880 ÷ 48 = 60.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b893de5-b6ab-4ae0-94e2-488746db76ba', '60', true, 'da15b04d-2cef-44fe-a70b-d889ec2cca3d');
