INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b6db8689-cb9f-4e80-828f-1bd19545c131', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Hard', 'Express the number 44 as the sum of two odd primes:', 'Goldbach''s partition: 3 and 41 are both odd prime numbers and 3 + 41 = 44.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('551f9299-eaad-47ba-933d-2fae48ff4a30', '3 + 41 (or 7 + 37, 13 + 31)', true, 'b6db8689-cb9f-4e80-828f-1bd19545c131');
