INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2c6f5b3b-1905-4671-bcb0-ad8ca7eefb81', 'Class 6', 'Mathematics', 'Chapter 3: Playing with Numbers', 'Hard', 'Find the greatest number which will divide 136, 170, and 255 leaving zero remainder in each case:', '136 = 17 × 8; 170 = 17 × 10; 255 = 17 × 15. HCF(136, 170, 255) = 17.', NOW()) ON CONFLICT DO NOTHING;
