INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('671dc05b-51d7-44f5-a295-d6c3925a958c', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'What profession did young Taro pursue for a living?', 'Taro was a young Japanese woodcutter who chopped wood on the hillside all day long.', NOW()) ON CONFLICT DO NOTHING;
