INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8778b0a4-27d1-425f-88b2-9ada4959140b', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'Where did Taro live with his elderly parents?', 'Taro lived with his old mother and father in a small wooden hut on a lonely mountainside.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a851a652-9039-4c75-bab9-974dd9be9aa9', 'On a lonely hillside in Japan', true, '8778b0a4-27d1-425f-88b2-9ada4959140b');
