INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b61687c-6366-4fdb-a457-5e4ca5014656', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'What did Taro''s old father wish for on a very cold, windy evening?', 'Feeling the icy wind through the cracks of the hut, Taro''s shivering father wished for a cup of nourishing sake.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7989e04-6bcd-4f9f-9c4d-3c586ce22ffe', 'A cup of sake (a warm, expensive Japanese drink) to warm his heart', true, '6b61687c-6366-4fdb-a457-5e4ca5014656');
