INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a300192-d3b1-4614-af1d-56a9ad188ced', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'Why was Taro deeply saddened by his father''s wish for sake?', 'Taro was heartbroken because his meager earnings could not afford the costly traditional beverage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c53a513-3d42-4598-b630-3b82a341c48f', 'Because sake was very expensive, and Taro earned very little money from chopping wood', true, '9a300192-d3b1-4614-af1d-56a9ad188ced');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eeda721d-dc71-414a-890a-bbbf316f067b', 'Because sake was forbidden in the village', false, '9a300192-d3b1-4614-af1d-56a9ad188ced');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1f8cabc-a8a0-48fa-bbf9-b092909991c1', 'Because the shops were closed', false, '9a300192-d3b1-4614-af1d-56a9ad188ced');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd8c9803-6319-4bdb-b316-a07a8f3e44cb', 'Because Taro disliked his father', false, '9a300192-d3b1-4614-af1d-56a9ad188ced');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03d1e5d6-14f5-4c2a-a943-0857f3be1882', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'What did Taro do the next morning to earn more money for the sake?', 'Motivated by filial love, Taro ventured into the deep forest at dawn to chop and split extra logs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d4741c4-5a2a-4df3-947c-71fff9d66daf', 'He woke up earlier than usual and hurried to the forest to chop extra wood', true, '03d1e5d6-14f5-4c2a-a943-0857f3be1882');
