INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01647c90-9213-4171-b852-61d8ae890a39', 'He went to the Emperor''s court', false, '03d1e5d6-14f5-4c2a-a943-0857f3be1882');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d162575b-9b02-4a08-826b-2049d2d5db86', 'He caught fish in the river', false, '03d1e5d6-14f5-4c2a-a943-0857f3be1882');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('de9fd4a9-9b10-4dc5-9cdc-ca0619cafb09', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'What unexpected sound surprised Taro while he was chopping wood in the forest?', 'Thirsty from his hard labor, Taro heard the sound of rushing water where no stream had previously existed.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1526d1f2-3117-4fe7-b786-1ca5f7bc991e', 'The sound of rushing, splashing water from a hidden waterfall', true, 'de9fd4a9-9b10-4dc5-9cdc-ca0619cafb09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0747532f-80f9-41b2-b142-edae25196db5', 'A roaring tiger', false, 'de9fd4a9-9b10-4dc5-9cdc-ca0619cafb09');
