INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b478c176-18d9-4155-b205-539ed500dcfc', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'When Taro cupped a little of the waterfall liquid in his hands and tasted it, what was it?', 'To Taro''s utter delight, the magical waterfall tasted like rich, warm, delicious sake.', NOW()) ON CONFLICT DO NOTHING;
