INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d8a75f5-02ea-42dd-a575-56200c499c72', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'What container did Taro fill with the magical sake to carry home to his father?', 'Taro hurriedly filled his personal wooden pitcher and ran home joyfully to his father.', NOW()) ON CONFLICT DO NOTHING;
