INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e457f21-4a1d-489a-bb72-12b579fa2b33', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'What physical effect did the sake have on Taro''s elderly father?', 'The nourishing warmth invigorated the old man so much that he happily danced on the floor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d602d788-0da0-469c-b046-6d39ce31496c', 'He stopped shivering immediately and did a joyful little dance in the middle of the floor', true, '4e457f21-4a1d-489a-bb72-12b579fa2b33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07768e40-56a9-46f6-86ff-867ae84892ee', 'He fell into a deep sleep for two days', false, '4e457f21-4a1d-489a-bb72-12b579fa2b33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2844bf2-d77c-47b8-b89d-65b74b87a139', 'He became young again', false, '4e457f21-4a1d-489a-bb72-12b579fa2b33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85ee90a8-a434-4cbc-b421-7a11647953c7', 'He grew taller', false, '4e457f21-4a1d-489a-bb72-12b579fa2b33');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7327ee0-fc44-4b6b-81e6-003a2677d040', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'How did the entire village learn about the magical sake waterfall by evening?', 'The neighbor lady hastily spread the gossip across the entire hamlet before nightfall.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14d61a66-0dc7-42a1-b3f7-e271a54958a1', 'A visiting neighbor lady drank a cup, heard the whole story from the father, and spread the news from house to house', true, 'b7327ee0-fc44-4b6b-81e6-003a2677d040');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7f8a1fd-b246-47e4-b99f-f57400240a3d', 'Taro put up a notice in the marketplace', false, 'b7327ee0-fc44-4b6b-81e6-003a2677d040');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a33226ed-816b-490f-b17b-11b7f8fb2927', 'The Emperor sent messengers', false, 'b7327ee0-fc44-4b6b-81e6-003a2677d040');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e16b671-fc0e-4015-86e1-9c2b0b9aef89', 'A bird announced it', false, 'b7327ee0-fc44-4b6b-81e6-003a2677d040');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b0a7982-c765-4688-8bba-bab1fe2e7438', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'How did the Emperor of Japan honor and reward Taro for his profound devotion and kindness?', 'The Emperor rewarded Taro with 20 gold coins and named the grandest imperial fountain after him to inspire all children to honor parents.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e46e1889-ac6e-4b14-81f1-9917b683c426', 'He rewarded him with twenty pieces of gold and named the most beautiful fountain in the city after Taro', true, '8b0a7982-c765-4688-8bba-bab1fe2e7438');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1cec89b-c115-4c00-a530-0d24e213141a', 'He made Taro the commander of the army', false, '8b0a7982-c765-4688-8bba-bab1fe2e7438');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32358c55-8d61-4e1a-b295-3c03620ec2f0', 'He gave Taro a palace made of glass', false, '8b0a7982-c765-4688-8bba-bab1fe2e7438');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38b0ff44-2eff-408f-bad6-583c6f791f33', 'He gave him a flying horse', false, '8b0a7982-c765-4688-8bba-bab1fe2e7438');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a1e53d51-05c9-4e59-a1eb-6c59b27d408d', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Easy', 'In the supplementary tale ''The Shepherd''s Treasure'', where did the wise shepherd live?', 'The humble, uneducated yet deeply wise shepherd lived in a poor village in ancient Iran.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d55709c7-5bfc-4274-8775-04f2c0cb49b6', 'In a village in Iran (Persia)', true, 'a1e53d51-05c9-4e59-a1eb-6c59b27d408d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('824692bb-1bf4-45f0-b1a2-438a872d19af', 'In the mountains of Japan', false, 'a1e53d51-05c9-4e59-a1eb-6c59b27d408d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6fcf1b6-5b05-4658-bde5-141b55fdcade', 'In an Indian forest', false, 'a1e53d51-05c9-4e59-a1eb-6c59b27d408d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7acac565-a8c7-4f0f-bf9c-50440d5a4a08', 'In a palace in Egypt', false, 'a1e53d51-05c9-4e59-a1eb-6c59b27d408d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('05bf0a11-407b-435a-bce5-349b04a048ae', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'What happened when the greedy villagers rushed with pitchers and buckets to the waterfall the next morning?', 'The magic waterfall gave delicious sake only to thoughtful, devoted Taro, but gave only cold water to greedy villagers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86463531-00d0-47dd-abce-cb14d5639caf', 'The waterfall yielded only plain, ice-cold water to everyone else because of their selfish greed', true, '05bf0a11-407b-435a-bce5-349b04a048ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49356dd6-4450-46e4-926d-289a7259a969', 'The waterfall dried up instantly', false, '05bf0a11-407b-435a-bce5-349b04a048ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd1f0da6-5d6b-4408-823c-3ae39bcf7d55', 'The waterfall gave boiling hot soup', false, '05bf0a11-407b-435a-bce5-349b04a048ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3c03393-f4bc-4657-8adb-9f8d7a7b45be', 'The waterfall turned into poison', false, '05bf0a11-407b-435a-bce5-349b04a048ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4f8bb8f-e27a-4672-8861-1229d9917028', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'Why were the villagers furious with Taro at the waterfall, muttering ''We have been tricked!''?', 'Expecting fine free sake, the villagers tasted only cold water and angrily threatened to drown Taro in the pool.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('494d9ee5-24a2-46bf-b57b-84bc4dea718b', 'They tasted the water repeatedly and found it was ordinary cold water, suspecting Taro had fooled them', true, 'd4f8bb8f-e27a-4672-8861-1229d9917028');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('699fcad2-90b8-48e3-889a-4972e6ebc02c', 'Taro stole their buckets', false, 'd4f8bb8f-e27a-4672-8861-1229d9917028');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c24499f-3185-40a9-ace8-5c8b159be906', 'The waterfall wet their clothes', false, 'd4f8bb8f-e27a-4672-8861-1229d9917028');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0ea41a9-f2f1-437d-bb0c-05ad8c4328ba', 'The forest was too dark', false, 'd4f8bb8f-e27a-4672-8861-1229d9917028');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b828c5d-80de-4b41-b19e-496da786ff9d', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'In ''The Shepherd''s Treasure'', what made the King of Iran disguise himself as a shepherd riding on a mule?', 'Fascinated by reports of the poor shepherd''s extraordinary wisdom, the King went disguised to assess his character.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6df37a39-867a-4490-a6dc-d163604749b7', 'To personally visit and test the famous wisdom, humility, and hospitality of the poor shepherd', true, '4b828c5d-80de-4b41-b19e-496da786ff9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a96fb54d-b831-4d54-8d89-2b643a4863fd', 'To escape from enemy soldiers', false, '4b828c5d-80de-4b41-b19e-496da786ff9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e6be1fd-a04f-46c5-8385-58214bdbd456', 'To hunt wild deer in the mountains', false, '4b828c5d-80de-4b41-b19e-496da786ff9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('409e29f6-a743-4910-bd29-88a6d07efa8f', 'To look for hidden gold', false, '4b828c5d-80de-4b41-b19e-496da786ff9d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a9874dc-1a67-4222-b104-d4dd5b4ee6a8', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'How did the poor shepherd treat the disguised King who arrived at his cave door exhausted?', 'The shepherd welcomed the stranger warmly, offering fresh water and half of his modest meal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbcd2056-5873-45ff-b385-8b99a7e57e47', 'With warm hospitality: sharing his own meager supper of food, fresh spring water, and shelter for the night', true, '9a9874dc-1a67-4222-b104-d4dd5b4ee6a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cb135dd-782b-4fe3-836e-97dbf70674f9', 'He asked for payment before opening the door', false, '9a9874dc-1a67-4222-b104-d4dd5b4ee6a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89bc7e12-8349-4917-a55f-6d800a238eef', 'He told the traveler to sleep in the cold', false, '9a9874dc-1a67-4222-b104-d4dd5b4ee6a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33f98133-6a41-4a16-9a19-b21a8fa21a10', 'He reported him to the police', false, '9a9874dc-1a67-4222-b104-d4dd5b4ee6a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('babf96f1-6a50-4947-9a93-c6ecc5c81972', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'What position did the impressed King bestow upon the wise shepherd?', 'Deeply impressed by his natural wisdom, justice, and kindness, the King appointed him Governor of a district.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44aee1d4-8d61-4629-910a-e4d9635e54b1', 'Governor of a small district', true, 'babf96f1-6a50-4947-9a93-c6ecc5c81972');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4abcdbc7-02f1-4835-88c2-3481681c7a09', 'Chief General of the army', false, 'babf96f1-6a50-4947-9a93-c6ecc5c81972');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05ef7829-a9b9-4637-b4f2-3e803e9dd426', 'Imperial Treasurer', false, 'babf96f1-6a50-4947-9a93-c6ecc5c81972');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2f0a741-9fa8-4c68-929e-46c555f54599', 'Royal Cook', false, 'babf96f1-6a50-4947-9a93-c6ecc5c81972');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e39a1f79-67e9-48b5-a9cb-2b0d576295a1', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'Why did other jealous governors in neighboring provinces plot against the new shepherd-governor?', 'His incorruptible justice and widespread public adoration provoked bitter jealousy among the corrupt aristocrats.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d02150bf-06e0-4954-b370-b09de9a6db00', 'They were intensely envious of his soaring popularity, wisdom, and the King''s immense trust in him', true, 'e39a1f79-67e9-48b5-a9cb-2b0d576295a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('327966bd-77a4-41d7-95a0-0f3be0f8ebc3', 'He stole money from their provinces', false, 'e39a1f79-67e9-48b5-a9cb-2b0d576295a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40f88c59-e77b-4d3d-9485-0fe86137fb8c', 'He refused to wear fine clothes', false, 'e39a1f79-67e9-48b5-a9cb-2b0d576295a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb99c113-6f2e-4a2e-a041-efd36a121258', 'He closed all markets', false, 'e39a1f79-67e9-48b5-a9cb-2b0d576295a1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('321bc6ff-7b6a-4a1b-bde3-c8bae01eacf5', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'What false accusation did the jealous governors bring against the shepherd-governor before the King?', 'They falsely alleged that the iron box he always carried contained embezzled tax revenues.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f746fb9c-76f9-45e5-9779-a7002e0ea876', 'They claimed he was dishonest and secretly carried stolen tax gold in an iron chest strapped to his camel''s back', true, '321bc6ff-7b6a-4a1b-bde3-c8bae01eacf5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8be87ac-6124-4ffb-bd41-9745d35176f8', 'They claimed he was an enemy spy', false, '321bc6ff-7b6a-4a1b-bde3-c8bae01eacf5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7fb312e-7cfd-4da3-bf48-9b749139e73c', 'They said he murdered a merchant', false, '321bc6ff-7b6a-4a1b-bde3-c8bae01eacf5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11d36eb4-34f8-4d19-9b80-9b596eda90b2', 'They said he refused to pay respect to the King', false, '321bc6ff-7b6a-4a1b-bde3-c8bae01eacf5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('abf9ef15-cedf-4aeb-b37d-db4ecfb8b4fb', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'When the King ordered the iron chest to be opened in the royal court, what was discovered inside?', 'The chest contained only his humble old woollen blanket, which he kept as a reminder of his true self.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b38b406-3f40-4a35-b1a5-67f38e4ed54d', 'No gold, jewels, or silver — only an old, worn-out woollen blanket', true, 'abf9ef15-cedf-4aeb-b37d-db4ecfb8b4fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c644595-e2d6-4e54-89b7-6cc4e6e71a53', 'A hoard of glittering diamonds and gold coins', false, 'abf9ef15-cedf-4aeb-b37d-db4ecfb8b4fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8b93f35-9182-4634-9479-406888e91060', 'A bundle of secret enemy maps', false, 'abf9ef15-cedf-4aeb-b37d-db4ecfb8b4fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edba7187-b20b-43a5-8f4e-d0a0912a816f', 'The box was completely empty', false, 'abf9ef15-cedf-4aeb-b37d-db4ecfb8b4fb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c44a365f-fd80-4123-ac49-683f109b2c74', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'Why did the shepherd-governor always carry his old blanket everywhere with him?', 'The blanket symbolized true humility; if fortune and titles vanished, his honest blanket would remain his steadfast shield.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23036e5c-0a63-43bc-8bf8-4a1c3256f199', 'Because it was his oldest friend that would still protect him from cold even if the King stripped him of all titles and royal cloaks', true, 'c44a365f-fd80-4123-ac49-683f109b2c74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1298c3f-628b-4460-aa21-a09f4404d981', 'Because it had magical flying powers', false, 'c44a365f-fd80-4123-ac49-683f109b2c74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b4edff7-99bb-44ef-86e0-565b3f4bf27f', 'Because it was given by a wizard', false, 'c44a365f-fd80-4123-ac49-683f109b2c74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5444e878-8ece-4034-ac19-0c86bb8bd4c2', 'Because it was very heavy', false, 'c44a365f-fd80-4123-ac49-683f109b2c74');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6dd88aff-2410-4a68-8f7b-05df257a7a25', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'What did the King do after witnessing the shepherd''s supreme humility, honesty, and wisdom?', 'Vindicated and moved by his sterling character, the King promoted the shepherd to govern a much larger province.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72ad467f-68ed-4e16-bdad-296377bfc3c9', 'He made him the governor of a much bigger district and publicly shamed the jealous accusers', true, '6dd88aff-2410-4a68-8f7b-05df257a7a25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ac435ce-3d16-47a6-a70c-37129559a8b0', 'He dismissed him from service', false, '6dd88aff-2410-4a68-8f7b-05df257a7a25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2580ba8-13fe-4c90-924c-e3998a5d219a', 'He confiscated his blanket', false, '6dd88aff-2410-4a68-8f7b-05df257a7a25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59085a63-e8f9-4e2b-b4b4-1d825d866a36', 'He sent him back to his cave', false, '6dd88aff-2410-4a68-8f7b-05df257a7a25');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32530022-82f4-4919-aca2-f09164504371', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'What does the word ''Whistled through'' mean in: ''A cold wind whistled through the cracks of the hut''?', 'Describing the high-velocity freezing gale producing a sharp aerodynamic whistling noise through timber crevices.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcffd2cf-c61b-4d78-bf04-2ea464dd7cae', 'Passed through making a shrill whistling sound', true, '32530022-82f4-4919-aca2-f09164504371');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('417ffa40-4001-48f9-8dbd-1e4710a3f87c', 'Blew the hut away completely', false, '32530022-82f4-4919-aca2-f09164504371');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8aca2f9-2519-47cd-9ca4-0b0b5a64e160', 'Played a flute', false, '32530022-82f4-4919-aca2-f09164504371');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20758ee7-c4d6-45de-9426-cec1c32245a9', 'Made the house warm', false, '32530022-82f4-4919-aca2-f09164504371');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58fc94d5-444f-4070-a6b0-72f29ad2426f', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'What is the meaning of the word ''Pitted'' or ''Pitcher'' in the story of Taro?', 'A pitcher is a container (often with a handle and lip) designed to carry and dispense potable liquids.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bacef6a-f863-4aaa-8737-6637b741963d', 'A pot / vessel made of earthenware or wood for holding liquids', true, '58fc94d5-444f-4070-a6b0-72f29ad2426f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e222932-3ce7-4ce1-ae23-dd6845897980', 'A baseball player', false, '58fc94d5-444f-4070-a6b0-72f29ad2426f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09f051d3-315d-4df3-980a-a4bb63463c65', 'A sharp axe', false, '58fc94d5-444f-4070-a6b0-72f29ad2426f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71cd492d-b4ac-4c16-9c2b-818fc20399c2', 'A wooden cart', false, '58fc94d5-444f-4070-a6b0-72f29ad2426f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('213744f8-0b58-4463-82ab-80ea57ac1d5a', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'What does the phrase ''to chop and hew'' mean in describing Taro''s labor?', '''Hew'' means to hack, shape, or fell timber using sharp heavy cutting tools.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6234fe69-4ad9-4c8a-b10c-1e5ec0300c76', 'To cut down trees and strike wood with repeated heavy blows of an axe', true, '213744f8-0b58-4463-82ab-80ea57ac1d5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a342c5b5-bad1-4a49-84ae-122e8c855388', 'To paint timber', false, '213744f8-0b58-4463-82ab-80ea57ac1d5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82909736-62ab-4c20-9801-8ed539f9aadc', 'To plant new saplings', false, '213744f8-0b58-4463-82ab-80ea57ac1d5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5802bf75-4808-41cd-839c-561df460bcb7', 'To climb trees', false, '213744f8-0b58-4463-82ab-80ea57ac1d5a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd783d27-b08c-465a-980f-18b765541c37', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'Why did Taro hide behind a rock when the villagers arrived at the waterfall?', 'Prudent Taro concealed himself until the shouting, disappointed mob departed back to the village.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('824969d9-4835-4c43-b8df-50c862d73a0d', 'He saw their wild fury and did not want to face their violent anger when they found only water', true, 'fd783d27-b08c-465a-980f-18b765541c37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cb4b071-3418-4c29-bfed-3d2d7644c7fb', 'He wanted to scare them', false, 'fd783d27-b08c-465a-980f-18b765541c37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abe6aa37-2304-4cb7-9d2d-1f13b0911528', 'He fell asleep behind the rock', false, 'fd783d27-b08c-465a-980f-18b765541c37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09171438-8dd9-4133-ba8d-82608d74fa72', 'He was waiting for the Emperor', false, 'fd783d27-b08c-465a-980f-18b765541c37');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6f373e5-f181-42f9-92fe-7cfb5b484720', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'What is the primary moral message of ''Taro''s Reward'' for young children?', 'The tale exemplifies the virtues of filial piety, selfless love, and honest industrious labor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dd9139f-0cff-48e4-aaed-ac2823f93e63', 'Diligence, thoughtful care, and profound devotion to one''s parents earn the highest divine and human rewards', true, 'e6f373e5-f181-42f9-92fe-7cfb5b484720');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8a992d8-6a76-4fcc-8d8d-79c6e7157b98', 'Magic waterfalls exist in every mountain', false, 'e6f373e5-f181-42f9-92fe-7cfb5b484720');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8731a942-6ff0-442d-93cd-84755bfd6df3', 'Greed always brings wealth', false, 'e6f373e5-f181-42f9-92fe-7cfb5b484720');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65574bda-efce-4a9c-ac3f-74ebab8ded5a', 'Woodcutting is the best job', false, 'e6f373e5-f181-42f9-92fe-7cfb5b484720');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fb2fc99c-aa66-4f75-ab10-c62794c32e08', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Medium', 'In ''The Shepherd''s Treasure'', how is true nobility of character demonstrated?', 'Inner virtue, incorruptibility, and humility outshine all artificial titles, wealth, and ancestral pedigree.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0113432a-6f24-4b1c-8e23-c3fa06f2c300', 'Through steadfast humility, unwavering honesty, and wisdom, regardless of one''s humble birth or elevated royal station', true, 'fb2fc99c-aa66-4f75-ab10-c62794c32e08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b64adee-adf3-4418-89b5-f88091e5b46c', 'Through wearing expensive gold ornaments', false, 'fb2fc99c-aa66-4f75-ab10-c62794c32e08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a33707a-a7a8-48d4-b6fc-0e5057dfc9e8', 'Through defeating enemies in battle', false, 'fb2fc99c-aa66-4f75-ab10-c62794c32e08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7abc7a8d-b6ed-40cd-9649-44f3fe6c3434', 'Through collecting high taxes', false, 'fb2fc99c-aa66-4f75-ab10-c62794c32e08');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b13b965b-01e5-4315-93a5-1dd102ac4d49', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e74b8a1-6d16-4482-b75f-e360e739434f', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'b13b965b-01e5-4315-93a5-1dd102ac4d49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b606e522-3367-4dac-9dbd-39d7a16c2c00', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'b13b965b-01e5-4315-93a5-1dd102ac4d49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('683d2a0b-9b1c-4aea-bd6a-59b576f498df', '(A) is true, but (R) is false.', false, 'b13b965b-01e5-4315-93a5-1dd102ac4d49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78975822-56f7-44fa-b772-532839b767b0', '(A) is false, but (R) is true.', false, 'b13b965b-01e5-4315-93a5-1dd102ac4d49');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('72b07a26-8f12-4758-b1e8-85794e0a1baf', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'Spot the IMPOSTER in the following group of vocabulary words from Chapter 3 paired with their meanings:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0e917c5-1f4f-4be3-b7d0-d240e980e0ae', 'Kneel - bend on knees', false, '72b07a26-8f12-4758-b1e8-85794e0a1baf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea160661-5c58-494c-aa58-0bcd74358fff', 'Gourd - a fleshy fruit/pitcher', false, '72b07a26-8f12-4758-b1e8-85794e0a1baf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c0bcb9e-6319-47dd-9f6d-a68b2dda9d23', 'Chieftain - a leader/ruler', false, '72b07a26-8f12-4758-b1e8-85794e0a1baf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65be72fc-a588-4b47-8518-e66b1d6c5c5e', 'Delighted - intensely angry', true, '72b07a26-8f12-4758-b1e8-85794e0a1baf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1925d08b-0183-4c8f-a885-e6e6a3ccee87', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'What profound psychological contrast is portrayed between Taro and the village community?', 'Taro toiled selflessly for his family, whereas the envious neighbors rushed en masse with pots purely for selfish indulgence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ebf5e47-8ad7-4078-95ee-1b41fed19e5a', 'Taro was driven by selfless love and extra toil to comfort his parents, while the villagers were driven by opportunistic greed to exploit free luxury', true, '1925d08b-0183-4c8f-a885-e6e6a3ccee87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55c8e9b2-f08b-4eea-8e9b-71c148f1d151', 'Taro was lazy while the villagers worked hard', false, '1925d08b-0183-4c8f-a885-e6e6a3ccee87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e577c6f-2789-4349-ba0a-bd7350c4f02a', 'Taro was greedy for gold', false, '1925d08b-0183-4c8f-a885-e6e6a3ccee87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('097fe3df-03ad-497a-926f-31e1d7ec6d4d', 'The villagers wanted to help Taro''s father', false, '1925d08b-0183-4c8f-a885-e6e6a3ccee87');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dced7822-0160-4d1e-a4f5-7e000915a2c0', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'In ''The Shepherd''s Treasure'', what symbolic meaning did the old woollen blanket hold for the wise governor?', 'The blanket preserved his philosophical humility, ensuring he never succumbed to arrogance or the vanity of royal office.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14ea28de-8ede-4c2a-a451-8aec9a86a200', 'It was a grounding talisman of his humble origins, reminding him that worldly power is fleeting and moral integrity is eternal', true, 'dced7822-0160-4d1e-a4f5-7e000915a2c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2d5971a-47fa-4b35-b0cf-90c80c36afc5', 'It contained a hidden treasure map sewn in the seam', false, 'dced7822-0160-4d1e-a4f5-7e000915a2c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49b69cab-d8f8-4f1f-916f-ff1b1087ab33', 'It was worth millions of gold dinars', false, 'dced7822-0160-4d1e-a4f5-7e000915a2c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84c1ddda-1447-4760-bc7e-cf642168dbe6', 'It was a royal gift from his grandfather', false, 'dced7822-0160-4d1e-a4f5-7e000915a2c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa6b27eb-dbdb-4ac8-800e-a02014658905', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'Match the following characters with their distinctive traits:
(a) Taro             -> (i) Wise, humble, and incorruptible
(b) Iranian Shepherd -> (ii) Inquisitive, just, and appreciative of true virtue
(c) The Persian King -> (iii) Selfless, hardworking, and devoted son
(d) Jealous Governors-> (iv) Malicious, corrupt, and envious', 'Taro = devoted son; Shepherd = wise & humble; King = just & appreciative; Governors = corrupt & envious.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f76b87f6-8331-49bb-8406-7eb82aa056c3', 'a-(iii), b-(i), c-(ii), d-(iv)', true, 'aa6b27eb-dbdb-4ac8-800e-a02014658905');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('717b414f-540b-48a3-9752-0eb4703f9f3f', 'a-(i), b-(iii), c-(ii), d-(iv)', false, 'aa6b27eb-dbdb-4ac8-800e-a02014658905');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2fa314c-ce4c-4b68-b21d-09b0252365f7', 'a-(iv), b-(ii), c-(i), d-(iii)', false, 'aa6b27eb-dbdb-4ac8-800e-a02014658905');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8e05690-0dc5-4df5-96ca-6d72c521a623', 'a-(ii), b-(iv), c-(iii), d-(i)', false, 'aa6b27eb-dbdb-4ac8-800e-a02014658905');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d17ad6a8-dbfd-4da0-9785-b02ec0b19565', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'Read the statements from the story:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed4bc09d-b1ca-448a-a43e-0ca5c0495847', 'Statements 1 and 3 only', true, 'd17ad6a8-dbfd-4da0-9785-b02ec0b19565');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecc5fa36-b0f2-4a14-850f-2a397da1133e', 'Statements 1 and 2 only', false, 'd17ad6a8-dbfd-4da0-9785-b02ec0b19565');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cc5615a-13c6-462c-9877-49d473bb8837', 'Statements 2 and 3 only', false, 'd17ad6a8-dbfd-4da0-9785-b02ec0b19565');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e04906e-2fb1-4f1e-b85a-96a5e9d8482f', 'All Statements 1, 2, and 3', false, 'd17ad6a8-dbfd-4da0-9785-b02ec0b19565');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e20b6b9-13b9-400d-9810-7d8adebf6846', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'Identify the part of speech of the underlined word in the sentence: ''Taro worked *harder* than ever to earn money.''', '''Harder'' modifies the verb ''worked'' in the comparative degree, functioning as an Adverb.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28eccdb0-dcff-43f8-8dec-dc0fee0e25f1', 'Adverb (Comparative degree)', true, '3e20b6b9-13b9-400d-9810-7d8adebf6846');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6f7aa24-f838-430c-a1ee-a1c7c6cff265', 'Adjective', false, '3e20b6b9-13b9-400d-9810-7d8adebf6846');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('723613c8-7966-4521-b242-e0874046c10f', 'Noun', false, '3e20b6b9-13b9-400d-9810-7d8adebf6846');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb95e5b2-59e9-4701-9f03-ec81869d474e', 'Preposition', false, '3e20b6b9-13b9-400d-9810-7d8adebf6846');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecbdc762-44f8-4f5a-86ce-929aa10b8521', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'What is the meaning of the idiomatic phrase ''to have one''s heart warmed'' in literature?', 'Metaphorical idiom expressing profound internal emotional comfort, solace, and gratitude.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b837893f-12c0-4b56-844b-45e168907c73', 'To feel deep emotional joy, satisfaction, affection, or gratitude', true, 'ecbdc762-44f8-4f5a-86ce-929aa10b8521');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f160d7bd-99b8-4b6d-a4ed-eff8fa000c10', 'To suffer from physical fever', false, 'ecbdc762-44f8-4f5a-86ce-929aa10b8521');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25d320ee-54f0-494c-a522-3c904a0808de', 'To sit too close to a fireplace', false, 'ecbdc762-44f8-4f5a-86ce-929aa10b8521');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0028779d-e6c6-4a98-9e29-64b34eabdf24', 'To drink hot water', false, 'ecbdc762-44f8-4f5a-86ce-929aa10b8521');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76fa78fc-7059-487c-9fd1-23a313df09f2', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'In ''The Shepherd''s Treasure'', why was the King delighted when the shepherd gave his famous answer about the blanket?', 'The shepherd''s humble reply vindicated the King''s original trust and utterly demolished the slanders of the jealous governors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e6e308f-7c0c-40f4-ac27-d08f361fd9cd', 'Because the shepherd proved beyond all doubt that he was truly the wisest, most honest, and uncorrupted man in the entire kingdom', true, '76fa78fc-7059-487c-9fd1-23a313df09f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('367c8de4-2742-498a-a2c6-8489a9f302f3', 'Because the King wanted to borrow the blanket', false, '76fa78fc-7059-487c-9fd1-23a313df09f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef5bc603-d759-49a1-baf0-e217d00f1a4f', 'Because the King found gold under the carpet', false, '76fa78fc-7059-487c-9fd1-23a313df09f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91cd75bc-0949-4372-a7db-ff18f87c4644', 'Because the court cheered for war', false, '76fa78fc-7059-487c-9fd1-23a313df09f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd318f0f-98f9-4bf8-aca3-72f3db86449f', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'Choose the correct sentence showcasing the proper use of the conjunction ''although'':', 'Concessive conjunction ''Although'' introduces a subordinate clause of contrast without combining with ''but''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb88d7d3-32d5-4242-8e86-3d2c759a7f42', 'Although Taro was poor, he never hesitated to work tirelessly for his parents'' comfort.', true, 'dd318f0f-98f9-4bf8-aca3-72f3db86449f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28f83572-fd8a-4215-97ff-8def56c72008', 'Although Taro was rich but he worked hard.', false, 'dd318f0f-98f9-4bf8-aca3-72f3db86449f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51166ec3-6db8-4ff7-a02f-cf474f841727', 'Taro although poor so he slept all day.', false, 'dd318f0f-98f9-4bf8-aca3-72f3db86449f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a465773f-0c01-4b87-a2ed-9deb387fd105', 'Although he worked but he earned gold.', false, 'dd318f0f-98f9-4bf8-aca3-72f3db86449f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ce4534b9-9b08-49af-a632-0dc096490b9b', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'What narrative structure is common to both ''Taro''s Reward'' and ''The Shepherd''s Treasure''?', 'Both classic didactic fables utilize a moral test where an underdog of supreme virtue is elevated by wise royal authority.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2ffb56e-e664-4d20-bece-371d52abcfe1', 'Both feature an undercover/mystical test of virtue where true moral integrity is rewarded by a sovereign ruler while shallow jealousy/greed is exposed', true, 'ce4534b9-9b08-49af-a632-0dc096490b9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76f6be5d-b95c-469f-a631-5d7b2ffabf71', 'Both are tragic tales ending in defeat', false, 'ce4534b9-9b08-49af-a632-0dc096490b9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0db660ea-eba9-429d-8081-a05d3d66148d', 'Both are science-fiction space stories', false, 'ce4534b9-9b08-49af-a632-0dc096490b9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a8945ce-ff1c-49f3-a99a-c0113dff0cf7', 'Both are set in modern Europe', false, 'ce4534b9-9b08-49af-a632-0dc096490b9b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25cecdde-2d62-4390-a6b0-45d664a6fc3b', 'Class 6', 'English', 'Chapter 3: Taro''s Reward', 'Hard', 'What is the synonym of ''muttered'' as used when the disappointed villagers left the waterfall?', '''Mutter'' means to speak indistinctly in low, suppressed tones of complaint or resentment.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('116b7a3c-6e7d-429a-a5ff-3b2c3f75a61a', 'Grumbeled / murmured in low dissatisfied tones', true, '25cecdde-2d62-4390-a6b0-45d664a6fc3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c743c04-35a4-435d-8d46-6e7a99f2d751', 'Shouted with immense joy', false, '25cecdde-2d62-4390-a6b0-45d664a6fc3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c40800b-2f0f-4b33-9410-9679bbaa8a73', 'Sang a song', false, '25cecdde-2d62-4390-a6b0-45d664a6fc3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9345e2a1-2b30-49d9-9a94-0fd145c7e0fd', 'Whistled happily', false, '25cecdde-2d62-4390-a6b0-45d664a6fc3b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3cba60c5-4c9a-4750-9b2d-a1bf8c2f2887', 'Class 6', 'GK', 'Chapter 3: Geography & Wonders of India', 'Easy', 'What is the highest mountain peak located entirely within the territory of India?', 'Kangchenjunga on the Sikkim-Nepal border is the 3rd highest peak in the world (8,586 m) and India''s highest.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bfd211a-457a-4945-8b33-94e5982e90c6', 'Kangchenjunga (8,586 meters, Sikkim)', true, '3cba60c5-4c9a-4750-9b2d-a1bf8c2f2887');
