INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94780def-8f2f-4961-9211-40593b39f2ba', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Easy', 'What causes the cycle of changing SEASONS (Summer, Winter, Spring, Autumn) on Earth?', 'Seasonal changes result from cyclical variations in solar insolation caused by Earth''s orbital revolution and persistent 23.5° axial tilt.', NOW()) ON CONFLICT DO NOTHING;
