INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ddeab61f-8a9a-4ae9-bd42-963ed4ba6166', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Easy', 'How much time does the Earth take to complete one full rotation on its axis (known as an ''Earthday'')?', 'Earth rotates 360° relative to the Sun in precisely 24 hours, defining our standard daily civil time.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb16d108-35da-4ec9-87d4-d5af1c7cd80c', '24 hours (1 solar day)', true, 'ddeab61f-8a9a-4ae9-bd42-963ed4ba6166');
