INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('12de9e78-565f-4e89-b1de-3dfa0dda441d', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Easy', 'How long does the Earth take to complete one full orbital revolution around the Sun?', 'One sidereal/tropical orbital revolution takes ~365.242 days (365 days and ~6 hours).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7b5e739-a872-40d7-b313-11a17c417f2a', '365 days and 6 hours (365¼ days)', true, '12de9e78-565f-4e89-b1de-3dfa0dda441d');
