INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b42de3ac-c92d-42c8-857e-7f3ccd7d02cb', '23rd September', false, 'd0af54f6-7057-4729-8051-50fdcb37caad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46cbce54-4f4d-4a6f-99f7-82bcab3dd504', '21st March', false, 'd0af54f6-7057-4729-8051-50fdcb37caad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba2fbb77-9fbb-4001-87d3-e31900bde9e4', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Easy', 'On which two dates does the Earth experience an ''Equinox'' when direct rays of the Sun fall on the Equator and day and night are of equal duration all over the world?', 'During Equinoxes (21 March Vernal & 23 September Autumnal), neither pole tilts toward the Sun, resulting in equal 12-hour day and night.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20710bfe-e00f-44d5-8459-002ddd1a528a', '21st March and 23rd September', true, 'ba2fbb77-9fbb-4001-87d3-e31900bde9e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b30ea72-2775-46d1-a238-0125f5cf3692', '21st June and 22nd December', false, 'ba2fbb77-9fbb-4001-87d3-e31900bde9e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8784eece-5d31-4202-82f8-ced29132a6a7', '1st January and 1st July', false, 'ba2fbb77-9fbb-4001-87d3-e31900bde9e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cea99a0-c836-4ddb-bc71-4c14bd38acc6', '15th August and 26th January', false, 'ba2fbb77-9fbb-4001-87d3-e31900bde9e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6eda57d-72ed-4f70-b227-91b6418c46a5', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Easy', 'In which country is Christmas famously celebrated in the middle of summer?', 'Christmas falls on 25 December during peak summer in the Southern Hemisphere (Australia, New Zealand, South Africa).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32368aec-7742-4b45-9932-0ee797a23c73', 'Australia (Southern Hemisphere)', true, 'f6eda57d-72ed-4f70-b227-91b6418c46a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('166f5d61-a259-4a3d-994d-8fdb113624e8', 'United Kingdom', false, 'f6eda57d-72ed-4f70-b227-91b6418c46a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7c1fa87-fdaa-4f1a-b055-caca646bfecf', 'Canada', false, 'f6eda57d-72ed-4f70-b227-91b6418c46a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1a43ad0-7a94-4cef-9536-2cc85a3607cb', 'Norway', false, 'f6eda57d-72ed-4f70-b227-91b6418c46a5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fdc851a5-cd9a-4914-9abf-6ad3dda84c3d', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'What would happen if the Earth stopped rotating on its axis entirely?', 'Cessation of spin would create a tidally locked thermal catastrophe: an unlivable subsolar oven on one side and an absolute cryogenic desert on the other.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92d62f37-6f28-43fd-925c-79395f69abbe', 'The hemisphere facing the Sun would be in permanent scorching daylight and extreme heat, while the other hemisphere would remain in perpetual freezing darkness, making life impossible', true, 'fdc851a5-cd9a-4914-9abf-6ad3dda84c3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e211b5e-fcdc-4a11-9a9f-5e8595c06b57', 'All humans would fly into space', false, 'fdc851a5-cd9a-4914-9abf-6ad3dda84c3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f522ccc-ba9d-4d63-899f-c77c20404454', 'The Sun would turn into ice', false, 'fdc851a5-cd9a-4914-9abf-6ad3dda84c3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('104d7f28-39e3-4d51-a000-3679fc60ad5f', 'Seasons would change every 2 hours', false, 'fdc851a5-cd9a-4914-9abf-6ad3dda84c3d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6e578b4-07d5-427e-82a9-6cae5762d94a', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'Does the Circle of Illumination coincide with the Earth''s rotational axis?', 'The Circle of Illumination is perpendicular to solar rays, while Earth''s tilted axis maintains a fixed 66.5° angle to the orbital plane.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc03d787-1dae-42e0-a57e-ca09dfde0cb3', 'No, because the Earth''s rotational axis is tilted at an angle of 23½° from the perpendicular (66½° with the orbital plane)', true, 'c6e578b4-07d5-427e-82a9-6cae5762d94a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a843a913-6441-4b36-a648-fe6c7fcba4d2', 'Yes, they are the exact same line', false, 'c6e578b4-07d5-427e-82a9-6cae5762d94a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7e78a34-393b-40eb-8e47-6d0f008bf562', 'Yes, only on Mondays', false, 'c6e578b4-07d5-427e-82a9-6cae5762d94a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43208ca4-948f-498d-87aa-fac4fffd8f84', 'Only during midnight', false, 'c6e578b4-07d5-427e-82a9-6cae5762d94a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96e62302-f131-4ae8-ac06-428f7503a3e4', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'Why do places beyond the Arctic Circle (66½° N) experience continuous daylight (the ''Midnight Sun'') for about 6 months around June?', 'Axial tilt positions the circumpolar region entirely within the sunlit hemisphere throughout the daily 360° spin.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f69faa8c-ea9f-4f16-89f4-49feb0644672', 'The North Pole remains tilted towards the Sun continuously as Earth rotates, so the Arctic region stays inside the Circle of Illumination for 24 hours a day', true, '96e62302-f131-4ae8-ac06-428f7503a3e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40c1e2d3-aafa-4b92-aafc-eab866526a04', 'The Moon turns into a small sun', false, '96e62302-f131-4ae8-ac06-428f7503a3e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16749ef9-778e-4369-8bb5-1f2e7c135ddc', 'Snow reflects light like a mirror', false, '96e62302-f131-4ae8-ac06-428f7503a3e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b62ba3f3-b46b-4cd9-b2a7-606bdcb4ab07', 'The Sun stops setting in all galaxies', false, '96e62302-f131-4ae8-ac06-428f7503a3e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2bd29db0-4296-4ab3-a36f-5983c83d2047', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'Why do areas around the Poles receive minimum heat even during long daylight hours in summer?', 'Low solar elevation angle reduces radiant flux per unit surface area according to Lambert''s cosine law.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d78821c-477a-4c49-bb58-ce9c088411ba', 'The sun''s rays strike the polar surface at an extremely acute, slanting angle, spreading the heat energy over a very large area', true, '2bd29db0-4296-4ab3-a36f-5983c83d2047');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1edd7623-ad3f-4fa0-a182-4f048b954ce6', 'Poles have no air', false, '2bd29db0-4296-4ab3-a36f-5983c83d2047');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('580d74c7-6dd5-448a-bc72-579548ce7273', 'The Sun is millions of miles farther from the poles', false, '2bd29db0-4296-4ab3-a36f-5983c83d2047');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22a77dc0-addc-4d40-82ca-a4416cdc7557', 'Ice pushes the Sun away', false, '2bd29db0-4296-4ab3-a36f-5983c83d2047');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('430ef221-1a09-489b-a752-4af203f5cc56', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'What is the shape of the Earth''s orbit around the Sun?', 'Kepler''s First Law: All planets orbit the Sun in an elliptical path with the Sun situated at one of the two focal points.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3706b6a-ae27-4037-a220-bacf58c1b45e', 'An Elliptical orbit (an elongated, oval circle)', true, '430ef221-1a09-489b-a752-4af203f5cc56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e92de77-a0c2-45db-a99f-3ddacf8422a6', 'A perfect circle', false, '430ef221-1a09-489b-a752-4af203f5cc56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46b41f60-aaee-42f1-96ab-b94d37b51078', 'A straight line', false, '430ef221-1a09-489b-a752-4af203f5cc56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d8d26ba-17a3-4663-abfb-b3c9693e1bd1', 'A square path', false, '430ef221-1a09-489b-a752-4af203f5cc56');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8718d0c5-f73f-4542-8e8b-2902a58b1f92', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'On 23rd September, what season is experienced in the Northern Hemisphere and Southern Hemisphere respectively?', 'The 23 September Equinox brings Autumn to the Northern Hemisphere and Spring to the Southern Hemisphere.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7117bf42-9354-4936-95e4-97ea503cc1c7', 'Northern Hemisphere: Autumn (Fall); Southern Hemisphere: Spring', true, '8718d0c5-f73f-4542-8e8b-2902a58b1f92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48e7804d-8e91-4111-a99b-daed2eeefa2a', 'Northern Hemisphere: Spring; Southern Hemisphere: Autumn', false, '8718d0c5-f73f-4542-8e8b-2902a58b1f92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f724bbb-fdff-4d11-aa7a-0ffd26c44696', 'Northern Hemisphere: Summer; Southern Hemisphere: Winter', false, '8718d0c5-f73f-4542-8e8b-2902a58b1f92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dcf4ad5-0596-4f6a-bcf4-0cfff152129d', 'Both experience Winter', false, '8718d0c5-f73f-4542-8e8b-2902a58b1f92');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d407b536-8646-4b98-944c-de03c0147ea9', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'On 21st March, what season is experienced in the Northern Hemisphere and Southern Hemisphere respectively?', 'The 21 March Equinox marks the beginning of Spring (Vernal Equinox) in the north and Autumn in the south.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94d9c049-a78e-4df8-a71f-65ec0b555976', 'Northern Hemisphere: Spring (Vernal); Southern Hemisphere: Autumn', true, 'd407b536-8646-4b98-944c-de03c0147ea9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('326ab3f0-ec94-4b8c-a3ea-c5b04baefc9f', 'Northern Hemisphere: Autumn; Southern Hemisphere: Spring', false, 'd407b536-8646-4b98-944c-de03c0147ea9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26e350d6-2ee2-4504-9a52-3a20c6982879', 'Northern Hemisphere: Winter; Southern Hemisphere: Summer', false, 'd407b536-8646-4b98-944c-de03c0147ea9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32d7a47b-20a6-431c-a386-1d9caee7ac98', 'Both experience Summer', false, 'd407b536-8646-4b98-944c-de03c0147ea9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8335701f-fdcd-49e2-a4c6-c08ca6440115', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'What is the orbital plane of the Earth?', 'The orbital plane (ecliptic plane) is the geometric plane containing the Earth''s revolution path around the Sun.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b32b04a-179d-4a2d-bf16-a1824baefde0', 'The plane formed by the Earth''s orbit around the Sun', true, '8335701f-fdcd-49e2-a4c6-c08ca6440115');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39224271-614c-4289-8229-4eda79b28195', 'The plane passing through the equator', false, '8335701f-fdcd-49e2-a4c6-c08ca6440115');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1fc8420-c7de-4ff2-b30c-2272bb6df3b9', 'The plane passing through the prime meridian', false, '8335701f-fdcd-49e2-a4c6-c08ca6440115');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8837dc52-897b-4ebd-b11a-474ddc850bf6', 'The surface of the ocean', false, '8335701f-fdcd-49e2-a4c6-c08ca6440115');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b422b73-09f3-4b91-8fe3-516f77fed938', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'What angle does the Earth''s axis make with its orbital plane?', 'Earth''s rotational axis tilts 23½° from the perpendicular, making an angle of 90° - 23½° = 66½° with its orbital plane.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e7621d5-c1f2-4467-a45d-cc996fd82941', '66½°', true, '1b422b73-09f3-4b91-8fe3-516f77fed938');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a518b896-6cec-4939-8094-037f46b42eb2', '23½°', false, '1b422b73-09f3-4b91-8fe3-516f77fed938');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a65369af-a168-4bef-88f1-08b7b8988770', '90°', false, '1b422b73-09f3-4b91-8fe3-516f77fed938');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21ed057e-db90-472c-b3d0-eee4c9bf7ea3', '45°', false, '1b422b73-09f3-4b91-8fe3-516f77fed938');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84da0735-cf5c-47b5-9e70-903c6172d88c', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'Why do days become longer in summer and nights become shorter in winter in the Northern Hemisphere?', 'The northern tilt causes northern latitude parallels to spend more than 50% of their diurnal rotational arc inside the Circle of Illumination.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5275232-0d61-4780-9b2f-25937ca77910', 'The Northern Hemisphere is tilted towards the Sun in summer, so a larger portion of the northern latitude circles lies within the sunlit day hemisphere', true, '84da0735-cf5c-47b5-9e70-903c6172d88c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87e14af1-a3ad-4e9a-8019-10a452239b3b', 'The Earth rotates slower in summer and faster in winter', false, '84da0735-cf5c-47b5-9e70-903c6172d88c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96f9d413-ac8e-4384-9869-db2be6957caa', 'The Sun grows bigger in summer', false, '84da0735-cf5c-47b5-9e70-903c6172d88c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5c6e30a-d6db-493e-aaa0-1d0045adabd8', 'Clouds hide the night in summer', false, '84da0735-cf5c-47b5-9e70-903c6172d88c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3348c85a-643f-43fe-9ca3-5e01efba90ce', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'Which term describes the point in the Earth''s elliptical orbit when it is CLOSEST to the Sun (about 147 million km around 3 January)?', 'Perihelion (from Greek peri = near, helios = sun) is the orbital periapsis where Earth is closest to the Sun.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bc5f2c2-3b5c-4756-bb6b-6c6319a46099', 'Perihelion', true, '3348c85a-643f-43fe-9ca3-5e01efba90ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c35097ec-67ac-4003-b16b-e61a5b356825', 'Aphelion', false, '3348c85a-643f-43fe-9ca3-5e01efba90ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a65bbe31-e8c1-42d8-ad06-a952037899af', 'Solstice', false, '3348c85a-643f-43fe-9ca3-5e01efba90ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69131748-1a64-444b-8bad-343ed6d95d48', 'Equinox', false, '3348c85a-643f-43fe-9ca3-5e01efba90ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cccb3493-f78b-4b1b-baea-21ac36f1cab5', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'Which term describes the point in the Earth''s orbit when it is FARTHEST from the Sun (about 152 million km around 4 July)?', 'Aphelion (apo = away, helios = sun) is the orbital apoapsis where Earth reaches maximum solar distance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fecae8bd-e9f1-4f3a-b004-6a5e5f212f48', 'Aphelion', true, 'cccb3493-f78b-4b1b-baea-21ac36f1cab5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef94716c-348e-49cd-a828-f0e8e08b65fe', 'Perihelion', false, 'cccb3493-f78b-4b1b-baea-21ac36f1cab5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('171699fc-c5f8-4950-8204-8990204224a2', 'Equinox', false, 'cccb3493-f78b-4b1b-baea-21ac36f1cab5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bb832ba-f378-471c-aa8d-c0e3f8dafcd5', 'Zenith', false, 'cccb3493-f78b-4b1b-baea-21ac36f1cab5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('544f9041-f394-40b0-b65e-30e6864e3f93', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'What is the phenomenon called when the Sun is visible at local midnight during summer months in northern Norway, Sweden, and Finland?', 'At latitudes north of the Arctic Circle, the Sun remains above the horizon 24 hours a day during summer solstice.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc7558c4-4101-41af-b1b4-03fa078bc963', 'The Midnight Sun', true, '544f9041-f394-40b0-b65e-30e6864e3f93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcf5cc08-f787-4b68-b0af-1e69dfccd8cf', 'Solar Eclipse', false, '544f9041-f394-40b0-b65e-30e6864e3f93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54ca40df-5aca-48ea-adc3-75329bbe2c72', 'Aurora Borealis', false, '544f9041-f394-40b0-b65e-30e6864e3f93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d41cd95a-f601-42f0-b5ce-e627dec51d98', 'Polar Vortex', false, '544f9041-f394-40b0-b65e-30e6864e3f93');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0df39f54-0298-49fd-be08-04a37de08129', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'Why is an extra day added to the calendar every fourth year in February?', 'Without leap days, the 0.242-day annual discrepancy would cause calendar seasons to drift by ~24 days every century.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af0cd10b-048d-421e-ad75-3ac2997a3e75', 'To synchronize the civil calendar year (365 days) with the astronomical solar year (365.25 days) and prevent calendar seasonal drift', true, '0df39f54-0298-49fd-be08-04a37de08129');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9685a90-4f1a-4a0b-bbc5-4b3d65beebb2', 'Because February was feeling too short', false, '0df39f54-0298-49fd-be08-04a37de08129');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bba03fd-ff2f-4ce4-9b6c-2e32fb3ae1ae', 'To celebrate the King''s birthday', false, '0df39f54-0298-49fd-be08-04a37de08129');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bfe1a26-6675-4781-b272-c39da963aa63', 'Because Earth takes a vacation every 4 years', false, '0df39f54-0298-49fd-be08-04a37de08129');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59bfc3b8-c957-4a10-a782-67958a65b86c', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'What is the daily rotation of the Earth around its axis also termed in geography?', 'Diurnal motion refers to the daily 24-hour apparent rotation of celestial objects caused by Earth''s axial rotation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10715290-048f-45ac-bbdb-0a6abd84955c', 'Diurnal Motion', true, '59bfc3b8-c957-4a10-a782-67958a65b86c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ce9168d-852d-4f7e-9a27-aa7af10f21c3', 'Annual Motion', false, '59bfc3b8-c957-4a10-a782-67958a65b86c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd27a01a-defd-4bf2-9d88-d257082a18ff', 'Secular Motion', false, '59bfc3b8-c957-4a10-a782-67958a65b86c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69c133a7-4122-4668-8a4a-ba02bef3f331', 'Orbital Motion', false, '59bfc3b8-c957-4a10-a782-67958a65b86c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23bb4dcc-f6bb-442b-bddc-8dab6bce4f62', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Medium', 'Why does the Equator experience virtually equal 12-hour days and 12-hour nights throughout the entire year?', 'The Equator is a Great Circle, and any plane passing through the Earth''s center (like the Circle of Illumination) bisects all Great Circles equally.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cb936f3-cf05-481f-84c0-cbb9ea4ba809', 'Because the Circle of Illumination always bisects the Equator into two exact equal halves in all orbital positions', true, '23bb4dcc-f6bb-442b-bddc-8dab6bce4f62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58f9d25f-3743-43ac-895d-96071002f555', 'Because the Sun never moves away from the Equator', false, '23bb4dcc-f6bb-442b-bddc-8dab6bce4f62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77912c2f-0c4d-481b-829c-e27b3e266cb8', 'Because Earth does not rotate at the Equator', false, '23bb4dcc-f6bb-442b-bddc-8dab6bce4f62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15f57737-3adb-44d7-b2ce-d3db755dfaed', 'Because the Equator is flat', false, '23bb4dcc-f6bb-442b-bddc-8dab6bce4f62');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad6d9e6d-01f3-4205-8fc2-c7c12d0e0be9', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b05422e-5fdf-4016-9e0a-f31c830eee45', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'ad6d9e6d-01f3-4205-8fc2-c7c12d0e0be9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b6da1ee-6dfe-439b-afca-a3f35c995fc8', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'ad6d9e6d-01f3-4205-8fc2-c7c12d0e0be9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('472a20ae-833a-4c42-b70d-7359ad6fe3b1', '(A) is true, but (R) is false.', false, 'ad6d9e6d-01f3-4205-8fc2-c7c12d0e0be9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84fa6931-5b21-48ca-8526-a2b6129b428a', '(A) is false, but (R) is true.', false, 'ad6d9e6d-01f3-4205-8fc2-c7c12d0e0be9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bd455515-3cd1-4f3e-9c88-942342a63318', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Spot the IMPOSTER in the following list of astronomical dates and their northern seasonal designations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e12fdfa0-0c73-4413-aae2-8f0ece3d921e', '21 June - Summer Solstice', false, 'bd455515-3cd1-4f3e-9c88-942342a63318');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('379c65a3-7bbf-430e-b3a6-ddd61a82c1ee', '22 December - Winter Solstice', false, 'bd455515-3cd1-4f3e-9c88-942342a63318');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a17eb366-2207-47d4-be44-4f272b5dab6c', '21 March - Vernal Equinox', false, 'bd455515-3cd1-4f3e-9c88-942342a63318');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90d27af4-5670-4750-a626-5104a4fc9637', '23 September - Winter Solstice', true, 'bd455515-3cd1-4f3e-9c88-942342a63318');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4a37056-571f-4ea5-9a27-4824d70e245a', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Consider a person standing at the South Pole on 21st June. What will they experience for the entire 24-hour period?', 'On 21 June, the South Pole tilts away from the Sun, remaining fully submerged in the dark night hemisphere.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be46b35e-ccf9-47af-a2e4-a813648c3a7f', 'Continuous, complete 24-hour darkness (Polar Night), with the Sun never rising above the horizon', true, 'f4a37056-571f-4ea5-9a27-4824d70e245a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a7931f4-cbeb-468c-bfcd-8cc25d308ded', 'Continuous 24-hour bright daylight', false, 'f4a37056-571f-4ea5-9a27-4824d70e245a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('748b3b67-6b50-437f-8c2b-2ff44d87f627', 'Equal 12-hour day and 12-hour night', false, 'f4a37056-571f-4ea5-9a27-4824d70e245a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec09f75c-d092-4c1a-b0a0-3e06dd7dc3f6', 'A solar eclipse every 2 hours', false, 'f4a37056-571f-4ea5-9a27-4824d70e245a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('923e40a6-b0a8-4726-956b-6d2e4dc341a2', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Match Column I (Dates) with Column II (Solar Positions & Events):
(a) 21st June       -> (i) Direct rays on Tropic of Capricorn
(b) 22nd December   -> (ii) Direct rays on Tropic of Cancer
(c) 21st March      -> (iii) Direct rays on Equator (Spring Equinox in North)
(d) 23rd September  -> (iv) Direct rays on Equator (Autumn Equinox in North)', '21 June = Sun on Cancer; 22 Dec = Sun on Capricorn; 21 March = Spring Equinox; 23 Sept = Autumn Equinox.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4627ea85-057b-41b9-b259-bf9993fd037f', 'a-(ii), b-(i), c-(iii), d-(iv)', true, '923e40a6-b0a8-4726-956b-6d2e4dc341a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e6932bf-e656-421c-96e9-ba2c349e1241', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '923e40a6-b0a8-4726-956b-6d2e4dc341a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3875b55-dc49-49e5-a2f0-1c5ee9448bca', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '923e40a6-b0a8-4726-956b-6d2e4dc341a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('411aac78-759d-4ce5-a518-33f12728d75d', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '923e40a6-b0a8-4726-956b-6d2e4dc341a2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a2b00ef-b499-47a7-846b-fd6268ebd5a8', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21d80919-5831-4d13-9764-4919b2963d85', 'All Statements 1, 2, and 3', true, '1a2b00ef-b499-47a7-846b-fd6268ebd5a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98717117-31f1-470e-adb2-15a36a7ac5e7', 'Statements 1 and 2 only', false, '1a2b00ef-b499-47a7-846b-fd6268ebd5a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd7f6425-a843-4b98-b869-0bee4e1483de', 'Statements 2 and 3 only', false, '1a2b00ef-b499-47a7-846b-fd6268ebd5a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7675273-d9af-408f-ad6f-f1b3261f97af', 'Statements 1 and 3 only', false, '1a2b00ef-b499-47a7-846b-fd6268ebd5a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e1f1a64-e551-4ecb-8f63-976433a2ee34', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Why are solar days slightly longer than sidereal days (the true rotation period relative to distant stars being 23h 56m 4s)?', 'Orbital progression (~1° per day) requires Earth to spin an extra ~1° (360°/365 ≈ 4 minutes) for the Sun to return to the meridian.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a22c8252-fd07-4699-a7d9-53ac1bc8507f', 'Because while rotating, Earth also moves forward in its orbit around the Sun, requiring an extra ~4 minutes of rotation to align with the Sun again', true, '4e1f1a64-e551-4ecb-8f63-976433a2ee34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc709a6e-86fe-42c5-a595-ebc413f6894c', 'Because stars move backwards', false, '4e1f1a64-e551-4ecb-8f63-976433a2ee34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f52bd23-b3c7-4446-80ac-6f7a9bc72dc8', 'Because the Sun rotates in the opposite direction', false, '4e1f1a64-e551-4ecb-8f63-976433a2ee34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de019edc-05c2-44ce-9ea1-d48500c32e18', 'Because gravity slows down at night', false, '4e1f1a64-e551-4ecb-8f63-976433a2ee34');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f842e01c-9feb-4341-8e72-863f810adb80', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'What is the mathematical condition for a century year (like 1900, 2000, 2100) to be designated a Leap Year in the Gregorian calendar?', 'Century years must be multiples of 400 to account for the precise fractional solar year (365.2422 days).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03f038e0-3e32-45e7-9ce3-5a30f1a46a3b', 'It must be divisible by 400 (e.g. 2000 was a leap year, but 1900 and 2100 are NOT leap years)', true, 'f842e01c-9feb-4341-8e72-863f810adb80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc6ae295-b34b-4428-a96b-25adf3c1a229', 'It must be divisible by 4 only', false, 'f842e01c-9feb-4341-8e72-863f810adb80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('423ed22a-29d3-47a6-9a71-9f3fb8eaab06', 'It must be divisible by 100 only', false, 'f842e01c-9feb-4341-8e72-863f810adb80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c3f0ae5-331a-47c8-8cae-9d27453e8478', 'All century years are leap years', false, 'f842e01c-9feb-4341-8e72-863f810adb80');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a85182a5-9fc3-45fb-ae9c-3e7433bed528', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Why do direct solar rays at noon produce significantly more heating than slanting rays in the early morning and late evening?', 'Vertical rays minimize atmospheric optical path attenuation (air mass = 1) and maximize insolation flux per square meter.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b575189d-c401-4e56-8a23-8b9278eb61b6', 'Direct vertical rays travel through a thinner slice of the atmosphere and concentrate high radiant energy on a small surface patch', true, 'a85182a5-9fc3-45fb-ae9c-3e7433bed528');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9100c856-7730-4832-a1dd-89aee57c216d', 'The Sun is hotter at noon', false, 'a85182a5-9fc3-45fb-ae9c-3e7433bed528');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6f86281-f90d-4fed-b941-e9177cf222c0', 'Air disappears at noon', false, 'a85182a5-9fc3-45fb-ae9c-3e7433bed528');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('faf0d227-b6fd-4993-a45b-0af731202e42', 'Clouds only exist in the morning', false, 'a85182a5-9fc3-45fb-ae9c-3e7433bed528');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9499b10b-995b-438e-adf5-993bf06fdaaf', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Why does the Southern Hemisphere experience peak winter when the Northern Hemisphere is experiencing peak summer?', 'Axial orientation creates inverse subsolar exposure between opposite hemispheres during Earth''s orbital journey.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df710bac-97b3-406d-9ca8-3bf8b81f3368', 'Due to Earth''s fixed axial tilt, when the Northern Hemisphere points towards the Sun, the Southern Hemisphere is tilted away from the Sun', true, '9499b10b-995b-438e-adf5-993bf06fdaaf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('623376c5-b445-47c1-a248-8115334ec221', 'Because the Southern Hemisphere is made of water', false, '9499b10b-995b-438e-adf5-993bf06fdaaf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19530205-de9b-4270-a6da-41019daabce5', 'Because the Sun only shines on the north', false, '9499b10b-995b-438e-adf5-993bf06fdaaf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('770c76ef-556b-4bce-8977-22677e8a0191', 'Because Antarctica is too high', false, '9499b10b-995b-438e-adf5-993bf06fdaaf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11c1289c-bb08-41f6-877a-32be9ea8e12c', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Consider four points on Earth on 21st June:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04a17c3e-1fcf-4c6c-b0fa-c29a29d8affc', '1 -> 2 -> 3 -> 4 (North Pole: 24h -> Equator: 12h -> Tropic of Capricorn: ~10.5h -> South Pole: 0h)', true, '11c1289c-bb08-41f6-877a-32be9ea8e12c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2d430ba-08cd-483a-b12b-034d550d4399', '4 -> 3 -> 2 -> 1', false, '11c1289c-bb08-41f6-877a-32be9ea8e12c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbfc43ba-6bc9-4f07-9127-7ff6bdfb2162', '2 -> 1 -> 3 -> 4', false, '11c1289c-bb08-41f6-877a-32be9ea8e12c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21937bcf-3935-4745-b70e-2b48f329fc1f', '1 -> 3 -> 2 -> 4', false, '11c1289c-bb08-41f6-877a-32be9ea8e12c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0868b2db-0526-476c-a965-26041efede8a', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'What is the velocity of Earth''s rotational spin at the Equator compared to that at the Poles?', 'Linear velocity v = ω·R·cos(θ); at θ = 0° (Equator), v ≈ 40,075 km / 24 h ≈ 1,670 km/h; at θ = 90° (Poles), v = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66567805-2315-44ba-8c26-b7b97272cb4e', 'Maximum at the Equator (~1,670 km/h) and zero at the Poles', true, '0868b2db-0526-476c-a965-26041efede8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('777f9bf6-b26e-41f7-b7a8-949368fa0882', 'Zero at the Equator and maximum at the Poles', false, '0868b2db-0526-476c-a965-26041efede8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22868312-881d-49df-86ee-1c1b5472e927', 'Equal at all latitudes', false, '0868b2db-0526-476c-a965-26041efede8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a72b9d0-c841-4cc0-b337-41a7b9cad7dd', '100 km/h everywhere', false, '0868b2db-0526-476c-a965-26041efede8a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('29c91b47-ec42-497b-8be6-047457db0dd7', 'Class 6', 'Social Science', 'Chapter 3: Motions of the Earth', 'Hard', 'Which of the following would be an immediate consequence if the Earth revolved around the Sun at TWICE its current orbital speed while maintaining its current rotation rate?', 'Doubling orbital velocity halves the annual revolution period (365/2 ≈ 182.5 days), while diurnal spin remains unchanged at 24 hours.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd080116-1b18-426a-b766-fbb6447688b5', 'A year would last only ~182.5 days (seasons would change twice as fast), but each day would still last 24 hours', true, '29c91b47-ec42-497b-8be6-047457db0dd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6caf693-1f5b-4cec-b5eb-f4f8b9abdbee', 'A day would become 12 hours', false, '29c91b47-ec42-497b-8be6-047457db0dd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09480f80-9239-4aff-8ed7-49e197fbc57d', 'Gravity would double', false, '29c91b47-ec42-497b-8be6-047457db0dd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49b43b0c-3417-4ca0-9480-1e6c89f3328b', 'The Moon would crash into Earth', false, '29c91b47-ec42-497b-8be6-047457db0dd7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c3743f9-a27d-451c-87d9-fb71254c7f19', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'दो या दो से अधिक वर्णों के सार्थक (अर्थपूर्ण) मेल को क्या कहते हैं?', 'वर्णों का वह स्वतंत्र एवं सार्थक समूह जिसका कोई निश्चित अर्थ निकलता हो, ''शब्द'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d2e5228-38d8-4261-b7fa-f8d55852a75d', 'शब्द (Word)', true, '4c3743f9-a27d-451c-87d9-fb71254c7f19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d53d542a-0b92-4352-ae84-9cc8ae9920c4', 'वर्णमाला', false, '4c3743f9-a27d-451c-87d9-fb71254c7f19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1cba6a9-34d5-4afd-a133-bc26f0e67c54', 'वाक्य', false, '4c3743f9-a27d-451c-87d9-fb71254c7f19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb1206ab-41ca-4525-9ded-050829cfb648', 'लिपि', false, '4c3743f9-a27d-451c-87d9-fb71254c7f19');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6c855a6e-0d93-43ef-984f-9952604dd19e', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'जब कोई सार्थक शब्द किसी वाक्य में व्याकरण के नियमों के अनुसार प्रयुक्त होता है, तो उसे क्या कहते हैं?', 'वाक्य में प्रयुक्त होकर व्याकरणिक संबंध (कारक, वचन, लिंग) ग्रहण करने पर शब्द ''पद'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51f0e22a-62cb-45ec-902e-437a28d79305', 'पद (Word in a sentence / Form)', true, '6c855a6e-0d93-43ef-984f-9952604dd19e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6882c6c9-9536-4cfa-a2a1-b2db4d679739', 'ध्वनि', false, '6c855a6e-0d93-43ef-984f-9952604dd19e');
