INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1045c368-942b-40f9-9e22-ea1848893055', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'अर्थ के आधार पर शब्दों को मुख्य रूप से कितने भागों में बाँटा जाता है?', 'अर्थ के आधार पर दो भेद होते हैं: 1. सार्थक शब्द (जिनका निश्चित अर्थ हो) तथा 2. निरर्थक शब्द (जिनका कोई अर्थ न हो, जैसे ''वाय-शाय'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ca115ac-6e8f-46c5-a2dc-d405e29651a8', 'दो भागों में (सार्थक शब्द और निरर्थक शब्द)', true, '1045c368-942b-40f9-9e22-ea1848893055');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('513fdcc2-2d43-402a-b1ae-f0bad98f4f6c', 'चार भागों में', false, '1045c368-942b-40f9-9e22-ea1848893055');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c224538-dd15-45c8-ac87-afd826c17039', 'तीन भागों में', false, '1045c368-942b-40f9-9e22-ea1848893055');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('770e8948-9579-454c-a9e3-7a2bfe35e2dd', 'पाँच भागों में', false, '1045c368-942b-40f9-9e22-ea1848893055');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13597fb4-cadf-4ebe-a3a1-170382795e06', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'उत्पत्ति या स्रोत (Origin) के आधार पर शब्दों के कितने भेद होते हैं?', 'उत्पत्ति के आधार पर चार मुख्य वर्ग हैं: तत्सम (संस्कृत मूल), तद्भव (परिवर्तित), देशज (स्थानीय), तथा विदेशी (आगत)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75cd85ce-0015-47c7-a19e-3a3e6e37a9a9', 'चार मुख्य भेद (तत्सम, तद्भव, देशज, विदेशी)', true, '13597fb4-cadf-4ebe-a3a1-170382795e06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76e5f3a0-8efe-400d-9788-bf6e9b664fed', 'दो भेद', false, '13597fb4-cadf-4ebe-a3a1-170382795e06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10c68779-85dc-4da4-9f57-9d613d58aa31', 'छह भेद', false, '13597fb4-cadf-4ebe-a3a1-170382795e06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41bcdc25-8664-4c45-9d4b-99f1a9beb672', 'तीन भेद', false, '13597fb4-cadf-4ebe-a3a1-170382795e06');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4b77727-ace0-4c6c-a164-11c6e892ac77', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'संस्कृत भाषा के वे शब्द जो बिना किसी परिवर्तन के अपने मूल रूप में हिंदी में प्रयुक्त होते हैं, उन्हें क्या कहते हैं?', '''तत्'' (उसके/संस्कृत) + ''सम'' (समान) = जो शब्द संस्कृत से ज्यों-के-त्यों हिंदी में आए हैं, तत्सम कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06f4a795-348a-400b-867b-8c08c4ff48be', 'तत्सम शब्द (Tatsam - जैसे: अग्नि, सूर्य, दुग्ध, रात्रि)', true, 'e4b77727-ace0-4c6c-a164-11c6e892ac77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fb54dfc-8b9c-46d3-8601-848285c2b610', 'तद्भव शब्द', false, 'e4b77727-ace0-4c6c-a164-11c6e892ac77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6176ee8-329f-4d1f-8123-8075346c66dc', 'देशज शब्द', false, 'e4b77727-ace0-4c6c-a164-11c6e892ac77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cd1c4fc-1d6e-4d98-9453-8cd70c160aa1', 'विदेशी शब्द', false, 'e4b77727-ace0-4c6c-a164-11c6e892ac77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23974d66-f393-4b27-82d7-190254d75581', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'संस्कृत के वे शब्द जो समय के साथ रूप बदलकर (सरल होकर) हिंदी में प्रयुक्त होते हैं, उन्हें क्या कहते हैं?', '''तत्'' + ''भव'' (उससे उत्पन्न/विकसित) = संस्कृत से प्राकृत/अपभ्रंश होते हुए हिंदी में रूप बदलने वाले शब्द तद्भव कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7a6e6bf-ce46-49d9-a0d4-e262c280013a', 'तद्भव शब्द (Tadbhav - जैसे: आग, सूरज, दूध, रात)', true, '23974d66-f393-4b27-82d7-190254d75581');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('974b7267-6bab-4a9d-a862-ddbc64e10d89', 'तत्सम शब्द', false, '23974d66-f393-4b27-82d7-190254d75581');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fdab0e2-06de-462e-b085-ffdee2395707', 'रूढ़ शब्द', false, '23974d66-f393-4b27-82d7-190254d75581');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adf48ec5-1c24-49b4-9cb0-d70e53d04985', 'योगरूढ़ शब्द', false, '23974d66-f393-4b27-82d7-190254d75581');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('15de81c3-9e46-43d9-bd4e-87180f391854', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'वे शब्द जो स्थानीय बोलियों या क्षेत्रीय प्रभाव से आवश्यकतानुसार हिंदी में आ गए हैं, उन्हें क्या कहते हैं?', 'देश में ही क्षेत्रीय बोलियों और लोक-व्यवहार से निर्मित शब्द ''देशज'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55f0628f-d04d-4de4-a539-610d5ba4538d', 'देशज शब्द (Deshaj - जैसे: लोटा, पगड़ी, खिड़की, डिबिया)', true, '15de81c3-9e46-43d9-bd4e-87180f391854');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92db663d-ceff-4f89-8f26-fd1e89f5bcb8', 'तत्सम शब्द', false, '15de81c3-9e46-43d9-bd4e-87180f391854');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c72064a-542a-4aaa-a658-502912256f98', 'विदेशी शब्द', false, '15de81c3-9e46-43d9-bd4e-87180f391854');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50fb005a-eb7b-4d3f-84f0-ae259a2bdc9d', 'यौगिक शब्द', false, '15de81c3-9e46-43d9-bd4e-87180f391854');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f687b20-2c63-491a-9dbd-81857d128b3b', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'विदेशी भाषाओं (अंग्रेज़ी, अरबी, फारसी, पुर्तगाली आदि) से हिंदी में आए शब्दों को क्या कहते हैं?', 'विदेशी संपर्कों और शासनकालों के कारण हिंदी में गृहीत शब्द ''विदेशी/आगत शब्द'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0deb0511-6823-4213-aa47-715d88ffa060', 'विदेशी या आगत शब्द (जैसे: स्कूल, डॉक्टर, किताब, तोप, चाय)', true, '4f687b20-2c63-491a-9dbd-81857d128b3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8036cd7b-f6d2-43cf-bb6e-de3625c45e0b', 'तत्सम शब्द', false, '4f687b20-2c63-491a-9dbd-81857d128b3b');
