INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9de0a396-209e-4598-8d6e-211d65e261c9', 'रूढ़ शब्द', false, '4f687b20-2c63-491a-9dbd-81857d128b3b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2da33b3a-3926-4c9c-8284-125a19681d70', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'रचना या बनावट (Structure) के आधार पर शब्दों के कितने भेद होते हैं?', 'बनावट के आधार पर तीन भेद हैं: 1. रूढ़ (अविभाज्य मूल), 2. यौगिक (मेल से बने), 3. योगरूढ़ (विशेष अर्थ देने वाले)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2e69979-bdb3-40c5-8e5c-f85b907ef560', 'तीन भेद (रूढ़ शब्द, यौगिक शब्द, योगरूढ़ शब्द)', true, '2da33b3a-3926-4c9c-8284-125a19681d70');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5e2f047-f9b5-4d07-ae65-9ad3b6a9234c', 'दो भेद', false, '2da33b3a-3926-4c9c-8284-125a19681d70');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acb657fe-e173-49c3-b845-39b42506ceb4', 'चार भेद', false, '2da33b3a-3926-4c9c-8284-125a19681d70');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc95c861-a8ff-46e2-beee-b2f24ff497e6', 'पाँच भेद', false, '2da33b3a-3926-4c9c-8284-125a19681d70');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d044d33d-f7e8-4f31-a661-bdda6e4098ae', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'वे शब्द जिनके सार्थक खंड (टुकड़े) नहीं किए जा सकते और जो किसी विशेष अर्थ के लिए परंपरा से प्रसिद्ध हैं, उन्हें क्या कहते हैं?', 'रूढ़ शब्दों के टुकड़े करने पर कोई स्वतंत्र अर्थ नहीं निकलता (जैसे ''घ + र'' का कोई अर्थ नहीं)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8c2e6e4-17cf-474c-adb4-af3fc0c4c979', 'रूढ़ शब्द (जैसे: घर, जल, पुस्तक, पेड़)', true, 'd044d33d-f7e8-4f31-a661-bdda6e4098ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3de409b-414f-48c2-ac30-7e9abf9f2300', 'यौगिक शब्द', false, 'd044d33d-f7e8-4f31-a661-bdda6e4098ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f65af9d-cc48-4157-acaf-3c6627bea60b', 'योगरूढ़ शब्द', false, 'd044d33d-f7e8-4f31-a661-bdda6e4098ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33e7db34-a1ba-4cfd-856c-c64c5ccec3cf', 'तद्भव शब्द', false, 'd044d33d-f7e8-4f31-a661-bdda6e4098ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9f54520-4845-494c-81c9-c2732e27a102', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'दो या दो से अधिक सार्थक शब्दों या शब्दांशों के मेल से बनने वाले शब्दों को क्या कहते हैं?', 'यौगिक शब्दों के प्रत्येक खंड का अपना स्वतंत्र सार्थक अर्थ होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee5a7eef-461c-414a-aad1-51b68ec93331', 'यौगिक शब्द (जैसे: पाठ + शाला = पाठशाला, विद्या + आलय = विद्यालय)', true, 'a9f54520-4845-494c-81c9-c2732e27a102');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7980754-5d22-4daf-ab5c-4c7f832e7ce8', 'रूढ़ शब्द', false, 'a9f54520-4845-494c-81c9-c2732e27a102');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a95e658-6e85-419a-a067-0a88c0c25aa2', 'योगरूढ़ शब्द', false, 'a9f54520-4845-494c-81c9-c2732e27a102');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37743090-a1fe-4d68-a814-b6a3aa81999d', 'निरर्थक शब्द', false, 'a9f54520-4845-494c-81c9-c2732e27a102');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ae8d3fe-99fe-4ab9-8313-d7c7d7995382', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Easy', 'वे शब्द जो दो या दो से अधिक शब्दों के मेल से बनते हैं, परन्तु किसी विशेष/रूढ़ अर्थ को प्रकट करते हैं, उन्हें क्या कहते हैं?', 'योगरूढ़ शब्द यौगिक होते हुए भी सामान्य अर्थ को छोड़कर किसी तीसरे विशिष्ट अर्थ के लिए रूढ़ हो जाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afcebd6b-9d5d-436b-9c45-8be65fb46c12', 'योगरूढ़ शब्द (जैसे: जलज = कमल, लंबोदर = गणेश, दशानन = रावण)', true, '6ae8d3fe-99fe-4ab9-8313-d7c7d7995382');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4062f66a-8dcc-47c2-8014-25d0237fa8a0', 'रूढ़ शब्द', false, '6ae8d3fe-99fe-4ab9-8313-d7c7d7995382');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('650d09da-7d4c-49aa-a5d0-a9a09773779a', 'यौगिक शब्द', false, '6ae8d3fe-99fe-4ab9-8313-d7c7d7995382');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d92ae32-0801-4732-9dd4-a0572fa6ae10', 'देशज शब्द', false, '6ae8d3fe-99fe-4ab9-8313-d7c7d7995382');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5ecaeba7-e9de-48e6-9ff2-26c21a2ca0c6', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Medium', 'प्रयोग या विकार (Grammatical Variation) के आधार पर शब्दों के दो प्रमुख भेद कौन-से हैं?', 'विकार के आधार पर: विकारी (संज्ञा, सर्वनाम, विशेषण, क्रिया) तथा अविकारी (क्रियाविशेषण, संबंधबोधक, समुच्चयबोधक, विस्मयादिबोधक)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2878bdbc-b604-49b5-93c4-b963892033f0', 'विकारी शब्द (जिनमें परिवर्तन होता है) और अविकारी शब्द (जिनमें कभी परिवर्तन नहीं होता)', true, '5ecaeba7-e9de-48e6-9ff2-26c21a2ca0c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9d62109-dcdd-4261-ac8f-59dbee1e7bb4', 'तत्सम और तद्भव', false, '5ecaeba7-e9de-48e6-9ff2-26c21a2ca0c6');
