INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('326e8695-1e83-432b-961a-83fcf0592811', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Medium', 'शब्द ''दशानन'' (दश + आनन = दस मुख वाला) किस विशिष्ट ऐतिहासिक पौराणिक पात्र के लिए योगरूढ़ है?', '''दशानन'' का रूढ़ विशेष अर्थ लंकापति ''रावण'' है।', NOW()) ON CONFLICT DO NOTHING;
