INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2fbc6d39-54cd-4d40-baf7-c414540016ee', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Medium', 'एक से अधिक अर्थ प्रकट करने वाले शब्दों को क्या कहते हैं (जैसे: ''कर'' = हाथ, टैक्स, किरण)?', 'प्रसंग भेद के अनुसार अनेक अर्थ देने वाले स्वतंत्र शब्द अनेकार्थी कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
