INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eb59e283-7a73-42e1-a3c8-44f502b08c46', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Medium', 'निम्नलिखित में से कौन-सा शब्द ''यौगिक शब्द'' का सही उदाहरण है?', '''राष्ट्रपति'' दो सार्थक शब्दों (राष्ट्र + पति) के योग से बना यौगिक शब्द है।', NOW()) ON CONFLICT DO NOTHING;
