INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1238f650-5558-4988-866d-4c39b3a6e637', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '799d83ad-15c5-4bd4-b6c9-39f1ea3998ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8cd88d2-4e10-43af-98f9-ddd2bc298121', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '799d83ad-15c5-4bd4-b6c9-39f1ea3998ce');
