INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5214c426-14c8-47b6-8131-0e641f792559', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Hard', 'सुमेलित कीजिए (तत्सम और तद्भव युग्म):
(क) मयूर  -> (i) घी
(ख) ग्राम  -> (ii) मोर
(ग) घृत   -> (iii) खेत
(घ) क्षेत्र -> (iv) गाँव', 'मयूर = मोर; ग्राम = गाँव; घृत = घी; क्षेत्र = खेत।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d5ec786-9fe0-46ab-8ed9-8207581f689f', 'क-(ii), ख-(iv), ग-(i), घ-(iii)', true, '5214c426-14c8-47b6-8131-0e641f792559');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b2e0fd1-cb8c-4803-a822-446512cbdd27', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, '5214c426-14c8-47b6-8131-0e641f792559');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51678155-ce70-4280-afe3-ae4b57471645', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '5214c426-14c8-47b6-8131-0e641f792559');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0a89b0a-97c6-4e51-bbda-081d3a0371e6', 'क-(iii), ख-(i), ग-(iv), घ-(ii)', false, '5214c426-14c8-47b6-8131-0e641f792559');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a91e2c1c-7a8f-464e-a33d-178e1a9a8b38', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Hard', 'दो भिन्न भाषाओं के शब्दों के मेल से बने नवीन शब्द को हिंदी में क्या कहा जाता है (जैसे: रेल + गाड़ी = रेलगाड़ी, वर्ष + गाँठ = वर्षगाँठ)?', 'दो भिन्न भाषाई स्रोतों (जैसे अंग्रेज़ी + हिंदी) से निर्मित मिश्रित शब्द ''संकर शब्द'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f8efc94-31e5-40f3-9b17-dc10f4d8d2d8', 'संकर शब्द (Hybrid Words)', true, 'a91e2c1c-7a8f-464e-a33d-178e1a9a8b38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95a90b8b-a8a0-439f-bb41-00ea9a95e011', 'तत्सम शब्द', false, 'a91e2c1c-7a8f-464e-a33d-178e1a9a8b38');
