INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0f85cf5-6ec2-459d-8fd4-c1366b5ad335', 'सभी कथन 1, 2 और 3 सत्य हैं', true, 'a1a1ff43-c594-464e-9470-7937da8b7442');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('409230ab-1a4c-4fb5-9db0-9dffbfaeac30', 'कथन 1 और 2 केवल', false, 'a1a1ff43-c594-464e-9470-7937da8b7442');
