INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('575661a9-342d-4fe6-a1f8-d3001e0ee245', 'कथन 1 और 3 केवल', false, 'a1a1ff43-c594-464e-9470-7937da8b7442');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c482bca2-de19-4ebd-806e-2fdc4e463d9f', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Hard', 'शब्द ''नीलकंठ'' (नील + कंठ) रचना की दृष्टि से किस वर्ग का शब्द है और क्यों?', '''नीलकंठ'' यौगिक संरचना होते हुए भी देवाधिदेव शिव के विशिष्ट तीसरे अर्थ में रूढ़ है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e45ac95f-2ebc-4122-81d4-b427a2bb4346', 'योगरूढ़ शब्द; क्योंकि यह नीले कंठ वाले सामान्य पक्षी के बजाय भगवान शिव के विशिष्ट अर्थ में रूढ़ हो गया है', true, 'c482bca2-de19-4ebd-806e-2fdc4e463d9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d06b39db-f4c1-4ffa-b78e-89b8483799ba', 'रूढ़ शब्द; क्योंकि इसके खंड नहीं हो सकते', false, 'c482bca2-de19-4ebd-806e-2fdc4e463d9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1071cb5a-e10e-494a-af61-731ceaa288dd', 'विदेशी शब्द', false, 'c482bca2-de19-4ebd-806e-2fdc4e463d9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d014261e-32f7-4bb1-a615-fa4b03ac8159', 'निरर्थक शब्द', false, 'c482bca2-de19-4ebd-806e-2fdc4e463d9f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eeed5671-3943-4975-bd2c-2c465adade8d', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Hard', 'श्रुतिसमभिन्नार्थक शब्द युग्म ''दिन'' और ''दीन'' के क्रमशः सही अर्थ क्या हैं?', 'ह्रस्व ''इ'' वाला ''दिन'' = दिवस/वार, तथा दीर्घ ''ई'' वाला ''दीन'' = दरिद्र/गरीब।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b66d4e73-0270-4e0f-9b2d-56bad8c17f7f', 'दिन = दिवस (Day) ; दीन = गरीब / असहाय (Poor)', true, 'eeed5671-3943-4975-bd2c-2c465adade8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8725ef32-59d1-4c7d-b3c4-a41f55b724b0', 'दिन = रात ; दीन = अमीर', false, 'eeed5671-3943-4975-bd2c-2c465adade8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1d8192e-050a-4b2e-ae13-8cba77d7960f', 'दिन = सूरज ; दीन = चाँद', false, 'eeed5671-3943-4975-bd2c-2c465adade8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e62ba170-0de6-46d6-92f3-bf86e61d3319', 'दोनों का अर्थ समान है', false, 'eeed5671-3943-4975-bd2c-2c465adade8d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('15d779e3-8e63-4145-9ce5-85eae6ed1fef', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Hard', 'श्रुतिसमभिन्नार्थक शब्द युग्म ''गृह'' और ''ग्रह'' के क्रमशः सही अर्थ क्या हैं?', '''गृह'' (ऋ की मात्रा) = घर/आवास, तथा ''ग्रह'' (र पदेन) = सूर्य की परिक्रमा करने वाला खगोलीय पिंड।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68378ad6-4db0-453e-9e3f-9d59386eafa4', 'गृह = घर (Mansion/House) ; ग्रह = आकाशीय पिंड (Planet)', true, '15d779e3-8e63-4145-9ce5-85eae6ed1fef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63418a3a-2a48-46cd-a660-816db421b87c', 'गृह = नक्षत्र ; ग्रह = कमरा', false, '15d779e3-8e63-4145-9ce5-85eae6ed1fef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f5f48f3-a670-4f58-91a3-29b2d5d3738e', 'गृह = सूर्य ; ग्रह = मंदिर', false, '15d779e3-8e63-4145-9ce5-85eae6ed1fef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a2715cf-6af2-49e5-8013-812b51bbeeba', 'दोनों का अर्थ घर है', false, '15d779e3-8e63-4145-9ce5-85eae6ed1fef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35ee922f-96fe-4a9f-93c4-133f69ed0b39', 'Class 6', 'Hindi Grammar', 'Chapter 3: शब्द-विचार', 'Hard', 'अनेकार्थी शब्द ''अंबर'' के दो विभिन्न संदर्भगत अर्थ कौन-से हैं?', '''अंबर'' का एक अर्थ विस्तृत नभ/आकाश है (जैसे ''नीलांबर'') तथा दूसरा अर्थ परिधान/वस्त्र है (जैसे ''पीतांबर'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c0a8cd7-09e9-4802-a6d4-fec0acb5ea9c', 'आकाश (Sky) और वस्त्र / कपड़ा (Cloth)', true, '35ee922f-96fe-4a9f-93c4-133f69ed0b39');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d9dcedd-cc2d-49eb-8d87-60d0d1d899fe', 'पानी और हवा', false, '35ee922f-96fe-4a9f-93c4-133f69ed0b39');
