INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0454bd1f-05ef-4e69-b9dc-ed2dfdcc5936', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Easy', 'The physiological process by which plants release excess water as water vapor into the air through microscopic stomatal pores is:', 'Transpiration generates negative xylem tension that pulls water from roots up to crown leaves.', NOW()) ON CONFLICT DO NOTHING;
