INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3783eea3-f97b-497c-9587-bf0e21639a76', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Easy', 'The biochemical process by which green leaves synthesize glucose food in the presence of sunlight, chlorophyll, CO₂, and water is called:', 'Photosynthesis converts solar energy into chemical energy: 6CO₂ + 6H₂O -> C₆H₁₂O₆ + 6O₂.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afc60820-d3e1-42bb-8806-cadaea300894', 'Photosynthesis', true, '3783eea3-f97b-497c-9587-bf0e21639a76');
