INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('387dd626-d25c-4020-b792-cc89725f89f0', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Easy', 'What primary gas is released into the atmosphere by green leaves during daytime photosynthesis?', 'Photolysis of water molecules during light-dependent reactions yields diatomic oxygen (O₂) byproduct.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('871dac0f-470d-4fc2-97e3-c0b2b597febd', 'Oxygen gas (O₂)', true, '387dd626-d25c-4020-b792-cc89725f89f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fbbb84b-e372-443d-b986-aa3ae316c2af', 'Carbon dioxide gas', false, '387dd626-d25c-4020-b792-cc89725f89f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04063cbe-3299-4f41-8fc0-40164efb72eb', 'Nitrogen gas', false, '387dd626-d25c-4020-b792-cc89725f89f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ffda1fd-6a78-4145-8923-02849ee57fe0', 'Methane gas', false, '387dd626-d25c-4020-b792-cc89725f89f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0db93d2-b6f1-4a69-8a12-73516e623081', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What is the key difference between Reticulate Venation and Parallel Venation?', 'Dicot leaves exhibit branching anastomosing net patterns (reticulate), while monocots feature longitudinal parallel venation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ceae3c7-d9ce-41cd-8a55-7094867c0da6', 'Reticulate venation forms a net-like web of veins (e.g. Peepal, Mango), while Parallel venation runs in parallel lines (e.g. Grass, Wheat, Banana)', true, 'd0db93d2-b6f1-4a69-8a12-73516e623081');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06aac6df-9714-45d6-9f23-bff43b936bf8', 'Parallel venation only occurs in trees', false, 'd0db93d2-b6f1-4a69-8a12-73516e623081');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99c26d8f-5243-41dd-b13f-d334fce7bb12', 'Reticulate venation has no midrib', false, 'd0db93d2-b6f1-4a69-8a12-73516e623081');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d3c39ac-0a09-4402-8f88-43dc05d166a5', 'They are identical', false, 'd0db93d2-b6f1-4a69-8a12-73516e623081');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('92ceedc4-eaa4-4afb-a600-849095df1025', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What correlation exists between a plant''s root system and its leaf venation type?', 'Dicotyledons typically pair reticulate leaf venation with taproots; monocotyledons pair parallel venation with fibrous root clusters.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fcf7759-c765-4729-9a6c-5a7aa2fb8b64', 'Plants with Reticulate venation have Taproots, while plants with Parallel venation have Fibrous roots', true, '92ceedc4-eaa4-4afb-a600-849095df1025');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('702b51f9-20ef-4f6e-9b40-b768e916d03f', 'Plants with Reticulate venation have Fibrous roots', false, '92ceedc4-eaa4-4afb-a600-849095df1025');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24655a14-9015-482a-8e08-c768476d52be', 'Leaf venation has zero relation to root type', false, '92ceedc4-eaa4-4afb-a600-849095df1025');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1df48989-e664-474f-b9f0-635543ff2523', 'All trees have fibrous roots', false, '92ceedc4-eaa4-4afb-a600-849095df1025');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4a9599f-4d76-4ee7-8c9e-62b627e0f7f4', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What are the two primary physiological functions performed by plant ROOTS?', 'Roots provide mechanical soil anchorage and extract aqueous minerals across root hair membranes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('beb99d66-bafc-4cc2-904c-2a3e88641c0c', 'Anchoring the plant firmly in the soil and absorbing water and dissolved mineral nutrients', true, 'f4a9599f-4d76-4ee7-8c9e-62b627e0f7f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aeaa8496-91a1-4172-b698-e1f9e566bd2a', 'Producing flowers and seeds', false, 'f4a9599f-4d76-4ee7-8c9e-62b627e0f7f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('357d27f6-d86f-4d7a-8c7a-9d3648c9478c', 'Synthesizing oxygen from sunlight', false, 'f4a9599f-4d76-4ee7-8c9e-62b627e0f7f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f4401c8-5f04-49f7-a473-5ef672ebf24e', 'Breathing air for animals', false, 'f4a9599f-4d76-4ee7-8c9e-62b627e0f7f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a50f09e1-978b-4ff4-98c0-3ebe8f0f78a6', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What are the two primary physiological functions performed by the plant STEM?', 'Stems house xylem vascular conduits (upward sap transport) and phloem conduits (bidirectional photosynthate translocation).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('332ce8ea-6fd9-4b93-8524-ccd9fb4155d7', 'Conducting water and minerals from roots upward to leaves, and transporting synthesized food from leaves to all plant parts', true, 'a50f09e1-978b-4ff4-98c0-3ebe8f0f78a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c9b484c-ca31-4105-b1fd-49744d961e3c', 'Producing pollen grains', false, 'a50f09e1-978b-4ff4-98c0-3ebe8f0f78a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4134c46a-ab12-4066-a938-708c1c07e69c', 'Absorbing sunlight directly through bark', false, 'a50f09e1-978b-4ff4-98c0-3ebe8f0f78a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79364874-ebfe-4921-b924-b6b93b794b2b', 'Storing stones', false, 'a50f09e1-978b-4ff4-98c0-3ebe8f0f78a6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7812abf3-7da2-4b8f-8c4d-a0311c6ea35d', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What are the four concentric whorls of a complete typical flower from outside to inside?', 'Floral organs arise in four sequential whorls: outer protective sepals, showy petals, male stamens, and central female pistil.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('269b3bcd-36e7-4376-b838-e5dd94ceebd2', 'Sepals (Calyx) -> Petals (Corolla) -> Stamens (Androecium) -> Pistil/Carpel (Gynoecium)', true, '7812abf3-7da2-4b8f-8c4d-a0311c6ea35d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('391074bb-ac5b-4a14-827b-031a65fb4dc4', 'Petals -> Sepals -> Pistil -> Stamens', false, '7812abf3-7da2-4b8f-8c4d-a0311c6ea35d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9eea45f-02db-4155-986f-ee0e681adcba', 'Pistil -> Stamens -> Petals -> Sepals', false, '7812abf3-7da2-4b8f-8c4d-a0311c6ea35d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f24c33ed-eb93-47e5-958b-87ee6aa65312', 'Root -> Stem -> Leaf -> Flower', false, '7812abf3-7da2-4b8f-8c4d-a0311c6ea35d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a94875f4-f6de-481a-bc45-f84b66a91564', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What are the two main parts that make up a male reproductive organ (Stamen) of a flower?', 'The stamen consists of the microsporangiate anther supported by a slender filament.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3863d650-04eb-4fd6-b952-7703aeff7eb9', 'Anther (produces pollen grains) and Filament (stalk)', true, 'a94875f4-f6de-481a-bc45-f84b66a91564');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('135602d3-0287-4cdf-90f2-817e3c4b7c61', 'Stigma and Style', false, 'a94875f4-f6de-481a-bc45-f84b66a91564');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd898ed5-3ef0-4439-833c-22851d306778', 'Ovary and Ovule', false, 'a94875f4-f6de-481a-bc45-f84b66a91564');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f521d02b-d127-4bef-9b81-c33170dba9e2', 'Sepal and Petal', false, 'a94875f4-f6de-481a-bc45-f84b66a91564');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f2c78cb-586c-4ea9-885c-089d18a867b4', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What are the three main morphological parts of the female reproductive organ (Pistil / Carpel)?', 'The pistil comprises the sticky receptive stigma, elongate neck style, and basal ovule-bearing ovary.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3472fc8a-6532-445d-b40e-1b8c8604362c', 'Stigma (receptive top), Style (middle tube), and Ovary (swollen base)', true, '5f2c78cb-586c-4ea9-885c-089d18a867b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48986d70-fd38-43c0-8226-2411b1850453', 'Anther, Filament, Pollen', false, '5f2c78cb-586c-4ea9-885c-089d18a867b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aabfffd6-7a37-499c-be3b-7c306d01105e', 'Sepal, Petal, Node', false, '5f2c78cb-586c-4ea9-885c-089d18a867b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b68dcfd3-05c5-44e5-8643-53a3bb69e91d', 'Root, Stem, Leaf', false, '5f2c78cb-586c-4ea9-885c-089d18a867b4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b901061-af21-404c-bf1e-d3fd952f3841', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What are the small bead-like structures found attached inside the cut ovary of a flower called?', 'Ovules are the female megasporangia housed on ovarian placentas that ripen into seeds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea1f6cc6-cef4-494a-9eeb-3df1b822afba', 'Ovules (which develop into seeds after fertilization)', true, '8b901061-af21-404c-bf1e-d3fd952f3841');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c607334-0dad-4685-8607-a362504cc633', 'Pollen grains', false, '8b901061-af21-404c-bf1e-d3fd952f3841');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04eee5be-24ab-4a06-a388-835d9cf79c1b', 'Sepals', false, '8b901061-af21-404c-bf1e-d3fd952f3841');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('619d8e56-1e7c-479d-a146-03831de53b40', 'Stomata', false, '8b901061-af21-404c-bf1e-d3fd952f3841');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab3e6a68-73d9-4bc2-bf66-7e6a427f74fd', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'After successful pollination and fertilization, what does the flower''s Ovary ripen into?', 'Post-fertilization hormonal signaling swells ovarian pericarp tissues into botanical fruit surrounding the mature seeds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26a9b92b-f21b-44c3-b87d-1a9ee9a0197a', 'The Fruit (containing seeds inside)', true, 'ab3e6a68-73d9-4bc2-bf66-7e6a427f74fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1158f38f-f10c-4cc4-828e-238480c9ebeb', 'A new leaf', false, 'ab3e6a68-73d9-4bc2-bf66-7e6a427f74fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68c9fb1e-7ed6-4b15-9d99-fffa9df17f52', 'A root', false, 'ab3e6a68-73d9-4bc2-bf66-7e6a427f74fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0367f54-618a-4d26-b6a1-61eeab842046', 'A petal', false, 'ab3e6a68-73d9-4bc2-bf66-7e6a427f74fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3975cc40-c35e-4a6f-ab26-75b9ac498790', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'In an experiment, a freshly cut leafy branch with white flowers is placed in water coloured with red ink. What happens after a few hours?', 'Demonstrates xylem vascular conduction: negative transpiration pull draws colored aqueous dye up through stem capillaries.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fdbf9f1-835f-4592-a673-0c857fa7e7ad', 'Red color ascends through narrow vascular tubes inside the stem, turning the flower petals and leaf veins reddish', true, '3975cc40-c35e-4a6f-ab26-75b9ac498790');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09366d3e-5519-4e7f-aea7-3d52107fc8d0', 'The branch dissolves completely', false, '3975cc40-c35e-4a6f-ab26-75b9ac498790');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dedfb2ee-e9cc-405e-b91c-604f004fea30', 'The leaves turn black', false, '3975cc40-c35e-4a6f-ab26-75b9ac498790');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84e838b3-7b4d-4d81-8148-a04cb31011af', 'The water evaporates instantly', false, '3975cc40-c35e-4a6f-ab26-75b9ac498790');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa42c8c5-c365-45c8-989d-9c833ebbe688', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'Why are bright, colourful petals and sweet nectar present in many entomophilous flowers?', 'Pigmented floral visual displays and nectar rewards entice insect pollinators to transfer pollen between blossoms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ced501c-d2e5-4148-aa2e-34292e052b62', 'To attract honeybees, butterflies, and insects for cross-pollination', true, 'aa42c8c5-c365-45c8-989d-9c833ebbe688');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ab08d4d-b201-4152-a03e-cb78d9405383', 'To keep the flower warm at night', false, 'aa42c8c5-c365-45c8-989d-9c833ebbe688');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b52333c2-1f51-446e-b70d-5f44a628d40a', 'To frighten grazing cattle', false, 'aa42c8c5-c365-45c8-989d-9c833ebbe688');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf29a794-3adb-4c1a-bd08-c5527b0caade', 'To absorb extra rain', false, 'aa42c8c5-c365-45c8-989d-9c833ebbe688');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c81c7716-35b3-4c09-aa6c-702c8d7e5cea', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'Which of the following root vegetables represents an enlarged, modified Taproot storing surplus food?', 'Carrot, radish, turnip, and beetroot are swollen biennial primary taproots storing accumulated carbohydrate reserves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbe60ce0-4075-4b01-a8d8-4d2c74766d71', 'Carrot, Radish, and Beetroot', true, 'c81c7716-35b3-4c09-aa6c-702c8d7e5cea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c7b233c-f41e-42cc-98c5-6585c5b3d038', 'Potato and Ginger', false, 'c81c7716-35b3-4c09-aa6c-702c8d7e5cea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64c7e40f-636b-4f51-b90f-6bae6b99fd73', 'Onion and Garlic', false, 'c81c7716-35b3-4c09-aa6c-702c8d7e5cea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb1305b2-b5df-451d-b72c-532c61fb4c59', 'Tomato and Brinjal', false, 'c81c7716-35b3-4c09-aa6c-702c8d7e5cea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7791e867-bb80-420d-8f0b-39f1e811ce18', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'Potato, ginger, and turmeric grow underground but are botanically classified as modified STEMS because:', 'Tubers and rhizomes exhibit cauline morphological features: nodes, internodal spacing, and vegetative eye buds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('686d9904-c58e-430a-b5c3-862614c5d408', 'They possess nodes, internodes, scale leaves, and axillary buds (eyes)', true, '7791e867-bb80-420d-8f0b-39f1e811ce18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a15cecf-1afc-4065-9403-5acf5e06dee4', 'They absorb water from soil like roots', false, '7791e867-bb80-420d-8f0b-39f1e811ce18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c74efaa-1bb3-4885-9489-f44f56d21f36', 'They have root caps', false, '7791e867-bb80-420d-8f0b-39f1e811ce18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07a9ff7b-c267-4625-a5fa-a8d6e7bf4145', 'They have no cells', false, '7791e867-bb80-420d-8f0b-39f1e811ce18');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f5d770c1-1fb1-49c7-b4d4-cf90c6a6e6e6', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'What happens when a clear polythene bag is tied around a leafy green twig of a potted plant kept in bright sunlight?', 'Transpirational water vapor escaping from foliar stomata hits the cooler polyethylene film and condenses into liquid droplets.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b947d793-0ee1-49c0-8901-8f8ea0bd87b6', 'Tiny droplets of water condense on the inner walls of the bag due to transpiration', true, 'f5d770c1-1fb1-49c7-b4d4-cf90c6a6e6e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0512abab-c587-4aa3-8249-f9dac0526578', 'The bag fills with black smoke', false, 'f5d770c1-1fb1-49c7-b4d4-cf90c6a6e6e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d744f4fe-af2b-47b9-9963-137898616855', 'The leaves turn into wood', false, 'f5d770c1-1fb1-49c7-b4d4-cf90c6a6e6e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8149927-a366-4042-b9db-c750ad3c7f66', 'The bag catches fire', false, 'f5d770c1-1fb1-49c7-b4d4-cf90c6a6e6e6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('611ca00f-91c4-40a4-a611-c2b627059369', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'Which test confirms that green leaves produce and store carbohydrate Starch during photosynthesis?', 'Ethanol extracts green chlorophyll; subsequent triiodide staining yields a deep blue-black amylose-iodine complex.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6dd10e2-2b61-40d5-94de-cd207045f1c6', 'Decolourizing a green leaf by boiling in spirit/alcohol, then adding drops of dilute Iodine solution to see a blue-black color', true, '611ca00f-91c4-40a4-a611-c2b627059369');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1107f722-f3a4-4175-a391-db38242263eb', 'Adding copper sulphate', false, '611ca00f-91c4-40a4-a611-c2b627059369');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebc3fcc3-6eb6-403a-97c7-e87d20023770', 'Burning the leaf on paper', false, '611ca00f-91c4-40a4-a611-c2b627059369');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21684cf2-277e-4dde-bf7c-cf2537d8b2dc', 'Freezing the leaf in ice', false, '611ca00f-91c4-40a4-a611-c2b627059369');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02ebfb28-38cf-40bd-a31d-cec90224d2c3', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Medium', 'Which of the following plants has leaves with PARALLEL venation and a FIBROUS root system?', 'Poaceae grasses and cereals (maize, wheat, rice) are monocots with linear parallel venation and adventitious fibrous roots.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23666f30-b5b4-43f3-88aa-d0e86b0787bf', 'Maize, Wheat, and Grass', true, '02ebfb28-38cf-40bd-a31d-cec90224d2c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf76c832-19b8-4716-ae26-6fd5c86cdffe', 'Mustard and Gram', false, '02ebfb28-38cf-40bd-a31d-cec90224d2c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fe4d491-66ca-473b-bf17-5d86ed6b9a14', 'Mango and Peepal', false, '02ebfb28-38cf-40bd-a31d-cec90224d2c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef8d355c-2386-4989-a527-9f0bfd066936', 'China rose and Rose', false, '02ebfb28-38cf-40bd-a31d-cec90224d2c3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c94e72e-770a-41aa-8638-d114b2b38c93', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddda2b9b-23d5-4c2d-94b3-100eb1b77e0f', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '4c94e72e-770a-41aa-8638-d114b2b38c93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0dc2361-c52e-4b91-a60d-94d2ebd433e6', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '4c94e72e-770a-41aa-8638-d114b2b38c93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1380ca60-cea0-4c2c-982e-ac7261f839cc', '(A) is true, but (R) is false.', false, '4c94e72e-770a-41aa-8638-d114b2b38c93');
