INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc6c9eac-f930-47ed-9c6d-a10593b4396f', 'Ginger', true, '380d3a67-c34c-4e7c-9704-13490b974177');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a04a8cff-87ab-4f93-95d9-7a6616c57b66', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'A potted green plant kept inside a dark cupboard for 48 hours is tested with iodine solution for starch. The leaf does NOT turn blue-black. Why?', 'Without photons to drive light reactions, dark metabolism hydrolyzes stored amylose reserves to sustain basal cellular respiration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e971abf1-e3b2-4233-a9ce-1149212db2e4', 'In the absence of sunlight, photosynthesis ceased, and the plant consumed all its stored starch through cellular respiration (Destarching)', true, 'a04a8cff-87ab-4f93-95d9-7a6616c57b66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93493f0b-bd31-4a59-9028-dbe7c0b62138', 'The iodine lost its chemical power', false, 'a04a8cff-87ab-4f93-95d9-7a6616c57b66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a8018a8-ac0a-47f5-aab8-742a1ea7338b', 'The leaves dissolved in the dark', false, 'a04a8cff-87ab-4f93-95d9-7a6616c57b66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df4b5b94-408f-4042-9b83-23c02e3a57ec', 'Darkness creates excess starch', false, 'a04a8cff-87ab-4f93-95d9-7a6616c57b66');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17e37458-7db8-4818-af33-1c42a56d2715', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'Match Column I (Flower Organs) with Column II (Functions):
(a) Sepals   -> (i) Protect flower during bud stage
(b) Petals   -> (ii) Attract insect pollinators
(c) Anther   -> (iii) Produce male pollen grains
(d) Stigma   -> (iv) Receive pollen grains during pollination', 'Sepals = bud protection; Petals = pollinator attraction; Anther = pollen genesis; Stigma = pollen reception.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f570b9a-17da-4141-902d-11699d5f5316', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '17e37458-7db8-4818-af33-1c42a56d2715');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7b3da92-94fe-4ff3-8442-4f1681cb2eb3', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '17e37458-7db8-4818-af33-1c42a56d2715');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2648b912-de78-413d-be48-a181048cf72b', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '17e37458-7db8-4818-af33-1c42a56d2715');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8051d94e-dec5-4a71-ab35-86630970e1be', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '17e37458-7db8-4818-af33-1c42a56d2715');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a6eb1e6-79dd-4096-90fa-ac28012b5504', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'Read the statements regarding plant physiology:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('745ba487-e675-41be-94af-f82213076775', 'Statements 1 and 3 only', true, '8a6eb1e6-79dd-4096-90fa-ac28012b5504');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('314042af-a7ad-424c-88b9-6758939d09bb', 'Statements 1 and 2 only', false, '8a6eb1e6-79dd-4096-90fa-ac28012b5504');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dc38d27-1e74-4af6-8aa9-11b9478c8c6d', 'Statements 2 and 3 only', false, '8a6eb1e6-79dd-4096-90fa-ac28012b5504');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa60a011-257a-482b-8619-7650c372e95e', 'All Statements 1, 2, and 3', false, '8a6eb1e6-79dd-4096-90fa-ac28012b5504');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6083034a-a047-4c7f-b0b1-6b59dff8d1f9', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'Why do desert xerophytic plants (like Opuntia cactus) have leaves modified into sharp spines and fleshy green stems?', 'Foliar reduction into sclerified spines minimizes surface area for transpiration, while the phylloclade stem handles photosynthesis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1aa32117-b3cf-4ea1-bf62-44c53b4989d3', 'Spines drastically reduce water loss via transpiration, while the thick green stem carries out photosynthesis and stores succulent water', true, '6083034a-a047-4c7f-b0b1-6b59dff8d1f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e694c55-82a7-4d83-b9a7-9296dcd564d9', 'Spines absorb water from air', false, '6083034a-a047-4c7f-b0b1-6b59dff8d1f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcade891-5681-4646-a694-1c8dfaa5d011', 'To frighten wild animals only', false, '6083034a-a047-4c7f-b0b1-6b59dff8d1f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2460f8e3-7f60-4781-abf5-ff1b9c8d55c6', 'Because desert soil has no minerals', false, '6083034a-a047-4c7f-b0b1-6b59dff8d1f9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14580ec6-4ed2-4767-8928-4f0f6cdb936d', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'A student slices an ovary of a hibiscus flower horizontally (transverse cut) and another longitudinally (vertical cut). What do they observe under a magnifying lens?', 'Microscopic inspection reveals unfertilized megasporangiate ovules anchored to the central placenta within multi-locular carpels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca6a79ab-523f-4012-b9b0-f8b52e49bd9b', 'Small bead-like ovules arranged inside distinct ovarian chambers (locules)', true, '14580ec6-4ed2-4767-8928-4f0f6cdb936d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46137dab-f15e-4f7e-b32c-a98ee7ddb733', 'Fully formed green seeds', false, '14580ec6-4ed2-4767-8928-4f0f6cdb936d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73073df9-1700-4d22-a346-059a1a916284', 'Flowing red ink', false, '14580ec6-4ed2-4767-8928-4f0f6cdb936d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d05aef39-a668-4fec-bb8a-984b7e43cd02', 'Tiny pollen tubes only', false, '14580ec6-4ed2-4767-8928-4f0f6cdb936d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9f2b512-1c3d-4cb4-9077-ac7831fbf83b', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'Consider four plants:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd3bfd17-c0c4-4a2c-8455-4aa336bfb992', 'Plant 3 (Bamboo)', true, 'e9f2b512-1c3d-4cb4-9077-ac7831fbf83b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38736cc4-a256-4d0f-bfc5-bfb5e21ddbab', 'Plant 1 (Hibiscus)', false, 'e9f2b512-1c3d-4cb4-9077-ac7831fbf83b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07a9e99e-9c4c-4282-ac43-2c35f6a620ae', 'Plant 2 (Mustard)', false, 'e9f2b512-1c3d-4cb4-9077-ac7831fbf83b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c2eaad5-f120-4551-837b-c6fded4d3db1', 'Plant 4 (Mango)', false, 'e9f2b512-1c3d-4cb4-9077-ac7831fbf83b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('832a65ef-475a-4b0c-a6f2-79a95b2f38a5', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'Why must a leaf be boiled in alcohol / surgical spirit over a water bath (and NEVER directly over an open burner flame) during the starch test?', 'Ethanol''s low flash point (~13°C) demands indirect heating in a double-boiler water bath to safely extract chlorophyll.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cba30c18-b3ca-4467-bdbf-f878d7444531', 'Alcohol is highly flammable and volatile; heating directly over an open flame would ignite it and cause a severe fire hazard', true, '832a65ef-475a-4b0c-a6f2-79a95b2f38a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('670c1374-9e8a-4061-9380-fc98560a4596', 'Water bath makes the leaf sweet', false, '832a65ef-475a-4b0c-a6f2-79a95b2f38a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9103b5dd-d9dc-4083-ac1b-a164b98facc7', 'Direct flame freezes alcohol', false, '832a65ef-475a-4b0c-a6f2-79a95b2f38a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2eadd33d-d141-4b78-8bc6-5b65d1394e26', 'Alcohol turns into stone over flame', false, '832a65ef-475a-4b0c-a6f2-79a95b2f38a5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0fa16407-b6a3-4189-b281-9db25a892d68', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'What is the primary role of the ''transpiration pull'' generated by leaves in tall hundred-meter giant redwood trees?', 'Cohesion-Tension theory: Meniscus evaporation in stomatal chambers generates negative xylem xylem sap tension (~-2 MPa) pulling water upwards.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4746204-0e11-41c1-ab51-93662e151e75', 'It creates continuous negative hydrostatic suction tension that lifts water and dissolved mineral ions from deep root hair cells to top canopy leaves', true, '0fa16407-b6a3-4189-b281-9db25a892d68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('479c5140-8281-49c6-a662-fd2a52186fea', 'It pushes the tree trunk into the ground', false, '0fa16407-b6a3-4189-b281-9db25a892d68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb5c2702-2aaf-45a1-b32a-94711af59054', 'It stops the leaves from getting green', false, '0fa16407-b6a3-4189-b281-9db25a892d68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c12d23af-440a-400a-8708-eaf369e1117d', 'It keeps the tree warm in summer', false, '0fa16407-b6a3-4189-b281-9db25a892d68');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6707c47-6452-4263-88fd-a707aaff43bb', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'Which of the following flowers is ''Incomplete'' because it lacks either male stamens or female pistil in the same blossom (Unisexual flower)?', 'Papaya and cucumber are dioecious/monoecious species bearing unisexual staminate (male) or pistillate (female) flowers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7682e58-3c88-48e5-bc2c-ae5113920b28', 'Papaya and Cucumber flower', true, 'f6707c47-6452-4263-88fd-a707aaff43bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6019f54f-b757-44c0-aab7-d6749d0b00fe', 'Mustard flower', false, 'f6707c47-6452-4263-88fd-a707aaff43bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7df00502-5565-4c16-ae51-54d9110cf242', 'China rose (Hibiscus)', false, 'f6707c47-6452-4263-88fd-a707aaff43bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdbc5738-0399-4603-8aa8-ed44047be008', 'Rose flower', false, 'f6707c47-6452-4263-88fd-a707aaff43bb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c143917-1467-4c5c-98a8-35bbb9de308e', 'Class 6', 'Science', 'Chapter 4: Getting to Know Plants', 'Hard', 'What anatomical pathway traces the path of a water molecule from soil entry to atmospheric release?', 'Unidirectional transpiration stream: soil water traverses root cortex into central vascular stele, ascends xylem pipes, and exits via leaf stomata.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fb15cb1-c471-481d-be71-62663ae2c976', 'Soil water -> Root hair -> Root xylem -> Stem xylem -> Leaf petiole & veins -> Stomatal pores -> Atmosphere (as vapor)', true, '1c143917-1467-4c5c-98a8-35bbb9de308e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d61533f9-bf22-400b-82bd-fe69aa85eb78', 'Leaf -> Stem -> Root -> Soil', false, '1c143917-1467-4c5c-98a8-35bbb9de308e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0a00329-8584-4c2d-b2dc-260b2e473022', 'Flower -> Stem -> Root -> Seed', false, '1c143917-1467-4c5c-98a8-35bbb9de308e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b1acf13-6f6d-4cbb-ac48-1efde00b9e05', 'Soil -> Stoma -> Root -> Stem', false, '1c143917-1467-4c5c-98a8-35bbb9de308e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('258df8b1-c894-4928-9b9f-1aa8b390790c', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Easy', 'A dimensionless location in space which has zero length, zero breadth, and zero thickness, denoted by a sharp dot, is a:', 'A point is a fundamental geometric primitive indicating an exact position in space, represented by a single capital letter (e.g. Point A).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea6c68fa-20c9-45dd-97d5-b0c45d1f4e9f', 'Point', true, '258df8b1-c894-4928-9b9f-1aa8b390790c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b281aaaf-592f-4ae0-8053-9686d3f4a012', 'Line', false, '258df8b1-c894-4928-9b9f-1aa8b390790c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1b3968e-22b4-4a78-a990-c6c5597765f6', 'Ray', false, '258df8b1-c894-4928-9b9f-1aa8b390790c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('953bafe7-af1f-4b97-8555-94f2c61f10e9', 'Plane', false, '258df8b1-c894-4928-9b9f-1aa8b390790c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38a90c02-7520-4b16-8a01-3384d59f3bac', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Easy', 'A straight path connecting two fixed end points A and B, which has a definite measurable length, is called a:', 'A line segment AB is the shortest path bounded by two distinct end points A and B.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07e5eaab-c652-47df-b4ba-a0e8ba9f44c1', 'Line Segment (denoted as AB)', true, '38a90c02-7520-4b16-8a01-3384d59f3bac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3b427bc-478a-4218-b712-acc6553e2b48', 'Line', false, '38a90c02-7520-4b16-8a01-3384d59f3bac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dc2bb51-991f-44fd-86fe-964a784f552d', 'Ray', false, '38a90c02-7520-4b16-8a01-3384d59f3bac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c49323a4-2b3d-45bc-9814-ab23ed8133ef', 'Curve', false, '38a90c02-7520-4b16-8a01-3384d59f3bac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a89d3a9-30c3-4285-960e-650f91f085e8', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Easy', 'A straight path that extends infinitely without end in BOTH directions and has no fixed length is called a:', 'A line extends boundlessly in both opposite directions and has zero end points.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9288d104-5707-4431-8a73-b9b1507a2155', 'Line (denoted as AB with double arrows)', true, '8a89d3a9-30c3-4285-960e-650f91f085e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cddf8ea5-a572-4381-b457-1a24ee301ede', 'Line Segment', false, '8a89d3a9-30c3-4285-960e-650f91f085e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9383fc13-7ae6-4c3f-b01d-36ae112164a2', 'Ray', false, '8a89d3a9-30c3-4285-960e-650f91f085e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93d02af4-cea5-4654-b1fd-d1c368ac3a57', 'Angle', false, '8a89d3a9-30c3-4285-960e-650f91f085e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93cd03e5-2b4c-4d6d-8cc8-00a82324a453', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Easy', 'A portion of a line that starts at one fixed starting point (initial point) and extends endlessly in one direction is called a:', 'A ray has exactly one starting endpoint and extends infinitely in the designated direction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4998f193-8a0d-40da-9020-acfb85df03c0', 'Ray (e.g. Sun ray, torch ray, denoted as AB)', true, '93cd03e5-2b4c-4d6d-8cc8-00a82324a453');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5611890-ec73-4c2a-b31a-6d7f5b07d766', 'Line Segment', false, '93cd03e5-2b4c-4d6d-8cc8-00a82324a453');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4571b87b-0a84-45c3-bfba-4060f2051cbe', 'Line', false, '93cd03e5-2b4c-4d6d-8cc8-00a82324a453');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24f680b4-8f01-4f1b-ad7a-2125706ec6b8', 'Chord', false, '93cd03e5-2b4c-4d6d-8cc8-00a82324a453');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7927d7d6-e3c3-494b-a0bb-91cdf99c2d63', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Easy', 'Two straight lines that meet or cross each other at a single common point are called:', 'If two distinct coplanar lines share exactly one common intersection point, they are intersecting lines.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a937338b-4996-48b1-92e5-effcd67aa29b', 'Intersecting Lines', true, '7927d7d6-e3c3-494b-a0bb-91cdf99c2d63');
