INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('80ee4103-ef03-4318-b948-01da82f88440', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Medium', 'Into how many distinct regions does a simple closed curve divide the plane it lies on?', 'Jordan Curve Theorem: A simple closed planar curve partitions the plane into interior, boundary, and exterior.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ec75b62-c837-4e3a-ae45-e31e9fc491cb', 'Three regions: 1. Interior (inside), 2. Boundary (on the curve), 3. Exterior (outside)', true, '80ee4103-ef03-4318-b948-01da82f88440');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff033c67-1c86-4639-abe4-58939b8cb527', 'Two regions', false, '80ee4103-ef03-4318-b948-01da82f88440');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a8928e3-0721-4dc2-aaea-a181c192906e', 'Four regions', false, '80ee4103-ef03-4318-b948-01da82f88440');
