INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ee888fc1-7087-459e-a5d0-ede9ee1d75c2', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Medium', 'What is a 4-sided polygon called in geometry?', 'A quadrilateral is a 4-gon consisting of 4 vertices, 4 edges, and 2 internal diagonals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3442d8a3-a8c3-4737-9ade-8e220fd85c90', 'Quadrilateral (has 4 sides, 4 vertices, 4 angles, and 2 diagonals)', true, 'ee888fc1-7087-459e-a5d0-ede9ee1d75c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce2beb23-966f-4ebd-bdd3-486569c87dbc', 'Triangle', false, 'ee888fc1-7087-459e-a5d0-ede9ee1d75c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a156575-d150-4ad3-a05d-a17df06ab58c', 'Pentagon', false, 'ee888fc1-7087-459e-a5d0-ede9ee1d75c2');
