INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('393113c7-3da2-4f38-b59e-8b1c89940d6f', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Medium', 'How many diagonals does a regular quadrilateral (4-sided polygon) possess?', 'Formula d = n(n-3)/2; for n = 4: d = 4(4-3)/2 = 2 diagonals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6893da7c-144e-450c-b180-5ee2ed8bb3f7', '2 diagonals', true, '393113c7-3da2-4f38-b59e-8b1c89940d6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8b4966b-4dc2-4a07-8945-76f8dcf9cd81', '4 diagonals', false, '393113c7-3da2-4f38-b59e-8b1c89940d6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ba33aa9-fb9e-4db9-b6da-82d891cf4748', '1 diagonal', false, '393113c7-3da2-4f38-b59e-8b1c89940d6f');
