INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('80f834dd-fb38-471c-9044-116295e36f97', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Medium', 'How many diagonals does a Triangle (3-sided polygon) have?', 'In a triangle, all vertices are adjacent to one another; d = 3(3-3)/2 = 0.', NOW()) ON CONFLICT DO NOTHING;
