INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ee69ade-e315-423d-a9b0-bf615535161a', '1 diagonal', false, '80f834dd-fb38-471c-9044-116295e36f97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a11209a-068f-4125-adb3-11e175ff9af7', '3 diagonals', false, '80f834dd-fb38-471c-9044-116295e36f97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99496a08-f240-4dbc-a33a-7d16f879cf7d', '2 diagonals', false, '80f834dd-fb38-471c-9044-116295e36f97');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a698d56d-b317-44bc-8756-2448247170fe', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Medium', 'A diameter of a circle divides the entire circular region into two exact equal halves called:', 'A central diameter chord bisects the circle into two congruent semicircles.', NOW()) ON CONFLICT DO NOTHING;
