INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d900ad92-4b18-4122-9cc7-69e6c14ebead', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Medium', 'Which of the following is an everyday physical model of a Line Segment?', 'The edge of a ruler has two distinct endpoints and a measurable length, modeling a line segment.', NOW()) ON CONFLICT DO NOTHING;
