INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f4bc742-6f72-4257-b689-e3cf13ae2f4d', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Hard', 'How many total diagonals exist in a Pentagon (5-sided polygon)?', 'Formula d = n(n-3)/2; for n = 5: d = 5(5-3)/2 = 5 × 2 / 2 = 5 diagonals (forming a star).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9231bd3d-180e-426c-b052-42dc7cd768a8', '5 diagonals', true, '7f4bc742-6f72-4257-b689-e3cf13ae2f4d');
