INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba54c60a-dc19-4207-9ce8-3606a08ab079', '4 diagonals', false, '7f4bc742-6f72-4257-b689-e3cf13ae2f4d');
