INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10853081-a070-46db-b769-e4cf6b8a77f7', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Hard', 'How many total diagonals exist in a Hexagon (6-sided polygon)?', 'Formula d = n(n-3)/2; for n = 6: d = 6(6-3)/2 = 6 × 3 / 2 = 9 diagonals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11771f2a-8581-41ce-85f4-4eb1c577d212', '9 diagonals', true, '10853081-a070-46db-b769-e4cf6b8a77f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99509f93-1d89-403c-8d90-8d9990c5533c', '6 diagonals', false, '10853081-a070-46db-b769-e4cf6b8a77f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b33d799-29df-4e14-83c1-5f50a32af82f', '12 diagonals', false, '10853081-a070-46db-b769-e4cf6b8a77f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2b5ac1c-53cc-48a6-8ef1-4fa2f1f2d508', '15 diagonals', false, '10853081-a070-46db-b769-e4cf6b8a77f7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b67fa3ad-6165-4d20-90b7-afae202d1f6a', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Hard', 'Match Column I (Geometric Terms) with Column II (Definitions):
(a) Ray       -> (i) Two endpoints with fixed length
(b) Line      -> (ii) One endpoint, extending infinitely in one direction
(c) Segment   -> (iii) Zero endpoints, extending infinitely both ways
(d) Point     -> (iv) Position in space with zero dimensions', 'Ray = 1 endpoint; Line = 0 endpoints (infinite both sides); Segment = 2 endpoints; Point = 0 dimensions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6d43dc5-f81a-4fbc-8a98-1d1ceb79eaef', 'a-(ii), b-(iii), c-(i), d-(iv)', true, 'b67fa3ad-6165-4d20-90b7-afae202d1f6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3611de2-106c-4138-83be-9db08ce0e5e9', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'b67fa3ad-6165-4d20-90b7-afae202d1f6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b588193-763f-49b1-bc07-f6c202e0255e', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'b67fa3ad-6165-4d20-90b7-afae202d1f6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fb2006a-f9cc-47fc-acd0-c4e5065fc146', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'b67fa3ad-6165-4d20-90b7-afae202d1f6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d24ed0d-3d63-4f5c-8971-89f4450dedeb', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0160eccb-7acd-47ca-b3c6-77a4a0a58a19', 'Statements 1 and 2 only', true, '7d24ed0d-3d63-4f5c-8971-89f4450dedeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce42d65c-a741-4e2f-a273-547bc3bdf068', 'Statements 2 and 3 only', false, '7d24ed0d-3d63-4f5c-8971-89f4450dedeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0131ddae-2fac-4a06-a533-42bc9946db0d', 'Statements 1 and 3 only', false, '7d24ed0d-3d63-4f5c-8971-89f4450dedeb');
