INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a0785b9-74ce-408e-97f7-e14f93459a55', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Hard', 'In a quadrilateral ABCD, which of the following represents a pair of OPPOSITE sides and a pair of OPPOSITE angles?', 'In polygon ABCD, vertices order A-B-C-D means AB is opposite CD, and ∠A is diagonally opposite ∠C.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39b3943f-2da9-4ef0-9e4d-59ddbcd83096', 'Opposite sides: (AB and CD) ; Opposite angles: (∠A and ∠C)', true, '8a0785b9-74ce-408e-97f7-e14f93459a55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1785c10f-1d92-44ce-a73f-093331d84cc7', 'Opposite sides: (AB and BC)', false, '8a0785b9-74ce-408e-97f7-e14f93459a55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76dabcc9-c919-415d-94ba-a3f775aa5876', 'Opposite angles: (∠A and ∠B)', false, '8a0785b9-74ce-408e-97f7-e14f93459a55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2ecc776-6fa1-4286-8c00-76309d09ec1f', 'Opposite sides: (BC and CD)', false, '8a0785b9-74ce-408e-97f7-e14f93459a55');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43e8bd57-c65b-48b5-a4a1-ab91f830e7e8', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Hard', 'How many lines can be drawn passing through any TWO points chosen out of FOUR collinear points?', 'Since all 4 points lie on the exact same single straight line, every pair defines that same unique collinear line.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2c20de1-084e-4024-aa0c-7fc667fa4da7', 'Only 1 line', true, '43e8bd57-c65b-48b5-a4a1-ab91f830e7e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ea1ce6a-b065-47d3-bb9c-cf97ba25c9fa', '4 lines', false, '43e8bd57-c65b-48b5-a4a1-ab91f830e7e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4506c0e-325d-494d-8260-753eb4372633', '6 lines', false, '43e8bd57-c65b-48b5-a4a1-ab91f830e7e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db754736-b2b6-440a-9bc3-f407bd15eba4', 'Infinite lines', false, '43e8bd57-c65b-48b5-a4a1-ab91f830e7e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c2da55a-d2a1-4b87-bd1b-d64ae6e5480a', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Hard', 'How many lines can be drawn passing through pairs of points chosen from FOUR points where NO THREE points are collinear?', 'Combinatorial formula n(n-1)/2: with 4 non-collinear points, total unique lines = 4 × 3 / 2 = 6 lines.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cb21ca0-f4af-4fbe-93c1-8996a28aad25', '6 lines (4C2 = 4 × 3 / 2 = 6)', true, '5c2da55a-d2a1-4b87-bd1b-d64ae6e5480a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4399b0dd-75b0-40fb-a1b9-ee8f065e1c60', '4 lines', false, '5c2da55a-d2a1-4b87-bd1b-d64ae6e5480a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad4fe4da-a57b-4ebb-8ee9-37b812536758', '8 lines', false, '5c2da55a-d2a1-4b87-bd1b-d64ae6e5480a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a71abb9f-e924-43ac-b352-528e32237b5c', '1 line', false, '5c2da55a-d2a1-4b87-bd1b-d64ae6e5480a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac115e17-c716-4c5d-8f24-2fa8b36f6aae', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Hard', 'What is the difference between an ''Open Curve'' and a ''Closed Curve''?', 'Closed curves enclose a bounded interior domain because their endpoints join; open curves do not bound an interior.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56ba7f0f-1ce3-428a-86f5-b2b7a38a1d9b', 'In an open curve, the two starting and ending points do not meet, whereas in a closed curve, the path begins and ends at the exact same point', true, 'ac115e17-c716-4c5d-8f24-2fa8b36f6aae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4b2f8a1-f24d-48f3-9dca-530b7cba8425', 'An open curve is made of metal', false, 'ac115e17-c716-4c5d-8f24-2fa8b36f6aae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fce8857b-614e-438c-ad4c-008f2f920235', 'A closed curve is always a straight line', false, 'ac115e17-c716-4c5d-8f24-2fa8b36f6aae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b80ed24-849a-49f1-ae41-68966a76740e', 'There is no difference', false, 'ac115e17-c716-4c5d-8f24-2fa8b36f6aae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('222c6a7f-be67-4130-8071-a3320a6c6b67', 'Class 6', 'Mathematics', 'Chapter 4: Basic Geometrical Ideas', 'Hard', 'Consider a point P situated inside a circle of radius 5 cm. If the distance from the center O to point P is d(O, P) = 3.5 cm, where does point P lie?', 'Since d(O, P) = 3.5 cm < r = 5 cm, point P lies strictly within the circle''s interior.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16a5b403-c099-4fc8-b681-d83036a9c25f', 'In the Interior of the circle', true, '222c6a7f-be67-4130-8071-a3320a6c6b67');
