INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f805f83c-0af9-4760-9368-17d45a486c7d', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Easy', 'How many crew members (astronauts) were on board Space Shuttle Columbia during the STS-107 mission?', 'A multinational crew of seven astronauts (including Israeli Ilan Ramon and Kalpana) staffed STS-107.', NOW()) ON CONFLICT DO NOTHING;
