INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5b3a03c4-32b4-425f-9c8b-cecff67ac46a', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Easy', 'In the poem ''Beauty'' by E-Yeh-Shure, where can beauty be seen according to the poet?', 'Native American poet E-Yeh-Shure describes beauty in simple natural wonders, agriculture, and joyous human labor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30eedcdd-c7cf-4e93-9f14-43d2babed966', 'In the sunlight, trees, birds, growing corn, and people working or dancing for their harvest', true, '5b3a03c4-32b4-425f-9c8b-cecff67ac46a');
