INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ecff42e-5aca-4cb7-83a1-8f90bedf4dbd', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Easy', 'In the supplementary story ''The Old-Clock Shop'', who was Ray?', 'Ray was an elderly, hearing-impaired craftsman who repaired and loaned money on old timepieces in Salt Lake City.', NOW()) ON CONFLICT DO NOTHING;
