INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8c12a62d-f5a4-47bb-83c1-d5f48c358d27', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Easy', 'On which evening did two desperate men visit Ray''s old clock shop?', 'The two men entered just as Ray was finishing work on a cold Christmas Eve night.', NOW()) ON CONFLICT DO NOTHING;
