INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cbdb8ba-3057-45f5-bde6-ce5efb8b6b46', 'Halloween night', false, '8c12a62d-f5a4-47bb-83c1-d5f48c358d27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d89905f-44f9-4466-b13e-50e8b2d91ea3', 'Easter Sunday', false, '8c12a62d-f5a4-47bb-83c1-d5f48c358d27');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74a91450-f5bb-4b6a-bf7a-fd2b3a639ece', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Medium', 'What inspiring message did Kalpana Chawla send to students from aboard the Space Shuttle Columbia?', 'Her immortal transmission from Columbia inspired youth worldwide to boldly pursue their highest aspirations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8779270d-f278-41a0-8db4-663b827a9db9', '"The path from dreams to success does exist. May you have the vision to find it, the courage to get onto it, and the perseverance to follow it."', true, '74a91450-f5bb-4b6a-bf7a-fd2b3a639ece');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe7018f8-d0b0-4154-b683-2768f583ae2e', '"Space is too dangerous for students."', false, '74a91450-f5bb-4b6a-bf7a-fd2b3a639ece');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59899073-e258-43d2-b32f-21aac64fa77f', '"Never leave your hometown."', false, '74a91450-f5bb-4b6a-bf7a-fd2b3a639ece');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('566c2c54-9bac-4301-aecc-88cf2ef11a31', '"Success comes without any hard work."', false, '74a91450-f5bb-4b6a-bf7a-fd2b3a639ece');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e0dc5d3b-27e8-402e-b6d4-13b3243a52f8', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Medium', 'What other aircraft pilot licenses did Kalpana Chawla hold besides astronaut qualifications?', 'She was a multi-engine land and seaplane pilot, glider enthusiast, and FAA-certified flight instructor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30443704-1ecf-4102-b32c-9eba0386110a', 'Commercial pilot licenses for single and multi-engine land planes, single-engine seaplanes, gliders, and certified flight instructor', true, 'e0dc5d3b-27e8-402e-b6d4-13b3243a52f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3bd6dfe-d5cb-43ce-88ff-e79f8b1de6ca', 'Helicopter military gunship license only', false, 'e0dc5d3b-27e8-402e-b6d4-13b3243a52f8');
