INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c1f292b-8610-48e6-be1e-11176d290e62', 'Commercial rocket captain', false, 'e0dc5d3b-27e8-402e-b6d4-13b3243a52f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8eafa32-8000-4a79-8d5d-aa1ebc3a777b', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Medium', 'What scientific experiments did the Columbia crew conduct during their 16-day STS-107 flight?', 'The SPACEHAB payload conducted 80 microgravity biology, physical science, and fluid physics experiments.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54f8a493-e675-4c11-9731-738e500a6c9f', '80 scientific experiments including plant microgravity pollination, materials crystal growth, and combustion behavior in space', true, 'd8eafa32-8000-4a79-8d5d-aa1ebc3a777b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('931bf896-caf9-4efd-ad4f-eed32f2a629a', 'Military missile target testing', false, 'd8eafa32-8000-4a79-8d5d-aa1ebc3a777b');
