INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b527f556-de44-40d7-baa4-eb7fb0a5ff84', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Medium', 'Why was Ray NOT a commercial moneylender / pawn-broker in the traditional sense?', 'Ray operated out of goodwill, providing bridge loans against used watches to aid destitute folks through hard times.', NOW()) ON CONFLICT DO NOTHING;
