INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c53398e8-8998-4574-a0af-cdaedf9fdb13', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Medium', 'What did journalists write about Kalpana Chawla''s extraordinary intellectual capability?', 'Her biographical tribute highlighted the multidisciplinary mastery of mathematics, biology, astronomy, and physics required of astronauts.', NOW()) ON CONFLICT DO NOTHING;
