INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1537c7c3-7886-47b7-aa71-3442f7d20176', 'Class 6', 'English', 'Chapter 4: An Indian-American Woman in Space: Kalpana Chawla', 'Hard', 'What is the figurative meaning of the phrase ''to cross the frontiers of space''?', '''Frontiers of space'' symbolizes the outermost boundary of human technological reach and cosmic exploration.', NOW()) ON CONFLICT DO NOTHING;
