INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ede48e15-f14a-4dc5-b9ae-996c9359a2b1', 'Class 6', 'GK', 'Chapter 4: Wildlife, Flora & National Parks of India', 'Hard', 'What is the crucial ecological difference between a ''National Park'' and a ''Wildlife Sanctuary'' in India under the Wildlife Protection Act 1972?', 'National Parks have a higher degree of statutory protection with complete prohibition on livestock grazing and resource extraction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a850872c-4bed-4289-836c-136dc87dc084', 'In a National Park, human activities (grazing, timber harvesting, private land ownership) are strictly prohibited, whereas in a Wildlife Sanctuary, limited traditional human activities may be permitted', true, 'ede48e15-f14a-4dc5-b9ae-996c9359a2b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ca43a1c-7cfc-478b-ae70-077a91b560a0', 'Sanctuaries only have birds while parks have lions', false, 'ede48e15-f14a-4dc5-b9ae-996c9359a2b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ada25cf9-1be8-47b4-b68b-44f67e9349e4', 'National parks are owned by private companies', false, 'ede48e15-f14a-4dc5-b9ae-996c9359a2b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('317f8456-d9f6-4692-b959-92608cb29d94', 'There is zero difference', false, 'ede48e15-f14a-4dc5-b9ae-996c9359a2b1');
