INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('743d7f3a-ae69-4f5d-bfa4-fe7360d37c6f', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'What are the THREE essential components of any standard map?', 'Cartography rests on three foundational structural components: Scale (Distance), Orientation (Direction), and Legend (Symbols).', NOW()) ON CONFLICT DO NOTHING;
