INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98b5d6b3-ddc4-4bef-89c9-d11b4aaa3c86', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'The ratio between the actual ground distance on the Earth and the distance shown on the map paper is called the:', 'Map scale = (Distance on Map) / (Actual Ground Distance).', NOW()) ON CONFLICT DO NOTHING;
