INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa7522ff-ba4a-4745-a04a-b4a7dbb391ae', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'What are the FOUR major Cardinal Points / Directions on a map?', 'The four primary cardinal directions are North (N), South (S), East (E), and West (W).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f4531d7-00e3-482a-88d9-8734fead03b7', 'North, South, East, and West', true, 'aa7522ff-ba4a-4745-a04a-b4a7dbb391ae');
