INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1f39df7c-f113-4b2e-8c9b-0d056981e13e', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'What are the four intermediate directions located between the cardinal points?', 'The four ordinal/intercardinal compass bearings are NE (45°), SE (135°), SW (225°), and NW (315°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a884eaa1-8ffb-42b2-9d3c-db7c6a7d3144', 'North-East (NE), South-East (SE), South-West (SW), and North-West (NW)', true, '1f39df7c-f113-4b2e-8c9b-0d056981e13e');
