INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aae9f78f-ef23-4f08-90a2-2b40b18d6bff', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'An instrument used to find the main directions, featuring a magnetic needle that always points towards the North-South direction, is a:', 'A magnetic compass needle aligns itself with the geomagnetic dipole axis pointing towards magnetic North.', NOW()) ON CONFLICT DO NOTHING;
