INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18bc741d-e1f3-4c10-bb91-0101ec020027', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'Symbols on a map that are internationally agreed upon and recognized across the world are called:', 'Conventional signs and symbols follow standardized international cartographic conventions (e.g. blue for water, green for forests).', NOW()) ON CONFLICT DO NOTHING;
