INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('57dd53c1-a144-4a96-8adc-f8456c340a77', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'On a standard physical map, what natural feature is universally represented using BLUE color?', 'In standard topographic symbology, cyan/blue shades denote water bodies, streams, and reservoirs.', NOW()) ON CONFLICT DO NOTHING;
