INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2cc677b-7a2d-4a56-ac87-03412e4571bb', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Easy', 'A book or bound collection of various maps of the world, continents, and countries is called an:', 'An Atlas is a comprehensive bound volume of geographical, thematic, and political charts.', NOW()) ON CONFLICT DO NOTHING;
