INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba65b946-ffa2-4902-8d0d-df830c9c2779', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What is the key difference between a ''Small Scale Map'' and a ''Large Scale Map''?', 'Scale fraction 1/50,000,000 is small (macro coverage), while 1/5,000 is large (micro granular street detail).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a5d1a15-4833-4ce0-a702-7275412d7827', 'A Small Scale map shows large areas (continents/countries) with less detail (e.g. 1 cm = 500 km), while a Large Scale map shows small areas (villages/towns) with great detail (e.g. 1 cm = 50 m)', true, 'ba65b946-ffa2-4902-8d0d-df830c9c2779');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52b96758-d2b7-48e9-a6cc-3a7f1c564272', 'A Small scale map is drawn on tiny paper', false, 'ba65b946-ffa2-4902-8d0d-df830c9c2779');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c3f1961-6cb3-4c0a-9c19-128862ba8a07', 'A Large scale map shows only outer space', false, 'ba65b946-ffa2-4902-8d0d-df830c9c2779');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f476115-583c-485e-b7cb-52aa4dd25ff5', 'There is no difference', false, 'ba65b946-ffa2-4902-8d0d-df830c9c2779');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7a3ecf8-d3cc-4638-84f3-7ad2bbe9f7a3', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What is a ''Sketch'' in cartography?', 'A sketch map is a rapid, non-instrumental mental drawing showing landmarks to guide directions without scale.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dba7325-4bee-4857-8bc4-9b6223d7472c', 'A rough drawing mainly based on memory and spot observation without any scale', true, 'c7a3ecf8-d3cc-4638-84f3-7ad2bbe9f7a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e19208e9-2705-4c74-948a-56bff2926963', 'A mathematically accurate scaled blueprint', false, 'c7a3ecf8-d3cc-4638-84f3-7ad2bbe9f7a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f34450a6-b716-4aa9-9266-647eac94b26f', 'A satellite photograph', false, 'c7a3ecf8-d3cc-4638-84f3-7ad2bbe9f7a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b6ced7e-aea8-4f5a-b840-ef6a70b41e9f', 'A globe', false, 'c7a3ecf8-d3cc-4638-84f3-7ad2bbe9f7a3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ce9b7586-de65-4d93-a435-82db1d7e74ce', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What is a ''Plan'' in cartography and architecture?', 'A plan provides ultra-large-scale engineering dimensions for an individual architectural space or plot.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1eb49e9-1842-4ae6-bd14-21d1434fd30e', 'A drawing of a small area (like a single room or house) drawn on a very large scale showing minute measurements like length and breadth', true, 'ce9b7586-de65-4d93-a435-82db1d7e74ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('649b815f-6577-4824-9a46-2a23edb3b6c1', 'A rough sketch of a continent', false, 'ce9b7586-de65-4d93-a435-82db1d7e74ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1349fe29-5250-4cfd-92dd-76cee10b6177', 'A world map', false, 'ce9b7586-de65-4d93-a435-82db1d7e74ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cc339e0-7b2c-4c8a-8121-e5ebb5e95bfc', 'A weather forecast', false, 'ce9b7586-de65-4d93-a435-82db1d7e74ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f83ae2bf-f62e-44db-8bc0-d63c1191ee7e', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What does the letter ''N'' with an arrow at the upper right-hand corner of a map indicate?', 'The North Arrow indicates true geodetic or grid north, establishing map orientation for navigation.', NOW()) ON CONFLICT DO NOTHING;
