INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('887a056c-6925-449d-8281-cc6ec457a60e', 'New Town', false, 'f83ae2bf-f62e-44db-8bc0-d63c1191ee7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('980ab986-0786-489f-9920-14e36ee548b2', 'No Entry', false, 'f83ae2bf-f62e-44db-8bc0-d63c1191ee7e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4854b18e-7bbc-4a3e-8d11-7bf8e17c3595', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'On a standard physical map, what colors are conventionally used for Mountains, Plateaus, and Plains respectively?', 'Hypsometric tinting: Brown indicates high mountain relief, Yellow denotes intermediate plateau tablelands, and Green indicates low plains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dc87beb-b1e2-4bcd-9a74-48f09e05c897', 'Mountains: Brown ; Plateaus: Yellow ; Plains: Green', true, '4854b18e-7bbc-4a3e-8d11-7bf8e17c3595');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bf3593d-f5e9-4a0b-895c-2e56b6ccc601', 'Mountains: Green ; Plateaus: Red ; Plains: Blue', false, '4854b18e-7bbc-4a3e-8d11-7bf8e17c3595');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2cf4acd-e3f6-4567-89a2-8d0a51baa598', 'Mountains: Yellow ; Plateaus: Brown ; Plains: White', false, '4854b18e-7bbc-4a3e-8d11-7bf8e17c3595');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bf6864b-fdf0-489b-a9cd-b3cf17253cd9', 'Mountains: White ; Plateaus: Green ; Plains: Black', false, '4854b18e-7bbc-4a3e-8d11-7bf8e17c3595');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae8755a3-8f92-4f5c-8a01-71e4fb94b822', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'Why are conventional symbols, letters, shades, and signs extensively used in maps?', 'Cartographic symbols compress complex multidimensional geographic features into concise, universally decodable visual tokens.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd9291c7-480d-4e3e-9d06-f7eb60437138', 'They allow large amounts of spatial information (roads, bridges, trees, railways, temples) to be depicted clearly in a limited map space', true, 'ae8755a3-8f92-4f5c-8a01-71e4fb94b822');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('922e1da1-6b7a-4ebb-8faf-554e5bde6b49', 'To make maps look like paintings', false, 'ae8755a3-8f92-4f5c-8a01-71e4fb94b822');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('287166d4-2043-407e-809c-941887077614', 'To hide secrets from enemies', false, 'ae8755a3-8f92-4f5c-8a01-71e4fb94b822');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efbe9b28-3108-4ee5-86b7-5fd50e5dca3e', 'Because map makers cannot write words', false, 'ae8755a3-8f92-4f5c-8a01-71e4fb94b822');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1f354c8-7c5e-4452-8d33-32c3ba9596b6', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'If a map uses a scale of ''1 cm = 5 km'', what is the actual ground distance between two railway stations that are 6 cm apart on the map?', 'Ground distance = Map distance × Scale factor = 6 cm × 5 km/cm = 30 kilometers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2526da36-9f82-4fb2-8dd9-5da8aa983502', '30 km (6 cm × 5 km/cm)', true, 'e1f354c8-7c5e-4452-8d33-32c3ba9596b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7f7f99c-d987-4d4d-af0b-86a23ab0eb66', '11 km', false, 'e1f354c8-7c5e-4452-8d33-32c3ba9596b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0ed880a-6a79-47f1-8421-111f98a1d522', '60 km', false, 'e1f354c8-7c5e-4452-8d33-32c3ba9596b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc06ed8d-02df-460d-88ea-405f7c08b6f8', '5 km', false, 'e1f354c8-7c5e-4452-8d33-32c3ba9596b6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ce92c07-472f-4d54-906f-ad215ec457cc', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What is the conventional cartographic symbol for a ''Broad Gauge Railway Line'' with a railway station?', 'Survey of India standards use a hatched black band with an attached ''RS'' box for broad gauge railway stations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df846916-dad3-4169-a6a7-8dc1848fdf6e', 'A black track with alternating cross-hatches and a rectangle marked ''RS''', true, '7ce92c07-472f-4d54-906f-ad215ec457cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4d16289-2447-4ae9-ae99-b480c50043c0', 'A continuous red line', false, '7ce92c07-472f-4d54-906f-ad215ec457cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0767316a-fcf9-44ca-8da4-d7d41d321e4a', 'A blue wavy curve', false, '7ce92c07-472f-4d54-906f-ad215ec457cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b422253-6cde-43e2-abe6-bf7a19f35ce6', 'A green circle', false, '7ce92c07-472f-4d54-906f-ad215ec457cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96efa332-40b1-4099-ae57-b75b5fe6e6c3', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What conventional symbol is used to represent a ''Metalled Road'' versus an ''Unmetalled Road'' on Indian topographical maps?', 'Pucca metalled roads are depicted as continuous double red lines, while kuccha unmetalled tracks are dashed double lines.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81765118-0d7f-4478-ad49-314ba08227b4', 'Metalled Road: Two parallel continuous red lines ; Unmetalled Road: Two parallel broken/dashed red lines', true, '96efa332-40b1-4099-ae57-b75b5fe6e6c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58a8c68e-b9b0-4000-bfe1-4f98dfb0e581', 'Metalled: Solid blue line ; Unmetalled: Green line', false, '96efa332-40b1-4099-ae57-b75b5fe6e6c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97c5e2a7-11b1-462f-9807-960ee1d89626', 'Metalled: Black dots ; Unmetalled: Solid square', false, '96efa332-40b1-4099-ae57-b75b5fe6e6c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f859c65-55f9-4ca7-b48a-f3722c3ab76f', 'Metalled: Star ; Unmetalled: Triangle', false, '96efa332-40b1-4099-ae57-b75b5fe6e6c3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa43dfa3-194c-43c0-80a8-74255de1e440', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What abbreviation is conventionally used on Indian maps for ''Post Office'', ''Post and Telegraph Office'', and ''Police Station''?', 'Standard Survey of India abbreviations: PO = Post Office, PTO = Post & Telegraph Office, PS = Police Station.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ee930e3-c048-43a4-8068-13f9c13b6cd4', 'PO, PTO, and PS respectively', true, 'aa43dfa3-194c-43c0-80a8-74255de1e440');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('116323ea-3c38-4c01-b4a2-88a3da565cdd', 'PO, POST, POL', false, 'aa43dfa3-194c-43c0-80a8-74255de1e440');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0793933-a4d8-409c-a500-7267a069ac15', 'P, PT, PL', false, 'aa43dfa3-194c-43c0-80a8-74255de1e440');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('398535ee-eb4a-4a32-b4c8-522e70074c01', 'OFF, TEL, COP', false, 'aa43dfa3-194c-43c0-80a8-74255de1e440');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c3a8692-e773-47ff-8764-5f674fcc46cc', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What is the main limitation of a flat 2D map when representing the entire spherical Earth?', 'Gauss''s Theorema Egregium: A sphere possesses positive Gaussian curvature and cannot be mapped onto a flat plane without metric distortion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccb025de-b918-4c3e-a185-714436011087', 'A spherical surface (like an orange peel) cannot be flattened onto a flat plane without some geometric distortion of shape, area, or distance', true, '5c3a8692-e773-47ff-8764-5f674fcc46cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efda02c0-ad9c-4162-8ded-8cc527c36185', 'Maps are too heavy to carry', false, '5c3a8692-e773-47ff-8764-5f674fcc46cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8281e0e7-7c1b-4bfd-aa16-86a9f3615cfc', 'Maps cannot show colors', false, '5c3a8692-e773-47ff-8764-5f674fcc46cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a9ccce5-b9ee-41e4-8bfb-7e0112c2d6f0', 'Maps erase the oceans', false, '5c3a8692-e773-47ff-8764-5f674fcc46cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eeb460c2-6211-4249-9e54-acbd5e0996e8', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'Why is a Globe more advantageous than a Map when studying the Earth as a planetary whole?', 'A globe preserves true conformal shapes, area ratios, and geodetic arcs without projection distortions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7878db29-ca66-47dc-8f58-c0c1382149a6', 'A globe is a true, undistorted 3D three-dimensional model showing exact shapes, relative sizes, and spatial orientations of continents and oceans', true, 'eeb460c2-6211-4249-9e54-acbd5e0996e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fff8435e-96b9-48fe-91b4-1878ac90a0d3', 'A globe can fit in a pocket easily', false, 'eeb460c2-6211-4249-9e54-acbd5e0996e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5af0c83-e39e-421c-902e-0d7b43422029', 'A globe shows every small street in a village', false, 'eeb460c2-6211-4249-9e54-acbd5e0996e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a6f171e-9ca0-4553-aa08-e407d417959e', 'A globe can be folded into a book', false, 'eeb460c2-6211-4249-9e54-acbd5e0996e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e1e7319-783c-45ed-99fa-370fc3c6b78f', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'If you are walking facing the rising Sun in the early morning, which directions are directly on your LEFT, RIGHT, and BACK?', 'Facing East (090° azimuth): Left is 90° counterclockwise (North), Right is 90° clockwise (South), and behind is West.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1a9fb55-ba3e-474c-b88d-8b017f1bb84b', 'Left: North ; Right: South ; Back: West', true, '8e1e7319-783c-45ed-99fa-370fc3c6b78f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab807d44-59d7-472a-b699-54ab00e15e41', 'Left: South ; Right: North ; Back: West', false, '8e1e7319-783c-45ed-99fa-370fc3c6b78f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4d86541-e76c-4bbf-87af-986dc388d55e', 'Left: West ; Right: North ; Back: South', false, '8e1e7319-783c-45ed-99fa-370fc3c6b78f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2e6a03b-cb19-4627-aba7-c17df19a0cdf', 'Left: East ; Right: West ; Back: North', false, '8e1e7319-783c-45ed-99fa-370fc3c6b78f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c90984a-2afb-415e-92fe-f6ee0914060e', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'What is the science and art of making and drawing maps called?', 'Cartography (from French carte = map, graphie = writing) is the discipline of map conception, design, and production.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3143c33-8515-45e5-aa1b-66bf66e3f827', 'Cartography', true, '0c90984a-2afb-415e-92fe-f6ee0914060e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57b845c9-58b4-4d31-a6ac-ecb556a7a36c', 'Calligraphy', false, '0c90984a-2afb-415e-92fe-f6ee0914060e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('757bcf32-4a6e-4fb6-836f-99a79853ca38', 'Topography', false, '0c90984a-2afb-415e-92fe-f6ee0914060e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33806294-8807-465f-8ce9-584c304adf76', 'Geology', false, '0c90984a-2afb-415e-92fe-f6ee0914060e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc0a70cd-f7f3-402c-9b9b-6d29fbc6d49b', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'Which type of map would a town planner or revenue officer use to show individual cadastral land ownership plots in a village?', 'Cadastral maps are very large-scale (e.g. 1:1,000 to 1:4,000) legal boundary surveys showing parcel ownership.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aad6208a-c609-436a-8a6b-c77073eba304', 'A Cadastral / Large-Scale Village Plan Map', true, 'cc0a70cd-f7f3-402c-9b9b-6d29fbc6d49b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb74bed5-5b18-4985-b001-3e4875ca599b', 'A World Thematic Map', false, 'cc0a70cd-f7f3-402c-9b9b-6d29fbc6d49b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('541f7224-d792-4ba1-843b-7476741bf3d7', 'A Global Physical Map', false, 'cc0a70cd-f7f3-402c-9b9b-6d29fbc6d49b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7de641f-7035-4862-a142-dc309838fbb5', 'A Small-Scale Atlas Map', false, 'cc0a70cd-f7f3-402c-9b9b-6d29fbc6d49b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6cf4f6c-7a55-4e39-9a10-17983eaab782', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Medium', 'How is an International Boundary conventionally depicted on standard maps?', 'International borders are designated by thick black alternating dash-dot-dash lines.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5918415-703f-427f-ae1a-be59c94efac9', 'A bold line of alternating dark thick dashes and dots', true, 'c6cf4f6c-7a55-4e39-9a10-17983eaab782');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad2289c2-f65a-4a19-9eae-c9dbd8d99746', 'A thin dotted line', false, 'c6cf4f6c-7a55-4e39-9a10-17983eaab782');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('444cbbab-cfbc-4a0f-9f1b-17139ee39ef4', 'A solid green double line', false, 'c6cf4f6c-7a55-4e39-9a10-17983eaab782');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60f0c4bc-c554-4165-8f81-b100e0bd1fc7', 'A wavy blue line', false, 'c6cf4f6c-7a55-4e39-9a10-17983eaab782');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8e58b47-b99e-4cdc-a676-6b723bf2d91d', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0efcb2bb-d013-464e-8a7b-1e8e1463f72e', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'd8e58b47-b99e-4cdc-a676-6b723bf2d91d');
