INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13534aed-ac11-48ca-9b5c-88052b011336', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'Spot the IMPOSTER in the following classification of maps:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db514585-c580-4fea-94f2-0c52e067b234', 'Physical Map', false, '13534aed-ac11-48ca-9b5c-88052b011336');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b1cfa4c-3bc5-43f9-aa6f-e5a002fbaf4c', 'Political Map', false, '13534aed-ac11-48ca-9b5c-88052b011336');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('556e88aa-f52c-49c4-a420-167cfff9657c', 'Thematic Map', false, '13534aed-ac11-48ca-9b5c-88052b011336');
