INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('011b95f8-72ed-4bca-914f-1f79d20e56a3', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'A hiker at a base camp wants to walk towards a scenic waterfall located exactly halfway between North and West. In which direction must the hiker set their compass bearing?', 'Halfway between North (000°/360°) and West (270°) is North-West (315°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd335164-e499-42fe-a4ca-6bcd746ef067', 'North-West (NW / 315° bearing)', true, '011b95f8-72ed-4bca-914f-1f79d20e56a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0615dca2-ca6b-45c9-b542-59d1789d0aa4', 'North-East (NE)', false, '011b95f8-72ed-4bca-914f-1f79d20e56a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bade8671-755a-44c1-b0e1-6ef99511c802', 'South-West (SW)', false, '011b95f8-72ed-4bca-914f-1f79d20e56a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1764cbc4-ae52-4dc9-9211-a82a7e66b0a7', 'South-East (SE)', false, '011b95f8-72ed-4bca-914f-1f79d20e56a3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dbb71c2b-b295-4e4e-a7e1-3ed9436e2653', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'Match Column I (Map Components & Types) with Column II (Descriptions):
(a) Physical Map  -> (i) Shows distribution of rainfall or industries
(b) Political Map -> (ii) Shows relief, rivers, mountains, and plains
(c) Thematic Map  -> (iii) Shows national and state administrative boundaries
(d) Scale         -> (iv) Ratio of map distance to ground distance', 'Physical = relief/rivers; Political = boundaries; Thematic = rainfall/industries; Scale = distance ratio.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd402957-2f6d-4df6-af14-24dc7896242e', 'a-(ii), b-(iii), c-(i), d-(iv)', true, 'dbb71c2b-b295-4e4e-a7e1-3ed9436e2653');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2639561f-6821-4310-8e4a-bc1b0ccb967a', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'dbb71c2b-b295-4e4e-a7e1-3ed9436e2653');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2bee275-a4a3-42f0-96e8-67398f8bd336', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'dbb71c2b-b295-4e4e-a7e1-3ed9436e2653');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36b8a56c-ab32-421e-86a3-1471834b5b07', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'dbb71c2b-b295-4e4e-a7e1-3ed9436e2653');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3be02d85-a79b-4bfc-a0d3-4ba837750de4', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31ee0ae3-3612-470f-82bd-dec260efc582', 'Statements 1 and 2 only', true, '3be02d85-a79b-4bfc-a0d3-4ba837750de4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a72d0b2-b5f6-43f5-a074-9d4d54590879', 'Statements 2 and 3 only', false, '3be02d85-a79b-4bfc-a0d3-4ba837750de4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('584ee0b6-d39d-4201-be60-a4c4f2e00bee', 'Statements 1 and 3 only', false, '3be02d85-a79b-4bfc-a0d3-4ba837750de4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5ec6968-1543-4825-a64f-e17bbd8b9c88', 'All Statements 1, 2, and 3', false, '3be02d85-a79b-4bfc-a0d3-4ba837750de4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b6e70fcf-704e-440e-b5f7-461fb6972ac8', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'On a topographical sheet drawn on a scale of 1:50,000, two towns are separated by 8 cm on the map. What is the actual straight-line distance on the ground in kilometers?', '8 cm × 50,000 = 400,000 cm = 4,000 meters = 4.0 kilometers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('257f04fa-a953-4bb1-ac57-065434da4320', '4 km (8 cm × 50,000 = 400,000 cm = 4,000 m = 4 km)', true, 'b6e70fcf-704e-440e-b5f7-461fb6972ac8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a04046e-6c07-41f8-baef-41b9024814e2', '40 km', false, 'b6e70fcf-704e-440e-b5f7-461fb6972ac8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be963f11-688b-4892-b431-dd765552cbde', '2 km', false, 'b6e70fcf-704e-440e-b5f7-461fb6972ac8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d459c56a-4daf-4ca8-98ee-713fcd3fe394', '8 km', false, 'b6e70fcf-704e-440e-b5f7-461fb6972ac8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f39ecf8e-4a09-4508-9227-55377cd37ed1', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'Why does the magnetic needle of a compass always align itself along the North-South direction anywhere on Earth''s surface?', 'Earth''s liquid outer core dynamo generates a global geomagnetic field that aligns magnetized dipoles with geomagnetic flux lines.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8234b9e0-2b38-4399-ab28-5e1e7ac261b4', 'The Earth itself acts as a gigantic magnet with geomagnetic poles near its geographic poles, exerting magnetic torque on the compass needle', true, 'f39ecf8e-4a09-4508-9227-55377cd37ed1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e2a35aa-8d82-485e-9740-623a39f5b36d', 'Because the Sun attracts it', false, 'f39ecf8e-4a09-4508-9227-55377cd37ed1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dccafdad-fb8b-43e8-98ec-8d32ad514fd2', 'Because wind blows from north to south', false, 'f39ecf8e-4a09-4508-9227-55377cd37ed1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('022f8b75-4789-464a-b40e-1e1ecaf11b3f', 'Because the needle is heavy at one end', false, 'f39ecf8e-4a09-4508-9227-55377cd37ed1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a35d851-5f17-419f-96dc-e01a8f0eef6a', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'Which of the following represents the correct Representative Fraction (R.F.) for a map scale given as ''2 cm = 1 km''?', 'R.F. = Map Distance / Ground Distance = 2 cm / 100,000 cm = 1 : 50,000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1da4199d-ecff-4d3c-bd8e-f55c0042ce1c', '1 : 50,000 (since 1 km = 100,000 cm, so 2 / 100,000 = 1 / 50,000)', true, '7a35d851-5f17-419f-96dc-e01a8f0eef6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8649de32-8c6b-4122-8ef1-e9c0a92a462b', '1 : 100,000', false, '7a35d851-5f17-419f-96dc-e01a8f0eef6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9e4aeec-5a29-4540-b02f-af1cb58e9752', '1 : 25,000', false, '7a35d851-5f17-419f-96dc-e01a8f0eef6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1adaef64-4870-4bba-9aca-84be77befa77', '1 : 2,000', false, '7a35d851-5f17-419f-96dc-e01a8f0eef6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31d7676a-32e9-41cf-9904-62d61d0fa896', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'Consider four map scales:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e15662e5-8b30-42a7-9a95-1984379b2031', 'Scale 1 (1 : 2,500)', true, '31d7676a-32e9-41cf-9904-62d61d0fa896');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('079ef562-9e94-4c08-b98d-a9d0d4db455a', 'Scale 2', false, '31d7676a-32e9-41cf-9904-62d61d0fa896');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cd680d7-04b9-4444-ae8b-5d4c9f64547b', 'Scale 3', false, '31d7676a-32e9-41cf-9904-62d61d0fa896');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9684b7bd-a167-4be5-a25f-46ea3c2d94dd', 'Scale 4', false, '31d7676a-32e9-41cf-9904-62d61d0fa896');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55b4e97f-6e37-4698-a316-e820c026bb52', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'Why is a Map generally more practical and convenient for daily travel navigation than a 3D Globe?', 'Portability, high-resolution thematic zoom, ease of plotting, and selective regional coverage make maps far superior for navigation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3aa6a7d3-7f08-4ebc-a932-a32169a3bcd1', 'Maps are portable, can be folded, can focus on a specific small locality (city/road), and provide high-density localized data on a flat surface', true, '55b4e97f-6e37-4698-a316-e820c026bb52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d01d35f7-9a27-4e2c-b06e-46eb8a31de0d', 'Globes are always inaccurate', false, '55b4e97f-6e37-4698-a316-e820c026bb52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc1566ed-d590-4dae-8f44-68a674265f75', 'Maps are made of gold', false, '55b4e97f-6e37-4698-a316-e820c026bb52');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5784200a-6fe6-4958-95d8-404532df549d', 'Globes cannot show oceans', false, '55b4e97f-6e37-4698-a316-e820c026bb52');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98f3754c-f4b5-46d1-8aba-548bd0650f43', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'What is the conventional color used on topographical maps to show agricultural cultivable farmland?', 'On Survey of India topographic sheets, yellow wash denotes cultivated agricultural land, while green denotes forest/woodland cover.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f6c2b8e-73fc-47cf-ac6e-a0c635556615', 'Yellow color', true, '98f3754c-f4b5-46d1-8aba-548bd0650f43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e65e48b-0ecb-4d86-abc5-7265782c309c', 'Green color', false, '98f3754c-f4b5-46d1-8aba-548bd0650f43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e337f81-dc63-4fff-aa19-840cd663ddc0', 'Brown color', false, '98f3754c-f4b5-46d1-8aba-548bd0650f43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32afa0bb-53d4-44ea-8b14-891f05334a66', 'Red color', false, '98f3754c-f4b5-46d1-8aba-548bd0650f43');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cea54392-14e9-4c5b-a076-eab78bfd6a3f', 'Class 6', 'Social Science', 'Chapter 4: Maps', 'Hard', 'If a village church is located to the South-East (SE) of a school, in which direction is the school located relative to the church?', 'The diametrically opposite direction of South-East (135°) is North-West (315°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07d4426e-508d-486b-8a4f-00faf6ea08e9', 'North-West (NW)', true, 'cea54392-14e9-4c5b-a076-eab78bfd6a3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3350d48c-e7fe-4e31-93d8-f9bda4b8f7d9', 'North-East (NE)', false, 'cea54392-14e9-4c5b-a076-eab78bfd6a3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0716b8b-5e8b-4971-8040-9559c8cf12ef', 'South-West (SW)', false, 'cea54392-14e9-4c5b-a076-eab78bfd6a3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac86cf7a-7681-4ae7-ad4f-3f3fde9e214b', 'South-East (SE)', false, 'cea54392-14e9-4c5b-a076-eab78bfd6a3f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dfe67123-d9b9-4220-b865-96ba54b98bfc', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'किसी व्यक्ति, वस्तु, स्थान, प्राणी या भाव के नाम का बोध कराने वाले शब्द को क्या कहते हैं?', 'संसार के किसी भी नाम (व्यक्ति, वस्तु, स्थान, जाति अथवा भाव) को व्याकरण में ''संज्ञा'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89c96d2f-08df-4c16-98eb-45647a3ac3eb', 'संज्ञा (Noun)', true, 'dfe67123-d9b9-4220-b865-96ba54b98bfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24952d00-e86a-435a-b765-24da35aa62a1', 'सर्वनाम', false, 'dfe67123-d9b9-4220-b865-96ba54b98bfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ea5375e-137f-43a5-8735-56ce7fbf61f5', 'विशेषण', false, 'dfe67123-d9b9-4220-b865-96ba54b98bfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86e0fb4c-9516-4156-926e-973fd7fab201', 'क्रिया', false, 'dfe67123-d9b9-4220-b865-96ba54b98bfc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be4c05c6-21e2-4a74-8387-53ee07f59bf8', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'हिंदी व्याकरण में मुख्य रूप से संज्ञा के कितने भेद (प्रकार) माने जाते हैं?', 'संज्ञा के 3 मुख्य भेद हैं: व्यक्तिवाचक, जातिवाचक, तथा भाववाचक (जातिवाचक के अंतर्गत द्रव्यवाचक व समूहवाचक आते हैं)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ed41b3c-faa5-409f-8409-74e12670e0e4', 'तीन मुख्य भेद (व्यक्तिवाचक, जातिवाचक, भाववाचक)', true, 'be4c05c6-21e2-4a74-8387-53ee07f59bf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70a5f88a-342e-4f40-9963-6b49d352da04', 'दो भेद', false, 'be4c05c6-21e2-4a74-8387-53ee07f59bf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11c9dce9-dc7c-430c-9e8d-77b777792a5d', 'चार भेद', false, 'be4c05c6-21e2-4a74-8387-53ee07f59bf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e3b4ee2-1a45-427a-8470-028d35bb4c49', 'छह भेद', false, 'be4c05c6-21e2-4a74-8387-53ee07f59bf8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('389107fa-c457-49b4-a273-d800ecb79c9b', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'जिस संज्ञा शब्द से किसी एक विशेष व्यक्ति, विशेष स्थान या विशेष वस्तु का बोध हो, उसे क्या कहते हैं?', 'विशिष्ट इकाई/नाम का बोध कराने वाले शब्द व्यक्तिवाचक संज्ञा कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e71b1ace-8cf0-4ade-b50c-d1282ff368aa', 'व्यक्तिवाचक संज्ञा (Proper Noun - जैसे: राम, दिल्ली, हिमालय, गंगा, ताजमहल)', true, '389107fa-c457-49b4-a273-d800ecb79c9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1984e99-52c8-4625-bbc8-24c753304cde', 'जातिवाचक संज्ञा', false, '389107fa-c457-49b4-a273-d800ecb79c9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c188304-f406-45ff-ae80-eb08147f7a14', 'भाववाचक संज्ञा', false, '389107fa-c457-49b4-a273-d800ecb79c9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5281b78-8d8a-481a-8f01-db4ae7a10f96', 'द्रव्यवाचक संज्ञा', false, '389107fa-c457-49b4-a273-d800ecb79c9b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b51d8ff8-4f20-45c7-9748-c13cd7c317e4', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'जिस संज्ञा शब्द से किसी संपूर्ण जाति, वर्ग या श्रेणी के सभी प्राणियों, वस्तुओं या स्थानों का बोध हो, उसे क्या कहते हैं?', 'संपूर्ण प्रजाति/वर्ग का सामान्य बोध कराने वाले शब्द जातिवाचक संज्ञा कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0785c52d-fe36-4f3e-bc8a-732dcd86d3b0', 'जातिवाचक संज्ञा (Common Noun - जैसे: लड़का, नदी, पर्वत, नगर, पुस्तक)', true, 'b51d8ff8-4f20-45c7-9748-c13cd7c317e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('727957fa-2468-4b47-956d-4a479a78484b', 'व्यक्तिवाचक संज्ञा', false, 'b51d8ff8-4f20-45c7-9748-c13cd7c317e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('694a214f-e099-4e56-88ca-f55bf520ca58', 'भाववाचक संज्ञा', false, 'b51d8ff8-4f20-45c7-9748-c13cd7c317e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b48f328-080f-4ba5-9a54-af74e4a2f53e', 'समूहवाचक संज्ञा', false, 'b51d8ff8-4f20-45c7-9748-c13cd7c317e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47081f75-15f5-427e-8bac-85d9a63164cb', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'जिन शब्दों से किसी व्यक्ति या वस्तु के गुण, दोष, दशा, अवस्था, मन के भाव या स्वभाव का बोध हो, उन्हें क्या कहते हैं?', 'अमूर्त भाव, गुण, दशा या अवस्था का बोध कराने वाले शब्द भाववाचक संज्ञा कहलाते हैं (इन्हें छुआ नहीं, केवल अनुभव किया जाता है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b8fd275-2277-43a5-9087-c32f7290c7b2', 'भाववाचक संज्ञा (Abstract Noun - जैसे: मिठास, बचपन, ईमानदारी, बुढ़ापा, क्रोध)', true, '47081f75-15f5-427e-8bac-85d9a63164cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07cf4dfd-1b6a-45d9-8353-288c31c49270', 'जातिवाचक संज्ञा', false, '47081f75-15f5-427e-8bac-85d9a63164cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c91e5f26-4ad5-4c35-9297-727e8ced0a53', 'व्यक्तिवाचक संज्ञा', false, '47081f75-15f5-427e-8bac-85d9a63164cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5a8a90c-bc29-4695-90d7-2bd6a4520157', 'द्रव्यवाचक संज्ञा', false, '47081f75-15f5-427e-8bac-85d9a63164cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe81e33a-e183-4a10-b41c-1e6c1d5f51df', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'वे संज्ञा शब्द जिनसे किसी धातु, तरल, ठोस या द्रव्य (पदार्थ) का बोध होता है जिसे नापा या तौला जा सके, उन्हें क्या कहते हैं?', 'मात्रात्मक एवं परिमाप्य पदार्थों का बोध कराने वाले शब्द द्रव्यवाचक संज्ञा कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65aab64c-8b34-478a-a797-07145447d780', 'द्रव्यवाचक संज्ञा (Material Noun - जैसे: सोना, चाँदी, दूध, पानी, गेहूँ, तेल)', true, 'fe81e33a-e183-4a10-b41c-1e6c1d5f51df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d44db6e-6006-4744-8693-d109d6c54fb2', 'समूहवाचक संज्ञा', false, 'fe81e33a-e183-4a10-b41c-1e6c1d5f51df');
