INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('528a68ea-771b-4e13-b870-b93a69473f11', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Easy', 'वे संज्ञा शब्द जिनसे किसी समूह, दल, सभा, भीड़ या समुदाय का बोध होता है, उन्हें क्या कहते हैं?', 'अनेक प्राणियों या वस्तुओं के समूह का संयुक्त बोध कराने वाले शब्द समूहवाचक संज्ञा कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
