INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ddc80739-f3b9-4986-9374-8cbedfe87048', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'सर्वनाम शब्द ''अपना'', ''मम'' और ''निज'' से बनने वाली भाववाचक संज्ञाएँ क्रमशः कौन-सी हैं?', 'सर्वनामों में ''पन'', ''ता'', ''त्व'' प्रत्यय लगाने से भाववाचक संज्ञा बनती है: अपनापन, ममता/ममत्व, निजत्व।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a867ff6d-289d-42b7-9dce-2aae005ee498', 'अपनापन (या अपनत्व), ममता (या ममत्व), निजत्व', true, 'ddc80739-f3b9-4986-9374-8cbedfe87048');
