INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('44783e73-5d76-4a86-880b-746403fb4fff', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'क्रिया शब्द ''पढ़ना'', ''हँसना'' और ''सजाना'' से बनने वाली भाववाचक संज्ञाएँ क्रमशः कौन-सी हैं?', 'क्रिया के धातु रूप में प्रत्यय लगने से भाववाचक संज्ञाएँ बनती हैं: पढ़ना -> पढ़ाई; हँसना -> हँसी; सजाना -> सजावट।', NOW()) ON CONFLICT DO NOTHING;
