INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83ae15df-3233-4136-bf64-0bf1430fb0fb', 'सुहावना, साहसी, फल', false, 'c17d698f-571c-403f-8e88-6bd409e09f9b');
