INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd69d99f-f1ed-4939-ba99-ca3a05d3995c', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'अव्यय शब्द ''दूर'', ''समीप'' और ''मना'' से बनने वाली भाववाचक संज्ञाएँ कौन-सी हैं?', 'अव्यय से निर्मित भाववाचक संज्ञाएँ: दूर -> दूरी; समीप -> समीपता/सामीप्य; मना -> मनाही।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('302ed998-d779-4065-8ea5-c69fc3d91f77', 'दूरी, समीपता (सामीप्य), मनाही', true, 'cd69d99f-f1ed-4939-ba99-ca3a05d3995c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7347bc4f-565d-4e22-bff6-38410b2741d6', 'दूरबीन, समीपवर्ती, मनाना', false, 'cd69d99f-f1ed-4939-ba99-ca3a05d3995c');
