INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04995685-41d7-40ff-8f41-bd3140d1e166', 'दूरस्थ, निकटता, इनकार', false, 'cd69d99f-f1ed-4939-ba99-ca3a05d3995c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ea6c2b5-096b-4c7d-aad1-09b4082ea224', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'जब कोई व्यक्तिवाचक संज्ञा किसी व्यक्ति विशेष के नाम के रूप में न आकर उसके विशेष गुणों के कारण पूरी जाति का बोध कराती है (जैसे: ''हमारे देश में जयचंदों की कमी नहीं है''), तो वह क्या बन जाती है?', 'व्यक्तिवाचक संज्ञा जब बहुवचन में प्रयुक्त होकर किसी लाक्षणिक वर्ग (गद्दारों/दानवीरों) को दर्शाए, तो वह जातिवाचक बन जाती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9df8db58-577b-434e-bbff-c6bdf7c3a3c8', 'जातिवाचक संज्ञा (विश्वासघातियों की संपूर्ण श्रेणी)', true, '9ea6c2b5-096b-4c7d-aad1-09b4082ea224');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8c1c5ba-6fb4-4294-b4cb-18b9cc3377b3', 'भाववाचक संज्ञा', false, '9ea6c2b5-096b-4c7d-aad1-09b4082ea224');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d849b43-d0ef-45f8-96a9-bfc0215b562d', 'द्रव्यवाचक संज्ञा', false, '9ea6c2b5-096b-4c7d-aad1-09b4082ea224');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('464334c1-04cf-4b31-8015-37b2d9368547', 'समूहवाचक संज्ञा', false, '9ea6c2b5-096b-4c7d-aad1-09b4082ea224');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('144e725f-8163-4b03-a719-7825d8a71667', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'जब कोई जातिवाचक संज्ञा किसी विशेष रूढ़ व्यक्ति के लिए निश्चित हो जाती है (जैसे: ''पंडित जी भारत के प्रथम प्रधानमंत्री थे'' या ''नेता जी ने आज़ाद हिंद फ़ौज बनाई''), तो वह क्या बन जाती है?', 'जातिवाचक पद जब किसी सुप्रसिद्ध व्यक्ति विशेष के लिए रूढ़ होकर प्रयुक्त हो, तो वह व्यक्तिवाचक संज्ञा बन जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d60ee920-7717-40a0-9680-54a4073bece5', 'व्यक्तिवाचक संज्ञा (पंडित जी = जवाहरलाल नेहरू ; नेता जी = सुभाष चंद्र बोस)', true, '144e725f-8163-4b03-a719-7825d8a71667');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('991446d1-92ab-44d8-9e18-28dd91408adc', 'भाववाचक संज्ञा', false, '144e725f-8163-4b03-a719-7825d8a71667');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79c6e351-fa80-47e7-8e4e-d69bb4f170ce', 'समूहवाचक संज्ञा', false, '144e725f-8163-4b03-a719-7825d8a71667');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d67c078-f990-425f-89d9-abf2a6164641', 'द्रव्यवाचक संज्ञा', false, '144e725f-8163-4b03-a719-7825d8a71667');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ec6b539-6e7e-4db5-bcc4-117bcc6eb71b', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'भाववाचक संज्ञाओं का प्रयोग सामान्यतः किस वचन में होता है?', 'अमूर्त भाववाचक संज्ञाएँ सदा एकवचन में रहती हैं; बहुवचन बनते ही वे जातिवाचक संज्ञा में परिवर्तित हो जाती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bcfce11-deef-4fce-9b7e-9040debe3b64', 'सदैव एकवचन में (जब भाववाचक संज्ञा बहुवचन में प्रयुक्त होती है, जैसे ''दूरियाँ, बुराइयाँ'', तो वह जातिवाचक बन जाती है)', true, '9ec6b539-6e7e-4db5-bcc4-117bcc6eb71b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d36bb0a9-2688-4afb-9f22-52e605ee5444', 'सदैव बहुवचन में', false, '9ec6b539-6e7e-4db5-bcc4-117bcc6eb71b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb19ece4-5885-461a-8466-9ad23e121953', 'द्विवचन में', false, '9ec6b539-6e7e-4db5-bcc4-117bcc6eb71b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fbba500-a8c1-4dfd-a3ec-61ff6c03bb76', 'किसी भी वचन में नहीं', false, '9ec6b539-6e7e-4db5-bcc4-117bcc6eb71b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc354d72-876a-480b-9cff-b868d9ad5be2', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'निम्नलिखित में से कौन-सा शब्द ''समूहवाचक संज्ञा'' का सही समूह है?', 'संसद, मेला, जुलूस, दल, झुंड सभी व्यक्तियों या जीवों के एकत्र समुदाय का बोध कराते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('609d1442-f05f-45ee-a9f5-255c33af3336', 'संसद, मेला, जुलूस, दल, झुंड', true, 'cc354d72-876a-480b-9cff-b868d9ad5be2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c1284a3-8c06-4f74-86ad-d13ad1936c69', 'पानी, तेल, घी, शक्कर', false, 'cc354d72-876a-480b-9cff-b868d9ad5be2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb28cbba-a4db-46bf-b596-33c312cbfae2', 'गंगा, हिमालय, दिल्ली', false, 'cc354d72-876a-480b-9cff-b868d9ad5be2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52690010-e58d-43d9-948f-9394259e5bde', 'बचपन, बुढ़ापा, जवानी', false, 'cc354d72-876a-480b-9cff-b868d9ad5be2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a08a4a2d-e01a-4a30-9e09-df683e667d37', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'निम्नलिखित में से कौन-सा शब्द ''द्रव्यवाचक संज्ञा'' का सही समूह है?', 'ताँबा, पीतल, पेट्रोल, कोयला, घी सभी द्रव्यमान और रासायनिक धातु/तरल पदार्थ हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9242c9a-970b-4096-91c3-f9940156ac00', 'ताँबा, पीतल, पेट्रोल, कोयला, घी', true, 'a08a4a2d-e01a-4a30-9e09-df683e667d37');
