INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5597fd45-9a82-4f57-a9a6-95ab0c5f3d35', 'ईमानदारी, चालाकी, क्रोध', false, 'a08a4a2d-e01a-4a30-9e09-df683e667d37');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5ae22dad-44a5-4ab1-9bc4-7fe6dbfea375', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'जातिवाचक संज्ञा ''पंडित'' से बनने वाली सही भाववाचक संज्ञा कौन-सी है?', '''पंडित'' से ''पांडित्य'' (संस्कृत प्रत्यय य) तथा ''पंडिताई'' (आई प्रत्यय) दोनों मानक भाववाचक संज्ञाएँ बनती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c54b3ea2-9a8e-4f14-94ca-aefa5d32ee26', 'पांडित्य', false, '5ae22dad-44a5-4ab1-9bc4-7fe6dbfea375');
