INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d0bf9ad-6a6e-409b-b3b9-c9fce970a817', 'सत्य, अहिंसा, आज़ादी', true, '1e68d32a-0586-42f4-afab-a37756d6883b');
