INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53558098-aa55-4bce-9ebf-3c21ee7faa8b', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Medium', 'विशेषण शब्द ''गर्म'' और ''ठंडा'' से बनने वाली भाववाचक संज्ञाएँ क्रमशः कौन-सी हैं?', 'गर्म से ''गर्मी'' / ''गर्माहट'' तथा ठंडा से ''ठंडक'' / ''ठंड'' मानक भाववाचक संज्ञाएँ बनती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51e56357-7a5f-4ff6-8186-254efdf273ad', 'गर्मी और ठंडक (या ठंड)', false, '53558098-aa55-4bce-9ebf-3c21ee7faa8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1362a82-c479-487e-a199-d4b035a9cd9d', 'गरमपानी और बर्फ', false, '53558098-aa55-4bce-9ebf-3c21ee7faa8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98695902-0c5c-46ea-812d-d12040687d3b', 'गर्माहट और शीत', false, '53558098-aa55-4bce-9ebf-3c21ee7faa8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2f25dde-bd4f-46ad-b80c-4d5b7512c279', 'दोनों ''गर्मी और ठंडक'' सही हैं', true, '53558098-aa55-4bce-9ebf-3c21ee7faa8b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56c48dc0-5d02-48bb-a9c2-8cfba0964575', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57eff4a1-0237-45a8-af62-fe55202e1c7a', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '56c48dc0-5d02-48bb-a9c2-8cfba0964575');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2c2c9df-fee1-4fd6-a026-dd0151007315', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '56c48dc0-5d02-48bb-a9c2-8cfba0964575');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28ea53b4-150c-4b58-9657-a7b42c602409', '(A) सही है, परन्तु (R) गलत है।', false, '56c48dc0-5d02-48bb-a9c2-8cfba0964575');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72bb26f9-8200-40e3-9987-502e53c3f8a7', '(A) गलत है, परन्तु (R) सही है।', false, '56c48dc0-5d02-48bb-a9c2-8cfba0964575');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1516a54-28bb-4c03-a1d3-8e90601f6aa6', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'Spot the IMPOSTER in the following group of भाववाचक संज्ञा शब्दों के आधार पर:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44bb7e50-a2f0-4374-828c-ad5bda8f3121', 'मिठास', false, 'e1516a54-28bb-4c03-a1d3-8e90601f6aa6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3388e3ef-622d-4db9-81c7-7880d5c0c03c', 'सुंदरता', false, 'e1516a54-28bb-4c03-a1d3-8e90601f6aa6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5072da8a-b48e-4395-aace-7210b99e905d', 'बचपन', false, 'e1516a54-28bb-4c03-a1d3-8e90601f6aa6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9014818f-fc9a-4cb7-b003-de5133c38786', 'हिमालय', true, 'e1516a54-28bb-4c03-a1d3-8e90601f6aa6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0fb6480a-b72f-4f94-b375-4a5d98feaa86', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'सुमेलित कीजिए (शब्द और उनकी भाववाचक संज्ञा):
(क) बूढ़ा    -> (i) लड़कपन
(ख) लड़का   -> (ii) मोटापा
(ग) मोटा    -> (iii) बुढ़ापा
(घ) चढ़ना   -> (iv) चढ़ाई', 'बूढ़ा = बुढ़ापा; लड़का = लड़कपन; मोटा = मोटापा; चढ़ना = चढ़ाई।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6647ebc-092c-4866-961e-51dfcc314c32', 'क-(iii), ख-(i), ग-(ii), घ-(iv)', true, '0fb6480a-b72f-4f94-b375-4a5d98feaa86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a66f0e86-ab2c-4d61-a1f0-ff6730b1510f', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, '0fb6480a-b72f-4f94-b375-4a5d98feaa86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f92dc2e3-c8a3-4ba9-bb8e-a5e8eb01fdc9', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '0fb6480a-b72f-4f94-b375-4a5d98feaa86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b64f69c5-4de9-488c-bf00-c940370624b5', 'क-(ii), ख-(iv), ग-(i), घ-(iii)', false, '0fb6480a-b72f-4f94-b375-4a5d98feaa86');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45192617-ec4e-4bdb-8a87-760631393b34', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'भाववाचक संज्ञाओं की रचना मुख्यतः कितने प्रकार के शब्दों से की जाती है?', 'व्याकरणिक नियमानुसार भाववाचक संज्ञा पाँच स्रोतों से व्युत्पन्न होती है: जातिवाचक संज्ञा, सर्वनाम, विशेषण, क्रिया, तथा अव्यय।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0418d2a1-c3a6-4319-a2ba-6fb117fc8838', 'पाँच प्रकार के शब्दों से: 1. जातिवाचक संज्ञा से, 2. सर्वनाम से, 3. विशेषण से, 4. क्रिया से, 5. अव्यय से', true, '45192617-ec4e-4bdb-8a87-760631393b34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70307876-05a8-4ebe-a109-14926c5a5118', 'केवल दो प्रकार से', false, '45192617-ec4e-4bdb-8a87-760631393b34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('722c6625-3d7f-4582-a0a4-68cd1418b3ea', 'केवल तीन प्रकार से', false, '45192617-ec4e-4bdb-8a87-760631393b34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4eda73b8-42c3-41e8-ad37-163cc7455f83', 'चार प्रकार से', false, '45192617-ec4e-4bdb-8a87-760631393b34');
