INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09709a7b-572e-469f-bee7-99eada23cc63', 'सभी वाक्य 1, 2 और 3 सत्य हैं', true, 'eb0aa779-e8d6-43f0-a37d-45f97fc6e908');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1a121c7-42d9-499f-996b-4986cdce490c', 'वाक्य 1 और 2 केवल', false, 'eb0aa779-e8d6-43f0-a37d-45f97fc6e908');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('542e7a37-9993-44cc-ad42-b36e4c10c66d', 'वाक्य 2 और 3 केवल', false, 'eb0aa779-e8d6-43f0-a37d-45f97fc6e908');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4b572c0-c49d-40e8-b6f7-a0cafc38c1fb', 'वाक्य 1 और 3 केवल', false, 'eb0aa779-e8d6-43f0-a37d-45f97fc6e908');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb4eb329-631a-41ae-9e61-976cb262cc78', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'वाक्य में प्रयुक्त पद ''शाबाशी'' और ''वाहवाही'' व्याकरण की दृष्टि से किस कोटि की संज्ञाएँ हैं?', 'विस्मयादिबोधक अव्यय ''शाबाश'' और ''वाह-वाह'' में ''ई'' प्रत्यय जुड़ने से अमूर्त भाववाचक संज्ञाएँ निर्मित होती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d1ac555-8e23-4549-9468-0370e20475d0', 'विस्मयादिबोधक अव्यय से बनी भाववाचक संज्ञाएँ (शाबाश -> शाबाशी ; वाह-वाह -> वाहवाही)', true, 'bb4eb329-631a-41ae-9e61-976cb262cc78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('327433cf-85b9-457b-9879-dee800dd1f89', 'द्रव्यवाचक संज्ञाएँ', false, 'bb4eb329-631a-41ae-9e61-976cb262cc78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aca7956d-90fc-45c9-bd05-3d1fd6956d99', 'व्यक्तिवाचक संज्ञाएँ', false, 'bb4eb329-631a-41ae-9e61-976cb262cc78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fda38ca7-7c80-4d32-a57e-eb50610b5ef3', 'समूहवाचक संज्ञाएँ', false, 'bb4eb329-631a-41ae-9e61-976cb262cc78');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fcae3ce8-7140-4b82-9864-d7a106ff8f41', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'जातिवाचक संज्ञा ''चोर'', ''ठग'' और ''शिशु'' से बनने वाली भाववाचक संज्ञाएँ क्रमशः कौन-सी हैं?', 'चोर -> चोरी; ठग -> ठगी; शिशु -> शैशव/शिशुता मानक व्याकरणिक भाववाचक संज्ञाएँ हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('103a5ce0-d720-47c1-8808-20274245689b', 'चोरी, ठगी, शैशव (या शिशुता)', true, 'fcae3ce8-7140-4b82-9864-d7a106ff8f41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e13a55e-f3cf-4223-ad89-85f1c1830dbd', 'चोरपन, ठगपन, शिशुपन', false, 'fcae3ce8-7140-4b82-9864-d7a106ff8f41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('747f595e-2eda-425b-8549-f5d8be14ac82', 'चोरना, ठगना, छोटा', false, 'fcae3ce8-7140-4b82-9864-d7a106ff8f41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f586d57-8eeb-41e2-b983-00acf6014694', 'डकैती, बेईमानी, बालक', false, 'fcae3ce8-7140-4b82-9864-d7a106ff8f41');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('859bc38c-c6a0-4d78-b4ec-4a816ad25ac1', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'सर्वनाम ''सर्व'' और ''अहं'' से बनने वाली भाववाचक संज्ञाएँ क्रमशः कौन-सी हैं?', '''सर्व'' में ''स्व'' प्रत्यय से ''सर्वस्व'' तथा ''अहं'' (मैं) में ''कार'' प्रत्यय से ''अहंकार'' भाववाचक संज्ञा बनती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97ba3beb-7710-4684-abc4-722b643924ec', 'सर्वस्व और अहंकार', true, '859bc38c-c6a0-4d78-b4ec-4a816ad25ac1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89e291df-5b22-4476-8785-41c8a5ec5f4e', 'सबकुछ और घमंड', false, '859bc38c-c6a0-4d78-b4ec-4a816ad25ac1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b79f19d3-c1f7-42b9-b72b-a006b378d4f0', 'सभी और मैं', false, '859bc38c-c6a0-4d78-b4ec-4a816ad25ac1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9755109-676f-472c-8aa0-5ffc559b5cfe', 'सर्वत्र और अभिमान', false, '859bc38c-c6a0-4d78-b4ec-4a816ad25ac1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78ada743-3371-4855-bd74-ff88b1134c2f', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'विशेषण ''चतुर'', ''आलसी'' और ''कायर'' से बनने वाली भाववाचक संज्ञाएँ क्रमशः कौन-सी हैं?', 'चतुर -> चतुराई/चतुरता; आलसी -> आलस्य; कायर -> कायरता।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe8446c3-911c-4f88-afb9-469713a5c064', 'चतुराई, आलस्य (या आलस), कायरता', true, '78ada743-3371-4855-bd74-ff88b1134c2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b34293b8-d81d-4ff5-aeb0-979f0e2cbf42', 'चालाक, सुस्त, डरपोक', false, '78ada743-3371-4855-bd74-ff88b1134c2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b82e0ddc-8cf4-423e-aa2b-6758c0e3f7ba', 'चतुरपन, आलसीपन, कायरपन', false, '78ada743-3371-4855-bd74-ff88b1134c2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6f184c0-c716-4d3c-845f-af584f960b2c', 'चतुरता, नींद, भागना', false, '78ada743-3371-4855-bd74-ff88b1134c2f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f8912c1-c0dc-4e37-bf2b-bda05ddafaed', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'क्रिया ''घबराना'', ''थकना'' और ''बहाव'' (बहना) से बनने वाली भाववाचक संज्ञाएँ क्रमशः कौन-सी हैं?', 'घबराना + आहट = घबराहट; थकना + आवट = थकावट/थकान; बहना + आव = बहाव।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b5445a4-cb77-4fc3-bb71-d6d1077c3b30', 'घबराहट, थकावट (थकान), बहाव', true, '5f8912c1-c0dc-4e37-bf2b-bda05ddafaed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('893d6a9a-9e8c-4a48-ba89-dc6bbc71a549', 'घबराया, थका, बहता', false, '5f8912c1-c0dc-4e37-bf2b-bda05ddafaed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d27274a-78e4-4cbf-9259-54b328575485', 'घबराहटपन, थकनी, बाढ़', false, '5f8912c1-c0dc-4e37-bf2b-bda05ddafaed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('430449ce-121e-43c4-9825-7bbdebada699', 'डर, सुस्ती, पानी', false, '5f8912c1-c0dc-4e37-bf2b-bda05ddafaed');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be15d6cb-4c3d-44d4-a8c6-fb2da04f2b77', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'अंग्रेज़ी व्याकरण के प्रभाव से आधुनिक हिंदी में स्वीकृत ''द्रव्यवाचक'' और ''समूहवाचक'' संज्ञाओं को पारंपरिक रूप से किस मुख्य भेद का उपभेद माना जाता है?', 'पारंपरिक हिंदी व्याकरण में द्रव्यवाचक (Material) और समूहवाचक (Collective) दोनों को जातिवाचक संज्ञा का ही विस्तार माना जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5945a02a-ddf4-46a2-a47c-f61ca94abc75', 'जातिवाचक संज्ञा के अंतर्गत', true, 'be15d6cb-4c3d-44d4-a8c6-fb2da04f2b77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f3c9435-8e32-408a-8545-42158e9eb503', 'व्यक्तिवाचक संज्ञा के अंतर्गत', false, 'be15d6cb-4c3d-44d4-a8c6-fb2da04f2b77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('561194d5-1971-4c0e-9be9-bda2386ed41c', 'भाववाचक संज्ञा के अंतर्गत', false, 'be15d6cb-4c3d-44d4-a8c6-fb2da04f2b77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8638bba-e3f2-4d6e-a3bb-6bc17cc21e33', 'सर्वनाम के अंतर्गत', false, 'be15d6cb-4c3d-44d4-a8c6-fb2da04f2b77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3458133c-eab1-4c11-805e-b3da51051914', 'Class 6', 'Hindi Grammar', 'Chapter 4: संज्ञा', 'Hard', 'वाक्य में रेखांकित पदों के संज्ञा भेदों का सही क्रम चुनिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0013a857-6fd1-420b-abbd-2170676eb599', 'सरदार पटेल = व्यक्तिवाचक ; दृढ़ता = भाववाचक ; राष्ट्र = जातिवाचक', true, '3458133c-eab1-4c11-805e-b3da51051914');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9229e739-dee6-44e0-8b10-583e263d59c6', 'सरदार पटेल = जातिवाचक ; दृढ़ता = व्यक्तिवाचक ; राष्ट्र = भाववाचक', false, '3458133c-eab1-4c11-805e-b3da51051914');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddea1001-3c4f-4126-8dd5-1fe21f39c11d', 'सरदार पटेल = व्यक्तिवाचक ; दृढ़ता = जातिवाचक ; राष्ट्र = समूहवाचक', false, '3458133c-eab1-4c11-805e-b3da51051914');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3b28f20-46af-405b-a4d8-8a920e9cd688', 'तीनों भाववाचक संज्ञाएँ हैं', false, '3458133c-eab1-4c11-805e-b3da51051914');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3dd5061d-4bb5-4053-a8ca-a79d48b7093c', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'The hard, internal bony framework that supports, gives shape, and protects the internal organs of the human body is called the:', 'The human skeleton consists of 206 bones in adults, providing mechanical structure, protection, and levers for movement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00139b7b-630f-4d80-aa20-012e44a88a95', 'Skeleton (Human Skeletal System)', true, '3dd5061d-4bb5-4053-a8ca-a79d48b7093c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b262fb0c-9227-425a-9b7a-801c150a0f98', 'Muscular system', false, '3dd5061d-4bb5-4053-a8ca-a79d48b7093c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80a404f2-89c7-45b7-924f-f917800908bc', 'Digestive system', false, '3dd5061d-4bb5-4053-a8ca-a79d48b7093c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35be9e77-d5f9-4b31-a70c-26348b22e309', 'Circulatory system', false, '3dd5061d-4bb5-4053-a8ca-a79d48b7093c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56548962-2b12-4104-a403-c993b01d7178', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'The anatomical place or point where two or more bones meet and join together is called a:', 'Joints are structural articulations between bones allowing varying degrees of flexibility and bodily movement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8735f206-8075-4cad-b522-48ee6fad5b47', 'Joint (Articulation)', true, '56548962-2b12-4104-a403-c993b01d7178');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5ae6b47-1539-4f09-af67-72c165aee696', 'Muscle', false, '56548962-2b12-4104-a403-c993b01d7178');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a6c7a4c-f723-4d84-86af-15287e366338', 'Tendon', false, '56548962-2b12-4104-a403-c993b01d7178');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08a62142-1241-4716-b70b-9b3917b4c949', 'Cartilage', false, '56548962-2b12-4104-a403-c993b01d7178');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c30f83fa-ce0d-4d51-8dc5-2a0530ce6cf2', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'Which type of movable joint allows complete rotational movement in ALL directions (360°), found at the shoulder and hip?', 'The spherical head of one bone fits into the cup-like cavity of another, enabling multi-axial 360° rotatory movement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4b12577-33f3-4367-8b9c-2ea220cc8026', 'Ball and Socket Joint', true, 'c30f83fa-ce0d-4d51-8dc5-2a0530ce6cf2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fcd4090-2abb-4300-867a-37b12c69482e', 'Hinge Joint', false, 'c30f83fa-ce0d-4d51-8dc5-2a0530ce6cf2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5abd114e-1ff6-4a09-905f-4e6c867ba4ea', 'Pivot Joint', false, 'c30f83fa-ce0d-4d51-8dc5-2a0530ce6cf2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ed3399d-e850-4bcd-a24f-2f5026c71fe7', 'Fixed Joint', false, 'c30f83fa-ce0d-4d51-8dc5-2a0530ce6cf2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8ec78db-e96e-40ff-90a6-8259d2b70190', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'Which type of joint allows movement in only ONE single plane (back and forth like a door hinge), found at the elbow and knee?', 'Hinge joints permit angular flexion and extension along a single transverse axis, resembling a door hinge.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a1f2dc3-e205-477f-96d8-c21d1e91859e', 'Hinge Joint', true, 'e8ec78db-e96e-40ff-90a6-8259d2b70190');
