INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47a2c695-4574-4706-bd6d-e86b5b53096c', 'Pivot Joint', false, 'e8ec78db-e96e-40ff-90a6-8259d2b70190');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b05af33c-a94d-4378-9dac-0218050d9320', 'Fixed Joint', false, 'e8ec78db-e96e-40ff-90a6-8259d2b70190');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2db597c9-1609-4387-a676-3d6e3146276d', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'The joint where our neck joins the head, allowing us to bend our head forward/backward and turn it to the right/left, is a:', 'The atlanto-axial pivotal joint allows a cylindrical bone to rotate within a ring formed by bone and ligament.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a73ec10-8402-45a6-9b5a-0ef88e779b0d', 'Pivotal Joint (Pivot Joint)', true, '2db597c9-1609-4387-a676-3d6e3146276d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26197518-9ae8-4c2c-96d2-5493379a0dbb', 'Hinge Joint', false, '2db597c9-1609-4387-a676-3d6e3146276d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e597a1b1-381e-4ce5-a94a-20cbfbe12f46', 'Ball and Socket Joint', false, '2db597c9-1609-4387-a676-3d6e3146276d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc40c4cb-bfca-4c92-91c8-69569b520258', 'Fixed Joint', false, '2db597c9-1609-4387-a676-3d6e3146276d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('958e2c2c-82f3-47dd-a283-d222de2d1e48', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'The bones in our head (cranium/skull) that are fused together tightly and CANNOT move at all are examples of:', 'Cranial skull bones are united by fibrous immovable suture joints to shield the delicate brain from injury.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dd17b43-49e8-4e33-8a68-13b70421fbd8', 'Fixed Joints (Immovable Joints / Sutures)', true, '958e2c2c-82f3-47dd-a283-d222de2d1e48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('354b83f1-9c34-4a94-92ea-d1f28d1c4afc', 'Hinge Joints', false, '958e2c2c-82f3-47dd-a283-d222de2d1e48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08e97ce5-f10d-4530-b325-efd64dd98f1d', 'Pivotal Joints', false, '958e2c2c-82f3-47dd-a283-d222de2d1e48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48be7e50-b305-4a8d-96a2-94d1edf2588a', 'Gliding Joints', false, '958e2c2c-82f3-47dd-a283-d222de2d1e48');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d95b6fe-94ab-484d-8747-87e7ef25357f', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'Which is the ONLY movable bone in the human skull, enabling us to chew food and speak?', 'The mandible articulates via the temporomandibular joint, making it the skull''s only dynamic movable bone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('471ddbef-c2f4-4f2b-9fb8-eedd50fc48f8', 'Lower Jaw bone (Mandible)', true, '6d95b6fe-94ab-484d-8747-87e7ef25357f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fc1c6ab-f2c2-4814-b1ee-8c0a3efaad5e', 'Upper Jaw bone (Maxilla)', false, '6d95b6fe-94ab-484d-8747-87e7ef25357f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6abedbd-c221-4467-85c0-c91c399b8014', 'Nasal bone', false, '6d95b6fe-94ab-484d-8747-87e7ef25357f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2b6ad02-f88d-4eb8-b805-6d5a41f7948d', 'Forehead bone (Frontal)', false, '6d95b6fe-94ab-484d-8747-87e7ef25357f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d22747df-9c3b-46ef-b21f-9caef2920471', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'The curved bones that join the chest bone (sternum) and the backbone together to form a protective cage around the heart and lungs are called:', '12 pairs of curved ribs form the thoracic cage, shielding the heart, lungs, and major blood vessels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7c3057e-4670-483d-8e78-dae8ba475dd9', 'Ribs (forming the Rib Cage)', true, 'd22747df-9c3b-46ef-b21f-9caef2920471');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9af90316-91fc-470e-a76e-d482e5bce7db', 'Vertebrae', false, 'd22747df-9c3b-46ef-b21f-9caef2920471');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cafc7ad8-27ee-4ba7-9dea-3781b24786c5', 'Pelvis', false, 'd22747df-9c3b-46ef-b21f-9caef2920471');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('007ca73f-d82a-413a-b24c-f23f6eb020f6', 'Clavicles', false, 'd22747df-9c3b-46ef-b21f-9caef2920471');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e3138e5-abea-488b-aa72-87df2ec8cb9e', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'How many pairs of ribs are there in the normal human rib cage?', 'There are 12 bilateral pairs of ribs: 7 true ribs, 3 false ribs, and 2 floating rib pairs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('953416d3-0154-4891-9aa8-bf7df78f727b', '12 pairs (24 ribs total)', true, '3e3138e5-abea-488b-aa72-87df2ec8cb9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e5f477e-3319-4937-9dbf-e918eebc287c', '10 pairs', false, '3e3138e5-abea-488b-aa72-87df2ec8cb9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3491bd83-8279-4ced-b8db-2e1ccfb28ae9', '14 pairs', false, '3e3138e5-abea-488b-aa72-87df2ec8cb9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bca5503-8c6a-4312-b701-e0495cb5fcef', '7 pairs', false, '3e3138e5-abea-488b-aa72-87df2ec8cb9e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c204dc0b-108b-464c-b1ff-85dde084d766', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'The long, flexible column running along our back made up of 33 small individual bones (vertebrae) is the:', 'The vertebral column consists of 33 stacked vertebrae that protect the spinal cord and allow torso bending.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fce4d90-95b2-4b3d-86bb-542e54e7018c', 'Backbone (Spine / Vertebral Column)', true, 'c204dc0b-108b-464c-b1ff-85dde084d766');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c97cb7d-9f0a-4855-abcb-477bcd85647f', 'Rib cage', false, 'c204dc0b-108b-464c-b1ff-85dde084d766');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1a4c311-2082-4e87-b8b5-ab6544c43c17', 'Pelvic bone', false, 'c204dc0b-108b-464c-b1ff-85dde084d766');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83149ff1-af7c-43e4-ba8c-fca6c14bfdd2', 'Femur', false, 'c204dc0b-108b-464c-b1ff-85dde084d766');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2024e316-604c-480f-ad22-29a31aa42a9a', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'The softer, flexible connective tissue that is not as hard as bone and can be bent, found in the upper ear lobe and tip of the nose, is:', 'Cartilage is an avascular, flexible cartilaginous matrix cushioning joints and structuring the external pinna.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cd51a24-1976-4a47-bba6-00263871d460', 'Cartilage', true, '2024e316-604c-480f-ad22-29a31aa42a9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3edbd165-2fb4-44dd-8b67-125536e52a69', 'Ligament', false, '2024e316-604c-480f-ad22-29a31aa42a9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4e59661-7e72-4cb7-b677-aca9f489aa33', 'Tendon', false, '2024e316-604c-480f-ad22-29a31aa42a9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d86fbbb9-140a-4483-87e5-35164e3c7bd1', 'Muscle', false, '2024e316-604c-480f-ad22-29a31aa42a9a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0525d96-a4ed-41a8-89b6-ab2c6cdb2526', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Easy', 'What are the specialized contractile tissues that work in coordinated antagonistic pairs (contraction and relaxation) to pull bones and cause movement?', 'Muscles can only pull (contract) and cannot push; hence they operate in antagonistic pairs to flex and extend limbs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('645553d0-1874-437e-8058-42d104d52982', 'Muscles (e.g., Biceps and Triceps)', true, 'd0525d96-a4ed-41a8-89b6-ab2c6cdb2526');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b218b332-3435-4e01-b0bb-80b454f54beb', 'Cartilage', false, 'd0525d96-a4ed-41a8-89b6-ab2c6cdb2526');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dbbea3d-2bd3-4326-a9b3-188e477a7b76', 'Nerves', false, 'd0525d96-a4ed-41a8-89b6-ab2c6cdb2526');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93180925-33cd-457f-b468-7a5a0b7d977f', 'Blood vessels', false, 'd0525d96-a4ed-41a8-89b6-ab2c6cdb2526');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd754c7f-266b-4745-be7e-482f128230cd', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'Why do muscles always operate in PAIRS to move a bone at a joint?', 'Muscle fiber sliding-filament contraction exerts unidirectional tensile pulling force; returning the limb requires an antagonistic counter-pull.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a1f29df-2aba-4d2c-8ad5-7c852d8091e6', 'A muscle can only pull (contract) and cannot push; when one contracts to pull a bone, the other relaxes, and vice versa to return it', true, 'dd754c7f-266b-4745-be7e-482f128230cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5551b98-d50e-4f49-a65b-67c487200da4', 'Because one muscle is always sleeping', false, 'dd754c7f-266b-4745-be7e-482f128230cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad1fbdfa-d2e3-4d1f-8eaa-3daa74096ba9', 'To make bones heavier', false, 'dd754c7f-266b-4745-be7e-482f128230cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61dfc39e-5bfd-467f-8779-67d67580cd62', 'Because bones have two heads', false, 'dd754c7f-266b-4745-be7e-482f128230cd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1b13683-9a47-404d-855c-d2b06d12cbf5', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'How does an Earthworm crawl forward on the ground without having any internal bones?', 'Peristaltic hydrostatic locomotion: circular and longitudinal muscle waves coordinate with anchoring chitinous setae.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64e58f81-8804-4065-8a60-a40d399dff01', 'By alternate cycles of muscular contraction and expansion of body segments, aided by tiny hair-like bristles (setae) that grip the soil', true, 'c1b13683-9a47-404d-855c-d2b06d12cbf5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f2ab75e-6a47-48be-beaa-2c1561a4d8c7', 'By rolling like a ball', false, 'c1b13683-9a47-404d-855c-d2b06d12cbf5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19f50fed-86e6-42d5-adaf-f26c9274602a', 'By using wings to glide', false, 'c1b13683-9a47-404d-855c-d2b06d12cbf5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70081214-cb82-45bb-a15a-50deffd50c2d', 'By jumping with legs', false, 'c1b13683-9a47-404d-855c-d2b06d12cbf5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e4751ad-9020-4a3f-9ad0-62fc73e79027', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'What organ does a Snail use for locomotion, and what substance does it secrete to glide smoothly over sharp surfaces?', 'The ventral muscular foot produces retrograde pedal muscular waves over a protective friction-reducing mucus layer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80c7edf1-c587-4567-8505-334df8b54be8', 'A strong muscular foot, secreting a slimy layer of lubricating mucus', true, '4e4751ad-9020-4a3f-9ad0-62fc73e79027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e228126-ea4a-497c-9aa7-6e9357b9c607', 'Jointed legs, secreting wax', false, '4e4751ad-9020-4a3f-9ad0-62fc73e79027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f2d9161-a012-4d8e-b011-32bd3249b97e', 'Wings, secreting water', false, '4e4751ad-9020-4a3f-9ad0-62fc73e79027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d8af701-c2ef-41dc-9001-cf7537f24f69', 'A bony tail, secreting oil', false, '4e4751ad-9020-4a3f-9ad0-62fc73e79027');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02235729-572a-4443-b91f-b8c594f3d755', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'How many pairs of walking legs and how many pairs of wings does a Cockroach have attached to its thorax?', 'Cockroach hexapod anatomy: three thoracic segments bear three pairs of jointed ambulatory legs and two pairs of wings.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('932ba676-e3d6-444c-bfb7-97e2fba2d819', '3 pairs of legs (6 legs) and 2 pairs of wings (4 wings)', true, '02235729-572a-4443-b91f-b8c594f3d755');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cde12e21-d1f4-44b4-b282-ac2b9b554213', '4 pairs of legs and 1 pair of wings', false, '02235729-572a-4443-b91f-b8c594f3d755');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('610a0924-4cf7-404a-a12f-e6bbfc4cf010', '2 pairs of legs and 2 pairs of wings', false, '02235729-572a-4443-b91f-b8c594f3d755');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dbcdf12-df15-4aa2-8a51-6adb1e1bfc12', '5 pairs of legs and 0 wings', false, '02235729-572a-4443-b91f-b8c594f3d755');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4de4766c-e7e4-45cb-bbd2-04e0756f9db3', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'What anatomical adaptations enable Birds to fly efficiently in the air?', 'Avian flight requires pneumatic skeletal weight reduction, aerodynamic wing camber, and hypertrophied supracoracoideus/pectoralis flight muscles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8781803-b920-4f5c-a711-f7dc5f1f07c0', 'Hollow and light pneumatic bones, forelimbs modified into wings with flight feathers, and powerful pectoral breast muscles attached to a deep breastbone', true, '4de4766c-e7e4-45cb-bbd2-04e0756f9db3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c0e9712-e816-4499-8acb-ddf47e43dc89', 'Heavy solid bones to resist wind', false, '4de4766c-e7e4-45cb-bbd2-04e0756f9db3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2466e35-a702-42fe-ac22-11b46ee0199c', 'Lack of heart and lungs', false, '4de4766c-e7e4-45cb-bbd2-04e0756f9db3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3546fb3-596e-45af-a280-4165a071bc75', 'A heavy tail made of steel', false, '4de4766c-e7e4-45cb-bbd2-04e0756f9db3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('40ce6e12-7936-457f-9ce8-58aa55fba145', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'What is the characteristic ''streamlined'' body shape of a Fish, and how does it assist aquatic swimming?', 'Fusiform hydrodynamic streamlining reduces laminar drag, skin friction, and wake vortices during underwater propulsion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbf80329-23bc-4217-8ea0-c9f39ba35173', 'The head and tail are narrower than the middle portion, minimizing fluid resistance and drag as it glides through water', true, '40ce6e12-7936-457f-9ce8-58aa55fba145');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c60dd534-e1b4-42cf-a98e-6312116eb9d1', 'A square flat shape that traps water', false, '40ce6e12-7936-457f-9ce8-58aa55fba145');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cadafe4-b472-40ec-91ef-4609b4eb4123', 'A circular spherical shape', false, '40ce6e12-7936-457f-9ce8-58aa55fba145');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('559051a2-8122-4e34-bc68-03f31927d289', 'A long straight line without curves', false, '40ce6e12-7936-457f-9ce8-58aa55fba145');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('70475199-042c-456b-a908-b380d4a4a618', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'How does a Fish propel itself forward through water using its body and caudal (tail) fin?', 'Alternating lateral myotomal muscle contractions produce undulating waves along the spine, ending in a propulsive caudal thrust.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0007f886-e87e-47b7-a700-40e35aec00fd', 'By curving its flexible body into alternating side-to-side loops (undulations), where the tail fin pushes water in the opposite direction creating forward thrust', true, '70475199-042c-456b-a908-b380d4a4a618');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c777ef1-c76e-4ab1-9379-080c8d196cbd', 'By sucking in water through its nose', false, '70475199-042c-456b-a908-b380d4a4a618');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2596457-c838-428f-a90c-666a80aefc07', 'By walking on underwater sand', false, '70475199-042c-456b-a908-b380d4a4a618');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffc49e45-53d2-4f1a-9b88-561742fbbe48', 'By floating motionless', false, '70475199-042c-456b-a908-b380d4a4a618');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad498ed5-37a7-486e-972e-c7af12cda2a3', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'How does a Snake move rapidly across ground without having any limbs or legs?', 'Serpentine lateral undulation: wave curves along hundreds of vertebrae and ribs exert posterior force against ground irregularities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4eccc5e8-6708-4041-b1b0-a5950dd078df', 'By slithering in S-shaped sinusoidal loops; each loop presses against the ground to push the snake forward', true, 'ad498ed5-37a7-486e-972e-c7af12cda2a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03aa821a-2f96-4bc5-91fd-4e3a64a0392d', 'By rolling like a wheel', false, 'ad498ed5-37a7-486e-972e-c7af12cda2a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('667310c7-403e-4f7b-b2b7-7b4fe28ccb61', 'By jumping on its tail', false, 'ad498ed5-37a7-486e-972e-c7af12cda2a3');
