INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('507e08cc-4dbb-4203-8f81-4f019c34c29c', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'Why do snakes move in deep wave-like curves and NEVER in a perfectly straight line during rapid slithering?', 'Lateral undulation requires curved contact zones where body angles transfer vector thrust against friction points.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c478162d-7ba6-42ea-ad69-f272821a130f', 'Each lateral loop of its long flexible body pushes against surface irregularities to generate forward momentum', true, '507e08cc-4dbb-4203-8f81-4f019c34c29c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11a21047-aa6c-469d-b95d-d116bb672bd4', 'Snakes have crooked eyes', false, '507e08cc-4dbb-4203-8f81-4f019c34c29c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ed6bf5a-36b2-4992-93b7-5e2e56d334ad', 'Straight paths make snakes dizzy', false, '507e08cc-4dbb-4203-8f81-4f019c34c29c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2d6931e-b0e4-4d81-875b-4ac22e1e81f7', 'Snakes cannot bend their bones', false, '507e08cc-4dbb-4203-8f81-4f019c34c29c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5264f008-295e-4a36-b1cd-c9111700fa17', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'What is an X-ray radiograph used for in medical diagnostic science?', 'High-density calcium in bones absorbs X-ray photons, casting sharp white silhouettes on radiographic film to reveal fractures.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74518f03-c941-4c15-adff-6365eddbb203', 'To capture photographic shadow images of dense bones and detect fractures, dislocations, or skeletal injuries', true, '5264f008-295e-4a36-b1cd-c9111700fa17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1d6c297-3ef2-4a08-999a-ac07d006f2c7', 'To check blood color', false, '5264f008-295e-4a36-b1cd-c9111700fa17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eead3c9f-d72f-4d76-ad79-2f5e7554bb0f', 'To count hairs on the head', false, '5264f008-295e-4a36-b1cd-c9111700fa17');
