INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aac7121a-0b28-4348-b585-89c8cf063add', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'Which anatomical joint in the human body is formed by the Pelvic bone joining the upper leg bone (Femur)?', 'The femoral head inserts into the pelvic acetabulum socket, forming a stable weight-bearing ball-and-socket joint.', NOW()) ON CONFLICT DO NOTHING;
