INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78a496cd-5c9f-478a-9630-e63ad7c5635f', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'What is the tough, fibrous connective tissue band that attaches a MUSCLE to a BONE called?', 'Tendons are collagenous bands transmitting contractile muscle forces to move skeletal bones.', NOW()) ON CONFLICT DO NOTHING;
