INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('39dc5e4f-3e61-456a-813c-539100507ed2', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'What is the strong fibrous connective tissue band that connects a BONE to another BONE at a joint called?', 'Ligaments are strong elastomeric bands bridging bone-to-bone junctions to stabilize joint capsules.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10bc49c3-bdb5-42d7-abac-5f9d90e600eb', 'Ligament', true, '39dc5e4f-3e61-456a-813c-539100507ed2');
