INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1bb0113-1e71-416d-a6b4-9db70713ee84', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'Why is the human backbone composed of 33 small vertebrae with intervertebral discs instead of one single, solid long bone?', 'Segmented multi-vertebral articulation provides multi-axis spinal flexibility, shock absorption, and bending.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aaed5f8f-d5a0-4275-8434-2c14fb3b0073', 'If it were a single continuous bone, we would never be able to bend forward, backward, or twist our torso sideways', true, 'c1bb0113-1e71-416d-a6b4-9db70713ee84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5534a03-f4f7-49d6-a1c2-06ec19939d29', 'To make the body heavier', false, 'c1bb0113-1e71-416d-a6b4-9db70713ee84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('199015dd-a090-4795-803d-edf77fe1d374', 'Because one long bone would melt', false, 'c1bb0113-1e71-416d-a6b4-9db70713ee84');
