INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2be2d833-68f3-402e-9fe7-95d5b7dc88ad', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'Which of the following animals possesses a hard external skeleton (Exoskeleton) made of chitin that is periodically molted?', 'Arthropods (insects, crustaceans) possess a rigid cuticular chitinous exoskeleton encasing soft internal organs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1106996b-36ec-4079-b7fe-2b114b4ec7aa', 'Cockroach and Crab', true, '2be2d833-68f3-402e-9fe7-95d5b7dc88ad');
