INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6866db6-dd7b-4825-998c-d08fc68ce25b', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Medium', 'What is the ancient philosophical Greek treatise ''Gait of Animals'' (De Motu Animalium) that first analyzed the mechanics of animal locomotion authored by?', 'Aristotle authored ''Progression of Animals'' and ''Movement of Animals'', pioneering the comparative biomechanics of locomotion.', NOW()) ON CONFLICT DO NOTHING;
