INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51c7d764-35b1-413d-9b96-eb60408053db', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '3352aa6d-126e-4447-b35e-a491410528f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17e402f4-ccc0-4ed4-a003-c146a24352e7', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '3352aa6d-126e-4447-b35e-a491410528f5');
