INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('356a9aff-cc7b-4124-ac83-b5e5b95e014d', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'Spot the IMPOSTER in the following group of anatomical joints paired with their locations in the human body:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c16f7d13-de20-4999-a5a8-41e142c4a2da', 'Shoulder Joint - Ball and Socket', false, '356a9aff-cc7b-4124-ac83-b5e5b95e014d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('046d5062-f77e-4411-ac35-08433f810195', 'Elbow Joint - Hinge', false, '356a9aff-cc7b-4124-ac83-b5e5b95e014d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c82de34-51ef-4605-b3b0-5968df46cb52', 'Cranial Sutures - Fixed', false, '356a9aff-cc7b-4124-ac83-b5e5b95e014d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7042ec47-1e2e-489e-9f53-f3438c53cc96', 'Knee Joint - Pivot', true, '356a9aff-cc7b-4124-ac83-b5e5b95e014d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34638692-5de8-46c3-aca0-de2bc5b34603', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'A biomechanist observes the flight mechanics of a pigeon. What anatomical structures execute the ''downstroke'' and ''upstroke'' of the wings during flight?', 'Avian triosseal canal pulley mechanism: Pectoralis major powers propulsive downstrokes, while supracoracoideus elevates wings for upstroke.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1ff0172-877c-41f3-bf57-351ebe402786', 'The massive Pectoralis major breast muscle contracts for the powerful downstroke, while the Pectoralis minor (Supracoracoideus) pulls a tendon over a pulley to lift the wing in upstroke', true, '34638692-5de8-46c3-aca0-de2bc5b34603');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5823f72-ae99-4808-a551-ed3304b468e1', 'The legs kick backwards', false, '34638692-5de8-46c3-aca0-de2bc5b34603');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11a2c9ac-3341-4668-8eee-4ff2a754247b', 'The neck turns left and right', false, '34638692-5de8-46c3-aca0-de2bc5b34603');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68f7ec92-10ed-40ec-a286-50e7b44a3684', 'Air is blown out from the tail', false, '34638692-5de8-46c3-aca0-de2bc5b34603');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a729a76a-d111-45af-b3f2-ec2f027dbf46', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'Match Column I (Organisms) with Column II (Locomotory Organs / Mechanics):
(a) Earthworm -> (i) Muscular foot with mucus trail
(b) Snail     -> (ii) Hydrostatic body segments with setae
(c) Cockroach -> (iii) Streamlined body with myotomes and fins
(d) Fish      -> (iv) Jointed thoracic legs and chitinous wings', 'Earthworm = setae & segments; Snail = muscular foot; Cockroach = 6 legs & wings; Fish = streamlined myotome fins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea1251a1-f47c-4f3b-9919-f5aa1eb380c8', 'a-(ii), b-(i), c-(iv), d-(iii)', true, 'a729a76a-d111-45af-b3f2-ec2f027dbf46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03ddff2d-ddfd-4e2c-ae75-4678271faf3e', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'a729a76a-d111-45af-b3f2-ec2f027dbf46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ac60c22-20fb-47f6-bcc3-17482f050d0c', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'a729a76a-d111-45af-b3f2-ec2f027dbf46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87439026-f7c2-40ca-9789-00c385d562a6', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'a729a76a-d111-45af-b3f2-ec2f027dbf46');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('df740e03-f397-4aad-9599-6161f2d0f6f7', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'Read the statements regarding skeletal anatomy:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20ba2385-4435-4cb2-8eaf-9bc592f46abf', 'Statements 1 and 2 only', true, 'df740e03-f397-4aad-9599-6161f2d0f6f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be8e9562-da93-4011-873b-7cd85b1ee288', 'Statements 2 and 3 only', false, 'df740e03-f397-4aad-9599-6161f2d0f6f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c75126dc-e38a-4908-ad85-440d1e20f658', 'Statements 1 and 3 only', false, 'df740e03-f397-4aad-9599-6161f2d0f6f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3af227f-34bc-4e0c-b8cb-497b8b39e57e', 'All Statements 1, 2, and 3', false, 'df740e03-f397-4aad-9599-6161f2d0f6f7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b97a4f0d-cda4-4f5d-b441-8cbdf642722c', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'Why do underwater divers wear long, flipper-shaped swim fins on their feet?', 'Flippers increase effective propulsive surface area, converting oscillating leg strokes into laminar hydrodynamic thrust.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eeae77b4-b214-44d6-abe8-27af2f687efb', 'To mimic the streamlined flat caudal fins of fish, maximizing water displacement thrust and swimming speed with minimal muscular effort', true, 'b97a4f0d-cda4-4f5d-b441-8cbdf642722c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d907c840-c8f0-44ac-a453-91e79d887549', 'To keep their feet warm', false, 'b97a4f0d-cda4-4f5d-b441-8cbdf642722c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9eb80521-7b25-4c2a-9190-cba047e01d89', 'To walk on the ocean floor like a crab', false, 'b97a4f0d-cda4-4f5d-b441-8cbdf642722c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1c6268a-841e-42e6-a823-79d9eb2884f3', 'To float like a balloon', false, 'b97a4f0d-cda4-4f5d-b441-8cbdf642722c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3420efe3-6352-451c-8742-5e9552bcbe27', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'What happens when a person flexes (bends) their arm at the elbow to touch their shoulder with their hand?', 'Elbow flexion: agonist biceps brachii contracts concentrically while antagonist triceps brachii lengthens in eccentric relaxation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('604c2b4c-8c49-4b46-903b-af648d6f18af', 'The Biceps muscle on the front of the upper arm contracts (shortens and bulges), while the Triceps muscle on the back relaxes', true, '3420efe3-6352-451c-8742-5e9552bcbe27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c90038d2-b098-4a66-ad21-7969c10e22ad', 'The Triceps contracts and biceps relaxes', false, '3420efe3-6352-451c-8742-5e9552bcbe27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9156c1b2-63da-4ad6-8cde-a5902aee2f20', 'Both biceps and triceps contract simultaneously', false, '3420efe3-6352-451c-8742-5e9552bcbe27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('191424e5-aa1f-40fd-86a4-f06bb32cda46', 'Both muscles relax completely', false, '3420efe3-6352-451c-8742-5e9552bcbe27');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('162ffb5d-65da-446a-8763-2d71a432e857', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'Consider four joints in the human body:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a293e72-396d-4b84-b39b-1e9dfaaa444a', '1 (Ball & Socket - 360°) -> 4 (Gliding) -> 3 (Hinge - 180°) -> 2 (Fixed - 0°)', true, '162ffb5d-65da-446a-8763-2d71a432e857');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('659c7674-4441-429f-a9c3-c89224663de2', '2 -> 3 -> 4 -> 1', false, '162ffb5d-65da-446a-8763-2d71a432e857');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b4f885c-5ddf-4b07-b84b-c3e0c634515d', '3 -> 1 -> 4 -> 2', false, '162ffb5d-65da-446a-8763-2d71a432e857');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf17ef2b-d13c-44db-8d80-386cc0c928cb', '1 -> 2 -> 3 -> 4', false, '162ffb5d-65da-446a-8763-2d71a432e857');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b202815-1667-4808-a895-291975c85f5f', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'Why are the bones of the pelvic girdle much thicker, heavier, and more tightly fused than the bones of the shoulder pectoral girdle?', 'The ilium, ischium, and pubis fuse into a heavy rigid osseous ring to transfer axial torso loads into lower limb femurs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43641da6-bd53-4797-b9b6-46fe897adee2', 'The pelvic girdle bears the entire weight of the upper body during standing, walking, and running, and protects pelvic visceral organs', true, '0b202815-1667-4808-a895-291975c85f5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54c464c3-c54b-46cf-a155-56b9128cb0f0', 'To store extra blood', false, '0b202815-1667-4808-a895-291975c85f5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86540aa8-d4dd-40f0-a4a8-b5645dad023b', 'Because legs are shorter than arms', false, '0b202815-1667-4808-a895-291975c85f5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57c0a32a-5102-49b0-925e-ddf955dfd323', 'To help digest food', false, '0b202815-1667-4808-a895-291975c85f5f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ce6b14e-132d-4b7c-8622-8c63bd7feedb', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'How does the swim bladder (air bladder) in bony fishes assist their buoyancy and vertical movement in water?', 'Hydrostatic swim bladders adjust gas partial pressure via the rete mirabile to equalize whole-body density with surrounding water density.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c9c9591-c707-47eb-acec-c588f28d909e', 'By regulating the volume of gas inside the bladder, allowing the fish to maintain neutral buoyancy and hover at any water depth without sinking or floating', true, '8ce6b14e-132d-4b7c-8622-8c63bd7feedb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edeb6ef6-4421-42b2-993a-abab2df913bf', 'By heating the water around the fish', false, '8ce6b14e-132d-4b7c-8622-8c63bd7feedb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33500da3-b371-4ca0-ae59-1c149f906ef1', 'By digesting fish food', false, '8ce6b14e-132d-4b7c-8622-8c63bd7feedb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8848949-1fb1-4dd0-9d7d-a68c133e6f43', 'By glowing in the dark', false, '8ce6b14e-132d-4b7c-8622-8c63bd7feedb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61956692-7209-4ac1-9d34-2533056a3602', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'Which of the following describes the functional anatomy of the human Wrist Joint (Carpal bones)?', 'Intercarpal articulations are planar arthrodial gliding joints allowing smooth translational sliding motions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f77d6392-6dff-47a2-b98e-878059f4a623', 'Gliding Joint (Plane Joint) where small carpal bones slide gently over one another, providing subtle multidirectional hand flexion', true, '61956692-7209-4ac1-9d34-2533056a3602');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b2a09e7-9401-4291-b638-f14742612db3', 'Ball and Socket Joint', false, '61956692-7209-4ac1-9d34-2533056a3602');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f140ee97-a2f0-4861-90ff-3478a95a0a62', 'Fixed Suture Joint', false, '61956692-7209-4ac1-9d34-2533056a3602');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('015d6118-ed59-4403-8774-fb560c1f2738', 'Pivotal Joint', false, '61956692-7209-4ac1-9d34-2533056a3602');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b8a0310b-0563-4eac-82ca-bbbcfb122561', 'Class 6', 'Science', 'Chapter 5: Body Movements', 'Hard', 'What physiological consequence occurs if articular cartilage at the ends of synovial joints wears away due to degenerative disease (osteoarthritis)?', 'Loss of hyaline articular cartilage eliminates hydrodynamic lubrication, leading to painful eburnation and bone spurs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e71cdf53-65da-4ec2-8410-9987f827f414', 'Exposed bare bones rub directly against each other, causing severe friction, excruciating pain, inflammation, and stiffness during movement', true, 'b8a0310b-0563-4eac-82ca-bbbcfb122561');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2bbbe1d-7f26-4886-bb66-78535c30e6e3', 'Bones turn into soft muscle', false, 'b8a0310b-0563-4eac-82ca-bbbcfb122561');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e77f0632-ee44-4d4a-8479-f22e4693b6c8', 'Joints become 10 times more flexible', false, 'b8a0310b-0563-4eac-82ca-bbbcfb122561');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc5b632f-3d54-4228-9730-0ed1114b88a1', 'Bones disappear completely', false, 'b8a0310b-0563-4eac-82ca-bbbcfb122561');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fdcdd7a3-71e0-4755-a6b4-d5c06f71323c', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Easy', 'An angle measuring exactly 90° (equal to one-fourth of a full revolution) is called a:', 'A right angle measures exactly 90° (¼ of a 360° full revolution).', NOW()) ON CONFLICT DO NOTHING;
