INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('230ceb02-98a5-41b7-b4f4-2000473e03bb', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'What fraction of a clockwise revolution does the hour hand of a clock turn through when it goes from 3 to 9?', 'From 3 to 9 is 6 hour divisions: 6/12 = 1/2 revolution = 180°.', NOW()) ON CONFLICT DO NOTHING;
