INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eda3d695-8318-44a5-9818-c2ccb244b0ed', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'What fraction of a clockwise revolution does the hour hand of a clock turn through when it goes from 12 to 3?', 'From 12 to 3 is 3 hour divisions: 3/12 = 1/4 revolution = 90°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f80fe05b-8e6e-42ac-be6b-4599f2c22db1', '1/4 revolution (90° / 1 right angle)', true, 'eda3d695-8318-44a5-9818-c2ccb244b0ed');
