INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4775219e-92cf-4b5b-ac28-4d05236aaa0a', '3/4 revolution', false, 'eda3d695-8318-44a5-9818-c2ccb244b0ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13dc2480-b339-4611-a27f-aa8ca09d3bf1', '1/3 revolution', false, 'eda3d695-8318-44a5-9818-c2ccb244b0ed');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f77d24a-b267-47fa-b31f-dfad89118a81', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'Where will the hand of a clock stop if it starts at 12 and makes 1/2 of a revolution clockwise?', '12 + (1/2 × 12) = 12 + 6 = 6 o''clock.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6911d5c9-7206-43d0-894f-3c147beac107', 'At 6', true, '9f77d24a-b267-47fa-b31f-dfad89118a81');
