INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3386037b-a005-4fea-96bc-ca06c55f6819', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'Where will the hand of a clock stop if it starts at 2 and makes 3/4 of a revolution clockwise?', '3/4 of 12 hours = 9 hours. 2 + 9 = 11 o''clock.', NOW()) ON CONFLICT DO NOTHING;
