INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0222f705-5c4e-40c9-aa1a-524850d5f306', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'If you face North and turn clockwise to face East, what fraction of a revolution have you turned through?', 'From North (0°) clockwise to East (90°) is 90°/360° = 1/4 revolution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3b31994-5074-4f72-81d4-3e309167c3d1', '1/4 revolution (90° right angle)', true, '0222f705-5c4e-40c9-aa1a-524850d5f306');
