INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66de7003-7bbc-463f-9f3c-96028c24501c', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'If you face West and turn clockwise to face South, how many right angles have you turned through?', 'From West clockwise: West -> North (1) -> East (2) -> South (3) = 3 right angles (270°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90f2f0a5-c805-40a9-924b-14b8e786e3e1', '3 right angles (270° / 3/4 revolution)', true, '66de7003-7bbc-463f-9f3c-96028c24501c');
