INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01ac8094-1697-47a6-8615-3a1e1cd02b81', '2 right angles', false, '66de7003-7bbc-463f-9f3c-96028c24501c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02a25f15-2ed2-4932-af3a-0705b774ff9d', '4 right angles', false, '66de7003-7bbc-463f-9f3c-96028c24501c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97367363-0338-4e43-8b60-4b63bd09e0c8', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'What is a line called that is perpendicular to a given line segment and divides it into two exact equal halves?', 'A perpendicular bisector intersects a segment at its midpoint at a right angle (90°).', NOW()) ON CONFLICT DO NOTHING;
