INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('748804a7-3177-4c97-8148-6f64aabab252', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'A quadrilateral in which opposite sides are parallel and equal, but opposite angles are NOT necessarily 90°, is a:', 'A parallelogram has opposite parallel congruent sides and bisecting diagonals.', NOW()) ON CONFLICT DO NOTHING;
