INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fff59e5d-0d25-465a-839a-1170c9cd6099', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'A quadrilateral having all 4 sides equal, opposite sides parallel, but whose angles are not 90° is a:', 'A rhombus is an equilateral parallelogram whose diagonals bisect each other perpendicularly at 90°.', NOW()) ON CONFLICT DO NOTHING;
