INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94532514-1eee-4401-84b8-8f2c3310afc4', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'A quadrilateral with exactly ONE pair of parallel opposite sides is called a:', 'A trapezium is a 4-sided polygon having strictly one pair of parallel opposing bases.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6adbc0de-8fa1-4a36-9b3c-5ab11927730c', 'Trapezium (or Trapezoid)', true, '94532514-1eee-4401-84b8-8f2c3310afc4');
