INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d257b9a-7c65-4dc4-834c-97cbe7c2078b', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'What is a 5-sided polygon and an 8-sided polygon called respectively in geometry?', '5 sides = Pentagon; 6 sides = Hexagon; 7 sides = Heptagon; 8 sides = Octagon.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('818f837e-b7d6-42d1-8867-2bc988c1e418', 'Pentagon (5 sides) and Octagon (8 sides)', true, '9d257b9a-7c65-4dc4-834c-97cbe7c2078b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9526e7d5-d9d8-4033-99fd-9edab2bab0ef', 'Hexagon and Heptagon', false, '9d257b9a-7c65-4dc4-834c-97cbe7c2078b');
