INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcc86396-96e6-4b2c-8884-57641d9364a8', 'Triangle and Quadrilateral', false, '9d257b9a-7c65-4dc4-834c-97cbe7c2078b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98efb33c-b93e-4a71-a46b-3b562f1de27f', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'What are the numbers of Faces (F), Vertices (V), and Edges (E) in a triangular pyramid (Tetrahedron)?', 'A tetrahedron has 4 triangular faces, 4 corner vertices, and 6 connecting edges (Euler''s formula F+V-E = 4+4-6 = 2).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a55acd95-3520-4a1d-aabb-0c2e22f9cc14', '4 Faces, 4 Vertices, 6 Edges', true, '98efb33c-b93e-4a71-a46b-3b562f1de27f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31bc6373-6128-41b6-99b4-a18f1cf8ac5e', '5 Faces, 6 Vertices, 9 Edges', false, '98efb33c-b93e-4a71-a46b-3b562f1de27f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a57e49d-d02f-4187-a2be-5942af9a73b3', '6 Faces, 8 Vertices, 12 Edges', false, '98efb33c-b93e-4a71-a46b-3b562f1de27f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2570f596-adbd-4538-aebb-0521425e8ae3', '4 Faces, 6 Vertices, 4 Edges', false, '98efb33c-b93e-4a71-a46b-3b562f1de27f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18aad674-c101-4292-82a7-0e1c5687591d', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'What are the numbers of Faces, Vertices, and Edges in a Triangular Prism?', 'A triangular prism has 5 faces (2 bases + 3 rectangular sides), 6 vertices, and 9 edges (5+6-9 = 2).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f34254a9-ad9c-4df3-85a0-f05d33e3a312', '5 Faces (2 triangular, 3 rectangular), 6 Vertices, 9 Edges', true, '18aad674-c101-4292-82a7-0e1c5687591d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2585b34-2a6f-418b-890e-06a6405b63f9', '4 Faces, 4 Vertices, 6 Edges', false, '18aad674-c101-4292-82a7-0e1c5687591d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30dea2b6-8766-401d-97ef-e35c63e399d0', '6 Faces, 8 Vertices, 12 Edges', false, '18aad674-c101-4292-82a7-0e1c5687591d');
