INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('24d12f85-7adc-4029-b2b4-b62099cc85b8', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'What are the numbers of Faces, Vertices, and Edges in a Square Pyramid (like the Egyptian Pyramids)?', 'A square pyramid has 5 faces, 5 vertices (1 apex + 4 base), and 8 edges (5+5-8 = 2).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48c26d1f-6d25-4365-9509-5d303c5a487a', '5 Faces (1 square base, 4 triangular sides), 5 Vertices, 8 Edges', true, '24d12f85-7adc-4029-b2b4-b62099cc85b8');
