INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e556e4de-232a-486d-91b4-6d8cd674e54d', '4 Faces, 4 Vertices, 6 Edges', false, '24d12f85-7adc-4029-b2b4-b62099cc85b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('617198a3-8b79-4fa7-a51b-274b9d964f03', '5 Faces, 6 Vertices, 9 Edges', false, '24d12f85-7adc-4029-b2b4-b62099cc85b8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc8aa401-9c07-49ce-b579-4e4a61bb053d', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'Which of the following 3D solid shapes has NO flat face, NO straight edge, and NO vertex?', 'A sphere is a perfectly smooth continuous curved surface with zero vertices, zero edges, and zero planar faces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27828570-8de7-4b69-a160-c88189e04a15', 'Sphere (e.g. a football)', true, 'dc8aa401-9c07-49ce-b579-4e4a61bb053d');
