INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bedd8240-8e26-4ff5-9975-a20edc8feab9', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Medium', 'How many circular flat faces and curved surfaces does a solid Cylinder have?', 'A cylinder possesses two congruent circular planar end-bases connected by a single lateral curved surface.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bff82c55-537d-405f-9301-02fa293fa852', '2 flat circular faces and 1 curved surface', true, 'bedd8240-8e26-4ff5-9975-a20edc8feab9');
