INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('90ae533c-39c7-46a6-a074-8de37ffd0d87', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'What is the angle between the hands of a clock at 9:00 PM?', 'Hour hand at 9, minute hand at 12: separation = 3 hour marks = 3 × 30° = 90°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07e9372e-cb2d-4b50-ba51-2388224f27de', '90° (Right angle) or Reflex 270°', true, '90ae533c-39c7-46a6-a074-8de37ffd0d87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdac68ea-ab91-4adf-bca7-770038898353', '180°', false, '90ae533c-39c7-46a6-a074-8de37ffd0d87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('245a2cb2-4c1a-43c7-a04f-9e682918e56f', '120°', false, '90ae533c-39c7-46a6-a074-8de37ffd0d87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df98f52a-c669-4cba-a8cf-be13364f0f07', '60°', false, '90ae533c-39c7-46a6-a074-8de37ffd0d87');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bd9edeaf-2e90-43e4-bfa8-a1824eec4cbb', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'Match Column I (Quadrilaterals) with Column II (Properties of Diagonals):
(a) Square        -> (i) Diagonals are equal and bisect each other perpendicularly at 90°
(b) Rectangle     -> (ii) Diagonals are equal and bisect each other (not at 90°)
(c) Rhombus       -> (iii) Diagonals are unequal and bisect each other perpendicularly at 90°
(d) Parallelogram -> (iv) Diagonals bisect each other but are neither equal nor perpendicular', 'Square = equal & perp; Rectangle = equal; Rhombus = unequal & perp; Parallelogram = bisect only.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ca4319c-2379-4aa3-82f9-01dc8f94b3c4', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'bd9edeaf-2e90-43e4-bfa8-a1824eec4cbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4f831d8-3a16-4670-a20b-c6b4ae5b557e', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'bd9edeaf-2e90-43e4-bfa8-a1824eec4cbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6be8ac6-31d7-43ea-8123-3161fdadb0ad', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'bd9edeaf-2e90-43e4-bfa8-a1824eec4cbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b73128a-76ca-41d1-9581-0e21c303176d', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'bd9edeaf-2e90-43e4-bfa8-a1824eec4cbb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e74277e4-a3c7-4e6b-922d-e64a7ac76cd3', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f000a761-8116-4f52-b4eb-115677b162c6', 'Statement 3 only', true, 'e74277e4-a3c7-4e6b-922d-e64a7ac76cd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10473067-6490-4896-84f1-e2b8d379fb0f', 'Statements 1 and 2 only', false, 'e74277e4-a3c7-4e6b-922d-e64a7ac76cd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a13286a2-f448-4407-9b99-753f79d70f19', 'Statements 2 and 3 only', false, 'e74277e4-a3c7-4e6b-922d-e64a7ac76cd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29a852e2-5b0c-4da9-9942-e4f60cbc5008', 'All Statements 1, 2, and 3', false, 'e74277e4-a3c7-4e6b-922d-e64a7ac76cd3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('167392b5-bdfe-4f6b-857b-10479682e93b', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'What is the angle traced by the hour hand of a clock between 1:00 PM and 5:00 PM?', 'Each clock hour span = 360°/12 = 30°. Elapsed time = 4 hours -> 4 × 30° = 120° (Obtuse angle).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6047cc22-fe3e-4dc1-90b9-24940e97133c', '120° (4 hours × 30°/hour = 4/12 × 360°)', true, '167392b5-bdfe-4f6b-857b-10479682e93b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a7ecb7b-53bf-44f7-ac45-5ac5374d2d31', '90°', false, '167392b5-bdfe-4f6b-857b-10479682e93b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('334ef6b6-a62c-4d14-acfb-3a9f4963035b', '150°', false, '167392b5-bdfe-4f6b-857b-10479682e93b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3edf6b52-080d-40a2-a876-72fe2264b37e', '180°', false, '167392b5-bdfe-4f6b-857b-10479682e93b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7411fd2c-8e59-4627-a709-cd1b137f4bb9', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'A polygon is ''Regular'' if it satisfies which two conditions simultaneously?', 'A regular polygon (like an equilateral triangle or square) has equal edge lengths and congruent interior vertex angles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ffc5b9c-23a5-44bf-99d2-89b5fb2bb9a2', 'It is Equilateral (all sides equal) AND Equiangular (all internal angles equal)', true, '7411fd2c-8e59-4627-a709-cd1b137f4bb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d13691ba-a5e9-4211-9192-00903c924518', 'It has only 4 sides', false, '7411fd2c-8e59-4627-a709-cd1b137f4bb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78c3cbb8-7630-4d7d-bd78-7431e422ee86', 'It has curved sides', false, '7411fd2c-8e59-4627-a709-cd1b137f4bb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb891c44-ca5d-4509-8bf4-a8ed3cd1d9e5', 'Its diagonals are parallel', false, '7411fd2c-8e59-4627-a709-cd1b137f4bb9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a8bf067b-e42a-4a89-9259-865b696bd145', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'How many total faces, edges, and vertices does an Octahedron (8-faced regular polyhedron formed by joining two square pyramids base-to-base) possess?', 'An octahedron has 8 triangular faces, 6 vertices, and 12 edges (8 + 6 - 12 = 2).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94fdbd3d-b00f-47a3-9d7a-c8c264f293ed', '8 Faces, 6 Vertices, 12 Edges', true, 'a8bf067b-e42a-4a89-9259-865b696bd145');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54709750-17e9-4df4-9bac-c6cf00a0dc9a', '8 Faces, 8 Vertices, 16 Edges', false, 'a8bf067b-e42a-4a89-9259-865b696bd145');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39a8c8e2-74ec-41f7-9a5f-e18e9b4133ea', '6 Faces, 8 Vertices, 12 Edges', false, 'a8bf067b-e42a-4a89-9259-865b696bd145');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be2593ef-0107-4dcc-9d3c-95759910bde3', '8 Faces, 12 Vertices, 6 Edges', false, 'a8bf067b-e42a-4a89-9259-865b696bd145');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7adad8af-7d35-4a81-943f-960cb01f40d4', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'Which 3D solid shape is formed when a right-angled triangle is rotated 360° continuously about one of its perpendicular legs?', 'Revolving a right triangle about an altitude leg sweeps out the circular base and conical apex of a cone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67bc2209-4e2e-4088-b406-16bf4eba8097', 'Right Circular Cone', true, '7adad8af-7d35-4a81-943f-960cb01f40d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28224d16-c8b7-4def-8d11-fb691edc70e6', 'Cylinder', false, '7adad8af-7d35-4a81-943f-960cb01f40d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ac2d009-c32e-4ce4-adc3-9fad3e9c3d8c', 'Sphere', false, '7adad8af-7d35-4a81-943f-960cb01f40d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff1061ed-ad14-4bb6-97c1-a869663faa13', 'Prism', false, '7adad8af-7d35-4a81-943f-960cb01f40d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb28a1f8-9aa8-4399-9bf7-9d56ec01d5ce', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'Consider a clock at 6:30. What is the angle between the hour hand and the minute hand?', 'At 6:30, minute hand is at 6 (180°), and hour hand is at 6.5 (195°). Angle = 195° - 180° = 15°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36ab7b29-bbcd-4c8f-bb35-b488a539968b', '15° (at 6:30, hour hand is halfway between 6 and 7: 30° / 2 = 15°)', true, 'bb28a1f8-9aa8-4399-9bf7-9d56ec01d5ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4ae2fa9-f7a1-40fd-8750-eedcdf64a6fa', '0°', false, 'bb28a1f8-9aa8-4399-9bf7-9d56ec01d5ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b194a14-ad51-490c-b113-4af4c7e3627c', '30°', false, 'bb28a1f8-9aa8-4399-9bf7-9d56ec01d5ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f028c57-9c04-41c5-b91c-1d9750855673', '45°', false, 'bb28a1f8-9aa8-4399-9bf7-9d56ec01d5ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20433992-562f-40c1-a2b8-bd9981945942', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'In which of the following quadrilaterals are the diagonals NOT necessarily equal in length?', 'In a rhombus and general parallelogram, one diagonal is longer (spanning obtuse angles) than the other.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40e9d9ee-9526-408a-9208-e73543c931b3', 'Rhombus and Parallelogram', true, '20433992-562f-40c1-a2b8-bd9981945942');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0d979a0-c849-405f-abea-ddc766cc965a', 'Square', false, '20433992-562f-40c1-a2b8-bd9981945942');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b94ccd90-aab1-4a2f-9bd7-0454339fc1d6', 'Rectangle', false, '20433992-562f-40c1-a2b8-bd9981945942');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae749db7-4e38-4a02-9ecc-4bd3229b4cd7', 'Isosceles Trapezium', false, '20433992-562f-40c1-a2b8-bd9981945942');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58c0aa37-e8fb-4e85-baa0-fa423dfbbd04', 'Class 6', 'Mathematics', 'Chapter 5: Understanding Elementary Shapes', 'Hard', 'What is the sum of all internal angles in a 6-sided Hexagon?', 'Formula S = (n - 2) × 180°; for n = 6: S = 4 × 180° = 720°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e29fc9c-b912-4f36-80cf-daaca12d4898', '720° ((n - 2) × 180° = (6 - 2) × 180° = 4 × 180°)', true, '58c0aa37-e8fb-4e85-baa0-fa423dfbbd04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d37efbff-d975-495e-821d-bc6383040342', '540°', false, '58c0aa37-e8fb-4e85-baa0-fa423dfbbd04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f5d85ec-4195-4675-82be-8e6675067787', '360°', false, '58c0aa37-e8fb-4e85-baa0-fa423dfbbd04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba92b7ab-7164-43a8-9ea2-ae930950f88b', '900°', false, '58c0aa37-e8fb-4e85-baa0-fa423dfbbd04');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aaafea99-a548-4329-a604-6cc67d9d3713', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'Who was the headmistress and founder of the innovative school visited by the author E.V. Lucas?', 'Miss Beam was a middle-aged, authoritative yet kind and understanding woman who ran the unique school.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8730f1f9-a9f8-40c7-a27e-382017beba65', 'Miss Beam', true, 'aaafea99-a548-4329-a604-6cc67d9d3713');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa15905c-e5c8-469c-990c-f2685f1c56e9', 'Miss Sullivan', false, 'aaafea99-a548-4329-a604-6cc67d9d3713');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc42ff55-8185-4b2c-8108-af1fa85f5133', 'Miss Mary', false, 'aaafea99-a548-4329-a604-6cc67d9d3713');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bedb0fbb-2bc3-4459-b35b-8a528389319a', 'Mrs. Smith', false, 'aaafea99-a548-4329-a604-6cc67d9d3713');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('54a0b275-9de1-4cab-b606-39b21122cec9', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'What was the real aim and core educational philosophy of Miss Beam''s school?', 'Miss Beam emphasized active empathy, compassion, and experiential understanding of others'' misfortunes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('657a258e-8ce0-42df-ab21-fd5e4d8fa87f', 'Not so much to teach thought, but thoughtfulness — kindness to others, empathy, and being responsible citizens', true, '54a0b275-9de1-4cab-b606-39b21122cec9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbe70465-41ef-4927-a635-2f02bda0ff08', 'To produce top rankers in mathematics only', false, '54a0b275-9de1-4cab-b606-39b21122cec9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a12aef7-26f4-4177-89aa-26f2e10128d6', 'To train professional athletes', false, '54a0b275-9de1-4cab-b606-39b21122cec9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f54a56e-5606-4f37-82c2-1875fe574b5d', 'To teach only ancient languages', false, '54a0b275-9de1-4cab-b606-39b21122cec9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e49037e4-5e4e-4384-b993-709ee61d5da4', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'What special experiential system was organized in Miss Beam''s school to make children appreciate and understand misfortune?', 'Each child lived through simulated disabilities so they developed genuine compassion for the disabled.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be74b281-fe0c-47f0-afbc-5e62a4bec2a9', 'Every child had one blind day, one lame day, one deaf day, one injured day, and one dumb day during each term', true, 'e49037e4-5e4e-4384-b993-709ee61d5da4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('debb5852-4474-4c08-bee3-82889d0e55dc', 'Students had to do all cleaning work', false, 'e49037e4-5e4e-4384-b993-709ee61d5da4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32158773-e109-4c5c-b9cb-84e83ff187fe', 'Students were sent to live in a forest', false, 'e49037e4-5e4e-4384-b993-709ee61d5da4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('954bba08-c80b-49b6-8e7f-347ef69efee7', 'Students were not allowed to eat food', false, 'e49037e4-5e4e-4384-b993-709ee61d5da4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf225ae1-3160-45cd-ad00-c70bd065a25c', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'What happened on a student''s ''Blind Day'' at Miss Beam''s school?', 'With bandaged eyes, the child experienced complete visual impairment, assisted by designated helpers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62fa63a0-0499-467b-ac81-a14d5863c36d', 'Their eyes were bandaged absolutely, and they promised on honor not to peep; another child was assigned to guide them', true, 'bf225ae1-3160-45cd-ad00-c70bd065a25c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9532889-c93c-478c-94fc-358e7693db28', 'They had to wear dark sunglasses', false, 'bf225ae1-3160-45cd-ad00-c70bd065a25c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30c64119-84f7-4b1c-8da2-29cd5f39d867', 'They stayed locked in a dark room', false, 'bf225ae1-3160-45cd-ad00-c70bd065a25c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8662d945-6f6b-4244-96b9-f6c30d1e11df', 'They were not allowed to walk', false, 'bf225ae1-3160-45cd-ad00-c70bd065a25c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5ec969d4-8090-4af0-a21b-04c4a301b70e', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'Which day did the little girl confess to the author was by far the MOST DIFFICULT and awful day?', 'The Blind Day was the hardest because one feared bumping into things constantly and felt helpless in the dark.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4032c1ff-26c8-445c-b80d-10dde718ad92', 'The Blind Day', true, '5ec969d4-8090-4af0-a21b-04c4a301b70e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ca194b1-910a-4666-855a-95e71bdf0f27', 'The Lame Day', false, '5ec969d4-8090-4af0-a21b-04c4a301b70e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0555c06-a60c-4003-b3c0-2d900d128484', 'The Deaf Day', false, '5ec969d4-8090-4af0-a21b-04c4a301b70e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02539792-be03-4ed4-878c-3c452ad428cd', 'The Dumb Day', false, '5ec969d4-8090-4af0-a21b-04c4a301b70e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47226169-98aa-446f-ac81-e406f362597c', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'Why was the ''Dumb Day'' also extremely challenging for young children?', 'Without physical mouth bindings, maintaining total silence tested the child''s internal discipline.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a964de5-7cfc-4fb3-b4bb-f34e9ec53b76', 'Because the mouth could not be bandaged, so the child had to rely entirely on pure willpower and self-control to remain silent', true, '47226169-98aa-446f-ac81-e406f362597c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66ea7d20-8117-4516-8d84-dd0c277e3ae6', 'Because they had to write 100 pages', false, '47226169-98aa-446f-ac81-e406f362597c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6433bf89-1850-4173-8db8-863cae12345e', 'Because they were not allowed to drink water', false, '47226169-98aa-446f-ac81-e406f362597c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('508a71e7-a968-4cc2-9bc0-2691bbc2325e', 'Because other children made jokes', false, '47226169-98aa-446f-ac81-e406f362597c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3bcc3e6-8bc0-4187-b14f-46e7a4079aed', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'In the supplementary story ''Tansen'', who was Tansen?', 'Tansen (originally Ramtanu Pandey) was India''s supreme classical musician in Akbar''s court.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97b32c1c-4d23-486a-aa82-a9a4b6ca0263', 'The greatest and most famous musical maestro of India, one of the Navaratnas in Emperor Akbar''s court', true, 'f3bcc3e6-8bc0-4187-b14f-46e7a4079aed');
