INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8db37405-544f-4236-82e9-fc016403b605', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'Where was Tansen born, as the only child of Mukandan Misra?', 'Tansen was born in Behat near Gwalior and studied music under the great master Swami Haridas.', NOW()) ON CONFLICT DO NOTHING;
