INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('467ace73-02b6-4ec5-91c7-54a39d054aa6', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'What naughty animal trick did young Tansen play in the forest when he met Swami Haridas and his disciples?', 'Young Tansen had mastered mimicking bird and beast sounds, flawlessly roaring like a tiger.', NOW()) ON CONFLICT DO NOTHING;
