INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da410b05-472f-4ec3-9a5f-429cbd9b67b4', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'For how many years did Tansen learn classical music under the tutelage of Swami Haridas?', 'Tansen spent eleven intensive years residing with Swami Haridas, mastering Hindustani classical ragas.', NOW()) ON CONFLICT DO NOTHING;
