INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4ec19e28-a1bf-42a7-bb1c-07d3f2b72b52', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'In which year did Tansen join the royal imperial court of Mughal Emperor Akbar?', 'Tansen entered Akbar''s court in 1556 and was elevated as one of the nine precious jewels (Navaratnas).', NOW()) ON CONFLICT DO NOTHING;
