INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d23639d-2476-441c-81a4-2c3e7c38ed5d', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Easy', 'In the poem ''Where Do All the Teachers Go?'' by Peter Dixon, what curious question does the child ponder?', 'The child''s innocent perspective wonders if authoritative teachers lead ordinary domestic lives at home.', NOW()) ON CONFLICT DO NOTHING;
