INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2dd1fce-7f31-49eb-b098-2549c72b967b', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'What transformation did the author E.V. Lucas feel inside himself when he walked around Miss Beam''s school with the blindfolded girl?', 'Guiding the visually impaired girl heightened the author''s descriptive attentiveness and empathetic awareness.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e39c5e4e-c561-4f54-a2ec-646c510267a1', 'He realized he had become ten times more thoughtful, observant, and sensitive to others than he ever thought possible', true, 'c2dd1fce-7f31-49eb-b098-2549c72b967b');
