INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f2995838-d533-4905-8476-810b5748585a', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'Who was ''Millie'' whom the author and the blindfolded girl observed in the garden?', 'The author described the tall girl walking in the garden, whom his companion identified as Millie, the Head Girl.', NOW()) ON CONFLICT DO NOTHING;
