INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c278a881-634e-47f2-8d6b-c80c96cf7e57', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'Who was ''Peter'' in Miss Beam''s school garden?', 'Peter was the aged, devoted gardener seen by the author tying up flowering rose stems.', NOW()) ON CONFLICT DO NOTHING;
