INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a665b1dd-3703-4acd-99ac-d681384f7152', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'Why did jealous courtiers in Akbar''s court (led by Shaukat Mian) conspire to demand that Tansen sing ''Raga Deepak''?', 'The conspirators sought Tansen''s destruction, knowing pure Raga Deepak''s incandescent heat would incinerate the performer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('816630cc-582e-44ce-911e-b60f24e5aeba', 'If sung with absolute perfection, Raga Deepak creates such intense thermal heat that it lights lamps and burns the singer to ashes', true, 'a665b1dd-3703-4acd-99ac-d681384f7152');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7305a04f-22da-4b3d-981a-13b28b921299', 'Because they wanted to dance', false, 'a665b1dd-3703-4acd-99ac-d681384f7152');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fe8b5db-0845-4d6b-94fe-040e730da566', 'Because Raga Deepak makes everyone fall asleep', false, 'a665b1dd-3703-4acd-99ac-d681384f7152');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b5810bc-63f2-47b0-a902-baaaeb8ff093', 'Because the Emperor was deaf', false, 'a665b1dd-3703-4acd-99ac-d681384f7152');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5ca3870c-cb3e-46c3-b549-9c559b9ec79b', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'How did Tansen brilliantly counter the lethal heat of Raga Deepak and save his life?', 'Tansen coordinated Raga Megh (rain raga) to trigger atmospheric precipitation the moment Raga Deepak sparked flames.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cff6cca-2c77-4d75-8991-b0be56da8d70', 'He trained his daughter Saraswati and her friend Rupvati to sing ''Raga Megh'' simultaneously, bringing torrents of cooling rain the moment the air grew hot and lamps lit up', true, '5ca3870c-cb3e-46c3-b549-9c559b9ec79b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('945bfb9e-4f41-4fda-9b0c-1ad846e72189', 'He poured cold water over himself while singing', false, '5ca3870c-cb3e-46c3-b549-9c559b9ec79b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb12ee4a-49bf-4eb0-8956-bfa80cc1e103', 'He refused to sing before Akbar', false, '5ca3870c-cb3e-46c3-b549-9c559b9ec79b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c288eb51-59fe-46f3-a8b3-8b4d0727eb2c', 'He fled to another country', false, '5ca3870c-cb3e-46c3-b549-9c559b9ec79b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64c84e98-2593-4528-a969-4b9d0342dc21', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'What happened when Tansen began singing Raga Deepak in Akbar''s court on the appointed day?', 'His acoustic harmonics manifested physical thermal phenomena, lighting the palace oil lamps.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e481ca8-7d50-4129-91f8-a4c754442822', 'The air grew intensely warm, audience perspired, leaves dried up on trees, birds fell dead, river boiled, and unlit lamps suddenly burst into flame', true, '64c84e98-2593-4528-a969-4b9d0342dc21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a13d3f3a-fd21-4e75-84f9-7bdb1648575a', 'Snow began falling in the hall', false, '64c84e98-2593-4528-a969-4b9d0342dc21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6787c19-3477-4655-a00b-aa63c0270a1f', 'The Emperor fell unconscious', false, '64c84e98-2593-4528-a969-4b9d0342dc21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f6cc485-7d56-43fe-b0d4-92f9f02c2274', 'The palace collapsed', false, '64c84e98-2593-4528-a969-4b9d0342dc21');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6125afc-14d4-4281-a6ff-fea2acebaff4', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'What did Emperor Akbar do when he discovered the malicious plot of the jealous courtiers against Tansen?', 'Akbar rejoiced in Tansen''s recovery from illness, severely penalizing the conspirators.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8777e8fa-ca4e-4f16-8a9a-c84003658734', 'He severely punished the wicked courtiers and rewarded Tansen with great honor and royal treasures', true, 'd6125afc-14d4-4281-a6ff-fea2acebaff4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c4ee4eb-aedb-4752-bef3-bff709d31421', 'He banned music in India', false, 'd6125afc-14d4-4281-a6ff-fea2acebaff4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b7769c3-c3bf-41ed-bc94-7ad74749c41e', 'He dismissed Tansen from court', false, 'd6125afc-14d4-4281-a6ff-fea2acebaff4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17edb39c-54e4-4aba-858d-538be8953095', 'He gave his crown to Tansen', false, 'd6125afc-14d4-4281-a6ff-fea2acebaff4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1e98936-03d7-40e2-b981-5f83112956a4', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'Where is the historic tomb of Tansen situated, revered as a place of pilgrimage for musicians?', 'Tansen''s tomb in Gwalior is a celebrated pilgrimage monument where an annual national music festival is hosted.', NOW()) ON CONFLICT DO NOTHING;
