INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c252fc20-b7eb-41dc-aef5-7fda1d9abc6f', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'What is the meaning of the word ''Thoughtfulness'' as used by Miss Beam?', 'Thoughtfulness transcends academic intellect to signify active empathy, social responsibility, and human kindness.', NOW()) ON CONFLICT DO NOTHING;
