INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fdf7f0d2-7320-4e69-9818-f6ea3c83fcdd', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'What was the rule for the other children assigned as ''Helpers'' to a blind child for the day?', 'Helpers developed acute observational and communication skills while experiencing the vital importance of assisting others.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ac59d4d-ad99-4848-a8fc-05626b35d6c9', 'They had to guide them around everywhere and explain the world to them, learning as much about empathy as the blind child', true, 'fdf7f0d2-7320-4e69-9818-f6ea3c83fcdd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2ed0993-ed1c-47d6-9064-bc881c114717', 'They had to carry the blind child on their shoulders', false, 'fdf7f0d2-7320-4e69-9818-f6ea3c83fcdd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4442aef9-1c14-4883-830d-ea6b96109ba7', 'They had to do all their homework', false, 'fdf7f0d2-7320-4e69-9818-f6ea3c83fcdd');
