INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17539443-b995-4d29-b424-0eea60b8665e', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'What did the poet Peter Dixon plan to do one day to solve the mystery of teachers?', 'The speaker schemes to follow a teacher home after school and compose a poem revealing their ordinary domestic life.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a1f1024-43aa-4486-90ad-c3159fee69ae', 'Follow one teacher home all the way after school to see what they do, and write a poem about it for other children to read', true, '17539443-b995-4d29-b424-0eea60b8665e');
