INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cfbda6f3-f295-4598-a099-0aa80aed37e5', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'What does the word ''Peep'' mean in: ''They promise on their honour not to peep''?', '''Peep'' means to take a quick, illicit, surreptitious glance.', NOW()) ON CONFLICT DO NOTHING;
