INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14183ead-c2da-4e13-a01b-bd889d388b98', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'Who was Mohammad Ghaus in Tansen''s musical life?', 'Mohammad Ghaus was a venerated Sufi mystic who fostered Tansen''s early musical and spiritual genius in Gwalior.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d0d0a2e-d6bc-4b13-ba8f-719008106587', 'A holy Sufi saint of Gwalior with whom Tansen lived and received deep spiritual and musical blessings', true, '14183ead-c2da-4e13-a01b-bd889d388b98');
