INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bc98f035-10b6-4f89-bfea-e6fc627075b5', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'Whom did Tansen marry from the court of Rani Mrignayani of Gwalior?', 'Tansen married Hussaini, a talented court singer from Rani Mrignayani''s entourage.', NOW()) ON CONFLICT DO NOTHING;
