INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62bd538c-ce67-48f6-b457-6f82cf3cd2b8', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Medium', 'What is the overarching educational message of ''A Different Kind of School''?', 'The narrative emphasizes that moral character and active humanitarian empathy represent the highest aims of pedagogy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6975e5e8-6bf4-47fb-bc31-522bfc5f482f', 'True education must cultivate emotional intelligence, empathetic social consciousness, and mutual care rather than mere mechanical rote learning', true, '62bd538c-ce67-48f6-b457-6f82cf3cd2b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d2d5d2f-ef9d-46c3-aa21-f45a1a616029', 'Children should never go to school', false, '62bd538c-ce67-48f6-b457-6f82cf3cd2b8');
