INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('660b1c54-3332-47c5-85df-23e8ed384728', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Hard', 'In ''Tansen'', how did the musical duel between Raga Deepak and Raga Megh symbolize the cosmic balance of classical Indian music?', 'Classical Indian music theory holds that ragas evoke elemental resonances (Agni vs Varuna) in cosmic equilibrium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec3ab52d-bc0a-43ca-a4fe-9d9da16ff4ea', 'It demonstrated that acoustic vibrations correspond to fundamental cosmic forces (Fire/Agni and Water/Varuna) that must remain harmoniously balanced', true, '660b1c54-3332-47c5-85df-23e8ed384728');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4c91776-5dc9-4290-a5f6-aa87eb89ef49', 'It proved that singing was louder than drums', false, '660b1c54-3332-47c5-85df-23e8ed384728');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d47293b-9c9f-4537-ad45-a0e00ea46fa2', 'It showed that kings can control weather', false, '660b1c54-3332-47c5-85df-23e8ed384728');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('973bb93d-7b4b-46a2-bb9e-f6f271060dc9', 'It proved that courtiers were better singers', false, '660b1c54-3332-47c5-85df-23e8ed384728');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f381cdb-80fa-4d45-8172-879135bd2e24', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Hard', 'Match the following disabilities with the specific challenges described by the children in Miss Beam''s school:
(a) Blind Day   -> (i) Constant fear of being hit by unseen obstacles
(b) Lame Day    -> (ii) Having one leg tied up and hopping on crutches (fun for some)
(c) Injured Day -> (iii) Having an arm tied up so one cannot eat or dress alone
(d) Dumb Day    -> (iv) Constant test of internal willpower to prevent speaking', 'Blind = fear of collisions; Lame = crutch hopping; Injured = tied arm; Dumb = willpower silence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a43df0c4-254c-4889-b542-15978d67e3db', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '2f381cdb-80fa-4d45-8172-879135bd2e24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f6b75dc-8fc2-45b1-9403-84dc2f668fff', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '2f381cdb-80fa-4d45-8172-879135bd2e24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d055870-c430-4288-bbd5-6763410e514f', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '2f381cdb-80fa-4d45-8172-879135bd2e24');
