INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eb14eb3d-d827-4b00-aa4a-0e0deb9e4bd1', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Hard', 'Identify the figure of speech used in the line: ''The leaves dried up and fell to the ground, the rivers boiled, and unlit lamps burst into flame.''', 'Hyperbolic legendary imagery depicts the supernatural intensity of Tansen''s perfect raga.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('824dd8b4-2c98-44ac-b0c9-735a813a3922', 'Hyperbole (poetic deliberate exaggeration for dramatic acoustic impact)', true, 'eb14eb3d-d827-4b00-aa4a-0e0deb9e4bd1');
