INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd0b6ceb-74c7-41d6-9f04-c5e1988e4bb0', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Hard', 'What does the word ''Mischief'' or ''Mischievous'' mean when describing young Tansen in the forest?', 'Mischief refers to playful, harmless pranks driven by childhood curiosity and high spirits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd7d045f-bc78-4cdb-9661-0ae28b551a86', 'Playfully troublesome, full of tricks, but without intending malicious harm', true, 'cd0b6ceb-74c7-41d6-9f04-c5e1988e4bb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cba4753-6d6f-4ae7-93e7-35f06a14bf32', 'Evil and criminal', false, 'cd0b6ceb-74c7-41d6-9f04-c5e1988e4bb0');
