INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35d947c7-92d3-4846-8cf4-3c22911080ea', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Hard', 'In ''Where Do All the Teachers Go?'', what poetic perspective does Peter Dixon capture?', 'The poem explores the innocent cognitive duality where children view teachers as flawless, mythical entities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33dd2592-8fd3-4232-9683-6fdb99195698', 'The innocent childhood wonder that perceives adult authority figures as supernatural beings devoid of mundane domestic routines', true, '35d947c7-92d3-4846-8cf4-3c22911080ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18a7eb1a-547a-443b-b14b-3341fb81f782', 'An adult''s complaint about school fees', false, '35d947c7-92d3-4846-8cf4-3c22911080ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47b221fc-708f-4096-b535-3be757d095df', 'A teacher''s daily diary', false, '35d947c7-92d3-4846-8cf4-3c22911080ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e01e41a6-b1b5-4616-8f65-7237fa26e1fb', 'A historical report on education', false, '35d947c7-92d3-4846-8cf4-3c22911080ea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99af817a-84c6-439d-a67e-c59e606430f9', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Hard', 'Why did the little blindfolded girl describe her guiding experience as ''making her realize so many things she never thought of before''?', 'Sensory deprivation stimulates acute neuro-auditory perception and profound cognitive re-evaluation of the environment.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74c5b140-7f8e-42c3-915d-fe82e0a2ae75', 'Because when one cannot see, other senses (hearing, spatial touch, imagination) sharpen intensely to perceive subtle realities', true, '99af817a-84c6-439d-a67e-c59e606430f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a45c808-0bce-414b-b149-6c2ef2b56f51', 'Because she was told to memorize a book', false, '99af817a-84c6-439d-a67e-c59e606430f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffb4f524-b045-4735-b5cd-857d567b7f73', 'Because the author bought her ice cream', false, '99af817a-84c6-439d-a67e-c59e606430f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbf5d80b-0d98-4f9f-813c-1acc6e6b12ca', 'Because she wanted to win a prize', false, '99af817a-84c6-439d-a67e-c59e606430f9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2be66b4c-77d7-4382-9d54-8f2f4d7a0001', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Hard', 'Choose the grammatically correct transformation from Active to Passive Voice:
