INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8adc538b-e53b-434c-a290-fd836f6594d7', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Hard', 'What is the synonym of ''Wretched'' as used when the girl describes how she felt about the plight of the disabled?', '''Wretched'' denotes a profound state of emotional sorrow, misery, or deep distress.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e7aec3e-ea87-4b95-b913-36b69cf9c05c', 'Deeply distressed, miserable, or heartbroken with sympathy', true, '8adc538b-e53b-434c-a290-fd836f6594d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc353b9c-85db-4f7d-8019-8cdb0569d08d', 'Overjoyed and laughing', false, '8adc538b-e53b-434c-a290-fd836f6594d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('919033f7-5f94-46ce-9e94-81924dd537b8', 'Extremely wealthy', false, '8adc538b-e53b-434c-a290-fd836f6594d7');
