INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6eea01f9-d014-48f0-97ab-5fbe5fdcd2fe', 'Class 6', 'English', 'Chapter 5: A Different Kind of School', 'Hard', 'What philosophical synthesis unites both stories in Chapter 5 (''A Different Kind of School'' and ''Tansen'')?', 'Both classic texts elevate human excellence: ethical empathy in pedagogical training and transcendental devotion in classical art.', NOW()) ON CONFLICT DO NOTHING;
