INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a48ea77f-157e-4061-be39-208b75a58424', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Medium', 'Which mountain range separates the continents of Asia and Europe on the west?', 'The Ural Mountains and Ural River in Russia form the conventional geographic boundary dividing Europe from Asia (together termed ''Eurasia'').', NOW()) ON CONFLICT DO NOTHING;
