INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e67e13e7-3f3f-48a3-bfd0-e06a50691a9e', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Medium', 'What are the FIVE vertical layers of the Earth''s atmosphere arranged starting from the Earth''s surface upwards?', 'Thermal atmospheric stratification: Troposphere (0-12 km), Stratosphere (12-50 km), Mesosphere (50-80 km), Thermosphere (80-700 km), and Exosphere (>700 km).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44970460-643f-49f5-bc9b-1d2f09eb557b', 'Troposphere -> Stratosphere -> Mesosphere -> Thermosphere -> Exosphere', true, 'e67e13e7-3f3f-48a3-bfd0-e06a50691a9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f547fd3d-a2f8-413a-b079-b31d1397d40f', 'Stratosphere -> Troposphere -> Mesosphere -> Exosphere -> Thermosphere', false, 'e67e13e7-3f3f-48a3-bfd0-e06a50691a9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b088832-86a3-4241-bfa4-35158d41506c', 'Exosphere -> Thermosphere -> Mesosphere -> Stratosphere -> Troposphere', false, 'e67e13e7-3f3f-48a3-bfd0-e06a50691a9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('114c239c-21ae-48cf-bc09-224976ff0dde', 'Troposphere -> Mesosphere -> Stratosphere -> Thermosphere -> Ionosphere', false, 'e67e13e7-3f3f-48a3-bfd0-e06a50691a9e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d721adc4-b377-49e4-85d0-f5d8dabab7b2', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Medium', 'Why is Earth uniquely called the ''Blue Planet'' and the ''Water Planet''?', 'Rayleigh scattering of solar light across oceans covering 71% of Earth''s surface yields our planetary blue hue.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d94dffbf-6d05-4d13-902f-9d0ffb60c911', 'More than 71% of Earth''s surface is covered with water, giving it a brilliant azure-blue appearance from outer space', true, 'd721adc4-b377-49e4-85d0-f5d8dabab7b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac07e890-6f28-4eb3-b619-2ac3b057ab9d', 'Because the sky reflects blue paint', false, 'd721adc4-b377-49e4-85d0-f5d8dabab7b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fde1100-11bb-4b92-8588-464a9623338e', 'Because mountains are blue', false, 'd721adc4-b377-49e4-85d0-f5d8dabab7b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e992024-5044-49bb-bc3d-592f67df049d', 'Because trees are blue in space', false, 'd721adc4-b377-49e4-85d0-f5d8dabab7b2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('05dc9e6c-6359-4051-9c41-149a58a0695b', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Medium', 'Despite Earth having 71% water, why do humans and land ecosystems face acute freshwater shortages?', 'Only ~0.3% of global water is accessible liquid freshwater in rivers, freshwater lakes, and shallow aquifers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68a45c8f-32a9-4d62-8714-e6a788ca8188', 'More than 97% of Earth''s water is saline seawater in oceans, and of the remaining 3% freshwater, most is locked in polar ice sheets and glaciers', true, '05dc9e6c-6359-4051-9c41-149a58a0695b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c13631de-3f0f-4b19-8a40-e000980dd666', 'Because water evaporates into outer space', false, '05dc9e6c-6359-4051-9c41-149a58a0695b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb648bc8-36fb-4fb6-abc5-75b29fad73d0', 'Because clouds take water away', false, '05dc9e6c-6359-4051-9c41-149a58a0695b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7ccc089-a276-4456-a3d4-09d0da3c15d0', 'Because rivers do not flow', false, '05dc9e6c-6359-4051-9c41-149a58a0695b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('42761638-61d1-4153-9f69-d4e384a96b49', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Medium', 'What is the crucial biological role of Carbon Dioxide (CO₂) in the atmosphere, despite its small concentration (0.03%)?', 'Radiative greenhouse forcing by CO₂ maintains Earth''s mean surface temperature at +15°C instead of a freezing -18°C.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d44179b9-fbbb-467c-8fcd-91444ddef4c7', 'It absorbs infrared heat radiated by the Earth (Greenhouse effect) to keep the planet comfortably warm and livable, and plants use it for photosynthesis', true, '42761638-61d1-4153-9f69-d4e384a96b49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df3eee1b-7d44-46c2-8463-c7028b59de4e', 'It freezes the oceans', false, '42761638-61d1-4153-9f69-d4e384a96b49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f82dec6-538f-48b9-be51-62e897ec7dc4', 'It produces rain directly', false, '42761638-61d1-4153-9f69-d4e384a96b49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e613bcb3-d539-4f91-9ac2-77e57e17c142', 'It makes rocks hard', false, '42761638-61d1-4153-9f69-d4e384a96b49');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59b49ed3-46d2-43f1-adc2-a0b0d75fc57b', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Medium', 'Why does atmospheric density and air pressure decrease rapidly with increasing altitude as mountaineers climb high Himalayan peaks?', 'Barometric hypsometric formula: atmospheric pressure drops exponentially with height, reducing the partial pressure of oxygen.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('920cb72f-afbe-4399-9cf4-36fb38a3b635', 'Earth''s gravitational attraction compresses air molecules near sea level; at high altitudes, air molecules spread apart, causing lower oxygen pressure and breathing difficulty', true, '59b49ed3-46d2-43f1-adc2-a0b0d75fc57b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f2b19e4-1630-4cf3-8ce1-39fcb9446444', 'Air is blown away by satellites', false, '59b49ed3-46d2-43f1-adc2-a0b0d75fc57b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43919a6a-d492-467d-bfa0-0b88feec01ab', 'Sunlight destroys air at high altitude', false, '59b49ed3-46d2-43f1-adc2-a0b0d75fc57b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c058506-f775-441d-8bf9-3e5d77a65942', 'Clouds push air down', false, '59b49ed3-46d2-43f1-adc2-a0b0d75fc57b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a437293a-0978-4087-a3ad-cb67ce2d373e', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ffb61da-8cf4-4402-9229-4eafeecba378', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'a437293a-0978-4087-a3ad-cb67ce2d373e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('401116f1-cf8b-4425-8f9b-5922d3b2293e', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'a437293a-0978-4087-a3ad-cb67ce2d373e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('281415d6-c561-4cac-8974-ca2043d8852b', '(A) is true, but (R) is false.', false, 'a437293a-0978-4087-a3ad-cb67ce2d373e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11150289-764e-41d6-b7ca-1de169f0c0b1', '(A) is false, but (R) is true.', false, 'a437293a-0978-4087-a3ad-cb67ce2d373e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a1aa37c9-d74e-4f6a-a980-8f244e6e7d83', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Spot the IMPOSTER in the following group of geographic features paired with their home Continents:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9041315c-a997-4601-b09d-838f93d3e7db', 'Nile River - Africa', false, 'a1aa37c9-d74e-4f6a-a980-8f244e6e7d83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b44a9e7a-873f-40c3-b556-3f18e7ca87d6', 'Amazon River - South America', false, 'a1aa37c9-d74e-4f6a-a980-8f244e6e7d83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75eafcc6-7b37-4a07-bef1-d85684ef66dc', 'Mount Everest - Asia', false, 'a1aa37c9-d74e-4f6a-a980-8f244e6e7d83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('485c838d-9fea-48b4-bee9-fbff28ea541b', 'Andes Mountain Range - North America', true, 'a1aa37c9-d74e-4f6a-a980-8f244e6e7d83');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46d1cd67-0f11-45d3-94f2-e0a89cbb2e26', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Who were the first mountaineers to conquer and step onto the highest summit of Mount Everest on 29th May 1953?', 'Edmund Hillary and Tenzing Norgay achieved the historic first confirmed ascent of Mount Everest in the 1953 British expedition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48a3815f-d616-4d96-aef5-bc6cf04d37e9', 'Sir Edmund Hillary (New Zealand) and Tenzing Norgay Sherpa (India/Nepal)', true, '46d1cd67-0f11-45d3-94f2-e0a89cbb2e26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b4fd7df-960b-47a5-964c-90c0f0a676dc', 'George Mallory and Andrew Irvine', false, '46d1cd67-0f11-45d3-94f2-e0a89cbb2e26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bd6c77f-36a3-4b7e-8bc9-2052b4c9ffa5', 'Bachendri Pal and Junko Tabei', false, '46d1cd67-0f11-45d3-94f2-e0a89cbb2e26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fff1b7f-c21b-4804-ae6b-8faf41a14228', 'Reinhold Messner and Peter Habeler', false, '46d1cd67-0f11-45d3-94f2-e0a89cbb2e26');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b1cebea7-012c-416c-b7c1-858d74ebafdd', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Match Column I (Earth Domains & Features) with Column II (Definitions & Examples):
(a) Lithosphere -> (i) Gaseous envelope held by gravity
(b) Hydrosphere -> (ii) Solid rock crust and continental landmasses
(c) Atmosphere  -> (iii) 71% planetary ocean and surface water realm
(d) Biosphere   -> (iv) Narrow zone of contact supporting all living organisms', 'Lithosphere = rock crust; Hydrosphere = 71% water; Atmosphere = gas envelope; Biosphere = life zone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f959c8db-01d7-4197-a5aa-fd2b76305208', 'a-(ii), b-(iii), c-(i), d-(iv)', true, 'b1cebea7-012c-416c-b7c1-858d74ebafdd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1bdb08c-c900-4f1f-84c4-a1e91436ea3a', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'b1cebea7-012c-416c-b7c1-858d74ebafdd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd3ca8a4-3fd0-4e7f-97bd-a08b8c63c29a', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'b1cebea7-012c-416c-b7c1-858d74ebafdd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a852dab3-ef8a-4ee6-b053-7de04c36b74d', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'b1cebea7-012c-416c-b7c1-858d74ebafdd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3042060-3061-4128-a6c4-d18c5726ecc2', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Read the statements regarding the continents:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3f17088-618e-4f16-9f5c-78c27b118fb0', 'Statements 1 and 3 only', true, 'f3042060-3061-4128-a6c4-d18c5726ecc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c879023-a808-4a18-a282-ad88fc32ccb8', 'Statements 1 and 2 only', false, 'f3042060-3061-4128-a6c4-d18c5726ecc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3852bfeb-f048-4bc3-b56c-0945055ae3aa', 'Statements 2 and 3 only', false, 'f3042060-3061-4128-a6c4-d18c5726ecc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('363eecc5-1b9a-4ce3-85ac-af17b0d399a3', 'All Statements 1, 2, and 3', false, 'f3042060-3061-4128-a6c4-d18c5726ecc2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('870f5774-8941-47d4-a221-a238091806a4', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'What is the oceanic body surrounding the continent of Antarctica, formed by the southward extension of the Pacific, Atlantic, and Indian Oceans?', 'The Southern Ocean encompasses the circumpolar Antarctic waters south of 60° S, connected by the Antarctic Circumpolar Current.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('baf143df-fcdd-42b5-be35-197708a7bb65', 'The Southern Ocean (or Antarctic Ocean, extending up to 60° S latitude)', true, '870f5774-8941-47d4-a221-a238091806a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2f471fc-9568-4949-98d3-e90d2804f9b9', 'Arctic Ocean', false, '870f5774-8941-47d4-a221-a238091806a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc8d805a-90b8-451a-8373-4c744f27e69b', 'Indian Ocean', false, '870f5774-8941-47d4-a221-a238091806a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2f1d150-a8fd-4194-b732-469a41bac21c', 'Mediterranean Sea', false, '870f5774-8941-47d4-a221-a238091806a4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb3a5903-fa4e-449e-a58c-99485c94910c', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Which narrow strait connects the Arctic Ocean with the Pacific Ocean between Alaska (USA) and Siberia (Russia)?', 'The Bering Strait connects the Arctic Chukchi Sea with the Pacific Bering Sea across an 82 km maritime passage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7227f890-e48d-471b-89fb-ccfc16670dae', 'Bering Strait', true, 'cb3a5903-fa4e-449e-a58c-99485c94910c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('841bb473-f887-4975-8fe5-9135099eba29', 'Strait of Gibraltar', false, 'cb3a5903-fa4e-449e-a58c-99485c94910c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0730ef1-52ff-41ea-bbcc-f49077e8f940', 'Palk Strait', false, 'cb3a5903-fa4e-449e-a58c-99485c94910c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('549052c6-583f-4bb7-88ff-3f05ed18cd4c', 'Strait of Malacca', false, 'cb3a5903-fa4e-449e-a58c-99485c94910c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f44645c7-401f-4045-babe-bad8c97364f1', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Why is the elevation of any land point on Earth always measured from Sea Level, and why is Sea Level taken as zero everywhere?', 'Hydrostatic communicability ensures the global marine surface conforms to an equipotential gravitational geoid serving as the datum (0 m elevation).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58a55655-cec4-4212-ae7b-a820a43f1a70', 'All the interconnected oceans of the world maintain a uniform, continuous hydrostatic surface level at equilibrium (Mean Sea Level = 0 m)', true, 'f44645c7-401f-4045-babe-bad8c97364f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80702cf5-cad5-4389-8540-a2311f5fee9f', 'Because oceans have no weight', false, 'f44645c7-401f-4045-babe-bad8c97364f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef7a5005-9f49-4eef-b0bc-c27d3fccc129', 'Because sea water cannot be measured', false, 'f44645c7-401f-4045-babe-bad8c97364f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8ea8859-2704-425f-809d-bfcedb13c1cf', 'Because land sinks every year', false, 'f44645c7-401f-4045-babe-bad8c97364f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea614556-b40b-451a-b6f3-8995c38f4a4c', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Consider four atmospheric gases:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8eebab41-932a-41ed-96a9-39d79712796b', '1 -> 2 -> 3 -> 4', true, 'ea614556-b40b-451a-b6f3-8995c38f4a4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffb787c8-1b65-435a-82b6-6bdbaf5970d8', '2 -> 1 -> 4 -> 3', false, 'ea614556-b40b-451a-b6f3-8995c38f4a4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('278d29a8-6794-4cb7-9d3b-9abc0c93afdb', '1 -> 2 -> 4 -> 3', false, 'ea614556-b40b-451a-b6f3-8995c38f4a4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9440417d-fabe-4b2e-8c9b-ccdc043819b2', '4 -> 3 -> 2 -> 1', false, 'ea614556-b40b-451a-b6f3-8995c38f4a4c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f47920bf-f9dd-4e7f-9011-2286696a730e', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'What is the combined landmass consisting of Europe and Asia joined together without any oceanic separation called?', 'Europe and Asia form a single contiguous tectonic landmass termed Eurasia, demarcated geographically by the Ural Mountains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7395bee-a04a-45ec-99c3-48b66421f562', 'Eurasia', true, 'f47920bf-f9dd-4e7f-9011-2286696a730e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34245043-cdb6-404a-adec-2ed7eba7713d', 'Afro-Eurasia', false, 'f47920bf-f9dd-4e7f-9011-2286696a730e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccd7363c-943a-47fc-b703-5b2e26f1a8c3', 'Pangaea', false, 'f47920bf-f9dd-4e7f-9011-2286696a730e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0138c6f-3548-4e0b-93bc-570bc6a54b7d', 'Gondwanaland', false, 'f47920bf-f9dd-4e7f-9011-2286696a730e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2be45b2-d5f9-4b61-a1fd-000e64c32bfa', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Who was the FIRST Indian woman to climb the summit of Mount Everest on 23rd May 1984?', 'Bachendri Pal became the first Indian woman and fifth woman in the world to reach the peak of Mount Everest in 1984.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73459f67-9564-47c3-b1ee-94d9fd5c23ac', 'Bachendri Pal', true, 'b2be45b2-d5f9-4b61-a1fd-000e64c32bfa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f8248c4-3ad9-4822-a1d1-835c1a88b0ae', 'Santosh Yadav', false, 'b2be45b2-d5f9-4b61-a1fd-000e64c32bfa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29a0080b-4b9e-4444-ac86-81573bdebff7', 'Arunima Sinha', false, 'b2be45b2-d5f9-4b61-a1fd-000e64c32bfa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fb55682-b447-4856-84ce-8e62da04ff0c', 'Premlata Agarwal', false, 'b2be45b2-d5f9-4b61-a1fd-000e64c32bfa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('de8bdc80-89da-41e7-a618-5538d38da3d0', 'Class 6', 'Social Science', 'Chapter 5: Major Domains of the Earth', 'Hard', 'Why is human disturbance in one domain of the Earth (e.g. cutting forests in the Lithosphere or emitting gases into Atmosphere) directly detrimental to all other domains?', 'Earth Systems Science shows complex feedback loops (carbon cycle, hydrologic cycle) link all spheres into a single interdependent ecosystem.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69433b8e-368b-4f67-9d15-5f2b9b9310dd', 'All four domains (Lithosphere, Hydrosphere, Atmosphere, Biosphere) are dynamically interconnected in continuous thermodynamic and biogeochemical nutrient cycles', true, 'de8bdc80-89da-41e7-a618-5538d38da3d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f79a128-08e2-400e-9105-15f6d8efdd38', 'Because Earth is made of glass', false, 'de8bdc80-89da-41e7-a618-5538d38da3d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ef7e9ef-8273-4631-91fa-b4da71e3b4ac', 'Because oceans will dry up in one second', false, 'de8bdc80-89da-41e7-a618-5538d38da3d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('861c0019-06c2-43e7-a563-7970cd912fb4', 'Because gravity will stop working', false, 'de8bdc80-89da-41e7-a618-5538d38da3d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb7ff885-b606-47d8-b777-e3fb39f5e033', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'संज्ञा शब्द के जिस रूप से उसके पुरुष जाति (नर) या स्त्री जाति (मादा) होने का बोध होता है, उसे व्याकरण में क्या कहते हैं?', 'संज्ञा के जाति-निर्धारक रूप (पुरुष या स्त्री जाति के बोधक चिह्न) को ''लिंग'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fb85f3d-1f42-492c-99a0-177edb336cf7', 'लिंग (Gender)', true, 'cb7ff885-b606-47d8-b777-e3fb39f5e033');
