INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89046737-56d3-49b8-b272-105e88192808', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'हिंदी भाषा में मुख्य रूप से लिंग के कितने भेद (प्रकार) होते हैं?', 'हिंदी में केवल दो लिंग होते हैं: 1. पुल्लिंग (Masculine) तथा 2. स्त्रीलिंग (Feminine)। (संस्कृत की तरह नपुंसक लिंग हिंदी में नहीं होता)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44ec6c98-a26e-4708-8641-0ca15d5da336', 'दो भेद (पुल्लिंग और स्त्रीलिंग)', true, '89046737-56d3-49b8-b272-105e88192808');
