INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2dc63170-2a3e-4ba8-b32a-abd904a6011b', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'जिन संज्ञा शब्दों से पुरुष जाति (Male) का बोध होता है, उन्हें क्या कहते हैं?', 'पुरुषत्व का बोध कराने वाले संज्ञा शब्द पुल्लिंग कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
