INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dbf71abb-4154-42f9-85c0-54b8da4ea824', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'जिन संज्ञा शब्दों से स्त्री जाति (Female) का बोध होता है, उन्हें क्या कहते हैं?', 'स्त्रीत्व का बोध कराने वाले संज्ञा शब्द स्त्रीलिंग कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
