INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17196f93-ec43-45b9-a410-d7e59c4db827', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'निम्नलिखित में से ''पुल्लिंग'' शब्द का सही उदाहरण कौन-सा है?', 'पर्वतों के नाम (हिमालय), देशों के नाम (भारत), दिनों के नाम (सोमवार), तथा धातुओं के नाम (लोहा) सदैव पुल्लिंग होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c60dddcf-964c-406d-bea0-3915b730c3fe', 'हिमालय, भारत, सोमवार, लोहा', true, '17196f93-ec43-45b9-a410-d7e59c4db827');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('102b9ee3-26f8-4468-804d-39fa77a9d747', 'गंगा, यमुना, रोटी, तितली', false, '17196f93-ec43-45b9-a410-d7e59c4db827');
