INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f19fc38-c484-41d0-a731-64e5198d8056', 'पुस्तक, माला, चिड़िया, लता', false, '17196f93-ec43-45b9-a410-d7e59c4db827');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5a067394-51cc-4e42-b058-a1bf0ae30863', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'निम्नलिखित में से ''स्त्रीलिंग'' शब्द का सही उदाहरण कौन-सा है?', 'नदियों के नाम (गंगा), भाषाओं के नाम (हिंदी), लिपियों के नाम (देवनागरी), तथा तिथियों के नाम स्त्रीलिंग होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e61daf40-15ed-4fe7-b44d-c74a840379b3', 'गंगा, हिंदी, देवनागरी, पूर्णिमा', true, '5a067394-51cc-4e42-b058-a1bf0ae30863');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f97ed609-b4de-42ba-8166-28e55846f169', 'समुद्र, प्रशांत, आम, सोना', false, '5a067394-51cc-4e42-b058-a1bf0ae30863');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23c06ff1-7605-4ad2-bc4d-255bff3885cb', 'पेड़, जंगल, शहर, गाँव', false, '5a067394-51cc-4e42-b058-a1bf0ae30863');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ea1283a-b9c9-46e3-bd56-735a3eee607b', 'दूध, पानी, तेल, घी', false, '5a067394-51cc-4e42-b058-a1bf0ae30863');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d0d14c6-7505-48d7-8021-b2351b2b097d', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'पुल्लिंग शब्द ''कवि'' का सही स्त्रीलिंग रूप क्या है?', '''कवि'' का मानक शुद्ध स्त्रीलिंग वर्तनी रूप ''कवयित्री'' (क + व + यि + त्री) है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68528b33-d9be-4bc1-ae90-db5f7b69ab95', 'कवयित्री', true, '2d0d14c6-7505-48d7-8021-b2351b2b097d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab0e3f42-0721-4fce-9898-a0f72f011d8f', 'कवियत्री', false, '2d0d14c6-7505-48d7-8021-b2351b2b097d');
