INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('85f64ecd-649d-46c7-b65b-3e3d4b41c44b', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'पुल्लिंग शब्द ''विद्वान'' का सही स्त्रीलिंग रूप क्या है?', '''विद्वान'' (ज्ञानवान पुरुष) का शुद्ध स्त्रीलिंग ''विदुषी'' (ज्ञानवती स्त्री) होता है।', NOW()) ON CONFLICT DO NOTHING;
