INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6893607-4e4c-4ebf-bbd5-56e12f86c78b', 'ज्ञानी', false, '85f64ecd-649d-46c7-b65b-3e3d4b41c44b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7c72808e-7401-488f-b4e7-a20e82b25b7a', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'पुल्लिंग शब्द ''सम्राट'' का सही स्त्रीलिंग रूप क्या है?', 'संस्कृत तत्सम नियम के अनुसार ''सम्राट'' का स्त्रीलिंग ''सम्राज्ञी'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5032a927-99aa-4291-b89a-0e76b2133314', 'सम्राज्ञी', true, '7c72808e-7401-488f-b4e7-a20e82b25b7a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0484148-d8ed-4e02-9ff6-7d47ae6a17d8', 'सम्राटिनी', false, '7c72808e-7401-488f-b4e7-a20e82b25b7a');
