INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23551931-ea9d-4ea9-be2e-2c44865b476b', 'रानी', false, '7c72808e-7401-488f-b4e7-a20e82b25b7a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc4e06c5-38a9-410b-b0c6-785be8062528', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'पुल्लिंग शब्द ''नेता'' और ''अभिनेता'' के सही स्त्रीलिंग रूप क्रमशः क्या हैं?', '''ता'' का ''त्री'' में परिवर्तन: नेता -> नेत्री; अभिनेता -> अभिनेत्री; धाता -> धात्री।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd9b13bc-78ff-4cbd-ab58-a2540fe0c295', 'नेत्री और अभिनेत्री', true, 'cc4e06c5-38a9-410b-b0c6-785be8062528');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b611107-8757-4d61-be41-dfff3d9c43c5', 'नेतिन और अभिनेतिन', false, 'cc4e06c5-38a9-410b-b0c6-785be8062528');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fec026c8-d439-4f90-b966-16423ece5890', 'नेताइन और अभिनेत्र', false, 'cc4e06c5-38a9-410b-b0c6-785be8062528');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89b37b40-fed6-40dc-bb8b-13999f6a266c', 'नेती और अभिनेती', false, 'cc4e06c5-38a9-410b-b0c6-785be8062528');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa32d59d-3874-4347-837f-3a553d6126dd', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'पुल्लिंग शब्द ''वर'' और ''साधु'' के सही स्त्रीलिंग रूप क्रमशः क्या हैं?', 'वर का स्त्रीलिंग ''वधू'' तथा साधु का स्त्रीलिंग ''साध्वी'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15715fa7-e181-40e6-aeff-ecbc3b4b909a', 'वधू और साध्वी', true, 'fa32d59d-3874-4347-837f-3a553d6126dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('151e7e05-c85c-491a-9b65-e5426ce3636f', 'वधु और साधुनी', false, 'fa32d59d-3874-4347-837f-3a553d6126dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ef49e2d-d165-41cb-9eed-c98e3ca3bcf9', 'पत्नी और सन्यासिनी', false, 'fa32d59d-3874-4347-837f-3a553d6126dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61915e1c-4cfc-4257-9309-8a074dffd174', 'दुल्हन और औरत', false, 'fa32d59d-3874-4347-837f-3a553d6126dd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b90a4201-eef4-45ce-84b6-f8761c6b9c22', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Easy', 'पुल्लिंग शब्द ''बैल'' और ''पुरुष'' के सही स्त्रीलिंग रूप क्रमशः क्या हैं?', 'भिन्न रूप वाले स्वतंत्र युग्म: बैल -> गाय; पुरुष -> स्त्री; पिता -> माता; भाई -> बहन।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('081e85ce-1e07-49b7-82aa-29fb1a28ff1d', 'गाय और स्त्री', true, 'b90a4201-eef4-45ce-84b6-f8761c6b9c22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3ec6590-559f-4d55-a6a6-cee9d26bb02c', 'भैंस और नारी', false, 'b90a4201-eef4-45ce-84b6-f8761c6b9c22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac20b12a-55ee-4c82-9391-339e32113974', 'गौ और औरत', false, 'b90a4201-eef4-45ce-84b6-f8761c6b9c22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ad163d8-7435-4b5a-bde9-b429b68b7d0b', 'गाय और महिला', false, 'b90a4201-eef4-45ce-84b6-f8761c6b9c22');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f806a8e7-a9be-4f9c-8a9f-2d47036f66eb', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'वे शब्द जो पद, व्यवसाय या ओहदे के सूचक होते हैं और स्त्री व पुरुष दोनों के लिए समान रूप से प्रयुक्त होते हैं (जैसे: राष्ट्रपति, प्रधानमंत्री, डॉक्टर, इंजीनियर, जज), उन्हें क्या कहा जाता है?', 'संवैधानिक पद और व्यावसायिक उपाधियाँ (राष्ट्रपति, डॉक्टर, मंत्री) उभयलिंगी रूप में दोनों लिंगों के लिए समान रहती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97c63d0e-002c-4ac6-abc4-0fe4594d239b', 'उभयलिंगी शब्द (Common Gender Words)', true, 'f806a8e7-a9be-4f9c-8a9f-2d47036f66eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7063a1c6-0d1b-4a21-b1cf-e503b6095c40', 'नपुंसक शब्द', false, 'f806a8e7-a9be-4f9c-8a9f-2d47036f66eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26154458-3625-4f73-b90a-6ede6344844f', 'सदा स्त्रीलिंग शब्द', false, 'f806a8e7-a9be-4f9c-8a9f-2d47036f66eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99d65aef-2ee7-4105-b23c-97e4639dac4b', 'अविकारी शब्द', false, 'f806a8e7-a9be-4f9c-8a9f-2d47036f66eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('54868a07-a28a-4072-a708-b1f4aa6ccd10', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'वे प्राणीवाचक शब्द जो सदा पुल्लिंग में ही प्रयुक्त होते हैं (जैसे: मच्छर, चीता, तोता, भेड़िया, खरगोश), उनका स्त्रीलिंग बनाने के लिए क्या किया जाता है?', 'नित्य पुल्लिंग शब्दों के स्त्रीलिंग रूप हेतु ''मादा'' उपसर्ग जोड़ा जाता है (मादा भेड़िया, मादा चीता)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('faa9d6bd-9233-407a-937d-18e896b1374f', 'शब्द के आगे ''मादा'' शब्द जोड़ दिया जाता है (जैसे: मादा मच्छर, मादा चीता, मादा तोता)', true, '54868a07-a28a-4072-a708-b1f4aa6ccd10');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db576a96-d8ff-41bf-9887-f621f345c18d', 'शब्द के अंत में ''नी'' प्रत्यय लगाते हैं', false, '54868a07-a28a-4072-a708-b1f4aa6ccd10');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40437245-fd95-4caf-8959-11c1eacfaada', 'शब्द को बहुवचन बना देते हैं', false, '54868a07-a28a-4072-a708-b1f4aa6ccd10');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96b7b137-2107-4547-bf94-de5fa2c7b28f', 'उनका कोई स्त्रीलिंग नहीं होता', false, '54868a07-a28a-4072-a708-b1f4aa6ccd10');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6964b80-9601-451d-b63e-a66bd30a1482', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'वे शब्द जो सदा स्त्रीलिंग में ही प्रयुक्त होते हैं (जैसे: तितली, मक्खी, कोयल, मछली, मैना, गिलहरी), उनका पुल्लिंग बनाने के लिए क्या किया जाता है?', 'नित्य स्त्रीलिंग शब्दों के पुल्लिंग रूप हेतु ''नर'' उपसर्ग जोड़ा जाता है (नर कोयल, नर मछली, नर गिलहरी)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('273dde08-ee4c-400b-b3ac-0334debc9fa2', 'शब्द के आगे ''नर'' शब्द जोड़ दिया जाता है (जैसे: नर तितली, नर मक्खी, नर कोयल, नर मछली)', true, 'f6964b80-9601-451d-b63e-a66bd30a1482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf00f7c9-5851-4b7a-8a26-6daa37bc3245', 'शब्द के अंत में ''आ'' जोड़ते हैं', false, 'f6964b80-9601-451d-b63e-a66bd30a1482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2255074-a2a2-48af-a9a1-b407bfdbfe1e', 'शब्द को बदल देते हैं', false, 'f6964b80-9601-451d-b63e-a66bd30a1482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64ef2c4b-adcb-4f9c-9623-30b9e959d6d1', 'कोई परिवर्तन नहीं होता', false, 'f6964b80-9601-451d-b63e-a66bd30a1482');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f14bb6d-521b-4c71-9830-314c83f0864a', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'निम्नलिखित में से ''सदा पुल्लिंग'' रहने वाले संज्ञा शब्दों का सही समूह कौन-सा है?', 'भूगोलीय महाद्वीप, देश, पर्वत, सागर, वार और महीने सर्वमान्य रूप से नित्य पुल्लिंग वर्ग में आते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2710167b-8cd1-4e1b-b60f-3b8b49b85d1d', 'देशों के नाम (भारत, रूस), पर्वतों के नाम (हिमालय), सागरों के नाम (हिंद महासागर), दिनों और महीनों के नाम (सोमवार, चैत्र)', true, '6f14bb6d-521b-4c71-9830-314c83f0864a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28701e9a-c969-4af7-85b2-9be333a673c7', 'नदियों के नाम, भाषाओं के नाम', false, '6f14bb6d-521b-4c71-9830-314c83f0864a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ede31f5-dd6b-4034-abd8-4461f7b86e45', 'तिथियों के नाम, लिपियों के नाम', false, '6f14bb6d-521b-4c71-9830-314c83f0864a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8efc9a82-7fad-4218-878b-53eb0d7898fe', 'बोलियों और झीलों के नाम', false, '6f14bb6d-521b-4c71-9830-314c83f0864a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0e9de3a-1375-4a5f-8d6c-7058ce66fcbb', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'निम्नलिखित में से ''सदा स्त्रीलिंग'' रहने वाले संज्ञा शब्दों का सही समूह कौन-सा है?', 'नदियों, भाषाओं, लिपियों, बोलियों तथा पंचांग तिथियों के नाम हिंदी में अनिवार्यतः स्त्रीलिंग होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0be8b325-a85b-4259-88fb-1cf850153d00', 'नदियों के नाम (गंगा, कावेरी), भाषाओं और बोलियों के नाम (हिंदी, ब्रज), लिपियों के नाम (देवनागरी), तिथियों के नाम (एकादशी)', true, 'b0e9de3a-1375-4a5f-8d6c-7058ce66fcbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('504b9a6d-6cb9-4fe7-830a-35b1eaf01d8e', 'पेड़ों के नाम, फलों के नाम', false, 'b0e9de3a-1375-4a5f-8d6c-7058ce66fcbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9635cb8c-c40f-41ce-9482-d7ce3bee99ac', 'अनाजों के नाम, ग्रहों के नाम', false, 'b0e9de3a-1375-4a5f-8d6c-7058ce66fcbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97fda843-ca87-4004-863d-9c0cbe97b4e2', 'धातुओं और रत्नों के नाम', false, 'b0e9de3a-1375-4a5f-8d6c-7058ce66fcbb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f7a2117f-82cb-4ece-b29c-d1426b23ca68', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'अधिकांश धातुएँ और रत्न पुल्लिंग होते हैं, परन्तु कौन-सी धातु और रत्न अपवाद स्वरूप ''स्त्रीलिंग'' माने जाते हैं?', 'सोना, लोहा, ताँबा पुल्लिंग हैं, किन्तु ''चाँदी'' धातु स्त्रीलिंग है; इसी प्रकार अधिकांश रत्न पुल्लिंग हैं किन्तु ''मणि'' स्त्रीलिंग है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cc994ee-01d1-45cc-a914-cbef2477716c', 'धातु में ''चाँदी'' तथा रत्न में ''मणि'' (स्त्रीलिंग)', true, 'f7a2117f-82cb-4ece-b29c-d1426b23ca68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83237575-8e9b-4adc-a676-707cfcf00415', 'लोहा और सोना', false, 'f7a2117f-82cb-4ece-b29c-d1426b23ca68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9642e944-1755-4060-b75d-59c025a0ea58', 'ताँबा और पीतल', false, 'f7a2117f-82cb-4ece-b29c-d1426b23ca68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49e5fbc4-45e6-4e80-9546-9158f43e9101', 'हीरा और पन्ना', false, 'f7a2117f-82cb-4ece-b29c-d1426b23ca68');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cfc191d6-a051-4a61-8b34-58973e438b63', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'अधिकांश अनाज पुल्लिंग होते हैं (गेहूँ, चावल, चना, बाजरा), परन्तु कौन-से अनाज अपवाद स्वरूप ''स्त्रीलिंग'' होते हैं?', 'मक्का, ज्वार, मूँग, और अरहर दालें स्त्रीलिंग प्रयोग में आती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d945fa8-c469-44e7-8b7f-205ba6b4b3c4', 'मक्का, ज्वार, मूँग, अरहर (स्त्रीलिंग)', true, 'cfc191d6-a051-4a61-8b34-58973e438b63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59795c10-18fd-490d-8262-5def7a348fea', 'गेहूँ और धान', false, 'cfc191d6-a051-4a61-8b34-58973e438b63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3edd335f-6fea-47fc-b5fb-b3809c936722', 'चना और मटर', false, 'cfc191d6-a051-4a61-8b34-58973e438b63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f7e0e6b-9d41-48e6-9633-1c9d4d21e4c0', 'जौ और बाजरा', false, 'cfc191d6-a051-4a61-8b34-58973e438b63');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('447d40bf-c5c3-473e-a052-8fbb78e367ba', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'अधिकांश द्रव पदार्थ पुल्लिंग होते हैं (पानी, दूध, तेल, घी, शर्बत), परन्तु कौन-से द्रव अपवाद स्वरूप ''स्त्रीलिंग'' होते हैं?', 'चाय, कॉफ़ी, लस्सी, छाछ आदि पेय पदार्थ व्याकरण में स्त्रीलिंग माने जाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b37f907b-2c87-4b1d-bb2f-1c59343b7bba', 'चाय, कॉफ़ी, लस्सी, शराब, छाछ (स्त्रीलिंग)', true, '447d40bf-c5c3-473e-a052-8fbb78e367ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('655567a2-d176-4a7a-a6e5-e1afc5820614', 'दूध और दही', false, '447d40bf-c5c3-473e-a052-8fbb78e367ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d0789d4-94b1-42a5-9c96-761ef3cb584a', 'तेल और पेट्रोल', false, '447d40bf-c5c3-473e-a052-8fbb78e367ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('713cc714-a417-4c1f-90bd-d99c574a12f7', 'पानी और शरबत', false, '447d40bf-c5c3-473e-a052-8fbb78e367ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f620085-96de-43a0-ad70-a609d59f8ccc', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'पुल्लिंग शब्द ''श्रीमान'' और ''आयुष्मान'' के सही स्त्रीलिंग रूप क्रमशः क्या हैं?', 'मान् का मती तथा वान् का वती: श्रीमान -> श्रीमती; आयुष्मान -> आयुष्मती; गुणवान -> गुणवती; बलवान -> बलवती।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1b55870-8aec-4b80-9584-9b889c3fd760', 'श्रीमती और आयुष्मती', true, '6f620085-96de-43a0-ad70-a609d59f8ccc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01ee09f3-0d3f-42e9-8791-e7690eac70fa', 'श्रीमान्य और आयुष्मान्', false, '6f620085-96de-43a0-ad70-a609d59f8ccc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6428b08-056f-4872-85fd-1c5b5c2dd536', 'श्रीवती और आयुष्मंती', false, '6f620085-96de-43a0-ad70-a609d59f8ccc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dfd6554-30f8-4b8b-b64d-79d2bc69580a', 'श्रीमतीजी और आयुष्मनी', false, '6f620085-96de-43a0-ad70-a609d59f8ccc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fcfa22d7-37ed-4588-a4aa-744e79be30be', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'पुल्लिंग शब्द ''दाता'', ''विधाता'' और ''रचयिता'' के सही स्त्रीलिंग रूप क्रमशः क्या हैं?', 'संस्कृत तत्सम शब्दों में अंतस्थ ''ता'' स्त्रीलिंग में ''त्री'' बन जाता है: दाता -> दात्री; विधाता -> विधात्री; रचयिता -> रचयित्री।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92748a3a-7657-435b-a3dd-93e92219759d', 'दात्री, विधात्री, रचयित्री', true, 'fcfa22d7-37ed-4588-a4aa-744e79be30be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b377a4bb-1faa-447a-b462-779ce42af5b0', 'दातिन, विधातिन, रचयिताइन', false, 'fcfa22d7-37ed-4588-a4aa-744e79be30be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c83b0bb-084b-4d48-8dc6-87afe4473195', 'दाती, विधाती, रचयिती', false, 'fcfa22d7-37ed-4588-a4aa-744e79be30be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('004c8272-e109-4458-9817-71468009ab64', 'दानी, विधाता, रचनाकार', false, 'fcfa22d7-37ed-4588-a4aa-744e79be30be');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ace9ad5a-b1ce-48bd-bdc8-c9676c83d3e2', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'पुल्लिंग शब्द ''धोबी'', ''माली'' और ''तेली'' में ''इन'' प्रत्यय लगाने पर सही स्त्रीलिंग रूप क्या बनेंगे?', 'ई-कारान्त पुल्लिंग शब्दों में ''इन'' प्रत्यय लगने पर ई ह्रस्व होकर ''इन्'' बनता है: धोबी -> धोबिन; माली -> मालिन; तेली -> तेलिन।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0da3a88c-a7a8-4f75-a8c1-77e6c92e4091', 'धोबिन, मालिन, तेलिन', true, 'ace9ad5a-b1ce-48bd-bdc8-c9676c83d3e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fb8c5a8-b153-481a-8b0f-74f47f124659', 'धोबनी, मालनी, तेलनी', false, 'ace9ad5a-b1ce-48bd-bdc8-c9676c83d3e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06c759bc-41a3-47b0-b03e-f019dfeb1d3b', 'धोबन, मालिया, तेलाई', false, 'ace9ad5a-b1ce-48bd-bdc8-c9676c83d3e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('691644f2-3a95-4a70-8036-7166d8ef9ab6', 'धोबीइन, मालीइन, तेलीइन', false, 'ace9ad5a-b1ce-48bd-bdc8-c9676c83d3e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ba40267-de06-46e6-80c4-12ed19bbdd1d', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'पुल्लिंग शब्द ''पंडित'', ''चौधरी'' और ''ठाकुर'' में ''आइन'' प्रत्यय लगाने पर सही स्त्रीलिंग रूप क्या बनेंगे?', 'आइन प्रत्यय से स्त्रीलिंग निर्माण: पंडित -> पंडिताइन; चौधरी -> चौधराइन; ठाकुर -> ठकुराइन; बाबू -> बबुआइन।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c053f58-e0a9-4d6b-ba73-f304b6159a19', 'पंडिताइन, चौधराइन, ठकुराइन', true, '3ba40267-de06-46e6-80c4-12ed19bbdd1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1474c67-8eeb-4ff7-9197-2b06f93cf284', 'पंडिती, चौधरीनी, ठाकुरनी', false, '3ba40267-de06-46e6-80c4-12ed19bbdd1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f22486b2-0b68-4451-96a5-611acbd953f0', 'पंडितनी, चौधरायन, ठकुरायन', false, '3ba40267-de06-46e6-80c4-12ed19bbdd1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1592ea6-e214-4dd9-9bb3-d133e825ce93', 'पंडितानी, चौधरानी, ठाकुरानी', false, '3ba40267-de06-46e6-80c4-12ed19bbdd1d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('09b7f729-a1cd-4f0b-85ad-74deb47cdd25', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'पुल्लिंग शब्द ''सेठ'', ''देवर'' और ''इंद्र'' में ''आनी'' प्रत्यय लगाने पर सही स्त्रीलिंग रूप क्या बनेंगे?', 'आनी प्रत्यय से स्त्रीलिंग: सेठ -> सेठानी; देवर -> देवरानी; नौकर -> नौकरानी; इंद्र -> इंद्राणी; रुद्र -> रुद्राणी।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e9992e0-f92e-4d0e-b984-b084de6b65de', 'सेठानी, देवरानी, इंद्राणी', true, '09b7f729-a1cd-4f0b-85ad-74deb47cdd25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c6e67fe-cc82-489d-9011-3fa398654d93', 'सेठी, देवरी, इंद्री', false, '09b7f729-a1cd-4f0b-85ad-74deb47cdd25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de1f28b4-a9b9-4d15-ba5d-bae5a6b4b221', 'सेठिन, देवरिन, इंद्रिन', false, '09b7f729-a1cd-4f0b-85ad-74deb47cdd25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c07974dc-8925-4336-b3b8-b510b48e29ce', 'सेठाइन, देवरिया, इंद्रा', false, '09b7f729-a1cd-4f0b-85ad-74deb47cdd25');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('606bb861-2e2c-46d6-9e00-1e4bde7e519a', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'पुल्लिंग शब्द ''नायक'', ''गायक'' और ''लेखक'' में ''इका'' प्रत्यय लगाने पर सही स्त्रीलिंग रूप क्या बनेंगे?', 'अक-अन्त पुल्लिंग शब्दों में ''इका'' प्रत्यय: नायक -> नायिका; गायक -> गायिका; लेखक -> लेखिका; पाठक -> पाठिका।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03dc510e-43d6-4c06-ae1d-a73ffc24d0e8', 'नायिका, गायिका, लेखिका', true, '606bb861-2e2c-46d6-9e00-1e4bde7e519a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07d36ba4-3d46-4e7c-94b9-1648187d9ae0', 'नायकी, गायकी, लेखकी', false, '606bb861-2e2c-46d6-9e00-1e4bde7e519a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e14ca92d-f510-4788-89fb-5662d330fca4', 'नायकिन, गायकिन, लेखकिन', false, '606bb861-2e2c-46d6-9e00-1e4bde7e519a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35a3e9ed-7c39-4df9-9679-e1c0ac7c5316', 'नायका, गायका, लेखका', false, '606bb861-2e2c-46d6-9e00-1e4bde7e519a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('240f908e-7b60-4cd7-872b-eef3e5031ad0', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'पुल्लिंग शब्द ''हाथी'' का शुद्ध मानक स्त्रीलिंग रूप क्या होता है?', '''हाथी'' का मानक शुद्ध व्याकरणिक स्त्रीलिंग रूप ''हथिनी'' (ह + थि + नी) होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0260208-cc11-4656-b433-e3530745232c', 'हथिनी', true, '240f908e-7b60-4cd7-872b-eef3e5031ad0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2308def7-e3b0-4f70-ba60-e02cd90260d1', 'हाथिन', false, '240f908e-7b60-4cd7-872b-eef3e5031ad0');
