INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6ea593d-080b-4c96-813f-197e040a215c', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Medium', 'वाक्य में प्रयुक्त क्रिया से लिंग की पहचान कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('284706df-01df-46ac-a4d8-86a85696910c', 'पत्ता = पुल्लिंग ; पत्ती = स्त्रीलिंग', true, 'c6ea593d-080b-4c96-813f-197e040a215c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75dfcb7e-8e53-453c-adae-de5e004a62b1', 'पत्ता = स्त्रीलिंग ; पत्ती = पुल्लिंग', false, 'c6ea593d-080b-4c96-813f-197e040a215c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b3a18a6-4bcc-486b-81e9-3fcf5a4329d4', 'दोनों पुल्लिंग हैं', false, 'c6ea593d-080b-4c96-813f-197e040a215c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c517f475-255a-4cfd-a0e6-2e10c8e9da6c', 'दोनों स्त्रीलिंग हैं', false, 'c6ea593d-080b-4c96-813f-197e040a215c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9219aac1-0a7e-4b16-8d2d-3ec18b49e682', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32767462-f27e-4587-89db-f0158a0420ff', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '9219aac1-0a7e-4b16-8d2d-3ec18b49e682');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea61c99b-b8a3-4404-a687-bb211bed85c8', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '9219aac1-0a7e-4b16-8d2d-3ec18b49e682');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dc231a9-4f19-48ed-b1ac-5668b4880687', '(A) सही है, परन्तु (R) गलत है।', false, '9219aac1-0a7e-4b16-8d2d-3ec18b49e682');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec9a4a6d-9f31-45a5-b0de-d35c88b9327d', '(A) गलत है, परन्तु (R) सही है।', false, '9219aac1-0a7e-4b16-8d2d-3ec18b49e682');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('244f4237-4577-4138-91e3-9dc2a42d6409', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'Spot the IMPOSTER in the following group of ई-कारान्त शब्दों के लिंग के आधार पर:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b314996f-d135-4108-980a-209ae9050fde', 'नदी', false, '244f4237-4577-4138-91e3-9dc2a42d6409');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('085bda94-8e47-417a-bde1-da2562841a7d', 'रोटी', false, '244f4237-4577-4138-91e3-9dc2a42d6409');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('389cb1a4-5ee8-4496-ae39-179e9c90ec9b', 'टोपी', false, '244f4237-4577-4138-91e3-9dc2a42d6409');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('300d1641-4f19-459d-a86d-b254970b27dc', 'पानी', true, '244f4237-4577-4138-91e3-9dc2a42d6409');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c85be945-c4b1-442e-9136-0a333591175b', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'सुमेलित कीजिए (पुल्लिंग और स्त्रीलिंग के विशिष्ट तत्सम युग्म):
(क) विद्वान  -> (i) तपस्विनी
(ख) तपस्वी   -> (ii) विदुषी
(ग) सम्राट    -> (iii) साध्वी
(घ) साधु     -> (iv) सम्राज्ञी', 'विद्वान = विदुषी; तपस्वी = तपस्विनी; सम्राट = सम्राज्ञी; साधु = साध्वी।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a0b1d81-8b4f-4bf1-b07f-402f0fe7cd3a', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', true, 'c85be945-c4b1-442e-9136-0a333591175b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74c606d4-579e-4ece-8093-3b2b48e91a96', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, 'c85be945-c4b1-442e-9136-0a333591175b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abfa5038-ff74-43db-953d-4abc4dd8d6da', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, 'c85be945-c4b1-442e-9136-0a333591175b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bf8a848-f568-46e3-b888-5a2d5ee2e1dd', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, 'c85be945-c4b1-442e-9136-0a333591175b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f32b8ff4-2391-4f93-a06a-3cc820bf477f', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'निम्नलिखित प्रत्ययों वाले भाववाचक शब्दों के लिंग के संदर्भ में कौन-सा कथन सत्य है?', 'ता, आई, आवट, आहट, इमा, ई प्रत्ययान्त भाववाचक शब्द (मानवता, लिखाई, लिखावट, चिकनाहट, महिमा) अनिवार्यतः स्त्रीलिंग होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d217890d-931f-4851-8943-3cb39b4e07e3', 'जिन शब्दों के अंत में ''ता'', ''आई'', ''आवट'', ''आहट'', ''इमा'' प्रत्यय आते हैं (जैसे: सुंदरता, भलाई, सजावट, घबराहट, लालिमा), वे प्रायः स्त्रीलिंग होते हैं', true, 'f32b8ff4-2391-4f93-a06a-3cc820bf477f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('574a9022-da68-4344-a1a4-bf162f23aeb5', 'वे सदा पुल्लिंग होते हैं', false, 'f32b8ff4-2391-4f93-a06a-3cc820bf477f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4752cfc2-aed7-4193-b5d2-8573662376bb', 'वे उभयलिंगी होते हैं', false, 'f32b8ff4-2391-4f93-a06a-3cc820bf477f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91799bbd-ceda-4594-886d-e3e79059d860', 'वे अविकारी होते हैं', false, 'f32b8ff4-2391-4f93-a06a-3cc820bf477f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad022dce-38b7-4453-ba9b-1f14d5125344', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'जिन भाववाचक शब्दों के अंत में ''त्व'', ''पन'', ''पा'', ''आव'', ''आस'' आते हैं (जैसे: मनुष्यत्व, बचपन, बुढ़ापा, बहाव, निकास), वे प्रायः किस लिंग में होते हैं?', 'त्व, पन, पा, आव प्रत्ययान्त भाववाचक संज्ञाएँ सदा पुल्लिंग होती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26c8e76d-2f1e-43eb-bb37-66d8a8543f08', 'पुल्लिंग (जैसे: देवत्व, अपनापन, मोटापा, फैलाव)', true, 'ad022dce-38b7-4453-ba9b-1f14d5125344');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1874627-374f-4f08-92ae-3155861c2f7d', 'स्त्रीलिंग', false, 'ad022dce-38b7-4453-ba9b-1f14d5125344');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('403f9fc0-e5cf-44dd-bb0c-2c474436e0e7', 'नपुंसकलिंग', false, 'ad022dce-38b7-4453-ba9b-1f14d5125344');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62690efd-02c1-450b-bcf3-44641569b0c3', 'उभयलिंगी', false, 'ad022dce-38b7-4453-ba9b-1f14d5125344');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5794b434-4c07-4a41-aa0d-2938647a4046', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'निम्नलिखित वाक्यों पर विचार कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d0218f6-b8e2-40cd-8be3-fc6e69397fc8', 'सभी वाक्य 1, 2 और 3 सत्य हैं', true, '5794b434-4c07-4a41-aa0d-2938647a4046');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5af452a-edee-4318-a6df-c8c89c5a912c', 'वाक्य 1 और 2 केवल', false, '5794b434-4c07-4a41-aa0d-2938647a4046');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fdedeb1-5448-47b9-9008-005468fc4099', 'वाक्य 2 and 3 केवल', false, '5794b434-4c07-4a41-aa0d-2938647a4046');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5667941d-8e3c-4ac3-9db2-45dfe9201d5f', 'वाक्य 1 और 3 केवल', false, '5794b434-4c07-4a41-aa0d-2938647a4046');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('732c3536-e24e-4102-a5d3-ed6174c6ed20', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'पुल्लिंग शब्द ''महान'' और ''युवा'' के सही स्त्रीलिंग रूप क्रमशः क्या हैं?', '''महान'' का तत्सम स्त्रीलिंग रूप ''महती'' (जैसे महती कृपा) तथा ''युवा'' का स्त्रीलिंग ''युवती'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5daecef-484b-4d31-94d9-6454aa7cd84d', 'महती और युवती', true, '732c3536-e24e-4102-a5d3-ed6174c6ed20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52688c9f-2b33-48fb-85bd-783119ce70bf', 'महानता और युवती', false, '732c3536-e24e-4102-a5d3-ed6174c6ed20');
