INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a5aa0e6-f543-4cec-bc9d-e6e7ff05770e', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'शरीर के अंगों के नाम में कौन-से अंग अपवाद स्वरूप ''स्त्रीलिंग'' होते हैं?', 'हाथ, पैर, कान, सिर पुल्लिंग हैं, जबकि आँख, नाक, जीभ, ठोड़ी, उँगली, कलाई स्त्रीलिंग हैं।', NOW()) ON CONFLICT DO NOTHING;
