INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2a5f9dd5-cbed-4bdf-8be2-3f851eb69b02', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'सौरमंडल के सभी ग्रहों के नाम पुल्लिंग होते हैं (सूर्य, चंद्र, मंगल, बुध, गुरु, शुक्र, शनि, राहु, केतु), परन्तु कौन-सा ग्रह अपवाद स्वरूप ''स्त्रीलिंग'' है?', '''पृथ्वी'' हमारी धरती माता होने के कारण व्याकरण में एकमात्र स्त्रीलिंग ग्रह नाम है।', NOW()) ON CONFLICT DO NOTHING;
