INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b67c257f-7d14-4f11-bb7f-4df8e6176719', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'पुल्लिंग शब्द ''बिलाव'' (या बिलाव/बिलाड़) का सही स्त्रीलिंग रूप क्या है?', 'नर मार्जार को ''बिलाव'' तथा मादा मार्जार को ''बिल्ली'' कहा जाता है।', NOW()) ON CONFLICT DO NOTHING;
