INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('397c82a0-7900-4556-9d97-226939fb64ed', 'Class 6', 'Hindi Grammar', 'Chapter 5: लिंग', 'Hard', 'पुल्लिंग शब्द ''भेड़िया'' का सही स्त्रीलिंग रूप क्या होगा?', '''भेड़िया'' नित्य पुल्लिंग शब्द है, अतः इसका स्त्रीलिंग ''मादा भेड़िया'' बनता है (''भेड़'' अलग प्रजाति का जीव है)।', NOW()) ON CONFLICT DO NOTHING;
