INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5da16b31-1259-4308-9921-c85ec298bb32', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Easy', 'Which plant is famous for folding and drooping its leaves immediately when touched by a human hand?', 'Mimosa exhibits thigmonastic turgor loss in pulvini motor cells upon tactile mechanical stimulus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b7e5eae-a734-40c9-8a6a-ae02a993aade', 'Mimosa pudica (''Touch-me-not'' / Chhui-mui)', true, '5da16b31-1259-4308-9921-c85ec298bb32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f20760c-b66b-4063-a33b-a16fd5074e93', 'Cactus', false, '5da16b31-1259-4308-9921-c85ec298bb32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71ee6bb9-1dba-4eb8-8e97-4dd04d485c04', 'Rose', false, '5da16b31-1259-4308-9921-c85ec298bb32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bce260ae-59ca-415b-9bab-be8c845adbf8', 'Hydrilla', false, '5da16b31-1259-4308-9921-c85ec298bb32');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e9d0496-a92c-4086-8736-694af8802047', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Easy', 'How do Earthworms breathe and exchange respiratory gases (O₂ and CO₂)?', 'Earthworms undergo cutaneous respiration: atmospheric oxygen dissolves across the vascularized moist epidermis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15c422ff-a781-4c96-8b63-8451b712e0fa', 'Through their moist and slimy skin', true, '4e9d0496-a92c-4086-8736-694af8802047');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b209f7a-4fdc-472e-a209-3d3a5ec953b9', 'Through lungs', false, '4e9d0496-a92c-4086-8736-694af8802047');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88c65285-f203-4718-be1d-0809e21c802e', 'Through gills', false, '4e9d0496-a92c-4086-8736-694af8802047');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20f7223c-7099-40eb-9294-96f484416229', 'Through nostrils', false, '4e9d0496-a92c-4086-8736-694af8802047');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b4975705-6fbc-4057-84a8-b7c842dd94af', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'What is the key difference between ''Adaptation'' and ''Acclimatization''?', 'Acclimatization is short-term physiological tuning (e.g. higher breathing rate in mountains), whereas adaptation is heritable evolutionary change.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a99307a-b750-45ff-8afb-4f042ace14f2', 'Adaptation occurs very slowly over thousands of years across generations through natural selection, while Acclimatization consists of small temporary adjustments made by an individual organism over a few days', true, 'b4975705-6fbc-4057-84a8-b7c842dd94af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d6c958b-8347-43ab-b75a-9b546f77bb34', 'Adaptation only happens in water', false, 'b4975705-6fbc-4057-84a8-b7c842dd94af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6578d8c-f80b-4ef6-aa84-99aee5e7a835', 'Acclimatization takes millions of years', false, 'b4975705-6fbc-4057-84a8-b7c842dd94af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56efcebb-b6ca-4126-b741-3e17b650be61', 'There is no difference', false, 'b4975705-6fbc-4057-84a8-b7c842dd94af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4504eae1-b391-4190-a61c-9943b52b6047', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'How do desert plants (like Cactus / Opuntia) adapt to survive extreme water scarcity?', 'Xerophytic adaptations: spine modifications reduce transpiration, cladode stems store water, and roots penetrate deep.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dfb7698-d36b-417f-bd1d-1d1695556c90', 'Leaves are reduced to sharp spines to minimize transpiration; stems become thick, green, and fleshy to perform photosynthesis and store water, coated with a waxy cuticle', true, '4504eae1-b391-4190-a61c-9943b52b6047');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb19ed8d-93f4-4451-ad88-843d54a28679', 'They grow broad leaves to catch rain', false, '4504eae1-b391-4190-a61c-9943b52b6047');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4006297-1ae8-4559-a766-52e2c0022a8d', 'They absorb water from desert air using flowers', false, '4504eae1-b391-4190-a61c-9943b52b6047');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7153a934-d038-4168-96eb-009ce9cd7af1', 'They sleep underground all year', false, '4504eae1-b391-4190-a61c-9943b52b6047');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38505b06-e38c-423e-beeb-09f316de572f', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'How do desert animals like Rats and Snakes survive the scorching daytime heat without drinking much water?', 'Fossorial nocturnal behavior avoids diurnal solar heat load while conserving metabolic water.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40774e13-f66a-42b2-8f70-7cff5c50d7c4', 'They stay in deep underground cool burrows during the daytime heat and emerge only during the cool night (Nocturnal habit)', true, '38505b06-e38c-423e-beeb-09f316de572f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('314f09cc-ef58-4de4-80a0-bc9c92d7b709', 'They swim in desert lakes', false, '38505b06-e38c-423e-beeb-09f316de572f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a157a31e-fa96-45d1-87b2-353b043d1335', 'They sweat constantly', false, '38505b06-e38c-423e-beeb-09f316de572f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('426311f8-91e3-429a-9324-7af94d523b02', 'They turn into ice', false, '38505b06-e38c-423e-beeb-09f316de572f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c50d96a1-f395-47f6-b0b7-f28b581280dc', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'What anatomical adaptations allow Mountain Trees (like Pines, Deodars, and Firs) to withstand heavy snow and freezing gales?', 'Conical architecture and needle foliage shed heavy snow loads, preventing mechanical crown fracturing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b089b3fb-b367-4193-ab2a-9f64bebb5079', 'Cone-shaped canopy with sloping branches and needle-like leaves, allowing rainwater and snow to slide off effortlessly without snapping branches', true, 'c50d96a1-f395-47f6-b0b7-f28b581280dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a1f9be3-b488-426d-a6f6-a6519b7e65bc', 'Broad, flat horizontal leaves to catch snow', false, 'c50d96a1-f395-47f6-b0b7-f28b581280dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('460afae0-1490-4203-a1fa-98ab6a5a9291', 'Weak climbing stems', false, 'c50d96a1-f395-47f6-b0b7-f28b581280dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b5055c7-61ad-4f7e-8804-e158cac40fcc', 'Lack of roots', false, 'c50d96a1-f395-47f6-b0b7-f28b581280dc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad151e14-701f-48bf-9305-d348b5820587', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'How is the Snow Leopard adapted to its freezing high-altitude rocky habitat?', 'Dense woolly underfur and fur-cushioned paws insulate against snow while providing high-traction cliff grip.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3360c18-713b-4e28-8451-57d6c0e02918', 'Thick dense fur on its body, feet, and toes to protect from extreme cold, and a long furry tail for balance and warmth', true, 'ad151e14-701f-48bf-9305-d348b5820587');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5ae0fe1-37fe-4b1b-a88e-c7afea8c78d3', 'A bare skin without fur', false, 'ad151e14-701f-48bf-9305-d348b5820587');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4186883-21be-466c-b8b8-4339a953c05a', 'Large flapping ears', false, 'ad151e14-701f-48bf-9305-d348b5820587');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcabb0a5-b261-489c-a9dc-e50be5e0b55a', 'Swimming fins', false, 'ad151e14-701f-48bf-9305-d348b5820587');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22d79cc2-661d-4086-bf1f-33ef8aca2338', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'What adaptation enables the Mountain Goat (Markhor / Himalayan Tahr) to run swiftly up steep rocky slopes?', 'Clad-hoofed ungulates possess keratinous outer walls and concave inner pads creating suction grip on vertical crags.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3a942c0-a055-4100-bf22-c736718f32df', 'Strong, hard hooves with rubbery traction pads for running securely on steep, jagged rocks without slipping', true, '22d79cc2-661d-4086-bf1f-33ef8aca2338');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07fbc83c-58c0-4e19-8ec9-ae3b2c90a925', 'Large wings for gliding', false, '22d79cc2-661d-4086-bf1f-33ef8aca2338');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f1be286-8f2f-4e63-a566-9958e90da763', 'A long snake-like tail', false, '22d79cc2-661d-4086-bf1f-33ef8aca2338');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('361a4e05-1642-446a-b7d1-2c188730e836', 'Soft padded paws like a cat', false, '22d79cc2-661d-4086-bf1f-33ef8aca2338');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf482b17-332b-482e-b41f-a84e766d3a5f', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'Why do Lions living in grasslands have light brown (tawny) fur and forward-facing eyes?', 'Predatory binocular vision grants depth field focus, while tawny pelage blends into savanna grassland backgrounds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f4e54e2-3880-49d3-bffb-38f2a405e0b4', 'Light brown coat camouflages in dry grasses during stalking, and forward-facing eyes allow precise stereoscopic depth perception of prey distance', true, 'cf482b17-332b-482e-b41f-a84e766d3a5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5462ebc-cce2-4d3e-aaff-d3cf13739dda', 'To attract sunlight', false, 'cf482b17-332b-482e-b41f-a84e766d3a5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e489afc6-93f0-494e-9986-932dc4b79e39', 'To scare birds', false, 'cf482b17-332b-482e-b41f-a84e766d3a5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('533ede56-5f78-42c9-bf15-05dff57de4b1', 'Because they only eat grass', false, 'cf482b17-332b-482e-b41f-a84e766d3a5f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60544f50-feba-4998-ba3b-ebc26c00fbae', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'Why do prey animals like Deer in grasslands have long ears and eyes positioned on the SIDES of their head?', 'Herbivore side-mounted eyes deliver panoramic peripheral vision to detect approaching carnivores without turning the head.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd1eceee-65a4-4ef9-ab45-b6385b9f48be', 'Long ears hear subtle predator movements from afar, and lateral eyes provide wide 360° panoramic field of vision to spot danger in all directions', true, '60544f50-feba-4998-ba3b-ebc26c00fbae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aeb0b2f-dde4-413b-adab-71a1c0685209', 'To look at their own tails', false, '60544f50-feba-4998-ba3b-ebc26c00fbae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fba3d64-fc96-47bd-9737-ae7d84f11e57', 'To fly in the wind', false, '60544f50-feba-4998-ba3b-ebc26c00fbae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af40e29e-4108-43d1-a332-082a85f37152', 'To keep their head cool', false, '60544f50-feba-4998-ba3b-ebc26c00fbae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6c395c0b-7358-43b4-9bc0-3034fc93a386', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'How do marine mammals like Dolphins and Whales breathe oxygen since they do NOT possess gills?', 'Cetaceans are air-breathing lung-bearing mammals that surface to ventilate through dorsal blowholes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc481e51-477c-4d33-a295-509c4c6bc4d0', 'Through Blowholes (nostrils) located on the upper surface of their heads, coming to the ocean surface to breathe air into their lungs', true, '6c395c0b-7358-43b4-9bc0-3034fc93a386');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bba45f4-b9b9-44a5-affb-6894d0beff54', 'Through their mouth underwater', false, '6c395c0b-7358-43b4-9bc0-3034fc93a386');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a292312-6a80-4296-838f-c944f3635891', 'Through their tail flukes', false, '6c395c0b-7358-43b4-9bc0-3034fc93a386');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c2af437-5f7d-4c94-a407-1518f5f6c1ab', 'They do not breathe oxygen', false, '6c395c0b-7358-43b4-9bc0-3034fc93a386');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3427ed66-7d0a-4872-a1ac-97a935bb9af2', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'How are completely submerged aquatic plants (like Hydrilla and Vallisneria) adapted to flowing water currents?', 'Ribbon-like linear foliage minimizes hydrodynamic drag, flexing gracefully with aqueous streamflow.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc3c428b-662d-489b-923a-82a468d0d4a9', 'Narrow, thin, ribbon-like flexible leaves that can bend freely in water currents without tearing', true, '3427ed66-7d0a-4872-a1ac-97a935bb9af2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ed909ec-0a53-432f-8602-2a62bc0e4abc', 'Large hard wooden trunks', false, '3427ed66-7d0a-4872-a1ac-97a935bb9af2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b8d618d-8dcb-48d0-9e4d-e5b183bfea15', 'Thick waxy spines', false, '3427ed66-7d0a-4872-a1ac-97a935bb9af2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2a982db-f415-4ab4-8966-7e0e5a4bd1e0', 'Heavy stone fruits', false, '3427ed66-7d0a-4872-a1ac-97a935bb9af2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('204c38a7-499a-4365-85fd-d7d2c8cdbc65', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'How are floating aquatic plants (like Lotus and Water Lily) adapted to survive on water surfaces?', 'Aerenchyma tissue provides buoyancy, while epistomatous leaves have stomata on the dorsal side to exchange air above water.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6254fc9b-eeff-4b7f-8e15-7e8b8d0ec2aa', 'Stems are long, hollow, light, and spongy filled with air spaces; leaves and flowers float on the surface with stomata on the upper surface', true, '204c38a7-499a-4365-85fd-d7d2c8cdbc65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28b30e2a-f183-497e-9ad1-d3121d505ee6', 'Stems are solid heavy iron wood', false, '204c38a7-499a-4365-85fd-d7d2c8cdbc65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff2c573c-b740-418e-b194-b2f0381fda2d', 'Roots are 50 meters deep in soil', false, '204c38a7-499a-4365-85fd-d7d2c8cdbc65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b25cf6e5-80ee-457a-b483-7ea8730b907b', 'Leaves are covered with ice', false, '204c38a7-499a-4365-85fd-d7d2c8cdbc65');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7951694-dac0-4f31-b573-5fb1768b454b', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'How are Frogs adapted to live both on land and in freshwater ponds (Amphibious lifestyle)?', 'Dual respiration (pulmonary on land and cutaneous underwater) combined with webbed feet enables life in both aquatic and terrestrial habitats.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3720bff8-59ac-42b0-93e8-2eaa505cfefe', 'They possess strong webbed hind legs for swimming and leaping, breathe through lungs on land, and breathe through moist skin underwater', true, 'b7951694-dac0-4f31-b573-5fb1768b454b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d7b1485-29d2-49be-84f0-fb20bbce709a', 'They have feathers to fly', false, 'b7951694-dac0-4f31-b573-5fb1768b454b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d556292f-13b3-484f-aaf2-dc06b8545ade', 'They have gills like sharks', false, 'b7951694-dac0-4f31-b573-5fb1768b454b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9b21b9b-3aea-4f94-bd41-b364b03e0e70', 'They eat rocks', false, 'b7951694-dac0-4f31-b573-5fb1768b454b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18a6bd0a-7103-475c-b629-d434ee69b3ee', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'What is the key difference between ''Breathing'' and ''Respiration'' in living organisms?', 'Breathing is physical gas exchange; cellular respiration is the metabolic catabolism of nutrients yielding ATP energy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ea649b7-6b7d-4b8b-9c01-16fdfde0dd6c', 'Breathing is the physical intake of oxygen and release of carbon dioxide, while Respiration is the biochemical oxidation of glucose inside cells to release energy', true, '18a6bd0a-7103-475c-b629-d434ee69b3ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f4ff732-1fdc-4675-a228-6538c084b9f7', 'Breathing produces food', false, '18a6bd0a-7103-475c-b629-d434ee69b3ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cf21a0d-1a39-4665-9731-8bb26fd64afe', 'Respiration is only done by plants', false, '18a6bd0a-7103-475c-b629-d434ee69b3ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('281d5c9a-c383-4208-b7f8-a93c9ad0064b', 'They are the exact same thing', false, '18a6bd0a-7103-475c-b629-d434ee69b3ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d5b884c-731b-421e-b4b0-a3c9e0b5180e', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'Why is a car or an airplane that moves, consumes fuel, and exhausts smoke NOT considered a living organism?', 'Non-living machines lack biological homeostasis, cellular organization, intrinsic growth, and reproductive heredity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48320268-8a8f-4aa2-b1b7-537d01434080', 'It cannot grow, reproduce offspring, respond to biological stimuli, or carry out internal cellular metabolism independently', true, '4d5b884c-731b-421e-b4b0-a3c9e0b5180e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c6f9fb2-914d-4985-aced-7fb89bb4a34e', 'Because it is made of metal', false, '4d5b884c-731b-421e-b4b0-a3c9e0b5180e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1e1525f-451a-4c3d-bf9c-a96b0fc0171e', 'Because it has wheels', false, '4d5b884c-731b-421e-b4b0-a3c9e0b5180e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbbcaa90-6483-486b-8977-9cc13a8cb870', 'Because it is too fast', false, '4d5b884c-731b-421e-b4b0-a3c9e0b5180e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2808f795-e84d-48b5-a0f5-9909131b550c', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'How do green plants respire during the night when there is no sunlight for photosynthesis?', 'Cellular respiration occurs 24/7 in plants; at night without photosynthetic O₂ production, net gas exchange consumes O₂ and expels CO₂.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f8f6ba5-0a8f-480c-9ce1-c8a19733338b', 'They take in Oxygen (O₂) and release Carbon Dioxide (CO₂) through microscopic stomata, exactly like animals do', true, '2808f795-e84d-48b5-a0f5-9909131b550c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a35894e4-6b8f-41f7-9062-948aedf688f0', 'They stop respiring completely', false, '2808f795-e84d-48b5-a0f5-9909131b550c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9abcb8eb-f10d-418a-9136-807807a10ce0', 'They produce glucose from moonlight', false, '2808f795-e84d-48b5-a0f5-9909131b550c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e5e2838-e8c5-4393-9966-019ccd6d30e1', 'They turn into stone', false, '2808f795-e84d-48b5-a0f5-9909131b550c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ce411ea-9d31-4197-a753-3156f1995dc3', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Medium', 'Which of the following organisms reproduces by laying eggs (Oviparous)?', 'Oviparous animals (birds, reptiles, amphibians, insects) lay eggs that hatch outside the maternal body.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cd5b33d-eb25-4513-a693-5bdbab1ce765', 'Birds, Snakes, and Frogs', true, '0ce411ea-9d31-4197-a753-3156f1995dc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2577ff30-6177-4d35-ba2b-ae521c5a20f5', 'Cows and Buffaloes', false, '0ce411ea-9d31-4197-a753-3156f1995dc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e72a2d0a-2f3c-4843-8f34-5882cc680024', 'Lions and Tigers', false, '0ce411ea-9d31-4197-a753-3156f1995dc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d70ad679-150f-49c0-bf82-f4bdaa17539e', 'Humans and Elephants', false, '0ce411ea-9d31-4197-a753-3156f1995dc3');
