INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41a2e1e0-9ff0-409b-9382-a2de4ebe736b', 'Fish (Gills)', false, 'b3477aec-1630-4538-ae4f-1b9bb71fae16');
