INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63779d64-6499-4aa8-8ea8-4094be3977e2', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'A botanist investigates root development in three plant species: Cactus (Desert), Hydrilla (Submerged aquatic), and Neem (Mesophytic tree). What comparative root adaptations are observed?', 'Xerophytes develop extensive root networks to scavenge moisture; hydrophytes reduce roots because water surrounds the entire plant body.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0cf3ba7-8a95-4e1e-b9c0-ee3cb08d4c35', 'Cactus has deep extensive roots to reach deep groundwater; Hydrilla has very reduced roots purely for holding in place; Neem has widespread deep taproots', true, '63779d64-6499-4aa8-8ea8-4094be3977e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97fe75cc-7cc5-490a-9361-65e19214bf00', 'Hydrilla has the deepest roots', false, '63779d64-6499-4aa8-8ea8-4094be3977e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0041719a-333f-4189-8665-024397ab0c2f', 'Cactus roots float in air', false, '63779d64-6499-4aa8-8ea8-4094be3977e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed637d2f-3564-4e73-922d-bf808ea8bff9', 'All three have identical root structures', false, '63779d64-6499-4aa8-8ea8-4094be3977e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b54b4e9b-3198-4ace-b32c-35eb9f846ee3', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'Match Column I (Habitats & Adaptations) with Column II (Organisms):
(a) Padded feet, hump, dry dung         -> (i) Snow Leopard
(b) Thick fur on body, feet, long tail   -> (ii) Mountain Pine Tree
(c) Conical crown, sloping branches     -> (iii) Camel
(d) Webbed hind feet, moist skin         -> (iv) Frog', 'Camel = padded feet/hump; Snow Leopard = thick fur; Pine = conical crown; Frog = webbed feet.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e862978-1cb2-4531-a5b1-a8bb00a07e92', 'a-(iii), b-(i), c-(ii), d-(iv)', true, 'b54b4e9b-3198-4ace-b32c-35eb9f846ee3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65b3a8d7-6bd1-4c20-9e1d-1a6e037ee3dd', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'b54b4e9b-3198-4ace-b32c-35eb9f846ee3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ec462ce-c9f7-4e15-af13-88580e3cea0c', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'b54b4e9b-3198-4ace-b32c-35eb9f846ee3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf12b1b9-0e2c-4ada-94e4-8bed2a8cc48d', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'b54b4e9b-3198-4ace-b32c-35eb9f846ee3');
