INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edc7419f-d382-40ff-86eb-92b445c7f322', 'Statements 1 and 2 only', true, '1d91b8c9-5926-42e7-8531-229792b90597');
