INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('501a2b34-0854-4d76-ad91-fe76ce210afe', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'Why do seeds (like dry kidney beans or wheat grains) kept dry inside a kitchen jar stay dormant without growing for months, yet sprout rapidly when placed in moist soil with warmth and air?', 'Seed dormancy maintains low basal metabolic rate until hydration and oxygen activate gibberellins to initiate embryo growth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2419d1af-af6d-43d9-8104-9ae023620da1', 'Seeds are living biological entities in a state of suspended dormancy; moisture, oxygen, and warmth trigger enzymatic metabolic germination', true, '501a2b34-0854-4d76-ad91-fe76ce210afe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9e9fa93-c6de-45f3-8c75-514740167643', 'Seeds are non-living stones that turn alive', false, '501a2b34-0854-4d76-ad91-fe76ce210afe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('227a60fe-5339-4aae-8117-af42806df76b', 'Soil injects electricity into seeds', false, '501a2b34-0854-4d76-ad91-fe76ce210afe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5742dcef-c3c2-4199-adb2-10101330c156', 'Water creates seeds from magic', false, '501a2b34-0854-4d76-ad91-fe76ce210afe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4330721e-b29f-4fd5-bccf-0b1ca17be6c8', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'Consider four animals:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f69b382-1860-4bf2-98c1-b0b9d61a7c65', 'Animal 2 (Fish - streamlined body, mucous scales, fins)', true, '4330721e-b29f-4fd5-bccf-0b1ca17be6c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dde5faa-dc66-4a40-a353-6b959eef77f0', 'Animal 1', false, '4330721e-b29f-4fd5-bccf-0b1ca17be6c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4e1bca4-d9af-45e1-b0e4-aa6a6633af57', 'Animal 3', false, '4330721e-b29f-4fd5-bccf-0b1ca17be6c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80a00132-3551-4c38-a0eb-cab9c66a24d0', 'Animal 4', false, '4330721e-b29f-4fd5-bccf-0b1ca17be6c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81e85600-48fc-4158-b2f2-a22717e56fbe', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'How do plants respond to the unidirectional stimulus of sunlight (Phototropism)?', 'Phototropic curvature: Auxin redistributes to shaded stem tissues, promoting differential cell elongation towards the light vector.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('171d655e-1e47-4d35-95d6-f47b63490360', 'Shoots bend towards the light source due to the hormone auxin accumulating on the shaded side, while roots grow away from light into the soil', true, '81e85600-48fc-4158-b2f2-a22717e56fbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2589693c-bd08-4d6d-92c5-f5076fd6af27', 'Plants close their leaves and hide', false, '81e85600-48fc-4158-b2f2-a22717e56fbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a66e404-99ec-4d7d-8703-aa290c61e0b8', 'Plants produce black smoke', false, '81e85600-48fc-4158-b2f2-a22717e56fbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58f5e0e3-2aed-4e13-8fd0-798dc530ec8a', 'Shoots grow straight into the ground', false, '81e85600-48fc-4158-b2f2-a22717e56fbe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('975e69f0-4010-4752-a5f9-e7221a43607b', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'Why is the urine of a camel extremely concentrated and viscous, and its dung completely dry?', 'Elongate loops of Henle in camel kidneys generate hyperosmotic urine, minimizing urinary and fecal water excretion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('daf4fb4a-3408-40fe-bf2f-023f09e3c11f', 'Extreme physiological water conservation: kidneys reabsorb maximum water to allow the camel to survive weeks without drinking water', true, '975e69f0-4010-4752-a5f9-e7221a43607b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('731bd59e-e223-4358-a4ba-032d5de7cb91', 'Camels eat sand', false, '975e69f0-4010-4752-a5f9-e7221a43607b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53e0ccd5-1178-4e1c-a2dd-4c75f8240348', 'Camels have no kidneys', false, '975e69f0-4010-4752-a5f9-e7221a43607b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ffd9196-97c5-4c00-a32d-c84408bca08d', 'To make waste colorful', false, '975e69f0-4010-4752-a5f9-e7221a43607b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('28be97ae-778e-4ebb-b51d-fe001df0973c', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'What is the primary ecological consequence when a non-native invasive species is introduced into a new habitat lacking natural predators?', 'Invasive species disrupt biotic food webs by outcompeting native taxa through aggressive unchecked proliferation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28264ba0-c387-4f28-be3c-e91145f736ea', 'It multiplies uncontrollably, outcompeting native species for resources (food, water, space) and destabilizing the ecological biotic balance', true, '28be97ae-778e-4ebb-b51d-fe001df0973c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b67eb755-d52e-477e-afdd-3b85ade8f7ed', 'It turns into a tree', false, '28be97ae-778e-4ebb-b51d-fe001df0973c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa32e25f-e97a-41c2-934e-e52dd2f511fc', 'It evaporates the ocean', false, '28be97ae-778e-4ebb-b51d-fe001df0973c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('955d30fc-f230-4f7e-9264-4c38d1fe5605', 'It causes gravity to stop', false, '28be97ae-778e-4ebb-b51d-fe001df0973c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99fcd849-cd85-472f-bcc1-e7ba2eef5b6b', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'Which of the following describes the biological phenomenon of ''Aestivation'' (Summer Sleep) in desert animals and snails?', 'Aestivation suppresses metabolic rate during prolonged hot droughts, protecting organisms from desiccation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79102c0e-a6bc-4a55-a73e-ddc82f80e60f', 'A state of metabolic dormancy and torpor during hot, dry summer months to prevent lethal dehydration and thermal stress', true, '99fcd849-cd85-472f-bcc1-e7ba2eef5b6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45b2e23b-3f98-47a9-8369-eb772bfab133', 'Winter hibernation', false, '99fcd849-cd85-472f-bcc1-e7ba2eef5b6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11bbf693-8666-43ab-81b1-004322b797ca', 'Migrating to the moon', false, '99fcd849-cd85-472f-bcc1-e7ba2eef5b6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2a81abe-8a52-4bd5-b81a-664de2dcad28', 'Laying eggs in water', false, '99fcd849-cd85-472f-bcc1-e7ba2eef5b6b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('71e77b40-08bc-4731-a52b-57f9c4109a1c', 'Class 6', 'Science', 'Chapter 6: The Living Organisms — Characteristics and Habitats', 'Hard', 'What are the universal core characteristics shared by ALL living organisms without exception?', 'The seven defining biological characteristics of life: Nutrition, Respiration, Irritability/Response, Excretion, Reproduction, Growth, and Movement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3242cd2c-09c5-4d47-972b-6561d5b68ace', 'Need for nutrition, Cellular respiration, Response to stimuli, Excretion, Reproduction, Growth, and Movement', true, '71e77b40-08bc-4731-a52b-57f9c4109a1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5445d509-63a7-4016-9d68-e7d8be4d3930', 'Ability to fly in air', false, '71e77b40-08bc-4731-a52b-57f9c4109a1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92299afb-a8fb-4096-bd95-34a54b821c53', 'Having red blood', false, '71e77b40-08bc-4731-a52b-57f9c4109a1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9920d932-421a-4870-83f4-628156cc9ba3', 'Having bones and teeth', false, '71e77b40-08bc-4731-a52b-57f9c4109a1c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('744594f1-cc41-4119-b49c-91b0a22ee0cf', 'Class 6', 'Mathematics', 'Chapter 6: Integers', 'Easy', 'The complete collection of numbers consisting of all positive numbers, zero, and all negative numbers (... -3, -2, -1, 0, 1, 2, 3 ...) is called:', 'Integers comprise the set of whole numbers along with their negative additive inverses.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('093c99f4-8810-4e04-8356-d79f5bd5f3a8', 'Integers (denoted as Z)', true, '744594f1-cc41-4119-b49c-91b0a22ee0cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab138bb1-26bf-4774-9f7b-e6aa07dd5545', 'Whole Numbers', false, '744594f1-cc41-4119-b49c-91b0a22ee0cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('044b0397-127f-4c24-a34c-10eb09910f0d', 'Natural Numbers', false, '744594f1-cc41-4119-b49c-91b0a22ee0cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc564e44-cdc8-4f7f-a557-4a2f52bedf08', 'Fractions', false, '744594f1-cc41-4119-b49c-91b0a22ee0cf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d2cc404e-89f8-46f2-8ca5-b55a8337e926', 'Class 6', 'Mathematics', 'Chapter 6: Integers', 'Easy', 'Which unique integer is NEITHER positive NOR negative?', 'Zero is the neutral boundary origin on the number line; it is neither positive nor negative.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d5956fc-9ef4-464e-8532-bb5843a74ba5', '0 (Zero)', true, 'd2cc404e-89f8-46f2-8ca5-b55a8337e926');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7459562-e8bf-4352-8f2a-96e67473bebd', '1', false, 'd2cc404e-89f8-46f2-8ca5-b55a8337e926');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c81af258-c859-4d9f-b98a-5c25af615eae', '-1', false, 'd2cc404e-89f8-46f2-8ca5-b55a8337e926');
