INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10acab13-d540-42c2-8555-b600c4dff7f9', 'Class 6', 'Mathematics', 'Chapter 6: Integers', 'Easy', 'On a horizontal number line, where do positive integers lie relative to zero (0)?', 'Conventionally on a standard number line, positive values extend rightwards, while negative values extend leftwards.', NOW()) ON CONFLICT DO NOTHING;
