INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('80017836-f7a1-4a2d-9317-62770f58f7b0', 'Class 6', 'Mathematics', 'Chapter 6: Integers', 'Hard', 'Subtract the sum of -1032 and 878 from -34:', 'Sum = -1032 + 878 = -154. Required difference = -34 - (-154) = -34 + 154 = +120.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ac533a4-14b0-4291-be93-359cb4afb6d3', '+120 (-34 - (-154) = -34 + 154 = +120)', true, '80017836-f7a1-4a2d-9317-62770f58f7b0');
