INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff748e73-ad25-4a40-8978-b9e74f9315b1', 'Class 6', 'Mathematics', 'Chapter 6: Integers', 'Hard', 'Match Column I (Expressions) with Column II (Simplified Integer Values):
(a) (-50) + (-200) + 300 -> (i) +50
(b) 37 + (-2) + (-65) + (-8) -> (ii) -38
(c) (-7) - 8 - (-25)     -> (iii) +10
(d) 50 - (-40) - (-2)    -> (iv) +92', 'a: -250 + 300 = +50; b: 37 - 75 = -38; c: -15 + 25 = +10; d: 50 + 40 + 2 = +92.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24e7a064-216e-4854-9857-706d8e6ad83b', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'ff748e73-ad25-4a40-8978-b9e74f9315b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('829ce8c6-1321-48b6-a76a-c1121a59644a', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'ff748e73-ad25-4a40-8978-b9e74f9315b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f004b555-5fe7-4c1f-a133-933b37c46139', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'ff748e73-ad25-4a40-8978-b9e74f9315b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3e43859-3d8b-4383-aa4c-a9343d83afad', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'ff748e73-ad25-4a40-8978-b9e74f9315b1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be4cfd6d-59ea-4870-b2bb-a7e155dc3bce', 'Class 6', 'Mathematics', 'Chapter 6: Integers', 'Hard', 'Read the statements regarding integers:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('195e0e8c-2973-464f-af17-8ed901b3c0f7', 'All Statements 1, 2, and 3', true, 'be4cfd6d-59ea-4870-b2bb-a7e155dc3bce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18442d53-2f95-41f7-93b6-a4bb0eb2781d', 'Statements 1 and 2 only', false, 'be4cfd6d-59ea-4870-b2bb-a7e155dc3bce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f4202ca-bc7a-4c89-a449-b14970ac943a', 'Statements 2 and 3 only', false, 'be4cfd6d-59ea-4870-b2bb-a7e155dc3bce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62f62f89-ed06-465a-ac1d-625fdb33cdae', 'Statements 1 and 3 only', false, 'be4cfd6d-59ea-4870-b2bb-a7e155dc3bce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17d3b3e1-4e11-4fb5-be96-3d2d243db5f4', 'Class 6', 'Mathematics', 'Chapter 6: Integers', 'Hard', 'If a = -9 and b = -6, show whether (a - b) is equal to (b - a):', 'a - b = (-9) - (-6) = -3; b - a = (-6) - (-9) = +3. Hence a - b ≠ b - a.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5db0b4f0-b36a-4372-ab69-906d48f8f8cc', 'No, (a - b) = -3 while (b - a) = +3 ; Subtraction of integers is NOT commutative', true, '17d3b3e1-4e11-4fb5-be96-3d2d243db5f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ca1900c-ab58-462a-bad1-8ccc92b48a9e', 'Yes, both equal -3', false, '17d3b3e1-4e11-4fb5-be96-3d2d243db5f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('220d94b2-8a76-4f53-a43b-f730cd25c613', 'Yes, both equal +3', false, '17d3b3e1-4e11-4fb5-be96-3d2d243db5f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbcd4bbe-58e9-49cb-b79a-0e926d855f72', 'Both equal 0', false, '17d3b3e1-4e11-4fb5-be96-3d2d243db5f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fbab4e63-d4b6-4871-bc0f-1d3ed86ae622', 'Class 6', 'Mathematics', 'Chapter 6: Integers', 'Hard', 'An elevator descends into a mine shaft at the rate of 6 meters per minute. If the descent starts from 10 meters above ground level (+10 m), how long will it take to reach -350 meters?', 'Total vertical displacement = (+10) - (-350) = 360 meters. Time = 360 m ÷ 6 m/min = 60 minutes = 1 hour.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a689983-273a-4674-a85d-c66d0d7e3784', '60 minutes (1 hour)', true, 'fbab4e63-d4b6-4871-bc0f-1d3ed86ae622');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f2bca49-bcec-4202-b494-0778ce273200', '45 minutes', false, 'fbab4e63-d4b6-4871-bc0f-1d3ed86ae622');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82895046-b56a-449f-833f-f9ad5bb00dce', '50 minutes', false, 'fbab4e63-d4b6-4871-bc0f-1d3ed86ae622');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad1a1018-ae6f-4d8d-8748-0d0bf77a518c', '75 minutes', false, 'fbab4e63-d4b6-4871-bc0f-1d3ed86ae622');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('215482ae-d725-4dc1-8dc5-52845d1dd4d8', 'Class 6', 'Mathematics', 'Chapter 6: Integers', 'Hard', 'In a quiz competition, positive marks (+5) are given for correct answers and negative marks (-2) are given for incorrect answers. If Rohit scored -6 marks by getting 4 correct answers, how many incorrect answers did he attempt?', '20 - 2x = -6 -> 2x = 26 -> x = 13 incorrect answers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('533f3e2b-821d-4379-8312-632c112d383c', '13 incorrect answers (4 × 5 - 2x = -6 -> 20 - 2x = -6 -> 2x = 26 -> x = 13)', true, '215482ae-d725-4dc1-8dc5-52845d1dd4d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0a407b4-4aa4-491b-b544-06d2114bc97d', '10', false, '215482ae-d725-4dc1-8dc5-52845d1dd4d8');
