INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a55be0e7-defe-43b5-b397-536ede77bd5d', 'Class 6', 'Mathematics', 'Chapter 6: Integers', 'Hard', 'What is the absolute value of an integer (denoted as |x|)?', 'Absolute value |x| = x for x ≥ 0, and -x for x < 0, measuring Euclidean metric distance from origin.', NOW()) ON CONFLICT DO NOTHING;
