INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8cb770cf-1632-4970-be60-8400afdcf191', 'Class 6', 'Mathematics', 'Chapter 6: Integers', 'Hard', 'Calculate the value of the algebraic expression: |-25| - |+15| + |-10| - |-5|', '25 - 15 + 10 - 5 = 10 + 10 - 5 = 15.', NOW()) ON CONFLICT DO NOTHING;
