INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e701d20e-4943-45bf-8068-2912476730a9', 'Class 6', 'Mathematics', 'Chapter 6: Integers', 'Hard', 'Starting at integer -3 on the number line, move 5 units to the right, then 8 units to the left, and finally 4 units to the right. What is your final resting integer position?', '-3 + 5 = 2; 2 - 8 = -6; -6 + 4 = -2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db23e17d-d8b5-4e6b-ab19-0539b961dfad', '-2 ((-3) + 5 - 8 + 4 = 2 - 8 + 4 = -6 + 4 = -2)', true, 'e701d20e-4943-45bf-8068-2912476730a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47916029-4828-496c-a3e9-74567ce3ae70', '+2', false, 'e701d20e-4943-45bf-8068-2912476730a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec49635f-f821-458c-9361-db69c8d974f7', '-4', false, 'e701d20e-4943-45bf-8068-2912476730a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94d8d4aa-df43-44d7-a48a-17cd778d9d94', '0', false, 'e701d20e-4943-45bf-8068-2912476730a9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('228c57c2-2b0c-4f9d-afbc-75278b28f253', 'Class 6', 'Mathematics', 'Chapter 6: Integers', 'Hard', 'Which of the following properties holds TRUE for Addition of integers but FAILS for Subtraction of integers?', 'Integer addition is both commutative and associative, while subtraction is strictly non-commutative (a-b ≠ b-a) and non-associative.', NOW()) ON CONFLICT DO NOTHING;
