INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16e0c96d-ffe0-47ea-8699-a8486d3e9303', 'Closure Property', false, '228c57c2-2b0c-4f9d-afbc-75278b28f253');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('812b8bac-e720-4784-94ff-586f7136f18e', 'Identity Property', false, '228c57c2-2b0c-4f9d-afbc-75278b28f253');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0ecf63c-9a07-4e4d-a6bc-703cc8f1217f', 'Distributive Property', false, '228c57c2-2b0c-4f9d-afbc-75278b28f253');
