INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38d4e9be-bd3d-47aa-8675-986d913ec8af', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'What does Serbjit do when he gets angry because people don''t believe him when he tells the truth?', 'Serbjit controls his temper by looking at his shoes and counting to ten when teachers or parents distrust his honest word.', NOW()) ON CONFLICT DO NOTHING;
