INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cccd2288-2038-493a-964d-a2e86ca4c17c', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'What is Dolma''s grand ambition for her future career?', 'Dolma has strong leadership qualities; when people say it''s impossible, she insists she will make things better for everyone as Prime Minister.', NOW()) ON CONFLICT DO NOTHING;
