INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('beb8c1b1-cfda-4566-8b3a-773df02d7450', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'In the supplementary tale ''The Monkey and the Crocodile'', where did the friendly monkey live?', 'The solitary monkey lived happily in a fruit-laden tree on the riverbank, feasting on sweet berries.', NOW()) ON CONFLICT DO NOTHING;
