INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ecb1a1e-b49c-41fa-9655-d9f8ad8e74aa', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'What sweet fruit did the generous monkey pluck and throw down to his new friend, the crocodile?', 'The monkey shared delicious fresh berries with the visiting crocodile daily.', NOW()) ON CONFLICT DO NOTHING;
