INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7088d3ad-8805-47c6-b346-d4452b2a6cc6', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'Why was the crocodile''s wife furious when the crocodile returned home very late one day?', 'Waiting impatiently with her newly hatched babies, the crocodile''s wife resented her husband''s long daily chats with the monkey.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bea60a2-953d-49dd-9fd8-84adeb1202bb', 'She was tired of waiting and managing the newly hatched baby crocodiles alone', true, '7088d3ad-8805-47c6-b346-d4452b2a6cc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('891dc5e3-0e02-454f-8735-5a3294ed904a', 'She had lost her house', false, '7088d3ad-8805-47c6-b346-d4452b2a6cc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e4c6885-5f59-433b-9e67-c2cea282db8c', 'She was angry at the river', false, '7088d3ad-8805-47c6-b346-d4452b2a6cc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('070a62d6-2ba4-46cf-b0b1-2ec54d8baccd', 'She wanted to swim to the sea', false, '7088d3ad-8805-47c6-b346-d4452b2a6cc6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b04e7faa-391a-4963-99ec-6e4e4427cce8', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'What wicked demand did the crocodile''s wife make after tasting the sweet berries brought home by her husband?', 'Her cruel greed demanded the monkey''s heart as an exotic delicacy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f675f8a-5270-4ab3-a29d-bebd52726b25', 'She demanded to eat the monkey''s heart, arguing that an animal eating such sweet fruit daily must have the sweetest heart', true, 'b04e7faa-391a-4963-99ec-6e4e4427cce8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b50dd9a4-0c8e-4425-91d7-e0f81c5f71a1', 'She wanted the monkey''s fur coat', false, 'b04e7faa-391a-4963-99ec-6e4e4427cce8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3497e5f2-defa-400c-8af0-a45093fe3ed4', 'She wanted the tree to be cut down', false, 'b04e7faa-391a-4963-99ec-6e4e4427cce8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ad90168-6153-4c4b-aa0d-b0fecf6f9a2c', 'She wanted to live in the tree', false, 'b04e7faa-391a-4963-99ec-6e4e4427cce8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('86269eca-284c-40a3-91ec-f88467c9a17b', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'How did the crocodile transport the monkey across the river to visit his home?', 'Unable to swim, the trusting monkey rode happily perched on the crocodile''s back.', NOW()) ON CONFLICT DO NOTHING;
