INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5aa8418b-30f5-465c-8ae0-a4ec461bde14', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Easy', 'In the poem ''The Wonderful Words'' by Mary O''Neill, what are words described as?', 'Poet Mary O''Neill writes that words give physical form, elegance, and dynamic expression to human thoughts.', NOW()) ON CONFLICT DO NOTHING;
