INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('978b8f8d-92b2-4cba-8c3c-b7f20a73b59d', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What clever trick did the quick-witted monkey play in mid-stream when the crocodile confessed he was taking him to be killed?', 'The brilliant monkey feigned willingness to sacrifice himself, tricking the gullible reptile into returning to the tree to ''fetch his heart''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2ad1e89-c722-4976-8956-8bae0d9556dc', 'He declared that he had left his heart safely behind on the tree branch, and persuaded the foolish crocodile to swim back to fetch it', true, '978b8f8d-92b2-4cba-8c3c-b7f20a73b59d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('745f1991-d524-42a2-9342-56b958dad539', 'He jumped into the water and drowned the crocodile', false, '978b8f8d-92b2-4cba-8c3c-b7f20a73b59d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70391e91-6d2b-41f4-b520-6dbee9c7b511', 'He hit the crocodile with a stone', false, '978b8f8d-92b2-4cba-8c3c-b7f20a73b59d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ee1fe34-c059-4ac1-9469-138a354b64df', 'He called other monkeys for help', false, '978b8f8d-92b2-4cba-8c3c-b7f20a73b59d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac9e1538-6db6-4b4d-985f-a23ced93d46c', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What did the monkey do the moment the crocodile reached back to the riverbank tree?', 'Reaching safety, the monkey rebuked the treacherous crocodile for his betrayal and ended the friendship forever.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35aa5473-1226-4d3c-9031-7040a6a715fc', 'He leaped up to the safety of the tree branch in a flash, threw down fruit, and permanently terminated their friendship', true, 'ac9e1538-6db6-4b4d-985f-a23ced93d46c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52fd7386-b86e-4145-95e6-731aa27e85fa', 'He gave his heart to the crocodile', false, 'ac9e1538-6db6-4b4d-985f-a23ced93d46c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b0b5fcf-1ba4-4927-b83f-2eff3c7ba53f', 'He jumped into the crocodile''s mouth', false, 'ac9e1538-6db6-4b4d-985f-a23ced93d46c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b45e668-0164-4a22-b546-04df2d49eb2d', 'He invited the crocodile''s wife to the tree', false, 'ac9e1538-6db6-4b4d-985f-a23ced93d46c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9caa416c-a22f-4534-956b-9c4c94884119', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What moral lesson does the Panchatantra classic ''The Monkey and the Crocodile'' teach?', 'Mental agility and composure in crises defeat brute betrayal and treachery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbc89f65-d8e7-46b0-b8c6-c3498d7108be', 'Presence of mind, quick wit, and intelligence can overcome the deadliest danger; a treacherous friend is worse than an open enemy', true, '9caa416c-a22f-4534-956b-9c4c94884119');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37639adb-d0a1-4ff6-ad4f-884967c5275b', 'Crocodiles are the fastest swimmers', false, '9caa416c-a22f-4534-956b-9c4c94884119');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('959cf242-8699-47c8-9eb9-027a5c598cd7', 'Monkeys should never eat fruit', false, '9caa416c-a22f-4534-956b-9c4c94884119');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f828d7b-13a2-409d-b7f4-b265158934e8', 'Trees should not grow near rivers', false, '9caa416c-a22f-4534-956b-9c4c94884119');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0fc27e4-d772-4b0f-91c0-811998d85284', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'In ''Who I Am'', what central message is celebrated through the six unique children (Radha, Nasir, Rohit, Serbjit, Dolma, Peter)?', 'The chapter showcases Howard Gardner''s multiple intelligences: bodily-kinesthetic, naturalist, interpersonal, visual-spatial, and linguistic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('568db5ed-3530-4025-b7de-b17f33626602', 'Every individual child is uniquely talented, has distinct aspirations, intelligences, and ways of viewing the world that deserve celebration', true, 'b0fc27e4-d772-4b0f-91c0-811998d85284');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cda39f0d-1b6e-489b-afee-ed8710cc55c3', 'All children must have the exact same career dream', false, 'b0fc27e4-d772-4b0f-91c0-811998d85284');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0799bce1-294b-47b0-b2e0-f8da0f0bc870', 'Only children who climb trees are smart', false, 'b0fc27e4-d772-4b0f-91c0-811998d85284');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73343c13-6d90-4f9f-bef3-5ec1bdda2af5', 'Children should never share their thoughts', false, 'b0fc27e4-d772-4b0f-91c0-811998d85284');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4abc273-7254-4db9-851d-bf2ee778a966', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'In the poem ''The Wonderful Words'', why does the poet advise: ''Never let a thought shrivel and die for want of a way to say it''?', 'Language empowers humans to liberate imprisoned thoughts into radiant verbal articulation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5b159dd-633c-43e9-a97c-d014562d2d88', 'Because English is a wonderful game of words that allows anyone to express their finest, brightest ideas clearly and beautifully', true, 'f4abc273-7254-4db9-851d-bf2ee778a966');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('019a2ffc-3710-4749-9c56-44fb93fc5dd6', 'Because thoughts can bite you', false, 'f4abc273-7254-4db9-851d-bf2ee778a966');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da568c2d-cb94-4137-ac74-f1e4a8f996d0', 'Because silence is dangerous', false, 'f4abc273-7254-4db9-851d-bf2ee778a966');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('493f73d8-b71b-4850-8c11-2ab7fddf9639', 'Because dictionaries are free', false, 'f4abc273-7254-4db9-851d-bf2ee778a966');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f0485fe0-e2d1-4959-bf7d-fe1db6b66802', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What is Visual-Spatial intelligence, as demonstrated by someone who thinks in pictures, loves maps, diagrams, and visual arts?', 'Visual-spatial learners navigate 3D environments, orient maps, and conceptualize architectural imagery effortlessly.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e01108b-f481-41a5-9d89-4830cf5060b9', 'Visual intelligence', true, 'f0485fe0-e2d1-4959-bf7d-fe1db6b66802');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44ae3972-ccfe-439b-bb39-3fd5c4b9bf06', 'Bodily-Kinesthetic intelligence', false, 'f0485fe0-e2d1-4959-bf7d-fe1db6b66802');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd9209e3-113a-4183-b05d-fb06aa427455', 'Musical intelligence', false, 'f0485fe0-e2d1-4959-bf7d-fe1db6b66802');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b5509d4-5d48-4509-b403-d1ba4045056d', 'Mathematical intelligence', false, 'f0485fe0-e2d1-4959-bf7d-fe1db6b66802');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5ac6b5e-f368-4f5e-9c66-287fe9363fe3', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What is Bodily-Kinesthetic intelligence, as demonstrated by Radha who loves climbing and physical coordination?', 'Bodily-kinesthetic intelligence involves gross and fine motor coordination, physical balance, and tactile mastery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c6a3b60-4234-450a-9609-3c30939f2009', 'The ability to control body movements, physical agility, balance, and handle objects skillfully', true, 'e5ac6b5e-f368-4f5e-9c66-287fe9363fe3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52a6d7f2-d531-4ce6-a923-603b9a159252', 'The ability to solve calculus problems', false, 'e5ac6b5e-f368-4f5e-9c66-287fe9363fe3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e7ae1b2-7d76-4119-8be4-242412e5e160', 'The ability to compose symphony music', false, 'e5ac6b5e-f368-4f5e-9c66-287fe9363fe3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b877ac0a-f781-4f36-b30a-943f64593a8c', 'The ability to speak 10 languages', false, 'e5ac6b5e-f368-4f5e-9c66-287fe9363fe3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('163d79f1-e308-4c0a-bd7e-ea15bc935217', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What is Interpersonal intelligence, as demonstrated by Dolma who loves resolving classmates'' disputes and leading groups?', 'Interpersonal intelligence enables leadership, social empathy, mediation, and group teamwork.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67f7f520-df33-4acb-8543-61678779a772', 'The ability to understand, empathize with, motivate, and collaborate effectively with other people', true, '163d79f1-e308-4c0a-bd7e-ea15bc935217');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cca1270-3315-4c94-a8b7-be8364e99252', 'The ability to talk to oneself only', false, '163d79f1-e308-4c0a-bd7e-ea15bc935217');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5ae4802-9445-4928-a707-659097d388fc', 'The ability to paint portraits', false, '163d79f1-e308-4c0a-bd7e-ea15bc935217');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('393bf483-0654-4b1a-9f36-e03eadf63222', 'The ability to run fast', false, '163d79f1-e308-4c0a-bd7e-ea15bc935217');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d64374d-40ae-4bad-a741-261bdd351bc0', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'Why was the crocodile torn between two conflicting loyalties in the middle of the river?', 'His moral dilemma: honoring sacred friendship versus succumbing to marital pressure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7b3ec64-8cfc-4102-adfd-0f3d35da3779', 'He genuinely loved his loyal friend the monkey, but could not resist or disobey his aggressive, demanding wife', true, '9d64374d-40ae-4bad-a741-261bdd351bc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bba090be-5b35-4be2-b0fb-257f18ae3a8e', 'He wanted to become a vegetarian', false, '9d64374d-40ae-4bad-a741-261bdd351bc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afc025fc-3287-4bd7-b443-f23fdb6a3458', 'He forgot how to swim', false, '9d64374d-40ae-4bad-a741-261bdd351bc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60b64cad-f7e8-492c-85cf-685cd6420ccd', 'He was afraid of water', false, '9d64374d-40ae-4bad-a741-261bdd351bc0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('828ed861-9544-44c2-a61d-c0a9c37528fe', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What does the word ''Preserve'' mean when Nasir talks about cotton seeds?', 'Preservation involves storing and protecting biological germplasm seeds across planting seasons.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56154b9c-bdcf-496b-881b-3cd481232da5', 'To save, maintain, and protect something safely for future use', true, '828ed861-9544-44c2-a61d-c0a9c37528fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('166bbc16-b190-4f9c-9cec-7be76de88e5a', 'To destroy by burning', false, '828ed861-9544-44c2-a61d-c0a9c37528fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a5fefba-777b-4e8f-b0fa-54a9fb53cc0c', 'To throw into the river', false, '828ed861-9544-44c2-a61d-c0a9c37528fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0439aa7b-c47d-44cf-aacf-15a06570ec52', 'To eat immediately', false, '828ed861-9544-44c2-a61d-c0a9c37528fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c685ff9c-0900-4b6b-91bf-e594da1bbb96', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What does the phrase ''to shrivel and die'' mean in ''The Wonderful Words''?', '''Shrivel'' metaphorically depicts unuttered ideas withering away from lack of communicative expression.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62250675-c854-40a7-bc99-03c604c3c1e7', 'To shrink, dry up, wither away, and disappear without being expressed', true, 'c685ff9c-0900-4b6b-91bf-e594da1bbb96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35a9eceb-3566-4478-b1f6-054cce9a0115', 'To grow very large', false, 'c685ff9c-0900-4b6b-91bf-e594da1bbb96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96be5643-d2e0-49ab-8807-b69b58dd172c', 'To sing a song', false, 'c685ff9c-0900-4b6b-91bf-e594da1bbb96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a990cb1-223f-4331-9813-56d5874bb556', 'To fly like a kite', false, 'c685ff9c-0900-4b6b-91bf-e594da1bbb96');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8c7403f1-e7bf-4556-b265-9ec5a078b655', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'Why does Dolma say: ''I know that when I grow up, I will be a great Prime Minister''?', 'Dolma exhibits natural civic responsibility, public problem-solving, and infrastructural vision for society.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ced44d6-c5fb-48d6-88e1-de36efcce6a7', 'Because everyone in school comes to her with problems, teachers trust her to manage things, and she genuinely wants to build better hospitals and roads', true, '8c7403f1-e7bf-4556-b265-9ec5a078b655');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1195eda-c938-4b8b-a0e7-49a1b7b4e8b6', 'Because she wants to be rich and famous', false, '8c7403f1-e7bf-4556-b265-9ec5a078b655');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fad7c5b-34ed-4ef6-b133-063d61a13259', 'Because her parents ordered her to', false, '8c7403f1-e7bf-4556-b265-9ec5a078b655');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2d1d4b8-cc6b-4a01-9977-fa778e6cd30d', 'Because she wants to fly in an aeroplane', false, '8c7403f1-e7bf-4556-b265-9ec5a078b655');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('033be769-06ec-489a-a35f-17c2a36a0ebd', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'In the poem ''The Wonderful Words'', what is described as being ''imprisoned behind your eyes''?', 'The poet portrays unvoiced thoughts as captives in the mind awaiting liberation through eloquent vocabulary.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b0c109c-f84c-476c-9ea5-a65b17691aac', 'Fresh, marvellous new thoughts waiting to be freed by words', true, '033be769-06ec-489a-a35f-17c2a36a0ebd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7bb7775-5739-4176-a5c8-53ac9d4032e2', 'Tears of sadness', false, '033be769-06ec-489a-a35f-17c2a36a0ebd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03607748-940e-4254-9d89-f8d96db3029f', 'Sleep and dreams', false, '033be769-06ec-489a-a35f-17c2a36a0ebd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('910e9cb9-0a42-4fc4-b305-cd1488a8f0a8', 'Old memories', false, '033be769-06ec-489a-a35f-17c2a36a0ebd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43834d17-dd9e-439f-8cba-90a0a22fe591', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What was the crocodile''s emotional state as he swam back to his riverbank lair after being outsmarted by the monkey?', 'The Panchatantra concludes with the crocodile weeping tears of profound regret over the tragic forfeiture of true friendship.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eac56e50-71dd-45d1-be35-60a348e8603a', 'Sadder and wiser — filled with shame, sorrow, and regret for having lost a loyal, lifelong true friend through foolish treachery', true, '43834d17-dd9e-439f-8cba-90a0a22fe591');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db3e7055-b499-47ce-8bcc-f46905e88f48', 'Laughing with great joy', false, '43834d17-dd9e-439f-8cba-90a0a22fe591');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('231fa536-08c6-4573-ab33-de8edaff4205', 'Eager to eat more berries', false, '43834d17-dd9e-439f-8cba-90a0a22fe591');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8af3cc29-99ba-4ca8-bdf6-ec986cc1ef65', 'Singing a battle song', false, '43834d17-dd9e-439f-8cba-90a0a22fe591');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e0013846-c34c-40aa-b43e-20777d4acb26', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What is Naturalist intelligence, as exemplified by Nasir who understands seeds, soil, and agricultural growth?', 'Naturalist intelligence involves attunement to biological ecosystems, flora, fauna, and environmental cycles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0dc287e-01bb-4559-a8c6-e5cb7300acf9', 'The ability to understand, categorize, and appreciate features of the natural environment, plants, and animals', true, 'e0013846-c34c-40aa-b43e-20777d4acb26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f79ca2d-3ab6-4942-9b71-7e47c301cb6d', 'The ability to build tall skyscrapers', false, 'e0013846-c34c-40aa-b43e-20777d4acb26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c84010e8-e49c-4424-af22-673a16b82403', 'The ability to drive trains', false, 'e0013846-c34c-40aa-b43e-20777d4acb26');
