INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ed291f3-67e7-48bd-9fb8-913e40240716', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Medium', 'What is Musical intelligence in Howard Gardner''s theory?', 'Musical intelligence governs auditory harmonic sensitivity, rhythm, pitch discernment, and compositional skill.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95de1b66-4347-4260-a7bb-afc0281f6fa1', 'The capacity to discern pitch, rhythm, timbre, tone, and compose or appreciate musical structures', true, '8ed291f3-67e7-48bd-9fb8-913e40240716');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6041f42-c6c7-43df-8675-256aba725be1', 'The ability to swim fast', false, '8ed291f3-67e7-48bd-9fb8-913e40240716');
