INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a54e5ef0-438d-4b89-b28d-dae6b9f46d32', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Hard', 'In ''The Wonderful Words'', what profound linguistic philosophy does Mary O''Neill advocate?', 'The poem celebrates verbal literacy as the indispensable vehicle for manifesting internal human consciousness.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0c53d82-d57b-43f5-9cfb-04706fa260d6', 'Language is a living creative instrument: we must actively nurture vocabulary so that brilliant human thoughts are not silenced by linguistic poverty', true, 'a54e5ef0-438d-4b89-b28d-dae6b9f46d32');
