INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7aa6a5a6-c452-455b-893f-ebe5c51aa9e7', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Hard', 'Identify the figure of speech in Mary O''Neill''s line: ''Words are the food and dress of thought.''', 'A direct figurative equation comparing verbal words to food (nourishment) and dress (outer form) without using ''like'' or ''as'' is a Metaphor.', NOW()) ON CONFLICT DO NOTHING;
