INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ec94ddbc-7875-4325-871d-e4fd63c02de2', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Hard', 'How does Serbjit constructively channel and regulate his intense emotional frustration when misunderstood?', 'Counting to ten and grounding visual focus is an effective cognitive-behavioral technique for anger management.', NOW()) ON CONFLICT DO NOTHING;
