INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0cf99dd-9ad8-4c10-907e-26b966ad140b', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Hard', 'What is the grammatical function of the underlined clause in: ''Nasir wants to know *how seeds can be collected for future farming*.''', 'The embedded interrogative clause functions as the direct object of the transitive verb ''know'', making it a Noun Clause.', NOW()) ON CONFLICT DO NOTHING;
