INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea72e208-7d62-41b7-b818-3b0bdcb0b74f', 'Class 6', 'English', 'Chapter 6: Who I Am', 'Hard', 'In ''The Monkey and the Crocodile'', what tragic philosophical reality did the crocodile realize upon reaching the bank?', 'Betraying moral integrity for unholy appeasement results in irreversible spiritual and relational bankruptcy.', NOW()) ON CONFLICT DO NOTHING;
