INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c2a8420-9784-454b-8c75-4605350cc6fb', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Medium', 'Which cave site in Madhya Pradesh contains the oldest prehistoric rock art paintings in India (some dating back over 10,000 years to the Upper Paleolithic and Mesolithic eras)?', 'Discovered by V.S. Wakankar in 1957, Bhimbetka''s 750 rock shelters depict early human hunting scenes, animal life, and community dances in natural mineral pigments.', NOW()) ON CONFLICT DO NOTHING;
