INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f000187-bb74-4f04-bcd2-68e4a687a6a9', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Medium', 'Which historic monument in Madurai, Tamil Nadu is famous for its 14 towering colourful Gopurams (temple gateway towers) and the iconic Hall of Thousand Pillars?', 'Meenakshi Sundareswarar Temple in Madurai on the Vaigai River is an epicenter of classical Dravidian sculpture and Pandyan architecture.', NOW()) ON CONFLICT DO NOTHING;
