INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('142ef8e3-0583-44c2-ab4b-6b7043b1cc32', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Medium', 'Which ancient iron pillar located in the Qutub Minar complex in Delhi has stood exposed to open weather for over 1,600 years without rusting, demonstrating ancient Indian metallurgical mastery?', 'The 6-tonne wrought iron pillar developed a passive protective amorphous iron hydrogen phosphate hydrate (misawite) film preventing corrosion.', NOW()) ON CONFLICT DO NOTHING;
