INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('664454fb-d748-48a9-8c66-ebd897136c05', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Medium', 'What is the 8th-century shore-facing monolithic and structural temple complex in Mamallapuram (Mahabalipuram), Tamil Nadu, built by the Pallava Dynasty King Narasimhavarman II?', 'The Shore Temple overlooks the Bay of Bengal, marking the structural pinnacle of Pallava granite temple engineering.', NOW()) ON CONFLICT DO NOTHING;
