INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0047b77e-797e-4468-b4cc-4cea3028488e', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'What is the architectural name of the ancient open-air bas-relief rock sculpture in Mahabalipuram depicting the descent of the sacred river Ganga onto Earth, measuring 27m by 9m?', 'Carved onto two massive pink granite boulders with a natural cleft representing the descending celestial river, it depicts gods, gandharvas, and elephants.', NOW()) ON CONFLICT DO NOTHING;
