INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db14a466-d0c5-482b-b0fb-47716aa8460f', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'Match Column I (Iconic Monuments) with Column II (Dynasties / Rulers who built them):
(a) Kailash Rock Temple (Ellora) -> (i) Chola Dynasty (Rajaraja I)
(b) Brihadisvara Temple (Thanjavur) -> (ii) Rashtrakuta Dynasty (Krishna I)
(c) Konark Sun Temple (Odisha)    -> (iii) Mughal Emperor Shah Jahan
(d) Red Fort (Delhi)             -> (iv) Eastern Ganga Dynasty (Narasimhadeva I)', 'Kailash = Rashtrakuta; Brihadisvara = Chola; Konark = Eastern Ganga; Red Fort = Mughal (Shah Jahan).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6aca4dd5-2d38-43d6-b25d-855465d0e73f', 'a-(ii), b-(i), c-(iv), d-(iii)', true, 'db14a466-d0c5-482b-b0fb-47716aa8460f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d11af9bf-0d0b-4321-89e8-79f21688d451', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'db14a466-d0c5-482b-b0fb-47716aa8460f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4229438f-a8a2-4cb7-9416-2502d29f7d93', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'db14a466-d0c5-482b-b0fb-47716aa8460f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5d01aca-14e1-48ea-9558-754eb8d650fa', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'db14a466-d0c5-482b-b0fb-47716aa8460f');
