INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('349afa76-60ab-4220-882d-63329e5fd1d0', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'What is the famous acoustic phenomenon of the whispering gallery inside the massive dome of the Gol Gumbaz (mausoleum of Mohammed Adil Shah in Bijapur, Karnataka)?', 'The acoustic geometry of Gol Gumbaz''s 44-meter unsupported acoustic dome channels sound waves around smooth circular gallery perimeters with minimal decay.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('308a221b-0de0-4c7c-9b17-8b015a073783', 'The faintest whisper at one side of the 44-meter circular gallery can be heard crystal clear on the diametrically opposite side, and a single handclap echoes 7 to 10 times', true, '349afa76-60ab-4220-882d-63329e5fd1d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d061ad7d-5c01-495e-bafb-fc1511286c49', 'Sound disappears completely', false, '349afa76-60ab-4220-882d-63329e5fd1d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad96d382-9f7f-4b0f-b9f2-2454b817905e', 'It turns human voices into bird songs', false, '349afa76-60ab-4220-882d-63329e5fd1d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93879a43-34ae-47aa-9c6e-cfedea2c15b6', 'Only whispers in Persian can be heard', false, '349afa76-60ab-4220-882d-63329e5fd1d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6de8d2a0-3589-43f5-b0d7-9e2d4cbaac1d', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'Which 15th-century nine-storey marble and red sandstone victory tower in Chittorgarh Fort, Rajasthan, was built by Maharana Kumbha to commemorate his triumph over the combined Sultanate armies of Malwa and Gujarat?', 'Vijay Stambha is a 37.2-meter high nine-storeyed architectural encyclopedia of Hindu iconography and Vaishnava sculpture completed in 1448.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6e13a11-c479-4d63-997f-7aede09d0cb9', 'Vijay Stambha (Tower of Victory)', true, '6de8d2a0-3589-43f5-b0d7-9e2d4cbaac1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ec38da5-b4d7-431e-8d96-b565e4aae7af', 'Kirti Stambha', false, '6de8d2a0-3589-43f5-b0d7-9e2d4cbaac1d');
