INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f0f8c949-32e2-4f4e-a005-f1b4ee93707b', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'Which cave island in Mumbai harbor features the colossal 6-meter high three-headed rock-cut relief sculpture of ''Trimurti'' (Sadashiva representing creation, preservation, and destruction)?', 'Elephanta''s rock-cut monolithic cavern features the celebrated 20-foot high masterpiece sculpture of three-headed Shiva (Aghora, Tatpurusha, and Vamadeva).', NOW()) ON CONFLICT DO NOTHING;
