INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5fda3ebd-0c13-4cbc-9068-2f563f76fd75', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'Which ancient university in Bihar, founded by Gupta Emperor Kumaragupta I in the 5th century CE, was a renowned global center of learning that housed 10,000 students and 2,000 scholars from across Asia?', 'Nalanda was a premier residential monastic university with a vast nine-storey library (Dharmaganja) visited by Chinese pilgrim Xuanzang.', NOW()) ON CONFLICT DO NOTHING;
