INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('819e8a76-5977-44bb-89f5-2e031dbb5fe2', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'What is the unique structural engineering feature of the famous 18th-century stepwell ''Chand Baori'' in Abhaneri, Rajasthan?', 'Chand Baori''s 3,500 geometric zigzagging steps create a mesmerizing optical geometry designed to harvest rainwater in drought-prone eastern Rajasthan.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5871faae-4b7c-4422-a95a-13b1e18e996d', 'It consists of 3,500 narrow, perfectly symmetrical stone steps arranged across 13 storeys plunging 20 meters deep into the earth', true, '819e8a76-5977-44bb-89f5-2e031dbb5fe2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1e3a9b1-973f-4ab7-93ac-dde6f5c4280e', 'It was built entirely upside down without water', false, '819e8a76-5977-44bb-89f5-2e031dbb5fe2');
