INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0445396-6f05-4928-a466-3587ec2fd8f1', 'It has no stairs', false, '819e8a76-5977-44bb-89f5-2e031dbb5fe2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9b77693-ea6e-4855-8fe5-1c0c0ae7d4c7', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'Which temple complex in Delhi and Gujarat, built by BAPS Swaminarayan Sanstha, holds the Guinness World Record as the world''s largest comprehensive Hindu temple campus, carved entirely from Rajasthani pink sandstone and Italian Carrara marble without using any structural steel?', 'Akshardham New Delhi was constructed strictly following ancient Shilpa Shastra interlocking stone-joinery without any ferrous structural metal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4be587aa-c90a-499b-95e4-b1b25163c06f', 'Akshardham Temple', true, 'e9b77693-ea6e-4855-8fe5-1c0c0ae7d4c7');
