INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8789bca9-edcf-4a26-99e5-fa0f2f8486ab', 'Class 6', 'GK', 'Chapter 6: Famous Monuments, Heritage & Architecture of India', 'Hard', 'Which Victorian Gothic railway terminus in Mumbai, designed by Frederick William Stevens and completed in 1887, is a UNESCO World Heritage site blending Victorian Italianate High Gothic architecture with traditional Indian stone palace craftsmanship?', 'CSMT is characterized by its grand stone dome, turrets, pointed arches, stained glass, and decorative wood and brass carvings.', NOW()) ON CONFLICT DO NOTHING;
