INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7abe9d8-9ea6-4449-90a4-cfdc6c5160c0', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'Any natural elevation of the Earth''s surface considerably higher and steeper than the surrounding area, with a small summit and broad base, is a:', 'A mountain is a steep natural topographic elevation rising significantly above the surrounding terrain.', NOW()) ON CONFLICT DO NOTHING;
