INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e8ab765-8311-45bb-900d-93927ce897e1', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'Permanently frozen rivers of solid ice moving slowly down high mountain slopes are called:', 'Glaciers are persistent masses of recrystallized ice flowing downhill under gravity in high alpine zones.', NOW()) ON CONFLICT DO NOTHING;
