INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5f74fec-7f98-4aa5-9110-e7f00da276a5', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'Mountains formed by the tectonic folding and buckling of crustal rock layers under intense compressive forces are called:', 'Fold mountains form at convergent plate boundaries where crustal sediments buckle into anticlines and synclines.', NOW()) ON CONFLICT DO NOTHING;
