INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f3701dc-10d8-45fd-9a4e-d2e15c5f5d7c', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'What are the two major youthful fold mountain systems in Asia and Europe characterized by rugged relief and high conical peaks?', 'The Himalayas and Alps are young Cenozoic fold mountain belts with sharp soaring peaks and deep gorges.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6328201-0107-4d5e-baa0-4cb367e248d1', 'The Himalayas (Asia) and the Alps (Europe)', true, '8f3701dc-10d8-45fd-9a4e-d2e15c5f5d7c');
