INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f71ee055-c763-4cd4-9fd7-21d866146c4b', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'An elevated flat-topped tableland standing abruptly above the surrounding area with one or more steep sides is called a:', 'A plateau is a high-altitude, flat-topped geomorphic tableland bounded by steep escarpments.', NOW()) ON CONFLICT DO NOTHING;
