INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d90b298f-bc4c-4678-aa1b-0468f05cc7ec', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'What is the highest plateau in the world (often crowned the ''Roof of the World'') with an elevation of 4,000 to 6,000 meters above sea level?', 'The Tibetan Plateau covers 2.5 million km² at an average altitude exceeding 4,500 m.', NOW()) ON CONFLICT DO NOTHING;
