INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d1699fb8-4ca0-48cd-a72c-b49ac88439fe', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'Why are river Plains the MOST DENSELY POPULATED regions in the world?', 'Deep alluvial topsoils, perennial irrigation, and flat topography support high-yield agriculture and urban transport infrastructure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9772805d-b0aa-4fab-9be2-3cbeb16e5a18', 'Extremely fertile alluvial soil, abundance of fresh river water, level flat land easy for agriculture, transport networks, and building cities', true, 'd1699fb8-4ca0-48cd-a72c-b49ac88439fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a664d87-457b-479b-928a-542424602db8', 'Because plains have no trees', false, 'd1699fb8-4ca0-48cd-a72c-b49ac88439fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08bf3c8b-fa53-4777-a512-322952b79d99', 'Because mountains are too hot', false, 'd1699fb8-4ca0-48cd-a72c-b49ac88439fe');
