INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f532f357-cbf2-44a1-94c8-c7ef59c60f42', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Easy', 'Mountains formed due to the accumulation and cooling of molten volcanic lava, ash, and pyroclastic ejecta around a volcanic vent are:', 'Volcanic stratocones (Kilimanjaro, Fuji, Vesuvius) are constructed from repeated cooled lava flows and tephra.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7c2a7bb-9984-4982-8146-d911796fd699', 'Volcanic Mountains (e.g., Mount Kilimanjaro in Africa, Mount Fujiyama in Japan)', true, 'f532f357-cbf2-44a1-94c8-c7ef59c60f42');
