INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e17d43dd-a309-418f-9ef8-d88e18213219', 'Subduction', false, '3eb338c8-3017-4e9c-8a87-c1a644cfb4b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54ab2bbe-da9c-4a0a-8061-7d2b74bc7ac0', 'Weathering', false, '3eb338c8-3017-4e9c-8a87-c1a644cfb4b9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cff55412-8f85-4d8e-97cd-63e44459a996', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'How are ''Block Mountains'' formed when large sections of the Earth''s crust crack, fault, and displace vertically?', 'Tensional crustal faulting raises horst block massifs (e.g. Vosges, Black Forest) and drops graben rift valleys (Rhine Valley).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05182abd-b381-406f-9406-d45d6c55196d', 'The uplifted block between faults is called a ''Horst'' (Block Mountain) and the sunken depressed valley between them is called a ''Graben'' (Rift Valley)', true, 'cff55412-8f85-4d8e-97cd-63e44459a996');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b321ef15-04f3-4554-8b42-44e0bf9fb63b', 'Lava explodes into the sky', false, 'cff55412-8f85-4d8e-97cd-63e44459a996');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69060c70-f3f6-4588-a116-eaf9919f176f', 'Rivers cut through soft clay', false, 'cff55412-8f85-4d8e-97cd-63e44459a996');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a9533fc-7c34-4046-826c-e5367b7dc0b4', 'Glaciers melt into water', false, 'cff55412-8f85-4d8e-97cd-63e44459a996');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bd3587b7-a873-436a-a3c4-4cac82ee6f29', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Which of the following mountain ranges in Europe are classic examples of Block Mountains and an associated Rift Valley?', 'The Rhine Graben rift valley is bounded on either side by the uplifted Vosges and Black Forest horst fault blocks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa1b442d-c541-474e-968a-1c7672eb13b8', 'The Rhine Valley and the Vosges / Black Forest mountains', true, 'bd3587b7-a873-436a-a3c4-4cac82ee6f29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eadbcb5c-cee9-4859-b96f-88be1d3e8a03', 'The Alps and Himalayas', false, 'bd3587b7-a873-436a-a3c4-4cac82ee6f29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b460ec46-af36-4cba-b473-2f98185a7a5d', 'The Urals and Aravalli', false, 'bd3587b7-a873-436a-a3c4-4cac82ee6f29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c547a0a3-a2eb-4296-9085-44128c64ffcc', 'The Andes and Rockies', false, 'bd3587b7-a873-436a-a3c4-4cac82ee6f29');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d795ab8b-3431-4f97-99c3-c57ed0daa015', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Why is the ancient Aravalli Range in India low, rounded, and devoid of sharp conical peaks compared to the towering Himalayas?', 'Proterozoic orogenies created the Aravallis, which over hundreds of millions of years eroded into relict peneplains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c610e1f6-4f48-4c62-ba28-aa965e4e1417', 'It is one of the oldest fold mountain systems in the world that has suffered millions of years of continuous weathering and erosion (Old Fold Mountains)', true, 'd795ab8b-3431-4f97-99c3-c57ed0daa015');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c1114d9-405b-40e0-b1f5-66510cedd97e', 'It was built by volcanic lava', false, 'd795ab8b-3431-4f97-99c3-c57ed0daa015');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38d1494d-29f9-40ee-9d15-e6040d28625f', 'It was built by human hands', false, 'd795ab8b-3431-4f97-99c3-c57ed0daa015');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57fe5f8f-e7dc-40be-a325-d9de456d6da2', 'It sank into the ocean', false, 'd795ab8b-3431-4f97-99c3-c57ed0daa015');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7768393e-d724-4c74-87f6-7ede084f1a57', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Why are Plateaus world-renowned as the richest storehouses of valuable mineral deposits?', 'Cratonic basalt and crystalline shields in plateaus host vast metallic ores (e.g. Chota Nagpur plateau iron/coal, African gold/diamonds).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('780643b4-79b5-40cb-bf6f-c6c7bd1c092d', 'Ancient volcanic and metamorphic activity concentrated rich ores (e.g. Iron, Coal, Manganese, Gold, Diamonds) in plateau rocks', true, '7768393e-d724-4c74-87f6-7ede084f1a57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dd5f14e-44c9-4531-beb9-0a32d84956c0', 'Because rivers wash gold onto plateaus', false, '7768393e-d724-4c74-87f6-7ede084f1a57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6ce2576-fc93-4e65-9871-4c3978b1c146', 'Because plateaus are made of plastic', false, '7768393e-d724-4c74-87f6-7ede084f1a57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13d29e96-c259-495a-88f8-1102bc2c92f8', 'Because plants turn into diamonds on plateaus', false, '7768393e-d724-4c74-87f6-7ede084f1a57');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cee98605-0ace-4025-93aa-9a7daef43f0a', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Which mineral-rich plateau in eastern India is famous as the ''Ruhr of India'' for its massive reserves of iron ore, coal, bauxite, and manganese?', 'The Gondwana formations and Dharwar shield of the Chota Nagpur Plateau supply India''s primary industrial heavy metals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('141810fa-fca8-40de-a2a3-115a0d9f696e', 'Chota Nagpur Plateau (Jharkhand/Odisha/Chhattisgarh)', true, 'cee98605-0ace-4025-93aa-9a7daef43f0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d250896-58b2-4a9d-8e13-1b8a57e92765', 'Malwa Plateau', false, 'cee98605-0ace-4025-93aa-9a7daef43f0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a024e60-c0cc-49d4-8b92-f61eef67cf0f', 'Shillong Plateau', false, 'cee98605-0ace-4025-93aa-9a7daef43f0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22914ff6-37d7-44a8-b3a4-f553f71eaec3', 'Ladakh Plateau', false, 'cee98605-0ace-4025-93aa-9a7daef43f0a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea54ef80-f548-49a3-bdb0-440fa17d2520', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'What is the famous scenic waterfall located on the Subarnarekha River in the Chota Nagpur Plateau of Jharkhand?', 'Hundru Falls plunges 98 meters over a steep escarpment of the Subarnarekha River near Ranchi.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a792308-5c8d-41fb-a308-1e4b32395232', 'Hundru Falls', true, 'ea54ef80-f548-49a3-bdb0-440fa17d2520');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c963fc9-a071-4baf-876d-e7d243d0ad80', 'Jog Falls', false, 'ea54ef80-f548-49a3-bdb0-440fa17d2520');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be767334-9978-4a1c-9e48-422de81ad418', 'Dhuandhar Falls', false, 'ea54ef80-f548-49a3-bdb0-440fa17d2520');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('040648c0-dfd7-4307-a62a-0b85a576d9c1', 'Nohkalikai Falls', false, 'ea54ef80-f548-49a3-bdb0-440fa17d2520');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('08897e3e-ee0d-4d8e-bd36-485a58e1f996', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'What famous waterfall on the Sharavathi River in the Western Ghats plateau of Karnataka plunges 253 meters in four cascades?', 'Jog Falls cascades down the rugged western plateau escarpment in four torrents: Raja, Roarer, Rocket, and Rani.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2dfdd5b-a234-4c1f-842a-ce2c5f9d3ce6', 'Jog Falls (Gersoppa Falls)', true, '08897e3e-ee0d-4d8e-bd36-485a58e1f996');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09a7ca24-d429-429e-bfc2-cf992eec720b', 'Hundru Falls', false, '08897e3e-ee0d-4d8e-bd36-485a58e1f996');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8550a755-1b6e-4708-9611-c6504c6430dc', 'Shivanasamudra Falls', false, '08897e3e-ee0d-4d8e-bd36-485a58e1f996');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9bb7dd9-5775-4ce0-a506-8fb82568133f', 'Dudhsagar Falls', false, '08897e3e-ee0d-4d8e-bd36-485a58e1f996');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5065d1ef-b99a-4fd3-9676-24eb7bad64d0', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Why are the volcanic Black Soil (Regur soil) areas of the Deccan Plateau highly prized for agriculture, especially for growing Cotton?', 'Montmorillonite-rich basaltic regur soils possess exceptional cation exchange capacity and hygroscopic moisture retention ideal for cotton.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fc54a6b-877a-431f-ba0c-15e66e41e163', 'Formed from weathered volcanic basalt lava, black soil is exceptionally rich in clay minerals, highly fertile, and retains moisture for long durations', true, '5065d1ef-b99a-4fd3-9676-24eb7bad64d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39c2463a-fd12-44a1-ad4d-5ef947740b54', 'Because black soil has no water', false, '5065d1ef-b99a-4fd3-9676-24eb7bad64d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcfdad19-7818-43db-857d-dce1a32a1069', 'Because black soil turns white in winter', false, '5065d1ef-b99a-4fd3-9676-24eb7bad64d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b314ee9-e82b-45cd-9c4e-1e160a471e95', 'Because it contains natural dye', false, '5065d1ef-b99a-4fd3-9676-24eb7bad64d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74616b0a-9520-4ff1-be66-3b77e968d630', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'How did the great Northern Plains of India (Indo-Gangetic-Brahmaputra Plains) form over geological epochs?', 'Continuous aggradation of fertile alluvium in the Himalayan foredeep depression by the Indus, Ganga, and Brahmaputra formed these vast plains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0577394-8e4e-455f-8c06-f142840a1b77', 'Perennial Himalayan and peninsular rivers deposited millions of tonnes of fine silt, clay, and sand (Alluvium) in a vast subsiding foreland basin over millions of years', true, '74616b0a-9520-4ff1-be66-3b77e968d630');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4eaea00-cf07-4d3c-a3a3-ac17a489de15', 'By volcanic lava filling the sea', false, '74616b0a-9520-4ff1-be66-3b77e968d630');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f54c717-ec96-489b-b3bd-052caa127f62', 'By wind blowing sand from the Thar desert', false, '74616b0a-9520-4ff1-be66-3b77e968d630');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7e1afbb-d921-4598-a28e-b5e24e2f3072', 'By glaciers melting in one day', false, '74616b0a-9520-4ff1-be66-3b77e968d630');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91abcfe8-2d88-4ecf-9761-5da659c72c29', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Which vast plain in China is formed by the extensive alluvial silt deposition of the Yangtze and Yellow (Huang He) rivers?', 'The densely populated North China Plain was built by loess silt transport and flood deposits of the Huang He and Yangtze.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cf945e2-b4f1-4184-b66b-a46525883f35', 'Yangtze / North China Plain', true, '91abcfe8-2d88-4ecf-9761-5da659c72c29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e375f71-590c-406a-a93a-a2a97e9862c3', 'Siberian Plain', false, '91abcfe8-2d88-4ecf-9761-5da659c72c29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('334b5ae8-be04-4696-9f49-cad3c1c7718c', 'Manchurian Plain', false, '91abcfe8-2d88-4ecf-9761-5da659c72c29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('904a5377-485b-404b-924e-2b6c093c0af6', 'Gobi Plain', false, '91abcfe8-2d88-4ecf-9761-5da659c72c29');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98faca6c-a7e2-41f4-b55a-108aa4aff7ac', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'What are the two major continuous processes constantly shaping and modifying the Earth''s surface landforms?', 'Internal tectonic forces (volcanism, orogeny) uplift relief, while external agents (water, wind, ice) erode and level the terrain.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f12c503-6709-4139-a012-55313525cd8f', 'Internal (Endogenic) processes causing crustal uplift/sinking AND External (Exogenic) processes of erosion and deposition', true, '98faca6c-a7e2-41f4-b55a-108aa4aff7ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47ac83cb-875c-481b-91d9-7c71920dddce', 'Solar eclipses and lunar tides', false, '98faca6c-a7e2-41f4-b55a-108aa4aff7ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f68d8442-ec1b-4a44-9a6b-d86db6c19eb5', 'Ocean waves and lightning', false, '98faca6c-a7e2-41f4-b55a-108aa4aff7ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('519821b4-d549-425c-b43c-4924e3767110', 'Plant growth and animal walking', false, '98faca6c-a7e2-41f4-b55a-108aa4aff7ac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a71884a-2e2c-4a41-9848-0b845794dd72', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Why do Mountain regions generally have very sparse human populations compared to Plains?', 'Steep slope gradients, severe weather, mass-wasting hazards, and logistical construction barriers severely limit demographic carrying capacity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d822871d-53e7-4dce-8430-ee927ec4d1df', 'Harsh freezing climate, steep rocky slopes unsuitable for farming, thin infertile soil, and extreme difficulty in building transport roads and railways', true, '7a71884a-2e2c-4a41-9848-0b845794dd72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c80403d0-f3bc-4c4a-8c90-7a22f8c44c8b', 'Because mountains have no water', false, '7a71884a-2e2c-4a41-9848-0b845794dd72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7d2221a-676c-4b11-b8d8-f68807497f4e', 'Because mountains move every week', false, '7a71884a-2e2c-4a41-9848-0b845794dd72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4fc5787-8893-4043-bff8-912f547ef147', 'Because wild animals do not allow humans', false, '7a71884a-2e2c-4a41-9848-0b845794dd72');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b13ecb74-5366-43f3-9b4b-8f59ebbabf18', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'What agricultural technique is practiced by farmers on steep mountain hillsides to carve out flat step-like fields and prevent soil erosion?', 'Contour bench terracing creates flat horizontal steps, slowing runoff velocity and conserving irrigation water on steep slopes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06fdb630-c1a8-4982-809f-f7a9be2bd63f', 'Terrace Farming (Step Cultivation)', true, 'b13ecb74-5366-43f3-9b4b-8f59ebbabf18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84b6ac3e-647e-421a-83a9-af98f4b18e08', 'Strip Mining', false, 'b13ecb74-5366-43f3-9b4b-8f59ebbabf18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abbcbdbb-1012-40e0-978c-1888fc2d23d4', 'Slash and Burn', false, 'b13ecb74-5366-43f3-9b4b-8f59ebbabf18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4408a6e0-51e5-4e38-961c-fa20e9f125cd', 'Hydroponics', false, 'b13ecb74-5366-43f3-9b4b-8f59ebbabf18');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22e1931c-968c-497b-9b2b-1e6a276e7dc0', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Which of the following mountain sports and tourism activities are popular in high snow-covered mountains?', 'High alpine relief and snow-covered slopes provide ideal environments for winter sports, climbing expeditions, and adventure tourism.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb664fa6-a6df-45c8-b732-c06b48690b9c', 'Skiing, Paragliding, Mountaineering, and River Rafting', true, '22e1931c-968c-497b-9b2b-1e6a276e7dc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f5f4457-c459-4565-8efc-1ff4e20c4e8f', 'Deep sea diving', false, '22e1931c-968c-497b-9b2b-1e6a276e7dc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c633055d-aa6b-4702-969e-369be7e409f7', 'Desert dune bashing', false, '22e1931c-968c-497b-9b2b-1e6a276e7dc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e592220c-33da-40ed-bb17-c3247a7f4e3b', 'Submarine racing', false, '22e1931c-968c-497b-9b2b-1e6a276e7dc0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8cfb1e4d-ece5-4b0b-8cd7-b56366be78ec', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'Why are mountains rightly called ''Storehouses of Water'' for continental river systems?', 'Glacial meltwaters and orographic rainfall in mountain catchments sustain perennial river systems (Ganga, Indus, Brahmaputra).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5f0711c-018b-42f5-82b1-e4d9b6105405', 'Vast glaciers on high peaks store frozen freshwater that melts in summer, feeding perennial rivers that provide drinking and irrigation water to millions downstream', true, '8cfb1e4d-ece5-4b0b-8cd7-b56366be78ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fb0740a-e5ab-49eb-b8c6-fb040a9f5aea', 'Mountains pump water from the center of Earth', false, '8cfb1e4d-ece5-4b0b-8cd7-b56366be78ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a234b364-437f-44fa-b559-55fe876008d5', 'Mountains make water from rocks', false, '8cfb1e4d-ece5-4b0b-8cd7-b56366be78ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6045d077-1a45-45c4-90fb-3af1f285abb2', 'Mountains stop all clouds permanently', false, '8cfb1e4d-ece5-4b0b-8cd7-b56366be78ec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a68a4c44-728a-4e04-aede-adf1ca6e696b', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Medium', 'What is the crucial difference between a Mountain and a Hill?', 'Standard geographic conventions classify land elevations with steep slopes rising above 600 meters as mountains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f1f1578-98c1-484a-8f61-2c2886291096', 'A hill is a land surface with a rounded summit rising moderately above surrounding areas, whereas a steep hill with an elevation of more than 600 meters is classified as a Mountain', true, 'a68a4c44-728a-4e04-aede-adf1ca6e696b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cab86f0-d757-4acc-aaa5-e00f58b6b4a4', 'Hills are made of ice and mountains of rock', false, 'a68a4c44-728a-4e04-aede-adf1ca6e696b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11e82f55-9c94-49a1-b9f9-5e0f12075728', 'Hills only exist in oceans', false, 'a68a4c44-728a-4e04-aede-adf1ca6e696b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6d59803-a068-4f96-bc5d-7a33032db1bc', 'There is no difference', false, 'a68a4c44-728a-4e04-aede-adf1ca6e696b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('925fa582-ac8c-4c6e-9781-17fb11cfb055', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98b69321-2d8b-4c1c-9615-4fbe0c3e31e7', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '925fa582-ac8c-4c6e-9781-17fb11cfb055');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fdac37d-e20e-4624-bc62-39389b1bd1d8', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '925fa582-ac8c-4c6e-9781-17fb11cfb055');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a99ef65-be07-40b0-9c20-78b004b6d142', '(A) is true, but (R) is false.', false, '925fa582-ac8c-4c6e-9781-17fb11cfb055');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dffdebd-6777-4449-b73e-1d7c874ff1b8', '(A) is false, but (R) is true.', false, '925fa582-ac8c-4c6e-9781-17fb11cfb055');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17e86649-d61e-41eb-bf27-67f9d09eb9f7', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'Spot the IMPOSTER in the following group of mountains classified by their geological type:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d242846d-6bad-4e06-8ac7-9decff29a4e8', 'Himalayas (Fold)', false, '17e86649-d61e-41eb-bf27-67f9d09eb9f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28ba5eda-4784-45c4-a7ae-b694de9cd6a0', 'Alps (Fold)', false, '17e86649-d61e-41eb-bf27-67f9d09eb9f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62c05d40-e9d5-40a5-bfd8-e958ce6b054d', 'Rockies (Fold)', false, '17e86649-d61e-41eb-bf27-67f9d09eb9f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48cff6ae-f927-430d-9192-90160eaf4d0c', 'Mount Kilimanjaro (Fold)', true, '17e86649-d61e-41eb-bf27-67f9d09eb9f7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fcaaf3b-cd56-49c1-b983-06071b17c104', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'A tectonic geomorphologist analyzes the Rhine Valley in Germany and the Vosges Mountain in France. What structural landform pair is represented?', 'Parallel extensional normal faulting dropped the central Rhine graben while leaving the adjacent Vosges and Black Forest horst blocks elevated.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d91b95a-f4e6-4b19-854a-665f5f3469b6', 'Rhine Valley = Graben (Rift Valley) ; Vosges = Horst (Block Mountain)', true, '7fcaaf3b-cd56-49c1-b983-06071b17c104');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa478500-a007-4bbd-8e02-c22d391d0ec8', 'Rhine Valley = Horst ; Vosges = Graben', false, '7fcaaf3b-cd56-49c1-b983-06071b17c104');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29f97903-389c-4bee-9777-9e7cab3985f4', 'Both are Fold Mountains', false, '7fcaaf3b-cd56-49c1-b983-06071b17c104');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c045327-1f6d-4e15-aded-ed4faf55ecec', 'Both are Volcanic stratocones', false, '7fcaaf3b-cd56-49c1-b983-06071b17c104');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ecae79c-2e2f-4a7f-8b42-a117f97d8258', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'Match Column I (Mountain Systems) with Column II (Geological Types & Continents):
(a) Mount Fujiyama -> (i) Old Fold Mountain (India)
(b) Himalayas       -> (ii) Volcanic Mountain (Japan)
(c) Vosges          -> (iii) Young Fold Mountain (Asia)
(d) Aravalli        -> (iv) Block Mountain (Europe)', 'Fujiyama = Volcanic; Himalayas = Young Fold; Vosges = Block; Aravalli = Old Fold.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db6ce6a5-0bbc-4700-8daa-7996337ced33', 'a-(ii), b-(iii), c-(iv), d-(i)', true, '7ecae79c-2e2f-4a7f-8b42-a117f97d8258');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51e0e72d-4fcf-4c05-8f79-12d093256266', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '7ecae79c-2e2f-4a7f-8b42-a117f97d8258');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('470038d3-d87d-4666-afc0-bb74c5743ec8', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '7ecae79c-2e2f-4a7f-8b42-a117f97d8258');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aaa80850-944f-4f45-bb2e-6e3f69f5aa7d', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '7ecae79c-2e2f-4a7f-8b42-a117f97d8258');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62733d10-2b00-4de6-aef0-2ef1f363e305', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54aa470c-99a2-46b1-bb13-4ee6f3c4e0bd', 'Statements 1 and 2 only', true, '62733d10-2b00-4de6-aef0-2ef1f363e305');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5250c1e8-75bf-493c-8327-d6d39be17787', 'Statements 2 and 3 only', false, '62733d10-2b00-4de6-aef0-2ef1f363e305');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71dc0b5e-1c3b-4906-b3c9-5d9631f22553', 'Statements 1 and 3 only', false, '62733d10-2b00-4de6-aef0-2ef1f363e305');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffc8604b-4aae-49ba-89f7-e64e1fe17ca2', 'All Statements 1, 2, and 3', false, '62733d10-2b00-4de6-aef0-2ef1f363e305');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31ce4c5b-777c-4ffc-81a2-c432de9f0ed8', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'Why is building linear transport infrastructure (like multi-lane highways and broad-gauge railways) exponentially more expensive and technically difficult in mountainous terrain than in flat plains?', 'Steep gradients, slope instability, and seismic hazards necessitate complex civil engineering (tunnels, viaducts, avalanche sheds).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28e603da-125b-4bb9-a32a-0dcde2c7e616', 'Rugged topography demands costly construction of deep tunnels, high viaduct bridges, slope stabilization against landslides, and steep gradient switchbacks', true, '31ce4c5b-777c-4ffc-81a2-c432de9f0ed8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30057ee1-440c-48ed-8eba-2426b11141dd', 'Because mountain stone cannot be cut', false, '31ce4c5b-777c-4ffc-81a2-c432de9f0ed8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2714a216-794e-46e2-b396-90436132c4f8', 'Because trains cannot run at high altitudes', false, '31ce4c5b-777c-4ffc-81a2-c432de9f0ed8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2538667d-6388-4438-aa43-52dcae50f866', 'Because concrete melts in cold air', false, '31ce4c5b-777c-4ffc-81a2-c432de9f0ed8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d1cf9cb-589e-4863-afe1-ca39805ec08d', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'What is the primary ecological hazard caused by reckless deforestation, quarrying, and unplanned concrete construction on mountain slopes?', 'Stripping stabilizing vegetative root matrices triggers mass-wasting debris flows, soil creep, and deadly landslides during monsoons.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('458c3b2f-f8c7-4d25-bf4d-5dab58de98c6', 'Severe slope destabilization triggering catastrophic Landslides, flash floods, topsoil erosion, and loss of human settlements', true, '5d1cf9cb-589e-4863-afe1-ca39805ec08d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b1f4f92-f6ea-4975-b3b1-b40af0da8ba4', 'The mountain turning into a volcano', false, '5d1cf9cb-589e-4863-afe1-ca39805ec08d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc5050b9-b062-472f-a66d-04c395ecb62f', 'The mountain flying into space', false, '5d1cf9cb-589e-4863-afe1-ca39805ec08d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58514679-adbe-44e3-9b31-88b524e00cbe', 'Rivers turning into ice permanently', false, '5d1cf9cb-589e-4863-afe1-ca39805ec08d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f6ad556-33f7-41c7-a611-a5cb032d112d', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'Consider four major plateaus of the world:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16dcecb1-b9e8-4d20-8cfa-9ef7fdc24378', 'Plateau 1 (Tibetan Plateau)', true, '6f6ad556-33f7-41c7-a611-a5cb032d112d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e880d738-aa5b-48c8-9830-d1308b68684c', 'Plateau 2', false, '6f6ad556-33f7-41c7-a611-a5cb032d112d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c39cee6a-1c11-4de2-a252-661f9f128de4', 'Plateau 3', false, '6f6ad556-33f7-41c7-a611-a5cb032d112d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e526570-ed0a-48c8-8050-e72017009f67', 'Plateau 4', false, '6f6ad556-33f7-41c7-a611-a5cb032d112d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d306773a-04f1-421b-9caf-31b194286d50', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'How do volcanic ash soils on the slopes of volcanic mountains (such as around Mount Vesuvius or Mount Etna) benefit agriculture?', 'Andisols formed from volcanic ejecta possess exceptional mineral nutrient fertility and water retention capacity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b7faf9d-fa6f-4e2e-9c42-28d1cc9bdec8', 'Weathered tephra and volcanic ash are extraordinarily rich in bioavailable potassium, phosphorus, iron, and trace minerals, creating fertile soils for vineyards and orchards', true, 'd306773a-04f1-421b-9caf-31b194286d50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a46b5c8-7a42-4b3d-9537-cd5c7a7dbbef', 'Volcanic ash freezes the crops', false, 'd306773a-04f1-421b-9caf-31b194286d50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a9afa8f-45dd-4625-aabd-cd733d2f0a45', 'Volcanic soil prevents weeds by burning them', false, 'd306773a-04f1-421b-9caf-31b194286d50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c36162db-26d7-40c4-9c98-61a93fba4039', 'Volcanic soil produces diamonds', false, 'd306773a-04f1-421b-9caf-31b194286d50');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f919d6a7-e25c-4073-8272-1b91a9ce814f', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'What is the geographic name for a steep cliff or long rock wall marking the edge of a plateau or separating two relatively level areas of different elevations?', 'An escarpment is a steep, precipitous cliff or slope resulting from faulting or erosion separating high plateau tablelands from lowlands.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3bc3fea-fe5c-4048-b594-3721e47eb3b7', 'Escarpment (or Scarp)', true, 'f919d6a7-e25c-4073-8272-1b91a9ce814f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dabcd48-4a0e-46f9-b284-4506b68e6999', 'Pass', false, 'f919d6a7-e25c-4073-8272-1b91a9ce814f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('452fa2b2-dccc-4202-b298-1713fd3e0f63', 'Delta', false, 'f919d6a7-e25c-4073-8272-1b91a9ce814f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9392c6e-75f6-4ff3-9de6-3b9ebcb54003', 'Gorge', false, 'f919d6a7-e25c-4073-8272-1b91a9ce814f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6cb09936-72d5-4ed8-9a68-fff119092d28', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'Which of the following accurately contrasts the economic significance of Mountains versus Plateaus versus Plains?', 'Each geomorphic macro-domain provides distinct economic utility: mountains supply hydrologic heads/forests, plateaus yield mineral wealth, and plains provide arable farmland.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4840e338-3465-4fcb-ae3a-082deaa077ca', 'Mountains = Water storehouses, timber forests & tourism ; Plateaus = Rich mineral ore reserves & hydroelectric waterfalls ; Plains = Intensive agriculture & human settlements', true, '6cb09936-72d5-4ed8-9a68-fff119092d28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50652e11-142b-4cff-b360-64b242c3c42f', 'Mountains = Only for farming ; Plateaus = No minerals ; Plains = High altitude sports', false, '6cb09936-72d5-4ed8-9a68-fff119092d28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a922ca5-2a57-4502-a933-2064c5b79a55', 'All three have identical economic roles', false, '6cb09936-72d5-4ed8-9a68-fff119092d28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0705b55-0012-480c-a9ed-630496218738', 'Plains have only mineral ores', false, '6cb09936-72d5-4ed8-9a68-fff119092d28');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be428705-6c0c-4714-944d-4946c1578c85', 'Class 6', 'Social Science', 'Chapter 6: Major Landforms of the Earth', 'Hard', 'What international civic responsibility is emphasized in NCERT Social Science regarding the stewardship of land and water resources?', 'Sustainable land management requires treating soil, mountains, and water as shared intergenerational ecological heritage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d94f30ca-052a-4ca3-950b-713a8e61b924', 'Conserving land and water for future generations, avoiding wasteful pollution of fertile land with plastic/garbage, and living sustainably in harmony with nature', true, 'be428705-6c0c-4714-944d-4946c1578c85');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7fd02fb-0e53-41ea-bac8-91df4bed1a64', 'Covering all mountains with concrete', false, 'be428705-6c0c-4714-944d-4946c1578c85');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce0a9cbd-d7e0-4be1-a99c-86117e22f672', 'Draining all river water into the desert', false, 'be428705-6c0c-4714-944d-4946c1578c85');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22e06a43-7083-4de1-b907-7d0ac708a757', 'Building factories inside all forests', false, 'be428705-6c0c-4714-944d-4946c1578c85');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d4b5a83-2688-4dcf-8b29-5d9a249d7c3f', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'संज्ञा, सर्वनाम, विशेषण या क्रिया के जिस रूप से उसकी संख्या (एक या एक से अधिक) का बोध होता है, उसे व्याकरण में क्या कहते हैं?', 'शब्द के जिस रूप से वस्तु या प्राणी की संख्यात्मक स्थिति (एक या अनेक) का ज्ञान हो, उसे ''वचन'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adf29e41-02be-4dae-ae5a-0189e828821a', 'वचन (Number)', true, '4d4b5a83-2688-4dcf-8b29-5d9a249d7c3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2fdd9e1-26cc-402f-8d13-84f224e4515f', 'लिंग', false, '4d4b5a83-2688-4dcf-8b29-5d9a249d7c3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f0cb79d-4dee-409b-a897-48663bcff78a', 'कारक', false, '4d4b5a83-2688-4dcf-8b29-5d9a249d7c3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cff8ae1-86a6-4bd3-aeef-4bec07c01616', 'काल', false, '4d4b5a83-2688-4dcf-8b29-5d9a249d7c3f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4330c8a-0337-4782-b483-947080f03136', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'हिंदी भाषा में वचन के कितने भेद (प्रकार) होते हैं?', 'हिंदी में केवल दो वचन होते हैं: 1. एकवचन (Singular) तथा 2. बहुवचन (Plural)। (संस्कृत का द्विवचन हिंदी में नहीं होता)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6ae868f-5215-4018-aeb4-4fd5db63a019', 'दो भेद (एकवचन और बहुवचन)', true, 'c4330c8a-0337-4782-b483-947080f03136');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0260f1a-33bd-4285-afdb-7cdcfb8b290b', 'तीन भेद', false, 'c4330c8a-0337-4782-b483-947080f03136');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3140abb2-eac1-4b47-b706-e2e52bfaeda1', 'चार भेद', false, 'c4330c8a-0337-4782-b483-947080f03136');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e645551d-7be3-4e12-8b33-f2944bf71ecb', 'पाँच भेद', false, 'c4330c8a-0337-4782-b483-947080f03136');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8acbea93-15d2-47b5-9959-d0c92f13599a', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'शब्द के जिस रूप से केवल एक ही वस्तु, प्राणी या स्थान का बोध होता है, उसे क्या कहते हैं?', 'एकमात्र इकाई की संख्या का बोध कराने वाला रूप ''एकवचन'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df3c0ffb-0fc0-4220-b82a-e53fbfac5476', 'एकवचन (जैसे: लड़का, पुस्तक, नदी, माला, गाय, पंखा)', true, '8acbea93-15d2-47b5-9959-d0c92f13599a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('580e950f-87c1-426b-8dcb-bf7c71508bcc', 'बहुवचन', false, '8acbea93-15d2-47b5-9959-d0c92f13599a');
