INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f73542dd-a217-40ca-ae46-84101bdc1340', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'शब्द के जिस रूप से एक से अधिक (अनेक) वस्तुओं, प्राणियों या स्थानों का बोध होता है, उसे क्या कहते हैं?', 'एकाधिक (दो या अधिक) संख्याओं का बोध कराने वाला रूप ''बहुवचन'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3b93ddf-d850-4d22-853f-055ba4773afe', 'बहुवचन (जैसे: लड़के, पुस्तकें, नदियाँ, मालाएँ, गायें, पंखे)', true, 'f73542dd-a217-40ca-ae46-84101bdc1340');
