INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4261e43b-c2e9-40be-bef0-cc7107e17a71', 'लिंग', false, 'f73542dd-a217-40ca-ae46-84101bdc1340');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3c986f26-ce65-4749-9980-b4c744b7b1ff', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'एकवचन शब्द ''लड़का'' का सही बहुवचन रूप क्या है?', 'आ-कारान्त पुल्लिंग संज्ञा में ''आ'' का ''ए'' करने पर बहुवचन बनता है: लड़का -> लड़के।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd0b030b-052b-4e9c-b4c2-0706576a74b2', 'लड़के', true, '3c986f26-ce65-4749-9980-b4c744b7b1ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1b053e7-48e1-4495-9407-ad18666f2a1c', 'लड़कों', false, '3c986f26-ce65-4749-9980-b4c744b7b1ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a6915df-99e9-43ec-859b-1cef9334cae8', 'लड़कियाँ', false, '3c986f26-ce65-4749-9980-b4c744b7b1ff');
