INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19b28939-8e03-47bb-b0a9-f44048ef3d71', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'एकवचन शब्द ''पुस्तक'' और ''किताब'' के सही बहुवचन रूप क्रमशः क्या हैं?', 'अ-कारान्त स्त्रीलिंग संज्ञाओं में ''एं'' (अनुस्वार सहित) लगता है: पुस्तक -> पुस्तकें; किताब -> किताबें।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('864c803d-225c-40bb-a883-f3e3265b0a9a', 'पुस्तकें और किताबें', true, '19b28939-8e03-47bb-b0a9-f44048ef3d71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('115543d2-f5dd-4663-a5c5-ff6cf1aa368b', 'पुस्तकों और किताबों', false, '19b28939-8e03-47bb-b0a9-f44048ef3d71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1aa5db08-daa9-42f3-85e9-6250162a1461', 'पुस्तकाएं और किताबाएं', false, '19b28939-8e03-47bb-b0a9-f44048ef3d71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86333b15-e2d0-432b-ae52-365bd61ea572', 'पुस्तकी और किताबी', false, '19b28939-8e03-47bb-b0a9-f44048ef3d71');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f387ed5-d9af-471e-a1ab-f7d9dccfba4e', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'एकवचन शब्द ''माला'' और ''महिला'' के सही बहुवचन रूप क्रमशः क्या हैं?', 'आ-कारान्त स्त्रीलिंग शब्दों में ''एँ'' जोड़कर बहुवचन बनता है: माला -> मालाएँ; महिला -> महिलाएँ; लता -> लताएँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('644ac095-1b78-41d3-9f14-96cb7c195741', 'मालाएँ और महिलाएँ', true, '9f387ed5-d9af-471e-a1ab-f7d9dccfba4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3050ad5f-8282-4994-9649-1a1898d95427', 'मालाएं और महिलाएं', false, '9f387ed5-d9af-471e-a1ab-f7d9dccfba4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc40345c-ed69-46af-bf32-f455f3e74fbe', 'माले और महिले', false, '9f387ed5-d9af-471e-a1ab-f7d9dccfba4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abc5a3d0-364d-492d-b278-49262aa0385e', 'मालों और महिलाओं', false, '9f387ed5-d9af-471e-a1ab-f7d9dccfba4e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98275930-a4fc-4153-b343-fd12afcad28e', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'एकवचन शब्द ''नदी'' और ''लड़की'' का बहुवचन बनाते समय अंतिम दीर्घ ''ई'' को क्या हो जाता है?', 'ई-कारान्त स्त्रीलिंग शब्दों के बहुवचन में दीर्घ ई ह्रस्व ''इ'' में बदलती है और ''याँ'' जुड़ता है: नदी -> नदियाँ; लड़की -> लड़कियाँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cff2774-2d2a-4885-a990-b16ad03b8b47', 'दीर्घ ''ई'' बदलकर ह्रस्व ''इ'' हो जाती है और अंत में ''याँ'' जुड़ जाता है (नदियाँ, लड़कियाँ)', true, '98275930-a4fc-4153-b343-fd12afcad28e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c82ed232-5847-435f-85be-d8edddd71272', 'दीर्घ ''ई'' वैसी ही रहती है', false, '98275930-a4fc-4153-b343-fd12afcad28e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f70ea53-befc-41d2-b879-c4cd817ea504', 'ई का ए बन जाता है', false, '98275930-a4fc-4153-b343-fd12afcad28e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11c01153-51a1-46fb-ab47-df351e04f8c8', 'कोई परिवर्तन नहीं होता', false, '98275930-a4fc-4153-b343-fd12afcad28e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59acf71e-d169-487d-9eba-9e94a8f0778c', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'एकवचन शब्द ''चिड़िया'' और ''डिबिया'' के सही बहुवचन रूप क्या हैं?', 'या-अन्त स्त्रीलिंग शब्दों के अंत में केवल चंद्रबिंदु (ँ) लगाने से बहुवचन बनता है: चिड़िया -> चिड़ियाँ; डिबिया -> डिबियाँ; गुड़िया -> गुड़ियाँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e010cdf3-59b8-457d-996c-6481c0a2d8d4', 'चिड़ियाँ और डिबियाँ (या के ऊपर चंद्रबिंदु लगाकर)', true, '59acf71e-d169-487d-9eba-9e94a8f0778c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9973763f-d05b-4595-a5c9-33803b6701c7', 'चिड़िए और डिबिए', false, '59acf71e-d169-487d-9eba-9e94a8f0778c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dfd2257-f3c3-4740-9839-ca199430586e', 'चिड़ियों और डिबियों', false, '59acf71e-d169-487d-9eba-9e94a8f0778c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02e32ee4-413c-4639-ac5c-ecb5be5005ea', 'चिड़ी और डिबी', false, '59acf71e-d169-487d-9eba-9e94a8f0778c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('308766f2-1dba-4a59-86a5-a08373942a26', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'हिंदी में किसी व्यक्ति को आदर, सम्मान या प्रतिष्ठा देने के लिए एकवचन होने पर भी किस वचन की क्रिया का प्रयोग किया जाता है?', 'सम्माननीय या पूज्य व्यक्तियों के लिए एकवचन कर्ता के साथ भी आदरार्थक बहुवचन क्रिया प्रयुक्त होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ed53c7b-db82-4077-be64-8030e5f4b503', 'बहुवचन की क्रिया का (आदरार्थक बहुवचन - जैसे: ''गांधी जी महान नेता थे'', ''पिता जी आ रहे हैं'')', true, '308766f2-1dba-4a59-86a5-a08373942a26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df93ec91-08c4-498f-8058-ea3df2099c84', 'एकवचन की क्रिया का', false, '308766f2-1dba-4a59-86a5-a08373942a26');
