INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('462114d9-d1d7-40b5-86de-c692269ff561', 'क्रिया नहीं लगती', false, '308766f2-1dba-4a59-86a5-a08373942a26');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d1f11921-7f93-4f40-801e-7337dbe7e1d7', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'निम्नलिखित में से ''सदा बहुवचन'' (नित्य बहुवचन) में प्रयुक्त होने वाले शब्दों का सही समूह कौन-सा है?', 'प्राण, दर्शन, हस्ताक्षर, आँसू, बाल, होश आदि संज्ञा शब्द हिंदी में सर्वदा बहुवचन में ही प्रयुक्त होते हैं।', NOW()) ON CONFLICT DO NOTHING;
