INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e59edb9-4758-46bb-8113-89a752f53e7f', 'पानी, दूध, तेल, घी', false, 'd1f11921-7f93-4f40-801e-7337dbe7e1d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17898c86-7c58-433c-8a3a-55f5da4834ac', 'जनता, वर्षा, हवा, आकाश', false, 'd1f11921-7f93-4f40-801e-7337dbe7e1d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a3782cc-aa13-47ad-a036-bb0cb4a80cfa', 'सोना, चाँदी, ताँबा', false, 'd1f11921-7f93-4f40-801e-7337dbe7e1d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5cbe42e-345e-487b-a329-0baa8d26773e', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Easy', 'निम्नलिखित में से ''सदा एकवचन'' (नित्य एकवचन) में प्रयुक्त होने वाले शब्दों का सही समूह कौन-सा है?', 'द्रव्यवाचक संज्ञाएँ (पानी, दूध, सोना), समूहवाचक (जनता), तथा प्राकृतिक (वर्षा) शब्द नित्य एकवचन में रहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38403c9a-da7c-4fad-b281-12990b21e191', 'जनता, वर्षा, पानी, दूध, सोना, घी, सत्य', true, 'c5cbe42e-345e-487b-a329-0baa8d26773e');
