INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fb2f456b-0e01-4aa6-9e68-f2b9f15a4795', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'एकवचन शब्द ''वधू'' और ''वस्तु'' के सही बहुवचन रूप क्रमशः क्या हैं?', 'उ/ऊ-कारान्त स्त्रीलिंग शब्दों में ''एँ'' जोड़ते हैं तथा दीर्घ ऊ ह्रस्व ''उ'' में बदलता है: वधू -> वधुएँ; वस्तु -> वस्तुएँ।', NOW()) ON CONFLICT DO NOTHING;
