INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('051abd85-db49-4629-93da-ffebdb945863', 'वधुएं और वस्तुएं', false, 'fb2f456b-0e01-4aa6-9e68-f2b9f15a4795');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc80ea93-2ac2-4e83-b832-b368cf696bac', 'वधुए और वस्तुए', false, 'fb2f456b-0e01-4aa6-9e68-f2b9f15a4795');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16edc1b2-3ed0-4e20-9fb7-e3862c8ac9a7', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'एकवचन शब्द ''कक्षा'', ''माता'' और ''शाखा'' के सही बहुवचन रूप क्या हैं?', 'मानक हिंदी वर्तनी में आ-कारान्त स्त्रीलिंग शब्दों के बहुवचन में ''एँ'' (चंद्रबिंदु युक्त) जोड़ा जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4204811f-3f2c-4167-b399-b8ff5b38f1cb', 'कक्षाएँ, माताएँ, शाखाएँ', true, '16edc1b2-3ed0-4e20-9fb7-e3862c8ac9a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5c29b36-ffca-45b3-9ecd-bde4254fbd08', 'कक्षाएं, माताएं, शाखाएं', false, '16edc1b2-3ed0-4e20-9fb7-e3862c8ac9a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd51630b-7ab5-4267-b5b3-ac753cfd10b7', 'कक्षायें, मातायें, शाखायें', false, '16edc1b2-3ed0-4e20-9fb7-e3862c8ac9a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be4dfb68-0442-449c-b093-39017997cfc0', 'कक्षों, माताओं, शाखाओं', false, '16edc1b2-3ed0-4e20-9fb7-e3862c8ac9a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13c93d22-44f6-4c36-9dc5-13c08769afff', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'कुछ एकवचन शब्दों के अंत में ''गण'', ''वृंद'', ''जन'', ''वर्ग'' या ''दल'' जोड़कर बहुवचन बनाया जाता है; इसका सही सुमेल कौन-सा है?', 'समूहवाची प्रत्ययों द्वारा आदरयुक्त या समुदायवाची बहुवचन रूप बनते हैं: शिक्षकगण, पक्षीवृंद, गुरुजन, छात्रवर्ग, टिड्डीदल।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8dd3bcb-4b16-4a44-a1a1-a8416f903be5', 'शिक्षक -> शिक्षकगण ; पक्षी -> पक्षीवृंद ; गुरु -> गुरुजन ; छात्र -> छात्रवर्ग ; टिड्डी -> टिड्डीदल', true, '13c93d22-44f6-4c36-9dc5-13c08769afff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fc6632b-e8a6-44d9-9ad6-d9b198200847', 'शिक्षक -> शिक्षकें ; पक्षी -> पक्षियाँ', false, '13c93d22-44f6-4c36-9dc5-13c08769afff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea8b7398-df67-4c05-aaf4-d843e418f1aa', 'गुरु -> गुरुएँ ; छात्र -> छात्राएँ', false, '13c93d22-44f6-4c36-9dc5-13c08769afff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea09df6f-ca4a-48e7-bafc-0cba66fa99ba', 'टिड्डी -> टिड्डे', false, '13c93d22-44f6-4c36-9dc5-13c08769afff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bfcbac85-b3c8-40fa-8e19-797ba51626f4', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'जब किसी संज्ञा के साथ परसर्ग (कारक चिह्न जैसे ने, को, से, में, पर) लगा होता है, तो उसका बहुवचन बनाने के लिए कौन-सा प्रत्यय लगता है?', 'सपरसर्ग (तिर्यक/Oblique) स्थिति में सभी संज्ञाओं का बहुवचन ''ओं'' प्रत्यय लगाकर बनाया जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4a45bbe-17e7-4acd-bd8a-60a530bf2c52', '''ओं'' प्रत्यय (तिर्यक बहुवचन - जैसे: लड़कों ने, नदियों में, घरों पर)', true, 'bfcbac85-b3c8-40fa-8e19-797ba51626f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff7f6a51-492b-4dc7-9a76-98b8e35c6b85', '''एँ'' प्रत्यय', false, 'bfcbac85-b3c8-40fa-8e19-797ba51626f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a67d671d-4971-414e-b8de-bdfeffbd8df1', '''याँ'' प्रत्यय', false, 'bfcbac85-b3c8-40fa-8e19-797ba51626f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4449680d-d00e-4ed6-8481-78d3c2af7cbf', 'कोई प्रत्यय नहीं लगता', false, 'bfcbac85-b3c8-40fa-8e19-797ba51626f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea940ff7-012b-4169-bd2b-781b2a063df0', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'एकवचन शब्द ''दवाई'' और ''मिठाई'' के सही बहुवचन रूप क्या हैं?', 'ई-कारान्त में दीर्घ ''ई'' ह्रस्व ''इ'' बनकर ''याँ'' जुड़ती है: दवाई -> दवाइयाँ; मिठाई -> मिठाइयाँ; खिड़की -> खिड़कियाँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e87f0e6-1856-4362-81f0-a2223ceb2d14', 'दवाइयाँ और मिठाइयाँ', true, 'ea940ff7-012b-4169-bd2b-781b2a063df0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e72290d3-fa0f-4d61-815c-22df58112fae', 'दवाइयों और मिठाइयों', false, 'ea940ff7-012b-4169-bd2b-781b2a063df0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb6395a3-f7bd-4cbb-9d1b-fe69cfd70cf5', 'दवाईयाँ और मिठाईयाँ', false, 'ea940ff7-012b-4169-bd2b-781b2a063df0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('478b6be0-6fec-4ca8-8aca-ae7f2549d700', 'दवाएं और मीठा', false, 'ea940ff7-012b-4169-bd2b-781b2a063df0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94094d52-6fda-416b-93f6-a07cce22b671', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'एकवचन शब्द ''ऋतु'' और ''गौ'' के सही बहुवचन रूप क्या हैं?', 'उ/औ-कारान्त शब्दों में ''एँ'' प्रत्यय: ऋतु -> ऋतुएँ; गौ -> गौएँ; धेनु -> धेनुएँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c30ca5c2-4d77-4726-89d3-f1f95f2ed6c0', 'ऋतुएँ और गौएँ', true, '94094d52-6fda-416b-93f6-a07cce22b671');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4838fbce-e1b0-480d-9845-5fd0e6666e6e', 'ऋतुएं और गौएं', false, '94094d52-6fda-416b-93f6-a07cce22b671');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11894449-83a3-43fc-94f4-e47b93ef4f2f', 'ऋतुओं और गौओं', false, '94094d52-6fda-416b-93f6-a07cce22b671');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3673f79a-5bff-43a0-80fe-a19a73a0280c', 'ऋतुए और गौए', false, '94094d52-6fda-416b-93f6-a07cce22b671');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e8b9700-b89d-4612-a250-6110f8399211', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'अ-कारान्त पुल्लिंग शब्द (जैसे: घर, पेड़, हाथी, बालक, साधु) बिना किसी कारक चिह्न के बहुवचन में किस रूप में रहते हैं?', 'निःपरसर्ग (प्रत्ययरहित) स्थिति में अ/उ/ऊ-कारान्त पुल्लिंग शब्द एकवचन और बहुवचन दोनों में समान रूप में रहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddf8203d-2432-4da6-976c-f7d69f142864', 'वे दोनों वचनों (एकवचन और बहुवचन) में समान (अपरिवर्तित) रहते हैं (जैसे: ''एक पेड़ / दस पेड़'', ''एक घर / कई घर'')', true, '3e8b9700-b89d-4612-a250-6110f8399211');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fd6d488-a2d8-45de-b87d-f03e5296731a', 'उनमें ''एँ'' लग जाता है', false, '3e8b9700-b89d-4612-a250-6110f8399211');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4cbe111-e0e6-40df-a5db-041656e9e846', 'वे स्त्रीलिंग बन जाते हैं', false, '3e8b9700-b89d-4612-a250-6110f8399211');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('615dd2b1-11c7-4279-bdd7-71fb39edce18', 'उनका बहुवचन नहीं होता', false, '3e8b9700-b89d-4612-a250-6110f8399211');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f26922ba-1c03-4d93-9593-2c50a8c5293b', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'वाक्य में वचन की पहचान संज्ञा के अतिरिक्त और किस व्याकरणिक पद से आसानी से की जा सकती है?', 'जैसे ''बालक पढ़ता है'' (एकवचन क्रिया) बनाम ''बालक पढ़ते हैं'' (बहुवचन क्रिया); ''अच्छा फल'' बनाम ''अच्छे फल''।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('370eb225-b00c-49ae-b70f-630cbce53c20', 'क्रिया और विशेषण के रूप से', true, 'f26922ba-1c03-4d93-9593-2c50a8c5293b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0744bbe-4498-4409-8ba7-d1f2f96e3ae7', 'केवल उपसर्ग से', false, 'f26922ba-1c03-4d93-9593-2c50a8c5293b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a9f9b22-0d91-4627-bce3-8b7166b99f6b', 'केवल प्रत्यय से', false, 'f26922ba-1c03-4d93-9593-2c50a8c5293b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ec5796f-c581-4e4c-a9b9-668fa4b613cf', 'संधि से', false, 'f26922ba-1c03-4d93-9593-2c50a8c5293b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed11d58f-63e6-4176-8351-32cd3abf47b3', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'सर्वनाम शब्द ''मैं'' और ''वह'' के सही बहुवचन रूप क्रमशः क्या हैं?', 'उत्तम पुरुष ''मैं'' का बहुवचन ''हम'' तथा अन्य पुरुष ''वह'' का बहुवचन ''वे'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1cb4627-cfb3-4e8f-b281-b66684a1a348', 'हम और वे', true, 'ed11d58f-63e6-4176-8351-32cd3abf47b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2454b422-9e65-4030-8329-8cf212a05740', 'मुझे और उसे', false, 'ed11d58f-63e6-4176-8351-32cd3abf47b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1707daa-a6cc-4444-a977-71e60a32873c', 'मेरा और उसका', false, 'ed11d58f-63e6-4176-8351-32cd3abf47b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e972630a-ee83-46c5-8d95-03e13b46083f', 'हमलोग और वो', false, 'ed11d58f-63e6-4176-8351-32cd3abf47b3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ef8af977-6688-4bf2-8881-c5d03394f6c2', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'सर्वनाम शब्द ''यह'' और ''तू'' के सही बहुवचन रूप क्रमशः क्या हैं?', '''यह'' का बहुवचन ''ये'' तथा ''तू'' का बहुवचन ''तुम/आप'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4aea500-9b53-4aa8-9817-3c0b4268f58b', 'ये और तुम (या आप)', true, 'ef8af977-6688-4bf2-8881-c5d03394f6c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29ca1218-47ff-4e9c-998c-422790ce12c7', 'इसे और तुझे', false, 'ef8af977-6688-4bf2-8881-c5d03394f6c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0053755-5ac8-4eb7-a4e8-c1c7b31650c6', 'यहाँ और वहाँ', false, 'ef8af977-6688-4bf2-8881-c5d03394f6c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce848817-f121-462a-a922-f3cf8bea2977', 'इस और उस', false, 'ef8af977-6688-4bf2-8881-c5d03394f6c2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cccce22b-420d-4cf2-9cdd-36cbf90f8e7f', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'एकवचन शब्द ''रात'', ''बात'' और ''आँख'' के सही बहुवचन रूप क्या हैं?', 'अ-कारान्त स्त्रीलिंग संज्ञाओं में ''एं'' अनुस्वार सहित: रात -> रातें; बात -> बातें; आँख -> आँखें; सड़क -> सड़कें।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cee72bad-51ae-40ab-b8f2-54961a7b2a7f', 'रातें, बातें, आँखें', true, 'cccce22b-420d-4cf2-9cdd-36cbf90f8e7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94deed72-cf56-4fb4-86e1-bac15b208c6a', 'रातों, बातों, आँखों', false, 'cccce22b-420d-4cf2-9cdd-36cbf90f8e7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04058176-b429-4ebf-a90e-dd83ab891818', 'राताएँ, बाताएँ, आंखाएँ', false, 'cccce22b-420d-4cf2-9cdd-36cbf90f8e7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0004282e-ffb1-4506-8bc0-07bb81acfe14', 'राती, बाती, आँखी', false, 'cccce22b-420d-4cf2-9cdd-36cbf90f8e7f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9a196b7-867f-45a4-8b17-54b3794dfae0', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'एकवचन शब्द ''पंखा'', ''कमरा'' और ''जूता'' के सही बहुवचन रूप क्या हैं?', 'आ-कारान्त पुल्लिंग शब्दों के अंत में ''ए'': पंखा -> पंखे; कमरा -> कमरे; जूता -> जूते; बेटा -> बेटे।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c85c9d10-b91c-440d-a4d8-cd2f312aa4f6', 'पंखे, कमरे, जूते', true, 'f9a196b7-867f-45a4-8b17-54b3794dfae0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2044f1cb-8302-4527-a68a-2c0fb1f0295e', 'पंखों, कमरों, जूतों', false, 'f9a196b7-867f-45a4-8b17-54b3794dfae0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfefbeab-8455-4eba-b759-da373e878126', 'पंखाएँ, कमराएँ, जूताएँ', false, 'f9a196b7-867f-45a4-8b17-54b3794dfae0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('760b0497-3688-4893-9a61-4517953cf984', 'पंखाएं, कमराएं', false, 'f9a196b7-867f-45a4-8b17-54b3794dfae0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('898a6233-4f8b-4751-afdc-2b1f75a35570', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'वाक्य को शुद्ध कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3a5edc5-2143-4f1b-bdeb-4519b742ca2b', 'मुझे आपके दर्शन हुए। (''दर्शन'' नित्य बहुवचन शब्द है)', true, '898a6233-4f8b-4751-afdc-2b1f75a35570');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e347fea-bafa-4de9-920f-ddd6984d1977', 'मुझको आपका दर्शन हुआ।', false, '898a6233-4f8b-4751-afdc-2b1f75a35570');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da9a0a72-964c-479b-94f2-1e0b757e04d4', 'मेरे को आपका दर्शन मिला।', false, '898a6233-4f8b-4751-afdc-2b1f75a35570');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67ab4050-ee71-4ed3-866d-1dc11e68fcaa', 'मैं आपका दर्शन किया।', false, '898a6233-4f8b-4751-afdc-2b1f75a35570');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ffb2135b-224a-4ee8-83bf-38989f56e4e1', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Medium', 'वाक्य में प्रयुक्त रेखांकित पद का सही वचन बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('418c1c19-20a4-445a-9ffc-2fbe6ec38f77', 'आदरार्थक बहुवचन (एकवचन व्यक्ति हेतु सम्मान सूचक बहुवचन क्रिया)', true, 'ffb2135b-224a-4ee8-83bf-38989f56e4e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5058a0f-8af8-4083-8a9a-a590bdc886be', 'एकवचन', false, 'ffb2135b-224a-4ee8-83bf-38989f56e4e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c739e114-4bb8-4257-852e-319b3e9c66cb', 'नित्य एकवचन', false, 'ffb2135b-224a-4ee8-83bf-38989f56e4e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03c7fa0d-00d5-4ada-b5f1-3957f6d734cb', 'द्विवचन', false, 'ffb2135b-224a-4ee8-83bf-38989f56e4e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c2818ff-6ff7-40ec-9365-6e16fa63f654', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62612081-dd5e-469a-a109-f945b403ded4', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '5c2818ff-6ff7-40ec-9365-6e16fa63f654');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44453ce7-2196-40ec-9d26-9691270884ff', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '5c2818ff-6ff7-40ec-9365-6e16fa63f654');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bbca295-0b7a-4309-87ad-ef1cea478ed1', '(A) सही है, परन्तु (R) गलत है।', false, '5c2818ff-6ff7-40ec-9365-6e16fa63f654');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e7e410c-c04f-427f-b2b5-527955d33cf1', '(A) गलत है, परन्तु (R) सही है।', false, '5c2818ff-6ff7-40ec-9365-6e16fa63f654');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8350a47-3fda-494f-a744-efebb2937deb', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'Spot the IMPOSTER in the following group of नित्य बहुवचन शब्दों के आधार पर:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcea047b-3612-4232-92ea-0e3cbcf2e21b', 'दर्शन', false, 'e8350a47-3fda-494f-a744-efebb2937deb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4acd3651-e23a-48f3-bc5b-d5f39fc3d046', 'हस्ताक्षर', false, 'e8350a47-3fda-494f-a744-efebb2937deb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7b3209e-3be0-4e8c-b970-da1a2f6404a2', 'प्राण', false, 'e8350a47-3fda-494f-a744-efebb2937deb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb0652d7-e9ab-4616-8cd7-ea830901e5cd', 'जनता', true, 'e8350a47-3fda-494f-a744-efebb2937deb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a80e3ab9-3287-45d9-a432-f4d4ebaf86a1', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'सुमेलित कीजिए (शब्द और उनके सही बहुवचन):
(क) बहु   -> (i) नीतियां
(ख) नीति  -> (ii) बहुएँ
(ग) चिड़िया -> (iii) चिड़ियाँ
(घ) नारी   -> (iv) नारियाँ', 'बहु = बहुएँ; नीति = नीतियाँ; चिड़िया = चिड़ियाँ; नारी = नारियाँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0de3ee7b-4e56-4ae9-8fa0-5b9e1a9395ec', 'क-(ii), ख-(i), ग-(iii), घ-(iv)', true, 'a80e3ab9-3287-45d9-a432-f4d4ebaf86a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('636478f8-3e10-4708-8a73-0e2929d0503d', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, 'a80e3ab9-3287-45d9-a432-f4d4ebaf86a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f878ee15-c37e-44ec-82bd-70bc626ea564', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, 'a80e3ab9-3287-45d9-a432-f4d4ebaf86a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7907efd-a047-45c4-93a3-cbb241ada2f4', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, 'a80e3ab9-3287-45d9-a432-f4d4ebaf86a1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02e89745-b629-493f-afb4-aec6c94ff601', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'भाववाचक, गुणवाचक तथा द्रव्यवाचक संज्ञाओं का प्रयोग सामान्यतः किस वचन में होता है?', 'अमूर्त भाववाचक और द्रव्यवाचक संज्ञाएँ नित्य एकवचन में रहती हैं; बहुवचन बनने पर वे जातिवाचक रूप ले लेती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87b89909-84c6-4b75-a161-737b3c594d12', 'सदैव एकवचन में (किन्तु जब भाववाचक संज्ञा बहुवचन बनती है, जैसे ''दूरियाँ, बुराइयाँ, अच्छाइयाँ'', तो वह जातिवाचक संज्ञा बन जाती है)', true, '02e89745-b629-493f-afb4-aec6c94ff601');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06d6baaf-68d8-4c8b-8dd7-d4aabe0e63a8', 'सदैव बहुवचन में', false, '02e89745-b629-493f-afb4-aec6c94ff601');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c86b8d51-3d0a-4c06-9288-7dedaaf63af2', 'उभयवचन में', false, '02e89745-b629-493f-afb4-aec6c94ff601');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfb34637-f018-4b96-9f53-aa6f1e4c6643', 'द्विवचन में', false, '02e89745-b629-493f-afb4-aec6c94ff601');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('188eef73-ee8b-48ef-ac4f-0504b3a96cf6', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'निम्नलिखित वाक्यों पर विचार कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3abea91d-a094-499c-9f3c-63c84b8cc2bb', 'सभी वाक्य 1, 2 और 3 सत्य हैं', true, '188eef73-ee8b-48ef-ac4f-0504b3a96cf6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab8e334c-298b-48cf-b309-e811813490e9', 'वाक्य 1 और 2 केवल', false, '188eef73-ee8b-48ef-ac4f-0504b3a96cf6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('363c8bee-9a62-4c8c-b352-77fc5bb608fc', 'वाक्य 2 और 3 केवल', false, '188eef73-ee8b-48ef-ac4f-0504b3a96cf6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e640d8a-40e6-4437-b765-8d496cb6b7d0', 'वाक्य 1 और 3 केवल', false, '188eef73-ee8b-48ef-ac4f-0504b3a96cf6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1eeb1fe0-fabe-4a84-8793-22993527351c', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'संबोधन कारक में बहुवचन बनाते समय ''ओ'' की मात्रा के साथ अनुस्वार (ं) क्यों नहीं लगाया जाता?', 'केंद्रीय हिंदी निदेशालय के मानक वर्तनी नियम के अनुसार संबोधन कारक के बहुवचन में अनुस्वार-रहित ''ओ'' (भाइयो, मित्रो, देवियो) का प्रयोग शुद्ध है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ef6954e-9664-4692-b034-947d637acfeb', 'संबोधन में अनुस्वार का प्रयोग वर्जित है (जैसे: ''हे भाइयो!'', ''बालको!'', ''साथियो!'' शुद्ध हैं ; ''भाइयों!'', ''बालकों!'' अशुद्ध हैं)', true, '1eeb1fe0-fabe-4a84-8793-22993527351c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a92287da-d7e0-4541-82c4-90e52585a955', 'क्योंकि संबोधन केवल एकवचन में होता है', false, '1eeb1fe0-fabe-4a84-8793-22993527351c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2eb7ac5e-cc49-4d4c-a5f9-eb56a0e29ff5', 'क्योंकि अनुस्वार लगाने से शब्द बदल जाता है', false, '1eeb1fe0-fabe-4a84-8793-22993527351c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c98dab0-e5e3-4b84-8331-ecb2559c84b5', 'कोई नियम नहीं है', false, '1eeb1fe0-fabe-4a84-8793-22993527351c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9924945-59cb-4f29-a302-913531ec7e7e', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'एकवचन शब्द ''श्रीमती'' और ''कवयित्री'' के सही बहुवचन रूप क्या होंगे?', 'ई-कारान्त स्त्रीलिंग संज्ञाओं के बहुवचन में अंतिम ई ह्रस्व ''इ'' में बदलकर ''याँ'' जुड़ती है: श्रीमतियाँ, कवयित्रियाँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9722e451-2f03-44ab-9d77-8bbbec52af54', 'श्रीमती -> श्रीमतियाँ ; कवयित्री -> कवयित्रियाँ', true, 'a9924945-59cb-4f29-a302-913531ec7e7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dfe6295-5587-4696-a1b3-4e44ef2a405e', 'श्रीमती -> श्रीमतियां ; कवयित्री -> कवयित्री', false, 'a9924945-59cb-4f29-a302-913531ec7e7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fa0ce62-a706-48ea-ba8c-7a6f4b2f096b', 'श्रीमती -> श्रीमतीगण', false, 'a9924945-59cb-4f29-a302-913531ec7e7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('763e2dff-77cd-4958-8444-bb181083ecf9', 'दोनों अपरिवर्तित रहते हैं', false, 'a9924945-59cb-4f29-a302-913531ec7e7e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('01f3a5b7-3d26-40d6-976e-e635612b1259', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'एकवचन शब्द ''अध्यापक'' और ''कवि'' का आदरयुक्त विधिवत बहुवचन रूप क्या होगा?', 'सम्माननीय पदों के समूहवाची बहुवचन रूप ''गण'', ''वृंद'', ''मंडल'' जोड़कर बनाए जाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a11b93a7-3328-42aa-a5a5-b3558fc4a48c', 'अध्यापकवृंद (या अध्यापकगण) और कविगण (या कविमंडल)', true, '01f3a5b7-3d26-40d6-976e-e635612b1259');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cf93e73-3377-49c4-b8e3-b6c22847d555', 'अध्यापिकाएँ और कविताएँ', false, '01f3a5b7-3d26-40d6-976e-e635612b1259');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2401b8c5-2123-4002-a50b-ae0b7ac29580', 'अध्यापकों और कवियों', false, '01f3a5b7-3d26-40d6-976e-e635612b1259');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1890ae1e-5fa6-45e8-88cf-6c5ce69280ea', 'अध्यापके और कविये', false, '01f3a5b7-3d26-40d6-976e-e635612b1259');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f855f604-dc80-4055-ac07-3958d5cd9886', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'वाक्य को शुद्ध कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fa8d1d6-d8e2-4462-9d97-b735e8183be6', 'पेड़ों पर चिड़ियाँ बैठी हैं। (''चिड़ियाँ'' बहुवचन के अनुसार ''हैं'' अनुस्वार युक्त क्रिया होगी)', true, 'f855f604-dc80-4055-ac07-3958d5cd9886');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3da061d2-f05b-48e1-876c-636628d536a0', 'पेड़ पर चिड़िया बैठी है।', false, 'f855f604-dc80-4055-ac07-3958d5cd9886');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d120de32-5d1c-498d-af1f-bdc30c93457c', 'पेड़ों में चिड़ियाँ बैठा है।', false, 'f855f604-dc80-4055-ac07-3958d5cd9886');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7be6e4b6-f95f-4f52-8faf-4767c427ab12', 'पेड़ पर चिड़ियों बैठी हैं।', false, 'f855f604-dc80-4055-ac07-3958d5cd9886');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b994f6a-22a4-4ab6-a266-21a94e8825e0', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'संख्यावाची विशेषणों के साथ जातिवाचक संज्ञाओं के वचन के संबंध में सही नियम कौन-सा है?', 'निश्चित समूहवाची एवं परिमाण सूचक संख्याओं के साथ द्रव्य/जातिवाचक संज्ञाएँ सामान्यतः एकवचन रूप में प्रयुक्त होती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db9c51fa-d3bb-4be2-9ddf-fbdadb28f988', 'जब निश्चित संख्यावाची विशेषण आते हैं, तो जातिवाचक संज्ञा प्रायः एकवचन में ही प्रयुक्त होती है (जैसे: ''पाँच सौ रुपया'', ''दो दर्जन केला'')', true, '0b994f6a-22a4-4ab6-a266-21a94e8825e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42c4dd2c-a42a-4d66-ab21-5941ec0557ff', 'वे सदैव बहुवचन में ही आती हैं', false, '0b994f6a-22a4-4ab6-a266-21a94e8825e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6e567af-ca3d-403a-9f3c-0409e60e67ae', 'वे स्त्रीलिंग बन जाती हैं', false, '0b994f6a-22a4-4ab6-a266-21a94e8825e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9806f7ab-0ee6-4fb6-bbb9-2e750a1dc379', 'कोई नियम नहीं है', false, '0b994f6a-22a4-4ab6-a266-21a94e8825e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18f8740b-b0f9-46ff-97fa-1b4270f6457b', 'Class 6', 'Hindi Grammar', 'Chapter 6: वचन', 'Hard', 'एकवचन शब्द ''तिथि'' और ''जाति'' के सही बहुवचन रूप क्या हैं?', 'इ-कारान्त स्त्रीलिंग शब्दों में अंत में ''याँ'' जुड़ता है: तिथि -> तिथियाँ; जाति -> जातियाँ; रीति -> रीतियाँ; पंक्ति -> पंक्तियाँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d2fa5c5-8304-4f4c-b68e-404d9fcf8616', 'तिथियाँ और जातियाँ', true, '18f8740b-b0f9-46ff-97fa-1b4270f6457b');
