INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('121ec404-c4fc-4fbe-81fa-04d7574f6d1a', 'जनता = नित्य एकवचन ; लाखों रुपए = बहुवचन (तिर्यक बहुवचन)', true, 'df0584e0-c31b-4024-b2b8-3d10b8696628');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8d51313-c588-44f4-a55c-1ff052398f11', 'जनता = बहुवचन ; लाखों रुपए = एकवचन', false, 'df0584e0-c31b-4024-b2b8-3d10b8696628');
