INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd53cea2-d707-47b3-89f3-95131b9a20ad', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'What is the internationally accepted standard unit of LENGTH in the International System of Units (SI Units)?', 'The Metre (m) is the fundamental base SI unit for measuring linear distance and length worldwide.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3388b9a6-4306-4778-b5b6-2402bfbcbd84', 'Metre (m)', true, 'fd53cea2-d707-47b3-89f3-95131b9a20ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b41fd151-9a08-42bd-a2a5-8427c117cef2', 'Centimetre (cm)', false, 'fd53cea2-d707-47b3-89f3-95131b9a20ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35f55c9d-3bce-46a1-83e8-29555e48fffb', 'Kilometre (km)', false, 'fd53cea2-d707-47b3-89f3-95131b9a20ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c2e9704-327b-4e3e-a77a-baa0e1631896', 'Foot (ft)', false, 'fd53cea2-d707-47b3-89f3-95131b9a20ad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a416d06e-1b9a-43fe-b4b8-debd6f58fbea', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'How many Centimetres (cm) are there in exactly 1 Metre (m)?', '1 metre = 100 centimetres (1 m = 100 cm = 1,000 mm).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('375314d2-5447-477e-aeae-dc710e9815b4', '100 cm', true, 'a416d06e-1b9a-43fe-b4b8-debd6f58fbea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56f85023-3cd4-4c69-8cd2-9d24d0742b7b', '10 cm', false, 'a416d06e-1b9a-43fe-b4b8-debd6f58fbea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58d4e645-7326-45e4-bf85-dcda112d44c1', '1,000 cm', false, 'a416d06e-1b9a-43fe-b4b8-debd6f58fbea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36d1c6b7-b4d4-452e-b597-ab7a99160afa', '1,000 mm', false, 'a416d06e-1b9a-43fe-b4b8-debd6f58fbea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17dc47e6-e3e4-4a2b-9e90-f6b5d1562988', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'How many Metres (m) make up exactly 1 Kilometre (km)?', 'The metric prefix ''kilo'' represents 1,000; therefore 1 km = 1,000 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d123f74-bfa5-49eb-9fce-bf2939345949', '1,000 metres (1 km = 1,000 m)', true, '17dc47e6-e3e4-4a2b-9e90-f6b5d1562988');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b384e3a1-7d40-4893-86ff-e23612411cc4', '100 metres', false, '17dc47e6-e3e4-4a2b-9e90-f6b5d1562988');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f023484-6bf5-43f5-a97e-c39c3c66c3dc', '10,000 metres', false, '17dc47e6-e3e4-4a2b-9e90-f6b5d1562988');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c24734d6-52f8-4d08-a68c-cbfa7483c8f8', '500 metres', false, '17dc47e6-e3e4-4a2b-9e90-f6b5d1562988');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b4427396-de97-47ea-8fab-6b543c4204b0', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'Why were ancient non-standard units of length like ''Handspan'', ''Footstep'', and ''Cubits'' discarded for scientific measurements?', 'Biological anatomical variations caused commercial discrepancies, necessitating invariant scientific standard units.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cbf6542-88d6-425d-abc8-05cce8ee805e', 'Because human body dimensions vary from person to person, leading to inconsistent, inaccurate, and unreliable measurements', true, 'b4427396-de97-47ea-8fab-6b543c4204b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f67bed80-a78c-4bad-9940-03d62a1376ad', 'Because rulers are cheaper', false, 'b4427396-de97-47ea-8fab-6b543c4204b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93471438-ccdc-4807-8f44-b0b559671b2c', 'Because hands cannot measure wood', false, 'b4427396-de97-47ea-8fab-6b543c4204b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec4b640d-fa7b-473c-9b54-a0996777b6d9', 'Because kings banned hands', false, 'b4427396-de97-47ea-8fab-6b543c4204b0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3b2fdc8-99cc-46ac-9284-10563406e86a', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'The motion of an object along a straight line path is called:', 'Linear unidirectional motion along a single straight axis is rectilinear motion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc5362a2-526c-4fc5-855e-a8358e3ff70a', 'Rectilinear Motion (e.g. a car moving on a straight road, march-past of soldiers)', true, 'd3b2fdc8-99cc-46ac-9284-10563406e86a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c86e90a9-f9b3-4337-972f-8fed31237295', 'Circular Motion', false, 'd3b2fdc8-99cc-46ac-9284-10563406e86a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e9ccf15-814b-4fc6-9f62-2c816f5de5a9', 'Periodic Motion', false, 'd3b2fdc8-99cc-46ac-9284-10563406e86a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c69b1799-e1de-4f35-a151-82c36a52d635', 'Rotational Motion', false, 'd3b2fdc8-99cc-46ac-9284-10563406e86a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ec75932-b450-43f0-ba83-3f8529b7a085', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'The motion of an object along a circular path such that its distance from a fixed central point remains constant is called:', 'Trajectory tracking along the circumference of a circle at constant radial distance is circular motion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2698faf2-27f0-459c-95c4-700446801cae', 'Circular Motion (e.g. motion of blades of an electric fan, hands of a clock)', true, '2ec75932-b450-43f0-ba83-3f8529b7a085');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d61039ea-3a66-4e26-a878-f5f75ac3231a', 'Rectilinear Motion', false, '2ec75932-b450-43f0-ba83-3f8529b7a085');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22e52091-9a49-4c63-8426-f2673aab40c8', 'Periodic Motion', false, '2ec75932-b450-43f0-ba83-3f8529b7a085');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65a41c8d-41e1-4c71-8b1b-ca7b770f014b', 'Random Motion', false, '2ec75932-b450-43f0-ba83-3f8529b7a085');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41e173dc-f3d6-4cc6-914d-48a219aa3e72', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'Motion that repeats itself at regular equal intervals of time is called:', 'Harmonic oscillatory motions repeating over a constant time period (T) are periodic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff3989ca-78a7-4d92-96ec-9ca7195ab21f', 'Periodic Motion (e.g. pendulum of a clock, branch of a tree swinging, string of a guitar)', true, '41e173dc-f3d6-4cc6-914d-48a219aa3e72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b6565a9-ec89-4fac-9d8e-b930593e87e3', 'Rectilinear Motion', false, '41e173dc-f3d6-4cc6-914d-48a219aa3e72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76f8b60b-cd14-4269-b9ad-ff326a92b899', 'Random Motion', false, '41e173dc-f3d6-4cc6-914d-48a219aa3e72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf6f5701-b8ed-4ef5-8023-318bbf463d8e', 'Non-periodic Motion', false, '41e173dc-f3d6-4cc6-914d-48a219aa3e72');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc9b8e60-cd04-4195-85d8-b05d91f23c45', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'What instrument is used by tailors to measure the curved circumference of a person''s chest or waist?', 'Flexible measuring tape conforms along curved anatomical contours where rigid straight rulers cannot bend.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e492dc6-84ac-45bd-81ae-cbd276ce508a', 'A flexible Measuring Tape', true, 'cc9b8e60-cd04-4195-85d8-b05d91f23c45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b26de1a7-9766-44f3-b643-45255dfbbc46', 'A rigid wooden meter rod', false, 'cc9b8e60-cd04-4195-85d8-b05d91f23c45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69121d4c-582d-468c-b3a4-2034a718017f', 'A metal divider', false, 'cc9b8e60-cd04-4195-85d8-b05d91f23c45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b2ef476-7dd6-42b8-8246-a41a03b93168', 'A compass', false, 'cc9b8e60-cd04-4195-85d8-b05d91f23c45');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('71d17be1-be6d-48ab-ab8d-e8868148ea9e', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'What revolutionary invention in the history of human transport made land travel and haulage of heavy loads dramatically faster?', 'The wheel substituted rolling friction for sliding friction, revolutionizing wheeled vehicle transport.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83350f9f-f6ac-4c81-9144-94977ddb5682', 'The invention of the Wheel', true, '71d17be1-be6d-48ab-ab8d-e8868148ea9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ac623ac-ff8d-4f8b-b86e-0b5b599e3c85', 'The invention of stone knives', false, '71d17be1-be6d-48ab-ab8d-e8868148ea9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a65495ae-2e66-42ba-8b2a-abdac504487d', 'The invention of paper', false, '71d17be1-be6d-48ab-ab8d-e8868148ea9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54abb984-e709-4d44-95c3-d8b704a0f116', 'The invention of glass', false, '71d17be1-be6d-48ab-ab8d-e8868148ea9e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb9f3306-27ea-429d-8140-2b3f89f897f9', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'Which prime mover invented in the 18th century paved the way for the development of modern high-speed steam locomotives and railways?', 'The Watt steam engine transformed thermodynamic enthalpy into mechanical work for railway transport.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f2f7027-50cb-48ed-aa32-6338aded30b8', 'Steam Engine (by James Watt)', true, 'cb9f3306-27ea-429d-8140-2b3f89f897f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('592b8b9e-086e-4a56-90a1-a7d38d8cd624', 'Electric Motor', false, 'cb9f3306-27ea-429d-8140-2b3f89f897f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2030b403-f640-4183-8f30-181f7f1338ec', 'Jet Engine', false, 'cb9f3306-27ea-429d-8140-2b3f89f897f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e36a477-aff2-4192-b16a-bf55a9666246', 'Diesel Engine', false, 'cb9f3306-27ea-429d-8140-2b3f89f897f9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba63c4de-b823-4967-bb02-7c7da841b129', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'Which of the following is an example of an object exhibiting MULTIPLE types of motion simultaneously?', 'A rolling sphere or bicycle wheel rotates about its axle while translating rectilinearly forward.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c90fb7de-03ed-46e0-980e-50cdd186d4f3', 'A rolling ball on the ground (both Rotational motion on its axis and Rectilinear motion along the floor)', true, 'ba63c4de-b823-4967-bb02-7c7da841b129');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f0d958d-040f-4cc2-bbeb-d5459afd2dc3', 'A bird sleeping in a nest', false, 'ba63c4de-b823-4967-bb02-7c7da841b129');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9aaf32bf-eabb-4731-b85e-f3a6056713ae', 'A fixed stone on a hill', false, 'ba63c4de-b823-4967-bb02-7c7da841b129');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d526d131-2b12-4c2c-b59d-a62938261d68', 'A book lying on a table', false, 'ba63c4de-b823-4967-bb02-7c7da841b129');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e50bd0d9-4184-401c-9b57-3755d13f0518', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Easy', 'A change in the position of an object with time relative to a stationary reference point (frame of reference) is called:', 'Kinematic motion is defined as a temporal displacement in positional coordinates relative to a chosen reference frame.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5ba3ee1-17b3-4de7-b3e7-9a90f0e3483b', 'Motion', true, 'e50bd0d9-4184-401c-9b57-3755d13f0518');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8be9fae4-ae6b-4e4f-820a-5053cfdee052', 'Rest', false, 'e50bd0d9-4184-401c-9b57-3755d13f0518');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19d86adf-cf12-46bb-916c-b68d9c197dd8', 'Force', false, 'e50bd0d9-4184-401c-9b57-3755d13f0518');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c36b798-af32-4000-a3df-66a193d03aba', 'Friction', false, 'e50bd0d9-4184-401c-9b57-3755d13f0518');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0730581-d15d-42eb-9b55-2161e1349f9f', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'How can the length of a curved line (such as a winding river curve on a map) be measured accurately?', 'A non-stretchable string traces continuous curvature and is subsequently calibrated against a linear metric scale.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22e4aa37-2af8-4256-a318-2ded2d301ebc', 'By laying a flexible thread carefully along the curved path from start to end, marking the endpoints on the thread, and then measuring the straightened thread on a standard meter scale', true, 'b0730581-d15d-42eb-9b55-2161e1349f9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('086696fa-9e3a-497d-97ea-9a031e114d61', 'By bending a wooden ruler until it snaps', false, 'b0730581-d15d-42eb-9b55-2161e1349f9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bfdb980-0d42-4987-af56-43f18c26bd4e', 'By guessing with eyes', false, 'b0730581-d15d-42eb-9b55-2161e1349f9f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bfc3f9b-830c-4032-9f5b-9ea1613b5a24', 'By weighing the paper on a balance', false, 'b0730581-d15d-42eb-9b55-2161e1349f9f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d621013-3f4d-4b01-95ad-bcc7e1958bbe', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'What is ''Parallax Error'' in taking length measurements with a scale, and how is it avoided?', 'Viewing the scale at an oblique angle introduces parallax displacement; the sight line must be perpendicular (90°) to the mark.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a42fe22-2439-46ed-a376-214063bdfd84', 'An apparent optical shift error caused by viewing the scale markings from an angle; it is avoided by positioning the eye directly vertically above the point of measurement', true, '1d621013-3f4d-4b01-95ad-bcc7e1958bbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5233c709-d047-445d-9788-31b4b21aa38a', 'An error caused by wind blowing', false, '1d621013-3f4d-4b01-95ad-bcc7e1958bbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('415f7f5e-5900-4b96-8e4b-716fb1239807', 'An error caused by warm weather', false, '1d621013-3f4d-4b01-95ad-bcc7e1958bbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d10d6da7-8ebb-4d1d-8008-cbd2add1cee4', 'An error caused by dirty paper', false, '1d621013-3f4d-4b01-95ad-bcc7e1958bbe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f0aaea72-132f-4840-966c-a55d6ef21c1f', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'If the zero mark (0 cm) of a ruler is broken or damaged, how should one take an accurate measurement?', 'True length = (Final scale reading) - (Initial non-zero offset reading). E.g. 14.3 cm - 1.0 cm = 13.3 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79874d39-e316-433c-b023-d65b172bb422', 'Start measuring from any other full mark (e.g. 1.0 cm or 2.0 cm) and subtract that initial reading from the final end reading', true, 'f0aaea72-132f-4840-966c-a55d6ef21c1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10d36292-1160-4c38-beb6-2f32a83876d4', 'Throw the ruler away immediately', false, 'f0aaea72-132f-4840-966c-a55d6ef21c1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30722fe2-9503-4052-9a58-c5bd93c92ed3', 'Guess the missing zero mark', false, 'f0aaea72-132f-4840-966c-a55d6ef21c1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6763c15-0152-4ae5-9faf-16b5cc81a241', 'Add 10 cm to the final reading', false, 'f0aaea72-132f-4840-966c-a55d6ef21c1f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('527ca95b-49e1-4854-a94e-9aa5c2bafdf4', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'Why is a passenger sitting inside a moving bus in motion relative to a roadside tree, but AT REST relative to a fellow passenger sitting next to them?', 'Kinematics is reference-frame dependent: position vector changes in the Earth frame, but dr/dt = 0 in the bus co-moving frame.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('988b0ed7-6c5d-43b1-a8c5-2eefd713df68', 'Motion is relative: position changes relative to the stationary roadside tree, but position remains unchanged relative to the bus interior and fellow passenger', true, '527ca95b-49e1-4854-a94e-9aa5c2bafdf4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fcbf180-7790-4e7e-a11f-d523702b30cb', 'Because the bus has windows', false, '527ca95b-49e1-4854-a94e-9aa5c2bafdf4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('617b4d11-5b62-4d70-83f5-44fe74886dfe', 'Because the tree is running backwards', false, '527ca95b-49e1-4854-a94e-9aa5c2bafdf4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('640b290d-ab3b-4800-b423-f2f4be867f91', 'Because eyes get confused in a bus', false, '527ca95b-49e1-4854-a94e-9aa5c2bafdf4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d097acc-cde1-4137-8a2a-591ee584bf4a', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'What types of motion are executed by the needle of a sewing machine and its rotating balance wheel?', 'The balance wheel rotates about a fixed axis (circular/rotational), while the crank drives the needle in periodic reciprocating motion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43b8db16-6a70-4d63-88de-34130fda4653', 'The sewing needle moves up and down in Periodic / Oscillatory motion, while the balance wheel executes Circular / Rotational motion', true, '2d097acc-cde1-4137-8a2a-591ee584bf4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b27a847b-74cb-46fe-b0db-e733f4906cde', 'Both move in straight rectilinear motion', false, '2d097acc-cde1-4137-8a2a-591ee584bf4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('750c749d-e043-4bb0-9a06-d9bcc51d2f53', 'The needle moves in circles', false, '2d097acc-cde1-4137-8a2a-591ee584bf4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26880216-64b5-4f98-9aca-9144ec5e1b18', 'Both are completely at rest', false, '2d097acc-cde1-4137-8a2a-591ee584bf4a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6797283-6946-4466-be4f-57946126fa9e', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'What is the key difference between ''Rotational Motion'' and ''Circular Motion''?', 'Rotation involves spin about an intrinsic internal axis; circular revolution tracks a trajectory around an extrinsic external focus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25b1172e-d2e8-4a94-88d3-fc541381c708', 'In Rotational motion, the entire body spins about an internal fixed axis passing through itself (e.g. spinning top, Earth''s spin); in Circular motion, an object moves around an external central point (e.g. Earth revolving around the Sun)', true, 'c6797283-6946-4466-be4f-57946126fa9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed2e4f0d-a4db-4c48-9a0e-936b966a328e', 'Rotational motion has no speed', false, 'c6797283-6946-4466-be4f-57946126fa9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df5c244d-e088-463b-a838-b7222c7be177', 'Circular motion is always straight', false, 'c6797283-6946-4466-be4f-57946126fa9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d2e10dc-31e0-4e52-8a11-e65bf2703414', 'There is no difference', false, 'c6797283-6946-4466-be4f-57946126fa9e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2254f9cf-27fc-4ad1-93d1-7f15fa253945', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'Convert a distance of 4.5 kilometres into metres (m) and centimetres (cm):', '4.5 km × 1,000 m/km = 4,500 m. 4,500 m × 100 cm/m = 450,000 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c206650-54ad-463b-ad3f-8dffa94c7be8', '4,500 m and 450,000 cm', true, '2254f9cf-27fc-4ad1-93d1-7f15fa253945');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c14ea61-997b-4381-9152-33b7ea616abe', '450 m and 45,000 cm', false, '2254f9cf-27fc-4ad1-93d1-7f15fa253945');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c06bd697-5b59-476d-b33b-d3cd07d9c4e9', '45,000 m and 4,500 cm', false, '2254f9cf-27fc-4ad1-93d1-7f15fa253945');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3db4cc35-7c1d-4477-9b31-2725e09632a3', '4.5 m and 450 cm', false, '2254f9cf-27fc-4ad1-93d1-7f15fa253945');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9802e010-21b7-4b01-a33d-e41543bb9984', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'Convert the length of a pencil measuring 18.5 cm into millimetres (mm):', '1 cm = 10 mm. 18.5 cm × 10 mm/cm = 185 mm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3afa2bf-a5af-4919-902e-3a95e79c7e5c', '185 mm (18.5 × 10 mm = 185 mm)', true, '9802e010-21b7-4b01-a33d-e41543bb9984');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1ae2871-2016-48e9-9fa7-8a00867dde28', '1.85 mm', false, '9802e010-21b7-4b01-a33d-e41543bb9984');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a4e41fa-23b7-4bc6-a161-da8bca50b5c3', '1,850 mm', false, '9802e010-21b7-4b01-a33d-e41543bb9984');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7831d60-a5a0-4eb4-87a5-66bfc8c2dc48', '0.185 mm', false, '9802e010-21b7-4b01-a33d-e41543bb9984');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55586875-d1b9-43f5-aeb3-13080cb05b5a', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'Which of the following motions is NON-PERIODIC (does not repeat itself at regular intervals)?', 'Random athletic maneuvering has no fixed periodic time interval, making it non-periodic/random.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de7aa8cc-1928-4c11-a9f4-1f88373b5431', 'A footballer running unpredictably across the sports ground', true, '55586875-d1b9-43f5-aeb3-13080cb05b5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56dcc698-7548-4328-8249-935d42f25fd3', 'The swing of a simple pendulum', false, '55586875-d1b9-43f5-aeb3-13080cb05b5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a100f5f-dfc9-4e15-a290-389a6fd9501a', 'The revolution of the Earth around the Sun', false, '55586875-d1b9-43f5-aeb3-13080cb05b5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5390939-2da9-477c-bb5e-6f85b4172a1e', 'The heartbeat of a healthy resting human', false, '55586875-d1b9-43f5-aeb3-13080cb05b5a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d7c1d50-639d-4df6-a650-1cb567c540be', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'What type of motion is executed by the plucked strings of a Sitar or Guitar when playing musical notes?', 'Tensioned strings execute transverse periodic standing wave vibrations generating acoustic harmonics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e181bf7-5c96-4036-b143-0c3ca02f05da', 'Periodic / Vibratory (Oscillatory) Motion', true, '9d7c1d50-639d-4df6-a650-1cb567c540be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6be7590f-ee6c-4493-a625-2b4b1e4b9e98', 'Rectilinear Motion', false, '9d7c1d50-639d-4df6-a650-1cb567c540be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49c7143a-e474-4e3a-984a-9bf2a458f63c', 'Rotational Motion', false, '9d7c1d50-639d-4df6-a650-1cb567c540be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4767aa38-8031-4fae-a5ca-ec9ae4d7904a', 'Circular Motion', false, '9d7c1d50-639d-4df6-a650-1cb567c540be');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('baa0b163-46e8-42bd-b17a-20fbb6c122e7', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'Why does an elastic rubber measuring tape give incorrect and inconsistent measurements of length?', 'Elastic deformation alters the calibrated spacing between interval markers under variable tensile stress.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('745308b4-9781-4b7f-b539-e2ed714a7745', 'Because rubber stretches variably depending on how hard a person pulls it, giving different lengths for the exact same object', true, 'baa0b163-46e8-42bd-b17a-20fbb6c122e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f805f92e-bc49-4366-9469-7ec87a8dab67', 'Because rubber has no numbers printed on it', false, 'baa0b163-46e8-42bd-b17a-20fbb6c122e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80371090-6c9c-4347-a83c-c7ee2d56a40a', 'Because rubber dissolves in air', false, 'baa0b163-46e8-42bd-b17a-20fbb6c122e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f77c1535-1786-465d-ac69-a7d4e36bdea8', 'Because rubber is too heavy', false, 'baa0b163-46e8-42bd-b17a-20fbb6c122e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47953561-53d5-4bfb-95fc-dab8ef785739', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'What is the historical chronological progression of transportation technology across human civilizations?', 'Transport evolved from biological walking to animal draught, mechanical combustion steam engines, internal combustion cars, and aerospace rocketry.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d44dd435-ee21-40de-93fd-d31b8d93a146', 'Walking on foot -> Pack animals -> Wooden wheeled bullock carts / Sailboats -> Steam engine railways -> Motorcars & Aeroplanes -> Supersonic jets & Spacecraft', true, '47953561-53d5-4bfb-95fc-dab8ef785739');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('086ff37b-4a2c-4f9e-8ebf-b46ae6ce5a4d', 'Aeroplanes -> Walking -> Steam engines', false, '47953561-53d5-4bfb-95fc-dab8ef785739');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e504ac7-97d9-47bb-8400-4d1cfe5819c1', 'Steam engines -> Spacecraft -> Walking', false, '47953561-53d5-4bfb-95fc-dab8ef785739');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b621f8fe-27a2-4ea5-82b6-aef789715575', 'Bicycles -> Spacecraft -> Bullock carts', false, '47953561-53d5-4bfb-95fc-dab8ef785739');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f781e27e-9999-4706-8b67-fefae9f0f082', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'A student measures the thickness of a single page of a 500-page book using a 15 cm plastic scale. How can they achieve high accuracy?', 'Bulk averaging method: dividing composite thickness by total sheet count minimizes least-count reading error.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a600627f-bec5-42d8-b54c-775747aaf835', 'Measure the total thickness of all 500 pages together with the scale and divide that total thickness by 500', true, 'f781e27e-9999-4706-8b67-fefae9f0f082');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c56e0fd-48fb-4ae6-b812-8d1f9e0960a8', 'Try to read a single page with a magnifying lens', false, 'f781e27e-9999-4706-8b67-fefae9f0f082');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e5f4d10-eaca-493b-888e-26c6b0b51439', 'Guess the thickness as 1 mm', false, 'f781e27e-9999-4706-8b67-fefae9f0f082');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49fae7e0-a443-4acd-84fa-f1815de0f293', 'Burn the book and weigh the ash', false, 'f781e27e-9999-4706-8b67-fefae9f0f082');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b6cc496a-061c-49b7-8cf5-b486d623122c', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'Which of the following SI unit abbreviations is written CORRECTLY according to standard international IUPAP conventions?', 'SI unit symbols are written in lower case (m for metre), never pluralized with ''s'', and never followed by periods unless at sentence ends.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('109dc4c4-87be-48bc-bf86-9e8deec9c80d', '50 m (lower-case m without plural ''s'' or full stop)', true, 'b6cc496a-061c-49b7-8cf5-b486d623122c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca7e83d6-fbb2-46e0-8ef9-48f00c30a015', '50 ms.', false, 'b6cc496a-061c-49b7-8cf5-b486d623122c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95ded34c-3709-46b3-8499-e44233f4a4e7', '50 Metres.', false, 'b6cc496a-061c-49b7-8cf5-b486d623122c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3df8c82-210c-499e-b4b8-74ba8daddc47', '50 Mts', false, 'b6cc496a-061c-49b7-8cf5-b486d623122c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96125042-50a4-45e3-b4ba-d77f49592c12', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'What motion is performed by the Earth around its own polar axis and around the Sun respectively?', 'Earth combines intrinsic diurnal axial rotation (24h) with periodic orbital revolution (365.25d).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e727da37-aee6-46d8-9561-508979c97198', 'Rotational motion on its own axis (every 24 hours) AND Circular/Elliptical Periodic revolution around the Sun (every 365¼ days)', true, '96125042-50a4-45e3-b4ba-d77f49592c12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3ee198c-35d4-40df-b3ab-b93ad5f3a4f0', 'Rectilinear motion only', false, '96125042-50a4-45e3-b4ba-d77f49592c12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4026f698-141f-4858-a4a9-423d5490b113', 'Random non-periodic motion', false, '96125042-50a4-45e3-b4ba-d77f49592c12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17b95b06-cb41-4c15-9205-71d878c7d2c0', 'It remains completely at rest', false, '96125042-50a4-45e3-b4ba-d77f49592c12');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8649526-7172-409a-af74-43414fb97239', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Medium', 'In which year was the International System of Units (SI) accepted internationally by the General Conference on Weights and Measures?', 'The 11th CGPM officially established the International System of Units (SI) based on the metric system in 1960.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b73f20a1-70e0-4851-95af-c5c0f69b620a', '1960', true, 'd8649526-7172-409a-af74-43414fb97239');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77965a06-5b86-4107-af1d-6d2f36068dcb', '1947', false, 'd8649526-7172-409a-af74-43414fb97239');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71f3595b-9db4-4f0e-b9f3-abe6bf757a9a', '1900', false, 'd8649526-7172-409a-af74-43414fb97239');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b59d0a87-d41c-4d93-8268-2816c96d501c', '2000', false, 'd8649526-7172-409a-af74-43414fb97239');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f17eec6-a293-4a3e-9367-3cca7e261ff9', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6eaf8c6d-07a9-49b0-ba82-c299c2e06e27', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '4f17eec6-a293-4a3e-9367-3cca7e261ff9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9039528d-383e-43b5-9e2e-caed873f1e22', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '4f17eec6-a293-4a3e-9367-3cca7e261ff9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14f1c1d7-e40f-47c9-9422-445f108b32e4', '(A) is true, but (R) is false.', false, '4f17eec6-a293-4a3e-9367-3cca7e261ff9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9483b64f-bc20-4ab4-b1df-1cea3d1777b3', '(A) is false, but (R) is true.', false, '4f17eec6-a293-4a3e-9367-3cca7e261ff9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf9dcec5-90e6-4056-81fe-61046652caba', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'Spot the IMPOSTER in the following group of motions classified as Periodic Motion:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51eb3fd8-0dc3-4ec0-817c-46f3e9d248ab', 'Motion of a child on a swing', false, 'bf9dcec5-90e6-4056-81fe-61046652caba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b4e9f64-7717-420c-8929-176232c8ae11', 'Oscillation of a clock pendulum', false, 'bf9dcec5-90e6-4056-81fe-61046652caba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24f7d8b5-04ae-4969-9287-d5f5e3655aac', 'Plucked string of a sitar', false, 'bf9dcec5-90e6-4056-81fe-61046652caba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c922082a-02ba-4a27-b208-fff1a264053c', 'A dry leaf falling in turbulent wind', true, 'bf9dcec5-90e6-4056-81fe-61046652caba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4430394-0cae-401e-b190-c52db65e0411', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'A student measures the length of a wooden block using a broken scale starting at 2.4 cm mark. The reading at the other end is 18.7 cm. What is the true physical length of the block?', 'True length = Final reading - Initial offset = 18.7 cm - 2.4 cm = 16.3 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dd62da5-56e6-4d60-9077-6a9a52f7f781', '16.3 cm (18.7 cm - 2.4 cm = 16.3 cm)', true, 'e4430394-0cae-401e-b190-c52db65e0411');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4a4e9be-7412-48db-80b7-211f83823c0a', '18.7 cm', false, 'e4430394-0cae-401e-b190-c52db65e0411');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ecf9e11-a6d6-4d94-8cc5-fb491f5c12ec', '21.1 cm', false, 'e4430394-0cae-401e-b190-c52db65e0411');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ed9f078-915d-42ca-9334-9fdc55de9b86', '14.3 cm', false, 'e4430394-0cae-401e-b190-c52db65e0411');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8a10654-7428-4462-891c-9192d0f4d950', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'Match Column I (Moving Objects) with Column II (Primary Types of Motion):
(a) A stone tied to a string and whirled overhead -> (i) Rectilinear Motion
(b) An apple falling vertically from a tree       -> (ii) Periodic / Oscillatory Motion
(c) The membrane of a tabla being played        -> (iii) Circular Motion
(d) A potter''s wheel spinning on its pivot      -> (iv) Rotational Motion', 'Whirled stone = Circular; Falling apple = Rectilinear; Tabla membrane = Periodic; Potter''s wheel = Rotational.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88f80b48-8766-4eac-8b39-9df1c34fd214', 'a-(iii), b-(i), c-(ii), d-(iv)', true, 'd8a10654-7428-4462-891c-9192d0f4d950');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('602949e6-bb3d-4f91-ad6b-175f52f1ede2', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'd8a10654-7428-4462-891c-9192d0f4d950');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6c92b21-9df1-47f2-9b66-29440f515529', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'd8a10654-7428-4462-891c-9192d0f4d950');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55989731-2928-4b36-9fcd-4c0209075bfc', 'a-(ii), b-(iv), c-(i), d-(iii)', false, 'd8a10654-7428-4462-891c-9192d0f4d950');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9257ae20-b747-41f1-9fa6-a32c168e073e', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'Read the statements regarding measurement conventions:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ca67f64-1b6d-4315-8216-d187e8e6a3a1', 'Statements 1 and 3 only', true, '9257ae20-b747-41f1-9fa6-a32c168e073e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f4fc922-64b5-48f4-8549-89a6f8240c65', 'Statements 1 and 2 only', false, '9257ae20-b747-41f1-9fa6-a32c168e073e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e77ef503-c105-4dac-8d4f-dfd08ec80846', 'Statements 2 and 3 only', false, '9257ae20-b747-41f1-9fa6-a32c168e073e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0413786-848a-4f15-9651-960a2288ce13', 'All Statements 1, 2, and 3', false, '9257ae20-b747-41f1-9fa6-a32c168e073e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7af91efe-6f37-45b7-af48-2c86845dc7b4', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'Why was the standard prototype metre bar historically crafted from an alloy of 90% Platinum and 10% Iridium and preserved at 0°C near Paris?', 'Pt-Ir provides supreme chemical inertness, high mechanical hardness, and minimal thermal contraction/expansion across seasonal shifts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad94840e-97b9-4415-8d5b-612c03aa2975', 'Platinum-Iridium alloy exhibits extreme resistance to corrosion and an exceptionally low coefficient of thermal expansion, preserving invariant physical length', true, '7af91efe-6f37-45b7-af48-2c86845dc7b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('896ac939-5bb4-4680-ab2e-a3b2c77fb99d', 'To make the ruler shiny and expensive', false, '7af91efe-6f37-45b7-af48-2c86845dc7b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a883fd0-c8d4-43f2-8995-d161d74c8c1e', 'Because platinum melts easily in cold water', false, '7af91efe-6f37-45b7-af48-2c86845dc7b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9274e12a-23e3-4583-81f2-c51a847905c6', 'Because France wanted to hoard gold', false, '7af91efe-6f37-45b7-af48-2c86845dc7b4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ee55948f-31ba-45ab-ad5c-8e98376ce6ce', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'A cyclist pedals along a straight level road at 15 km/h. Analyze the motion of the bicycle''s WHEEL versus the motion of the cyclist''s PEDALS:', 'Wheels translate along the ground while spinning on their hub; foot pedals trace circular revolutions around the central bottom bracket spindle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9eb60285-421a-496e-91e4-3f1d758f6a66', 'The wheels execute both Rotational motion and Rectilinear translation forward, while the pedals execute Circular motion around the crank axle', true, 'ee55948f-31ba-45ab-ad5c-8e98376ce6ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcbca9f0-1f1b-4926-9c08-bd29baa3f1ba', 'Both move in straight lines only', false, 'ee55948f-31ba-45ab-ad5c-8e98376ce6ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac8ff54c-113b-4736-8b74-fed97d394aa8', 'Both move in random motion', false, 'ee55948f-31ba-45ab-ad5c-8e98376ce6ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ff0bdcf-5bcc-4a2a-a0da-3a16d6426435', 'The bicycle is at rest', false, 'ee55948f-31ba-45ab-ad5c-8e98376ce6ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0bf94b33-ad78-4bfe-a614-fcbef8dc2f9c', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'Consider four measurement scenarios:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be5d3adb-b846-4c41-bbb2-87fb59cbf791', '1: cm ; 2: km (or AU) ; 3: mm ; 4: km', true, '0bf94b33-ad78-4bfe-a614-fcbef8dc2f9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('252d469f-6e56-4e44-a591-ad6cafe2a0ab', '1: mm ; 2: m ; 3: km ; 4: cm', false, '0bf94b33-ad78-4bfe-a614-fcbef8dc2f9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4df4a5ff-523c-479c-969d-147afe18a7b8', '1: m ; 2: cm ; 3: km ; 4: mm', false, '0bf94b33-ad78-4bfe-a614-fcbef8dc2f9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22a22320-8189-4f9d-9650-8d51f57c71fb', '1: km ; 2: mm ; 3: cm ; 4: m', false, '0bf94b33-ad78-4bfe-a614-fcbef8dc2f9c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a6d93d16-df71-4f7d-ae25-e13e9ba80876', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'Why must a measurement always be expressed as BOTH a number (magnitude) AND a unit (e.g. ''15 metres'' and NOT just ''15'')?', 'A physical quantity Q = n · [U], where n is the dimensionless numerical multiplier and U is the standardized invariant unit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b075e20d-a286-47a1-b163-f90fa7485c4c', 'A pure number conveys no physical dimension or scale; the unit gives definite physical meaning and comparability to standard references', true, 'a6d93d16-df71-4f7d-ae25-e13e9ba80876');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b0aa851-0ef7-40ea-a5ff-d139c634fa2a', 'Because numbers are illegal without letters', false, 'a6d93d16-df71-4f7d-ae25-e13e9ba80876');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('922399d0-554f-4aef-926f-1efe14d4c95c', 'To make sentences longer', false, 'a6d93d16-df71-4f7d-ae25-e13e9ba80876');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a015b66c-a841-4cc1-a691-01fa5d398203', 'Because scientists like words', false, 'a6d93d16-df71-4f7d-ae25-e13e9ba80876');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ffa32087-cace-491f-95e7-c8c4a364be8d', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'What type of motion is executed by a marching soldier during a Republic Day parade along the straight Kartavya Path?', 'Linear forward center-of-mass translation (rectilinear) combines with periodic antagonistic pendular limb oscillations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b91dd1f-cae9-42b6-a750-2e4627551463', 'The soldier''s entire body moves in Rectilinear motion along the road, while their arms and legs swing in Periodic / Oscillatory motion', true, 'ffa32087-cace-491f-95e7-c8c4a364be8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc57ffb4-00c7-4f2c-856c-40b3f64b0e83', 'Pure circular motion', false, 'ffa32087-cace-491f-95e7-c8c4a364be8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27b9ddf5-66c8-4c13-9266-dee26c7d9216', 'Random chaotic motion', false, 'ffa32087-cace-491f-95e7-c8c4a364be8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e303677b-b020-43b9-8fa6-0f0b155ff089', 'Rotational spin', false, 'ffa32087-cace-491f-95e7-c8c4a364be8d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe4c9ae1-c7dc-45bd-82c0-53a595720fdf', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'Which of the following accurately describes the modern SI definition of 1 Metre adopted in 1983 by the CGPM?', 'The metre is defined by fixing the speed of light in vacuum c = 299,792,458 m/s, tying length directly to cesium atomic clocks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58ccef79-3e90-4d96-88c9-63cfbe450d23', 'The distance travelled by light in absolute vacuum during a time interval of 1 / 299,792,458 of a second', true, 'fe4c9ae1-c7dc-45bd-82c0-53a595720fdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4249976-55a9-48a0-966b-9d2610adbd93', 'The length of a king''s arm', false, 'fe4c9ae1-c7dc-45bd-82c0-53a595720fdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('451340d8-fdd6-42f2-8149-2b38e74cc18f', 'The circumference of Earth divided by 100', false, 'fe4c9ae1-c7dc-45bd-82c0-53a595720fdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61c6ecd5-3a8b-479e-b829-963f7282db2e', 'The length of a gold bar in London', false, 'fe4c9ae1-c7dc-45bd-82c0-53a595720fdf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f88fa6cb-0a75-48f6-a571-7d82a1e07e14', 'Class 6', 'Science', 'Chapter 7: Motion and Measurement of Distances', 'Hard', 'A toy train moves along a circular railway track of radius 7 metres. When it completes one full circle, what are its Distance travelled and Net Displacement respectively?', 'Scalar path distance = circumference = 2πr = 44 m; vector displacement = Δr = r_final - r_initial = 0 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5bd5a4c-1be0-4a65-97ce-0e8e36b59f85', 'Distance = 44 metres (2πr = 2 × 22/7 × 7) ; Displacement = 0 metres (since start and end points coincide)', true, 'f88fa6cb-0a75-48f6-a571-7d82a1e07e14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b716d39-7fb9-41c8-b6c6-192cd691f9fd', 'Distance = 0 m ; Displacement = 44 m', false, 'f88fa6cb-0a75-48f6-a571-7d82a1e07e14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0002fd88-9619-4adb-ae93-6aa7c828f08f', 'Distance = 14 m ; Displacement = 14 m', false, 'f88fa6cb-0a75-48f6-a571-7d82a1e07e14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fe804d5-461d-4f7b-bcb9-6707aa7d2ee2', 'Distance = 44 m ; Displacement = 44 m', false, 'f88fa6cb-0a75-48f6-a571-7d82a1e07e14');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e96ff96b-dcb5-41e9-92a8-9cdc86c8ff84', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'A number representing a part of a whole (where the whole may be a single object or a group of objects) is called a:', 'A fraction a/b expresses a parts taken out of b equal partitions of a whole.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67eb95b1-b88c-4781-858b-1bdf9a5ea51a', 'Fraction (written as a/b where b ≠ 0)', true, 'e96ff96b-dcb5-41e9-92a8-9cdc86c8ff84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c203fa2c-e4a7-44b8-a594-c22a7192d523', 'Integer', false, 'e96ff96b-dcb5-41e9-92a8-9cdc86c8ff84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f8aa57b-b983-424c-b63a-c115c20a0a41', 'Natural Number', false, 'e96ff96b-dcb5-41e9-92a8-9cdc86c8ff84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bda4e6b-1342-4bc2-9d27-f3670accfb33', 'Equation', false, 'e96ff96b-dcb5-41e9-92a8-9cdc86c8ff84');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6bae0861-ea18-4d08-89f5-982f17aafacf', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'In the fraction 3/5, what is the number 3 called and what is the number 5 called?', 'The top number is the Numerator (parts counted); the bottom number is the Denominator (total equal parts).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa997428-98e8-4fdf-94bd-ccdb0c337a41', '3 is the Numerator and 5 is the Denominator', true, '6bae0861-ea18-4d08-89f5-982f17aafacf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3e48214-1d74-4330-8e98-a60e8698bb8e', '3 is the Denominator and 5 is the Numerator', false, '6bae0861-ea18-4d08-89f5-982f17aafacf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1aad311-8150-4cf7-996c-b180e9a761be', 'Both are Numerators', false, '6bae0861-ea18-4d08-89f5-982f17aafacf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23ca923f-8052-4d38-9834-bcff25ecc969', 'Both are Denominators', false, '6bae0861-ea18-4d08-89f5-982f17aafacf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7f5bf9c-0a34-4cbe-847c-d9f2c2ee13e1', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'A fraction in which the Numerator is strictly LESS than the Denominator (Numerator < Denominator, representing a quantity less than 1) is a:', 'A proper fraction has a numerator smaller than its denominator, with a numeric value strictly between 0 and 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('699d9d62-7615-4b26-9aa5-3fc514023ee3', 'Proper Fraction (e.g., 2/3, 5/8, 1/4)', true, 'b7f5bf9c-0a34-4cbe-847c-d9f2c2ee13e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdd2ba17-ebeb-4517-a4fc-670c2dab34ec', 'Improper Fraction', false, 'b7f5bf9c-0a34-4cbe-847c-d9f2c2ee13e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5421b26-9ae1-475a-95f6-7defa4ff6ac9', 'Mixed Fraction', false, 'b7f5bf9c-0a34-4cbe-847c-d9f2c2ee13e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5c13204-3271-42d2-948f-a4348afb90a4', 'Unit Fraction', false, 'b7f5bf9c-0a34-4cbe-847c-d9f2c2ee13e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84aed64f-6505-49b1-ae09-08379f5c78af', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'A fraction in which the Numerator is GREATER than or equal to the Denominator (Numerator ≥ Denominator, representing a quantity ≥ 1) is an:', 'An improper fraction has a numerator greater than or equal to its denominator (value ≥ 1).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cef8c044-43d9-4618-a74d-cc0df98cdd38', 'Improper Fraction (e.g., 7/4, 9/5, 11/3)', true, '84aed64f-6505-49b1-ae09-08379f5c78af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f548da8f-a21b-494e-b8ef-8e1097b0b8ea', 'Proper Fraction', false, '84aed64f-6505-49b1-ae09-08379f5c78af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bde0c542-9547-4d0f-a74f-bb2968641206', 'Unit Fraction', false, '84aed64f-6505-49b1-ae09-08379f5c78af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6f03d1c-f372-4b3e-aa4b-7e7384a034ca', 'Decimal Fraction', false, '84aed64f-6505-49b1-ae09-08379f5c78af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd80536d-7109-41f6-819f-a158553d447a', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'A number expressed as a combination of a Whole number and a Proper fraction (like 2 ¾) is called a:', 'A mixed fraction (e.g. 2 ¾ = 2 + ¾ = 11/4) represents an integer quotient combined with a proper fractional remainder.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8820771-eb30-4789-b704-d705503a7149', 'Mixed Fraction', true, 'dd80536d-7109-41f6-819f-a158553d447a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60db7af0-b33a-4a11-81db-60dc57426979', 'Proper Fraction', false, 'dd80536d-7109-41f6-819f-a158553d447a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63897750-a70d-4841-8baf-e0abdc258ae2', 'Unit Fraction', false, 'dd80536d-7109-41f6-819f-a158553d447a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1598b8c0-9154-4092-b5ac-4ca48bb8ce96', 'Like Fraction', false, 'dd80536d-7109-41f6-819f-a158553d447a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f279d1c-668d-48e3-993a-c53effd9bb77', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'Fractions having the EXACT SAME denominator (such as 2/7, 5/7, 6/7) are called:', 'Fractions sharing an identical denominator are Like Fractions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32ebfcb0-1576-438a-887c-26c9eeadaafb', 'Like Fractions', true, '9f279d1c-668d-48e3-993a-c53effd9bb77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50460984-c05c-4a17-8e0c-f4d060b439b0', 'Unlike Fractions', false, '9f279d1c-668d-48e3-993a-c53effd9bb77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa452cb0-2000-41c0-8738-250ef999bc81', 'Equivalent Fractions', false, '9f279d1c-668d-48e3-993a-c53effd9bb77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4c2622b-a05e-4107-b15c-a3b8a8d6464f', 'Improper Fractions', false, '9f279d1c-668d-48e3-993a-c53effd9bb77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e34a675-c638-4007-894a-6142bad8c787', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'Fractions having DIFFERENT denominators (such as 2/3, 4/5, 7/9) are called:', 'Fractions with unequal denominators are Unlike Fractions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b7749f0-1dba-4e29-b49f-f8c59da59494', 'Unlike Fractions', true, '9e34a675-c638-4007-894a-6142bad8c787');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72dae3f5-b9ab-4b4d-8773-2a9741eb8d08', 'Like Fractions', false, '9e34a675-c638-4007-894a-6142bad8c787');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d78d556-4c74-412f-849b-e3a747bf776d', 'Unit Fractions', false, '9e34a675-c638-4007-894a-6142bad8c787');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a6c25c7-020a-40e2-9374-98c6854d5451', 'Mixed Fractions', false, '9e34a675-c638-4007-894a-6142bad8c787');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db080e60-1705-46a5-8e6d-4e7e89d1ff6a', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'A fraction whose numerator is always 1 (such as 1/2, 1/3, 1/4, 1/7) is called a:', 'A fraction of the form 1/n where n is a natural number is a Unit Fraction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eda7ac5c-f3d2-4755-a2d4-2f66f909e018', 'Unit Fraction', true, 'db080e60-1705-46a5-8e6d-4e7e89d1ff6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b5dd67c-875d-4f59-8b7b-78339890921c', 'Proper Fraction', false, 'db080e60-1705-46a5-8e6d-4e7e89d1ff6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('621a5367-bfaa-408b-8ccc-c228f127b994', 'Like Fraction', false, 'db080e60-1705-46a5-8e6d-4e7e89d1ff6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3323928d-0e95-4f6a-84b6-8579badccea7', 'Mixed Fraction', false, 'db080e60-1705-46a5-8e6d-4e7e89d1ff6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d9e9493-d96c-40ac-8c5a-3734a3f4fac4', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'What fraction of an hour is 20 minutes?', '1 hour = 60 minutes. Fraction = 20/60 = 1/3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23528060-2c61-4970-b3da-df52702788f9', '1/3 (20/60 = 1/3)', true, '6d9e9493-d96c-40ac-8c5a-3734a3f4fac4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09de1af5-458b-4d9e-8356-4efa8bb61a4a', '1/2', false, '6d9e9493-d96c-40ac-8c5a-3734a3f4fac4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5fd7378-5db2-4b67-b421-0e9e608f497d', '1/4', false, '6d9e9493-d96c-40ac-8c5a-3734a3f4fac4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afafc1bc-88ed-4da9-9b1d-c1c3f446d5b8', '2/5', false, '6d9e9493-d96c-40ac-8c5a-3734a3f4fac4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b39c7832-2302-4d62-bfc9-9d3d93c61ce1', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'What fraction of a day is 8 hours?', '1 day = 24 hours. Fraction = 8/24 = 1/3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65c956df-8bbb-41e3-9183-56c395b84f74', '1/3 (8/24 = 1/3)', true, 'b39c7832-2302-4d62-bfc9-9d3d93c61ce1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('552b0efb-2e4a-4052-945d-2d213ed1c15d', '1/4', false, 'b39c7832-2302-4d62-bfc9-9d3d93c61ce1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61319d5f-27bf-4730-99f8-e30256aad72f', '1/2', false, 'b39c7832-2302-4d62-bfc9-9d3d93c61ce1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c77eb1f-3c5d-4154-adab-85ff29731919', '3/8', false, 'b39c7832-2302-4d62-bfc9-9d3d93c61ce1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7839dbe-6e44-4a82-9a6b-1829d445a6b5', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'Convert the improper fraction 17/4 into a Mixed Fraction:', '17 ÷ 4 = 4 with remainder 1, yielding 4 ¼.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed643b7a-25fc-4791-b63f-16222a4fbdc3', '4 ¼ (17 ÷ 4 = 4 with remainder 1)', true, 'd7839dbe-6e44-4a82-9a6b-1829d445a6b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f70d38aa-5dc0-4e21-a9a9-05acbf849c06', '3 ¾', false, 'd7839dbe-6e44-4a82-9a6b-1829d445a6b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd1a2b6f-38e3-412f-a2db-9f3eee85b18b', '4 ½', false, 'd7839dbe-6e44-4a82-9a6b-1829d445a6b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cab311c-01fa-4272-b2de-7a276555f5ea', '5 ¼', false, 'd7839dbe-6e44-4a82-9a6b-1829d445a6b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('85ee35e5-46fb-410a-804f-603d3e84de2f', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Easy', 'Convert the mixed fraction 5 ⅔ into an Improper Fraction:', '(5 × 3 + 2) / 3 = (15 + 2) / 3 = 17/3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1dc56df-e9f7-4587-9ac2-f9c5d7b9356a', '17/3 ((5 × 3 + 2)/3 = 17/3)', true, '85ee35e5-46fb-410a-804f-603d3e84de2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77ed01fe-3a58-43e0-b124-85af89bd00ac', '13/3', false, '85ee35e5-46fb-410a-804f-603d3e84de2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bca5423-cfaa-4797-a743-32bccc7f7977', '15/3', false, '85ee35e5-46fb-410a-804f-603d3e84de2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9746721-cf2e-4976-ae88-5abab9130c21', '10/3', false, '85ee35e5-46fb-410a-804f-603d3e84de2f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b5d51b0-7104-4ad5-9e95-3abe138b066c', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Which of the following is an Equivalent Fraction to 2/5 with numerator 6?', 'Multiplying numerator and denominator by 3 gives (2 × 3) / (5 × 3) = 6/15.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee61dfde-3526-421c-89cd-775b18254506', '6/15 (multiply numerator and denominator by 3: 2×3 / 5×3)', true, '9b5d51b0-7104-4ad5-9e95-3abe138b066c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06eeacc5-2beb-476e-b507-16e84b59da82', '6/10', false, '9b5d51b0-7104-4ad5-9e95-3abe138b066c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('925f52ad-c5e9-4835-bfc5-1659753aeac0', '6/20', false, '9b5d51b0-7104-4ad5-9e95-3abe138b066c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a9a82b1-498d-4e4b-bc4c-08ebdaa424f8', '6/25', false, '9b5d51b0-7104-4ad5-9e95-3abe138b066c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f414eac-75db-484a-a541-117410ebc7a4', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'A fraction is said to be in its ''Simplest Form'' (or lowest terms) when:', 'A fraction a/b is in simplest irreducible form if gcd(a, b) = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ae37d35-4f93-4393-bc64-d10a5f137e17', 'The HCF of its Numerator and Denominator is strictly 1 (they are co-prime)', true, '9f414eac-75db-484a-a541-117410ebc7a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f319ef6-a11f-4863-a2d0-e7c80d8a7975', 'The numerator is 1', false, '9f414eac-75db-484a-a541-117410ebc7a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27db52eb-364b-494c-8fae-fb739e79ad88', 'The denominator is 100', false, '9f414eac-75db-484a-a541-117410ebc7a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('920870f8-0d80-429c-8737-ba3d2f8c64c7', 'The fraction is greater than 1', false, '9f414eac-75db-484a-a541-117410ebc7a4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3cdcbfc-10f3-4983-b8e7-037668dc541d', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Reduce the fraction 36/48 to its Simplest Form:', 'HCF(36, 48) = 12. 36 ÷ 12 / 48 ÷ 12 = 3/4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c19afa1-63ff-4678-8e41-8b2d1f4c17af', '3/4 (divide numerator and denominator by HCF = 12)', true, 'c3cdcbfc-10f3-4983-b8e7-037668dc541d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35d3088e-1f74-4698-9867-05298e3678a4', '2/3', false, 'c3cdcbfc-10f3-4983-b8e7-037668dc541d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ccc88b8-5fa3-4cff-b073-ae12b14a4dce', '6/8', false, 'c3cdcbfc-10f3-4983-b8e7-037668dc541d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('810b3ae2-816f-4f34-a9f2-354163dc3b7f', '18/24', false, 'c3cdcbfc-10f3-4983-b8e7-037668dc541d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4702bcd9-1984-4e97-bda0-fd6d06c93d8c', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Which fraction is LARGER: 3/5 or 4/7?', '3/5 = 21/35 and 4/7 = 20/35. Since 21/35 > 20/35, 3/5 is larger.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1e151a4-45a3-4568-a454-5aa7a0d80116', '3/5 (Cross-multiplying: 3 × 7 = 21 > 5 × 4 = 20)', true, '4702bcd9-1984-4e97-bda0-fd6d06c93d8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('481032c1-e772-4c5d-91ea-9f3a86cee2f7', '4/7', false, '4702bcd9-1984-4e97-bda0-fd6d06c93d8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f929a3a-1570-4167-a010-53fc043a783c', 'Both are equal', false, '4702bcd9-1984-4e97-bda0-fd6d06c93d8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f40dd37a-e252-491f-bc12-ac6f50f62538', 'Cannot be compared', false, '4702bcd9-1984-4e97-bda0-fd6d06c93d8c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b456d9b4-88c2-4f7b-b747-fd155edba47a', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Calculate the sum of like fractions: 3/11 + 5/11 + 2/11', 'For like fractions, add numerators over the common denominator: (3 + 5 + 2)/11 = 10/11.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35cf4330-433b-4d32-8888-63ec93023d77', '10/11', true, 'b456d9b4-88c2-4f7b-b747-fd155edba47a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7133e3d-d674-4ac3-acec-aa01a5381838', '10/33', false, 'b456d9b4-88c2-4f7b-b747-fd155edba47a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1712832-0cb5-4455-9e0d-3bc251bb9998', '1', false, 'b456d9b4-88c2-4f7b-b747-fd155edba47a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5fb3322-e5a0-4d26-bc63-708fc6e8d468', '8/11', false, 'b456d9b4-88c2-4f7b-b747-fd155edba47a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c32e313-5849-43eb-9b27-c6f448fecb8e', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Calculate the difference: 7/9 - 4/9', '(7 - 4)/9 = 3/9 = 1/3 in simplest form.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d30d92f9-7bba-43a0-aaf4-719cbfc6ce56', '3/9 = 1/3', true, '4c32e313-5849-43eb-9b27-c6f448fecb8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b4cb29a-47cc-4f71-80fd-3bb41ef37fab', '3/0', false, '4c32e313-5849-43eb-9b27-c6f448fecb8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eae6d252-69ef-4d23-aa35-bb09e10295d7', '11/9', false, '4c32e313-5849-43eb-9b27-c6f448fecb8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51d814c8-66b5-4ca4-b276-80d54cc30e9f', '3/18', false, '4c32e313-5849-43eb-9b27-c6f448fecb8e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe7ccb6f-e195-4454-ba54-47a40a069524', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Calculate the sum of unlike fractions: 2/5 + 1/3', 'LCM(5, 3) = 15. 2/5 = 6/15 and 1/3 = 5/15. Sum = (6 + 5)/15 = 11/15.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63d077e8-6921-4980-8ba8-b5fbfa0795c0', '11/15 ((6 + 5)/15 = 11/15)', true, 'fe7ccb6f-e195-4454-ba54-47a40a069524');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18ff6cc2-61e2-4030-b1f4-0a7e4a1b1b91', '3/8', false, 'fe7ccb6f-e195-4454-ba54-47a40a069524');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61e14d31-6b80-4da1-bf2d-33a879aa0bef', '2/15', false, 'fe7ccb6f-e195-4454-ba54-47a40a069524');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40492e93-cd8e-4fac-bc09-21ebd6472a63', '13/15', false, 'fe7ccb6f-e195-4454-ba54-47a40a069524');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68250370-ff5e-4c55-af4c-943ba262ebc1', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Calculate the difference: 5/6 - 3/4', 'LCM(6, 4) = 12. 5/6 = 10/12 and 3/4 = 9/12. Difference = (10 - 9)/12 = 1/12.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8a8e446-538d-4552-92cd-22dea69da4e7', '1/12 ((10 - 9)/12 = 1/12)', true, '68250370-ff5e-4c55-af4c-943ba262ebc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed0ae104-0d3e-4b11-bcef-6d3584bd6256', '2/2', false, '68250370-ff5e-4c55-af4c-943ba262ebc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1d5296e-2afe-4bf6-93b4-e9968609c1ba', '2/24', false, '68250370-ff5e-4c55-af4c-943ba262ebc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21cd4615-d94f-4a45-a1c7-a40d3bc02652', '1/6', false, '68250370-ff5e-4c55-af4c-943ba262ebc1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a2820e6f-889f-4972-8fd5-17d1e64530fb', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Solve the addition of mixed fractions: 2 ⅓ + 3 ½', 'Whole parts sum = 2 + 3 = 5. Fractional parts = 1/3 + 1/2 = 5/6. Total = 5 5/6.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d17fb3df-32aa-4aec-b338-ddcb62b2fa86', '5 ⅚ (7/3 + 7/2 = (14 + 21)/6 = 35/6 = 5 ⅚)', true, 'a2820e6f-889f-4972-8fd5-17d1e64530fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e10cdc0-4294-41a5-993c-0b34f0a05cba', '5 ⅖', false, 'a2820e6f-889f-4972-8fd5-17d1e64530fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e35e759-052a-4def-9e25-c0cf30dc4f17', '6 ⅚', false, 'a2820e6f-889f-4972-8fd5-17d1e64530fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c4d458a-1551-4a4b-b4af-485e87a1c0e6', '5 ⅔', false, 'a2820e6f-889f-4972-8fd5-17d1e64530fb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cabb950e-4da7-407b-a88a-05983cc793ac', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Solve the subtraction of mixed fractions: 4 ⅔ - 2 ⅕', '4 2/3 - 2 1/5 = (4 - 2) + (2/3 - 1/5) = 2 + (10 - 3)/15 = 2 7/15.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('266bdfe7-551b-4a01-8c39-1b2db7b26af8', '2 ⁷/₁₅ ((14/3 - 11/5) = (70 - 33)/15 = 37/15 = 2 ⁷/₁₅)', true, 'cabb950e-4da7-407b-a88a-05983cc793ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d30f8310-3a05-4b51-ad7f-405f256fbd15', '2 ⅖', false, 'cabb950e-4da7-407b-a88a-05983cc793ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad431c94-9184-4010-a727-612596680cf1', '2 ⅔', false, 'cabb950e-4da7-407b-a88a-05983cc793ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3dbbd07-353a-4b26-b310-b83007b26bc2', '1 ⁸/₁₅', false, 'cabb950e-4da7-407b-a88a-05983cc793ac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0acaea92-c658-40bf-84c4-43ba3438394e', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Ramesh had 20 pencils, Sheelu had 50 pencils, and Jamaal had 80 pencils. After 4 months, Ramesh used up 10 pencils, Sheelu used up 25 pencils, and Jamaal used up 40 pencils. What fraction of pencils did each use up?', '10/20 = 1/2; 25/50 = 1/2; 40/80 = 1/2. All three used up identical proportions (1/2).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f109caa-8d11-4248-a9ba-d4e467a27399', 'Each used up exactly 1/2 of their pencils (10/20 = 25/50 = 40/80 = 1/2)', true, '0acaea92-c658-40bf-84c4-43ba3438394e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db36c61b-87dc-4c84-a5dc-ae56bf95ffd0', 'Ramesh used 1/4, Sheelu 1/2, Jamaal 3/4', false, '0acaea92-c658-40bf-84c4-43ba3438394e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f72f137-09e6-45c0-8615-45ce3af577a4', 'Each used 1/3', false, '0acaea92-c658-40bf-84c4-43ba3438394e');
