INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45859b8c-8949-4e4a-918e-63436ee08bc3', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Jaidev takes 2 ⅕ minutes to walk across the school ground. Rahul takes 7/4 minutes to do the same. Who takes less time and by what fraction?', '11/5 = 44/20 min; 7/4 = 35/20 min. Rahul takes less time: 44/20 - 35/20 = 9/20 minutes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53f9eff3-d9fb-4e40-b381-86ea9b7f2fc9', 'Rahul takes less time by 9/20 minutes (Jaidev = 11/5 = 44/20 min ; Rahul = 7/4 = 35/20 min ; Difference = 9/20 min)', true, '45859b8c-8949-4e4a-918e-63436ee08bc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b32ab5c1-0037-4a7c-8dff-69e81c9ca243', 'Jaidev takes less time by 1/2 min', false, '45859b8c-8949-4e4a-918e-63436ee08bc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f387da4e-cc5e-490e-a6f0-ee858cd60466', 'Both take equal time', false, '45859b8c-8949-4e4a-918e-63436ee08bc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8edd8597-7546-410b-8610-cf7382898e7a', 'Rahul takes less time by 1/4 min', false, '45859b8c-8949-4e4a-918e-63436ee08bc3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ec60b964-d526-4634-91e9-33abda41c6c9', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'What must be subtracted from 7/8 to get 1/3?', '7/8 - x = 1/3 -> x = 7/8 - 1/3 = (21 - 8)/24 = 13/24.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f31bd078-0694-476a-8986-b894e7fee24f', '13/24 (7/8 - 1/3 = (21 - 8)/24 = 13/24)', true, 'ec60b964-d526-4634-91e9-33abda41c6c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a24adddd-6b16-4a81-9ba3-bf4ab966b942', '11/24', false, 'ec60b964-d526-4634-91e9-33abda41c6c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('832672ee-883c-4e81-baab-c5206deea379', '5/8', false, 'ec60b964-d526-4634-91e9-33abda41c6c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdb6c9cd-d805-4c18-bc83-24411d0023e0', '2/3', false, 'ec60b964-d526-4634-91e9-33abda41c6c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('90afc04a-4757-4b15-a312-e154bba43b5e', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'What should be added to 3/7 to get 1?', '1 - 3/7 = 7/7 - 3/7 = 4/7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57f81796-8e60-4133-bb81-916a576b189c', '4/7 (1 - 3/7 = (7 - 3)/7 = 4/7)', true, '90afc04a-4757-4b15-a312-e154bba43b5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45f8bd03-5d2a-48a0-8197-63e55d3ad6c2', '3/7', false, '90afc04a-4757-4b15-a312-e154bba43b5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac4883b3-d746-4b3d-9840-4cea302041c7', '7/3', false, '90afc04a-4757-4b15-a312-e154bba43b5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c135d03-084c-48c8-9550-47a06b2508c6', '1/7', false, '90afc04a-4757-4b15-a312-e154bba43b5e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0259550a-1714-4574-ab89-08a6f35b1d4f', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'Sarita bought 2/5 metre of ribbon and Lalita bought 3/4 metre of ribbon. What is the total length of the ribbon they bought together?', '2/5 + 3/4 = (8 + 15)/20 = 23/20 = 1 3/20 metres.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f45bf52-81a3-42e2-a609-b9e60a38e619', '1 ³/₂₀ metres ((8 + 15)/20 = 23/20 = 1 ³/₂₀ m)', true, '0259550a-1714-4574-ab89-08a6f35b1d4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('745da072-9cb9-4381-8af2-6786c846912f', '1 ½ m', false, '0259550a-1714-4574-ab89-08a6f35b1d4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff210335-57e4-400a-94a3-fcddaa375a18', '5/9 m', false, '0259550a-1714-4574-ab89-08a6f35b1d4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce962c88-e7db-44b9-90f2-dfb4a0d69293', '1 ⅖ m', false, '0259550a-1714-4574-ab89-08a6f35b1d4f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03ce5105-453b-4e5a-b21e-5ca48f22b7b6', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Medium', 'A piece of wire 7/8 metre long broke into two pieces. One piece was 1/4 metre long. How long is the other piece?', '7/8 - 1/4 = 7/8 - 2/8 = 5/8 metre.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87209985-9b39-49e6-b6fd-dbd4fa74d19e', '5/8 metre (7/8 - 1/4 = 7/8 - 2/8 = 5/8 m)', true, '03ce5105-453b-4e5a-b21e-5ca48f22b7b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0eec0b4-1309-4627-93c8-33ca71a094f4', '3/8 m', false, '03ce5105-453b-4e5a-b21e-5ca48f22b7b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e397436e-3860-445b-bc76-c3082605f898', '6/8 m', false, '03ce5105-453b-4e5a-b21e-5ca48f22b7b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb37d9dd-df5d-4df8-8cda-4a3328d18423', '1/2 m', false, '03ce5105-453b-4e5a-b21e-5ca48f22b7b6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63416502-02eb-4993-92a4-7a3df8316795', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcd44006-6db7-4f41-94b3-fabe5527105d', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '63416502-02eb-4993-92a4-7a3df8316795');
