INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('404b2338-a83c-45db-b59c-435161e41ed4', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'Spot the IMPOSTER in the following group of fractions that is NOT equivalent to 2/3:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88584cd9-213a-432d-8d1a-8322fe178088', '4/6', false, '404b2338-a83c-45db-b59c-435161e41ed4');
