INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a53c6d24-a783-4f6b-9023-6c45e7fc7584', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'Simplify the complex fractional expression:
(3 ⅓ + 4 ¼) - (2 ½ + 1 ⅚)', '(10/3 + 17/4) - (5/2 + 11/6) = (40 + 51)/12 - (15 + 11)/6 = 91/12 - 26/6 = 91/12 - 52/12 = 39/12 = 13/4 = 3 ¼.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('380750f9-02a6-45cb-810e-53c2399c9316', '3 ¼ (7 ⁷/₁₂ - 4 ⁴/₆ = 91/12 - 52/12 = 39/12 = 13/4 = 3 ¼)', true, 'a53c6d24-a783-4f6b-9023-6c45e7fc7584');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf26e33e-7850-4283-b9b7-557d83ead912', '3 ½', false, 'a53c6d24-a783-4f6b-9023-6c45e7fc7584');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4aec038c-4df0-4288-a7d5-085a4dd27188', '2 ¾', false, 'a53c6d24-a783-4f6b-9023-6c45e7fc7584');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c46701d2-3de7-46ab-b96c-c6c6c9f119d2', '4 ¼', false, 'a53c6d24-a783-4f6b-9023-6c45e7fc7584');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('925f4c0c-5cc8-479f-9437-058e655274e7', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'Match Column I (Fraction Pairs) with Column II (Comparison Symbol):
(a) 5/8  ____ 5/12 -> (i) > (Same numerator: smaller denominator is larger)
(b) 3/7  ____ 4/7  -> (ii) < (Same denominator: larger numerator is larger)
(c) 4/6  ____ 2/3  -> (iii) =
(d) 7/10 ____ 3/5  -> (iv) > (since 7/10 > 6/10)', 'a: 5/8 > 5/12; b: 3/7 < 4/7; c: 4/6 = 2/3; d: 7/10 > 3/5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('171fb589-5f2c-4817-97e5-4bedb037f46b', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '925f4c0c-5cc8-479f-9437-058e655274e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7c17c50-7cc1-46eb-bae7-7a547bdd404f', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '925f4c0c-5cc8-479f-9437-058e655274e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d18e860-b278-4116-b3f3-6e1991a63f86', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '925f4c0c-5cc8-479f-9437-058e655274e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c63636ba-7049-4952-901f-53dbeed9ff5f', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '925f4c0c-5cc8-479f-9437-058e655274e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('248dbc28-3584-44c9-829e-3ba5261257db', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('384f8084-44b2-49ef-83c0-4123ce0704b8', 'Statements 1 and 2 only', true, '248dbc28-3584-44c9-829e-3ba5261257db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bc382a0-2619-49bd-a651-855af4d3cc41', 'Statements 2 and 3 only', false, '248dbc28-3584-44c9-829e-3ba5261257db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d653f2f1-4091-41aa-ac4e-280b1efed142', 'Statements 1 and 3 only', false, '248dbc28-3584-44c9-829e-3ba5261257db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f9ca2e7-ce78-4749-a2c0-50b2766ee4b0', 'All Statements 1, 2, and 3', false, '248dbc28-3584-44c9-829e-3ba5261257db');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e545b906-48ae-4cc5-8251-328ac35ee200', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'Arrange the following unlike fractions in ASCENDING order: 2/3, 1/6, 5/9, 7/12', 'LCM(3, 6, 9, 12) = 36: 1/6 = 6/36, 5/9 = 20/36, 7/12 = 21/36, 2/3 = 24/36.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eabb90eb-6318-44c4-9bcc-f5e29705f375', '1/6 < 5/9 < 7/12 < 2/3 (LCM = 36: 6/36 < 20/36 < 21/36 < 24/36)', true, 'e545b906-48ae-4cc5-8251-328ac35ee200');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71552d93-7a04-46bf-8983-83ea8ee51f40', '1/6 < 7/12 < 5/9 < 2/3', false, 'e545b906-48ae-4cc5-8251-328ac35ee200');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46b3a15d-f13c-4c16-9a98-8b5cfbfa1028', '2/3 < 7/12 < 5/9 < 1/6', false, 'e545b906-48ae-4cc5-8251-328ac35ee200');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('766d5a40-e628-434f-a982-c8dfb90e1dd8', '5/9 < 1/6 < 7/12 < 2/3', false, 'e545b906-48ae-4cc5-8251-328ac35ee200');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99288a9a-2720-4a72-9127-cae2177f3c30', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'In a class of 45 students, 2/5 of the total students are girls. How many boys are there in the class?', 'Girls = 2/5 of 45 = 18. Boys = 3/5 of 45 = 27.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf93fadd-8310-4606-b421-267133748ffe', '27 boys (Girls = 45 × 2/5 = 18 ; Boys = 45 - 18 = 27)', true, '99288a9a-2720-4a72-9127-cae2177f3c30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a395319-99bc-4b31-8c08-089fb6944440', '18 boys', false, '99288a9a-2720-4a72-9127-cae2177f3c30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca527bec-42fa-488f-b49d-0de920750fda', '25 boys', false, '99288a9a-2720-4a72-9127-cae2177f3c30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e605356-f1c6-48dc-bae9-899cc484ccc6', '30 boys', false, '99288a9a-2720-4a72-9127-cae2177f3c30');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e355a9de-be29-4360-a42f-2454a316170b', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'A tank is 3/5 full of water. If 50 litres of water is needed to fill the tank completely, what is the total capacity of the tank?', 'Remaining 2/5 = 50 litres -> Full capacity = 50 × (5/2) = 125 litres.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f195b296-8a33-485c-90dc-34cada60b3a6', '125 litres (Empty fraction = 1 - 3/5 = 2/5 ; 2/5 of Total = 50 L -> Total = 50 × 5/2 = 125 L)', true, 'e355a9de-be29-4360-a42f-2454a316170b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a214d70-eb64-4dda-b72b-acabd736da0a', '100 litres', false, 'e355a9de-be29-4360-a42f-2454a316170b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba3b32e6-a025-4f66-80b3-c1fa2b5ecfe8', '150 litres', false, 'e355a9de-be29-4360-a42f-2454a316170b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('353ce903-bdfa-4c42-bb79-bad9ff66c9cd', '200 litres', false, 'e355a9de-be29-4360-a42f-2454a316170b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('157236f5-1de7-45ce-8678-132eb89de560', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'How is the fraction 3 ⅝ represented on a number line?', '3 ⅝ lies on the interval [3, 4] at 3/8 distance beyond 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4310ccb-ec09-4c63-9b04-a4b8d87e3317', 'Between integers 3 and 4, dividing the unit segment into 8 equal parts and taking the 3rd mark from 3', true, '157236f5-1de7-45ce-8678-132eb89de560');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e44348f3-b44f-44fd-8776-268e28eb3f10', 'Between 0 and 1', false, '157236f5-1de7-45ce-8678-132eb89de560');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55c4258e-098e-468d-909a-82a72aac5138', 'Between 2 and 3', false, '157236f5-1de7-45ce-8678-132eb89de560');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec531186-21f8-46f6-97ec-1a89326cf2e3', 'Between 5 and 6', false, '157236f5-1de7-45ce-8678-132eb89de560');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d402436-44c0-4ff1-b531-63b4849ec0d7', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'Which of the following fraction pairs are NOT co-prime in their current form and can be reduced further?', 'HCF(84, 98) = 14 ≠ 1. 84/98 = 6/7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcd84b95-0e42-4dc1-be86-bd2f2f5df3da', '84/98 (both divisible by 14: 6/7)', true, '8d402436-44c0-4ff1-b531-63b4849ec0d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3657dca3-53ef-4957-b60c-c1397067b179', '15/37', false, '8d402436-44c0-4ff1-b531-63b4849ec0d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71cf79d1-b989-45ac-a568-c7d6f2aacebd', '8/15', false, '8d402436-44c0-4ff1-b531-63b4849ec0d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ac45c57-01a5-4e8b-bb72-9a4959fa8886', '11/17', false, '8d402436-44c0-4ff1-b531-63b4849ec0d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2cdf31d2-23e4-4d81-b237-f14150c5ff9a', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'Solve the missing fraction in the box: [ ? ] - 5/8 = 1/4', '? = 1/4 + 5/8 = 2/8 + 5/8 = 7/8.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba9c46ab-652c-4279-a299-d04a6b2615fc', '7/8 (1/4 + 5/8 = 2/8 + 5/8 = 7/8)', true, '2cdf31d2-23e4-4d81-b237-f14150c5ff9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55b8b648-9953-45a2-8ff4-f8c2cfc9461f', '6/8', false, '2cdf31d2-23e4-4d81-b237-f14150c5ff9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35a5008c-90c0-4811-af0d-50224eb0382a', '3/8', false, '2cdf31d2-23e4-4d81-b237-f14150c5ff9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1fc1cf9-c84e-473a-992e-a9b158660c2e', '1/2', false, '2cdf31d2-23e4-4d81-b237-f14150c5ff9a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e689136a-e87b-4543-8bd4-3bdf1de9f87c', 'Class 6', 'Mathematics', 'Chapter 7: Fractions', 'Hard', 'A cake was divided into 12 equal slices. Anil ate 1/4 of the cake, Sunita ate 1/3 of the cake, and the rest was eaten by Rohan. What fraction of the cake did Rohan eat?', '1 - (1/4 + 1/3) = 1 - (3/12 + 4/12) = 1 - 7/12 = 5/12.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('622b6e30-7c48-4472-be47-7b8049e32e6d', '5/12 (Anil = 3/12 ; Sunita = 4/12 ; Remaining = 12/12 - 7/12 = 5/12)', true, 'e689136a-e87b-4543-8bd4-3bdf1de9f87c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('727b0189-a7fd-40c9-91b6-9a0dabae3fb0', '1/12', false, 'e689136a-e87b-4543-8bd4-3bdf1de9f87c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3c7a75b-b392-4770-a843-f7759bb95acc', '7/12', false, 'e689136a-e87b-4543-8bd4-3bdf1de9f87c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('584af487-7588-4b4c-8e37-6a56492d797a', '1/2', false, 'e689136a-e87b-4543-8bd4-3bdf1de9f87c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d4a847c-66cd-45fa-a728-c05bef9ebe57', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'Who were the two inseparable childhood friends whose deep bond of friendship was celebrated across the village in ''Fair Play''?', 'Jumman Shaikh and Algu Chowdhry shared an iconic village friendship; whenever either went away, the other looked after his household.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa586631-41c7-40a0-ab15-d52f71554cd2', 'Jumman Shaikh and Algu Chowdhry', true, '3d4a847c-66cd-45fa-a728-c05bef9ebe57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdc28760-81b3-42c6-859a-2f6b8b9bd711', 'Samjhu Sahu and Jumman', false, '3d4a847c-66cd-45fa-a728-c05bef9ebe57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d2db94c-a71e-4648-8861-3d088428c5ce', 'Premchand and Algu', false, '3d4a847c-66cd-45fa-a728-c05bef9ebe57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('043d5bd1-be54-4b96-ba65-f185760d290c', 'Rahim and Karim', false, '3d4a847c-66cd-45fa-a728-c05bef9ebe57');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d690661d-a7a3-47d3-a0d2-4b54e36b1bdc', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'Why did Jumman''s elderly maternal aunt transfer her property and land to Jumman?', 'The aunt transferred her property in exchange for lifelong care and maintenance from Jumman and his family.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0005e35-8b0f-41cc-82d8-df0f018a2377', 'On the condition that she would stay with him and he would look after and care for her until her death', true, 'd690661d-a7a3-47d3-a0d2-4b54e36b1bdc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47965c96-fe08-457a-ba86-f57f2f3c0d8a', 'Because she wanted to sell the land', false, 'd690661d-a7a3-47d3-a0d2-4b54e36b1bdc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8fd1f90-e968-493e-ac39-d18797332129', 'Because she had no house', false, 'd690661d-a7a3-47d3-a0d2-4b54e36b1bdc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07217839-b7d5-4c2d-bd0d-e69d3de2e3aa', 'Because the village panchayat ordered her', false, 'd690661d-a7a3-47d3-a0d2-4b54e36b1bdc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62ad30e3-b37c-46d2-a137-7d5b3d507e6d', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'How did Jumman and his wife Kariman treat the old aunt after the property transfer was officially completed?', 'Once the land was secured, Jumman grew cold and his wife Kariman grudged every bite of food given to the old lady.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a60c3e7-baf7-4957-b0c4-2dc1731fb929', 'They became indifferent and harsh, grudging even the small amount of daily food she ate and insulting her', true, '62ad30e3-b37c-46d2-a137-7d5b3d507e6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e555e4d1-ed12-4b88-ac8a-190039d004b6', 'They treated her like a queen', false, '62ad30e3-b37c-46d2-a137-7d5b3d507e6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eca44c90-98e4-4766-868b-827a0b4c9922', 'They built her a palace', false, '62ad30e3-b37c-46d2-a137-7d5b3d507e6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c98879db-734d-44cd-92da-acc6685bbef8', 'They gave her all their money', false, '62ad30e3-b37c-46d2-a137-7d5b3d507e6d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f31921cf-637a-42f8-b819-4089012cab94', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'What reasonable demand did the mistreated aunt make when she could no longer bear the daily insults?', 'The aunt requested a modest monthly allowance so she could cook independently with dignity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aacbee09-1d69-4bfe-a4c1-367290728159', 'She asked for a small monthly allowance to set up a separate kitchen for herself', true, 'f31921cf-637a-42f8-b819-4089012cab94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('906cd45a-b31b-46f5-b63f-9b1e7941c2cd', 'She asked for all of Jumman''s property', false, 'f31921cf-637a-42f8-b819-4089012cab94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8baba87a-f66b-4827-a924-dbe423104744', 'She asked to leave the country', false, 'f31921cf-637a-42f8-b819-4089012cab94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a97727f-0bbf-4705-9e9d-f341f1aa3a7f', 'She asked for a car', false, 'f31921cf-637a-42f8-b819-4089012cab94');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b47a9c8c-41af-431c-a83f-215bd0a1e90b', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'Whom did the aunt nominate as the Head Panch (Sarpanch) in the village panchayat?', 'Trusting in pure justice, the aunt nominated Algu Chowdhry, knowing a true Panch has no friends or enemies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e74bb6cf-4c37-4719-8bfc-bc97cc0fed47', 'Algu Chowdhry (Jumman''s best friend)', true, 'b47a9c8c-41af-431c-a83f-215bd0a1e90b');
