INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9366a08-3ec1-41fe-a807-46d54a7f5055', 'The Village Headman', false, 'b47a9c8c-41af-431c-a83f-215bd0a1e90b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8907f4d2-3b76-4f29-a8e0-6062c59b23f3', 'Her nephew', false, 'b47a9c8c-41af-431c-a83f-215bd0a1e90b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf85cbde-cdd8-451a-8033-4bccde7cd423', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'What famous principle did the aunt state to Algu: ''The voice of the Panch is the voice of...''?', 'The aunt declared: ''God lives in the heart of the Panch, and his voice is the voice of God.''', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c15ba2a-a5e2-4d82-b95d-225784d847ea', 'God', true, 'cf85cbde-cdd8-451a-8033-4bccde7cd423');
