INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d7c4730-f908-46ce-8d15-2d3dcf3914e5', 'The Village', false, 'cf85cbde-cdd8-451a-8033-4bccde7cd423');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a67eaaf-1559-4c60-a566-bfca34c78df5', 'Justice', false, 'cf85cbde-cdd8-451a-8033-4bccde7cd423');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2fd00632-62f8-499c-9045-8618d674043a', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'What verdict did Head Panch Algu Chowdhry deliver in the panchayat case regarding the aunt?', 'Upholding absolute justice over personal friendship, Algu ruled that Jumman must pay the allowance or surrender the land.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2c53157-dc8c-4a19-ac48-b4680c7d300c', 'Jumman must pay his aunt a monthly allowance, or the transferred property will be returned to her immediately', true, '2fd00632-62f8-499c-9045-8618d674043a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('def3cf6c-ab45-4cd0-88c9-3f771a5b6f40', 'The aunt must leave the village', false, '2fd00632-62f8-499c-9045-8618d674043a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a76ed818-38d4-4d32-be4a-00ac86ac7e5f', 'Jumman is innocent', false, '2fd00632-62f8-499c-9045-8618d674043a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1f602e7-4c93-4b2d-bf95-89cec80b7fbb', 'The property must be sold', false, '2fd00632-62f8-499c-9045-8618d674043a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1f00e7e1-115d-4c4e-82e2-4b2363bc0673', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'How did Algu''s fair judgment affect his friendship with Jumman?', 'Jumman harbored deep resentment against Algu, awaiting an opportunity to take revenge.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69f19d76-6bda-48c4-bc39-7614bf7e1708', 'The bond of friendship was broken; Jumman felt betrayed and saw Algu as his bitter enemy, seeking revenge', true, '1f00e7e1-115d-4c4e-82e2-4b2363bc0673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc9faea5-6892-4fc1-8213-7cc65f049ac0', 'They became even closer friends', false, '1f00e7e1-115d-4c4e-82e2-4b2363bc0673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74413b14-c582-434b-b067-9e6c7c526756', 'They started a business together', false, '1f00e7e1-115d-4c4e-82e2-4b2363bc0673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6dff9ec6-3d43-4a2b-b1db-c74c01261630', 'They moved to the city', false, '1f00e7e1-115d-4c4e-82e2-4b2363bc0673');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea548029-2a65-49dc-9d42-c661c70f109b', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'To whom did Algu sell his fine surviving bullock on the promise of payment within a month?', 'Algu sold his bullock to Samjhu Sahu, who used it to transport goods between the village and town.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42e8581e-b456-427a-9dc3-6ba2031dca51', 'Samjhu Sahu (a village cart driver)', true, 'ea548029-2a65-49dc-9d42-c661c70f109b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc24d6cf-c818-40b5-8008-e250a325d9ef', 'Jumman Shaikh', false, 'ea548029-2a65-49dc-9d42-c661c70f109b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48001b62-047f-4135-9e73-6f3419e5a27c', 'The village priest', false, 'ea548029-2a65-49dc-9d42-c661c70f109b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be8e179c-fd61-4997-859d-352dbb30eae7', 'A merchant in town', false, 'ea548029-2a65-49dc-9d42-c661c70f109b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66b2399c-bdbc-4e7f-bd2f-668062d69025', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'Why did the bullock die within a month of being purchased by Samjhu Sahu?', 'Cruel overworking and severe malnutrition caused the exhausted beast to collapse and die on the road.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d85faf7-359a-4ee4-967e-678cb15be142', 'Sahu overworked the poor animal with multiple daily trips, gave it little water and only dry straw/fodder to eat', true, '66b2399c-bdbc-4e7f-bd2f-668062d69025');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4a54a9e-3b8f-4741-8266-9fa6850de6c6', 'It fell into a deep river', false, '66b2399c-bdbc-4e7f-bd2f-668062d69025');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dc71c5f-afc1-4c27-a38f-4e8ea0a1230d', 'It was bitten by a snake', false, '66b2399c-bdbc-4e7f-bd2f-668062d69025');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b30d869-3c72-462e-bed4-b549cc3a6623', 'It was poisoned', false, '66b2399c-bdbc-4e7f-bd2f-668062d69025');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d5a40dbb-8f37-4b8f-b91d-f27efa5fa23c', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'Whom did Samjhu Sahu nominate as Head Panch when Algu took the unpaid bullock case to the panchayat?', 'Sahu cunningly chose Jumman, expecting him to deliver a revenge verdict against Algu.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eea79afa-0ec4-4a9f-ad4c-b29b936e6f21', 'Jumman Shaikh (Algu''s estranged enemy)', true, 'd5a40dbb-8f37-4b8f-b91d-f27efa5fa23c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bb3eb20-3546-4d96-bc96-bd62537ba0f9', 'The village headman', false, 'd5a40dbb-8f37-4b8f-b91d-f27efa5fa23c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('818a41a0-19f6-45cb-b45a-cef7c8785a46', 'The old aunt', false, 'd5a40dbb-8f37-4b8f-b91d-f27efa5fa23c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c33a92b7-422e-4cdc-8f2c-f31599f88462', 'A merchant', false, 'd5a40dbb-8f37-4b8f-b91d-f27efa5fa23c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4597c021-a62c-42e7-91a9-0c0502747a37', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Easy', 'In the supplementary chapter ''The Wonder Called Sleep'', what happens to our body temperature and blood pressure during deep sleep?', 'During deep somatic sleep, metabolic basal rate drops, reducing muscular tone, body temperature, and arterial pressure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e29bd13-002c-4686-9eef-a849e92bf220', 'Body temperature falls and blood pressure drops as muscles relax completely', true, '4597c021-a62c-42e7-91a9-0c0502747a37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81bfc582-7e36-4d3c-9c27-835fdeca403d', 'Body temperature rises to boiling point', false, '4597c021-a62c-42e7-91a9-0c0502747a37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f0d1aa8-26f4-44ce-b85a-0a588667aff7', 'Blood pressure doubles', false, '4597c021-a62c-42e7-91a9-0c0502747a37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fad19d71-1e9e-4807-af53-3d208451f388', 'The heart stops beating', false, '4597c021-a62c-42e7-91a9-0c0502747a37');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('634e38dc-93c1-4c94-a31d-c6c13c6aa9ee', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What profound realization came over Jumman Shaikh the moment he sat on the seat of the Head Panch?', 'The solemn office of Sarpanch awakened Jumman''s conscience, transcending personal grudge to embrace immaculate justice.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f49084cd-0030-4bb1-bd12-aa0346896c09', 'He felt the supreme gravity and sanctity of justice; as a Panch, he represented divine truth above all personal enmity or friendship', true, '634e38dc-93c1-4c94-a31d-c6c13c6aa9ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb0fd69c-947a-4b44-88a4-bb38c7bb6806', 'He decided to take sweet revenge on Algu', false, '634e38dc-93c1-4c94-a31d-c6c13c6aa9ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b70e7744-0eeb-46b5-ae02-6f6633228fb4', 'He wanted to punish everyone', false, '634e38dc-93c1-4c94-a31d-c6c13c6aa9ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffe31faa-3338-40c1-aa68-1ccca422a880', 'He wanted to run away', false, '634e38dc-93c1-4c94-a31d-c6c13c6aa9ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58ec1cb0-02ed-4871-8a97-0c3f1aff8b12', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What verdict did Head Panch Jumman deliver in the dispute between Algu and Samjhu Sahu?', 'Jumman ruled impartially: since the bullock was healthy at purchase, Sahu was legally and morally obligated to pay the full price.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd227a76-759d-4517-9bbb-04b4fdefc826', 'Samjhu Sahu must pay Algu the full price of the bullock, because the bullock suffered from no disability when sold and died solely due to Sahu''s ill-treatment and neglect', true, '58ec1cb0-02ed-4871-8a97-0c3f1aff8b12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b004760d-f931-49f5-a2d6-0e41f5dcb01e', 'Algu must pay a fine to Sahu', false, '58ec1cb0-02ed-4871-8a97-0c3f1aff8b12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('549a1700-f065-45d1-a220-7c4680fe6f68', 'Both must go to jail', false, '58ec1cb0-02ed-4871-8a97-0c3f1aff8b12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72b3c98a-6d1c-4622-8591-207f349a9baa', 'The money should be given to the panchayat', false, '58ec1cb0-02ed-4871-8a97-0c3f1aff8b12');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d2d24f58-4ce8-4c41-9076-3b23002cbd4b', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What did Algu and Jumman do after the verdict was pronounced?', 'The righteous judgment reconciled the two friends, restoring their mutual respect and sacred bond.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60a4da4f-726b-4d1a-924d-867a06c0fcf1', 'Algu wept with joy shouting ''Victory to the Panchayat!'', and both friends embraced each other, washing away all misunderstandings with tears', true, 'd2d24f58-4ce8-4c41-9076-3b23002cbd4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c4d1b6d-439a-4a01-b055-b579db46edc3', 'They had a fist fight', false, 'd2d24f58-4ce8-4c41-9076-3b23002cbd4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfd8da6d-0c67-43ed-90d2-6666622633ff', 'They left the village forever', false, 'd2d24f58-4ce8-4c41-9076-3b23002cbd4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cff3c35a-3fbd-48ef-888c-e6e9d285cec4', 'They refused to speak', false, 'd2d24f58-4ce8-4c41-9076-3b23002cbd4b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e2a5456-040e-4296-b640-c6309add80e7', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What is the core moral and philosophical message of Premchand''s ''Fair Play''?', 'The story immortalizes the principle that judicial duty demands immaculate neutrality and allegiance to truth alone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33c85d2b-5343-49ba-a4b7-3630af200036', 'Justice transcends all personal relationships, friendships, and enmities; when seated in judgment, one is the voice of God and must remain strictly impartial', true, '6e2a5456-040e-4296-b640-c6309add80e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49069200-457d-4a80-90a4-9edfe6da52b1', 'Friends should never lend money', false, '6e2a5456-040e-4296-b640-c6309add80e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46543a4e-131e-44ef-91c5-ab3942170fa7', 'Bullocks should not be sold', false, '6e2a5456-040e-4296-b640-c6309add80e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88289e3c-10fb-417a-81f8-8b2802b55318', 'Panchayats should be avoided', false, '6e2a5456-040e-4296-b640-c6309add80e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a69613e-db54-44ed-91d1-c28f35953057', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'In ''The Wonder Called Sleep'', why is sleep called an ''unconscious state of rest'' and a miraculous wonder?', 'Sleep is biological restorative maintenance, facilitating neurocellular recovery and memory consolidation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('085d9dd3-939c-48ef-ac46-ffddfb186559', 'It recharges and heals our fatigued body and mind, restoring full vigor, mental clarity, and somatic energy for the next day''s activities', true, '0a69613e-db54-44ed-91d1-c28f35953057');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3404b4f-c9c4-4296-8139-3fd7866cf13d', 'It makes humans fly in reality', false, '0a69613e-db54-44ed-91d1-c28f35953057');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ca44b3d-688f-4c91-bb02-879a114e41ff', 'It stops aging permanently', false, '0a69613e-db54-44ed-91d1-c28f35953057');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f99787b7-bd21-4244-8257-5db3c59e39ec', 'It erases all human memories', false, '0a69613e-db54-44ed-91d1-c28f35953057');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('85607a2a-1433-4e6e-82fd-d5d79047342d', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What is a ''Dream'' according to the scientific explanation in ''The Wonder Called Sleep''?', 'Dreams are neuro-cognitive simulations during REM sleep aiding psychological equilibrium and creative problem solving.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62b3a540-d32e-4076-ab75-9d6a3dcb12dd', 'An active state of mind during sleep where the brain processes subconscious thoughts, emotions, and daily memories, sometimes revealing solutions to problems', true, '85607a2a-1433-4e6e-82fd-d5d79047342d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02a1afb2-28b6-48c0-9401-44d78ac84f29', 'A message from aliens', false, '85607a2a-1433-4e6e-82fd-d5d79047342d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('defd7c5e-cea4-49fd-a9d3-c4c141b96a8b', 'A magical vision of the past', false, '85607a2a-1433-4e6e-82fd-d5d79047342d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e6ffe93-300c-49a9-9e71-61c517e5de24', 'A disease of the brain', false, '85607a2a-1433-4e6e-82fd-d5d79047342d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1fe95170-7d06-405e-8e43-9cbd8dbfbf88', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'Why can dreams NEVER predict the future?', 'NCERT clarifies that while dreams process subjective memory traces, they possess no supernatural predictive validity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed91eaf7-c2d2-4f7e-b7ad-eaf3d29574b5', 'Dreams are merely internal neural processing of our own past experiences, subconscious desires, and fears, having no magical psychic power to foretell future events', true, '1fe95170-7d06-405e-8e43-9cbd8dbfbf88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f28a62c3-b20f-4bb9-8b41-e907f10fec47', 'Because dreams only last 1 second', false, '1fe95170-7d06-405e-8e43-9cbd8dbfbf88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8834b719-7a99-4507-8ed0-6b86d3315c98', 'Because future is written in stone', false, '1fe95170-7d06-405e-8e43-9cbd8dbfbf88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06f01229-a43d-451a-b166-22fec92f68e5', 'Because sleep blocks the future', false, '1fe95170-7d06-405e-8e43-9cbd8dbfbf88');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0aa2b9aa-5ce1-490a-947b-3096f7646f3e', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What poetic phrase did Edward Thomas use to describe sleep in his famous poem ''Lights Out''?', 'Thomas portrays sleep as an enigmatic boundless forest into which all travelers, ambition, and passions inevitably descend.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e340efcc-b426-482c-aaf3-00e456f2db26', 'The unfathomable deep forest where all human paths must lose their way', true, '0aa2b9aa-5ce1-490a-947b-3096f7646f3e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8ba03c7-ef4c-44a6-b606-75b182537154', 'A shining golden castle', false, '0aa2b9aa-5ce1-490a-947b-3096f7646f3e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d54bd89-4826-46b6-b06c-73150c22349a', 'A stormy ocean', false, '0aa2b9aa-5ce1-490a-947b-3096f7646f3e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('518c7113-fc55-4932-8e64-542f359a9281', 'A dark prison cell', false, '0aa2b9aa-5ce1-490a-947b-3096f7646f3e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5fbac60e-4c3b-4713-a064-18b32518c2a3', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What does the idiom ''to swallow insults'' mean in the context of the aunt enduring mistreatment?', '''To swallow insults'' denotes stoically absorbing verbal humiliation without outward resistance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('456b82e3-ed51-4d9d-ada8-6c1f881d50bc', 'To tolerate humiliation, abuse, or offensive remarks quietly without protesting or retaliating', true, '5fbac60e-4c3b-4713-a064-18b32518c2a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('424459b2-1c24-466e-b5ed-0aa0727e8054', 'To eat poisonous food', false, '5fbac60e-4c3b-4713-a064-18b32518c2a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82ecc6e0-ed6d-46d7-84c3-6370184d5cf8', 'To speak very loudly', false, '5fbac60e-4c3b-4713-a064-18b32518c2a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b01fc5c-fed7-4cb5-bd62-edc1cc6d13f3', 'To laugh at someone', false, '5fbac60e-4c3b-4713-a064-18b32518c2a3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dac4bcd5-8432-4225-b4cd-864436037d91', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'Why did Algu''s heart sink when Samjhu Sahu nominated Jumman as the Head Panch?', 'Knowing their severed friendship, Algu dreaded that personal enmity would bias Jumman''s judgment.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2980590b-64ef-42b6-87c8-a78e6a54e52d', 'Algu feared that Jumman would use this judicial opportunity to exact vengeance and rule against him maliciously', true, 'dac4bcd5-8432-4225-b4cd-864436037d91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87bd6f27-4ee8-4767-91c0-c963cd847bcd', 'Algu didn''t like Jumman''s clothes', false, 'dac4bcd5-8432-4225-b4cd-864436037d91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12534663-2b2a-4ab4-aa09-0f037e8b562e', 'Algu wanted to go home early', false, 'dac4bcd5-8432-4225-b4cd-864436037d91');
