INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9c705c9-cb3e-45d4-9eff-96ff5ee7f4a0', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What is the meaning of the word ''Panchayat'' in rural Indian governance?', 'Panchayat is a traditional democratic council of five elders deliberating community disputes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c761219a-c231-4de9-9fb8-4e3c89548b32', 'A traditional council of village elders gathered to resolve disputes and administer local justice and welfare', true, 'f9c705c9-cb3e-45d4-9eff-96ff5ee7f4a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed147fe4-908f-47e9-af5e-1f5cddac9dd8', 'A big market fair', false, 'f9c705c9-cb3e-45d4-9eff-96ff5ee7f4a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3ca1efb-a48c-46ea-b1a1-0269428d6155', 'A wrestling match', false, 'f9c705c9-cb3e-45d4-9eff-96ff5ee7f4a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d791debb-ea00-4dba-93b9-4c9434a705b2', 'A religious festival', false, 'f9c705c9-cb3e-45d4-9eff-96ff5ee7f4a0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ccc3883-a8be-496a-9083-65068af4d32e', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What physiological change occurs in the brain when a sleeping person transitions into the Rapid Eye Movement (REM) dream stage?', 'REM sleep exhibits paradoxical cortical activation and rapid ocular oscillations alongside somatic motor inhibition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0a33532-4dc2-4d1d-b0ef-130814ac6066', 'Brain activity increases, eyes move rapidly behind closed eyelids, while large skeletal muscles remain temporarily paralyzed (atonic)', true, '1ccc3883-a8be-496a-9083-65068af4d32e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25fa0808-31d6-4280-9856-229d6e8f3b9a', 'The brain stops working completely', false, '1ccc3883-a8be-496a-9083-65068af4d32e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbdf73e0-5f95-4554-b70a-9f3be538c22e', 'The body starts walking automatically', false, '1ccc3883-a8be-496a-9083-65068af4d32e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1234ca96-76df-4b30-b2ba-78fe4ddc8e9e', 'The person speaks fluent Greek', false, '1ccc3883-a8be-496a-9083-65068af4d32e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5342c157-861a-47f7-bafb-f50e4d740830', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'What does the expression ''a tight spot'' mean when Algu found himself in trouble after the death of his bullock?', '''In a tight spot'' is an idiomatic metaphor signifying financial or personal dilemma.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81630e7e-43c1-42e6-8a1c-8735bba4d662', 'A difficult, perplexing, or precarious situation', true, '5342c157-861a-47f7-bafb-f50e4d740830');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3941d3ed-0776-498d-83fd-9756442ca0b7', 'A narrow physical hallway', false, '5342c157-861a-47f7-bafb-f50e4d740830');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d77d1bcc-b8bd-4ba8-bc56-6856cddc76cf', 'A small shoe', false, '5342c157-861a-47f7-bafb-f50e4d740830');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12662128-3227-4530-99de-b53a31ffe774', 'A warm blanket', false, '5342c157-861a-47f7-bafb-f50e4d740830');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b7f12c9-3fae-4bf1-94f2-886d318b1b17', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'Who is the legendary author of the original Hindi classic story ''Panch Parmeshwar'', translated into English as ''Fair Play''?', 'Munshi Premchand penned the iconic masterpiece ''पंच परमेश्वर'' (Panch Parmeshwar) portraying rural judicial ethics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e3be4c1-4c59-4fcc-ba97-21fb0214e464', 'Munshi Premchand (Dhanpat Rai Shrivastava)', true, '3b7f12c9-3fae-4bf1-94f2-886d318b1b17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8a2c8b1-14db-456c-b0b6-aa2c2cc3b9a9', 'Rabindranath Tagore', false, '3b7f12c9-3fae-4bf1-94f2-886d318b1b17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33b05a4f-f0fc-40bf-8682-e1317a8d0383', 'R.K. Narayan', false, '3b7f12c9-3fae-4bf1-94f2-886d318b1b17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3da5a85-7825-4b97-9731-0288bbb9a32f', 'Mulk Raj Anand', false, '3b7f12c9-3fae-4bf1-94f2-886d318b1b17');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd6e0c67-a5a6-4080-9568-082db364d69f', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'Why did the villagers cheer ''Victory to the Panchayat! This is justice!'' at the end of both trials?', 'The community celebrated the incorruptibility and divine moral authority of the village judicial institution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4df62f44-6831-4ef4-81f4-bf3f73144e4e', 'Because in both cases, the Panch proved that truth and justice prevail above personal biases, friendships, and vendettas', true, 'dd6e0c67-a5a6-4080-9568-082db364d69f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d64830e-6cdc-4f86-a80e-855dadedade9', 'Because the trial was very short', false, 'dd6e0c67-a5a6-4080-9568-082db364d69f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eeff56da-8554-4686-9689-fd7e80824b77', 'Because they received free sweets', false, 'dd6e0c67-a5a6-4080-9568-082db364d69f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad7d9465-c5e1-4a0c-bc07-f3816618c493', 'Because it started raining', false, 'dd6e0c67-a5a6-4080-9568-082db364d69f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('09816214-8f4f-4549-9f81-6233700ee848', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Medium', 'In ''The Wonder Called Sleep'', why is sleep compared to an enchanting ''haven'' or ''sweet land''?', 'Sleep serves as a biological and emotional oasis restoring physical equilibrium away from conscious distress.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0809e587-e72c-43d6-a198-a166e4a9b6ec', 'Because it provides a tranquil sanctuary where all sorrows, fatigue, worries, and pain are forgotten in peaceful rest', true, '09816214-8f4f-4549-9f81-6233700ee848');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b5830f7-a5de-4b45-9926-33354bbb9deb', 'Because you can buy candy there', false, '09816214-8f4f-4549-9f81-6233700ee848');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2789d0b8-29d9-4ea8-972a-3925e5eb403f', 'Because nobody can wake you up', false, '09816214-8f4f-4549-9f81-6233700ee848');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd7c588e-657f-4ba2-a84e-41ec342ed62b', 'Because it has golden rivers', false, '09816214-8f4f-4549-9f81-6233700ee848');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61955bb5-69e8-4550-a6c7-e9e0dc638f36', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ec2f07d-8d30-470f-a33f-efaef3a441bf', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '61955bb5-69e8-4550-a6c7-e9e0dc638f36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f80e456a-d0c5-4651-9c54-9c9aa932de29', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '61955bb5-69e8-4550-a6c7-e9e0dc638f36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d99e191d-6907-4f11-95db-32de2fb552b1', '(A) is true, but (R) is false.', false, '61955bb5-69e8-4550-a6c7-e9e0dc638f36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eecbf023-6a82-4f61-adb8-a98ebecdda66', '(A) is false, but (R) is true.', false, '61955bb5-69e8-4550-a6c7-e9e0dc638f36');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b328a6f-d612-407d-925c-c662648ea73d', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'Spot the IMPOSTER in the following group of character descriptions from ''Fair Play'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b31ceec1-2d0a-4acb-821d-126ab15dd92e', 'Jumman Shaikh - Nephew of the old aunt', false, '2b328a6f-d612-407d-925c-c662648ea73d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1740a27f-1334-417c-a769-b49577229614', 'Algu Chowdhry - Head Panch in the aunt''s case', false, '2b328a6f-d612-407d-925c-c662648ea73d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f38f0ea6-f0e4-4b8d-8f77-99653f734bf6', 'Samjhu Sahu - Village cart driver who bought the bullock', false, '2b328a6f-d612-407d-925c-c662648ea73d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33ca36a8-a481-40db-85cc-27247ec6d447', 'Kariman - The kind daughter who gave money to the aunt', true, '2b328a6f-d612-407d-925c-c662648ea73d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61c2cd10-8e92-485c-8b7f-21031db3ffeb', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'Analyze the dramatic irony in Samjhu Sahu''s decision to nominate Jumman Shaikh as the Head Panch in his dispute with Algu:', 'Dramatic irony arises when Sahu''s calculated attempt to exploit a personal feud collapses before the sanctity of judicial truth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab44655d-0bfe-48f3-9e65-b6a9523d037c', 'Sahu expected Jumman''s enmity with Algu to guarantee a biased ruling in his favor, but the sacred seat transformed Jumman into an impartial judge who ruled against Sahu', true, '61c2cd10-8e92-485c-8b7f-21031db3ffeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('164ae332-4b3f-44f2-b1ab-e998eb8b0c14', 'Sahu wanted Jumman to lose money', false, '61c2cd10-8e92-485c-8b7f-21031db3ffeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77996a2d-1562-4b01-8ede-8f02ce46e219', 'Sahu knew Jumman was Algu''s brother', false, '61c2cd10-8e92-485c-8b7f-21031db3ffeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8acd923-c443-419e-89ec-b6364063b57f', 'Sahu wanted to pay double money', false, '61c2cd10-8e92-485c-8b7f-21031db3ffeb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f5d04f9d-202a-410e-944a-2c1bb9fd51de', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'Match Column I (Characters / Concepts) with Column II (Key Roles / Quotes):
(a) The Old Aunt     -> (i) ''God lives in the heart of the Panch''
(b) Jumman Shaikh    -> (ii) ''Algu, since you gave verdict against me, I became your enemy''
(c) Samjhu Sahu      -> (iii) Cruelly overworked the bullock to death
(d) Edward Thomas    -> (iv) Poet of ''Lights Out'' describing the deep forest of sleep', 'Aunt = ''God lives in the Panch''; Jumman = ''I became your enemy''; Sahu = overworked bullock; Edward Thomas = ''Lights Out''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2870ec2-f66d-4d91-90db-4928e7adb132', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'f5d04f9d-202a-410e-944a-2c1bb9fd51de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c315da9b-7d40-43c0-b717-a730800c1697', 'a-(ii), b-(i), c-(iii), d-(iv)', false, 'f5d04f9d-202a-410e-944a-2c1bb9fd51de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b962c02-2308-426c-96d5-56a7bb7774c9', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'f5d04f9d-202a-410e-944a-2c1bb9fd51de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8bdd9a9-e8a6-48e8-ba97-8a9590c18372', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'f5d04f9d-202a-410e-944a-2c1bb9fd51de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c4b9a18-8cad-42fe-af0f-70947f6d8043', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'Read the statements regarding ''The Wonder Called Sleep'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b823373-1574-43d7-8b75-6376dbe8d1a2', 'Statements 2 and 3 only', true, '0c4b9a18-8cad-42fe-af0f-70947f6d8043');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89cccc0e-c001-4f26-92d0-4f8f71b161cc', 'Statements 1 and 2 only', false, '0c4b9a18-8cad-42fe-af0f-70947f6d8043');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82640cbb-52ff-424f-ba70-cd5567d83768', 'Statements 1 and 3 only', false, '0c4b9a18-8cad-42fe-af0f-70947f6d8043');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc0b08f2-842d-4e39-95e8-9a1e47b2e9f7', 'All Statements 1, 2, and 3', false, '0c4b9a18-8cad-42fe-af0f-70947f6d8043');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19648ad6-46e0-4591-91ae-e181553cedeb', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'What is the grammatical voice and structure of the sentence: ''A monthly allowance must be paid to the aunt by Jumman.''?', 'The modal passive construction ''must be + V3'' places the patient (monthly allowance) in subject position.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47c49a48-4ded-466b-8c32-af10346157c5', 'Passive Voice (with modal auxiliary ''must be'' + past participle ''paid'')', true, '19648ad6-46e0-4591-91ae-e181553cedeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7afbc64d-a5dc-454a-9e2b-415f6fd6160c', 'Active Voice', false, '19648ad6-46e0-4591-91ae-e181553cedeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4456e671-8676-4194-8d6d-c41448b66dba', 'Indirect Speech', false, '19648ad6-46e0-4591-91ae-e181553cedeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('929d6053-e427-4140-8e5a-756876179bf1', 'Imperative Sentence', false, '19648ad6-46e0-4591-91ae-e181553cedeb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0efc3811-0bc5-46ae-85e9-f97e3a0f2694', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'Identify the figure of speech in Edward Thomas''s lines from ''Lights Out'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2af980d9-3cdb-4575-9aad-b7c0fa0cc192', 'Extended Metaphor (comparing sleep to an all-encompassing dark impenetrable forest)', true, '0efc3811-0bc5-46ae-85e9-f97e3a0f2694');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f7e000e-e364-4295-8364-d3045d09bb33', 'Simile', false, '0efc3811-0bc5-46ae-85e9-f97e3a0f2694');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5ab5c0a-0cce-4506-957e-e12bbbc277aa', 'Onomatopoeia', false, '0efc3811-0bc5-46ae-85e9-f97e3a0f2694');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29131ace-03c0-4d26-9d12-dd1276ac801d', 'Hyperbole', false, '0efc3811-0bc5-46ae-85e9-f97e3a0f2694');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc4cb994-8e71-4e3a-8e8e-b55915dcc677', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'Why does the narrator state: ''The Panch has neither friend nor enemy''?', 'Judicial impartiality requires that judges strip away personal ties when sitting on the seat of truth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31822844-b423-4ab3-adce-5b0c6ceb49db', 'Because judicial office demands complete transcendence of personal ego, prejudice, and private affection to serve absolute cosmic justice', true, 'dc4cb994-8e71-4e3a-8e8e-b55915dcc677');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4afb944-7fd5-4e7e-a171-fd405780c1ea', 'Because Panchs are not allowed to talk to villagers', false, 'dc4cb994-8e71-4e3a-8e8e-b55915dcc677');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc1e2bb5-71d3-4cac-86db-6ed1caf6940e', 'Because Panchs live outside the village', false, 'dc4cb994-8e71-4e3a-8e8e-b55915dcc677');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21e1ab6d-255a-4321-9402-5d3c9e2e46c1', 'Because Panchs have no family', false, 'dc4cb994-8e71-4e3a-8e8e-b55915dcc677');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('740db22c-9e44-4f27-9b50-bf8332a46723', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'What is the meaning of the archaic/formal phrasal verb ''to make up one''s mind'' as used by the aunt before approaching the village elders?', '''To make up one''s mind'' is an English idiom meaning to resolve or decide firmly upon a course of action.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec05ee50-ddcd-4df8-958b-63b147fb7a96', 'To reach a firm and decisive decision', true, '740db22c-9e44-4f27-9b50-bf8332a46723');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cee26d18-df22-476e-9e9f-5d944d02f581', 'To forget everything', false, '740db22c-9e44-4f27-9b50-bf8332a46723');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93041cee-64dd-4ae4-b02d-38faac6ab067', 'To change thoughts randomly', false, '740db22c-9e44-4f27-9b50-bf8332a46723');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e6326cd-d39a-4823-bd68-29b5dad11a3a', 'To clean one''s face', false, '740db22c-9e44-4f27-9b50-bf8332a46723');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31d811f5-d0f2-426c-af72-1cefbe91f6ce', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'How does Premchand use the bullock''s tragic death to critique commercial greed and animal cruelty in rural society?', 'Premchand exposes unbridled commercial exploitation that sacrifices sentient lives for mercenary profit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62f29239-7956-4bb2-9de6-6c778f9a19a9', 'Through Sahu''s ruthless exploitation of the defenseless animal for quick profit without food or rest, illustrating how avarice degrades humanity', true, '31d811f5-d0f2-426c-af72-1cefbe91f6ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e95395fd-24aa-4186-9992-54fb059f92d0', 'By showing that bullocks should not pull carts', false, '31d811f5-d0f2-426c-af72-1cefbe91f6ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91134fe7-6b0f-484a-9861-7b4f2d56c334', 'By arguing that all carts should be banned', false, '31d811f5-d0f2-426c-af72-1cefbe91f6ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3efa57a9-d941-44ad-bc92-010dd530f200', 'By showing that traders are always poor', false, '31d811f5-d0f2-426c-af72-1cefbe91f6ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1dd7dd29-b897-49c4-9fcb-80dd3e68cd33', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'In ''The Wonder Called Sleep'', what happens to our conscious sensory awareness when external stimuli (such as an alarm clock ringing or sunlight hitting eyelids) occur?', 'Subconscious sensory incorporation (e.g. dreaming of a church bell when the alarm rings) occurs before full cortical awakening.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8aaca07-739b-4e76-9761-0ccbcff8acfe', 'Our brain integrates the sensory stimulus into our ongoing dream narrative until neural arousal crosses the waking threshold', true, '1dd7dd29-b897-49c4-9fcb-80dd3e68cd33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa5e4a2c-bca4-4e9d-b70e-fadad097ed4a', 'The brain explodes', false, '1dd7dd29-b897-49c4-9fcb-80dd3e68cd33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fb5ded2-71a6-426c-99ca-a5fec1ecd56b', 'The person forgets who they are', false, '1dd7dd29-b897-49c4-9fcb-80dd3e68cd33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f3855aa-0f01-4d25-92ce-43b5fef830d8', 'Sleep becomes permanent', false, '1dd7dd29-b897-49c4-9fcb-80dd3e68cd33');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38d4f7cb-f2a3-432b-ac1a-991fae855b72', 'Class 6', 'English', 'Chapter 7: Fair Play', 'Hard', 'What timeless ethical synthesis emerges when comparing the judicial triumphs of ''Fair Play'' with modern democratic jurisprudence?', 'Both traditional panchayats and modern constitutional courts derive legitimacy from unwavering impartiality and adherence to natural justice.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b42921db-cd2c-47ef-a2c2-76d048faecf1', 'The Rule of Law and ethical integrity must always stand sovereign above individual power, friendship, caste, or wealth', true, '38d4f7cb-f2a3-432b-ac1a-991fae855b72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('793fb378-3a39-430f-94b2-42d0b0e507e9', 'Friends should always protect each other even when guilty', false, '38d4f7cb-f2a3-432b-ac1a-991fae855b72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb71b0e1-f274-4d24-a846-6380e93e3821', 'Judges should take bribes', false, '38d4f7cb-f2a3-432b-ac1a-991fae855b72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25f52489-21a7-4e98-94fb-24d7ea31bc59', 'Panchayats should only favor rich traders', false, '38d4f7cb-f2a3-432b-ac1a-991fae855b72');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3af7d9f5-9f98-420b-94b9-cc4732b8d082', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'What is the supreme legal and constitutional document of India, establishing the framework of government, fundamental rights, and duties?', 'The Constitution of India is the supreme law of the land, drafted by the Constituent Assembly.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d57a9fc4-0b83-439e-bc76-d1f00f722af9', 'The Constitution of India', true, '3af7d9f5-9f98-420b-94b9-cc4732b8d082');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7b94858-68d5-4533-9d0c-254e2189d249', 'The Indian Penal Code', false, '3af7d9f5-9f98-420b-94b9-cc4732b8d082');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fdafb42-c093-46de-b07e-e5b2d7998465', 'The Magna Carta', false, '3af7d9f5-9f98-420b-94b9-cc4732b8d082');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1f362a1-c1f7-434b-9021-012d0195e315', 'The Parliament Act', false, '3af7d9f5-9f98-420b-94b9-cc4732b8d082');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2ed1024-dab1-4318-815c-4925a44013c0', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'Who is revered as the ''Chief Architect and Father of the Indian Constitution'' and served as the Chairman of the Drafting Committee?', 'Dr. B.R. Ambedkar chaired the Drafting Committee, synthesizing social justice into constitutional jurisprudence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee649803-7abd-4fc7-abb8-b2d5a4223472', 'Dr. B.R. Ambedkar (Bhimrao Ramji Ambedkar)', true, 'b2ed1024-dab1-4318-815c-4925a44013c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7b4c133-8af6-42b7-93e6-773f1afb29af', 'Dr. Rajendra Prasad', false, 'b2ed1024-dab1-4318-815c-4925a44013c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4b902bd-0511-452a-8022-efa5d412f372', 'Jawaharlal Nehru', false, 'b2ed1024-dab1-4318-815c-4925a44013c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf4802e1-4bc4-4ef4-8505-d13761a4469d', 'Sardar Vallabhbhai Patel', false, 'b2ed1024-dab1-4318-815c-4925a44013c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('54b5628a-4a62-46f7-a105-ca728aabd814', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'On which historic date did the Constitution of India come into full effect, celebrated annually as Republic Day across the country?', 'The Constitution came into force on 26 January 1950, commemorated every year as India''s Republic Day.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32e249bc-fd33-4b6b-b758-a936cec7a5f1', '26th January 1950', true, '54b5628a-4a62-46f7-a105-ca728aabd814');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d5fb8d3-f0b2-4d0c-aefc-638279ec5628', '15th August 1947', false, '54b5628a-4a62-46f7-a105-ca728aabd814');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c739eaf8-2b88-4588-b66e-a605a6a041f4', '26th November 1949', false, '54b5628a-4a62-46f7-a105-ca728aabd814');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3185021-7ed2-4d41-9694-e8080d3e2f37', '2nd October 1950', false, '54b5628a-4a62-46f7-a105-ca728aabd814');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('15daf353-fc37-43f5-b497-91d0f8037f5a', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'On which date was the Constitution of India officially ADOPTED by the Constituent Assembly, celebrated annually as ''Constitution Day'' (Samvidhan Divas)?', 'The Constituent Assembly adopted the Constitution on 26 November 1949, designated as Constitution Day.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31a4f3ef-0f40-4720-9646-f7543d5f7982', '26th November 1949', true, '15daf353-fc37-43f5-b497-91d0f8037f5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4ebded8-e4b6-4dc5-8ee2-1a51c400933b', '26th January 1950', false, '15daf353-fc37-43f5-b497-91d0f8037f5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6733a1d-746f-489b-a904-4b9cab0fc402', '15th August 1947', false, '15daf353-fc37-43f5-b497-91d0f8037f5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4faee3a4-1151-4635-9772-1aeb0fd96793', '30th January 1948', false, '15daf353-fc37-43f5-b497-91d0f8037f5a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6259acde-9fb7-4309-a522-8e7dd3a023b8', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'Who was the FIRST President of the Republic of India and also the President of the Constituent Assembly?', 'Dr. Rajendra Prasad presided over the Constituent Assembly and served as India''s first President from 1950 to 1962.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50d7a34f-1a01-4fb1-adbd-671d512afa0b', 'Dr. Rajendra Prasad', true, '6259acde-9fb7-4309-a522-8e7dd3a023b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45b43f65-cf0e-4fc4-b157-09f621a2d934', 'Dr. S. Radhakrishnan', false, '6259acde-9fb7-4309-a522-8e7dd3a023b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e16ea83-da14-4ace-9ede-14ace036230c', 'Dr. Zakir Husain', false, '6259acde-9fb7-4309-a522-8e7dd3a023b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f9042e2-25b5-42c8-b595-7ab93276d00c', 'C. Rajagopalachari', false, '6259acde-9fb7-4309-a522-8e7dd3a023b8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('794aed67-f644-499c-a8f7-c180c578d011', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'Who is the FIRST citizen of India and the Supreme Commander of the Indian Armed Forces?', 'The President is the constitutional Head of State, First Citizen, and Supreme Commander of the Army, Navy, and Air Force.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bb33694-9a79-4ba1-867d-c7833d1ddb17', 'The President of India', true, '794aed67-f644-499c-a8f7-c180c578d011');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('750be358-b07c-4cfb-a5f3-40ffc8a6a15e', 'The Prime Minister', false, '794aed67-f644-499c-a8f7-c180c578d011');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('987b30b0-50a0-43f3-90b3-12a71de538c0', 'The Chief Justice of India', false, '794aed67-f644-499c-a8f7-c180c578d011');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('671041ef-3b13-458c-a253-be0d0a0d14e4', 'The Defence Minister', false, '794aed67-f644-499c-a8f7-c180c578d011');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2271160c-738a-4425-b6c4-d4e0ffd32cd8', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'Who is the real executive Head of Government and leader of the Council of Ministers in India?', 'Under our parliamentary system, the Prime Minister is the de facto head of government leading the executive cabinet.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ac3fb5f-af99-4b5a-bad2-547fe92d1bd0', 'The Prime Minister of India', true, '2271160c-738a-4425-b6c4-d4e0ffd32cd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f474df3-3f2b-4c4d-8aec-770782e1b0cc', 'The President', false, '2271160c-738a-4425-b6c4-d4e0ffd32cd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('627226b2-1b61-4edc-93ad-ef67665d0826', 'The Chief Justice', false, '2271160c-738a-4425-b6c4-d4e0ffd32cd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e61f5d1b-cbcd-43ab-9b62-56662dfb6afa', 'The Speaker of Lok Sabha', false, '2271160c-738a-4425-b6c4-d4e0ffd32cd8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d638c740-4b32-4e12-99bf-d2f1c91d003b', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'What are the two Houses of the Parliament of India (Bicameral Legislature)?', 'The Indian Parliament comprises the President and two Houses: Lok Sabha (Lower House) and Rajya Sabha (Upper House).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f2c2744-a1cd-4c7b-b90f-d4483726555c', 'Lok Sabha (House of the People) and Rajya Sabha (Council of States)', true, 'd638c740-4b32-4e12-99bf-d2f1c91d003b');
