INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ef575583-44fe-4e9f-b911-2e00d71638e6', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'What is the minimum voting age for Indian citizens in general democratic elections under Universal Adult Suffrage?', 'Every Indian citizen aged 18 years or above possesses the constitutional fundamental right to vote without discrimination.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c357fda-7bf2-4c0b-9f0b-c23d24890351', '18 years (lowered from 21 by 61st Constitutional Amendment in 1988)', true, 'ef575583-44fe-4e9f-b911-2e00d71638e6');
