INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6b0bf4f-0676-4b40-a63d-9e875af491eb', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'What is the highest judicial court of appeal in India, situated in New Delhi?', 'The Supreme Court of India is the apex judicial guardian and final interpreter of the Constitution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53564061-6662-4ab2-9de3-5701fc2e84e4', 'Supreme Court of India (headed by the Chief Justice of India)', true, 'd6b0bf4f-0676-4b40-a63d-9e875af491eb');
