INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0079b07f-0e80-49f6-a7ef-5f7ba1959a15', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'What opening introductory statement sets out the guiding ideals, philosophy, and principles of the Constitution of India?', 'The Preamble is the identity card and philosophical soul of the Indian Constitution, declaring India a Sovereign, Socialist, Secular, Democratic Republic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff27c859-59c9-4088-b340-e2147950f65f', 'The Preamble (''WE, THE PEOPLE OF INDIA...'')', true, '0079b07f-0e80-49f6-a7ef-5f7ba1959a15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9019c6af-5c9e-4fae-8229-21adc5d6293c', 'The Index', false, '0079b07f-0e80-49f6-a7ef-5f7ba1959a15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94559d82-aa0c-4d79-8a1d-63fd9c755016', 'The Appendix', false, '0079b07f-0e80-49f6-a7ef-5f7ba1959a15');
