INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4cfd6f38-6c68-4fd8-95c7-235fd039f371', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Easy', 'What is the national motto of India inscribed below the State Emblem, taken from the ancient Mundaka Upanishad?', '''Satyameva Jayate'' (''Truth alone triumphs'') is the national motto inscribed in Devanagari script at the base of the national emblem.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc82028d-4b05-47f7-ba16-8a023847325c', '''Satyameva Jayate'' (Truth Alone Triumphs)', true, '4cfd6f38-6c68-4fd8-95c7-235fd039f371');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c76358ba-03ad-4f2f-bcd1-5b7505bfb774', '''Vande Mataram''', false, '4cfd6f38-6c68-4fd8-95c7-235fd039f371');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('053649b6-d854-479d-b312-dac24006cbc5', '''Jai Hind''', false, '4cfd6f38-6c68-4fd8-95c7-235fd039f371');
