INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc64d976-0747-4a3d-8384-89317c80187d', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'How many Fundamental Rights are currently guaranteed to all Indian citizens under Part III of the Constitution?', 'There are 6 Fundamental Rights (the 7th, Right to Property, was converted to a legal right by the 44th Amendment in 1978).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97b8b561-06c3-4171-a214-47040d46237b', '6 Fundamental Rights (Right to Equality, Right to Freedom, Right against Exploitation, Right to Freedom of Religion, Cultural & Educational Rights, Right to Constitutional Remedies)', true, 'dc64d976-0747-4a3d-8384-89317c80187d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f5cd60b-5913-42af-a2e2-b6cd53f5fab4', '7 Fundamental Rights', false, 'dc64d976-0747-4a3d-8384-89317c80187d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d085def-639b-4656-aca2-07ee74d974e4', '10 Fundamental Rights', false, 'dc64d976-0747-4a3d-8384-89317c80187d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58c8ab6c-ccb8-4b95-a370-5db7953a4611', '5 Fundamental Rights', false, 'dc64d976-0747-4a3d-8384-89317c80187d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a3ca45a-fcee-440f-94b5-aae8b96ecfe9', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'Which Fundamental Right under Article 32 was famously called the ''Heart and Soul of the Constitution'' by Dr. B.R. Ambedkar?', 'Article 32 empowers the Supreme Court to issue prerogative writs to enforce fundamental rights, making rights truly enforceable.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a014e2f9-6707-4a93-a8a7-f56908b5fbd8', 'Right to Constitutional Remedies (allowing citizens to approach Supreme Court via writs like Habeas Corpus, Mandamus)', true, '1a3ca45a-fcee-440f-94b5-aae8b96ecfe9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('036f380b-bde7-408f-bddd-11e0b6ef49b8', 'Right to Equality', false, '1a3ca45a-fcee-440f-94b5-aae8b96ecfe9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccfc31e2-3823-4127-82e1-9edc2beef763', 'Right to Freedom of Speech', false, '1a3ca45a-fcee-440f-94b5-aae8b96ecfe9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0c320a1-8521-4e79-ab11-454fa6632757', 'Right to Property', false, '1a3ca45a-fcee-440f-94b5-aae8b96ecfe9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6ebf8be-fee0-424c-8174-6ae14ecf0b97', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'How many Fundamental Duties are prescribed for Indian citizens under Article 51A (Part IVA) of the Constitution?', 'Originally 10 duties recommended by Swaran Singh Committee were added in 1976; the 11th duty on education was added in 2002.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a280199-d8e7-46d5-b044-448f8ae850fd', '11 Fundamental Duties (added by 42nd & 86th Amendments)', true, 'f6ebf8be-fee0-424c-8174-6ae14ecf0b97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98c82b01-d344-44bc-8c36-caf17638ec82', '10 Fundamental Duties', false, 'f6ebf8be-fee0-424c-8174-6ae14ecf0b97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7415df03-9c04-4eee-aa7e-3ede61e9ab0d', '8 Fundamental Duties', false, 'f6ebf8be-fee0-424c-8174-6ae14ecf0b97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b9969d3-cf72-4bb1-8c2b-6df31a3399d4', '12 Fundamental Duties', false, 'f6ebf8be-fee0-424c-8174-6ae14ecf0b97');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6a43e8ca-38ec-45ce-a645-a5121494a8a8', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'What is the normal term of office for elected Members of the Lok Sabha (Lower House)?', 'Lok Sabha members are elected directly by the people for a standard 5-year term unless dissolved earlier.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f60a857-558f-496c-9474-bdc3c50c326d', '5 years', true, '6a43e8ca-38ec-45ce-a645-a5121494a8a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91f3c600-ce17-4c61-8658-f549c7068b52', '6 years', false, '6a43e8ca-38ec-45ce-a645-a5121494a8a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c36214d8-282f-4412-b1bf-6bd9d5af59d3', '4 years', false, '6a43e8ca-38ec-45ce-a645-a5121494a8a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('643f1257-e68b-49c6-97b0-da134ee24d33', 'Permanent (no term limit)', false, '6a43e8ca-38ec-45ce-a645-a5121494a8a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6da12646-bda2-4b8f-85e4-8ad8e8603af4', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'What is the permanent nature and term of members in the Rajya Sabha (Upper House)?', 'Rajya Sabha is a continuous permanent federal chamber where 1/3rd of members retire biennially after 6-year terms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6402af58-91f0-4f07-963f-bc1a98fcbfd4', 'It is a permanent House never subject to total dissolution; members serve 6-year terms with one-third retiring every 2 years', true, '6da12646-bda2-4b8f-85e4-8ad8e8603af4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d23058b-3540-4cea-8e65-ba681673ada5', 'It dissolves every 5 years', false, '6da12646-bda2-4b8f-85e4-8ad8e8603af4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce162169-2836-4300-a2af-cb82aee8310b', 'Members serve for life', false, '6da12646-bda2-4b8f-85e4-8ad8e8603af4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6e1a809-7307-4073-9437-bff0bc1c7df7', 'It dissolves every year', false, '6da12646-bda2-4b8f-85e4-8ad8e8603af4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f5d3796f-8235-4372-b1de-5c2f28371a96', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'Who is the ex-officio Chairman of the Rajya Sabha in India?', 'Under Article 64, the Vice-President of India serves as the constitutional ex-officio Chairman of the Rajya Sabha.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e554a64a-7714-4620-a11f-52f7dde7428f', 'The Vice-President of India', true, 'f5d3796f-8235-4372-b1de-5c2f28371a96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fcc0b9c-4367-43ce-8311-6bc7054df3ae', 'The Prime Minister', false, 'f5d3796f-8235-4372-b1de-5c2f28371a96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a017f9f2-a9c2-4334-931f-74df6b603771', 'The Speaker of Lok Sabha', false, 'f5d3796f-8235-4372-b1de-5c2f28371a96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a6658d5-31ad-406f-9900-de6e579c7a05', 'The Chief Justice', false, 'f5d3796f-8235-4372-b1de-5c2f28371a96');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76c1d607-c3cd-486e-9502-8430a6d46013', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'What is the Three-Tier system of rural local self-government in India called?', 'Constitutionalized by the 73rd Amendment (1992), Panchayati Raj establishes a 3-tier democratic decentralization system.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eda43131-d597-4113-96e7-1098a8d38cca', 'Panchayati Raj (Gram Panchayat at village level, Panchayat Samiti at block level, Zilla Parishad at district level)', true, '76c1d607-c3cd-486e-9502-8430a6d46013');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b8438b1-79c4-4ae0-be16-e2565d2b543f', 'Municipal Corporation', false, '76c1d607-c3cd-486e-9502-8430a6d46013');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc0675e6-ba0c-4e2a-baa4-4ee3a9f55492', 'District Magistrate Council', false, '76c1d607-c3cd-486e-9502-8430a6d46013');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f5e4477-5ffc-4bb7-993f-9a94e9c6a101', 'Gram Sabha only', false, '76c1d607-c3cd-486e-9502-8430a6d46013');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e723ae5-de2e-4e38-b6d7-ef2a3cd4f54a', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'Which Indian state was the first to establish the Panchayati Raj system on 2nd October 1959 at Nagaur?', 'Prime Minister Jawaharlal Nehru inaugurated democratic Panchayati Raj in Nagaur district, Rajasthan on Gandhi Jayanti in 1959.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7291a36-122b-411c-9797-43e0d6ac6748', 'Rajasthan', true, '3e723ae5-de2e-4e38-b6d7-ef2a3cd4f54a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68966190-17f4-4b2a-8fbf-bb5a191472ac', 'Andhra Pradesh', false, '3e723ae5-de2e-4e38-b6d7-ef2a3cd4f54a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('999462c6-d70e-497a-8738-b4aeffc89dea', 'Uttar Pradesh', false, '3e723ae5-de2e-4e38-b6d7-ef2a3cd4f54a');
