INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('168d260f-0c64-4297-95c1-b135d1dbb0b2', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'What constitutional body conducts free, fair, and impartial democratic elections for Parliament, State Assemblies, President, and Vice-President in India?', 'The Election Commission of India (Article 324) is an autonomous constitutional watchdog conducting national and state elections.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04fbaa88-7159-4aab-b143-7a891c78fa9d', 'Election Commission of India (ECI - Article 324)', true, '168d260f-0c64-4297-95c1-b135d1dbb0b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b8e0748-53ea-4b36-af36-f2c288742e55', 'NITI Aayog', false, '168d260f-0c64-4297-95c1-b135d1dbb0b2');
