INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0aab8d98-1a05-49ba-a2f7-1788486ebb6c', 'Supreme Court', false, '168d260f-0c64-4297-95c1-b135d1dbb0b2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be4713ab-c2a1-4134-979f-25a22df12b7d', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'Who was the FIRST Chief Election Commissioner of Independent India who supervised India''s first historic General Elections in 1951–52?', 'Sukumar Sen organized India''s gigantic first democratic general election of 173 million voters across remote geographies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7d90e8d-bd90-4cf5-b792-89c733c0ee52', 'Sukumar Sen', true, 'be4713ab-c2a1-4134-979f-25a22df12b7d');
