INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b0cdbb1-8fa7-4367-8f68-b247589764f6', 'K.V.K. Sundaram', false, 'be4713ab-c2a1-4134-979f-25a22df12b7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca60f970-e386-4ad8-a1c6-86b4027ab8c6', 'Sunil Arora', false, 'be4713ab-c2a1-4134-979f-25a22df12b7d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b7c962e-1039-41dd-b130-a2df09413933', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'What is the maximum strength of Lok Sabha and Rajya Sabha sanctioned by the Constitution of India?', 'Maximum sanctioned strength: Lok Sabha = 550; Rajya Sabha = 250 (including 12 nominated eminent persons in arts, literature, science, social service).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92503302-4f34-42f7-a16d-c569bd7b3cf4', 'Lok Sabha: 550 members ; Rajya Sabha: 250 members (238 elected + 12 nominated by President)', true, '0b7c962e-1039-41dd-b130-a2df09413933');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e91429d0-de6a-4abb-ab63-93e24178a542', 'Lok Sabha: 500 ; Rajya Sabha: 200', false, '0b7c962e-1039-41dd-b130-a2df09413933');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37dba36c-7830-4629-896d-eb042d3df576', 'Lok Sabha: 600 ; Rajya Sabha: 300', false, '0b7c962e-1039-41dd-b130-a2df09413933');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99fa18ba-01c5-4a5d-ba2c-959c111b1a33', 'Both have 500 members', false, '0b7c962e-1039-41dd-b130-a2df09413933');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b8ea25d-9d4c-47c8-b404-6c2771c09225', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'What does the term ''Secular State'' in the Indian Preamble signify?', 'Indian secularism (Sarva Dharma Sambhava) mandates absolute neutrality, non-discrimination, and equal protection for all faiths.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6b2233c-aadf-43a2-abf1-0072373eda01', 'The State has no official state religion and treats all religions equally with complete freedom of faith, worship, and conscience', true, '3b8ea25d-9d4c-47c8-b404-6c2771c09225');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('268bb1fd-0c46-4973-9673-f789ef6419ac', 'The State bans all religions', false, '3b8ea25d-9d4c-47c8-b404-6c2771c09225');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee2904e8-72af-4e58-88cd-257fd3dfccbe', 'The State only supports one religion', false, '3b8ea25d-9d4c-47c8-b404-6c2771c09225');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4ac8626-d2ba-44d3-b9c4-bc3f98518bc7', 'The State is ruled by priests', false, '3b8ea25d-9d4c-47c8-b404-6c2771c09225');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5f1edb9-2484-415e-b4a4-b055b5710c68', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'Who presides over the joint sittings of both Houses of Parliament in India?', 'Under Article 118(4), the Speaker of the Lok Sabha presides over joint sittings summoned by the President to resolve legislative deadlocks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c28ff554-0689-43c1-8a63-321d9df131cb', 'The Speaker of the Lok Sabha', true, 'a5f1edb9-2484-415e-b4a4-b055b5710c68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56cb27ea-0d96-43ad-a763-37311870bd78', 'The Chairman of Rajya Sabha', false, 'a5f1edb9-2484-415e-b4a4-b055b5710c68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2da86f18-28cb-45bb-94d9-5add4f4ce7c6', 'The President', false, 'a5f1edb9-2484-415e-b4a4-b055b5710c68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('269140d4-ee9b-4663-91b2-03182ef2e06b', 'The Prime Minister', false, 'a5f1edb9-2484-415e-b4a4-b055b5710c68');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7119fd1-bfe5-405f-9871-6bb9cab3f0a8', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'What is the retirement age of a Judge of the Supreme Court of India and a Judge of a High Court respectively?', 'Constitutionally, Supreme Court judges hold office until 65 years of age, whereas High Court judges retire at 62 years.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08fcd0aa-e5f4-447f-9558-7b2e3fdc1fc4', 'Supreme Court Judge: 65 years ; High Court Judge: 62 years', true, 'd7119fd1-bfe5-405f-9871-6bb9cab3f0a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb2f8119-bf91-47b8-aa8b-18e1757a539f', 'Both 60 years', false, 'd7119fd1-bfe5-405f-9871-6bb9cab3f0a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48570076-41b2-43ff-b5d8-a960fa25d50b', 'Both 65 years', false, 'd7119fd1-bfe5-405f-9871-6bb9cab3f0a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffed0672-6f3b-4c5c-ae68-9596f2b9fff8', 'Supreme Court: 70 years ; High Court: 65 years', false, 'd7119fd1-bfe5-405f-9871-6bb9cab3f0a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7152236d-b0ed-4235-8f55-17d5be3f3787', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'What is the policy think-tank of the Government of India that replaced the Planning Commission in 2015, chaired by the Prime Minister?', 'Established on 1 January 2015, NITI Aayog fosters cooperative federalism and strategic policy advisory.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91f19065-917a-433d-98e2-ba5dd85c20b4', 'NITI Aayog (National Institution for Transforming India)', true, '7152236d-b0ed-4235-8f55-17d5be3f3787');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6bbb370-82de-4bf9-be5f-673b482ba116', 'Finance Commission', false, '7152236d-b0ed-4235-8f55-17d5be3f3787');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2930b0e8-bf3e-4ff9-9ad2-cb8a29dea5e3', 'National Development Council', false, '7152236d-b0ed-4235-8f55-17d5be3f3787');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd3fe99a-2378-47bf-bd85-e42dbf4e317d', 'RBI', false, '7152236d-b0ed-4235-8f55-17d5be3f3787');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d1a0abbd-f96c-44a0-b82b-ca44e7c6d625', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Medium', 'How long did the Constituent Assembly take to draft and complete the Constitution of India?', 'The Constituent Assembly held 11 plenary sessions spanning 165 days over a total period of 2 years, 11 months, and 18 days.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87c3f4a7-767d-4b05-b0a0-11c0e4947d67', '2 years, 11 months, and 18 days', true, 'd1a0abbd-f96c-44a0-b82b-ca44e7c6d625');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('377745d6-5cf2-4d00-9e0c-c476dda44582', '1 year and 6 months', false, 'd1a0abbd-f96c-44a0-b82b-ca44e7c6d625');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('297e6b6e-dd07-4454-a22b-fb29df672a34', '5 full years', false, 'd1a0abbd-f96c-44a0-b82b-ca44e7c6d625');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3841f0e8-76c2-4327-8b64-18f6929f14ba', '3 years exactly', false, 'd1a0abbd-f96c-44a0-b82b-ca44e7c6d625');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f34df426-e0da-4fc6-b3f4-312caed0cafb', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f176d86-7fbf-4313-a117-7d48c4ae4d4d', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'f34df426-e0da-4fc6-b3f4-312caed0cafb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2544ffe2-b381-40ce-a3b5-67c683b4a7d2', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'f34df426-e0da-4fc6-b3f4-312caed0cafb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('409ad768-f79a-4e92-ad5b-4c20990637f2', '(A) is true, but (R) is false.', false, 'f34df426-e0da-4fc6-b3f4-312caed0cafb');
