INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4ea1af6-b520-4d20-a395-a4413f9fe88e', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'Spot the IMPOSTER in the following group of Fundamental Rights paired with their constitutional articles:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7d1849e-e835-4a0a-b5e1-e4687f10f8a7', 'Right to Equality - Articles 14-18', false, 'd4ea1af6-b520-4d20-a395-a4413f9fe88e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d084b129-829e-41b2-9896-4155bcf55d3c', 'Right to Freedom - Articles 19-22', false, 'd4ea1af6-b520-4d20-a395-a4413f9fe88e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('937356dd-6710-4e68-b9ff-b0b6156b049e', 'Right against Exploitation - Articles 23-24', false, 'd4ea1af6-b520-4d20-a395-a4413f9fe88e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f884f44-4512-4466-8ab9-626af8edff4d', 'Right to Education - Article 51A', true, 'd4ea1af6-b520-4d20-a395-a4413f9fe88e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8401ecc1-dcf1-4c3d-8267-d03ce03a05e7', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'What historic landmark judgment by a 13-judge constitutional bench of the Supreme Court in 1973 established that Parliament cannot alter the ''Basic Structure'' of the Indian Constitution?', 'The Kesavananda Bharati verdict ruled that while Article 368 empowers Parliament to amend the Constitution, it cannot destroy its essential basic structure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcd43104-00e1-4a4a-a5a0-72c8a8c8b250', 'Kesavananda Bharati v. State of Kerala (1973)', true, '8401ecc1-dcf1-4c3d-8267-d03ce03a05e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fee92d1-476e-4512-8157-92113e8799f1', 'Golaknath Case (1967)', false, '8401ecc1-dcf1-4c3d-8267-d03ce03a05e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d80d599f-f5c3-407c-ab9c-977b7d4c19b5', 'Minerva Mills Case (1980)', false, '8401ecc1-dcf1-4c3d-8267-d03ce03a05e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e16c6727-08e0-4c04-b02d-f0ddc1b33414', 'Maneka Gandhi Case (1978)', false, '8401ecc1-dcf1-4c3d-8267-d03ce03a05e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('805f486f-ee7d-41cd-881c-e0d116b05622', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'Match Column I (Constitutional Bodies & Articles) with Column II (Functions):
(a) Article 324  -> (i) Autonomous Election Commission of India
(b) Article 280  -> (ii) Finance Commission for tax devolution
(c) Article 148  -> (iii) Comptroller and Auditor General (CAG) of India
(d) Article 76   -> (iv) Attorney General for India (highest law officer)', '324 = ECI; 280 = Finance Commission; 148 = CAG; 76 = Attorney General.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b13f1de3-432c-4b54-8cc6-c63cb4fc43ab', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '805f486f-ee7d-41cd-881c-e0d116b05622');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('015cb852-30f2-41a0-b919-fe82c6c018a4', 'a-(ii), b-(i), c-(iii), d-(iv)', false, '805f486f-ee7d-41cd-881c-e0d116b05622');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1d681f2-49a6-4abc-8209-b116327b17eb', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '805f486f-ee7d-41cd-881c-e0d116b05622');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5992ded-0323-43c4-930e-db76546d6660', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '805f486f-ee7d-41cd-881c-e0d116b05622');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6cd456a1-747a-4a8d-94ae-75f8737cd91c', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'Read the statements regarding the Preamble of the Indian Constitution:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d92f3e07-695d-4b16-abe0-f95f62d880b9', 'Statements 1 and 3 only', true, '6cd456a1-747a-4a8d-94ae-75f8737cd91c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0627b28e-897e-4f72-89a7-13916f2ae443', 'Statements 1 and 2 only', false, '6cd456a1-747a-4a8d-94ae-75f8737cd91c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d835da28-2c81-432c-8e0b-83d845c033ff', 'Statements 2 and 3 only', false, '6cd456a1-747a-4a8d-94ae-75f8737cd91c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7d13f73-323a-4e4c-b30a-dfbdbcc9dff6', 'All Statements 1, 2, and 3', false, '6cd456a1-747a-4a8d-94ae-75f8737cd91c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96973393-e23a-4b10-997e-e187bc3fa88f', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'Which Constitutional Amendment Act lowered the voting age for Lok Sabha and Legislative Assembly elections from 21 years to 18 years?', 'The 61st Amendment amended Article 326, empowering 18-year-old Indian youth with democratic voting rights.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6297ba9-6f9d-4101-9b2c-94e9db1b81f4', '61st Constitutional Amendment Act (1988)', true, '96973393-e23a-4b10-997e-e187bc3fa88f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('810ad386-1084-470d-831a-e82cfcbb4c0c', '42nd Constitutional Amendment Act (1976)', false, '96973393-e23a-4b10-997e-e187bc3fa88f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c43981ac-89ba-4b9b-9e01-c882c1ebb9a7', '44th Constitutional Amendment Act (1978)', false, '96973393-e23a-4b10-997e-e187bc3fa88f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('363e2e39-c1d4-48d4-afbe-8c07cb254da2', '73rd Constitutional Amendment Act (1992)', false, '96973393-e23a-4b10-997e-e187bc3fa88f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c042d3e9-fa78-492e-bc8f-42cfdb1c029d', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'What are the Three Types of Emergencies that the President of India can proclaim under Part XVIII of the Constitution?', 'Articles 352 (National/War), 356 (Constitutional machinery failure in states), and 360 (Financial threat) constitute emergency provisions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0771f8bc-084f-4e1a-93f0-defc85b3bea8', 'National Emergency (Article 352), State Emergency / President''s Rule (Article 356), and Financial Emergency (Article 360)', true, 'c042d3e9-fa78-492e-bc8f-42cfdb1c029d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('224bb9b1-e893-4dfd-99fd-6dcd82ceed77', 'War Emergency, Climate Emergency, Health Emergency', false, 'c042d3e9-fa78-492e-bc8f-42cfdb1c029d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a2a77af-37bf-4123-8d42-114936ff05cf', 'Police Emergency, Judicial Emergency, Army Emergency', false, 'c042d3e9-fa78-492e-bc8f-42cfdb1c029d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3625f7f-bcf3-465b-b3ba-7f0ac6c57fd2', 'Only one type of emergency exists', false, 'c042d3e9-fa78-492e-bc8f-42cfdb1c029d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93723fb0-c4f8-4a80-92ab-af74b78a7d09', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'Which of the following constitutional features of the Indian Constitution was borrowed from the Constitution of the United Kingdom (British Parliamentary Model)?', 'The Westminster parliamentary model, bicameralism, single citizenship, and legislative procedure were derived from the UK.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('717dfc93-5127-46a7-bb23-7c6056788ebe', 'Parliamentary form of government, Rule of Law, Single Citizenship, and Cabinet System', true, '93723fb0-c4f8-4a80-92ab-af74b78a7d09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e963a727-a950-41a9-8005-31580b791293', 'Fundamental Rights (USA)', false, '93723fb0-c4f8-4a80-92ab-af74b78a7d09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d975c3ce-8c56-4213-915f-215846bb5996', 'Directive Principles of State Policy (Ireland)', false, '93723fb0-c4f8-4a80-92ab-af74b78a7d09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ec88f5b-2784-4f9c-b025-295d993e10b3', 'Concurrent List (Australia)', false, '93723fb0-c4f8-4a80-92ab-af74b78a7d09');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac62f389-7936-44a0-a5f3-e46066bf890f', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'What is the constitutional mechanism known as ''Gram Sabha'' under the 73rd Amendment Act?', 'Gram Sabha comprises every registered voter in the village panchayat area, deliberating village plans and budget expenditures.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8df6fda-05ad-4d37-bb75-b75606767e44', 'A village assembly consisting of ALL registered adult voters of a village, serving as the foundational grassroots direct democracy organ', true, 'ac62f389-7936-44a0-a5f3-e46066bf890f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5261cd2d-00b3-44d4-be4b-8362885cec90', 'A council of village priests only', false, 'ac62f389-7936-44a0-a5f3-e46066bf890f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37a7e2ec-2210-496b-b35e-557cfdc6e240', 'A group of rich landowners', false, 'ac62f389-7936-44a0-a5f3-e46066bf890f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('977e1b04-ed70-4611-8974-c845abf614ee', 'The state legislative assembly', false, 'ac62f389-7936-44a0-a5f3-e46066bf890f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('29f8912c-44fe-461d-a592-8c43559097ff', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'Who was the famous master artist of Shantiniketan who, along with his students (including Beohar Rammanohar Sinha), painstakingly illuminated and hand-decorated the original calligraphy pages of the Constitution of India?', 'Nandalal Bose decorated the original manuscript with classical Indian motifs, while Prem Behari Narain Raizada wrote the elegant calligraphy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da9450c8-aa95-480a-b4e8-249c06d57d49', 'Nandalal Bose', true, '29f8912c-44fe-461d-a592-8c43559097ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6672a0f-5769-4af0-b979-9edf1a381def', 'Raja Ravi Varma', false, '29f8912c-44fe-461d-a592-8c43559097ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f08ea03-860c-4c47-b0c2-d02415615851', 'Abanindranath Tagore', false, '29f8912c-44fe-461d-a592-8c43559097ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3864a711-47dd-4646-b5f0-1b03f3b53659', 'M.F. Husain', false, '29f8912c-44fe-461d-a592-8c43559097ff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20e6d86a-4525-4ad5-b00f-42a6efbe72ae', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'What is the primary function of the ''Directive Principles of State Policy'' (DPSP) contained in Part IV (Articles 36–51) of the Indian Constitution?', 'Inspired by Ireland, DPSPs guide governmental legislation towards achieving social and economic democracy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da2ff3b6-caa5-423d-b372-84b642c570dc', 'They are non-justiciable socio-economic policy guidelines and goals for the State to establish a Welfare State (Kalyankari Rajya) based on social justice', true, '20e6d86a-4525-4ad5-b00f-42a6efbe72ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0565afe3-447e-4d23-854e-14a021eff566', 'They are criminal punishment laws', false, '20e6d86a-4525-4ad5-b00f-42a6efbe72ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54cf9480-9f63-4968-b67e-ac4909099815', 'They are rules for the Indian Army', false, '20e6d86a-4525-4ad5-b00f-42a6efbe72ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88773f16-7bf4-4984-a74a-cf2f87e0329c', 'They are tax collection rules', false, '20e6d86a-4525-4ad5-b00f-42a6efbe72ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c93dbe69-b8cf-4239-9389-8749e664bc2f', 'Class 6', 'GK', 'Chapter 7: Indian Polity, Constitution & Governance', 'Hard', 'How is the President of India elected according to the Constitution?', 'Article 54 prescribes an Electoral College comprising elected MPs and MLAs through proportional representation by single transferable vote.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c590ce4-6a8c-457b-aea2-4c3c442754b7', 'Indirectly by an Electoral College consisting of elected members of both Houses of Parliament AND elected members of State Legislative Assemblies (using Single Transferable Vote)', true, 'c93dbe69-b8cf-4239-9389-8749e664bc2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f09cf74a-e3f8-4282-b1b9-33090730ba1a', 'Directly by all voting citizens of India', false, 'c93dbe69-b8cf-4239-9389-8749e664bc2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7431514-e698-40c9-9fb8-433366de4fb7', 'Nominated solely by the Prime Minister', false, 'c93dbe69-b8cf-4239-9389-8749e664bc2f');
