INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('24b35d5a-339b-41be-93ca-79c6e010d505', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Easy', 'What are the THREE parallel mountain ranges of the Himalayas from north to south?', 'From north to south: 1. Himadri (Great Himalayas), 2. Himachal (Lesser Himalayas), 3. Shiwalik (Outer Himalayas).', NOW()) ON CONFLICT DO NOTHING;
