INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b556e8dc-28c7-4bb1-8314-0ee503f5d78c', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'What is the Standard Meridian of India, chosen to determine the Indian Standard Time (IST)?', 'The 82°30'' E meridian is the standard time meridian for India, exactly 5 hours and 30 minutes ahead of Greenwich Mean Time (UTC+05:30).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af41bac2-66ea-4a2f-a4aa-59de355b7176', '82°30'' E longitude (passing through Mirzapur / Prayagraj in Uttar Pradesh)', true, 'b556e8dc-28c7-4bb1-8314-0ee503f5d78c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f81ea6be-b1c0-48f3-bff8-44dad2d848c2', '80°00'' E', false, 'b556e8dc-28c7-4bb1-8314-0ee503f5d78c');
