INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d7d7362-9234-41ca-b017-be0a70117bb8', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'Why is there a time difference of nearly TWO HOURS in local sunrise time between Arunachal Pradesh in the east and Gujarat in the west?', 'Diurnal rotation: 360° in 24 hours = 1° in 4 minutes. A longitudinal span of ~29° equates to roughly 116 minutes (~2 hours) local solar lag.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f8196b1-aef4-44af-8a68-f820be295f7f', 'India spans a longitudinal width of nearly 30° (68°7'' E to 97°25'' E); since Earth rotates 1° of longitude in 4 minutes, 30° × 4 min = 120 minutes (2 hours)', true, '1d7d7362-9234-41ca-b017-be0a70117bb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('910d28e8-e969-4de0-9b53-0d47f1ba94c0', 'Because clocks run faster in Gujarat', false, '1d7d7362-9234-41ca-b017-be0a70117bb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47a90890-aad3-42c5-aa37-317f579ef21e', 'Because the Sun rises in the west in India', false, '1d7d7362-9234-41ca-b017-be0a70117bb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22888548-2eb7-45c9-97eb-158a21882c04', 'Because mountains block the Sun', false, '1d7d7362-9234-41ca-b017-be0a70117bb8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66bbde3f-21de-4e56-a2eb-2de7481710c0', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'How many countries share land borders with India?', 'India shares 15,106 km of land borders with 7 neighboring nations: Bangladesh, China, Pakistan, Nepal, Myanmar, Bhutan, and Afghanistan.', NOW()) ON CONFLICT DO NOTHING;
