INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82253eb9-fa39-405d-807e-269f22893b4b', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'What is the world''s LARGEST river delta, formed by the confluence of the Ganga and Brahmaputra rivers emptying into the Bay of Bengal?', 'The triangular Sundarbans mangrove delta covers ~100,000 km², named after the abundant Sundari mangrove trees (Heritiera fomes).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8abd4e7f-e1db-4509-a264-078aba524e5c', 'Sundarbans Delta (Ganga-Brahmaputra Delta)', true, '82253eb9-fa39-405d-807e-269f22893b4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3a9b9d1-c692-40b8-b004-76e16301ec6d', 'Nile Delta', false, '82253eb9-fa39-405d-807e-269f22893b4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83fbe1af-d972-42ff-ab3f-6ec47c1e23eb', 'Mississippi Delta', false, '82253eb9-fa39-405d-807e-269f22893b4b');
