INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0e569b33-748d-4ce1-9c95-3bd8ae3dd023', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'Which triangular relief feature of India is an ancient elevated tableland composed of old crystalline, igneous, and metamorphic rocks?', 'The Peninsular Plateau is the oldest and most stable geological landmass of India, forming part of ancient Gondwanaland.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c304a9f4-01b3-417b-b4d7-968655149357', 'The Peninsular Plateau', true, '0e569b33-748d-4ce1-9c95-3bd8ae3dd023');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6f37f6c-92ad-4837-9256-005de3ace332', 'The Northern Plains', false, '0e569b33-748d-4ce1-9c95-3bd8ae3dd023');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62eefa04-7ab7-4366-8263-28588862356c', 'The Coastal Plains', false, '0e569b33-748d-4ce1-9c95-3bd8ae3dd023');
