INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03eb45e5-a153-4178-9662-80b8f798234d', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'What are the continuous elevated mountain ranges bordering the western edge of the Deccan Plateau called?', 'The Western Ghats (Sahyadris) form an unbroken high escarpment along the western coast with passes like Thal, Bhor, and Pal Ghats.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af91d5fc-981d-47c6-a920-3c2dfe760c04', 'Western Ghats (or Sahyadris)', true, '03eb45e5-a153-4178-9662-80b8f798234d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01c3f38c-3b7b-4376-9e20-8d3223c2abbf', 'Eastern Ghats', false, '03eb45e5-a153-4178-9662-80b8f798234d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db6d0f05-eca8-4c5b-aaea-a9fe7e22c5c1', 'Aravalli Range', false, '03eb45e5-a153-4178-9662-80b8f798234d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80affbc0-5129-4e27-8d24-84793316c62d', 'Vindhya Range', false, '03eb45e5-a153-4178-9662-80b8f798234d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca61ab61-c3c6-4114-8b23-56b0ea3a8bb8', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'How do the Eastern Ghats differ from the Western Ghats?', 'East-flowing peninsular rivers cut wide valleys through the Eastern Ghats, making them discontinuous and lower in average altitude (600m vs 1200m).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b7e901b-5a08-460f-be72-29787591c9bd', 'The Eastern Ghats are discontinuous, lower in height, and dissected by east-flowing rivers (Mahanadi, Godavari, Krishna, Kaveri), whereas the Western Ghats are continuous and higher', true, 'ca61ab61-c3c6-4114-8b23-56b0ea3a8bb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85fb1bbd-8148-45b9-810f-cd9d99f2d6ec', 'The Eastern Ghats have snow glaciers', false, 'ca61ab61-c3c6-4114-8b23-56b0ea3a8bb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddebf3b1-4daa-43b9-92f5-882f57ba86ba', 'The Eastern Ghats are in the Arabian Sea', false, 'ca61ab61-c3c6-4114-8b23-56b0ea3a8bb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6c6570a-09a2-4602-a2ba-ef4d1d1215fe', 'There is no difference', false, 'ca61ab61-c3c6-4114-8b23-56b0ea3a8bb8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8dad7a6-5a90-4274-926c-36b4b91d7ba5', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'Which are the only two major west-flowing peninsular rivers in India that drain into the Arabian Sea through rift valleys without forming deltas?', 'Narmada and Tapi flow westward in structural fault rift valleys between the Vindhya and Satpura ranges, forming estuaries instead of deltas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cb73630-d4d9-4b1e-9759-ff5372665340', 'Narmada and Tapi (Tapti)', true, 'c8dad7a6-5a90-4274-926c-36b4b91d7ba5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14a07eab-c1c1-4853-9f20-76fa2e2883ff', 'Ganga and Yamuna', false, 'c8dad7a6-5a90-4274-926c-36b4b91d7ba5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('457a1ddd-2f21-4a00-8b10-d3eb8105e736', 'Godavari and Krishna', false, 'c8dad7a6-5a90-4274-926c-36b4b91d7ba5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43818e54-3e8b-4cd7-ba1e-aa9f8f4b8da5', 'Mahanadi and Kaveri', false, 'c8dad7a6-5a90-4274-926c-36b4b91d7ba5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9849593e-11ed-4070-be79-8da25f2f21e8', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'Which major peninsular rivers flow eastward and drain into the Bay of Bengal, forming large fertile deltas at their mouths?', 'Godavari (Dakshin Ganga), Krishna, Kaveri, and Mahanadi flow down the eastward regional plateau gradient, depositing extensive deltas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9ee4bea-5115-4b87-84c5-3ca8c0b56e85', 'Mahanadi, Godavari, Krishna, and Kaveri', true, '9849593e-11ed-4070-be79-8da25f2f21e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4c22371-4154-4449-990c-feb4182c8d40', 'Narmada and Tapi', false, '9849593e-11ed-4070-be79-8da25f2f21e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('216460b7-7107-4629-ab5c-dd2eb6406ee3', 'Indus and Jhelum', false, '9849593e-11ed-4070-be79-8da25f2f21e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38e6eb10-89cb-4744-ad8b-6f0e02c65671', 'Luni and Sabarmati', false, '9849593e-11ed-4070-be79-8da25f2f21e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c71d4759-d963-4c82-98df-2243db28b91b', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'How do the Western Coastal Plains compare with the Eastern Coastal Plains of India?', 'Western coastal strip (Konkan, Malabar) is narrow (~50 km); Eastern coastal strip (Northern Circars, Coromandel) is wide (~100–120 km) with deltas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81b94a1b-f9a5-4032-b943-d87de7c06bc2', 'Western Coastal Plains are very narrow between the Western Ghats and Arabian Sea, while Eastern Coastal Plains are much broader and wider along the Bay of Bengal', true, 'c71d4759-d963-4c82-98df-2243db28b91b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e980f15-9526-4ffb-8a28-c3bdcfa4c56d', 'Western Coastal Plains are covered in snow', false, 'c71d4759-d963-4c82-98df-2243db28b91b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('807ac982-97b7-4ee4-8d5a-58ed1f3fb68c', 'Eastern Coastal Plains have no rivers', false, 'c71d4759-d963-4c82-98df-2243db28b91b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4f8891d-f556-4659-96df-577d51547204', 'Both are identical in width', false, 'c71d4759-d963-4c82-98df-2243db28b91b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('548c768e-9878-45a6-8fee-72dce763a57c', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'What are ''Corals'' and how did coral islands like Lakshadweep form?', 'Scleractinian anthozoan polyps secrete calcium carbonate exoskeletons; generational biogenic reef accumulation builds atolls.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbc20c40-0bb9-403e-a797-d992c0ef6e08', 'Corals are tiny marine animals (Polyps); when polyps die, their hard calcium carbonate skeletons accumulate over millennia to form coral reefs and islands', true, '548c768e-9878-45a6-8fee-72dce763a57c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a1fd5bb-6994-4668-bae5-3f92c9893a55', 'They are volcanic stones thrown by volcanoes', false, '548c768e-9878-45a6-8fee-72dce763a57c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fd1359e-9b57-49f5-a040-587c90911be4', 'They are plants that turn into wood', false, '548c768e-9878-45a6-8fee-72dce763a57c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be90866f-28a7-40fb-92a5-bf56966d9b50', 'They are icebergs from the South Pole', false, '548c768e-9878-45a6-8fee-72dce763a57c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f0fef3d9-09ee-4ac4-a0d3-f02e119633c7', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'What is the southernmost point of the Indian Union territory (located in Great Nicobar), which was submerged during the devastating 2004 Indian Ocean tsunami?', 'Indira Point on Great Nicobar island at 6°45'' N is the southernmost geographic point of the sovereign Indian Republic.', NOW()) ON CONFLICT DO NOTHING;
