INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f88ad7ee-bff8-494e-bbbd-ced80c8a62c8', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'What is the southernmost tip of the MAINLAND of India located in Tamil Nadu where three water bodies (Arabian Sea, Bay of Bengal, Indian Ocean) meet?', 'Cape Comorin (Kanyakumari) at 8°4'' N is the southern apex of mainland peninsular India.', NOW()) ON CONFLICT DO NOTHING;
