INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16cd1708-693c-4671-a71e-fda906c143e8', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'Which mountain range is the oldest fold mountain system in India and among the oldest in the world, running from Gujarat to Delhi across Rajasthan?', 'The Aravalli Range is a Precambrian fold mountain system severely eroded into relict hills (highest peak Guru Shikhar at 1,722 m).', NOW()) ON CONFLICT DO NOTHING;
