INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53d9caf8-4833-4c2b-8e98-3a1496f5c947', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Medium', 'What are the states of India known as the ''Seven Sisters'' of the North-Eastern region?', 'The 7 contiguous North-Eastern states: Arunachal Pradesh, Assam, Meghalaya, Nagaland, Manipur, Mizoram, and Tripura.', NOW()) ON CONFLICT DO NOTHING;
