INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e8fd0a2-fac6-45dd-8042-3a4ee4a0aa8c', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'A geography student charts the latitudinal and longitudinal coordinates of the Indian mainland. What are the exact mathematical coordinates?', 'Mainland limits: Latitudes 8°4'' N (Kanyakumari) to 37°6'' N (Indira Col); Longitudes 68°7'' E (Gujarat) to 97°25'' E (Arunachal).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b0fc11b-1775-48bd-9fc0-27223a5979c9', 'Latitudes: 8°4'' N to 37°6'' N ; Longitudes: 68°7'' E to 97°25'' E', true, '6e8fd0a2-fac6-45dd-8042-3a4ee4a0aa8c');
