INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('362a1a04-30c1-47d2-9105-201ef92be556', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'Match Column I (Physical Divisions) with Column II (Dominant Characteristics):
(a) Himadri           -> (i) Northernmost highest Himalayan crest with perennial snow
(b) Northern Plains   -> (ii) Fertile alluvial basin formed by Indus, Ganga, Brahmaputra
(c) Thar Desert       -> (iii) Arid sandy tract with shifting barchan dunes
(d) Lakshadweep       -> (iv) Coral atoll island archipelago in the Arabian Sea', 'Himadri = highest snow peaks; Northern Plains = alluvium; Thar = sandy dunes; Lakshadweep = coral atolls.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5017df97-f16e-42c8-baec-a96813fc2b53', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '362a1a04-30c1-47d2-9105-201ef92be556');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62396c2b-62a8-4f24-9129-7ce697f45c5b', 'a-(ii), b-(i), c-(iii), d-(iv)', false, '362a1a04-30c1-47d2-9105-201ef92be556');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27dff486-6d25-46ac-a23f-c87f4a2c133f', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '362a1a04-30c1-47d2-9105-201ef92be556');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b03dd31b-0c0b-489c-9ce5-142f93888fed', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '362a1a04-30c1-47d2-9105-201ef92be556');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('40c2fa9b-514e-4d90-ace9-cdce03b7b685', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a35ff2fd-4ff7-4423-9d44-99b07b5da17e', 'Statements 1 and 2 only', true, '40c2fa9b-514e-4d90-ace9-cdce03b7b685');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d48329c-14e6-4c67-ad68-5da686120f2a', 'Statements 2 and 3 only', false, '40c2fa9b-514e-4d90-ace9-cdce03b7b685');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19bf4808-e7cc-4c0a-adc8-7975aa998ff1', 'Statements 1 and 3 only', false, '40c2fa9b-514e-4d90-ace9-cdce03b7b685');
