INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a75c5502-7657-4f95-8f0f-9a3204833557', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'Which of the following coastal sub-regions are located along the WESTERN coast and EASTERN coast of India respectively?', 'West coast: Konkan (north) and Malabar (south); East coast: Northern Circar (north) and Coromandel (south).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4a064e6-742e-42de-87f1-9733bcd81210', 'Western Coast: Konkan & Malabar Coast ; Eastern Coast: Northern Circars & Coromandel Coast', true, 'a75c5502-7657-4f95-8f0f-9a3204833557');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8c30dab-55dc-4941-9b38-f39135805d76', 'Western Coast: Coromandel ; Eastern Coast: Konkan', false, 'a75c5502-7657-4f95-8f0f-9a3204833557');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bb78b06-268d-4b15-bc3c-549d6054f95e', 'Western Coast: Northern Circars ; Eastern Coast: Malabar', false, 'a75c5502-7657-4f95-8f0f-9a3204833557');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('963f2dc5-e215-48c7-9645-323842ac0099', 'Both are called Malabar', false, 'a75c5502-7657-4f95-8f0f-9a3204833557');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32b8c609-708a-4dd0-b51e-55fc02552525', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'Why does the Sundarbans Delta feature extensive amphibious Mangrove forests adapted to coastal saline waters?', 'Halophytic adaptations: viviparous germination, salt-excreting glands, and negative geotropic pneumatophores flourish in intertidal muds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0be00656-9fb3-4731-aa42-d226fd8f6b1a', 'Tidal sea surges mix with freshwater river floods; mangrove species (Sundari) develop specialized breathing roots (pneumatophores) and stilt roots to survive in anaerobic saline mudflats', true, '32b8c609-708a-4dd0-b51e-55fc02552525');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb2e3ce2-e5ad-43cd-afd1-57ee97528cfb', 'Because mangroves only grow in snow', false, '32b8c609-708a-4dd0-b51e-55fc02552525');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fb479f0-72e7-498e-9d6d-b757bd9acdee', 'Because salt water kills all other trees except plastic trees', false, '32b8c609-708a-4dd0-b51e-55fc02552525');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('433c8e2f-98f6-4153-8bad-c97e85fa2075', 'Because it never rains there', false, '32b8c609-708a-4dd0-b51e-55fc02552525');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b85ab91-554d-45e7-ac92-1fc3b2f5c813', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'What is the highest mountain peak situated entirely within the undisputed sovereign territory of India?', 'Kangchenjunga (8,586 m) in Sikkim on the India-Nepal border is the highest peak in India (and 3rd highest in the world).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c061c249-f9d7-471f-9d75-271dd6e79220', 'Kangchenjunga (8,586 meters, Sikkim)', true, '6b85ab91-554d-45e7-ac92-1fc3b2f5c813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0286c2b-6acb-4417-9cde-2133c370e6df', 'Nanda Devi (7,816 m)', false, '6b85ab91-554d-45e7-ac92-1fc3b2f5c813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dd98ae0-74b5-40da-a76b-29167e4fe10d', 'Kamet', false, '6b85ab91-554d-45e7-ac92-1fc3b2f5c813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31a94e98-e167-4817-b752-0002794ee98f', 'Anamudi', false, '6b85ab91-554d-45e7-ac92-1fc3b2f5c813');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d757b6f-620e-475a-a944-289f85b6e24a', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'What is the highest peak in the Western Ghats and in the entire Peninsular South India (located in Kerala)?', 'Anamudi (''Elephant''s Forehead'') stands at 2,695 m in Eravikulam National Park, Kerala, the highest summit in South India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7aaaed1-3441-4ebc-b941-dfca2745e626', 'Anamudi (2,695 meters in Anaimalai Hills)', true, '2d757b6f-620e-475a-a944-289f85b6e24a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f6c25f3-bebd-47b2-86fa-7de2cada0126', 'Doda Betta (2,637 m)', false, '2d757b6f-620e-475a-a944-289f85b6e24a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5afc45d8-98fc-41cb-a72b-ab6040316c82', 'Mahendragiri', false, '2d757b6f-620e-475a-a944-289f85b6e24a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77d1096f-db24-427c-84c7-9f481ef29459', 'Kalsubai', false, '2d757b6f-620e-475a-a944-289f85b6e24a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da6c1e61-963d-474d-9be3-db71abab0432', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'Which of the following Indian states do NOT share an international boundary with any foreign country and have no coastline (landlocked internal states)?', 'MP, Chhattisgarh, Jharkhand, Telangana, and Haryana are entirely landlocked interior states with neither international frontiers nor coastlines.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68e0c910-6a16-4d75-8d2f-bc758f47f0e6', 'Madhya Pradesh, Chhattisgarh, Jharkhand, Telangana, and Haryana', true, 'da6c1e61-963d-474d-9be3-db71abab0432');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc20fad0-89ef-452b-9788-2e0f6f8bd7d8', 'Gujarat, Rajasthan, Punjab', false, 'da6c1e61-963d-474d-9be3-db71abab0432');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2f3a966-91c9-40a1-b0ff-1dcb98f0eeda', 'West Bengal, Assam, Bihar', false, 'da6c1e61-963d-474d-9be3-db71abab0432');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ed8254e-4fe7-4262-b490-c17a328e4e87', 'Tamil Nadu, Kerala, Karnataka', false, 'da6c1e61-963d-474d-9be3-db71abab0432');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d9d11d7-60ef-4e07-987f-fc0c27aac594', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'What is the physical geographic significance of the ''Ten Degree Channel'' (10° N latitude)?', 'The 10° Channel lies along the 10° N parallel, separating Little Andaman from Car Nicobar across a 150 km strait.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8602c1cf-579a-45c2-aa8f-748a006f624e', 'It is a maritime channel in the Bay of Bengal that separates the Andaman Islands in the north from the Nicobar Islands in the south', true, '2d9d11d7-60ef-4e07-987f-fc0c27aac594');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c632c237-f8d2-4262-97b7-2a42fa23e7cf', 'It separates India from Sri Lanka', false, '2d9d11d7-60ef-4e07-987f-fc0c27aac594');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f79f457f-7c23-4b9b-b7f2-0721780692e0', 'It separates Lakshadweep from Maldives', false, '2d9d11d7-60ef-4e07-987f-fc0c27aac594');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8eaa09e0-59d2-46d9-8310-71b5564d1b6a', 'It separates Gujarat from Pakistan', false, '2d9d11d7-60ef-4e07-987f-fc0c27aac594');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('595b455a-98db-4522-8336-6c010d37830f', 'Class 6', 'Social Science', 'Chapter 7: Our Country — India', 'Hard', 'Why is India described as a land of immense ''Unity in Diversity'' in NCERT Social Science?', 'Coined by Jawaharlal Nehru, ''Unity in Diversity'' celebrates India''s pluralistic mosaic united by shared civilizational and constitutional ethos.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6e8eb2a-2d34-4a4c-a83b-69dbd599af4c', 'Despite profound geographical, climatic, linguistic, religious, and cultural diversity, a deep underlying thread of common national civilization and constitutional brotherhood binds the people of India together as one nation', true, '595b455a-98db-4522-8336-6c010d37830f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20df2cc8-7a88-4fac-800a-809d3b46c740', 'Because all Indians speak only one language', false, '595b455a-98db-4522-8336-6c010d37830f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10a661bb-9ec9-4187-afdc-1dea813abd4e', 'Because all regions look identical', false, '595b455a-98db-4522-8336-6c010d37830f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ae7d351-8959-4757-9621-acd5fe77ee28', 'Because everyone eats the exact same food', false, '595b455a-98db-4522-8336-6c010d37830f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b376a18-d2c4-43d9-9399-a4faf691f870', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'संज्ञा या सर्वनाम के जिस रूप से उसका संबंध वाक्य की क्रिया तथा अन्य शब्दों से जाना जाता है, उसे व्याकरण में क्या कहते हैं?', 'क्रिया से साक्षात् संबंध स्थापित करने वाले संज्ञा/सर्वनाम के रूपात्मक संबंध को ''कारक'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('406fe9fd-8550-4072-b003-071414f73fc5', 'कारक (Case)', true, '4b376a18-d2c4-43d9-9399-a4faf691f870');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61350a19-a13f-480d-bdf2-439754cd5dc0', 'काल', false, '4b376a18-d2c4-43d9-9399-a4faf691f870');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e369ce9-e479-4bb0-90bd-88b1ba01b761', 'वाच्य', false, '4b376a18-d2c4-43d9-9399-a4faf691f870');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3b4c4c5-b385-45d2-9211-3497c12aa42b', 'संधि', false, '4b376a18-d2c4-43d9-9399-a4faf691f870');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('65cf8fda-5e4e-4cc6-973a-18b58fda6c6b', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'हिंदी भाषा में कारक के मुख्य रूप से कितने भेद (प्रकार) होते हैं?', 'हिंदी में आठ कारक होते हैं: कर्ता, कर्म, करण, संप्रदान, अपादान, संबंध, अधिकरण और संबोधन।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1defb6a1-155f-4d2d-bb65-dcf5a70b6c2a', 'आठ भेद (8 Types)', true, '65cf8fda-5e4e-4cc6-973a-18b58fda6c6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('544b80e0-ba91-44a8-93bc-3d36478bf34d', 'छह भेद', false, '65cf8fda-5e4e-4cc6-973a-18b58fda6c6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f80d46dc-4234-48b8-bcbd-22de5a37e1e0', 'सात भेद', false, '65cf8fda-5e4e-4cc6-973a-18b58fda6c6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbdbbcae-1167-4a7f-894b-8818a936ceb9', 'पाँच भेद', false, '65cf8fda-5e4e-4cc6-973a-18b58fda6c6b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53d0d741-9074-4217-a6e5-74188474cd72', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'कारकों को प्रकट करने के लिए संज्ञा या सर्वनाम के साथ लगाए जाने वाले चिह्नों (जैसे: ने, को, से, के लिए, का, में, पर) को क्या कहते हैं?', 'कारक संबंधों को व्यक्त करने वाले प्रत्यय/चिह्न ''विभक्ति'' या ''परसर्ग'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba84bd2c-efe4-4113-81dc-c3ff67b31d59', 'विभक्ति चिह्न या परसर्ग (Case Endings / Postpositions)', true, '53d0d741-9074-4217-a6e5-74188474cd72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4895d52-d759-4c2d-9cac-3142d9071c30', 'उपसर्ग', false, '53d0d741-9074-4217-a6e5-74188474cd72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24b594bc-9bfc-4962-ba8c-4385e067c7d2', 'प्रत्यय', false, '53d0d741-9074-4217-a6e5-74188474cd72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f2e3435-35c4-46f8-9ea1-4504a9680b3f', 'समास', false, '53d0d741-9074-4217-a6e5-74188474cd72');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a15848b8-4016-4994-af3b-30a6d7526d73', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'वाक्य में कार्य (क्रिया) को करने वाले पद को कौन-सा कारक कहते हैं और इसका विभक्ति चिह्न क्या है?', 'क्रिया को संपन्न करने वाला ''कर्ता कारक'' होता है, जिसका प्रमुख परसर्ग ''ने'' है (जैसे: ''राम ने पत्र लिखा'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c86a2dae-c6c9-4e2b-8c73-8cc9ab782f7f', 'कर्ता कारक (विभक्ति: ''ने'')', true, 'a15848b8-4016-4994-af3b-30a6d7526d73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72d0ac4a-8111-47ac-b7ab-c3fd8b368608', 'कर्म कारक (विभक्ति: ''को'')', false, 'a15848b8-4016-4994-af3b-30a6d7526d73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e11a0fc-7c5b-4d01-84a4-8d4b4646689b', 'करण कारक (विभक्ति: ''से'')', false, 'a15848b8-4016-4994-af3b-30a6d7526d73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a87c9c97-cca5-4d7f-83c8-d1515e8f7624', 'अपादान कारक', false, 'a15848b8-4016-4994-af3b-30a6d7526d73');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66a3726f-17bc-4f18-91ee-80ea80b8176c', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'क्रिया का फल (प्रभाव) जिस संज्ञा या सर्वनाम पर पड़ता है, उसे कौन-सा कारक कहते हैं और इसका विभक्ति चिह्न क्या है?', 'जिस वस्तु/प्राणी पर क्रिया का व्यापारिक फल पड़े वह ''कर्म कारक'' है, जिसका परसर्ग ''को'' है (जैसे: ''अध्यापक ने छात्र को पढ़ाया'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0dcc4855-6fc6-4d7c-9df7-1abb6da696b4', 'कर्म कारक (विभक्ति: ''को'')', true, '66a3726f-17bc-4f18-91ee-80ea80b8176c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50dbf969-04c2-4c2e-a643-ad705e6dd8e8', 'कर्ता कारक', false, '66a3726f-17bc-4f18-91ee-80ea80b8176c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b28ad1c-7aad-4b61-abe5-582dc74d3e48', 'करण कारक', false, '66a3726f-17bc-4f18-91ee-80ea80b8176c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbecb1de-e30d-471e-b54b-23491db30bed', 'संबंध कारक', false, '66a3726f-17bc-4f18-91ee-80ea80b8176c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2321b68e-8985-4711-a2bc-65315815c52c', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'कर्ता जिस साधन या माध्यम की सहायता से क्रिया को संपन्न करता है, उसे कौन-सा कारक कहते हैं और इसका विभक्ति चिह्न क्या है?', 'साधनवाची कारक ''करण कारक'' कहलाता है (विभक्ति: ''से/के द्वारा'' - जैसे: ''उसने चाकू से सेब काटा'', ''कलम से लिखा'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6abb9966-ca50-4e89-ba66-311f0fbacce3', 'करण कारक (विभक्ति: ''से'' / ''के द्वारा'')', true, '2321b68e-8985-4711-a2bc-65315815c52c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd3d0edd-46e6-41a4-9db1-5b769258b9b6', 'अपादान कारक', false, '2321b68e-8985-4711-a2bc-65315815c52c');
