INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('117a527a-5eb2-4333-b67c-71a3ffc7d08a', 'अधिकरण कारक', false, '2321b68e-8985-4711-a2bc-65315815c52c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a32883b-3861-448b-9f42-cde41b745f19', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'जिसके लिए कोई कार्य किया जाए या जिसे कुछ दिया जाए, उसे कौन-सा कारक कहते हैं और इसका विभक्ति चिह्न क्या है?', 'दान या उपकार के पात्र हेतु ''संप्रदान कारक'' होता है (विभक्ति: ''के लिए'', ''को'' - जैसे: ''माता जी ने भिखारी को भोजन दिया'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc3c7a13-a345-4ec6-ad4a-9d7f1872fc2f', 'संप्रदान कारक (विभक्ति: ''के लिए'' / ''को'')', true, '0a32883b-3861-448b-9f42-cde41b745f19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30ab75fa-fe66-4432-be87-4fcf5e8a2acd', 'अपादान कारक', false, '0a32883b-3861-448b-9f42-cde41b745f19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e88b6253-851f-41a0-a0d0-57e6ee547842', 'करण कारक', false, '0a32883b-3861-448b-9f42-cde41b745f19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fab6a6d-7b07-42c9-ab78-4d8ae516e6b6', 'कर्ता कारक', false, '0a32883b-3861-448b-9f42-cde41b745f19');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d8d7e14-886e-4320-8e79-58f5b35ab575', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'संज्ञा के जिस रूप से किसी वस्तु या प्राणी का दूसरी वस्तु से अलग (पृथक) होने का भाव प्रकट हो, उसे कौन-सा कारक कहते हैं और इसका विभक्ति चिह्न क्या है?', 'अलगाव, पृथक्करण, भय या तुलना के भाव में ''अपादान कारक'' होता है (विभक्ति: ''से'' - जैसे: ''पेड़ से पत्ता गिरा'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50733c3e-8587-4987-b6ce-fb0d6faa8632', 'अपादान कारक (विभक्ति: ''से'' - अलग होने के अर्थ में)', true, '3d8d7e14-886e-4320-8e79-58f5b35ab575');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8146d121-d625-438c-9814-61fd0d7a3228', 'करण कारक', false, '3d8d7e14-886e-4320-8e79-58f5b35ab575');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa48ed33-5557-4864-adc1-213332e8a573', 'कर्म कारक', false, '3d8d7e14-886e-4320-8e79-58f5b35ab575');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f07a6d0-48c6-4365-94f5-bc883b5504f3', 'अधिकरण कारक', false, '3d8d7e14-886e-4320-8e79-58f5b35ab575');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca9a9374-afd3-4669-841e-2d534d543c5b', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'संज्ञा या सर्वनाम के जिस रूप से उसका संबंध वाक्य के किसी अन्य संज्ञा/सर्वनाम से प्रकट हो, उसे कौन-सा कारक कहते हैं?', 'पारस्परिक स्वामित्व व संबंध दर्शाने वाला ''संबंध कारक'' होता है (जैसे: ''यह रोहन का घर है'', ''मेरी पुस्तक'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('850311ab-66df-4e1e-a9b4-ad1168a691a4', 'संबंध कारक (विभक्ति: ''का, के, की, रा, रे, री, ना, ने, नी'')', true, 'ca9a9374-afd3-4669-841e-2d534d543c5b');
