INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37c7e5a9-8ac3-4561-bad1-1080b9b6bc57', 'करण कारक', false, 'ca9a9374-afd3-4669-841e-2d534d543c5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91b730ac-08d0-4a2b-8d62-21b651b84626', 'संप्रदान कारक', false, 'ca9a9374-afd3-4669-841e-2d534d543c5b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9af80520-e075-416d-a3e0-caa8bf039db6', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'क्रिया के घटित होने के स्थान, आधार या समय का बोध कराने वाले संज्ञा पद को कौन-सा कारक कहते हैं?', 'क्रिया के आधार (स्थान/काल) का बोधक ''अधिकरण कारक'' कहलाता है (जैसे: ''पक्षी पेड़ पर बैठे हैं'', ''कमरे में पंखा है'')।', NOW()) ON CONFLICT DO NOTHING;
