INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('880c91d6-b4e9-4085-90d1-0cd08c5eff30', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Easy', 'संज्ञा के जिस रूप से किसी को पुकारने, बुलाने, सचेत करने या संबोधित करने का भाव प्रकट हो, उसे कौन-सा कारक कहते हैं?', 'आह्वान या संबोधन हेतु विस्मयादिबोधक चिह्न (!) युक्त ''संबोधन कारक'' प्रयुक्त होता है (जैसे: ''हे प्रभु! रक्षा करो'')।', NOW()) ON CONFLICT DO NOTHING;
