INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56848e43-fb51-4c27-b752-4ca271a51ed6', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Medium', 'करण कारक और अपादान कारक दोनों का विभक्ति चिह्न ''से'' होता है। इन दोनों में क्या मूलभूत अंतर है?', 'करण का ''से'' सहायक इंस्ट्रूमेंटल साधन है; अपादान का ''से'' एब्लेटिव सेपरेशन, फियर या ओरिजिन का परिचायक है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2737717-a963-4bba-a3c4-de9ba0df328b', 'करण कारक में ''से'' का प्रयोग ''साधन/माध्यम'' के रूप में होता है (जैसे: ''कलम से लिखना''), जबकि अपादान कारक में ''से'' का प्रयोग ''अलग होने, डरने या तुलना करने'' के अर्थ में होता है (जैसे: ''पेड़ से गिरना'', ''शेर से डरना'')', true, '56848e43-fb51-4c27-b752-4ca271a51ed6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('274cd3b3-9ef1-4688-bf19-7d745495db39', 'करण कारक केवल इंसानों के लिए आता है', false, '56848e43-fb51-4c27-b752-4ca271a51ed6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e03e850-b75c-4a7e-8dfa-d20a89b828b4', 'अपादान कारक में ''से'' कभी नहीं आता', false, '56848e43-fb51-4c27-b752-4ca271a51ed6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46143cf6-e262-458d-98b8-d47bf032a039', 'कोई अंतर नहीं है', false, '56848e43-fb51-4c27-b752-4ca271a51ed6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8bb9d4bd-0faf-4026-900f-3d2e745d47ba', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Medium', 'वाक्य में प्रयुक्त दोनों ''से'' का सही कारक क्रम बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('668c352f-0451-43da-9604-26be2ef5a937', 'बस से = करण कारक ; घर से = अपादान कारक', true, '8bb9d4bd-0faf-4026-900f-3d2e745d47ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3868c0c3-2bc7-48ad-a8ea-65df6b90b44c', 'बस से = अपादान कारक ; घर से = करण कारक', false, '8bb9d4bd-0faf-4026-900f-3d2e745d47ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dcc0cf3-cf44-46d5-8fd3-6b2338951f8a', 'दोनों करण कारक हैं', false, '8bb9d4bd-0faf-4026-900f-3d2e745d47ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26db7675-152a-44a6-b5cd-78ed44faccc8', 'दोनों अपादान कारक हैं', false, '8bb9d4bd-0faf-4026-900f-3d2e745d47ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('507a75cf-325d-43c5-af18-1d814c6dcb94', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Medium', 'कर्म कारक और संप्रदान कारक दोनों में ''को'' विभक्ति का प्रयोग होता है। इन दोनों में क्या अंतर है?', 'दानार्थे चतुर्थी (संप्रदान) में जब कोई वस्तु किसी को हमेशा के लिए दी जाए तो ''को'' संप्रदान कारक बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cea80888-a914-4507-9c73-22a3bfec05b9', 'कर्म कारक में ''को'' क्रिया के प्रभाव/फल को दर्शाता है, जबकि संप्रदान कारक में ''को'' ''देने के भाव'' (उपकार/दान) में ''के लिए'' के स्थान पर आता है (जैसे: ''गरीब को कम्बल दो'')', true, '507a75cf-325d-43c5-af18-1d814c6dcb94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15decf64-9901-4f7f-8e74-a4a26cb15973', 'कर्म कारक में ''को'' कभी नहीं लगता', false, '507a75cf-325d-43c5-af18-1d814c6dcb94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53d566ef-1e14-4ec6-b236-0feaf4aff993', 'संप्रदान कारक में केवल ''ने'' लगता है', false, '507a75cf-325d-43c5-af18-1d814c6dcb94');
