INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97be59d3-5f89-49bd-8027-5311edc10b08', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Medium', 'सर्वनाम शब्दों में कारक विभक्ति चिह्न जोड़ने पर बनने वाले रूपों का सही युग्म कौन-सा है?', 'सर्वनामों के साथ विभक्तियाँ मिलाकर संश्लिष्ट (synthesized) रूप में लिखी जाती हैं: मैंने, उसे, हमसे, तुम्हारा।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61cde71a-fac4-420c-99a2-34864f55b47b', 'मैं + ने = मैंने ; वह + को = उसको / उसे ; हम + से = हमसे ; तुम + का = तुम्हारा', true, '97be59d3-5f89-49bd-8027-5311edc10b08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf9f0178-bfdf-4ce6-9157-a3fd30b58716', 'मैं + ने = मैन्ने ; वह + को = वहको', false, '97be59d3-5f89-49bd-8027-5311edc10b08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae8dda20-30e6-41af-8601-6139eb4dc2dc', 'हम + से = हमोंसे', false, '97be59d3-5f89-49bd-8027-5311edc10b08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b238a2f-3e67-4d44-a07b-e438b441e423', 'तुम + का = तुमाका', false, '97be59d3-5f89-49bd-8027-5311edc10b08');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad241bf9-66cf-4e9e-b917-42e90486b778', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Medium', 'संज्ञा शब्दों के साथ कारक विभक्तियाँ किस प्रकार लिखी जाती हैं?', 'मानक हिंदी वर्तनी नियम: संज्ञा के साथ परसर्ग अलग (स्पेस देकर) लिखे जाते हैं, जबकि सर्वनाम के साथ जोड़कर लिखे जाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89066578-40b1-4d75-8b3a-3d2b755f4784', 'संज्ञा शब्दों से अलग (विश्लिष्ट) हटाकर लिखी जाती हैं (जैसे: ''राम ने'', ''पेड़ पर'', ''घर से'')', true, 'ad241bf9-66cf-4e9e-b917-42e90486b778');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbab95c0-2184-4278-8bd0-43a213254e69', 'संज्ञा के साथ चिपकाकर मिलाकर लिखी जाती हैं', false, 'ad241bf9-66cf-4e9e-b917-42e90486b778');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dbd0c5c-0565-4f45-b4e4-0255f9e00836', 'विभक्तियाँ कभी नहीं लिखी जातीं', false, 'ad241bf9-66cf-4e9e-b917-42e90486b778');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e988513-2c51-4260-8412-3fbfa047ad91', 'संज्ञा के आगे लिखी जाती हैं', false, 'ad241bf9-66cf-4e9e-b917-42e90486b778');
