INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b5754112-f8e7-4268-a96f-464aebe046d2', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('786c90a6-4f45-4256-bdca-202cacd976e5', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'b5754112-f8e7-4268-a96f-464aebe046d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e58a1fc-54dd-481c-ba3e-99127a49dccb', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'b5754112-f8e7-4268-a96f-464aebe046d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11e3f93f-d4c7-471c-b032-9b225e4eb68f', '(A) सही है, परन्तु (R) गलत है।', false, 'b5754112-f8e7-4268-a96f-464aebe046d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbb010c1-c089-4cce-8719-d7f35c0bf5cb', '(A) गलत है, परन्तु (R) सही है।', false, 'b5754112-f8e7-4268-a96f-464aebe046d2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cac97a94-10b8-424f-8f97-8664e377cee8', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Hard', 'Spot the IMPOSTER in the following group of कारक और उनकी विभक्तियों के युग्म में:
