INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9607d464-8dcc-4f23-ae76-e71216fda832', 'करण - से (द्वारा)', false, 'cac97a94-10b8-424f-8f97-8664e377cee8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57911f1f-8266-4717-91a4-69892863aa90', 'संप्रदान - के लिए', false, 'cac97a94-10b8-424f-8f97-8664e377cee8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52fa0393-ed81-4f4a-a576-ff48433c07af', 'अपादान - में (पर)', true, 'cac97a94-10b8-424f-8f97-8664e377cee8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ba2a86a-59ed-48ab-8efe-ab667cf5d63d', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Hard', 'सुमेलित कीजिए (वाक्य और उनमें प्रयुक्त प्रमुख कारक):
(क) छात्र कलम से लिखता है   -> (i) अपादान कारक
(ख) पेड़ से फल गिरा          -> (ii) करण कारक
(ग) राजा ने ब्राह्मण को दान दिया -> (iii) अधिकरण कारक
(घ) पक्षी घोंसले में बैठे हैं     -> (iv) संप्रदान कारक', 'कलम से = करण; पेड़ से = अपादान; ब्राह्मण को = संप्रदान; घोंसले में = अधिकरण।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42e9f97a-6ac9-47c7-9390-fb244c216562', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', true, '9ba2a86a-59ed-48ab-8efe-ab667cf5d63d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('814e4301-a50a-4c8d-b411-e214b504c8f4', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, '9ba2a86a-59ed-48ab-8efe-ab667cf5d63d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bbb2a03-0d0d-46fc-bfaa-3d9c530526e8', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '9ba2a86a-59ed-48ab-8efe-ab667cf5d63d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b1f1908-6a4e-4637-8adf-5705e7238f36', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '9ba2a86a-59ed-48ab-8efe-ab667cf5d63d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7da0215-a9a7-43c6-b44f-d1842f74fd1c', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Hard', 'निम्नलिखित वाक्य में सभी आठ कारकों का एक साथ अद्भुत प्रयोग देखिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c345c3c-8903-46e3-bd24-582d5747a6ac', 'बाण से = करण कारक ; अयोध्या से = अपादान कारक ; लंका में = अधिकरण कारक', true, 'c7da0215-a9a7-43c6-b44f-d1842f74fd1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('436dce72-7d52-46c6-9d44-a697c3d30e16', 'बाण से = अपादान ; अयोध्या से = करण ; लंका में = कर्म', false, 'c7da0215-a9a7-43c6-b44f-d1842f74fd1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('361485e0-eae0-424f-8979-1aeca84ba65c', 'तीनों करण कारक हैं', false, 'c7da0215-a9a7-43c6-b44f-d1842f74fd1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f607b609-f2f7-416d-8eb3-4918a1915da3', 'तीनों अधिकरण कारक हैं', false, 'c7da0215-a9a7-43c6-b44f-d1842f74fd1c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('de479e78-bf36-4be0-a64d-9940ee709c4b', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Hard', 'जब कोई वस्तु किसी को सदा के लिए न देकर केवल कुछ समय के लिए दी जाए (जैसे: ''मैंने धोबी को कपड़े दिए'' या ''मैंने मित्र को पुस्तक दी पढ़ने के लिए''), तो वहाँ कौन-सा कारक होता है?', 'दानार्थे चतुर्थी का नियम: जब वस्तु वापस ली जानी हो (धोबी को कपड़े), तो वहाँ कर्म कारक मान्य होता है, संप्रदान नहीं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afd88c4f-d7e4-4379-9087-4f6a2835b305', 'कर्म कारक (चूँकि वस्तु हमेशा के लिए दान नहीं दी गई, अतः संप्रदान न होकर कर्म कारक होगा)', true, 'de479e78-bf36-4be0-a64d-9940ee709c4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('441f7d62-5086-4596-bebf-529c2a058b37', 'संप्रदान कारक', false, 'de479e78-bf36-4be0-a64d-9940ee709c4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69ca60fb-f58f-4251-900a-f8c9198d977e', 'अपादान कारक', false, 'de479e78-bf36-4be0-a64d-9940ee709c4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b33f4076-471b-497a-a22c-545f9211cb24', 'संबंध कारक', false, 'de479e78-bf36-4be0-a64d-9940ee709c4b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4d38c09-a7c1-44fa-9e4f-b76a294a44f6', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Hard', 'वाक्य में रेखांकित पदों के कारकों का सही युग्म चुनिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5288727-249f-431d-91fe-0a5035787aca', 'गुरु जी को = संप्रदान कारक (नमस्कार/स्वस्ति योगे चतुर्थी) ; गीता से = अपादान कारक (तुलना)', true, 'd4d38c09-a7c1-44fa-9e4f-b76a294a44f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bbea5bc-960b-49e0-b793-a206a8fb6002', 'दोनों कर्म कारक हैं', false, 'd4d38c09-a7c1-44fa-9e4f-b76a294a44f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cfd314a-34aa-4915-bc75-700a20199a0a', 'दोनों करण कारक हैं', false, 'd4d38c09-a7c1-44fa-9e4f-b76a294a44f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('573018d6-8f32-4cf1-91a2-5e75bd400fd2', 'गुरु जी को = कर्म कारक ; गीता से = करण कारक', false, 'd4d38c09-a7c1-44fa-9e4f-b76a294a44f6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b659acf-e75c-4112-a20f-eb021d1ec62f', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Hard', 'कर्मवाच्य या भाववाच्य के वाक्यों में कर्ता के साथ किस कारक विभक्ति का प्रयोग होता है?', 'कर्मवाच्य और भाववाच्य में कर्ता गौण होकर ''से/के द्वारा'' विभक्ति ग्रहण करता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c99c871-c7eb-473e-aac0-68d6433c463b', '''से'' या ''के द्वारा'' (करण कारक परसर्ग - जैसे: ''मुझसे चला नहीं जाता'', ''मोहन के द्वारा पत्र लिखा गया'')', true, '8b659acf-e75c-4112-a20f-eb021d1ec62f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4346c22-092d-4b4b-b3c6-b3d3a4034add', 'केवल ''ने''', false, '8b659acf-e75c-4112-a20f-eb021d1ec62f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('292d2d23-0ac6-446d-b616-188421f66a96', 'केवल ''को''', false, '8b659acf-e75c-4112-a20f-eb021d1ec62f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca11455f-f266-49ee-b89f-e5da8d6e4f45', 'कोई विभक्ति नहीं लगती', false, '8b659acf-e75c-4112-a20f-eb021d1ec62f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e3810c07-2ea5-4257-b806-f9fdcc91cb25', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Hard', 'वाक्य में प्रयुक्त रेखांकित पद का कारक बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b7654ec-e2f9-4a80-bc15-e1253e5492ab', 'जन्म से = अपादान कारक (आरंभ/काल की उत्पत्ति) ; आँखों से = करण कारक (देखने का साधन अंग)', true, 'e3810c07-2ea5-4257-b806-f9fdcc91cb25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('821c9b21-ffbb-4fd7-a94b-ff71c28e5716', 'दोनों अपादान कारक हैं', false, 'e3810c07-2ea5-4257-b806-f9fdcc91cb25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d251c634-79fb-4b39-ae58-67a3c4aab63e', 'दोनों करण कारक हैं', false, 'e3810c07-2ea5-4257-b806-f9fdcc91cb25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65f1d718-ce91-4395-a4ae-cbc478256805', 'जन्म से = करण ; आँखों से = अपादान', false, 'e3810c07-2ea5-4257-b806-f9fdcc91cb25');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a4d3827-e2a4-413c-a765-d982d80faf91', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Hard', 'वाक्य को शुद्ध कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19895b41-f7d8-4f7c-af1d-b99ac4d062a6', 'मुझे बाज़ार जाना है। (''मेरे को'' अमानक है, उत्तम पुरुष में ''मुझे'' शुद्ध है)', true, '8a4d3827-e2a4-413c-a765-d982d80faf91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f28eaec-f054-4a8b-b175-3bad696707aa', 'मुझको को बाज़ार जाना है।', false, '8a4d3827-e2a4-413c-a765-d982d80faf91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85083446-0469-4941-90c8-eb9c800d6c59', 'मैं ने बाज़ार जाना है।', false, '8a4d3827-e2a4-413c-a765-d982d80faf91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11ccb076-49ee-4848-98b6-3cf43bee2f13', 'मेरा बाज़ार जाना है।', false, '8a4d3827-e2a4-413c-a765-d982d80faf91');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d24edb24-b9f1-45ce-99ce-cd7418b67a02', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Hard', 'संस्कृत व्याकरण में ''संबोधन'' और ''संबंध'' को स्वतंत्र कारक क्यों नहीं माना जाता, जबकि हिंदी में आठों को कारक माना जाता है?', 'संस्कृत में साक्षात् क्रियान्वयी केवल 6 कारक माने जाते हैं, किन्तु हिंदी में आठों रूपों को व्यावहारिक रूप से कारक स्वीकार किया गया है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b1bef60-4cf3-43fa-a36e-c50e710f488a', 'क्योंकि संस्कृत में ''साक्षात् क्रियान्वयित्वं कारकत्वम्'' (क्रिया से सीधा संबंध) की परिभाषा है, जबकि संबंध और संबोधन का क्रिया से सीधा संबंध नहीं होता', true, 'd24edb24-b9f1-45ce-99ce-cd7418b67a02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4176328-8b39-4948-860c-1c441d478040', 'क्योंकि संस्कृत में शब्द कम थे', false, 'd24edb24-b9f1-45ce-99ce-cd7418b67a02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('940244bd-bc65-4416-98e4-5d27e33eed3c', 'क्योंकि हिंदी में नियम नहीं होते', false, 'd24edb24-b9f1-45ce-99ce-cd7418b67a02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b08d394d-c106-4927-90f8-d9f20cb6c4d8', 'कोई कारण नहीं है', false, 'd24edb24-b9f1-45ce-99ce-cd7418b67a02');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('affc0f43-262e-488b-b2f8-40574449175a', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Hard', 'वाक्य में प्रयुक्त रेखांकित पद का कारक बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df17c286-4313-4744-a87a-6db1090f38de', 'करण कारक (सफाई की क्रिया का उपकरण/साधन ''झाड़ू'')', true, 'affc0f43-262e-488b-b2f8-40574449175a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb77067c-c41e-477f-8a0c-5b51691446ea', 'कर्म कारक', false, 'affc0f43-262e-488b-b2f8-40574449175a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3497a8fc-f01d-4281-ab7f-592695230c94', 'अपादान कारक', false, 'affc0f43-262e-488b-b2f8-40574449175a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bfc0fcf-4304-474a-a588-600cd9782a28', 'अधिकरण कारक', false, 'affc0f43-262e-488b-b2f8-40574449175a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c89b2d85-4843-401d-8e47-3274b72e51b9', 'Class 6', 'Hindi Grammar', 'Chapter 7: कारक', 'Hard', 'अकर्मक क्रियाओं के भूतकालिक रूप में कर्ता के साथ ''ने'' का प्रयोग क्यों नहीं होता?', 'हँसना, रोना, सोना, चलना आदि अकर्मक धातुओं के भूतकाल में ''ने'' का प्रयोग वर्जित है (वह सोया, बच्चा रोया)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac7e4b2e-9e8f-44ee-a2c1-58c1a688dbce', 'नियमतः ''ने'' का प्रयोग केवल सकर्मक क्रियाओं के भूतकाल में ही होता है (जैसे: ''वह हँसा'' शुद्ध है ; ''उसने हँसा'' अशुद्ध है)', true, 'c89b2d85-4843-401d-8e47-3274b72e51b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9901c451-5400-4868-9c67-59b49eabccb8', 'क्योंकि अकर्मक क्रिया भूतकाल में नहीं होती', false, 'c89b2d85-4843-401d-8e47-3274b72e51b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a209d06-710e-4792-aa4e-067fe6f63b3a', 'क्योंकि ''ने'' केवल स्त्रीलिंग में आता है', false, 'c89b2d85-4843-401d-8e47-3274b72e51b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e065114-3217-4ba4-b285-8c275a3da827', 'कोई नियम नहीं है', false, 'c89b2d85-4843-401d-8e47-3274b72e51b9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('05ac0103-b0a4-4993-b31f-9f704c9176ee', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Easy', 'Objects that emit or give out light of their own (such as the Sun, stars, a lit candle, an electric torch) are called:', 'Luminous objects radiate their own photon emissions directly (e.g. the Sun, electric bulb, candle flame).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad601971-c6ff-4435-8cc2-141e37353de4', 'Luminous Objects', true, '05ac0103-b0a4-4993-b31f-9f704c9176ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32bcb0b5-7451-49d5-ae0f-6fecb9bf730a', 'Non-luminous Objects', false, '05ac0103-b0a4-4993-b31f-9f704c9176ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d16340d1-28ee-443e-a689-3f938d76824e', 'Transparent Objects', false, '05ac0103-b0a4-4993-b31f-9f704c9176ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('557b71d6-60ac-4f64-befe-ff212d9a33ec', 'Opaque Objects', false, '05ac0103-b0a4-4993-b31f-9f704c9176ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7739bc84-a79e-48a1-bada-4841d0ef4367', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Easy', 'Objects that do NOT emit light of their own and become visible only when light falls on them (such as the Moon, a chair, a book) are called:', 'Non-luminous bodies (including the Moon, which reflects sunlight) do not generate intrinsic light.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af1aaf25-4841-47f2-8cfb-a5a2af0506bb', 'Non-luminous Objects', true, '7739bc84-a79e-48a1-bada-4841d0ef4367');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51293e8c-7cf0-4f70-95a2-d9d2eea63f0e', 'Luminous Objects', false, '7739bc84-a79e-48a1-bada-4841d0ef4367');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e660c49-6500-4ea3-a67a-2632d46a8712', 'Incandescent Objects', false, '7739bc84-a79e-48a1-bada-4841d0ef4367');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('854afecc-d54a-4a37-83d7-ca4fa8ba5da1', 'Fluorescent Objects', false, '7739bc84-a79e-48a1-bada-4841d0ef4367');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e0a28e22-f350-4692-a27a-947b4e981f1d', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Easy', 'Materials that allow light to pass through them completely and clearly, so that objects behind them can be seen distinctly (such as clear glass, air, clean water) are called:', 'Transparent media transmit light rays with negligible absorption and scattering, permitting sharp visual transmission.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74111a12-1d26-4864-9067-90e411e11d02', 'Transparent Materials', true, 'e0a28e22-f350-4692-a27a-947b4e981f1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ff82f60-d8ae-4c24-bd51-17ca8fb7bf6d', 'Translucent Materials', false, 'e0a28e22-f350-4692-a27a-947b4e981f1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da234756-f903-4f1f-9256-ed36664740ae', 'Opaque Materials', false, 'e0a28e22-f350-4692-a27a-947b4e981f1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87e33d3e-e2f7-4ad7-ba26-1b28f6d12ec0', 'Luminous Materials', false, 'e0a28e22-f350-4692-a27a-947b4e981f1d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d21c53e-d35f-4adf-a46e-ba58d3d82af7', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Easy', 'Materials that do NOT allow ANY light to pass through them at all, so that we cannot see through them (such as a wooden board, brick wall, metal plate) are called:', 'Opaque materials completely absorb and reflect incident light, blocking optical transmission.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b96b6f36-23f8-47d6-a004-b5bbac7e2cb9', 'Opaque Materials', true, '2d21c53e-d35f-4adf-a46e-ba58d3d82af7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52a573f0-8757-4eb2-966b-2aaf61bb7598', 'Transparent Materials', false, '2d21c53e-d35f-4adf-a46e-ba58d3d82af7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5d95226-d4bf-43c2-8f6c-2216e1fa2fe4', 'Translucent Materials', false, '2d21c53e-d35f-4adf-a46e-ba58d3d82af7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1498e6a-3d96-44e9-baf9-264e9dd73f2d', 'Luminous Materials', false, '2d21c53e-d35f-4adf-a46e-ba58d3d82af7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9178857-b446-4904-ab72-aa6c6333c2b1', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Easy', 'Materials that allow light to pass through them only partially, so that objects behind them can be seen only faintly or hazily (such as butter paper, frosted glass, oily paper) are called:', 'Translucent media transmit light diffusely, scattering photons so images behind appear indistinct.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba4447a3-376e-44fb-9242-c78213ad1278', 'Translucent Materials', true, 'a9178857-b446-4904-ab72-aa6c6333c2b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59e0491b-1e14-49b9-a2d0-0cd9dbc9c9d8', 'Transparent Materials', false, 'a9178857-b446-4904-ab72-aa6c6333c2b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e771020-42de-4a53-aeaa-96499a79d612', 'Opaque Materials', false, 'a9178857-b446-4904-ab72-aa6c6333c2b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('180c815b-4b8a-4653-8bd8-a20f5062a6a3', 'Reflective Materials', false, 'a9178857-b446-4904-ab72-aa6c6333c2b1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('724e7224-7aef-44e6-b5b6-4bb4263afa0f', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Easy', 'A dark patch formed on a surface behind an opaque object when it blocks the straight path of light is called a:', 'A shadow is an umbral region of darkness cast when an opaque body obstructs rectilinear light propagation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26105e66-b8ca-40f5-bc44-76b4b6c40b6c', 'Shadow', true, '724e7224-7aef-44e6-b5b6-4bb4263afa0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46050bb1-a7e8-4030-b2d7-5ee47aa2e919', 'Reflection', false, '724e7224-7aef-44e6-b5b6-4bb4263afa0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72f1743d-f377-454e-8ee0-2dd4391ee260', 'Spectrum', false, '724e7224-7aef-44e6-b5b6-4bb4263afa0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47ab0301-e6cf-4411-8320-e1630e4df64e', 'Beam', false, '724e7224-7aef-44e6-b5b6-4bb4263afa0f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc6ceb45-96a9-4d45-aa46-4f11e0ea64cc', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Easy', 'What three essential things are required to form and view a Shadow?', 'Shadow formation strictly necessitates 1. an incident light source, 2. an obstructing opaque object, and 3. a screen/surface to cast upon.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e4baced-b27e-476a-b7c5-9f9a82950973', 'A Source of Light, an Opaque Object, and a Screen (surface)', true, 'fc6ceb45-96a9-4d45-aa46-4f11e0ea64cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b89fe0dd-5b6c-403b-88b3-5faf013b45f3', 'A Mirror, a Candle, and Water', false, 'fc6ceb45-96a9-4d45-aa46-4f11e0ea64cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86538aa1-a3b2-48e5-8805-0c30d320615e', 'Only a Light Source', false, 'fc6ceb45-96a9-4d45-aa46-4f11e0ea64cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9df0fce7-905f-4a7e-bdb5-83cd16303e32', 'Only a transparent glass', false, 'fc6ceb45-96a9-4d45-aa46-4f11e0ea64cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('92701884-cb16-47a0-89ef-85f5d1679034', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Easy', 'The fundamental scientific principle that light travels strictly in STRAIGHT LINES is known as:', 'Rectilinear propagation states that optical rays travel along straight linear trajectories in a homogeneous medium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de0fe3a2-255d-4733-b636-28a823ccc2c6', 'Rectilinear Propagation of Light', true, '92701884-cb16-47a0-89ef-85f5d1679034');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3c2171f-6e41-473c-9b24-72cf1904fbd6', 'Curvilinear Propagation', false, '92701884-cb16-47a0-89ef-85f5d1679034');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff12ada4-d0a8-4c41-ac4d-d3d649148d83', 'Dispersion', false, '92701884-cb16-47a0-89ef-85f5d1679034');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38ac11b1-d956-4ff3-9a9a-6c12d1a35fe7', 'Total Internal Reflection', false, '92701884-cb16-47a0-89ef-85f5d1679034');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3cb88e9-4285-4f3f-be86-7d3d1ad5f7fa', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Easy', 'What simple optical device consisting of a box with a tiny pinhole aperture at one end produces an INVERTED (upside-down) image on a translucent screen without using any glass lens?', 'A pinhole camera exploits rectilinear light paths crossing through a minute aperture to project an inverted real image.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11e8fff6-6670-4f28-8ca3-c2090016f470', 'Pinhole Camera (Camera Obscura)', true, 'f3cb88e9-4285-4f3f-be86-7d3d1ad5f7fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33583b7d-bd6b-4ab5-bd13-b003a2d984f2', 'Microscope', false, 'f3cb88e9-4285-4f3f-be86-7d3d1ad5f7fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c069625-1040-46a7-a776-d89c3c2577a9', 'Telescope', false, 'f3cb88e9-4285-4f3f-be86-7d3d1ad5f7fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('810ec183-4b66-4fb9-bd66-5a90d151ff4f', 'Periscope', false, 'f3cb88e9-4285-4f3f-be86-7d3d1ad5f7fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07b2e0f0-6dc0-4640-817d-061bf1c6f684', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Easy', 'The bouncing back of light rays when they strike a smooth, polished, highly reflective surface (such as a plane mirror or still water surface) is called:', 'Reflection is the redirection of incident light waves at an interface according to the laws of reflection.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aadfd37a-aa61-4f1b-afdc-4948b1e67186', 'Reflection of Light', true, '07b2e0f0-6dc0-4640-817d-061bf1c6f684');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef2ef49c-f677-47af-8670-910ec04d9cad', 'Refraction of Light', false, '07b2e0f0-6dc0-4640-817d-061bf1c6f684');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dff75db-cf9c-47f9-bf4d-fd78d5e21bb2', 'Absorption of Light', false, '07b2e0f0-6dc0-4640-817d-061bf1c6f684');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('846f2cda-5b5a-48d2-893e-a3465543d8b1', 'Shadowing', false, '07b2e0f0-6dc0-4640-817d-061bf1c6f684');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66f05b7a-9037-4f69-8bf7-daf7157b906a', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Easy', 'What are the characteristics of the image of our face formed in a standard Plane Mirror?', 'A plane mirror forms a virtual, erect, equi-distant, unmagnified, laterally inverted image.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bad67d01-4cd6-40ea-baf5-999efb84d59c', 'Erect (upright), same size as the object, laterally inverted (left appears right), and formed at the same distance behind the mirror', true, '66f05b7a-9037-4f69-8bf7-daf7157b906a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6b8296d-12e5-4403-85f4-b66d86130ea8', 'Inverted and very small', false, '66f05b7a-9037-4f69-8bf7-daf7157b906a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec542f2f-3ec2-4d38-a9c0-6f2eefc3be5c', 'Dark black like a shadow', false, '66f05b7a-9037-4f69-8bf7-daf7157b906a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef80f8bc-c46d-4312-8451-4174f67701ee', 'Upside-down and magnified', false, '66f05b7a-9037-4f69-8bf7-daf7157b906a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60154cbd-4d2f-4f86-b7c1-2f33ae8b1919', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Easy', 'What natural pinhole images can be observed on the ground under a dense tree during bright daylight?', 'Gaps between leafy canopies act as natural pinhole apertures, projecting circular solar images onto the ground.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e3f4b88-6274-499e-99ee-9d7f07b9043c', 'Circular bright patches of light (which are actually pinhole images of the Sun formed by tiny gaps between overlapping leaves)', true, '60154cbd-4d2f-4f86-b7c1-2f33ae8b1919');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e94c90c1-33c3-4fdf-b0d8-8419107f0674', 'Square dark holes', false, '60154cbd-4d2f-4f86-b7c1-2f33ae8b1919');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d408730-05c0-4f54-acc9-bc7036293735', 'Pictures of birds', false, '60154cbd-4d2f-4f86-b7c1-2f33ae8b1919');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70a29f5d-4690-4448-8588-348d363dfb1b', 'Rainbow rings', false, '60154cbd-4d2f-4f86-b7c1-2f33ae8b1919');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd12660f-d31b-41dc-8c85-0f4102c7c83b', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Medium', 'What is the crucial difference between a ''Shadow'' and an ''Image'' formed by a mirror?', 'Shadows represent absence of light displaying silhouette geometry; optical images reproduce chromatic wavelengths and surface textures.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('465b3ece-d24c-4501-a398-93f9760034bb', 'A Shadow is only a dark outline showing the shape of an object without any color or details; an Image shows the full color, facial details, and features of the object formed by reflected light', true, 'cd12660f-d31b-41dc-8c85-0f4102c7c83b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('049cb6de-6a4d-421d-8d7f-5013ff71969b', 'A Shadow is colorful while an image is black', false, 'cd12660f-d31b-41dc-8c85-0f4102c7c83b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('398d346b-5458-49c8-8c99-cc2e1737a210', 'A Shadow is formed by mirrors', false, 'cd12660f-d31b-41dc-8c85-0f4102c7c83b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1d9fd53-55a2-4b0d-9773-d14bf269d7b3', 'There is no difference', false, 'cd12660f-d31b-41dc-8c85-0f4102c7c83b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0be162e5-23cf-4b50-ae39-3ef28642ebd8', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Medium', 'Why can we NOT see the flame of a lit candle when looking through a BENT or curved plastic pipe, whereas we can see it clearly through a STRAIGHT pipe?', 'Light cannot spontaneously negotiate curvature without reflective mirrors, proving straight-line rectilinear transmission.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f7f17dc-17ff-4c81-a791-14ffcf246403', 'Because light travels only in straight lines (Rectilinear propagation) and cannot bend around the corners of a curved pipe', true, '0be162e5-23cf-4b50-ae39-3ef28642ebd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('725b43ab-b3e6-4aac-887c-1bddf7b17282', 'Because the bent pipe blows out the candle flame', false, '0be162e5-23cf-4b50-ae39-3ef28642ebd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99d3fb7c-737d-4138-b994-f4607f9c9889', 'Because candle light is too heavy to travel up a pipe', false, '0be162e5-23cf-4b50-ae39-3ef28642ebd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cd5cfc1-a0e3-40eb-a42b-c65bceb5c84a', 'Because curved pipes absorb all oxygen', false, '0be162e5-23cf-4b50-ae39-3ef28642ebd8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f8a2def-5651-46cb-9080-56bfbf07809d', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Medium', 'Why does the color of a shadow NOT change when a red ball, a green book, or a yellow toy blocks white light?', 'Shadows are regions of photon deprivation (umbra); chromatic properties of the blocking opaque object do not affect the darkness.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78ff9881-2778-4f7f-b422-6eb9a6d5778d', 'Because a shadow is merely an area of darkness where light was completely blocked from reaching the screen, regardless of the object''s surface color', true, '0f8a2def-5651-46cb-9080-56bfbf07809d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1b05ddc-4611-482d-a71f-e09b3975d80a', 'Because all shadows are painted black by nature', false, '0f8a2def-5651-46cb-9080-56bfbf07809d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f86edca-22be-48c2-b2ff-8a2851bce017', 'Because colored light is absorbed by the ground', false, '0f8a2def-5651-46cb-9080-56bfbf07809d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b42afa1-7aaf-4617-a575-5a5221ef9f8a', 'Because human eyes only see black', false, '0f8a2def-5651-46cb-9080-56bfbf07809d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5ef4f8af-1890-48f7-8c08-4ba91664795d', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Medium', 'What is ''Lateral Inversion'' observed when you raise your left hand in front of a plane mirror?', 'Front-to-back ray reflection reverses apparent lateral chirality: left hand maps to the image''s right hand.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f54588b4-35b4-47ce-a279-46911962979d', 'The phenomenon where the left side of the object appears as the right side in the mirror image, and the right side appears as the left side', true, '5ef4f8af-1890-48f7-8c08-4ba91664795d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d9543f1-8930-4a16-876f-6c5fb7a3e821', 'The image turns completely upside-down', false, '5ef4f8af-1890-48f7-8c08-4ba91664795d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d74861f8-b9e7-41f9-838e-503f652f401f', 'The image disappears', false, '5ef4f8af-1890-48f7-8c08-4ba91664795d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9704fd25-b81b-4922-a57c-414526016ff5', 'The image becomes transparent', false, '5ef4f8af-1890-48f7-8c08-4ba91664795d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fee3d6e2-f9fd-433b-8665-5c4efeaef9ce', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Medium', 'Why is the word ''AMBULANCE'' printed backwards (''ECNALUBMA'') on the front of emergency hospital vans?', 'Pre-inverting the lettering ensures that lateral inversion in planar rear-view mirrors restores legible front-facing orthography.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('379ebf5d-3a2e-4e57-b22d-5c0e5e51145c', 'So that drivers looking into their rear-view mirrors see the laterally inverted reflection read forward and correctly as ''AMBULANCE''', true, 'fee3d6e2-f9fd-433b-8665-5c4efeaef9ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb517589-2ea1-44cb-b234-9c56cdb8dde6', 'Because of a printing machine mistake', false, 'fee3d6e2-f9fd-433b-8665-5c4efeaef9ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1aa4a4bc-37c2-4d4e-b84f-8675b5a25774', 'To make the van look foreign', false, 'fee3d6e2-f9fd-433b-8665-5c4efeaef9ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22f0b81e-4d1d-4e13-b709-58f44099b67f', 'Because of medical code laws', false, 'fee3d6e2-f9fd-433b-8665-5c4efeaef9ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78fe17fc-1712-4290-aeba-aae2fe21e058', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Medium', 'What happens to the size of a shadow when an opaque object is moved CLOSER to the light source (with the screen position fixed)?', 'Moving closer intercepts a broader angular divergence cone of light rays, casting a larger geometric shadow cone on the screen.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54c156e8-bb33-4533-801f-c7530fd38af5', 'The size of the shadow INCREASES (becomes larger)', true, '78fe17fc-1712-4290-aeba-aae2fe21e058');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4eb4d66-5742-4e49-bb52-bd4087da2535', 'The size of the shadow decreases', false, '78fe17fc-1712-4290-aeba-aae2fe21e058');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('181eead3-2e4c-4afe-b133-1f86b51c9659', 'The shadow turns into an image', false, '78fe17fc-1712-4290-aeba-aae2fe21e058');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08373aec-dab9-4077-9673-bbf0a243efdf', 'The shadow disappears completely', false, '78fe17fc-1712-4290-aeba-aae2fe21e058');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e222bd47-b4f7-475b-89f5-1bb345dc36af', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Medium', 'Why does a high-flying aeroplane or a bird soaring very high in the clear sky NOT cast a visible shadow on the ground?', 'Due to the finite angular size of the Sun, the umbral cone terminates before reaching ground level, dispersing ambient light.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da01a72c-9134-47c6-bc91-91567ca0c2e6', 'Because at great altitudes, the dark central shadow (umbra) tapers off in air and only faint penumbra reaches the ground, making the shadow imperceptible', true, 'e222bd47-b4f7-475b-89f5-1bb345dc36af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8cf0402-1a6a-42b4-be3b-4aef9887727e', 'Because birds are transparent to sunlight', false, 'e222bd47-b4f7-475b-89f5-1bb345dc36af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5386fbad-a60f-492a-b93d-66b130bd1537', 'Because aeroplanes fly faster than light', false, 'e222bd47-b4f7-475b-89f5-1bb345dc36af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a76914f4-a4bd-47ae-89a6-fef84b9b3cc5', 'Because the sky absorbs shadows', false, 'e222bd47-b4f7-475b-89f5-1bb345dc36af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('357c6791-53c7-425a-a2ca-ff66fef123ed', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Medium', 'How does the image formed in a Pinhole Camera change if the tiny pinhole is replaced by a LARGE open hole (e.g. 2 cm diameter)?', 'A large aperture acts as infinite adjacent pinholes, creating overlapping circles of confusion that blur optical fidelity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3864692e-5265-487e-bd83-472b5bd37871', 'The image becomes completely blurred and unclear because multiple overlapping images enter through different points of the large hole', true, '357c6791-53c7-425a-a2ca-ff66fef123ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17fa6d11-5714-4b46-b92c-faf268f835c0', 'The image becomes super sharp and magnified', false, '357c6791-53c7-425a-a2ca-ff66fef123ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eae3c430-126b-49b1-b1e4-d642bbd5cde5', 'The image turns black and white', false, '357c6791-53c7-425a-a2ca-ff66fef123ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91d779ab-c4d9-48f7-90fe-993d14a75a9b', 'No light enters the camera', false, '357c6791-53c7-425a-a2ca-ff66fef123ed');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4566a340-1c92-4c3c-abec-af0798a45696', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Medium', 'Why is an image formed in a pinhole camera always INVERTED (upside down)?', 'Intersecting rectilinear ray trajectories cross linearly at the focal aperture, projecting top points to bottom screen coordinates.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e258cad7-507d-4cae-805f-9a34b1c44837', 'Light rays from the top of the object travel in a straight line through the pinhole to strike the bottom of the screen, while rays from the bottom strike the top', true, '4566a340-1c92-4c3c-abec-af0798a45696');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccb4b5d2-ceca-40d8-82f4-249cfbe9163c', 'Because the camera box is upside down', false, '4566a340-1c92-4c3c-abec-af0798a45696');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a797f402-f63f-494d-a74c-c31987c49b54', 'Because air rotates light rays by 180°', false, '4566a340-1c92-4c3c-abec-af0798a45696');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd2cf3d8-0cb5-44d4-b352-700eb2465b50', 'Because translucent paper inverts gravity', false, '4566a340-1c92-4c3c-abec-af0798a45696');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ebaa3b19-6855-43eb-bbc2-ecda61b15426', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Medium', 'Why is the Moon classified as a NON-LUMINOUS object, despite shining brilliantly in the night sky?', 'Lunar regolith has an albedo of ~0.12, reflecting solar irradiation without generating autonomous luminescent energy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ebbb36b-b4e3-4602-9d5e-ec928d90df3c', 'The Moon does not produce any light through nuclear fusion or heat; it merely reflects incident sunlight striking its rocky dusty surface', true, 'ebaa3b19-6855-43eb-bbc2-ecda61b15426');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61c9de26-b5ce-4966-bb46-0c074bdd078c', 'Because it is covered with ice', false, 'ebaa3b19-6855-43eb-bbc2-ecda61b15426');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06fdd655-ab05-4afd-9fb9-1c689ea405a2', 'Because it only shines for a few hours', false, 'ebaa3b19-6855-43eb-bbc2-ecda61b15426');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('828e3bdd-abaf-4cfc-9349-864030c230ae', 'Because it is too far from Earth', false, 'ebaa3b19-6855-43eb-bbc2-ecda61b15426');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('625f3a68-04a7-47ce-86b6-5bdab6caa023', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Medium', 'What optical device uses two parallel plane mirrors fixed at 45° angles inside a Z-shaped tube to allow a person to see over walls or around corners (used in submarines to view surface ships)?', 'A periscope utilizes twin 45° plane mirrors to reflect incoming horizontal rays downward and then horizontally into the observer''s eye.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42316116-94b6-415a-9969-f918cc8dbd2a', 'Periscope', true, '625f3a68-04a7-47ce-86b6-5bdab6caa023');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04ea203a-781f-45a3-815e-1c382f0e0407', 'Kaleidoscope', false, '625f3a68-04a7-47ce-86b6-5bdab6caa023');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca0a7218-178b-4e2c-b663-3ef525f8a8d8', 'Microscope', false, '625f3a68-04a7-47ce-86b6-5bdab6caa023');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c11e7f0f-1a59-4d3e-8c40-5812ba82d3ca', 'Telescope', false, '625f3a68-04a7-47ce-86b6-5bdab6caa023');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63cb6a2b-4807-402f-8fc6-fd4f4c4483ea', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Medium', 'What biological organism is a natural living LUMINOUS animal that emits glowing yellow-green light through bioluminescence in the dark?', 'Fireflies exhibit enzymatic bioluminescence (luciferin oxidized by luciferase in the presence of ATP) to emit cold light.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28eff95d-8372-42dc-9d9d-0b60ecfc85f7', 'Firefly (Jugnu)', true, '63cb6a2b-4807-402f-8fc6-fd4f4c4483ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('330d615a-e4e0-4777-9c01-66d14841a568', 'Earthworm', false, '63cb6a2b-4807-402f-8fc6-fd4f4c4483ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fdcf3d2-91d9-4a09-be1c-4f1eaebf6215', 'Housefly', false, '63cb6a2b-4807-402f-8fc6-fd4f4c4483ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c843a076-84ce-4fce-92c0-b208eaaeb124', 'Butterfly', false, '63cb6a2b-4807-402f-8fc6-fd4f4c4483ea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03941e4c-3e1d-434c-96ae-b00169d1595a', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Medium', 'Can a transparent glass sheet cast a dark, distinct shadow on the wall?', 'High optical transmittance prevents significant light blockage, resulting in no discernible umbral shadow.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81592568-7c92-4365-9b44-9923b8dfcc12', 'No, because transparent glass allows almost all light rays to pass directly through without obstruction', true, '03941e4c-3e1d-434c-96ae-b00169d1595a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68d95900-c16b-44b9-99c0-b6faf0e4ddd2', 'Yes, exactly like a thick wooden door', false, '03941e4c-3e1d-434c-96ae-b00169d1595a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95d88081-b75e-4f91-bde0-a80ddb55d2ca', 'Yes, if the light is turned off', false, '03941e4c-3e1d-434c-96ae-b00169d1595a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a9d9b86-2788-44b2-b4b6-1d7c5aacf1e0', 'Yes, if the glass is round', false, '03941e4c-3e1d-434c-96ae-b00169d1595a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb05eb7b-5219-45d6-865d-b0104872e6aa', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Medium', 'How do the shadows of objects cast by the Sun change in length during the course of a clear sunny day?', 'Shadow length L = h / tan(θ), where θ is solar elevation angle; low morning/evening solar altitudes yield elongated shadows.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('728e779a-f95b-4997-a44c-e3f1731ec7e7', 'Shadows are longest in the early morning and late evening (when Sun is low on horizon), and shortest at solar noon (when Sun is highest overhead)', true, 'bb05eb7b-5219-45d6-865d-b0104872e6aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dceaf08-47a3-492b-b48f-851a432eb560', 'Shadows are longest at noon', false, 'bb05eb7b-5219-45d6-865d-b0104872e6aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4e18d27-2856-4604-9f14-ec47c6723c31', 'Shadow length remains exactly constant all day', false, 'bb05eb7b-5219-45d6-865d-b0104872e6aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7420859b-7e56-47ee-b1d8-19bd4a002d0a', 'Shadows disappear in morning', false, 'bb05eb7b-5219-45d6-865d-b0104872e6aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9ef4d16-f635-470f-a646-1bcfebc66b29', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Medium', 'Why can we NOT see anything when entering a pitch-dark room without any light source?', 'Photoreceptors in the retina require incoming reflected photons to trigger neuro-electrical optic nerve impulses.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6dafbc46-bc86-42f2-8de2-f8083d3bb0eb', 'Our eyes do not emit light; vision requires light from a luminous source to reflect off objects and enter our eyes', true, 'a9ef4d16-f635-470f-a646-1bcfebc66b29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b82a76c-e054-4da3-bbf4-420d0d0b1505', 'Because dark rooms make human eyes close automatically', false, 'a9ef4d16-f635-470f-a646-1bcfebc66b29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26ebf89d-737f-4869-8e22-a2190ecb7b81', 'Because darkness turns objects invisible permanently', false, 'a9ef4d16-f635-470f-a646-1bcfebc66b29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('909197a9-1db3-44de-9802-8942389491a0', 'Because light rays freeze in dark rooms', false, 'a9ef4d16-f635-470f-a646-1bcfebc66b29');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('433257e9-d887-43be-9a22-2959e9772ae1', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Medium', 'What is an Eclipse (Solar or Lunar) in astronomical science?', 'Eclipses are large-scale celestial shadow events governed by rectilinear light propagation across astronomical orbits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7a5108b-2690-4b7c-b1a2-bbecd619d90a', 'A colossal natural shadow phenomenon formed in space when an astronomical body (Moon or Earth) blocks sunlight from reaching another body', true, '433257e9-d887-43be-9a22-2959e9772ae1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66f52f75-4605-4c5a-8e46-bee0a06cbcca', 'A magical storm on the Sun', false, '433257e9-d887-43be-9a22-2959e9772ae1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f829b493-434b-4951-96f4-38c2be534a9b', 'The Moon exploding', false, '433257e9-d887-43be-9a22-2959e9772ae1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db708c3c-80c8-45f6-a7a9-3719c40d9465', 'The Sun turning off for a few minutes', false, '433257e9-d887-43be-9a22-2959e9772ae1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7393564c-baf5-4e31-87d3-771362168c2b', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a8a1076-1540-424c-8476-f98e053dea02', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '7393564c-baf5-4e31-87d3-771362168c2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b27d120d-98e1-42ca-b242-6c0a1cad94d4', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '7393564c-baf5-4e31-87d3-771362168c2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('594f5df5-85d9-47d2-9e8c-1cad4adb3dfc', '(A) is true, but (R) is false.', false, '7393564c-baf5-4e31-87d3-771362168c2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72cdca0c-aba6-4647-96e0-6cc31ecb8b06', '(A) is false, but (R) is true.', false, '7393564c-baf5-4e31-87d3-771362168c2b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9eb6c9ed-8496-4b91-be44-7c33253bcd36', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Hard', 'Spot the IMPOSTER in the following group of optical materials classified as Translucent:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7936230-a2a0-401b-8769-0232415332a0', 'Butter paper', false, '9eb6c9ed-8496-4b91-be44-7c33253bcd36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e67b120c-9f63-4b6c-b5ba-891c18ae3744', 'Frosted glass', false, '9eb6c9ed-8496-4b91-be44-7c33253bcd36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ad4eec0-1520-4c2d-92b3-8bc8986076b1', 'Oily tissue paper', false, '9eb6c9ed-8496-4b91-be44-7c33253bcd36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af54e8d8-388a-42a6-aa48-d3def691ad26', 'Clear optical window glass', true, '9eb6c9ed-8496-4b91-be44-7c33253bcd36');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e7b518f4-57e0-43be-a3c1-00286dba180b', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Hard', 'A student holds a circular disc between a point source of light and a white screen. How can the circular disc cast an OVAL or ELLIPTICAL shadow on the screen?', 'Projective geometry: the cross-sectional silhouette of an inclined circle projected along rectilinear rays onto a planar screen forms an ellipse.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('290a9f64-08db-40c5-bdf2-c45d4e6a392c', 'By tilting the disc at an angle (oblique orientation) relative to the incident light beam', true, 'e7b518f4-57e0-43be-a3c1-00286dba180b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f384ec9-c8d9-4b65-a94b-3f8ea3bb12b5', 'By painting the disc red', false, 'e7b518f4-57e0-43be-a3c1-00286dba180b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97f9eb17-3ea9-45f3-85cf-b42275003e08', 'By moving the screen further away', false, 'e7b518f4-57e0-43be-a3c1-00286dba180b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58cdc79d-39d9-4b8d-88b8-0a08812d2698', 'A circular disc can never cast an elliptical shadow', false, 'e7b518f4-57e0-43be-a3c1-00286dba180b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e016709-c15c-4a7e-b39a-42847c09e315', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Hard', 'Match Column I (Optical Concepts) with Column II (Definitions / Examples):
(a) Luminous body      -> (i) Bouncing of light rays from smooth surface
(b) Translucent body   -> (ii) Emits its own light (Sun, Electric bulb)
(c) Rectilinear motion -> (iii) Transmits light partially (Butter paper)
(d) Reflection         -> (iv) Light travels strictly along straight paths', 'Luminous = emits light; Translucent = partial transmission; Rectilinear = straight lines; Reflection = bouncing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('617dcd76-d55f-4894-9d14-f4c458679479', 'a-(ii), b-(iii), c-(iv), d-(i)', true, '5e016709-c15c-4a7e-b39a-42847c09e315');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24192769-2df5-454e-a545-d7773241d25a', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '5e016709-c15c-4a7e-b39a-42847c09e315');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64477d2d-7751-4ebb-b730-d4428c497ab0', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '5e016709-c15c-4a7e-b39a-42847c09e315');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0be20a12-c423-4461-b858-59be34bf9981', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '5e016709-c15c-4a7e-b39a-42847c09e315');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('417565f0-91b9-49b4-afc6-5b9c651f1b15', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Hard', 'Read the statements regarding shadows:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5eaacb37-4f6e-42f7-8182-f7ed7df37835', 'Statements 1 and 3 only', true, '417565f0-91b9-49b4-afc6-5b9c651f1b15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8d8ce84-815e-4176-91b0-c4f3e66ae88e', 'Statements 1 and 2 only', false, '417565f0-91b9-49b4-afc6-5b9c651f1b15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('816b4b96-4fc7-478d-a2ab-a9af9b41f71c', 'Statements 2 and 3 only', false, '417565f0-91b9-49b4-afc6-5b9c651f1b15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96edbe7c-5f54-48df-8fdc-12614f3fe90c', 'All Statements 1, 2, and 3', false, '417565f0-91b9-49b4-afc6-5b9c651f1b15');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8a0ac1b-0880-4848-b83e-f0a4c9348d37', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Hard', 'What is the physical nature of the two regions of a shadow cast by an extended light source (like a large frosted bulb)?', 'An extended source generates a total geometric shadow cone (umbra) flanked by an annular partial shadow cone (penumbra).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df51a009-23d6-41cf-9576-ed3839ecafbe', 'Umbra (the central completely dark region receiving zero light) and Penumbra (the outer partially illuminated grey region receiving partial light)', true, 'd8a0ac1b-0880-4848-b83e-f0a4c9348d37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d878928f-497f-451d-9e8b-f154c1c89dc0', 'North pole and South pole', false, 'd8a0ac1b-0880-4848-b83e-f0a4c9348d37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17a4c6b6-fc85-450b-97a1-68adc88a402e', 'Red zone and Blue zone', false, 'd8a0ac1b-0880-4848-b83e-f0a4c9348d37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb2f32f5-663a-4841-911e-e7232626f749', 'Reflection and Refraction', false, 'd8a0ac1b-0880-4848-b83e-f0a4c9348d37');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('247ce1e0-b22a-4393-95c7-d013dbf8f745', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Hard', 'If you stand 2 metres in front of a flat plane mirror, what is the total distance between YOU and your virtual IMAGE in the mirror?', 'Object distance = Image distance (d_o = d_i = 2 m). Total separation between object and image = 2 + 2 = 4 metres.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fcae7ad-0840-4a49-a06f-db31d7e08b5a', '4 metres (2 m in front + 2 m behind the mirror)', true, '247ce1e0-b22a-4393-95c7-d013dbf8f745');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5114a87-eb0c-4139-9da3-db086cfd6ff0', '2 metres', false, '247ce1e0-b22a-4393-95c7-d013dbf8f745');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc62f0bb-3c8e-4ef0-bff4-80379f99c6ef', '1 metre', false, '247ce1e0-b22a-4393-95c7-d013dbf8f745');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b39c068b-a85b-48c4-91f5-b6c966a3b715', '0 metres', false, '247ce1e0-b22a-4393-95c7-d013dbf8f745');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b14e28b7-82f7-49e3-a2e0-4afe1ce805eb', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Hard', 'Consider four objects:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42b7caac-aa91-4dab-9ae2-61cdc1157077', 'Object 3 (Oiled paper)', true, 'b14e28b7-82f7-49e3-a2e0-4afe1ce805eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78c2b223-13b5-472b-b306-a47c7b2dfa51', 'Object 1', false, 'b14e28b7-82f7-49e3-a2e0-4afe1ce805eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9758b73-d7cd-4b15-9c9e-1dfce7381d99', 'Object 2', false, 'b14e28b7-82f7-49e3-a2e0-4afe1ce805eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('735c612f-9b8a-44dd-bdfc-bc38dfe97940', 'Object 4', false, 'b14e28b7-82f7-49e3-a2e0-4afe1ce805eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8fe885b8-2c5c-4f62-9d3c-1ac9baccec20', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Hard', 'Why does a rough unpolished surface (like a chalk wall or unpolished wood) NOT form a clear mirror image, despite reflecting light into our eyes?', 'Specular reflection from planar mirrors maintains parallel wavefronts; microscopic rugosity produces diffuse multi-directional scattering.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1a93552-ee55-4955-94c9-7d2acf39102f', 'Microscopic surface irregularities cause Diffuse (Irregular) Reflection, scattering reflected light rays in all random directions rather than parallel reflection', true, '8fe885b8-2c5c-4f62-9d3c-1ac9baccec20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('494b3c2f-b2ac-4cbc-8780-0b1d716538a1', 'Because chalk absorbs all light completely', false, '8fe885b8-2c5c-4f62-9d3c-1ac9baccec20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79ad8dd0-6ffe-43d1-b051-fe09d653fee3', 'Because rough surfaces destroy photons', false, '8fe885b8-2c5c-4f62-9d3c-1ac9baccec20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63072211-8ea4-437c-94bd-a3a4801fe7fd', 'Because chalk is transparent', false, '8fe885b8-2c5c-4f62-9d3c-1ac9baccec20');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d85a4b6-2960-4ea5-ac38-c09b775c697e', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Hard', 'An experimenter constructs a pinhole camera with an adjustable sliding box. What happens to the projected image on the screen when the screen is moved FURTHER away from the pinhole?', 'Linear divergence magnifies image height h_i = h_o · (v/u), while photon flux spreads over a greater surface area, reducing luminous illuminance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b3c18aa-3f7d-4099-9bc9-931c9956361f', 'The image becomes LARGER in size but FAINTER in brightness', true, '5d85a4b6-2960-4ea5-ac38-c09b775c697e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d76fa6a3-0441-4fa8-8333-9d8b765e3c88', 'The image becomes smaller and brighter', false, '5d85a4b6-2960-4ea5-ac38-c09b775c697e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e90765c3-1471-4f71-ba7e-cf95d0811ac2', 'The image turns erect', false, '5d85a4b6-2960-4ea5-ac38-c09b775c697e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f14f109-f538-4b08-95a6-ea332ff8b191', 'The image disappears completely', false, '5d85a4b6-2960-4ea5-ac38-c09b775c697e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c89fa4b1-d5d5-4792-b217-81571de6c4fd', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Hard', 'What is the speed of light in vacuum (c), representing the absolute cosmic speed limit in physics?', 'c = 299,792,458 m/s (~3 × 10⁸ m/s), traversing vacuum from Sun to Earth in ~8 minutes and 20 seconds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57cd4559-026e-4d50-bf3e-138082e97ebf', 'Approximately 300,000 kilometres per second (3 × 10⁸ m/s)', true, 'c89fa4b1-d5d5-4792-b217-81571de6c4fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38eebf55-058f-4cc5-8020-c68c3f682a6d', '330 metres per second', false, 'c89fa4b1-d5d5-4792-b217-81571de6c4fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eff8b49e-048b-4ba7-a72a-bf2f1f97d6dd', '1,000 km/h', false, 'c89fa4b1-d5d5-4792-b217-81571de6c4fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8df07d42-c56e-4c8a-b285-2a8e47dbdcc6', '30,000 km/s', false, 'c89fa4b1-d5d5-4792-b217-81571de6c4fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('44b5c91e-5101-4dc0-ae0d-74aef4d8cb9e', 'Class 6', 'Science', 'Chapter 8: Light, Shadows and Reflections', 'Hard', 'Why is an image formed in a plane mirror called a ''VIRTUAL Image'' in physics?', 'Virtual images are formed by the imaginary backwards extrapolation of diverging reflected rays and cannot be projected on a real screen.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29acdcac-48c2-4615-994b-639342c4b6cb', 'Because reflected light rays only appear to diverge from a point behind the mirror and cannot be captured or focused on a physical screen placed there', true, '44b5c91e-5101-4dc0-ae0d-74aef4d8cb9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab2a9417-a062-40a2-b93c-a472b8f6bcc3', 'Because it exists only in computer software', false, '44b5c91e-5101-4dc0-ae0d-74aef4d8cb9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2018973b-30c6-45ef-b09b-c96bb08ed034', 'Because it is fake and painted', false, '44b5c91e-5101-4dc0-ae0d-74aef4d8cb9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e491cfb-e5f8-43a8-8de4-1e504a7a9ba5', 'Because it disappears when we blink', false, '44b5c91e-5101-4dc0-ae0d-74aef4d8cb9e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2baa2b32-2ff5-4c1b-bc9c-13d8720abdbf', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Easy', 'In the decimal system, what does the first place value immediately to the RIGHT of the decimal point represent?', 'The first digit to the right of the decimal point has place value 1/10 (Tenths).', NOW()) ON CONFLICT DO NOTHING;
