INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82cff3a1-3cfc-4025-a101-90b9e423cb5d', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Medium', 'Sunita bought 5 kg 75 g of potatoes, 2 kg 500 g of tomatoes, and 1 kg 50 g of onions. What is the total weight of her purchases in kilograms?', '5.075 kg + 2.500 kg + 1.050 kg = 8.625 kg.', NOW()) ON CONFLICT DO NOTHING;
