INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30196a55-847e-4f23-9c93-587cac33258e', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Medium', 'Aakash bought vegetables weighing 10 kg in total. Out of this, 3 kg 500 g is onions, 2 kg 75 g is tomatoes, and the rest is potatoes. What is the weight of the potatoes?', 'Total other veggies = 3.500 + 2.075 = 5.575 kg. Potatoes = 10.000 - 5.575 = 4.425 kg.', NOW()) ON CONFLICT DO NOTHING;
