INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e80fec4-196b-47bc-9a5a-01534bdc4664', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Hard', 'Arrange the following decimals in DESCENDING (decreasing) order: 2.2, 2.02, 2.22, 2.002, 2.202', 'Aligning 3 decimal places: 2.220 > 2.202 > 2.200 > 2.020 > 2.002.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('164955a6-2fd1-432b-9ba6-b3c2b84de777', '2.22 > 2.202 > 2.2 > 2.02 > 2.002', true, '5e80fec4-196b-47bc-9a5a-01534bdc4664');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3743dd78-ad62-4a98-8b23-dceafe2d702f', '2.2 > 2.22 > 2.202 > 2.02 > 2.002', false, '5e80fec4-196b-47bc-9a5a-01534bdc4664');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36836377-8382-4b72-8dd2-7ad4d9002287', '2.002 > 2.02 > 2.2 > 2.202 > 2.22', false, '5e80fec4-196b-47bc-9a5a-01534bdc4664');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('300887c2-6a2e-4157-bbd3-a8b07c9a4b61', '2.22 > 2.2 > 2.202 > 2.02 > 2.002', false, '5e80fec4-196b-47bc-9a5a-01534bdc4664');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1110619e-e602-4f53-93e9-61eb72e6f1fc', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Hard', 'A wire of length 20 m is cut into three pieces. The first piece is 4.35 m long and the second piece is 8.7 m long. What is the length of the third piece?', '4.35 + 8.70 = 13.05 m. Remaining = 20.00 - 13.05 = 6.95 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dc7cec8-fcdd-4e69-bfee-b7b677225423', '6.95 m (20.00 - (4.35 + 8.70) = 20.00 - 13.05 = 6.95 m)', true, '1110619e-e602-4f53-93e9-61eb72e6f1fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('520b4344-71c1-4706-ae49-7f476cd16d5a', '7.95 m', false, '1110619e-e602-4f53-93e9-61eb72e6f1fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9d4f303-2941-4549-8644-7da764910db1', '6.05 m', false, '1110619e-e602-4f53-93e9-61eb72e6f1fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db103998-8de1-4005-956d-7442b88a322b', '7.05 m', false, '1110619e-e602-4f53-93e9-61eb72e6f1fc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da7a6f3a-4816-45e8-b4a5-f73f02c37f7e', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Hard', 'What number should be added to the sum of 18.05 and 12.9 to get 40?', '18.05 + 12.90 = 30.95. Required addend = 40.00 - 30.95 = 9.05.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd6b5ad3-2735-4782-92e4-b3f4a6185363', '9.05 (40.00 - (18.05 + 12.90) = 40.00 - 30.95 = 9.05)', true, 'da7a6f3a-4816-45e8-b4a5-f73f02c37f7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d2067d1-be34-4109-9ce3-99469ef56c7a', '8.95', false, 'da7a6f3a-4816-45e8-b4a5-f73f02c37f7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('364f56f1-8754-475e-97e1-d7d0bd86198e', '9.15', false, 'da7a6f3a-4816-45e8-b4a5-f73f02c37f7e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55996ed2-5bb2-4530-a781-8af55563ef20', '10.05', false, 'da7a6f3a-4816-45e8-b4a5-f73f02c37f7e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca3f981a-3f27-438a-bdd8-3354cfa2bba6', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Hard', 'How is the decimal 1.7 represented accurately on a number line?', '1.7 = 1 + 7/10, situated 7/10ths of the distance from 1 towards 2 on the number line.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61d4fe2b-e194-4ca6-bc72-c14fde159410', 'Between integers 1 and 2, dividing the unit length into 10 equal subdivisions and marking the 7th subdivision from 1', true, 'ca3f981a-3f27-438a-bdd8-3354cfa2bba6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbf18189-faf4-420e-80ad-1b6af50217a7', 'Between 0 and 1 at 7th subdivision', false, 'ca3f981a-3f27-438a-bdd8-3354cfa2bba6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fcf051f-0e41-43d2-91e9-0d583beffccf', 'Between 7 and 8', false, 'ca3f981a-3f27-438a-bdd8-3354cfa2bba6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ba61ba8-9824-4c7b-bbd8-346c3d5b410b', 'Directly at 1', false, 'ca3f981a-3f27-438a-bdd8-3354cfa2bba6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ddf1ebf3-1a8e-4d2f-9fed-5c2d64bf5547', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Hard', 'What is the expanded form of the decimal number 253.408 in place-value notation?', '200 + 50 + 3 + 4/10 + 0/100 + 8/1000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bc35ec2-c5a9-4ca1-a6a0-5a7de1943271', '2 × 100 + 5 × 10 + 3 × 1 + 4 × (1/10) + 0 × (1/100) + 8 × (1/1000)', true, 'ddf1ebf3-1a8e-4d2f-9fed-5c2d64bf5547');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d185564-9e84-4798-ada9-3a41b97c09bb', '2 × 100 + 5 × 10 + 3 × 1 + 4 × 10 + 8 × 100', false, 'ddf1ebf3-1a8e-4d2f-9fed-5c2d64bf5547');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ea2a2f1-f1ae-4b88-b88b-9f141177e4fa', '253 + 408/100', false, 'ddf1ebf3-1a8e-4d2f-9fed-5c2d64bf5547');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d26db43b-c497-42f6-9f01-e63925dd5159', '200 + 50 + 3 + 4/100 + 8/10', false, 'ddf1ebf3-1a8e-4d2f-9fed-5c2d64bf5547');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff1b50ab-ce46-46e9-af35-9e3840f6bd75', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Hard', 'Express 725 paise as rupees, 485 cm as metres, and 3050 g as kilograms respectively in Decimals:', '725 paise = ₹7.25; 485 cm = 4.85 m; 3050 g = 3.050 kg.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('916482fb-0e62-4dad-9994-9faca730807e', '₹7.25 ; 4.85 m ; 3.050 kg', true, 'ff1b50ab-ce46-46e9-af35-9e3840f6bd75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4637806-a26e-4422-a51a-ecab46962391', '₹72.5 ; 48.5 m ; 30.5 kg', false, 'ff1b50ab-ce46-46e9-af35-9e3840f6bd75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aca3754f-7d75-457d-8baa-51cabb8ab1f9', '₹0.725 ; 0.485 m ; 0.305 kg', false, 'ff1b50ab-ce46-46e9-af35-9e3840f6bd75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73c49eae-0f9c-4ec9-ac65-e1052b2a7b24', '₹7.25 ; 48.5 m ; 3.5 kg', false, 'ff1b50ab-ce46-46e9-af35-9e3840f6bd75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc7db471-3029-4aea-b96b-a156b2ed0ccb', 'Class 6', 'Mathematics', 'Chapter 8: Decimals', 'Hard', 'A container has 15.5 litres of milk. If 3.75 litres is used for tea and 6.8 litres is used for sweets, how much milk is left in the container?', 'Used = 3.75 + 6.80 = 10.55 L. Remaining = 15.50 - 10.55 = 4.95 litres.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a935374-73de-43db-935f-9845f4a5b52c', '4.95 litres (15.50 - (3.75 + 6.80) = 15.50 - 10.55 = 4.95 L)', true, 'fc7db471-3029-4aea-b96b-a156b2ed0ccb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e19e93c-b467-431b-9d15-f7c89a09619e', '5.05 L', false, 'fc7db471-3029-4aea-b96b-a156b2ed0ccb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0933341-1a4e-4327-a1c5-4a3d8bf14da1', '4.85 L', false, 'fc7db471-3029-4aea-b96b-a156b2ed0ccb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9577323c-5f03-4bb2-94d6-121a21f48021', '5.95 L', false, 'fc7db471-3029-4aea-b96b-a156b2ed0ccb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07b56e96-a270-4877-b218-5feb41fc2465', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'On which festive occasion was the grand village fair held every year in Rasheed''s village?', 'There was a big fair in Rasheed''s village every year on the occasion of Eid, drawing tradesmen from all over.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cf64fcd-05d7-41ee-ad31-44897f1dd24b', 'Eid festival (which lasted many days)', true, '07b56e96-a270-4877-b218-5feb41fc2465');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92d30194-3a52-404c-84d6-8764a2525887', 'Diwali', false, '07b56e96-a270-4877-b218-5feb41fc2465');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e4d4ec5-57b3-4a6c-ad64-13e7e25c1916', 'Holi', false, '07b56e96-a270-4877-b218-5feb41fc2465');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0ef8e07-b9ba-496a-86b4-2cd9eff3db6b', 'Christmas', false, '07b56e96-a270-4877-b218-5feb41fc2465');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('85002f59-10d5-49cc-9767-5023f5dd5406', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'Who accompanied Rasheed to the Eid fair along with the domestic helper Bhaiya?', 'Uncle took Rasheed to the fair, along with their domestic helper Bhaiya.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c5ac2e0-0ead-4750-b56c-2947ff09629f', 'His Uncle', true, '85002f59-10d5-49cc-9767-5023f5dd5406');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c3f6d59-f9ca-4ead-a98a-6fd37b109bba', 'His father', false, '85002f59-10d5-49cc-9767-5023f5dd5406');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04be8cb6-1d10-417b-af9d-c18637132d56', 'His grandfather', false, '85002f59-10d5-49cc-9767-5023f5dd5406');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('868225a5-031a-4a72-8483-7831c9183bff', 'His elder brother', false, '85002f59-10d5-49cc-9767-5023f5dd5406');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4ddca14e-5acc-4a6f-93e9-5a7828dbaaa9', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'What strict warning did Uncle give Rasheed before leaving him to meet some friends at the fair?', 'Uncle strictly cautioned Rasheed neither to buy anything nor to wander away while he was away.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24bba641-992c-4e3d-8e0f-73e2778aacf7', 'Not to buy anything and not to go too far away in his absence', true, '4ddca14e-5acc-4a6f-93e9-5a7828dbaaa9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('512d48a0-1499-4b6c-87fd-cb1ec3bc30b1', 'Not to eat sweets', false, '4ddca14e-5acc-4a6f-93e9-5a7828dbaaa9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bfab86c-a97e-4f4b-acf5-94a03d85b569', 'Not to ride the merry-go-round', false, '4ddca14e-5acc-4a6f-93e9-5a7828dbaaa9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db6c285d-2438-4864-8a10-8e3cf9a1aa26', 'Not to talk to anyone', false, '4ddca14e-5acc-4a6f-93e9-5a7828dbaaa9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56fd6a3a-5438-4021-a516-e80e23a9cccb', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'What was the name of the shop that caught Rasheed''s attention with numbered discs?', 'The stall was called ''Lucky Shop'', run by a middle-aged shopkeeper who seemed neither too smart nor too lazy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e744015-3dc9-47f1-89aa-f9edf8620fe0', 'Lucky Shop', true, '56fd6a3a-5438-4021-a516-e80e23a9cccb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc1ce477-04c2-4f32-a3c8-63c0aea6da29', 'Magic Shop', false, '56fd6a3a-5438-4021-a516-e80e23a9cccb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53a8b709-fcb9-4986-a842-f0fd5d32c48e', 'Toy Bazaar', false, '56fd6a3a-5438-4021-a516-e80e23a9cccb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aee2fdb3-1b37-458b-ade2-55f0b4fe16b9', 'Gift Corner', false, '56fd6a3a-5438-4021-a516-e80e23a9cccb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84a01779-596a-4f35-8b3b-19c762a70acc', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'How much did it cost to try one''s luck by picking six numbered discs at the Lucky Shop?', 'The rule required paying 50 paise to choose six numbered discs, summing the numbers to claim the matching article.', NOW()) ON CONFLICT DO NOTHING;
