INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03fba96f-a41e-4f07-b142-81daf0d6d506', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'What happened to all of Rasheed''s pocket money as he kept playing in the hope of winning a big prize?', 'Gambling repeatedly in vain hope, Rasheed lost all his money to the cunning shopkeeper.', NOW()) ON CONFLICT DO NOTHING;
