INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('de620b64-d5f6-44ea-9e5f-a981a830f942', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'In the supplementary story ''A Pact with the Sun'', what was Saeeda''s ailing mother suffering from for a long time?', 'Saeeda''s mother had been suffering from chronic fever, body ache, and cough, confined to a dark dingy room.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e86b817-5cb1-481e-9649-b16c11e80390', 'Fever, body ache, joint pain, and chronic unhealed cough/illness', true, 'de620b64-d5f6-44ea-9e5f-a981a830f942');
