INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('607c333a-c150-422c-bb2b-67ced77c93cc', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'What foolish advice had orthodox quacks given to Saeeda''s mother before the wise specialist doctor arrived?', 'Quacks strictly forbade fresh air, sunshine, and normal food, worsening her physical deterioration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d9b1613-c85d-4eb3-ac0a-f59c06d03720', 'To stay locked in a dark, dingy small room with closed doors/windows, deprived of fresh air and sunlight', true, '607c333a-c150-422c-bb2b-67ced77c93cc');
