INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7c96ce7-448c-4264-a1d8-9a119687a854', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'What crucial life-saving prescription did the learned specialist physician give to Saeeda''s mother?', 'The doctor prescribed normal diet plus one hour of daily morning sunshine and fresh air as essential medicine.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('544cdebd-e345-4a13-b988-c6aa2b46d071', 'To move into a larger room with open windows and sit in the bright morning sunshine for an hour every day while breathing fresh air', true, 'd7c96ce7-448c-4264-a1d8-9a119687a854');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4871634d-5d6d-4d95-b382-6c0e55296095', 'To take 50 pills a day in a dark room', false, 'd7c96ce7-448c-4264-a1d8-9a119687a854');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5a20076-9271-4146-a437-846bce59584a', 'To stay in bed without food', false, 'd7c96ce7-448c-4264-a1d8-9a119687a854');
