INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4717c05-960b-4505-adf2-bad8cf59e451', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Easy', 'To whom did little Saeeda make a heartfelt secret pact/prayer in the courtyard in the evening?', 'Saeeda made a solemn pact with the evening sunrays to arrive the following morning with warmth for her mother.', NOW()) ON CONFLICT DO NOTHING;
