INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('95848b97-f9fd-4d44-ac5a-3d0f91a705c1', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'How did Uncle react when he saw Rasheed looking utterly sad and dejected with an empty pocket?', 'Uncle consoled Rasheed with gifts and explained how the shopkeeper tricked naive customers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79af3bfc-264f-42a6-a86c-bc795f56de26', 'Uncle smiled kindly, bought him a beautiful umbrella, biscuits, sweets, and other gifts, and gently explained the reality of the game', true, '95848b97-f9fd-4d44-ac5a-3d0f91a705c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('106a2452-844d-4aab-ab0f-a516c97924d0', 'Uncle scolded and beat him harshly', false, '95848b97-f9fd-4d44-ac5a-3d0f91a705c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5cf1738-5f47-45a7-8add-90a87b54c713', 'Uncle punished Bhaiya', false, '95848b97-f9fd-4d44-ac5a-3d0f91a705c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3abe3b33-6166-466c-84e6-33106a10b46f', 'Uncle complained to the police', false, '95848b97-f9fd-4d44-ac5a-3d0f91a705c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75881e2e-ccee-4f3d-bb1d-922a2b686f14', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'What secret truth did Uncle reveal to Rasheed about the old man and the boy who won expensive prizes at the Lucky Shop?', 'Uncle revealed that the ''winners'' were shills working in league with the shopkeeper to deceive gullible spectators.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d4a8915-6f32-4fc0-8231-3ec633bda62b', 'They were all accomplices and friends of the shopkeeper, playing rigged tricks to tempt greedy onlookers into gambling away their money', true, '75881e2e-ccee-4f3d-bb1d-922a2b686f14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('278f023e-3d33-47b6-bf54-9ed97295512f', 'They were the luckiest people in the world', false, '75881e2e-ccee-4f3d-bb1d-922a2b686f14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b6c08dd-934d-456c-a083-031fcd52a110', 'They were professional magicians', false, '75881e2e-ccee-4f3d-bb1d-922a2b686f14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01b40909-1e08-4c45-a320-1ac8bb1aa85e', 'They owned the shop', false, '75881e2e-ccee-4f3d-bb1d-922a2b686f14');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bc013e2f-2e94-4892-9277-700034ac2f5b', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'What important life lesson did Uncle teach Rasheed about ''Bad Luck'' versus ''Foolishness''?', 'Uncle advised him to forget the incident and realize that tricksters exploit greed rather than genuine luck.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b697e98-aaa0-4016-94fc-007ddc159b7f', 'It was NOT bad luck at all, but pure gullibility and foolishness; one should never fall prey to get-rich-quick gambles or rigged games of chance', true, 'bc013e2f-2e94-4892-9277-700034ac2f5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b50d61a-8147-47a4-b44e-1207eac241ad', 'Rasheed was born under an unlucky star', false, 'bc013e2f-2e94-4892-9277-700034ac2f5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1da032eb-db02-4960-8f5f-4279b391b580', 'Fairs should be banned completely', false, 'bc013e2f-2e94-4892-9277-700034ac2f5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dd671b2-c5cb-4eae-af36-d124e56470d2', 'Children should never carry umbrellas', false, 'bc013e2f-2e94-4892-9277-700034ac2f5b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4a83e44-04ef-4fb2-8848-d2f695a49bbb', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'Why were the sunrays determined to break through the thick, dark army of clouds the next morning despite the Sun King''s hesitation?', 'Bound by their sacred promise to Saeeda, the loyal sunrays pierced the overcast clouds to fulfill their word.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8861f7b9-e6d1-4eb3-a7cc-684a8ccf4f43', 'Because they had given their word of honour to little Saeeda, and breaking their promise would make them liars in the eyes of humans', true, 'e4a83e44-04ef-4fb2-8848-d2f695a49bbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('577880fb-ec58-48e5-9d3f-bdac923bb804', 'Because they hated clouds', false, 'e4a83e44-04ef-4fb2-8848-d2f695a49bbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3997f890-eee3-48b3-acc6-fe9dbe31cc36', 'Because they wanted to burn the earth', false, 'e4a83e44-04ef-4fb2-8848-d2f695a49bbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('322aa4ae-1dde-4d8c-94af-1ed789717152', 'Because they were cold', false, 'e4a83e44-04ef-4fb2-8848-d2f695a49bbb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6cd240f6-b594-4ce6-af55-4666a00a9959', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'What happened when the bright, warm morning sunrays bathed Saeeda''s mother as she lay in the courtyard?', 'Sunlight and fresh air rejuvenated her immune system, bringing swift, joyful physical recovery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edf85c65-674e-49f1-8c2b-90beb80d324a', 'Her pale face glowed with fresh vitality, her eyes sparkled, tears of joy welled up, and she recovered her health rapidly', true, '6cd240f6-b594-4ce6-af55-4666a00a9959');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79c64bf7-7d55-4c2b-b2b0-1af8e1056bc1', 'She felt too hot and went inside', false, '6cd240f6-b594-4ce6-af55-4666a00a9959');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b29326c8-3972-4d19-86e8-e0c4bcc39704', 'She got angry at Saeeda', false, '6cd240f6-b594-4ce6-af55-4666a00a9959');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a1f6f63-f86a-49e4-84aa-e943bf58a264', 'Her fever increased', false, '6cd240f6-b594-4ce6-af55-4666a00a9959');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82b32dfd-49cc-4d56-bfb7-1c086ba19d79', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'What central scientific and health message is conveyed in ''A Pact with the Sun'' by Zakir Husain?', 'The story highlights the therapeutic power of sunshine (Vitamin D) and fresh air over confining darkness.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2bfe995-f3ca-48e2-964f-85cc12fcf5ac', 'Sunlight and fresh open air are nature''s supreme indispensable medicines for human vitality, mental health, and physical healing', true, '82b32dfd-49cc-4d56-bfb7-1c086ba19d79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b4c817c-eb83-4d4b-b515-8751056aab62', 'Medicine tablets are the only cure for everything', false, '82b32dfd-49cc-4d56-bfb7-1c086ba19d79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b66602b-6145-4837-9496-673cc667f856', 'Windows should always be kept shut', false, '82b32dfd-49cc-4d56-bfb7-1c086ba19d79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f26cbbb-dd04-4d35-bb15-ad4b26f097cc', 'Sunlight is harmful for sick people', false, '82b32dfd-49cc-4d56-bfb7-1c086ba19d79');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5cf2e8d3-0ba6-4b9e-8eaf-fb031b5b5fc2', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'Who is the eminent author of the original Urdu classic story ''A Pact with the Sun''?', 'Dr. Zakir Husain, eminent educationist and 3rd President of India, penned this allegorical children''s classic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('179c94cc-26d2-4e25-a3f9-df24fb7cd36d', 'Dr. Zakir Husain (former President of India and renowned educationist)', true, '5cf2e8d3-0ba6-4b9e-8eaf-fb031b5b5fc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e511c7b-e4af-4811-9dd9-05933e6f38e5', 'Munshi Premchand', false, '5cf2e8d3-0ba6-4b9e-8eaf-fb031b5b5fc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33e78db6-cf2f-41a4-96df-ea40845a231a', 'Rabindranath Tagore', false, '5cf2e8d3-0ba6-4b9e-8eaf-fb031b5b5fc2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df0633ea-da05-4d94-a763-6ddf6590bd1d', 'Ismat Chughtai', false, '5cf2e8d3-0ba6-4b9e-8eaf-fb031b5b5fc2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('51801ccd-9070-48c5-b39b-81805a08c3c6', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'In the poem ''Vocation'' by Rabindranath Tagore, what three workers does the schoolboy observe and envy throughout his day?', 'Tagore''s young narrator envies the unconstrained freedom of the bangle-hawker, the gardener, and the night watchman.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('971f10d0-72fd-4d7d-8a7d-f5938897b5f9', 'The Hawker selling bangles (10 AM), the Gardener digging soil (4 PM), and the Watchman swinging his lantern at night (dark evening)', true, '51801ccd-9070-48c5-b39b-81805a08c3c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5706fa07-d483-4757-a4c9-741641b1fe9a', 'A carpenter, a doctor, and a pilot', false, '51801ccd-9070-48c5-b39b-81805a08c3c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1f45821-6084-47e5-bdfa-dd69af64e603', 'A farmer, a soldier, and a sailor', false, '51801ccd-9070-48c5-b39b-81805a08c3c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd8289dc-b35d-443e-a548-024bc6d2d212', 'A teacher, a painter, and a singer', false, '51801ccd-9070-48c5-b39b-81805a08c3c6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e0e253e-8b99-477c-a1e6-17f783292356', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'Why does the young schoolboy in Tagore''s poem ''Vocation'' envy the Gardener?', 'The boy yearns for the unrestricted physical freedom to get dirty and dig in nature without parental reprimand.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('336a68e5-775a-477e-9483-9a322f1abf58', 'Because the gardener bakes in the sun and gets soaked in rain, soils his clothes with mud, and nobody scolds him or stops him from digging', true, '5e0e253e-8b99-477c-a1e6-17f783292356');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33e6ea12-74bc-4c96-8037-7da2ea7304b2', 'Because the gardener gets to eat flowers', false, '5e0e253e-8b99-477c-a1e6-17f783292356');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f43003b5-c182-4908-9b2c-61ba9c36b685', 'Because the gardener has a big house', false, '5e0e253e-8b99-477c-a1e6-17f783292356');
