INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2af20c0d-1ec0-470c-85e1-45f04b9df1fa', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'Why does the schoolboy in ''Vocation'' wish to become a Night Watchman?', 'The child desires nocturnal freedom, roaming open streetscapes beneath starlit skies instead of early bedtime rules.', NOW()) ON CONFLICT DO NOTHING;
