INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a016c3dd-304b-4532-93b1-70d0e117a6d8', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'Why was the shopkeeper described as ''neither too young nor too old, neither smart nor lazy''?', 'His nondescript facade disarmed suspicion, making the rigged game appear benign and authentic.', NOW()) ON CONFLICT DO NOTHING;
