INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd5ecd0e-d108-401a-ac15-1468a2fc6777', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'What psychological weakness in Rasheed did the shopkeeper exploit to make him lose all his money?', 'The gambler''s fallacy and lure of easy riches seduced Rasheed into reckless stakes.', NOW()) ON CONFLICT DO NOTHING;
