INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('51e82678-aff8-46be-9d04-28ba54d6b910', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'How did little Saeeda communicate with the sunrays in the courtyard?', 'The story personifies nature responding to the pure, heartfelt language of a child''s filial devotion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a601e090-56fb-429a-b143-4ccd8319eb73', 'In her own special innocent language of childhood love, which nature and the elements understood perfectly', true, '51e82678-aff8-46be-9d04-28ba54d6b910');
