INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eee7889f-ce86-48af-897b-014ab8bdcde2', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Medium', 'What poetic yearning lies at the heart of Rabindranath Tagore''s poem ''Vocation''?', 'Tagore captures childhood''s innocence, viewing adult manual labor as heroic liberation from disciplinary domestic constraints.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7745d76-2d6b-45ff-9131-ccc999a9beea', 'A child''s romantic longing for complete autonomy, freedom from rigid adult schedules, and intimate immersion in the open outdoor world', true, 'eee7889f-ce86-48af-897b-014ab8bdcde2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ccc8013-6d27-4aa1-beb0-253395bcc39f', 'A desire to become a king', false, 'eee7889f-ce86-48af-897b-014ab8bdcde2');
