INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e314828-9634-462a-8926-48dbac7354e3', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Hard', 'Analyze the allegorical conflict between the Sunrays and the dark clouds in ''A Pact with the Sun'':', 'The breakthrough of rays allegorizes enlightened rational medicine and steadfast fidelity triumphing over superstitious confinement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('159e8782-1eec-42e4-9863-9c0908f6ddef', 'The sunrays represent life-giving truth, healing, and fidelity to moral vows overcoming the suffocating, obscurantist darkness of dogmatic quackery and despair', true, '6e314828-9634-462a-8926-48dbac7354e3');
