INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b75a5759-1d57-4224-8c44-bede84e43292', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Hard', 'What is the grammatical classification of the underlined phrase in: ''Rasheed played *again and again* hoping for a big prize.''?', '''Again and again'' functions adverbially to modify the verb ''played'', indicating repetitive frequency.', NOW()) ON CONFLICT DO NOTHING;
