INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b01306a1-a8f1-4a5c-ad45-cfe62ce42e8a', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Hard', 'What deep psychological insight did Uncle share when he told Rasheed: ''Do not tell anybody at home about your bad luck or your foolishness''?', 'Uncle balances empathetic emotional protection with constructive moral mentorship, preserving the child''s dignity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('def18ab9-6bbc-48fb-b2a2-6b59af8acf12', 'To protect the boy''s self-esteem and dignity from unnecessary family mockery while ensuring he internalized the core moral lesson privately', true, 'b01306a1-a8f1-4a5c-ad45-cfe62ce42e8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1544963-c074-40ef-af6a-780bc7ea9b9e', 'To hide crimes from the police', false, 'b01306a1-a8f1-4a5c-ad45-cfe62ce42e8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aca6647a-4db5-431b-9d5a-bb200beccc95', 'Because Uncle was afraid of parents', false, 'b01306a1-a8f1-4a5c-ad45-cfe62ce42e8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa861b51-c674-4cf1-b1d0-369868d01191', 'Because the money was stolen', false, 'b01306a1-a8f1-4a5c-ad45-cfe62ce42e8a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be6d97e2-23f9-444e-8b3c-a54a13c903dc', 'Class 6', 'English', 'Chapter 8: A Game of Chance', 'Hard', 'In ''A Pact with the Sun'', how is the personification of the Sun''s court depicted?', 'Anthropomorphic personification endows celestial entities with royal court hierarchy, ethical agency, and compassionate vows.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55a9aee2-df6e-4fc6-82bf-ea992c516d38', 'The Sun is portrayed as a majestic sovereign king, and the rays are his dutiful courtiers and celestial emissaries bound by sacred honour', true, 'be6d97e2-23f9-444e-8b3c-a54a13c903dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cba754ea-76a2-4413-b0e8-a0eac886b0e9', 'As a burning furnace of coal', false, 'be6d97e2-23f9-444e-8b3c-a54a13c903dc');
