INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f14fdeb0-c399-4f98-bbb6-c88ae169aaa3', 'Class 6', 'GK', 'Chapter 8: Environmental Studies, Biodiversity & Wildlife Conservation of India', 'Hard', 'Who was the renowned environmental activist and forester from Assam known as the ''Forest Man of India'', who single-handedly planted an entire 1,360-acre forest (Molai Forest) over 30 years on a barren Brahmaputra sandbar?', 'Jadav Payeng created a thriving forest ecosystem single-handedly on Majuli sandbars, attracting elephants, tigers, and rhinos.', NOW()) ON CONFLICT DO NOTHING;
