INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('28aba67f-638d-4d01-af77-013b5117d9f2', 'Class 6', 'GK', 'Chapter 8: Environmental Studies, Biodiversity & Wildlife Conservation of India', 'Hard', 'What is the biological phenomenon of ''Bio-magnification'' (or Bio-accumulation) in environmental toxicology?', 'Lipophilic xenobiotics accumulate in adipose tissue, concentrating exponentially towards apex carnivores (e.g. vultures and raptors).', NOW()) ON CONFLICT DO NOTHING;
