INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('51f6fc33-80ed-4a8c-8580-2e93e5588c1e', 'Class 6', 'GK', 'Chapter 8: Environmental Studies, Biodiversity & Wildlife Conservation of India', 'Hard', 'Why did the populations of three species of vultures (Gyps species) in India collapse by over 99% during the 1990s, leading to a catastrophic ecological crisis?', 'Diclofenac residues in livestock carcasses proved lethally nephrotoxic to vultures, leading to a total national veterinary ban on diclofenac.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45c5bba7-62a6-45da-8e40-0467ac266864', 'Veterinary use of the non-steroidal anti-inflammatory drug ''Diclofenac'' in cattle, which caused acute renal failure and visceral gout in scavenging vultures', true, '51f6fc33-80ed-4a8c-8580-2e93e5588c1e');
