INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a17b8e20-91e4-4054-b9f2-303ea15aa20b', 'Class 6', 'GK', 'Chapter 8: Environmental Studies, Biodiversity & Wildlife Conservation of India', 'Hard', 'Which ancient tribal forest community in the Niyamgiri hills of Odisha successfully asserted their sacred ecological rights under the Forest Rights Act to save their mountain from bauxite mining?', 'The Dongria Kondh venerate the Niyamgiri ranges as Niyam Raja, winning a historic Supreme Court forest rights consensus in 2013.', NOW()) ON CONFLICT DO NOTHING;
