INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fbee3977-ea3c-43c1-95d7-024b3c46f040', 'Class 6', 'GK', 'Chapter 8: Environmental Studies, Biodiversity & Wildlife Conservation of India', 'Hard', 'What is the primary objective of the ''International Solar Alliance'' (ISA), headquartered in Gurugram, India, co-founded by India and France in 2015?', 'The ISA coordinates over 120 member states to unlock $1 trillion in solar infrastructure deployment under the ''One Sun One World One Grid'' vision.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a95c2bc3-49b6-4f54-b96f-aeec3e326e5d', 'To mobilize global investments and deploy massive solar photovoltaic energy across sunshine-rich countries (between Tropics of Cancer & Capricorn) to fight climate change', true, 'fbee3977-ea3c-43c1-95d7-024b3c46f040');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab1fc589-0aef-4eb6-ac45-8b7bd2085521', 'To build spaceships to fly to the Sun', false, 'fbee3977-ea3c-43c1-95d7-024b3c46f040');
