INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1d37572-915d-4a13-92eb-3ed4a559e46d', 'To build atomic reactors worldwide', false, 'fbee3977-ea3c-43c1-95d7-024b3c46f040');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d1c9af3-3c32-4432-a4d3-3c7383e555f7', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Easy', 'The day-to-day conditions of the atmosphere at a particular place (including temperature, rainfall, sunshine, and wind) is called:', 'Weather denotes short-term diurnal atmospheric states; climate represents statistical averages over ~30+ years.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a5e11da-370a-4a00-98b6-de20f720c65b', 'Weather', true, '0d1c9af3-3c32-4432-a4d3-3c7383e555f7');
