INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('610f309a-2237-4032-84b6-008d00283b7e', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Easy', 'The average weather condition of a large geographic region measured and recorded over a long period of time (around 30 to 35 years) is called its:', 'Climate is the long-term aggregated pattern of meteorological parameters across decades.', NOW()) ON CONFLICT DO NOTHING;
