INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6a2885c0-62ce-4500-b40d-a80830e27ae8', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Easy', 'What type of general climate does India broadly possess, which is dominated and shaped by seasonal reversal of wind patterns?', 'India''s climate is predominantly Tropical Monsoon, derived from the Arabic word ''Mausim'' meaning seasonal wind reversal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a2eca75-f515-45f0-8d3c-8d0f2ca43a3a', 'Tropical Monsoon Climate', true, '6a2885c0-62ce-4500-b40d-a80830e27ae8');
