INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b236a91c-00d4-4bc0-bd11-ea680690b9ec', 'Tundra Polar Climate', false, '6a2885c0-62ce-4500-b40d-a80830e27ae8');
