INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('172b84a8-d481-4bbc-ad2a-03aee8580e88', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Easy', 'Which season occurs in India from December to February when the sun rays do not fall directly in the region, bringing cool temperatures?', 'During winter (Dec–Feb), oblique solar rays over Northern India cause temperatures to drop sharply.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4f7e1ce-3626-4dbe-83b7-eb63604892b4', 'Cold Weather Season (Winter)', true, '172b84a8-d481-4bbc-ad2a-03aee8580e88');
