INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('daa5045d-08e4-4637-a47d-b80f20b23b5f', 'Southwest Monsoon Season', false, '172b84a8-d481-4bbc-ad2a-03aee8580e88');
