INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5b4dc9c2-39c0-4bf3-a528-0648579403a8', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Easy', 'Which season occurs in India from March to May when sun rays fall more or less directly, causing high temperatures?', 'From March to May, the northward apparent movement of the Sun raises thermal heating across the subcontinent.', NOW()) ON CONFLICT DO NOTHING;
