INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ed94c82-971e-467f-967b-32dcecccb54b', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Easy', 'Which rainy season occurs from June to September when moisture-laden winds blow from the Arabian Sea and Bay of Bengal towards the land, bringing heavy rains?', 'The Southwest Monsoon brings ~75% of India''s annual precipitation between June and September.', NOW()) ON CONFLICT DO NOTHING;
