INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db08d0ff-5b20-4489-8ffb-a416f2181561', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Easy', 'Plants and trees that grow naturally on their own in an area without human interference or help are collectively called:', 'Natural vegetation comprises virgin plant communities that have evolved undisturbed by anthropogenic interference.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8de0a163-6809-40d0-bde7-d374d1ff04d6', 'Natural Vegetation (Flora)', true, 'db08d0ff-5b20-4489-8ffb-a416f2181561');
