INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0308fe01-bda8-4f80-bce7-f456d5890633', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Easy', 'Which dense forests remain green throughout the entire year because different tree species shed their leaves at different times?', 'Tropical Rain Forests (Evergreen) occur in heavy rainfall zones (>200 cm), retaining a continuous verdant canopy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee0df177-8472-41b2-a7a4-963d1a1cd5aa', 'Tropical Evergreen Rainforests', true, '0308fe01-bda8-4f80-bce7-f456d5890633');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2eaa3a30-ce92-4293-b8ec-70a8e1d4036c', 'Tropical Deciduous Forests', false, '0308fe01-bda8-4f80-bce7-f456d5890633');
