INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b46f1299-eaf1-48c6-9be5-b66ca65673d5', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Easy', 'Which are the MOST WIDESPREAD and dominant natural forests in India, also popularly called ''Monsoon Forests''?', 'Tropical deciduous forests cover the largest area in India, shedding their leaves for 6–8 weeks in dry summer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f1d1774-b82b-426b-8a7b-91ed87f6d6ad', 'Tropical Deciduous Forests (e.g. Sal, Teak, Peepal, Neem, Shisham)', true, 'b46f1299-eaf1-48c6-9be5-b66ca65673d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf8263f2-06b3-420d-b9a2-534a8a62859d', 'Tropical Evergreen Forests', false, 'b46f1299-eaf1-48c6-9be5-b66ca65673d5');
