INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d431c531-31b7-4c4c-992e-bbabc4d0f641', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Easy', 'In which month is ''Wildlife Week'' celebrated in India every year to encourage biodiversity awareness?', 'National Wildlife Week is observed from 2 to 8 October annually across India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d392b7c-7a31-406c-b347-c9f27735202b', 'First week of October (1st to 7th October)', true, 'd431c531-31b7-4c4c-992e-bbabc4d0f641');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26885227-2cf4-40c3-8099-e29b9673c200', 'First week of June', false, 'd431c531-31b7-4c4c-992e-bbabc4d0f641');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45f384d4-e1d2-4ebd-847d-2523ad16fcdd', 'First week of January', false, 'd431c531-31b7-4c4c-992e-bbabc4d0f641');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4813379-0259-472e-bc06-9c632916b27f', 'First week of August', false, 'd431c531-31b7-4c4c-992e-bbabc4d0f641');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd38fa26-6ee9-4eeb-8081-29f7d3c8551b', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'Why do the coastal states of Tamil Nadu and Andhra Pradesh receive a major part of their annual rainfall during the ''Retreating Monsoon'' (Autumn season in October & November)?', 'Retreating monsoonal winds pick up marine moisture crossing the Bay of Bengal, causing heavy rainfall along the Coromandel coast.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad66444b-cfc0-40f6-9ab8-8e027ce3e3ae', 'Winds blow back from the mainland towards the Bay of Bengal, picking up moisture over the Bay of Bengal and striking the Coromandel coast (Northeast Monsoon)', true, 'fd38fa26-6ee9-4eeb-8081-29f7d3c8551b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bade2718-ad1d-486d-88f2-848a6794418e', 'Because snow melts in the Himalayas', false, 'fd38fa26-6ee9-4eeb-8081-29f7d3c8551b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4c76f01-32b3-47af-b330-c77788ace24a', 'Because the Arabian sea dries up', false, 'fd38fa26-6ee9-4eeb-8081-29f7d3c8551b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c340d42-b443-48a7-a904-7174bbb4dcb1', 'Because clouds move only in circles', false, 'fd38fa26-6ee9-4eeb-8081-29f7d3c8551b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fcbfdb16-cfad-416f-9656-060896d6958a', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'What are the four primary factors that influence and determine the climate of any place on Earth?', 'Climate drivers: 1. Latitude, 2. Altitude, 3. Continentality / distance from sea, and 4. Topographic relief barriers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60afe1a3-e03c-4fbf-81aa-c16b384717cc', 'Location (Latitude), Altitude (Height above sea level), Distance from the sea, and Relief (Topography)', true, 'fcbfdb16-cfad-416f-9656-060896d6958a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07f95071-9a4c-4a83-ac20-cc2d3fb70869', 'Number of cars, houses, trains, and planes', false, 'fcbfdb16-cfad-416f-9656-060896d6958a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24d0cb71-963a-48ad-91bd-0335ba38a4be', 'Types of soil, rocks, metals, and minerals', false, 'fcbfdb16-cfad-416f-9656-060896d6958a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbaee77d-0e20-4abd-92f8-8c6adacc73b3', 'Color of clouds, birds, rivers, and trees', false, 'fcbfdb16-cfad-416f-9656-060896d6958a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f901405-81f0-46c9-942c-7de9b0031916', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'Why do coastal places like Mumbai, Kolkata, and Chennai experience an ''Equable Climate'' (moderate temperature with neither extreme hot nor extreme cold), whereas Delhi and Jaipur experience ''Extreme Climate''?', 'High specific heat capacity of seawater dampens temperature extremes in maritime coastal regions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bda30eda-2b93-4ee8-a900-42653155e86a', 'Proximity to the vast ocean provides a moderating maritime sea breeze, whereas interior landlocked places suffer high continental temperature variations', true, '6f901405-81f0-46c9-942c-7de9b0031916');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d80f533-49a6-44eb-a88b-2d2c16c8ebb7', 'Because coastal cities have more air conditioners', false, '6f901405-81f0-46c9-942c-7de9b0031916');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ca9c231-2e22-4934-bb4a-c877c12814aa', 'Because the sun doesn''t shine on oceans', false, '6f901405-81f0-46c9-942c-7de9b0031916');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9f801a3-45c2-427d-b57f-055d44756b8f', 'Because Delhi has no rain', false, '6f901405-81f0-46c9-942c-7de9b0031916');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('643f102a-8474-4339-9c9e-89456de0685f', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'What are the two extreme temperature locations in India: Drass (Ladakh) and Jaisalmer (Rajasthan)?', 'Drass in Ladakh is the 2nd coldest inhabited place on Earth (-45°C), while Thar''s Jaisalmer reaches +50°C.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19de4e9c-87eb-4214-95be-980cd1012514', 'Drass is freezing cold with temperatures dropping to -45°C, while Jaisalmer is scorching hot with summer temperatures touching 50°C', true, '643f102a-8474-4339-9c9e-89456de0685f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d5901ad-ae3e-4c05-be86-1d51c827434b', 'Both are freezing ice caps', false, '643f102a-8474-4339-9c9e-89456de0685f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd289032-6f68-43c5-b19d-9122db7cb532', 'Both are scorching hot deserts', false, '643f102a-8474-4339-9c9e-89456de0685f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('472895ff-1f4a-480e-9710-891128a5b03d', 'Both have identical moderate temperatures', false, '643f102a-8474-4339-9c9e-89456de0685f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a851f72-b1c3-4776-9770-6dec1d909e08', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'How are Thorny Bushes and vegetation in arid desert regions (Rajasthan, Gujarat, dry Deccan) adapted to survive with minimal rainfall?', 'Xerophytic adaptations: microphyllous spines reduce transpiration, deep roots tap aquifers, and suberized bark insulates.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('357ae204-b91c-442d-8bae-1728e476a908', 'Leaves are modified into sharp spines (thorns) to minimize transpiration water loss, and stems are fleshy with deep taproots to absorb groundwater', true, '0a851f72-b1c3-4776-9770-6dec1d909e08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43add1f6-74da-4f84-a18a-eb8df04478f8', 'They have broad giant leaves', false, '0a851f72-b1c3-4776-9770-6dec1d909e08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e0095f6-0542-4692-9803-b93ca568faa9', 'They float in air', false, '0a851f72-b1c3-4776-9770-6dec1d909e08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1992d516-d9ac-4963-82ff-49cd96f6fb05', 'They shed leaves every day', false, '0a851f72-b1c3-4776-9770-6dec1d909e08');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bff7f84c-e8f3-4be8-9d07-afa2cc34ffea', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'How does vegetation change with increasing altitude in the Himalayan mountain zones (Mountain Vegetation)?', 'Altitudinal zonation transitions from sub-tropical foothills to temperate coniferous taiga (Pinus, Cedrus deodara) and alpine meadows.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5cb846a-a3a4-4102-9109-980ac2ad81a7', 'Between 1,500 m and 2,500 m, trees become conical in shape with needle-like leaves called Coniferous Trees (e.g. Chir, Pine, Deodar)', true, 'bff7f84c-e8f3-4be8-9d07-afa2cc34ffea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caa9ae4e-08e5-45b3-ba69-1423524b2cb4', 'Trees become thorny bushes', false, 'bff7f84c-e8f3-4be8-9d07-afa2cc34ffea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7b71c82-a43b-4eae-863d-637f5af15895', 'Trees turn into ocean kelp', false, 'bff7f84c-e8f3-4be8-9d07-afa2cc34ffea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac41ba10-755f-4442-ab1b-21a72f0f269a', 'No trees exist in mountains', false, 'bff7f84c-e8f3-4be8-9d07-afa2cc34ffea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed41f380-5e18-41ff-b152-c4a32b57fed6', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'What are ''Mangrove Forests'' and in which type of water environment do they thrive?', 'Mangroves are tidal halophytes with salt-filtering roots and pneumatophores adapted to saline coastal estuaries.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f9732d4-dd2c-47f0-b6a8-8bafe472be54', 'Specialized halophytic coastal forests that can survive and thrive in saline seawater mudflats (e.g. Sundari trees in Sundarbans)', true, 'ed41f380-5e18-41ff-b152-c4a32b57fed6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84229ce0-2424-4767-a768-591948c59085', 'Forests that grow on mountaintops in snow', false, 'ed41f380-5e18-41ff-b152-c4a32b57fed6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f86071e-ca0a-4d53-82af-380f5c2a2f68', 'Desert cactus plants', false, 'ed41f380-5e18-41ff-b152-c4a32b57fed6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5ed0182-02d4-45f6-a9cf-a7b2c4d96f4f', 'Freshwater lake lilies', false, 'ed41f380-5e18-41ff-b152-c4a32b57fed6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa2b6521-3e6d-4884-a2a1-8c5f7b9b5eba', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'What is the famous mangrove tree species found in the Ganga-Brahmaputra delta after which the ''Sundarbans'' are named?', 'Sundari trees (Heritiera fomes) dominate the tidal delta, providing timber and lending their name to the Sundarbans.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6aa2f87-f470-4066-8712-3e9ab3d96257', 'Sundari tree (Heritiera fomes)', true, 'aa2b6521-3e6d-4884-a2a1-8c5f7b9b5eba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d63e76e-30ff-457c-9dc6-1739657d65af', 'Sal tree', false, 'aa2b6521-3e6d-4884-a2a1-8c5f7b9b5eba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a68a99f2-ffea-4688-bc61-09a1aae24b1b', 'Teak tree', false, 'aa2b6521-3e6d-4884-a2a1-8c5f7b9b5eba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('594db7dc-0831-458d-a12d-a22b1505d39a', 'Chir Pine', false, 'aa2b6521-3e6d-4884-a2a1-8c5f7b9b5eba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81b5bd1f-afa7-497b-948b-c9ffee9c88c7', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'Why are natural forests of vital ecological and economic importance to our planet and human society?', 'Forests provide ecosystem services: oxygen production, carbon sequestration, soil anchoring, and non-timber forest products.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01ecb55d-57e9-4830-a5b0-de05add41a2f', 'They release Oxygen and absorb Carbon Dioxide, bind soil roots to prevent erosion, regulate rainfall, and provide timber, medicinal herbs, lac, and honey', true, '81b5bd1f-afa7-497b-948b-c9ffee9c88c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f9e075a-e803-46d6-b431-dfae57361bf7', 'They take away all oxygen', false, '81b5bd1f-afa7-497b-948b-c9ffee9c88c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e491d0f-2939-452a-9d69-4963fb4b3ef8', 'They cause soil erosion', false, '81b5bd1f-afa7-497b-948b-c9ffee9c88c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2498be15-2477-4081-b1e7-112e22a2260d', 'They make land barren', false, '81b5bd1f-afa7-497b-948b-c9ffee9c88c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ba5bb0a-57b4-4ff4-a529-ccfa7c7c4173', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'Which forest in Gujarat is world-famous as the home of the Asiatic Lion?', 'The dry deciduous teak forests of Gir in Gujarat constitute the exclusive natural habitat of the Asiatic Lion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca79185c-9e51-47bf-b575-cf003a297586', 'Gir Forest', true, '3ba5bb0a-57b4-4ff4-a529-ccfa7c7c4173');
