INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52708259-516f-41ca-9973-6664d617d482', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'Where in India are wild Elephants and One-Horned Rhinoceroses naturally found roaming together in tall alluvial grasslands?', 'The floodplains of Assam support mega-herbivores like Asian Elephants, One-horned Rhinos, and Wild Water Buffaloes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d9b7b1d-6c4a-4e16-90d3-1af67bf513ea', 'In the forests of Assam (Kaziranga and Manas)', true, '52708259-516f-41ca-9973-6664d617d482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('805f47c4-ea2c-4db3-8cc0-531c1d514906', 'In the Thar Desert of Rajasthan', false, '52708259-516f-41ca-9973-6664d617d482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe31dd82-0cd2-4f88-8d23-0b5dabe3bab0', 'In the cold deserts of Ladakh', false, '52708259-516f-41ca-9973-6664d617d482');
