INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f49596d-50ba-450c-b313-a6c79a878e33', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'Which high-altitude animals with thick woolly coats are found roaming in the snow-bound Himalayan and Ladakh ranges?', 'High alpine Himalayan fauna features thick pelts: Bos mutus (Wild Yak), Chiru, Snow Leopards, and Bharal (Blue Sheep).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('452e0b87-509b-4622-83a4-1fbae9eb1010', 'Wild Yaks, Tibetan Antelope (Chiru), Snow Leopards, and Himalayan Ibex', true, '4f49596d-50ba-450c-b313-a6c79a878e33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ece91366-7c6b-46c8-a36a-7a7e89513a17', 'Camels and Lions', false, '4f49596d-50ba-450c-b313-a6c79a878e33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0559ccf1-a515-4d2f-9566-27595763cd43', 'Elephants and Rhinos', false, '4f49596d-50ba-450c-b313-a6c79a878e33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('965b5657-c4d1-49fb-8d3f-d385958b58b0', 'Peacocks and Flamingos', false, '4f49596d-50ba-450c-b313-a6c79a878e33');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('831d9a8a-1bbb-4b80-a7fc-1d356165a241', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'What are ''Migratory Birds'' and why do birds like Siberian Cranes, Flamingos, and Pintail Ducks migrate to Indian wetlands every winter?', 'Migratory avifauna escape freezing sub-polar temperatures along the Central Asian Flyway to winter in hospitable Indian wetlands.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40b69cc5-3177-4e21-9eaa-6a1b1824bfb8', 'They fly thousands of kilometres from freezing Arctic/Siberian winter extremes to warmer Indian wetlands in search of food and nesting grounds', true, '831d9a8a-1bbb-4b80-a7fc-1d356165a241');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('211e6e28-fd44-486b-bba1-e97a7bb3dd2e', 'They migrate because they get lost', false, '831d9a8a-1bbb-4b80-a7fc-1d356165a241');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('731fb61a-0773-497f-af58-3188bf5aa19b', 'They come to India to hibernate underwater', false, '831d9a8a-1bbb-4b80-a7fc-1d356165a241');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd18132a-8b8b-485c-823b-4e04fab6a7b9', 'They only fly in summer', false, '831d9a8a-1bbb-4b80-a7fc-1d356165a241');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3c59449b-c5bf-4b2f-bbf6-eb1948f5bb07', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'Which desert animals are specially adapted to the arid Rann of Kachchh and Thar Desert of northwestern India?', 'The Indian Wild Ass (Equus hemionus khur) thrives in the saline flats of Rann of Kachchh alongside desert camels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebce3479-67bc-4fa4-af87-0479d99ed8e4', 'Camels (in Thar) and Wild Ass / Khur (in the Little Rann of Kachchh)', true, '3c59449b-c5bf-4b2f-bbf6-eb1948f5bb07');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de4e4312-9097-4797-907e-4c5020d80974', 'Yaks and Snow Leopards', false, '3c59449b-c5bf-4b2f-bbf6-eb1948f5bb07');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('673b602d-2f46-4042-b17a-b5b651e9d24b', 'Tigers and Rhinos', false, '3c59449b-c5bf-4b2f-bbf6-eb1948f5bb07');
