INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf3b3b84-0292-496c-adbf-37e547135d02', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'What civic programme was launched to encourage people and school students across India to plant millions of trees during the monsoon season?', 'Initiated by K.M. Munshi in 1950, Van Mahotsav is an annual tree-planting festival celebrated in the first week of July.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('573d1469-ef63-40ab-8be3-501408ffc639', 'Van Mahotsav (''Forest Festival'')', true, 'cf3b3b84-0292-496c-adbf-37e547135d02');
