INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('326aa051-8f8a-446c-bc34-2308085df016', 'Swachh Bharat', false, 'cf3b3b84-0292-496c-adbf-37e547135d02');
