INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('356c270a-85ff-4208-9fb5-742336cfb711', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Medium', 'Why is agriculture in India predominantly described as a ''Gamble with the Monsoons''?', 'Rainfed agrarian livelihoods depend heavily on the spatio-temporal distribution of southwest monsoonal rains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('274428c3-e5a3-4ea2-a655-8ab7a4837fac', 'A vast majority of Indian farming relies on timely, adequate monsoon rainfall; a weak or delayed monsoon causes severe drought and crop failure', true, '356c270a-85ff-4208-9fb5-742336cfb711');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78d44a76-e616-46ed-82dc-4af56d3b3deb', 'Because farmers play card games in fields', false, '356c270a-85ff-4208-9fb5-742336cfb711');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c67e1921-ad21-4906-965a-bca9894cc0f7', 'Because crops grow without water', false, '356c270a-85ff-4208-9fb5-742336cfb711');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('416de4e7-f50a-422b-984c-9170e717a6dd', 'Because monsoons only bring snow', false, '356c270a-85ff-4208-9fb5-742336cfb711');
