INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6ccbb99-220b-4240-a496-44b545bfcd5a', 'Ebony (Evergreen)', false, 'f41fecda-736f-44ae-b84e-ffe10f507a80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42310004-e55c-427a-93d3-e53860062f72', 'Mahogany (Evergreen)', false, 'f41fecda-736f-44ae-b84e-ffe10f507a80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e15113e-b1b5-4e5b-a857-9e747ff8391b', 'Rosewood (Evergreen)', false, 'f41fecda-736f-44ae-b84e-ffe10f507a80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ec54413-56af-4124-9a55-54bc154c0a7b', 'Teak (Evergreen)', true, 'f41fecda-736f-44ae-b84e-ffe10f507a80');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31a20396-10cb-4ddc-9db2-ae46e4268ae7', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'A climatologist records the seasonal pressure patterns over South Asia in July. What atmospheric mechanism drives the Southwest Monsoon?', 'Thermal depression over the continental interior draws cross-equatorial Coriolis-deflected southwesterly trade winds carrying ocean moisture.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f2e13e8-4e24-48ce-94e1-3391a760be30', 'Intense solar heating creates an intense thermal Low-Pressure trough over the northwestern plains/Tibetan plateau, sucking in moist High-Pressure oceanic trade winds from the southern Indian Ocean', true, '31a20396-10cb-4ddc-9db2-ae46e4268ae7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1c2671c-6042-4561-9fcb-bb92382d1879', 'Cold snow in the Himalayas blows wind to the sea', false, '31a20396-10cb-4ddc-9db2-ae46e4268ae7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddcdfdf4-49f9-4777-b4b0-13d7481f5c49', 'The moon pulls all ocean water onto the land', false, '31a20396-10cb-4ddc-9db2-ae46e4268ae7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8023aa07-b2de-4412-b09d-1964cb8189b5', 'Earth stops rotating for a month', false, '31a20396-10cb-4ddc-9db2-ae46e4268ae7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77ebc721-95aa-464d-9bf7-f96f40ffe3e4', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'Match Column I (Forest Types) with Column II (Dominant Species / Typical Regions):
(a) Tropical Rainforest  -> (i) Sundari / Ganga-Brahmaputra delta
(b) Tropical Deciduous   -> (ii) Ebony, Mahogany, Rosewood / Western Ghats
(c) Coniferous Mountain   -> (iii) Sal, Teak, Peepal, Shisham / Central India
(d) Mangrove Forest      -> (iv) Chir, Pine, Deodar / Himalayan slopes', 'Rainforest = Ebony/Mahogany; Deciduous = Sal/Teak; Coniferous = Chir/Deodar; Mangrove = Sundari.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49ac6b8f-0bef-4e97-a890-9e5ffa85beaa', 'a-(ii), b-(iii), c-(iv), d-(i)', true, '77ebc721-95aa-464d-9bf7-f96f40ffe3e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5228cb07-3e76-431c-a9d1-c93b1df4ef56', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '77ebc721-95aa-464d-9bf7-f96f40ffe3e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae9c0b9a-7f7c-400e-8a0e-bfd7c623b2ce', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '77ebc721-95aa-464d-9bf7-f96f40ffe3e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82311860-c645-4b0b-be17-03e416af76c4', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '77ebc721-95aa-464d-9bf7-f96f40ffe3e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd3d0e6e-fb27-4186-9930-b33354781e63', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'Read the statements regarding Indian climate and forests:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36a44a5a-6fa8-4cee-ab86-4d3284d7e0f8', 'Statements 1 and 2 only', true, 'cd3d0e6e-fb27-4186-9930-b33354781e63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2a16834-6951-448b-b493-34c66e8a2270', 'Statements 2 and 3 only', false, 'cd3d0e6e-fb27-4186-9930-b33354781e63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c36bdbc-09b8-4e7e-ad15-ce8c7e233483', 'Statements 1 and 3 only', false, 'cd3d0e6e-fb27-4186-9930-b33354781e63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8c6e04f-f306-492e-a326-34c0e76ffaa0', 'All Statements 1, 2, and 3', false, 'cd3d0e6e-fb27-4186-9930-b33354781e63');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41b4ac39-e0a2-4442-b8d5-cafada2c7e55', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'Why do plants in thorny scrub forests (like Acacia/Babool, Cactus, and Khejri) develop extensive underground root networks stretching meters deep and wide?', 'Deep phreatophytic taproots reach capillary fringe water tables, sustaining desert scrub in xerophytic environments.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9899807-4eb5-4ccb-b0c5-8bfda8c86623', 'To maximize groundwater scavenging across deep arid soil profiles where surface moisture is scarce', true, '41b4ac39-e0a2-4442-b8d5-cafada2c7e55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce4d9684-b8f6-4c9e-b2ee-3616892597e8', 'To anchor against heavy snowstorms', false, '41b4ac39-e0a2-4442-b8d5-cafada2c7e55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8e2d24d-352b-4cec-939b-0ddba3a18a1c', 'To store frozen ice', false, '41b4ac39-e0a2-4442-b8d5-cafada2c7e55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8b1b97c-7488-4602-ad30-36f16c987be0', 'To connect with ocean water', false, '41b4ac39-e0a2-4442-b8d5-cafada2c7e55');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d09635cf-e5cb-49c9-8319-4ca7ed0cfb19', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'Consider four national conservation sanctuaries:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b11c993-eeda-481e-8be5-bc953b8dda06', '1: Asiatic Lion ; 2: One-Horned Rhino ; 3: Hangul (Kashmir Stag) ; 4: Sangai (Dancing Deer)', true, 'd09635cf-e5cb-49c9-8319-4ca7ed0cfb19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3678fa5-4b98-4c57-bd0e-24d7efa28ba1', '1: Snow Leopard ; 2: Royal Bengal Tiger ; 3: Asiatic Lion ; 4: Elephant', false, 'd09635cf-e5cb-49c9-8319-4ca7ed0cfb19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('139d1bf4-35ea-484c-96f3-6cb46178f2d1', '1: Hangul ; 2: Sangai ; 3: Asiatic Lion ; 4: Rhino', false, 'd09635cf-e5cb-49c9-8319-4ca7ed0cfb19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0ca79e3-7ed0-4c5a-9a66-a9059343684b', '1: Elephant ; 2: Tiger ; 3: Snow Leopard ; 4: Hangul', false, 'd09635cf-e5cb-49c9-8319-4ca7ed0cfb19');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e5e0a86-42d7-4338-9de8-02b9f7da8777', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'What is the phenomenon of ''Western Disturbances'' that brings winter rainfall and mountain snowfall to north-western India in December and January?', 'Mediterranean extra-tropical cyclones steered by westerly jet streams provide crucial rabi crop (wheat) moisture in northwest India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('873c8544-a2ff-485a-be02-ba857d7f169b', 'Temperate cyclonic low-pressure systems originating over the Mediterranean Sea that are carried eastward into India by the subtropical westerly jet stream', true, '5e5e0a86-42d7-4338-9de8-02b9f7da8777');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fc3476b-1055-4ca3-876a-a5b78d0b763d', 'Cyclones from the Bay of Bengal', false, '5e5e0a86-42d7-4338-9de8-02b9f7da8777');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc5e5434-4a94-46de-a623-73fbb0353c53', 'Dust storms from the Sahara', false, '5e5e0a86-42d7-4338-9de8-02b9f7da8777');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ca45fbf-4ef3-49ac-9076-8e772416a922', 'Tornadoes from the Pacific', false, '5e5e0a86-42d7-4338-9de8-02b9f7da8777');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d5c5c8be-3472-4662-8014-8512c1122f95', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'Why is the Tibetan Antelope (''Chiru'') illegally hunted and endangered in high-altitude Himalayas?', 'Chiru is poached for Shahtoosh (''King of Wools''), prompting strict international CITES Appendix I trade bans.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea76fa43-6ae2-4d98-b8d6-dee46ccf8405', 'For its ultra-fine, warm, and lightweight wool called ''Shahtoosh'', which is spun into expensive luxury shawls', true, 'd5c5c8be-3472-4662-8014-8512c1122f95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db0a5178-bc8c-4cfd-a161-dcee8337825d', 'For its horn meat', false, 'd5c5c8be-3472-4662-8014-8512c1122f95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5b6cf93-7547-4705-8ac5-de7493097bc6', 'For leather shoes', false, 'd5c5c8be-3472-4662-8014-8512c1122f95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f86289c3-0c2d-4be6-8ae0-ce64997eb451', 'Because it attacks domestic sheep', false, 'd5c5c8be-3472-4662-8014-8512c1122f95');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3968b525-b585-4a70-92da-a976d41aeae2', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'What ecological role do coastal Mangrove forests perform during violent tropical cyclones and tsunamis?', 'Mangrove bioshields act as natural coastal wave attenuators, dampening destructive hydro-dynamic surge energies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8fb983c-242b-4c19-a76a-d81ffdc11d65', 'Their dense root networks absorb and attenuate high-energy oceanic storm surges, drastically reducing inland coastal erosion and protecting human lives', true, '3968b525-b585-4a70-92da-a976d41aeae2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('643bac9c-5fd5-4ae5-be5e-559296968156', 'They create bigger waves', false, '3968b525-b585-4a70-92da-a976d41aeae2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64d0cb3b-5598-4d0f-8726-8ce2cca34460', 'They pump seawater into clouds', false, '3968b525-b585-4a70-92da-a976d41aeae2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eafeeaff-867a-41c5-b211-75cea899458b', 'They blow cyclone winds away', false, '3968b525-b585-4a70-92da-a976d41aeae2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c171172-5fa8-41b4-aff1-3f9d89b998de', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'What is the primary conservation objective of establishing ''Wildlife Corridors'' between fragmented National Parks and Tiger Reserves?', 'Landscape ecological corridors connect fragmented habitats, preventing genetic bottlenecks and human-wildlife conflict.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cfd2a59-856d-4ada-a6e2-949e398db4fb', 'To enable safe, unobstructed seasonal migration, gene flow, and territorial dispersal of wildlife populations, preventing inbreeding depression', true, '9c171172-5fa8-41b4-aff1-3f9d89b998de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5fa80e7-fee9-4201-b95d-95a19b9cebfd', 'To build tourist highways through forests', false, '9c171172-5fa8-41b4-aff1-3f9d89b998de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90ee632a-6b92-4c54-86af-825975355a7f', 'To fence animals in cages', false, '9c171172-5fa8-41b4-aff1-3f9d89b998de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f77615c8-8a0a-4d12-9ece-4f9f04972e30', 'To separate male and female animals', false, '9c171172-5fa8-41b4-aff1-3f9d89b998de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b78315ff-58ab-494a-a885-13102f4f9104', 'Class 6', 'Social Science', 'Chapter 8: India — Climate, Vegetation and Wildlife', 'Hard', 'What fundamental message does the final chapter of NCERT Class 6 Geography emphasize regarding wildlife coexistence?', 'NCERT urges ethical consumer boycotts of wildlife derivatives and active community afforestation for ecological sustainability.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8768637b-c07f-4955-b427-746e73da7d92', 'Refusing to purchase items made from animal parts (bones, horns, fur, feathers, ivory), planting native trees, and respecting all biological life on Earth', true, 'b78315ff-58ab-494a-a885-13102f4f9104');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a63aaa18-a8b9-46fe-9d4d-33f242e5babb', 'Cutting down all forests for cities', false, 'b78315ff-58ab-494a-a885-13102f4f9104');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f4520d2-6208-44bb-bb03-82aafb64bf37', 'Keeping wild tigers as domestic pets', false, 'b78315ff-58ab-494a-a885-13102f4f9104');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7b57ad8-7e20-4e8a-9cf8-a4d1eabdd2a8', 'Hunting birds during winter', false, 'b78315ff-58ab-494a-a885-13102f4f9104');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a45ccde-df12-4ae0-b2b7-c8368fe7aa96', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'संज्ञा के स्थान पर प्रयुक्त होने वाले शब्दों (जैसे: मैं, तुम, वह, हम, आप, यह, कोई, क्या) को व्याकरण में क्या कहते हैं?', 'संज्ञा की पुनरुक्ति को रोककर वाक्य को सुंदर व संक्षिप्त बनाने वाले विकारी शब्द ''सर्वनाम'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe94635a-bf23-40c3-80a6-5cd7a8a0c2e0', 'सर्वनाम (Pronoun)', true, '7a45ccde-df12-4ae0-b2b7-c8368fe7aa96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5eb1073-31be-401f-afc8-5537adc0cd00', 'विशेषण', false, '7a45ccde-df12-4ae0-b2b7-c8368fe7aa96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7551833-606d-4586-886e-8c72e7028140', 'क्रिया', false, '7a45ccde-df12-4ae0-b2b7-c8368fe7aa96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc932641-b568-46d2-ae04-00ccf66bfbd9', 'अव्यय', false, '7a45ccde-df12-4ae0-b2b7-c8368fe7aa96');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76e37456-8911-4f0b-b6f9-97af03350ae6', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'हिंदी भाषा में सर्वनाम के मुख्य रूप से कितने भेद (प्रकार) होते हैं?', 'सर्वनाम के 6 प्रमुख भेद हैं: 1. पुरुषवाचक, 2. निश्चयवाचक, 3. अनिश्चयवाचक, 4. संबंधवाचक, 5. प्रश्नवाचक, और 6. निजवाचक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('134617b2-b40e-4825-abcc-c694be29cf92', 'छह भेद (6 Types)', true, '76e37456-8911-4f0b-b6f9-97af03350ae6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29470852-dbc2-449c-b089-6999c6f9501c', 'पाँच भेद', false, '76e37456-8911-4f0b-b6f9-97af03350ae6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1866d6e-c459-4051-8137-37a49a52ff91', 'चार भेद', false, '76e37456-8911-4f0b-b6f9-97af03350ae6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21d94f1f-b4ee-4117-b2c3-04d340e1481a', 'आठ भेद', false, '76e37456-8911-4f0b-b6f9-97af03350ae6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91fb1075-d7db-4e44-90a8-1f6e2420ab1e', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'बोलने वाले (वक्ता), सुनने वाले (श्रोता) अथवा किसी अन्य व्यक्ति के लिए प्रयुक्त होने वाले सर्वनाम को क्या कहते हैं?', 'संवाद में तीनों पुरुषों (वक्ता, श्रोता, अन्य) के लिए प्रयुक्त सर्वनाम ''पुरुषवाचक सर्वनाम'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfc356b7-7612-49a4-b44f-f70c8b48c0b7', 'पुरुषवाचक सर्वनाम (Personal Pronoun)', true, '91fb1075-d7db-4e44-90a8-1f6e2420ab1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38a23744-3f16-4c0a-827d-b2de03c8d495', 'निश्चयवाचक सर्वनाम', false, '91fb1075-d7db-4e44-90a8-1f6e2420ab1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('550927a9-8cf3-496a-89b2-b951b2541028', 'निजवाचक सर्वनाम', false, '91fb1075-d7db-4e44-90a8-1f6e2420ab1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('021b2d02-61e6-4108-94fe-49397693bc0d', 'प्रश्नवाचक सर्वनाम', false, '91fb1075-d7db-4e44-90a8-1f6e2420ab1e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('86904dd9-af81-474e-807f-bf8bdf540366', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'पुरुषवाचक सर्वनाम के कितने भेद होते हैं?', 'पुरुषवाचक के 3 भेद हैं: उत्तम पुरुष (First Person - मैं/हम), मध्यम पुरुष (Second Person - तू/तुम/आप), अन्य पुरुष (Third Person - वह/वे)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b17417d6-da1e-40ac-b221-b047839fed27', 'तीन भेद (उत्तम पुरुष, मध्यम पुरुष, और अन्य पुरुष)', true, '86904dd9-af81-474e-807f-bf8bdf540366');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef0b127d-61ef-4b23-9eea-435be9b3d457', 'दो भेद', false, '86904dd9-af81-474e-807f-bf8bdf540366');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7041330-a5da-4aa6-9d06-f0945dc32ac9', 'चार भेद', false, '86904dd9-af81-474e-807f-bf8bdf540366');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5586ef21-1476-4533-8845-b35ea4e5047d', 'पाँच भेद', false, '86904dd9-af81-474e-807f-bf8bdf540366');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9ae6e22-3273-4763-874b-d69ef10b9859', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'बोलने वाला (वक्ता) या लिखने वाला अपने लिए जिन सर्वनाम शब्दों का प्रयोग करता है (जैसे: मैं, हम, मुझे, मेरा, हमारा), वे क्या कहलाते हैं?', 'वक्ता द्वारा स्वयं के संदर्भ में प्रयुक्त पद ''उत्तम पुरुष'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('febfb6c9-27fc-4d80-aa72-77196b41efd2', 'उत्तम पुरुषवाचक सर्वनाम (First Person)', true, 'f9ae6e22-3273-4763-874b-d69ef10b9859');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cee8da70-67c7-4bc8-91b7-407a951ccac3', 'मध्यम पुरुषवाचक', false, 'f9ae6e22-3273-4763-874b-d69ef10b9859');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82bff453-31f0-4334-834f-9f3077283404', 'अन्य पुरुषवाचक', false, 'f9ae6e22-3273-4763-874b-d69ef10b9859');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b009cd4e-1385-4e30-8aba-6dcd19d7d663', 'निजवाचक', false, 'f9ae6e22-3273-4763-874b-d69ef10b9859');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ec889481-140b-479f-9565-569ea4ee0fe3', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'जिससे बात की जाए (श्रोता/सुनने वाले) के लिए जिन सर्वनाम शब्दों का प्रयोग होता है (जैसे: तू, तुम, आप, तुझे, तुम्हारा, आपका), वे क्या कहलाते हैं?', 'श्रोता के लिए प्रयुक्त सर्वनाम पद ''मध्यम पुरुष'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e484625e-8f0a-4d55-a3c9-e059e6147bb4', 'मध्यम पुरुषवाचक सर्वनाम (Second Person)', true, 'ec889481-140b-479f-9565-569ea4ee0fe3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9c7ec35-e09c-4171-95c3-b1188273b555', 'उत्तम पुरुषवाचक', false, 'ec889481-140b-479f-9565-569ea4ee0fe3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f91eb8e3-5849-4aac-899b-498fb992c2ff', 'अन्य पुरुषवाचक', false, 'ec889481-140b-479f-9565-569ea4ee0fe3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b68cd90-6d61-487a-8a9c-f3b5b66094ab', 'संबंधवाचक', false, 'ec889481-140b-479f-9565-569ea4ee0fe3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6213f256-bbab-47cb-b258-d0659501ed79', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'वक्ता और श्रोता जिसके विषय में बात कर रहे हों (किसी तीसरे व्यक्ति) के लिए प्रयुक्त सर्वनाम (जैसे: वह, वे, उसे, उनका, उन्होंने) क्या कहलाते हैं?', 'अनुपस्थित या किसी अन्य व्यक्ति के लिए प्रयुक्त पद ''अन्य पुरुष'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acedabe8-7398-4031-9df1-ebc586a15273', 'अन्य पुरुषवाचक सर्वनाम (Third Person)', true, '6213f256-bbab-47cb-b258-d0659501ed79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8be015e-62cb-4135-883c-ffc24fdd4be8', 'उत्तम पुरुषवाचक', false, '6213f256-bbab-47cb-b258-d0659501ed79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1572379-11c7-4d8e-9f46-e2a259b6c2ed', 'मध्यम पुरुषवाचक', false, '6213f256-bbab-47cb-b258-d0659501ed79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d391fc94-d35c-4952-9689-dc2df0a8a144', 'अनिश्चयवाचक', false, '6213f256-bbab-47cb-b258-d0659501ed79');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6a98e0c2-5c97-4389-bb90-94febbe5b396', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'जो सर्वनाम शब्द किसी निश्चित व्यक्ति, वस्तु या स्थान का निश्चित संकेत करते हैं (जैसे: ''यह मेरी पुस्तक है'', ''वह रोहन का घर है''), उन्हें क्या कहते हैं?', 'निश्चित दूरस्थ या निकटवर्ती वस्तु की ओर संकेत करने वाले सर्वनाम (यह, वह, ये, वे) ''निश्चयवाचक'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f737dfcd-3779-432e-ae1c-4e74748395dc', 'निश्चयवाचक सर्वनाम या संकेतवाचक सर्वनाम (Demonstrative Pronoun)', true, '6a98e0c2-5c97-4389-bb90-94febbe5b396');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3550933-a5cb-483a-8e85-cf327dc98039', 'अनिश्चयवाचक सर्वनाम', false, '6a98e0c2-5c97-4389-bb90-94febbe5b396');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2d9503c-3537-4c95-8490-f48bef557ce5', 'निजवाचक सर्वनाम', false, '6a98e0c2-5c97-4389-bb90-94febbe5b396');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af6da393-048f-41a4-b400-f24571d396b7', 'प्रश्नवाचक सर्वनाम', false, '6a98e0c2-5c97-4389-bb90-94febbe5b396');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ba99372-a7ca-4e11-b009-05bfea70cb34', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'जिन सर्वनाम शब्दों से किसी निश्चित व्यक्ति या वस्तु का बोध नहीं होता (जैसे: ''दूध में कुछ गिर गया है'', ''दरवाजे पर कोई खड़ा है''), उन्हें क्या कहते हैं?', 'अस्पष्ट या अनिर्दिष्ट संज्ञा के स्थान पर आने वाले शब्द (कोई, कुछ, किसी) ''अनिश्चयवाचक सर्वनाम'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('974aa647-163a-4900-9d4a-3ac8a1222e69', 'अनिश्चयवाचक सर्वनाम (Indefinite Pronoun - ''कोई'', ''कुछ'')', true, '6ba99372-a7ca-4e11-b009-05bfea70cb34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89df4bc6-b193-4c35-b89d-fc966255d654', 'निश्चयवाचक सर्वनाम', false, '6ba99372-a7ca-4e11-b009-05bfea70cb34');
