INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a8317e0f-e45f-44a2-ab45-f789c0ba7d15', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'वाक्य में एक संज्ञा या सर्वनाम का दूसरे संज्ञा या सर्वनाम से संबंध जोड़ने वाले शब्द (जैसे: ''जो मेहनत करेगा, वह सफल होगा'', ''जिसकी लाठी उसकी भैंस'') क्या कहलाते हैं?', 'पारस्परिक उपवाक्यों में संबंध प्रकट करने वाले सर्वनाम युग्म ''संबंधवाचक'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1a8ec5c-47d9-458b-853a-10857414cae0', 'संबंधवाचक सर्वनाम (Relative Pronoun - ''जो-सो'', ''जैसा-वैसा'', ''जिसकी-उसकी'')', true, 'a8317e0f-e45f-44a2-ab45-f789c0ba7d15');
