INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30de12fa-16c3-4ca8-aecc-7f85557ea2cb', 'संबंधवाचक सर्वनाम', false, '32a25fa9-5214-45f6-89b5-3f93b2e52766');
