INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f748370-bcd9-49ba-ad9f-543811e3a816', 'निजवाचक सर्वनाम', false, '32a25fa9-5214-45f6-89b5-3f93b2e52766');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf00d4ed-76e8-4a25-86a7-476babba0e20', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Easy', 'जिन सर्वनाम शब्दों का प्रयोग कर्ता स्वयं अपने लिए (अपने आप के अर्थ में) करता है (जैसे: ''मैं अपना काम स्वयं करूँगा'', ''वह खुद चला गया'', ''आप ही कर लो''), उन्हें क्या कहते हैं?', 'कर्ता द्वारा आत्मबोध (स्वयं/खुद/अपने आप) हेतु प्रयुक्त सर्वनाम ''निजवाचक सर्वनाम'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f499a817-2d37-4228-89a5-15463f9dc371', 'निजवाचक सर्वनाम (Reflexive Pronoun - ''स्वयं'', ''खुद'', ''अपने आप'', ''आप'')', true, 'bf00d4ed-76e8-4a25-86a7-476babba0e20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39b052b9-e6e5-4969-a70c-35e56ed396aa', 'मध्यम पुरुष सर्वनाम', false, 'bf00d4ed-76e8-4a25-86a7-476babba0e20');
