INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e7c36dd-4e16-47be-8623-a3c4dadcfbf3', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', '''आप'' शब्द का प्रयोग मध्यम पुरुष और निजवाचक दोनों में होता है। निम्नलिखित में से किस वाक्य में ''आप'' का प्रयोग ''निजवाचक सर्वनाम'' के रूप में हुआ है?', 'जब ''आप'' का अर्थ ''स्वयं/खुद'' (अपने आप) हो तो वह निजवाचक सर्वनाम होता है; जब आदरपूर्वक श्रोता के लिए हो तो मध्यम पुरुष होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0fdf6da-c47e-44ab-b543-7ec30f519f18', '''मैं यह काम आप (स्वयं) ही कर लूँगा।'' (निजवाचक)', true, '4e7c36dd-4e16-47be-8623-a3c4dadcfbf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7949fa61-570c-49c2-87e6-502798a7f3bf', '''आप कहाँ जा रहे हैं?'' (आदरार्थक मध्यम पुरुष)', false, '4e7c36dd-4e16-47be-8623-a3c4dadcfbf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cec417e7-1d5a-4156-8a19-a4d97646c7ed', '''आप हमारे आदरणीय शिक्षक हैं।'' (मध्यम पुरुष)', false, '4e7c36dd-4e16-47be-8623-a3c4dadcfbf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17d1e74e-8922-44ea-a0c6-7d4f333ce4e0', '''आप चाय पीजिए।'' (मध्यम पुरुष)', false, '4e7c36dd-4e16-47be-8623-a3c4dadcfbf3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('40d9da4b-d4bf-446d-ac1d-6547ec339754', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'सर्वनाम और सार्वनामिक विशेषण में क्या मूलभूत अंतर होता है?', 'संज्ञा के स्थान पर प्रयुक्त अकेला पद = सर्वनाम; संज्ञा के आगे लगकर निर्देश करने वाला पद = सार्वनामिक विशेषण।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70c32702-0e34-40b3-9b60-6677eb6e01fc', 'जब ''यह/वह'' संज्ञा के स्थान पर अकेले आते हैं तो सर्वनाम होते हैं (जैसे: ''यह मेरी कार है'') ; किन्तु जब वे संज्ञा शब्द के ठीक पहले आकर उसकी विशेषता बताते हैं तो सार्वनामिक विशेषण कहलाते हैं (जैसे: ''यह कार मेरी है'')', true, '40d9da4b-d4bf-446d-ac1d-6547ec339754');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4078c661-f78c-4f86-87b2-9a3faa38b776', 'सर्वनाम केवल बहुवचन होते हैं', false, '40d9da4b-d4bf-446d-ac1d-6547ec339754');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7090dd95-53d2-4f16-8e03-1c7d15817f86', 'सार्वनामिक विशेषण में संज्ञा नहीं होती', false, '40d9da4b-d4bf-446d-ac1d-6547ec339754');
