INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('50aca532-4171-4427-bf1b-cf6822f64101', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'सर्वनाम शब्दों में लिंग का निर्धारण किस आधार पर होता है?', 'सर्वनाम स्वयं लिंग-निरपेक्ष होते हैं (वह, मैं, तुम); उनका लिंग वाक्य की समापिका क्रिया से स्पष्ट होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cbe0f81-bc87-4778-9803-22e03ec22a1a', 'सर्वनाम का रूप दोनों लिंगों में समान रहता है; लिंग की पहचान वाक्य में प्रयुक्त क्रिया पद से होती है (जैसे: ''वह पढ़ता है'' - पुल्लिंग ; ''वह पढ़ती है'' - स्त्रीलिंग)', true, '50aca532-4171-4427-bf1b-cf6822f64101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa221fc7-9a5b-4953-a847-3fc952073e09', 'सर्वनाम शब्द में मात्रा बदलकर', false, '50aca532-4171-4427-bf1b-cf6822f64101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed42b15f-1aed-4223-a534-621fe0ab0ed1', 'सर्वनाम केवल पुल्लिंग होते हैं', false, '50aca532-4171-4427-bf1b-cf6822f64101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6384c135-0ecb-412d-b818-c49848c1b867', 'सर्वनाम में लिंग नहीं होता', false, '50aca532-4171-4427-bf1b-cf6822f64101');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f12b99a8-5608-474f-b37c-e748873c5070', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'वाक्य को सर्वनाम की दृष्टि से शुद्ध कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0dba7305-a0a4-4b33-8075-b9022effe5ac', 'मुझे आपकी कलम चाहिए। (''मेरे को'' के स्थान पर ''मुझे'' मानक शुद्ध रूप है)', true, 'f12b99a8-5608-474f-b37c-e748873c5070');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7dde3bd-3007-4a52-8f8a-510e93355150', 'मुझको आपकी कलम चाहिए है।', false, 'f12b99a8-5608-474f-b37c-e748873c5070');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('202e36e6-a571-4ac0-bb41-e171d11e4515', 'मैं आपकी कलम मांगता।', false, 'f12b99a8-5608-474f-b37c-e748873c5070');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ded062c4-c611-4bf2-a69f-42753472a209', 'मेरा आपकी कलम चाहिए।', false, 'f12b99a8-5608-474f-b37c-e748873c5070');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('28dc74ed-c0ff-4994-803b-40e5005326e7', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'वाक्य को शुद्ध कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d889dd7-6eac-427c-9b2b-2f35a0cb572b', 'वे लोग कल दिल्ली जा रहे हैं। (बहुवचन संज्ञा ''लोग'' के साथ बहुवचन सर्वनाम ''वे'' शुद्ध है)', true, '28dc74ed-c0ff-4994-803b-40e5005326e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9d1d7d8-a20f-49f9-8234-cd122cb63776', 'वह लोग दिल्ली जाएगा।', false, '28dc74ed-c0ff-4994-803b-40e5005326e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c1534c3-1a0e-428c-b3b1-0a4dcbc1c056', 'उसे लोग दिल्ली जा रहे हैं।', false, '28dc74ed-c0ff-4994-803b-40e5005326e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7916e07-998b-4400-9e28-e9af9ed41716', 'उन लोग दिल्ली जा रहा है।', false, '28dc74ed-c0ff-4994-803b-40e5005326e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0e6644ec-8734-480e-a63b-8e89b7f94a94', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'सर्वनाम शब्द ''जो'' के विभिन्न कारक रूपों का सही युग्म कौन-सा है?', 'संबंधवाचक सर्वनाम ''जो'' के कारक रूप ''जिस-'' प्रातिपदिक से बनते हैं (जिसने, जिसे, जिससे, जिसका)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('010d3ae0-5854-4685-a5b2-494d67911564', 'जिसने (कर्ता), जिसको/जिसे (कर्म), जिससे (करण/अपादान), जिसका/जिसके/जिसकी (संबंध), जिसमें/जिसपर (अधिकरण)', true, '0e6644ec-8734-480e-a63b-8e89b7f94a94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01391139-6d88-46c0-9484-bc4452e00427', 'जोने, जोको, जोसे', false, '0e6644ec-8734-480e-a63b-8e89b7f94a94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('622eeb99-3a11-4aa7-a92a-604a5ce9bde7', 'ज्याका, ज्याकी', false, '0e6644ec-8734-480e-a63b-8e89b7f94a94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b88ddc6-b2d3-4d5a-b6ad-dd2ceda3da8e', 'जोए, जोओ', false, '0e6644ec-8734-480e-a63b-8e89b7f94a94');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f05727d4-27ef-413c-a5f6-2a050d3f31d9', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'प्रश्नवाचक सर्वनाम ''कौन'' और ''क्या'' का प्रयोग क्रमशः किनके लिए होता है?', 'प्राणीवाचक प्रश्न = ''कौन'' (बाहर कौन है?); अप्राणीवाचक प्रश्न = ''क्या'' (हाथ में क्या है?)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dab9efe9-8dbc-4370-b236-ba6ac3f8149f', '''कौन'' का प्रयोग सजीव प्राणियों (व्यक्तियों) के लिए तथा ''क्या'' का प्रयोग निर्जीव वस्तुओं या घटनाओं के लिए होता है', true, 'f05727d4-27ef-413c-a5f6-2a050d3f31d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2773cc56-4c7d-4510-a9ec-c93b8b001f9f', '''क्या'' केवल इंसानों के लिए आता है', false, 'f05727d4-27ef-413c-a5f6-2a050d3f31d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d13dab8-3ee7-4a5a-a6ee-e324793d087e', 'दोनों केवल जानवरों के लिए आते हैं', false, 'f05727d4-27ef-413c-a5f6-2a050d3f31d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c5d1bf8-2adc-46c6-ab49-d2911f5f071e', 'कोई नियम नहीं है', false, 'f05727d4-27ef-413c-a5f6-2a050d3f31d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1f119cb-d02f-40fa-a97c-fee26e46aa9a', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'वाक्य में प्रयुक्त रेखांकित पद का सर्वनाम भेद बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ed5a658-4e53-4c64-8262-66f2f5a45799', 'अन्य पुरुषवाचक सर्वनाम (आदरार्थक रूप में किसी तीसरे ऐतिहासिक महापुरुष के परिचय में ''आप'' का प्रयोग)', true, 'e1f119cb-d02f-40fa-a97c-fee26e46aa9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0de23e4-a6bc-49e8-9a9f-c628116dd094', 'मध्यम पुरुष', false, 'e1f119cb-d02f-40fa-a97c-fee26e46aa9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec06c7ac-21a1-4d47-afc7-d88b0223a8c2', 'निजवाचक', false, 'e1f119cb-d02f-40fa-a97c-fee26e46aa9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65f3c73a-ab9d-4f97-9b0a-42ff965118f7', 'अनिश्चयवाचक', false, 'e1f119cb-d02f-40fa-a97c-fee26e46aa9a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36a77496-be94-4a23-843e-921161702f34', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'सर्वनाम के साथ जब दो कारक चिह्न (विभक्तियाँ) एक साथ आती हैं, तो उन्हें कैसे लिखा जाता है?', 'मानक हिंदी वर्तनी नियम: ''उसके लिए'' में पहला परसर्ग ''के'' संश्लिष्ट तथा दूसरा ''लिए'' विश्लिष्ट लिखा जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f718f16-ed73-4fdf-8d13-0e209261b77f', 'पहला कारक चिह्न सर्वनाम से मिलाकर और दूसरा अलग लिखा जाता है (जैसे: ''उसके लिए'', ''उनमें से'')', true, '36a77496-be94-4a23-843e-921161702f34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fd3ef27-0e6b-4f14-bd04-1b59fdc2f497', 'दोनों मिलाकर लिखे जाते हैं (''उसकेलिए'')', false, '36a77496-be94-4a23-843e-921161702f34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cd3ec69-90e2-4135-b1da-8c39baad3b3d', 'दोनों अलग लिखे जाते हैं (''उस के लिए'')', false, '36a77496-be94-4a23-843e-921161702f34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74a1c249-85a8-47ae-8ebe-c8926865ae60', 'कारक चिह्न कभी नहीं आते', false, '36a77496-be94-4a23-843e-921161702f34');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d4ddac6-94f1-4023-a941-0310902543d0', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Medium', 'वाक्य में प्रयुक्त रेखांकित पद का सर्वनाम भेद बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50504871-27ce-40c8-915f-b0c635398966', 'संबंधवाचक सर्वनाम', true, '3d4ddac6-94f1-4023-a941-0310902543d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27217380-d455-4b3c-86fd-6d4a9b2c33b9', 'निश्चयवाचक सर्वनाम', false, '3d4ddac6-94f1-4023-a941-0310902543d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9258d809-0f2c-4193-87d8-34d271f9192d', 'निजवाचक सर्वनाम', false, '3d4ddac6-94f1-4023-a941-0310902543d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13346bf4-8f77-4bce-8a7b-18dd730e767d', 'प्रश्नवाचक सर्वनाम', false, '3d4ddac6-94f1-4023-a941-0310902543d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e569fc64-a16e-4571-9739-90b84d00dae1', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f36c784-9576-4667-98bf-971cd58e0f9d', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'e569fc64-a16e-4571-9739-90b84d00dae1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3f0267f-a859-4993-aa3f-932756da5dff', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'e569fc64-a16e-4571-9739-90b84d00dae1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6c6c47f-cb86-4783-99e2-8316d2b194b0', '(A) सही है, परन्तु (R) गलत है।', false, 'e569fc64-a16e-4571-9739-90b84d00dae1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f859507-ed37-48e0-8204-bc54c3cb8143', '(A) गलत है, परन्तु (R) सही है।', false, 'e569fc64-a16e-4571-9739-90b84d00dae1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('57590d6e-3728-4ba0-940f-8812b98babcd', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'Spot the IMPOSTER in the following group of सर्वनाम और उनके भेदों के युग्म में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bc8d9dc-642d-40e7-a36b-fd5a07f4c427', 'हम - उत्तम पुरुष', false, '57590d6e-3728-4ba0-940f-8812b98babcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f33fe5f-056f-46cd-8bdd-4a3f9ff1702a', 'तुम - मध्यम पुरुष', false, '57590d6e-3728-4ba0-940f-8812b98babcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a12dcf7d-a1b8-4a66-9673-0cbf27131227', 'कोई - अनिश्चयवाचक', false, '57590d6e-3728-4ba0-940f-8812b98babcd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a109fa5-c708-4e7c-b91f-16b796790a68', 'स्वयं - प्रश्नवाचक', true, '57590d6e-3728-4ba0-940f-8812b98babcd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78f7e0d6-e02a-4682-b109-2840f256eb70', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'सुमेलित कीजिए (सर्वनाम शब्द और उनके व्याकरणिक भेद):
(क) हम      -> (i) अनिश्चयवाचक सर्वनाम
(ख) कोई     -> (ii) उत्तम पुरुषवाचक सर्वनाम
(ग) जो-वह   -> (iii) निजवाचक सर्वनाम
(घ) अपने आप -> (iv) संबंधवाचक सर्वनाम', 'हम = उत्तम पुरुष; कोई = अनिश्चयवाचक; जो-वह = संबंधवाचक; अपने आप = निजवाचक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18eb01fe-8625-4219-8247-0a2fc8e59451', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', true, '78f7e0d6-e02a-4682-b109-2840f256eb70');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c4df409-11b4-4c05-8b9e-e68ef032a52f', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, '78f7e0d6-e02a-4682-b109-2840f256eb70');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36aba590-773f-4d10-86c0-7e5c6d683e15', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '78f7e0d6-e02a-4682-b109-2840f256eb70');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7062015f-911b-4f63-9376-b03a1fef356b', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '78f7e0d6-e02a-4682-b109-2840f256eb70');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f47b2ff4-265c-438b-a5bd-3bc15a47fbe6', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'निम्नलिखित वाक्य में प्रयुक्त सर्वनामों की सही संख्या और भेद पहचानिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26e6b4f0-04a7-41ae-8a02-37652f5981bd', '5 सर्वनाम पद (मैं = उत्तम पुरुष, अपना = निजवाचक, स्वयं = निजवाचक, उसे = अन्य पुरुष, कुछ = अनिश्चयवाचक)', true, 'f47b2ff4-265c-438b-a5bd-3bc15a47fbe6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc43cece-035a-4f7f-845f-06a09cd0869c', '3 सर्वनाम पद', false, 'f47b2ff4-265c-438b-a5bd-3bc15a47fbe6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90634a0a-942d-4cf7-9a97-b62155236d59', '2 सर्वनाम पद', false, 'f47b2ff4-265c-438b-a5bd-3bc15a47fbe6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95510955-7dd9-405d-91d2-026fc5c77c44', '6 सर्वनाम पद', false, 'f47b2ff4-265c-438b-a5bd-3bc15a47fbe6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f8a52a80-1424-4f93-b4ef-ae19b21d1517', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'सर्वनाम शब्दों में किस कारक की विभक्ति का प्रयोग पूर्णतः वर्जित होता है (अर्थात् वह कारक सर्वनाम में नहीं होता)?', 'सर्वनाम में संबोधन कारक नहीं होता; अतः सर्वनाम के 7 कारक रूप ही बनते हैं (संबोधन रहित)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df65fd91-a2e2-4092-9951-237d838bfaf0', 'संबोधन कारक (हे!, अरे! - सर्वनामों का संबोधन नहीं होता, जैसे ''हे तुम!'', ''अरे मैं!'' अमानक हैं)', true, 'f8a52a80-1424-4f93-b4ef-ae19b21d1517');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08be4e08-6d6b-4c95-aec8-f1d6d6e038bc', 'कर्ता कारक', false, 'f8a52a80-1424-4f93-b4ef-ae19b21d1517');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b801f76-6318-4d7e-9d4a-795f0cc12520', 'अधिकरण कारक', false, 'f8a52a80-1424-4f93-b4ef-ae19b21d1517');
