INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5a75278e-696f-4203-b56c-397c58183f5f', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'अनिश्चयवाचक सर्वनाम ''कोई'' का तिर्यक (सपरसर्ग) बहुवचन रूप क्या होता है?', '''कोई'' का एकवचन तिर्यक ''किसी'' तथा बहुवचन तिर्यक ''किन्हीं'' (किन्हीं ने, किन्हीं को) होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4b21377-a038-4607-9555-be24cb8a2ba0', 'किन्हीं (जैसे: ''किन्हीं लोगों ने कहा'', ''किन्हीं को बुलाओ'')', true, '5a75278e-696f-4203-b56c-397c58183f5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9463d1d2-e842-467e-a798-df04722ecef1', 'कोइयों', false, '5a75278e-696f-4203-b56c-397c58183f5f');
