INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b599117a-fa33-4f5d-8211-c4846774ab02', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'सर्वनाम शब्द ''क्या'' का प्रयोग जब विस्मय (आश्चर्य) प्रकट करने के लिए होता है (जैसे: ''क्या शानदार दृश्य है!''), तो वह क्या कहलाता है?', 'यहाँ प्रश्न न पूछकर विस्मय/प्रशंसा की जा रही है, अतः यह विस्मयादिबोधक अव्यय के रूप में प्रयुक्त हुआ है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ade0f98-ab56-4c7a-b145-613b48ef3b6b', 'विस्मयादिबोधक अव्यय रूप', true, 'b599117a-fa33-4f5d-8211-c4846774ab02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7661984c-eb1e-4c61-bcfc-8a8a84e0e14d', 'प्रश्नवाचक सर्वनाम', false, 'b599117a-fa33-4f5d-8211-c4846774ab02');
