INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eaab249c-5b03-4d16-b666-8443b614fd7a', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'वाक्य में प्रयुक्त रेखांकित पदों के सर्वनाम भेदों का सही क्रम बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94999470-91f4-4113-b472-88c0eda260d6', 'आप = मध्यम पुरुष ; मैं = उत्तम पुरुष ; स्वयं = निजवाचक ; कौन = प्रश्नवाचक', true, 'eaab249c-5b03-4d16-b666-8443b614fd7a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5616c481-19cc-4827-b6cb-bace8cb04ad7', 'आप = निजवाचक ; मैं = अन्य पुरुष ; स्वयं = मध्यम पुरुष ; कौन = अनिश्चयवाचक', false, 'eaab249c-5b03-4d16-b666-8443b614fd7a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c1d125e-b231-49e9-a5b1-485857ca9d55', 'चारों पुरुषवाचक हैं', false, 'eaab249c-5b03-4d16-b666-8443b614fd7a');
