INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b8160a1-27f5-4f3e-b223-48908bd5641f', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'वाक्य को मानक हिंदी व्याकरण के अनुसार शुद्ध कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b9314a5-c7ea-40d4-8c4a-4da5a352e43e', 'तुझे क्या चाहिए? (या ''आपको क्या चाहिए?'')', true, '2b8160a1-27f5-4f3e-b223-48908bd5641f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fb34729-4f89-4e8a-9c0e-ca639dcf87ff', 'तेरे को क्या मंगता?', false, '2b8160a1-27f5-4f3e-b223-48908bd5641f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('991d868e-2c2c-4b2f-83ca-ee40219d010a', 'तू को क्या चाहिए?', false, '2b8160a1-27f5-4f3e-b223-48908bd5641f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9f8d4a8-aba7-43c2-b68c-61e4d1d14a19', 'तेरा क्या चाहिए?', false, '2b8160a1-27f5-4f3e-b223-48908bd5641f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20b8ee29-5511-4461-ac64-34deab4fb5fe', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'संयुक्त सर्वनाम (Compound Pronoun) का सही उदाहरण कौन-सा है?', 'डॉ. दीमशित्स के अनुसार दो सर्वनामों के संयोग से बनने वाले पद ''संयुक्त सर्वनाम'' कहलाते हैं (जो कोई, कोई न कोई, सब कुछ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11415a63-6b4d-4949-ae7e-722a4da0241a', 'जो कोई, कोई न कोई, कुछ न कुछ, सब कुछ, और कोई', true, '20b8ee29-5511-4461-ac64-34deab4fb5fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96b7a9f6-11c3-4d9f-91f6-d2fe4175c24a', 'केवल ''मैं'' और ''तुम''', false, '20b8ee29-5511-4461-ac64-34deab4fb5fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dd2f0f7-ae29-4bf4-b524-589807a0b36b', 'केवल ''यह'' और ''वह''', false, '20b8ee29-5511-4461-ac64-34deab4fb5fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f41c4e9-9c1a-40d4-80ca-68ff8ad89080', 'संज्ञा और क्रिया', false, '20b8ee29-5511-4461-ac64-34deab4fb5fe');
