INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6022e18-2424-447e-9317-4c4127f68c3d', 'निश्चयवाचक सर्वनाम', false, '802b6641-7ba6-42e5-8fe0-adefa9d52f90');
