INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91c821e4-5835-4a6f-a582-0ea0a9e442ef', 'Class 6', 'Hindi Grammar', 'Chapter 8: सर्वनाम', 'Hard', 'सर्वनाम की उपयोगिता के संदर्भ में कौन-सा कथन सर्वाधिक सटीक है?', 'संज्ञा की बार-बार होने वाली अप्रिय पुनरावृत्ति से मुक्ति दिलाकर भाषा में प्रवाह और लालित्य उत्पन्न करना सर्वनाम का मुख्य प्रयोजन है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9127fcde-d2b8-4617-a718-774b60299c37', 'सर्वनाम भाषा को सहज, संक्षिप्त, प्रवाहपूर्ण और पुनरुक्ति दोष से मुक्त बनाते हैं, जिससे भाषा की अभिव्यक्ति क्षमता उत्कृष्ट हो जाती है', true, '91c821e4-5835-4a6f-a582-0ea0a9e442ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb167009-4a5f-4fec-9f84-1901dc481751', 'सर्वनाम केवल संस्कृत में उपयोगी हैं', false, '91c821e4-5835-4a6f-a582-0ea0a9e442ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb62de04-2b9a-41a9-adc7-34238e52bb73', 'सर्वनाम से वाक्य कठिन हो जाते हैं', false, '91c821e4-5835-4a6f-a582-0ea0a9e442ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d7f36ed-03fd-49da-b6c1-d96844255109', 'सर्वनाम का कोई व्याकरणिक महत्व नहीं है', false, '91c821e4-5835-4a6f-a582-0ea0a9e442ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4997b9bc-a59d-4f1d-b2d5-67ef24e6fe91', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'What is a portable source of electricity that produces electric current from chemicals stored inside it?', 'An electric cell converts internal chemical energy into electrical energy through electrochemical reactions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8643fac3-ccc9-48a8-af4c-cd47cabd3c7b', 'Electric Cell (Dry Cell / Battery)', true, '4997b9bc-a59d-4f1d-b2d5-67ef24e6fe91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98e721dd-634c-4707-9df2-cca8719943d1', 'Electric Switch', false, '4997b9bc-a59d-4f1d-b2d5-67ef24e6fe91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3dfc0a5-90d3-4f97-a4b9-01426853fa7d', 'Electric Bulb', false, '4997b9bc-a59d-4f1d-b2d5-67ef24e6fe91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e73bb4a-b884-4735-9627-41f601603e7f', 'Conductor', false, '4997b9bc-a59d-4f1d-b2d5-67ef24e6fe91');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4cf7f962-01f7-4413-a830-3f3292858eed', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'How many terminals does an electric cell have?', 'The metal cap on top is the Positive (+) terminal, while the flat metal disc at the base is the Negative (-) terminal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('251b7812-e41b-4108-9ed3-3236003bf674', 'Two terminals (a Positive terminal marked ''+'' and a Negative terminal marked ''-'')', true, '4cf7f962-01f7-4413-a830-3f3292858eed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58541e6c-5dcc-48c6-842f-f0c3640dab80', 'One terminal', false, '4cf7f962-01f7-4413-a830-3f3292858eed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41247f1a-da3f-421a-98a5-286260d5c77c', 'Three terminals', false, '4cf7f962-01f7-4413-a830-3f3292858eed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00742d26-9595-4f41-83d8-2805ec0340a7', 'Four terminals', false, '4cf7f962-01f7-4413-a830-3f3292858eed');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5a06ef6-ca75-4c2c-9848-7f5f6a0e35cc', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'What is the tiny, thin coiled metallic wire inside an incandescent bulb that glows white-hot and emits light when electricity passes through it?', 'The high-resistance tungsten filament heats up due to Joule heating, glowing incandescently to emit visible light.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff7bb023-b810-465e-a25c-694d69abe0cf', 'Filament (made of Tungsten)', true, 'a5a06ef6-ca75-4c2c-9848-7f5f6a0e35cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba7588ec-5816-4b53-8346-1619d6ea8951', 'Terminal', false, 'a5a06ef6-ca75-4c2c-9848-7f5f6a0e35cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fed43aee-4c1c-4fa2-9724-8c6e6cf31690', 'Switch', false, 'a5a06ef6-ca75-4c2c-9848-7f5f6a0e35cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22c9634a-a227-47af-9c17-d498bd8bc90c', 'Insulator', false, 'a5a06ef6-ca75-4c2c-9848-7f5f6a0e35cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ff78487-e69f-4acf-938f-6a2a359866a6', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'A simple electrical device used to either break (open) an electric circuit or complete (close) it is called a:', 'An electrical switch acts as a mechanical gate opening or closing the conductive loop.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbada631-8193-40ee-8190-50216fa93eed', 'Switch', true, '7ff78487-e69f-4acf-938f-6a2a359866a6');
