INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ad219a2-597b-44d0-aba9-5a996cbefd45', 'Cell', false, '7ff78487-e69f-4acf-938f-6a2a359866a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18843a8f-11d0-4d5c-91bf-3f3493495f36', 'Fuse', false, '7ff78487-e69f-4acf-938f-6a2a359866a6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b87ec4c6-7871-44cc-9cb7-edd98b618692', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'Materials that allow electric current to pass through them easily (such as copper wire, aluminium, iron, silver) are called:', 'Conductors possess abundant free delocalized valence electrons that facilitate electric charge flow.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1be524d9-6034-407c-a0e4-e2683e94de47', 'Conductors of Electricity', true, 'b87ec4c6-7871-44cc-9cb7-edd98b618692');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('416b9ad4-fd51-4461-a49d-68f455f8f419', 'Insulators', false, 'b87ec4c6-7871-44cc-9cb7-edd98b618692');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed3fa894-afec-4c2e-a43b-edbf6f3b6ba4', 'Semiconductors', false, 'b87ec4c6-7871-44cc-9cb7-edd98b618692');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4320c9e2-429e-44f4-b439-d040c86d5c8f', 'Dielectrics', false, 'b87ec4c6-7871-44cc-9cb7-edd98b618692');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f2830073-1c2b-4ce8-b60a-a080b01525c7', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'Materials that do NOT allow electric current to pass through them (such as rubber, plastic, dry wood, glass) are called:', 'Insulators have tightly bound localized valence electrons with high dielectric resistivity, blocking electrical conduction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c84ab9d-d5ce-4ca6-9df6-d418305008c7', 'Insulators of Electricity', true, 'f2830073-1c2b-4ce8-b60a-a080b01525c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('593235c4-9fd8-410c-a4d3-c8f0cfdea04c', 'Conductors', false, 'f2830073-1c2b-4ce8-b60a-a080b01525c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7444074-9f17-4554-b863-6ff4d4560430', 'Metals', false, 'f2830073-1c2b-4ce8-b60a-a080b01525c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49797411-34e8-42f1-b337-5de8673e7b9a', 'Electrolytes', false, 'f2830073-1c2b-4ce8-b60a-a080b01525c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56ffbe4b-a7a5-4f92-8db1-a72dc89e894d', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'What is the conventional direction of electric current flow in an electric circuit?', 'By historical convention, current is defined as positive charge flow moving from the positive (+) to negative (-) terminal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38ccb0de-e763-42be-85c5-f2d92d2ad464', 'From the Positive (+) terminal to the Negative (-) terminal of the electric cell', true, '56ffbe4b-a7a5-4f92-8db1-a72dc89e894d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3cf86a6-6068-48e5-9c6d-10ab760e710b', 'From the Negative (-) terminal to the Positive (+) terminal', false, '56ffbe4b-a7a5-4f92-8db1-a72dc89e894d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4838f14e-1b04-4ed1-aa98-ee6cb705aff9', 'From both terminals at the same time', false, '56ffbe4b-a7a5-4f92-8db1-a72dc89e894d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('410ba88d-9908-4e6d-ab2f-20160a5461c9', 'Current does not have any direction', false, '56ffbe4b-a7a5-4f92-8db1-a72dc89e894d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b3b00c4f-5bc4-4032-b5b4-ae701c3d04da', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'Why does an electric bulb NOT glow when its internal filament is broken (fused bulb)?', 'A severed filament breaks electrical continuity, preventing loop closure and extinguishing electron drift.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c226ddb6-0759-4c7c-a370-f78df7a99671', 'Because a broken filament creates a gap in the path, resulting in an Incomplete (Open) Circuit through which current cannot flow', true, 'b3b00c4f-5bc4-4032-b5b4-ae701c3d04da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27456b16-0c6d-4bc2-bf7d-4ae447af7d26', 'Because the glass melts', false, 'b3b00c4f-5bc4-4032-b5b4-ae701c3d04da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58bd2e97-3dc6-4903-b8ba-57f61c80a933', 'Because the cell explodes', false, 'b3b00c4f-5bc4-4032-b5b4-ae701c3d04da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01746559-2da8-4251-a5ed-8e20696bd598', 'Because light leaks out of the hole', false, 'b3b00c4f-5bc4-4032-b5b4-ae701c3d04da');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b5f92364-f99c-4c65-8ccb-93b551c5f5f8', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'Why are electrical wires and screwdriver handles coated with Rubber or Plastic?', 'Insulating polymer sleeves shield against direct galvanic human contact with live energized conductors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8e2d84a-a0ed-4603-abb4-e7d3b3051313', 'Rubber and plastic are electrical Insulators that protect electricians and users from dangerous electric shocks', true, 'b5f92364-f99c-4c65-8ccb-93b551c5f5f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db0e034f-05f5-49fb-869d-cb019f791e51', 'To make wires look colorful and shiny', false, 'b5f92364-f99c-4c65-8ccb-93b551c5f5f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01d98c70-f952-470c-acad-8550f16d2876', 'To make wires heavier', false, 'b5f92364-f99c-4c65-8ccb-93b551c5f5f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c969f2d-bf40-435c-bda6-125e8b348122', 'Because metals melt in air', false, 'b5f92364-f99c-4c65-8ccb-93b551c5f5f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('021bb41d-bb65-4bfe-99c0-3b57ccbe530a', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'Is the human body a Conductor or an Insulator of electricity?', 'Saline electrolytes in blood and tissues render the human body conductive, which is why electric shocks occur.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4358507-25a2-4c01-bb50-57a47430ac6f', 'A Conductor of electricity (since our body fluid contains dissolved mineral salts and water)', true, '021bb41d-bb65-4bfe-99c0-3b57ccbe530a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98ce6ee7-82fa-4e77-b09d-41310fab5f95', 'An Insulator', false, '021bb41d-bb65-4bfe-99c0-3b57ccbe530a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('356f59dd-a247-497c-aac7-b7d7eb5a98d1', 'Neither', false, '021bb41d-bb65-4bfe-99c0-3b57ccbe530a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b0aa93b-e384-44bd-ae22-6c70c0091308', 'Only our hair conducts electricity', false, '021bb41d-bb65-4bfe-99c0-3b57ccbe530a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7b6dce07-e8da-435c-bc2a-4e38d8d4aab1', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'What happens if the two terminals of an electric cell are connected directly with a wire WITHOUT connecting a bulb or switch?', 'A direct zero-resistance short-circuit produces high discharge current, rapidly draining chemical potential and overheating the cell.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('596af8c9-beba-4044-874c-8e156906c87c', 'The chemicals in the cell get exhausted very rapidly, generating dangerous heat that can damage the cell (Short Circuit)', true, '7b6dce07-e8da-435c-bc2a-4e38d8d4aab1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c407541-fe88-4322-b2de-faed288a5202', 'The wire turns into gold', false, '7b6dce07-e8da-435c-bc2a-4e38d8d4aab1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b181937-31b8-4ba5-b115-3341a0c177c1', 'The cell charges to 1000 volts', false, '7b6dce07-e8da-435c-bc2a-4e38d8d4aab1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1aade84-02f3-411b-b2f5-9a7411d3fb05', 'Nothing happens', false, '7b6dce07-e8da-435c-bc2a-4e38d8d4aab1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4eeb6d9f-803d-4d1f-8bcb-868223c00aa0', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Easy', 'Which metal is the MOST COMMONLY used for making domestic electrical connecting wires due to its high conductivity and affordability?', 'Copper has exceptionally low electrical resistivity, high ductility, and corrosion resistance, making it the industry standard.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('577c7b29-dcd4-4155-ab30-85b400d07fbf', 'Copper (and Aluminium)', true, '4eeb6d9f-803d-4d1f-8bcb-868223c00aa0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f61ce509-d741-4f85-b698-d67fa88c0805', 'Iron', false, '4eeb6d9f-803d-4d1f-8bcb-868223c00aa0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e19e650e-5a4e-4878-8bc0-6bf5d79d7cce', 'Lead', false, '4eeb6d9f-803d-4d1f-8bcb-868223c00aa0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c391bf46-164e-422f-8a07-e8dc6f5be668', 'Mercury', false, '4eeb6d9f-803d-4d1f-8bcb-868223c00aa0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d31d28c-e4b0-4ec7-9eca-ded35c7422c5', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'What is an ''Electric Circuit'' in physics?', 'An electric circuit provides a closed continuous conducting path for circulating electric charges.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65d4f598-e8d4-4a52-bd7f-25dc9ff75c6c', 'A complete, unbroken closed conducting loop through which electric current can flow continuously from one terminal of the source to the other', true, '1d31d28c-e4b0-4ec7-9eca-ded35c7422c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75675454-dbfb-456d-a9e8-ec931b8d2681', 'A machine that makes electricity from coal', false, '1d31d28c-e4b0-4ec7-9eca-ded35c7422c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8448d927-6751-4418-ad30-a01436f302c0', 'A broken wire hanging in air', false, '1d31d28c-e4b0-4ec7-9eca-ded35c7422c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('800488ee-a082-4346-bffa-e3c72b991eea', 'A battery inside a toy', false, '1d31d28c-e4b0-4ec7-9eca-ded35c7422c5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('786db54d-0444-4939-92a7-5d4a82486e7f', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'What is the difference between a ''Closed Circuit'' and an ''Open Circuit''?', 'Closed = complete conducting loop (current flows); Open = disconnected path (infinite resistance, zero current).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('666518b8-14d5-414e-a14d-07a13101a638', 'In a Closed Circuit, the conducting path is completely unbroken and current flows to glow the bulb; in an Open Circuit, there is a break or open switch, stopping current flow', true, '786db54d-0444-4939-92a7-5d4a82486e7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19d87d5c-a40b-4a71-88bf-1ac45ef3a31a', 'In a Closed Circuit, the switch is OFF', false, '786db54d-0444-4939-92a7-5d4a82486e7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d44ae4db-a146-4bb8-9a2a-dc37b44a0bac', 'In an Open Circuit, electricity flows faster', false, '786db54d-0444-4939-92a7-5d4a82486e7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca20aed1-8f81-441f-9fa2-1bd2fccf3f50', 'There is no difference', false, '786db54d-0444-4939-92a7-5d4a82486e7f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93675c94-1bee-4555-bdbc-24fc7d58f1b2', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'How can a student build a simple DIY electric switch using common household items?', 'The metal safety pin rotates into contact with the second brass drawing pin, completing or opening the conductive circuit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37a5b248-8cc9-4658-aed6-013573b7ae20', 'Using two metal drawing pins pushed into a wooden board, connected by a movable metal safety pin that bridges the gap when rotated', true, '93675c94-1bee-4555-bdbc-24fc7d58f1b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc8eb1b0-a2f0-4299-acf6-50699120f142', 'Using a piece of plastic thread', false, '93675c94-1bee-4555-bdbc-24fc7d58f1b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5f36697-69c9-43c3-9197-6a3286db9c6d', 'Using a rubber eraser', false, '93675c94-1bee-4555-bdbc-24fc7d58f1b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d37d4f1-40b3-4486-be35-568a84234386', 'Using a dry stick', false, '93675c94-1bee-4555-bdbc-24fc7d58f1b2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('668ec1c9-45bf-4471-ab6f-5694366d158d', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'What happens when you insert an iron key versus a rubber eraser into the gap of a conduction tester circuit?', 'Iron conducts electrons, completing the circuit; rubber blocks electron flow, leaving the circuit open.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f75e4e11-b762-4409-becf-aa5e9ac6f844', 'With the iron key (conductor), the bulb glows brightly; with the rubber eraser (insulator), the bulb does NOT glow', true, '668ec1c9-45bf-4471-ab6f-5694366d158d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b25b7fde-878d-40f7-aafc-60802a400cb0', 'Both make the bulb glow', false, '668ec1c9-45bf-4471-ab6f-5694366d158d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50afd6e9-fab3-4182-8c08-50270b46c83a', 'Neither makes the bulb glow', false, '668ec1c9-45bf-4471-ab6f-5694366d158d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83a16ec4-bfd5-438d-b81d-0c71a7403e1d', 'The rubber eraser makes the bulb explode', false, '668ec1c9-45bf-4471-ab6f-5694366d158d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66bb4d2d-a596-4c9c-800b-8e209dd517d3', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Why is pure Distilled Water an insulator, whereas ordinary Tap Water / Salty Water is a conductor of electricity?', 'Dissociated cations (Na⁺, Ca²⁺) and anions (Cl⁻, SO₄²⁻) in tap water provide electrolytic charge transport.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc774c7b-0ab9-4dab-8775-fdb973257901', 'Distilled water has no free ions; tap water and saline water contain dissolved mineral salts and electrolytes that dissociate into free charge carriers', true, '66bb4d2d-a596-4c9c-800b-8e209dd517d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d78626b-08ad-4e4e-9003-4f3fc36da547', 'Because tap water is colder', false, '66bb4d2d-a596-4c9c-800b-8e209dd517d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82a08c0d-e186-4119-88f6-18fdcea60d1e', 'Because distilled water is made of oil', false, '66bb4d2d-a596-4c9c-800b-8e209dd517d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e54c35fc-d10a-4e82-98dd-a229bc812154', 'Because salt destroys electricity', false, '66bb4d2d-a596-4c9c-800b-8e209dd517d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecae46d7-d4d9-4a8a-9eb8-519b25c1469a', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Why is graphite (the lead inside a pencil) an exception among non-metals in terms of electrical conductivity?', 'Sp² hybridized carbon sheets in graphite possess free pi electrons, making pencil lead electrically conductive.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75f58bb6-cde3-48a4-961e-d390e02b3a49', 'Graphite is a good conductor of electricity because its layered hexagonal carbon lattice has delocalized pi electrons that move freely', true, 'ecae46d7-d4d9-4a8a-9eb8-519b25c1469a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7c5ffcc-0eab-49c2-bc9f-31052f0a6985', 'Because pencil lead is made of iron', false, 'ecae46d7-d4d9-4a8a-9eb8-519b25c1469a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36f85280-a33f-40e7-bfca-1c4df6a8e2b2', 'Because it is painted black', false, 'ecae46d7-d4d9-4a8a-9eb8-519b25c1469a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f6230fb-a581-43a2-9712-42a99d82a3be', 'Pencils do not conduct electricity', false, 'ecae46d7-d4d9-4a8a-9eb8-519b25c1469a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1014ffc3-7c18-476a-affc-fc91442b4913', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'What are the two thick supporting wires inside an electric bulb attached to?', 'The two lead-in support wires connect the filament ends to two isolated terminal contacts at the bulb base.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43a89b77-6b7e-4142-9c69-cd487942cd06', 'One thick wire is attached to the metal tip at the base, and the other is attached to the metal casing around the base (the two terminals of the bulb)', true, '1014ffc3-7c18-476a-affc-fc91442b4913');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d93b9b1e-2306-42d8-b5b9-94cae17aacc1', 'Both are connected to the glass shell', false, '1014ffc3-7c18-476a-affc-fc91442b4913');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7781cef-e924-4f4e-bee9-9d66ac372a7f', 'Both are connected to the ceiling', false, '1014ffc3-7c18-476a-affc-fc91442b4913');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb62340a-4f9d-41b6-954b-44f051e43cc6', 'They are not connected to anything', false, '1014ffc3-7c18-476a-affc-fc91442b4913');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('560ccc6d-eb73-49c5-a593-0621b656ad8a', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Why should you NEVER touch an electric wall socket or an operating electrical appliance with WET hands?', 'Wet skin impedance drops from 100,000 Ω to <1,000 Ω, allowing dangerous milliamps of 230V current to pass through the body.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94d1036f-35b3-4734-b2c0-c853ddc01256', 'Water drastically reduces the electrical resistance of human skin, facilitating massive electric shock that can be fatal', true, '560ccc6d-eb73-49c5-a593-0621b656ad8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ab8c0cf-6a2b-4c85-87ef-f5bc1cbf26d9', 'Because water makes the socket dirty', false, '560ccc6d-eb73-49c5-a593-0621b656ad8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7d7bd15-c7da-4914-bbcb-f89019025aca', 'Because the appliance will switch off', false, '560ccc6d-eb73-49c5-a593-0621b656ad8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d06957d-ce28-44af-8a9a-02a28d7ccc71', 'Because water turns into ice', false, '560ccc6d-eb73-49c5-a593-0621b656ad8a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c6f109d-6877-4ab3-8bdc-7972c4c72b5c', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Why do electricians wear thick Rubber Gloves and rubber-soled shoes while repairing electrical installations?', 'Dielectric rubber PPE isolates the worker from electrical grounding, preventing electrocution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8c32975-5cd5-408a-a388-a98d7c0d87e0', 'Rubber is an electrical insulator that breaks any potential ground path for electric current through their body to the earth', true, '0c6f109d-6877-4ab3-8bdc-7972c4c72b5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d30e8310-1eca-4085-afdd-e50e44029551', 'To keep their hands warm in winter', false, '0c6f109d-6877-4ab3-8bdc-7972c4c72b5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60cef47b-5ab2-4db2-99c5-b968df6e9678', 'To improve their grip on tools', false, '0c6f109d-6877-4ab3-8bdc-7972c4c72b5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4143e63-3562-4dc2-a515-927f8073559c', 'To follow fashion rules', false, '0c6f109d-6877-4ab3-8bdc-7972c4c72b5c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ee47061-563c-4ffd-85fe-af59f5a59b38', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'What is an ''Electric Torch'' and how does it function when switched ON?', 'Sliding the switch closes the internal spring-contact circuit, illuminating the bulb backed by a parabolic reflector.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef4d71fd-7248-419b-9fc2-03e8ec47daff', 'The slide switch pushes a metal contact strip against the bulb base, completing the closed circuit between cells, reflector, and bulb', true, '3ee47061-563c-4ffd-85fe-af59f5a59b38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51c09f49-0b5e-4f8b-a169-dd4f1a14b325', 'It uses burning oil', false, '3ee47061-563c-4ffd-85fe-af59f5a59b38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd7a5d35-3b27-4b47-bd61-8e39ecfe0560', 'It catches sunlight in a glass', false, '3ee47061-563c-4ffd-85fe-af59f5a59b38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f367734e-208a-4e7b-9384-9a2664c3702f', 'It generates electricity from air', false, '3ee47061-563c-4ffd-85fe-af59f5a59b38');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ad23d86-8021-40d7-94a4-14ad0afaa0f9', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Why is Tungsten metal specifically chosen to make the filament of an electric incandescent bulb?', 'Tungsten sustains operating temperatures over 2,500°C due to its record metallic melting point of 3,422°C.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f43e77f-52d9-4d01-8a1b-7a367f96ecee', 'It has an exceptionally high melting point (~3422°C) and high electrical resistance, glowing white-hot without melting', true, '7ad23d86-8021-40d7-94a4-14ad0afaa0f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb060067-bc23-4f03-9f6d-e3e9d5651d46', 'Because it is very cheap', false, '7ad23d86-8021-40d7-94a4-14ad0afaa0f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98ac84df-94da-4832-9a2d-d0137c3eff60', 'Because it is a liquid at room temperature', false, '7ad23d86-8021-40d7-94a4-14ad0afaa0f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5547f567-4556-434f-8f8a-1a1d9101af1c', 'Because it is transparent', false, '7ad23d86-8021-40d7-94a4-14ad0afaa0f9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b3683f91-17ad-4b17-b060-5092a8ce3320', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Why should we NEVER use the electric current from domestic 230V AC mains wall sockets for classroom experiments?', 'Domestic 230V mains is lethal; educational circuits must strictly use low-voltage 1.5V DC dry cells for complete safety.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b3f18c9-00b3-422e-920d-dec6696e8924', '230V AC mains current carries lethal power that can cause fatal electric shocks and fires; school experiments must strictly use small 1.5V DC electric cells', true, 'b3683f91-17ad-4b17-b060-5092a8ce3320');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33c95f82-73d4-4af2-aea2-04e3e01c53fd', 'Because the school bill will be too high', false, 'b3683f91-17ad-4b17-b060-5092a8ce3320');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1f1c7ec-8214-4e03-b730-b03fe04dddd3', 'Because wall sockets do not work during the day', false, 'b3683f91-17ad-4b17-b060-5092a8ce3320');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cb039ba-04aa-4e56-92af-43f2cb3d716b', 'Because mains electricity has no voltage', false, 'b3683f91-17ad-4b17-b060-5092a8ce3320');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4287b72b-5483-4b83-b8ed-bdfdde7b99b7', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Which of the following common household objects is an electrical CONDUCTOR?', 'Brass (copper-zinc alloy) and aluminium foil are metallic conductors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9fcf049-6d81-4211-8306-f97ae0559287', 'Brass key and aluminium foil', true, '4287b72b-5483-4b83-b8ed-bdfdde7b99b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec36236f-a4ed-4365-82b8-6de32013a1df', 'Plastic ruler and wooden pencil body', false, '4287b72b-5483-4b83-b8ed-bdfdde7b99b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a325c701-9078-436c-9c0b-ec12f1c260b7', 'Glass bangle and rubber band', false, '4287b72b-5483-4b83-b8ed-bdfdde7b99b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42b474f6-fc7b-4ea1-a498-91ac7e2020c2', 'Cotton cloth and paper sheet', false, '4287b72b-5483-4b83-b8ed-bdfdde7b99b7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a6cf648-c354-4256-89e4-dea811c2af3b', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Which of the following common household objects is an electrical INSULATOR?', 'Polymers, ceramics, elastomers, and celluloid wood are non-conductive electrical insulators.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b30edee-19dc-433b-83b1-c4771f4a57ee', 'Plastic pen body, glass marble, dry rubber eraser, wooden stick', true, '8a6cf648-c354-4256-89e4-dea811c2af3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a59fc6a9-85c2-4a2c-862f-a743ddc1a6ab', 'Iron nail and steel spoon', false, '8a6cf648-c354-4256-89e4-dea811c2af3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d374b211-11ec-4a58-850c-ee145ebb3711', 'Copper wire and gold ring', false, '8a6cf648-c354-4256-89e4-dea811c2af3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15b14b63-9369-45b5-b4de-c0f759deb57d', 'Aluminium key', false, '8a6cf648-c354-4256-89e4-dea811c2af3b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91c24559-3285-4d2e-8282-b152f92998d6', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'Why is air generally classified as a non-conductor (insulator) of electricity?', 'Air has a high dielectric breakdown threshold (~3 kV/mm); neutral N₂ and O₂ molecules block low-voltage conduction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abede55f-90eb-4e83-a966-30dc823e6b69', 'Dry atmospheric air consists of neutral gas molecules without free charge carriers, preventing electric current from jumping across open gaps under normal voltages', true, '91c24559-3285-4d2e-8282-b152f92998d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5f83380-8a42-46a7-9774-1e44d6ac135b', 'Because air is too light', false, '91c24559-3285-4d2e-8282-b152f92998d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80bc2b24-d0ae-4df0-8ec8-8557e8679e8b', 'Because air has no oxygen', false, '91c24559-3285-4d2e-8282-b152f92998d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('062866f3-307a-4588-8d2d-7ec657e26588', 'Because air only conducts heat', false, '91c24559-3285-4d2e-8282-b152f92998d6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5edb89e7-5d07-45ce-96c2-05bb070f7d9b', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Medium', 'What warning sign featuring a skull and crossed bones is prominently displayed on electrical substations and transformers?', 'The skull and crossbones caution sign warns of lethal high-voltage electrocution hazards.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('747ee99b-391f-41a8-b2be-dee2b51e55cf', 'DANGER - High Voltage Electric Shock Hazard', true, '5edb89e7-5d07-45ce-96c2-05bb070f7d9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26e99c81-651e-4344-a6f2-f4c0d78335eb', 'Hospital zone', false, '5edb89e7-5d07-45ce-96c2-05bb070f7d9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41d0c44b-9fcf-4022-a601-6cbe64ab4010', 'No parking', false, '5edb89e7-5d07-45ce-96c2-05bb070f7d9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f206a9e-e1fe-40e9-8e7a-35937b3488cb', 'Speed breaker ahead', false, '5edb89e7-5d07-45ce-96c2-05bb070f7d9b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa9adde0-c7e1-4272-ad19-e589bacd7335', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0976b8e1-094c-4d45-a56c-2f38c97edd3c', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'aa9adde0-c7e1-4272-ad19-e589bacd7335');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9e369fa-1860-4136-bd1f-1e3c4a682588', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'aa9adde0-c7e1-4272-ad19-e589bacd7335');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83fd1fb1-32cc-44c9-9a53-0f076d7bc4d4', '(A) is true, but (R) is false.', false, 'aa9adde0-c7e1-4272-ad19-e589bacd7335');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88ca2996-3b99-48fd-931b-94c8b8db110b', '(A) is false, but (R) is true.', false, 'aa9adde0-c7e1-4272-ad19-e589bacd7335');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed653720-c1e6-48be-befa-e5febe6a60f1', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'Spot the IMPOSTER in the following group of materials classified by their electrical conductivity:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0450ef45-6757-47dc-9bf3-129ba32a3c26', 'Silver (Conductor)', false, 'ed653720-c1e6-48be-befa-e5febe6a60f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6af8341-86c4-4a91-b8ba-f5c413a5dfcc', 'Copper (Conductor)', false, 'ed653720-c1e6-48be-befa-e5febe6a60f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c7c4be3-b8f5-45cd-ae83-0ad93852a58c', 'Graphite (Conductor)', false, 'ed653720-c1e6-48be-befa-e5febe6a60f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('916fc924-862b-454c-b1ae-74d36002ef18', 'Pure Rubber (Conductor)', true, 'ed653720-c1e6-48be-befa-e5febe6a60f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('397e8f87-9be2-40e9-9dbe-add5a656ebfd', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'A student connects two electric cells in series to power a bulb. Which terminal connection configuration is CORRECT to light up the bulb?', 'Series battery connection requires connecting opposite polarity terminals (+ to -) to add cell voltages (1.5V + 1.5V = 3.0V).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4851f9f-e010-429f-9910-8b33a39f7ea0', 'The Positive (+) terminal of the first cell is connected to the Negative (-) terminal of the second cell in series', true, '397e8f87-9be2-40e9-9dbe-add5a656ebfd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02eb764b-848e-4355-9fb8-2366a6acfe8e', 'Positive connected to Positive', false, '397e8f87-9be2-40e9-9dbe-add5a656ebfd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17ce0e63-448b-4d5d-a16b-89c199fa7dff', 'Negative connected to Negative', false, '397e8f87-9be2-40e9-9dbe-add5a656ebfd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('474016ee-56c9-45e2-82c7-a13e0816121e', 'Connecting only one cell and leaving the other disconnected', false, '397e8f87-9be2-40e9-9dbe-add5a656ebfd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a564b155-3316-4468-9dc2-ccdc1b1353d6', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'Match Column I (Electrical Components) with Column II (Functions):
(a) Electric Cell -> (i) Produces electricity from chemical energy
(b) Switch        -> (ii) Breaks or completes an electric circuit
(c) Filament      -> (iii) Glows incandescently to emit light
(d) Rubber sleeve -> (iv) Insulates and prevents electric shock', 'Cell = chemical energy; Switch = circuit breaker; Filament = light emission; Rubber = insulation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc3e92e5-021a-41a6-a03d-2215125019c8', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'a564b155-3316-4468-9dc2-ccdc1b1353d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a15672d9-e9f8-4fa5-88f6-5519e0be9897', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'a564b155-3316-4468-9dc2-ccdc1b1353d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b261afa-b491-4363-8097-9d68af5caef0', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'a564b155-3316-4468-9dc2-ccdc1b1353d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15efd705-2289-4175-b262-380deb8b18e8', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'a564b155-3316-4468-9dc2-ccdc1b1353d6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('15029eb3-5fac-449f-8c92-bb0da7671bfb', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'Read the statements regarding electric circuits:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ee140cf-9da1-47f3-bbdc-cf204c65c004', 'Statements 1 and 2 only', true, '15029eb3-5fac-449f-8c92-bb0da7671bfb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57f6e2eb-42f7-41be-af89-fa5a0395c2af', 'Statements 2 and 3 only', false, '15029eb3-5fac-449f-8c92-bb0da7671bfb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3325b2fb-c0ac-4391-8281-e26c3cd465a2', 'Statements 1 and 3 only', false, '15029eb3-5fac-449f-8c92-bb0da7671bfb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6369168e-f14d-4745-a77c-5329d8884721', 'All Statements 1, 2, and 3', false, '15029eb3-5fac-449f-8c92-bb0da7671bfb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d164660-a3aa-4b78-a972-728dd8e509cc', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'Why is an incandescent bulb filled with an inert gas like Argon or Nitrogen rather than ordinary air?', 'Inert argon/nitrogen eliminates oxidative combustion of the tungsten filament while suppressing filament thermal evaporation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cf46d7f-dd52-4e76-a74c-964fff98e372', 'Atmospheric oxygen in air would instantly burn and oxidize the white-hot tungsten filament into vapor within seconds; inert gas prevents oxidation', true, '6d164660-a3aa-4b78-a972-728dd8e509cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e441b44-ce8b-4600-8523-7517acd25be2', 'To make the bulb lighter so it can float', false, '6d164660-a3aa-4b78-a972-728dd8e509cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b335d76-6828-42cd-8d4c-9677ab56c16f', 'Because argon makes the bulb green', false, '6d164660-a3aa-4b78-a972-728dd8e509cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2c6221f-e305-4a7c-8a13-1f7dd5360831', 'To cool the glass completely', false, '6d164660-a3aa-4b78-a972-728dd8e509cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4001879-7b46-4bd2-b733-3c82a077f815', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'Consider four test materials placed in the gap of a conduction tester circuit:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be0fa5ec-0833-4aab-a30e-585e9073f6bd', 'Materials 1 and 3 only (Steel and Aluminium)', true, 'd4001879-7b46-4bd2-b733-3c82a077f815');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82351258-6b0a-4317-9b16-9a7b74b03440', 'Materials 2 and 4 only', false, 'd4001879-7b46-4bd2-b733-3c82a077f815');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39762019-a1a3-438c-ab94-830c3f90c189', 'Materials 1, 2, and 3', false, 'd4001879-7b46-4bd2-b733-3c82a077f815');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1009dafb-04e3-4263-a3a1-7e19b7368c66', 'All 4 materials', false, 'd4001879-7b46-4bd2-b733-3c82a077f815');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd34ea4c-8e88-4dbf-874b-a683958eba9a', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'What is the physical reason why a bird perching with BOTH feet on a single bare 11,000V live high-tension electrical wire does NOT get electrocuted?', 'Current requires a potential difference (I = ΔV/R); being at equipotential with no ground circuit prevents current flow through the bird.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6af29d16-6be0-43d4-8b37-fde069b17051', 'Both feet are on the same conductor wire at the exact same electrical potential (voltage), so there is zero potential difference (ΔV = 0) and no current flows through the bird''s body', true, 'fd34ea4c-8e88-4dbf-874b-a683958eba9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9eeff781-dc5c-4a95-a88a-c6e81373e084', 'Because birds have rubber feet', false, 'fd34ea4c-8e88-4dbf-874b-a683958eba9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c322660-8978-442f-be79-001b03fde599', 'Because high voltage cannot hurt animals', false, 'fd34ea4c-8e88-4dbf-874b-a683958eba9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf2be150-c78c-49eb-b7f4-b90989a28aeb', 'Because birds fly faster than current', false, 'fd34ea4c-8e88-4dbf-874b-a683958eba9a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f24f5bb5-84d6-4113-9ac4-27014e97aa1c', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'What is a ''Light Emitting Diode'' (LED) and why is it rapidly replacing traditional tungsten incandescent bulbs in modern lighting?', 'Solid-state electroluminescence in LEDs achieves high luminous efficacy (>100 lm/W) without incandescent thermal waste.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6959187b-b99c-467c-a513-f777a9eb8342', 'A semiconductor diode that converts electrical energy directly into light with minimal heat generation, consuming up to 85% less electricity and lasting 25 times longer', true, 'f24f5bb5-84d6-4113-9ac4-27014e97aa1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7c355f1-db3d-4e3f-b425-98ada0255ad6', 'A bulb that works on kerosene', false, 'f24f5bb5-84d6-4113-9ac4-27014e97aa1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b9db8b9-f53d-4d86-97b9-0866147706e1', 'A chemical candle in a tube', false, 'f24f5bb5-84d6-4113-9ac4-27014e97aa1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('080c9761-e419-46c1-92b9-0d16640e01b8', 'A battery that shines on its own', false, 'f24f5bb5-84d6-4113-9ac4-27014e97aa1c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('137b290d-db1d-4c00-a21a-e59f2eef471d', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'Why must the metal terminals of an electric cell and connecting wires be scraped clean with sandpaper before making circuit connections?', 'Abrasive cleaning strips insulating metal oxide tarnish films, establishing pristine low-impedance galvanic contact.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89b2c121-3673-4a7b-8d11-3a4e1a623ea9', 'To remove non-conductive oxide layers, dirt, or lacquer coatings on the metal surface that create high contact resistance and block electric flow', true, '137b290d-db1d-4c00-a21a-e59f2eef471d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f36effe3-05fd-49b6-b68b-eaadc987ca7a', 'To make the wire shiny', false, '137b290d-db1d-4c00-a21a-e59f2eef471d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5165cf1-17d2-4579-a20b-fba43eefd0ed', 'To change the wire''s color', false, '137b290d-db1d-4c00-a21a-e59f2eef471d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('331dc0ca-8960-4215-b381-fcd991a4bd62', 'To make the wire thinner', false, '137b290d-db1d-4c00-a21a-e59f2eef471d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd8f0a23-0747-4ae1-9726-d44027709818', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'What is the primary function of a safety ''Electric Fuse'' in household circuits?', 'A fuse provides over-current protection: excessive fault current melts the fusible alloy link, interrupting the circuit before wires overheat.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69f4e988-601d-4d0f-9c33-764abd674b94', 'A sacrificial safety wire with a low melting point that melts and breaks the circuit automatically if excessive dangerously high current flows', true, 'cd8f0a23-0747-4ae1-9726-d44027709818');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41662e0e-4baa-40d0-b29e-70da07a6f519', 'To store extra electricity for night', false, 'cd8f0a23-0747-4ae1-9726-d44027709818');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3caaf90d-c1f3-4570-adb6-66f9ed47b7ea', 'To make the current flow faster', false, 'cd8f0a23-0747-4ae1-9726-d44027709818');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08484ed3-2534-45d4-aa7e-09a2d38c07a4', 'To turn off the water pump', false, 'cd8f0a23-0747-4ae1-9726-d44027709818');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b4c389f-6915-41b5-a73f-853a76683e05', 'Class 6', 'Science', 'Chapter 9: Electricity and Circuits', 'Hard', 'What is the foundational law of electricity established in physics regarding the conservation of electric charge in any closed circuit?', 'Kirchhoff''s Current Law reflects fundamental charge conservation: net nodal divergence of continuous current is zero.', NOW()) ON CONFLICT DO NOTHING;
