INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('120322fd-2fbc-4e6c-9399-4723d46f9270', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Easy', 'What number is represented by the standard tally marks: 卌 卌 ||| ?', 'Two full 5-bundles (5 + 5 = 10) plus 3 individual strokes equals 13.', NOW()) ON CONFLICT DO NOTHING;
