INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4342b2dc-f7eb-465e-8527-7a38827308e7', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Easy', 'In a pictograph, if one symbol 🚗 represents 10 cars, how many cars are represented by 4 complete car symbols: 🚗🚗🚗🚗 ?', '4 symbols × 10 cars per symbol = 40 cars.', NOW()) ON CONFLICT DO NOTHING;
