INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9aaa0ea4-2508-4732-a2ae-23f38d7b3f3c', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Easy', 'In a pictograph, if one symbol 📖 represents 50 books, how many book symbols are needed to represent 250 books in a school library?', '250 books ÷ 50 books/symbol = 5 symbols.', NOW()) ON CONFLICT DO NOTHING;
