INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5122b63d-5430-44f0-a68a-d7f203fbf475', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Easy', 'If a bar graph uses a scale of ''1 unit length = 5 students'', what is the number of students represented by a bar of height 6 units?', '6 units × 5 students/unit = 30 students.', NOW()) ON CONFLICT DO NOTHING;
