INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('515d9291-b6e6-4d50-821a-c19767216b6b', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'The following are marks scored by 20 students out of 10 in a class test: 5, 8, 4, 7, 5, 8, 6, 7, 5, 9, 8, 5, 6, 4, 7, 5, 6, 8, 9, 5. What is the frequency of mark 5?', 'Counting instances of mark 5 in the list: 5, 5, 5, 5, 5, 5 -> exactly 6 times.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2307dc96-fa1b-4dcf-a4d3-f0b29e59a1db', '6 times (Mark 5 appears 6 times)', true, '515d9291-b6e6-4d50-821a-c19767216b6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2483074-bd0d-49fb-aeb8-b1aba134c135', '5 times', false, '515d9291-b6e6-4d50-821a-c19767216b6b');
