INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ce990b5-c23c-42ed-9053-c4698aeb42e7', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'In a school library survey, the number of books read across subjects is: English: 40, Maths: 60, Science: 80, Social Science: 50. If 1 book icon represents 10 books in a pictograph, how many icons represent Science and Social Science respectively?', 'Science = 80/10 = 8 icons; Social Science = 50/10 = 5 icons.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07ce8b9c-fc24-40ca-8183-a273ddcc92f9', 'Science: 8 icons ; Social Science: 5 icons', true, '2ce990b5-c23c-42ed-9053-c4698aeb42e7');
