INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c9f41662-3082-4bb7-8ff7-d432d55edd9e', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'A bar graph shows the number of bicycles manufactured by a factory from Monday to Friday: Mon: 300, Tue: 250, Wed: 400, Thu: 350, Fri: 500. On which day was the MAXIMUM number of bicycles manufactured, and on which day was the MINIMUM?', 'Highest bar = Friday (500 bicycles); Shortest bar = Tuesday (250 bicycles).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3730da5d-edd1-4fb3-b60d-2d4ccb0bc9f1', 'Maximum: Friday (500) ; Minimum: Tuesday (250)', true, 'c9f41662-3082-4bb7-8ff7-d432d55edd9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('704fb01e-3653-4b22-8f69-76dd07a385dd', 'Maximum: Wednesday ; Minimum: Monday', false, 'c9f41662-3082-4bb7-8ff7-d432d55edd9e');
