INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d7d9e99-d8cf-40f6-a37b-7555838c0a99', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'What is the total number of bicycles manufactured from Monday to Friday in the above factory?', '300 + 250 + 400 + 350 + 500 = 1,800 bicycles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f332e4a7-5557-43db-8873-835e93f062cf', '1,800 bicycles (300 + 250 + 400 + 350 + 500 = 1,800)', true, '3d7d9e99-d8cf-40f6-a37b-7555838c0a99');
