INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d33597ca-815b-48cc-8765-723e838fa566', '1,650 bicycles', false, '3d7d9e99-d8cf-40f6-a37b-7555838c0a99');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b5d09b3-d58e-4302-8641-1dcd1c76be4d', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'In a bar graph showing the favorite fruits of students: Mango: 45, Apple: 30, Banana: 25, Orange: 20. How many MORE students prefer Mango than Orange?', 'Difference = 45 - 20 = 25 students.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34dadf1a-ae8a-4e48-96de-97a2b16dbc34', '25 students (45 - 20 = 25)', true, '3b5d09b3-d58e-4302-8641-1dcd1c76be4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86a2c745-c120-4bf2-a386-99847f412857', '15 students', false, '3b5d09b3-d58e-4302-8641-1dcd1c76be4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04714b87-f1fc-4127-89ad-143310e0af32', '20 students', false, '3b5d09b3-d58e-4302-8641-1dcd1c76be4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('deef1182-916d-41fd-97f2-a45bf4b85c5d', '35 students', false, '3b5d09b3-d58e-4302-8641-1dcd1c76be4d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd95452d-f50a-4f50-9a8a-7b339d646e43', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'If a bar graph is drawn with a vertical scale of ''1 cm = 20 vehicles'', what will be the height of the bar representing 140 vehicles?', '140 vehicles ÷ 20 vehicles/cm = 7 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aaf1e5ee-0972-4fed-ba30-f2a4d2360dfa', '7 cm (140 ÷ 20 = 7 cm)', true, 'fd95452d-f50a-4f50-9a8a-7b339d646e43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ad21033-5c29-48d4-9029-8acbe2a848c4', '6 cm', false, 'fd95452d-f50a-4f50-9a8a-7b339d646e43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9add01b7-ddb9-4b01-9b1b-47231c1a2bb9', '8 cm', false, 'fd95452d-f50a-4f50-9a8a-7b339d646e43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5f6633c-e24e-4f3a-9c94-3ebcfe0d3609', '14 cm', false, 'fd95452d-f50a-4f50-9a8a-7b339d646e43');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('716c2376-d984-4494-9461-72b5c83873e5', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'A die was thrown 25 times and the following outcomes were recorded: 1, 2, 5, 4, 3, 6, 1, 3, 2, 5, 6, 4, 5, 2, 1, 3, 6, 5, 4, 2, 5, 3, 1, 5, 6. Which outcome appeared the MAXIMUM number of times?', 'Counting frequencies: 1:4, 2:4, 3:4, 4:3, 5:6, 6:4. Number 5 has the highest frequency (6).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4c0bb3b-5041-4136-a084-8be4e2a9a82a', 'Number 5 (frequency = 6 times)', true, '716c2376-d984-4494-9461-72b5c83873e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c94d811-b583-42bc-a797-4b1d891b9fc8', 'Number 6 (frequency = 4 times)', false, '716c2376-d984-4494-9461-72b5c83873e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c0bd026-fffc-4319-b6b2-53eabb6ababc', 'Number 1 (frequency = 4 times)', false, '716c2376-d984-4494-9461-72b5c83873e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dad03d8-bbaf-4330-9ed7-0cc9cc39b3e6', 'Number 2 (frequency = 4 times)', false, '716c2376-d984-4494-9461-72b5c83873e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b243bee-ce39-49dd-a1bd-599ea90a668a', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'What is the primary advantage of a Bar Graph over a raw list of data numbers?', 'Bar graphs provide immediate visual comparison of magnitudes across categorical variables.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8398aca-935f-4bec-ba64-0f801c46c0ed', 'It allows instant visual comparison of different categories at a single glance without tedious manual counting', true, '6b243bee-ce39-49dd-a1bd-599ea90a668a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b0810ea-d4cb-4a3a-8c71-ddc84f27fc6e', 'It makes the page look colorful', false, '6b243bee-ce39-49dd-a1bd-599ea90a668a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5d2b27c-b4de-450b-baaa-338f9f91450a', 'It reduces the actual numbers', false, '6b243bee-ce39-49dd-a1bd-599ea90a668a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f734d722-4088-4e6f-a8e9-02fa8224305c', 'It changes mathematics into art', false, '6b243bee-ce39-49dd-a1bd-599ea90a668a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10364da3-732b-4c2c-bb1e-11dabb981f45', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'In a pictograph where 1 🌲 represents 100 trees, Village A has 6 🌲, Village B has 4 🌲, and Village C has 7 🌲. What is the total tree count in all three villages together?', '(6 + 4 + 7) = 17 symbols × 100 trees/symbol = 1,700 trees.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('198070a9-6ef3-44f6-84fb-7b3385f04c94', '1,700 trees ((6 + 4 + 7) × 100 = 17 × 100 = 1,700)', true, '10364da3-732b-4c2c-bb1e-11dabb981f45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d423356-3980-45df-8ba8-cd4ba0cc9b7a', '1,500 trees', false, '10364da3-732b-4c2c-bb1e-11dabb981f45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c0a9886-c751-4783-9447-45dc263c56a7', '1,800 trees', false, '10364da3-732b-4c2c-bb1e-11dabb981f45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01bca8cf-ae15-413c-a3b1-4a50e239c3bd', '1,600 trees', false, '10364da3-732b-4c2c-bb1e-11dabb981f45');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7516542b-a609-445e-b82a-308b8ef01480', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'Why must all rectangular bars in a bar graph be of EQUAL WIDTH?', 'Bar width is non-data carrying; uniform width ensures that visual area remains strictly proportional to bar height.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('627e2496-95a8-4d94-b020-71c4bf296753', 'Because the width does not represent any data value; keeping widths uniform prevents visual distortion and misleading impressions', true, '7516542b-a609-445e-b82a-308b8ef01480');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e35ab190-097a-42d7-b8c5-a618eb8e5ba1', 'Because paper only has one width', false, '7516542b-a609-445e-b82a-308b8ef01480');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd1073ce-f0b3-47d6-8e1e-89ea37367901', 'Because rulers cannot draw different widths', false, '7516542b-a609-445e-b82a-308b8ef01480');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('184ea42c-82a8-40cd-b16b-526226f5df82', 'It is not necessary, widths can be random', false, '7516542b-a609-445e-b82a-308b8ef01480');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e480978d-a6d3-4940-a3a9-a4734af82bcc', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'In a class of 30 students, blood groups were recorded as: A: 8, B: 12, O: 7, AB: 3. What fraction of the total class has blood group B?', '12 / 30 = 2/5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c996d03b-bb62-4c59-b518-6505cf606b8a', '2/5 (12/30 = 2/5)', true, 'e480978d-a6d3-4940-a3a9-a4734af82bcc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4eabb7ea-a7a5-43a8-8750-d53d8cfd7768', '1/3', false, 'e480978d-a6d3-4940-a3a9-a4734af82bcc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e9df01d-58b9-44e7-b8f1-bdf76e1d57d7', '1/4', false, 'e480978d-a6d3-4940-a3a9-a4734af82bcc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e793e0b1-ef9b-4d77-8fab-dfdccd6f4e29', '3/10', false, 'e480978d-a6d3-4940-a3a9-a4734af82bcc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab5018df-f848-4996-8bfd-7408a951d8fa', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'What is the first step in constructing a frequency distribution table from disorganized raw data?', 'Systematic tally grouping transforms raw unstructured data into an organized frequency distribution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bb1d846-bb30-4498-9eb8-9d05cd125a4d', 'Identify the distinct categories, count occurrences systematically using tally marks, and total the frequencies', true, 'ab5018df-f848-4996-8bfd-7408a951d8fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a6ce0e0-3e9d-44eb-9cb0-08b2c1e821a1', 'Draw bars immediately without counting', false, 'ab5018df-f848-4996-8bfd-7408a951d8fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ccd2d89-26a4-4f95-819d-da38960f1dae', 'Color the page with pencils', false, 'ab5018df-f848-4996-8bfd-7408a951d8fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd94cf4c-3848-49c0-9bb9-78f85fa323fd', 'Guess the highest number', false, 'ab5018df-f848-4996-8bfd-7408a951d8fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68a847eb-2fcf-4c9e-98db-e850b3cd65aa', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'If 1 symbol 👶 represents 20 babies born in a hospital, how many symbols represent 70 babies (including a partial symbol)?', '70 ÷ 20 = 3.5 symbols (3 full icons + 1 half icon).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4940d61-05cd-4a01-9fc9-3d7d9acf67f9', '3 ½ symbols (3 complete symbols = 60 + half symbol = 10)', true, '68a847eb-2fcf-4c9e-98db-e850b3cd65aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('574f51bf-1a0f-42f0-ae6c-bc68b879ecd6', '4 symbols', false, '68a847eb-2fcf-4c9e-98db-e850b3cd65aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08fe0263-1b28-4880-bc38-545b14bd7d56', '3 symbols', false, '68a847eb-2fcf-4c9e-98db-e850b3cd65aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd3602d9-15b7-45cb-8df8-5f40e38fe112', '7 symbols', false, '68a847eb-2fcf-4c9e-98db-e850b3cd65aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb102b45-9193-451f-b098-acc25e499012', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'In a bar graph showing weekly rainfall: Mon: 2 cm, Tue: 5 cm, Wed: 0 cm, Thu: 3 cm, Fri: 6 cm, Sat: 4 cm, Sun: 1 cm. What is the difference in rainfall between the wettest and driest days?', 'Maximum (6 cm) - Minimum (0 cm) = 6 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f7e884e-aee4-4d76-a6c9-7adc88a35228', '6 cm (Wettest = Fri: 6 cm ; Driest = Wed: 0 cm ; Difference = 6 - 0 = 6 cm)', true, 'cb102b45-9193-451f-b098-acc25e499012');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d729c50-df90-4947-bb03-17f627a2801d', '5 cm', false, 'cb102b45-9193-451f-b098-acc25e499012');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('797e48cd-b734-4340-9471-d263e85d06cf', '4 cm', false, 'cb102b45-9193-451f-b098-acc25e499012');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c60e788f-b9d3-4980-acf7-7cefb7e35a35', '7 cm', false, 'cb102b45-9193-451f-b098-acc25e499012');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d9803713-3990-4955-9844-07c74dbaa028', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'How can a bar graph be drawn horizontally instead of vertically?', 'Horizontal bar graphs plot categories along the ordinate (Y) and lengths along the abscissa (X).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37770ce1-d67b-4637-a6d3-f2a30e5c3438', 'By placing categories on the vertical Y-axis and numerical values/scale on the horizontal X-axis (Horizontal Bar Graph)', true, 'd9803713-3990-4955-9844-07c74dbaa028');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4837d40-ffd9-4554-8021-e11825447c03', 'By turning the paper upside down', false, 'd9803713-3990-4955-9844-07c74dbaa028');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('846fe06b-f40a-43d4-8d67-a93e06b1bce9', 'By drawing curved lines', false, 'd9803713-3990-4955-9844-07c74dbaa028');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0f55a3b-d1df-4c69-afe6-5f8fc62aa6ef', 'Bar graphs cannot be drawn horizontally', false, 'd9803713-3990-4955-9844-07c74dbaa028');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be1588da-a319-433d-aa44-88505b8cb79c', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Medium', 'What is the total sum of frequencies in a complete frequency table equal to?', 'The sum of all category frequencies (Σf) must exactly equal total sample size N.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('965aff4e-1992-4505-8591-570fa6bde8a2', 'The total number of observations in the original dataset', true, 'be1588da-a319-433d-aa44-88505b8cb79c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2655a84d-7ffe-45bf-afa1-9073c2a175a4', 'Zero', false, 'be1588da-a319-433d-aa44-88505b8cb79c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('864f6576-a9d7-47ab-b734-25b1c759e08c', 'Always 100', false, 'be1588da-a319-433d-aa44-88505b8cb79c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('146ba2de-ccba-44d8-8681-ca0346927e17', 'The highest mark', false, 'be1588da-a319-433d-aa44-88505b8cb79c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b1d76c36-719b-4956-9276-646d36ce9e39', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef0a4e3c-efd6-4961-a09e-8874ea0c11c0', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'b1d76c36-719b-4956-9276-646d36ce9e39');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('996dff16-a539-46e3-8ea1-e43d76b30890', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'b1d76c36-719b-4956-9276-646d36ce9e39');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34c02a42-3925-42a1-b614-844183ba12f6', '(A) is true, but (R) is false.', false, 'b1d76c36-719b-4956-9276-646d36ce9e39');
