INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6dbf6f78-660f-426a-8d0d-6cf706c0db73', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'Spot the IMPOSTER in the following tally representations of numbers:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('270feca5-8aab-425c-ad32-0527b7c732af', '8 = 卌 |||', false, '6dbf6f78-660f-426a-8d0d-6cf706c0db73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8ffbde0-5738-4372-8175-523f6ea2c4df', '10 = 卌 卌', false, '6dbf6f78-660f-426a-8d0d-6cf706c0db73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f670baa-9aa5-4a89-adad-57fb79cbdf54', '14 = 卌 卌 ||||', false, '6dbf6f78-660f-426a-8d0d-6cf706c0db73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab5c4e41-3499-4437-a1a6-b70f45bbfb65', '16 = 卌 卌 卌 ||', true, '6dbf6f78-660f-426a-8d0d-6cf706c0db73');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63a5f612-a2c9-4691-8a9a-297554c8ef3c', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'A bar graph shows the population of a town over four decades:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33b61617-31ef-4428-a870-8341f2aaa09d', '2010 to 2020 (Increase = 80,000 - 55,000 = 25,000)', true, '63a5f612-a2c9-4691-8a9a-297554c8ef3c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63be00f8-6541-4756-a8f8-76d73f9db04e', '1990 to 2000 (15,000)', false, '63a5f612-a2c9-4691-8a9a-297554c8ef3c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d23d99bc-e558-4f15-a6fc-2ae2af52cb4e', '2000 to 2010 (20,000)', false, '63a5f612-a2c9-4691-8a9a-297554c8ef3c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72d8b2cb-b6c4-4b5e-9b52-94d424302977', 'All decades had equal increase', false, '63a5f612-a2c9-4691-8a9a-297554c8ef3c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25474ce9-80eb-4212-b920-814d3ae9f9ef', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'Match Column I (Data Concepts) with Column II (Definitions / Symbols):
(a) Tally Mark bundle 卌 -> (i) Proportional rectangular visual display
(b) Pictograph          -> (ii) Groups 5 counts together
(c) Frequency            -> (iii) Uses pictures with scaling keys
(d) Bar Graph            -> (iv) Number of occurrences of a data item', '卌 = 5 bundle; Pictograph = picture icons; Frequency = count; Bar graph = proportional bars.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66e2164c-e1e0-4e2b-ba37-83493705f31b', 'a-(ii), b-(iii), c-(iv), d-(i)', true, '25474ce9-80eb-4212-b920-814d3ae9f9ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('389b030b-ae96-4e68-9694-b5c760f31c21', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '25474ce9-80eb-4212-b920-814d3ae9f9ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2740c137-8a50-4f2b-bd0c-535f52f6f0d9', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '25474ce9-80eb-4212-b920-814d3ae9f9ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ea84ae5-a3aa-46e2-a99b-82303c4923fd', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '25474ce9-80eb-4212-b920-814d3ae9f9ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f8223f85-fcd5-4383-b52c-562fc766deb0', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'Read the statements regarding graphs:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8212a7e1-a549-4fbd-8938-e7f92b59cbfc', 'Statements 1 and 2 only', true, 'f8223f85-fcd5-4383-b52c-562fc766deb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b90f28d-8a7a-4b7d-ad61-26c20f537deb', 'Statements 2 and 3 only', false, 'f8223f85-fcd5-4383-b52c-562fc766deb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64f2289d-212b-432f-a52f-8f510913c251', 'Statements 1 and 3 only', false, 'f8223f85-fcd5-4383-b52c-562fc766deb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1dbc80b-bf63-482a-9a93-c5c097567b73', 'All Statements 1, 2, and 3', false, 'f8223f85-fcd5-4383-b52c-562fc766deb0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23a56df6-d52a-4868-9b66-87e39d32dd34', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'A factory produces 4 types of vehicles in a month: Cars: 120, Vans: 60, Trucks: 40, Motorcycles: 180. If drawn on a bar graph with scale 1 cm = 20 vehicles, what will be the combined total height of all 4 bars?', 'Heights: Cars=6 cm, Vans=3 cm, Trucks=2 cm, Bikes=9 cm. Total = 6+3+2+9 = 20 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1371923-cb7a-4703-b945-5f5362a9ad92', '20 cm ((120 + 60 + 40 + 180)/20 = 400/20 = 20 cm)', true, '23a56df6-d52a-4868-9b66-87e39d32dd34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01044e25-959c-4c35-a907-3bd2646c2f46', '18 cm', false, '23a56df6-d52a-4868-9b66-87e39d32dd34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77fb0a36-71d6-44cc-be9e-b40a2b343571', '25 cm', false, '23a56df6-d52a-4868-9b66-87e39d32dd34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fc5a139-0e36-4b45-ab58-f61e7bd7d083', '40 cm', false, '23a56df6-d52a-4868-9b66-87e39d32dd34');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('afefeac4-4465-49e0-8c39-c5555fd0bda9', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'Consider a dataset of 50 student test scores ranging from minimum score 12 to maximum score 98. What is the most appropriate scale for the vertical axis of a bar graph on standard graph paper (height ~20 cm)?', '1 unit = 10 marks maps the 0–100 range across a 10 cm vertical span.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adb08b04-d1a3-489e-bc5b-d7e31e804a17', '1 unit length = 10 marks (so 100 marks fits comfortably in 10 cm)', true, 'afefeac4-4465-49e0-8c39-c5555fd0bda9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65f913df-fd72-44ae-99c4-c28605f992c1', '1 unit length = 1 mark (needs 100 cm paper)', false, 'afefeac4-4465-49e0-8c39-c5555fd0bda9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b1b7443-88a5-434d-8d2c-3ccc761d06b1', '1 unit length = 50 marks', false, 'afefeac4-4465-49e0-8c39-c5555fd0bda9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4e3b8f7-0165-42ea-b03b-caa51f15fc6b', '1 unit length = 100 marks', false, 'afefeac4-4465-49e0-8c39-c5555fd0bda9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7dfa572d-add4-4a3b-b734-f843c6a685e1', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'In a pictograph where 1 🌸 represents 50 flowers, a florist sells 225 roses and 175 lilies. How many total flower symbols (including fractions) represent roses and lilies together?', 'Total flowers = 225 + 175 = 400 flowers ÷ 50 flowers/symbol = 8 symbols.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aae24d2c-777b-4a45-9e53-ca18e20dd6df', '8 symbols (225/50 = 4.5 symbols ; 175/50 = 3.5 symbols ; Total = 4.5 + 3.5 = 8 symbols)', true, '7dfa572d-add4-4a3b-b734-f843c6a685e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17148198-0e99-4eb3-a0bc-14f532512fab', '7 symbols', false, '7dfa572d-add4-4a3b-b734-f843c6a685e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7e734f1-9436-4b97-906e-43d8e3af7080', '9 symbols', false, '7dfa572d-add4-4a3b-b734-f843c6a685e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00164930-aff3-4a1c-9a51-0c619cd0d88b', '10 symbols', false, '7dfa572d-add4-4a3b-b734-f843c6a685e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('043e2a90-8fc9-4b0e-bb3e-4a54f49a9cbb', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'A survey asked 120 people their favorite mode of transport: Bus: 48, Train: 36, Car: 24, Bicycle: 12. What percentage of total people prefer Bus?', '(48 ÷ 120) × 100% = 0.40 × 100% = 40%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0f987e0-7079-4a82-9e62-d3efb2667025', '40% ((48/120) × 100% = 40%)', true, '043e2a90-8fc9-4b0e-bb3e-4a54f49a9cbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e165b49-53b1-42a5-b808-dabef9327264', '48%', false, '043e2a90-8fc9-4b0e-bb3e-4a54f49a9cbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61a12077-cedb-47fc-83f3-e4c6ebe96a79', '30%', false, '043e2a90-8fc9-4b0e-bb3e-4a54f49a9cbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4d2cce3-9081-4b65-bebb-dc6cb371d07e', '36%', false, '043e2a90-8fc9-4b0e-bb3e-4a54f49a9cbb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('498ceaf2-cab7-4280-a078-68082ebe107d', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'What is a ''Double Bar Graph'' used for in advanced data handling?', 'Double bar graphs pair bivariate data series side by side across common categories.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f20dea55-11b6-403f-8361-d706cdbceeeb', 'To display two sets of data simultaneously side by side for direct comparison between two groups or two time periods', true, '498ceaf2-cab7-4280-a078-68082ebe107d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a139d1ea-b9a6-4dfb-9e4d-2f856e787918', 'To draw bars twice as wide', false, '498ceaf2-cab7-4280-a078-68082ebe107d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('605cc582-8044-45d5-baff-7f9ff654efd4', 'To color bars with two paints', false, '498ceaf2-cab7-4280-a078-68082ebe107d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6a81438-967f-476d-ae1b-3f03b64dd431', 'To erase mistakes', false, '498ceaf2-cab7-4280-a078-68082ebe107d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2f7dce3-895f-4556-a967-d676efb67d44', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'If the mean (average) score of 5 matches played by a batsman is 42 runs, what is the total number of runs scored by him in all 5 matches?', 'Sum = Mean × N = 42 × 5 = 210 runs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef099cda-456e-4848-9a2f-63f830b6e5b8', '210 runs (Total = Mean × Number of matches = 42 × 5 = 210)', true, 'c2f7dce3-895f-4556-a967-d676efb67d44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ceb8e5d-ed47-4c35-964d-1cd6ee239bca', '200 runs', false, 'c2f7dce3-895f-4556-a967-d676efb67d44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a78343f-5688-4a9c-abc3-7a48ec031339', '225 runs', false, 'c2f7dce3-895f-4556-a967-d676efb67d44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c66e4e0-da78-4a84-9145-86b263228f97', '180 runs', false, 'c2f7dce3-895f-4556-a967-d676efb67d44');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6797ad2f-34e7-4fb2-b066-5dd42a95d7ef', 'Class 6', 'Mathematics', 'Chapter 9: Data Handling', 'Hard', 'Why is statistical data collection and visual representation critical in modern scientific and government decision making?', 'Visual analytics reveal underlying trends, outliers, and distributions to guide evidence-based policy formulation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c704364-109d-415f-a65f-091161a7fa43', 'It transforms vast, complex numerical data into clear, objective visual trends, enabling evidence-based policy, planning, and scientific forecasting', true, '6797ad2f-34e7-4fb2-b066-5dd42a95d7ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('371cfba3-764b-4b7f-884f-114685fa0bc4', 'Because computers cannot read numbers without graphs', false, '6797ad2f-34e7-4fb2-b066-5dd42a95d7ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f01a3fe-602a-457f-82ed-173f088c3c09', 'To make government books heavier', false, '6797ad2f-34e7-4fb2-b066-5dd42a95d7ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41b6b3c9-1dbb-446f-8a31-2cb0ec23a21c', 'Because graphs eliminate the need for mathematics', false, '6797ad2f-34e7-4fb2-b066-5dd42a95d7ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a379a66d-f93e-4d61-86d6-3cbb6416698e', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'What are Deserts defined as in ''Desert Animals''?', 'Deserts are hyper-arid biomes enduring prolonged droughts, yet harboring uniquely adapted wildlife.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('472f8fed-b990-4657-ba39-a94d520603c3', 'The driest places on Earth that sometimes go for months or even years without any rainfall', true, 'a379a66d-f93e-4d61-86d6-3cbb6416698e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93aded1e-530e-4353-8948-c7b41e99e42f', 'Areas covered with snow', false, 'a379a66d-f93e-4d61-86d6-3cbb6416698e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88532e54-d56a-4fab-bfec-0e579fb6ad29', 'Places full of rivers', false, 'a379a66d-f93e-4d61-86d6-3cbb6416698e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d6c707d-033e-4f6f-952b-5d920efd0ee8', 'Dense tropical forests', false, 'a379a66d-f93e-4d61-86d6-3cbb6416698e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1582b829-28c6-4e8e-bb59-4045c347c628', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'How do tiny desert rodents called ''Gerbils'' spend the hottest scorching hours of the desert day?', 'Gerbils avoid lethal surface heat by retreating into cool subterranean burrows.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbec3d95-fd82-4e9c-81cc-805055a18069', 'In cool, deep underground burrows', true, '1582b829-28c6-4e8e-bb59-4045c347c628');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('412945bc-6b20-4a66-81d9-a7c0495c34b2', 'Swimming in desert lakes', false, '1582b829-28c6-4e8e-bb59-4045c347c628');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76a9e398-100f-4dca-ab9c-a4a555ce117e', 'Climbing cactus trees', false, '1582b829-28c6-4e8e-bb59-4045c347c628');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fdf45cc-2061-4e5b-aa86-5ce58ffdc313', 'Sleeping in clouds', false, '1582b829-28c6-4e8e-bb59-4045c347c628');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d71c0260-de4f-4d1a-83f9-50a8ade267e0', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'How do strange desert insects called ''Darkling Beetles'' harvest drinking water in the arid desert?', 'Stenocara beetles employ fog-basking: condensing coastal fog on hydrophilic shell bumps and tilting to drink.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f06702de-51e9-4959-aa0a-b444494e6306', 'They catch morning fog droplets on their legs and tilt their bodies upward so the water drops trickle down directly into their mouths', true, 'd71c0260-de4f-4d1a-83f9-50a8ade267e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1020a7b2-fdd9-4752-a7d3-4a73940f87da', 'They dig 50-foot wells', false, 'd71c0260-de4f-4d1a-83f9-50a8ade267e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('249122e0-516a-4fb6-9c3e-73a01eeebe90', 'They drink water from cactus roots', false, 'd71c0260-de4f-4d1a-83f9-50a8ade267e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8c764c6-76d0-47e9-a62c-4dbfcbebda18', 'They don''t need water at all', false, 'd71c0260-de4f-4d1a-83f9-50a8ade267e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66dbe5b6-3bd8-4a2d-bc91-459e0d087414', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'Why do Rattlesnakes vibrate their dry rattle tails when threatened by an intruder?', 'Interlocking keratinous rattle segments buzz audibly at 30 meters as an aposematic defensive warning.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e712697a-f617-47c7-bd02-318f02ebe2c8', 'To produce a loud rattling warning sound that can be heard up to 30 metres away, warning the intruder to back off', true, '66dbe5b6-3bd8-4a2d-bc91-459e0d087414');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3141bc2-52e4-4643-93d5-5f348e0b0309', 'To attract prey animals', false, '66dbe5b6-3bd8-4a2d-bc91-459e0d087414');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d9403b4-df0b-41ad-a622-94e49a9c83ab', 'To keep their tail warm', false, '66dbe5b6-3bd8-4a2d-bc91-459e0d087414');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36326f4f-bf23-4aa9-93d5-6431983abf31', 'To make music in the desert', false, '66dbe5b6-3bd8-4a2d-bc91-459e0d087414');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03d255fa-4ddf-4dbe-9922-7d8b547cc501', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'How do snakes ''hear'' approaching footsteps despite being completely deaf to airborne sounds?', 'Lacking tympanic ears, snakes detect substrate acoustic seismic vibrations through somatic mechanoreceptors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b07f58e-65c7-4deb-827d-4a60108268ea', 'They feel ground vibrations directly through their sensitive belly scales and lower jawbones', true, '03d255fa-4ddf-4dbe-9922-7d8b547cc501');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f68990c-baae-49ce-ae06-ffc6584c29a0', 'Through big hidden ears', false, '03d255fa-4ddf-4dbe-9922-7d8b547cc501');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c2e4216-eb31-44e8-b901-4680be1d4791', 'Through their long tongues', false, '03d255fa-4ddf-4dbe-9922-7d8b547cc501');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed63f42e-a684-4e36-8422-4f38adbb5609', 'Through their eyes', false, '03d255fa-4ddf-4dbe-9922-7d8b547cc501');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e191cffd-e32f-4caa-8bd9-b213397c2a4d', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'What animal is famous for its astonishing speed and lightning-fast reflexes that enable it to kill deadly venomous snakes without getting bitten?', 'Mongooses combine agile predatory reflexes with specialized neurotoxin resistance to conquer venomous snakes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eeec9cce-0ded-41a7-8b13-f49c435ad5c5', 'Mongoose', true, 'e191cffd-e32f-4caa-8bd9-b213397c2a4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7311c547-3c7e-4adb-bee9-51fef001a016', 'Desert Rat', false, 'e191cffd-e32f-4caa-8bd9-b213397c2a4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01004db9-da11-445d-a013-7a55271f2165', 'Camel', false, 'e191cffd-e32f-4caa-8bd9-b213397c2a4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a27e9b8-86a0-4cf5-9e75-17627ea2fa5e', 'Gerbil', false, 'e191cffd-e32f-4caa-8bd9-b213397c2a4d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e4b7331-c3a4-4d13-9659-2d08a54bd347', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'What are the two distinct types of Camels found in the world?', 'Camelus dromedarius has a single hump, while Central Asian Camelus bactrianus possesses two humps.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eeb59f7b-3235-4fdd-a468-a4ce747fb5e1', 'Dromedary Camel (with ONE hump) and Bactrian Camel (with TWO humps)', true, '1e4b7331-c3a4-4d13-9659-2d08a54bd347');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d071872-d3ec-4ca4-9483-fbcf53a8c880', 'African Camel and Arctic Camel', false, '1e4b7331-c3a4-4d13-9659-2d08a54bd347');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33157048-1e88-4161-8726-036e495c92e8', 'Water Camel and Land Camel', false, '1e4b7331-c3a4-4d13-9659-2d08a54bd347');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a92a7c26-1b13-48fc-a156-6a082ab7eae2', 'Mountain Camel and Forest Camel', false, '1e4b7331-c3a4-4d13-9659-2d08a54bd347');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f9d970a-482c-4ca3-b829-660b7caf0aff', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'What is stored inside a Camel''s hump?', 'A camel''s hump stores adipose fat tissue, metabolizing into metabolic water and nourishment during famine.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48d4460e-0adb-424e-a53c-73ce32b687f8', 'Fat (which acts as a nourishment reserve and metabolic food supply)', true, '6f9d970a-482c-4ca3-b829-660b7caf0aff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea1d0507-f3ae-4626-b347-666bd3a8d46b', 'Drinking water', false, '6f9d970a-482c-4ca3-b829-660b7caf0aff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3fa352d-1f22-40d9-9ce7-f140d51497d3', 'Air', false, '6f9d970a-482c-4ca3-b829-660b7caf0aff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('244c6249-6949-49be-b22a-340e1ba7e1f4', 'Bones', false, '6f9d970a-482c-4ca3-b829-660b7caf0aff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eb34068d-ad46-4600-b8aa-b95879af21de', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'In the supplementary story ''What Happened to the Reptiles'', what was the peaceful forest village called?', 'Pambupatti was an idyllic peaceful village where Prem took shelter after escaping communal violence in his hometown.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('822001c3-7ee0-49e2-8f6d-a080b05d266e', 'Pambupatti (a village where people of all communities lived in peace)', true, 'eb34068d-ad46-4600-b8aa-b95879af21de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3164d110-e631-4472-819e-4c3b45b60e07', 'Rampur', false, 'eb34068d-ad46-4600-b8aa-b95879af21de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bfcf78d-49b1-4e7d-a4bf-bf16f3f063ff', 'Shampur', false, 'eb34068d-ad46-4600-b8aa-b95879af21de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0727ed12-02e4-4463-9788-da3bb9cb0283', 'Sitapur', false, 'eb34068d-ad46-4600-b8aa-b95879af21de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5898ed8c-7260-4a82-a55c-bf803485f208', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'Who was Makara in the ancient fable of Pambupatti?', 'Makara was a domineering tyrant crocodile who bullied other reptiles into unquestioning subservience.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2a42561-8d16-488b-9934-0edb8afeac53', 'The biggest, strongest, and most arrogant crocodile who was the president of the reptile council', true, '5898ed8c-7260-4a82-a55c-bf803485f208');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e1f79e5-be5b-4dea-8bf7-5e85a3520bca', 'A wise old tortoise', false, '5898ed8c-7260-4a82-a55c-bf803485f208');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9e27f37-f7c6-4d26-bc8a-c96d1a6e6009', 'A poisonous snake', false, '5898ed8c-7260-4a82-a55c-bf803485f208');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36ea3d0c-ad91-4103-835f-0d1c0cf1e931', 'A harmless lizard', false, '5898ed8c-7260-4a82-a55c-bf803485f208');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8351b4a2-2657-44b6-a706-1e2b41b1deb6', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'Which gentle, slow-moving creature was the FIRST to be expelled from the forest by Makara''s tyrannical decree?', 'Makara expelled peaceful tortoises first, arrogantly mocking their slow pace and protective shells.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a4b87e0-4985-4a9b-90d3-efd0186a728b', 'The Tortoises (led by wise old Prem)', true, '8351b4a2-2657-44b6-a706-1e2b41b1deb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29602bd3-c758-4dec-b4b8-c3b587099c4a', 'The Snakes', false, '8351b4a2-2657-44b6-a706-1e2b41b1deb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64d9951f-42fc-462b-b57a-4dee0c7b2ce5', 'The Lizards', false, '8351b4a2-2657-44b6-a706-1e2b41b1deb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6205bbb-429c-47a8-b27d-6bcd24207d8b', 'The Frogs', false, '8351b4a2-2657-44b6-a706-1e2b41b1deb6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8fc80fe-67f3-4765-962a-c2b69dbea406', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Easy', 'What happened to the forest ecosystem of Pambupatti after Makara drove out tortoises, snakes, and lizards?', 'Expelling natural predator and scavenger reptiles triggered an explosive plague of rats and insect pests.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('316460c8-dc4b-4f63-97fa-bb3536bad9ed', 'A disastrous ecological crisis occurred: rats multiplied out of control eating eggs, rotting smell filled the air, and millions of insects infested the forest', true, 'e8fc80fe-67f3-4765-962a-c2b69dbea406');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e00bd38f-92ef-472e-841f-b9a3f47b6cc8', 'The forest became a paradise', false, 'e8fc80fe-67f3-4765-962a-c2b69dbea406');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6497fba-d8cf-426a-9151-bebb6ffb2763', 'Crocodiles became twice as large', false, 'e8fc80fe-67f3-4765-962a-c2b69dbea406');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75d89529-f22a-47d4-a490-6ed3e2e5b3a9', 'All rivers turned into gold', false, 'e8fc80fe-67f3-4765-962a-c2b69dbea406');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('220ad9eb-8b4d-4ac5-89b0-dcf8162115ea', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'How does a Mongoose successfully defeat a venomous cobra in combat?', 'Tactical agility: the mongoose dances out of strike range, exhausting the serpent''s energy reserves before delivering a lethal cervical bite.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1fa7659-9335-4809-b6f0-c85ab2ab2eb1', 'By constantly dodging, darting, and exhausting the snake through repeated evasive maneuvers until the tired snake strikes slowly, then biting its neck', true, '220ad9eb-8b4d-4ac5-89b0-dcf8162115ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc3a0b2e-d506-4e36-99ca-1e2c50c02370', 'By using poison gas', false, '220ad9eb-8b4d-4ac5-89b0-dcf8162115ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa64fb74-5b96-4c37-afeb-b091960984d8', 'By hypnotizing the snake with music', false, '220ad9eb-8b4d-4ac5-89b0-dcf8162115ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bedb8dcc-1954-4856-8992-4a3f56850861', 'By hiding in trees', false, '220ad9eb-8b4d-4ac5-89b0-dcf8162115ea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bee398e6-953d-439f-b120-e06991ac5bdb', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'Why do Mongooses hunt in friendly groups and constantly stay in touch using twittering and whistling sounds?', 'Cooperative social foraging: contact calls coordinate foraging while sentinel alarm chirps warn of aerial raptors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a05309db-8ace-4d1b-b7b7-4ab6d5e960b6', 'To keep track of each other while hunting in dense brush and alert the whole clan immediately if a predator (like a hawk or eagle) appears', true, 'bee398e6-953d-439f-b120-e06991ac5bdb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04639e8a-4e3e-45db-8bbb-4ec21bbc3448', 'Because they like to sing songs', false, 'bee398e6-953d-439f-b120-e06991ac5bdb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58cd927a-d3ab-425c-a748-55e4fa8cba1f', 'To scare away all insects', false, 'bee398e6-953d-439f-b120-e06991ac5bdb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c209d5c-a725-4fff-a48a-db0160f7b500', 'To practice speaking human words', false, 'bee398e6-953d-439f-b120-e06991ac5bdb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da36e8ff-fa66-495a-8b71-32a948c6f0f5', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'How much water can a thirsty camel drink in a single 10-minute session?', 'Rehydrating camels can drink over 100 litres of water in 10 minutes without osmotic hemolysis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8623723-c51e-4681-b1a7-f79778b48e53', 'As much as 30 gallons (about 500 glasses of water / ~115 to 135 litres)', true, 'da36e8ff-fa66-495a-8b71-32a948c6f0f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad830be1-8a13-4683-86e6-498478ef2d36', 'Only 1 glass', false, 'da36e8ff-fa66-495a-8b71-32a948c6f0f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90e734db-2ff4-41e0-a729-cd6676d93398', '5 litres', false, 'da36e8ff-fa66-495a-8b71-32a948c6f0f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ab377a4-750a-480c-95db-2bf5ce7ba69e', '500 gallons', false, 'da36e8ff-fa66-495a-8b71-32a948c6f0f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a400e8d-0a6b-4f37-85de-520a30356e75', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'How does a Camel''s mouth adapt to eating thorny desert cactus plants without getting hurt?', 'Dense, heavily keratinized conical oral papillae protect the camel''s palate and gums against sharp desert thorns.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7f0bec1-9691-4165-b5bd-e2b093098a8e', 'Its mouth is lined with tough, thick leathery mucous membranes that sharp thorns cannot pierce', true, '0a400e8d-0a6b-4f37-85de-520a30356e75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcc19223-5128-49a1-8c0e-b0594db0a5a8', 'It melts thorns with boiling saliva', false, '0a400e8d-0a6b-4f37-85de-520a30356e75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a278c18-0682-463e-9644-cabbf3346214', 'It has steel teeth', false, '0a400e8d-0a6b-4f37-85de-520a30356e75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1849f13a-4d63-4e3a-8302-ed71d8953f08', 'It only eats powdered cactus', false, '0a400e8d-0a6b-4f37-85de-520a30356e75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25d0d21a-d5cd-4495-9822-3578b5bf84dc', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'Why was Makara forced to send urgent letters recalling all the expelled snakes, tortoises, and lizards back to Pambupatti?', 'Ecological pestilence humbled Makara''s tyranny, forcing him to restore the reptile community.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a036168-d779-4198-9f88-8fb530d40a4c', 'Because millions of bold rats were chewing baby crocodile tails, frogs were invading every pool, and the forest had become unlivable without ecological balance', true, '25d0d21a-d5cd-4495-9822-3578b5bf84dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2821c20a-02b7-4beb-ae70-d81b7c6c07c5', 'Because Makara wanted to have a dance party', false, '25d0d21a-d5cd-4495-9822-3578b5bf84dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7684e57-f7be-48b5-a9e6-da2c8075b683', 'Because the crocodiles felt lonely', false, '25d0d21a-d5cd-4495-9822-3578b5bf84dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2917f2e6-037d-42aa-bf35-80483d7e004d', 'Because the government ordered them', false, '25d0d21a-d5cd-4495-9822-3578b5bf84dc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b8db5f57-ee4a-40a5-acb4-cfc75425733e', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'What profound moral and environmental lesson does Zai Whitaker''s story ''What Happened to the Reptiles'' teach?', 'An ecological and socio-political allegory demonstrating that biodiversity and human pluralism are essential for survival.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a59f41a2-ee52-4ebd-ab55-4fd1fffdb395', 'Every single creature in an ecosystem has an indispensable role; no species or human community is superior, and harmony requires celebrating diversity and mutual coexistence', true, 'b8db5f57-ee4a-40a5-acb4-cfc75425733e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('380d0a31-c17b-4683-bece-19837bd3f5cc', 'Crocodiles are the wisest animals', false, 'b8db5f57-ee4a-40a5-acb4-cfc75425733e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbb38974-8791-409f-91f9-50ea67459644', 'Villages should have no reptiles', false, 'b8db5f57-ee4a-40a5-acb4-cfc75425733e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea90dc4f-15fa-4262-b287-c9e4ff28d9ba', 'Rats make the best pets', false, 'b8db5f57-ee4a-40a5-acb4-cfc75425733e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('15f9ba10-8f68-4e60-9a4b-585ce1f67a91', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'Why did the old man in Pambupatti tell the story to Prem, who had fled from communal riots in his distant city?', 'The elder uses the ecological parable to heal Prem''s trauma and inspire him as an ambassador of communal harmony.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5b0b997-b1a3-4fb7-863b-20d08270542c', 'To make Prem realize that hatred, exclusion, and intolerance destroy society, and that he must return home to spread the message of peaceful communal coexistence', true, '15f9ba10-8f68-4e60-9a4b-585ce1f67a91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dfd73be-e7f0-415d-ae63-ce12d9819dfe', 'To scare Prem with crocodile tales', false, '15f9ba10-8f68-4e60-9a4b-585ce1f67a91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64d85301-c078-41e4-bc39-83680ab84611', 'To teach him how to hunt snakes', false, '15f9ba10-8f68-4e60-9a4b-585ce1f67a91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd513aae-3d9a-43c4-aef6-1586dd531db8', 'To pass time before dinner', false, '15f9ba10-8f68-4e60-9a4b-585ce1f67a91');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d434b00-2f97-4da9-8bbf-e3fd53a140c9', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'What does the word ''Predator'' mean in biological ecology?', 'A predator is a carnivorous organism that preys upon other organisms for metabolic sustenance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f0cf26f-d387-41af-8e96-dc64153ed7e1', 'An animal that hunts, kills, and feeds on other animals (prey)', true, '3d434b00-2f97-4da9-8bbf-e3fd53a140c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58a34feb-f565-42e1-800d-0b749b7d01b4', 'An animal that only eats grass', false, '3d434b00-2f97-4da9-8bbf-e3fd53a140c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f64bb8bb-9340-4bb8-873e-9681e4345efa', 'An animal that lives underwater', false, '3d434b00-2f97-4da9-8bbf-e3fd53a140c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a56ed9d-5651-4f18-a7ed-319562dd4b6c', 'A pet animal', false, '3d434b00-2f97-4da9-8bbf-e3fd53a140c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64d01ff7-9b6a-4be6-91ee-bf256be5eddb', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'How do Rattle snakes perceive warm-blooded prey in total darkness?', 'Pit vipers possess infrared pit organs mapping thermal infrared signatures of endothermic rodent prey.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('686acad3-27c4-45cb-bcf5-f0ca775f66d9', 'Through thermal heat-sensing pit organs located between their eyes and nostrils that detect infrared thermal radiation', true, '64d01ff7-9b6a-4be6-91ee-bf256be5eddb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80482d16-67ca-4810-98f5-54980aecd894', 'Using night-vision glasses', false, '64d01ff7-9b6a-4be6-91ee-bf256be5eddb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0a72a2c-3842-4399-97e4-fada734c9849', 'Through loud shouts', false, '64d01ff7-9b6a-4be6-91ee-bf256be5eddb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c696425-cf63-44af-bea3-1491e79f3cee', 'By smelling with their ears', false, '64d01ff7-9b6a-4be6-91ee-bf256be5eddb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d477fd52-b4a9-4c95-9812-cdd32f43ac75', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'What is ''Communal Harmony'' as reflected in the village of Pambupatti?', 'Communal harmony embodies interfaith tolerance, pluralistic fraternity, and peaceful social cohesion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc72ba54-9f75-48ca-ac2b-d732c6342c6a', 'People belonging to different religions, backgrounds, and communities living together in mutual peace, respect, equality, and brotherhood', true, 'd477fd52-b4a9-4c95-9812-cdd32f43ac75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffbb6a64-861f-4410-9c40-545338cb5db7', 'People fighting over property', false, 'd477fd52-b4a9-4c95-9812-cdd32f43ac75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caef870b-8549-4fdf-be81-1ad2caa5713b', 'Only one group ruling everyone else', false, 'd477fd52-b4a9-4c95-9812-cdd32f43ac75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15ceb560-986c-4465-8632-6def47983fc1', 'Living without any laws', false, 'd477fd52-b4a9-4c95-9812-cdd32f43ac75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bd609260-e9d5-4bc8-9220-45caf97148cf', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'Why does a camel sweat so little compared to humans?', 'Adaptive heterothermy: camels tolerate diurnal body temperatures from 34°C to 41°C, minimizing evaporative sweat loss.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bc38771-0672-47ae-9d89-26cf5dac54ce', 'Camels can withstand body temperature fluctuations up to 42°C without sweating, conserving vital body water in desert heat', true, 'bd609260-e9d5-4bc8-9220-45caf97148cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7f66fd9-ef42-45e9-9951-fcc763ca8275', 'Camels have no sweat glands', false, 'bd609260-e9d5-4bc8-9220-45caf97148cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71c7cd37-a613-4ba6-b771-d9ef24b77442', 'Camels are made of stone', false, 'bd609260-e9d5-4bc8-9220-45caf97148cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b6cf517-38c3-4677-b38b-65119230fafd', 'Camels only sweat in winter', false, 'bd609260-e9d5-4bc8-9220-45caf97148cf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b28d1f8a-d635-4dfd-a5bb-cdc1d7624039', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'What role do lizards and chameleons play in maintaining the forest ecology of Pambupatti?', 'Insectivorous lizards provide critical top-down biological pest control in forest biomes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e22f2698-d031-46d9-9d7d-b7ce4ef5c00a', 'They consume millions of insects and pests daily, preventing insect swarms from destroying plants and trees', true, 'b28d1f8a-d635-4dfd-a5bb-cdc1d7624039');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b89e614a-c0c3-4343-9c25-c14c828c1a73', 'They build wooden bridges', false, 'b28d1f8a-d635-4dfd-a5bb-cdc1d7624039');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0c7048e-8f21-42a8-beda-722ebc0dc860', 'They dig deep rivers', false, 'b28d1f8a-d635-4dfd-a5bb-cdc1d7624039');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2e366cb-01b0-4b8d-b121-201a3512d3ef', 'They hunt crocodiles', false, 'b28d1f8a-d635-4dfd-a5bb-cdc1d7624039');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('354892bc-029d-40d2-b520-bc8f6e6eb1b5', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'What does the phrase ''to turn a deaf ear'' mean when Makara ignored the pleas of smaller animals?', '''To turn a deaf ear'' is an idiom meaning to deliberately disregard advice or compassionate appeals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0f41599-3c08-4af7-9d15-ad9d87f7ecd2', 'To deliberately refuse to listen or pay attention to someone', true, '354892bc-029d-40d2-b520-bc8f6e6eb1b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c945c98-d322-437d-8dc8-dff8bf2dca1f', 'To become physically deaf from loud noise', false, '354892bc-029d-40d2-b520-bc8f6e6eb1b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f8b5ca0-8193-41dc-b928-2d7c74dfebf1', 'To clean one''s ear', false, '354892bc-029d-40d2-b520-bc8f6e6eb1b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80a55828-bc7f-45b0-a1c5-964421cda4ca', 'To whisper a secret', false, '354892bc-029d-40d2-b520-bc8f6e6eb1b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36f29c5d-c6e5-4145-aa03-2a66be495019', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'Why do female mongooses in a clan give birth to litters at the same time in communal dens?', 'Synchronous breeding enables communal alloparental care, elevating pup survival against predators.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edc2ddd3-110e-4e65-af55-02067f52b5a9', 'So that nursing mothers can share parental duties and adult group members take turns babysitting while others forage for food', true, '36f29c5d-c6e5-4145-aa03-2a66be495019');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdcc7d38-e70b-46e0-b632-634b718fd3b8', 'Because they have no houses', false, '36f29c5d-c6e5-4145-aa03-2a66be495019');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d9ab2be-a9ac-41d6-b646-b2e88eeb2971', 'To fight other animals', false, '36f29c5d-c6e5-4145-aa03-2a66be495019');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60513679-d1a5-4f35-8f3d-f3589a663fc9', 'By pure accidental coincidence', false, '36f29c5d-c6e5-4145-aa03-2a66be495019');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6f47854-c816-47c8-9ec8-c9b42229bba9', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'In ''What Happened to the Reptiles'', what happened to the forest''s atmosphere after the expelled animals returned?', 'Trophic balance was immediately restored as returning predators and scavengers re-established ecological equilibrium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3100e67b-8166-41ab-a277-e6f2ac891283', 'The rats were eaten, insects were controlled, rotting foul smell vanished, and the pristine green forest returned to healthy peace and normal balance', true, 'e6f47854-c816-47c8-9ec8-c9b42229bba9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84ba2ef6-0cbe-4bf8-9bfc-dd66fcfe7f1c', 'The forest caught fire', false, 'e6f47854-c816-47c8-9ec8-c9b42229bba9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34fdb0df-0f46-4a99-8a15-8b098099af59', 'The animals fought a war', false, 'e6f47854-c816-47c8-9ec8-c9b42229bba9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('669852c2-8b0e-4ca2-b1dd-8f87cfc943d0', 'The river dried up', false, 'e6f47854-c816-47c8-9ec8-c9b42229bba9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7656116e-89e9-44c4-90cf-ff8dc96560d6', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Medium', 'Who is the prominent naturalist and wildlife author who wrote ''What Happened to the Reptiles''?', 'Zai Whitaker, co-founder of the Madras Crocodile Bank Trust, authored this environmental allegory.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a654923-9486-47e4-a334-914864c5eca3', 'Zai Whitaker', true, '7656116e-89e9-44c4-90cf-ff8dc96560d6');
