INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd8ff7ad-7bd0-4908-8a4c-75f34b41773a', 'Jim Corbett', false, '7656116e-89e9-44c4-90cf-ff8dc96560d6');
