INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d2ac5d3e-935b-4e9c-bcd3-a668d716b6f1', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Hard', 'Spot the IMPOSTER in the following group of desert animal adaptations from Chapter 9:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab27940f-243d-47bd-9b61-81b3d0536d32', 'Darkling Beetle (Fog harvesting)', false, 'd2ac5d3e-935b-4e9c-bcd3-a668d716b6f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9c23605-3486-4c75-8fdc-8b51392333fc', 'Gerbil (Cool underground burrows)', false, 'd2ac5d3e-935b-4e9c-bcd3-a668d716b6f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d3bab79-3f11-4638-aaae-805a60826d39', 'Camel (Fat-filled hump)', false, 'd2ac5d3e-935b-4e9c-bcd3-a668d716b6f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e172aee9-0359-42f0-974f-a196646416f1', 'Mongoose (Swimming underwater with gills)', true, 'd2ac5d3e-935b-4e9c-bcd3-a668d716b6f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e75feddc-f26e-44a0-a0a3-a3207a14bb28', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Hard', 'Analyze the deeper political symbolism in Makara''s rhetoric when he banished the lizards because ''they change color and cannot be trusted'':', 'Makara''s irrational scapegoating mirrors authoritarian propaganda used to persecute pluralistic minorities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a56e8c7c-0a57-4392-9e23-105194f33162', 'It represents fascist and majoritarian prejudice that invents irrational, fabricated excuses to demonize and purge minority communities from society', true, 'e75feddc-f26e-44a0-a0a3-a3207a14bb28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a1ce6a4-b90a-49b0-89dc-7af237224a7a', 'It shows that lizards are bad painters', false, 'e75feddc-f26e-44a0-a0a3-a3207a14bb28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28db8599-f005-46e9-a545-fab2526d1b0f', 'It proves that reptiles don''t like green color', false, 'e75feddc-f26e-44a0-a0a3-a3207a14bb28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51f1e828-0e1d-4e34-aca3-bed0100babdf', 'It is a guide on how to catch lizards', false, 'e75feddc-f26e-44a0-a0a3-a3207a14bb28');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8eeccc48-918c-4cd8-9167-8bdac6d02a04', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Hard', 'Match Column I (Desert Creatures) with Column II (Physiological & Behavioral Adaptations):
(a) Darkling Beetle -> (i) Fast reflex dodges exhausting cobras
(b) Dromedary Camel -> (ii) Condenses coastal fog droplets on body
(c) Mongoose        -> (iii) Single dorsal fat hump for famine metabolism
(d) Rattlesnake     -> (iv) Warning tail buzz & infrared heat pit organs', 'Beetle = fog condensation; Camel = fat hump; Mongoose = agility/dodges; Rattlesnake = rattle buzz/pits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b16d52d-d371-4cda-94ab-2658075067de', 'a-(ii), b-(iii), c-(i), d-(iv)', true, '8eeccc48-918c-4cd8-9167-8bdac6d02a04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f1fa674-171d-44c1-9b1c-b9b43b880547', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '8eeccc48-918c-4cd8-9167-8bdac6d02a04');
