INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('881705f8-edb2-42b4-b8cf-be5dbe3cd508', 'Statements 1 and 2 only', true, '7b39bab4-886c-4b72-9da9-6462d2ebada0');
