INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('299e04ad-f6fa-426c-888b-c2c59fc70e6a', 'Statements 1 and 3 only', false, '7b39bab4-886c-4b72-9da9-6462d2ebada0');
