INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf6c8dc6-f015-4b01-a8d7-06932d47fa8e', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Hard', 'What is the grammatical function of the underlined relative clause in: ''Prem met an old man *who told him the story of Pambupatti*.''?', 'The relative clause ''who told him...'' acts as an Adjective Clause characterizing the noun ''old man''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a8346f6-113e-477c-9b75-2ea09d98e1a6', 'Adjective Clause (modifying the antecedent noun ''old man'')', true, 'cf6c8dc6-f015-4b01-a8d7-06932d47fa8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e3be5ab-aae3-4753-ad67-7728a7078c36', 'Noun Clause', false, 'cf6c8dc6-f015-4b01-a8d7-06932d47fa8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('398ba147-fef6-4215-bfae-7c9efbbbd959', 'Adverb Clause of Reason', false, 'cf6c8dc6-f015-4b01-a8d7-06932d47fa8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f82dbe43-16cf-462c-9170-7debc35374cc', 'Prepositional Phrase', false, 'cf6c8dc6-f015-4b01-a8d7-06932d47fa8e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2de4f2a4-c6b4-412b-a076-cb642aa83bc1', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Hard', 'What biochemical mechanism protects the mongoose when it receives a minor bite from a venomous snake?', 'Glycosylation on the alpha-subunit of muscle nAChRs physically blocks snake neurotoxin binding in mongooses.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b383c6e3-c148-4b3a-9fe9-9666e572c07b', 'Mutated nicotinic acetylcholine receptors in mongoose muscle cells prevent snake alpha-neurotoxins from binding, conferring intrinsic venom resistance', true, '2de4f2a4-c6b4-412b-a076-cb642aa83bc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('580c9b6d-bde6-4b7e-b474-333aace0547f', 'Mongooses have cold blood that freezes venom', false, '2de4f2a4-c6b4-412b-a076-cb642aa83bc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f28f702b-4b28-4fbd-8099-112f7e9b3f12', 'Mongooses drink special snake antidotes from rivers', false, '2de4f2a4-c6b4-412b-a076-cb642aa83bc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08c7b407-e768-4616-95f0-5ae813ffc496', 'Their fur has iron shields', false, '2de4f2a4-c6b4-412b-a076-cb642aa83bc1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6cc5d410-5a3f-4b78-8611-cbb1cdd85304', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Hard', 'What is the meaning of the adjective ''Unanimous'' when Makara declared his orders without voting?', '''Unanimous'' denotes complete collective consensus without dissent.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d4746b8-f592-437a-b3bc-9fa13ae85783', 'Held in complete total agreement by everyone (though in Makara''s case, enforced through sheer terror and intimidation)', true, '6cc5d410-5a3f-4b78-8611-cbb1cdd85304');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d83020e-2257-4752-8228-54074a5113f2', 'Divided equally into two parts', false, '6cc5d410-5a3f-4b78-8611-cbb1cdd85304');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00c27bd1-9e80-42b3-b2b3-25630ebbe135', 'Completely secret', false, '6cc5d410-5a3f-4b78-8611-cbb1cdd85304');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('522b6f4c-86ca-46f9-9e0d-1b304c4c9a78', 'Written in pencil', false, '6cc5d410-5a3f-4b78-8611-cbb1cdd85304');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2512e9ea-49f7-449f-9f4b-6a2015972abf', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Hard', 'How does the structure of camel red blood cells (erythrocytes) differ from that of humans to support extreme dehydration and rehydration?', 'Elliptical erythrocytes resist osmotic lysis and navigate hyper-viscous microcirculation during severe dehydration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7f77531-4dd5-4ee3-bae3-d00e59f2bdb9', 'Camels have oval-shaped (elliptical) erythrocytes that can expand up to 240% of their volume during rapid rehydration without bursting, and flow smoothly even in thick viscous dehydrated blood', true, '2512e9ea-49f7-449f-9f4b-6a2015972abf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9c0d441-6c4c-408a-bb2a-abd3c9a44a28', 'Camels have square blood cells', false, '2512e9ea-49f7-449f-9f4b-6a2015972abf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d59ad155-a0e0-4898-8c5d-e1ca88850f1c', 'Camels have no red blood cells', false, '2512e9ea-49f7-449f-9f4b-6a2015972abf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c006755b-b6e2-4bb1-b13b-369451eff5b0', 'Camel blood is made of pure water', false, '2512e9ea-49f7-449f-9f4b-6a2015972abf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('95f6813e-027e-4ea7-9083-9b98e3fd7777', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Hard', 'Why did Prem initially refuse to return to his village, stating: ''I never want to go back there''?', 'Socio-political violence had shattered Prem''s faith in human decency until Pambupatti restored his hope.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93f4f491-d8e3-4644-bb0b-6afb67a29cba', 'He was deeply traumatized by sectarian communal violence where neighbors burned houses and attacked each other in religious madness', true, '95f6813e-027e-4ea7-9083-9b98e3fd7777');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c701acb8-1130-4228-8eaf-dbb76d5bb761', 'He had lost his school bag', false, '95f6813e-027e-4ea7-9083-9b98e3fd7777');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65cd4739-1148-4ff2-a45f-6fd9c4866e86', 'He wanted to become a fisherman', false, '95f6813e-027e-4ea7-9083-9b98e3fd7777');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3eca5451-63e8-4d7d-b664-8f4d5f21732b', 'He was afraid of rain', false, '95f6813e-027e-4ea7-9083-9b98e3fd7777');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9fff8c9-0548-49ff-a732-d8c3dfe04f40', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Hard', 'What literary device is utilized in ''What Happened to the Reptiles'' to address human social conflicts through animal characters?', 'An Allegory uses a narrative surface level (reptiles in a forest) to symbolize deeper political realities (communal tolerance).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('152e1cb9-2553-4498-88cd-a643b0e01b8a', 'Allegory / Fable (using animal personification to deliver deep moral, social, and political truths)', true, 'a9fff8c9-0548-49ff-a732-d8c3dfe04f40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31a539ff-4406-494a-83f3-56090307d4f1', 'Satirical farce', false, 'a9fff8c9-0548-49ff-a732-d8c3dfe04f40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be876b5d-f1cc-4cf8-b0ef-760f381c5547', 'Science fiction', false, 'a9fff8c9-0548-49ff-a732-d8c3dfe04f40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee6ca92b-ced2-4e8c-bf2d-948cdd13ff0f', 'Sonnet', false, 'a9fff8c9-0548-49ff-a732-d8c3dfe04f40');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eb1bce42-1618-4c6f-8158-9f862c9af0c1', 'Class 6', 'English', 'Chapter 9: Desert Animals', 'Hard', 'What ultimate philosophical conviction inspires Prem to return to his wounded city at the conclusion of the story?', 'Prem embraces the duty of storytelling to heal fractured societies through the gospel of pluralistic harmony.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb99735d-88fb-4495-b645-79ae03445b1a', 'That even if cynical people laugh or resist at first, repeating the story of Pambupatti will eventually open human minds to the sacred truth of mutual harmony and interdependence', true, 'eb1bce42-1618-4c6f-8158-9f862c9af0c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('223604d4-f9e9-46bd-81b2-263df4ef2c1b', 'To become the mayor of the city', false, 'eb1bce42-1618-4c6f-8158-9f862c9af0c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88ccac22-6790-4d39-b176-cde210e96c91', 'To build a wall around his house', false, 'eb1bce42-1618-4c6f-8158-9f862c9af0c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fd46336-2795-4ceb-88a4-8dc811c1773b', 'To buy expensive camels', false, 'eb1bce42-1618-4c6f-8158-9f862c9af0c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e0e859f1-1545-4f48-aa54-b0611c995e25', 'Class 6', 'GK', 'Chapter 9: Sports, Famous Champions & Traditional Games of India', 'Easy', 'Who is celebrated as the ''Wizard of Hockey'' (Hockey Wizard) in India, who led the Indian hockey team to Olympic gold medals in 1928, 1932, and 1936?', 'Major Dhyan Chand scored over 400 international goals; his birthday on 29th August is celebrated as India''s National Sports Day.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e6ac0ec-fc19-46c2-8a6c-fa4ab08a5b9f', 'Major Dhyan Chand', true, 'e0e859f1-1545-4f48-aa54-b0611c995e25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6569bd01-b3ba-49de-b9a6-cb728d8fc684', 'Balbir Singh Sr.', false, 'e0e859f1-1545-4f48-aa54-b0611c995e25');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e156dcf-28c7-4671-b44c-6f18762243f4', 'Dhanraj Pillay', false, 'e0e859f1-1545-4f48-aa54-b0611c995e25');
