INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1abe98c0-ee47-4959-97fc-57fabb326de6', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Easy', 'What is the earliest body of Tamil literature composed around 2,300 years ago in assemblies of poets held in the city of Madurai called?', '''Sangam'' literature refers to ancient Tamil poetry anthologies compiled in assemblies (sangams) of bards under Pandyan patronage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5433a525-a3b5-47eb-bc4c-804274120aa9', 'Sangam Literature', true, '1abe98c0-ee47-4959-97fc-57fabb326de6');
