INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5fb5db81-16aa-49cf-92cb-97263f4a4d95', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Easy', 'What are the earliest coins used in India for about 500 years (from c. 600 BCE), made of silver or copper punched with distinct symbols called?', 'Punch-marked coins were stamped with metallurgical dies featuring symbols (hills, trees, animals) on silver and copper flans.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50435ca9-7a1d-4baf-8274-8a2f241342c0', 'Punch-Marked Coins (Aahat Mudra)', true, '5fb5db81-16aa-49cf-92cb-97263f4a4d95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18d10888-8a70-4181-aabf-4a43aadec1b0', 'Gold Dinars', false, '5fb5db81-16aa-49cf-92cb-97263f4a4d95');
