INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e65032fc-2795-4cb2-8c62-764ff52d2e58', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Easy', 'Which ancient coastal port settlement in Puducherry (excavated by Sir Mortimer Wheeler) was a thriving international trade hub with the Roman Empire between 2200 and 1900 years ago?', 'Arikamedu excavations yielded Roman amphorae wine jars, Arretine red-glazed pottery, and Roman gold coins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66ad9bc8-3021-4e6d-aab5-e3e6a1c20a9c', 'Arikamedu (Podouke of the Periplus)', true, 'e65032fc-2795-4cb2-8c62-764ff52d2e58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b137c877-a5e6-4cd0-b1d1-4fa0b5835106', 'Kaveripattinam', false, 'e65032fc-2795-4cb2-8c62-764ff52d2e58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ee1d335-cb6e-4466-a384-b3ceea757d7a', 'Lothal', false, 'e65032fc-2795-4cb2-8c62-764ff52d2e58');
