INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45b472d7-7f35-4ed3-8ea2-4a64da947bd5', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What were ''Shrenis'' in ancient Indian urban centers?', 'Shrenis operated as merchant/artisan guilds, providing credit finance, technical quality control, and banking services.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8e67017-b72b-42a3-baaf-3cf01cb13915', 'Associations and guilds formed by craftspersons and merchants to procure raw materials, train artisans, distribute goods, and function as banks', true, '45b472d7-7f35-4ed3-8ea2-4a64da947bd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc979ba3-126f-4d04-9860-8ac0c84121f0', 'Royal palaces of kings', false, '45b472d7-7f35-4ed3-8ea2-4a64da947bd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c1dee40-eeda-4186-8bc5-0ae1863ad9f7', 'Military battalions', false, '45b472d7-7f35-4ed3-8ea2-4a64da947bd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab078762-36c2-4d85-89b1-7421ba60b5f0', 'Taxes paid by farmers', false, '45b472d7-7f35-4ed3-8ea2-4a64da947bd5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c26cbe45-a0b2-46a2-9438-71983c30caf6', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'Why was Mathura a major, thriving multi-functional urban city for over 2,500 years?', 'Mathura''s strategic commercial crossroads location and vibrant religious syncretism made it the second capital of the Kushanas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e6185fd-f666-422c-a12d-0f969edf0084', 'It was located at the vital crossroads of two major ancient trade routes (North-west to East, and North to South), a center of fine sculpture, and a religious hub for Krishna worship, Buddhism, and Jainism', true, 'c26cbe45-a0b2-46a2-9438-71983c30caf6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd0d0640-4412-48e8-b4d7-6c496ff5fab3', 'Because it had gold mines', false, 'c26cbe45-a0b2-46a2-9438-71983c30caf6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('587f8d84-4c4f-4a5d-9451-70ddb1b6cba6', 'Because it was on the sea coast', false, 'c26cbe45-a0b2-46a2-9438-71983c30caf6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2278f24b-b14e-44d9-bcdc-2da2cba1f381', 'Because it had no agriculture', false, 'c26cbe45-a0b2-46a2-9438-71983c30caf6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2082b5e3-921e-4d5e-91d9-ad5b6fcbab64', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What was ''Northern Black Polished Ware'' (NBPW) produced in ancient urban centers of the Gangetic valley?', 'NBPW was premium deluxe tableware fired at high kilns, producing an iridescent black gloss.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19b966f6-358a-4747-9d0d-0b012e386fd8', 'A very fine, ultra-smooth, glossy black earthenware pottery with a mirror-like metallic shine used as luxury tableware', true, '2082b5e3-921e-4d5e-91d9-ad5b6fcbab64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc681747-0ea5-4ec2-bc72-aea1ff995364', 'A heavy iron shield', false, '2082b5e3-921e-4d5e-91d9-ad5b6fcbab64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdfcc755-b3c5-43cf-a62f-91bbc5c3751f', 'A type of black stone', false, '2082b5e3-921e-4d5e-91d9-ad5b6fcbab64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2df36db7-1b0f-4072-84a8-aa1696b2bf44', 'A wooden plate', false, '2082b5e3-921e-4d5e-91d9-ad5b6fcbab64');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22543d93-0764-4c0b-b3f8-424a42f7cf1d', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What were ''Ring Wells'' discovered in archaeological excavations of ancient cities like Delhi and Hastinapur used for?', 'Stacked ceramic terracotta ring wells served as soakage pits, sullage drains, and latrines in dense urban quarters.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('162d5f48-4d0e-4532-a7cf-3e21edde8db4', 'As domestic toilets, drain pipes, or garbage waste pits by stacking terracotta rings vertically in the ground', true, '22543d93-0764-4c0b-b3f8-424a42f7cf1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69f0e057-1ece-44de-bc22-b5f6ff6b2b7f', 'As gold treasure vaults', false, '22543d93-0764-4c0b-b3f8-424a42f7cf1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('821de926-6e70-4773-87b7-3ec4ff4a64db', 'As musical instruments', false, '22543d93-0764-4c0b-b3f8-424a42f7cf1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4a6b2a3-8961-429e-a537-209bffc0d76b', 'As animal traps', false, '22543d93-0764-4c0b-b3f8-424a42f7cf1d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('05ed3210-197d-42ef-85ce-0e1232986e18', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What ancient Greco-Roman travel guidebook written by an anonymous Greek sailor in the 1st century CE describes Indian coastal ports and maritime trade items?', 'The ''Periplus of the Erythraean Sea'' details trade goods traded at Bharuch (Barygaza), Muziris, and Arikamedu.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82662d7f-9752-444c-92b2-2ea1d16f164e', 'The Periplus of the Erythraean Sea (''Periplus of the Red/Arabian Sea'')', true, '05ed3210-197d-42ef-85ce-0e1232986e18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a914e15-7dff-4e74-b5e3-c1e5a4bcce54', 'Indica by Megasthenes', false, '05ed3210-197d-42ef-85ce-0e1232986e18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a48fabe-d6ff-4ea8-bc11-1db04e8c6020', 'Geographia by Ptolemy', false, '05ed3210-197d-42ef-85ce-0e1232986e18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d64f5def-23fd-4acb-9cfd-7235e3e3432e', 'Naturalis Historia', false, '05ed3210-197d-42ef-85ce-0e1232986e18');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5be599b9-4b91-4d23-ab1a-887449ffa82e', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What goods were EXPORTED from Indian ports like Barygaza (Bharuch in Gujarat) to the Roman Empire?', 'Indian exports comprised fine muslins, black pepper (''black gold''), ivory, precious gemstones, and aromatics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ab25d8d-83c8-4718-aeda-e3a357857614', 'Fine cotton textiles, silk, black pepper and spices, ivory, agate, jasper, and medicinal herbs', true, '5be599b9-4b91-4d23-ab1a-887449ffa82e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('999eacfd-b4dd-4649-8e2f-fa894cbfb614', 'Wine and Italian pottery', false, '5be599b9-4b91-4d23-ab1a-887449ffa82e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dea61cf9-4d0b-483d-92d6-334174c7ef13', 'Roman gold and silver coins', false, '5be599b9-4b91-4d23-ab1a-887449ffa82e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9d2e754-0d72-4fc5-b7de-129552186475', 'Tin, lead, and glass', false, '5be599b9-4b91-4d23-ab1a-887449ffa82e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b9eefddf-f68b-4730-a733-3b8b9e036eae', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What goods were IMPORTED into India from the Mediterranean Roman world?', 'Rome exported wine, metals (tin/lead), coral, and huge hoards of imperial gold/silver denarii to balance trade.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba59da65-6c3c-4921-99b3-f2125065f384', 'Italian wine in amphorae jars, Roman gold and silver coins, copper, tin, lead, coral, and topaz', true, 'b9eefddf-f68b-4730-a733-3b8b9e036eae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba0a8db9-0faf-4af2-a9cd-dc54e8ab8dcd', 'Black pepper and cardamoms', false, 'b9eefddf-f68b-4730-a733-3b8b9e036eae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc9d2dff-c1d0-4fb0-988b-87b17d355ca3', 'Fine cotton cloth', false, 'b9eefddf-f68b-4730-a733-3b8b9e036eae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17a889a7-0020-4601-94d9-75ed2f50dc58', 'Ivory and peacocks', false, 'b9eefddf-f68b-4730-a733-3b8b9e036eae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5477269d-8168-4ea3-801e-744c5fac8829', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What were ''Arretine Ware'' vessels discovered at Arikamedu?', 'Arretine ware was Italian fine slip-coated red terra sigillata exported across Mediterranean maritime trade networks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1feb018-30b7-423b-b4dc-aa9d8226730c', 'Fine red-glazed Roman pottery named after the Italian city of Arezzo, stamped with decorative designs using wet clay molds', true, '5477269d-8168-4ea3-801e-744c5fac8829');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1336bee8-8b1f-4404-a7a9-b0be3a8041d0', 'Chinese porcelain vases', false, '5477269d-8168-4ea3-801e-744c5fac8829');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e87c72be-4c1e-4450-8d46-95cd2f377ced', 'Ancient bronze statues', false, '5477269d-8168-4ea3-801e-744c5fac8829');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8459895d-e43e-4c15-8f22-374e30bdee58', 'Iron cooking pots', false, '5477269d-8168-4ea3-801e-744c5fac8829');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('af64bd06-15b8-4aab-a0c8-bcbfca20bc9c', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'Why did Pliny the Elder, a Roman historian, lament that ''not a year passes without India taking fifty million sesterces of Roman gold''?', 'Pliny''s ''Naturalis Historia'' lamented the massive trade deficit and gold drain caused by aristocratic Roman addiction to Indian luxury spices.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72c64d96-8919-42f0-b09f-6ceba6f3f2a6', 'Because Roman wealth was draining into India to purchase Indian luxury spices (black pepper), silk, and gemstones', true, 'af64bd06-15b8-4aab-a0c8-bcbfca20bc9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d743b7a-9b66-4314-8a22-e0f334533f4c', 'Because India was buying all Roman wheat', false, 'af64bd06-15b8-4aab-a0c8-bcbfca20bc9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21b046f7-596c-499c-a4ea-af92a6c41177', 'Because Roman armies lost wars to India', false, 'af64bd06-15b8-4aab-a0c8-bcbfca20bc9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('707c36a0-be95-4e2f-8278-5fdec740b6cb', 'Because Roman emperors gave gifts to India', false, 'af64bd06-15b8-4aab-a0c8-bcbfca20bc9c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75b3d972-4af5-4042-82e3-b93c9fb40778', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What were the famous ancient centers of cotton textile weaving in northern and southern India mentioned in Kautilya''s Arthashastra?', 'Arthashastra identifies Varanasi and Madurai as renowned manufacturing guild centers of fine cotton textiles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69068cd0-d7ae-4ea5-ae21-e34168bb90bf', 'Varanasi (in the north) and Madurai (in the south)', true, '75b3d972-4af5-4042-82e3-b93c9fb40778');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fccf922a-90fd-429d-9b88-d7a07242794d', 'Delhi and Mumbai', false, '75b3d972-4af5-4042-82e3-b93c9fb40778');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad0d0aa9-9a82-4e1f-a19a-06fbbc7a8376', 'Taxila and Ujjain', false, '75b3d972-4af5-4042-82e3-b93c9fb40778');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05893836-c8ab-4123-b0cf-27132a46a71c', 'Patliputra and Kanchi', false, '75b3d972-4af5-4042-82e3-b93c9fb40778');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae8f0dd2-c6b1-4a88-b267-1de1a9e37b57', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'Why was the post of ''Gramabhojaka'' hereditary in northern villages?', 'Hereditary succession maintained aristocratic lineage control over village revenues and rural administration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a41ba26c-ccb2-4e54-bd38-58546d43c835', 'The position passed from father to son across generations within the village''s wealthiest landowning family', true, 'ae8f0dd2-c6b1-4a88-b267-1de1a9e37b57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0ae330b-4962-4480-aef0-139b73ed8acc', 'Because kings held elections every year', false, 'ae8f0dd2-c6b1-4a88-b267-1de1a9e37b57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fcb91af-83d2-4747-847f-9af50eeda4a7', 'Because villagers voted with stones', false, 'ae8f0dd2-c6b1-4a88-b267-1de1a9e37b57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d311c46-c83e-4996-9a5f-25ff332fc060', 'Because only priests could hold the post', false, 'ae8f0dd2-c6b1-4a88-b267-1de1a9e37b57');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c64d2c0-160d-4bf3-b6fb-d9c4555cd48a', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What are ''Jatakas'' in ancient Indian literature?', 'Jatakas are moral Buddhist folk narratives (e.g. story of the clever poor young man) preserved in Pali canon.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c82341a-38f2-4042-a94d-4ae51739367c', 'Popular folk stories depicting previous lives of the Buddha, composed by ordinary people and written down by Buddhist monks', true, '5c64d2c0-160d-4bf3-b6fb-d9c4555cd48a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6a799e1-5fdd-4041-a233-f3e1f19f7915', 'Royal inscriptions carved on rocks', false, '5c64d2c0-160d-4bf3-b6fb-d9c4555cd48a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68115087-4287-4544-a1e3-ede11f75b531', 'Mathematical textbooks', false, '5c64d2c0-160d-4bf3-b6fb-d9c4555cd48a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f233d37-0f4f-404e-b17a-81a26a6896aa', 'Military strategies of kings', false, '5c64d2c0-160d-4bf3-b6fb-d9c4555cd48a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d2a6077-641c-4393-a855-d289c20ca7df', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What crucial archaeological evidence proves the existence of flourishing international trade at ancient port sites?', 'Numismatic hoards, imported pottery (terra sigillata), and wharves confirm historical maritime trade connectivity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('868018fd-d6ae-4507-8b64-26765e262bc1', 'Foreign coins, imported amphorae wine jars, foreign stamped pottery, and specialized port warehouse brick structures', true, '9d2a6077-641c-4393-a855-d289c20ca7df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab151b71-6983-43b5-8069-eb2ddacb4940', 'Modern asphalt roads', false, '9d2a6077-641c-4393-a855-d289c20ca7df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c9ba1e5-17e1-489d-8127-1ac6703cb6a1', 'Plastic toys', false, '9d2a6077-641c-4393-a855-d289c20ca7df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c1f2004-534f-40ef-9a40-4c7c96c8f3ca', 'Steel cargo ships', false, '9d2a6077-641c-4393-a855-d289c20ca7df');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04de460c-65bd-4d9e-84a9-9b7745e3ca1b', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'How did the invention and expansion of Iron tools transform civilization between 1000 BCE and 500 BCE?', 'Iron metallurgy enabled forest clearance and agricultural surplus in the Gangetic basin, catalyzing the Second Urbanization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d0e0d17-6315-44a0-9bfa-297a0a4d4e1d', 'Heavy iron axes cleared dense subtropical Gangetic monsoon forests for settled farming, and iron ploughs dramatically increased food surpluses, sustaining urbanization', true, '04de460c-65bd-4d9e-84a9-9b7745e3ca1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97ac8887-7719-403d-9d45-b8ccd61462d7', 'It destroyed all cities', false, '04de460c-65bd-4d9e-84a9-9b7745e3ca1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91dc5220-ee27-4c01-a2db-adf06f5dc02d', 'It stopped all agriculture', false, '04de460c-65bd-4d9e-84a9-9b7745e3ca1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab3f1814-53bf-4d16-980f-8f705197f0a9', 'It made people leave India', false, '04de460c-65bd-4d9e-84a9-9b7745e3ca1b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa7ad996-1fcc-4529-a2f5-257565bc0ecc', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'What religious donations were inscribed on stone pillars and railings of Buddhist stupas (such as Sanchi and Mathura)?', 'Votive epigraphs record pious donations by diverse socio-economic strata (guilds, artisans, lay devotees) to monastic orders.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('605cbe5a-3374-408a-8425-78585e7d4280', 'Votive Inscriptions recording gifts given by kings, queens, guild merchants, weavers, goldsmiths, and monks/nuns', true, 'fa7ad996-1fcc-4529-a2f5-257565bc0ecc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28c1297f-768b-482b-9105-c16fa6f1ea01', 'Tax receipts from farmers', false, 'fa7ad996-1fcc-4529-a2f5-257565bc0ecc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f70a74c-5caf-42cb-9beb-2d9f640c8b7a', 'Cooking recipes', false, 'fa7ad996-1fcc-4529-a2f5-257565bc0ecc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91b4e253-1ae5-4410-9e41-8fab42a357ca', 'War declarations', false, 'fa7ad996-1fcc-4529-a2f5-257565bc0ecc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9fc0b7e0-4e73-424a-8071-4cdfbf32364f', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Medium', 'Why was the ancient port of Barygaza (modern Bharuch) in the Gulf of Khambhat difficult for foreign ships to navigate?', 'The ''Periplus'' records that violent tidal bores in the narrow Gulf of Khambhat required specialized pilots.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('402339c1-8331-48bc-b77e-60db3130d854', 'The gulf was narrow, shallow, and plagued by fierce tidal bore currents, requiring skillful local fishermen employed by the king to steer ships into port', true, '9fc0b7e0-4e73-424a-8071-4cdfbf32364f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef47fadf-ea0c-47ce-911c-cfdb224b3fbf', 'Because of icebergs', false, '9fc0b7e0-4e73-424a-8071-4cdfbf32364f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d65a23d-ae09-49ef-bb7c-1c0b9abd33a6', 'Because of pirates with cannons', false, '9fc0b7e0-4e73-424a-8071-4cdfbf32364f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf03fdb5-34b6-4808-8832-c20bba148c5f', 'Because there was no water', false, '9fc0b7e0-4e73-424a-8071-4cdfbf32364f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8551b8a0-8a94-4170-ad69-8454f5dbe566', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'Read the statements:
