INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c64284a-0b8b-4b8f-95e6-192349255161', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '8551b8a0-8a94-4170-ad69-8454f5dbe566');
