INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf2f7d24-a152-48f0-8242-bc0a5f465874', 'Vellalar (Large Landowner)', false, '56288f60-3991-4d73-88f6-ddedff9a0b98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac638f2a-83ab-4432-be9b-6b7c62702278', 'Uzhavar (Ploughman)', false, '56288f60-3991-4d73-88f6-ddedff9a0b98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99b06d8f-1e9a-4a54-b958-91101cb90908', 'Kadaisiyar (Landless Labourer)', false, '56288f60-3991-4d73-88f6-ddedff9a0b98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fadeeb93-ca7d-4915-8622-1f5aad533abb', 'Gramabhojaka (Slaves in Tamil Nadu)', true, '56288f60-3991-4d73-88f6-ddedff9a0b98');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('112370c2-fa20-45f1-8584-8bf9fb405a9a', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'An archaeologist excavates an ancient trade site and discovers: (1) Amphorae containing dried wine residue, (2) Red-glazed stamped pottery, (3) Roman gold coins of Emperor Augustus. What historical site is represented?', 'Mortimer Wheeler''s excavations at Arikamedu proved it was an Indo-Roman maritime emporium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('773feb05-7131-4807-9333-d00c7f4a174c', 'Arikamedu (near Puducherry on the southeastern Coromandel coast)', true, '112370c2-fa20-45f1-8584-8bf9fb405a9a');
