INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a023c0ab-f763-428c-b69b-2c4b2c048cd5', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'Match Column I (Ancient Terms) with Column II (Definitions & Roles):
(a) Shrenis        -> (i) Earliest stamped silver/copper coins
(b) Gramabhojaka   -> (ii) Guilds of craftspersons & merchants
(c) Punch-marked   -> (iii) Hereditary village headman & tax collector (North)
(d) Sangam         -> (iv) Assemblies of ancient Tamil poets in Madurai', 'Shrenis = guilds; Gramabhojaka = northern village headman; Punch-marked = coins; Sangam = poet assemblies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7433d6fa-ee9f-4a74-a57a-39ee664d91db', 'a-(ii), b-(iii), c-(i), d-(iv)', true, 'a023c0ab-f763-428c-b69b-2c4b2c048cd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79997ecb-e643-4d7b-bc14-e57edb80b744', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'a023c0ab-f763-428c-b69b-2c4b2c048cd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13574a81-66b0-4f23-82d5-ef3effb6bf03', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'a023c0ab-f763-428c-b69b-2c4b2c048cd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcb39119-87c9-4822-9120-73ad841e75f7', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'a023c0ab-f763-428c-b69b-2c4b2c048cd5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('670495c4-fde5-409f-b944-a82f8f40f107', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'Read the statements regarding ancient craft and trade:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aaebbae5-f9a4-4685-84de-9466b06da744', 'Statements 1 and 2 only', true, '670495c4-fde5-409f-b944-a82f8f40f107');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ab70855-349f-4e32-8846-26f29cf3dace', 'Statements 2 and 3 only', false, '670495c4-fde5-409f-b944-a82f8f40f107');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bead3b2-39e9-422a-8c10-83b1e82251f9', 'Statements 1 and 3 only', false, '670495c4-fde5-409f-b944-a82f8f40f107');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6aeabe73-368b-4fe8-be01-bced09279a94', 'All Statements 1, 2, and 3', false, '670495c4-fde5-409f-b944-a82f8f40f107');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('357a82c0-4345-46a1-846c-d30f039e4606', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'What was the significance of Mathura becoming the second capital of the Kushana Empire (under Emperor Kanishka)?', 'Mathura flourished as the southern capital of the Kushanas, creating the Mathura school of art in mottled red Sikri sandstone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bfe9437-69e7-407e-b0e0-8c5140a6f901', 'It became a premier center of red sandstone sculpture (producing magnificent Buddha images) and a crossroads linking Gandhara with Gangetic trade', true, '357a82c0-4345-46a1-846c-d30f039e4606');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98a5811a-5f36-475c-a1f9-06906e714b52', 'It was made of ice', false, '357a82c0-4345-46a1-846c-d30f039e4606');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('becad56a-acc7-4d0f-b160-80ec58db67bd', 'It was abandoned forever', false, '357a82c0-4345-46a1-846c-d30f039e4606');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69259a3b-32d7-4e9e-8c7f-5bdcfc426cf0', 'It was only used as a prison', false, '357a82c0-4345-46a1-846c-d30f039e4606');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3bb784c-b54b-4c67-9350-ea9edae18ed4', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'Why was the process of ''Paddy (Rice) Transplantation'' around 2,500 years ago a major technological turning point in Gangetic agriculture?', 'Transplantation minimized seedling mortality, drastically raising grain productivity per hectare.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6eb2eef6-ea12-4830-9751-0585c066aeb0', 'Instead of scattering dry seeds on soil where many died, saplings were grown in nurseries and transplanted into water-logged flooded fields, ensuring far higher plant survival and bumper yields', true, 'c3bb784c-b54b-4c67-9350-ea9edae18ed4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2317b1c5-4e62-4ac3-993d-0c7821d177e9', 'Because it stopped weeds by burning', false, 'c3bb784c-b54b-4c67-9350-ea9edae18ed4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a63ef9fd-27af-4a34-987e-fa4d9342929b', 'Because rice could grow without water', false, 'c3bb784c-b54b-4c67-9350-ea9edae18ed4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('513880e5-178b-4a0f-9259-1014ee80d8f4', 'Because animals did all the work', false, 'c3bb784c-b54b-4c67-9350-ea9edae18ed4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('80ae36b1-f378-4edf-9e3a-92037b8aa1ff', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'Consider four occupational groups in an ancient village:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('025f90e0-6a5d-4651-bfb6-f2eb884b3ae5', '1 -> 2 -> 4 -> 3', true, '80ae36b1-f378-4edf-9e3a-92037b8aa1ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0f95b60-c37b-4a46-90d4-dda7d098441b', '3 -> 4 -> 2 -> 1', false, '80ae36b1-f378-4edf-9e3a-92037b8aa1ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78d91532-978c-4cde-a161-ecfd3d119f23', '2 -> 1 -> 3 -> 4', false, '80ae36b1-f378-4edf-9e3a-92037b8aa1ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5446fc2f-dda6-440e-ad4f-4e1fc3fc6ae9', '4 -> 3 -> 2 -> 1', false, '80ae36b1-f378-4edf-9e3a-92037b8aa1ff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('678b5584-32a6-401f-9bc6-ec83a2a53918', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'What archaeological feature distinguishes Northern Black Polished Ware (NBPW) from earlier Painted Grey Ware (PGW)?', 'NBPW''s distinctive black mirror gloss derived from iron-rich ferruginous slips subjected to reduction firing in sealed kilns.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7efb8728-4f02-412c-af67-12def7412e8f', 'NBPW is characterized by its lustrous, mirror-like jet-black surface sheen achieved by two-stage reducing atmosphere kiln firing and organic slip application', true, '678b5584-32a6-401f-9bc6-ec83a2a53918');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eba53adb-b110-4056-a701-6f91256a55eb', 'NBPW is made of metal', false, '678b5584-32a6-401f-9bc6-ec83a2a53918');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a97e67dd-dde9-48ae-85e4-1286d1132a3a', 'NBPW has red flowers painted on it', false, '678b5584-32a6-401f-9bc6-ec83a2a53918');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1a9c4a0-b37f-4ca8-958f-deb1ccd09169', 'NBPW is unbaked mud', false, '678b5584-32a6-401f-9bc6-ec83a2a53918');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e62939b-2b40-4b6f-9925-6c35a1f5650b', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'What do the numerous Megalithic burial stone circles in South India (dating from c. 1000 BCE) contain inside them that proves early iron metallurgy?', 'Megalithic cists and urns contain funerary grave goods: iron swords, daggers, agricultural sickles, and horse bits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c9a0cd1-06c5-491c-aa29-1d08c1c3c33a', 'Large assortments of iron weapons, iron hoes, sickles, horse equipment, and black-and-red pottery buried alongside human skeletons', true, '7e62939b-2b40-4b6f-9925-6c35a1f5650b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('370b02ed-29f8-4bec-9efb-233ddf6ec094', 'Paper books and modern pens', false, '7e62939b-2b40-4b6f-9925-6c35a1f5650b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffde73da-e4c1-4e37-b265-bb5e9eee3e95', 'Steam engines', false, '7e62939b-2b40-4b6f-9925-6c35a1f5650b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47d8b3ea-67d3-43dc-b0dc-3ba79335f3a2', 'Plastic utensils', false, '7e62939b-2b40-4b6f-9925-6c35a1f5650b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81d5302e-f0a9-401d-b677-6978004c41a8', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'How did ancient kings in India ensure the loyalty of the Gramabhojaka in administering rural territories?', 'Monarchs co-opted dominant local landed elites, delegating fiscal and judicial power in exchange for tax remittance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d10b36ed-3267-4432-acfc-a763d5e96155', 'By recognizing his hereditary local land power and delegating official state functions (tax collection, judicial dispute settlement, and local policing) to him', true, '81d5302e-f0a9-401d-b677-6978004c41a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae51cb75-8db9-4731-96c0-6a99a362a47e', 'By imprisoning his family', false, '81d5302e-f0a9-401d-b677-6978004c41a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2483e08e-ee54-4696-8db7-432d24a10694', 'By destroying his crops', false, '81d5302e-f0a9-401d-b677-6978004c41a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27c1a481-720b-44b8-a8cb-803d6ad6f042', 'By replacing him every month', false, '81d5302e-f0a9-401d-b677-6978004c41a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3230db8-b903-4ef1-b739-15fd323ecd9e', 'Class 6', 'Social Science', 'Chapter 9: Vital Villages, Thriving Towns', 'Hard', 'What holistic picture of ancient society emerges from reading NCERT Class 6 History on villages and towns?', 'History portrays an integrated ecosystem connecting agrarian villages, craft guilds, and international maritime trade emporia.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1522a483-057a-45d2-8379-898659069685', 'An interdependent socio-economic web where thriving agricultural villages, specialized urban craft guilds, and global maritime ports sustained flourishing civilization through trade and cultural exchange', true, 'd3230db8-b903-4ef1-b739-15fd323ecd9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4112fd7f-5c25-4434-8243-1b575463c81e', 'A society where towns had no connection to villages', false, 'd3230db8-b903-4ef1-b739-15fd323ecd9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f26511cc-4a65-4acf-8500-dffd41f6036f', 'A civilization that had no tools or trade', false, 'd3230db8-b903-4ef1-b739-15fd323ecd9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0360d30c-2e41-4a6d-b132-5fa8dbc2ab30', 'A world without any laws or coins', false, 'd3230db8-b903-4ef1-b739-15fd323ecd9e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f64a39df-9ff1-4489-9a4c-d6ebd9c5dd15', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'संज्ञा अथवा सर्वनाम शब्दों की विशेषता (गुण, दोष, रूप, रंग, आकार, संख्या, परिमाण) बताने वाले शब्दों को क्या कहते हैं?', 'संज्ञा या सर्वनाम की विशेषता प्रकट करने वाले विकारी शब्द ''विशेषण'' कहलाते हैं (जैसे: ''सुंदर'', ''लाल'', ''पाँच'', ''मीठा'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b224860-866e-4396-aa26-41aacc0e1502', 'विशेषण (Adjective)', true, 'f64a39df-9ff1-4489-9a4c-d6ebd9c5dd15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc33f0c8-9a85-447d-a59c-65e5280c5d9a', 'क्रिया', false, 'f64a39df-9ff1-4489-9a4c-d6ebd9c5dd15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d7e6cbc-442b-4c05-97df-87daaa59271a', 'अव्यय', false, 'f64a39df-9ff1-4489-9a4c-d6ebd9c5dd15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6c39b36-a07c-4abe-882a-453723debe90', 'कारक', false, 'f64a39df-9ff1-4489-9a4c-d6ebd9c5dd15');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bbdbc05b-c705-4b80-946e-97a81c9d3126', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'विशेषण शब्द जिस संज्ञा या सर्वनाम शब्द की विशेषता बताता है, उसे व्याकरण में क्या कहते हैं?', 'जिसकी विशेषता बताई जाए वह ''विशेष्य'' कहलाता है (जैसे: ''मीठा सेब'' में ''मीठा'' = विशेषण, ''सेब'' = विशेष्य)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0143b34-185c-4bb9-9651-aeb1802b26f7', 'विशेष्य (जैसे: ''काली गाय'' में ''गाय'' विशेष्य है)', true, 'bbdbc05b-c705-4b80-946e-97a81c9d3126');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c59c2f56-6833-43b8-8f5a-8e2dcfa4a13c', 'प्रविशेषण', false, 'bbdbc05b-c705-4b80-946e-97a81c9d3126');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e319fb43-18e4-4efd-8779-c8ceda57dfc6', 'क्रिया', false, 'bbdbc05b-c705-4b80-946e-97a81c9d3126');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef2a0a23-b2c4-4ef4-9b83-3aa833ff06ea', 'कर्म', false, 'bbdbc05b-c705-4b80-946e-97a81c9d3126');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('210865a7-1b5b-4395-aa4c-40c8e4f7010c', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'हिंदी भाषा में विशेषण के मुख्य रूप से कितने भेद (प्रकार) होते हैं?', 'विशेषण के 4 मुख्य भेद हैं: 1. गुणवाचक, 2. संख्यावाचक, 3. परिमाणवाचक, तथा 4. सार्वनामिक विशेषण।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b33a30a-6750-4b4e-b599-208287c0d712', 'चार भेद (गुणवाचक, संख्यावाचक, परिमाणवाचक, और सार्वनामिक विशेषण)', true, '210865a7-1b5b-4395-aa4c-40c8e4f7010c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8471ad1-9ab6-43b5-8790-06ada612fef6', 'तीन भेद', false, '210865a7-1b5b-4395-aa4c-40c8e4f7010c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('527052fd-c576-4fb1-9ce5-61cb2189066c', 'पाँच भेद', false, '210865a7-1b5b-4395-aa4c-40c8e4f7010c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe09b43f-5acd-40a0-8d37-81573aaae913', 'छह भेद', false, '210865a7-1b5b-4395-aa4c-40c8e4f7010c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67d65f64-eb4f-44c4-884e-4038fc063e6f', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'जो विशेषण शब्द संज्ञा या सर्वनाम के गुण, दोष, रंग, रूप, आकार, दशा, स्वाद या स्पर्श का बोध कराते हैं, उन्हें क्या कहते हैं?', 'गुण, दोष, रंग, आकार, अवस्था का बोध कराने वाले शब्द ''गुणवाचक विशेषण'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aefc91e0-6192-4ee2-a7a5-fc47c4cbb520', 'गुणवाचक विशेषण (जैसे: ''ईमानदार लड़का'', ''काला घोड़ा'', ''गोल मेज'', ''मीठा आम'')', true, '67d65f64-eb4f-44c4-884e-4038fc063e6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27f7090a-8a63-4ca0-9e26-5b91870ae9d4', 'संख्यावाचक विशेषण', false, '67d65f64-eb4f-44c4-884e-4038fc063e6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1dc5e50-b764-49bd-9398-907d55b8c26b', 'परिमाणवाचक विशेषण', false, '67d65f64-eb4f-44c4-884e-4038fc063e6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f5edb89-dc3c-4a1b-86f9-f0eb2a9096d8', 'सार्वनामिक विशेषण', false, '67d65f64-eb4f-44c4-884e-4038fc063e6f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1a6fc97-b8ac-483a-8db7-745e30c7bdfd', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'जो विशेषण शब्द संज्ञा या सर्वनाम की संख्या (गिनती) का बोध कराते हैं, उन्हें क्या कहते हैं?', 'गणनीय वस्तुओं की संख्या दर्शाने वाले शब्द ''संख्यावाचक विशेषण'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82fe71f6-da39-4514-82c9-692cbb63beb8', 'संख्यावाचक विशेषण (जैसे: ''चार पुस्तकें'', ''कुछ बच्चे'', ''पहला स्थान'')', true, 'e1a6fc97-b8ac-483a-8db7-745e30c7bdfd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('139113ba-769d-4df3-bcb5-1f89cea91ade', 'गुणवाचक विशेषण', false, 'e1a6fc97-b8ac-483a-8db7-745e30c7bdfd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65920ced-6562-4944-b74c-52be6b42a8f8', 'परिमाणवाचक विशेषण', false, 'e1a6fc97-b8ac-483a-8db7-745e30c7bdfd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a78cc32d-1c5c-4cff-a9e0-1f1a0e0fc719', 'सार्वनामिक विशेषण', false, 'e1a6fc97-b8ac-483a-8db7-745e30c7bdfd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3ad620c-9792-4e93-afea-e633004e734c', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'संख्यावाचक विशेषण के कितने उपभेद होते हैं?', 'निश्चित संख्या (पाँच, दस, पहला) तथा अनिश्चित संख्या (कुछ, कई, अनेक, सब) इसके दो उपभेद हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80bce093-fc6a-4ed3-bf6e-97a83927523d', 'दो उपभेद (1. निश्चित संख्यावाचक जैसे ''दस छात्र'', और 2. अनिश्चित संख्यावाचक जैसे ''कुछ लोग'')', true, 'f3ad620c-9792-4e93-afea-e633004e734c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73930936-4be1-4db9-bb5d-bb586730aca3', 'तीन उपभेद', false, 'f3ad620c-9792-4e93-afea-e633004e734c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0dc5ec80-b2ed-4d39-8208-98f7a201a34e', 'चार उपभेद', false, 'f3ad620c-9792-4e93-afea-e633004e734c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fef8d45-77fd-47aa-a0dd-eacafb7af722', 'पाँच उपभेद', false, 'f3ad620c-9792-4e93-afea-e633004e734c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5f33544-4391-4177-afc8-f8bd43123931', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'जो विशेषण शब्द किसी वस्तु की नाप, तौल या माप (मात्रा) का बोध कराते हैं (जिन्हें गिना नहीं जा सकता, केवल नापा/तौला जाता है), उन्हें क्या कहते हैं?', 'द्रव्य या अगणनीय वस्तुओं की माप-तौल बताने वाले शब्द ''परिमाणवाचक विशेषण'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33bbc355-b6b9-46dc-ac07-615ecb6c8952', 'परिमाणवाचक विशेषण (जैसे: ''दो लीटर दूध'', ''पाँच किलो आटा'', ''थोड़ा पानी'')', true, 'e5f33544-4391-4177-afc8-f8bd43123931');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2117a1c1-1a2f-4e46-8da9-1f0b730dad36', 'संख्यावाचक विशेषण', false, 'e5f33544-4391-4177-afc8-f8bd43123931');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95e07210-fe15-49b6-9cc5-6b0ba45f1dd2', 'गुणवाचक विशेषण', false, 'e5f33544-4391-4177-afc8-f8bd43123931');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4314f615-750a-4fc4-b7be-f27cc2aa2d15', 'सार्वनामिक विशेषण', false, 'e5f33544-4391-4177-afc8-f8bd43123931');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a634b305-e630-4875-b2f5-851e445b072c', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'परिमाणवाचक विशेषण के दो उपभेद कौन-से हैं?', 'निश्चित माप-तौल = निश्चित परिमाणवाचक; अनुमानित अनिर्दिष्ट माप = अनिश्चित परिमाणवाचक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b0ee65b-bf70-4e9c-9d05-db32bcd16f13', 'निश्चित परिमाणवाचक (जैसे: ''3 मीटर कपड़ा'', ''2 किलो चीनी'') और अनिश्चित परिमाणवाचक (जैसे: ''थोड़ा दूध'', ''ज्यादा पानी'')', true, 'a634b305-e630-4875-b2f5-851e445b072c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad912e68-ee7a-4971-b324-cfa6e7cd171e', 'उत्तम और मध्यम', false, 'a634b305-e630-4875-b2f5-851e445b072c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dee7be8c-1569-4dec-87e2-7a62a610ae4d', 'सकर्मक और अकर्मक', false, 'a634b305-e630-4875-b2f5-851e445b072c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2cbfffa-6d5e-4dd0-89d1-919f2a94cd27', 'प्रत्यय और उपसर्ग', false, 'a634b305-e630-4875-b2f5-851e445b072c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6c2957c9-014e-4c89-bde1-42b6189cc212', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'जो सर्वनाम शब्द संज्ञा से ठीक पहले आकर उसकी ओर संकेत करते हैं और विशेषण का कार्य करते हैं, उन्हें क्या कहते हैं?', 'संज्ञा से पूर्व प्रयुक्त होकर निर्देश करने वाले सर्वनाम पद ''सार्वनामिक विशेषण'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a485b327-c937-41de-871b-1a0907938102', 'सार्वनामिक विशेषण या संकेतवाचक विशेषण (जैसे: ''यह घर मेरा है'', ''वह पुस्तक अच्छी है'')', true, '6c2957c9-014e-4c89-bde1-42b6189cc212');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c49a3da-8f15-48df-9e2e-1d05eb4a915d', 'निजवाचक सर्वनाम', false, '6c2957c9-014e-4c89-bde1-42b6189cc212');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d619099-fa1e-490e-9c0f-470c7510b997', 'गुणवाचक विशेषण', false, '6c2957c9-014e-4c89-bde1-42b6189cc212');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47fe89e4-8648-4252-9cce-f8107126af8b', 'प्रविशेषण', false, '6c2957c9-014e-4c89-bde1-42b6189cc212');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b3606d9-28c8-4ebd-a6db-a8a545ed1b43', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Easy', 'जो शब्द विशेषण की भी विशेषता बताते हैं (जैसे: ''रोहन **बहुत** चतुर लड़का है'', ''सेब **अत्यंत** मीठा है''), उन्हें व्याकरण में क्या कहते हैं?', 'विशेषण शब्दों की तीव्रता या न्यूनता बताने वाले पद ''प्रविशेषण'' कहलाते हैं (जैसे: ''बहुत'' सुंदर)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef39367e-a091-4727-869c-ccedc9db3b59', 'प्रविशेषण (जैसे: बहुत, अत्यंत, अत्यधिक, बड़ा, थोड़ा)', true, '1b3606d9-28c8-4ebd-a6db-a8a545ed1b43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba08d5a5-9d3a-4ab8-813f-dc95d481857d', 'विशेष्य', false, '1b3606d9-28c8-4ebd-a6db-a8a545ed1b43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d294731e-8b2f-4955-9f22-c8b2e49fd125', 'सर्वनाम', false, '1b3606d9-28c8-4ebd-a6db-a8a545ed1b43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('959a550a-3a07-42b5-8578-30bd9ecc8b6c', 'क्रियाविशेषण', false, '1b3606d9-28c8-4ebd-a6db-a8a545ed1b43');
