INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed4482b4-3bb6-4c4e-a37d-051f127041ff', 'गुणवाचक विशेषण', false, 'fd61dd64-3e47-4f1a-9d71-f33500bcf545');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f18ff9e6-700e-4ee6-813a-89c6372d6c73', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'संख्यावाचक विशेषण और परिमाणवाचक विशेषण में क्या मुख्य अंतर होता है?', 'गणनीय संज्ञा = संख्यावाचक विशेषण; माप-तौल योग्य अगणनीय द्रव्य = परिमाणवाचक विशेषण।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afa6942f-e7d3-4800-b17c-410c18e5cf22', 'संख्यावाचक विशेषण उन वस्तुओं के लिए आता है जिन्हें गिना जा सकता है (Countable - जैसे: ''चार केले'', ''दस पुस्तकें'') ; परिमाणवाचक विशेषण उन वस्तुओं के लिए आता है जिन्हें गिना नहीं जा सकता, केवल नापा/तौला जाता है (Uncountable - जैसे: ''चार लीटर दूध'', ''दस किलो गेहूँ'')', true, 'f18ff9e6-700e-4ee6-813a-89c6372d6c73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('224d22e2-a7ab-446e-8010-dc93ca224089', 'संख्यावाचक केवल जानवरों के लिए आता है', false, 'f18ff9e6-700e-4ee6-813a-89c6372d6c73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dcbe5cb-f194-46cc-9591-3dd70bf46df0', 'परिमाणवाचक में संख्या नहीं होती', false, 'f18ff9e6-700e-4ee6-813a-89c6372d6c73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('348288f3-acff-47b6-800c-a1e9c3c0daba', 'दोनों में कोई अंतर नहीं है', false, 'f18ff9e6-700e-4ee6-813a-89c6372d6c73');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81bae61f-47dd-4471-a759-c62644d2de49', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'वाक्य में प्रयुक्त दोनों ''कुछ'' का सही विशेषण क्रम बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e749993e-ea28-4192-9626-72e6f8466fff', 'कुछ फल = अनिश्चित संख्यावाचक ; कुछ दूध = अनिश्चित परिमाणवाचक', true, '81bae61f-47dd-4471-a759-c62644d2de49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68b8f217-7db1-4965-a029-25fbc8523a42', 'कुछ फल = परिमाणवाचक ; कुछ दूध = संख्यावाचक', false, '81bae61f-47dd-4471-a759-c62644d2de49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81395ac6-3da5-41ab-b970-74b621a4e52f', 'दोनों संख्यावाचक हैं', false, '81bae61f-47dd-4471-a759-c62644d2de49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c2d4c03-6cda-444a-bb59-0db32b816370', 'दोनों परिमाणवाचक हैं', false, '81bae61f-47dd-4471-a759-c62644d2de49');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf4ddaf4-e85d-4868-9317-8e1f1219f9d0', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'संज्ञा शब्द ''भारत'' और ''इतिहास'' से बनने वाले सही विशेषण शब्द क्रमशः क्या हैं?', 'भारत + ईय = भारतीय; इतिहास + इक = ऐतिहासिक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b174c07-213b-4bca-a568-231deec69bec', 'भारतीय और ऐतिहासिक', true, 'cf4ddaf4-e85d-4868-9317-8e1f1219f9d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bd0210a-ec53-47dc-b0d4-3351e7a31128', 'भारतवासी और इतिहासी', false, 'cf4ddaf4-e85d-4868-9317-8e1f1219f9d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6715f483-5751-41c5-9c95-87b98b969081', 'भारती और इतिहासवान', false, 'cf4ddaf4-e85d-4868-9317-8e1f1219f9d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97294048-b7a9-4109-ada3-d69f682f3292', 'भारतीकरण और इतिहासिक', false, 'cf4ddaf4-e85d-4868-9317-8e1f1219f9d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d4b7890-baf2-412e-88fd-eafd49bad5fa', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'संज्ञा शब्द ''दया'', ''धर्म'' और ''नगर'' से ''इक'' या ''लु'' प्रत्यय जोड़कर बनने वाले विशेषण शब्द क्या हैं?', 'दया + आलु = दयालु; धर्म + इक = धार्मिक; नगर + इक = नागरिक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6bb9b61-b15b-49f4-80fd-1c1c42718b8b', 'दयालु, धार्मिक, नागरिक', true, '0d4b7890-baf2-412e-88fd-eafd49bad5fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1def9629-e319-4be5-9de2-cd94e90ba5b2', 'दयी, धर्मात्मा, नगरी', false, '0d4b7890-baf2-412e-88fd-eafd49bad5fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd0e2d23-2751-409f-8907-c82ccef90f50', 'दयावान, धर्महीन, नगरिया', false, '0d4b7890-baf2-412e-88fd-eafd49bad5fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01f60d11-d97c-4f15-b81b-a59dd1093c94', 'दयानंद, धर्मिक, नगरवासी', false, '0d4b7890-baf2-412e-88fd-eafd49bad5fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ab94b75-8e1f-46f9-970e-43b69b467da0', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'संज्ञा शब्द ''जंग'' और ''विष'' से ''ईला'' प्रत्यय लगाकर बनने वाले सही विशेषण रूप क्या हैं?', 'जंगल + ई = जंगली; विष + ऐला = विषैला।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0d40d31-2bf9-40c4-95de-428fbfdcb1ee', 'जंगली और विषैला (या जहरीला)', true, '3ab94b75-8e1f-46f9-970e-43b69b467da0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('848f7c96-6822-406e-9330-ff41363586cc', 'जंगला और विषैली', false, '3ab94b75-8e1f-46f9-970e-43b69b467da0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e80888c-455e-48e7-ba3b-65ae5f1c5bc3', 'जंगलू और विषवान', false, '3ab94b75-8e1f-46f9-970e-43b69b467da0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f2353d3-975e-458b-8037-a34251dbbb77', 'जंगलमय और विषयुक्त', false, '3ab94b75-8e1f-46f9-970e-43b69b467da0');
