INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7d53421-cf9b-4a27-abfe-987f26d64c37', 'सार्वनामिक विशेषण (संज्ञा ''लड़का'' के आगे आकर संकेत करने वाला पद)', true, '07d6e14d-df2e-416b-968e-98a17d3cd1c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d310fe83-c952-43b2-81d4-74b829e28bde', 'निश्चयवाचक सर्वनाम', false, '07d6e14d-df2e-416b-968e-98a17d3cd1c2');
