INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ae4b5f1-967d-4ac6-b79d-db16b4b50996', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'विशेषण की तुलना की दृष्टि से कितनी अवस्थाएँ (Degrees of Comparison) होती हैं?', 'तुलनात्मक 3 अवस्थाएँ: मूलावस्था (Positive), उत्तरावस्था (Comparative: -तर), उत्तमावस्था (Superlative: -तम)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83f70d3e-264b-4401-8486-32add94f1f2d', 'तीन अवस्थाएँ (1. मूलावस्था - जैसे ''सुंदर'', 2. उत्तरावस्था - जैसे ''सुंदरतर / अधिक सुंदर'', 3. उत्तमावस्था - जैसे ''सुंदरतम / सबसे सुंदर'')', true, '7ae4b5f1-967d-4ac6-b79d-db16b4b50996');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3b0ac70-581f-4e22-8e1a-0cd297574196', 'दो अवस्थाएँ', false, '7ae4b5f1-967d-4ac6-b79d-db16b4b50996');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9eb91bb5-8c04-4695-8c1e-137ccb684a81', 'चार अवस्थाएँ', false, '7ae4b5f1-967d-4ac6-b79d-db16b4b50996');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e5d4074-87c2-44b1-8629-d8c397c8f937', 'पाँच अवस्थाएँ', false, '7ae4b5f1-967d-4ac6-b79d-db16b4b50996');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f9b2b89-c979-464a-91ba-c295d04c4221', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'शब्द ''उच्च'' की उत्तरावस्था और उत्तमावस्था के सही रूप क्रमशः क्या हैं?', 'उच्च (मूलावस्था) -> उच्चतर (उत्तरावस्था) -> उच्चतम (उत्तमावस्था)।', NOW()) ON CONFLICT DO NOTHING;
