INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a21035f3-b084-434e-b635-01feea5f4afa', 'उच्ची और सर्वोच्च', false, '8f9b2b89-c979-464a-91ba-c295d04c4221');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e00f5264-034d-458b-8b0a-886ed5592724', 'उच्चतम और उच्चतर', false, '8f9b2b89-c979-464a-91ba-c295d04c4221');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6c36b60a-9394-42b4-8e24-38f14dbc5ac4', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'वाक्य में प्रयुक्त रेखांकित पद का व्याकरणिक परिचय दीजिए:
