INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f1ac4eb-d33f-4822-9ebc-e6ac29e1c85c', 'तीनों संज्ञा पद हैं', false, '6c36b60a-9394-42b4-8e24-38f14dbc5ac4');
