INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('629ab64e-7602-4b95-8d6f-3cf0e4820825', 'अनिश्चित संख्यावाचक विशेषण (''हज़ारों'' अनिश्चित बड़ी संख्या का द्योतक है)', true, '57c92f98-d331-4209-a915-d97967e8882f');
