INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('650fb206-c681-407b-842a-8d91bdb2217f', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'क्रिया पद ''हँसना'' और ''पढ़ना'' से बनने वाले सही विशेषण शब्द क्रमशः क्या हैं?', 'हँसना -> हँसमुख/हँसोड़; पढ़ना -> पढ़ाकू (कृदंत विशेषण)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd5197fe-2a0a-4b5e-b269-ac259c392002', 'हँसोड़ (या हँसमुख) और पढ़ाकू', true, '650fb206-c681-407b-842a-8d91bdb2217f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e3d1bf3-5ace-434e-b04b-e8e4226a8429', 'हँसी और पढ़ाई', false, '650fb206-c681-407b-842a-8d91bdb2217f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba305db4-cfd4-47a6-a3df-0c892aa13fba', 'हँसा और पढ़ा', false, '650fb206-c681-407b-842a-8d91bdb2217f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('639221bc-283e-470c-b728-2d9de9ee7576', 'हँसानेवाला और पढ़ानेवाला', false, '650fb206-c681-407b-842a-8d91bdb2217f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('65e9103d-4571-4235-8cff-4038cccff890', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'अव्यय पद ''बाहर'' और ''आगे'' से बनने वाले विशेषण शब्द क्रमशः क्या हैं?', 'बाहर + ई = बाहरी; आगे + ला = अगला; पीछे + ला = पिछला।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9046e9cf-a739-4b07-9b66-7fbf5e41cd6b', 'बाहरी और अगला', true, '65e9103d-4571-4235-8cff-4038cccff890');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('beacb516-d7b4-4db2-911f-3f54e3e2d18b', 'बाहरवाला और आगेवाला', false, '65e9103d-4571-4235-8cff-4038cccff890');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1a55dcd-bb7a-4d9d-8b15-60a037a74092', 'बाह्य और अग्रिम', false, '65e9103d-4571-4235-8cff-4038cccff890');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5570fdfc-81e7-4819-862f-dbb576ceec8c', 'बहार और आगा', false, '65e9103d-4571-4235-8cff-4038cccff890');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d982589-3902-40c4-82b8-9a33f7dc000e', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'स्थानवाचक गुणवाचक विशेषण का सही समूह कौन-सा है?', 'स्थान, भूभाग या क्षेत्र से संबद्ध विशेषता बताने वाले शब्द स्थानवाचक गुणवाचक विशेषण हैं (बनारसी साड़ी, जोधपुरी पगड़ी)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9088b0d-5fc4-4650-8242-26c2ec3780dd', 'भारतीय, जापानी, बनारसी, ग्रामीण, शहरी, पहाड़ी', true, '7d982589-3902-40c4-82b8-9a33f7dc000e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb8f05db-e216-4f7c-b7a6-99642ae321cf', 'लाल, पीला, नीला, हरा', false, '7d982589-3902-40c4-82b8-9a33f7dc000e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('991d0867-ff65-4ebd-a9c2-7401e291097a', 'गोल, चौकोर, नुकीला', false, '7d982589-3902-40c4-82b8-9a33f7dc000e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('622049e6-b9f0-49a7-bae9-af814e044fb1', 'मीठा, खट्टा, कड़वा', false, '7d982589-3902-40c4-82b8-9a33f7dc000e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('715207dc-5590-4ca8-b9fd-abe21c4d605e', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'स्पर्शवाचक गुणवाचक विशेषण का सही उदाहरण कौन-सा है?', 'त्वचा द्वारा अनुभव किए जाने वाले गुण (कोमल, कठोर, खुरदुरा) स्पर्शवाचक विशेषण हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33f14b50-b598-4d4b-9528-876545b0eb9c', 'कोमल, कठोर, खुरदुरा, मुलायम, चिकना, ठंडा', true, '715207dc-5590-4ca8-b9fd-abe21c4d605e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60a7da15-62f8-401c-b515-a952797a0ab9', 'सुगंधित और दुर्गंधयुक्त', false, '715207dc-5590-4ca8-b9fd-abe21c4d605e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e01bee0-8487-48ca-9201-1452c7824834', 'लंबा और चौड़ा', false, '715207dc-5590-4ca8-b9fd-abe21c4d605e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('feb431d1-912c-415e-9a13-817956b85c48', 'स्वस्थ और रोगी', false, '715207dc-5590-4ca8-b9fd-abe21c4d605e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('930eae4c-adbb-48b2-81fc-6cbe851e443f', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Medium', 'कालवाचक गुणवाचक विशेषण का सही उदाहरण कौन-सा है?', 'समय या काल की विशेषता दर्शाने वाले पद (प्राचीन, नवीन, दैनिक, मौसमी) कालवाचक विशेषण हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d9fef70-3dae-4055-82e9-f5053d92a409', 'नया, पुराना, प्राचीन, दैनिक, वार्षिक, मौसमी, आधुनिक', true, '930eae4c-adbb-48b2-81fc-6cbe851e443f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85baf8b7-2aa0-410c-be0b-6a5c75756fd0', 'सुंदर और कुरूप', false, '930eae4c-adbb-48b2-81fc-6cbe851e443f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ca3e1ba-df6f-4580-bdda-2287b36ec40b', 'कायर और वीर', false, '930eae4c-adbb-48b2-81fc-6cbe851e443f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fc6a86d-54d0-44f9-b33a-175a6874ad2c', 'लाल और पीला', false, '930eae4c-adbb-48b2-81fc-6cbe851e443f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36bc964d-d817-4914-88f2-aefa79c46659', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4902484b-3bfb-4fb3-99c8-1ca37f084cf0', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '36bc964d-d817-4914-88f2-aefa79c46659');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21752d3b-e73c-4428-a81c-dff0fb62fbf9', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '36bc964d-d817-4914-88f2-aefa79c46659');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65197dd1-c3b9-45de-b26c-9dd4e597f0e3', '(A) सही है, परन्तु (R) गलत है।', false, '36bc964d-d817-4914-88f2-aefa79c46659');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96ad240d-332c-4a19-a076-695140352c23', '(A) गलत है, परन्तु (R) सही है।', false, '36bc964d-d817-4914-88f2-aefa79c46659');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea4a3521-bcd2-4c29-a970-5a4441eaa301', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'Spot the IMPOSTER in the following group of विशेषण और उनके भेदों के युग्म में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('598656d4-91ab-4ddb-bc4f-cead742419ab', 'चार पुस्तकें - निश्चित संख्यावाचक', false, 'ea4a3521-bcd2-4c29-a970-5a4441eaa301');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d79a68b-f97f-4896-9d46-08a53cccaa7a', 'थोड़ा पानी - अनिश्चित परिमाणवाचक', false, 'ea4a3521-bcd2-4c29-a970-5a4441eaa301');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb8e9a93-b2bd-428c-834b-761a9b0209c7', 'यह बालक - सार्वनामिक विशेषण', false, 'ea4a3521-bcd2-4c29-a970-5a4441eaa301');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f524e7c9-84ab-4297-ae24-c62f5b699d85', 'ईमानदार लड़का - अनिश्चित संख्यावाचक', true, 'ea4a3521-bcd2-4c29-a970-5a4441eaa301');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56771729-f20b-4c74-b9b4-b437c12a771f', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'सुमेलित कीजिए (संज्ञा शब्द और उनसे बने शुद्ध विशेषण):
(क) भूगोल  -> (i) वार्षिक
(ख) वर्ष    -> (ii) भौगोलिक
(ग) चमक    -> (iii) विषैला
(घ) विष     -> (iv) चमकीला', 'भूगोल = भौगोलिक; वर्ष = वार्षिक; चमक = चमकीला; विष = विषैला।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc4031d8-fd17-4d3b-a4ba-878d8f71ddc1', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', true, '56771729-f20b-4c74-b9b4-b437c12a771f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bea85f0-efcc-47d2-9080-e1f7d0c1b9d5', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, '56771729-f20b-4c74-b9b4-b437c12a771f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fe8c5f7-4c58-43eb-960a-36c32a6cb1af', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '56771729-f20b-4c74-b9b4-b437c12a771f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f28e028-6760-4b96-a7e7-5e562ef371a5', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '56771729-f20b-4c74-b9b4-b437c12a771f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e155f89c-fffe-4ffa-aaa1-c5434a020e7d', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'निश्चित संख्यावाचक विशेषण के पाँच प्रमुख उप-प्रकारों (गणनावाचक, क्रमवाचक, आवृत्तिवाचक, समुदायवाचक, प्रत्येकबोधक) का सही सुमेल कौन-सा है?', 'निश्चित संख्या के 5 प्रकार: गणना (1, 2), क्रम (पहला, दूसरा), आवृत्ति (दुगुना, चौगुना), समुदाय (दोनों, तीनों), प्रत्येकबोधक (हर एक, प्रति)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d306b2f2-e803-4d11-a100-874cb1dcd764', 'एक, दो (गणनावाचक) ; पहला, दूसरा (क्रमवाचक) ; दुगुना, तिगुना (आवृत्तिवाचक) ; दोनों, चारों (समुदायवाचक) ; प्रत्येक, हर एक (प्रत्येकबोधक)', true, 'e155f89c-fffe-4ffa-aaa1-c5434a020e7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48aaf4be-7796-4799-bfc4-3bf54188f9ed', 'सभी केवल गणनावाचक हैं', false, 'e155f89c-fffe-4ffa-aaa1-c5434a020e7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5564bc1e-fcb2-4214-ae80-9c7680bce851', 'पहला दूसरा समुदायवाचक है', false, 'e155f89c-fffe-4ffa-aaa1-c5434a020e7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16ea889d-3c1a-457f-897f-b0be85e8c9bf', 'दुगुना तिगुना क्रमवाचक है', false, 'e155f89c-fffe-4ffa-aaa1-c5434a020e7d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('548ce9e6-0493-4365-9b81-bcee7d6536c7', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'वाक्य में प्रयुक्त रेखांकित पद का सही व्याकरणिक भेद बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7aee4abd-e448-497f-8846-29518bf58816', 'गुणवाचक विशेषण (उत्तमावस्था - Superlative Degree)', true, '548ce9e6-0493-4365-9b81-bcee7d6536c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a719a1da-1065-4df0-b6ec-c8b86b4dab08', 'उत्तरावस्था', false, '548ce9e6-0493-4365-9b81-bcee7d6536c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df81ecee-95bd-4971-9aa7-89649e10093a', 'मूलावस्था', false, '548ce9e6-0493-4365-9b81-bcee7d6536c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ce2ae6e-e574-47ea-9ec4-59da2538540f', 'प्रविशेषण', false, '548ce9e6-0493-4365-9b81-bcee7d6536c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('71adc38d-9589-4664-9407-845a6229b8cf', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'उद्देश्य विशेषण (Attributive) और विधेय विशेषण (Predicative) में क्या अंतर होता है?', 'विशेष्य से पूर्व स्थिति = उद्देश्य विशेषण (लाल गुलाब); विशेष्य के उपरांत स्थिति = विधेय विशेषण (गुलाब लाल है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a15601e-830a-4960-8fb2-71aefd175410', 'जब विशेषण शब्द विशेष्य (संज्ञा) से पहले आता है तो वह ''उद्देश्य विशेषण'' कहलाता है (जैसे: ''यह मीठा सेब है'') ; और जब विशेषण विशेष्य के बाद तथा क्रिया से पहले आता है तो वह ''विधेय विशेषण'' कहलाता है (जैसे: ''यह सेब मीठा है'')', true, '71adc38d-9589-4664-9407-845a6229b8cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ed6f02d-3cd6-4667-906c-ccc8dcccdbda', 'उद्देश्य विशेषण में विशेष्य नहीं होता', false, '71adc38d-9589-4664-9407-845a6229b8cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9333168b-505e-465b-be31-ef4c4a481b1c', 'विधेय विशेषण केवल भूतकाल में आता है', false, '71adc38d-9589-4664-9407-845a6229b8cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74d4d2bd-f614-412f-98a8-92d90d0214a2', 'दोनों में कोई अंतर नहीं है', false, '71adc38d-9589-4664-9407-845a6229b8cf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd07d9ca-96e7-4069-a295-1b549fb25f29', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'संज्ञा शब्द ''शरीर'', ''बुद्धि'' और ''ज्ञान'' से ''इक'' या ''वान'' प्रत्यय लगाने पर सही विशेषण रूप क्या बनेंगे?', 'शरीर + इक = शारीरिक (आदि स्वर वृद्धि); बुद्धि + इक = बौद्धिक (उ का औ); ज्ञान + वान = ज्ञानवान।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73e9c1ed-5282-4b1b-b277-d5a61330933b', 'शारीरिक, बौद्धिक, ज्ञानवान', true, 'fd07d9ca-96e7-4069-a295-1b549fb25f29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18060883-0a2a-4449-904f-f13fcc3e4aee', 'शरीरी, बुद्धिमान, ज्ञानी', false, 'fd07d9ca-96e7-4069-a295-1b549fb25f29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14039a3e-1596-4921-93e1-11a980093f1e', 'शारीरिक, बुद्धिक, ज्ञानमय', false, 'fd07d9ca-96e7-4069-a295-1b549fb25f29');
