INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1490f39a-22ec-4a20-8b68-a3e47b93a3dc', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'सर्वनाम पद ''यह'' और ''वह'' से निर्मित विशेषण शब्द क्रमशः क्या हैं?', 'सर्वनामों से रूपांतरित यौगिक विशेषण: ''यह'' -> ऐसा/इतना; ''वह'' -> वैसा/उतना; ''कौन'' -> कैसा/कितना; ''जो'' -> जैसा/जितना।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2839160a-a664-4506-ba25-f62ffff865f3', 'ऐसा (या इतना) और वैसा (या उतना)', true, '1490f39a-22ec-4a20-8b68-a3e47b93a3dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bff0562d-925f-4a8e-9538-0dece888995a', 'यहवाला और वहवाला', false, '1490f39a-22ec-4a20-8b68-a3e47b93a3dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f55af929-dfa7-4e53-8754-6ba8d8b3e49a', 'यहाँ और वहाँ', false, '1490f39a-22ec-4a20-8b68-a3e47b93a3dc');
