INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75140cab-79e7-43f9-adc3-aff45f8ee407', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'व्यक्तिवाचक विशेषण (Proper Adjective) का सही उदाहरण कौन-सा है?', 'व्यक्तिवाचक संज्ञाओं से निर्मित विशेषण ''व्यक्तिवाचक विशेषण'' कहलाते हैं (जयपुर -> जयपुरी; बनारस -> बनारसी; कश्मीर -> कश्मीरी)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf9babe7-e281-4e96-a40d-9eac9b373622', 'जयपुरी रज़ाई, बनारसी साड़ी, लखनवी चिकन, कश्मीरी सेब, बीकानेरी भुजिया', true, '75140cab-79e7-43f9-adc3-aff45f8ee407');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a67db70c-2a01-45ac-9d5c-ee605622c7ae', 'अच्छा लड़का और सुंदर लड़की', false, '75140cab-79e7-43f9-adc3-aff45f8ee407');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71cd758d-00e7-42b4-b8ef-d2e097776725', 'दो किलो आम', false, '75140cab-79e7-43f9-adc3-aff45f8ee407');
