INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9676df96-1eec-4a29-9be2-e92b43cfeba5', 'प्रत्येकबोधक निश्चित संख्यावाचक विशेषण', true, 'a1e08b90-670c-434b-81c2-558f87177374');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1a289b3-dc3f-457f-89f7-9249f5f4cc9c', 'अनिश्चित परिमाणवाचक', false, 'a1e08b90-670c-434b-81c2-558f87177374');
