INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9aac8b0f-6349-45e7-aff5-2aa2aa2e5b91', '''यह सबसे सुंदर फूल है।'' (या ''यह सुंदरतम फूल है।'' - ''सबसे'' और ''-तम'' दोनों का एक साथ प्रयोग पुनरुक्ति दोष है)', true, '1fe52bf7-0299-4348-b416-ca22dc936a12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23eb4a5f-5679-4c32-9e07-d785e44f9d3f', 'यह सुंदर फूल है सबसे।', false, '1fe52bf7-0299-4348-b416-ca22dc936a12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bfbe861-1174-494e-85a6-387b278ef096', 'यह सुंदरतम सबसे फूल है।', false, '1fe52bf7-0299-4348-b416-ca22dc936a12');
