INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b63a9b5e-95c0-4a1d-876d-38f4064d2d80', 'Class 6', 'Hindi Grammar', 'Chapter 9: विशेषण', 'Hard', 'विशेषण पदों की पद-व्याख्या (पद-परिचय) करते समय किन-किन व्याकरणिक तत्वों का उल्लेख करना अनिवार्य होता है?', 'विशेषण के पद-परिचय में 5 तत्व शामिल होते हैं: भेद, अवस्था, लिंग, वचन और विशेष्य।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('934aed9c-919e-44cd-a82f-578e1a38b684', 'विशेषण का भेद, उसकी अवस्था (मूलावस्था/उत्तरावस्था/उत्तमावस्था), उसका लिंग, वचन, तथा उसका संबंधित विशेष्य पद', true, 'b63a9b5e-95c0-4a1d-876d-38f4064d2d80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99b4793e-8d2f-48a1-a9c8-0fb8349211a2', 'केवल उसका अर्थ', false, 'b63a9b5e-95c0-4a1d-876d-38f4064d2d80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b16f96c-da4c-4c6d-ade6-efe4bb075e58', 'केवल कारक चिह्न', false, 'b63a9b5e-95c0-4a1d-876d-38f4064d2d80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6882aaab-8009-423d-ab69-e94cb8f7c175', 'केवल काल', false, 'b63a9b5e-95c0-4a1d-876d-38f4064d2d80');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bc77d902-a04a-4e1a-b8a6-0e6780d1ca27', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'What is a naturally occurring magnetic rock/mineral consisting of iron oxide (Fe₃O₄) that was discovered in ancient Greece?', 'Magnetite is a natural permanent magnet discovered in Magnesia, ancient Greece, also called ''lodestone'' (''leading stone'').', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb250ca7-9d48-41c6-ab09-c7784a661227', 'Magnetite (Lodestone)', true, 'bc77d902-a04a-4e1a-b8a6-0e6780d1ca27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e32d9e6-3c12-4c23-876e-8588484b2c4f', 'Hematite', false, 'bc77d902-a04a-4e1a-b8a6-0e6780d1ca27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dfce869-c846-476a-a85d-d34c3b383a05', 'Bauxite', false, 'bc77d902-a04a-4e1a-b8a6-0e6780d1ca27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec62ba6b-889f-4598-98f0-2e6b0a45dab8', 'Pyrite', false, 'bc77d902-a04a-4e1a-b8a6-0e6780d1ca27');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fcd4cc53-a390-4afe-b927-3ad07fe1dc73', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'Who was the ancient Greek shepherd who discovered natural magnetic rock when the iron tip of his walking stick and iron nails in his shoes got stuck to a black rock?', 'Legend says the shepherd Magnes discovered magnetic ore on Mount Ida when his iron-tipped staff stuck to magnetite rocks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ead318a4-fa75-4948-8889-1e1222fc4f0b', 'Magnes', true, 'fcd4cc53-a390-4afe-b927-3ad07fe1dc73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10c4abe3-dd73-4f83-afe4-6af65fc4c9ed', 'Archimedes', false, 'fcd4cc53-a390-4afe-b927-3ad07fe1dc73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('010a0e3d-aa57-4aad-a9df-a90f5d6dbb10', 'Aristotle', false, 'fcd4cc53-a390-4afe-b927-3ad07fe1dc73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbd7e2b8-4aa5-4ca9-9e1c-8eafaa29ca39', 'Socrates', false, 'fcd4cc53-a390-4afe-b927-3ad07fe1dc73');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('030b9897-a621-4a49-94b8-b5d2adc53701', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'Materials that are attracted strongly towards a magnet (such as iron, nickel, cobalt, and steel) are called:', 'Ferromagnetic materials containing unpaired d-electrons (Fe, Ni, Co) are attracted to magnetic fields.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2ea8648-bf5b-4305-948e-afde0d25d301', 'Magnetic Materials', true, '030b9897-a621-4a49-94b8-b5d2adc53701');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb7e5966-25f0-4336-a7b6-b737dcd738f0', 'Non-magnetic Materials', false, '030b9897-a621-4a49-94b8-b5d2adc53701');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6dc2f09d-9908-4e8e-84bb-ce4e1a9642c2', 'Insulators', false, '030b9897-a621-4a49-94b8-b5d2adc53701');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('410c94fb-9b0f-47cf-9ee9-90d4ddc1ec6c', 'Plastic Materials', false, '030b9897-a621-4a49-94b8-b5d2adc53701');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('121b3547-e0f3-425a-bfc3-6290f8bb6e78', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'Materials that are NOT attracted towards a magnet (such as wood, plastic, rubber, glass, paper, gold, aluminium) are called:', 'Non-magnetic materials lack permanent atomic magnetic dipoles and do not exhibit magnetic attraction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38444a5c-3bc7-48f2-b61c-b1af3d676ee2', 'Non-magnetic Materials', true, '121b3547-e0f3-425a-bfc3-6290f8bb6e78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2eeb3d93-ae04-4a02-abb7-4174b8bd5984', 'Magnetic Materials', false, '121b3547-e0f3-425a-bfc3-6290f8bb6e78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a060294-ef3c-4ad8-a87c-fd81210cc5e0', 'Electromagnets', false, '121b3547-e0f3-425a-bfc3-6290f8bb6e78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87de0a0a-a469-4f47-ac76-1a8d98d2aeda', 'Lodestones', false, '121b3547-e0f3-425a-bfc3-6290f8bb6e78');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f261110d-49b2-4e20-9f51-c0b0815f8920', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'How many magnetic poles does EVERY magnet possess, regardless of its shape or size?', 'Magnetic dipoles always exist in pairs: a North-seeking pole (N) and a South-seeking pole (S).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e705fab2-aa57-49d4-bf4d-f495e5c2fde0', 'Two poles (North Pole ''N'' and South Pole ''S'')', true, 'f261110d-49b2-4e20-9f51-c0b0815f8920');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82451fde-c6a9-4f4e-bef3-3ad0830b0d6b', 'One single pole', false, 'f261110d-49b2-4e20-9f51-c0b0815f8920');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a208543-407c-484d-84b4-270731d570d6', 'Three poles', false, 'f261110d-49b2-4e20-9f51-c0b0815f8920');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a937e60-ba8b-485d-a49f-3b3144353e6d', 'Four poles', false, 'f261110d-49b2-4e20-9f51-c0b0815f8920');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d7add32-c51a-4bd7-a357-b27aff98f1f9', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'Where is the magnetic force (attraction power) of a bar magnet the STRONGEST?', 'Magnetic field flux density converges at the two terminal poles, where iron filings cling in dense clusters.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a937257d-4ae8-41d6-b110-a003fb4a81a4', 'Near its two end Poles (North and South Poles)', true, '8d7add32-c51a-4bd7-a357-b27aff98f1f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e84381b4-86e3-452a-9b96-926f5bfb44d8', 'Exactly at the center of the magnet', false, '8d7add32-c51a-4bd7-a357-b27aff98f1f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd62e297-01b0-4597-b49d-961238e7f96e', 'Uniform everywhere across its body', false, '8d7add32-c51a-4bd7-a357-b27aff98f1f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54ec75b2-f681-4e1d-be25-8683ee27946e', 'Only on its top surface', false, '8d7add32-c51a-4bd7-a357-b27aff98f1f9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba13b520-c7e0-4060-8b43-d4aef415fe78', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'In which geographical direction does a freely suspended bar magnet ALWAYS come to rest?', 'A freely pivoted magnet aligns with Earth''s geomagnetic field lines along the geographic North-South meridian.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7c354ad-667e-4c8f-98dc-a5f3d91e61d9', 'North-South direction (N-S)', true, 'ba13b520-c7e0-4060-8b43-d4aef415fe78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ef8d0ac-0a47-4a77-8d3c-e5085e66172c', 'East-West direction (E-W)', false, 'ba13b520-c7e0-4060-8b43-d4aef415fe78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cdea9cf-b0f5-4718-98f3-47a8299d1c3c', 'North-East direction', false, 'ba13b520-c7e0-4060-8b43-d4aef415fe78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4de5b627-2c6b-4681-b2e6-bff41e1141b3', 'Any random direction', false, 'ba13b520-c7e0-4060-8b43-d4aef415fe78');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8acef74b-aaad-4c11-890f-8f0770794b55', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'What navigational instrument uses a magnetized needle freely pivoted inside a dial to find geographical directions?', 'A magnetic compass features a pivoted magnetized needle whose painted North tip indicates geomagnetic north.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61cf147a-5b90-415f-a62c-ff369217bc81', 'Magnetic Compass', true, '8acef74b-aaad-4c11-890f-8f0770794b55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b493162-7333-4ebc-b2ca-8ce5ccc782fc', 'Speedometer', false, '8acef74b-aaad-4c11-890f-8f0770794b55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbb2583a-5544-4cb1-bc9a-05f15958bf85', 'Barometer', false, '8acef74b-aaad-4c11-890f-8f0770794b55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c2f7ef5-ff4b-4129-be4f-8e89a942a8a5', 'Thermometer', false, '8acef74b-aaad-4c11-890f-8f0770794b55');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b788cfc-ba0e-471d-8425-8fb97260a691', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'What happens when two LIKE magnetic poles (North and North, or South and South) are brought close to each other?', 'Fundamental magnetic law: Like poles repel (N-N or S-S); unlike poles attract (N-S).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99994fbf-c9d8-470a-8a3b-025a32093f5a', 'They REPEL (push away from) each other', true, '9b788cfc-ba0e-471d-8425-8fb97260a691');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3a47794-8e58-463f-926f-dc6ed990a906', 'They attract each other', false, '9b788cfc-ba0e-471d-8425-8fb97260a691');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6aed90a3-9b20-4bb2-8020-d25cb79f61c6', 'They stick together tightly', false, '9b788cfc-ba0e-471d-8425-8fb97260a691');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3610f2ec-0f27-4c87-b97d-aaadb5fd64d7', 'They turn into copper', false, '9b788cfc-ba0e-471d-8425-8fb97260a691');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('39b87fb4-21ed-4adc-99cd-4f4a563b6461', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'What happens when two UNLIKE magnetic poles (North and South) are brought close to each other?', 'Opposite magnetic polarities (N and S) experience mutual attractive Lorentz/dipolar forces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('897cbb3d-a109-49b6-ac29-4b4d32383512', 'They ATTRACT (pull towards) each other', true, '39b87fb4-21ed-4adc-99cd-4f4a563b6461');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b006b721-7678-4295-982f-7504426048b0', 'They repel each other', false, '39b87fb4-21ed-4adc-99cd-4f4a563b6461');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('462a1c47-4137-4f96-a5a3-4928fbac8142', 'They lose their magnetism immediately', false, '39b87fb4-21ed-4adc-99cd-4f4a563b6461');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3908e902-6ddf-4e96-871a-24858ecf5051', 'They heat up and melt', false, '39b87fb4-21ed-4adc-99cd-4f4a563b6461');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('822fdb42-62e7-42ea-b82c-717007c7978f', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'Which of the following is a classic artificial shape of manufactured permanent magnets?', 'Artificial magnets are cast/sintered in bar, horseshoe, disc, cylindrical, and ring geometries.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb2087b2-2fbc-40dc-8924-5b13b849ae9e', 'Bar magnet, Horse-shoe magnet, Cylindrical magnet, and Ball-ended magnet', true, '822fdb42-62e7-42ea-b82c-717007c7978f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2740a757-840c-46e4-befb-5239feaf7c68', 'Square paper magnet', false, '822fdb42-62e7-42ea-b82c-717007c7978f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1915c2b-72e5-479a-953f-7db8d90be4a7', 'Liquid water magnet', false, '822fdb42-62e7-42ea-b82c-717007c7978f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8972a665-258b-44a5-a781-966d566fe8aa', 'Cloth magnet', false, '822fdb42-62e7-42ea-b82c-717007c7978f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20c30120-0623-4a07-8b9b-00e95595eb8b', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Easy', 'What is the surest and only foolproof test to confirm whether an unknown metal piece is an active magnet or merely a magnetic iron piece?', 'Unmagnetized ferromagnetic iron is attracted by both N and S poles; only a true magnet repels like poles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d882cb2-239c-4372-87e2-8abd9c4e2b84', 'REPULSION test (only another magnet will experience repulsion; an ordinary iron piece is attracted to both poles)', true, '20c30120-0623-4a07-8b9b-00e95595eb8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0291a5d7-3d3d-4ea7-affe-c975fd074ab7', 'Attraction test', false, '20c30120-0623-4a07-8b9b-00e95595eb8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be8f3213-545b-48d2-810b-aada884af364', 'Weighing test', false, '20c30120-0623-4a07-8b9b-00e95595eb8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44005591-86f6-4aec-8286-a40e484c4565', 'Color test', false, '20c30120-0623-4a07-8b9b-00e95595eb8b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f421e5d-65cb-477d-9ef0-66f943ac06d7', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'What happens when a bar magnet is cut or broken into TWO halves across its middle?', 'Atomic magnetic domains remain dipolar; cutting a magnet creates two smaller dipoles each with N and S poles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fb3b3fd-e018-4da2-a9c3-915722ccbac2', 'Each broken piece becomes a complete, independent magnet with its own North and South Pole (Magnetic monopoles do NOT exist)', true, '7f421e5d-65cb-477d-9ef0-66f943ac06d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('911719fe-7d3b-4f23-884e-0e413b7f6e68', 'One piece becomes pure North pole and the other pure South pole', false, '7f421e5d-65cb-477d-9ef0-66f943ac06d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b360fff7-023a-465b-8f63-821b58f2290a', 'Both pieces lose all magnetism permanently', false, '7f421e5d-65cb-477d-9ef0-66f943ac06d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('259a87db-acd9-418d-8622-4a8714913f2f', 'The magnet explodes', false, '7f421e5d-65cb-477d-9ef0-66f943ac06d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1409e26b-ccde-4d49-bb4f-5f07fa5544b6', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'How can you magnetize an ordinary iron nail or sewing needle using the ''Single-Touch'' method?', 'Unidirectional stroking aligns magnetic Weiss domains in the ferromagnetic nail along the stroke vector.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3b99e10-c673-4f4a-b3e5-ed0f571faf8c', 'Stroke the iron nail with one pole of a bar magnet repeatedly in ONE fixed direction along its length (30–40 times) without reversing direction', true, '1409e26b-ccde-4d49-bb4f-5f07fa5544b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89383248-029b-4976-b2c8-e6d498330397', 'Rub the magnet back and forth randomly', false, '1409e26b-ccde-4d49-bb4f-5f07fa5544b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5edfac9-b837-4710-b98e-2e9b63a93fcb', 'Heat the nail in a fire with the magnet', false, '1409e26b-ccde-4d49-bb4f-5f07fa5544b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('427eaec3-fb18-49c4-be19-4407fe047151', 'Drop the nail in cold water', false, '1409e26b-ccde-4d49-bb4f-5f07fa5544b6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('493e2ae8-a7aa-4d98-be57-33a0e0cbd419', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'Which of the following actions can cause a permanent magnet to LOSE its magnetism (Demagnetization)?', 'Thermal energy (above Curie temperature) and mechanical impact randomize aligned magnetic domain orientations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97fccb6e-7d1f-4056-8d56-5d006cc02bf2', 'Heating to high temperatures, hammering vigorously with a mallet, or dropping it repeatedly from a height onto hard floor', true, '493e2ae8-a7aa-4d98-be57-33a0e0cbd419');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0f66c34-9860-479c-bf1f-b8c7484f66ae', 'Washing it with clean water', false, '493e2ae8-a7aa-4d98-be57-33a0e0cbd419');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e493474c-ee2d-42de-8b3a-48ae9ac40cc1', 'Keeping it in a dark wooden box', false, '493e2ae8-a7aa-4d98-be57-33a0e0cbd419');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df1b0faf-5b65-474c-97b8-c0beefda12f0', 'Using it to pick up paper clips', false, '493e2ae8-a7aa-4d98-be57-33a0e0cbd419');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bdba7d10-4627-4a1f-a396-56e01dfc6d5e', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'How should Bar Magnets be safely stored in pairs to preserve their magnetic strength over years?', 'Soft iron magnetic keepers close magnetic flux loops, preventing self-demagnetizing free pole dissipation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6992d46a-05aa-4870-91de-d5df5cd13178', 'Stored in pairs with UNLIKE poles opposite each other, separated by a wooden spacer in the middle and connected by soft iron pieces (Keepers) across their ends', true, 'bdba7d10-4627-4a1f-a396-56e01dfc6d5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7aeaf682-e47c-4ccc-bc7c-0f85fb56a516', 'Stored with like poles touching', false, 'bdba7d10-4627-4a1f-a396-56e01dfc6d5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e11bcc68-20de-4158-b3bf-58392331711b', 'Stored loose in an iron bucket', false, 'bdba7d10-4627-4a1f-a396-56e01dfc6d5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ab0154d-021f-4120-a944-55d0a620a619', 'Stored submerged in salt water', false, 'bdba7d10-4627-4a1f-a396-56e01dfc6d5e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64c8900a-c244-4a6e-9cb7-7f0c0ab008bd', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'How should a Horseshoe Magnet be stored properly?', 'A soft iron keeper across both adjacent poles of a horseshoe magnet bridges the gap, completing the magnetic circuit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da3020cd-bba9-45e5-8b2c-bb9c1bedbd11', 'By placing a single piece of soft iron (magnetic keeper) across its two open poles', true, '64c8900a-c244-4a6e-9cb7-7f0c0ab008bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3c698a6-ede6-48c2-8d8a-9577c50493d1', 'By bending its arms together', false, '64c8900a-c244-4a6e-9cb7-7f0c0ab008bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb03c391-9b6e-470e-acf0-2fe6d41e9ce8', 'By heating it before storing', false, '64c8900a-c244-4a6e-9cb7-7f0c0ab008bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d826323c-65c9-4875-95b3-73370b4acae5', 'By wrapping it in aluminium foil', false, '64c8900a-c244-4a6e-9cb7-7f0c0ab008bd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e33a4fa-3044-4c9d-bb1b-0df64acb886c', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'Why does the Earth itself behave like a colossal gigantic magnet?', 'Geodynamo convection in the outer core generates Earth''s geomagnetic field; geographic North hosts geomagnetic South polarity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8f693da-b2ab-4909-a2c8-b3a5e3d34e62', 'Circulating molten iron-nickel liquid currents in Earth''s outer core generate a geomagnetic field, with its magnetic south pole located near the geographic North Pole', true, '4e33a4fa-3044-4c9d-bb1b-0df64acb886c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d13cf157-d26e-48c5-a798-55eebcc0e24f', 'Because Earth is made of giant plastic magnets', false, '4e33a4fa-3044-4c9d-bb1b-0df64acb886c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c975a09-cd61-467f-a54c-9206feb76ece', 'Because mountains are magnetic', false, '4e33a4fa-3044-4c9d-bb1b-0df64acb886c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c5db6c7-6a3b-4286-9fa5-c92d8fb50543', 'Because satellites magnetize Earth', false, '4e33a4fa-3044-4c9d-bb1b-0df64acb886c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('535f456d-cd4e-4a40-b490-3f1ed3d6ecd1', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'What ancient Chinese legend describes an emperor''s chariot equipped with a rotating wooden statue holding an outstretched arm that always pointed SOUTH?', 'Huang Di''s legendary chariot utilized a lodestone/geared mechanism whose statue arm consistently pointed South.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85f3e00b-0ee5-41b4-8c34-b93db5278d19', 'The South-Pointing Chariot of Emperor Huang Di', true, '535f456d-cd4e-4a40-b490-3f1ed3d6ecd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bb48c78-b8d5-43b0-bd56-4f1062cb77ec', 'The Dragon Compass', false, '535f456d-cd4e-4a40-b490-3f1ed3d6ecd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('447de931-2fdb-4147-83e8-47b121f31fe9', 'The Great Wall Chariot', false, '535f456d-cd4e-4a40-b490-3f1ed3d6ecd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('792cdb77-a3c4-4b63-ab48-b4109f425d01', 'The Silk Navigator', false, '535f456d-cd4e-4a40-b490-3f1ed3d6ecd1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b88db12b-ac14-4bdc-8241-5f359ad31087', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'Why should permanent strong magnets be kept away from cassette tapes, credit cards, computer hard drives, and mobile phones?', 'External stray magnetic flux can corrupt magnetically stored binary bits and saturate Hall sensors in electronics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43b2e9fd-fa9c-4cf2-9b03-3501a10cac92', 'The strong magnetic field can alter or erase the magnetic data encoded on magnetic strips, chips, and micro-circuitry', true, 'b88db12b-ac14-4bdc-8241-5f359ad31087');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ad30007-2f57-4096-8028-6d94d8673cf3', 'Because magnets will catch fire near phones', false, 'b88db12b-ac14-4bdc-8241-5f359ad31087');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6d399ac-75ae-4a82-8c7d-cf4d170935bf', 'Because phones will become too heavy', false, 'b88db12b-ac14-4bdc-8241-5f359ad31087');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a38ac111-bb6f-4075-b4ec-738942ba11a7', 'Because phone glass turns into mirror', false, 'b88db12b-ac14-4bdc-8241-5f359ad31087');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f318eab-8aaf-489c-8c73-d65d5b5d48a8', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'If an iron needle is magnetized by stroking with the North pole of a bar magnet starting from end A to end B, what magnetic pole is formed at end B?', 'The trailing end B of the stroke acquires opposite polarity (South pole) to the departing North pole.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55bb1c05-38fd-4131-bec4-53a10359ffc6', 'South Pole (opposite to the stroking pole)', true, '8f318eab-8aaf-489c-8c73-d65d5b5d48a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ad10185-97bd-425b-ab2d-0e2893376460', 'North Pole', false, '8f318eab-8aaf-489c-8c73-d65d5b5d48a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6efdb5ed-c1f9-41c4-b688-80a4d5f7f87c', 'No pole is formed', false, '8f318eab-8aaf-489c-8c73-d65d5b5d48a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82d963ee-f59c-4ae0-92d5-78815de4b3b5', 'End B becomes non-magnetic', false, '8f318eab-8aaf-489c-8c73-d65d5b5d48a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7687b805-8520-4276-a1ba-f5c315f636e6', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'Can magnetic force act through non-magnetic barriers (like a sheet of paper, cardboard, or a plastic ruler)?', 'Magnetic flux permeates non-ferromagnetic dielectric media with magnetic permeability μ ≈ μ₀.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('771dff44-f4ca-437c-9a34-7ebce32bdf96', 'Yes, magnetic field lines penetrate through non-magnetic materials like paper, glass, plastic, and water effortlessly', true, '7687b805-8520-4276-a1ba-f5c315f636e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9610a2a4-bc0b-4fdf-b759-2445d299ce9f', 'No, paper blocks all magnetic forces completely', false, '7687b805-8520-4276-a1ba-f5c315f636e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e814d2a7-0e9d-4411-9fb9-93280eddc9fe', 'Only if the paper is wet', false, '7687b805-8520-4276-a1ba-f5c315f636e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fa72eee-b2bc-4100-b940-98e22c348a15', 'Only in space', false, '7687b805-8520-4276-a1ba-f5c315f636e6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ba7895f-76da-4f60-bcd5-610405fee675', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'A tailor dropped a box of sewing needles into a box of sawdust. What is the fastest and easiest way to separate all the steel needles without searching by hand?', 'Magnetic separation extracts ferromagnetic steel needles while leaving non-magnetic sawdust behind.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66b05146-2676-47ee-bdf5-5b389d035f47', 'Pass a strong magnet through the sawdust; all steel needles will cling to the magnet instantly', true, '1ba7895f-76da-4f60-bcd5-610405fee675');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cafee1ab-4982-48ab-ac58-0378c7160d2a', 'Burn the sawdust', false, '1ba7895f-76da-4f60-bcd5-610405fee675');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f732a3b-7815-4fcb-ad58-4519b52c847e', 'Dissolve in water', false, '1ba7895f-76da-4f60-bcd5-610405fee675');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('094da22e-4d96-4cb2-a711-a0da2fa833f3', 'Use a microscope', false, '1ba7895f-76da-4f60-bcd5-610405fee675');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('927c41bf-f401-4155-a852-12d070809bf8', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'Which of the following modern technological devices utilizes powerful magnets to operate?', 'Electromagnetic induction and magnetic levitation power electric motors, Maglev transit, MRI tomography, and acoustic transducers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1599c8a-631d-4db1-add9-7ed728efee24', 'Electric motors, Dynamos, MRI medical scanners, Maglev trains, and Audio speakers', true, '927c41bf-f401-4155-a852-12d070809bf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63da72b7-9f80-4a1e-aa26-23a4c2f06def', 'Wooden chairs', false, '927c41bf-f401-4155-a852-12d070809bf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f11096a2-5473-4075-833f-6bb50fed5fec', 'Cotton shirts', false, '927c41bf-f401-4155-a852-12d070809bf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5a02396-21f3-4cc2-8eb9-ffd58d5a72ba', 'Glass bottles', false, '927c41bf-f401-4155-a852-12d070809bf8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9116f386-62dc-424f-a1e8-40bf18e301ec', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'How does a Maglev (Magnetic Levitation) high-speed bullet train run without touching the track rails?', 'Electrodynamic/electromagnetic levitation utilizes magnetic repulsion to float carriages ~10–15 mm above guideways.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75061a4e-a7f5-46b3-ac52-dd0a6ceecaa3', 'Superconducting electromagnets on the train and track repel each other with strong like magnetic poles, levitating the train in air and eliminating mechanical friction', true, '9116f386-62dc-424f-a1e8-40bf18e301ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('308809eb-cda6-483a-84c1-98b9f58a799b', 'It flies using jet wings', false, '9116f386-62dc-424f-a1e8-40bf18e301ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f604d251-61d8-4a33-9b98-bee064664689', 'It rolls on millions of tiny ball bearings', false, '9116f386-62dc-424f-a1e8-40bf18e301ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67d273b2-70ae-40db-bc92-51bd3c9a87a2', 'It floats on a layer of hot steam', false, '9116f386-62dc-424f-a1e8-40bf18e301ec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('44a8f6f1-1e54-4637-8dcb-15dbc03e3eec', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'What is an ''Electromagnet''?', 'An electromagnet generates a controllable magnetic field via current flow through an insulated solenoid coil.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cedb02b-a80a-4529-b062-c94d054229f6', 'A temporary magnet formed by winding an insulated copper wire around a soft iron core and passing electric current through it', true, '44a8f6f1-1e54-4637-8dcb-15dbc03e3eec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f776f9de-9a1a-4cb6-afe3-83081546460c', 'A rock found in the ocean', false, '44a8f6f1-1e54-4637-8dcb-15dbc03e3eec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03c8897c-8c8e-4ee2-9ae5-6dfcb94f12c6', 'A permanent bar magnet that never loses magnetism', false, '44a8f6f1-1e54-4637-8dcb-15dbc03e3eec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dcaecd7-cc60-47fd-918a-1846226845b4', 'A magnet made of pure plastic', false, '44a8f6f1-1e54-4637-8dcb-15dbc03e3eec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45238bac-588a-49d2-8806-6e3d92fff4df', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'Why do iron filings sprinkle on a sheet of paper over a bar magnet arrange themselves in distinct curved lines?', 'Induced magnetic dipolar moments torque iron filings tangent to lines of magnetic flux density.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05e50163-97a1-4a07-8f90-2cfef4e2889b', 'Each tiny iron filing becomes a miniature induced magnet and aligns along the invisible curved Magnetic Field Lines running from North to South pole', true, '45238bac-588a-49d2-8806-6e3d92fff4df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a5c8866-1642-4597-9a2d-95cba01e9609', 'Because the paper is curved', false, '45238bac-588a-49d2-8806-6e3d92fff4df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0a75254-253b-47e2-9237-81ffc9633725', 'Because iron filings melt', false, '45238bac-588a-49d2-8806-6e3d92fff4df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63d0c9ee-59cc-4c8b-9d6f-beda1ac0a6f3', 'Because of gravity pulling them sideways', false, '45238bac-588a-49d2-8806-6e3d92fff4df');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b3f1d886-fc7d-4fd7-bf8c-dda8c3a9f56e', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Medium', 'What happens if a freely suspended bar magnet is brought near another strong magnet?', 'Torque τ = m × B causes the pivoted dipole to rotate until its magnetic moment aligns with the external field.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00edfecf-5703-438e-8e4c-25a5a176a975', 'The suspended magnet will rotate and re-align: its North pole will be attracted to the other''s South pole and repelled by its North pole', true, 'b3f1d886-fc7d-4fd7-bf8c-dda8c3a9f56e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd475b0a-a15a-4b09-94a0-41342d02e2e9', 'It will stop moving forever', false, 'b3f1d886-fc7d-4fd7-bf8c-dda8c3a9f56e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9501e305-da09-43c2-bd7f-1bc339d9e8df', 'It will turn into copper', false, 'b3f1d886-fc7d-4fd7-bf8c-dda8c3a9f56e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e524d1d1-cbf7-437f-82c2-fe1ddecab6f6', 'It will ignore the second magnet', false, 'b3f1d886-fc7d-4fd7-bf8c-dda8c3a9f56e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('967f3cf7-78e8-416f-b3e0-9f7f003d975a', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b152a2bf-0b10-41c8-b4e4-b606a13d93c1', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '967f3cf7-78e8-416f-b3e0-9f7f003d975a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33cf3b51-7ddd-4466-9739-50797b1ebf91', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '967f3cf7-78e8-416f-b3e0-9f7f003d975a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5985b0f0-919f-4991-a247-4f0a37fa22f0', '(A) is true, but (R) is false.', false, '967f3cf7-78e8-416f-b3e0-9f7f003d975a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1b821bc-239a-4bba-bbe5-568b3f8b25fe', '(A) is false, but (R) is true.', false, '967f3cf7-78e8-416f-b3e0-9f7f003d975a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ffcbe15-bc0b-4824-ace6-9c8d079d2244', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'Spot the IMPOSTER in the following group of materials categorized as Non-magnetic:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82d4f05c-a59c-46fa-b6a0-8ad56083cdb5', 'Pure Aluminium', false, '1ffcbe15-bc0b-4824-ace6-9c8d079d2244');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a04dc72c-6545-4fe2-966e-688be27605b0', 'Copper coin', false, '1ffcbe15-bc0b-4824-ace6-9c8d079d2244');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('787f9078-4f46-4d55-a00d-3b9261839191', 'Brass screw', false, '1ffcbe15-bc0b-4824-ace6-9c8d079d2244');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('daa9ae1a-5eb5-4a04-a1ef-466635817ec9', 'Cobalt plate', true, '1ffcbe15-bc0b-4824-ace6-9c8d079d2244');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1974cb17-a34f-485d-b7fa-df32935c3c8b', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'A student suspends an unmarked metallic bar X-Y freely. End X points towards geographic North. When the North pole of a known bar magnet is brought near end X, end X is strongly REPELLED. What can you conclude definitively about end X and end Y?', 'Repulsion definitively confirms that bar X-Y is a magnet and end X is a North pole.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('994b0a3c-5a79-4159-91e8-7914ba1ff23f', 'The bar is a magnet; end X is a North Pole and end Y is a South Pole', true, '1974cb17-a34f-485d-b7fa-df32935c3c8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33de283e-abce-4ca4-b494-5f8ebcf6ca01', 'The bar is ordinary non-magnetic aluminium', false, '1974cb17-a34f-485d-b7fa-df32935c3c8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ab27a42-fb9d-4996-9c2d-2afc1434d361', 'End X is a South Pole', false, '1974cb17-a34f-485d-b7fa-df32935c3c8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('534c2826-6cd3-4895-9f4a-557b165437c8', 'The bar is unmagnetized soft iron', false, '1974cb17-a34f-485d-b7fa-df32935c3c8b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5680230-ee0b-4a68-af8f-9becf33e90d7', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'Match Column I (Magnetic Phenomena) with Column II (Scientific Principles):
(a) Freely suspended magnet -> (i) Opposite poles experience mutual attraction
(b) Like poles (N-N / S-S)     -> (ii) Like poles experience mutual repulsion
(c) Unlike poles (N-S)       -> (iii) Aligns along Earth''s geomagnetic N-S meridian
(d) Soft iron keeper         -> (iv) Closes magnetic flux loop preventing demagnetization', 'Suspended magnet = Earth N-S; Like poles = Repulsion; Unlike poles = Attraction; Keepers = Prevents demagnetization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd031f0a-738c-45c9-8980-f3c9e4652ee7', 'a-(iii), b-(ii), c-(i), d-(iv)', true, 'c5680230-ee0b-4a68-af8f-9becf33e90d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('081c79cb-21d9-44f9-ae50-4fa4ec46c119', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'c5680230-ee0b-4a68-af8f-9becf33e90d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c5d5609-e344-4d62-ad81-481f64f2edc3', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'c5680230-ee0b-4a68-af8f-9becf33e90d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78401550-8626-452d-a42d-0df490da8ec0', 'a-(ii), b-(iv), c-(i), d-(iii)', false, 'c5680230-ee0b-4a68-af8f-9becf33e90d7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b608482d-66b3-41dc-9463-16e3ef89b7c4', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'Read the statements regarding magnetic properties:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d12c9697-4666-4995-b79e-356d80601227', 'Statements 1 and 2 only', true, 'b608482d-66b3-41dc-9463-16e3ef89b7c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('481998ad-6e12-422e-a816-c149e2848206', 'Statements 2 and 3 only', false, 'b608482d-66b3-41dc-9463-16e3ef89b7c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f714ff5b-9b04-41e2-b839-faece8a1ca07', 'Statements 1 and 3 only', false, 'b608482d-66b3-41dc-9463-16e3ef89b7c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85ecef5b-b8b8-4eec-8763-26775a7305cd', 'All Statements 1, 2, and 3', false, 'b608482d-66b3-41dc-9463-16e3ef89b7c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('017b4c09-7bd9-4b42-a476-967864637d16', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'Why does the geographic North Pole of Earth attract the NORTH-seeking pole of a compass needle?', 'Earth''s internal magnetic dipole is inverted relative to geography: the geomagnetic South pole resides near Arctic geographic North.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9b49009-32c6-45d8-b5f4-0ad552d4c326', 'Because Earth''s geomagnetic SOUTH magnetic pole is physically located near the geographic North Pole, exerting attractive force on the needle''s North pole', true, '017b4c09-7bd9-4b42-a476-967864637d16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47d5f9aa-cd8a-46e0-926d-84fa3b5946ac', 'Because like poles attract in space', false, '017b4c09-7bd9-4b42-a476-967864637d16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b8515b0-e743-46f9-96fb-03e28a6ffebd', 'Because geographic north has positive electricity', false, '017b4c09-7bd9-4b42-a476-967864637d16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c67a92b-ac8c-4a09-8aa9-298606c9519e', 'Because the compass is upside down', false, '017b4c09-7bd9-4b42-a476-967864637d16');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78756837-33ba-40e3-b561-106227ff6289', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'A heavy-duty industrial magnetic crane in a junkyard lifts 5 tonnes of scrap iron cars and drops them precisely into a furnace. How does the crane operator release the scrap iron instantly?', 'Electromagnets provide instantaneous on/off control: cutting the solenoid circuit demagnetizes the soft iron core, dropping the load.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba519438-25f3-4f20-80f2-44919417484d', 'The crane uses a powerful Electromagnet; switching OFF the electric current stops the magnetic field instantly, releasing the scrap iron', true, '78756837-33ba-40e3-b561-106227ff6289');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('729319d0-a4e1-441e-9561-f84ba61b13b9', 'By hitting the magnet with a hammer', false, '78756837-33ba-40e3-b561-106227ff6289');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f1930d2-f658-4401-88a7-0d04e2ad9629', 'By spraying cold water on the cars', false, '78756837-33ba-40e3-b561-106227ff6289');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20314f69-4250-41b6-a4ac-4c9e7e407ce8', 'By turning the crane upside down', false, '78756837-33ba-40e3-b561-106227ff6289');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3243ba12-ba8f-493a-aadf-8d98f7d1a9d0', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'Consider four rings placed over a vertical wooden pencil:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08bbeedd-2b3e-4e40-8450-f01a60650114', 'Between Ring 1 and Ring 2 (both facing surfaces have South Pole ''S-S'', causing strong mutual repulsion and levitation)', true, '3243ba12-ba8f-493a-aadf-8d98f7d1a9d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c33147d3-df21-4631-8c02-88f4d7626bf8', 'Between Ring 2 and Ring 3', false, '3243ba12-ba8f-493a-aadf-8d98f7d1a9d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f5f01e8-7e51-4929-b882-23b960c4479a', 'Between Ring 3 and Ring 4', false, '3243ba12-ba8f-493a-aadf-8d98f7d1a9d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18a11d82-5407-4212-983c-b6fc97a4ae94', 'All rings stick tightly without gaps', false, '3243ba12-ba8f-493a-aadf-8d98f7d1a9d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a878c0f-5430-4a0f-9496-de2775a2a48d', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'Why is Soft Iron preferred over Hard Steel for making magnetic keepers and cores of electromagnets?', 'Soft iron possesses low coercive force and narrow hysteresis loop, ideal for temporary magnetic coupling.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8d2dde4-479d-4b75-9acf-603f157afea4', 'Soft iron has high magnetic permeability and low retentivity, magnetizing and demagnetizing instantly without retaining permanent residual magnetism', true, '8a878c0f-5430-4a0f-9496-de2775a2a48d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b1ba9b3-fad3-4ee4-8f0c-c52aa664bb86', 'Because soft iron is cheaper than wood', false, '8a878c0f-5430-4a0f-9496-de2775a2a48d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac3113d1-ef60-4e85-bf56-dac15a591a22', 'Because soft iron is transparent', false, '8a878c0f-5430-4a0f-9496-de2775a2a48d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72da902d-55cc-41e0-8e80-8ac14f0f956d', 'Because steel cannot be magnetized', false, '8a878c0f-5430-4a0f-9496-de2775a2a48d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ef55b729-ad89-435f-9887-866d1e122202', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'What is an alloy made of Aluminium, Nickel, and Cobalt widely used to manufacture ultra-strong permanent industrial magnets called?', 'Alnico ferromagnetic alloys combine high coercivity and temperature stability for permanent magnets.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('755f09fe-cabe-49c3-8a4b-c137ae718b9c', 'Alnico (Al-Ni-Co)', true, 'ef55b729-ad89-435f-9887-866d1e122202');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6cc5e6b-9b43-4471-b37c-6a76005e2567', 'Brass', false, 'ef55b729-ad89-435f-9887-866d1e122202');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0bb0133-b122-4f90-af93-a793de5d2cc7', 'Bronze', false, 'ef55b729-ad89-435f-9887-866d1e122202');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24e81d3d-06c8-46aa-9647-f851ee4a89bc', 'Solder', false, 'ef55b729-ad89-435f-9887-866d1e122202');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7613720b-369b-48cd-8629-5e3d70ae7d19', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'A compass is placed near an unknown hidden box. The compass needle deflects wildly away when brought near one corner of the box and deflects in reverse at the other corner. What is inside the box?', 'Bipolar deflection matching inverse field directions proves an active magnetic dipole source inside the enclosure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54354326-d73f-4cfa-929d-20616af95ddc', 'A permanent magnet (the deflection reversals reflect the presence of North and South dipolar poles)', true, '7613720b-369b-48cd-8629-5e3d70ae7d19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26511604-24cb-4c6a-ab48-3e89430ae735', 'A piece of gold jewelry', false, '7613720b-369b-48cd-8629-5e3d70ae7d19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01e57caa-f5ef-4504-a64b-b730ea47cfe2', 'A bottle of pure water', false, '7613720b-369b-48cd-8629-5e3d70ae7d19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6b6e158-e41b-4f23-aea7-67683be9c0c8', 'An empty wooden block', false, '7613720b-369b-48cd-8629-5e3d70ae7d19');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('431e5def-daed-4aa5-9581-2688ad41f717', 'Class 6', 'Science', 'Chapter 10: Fun with Magnets', 'Hard', 'What protective geomagnetic structure shields Earth''s biosphere from deadly ionizing solar wind and cosmic radiation?', 'The geomagnetic magnetosphere deflects charged interplanetary solar wind plasma around Earth, shielding life.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0e161b8-943c-4112-b99b-00be5a6a6a94', 'Earth''s Magnetosphere (Van Allen radiation belts)', true, '431e5def-daed-4aa5-9581-2688ad41f717');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b4950c4-c157-4c09-b8fe-43afb03ba80d', 'The Ozone layer only', false, '431e5def-daed-4aa5-9581-2688ad41f717');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('256564d7-9381-44ac-8990-f9caf6bbdb6a', 'The Troposphere', false, '431e5def-daed-4aa5-9581-2688ad41f717');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77150fac-1949-4ece-811a-ccb78571e15c', 'Ocean tides', false, '431e5def-daed-4aa5-9581-2688ad41f717');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45d6929d-b954-433e-b8c4-1b503b0693d2', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Easy', 'The total distance around the closed boundary of a 2-dimensional plane figure is called its:', 'Perimeter is the linear continuous boundary measure of a closed planar shape (sum of all outer sides).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0319a422-8ca4-4964-9ca5-80dbbb57b782', 'Perimeter', true, '45d6929d-b954-433e-b8c4-1b503b0693d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa3e7543-eec2-48ea-9791-afc1a64056b0', 'Area', false, '45d6929d-b954-433e-b8c4-1b503b0693d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed65031a-cebf-4db2-8a65-a2fd300b26b3', 'Volume', false, '45d6929d-b954-433e-b8c4-1b503b0693d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b100abaa-d2fa-4c3b-a53e-6e56a5f8225b', 'Diagonal', false, '45d6929d-b954-433e-b8c4-1b503b0693d2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91ed5696-bfe8-430f-b26e-ebabd3edb8f6', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Easy', 'What is the standard formula to calculate the Perimeter of a Rectangle with length ''l'' and breadth ''b''?', 'Perimeter of Rectangle = 2(l + b).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21f5f8a0-5a87-4136-a340-fead247c3c45', 'Perimeter = 2 × (length + breadth)', true, '91ed5696-bfe8-430f-b26e-ebabd3edb8f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4719249-d70a-4c36-a318-022cdb68138b', 'Perimeter = length × breadth', false, '91ed5696-bfe8-430f-b26e-ebabd3edb8f6');
