INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac1d8b82-70e6-4cd6-812e-117562e7329a', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'A piece of wire of length 36 cm is bent to form a Square. What will be the length of each side of the square?', 'Perimeter = 4 × s = 36 cm ⇒ s = 36 / 4 = 9 cm.', NOW()) ON CONFLICT DO NOTHING;
