INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('713d7935-3427-498e-b78a-540bb25ea08c', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'A farmer wants to fence his rectangular field of length 240 m and breadth 160 m with 4 rows of barbed wire. What is the total length of wire required?', 'One round = 2(240 + 160) = 800 m. For 4 rounds = 800 × 4 = 3,200 m.', NOW()) ON CONFLICT DO NOTHING;
