INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3f8e042-d2ba-4867-b2d8-a88055dbace3', '15 sq m', false, '8d394cc9-071c-4d8f-be12-f65ed29fa8fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e20ebe14-7fe1-4731-9e58-d47d1522e351', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'How many square tiles of side 10 cm will be needed to pave a rectangular bathroom floor of size 2 m by 1.5 m?', 'Floor = 200 × 150 = 30,000 cm². Tile = 100 cm². Number of tiles = 30,000 ÷ 100 = 300 tiles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97ab49e7-e183-4ce2-86eb-5e8bcc9d86a9', '300 tiles (Floor = 200 cm × 150 cm = 30,000 cm² ; Tile = 10 × 10 = 100 cm² ; Tiles = 30,000 / 100 = 300)', true, 'e20ebe14-7fe1-4731-9e58-d47d1522e351');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('185a9cf1-33a5-432b-bad6-03ccd7886cad', '30 tiles', false, 'e20ebe14-7fe1-4731-9e58-d47d1522e351');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6bdbd3e-9656-4f51-a95e-d585af64818e', '150 tiles', false, 'e20ebe14-7fe1-4731-9e58-d47d1522e351');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('317dbfda-b526-4eb3-bea2-d144cc25bdb7', '3,000 tiles', false, 'e20ebe14-7fe1-4731-9e58-d47d1522e351');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca5f6540-8b35-4a79-842d-e820d9c53096', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'Find the perimeter of a regular Octagon (8 equal sides) having side length 4.5 cm:', 'Perimeter = 8 × 4.5 = 36 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42f23620-8e13-41b5-8107-d8816927ae7c', '36 cm (8 × 4.5 = 36 cm)', true, 'ca5f6540-8b35-4a79-842d-e820d9c53096');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17bb33f1-44e5-413d-9937-788643ac9140', '32 cm', false, 'ca5f6540-8b35-4a79-842d-e820d9c53096');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b8bfd38-7430-4980-9fc7-93c6ab50a160', '40 cm', false, 'ca5f6540-8b35-4a79-842d-e820d9c53096');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3bf1914-77de-4403-ae7d-094ba3e14500', '28 cm', false, 'ca5f6540-8b35-4a79-842d-e820d9c53096');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa6d935c-743b-4c6f-b3b7-ca100fda16f4', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'Two sides of a triangle are 12 cm and 14 cm. The perimeter of the triangle is 36 cm. What is the length of the third side?', 'Side 3 = Perimeter - (Side 1 + Side 2) = 36 - 26 = 10 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af254239-6d22-44c4-9888-7475f820d80c', '10 cm (Third side = 36 - (12 + 14) = 36 - 26 = 10 cm)', true, 'fa6d935c-743b-4c6f-b3b7-ca100fda16f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('146231d5-7842-47d0-ac83-ec8ca393341e', '12 cm', false, 'fa6d935c-743b-4c6f-b3b7-ca100fda16f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('173e909f-9792-4f88-aad3-9d1a0e838f5d', '8 cm', false, 'fa6d935c-743b-4c6f-b3b7-ca100fda16f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3fed65f-4a8a-49a3-9c25-201bc714304a', '11 cm', false, 'fa6d935c-743b-4c6f-b3b7-ca100fda16f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e01facb-df91-4f21-a44e-1ed456d8f55a', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'Find the cost of leveling a rectangular playground of dimensions 70 m by 50 m at the rate of ₹5 per square metre:', 'Area = 70 × 50 = 3,500 m². Cost = 3,500 × 5 = ₹17,500.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b93a1ac5-f277-43e8-90c8-2628aad741b6', '₹17,500 (Area = 70 × 50 = 3,500 m² ; Cost = 3,500 × 5 = ₹17,500)', true, '6e01facb-df91-4f21-a44e-1ed456d8f55a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ae715a6-c93f-460b-a1ba-3a201c8bb1b5', '₹12,000', false, '6e01facb-df91-4f21-a44e-1ed456d8f55a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9107a799-1118-44c4-8958-9f97b25a0240', '₹35,000', false, '6e01facb-df91-4f21-a44e-1ed456d8f55a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2352744-c6be-4889-a0c3-2e9825ced017', '₹15,000', false, '6e01facb-df91-4f21-a44e-1ed456d8f55a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('040bbe7e-793c-41a2-9b75-93f502ee0387', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'Sweety runs around a square park of side 75 m. Bulbul runs around a rectangular park of length 60 m and breadth 45 m. Who covers LESS distance and by how much?', 'Sweety perimeter = 300 m; Bulbul perimeter = 210 m. Bulbul covers 90 m less.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('543157f7-5696-4109-a43d-8c2510afe994', 'Bulbul covers less distance by 90 metres (Sweety = 4 × 75 = 300 m ; Bulbul = 2 × (60 + 45) = 210 m ; Difference = 300 - 210 = 90 m)', true, '040bbe7e-793c-41a2-9b75-93f502ee0387');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99230832-2df5-4643-bc17-51956b05e5c6', 'Sweety covers less distance by 90 m', false, '040bbe7e-793c-41a2-9b75-93f502ee0387');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('234e37e1-f8d2-4d15-ae82-2e934ab9a1f4', 'Both cover exactly the same distance', false, '040bbe7e-793c-41a2-9b75-93f502ee0387');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68d6b6e5-e1d3-4549-9cee-f63d8e7fab4a', 'Bulbul covers less distance by 50 m', false, '040bbe7e-793c-41a2-9b75-93f502ee0387');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37f3bbb7-0bcf-41ff-bfc7-876215d078fe', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'How is the approximate area of an irregular closed shape estimated using standard 1 cm × 1 cm squared grid paper?', 'Standard grid approximation: full squares = 1, >half squares = 1, =half squares = 0.5, <half squares = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d131eca4-c8ac-42a7-96d0-f37f2c9c7a93', 'Count 1 sq unit for fully covered squares + ignore squares less than half covered + count 1 sq unit for squares more than half covered + count ½ sq unit for exactly half covered squares', true, '37f3bbb7-0bcf-41ff-bfc7-876215d078fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('070baa05-a88e-486a-af30-a415d7dbd6b1', 'Only count full squares and throw away everything else', false, '37f3bbb7-0bcf-41ff-bfc7-876215d078fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49d14657-0768-4d39-880a-852b9efd3518', 'Multiply width by height directly', false, '37f3bbb7-0bcf-41ff-bfc7-876215d078fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ea136b5-31d2-4c65-ae54-16f7764e8c64', 'Weigh the paper on a balance', false, '37f3bbb7-0bcf-41ff-bfc7-876215d078fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fb7d269b-07c9-44a6-bd79-976270454126', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'What happens to the AREA of a square if its side length is DOUBLED (multiplied by 2)?', 'A_new = (2s)² = 4s² (area quadruples / 4 times).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8d13f26-b0ac-4632-aa38-2eb7a82767a4', 'The area becomes 4 TIMES the original area ((2s)² = 4s²)', true, 'fb7d269b-07c9-44a6-bd79-976270454126');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c0ce8c2-8e29-4135-9506-0224dc906caa', 'The area doubles (2 times)', false, 'fb7d269b-07c9-44a6-bd79-976270454126');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e8cef97-0f86-4058-b655-44f5d8d3407a', 'The area triples (3 times)', false, 'fb7d269b-07c9-44a6-bd79-976270454126');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c01f3025-0a34-4461-828b-4c60c0322c4f', 'The area remains unchanged', false, 'fb7d269b-07c9-44a6-bd79-976270454126');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae907088-a68d-4730-86c4-34ecdbedafb0', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'What happens to the PERIMETER of a square if its side length is DOUBLED?', 'P_new = 4(2s) = 2(4s) = 2 × P_old (doubles).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b83a7e7-3476-42ab-a037-e4105c600d44', 'The perimeter is DOUBLED (2 times: 4 × (2s) = 2 × (4s))', true, 'ae907088-a68d-4730-86c4-34ecdbedafb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c140d337-a8c4-42b6-be49-d0fdb21fc6c7', 'The perimeter becomes 4 times', false, 'ae907088-a68d-4730-86c4-34ecdbedafb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2695e381-5fe7-4e94-ab88-a0d49992d0b6', 'The perimeter remains the same', false, 'ae907088-a68d-4730-86c4-34ecdbedafb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c9daca3-5d0a-4a71-ab97-275e02a46015', 'The perimeter halves', false, 'ae907088-a68d-4730-86c4-34ecdbedafb0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe2d2d1d-6d59-4f62-b8d8-e870d1044474', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Medium', 'Five square flower beds each of side 1 m are dug on a piece of rectangular land 5 m long and 4 m wide. What is the remaining area of the land?', 'Total area = 20 m²; 5 beds = 5 m²; Remaining = 20 - 5 = 15 m².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d66ac284-52cb-4059-b369-8440e4e6a32f', '15 sq m (Total Land = 5 × 4 = 20 m² ; Beds = 5 × (1 × 1) = 5 m² ; Remaining = 20 - 5 = 15 m²)', true, 'fe2d2d1d-6d59-4f62-b8d8-e870d1044474');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecc7b4c4-0cbd-4c76-a299-211725ac10a8', '10 sq m', false, 'fe2d2d1d-6d59-4f62-b8d8-e870d1044474');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cde068e6-22e1-4cf6-ac58-f124284a3a0a', '19 sq m', false, 'fe2d2d1d-6d59-4f62-b8d8-e870d1044474');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bf456ef-6b2f-42e1-8f4a-5257ffc86356', '16 sq m', false, 'fe2d2d1d-6d59-4f62-b8d8-e870d1044474');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e30c645c-a39e-4ce8-87fb-e116fa95afd3', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61d85807-ead6-49f5-9383-1edb24a318d1', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'e30c645c-a39e-4ce8-87fb-e116fa95afd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('199292de-b054-44f2-aa18-94683678c4c1', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'e30c645c-a39e-4ce8-87fb-e116fa95afd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('449830c5-d3a9-4778-9a79-aea5871e74bc', '(A) is true, but (R) is false.', false, 'e30c645c-a39e-4ce8-87fb-e116fa95afd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cd44086-b1d9-4c69-ad42-39f6251feaa3', '(A) is false, but (R) is true.', false, 'e30c645c-a39e-4ce8-87fb-e116fa95afd3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a266855e-731d-4250-9dd7-c2e9998c49b9', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'Spot the IMPOSTER in the following polygon perimeters where each side length s = 6 cm:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7de9aadc-a518-4691-81c4-baba0658d97c', 'Square (P = 24 cm)', false, 'a266855e-731d-4250-9dd7-c2e9998c49b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3fce254-7ca4-45bb-b40c-f113634347dc', 'Equilateral Triangle (P = 18 cm)', false, 'a266855e-731d-4250-9dd7-c2e9998c49b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c504a69f-bb5a-496c-83e4-9ea9b2e4fa92', 'Regular Hexagon (P = 36 cm)', false, 'a266855e-731d-4250-9dd7-c2e9998c49b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2827a788-e22f-454a-8824-e9d82eb6aa0e', 'Regular Pentagon (P = 35 cm)', true, 'a266855e-731d-4250-9dd7-c2e9998c49b9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e72d6942-7b25-475b-bf01-beaa42fa815f', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'A rectangular hall of length 30 m and breadth 20 m is surrounded on all outer sides by a 2.5 m wide verandah. What is the total AREA of the verandah path alone?', 'Outer dims = (30 + 5) × (20 + 5) = 35 × 25 = 875 m²; Inner = 600 m²; Path = 875 - 600 = 275 m².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa5a5e9c-15a9-4d61-b9db-567bbc5e8832', '275 sq m (Outer length = 35 m, Outer breadth = 25 m ; Outer Area = 35 × 25 = 875 m² ; Inner Area = 30 × 20 = 600 m² ; Path Area = 875 - 600 = 275 m²)', true, 'e72d6942-7b25-475b-bf01-beaa42fa815f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da32d5b1-95cb-439a-ab99-a6b12a35926f', '250 sq m', false, 'e72d6942-7b25-475b-bf01-beaa42fa815f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1eb5c572-f9cb-4499-931d-4ee1e28cbcbf', '300 sq m', false, 'e72d6942-7b25-475b-bf01-beaa42fa815f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f398d75-e751-4a4d-916e-f207cba1919a', '150 sq m', false, 'e72d6942-7b25-475b-bf01-beaa42fa815f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18fd7cc8-e59a-473b-8f1a-1be35a082ccb', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'Match Column I (Geometric Figures) with Column II (Perimeter / Area Formulas):
(a) Square Area              -> (i) 2(l + b)
(b) Rectangle Perimeter      -> (ii) s²
(c) Equilateral Triangle P   -> (iii) l × b
(d) Rectangle Area           -> (iv) 3s', 'Square Area = s²; Rectangle P = 2(l+b); Triangle P = 3s; Rectangle Area = l×b.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c178f9f-8b72-4d55-bf9d-257562790ca0', 'a-(ii), b-(i), c-(iv), d-(iii)', true, '18fd7cc8-e59a-473b-8f1a-1be35a082ccb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('347d49e7-6eea-43d6-afc9-92558e867396', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '18fd7cc8-e59a-473b-8f1a-1be35a082ccb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc958a1e-b753-43a8-a6c8-ac507d255e79', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '18fd7cc8-e59a-473b-8f1a-1be35a082ccb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fb63926-94fe-4569-9357-bc6a2437f0b1', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '18fd7cc8-e59a-473b-8f1a-1be35a082ccb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9451ffef-e3cf-4b39-9a32-796e4770b468', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'Read the statements regarding geometric measures:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('173ae162-1ff2-4c2f-810a-768dc7d07beb', 'Statements 1 and 2 only', true, '9451ffef-e3cf-4b39-9a32-796e4770b468');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9cb2667-6677-431c-9fad-f9702aac5b5c', 'Statements 2 and 3 only', false, '9451ffef-e3cf-4b39-9a32-796e4770b468');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28a352ea-dfb9-44cd-85d3-f157c97a080e', 'Statements 1 and 3 only', false, '9451ffef-e3cf-4b39-9a32-796e4770b468');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8f477ec-d502-45d3-95cb-cb32725ac45f', 'All Statements 1, 2, and 3', false, '9451ffef-e3cf-4b39-9a32-796e4770b468');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8847013-ee60-4544-976d-9ee9f19a6247', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'A wire in the shape of a Rectangle of dimensions 18 cm by 10 cm is cut, straightened, and rebent into a Square. What will be the area of this new Square?', 'Perimeter = 2(18 + 10) = 56 cm. Square side = 56/4 = 14 cm. Square area = 14² = 196 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('158068fb-7ea7-48cf-931e-152e6ad1729e', '196 sq cm (Perimeter = 2(18 + 10) = 56 cm ; Square side = 56/4 = 14 cm ; Area = 14 × 14 = 196 cm²)', true, 'c8847013-ee60-4544-976d-9ee9f19a6247');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73a95614-9e3c-4403-b035-95fe6bf7eb1c', '180 sq cm', false, 'c8847013-ee60-4544-976d-9ee9f19a6247');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47eb2486-bffc-4f4b-927f-59458383de1b', '144 sq cm', false, 'c8847013-ee60-4544-976d-9ee9f19a6247');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e26fad9-2956-4c48-8930-efc633696a85', '256 sq cm', false, 'c8847013-ee60-4544-976d-9ee9f19a6247');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4ddc8cf8-0423-403b-ad0e-8ae88379376d', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'Find the total perimeter of an L-shaped polygon with side lengths: bottom = 10 cm, left vertical = 8 cm, top horizontal = 4 cm, inner vertical = 5 cm, inner horizontal = 6 cm, right vertical = 3 cm:', 'Summing all 6 contiguous boundary edges: 10 + 8 + 4 + 5 + 6 + 3 = 36 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b225616f-8a9a-4e3c-a026-47debfed9fcc', '36 cm (10 + 8 + 4 + 5 + 6 + 3 = 36 cm)', true, '4ddc8cf8-0423-403b-ad0e-8ae88379376d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc369ad6-8ba3-46c8-b2d7-eb50bb03bffc', '32 cm', false, '4ddc8cf8-0423-403b-ad0e-8ae88379376d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21e464b2-6528-468d-9095-3b961b434fbb', '40 cm', false, '4ddc8cf8-0423-403b-ad0e-8ae88379376d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a65e5dee-d2b7-4c52-92a2-3d4d2644e24c', '28 cm', false, '4ddc8cf8-0423-403b-ad0e-8ae88379376d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06f057a1-81ac-4956-b66d-4bca599fb434', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'A rectangular lawn of length 60 m and breadth 40 m has two crossroads each 2 m wide running at right angles through its center parallel to its sides. What is the area of the crossroads?', 'Area of crossroads = (60 × 2) + (40 × 2) - (2 × 2) = 120 + 80 - 4 = 196 m².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf913cea-9e9e-4f49-b281-44c02ace531d', '196 sq m (Road 1 = 60 × 2 = 120 m² ; Road 2 = 40 × 2 = 80 m² ; Center overlap = 2 × 2 = 4 m² ; Net Area = 120 + 80 - 4 = 196 m²)', true, '06f057a1-81ac-4956-b66d-4bca599fb434');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d3337a7-6a82-4ab8-b681-af724fab4485', '200 sq m', false, '06f057a1-81ac-4956-b66d-4bca599fb434');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('531fe84a-fbca-4991-a019-0807a510734d', '192 sq m', false, '06f057a1-81ac-4956-b66d-4bca599fb434');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfbd1cdc-d60e-4876-a3ab-0a518ce8bc60', '204 sq m', false, '06f057a1-81ac-4956-b66d-4bca599fb434');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ebc463dc-5233-4278-910b-2275e613f83b', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'If 1 hectare = 10,000 square metres, how many hectares is a rectangular agricultural farm of length 500 m and breadth 200 m?', 'Area = 500 × 200 = 100,000 m² ÷ 10,000 m²/ha = 10 hectares.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a0c7c39-00dd-4fa5-b601-cc7d77956e98', '10 hectares (Area = 500 × 200 = 100,000 m² ; Hectares = 100,000 / 10,000 = 10)', true, 'ebc463dc-5233-4278-910b-2275e613f83b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adeb8a19-28d6-48bf-8dce-20defe56fd32', '5 hectares', false, 'ebc463dc-5233-4278-910b-2275e613f83b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fd0af24-ff11-45f9-b5aa-197ff683f9da', '20 hectares', false, 'ebc463dc-5233-4278-910b-2275e613f83b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5674d98c-640d-4606-b9b5-d7d7cfbc006d', '100 hectares', false, 'ebc463dc-5233-4278-910b-2275e613f83b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e1e0f96-4a1d-42b5-a3bb-00b564726de0', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'A square park of side 60 m has a walking path of uniform width 3 m constructed INSIDE along its boundary. What is the area of this internal path?', 'Outer = 3600 m²; Inner = (60-6)² = 54² = 2916 m²; Path = 3600 - 2916 = 684 m².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('465338a1-85c6-4fbe-85e4-9708cfd48e4a', '684 sq m (Outer Area = 60 × 60 = 3600 m² ; Inner side = 60 - 6 = 54 m ; Inner Area = 54 × 54 = 2916 m² ; Path = 3600 - 2916 = 684 m²)', true, '2e1e0f96-4a1d-42b5-a3bb-00b564726de0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc84626a-8c05-4b44-8122-134890747f35', '720 sq m', false, '2e1e0f96-4a1d-42b5-a3bb-00b564726de0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a815627-9929-4da9-84d4-7e7c0fb6fc34', '600 sq m', false, '2e1e0f96-4a1d-42b5-a3bb-00b564726de0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29f0b76e-445e-4124-9b6c-55730350fded', '648 sq m', false, '2e1e0f96-4a1d-42b5-a3bb-00b564726de0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3789351c-6c3b-441a-9a45-c57ec78bcb64', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'If the length of a rectangle is increased by 50% and its breadth is decreased by 20%, what is the percentage change in its area?', 'New Area = 1.50 × 0.80 = 1.20 × Original Area (+20% increase).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21d37d6c-bb0c-42a9-9328-9eef657e1233', 'Increases by 20% (A_new = (1.5 l) × (0.8 b) = 1.20 (l × b) -> 20% increase)', true, '3789351c-6c3b-441a-9a45-c57ec78bcb64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb98bbfa-a3be-47e2-9159-005b52f74f4a', 'Increases by 30%', false, '3789351c-6c3b-441a-9a45-c57ec78bcb64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccacfd41-d2fa-4713-af6a-28730299e6ec', 'Decreases by 10%', false, '3789351c-6c3b-441a-9a45-c57ec78bcb64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00391202-7806-4923-aba9-11a22d57f471', 'Remains unchanged', false, '3789351c-6c3b-441a-9a45-c57ec78bcb64');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('792dd59b-64f1-4801-bebb-dc341fe4beae', 'Class 6', 'Mathematics', 'Chapter 10: Mensuration', 'Hard', 'Why is the study of Mensuration (perimeter and area) essential in architectural engineering and real-world civil planning?', 'Mensuration provides foundational geometric formulas for structural material estimation, cost budgeting, and land surveying.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83c70cd7-ca67-487d-98e4-7d30ac12fd1a', 'It enables precise material quantification, budget estimation for construction, land cadastral mapping, and cost calculation for tiling, painting, and fencing', true, '792dd59b-64f1-4801-bebb-dc341fe4beae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fec89af-f746-4164-9b3e-07046cffa109', 'Because numbers make buildings stronger by magic', false, '792dd59b-64f1-4801-bebb-dc341fe4beae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e77736c2-97d6-4e16-8338-2d34b7187de4', 'To prevent land from moving', false, '792dd59b-64f1-4801-bebb-dc341fe4beae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca1d9cba-4db5-4cfb-bc86-3b39fffa2597', 'Because rulers only measure area', false, '792dd59b-64f1-4801-bebb-dc341fe4beae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ddf5e4d1-d32e-48a0-a4db-0bc8f40c2f6f', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'Who is the world-renowned Indian author who wrote the autobiographical nature story ''The Banyan Tree''?', 'Ruskin Bond penned ''The Banyan Tree'', describing his childhood natural explorations in his grandfather''s garden in Dehradun.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('270848bb-fefa-42dc-b6ca-5a7c7797b108', 'Ruskin Bond', true, 'ddf5e4d1-d32e-48a0-a4db-0bc8f40c2f6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b7ef3eb-ea5f-4318-b2d2-5efbcdd3f24f', 'R.K. Narayan', false, 'ddf5e4d1-d32e-48a0-a4db-0bc8f40c2f6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42355bca-b29d-4120-92c5-4e5be5f9c6cc', 'Mulk Raj Anand', false, 'ddf5e4d1-d32e-48a0-a4db-0bc8f40c2f6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d82f8f5-52b7-40ff-b3fa-20f724f23e7f', 'Vikram Seth', false, 'ddf5e4d1-d32e-48a0-a4db-0bc8f40c2f6f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cfd7e9b7-5e12-48f6-88ed-a9697b6af3b1', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'Why did the young boy (narrator) claim that the magnificent old banyan tree belonged exclusively to HIM rather than his grandfather?', 'Grandfather at sixty-five had lost the agility to climb, making the sprawling banyan the young boy''s private leafy kingdom.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43ae7afb-120e-46d8-9d04-5462d7fb93f6', 'Because his sixty-five-year-old grandfather was too old to climb trees anymore', true, 'cfd7e9b7-5e12-48f6-88ed-a9697b6af3b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('405f06b5-154f-4172-8106-3beb997f6c92', 'Because the boy bought the tree with pocket money', false, 'cfd7e9b7-5e12-48f6-88ed-a9697b6af3b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('728833e3-55fc-488c-86a3-527082f89a6d', 'Because the tree was planted by the boy', false, 'cfd7e9b7-5e12-48f6-88ed-a9697b6af3b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6eb939ac-abd5-4c5b-a62f-90554dcf86a7', 'Because grandfather hated trees', false, 'cfd7e9b7-5e12-48f6-88ed-a9697b6af3b1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91cce569-eaba-43c6-9fec-a947b1f81334', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'Which small creature in the banyan tree became the narrator''s first bold friend, even eating pieces of cake and biscuits out of his hand?', 'A young grey squirrel shed its initial fear when it found the boy carried no catapult, soon eating crumbs from his hand.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5047b779-c5f5-4e74-b63d-617caa0ec919', 'A small grey Squirrel', true, '91cce569-eaba-43c6-9fec-a947b1f81334');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3f7ce46-8f29-4daa-a19e-0d43b6d10b59', 'A green parrot', false, '91cce569-eaba-43c6-9fec-a947b1f81334');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fcc7f11-f26e-40c5-8b19-50e446d5ab87', 'A white rabbit', false, '91cce569-eaba-43c6-9fec-a947b1f81334');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6026602c-8584-429b-96d6-b00bfcd891a8', 'A chameleon', false, '91cce569-eaba-43c6-9fec-a947b1f81334');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed13e0fd-6234-4220-9611-2158c8ad5c76', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'What did the boy build halfway up the banyan tree so he could spend hot afternoons reading adventure books?', 'The boy built a makeshift treehouse platform among the leafy branches, reading ''Treasure Island'' and ''Robinson Crusoe''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fc80146-560f-47be-813a-a3a4d9c62b3b', 'A crude wooden platform with cushions', true, 'ed13e0fd-6234-4220-9611-2158c8ad5c76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aeffe31e-21de-41a5-83a8-86af6c500a88', 'A stone castle', false, 'ed13e0fd-6234-4220-9611-2158c8ad5c76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75cf8fa9-3daf-4bfc-93eb-3934ac5e9f34', 'A glass house', false, 'ed13e0fd-6234-4220-9611-2158c8ad5c76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46b12f64-9dc4-4823-a9e2-5d50daaf165d', 'An iron cage', false, 'ed13e0fd-6234-4220-9611-2158c8ad5c76');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f61d64a-1d42-4ed3-8490-6cc6a7236212', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'What dramatic classic battle of nature did the boy witness from his banyan tree platform on a drowsy summer afternoon?', 'The boy witnessed the primordial duel between a 6-foot venomous black cobra and an agile 3-foot mongoose.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ed0bc64-8bae-42c0-bd8d-14b0570d5990', 'A deadly fight between a huge black Cobra and a nimble grey Mongoose', true, '0f61d64a-1d42-4ed3-8490-6cc6a7236212');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73480507-220d-4494-b33e-866d700ba8fd', 'A fight between a tiger and an elephant', false, '0f61d64a-1d42-4ed3-8490-6cc6a7236212');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52b5d925-58bd-405d-ba60-d4a9461ea0e2', 'A race between two horses', false, '0f61d64a-1d42-4ed3-8490-6cc6a7236212');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f54d0828-71be-4015-9c96-a53df45474d4', 'A battle between eagles', false, '0f61d64a-1d42-4ed3-8490-6cc6a7236212');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3487dc3d-02ca-488d-aaee-e2778e37fb7d', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'What two bird spectators perched on a nearby cactus bush to watch the cobra-mongoose fight?', 'A jungle crow and a myna sat on a prickly cactus bush, acting as eager onlookers and attempting to dive into the fight.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d60832ff-f889-4902-88be-0ae3d4fd6ad2', 'A Crow and a Myna', true, '3487dc3d-02ca-488d-aaee-e2778e37fb7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6dff1417-b386-4329-86c8-676b1b32750d', 'An Eagle and a Hawk', false, '3487dc3d-02ca-488d-aaee-e2778e37fb7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8239175a-1fca-4b2e-9b2b-a258f0b56185', 'A Parrot and a Pigeon', false, '3487dc3d-02ca-488d-aaee-e2778e37fb7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e853db6-b2df-4dae-aafd-8ba1bc269a02', 'A Peacock and a Sparrow', false, '3487dc3d-02ca-488d-aaee-e2778e37fb7d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c72bc713-44fb-45a0-b719-e3fb28f7161f', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'What happened to the foolish Crow when it persistently dived at the cobra during the battle?', 'On its third reckless dive, the cobra countered with a lightning strike, fatally colliding with the crow.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90d9579f-fc8c-4a72-971d-fec67d7de7e5', 'The cobra whipped its head back with lightning speed and struck the crow with its snout, flinging it dead onto the garden path', true, 'c72bc713-44fb-45a0-b719-e3fb28f7161f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94439eb6-8a96-4bc7-a510-7dbd996dd7b6', 'The crow flew away with the cobra', false, 'c72bc713-44fb-45a0-b719-e3fb28f7161f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eebe771e-c307-4ce7-81b1-7e9362764cf7', 'The crow won the fight', false, 'c72bc713-44fb-45a0-b719-e3fb28f7161f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0681c5d-6477-4378-bc24-03dee32de4c8', 'The myna saved the crow', false, 'c72bc713-44fb-45a0-b719-e3fb28f7161f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a0487356-3acb-4351-a63e-26553563764b', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'Who emerged VICTORIOUS in the epic duel beneath the banyan tree?', 'The mongoose exhausted the cobra with lightning feints, bit through its spine, and dragged its carcass into the bushes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccc09646-833c-4b0e-ba8a-3695d559b8fd', 'The Mongoose (which dragged the defeated cobra into the bushes)', true, 'a0487356-3acb-4351-a63e-26553563764b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cd4a588-b974-4567-bf7b-3c75b09197ed', 'The Cobra', false, 'a0487356-3acb-4351-a63e-26553563764b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57213120-afac-4485-8f45-9085fb58eae6', 'The Myna', false, 'a0487356-3acb-4351-a63e-26553563764b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a88c7add-53ee-4de5-932f-e62771d9c572', 'The Crow', false, 'a0487356-3acb-4351-a63e-26553563764b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9e48164-c12e-48eb-b7b4-946806746f27', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'In the supplementary story ''A Strange Wrestling Match'', who was Vijay Singh?', 'Vijay Singh was a hulking champion wrestler with massive muscles who foolishly boasted he wanted to wrestle a ghost.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ff198cf-a4f4-4ffa-9ede-9a2719fe5303', 'A famous, boastful wrestler who was unbeatable in the wrestling pit but had a fatal weakness for foolish bragging', true, 'f9e48164-c12e-48eb-b7b4-946806746f27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33d54d16-eea9-4535-9a10-50f861188aed', 'A timid ghost in a well', false, 'f9e48164-c12e-48eb-b7b4-946806746f27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5837a501-658b-4364-b6f9-7e6369eea593', 'A greedy shopkeeper', false, 'f9e48164-c12e-48eb-b7b4-946806746f27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('941a07cb-cc6e-4ba0-83d1-02746d5b5957', 'A learned school teacher', false, 'f9e48164-c12e-48eb-b7b4-946806746f27');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0e213517-fe91-49a5-be19-d702c5730c16', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'What was Vijay Singh''s boastful claim that led him to travel to the Haunted Deserts?', 'In an unguarded moment of bravado, Vijay Singh declared his desire to meet and thrash a ghost in the Haunted Desert.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c898713d-6462-4445-b404-f0b55165e574', 'That he was not afraid of any ghost and wished to meet a real ghost to teach him a wrestling lesson', true, '0e213517-fe91-49a5-be19-d702c5730c16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5888cfcf-30c9-4f08-b1e1-21046e1003d6', 'That he could lift a mountain', false, '0e213517-fe91-49a5-be19-d702c5730c16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('793b3e0b-f0ce-41d6-a332-0355815af5a0', 'That he could run faster than a cheetah', false, '0e213517-fe91-49a5-be19-d702c5730c16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a98c5dfc-504d-4187-9a0d-80e7e084cb67', 'That he could drink an entire river', false, '0e213517-fe91-49a5-be19-d702c5730c16');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35d3a543-5b0d-4b13-807e-6a188816e47e', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Easy', 'What two seemingly bizarre gifts did the eccentric old woman in the village give Vijay Singh in a packet before his departure?', 'The old woman handed him a small bag containing an ordinary raw egg and a lump of rock salt.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9948d8b9-3c9b-4ec5-8825-8f378bbd5826', 'A raw egg and a lump of sea salt', true, '35d3a543-5b0d-4b13-807e-6a188816e47e');
