INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a4666e50-e19a-496c-b783-04579cb32daa', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'How did Vijay Singh trick the ghost Natwar into believing that he possessed superhuman physical strength by squeezing a rock?', 'Vijay Singh''s sleight of hand substituted the egg; crushing it fooled the naive ghost into believing he squeezed liquid from rock.', NOW()) ON CONFLICT DO NOTHING;
