INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5140d589-a86f-4720-8a7c-14e49b5945bb', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'How did Vijay Singh trick the ghost a second time using the lump of salt?', 'Vijay Singh pulverized the brittle rock salt lump in his grip, convincing the terrified ghost he had turned stone into salt powder.', NOW()) ON CONFLICT DO NOTHING;
