INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88071c9f-d65e-4911-9be6-fde43e2abe32', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'How did Vijay Singh outwit the ghost''s nocturnal assassination attempt inside the ghost''s cave?', 'Vijay Singh rolled a bolster under his blanket; the ghost battered the pillow with a club thinking he had killed the wrestler.', NOW()) ON CONFLICT DO NOTHING;
