INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cae8c8aa-fb75-4b17-9733-60031b033a66', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'What was the final outcome of Vijay Singh''s encounter with the ghost in the Haunted Desert?', 'The ghost abandoned the desert; Vijay Singh restored stolen treasures to rightful owners and renounced boastful pride.', NOW()) ON CONFLICT DO NOTHING;
