INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('085a1afa-0a2e-4e19-acbd-2602e6a4fd36', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'Why did the Myna fly away safely while the Crow died in ''The Banyan Tree''?', 'The myna exercised prudent caution, declining to intervene in a battle between lethal apex specialists.', NOW()) ON CONFLICT DO NOTHING;
