INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc36b651-f5ea-4b48-a519-67440d0544a3', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Medium', 'In ''The Banyan Tree'', how did the boy feel while sitting quietly in the banyan tree during spring?', 'Bond captures the sublime romantic communion between a sensitive child observer and the vibrant natural world.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb1b7101-9d39-4b43-ade0-8886e5036278', 'He felt a profound, intimate kinship with nature, surrounded by chirping birds, buzzing bees, and red figs', true, 'cc36b651-f5ea-4b48-a519-67440d0544a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b46c9148-57b0-4b1b-b934-81107280c5f2', 'He felt bored and lonely', false, 'cc36b651-f5ea-4b48-a519-67440d0544a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fea3a7b-b47b-49d4-bb61-383f7aefebf4', 'He was terrified of falling', false, 'cc36b651-f5ea-4b48-a519-67440d0544a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56f4ea31-a0c9-495b-8abf-b12c12362f6e', 'He wanted to chop down the tree', false, 'cc36b651-f5ea-4b48-a519-67440d0544a3');
