INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14ffbdcb-1011-4f4e-a46e-19755d91bc09', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Hard', 'Spot the IMPOSTER in the following group of characters/elements paired with their texts from Chapter 10:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f528ba46-61cc-4540-a75a-ababcf31611d', 'Ruskin Bond - Narrator of Banyan Tree', false, '14ffbdcb-1011-4f4e-a46e-19755d91bc09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6f2e85a-cfb2-4c79-a5d2-974284edc5e2', 'Vijay Singh - Boastful wrestler', false, '14ffbdcb-1011-4f4e-a46e-19755d91bc09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8eb3760-8af3-47d4-a77c-d91e7944ebcc', 'Natwar - Ghost of Haunted Desert', false, '14ffbdcb-1011-4f4e-a46e-19755d91bc09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bbba284-d969-424f-85df-2401df80ce3e', 'Makara - The Crocodile from Banyan Tree', true, '14ffbdcb-1011-4f4e-a46e-19755d91bc09');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9426893-d020-4eb6-8901-f510828f20f7', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Hard', 'Analyze how Vijay Singh''s boastfulness in the opening of the story represents a classic folkloric character arc:', 'The classic moral arc moves from hubristic vulnerability to intellectual realization and moral humility.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5be4aa41-1cbc-4342-a347-a54107eb42c9', 'His hubristic flaw (vanity and bragging) leads him into mortal peril, which he survives through razor-sharp wit, emerging thoroughly humbled and wiser', true, 'e9426893-d020-4eb6-8901-f510828f20f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3a43acd-2afd-4325-b6ed-852b6ec92030', 'He becomes a magical wizard', false, 'e9426893-d020-4eb6-8901-f510828f20f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('451042c1-032f-4ce0-9a3f-c6e23ba60403', 'He loses his memory', false, 'e9426893-d020-4eb6-8901-f510828f20f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7398e3b8-28b9-415e-a7a1-8c31b131da95', 'He joins the ghosts in haunting deserts', false, 'e9426893-d020-4eb6-8901-f510828f20f7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2be4413a-7c3f-464a-a52c-fcb7d1634153', 'Class 6', 'English', 'Chapter 10: The Banyan Tree', 'Hard', 'Match Column I (Characters / Items) with Column II (Roles in Chapter 10):
(a) Ruskin Bond    -> (i) Young boy observing nature from banyan tree platform
(b) Grey Mongoose   -> (ii) Agile victor of the epic garden duel
(c) Raw Egg & Salt  -> (iii) Improvised psychological props used to trick the ghost
(d) Bolster / Pillow-> (iv) Decoy used under blanket to survive midnight clubbing', 'Bond = narrator; Mongoose = victor; Egg/Salt = psychological props; Bolster = bed decoy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bafad0ec-7467-45ce-a806-bc82ca96b571', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '2be4413a-7c3f-464a-a52c-fcb7d1634153');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a9c8213-2900-4679-9d52-5a8545284923', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '2be4413a-7c3f-464a-a52c-fcb7d1634153');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('223cb4e4-6d39-4a6e-88bf-3c9bea2922df', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '2be4413a-7c3f-464a-a52c-fcb7d1634153');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea24d371-dee7-4ee7-bbce-7315ef685b86', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '2be4413a-7c3f-464a-a52c-fcb7d1634153');
