INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8f0bb2d-9217-4f4b-bbc6-8e4174562011', 'Statements 1 and 2 only', true, '197ea164-b18d-4520-94e8-3090d7514019');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40b88a94-da8a-4e29-8c40-6eaacf595358', 'Statements 2 and 3 only', false, '197ea164-b18d-4520-94e8-3090d7514019');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7691c96-d7b3-4470-b1cc-b4ccebdbc8b7', 'Statements 1 and 3 only', false, '197ea164-b18d-4520-94e8-3090d7514019');
