INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe3ebb21-6aa3-4ed2-a234-38fba3ae66d2', 'Class 6', 'GK', 'Chapter 10: World Geography, Continents, Oceans & Global Wonders', 'Easy', 'Which is the LARGEST and DEEPEST ocean on Earth, covering more than one-third of the globe?', 'The Pacific Ocean covers 165.25 million km², larger than all Earth''s landmasses combined.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f6590eb-a182-4930-bc06-a9716d960fd4', 'Pacific Ocean', true, 'fe3ebb21-6aa3-4ed2-a234-38fba3ae66d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a30167c7-8641-43dc-a3ca-30ab06405be7', 'Atlantic Ocean', false, 'fe3ebb21-6aa3-4ed2-a234-38fba3ae66d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('340003e6-f76c-49cd-815a-f97fa0f23c45', 'Indian Ocean', false, 'fe3ebb21-6aa3-4ed2-a234-38fba3ae66d2');
