INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3a1598e4-8c47-459c-9efd-529d32df59df', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'Why did ancient kings try hard to control the Silk Route?', 'Controlling choke points allowed kingdoms to levy transit tolls, ensuring armed security in exchange for tariffs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82431098-262a-48ef-a560-808e6f377461', 'Because they could collect rich taxes, customs duties, and precious gifts from wealthy merchants traveling with valuable goods along the route', true, '3a1598e4-8c47-459c-9efd-529d32df59df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40cedd15-496d-4890-87f1-7e57316223b7', 'Because kings wanted to make silk shirts themselves', false, '3a1598e4-8c47-459c-9efd-529d32df59df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d237efbd-c502-4887-afbc-667c019ec346', 'Because the route was made of gold', false, '3a1598e4-8c47-459c-9efd-529d32df59df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c562680e-438e-498a-af86-1ef94ebd9a08', 'Because nobody else was allowed on the road', false, '3a1598e4-8c47-459c-9efd-529d32df59df');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7450a2e7-10e1-4319-b75f-472c7337b114', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What two major sculptural art schools produced exquisite Buddha statues under Mahayana Buddhism?', 'Gandhara fused Hellenistic drapery with Buddhist themes, while Mathura evolved robust indigenous stone iconography.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36f1c4d7-2daa-4184-8305-5eba5abbfe0e', 'Mathura Art School (indigenous red sandstone style) and Gandhara Art School (Greco-Buddhist style in Taxila/Peshawar)', true, '7450a2e7-10e1-4319-b75f-472c7337b114');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fece453-dba2-4c11-bd67-e1167bb00565', 'Chola and Pallava style', false, '7450a2e7-10e1-4319-b75f-472c7337b114');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f78523a-711a-484a-8f71-fc0971c5fe26', 'Roman and Egyptian style', false, '7450a2e7-10e1-4319-b75f-472c7337b114');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3d2b0e7-5dcd-47ad-a4a1-40c1b9576c78', 'Mughal and Rajput style', false, '7450a2e7-10e1-4319-b75f-472c7337b114');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e89ce10-e371-4f2d-a32d-f79a2fefd237', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'How did Xuan Zang transport hundreds of sacred Buddhist manuscripts and golden statues back from India to China in 645 CE?', 'Xuan Zang transported 657 Sanskrit texts on pack horses, spending his remaining life in Chang''an translating them into Chinese.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86837f9e-65d7-44d6-b231-e2fd5f830503', 'Loaded on the backs of 20 horses across the overland mountain passes of the Pamirs, Hindu Kush, and Taklamakan desert', true, '8e89ce10-e371-4f2d-a32d-f79a2fefd237');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cb071fb-c4db-4a6d-bfa3-756b49f7d887', 'On a modern cargo airplane', false, '8e89ce10-e371-4f2d-a32d-f79a2fefd237');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01752cb5-1cfc-4221-b4b2-0975ab7e9dbb', 'By sending a postal parcel', false, '8e89ce10-e371-4f2d-a32d-f79a2fefd237');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5609a51d-f4ec-44d8-86c7-730438d3fa51', 'Through underwater tunnels', false, '8e89ce10-e371-4f2d-a32d-f79a2fefd237');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('df18ff04-872b-4f1d-9a2c-b1366cfb79fa', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What religious path gained immense popularity in India during this period, emphasizing intense personal devotion and pure love for a chosen deity (Ishta-Deva) regardless of caste or gender?', 'Bhakti (from Sanskrit ''bhaj'' = to share/devote) emphasized egalitarian personal devotion to Shiva, Vishnu, or Durga.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2694eff-cbfd-41a3-885b-5c4a98323996', 'Bhakti Movement (Bhakti Marga)', true, 'df18ff04-872b-4f1d-9a2c-b1366cfb79fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a59a8097-b621-43cc-9f65-ec324f21476f', 'Yajna ritualism', false, 'df18ff04-872b-4f1d-9a2c-b1366cfb79fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('925d522d-3a84-4782-abd1-b460bae85e60', 'Vedic sacrifice', false, 'df18ff04-872b-4f1d-9a2c-b1366cfb79fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('182f2e83-ff5e-4a2f-96bd-3d84a5216f37', 'Tantric isolation', false, 'df18ff04-872b-4f1d-9a2c-b1366cfb79fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d43f83b-d5d4-4d6d-b76e-8a2f55002b74', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'Which sacred Hindu scripture (a 700-verse section of the Mahabharata) contains the foundational doctrine of Bhakti taught by Lord Krishna to Arjuna?', 'In the Gita, Krishna reveals ''Bhakti Marga'' (devotional self-surrender) as the supreme path to spiritual liberation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e648e84-a21d-4b6f-8444-bc2c8d80077f', 'The Bhagavad Gita', true, '8d43f83b-d5d4-4d6d-b76e-8a2f55002b74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95b87adf-b95e-4212-b00f-3f25189a2727', 'The Ramayana', false, '8d43f83b-d5d4-4d6d-b76e-8a2f55002b74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3be7464d-53d7-4446-8deb-59b8ebc73d67', 'Rigveda', false, '8d43f83b-d5d4-4d6d-b76e-8a2f55002b74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6134c0c-d751-46d8-aed4-5238313943af', 'Manusmriti', false, '8d43f83b-d5d4-4d6d-b76e-8a2f55002b74');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1951bca6-0fef-4b7c-94ac-771e1f59ccd1', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What does the Sanskrit root word ''Bhaj'' in ''Bhakti'' literally mean?', '''Bhaj'' means to share intimately, signifying a mutual emotional relationship between the bhakta and the Divine.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6b1f0aa-aeac-4e63-ba24-8d920b2076ce', 'To divide, share, participate in, or belong to (creating a reciprocal loving bond between the devotee and deity)', true, '1951bca6-0fef-4b7c-94ac-771e1f59ccd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80a9b422-2392-4963-a2d1-da3988c69cc8', 'To fight in war', false, '1951bca6-0fef-4b7c-94ac-771e1f59ccd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36685032-b26a-45e9-bd3c-6b87eaabee7b', 'To fast without food', false, '1951bca6-0fef-4b7c-94ac-771e1f59ccd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('886fe7e7-7770-4c43-ab24-9ef75aa835a9', 'To speak Sanskrit', false, '1951bca6-0fef-4b7c-94ac-771e1f59ccd1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20eea0ee-86f9-4545-a3d0-4b93a21915ea', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'Why was the Bhakti movement revolutionary in the socio-religious history of ancient India?', 'Bhakti dismantled caste-based religious exclusivism, making direct devotion universally accessible to all social strata.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67bbc409-dd65-4ae5-9d14-dbaecbcf315a', 'It threw open spiritual salvation to everyone—rich or poor, high caste or low caste, men or women—without expensive priestly rituals or animal sacrifices', true, '20eea0ee-86f9-4545-a3d0-4b93a21915ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ad9fd38-0586-4b80-9914-51a7abe216ee', 'It banned all temples', false, '20eea0ee-86f9-4545-a3d0-4b93a21915ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f67d6f99-2b78-4efb-ba78-2d25d5f55e78', 'It ordered everyone to become monks', false, '20eea0ee-86f9-4545-a3d0-4b93a21915ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff118b46-5c6e-4387-9cd1-62e64feb4833', 'It was only for kings', false, '20eea0ee-86f9-4545-a3d0-4b93a21915ea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f533e03d-7eb6-47a4-b11f-a97ed22ae0fa', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What is the famous depiction of Lord Vishnu as the ''Varaha'' (Boar) avatar rescuing Mother Earth (Bhudevi) from the cosmic ocean carved in stone at:', 'Gupta-era colossal Varaha bas-reliefs at Udayagiri and Eran symbolize cosmic restoration and divine salvation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aca72bf-b302-4a9d-b83f-9d343b3c3e86', 'Eran (Madhya Pradesh) and Udayagiri caves', true, 'f533e03d-7eb6-47a4-b11f-a97ed22ae0fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c7cd3a8-004e-40b6-bfe9-4fbdb4dee9d5', 'Sanchi', false, 'f533e03d-7eb6-47a4-b11f-a97ed22ae0fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb229c39-b2d4-4ab7-8d4b-2849583742de', 'Ajanta', false, 'f533e03d-7eb6-47a4-b11f-a97ed22ae0fa');
