INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ccb2cba-355e-4a0f-9bce-e8488164d8a6', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'How did Buddhist monk pilgrim Fa Xian describe his perilous sea return journey from Tamralipti port (Bengal) to China via Sri Lanka and Java?', 'Fa Xian''s travelogue chronicles the terror of monsoonal typhoons, clinging to his precious Buddhist manuscripts on board.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb4a0348-a7a8-4fe2-8233-ecdf13763666', 'His merchant ship encountered a catastrophic cyclone storm for 13 days, forcing merchants to throw all heavy trade cargo overboard to prevent the ship from sinking', true, '9ccb2cba-355e-4a0f-9bce-e8488164d8a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c8eaa10-fcd9-4a64-ba09-5e6bc1050b1b', 'He sailed smoothly without wind', false, '9ccb2cba-355e-4a0f-9bce-e8488164d8a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d98b9c2-b195-4dce-9997-1cf14b438c41', 'He was captured by Roman soldiers', false, '9ccb2cba-355e-4a0f-9bce-e8488164d8a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcb15ea8-ff7b-4e3b-aabc-2e14e03eecd8', 'He walked across the ocean on foot', false, '9ccb2cba-355e-4a0f-9bce-e8488164d8a6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13ed0a91-85f1-4f10-b02f-ee5e595353cf', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What strict entrance examination did students have to pass to gain admission into Nalanda University, according to Xuan Zang?', 'Xuan Zang noted that Nalanda maintained rigorous academic standards, screening applicants through oral philosophical disputation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fea91f91-e49e-4fca-bde4-645245083d02', 'The Gatekeeper (Dvarapandita) posed deep philosophical questions at the main entrance gate; only 20% to 30% of applicants could answer and gain admission', true, '13ed0a91-85f1-4f10-b02f-ee5e595353cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d72fd778-f259-4bfd-9323-698b38f05019', 'They had to pay 100 gold coins', false, '13ed0a91-85f1-4f10-b02f-ee5e595353cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2231f242-1e99-4dc7-989b-e84ead9251a1', 'They had to run a 5-mile race', false, '13ed0a91-85f1-4f10-b02f-ee5e595353cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04c33422-4b4c-4352-855e-9b290dc9b176', 'They had to belong to royal families', false, '13ed0a91-85f1-4f10-b02f-ee5e595353cf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('acc9f10e-bd75-4c95-8395-89656f56dd43', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'Who was the South Indian Bhakti poet-saint Appar (a devotee of Lord Shiva) who composed soulful devotional poems in Tamil celebrating equality?', 'Appar (Thirunavukkarasar), a peasant Vellalar, composed Tevaram hymns proclaiming that sincere devotion supersedes caste origins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd445333-fbfe-4b69-9ef9-68edff0d3790', 'A 7th-century Nayanar saint who was a Vellalar (farmer)', true, 'acc9f10e-bd75-4c95-8395-89656f56dd43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90162f01-7f38-4764-9729-01f08599d9e8', 'A Buddhist monk', false, 'acc9f10e-bd75-4c95-8395-89656f56dd43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9ce42fd-ea96-4159-8e29-e1105070e289', 'A Greek trader', false, 'acc9f10e-bd75-4c95-8395-89656f56dd43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5566eec-2dfb-4fe8-b748-5f60eef8c764', 'A Kushana king', false, 'acc9f10e-bd75-4c95-8395-89656f56dd43');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46921958-825e-4618-9b02-cf9b53094a67', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What three ruling dynasties were known as the ''Muvendar'' (Three Crowned Kings) who controlled the fertile Kaveri delta and southern coastal ports around 2,300 years ago?', 'Sangam literature celebrates the ''Muvendar'': the Cholas (Uraiyur/Puhar), Cheras (Karur/Muziris), and Pandyas (Madurai/Korkai).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6364fcb-676b-4ac1-82f1-b9afd09a1166', 'The Cholas, the Cheras, and the Pandyas', true, '46921958-825e-4618-9b02-cf9b53094a67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73729bcd-0d3b-4eb6-8f8f-931169ebb793', 'The Mauryas, Guptas, and Kushanas', false, '46921958-825e-4618-9b02-cf9b53094a67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20cccfdf-5126-4bcd-ab99-328a8df9be9e', 'The Pallavas, Chalukyas, and Rashtrakutas', false, '46921958-825e-4618-9b02-cf9b53094a67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56107df6-25dc-4d56-b51a-61435845b696', 'The Mughals, Marathas, and Rajputs', false, '46921958-825e-4618-9b02-cf9b53094a67');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('984b8c63-90ad-4d97-b20c-96aa15dc5a14', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What was Puhar (also known as Kaveripattinam) in ancient South India?', 'Puhar was the bustling maritime port of the Cholas, vividly depicted in the Tamil epic ''Silappadikaram''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28641fa9-16ed-4ff5-8ada-7e233b888979', 'The premier coastal port city of the early Cholas on the Bay of Bengal, bustling with international sea trade', true, '984b8c63-90ad-4d97-b20c-96aa15dc5a14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac1eb03e-d170-4820-9039-15e62656a9cd', 'The capital of the Kushanas', false, '984b8c63-90ad-4d97-b20c-96aa15dc5a14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('459ad28d-9d46-4746-bbc0-040afbf00cba', 'A monastery in Kashmir', false, '984b8c63-90ad-4d97-b20c-96aa15dc5a14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1738d64-4c58-4a46-89f3-b39055a69604', 'A desert oasis', false, '984b8c63-90ad-4d97-b20c-96aa15dc5a14');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('463dd136-5382-4492-a25d-5077f338d6af', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What Indian commodity was so prized in the ancient Roman Empire that it was popularly called ''Black Gold'' (Yavanapriya)?', 'Malabar black pepper was in such huge demand in Rome that it was traded for its weight in gold and termed ''Black Gold''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8db92bf0-5803-4be1-be37-4f43d625475b', 'Black Pepper (Kali Mirch)', true, '463dd136-5382-4492-a25d-5077f338d6af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58c75211-bc4a-4ed4-9097-4a243ddaa076', 'Black tea', false, '463dd136-5382-4492-a25d-5077f338d6af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f88fe005-8849-4909-bf35-7d5e97b7e1a2', 'Coal', false, '463dd136-5382-4492-a25d-5077f338d6af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef20544c-0de4-4483-992b-8439dd52a9f2', 'Black stone', false, '463dd136-5382-4492-a25d-5077f338d6af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('69f19c64-b16f-4899-8976-a0fb2cbc8d99', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'How did ancient sailors and merchant navigators cross the Arabian Sea to reach the western ports of India quickly?', 'Hippalus and Greek sailors harnessed the predictable seasonal Southwest Monsoon winds to sail straight across the open Arabian Sea.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b23c38d-8670-468c-b9fc-3af062b0c531', 'They took strategic advantage of the seasonal Southwest Monsoon winds to sail directly across the open ocean from the Gulf of Aden to the Malabar coast in summer', true, '69f19c64-b16f-4899-8976-a0fb2cbc8d99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3999a21a-28cb-4803-ba8c-d444ccfdec58', 'Using steam engine ships', false, '69f19c64-b16f-4899-8976-a0fb2cbc8d99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a79debd8-575e-4de9-8a94-4f2b6d2d4b83', 'By rowing continuously by hand without sails', false, '69f19c64-b16f-4899-8976-a0fb2cbc8d99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89cc0d50-3d0e-4894-954b-4e14d832e74b', 'By following stars in winter only', false, '69f19c64-b16f-4899-8976-a0fb2cbc8d99');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5fb079ed-7403-4b01-921b-f4521a53563e', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Medium', 'What is the primary spiritual concept behind the construction of magnificent Hindu temple architecture that evolved from the Bhakti movement?', 'Bhakti catalyzed temple architecture: housing the enshrined deity in the sanctum sanctorum (Garbhagriha) for direct darshan.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6abf5d89-8a5d-4c25-8410-c67d301ec909', 'Creating sacred physical abodes (Prasad/Garbhagriha) where the chosen deity resides to receive personal loving worship and darshan from devotees', true, '5fb079ed-7403-4b01-921b-f4521a53563e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d69575da-4790-49c8-900b-e32ce66f7fdc', 'Building fortresses for war', false, '5fb079ed-7403-4b01-921b-f4521a53563e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6203663f-d27e-4223-91fd-93414ba78fd1', 'Storing grain for famine', false, '5fb079ed-7403-4b01-921b-f4521a53563e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b827e161-e3cd-4671-be21-08469ab1e585', 'Astronomical observatories only', false, '5fb079ed-7403-4b01-921b-f4521a53563e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f343fc68-c324-4273-9239-98da807e833a', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8f70f21-bcf8-4aa1-bfc2-865772659955', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'f343fc68-c324-4273-9239-98da807e833a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1a837c9-b330-4da0-a0ec-19be30b1a5f5', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'f343fc68-c324-4273-9239-98da807e833a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be7c817e-9e16-45b5-b0af-7de299602c8e', '(A) is true, but (R) is false.', false, 'f343fc68-c324-4273-9239-98da807e833a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91f258bd-3f8e-4ef3-a14c-df6b0f9472c6', '(A) is false, but (R) is true.', false, 'f343fc68-c324-4273-9239-98da807e833a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('abfb36dd-d62e-4fb5-94b2-00b09521572b', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'Spot the IMPOSTER in the following group of ancient Chinese pilgrims who visited India to study Buddhist texts:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f744680c-50ce-45ed-9ee4-4b22cb2edfe9', 'Fa Xian (Faxian)', false, 'abfb36dd-d62e-4fb5-94b2-00b09521572b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a44c7076-17a0-411e-aedf-1689f27bb5f7', 'Xuan Zang (Hiuen Tsang)', false, 'abfb36dd-d62e-4fb5-94b2-00b09521572b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70de0d30-2895-49ca-a3b7-2dcf442590f7', 'I-Qing (Yijing)', false, 'abfb36dd-d62e-4fb5-94b2-00b09521572b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a9f236f-2771-4cac-9c2a-4bc5b52f96ea', 'Megasthenes', true, 'abfb36dd-d62e-4fb5-94b2-00b09521572b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56bf987e-825e-41d8-a5a6-6ea6d98302b4', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'Consider the theological evolution between Early Buddhism (Theravada) and Later Buddhism (Mahayana):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('022f1bd3-be65-4eef-96e0-71a299e54363', 'Depicting Buddha in anthropomorphic human statue form and worshipping Bodhisattvas who postpone nirvana to save all sentient beings', true, '56bf987e-825e-41d8-a5a6-6ea6d98302b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('082ef06c-b2b9-4aa4-bcd2-1c0c6c84fb0a', 'Strictly representing Buddha through aniconic symbols (footprints, empty throne, wheel)', false, '56bf987e-825e-41d8-a5a6-6ea6d98302b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37528ac4-5e5e-46c3-a1aa-10924f1d6fce', 'Banning all statues and rituals', false, '56bf987e-825e-41d8-a5a6-6ea6d98302b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('727e94f5-e8e0-43e0-af24-00038dd206a6', 'Using only Pali language and rejecting Sanskrit', false, '56bf987e-825e-41d8-a5a6-6ea6d98302b4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b83a7783-d32b-4bc5-a6e6-538c7271e895', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'Match Column I (Ancient Personalities / Texts) with Column II (Historical Contributions):
(a) Kanishka     -> (i) Author of Buddhacharita in Sanskrit
(b) Ashvaghosha  -> (ii) Kushana Emperor who convened 4th Buddhist Council
(c) Xuan Zang    -> (iii) Pilgrim who spent 16 years studying at Nalanda
(d) Appar        -> (iv) Nayanar saint who composed Tamil devotional hymns', 'Kanishka = 4th Council; Ashvaghosha = Buddhacharita; Xuan Zang = Nalanda scholar; Appar = Nayanar saint.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('787edd7b-ece7-4531-9799-36ca1b9f5f3d', 'a-(ii), b-(i), c-(iii), d-(iv)', true, 'b83a7783-d32b-4bc5-a6e6-538c7271e895');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6141815d-ce23-4bee-b1bd-6f91a682c5b2', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'b83a7783-d32b-4bc5-a6e6-538c7271e895');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99510453-57b2-48cc-890a-0dc2bfcd0daa', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'b83a7783-d32b-4bc5-a6e6-538c7271e895');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c236c16-aca2-4079-a6d8-aa00d93dacdc', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'b83a7783-d32b-4bc5-a6e6-538c7271e895');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8f35e2c-289c-41ea-a7aa-0f45a47b21a8', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'Read the statements regarding ancient pilgrims:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3fac667-16eb-4e1d-938f-289d2624d0ea', 'Statements 1 and 3 only', true, 'c8f35e2c-289c-41ea-a7aa-0f45a47b21a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('533b5c14-8002-43a3-83df-682cada59e92', 'Statements 1 and 2 only', false, 'c8f35e2c-289c-41ea-a7aa-0f45a47b21a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3f5f3db-9390-4505-8e42-bc2318449743', 'Statements 2 and 3 only', false, 'c8f35e2c-289c-41ea-a7aa-0f45a47b21a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7136709-670b-49fe-a949-6450e0a97dca', 'All Statements 1, 2, and 3', false, 'c8f35e2c-289c-41ea-a7aa-0f45a47b21a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('29dd3929-abab-4350-9b03-f581f76660b3', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'What was the administrative concept of ''Muvendar'' mentioned in Sangam poems, where each of the three ruling chiefs had TWO centers of power?', 'Dual nodes of power: Cholas (Uraiyur inland + Puhar port), Pandyas (Madurai inland + Korkai port), Cheras (Karur inland + Muziris port).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6646c63f-f934-469a-89e0-f7be43b20070', 'Each dynasty (Cholas, Cheras, Pandyas) maintained ONE inland capital city and ONE coastal seaport, totaling six major urban power hubs in South India', true, '29dd3929-abab-4350-9b03-f581f76660b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8b5bbec-30d2-4c6c-8520-a229b0569d67', 'Each had two kings ruling at once', false, '29dd3929-abab-4350-9b03-f581f76660b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62af7efc-1d05-44af-b05b-6243334f4bc0', 'Each ruled over two separate islands', false, '29dd3929-abab-4350-9b03-f581f76660b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c0acbc0-d3fe-4a5a-a2ae-4b3b2b0ab387', 'Each had two armies', false, '29dd3929-abab-4350-9b03-f581f76660b3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20114836-0079-4f9c-ab47-a56eb4deaa2b', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'Why did the Kushana rulers issue such high-denomination, pure GOLD coins around the 1st century CE?', 'Kushana gold dinars mirrored Roman imperial weight standards (8 grams), creating a convertible reserve currency along the Silk Road.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd64bd67-7808-49f0-bf15-a672513b9fc0', 'To facilitate large-scale international transactions on the Silk Route, fueled by massive inflows of Roman gold and overland transit profits', true, '20114836-0079-4f9c-ab47-a56eb4deaa2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('596bdb48-6b95-4978-a25e-edd39c9b37bf', 'Because they had no copper or silver', false, '20114836-0079-4f9c-ab47-a56eb4deaa2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce63e6cd-b750-41c2-b835-2c1f53b2d474', 'To give as gifts to pilgrims', false, '20114836-0079-4f9c-ab47-a56eb4deaa2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22a62132-9731-41cb-b6f5-230e8db48790', 'To melt and build gold palaces', false, '20114836-0079-4f9c-ab47-a56eb4deaa2b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad347a3c-37b2-4abf-86c1-39aadd43d2d4', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'Consider four events in the history of trade and pilgrimage:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d5c0c45-b7c6-4842-8ffd-ce5079cb1d9a', '1 -> 2 -> 3 -> 4', true, 'ad347a3c-37b2-4abf-86c1-39aadd43d2d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a3989fc-586c-484b-b6ec-bfa1b962b0c1', '2 -> 1 -> 3 -> 4', false, 'ad347a3c-37b2-4abf-86c1-39aadd43d2d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d80e122-23a4-4ce2-b979-0a03dd7a107b', '1 -> 3 -> 2 -> 4', false, 'ad347a3c-37b2-4abf-86c1-39aadd43d2d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b207e34-a5e0-442b-963f-e884be38ef2a', '4 -> 3 -> 2 -> 1', false, 'ad347a3c-37b2-4abf-86c1-39aadd43d2d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b54e1d8d-8f62-488f-90e7-be4e383d0d72', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'What role did Buddhist monastic establishments along trade routes (such as Kanheri, Karle, and Ajanta rock-cut chaityas and viharas) play in ancient commerce?', 'Rock-cut viharas located along mountain passes (Bhor Ghat, Thal Ghat) offered safe lodging, credit, and water for merchant guilds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35353f4e-ba1a-46fb-8a7c-3bc24097a989', 'They served as secure rest stops, financial banking vaults, and provisioning stations for traveling merchant caravans passing through Western Ghat passes', true, 'b54e1d8d-8f62-488f-90e7-be4e383d0d72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f0c68d5-f5bc-4f47-b6d5-689c08a619da', 'They were military garrisons', false, 'b54e1d8d-8f62-488f-90e7-be4e383d0d72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9adad71-0d6a-4d3d-8e07-a3b980efd863', 'They manufactured silk', false, 'b54e1d8d-8f62-488f-90e7-be4e383d0d72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fa39fbb-ddc7-42a6-a25d-8a93a2d70a1e', 'They minted royal coins', false, 'b54e1d8d-8f62-488f-90e7-be4e383d0d72');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32db0990-5c1c-4400-80b3-2c63ef419e46', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'How did the Bhakti philosophy transform Indian art, poetry, and regional vernacular languages?', 'Bhakti democratized culture, spawning vernacular literature (Tevaram, Divya Prabandham) and emotive temple sculpture.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5103df00-da4a-4885-ba4e-3608d24cbe49', 'It inspired an explosion of devotional poetry, music, and sculpture composed in popular regional spoken languages (Tamil, Kannada, Marathi, Hindi) rather than exclusive elite Sanskrit alone', true, '32db0990-5c1c-4400-80b3-2c63ef419e46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b077acd9-21bb-48f1-b4cf-d161fe2fadc9', 'It banned all vernacular poetry', false, '32db0990-5c1c-4400-80b3-2c63ef419e46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28132ced-fc04-40ea-8f42-aa71cdb1b6d4', 'It stopped people from painting', false, '32db0990-5c1c-4400-80b3-2c63ef419e46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e609fb8-0114-4784-9703-fe1ef96dde91', 'It mandated writing books only in Greek', false, '32db0990-5c1c-4400-80b3-2c63ef419e46');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e810b3f3-efd7-4dc5-9e58-5a7bb1b94221', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'What is the profound philosophical meaning behind the Bhagavad Gita''s teaching on ''Nishkama Karma'' in the context of Bhakti?', 'Nishkama Karma unites selfless duty with spiritual devotion, purifying human intent of egoistic desire.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e24ef22e-30ba-40e6-858d-31364e6b23ee', 'Performing one''s righteous duty selflessly without selfish attachment to the fruits or rewards of action, dedicating all outcomes in love to the Divine', true, 'e810b3f3-efd7-4dc5-9e58-5a7bb1b94221');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca9657c4-007f-4517-a394-6d37e4b7ebe0', 'Renouncing all work and sitting idle', false, 'e810b3f3-efd7-4dc5-9e58-5a7bb1b94221');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a003745-0c3f-47b4-84f8-34f7eeab8228', 'Fighting wars to acquire personal wealth', false, 'e810b3f3-efd7-4dc5-9e58-5a7bb1b94221');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8900dd66-15ad-4a11-acfa-ce77fdb0e8fb', 'Doing good deeds only for praise', false, 'e810b3f3-efd7-4dc5-9e58-5a7bb1b94221');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e39c335-1786-4717-8786-f76344c12794', 'Class 6', 'Social Science', 'Chapter 10: Traders, Kings and Pilgrims', 'Hard', 'What grand historical synthesis does Chapter 10 of NCERT History reveal about the ancient world?', 'The chapter portrays an open, interconnected global ancient world enriched by trade, intellectual cross-pollination, and shared spiritual quest.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76eeecd0-de14-4299-b54d-fdbc986192bd', 'A dynamic, interconnected world where trans-continental trade corridors, imperial patronage, philosophical reformations, and spiritual pilgrimages fostered deep cross-cultural synthesis across human civilization', true, '9e39c335-1786-4717-8786-f76344c12794');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0af1717-17a3-43c2-ba39-b1c38574584f', 'A collection of completely isolated civilizations with zero contact', false, '9e39c335-1786-4717-8786-f76344c12794');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('859ada9d-eb5a-4dd8-a2d2-781a56b18578', 'A world where only war existed without trade', false, '9e39c335-1786-4717-8786-f76344c12794');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51d4a8ad-a004-4be7-b8bf-969bf589abc0', 'A primitive society without roads or ideas', false, '9e39c335-1786-4717-8786-f76344c12794');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4690900b-f8df-4d82-a1de-e31023bf8053', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'जिस शब्द से किसी कार्य के करने या होने का बोध होता है (जैसे: पढ़ना, लिखना, दौड़ना, खाना, सोना, होना), उसे व्याकरण में क्या कहते हैं?', 'कार्य के निष्पादन या स्वतः होने का बोध कराने वाले विकारी शब्द ''क्रिया'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c687d2a-12f9-46a0-90c8-d1cf7f2c2682', 'क्रिया (Verb)', true, '4690900b-f8df-4d82-a1de-e31023bf8053');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5526064c-af40-4e0c-bb27-ab913a323579', 'संज्ञा', false, '4690900b-f8df-4d82-a1de-e31023bf8053');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce425230-cf68-4ca8-b6b1-021c9b805f5d', 'विशेषण', false, '4690900b-f8df-4d82-a1de-e31023bf8053');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c96e9d3-4353-4ba9-ba64-7f37c46531a8', 'सर्वनाम', false, '4690900b-f8df-4d82-a1de-e31023bf8053');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8178950a-2a7b-499e-8624-1c3bfc0fe28f', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'क्रिया के मूल रूप (Basic root form) को क्या कहते हैं, जिससे विभिन्न क्रिया पद बनते हैं (जैसे: ''पढ़'' से पढ़ना, पढ़ता, पढ़ेगा)?', 'क्रिया के मूल अविभाज्य रूप को ''धातु'' कहते हैं (जैसे: लिख, खा, देख, गा, हँस)। धातु में ''ना'' प्रत्यय जोड़कर सामान्य क्रिया बनती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c84130c-5e09-4cbd-b6bc-ad09c7a84dc9', 'धातु (Root)', true, '8178950a-2a7b-499e-8624-1c3bfc0fe28f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d75474a5-81e9-43e9-8d01-c8382a5ed823', 'उपसर्ग', false, '8178950a-2a7b-499e-8624-1c3bfc0fe28f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47a49e96-6b0a-4416-be78-64c3d068e7dc', 'प्रत्यय', false, '8178950a-2a7b-499e-8624-1c3bfc0fe28f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0bd3e86-ce82-4d82-90c1-da878ce2690c', 'समास', false, '8178950a-2a7b-499e-8624-1c3bfc0fe28f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31fcccd4-3354-445b-87e2-32a3f54e70fa', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'कर्म के आधार पर क्रिया के मुख्य रूप से कितने भेद होते हैं?', 'कर्म की अपेक्षा के आधार पर क्रिया के 2 प्रमुख भेद हैं: सकर्मक (कर्म सहित) और अकर्मक (कर्म रहित)।', NOW()) ON CONFLICT DO NOTHING;
