INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6cb4e995-91a0-4706-b160-c5bc3ac5f1fd', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'जिस क्रिया के व्यापार (कार्य) का फल कर्ता पर न पड़कर ''कर्म'' पर पड़ता है (अर्थात् जिसमें कर्म की आवश्यकता होती है), उसे क्या कहते हैं?', 'जिस क्रिया का प्रभाव कर्म पर पड़े (क्या/किसे का उत्तर मिले), वह ''सकर्मक क्रिया'' होती है।', NOW()) ON CONFLICT DO NOTHING;
