INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0944e7ab-4743-4be0-bc6c-e863e9fce879', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'जिस क्रिया के व्यापार का फल सीधे कर्ता पर ही पड़ता है और जिसमें कर्म नहीं होता (जैसे: ''बच्चा रोता है'', ''पक्षी उड़ते हैं''), उसे क्या कहते हैं?', 'जिसमें कर्म की अपेक्षा न हो और कार्य का प्रभाव कर्ता पर ही सीमित रहे, वह ''अकर्मक क्रिया'' होती है।', NOW()) ON CONFLICT DO NOTHING;
