INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('709727f4-3c9d-4fe4-9a1a-e3379170d37a', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'वाक्य में क्रिया के साथ ''क्या'' या ''किसे/किसको'' लगाकर प्रश्न पूछने पर यदि कोई उत्तर मिलता है, तो वह क्रिया क्या कहलाती है?', '''क्या/किसे'' प्रश्न का सार्थक उत्तर मिलना सकर्मक क्रिया की सबसे सरल व प्रामाणिक पहचान है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77659d66-d9d2-43f0-96d6-e8b0a93ea35a', 'सकर्मक क्रिया (उत्तर मिलने वाला पद ''कर्म'' होता है)', true, '709727f4-3c9d-4fe4-9a1a-e3379170d37a');
