INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46927c17-98b2-4cb7-9ce5-40d6379a155f', 'अव्यय', false, '709727f4-3c9d-4fe4-9a1a-e3379170d37a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea6d7cf8-6e02-4a73-ab0d-22fcb29212e5', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'जिस सकर्मक क्रिया में दो कर्म होते हैं (जैसे: ''अध्यापक ने छात्रों को हिंदी पढ़ाई''), उसे क्या कहते हैं?', 'दो कर्मों (मुख्य कर्म वस्तुवाचक + गौण कर्म प्राणीवाचक) से युक्त क्रिया ''द्विकर्मक क्रिया'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
