INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3dd3db6-b452-4289-b6d9-28a3c9a5e571', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'जब कर्ता स्वयं कार्य न करके किसी अन्य को कार्य करने की प्रेरणा देता है या करवाता है (जैसे: ''माँ नौकरानी से कपड़े धुलवाती है''), तो उस क्रिया को क्या कहते हैं?', 'कर्ता द्वारा किसी अन्य को कार्य में प्रवृत्त कराने वाली क्रिया ''प्रेरणार्थक क्रिया'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
