INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fb171bd8-f3c7-41dd-be4f-f1df71b6f14f', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'संज्ञा, सर्वनाम या विशेषण शब्दों से बनने वाली क्रियाओं (जैसे: ''हाथ'' से हथियाना, ''बात'' से बतियाना, ''शर्म'' से शर्माना, ''गर्म'' से गरमाना) को क्या कहते हैं?', 'संज्ञा/सर्वनाम/विशेषण प्रातिपदिकों में प्रत्यय जोड़कर निर्मित क्रियाएँ ''नामधातु क्रिया'' कहलाती हैं।', NOW()) ON CONFLICT DO NOTHING;
