INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2a7042b0-2386-44df-8e97-7b56442112ab', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'जब दो या दो से अधिक क्रियाएँ मिलकर एक पूर्ण क्रिया बनाती हैं (जैसे: ''वह खाना **खा चुका है**'', ''मोहन **चला गया**''), तो उन्हें क्या कहते हैं?', 'मुख्य क्रिया और रंजक क्रिया के संयोग से गठित क्रिया पद ''संयुक्त क्रिया'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
