INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e17e4551-346a-47b3-829f-0cb3b221565e', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'मुख्य क्रिया से पहले होने वाली क्रिया (जिसमें प्रायः ''कर'' या ''करके'' लगा होता है, जैसे: ''वह **नहाकर** विद्यालय गया'') को क्या कहते हैं?', 'समापिका क्रिया से पूर्व निष्पादित क्रिया ''पूर्वकालिक क्रिया'' कहलाती है (जैसे: पढ़कर, खेलकर, खाकर)।', NOW()) ON CONFLICT DO NOTHING;
