INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d370691-ac81-45be-9598-f0a663ba7605', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Easy', 'मुख्य क्रिया के साथ जुड़कर काल और अर्थ को स्पष्ट करने वाली क्रिया (जैसे: ''है'', ''था'', ''रहा है'', ''होगा'') को क्या कहते हैं?', 'काल और पक्ष की सिद्धि में मुख्य क्रिया की सहायता करने वाले पद ''सहायक क्रिया'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
