INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d44b211-4c1e-420e-a527-08e415ac0003', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'निम्नलिखित में से स्वाभाविक रूप से ''अकर्मक क्रियाओं'' का सही समूह कौन-सा है?', 'शारीरिक स्थितियाँ एवं स्वाभाविक गतियाँ (हँसना, रोना, सोना, दौड़ना) स्वतः अकर्मक क्रियाएँ होती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f649463-1de7-4d1f-9104-5dfcd35da7bf', 'हँसना, रोना, सोना, जागना, उड़ना, तैरना, बैठना, चलना', true, '9d44b211-4c1e-420e-a527-08e415ac0003');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea685bf9-3368-460b-9048-79b3b8ba9fcd', 'पढ़ना, लिखना, खाना, पीना, देखना, बनाना', false, '9d44b211-4c1e-420e-a527-08e415ac0003');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('728759f0-4f5d-4684-baee-9d8a9c26b7a9', 'काटना, धोना, सिलना, बेचना', false, '9d44b211-4c1e-420e-a527-08e415ac0003');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed50eb89-fdd1-4ffe-9037-301127bad051', 'पकाना, सिखाना, दिलाना', false, '9d44b211-4c1e-420e-a527-08e415ac0003');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e36a64c-9d5b-4812-bb4a-b91d1080c1cc', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'प्रेरणार्थक क्रिया के दो रूप (प्रथम प्रेरणार्थक और द्वितीय प्रेरणार्थक) का सही उदाहरण कौन-सा है?', 'प्रथम प्रेरणार्थक में ''-आना'' (पढ़ाना) तथा द्वितीय प्रेरणार्थक में ''-वाना'' (पढ़वाना) प्रत्यय जुड़ता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('788d208c-69ec-4330-bf50-2d876129d809', 'मूल: पढ़ना -> प्रथम: पढ़ाना -> द्वितीय: पढ़वाना', true, '9e36a64c-9d5b-4812-bb4a-b91d1080c1cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2efaf090-803d-44fa-b69a-48de87057ed9', 'मूल: खाना -> प्रथम: खाया -> द्वितीय: खाएगा', false, '9e36a64c-9d5b-4812-bb4a-b91d1080c1cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd7a815e-a3ac-451c-9f9f-67aab1b66f19', 'मूल: चलना -> प्रथम: चला -> द्वितीय: चल', false, '9e36a64c-9d5b-4812-bb4a-b91d1080c1cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('253b0a06-de2b-417b-b913-d02269720aa3', 'मूल: लिखना -> प्रथम: लिखा -> द्वितीय: लेख', false, '9e36a64c-9d5b-4812-bb4a-b91d1080c1cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f82a8c80-26a0-4548-8edd-810f5ab6918c', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'वाक्य में प्रयुक्त दोनों कर्मों की सही पहचान कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8f0d2a8-4cc3-49f1-b92a-6ec134701db0', 'घड़ी = मुख्य कर्म (प्रत्यक्ष/निर्जीव) ; पुत्र = गौण कर्म (अप्रत्यक्ष/सजीव)', true, 'f82a8c80-26a0-4548-8edd-810f5ab6918c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a59e742d-9f05-43b8-9bf6-c60c548e15ff', 'घड़ी = गौण कर्म ; पुत्र = मुख्य कर्म', false, 'f82a8c80-26a0-4548-8edd-810f5ab6918c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b8e87bf-5555-4a8f-ae63-85aecf580766', 'दोनों मुख्य कर्म हैं', false, 'f82a8c80-26a0-4548-8edd-810f5ab6918c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23c55aec-d445-46c0-9652-dedf0a94445a', 'दोनों गौण कर्म हैं', false, 'f82a8c80-26a0-4548-8edd-810f5ab6918c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02cf9144-4283-4829-9297-0342dbdb9700', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'संज्ञा शब्द ''लाठी'' और ''फिल्म'' से बनने वाली सही नामधातु क्रियाएँ क्रमशः क्या हैं?', 'लाठी -> लठियाना; फिल्म -> फिल्माना (नामधातु क्रियाएँ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c215f0b-86d3-4bc3-b91f-ce0394a4f741', 'लठियाना और फिल्माना', true, '02cf9144-4283-4829-9297-0342dbdb9700');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3217a1a0-8a2f-45e6-a3f6-715804985aec', 'लाठना और फिल्मना', false, '02cf9144-4283-4829-9297-0342dbdb9700');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3142059-240a-499c-a105-8f038e5d2a64', 'लाठी चलाना और फिल्म देखना', false, '02cf9144-4283-4829-9297-0342dbdb9700');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6129dec4-9370-454c-9bdf-a57377b8da0c', 'लठैत और फिल्मी', false, '02cf9144-4283-4829-9297-0342dbdb9700');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6fef3ce-e17e-493e-ada1-8ba1a5c49891', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'विशेषण शब्द ''चिकना'' और ''अपना'' (सर्वनाम) से बनने वाली सही नामधातु क्रियाएँ क्या हैं?', 'चिकना (विशेषण) -> चिकनाना; अपना (सर्वनाम) -> अपनाना।', NOW()) ON CONFLICT DO NOTHING;
