INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47c4e79e-2704-468d-8b13-d85513716bc4', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'संयुक्त क्रिया ''रोहन खेलने लगा'' में मुख्य क्रिया और रंजक (सहायक) क्रिया कौन-सी है?', '''खेलने'' मुख्य अर्थ दे रहा है, और ''लगा'' क्रिया के आरंभ होने का रंजक अर्थ जोड़ रहा है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8da9f005-155a-4afc-b7a0-cee36e43f0fd', '''खेलने'' = मुख्य क्रिया ; ''लगा'' = रंजक/सहायक क्रिया', true, '47c4e79e-2704-468d-8b13-d85513716bc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8877da3a-94d8-453a-9519-bd55ff22a767', '''लगा'' = मुख्य क्रिया ; ''खेलने'' = सहायक', false, '47c4e79e-2704-468d-8b13-d85513716bc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6eb42e21-4f98-49ea-a170-1224b14be59a', 'दोनों मुख्य क्रियाएँ हैं', false, '47c4e79e-2704-468d-8b13-d85513716bc4');
