INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d356e42f-25b0-42f1-9ce2-d354d191c68a', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'वाक्य में प्रयुक्त क्रिया का लिंग और वचन किसके अनुसार निर्धारित होता है?', 'कर्तृप्रयोग में क्रिया कर्ता के अनुसार और कर्मणिप्रयोग (जैसे ''राम ने रोटी खाई'') में कर्म के अनुसार प्रयुक्त होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d75f7df1-096d-4e37-9812-c0f93a535040', 'सामान्यतः कर्ता के लिंग-वचन के अनुसार ; किन्तु कर्मवाच्य में अथवा कर्ता के साथ ''ने'' परसर्ग होने पर कर्म के लिंग-वचन के अनुसार', true, 'd356e42f-25b0-42f1-9ce2-d354d191c68a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72b1a250-1d4d-4397-9ebf-f43c23dad7de', 'हमेशा केवल विशेषण के अनुसार', false, 'd356e42f-25b0-42f1-9ce2-d354d191c68a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2eed15d-daa2-43f0-b959-9cd0dc84991e', 'हमेशा केवल क्रियाविशेषण के अनुसार', false, 'd356e42f-25b0-42f1-9ce2-d354d191c68a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13e35738-07c4-4e7f-90d2-1dd7d9e95322', 'क्रिया का कोई लिंग-वचन नहीं होता', false, 'd356e42f-25b0-42f1-9ce2-d354d191c68a');
