INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5a02f33-290c-482b-8573-a0177712f9cf', 'गाया (कर्म ''गीत'' पुल्लिंग एकवचन है, अतः क्रिया ''गाया'' होगी)', true, 'dce925d7-5d85-458e-9152-1f61725a1e16');
