INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd6235b9-e539-4fad-863c-f5fd3c6003d5', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'अनुकरणात्मक धातुओं (ध्वनियों के अनुकरण से बनने वाली क्रियाएँ) का सही उदाहरण कौन-सा है?', 'ध्वनि के अनुकरण पर गढ़ी गई धातुएँ अनुकरणात्मक नामधातु क्रियाएँ कहलाती हैं (खटखट -> खटखटाना)।', NOW()) ON CONFLICT DO NOTHING;
