INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b64afacb-969b-41d0-b60b-83f6a3b77cfe', 'पढ़ना और लिखना', false, 'fd6235b9-e539-4fad-863c-f5fd3c6003d5');
