INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf60968e-6882-4a01-814c-e3a9d16c14e2', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'मूल धातु ''हँसना'' का प्रथम और द्वितीय प्रेरणार्थक रूप क्या होगा?', 'हँसना -> हँसाना -> हँसवाना।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('951f70bb-ad8e-41af-90cc-fc7915d1dc84', 'हँसाना (प्रथम) और हँसवाना (द्वितीय)', true, 'cf60968e-6882-4a01-814c-e3a9d16c14e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3155f983-f850-4296-a69e-da9e3f2bdcef', 'हँसा और हँसाया', false, 'cf60968e-6882-4a01-814c-e3a9d16c14e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('503d2c12-5f43-4e64-bbd6-0f14e150071a', 'हँसी और हँसमुख', false, 'cf60968e-6882-4a01-814c-e3a9d16c14e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20a87b3b-cfcd-4341-a327-ac325260bc36', 'हँसता और हँसेगा', false, 'cf60968e-6882-4a01-814c-e3a9d16c14e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db5c6f9f-d515-46ae-bc8c-76ef4fc0771f', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Medium', 'वाक्य में प्रयुक्त रेखांकित पद का क्रिया भेद बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0223cedd-e4e5-49f4-9834-6faa69c9ddca', 'अकर्मक संयुक्त क्रिया (डूबना + जाना)', true, 'db5c6f9f-d515-46ae-bc8c-76ef4fc0771f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15e47577-397e-41aa-be67-14f196f710ba', 'सकर्मक क्रिया', false, 'db5c6f9f-d515-46ae-bc8c-76ef4fc0771f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36f42cd2-20c7-4ad7-921e-8b12a4154167', 'प्रेरणार्थक क्रिया', false, 'db5c6f9f-d515-46ae-bc8c-76ef4fc0771f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7b37caa-9721-4aa4-b08e-d451fe330dd3', 'नामधातु क्रिया', false, 'db5c6f9f-d515-46ae-bc8c-76ef4fc0771f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6a57a7f-5e60-4ac0-83eb-1b75315579d5', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9b9c03a-d6d7-4b14-b5c5-6464409c99a8', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'd6a57a7f-5e60-4ac0-83eb-1b75315579d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29b65771-8308-4baf-84f8-007ba31ee59c', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'd6a57a7f-5e60-4ac0-83eb-1b75315579d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d747514-1f6e-4f39-8190-4cccc21647e5', '(A) सही है, परन्तु (R) गलत है।', false, 'd6a57a7f-5e60-4ac0-83eb-1b75315579d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d277b75b-7bc2-4cfb-ba7f-d62c9c937cdf', '(A) गलत है, परन्तु (R) सही है।', false, 'd6a57a7f-5e60-4ac0-83eb-1b75315579d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7bb699b-110a-4211-a3d3-154714d13364', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'Spot the IMPOSTER in the following group of क्रिया और उनके भेदों के युग्म में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54743efa-da3a-462a-9f43-a881e087c6f3', 'पढ़ना - सकर्मक', false, 'd7bb699b-110a-4211-a3d3-154714d13364');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fd04151-0b3b-4464-b0e6-16da89cfcc2d', 'हँसना - अकर्मक', false, 'd7bb699b-110a-4211-a3d3-154714d13364');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b4047ee-69dc-4a29-8a6e-1c2207534428', 'लिखना - सकर्मक', false, 'd7bb699b-110a-4211-a3d3-154714d13364');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('718be74d-92e8-4337-a720-52756317b288', 'सोना - सकर्मक', true, 'd7bb699b-110a-4211-a3d3-154714d13364');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b1ca79d5-74b1-4f43-a8db-2d00f678e515', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'सुमेलित कीजिए (क्रिया के रूप और उनके व्याकरणिक भेद):
(क) हथियाना   -> (i) पूर्वकालिक क्रिया
(ख) पिलवाना    -> (ii) नामधातु क्रिया
(ग) खाकर      -> (iii) संयुक्त क्रिया
(घ) चल पड़ा   -> (iv) द्वितीय प्रेरणार्थक क्रिया', 'हथियाना = नामधातु; पिलवाना = द्वितीय प्रेरणार्थक; खाकर = पूर्वकालिक; चल पड़ा = संयुक्त क्रिया।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06842e48-e1f1-4ff3-a7e5-b427166a6b17', 'क-(ii), ख-(iv), ग-(i), घ-(iii)', true, 'b1ca79d5-74b1-4f43-a8db-2d00f678e515');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10f6d964-ec6c-40ec-bbab-f83a9e5db546', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, 'b1ca79d5-74b1-4f43-a8db-2d00f678e515');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cc8c6cc-0880-4a19-9e1d-2497f0ae4797', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, 'b1ca79d5-74b1-4f43-a8db-2d00f678e515');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a6b9dc8-5cf9-4ee2-adf6-0f02b8bb2742', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, 'b1ca79d5-74b1-4f43-a8db-2d00f678e515');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('384e83e8-2464-4bb3-abf7-ba46919078ee', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'सजातीय क्रिया (Cognate Verb) का सही उदाहरण कौन-सा है?', 'जब कर्म और क्रिया दोनों एक ही मूल धातु से व्युत्पन्न हों (जैसे: लड़ाई लड़ी, चाल चली), तो उसे ''सजातीय क्रिया'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd1894d0-0af7-421b-9c5b-ffb205001614', 'भारत ने पाकिस्तान के विरुद्ध **शानदार लड़ाई लड़ी**। (कर्म ''लड़ाई'' और क्रिया ''लड़ी'' एक ही ''लड़'' धातु से बने हैं)', true, '384e83e8-2464-4bb3-abf7-ba46919078ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f71fb83-922e-462a-880f-fb5c3f5f9072', 'उसने पानी पिया।', false, '384e83e8-2464-4bb3-abf7-ba46919078ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02434b0f-c124-4a60-b5cd-514c9d2a973f', 'वह घर गया।', false, '384e83e8-2464-4bb3-abf7-ba46919078ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fddebf1d-694a-4c78-b7c2-a4bd6944c080', 'बच्चा खेल रहा है।', false, '384e83e8-2464-4bb3-abf7-ba46919078ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03c60a97-e8be-453f-921e-c388bc0ed88a', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'कृदंत क्रिया (Participle Verb) और तद्धित में क्या अंतर है?', 'धातु + प्रत्यय = कृदंत (लिखकर, पढ़ता, दौड़ा); संज्ञा/सर्वनाम + प्रत्यय = तद्धित/नामधातु।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41a63096-af39-44f3-9971-3c592373f6e9', 'धातुओं (क्रिया मूलों) में प्रत्यय जुड़ने से बनने वाले क्रिया रूप ''कृदंत'' कहलाते हैं (जैसे: लिख + ता = लिखता) ; जबकि संज्ञा/सर्वनाम/विशेषण से बनने वाले रूप ''तद्धित'' कहलाते हैं', true, '03c60a97-e8be-453f-921e-c388bc0ed88a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edffe932-8d8e-49c4-b6f0-d655cf2cf283', 'कृदंत केवल अव्यय होते हैं', false, '03c60a97-e8be-453f-921e-c388bc0ed88a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77b6a2aa-617e-4f96-a3f6-01f41384a1c2', 'तद्धित में धातु होती है', false, '03c60a97-e8be-453f-921e-c388bc0ed88a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5dc6e03-0cc5-44ff-83cf-0a67ecdad62c', 'दोनों में कोई अंतर नहीं है', false, '03c60a97-e8be-453f-921e-c388bc0ed88a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4ca8454-ce38-415a-801e-297ec5f8abe4', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'निम्नलिखित वाक्यों में से किस वाक्य में ''अकर्मक क्रिया'' प्रयुक्त हुई है?', '''सो रहा है'' अकर्मक क्रिया है; शेष तीनों वाक्यों में कर्म (सड़क, निबंध, खाना) उपस्थित हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61c1f5fa-428e-44fd-a146-bc6a84e5e048', '''मजदूर दिन भर से पसीना बहाकर **सो रहा है**।''', true, 'd4ca8454-ce38-415a-801e-297ec5f8abe4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c518e68-850c-40dd-9cc8-c454578adf08', '''मजदूर सड़क बना रहा है।''', false, 'd4ca8454-ce38-415a-801e-297ec5f8abe4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6748942-2e48-4de6-87d9-3341b0efa749', '''छात्र निबंध लिख रहा है।''', false, 'd4ca8454-ce38-415a-801e-297ec5f8abe4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c42c7e34-2218-4258-bfcd-c7877451862d', '''रसोइया खाना पका रहा है।''', false, 'd4ca8454-ce38-415a-801e-297ec5f8abe4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a1089881-1320-4ef4-a933-68679c5a6904', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'तात्कालिक कृदंत क्रिया का सही उदाहरण कौन-सा है?', 'धातु + ''ते ही'' लगकर तत्क्षण दूसरी क्रिया का संपादन सूचित करने वाली क्रिया ''तात्कालिक कृदंत'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a3e52ef-b661-4344-a16e-3fcec6478739', '''शेर को **देखते ही** शिकारी भाग गया।'' (''देखते ही'' एक क्रिया के तुरंत बाद दूसरी क्रिया का बोध कराती है)', true, 'a1089881-1320-4ef4-a933-68679c5a6904');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52f105d1-fcc4-4159-95d6-da569d6d81a0', '''वह पढ़कर सोया।''', false, 'a1089881-1320-4ef4-a933-68679c5a6904');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3243cb85-8ef5-4a8e-8871-dd6bcc4ff5bf', '''वह गाना गाता है।''', false, 'a1089881-1320-4ef4-a933-68679c5a6904');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20892ab1-a879-4182-ae2f-009bbcee32f2', '''वह चला गया।''', false, 'a1089881-1320-4ef4-a933-68679c5a6904');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55de7abf-23e5-442a-a044-99f53af55ea5', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'वाक्य में प्रयुक्त रेखांकित पद का व्याकरणिक परिचय दीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea237725-caef-4583-9ee8-b98e0e5f8a4f', 'प्रेरणार्थक सकर्मक क्रिया (कर्म = ''भोजन'')', true, '55de7abf-23e5-442a-a044-99f53af55ea5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1637fa4b-8090-4166-9cbe-d251b834d43e', 'अकर्मक क्रिया', false, '55de7abf-23e5-442a-a044-99f53af55ea5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5e2bd34-4bdd-4b07-a2d4-c331f114d5fc', 'पूर्वकालिक क्रिया', false, '55de7abf-23e5-442a-a044-99f53af55ea5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b30a980d-bcdb-4414-8bb2-b19107eb430c', 'नामधातु क्रिया', false, '55de7abf-23e5-442a-a044-99f53af55ea5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d404c176-bb3f-4790-bb44-6bf65f14a347', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'अकर्मक धातुओं को सकर्मक धातुओं में बदलने का सही नियम कौन-सा है?', 'अकर्मक धातुओं में आ/वा प्रत्यय जोड़कर या आदि स्वर दीर्घ करके सकर्मक क्रिया बनाई जाती है (कटना -> काटना, गिरना -> गिराना)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8172b7d9-0146-44c5-99b6-a3184d630768', 'हँसना (अकर्मक) -> हँसाना (सकर्मक) ; गिरना (अकर्मक) -> गिराना (सकर्मक) ; कटना (अकर्मक) -> काटना (सकर्मक)', true, 'd404c176-bb3f-4790-bb44-6bf65f14a347');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48a3b8a1-157a-4b36-b627-c4c35fca16fc', 'केवल ''ना'' हटाकर', false, 'd404c176-bb3f-4790-bb44-6bf65f14a347');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ecb77d0-095a-48c1-a482-7941f8161e4c', 'केवल विसर्ग लगाकर', false, 'd404c176-bb3f-4790-bb44-6bf65f14a347');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53ae3109-80c3-4490-ae49-525fb05b5f26', 'अकर्मक को कभी सकर्मक नहीं बनाया जा सकता', false, 'd404c176-bb3f-4790-bb44-6bf65f14a347');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66b682e0-15db-483f-92d5-39ec96acfc06', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'संयुक्त क्रिया के मुख्य 11 अर्थगत भेदों में से ''आरंभबोधक'' और ''समाप्तिबोधक'' का सही युग्म कौन-सा है?', '''धातु + लगना'' = आरंभबोधक (हँसने लगा); ''धातु + चुकना'' = समाप्तिबोधक (पढ़ चुका)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c501570-7b37-4b67-b103-7745a0ba1bb0', '''वह **गाने लगा**'' (आरंभबोधक) और ''वह **खा चुका**'' (समाप्तिबोधक)', true, '66b682e0-15db-483f-92d5-39ec96acfc06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51434577-b0b7-4fb2-bfdc-0a6425095c76', '''वह जा सकता है'' और ''वह गया''', false, '66b682e0-15db-483f-92d5-39ec96acfc06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('137bd9bf-6def-45ff-8e27-26e382e1b3bb', '''वह खेला'' और ''वह दौड़ा''', false, '66b682e0-15db-483f-92d5-39ec96acfc06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79b49782-965b-4741-a257-80220e283a46', '''पढ़ना'' और ''लिखना''', false, '66b682e0-15db-483f-92d5-39ec96acfc06');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d79163e-6d20-414b-b0aa-0e4d03942b44', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'वाक्य को क्रिया की दृष्टि से मानक रूप में शुद्ध कीजिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb519850-1bf3-4cd1-91c5-ec30ed745755', '''मेरे चाचा जी आए हैं, वे कल जाएँगे।'' (आदरार्थक बहुवचन कर्ता के साथ क्रिया बहुवचन ''जाएँगे'' होगी)', true, '8d79163e-6d20-414b-b0aa-0e4d03942b44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc5f3eb8-6dc8-47b8-b968-af066c5ac385', 'मेरे चाचा जी आया है, वह जाएगा।', false, '8d79163e-6d20-414b-b0aa-0e4d03942b44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d132a7b7-3acc-489a-a6a0-1d98dae213ae', 'चाचा जी आया, जाएगा कल।', false, '8d79163e-6d20-414b-b0aa-0e4d03942b44');
