INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8781f8f1-8682-455d-b407-41e6b61b9824', 'Class 6', 'Hindi Grammar', 'Chapter 10: क्रिया', 'Hard', 'क्रिया का वाक्य में क्या सर्वोच्च महत्व होता है?', 'क्रिया वाक्य का अनिवार्य विधेय तत्व है, जिसके बिना वाक्य की विचार-अभिव्यक्ति असंभव है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4f19026-76c4-447e-adb2-bd9d95d210a2', 'क्रिया वाक्य का अनिवार्य केंद्र (हृदय) होती है; बिना क्रिया के कोई भी सार्थक वाक्य पूर्ण नहीं हो सकता', true, '8781f8f1-8682-455d-b407-41e6b61b9824');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcd9c301-51f3-4732-8c1e-3fe8a038ad7e', 'क्रिया केवल कविता में उपयोगी है', false, '8781f8f1-8682-455d-b407-41e6b61b9824');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7a602dd-11da-460a-8acf-8471dae43f78', 'क्रिया के बिना भी वाक्य पूरे अर्थ दे सकते हैं', false, '8781f8f1-8682-455d-b407-41e6b61b9824');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5882860-1495-4de1-a697-fb8ebb8fb9cb', 'क्रिया केवल काल बताती है और कुछ नहीं', false, '8781f8f1-8682-455d-b407-41e6b61b9824');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf43e3c3-9bb7-42a2-9eba-f4b885f87678', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'What is the thick protective blanket/envelope of air surrounding the entire Earth called?', 'The atmosphere is the multi-layered gaseous envelope retained by Earth''s gravity extending hundreds of kilometres.', NOW()) ON CONFLICT DO NOTHING;
