INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('400c5ca8-b8dc-4ead-9553-0bed7302ffbd', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'Air in motion (moving air) is commonly called:', 'Moving air created by atmospheric pressure gradients is termed wind (or breeze).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5012d03f-8816-4c2e-a697-44990feed33a', 'Wind', true, '400c5ca8-b8dc-4ead-9553-0bed7302ffbd');
