INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac809c2a-dc63-40a7-a0d2-6a6ab4553298', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'Which gas is the MOST ABUNDANT in atmospheric air, making up approximately 78% (nearly 4/5ths) of air volume?', 'Nitrogen comprises ~78% of the dry atmosphere, acting as an unreactive diluent that tempers rapid combustion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ab5107b-73ef-44b8-a146-03369888389f', 'Nitrogen (N₂)', true, 'ac809c2a-dc63-40a7-a0d2-6a6ab4553298');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8af06a30-d38c-4dd1-9837-c105eef5b35f', 'Oxygen (O₂)', false, 'ac809c2a-dc63-40a7-a0d2-6a6ab4553298');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af8064d8-8b30-4e27-8e84-6ff9a5e3a1fb', 'Carbon dioxide (CO₂)', false, 'ac809c2a-dc63-40a7-a0d2-6a6ab4553298');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a580de1a-7d95-413d-bb8e-4fc9ed5926b3', 'Argon', false, 'ac809c2a-dc63-40a7-a0d2-6a6ab4553298');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18c70c0d-8906-41da-b3af-6d26f66ac7a3', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'Which essential gas constitutes approximately 21% (nearly 1/5th) of air volume and supports animal respiration and fire combustion?', 'Oxygen makes up ~21% of clean air, essential for cellular aerobic respiration and chemical combustion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b743e2d-239a-43b2-879e-642ad1ed1629', 'Oxygen (O₂)', true, '18c70c0d-8906-41da-b3af-6d26f66ac7a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b7930e7-6bd8-4ec9-ab27-b91df3d601b3', 'Nitrogen', false, '18c70c0d-8906-41da-b3af-6d26f66ac7a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2fef464-927e-4cfb-8d2a-9394e04151e7', 'Carbon dioxide', false, '18c70c0d-8906-41da-b3af-6d26f66ac7a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d9e7e66-226f-4473-aed1-b83d9f0b8baf', 'Hydrogen', false, '18c70c0d-8906-41da-b3af-6d26f66ac7a3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6965944-e545-4c0a-a55e-a1b0d0a9b0e4', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'What happens when a burning candle is covered with an inverted glass tumbler?', 'Combustion requires continuous oxygen; once the enclosed oxygen is depleted, the flame extinguishes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75f25920-005c-486a-bc54-81ae78394641', 'The candle flickers and goes out after a few moments because the limited oxygen inside the glass gets consumed completely', true, 'e6965944-e545-4c0a-a55e-a1b0d0a9b0e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a53c271-e5f4-4cd9-b785-118e45f8f845', 'The candle burns twice as brightly', false, 'e6965944-e545-4c0a-a55e-a1b0d0a9b0e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25bb283c-4d91-4760-9835-9aed6df7b4f1', 'The glass tumbler melts instantly', false, 'e6965944-e545-4c0a-a55e-a1b0d0a9b0e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('704f4e93-acf3-4133-8493-693138170842', 'The candle turns into ice', false, 'e6965944-e545-4c0a-a55e-a1b0d0a9b0e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('137f0d60-be4f-4528-8985-45e687e64a7c', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'Which component of air is responsible for the formation of clouds, mist, dew, and rain in nature?', 'Atmospheric water vapour evaporates from oceans/rivers and condenses at high altitudes to form cloud droplets and rain.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8087318b-4a07-44c5-af43-21ccc90b2ac9', 'Water Vapour (Moisture)', true, '137f0d60-be4f-4528-8985-45e687e64a7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b47589d9-d69c-4060-af89-d4294c39fd75', 'Nitrogen', false, '137f0d60-be4f-4528-8985-45e687e64a7c');
