INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d0fbe70-92aa-4d85-b352-0cab28515935', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'What gas is produced during burning of fuels and animal respiration, and used by green plants for photosynthesis?', 'Carbon dioxide (~0.04% of air) is released by respiration/combustion and absorbed by plants during photosynthesis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fe1b286-362e-4923-ab36-cbbbb32911f7', 'Carbon Dioxide (CO₂)', true, '1d0fbe70-92aa-4d85-b352-0cab28515935');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c60b2116-3d66-4903-a097-0fb46d25abb4', 'Oxygen', false, '1d0fbe70-92aa-4d85-b352-0cab28515935');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6aecbddf-7607-4411-9001-482d9612bb3e', 'Nitrogen', false, '1d0fbe70-92aa-4d85-b352-0cab28515935');
