INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('24bf6602-0df5-48bf-b2bd-ed49036fcf4d', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'Why do mountaineers climbing very high Himalayan peaks carry heavy Oxygen Cylinders on their backs?', 'Atmospheric pressure and oxygen partial pressure decline with altitude, causing hypoxia without supplementary O₂.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ab1e9e0-f421-4132-9fda-7ec2fd806652', 'Because atmospheric air becomes progressively thinner and the density/availability of oxygen drops drastically at high altitudes', true, '24bf6602-0df5-48bf-b2bd-ed49036fcf4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e89a342-01ad-4130-82cf-118370aa16be', 'To protect from bears', false, '24bf6602-0df5-48bf-b2bd-ed49036fcf4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('064b6a4a-7064-4fda-ba86-2089afb9cf1a', 'To cook food on snow', false, '24bf6602-0df5-48bf-b2bd-ed49036fcf4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c5c90a4-5b8c-4863-bc76-ce53e0442df0', 'To make the backpack heavier for balance', false, '24bf6602-0df5-48bf-b2bd-ed49036fcf4d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('daa605a5-daaf-44eb-a762-3cb448a35cc5', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'How do fish and other aquatic animals breathe underwater?', 'Fish pass oxygenated water over vascularized gill filaments, extracting dissolved O₂ via counter-current exchange.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26d6e5ae-adfb-4540-ad98-952751f5219c', 'They absorb Dissolved Oxygen from water through their specialized feather-like Gills', true, 'daa605a5-daaf-44eb-a762-3cb448a35cc5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02db2d7f-313e-4306-ab74-d15d1ac44a2b', 'They hold their breath forever', false, 'daa605a5-daaf-44eb-a762-3cb448a35cc5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83442227-d385-4fe3-b1e9-5125917a5fb0', 'They breathe water vapour from clouds', false, 'daa605a5-daaf-44eb-a762-3cb448a35cc5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92ebbc45-3ed3-468e-9b48-eefc123670f5', 'They eat oxygen rocks', false, 'daa605a5-daaf-44eb-a762-3cb448a35cc5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03f8e884-e34a-4303-85be-32f442220e13', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'Why do Earthworms and burrowing soil animals come out of their underground burrows to the surface only during HEAVY RAINFALL?', 'Waterlogged soils displace pore air; earthworms must surface to respire cutaneously across moist skin.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c719171-0240-4824-b9f7-31452e924837', 'Heavy rainwater fills up all air spaces and pores in the soil, forcing earthworms to the surface to breathe oxygen', true, '03f8e884-e34a-4303-85be-32f442220e13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af1823bd-a681-4150-8e22-11d412f7036f', 'Because they like to swim in puddles', false, '03f8e884-e34a-4303-85be-32f442220e13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('810dc352-f439-4638-9000-5822d788ff78', 'To wash their bodies', false, '03f8e884-e34a-4303-85be-32f442220e13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ae56a32-037f-4d4f-bfd3-31039b0fd79d', 'Because soil becomes too hot', false, '03f8e884-e34a-4303-85be-32f442220e13');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a34ce207-ca04-4c04-9da5-ebd5d1d1dc33', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'What is a simple rotating paper toy on a stick that spins furiously when you run with it or blow on it?', 'A firki rotates due to kinetic wind pressure against its angled vanes, demonstrating that air exerts mechanical force.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf97a8bf-788b-43fc-9773-225691f0cdf8', 'Firki (Pinwheel)', true, 'a34ce207-ca04-4c04-9da5-ebd5d1d1dc33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ea34401-dd32-47ad-976f-63832214d8f0', 'Kite', false, 'a34ce207-ca04-4c04-9da5-ebd5d1d1dc33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1e60ac0-340d-49f8-9c76-6b6201fb7e8d', 'Compass', false, 'a34ce207-ca04-4c04-9da5-ebd5d1d1dc33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a69bd783-a397-482b-b901-905a3440b9b5', 'Sundial', false, 'a34ce207-ca04-4c04-9da5-ebd5d1d1dc33');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fbff8dc2-631d-4bf2-9e12-58773510fbf0', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Easy', 'What large mechanical structure with rotating blades harnesses wind energy to pump water, grind grain, or generate clean electricity?', 'Windmills convert atmospheric wind kinetic energy into rotational mechanical and electrical power.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7509206f-6c99-4983-ba64-4bae91f7ce00', 'Windmill (Wind Turbine)', true, 'fbff8dc2-631d-4bf2-9e12-58773510fbf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26242cdb-f603-4548-b27b-3727f3406b4e', 'Waterwheel', false, 'fbff8dc2-631d-4bf2-9e12-58773510fbf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38b4f0a3-a80c-461b-b970-a805420398bb', 'Steam Engine', false, 'fbff8dc2-631d-4bf2-9e12-58773510fbf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53e8cca0-fa78-4c55-adbe-07b3475e5326', 'Solar Panel', false, 'fbff8dc2-631d-4bf2-9e12-58773510fbf0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d890e81-4fa3-4bdd-97ac-6f4643e1bd5a', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'How can you prove experimentally that an apparently ''empty'' open glass bottle is actually FULL of air?', 'Trapped air exerts internal pressure blocking water entry until tilting lets air bubble out, proving air occupies volume.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('864a23a9-0281-4998-801a-4c373b72f8d2', 'Invert the bottle vertically into a bucket of water; water cannot enter until you tilt the bottle slightly, allowing air bubbles to escape with a gurgling sound', true, '0d890e81-4fa3-4bdd-97ac-6f4643e1bd5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71b4036d-fbb3-47b2-a3e0-497b39866954', 'By looking through the glass with sunglasses', false, '0d890e81-4fa3-4bdd-97ac-6f4643e1bd5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcf88bdc-c40a-4592-8d0d-5e363633957d', 'By smelling the bottle', false, '0d890e81-4fa3-4bdd-97ac-6f4643e1bd5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d7ed349-919b-4c31-aeae-4d3d1e9b0496', 'By dropping the bottle on the floor', false, '0d890e81-4fa3-4bdd-97ac-6f4643e1bd5a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59d0bf4e-30c1-4f4f-ba42-052b8b5b74f1', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why does a lump of dry soil produce fizzing bubbles when dropped into a glass beaker of water?', 'Capillary suction of water displaces interstitial soil air, generating effervescent bubbles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a39586f0-9dd5-4228-aca1-ee2de101c826', 'Water enters the microscopic pores of the dry soil, displacing the air trapped inside soil particles which escapes upward as visible bubbles', true, '59d0bf4e-30c1-4f4f-ba42-052b8b5b74f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43de9748-18f4-460a-87c3-201a7b881ea6', 'Because soil is boiling hot', false, '59d0bf4e-30c1-4f4f-ba42-052b8b5b74f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed021427-03c4-4a36-b637-aef1b21612ad', 'Because soil reacts with water chemically to make poison', false, '59d0bf4e-30c1-4f4f-ba42-052b8b5b74f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7340ab8-39d0-471c-9001-207adf156af6', 'Because soil has soap in it', false, '59d0bf4e-30c1-4f4f-ba42-052b8b5b74f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e843b21e-9ad4-4741-8c63-e1a3bf07cd49', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why do tiny water droplets appear on the outer glass surface of a tumbler containing ice-cold water?', 'Ambient water vapour cools below its dew point against cold glass, condensing into liquid droplets.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('793139e9-8b02-4931-a781-0d2a3b3df453', 'Water vapour present in the surrounding air comes in contact with the cold glass surface and CONDENSES into liquid water droplets', true, 'e843b21e-9ad4-4741-8c63-e1a3bf07cd49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99ec31ef-0627-4dad-8466-126e038bb66d', 'Water leaks through the solid glass wall', false, 'e843b21e-9ad4-4741-8c63-e1a3bf07cd49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77d38d12-4171-4c5a-a7ed-9b24615fb22f', 'Ice melts through the top', false, 'e843b21e-9ad4-4741-8c63-e1a3bf07cd49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e02fcb99-70bc-4ec4-993b-b06813b6eab6', 'The glass tumbler sweats like skin', false, 'e843b21e-9ad4-4741-8c63-e1a3bf07cd49');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c015a0cb-53e8-4d73-bfbd-a46e1d190baf', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'How is the delicate balance of Oxygen and Carbon Dioxide maintained in Earth''s atmosphere?', 'Photosynthetic O₂ release by plants balances respiration and combustion CO₂ emissions across the biosphere.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92fb0244-8581-4eb1-b3cf-c1a48ecc56e4', 'Plants produce excess Oxygen during daytime Photosynthesis and consume Carbon Dioxide, while animals and humans inhale Oxygen and exhale Carbon Dioxide (Oxygen-Carbon Dioxide Cycle)', true, 'c015a0cb-53e8-4d73-bfbd-a46e1d190baf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d41e5e8-ccdb-42b4-a04d-41ea66133d51', 'Volcanoes pump oxygen into the sky', false, 'c015a0cb-53e8-4d73-bfbd-a46e1d190baf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75894321-1b99-4bcc-b613-1f919ede59ee', 'Windmills manufacture oxygen', false, 'c015a0cb-53e8-4d73-bfbd-a46e1d190baf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4e7ecd9-440c-46ae-b0bf-a05efffcdd15', 'Oxygen comes from the moon', false, 'c015a0cb-53e8-4d73-bfbd-a46e1d190baf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da7edd3c-62a6-46f2-9a7c-f722501a0f84', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why are tall chimneys installed in factories and industrial plants?', 'High stack chimneys disperse industrial effluents into higher atmospheric winds, reducing ground-level pollution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72f763f3-763d-41a3-a17c-736d174cf5fa', 'To release harmful smoke, dust, and toxic fumes high up into the upper atmosphere, away from ground-level human habitats', true, 'da7edd3c-62a6-46f2-9a7c-f722501a0f84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f72b34bf-00eb-4de0-9008-5c7966c51940', 'To catch birds', false, 'da7edd3c-62a6-46f2-9a7c-f722501a0f84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d965ef87-82f9-439e-bd01-1c3e6f58d81a', 'To make rain fall faster', false, 'da7edd3c-62a6-46f2-9a7c-f722501a0f84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75ea9583-4253-498e-89a1-70428fa9e134', 'To make the factory look taller', false, 'da7edd3c-62a6-46f2-9a7c-f722501a0f84');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7cf639b-d31e-4b33-8748-c227b61465c2', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why do we see tiny dancing, glittering dust particles in a dark room when a narrow beam of sunlight enters through a small slit?', 'Tyndall scattering by aerosolized particulate matter illuminates suspended dust in colloidal air.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa3f6059-ade1-4b98-b961-42d3d19a5cc4', 'The sunbeam illuminates microscopic solid Dust particles suspended in air, which scatter light (Tyndall Effect / Brownian motion)', true, 'c7cf639b-d31e-4b33-8748-c227b61465c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5814291-8f70-402f-9c06-b8f389e69502', 'They are tiny flying insects', false, 'c7cf639b-d31e-4b33-8748-c227b61465c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb667e92-0fef-4ff0-b5dd-05cc0770bf28', 'The sun rays are breaking into pieces', false, 'c7cf639b-d31e-4b33-8748-c227b61465c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('584dafb2-bba2-4be8-a39d-10b7bcc69745', 'They are magic sparks', false, 'c7cf639b-d31e-4b33-8748-c227b61465c2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e998e346-504d-4a00-b5e8-a434ad00198a', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why is it strictly recommended to breathe through the NOSE rather than through the MOUTH?', 'Nasal turbinates and mucociliary clearance humidify, warm, and filter airborne aerosols before reaching alveolar lungs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bfbdc62-1a7c-4a7e-be66-1a1556216263', 'Fine hairs (cilia) and sticky mucus lining inside nasal passages filter out dust particles, pollen, and microbes, preventing them from entering the lungs', true, 'e998e346-504d-4a00-b5e8-a434ad00198a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e2a0e11-a62c-46de-9c00-0b3da51bad4d', 'Because mouth breathing makes you thirsty', false, 'e998e346-504d-4a00-b5e8-a434ad00198a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3d860e1-977f-4480-8579-01a470fbcc3d', 'Because mouth has no teeth for air', false, 'e998e346-504d-4a00-b5e8-a434ad00198a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2cb2bf8-8835-43ee-9268-018ece256609', 'Because nose makes air colder', false, 'e998e346-504d-4a00-b5e8-a434ad00198a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1f7c61e9-7740-414b-9a40-db28a7284e9c', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'What instrument is installed on top of tall buildings to indicate the DIRECTION from which the wind is blowing?', 'A wind vane rotates freely on a vertical axis; its tail fin orients the pointer into the wind source direction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d77c7667-baf4-46f1-a053-35fd734879ea', 'Wind Vane (Weather Vane)', true, '1f7c61e9-7740-414b-9a40-db28a7284e9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecf3c31b-eb58-4c75-a687-0acc88d2ce44', 'Anemometer', false, '1f7c61e9-7740-414b-9a40-db28a7284e9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2b989c9-6850-4943-bffc-605a33080e28', 'Barometer', false, '1f7c61e9-7740-414b-9a40-db28a7284e9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0415eead-3d5e-48fc-bc81-7bbd2b77a922', 'Hygrometer', false, '1f7c61e9-7740-414b-9a40-db28a7284e9c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('691db242-2e8e-491c-965c-06ffc9c20e9d', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'How do plant seeds (like Dandelion, Maple, and Drumstick) disperse across vast distances?', 'Anemochory: aerodynamic samaras and pappus hairs utilize wind drift for long-distance seed dispersal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d425fde-213d-4308-9f1d-c509042bf4de', 'They possess feather-like tufts, parachutes, or wings that catch atmospheric wind currents and float across kilometres', true, '691db242-2e8e-491c-965c-06ffc9c20e9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e551e74-9e00-495f-a67c-c76d33f9f580', 'They swim across oceans', false, '691db242-2e8e-491c-965c-06ffc9c20e9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0f92807-9491-4a46-8494-a2b5f522b183', 'They walk on tiny roots', false, '691db242-2e8e-491c-965c-06ffc9c20e9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dffa592-5f7b-489f-ae5a-86b34d3e2ac0', 'They explode like fireworks', false, '691db242-2e8e-491c-965c-06ffc9c20e9d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa8411cb-074b-4763-ad79-570b50342532', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'What role does air play in the transmission of SOUND from one place to another?', 'Mechanical sound waves require molecular compression and rarefaction across an elastic fluid medium like air.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32ffc1d5-589e-4956-8e76-6b4504d8e354', 'Air provides the physical material medium through which sound pressure waves propagate; sound cannot travel through a vacuum', true, 'fa8411cb-074b-4763-ad79-570b50342532');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98544ce9-db56-4ca1-bb97-422f3bc5239c', 'Air blocks all sounds', false, 'fa8411cb-074b-4763-ad79-570b50342532');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('158be81f-e47e-48d5-8ed8-82c10c0f0e9c', 'Air creates sound out of light', false, 'fa8411cb-074b-4763-ad79-570b50342532');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48471a48-eec1-4b5a-b187-78a6392f1e30', 'Sound only travels through metal wires', false, 'fa8411cb-074b-4763-ad79-570b50342532');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a944854e-91f0-4d53-9c6d-3359c1a81fd1', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why does air bubble out when water is boiled in a glass pan long before it reaches 100°C?', 'Gas solubility in liquids decreases with rising temperature, driving dissolved air out of solution as bubbles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f3ee978-7d10-4484-9698-cc936eb58dad', 'Dissolved air in the water expands due to heating and escapes as tiny air bubbles from the pan floor', true, 'a944854e-91f0-4d53-9c6d-3359c1a81fd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0751e32-cb5f-41a9-af7b-38969e105736', 'Because glass creates bubbles', false, 'a944854e-91f0-4d53-9c6d-3359c1a81fd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('111a4fe6-42ee-41e0-a760-5fb2d0b1c9f5', 'Because water turns into ice', false, 'a944854e-91f0-4d53-9c6d-3359c1a81fd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb35c4fd-2894-4250-8e4c-6c7109b64f9e', 'Because heat destroys water molecules instantly', false, 'a944854e-91f0-4d53-9c6d-3359c1a81fd1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc26a08b-1693-4807-8690-3d76e443c350', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why can sailing yachts and gliders navigate across water and skies without engines?', 'Aerodynamic lift and drag forces produced by wind airflow propel yachts and gliders.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76b233c1-9727-4ced-9c3f-ca06b841d83e', 'They harness the aerodynamic thrust and lift generated by moving air (wind) pushing against canvas sails and aerofoil wings', true, 'dc26a08b-1693-4807-8690-3d76e443c350');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('862fd68e-dac4-4d04-a22f-48bd22ede73e', 'They are pulled by magnetic rocks', false, 'dc26a08b-1693-4807-8690-3d76e443c350');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c15c120-40cc-411a-bb8c-4cfd068ac2ca', 'They slide on cloud ice', false, 'dc26a08b-1693-4807-8690-3d76e443c350');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4d1fd38-171a-410e-bb3c-e8e71a8ca120', 'They float on solar rays', false, 'dc26a08b-1693-4807-8690-3d76e443c350');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2961cfb5-b6c2-4d99-a356-2b8ad91aa665', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'What are the three essential components that must be present together for Combustion (burning) to occur?', 'The classical Fire Triangle requires three elements: Combustible Fuel, Oxidizer (O₂), and Heat (ignition threshold).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f6f282e-4d67-478f-832f-11c5c6e3f105', 'Fuel (combustible substance), Oxygen (supporter of combustion), and Ignition Temperature (heat)', true, '2961cfb5-b6c2-4d99-a356-2b8ad91aa665');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c36e7b4-269e-42e9-9799-4e57a2005b1a', 'Water, Wood, and Plastic', false, '2961cfb5-b6c2-4d99-a356-2b8ad91aa665');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08c1c1eb-002b-469b-9946-a67ed2507710', 'Nitrogen, Carbon, and Ash', false, '2961cfb5-b6c2-4d99-a356-2b8ad91aa665');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9c56844-0a0c-4220-b7b1-66c6f0284917', 'Glass, Iron, and Air', false, '2961cfb5-b6c2-4d99-a356-2b8ad91aa665');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d9c0d2e7-13d2-4748-9281-cc38080744f0', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why does a traffic police officer standing at a busy intersection often wear a protective face mask?', 'Particulate masks filter toxic combustion emissions (PM2.5, NOₓ, CO) at congested traffic junctions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d09b7cf6-23e8-4334-aa28-dbd76e72ead5', 'To protect lungs from inhaling vehicular exhaust containing unburnt carbon soot, toxic carbon monoxide, and lead particulates', true, 'd9c0d2e7-13d2-4748-9281-cc38080744f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24aba2c0-687e-4335-9785-0b05a5753a57', 'To hide identity', false, 'd9c0d2e7-13d2-4748-9281-cc38080744f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2867714-f8cd-4e68-b6fd-288f28f38048', 'To keep face warm in summer', false, 'd9c0d2e7-13d2-4748-9281-cc38080744f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b30237b-2954-43bf-9e18-73cdf4f9371a', 'To amplify voice', false, 'd9c0d2e7-13d2-4748-9281-cc38080744f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8695a7d5-636a-49cd-aa03-39987391cbe1', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why is Nitrogen gas in air essential for plant life even though plants cannot absorb it directly through leaves?', 'Biological nitrogen fixation converts inert atmospheric N₂ into bioavailable ammonium and nitrate for plant amino acids.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('254ccd6c-67eb-4461-9afb-444f536cfca2', 'Soil bacteria (like Rhizobium) fix atmospheric nitrogen into soluble nitrates that plant roots absorb to synthesize essential proteins', true, '8695a7d5-636a-49cd-aa03-39987391cbe1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef7444ea-c835-44c2-9e97-d42511f938cb', 'Nitrogen gives green color to leaves', false, '8695a7d5-636a-49cd-aa03-39987391cbe1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66bcb5c7-612e-43c7-8cb1-bf035ae9833e', 'Nitrogen makes fruits sweet', false, '8695a7d5-636a-49cd-aa03-39987391cbe1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e205915-2566-4454-b818-01d48b6fe49c', 'Nitrogen turns into water inside roots', false, '8695a7d5-636a-49cd-aa03-39987391cbe1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b353e2c-00aa-4333-aaae-6a82472a9377', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Medium', 'Why does an inflated balloon burst when left in hot scorching sunlight for a long time?', 'Charles''s Law: thermal kinetic energy increases gas volume and internal pressure (P ∝ T), rupturing the elastic membrane.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a958cbf-c371-4cfd-adb3-c5b982a0e2df', 'Heat energy causes the air molecules trapped inside the balloon to expand and exert higher internal pressure against the rubber until it bursts', true, '8b353e2c-00aa-4333-aaae-6a82472a9377');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e39623ce-a892-427e-a8c6-099191eca534', 'The rubber melts from sun rays', false, '8b353e2c-00aa-4333-aaae-6a82472a9377');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c3332cb-b4d7-48ac-9c9a-a161cd236f83', 'Sunlight sucks the air out', false, '8b353e2c-00aa-4333-aaae-6a82472a9377');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43de6ed7-0014-4ae4-b7ce-8eb60d3890b7', 'The balloon turns into glass', false, '8b353e2c-00aa-4333-aaae-6a82472a9377');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac2308cb-5725-4c07-994a-d71b628ba263', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('043d028b-84d6-4c40-b9e1-7f9bc4608bcb', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'ac2308cb-5725-4c07-994a-d71b628ba263');
