INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7b6eaa97-c996-4516-881d-a08cba7a680b', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'Spot the IMPOSTER in the following group of atmospheric air properties:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdf0623a-fecd-41f3-aa2f-1e96ea13548c', 'Air occupies space', false, '7b6eaa97-c996-4516-881d-a08cba7a680b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1370a63e-f1b4-4398-8124-e238dc96c64a', 'Air has mass/weight', false, '7b6eaa97-c996-4516-881d-a08cba7a680b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f17b000b-f486-4e7c-a0b7-0cb79c3e27de', 'Air is a pure single element', true, '7b6eaa97-c996-4516-881d-a08cba7a680b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('283fefed-6090-430c-b014-4ec9b3dbfcb9', 'Air exerts atmospheric pressure in all directions', false, '7b6eaa97-c996-4516-881d-a08cba7a680b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9d7ca75-3571-4e86-b895-15cf955f512b', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'A scientist collects 100 litres of clean, dry atmospheric air at sea level. What is the approximate volume of NITROGEN and OXYGEN present in the sample?', 'Volumetric composition of dry atmospheric air: 78.08% N₂, 20.95% O₂, 0.93% Ar, 0.04% CO₂.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8271c31b-3bb7-488d-a540-9de0ed2e5c96', 'Nitrogen: ~78 litres ; Oxygen: ~21 litres', true, 'f9d7ca75-3571-4e86-b895-15cf955f512b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8e2ac1b-336a-4cd2-8ab4-9a928ddeab36', 'Nitrogen: 50 litres ; Oxygen: 50 litres', false, 'f9d7ca75-3571-4e86-b895-15cf955f512b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8223cbc-117f-4697-869d-004c870301cc', 'Nitrogen: 21 litres ; Oxygen: 78 litres', false, 'f9d7ca75-3571-4e86-b895-15cf955f512b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cf6ed81-d27b-4287-8e68-fd47bee52f72', 'Nitrogen: 90 litres ; Oxygen: 10 litres', false, 'f9d7ca75-3571-4e86-b895-15cf955f512b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99fccae8-9c50-49d6-be5c-b88014f881e6', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'Match Column I (Atmospheric Constituents) with Column II (Biological & Environmental Roles):
(a) Oxygen (21%)        -> (i) Respiration & supporter of combustion
(b) Carbon Dioxide (0.04%)-> (ii) Raw material for plant photosynthesis
(c) Nitrogen (78%)      -> (iii) Dilutes oxygen & provides protein building blocks via fixation
(d) Water Vapour        -> (iv) Drives hydrological cycle, clouds & precipitation', 'Oxygen = respiration; CO₂ = photosynthesis; Nitrogen = protein fixation; Water vapour = precipitation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a016d6f1-8269-42a2-a83a-39fb475449b7', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '99fccae8-9c50-49d6-be5c-b88014f881e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7526d92f-33a3-47a8-9015-f8c27e9f666e', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '99fccae8-9c50-49d6-be5c-b88014f881e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b19cc232-b718-4549-88bc-a1a3aaa316a4', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '99fccae8-9c50-49d6-be5c-b88014f881e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70e61667-6459-40fb-b7ba-de087ccfa175', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '99fccae8-9c50-49d6-be5c-b88014f881e6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('247fef84-4db9-4248-832d-c90f40b1fc89', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'Read the statements regarding respiration:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('524b393f-8d74-4d2e-a040-e520edcf163b', 'Statements 1 and 2 only', true, '247fef84-4db9-4248-832d-c90f40b1fc89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01ab3048-cbdd-422f-b1a8-34ea62ab3eb2', 'Statements 2 and 3 only', false, '247fef84-4db9-4248-832d-c90f40b1fc89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcc3fb8a-a7b2-4f3e-9d1a-49bda474f255', 'Statements 1 and 3 only', false, '247fef84-4db9-4248-832d-c90f40b1fc89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f14fe88-92eb-4dbb-bd0f-a71e70042754', 'All Statements 1, 2, and 3', false, '247fef84-4db9-4248-832d-c90f40b1fc89');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f92580e3-4133-4413-a093-b369c6fffc7d', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'Why does a suction rubber sucker stick firmly to a smooth glass or tiled wall when pressed hard?', 'Evacuating internal air creates a partial vacuum (P_inside < P_atm); external atmospheric pressure (101.3 kPa) pins the sucker.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0902f88-e4f4-4240-9918-220b023606e4', 'Pressing the sucker pushes out most of the air between the cup and surface; external atmospheric air pressure presses down hard on the outside, holding it tightly', true, 'f92580e3-4133-4413-a093-b369c6fffc7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92eeed08-64a6-4179-9d83-eccddd8ae82e', 'Because rubber has chemical glue', false, 'f92580e3-4133-4413-a093-b369c6fffc7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b4a2ca5-4731-48a4-949d-b042f0241c87', 'Because the glass melts onto rubber', false, 'f92580e3-4133-4413-a093-b369c6fffc7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6550332b-f7d9-4bb9-aa32-cbea007d894b', 'Because of magnetic attraction', false, 'f92580e3-4133-4413-a093-b369c6fffc7d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('853b8a00-da46-4d15-9291-74a102ac1bf0', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'How do mangroves and marsh plants growing in waterlogged saline mud adapt to breathe in oxygen-deficient soils?', 'Negatively geotropic pneumatophores with lenticels project above tidal water, ventilating root aerenchyma tissue.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06f1bb9c-7d5f-49ed-a1a9-dba243b3ac33', 'They produce specialized vertical aerial roots called Pneumatophores (Breathing Roots) that grow upward out of the mud to absorb air directly from the atmosphere', true, '853b8a00-da46-4d15-9291-74a102ac1bf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc5d5b59-3228-478d-a557-b723337b08c8', 'They absorb air through flowers', false, '853b8a00-da46-4d15-9291-74a102ac1bf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d45d5a94-8edc-4d33-bad2-784faaa0ed3a', 'They stop breathing completely', false, '853b8a00-da46-4d15-9291-74a102ac1bf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f578338-be96-43db-87ff-e5ee113b7118', 'They store oxygen in seeds', false, '853b8a00-da46-4d15-9291-74a102ac1bf0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('79901cd3-343a-490e-9458-a7198f8ef48f', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'Why does atmospheric pressure decrease progressively as you climb higher up a mountain?', 'Barometric equation: hydrostatic pressure equals the integrated mass of the overlying air column, decaying exponentially with altitude.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d58b805-35e9-49e0-95b6-a78ddbb183c2', 'Because the total vertical column and density of air molecules lying above decreases, exerting less downward gravitational weight per unit area', true, '79901cd3-343a-490e-9458-a7198f8ef48f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4543ad1d-56b5-486d-9e93-77c45c8a0ab7', 'Because gravity turns off in mountains', false, '79901cd3-343a-490e-9458-a7198f8ef48f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97dec968-fdbd-425a-886c-9603b6e28c14', 'Because cold air has no weight', false, '79901cd3-343a-490e-9458-a7198f8ef48f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93e7db94-87fc-4a8d-916b-9a3b6a164178', 'Because clouds absorb air pressure', false, '79901cd3-343a-490e-9458-a7198f8ef48f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19b50aa5-9911-4110-92f3-5a5c6167f0c9', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'What would happen to all life on Earth if the Atmosphere were completely absent?', 'The atmosphere provides respiration gases, radiative greenhouse buffering, meteor friction shield, and UV absorption.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('287914ed-a5af-4a67-bcdb-96e6a2b7b070', 'All living organisms would die instantly from asphyxiation, daytime surface temperatures would soar to +120°C and plunge to -180°C at night, and lethal cosmic rays would bombard the surface', true, '19b50aa5-9911-4110-92f3-5a5c6167f0c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b43497ff-6c55-4b54-810c-4552e0e254c8', 'Plants would grow twice as fast', false, '19b50aa5-9911-4110-92f3-5a5c6167f0c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f53fd9c-d6ad-47fc-8338-90ec6d4abf75', 'Oceans would freeze into pure gold', false, '19b50aa5-9911-4110-92f3-5a5c6167f0c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36de3429-c705-444f-8430-bb59dcd40e90', 'Earth would become lighter and float away', false, '19b50aa5-9911-4110-92f3-5a5c6167f0c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('15c9d9ac-9bc8-42fa-b912-73a0afb31dcf', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'Why does a glass tumbler filled completely with water, covered with a flat cardboard card, and inverted upside down NOT spill water?', 'Atmospheric pressure (~101,300 Pa) dwarfs the ~1,000 Pa downward hydrostatic column of water, holding the card in equilibrium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f7e3522-cf5c-4527-b2ab-057abd3897af', 'The upward atmospheric pressure exerted by outside air against the underside of the cardboard card is greater than the downward hydrostatic pressure of water', true, '15c9d9ac-9bc8-42fa-b912-73a0afb31dcf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4622016-4b3d-4fa5-8779-e14143595090', 'Because the card glues to water', false, '15c9d9ac-9bc8-42fa-b912-73a0afb31dcf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64ae0e67-2dbb-434a-aa04-57eae5c59dda', 'Because water freezes instantly', false, '15c9d9ac-9bc8-42fa-b912-73a0afb31dcf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f2a6253-1ded-443c-ab05-e1f4689b69dd', 'Because gravity stops working upside down', false, '15c9d9ac-9bc8-42fa-b912-73a0afb31dcf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d2e069e-e672-44cf-a61c-191665d7145c', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'What is ''Smog'' and why is it a dangerous environmental hazard in cities during winter?', 'Thermal inversion traps particulates and photochemical/sulfurous emissions in winter fog, forming hazardous smog.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16ef537c-7b20-4b80-b1c4-0f00d66c40bb', 'A toxic colloidal mixture of Smoke and Fog containing particulate soot and sulfur oxides that causes acute bronchitis, asthma, and severe visibility reduction', true, '5d2e069e-e672-44cf-a61c-191665d7145c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e973e288-92bc-4610-87ae-5ee7b34bb159', 'A cloud made of pure steam', false, '5d2e069e-e672-44cf-a61c-191665d7145c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0eb98e0b-5909-41e1-89bc-3f1848f3d1b6', 'A harmless morning mist', false, '5d2e069e-e672-44cf-a61c-191665d7145c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c066de05-da2c-4a04-8912-c73f79e7d206', 'Dust from the moon', false, '5d2e069e-e672-44cf-a61c-191665d7145c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7cffbcd0-c4ab-487c-8747-db76a3fe19dc', 'Class 6', 'Science', 'Chapter 11: Air Around Us', 'Hard', 'What crucial layer in the upper stratosphere shields life on Earth from harmful solar Ultraviolet (UV) radiation?', 'Stratospheric ozone photolytically absorbs high-energy UV-B radiation (280–315 nm), preventing cellular DNA mutagenesis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('456de310-3515-49e1-b095-52a2b1c15efe', 'The Ozone Layer (O₃)', true, '7cffbcd0-c4ab-487c-8747-db76a3fe19dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('975066cc-25dc-4414-b9c8-f39545a932cf', 'The Ionosphere', false, '7cffbcd0-c4ab-487c-8747-db76a3fe19dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d4e1c21-d883-4c60-8fe8-b84d561ed13a', 'The Troposphere', false, '7cffbcd0-c4ab-487c-8747-db76a3fe19dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6ac6073-1ccc-4c7d-a54d-4b8ffb86877d', 'The Exosphere', false, '7cffbcd0-c4ab-487c-8747-db76a3fe19dc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0732da36-948d-40f0-8e5b-8d05de91af60', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'A symbol or letter (such as x, y, z, m, n, a, b) that does NOT have a fixed value and can take different numerical values is called a:', 'A variable represents an unknown quantity whose value varies, denoted by English alphabetic letters.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a2c2260-99a1-496c-b33a-2f6e8ea552c9', 'Variable', true, '0732da36-948d-40f0-8e5b-8d05de91af60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('420620ed-fa4c-4b26-893c-1fc250b01ccd', 'Constant', false, '0732da36-948d-40f0-8e5b-8d05de91af60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a9e06b0-39fa-421f-9029-784776fe7df9', 'Fraction', false, '0732da36-948d-40f0-8e5b-8d05de91af60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e1dc5a1-52f5-49bd-b381-a8b7051c4576', 'Integer', false, '0732da36-948d-40f0-8e5b-8d05de91af60');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('368b3454-fe3b-4ffd-9eb7-4da292d26b3b', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'A quantity that has a fixed numerical value (such as 5, -8, 12, 100) that never changes is called a:', 'A constant possesses a fixed, definite mathematical magnitude.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3219cc90-351e-443e-9201-964ba4d54a5d', 'Constant', true, '368b3454-fe3b-4ffd-9eb7-4da292d26b3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55b7fdad-0f70-4f34-8505-a50a6a6c9851', 'Variable', false, '368b3454-fe3b-4ffd-9eb7-4da292d26b3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb41c3dd-29ff-40b1-92df-7f804e67736e', 'Equation', false, '368b3454-fe3b-4ffd-9eb7-4da292d26b3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b8aa3c8-e57b-4984-896f-617d3445feed', 'Expression', false, '368b3454-fe3b-4ffd-9eb7-4da292d26b3b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6253bf2f-54ca-4047-a979-746fab03a4ad', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'To form the letter ''L'' using matchsticks, 2 matchsticks are required for 1 ''L''. What is the algebraic rule for the number of matchsticks required to make ''n'' number of ''L''s?', '1 ''L'' = 2 matchsticks; n ''L''s = 2 × n = 2n matchsticks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f8bcda7-4662-4fce-832d-5fa72e40927f', '2n (2 × n)', true, '6253bf2f-54ca-4047-a979-746fab03a4ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49bf4904-36dc-45c3-a8bf-3ce972ad918d', 'n + 2', false, '6253bf2f-54ca-4047-a979-746fab03a4ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17953361-d801-482d-9750-ef033f25f83b', '2 + n', false, '6253bf2f-54ca-4047-a979-746fab03a4ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0038b425-6efb-465d-a9f0-abae207738e0', 'n / 2', false, '6253bf2f-54ca-4047-a979-746fab03a4ad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e4b3344-0176-46da-bc78-1f02c85f9780', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'To form the letter ''C'' using matchsticks, 3 matchsticks are required for each ''C''. How many matchsticks are needed to form 8 ''C''s?', 'Rule is 3n. For n = 8, matchsticks = 3 × 8 = 24.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd5309a2-c2a9-43dd-bd30-9d4598ba7ab1', '24 matchsticks (Rule: 3n = 3 × 8 = 24)', true, '8e4b3344-0176-46da-bc78-1f02c85f9780');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc280e91-7df9-4c0c-81e1-2c1c412d53cf', '16 matchsticks', false, '8e4b3344-0176-46da-bc78-1f02c85f9780');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25d93561-676e-4800-8449-417b9b20d8d4', '11 matchsticks', false, '8e4b3344-0176-46da-bc78-1f02c85f9780');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dece875-2906-4071-b74a-8a813dafebdb', '32 matchsticks', false, '8e4b3344-0176-46da-bc78-1f02c85f9780');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb81264c-c416-4c02-b612-a31c6c0e14de', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'How is the statement ''7 added to x'' written as an algebraic expression?', '''7 added to x'' maps directly to addition: x + 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b13577e-d126-469c-8b08-a278f3a27ad7', 'x + 7 (or 7 + x)', true, 'bb81264c-c416-4c02-b612-a31c6c0e14de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d77af2c-d8a5-4212-9c17-4c84a4edf4e7', '7x', false, 'bb81264c-c416-4c02-b612-a31c6c0e14de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1624975-e67c-4492-9440-4447261db994', 'x - 7', false, 'bb81264c-c416-4c02-b612-a31c6c0e14de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b774ade3-fe8d-4b4f-a468-aa4ec20680ed', 'x / 7', false, 'bb81264c-c416-4c02-b612-a31c6c0e14de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('936fe0f6-8b2a-4d85-bc6a-204adf883642', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'How is the statement ''y multiplied by 5 and then 3 subtracted from the result'' written algebraically?', '(y × 5) - 3 = 5y - 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e051517a-90f7-43da-ba58-6843c5888177', '5y - 3', true, '936fe0f6-8b2a-4d85-bc6a-204adf883642');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('894f3b8c-e5d4-4300-9af8-db9c33552c4d', '5y + 3', false, '936fe0f6-8b2a-4d85-bc6a-204adf883642');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b93d2837-6608-49d2-9a15-08367466cf3b', '3 - 5y', false, '936fe0f6-8b2a-4d85-bc6a-204adf883642');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17907b3c-1bec-49ed-9c66-47d6792ba1e0', 'y/5 - 3', false, '936fe0f6-8b2a-4d85-bc6a-204adf883642');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c31f0ae-8293-44b2-a31b-2fced0a4793d', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'A mathematical statement with an EQUALITY sign ''='' between two expressions (such as 2x + 5 = 15) is called an:', 'An algebraic equation establishes that two mathematical expressions have identical value using the equality symbol ''=''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9a2070b-7a1d-4706-85b4-74cadf4827a1', 'Equation', true, '1c31f0ae-8293-44b2-a31b-2fced0a4793d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bf77a5c-de46-4d61-ba6d-5031105f2cdb', 'Expression', false, '1c31f0ae-8293-44b2-a31b-2fced0a4793d');
