INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ce67536-f4a3-4d2c-bd3f-e3ff671b510b', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'The value of a variable that satisfies an equation (makes LHS = RHS) is called the:', 'A solution is a specific numerical value of the variable for which the Left Hand Side equals the Right Hand Side.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ec04f41-4b90-4aae-ac1e-71843f65e8ad', 'Solution (or Root) of the equation', true, '0ce67536-f4a3-4d2c-bd3f-e3ff671b510b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e2e60a8-6bb4-4b94-9c9b-f467a96e0b51', 'Constant', false, '0ce67536-f4a3-4d2c-bd3f-e3ff671b510b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b837f8b6-38f9-45c8-9521-2318d5d709c5', 'Coefficient', false, '0ce67536-f4a3-4d2c-bd3f-e3ff671b510b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4731887-c785-403d-804a-9e8a80b0ef29', 'Term', false, '0ce67536-f4a3-4d2c-bd3f-e3ff671b510b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1954d961-0e19-4017-8f36-14fd5dc1385e', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'Solve the simple linear equation: x + 6 = 15. What is the value of x?', 'x = 15 - 6 = 9.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd52646b-d4a9-44ba-a674-bd7c0b9eb026', 'x = 9 (15 - 6 = 9)', true, '1954d961-0e19-4017-8f36-14fd5dc1385e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('504dbb44-6e07-4dbe-a565-5b2eba623842', 'x = 21', false, '1954d961-0e19-4017-8f36-14fd5dc1385e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f37b110-dea8-484c-bb87-3e18c151f1c0', 'x = 90', false, '1954d961-0e19-4017-8f36-14fd5dc1385e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be77e3c9-aaaf-40b0-95b3-1cc6cc23984b', 'x = 6', false, '1954d961-0e19-4017-8f36-14fd5dc1385e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23f63a33-388f-48c9-8f82-99e6e6a624a1', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'Solve the linear equation: 4y = 28. What is the value of y?', 'y = 28 ÷ 4 = 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ad36a65-be2e-490a-9035-b6d89b2ce4d9', 'y = 7 (28 ÷ 4 = 7)', true, '23f63a33-388f-48c9-8f82-99e6e6a624a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf32083f-42e8-4d2c-b8ab-90d781bb771e', 'y = 32', false, '23f63a33-388f-48c9-8f82-99e6e6a624a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0cfab22-0818-4eac-aa5a-7ffc5b510498', 'y = 24', false, '23f63a33-388f-48c9-8f82-99e6e6a624a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75945277-da52-4d05-9764-b2f66a464185', 'y = 112', false, '23f63a33-388f-48c9-8f82-99e6e6a624a1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f2b9fc6-d997-42c9-add5-3d1f0a14fbfa', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'If side length of an equilateral triangle is denoted by ''l'', what is its perimeter written algebraically?', 'Perimeter = 3 × side = 3l.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70f191d0-3d42-4e5d-8a36-9cfec537801f', '3l (l + l + l = 3l)', true, '4f2b9fc6-d997-42c9-add5-3d1f0a14fbfa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04c053b3-29c0-48a8-8fc6-2c087c1d05df', 'l³', false, '4f2b9fc6-d997-42c9-add5-3d1f0a14fbfa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96eca5af-dd2c-4880-b6b2-b691a9209e89', '3 + l', false, '4f2b9fc6-d997-42c9-add5-3d1f0a14fbfa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89cb96f2-5023-4e3f-bbe5-91d7435bb132', 'l/3', false, '4f2b9fc6-d997-42c9-add5-3d1f0a14fbfa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('702987b3-e286-49f0-95e7-63bc0b8126c8', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Easy', 'What is the numerical coefficient of the variable in the algebraic term ''-7x''?', 'The numerical multiplying factor attached to the variable x is -7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('618f607c-c391-4c72-b300-66ded6897af8', '-7', true, '702987b3-e286-49f0-95e7-63bc0b8126c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e8b33bb-b634-4333-9fd1-de1130045a30', '7', false, '702987b3-e286-49f0-95e7-63bc0b8126c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('154d3760-74cc-43f1-871d-d179b0f1cf89', 'x', false, '702987b3-e286-49f0-95e7-63bc0b8126c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d51f593-0ca4-479c-920b-c193f3b24d75', '-x', false, '702987b3-e286-49f0-95e7-63bc0b8126c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('21b2083f-3494-451d-8fcb-e167df3c2892', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Raju is 5 years younger than his brother Ravi. If Ravi''s present age is ''x'' years, what is Raju''s age in terms of x?', 'Younger by 5 years means subtracting 5 from Ravi''s age: x - 5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b14fa70-ba76-4a0b-900f-a84468e2ae32', '(x - 5) years', true, '21b2083f-3494-451d-8fcb-e167df3c2892');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8ee73da-381d-449b-b65c-2d35c810aa95', '(x + 5) years', false, '21b2083f-3494-451d-8fcb-e167df3c2892');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52915bf9-79df-4137-b20a-f7676e509383', '5x years', false, '21b2083f-3494-451d-8fcb-e167df3c2892');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c605075-2341-4f3f-abf8-f942dba0f175', 'x/5 years', false, '21b2083f-3494-451d-8fcb-e167df3c2892');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('443699cc-419f-40d3-bf35-db479866caf7', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Sarita has ''m'' marbles. Ameena has 10 more than twice the number of marbles Sarita has. How many marbles does Ameena have?', 'Twice Sarita''s marbles = 2m; 10 more than twice = 2m + 10.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94113539-1f79-4642-9a7e-9a11a5dc2ca4', '2m + 10', true, '443699cc-419f-40d3-bf35-db479866caf7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9f11899-dfca-4f7d-a9c6-e1c00baa81d1', '2(m + 10)', false, '443699cc-419f-40d3-bf35-db479866caf7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7ae1a7d-8247-4298-aebc-631c9fa00e2d', '10m + 2', false, '443699cc-419f-40d3-bf35-db479866caf7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1aa790bd-6f2e-4a05-8417-9688631b9cc7', 'm/2 + 10', false, '443699cc-419f-40d3-bf35-db479866caf7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed25a7b2-815f-45b2-8567-d7a2ab2d371f', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Solve the linear equation: 3n + 7 = 25. What is the value of n?', '3n = 25 - 7 = 18 ⇒ n = 18 ÷ 3 = 6.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1c206e3-3dde-45b9-b5b9-68c61b2d487b', 'n = 6 (3n = 25 - 7 = 18 ⇒ n = 18/3 = 6)', true, 'ed25a7b2-815f-45b2-8567-d7a2ab2d371f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('767e3a45-6a4d-41af-8ac7-3ff29d4a7c55', 'n = 8', false, 'ed25a7b2-815f-45b2-8567-d7a2ab2d371f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4bb9f69-6726-458e-87eb-627975e0fd88', 'n = 5', false, 'ed25a7b2-815f-45b2-8567-d7a2ab2d371f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3623bfe-e066-4fd9-8543-9b8a6286b74a', 'n = 7', false, 'ed25a7b2-815f-45b2-8567-d7a2ab2d371f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74bd5cfa-eb4c-4118-a3b5-89f9a6669606', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Solve the equation: p/3 - 4 = 2. What is the value of p?', 'p/3 = 2 + 4 = 6 ⇒ p = 6 × 3 = 18.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('653604a1-6938-47b9-91db-66246fb95142', 'p = 18 (p/3 = 2 + 4 = 6 ⇒ p = 6 × 3 = 18)', true, '74bd5cfa-eb4c-4118-a3b5-89f9a6669606');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fb136b3-19ca-4181-9fd5-60a1f8ff6dff', 'p = 6', false, '74bd5cfa-eb4c-4118-a3b5-89f9a6669606');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ae9a583-bb18-4f45-a378-05724b80622a', 'p = 12', false, '74bd5cfa-eb4c-4118-a3b5-89f9a6669606');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('318261fc-91bb-479e-865f-4dd94a224080', 'p = 24', false, '74bd5cfa-eb4c-4118-a3b5-89f9a6669606');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b9c4cc9f-96c8-4aa3-bc9c-b58d4765da6d', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'A bus travels at a uniform speed of ''v'' km per hour. It goes from Daspur to Beespur. After the bus has travelled for 5 hours, Beespur is still 20 km away. What is the total distance between Daspur and Beespur in terms of v?', 'Distance travelled in 5 hours = Speed × Time = 5v km. Total distance = 5v + 20 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78c3c027-9831-4ef8-bee9-ad94a24260fa', '(5v + 20) km', true, 'b9c4cc9f-96c8-4aa3-bc9c-b58d4765da6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f804b775-d57b-4b72-9b53-f6cad3d5ab66', '(5v - 20) km', false, 'b9c4cc9f-96c8-4aa3-bc9c-b58d4765da6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('695fa5bc-6a1c-4595-9af8-e835468e39a0', '20v + 5 km', false, 'b9c4cc9f-96c8-4aa3-bc9c-b58d4765da6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f75b436-f7f2-4611-a4cc-01b4a57a896d', '5(v + 20) km', false, 'b9c4cc9f-96c8-4aa3-bc9c-b58d4765da6d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dcdce480-0c38-4709-9870-db83cb5d395c', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'If a box contains 50 mangoes, how will you write the total number of mangoes in ''b'' boxes?', 'Number of mangoes per box × number of boxes = 50 × b = 50b.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd792882-d6d9-49a3-908e-f7784d6e1c41', '50b (50 × b)', true, 'dcdce480-0c38-4709-9870-db83cb5d395c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('070fe349-9590-4948-bbf9-5d09ae2b4427', '50 + b', false, 'dcdce480-0c38-4709-9870-db83cb5d395c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2b60226-4f24-4c08-85cf-f176856dec16', 'b / 50', false, 'dcdce480-0c38-4709-9870-db83cb5d395c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('321784b2-8cc1-44b9-8e37-73fc404d6b8f', '50 - b', false, 'dcdce480-0c38-4709-9870-db83cb5d395c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fb8a957-10bf-4ee2-94ac-cee90d7c4e3a', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Cadets are marching in a parade in a Republic Day parade. There are 5 cadets in a row. What is the algebraic rule which gives the total number of cadets for ''r'' rows?', 'Cadets per row × rows = 5 × r = 5r.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cbef8be-1f29-4f88-afdc-3a8d02757213', '5r', true, '7fb8a957-10bf-4ee2-94ac-cee90d7c4e3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3223bbb9-b846-41c9-88df-1bd3de710af6', 'r + 5', false, '7fb8a957-10bf-4ee2-94ac-cee90d7c4e3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63d377f7-f8d6-4a21-bc2d-e411bed7299c', 'r / 5', false, '7fb8a957-10bf-4ee2-94ac-cee90d7c4e3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce4c1710-e7bf-4b9d-8591-c7a4adef988a', '5 + r', false, '7fb8a957-10bf-4ee2-94ac-cee90d7c4e3a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9bed77b4-3b4d-44e7-8569-6bd761db39dd', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Leela is Radha''s younger sister. Leela is 4 years younger than Radha. Can you write Leela''s age in terms of Radha''s age? (Take Radha''s age as ''x'' years):', 'Leela''s age = Radha''s age - 4 = x - 4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df3040d8-cb9f-4f9d-96d9-0826f8fa0448', '(x - 4) years', true, '9bed77b4-3b4d-44e7-8569-6bd761db39dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac615ac0-a411-435a-9f0c-2eddb8011752', '(x + 4) years', false, '9bed77b4-3b4d-44e7-8569-6bd761db39dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05225add-700c-44fd-9d86-e148ac01a37d', '4x years', false, '9bed77b4-3b4d-44e7-8569-6bd761db39dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c21d7534-cb00-4607-b6da-6c62ac223b72', 'x/4 years', false, '9bed77b4-3b4d-44e7-8569-6bd761db39dd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d0c227b-5cf8-4259-9a5a-727189ab8629', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Mother has made laddoos. She gives some laddoos to guests and family members; still 5 laddoos remain. If the number of laddoos mother gave away is ''l'', how many laddoos did she make in total?', 'Total made = Laddoos given away + remaining laddoos = l + 5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da80378f-e515-4aef-97c1-53de9027fbd1', 'l + 5', true, '4d0c227b-5cf8-4259-9a5a-727189ab8629');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf9a176a-937b-4dc0-8fdb-859e18d74410', 'l - 5', false, '4d0c227b-5cf8-4259-9a5a-727189ab8629');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e52d7a3-6ef1-4cbd-b831-844320dbb41c', '5l', false, '4d0c227b-5cf8-4259-9a5a-727189ab8629');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('286b311f-2324-4d60-8a46-2e2660450924', 'l / 5', false, '4d0c227b-5cf8-4259-9a5a-727189ab8629');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ce5345b7-3ec4-41b6-bbf3-6207a3037540', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Which of the following mathematical expressions is a valid ALGEBRAIC EQUATION containing a variable?', 'An algebraic equation must have both a variable and an equality sign (=).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a1719b4-be0d-4fc1-8284-cea374c8ee7a', '2x + 7 = 19 (contains variable x and ''='' sign)', true, 'ce5345b7-3ec4-41b6-bbf3-6207a3037540');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9346129-90e2-4dd0-88e7-03015ed57b5c', '2x + 7 > 19', false, 'ce5345b7-3ec4-41b6-bbf3-6207a3037540');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff05a7b9-e335-4377-9c2c-6a8a799f985f', '5 × 3 + 2 = 17 (arithmetic equality without variable)', false, 'ce5345b7-3ec4-41b6-bbf3-6207a3037540');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91080a38-5d8d-4f51-a4d6-827a6b7bae55', '3x - 5', false, 'ce5345b7-3ec4-41b6-bbf3-6207a3037540');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88ec0c27-8a67-47b2-acfb-25624ff83c76', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Find the value of the algebraic expression 3x² - 4x + 5 when x = 3:', '3(3²) - 4(3) + 5 = 3(9) - 12 + 5 = 27 - 12 + 5 = 20.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('479329da-c7bf-46f1-9ce3-aba112398344', '20 (3(3)² - 4(3) + 5 = 3(9) - 12 + 5 = 27 - 12 + 5 = 20)', true, '88ec0c27-8a67-47b2-acfb-25624ff83c76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52938991-c040-4793-b1f4-e9d7236b43a9', '18', false, '88ec0c27-8a67-47b2-acfb-25624ff83c76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8522e957-b37e-4d9c-9175-a4467d954bd8', '24', false, '88ec0c27-8a67-47b2-acfb-25624ff83c76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16af522e-63ac-4f86-85f7-026600183eb8', '15', false, '88ec0c27-8a67-47b2-acfb-25624ff83c76');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b70152a-94ee-47dc-b161-e022242cf085', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Change the algebraic statement into ordinary everyday English: ''A notebook costs ₹p. A book costs ₹3p.''', '3p indicates multiplication by 3, meaning the book costs 3 times the notebook''s price.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05af2358-b40d-47b1-ada1-258f8c29c290', 'A book costs three times as much as a notebook', true, '4b70152a-94ee-47dc-b161-e022242cf085');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64570cd3-339e-457d-8b31-c8995e828f5f', 'A notebook costs three times as much as a book', false, '4b70152a-94ee-47dc-b161-e022242cf085');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8eb2675c-5e96-4fb4-8579-e42d2fdc5459', 'A book costs ₹3 more than a notebook', false, '4b70152a-94ee-47dc-b161-e022242cf085');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40214bfd-0072-477b-a1cb-a13ef50e3d89', 'A book costs ₹3 less than a notebook', false, '4b70152a-94ee-47dc-b161-e022242cf085');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('685d6299-8448-4123-9d47-6fe2a65ea428', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'Solve the equation using the Trial and Error method: 5x = 35. For what value of x is the equation satisfied?', 'Testing values: 5(5)=25, 5(6)=30, 5(7)=35 (Satisfied!).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e78a41f-4961-42de-8635-a1ba2205e5d8', 'x = 7 (5 × 7 = 35)', true, '685d6299-8448-4123-9d47-6fe2a65ea428');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fd94310-7ae6-4bac-9507-0dcec960686d', 'x = 5', false, '685d6299-8448-4123-9d47-6fe2a65ea428');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cd03719-fdbd-43d1-96af-8f6d6b3443c5', 'x = 6', false, '685d6299-8448-4123-9d47-6fe2a65ea428');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eba63b52-9f85-4f42-bba3-d852fe4a0c28', 'x = 8', false, '685d6299-8448-4123-9d47-6fe2a65ea428');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('871cda72-1705-4d31-8358-e631ab4ce53e', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'How is the Commutative Property of Addition of two whole numbers ''a'' and ''b'' written in general algebraic notation?', 'Commutative law of addition states that order of terms does not alter the sum: a + b = b + a.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dc49c5e-fd3c-4e9c-9439-de9e75d23832', 'a + b = b + a', true, '871cda72-1705-4d31-8358-e631ab4ce53e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcadde3e-1b64-4558-b24a-a3971847f80a', 'a × b = b × a', false, '871cda72-1705-4d31-8358-e631ab4ce53e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7579fc4c-d0c1-4ed7-9f57-4794b75773dd', 'a - b = b - a', false, '871cda72-1705-4d31-8358-e631ab4ce53e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('973f8535-b9ca-486e-a765-9e4a70580733', 'a + (b + c) = (a + b) + c', false, '871cda72-1705-4d31-8358-e631ab4ce53e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18e20166-e467-40db-85f7-a5a9a85e32b0', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'How is the Distributive Property of Multiplication over Addition written algebraically for three numbers a, b, and c?', 'Distributive property: a(b + c) = ab + ac.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1db87625-908c-46e5-8907-d0b77f0ce12e', 'a × (b + c) = (a × b) + (a × c)', true, '18e20166-e467-40db-85f7-a5a9a85e32b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83a03621-abe2-4a29-a8e1-6240a1b0a09b', 'a + (b × c) = (a + b) × c', false, '18e20166-e467-40db-85f7-a5a9a85e32b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1980e6fd-f49e-410f-ae58-ee58f3514ab9', 'a × b × c = a + b + c', false, '18e20166-e467-40db-85f7-a5a9a85e32b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e69b9a7f-8b2e-4555-81ad-57164171d18c', 'a / (b + c) = a/b + a/c', false, '18e20166-e467-40db-85f7-a5a9a85e32b0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9a0dcfb-9265-41f9-8459-680b7535db6a', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Medium', 'If the diameter of a circle is ''d'' and its radius is ''r'', what is the algebraic relation between diameter and radius?', 'Diameter is twice the radius: d = 2r.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5f05555-028a-40ac-8cf9-f71fb6ae4c25', 'd = 2r (or r = d/2)', true, 'f9a0dcfb-9265-41f9-8459-680b7535db6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('383ac220-00a0-47e0-8c84-75e8fd4f84bc', 'd = r + 2', false, 'f9a0dcfb-9265-41f9-8459-680b7535db6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd4258f1-c3bb-467d-b2fc-f40fb5885fe2', 'd = r²', false, 'f9a0dcfb-9265-41f9-8459-680b7535db6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8509ce50-caf5-415a-817b-a5c8df90e10c', 'd = r/2', false, 'f9a0dcfb-9265-41f9-8459-680b7535db6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d7925f7-344e-47eb-b42f-edce2e885388', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fc674be-4757-4b19-980d-3c2760a5d3e0', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '2d7925f7-344e-47eb-b42f-edce2e885388');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a1d269f-8dab-45c5-99ec-b3bdbf3f47f9', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '2d7925f7-344e-47eb-b42f-edce2e885388');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fb51a33-0ca8-455d-8709-120f702f024e', '(A) is true, but (R) is false.', false, '2d7925f7-344e-47eb-b42f-edce2e885388');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0524d99-1b2d-446c-a787-13e491602f04', '(A) is false, but (R) is true.', false, '2d7925f7-344e-47eb-b42f-edce2e885388');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('357c7982-359c-462c-9958-74affa7a081d', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'Spot the IMPOSTER in the following algebraic expressions where x = 4:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35d20f77-069d-4573-8838-85ed9e17e4d3', '2x + 3 = 11', false, '357c7982-359c-462c-9958-74affa7a081d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0befc4a7-c37a-4e6e-adda-8c4fe480db26', '5x - 8 = 12', false, '357c7982-359c-462c-9958-74affa7a081d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff0eb5a4-8795-438d-826f-7766392c6e25', 'x² + 1 = 17', false, '357c7982-359c-462c-9958-74affa7a081d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e555c34-9545-44f7-8892-7f74a6b5a5de', '3x - 5 = 8', true, '357c7982-359c-462c-9958-74affa7a081d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97dc80ab-75b0-47c3-ae96-b300e6f21a16', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'To form a pattern of ''n'' connected squares using matchsticks in a row where the first square uses 4 sticks and each adjoining square shares 1 common vertical side, what is the exact algebraic rule for total matchsticks?', 'First square uses 4; every additional square adds 3 sticks: 4 + 3(n - 1) = 4 + 3n - 3 = 3n + 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99117364-ebae-4ddb-9eae-5e911a556593', '3n + 1 (For 1 square = 4 sticks ; For 2 squares = 7 sticks ; For 3 = 10 sticks)', true, '97dc80ab-75b0-47c3-ae96-b300e6f21a16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6d2bf59-2e9c-470f-8a49-2869a1a4d2c0', '4n', false, '97dc80ab-75b0-47c3-ae96-b300e6f21a16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b8a874e-1e07-4de1-b8fb-7cd570f25b45', '4n - 1', false, '97dc80ab-75b0-47c3-ae96-b300e6f21a16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a09a0116-b582-4b26-9bcd-8a20777ed05e', '2n + 2', false, '97dc80ab-75b0-47c3-ae96-b300e6f21a16');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c9712f76-0f62-4796-81f3-f42c985c6f60', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'Match Column I (Word Statements) with Column II (Algebraic Expressions):
(a) 5 subtracted from -m      -> (i) 2y + 11
(b) 11 added to twice of y    -> (ii) -m - 5
(c) y multiplied by -8        -> (iii) y/5 + 3
(d) 3 added to one-fifth of y -> (iv) -8y', '-m - 5; 2y + 11; -8y; y/5 + 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1aa518b4-e7c8-44f6-900a-40cc37a011d8', 'a-(ii), b-(i), c-(iv), d-(iii)', true, 'c9712f76-0f62-4796-81f3-f42c985c6f60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b235792-e594-47ff-9678-e7fa6ad6b4dd', 'a-(i), b-(ii), c-(iii), d-(iv)', false, 'c9712f76-0f62-4796-81f3-f42c985c6f60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4f6099d-452c-4cde-b867-4312329f8b60', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'c9712f76-0f62-4796-81f3-f42c985c6f60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a733fcaf-bbf3-4c9b-97a8-2c61cc5ffeab', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'c9712f76-0f62-4796-81f3-f42c985c6f60');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6a7d359c-26af-4ab8-a5a2-2edc0847da61', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'Read the statements regarding algebraic equations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e55f81d2-781b-400a-8b1c-ddd799c1bf76', 'Statements 1 and 2 only', true, '6a7d359c-26af-4ab8-a5a2-2edc0847da61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46897254-8feb-4d74-a20a-ad09af75134b', 'Statements 2 and 3 only', false, '6a7d359c-26af-4ab8-a5a2-2edc0847da61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca0a5bc4-12a7-44d9-9e71-b4b279de3881', 'Statements 1 and 3 only', false, '6a7d359c-26af-4ab8-a5a2-2edc0847da61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51b50f8e-e5ae-4846-8b72-1e91f345348e', 'All Statements 1, 2, and 3', false, '6a7d359c-26af-4ab8-a5a2-2edc0847da61');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be0d4471-5391-4ae3-a16c-77e0c35fb42a', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'Solve the linear equation: (2x - 3) / 5 = 3. What is the value of x?', '2x - 3 = 3 × 5 = 15 ⇒ 2x = 15 + 3 = 18 ⇒ x = 9.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('346a4638-02dc-41e2-92ee-145e18227185', 'x = 9 (2x - 3 = 15 ⇒ 2x = 18 ⇒ x = 9)', true, 'be0d4471-5391-4ae3-a16c-77e0c35fb42a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9a2c5a5-012d-41c8-bd57-9392b7b2d7b4', 'x = 6', false, 'be0d4471-5391-4ae3-a16c-77e0c35fb42a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bfd686c-38b7-4c94-ac87-5047a6e72b9e', 'x = 12', false, 'be0d4471-5391-4ae3-a16c-77e0c35fb42a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a20a1cb8-8d87-40d0-ab42-86348f148420', 'x = 15', false, 'be0d4471-5391-4ae3-a16c-77e0c35fb42a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d277d776-571e-430d-86db-97b902a9f6f3', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'The length of a rectangular hall is 4 metres less than 3 times the breadth of the hall. If the breadth is ''b'' metres, what is the length in terms of b?', '3 times breadth = 3b. 4 metres less than 3b = 3b - 4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8342e8a-11dc-4210-97b7-6fbb77358b95', '(3b - 4) metres', true, 'd277d776-571e-430d-86db-97b902a9f6f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f5159cb-9d67-4a5e-95e5-719dae05e874', '(3b + 4) metres', false, 'd277d776-571e-430d-86db-97b902a9f6f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b29b8124-b931-4145-ab25-a8b9d1679dbf', '(4b - 3) metres', false, 'd277d776-571e-430d-86db-97b902a9f6f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6099cfdd-abba-482f-88ae-9b3559df64d5', '3(b - 4) metres', false, 'd277d776-571e-430d-86db-97b902a9f6f3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2734f5bb-e764-481e-ad48-da70466bcbe7', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'A rectangular box has height ''h'' cm. Its length is 5 times the height and breadth is 10 cm less than the length. Express the length and breadth in terms of the height h:', 'Length = 5 × h = 5h cm; Breadth = Length - 10 = (5h - 10) cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d8056dc-4de4-4b02-a324-50d41faf5a6b', 'Length = 5h cm ; Breadth = (5h - 10) cm', true, '2734f5bb-e764-481e-ad48-da70466bcbe7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc4a879e-b01b-4b3a-b9bb-84d543711985', 'Length = h + 5 cm ; Breadth = h - 10 cm', false, '2734f5bb-e764-481e-ad48-da70466bcbe7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae1e238b-2957-4329-b75f-c57910d01203', 'Length = 5h cm ; Breadth = 5h + 10 cm', false, '2734f5bb-e764-481e-ad48-da70466bcbe7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5f94c5a-3e48-495e-9633-2d6243cf2b67', 'Length = h/5 cm ; Breadth = 5h - 10 cm', false, '2734f5bb-e764-481e-ad48-da70466bcbe7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba32735b-79ed-4bbe-8190-dae99268b9b0', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'The sum of three consecutive integers is 51. If the smallest integer is denoted by ''x'', what is the algebraic equation and the value of x?', '3x + 3 = 51 ⇒ 3x = 48 ⇒ x = 16. Integers are 16, 17, 18 (16+17+18 = 51).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fe7c066-c39e-4ba1-9cbd-5e5e4f5f57af', 'Equation: x + (x + 1) + (x + 2) = 51 ⇒ 3x + 3 = 51 ⇒ x = 16 (Integers are 16, 17, 18)', true, 'ba32735b-79ed-4bbe-8190-dae99268b9b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00bb292f-4153-4eed-8963-55e956bd1f0e', 'Equation: 3x = 51 ⇒ x = 17', false, 'ba32735b-79ed-4bbe-8190-dae99268b9b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69bdbb30-ca8b-4bab-be76-6a7148bef916', 'Equation: x + x + x = 51 ⇒ x = 15', false, 'ba32735b-79ed-4bbe-8190-dae99268b9b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b26d32a-5015-4f49-a9c9-5b21f24b13be', 'Equation: 3x - 3 = 51 ⇒ x = 18', false, 'ba32735b-79ed-4bbe-8190-dae99268b9b0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fdf68318-618b-46c1-be74-66a9eee2ddd5', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'A father is 35 years older than his son. After 5 years, the father will be twice as old as his son. If the son''s present age is ''s'', which equation correctly models this situation?', 'Father''s age in 5 yrs = (s + 35) + 5 = s + 40. Son''s age in 5 yrs = s + 5. Equation: s + 40 = 2(s + 5).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36f80804-2e7e-4349-a1d4-5f67b551d627', '(s + 35) + 5 = 2(s + 5) ⇒ s + 40 = 2s + 10 ⇒ s = 30', true, 'fdf68318-618b-46c1-be74-66a9eee2ddd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16b1f26f-64ea-4933-b5ae-a43e43d36a08', 's + 35 = 2s', false, 'fdf68318-618b-46c1-be74-66a9eee2ddd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ce51c3f-7f28-4b3e-b231-f8e869599030', 's + 5 = 2(s + 35)', false, 'fdf68318-618b-46c1-be74-66a9eee2ddd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fbe32e7-c43b-4106-beb2-696ac372f230', '35s = 2(s + 5)', false, 'fdf68318-618b-46c1-be74-66a9eee2ddd5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ccfd267f-1377-4cab-bd5e-5143a58105a1', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'If 3x + 2y = 24 and x = 4, find the value of y:', '12 + 2y = 24 ⇒ 2y = 12 ⇒ y = 6.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c16ba880-80fd-45fc-8017-e64abf698755', 'y = 6 (3(4) + 2y = 24 ⇒ 12 + 2y = 24 ⇒ 2y = 12 ⇒ y = 6)', true, 'ccfd267f-1377-4cab-bd5e-5143a58105a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3569a813-335c-4d60-995e-13a817616ecb', 'y = 4', false, 'ccfd267f-1377-4cab-bd5e-5143a58105a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7de93956-81ef-405c-bcf8-a908fa051adf', 'y = 8', false, 'ccfd267f-1377-4cab-bd5e-5143a58105a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('287800c4-cd4e-4ed5-ad1c-66b8a6228082', 'y = 12', false, 'ccfd267f-1377-4cab-bd5e-5143a58105a1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bcd395b3-f65e-4621-999a-6f010e7de2fa', 'Class 6', 'Mathematics', 'Chapter 11: Algebra', 'Hard', 'Why is Algebra considered the foundational universal language of higher mathematics, physics, and computer programming?', 'Algebra provides abstract symbolic modeling to formulate general rules, invariant laws, and computational algorithms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d7a5264-575c-4199-a609-a260dbdcc6b2', 'It allows generalized patterns, physical laws, and complex relationships to be stated succinctly using variables rather than specific arithmetic numbers alone', true, 'bcd395b3-f65e-4621-999a-6f010e7de2fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4919b20f-e042-42e9-84f1-20ab2535fba0', 'Because letters are easier to draw than numbers', false, 'bcd395b3-f65e-4621-999a-6f010e7de2fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc418aca-90ce-4ea8-b2db-8147dd41012c', 'Because algebra eliminates the need for thinking', false, 'bcd395b3-f65e-4621-999a-6f010e7de2fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('121d467b-feb2-4719-a2ec-4a69050c6707', 'Because it only works for matchsticks', false, 'bcd395b3-f65e-4621-999a-6f010e7de2fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c1956ef-6ed3-4baf-a053-e8025c523bce', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Easy', 'In English grammar, a sentence in which the SUBJECT performs the action is in:', 'In Active Voice, the grammatical subject is the active agent/doer of the transitive verb.', NOW()) ON CONFLICT DO NOTHING;
