INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52860b36-b2fc-47ae-85c2-26c1fc3e4c52', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Easy', 'A sentence in which the SUBJECT receives the action performed by an agent (e.g. ''The mouse was chased by the cat'') is in:', 'In Passive Voice, the recipient of the action occupies the subject position followed by ''be + past participle''.', NOW()) ON CONFLICT DO NOTHING;
