INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ff68cea-c26d-4c6e-8ca8-c66979b05f24', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'Spot the IMPOSTER in the following Active-Passive transformations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc0bab6a-3bab-4a90-88ea-6a21dace837c', 'Active: ''He wrote a letter'' -> Passive: ''A letter was written by him''', false, '7ff68cea-c26d-4c6e-8ca8-c66979b05f24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18ea3585-1552-416e-80d8-73fe1c07008c', 'Active: ''She ate an apple'' -> Passive: ''An apple was eaten by her''', false, '7ff68cea-c26d-4c6e-8ca8-c66979b05f24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f45da802-34c9-4680-a5c4-b4e239df49d7', 'Active: ''They built a bridge'' -> Passive: ''A bridge was built by them''', false, '7ff68cea-c26d-4c6e-8ca8-c66979b05f24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62e88827-e427-4570-9d06-965ddeaa5d66', 'Active: ''He slept peacefully'' -> Passive: ''Peacefully was slept by him''', true, '7ff68cea-c26d-4c6e-8ca8-c66979b05f24');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a47e1187-43ab-4991-97de-af447e8f9682', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'Analyze the contextual tone in Kalpana Chawla''s historic message from Columbia space shuttle to Indian students:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6046ca6c-c59f-4c5f-8b30-42014e498f17', 'Vision (clarity of purpose), Courage (bravery to begin), and Perseverance (tenacious resilience to endure)', true, 'a47e1187-43ab-4991-97de-af447e8f9682');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9ff105d-7914-4e7a-85b2-06ab3297a94b', 'Wealth, Fame, and Pride', false, 'a47e1187-43ab-4991-97de-af447e8f9682');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('225caff0-8820-4964-8d88-25bd9a1d84e6', 'Speed, Anger, and Power', false, 'a47e1187-43ab-4991-97de-af447e8f9682');
