INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7adeb4ba-f4d4-4b7e-bfd7-052ef2377f91', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'Match Column I (Phrasal Verbs) with Column II (Exact Definitions):
(a) Call off     -> (i) Extinguish a fire
(b) Put out      -> (ii) Cancel an event completely
(c) Look into    -> (iii) Tolerate / endure an unpleasant situation
(d) Put up with  -> (iv) Investigate or examine closely', 'Call off = cancel; Put out = extinguish; Look into = investigate; Put up with = tolerate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93eb83b7-3990-40f2-b44a-50c103ec244e', 'a-(ii), b-(i), c-(iv), d-(iii)', true, '7adeb4ba-f4d4-4b7e-bfd7-052ef2377f91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e20714a-b781-4720-9c8e-a05f137c2d98', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '7adeb4ba-f4d4-4b7e-bfd7-052ef2377f91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a09fa55d-ea94-446a-a89f-360379712faa', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '7adeb4ba-f4d4-4b7e-bfd7-052ef2377f91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b70c4657-84db-493d-9a2b-a9471e879be0', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '7adeb4ba-f4d4-4b7e-bfd7-052ef2377f91');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fac23ed2-7ad0-4d96-91e3-61c9ca21c29c', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'Read the statements regarding English grammar:
