INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bbf2ad2-20c9-4b23-92bb-c8f1c3a5de0c', 'Statements 2 and 3 only', false, 'fac23ed2-7ad0-4d96-91e3-61c9ca21c29c');
