INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f8f2c350-ea55-41e3-95f9-61c6e8fba66a', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'Transform the compound sentence into a COMPLEX sentence using an Adverb Clause of Concession:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('481714fb-61e1-488a-96ed-13f45c8b8f5e', '''Although he was very poor, he remained scrupulously honest.''', true, 'f8f2c350-ea55-41e3-95f9-61c6e8fba66a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f55d0044-38d4-43a1-aa14-d25074966ed7', '''He was poor and honest.''', false, 'f8f2c350-ea55-41e3-95f9-61c6e8fba66a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20aaab03-cb23-4741-84f4-6a0c69722fb4', '''Being poor, he was honest.''', false, 'f8f2c350-ea55-41e3-95f9-61c6e8fba66a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f74ae3ee-03a0-460f-84ac-ad7fb60b8077', '''Because he was poor, he was honest.''', false, 'f8f2c350-ea55-41e3-95f9-61c6e8fba66a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d60b7e2c-40ce-475d-9367-cb6b93c53dda', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'What is the grammatical error in the sentence: ''The flock of sheep were grazing on the hillside.''?', 'Collective noun ''flock'' takes singular grammatical agreement: ''The flock of sheep was grazing''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb3bd851-ae39-46f1-aded-202cc2e79cc6', 'The collective noun ''flock'' is singular and requires the singular verb ''was grazing''', true, 'd60b7e2c-40ce-475d-9367-cb6b93c53dda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7beaab17-9751-44d0-b16b-03339f380093', '''Flock'' should be spelled ''flook''', false, 'd60b7e2c-40ce-475d-9367-cb6b93c53dda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8815798-5145-4b4f-b281-27a89aae23ea', '''Sheep'' should be written as ''sheeps''', false, 'd60b7e2c-40ce-475d-9367-cb6b93c53dda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6751a0dd-e7bb-4619-946d-1c8bffba8248', '''Hillside'' is spelled incorrectly', false, 'd60b7e2c-40ce-475d-9367-cb6b93c53dda');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3d91a04-6e2e-4198-9882-96ffb8a24c20', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'Identify the figure of speech in: ''The lightning danced across the dark sky.''', 'Endowing natural phenomena with human kinetic agency constitutes Personification.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6a8b564-be63-43c0-b595-86f3dbe8a848', 'Personification (attributing the human voluntary action of ''dancing'' to inanimate lightning)', true, 'd3d91a04-6e2e-4198-9882-96ffb8a24c20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be6c5374-3cc1-411b-a5d6-a2f5440c7aa5', 'Simile', false, 'd3d91a04-6e2e-4198-9882-96ffb8a24c20');
