INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4df57b9b-37c8-4bf1-b65a-1028038887f1', 'Oxymoron', false, 'd3d91a04-6e2e-4198-9882-96ffb8a24c20');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('86c4f078-263e-46c1-9ba0-429b371cc18a', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'Convert into Indirect Speech:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e36b94ba-309c-4930-b5e5-0c9dd88c812a', 'She exclaimed with sorrow that she had lost her grandmother''s golden ring.', true, '86c4f078-263e-46c1-9ba0-429b371cc18a');
