INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea12091f-c8b4-490b-a9a8-a939e5328858', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'What is the meaning of the Latin phrase ''Vice Versa'' used in English?', '''Vice versa'' indicates that the reverse of the stated proposition is equally valid.', NOW()) ON CONFLICT DO NOTHING;
