INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aafcb8b0-57b1-4bb2-a088-3247a42044b2', 'With great speed', false, 'ea12091f-c8b4-490b-a9a8-a939e5328858');
