INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52cd7dbf-cff0-4548-847c-55801bcbda43', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'Which of the following sentences exhibits correct MODAL AUXILIARY usage to express moral obligation and duty?', '''Ought to'' expresses ethical and moral duty/obligation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('491ad4cf-e2ff-4049-8c8f-584bbaeccb31', '''We ought to respect our parents and teachers.''', true, '52cd7dbf-cff0-4548-847c-55801bcbda43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42f54cff-5239-4229-9158-1c37e320250b', '''We might respect our parents.''', false, '52cd7dbf-cff0-4548-847c-55801bcbda43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('134e8682-c9e0-4911-bfbe-e21cde7a6bd4', '''We can to respect our parents.''', false, '52cd7dbf-cff0-4548-847c-55801bcbda43');
