INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1377e2c6-77f3-4c64-8eb5-51d394846fd9', 'Class 6', 'English', 'Chapter 11: Comprehensive Literature Review & Applied Grammar', 'Hard', 'What core communicative and linguistic competency does mastery of applied grammar cultivate in young scholars?', 'Applied linguistics bridges structural grammatical precision with nuanced cognitive and empathetic literary expression.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25575a97-52ac-4c8a-9db8-ee152cfb64f1', 'Precision of thought, analytical reading comprehension, eloquent rhetorical expression, and ethical literary appreciation', true, '1377e2c6-77f3-4c64-8eb5-51d394846fd9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('730c3d0f-a93e-4414-9ace-7ceae946c872', 'Rote memorization of words without meaning', false, '1377e2c6-77f3-4c64-8eb5-51d394846fd9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fc86111-7d73-418a-b9da-b0d33b584708', 'Speaking without grammar rules', false, '1377e2c6-77f3-4c64-8eb5-51d394846fd9');
