INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e1934d5-32cd-4864-b2a7-b8431fd54dfd', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Easy', 'Who is celebrated as the ''Missile Man of India'' and served as the 11th President of India (2002–2007)?', 'Dr. A.P.J. Abdul Kalam led the development of India''s indigenous missile systems (Agni, Prithvi) and SLV-3.', NOW()) ON CONFLICT DO NOTHING;
