INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('83fe79f1-d966-4bc2-b7b7-4b37592909fd', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Easy', 'Who was the FIRST Indian scientist to win the Nobel Prize in Physics in 1930 for discovering the scattering of light?', 'Sir C.V. Raman discovered the Raman Effect on 28 February 1928, celebrated annually as National Science Day in India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('370606a1-c5e5-4321-bb74-b6b2d699d19b', 'Sir C.V. Raman (Chandrasekhara Venkata Raman)', true, '83fe79f1-d966-4bc2-b7b7-4b37592909fd');
