INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('218a79e9-6273-415f-b613-46a14c78acfc', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Easy', 'Why is ''National Science Day'' celebrated across India every year on 28th February?', 'The Government of India designated 28 February as National Science Day in 1986 to honor the Raman Effect discovery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84235705-1ad2-4b8c-8ce4-d071832c60a4', 'To commemorate Sir C.V. Raman''s historic discovery of the ''Raman Effect'' on 28th February 1928', true, '218a79e9-6273-415f-b613-46a14c78acfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91c1a8d4-9faa-464d-aa4b-1d1d90c5c0d2', 'To celebrate the launch of India''s first satellite', false, '218a79e9-6273-415f-b613-46a14c78acfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('914a4577-5be5-4957-a753-cd5ea6981c00', 'To mark the founding of ISRO', false, '218a79e9-6273-415f-b613-46a14c78acfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5579a59-2e5a-4384-bad7-b7e8dff2db19', 'To celebrate Dr. Kalam''s birthday', false, '218a79e9-6273-415f-b613-46a14c78acfc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37466578-8de2-44a8-bbc9-7248492d9ec6', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Easy', 'Who is reverently regarded as the ''Father of the Indian Space Programme''?', 'Dr. Vikram Sarabhai founded ISRO in 1969 and established the Thumba Equatorial Rocket Launching Station.', NOW()) ON CONFLICT DO NOTHING;
