INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ceb55f9a-f8fa-44c6-8c04-cf11485619ea', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Easy', 'What was India''s FIRST indigenous artificial satellite, launched into space on 19th April 1975, named after?', 'Aryabhata, built by ISRO and launched by a Soviet Kosmos-3M rocket in 1975, marked India''s entry into the space age.', NOW()) ON CONFLICT DO NOTHING;
