INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d54fd09a-2d07-49e1-935f-b9bdc3281dd4', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Easy', 'Who was the FIRST Indian citizen to travel into outer space (aboard Soviet Soyuz T-11 on 3rd April 1984)?', 'Rakesh Sharma spent 7 days aboard Salyut 7 in 1984, famously describing India as ''Saare Jahan Se Achha'' from space.', NOW()) ON CONFLICT DO NOTHING;
