INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73b58377-5d7e-4c7d-9318-ae5f21ff9c5b', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Hard', 'Who was the eminent Indian theoretical physicist whose collaborative quantum statistical work with Albert Einstein in 1924 predicted a new fifth state of matter at near absolute zero temperatures called:', 'Satyendra Nath Bose''s quantum statistics foundation for integral-spin particles led to the naming of ''Bosons'' and the Bose-Einstein Condensate.', NOW()) ON CONFLICT DO NOTHING;
