INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20dfcc75-11b7-4b29-a69e-2e4f60680806', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Hard', 'What is the specialized Cryogenic Upper Stage engine developed indigenously by ISRO for launching heavy communication satellites via the LVM3 (GSLV Mk-III) rocket called?', 'The CE-20 is an indigenous staged-combustion cryogenic rocket engine powering LVM3 upper stages with high specific impulse.', NOW()) ON CONFLICT DO NOTHING;
