INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6eb7c6b-0615-4091-aae5-2cb3da482397', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Hard', 'What is India''s indigenous satellite navigation constellation system developed by ISRO (equivalent to the US GPS system) officially named?', 'NavIC operates a constellation of geostationary and geosynchronous satellites providing real-time positioning across India and 1,500 km beyond.', NOW()) ON CONFLICT DO NOTHING;
