INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64341e17-a28f-432d-aff3-6a74c754eff3', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Hard', 'What is the groundbreaking scientific project that captured the FIRST EVER direct image of a Supermassive Black Hole''s event horizon (in galaxy M87) in 2019 using a global network of synchronized radio telescopes?', 'The global Event Horizon Telescope (EHT) array utilized very-long-baseline interferometry (VLBI) to resolve the shadow of M87*.', NOW()) ON CONFLICT DO NOTHING;
