INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('09474994-7fa3-4e29-b19a-203d352d09ca', 'Class 6', 'GK', 'Chapter 11: Great Inventions, Famous Scientists, Space Missions & Modern Technology', 'Hard', 'What overarching national vision guided Dr. Vikram Sarabhai when he founded India''s space programme in the 1960s?', 'Sarabhai''s doctrine dedicated space technology directly to societal upliftment: farmer communication, monsoon meteorology, and remote education.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('572b5f0f-fc51-4ae1-b456-8e4823e1f6f3', 'Using cutting-edge advanced science and space technology directly to solve real socioeconomic problems of the nation (tele-education, weather forecasting, agriculture, disaster management)', true, '09474994-7fa3-4e29-b19a-203d352d09ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4d48ca8-2422-426d-bda3-67bcf1fe0e8c', 'Building weapons to conquer other planets', false, '09474994-7fa3-4e29-b19a-203d352d09ca');
