INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6c2cb5e6-fe8c-43b5-a516-8fdd41035494', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Easy', 'What is a ''Prashasti'' in ancient Indian history?', 'Prashastis were eulogistic royal epigraphs composed in Sanskrit celebrating royal ancestry and military victories.', NOW()) ON CONFLICT DO NOTHING;
