INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43f6b214-1da3-44d6-9a90-0e5ea4db41d8', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Easy', 'Who was the court poet of Pulakeshin II who composed the famous ''Aihole Prashasti'' in Sanskrit verse on the Meguti Jain temple wall?', 'Ravikirti composed the Aihole inscription in 634 CE, describing Pulakeshin II''s military triumphs across Peninsular India.', NOW()) ON CONFLICT DO NOTHING;
