INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd12d02b-1323-48b7-89c4-bcf0b0c7378a', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Easy', 'What was the capital city of the Chalukyas, famous for its magnificent rock-cut and structural temples (like the Durga Temple)?', 'Vatapi (Badami) in the Malaprabha valley was the Chalukyan capital, with Aihole as an experimental temple architecture center.', NOW()) ON CONFLICT DO NOTHING;
