INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('071a742b-3b69-4e69-998e-d9c06ccbdc1d', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Easy', 'In the Pallava and southern kingdoms, what were local village assemblies called?', 'Southern rural administration operated through assemblies: Sabha (Brahmadeya landholders), Ur (peasant landowners), Nagaram (merchants).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9607a2bb-16a6-402b-bbb1-f271a1382054', 'Sabha (Brahmana landholders), Ur (non-Brahmana village assembly), and Nagaram (merchant guild)', true, '071a742b-3b69-4e69-998e-d9c06ccbdc1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d82d9727-3fc8-4d13-b9f7-1fb1f065b63d', 'Panchayat and Grama', false, '071a742b-3b69-4e69-998e-d9c06ccbdc1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02aef48c-efa3-4b6a-9310-7115aa86fd9b', 'Samiti and Parishad', false, '071a742b-3b69-4e69-998e-d9c06ccbdc1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2a8bf7a-f4ce-4e58-a869-6d5afde74393', 'Shreni and Sangha', false, '071a742b-3b69-4e69-998e-d9c06ccbdc1d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('44ba4039-9b95-44f4-81dc-cf2ebae0d890', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'How did Harisena in the Allahabad Prashasti describe Samudragupta''s differentiated policy towards the TWELVE rulers of ''Dakshinapatha'' (South India)?', 'Grahana-Mokshanugraha policy: Samudragupta defeated southern rulers, accepted their submission/tribute, and reinstated them.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b38c3ec-403e-4180-90fd-09e1ae792a7a', 'They surrendered after being defeated, were magnanimously liberated by Samudragupta, and allowed to rule their kingdoms again on condition of paying regular tribute and obeisance (Dharma Vijaya)', true, '44ba4039-9b95-44f4-81dc-cf2ebae0d890');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53061fd3-2f3c-49eb-a158-3fae4625d7ce', 'They were all executed and their land was destroyed', false, '44ba4039-9b95-44f4-81dc-cf2ebae0d890');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('544ea17b-9299-45d0-8373-6221797e4340', 'They were taken to Pataliputra as prisoners forever', false, '44ba4039-9b95-44f4-81dc-cf2ebae0d890');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca83b052-65c3-4dad-874c-2de15e7b6ed3', 'They were made to join the Roman army', false, '44ba4039-9b95-44f4-81dc-cf2ebae0d890');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3220eec-2265-434f-b511-d573810dfbdf', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'How did Samudragupta treat the rulers of ''Aryavarta'' (Northern Gangetic India)?', 'Prasabhoddharana policy: the 9 Gangetic Aryavarta rulers were overthrown and their lands annexed into direct Gupta governance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc77d8fe-7c68-4e5e-8846-5ee4a5af0ce7', 'Nine rulers of Aryavarta were uprooted completely and their territories were annexed directly into the Gupta Empire', true, 'd3220eec-2265-434f-b511-d573810dfbdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb863ba6-baa4-44d7-b9aa-a9ab73b3331d', 'He made peace treaties with them without war', false, 'd3220eec-2265-434f-b511-d573810dfbdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37ccdd1c-2a94-4100-ac5a-84f6eb94ca33', 'He gave them half his gold', false, 'd3220eec-2265-434f-b511-d573810dfbdf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01bc6850-52db-4309-b05c-1022f96542a6', 'He allowed them to rule independently', false, 'd3220eec-2265-434f-b511-d573810dfbdf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8fc5467a-5972-4d9e-b7ef-3c214c58208a', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'Who were the ''Samantas'' in early medieval Indian administration?', 'Samantas were feudal military vassals who maintained private retinues, remitted tribute, and revolted when central kings weakened.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('762b8abe-1af2-408e-993e-6fcd3622b57e', 'Military chieftains and feudal lords who provided armed troops to the king during war, collected local revenue, and paid tribute to the monarch', true, '8fc5467a-5972-4d9e-b7ef-3c214c58208a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('541bb027-500d-4eab-88ed-a56e353c586d', 'Foreign ambassadors from China', false, '8fc5467a-5972-4d9e-b7ef-3c214c58208a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fed1f4a9-0166-4ed5-873c-303aff0619d1', 'Buddhist monks living in caves', false, '8fc5467a-5972-4d9e-b7ef-3c214c58208a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca4db0c4-7f39-44fa-8094-2743d57d0cd0', 'Peasant farmers who ploughed land', false, '8fc5467a-5972-4d9e-b7ef-3c214c58208a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d849c85a-1142-4c74-a062-4b891cee021f', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What administrative change occurred in key government posts (such as ''Maha-danda-nayaka'' / Chief Judicial Officer) during the Gupta era?', 'Gupta bureaucracy became hereditary: sons inherited ministerial and judicial offices, concentrating local bureaucratic power.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1c29d8e-45ec-4373-a90a-a815a78fc234', 'Administrative posts became increasingly HEREDITARY (e.g. Harisena was a Maha-danda-nayaka just like his father Harisena before him)', true, 'd849c85a-1142-4c74-a062-4b891cee021f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86dfc562-4e76-43e5-b048-c47188621259', 'Officers were selected through written computer exams', false, 'd849c85a-1142-4c74-a062-4b891cee021f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf93a0c5-aff3-452a-be69-9aedcde44a7c', 'Kings replaced all officers every year', false, 'd849c85a-1142-4c74-a062-4b891cee021f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e98f5d6-20d8-4b20-b516-e2dd6106955f', 'Officers had to be Roman citizens', false, 'd849c85a-1142-4c74-a062-4b891cee021f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4953939e-471a-497a-8c43-0a8b7c9821df', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What was a single official holding MULTIPLE administrative portfolios called during the Gupta period (e.g. Harisena being a Kumaramatya, Maha-danda-nayaka, and Sandhi-vigrahika)?', 'Harisena held three concurrent ranks: Kumaramatya (minister), Maha-danda-nayaka (chief justice), and Sandhi-vigrahika (minister of war and peace).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('138388d8-5cd7-4dc6-8004-0ddca88844a3', 'Cumulation of offices (holding multiple concurrent ministerial, judicial, and diplomatic roles)', true, '4953939e-471a-497a-8c43-0a8b7c9821df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b140181-9ab7-4e1f-b0b1-d623856cf6de', 'Military dictatorship', false, '4953939e-471a-497a-8c43-0a8b7c9821df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af4bae33-ac30-4b42-a9eb-7d477423cab4', 'Feudal democracy', false, '4953939e-471a-497a-8c43-0a8b7c9821df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('493a20a6-1539-4825-bd35-3dbea2b1eecc', 'Monastic governance', false, '4953939e-471a-497a-8c43-0a8b7c9821df');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b70329b-f93d-4988-99b7-99466ec7b219', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What does the title ''Sandhi-vigrahika'' mean in Gupta administrative terminology?', '''Sandhi'' (treaty/alliance) + ''Vigraha'' (warfare): Sandhi-vigrahika handled foreign diplomacy and military treaties.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('febd90a5-6181-4ffa-8bb7-ee056b6b08c8', 'Minister of War and Peace (Foreign Affairs Minister)', true, '8b70329b-f93d-4988-99b7-99466ec7b219');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb2bae43-7da7-4121-8742-a1f0d9358292', 'Chief Police Officer', false, '8b70329b-f93d-4988-99b7-99466ec7b219');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84826da6-94c2-458a-88ba-3ef5b436617a', 'Treasury Collector', false, '8b70329b-f93d-4988-99b7-99466ec7b219');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48928b17-02a8-4e96-9083-501306d73a9f', 'Royal Cook', false, '8b70329b-f93d-4988-99b7-99466ec7b219');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ad9c6b7-89e1-446c-835b-3b58650d0109', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What magnificent monolithic rock-cut shrines (known as the ''Five Rathas'') and the Shore Temple were built by Pallava kings at:', 'Narasimhavarman I (Mamalla) sculpted the monolithic Pancha Pandava Rathas and structural Shore Temple at coastal Mahabalipuram.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7699fbf4-1124-4334-a5da-f3e9eeb73dce', 'Mahabalipuram (Mamallapuram)', true, '6ad9c6b7-89e1-446c-835b-3b58650d0109');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac9691df-20b2-4df0-8d79-db14875a851b', 'Kanchipuram', false, '6ad9c6b7-89e1-446c-835b-3b58650d0109');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f0eaeca-d094-404f-bd2c-c8c94249d2d8', 'Aihole', false, '6ad9c6b7-89e1-446c-835b-3b58650d0109');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('448d20c5-10bb-4386-9e5c-3a4c535387d3', 'Pattadakal', false, '6ad9c6b7-89e1-446c-835b-3b58650d0109');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('abc4c1f4-9a76-4786-8661-40bf4e13b007', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'How did the poet Banabhatta describe King Harshavardhana''s army marching through the countryside in ''Harshacharita''?', 'Banabhatta''s vivid prose depicts royal armies as colossal marching cities escorted by war elephants, music, and peasant offerings.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('238e0019-8d90-46e4-997f-88dd02c852a2', 'A massive traveling city with elephants carrying musicians and luggage, horses, bullock carts laden with food, while villagers rushed to offer curds, molasses, and flowers', true, 'abc4c1f4-9a76-4786-8661-40bf4e13b007');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b8a92a1-67b5-4691-8d71-6d10b28de131', 'A tiny group of 5 soldiers walking silently in dark', false, 'abc4c1f4-9a76-4786-8661-40bf4e13b007');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9932dfc0-b810-4656-8bb6-143e310c9e4a', 'Soldiers flying in balloons', false, 'abc4c1f4-9a76-4786-8661-40bf4e13b007');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7cddeec-6f40-446e-8722-19443e8e73cb', 'A fleet of ocean submarines', false, 'abc4c1f4-9a76-4786-8661-40bf4e13b007');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56e2ace6-d71c-482b-8e8d-92c5d58ae0ca', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What language did the elite king and Brahmanas speak in Kalidasa''s plays (like Abhijnanashakuntalam), while ordinary women and commoners spoke Prakrit?', 'Classical Sanskrit drama used sociolinguistic diglossia: high-status males spoke refined Sanskrit while women and commoners spoke Prakrit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7217a749-0daa-4f96-9bae-4cfe13d7be8b', 'Sanskrit', true, '56e2ace6-d71c-482b-8e8d-92c5d58ae0ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06731c14-4350-4931-8e33-a3ed03925ca0', 'Tamil', false, '56e2ace6-d71c-482b-8e8d-92c5d58ae0ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac0f6a98-7b22-4af0-981b-1b0c3be473fe', 'Greek', false, '56e2ace6-d71c-482b-8e8d-92c5d58ae0ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9573293e-9a0a-4417-9aff-b94ef89f6aa6', 'Latin', false, '56e2ace6-d71c-482b-8e8d-92c5d58ae0ca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e621b86-049a-428f-add8-351976982313', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'How did the Chinese pilgrim Fa Xian describe the miserable condition of the ''Untouchables'' (Chandalas) in 5th-century Indian cities?', 'Fa Xian''s travelogue documented rigid caste untouchability and spatial segregation enforced on Chandalas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8ecbd4d-f25d-4d86-b52b-bd54a935663a', 'They lived outside the city walls, and when entering a town or marketplace, had to strike a piece of wood to announce their presence so people could avoid touching them', true, '6e621b86-049a-428f-add8-351976982313');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37a9e2d8-4795-4028-9157-23d91d080bc0', 'They were made governors of cities', false, '6e621b86-049a-428f-add8-351976982313');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('092b7b3e-c4c8-463c-91b1-e77f2f2c7828', 'They lived in royal palaces', false, '6e621b86-049a-428f-add8-351976982313');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d6d9b0b-1d54-4601-b794-30ccd740b821', 'They were celebrated as national heroes', false, '6e621b86-049a-428f-add8-351976982313');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2b7c8b7-e6b9-4dc8-bdf5-654089f9592b', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'Who was the great astronomer and mathematician of the Gupta era who wrote the ''Aryabhatiya'', calculated the value of π (pi), and stated that the Earth rotates on its own axis?', 'Aryabhata (born 476 CE in Pataliputra) authored the Aryabhatiya, formulating earth''s axial rotation, solar/lunar eclipse math, and π = 3.1416.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0646c990-d6d6-4f72-9d77-21c695267a32', 'Aryabhata', true, 'c2b7c8b7-e6b9-4dc8-bdf5-654089f9592b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02d73a76-c54b-4044-83d1-41ac3dbf585b', 'Varahamihira', false, 'c2b7c8b7-e6b9-4dc8-bdf5-654089f9592b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('403b9086-1087-48cb-ba0d-cf38741e0101', 'Brahmagupta', false, 'c2b7c8b7-e6b9-4dc8-bdf5-654089f9592b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c3f8f94-4b6b-48c5-bcab-411864c9a926', 'Bhaskaracharya', false, 'c2b7c8b7-e6b9-4dc8-bdf5-654089f9592b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e77ef5fe-09b2-48fb-8a67-ffd28f71b1fd', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What happened to the Chalukyas and Pallavas around the 8th century CE?', 'Dantidurga founded the Rashtrakuta empire overthrowing Chalukyas, while Imperial Cholas (Vijayalaya) annexed Pallava Kanchi.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a74620e-60e2-47ef-8f11-11adb096e570', 'They were gradually replaced by new rising dynasties: the Rashtrakutas (who eclipsed the Chalukyas in the Deccan) and the Cholas (who conquered the Pallavas in Tamil country)', true, 'e77ef5fe-09b2-48fb-8a67-ffd28f71b1fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('625a639a-5afd-4ee3-b7f4-25e2040a4a0c', 'They migrated to Rome', false, 'e77ef5fe-09b2-48fb-8a67-ffd28f71b1fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72c3689e-f201-4b69-b459-20c4ec3099e8', 'They ruled India until the 20th century', false, 'e77ef5fe-09b2-48fb-8a67-ffd28f71b1fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20bede4f-8ad9-46da-acbf-23cca035c56c', 'Their cities sank into the ocean', false, 'e77ef5fe-09b2-48fb-8a67-ffd28f71b1fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8eba95d-77d8-4795-986d-66798f9c9f29', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What was the ''Sabha'' in the Pallava administrative system?', 'The Sabha governed Brahmadeya villages via specialized sub-committees (Variyams) overseeing canals, tanks, and temple charities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbb57d08-53f5-45fe-ae73-49e1cddedcce', 'An assembly of Brahmana landowners which functioned through sub-committees looking after irrigation, agricultural operations, roads, and local temples', true, 'c8eba95d-77d8-4795-986d-66798f9c9f29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed0df929-aaf7-4d90-a4eb-16743cf8a558', 'An assembly of foreign merchants', false, 'c8eba95d-77d8-4795-986d-66798f9c9f29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1b30f00-2038-48a3-ace9-317af2213b7d', 'A court of musicians', false, 'c8eba95d-77d8-4795-986d-66798f9c9f29');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('522d0c93-efb7-43fd-9335-4318a782c06f', 'An army unit of war elephants', false, 'c8eba95d-77d8-4795-986d-66798f9c9f29');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68b58d85-3a0d-4159-b4e1-b1b0407cc22a', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What was the ''Nagaram'' in southern kingdoms?', 'Nagaram represented mercantile corporations managing marketplaces, commercial taxes, and civic affairs in commercial hubs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cc4da33-efa6-4257-813c-7104a3ef5694', 'An organization and guild council of merchants that managed urban commerce and civic administration in trading towns', true, '68b58d85-3a0d-4159-b4e1-b1b0407cc22a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55fa3a3d-0e15-42d9-af6b-baf6221e05d1', 'A village of farmers', false, '68b58d85-3a0d-4159-b4e1-b1b0407cc22a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fff5a070-c19b-4511-bb9e-7ecadbc5348d', 'A school for archery', false, '68b58d85-3a0d-4159-b4e1-b1b0407cc22a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df58419b-37d6-4ed4-9a46-964bdffe44b8', 'A palace treasury', false, '68b58d85-3a0d-4159-b4e1-b1b0407cc22a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6a3e7319-5f2b-4cf8-a468-790013b8a49c', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'Why was the invention of the mathematical ''Zero'' (Shunya) and the Decimal System in India during this period a monumental gift to world civilization?', 'The Indian invention of zero and place-value decimal notation revolutionized global computational mathematics and algorithmic science.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b264cfb-f268-411e-86b6-f5b183ac3204', 'It simplified mathematical calculations, enabled positional place-value arithmetic, and was adopted by Arab mathematicians who transmitted it to Europe as ''Hindu-Arabic numerals''', true, '6a3e7319-5f2b-4cf8-a468-790013b8a49c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f288108-f425-48e1-9f01-fecc9dd44f64', 'Because zero was used as a weapon in war', false, '6a3e7319-5f2b-4cf8-a468-790013b8a49c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a8f5e02-4920-452f-abc6-c914087f8e26', 'Because it stopped money from being spent', false, '6a3e7319-5f2b-4cf8-a468-790013b8a49c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f38c59b9-114a-4949-bf1c-847027182bda', 'Because it was carved on all swords', false, '6a3e7319-5f2b-4cf8-a468-790013b8a49c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8213ab7f-380e-4c11-bf29-9418ca981374', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Medium', 'What medical treatise on surgery and surgical instruments was authored in ancient India by the father of plastic surgery?', 'Sushruta pioneered rhinoplasty, cataract surgery, and over 120 surgical instruments in the ''Sushruta Samhita''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e109c3ae-06c3-477c-9953-391e8a9187da', 'Sushruta Samhita (by Sushruta)', true, '8213ab7f-380e-4c11-bf29-9418ca981374');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8976a36f-e520-4fe1-a91c-8e5f16d19f89', 'Charaka Samhita', false, '8213ab7f-380e-4c11-bf29-9418ca981374');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('169a47d6-ade6-4148-8ff5-388878387b1e', 'Aryabhatiya', false, '8213ab7f-380e-4c11-bf29-9418ca981374');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('671640fb-2163-47dd-9eee-8ce9819e1601', 'Brihat Samhita', false, '8213ab7f-380e-4c11-bf29-9418ca981374');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ea95a91-7cdc-4d56-b9aa-26e5d2abf231', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'Read the statements:
