INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e902a55-838b-4a22-9881-e0d6bb5e65fc', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'Spot the IMPOSTER in the following group of ancient rulers matched with their royal court biographers/poets:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12ebcc56-2d64-4b27-9b1c-53f9c28efa7e', 'Samudragupta - Harisena', false, '1e902a55-838b-4a22-9881-e0d6bb5e65fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d5bf237-82d3-4cbb-abd3-adc172ebb4f7', 'Harshavardhana - Banabhatta', false, '1e902a55-838b-4a22-9881-e0d6bb5e65fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('447fb4d2-81ea-406c-b90b-92c600d44181', 'Pulakeshin II - Ravikirti', false, '1e902a55-838b-4a22-9881-e0d6bb5e65fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b62c99b-b72f-49d9-8546-803512ee9d25', 'Chandragupta I - Megasthenes', true, '1e902a55-838b-4a22-9881-e0d6bb5e65fc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06c295ef-c286-46b9-9931-ec1b3d1e4bc5', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'Analyze the four distinct geographic zones of conquest detailed by Harisena in Samudragupta''s Prayag Prashasti:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dce7ff1b-a936-49b8-8f4e-a0f29817129c', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '06c295ef-c286-46b9-9931-ec1b3d1e4bc5');
