INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba7f3dfd-4fa1-4bd5-a54d-51b06a0f7a65', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '06c295ef-c286-46b9-9931-ec1b3d1e4bc5');
