INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a8c2ab03-fd76-4966-a347-611b563c3d43', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'Match Column I (Ancient Dynasties) with Column II (Prominent Capitals / Royal Centers):
(a) Guptas     -> (i) Pataliputra and Ujjain
(b) Pushyabhuti-> (ii) Kannauj and Thanesar
(c) Chalukyas  -> (iii) Vatapi (Badami) and Aihole
(d) Pallavas   -> (iv) Kanchipuram and Mahabalipuram', 'Guptas = Pataliputra/Ujjain; Harsha = Kannauj; Chalukyas = Badami; Pallavas = Kanchipuram.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b76003f7-b365-4c65-afdd-6dfb251f4f04', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'a8c2ab03-fd76-4966-a347-611b563c3d43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5749b757-5e67-44f3-9726-e4264665992d', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'a8c2ab03-fd76-4966-a347-611b563c3d43');
