INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecebbf40-7d0b-4608-bbb9-657e778629bf', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'Read the statements regarding classical Indian science:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4c38aba-dc55-4442-bb38-a89578b875c2', 'Statements 1 and 2 only', true, 'ecebbf40-7d0b-4608-bbb9-657e778629bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78bec9a8-d5e4-4ee3-acfc-d841fbaa0b09', 'Statements 2 and 3 only', false, 'ecebbf40-7d0b-4608-bbb9-657e778629bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('069a6fc2-136c-434b-b8ab-d0bb804eb142', 'Statements 1 and 3 only', false, 'ecebbf40-7d0b-4608-bbb9-657e778629bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fa69b6c-601f-4b1e-b786-5bd0c793f56f', 'All Statements 1, 2, and 3', false, 'ecebbf40-7d0b-4608-bbb9-657e778629bf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f13661ca-2559-4843-b36f-72b4c3e27758', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'What dramatic story of social justice is depicted in Kalidasa''s play ''Abhijnanashakuntalam'' involving a poor Fisherman and the King''s signet ring?', 'Kalidasa''s fisherman scene critiques lower-level police bribery and class prejudice in ancient royal administration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7730504-7c45-4365-8409-03518b589bc5', 'A poor fisherman found the king''s lost signet ring inside a fish belly; police officers falsely accused him of theft and beat him until the king recognized the ring and rewarded the fisherman, exposing systemic judicial corruption and prejudice against the poor', true, 'f13661ca-2559-4843-b36f-72b4c3e27758');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0abcb5e6-bc6d-4415-9e0d-2820216e97ca', 'The fisherman became king', false, 'f13661ca-2559-4843-b36f-72b4c3e27758');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce30e3bf-efef-4a4f-a07d-84737a3d9aff', 'The king threw the ring into fire', false, 'f13661ca-2559-4843-b36f-72b4c3e27758');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74f8850b-2a7e-4bc9-aa0e-76f80bff4c65', 'The fish turned into gold', false, 'f13661ca-2559-4843-b36f-72b4c3e27758');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e97079a7-b9da-48d0-a5b5-bfba3bbe9d4d', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'What metallurgical feature of the 4th-century CE Iron Pillar of Delhi at Mehrauli prevents it from rusting even after 1,600 years of exposure to sun and monsoon rains?', 'Solid-state forge welding with high-phosphorus slag formed a catalytic protective misawite barrier shielding against corrosion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5365188a-dabb-4e9c-a059-0e39504a4334', 'High phosphorus content in forge-welded wrought iron which formed a protective passive amorphous iron hydrogen phosphate film (''misawite'') on the metal surface', true, 'e97079a7-b9da-48d0-a5b5-bfba3bbe9d4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6efb3c3d-95b3-4ce8-9c0e-e212d265fd10', 'It is painted with modern plastic paint', false, 'e97079a7-b9da-48d0-a5b5-bfba3bbe9d4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b9208b2-bdc9-46c3-8060-5045184f2474', 'It is made of pure gold inside', false, 'e97079a7-b9da-48d0-a5b5-bfba3bbe9d4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ec5bcf8-d9cf-4aa4-a47e-18baeda763b8', 'It is kept inside an air-conditioned room', false, 'e97079a7-b9da-48d0-a5b5-bfba3bbe9d4d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f2fda723-393a-47cc-a554-120d6b68085a', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'Consider four prominent rulers of classical India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db22b907-b1c7-474d-b6c6-9d2c353d2b1d', 'Rulers 3 and 4 (Harshavardhana and Pulakeshin II)', true, 'f2fda723-393a-47cc-a554-120d6b68085a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de67a0d3-f138-4a8c-b38d-11dd1784f27b', 'Rulers 1 and 2', false, 'f2fda723-393a-47cc-a554-120d6b68085a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28bf05b4-38ad-4f9a-96d7-5ee665a65529', 'Rulers 1 and 3', false, 'f2fda723-393a-47cc-a554-120d6b68085a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d55ac12-e1b1-419f-b4af-c062322d800c', 'Rulers 2 and 4', false, 'f2fda723-393a-47cc-a554-120d6b68085a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f532c79-e2fe-4984-afc9-ee14c558aaae', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'What socio-economic power did the Assemblies (Sabhas and Urs) hold in early medieval South India?', 'Southern assemblies exercised extensive fiscal, judicial, and civic self-governance over land tenure and infrastructure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d83bf739-2972-4bd4-a91c-3557cc860e66', 'They levied local agricultural taxes, maintained communal irrigation tanks, managed village dispute courts, and acted as autonomous corporate governing bodies', true, '0f532c79-e2fe-4984-afc9-ee14c558aaae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3792e341-4e93-4b57-b30c-fac6987eb02f', 'They had no power and followed only royal orders', false, '0f532c79-e2fe-4984-afc9-ee14c558aaae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('691fe96c-f37b-4bcd-af1e-b270a9f832b7', 'They were only allowed to sing prayers', false, '0f532c79-e2fe-4984-afc9-ee14c558aaae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe70a70b-4688-46f2-ac60-f8c25907ebe7', 'They were made of royal soldiers only', false, '0f532c79-e2fe-4984-afc9-ee14c558aaae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67dbaedb-425e-4cf9-9542-c300edb6fd7b', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'How did the genealogical lineages (Vamshavalis) recorded in Prashastis help historians reconstruct ancient Indian history?', 'Epigraphic genealogies reconstruct dynastic chronologies, matrimonial alliances (Gupta-Licchavi), and political succession.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8159fc0b-6bbc-4942-acca-8ca868da709c', 'They provide sequential lists of royal ancestors (father, grandfather, great-grandfather) and maternal alliances (e.g. Samudragupta''s mother Kumara Devi was a Licchavi princess), establishing chronology', true, '67dbaedb-425e-4cf9-9542-c300edb6fd7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e51a13ad-ae79-4c15-9585-152902f3f26f', 'They provide recipes for ancient food', false, '67dbaedb-425e-4cf9-9542-c300edb6fd7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0432c48f-1624-4789-8fbf-7e3240f0ea01', 'They describe stars in astronomy', false, '67dbaedb-425e-4cf9-9542-c300edb6fd7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e1f6650-a87e-4b5e-a975-4ad833ef65d4', 'They list animal species', false, '67dbaedb-425e-4cf9-9542-c300edb6fd7b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('12368751-01bb-42e6-9e6c-21a4cc2ddbbb', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'Why did Chinese pilgrim Xuan Zang spend extensive time studying at King Harsha''s grand assemblies at Kannauj and Prayag in 643 CE?', 'Harsha convened 18-day theological assemblies at Kannauj and the grand quinquennial Mahamoksha festival at Prayag.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e06640e0-4474-4471-b809-644a8cab7466', 'To participate in inter-religious philosophical disputations between Buddhist scholars, Vedic Brahmanas, and Jain thinkers under Harsha''s royal patronization', true, '12368751-01bb-42e6-9e6c-21a4cc2ddbbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b204249e-b974-4e29-9599-39f7e75fdb17', 'To purchase silk for China', false, '12368751-01bb-42e6-9e6c-21a4cc2ddbbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('653668dc-4d7b-4495-a2fb-1e690b4cdc5d', 'To recruit soldiers for the Chinese army', false, '12368751-01bb-42e6-9e6c-21a4cc2ddbbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14106f80-aa78-4e53-bea3-232b0cfc1e25', 'To build a stone castle', false, '12368751-01bb-42e6-9e6c-21a4cc2ddbbb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41e3aeb4-d31d-40d9-a581-cd90bd431e34', 'Class 6', 'Social Science', 'Chapter 11: New Empires and Kingdoms', 'Hard', 'What holistic view of Indian classical civilization is established in Chapter 11 of NCERT History?', 'The chapter portrays classical India''s golden synthesis of scientific breakthroughs, soaring literature, temple architecture, and grassroots assemblies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1971ce2e-72c8-4437-8232-783aaa14fb3d', 'A golden era of artistic, literary, scientific, and architectural brilliance flourishing alongside complex feudal political networks and vibrant local democratic village institutions', true, '41e3aeb4-d31d-40d9-a581-cd90bd431e34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd83e051-298d-4157-b251-1f548fa49487', 'A period of complete societal collapse', false, '41e3aeb4-d31d-40d9-a581-cd90bd431e34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e572e45-2d38-4914-b707-8d9708fb9019', 'A primitive era without science or art', false, '41e3aeb4-d31d-40d9-a581-cd90bd431e34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bbb8819-9a95-4fb7-9fb3-4a2b6dc404fa', 'A civilization isolated from the rest of Asia', false, '41e3aeb4-d31d-40d9-a581-cd90bd431e34');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1b36564-172b-464c-9876-b8b071700d57', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Easy', 'क्रिया के जिस रूप से उसके संपन्न होने के समय (Time of Action) का बोध होता है, उसे व्याकरण में क्या कहते हैं?', 'क्रिया के होने या करने के समय तथा उसकी पूर्णता/अपूर्णता का बोध कराने वाले रूप को ''काल'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f87c311-b878-4f17-9e33-ab82012546fe', 'काल (Tense)', true, 'e1b36564-172b-464c-9876-b8b071700d57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8df9f82-7d24-4758-b0e5-91c191e315c0', 'कारक', false, 'e1b36564-172b-464c-9876-b8b071700d57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('222016c6-a334-43bf-81b9-73f7753a33ef', 'वाच्य', false, 'e1b36564-172b-464c-9876-b8b071700d57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44dd7cb5-b9f6-4e2d-a050-7430b10b0162', 'समास', false, 'e1b36564-172b-464c-9876-b8b071700d57');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8510abc6-0b31-4d5a-988e-dbd5d4e00043', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Easy', 'हिंदी व्याकरण में काल के मुख्य रूप से कितने भेद होते हैं?', 'काल के 3 मुख्य भेद हैं: भूतकाल (बीता हुआ समय), वर्तमानकाल (चल रहा समय), और भविष्यत् काल (आने वाला समय)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ce7600e-a67b-4680-b24f-0fee27e65dda', 'तीन भेद (1. भूतकाल - Past, 2. वर्तमानकाल - Present, 3. भविष्यत् काल - Future)', true, '8510abc6-0b31-4d5a-988e-dbd5d4e00043');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c77ced7b-c0a0-448d-b3af-455686d38835', 'चार भेद', false, '8510abc6-0b31-4d5a-988e-dbd5d4e00043');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0482e6dc-c9ac-4c84-9ff2-383dfa9fb894', 'दो भेद', false, '8510abc6-0b31-4d5a-988e-dbd5d4e00043');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b794799-a82f-4963-97b4-83b21b000581', 'पाँच भेद', false, '8510abc6-0b31-4d5a-988e-dbd5d4e00043');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a417ccf-1446-4f29-94dc-c7049cfcf245', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Easy', 'क्रिया के जिस रूप से यह पता चले कि कार्य बीते हुए समय में संपन्न हो चुका है (जैसे: ''राम ने पत्र लिखा'', ''वह कल आया था''), उसे क्या कहते हैं?', 'बीते हुए समय में क्रिया के निष्पादन को ''भूतकाल'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('582ad614-36d6-4b35-8a1f-8b1726ffb4c7', 'भूतकाल (Past Tense)', true, '8a417ccf-1446-4f29-94dc-c7049cfcf245');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ec5f581-ef54-4d66-b515-68eb6b51be78', 'वर्तमानकाल', false, '8a417ccf-1446-4f29-94dc-c7049cfcf245');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56326392-2628-413d-9ac0-f1ab72514175', 'भविष्यत् काल', false, '8a417ccf-1446-4f29-94dc-c7049cfcf245');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efc7fa81-73ae-4e2d-a07f-17353872d3c2', 'आज्ञाकाल', false, '8a417ccf-1446-4f29-94dc-c7049cfcf245');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bef29ec3-a748-40e3-b316-5d7639ff5284', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Easy', 'क्रिया के जिस रूप से कार्य के वर्तमान (चल रहे) समय में होने का बोध होता है (जैसे: ''रोहन पढ़ता है'', ''वर्षा हो रही है''), उसे क्या कहते हैं?', 'वर्तमान समय में क्रिया के व्यापार का बोध ''वर्तमानकाल'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4f68f6e-e8ea-49de-a67c-ebac061a5eb9', 'वर्तमानकाल (Present Tense)', true, 'bef29ec3-a748-40e3-b316-5d7639ff5284');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92ff38e1-889b-42cc-9f86-31ab8dc5d9d5', 'भूतकाल', false, 'bef29ec3-a748-40e3-b316-5d7639ff5284');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('430865c9-47b3-4299-a7db-2bb59225f369', 'भविष्यत् काल', false, 'bef29ec3-a748-40e3-b316-5d7639ff5284');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c30524a2-7e06-44c3-a675-3fb50dda1ec5', 'हेतुहेतुमद् काल', false, 'bef29ec3-a748-40e3-b316-5d7639ff5284');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('69ebde13-77ee-4bf1-af88-049f6f8d26aa', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Easy', 'क्रिया के जिस रूप से कार्य के आने वाले समय में होने का बोध होता है (जैसे: ''हम कल चिड़ियाघर जाएँगे'', ''वह कल पढ़ेगा''), उसे क्या कहते हैं?', 'आगामी समय में क्रिया के संपादन का बोध ''भविष्यत् काल'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5b1c631-cbec-4749-9867-d723e2428ace', 'भविष्यत् काल (Future Tense)', true, '69ebde13-77ee-4bf1-af88-049f6f8d26aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfd4ef00-1aa3-4c23-939c-b44a1b61ac41', 'वर्तमानकाल', false, '69ebde13-77ee-4bf1-af88-049f6f8d26aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9997720-aff7-4abb-b6ca-33d4b0f4fba3', 'भूतकाल', false, '69ebde13-77ee-4bf1-af88-049f6f8d26aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('106352a5-b9af-48e7-9ba7-f67e793e6ee1', 'सामान्य भूतकाल', false, '69ebde13-77ee-4bf1-af88-049f6f8d26aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b1ea6c8a-cee7-4fdb-9d39-382d00c51160', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Easy', 'हिंदी में भूतकाल के कुल कितने भेद होते हैं?', 'भूतकाल के 6 भेद हैं: 1. सामान्य, 2. आसन्न, 3. पूर्ण, 4. अपूर्ण, 5. संदिग्ध, 6. हेतुहेतुमद् भूत।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('921e5587-ffd7-41f4-be18-0811c67f87ec', 'छह भेद (6 Types: सामान्य, आसन्न, पूर्ण, अपूर्ण, संदिग्ध, हेतुहेतुमद् भूत)', true, 'b1ea6c8a-cee7-4fdb-9d39-382d00c51160');
