INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b985e562-a846-477a-aef5-36ec1bdd09c7', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Medium', 'क्रिया के जिस रूप से यह पता चले कि कार्य अभी-अभी कुछ ही समय पहले समाप्त हुआ है (जैसे: ''मैंने अभी-अभी चाय पी है'', ''गाड़ी स्टेशन पर आई है''), उसे क्या कहते हैं?', 'निकटवर्ती बीते समय में अभी-अभी पूर्ण हुई क्रिया ''आसन्न भूतकाल'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
