INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61e80834-dcde-403a-a7f5-853187fa5f66', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Medium', 'क्रिया के जिस रूप से भूतकाल में कार्य के होने में संदेह (Doubt) प्रकट हो (जैसे: ''बस छूट गई होगी'', ''उसने खाना खा लिया होगा''), उसे क्या कहते हैं?', 'बीते समय में क्रिया की सिद्धि पर अनिश्चय/संदेह होने पर ''संदिग्ध भूतकाल'' होता है (गया होगा, पढ़ी होगी)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e700ee23-7e29-4365-9b6c-f39f7ea268c5', 'संदिग्ध भूतकाल (Suspicious / Probable Past)', true, '61e80834-dcde-403a-a7f5-853187fa5f66');
