INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93e4ebe6-4d8c-4394-b96a-ae6fb55f75bd', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Medium', 'जहाँ भूतकाल की एक क्रिया दूसरी क्रिया के होने पर निर्भर (conditional) थी किन्तु कार्य संपन्न नहीं हो सका (जैसे: ''यदि वर्षा होती, तो फसल अच्छी होती'', ''यदि परिश्रम करते, तो सफल हो जाते''), वहाँ कौन-सा काल होता है?', 'कारण-कार्य पर आश्रित अधूरी रह गई भूतकालीन क्रिया ''हेतुहेतुमद् भूतकाल'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
