INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d89932b-62f0-4d7b-a79a-95ba52c4e809', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Medium', 'क्रिया के जिस रूप से आने वाले समय में कार्य के होने की संभावना या इच्छा प्रकट हो (जैसे: ''शायद आज शाम वर्षा हो'', ''संभव है वह कल आए''), उसे क्या कहते हैं?', 'भविष्य में कार्य की केवल संभावना (शायद, संभवतः) प्रकट करने वाला रूप ''संभाव्य भविष्यत्'' है।', NOW()) ON CONFLICT DO NOTHING;
