INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f0e5416-0a08-4fe2-8c3b-b4b5944668ca', 'Class 6', 'Hindi Grammar', 'Chapter 11: काल', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b960097-b420-49c5-a93b-0c67de1bdaf7', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '4f0e5416-0a08-4fe2-8c3b-b4b5944668ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c978428b-930a-4689-ae0d-20493da65086', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '4f0e5416-0a08-4fe2-8c3b-b4b5944668ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92dfeba0-88ad-40bd-9b71-42665936c8b0', '(A) सही है, परन्तु (R) गलत है।', false, '4f0e5416-0a08-4fe2-8c3b-b4b5944668ca');
