INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d8fe82a-f7a0-4e40-b357-671f3e594693', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'The method of preparing rich compost from organic waste using specialized ''Redworms'' (Eisenia fetida) is called:', 'Vermicomposting uses epigeic redworms (Eisenia fetida) to bio-convert organic waste into vermicast fertilizer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eabbe19c-5f78-420d-bb36-4c146090de58', 'Vermicomposting', true, '2d8fe82a-f7a0-4e40-b357-671f3e594693');
