INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7040abe7-39d7-4063-9a5b-ba52f696be1b', 'Incineration', false, '2d8fe82a-f7a0-4e40-b357-671f3e594693');
