INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('822145c2-8890-4151-892c-73a598979ef2', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'What color dustbin is designated by municipalities for collecting BIODEGRADABLE wet kitchen waste, fruit peels, and animal waste?', 'Green bins collect biodegradable organic kitchen wet waste destined for community composting.', NOW()) ON CONFLICT DO NOTHING;
