INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f65a5bbe-9f79-47af-9eb3-5e7c086e418c', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'What color dustbin is designated by municipalities for collecting RECYCLABLE dry waste (plastics, metals, glass, paper)?', 'Blue bins collect non-biodegradable dry recyclable items like plastic bottles, glass, and metals.', NOW()) ON CONFLICT DO NOTHING;
