INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7c64a20a-f09e-4905-a10f-704a2ede9732', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'What specialized internal muscular organ do Redworms possess to grind their food in the absence of true teeth?', 'Redworms lack teeth; food is ground in a muscular gizzard aided by ingested mineral grit particles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('003dca3b-c2ca-46e9-8ac8-ad9998a2d815', 'Gizzard (which uses swallowed sand/grit particles to grind food)', true, '7c64a20a-f09e-4905-a10f-704a2ede9732');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('917faa66-039b-486a-b9a2-a3c1dfbeb3c8', 'Stomach', false, '7c64a20a-f09e-4905-a10f-704a2ede9732');
