INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5ff6fc4-ec5f-4973-8f47-7c37622fd725', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'What are the famous ''3 Rs'' of modern solid waste management and environmental conservation?', 'The 3Rs hierarchy prioritizes: 1. Reduce consumption, 2. Reuse items, and 3. Recycle discarded materials.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34f34aff-864f-4b71-9d81-a1bffac87c28', 'Reduce, Reuse, Recycle', true, 'c5ff6fc4-ec5f-4973-8f47-7c37622fd725');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1297f8f3-39e0-4922-bc89-42dddc291cb0', 'Read, Record, Remember', false, 'c5ff6fc4-ec5f-4973-8f47-7c37622fd725');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92d80e77-b893-40b3-999c-6cc2101f4d63', 'Run, Rest, Repeat', false, 'c5ff6fc4-ec5f-4973-8f47-7c37622fd725');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71676ac5-bb07-40c9-89d7-e1e2844f14a5', 'Remove, Repair, Replace', false, 'c5ff6fc4-ec5f-4973-8f47-7c37622fd725');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32fcbe23-0397-4ea8-9bb4-db244a0f8413', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'Which of the following household waste items CAN be easily recycled into fresh new paper in a classroom?', 'Waste cellulose paper pulp can be soaked, meshed, strained on wire frames, and dried into recycled paper.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a6be095-2f45-4000-81b8-6d438c77ddf7', 'Old newspapers, magazines, and used notebook paper', true, '32fcbe23-0397-4ea8-9bb4-db244a0f8413');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfac5a44-757f-4765-aed0-e22544139ecb', 'Plastic carry bags', false, '32fcbe23-0397-4ea8-9bb4-db244a0f8413');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6db3beb-b46a-4588-b021-8bbbddfd0f3c', 'Glass bottles', false, '32fcbe23-0397-4ea8-9bb4-db244a0f8413');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('709b1d6f-8067-4178-9f9c-37f96abdf9ac', 'Broken ceramic cups', false, '32fcbe23-0397-4ea8-9bb4-db244a0f8413');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bbf889fc-9188-41cb-87e7-17221dad2a16', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'Why should we NEVER burn dry fallen leaves, plastic waste, or synthetic garbage in open streets?', 'Incomplete combustion of plastics and biomass releases toxic dioxins, furans, PM2.5, and carbon monoxide.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d074f9f-a0aa-4e08-836b-b1b2fb86c956', 'Open burning releases highly toxic smoke, cancer-causing dioxins, and particulate matter that cause severe respiratory illnesses and air pollution', true, 'bbf889fc-9188-41cb-87e7-17221dad2a16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('726df729-61c2-41ce-91b2-d620f0ccc052', 'Because ash turns into gold', false, 'bbf889fc-9188-41cb-87e7-17221dad2a16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac6b024e-c2f4-445e-95e2-7a8f8e53c3c5', 'Because fire makes the ground too cold', false, 'bbf889fc-9188-41cb-87e7-17221dad2a16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8873d39-0b1a-47b7-8983-53ae84b33bd3', 'Because fire destroys the sun', false, 'bbf889fc-9188-41cb-87e7-17221dad2a16');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d0cf45b-a3de-4d45-9a8d-4bd9330a92fd', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Easy', 'What eco-friendly shopping bag should we use instead of single-use polythene plastic bags?', 'Jute and woven cotton bags are reusable, durable, renewable, and 100% biodegradable.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5b31015-606b-4b8b-9beb-4b1af5d2156b', 'Bags made of Cloth, Jute, or recycled Paper', true, '0d0cf45b-a3de-4d45-9a8d-4bd9330a92fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df59c2d8-fdda-4f58-9fd8-a644313f51c9', 'Thicker plastic bags', false, '0d0cf45b-a3de-4d45-9a8d-4bd9330a92fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('813b1c59-78e9-4d40-9eee-dde5ebcbd370', 'Aluminium foil bags', false, '0d0cf45b-a3de-4d45-9a8d-4bd9330a92fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd2b1d81-da7a-4725-b73c-f265d35b0b0a', 'Thermocol boxes', false, '0d0cf45b-a3de-4d45-9a8d-4bd9330a92fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('701aa7e0-6592-4231-ae5d-205ff883fc80', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'Why is putting cooked food with salt, oil, vinegar, or meat/dairy products into a Vermicomposting pit strictly avoided?', 'Saline, acidic, and fatty animal wastes rot pathogenically and destroy the neutral pH micro-habitat of redworms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96fde6d4-7869-4bac-8239-77c0313dd6f3', 'Oils, spices, and animal meats attract harmful disease-causing bacteria, foul smell, and pests (rats, ants) that can kill the redworms', true, '701aa7e0-6592-4231-ae5d-205ff883fc80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e95cefa2-0cf0-4950-9f0e-5058b60d513d', 'Because worms become too fat', false, '701aa7e0-6592-4231-ae5d-205ff883fc80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4201b188-9578-46c1-ae61-df49d60ed015', 'Because salt makes compost too sweet', false, '701aa7e0-6592-4231-ae5d-205ff883fc80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0bafb3a-6273-4d7f-b07f-de03bc966b94', 'Because redworms only eat ice', false, '701aa7e0-6592-4231-ae5d-205ff883fc80');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4516b449-a114-4c60-9334-76de88506557', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'What ideal physical environmental conditions are required inside a vermicompost pit for redworms to thrive?', 'Redworms require 60–80% moisture, loose organic bedding, and 15–25°C ambient temperature for optimal digestion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e6a07a5-74fd-4782-9f5f-b458943f495e', 'Moist, shaded, and well-aerated bedding (loose soil, wire mesh/sand base) with moderate temperature (neither too hot nor freezing cold)', true, '4516b449-a114-4c60-9334-76de88506557');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93128fbd-f883-439f-8a08-c4a6bd15d6ec', 'Direct scorching sunlight with boiling water', false, '4516b449-a114-4c60-9334-76de88506557');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f1d3986-6a37-4001-a3bc-690d9a043c30', 'Bone-dry gravel in total darkness', false, '4516b449-a114-4c60-9334-76de88506557');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fae7917-ba1d-4f64-80e8-f776e0a85638', 'Submerged in deep standing water', false, '4516b449-a114-4c60-9334-76de88506557');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bde305ea-ab83-48e8-aabb-54a4b12fe2b9', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'Why do stray cows and street animals often choke and die after scavenging from open garbage dumps?', 'Plastic bags containing food scraps are swallowed whole by ruminants, causing fatal gastrointestinal impaction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7a7db7a-9559-4a75-b156-b3d497546409', 'They swallow discarded polythene plastic bags filled with leftover food; the indigestible plastic accumulates in their rumen stomach, blocking digestion lethally', true, 'bde305ea-ab83-48e8-aabb-54a4b12fe2b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac7dd281-7316-4060-bc20-234e76334454', 'Because garbage is too heavy', false, 'bde305ea-ab83-48e8-aabb-54a4b12fe2b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d64d224-a8a4-41d6-9b61-db7eb3cf8122', 'Because they drink rain water', false, 'bde305ea-ab83-48e8-aabb-54a4b12fe2b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e49d840c-0774-4e2f-b4df-7517a83f401b', 'Because cows cannot chew food', false, 'bde305ea-ab83-48e8-aabb-54a4b12fe2b9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9e0b670-38da-4695-9c6e-6e7053bd3c6b', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'How does a city municipal corporation transform an old, completely filled landfill site after 20 years?', 'Decommissioned landfills (e.g. Indraprastha Millennium Park in Delhi) are converted into parks due to soil settlement and methane venting.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d824532-eff7-4b17-924a-b604bba8ad56', 'It is sealed with thick clay capping and topsoil and converted into a green public recreational park or playground (no heavy buildings are built for decades)', true, 'a9e0b670-38da-4695-9c6e-6e7053bd3c6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a487366-f8c4-4b35-b7b6-7b3e40c5ae5f', 'It is turned into a deep lake', false, 'a9e0b670-38da-4695-9c6e-6e7053bd3c6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58937f22-d458-4aa9-aaa4-68f56d673a45', 'High-rise glass skyscrapers are built immediately', false, 'a9e0b670-38da-4695-9c6e-6e7053bd3c6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0217b4c-29cb-425f-8582-4655c9817ed2', 'It is dug up and thrown into the sea', false, 'a9e0b670-38da-4695-9c6e-6e7053bd3c6b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d891e40c-70ec-4e2f-9533-c07258cc642e', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'Why are single-use plastic bags and thermocol disposable cups a major cause of urban flash floods during monsoons?', 'Non-biodegradable plastic debris physically chokes stormwater culverts and sewer conduits, triggering severe street waterlogging.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b764159-b1c0-4b16-b03e-8caea9ea10fc', 'Carelessly discarded plastic litter is washed into roadside drains and sewage pipes, clogging municipal drainage and causing dirty water overflow', true, 'd891e40c-70ec-4e2f-9533-c07258cc642e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7aa8bffb-f5e7-4173-a620-1220e0300794', 'Because plastic produces rain clouds', false, 'd891e40c-70ec-4e2f-9533-c07258cc642e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2ce7f1c-dc83-4a5e-9a02-72a2b92ee17c', 'Because plastic absorbs all water', false, 'd891e40c-70ec-4e2f-9533-c07258cc642e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdfa28cb-2c6d-474e-8c62-3cdc3debb6cf', 'Because plastic makes drains too clean', false, 'd891e40c-70ec-4e2f-9533-c07258cc642e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4d131a2-0d04-4675-b1ed-1f1212f7c96f', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'What is the primary ecological benefit of practicing ''Waste Segregation at Source'' (in every household)?', 'Source separation segregates organic feedstock for bioconversion while keeping recyclables uncontaminated.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42b9b05f-777c-405a-b10c-957ee74a3166', 'It prevents recyclable dry materials from getting contaminated by rotting wet waste, maximizing recycling efficiency and enabling clean composting', true, 'f4d131a2-0d04-4675-b1ed-1f1212f7c96f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee072dea-7232-4c99-9f01-dddbe615ac90', 'It makes garbage look beautiful', false, 'f4d131a2-0d04-4675-b1ed-1f1212f7c96f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23307906-c16a-4530-ae2a-0af2a56b961c', 'It reduces the weight of food', false, 'f4d131a2-0d04-4675-b1ed-1f1212f7c96f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61b73cb3-7928-48d7-8763-ea5407f17a66', 'It stops garbage from producing heat', false, 'f4d131a2-0d04-4675-b1ed-1f1212f7c96f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6453a142-98be-4c55-945c-00c1dd638367', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'Why is Vermicompost (vermicast) considered superior to synthetic chemical fertilizers for agricultural soil?', 'Vermicompost provides bioavailable N-P-K, humic acids, and beneficial soil mycorrhizae without chemical soil salinization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bbf95a7-7a4a-47d5-a78c-ab5525cd7d01', 'It enhances soil microbial biodiversity, improves water retention, enriches soil structure naturally without chemical leaching or soil toxicity', true, '6453a142-98be-4c55-945c-00c1dd638367');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc924e35-f2e6-4565-be33-6546156c745f', 'It kills all earthworms in the farm', false, '6453a142-98be-4c55-945c-00c1dd638367');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0b55750-ff63-455e-aca0-ed28b53b5f9a', 'It makes soil completely dry', false, '6453a142-98be-4c55-945c-00c1dd638367');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('005e95b5-10ee-496f-a69e-30962abbe6d6', 'It changes plant color to purple', false, '6453a142-98be-4c55-945c-00c1dd638367');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2c7ddd8-c28d-4236-9141-b5be9f423fa9', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'How can students easily make recycled decorative paper sheets at home or school?', 'Handmade papermaking meshes soaked recycled cellulose pulp onto deckle frames, creating textured artisan sheets.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23f05b34-10f4-4e99-a858-4bdd89cc3bd2', 'Tear waste paper into shreds, soak in water to make thick pulp, spread evenly over a wire mesh frame, press out excess water, decorate with dried flower petals, and sun dry', true, 'c2c7ddd8-c28d-4236-9141-b5be9f423fa9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23025c35-0a74-4d55-9c52-ee600017d18c', 'Melt plastic bottles in an oven', false, 'c2c7ddd8-c28d-4236-9141-b5be9f423fa9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('243bb15f-58c1-498c-8047-8029d32e90c9', 'Burn paper and mix ash with water', false, 'c2c7ddd8-c28d-4236-9141-b5be9f423fa9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84417547-052c-4918-bcef-005ec7589edc', 'Paint old wood with oil', false, 'c2c7ddd8-c28d-4236-9141-b5be9f423fa9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1eb45db8-c268-47b2-840f-4ea6a7894a42', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'Why should we avoid packing warm, edible cooked food items in recycled colored polythene plastic bags?', 'Non-food-grade recycled plastic carries phthalates, lead, and cadmium residues that migrate into fatty, warm foodstuffs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbebae8f-13cc-4f9a-891f-cc92e00eacd4', 'Recycled plastics contain toxic heavy metal dyes and chemical plasticizers that leach into hot food, causing toxic food poisoning', true, '1eb45db8-c268-47b2-840f-4ea6a7894a42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('308092c0-ce1f-4743-90b1-ccf53e07af98', 'Because recycled bags smell like strawberries', false, '1eb45db8-c268-47b2-840f-4ea6a7894a42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f6232e3-e67d-410b-90ac-a1add95f81eb', 'Because colored bags keep food too hot', false, '1eb45db8-c268-47b2-840f-4ea6a7894a42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd4606a6-ab07-4662-bbb7-9108698b80d0', 'Because food turns into plastic', false, '1eb45db8-c268-47b2-840f-4ea6a7894a42');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5643f77-59ae-4c65-95c7-2189eea5d127', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'What is ''Kabaadiwala'' (Scrap Dealer / Informal Recycler) in the Indian municipal waste ecosystem?', 'Informal kabadiwalas recover millions of tons of dry recyclables, achieving high diversion rates from landfills.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3e49ff4-1405-4ffd-89ce-08315b1f7a59', 'Crucial grassroots recycling entrepreneurs who purchase discarded paper, cardboard, scrap metal, glass, and plastics to supply to industrial recycling factories', true, 'e5643f77-59ae-4c65-95c7-2189eea5d127');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98f9eef6-a15d-4126-9b01-bc2aaf25d946', 'People who burn garbage in forests', false, 'e5643f77-59ae-4c65-95c7-2189eea5d127');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a025314f-7dbc-4b50-9adc-991be9ae4c42', 'Drivers of city buses', false, 'e5643f77-59ae-4c65-95c7-2189eea5d127');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fc9230b-8ad8-4b73-b6a1-4cf8803b36e6', 'Street food sellers', false, 'e5643f77-59ae-4c65-95c7-2189eea5d127');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02e7b501-3ac4-4312-a7d8-6a6d01796ae8', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'How does nature naturally recycle dead plant and animal remains in a pristine forest?', 'Natural biogeochemical nutrient cycles operate in closed loops where biotic detritus becomes nutrient feedstock for autotrophs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('875d8064-cf4b-46b8-b622-534fbe7ea900', 'Decomposers (bacteria, fungi, earthworms, beetles) break down fallen leaves and carcasses into nutrient-rich humus soil, which feeds new growing trees (Zero Waste in Nature)', true, '02e7b501-3ac4-4312-a7d8-6a6d01796ae8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c423807-d855-441a-9cb8-f16d63a977f9', 'Forests have trash trucks', false, '02e7b501-3ac4-4312-a7d8-6a6d01796ae8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45e56e3c-1a56-44b4-ba7b-30d26170eca1', 'Rivers wash everything into outer space', false, '02e7b501-3ac4-4312-a7d8-6a6d01796ae8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9b06e41-7700-45f8-aa34-da050495d87a', 'Sunlight burns all leaves instantly', false, '02e7b501-3ac4-4312-a7d8-6a6d01796ae8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99c58683-5fb2-4be5-8ad4-5eee127ff078', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'What happens when non-biodegradable plastics are dumped in soil?', 'Buried plastic membranes impede groundwater recharge, soil aeration, and root penetration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bcf86ae-19cf-41c4-9f65-aa1801e46d6c', 'They form an impermeable underground barrier that blocks rainwater percolation into deep aquifers, degrading soil health and vegetation growth', true, '99c58683-5fb2-4be5-8ad4-5eee127ff078');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7a9fe3e-24d0-42ba-a73a-26f6099f794c', 'They dissolve into fertilizer within 2 days', false, '99c58683-5fb2-4be5-8ad4-5eee127ff078');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('322822e2-9d95-454a-b401-5ea21002bd3e', 'They turn into groundwater', false, '99c58683-5fb2-4be5-8ad4-5eee127ff078');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05f1de87-1de8-4193-9b34-f30101bd0441', 'They make soil softer', false, '99c58683-5fb2-4be5-8ad4-5eee127ff078');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87567570-85c0-4677-8ea1-2581a6b43637', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'What is a major advantage of using traditional Clay Cups (''Kulhads'') and Dried Leaf Plates (''Pattals'') during public festivals?', 'Terracotta kulhads and Sal leaf pattals provide compostable, sustainable indigenous alternatives to single-use plastics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22f18a40-445a-4268-a891-f37f65c29ede', 'They are 100% natural and biodegradable; when discarded, they dissolve back harmlessly into fertile soil without toxic plastic pollution', true, '87567570-85c0-4677-8ea1-2581a6b43637');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11d7b71a-48d2-42d9-85c4-80a5708b51e4', 'They can be used for 50 years', false, '87567570-85c0-4677-8ea1-2581a6b43637');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b46d0cf-988c-4537-9a15-b20f89b6db4f', 'They are made of metal', false, '87567570-85c0-4677-8ea1-2581a6b43637');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d93e5b3-010d-47c7-88a0-8002230876db', 'They never break', false, '87567570-85c0-4677-8ea1-2581a6b43637');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a36d3e5e-426a-4266-aa3e-8cf1ea29b16b', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'Which of the following is a direct, responsible action an individual student can take to ''REDUCE'' waste generation?', 'Source reduction eliminates disposable waste generation at the consumer level.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5874e0fc-1f6f-4595-9aa6-1fe817bb30ee', 'Using a durable refillable steel water bottle and reusable lunchbox instead of single-use plastic bottles and plastic foil wraps', true, 'a36d3e5e-426a-4266-aa3e-8cf1ea29b16b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9a9a0ce-2d3e-4e2a-9d33-ffc7cdbf2c57', 'Throwing away half-eaten food in the street', false, 'a36d3e5e-426a-4266-aa3e-8cf1ea29b16b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d658761-682f-494c-8fe8-b64f100979bc', 'Using 10 new plastic bags every day', false, 'a36d3e5e-426a-4266-aa3e-8cf1ea29b16b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c914bb47-5fc5-44a0-981b-63b93ee70a83', 'Buying disposable pens and throwing them away after one use', false, 'a36d3e5e-426a-4266-aa3e-8cf1ea29b16b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3284487-e50c-4ccf-8a6d-7f1586c986f4', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'What is ''Leachate'' generated in unscientific open garbage landfills?', 'Landfill leachate is a hazardous liquid contaminated with dissolved heavy metals, ammonia, and organic toxins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('010693e9-1bbd-45cd-8302-c80d13f33a16', 'A highly toxic, black liquid formed when rainwater percolates through rotting waste, which can seep underground and poison drinking groundwater wells', true, 'f3284487-e50c-4ccf-8a6d-7f1586c986f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dac11d2-19ea-47d2-9442-3f522f242098', 'Clean drinking water', false, 'f3284487-e50c-4ccf-8a6d-7f1586c986f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1eebef1e-707a-4b91-92b7-d32ba4322b95', 'Mineral spring water', false, 'f3284487-e50c-4ccf-8a6d-7f1586c986f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f08af26-601c-4e1d-bf8d-6298f21c05cc', 'Compost powder', false, 'f3284487-e50c-4ccf-8a6d-7f1586c986f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc69d956-67f1-4871-9769-d27b7eb407cf', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Medium', 'What civic national mission was launched on 2nd October 2014 across India to eliminate open defecation, promote scientific solid waste management, and create cleaner cities?', 'Swachh Bharat Abhiyan transformed national sanitation, municipal waste processing, and behavioral cleanliness across India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2611c9f6-3dd0-49a4-8696-6f28dd7224ed', 'Swachh Bharat Abhiyan (Clean India Mission)', true, 'cc69d956-67f1-4871-9769-d27b7eb407cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2917553-9059-4bf2-9dc7-77502a48457d', 'Digital India', false, 'cc69d956-67f1-4871-9769-d27b7eb407cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d99e750a-3d6d-470d-a4f9-c3bf311b52b0', 'Make in India', false, 'cc69d956-67f1-4871-9769-d27b7eb407cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62e3d1d9-9768-4706-871b-c8dbf985abcd', 'Smart Cities Mission', false, 'cc69d956-67f1-4871-9769-d27b7eb407cf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db1f2329-4528-49b3-aebe-f31e2596b1e6', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22308103-416a-47df-897a-18074a658297', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'db1f2329-4528-49b3-aebe-f31e2596b1e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f315153-51a1-4600-b56f-f5a172befe96', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'db1f2329-4528-49b3-aebe-f31e2596b1e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e38b7706-97da-4d0b-8ee9-6e0066c7014e', '(A) is true, but (R) is false.', false, 'db1f2329-4528-49b3-aebe-f31e2596b1e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cd3ff0a-d0ef-4af2-a4cf-ee4288ed4293', '(A) is false, but (R) is true.', false, 'db1f2329-4528-49b3-aebe-f31e2596b1e6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d813c608-702f-4ab2-ac65-4eae883d3352', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'Spot the IMPOSTER in the following group of waste items categorized as 100% Biodegradable:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b72ec75-ae15-438c-adc5-091cddc9b22a', 'Banana peel', false, 'd813c608-702f-4ab2-ac65-4eae883d3352');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3006355d-1d45-4684-b0ef-6fe17ae4d0b4', 'Cotton cloth scrap', false, 'd813c608-702f-4ab2-ac65-4eae883d3352');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21c1a04b-c3db-4988-a9dc-66e20102e614', 'Dried fallen leaves', false, 'd813c608-702f-4ab2-ac65-4eae883d3352');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44e386a0-c290-4144-a492-dfc06015a262', 'Thermocol cup', true, 'd813c608-702f-4ab2-ac65-4eae883d3352');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dbe9db51-ab1c-41cd-b801-057b4b962a00', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'A student sets up two test pits in the garden:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b7be3df-51b5-49df-a421-f9bd6c7b285c', 'Contents of Pit A have rotted completely into dark, rich, earthy smelling compost humus; contents of Pit B remain completely unchanged without any decomposition', true, 'dbe9db51-ab1c-41cd-b801-057b4b962a00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('784c902d-8cfb-442d-a2c6-9324e22ec497', 'Contents of Pit B disappeared while Pit A turned into glass', false, 'dbe9db51-ab1c-41cd-b801-057b4b962a00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c59af261-3ce9-46fb-bdaf-3081ef69ee96', 'Both pits turned into plastic', false, 'dbe9db51-ab1c-41cd-b801-057b4b962a00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4adf0456-24db-4340-b852-a60ddf0eb955', 'Neither pit showed any change', false, 'dbe9db51-ab1c-41cd-b801-057b4b962a00');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e6bc7c1-095b-4787-a8f6-6193134212a3', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'Match Column I (Waste Materials) with Column II (Appropriate Management Disposal Method):
(a) Vegetable peels & leaves -> (i) Vermicomposting / Compost pit
(b) Scrap aluminium & glass  -> (ii) Blue bin for industrial recycling
(c) Used plastic bottle      -> (iii) Reuse as a flower pot / stationery holder
(d) Solid hospital syringes  -> (iv) High-temperature biomedical incineration', 'Organic peels = composting; Scrap metals = recycling; Bottles = reuse; Biomedical waste = incineration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('322ee40a-db10-4673-9d9a-8287c086f88e', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '4e6bc7c1-095b-4787-a8f6-6193134212a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c51ac59-c12a-48ad-8339-bd437f3400ab', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '4e6bc7c1-095b-4787-a8f6-6193134212a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f2b60d5-71fa-44f2-9471-fa015d73c39b', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '4e6bc7c1-095b-4787-a8f6-6193134212a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea72065e-b31c-4593-9f59-314698311bb4', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '4e6bc7c1-095b-4787-a8f6-6193134212a3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25993fe0-b075-4ef0-9292-ed9c158733ae', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'Read the statements regarding Vermicomposting:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a3e2ef4-1601-4a59-b361-11ffa4921ae4', 'Statements 1 and 2 only', true, '25993fe0-b075-4ef0-9292-ed9c158733ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b4dfd3f-5ac7-4792-ba2c-5c9c41b85480', 'Statements 2 and 3 only', false, '25993fe0-b075-4ef0-9292-ed9c158733ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c635b836-c27b-4cdd-a63f-3109f2bc8a48', 'Statements 1 and 3 only', false, '25993fe0-b075-4ef0-9292-ed9c158733ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('feb73a68-5feb-4908-ac4b-161c52cee65a', 'All Statements 1, 2, and 3', false, '25993fe0-b075-4ef0-9292-ed9c158733ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('455bbb41-2fb0-4aea-ac37-0a3c55f7856d', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'Why is the concept of ''Circular Economy'' (Cradle to Cradle) considered the ultimate sustainable solution to global garbage crisis?', 'Circular economy replaces linear take-make-dispose models with regenerative closed loops maximizing resource utility.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e4278cb-5e43-4a8b-8372-5f72bdd4021e', 'It designs products so that all materials are endlessly reused, repaired, refurbished, and recycled in closed loops, eliminating the concept of ''waste'' entirely', true, '455bbb41-2fb0-4aea-ac37-0a3c55f7856d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee4ed39c-9786-4bdb-98cb-d4cde34264d4', 'It dumps all waste into the deep ocean', false, '455bbb41-2fb0-4aea-ac37-0a3c55f7856d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('974f7449-3b7a-40b1-aaf8-181c465cd1ae', 'It burns all garbage in giant rocket engines', false, '455bbb41-2fb0-4aea-ac37-0a3c55f7856d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2d7e121-34b1-4a37-820c-2e3e0d9c5a10', 'It forces people to stop eating food', false, '455bbb41-2fb0-4aea-ac37-0a3c55f7856d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b6da3151-9d09-4f36-9430-5575c15cf8b1', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'What is ''Bioremediation'' in modern environmental biotechnology?', 'Bioremediation utilizes microbial metabolic pathways to degrade hazardous xenobiotics into non-toxic end products.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c14de95-d2ec-411e-9b78-4583652be562', 'Using living microorganisms (engineered bacteria, fungi) and plants to detoxify, break down, and clean up polluted soils, oil spills, and heavy metal contaminants', true, 'b6da3151-9d09-4f36-9430-5575c15cf8b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c9a80ad-9ec5-46fc-b7d3-d50302ea0d32', 'Covering garbage with plastic sheets', false, 'b6da3151-9d09-4f36-9430-5575c15cf8b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d15a80e-d38d-4654-9bbd-43fe8e21cd0a', 'Spraying perfume over landfill sites', false, 'b6da3151-9d09-4f36-9430-5575c15cf8b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2d8881e-fe76-4a7c-a264-fbadbdfae7ab', 'Burning garbage with nuclear lasers', false, 'b6da3151-9d09-4f36-9430-5575c15cf8b1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('800b08bd-da3a-491e-ab54-a4e49987768a', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'What is the phenomenon of ''Microplastics'' in global marine ecosystems?', 'UV photo-oxidation and mechanical abrasion fragment macro-plastics into persistent trophic microplastics (<5 mm).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bca3a13d-fa37-448d-9a90-4266c8136dd9', 'Microscopic plastic particles (<5 mm) formed by the weathering breakdown of discarded plastic litter, which are ingested by plankton and fish, entering the human food chain', true, '800b08bd-da3a-491e-ab54-a4e49987768a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82b37164-2875-40c4-b646-099865a69346', 'Tiny plastic toys for dolls', false, '800b08bd-da3a-491e-ab54-a4e49987768a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f80600b0-89c6-41cd-ab12-a04a6db8db43', 'Microscopes made of plastic', false, '800b08bd-da3a-491e-ab54-a4e49987768a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddca99bf-70e3-4591-85b4-3200563f6580', 'Plastics that dissolve in 1 second', false, '800b08bd-da3a-491e-ab54-a4e49987768a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('638f39ff-d663-43be-925e-2c0932fbc383', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'Why is ''Anaerobic Digestion'' of segregated organic waste in biogas plants doubly beneficial for rural and urban sustainability?', 'Methanogenic anaerobic digestion yields carbon-neutral biomethane fuel (CH₄) alongside nutrient-rich organic digestate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2abd362b-3c69-439e-9113-a79ef1502fb3', 'It produces clean renewable Methane Biogas for cooking and electricity while generating high-potency organic bio-slurry fertilizer', true, '638f39ff-d663-43be-925e-2c0932fbc383');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db3456de-0fc9-47eb-a8bd-825b507de9ae', 'It produces gold and silver', false, '638f39ff-d663-43be-925e-2c0932fbc383');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4657e575-f34c-44fa-8bd5-4c19dade466b', 'It makes synthetic plastics', false, '638f39ff-d663-43be-925e-2c0932fbc383');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bab4641d-19e4-457d-a891-23097f876415', 'It turns water into oil', false, '638f39ff-d663-43be-925e-2c0932fbc383');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8349948a-45a2-4125-87d3-80eac0476294', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'Consider four categories of household waste generated during a birthday party:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9c7ce30-96ea-4221-be4b-b79b4b856de9', 'Items 1 and 4 only (Peels and Bread crusts)', true, '8349948a-45a2-4125-87d3-80eac0476294');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c4cefb4-72f5-4125-9829-6623af574bb0', 'Items 2 and 3 only', false, '8349948a-45a2-4125-87d3-80eac0476294');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bbda5aa-8749-4c72-8bf5-9bccf9c3b8be', 'Items 1, 2, and 3', false, '8349948a-45a2-4125-87d3-80eac0476294');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6044db5f-b429-47f5-9c6a-15c2d589bd67', 'All 4 items', false, '8349948a-45a2-4125-87d3-80eac0476294');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6027fb83-d2f1-4c09-b212-15f101452e0e', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'What is ''E-Waste'' (Electronic Waste) and why does it require specialized certified recycling rather than normal municipal dumping?', 'E-waste contains hazardous heavy metals and persistent flame retardants requiring specialized dismantling and pyrometallurgical recovery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38696781-faad-4fb1-baee-d9fdc7120697', 'Discarded computers, smartphones, and circuit boards that contain toxic heavy metals (lead, mercury, cadmium) that can leach into soil and water if dumped casually', true, '6027fb83-d2f1-4c09-b212-15f101452e0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64494f09-6034-4c40-ba82-a4063d03ecdc', 'Old paper electricity bills', false, '6027fb83-d2f1-4c09-b212-15f101452e0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e3deeca-b2de-4b05-95d9-1c40de1e70f9', 'Electric wires made of pure cotton', false, '6027fb83-d2f1-4c09-b212-15f101452e0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0747ac00-d57f-4a47-8109-b746d18bec5e', 'Lightning in the sky', false, '6027fb83-d2f1-4c09-b212-15f101452e0e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f7d9f025-8881-43d0-8dd4-b66febad29ba', 'Class 6', 'Science', 'Chapter 12: Garbage In, Garbage Out', 'Hard', 'What fundamental environmental philosophy concludes the NCERT Class 6 Science curriculum in Chapter 12?', 'The curriculum culminates in proactive ecological citizenship, waste minimization, and harmonious circular resource stewardship.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e4ffcac-b456-47e6-a38c-104a63184663', 'Every human action produces ecological consequences; sustainable living requires individual responsibility to minimize waste, segregate at source, and harmonize human lifestyle with nature''s circular ecology', true, 'f7d9f025-8881-43d0-8dd4-b66febad29ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25ad55e7-94f3-4772-b985-e83ca5c754e0', 'Throwing garbage in rivers is good for fish', false, 'f7d9f025-8881-43d0-8dd4-b66febad29ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('455eadea-625f-4e39-b69c-8941ffec4f17', 'Only governments are responsible for cleanliness', false, 'f7d9f025-8881-43d0-8dd4-b66febad29ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('237be0ad-af02-4b7d-bcf3-a58a5d41d17d', 'Using disposable plastics is the only way to live', false, 'f7d9f025-8881-43d0-8dd4-b66febad29ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ef8617ba-dcd7-4a83-8b72-17f6dc348c0b', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'Comparing two quantities of the SAME kind and in the SAME units by division is called a:', 'A ratio is a mathematical comparison of two quantities of identical physical dimension by division (a : b = a/b).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('401e42bc-db81-4526-bede-58e8627b7bae', 'Ratio (denoted by the colon symbol '':'')', true, 'ef8617ba-dcd7-4a83-8b72-17f6dc348c0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('017b1bab-cc4c-4b2c-a011-b4f3d628cf7b', 'Fraction', false, 'ef8617ba-dcd7-4a83-8b72-17f6dc348c0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c80915c3-da01-4d4d-9339-bb59601e93bc', 'Percentage', false, 'ef8617ba-dcd7-4a83-8b72-17f6dc348c0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6da5fc9-3460-4d61-babe-d629b96a1a01', 'Equation', false, 'ef8617ba-dcd7-4a83-8b72-17f6dc348c0b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c0ffcdf-bee7-4fea-8db9-c1edefea4367', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'What is the Ratio of 20 boys to 40 girls in a classroom in its simplest form?', 'Ratio = 20/40 = 1/2 = 1 : 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91029ce6-c3f9-4632-93cb-37c428f695e5', '1 : 2 (20/40 = 1/2)', true, '4c0ffcdf-bee7-4fea-8db9-c1edefea4367');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('474ac9ac-e8bb-4a98-91cc-f90d873411ae', '2 : 1', false, '4c0ffcdf-bee7-4fea-8db9-c1edefea4367');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fde6e9c-bd50-4902-b7e2-af63017c816a', '1 : 4', false, '4c0ffcdf-bee7-4fea-8db9-c1edefea4367');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f53ceca-ca1e-416a-a64c-6444f92e4ecc', '20 : 40', false, '4c0ffcdf-bee7-4fea-8db9-c1edefea4367');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4d917fb-c9d0-4b66-9b17-c2282dfbbd3a', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'Find the ratio of 15 cm to 2 metres (remember to convert both into the SAME unit first):', '2 m = 200 cm. Ratio = 15 / 200 = (15÷5) / (200÷5) = 3/40 = 3 : 40.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c9fab22-021e-4eaf-87b4-135d5b029f37', '3 : 40 (2 m = 200 cm ; Ratio = 15/200 = 3/40)', true, 'd4d917fb-c9d0-4b66-9b17-c2282dfbbd3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a12e8be-8ab5-4239-a79c-05c3af2f348e', '15 : 2', false, 'd4d917fb-c9d0-4b66-9b17-c2282dfbbd3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5d9b441-2463-4ac8-926f-c06ca83d0bb7', '3 : 20', false, 'd4d917fb-c9d0-4b66-9b17-c2282dfbbd3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43cdb2b7-1011-4c20-9954-13aa28bc9352', '15 : 200', false, 'd4d917fb-c9d0-4b66-9b17-c2282dfbbd3a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('728e53f2-0f10-4954-8ac1-e8ff8d63519c', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'Find the ratio of 50 paise to ₹5 in simplest form:', '₹5 = 500 paise. Ratio = 50 / 500 = 1/10 = 1 : 10.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3512ddf0-e6ac-4e6b-a6e6-70b7fc3d0538', '1 : 10 (₹5 = 500 paise ; Ratio = 50/500 = 1/10)', true, '728e53f2-0f10-4954-8ac1-e8ff8d63519c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c72cb68-5b71-497e-a790-92ec9aa6d0e9', '1 : 5', false, '728e53f2-0f10-4954-8ac1-e8ff8d63519c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c22a9fc-3512-46e2-afaf-26c0937428db', '10 : 1', false, '728e53f2-0f10-4954-8ac1-e8ff8d63519c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45748ca0-dba4-40fd-915d-f3dfdee98483', '50 : 5', false, '728e53f2-0f10-4954-8ac1-e8ff8d63519c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e04a935-cae2-4627-bbcd-aab5379972eb', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'An equality of two ratios (e.g. a : b = c : d or a : b :: c : d) is called a:', 'A proportion states that two ratios are equal: a/b = c/d.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef589bdb-b028-45ac-bda4-8376e9a6e473', 'Proportion', true, '9e04a935-cae2-4627-bbcd-aab5379972eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32f23343-9b2a-462f-b97e-8c5ba9cb991a', 'Fraction', false, '9e04a935-cae2-4627-bbcd-aab5379972eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8480c79d-9bb1-4499-a22a-b437d69252df', 'Percentage', false, '9e04a935-cae2-4627-bbcd-aab5379972eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1a040d9-2895-4316-9747-a40a057450b1', 'Linear Equation', false, '9e04a935-cae2-4627-bbcd-aab5379972eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49a169e7-1832-4912-98c2-b115ba69cf65', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'In a proportion a : b :: c : d, what are the first and fourth terms (a and d) called, and what are the middle terms (b and c) called?', 'In a : b = c : d, outer terms (a, d) are Extremes and inner terms (b, c) are Means.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b712a518-d454-403f-b86e-15aeb1ee42d9', '''a'' and ''d'' are Extreme Terms (Extremes) ; ''b'' and ''c'' are Middle Terms (Means)', true, '49a169e7-1832-4912-98c2-b115ba69cf65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0349bf6-17a8-4859-a3aa-1634addd3b26', 'All four are Means', false, '49a169e7-1832-4912-98c2-b115ba69cf65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8143b95-255e-4594-addb-1b497bd28730', 'All four are Extremes', false, '49a169e7-1832-4912-98c2-b115ba69cf65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d05302e0-f114-441f-879a-6236b0b0aa1d', '''a'' and ''b'' are Extremes', false, '49a169e7-1832-4912-98c2-b115ba69cf65');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('514054a4-cdd4-4457-a6ed-a8f02c5f8e66', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'What is the fundamental property of four numbers in Proportion (a : b :: c : d)?', 'Cross-multiplication rule: a/b = c/d ⇔ a × d = b × c.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('759f98e6-e9bc-405f-9bc7-cf73999af257', 'Product of Extremes = Product of Means (a × d = b × c)', true, '514054a4-cdd4-4457-a6ed-a8f02c5f8e66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('110f684d-64f3-47c8-9b35-7757a602d7fb', 'Sum of Extremes = Sum of Means', false, '514054a4-cdd4-4457-a6ed-a8f02c5f8e66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc0657bf-23cd-4013-890a-67d3b7f978c0', 'Difference of Extremes = Difference of Means', false, '514054a4-cdd4-4457-a6ed-a8f02c5f8e66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7329ef16-3f7b-4b13-8b88-719e3a1cf74c', 'Extremes divided by Means = 0', false, '514054a4-cdd4-4457-a6ed-a8f02c5f8e66');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a838302-727b-4190-be0c-befa5e57457f', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'The method in which we first find the value of ONE unit and then find the value of the REQUIRED number of units is called the:', 'The Unitary Method calculates the per-unit cost/value first (by division) and scales up (by multiplication).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39fa85ba-565e-4145-80a2-66faf5bead83', 'Unitary Method', true, '1a838302-727b-4190-be0c-befa5e57457f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0960adf-9e62-42bb-818b-2a813c6ef4bc', 'Trial and Error Method', false, '1a838302-727b-4190-be0c-befa5e57457f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c62c1c2f-7748-4624-8061-f59a1255c32e', 'Substitution Method', false, '1a838302-727b-4190-be0c-befa5e57457f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c16a96c6-8c8e-405d-966e-4eaf41a7a28f', 'Elimination Method', false, '1a838302-727b-4190-be0c-befa5e57457f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d792e37-bdfa-4898-b4e7-e13112d0b803', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'If the cost of 6 cans of juice is ₹210, what is the cost of 4 cans of juice?', 'Cost of 1 can = 210 ÷ 6 = ₹35. Cost of 4 cans = 35 × 4 = ₹140.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7669aec6-57f6-4aef-b332-0fc213511150', '₹140 (1 can = 210/6 = ₹35 ; 4 cans = 35 × 4 = ₹140)', true, '6d792e37-bdfa-4898-b4e7-e13112d0b803');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30035a7c-7442-4a14-8167-03f389f6c2fb', '₹120', false, '6d792e37-bdfa-4898-b4e7-e13112d0b803');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49a0fccb-e923-45b4-9c16-4a9d890da5ab', '₹160', false, '6d792e37-bdfa-4898-b4e7-e13112d0b803');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62b4b58f-c83a-445c-a2ec-3c2e2a4dbce5', '₹180', false, '6d792e37-bdfa-4898-b4e7-e13112d0b803');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2ce75ba-6ca2-4061-8dd7-54bd3cde6012', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'Are the numbers 25, 30, 40, and 48 in Proportion?', '25/30 = 5/6; 40/48 = 5/6. Since ratios are equal (1200 = 1200), they are in proportion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f06fa818-e2d6-4dee-a627-a53aefc37964', 'Yes (25/30 = 5/6 and 40/48 = 5/6 ; Product of extremes = 25 × 48 = 1200, Product of means = 30 × 40 = 1200)', true, 'b2ce75ba-6ca2-4061-8dd7-54bd3cde6012');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54984b73-a76e-4842-8b20-3a4c2275dee2', 'No', false, 'b2ce75ba-6ca2-4061-8dd7-54bd3cde6012');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a118e50-7c11-44f5-aafb-2f0d6fe7ea9a', 'Only if multiplied by 2', false, 'b2ce75ba-6ca2-4061-8dd7-54bd3cde6012');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c334857d-e0c7-4cb1-98c7-94ef3d8357ed', 'Cannot be determined', false, 'b2ce75ba-6ca2-4061-8dd7-54bd3cde6012');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dfda1c3d-fa71-466b-b029-e1679b4e68f0', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'Find the ratio of 30 minutes to 1.5 hours in simplest form:', '1.5 hours = 1.5 × 60 = 90 minutes. Ratio = 30 / 90 = 1/3 = 1 : 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9ff8f5c-5225-4d3d-a7d5-c8e217c05edf', '1 : 3 (1.5 hours = 90 minutes ; Ratio = 30/90 = 1/3)', true, 'dfda1c3d-fa71-466b-b029-e1679b4e68f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d879728-4f98-4dae-94f5-a7f3c9e71074', '1 : 2', false, 'dfda1c3d-fa71-466b-b029-e1679b4e68f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8728b0d5-dff0-4679-8e73-e4c2750ba8b6', '30 : 1.5', false, 'dfda1c3d-fa71-466b-b029-e1679b4e68f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('766410ee-8699-427f-9581-e5eaac9a0e5e', '1 : 5', false, 'dfda1c3d-fa71-466b-b029-e1679b4e68f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('220d761d-67b4-4407-a070-8cc5ed1e33b9', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Easy', 'Does a pure mathematical Ratio have any physical unit (like cm, kg, or rupees)?', 'Ratios compare like quantities; identical dimensional units in numerator and denominator cancel out.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('187f6617-55bc-4326-9551-fa8ebe0febfe', 'No, a ratio is a pure dimensionless number with NO units (units cancel out during division)', true, '220d761d-67b4-4407-a070-8cc5ed1e33b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d622857-7f9e-4e45-8c3c-1fb8d48b8d96', 'Yes, ratio has units of cm', false, '220d761d-67b4-4407-a070-8cc5ed1e33b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dffc7b7a-d9be-4271-9e9f-7b9a9adb55e4', 'Yes, ratio has units of kg', false, '220d761d-67b4-4407-a070-8cc5ed1e33b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('540484ec-5438-444b-87f0-c19b25a50675', 'Only if it compares time', false, '220d761d-67b4-4407-a070-8cc5ed1e33b9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d43a6f47-f081-4b78-9740-02f6166d12ba', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'In a year, Seema earns ₹1,50,000 and saves ₹50,000. Find the ratio of money that Seema saves to the money she SPENDS:', 'Expenditure = 1,50,000 - 50,000 = ₹1,00,000. Savings : Expenditure = 50,000 : 1,00,000 = 1 : 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('794f003f-eaa2-4503-be13-6bc45bcbd31e', '1 : 2 (Spends = 1,50,000 - 50,000 = ₹1,00,000 ; Ratio = 50,000 / 1,00,000 = 1/2)', true, 'd43a6f47-f081-4b78-9740-02f6166d12ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3cab96d-81b6-4b61-a0c8-86a1caf9b6a6', '1 : 3', false, 'd43a6f47-f081-4b78-9740-02f6166d12ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10829d97-8047-4b8c-aec4-56fdd5322875', '2 : 1', false, 'd43a6f47-f081-4b78-9740-02f6166d12ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2538f74-3887-453a-9dba-69ed11648596', '1 : 4', false, 'd43a6f47-f081-4b78-9740-02f6166d12ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06f417ee-e9f5-4e7a-87ac-22c9a24a5dbb', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'Divide ₹1,200 between Sheela and Sangeeta in the ratio of 3 : 2. How much money will Sheela and Sangeeta get respectively?', 'Sum of ratio parts = 3 + 2 = 5. Sheela = (3/5) × 1200 = ₹720; Sangeeta = (2/5) × 1200 = ₹480.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3a77a7a-8b04-4071-bb03-617b02ae5009', 'Sheela: ₹720 ; Sangeeta: ₹480 (Total parts = 3 + 2 = 5 ; Sheela = 3/5 × 1200 = ₹720 ; Sangeeta = 2/5 × 1200 = ₹480)', true, '06f417ee-e9f5-4e7a-87ac-22c9a24a5dbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14c29bbd-28d3-4208-b98c-b747332054e3', 'Sheela: ₹600 ; Sangeeta: ₹600', false, '06f417ee-e9f5-4e7a-87ac-22c9a24a5dbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17afb80b-d0eb-4835-8ac0-f68c4e5b88f3', 'Sheela: ₹800 ; Sangeeta: ₹400', false, '06f417ee-e9f5-4e7a-87ac-22c9a24a5dbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bc8b9ed-bde5-408e-90ba-28355001cee4', 'Sheela: ₹900 ; Sangeeta: ₹300', false, '06f417ee-e9f5-4e7a-87ac-22c9a24a5dbb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5fbd761f-2ded-4ee0-ad03-20a8836c24dd', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'Find the missing value ''x'' in the proportion: 8 : 12 :: x : 18', 'Product of extremes = Product of means: 8 × 18 = 12 × x ⇒ 144 = 12x ⇒ x = 12.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26e63091-abdd-4cbc-889c-a860bd83a2fc', 'x = 12 (8 × 18 = 12 × x ⇒ 144 = 12x ⇒ x = 144/12 = 12)', true, '5fbd761f-2ded-4ee0-ad03-20a8836c24dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e338245e-c27a-4351-81b7-44d7631b7ffd', 'x = 10', false, '5fbd761f-2ded-4ee0-ad03-20a8836c24dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00dda4a2-2c1f-49f5-ba88-2624bef2aa36', 'x = 14', false, '5fbd761f-2ded-4ee0-ad03-20a8836c24dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c72308a-afdb-4ef0-a5cd-fde5892daaf5', 'x = 16', false, '5fbd761f-2ded-4ee0-ad03-20a8836c24dd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5a51092-59e8-46c9-a990-32ff089216bc', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'A motorbike travels 330 km in 5 litres of petrol. How much distance can it travel in 1.5 litres of petrol?', 'Mileage = 330 ÷ 5 = 66 km/litre. Distance for 1.5 L = 66 × 1.5 = 99 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23165351-ec08-40e3-9531-fda2bb72506c', '99 km (1 litre = 330/5 = 66 km ; 1.5 litres = 66 × 1.5 = 99 km)', true, 'e5a51092-59e8-46c9-a990-32ff089216bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9306276f-d853-4adf-8255-872ac90cf1dc', '88 km', false, 'e5a51092-59e8-46c9-a990-32ff089216bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7784ec35-9eee-4db6-9715-4406c0e2882e', '110 km', false, 'e5a51092-59e8-46c9-a990-32ff089216bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2eee3c37-d6e8-422e-9178-71327e371e30', '95 km', false, 'e5a51092-59e8-46c9-a990-32ff089216bc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('657083d8-fcdb-47f7-83a3-be774c91a8af', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'If the cost of 7 metres of cloth is ₹1,470, find the cost of 5 metres of cloth:', 'Cost of 1 m = 1470 ÷ 7 = ₹210. Cost of 5 m = 210 × 5 = ₹1,050.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b35fed14-c4f9-482d-8245-5b17ea995485', '₹1,050 (1 metre = 1470/7 = ₹210 ; 5 metres = 210 × 5 = ₹1,050)', true, '657083d8-fcdb-47f7-83a3-be774c91a8af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75dcca40-58e4-4d0d-a3ff-7f762dab7316', '₹1,000', false, '657083d8-fcdb-47f7-83a3-be774c91a8af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d419cd06-5e1f-4ae8-b8c7-6531c531e81c', '₹1,100', false, '657083d8-fcdb-47f7-83a3-be774c91a8af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c633c47c-3ee8-4f4b-9956-fe143af7e144', '₹950', false, '657083d8-fcdb-47f7-83a3-be774c91a8af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c445d233-f225-46a3-93a1-695cd4e15fd6', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'Cost of a dozen (12) pens is ₹180 and cost of 8 ball pens is ₹56. Find the ratio of the cost of a pen to the cost of a ball pen:', '1 pen = 180/12 = ₹15; 1 ball pen = 56/8 = ₹7. Ratio = 15 : 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bcfd299-58bc-4f75-a66a-dc33226c397f', '15 : 7 (1 pen = 180/12 = ₹15 ; 1 ball pen = 56/8 = ₹7 ; Ratio = 15/7 = 15 : 7)', true, 'c445d233-f225-46a3-93a1-695cd4e15fd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('354e6606-3ddb-4e8e-8441-ab921dac3292', '18 : 7', false, 'c445d233-f225-46a3-93a1-695cd4e15fd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef77b81d-71b1-47ac-a52d-cf201032adb4', '15 : 8', false, 'c445d233-f225-46a3-93a1-695cd4e15fd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b96e534-b048-4da5-9e9b-8925a05f1bf3', '7 : 15', false, 'c445d233-f225-46a3-93a1-695cd4e15fd6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a70afd1c-d740-4802-be21-0195a665b69e', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'The length and breadth of a school rectangular ground are 75 m and 25 m respectively. Find the ratio of the BREADTH to the LENGTH of the ground:', 'Order matters: Breadth : Length = 25 : 75 = 1 : 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('343f3d50-d8ad-44fa-9f08-200bdfb59758', '1 : 3 (Breadth/Length = 25/75 = 1/3)', true, 'a70afd1c-d740-4802-be21-0195a665b69e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a178649c-4ae6-4414-bd62-88ae0984228e', '3 : 1', false, 'a70afd1c-d740-4802-be21-0195a665b69e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86d76972-eef4-41b5-9de9-cf3ecb212ec9', '1 : 2', false, 'a70afd1c-d740-4802-be21-0195a665b69e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce8f58f2-c698-41b2-8d78-3f6143a5a062', '2 : 3', false, 'a70afd1c-d740-4802-be21-0195a665b69e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ccb8c52-7602-4215-9d6e-7eefa8d36ad1', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'Anish made 42 runs in 6 overs and Anup made 63 runs in 7 overs. Who made MORE runs per over and by how much?', 'Anish rate = 42/6 = 7; Anup rate = 63/7 = 9. Anup scored 9 runs/over (+2 higher).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8393ac91-7a61-4e3f-ba12-4bb5c966c481', 'Anup made more runs per over (Anish = 42/6 = 7 runs/over ; Anup = 63/7 = 9 runs/over ; Anup is higher by 2 runs/over)', true, '9ccb8c52-7602-4215-9d6e-7eefa8d36ad1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8b3e2be-2cf9-421c-9a8d-8acac4675980', 'Anish made more runs per over', false, '9ccb8c52-7602-4215-9d6e-7eefa8d36ad1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59a72d7b-e08d-40f7-9966-9f4831abe31a', 'Both made exactly the same runs per over', false, '9ccb8c52-7602-4215-9d6e-7eefa8d36ad1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e3a37ad-b74f-4cd1-8cfc-54cf158dd58b', 'Anup is higher by 5 runs/over', false, '9ccb8c52-7602-4215-9d6e-7eefa8d36ad1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f4850e2-20ac-49d4-93b4-d74af9ab9334', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'Which of the two ratios is GREATER: 3 : 4 or 5 : 6?', 'Comparing fractions with common denominator 12: 9/12 < 10/12 ⇒ 5 : 6 > 3 : 4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb6112ea-0797-4e0b-bb6d-3ad3d70a4ae2', '5 : 6 is greater (3/4 = 9/12 = 0.75 ; 5/6 = 10/12 = 0.833 ⇒ 5/6 > 3/4)', true, '7f4850e2-20ac-49d4-93b4-d74af9ab9334');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44a56e5e-5822-4166-847c-6d35e989934a', '3 : 4 is greater', false, '7f4850e2-20ac-49d4-93b4-d74af9ab9334');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3dbced2-ef9b-4965-8145-a074d7125a4e', 'Both ratios are equal', false, '7f4850e2-20ac-49d4-93b4-d74af9ab9334');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4962b746-2398-4959-bb40-5f9357c22ec4', 'Cannot be compared', false, '7f4850e2-20ac-49d4-93b4-d74af9ab9334');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e40bc1f8-3cc6-4d0c-a2fc-1e1487f6c536', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'A car covers 180 km in 4 hours. How much time will it take to cover 450 km at the same uniform speed?', 'Speed = 180 ÷ 4 = 45 km/h. Time = Distance ÷ Speed = 450 ÷ 45 = 10 hours.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0d28aa3-2dc6-4620-866c-f70f166aaf4c', '10 hours (Speed = 180/4 = 45 km/h ; Time = 450/45 = 10 hours)', true, 'e40bc1f8-3cc6-4d0c-a2fc-1e1487f6c536');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cdddcfc-a32f-4d7f-b48e-e2b33ec2d7c4', '8 hours', false, 'e40bc1f8-3cc6-4d0c-a2fc-1e1487f6c536');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b7c0288-0aed-42de-8f0b-fe70de10a127', '12 hours', false, 'e40bc1f8-3cc6-4d0c-a2fc-1e1487f6c536');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a46c7cf-ac2c-4eae-8a76-db73280bef0b', '9 hours', false, 'e40bc1f8-3cc6-4d0c-a2fc-1e1487f6c536');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('251569e9-6380-43f1-93d9-21abcb39e659', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'Find two Equivalent Ratios for 4 : 6:', 'Dividing by 2 gives 2 : 3; multiplying by 2 gives 8 : 12.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf0039dc-c08f-4a6f-930a-f165b43b0fd6', '2 : 3 and 8 : 12', true, '251569e9-6380-43f1-93d9-21abcb39e659');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb0acb99-8be5-4f00-ad4f-2084ba5571a9', '1 : 2 and 3 : 4', false, '251569e9-6380-43f1-93d9-21abcb39e659');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00bc6b7e-341b-46f8-98c9-01401c493c52', '6 : 4 and 12 : 8', false, '251569e9-6380-43f1-93d9-21abcb39e659');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18a93da4-cde6-4b50-a23b-5993e5ab5001', '4 : 12 and 6 : 18', false, '251569e9-6380-43f1-93d9-21abcb39e659');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7588c7e9-0091-4303-9cd6-9d9f8bee32ab', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'If 4, x, 9 are in CONTINUED Proportion (4 : x :: x : 9), find the positive value of x:', 'In continued proportion, Mean Proportional x² = a × c ⇒ x² = 4 × 9 = 36 ⇒ x = 6.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb90d42e-ef87-4e40-a835-c15ba0ac3997', 'x = 6 (x² = 4 × 9 = 36 ⇒ x = √36 = 6)', true, '7588c7e9-0091-4303-9cd6-9d9f8bee32ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3977703d-53af-4177-bddd-f4042f1f9038', 'x = 5', false, '7588c7e9-0091-4303-9cd6-9d9f8bee32ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d74e5582-d469-4de8-85ba-d0958352e258', 'x = 7', false, '7588c7e9-0091-4303-9cd6-9d9f8bee32ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7eeb8531-75c0-445d-b787-bb5df32c8447', 'x = 8', false, '7588c7e9-0091-4303-9cd6-9d9f8bee32ab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('175da069-f999-4431-8844-2a26c2bded3f', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'Ekta earns ₹1,500 in 10 days. How much will she earn in 30 days?', 'Earnings/day = 1500/10 = ₹150. For 30 days = 150 × 30 = ₹4,500.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86ee53e3-43e9-4e7b-88bb-bed2921687cd', '₹4,500 (1 day = 1500/10 = ₹150 ; 30 days = 150 × 30 = ₹4,500)', true, '175da069-f999-4431-8844-2a26c2bded3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e45df205-c184-4c53-833d-eaa40fc7d2d0', '₹3,000', false, '175da069-f999-4431-8844-2a26c2bded3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a970eee2-8ed6-44c1-a4e8-ad2c40420e4c', '₹5,000', false, '175da069-f999-4431-8844-2a26c2bded3f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2bb3fc2-32c0-4bcb-a09d-2a12fa714e67', '₹4,000', false, '175da069-f999-4431-8844-2a26c2bded3f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('deae2f80-8cea-4ab0-b1fd-e811f2200f6d', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'The weight of 72 books is 9 kg. What is the weight of 40 such books?', 'Weight of 1 book = 9/72 = 1/8 kg. Weight of 40 books = 40 × (1/8) = 5 kg.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f32b7584-20dd-4405-a696-4adc7a5701fe', '5 kg (1 book = 9/72 = 1/8 kg ; 40 books = 40 × 1/8 = 5 kg)', true, 'deae2f80-8cea-4ab0-b1fd-e811f2200f6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a26cfd87-ee94-41ac-9df8-f8fa84714053', '4 kg', false, 'deae2f80-8cea-4ab0-b1fd-e811f2200f6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a3bfb41-5468-46ef-a519-d3c911310801', '6 kg', false, 'deae2f80-8cea-4ab0-b1fd-e811f2200f6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9daa7ffc-57fc-43c4-a875-be1a803eaf15', '8 kg', false, 'deae2f80-8cea-4ab0-b1fd-e811f2200f6d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a37b0f4-62d1-49da-94db-1ac5748edddb', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'If it has rained 276 mm in the last 3 days, how many cm of rain will fall in one full week (7 days) assuming constant rainfall rate?', 'Daily rate = 276/3 = 92 mm/day. 7 days = 92 × 7 = 644 mm = 64.4 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04a646af-d063-404a-bd31-d1e62d177f73', '64.4 cm (1 day = 276/3 = 92 mm ; 7 days = 92 × 7 = 644 mm = 64.4 cm)', true, '7a37b0f4-62d1-49da-94db-1ac5748edddb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2257da7c-3a95-430e-9e45-4b3c0db24e10', '644 cm', false, '7a37b0f4-62d1-49da-94db-1ac5748edddb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b400e95-fe55-492f-857e-d33c22f63197', '6.44 cm', false, '7a37b0f4-62d1-49da-94db-1ac5748edddb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf292c26-c9c8-42e3-97bc-1229a2b5679d', '27.6 cm', false, '7a37b0f4-62d1-49da-94db-1ac5748edddb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('623aa1de-b176-45b3-b365-74a665d8053b', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Medium', 'Fill in the blank to make the proportion true: 15 / 18 = ___ / 6', '18 ÷ 3 = 6; therefore 15 ÷ 3 = 5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af1c40a8-d4ae-4b10-844b-912b172243b7', '5 (15/18 = (15÷3)/(18÷3) = 5/6)', true, '623aa1de-b176-45b3-b365-74a665d8053b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2340797-4884-48a4-b50d-7eb6c4182867', '6', false, '623aa1de-b176-45b3-b365-74a665d8053b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01bd2586-e04b-430a-96d2-d988f3dcee3b', '3', false, '623aa1de-b176-45b3-b365-74a665d8053b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eabcc352-e6fd-4d9c-a4cc-4eaa7b0eb569', '4', false, '623aa1de-b176-45b3-b365-74a665d8053b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55d44438-7732-4fb3-8dc9-66ae5f74a552', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('802007c7-aea6-4cd1-a307-e2afd273c7cd', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '55d44438-7732-4fb3-8dc9-66ae5f74a552');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4880a870-d6d7-4be2-9869-1e618d24e38e', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '55d44438-7732-4fb3-8dc9-66ae5f74a552');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5c95683-8167-47d8-8d0d-86100671696e', '(A) is true, but (R) is false.', false, '55d44438-7732-4fb3-8dc9-66ae5f74a552');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db3729f2-9f10-4511-8437-759ec7822785', '(A) is false, but (R) is true.', false, '55d44438-7732-4fb3-8dc9-66ae5f74a552');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('628cf3bf-c139-4bf1-ad7e-53cbfe532e74', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'Spot the IMPOSTER in the following pairs of ratios tested for PROPORTION:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8df1313-3076-40ff-9888-cb91f544a432', '1 : 5 and 3 : 15 (Proportion)', false, '628cf3bf-c139-4bf1-ad7e-53cbfe532e74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fe5a904-0079-41a3-b4f4-c96bb169810e', '2 : 9 and 18 : 81 (Proportion)', false, '628cf3bf-c139-4bf1-ad7e-53cbfe532e74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a45ee5cf-06b9-40c1-9836-25143039cf0b', '15 : 45 and 5 : 25 (Proportion)', true, '628cf3bf-c139-4bf1-ad7e-53cbfe532e74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41c7772f-1709-43b7-b2c4-72f5cb03a181', '4 : 12 and 9 : 27 (Proportion)', false, '628cf3bf-c139-4bf1-ad7e-53cbfe532e74');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cafe7804-1785-490c-852a-5944c6137a76', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'In a triangle, the angles are in the ratio 2 : 3 : 4. If the sum of interior angles of a triangle is always 180°, find the measure of the three angles:', '9 parts = 180° ⇒ 1 part = 20°. Angles are 2×20 = 40°, 3×20 = 60°, 4×20 = 80°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('052de5fb-e891-4712-8acb-a68c666bbadb', '40°, 60°, 80° (Total parts = 2 + 3 + 4 = 9 ; 1 part = 180/9 = 20° ; Angles = 2(20°)=40°, 3(20°)=60°, 4(20°)=80°)', true, 'cafe7804-1785-490c-852a-5944c6137a76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1fa27a2-28ca-4d82-84e9-4fd3db1469c3', '30°, 60°, 90°', false, 'cafe7804-1785-490c-852a-5944c6137a76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1a6d0af-7fcd-4285-9d01-1f855ec7359b', '45°, 45°, 90°', false, 'cafe7804-1785-490c-852a-5944c6137a76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75608bbf-11fb-4910-8cf5-07b3a5325a5d', '50°, 60°, 70°', false, 'cafe7804-1785-490c-852a-5944c6137a76');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('983fd3ad-a75d-4e4e-a251-8b9dd725149e', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'Match Column I (Quantities Compared) with Column II (Simplest Ratios):
(a) 500 mL to 2 Litres    -> (i) 1 : 4
(b) 3 days to 30 hours    -> (ii) 12 : 5
(c) 40 cm to 1.5 m        -> (iii) 4 : 15
(d) 55 paise to ₹1        -> (iv) 11 : 20', '500/2000 = 1:4; 72/30 = 12:5; 40/150 = 4:15; 55/100 = 11:20.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef6242d6-0042-47b0-bc15-07fefb51b585', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '983fd3ad-a75d-4e4e-a251-8b9dd725149e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f4c855c-06bf-422d-981a-0f7b2826e70c', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '983fd3ad-a75d-4e4e-a251-8b9dd725149e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19c8e745-a1f8-4bbb-85b1-da67fec3f22b', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '983fd3ad-a75d-4e4e-a251-8b9dd725149e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1062eb33-e09c-4f87-989a-88e3f2ba739b', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '983fd3ad-a75d-4e4e-a251-8b9dd725149e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ab709b7-7529-494f-b858-cf48b39faef7', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'Read the statements regarding proportional reasoning:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1604d0ec-710c-4f15-86ad-bf838844f692', 'Statements 1 and 2 only', true, '8ab709b7-7529-494f-b858-cf48b39faef7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8577722-9465-4026-a697-edf326265f01', 'Statements 2 and 3 only', false, '8ab709b7-7529-494f-b858-cf48b39faef7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c20b5549-71ed-4b9c-b3d9-00c458d3aaf2', 'Statements 1 and 3 only', false, '8ab709b7-7529-494f-b858-cf48b39faef7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c612d818-c3c6-4687-8879-bda7077a58bb', 'All Statements 1, 2, and 3', false, '8ab709b7-7529-494f-b858-cf48b39faef7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea017328-8f83-4ef4-b255-95a537262fe7', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'Present ages of a father and son are 42 years and 14 years respectively. Find the ratio of the age of father to the age of son when the son was 12 years old (2 years ago):', '2 years ago: Father = 40, Son = 12. Ratio = 40/12 = 10/3 = 10 : 3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23a6ac81-1d42-4866-905f-e10762c6b82e', '10 : 3 (2 years ago: Father = 40 years, Son = 12 years ; Ratio = 40/12 = 10/3 = 10 : 3)', true, 'ea017328-8f83-4ef4-b255-95a537262fe7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4282d71e-58e1-44d7-8c72-ffeb202d9e64', '3 : 1', false, 'ea017328-8f83-4ef4-b255-95a537262fe7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de5d4bd9-99ae-487f-ba94-7122de25d34d', '4 : 1', false, 'ea017328-8f83-4ef4-b255-95a537262fe7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92460a9d-f437-4b74-972d-a8c505acb2db', '7 : 2', false, 'ea017328-8f83-4ef4-b255-95a537262fe7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ffdc4ec2-ee16-4770-9a74-228488802aae', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'What is the ratio of father''s age to son''s age after 10 years (Father = 52, Son = 24)?', 'In 10 years: Father = 42 + 10 = 52; Son = 14 + 10 = 24. Ratio = 52/24 = 13/6 = 13 : 6.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f33a91f-2b31-4223-8406-35e515b3dc97', '13 : 6 (52 / 24 = (52÷4) / (24÷4) = 13/6 = 13 : 6)', true, 'ffdc4ec2-ee16-4770-9a74-228488802aae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2b27aaf-cf65-4f9b-9cf4-1cc77e0583f1', '14 : 7', false, 'ffdc4ec2-ee16-4770-9a74-228488802aae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ef09ef3-2f2a-42fe-be35-4d807e47fb45', '12 : 5', false, 'ffdc4ec2-ee16-4770-9a74-228488802aae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c39b6cd8-d8f6-4ad4-96f4-2b6f15bc33cd', '2 : 1', false, 'ffdc4ec2-ee16-4770-9a74-228488802aae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa3fbc4f-90a6-4aa8-be5b-7871b93dac1c', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'Two numbers are in the ratio 5 : 8. If their sum is 91, find the difference between the two numbers:', '13x = 91 ⇒ x = 7. Numbers = 35 and 56. Difference = 56 - 35 = 21.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('016cebd5-8081-4b3b-a82d-aeb88b46da56', '21 (Total parts = 13 ; 1 part = 91/13 = 7 ; Numbers are 35 and 56 ; Difference = 56 - 35 = 21)', true, 'aa3fbc4f-90a6-4aa8-be5b-7871b93dac1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef115b31-0825-449d-8655-b7c30ba6f114', '14', false, 'aa3fbc4f-90a6-4aa8-be5b-7871b93dac1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acbaa66d-f155-48f8-b733-e0d656936a3a', '28', false, 'aa3fbc4f-90a6-4aa8-be5b-7871b93dac1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('589eb89e-15bb-485d-aced-91fd9b056a35', '18', false, 'aa3fbc4f-90a6-4aa8-be5b-7871b93dac1c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5605b5d6-df71-4d9f-b0c4-94b9134645a7', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'A map is drawn to a scale of 1 : 25,000,000 (1 cm on map = 250 km on ground). If two cities are 4.8 cm apart on the map, what is the actual distance between them on ground?', 'Actual distance = 4.8 cm × 250 km/cm = 1,200 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d1d586d-7d20-46a4-8cd8-519be4325a80', '1,200 km (4.8 × 250 = 1,200 km)', true, '5605b5d6-df71-4d9f-b0c4-94b9134645a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc978549-1b7f-4aea-825b-fcbdceff3ac4', '1,000 km', false, '5605b5d6-df71-4d9f-b0c4-94b9134645a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4775b02-a003-4547-b2ac-2bcd3ac2d04e', '1,500 km', false, '5605b5d6-df71-4d9f-b0c4-94b9134645a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3b0149c-1544-429d-84f0-efb64276ab7c', '960 km', false, '5605b5d6-df71-4d9f-b0c4-94b9134645a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1de95709-2912-4332-aaab-18fd4c4a3976', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'If A : B = 2 : 3 and B : C = 4 : 5, find the compound ratio A : B : C:', 'Equalizing B: A:B = 8:12 and B:C = 12:15 ⇒ A : B : C = 8 : 12 : 15.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65c63e8e-cab8-48d0-8630-00feb52d5595', '8 : 12 : 15 (Multiply A:B by 4 -> 8:12 ; Multiply B:C by 3 -> 12:15 ⇒ A:B:C = 8:12:15)', true, '1de95709-2912-4332-aaab-18fd4c4a3976');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62d7917e-ac3f-46f2-8dc8-95d16abe8960', '2 : 4 : 5', false, '1de95709-2912-4332-aaab-18fd4c4a3976');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e2b1e78-eb03-45aa-bb0d-5d387b78ab00', '8 : 10 : 15', false, '1de95709-2912-4332-aaab-18fd4c4a3976');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('297f48d9-762a-4925-ae6b-c7be9e3ef527', '6 : 8 : 15', false, '1de95709-2912-4332-aaab-18fd4c4a3976');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('863c0a70-2125-400d-bbd6-208776533a61', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'In an alloy of brass, copper and zinc are mixed in the ratio 7 : 3. How much zinc is present in 35 kg of this brass alloy?', 'Zinc weight = (3/10) × 35 = 10.5 kg.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d87284b-1cb9-42af-a8cd-4f947bbd9b41', '10.5 kg (Total parts = 10 ; Zinc = (3/10) × 35 = 10.5 kg)', true, '863c0a70-2125-400d-bbd6-208776533a61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c637b5bb-acf9-4858-b3e9-449ee913d81b', '15 kg', false, '863c0a70-2125-400d-bbd6-208776533a61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48316024-dce8-4568-8655-a0ee2264801c', '12 kg', false, '863c0a70-2125-400d-bbd6-208776533a61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c0ea5b1-dc8c-4bd3-a4f4-2699f247f4fd', '9.5 kg', false, '863c0a70-2125-400d-bbd6-208776533a61');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f959ee1-9c4a-44c6-8a06-59fb22065040', 'Class 6', 'Mathematics', 'Chapter 12: Ratio and Proportion', 'Hard', 'Why does Ratio and Proportional reasoning form the cornerstone of all quantitative sciences (physics, chemistry stoichiometry, economic scaling, and engineering design)?', 'Proportional scaling underpins dimensional analysis, chemical molar stoichiometry, and scale-model engineering.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0da85fc8-de40-410f-b01a-30c2946f975f', 'It allows scale-invariant proportional comparisons, rate scaling, recipe formulations, and predictive quantitative modeling across macroscopic and microscopic dimensions', true, '7f959ee1-9c4a-44c6-8a06-59fb22065040');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('190b374f-7ebd-4dba-8a6d-5fc2deebfe1b', 'Because proportions replace all algebra', false, '7f959ee1-9c4a-44c6-8a06-59fb22065040');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b0e4f4d-d22d-4e7d-a2f9-177136a622ef', 'Because division is the only math operation', false, '7f959ee1-9c4a-44c6-8a06-59fb22065040');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f402cba8-c8c7-411a-ba9a-f71fc8b65e68', 'Because numbers without ratios have no value', false, '7f959ee1-9c4a-44c6-8a06-59fb22065040');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('861e8c24-9b85-41ee-9f81-3d9546c10842', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'What is the standard, polite salutation used at the beginning of a formal letter written to a School Principal or Municipal Commissioner?', 'Formal correspondence requires dignified salutations: ''Respected Sir/Madam'' or ''Dear Sir/Madam''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69562a57-88b8-40b5-a4b1-6446bf6ae518', 'Respected Sir / Madam (or Dear Sir / Madam)', true, '861e8c24-9b85-41ee-9f81-3d9546c10842');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('561e2ac6-e954-4e1b-b91f-7c0d1e8cc5eb', 'Hey buddy!', false, '861e8c24-9b85-41ee-9f81-3d9546c10842');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09323d0d-4fde-4891-889c-c0cf6c44aa3a', 'What''s up Principal!', false, '861e8c24-9b85-41ee-9f81-3d9546c10842');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33445775-207e-40b7-ad9c-9c808cda8536', 'Hi friend,', false, '861e8c24-9b85-41ee-9f81-3d9546c10842');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c633bf19-e41a-403e-a1ef-3e4a5f2fcb1e', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'What is the standard complimentary close used at the end of a formal application letter to a teacher or authority?', 'Standard formal sign-offs include ''Yours obediently'' (to teachers) and ''Yours faithfully/sincerely'' (official).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f38ccaa4-dc29-4d0f-bf26-8bdca73dc9ec', 'Yours faithfully / Yours obediently / Yours sincerely', true, 'c633bf19-e41a-403e-a1ef-3e4a5f2fcb1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d9db855-f09a-4c20-bdd5-f8fc75114164', 'Cheers,', false, 'c633bf19-e41a-403e-a1ef-3e4a5f2fcb1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb02e8e3-b590-48ec-9e34-2c6973836c61', 'See ya later,', false, 'c633bf19-e41a-403e-a1ef-3e4a5f2fcb1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d96158d-ddcf-4b47-a65a-97d052765b68', 'Your best pal,', false, 'c633bf19-e41a-403e-a1ef-3e4a5f2fcb1e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2836fa4d-aef4-43ed-9d88-9c7e8f7ad3ea', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'In a formal school ''NOTICE'', which crucial element is always written at the very top in BOLD CAPITAL letters enclosed in a box?', 'Notice format mandates: Institution Header, ''NOTICE'' in caps, Date, Heading, Body (enclosed in a rectangular box).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('272357aa-1ca6-4dc1-aee7-3fd6d7b58655', 'The Name of the School/Institution followed by the word ''NOTICE''', true, '2836fa4d-aef4-43ed-9d88-9c7e8f7ad3ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce35cc2a-defd-4ea7-b8e8-fb6cc17d9cbf', 'A personal story', false, '2836fa4d-aef4-43ed-9d88-9c7e8f7ad3ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f57a3263-0fee-4085-8c49-9af68550154e', 'A poem', false, '2836fa4d-aef4-43ed-9d88-9c7e8f7ad3ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94afb87a-6794-4e0e-a6a8-9d44c3e6f72b', 'The principal''s home address', false, '2836fa4d-aef4-43ed-9d88-9c7e8f7ad3ea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('598c94ac-eb59-4ac0-bab2-acf5cc6ac63e', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'What is a ''Paragraph'' in English composition?', 'A paragraph is a coherent structural unit unified around a single topical theme.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3b82133-7157-40ee-9477-89f25bad1f15', 'A group of related sentences focused on developing a single central topic or idea', true, '598c94ac-eb59-4ac0-bab2-acf5cc6ac63e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c6f5933-e394-45a6-a75d-3de413fd810c', 'A list of random words', false, '598c94ac-eb59-4ac0-bab2-acf5cc6ac63e');
