INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e980c5a5-5381-4211-90d3-2e980d9ddc4c', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'What was the magical waterfall in the forest that gave delicious, warm Sake to the dutiful woodcutter Taro while giving cold water to others called?', 'The waterfall magically manifested warm sake exclusively for dutiful, filial Taro.', NOW()) ON CONFLICT DO NOTHING;
