INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27cc3fbd-1d0d-4378-9963-2a3b1fefaa8f', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'What was the name of the American Space Shuttle that tragic heroine Kalpana Chawla flew on her STS-107 mission in 2003?', 'Kalpana Chawla tragically perished with 6 crew members aboard Columbia during atmospheric re-entry on 1 Feb 2003.', NOW()) ON CONFLICT DO NOTHING;
