INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10a589c2-0a07-4f18-bfa1-c105b1c1436e', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'Who became the wise Sarpanch of the village Panchayat in Munshi Premchand''s ''Fair Play'' and delivered justice without friendship bias?', 'Premchand portrays the sacred neutrality of the Panch seat: ''The voice of the Panch is the voice of God''.', NOW()) ON CONFLICT DO NOTHING;
