INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c235d2a-6352-4c7f-ab3f-2906e3a0c864', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'What is the famous philosophical quote from ''Fair Play'' that captures the sacred responsibility of a judge?', 'Premchand''s central aphorism emphasizes that justice transcends personal enmity or friendship.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26201c0c-0719-40d4-bc4f-be0d8f996c52', '"The voice of the Panch is the voice of God."', true, '5c235d2a-6352-4c7f-ab3f-2906e3a0c864');
