INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('608651e2-6244-420f-b801-8844dd9abb25', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'What is the figure of speech in which two contradictory words are placed together (such as ''deafening silence'', ''sweet sorrow'') called?', 'An Oxymoron juxtaposes seemingly contradictory semantic terms (e.g. bittersweet, open secret).', NOW()) ON CONFLICT DO NOTHING;
