INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0e9f9a6-0c1d-45b9-b4cf-8bc4a0c1d94d', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Easy', 'What is the repetition of the same initial consonant sound in adjacent or closely connected words (such as ''Peter Piper picked a peck of pickled peppers'') called?', 'Alliteration is the poetic repetition of identical initial consonant phonemes in neighboring words.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6515b248-98b3-4044-afca-cbd1266278d8', 'Alliteration', true, 'b0e9f9a6-0c1d-45b9-b4cf-8bc4a0c1d94d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d354a7d-7ecb-4045-8acd-0a084563a187', 'Rhyme', false, 'b0e9f9a6-0c1d-45b9-b4cf-8bc4a0c1d94d');
