INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ca27168-2886-43f8-a1e4-f76c2b54f367', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Medium', 'Read the excerpt from Eleanor Farjeon''s poem ''The Quarrel'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d58c9e7-f360-4de2-99eb-9cd2d8537bb7', 'Because admitting one''s fault with moral humility and taking the initiative to make peace requires true courage and nobility', true, '9ca27168-2886-43f8-a1e4-f76c2b54f367');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6702b5bb-803d-4fd3-94cc-591e4d74c838', 'Because the brother won the physical fight', false, '9ca27168-2886-43f8-a1e4-f76c2b54f367');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19d0eef0-6b74-4fe1-bd0e-0f6a26036bbf', 'Because he wanted to get dinner', false, '9ca27168-2886-43f8-a1e4-f76c2b54f367');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b00634a7-ffa6-4956-9d8f-f19e016e0e42', 'Because he was afraid of the dark', false, '9ca27168-2886-43f8-a1e4-f76c2b54f367');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74881919-e3e4-4568-80b1-f3383807a489', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Medium', 'What is the crucial moral distinction between ''A House'' and ''A Home'' in Lorraine M. Hailing''s poem?', 'A house is physical architecture; a home is spiritual communion characterized by familial love and mutual sacrifice.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60b6e839-fe2f-46af-97cb-c5125809b2aa', 'A House is merely a physical brick-and-stone building structure, whereas a Home is built of selfless love, family bonds, sharing, and caring for one another', true, '74881919-e3e4-4568-80b1-f3383807a489');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f65658c-6ce6-4443-9329-d90036b0f151', 'A house has a garden while a home has none', false, '74881919-e3e4-4568-80b1-f3383807a489');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dc68cbf-eeec-4a54-8895-eda31cece2b9', 'A house is made of glass', false, '74881919-e3e4-4568-80b1-f3383807a489');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a06d14c-1ed1-40ad-bfbe-ce423018d961', 'There is no difference between them', false, '74881919-e3e4-4568-80b1-f3383807a489');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e7e36b98-bbad-4aa2-8b86-5e9beff741d9', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Medium', 'In ''A Tale of Two Birds'', why did the two sibling birds behave so completely differently when travelers visited their trees?', 'The story exemplifies the proverb: ''One is known by the company one keeps''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05a82a78-8d21-4a91-86de-f717093682b1', 'One lived in a cave with robbers and repeated abusive language; the other lived near a rishi''s ashram and welcomed guests with gentle polite words (Company shapes character)', true, 'e7e36b98-bbad-4aa2-8b86-5e9beff741d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09cee9b4-e109-4c87-9705-ced217fd965e', 'Because one bird was born blind', false, 'e7e36b98-bbad-4aa2-8b86-5e9beff741d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('947907a0-b1ce-4ebd-8c15-fa22ed790c9b', 'Because one bird was a parrot and the other an eagle', false, 'e7e36b98-bbad-4aa2-8b86-5e9beff741d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0c7810b-34b4-45c4-8b26-75f364d0f098', 'Because one bird had no wings', false, 'e7e36b98-bbad-4aa2-8b86-5e9beff741d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e931c770-3e3b-4412-812a-4d717358d706', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Medium', 'In ''The Friendly Mongoose'', what fatal mistake did the farmer''s wife make when she saw blood on the mongoose''s mouth and paws?', 'The folktale warns against precipitous hasty wrath: ''Look before you leap; do not act in blind passion''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc984980-e7a9-44b8-affd-0727365119b2', 'She acted in blind hasty rage without investigating, struck the faithful mongoose with a heavy water pot and killed it, only to discover inside that the mongoose had killed a poisonous snake to save her baby', true, 'e931c770-3e3b-4412-812a-4d717358d706');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e83477d-f3aa-4d07-9a1c-80585eb74cfe', 'She gave all her money to the mongoose', false, 'e931c770-3e3b-4412-812a-4d717358d706');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('830a4345-327f-40e1-a446-5aae2f57f207', 'She ran away to another village', false, 'e931c770-3e3b-4412-812a-4d717358d706');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d329e2d-e344-46c4-a9a4-e0524ffd3b2a', 'She put the mongoose in a cage', false, 'e931c770-3e3b-4412-812a-4d717358d706');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b769e12-1a86-486d-bff4-3fb1610d76e0', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Medium', 'In ''The Shepherd''s Treasure'', how was the poor, illiterate Iranian shepherd rewarded by the King for his extraordinary wisdom, humility, and honesty?', 'The shepherd''s humble blanket symbolized uncorrupted virtue, winning the King''s deepest esteem as Grand Governor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b23fc0c-20d6-4fc0-b7f0-e1f1afe37541', 'The King appointed him Governor of a province, and when jealous ministers accused him of stealing, his iron chest contained only an old woolen blanket—symbol of his eternal humility', true, '1b769e12-1a86-486d-bff4-3fb1610d76e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('790ac3f0-7ca7-4b0d-9642-d7c1a41b8e5f', 'The King gave him a golden palace and 1,000 horses', false, '1b769e12-1a86-486d-bff4-3fb1610d76e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67d26df8-186f-4b1c-a035-966087b3584e', 'The King made him his royal cook', false, '1b769e12-1a86-486d-bff4-3fb1610d76e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f54718a-1977-40b4-85d4-a7f21e6f538f', 'The King sent him to prison', false, '1b769e12-1a86-486d-bff4-3fb1610d76e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1746103-28f4-4e81-84d6-96161314c30b', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Medium', 'In ''Tansen'', how did the legendary court musician Tansen save his life when jealous courtiers plotted to kill him by making him sing the fire-igniting ''Raga Deepak''?', 'Tansen harmonized musical thermodynamics: Raga Megh''s torrential monsoon counteracted Raga Deepak''s thermal incandescence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('425d52f9-9f7c-4f4f-9819-7fdc4df969f6', 'He taught his daughter Saraswati and her friend Rupvati to sing ''Raga Megh'' simultaneously; when Deepak ignited fires and dried the air, Raga Megh brought torrential cooling rain', true, 'f1746103-28f4-4e81-84d6-96161314c30b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed9c50ba-b577-4490-a14a-478f5957a736', 'He ran away from Emperor Akbar''s court', false, 'f1746103-28f4-4e81-84d6-96161314c30b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aee01686-45d9-45b0-8db3-1e21e0a7463d', 'He refused to sing', false, 'f1746103-28f4-4e81-84d6-96161314c30b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c5ccacb-e896-4242-98b5-ffd97c8ceda3', 'He jumped into the river', false, 'f1746103-28f4-4e81-84d6-96161314c30b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('111a28be-080c-4298-bd34-04af6e6be095', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Medium', 'In ''The Monkey and the Crocodile'', how did the clever monkey save his life when the foolish crocodile betrayed him in the middle of the river?', 'Panchatantra wit: the monkey''s quick presence of mind outsmarted the treacherous crocodile.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20a57660-650c-4a96-84b6-78802483226b', 'The monkey cleverly claimed that he had left his heart safely behind on the jamun tree; when the crocodile swam back to fetch it, the monkey leaped to safety on the branches', true, '111a28be-080c-4298-bd34-04af6e6be095');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('232602dc-a764-4e86-87ac-d43f10dd26b3', 'The monkey fought the crocodile in water', false, '111a28be-080c-4298-bd34-04af6e6be095');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02d707c9-2b23-4306-9a70-e1b8c7a7dd49', 'The monkey called a fish for help', false, '111a28be-080c-4298-bd34-04af6e6be095');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('324fe8b8-cab2-4798-8d02-42d6b7bbc8cf', 'The monkey swam across to the other bank', false, '111a28be-080c-4298-bd34-04af6e6be095');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('665a951c-da65-4a0e-9a1d-246f4e617970', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Medium', 'In ''The Wonder Called Sleep'', what physiological and psychological restorative processes happen to our body during deep sleep?', 'Sleep is nature''s supreme physiological healer: relaxing musculature and neuro-cognitively restoring bodily homeostatic equilibrium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d77cfdc9-a3fc-43c6-83a7-6da5beb20dce', 'Our muscles relax, body temperature and blood pressure lower, the overworked brain rests, and physical healing and memory consolidation occur', true, '665a951c-da65-4a0e-9a1d-246f4e617970');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfa368b7-fbf8-47c1-b6fb-e36d90a2d5d7', 'Our heart stops beating entirely', false, '665a951c-da65-4a0e-9a1d-246f4e617970');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4794b289-6b4c-4f24-be3b-a1e90c216976', 'Our body grows wings', false, '665a951c-da65-4a0e-9a1d-246f4e617970');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0518af1b-451a-4b6f-958a-79dd49c6cd32', 'We lose all our memories', false, '665a951c-da65-4a0e-9a1d-246f4e617970');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('011b901b-70d1-46fa-91b8-3a1170da71a7', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Medium', 'What is the theme of Harry Behn''s poem ''Trees''?', 'Behn celebrates trees as embodiments of selfless kindness, silent shelter, and ecological harmony.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('629a2bdb-a5d8-4111-a1b7-4d378f6ad850', 'Trees are the kindest, gentlest things upon Earth that do no harm, offer soothing shade to cows, shelter birds, hum evening lullabies, and give wood and fruit', true, '011b901b-70d1-46fa-91b8-3a1170da71a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0502bff-6ccb-4295-a6ca-4b323af846ba', 'Trees are dangerous in storms', false, '011b901b-70d1-46fa-91b8-3a1170da71a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35dae828-2d0e-4cd9-880e-efabd4249b95', 'Trees should be chopped down for paper', false, '011b901b-70d1-46fa-91b8-3a1170da71a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2637720-59de-410a-a79b-09c58bad7f60', 'Trees make the forest too dark', false, '011b901b-70d1-46fa-91b8-3a1170da71a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd0635fc-2563-47ef-bb92-1a641d14f284', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Medium', 'What is the theme of E-Yeh-Shure''s poem ''Beauty''?', 'Pueblo poet E-Yeh-Shure reveals beauty as universal sensory and ethical harmony residing in noble deeds and kind thoughts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d4c8538-ce33-49e8-a542-c33ec43d1851', 'Beauty is not merely external; it is seen in sunlight and trees, heard in wind and rain, and felt within good deeds, kind thoughts, and pure dreams', true, 'fd0635fc-2563-47ef-bb92-1a641d14f284');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('395ca376-23ad-457f-9340-6d59b13865d0', 'Beauty is only expensive clothes and jewelry', false, 'fd0635fc-2563-47ef-bb92-1a641d14f284');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('380146c8-0ab9-4a8f-9a40-08539b22af54', 'Beauty cannot be found in nature', false, 'fd0635fc-2563-47ef-bb92-1a641d14f284');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('795a6ccb-4532-4e71-a2b6-ce08237c5c26', 'Beauty is only in paintings', false, 'fd0635fc-2563-47ef-bb92-1a641d14f284');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f50a90b3-19e0-492a-98af-e431c2273833', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Medium', 'Identify the figure of speech in: ''The roaring thunderstorm was a furious monster tearing through the valley.''', 'Direct identification of the storm as a monster without comparative markers (''like'' or ''as'') is a Metaphor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2581805-011b-49f0-8086-28e7505c5850', 'Metaphor (direct figurative equation of thunderstorm to a furious monster)', true, 'f50a90b3-19e0-492a-98af-e431c2273833');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79345547-488a-43da-9856-f645e0e815ad', 'Simile', false, 'f50a90b3-19e0-492a-98af-e431c2273833');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a15983f6-4e6d-4a54-ba45-6c2f281bb7e3', 'Alliteration', false, 'f50a90b3-19e0-492a-98af-e431c2273833');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0add343b-2d01-4ed6-b82f-b18dd7af467e', 'Hyperbole', false, 'f50a90b3-19e0-492a-98af-e431c2273833');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74b46695-2267-4b72-be42-cac6c29cd0f2', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Medium', 'Choose the correct sentence that accurately demonstrates the difference between HOMOPHONES ''Principle'' and ''Principal'':', 'Principal = head of a school; Principle = fundamental moral rule or truth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e4a9926-e3c8-4715-8e51-f3910d3b1464', '''Our school **Principal** is a man of high moral **principles**.''', true, '74b46695-2267-4b72-be42-cac6c29cd0f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca174426-cd87-40b8-b68a-f586f1cec82b', '''Our school Principle is a man of high Principal.''', false, '74b46695-2267-4b72-be42-cac6c29cd0f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57ff9363-6870-4491-8a7a-3e7cdf79c9eb', '''Both words mean the exact same thing.''', false, '74b46695-2267-4b72-be42-cac6c29cd0f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fadc9c24-385d-4ba1-93a3-a28773d5012f', '''Principle is a person, Principal is a rule.''', false, '74b46695-2267-4b72-be42-cac6c29cd0f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5cf033d4-487b-418d-9470-e410afa43795', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Medium', 'Choose the correct spelling of the high-frequency vocabulary word meaning ''steady persistence and resilience in achieving a goal'':', 'Correct orthography: P-E-R-S-E-V-E-R-A-N-C-E.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef14566a-64f2-4659-a63a-0abfbe77325a', 'Perseverance', true, '5cf033d4-487b-418d-9470-e410afa43795');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94bef730-0b90-47ba-bfdf-49fc0bb987b9', 'Perseverence', false, '5cf033d4-487b-418d-9470-e410afa43795');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4113f95a-cf5d-4f7a-97ef-8a57c95ae164', 'Preservance', false, '5cf033d4-487b-418d-9470-e410afa43795');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75b080c3-757b-4181-b03d-d58d700b0c83', 'Perserverance', false, '5cf033d4-487b-418d-9470-e410afa43795');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f8b4e98d-e5ef-44e3-a541-3551d6b575fe', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Medium', 'Choose the correct spelling of the adjective describing a child who is playfully annoying or causing harmless trouble:', 'Correct orthography: M-I-S-C-H-I-E-V-O-U-S (pronounced mis-chuh-vuhs, 3 syllables).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdabfa9d-9fb0-49a3-950b-188968d73312', 'Mischievous', true, 'f8b4e98d-e5ef-44e3-a541-3551d6b575fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5c54649-1be8-4832-9b92-0260362a0fdc', 'Mischievious', false, 'f8b4e98d-e5ef-44e3-a541-3551d6b575fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('359c077e-8544-4620-86a9-6470a8fb1830', 'Mischevous', false, 'f8b4e98d-e5ef-44e3-a541-3551d6b575fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a0fd0e3-210d-4f39-a9c5-d328b9d4512d', 'Mischivous', false, 'f8b4e98d-e5ef-44e3-a541-3551d6b575fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4bbb55f1-99ff-43c5-8309-eac34575990b', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Medium', 'What is the purpose of writing a ''Diary Entry'' in English creative writing?', 'Diary entries are personal introspective chronological records of emotions and experiences.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9d0be49-085c-48dc-b5ae-ac24bc960946', 'To record personal, intimate reflections, feelings, and daily experiences in an informal, authentic first-person voice', true, '4bbb55f1-99ff-43c5-8309-eac34575990b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69f6a969-7559-4147-8e4a-1b3e0e6725fc', 'To send an official complaint to the police', false, '4bbb55f1-99ff-43c5-8309-eac34575990b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('071f1649-55d5-4ffc-a841-f635c0ccf3f1', 'To advertise a new product in the market', false, '4bbb55f1-99ff-43c5-8309-eac34575990b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adb589a6-15e3-4be7-8deb-92191cbf517b', 'To write an exam question paper', false, '4bbb55f1-99ff-43c5-8309-eac34575990b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02330838-ffbb-4abf-a918-ecafec6a1d42', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Medium', 'What is the primary role of a ''Topic Sentence'' in a well-structured expository paragraph?', 'The topic sentence anchors the paragraph, articulating the primary proposition developed by supporting evidence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d15a03ab-15b5-4ae3-be67-6bdb00161638', 'It states the main controlling idea of the paragraph clearly, which the following supporting sentences elaborate and explain', true, '02330838-ffbb-4abf-a918-ecafec6a1d42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6a60f54-509d-44ae-a987-5c8491686ccc', 'It provides the final goodbye to the reader', false, '02330838-ffbb-4abf-a918-ecafec6a1d42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16b5c2e2-b81a-4e17-b886-b069cd24c51c', 'It lists dictionary definitions only', false, '02330838-ffbb-4abf-a918-ecafec6a1d42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48182ae8-3c0a-4c80-a552-5369cab6d9dc', 'It is always a question without an answer', false, '02330838-ffbb-4abf-a918-ecafec6a1d42');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6620b980-fcd5-4f28-a3d2-b04b4632d89c', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45a5ef6d-0b70-4873-86b5-05b66fc4fa2c', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '6620b980-fcd5-4f28-a3d2-b04b4632d89c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7109423a-bee4-4843-8ff3-236147fb2f99', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '6620b980-fcd5-4f28-a3d2-b04b4632d89c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a7c09d1-7f27-482f-89ef-62e6c964c083', '(A) is true, but (R) is false.', false, '6620b980-fcd5-4f28-a3d2-b04b4632d89c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7947533e-0570-40b1-895a-6b830e379a1f', '(A) is false, but (R) is true.', false, '6620b980-fcd5-4f28-a3d2-b04b4632d89c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a3f08bab-6316-4551-8ddb-775c09ad6e84', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Hard', 'Spot the IMPOSTER in the following group of classic literary texts paired with their central moral messages:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f77cd2d4-430e-4961-abb5-ebbe9587ad9c', 'Taro''s Reward - Filial piety and devotion to parents', false, 'a3f08bab-6316-4551-8ddb-775c09ad6e84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e11181e-656a-4bc4-9fe3-002dc8265ab9', 'Fair Play - Sacred neutrality of justice', false, 'a3f08bab-6316-4551-8ddb-775c09ad6e84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66f93e54-d4ef-4f37-aba8-cfe9863440d8', 'A Game of Chance - Caution against gullibility & con tricks', false, 'a3f08bab-6316-4551-8ddb-775c09ad6e84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7a22838-53d9-4760-8aad-873b357d0f75', 'The Banyan Tree - The benefits of cutting old trees for roads', true, 'a3f08bab-6316-4551-8ddb-775c09ad6e84');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9059b547-946e-41c5-b57f-81bea726249c', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Hard', 'Synthesize the core message of the poem ''Where Do All the Teachers Go?'' by Peter Dixon:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4495904c-75f2-47fb-b886-d8d927674fa3', 'A young child''s innocent inability to imagine that their omnipotent, perfect school teachers are ordinary human beings who wear pyjamas, wash socks, and live normal domestic lives', true, '9059b547-946e-41c5-b57f-81bea726249c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11dd443e-7d16-431b-8cb2-3664e41c5466', 'A child wondering if teachers live on Mars', false, '9059b547-946e-41c5-b57f-81bea726249c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04187d03-dc31-4667-9266-5f47e586040d', 'A desire to become a teacher', false, '9059b547-946e-41c5-b57f-81bea726249c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95d433dc-1da8-4269-9659-6b72e58bf393', 'A fear of homework', false, '9059b547-946e-41c5-b57f-81bea726249c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('410bdf07-a213-48d7-b7a1-52c4868fca5b', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Hard', 'Match Column I (Literary Authors) with Column II (Masterpiece Works in Class 6):
(a) Munshi Premchand -> (i) The Banyan Tree
(b) Ruskin Bond       -> (ii) Fair Play
(c) Zai Whitaker      -> (iii) A Pact with the Sun
(d) Dr. Zakir Husain  -> (iv) What Happened to the Reptiles', 'Premchand = Fair Play; Bond = Banyan Tree; Whitaker = Reptiles; Zakir Husain = Pact with the Sun.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e55b580-479a-4479-93e7-1db9e3264425', 'a-(ii), b-(i), c-(iv), d-(iii)', true, '410bdf07-a213-48d7-b7a1-52c4868fca5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a0e8f9f-a958-4c5a-9b65-db73f955c623', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '410bdf07-a213-48d7-b7a1-52c4868fca5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf466403-7ff3-4c44-a7ab-71ee14aaae5d', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '410bdf07-a213-48d7-b7a1-52c4868fca5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ade212ac-6deb-4969-b56c-5eed5bb7491f', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '410bdf07-a213-48d7-b7a1-52c4868fca5b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d6e246d-e796-4f24-81c3-2c976e5a482f', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Hard', 'Read the statements regarding English stylistic devices:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de4b9a44-5126-49bf-8e1d-77578c530105', 'Statements 1 and 2 only', true, '0d6e246d-e796-4f24-81c3-2c976e5a482f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a72755f1-b9e9-47bf-b740-874d77716a2b', 'Statements 2 and 3 only', false, '0d6e246d-e796-4f24-81c3-2c976e5a482f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98f453ca-2eea-4be6-b261-9dbdba512324', 'Statements 1 and 3 only', false, '0d6e246d-e796-4f24-81c3-2c976e5a482f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09a8c216-5311-481f-b4ad-13bc5e9f2d36', 'All Statements 1, 2, and 3', false, '0d6e246d-e796-4f24-81c3-2c976e5a482f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17dc8bfc-e8cd-4e2a-9f50-62282136280a', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Hard', 'What is the grammatical classification of the underlined subordinate clause in: ''We cannot begin the meeting *until the Principal arrives*.''?', '''Until the Principal arrives'' functions as an Adverbial Clause of Time answering ''when''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('787d2ec3-91d9-4b53-8f42-62074ee2d3c5', 'Adverb Clause of Time (modifying the main verb ''cannot begin'')', true, '17dc8bfc-e8cd-4e2a-9f50-62282136280a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fe6a1cd-6006-4047-9626-df1166da4e4c', 'Noun Clause', false, '17dc8bfc-e8cd-4e2a-9f50-62282136280a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b794fbc1-99f9-4c47-ad81-b8c2453711b4', 'Adjective Clause', false, '17dc8bfc-e8cd-4e2a-9f50-62282136280a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99eb387c-550d-42d7-87a9-364d91d0086d', 'Relative Clause', false, '17dc8bfc-e8cd-4e2a-9f50-62282136280a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6918fd03-8830-41c4-a4b9-6db3d22212fa', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Hard', 'Which of the following demonstrates the correct use of PUNCTUATION in a complex direct speech quotation?', 'Interrupted direct quotation: comma inside first quotes, reporting attribution, comma, quotes around remainder.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8caa1821-308a-4006-a92d-6ae580439b9d', '"If you work hard," said the wise teacher, "you will achieve your greatest dreams."', true, '6918fd03-8830-41c4-a4b9-6db3d22212fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48a21784-e947-4e87-be3f-c3a87e245ea4', '"If you work hard said the wise teacher you will achieve your greatest dreams."', false, '6918fd03-8830-41c4-a4b9-6db3d22212fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d39a19ab-04fd-42aa-9170-cc9969baf14c', 'If you work hard, said the wise teacher, "you will achieve your greatest dreams."', false, '6918fd03-8830-41c4-a4b9-6db3d22212fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7168d443-7bb1-44ef-a46b-cecfc2155aa1', '"If you work hard" said the wise teacher "you will achieve your greatest dreams".', false, '6918fd03-8830-41c4-a4b9-6db3d22212fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a7b25f9-0039-46e3-a4c7-554cb6a0ef7d', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Hard', 'What is the meaning of the idiomatic phrase ''To have your heart in your mouth'' when Patrick opened his report card?', '''Heart in one''s mouth'' vividly expresses visceral somatic sensations of acute suspense or terror.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('373ffe4c-f683-45ad-99a2-bca822dc3731', 'To feel overwhelming acute anxiety, fear, or suspense', true, '9a7b25f9-0039-46e3-a4c7-554cb6a0ef7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('076bdb0f-21bd-4e2c-a970-390d89e7c8c2', 'To have a physical throat ache', false, '9a7b25f9-0039-46e3-a4c7-554cb6a0ef7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('063126e6-cfef-4eaa-945f-a853a53ee229', 'To be extremely hungry', false, '9a7b25f9-0039-46e3-a4c7-554cb6a0ef7d');
