INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('223c52e0-b50e-4259-8c94-cb79a219723c', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Hard', 'Identify the figure of speech in: ''The child was as brave as a young lion in the face of danger.''', 'Explicit comparative syntax with ''as... as'' constitutes a Simile.', NOW()) ON CONFLICT DO NOTHING;
