INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30ecce42-e70b-447c-a4d4-47b06a5bd7ba', 'Metaphor', false, '223c52e0-b50e-4259-8c94-cb79a219723c');
