INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf250adc-aed8-4fdc-a3c8-79ff1bb80304', '''Taro was rewarded with twenty pieces of gold by the Emperor of Japan.''', true, '7172d74b-c837-4248-a0c5-338b64e9f8aa');
