INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb5f9471-4fda-490e-8ddb-381bead51065', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Hard', 'What is the structural role of ''Transitional Linking Words'' (such as ''Furthermore'', ''However'', ''Consequently'', ''In conclusion'') in advanced essay composition?', 'Discourse connectives establish rhetorical cohesion, logical progression, and semantic clarity across paragraphs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09a4b0b3-9122-4629-9e8c-cc67dcfdf85d', 'They establish smooth logical coherence, signposting relationships between ideas and bridging sentences seamlessly', true, 'cb5f9471-4fda-490e-8ddb-381bead51065');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00635842-e944-4436-a063-1bba535f9cc5', 'They are decorative filler words that make essays longer', false, 'cb5f9471-4fda-490e-8ddb-381bead51065');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dbeb426-07ef-40b1-ba99-bbe99ccb414a', 'They are only used in mathematics', false, 'cb5f9471-4fda-490e-8ddb-381bead51065');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3859d4fb-bcfc-446b-a910-64669320927e', 'They replace punctuation marks', false, 'cb5f9471-4fda-490e-8ddb-381bead51065');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('601c4ad7-cb35-4e81-8b04-9c4f2a1bf0cc', 'Class 6', 'English', 'Chapter 12: Grand Master Literature & Composition Synthesis', 'Hard', 'What grand humanistic vision unites the entire NCERT Class 6 English curriculum at its completion?', 'The curriculum culminates in cognitive and linguistic empowerment: integrating linguistic mastery with ethical empathy and critical truth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('223e5f46-744b-4a76-bff7-0a712baee6f7', 'The empowerment of the young human mind through the mastery of language, critical inquiry, compassionate integrity, and lifelong love for reading and truth', true, '601c4ad7-cb35-4e81-8b04-9c4f2a1bf0cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b67f6a46-a2b6-4797-9ab3-a538639842dc', 'The memorization of grammar rules without understanding', false, '601c4ad7-cb35-4e81-8b04-9c4f2a1bf0cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25a94f82-df60-4341-8aa1-a926da4bb6a9', 'The rejection of all creative poetry', false, '601c4ad7-cb35-4e81-8b04-9c4f2a1bf0cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1baa1fb-869a-4845-894b-c686a1378265', 'The belief that only science is important', false, '601c4ad7-cb35-4e81-8b04-9c4f2a1bf0cc');
