INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('932ad6e8-94bb-467b-b194-d8a54bfb3f63', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Easy', 'Why is ''International Day of Non-Violence'' observed globally on 2nd October every year by the United Nations?', 'In 2007, the UN General Assembly unanimously established 2 October (Gandhi Jayanti) as the International Day of Non-Violence.', NOW()) ON CONFLICT DO NOTHING;
