INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eed0c72c-b641-4088-a5af-ab6fdedb104f', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Medium', 'Which international treaty adopted at COP21 in 2015 commits nearly all nations to limit global average temperature rise to well below 2°C above pre-industrial levels?', 'The 2015 Paris Accord legally binds parties to Nationally Determined Contributions (NDCs) aiming for a 1.5°C warming ceiling.', NOW()) ON CONFLICT DO NOTHING;
