INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6be930a-3645-42d5-88d6-cd37e501b06a', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Medium', 'What is the primary objective of the ''International Atomic Energy Agency'' (IAEA), headquartered in Vienna, Austria?', 'IAEA (''Atoms for Peace'') inspects nuclear facilities and verifies compliance with the Non-Proliferation Treaty (NPT).', NOW()) ON CONFLICT DO NOTHING;
