INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cef6043c-dea3-4549-af18-8e1720da3c9c', 'Building nuclear bombs for all countries', false, 'c6be930a-3645-42d5-88d6-cd37e501b06a');
