INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('041fd332-c0c0-4e7a-80b6-e0176746a4ae', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Medium', 'What is ''Earth Hour'' organized annually by the World Wide Fund for Nature (WWF) on the last Saturday of March?', 'Earth Hour is a grassroots climate mobilization where cities black out iconic monuments for 60 minutes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2a357b6-59a1-437f-96bd-d89d0b3040f7', 'Millions of people and landmarks across 190 countries turn off non-essential electric lights for ONE HOUR (8:30 to 9:30 PM) to show commitment to planet Earth', true, '041fd332-c0c0-4e7a-80b6-e0176746a4ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c87ccd2-7914-4abf-9a5e-238705de6287', 'Stopping all cars for a day', false, '041fd332-c0c0-4e7a-80b6-e0176746a4ae');
