INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b59ef4ca-a6a5-41ab-9549-6cdad1a0be83', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Medium', 'What is the international human rights organization founded in 1961 that was awarded the 1977 Nobel Peace Prize for campaigning against torture and political imprisonment worldwide?', 'Amnesty International investigates human rights abuses and advocates for prisoners of conscience globally.', NOW()) ON CONFLICT DO NOTHING;
