INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc78d094-3b9d-4d15-ba2e-e019a66f57c5', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Medium', 'What is the ancient Sanskrit universal philosophy adopted by India for its G20 Presidency in 2023: ''Vasudhaiva Kutumbakam''?', 'From the Maha Upanishad, ''Vasudhaiva Kutumbakam'' affirms that all humanity and planetary life belong to a single interconnected cosmic family.', NOW()) ON CONFLICT DO NOTHING;
