INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5427a52c-e692-49e6-91e4-a2ec873e9db9', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Hard', 'What is the diplomatic coalition known as the ''G4 Nations'' (India, Japan, Germany, and Brazil) advocating for in global governance?', 'The G4 bloc supports mutual bids for permanent UNSC reform to reflect contemporary 21st-century geopolitical realities.', NOW()) ON CONFLICT DO NOTHING;
