INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f2af6706-dc00-461c-a272-0e4c08f228c3', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Hard', 'What is the unique environmental conservation project in Africa known as the ''Great Green Wall''?', 'The Great Green Wall restores 100 million hectares of degraded Sahelian landscape through community agro-forestry.', NOW()) ON CONFLICT DO NOTHING;
