INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('153ee473-451c-4c60-9b2b-f1b1cb386dd9', 'Class 6', 'GK', 'Chapter 12: Global Organizations, Peace, United Nations & Environmental Sustainability', 'Hard', 'What ultimate planetary vision unites the United Nations Sustainable Development Goals and human civilization?', 'The UN SDGs envision a shared global blueprint balancing socio-economic equity with planetary ecological boundaries.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a6b2c85-e6cc-4cc6-8ac8-abbee6ea3858', 'Creating an equitable, peaceful, and regenerative world where human dignity, poverty eradication, economic prosperity, and ecological biosphere balance thrive in harmony', true, '153ee473-451c-4c60-9b2b-f1b1cb386dd9');
