INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('51761e83-2efc-4e3e-a92c-e32b0497934f', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'How did artists paint the vivid, luminous mural paintings inside the pitch-dark caves of Ajanta over 1500 years ago?', 'Ajanta fresco-secco murals used mineral pigments on clay/lime plaster, illuminated by reflective brass mirrors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f2f39bc-18db-4b39-9273-7a5e1b23ff38', 'They used natural plant and mineral pigments (clay, ochre, lime, lapis lazuli) applied over a plaster base, illuminated by sunlight reflected from metal mirrors and oil torches', true, '51761e83-2efc-4e3e-a92c-e32b0497934f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2379c91d-d866-4566-b96f-f56901d5e432', 'They used electric fluorescent lights', false, '51761e83-2efc-4e3e-a92c-e32b0497934f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51eb70fa-87b8-490a-ba13-167430a9a9a1', 'They painted with neon synthetic paints', false, '51761e83-2efc-4e3e-a92c-e32b0497934f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fa1f977-2dfb-4c5e-9cf8-c2e59c29d8e1', 'They painted only during solar eclipses', false, '51761e83-2efc-4e3e-a92c-e32b0497934f');
