INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88b9b698-4bf0-4513-bdb2-221067eb35f1', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'Who was the ancient Indian physician known as the ''Father of Indian Medicine'' whose medical treatise ''Charaka Samhita'' laid the foundations of Ayurveda?', 'Charaka formulated tridosha balance (Vata, Pitta, Kapha), diagnosis, and pharmacology in the foundational ''Charaka Samhita''.', NOW()) ON CONFLICT DO NOTHING;
