INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a4210204-583e-4ab2-9b32-9650aff00097', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'What scientific explanations did Aryabhata provide in his seminal treatise ''Aryabhatiya'' (c. 499 CE)?', 'Aryabhata pioneered heliocentric motion, axial planetary rotation, geometric calculation of eclipses, and trigonometry (jya/sine).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c98edd10-ee7a-4a15-8044-e26e61645362', 'He explained that day and night are caused by the rotation of the Earth on its axis, provided mathematical rules for calculating solar/lunar eclipses, and calculated π as 3.1416', true, 'a4210204-583e-4ab2-9b32-9650aff00097');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8db8cfaf-c1fd-4282-8ebb-579dd55e80ee', 'He claimed Earth was flat and balanced on elephants', false, 'a4210204-583e-4ab2-9b32-9650aff00097');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('857daabd-d707-4418-81d2-4fec911f044a', 'He stated the sun orbits the earth every hour', false, 'a4210204-583e-4ab2-9b32-9650aff00097');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72a1ee86-5ef9-4f53-b3fe-ddccce0a0b03', 'He rejected all mathematics', false, 'a4210204-583e-4ab2-9b32-9650aff00097');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ee2da02-9d01-4cdb-b772-1b565e66a46b', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'What are the ''Puranas'' in classical Hindu sacred literature?', 'The 18 Mahapuranas democratized religious lore: recited aloud in temples so commoners and women could hear sacred wisdom.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ada86d1-bfe7-42d3-bd2b-fad3e7be4a15', 'Eighteen major sacred Sanskrit texts containing stories of gods and goddesses (Vishnu, Shiva, Durga), cosmology, genealogies, written in simple verse accessible to all', true, '8ee2da02-9d01-4cdb-b772-1b565e66a46b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d1d9d4f-6614-4005-b904-152913db70ea', 'Military training manuals for war', false, '8ee2da02-9d01-4cdb-b772-1b565e66a46b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e57b674-d225-4305-98e0-155cdc4dac2e', 'Books on Roman trade', false, '8ee2da02-9d01-4cdb-b772-1b565e66a46b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ef9849e-b4a0-4323-9324-c7b8027367b6', 'Poetry written in Greek', false, '8ee2da02-9d01-4cdb-b772-1b565e66a46b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47e9994f-e586-48d2-845b-7acda454f552', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'How did the invention and knowledge of Papermaking spread from China across the world?', 'Following the 751 CE Battle of Talas, Arab artisans learned papermaking in Samarkand/Baghdad, diffusing it to Europe.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('701d26cc-a654-40c8-b197-3e686c5309cb', 'It reached Korea and Japan around 1400 years ago, was transmitted to Baghdad (Arab world) in 751 CE via the Silk Route, and traveled from there to Europe', true, '47e9994f-e586-48d2-845b-7acda454f552');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f92ab11f-6dc2-4822-9187-43471729817d', 'It was carried by birds flying across oceans', false, '47e9994f-e586-48d2-845b-7acda454f552');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bd329f5-c952-4484-a4ba-13c3a1331d20', 'It was discovered independently in every country in the same year', false, '47e9994f-e586-48d2-845b-7acda454f552');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ac00a83-1a56-4c23-beb4-cf1cacc65df0', 'It remained secret in China until 1950', false, '47e9994f-e586-48d2-845b-7acda454f552');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('28141f78-1eed-4210-9f82-90d37c027f98', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'What is the famous sculpture of ''Descent of the Ganga'' (Arjuna''s Penance) carved on an immense open-air granite rock relief at:', 'The 27m × 9m open-air bas-relief at Mahabalipuram depicts Bhagiratha''s penance / Arjuna''s austerities with celestial nagas and elephants.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8efc9d5f-54ab-4733-9909-269c054a7362', 'Mahabalipuram (Mamallapuram, Tamil Nadu)', true, '28141f78-1eed-4210-9f82-90d37c027f98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('062e06c6-ebbe-453e-8dc6-5f08799cb4f9', 'Ajanta', false, '28141f78-1eed-4210-9f82-90d37c027f98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('855b485f-0d17-4e63-afca-c35e9f666b39', 'Sanchi', false, '28141f78-1eed-4210-9f82-90d37c027f98');
