INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02a77ca5-00d3-456b-b9e1-61d325c7f0aa', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'What structural architectural material was used to encase and protect the older Ashokan mud-brick Great Stupa at Sanchi around the 2nd century BCE?', 'Sunga and Satavahana patrons doubled Sanchi''s diameter with sandstone ashlar casing and sculpted four monumental Torana gateways.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e09098b2-bb77-4d52-a5de-b7d5fde31c99', 'A protective outer stone casing, stone harmika balcony, stone railings (vedika), and four elaborately carved Torana gateways', true, '02a77ca5-00d3-456b-b9e1-61d325c7f0aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('213423ca-84c9-4393-9d29-069c877d0476', 'Solid gold bricks', false, '02a77ca5-00d3-456b-b9e1-61d325c7f0aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6096f086-8e0e-413e-aaee-108d24eb49ec', 'Carved timber wood only', false, '02a77ca5-00d3-456b-b9e1-61d325c7f0aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dea439f-b543-4ebc-9600-49219d6baeb1', 'Concrete slabs', false, '02a77ca5-00d3-456b-b9e1-61d325c7f0aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2308571d-326f-4926-b333-35aeb007f14b', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'What famous Buddhist stupa in Andhra Pradesh on the Krishna River was renowned for its exquisite marble-like limestone narrative relief carvings?', 'The Maha-chaitya at Amaravati featured dynamic, crowded narrative limestone reliefs depicting the Buddha''s life under Satavahana rule.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce4bea87-c38b-48c2-94a7-b7fa3e894ef7', 'Amaravati Stupa', true, '2308571d-326f-4926-b333-35aeb007f14b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4162635c-ae9c-48e2-a991-17fa0a3e2fd9', 'Sanchi Stupa', false, '2308571d-326f-4926-b333-35aeb007f14b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('762df4ca-8948-4ec0-bc62-018ebe573a21', 'Bharhut Stupa', false, '2308571d-326f-4926-b333-35aeb007f14b');
