INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('812dcd72-255f-4685-b9fc-be8991a2ab2b', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'Who financed the construction of magnificent stupas, temples, and rock-cut viharas in ancient India?', 'Epigraphic donative records prove monument construction was crowdsourced across all social strata: guilds, monks, queens, and artisans.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b13ea9b-1cc0-4938-bdd0-a6f1369a3f38', 'Royal kings, queens, wealthy guild merchants, ivory carvers, farmers, blacksmiths, and humble ordinary lay devotees (recorded in votive inscriptions)', true, '812dcd72-255f-4685-b9fc-be8991a2ab2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('922a9e70-058e-46d4-bd34-6960e9e253ef', 'Only Roman emperors', false, '812dcd72-255f-4685-b9fc-be8991a2ab2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e841f85f-6fdd-4b30-9a25-3b14cbb3f416', 'Foreign tourists only', false, '812dcd72-255f-4685-b9fc-be8991a2ab2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1d463be-010b-47cb-9ac4-9ef76210bf65', 'The temples were built by magic without human workers', false, '812dcd72-255f-4685-b9fc-be8991a2ab2b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecee005e-a07e-41e7-9472-7492c2e94328', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'What is the famous Gupta-era rock-cut temple carved into the Udayagiri hill caves in Madhya Pradesh known for?', 'Udayagiri Cave 5 houses the iconic 5th-century monumental Varaha relief symbolizing geopolitical order restored by the Guptas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('426ef24f-713f-43d5-a087-efe97e9d8151', 'The colossal rock-cut bas-relief of Lord Vishnu as Varaha (Boar avatar) rescuing Prithvi (Earth)', true, 'ecee005e-a07e-41e7-9472-7492c2e94328');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f8fa270-0b72-482b-9670-17c6de57c6bd', 'The largest Buddha statue in the world', false, 'ecee005e-a07e-41e7-9472-7492c2e94328');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60c2e6b4-62df-4ac4-be29-0806a36baedb', 'A library of paper books', false, 'ecee005e-a07e-41e7-9472-7492c2e94328');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5845fd4d-f4f5-4879-aa01-1ddb8212e6b0', 'A royal gold treasury', false, 'ecee005e-a07e-41e7-9472-7492c2e94328');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1f5d0289-44f5-4c5e-8050-5f6270c09bf5', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Medium', 'What ancient Indian treatise on statecraft, economic policy, military strategy, and royal administration was authored by Kautilya (Chanakya)?', 'Kautilya''s Arthashastra is the premier ancient Sanskrit compendium of political economy, fiscal taxation, and diplomatic espionage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90be1a82-9423-48a6-8122-cea406c0f774', 'Arthashastra', true, '1f5d0289-44f5-4c5e-8050-5f6270c09bf5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a9fe12f-963e-4a44-8a87-6e446a404549', 'Manusmriti', false, '1f5d0289-44f5-4c5e-8050-5f6270c09bf5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0d06bfa-4d0f-4bbc-8613-e0673e4cd508', 'Kamasutra', false, '1f5d0289-44f5-4c5e-8050-5f6270c09bf5');
