INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a0090dc-b4b9-4904-a46b-88309e21397d', 'Aryabhatiya - Aryabhata', false, '06934fdd-2d00-4b9b-89a6-4576f017ae6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eeb67eee-e6ce-4b3c-b949-6a9985d3d32b', 'Silappadikaram - Sage Valmiki', true, '06934fdd-2d00-4b9b-89a6-4576f017ae6b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fde16cfb-6c4c-4b41-85ad-2d886b98c2e6', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'Consider the architectural components of a classical Hindu Temple:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f1c0021-41b3-4ae0-ba2c-9378356d32a4', 'Enter through the Mandapa hall -> circumambulate clockwise along the Pradakshina path -> look up at the towering Shikhara -> gaze directly into the Garbhagriha sanctum for Darshan', true, 'fde16cfb-6c4c-4b41-85ad-2d886b98c2e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50bcb258-0b84-4065-b6c1-913694c46338', 'Start in the Garbhagriha and end at the gate', false, 'fde16cfb-6c4c-4b41-85ad-2d886b98c2e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35a424a8-93b7-4610-a5d8-cc38dc5123fd', 'Climb to the top of the Shikhara first', false, 'fde16cfb-6c4c-4b41-85ad-2d886b98c2e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04d6b00e-6b3a-4968-932e-ca3cddd12251', 'Walk around the outer village', false, 'fde16cfb-6c4c-4b41-85ad-2d886b98c2e6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8697c452-3c90-49b0-bf2b-fc504d9eceb1', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'Match Column I (Ancient Masterpieces) with Column II (Categories & Authors):
(a) Meghaduta          -> (i) Lyric Sanskrit poem of cloud messenger by Kalidasa
(b) Sushruta Samhita   -> (ii) Foundational surgical medical treatise
(c) Manimekalai        -> (iii) Tamil epic composed by poet Sattanar
(d) Panchatantra       -> (iv) Sanskrit animal fable collection by Vishnu Sharma', 'Meghaduta = Kalidasa; Sushruta = surgery; Manimekalai = Sattanar; Panchatantra = Vishnu Sharma.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecc25d94-7c32-442c-8988-fe8e88fa44bf', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '8697c452-3c90-49b0-bf2b-fc504d9eceb1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbf85cb5-958d-4837-bf15-dd97dd4ed968', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '8697c452-3c90-49b0-bf2b-fc504d9eceb1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13174f76-6fbf-4a43-86cc-895976d09fca', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '8697c452-3c90-49b0-bf2b-fc504d9eceb1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e2e5e45-da02-4fc2-80e8-4a7afd8e24c6', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '8697c452-3c90-49b0-bf2b-fc504d9eceb1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('748c9fd5-a243-42d0-bbc2-f6562a465372', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'Read the statements regarding ancient Indian literature and art:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f92a7e7d-f830-40ee-91c3-07a97c0e7e37', 'Statements 1 and 2 only', true, '748c9fd5-a243-42d0-bbc2-f6562a465372');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c53b4ce7-4923-4a88-9cba-7a1f89e6b8b6', 'Statements 2 and 3 only', false, '748c9fd5-a243-42d0-bbc2-f6562a465372');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c49e5511-5a96-43a0-8a11-e6b58f0f71e5', 'Statements 1 and 3 only', false, '748c9fd5-a243-42d0-bbc2-f6562a465372');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ae4bb07-e447-4221-b746-71b16c4b19c9', 'All Statements 1, 2, and 3', false, '748c9fd5-a243-42d0-bbc2-f6562a465372');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2788b273-f7fa-4da4-be88-207e736c102a', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'What is the profound thematic resolution in the Tamil epic ''Silappadikaram'' when Kannagi tears off her left breast and throws it at the city of Madurai?', 'Kannagi''s moral fury incinerates unjust Madurai, deifying her as the supreme goddess of chastity and justice (Pattini).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70931432-50ba-488c-806e-4eccb7da8c60', 'Her cosmic grief and chaste moral power (Karpu) invoke the god of fire to burn corrupt Madurai to ashes, vindicating innocent truth over royal miscarriage of justice', true, '2788b273-f7fa-4da4-be88-207e736c102a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae3f1a15-1b9a-4d53-af61-27a2d42f203e', 'She becomes the new queen of Madurai', false, '2788b273-f7fa-4da4-be88-207e736c102a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf1e73e4-f911-4dba-bae5-9f2ae2976e1e', 'She forgives the king with gold', false, '2788b273-f7fa-4da4-be88-207e736c102a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa778ad6-ecc4-4152-8851-9c0005a1f09a', 'She sails away to Rome', false, '2788b273-f7fa-4da4-be88-207e736c102a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1dc44362-ee3c-4370-a22e-256ab4ae5054', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'Why was birch bark (''Bhurjapatra'') and processed palm leaves (''Talapatra'') used as the primary writing material in ancient India before the advent of paper?', 'Pothi manuscripts utilized inscribed cured palm leaves and birch folios bound with cords through perforations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6a515cb-a3a8-4c1a-9f8f-7ac6871b33db', 'Dried inner bark of Himalayan Betula utilis (birch) and Palmyra palm leaves were cured, trimmed, and inscribed with iron styluses or ink, strung together through central binding holes', true, '1dc44362-ee3c-4370-a22e-256ab4ae5054');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d13a1c00-7f1d-44c2-a4fc-6de35f88022d', 'Because stone was too light to write on', false, '1dc44362-ee3c-4370-a22e-256ab4ae5054');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50fa6794-60cc-45c7-97b4-ecd862b34da7', 'Because ancient Indians had no metal tools', false, '1dc44362-ee3c-4370-a22e-256ab4ae5054');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e66ac93-ec54-44b6-bdda-b2c9fdcde019', 'Because trees produced pre-printed books', false, '1dc44362-ee3c-4370-a22e-256ab4ae5054');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da75fe28-ef96-46e5-8d63-7d22ea065033', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'What dramatic story of an artist and king''s devotion is represented in the ''Padmapani Bodhisattva'' fresco painting in Ajanta Cave 1?', 'Ajanta''s Padmapani Bodhisattva is celebrated globally for its delicate shading, downward compassionate gaze, and spiritual grace.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f8c8c9b-3c15-47b2-b11e-d55ab8877a66', 'The Bodhisattva Avalokiteshvara holding a blue lotus in his hand, radiating infinite serene compassion, graceful tribhanga posture, and sublime spiritual transcendence', true, 'da75fe28-ef96-46e5-8d63-7d22ea065033');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33193700-e7e9-4b69-9900-98cc28c7c071', 'A general riding a war horse', false, 'da75fe28-ef96-46e5-8d63-7d22ea065033');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78f27d04-917b-480a-aeb9-eda918ed3df3', 'A trader counting gold coins', false, 'da75fe28-ef96-46e5-8d63-7d22ea065033');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('340514d0-e0ee-4b74-b105-818ffca12092', 'A hunter chasing deer', false, 'da75fe28-ef96-46e5-8d63-7d22ea065033');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6613bcaf-bc5d-4dec-a38c-e65f9c15f1c6', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'How did Aryabhata mathematically calculate the length of the solar year in the 5th century CE?', 'Aryabhata determined the sidereal solar year to fractional precision using astronomical epicyclic models.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f7af9b3-140d-4f2a-b968-0e8ae4fe4ba0', 'He calculated it as 365.25868 days, remarkably close to modern atomic astronomical calculations (365.25636 days)', true, '6613bcaf-bc5d-4dec-a38c-e65f9c15f1c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f49dc5b9-64fc-4085-853a-8f8bfed30517', 'He calculated it as exactly 300 days', false, '6613bcaf-bc5d-4dec-a38c-e65f9c15f1c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d0e96a3-4427-4cd8-a089-75c33933bfc6', 'He calculated it as 400 days', false, '6613bcaf-bc5d-4dec-a38c-e65f9c15f1c6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bbda399-17a1-4da2-a03f-2985af63340a', 'He stated that days have no fixed length', false, '6613bcaf-bc5d-4dec-a38c-e65f9c15f1c6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6eb7c91-5322-4239-9742-347a3fe8dba5', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'What do the diverse architectural forms of Durga Temple at Aihole (with its apsidal curved chaitya-like end) demonstrate about 6th-century Deccan art?', 'Aihole''s Durga temple illustrates architectural experimentation: adapting the apsidal plan of Buddhist chaityas into a Hindu pillared ambulatory temple.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb6b7ff0-6ecf-46e9-9690-da343c6f6408', 'It represents a brilliant experimental hybrid where Chalukyan stone masons melded Buddhist rock-cut apsidal plans with emerging Hindu structural temple sanctums', true, 'f6eb7c91-5322-4239-9742-347a3fe8dba5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8daabd35-2945-4f6c-8de3-2ffdb07d2890', 'It was built by Roman architects', false, 'f6eb7c91-5322-4239-9742-347a3fe8dba5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caebf65a-59c4-4419-84e8-025fc4d6225a', 'It was a replica of a Greek stadium', false, 'f6eb7c91-5322-4239-9742-347a3fe8dba5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('265e131b-daf0-4f47-8e15-f402d0957276', 'It was carved out of sea ice', false, 'f6eb7c91-5322-4239-9742-347a3fe8dba5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('616ecfd1-e0fb-40fe-9972-26212f2aaa4c', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'What is the ancient Sanskrit treatise on dramatic arts, theatre performance, stage aesthetics, and the theory of Nine Rasas (emotions) authored by Sage Bharata?', 'Bharata Muni''s Natya Shastra formulated classical Indian dramaturgy, abhinaya (acting), and the foundational Rasa aesthetic theory.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('875d69a5-5e2f-4eb4-8659-adde333ccb5e', 'Natya Shastra', true, '616ecfd1-e0fb-40fe-9972-26212f2aaa4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('869dc9cf-cda3-4f0b-94cb-96cf97c9d0cc', 'Kavyamimamsa', false, '616ecfd1-e0fb-40fe-9972-26212f2aaa4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44b9744c-4f2e-4f19-8b4c-6eff82edac85', 'Sahitya Darpana', false, '616ecfd1-e0fb-40fe-9972-26212f2aaa4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54ef5f2b-5131-4d1d-85b2-f73aa03952c0', 'Dhvanyaloka', false, '616ecfd1-e0fb-40fe-9972-26212f2aaa4c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d5c98b62-274d-43f2-9ba7-6ad102a0606e', 'Class 6', 'Social Science', 'Chapter 12: Buildings, Paintings and Books', 'Hard', 'What grand cultural synthesis completes the NCERT Class 6 Social Science History journey in Chapter 12?', 'The curriculum concludes celebrating ancient India''s enduring global legacy across architecture, metallurgy, epic poetry, and mathematics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13915fe7-008d-4d24-9ab1-c5fdcaf79f5f', 'The realization that ancient Indian civilization bequeathed a glorious heritage of rustless metallurgy, soaring architectural stupas and temples, immortal epic literature, and revolutionary scientific and mathematical breakthroughs that enriched all humankind', true, 'd5c98b62-274d-43f2-9ba7-6ad102a0606e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('778fb798-850c-4e0d-8d90-50f4188b8533', 'A belief that history is only about wars', false, 'd5c98b62-274d-43f2-9ba7-6ad102a0606e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed1d73fa-2fa9-4798-a6c8-22c6c891eee6', 'The conclusion that ancient people knew nothing', false, 'd5c98b62-274d-43f2-9ba7-6ad102a0606e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6bf12c8-ce5a-45ff-a12f-c714845c19b6', 'A civilization that left no lasting legacy', false, 'd5c98b62-274d-43f2-9ba7-6ad102a0606e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e313ac66-adfb-498b-8bdd-6b3440ccf91a', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', 'वाक्य को बोलते या लिखते समय भावों को स्पष्ट करने तथा रुकने के लिए जिन विशेष चिह्नों का प्रयोग किया जाता है, उन्हें क्या कहते हैं?', 'भाषा में अर्थ की स्पष्टता और भाव प्रकटीकरण हेतु प्रयुक्त ठहराव के संकेत ''विराम चिह्न'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8237f946-7d59-49e8-9663-65fc0dee8ee3', 'विराम चिह्न (Punctuation Marks)', true, 'e313ac66-adfb-498b-8bdd-6b3440ccf91a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6def531c-5adc-4a6f-b6ad-efa3c9bd54df', 'कारक चिह्न', false, 'e313ac66-adfb-498b-8bdd-6b3440ccf91a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cd76195-f6c3-4286-a8cd-843e39731351', 'प्रत्यय', false, 'e313ac66-adfb-498b-8bdd-6b3440ccf91a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1af3169-a570-4159-8b6c-cc2c193e6dac', 'उपसर्ग', false, 'e313ac66-adfb-498b-8bdd-6b3440ccf91a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1660470b-3a45-412b-9c51-8aa2665eec44', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', 'साधारण वाक्य के पूर्ण समाप्त होने पर अंत में कौन-सा विराम चिह्न लगाया जाता है?', 'वाक्य की पूर्ण समाप्ति पर ''पूर्णविराम'' (।) लगाया जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63b938fb-bd7f-4c92-9307-d1ac00680c81', 'पूर्णविराम (।)', true, '1660470b-3a45-412b-9c51-8aa2665eec44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05c81457-2e3f-47f5-b06a-7bdc78e6363e', 'अल्पविराम (,)', false, '1660470b-3a45-412b-9c51-8aa2665eec44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e93ad745-d7fe-46b3-8d95-8b772e3f712f', 'प्रश्नवाचक चिह्न (?)', false, '1660470b-3a45-412b-9c51-8aa2665eec44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ac53506-ad17-4dd9-9d48-c176165046bb', 'विस्मयादिबोधक चिह्न (!)', false, '1660470b-3a45-412b-9c51-8aa2665eec44');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('acbb6c64-2701-4223-84a5-ade7e3dfdcc7', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', 'वाक्य में बहुत थोड़े समय के लिए रुकने या समान पदों को अलग करने के लिए किस चिह्न का प्रयोग होता है?', 'अल्पकालिक ठहराव तथा पदों के पृथक्करण हेतु अल्पविराम (,) का प्रयोग होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4c24182-7c6c-43c5-a5bc-700ff4e0b86b', 'अल्पविराम (Comma - ,)', true, 'acbb6c64-2701-4223-84a5-ade7e3dfdcc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e609cfae-26d2-406a-b3a4-bd9f036c2a25', 'पूर्णविराम (।)', false, 'acbb6c64-2701-4223-84a5-ade7e3dfdcc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8e15d1f-f2c4-4c42-a39e-1f33b2e1b4ea', 'योजक चिह्न (-)', false, 'acbb6c64-2701-4223-84a5-ade7e3dfdcc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02e70a0b-d299-480c-9a87-381cb22c8cae', 'कोष्ठक ()', false, 'acbb6c64-2701-4223-84a5-ade7e3dfdcc7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7b56bf63-4610-43ec-8668-e9d62c152215', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', 'हर्ष, शोक, विस्मय, भय, घृणा आदि तीव्र मनोभावों को प्रकट करने वाले शब्दों या वाक्यों के आगे कौन-सा चिह्न लगाया जाता है?', 'आश्चर्य, हर्ष, शोक आदि मनोभावों के लिए विस्मयादिबोधक चिह्न (!) प्रयुक्त होता है (जैसे: ''अरे! यह क्या हुआ?'')', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ba66264-e619-45d2-88db-a91af36ca1b4', 'विस्मयादिबोधक चिह्न (!)', true, '7b56bf63-4610-43ec-8668-e9d62c152215');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8671834d-56c7-4586-8eb2-9a82e18cea9e', 'प्रश्नवाचक चिह्न (?)', false, '7b56bf63-4610-43ec-8668-e9d62c152215');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95eca0ea-f9ea-4a9e-ae1d-3805d808731a', 'पूर्णविराम (।)', false, '7b56bf63-4610-43ec-8668-e9d62c152215');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d258c9a4-9966-4812-97a2-d0455c0065e2', 'अर्धविराम (;)', false, '7b56bf63-4610-43ec-8668-e9d62c152215');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('29037938-ec47-4880-977c-f01e43797c90', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', 'दो वर्णों (ध्वनियों) के अत्यंत निकट आने पर उनके परस्पर मेल से होने वाले विकार (परिवर्तन) को क्या कहते हैं?', 'दो समीपवर्ती ध्वनियों के मेल से उत्पन्न रूपात्मक परिवर्तन को ''संधि'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c3ab689-3dbb-4400-bb47-448993a3c366', 'संधि (Euphonic Combination)', true, '29037938-ec47-4880-977c-f01e43797c90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('521f386b-1ce5-4e7e-940e-e585a2bf0896', 'समास', false, '29037938-ec47-4880-977c-f01e43797c90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('338643fa-76c2-4084-a8f8-2aa570f79b08', 'उपसर्ग', false, '29037938-ec47-4880-977c-f01e43797c90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28467dea-843f-4f13-ace3-7384b6d8e5aa', 'कारक', false, '29037938-ec47-4880-977c-f01e43797c90');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16f400ec-a387-4758-9912-34dbffff0b41', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', 'हिंदी व्याकरण में संधि के मुख्य रूप से कितने भेद होते हैं?', 'संधि के 3 मुख्य भेद हैं: स्वर संधि, व्यंजन संधि, और विसर्ग संधि।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97b6fd7f-5751-4118-8a8d-0919a6cc5f23', 'तीन भेद (1. स्वर संधि, 2. व्यंजन संधि, 3. विसर्ग संधि)', true, '16f400ec-a387-4758-9912-34dbffff0b41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65366a68-4b90-4204-919b-6ac004b84a5d', 'दो भेद', false, '16f400ec-a387-4758-9912-34dbffff0b41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('032b9322-bb14-461a-b3d4-c16c487dcf6d', 'चार भेद', false, '16f400ec-a387-4758-9912-34dbffff0b41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26ad25c9-fb8f-4314-bac1-9c6f4cdb5c7e', 'पाँच भेद', false, '16f400ec-a387-4758-9912-34dbffff0b41');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b89aecb7-bdf0-4113-a490-addf83cb1760', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', 'दो स्वरों के आपस में मिलने से जो विकार या परिवर्तन होता है (जैसे: ''विद्या + आलय = विद्यालय''), उसे क्या कहते हैं?', 'स्वर वर्ण के साथ स्वर वर्ण के मेल से होने वाला विकार ''स्वर संधि'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9777660b-78e3-405b-a2fc-1d9d6bdd663e', 'स्वर संधि', true, 'b89aecb7-bdf0-4113-a490-addf83cb1760');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ea5f15b-907a-4005-a76c-a5878623cd15', 'व्यंजन संधि', false, 'b89aecb7-bdf0-4113-a490-addf83cb1760');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8780955-4b07-4efb-b18a-73e079fe5083', 'विसर्ग संधि', false, 'b89aecb7-bdf0-4113-a490-addf83cb1760');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0ea894a-cbe5-40a0-80c5-687442085759', 'समास', false, 'b89aecb7-bdf0-4113-a490-addf83cb1760');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a0a07b4f-30b5-484a-ac54-4e24a4bb1e8a', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', 'स्वर संधि के मुख्य कितने भेद होते हैं?', 'स्वर संधि के 5 भेद हैं: 1. दीर्घ, 2. गुण, 3. वृद्धि, 4. यण, तथा 5. अयादि संधि।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24151502-521a-4f18-bbc4-4a0f42cb33be', 'पाँच भेद (दीर्घ, गुण, वृद्धि, यण, और अयादि संधि)', true, 'a0a07b4f-30b5-484a-ac54-4e24a4bb1e8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66eb10a6-0e2b-465b-bfef-4f12d937453f', 'तीन भेद', false, 'a0a07b4f-30b5-484a-ac54-4e24a4bb1e8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3def7bc-93c1-4979-a42d-2d0faf36903b', 'चार भेद', false, 'a0a07b4f-30b5-484a-ac54-4e24a4bb1e8a');
