INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b235abb6-3d2e-4838-9e16-297648e0560d', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Easy', '''सूर्य + उदय'' का सही संधि युक्त शब्द क्या होगा?', 'सूर्य (अ) + उदय (उ) = सूर्योदय (गुण संधि: अ + उ = ओ)।', NOW()) ON CONFLICT DO NOTHING;
