INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4276c575-dfb7-4178-a3b1-cb1aa231797e', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'किसी के कहे हुए कथन को ज्यों-का-त्यों उद्धृत करने के लिए किस चिह्न का प्रयोग किया जाता है?', 'वक्ता के मूल कथन को सुरक्षित रखने हेतु दोहरा उद्धरण चिह्न (" ") प्रयुक्त होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('246c2925-d367-4044-9054-8f735afea0f9', 'उद्धरण चिह्न / अवतरण चिह्न (दोहरा उद्धरण " " या इकहरा उद्धरण '' '')', true, '4276c575-dfb7-4178-a3b1-cb1aa231797e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa20e257-63d4-41f8-8c3a-bf7810a49064', 'योजक चिह्न (-)', false, '4276c575-dfb7-4178-a3b1-cb1aa231797e');
