INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b571254-3a54-49e2-8b6d-7ba4d8ddca27', 'लाघव चिह्न (०)', false, '4276c575-dfb7-4178-a3b1-cb1aa231797e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87c09fe8-f4be-4748-aba7-e090da5a2b9c', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'शब्दों के संक्षिप्त रूप (abbreviation) को लिखने के लिए (जैसे: ''डॉक्टर'' के लिए ''डॉ०'', ''पंडित'' के लिए ''पं०'') किस चिह्न का प्रयोग होता है?', 'संक्षिप्त रूप दर्शाने हेतु प्रयुक्त लघु शून्यवत प्रतीक ''लाघव चिह्न'' (०) कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c069617-a0fe-406e-84b6-39a3156ae07a', 'लाघव चिह्न (० / संक्षेप सूचक)', true, '87c09fe8-f4be-4748-aba7-e090da5a2b9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7496c11-54c0-40a6-a0f2-82f1013a2b62', 'हंसपद (^)', false, '87c09fe8-f4be-4748-aba7-e090da5a2b9c');
