INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('514476bf-071b-4566-82b8-968a173cdbe3', 'विवरण चिह्न (:- )', false, '87c09fe8-f4be-4748-aba7-e090da5a2b9c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ce170d1-36e8-4b26-9ca9-80017577b0bc', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'लिखते समय जब कोई शब्द या अंश छूट जाता है, तो उसे ऊपर लिखने के लिए किस चिह्न का प्रयोग किया जाता है?', 'छूटे हुए शब्द को सम्मिलित करने हेतु ''त्रुटिपूरक / हंसपद चिह्न'' (^) लगाया जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ed8f14d-ec7c-4a18-be8a-37ca6d173fdb', 'हंसपद या त्रुटिपूरक चिह्न (^)', true, '0ce170d1-36e8-4b26-9ca9-80017577b0bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b46b214b-11f2-4c25-b39d-55bd3a8d67b5', 'योजक चिह्न (-)', false, '0ce170d1-36e8-4b26-9ca9-80017577b0bc');
