INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17050f66-1453-4ba2-b129-37a8ce14d307', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', '''देव + इंद्र = देवेंद्र'' और ''महा + ईश = महेश'' में कौन-सी स्वर संधि है?', 'अ/आ के साथ इ/ई के मेल से ''ए'' विकार उत्पन्न होना ''गुण स्वर संधि'' का नियम है।', NOW()) ON CONFLICT DO NOTHING;
