INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2998f064-b585-4b18-9271-29eb83b80820', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', '''सदा + एव = सदैव'' और ''एक + एक = एकैक'' में कौन-सी स्वर संधि है?', 'अ/आ के आगे ए/ऐ आने पर ''ऐ'' हो जाना ''वृद्धि स्वर संधि'' है (सदा + एव = सदैव)।', NOW()) ON CONFLICT DO NOTHING;
