INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6194c316-450f-4a5b-b4d2-59681e2e11cb', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', '''यदि + अपि = यद्यपि'' और ''इति + आदि = इत्यादि'' में कौन-सी स्वर संधि है?', 'इ/ई का ''य्'' में परिवर्तन ''यण स्वर संधि'' कहलाता है (यदि + अपि = यद्यपि)।', NOW()) ON CONFLICT DO NOTHING;
