INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e90d8af2-023f-46a9-95dd-05d44398f6c1', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'अनेकार्थी शब्द ''कर'' के विभिन्न अर्थों का सही समूह कौन-सा है?', '''कर'' के अनेकार्थ हैं: हाथ (हस्त), टैक्स/शुल्क, सूर्य की किरण, तथा सूँड़।', NOW()) ON CONFLICT DO NOTHING;
