INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e6f4829-38d2-4467-b877-b162b6a021b4', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'अनेकार्थी शब्द ''अंबर'' के दो मुख्य अर्थ क्या हैं?', '''अंबर'' के दो प्रमुख अर्थ हैं: आकाश/नभ तथा वस्त्र/चीर (जैसे: पीतांबर = पीला वस्त्र)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb4ad725-1010-4418-b12a-0ec8293d42cf', 'आकाश (गगन) और वस्त्र (कपड़ा)', true, '1e6f4829-38d2-4467-b877-b162b6a021b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3faeb6fb-79eb-4847-b75d-09aab0523f8b', 'पानी और हवा', false, '1e6f4829-38d2-4467-b877-b162b6a021b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb657d8f-c986-48e8-8f5b-128bb3633a34', 'फूल और पत्ता', false, '1e6f4829-38d2-4467-b877-b162b6a021b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1292306-7077-4688-ba78-86820891cdaa', 'दिन और रात', false, '1e6f4829-38d2-4467-b877-b162b6a021b4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6abeba9b-f2b4-4375-8f64-ceefe02fa221', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'श्रुतिसम भिन्नार्थक शब्द ''अनल'' और ''अनिल'' के सही अर्थ क्रमशः क्या हैं?', '''अनल'' का अर्थ आग है और ''अनिल'' का अर्थ वायु/समीर है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76019c12-6f30-476f-b224-e1e6b58fd0d6', 'अनल = आग (अग्नि) ; अनिल = हवा (वायु)', true, '6abeba9b-f2b4-4375-8f64-ceefe02fa221');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c23d6c09-96fb-40b6-b652-b92592b5b80f', 'अनल = हवा ; अनिल = आग', false, '6abeba9b-f2b4-4375-8f64-ceefe02fa221');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1db72e0d-2e94-4940-a631-bab64833d39b', 'दोनों का अर्थ पानी है', false, '6abeba9b-f2b4-4375-8f64-ceefe02fa221');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('babe86bf-a015-411c-a2dd-390fe43ffa6e', 'दोनों का अर्थ आकाश है', false, '6abeba9b-f2b4-4375-8f64-ceefe02fa221');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9fd99d2e-57db-4b22-a77a-fdcee8a24acd', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'श्रुतिसम भिन्नार्थक शब्द ''कुल'' और ''कूल'' के सही अर्थ क्रमशः क्या हैं?', '''कुल'' (ह्रस्व उ) = वंश/समग्र; ''कूल'' (दीर्घ ऊ) = नदी का किनारा/तट।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88580b9c-03df-443c-ae4b-4853c8fa3367', 'कुल = वंश / सब (समस्त) ; कूल = किनारा (तट)', true, '9fd99d2e-57db-4b22-a77a-fdcee8a24acd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4c1ff4c-465b-4cf9-8c91-ddf8ceee8941', 'कुल = किनारा ; कूल = वंश', false, '9fd99d2e-57db-4b22-a77a-fdcee8a24acd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9706356a-8726-4735-8a1e-609bb2f94597', 'दोनों का अर्थ ठंडा है', false, '9fd99d2e-57db-4b22-a77a-fdcee8a24acd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be35f679-c3d5-4ab6-a378-59e15f21dd01', 'दोनों का अर्थ नदी है', false, '9fd99d2e-57db-4b22-a77a-fdcee8a24acd');
