INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b6e9fcd0-804e-44b4-8d12-cbeb06e35349', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'विलोम शब्दों के सही समूह की पहचान कीजिए:', 'अनुराग-विराग, उदय-अस्त, उत्थान-पतन, स्वाधीन-पराधीन प्रामाणिक विलोम युग्म हैं।', NOW()) ON CONFLICT DO NOTHING;
