INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13c7cc29-1341-426f-a6e6-0034cec23e87', 'सत्य : सच, रात : निशा, जल : नीर', false, 'b6e9fcd0-804e-44b4-8d12-cbeb06e35349');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7272e1d6-2a12-4cda-a567-fff6c7a7833a', 'दिन : सुबह, सूर्य : चाँद', false, 'b6e9fcd0-804e-44b4-8d12-cbeb06e35349');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c0054a6-7a1b-4822-b410-ce5873adf2c3', 'आकाश : बादल, धरती : मिट्टी', false, 'b6e9fcd0-804e-44b4-8d12-cbeb06e35349');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('09a2906d-d60b-4324-9a0f-2d16f9036403', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'पर्यायवाची शब्दों में ''बादल'' के सही पर्यायवाची शब्दों का समूह कौन-सा है?', 'जल देने वाले (द = देने वाला): जलद, वारिद, नीरद, मेघ, घन = बादल।', NOW()) ON CONFLICT DO NOTHING;
