INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('405cd834-fccc-4a0f-a5d0-156948a110c9', 'जलज, पंकज, नीरज', false, '09a2906d-d60b-4324-9a0f-2d16f9036403');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62598c71-1398-4666-93da-638272cde9d5', 'दिनकर, दिवाकर, भास्कर', false, '09a2906d-d60b-4324-9a0f-2d16f9036403');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8505cd2-a8b4-4ed1-8855-f6b5858ff97d', 'पवन, अनिल, समीर', false, '09a2906d-d60b-4324-9a0f-2d16f9036403');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e3654576-3389-4cc1-aed0-f9bb23d25c75', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Medium', 'वाक्य में विराम चिह्नों का सही प्रयोग पहचानिए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a3371bc-4d43-4d5a-84d5-5d361a510d4a', 'सुभाष चंद्र बोस ने कहा था, "तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा!"', true, 'e3654576-3389-4cc1-aed0-f9bb23d25c75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ec9c68b-d550-4697-b4a5-e4e3d24ec358', 'सुभाष चंद्र बोस ने कहा था तुम मुझे खून दो मैं तुम्हें आज़ादी दूँगा।', false, 'e3654576-3389-4cc1-aed0-f9bb23d25c75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7975f25-656e-4253-9cfb-82612f64c338', '"सुभाष चंद्र बोस ने कहा था" तुम मुझे खून दो मैं तुम्हें आज़ादी दूँगा?', false, 'e3654576-3389-4cc1-aed0-f9bb23d25c75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b95a2c5f-9cdc-4095-b6fd-3a1f222014c8', 'सुभाष चंद्र बोस ने कहा था: तुम मुझे खून दो मैं तुम्हें आज़ादी दूँगा।', false, 'e3654576-3389-4cc1-aed0-f9bb23d25c75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be57b9f6-7e09-4caa-af28-2938b11495d0', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19764d09-49e7-4c9c-947c-721a6243b307', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'be57b9f6-7e09-4caa-af28-2938b11495d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bccc10e3-717f-472b-abb7-b416636aaef2', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'be57b9f6-7e09-4caa-af28-2938b11495d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2fed4ca-8e9f-49bd-804d-37d899acc779', '(A) सही है, परन्तु (R) गलत है।', false, 'be57b9f6-7e09-4caa-af28-2938b11495d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20eb4515-8ee9-4897-b9f4-b46eee61dc53', '(A) गलत है, परन्तु (R) सही है।', false, 'be57b9f6-7e09-4caa-af28-2938b11495d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d3954a4-73e3-4702-884d-e552b86b4765', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'Spot the IMPOSTER in the following group of संधि विच्छेद और उनके प्रकारों में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53656ffb-a167-4e47-9486-67e3d6189bfb', 'हिम + आलय = हिमालय (दीर्घ संधि)', false, '1d3954a4-73e3-4702-884d-e552b86b4765');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9f41b9e-16b5-49c9-9d78-de2be9fffb81', 'नर + ईश = नरेश (गुण संधि)', false, '1d3954a4-73e3-4702-884d-e552b86b4765');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8eefdcf5-5a6a-40fa-b777-5fa5d5212434', 'महा + ऐश्वर्य = महैश्वर्य (वृद्धि संधि)', false, '1d3954a4-73e3-4702-884d-e552b86b4765');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6b7a08b-aafa-455c-a14e-e1180d97dc3c', 'सु + आगत = स्वागत (अयादि संधि)', true, '1d3954a4-73e3-4702-884d-e552b86b4765');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c1b7d38-a3a9-45fc-ba2b-27e4a4520bc6', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'सुमेलित कीजिए (विराम चिह्न और उनके मानक प्रतीक):
(क) अर्धविराम     -> (i) ?
(ख) अल्पविराम     -> (ii) ;
(ग) विस्मयादिबोधक -> (iii) ,
(घ) प्रश्नवाचक     -> (iv) !', 'अर्धविराम = ; ; अल्पविराम = , ; विस्मयादिबोधक = ! ; प्रश्नवाचक = ?।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fba370f-a1e9-4388-96a9-9ddfe54265b2', 'क-(ii), ख-(iii), ग-(iv), घ-(i)', true, '1c1b7d38-a3a9-45fc-ba2b-27e4a4520bc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b068d77-f5f0-48b5-afa9-d796ea5b9c84', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', false, '1c1b7d38-a3a9-45fc-ba2b-27e4a4520bc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd51f624-b9d1-4905-b3fa-25c0974fd953', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '1c1b7d38-a3a9-45fc-ba2b-27e4a4520bc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bba8ce4-f6e6-42a6-be05-fa6c8f9d1573', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '1c1b7d38-a3a9-45fc-ba2b-27e4a4520bc6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f52e12ee-732b-4734-862d-10bd3fe73044', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', '''पो + अन = पवन'' और ''पौ + अन = पावन'' में संधि नियमों का सूक्ष्म अंतर क्या है?', 'अयादि संधि नियम: ओ + अन = अव् (पवन); औ + अन = आव् (पावन)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a7b931c-0552-4344-92f7-f5768981a897', '''पो'' (ओ) + अन में ''ओ'' का ''अव्'' होकर ''पवन'' बनता है ; जबकि ''पौ'' (औ) + अन में ''औ'' का ''आव्'' होकर ''पावन'' बनता है (अयादि संधि)', true, 'f52e12ee-732b-4734-862d-10bd3fe73044');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b476c687-25f9-4688-b396-11a55563f96c', 'दोनों में दीर्घ संधि है', false, 'f52e12ee-732b-4734-862d-10bd3fe73044');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('187f3c06-6294-4c25-96c5-7bb5eb336f30', 'पवन में व्यंजन संधि है', false, 'f52e12ee-732b-4734-862d-10bd3fe73044');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e61494e2-aaa1-48b4-b882-2ed16fb44898', 'दोनों में कोई नियम नहीं है', false, 'f52e12ee-732b-4734-862d-10bd3fe73044');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('08b9e6e5-93c7-4c97-85a5-00922a6556d8', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'संधि और समास में क्या तात्विक (मूलभूत) अंतर होता है?', 'संधि = वर्णों/ध्वनियों का विकारमूलक संयोग; समास = पदों/शब्दों का विभक्तिरहित संक्षिप्तीकरण।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fedb211-1cf3-49a1-975c-2f0531d07118', 'संधि दो वर्णों/ध्वनियों का मेल होती है जिससे ध्वनि विकार होता है (जैसे: ''विद्या + आलय = विद्यालय'') ; जबकि समास दो या दो से अधिक सार्थक पदों/शब्दों का मेल होता है जिसमें कारक चिह्न लुप्त होते हैं (जैसे: ''राजा का पुत्र = राजपुत्र'')', true, '08b9e6e5-93c7-4c97-85a5-00922a6556d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('219e3130-e979-4dbc-b51a-0320ef6087f1', 'संधि केवल संस्कृत में होती है', false, '08b9e6e5-93c7-4c97-85a5-00922a6556d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ad0b9e9-40b6-48e7-9e80-64c0e167b74f', 'समास केवल दो शब्दों में होता है', false, '08b9e6e5-93c7-4c97-85a5-00922a6556d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a9142d3-a2dd-4ef6-a7f6-7ebf44c0873d', 'दोनों में कोई अंतर नहीं है', false, '08b9e6e5-93c7-4c97-85a5-00922a6556d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23717f0a-ffe3-4307-a895-ef28d832559d', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'अनेकार्थी शब्द ''द्विज'' के विभिन्न अर्थों का सही समूह कौन-सा है?', 'द्वि (दो) + ज (जन्मा): ब्राह्मण (उपनयन से द्वितीय जन्म), पक्षी (अंडे से जन्म), दाँत (दूध के दाँत के बाद पुनर्जन्म), चंद्रमा।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ee39091-d261-437e-a911-ee8000f576fa', 'ब्राह्मण, पक्षी, दाँत, और चंद्रमा (जिनका दो बार जन्म माना जाता है)', true, '23717f0a-ffe3-4307-a895-ef28d832559d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0be1c41b-5662-47ef-8f37-e15761672960', 'हाथी, घोड़ा, ऊँट', false, '23717f0a-ffe3-4307-a895-ef28d832559d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bcfcc8e-1e8e-4499-9b39-3b1c3e364a74', 'सोना, चाँदी, ताँबा', false, '23717f0a-ffe3-4307-a895-ef28d832559d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eef8d690-f0c5-495c-9694-8af320ddf392', 'पेड़, फल, फूल', false, '23717f0a-ffe3-4307-a895-ef28d832559d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d6f27f5-df92-4154-8e6f-d993a4719bee', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'श्रुतिसम भिन्नार्थक शब्द ''अलि'' और ''अली'' के सही अर्थ क्रमशः क्या हैं?', '''अलि'' (ह्रस्व इ) = भ्रमर/भौंरा; ''अली'' (दीर्घ ई) = सखी/सहेली।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96ec5c86-a63d-4287-adb6-bd1d3ac89d1c', 'अलि (ह्रस्व) = भौंरा (भ्रमर) ; अली (दीर्घ) = सखी (सहेली)', true, '2d6f27f5-df92-4154-8e6f-d993a4719bee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74314aec-2099-4d37-b79b-7e554223a0db', 'अलि = सखी ; अली = भौंरा', false, '2d6f27f5-df92-4154-8e6f-d993a4719bee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f270f92-40e7-4795-ac3f-3893da8ddace', 'दोनों का अर्थ आँख है', false, '2d6f27f5-df92-4154-8e6f-d993a4719bee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0eb64efb-c76f-4860-a6a6-762a46540092', 'दोनों का अर्थ नदी है', false, '2d6f27f5-df92-4154-8e6f-d993a4719bee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da57f40b-abcf-486a-bd66-205b5e9b627a', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', '''पितृ + आज्ञा'' और ''मातृ + उपदेश'' का शुद्ध संधि रूप क्रमशः क्या होगा?', 'ऋ + आ = रा (पित्राज्ञा); ऋ + उ = रु (मात्रुपदेश) - यण संधि।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('276058c7-2332-48e8-b084-669789f5cdfa', 'पित्राज्ञा और मात्रुपदेश (यण स्वर संधि : ऋ + असमान स्वर = र्)', true, 'da57f40b-abcf-486a-bd66-205b5e9b627a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fa314ed-8b0a-4a14-9aca-838bed789a6f', 'पितराज्ञा और मातरोपदेश', false, 'da57f40b-abcf-486a-bd66-205b5e9b627a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff5b62a6-bfda-4f2e-bc40-26790136fe8b', 'पितृआज्ञा और मातृउपदेश', false, 'da57f40b-abcf-486a-bd66-205b5e9b627a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58f78924-32de-4c95-bebd-bfe2ada59856', 'पित्रीआज्ञा और मात्रोपदेश', false, 'da57f40b-abcf-486a-bd66-205b5e9b627a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7aab8207-eb26-419c-befc-8e2b15aab184', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'वाक्यांश के लिए एक शब्द का सही सुमेल बताइए:
(क) उपकार को मानने वाला -> कृतज्ञ
(ख) उपकार को न मानने वाला -> कृतघ्न
(ग) जो गिना न जा सके -> अगणित (असंख्येय)
(घ) जो सबमें व्याप्त हो -> सर्वव्यापी
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2787b61-4e9a-4564-907c-d345feb6763e', 'सभी (क, ख, ग, घ) पूर्णतः सत्य हैं', true, '7aab8207-eb26-419c-befc-8e2b15aab184');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45d95574-b6dc-429d-8839-b7debc5db8ed', 'केवल क और ख', false, '7aab8207-eb26-419c-befc-8e2b15aab184');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebeac34d-3007-4050-963f-9edbca5ba6fd', 'केवल ग और घ', false, '7aab8207-eb26-419c-befc-8e2b15aab184');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3273f80a-2ae3-496a-ac23-1f3835822394', 'केवल क और घ', false, '7aab8207-eb26-419c-befc-8e2b15aab184');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea88ef9f-0283-44fd-93c3-37f294bb557a', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'योजक चिह्न (-) का प्रयोग किन-किन परिस्थितियों में अनिवार्य रूप से किया जाता है?', 'योजक चिह्न (-) द्वंद्व युग्मों, पुनरुक्ति, विलोमों तथा ''सा/सी'' सादृश्यवाचियों में प्रयुक्त होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ffceb02-de16-4177-9e14-2e0a27dee27a', 'द्वंद्व समास के पदों के बीच (माता-पिता), पुनरुक्त शब्दों के बीच (धीरे-धीरे), तुलनात्मक ''सा/सी/से'' से पूर्व (चाँद-सा मुखड़ा), और विलोम युग्मों के बीच (दिन-रात)', true, 'ea88ef9f-0283-44fd-93c3-37f294bb557a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('875094d1-81f2-4fda-920b-eebfbdac93b7', 'केवल वाक्य के अंत में', false, 'ea88ef9f-0283-44fd-93c3-37f294bb557a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b552aef-afa2-489a-8e78-3bdc76670fc5', 'केवल प्रश्नों में', false, 'ea88ef9f-0283-44fd-93c3-37f294bb557a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae5b6af2-89da-4bba-b556-449b42291f7a', 'केवल संज्ञा और क्रिया के बीच', false, 'ea88ef9f-0283-44fd-93c3-37f294bb557a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f089f164-cf1d-436b-bbdd-07e360759af5', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'हिंदी भाषा की समृद्धि में ''शब्द संपदा'' (Vocabulary Enrichment) का क्या सर्वोच्च महत्व है?', 'शब्द संपदा भाषा की सूक्ष्म अभिव्यंजना शक्ति, संप्रेषणीयता और वैचारिक प्रखरता का मूल आधार है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ff25b94-c6d6-47ff-a082-d323d6110229', 'सटीक, समृद्ध शब्द संपदा से विचार-अभिव्यक्ति अत्यंत सजीव, प्रभावशाली, लालित्यपूर्ण तथा अर्थ-गांभीर्य से परिपूर्ण बनती है', true, 'f089f164-cf1d-436b-bbdd-07e360759af5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e322a58-b309-415b-ac5d-3bb5fde86314', 'शब्द संपदा से केवल शब्दकोश भारी होता है', false, 'f089f164-cf1d-436b-bbdd-07e360759af5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f27984a-eaa0-4e27-8a88-bc54473d73fa', 'ज्यादा शब्दों से भाषा कठिन हो जाती है', false, 'f089f164-cf1d-436b-bbdd-07e360759af5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c00edd7-ce6c-464d-a313-b0fbea10e061', 'शब्द संपदा का कोई विशेष लाभ नहीं है', false, 'f089f164-cf1d-436b-bbdd-07e360759af5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8fece664-0bce-4288-9267-aa2007a45fb3', 'Class 6', 'Hindi Grammar', 'Chapter 12: विराम चिह्न, संधि एवं शब्द संपदा', 'Hard', 'कक्षा 6 के संपूर्ण हिंदी व्याकरण पाठ्यक्रम का चरम उद्देश्य क्या है?', 'पाठ्यक्रम का लक्ष्य शुद्ध मानक भाषा ज्ञान, तार्किक व्याकरणिक दक्षता, और रचनात्मक अभिव्यक्ति का समग्र परिष्कार है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('924686e5-c842-4eb2-9028-f9dcbccfb860', 'छात्रों में मानक भाषा की शुद्ध वर्तनी, व्याकरणिक नियमों की गहरी समझ, समृद्ध संप्रेषण कौशल तथा रचनात्मक चिंतन का सर्वांगीण विकास करना', true, '8fece664-0bce-4288-9267-aa2007a45fb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f63fb2a6-e868-4a88-9500-bf0a39939ff8', 'केवल परीक्षा के लिए रटना', false, '8fece664-0bce-4288-9267-aa2007a45fb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bff06833-edf5-400b-9e4c-a43af1988754', 'बिना समझे नियम याद करना', false, '8fece664-0bce-4288-9267-aa2007a45fb3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ceb0001-cd68-4b03-ae78-b86fcd4cc7ce', 'अन्य भाषाओं का त्याग करना', false, '8fece664-0bce-4288-9267-aa2007a45fb3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a45e237-a4a8-4c03-b939-049632f5935b', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'The mode of nutrition in which organisms make food themselves from simple inorganic substances is called:', 'Autotrophic nutrition (Auto = self, trophos = nourishment) is the synthesis of organic food by green plants from simple substances.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81fda84f-f5ba-4696-a340-451082080d95', 'Autotrophic Nutrition', true, '0a45e237-a4a8-4c03-b939-049632f5935b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51fbc5d4-bae2-476b-ad4e-355c2cd4e8e8', 'Heterotrophic Nutrition', false, '0a45e237-a4a8-4c03-b939-049632f5935b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e3c48d5-7862-40fc-b77a-83dcfc6c22a7', 'Saprotrophic Nutrition', false, '0a45e237-a4a8-4c03-b939-049632f5935b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9803165c-4c49-41a1-80c5-5f7b1d02e81a', 'Parasitic Nutrition', false, '0a45e237-a4a8-4c03-b939-049632f5935b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d963185d-79a7-4880-89b3-24623d880234', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'The green pigment present in the leaves of plants that captures solar radiant energy for photosynthesis is called:', 'Chlorophyll is the green magnesium-containing pigment in chloroplasts that absorbs sunlight energy for photosynthesis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c906c3fd-b6fe-462b-bf9c-5f4908336898', 'Chlorophyll', true, 'd963185d-79a7-4880-89b3-24623d880234');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5f09553-d1e7-4e1b-b6f4-1bd77ce3070f', 'Hemoglobin', false, 'd963185d-79a7-4880-89b3-24623d880234');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0851bca-9ce1-49ab-a27a-9eea90556fb5', 'Carotene', false, 'd963185d-79a7-4880-89b3-24623d880234');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f57d3a4f-30b2-4636-97e5-1d576863f8bb', 'Anthocyanin', false, 'd963185d-79a7-4880-89b3-24623d880234');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa39b56b-2911-43a0-b921-371b1758cb6b', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'Tiny microscopic pores present on the surface of plant leaves surrounded by guard cells are called:', 'Stomata are microscopic dermal pores enclosed by bean-shaped guard cells that regulate gas exchange and transpiration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41ad3f1c-730f-49f6-88a6-f79d6686c264', 'Stomata', true, 'aa39b56b-2911-43a0-b921-371b1758cb6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0eec327-912f-4efc-8c26-6b44cbb779cd', 'Vessels', false, 'aa39b56b-2911-43a0-b921-371b1758cb6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e866b6e0-2690-4fe4-8f0e-6c08d53f93ab', 'Chloroplasts', false, 'aa39b56b-2911-43a0-b921-371b1758cb6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1b2240c-c11f-41d8-abdc-c451112e7ea5', 'Lenticels', false, 'aa39b56b-2911-43a0-b921-371b1758cb6b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74deb734-28de-4f49-a2b5-5e07c695e7f5', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'What are the essential raw materials required by green plants to carry out Photosynthesis?', 'Photosynthesis combines CO₂ and H₂O in the presence of light and chlorophyll to synthesize carbohydrates and O₂.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3034acf8-04ae-4e70-bed5-abfc2cac785c', 'Carbon dioxide, Water, Chlorophyll, and Sunlight', true, '74deb734-28de-4f49-a2b5-5e07c695e7f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4684021-3a97-4057-9e8f-0e1b20bb3c9e', 'Oxygen, Sugar, Soil, and Nitrogen', false, '74deb734-28de-4f49-a2b5-5e07c695e7f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('352cdc53-691d-4ce1-9694-dfff664db4e9', 'Carbon monoxide, Salt, Heat, and Sand', false, '74deb734-28de-4f49-a2b5-5e07c695e7f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c1bbd34-19e0-4a7d-9e30-ab1e8550376c', 'Glucose, Protein, Clay, and Water', false, '74deb734-28de-4f49-a2b5-5e07c695e7f5');
