INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ddd66d89-894e-4302-8c41-4fd90f3428be', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'Organisms that derive their nourishment in solution form from dead and decaying organic matter (such as Fungi/Mushrooms) are called:', 'Saprotrophs secrete digestive enzymes onto decaying substrates and absorb the liquefied nutrients.', NOW()) ON CONFLICT DO NOTHING;
