INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e24db48-5cbe-422f-9616-8bcf8ce6f66f', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'A symbiotic association in which an Alga (autotroph) and a Fungus (saprotroph) live together in mutual benefit is called a:', 'In Lichens, the green alga manufactures food via photosynthesis while the fungus provides shelter, water, and minerals.', NOW()) ON CONFLICT DO NOTHING;
