INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ef164c63-35e2-43ae-a726-b0eeabf9452d', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'Which chemical test is used to detect the presence of Starch in a green leaf after photosynthesis?', 'Iodine solution forms a characteristic blue-black charge-transfer complex with starch molecules in leaves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5342ea0f-8651-4782-9492-057cffdc0e2e', 'Iodine Solution Test (turns blue-black in presence of starch)', true, 'ef164c63-35e2-43ae-a726-b0eeabf9452d');
