INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3f4e3172-c107-41f2-82ce-9b5d98e8bcaa', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'What are the slimy, green floating patches commonly seen in stagnant ponds and ditches formed by simple photosynthetic organisms called?', 'Algae are simple thallophyte organisms containing chlorophyll that conduct aquatic photosynthesis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c2eacc3-927e-43b4-9553-747a1bce83da', 'Algae', true, '3f4e3172-c107-41f2-82ce-9b5d98e8bcaa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2523e0e0-984c-43bd-ae39-9070aafb6579', 'Fungi', false, '3f4e3172-c107-41f2-82ce-9b5d98e8bcaa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('344ba8f3-24b3-4e1f-bc0c-a9b77604e270', 'Protozoa', false, '3f4e3172-c107-41f2-82ce-9b5d98e8bcaa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e61c1e8-1627-46c3-9d91-94973f06cb67', 'Bacteria', false, '3f4e3172-c107-41f2-82ce-9b5d98e8bcaa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7c0b572c-d8bb-4699-a32a-d9e3e2aa6119', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Easy', 'Which beneficial bacterium lives inside the root nodules of leguminous crops (grams, peas, beans) to fix atmospheric nitrogen into soluble soil nitrates?', 'Rhizobium bacteria form symbiotic root nodules with legumes, biologically fixing inert atmospheric N₂ into fertile nitrates.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d88d69c-b39a-4ae1-98e9-fe287d5d1f60', 'Rhizobium', true, '7c0b572c-d8bb-4699-a32a-d9e3e2aa6119');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3354ef0-1e0b-4c09-8d11-132af3656cec', 'Lactobacillus', false, '7c0b572c-d8bb-4699-a32a-d9e3e2aa6119');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2988d1f-4e21-41ed-bfbb-4a5987dc538e', 'E. coli', false, '7c0b572c-d8bb-4699-a32a-d9e3e2aa6119');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4cc2a8e-fbff-4456-8ffb-3fbd7da0fed9', 'Salmonella', false, '7c0b572c-d8bb-4699-a32a-d9e3e2aa6119');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2bae8823-be8d-4d17-86be-12ca6dec455d', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'Why do insectivorous plants (like the Pitcher Plant) capture and digest insects even though their green leaves carry out photosynthesis?', 'Insectivorous plants are autotrophic for carbon/carbohydrates but carnivorous to supplement nitrogen deficient in marsh soils.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42eb91df-3f63-4345-936b-40836860f808', 'They grow in nitrogen-deficient, boggy acidic soils and trap insects to obtain essential nitrogenous compounds required for protein synthesis', true, '2bae8823-be8d-4d17-86be-12ca6dec455d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63aa511d-c987-4ac3-88de-fd4db300ca64', 'Because they cannot make any glucose at all', false, '2bae8823-be8d-4d17-86be-12ca6dec455d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38013034-e8ad-461e-8f77-1225d7d9219b', 'To protect themselves from insect bites', false, '2bae8823-be8d-4d17-86be-12ca6dec455d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa578a5f-8796-4594-8620-692180fd36b4', 'Because they do not need sunlight', false, '2bae8823-be8d-4d17-86be-12ca6dec455d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('528a8cff-f2d4-4564-b49d-071988b86f58', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'How do water and dissolved mineral nutrients absorbed by roots travel upwards to reach the green leaves?', 'Xylem vessels form continuous hollow tracheary conduits transporting water and minerals upwards by capillary and transpirational pull.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fa55dc0-87d1-425c-814d-abd675839c76', 'Through continuous pipe-like vascular vessels (Xylem tissue) running like pipelines throughout roots, stem, branches, and leaves', true, '528a8cff-f2d4-4564-b49d-071988b86f58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1104c97e-6205-4059-a8af-9962b5d1f539', 'By diffusing across the outer bark', false, '528a8cff-f2d4-4564-b49d-071988b86f58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41b78742-e753-4384-a2bc-b30d39acd95b', 'Carried inside pollen grains', false, '528a8cff-f2d4-4564-b49d-071988b86f58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d2bcbf0-0841-4417-bf7a-9a1f2e10daa1', 'Through stomatal pores', false, '528a8cff-f2d4-4564-b49d-071988b86f58');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a8d9fcc9-bd4a-41ed-9b32-96f0c140bb90', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'Why do leaves that are deep red, brown, or violet in color (such as Croton leaves) also carry out photosynthesis successfully?', 'Anthocyanin and carotenoid pigments mask the green chlorophyll optical color, but photosynthesis proceeds normally.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a00f1cf-0f53-47f7-a9a1-33fc1b133ce2', 'They contain large amounts of red and brown accessory pigments that mask the green chlorophyll, but chlorophyll is still present and functional underneath', true, 'a8d9fcc9-bd4a-41ed-9b32-96f0c140bb90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01071d6e-4393-4690-ba25-2fcd825defb6', 'Because red color is better than green for photosynthesis', false, 'a8d9fcc9-bd4a-41ed-9b32-96f0c140bb90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fef89df-269c-423b-865e-03f34fa57aa6', 'They absorb food directly from surrounding air', false, 'a8d9fcc9-bd4a-41ed-9b32-96f0c140bb90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05d716c8-40c7-4691-b69e-f3acade3445b', 'They only photosynthesize in the dark', false, 'a8d9fcc9-bd4a-41ed-9b32-96f0c140bb90');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7eb6a8c9-e863-4a7e-b935-2b6c165ee337', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'Why does a piece of moist bread develop a fluffy, cottony growth (mold) of green, white, or brown patches when left in a warm, moist room for 2-3 days?', 'Dormant fungal spores (like Rhizopus bread mold) germinate upon contact with warm moist organic substrates.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd24e49b-78ed-4538-93b8-94207ed02b3d', 'Airborne fungal spores land on the moist nutrient-rich bread, germinate into thread-like hyphae, and feed saprotrophically', true, '7eb6a8c9-e863-4a7e-b935-2b6c165ee337');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d567e7b-3214-4ebb-8ac4-1bd60a0e1244', 'The bread converts into green grass', false, '7eb6a8c9-e863-4a7e-b935-2b6c165ee337');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b3783e2-dae9-41cc-97e1-39ea66a8296e', 'Bacteria produce green paint', false, '7eb6a8c9-e863-4a7e-b935-2b6c165ee337');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98f05275-8338-4ef9-9211-0d58aa2d8af5', 'Moisture turns bread into plastic', false, '7eb6a8c9-e863-4a7e-b935-2b6c165ee337');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('003b3ae8-b9f3-40ab-89e4-1b192ae45602', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'Why is the Sun rightfully described as the ''Ultimate Source of Energy'' for all living organisms on planet Earth?', 'Solar photons captured during photosynthetic light reactions drive primary biomass production across the global biosphere.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f796a102-e885-4380-afac-2e182315c198', 'Solar radiant energy captured by green autotrophic plants through photosynthesis forms the foundational chemical energy that powers all herbivores, carnivores, and human food webs', true, '003b3ae8-b9f3-40ab-89e4-1b192ae45602');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77fed9c6-14d4-44e9-832f-b5bd94468534', 'Because the sun burns all waste materials', false, '003b3ae8-b9f3-40ab-89e4-1b192ae45602');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('478509dc-b148-4de2-8f73-b451f14fd3cf', 'Because animals can make food directly from sunlight without plants', false, '003b3ae8-b9f3-40ab-89e4-1b192ae45602');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6ddd94f-7a04-44ec-98fe-f2a11e52b15a', 'Because the sun produces soil directly', false, '003b3ae8-b9f3-40ab-89e4-1b192ae45602');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b45d668-70a2-4d5d-aa17-745688ec3b68', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'How do green plants synthesize PROTEINS when photosynthesis only directly produces carbohydrates (Carbon, Hydrogen, and Oxygen)?', 'Proteins require nitrogen along with C, H, O. Plants utilize soil nitrates absorbed by roots to synthesize amino acids.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('736b2f04-990f-49a3-a1b0-ca002bba832b', 'Plants combine carbohydrates with soluble Nitrogen absorbed from soil (via nitrogen-fixing bacteria and fertilizers) to synthesize amino acids and proteins', true, '0b45d668-70a2-4d5d-aa17-745688ec3b68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d9c0c7a-67de-477d-8b3a-7199e08fb21e', 'Plants absorb proteins directly from rainwater', false, '0b45d668-70a2-4d5d-aa17-745688ec3b68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2647b55e-b255-45e4-8cd5-03a42c57c95d', 'Chlorophyll turns directly into protein in sunlight', false, '0b45d668-70a2-4d5d-aa17-745688ec3b68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('971c1586-cfb7-4024-89dc-35eef82b6b15', 'Plants convert sunlight into iron', false, '0b45d668-70a2-4d5d-aa17-745688ec3b68');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e656a4c-2fac-4d37-9bca-329122ea947a', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'Why do farmers rarely need to add synthetic nitrogenous fertilizers to fields where leguminous crops (like peas, grams, or lentils) are cultivated?', 'Rhizobium-legume symbiosis enriches rhizosphere nitrogen stocks, reducing synthetic chemical fertilizer requirements.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf8cf60a-84ca-4dfb-b7fc-eeba7f910b97', 'Symbiotic Rhizobium bacteria living in the legume root nodules naturally enrich the soil with fixed nitrogen, replenishing soil fertility naturally', true, '2e656a4c-2fac-4d37-9bca-329122ea947a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f90ff385-4802-4051-aae6-8ce452f85a04', 'Because legumes do not require any nitrogen', false, '2e656a4c-2fac-4d37-9bca-329122ea947a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5d8c3f7-4b27-47c8-a75d-3170052d33eb', 'Because legume leaves produce chemical fertilizer powder', false, '2e656a4c-2fac-4d37-9bca-329122ea947a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1da9b68-160d-4ffe-93b1-7f002a9c3fa0', 'Because legumes absorb nitrogen through flowers', false, '2e656a4c-2fac-4d37-9bca-329122ea947a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ec9c1021-303d-46b8-a676-ba0d3a572662', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'What happens when a potted green plant is kept inside a pitch-dark room for 72 hours (3 days) before an Iodine test?', 'Destarching in prolonged darkness exhausts leaf starch reserves via metabolic cellular respiration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79398d0e-6acc-4fad-a897-25fe166591d2', 'The plant gets ''destarched'' as it consumes all its stored starch reserve in respiration without producing new starch, testing negative with iodine (no blue-black color)', true, 'ec9c1021-303d-46b8-a676-ba0d3a572662');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f79b957-976d-4a7f-be96-4d0a0bd458ab', 'The leaves turn permanently blue-black', false, 'ec9c1021-303d-46b8-a676-ba0d3a572662');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d7e74bb-4bb3-4863-b6ef-2b146fb06200', 'The plant produces double the amount of starch', false, 'ec9c1021-303d-46b8-a676-ba0d3a572662');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69ca3b99-87da-4576-b85f-7da505f76fbc', 'The roots turn into stems', false, 'ec9c1021-303d-46b8-a676-ba0d3a572662');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f9b261d-bf49-4e08-9059-aff2ee911dab', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'What is the symbiotic relationship between a Fungus and the roots of higher forest trees (such as Pinus / Oak) known as?', 'Mycorrhizal mutualism expands root surface area for phosphorus/water uptake in exchange for host plant photosynthate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12cc8449-dcf4-4ead-a884-4505ed18ba50', 'Mycorrhiza (Fungus absorbs water and minerals for the tree, while the tree provides photosynthetic carbohydrates to the fungus)', true, '6f9b261d-bf49-4e08-9059-aff2ee911dab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d41b9eb7-2be2-4c8b-8b86-115bd82952e4', 'Parasitism', false, '6f9b261d-bf49-4e08-9059-aff2ee911dab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61a0f3af-6124-46e8-b741-d94ebde5ada6', 'Predation', false, '6f9b261d-bf49-4e08-9059-aff2ee911dab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('005c93a6-63ce-4124-993e-e26611b7ac5b', 'Insectivory', false, '6f9b261d-bf49-4e08-9059-aff2ee911dab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62460d9d-73f3-4513-bf00-a51218ed54c0', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'How do Guard Cells regulate the opening and closing of stomatal pores on leaves?', 'Turgor pressure dynamics: osmotic potassium/water influx increases guard cell turgidity, bowing differential cell walls open.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0980bf8b-b5c2-464a-81e3-50dd2f50d63c', 'Guard cells swell and curve outward when water flows into them to open the pore, and shrink flaccid when water leaves to close the pore', true, '62460d9d-73f3-4513-bf00-a51218ed54c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a81f24c-2bdb-4373-994d-4178bb54f727', 'Guard cells spin around like wheels', false, '62460d9d-73f3-4513-bf00-a51218ed54c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6aa8d07-b923-4166-8519-fed589b2170a', 'They melt in hot sunlight', false, '62460d9d-73f3-4513-bf00-a51218ed54c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46e0005f-976c-4c10-84c1-052e063696d7', 'They break apart permanently at night', false, '62460d9d-73f3-4513-bf00-a51218ed54c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('555bcf9f-5142-4245-aea3-bd941fc1b8ef', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'Why is Cuscuta (Amarbel) classified as a ''Parasite'' while the host tree is harmed?', 'Parasitism represents a (+/-) relationship where the parasite extracts vascular sap without returning metabolic reciprocity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cc823ba-988e-4e2a-919b-5f18e723569d', 'It deprives the host tree of valuable synthesized nutrients without contributing any benefit, weakening the host''s vigor', true, '555bcf9f-5142-4245-aea3-bd941fc1b8ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3b24771-c44b-4c9e-9ab1-f66b71e148e3', 'Because it provides water to the host', false, '555bcf9f-5142-4245-aea3-bd941fc1b8ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c134efc-7432-4118-9436-d2fee67b86e8', 'Because it cleans the host tree leaves', false, '555bcf9f-5142-4245-aea3-bd941fc1b8ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('250798d8-2da9-49c8-875f-c9e9ddb9a529', 'Because it makes the tree grow twice as fast', false, '555bcf9f-5142-4245-aea3-bd941fc1b8ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61e0d906-deb5-41c7-918c-eb778b0acc90', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'What is the role of boiling a leaf in alcohol (ethanol) inside a water bath during the classic Starch test experiment?', 'Boiling in ethanol de-pigments the leaf by dissolving photosynthetic chlorophyll lipids, ensuring clear iodine colorimetry.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80ba63bf-996a-4121-8db1-cda32e1b5be8', 'To dissolve and extract the green chlorophyll completely so that the blue-black iodine color change can be observed clearly without green interference', true, '61e0d906-deb5-41c7-918c-eb778b0acc90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('010ac495-35d4-4192-88c8-a0db11772abd', 'To make the leaf grow bigger', false, '61e0d906-deb5-41c7-918c-eb778b0acc90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cba206b-82a8-4ad5-a1d2-a6fd5559115c', 'To kill the starch molecules', false, '61e0d906-deb5-41c7-918c-eb778b0acc90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f5bb87a-8f88-4ed8-adeb-e53b525627c5', 'To turn the leaf into sugar', false, '61e0d906-deb5-41c7-918c-eb778b0acc90');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10e6dc5b-e6fb-4b07-b4c7-857bed258f96', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'Why cannot human beings or other non-green animals synthesize their own food from atmospheric CO₂ and water like green plants do?', 'Heterotrophs lack thylakoid chloroplast machinery and chlorophyll complexes capable of light-driven photophosphorylation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc8d243d-b771-4e81-ba92-d9bfe499e134', 'Animal cells lack chloroplasts and the green pigment Chlorophyll necessary to absorb and convert solar photonic energy into chemical bonds', true, '10e6dc5b-e6fb-4b07-b4c7-857bed258f96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d99fbb56-48b3-40b1-aa62-99eb854d4488', 'Because animals do not drink enough water', false, '10e6dc5b-e6fb-4b07-b4c7-857bed258f96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62c4853c-f949-4517-b14e-65c5d32f097d', 'Because animal skin is too thick', false, '10e6dc5b-e6fb-4b07-b4c7-857bed258f96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86316215-476f-4781-8eec-5a6629786d7a', 'Because animals walk on legs', false, '10e6dc5b-e6fb-4b07-b4c7-857bed258f96');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('51d2a427-dd4b-48f3-a4b5-c518f55475ca', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'What is the chemical word equation representing Photosynthesis?', 'Photosynthetic stoichiometry: 6CO₂ + 6H₂O + radiant energy → C₆H₁₂O₆ + 6O₂.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('698ab36c-26cb-4b2b-bd04-c26c3c5c7aab', 'Carbon dioxide + Water --(Sunlight / Chlorophyll)--> Carbohydrate (Glucose) + Oxygen', true, '51d2a427-dd4b-48f3-a4b5-c518f55475ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c47c0e5-73b5-4af4-95b3-ed99806841f2', 'Glucose + Oxygen ----> Carbon dioxide + Water + Energy', false, '51d2a427-dd4b-48f3-a4b5-c518f55475ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e49d1f1a-fe97-4414-a6ef-b6ac5bb17fa5', 'Nitrogen + Water ----> Protein + Hydrogen', false, '51d2a427-dd4b-48f3-a4b5-c518f55475ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f686af7b-48da-4fc8-9cc0-9c1fe6bd3149', 'Carbon dioxide + Soil ----> Starch + Salt', false, '51d2a427-dd4b-48f3-a4b5-c518f55475ca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('689fa52c-77cc-4a21-bc6d-b6ef739f5a99', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'Why do fungal infections frequently spoil leather shoes, pickles, wet clothes, and wood furniture during hot and humid monsoon weather?', 'Microscopic ubiquitous fungal spores require warm (25–35°C) and humid (>70% RH) substrates for vegetative hyphal growth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16e03c54-7a96-4c99-b08a-24854d6f0756', 'High humidity (moisture) and warm ambient temperatures provide optimal ecological conditions for airborne fungal spores to settle, germinate, and proliferate rapidly', true, '689fa52c-77cc-4a21-bc6d-b6ef739f5a99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ede7854-cc11-4b2c-ba21-da56a60c5ce1', 'Because leather shoes make food for fungi', false, '689fa52c-77cc-4a21-bc6d-b6ef739f5a99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a68881a6-cad2-4403-8e4b-3fcbd4091a3e', 'Because rain turns clothes into fungi', false, '689fa52c-77cc-4a21-bc6d-b6ef739f5a99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60e71155-bfa2-4557-9b20-e5aea0b99e68', 'Because sunlight stops shining entirely', false, '689fa52c-77cc-4a21-bc6d-b6ef739f5a99');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d5478ca2-a3d0-4bc5-bac7-3ea959220f49', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Medium', 'How do major macronutrients like Nitrogen, Phosphorus, and Potassium (NPK) get depleted in soil over continuous farming?', 'Crop harvest continuously exports bio-accumulated N-P-K mineral reserves from agricultural soils, requiring systematic replenishment.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f22d7fb-f917-4567-a193-bf6f61a7c165', 'Growing crops continuously absorb massive quantities of mineral nutrients from the soil, requiring periodic replenishment via manure, compost, or fertilizers', true, 'd5478ca2-a3d0-4bc5-bac7-3ea959220f49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f748381-8bec-463e-b52f-d8d8acf0623c', 'Rain washes away all soil rocks', false, 'd5478ca2-a3d0-4bc5-bac7-3ea959220f49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3094b09e-5ee7-4aca-9fdf-5bcf0b920fe7', 'Earthworms eat all the soil nitrogen', false, 'd5478ca2-a3d0-4bc5-bac7-3ea959220f49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cf03994-b21b-4a46-9c99-c9376f690d87', 'Wind blows away minerals into clouds', false, 'd5478ca2-a3d0-4bc5-bac7-3ea959220f49');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab0d5efa-068f-4863-96b4-f696be9fa546', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e908b7b-e7ab-4821-bd16-49bb977befd2', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'ab0d5efa-068f-4863-96b4-f696be9fa546');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f217e948-22e5-4727-b26e-2e79f7de2901', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'ab0d5efa-068f-4863-96b4-f696be9fa546');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8052122-f31d-489b-8c8a-caa694edb525', '(A) is true, but (R) is false.', false, 'ab0d5efa-068f-4863-96b4-f696be9fa546');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61d0f2be-5035-4196-8fcb-718aaec6c4cb', '(A) is false, but (R) is true.', false, 'ab0d5efa-068f-4863-96b4-f696be9fa546');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9dc24e11-4f15-40e7-acc8-c01835f4881e', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'Spot the IMPOSTER in the following group of organisms categorized by their primary mode of nutrition:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb5e438a-6ab4-43b8-be88-e1f76e2ab089', 'Mushroom - Saprotroph', false, '9dc24e11-4f15-40e7-acc8-c01835f4881e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53b57684-166a-4272-9916-5b44cd8952cb', 'Yeast - Saprotroph', false, '9dc24e11-4f15-40e7-acc8-c01835f4881e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21b51b62-d3da-4da4-b632-3cac6b01393d', 'Bread Mold (Rhizopus) - Saprotroph', false, '9dc24e11-4f15-40e7-acc8-c01835f4881e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1d1222b-1998-4b27-ada4-562021c8ba35', 'Cuscuta (Amarbel) - Saprotroph', true, '9dc24e11-4f15-40e7-acc8-c01835f4881e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2130d396-5b06-4dc6-955b-7bf3d494b2e2', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'A variegated leaf of a Coleus plant (having green center and white non-green border) is exposed to bright sunlight for 6 hours and tested with Iodine solution. What will be the observed result?', 'Starch is synthesized exclusively in chlorophyll-containing green areas, confirming chlorophyll''s essential catalytic role.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ab9653e-222c-454d-a9c6-b535476c0c85', 'Only the green central region turns blue-black (showing starch present), while the white non-green border remains pale yellow-brown (no starch), proving chlorophyll is indispensable for photosynthesis', true, '2130d396-5b06-4dc6-955b-7bf3d494b2e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4accb39e-5451-412f-a8c2-8126b2c134ba', 'The entire leaf turns uniform blue-black', false, '2130d396-5b06-4dc6-955b-7bf3d494b2e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20892a6d-b863-4a17-88a7-a059ea5feda1', 'Only the white border turns blue-black', false, '2130d396-5b06-4dc6-955b-7bf3d494b2e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68aefc05-6df0-4430-a99a-28de10ab65da', 'The whole leaf turns bright red', false, '2130d396-5b06-4dc6-955b-7bf3d494b2e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('adca8380-e84b-46b9-bd0c-6a08b5ca6770', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'Match Column I (Modes of Plant Nutrition) with Column II (Representative Examples):
(a) Autotroph       -> (i) Cuscuta (Amarbel)
(b) Parasite        -> (ii) Pitcher Plant (Nepenthes)
(c) Saprotroph      -> (iii) Green Algae & Mango tree
(d) Insectivorous   -> (iv) Mushroom (Agaricus)', 'Autotroph = Algae/Mango; Parasite = Cuscuta; Saprotroph = Mushroom; Insectivorous = Pitcher plant.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba51fd2b-218a-4c20-8df6-793ea8a5306d', 'a-(iii), b-(i), c-(iv), d-(ii)', true, 'adca8380-e84b-46b9-bd0c-6a08b5ca6770');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5841f11a-6134-4e98-9911-6fcf439b9099', 'a-(i), b-(iii), c-(ii), d-(iv)', false, 'adca8380-e84b-46b9-bd0c-6a08b5ca6770');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4f3de95-1aa6-4552-8334-362b58dd846a', 'a-(iv), b-(ii), c-(iii), d-(i)', false, 'adca8380-e84b-46b9-bd0c-6a08b5ca6770');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4575986-25f9-4fe6-b9a2-17509af45d9d', 'a-(ii), b-(iv), c-(i), d-(iii)', false, 'adca8380-e84b-46b9-bd0c-6a08b5ca6770');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45aa7e36-81a3-4bbf-a67b-dece6f348b2b', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'Read the statements regarding plant physiology:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('639055ef-d9d3-422c-a182-b16bb9f95c1a', 'Statements 1 and 2 only', true, '45aa7e36-81a3-4bbf-a67b-dece6f348b2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18bbee04-d1fa-42cb-9ca2-5d876b1bf2ea', 'Statements 2 and 3 only', false, '45aa7e36-81a3-4bbf-a67b-dece6f348b2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fb766a1-8a3e-46f0-9620-3111a120eeb9', 'Statements 1 and 3 only', false, '45aa7e36-81a3-4bbf-a67b-dece6f348b2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('039dfe1c-1193-4e2e-84f5-1eccd843f83d', 'All Statements 1, 2, and 3', false, '45aa7e36-81a3-4bbf-a67b-dece6f348b2b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('062c9da8-a153-411d-b16f-6860319cd319', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'Why is the partial carnivorous adaptation in Drosera (Sundew) and Utricularia (Bladderwort) considered an evolutionary masterpiece?', 'Carnivory circumvents soil nitrogen/phosphorus limitations in bogs through enzymatic breakdown of captured arthropod biomass.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdc0810b-69ba-43c8-b426-dae140afc6f5', 'It allows plants to colonize ultra-oligotrophic, waterlogged, and nutrient-poor wetlands where competing non-carnivorous autotrophs cannot survive due to nitrogen starvation', true, '062c9da8-a153-411d-b16f-6860319cd319');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea160143-b64e-47e6-991c-76ba84abde1d', 'Because it turns the plants into active animals', false, '062c9da8-a153-411d-b16f-6860319cd319');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97ca5241-2a03-42c7-8972-2536cefd564d', 'Because they no longer require any water or carbon dioxide', false, '062c9da8-a153-411d-b16f-6860319cd319');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dbb13cf-de87-4444-845c-497d4687a315', 'Because they live underground without light', false, '062c9da8-a153-411d-b16f-6860319cd319');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3d3f1a0-46ea-4787-963c-f33268ac92b3', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'Why do underwater submerged aquatic plants (like Hydrilla and Vallisneria) have narrow ribbon-like leaves and lack stomatal pores with cuticles?', 'Hydrophytic adaptations eliminate stomata/cuticles to allow direct trans-epidermal diffusion of dissolved aquatic gases.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be7595a3-0837-43cb-90eb-6bf8ed6a94c3', 'Narrow flexible leaves withstand flowing water currents without tearing, and dissolved gases (CO₂ and O₂) diffuse directly across thin epidermal cell walls', true, 'd3d3f1a0-46ea-4787-963c-f33268ac92b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc73cc85-97f6-4b43-aaf4-50eb91c363a5', 'Because they do not need any carbon dioxide', false, 'd3d3f1a0-46ea-4787-963c-f33268ac92b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59cf032f-d328-4e49-8600-d69dd7d5e7f2', 'To avoid being eaten by sharks', false, 'd3d3f1a0-46ea-4787-963c-f33268ac92b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ffacde6-69dc-4cb1-bea3-7dd5bf75fdd3', 'Because they only absorb food from soil', false, 'd3d3f1a0-46ea-4787-963c-f33268ac92b3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22a7d843-6cb8-426f-b8fd-26c52117777c', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'Consider four experimental setups of potted plants:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f1a94e9-c3c6-4635-81b4-14a4dc22e03a', 'Sets 2 and 4 only', true, '22a7d843-6cb8-426f-b8fd-26c52117777c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44693ae3-bfc6-47fd-b803-6b906c1a1faa', 'Sets 1 and 3 only', false, '22a7d843-6cb8-426f-b8fd-26c52117777c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63e7d2af-8be0-4f83-b173-146325883593', 'Set 4 only', false, '22a7d843-6cb8-426f-b8fd-26c52117777c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aff30a90-cab3-4039-abfd-faf66f241eef', 'All 4 Sets', false, '22a7d843-6cb8-426f-b8fd-26c52117777c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('efbaa7c1-3468-48e8-9d98-67c85193d890', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'How do Lichens serve as sensitive ''Bio-indicators'' of atmospheric air quality in environmental monitoring?', 'Lacking roots and protective cuticles, symbiotic lichens hyper-absorb atmospheric SO₂, serving as classic biological air quality monitors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31fe1481-05f6-432e-a097-33b6bf49c418', 'Lichens are extraordinarily sensitive to toxic atmospheric Sulfur Dioxide (SO₂) air pollution and cannot survive in heavily polluted urban/industrial areas', true, 'efbaa7c1-3468-48e8-9d98-67c85193d890');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('697020a2-4ca1-46f3-950d-fa9d2635f7da', 'They change their color to neon purple in clean air', false, 'efbaa7c1-3468-48e8-9d98-67c85193d890');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('400e5802-8137-44d1-9913-acaa8ff545ea', 'They absorb plastic from the air', false, 'efbaa7c1-3468-48e8-9d98-67c85193d890');
