INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7eb6d308-2ce9-4342-82e4-edb1fbaa018b', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'What is the precise cellular organelle inside green plant mesophyll cells where photosynthesis takes place?', 'Chloroplasts contain thylakoid membranes with light-harvesting chlorophyll and stroma enzymes for Calvin cycle carbohydrate synthesis.', NOW()) ON CONFLICT DO NOTHING;
