INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c38574c7-8ab6-441c-ae3f-3ee77bfbdb04', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'What biochemical transformation happens to glucose molecules immediately after synthesis in leaf mesophyll cells?', 'Soluble osmotic glucose is condensed into insoluble, non-reactive amylose/amylopectin starch grains for osmotic equilibrium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38ea16ee-f386-426e-97ec-1dea619f47f2', 'Excess glucose is rapidly polymerized into insoluble complex Starch for compact long-term storage and later translocated as sucrose via phloem', true, 'c38574c7-8ab6-441c-ae3f-3ee77bfbdb04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('363d98a8-71c4-4a5e-8552-f6caf12ddd5a', 'Glucose turns into pure gold crystals', false, 'c38574c7-8ab6-441c-ae3f-3ee77bfbdb04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('602197b0-6a4e-44dc-9921-4b9599c77dd1', 'It evaporates immediately into the sky', false, 'c38574c7-8ab6-441c-ae3f-3ee77bfbdb04');
