INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3eb8e123-c177-4d0e-b40a-09593637081c', 'Class 7', 'Science', 'Chapter 1: Nutrition in Plants', 'Hard', 'What overarching biological principle is illuminated in Chapter 1 of NCERT Class 7 Science?', 'Chapter 1 establishes plant autotrophy and ecological symbiosis as the foundational energy conduit of terrestrial biomes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f814cf9-3a25-45ed-a802-2b2cc12eea67', 'Autotrophic green plants form the indispensable biological bedrock of terrestrial life, sustaining global biogeochemical energy flow, oxygen renewal, and complex symbiotic networks', true, '3eb8e123-c177-4d0e-b40a-09593637081c');
