INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d4e98f0-1fe4-40d9-bf21-826142865438', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'Find the product: (-1) × (-2) × (-3) × (-4) × (-5):', 'There are 5 negative factors (odd count) → product is negative: -(1 × 2 × 3 × 4 × 5) = -120.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b12540f-e120-45f9-8b3e-754d95b646f9', '-120 (Multiplying an ODD number (5) of negative signs yields a NEGATIVE result)', true, '6d4e98f0-1fe4-40d9-bf21-826142865438');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7246ed00-ce8d-4b3b-88ca-a6661bce7a06', '+120', false, '6d4e98f0-1fe4-40d9-bf21-826142865438');
