INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93c75397-eec8-4ebc-a6a7-0c323beed32e', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'Find the product: (-2) × (-5) × (-4) × (-10):', '4 negative factors (even count) → product is positive: +(2 × 5 × 4 × 10) = +400.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dbfec20-9758-432f-8d2b-08811b9ef4dd', '+400 (Multiplying an EVEN number (4) of negative signs yields a POSITIVE result)', true, '93c75397-eec8-4ebc-a6a7-0c323beed32e');
