INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ad69420-fd44-486d-8756-76bfa7660a46', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'In a class test containing 15 questions, 4 marks are given for every correct answer and (-2) marks are given for every incorrect answer. Gurpreet attempts all questions but only 9 of her answers are correct. What is her total score?', 'Correct marks = 9 × 4 = 36. Incorrect marks = (15 - 9) × (-2) = -12. Total = 36 - 12 = 24.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67db2023-4d94-478e-8d3f-932a44bf45f5', '24 marks (Correct = 9 × 4 = 36 ; Incorrect = 6 × (-2) = -12 ; Total = 36 + (-12) = 24)', true, '6ad69420-fd44-486d-8756-76bfa7660a46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('919e5547-57a5-41ca-83d4-3e44d6ba8103', '36 marks', false, '6ad69420-fd44-486d-8756-76bfa7660a46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0b820af-90bc-4e5c-9d83-6bc1f35a9c06', '12 marks', false, '6ad69420-fd44-486d-8756-76bfa7660a46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4aabb0c-9557-49df-80eb-42c6b6601436', '30 marks', false, '6ad69420-fd44-486d-8756-76bfa7660a46');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d0c2c7f-5c72-47d1-8a3c-b0b917fc5334', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'In the same test (4 marks for correct, -2 for incorrect), one of Gurpreet''s friends gets only 5 answers correct out of 15 attempted questions. What is her friend''s total score?', 'Score = (5 × 4) + (10 × (-2)) = 20 - 20 = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dfdf157-0cac-49dc-9d2f-90a915852ef1', '0 marks (Correct = 5 × 4 = 20 ; Incorrect = 10 × (-2) = -20 ; Total = 20 + (-20) = 0)', true, '1d0c2c7f-5c72-47d1-8a3c-b0b917fc5334');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a9f881b-4685-48ef-8659-c49c495029ea', '20 marks', false, '1d0c2c7f-5c72-47d1-8a3c-b0b917fc5334');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df99ddf5-3329-4a39-9e85-06b36f13b2c5', '-10 marks', false, '1d0c2c7f-5c72-47d1-8a3c-b0b917fc5334');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b461960-7c6e-4948-8daf-120dd1d36cfb', '10 marks', false, '1d0c2c7f-5c72-47d1-8a3c-b0b917fc5334');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7555093-4cc2-47f4-b93f-5eb8fec62a5d', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'An elevator descends into a mine shaft at the rate of 6 metres per minute. If the descent starts from 10 m ABOVE the ground level, how long will it take to reach -350 m (350 m below ground)?', 'Total vertical drop = 10 - (-350) = 360 m. Time = 360 ÷ 6 = 60 minutes = 1 hour.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23b297ee-78ad-4464-a81b-5e39d303b875', '60 minutes (1 hour) (Total distance = 10 - (-350) = 360 m ; Time = 360 / 6 = 60 minutes)', true, 'b7555093-4cc2-47f4-b93f-5eb8fec62a5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a40d9496-4242-4341-ad10-ed7ca499f6b7', '50 minutes', false, 'b7555093-4cc2-47f4-b93f-5eb8fec62a5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f629f8b-725f-40de-9b44-654ed66e938c', '45 minutes', false, 'b7555093-4cc2-47f4-b93f-5eb8fec62a5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6301335a-01bb-4d7c-b371-85f5b44693fb', '70 minutes', false, 'b7555093-4cc2-47f4-b93f-5eb8fec62a5d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad99e52c-cad6-4aa5-a870-2b7da3575dbf', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'At Srinagar, the temperature was -5°C on Monday and then it dropped by 2°C on Tuesday. What was the temperature of Srinagar on Tuesday? On Wednesday, it rose by 4°C. What was the temperature on Wednesday?', 'Tuesday = -5 - 2 = -7°C. Wednesday = -7 + 4 = -3°C.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('136861e5-a21c-43c5-b58c-1c94c70a8788', 'Tuesday: -7°C ; Wednesday: -3°C', true, 'ad99e52c-cad6-4aa5-a870-2b7da3575dbf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('037b1412-3c98-4930-bcf3-7218438785b2', 'Tuesday: -3°C ; Wednesday: +1°C', false, 'ad99e52c-cad6-4aa5-a870-2b7da3575dbf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('288e267c-7adb-49ef-add9-b442fd30b1dd', 'Tuesday: -7°C ; Wednesday: +4°C', false, 'ad99e52c-cad6-4aa5-a870-2b7da3575dbf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4e69454-10db-489c-92fc-afaa3f14a8a5', 'Tuesday: -10°C ; Wednesday: -6°C', false, 'ad99e52c-cad6-4aa5-a870-2b7da3575dbf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc03ca79-deaf-41de-92d7-d441a0f69d2a', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'A cement company earns a profit of ₹8 per bag of white cement sold and a loss of ₹5 per bag of grey cement sold. If the company sells 3,000 bags of white cement and 5,000 bags of grey cement in a month, what is its net profit or loss?', 'Profit on white = 3000 × 8 = ₹24,000. Loss on grey = 5000 × 5 = ₹25,000. Net = 24,000 - 25,000 = -₹1,000 (Loss).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('491d6f00-9240-4001-8c22-97357308021d', 'Loss of ₹1,000 (Profit = 3000 × 8 = ₹24,000 ; Loss = 5000 × (-5) = -₹25,000 ; Net = 24,000 - 25,000 = -₹1,000)', true, 'dc03ca79-deaf-41de-92d7-d441a0f69d2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('598d9934-af3f-4956-93ac-dd2f5666d0b9', 'Profit of ₹1,000', false, 'dc03ca79-deaf-41de-92d7-d441a0f69d2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e504b0ae-722a-4afa-9bf9-ab9a900f8a36', 'Profit of ₹24,000', false, 'dc03ca79-deaf-41de-92d7-d441a0f69d2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85d2b18e-23a1-4bdc-9723-098b63ab1a89', 'Loss of ₹5,000', false, 'dc03ca79-deaf-41de-92d7-d441a0f69d2a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60a009f4-6885-45d0-9e3c-a763d534d8c8', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'In the same cement problem (₹8 profit/white bag, ₹5 loss/grey bag), how many white cement bags must the company sell to have neither profit nor loss if the number of grey bags sold is 6,400 bags?', 'Total loss = 6400 × 5 = ₹32,000. Required white bags = 32000 ÷ 8 = 4,000 bags.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a514f78d-0067-4f60-865b-6a3f24882034', '4,000 bags (Loss on grey = 6400 × 5 = ₹32,000 ; White bags needed = 32,000 / 8 = 4,000 bags)', true, '60a009f4-6885-45d0-9e3c-a763d534d8c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b75a203-ad90-42bc-8a3e-517260daff4c', '3,200 bags', false, '60a009f4-6885-45d0-9e3c-a763d534d8c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('039ee481-cf39-485f-a8c4-f21524f2edbc', '5,000 bags', false, '60a009f4-6885-45d0-9e3c-a763d534d8c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d1d9d31-1cc4-4e1b-902e-9f0787a36861', '4,800 bags', false, '60a009f4-6885-45d0-9e3c-a763d534d8c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab587a0b-9891-4cf5-b3fa-79d44f775d1e', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'Fill in the blank with suitable integer: (-3) × [ _____ ] = +27', 'Missing integer = 27 ÷ (-3) = -9.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3e3af5f-120a-49fd-86a5-20a3df9d5118', '-9 (Since (-3) × (-9) = +27)', true, 'ab587a0b-9891-4cf5-b3fa-79d44f775d1e');
