INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2150f44f-f6b7-448b-9948-791044c3e497', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'Fill in the blank with suitable integer: [ _____ ] ÷ (-12) = -8', 'Missing integer = (-8) × (-12) = +96.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f335666a-25b2-4bb2-a19a-cbd4cf53d31c', '+96 (Since 96 ÷ (-12) = -8)', true, '2150f44f-f6b7-448b-9948-791044c3e497');
