INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d2e1b91-a751-42c4-b0da-b58be0107151', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'Which of the following mathematical properties holds strictly TRUE for Division of Integers?', 'Division of integers violates both commutative property (a ÷ b ≠ b ÷ a) and associative property.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d94fbd0-f8ba-491a-a758-476552e9cbfb', 'Division is NOT Commutative and NOT Associative for integers (e.g. 8 ÷ (-4) ≠ (-4) ÷ 8)', true, '7d2e1b91-a751-42c4-b0da-b58be0107151');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9e69f9e-8c41-447b-968c-2c26036135e6', 'Division is Commutative for integers', false, '7d2e1b91-a751-42c4-b0da-b58be0107151');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7cee43a-1c82-4137-aecb-7ee50c3abf4f', 'Division is Associative for integers', false, '7d2e1b91-a751-42c4-b0da-b58be0107151');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c59992e-b3f4-4987-90c1-ae615384591b', 'Division by zero equals zero', false, '7d2e1b91-a751-42c4-b0da-b58be0107151');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dad7ca99-4982-456d-b2cd-a163aa6dd4ca', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'Evaluate: [ (-30) ÷ 10 ] ÷ 3', '(-30 ÷ 10) ÷ 3 = (-3) ÷ 3 = -1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad9403ac-ed74-4a47-aae9-6cf72e0927ce', '-1 (Inside bracket: -30 ÷ 10 = -3 ; -3 ÷ 3 = -1)', true, 'dad7ca99-4982-456d-b2cd-a163aa6dd4ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f14147e5-d159-450c-98a9-4aa5ade2cf4d', '+1', false, 'dad7ca99-4982-456d-b2cd-a163aa6dd4ca');
