INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e931d319-f324-4709-a9d6-3d9f27239d7d', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'Evaluate: [ (-6) + 5 ] ÷ [ (-2) + 1 ]', '(-6 + 5) ÷ (-2 + 1) = (-1) ÷ (-1) = +1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10538cc6-5876-44f5-bdd1-537b93c309ab', '+1 (Numerator: -1 ; Denominator: -1 ; -1 ÷ -1 = +1)', true, 'e931d319-f324-4709-a9d6-3d9f27239d7d');
