INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('657c1baa-c161-492a-b507-efaf03ec4c04', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Medium', 'The temperature at 12 noon was 10°C above zero (+10°C). If it decreases at the rate of 2°C per hour until midnight, at what time will the temperature be 8°C below zero (-8°C)?', 'Total temperature drop = 10 - (-8) = 18°C. Time = 18 ÷ 2 = 9 hours. 12 noon + 9h = 9:00 PM.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b2abcbf-e6e9-4e02-a70e-9b4c7260f9e4', '9:00 PM (Total decrease = 10 - (-8) = 18°C ; Hours required = 18 / 2 = 9 hours ; 12 noon + 9 hours = 9 PM)', true, '657c1baa-c161-492a-b507-efaf03ec4c04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dd4559b-cdc7-4b7d-966d-c342cfa73d7e', '8:00 PM', false, '657c1baa-c161-492a-b507-efaf03ec4c04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1511ce05-b338-44ef-bae2-807fb15e847d', '10:00 PM', false, '657c1baa-c161-492a-b507-efaf03ec4c04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67962923-b5df-446f-8d1a-5c1172223eda', '11:00 PM', false, '657c1baa-c161-492a-b507-efaf03ec4c04');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca720281-4e08-4cfa-944b-ebdfba17eb1d', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f11d2a9-03d9-401b-94c8-86a05ebad0b5', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'ca720281-4e08-4cfa-944b-ebdfba17eb1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0edd5871-150a-40dd-860d-0aad29e2c579', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'ca720281-4e08-4cfa-944b-ebdfba17eb1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fa35f82-87d2-4b60-a9a7-a9114ffbf5ff', '(A) is true, but (R) is false.', false, 'ca720281-4e08-4cfa-944b-ebdfba17eb1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4945f7cf-b69a-48a2-afa7-f877a04e1f75', '(A) is false, but (R) is true.', false, 'ca720281-4e08-4cfa-944b-ebdfba17eb1d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4e18f44-6046-46f0-b0d9-531cf792f8b6', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'Spot the IMPOSTER among the following statements regarding Integer Properties:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac4130ac-22c0-417d-8ee6-128bca4de11a', 'Statement 1', false, 'd4e18f44-6046-46f0-b0d9-531cf792f8b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6b3eb92-3b77-4f24-a946-5ded39163702', 'Statement 2', false, 'd4e18f44-6046-46f0-b0d9-531cf792f8b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88f07950-8528-4283-aa36-51f3b6947bd4', 'Statement 3 (Subtraction is NOT commutative for integers)', true, 'd4e18f44-6046-46f0-b0d9-531cf792f8b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a040383-03e7-485f-85c1-a325f10e75d3', 'Statement 4', false, 'd4e18f44-6046-46f0-b0d9-531cf792f8b6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa2b3915-0b9a-4d29-b061-8ec730411b7b', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'Evaluate the nested integer expression:
(-1) × (-1) × (-1) × ... (multiplied 99 times) + (-1) × (-1) × (-1) × ... (multiplied 100 times):', '(-1) raised to an odd power (99) is -1. (-1) raised to an even power (100) is +1. (-1) + (+1) = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc3ef198-ff08-4195-9764-ab4618d63396', '0 ((-1)^99 = -1 and (-1)^100 = +1 ; Sum = -1 + 1 = 0)', true, 'aa2b3915-0b9a-4d29-b061-8ec730411b7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aea282f8-43d3-4419-b03f-bd1d76c26f35', '-2', false, 'aa2b3915-0b9a-4d29-b061-8ec730411b7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39baa2d2-a9ec-45ec-a185-c0005f2feb5b', '+2', false, 'aa2b3915-0b9a-4d29-b061-8ec730411b7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb1e3eeb-86c3-4b71-8ee0-217b8c80dac2', '-1', false, 'aa2b3915-0b9a-4d29-b061-8ec730411b7b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53f8a475-49cc-4ae8-983d-1d53d9020ac0', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'Match Column I (Algebraic Integer Identity) with Column II (Name of Property):
(a) a + b = b + a              -> (i) Associative Property of Addition
(b) a × (b × c) = (a × b) × c  -> (ii) Distributive Property of Multiplication over Addition
(c) (a + b) + c = a + (b + c)  -> (iii) Commutative Property of Addition
(d) a × (b + c) = ab + ac      -> (iv) Associative Property of Multiplication', 'a+b = b+a (Commutative +); a(bc) = (ab)c (Associative ×); (a+b)+c = a+(b+c) (Associative +); a(b+c) = ab+ac (Distributive).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7551a968-467a-4d04-979c-c9d2567803ce', 'a-(iii), b-(iv), c-(i), d-(ii)', true, '53f8a475-49cc-4ae8-983d-1d53d9020ac0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1f738f4-8ff6-427d-89a6-70b69905e800', 'a-(i), b-(ii), c-(iii), d-(iv)', false, '53f8a475-49cc-4ae8-983d-1d53d9020ac0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8793ef4-12de-41a8-aa28-7b67c871e62f', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '53f8a475-49cc-4ae8-983d-1d53d9020ac0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15ba1d9f-8d9d-4de0-841a-c082a517ed31', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '53f8a475-49cc-4ae8-983d-1d53d9020ac0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f42ba4c1-d37c-4b14-bf83-81d8aefdd28d', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'Read the statements regarding integer verification:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dedaca3-cfb0-437d-bb0d-5a3009225bc8', 'Statements 1 and 2 only', true, 'f42ba4c1-d37c-4b14-bf83-81d8aefdd28d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41b4ec3c-791a-44dc-a313-8e549aac6eb0', 'Statements 2 and 3 only', false, 'f42ba4c1-d37c-4b14-bf83-81d8aefdd28d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7803f85-774d-4542-a9e5-df45666375db', 'Statements 1 and 3 only', false, 'f42ba4c1-d37c-4b14-bf83-81d8aefdd28d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9ad1776-2840-4053-9a7b-78efb6d59a7d', 'All Statements 1, 2, and 3', false, 'f42ba4c1-d37c-4b14-bf83-81d8aefdd28d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89c68e0b-8ddf-40fd-ae44-1c919b099ada', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'If a = -8, b = -7, and c = 6, verify the value of (a + b) + c and a + (b + c):', '(-8 + -7) + 6 = -15 + 6 = -9. -8 + (-7 + 6) = -8 + (-1) = -9. Confirms Associative Property of Addition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10ea5e3d-8740-482c-bed8-090a76a51c46', 'Both equal -9 (((-8 + -7) + 6 = -15 + 6 = -9) and (-8 + (-7 + 6) = -8 + -1 = -9))', true, '89c68e0b-8ddf-40fd-ae44-1c919b099ada');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52906af9-850f-4fd0-bee5-2806bbd25104', 'Both equal +9', false, '89c68e0b-8ddf-40fd-ae44-1c919b099ada');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f709787-bf11-429f-a629-d99e8f884f45', 'First is -9, second is +5', false, '89c68e0b-8ddf-40fd-ae44-1c919b099ada');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5d21e38-2ef4-4ce0-9f86-f3bfb38b1231', 'Both equal -21', false, '89c68e0b-8ddf-40fd-ae44-1c919b099ada');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0648c9bf-1d5e-4ea5-889e-660727a6a462', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'Solve for x: (-15) × [ x + (-3) ] = (-15) × 8 + (-15) × (-3)', 'Comparing with Distributive law a × (b + c) = ab + ac: here a = -15, b = x = 8, c = -3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f84890e-9c81-4e31-a477-022cf2634570', 'x = 8 (By the Distributive Property: a × (x + b) = a × x + a × b ⇒ x = 8)', true, '0648c9bf-1d5e-4ea5-889e-660727a6a462');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e27daa43-c935-4f5a-8929-429c3ddb197a', 'x = -8', false, '0648c9bf-1d5e-4ea5-889e-660727a6a462');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('255a52b9-eed0-4bb1-8147-db4db2990d64', 'x = 3', false, '0648c9bf-1d5e-4ea5-889e-660727a6a462');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33331178-5694-4bcb-a93a-782ceae34885', 'x = -3', false, '0648c9bf-1d5e-4ea5-889e-660727a6a462');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68c05600-2e3a-4b85-89a3-17783178f670', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'A submarine is cruising at a depth of -650 m below sea level. It ascends 230 m, then dives down 180 m, and finally ascends 320 m. What is the final operating depth of the submarine relative to sea level?', '-650 + 230 - 180 + 320 = -420 - 180 + 320 = -600 + 320 = -280 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da199325-b5be-4391-8193-6151130de9c5', '-280 m below sea level (-650 + 230 - 180 + 320 = -280 m)', true, '68c05600-2e3a-4b85-89a3-17783178f670');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6995d295-49f4-43ef-93cc-104c4e856065', '-320 m below sea level', false, '68c05600-2e3a-4b85-89a3-17783178f670');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e780963-a2d3-4983-9688-c37ca2565e3b', '-410 m below sea level', false, '68c05600-2e3a-4b85-89a3-17783178f670');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ee3f21b-9862-4e28-aad5-345f603e607a', '-180 m below sea level', false, '68c05600-2e3a-4b85-89a3-17783178f670');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c69886f-82fd-464f-a67d-0eed52941fe5', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'Evaluate: (-325) × (-45) + (-325) × (-55)', 'Factoring out -325: (-325) × [(-45) + (-55)] = (-325) × (-100) = +32,500.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7214cbc5-4d88-4d70-bd7c-4da11c150c51', '+32,500 ((-325) × [(-45) + (-55)] = (-325) × (-100) = +32,500)', true, '9c69886f-82fd-464f-a67d-0eed52941fe5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78790916-b0f0-4767-b016-3b29cb5b69b6', '-32,500', false, '9c69886f-82fd-464f-a67d-0eed52941fe5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27c535c1-3119-4956-a421-e27c46c91bc4', '+3,250', false, '9c69886f-82fd-464f-a67d-0eed52941fe5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('366c6635-73fc-41f9-bd7b-472a64a337ee', '-3,250', false, '9c69886f-82fd-464f-a67d-0eed52941fe5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eec5aea2-35c6-4c7f-91db-1b4f5976de00', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'In a 20-question math competition, +5 marks are awarded for each correct answer, -3 marks for each incorrect answer, and 0 for unattempted questions. Rohan attempted 18 questions and got 14 correct. Priya attempted all 20 questions and got 15 correct. Who scored higher and by how many marks?', 'Rohan = 14×5 + 4×(-3) = 70 - 12 = 58. Priya = 15×5 + 5×(-3) = 75 - 15 = 60. Priya scored 60 vs 58 (+2 marks higher).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('220e50dd-059e-4feb-ae2e-67629ce67e6c', 'Rohan scored higher by 2 marks (Rohan: 14(5) + 4(-3) = 70 - 12 = 58 ; Priya: 15(5) + 5(-3) = 75 - 15 = 60 ... Wait: Priya = 60, Rohan = 58 ⇒ Priya is higher by 2 marks)', false, 'eec5aea2-35c6-4c7f-91db-1b4f5976de00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3775ca13-3fb9-419e-94e7-3c3049a3bdf6', 'Priya scored higher by 2 marks (Priya: 15(5) + 5(-3) = 60 ; Rohan: 14(5) + 4(-3) = 58 ; Priya is higher by 2 marks)', true, 'eec5aea2-35c6-4c7f-91db-1b4f5976de00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa08cca1-3005-4511-91c0-9b50056a87c2', 'Both scored exactly the same', false, 'eec5aea2-35c6-4c7f-91db-1b4f5976de00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1111534e-30c5-42bc-8eb2-b6fa2384d0a9', 'Rohan is higher by 5 marks', false, 'eec5aea2-35c6-4c7f-91db-1b4f5976de00');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('86c8b25f-9232-44ea-8ae0-37329be1d71b', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'If the product of two integers is -180 and one of the integers is +12, find the sum of the two integers:', 'Other integer = -180 ÷ 12 = -15. Sum = 12 + (-15) = -3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('012faa36-4250-4e6b-88bc-28bc34d48b94', '-3 (Second integer = -180 / 12 = -15 ; Sum = 12 + (-15) = -3)', true, '86c8b25f-9232-44ea-8ae0-37329be1d71b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93034c02-e5ed-423c-baa0-dc7f5ae2064b', '+3', false, '86c8b25f-9232-44ea-8ae0-37329be1d71b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5c4818f-3797-48ae-bd4c-ae3fa5e54a49', '-27', false, '86c8b25f-9232-44ea-8ae0-37329be1d71b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c2d6035-f671-4228-9fb2-427e4ac7e552', '+27', false, '86c8b25f-9232-44ea-8ae0-37329be1d71b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea6edcbe-24ac-4fd1-9704-a0fe7b8baeee', 'Class 7', 'Mathematics', 'Chapter 1: Integers', 'Hard', 'Why is the complete mastery of Integers and their sign algebraic laws fundamental to all future mathematics (algebra, coordinate geometry, calculus, and computing)?', 'Integers provide the foundational algebraic ring (ℤ, +, ×) modeling directed quantities, vectors, and sign arithmetic in higher mathematics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93592fb0-3654-4614-aa70-1b78d2cca5fe', 'It establishes bidirectional numerical continuity across positive and negative domains, vector magnitudes, directed quantities, and rigorous symbolic operations', true, 'ea6edcbe-24ac-4fd1-9704-a0fe7b8baeee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('259f6a1e-0570-4b1a-85fb-c5d180091719', 'Because negative numbers only exist in bank debts', false, 'ea6edcbe-24ac-4fd1-9704-a0fe7b8baeee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08824298-5fd3-4ddc-8e47-f3b909168321', 'Because integers eliminate the need for multiplication', false, 'ea6edcbe-24ac-4fd1-9704-a0fe7b8baeee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff17e577-1913-49dd-8bfa-7ec49230e83a', 'Because only positive numbers are used in science', false, 'ea6edcbe-24ac-4fd1-9704-a0fe7b8baeee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d9bee464-a6e2-4895-b3b2-b17342628329', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'In Leo Tolstoy''s famous story ''Three Questions'', what were the three fundamental questions the King wanted answers to?', 'Tolstoy''s king sought wisdom on: right time to act, right people to heed, and most crucial enterprise to undertake.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2bf7d07-b868-4944-8d36-ebd41892de11', '1. What is the right time to begin something? 2. Which people should he listen to? 3. What is the most important thing for him to do?', true, 'd9bee464-a6e2-4895-b3b2-b17342628329');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0586166-6652-4acc-8fa2-fd6d4ad849aa', '1. How to defeat enemies? 2. How much gold to collect? 3. Where to build castles?', false, 'd9bee464-a6e2-4895-b3b2-b17342628329');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdbf8b85-eb04-4d7e-b382-4d2245c7dfeb', '1. When to sleep? 2. What to eat? 3. How to ride horses?', false, 'd9bee464-a6e2-4895-b3b2-b17342628329');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0aa67c0-dcec-46d4-a7d2-9365e4b07e57', '1. Who is the richest king? 2. Where is the magic cave? 3. How to live forever?', false, 'd9bee464-a6e2-4895-b3b2-b17342628329');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76049a2c-0fa0-46a7-a02b-c40e79be91e2', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'Whom did the King decide to visit in the deep forest to seek true wisdom after being dissatisfied with the wise men''s conflicting answers?', 'The king disguised himself in simple peasant clothing and left his horse behind to consult the forest hermit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d26162b0-0599-48e7-a5d2-c09c7247b537', 'A simple, wise Hermit who lived alone in a hut in the woods and received only common folk', true, '76049a2c-0fa0-46a7-a02b-c40e79be91e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0d70ce1-2720-4972-99be-ee766d99b4d0', 'A powerful sorcerer with a crystal ball', false, '76049a2c-0fa0-46a7-a02b-c40e79be91e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ba76368-4bf5-4018-991d-0b6f19a50753', 'An astrologer in the royal palace', false, '76049a2c-0fa0-46a7-a02b-c40e79be91e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e66664f-46fe-43b9-a2ca-ea285af43032', 'A foreign emperor', false, '76049a2c-0fa0-46a7-a02b-c40e79be91e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('127c28ff-029d-426d-82ca-cad2f04528d3', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'What was the frail, old Hermit doing when the King arrived at his forest hut?', 'The hermit was laboriously digging flower/seed beds in front of his hut, breathing heavily from physical exertion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ba959e6-03c1-43c5-80ec-b72b26d8c56e', 'Digging ground beds in front of his hut with a spade', true, '127c28ff-029d-426d-82ca-cad2f04528d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c478617-95c1-4da1-80be-c2994deac78f', 'Sleeping under a tree', false, '127c28ff-029d-426d-82ca-cad2f04528d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3b095a1-1b3c-474b-a4cb-78030992780e', 'Reading a large book', false, '127c28ff-029d-426d-82ca-cad2f04528d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46ddc83c-cfa5-4483-9c72-295b9ffe6e6d', 'Cooking soup', false, '127c28ff-029d-426d-82ca-cad2f04528d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25a21e3e-dae0-45fb-8a35-0c2ea1380900', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'How did the King help the exhausted Hermit upon arrival?', 'Seeing the hermit''s frailty, the king took the spade and dug the ground tirelessly until evening.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4e4db02-c793-42ed-bd7b-8228bf622737', 'The King took the heavy spade from the hermit''s hands and dug the ground beds for him until sunset', true, '25a21e3e-dae0-45fb-8a35-0c2ea1380900');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05a89dfd-b89e-4819-be7d-58964fe3d7a4', 'He gave the hermit a bag of gold', false, '25a21e3e-dae0-45fb-8a35-0c2ea1380900');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fe5d6f5-f694-4159-b47e-adaf8360cec2', 'He ordered his soldiers to carry the hermit', false, '25a21e3e-dae0-45fb-8a35-0c2ea1380900');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbb7b127-805a-44ea-bd85-b0f4b3d7c8e9', 'He sat down and watched the hermit struggle', false, '25a21e3e-dae0-45fb-8a35-0c2ea1380900');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ec49078b-9f9e-4ed1-97bf-101a7ab501f5', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'Who came running out of the dark woods towards the King and the Hermit with hands pressed against his bleeding stomach?', 'A bearded wounded man ran out of the forest, fainting and bleeding profusely from a severe abdominal wound.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('240c350d-30e5-4959-8b0f-03a71b903049', 'A bearded man who was severely wounded by the King''s royal bodyguards', true, 'ec49078b-9f9e-4ed1-97bf-101a7ab501f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbbb35c8-11f2-4500-b247-58bf54932a51', 'A wild forest tiger', false, 'ec49078b-9f9e-4ed1-97bf-101a7ab501f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fec46254-70cc-40f7-b394-630b7df5b04c', 'A messenger from the palace', false, 'ec49078b-9f9e-4ed1-97bf-101a7ab501f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af206d58-5133-4425-a8ea-e628e74ef1ac', 'A robber looking for gold', false, 'ec49078b-9f9e-4ed1-97bf-101a7ab501f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7cfb3c81-ac63-4957-b24a-05cd3878e716', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'How did the King save the life of the bleeding bearded man?', 'The king washed and repeatedly redressed the severe wound with his handkerchief, nursing the man back to life.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fb2889e-04f9-4dc3-8957-953250c26b62', 'The King washed the wound repeatedly, bandaged it with his clean handkerchief and the hermit''s towel until the bleeding stopped, and gave him fresh water to drink', true, '7cfb3c81-ac63-4957-b24a-05cd3878e716');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c43255a-399d-4d65-83dc-25283d6d0656', 'He called a helicopter', false, '7cfb3c81-ac63-4957-b24a-05cd3878e716');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1122ce3d-90a9-4b65-b8be-90a21d2a344a', 'He put the man in prison', false, '7cfb3c81-ac63-4957-b24a-05cd3878e716');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03ad41b7-9e53-40be-afe0-92b04bd77ce3', 'He ran away into the forest', false, '7cfb3c81-ac63-4957-b24a-05cd3878e716');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55f45053-a05f-4216-8c0b-05a36096b2c7', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'Why had the bearded man originally hidden in the woods to ambush and kill the King?', 'The bearded man sought blood revenge because the king had put his brother to death and seized his estate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d48ce21-5d0c-4f17-9cad-10d257b5c8bb', 'Because the King had earlier executed the man''s brother and confiscated all his family property', true, '55f45053-a05f-4216-8c0b-05a36096b2c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01ef1f71-2d40-4845-9f42-ccc1cded516c', 'Because he wanted to steal the King''s crown', false, '55f45053-a05f-4216-8c0b-05a36096b2c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f2f6939-8e1a-407b-bb1f-e3c34e33a69c', 'Because the King owed him money', false, '55f45053-a05f-4216-8c0b-05a36096b2c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1aa48cb8-bbcb-4e1e-a589-6689371ade90', 'Because he was a spy for another kingdom', false, '55f45053-a05f-4216-8c0b-05a36096b2c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41048990-5b29-4b34-b86e-1ed9cf819f2e', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'According to the wise Hermit, what is the SINGLE MOST IMPORTANT TIME in life?', 'The hermit revealed: ''The most important time is NOW, because it is the only time we have any power''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddc6093a-0eff-4dec-8779-a07c03ffb963', '''NOW'' (The Present Moment) — because it is the only time over which we possess any real power to act', true, '41048990-5b29-4b34-b86e-1ed9cf819f2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77ccd713-33ee-4bcd-bb59-4ccd5118cb75', 'Yesterday', false, '41048990-5b29-4b34-b86e-1ed9cf819f2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e89c2cc1-9cc1-4098-90d4-4afbd052dbd6', 'Tomorrow', false, '41048990-5b29-4b34-b86e-1ed9cf819f2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1689c71-3e7d-4c22-b824-f95dcb7c15b3', 'Next year', false, '41048990-5b29-4b34-b86e-1ed9cf819f2e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('756f34bb-ff92-484e-b1a9-032032df2402', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'According to the Hermit, who is the MOST IMPORTANT PERSON to a human being?', 'The most necessary person is the one with whom you are in the immediate present moment.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bc8c4c9-9567-475b-863e-b819b13634b0', 'The person you are with at any given present moment (as no one knows if you will ever have dealings with anyone else)', true, '756f34bb-ff92-484e-b1a9-032032df2402');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('978050f7-78ba-4e1c-bbc4-35a1ec5cd8b1', 'The King or Queen', false, '756f34bb-ff92-484e-b1a9-032032df2402');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27508566-4f1e-4ca3-bfef-85c29d0bb9e0', 'The richest merchant', false, '756f34bb-ff92-484e-b1a9-032032df2402');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('004424d3-2f7d-4cc3-9ec8-152bb918c336', 'A distant celebrity', false, '756f34bb-ff92-484e-b1a9-032032df2402');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4d9ce01-c93c-4ef1-b22a-70610e243f68', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'According to the Hermit, what is the MOST IMPORTANT BUSINESS/AFFAIR in human life?', 'The ultimate human mission is to do good to others: ''for that purpose alone was man sent into this life''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96351ef9-e87c-4511-9408-d25fb80622e6', 'To do good to the person you are with (for that divine purpose alone were humans sent into this world)', true, 'e4d9ce01-c93c-4ef1-b22a-70610e243f68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d9963ef-f1e2-4c06-b770-5f2f934ee954', 'To amass gold and treasure', false, 'e4d9ce01-c93c-4ef1-b22a-70610e243f68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f426710-444f-4eec-a99f-3906612cd4be', 'To conquer new lands', false, 'e4d9ce01-c93c-4ef1-b22a-70610e243f68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3c86140-32f4-4c42-844d-7fdf04f2239b', 'To become famous and feared', false, 'e4d9ce01-c93c-4ef1-b22a-70610e243f68');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2f4d09f-4bc0-47bf-93a6-e2615e083f20', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'In Mildred Bowers Armstrong''s delightful poem ''The Squirrel'', what did the playful squirrel wear for a tail?', 'Armstrong''s opening line paints an iconic visual metaphor: ''He wore a question mark for tail''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('623f11b3-79de-4041-a939-9338337cc552', 'A Question Mark (?) for a tail', true, 'b2f4d09f-4bc0-47bf-93a6-e2615e083f20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36957cf7-ff7b-4e96-b847-fc0fb2bfd4b6', 'An exclamation mark', false, 'b2f4d09f-4bc0-47bf-93a6-e2615e083f20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4243b623-db7d-40b1-8974-f95e2c796670', 'A straight sword', false, 'b2f4d09f-4bc0-47bf-93a6-e2615e083f20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('345fd1d9-07e7-4c63-892c-725fe30c9ff1', 'A bushy broom', false, 'b2f4d09f-4bc0-47bf-93a6-e2615e083f20');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf410ada-1924-4a63-bf2a-d2fd161453c2', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Easy', 'In the poem ''The Squirrel'', what color ''overcoat'' did the squirrel wear, and what food did he sit straight up to eat?', 'Armstrong describes the squirrel''s natural fur: ''An overcoat of gray / He sat up straight to eat a nut''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b47c0650-dab8-4bf6-99e0-88570f5178c6', 'An overcoat of Gray ; sitting up straight to eat a Nut', true, 'cf410ada-1924-4a63-bf2a-d2fd161453c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0591b09a-e59c-4325-b714-2480fcfd0465', 'An overcoat of Green ; eating an Apple', false, 'cf410ada-1924-4a63-bf2a-d2fd161453c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56623788-8956-4d67-a7e6-b1c7b8fbb42c', 'An overcoat of Black ; eating a Fish', false, 'cf410ada-1924-4a63-bf2a-d2fd161453c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f5c3ffc-4d7f-4901-9f25-cefc45f5cea3', 'An overcoat of Red ; eating Berries', false, 'cf410ada-1924-4a63-bf2a-d2fd161453c2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3440021-96b6-44b2-90cb-ae23f95ca446', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'What dramatic moral transformation occurs between the King and his bitter enemy in ''Three Questions''?', 'Compassion and mercy transformed a bloodthirsty avenger into a lifelong loyal friend and ally.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eaca0a94-6557-4c02-9bfb-582dda4eae0a', 'The wounded enemy asked for forgiveness, pledged eternal loyal service, and the King warmly forgave him, promised to restore his confiscated property, and sent his royal doctor to care for him (Enemy turned into devoted friend through compassion)', true, 'f3440021-96b6-44b2-90cb-ae23f95ca446');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af8062db-ba2c-41d3-b61f-e7b6c14fdb12', 'The King executed the enemy in the forest', false, 'f3440021-96b6-44b2-90cb-ae23f95ca446');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2f45ad4-a926-48d1-9a25-2dc307c13c80', 'The enemy escaped and attacked the palace', false, 'f3440021-96b6-44b2-90cb-ae23f95ca446');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d256c95-3bb2-4a13-ab98-4b1e6aa8a4a2', 'The hermit asked for money from both', false, 'f3440021-96b6-44b2-90cb-ae23f95ca446');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b0009b5-f837-40cf-a58c-bda0d74325e7', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'How did the Hermit prove to the King that his three questions had ALREADY been answered through living experience?', 'Tolstoy demonstrates that wisdom is experiential: lived compassionate action in the present moment provides its own truth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3b5fbea-624f-42f1-8fe0-dbe21aee3b5e', 'If the King had not pitied the Hermit and dug the beds, he would have been killed by the ambush; and if he had not bandaged the wounded man, the man would have died without making peace', true, '0b0009b5-f837-40cf-a58c-bda0d74325e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86b5ed01-3aa9-4265-8ced-b27dadd9c292', 'The Hermit gave him a written parchment', false, '0b0009b5-f837-40cf-a58c-bda0d74325e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d40074f-a422-40b6-89b3-2616750e329d', 'The Hermit cast a magic spell', false, '0b0009b5-f837-40cf-a58c-bda0d74325e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('925dac7d-de97-4172-934f-fc7a690bb8c0', 'The Hermit sent him to another kingdom', false, '0b0009b5-f837-40cf-a58c-bda0d74325e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d1c849f9-2ca6-4151-8de0-9ddc7c0353ed', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'In the poem ''The Squirrel'', what playful game does the squirrel play when children run around his tree?', 'Armstrong captures the skittish, playful evasive antics of squirrels: darting to the opposite side of tree trunks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c0c7b59-a349-4ca9-bddd-38d2cf032973', '"He liked to tease and play, / And if we ran around his tree, / He went the other way."', true, 'd1c849f9-2ca6-4151-8de0-9ddc7c0353ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2821d6b6-1d67-4b5c-9c52-ecc034e2cafe', 'He throws nuts at the children', false, 'd1c849f9-2ca6-4151-8de0-9ddc7c0353ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f08cceed-7ef9-4f4a-bb94-23514513bd96', 'He jumps into their hands', false, 'd1c849f9-2ca6-4151-8de0-9ddc7c0353ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('270eee8d-2e47-47fe-b224-0e63bf56bb19', 'He flies into the sky', false, 'd1c849f9-2ca6-4151-8de0-9ddc7c0353ed');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d957dec9-dfa2-44d6-8d8c-893d5b6d7870', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'What is the SYNONYM for the word ''Council'' as used in ''Three Questions'' (''a council of wise men'')?', '''Council'' (noun) denotes an advisory assembly; distinct from ''counsel'' (verb/noun for advice).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7dba1b1-cd8c-48f1-8a23-b88b59ca8ad5', 'A body of advisors / committee of experts', true, 'd957dec9-dfa2-44d6-8d8c-893d5b6d7870');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4e5e8ea-681e-4b59-94d4-c003baebc3ca', 'To give advice to someone', false, 'd957dec9-dfa2-44d6-8d8c-893d5b6d7870');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('281959b0-dc19-4482-863e-42e7879d9118', 'A battlefield', false, 'd957dec9-dfa2-44d6-8d8c-893d5b6d7870');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21c8fe3c-fd05-43c1-beb8-77ad301cfd65', 'A royal palace', false, 'd957dec9-dfa2-44d6-8d8c-893d5b6d7870');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9bd3940d-8d8a-431b-ba1b-ed3397d9a66f', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'What is the meaning of the word ''Fainted'' in: ''The bearded man reached the king and fainted.''?', '''Fainted'' (syncope) signifies transient loss of consciousness caused by hypovolemia or trauma.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e022839-56c3-4134-a131-27fe9a9b1b20', 'Lost consciousness temporarily due to weakness or loss of blood', true, '9bd3940d-8d8a-431b-ba1b-ed3397d9a66f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de515a46-a7df-4f6d-8976-a0dfd8338bfb', 'Started shouting loudly', false, '9bd3940d-8d8a-431b-ba1b-ed3397d9a66f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e4ffe60-22d2-42fb-8391-ab024fbaeefe', 'Turned into a ghost', false, '9bd3940d-8d8a-431b-ba1b-ed3397d9a66f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e9b4fa2-d4ad-4bff-8ff5-4cd46d00deee', 'Fell asleep happily', false, '9bd3940d-8d8a-431b-ba1b-ed3397d9a66f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f0844952-2b25-4ae4-bed1-1e5bfdc33e0f', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'Identify the part of speech of the underlined word in: ''He lived in a wood which he **never** quitted.''', '''Never'' is an Adverb of Frequency specifying the temporal negation of the verb ''quitted''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcb375e8-d534-42cf-a8fd-d62a16631c30', 'Adverb of Frequency (modifying the verb ''quitted'')', true, 'f0844952-2b25-4ae4-bed1-1e5bfdc33e0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92b34c9d-d369-4668-8c99-a5215db1d2b9', 'Adjective', false, 'f0844952-2b25-4ae4-bed1-1e5bfdc33e0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83060aa1-46c8-4f24-9a4c-89b3370311ff', 'Preposition', false, 'f0844952-2b25-4ae4-bed1-1e5bfdc33e0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6087df79-182a-4e68-ae16-5671cf823e11', 'Conjunction', false, 'f0844952-2b25-4ae4-bed1-1e5bfdc33e0f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1f0beb3c-e429-4f86-a429-04180889c248', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'Combine the two sentences using a RELATIVE PRONOUN:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bfe35f1-ee3c-4b81-8bed-af16f12ea059', '''I saw a hermit who was digging the ground.''', true, '1f0beb3c-e429-4f86-a429-04180889c248');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59d6bd31-60a6-4986-a2ef-8ec7a9b34d90', '''I saw a hermit which was digging the ground.''', false, '1f0beb3c-e429-4f86-a429-04180889c248');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9aa1bd3-3170-4400-9728-03789cd46d4d', '''I saw a hermit whose was digging the ground.''', false, '1f0beb3c-e429-4f86-a429-04180889c248');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19c48c76-ac5b-422e-82ca-55f7420f6fb9', '''I saw a hermit where was digging the ground.''', false, '1f0beb3c-e429-4f86-a429-04180889c248');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b7c6f78-57c5-4b0f-a6a0-43b15144c3d3', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'What is the ANTONYM of ''Forgive''?', 'The opposite of ''forgive'' (granting pardon) is ''punish'' or ''condemn''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afc01df6-1869-44c4-b8ef-1bead8737999', 'Punish / Blame / Condemn', true, '1b7c6f78-57c5-4b0f-a6a0-43b15144c3d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb5cad45-fd7b-4620-8581-706797111e10', 'Pardon', false, '1b7c6f78-57c5-4b0f-a6a0-43b15144c3d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b23a37ca-e40f-4865-abec-ddb07bd607ea', 'Absolve', false, '1b7c6f78-57c5-4b0f-a6a0-43b15144c3d3');
