INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ffe895ac-98f1-4118-b7ce-fbbf1782c624', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'Choose the correct abstract noun formed from the adjective ''Wise'':', 'The abstract noun derived from the root adjective ''wise'' is ''wisdom''.', NOW()) ON CONFLICT DO NOTHING;
