INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('495f262b-f8bd-466b-98ad-a52e96c5b679', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'What figure of speech is used in the poetic line: ''He wore a question mark for tail''?', 'Equating the tail directly to a question mark without ''like'' or ''as'' is an imaginative Metaphor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('813abf77-6704-4ea5-a0aa-92138cfb5111', 'Metaphor (imaginatively describing the curved shape of the squirrel''s tail as a punctuation question mark)', true, '495f262b-f8bd-466b-98ad-a52e96c5b679');
