INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('500c132d-5557-4c24-b329-578c2eef9ebe', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'What does the phrasal verb ''To take pity on'' mean in the sentence: ''The king took pity on the old hermit.''?', '''To take pity on'' denotes feeling genuine compassionate concern prompting benevolent action.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f8222f6-156f-43b4-a803-f44e8ee63933', 'To feel deep compassion and sympathy for someone''s suffering', true, '500c132d-5557-4c24-b329-578c2eef9ebe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25075dfe-c471-468b-bce8-9adbe93b1904', 'To laugh at someone', false, '500c132d-5557-4c24-b329-578c2eef9ebe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d668f761-5275-4a95-a7f8-3035970fab95', 'To give someone an exam', false, '500c132d-5557-4c24-b329-578c2eef9ebe');
