INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a4d7c716-4f7e-4ccf-9e54-823dbf677cc1', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'Convert into Indirect Speech:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c49f30e-812b-42db-a3db-bbdfad93a036', 'The hermit told the king that he had already been answered.', true, 'a4d7c716-4f7e-4ccf-9e54-823dbf677cc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2589d691-ec7e-423a-9828-1e3d22eac15a', 'The hermit said to the king that you are already answered.', false, 'a4d7c716-4f7e-4ccf-9e54-823dbf677cc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9a933b8-7919-4c1e-a968-1c38ce59037e', 'The hermit asked the king if he was answered.', false, 'a4d7c716-4f7e-4ccf-9e54-823dbf677cc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3217667e-6f02-4929-a37d-59364b1dafb7', 'The hermit said the king that you had been answered.', false, 'a4d7c716-4f7e-4ccf-9e54-823dbf677cc1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4168e0e1-1e28-4fae-8ea6-6f966cedb698', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'What is the meaning of the word ''Beds'' in the agricultural context of ''Three Questions'' (''The king had dug two beds'')?', 'In gardening/horticulture, ''beds'' are demarcated tilled soil plots cultivated for sowing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d61febe5-1256-484c-afc0-a270f3f15c8c', 'Small rectangular patches of dug soil prepared for planting seeds and flowers', true, '4168e0e1-1e28-4fae-8ea6-6f966cedb698');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd902c81-6f06-40cd-b435-965b0a95b3bd', 'Furniture with mattresses for sleeping', false, '4168e0e1-1e28-4fae-8ea6-6f966cedb698');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc063f16-bb6d-42b4-a7f1-8f26ecd2c2ef', 'River floors', false, '4168e0e1-1e28-4fae-8ea6-6f966cedb698');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d3afce9-f4ec-4e42-9504-f8d85f8711e1', 'Wooden boxes', false, '4168e0e1-1e28-4fae-8ea6-6f966cedb698');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a6b4cad2-f4ca-4977-9392-4bfa77606ed2', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Medium', 'Choose the correct sentence with proper Subject-Verb Agreement:', 'In ''Neither... nor'' constructions, the finite verb agrees with the proximate plural subject (''ministers were'').', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5afcc93-6b9c-4d57-a156-bc0c07aa4012', '''Neither the king nor his ministers were able to find universal agreement.''', true, 'a6b4cad2-f4ca-4977-9392-4bfa77606ed2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c39fa12c-3305-4edb-8b48-fc0141606550', '''Neither the king nor his ministers was able to find universal agreement.''', false, 'a6b4cad2-f4ca-4977-9392-4bfa77606ed2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ee9f0bc-d212-4615-9d94-b1dd3f04293b', '''The king with his ministers were digging.''', false, 'a6b4cad2-f4ca-4977-9392-4bfa77606ed2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcdae05f-ecfc-4009-b2dc-d50ab7edeb12', '''Everyone of the wise men have different answers.''', false, 'a6b4cad2-f4ca-4977-9392-4bfa77606ed2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('070735cb-9ff1-4270-97e6-e28802914e68', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c393cfa-9740-40c6-805b-5a3e2caf48c0', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '070735cb-9ff1-4270-97e6-e28802914e68');
