INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d259cf54-e68c-4e4e-ac4e-e0a7d918b5e9', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'Spot the IMPOSTER in the following group of philosophical conclusions derived from ''Three Questions'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0a4046d-7e12-4319-b698-ca178c17ae37', 'Conclusion 1', false, 'd259cf54-e68c-4e4e-ac4e-e0a7d918b5e9');
