INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f59b0897-a438-42fb-add1-3fa7857ee814', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'Analyze the subtle irony in the arrival of the bearded wounded man in ''Three Questions'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb43ae9c-1a67-4f29-8d80-68dd376378c0', 'The man who came with the intent to murder the King had his own life saved by that very King, converting mortal hatred into eternal loyalty', true, 'f59b0897-a438-42fb-add1-3fa7857ee814');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00dfa0b3-bd74-4d8e-921f-c172ff793359', 'The King ran away from the wounded man', false, 'f59b0897-a438-42fb-add1-3fa7857ee814');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39d3e531-571d-4142-930e-0d5035618fef', 'The Hermit turned out to be the man''s brother', false, 'f59b0897-a438-42fb-add1-3fa7857ee814');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8ef58e3-253e-43d7-9688-68564903886e', 'The King discovered the man was a ghost', false, 'f59b0897-a438-42fb-add1-3fa7857ee814');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66a10e1d-f717-45b6-9ee2-2bcadce28647', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'Match Column I (Literary Character / Element) with Column II (Symbolic Representation in ''Three Questions''):
(a) The King     -> (i) The restless searcher for intellectual certainty
(b) The Hermit   -> (ii) Grounded spiritual wisdom living in harmony with nature
(c) The Spade    -> (iii) Humble, selfless labor in service of others
(d) The Bandage  -> (iv) Healing compassion that dissolves historical enmity', 'King = searcher; Hermit = wisdom; Spade = humble labor; Bandage = healing compassion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e83ff16-c88a-4bc5-a6b6-36200500b162', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '66a10e1d-f717-45b6-9ee2-2bcadce28647');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edeac3f7-3c66-484d-9502-a132baa78ae0', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '66a10e1d-f717-45b6-9ee2-2bcadce28647');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb6a41d8-be3e-466a-928f-3f8e59ddc8d8', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '66a10e1d-f717-45b6-9ee2-2bcadce28647');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b56d32f1-3fbe-4f72-b327-1c8d65548625', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '66a10e1d-f717-45b6-9ee2-2bcadce28647');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a451b58-4c41-442d-96a1-54f06aa97105', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'Read the statements regarding Mildred Bowers Armstrong''s poem ''The Squirrel'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('990d124a-6aa6-4e32-abd8-c7b22a5ff184', 'Statements 1 and 2 only', true, '1a451b58-4c41-442d-96a1-54f06aa97105');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('618d5a06-b510-4845-ad82-d60c0546b887', 'Statements 2 and 3 only', false, '1a451b58-4c41-442d-96a1-54f06aa97105');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d347c9e-e584-4a74-8b4f-f6ef286020d8', 'Statements 1 and 3 only', false, '1a451b58-4c41-442d-96a1-54f06aa97105');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('105e00ee-75b6-4c8d-884f-bb9d5ece34b8', 'All Statements 1, 2, and 3', false, '1a451b58-4c41-442d-96a1-54f06aa97105');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11284227-a794-42cd-9d5a-1c533013d247', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'Identify the grammatical role of the underlined words in: ''The king was **greatly pleased** to have made peace with his enemy so easily.''', '''Greatly'' intensifies the participial adjective predicate ''pleased'', functioning as an Adverb of Degree.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('861a3e2b-7c9a-49bb-a84f-665a2e31fd16', '''Greatly'' is an Adverb of Degree modifying the participial adjective ''pleased''', true, '11284227-a794-42cd-9d5a-1c533013d247');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47aad728-7455-4392-8cbc-da46511565a3', '''Greatly'' is a Noun', false, '11284227-a794-42cd-9d5a-1c533013d247');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84037d15-58a9-4337-bf56-371729a91562', '''Pleased'' is a Preposition', false, '11284227-a794-42cd-9d5a-1c533013d247');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c93ee9b-2bf1-4f88-870f-67d80f2ab550', '''Greatly'' is a Conjunction', false, '11284227-a794-42cd-9d5a-1c533013d247');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eeec0281-b168-4377-be9f-81b91b44ffff', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'Which of the following sentences correctly utilizes a CONDITIONAL CLAUSE (Type 3 / Unfulfilled Past Condition) matching the Hermit''s dialogue?', 'Third conditional structure: If + past perfect (had not pitied/dug) ... would have + past participle (would have been attacked).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d4dbd09-7ea6-4aa2-87cb-389eda1749d3', '''If you had not pitied my weakness yesterday and had not dug these beds, you would have been attacked by that man.''', true, 'eeec0281-b168-4377-be9f-81b91b44ffff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b873f766-a815-456d-ba80-092b35689495', '''If you do not dig beds, you will be attacked.''', false, 'eeec0281-b168-4377-be9f-81b91b44ffff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0dfb915-d8c1-49d4-b46f-2aea290948cb', '''If you dig beds, you are attacked.''', false, 'eeec0281-b168-4377-be9f-81b91b44ffff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee91d361-923f-49eb-b49c-4d234a703439', '''If you would dig beds, you had been attacked.''', false, 'eeec0281-b168-4377-be9f-81b91b44ffff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a5eb031-2074-413d-a11f-cea21ad67a7d', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'What is the tone and poetic meter of Mildred Bowers Armstrong''s ''The Squirrel''?', 'Armstrong''s tone is whimsical, playful, and delighted by nature''s miniature vivacity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58dbb90a-08d0-4b56-8ee4-909d3fb04c56', 'Playful, affectionate, and lighthearted with rhythmic rhyming couplets capturing lively kinetic movement', true, '1a5eb031-2074-413d-a11f-cea21ad67a7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40f6e419-5dac-47e5-8b12-f5c3ac4af52d', 'Somber, tragic, and mournful', false, '1a5eb031-2074-413d-a11f-cea21ad67a7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb4a8480-6d07-4429-924f-1956456446c9', 'Fierce, aggressive, and war-like', false, '1a5eb031-2074-413d-a11f-cea21ad67a7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4191abed-be4f-4e60-9b16-ee382bdce2b3', 'Scientific and analytical without emotion', false, '1a5eb031-2074-413d-a11f-cea21ad67a7d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('42dfebbc-fbd9-4be2-86e5-e1eebb54bad2', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'Select the sentence that contains a TRANSITIVE verb with both a DIRECT and an INDIRECT object:', 'Ditransitive syntax: Verb (gave) + Indirect Object (the wounded man) + Direct Object (a cup of fresh water).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0edda03-5113-44ad-910b-13df1fdc7d8c', '''The King gave the exhausted wounded man a cup of fresh water.'' (''the wounded man'' = indirect object ; ''a cup of fresh water'' = direct object)', true, '42dfebbc-fbd9-4be2-86e5-e1eebb54bad2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e49bd09-bbf8-446a-8e01-5d0265dc57d5', '''The squirrel ran up the tall tree.''', false, '42dfebbc-fbd9-4be2-86e5-e1eebb54bad2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b66b95f0-130d-4029-9ace-568278fc918e', '''The hermit was digging in the garden.''', false, '42dfebbc-fbd9-4be2-86e5-e1eebb54bad2');
