INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a62ae963-1da9-4d7e-85e9-2f624b3fefcf', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'What is the meaning of the archaic/literary term ''Quitted'' in ''He lived in a wood which he never quitted''?', 'Literary verb ''quit'' (past: quitted/quit) signifies to depart from or leave a location.', NOW()) ON CONFLICT DO NOTHING;
