INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91caf08f-9c0b-4241-a113-38aafc3e9a8d', '''On seeing the hermit, the King greeted him respectfully.''', true, '970d0462-d7ef-43ab-9242-9ff91cd17ae0');
