INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6f829cd-a04f-4471-a52b-075378915131', '''The King saw the hermit because he greeted him.''', false, '970d0462-d7ef-43ab-9242-9ff91cd17ae0');
