INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e50f331-f9f8-42cd-8735-af5c6a0ff82d', 'Class 7', 'English', 'Chapter 1: Three Questions & The Squirrel', 'Hard', 'What enduring message does the opening chapter of NCERT Class 7 English impart to young learners?', 'Chapter 1 harmonizes philosophical mindfulness (Tolstoy) with affectionate ecological wonder (Armstrong).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8bf1464-9f7f-4f32-a10d-55021f306436', 'True wisdom is not found in abstract academic speculation, but in practical mindfulness, living fully in the present moment, practicing unconditional kindness, and finding joy in the gentle creatures of nature', true, '6e50f331-f9f8-42cd-8735-af5c6a0ff82d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7eec023-d82c-4140-88d1-96827016640d', 'That questions in life can never be answered', false, '6e50f331-f9f8-42cd-8735-af5c6a0ff82d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1327913-91c0-4b1d-9068-f313d9ab6f0d', 'That rulers should never listen to common people', false, '6e50f331-f9f8-42cd-8735-af5c6a0ff82d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc3ca307-aae1-455d-8b7b-8521fa4e2c8a', 'That wild animals should be captured for research', false, '6e50f331-f9f8-42cd-8735-af5c6a0ff82d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('316c7eb4-0564-41df-80aa-bb3ced373130', 'Class 7', 'GK', 'Chapter 1: Our India - Heritage, Symbols, Polity & Geography', 'Easy', 'What is the National Emblem of the Republic of India adopted from on 26th January 1950?', 'India''s State Emblem is adapted from the Mauryan Lion Capital of Ashoka at Sarnath (250 BCE).', NOW()) ON CONFLICT DO NOTHING;
