INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9004fda9-9a1d-47a5-9ed2-826cc8b6f743', 'Class 7', 'GK', 'Chapter 1: Our India - Heritage, Symbols, Polity & Geography', 'Hard', 'How many languages are officially recognized as ''Classical Languages of India'' by the Government of India (with ancient antiquity, original literary tradition, and high cultural prestige)?', 'The Government expanded the Classical Languages list in 2024 to include Marathi, Pali, Prakrit, Assamese, and Bengali alongside the foundational six.', NOW()) ON CONFLICT DO NOTHING;
