INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea37bb86-fdc2-469b-912b-3ec1eaa5faaf', 'Class 7', 'GK', 'Chapter 1: Our India - Heritage, Symbols, Polity & Geography', 'Hard', 'Match Column I (Geographical Features of India) with Column II (Exact Locations / Superlatives):
(a) Wettest place on Earth (highest annual rainfall) -> (i) Mawsynram (Meghalaya)
(b) Only active volcano in South Asia                 -> (ii) Barren Island (Andaman)
(c) Largest freshwater lake in India                   -> (iii) Wular Lake (Jammu & Kashmir)
(d) Cold Desert biosphere reserve                     -> (iv) Spiti / Ladakh', 'Mawsynram = wettest (11,872 mm); Barren Island = volcano; Wular = largest freshwater lake; Spiti/Ladakh = cold desert.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e731acc-9b99-4796-ae6a-78a993b88b42', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'ea37bb86-fdc2-469b-912b-3ec1eaa5faaf');
