INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7bc952e4-417f-4e77-93d4-60b0b5f919c5', 'Class 7', 'GK', 'Chapter 1: Our India - Heritage, Symbols, Polity & Geography', 'Hard', 'Which unique festival celebrated at Haridwar, Prayagraj, Ujjain, and Nashik was inscribed on UNESCO''s Intangible Cultural Heritage of Humanity list as the world''s largest peaceful pilgrimage gathering?', 'Kumbh Mela rotates every 12 years across 4 river sacred sites, gathering tens of millions of pilgrims.', NOW()) ON CONFLICT DO NOTHING;
