INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c85d5bae-d23c-434b-a083-ec82fb6a8511', 'Class 7', 'GK', 'Chapter 1: Our India - Heritage, Symbols, Polity & Geography', 'Hard', 'What is the highest civilian award of the Republic of India, instituted on 2nd January 1954?', 'Bharat Ratna (peepal leaf shaped medallion in platinum) is India''s highest civilian honor for exceptional service.', NOW()) ON CONFLICT DO NOTHING;
