INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a069f638-0266-4270-8882-9f34fc9bccc7', 'Class 7', 'GK', 'Chapter 1: Our India - Heritage, Symbols, Polity & Geography', 'Hard', 'What is India''s highest military decoration awarded for highest degree of valor in the presence of the enemy in wartime?', 'Param Vir Chakra is India''s pre-eminent wartime military honor (first awarded to Major Somnath Sharma in 1947).', NOW()) ON CONFLICT DO NOTHING;
