INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa0617c6-6391-4c64-8ddd-bdd8e15868f0', 'Class 7', 'GK', 'Chapter 1: Our India - Heritage, Symbols, Polity & Geography', 'Hard', 'What profound civilizational reality makes India celebrated as the world''s most vibrant ''Unity in Diversity''?', 'India''s civilizational ethos harmonizes multi-ethnic, multi-lingual, and multi-faith diversity into an indivisible constitutional republic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4610366b-1483-421c-a921-014a2c89f43a', 'The harmonious synthesis of thousands of dialects, ancient classical traditions, multiple world religions, diverse biogeographical landscapes, and vibrant regional cultures unified under a secular democratic constitutional framework', true, 'fa0617c6-6391-4c64-8ddd-bdd8e15868f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed2f0690-9679-4367-b8df-f8b7c0f08383', 'A nation where everyone speaks only one language', false, 'fa0617c6-6391-4c64-8ddd-bdd8e15868f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c33080c0-5955-4d48-9cbc-bd8e4ea392d8', 'A country without any regional states', false, 'fa0617c6-6391-4c64-8ddd-bdd8e15868f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad6d1940-ea3c-4510-9bd2-faa24600117f', 'An isolated land with no external history', false, 'fa0617c6-6391-4c64-8ddd-bdd8e15868f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('44008026-bff2-4e16-8ccf-10ae6b502d68', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'A person who draws and creates geographical maps is professionally called a:', 'A cartographer is a specialist in the science and art of mapmaking and chart projection.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3caf6d6-ff26-456b-80ba-59ca06f13084', 'Cartographer', true, '44008026-bff2-4e16-8ccf-10ae6b502d68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c78cfc2-5952-4028-b51e-11f3451479a4', 'Calligrapher', false, '44008026-bff2-4e16-8ccf-10ae6b502d68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1feeb209-f6b3-4fc8-a7e3-b65abde7ef46', 'Scribe', false, '44008026-bff2-4e16-8ccf-10ae6b502d68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2812b2c2-28fb-49b6-9a97-c071300550f8', 'Archaeologist', false, '44008026-bff2-4e16-8ccf-10ae6b502d68');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1f416a97-44fc-4780-b800-ea41d0605717', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'How did the 12th-century Arab geographer Al-Idrisi (1154 CE) orient his famous map of the Indian subcontinent compared to modern maps?', 'Al-Idrisi''s 1154 CE Arabic map oriented South at the top, showing Sri Lanka at the upper summit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43fec1b7-ce08-4a0d-82a9-c0ec0ef6dd13', 'South India was shown at the TOP where North India is today, and Sri Lanka was shown as an island at the top', true, '1f416a97-44fc-4780-b800-ea41d0605717');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2229cd1-ed0c-48e5-8889-66d5d7369dac', 'He showed India upside down with Himalayas at the bottom', false, '1f416a97-44fc-4780-b800-ea41d0605717');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad268cd9-9627-46cf-ae58-46b9dd95606a', 'He showed only oceans without land', false, '1f416a97-44fc-4780-b800-ea41d0605717');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21138e91-2dc8-40ce-9c0c-d73978ee8423', 'His map was identical to Google Maps', false, '1f416a97-44fc-4780-b800-ea41d0605717');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('447aed60-15e1-4b50-b8d1-e2a9f35973b6', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'In the 13th century, what geographical area did the Persian chronicler Minhaj-i Siraj mean when he used the term ''Hindustan''?', 'Minhaj-i Siraj used ''Hindustan'' in a political sense to denote the Gangetic and Doab domains of the Delhi Sultanate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9e9d2ac-4734-45dd-8ccd-2b3b80d52d7b', 'The lands of Punjab, Haryana, and the fertile plains between the Ganga and Yamuna rivers ruled by the Delhi Sultan', true, '447aed60-15e1-4b50-b8d1-e2a9f35973b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f4ade78-dbf7-4097-93f8-5b2037d51cbf', 'The entire modern republic of India including south India', false, '447aed60-15e1-4b50-b8d1-e2a9f35973b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0be735aa-1e12-4bba-aa83-0b9529c7f99d', 'The continent of Asia', false, '447aed60-15e1-4b50-b8d1-e2a9f35973b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0730ed93-1cd9-4c4f-915d-98045cc93785', 'Only the island of Sri Lanka', false, '447aed60-15e1-4b50-b8d1-e2a9f35973b6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc3d9d42-2ad7-4346-bd0e-b21f0a9dbb5a', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'In the early 16th century, how did the Mughal Emperor Babur use the term ''Hindustan'' in his autobiography (Baburnama)?', 'Babur employed ''Hindustan'' in a biogeographical and cultural sense to describe the subcontinent''s fauna, flora, and customs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e42ff021-34b3-4716-a900-d30a502dd551', 'To describe the geography, the natural fauna, and the distinct cultural customs of the inhabitants of the subcontinent', true, 'fc3d9d42-2ad7-4346-bd0e-b21f0a9dbb5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca4830dc-232e-4a29-b86f-a2f23afd293b', 'As a political nation-state with a constitution', false, 'fc3d9d42-2ad7-4346-bd0e-b21f0a9dbb5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('517f022d-7834-490a-a5bb-2179d03fce1b', 'To describe only Afghanistan', false, 'fc3d9d42-2ad7-4346-bd0e-b21f0a9dbb5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba25d0ef-73de-4774-8890-9a03226a6038', 'To refer to the Roman Empire', false, 'fc3d9d42-2ad7-4346-bd0e-b21f0a9dbb5a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6daae3f-4403-496f-8463-2d65c7b593d7', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'In the medieval period, what did the term ''Foreigner'' (Pardesi in Hindi / Ajnabi in Persian) mean?', 'In medieval times, a ''foreigner'' (ajnabi/pardesi) was any outsider/stranger from another village, not necessarily from a foreign nation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('774268b1-2c14-4f2b-965e-87dbe8c518b8', 'Any stranger who appeared in a given village or town and was not a part of that local society or culture', true, 'c6daae3f-4403-496f-8463-2d65c7b593d7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33009ed3-659b-4421-be32-93312b0f6847', 'Only a person from another foreign country', false, 'c6daae3f-4403-496f-8463-2d65c7b593d7');
