INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5904046c-2638-4612-970a-f50047985e07', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'Before the invention of printing presses in India, who copied historical manuscripts by hand?', 'Scribes laboriously transcribed handwritten manuscript codices before the introduction of mechanical printing.', NOW()) ON CONFLICT DO NOTHING;
