INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75568130-bac8-41f4-ab50-33654aac92fd', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'What new group of warrior Kshatriya clans rose to great political and military prominence between the 8th and 14th centuries, derived from the Sanskrit term ''Rajaputra'' (son of a king)?', 'The term ''Rajput'' (from Rajaputra) designated martial warrior clans claiming Kshatriya lineage across northern and western India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6395957-2e1e-4a8b-b8fb-3b80b91c5ac9', 'Rajputs', true, '75568130-bac8-41f4-ab50-33654aac92fd');
