INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a366abf3-66f7-4592-9ec6-3bff5a6468d5', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'Which of the following new agricultural crops and beverages were introduced to the Indian subcontinent from the Americas and foreign trade during this thousand-year period?', 'The Columbian exchange and trade brought potatoes, maize, chillies, tomatoes, tobacco, tea, and coffee to India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ea00dfe-0333-4e9f-9751-b61017e41883', 'Potatoes, Corn (Maize), Chillies, Tea, and Coffee', true, 'a366abf3-66f7-4592-9ec6-3bff5a6468d5');
