INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68461c05-dc31-476f-aae9-c357ec8f6c82', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'What was a sub-caste or social ranking formed within the caste hierarchy based on occupation, family background, and social status called?', 'Jatis were occupational sub-castes ranked fluidly according to their local wealth, power, and ritual status.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55c44952-be76-4b6a-8464-41c811ae3a73', 'Jati', true, '68461c05-dc31-476f-aae9-c357ec8f6c82');
