INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('95da11bd-b4d4-40b4-b0f9-6424e8cf2530', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'Who framed the rules and regulations to manage the conduct of members within each Jati?', 'Jati Panchayats were self-regulating assemblies of caste elders enforcing community occupational and marital norms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc7b068e-6d2c-4d38-81c9-09c88b5c6c24', 'The Jati Panchayat (an assembly of village elders belonging to that specific jati)', true, '95da11bd-b4d4-40b4-b0f9-6424e8cf2530');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0257166d-ebda-4e01-b325-807d386beebb', 'The Mughal Emperor', false, '95da11bd-b4d4-40b4-b0f9-6424e8cf2530');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54252d94-71f6-43e4-85b1-9a36a43d3718', 'Foreign merchants', false, '95da11bd-b4d4-40b4-b0f9-6424e8cf2530');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c5697c0-6a7b-4fbb-ac3d-dbfbef502cfc', 'Roman senators', false, '95da11bd-b4d4-40b4-b0f9-6424e8cf2530');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a7ce9e0-e06b-4e75-a157-7638b5063f22', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Easy', 'What is the holy scripture of Islam that contains the divine revelations received by Prophet Muhammad?', 'The Holy Quran is the central sacred liturgical text of Islam revealed to Prophet Muhammad in Arabic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c5c7b6f-4ffc-41a5-aabb-1a9b6e124b1d', 'The Quran (Holy Quran)', true, '9a7ce9e0-e06b-4e75-a157-7638b5063f22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c930d3b7-4192-49bf-893f-e386ea6794b6', 'The Zend Avesta', false, '9a7ce9e0-e06b-4e75-a157-7638b5063f22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('674a99c2-fc7d-4027-89cf-79489435d7a2', 'The Tripitaka', false, '9a7ce9e0-e06b-4e75-a157-7638b5063f22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3775ef77-3938-4091-898c-c422accdd737', 'The Torah', false, '9a7ce9e0-e06b-4e75-a157-7638b5063f22');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('50ab6f16-a064-44f1-85cd-85e7aca711f5', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'Why do historians face enormous challenges and discrepancies when reading ancient handwritten manuscripts copied by scribes?', 'Manual transcription errors accumulated exponentially over generations of copyists, resulting in divergent recensions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73e4e578-bd2a-4ef5-aa99-bea5fb12e2ca', 'As scribes copied by hand, they frequently made unintentional copying errors, added small modifications, or substituted words, which compounded over centuries until different manuscript copies differed significantly from the author''s original text', true, '50ab6f16-a064-44f1-85cd-85e7aca711f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1168736-a6b2-468c-8125-37bda5df17fb', 'Because all scribes wrote in secret codes to trick historians', false, '50ab6f16-a064-44f1-85cd-85e7aca711f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bbeb8d6-2dd3-4347-b57d-0265b158ba87', 'Because paper was made of metal and faded', false, '50ab6f16-a064-44f1-85cd-85e7aca711f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dba0ae0d-f1d2-43e1-a22f-364681ce7c76', 'Because manuscripts were burned by kings', false, '50ab6f16-a064-44f1-85cd-85e7aca711f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b1d8c994-6320-44bb-96ee-29293a803f35', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'Who was the 14th-century chronicler Ziauddin Barani, and why did modern historians discover his first chronicle version only in the 1960s?', 'Ziauddin Barani''s 1356 CE recension of Tarikh-i Firuz Shahi was rediscovered in manuscript collections in the 1960s.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5c21bf2-8fc3-4e5d-b8da-a6b40a25cd02', 'Barani wrote his first chronicle in 1356 and a revised second version in 1358; the first version remained lost in vast library archives undiscovered until 1960', true, 'b1d8c994-6320-44bb-96ee-29293a803f35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba84d2f0-4c68-49d9-adb0-fbdc6f78a637', 'Because Barani hid his book inside a cave', false, 'b1d8c994-6320-44bb-96ee-29293a803f35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51ceb226-4e8e-4e3d-a208-b6afa644877e', 'Because his book was written in hieroglyphics', false, 'b1d8c994-6320-44bb-96ee-29293a803f35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71c94a2d-c252-4fb6-a18b-5550c014c038', 'Because Barani was a fictional character', false, 'b1d8c994-6320-44bb-96ee-29293a803f35');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13b96d86-da23-492f-8817-f65948335fce', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'What major technological innovations appeared in the Indian subcontinent between 700 and 1750 CE?', 'The medieval era witnessed crucial mechanical adoptions: saqia/Persian wheel, spinning wheel, and pyrotechnic firearms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2837093-ca1d-470a-89d0-0f45a70839dd', 'The Persian Wheel in irrigation, the Spinning Wheel (Charkha) in weaving, and Firearms (cannons & gunpowder) in combat warfare', true, '13b96d86-da23-492f-8817-f65948335fce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed60372c-16ee-41e2-b707-cb1626c7228d', 'Steam locomotives and telegraphs', false, '13b96d86-da23-492f-8817-f65948335fce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12d10a53-688f-4f10-89ec-0f62e4f73ebe', 'Computers and electricity', false, '13b96d86-da23-492f-8817-f65948335fce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('069dd577-4c30-44d7-beae-b23a17b361fc', 'Airplanes and submarines', false, '13b96d86-da23-492f-8817-f65948335fce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03574ec3-d7b8-4a9a-871a-dd3104fa8ba0', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'Why were many forest dwellers forced to migrate or become peasant farmers during the medieval thousand years?', 'Agricultural expansion and deforestation transformed tribal forest habitats, integrating tribals into peasant jati hierarchies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd6beafc-d37b-479d-a00f-8366eae20f3b', 'Extensive clearing of natural forests to expand agricultural arable land fundamentally changed forest habitats, pushing forest dwellers into agrarian village society', true, '03574ec3-d7b8-4a9a-871a-dd3104fa8ba0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36cc673a-5343-426d-9968-dfa7a43c288f', 'Because wild animals drove them out', false, '03574ec3-d7b8-4a9a-871a-dd3104fa8ba0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a91179d-ed5f-4676-bf02-60ba57f5a6e3', 'Because forests turned into deserts overnight', false, '03574ec3-d7b8-4a9a-871a-dd3104fa8ba0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ad8c80d-a92d-46dc-b154-daf7e44952c1', 'Because kings banned living near trees', false, '03574ec3-d7b8-4a9a-871a-dd3104fa8ba0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3e59e79-8bb0-484c-987b-39b40a657b6a', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'What is a ''Pan-Regional Empire'' in medieval Indian history?', 'Pan-regional polities integrated multiple diverse geographical sub-regions under an overarching imperial state apparatus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed6738c7-9ca0-4201-8a83-48e34563102d', 'An expansive empire spanning diverse geographic, linguistic, and cultural regions (such as the Cholas, Khaljis, Tughluqs, and Mughals)', true, 'f3e59e79-8bb0-484c-987b-39b40a657b6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a34cf70-8b7b-46fc-8f1c-8289cb401e4c', 'A small city-state ruling one town', false, 'f3e59e79-8bb0-484c-987b-39b40a657b6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e604394-5a8b-49b0-a732-fa839ec9abb7', 'A maritime empire in Europe', false, 'f3e59e79-8bb0-484c-987b-39b40a657b6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87bdd682-e09a-4371-a062-b5a1eb3041e8', 'An empire ruled by a single village council', false, 'f3e59e79-8bb0-484c-987b-39b40a657b6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22555e4d-5588-4c4d-bf3a-eb9c08e8e827', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'Who were the ''Ulama'' in medieval Islamic society?', 'The Ulama were authoritative theologians and jurists responsible for interpreting Islamic theology and Sharia law.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1d89ce0-3150-4c82-9be0-0f2c11a799db', 'Learned Muslim scholars, jurists, and theologians expert in Islamic sacred law (Sharia) and religious jurisprudence', true, '22555e4d-5588-4c4d-bf3a-eb9c08e8e827');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1164dd51-c4c0-42f5-84e3-0ed3c005376e', 'Foreign horse merchants', false, '22555e4d-5588-4c4d-bf3a-eb9c08e8e827');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd9b98d2-b61c-4ea0-a5ee-5cbf5716268e', 'Architects who built forts', false, '22555e4d-5588-4c4d-bf3a-eb9c08e8e827');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e6a96f7-ddd7-41a1-b795-2f2c09c1c41b', 'Musicians in royal courts', false, '22555e4d-5588-4c4d-bf3a-eb9c08e8e827');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a981e532-5bad-454d-9505-20dc573e868a', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'What was the fundamental theological difference between the SHIA and SUNNI traditions within Islam?', 'Schism: Sunnis recognized the historical succession of the Rashidun Caliphate; Shias recognized the hereditary leadership of Ali and Imams.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('344a5784-f914-4aae-bc37-fbea288b6a60', 'Shia Muslims believed that Prophet Muhammad''s son-in-law Ali was the legitimate leader (Imam) of the Muslim community ; Sunni Muslims accepted the authority of the early Caliphs (Khalifas)', true, 'a981e532-5bad-454d-9505-20dc573e868a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e60abf9e-2fc6-4007-98ca-4abb654c42e1', 'Shias worshipped fire while Sunnis worshipped water', false, 'a981e532-5bad-454d-9505-20dc573e868a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db70e21d-3580-4780-bbee-685e7a3477cd', 'Sunnis did not believe in the Quran', false, 'a981e532-5bad-454d-9505-20dc573e868a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05c9e764-77ed-4085-b9fb-78e04c4e58a3', 'Shias did not pray at all', false, 'a981e532-5bad-454d-9505-20dc573e868a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b8e99b3-4a3c-4a7b-9cd2-f47af6e50a5f', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'What were the two prominent schools of Islamic legal jurisprudence (Fiqh) influential in medieval India?', 'The Hanafi and Shafi''i madhhabs (schools of Islamic jurisprudence) were the primary legal traditions in the subcontinent.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0738293-d243-4070-812f-428ffd5eb24a', 'Hanafi and Shafi''i schools', true, '2b8e99b3-4a3c-4a7b-9cd2-f47af6e50a5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48fb9503-9132-428c-b651-54d490818642', 'Maliki and Hanbali only', false, '2b8e99b3-4a3c-4a7b-9cd2-f47af6e50a5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd99728b-cb44-4139-9123-a67a315d6893', 'Greek and Roman schools', false, '2b8e99b3-4a3c-4a7b-9cd2-f47af6e50a5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4c9ffdf-3825-4d22-a2a7-1d2120861977', 'Vedic and Buddhist schools', false, '2b8e99b3-4a3c-4a7b-9cd2-f47af6e50a5f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('48c1bb67-a387-41b6-8427-d28e0f05579b', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'Why was the 19th-century British historian James Mill''s tripartite division of Indian history into ''Hindu'', ''Muslim'', and ''British'' periods fundamentally flawed?', 'Mill''s communal periodization reduced complex multifaceted socio-economic and cultural histories to simplistic sectarian labels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38949394-a018-4935-b8f4-ead3b794458b', 'It characterized entire historical epochs solely by the personal religion of rulers, ignoring immense socio-economic diversity, scientific advances, and the diverse beliefs of ordinary people', true, '48c1bb67-a387-41b6-8427-d28e0f05579b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82f672e1-9f77-44fd-bc45-98d6a616e5f6', 'Because Mill was an Indian prince', false, '48c1bb67-a387-41b6-8427-d28e0f05579b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd5cad84-e701-41be-924b-04395730b349', 'Because there were no religions in India', false, '48c1bb67-a387-41b6-8427-d28e0f05579b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff7e0bff-d6e5-4933-b362-1ca1b9fa0740', 'Because British rule lasted 2,000 years', false, '48c1bb67-a387-41b6-8427-d28e0f05579b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5b009ffd-7037-4480-be0b-4e9c27ac1297', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'How do modern historians divide Indian history to reflect broader socio-economic, cultural, and technological transitions?', 'Historiographical periodization utilizes Ancient, Medieval (c. 700–1750 CE), and Modern frameworks reflecting structural socio-economic shifts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfa0e409-49cf-4304-987c-ccc89dcb0755', 'Ancient Period, Medieval Period, and Modern Period', true, '5b009ffd-7037-4480-be0b-4e9c27ac1297');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bd8139a-ab9e-4030-910d-8b83446f7646', 'Stone Age and Digital Age only', false, '5b009ffd-7037-4480-be0b-4e9c27ac1297');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c25edc75-a435-48f9-ad10-b7b50ab3396f', 'Kings Age and Queens Age', false, '5b009ffd-7037-4480-be0b-4e9c27ac1297');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e59ea61e-4ff5-420f-a10d-7d37de45e9c8', 'War Age and Peace Age', false, '5b009ffd-7037-4480-be0b-4e9c27ac1297');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed480d21-9bdb-48d2-a5b3-f9ec8c4e1993', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'What major transformation occurred in Hinduism during the medieval thousand years?', 'Medieval Hinduism saw temple-centered devotion, royal Brahmanical patronage, and popular personal Bhakti traditions without rigid rituals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54324cb2-df78-4bb9-a53f-921787e34238', 'The worship of new deities, the construction of massive royal stone temples, the growing social prestige and land grants (Brahmadeya) to Brahmanas, and the emergence of the Bhakti Movement', true, 'ed480d21-9bdb-48d2-a5b3-f9ec8c4e1993');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42c8251f-6353-4e7e-b3d9-48d62a6b96d9', 'The complete disappearance of all temples', false, 'ed480d21-9bdb-48d2-a5b3-f9ec8c4e1993');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f09afe2-cff9-40aa-a6db-2a6bb7c3759a', 'The ban on reading Sanskrit texts', false, 'ed480d21-9bdb-48d2-a5b3-f9ec8c4e1993');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7470d007-f447-490f-8eb2-4086cbd137e6', 'The replacement of all gods by Roman deities', false, 'ed480d21-9bdb-48d2-a5b3-f9ec8c4e1993');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6cae6630-a31a-48aa-97ef-cc26eca76c8b', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'What was the central liberating appeal of the ''Bhakti Movement'' to ordinary common people during the medieval era?', 'Bhakti democratized spirituality: direct, unmediated personal love (prema/bhakti) open to all genders and castes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2beedec-e6a8-4c87-9fe9-e36f66ae0de9', 'The idea of an intimate, personal, loving God whom devotees could reach directly with pure love without the mandatory mediation of wealthy priests or elaborate, costly sacrifices', true, '6cae6630-a31a-48aa-97ef-cc26eca76c8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff483bf0-29f4-4f31-8e80-ae09a9e12af4', 'Devotees had to give all their gold to kings', false, '6cae6630-a31a-48aa-97ef-cc26eca76c8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be9975d6-5713-42b7-a756-579f6fdfdc14', 'Devotees were forced to learn Greek', false, '6cae6630-a31a-48aa-97ef-cc26eca76c8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77b5125b-3421-47f9-90e9-570f08ce5458', 'Bhakti banned music and poetry', false, '6cae6630-a31a-48aa-97ef-cc26eca76c8b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('af957e1c-6c60-4fd0-98b3-fd8041a17ba9', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'What was the French cartographer Guillaume de L''Isle''s atlas map of India (1720s) famous for?', 'The 18th-century French atlas reflected advanced maritime surveying, exhibiting coastlines familiar to modern cartography.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed138d8a-07aa-42b8-b652-1c79a1c36f89', 'Remarkable scientific accuracy, modern orientation, and highly detailed coastal navigation geography used extensively by European maritime merchants', true, 'af957e1c-6c60-4fd0-98b3-fd8041a17ba9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a67a579-cd85-4ca0-ab9b-8f5a870b15d3', 'It showed South India at the top', false, 'af957e1c-6c60-4fd0-98b3-fd8041a17ba9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21514b3f-286c-4bf4-8135-b0b0691777e4', 'It omitted all Indian rivers', false, 'af957e1c-6c60-4fd0-98b3-fd8041a17ba9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('497b199a-a0f5-4923-b0d0-02a991e179b5', 'It had no place names', false, 'af957e1c-6c60-4fd0-98b3-fd8041a17ba9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ed793b2-0846-4239-8305-1f7e6eb4bd38', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'Who were the ''Kayasthas'' that gained prominent social and administrative status during this period?', 'Kayasthas emerged as an influential literate occupational community managing state archives, revenue ledgers, and scribal administration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40424840-b78c-490d-b79c-8d1681ddea18', 'A specialized caste of scribes, record-keepers, secretaries, and administrative accountants', true, '6ed793b2-0846-4239-8305-1f7e6eb4bd38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce0d5e68-0561-4513-a9bd-5241d4e7ac1f', 'Warrior cavalry officers', false, '6ed793b2-0846-4239-8305-1f7e6eb4bd38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88959717-fe29-4961-95f6-a5fea792ac49', 'Temple stone carvers', false, '6ed793b2-0846-4239-8305-1f7e6eb4bd38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3ca0df5-740f-4069-9d53-a0fe126299ec', 'Sea sailors', false, '6ed793b2-0846-4239-8305-1f7e6eb4bd38');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4dda3c90-0f28-411c-8ce6-f153a8525cb2', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'Why did the price of Paper fall and its availability increase dramatically during the 13th and 14th centuries in India?', 'Papermaking technology diffusion dramatically expanded codex production, record-keeping, and legal archiving.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3eec8640-1c7f-4c38-a58c-b114c9df57f5', 'Introduction of pulping watermills and spread of papermaking technology from China and the Islamic world led to widespread copying of religious, legal, and judicial texts', true, '4dda3c90-0f28-411c-8ce6-f153a8525cb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9a20f3a-31e8-415a-a4bb-d4613518ee37', 'Because trees were made of paper', false, '4dda3c90-0f28-411c-8ce6-f153a8525cb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0d73c54-d8a4-4b19-8906-03c008877c9d', 'Because kings banned writing on palm leaves', false, '4dda3c90-0f28-411c-8ce6-f153a8525cb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a416419c-4734-4c69-adc1-b2ba1a4cdb83', 'Because books were imported from America', false, '4dda3c90-0f28-411c-8ce6-f153a8525cb2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('067a2446-e9d6-4043-9c38-fe9cbaa1c7a8', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Medium', 'What were the two major styles of Persian and Arabic handwriting used by scribes in medieval India?', 'Nastaliq was fluid and legible for literary codices; Shikaste was dense and rapid for state administrative correspondence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08521630-8130-479a-a5ed-cdcecff8b9bd', 'Nastaliq (flowing, cursive, easy to read) and Shikaste (dense, cramped, rapid, and difficult to decipher)', true, '067a2446-e9d6-4043-9c38-fe9cbaa1c7a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d63f7cb1-9214-4b2e-8dac-d3c278a13bfa', 'Devanagari and Brahmi', false, '067a2446-e9d6-4043-9c38-fe9cbaa1c7a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d94c286-91b8-4ba9-9c49-6434598d6e68', 'Gothic and Latin', false, '067a2446-e9d6-4043-9c38-fe9cbaa1c7a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab0936f1-c9dc-4d5f-b38e-33c6289cd694', 'Cuneiform and Hieroglyphic', false, '067a2446-e9d6-4043-9c38-fe9cbaa1c7a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36812d50-d547-473d-b662-bc7391426327', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2b8b667-e88d-427c-8a18-9238ec59363d', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '36812d50-d547-473d-b662-bc7391426327');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a026236a-e60e-4ab1-83b2-c79db4e48388', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '36812d50-d547-473d-b662-bc7391426327');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0c10084-cf3f-4139-96fc-d3e00e2279b8', '(A) is true, but (R) is false.', false, '36812d50-d547-473d-b662-bc7391426327');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b29a4b92-a473-4f78-a7c1-ff473316e9c1', '(A) is false, but (R) is true.', false, '36812d50-d547-473d-b662-bc7391426327');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b677c00a-ad5b-4e13-a816-703993555521', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'Spot the IMPOSTER in the following group of historical sources matched with their methodological limitations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a676a662-ba1a-43c5-a442-bdb956bf42fa', 'Statement 1', false, 'b677c00a-ad5b-4e13-a816-703993555521');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c0df01e-0f3a-4955-aa04-5ba786d268c8', 'Statement 2', false, 'b677c00a-ad5b-4e13-a816-703993555521');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5ea88a2-a322-4af6-8bca-f36fb49ae071', 'Statement 3 (Handwritten manuscripts contain cumulative scribal errors)', true, 'b677c00a-ad5b-4e13-a816-703993555521');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee1d0220-6075-4764-851a-2bf1088b9551', 'Statement 4', false, 'b677c00a-ad5b-4e13-a816-703993555521');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3daf5964-87b5-4b9b-9331-d7da5d0e211b', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'Analyze the multi-layered social hierarchy of Jatis in medieval villages:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3b5c12f-bdce-46e8-919e-c6ef6520fc09', 'Each Jati had its own elders'' council (Jati Panchayat) to enforce internal customs, but every village was simultaneously governed by a Chieftain/Gramani, subject to overarching state revenue laws', true, '3daf5964-87b5-4b9b-9331-d7da5d0e211b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('874c4fea-fc5c-40f5-a3c6-d19e5874deb6', 'Jatis were completely independent and fought wars every day', false, '3daf5964-87b5-4b9b-9331-d7da5d0e211b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4840bffb-3641-4928-9f94-eb5bde268dfe', 'Only the King could make laws for individual jatis', false, '3daf5964-87b5-4b9b-9331-d7da5d0e211b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5de5d342-e1b5-4201-81f8-64850e888cf8', 'There were no laws or village councils in medieval times', false, '3daf5964-87b5-4b9b-9331-d7da5d0e211b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('899e3e8d-31fc-4136-aabc-7ac32b4e19a7', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'Match Column I (Historical Cartographers / Authors) with Column II (Work / Perspective):
(a) Al-Idrisi (1154 CE)           -> (i) Arabic map with South India at the top
(b) French Cartographer (1720s)   -> (ii) Scientifically detailed coastal maritime atlas
(c) Minhaj-i Siraj (13th Century) -> (iii) Sultanate political definition of Hindustan
(d) Ziauddin Barani (1356/1358)   -> (iv) Two distinct manuscript versions of Tarikh-i Firuz Shahi', 'Al-Idrisi = inverted map; French atlas = maritime surveying; Minhaj = political Hindustan; Barani = dual recensions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19ccb01f-190e-45c3-a225-6366f59fe279', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '899e3e8d-31fc-4136-aabc-7ac32b4e19a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05ecb241-2240-49d7-8374-ae77f2c4349a', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '899e3e8d-31fc-4136-aabc-7ac32b4e19a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f30b9a72-2668-4f78-82d0-80c978a3a217', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '899e3e8d-31fc-4136-aabc-7ac32b4e19a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d98d278b-f86f-4723-b7bb-925dd8bd82aa', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '899e3e8d-31fc-4136-aabc-7ac32b4e19a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1b2a42d-289e-4da9-b2be-06cb0780e2c3', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'Read the statements regarding religious developments in medieval India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4f99e0c-29ad-4e34-9b46-2bf7cb54f129', 'Statements 1 and 2 only', true, 'f1b2a42d-289e-4da9-b2be-06cb0780e2c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8888ea56-19a0-491d-86f2-e25ceb302e23', 'Statements 2 and 3 only', false, 'f1b2a42d-289e-4da9-b2be-06cb0780e2c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e527468f-75bd-4e08-8423-b6482b94b512', 'Statements 1 and 3 only', false, 'f1b2a42d-289e-4da9-b2be-06cb0780e2c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5428ce73-0765-4abf-b17f-dee582be134d', 'All Statements 1, 2, and 3', false, 'f1b2a42d-289e-4da9-b2be-06cb0780e2c3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0f755c9-1d42-43c3-b1a6-a382d2705653', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'Why do modern historians consider the period between 700 and 1750 CE as a time of ''Great Mobility and Dynamic Flux''?', 'The era witnessed high geographic/social mobility: agrarian colonization, pastoral sedentarization, and dynamic political reconfiguration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bf3e45b-265c-4bef-b2b3-e3360765fbd0', 'Groups of people traveled vast distances in search of economic opportunity, pastoralists settled as peasants, forest dwellers integrated into jatis, and new warrior confederacies reshaped frontiers', true, 'c0f755c9-1d42-43c3-b1a6-a382d2705653');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2c9a297-3aa5-40da-9b40-46b6e40c1ae1', 'Because people lived in airplanes', false, 'c0f755c9-1d42-43c3-b1a6-a382d2705653');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2b9a771-d12d-4b96-874e-ef930602f7e0', 'Because all cities were completely destroyed', false, 'c0f755c9-1d42-43c3-b1a6-a382d2705653');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1938e8b6-481f-4bea-8118-656db8ae8fde', 'Because money was abolished', false, 'c0f755c9-1d42-43c3-b1a6-a382d2705653');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66b8da72-9864-4626-8f4d-457734769068', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'How did Brahmanas achieve unrivaled social prestige and dominant ideological authority in early medieval society?', 'Epistemic monopoly over Sanskrit liturgy combined with royal land grants (Brahmadeya) consolidated Brahmanical socio-ritual dominance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f41bc0cd-832d-4b56-9cf8-718d3cc29792', 'Their mastery of sacred Sanskrit texts earned them profound veneration, while royal rulers granted them vast tax-free estates (Brahmadeya/Agraharas) and state patronage', true, '66b8da72-9864-4626-8f4d-457734769068');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2215f372-ae09-4f3a-bb51-a407adbf537c', 'They possessed the largest armies of cavalry', false, '66b8da72-9864-4626-8f4d-457734769068');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb0db19d-75d8-401d-8669-7b5d1e445659', 'They were the only merchants in the kingdom', false, '66b8da72-9864-4626-8f4d-457734769068');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c2196eb-fbf5-40e0-a21d-e05c43ce8566', 'They lived outside the subcontinent', false, '66b8da72-9864-4626-8f4d-457734769068');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3337730b-0f9a-47e6-a86a-8363a24b640a', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'Consider four medieval occupational groups:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02c55282-c11c-4b7c-b797-b0c93dc3b8d8', 'They utilized emerging socio-political opportunities to claim elevated social status, political autonomy, and state-building power', true, '3337730b-0f9a-47e6-a86a-8363a24b640a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a8f9cd9-9200-42f5-b8a8-c2b8348ada8f', 'They all gave up their occupations to become monks', false, '3337730b-0f9a-47e6-a86a-8363a24b640a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('628c0a03-9e3a-4c1c-8b92-3cb751cade44', 'They were all foreign invaders from Europe', false, '3337730b-0f9a-47e6-a86a-8363a24b640a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a51ca8f4-10c4-4fb5-992f-bf6f76ec0ccd', 'They completely disappeared from Indian history', false, '3337730b-0f9a-47e6-a86a-8363a24b640a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc0bd59f-5bb0-4922-9e0b-16de82d505c8', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'What is the critical distinction between ''Continuity'' and ''Change'' in historical analysis as emphasized in Chapter 1?', 'Historical methodology balances identifying enduring structural continuities against dynamic socio-cultural transformations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('225188b3-1747-4ac6-9c85-1be705cdb763', 'History is not a series of abrupt isolated events, but a continuous dialectical process where cultural traditions persist alongside profound technological, economic, and political shifts', true, 'cc0bd59f-5bb0-4922-9e0b-16de82d505c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81a58174-88ad-43d8-b0b3-9c6fdbb53873', 'History only records sudden catastrophic changes', false, 'cc0bd59f-5bb0-4922-9e0b-16de82d505c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae79d96b-f3c3-4733-bb52-7639bac57413', 'Nothing ever changes in human civilization', false, 'cc0bd59f-5bb0-4922-9e0b-16de82d505c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6bcbc36-90e2-4631-ae45-3586a63a3468', 'Only kings determine the path of history', false, 'cc0bd59f-5bb0-4922-9e0b-16de82d505c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f8c9c63d-b719-4edd-867d-14dd014bb899', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'Why is the term ''Medieval'' problematic when applied uniformly across global civilizations without regional nuance?', 'Eurocentric ''Dark Age'' medieval tropes contrast starkly with India''s vibrant urbanization, agrarian growth, and cultural synthesis (700–1750 CE).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f7896d4-7db4-478a-9fc1-e0f6c257f22c', 'In Europe, ''Medieval'' was long stereotyped as a dark age lacking intellectual progress before the Renaissance; in India, the same period was an era of extraordinary technological, artistic, and economic vitality', true, 'f8c9c63d-b719-4edd-867d-14dd014bb899');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('092f62c8-69e1-41fb-8fc6-f3ba3cba0331', 'Because medieval means modern', false, 'f8c9c63d-b719-4edd-867d-14dd014bb899');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('442344a5-d62a-4a4a-9683-1c22edd6e63c', 'Because India had no history during this time', false, 'f8c9c63d-b719-4edd-867d-14dd014bb899');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cb0a3d9-1699-46b9-8421-95add7d145d2', 'Because Europe was ahead in every science', false, 'f8c9c63d-b719-4edd-867d-14dd014bb899');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cfdd1ed1-6410-4591-8a36-4ec0aaab3a58', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'What primary archival material provides the most reliable primary chronological records of medieval Persianate court administration?', 'Tawarikh chronicles (e.g. Tarikh-i Firuz Shahi) authored by court literati provide primary narrative accounts of governance and military campaigns.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('717a5101-9ed5-4ad4-9457-d6d2c6363bd9', 'Tarikh / Tawarikh (Persian historical chronicles written by literate court officials, secretaries, and poets)', true, 'cfdd1ed1-6410-4591-8a36-4ec0aaab3a58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a50b270-7edb-4c14-9078-12301a692a89', 'Oral folk gossip', false, 'cfdd1ed1-6410-4591-8a36-4ec0aaab3a58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41049c94-e57d-4bab-b39f-a99687546d33', 'Roman coin hoards only', false, 'cfdd1ed1-6410-4591-8a36-4ec0aaab3a58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9780db54-2cc4-4723-827c-cc397fccf9ad', 'Cave rock paintings', false, 'cfdd1ed1-6410-4591-8a36-4ec0aaab3a58');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('640ba7c7-750c-493c-af87-b53a473fd757', 'Class 7', 'Social Science', 'Chapter 1: Tracing Changes Through a Thousand Years', 'Hard', 'What foundational intellectual mindset does Chapter 1 of NCERT Class 7 History instill in young scholars?', 'The chapter equips students with historiographical toolkits: contextual source criticism, semantic evolution, and composite cultural synthesis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('424532f1-a3b3-49b8-9502-f0899065722a', 'Critical historical inquiry: examining primary sources with contextual skepticism, tracing semantic shifts in language, and appreciating the deep multicultural roots of modern Indian society', true, '640ba7c7-750c-493c-af87-b53a473fd757');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73784da2-8f0b-4ff8-a389-3862fbcfe360', 'Unquestioning memorization of dates and king names', false, '640ba7c7-750c-493c-af87-b53a473fd757');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78756180-eaf5-40ac-8413-3f95594e8f7e', 'Viewing the past through narrow sectarian biases', false, '640ba7c7-750c-493c-af87-b53a473fd757');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfda2af8-d011-4efd-ac9b-0b8085d67971', 'Believing that ancient maps were always wrong', false, '640ba7c7-750c-493c-af87-b53a473fd757');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32c1287c-9719-4f83-9f62-0e023b8361ed', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'मनुष्य अपने मन के भावों और विचारों का परस्पर आदान-प्रदान (बोलकर या लिखकर) जिस माध्यम से करता है, उसे व्याकरण में क्या कहते हैं?', 'मनुष्य के वैचारिक विनिमय और भाव-संप्रेषण के सार्थक साधन को ''भाषा'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cb47c1c-c00a-47f4-9667-56294157708c', 'भाषा (Language)', true, '32c1287c-9719-4f83-9f62-0e023b8361ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0f5dfec-8d20-4201-8e37-70ef0fde205c', 'लिपि', false, '32c1287c-9719-4f83-9f62-0e023b8361ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dacaed19-a833-4584-b9a8-c2917e093d71', 'व्याकरण', false, '32c1287c-9719-4f83-9f62-0e023b8361ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e0fa843-2d64-4c39-a7fb-b33877acae1c', 'बोली', false, '32c1287c-9719-4f83-9f62-0e023b8361ed');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('673fcfc7-3c23-4bc1-8bc7-259f12b96f57', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'भाषा के मुख्य रूप से कितने रूप होते हैं?', 'भाषा के दो मूल रूप हैं: मौखिक (ध्वन्यात्मक उच्चारण) तथा लिखित (लिपिबद्ध आलेखन)। सांकेतिक रूप को व्याकरण में गौण माना जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ce25f44-bb40-4301-a9b6-52f7ce755009', 'दो रूप (1. मौखिक भाषा - Spoken, 2. लिखित भाषा - Written)', true, '673fcfc7-3c23-4bc1-8bc7-259f12b96f57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('373173f8-f636-4306-9082-862fc05dc6b1', 'चार रूप', false, '673fcfc7-3c23-4bc1-8bc7-259f12b96f57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a863a10a-7a10-4cc5-aa77-35d347bca268', 'तीन रूप', false, '673fcfc7-3c23-4bc1-8bc7-259f12b96f57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c2d259c-95e9-422a-a13c-795dc82ac068', 'पाँच रूप', false, '673fcfc7-3c23-4bc1-8bc7-259f12b96f57');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca2f22f4-04a7-4a19-bbed-157867c5aedf', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'मुख से बोलकर अपने विचारों को प्रकट करना तथा कानों से सुनकर समझना भाषा का कौन-सा रूप कहलाता है?', 'परस्पर बोलकर और सुनकर विचार व्यक्त करने का माध्यम ''मौखिक भाषा'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ceccb3b-8cc1-4370-8f2e-33c673db0fe5', 'मौखिक भाषा (Oral / Spoken Language)', true, 'ca2f22f4-04a7-4a19-bbed-157867c5aedf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d5caaee-835e-4a49-a8f4-62d1e68c47c1', 'लिखित भाषा', false, 'ca2f22f4-04a7-4a19-bbed-157867c5aedf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86a9949c-e8ed-4b80-a7b0-924f8114d606', 'सांकेतिक भाषा', false, 'ca2f22f4-04a7-4a19-bbed-157867c5aedf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29bee0ba-e114-4d4c-90de-b9dc30bef3f5', 'मातृभाषा', false, 'ca2f22f4-04a7-4a19-bbed-157867c5aedf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67a30b93-5eb5-4e2e-ae09-4a7e711c4e59', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'ध्वनियों को लिखकर प्रकट करने के लिए निश्चित किए गए विशेष चिह्न-संकेतों (Writing System) को क्या कहते हैं?', 'मौखिक ध्वनियों को लिखित रूप देने हेतु निर्धारित प्रतीकों/चिह्नों की व्यवस्था ''लिपि'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6101ad21-447b-4d52-86d2-8261f70a4a7e', 'लिपि (Script)', true, '67a30b93-5eb5-4e2e-ae09-4a7e711c4e59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c06b514-d258-4e5e-8c65-bcffc76d0c1b', 'व्याकरण', false, '67a30b93-5eb5-4e2e-ae09-4a7e711c4e59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e849690-e3de-40e0-922d-4547fb21cb6c', 'बोली', false, '67a30b93-5eb5-4e2e-ae09-4a7e711c4e59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('504b6b70-637d-4021-a08a-6db285f85933', 'वर्णमाला', false, '67a30b93-5eb5-4e2e-ae09-4a7e711c4e59');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46bbed8e-9178-4a34-a193-1e16c2b9865d', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'हिंदी और संस्कृत भाषाएँ किस लिपि में लिखी जाती हैं?', 'हिंदी, संस्कृत, मराठी और नेपाली भाषाएँ बाएँ से दाएँ लिखी जाने वाली ''देवनागरी लिपि'' में आलेखित होती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e18aa987-990b-49a0-8ff9-2f6a5f235958', 'देवनागरी लिपि (Devanagari Script)', true, '46bbed8e-9178-4a34-a193-1e16c2b9865d');
