INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc435c3a-48c4-4fbd-863b-8ff7ba93de9f', 'फ़ारसी लिपि', false, '46bbed8e-9178-4a34-a193-1e16c2b9865d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59f1fff2-4425-4f7b-abf1-c3e5cfb6e4a3', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'अंग्रेज़ी भाषा किस लिपि में लिखी जाती है?', 'अंग्रेज़ी, फ़्रेंच, जर्मन और स्पैनिश भाषाएँ ''रोमन लिपि'' (लैटिन वर्णमाला) में लिखी जाती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bc2fbc3-a09a-4ff3-bd66-7492e7580a82', 'रोमन लिपि (Roman Script)', true, '59f1fff2-4425-4f7b-abf1-c3e5cfb6e4a3');
