INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77fd318f-476b-42e5-98e0-6444ae406c45', 'ब्राह्मी लिपि', false, '59f1fff2-4425-4f7b-abf1-c3e5cfb6e4a3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25e3523c-1539-443d-b25d-c381cc06b5b4', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'पंजाबी भाषा की पारंपरिक लिपि कौन-सी है?', 'पंजाबी भाषा ''गुरुमुखी लिपि'' (सिख गुरु अंगद देव द्वारा मानकीकृत) में लिखी जाती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79e1b3f1-8ab5-4a45-b857-5459abf0dd53', 'गुरुमुखी लिपि (Gurmukhi Script)', true, '25e3523c-1539-443d-b25d-c381cc06b5b4');
