INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('847dadff-eb88-4e81-81b1-fd5f8fb7d678', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'उर्दू भाषा किस लिपि में (दाएँ से बाएँ) लिखी जाती है?', 'उर्दू भाषा दाएँ से बाएँ की दिशा में ''फ़ारसी (नस्तलीक़) लिपि'' में लिखी जाती है।', NOW()) ON CONFLICT DO NOTHING;
