INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6fa0e6b8-158f-4bf0-96da-d6d90f0c2833', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'किसी सीमित क्षेत्रीय भू-भाग में बोली जाने वाली भाषा के स्थानीय, अनौपचारिक रूप को क्या कहते हैं?', 'सीमित क्षेत्र में प्रयुक्त बोलचाल का मौखिक रूप ''बोली'' (जैसे: अवधी, ब्रज, हरियाणवी, भोजपुरी) कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df766a3b-1f72-4c44-830a-d31f6833195b', 'बोली (Dialect)', true, '6fa0e6b8-158f-4bf0-96da-d6d90f0c2833');
