INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f854b6b-4544-431a-9a4e-7061e84a5ab8', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'भारतीय संविधान की किस धारा / अनुच्छेद (Article) के अंतर्गत हिंदी को भारत संघ की ''राजभाषा'' (Official Language) घोषित किया गया है?', 'संविधान के अनुच्छेद 343(1) के अनुसार संघ की राजभाषा हिंदी और लिपि देवनागरी है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44bdab83-5e96-4ee0-b4b1-fb04eaa30673', 'अनुच्छेद 343 (Article 343 - 14 सितंबर 1949)', true, '2f854b6b-4544-431a-9a4e-7061e84a5ab8');
