INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('784dccf2-9c35-4e95-b8b4-866616bd68d2', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Easy', 'प्रत्येक वर्ष संपूर्ण भारत में ''हिंदी दिवस'' (Hindi Diwas) किस तिथि को राष्ट्रीय स्तर पर मनाया जाता है?', '14 सितंबर 1949 को संविधान सभा द्वारा हिंदी को राजभाषा स्वीकार किए जाने के उपलक्ष्य में प्रतिवर्ष ''हिंदी दिवस'' मनाया जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0a3cfcd-d3b7-4611-b522-c225454c1829', '14 सितंबर (14th September)', true, '784dccf2-9c35-4e95-b8b4-866616bd68d2');
