INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('781f08ab-fce6-498b-9c23-65def5fa8cdc', '26 जनवरी', false, '784dccf2-9c35-4e95-b8b4-866616bd68d2');
