INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0a6dd10-3aeb-4675-be0a-9282d564bc4a', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'व्याकरण के मुख्य रूप से कितने अंग (भाग / विभाग) होते हैं?', 'व्याकरण के 4 प्रमुख विभाग हैं: वर्ण विचार (ध्वनि), शब्द विचार (व्युत्पत्ति), पद विचार (रूपांतरण), तथा वाक्य विचार (संरचना)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dafaa27-61f1-46e5-855a-db652baa831a', 'चार अंग (1. वर्ण विचार - Phonology, 2. शब्द विचार - Morphology, 3. पद विचार - Syntax of parts, 4. वाक्य विचार - Syntax)', true, 'b0a6dd10-3aeb-4675-be0a-9282d564bc4a');
