INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fda01022-e7b1-404b-bef3-4d6fcb439916', 'पाँच अंग', false, 'b0a6dd10-3aeb-4675-be0a-9282d564bc4a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4b48a34-ac08-461b-9e54-a663e2eddcd3', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'बच्चा अपने परिवार और माता-पिता से शैशवावस्था में जो भाषा सबसे पहले स्वाभाविक रूप से सीखता है, उसे क्या कहते हैं?', 'पारिवारिक परिवेश में बालक द्वारा प्रथम अर्जित प्राथमिक भाषा ''मातृभाषा'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('166457af-362a-4ded-9855-911e50d82d3b', 'मातृभाषा (Mother Tongue)', true, 'd4b48a34-ac08-461b-9e54-a663e2eddcd3');
