INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8384bd16-d45f-40df-8340-af0725532a77', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'देश के अधिकांश नागरिकों द्वारा बोली और समझी जाने वाली सर्वमान्य संपर्क भाषा को क्या कहते हैं?', 'राष्ट्र के बहुसंख्यक जनसमुदाय द्वारा प्रयुक्त संपर्क एवं सांस्कृतिक एकता की सूत्रधार भाषा ''राष्ट्रभाषा'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4e9c84f-755f-48ea-a411-a53c8ddd8c43', 'राष्ट्रभाषा (National Language)', true, '8384bd16-d45f-40df-8340-af0725532a77');
