INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da925a4d-9383-4372-a6d5-7c42dcbdf9aa', '14 भाषाएँ', false, 'f507474d-40a1-4dbe-a795-246c55f5a777');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ffa7f5f-e163-42a7-bac7-dad6bcbfa821', '28 भाषाएँ', false, 'f507474d-40a1-4dbe-a795-246c55f5a777');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d47bcda-9beb-4d82-b090-0495259b76e9', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', '''बोली'' और ''भाषा'' में क्या मुख्य अंतर होता है?', 'बोली स्थानीय और अलिखित/मौखिक होती है; भाषा व्यापक, व्याकरण-सम्मत, लिपिबद्ध और साहित्यिक रूप धारण करती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1201898d-4f2c-4b22-a50e-42894866ba3b', 'बोली का क्षेत्र सीमित होता है और उसमें मानक साहित्य नहीं रचा जाता ; जबकि भाषा का क्षेत्र व्यापक होता है, उसकी अपनी मानक लिपि तथा समृद्ध लिखित साहित्य होता है', true, '8d47bcda-9beb-4d82-b090-0495259b76e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f9f9d04-07c0-4590-8b58-99e5667e2db2', 'बोली केवल विदेशी बोलते हैं', false, '8d47bcda-9beb-4d82-b090-0495259b76e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34f1494c-a700-47f9-9b88-5b42ac7cbd2e', 'भाषा केवल किताबों में होती है', false, '8d47bcda-9beb-4d82-b090-0495259b76e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac84b4aa-af0c-43b0-a2b8-5cf0f56376a3', 'दोनों में कोई अंतर नहीं है', false, '8d47bcda-9beb-4d82-b090-0495259b76e9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e617b7ed-2a99-46c3-9301-b806096652cd', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'जब किसी बोली में प्रचुर उत्कृष्ट साहित्य की रचना होने लगती है और उसका क्षेत्र विस्तृत हो जाता है (जैसे: सूरदास का ब्रजभाषा साहित्य, तुलसीदास की अवधी), तब वह क्या कहलाती है?', 'साहित्यिक सृजन से समृद्ध बोली ''उपभाषा'' का स्तर प्राप्त कर लेती है (जैसे: अवधी, ब्रजभाषा, मैथिली)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('451d6403-3175-49f1-bd40-233f45aa5224', 'उपभाषा (Sub-language / Literary Dialect)', true, 'e617b7ed-2a99-46c3-9301-b806096652cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f60b6983-e468-40b4-a129-11f725a9d358', 'राष्ट्रभाषा', false, 'e617b7ed-2a99-46c3-9301-b806096652cd');
