INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('39722290-e69e-4633-9fdf-7013a8ac338b', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'ज्ञान के संचित और व्यवस्थित कोष (कोष / खजाने) को क्या कहते हैं?', 'युग-युगांतर से संचित कल्याणकारी ज्ञानराशि और अनुभूतियों का व्यवस्थित लिखित संग्रह ''साहित्य'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
