INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4ea8d27c-6c3d-48c2-8f3a-2bd205f9880a', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'साहित्य के मुख्य रूप से दो भेद कौन-से होते हैं?', 'साहित्य के दो मूल वर्गीकरण हैं: गद्य (छंदमुक्त गद्यात्मक अभिव्यक्ति) तथा पद्य (गेय, लयात्मक, छंदोबद्ध काव्य)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f8bb083-6c1d-4917-b146-95acae398225', 'गद्य साहित्य (Prose - कहानी, निबंध, उपन्यास) और पद्य साहित्य (Poetry - कविता, पद, दोहे)', true, '4ea8d27c-6c3d-48c2-8f3a-2bd205f9880a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da42d005-6bb1-4580-a693-05c2ade8907b', 'मौखिक साहित्य और लिखित साहित्य', false, '4ea8d27c-6c3d-48c2-8f3a-2bd205f9880a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fcf45bc-f544-4044-96c0-ffe716cba16c', 'प्राचीन साहित्य और नया साहित्य', false, '4ea8d27c-6c3d-48c2-8f3a-2bd205f9880a');
