INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b517d911-ec50-46ba-8eb4-7bdf87bfb13d', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'देवनागरी लिपि की सर्वप्रमुख वैज्ञानिक विशेषता क्या है?', 'देवनागरी की विशिष्टता उसका वैज्ञानिक ध्वनि-प्रतीक सामंजस्य है: पूर्ण ध्वन्यात्मक संगति और शिरोरेखा (Head-line)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15b0fffa-0a76-4838-96ec-df1253714110', 'यह पूर्णतः ध्वन्यात्मक (Phonetic) लिपि है — जैसा बोला और उच्चारित किया जाता है, ठीक वैसा ही अक्षरशः लिखा और पढ़ा जाता है (प्रत्येक ध्वनि के लिए अद्वितीय वर्ण)', true, 'b517d911-ec50-46ba-8eb4-7bdf87bfb13d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17613e49-31ee-4739-ab3c-84a0a8f70a25', 'इसमें केवल 10 वर्ण होते हैं', false, 'b517d911-ec50-46ba-8eb4-7bdf87bfb13d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6ec85cc-634f-4ee0-ad3e-dfb4c0d2a492', 'यह ऊपर से नीचे लिखी जाती है', false, 'b517d911-ec50-46ba-8eb4-7bdf87bfb13d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e9b2727-68d8-436c-b0e1-52114dd2e86a', 'इसमें कोई स्वर नहीं होते', false, 'b517d911-ec50-46ba-8eb4-7bdf87bfb13d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2ddef62-08df-4077-b52d-aebd9b4dd904', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'व्याकरण के किस अंग के अंतर्गत वर्णों के आकार, उच्चारण, वर्गीकरण तथा संधि नियमों का अध्ययन किया जाता है?', 'वर्ण विचार में वर्णों के भेद, उच्चारण स्थान और ध्वनि संयोग का सैद्धांतिक अध्ययन होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39e6aa29-03f0-483c-bbf9-bc23e0b4129a', 'वर्ण विचार (Phonology)', true, 'c2ddef62-08df-4077-b52d-aebd9b4dd904');
