INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61930888-5a1b-401d-add2-cc1e0fc262ce', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'व्याकरण के किस अंग के अंतर्गत शब्दों के भेद, उत्पत्ति, व्युत्पत्ति तथा रचना का अध्ययन किया जाता है?', 'शब्द विचार में तत्सम, तद्भव, देशज, विदेशी, रूढ़, यौगिक और योगरूढ़ शब्दों की संरचना का विश्लेषण होता है।', NOW()) ON CONFLICT DO NOTHING;
