INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2038caa1-edc1-482f-a505-607897f1f46d', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'जब कोई स्वतंत्र शब्द वाक्य में व्याकरणिक नियमों (लिंग, वचन, कारक) के अनुसार प्रयुक्त होता है, तब वह क्या कहलाता है?', 'वाक्य में प्रयुक्त होकर व्याकरणिक संबंध स्थापित करने वाला शब्द ''पद'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
