INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('652b3ecc-1c42-4ad8-9826-4f79ebf79e03', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'व्याकरण के किस अंग के अंतर्गत वाक्य की रचना, वाक्य के अंग (उद्देश्य और विधेय), भेद तथा विराम चिह्नों का अध्ययन किया जाता है?', 'वाक्य विचार में वाक्य के अंगों, रूपांतरण, संश्लेषण और विश्लेषण का नियमन होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28d45653-7c1f-4b94-a0f4-ce7f5e0e6868', 'वाक्य विचार (Syntax)', true, '652b3ecc-1c42-4ad8-9826-4f79ebf79e03');
