INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94708aec-f0e9-486b-960f-775d1451c36e', 'पद विचार', false, '652b3ecc-1c42-4ad8-9826-4f79ebf79e03');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('48f9267c-6042-4f4b-90dd-1e784a63485e', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'विश्व में सबसे अधिक बोली जाने वाली भाषाओं में हिंदी का स्थान कौन-सा है?', 'वैश्विक जनसांख्यिकी (Ethnologue) में अंग्रेजी और मंदारिन के उपरांत हिंदी विश्व की तीसरी सर्वाधिक प्रयुक्त भाषा है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92d83d5f-8504-44ec-8875-83435439379e', 'विश्व की तीसरी (3rd) सर्वाधिक बोली जाने वाली वृहत्तम भाषा', true, '48f9267c-6042-4f4b-90dd-1e784a63485e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4a50d06-9ece-4c15-b5c8-3dc693a396d5', 'दसवाँ स्थान', false, '48f9267c-6042-4f4b-90dd-1e784a63485e');
