INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85212a02-78e7-4dcf-a760-9f5cf1a76716', 'पचासवाँ स्थान', false, '48f9267c-6042-4f4b-90dd-1e784a63485e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5773746d-ef54-48d9-8011-101484bc76fc', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Medium', 'निम्नलिखित में से कौन-सी भाषा देवनागरी लिपि में नहीं लिखी जाती है?', 'उर्दू फ़ारसी लिपि में लिखी जाती है; जबकि संस्कृत, मराठी, नेपाली और हिंदी देवनागरी में आलेखित होती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b0a1f83-c4c7-4602-867e-0b8a34277e4f', 'उर्दू (जो फ़ारसी लिपि में लिखी जाती है)', true, '5773746d-ef54-48d9-8011-101484bc76fc');
