INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('17a75b8e-5c65-4f16-8988-e2d70557a982', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ae4013d-2b93-4220-9b1f-7c15af02769d', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '17a75b8e-5c65-4f16-8988-e2d70557a982');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87a970b7-8cfc-4e44-952d-512614089b85', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '17a75b8e-5c65-4f16-8988-e2d70557a982');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e23ed8a-e195-479a-9401-a5802f725f17', '(A) सही है, परन्तु (R) गलत है।', false, '17a75b8e-5c65-4f16-8988-e2d70557a982');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('169b8f59-ff98-46e7-98c1-11923a6f0562', '(A) गलत है, परन्तु (R) सही है।', false, '17a75b8e-5c65-4f16-8988-e2d70557a982');
