INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57f39fac-d29f-4ee3-9625-2fc1e3fc3cfb', 'हिंदी - देवनागरी', false, 'd2e62746-2960-4b45-a8cb-ee28ea1f0ad5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('796cee2a-723d-4a74-ac94-677a7ad36c93', 'अंग्रेज़ी - रोमन', false, 'd2e62746-2960-4b45-a8cb-ee28ea1f0ad5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2baf9f03-58b4-4754-a9e6-b2b8821eb66b', 'Punjabi - गुरुमुखी', false, 'd2e62746-2960-4b45-a8cb-ee28ea1f0ad5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0d2c02f-adc7-4115-834a-7a71062b4bcf', 'अरबी - देवनागरी', true, 'd2e62746-2960-4b45-a8cb-ee28ea1f0ad5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ebbf106-3c0f-4d88-b2cb-fc1c704cd907', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'सुमेलित कीजिए (भाषा/बोली और उसके भौगोलिक/सांस्कृतिक वर्ग):
(क) अवधी और ब्रजभाषा -> (i) पश्चिमी व पूर्वी हिंदी की समृद्ध उपभाषाएँ
(ख) मैथिली और भोजपुरी -> (ii) बिहारी हिंदी वर्ग की बोलियाँ
(ग) गढ़वाली व कुमाऊँनी -> (iii) पहाड़ी हिंदी वर्ग की बोलियाँ
(घ) मारवाड़ी व जयपुरी  -> (iv) राजस्थानी हिंदी वर्ग की बोलियाँ', 'अवधी/ब्रज = मध्य देश; मैथिली/भोजपुरी = बिहारी; गढ़वाली/कुमाऊँनी = पहाड़ी; मारवाड़ी = राजस्थानी।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('894f1078-a558-4691-973b-e290056888e5', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, '0ebbf106-3c0f-4d88-b2cb-fc1c704cd907');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd3df81d-5c06-4725-967a-c4a0fc4e3cdb', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '0ebbf106-3c0f-4d88-b2cb-fc1c704cd907');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efb965d3-12f7-4601-9812-c5b8bae4855e', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '0ebbf106-3c0f-4d88-b2cb-fc1c704cd907');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fed543d7-0d28-4e34-be5c-50583ed5b931', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '0ebbf106-3c0f-4d88-b2cb-fc1c704cd907');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0766adbc-d768-4740-b793-13c61fd58e20', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'व्याकरण भाषा का निर्माण करता है अथवा भाषा का नियमन और अनुशासन करता है? सही दार्शनिक संबंध बताइए:', 'भाषा नैसर्गिक रूप से अग्रगामी होती है; व्याकरण भाषा का अनुगामी विश्लेषक एवं मानकीकृत नियामक होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1188b1e1-e4d3-4c38-9f34-ce229100269d', 'भाषा पहले स्वाभाविक रूप से जन्म लेती है और लोकव्यवहार में विकसित होती है ; व्याकरण भाषा का निर्माण नहीं करता, अपितु प्रचलित भाषा के स्वरूप का वैज्ञानिक विश्लेषण करके उसके नियम निर्धारित और अनुशासित करता है', true, '0766adbc-d768-4740-b793-13c61fd58e20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bb8561c-0700-49e8-b4e5-1dfa753c524e', 'व्याकरण पहले बनता है फिर भाषा बनती है', false, '0766adbc-d768-4740-b793-13c61fd58e20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22360789-e120-4578-aca5-c6c963835272', 'व्याकरण के बिना मनुष्य बोल ही नहीं सकता', false, '0766adbc-d768-4740-b793-13c61fd58e20');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f06c1e54-be0c-41d4-a1aa-301fa0a3f4bd', 'भाषा और व्याकरण में कोई संबंध नहीं होता', false, '0766adbc-d768-4740-b793-13c61fd58e20');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c263c011-bf8f-4447-87ee-f1aeaa505d0b', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'अंतर्राष्ट्रीय स्तर पर विश्व के विभिन्न देशों के बीच विचार-विमर्श, व्यापार तथा कूटनीतिक संपर्क के लिए स्वीकृत सर्वमान्य भाषा को क्या कहते हैं?', 'वैश्विक कूटनीति, वाणिज्य एवं वैज्ञानिक शोध हेतु प्रयुक्त वैश्विक संपर्क भाषा ''अंतर्राष्ट्रीय भाषा'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e85b3ba4-2b21-43e6-8a08-f7a959e5c3a9', 'अंतर्राष्ट्रीय भाषा (International Language - जैसे: अंग्रेज़ी)', true, 'c263c011-bf8f-4447-87ee-f1aeaa505d0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38a08472-0d7d-4e62-8171-cfcfb1123045', 'राजभाषा', false, 'c263c011-bf8f-4447-87ee-f1aeaa505d0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d6e6642-7f6b-4151-9d54-8f9534d7c78e', 'मातृभाषा', false, 'c263c011-bf8f-4447-87ee-f1aeaa505d0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a886ff9a-401d-459c-a2bb-84cf8999e215', 'बोली', false, 'c263c011-bf8f-4447-87ee-f1aeaa505d0b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('71ee4f0a-97df-4429-9bc6-476e478ee9e4', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'देवनागरी लिपि का ऐतिहासिक उद्भव और विकास भारत की किस प्राचीन ऐतिहासिक लिपि से हुआ है?', 'देवनागरी, बंगाली, तमिल, तेलुगु आदि अधिकांश भारतीय लिपियों की जननी प्राचीन ''ब्राह्मी लिपि'' है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b2f155d-c237-4ba2-a682-985fe8e237e5', 'ब्राह्मी लिपि (Brahmi Script - सम्राट अशोक के अभिलेखों की मूल लिपि)', true, '71ee4f0a-97df-4429-9bc6-476e478ee9e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fd6f427-dcb1-4a88-bf92-a5c3981e8aae', 'खरोष्ठी लिपि', false, '71ee4f0a-97df-4429-9bc6-476e478ee9e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('179eeafa-82bf-4ee7-8074-ddf5edec23e8', 'सिंधु घाटी लिपि', false, '71ee4f0a-97df-4429-9bc6-476e478ee9e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c879da3a-3ec2-4997-83bc-caf093fe1ca3', 'अरामी लिपि', false, '71ee4f0a-97df-4429-9bc6-476e478ee9e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4dcbd8c7-b23e-4753-8497-62b366898f1d', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', '''मानक भाषा'' (Standard Language) से क्या अभिप्राय है?', 'मानक भाषा (Standard Register) प्रामाणिक व्याकरणिक मानदंडों पर आधारित सर्वमान्य साहित्यिक व प्रशासनिक माध्यम है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ad23d60-01ce-4de9-aa83-4927de8f33e6', 'विद्वानों, शिक्षाविदों तथा शासन द्वारा सर्वसम्मति से स्वीकृत भाषा का वह शुद्ध, व्याकरण-सम्मत, एकरूप तथा सर्वमान्य रूप जो पत्र-पत्रिकाओं, पुस्तकों और दूरदर्शन में प्रयुक्त होता है', true, '4dcbd8c7-b23e-4753-8497-62b366898f1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('975978d4-e29e-4d37-8a63-cd21dac0a862', 'केवल अनपढ़ लोगों द्वारा बोली जाने वाली भाषा', false, '4dcbd8c7-b23e-4753-8497-62b366898f1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6edea16f-7def-4de9-a4e4-8b9e7bbbc42f', 'वह भाषा जिसमें कोई नियम न हो', false, '4dcbd8c7-b23e-4753-8497-62b366898f1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f04727a8-61e2-4f6f-a108-1ec8a8a0e9db', 'प्राचीन समय की मृत भाषा', false, '4dcbd8c7-b23e-4753-8497-62b366898f1d');
