INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('537d9609-e888-48fe-bc49-9959f4ecdd45', 'सभी 1, 2, 3 और 4 पूर्णतः सत्य हैं', true, '869d003e-3820-4548-9fc7-5eb945ab0132');
