INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2589e236-d848-40b6-b6c9-425afef41b00', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'वाक्य में अशुद्ध अंश की पहचान कीजिए और व्याकरणिक दोष का कारण बताइए:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d9d82d2-9382-4488-9f0d-ee5221ae1d22', '''मुझे आपकी बात समझ नहीं आई।'' (सर्वनाम संबंधी अशुद्धि : ''मेरे को'' के स्थान पर मानक सर्वनाम ''मुझे'' का प्रयोग)', true, '2589e236-d848-40b6-b6c9-425afef41b00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05f7187f-beff-4a5a-acea-ad683e9e9856', '''मुझको आपकी बात समझ नहीं आई।''', false, '2589e236-d848-40b6-b6c9-425afef41b00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74e458e2-5e5e-4180-b026-a219615efe2a', '''मैं को आपकी बात समझ नहीं आई।''', false, '2589e236-d848-40b6-b6c9-425afef41b00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d65ae440-518d-4c66-889a-d2d3aa1aff2b', '''मेरे द्वारा आपकी बात समझी गई।''', false, '2589e236-d848-40b6-b6c9-425afef41b00');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1a61a6f-9fd4-44e8-a31b-139e93cb31dc', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'ध्वनि (Phoneme) और वर्ण (Letter) में क्या सूक्ष्म अंतर होता है?', 'ध्वनि श्रव्य/मौखिक न्यूनतम इकाई है; वर्ण उसका दृश्य/लिखित आलेखीय प्रतीक (Grapheme) है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('949020d2-0a66-46c8-a247-be8c1075d04d', 'ध्वनि मौखिक भाषा की सबसे छोटी अविभाज्य उच्चरित इकाई है (कानों से सुनाई देती है) ; जबकि वर्ण उसी ध्वनि का लिखित दृश्य रूप/चिह्न है (आँखों से देखा जाता है)', true, 'f1a61a6f-9fd4-44e8-a31b-139e93cb31dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64c8e812-6f6a-4e34-8ae7-68008b417501', 'ध्वनि और वर्ण में कोई अंतर नहीं है', false, 'f1a61a6f-9fd4-44e8-a31b-139e93cb31dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bf22ac5-7148-41e9-af6a-fe60b6e7ff49', 'ध्वनि केवल वाद्ययंत्रों में होती है', false, 'f1a61a6f-9fd4-44e8-a31b-139e93cb31dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1e30c4d-7d49-4bcc-9835-5283e03734ab', 'वर्ण केवल कागज़ का नाम है', false, 'f1a61a6f-9fd4-44e8-a31b-139e93cb31dc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('538a4bde-064d-4032-be9a-f66cfbf21bd3', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'भाषा के मानकीकरण में केंद्रीय हिंदी निदेशालय और वैज्ञानिक तथा तकनीकी शब्दावली आयोग (CSTT) की क्या भूमिका है?', 'केंद्रीय हिंदी निदेशालय मानक वर्तनी, तकनीकी शब्दावली और देवनागरी यूनिकोड का मानकीकरण सुनिश्चित करता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6b38bb0-d730-491f-94d2-1cb9d8b4418e', 'हिंदी वर्तनी, पारिभाषिक शब्दावली और देवनागरी लिपि के मानकीकृत नियमों का निर्धारण करना ताकि पूरे राष्ट्र में एकरूपता बनी रहे', true, '538a4bde-064d-4032-be9a-f66cfbf21bd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2df39c2c-25c1-4e1c-a478-3f5d8248dbf6', 'नई बोलियों पर प्रतिबंध लगाना', false, '538a4bde-064d-4032-be9a-f66cfbf21bd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f476451-4944-452a-9a5e-1260f975dafb', 'केवल पुरानी पुस्तकें छापना', false, '538a4bde-064d-4032-be9a-f66cfbf21bd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8c3a5c8-d443-4e9f-9a6e-a07989506ff1', 'विदेशी भाषाओं को समाप्त करना', false, '538a4bde-064d-4032-be9a-f66cfbf21bd3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8275267f-842f-4dc1-a180-917f02815f17', 'Class 7', 'Hindi Grammar', 'Chapter 1: भाषा, लिपि और व्याकरण', 'Hard', 'कक्षा 7 हिंदी व्याकरण के प्रथम अध्याय का सारगर्भित निष्कर्ष क्या है?', 'अध्याय 1 भाषा के सांस्कृतिक महत्व, लिपि की ऐतिहासिकता तथा व्याकरण की नियामक सौंदर्य-चेतना को प्रतिष्ठापित करता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e59da379-9ac7-4a9e-ac85-cbc025e15e0a', 'भाषा मानव अभिव्यक्ति का अमूल्य वरदान है, लिपि उसकी अमर स्मृति है, और व्याकरण वह प्रकाश स्तंभ है जो भाषा को शुद्धता, अनुशासन और अमरता प्रदान करता है', true, '8275267f-842f-4dc1-a180-917f02815f17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72609074-689d-4338-abcf-39aeb89c2f1d', 'व्याकरण का अध्ययन केवल परीक्षा पास करने के लिए है', false, '8275267f-842f-4dc1-a180-917f02815f17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18bb312e-3645-4df6-a295-7cecda291194', 'बिना व्याकरण के भी भाषा हमेशा शुद्ध रहती है', false, '8275267f-842f-4dc1-a180-917f02815f17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90e0f489-70e5-4732-80d8-ca3a0394b3f3', 'भाषा केवल भारत में बोली जाती है', false, '8275267f-842f-4dc1-a180-917f02815f17');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1bde4787-8421-45fc-bc34-ff85e619fec7', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Easy', 'The process of taking food into the body through the mouth is called:', 'Ingestion is the initial physiological step of taking food into the buccal cavity/oral mouth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36b92ea0-22a5-4cd8-8b03-6924324e83bc', 'Ingestion', true, '1bde4787-8421-45fc-bc34-ff85e619fec7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb005e44-907d-4347-840c-e66bc2cf0408', 'Digestion', false, '1bde4787-8421-45fc-bc34-ff85e619fec7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5376ccc0-0e69-49a0-9a87-dd8543952c74', 'Absorption', false, '1bde4787-8421-45fc-bc34-ff85e619fec7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05cc52ad-51de-4406-80b7-1e9c528b43d5', 'Egestion', false, '1bde4787-8421-45fc-bc34-ff85e619fec7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('42ca7717-4625-4843-834f-3d5788c8bf1c', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Easy', 'The breakdown of complex, insoluble food substances into simpler, soluble absorbable molecules is called:', 'Digestion is the biochemical and mechanical hydrolysis of complex food polymers into absorbable monomer units.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55fb5a41-cee7-4921-b25d-b05def55a409', 'Digestion', true, '42ca7717-4625-4843-834f-3d5788c8bf1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16f69abb-53de-4da5-9008-aa43a32cc90b', 'Ingestion', false, '42ca7717-4625-4843-834f-3d5788c8bf1c');
