INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e76923e-3ad4-4993-8043-73e9323b8ef6', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Easy', 'Which flat, chisel-shaped front teeth are specialized for BITING and CUTTING food?', 'Incisors (4 in each jaw = 8 total) have sharp chisel edges designed for cutting and biting food.', NOW()) ON CONFLICT DO NOTHING;
