INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f8e9e1f-89c1-4ad9-81a1-a02fe828c09e', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Easy', 'Which sharp, pointed teeth situated next to the incisors are specialized for PIERCING and TEARING tough food/meat?', 'Canines (2 in each jaw = 4 total) possess pointed conical cusps adapted for tearing.', NOW()) ON CONFLICT DO NOTHING;
