INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('500dc8d0-8635-4821-8cb2-9daadd01a3d1', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Easy', 'What digestive fluid is secreted by the Salivary Glands into the mouth to moisten food and break down starch into simple sugars?', 'Saliva contains ptyalin/amylase which initiates the chemical digestion of starch into maltose sugar.', NOW()) ON CONFLICT DO NOTHING;
