INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bdd2c884-2239-43d7-be02-d14daf55d0b1', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Easy', 'What acid is secreted by the inner lining of the Stomach to kill harmful bacteria ingested with food and provide an acidic medium for pepsin?', 'Gastric parietal cells secrete dilute HCl (pH ~1.5–2) to kill pathogens and activate the protein enzyme pepsin.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34268dcf-a449-42e5-b7ae-80de84a1c385', 'Hydrochloric Acid (HCl)', true, 'bdd2c884-2239-43d7-be02-d14daf55d0b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee699973-27a6-4ade-b47b-c863a4d2c60c', 'Sulfuric Acid', false, 'bdd2c884-2239-43d7-be02-d14daf55d0b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55f2e6ac-d3b1-4503-9cca-f4a213b3a9c9', 'Citric Acid', false, 'bdd2c884-2239-43d7-be02-d14daf55d0b1');
