INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e56bb730-c7cd-4df2-a8e8-addb27b8c875', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Easy', 'Which is the LARGEST gland in the human body, reddish-brown in color, situated in the upper abdomen on the right side?', 'The liver is the heaviest internal metabolic gland (~1.5 kg in adults), secreting bile for fat emulsification.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91523552-6428-40a5-b1bf-3b4a06baaf1d', 'Liver', true, 'e56bb730-c7cd-4df2-a8e8-addb27b8c875');
