INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d5b2c1e-08fd-4008-bb53-d2fd54d04349', 'Thyroid', false, 'e56bb730-c7cd-4df2-a8e8-addb27b8c875');
