INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a4a3b3be-bf3f-4edd-93a9-9bbea95520cd', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Easy', 'Where is Bile juice stored in the body before being released into the small intestine?', 'Bile secreted by hepatic cells is concentrated and stored inside the muscular sac-like Gall Bladder.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd5b9d4e-6257-45b7-9ba0-503f1fd4bbfb', 'Gall Bladder', true, 'a4a3b3be-bf3f-4edd-93a9-9bbea95520cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5c1f604-335b-496f-a647-9a31ee33a92c', 'Stomach', false, 'a4a3b3be-bf3f-4edd-93a9-9bbea95520cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46341187-d0d8-4488-b580-495a234aefed', 'Pancreas', false, 'a4a3b3be-bf3f-4edd-93a9-9bbea95520cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6994a731-7bd3-4b8d-be5f-39ed5a9434cb', 'Large Intestine', false, 'a4a3b3be-bf3f-4edd-93a9-9bbea95520cd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('153c65bb-b1be-49d8-8e9b-84a31462cef8', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Easy', 'What are the thousands of tiny, finger-like outgrowths on the inner walls of the Small Intestine that dramatically increase the surface area for food absorption called?', 'Intestinal villi and microvilli expand internal surface area multi-hundredfold, lined with rich capillary networks for nutrient absorption.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba099046-6914-475f-8649-7d3cfc66874c', 'Villi (singular: Villus)', true, '153c65bb-b1be-49d8-8e9b-84a31462cef8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64ac15eb-94c6-487a-bad6-a748f9975592', 'Cilia', false, '153c65bb-b1be-49d8-8e9b-84a31462cef8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be77c1b8-2d20-4b4e-b76c-4342fa634a0f', 'Pseudopodia', false, '153c65bb-b1be-49d8-8e9b-84a31462cef8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('539bab45-9646-48fd-98b0-358e84d6fd6f', 'Flagella', false, '153c65bb-b1be-49d8-8e9b-84a31462cef8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27f87b03-2486-47d6-9258-dcc0f9594c67', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Easy', 'How does the microscopic single-celled organism Amoeba capture and engulf its food?', 'Amoeba uses cytoplasmic streaming to extend pseudopodia, engulfing prey by phagocytosis into a food vacuole.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c476943-425d-4406-b149-83a144573d0f', 'By extending finger-like false feet called Pseudopodia around the food particle to form a Food Vacuole', true, '27f87b03-2486-47d6-9258-dcc0f9594c67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfd40756-0d12-4150-8824-8c49a83585fe', 'Using sharp teeth', false, '27f87b03-2486-47d6-9258-dcc0f9594c67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bf26622-bdcb-4958-a3b7-2c3381999a5d', 'Through a wide mouth', false, '27f87b03-2486-47d6-9258-dcc0f9594c67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06a3af74-9db5-4f98-8a1d-0246cb6ef69d', 'By swimming with fins', false, '27f87b03-2486-47d6-9258-dcc0f9594c67');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be440e86-98d1-40be-bf90-b14520fefd50', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'Why do cows, buffaloes, and other grass-eating animals chew continuously even when they are resting and not eating fresh grass?', 'Ruminants regurgitate cud from the rumen back to the buccal cavity for secondary mastication and enzymatic breakdown.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc6f8790-a8ff-49ec-821a-d70563abb223', 'They quickly swallow grass into the Rumen where it is partially digested into ''Cud''; later, cud returns to the mouth in small lumps for thorough chewing (Rumination)', true, 'be440e86-98d1-40be-bf90-b14520fefd50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b00d500c-59bc-4b30-897f-d84d107989ff', 'Because their teeth never stop growing', false, 'be440e86-98d1-40be-bf90-b14520fefd50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d61b9d4-bc68-47e1-9793-9e2e431ee765', 'Because they are chewing bubblegum', false, 'be440e86-98d1-40be-bf90-b14520fefd50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3eb7762-e066-4630-9692-19c6115f21b2', 'To make grass colder', false, 'be440e86-98d1-40be-bf90-b14520fefd50');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6481d5d5-c5ca-4b76-8711-1f5f35280c67', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'Why can ruminant animals (cows, goats) digest tough plant Cellulose while human beings CANNOT digest cellulose at all?', 'Ruminant caecum/rumen harbors cellulolytic microbes breaking β-1,4-glycosidic cellulose bonds, which humans pass as dietary fiber.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0202aa70-00db-48e3-ace5-b9a202a1c46a', 'Ruminants have a large sac-like Caecum containing specialized symbiotic anaerobic bacteria and protozoa that produce cellulose-digesting enzymes (cellulase), which humans lack', true, '6481d5d5-c5ca-4b76-8711-1f5f35280c67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6015056e-d15d-40c4-b6f6-2c28819daf8d', 'Because humans have smaller teeth than cows', false, '6481d5d5-c5ca-4b76-8711-1f5f35280c67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc530ad1-eaf0-43bd-b03b-4ea32b860237', 'Because human stomachs have no acid', false, '6481d5d5-c5ca-4b76-8711-1f5f35280c67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7507e030-b44b-44ec-8417-eea2c64bded8', 'Because cows drink more water', false, '6481d5d5-c5ca-4b76-8711-1f5f35280c67');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('65846589-caed-4d03-93b1-10b0ca8ac809', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What protects the delicate inner wall lining of the Stomach from being corroded and digested by its own potent Hydrochloric Acid?', 'Gastric epithelial mucous cells secrete a bicarbonate-rich mucosal barrier protecting against acid-peptic autodigestion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dacf51bf-1bda-4284-a5bd-a42a94a58cc3', 'A thick, slippery protective layer of Mucous secreted by gastric mucosal cells', true, '65846589-caed-4d03-93b1-10b0ca8ac809');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1c8c1dc-3fb3-4ae3-be71-829d275dfb46', 'A layer of plastic', false, '65846589-caed-4d03-93b1-10b0ca8ac809');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ce5793b-25bd-4755-bddf-9dce91baacd3', 'Saliva from the mouth', false, '65846589-caed-4d03-93b1-10b0ca8ac809');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('251ae602-583c-4759-a176-4872eb55a4c9', 'Bile juice', false, '65846589-caed-4d03-93b1-10b0ca8ac809');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ef2742d1-efc9-41e8-8c90-a6f4e7506615', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What is the wave-like muscular contraction and relaxation of the walls of the Food Pipe (Oesophagus) that pushes swallowed food down into the stomach called?', 'Peristalsis is the rhythmic, coordinated involuntary contraction of longitudinal and circular gastrointestinal muscles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59b0c909-5a9f-4954-8f21-c47a38c1f228', 'Peristalsis (Peristaltic Movement)', true, 'ef2742d1-efc9-41e8-8c90-a6f4e7506615');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('395a4166-67c2-49e9-a7e9-cf4a2319fe1e', 'Circulation', false, 'ef2742d1-efc9-41e8-8c90-a6f4e7506615');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83579986-f4bf-4c36-b16b-4a5646b942c2', 'Respiration', false, 'ef2742d1-efc9-41e8-8c90-a6f4e7506615');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4c37f53-264d-4883-b3c9-ef50059688ce', 'Filtration', false, 'ef2742d1-efc9-41e8-8c90-a6f4e7506615');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('65c4afec-f6c8-4737-9d95-6a70483c7a91', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What crucial digestive role does Bile Juice play in the digestion of dietary FATS in the small intestine?', 'Bile salts (sodium glycocholate/taurocholate) act as biological detergents, emulsifying lipid triglycerides for lipase action.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c1e363b-c2f9-492e-982c-c01872f5803f', 'It emulsifies large fat globules into tiny micro-droplets, dramatically increasing the surface area for pancreatic lipase enzymes to break down fats into fatty acids and glycerol', true, '65c4afec-f6c8-4737-9d95-6a70483c7a91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3ee7c63-9554-43d5-985b-6c8ec96b9a4e', 'It converts fats directly into proteins', false, '65c4afec-f6c8-4737-9d95-6a70483c7a91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('206fadd5-5fea-4ed2-960d-41df98b929a0', 'It turns fats into solid bones', false, '65c4afec-f6c8-4737-9d95-6a70483c7a91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bd4541f-22aa-4398-b82e-8f8f92d52cb9', 'It freezes fats so they cannot enter blood', false, '65c4afec-f6c8-4737-9d95-6a70483c7a91');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ddf0643-9625-40a9-878a-e37407f8ea71', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What is ''Tooth Decay'' (Dental Caries) and what causes it?', 'Streptococcus mutans ferment oral sucrose into lactic acid, demineralizing hydroxyapatite enamel below critical pH 5.5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17917e77-0bd7-459f-89b8-74c5492f5a5a', 'Bacteria present in mouth feed on leftover sugary food particles and produce corrosive ACIDS that gradually dissolve the hard calcium enamel and dentine', true, '8ddf0643-9625-40a9-878a-e37407f8ea71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34051098-1da8-49a3-8ae9-a4db1942f1f2', 'Eating too many green vegetables', false, '8ddf0643-9625-40a9-878a-e37407f8ea71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2beb8cd-680c-459d-8f1d-ffa09d6909c5', 'Brushing teeth with toothpaste twice a day', false, '8ddf0643-9625-40a9-878a-e37407f8ea71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('037993c8-1a8a-4395-8813-b6f53d46f0f4', 'Drinking cold water', false, '8ddf0643-9625-40a9-878a-e37407f8ea71');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35149c7f-a5ed-4022-bb3e-a2832002bd77', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What is the primary physiological function of the LARGE INTESTINE in the human digestive system?', 'The colon/large intestine reabsorbs ~90% of residual luminal water and electrolytes, consolidating solid feces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c0b69f4-ea29-4122-b1bc-f1f156ccc6aa', 'Absorption of water and essential mineral salts from unabsorbed, undigested food matter, forming solid fecal waste for egestion', true, '35149c7f-a5ed-4022-bb3e-a2832002bd77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57e16487-b4ad-4ca0-a28e-39305e86b6a7', 'Complete digestion of proteins and fats', false, '35149c7f-a5ed-4022-bb3e-a2832002bd77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7532b0f0-653f-43cf-b8d5-44ba215d9ef9', 'Secretion of hydrochloric acid', false, '35149c7f-a5ed-4022-bb3e-a2832002bd77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0af558db-371b-4698-ae48-09d3edf1dfc3', 'Pumping blood to the heart', false, '35149c7f-a5ed-4022-bb3e-a2832002bd77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b57fc358-6a07-4fea-bcaf-f8ee22e960fd', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What is ''Assimilation'' in animal nutrition?', 'Assimilation is the cellular anabolic incorporation of absorbed amino acids, monosaccharides, and fatty acids into living protoplasm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07402401-f541-4424-8bfe-00fed4d7cf00', 'The transport and utilization of absorbed nutrient molecules by body cells to build complex tissues (proteins, cell membranes) and release energy for growth', true, 'b57fc358-6a07-4fea-bcaf-f8ee22e960fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7b4c32d-112d-4496-94fd-bc72e22b08b9', 'The removal of undigested feces through anus', false, 'b57fc358-6a07-4fea-bcaf-f8ee22e960fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b783dadd-de00-4dec-9e72-fde77a0af1c1', 'Chewing food in mouth', false, 'b57fc358-6a07-4fea-bcaf-f8ee22e960fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c35122d-31b8-4f57-a139-36cb3d091097', 'Swallowing water', false, 'b57fc358-6a07-4fea-bcaf-f8ee22e960fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('08b80d80-408b-4b92-bd3f-129992955544', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What happens during severe Diarrhoea, and why is administering Oral Rehydration Solution (ORS) life-saving?', 'ORS exploits intestinal sodium-glucose co-transport mechanisms (SGLT1) to rapidly rehydrate hypovolemic patients.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45f7a226-8765-47cc-aba3-5377daf3e2b1', 'Severe diarrhoea causes rapid, life-threatening loss of water and vital electrolytes (dehydration); ORS restores fluid, sodium, and glucose balance rapidly', true, '08b80d80-408b-4b92-bd3f-129992955544');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbe6582f-9047-43e2-b31c-93fd11f41d8b', 'ORS makes a person sleepy', false, '08b80d80-408b-4b92-bd3f-129992955544');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0db6f419-068e-4192-bd12-d63fc4e47279', 'ORS changes blood into milk', false, '08b80d80-408b-4b92-bd3f-129992955544');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('031fa2c2-f51c-438c-b52d-b397a579541b', 'Diarrhoea is harmless and needs no water', false, '08b80d80-408b-4b92-bd3f-129992955544');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6318ed22-0445-49b1-8cd5-0dc728b0e8ec', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'How does the unique marine animal Starfish (Asterias) feed on hard-shelled mollusks (clams and oysters)?', 'Starfish exhibit extraordinary eversible cardiac stomach feeding: everting stomach into bivalve shells for external enzymatic digestion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbf6a6af-fd15-4fff-89f0-eb454ae8ccb0', 'It pries open the shell, pops its own stomach OUT through its mouth into the shell to digest the soft animal inside, and then pulls its stomach back in', true, '6318ed22-0445-49b1-8cd5-0dc728b0e8ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39943fbf-f202-42d8-b547-402adc842184', 'It swallows the whole shell and crushes it with teeth', false, '6318ed22-0445-49b1-8cd5-0dc728b0e8ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('644f12ab-8ef6-4b85-9f26-777cb400c7e3', 'It drills a hole with a laser', false, '6318ed22-0445-49b1-8cd5-0dc728b0e8ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36d3fc8d-70a4-451c-a296-fd4d90756b29', 'It injects poison and waits for 10 years', false, '6318ed22-0445-49b1-8cd5-0dc728b0e8ec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('12a5bcac-c463-4251-bf55-52e1f96cfafb', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What is the historical medical discovery made by American doctor William Beaumont in 1822 through the unhealed gunshot stomach wound of Alexis St. Martin?', 'Dr. Beaumont''s pioneering gastric fistula experiments laid the empirical foundation of human gastrointestinal physiology.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a26d999f-ed66-4a8c-880f-70ec2c2489d7', 'He directly observed that the stomach walls churn food mechanically, secrete digestive acid/juices, and digestion proceeds only when food is exposed to these fluids', true, '12a5bcac-c463-4251-bf55-52e1f96cfafb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('792431b4-e19c-4679-9e7b-b078fc75e34a', 'He discovered that the stomach is made of bone', false, '12a5bcac-c463-4251-bf55-52e1f96cfafb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('152bbf04-f2a6-4eb3-bde1-86b01b3a9d13', 'He found that food turns into gold inside', false, '12a5bcac-c463-4251-bf55-52e1f96cfafb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6383e36c-9e50-4bd6-a752-a1c0e673ec98', 'He proved the stomach has teeth', false, '12a5bcac-c463-4251-bf55-52e1f96cfafb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae4170b0-14e0-44c2-8995-17095822b963', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What are the four primary taste modalities detected by taste buds located on different regional zones of the human Tongue?', 'Gustatory papillae taste buds detect Sweet, Salty, Sour, Bitter (and Umami) gustatory modalities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e481eb0-2d11-4529-aeba-d54fe5d67db4', 'Sweet, Sour, Salty, and Bitter', true, 'ae4170b0-14e0-44c2-8995-17095822b963');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ff62901-34b9-477c-aeaa-1efcfa9ef9ca', 'Hot, Cold, Wet, and Dry', false, 'ae4170b0-14e0-44c2-8995-17095822b963');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d0e0727-6338-40fd-a50f-f0936af2c311', 'Soft, Hard, Rough, and Smooth', false, 'ae4170b0-14e0-44c2-8995-17095822b963');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1788b28f-3792-498e-8ade-6a134ff1cf95', 'Red, Blue, Green, and Yellow', false, 'ae4170b0-14e0-44c2-8995-17095822b963');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11222395-ef31-4b81-a39c-2cbbffdba79a', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'Into what simpler, absorbable end-products are the three major food components broken down during complete digestion in the small intestine?', 'Terminal enzymatic hydrolysis yields absorbable monomer units: glucose/monosaccharides, amino acids, and fatty acids/glycerol.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7db3670b-7490-499a-ad16-7b77291d690e', 'Carbohydrates -> Glucose ; Proteins -> Amino Acids ; Fats -> Fatty Acids and Glycerol', true, '11222395-ef31-4b81-a39c-2cbbffdba79a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c10b573-e5e7-41c7-9ec1-f23a40fc1439', 'Carbohydrates -> Starch ; Proteins -> Meat ; Fats -> Oil', false, '11222395-ef31-4b81-a39c-2cbbffdba79a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a112acea-c1da-4f61-bcf4-b456e7067cb3', 'All three turn into pure water', false, '11222395-ef31-4b81-a39c-2cbbffdba79a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c25448f8-aa21-4c1f-92d3-527386286f8e', 'Carbohydrates -> Carbon ; Proteins -> Nitrogen ; Fats -> Oxygen', false, '11222395-ef31-4b81-a39c-2cbbffdba79a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f209322-7efd-42df-9191-2f83ca06a826', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'Why does chewing a piece of dry plain bread or boiled rice for several minutes without swallowing make it taste increasingly SWEET in the mouth?', 'Oral mastication blends salivary amylase with starch, hydrolyzing poly-saccharides into sweet disaccharide maltose.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('742fef17-587e-49b7-a6f2-0d6a3111c4ed', 'Salivary amylase enzyme present in saliva breaks down complex, tasteless starch molecules into sweet-tasting maltose sugar', true, '9f209322-7efd-42df-9191-2f83ca06a826');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('283f4336-fb08-4a57-9112-50ba755413cc', 'Because teeth have sugar crystals', false, '9f209322-7efd-42df-9191-2f83ca06a826');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5761e39-c8f5-40c9-84e2-9cb8be6a1fbd', 'Because bread absorbs sugar from air', false, '9f209322-7efd-42df-9191-2f83ca06a826');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a0456a9-d85d-47b2-87d4-6ae1eeefa0a1', 'Because saliva turns into honey', false, '9f209322-7efd-42df-9191-2f83ca06a826');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0967c05-e28a-41e4-8601-38a9b0cd87a5', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'What is the ''Milk Teeth'' set in human children, and at what age are they replaced by the permanent adult dentition?', 'Deciduous milk teeth (20 in total) shed sequentially between 6–8 years as secondary permanent teeth erupt.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28add88d-cac7-4fb2-8f05-89980da0449d', 'The first temporary set of 20 deciduous teeth that erupt in infancy and fall off between the ages of 6 and 8 years', true, 'd0967c05-e28a-41e4-8601-38a9b0cd87a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c427ec6-ae8c-4f3d-b056-8d328cc06ba1', 'Teeth made of dried milk', false, 'd0967c05-e28a-41e4-8601-38a9b0cd87a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f4f2d4e-de2e-492d-93bd-df8f4b2cd3ee', 'Teeth that never fall out', false, 'd0967c05-e28a-41e4-8601-38a9b0cd87a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d92659c-485a-44ce-8c74-3bb5a480cde0', 'Adult teeth that appear at age 40', false, 'd0967c05-e28a-41e4-8601-38a9b0cd87a5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('efcb9073-bcfd-4c70-8dd2-742e8de2a8ee', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Medium', 'Why do we cough or choke violently if we laugh or talk hurriedly while swallowing food?', 'Laryngeal epiglottic closure guards the glottis during deglutition; talking diverts food into the trachea, invoking the protective cough reflex.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efb88ad9-1870-4196-9d04-311caa75b030', 'The flap-like Epiglottis fails to close the windpipe (trachea) entrance in time, allowing food particles to enter the windpipe and triggering the coughing reflex', true, 'efcb9073-bcfd-4c70-8dd2-742e8de2a8ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8697aeb5-9800-4696-8827-4ad15fb172ab', 'Because food hits the ears', false, 'efcb9073-bcfd-4c70-8dd2-742e8de2a8ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a84aa57-35eb-4068-a817-9d4e08499f39', 'Because teeth bite the tongue', false, 'efcb9073-bcfd-4c70-8dd2-742e8de2a8ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e46f7f0c-5c6f-45a1-a735-a50a0742ffa0', 'Because the stomach is full of air', false, 'efcb9073-bcfd-4c70-8dd2-742e8de2a8ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e71ce0e-e6e7-42f9-a7a7-14d077516279', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85055b9b-4819-40c4-914b-e70938d0a98b', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '4e71ce0e-e6e7-42f9-a7a7-14d077516279');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68260c1d-aed8-4994-9afe-6f5184ca1ae3', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '4e71ce0e-e6e7-42f9-a7a7-14d077516279');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0079c21-0f43-4b4d-9938-2885a9909a5b', '(A) is true, but (R) is false.', false, '4e71ce0e-e6e7-42f9-a7a7-14d077516279');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('920f1683-6629-4404-8db1-36f23c1d4161', '(A) is false, but (R) is true.', false, '4e71ce0e-e6e7-42f9-a7a7-14d077516279');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98d47e80-c181-4d6b-81a7-9acccc2809df', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'Spot the IMPOSTER in the following sequence of steps in Animal Nutrition:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02d88192-e643-4513-882f-209a1061663f', 'Statement 1', false, '98d47e80-c181-4d6b-81a7-9acccc2809df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cee16d2-8d34-4525-ae71-669ce29d5042', 'Statement 2 (Absorption is taking nutrients into blood ; Assimilation is cellular utilization)', true, '98d47e80-c181-4d6b-81a7-9acccc2809df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b0f0b80-def3-4512-b9d4-82863bb13858', 'Statement 3', false, '98d47e80-c181-4d6b-81a7-9acccc2809df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8bf7575-c6de-42ed-9e2b-7c438130fa25', 'Statement 4', false, '98d47e80-c181-4d6b-81a7-9acccc2809df');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('95622e48-bfb4-4a84-9de7-e7545e206f4d', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'A student sets up two test tubes:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a660d372-4a98-47c8-be5b-94534e31f766', 'Test Tube A turns deep Blue-Black (starch present) ; Test Tube B shows NO blue-black color (remains pale yellowish-brown because salivary amylase broke starch down into sugar)', true, '95622e48-bfb4-4a84-9de7-e7545e206f4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a87ff69e-bba7-437b-9467-3cd64de43a53', 'Both turn deep blue-black', false, '95622e48-bfb4-4a84-9de7-e7545e206f4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59cd050b-492c-478e-80dd-43b86024792a', 'Neither tube shows any color change', false, '95622e48-bfb4-4a84-9de7-e7545e206f4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59f67eae-27bd-4ccf-865a-a11dd3949866', 'Test Tube B turns blue-black and Tube A remains clear', false, '95622e48-bfb4-4a84-9de7-e7545e206f4d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db051950-9502-4737-a0f8-cd7d2d9e8120', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'Match Column I (Digestive Organs) with Column II (Primary Biochemical Functions):
(a) Buccal Cavity   -> (i) Hydrochloric acid & pepsin protein digestion
(b) Stomach         -> (ii) Emulsification of fats via bile juice
(c) Liver           -> (iii) Complete digestion & villi nutrient absorption
(d) Small Intestine -> (iv) Mastication & starch digestion by salivary amylase', 'Mouth = starch hydrolysis; Stomach = HCl/protein; Liver = bile emulsification; Small Intestine = terminal absorption.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ef7fb3e-ba7e-4969-af99-93182d79fb79', 'a-(iv), b-(i), c-(ii), d-(iii)', true, 'db051950-9502-4737-a0f8-cd7d2d9e8120');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c773ef0b-372e-4f63-a3df-2535006046a6', 'a-(i), b-(iv), c-(iii), d-(ii)', false, 'db051950-9502-4737-a0f8-cd7d2d9e8120');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ecc391b-6846-42a5-babf-d41155691ef9', 'a-(ii), b-(iii), c-(iv), d-(i)', false, 'db051950-9502-4737-a0f8-cd7d2d9e8120');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c206dbb-51c8-451d-b7ac-b616903083f7', 'a-(iii), b-(ii), c-(i), d-(iv)', false, 'db051950-9502-4737-a0f8-cd7d2d9e8120');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c72ab494-24a0-40ba-ab0e-54a3531db601', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'Read the statements regarding animal digestion:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3983e406-6482-4ef9-8991-06fff13c8653', 'Statements 1 and 3 only', true, 'c72ab494-24a0-40ba-ab0e-54a3531db601');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3181d13a-1ea3-46f8-9491-eae8b7576f29', 'Statements 1 and 2 only', false, 'c72ab494-24a0-40ba-ab0e-54a3531db601');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2f248c5-edde-45b7-934e-b95359fcce7b', 'Statements 2 and 3 only', false, 'c72ab494-24a0-40ba-ab0e-54a3531db601');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c131da58-03bf-4af0-9489-59a417160425', 'All Statements 1, 2, and 3', false, 'c72ab494-24a0-40ba-ab0e-54a3531db601');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad4a3e3d-0cac-4179-b393-0449982e5fa2', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'Consider the anatomical dental formula of an adult human with 32 permanent teeth:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72530c36-70f2-4df4-bf21-6ff8040db982', 'Incisors: 8 ; Canines: 4 ; Premolars: 8 ; Molars: 12 (Dental formula: 2-1-2-3 / 2-1-2-3 × 2 = 32)', true, 'ad4a3e3d-0cac-4179-b393-0449982e5fa2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bf91063-c9e4-486e-a2ea-640ef85737ed', 'Incisors: 4 ; Canines: 8 ; Premolars: 12 ; Molars: 8', false, 'ad4a3e3d-0cac-4179-b393-0449982e5fa2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('694577db-981a-40a4-9999-9a6fca605f9a', 'Incisors: 8 ; Canines: 8 ; Premolars: 8 ; Molars: 8', false, 'ad4a3e3d-0cac-4179-b393-0449982e5fa2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e33f1ef8-8c0a-4276-abd2-c92d49609f7c', 'Incisors: 10 ; Canines: 2 ; Premolars: 10 ; Molars: 10', false, 'ad4a3e3d-0cac-4179-b393-0449982e5fa2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3b2bd11-ed2d-47e4-8564-75859e346c49', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'Why do fatty acids and glycerol absorbed by intestinal villi enter the central Lymphatic Lacteal vessels rather than direct blood capillaries?', 'Chylomicrons exit enterocytes via exocytosis, entering permeable lacteal lymphatics for thoracic duct delivery to circulation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a25ac011-566c-43f7-8b2f-dca220edde2d', 'Water-insoluble fatty acids are re-synthesized into chylomicron lipid droplets inside epithelial cells, which are too large to cross blood capillary pores and enter the wider lacteal lymphatic system', true, 'd3b2bd11-ed2d-47e4-8564-75859e346c49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a7391eb-2b29-42cb-b728-cdd7c11cf437', 'Because blood destroys all fats immediately', false, 'd3b2bd11-ed2d-47e4-8564-75859e346c49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd17394b-797d-4f04-ab61-d3b397465103', 'Because lacteals are made of fat', false, 'd3b2bd11-ed2d-47e4-8564-75859e346c49');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f12c454-2fc7-491e-8217-32124d9debc9', 'Because fats turn into blood in the liver', false, 'd3b2bd11-ed2d-47e4-8564-75859e346c49');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('15d105e6-bb88-4773-abbe-52104c1a6554', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'What is the structural and functional similarity between nutrition in the single-celled Amoeba and multi-cellular Human beings?', 'Universal holozoic nutrition across metazoa and protozoa follows identical sequential biochemical phases: ingestion, digestion, absorption, assimilation, egestion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38120f22-64fd-4d41-9b54-a87230a72a81', 'Both require complex food intake, chemical enzymatic breakdown into soluble nutrients, cellular absorption/assimilation, and expulsion of undigested waste', true, '15d105e6-bb88-4773-abbe-52104c1a6554');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b0cd69e-35ad-467e-813b-74a34484e568', 'Both chew food with enamel teeth', false, '15d105e6-bb88-4773-abbe-52104c1a6554');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef56532d-c325-4d5b-b04e-63d366f23dec', 'Both possess an 8-meter long alimentary canal', false, '15d105e6-bb88-4773-abbe-52104c1a6554');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c2b9c20-d345-4718-923a-8bc9d0872ad4', 'Both use pseudopodia for swallowing', false, '15d105e6-bb88-4773-abbe-52104c1a6554');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1163d4f6-3e55-4b5d-8d72-4fbd42d6c55e', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'Why does the Pancreatic Juice contain sodium bicarbonate in addition to digestive enzymes (trypsin, amylase, lipase)?', 'Pancreatic ductal HCO₃⁻ neutralizes gastric HCl, establishing an alkaline duodenal environment (pH 7.8–8.2) for enzyme kinetics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77ae5d4e-622f-49ba-a9df-0ee956f75fb3', 'To neutralize the highly acidic chyme arriving from the stomach, creating an optimal ALKALINE medium (pH ~8.0) required for pancreatic enzymes to function', true, '1163d4f6-3e55-4b5d-8d72-4fbd42d6c55e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c21a3784-3e7a-4132-9d57-c90cbe6f0cec', 'To make the food spicy', false, '1163d4f6-3e55-4b5d-8d72-4fbd42d6c55e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3cc1f07-8401-4c8d-a885-fef160a27555', 'To cool the stomach down', false, '1163d4f6-3e55-4b5d-8d72-4fbd42d6c55e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d2887bb-1232-46b2-ad0e-f6ef55d4ce45', 'To produce bubbles in blood', false, '1163d4f6-3e55-4b5d-8d72-4fbd42d6c55e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b3891a1d-d25a-44b3-9158-1d373aaadd11', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'Consider four physiological events in human digestion:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b78ed276-4306-4532-9777-9e64a8fc5d15', 'Event 3 (Mouth) -> Event 2 (Stomach) -> Event 1 (Small Intestine) -> Event 4 (Large Intestine)', true, 'b3891a1d-d25a-44b3-9158-1d373aaadd11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efdba5ca-24e0-4b52-8d7f-7c455fad2401', 'Event 1 -> Event 2 -> Event 3 -> Event 4', false, 'b3891a1d-d25a-44b3-9158-1d373aaadd11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f004a750-5d76-4a20-8f05-f33abb21d0e5', 'Event 2 -> Event 1 -> Event 4 -> Event 3', false, 'b3891a1d-d25a-44b3-9158-1d373aaadd11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05aa7733-8eea-4b97-9079-1f56cda20720', 'Event 4 -> Event 3 -> Event 2 -> Event 1', false, 'b3891a1d-d25a-44b3-9158-1d373aaadd11');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('170f77b3-417a-49c7-a137-603f3cdbd7c3', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'What is the specialized evolutionary adaptation in Hydra for capturing aquatic prey and injecting paralyzing neurotoxins?', 'Hydra fires microscopic pressurized nematocyst barbed threads containing hypnotoxin to immobilize aquatic prey.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b7fc73a-970e-433a-9bc4-cf8b5ce8491b', 'Stinging cells called Nematocysts (Cnidocytes) located on its flexible tentacles around the mouth', true, '170f77b3-417a-49c7-a137-603f3cdbd7c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27b9798f-0485-48ee-9f50-a1e48f00bce5', 'Sharp incisor teeth', false, '170f77b3-417a-49c7-a137-603f3cdbd7c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0edfb16-6d64-4aeb-8aa8-da351fd5bd3f', 'Pseudopodia', false, '170f77b3-417a-49c7-a137-603f3cdbd7c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6be6e638-7226-42ef-80ad-d43ff1cbe424', 'A muscular tongue', false, '170f77b3-417a-49c7-a137-603f3cdbd7c3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('210a2477-8464-4c69-87a2-c829275b950f', 'Class 7', 'Science', 'Chapter 2: Nutrition in Animals', 'Hard', 'What overarching biological concept summarizes Chapter 2 of NCERT Class 7 Science?', 'Chapter 2 synthesizes comparative digestive morphology, biochemical enzyme cascades, and metabolic assimilation across the animal kingdom.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e3df3ed-232f-4234-a660-3de16f203304', 'Holozoic animal nutrition is a marvel of evolutionary specialization: diverse organisms possess intricate mechanical and biochemical systems tailored to ingest, hydrolyze, assimilate nutrients, and sustain metabolic life', true, '210a2477-8464-4c69-87a2-c829275b950f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d9e1c34-155e-4308-bd43-e08b77afaf48', 'All animals have identical stomachs and teeth', false, '210a2477-8464-4c69-87a2-c829275b950f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8897af51-eef7-4ffd-aad8-f5315ef9919c', 'Digestion only happens in mouth', false, '210a2477-8464-4c69-87a2-c829275b950f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8a0abcf-6b1d-45d3-b2bd-535afbc82ee2', 'Animals do not require any enzymes for digestion', false, '210a2477-8464-4c69-87a2-c829275b950f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fdee0f1-66cc-4368-bc1b-2d558e12ddb6', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'A fraction where the Numerator is strictly LESS than the Denominator (such as 3/5, 7/9) is called a:', 'In a proper fraction, 0 < numerator < denominator, representing a quantity strictly less than 1 whole.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c95c227-8fa7-4093-ae1a-6ff49f7711c2', 'Proper Fraction', true, '7fdee0f1-66cc-4368-bc1b-2d558e12ddb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74c43913-930b-40e7-af27-195ac6935ad8', 'Improper Fraction', false, '7fdee0f1-66cc-4368-bc1b-2d558e12ddb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f89214c5-681e-467a-af8e-f815978c878f', 'Mixed Fraction', false, '7fdee0f1-66cc-4368-bc1b-2d558e12ddb6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8b1c0a2-752e-41bd-b126-f8b21c32c413', 'Reciprocal', false, '7fdee0f1-66cc-4368-bc1b-2d558e12ddb6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cdf7a917-1365-4f33-9ab9-4329462bc213', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'A fraction where the Numerator is GREATER than or equal to the Denominator (such as 7/4, 9/5) is called an:', 'In an improper fraction, numerator ≥ denominator, representing a value ≥ 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5a75708-7e1d-4cfb-ad92-70bbfda8ef35', 'Improper Fraction', true, 'cdf7a917-1365-4f33-9ab9-4329462bc213');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a589845f-4fb1-42d8-a1ab-083d24b2e1d9', 'Proper Fraction', false, 'cdf7a917-1365-4f33-9ab9-4329462bc213');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7dc127e-ec7e-4927-913e-890164fa2cd9', 'Decimal Fraction', false, 'cdf7a917-1365-4f33-9ab9-4329462bc213');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14f3d005-c778-4c7a-8359-70f25dde1107', 'Unit Fraction', false, 'cdf7a917-1365-4f33-9ab9-4329462bc213');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc5c5b22-1690-4bc2-9f17-04572bc2e636', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'Convert the improper fraction 17/5 into a Mixed Fraction:', '17 ÷ 5 = 3 with remainder 2 → 3 2/5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad83fac7-c4c9-4275-8a9a-664d4504a7e9', '3 2/5 (17 ÷ 5 = Quotient 3, Remainder 2)', true, 'dc5c5b22-1690-4bc2-9f17-04572bc2e636');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9db7440-32d0-4ca4-a58a-85361309b1be', '3 1/5', false, 'dc5c5b22-1690-4bc2-9f17-04572bc2e636');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e8a3d3e-56d2-4e1e-979c-e05b2289e25c', '2 3/5', false, 'dc5c5b22-1690-4bc2-9f17-04572bc2e636');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20fc386f-dd14-4b16-85a6-78802afdfdf3', '5 2/3', false, 'dc5c5b22-1690-4bc2-9f17-04572bc2e636');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8cf951c-49d4-41b6-bd1a-bdc3e16308fa', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'What is the product of multiplying two fractions: (2/3) × (5/7)?', 'Product of fractions = (Product of numerators) / (Product of denominators) = (2×5)/(3×7) = 10/21.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10eb6568-23a8-4cd6-8582-bd1d7cb107c5', '10/21 ((2 × 5) / (3 × 7) = 10/21)', true, 'd8cf951c-49d4-41b6-bd1a-bdc3e16308fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40db6c27-1cca-488b-af6d-254222209894', '7/10', false, 'd8cf951c-49d4-41b6-bd1a-bdc3e16308fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02e3dcca-a9f2-4e22-aeac-3936fa7a8c75', '10/14', false, 'd8cf951c-49d4-41b6-bd1a-bdc3e16308fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1557b2d7-b7ab-4b02-b87b-4dd0b92e95e0', '14/15', false, 'd8cf951c-49d4-41b6-bd1a-bdc3e16308fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e1395c2-73f8-46c0-84f6-826609785621', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'Evaluate: (1/2) of 24:', 'In mathematics, the operator ''of'' represents multiplication: (1/2) × 24 = 12.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe357a4e-ad8d-4bba-899b-24a86c55d2c6', '12 (1/2 × 24 = 12)', true, '4e1395c2-73f8-46c0-84f6-826609785621');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6cec74a-0568-4dde-84b4-aa5b347d4752', '24', false, '4e1395c2-73f8-46c0-84f6-826609785621');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27b8aaa8-c11b-4a95-ba15-f55ff564289e', '48', false, '4e1395c2-73f8-46c0-84f6-826609785621');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48c6ccc2-4492-40fc-a02c-b673ed268f3b', '6', false, '4e1395c2-73f8-46c0-84f6-826609785621');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f07ecaf2-de4d-47e5-a52f-c66ad1cfd16a', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'What is the non-zero Reciprocal (Multiplicative Inverse) of the fraction 4/9?', 'The reciprocal of a/b is b/a (inverting numerator and denominator).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9897a5e-8a1c-4fd7-80f1-45bfa1c4b830', '9/4 (since 4/9 × 9/4 = 1)', true, 'f07ecaf2-de4d-47e5-a52f-c66ad1cfd16a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b18530fb-a4b8-4c8f-aa63-96811d83f3a0', '-4/9', false, 'f07ecaf2-de4d-47e5-a52f-c66ad1cfd16a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49f88418-5b39-4580-b8dd-e88f4ed7cda0', '4/9', false, 'f07ecaf2-de4d-47e5-a52f-c66ad1cfd16a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4bab610-a60c-4c8a-8ef3-dbefd386745a', '1/4', false, 'f07ecaf2-de4d-47e5-a52f-c66ad1cfd16a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad8fdcba-9243-4a9e-bebb-bf938f6171b8', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'Evaluate the division of fractions: (3/5) ÷ (2/7):', 'Dividing by a fraction is multiplying by its reciprocal: (3/5) × (7/2) = 21/10.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('135f0b75-a6e2-4154-ba94-85435b1f2332', '21/10 (3/5 × 7/2 = 21/10 = 2 1/10)', true, 'ad8fdcba-9243-4a9e-bebb-bf938f6171b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('037e872f-8991-4065-815f-7c228a9d1c49', '6/35', false, 'ad8fdcba-9243-4a9e-bebb-bf938f6171b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4cb50b6-fe9c-44f1-b6a5-ba96f40c9f7f', '10/21', false, 'ad8fdcba-9243-4a9e-bebb-bf938f6171b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbb765e2-f267-4b19-98d5-543dba568fdd', '35/6', false, 'ad8fdcba-9243-4a9e-bebb-bf938f6171b8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d3b3794-a10b-445e-9258-319410ad0f30', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'What is 2.75 multiplied by 100?', 'Multiplying by 100 shifts the decimal point 2 places to the right: 2.75 × 100 = 275.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27979d77-6502-4752-a4e0-4ee9a5adadd2', '275 (Shifting decimal point 2 places to the RIGHT)', true, '6d3b3794-a10b-445e-9258-319410ad0f30');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77cff738-86f3-49af-9d76-6d9702425030', '27.5', false, '6d3b3794-a10b-445e-9258-319410ad0f30');
