INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c43ea25-53d0-47be-98e1-fb104683d0fe', '0.0275', false, '6d3b3794-a10b-445e-9258-319410ad0f30');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a2b05be-4469-4cfc-9678-886f4612be2e', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'What is 45.8 divided by 10?', 'Dividing by 10 shifts the decimal point 1 place to the left: 45.8 ÷ 10 = 4.58.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a1724b0-213f-4a36-a02a-93d3fc274e77', '4.58 (Shifting decimal point 1 place to the LEFT)', true, '9a2b05be-4469-4cfc-9678-886f4612be2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e8421d3-cbd9-42ab-b60e-28f3bb609ea9', '458', false, '9a2b05be-4469-4cfc-9678-886f4612be2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93629fe6-b075-4dda-acd5-b896adbfb1a3', '0.458', false, '9a2b05be-4469-4cfc-9678-886f4612be2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b46a9b9-a19e-463d-b06b-4581bd26b1b7', '45.8', false, '9a2b05be-4469-4cfc-9678-886f4612be2e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c17bbad9-565a-463a-9289-a9a156891ed1', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'What is the product: 0.2 × 0.3?', '0.2 × 0.3 = (2/10) × (3/10) = 6/100 = 0.06.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74abe403-25e3-4115-8368-b7db9dce7380', '0.06 (2 × 3 = 6 ; with 1 + 1 = 2 decimal places)', true, 'c17bbad9-565a-463a-9289-a9a156891ed1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed2e1899-4b3a-4712-aaf5-4b09cd7145dd', '0.6', false, 'c17bbad9-565a-463a-9289-a9a156891ed1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('545c1a07-23cd-4573-b6b5-93d9f56d7dab', '6.0', false, 'c17bbad9-565a-463a-9289-a9a156891ed1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d91dcce-ff49-4cc8-b5bf-2a6129f2f048', '0.006', false, 'c17bbad9-565a-463a-9289-a9a156891ed1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('257fde31-b1dd-43da-bc6c-4207c651748c', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'What is 7.2 divided by 9?', '7.2 ÷ 9 = 0.8.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22fc42fe-8d1f-4a09-8fe9-d4e0df76f2a9', '0.8 (72 ÷ 9 = 8 with one decimal place)', true, '257fde31-b1dd-43da-bc6c-4207c651748c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88e9a39d-e898-49f7-bbb5-01bd7931a716', '8.0', false, '257fde31-b1dd-43da-bc6c-4207c651748c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('556280a2-24bf-4659-b2d4-fa8d6ed019ca', '0.08', false, '257fde31-b1dd-43da-bc6c-4207c651748c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6d4d449-98de-428e-b59a-51a16101c1e6', '80', false, '257fde31-b1dd-43da-bc6c-4207c651748c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d93b1260-a2d2-488b-bacf-5819480f03bf', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Easy', 'Express 7 cm in metres as a decimal (1 m = 100 cm):', '7 cm = 7 ÷ 100 = 0.07 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92e78420-f7d0-4928-a629-0f013b24065a', '0.07 m (7/100 m = 0.07 m)', true, 'd93b1260-a2d2-488b-bacf-5819480f03bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b11a604a-4b6a-451d-8955-e93e14f06b57', '0.7 m', false, 'd93b1260-a2d2-488b-bacf-5819480f03bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd659a7d-3f32-40fc-a9f1-d678192c223b', '7.0 m', false, 'd93b1260-a2d2-488b-bacf-5819480f03bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f59ce5a8-3747-4b30-ac90-14979748ec95', '0.007 m', false, 'd93b1260-a2d2-488b-bacf-5819480f03bf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab952502-4b84-4d1a-9e09-0087666c2b27', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Ramesh solved 2/7 part of an exercise while Seema solved 4/5 of it. Who solved a LESSER part?', 'Converting to common denominator 35: Ramesh = 10/35, Seema = 28/35. Ramesh solved lesser.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3601c918-520c-4c2b-a782-287d67c9a302', 'Ramesh solved a lesser part (2/7 = 10/35 ; 4/5 = 28/35 ⇒ 10/35 < 28/35)', true, 'ab952502-4b84-4d1a-9e09-0087666c2b27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2552e402-3684-45c7-ba05-8b62567c6499', 'Seema solved a lesser part', false, 'ab952502-4b84-4d1a-9e09-0087666c2b27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a093eb91-0fb3-45d9-ae22-a2099aa81cd9', 'Both solved exactly the same part', false, 'ab952502-4b84-4d1a-9e09-0087666c2b27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d628d0a-e22d-46fe-a1d8-7556d7ed8d50', 'Cannot be compared', false, 'ab952502-4b84-4d1a-9e09-0087666c2b27');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e14afff8-437b-4a87-ad1b-40268b14fb35', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Sameera purchased 3 1/2 kg apples and 4 3/4 kg oranges. What is the total weight of fruits purchased by her?', '3.5 + 4.75 = 8.25 kg = 8 1/4 kg.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1497a980-078e-4379-96f8-a530f0607600', '8 1/4 kg (7/2 + 19/4 = 14/4 + 19/4 = 33/4 = 8 1/4 kg)', true, 'e14afff8-437b-4a87-ad1b-40268b14fb35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73f3752b-f37f-4c63-9a4f-76fead78a01b', '7 4/6 kg', false, 'e14afff8-437b-4a87-ad1b-40268b14fb35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b79511d-bfca-4130-8533-f486df79fec6', '8 1/2 kg', false, 'e14afff8-437b-4a87-ad1b-40268b14fb35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('628820a6-9f47-43bc-998f-6c7dc9c84eda', '7 3/4 kg', false, 'e14afff8-437b-4a87-ad1b-40268b14fb35');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fda251a2-e381-441e-94ea-3ca9b8209586', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'A car runs 16 km using 1 litre of petrol. How much distance will it cover using 2 3/4 litres of petrol?', 'Distance = 16 × (11/4) = 44 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf4f3fea-0deb-42d3-99dc-f10f1ba7604d', '44 km (16 × 11/4 = 4 × 11 = 44 km)', true, 'fda251a2-e381-441e-94ea-3ca9b8209586');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3aa0f8a6-2bdd-40c5-a4e8-a305173f6c06', '32 km', false, 'fda251a2-e381-441e-94ea-3ca9b8209586');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8743f04c-65f3-46a9-a590-db73f7b08c42', '48 km', false, 'fda251a2-e381-441e-94ea-3ca9b8209586');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b74262f9-8a43-4ba8-9600-f3d1cf760aba', '40 km', false, 'fda251a2-e381-441e-94ea-3ca9b8209586');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dea2b2c9-e60b-4451-a155-2c93d6bb0bde', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Saili plants 4 saplings in a row in her garden. The distance between two adjacent saplings is 3/4 m. Find the total distance between the FIRST and the LAST sapling:', '4 saplings have (4 - 1) = 3 equal intervals: 3 × (3/4) = 9/4 m = 2 1/4 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5ee7ced-dcfc-4ee3-a72d-554819807815', '2 1/4 m (There are 3 gaps between 4 saplings ; Distance = 3 × 3/4 = 9/4 = 2 1/4 m)', true, 'dea2b2c9-e60b-4451-a155-2c93d6bb0bde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ee3d645-c92c-438e-9e34-1a605e8ba9da', '3 m', false, 'dea2b2c9-e60b-4451-a155-2c93d6bb0bde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4a11436-6e6f-4e72-a1db-639016576c35', '2 1/2 m', false, 'dea2b2c9-e60b-4451-a155-2c93d6bb0bde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dabcc588-2f86-4565-a224-4c02ecf9a37f', '1 3/4 m', false, 'dea2b2c9-e60b-4451-a155-2c93d6bb0bde');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2a7a8ed8-dcca-443d-a289-b5745e49506b', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Lipika reads a book for 1 3/4 hours every day. She reads the entire book in 6 days. How many total hours were required by her to read the book?', 'Total hours = 6 × (7/4) = 42/4 = 21/2 = 10 1/2 hours (10.5 hours).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f73c7fe-25f8-4800-9ad0-a458d8e310e5', '10 1/2 hours (6 × 7/4 = 42/4 = 21/2 = 10 1/2 hours)', true, '2a7a8ed8-dcca-443d-a289-b5745e49506b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3c8f187-c480-41e3-be5a-de66f9459e35', '8 hours', false, '2a7a8ed8-dcca-443d-a289-b5745e49506b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa45aa86-0182-4a57-8fa4-0107f19ea2bb', '12 hours', false, '2a7a8ed8-dcca-443d-a289-b5745e49506b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6dfd81d5-d5df-41bf-b2e3-304b7900f112', '9 1/4 hours', false, '2a7a8ed8-dcca-443d-a289-b5745e49506b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fb8442df-c132-44db-9e98-79c120c1fe9b', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'A picture is 7 3/5 cm wide. To fit in a frame, it cannot be more than 7 3/10 cm wide. How much should the picture be trimmed?', '7.6 cm - 7.3 cm = 0.3 cm = 3/10 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2cd6b3f-706a-4da6-875e-ea0daffb62c7', '3/10 cm (7 3/5 - 7 3/10 = 38/5 - 73/10 = 76/10 - 73/10 = 3/10 cm)', true, 'fb8442df-c132-44db-9e98-79c120c1fe9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16796335-6b60-445c-86cb-ce975bc9a41b', '1/5 cm', false, 'fb8442df-c132-44db-9e98-79c120c1fe9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5eab1735-a616-43f0-883e-18600d4faf6a', '1/10 cm', false, 'fb8442df-c132-44db-9e98-79c120c1fe9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58a9216d-8523-40ee-99da-2da9b4d8c100', '2/5 cm', false, 'fb8442df-c132-44db-9e98-79c120c1fe9b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f21c5e08-d2f0-498a-8338-ea5d15ac3982', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Find the product: 11.2 × 0.15:', '112 × 15 = 1680. Decimal places = 1 + 2 = 3 → 1.680 = 1.68.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5715df7c-24ab-4270-8297-1ef9c050cc27', '1.680 (1.68)', true, 'f21c5e08-d2f0-498a-8338-ea5d15ac3982');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b76f7aa-5050-4994-9dbb-713c1dbcf7e4', '16.8', false, 'f21c5e08-d2f0-498a-8338-ea5d15ac3982');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('975a26b7-1376-4cad-81ea-e676361f888c', '0.168', false, 'f21c5e08-d2f0-498a-8338-ea5d15ac3982');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('deff4059-d8d5-4c23-898e-98b54cd367ed', '168', false, 'f21c5e08-d2f0-498a-8338-ea5d15ac3982');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f4fbd50-136d-4912-ace8-d5b5703e3cb2', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Evaluate: 76.5 ÷ 0.15:', '76.5 ÷ 0.15 = 7650 ÷ 15 = 510.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa82f8f7-d1d6-4000-b372-f4d56af0a85c', '510 (7650 ÷ 15 = 510)', true, '0f4fbd50-136d-4912-ace8-d5b5703e3cb2');
