INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc9c4318-25ca-4aab-8081-c3a117795788', '5.1', false, '0f4fbd50-136d-4912-ace8-d5b5703e3cb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ee20a01-817c-494d-a1f5-6263840c1655', '5100', false, '0f4fbd50-136d-4912-ace8-d5b5703e3cb2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d11ad7fb-f023-4745-953d-3c3789931548', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Find the average (mean) of the numbers: 4.2, 3.8, and 7.6:', 'Sum = 4.2 + 3.8 + 7.6 = 15.6. Average = 15.6 ÷ 3 = 5.2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7d2233b-83b5-49ea-83ff-231141a08c15', '5.2 ((4.2 + 3.8 + 7.6) / 3 = 15.6 / 3 = 5.2)', true, 'd11ad7fb-f023-4745-953d-3c3789931548');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df111bbd-6d2d-4d6c-8b6a-78febc5b8701', '5.0', false, 'd11ad7fb-f023-4745-953d-3c3789931548');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57152375-ccfa-4ef9-9aa1-b253af5bdc6f', '5.6', false, 'd11ad7fb-f023-4745-953d-3c3789931548');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ac48908-e710-4ac4-bdcd-2c19be17214c', '4.8', false, 'd11ad7fb-f023-4745-953d-3c3789931548');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('86b6aac9-a6b0-474d-937d-e4be506b099c', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'A two-wheeler covers a distance of 55.3 km in 1 litre of petrol. How much distance will it cover in 10 litres of petrol?', '55.3 × 10 = 553 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77b6f6ad-acb7-4df7-a23f-e2f5d6683e00', '553 km (55.3 × 10 = 553 km)', true, '86b6aac9-a6b0-474d-937d-e4be506b099c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eea9d0d8-e56a-4fd6-a13f-7bd757ea82d9', '55.3 km', false, '86b6aac9-a6b0-474d-937d-e4be506b099c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c89f3773-7317-4d39-af00-508d0e30675d', '5530 km', false, '86b6aac9-a6b0-474d-937d-e4be506b099c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03eee731-b290-4195-ae21-724724320aca', '5.53 km', false, '86b6aac9-a6b0-474d-937d-e4be506b099c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('033eeea9-ac60-433f-9dce-58cf02f41f01', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'The side of an equilateral triangle is 3.5 cm. Find its perimeter:', 'Perimeter = 3 × side = 3 × 3.5 = 10.5 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c53c850d-03f2-49b5-a9dc-50de1cd62bcf', '10.5 cm (3 × 3.5 = 10.5 cm)', true, '033eeea9-ac60-433f-9dce-58cf02f41f01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcb1ceff-9650-42ce-a4f8-06058c0cd5bc', '7.0 cm', false, '033eeea9-ac60-433f-9dce-58cf02f41f01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42c355c3-cf49-4288-b4d1-4379b1a77600', '12.25 cm', false, '033eeea9-ac60-433f-9dce-58cf02f41f01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9700d9e7-8d9f-44f9-b766-dde16dc4fdb9', '14.0 cm', false, '033eeea9-ac60-433f-9dce-58cf02f41f01');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47f04044-52ef-409a-adca-907dd169909d', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'The length of a rectangle is 7.1 cm and its breadth is 2.5 cm. What is the area of the rectangle?', 'Area = Length × Breadth = 7.1 × 2.5 = 17.75 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21cdb070-f6a4-44c9-9346-317797158e59', '17.75 cm² (7.1 × 2.5 = 17.75 cm²)', true, '47f04044-52ef-409a-adca-907dd169909d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c6b3504-9ff1-49af-9016-e3ff9b6fd32b', '19.2 cm²', false, '47f04044-52ef-409a-adca-907dd169909d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc8376de-f3aa-4a65-850a-5c6a83424d83', '18.5 cm²', false, '47f04044-52ef-409a-adca-907dd169909d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb300008-4360-4820-ba31-ef8aa081dae2', '16.85 cm²', false, '47f04044-52ef-409a-adca-907dd169909d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f619bc48-b1e2-4fa2-bef7-52ebbc3e9fe1', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Each side of a regular polygon is 2.5 cm in length. The perimeter of the polygon is 12.5 cm. How many sides does the polygon have?', 'Number of sides = Perimeter ÷ Side length = 12.5 ÷ 2.5 = 5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7248b993-8179-410f-8e18-073b687826ce', '5 sides (12.5 ÷ 2.5 = 5 sides - Pentagon)', true, 'f619bc48-b1e2-4fa2-bef7-52ebbc3e9fe1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f62e7fc-ded6-4ed0-a65b-a91ba1092d63', '6 sides', false, 'f619bc48-b1e2-4fa2-bef7-52ebbc3e9fe1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3477db93-c5a4-465d-9ed5-fb86235cb080', '4 sides', false, 'f619bc48-b1e2-4fa2-bef7-52ebbc3e9fe1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2999287f-48ee-4f24-9574-8c68bc3d3142', '8 sides', false, 'f619bc48-b1e2-4fa2-bef7-52ebbc3e9fe1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e771645c-fd32-4c5b-809d-c37f07cbcdb2', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'A vehicle covers a distance of 43.2 km in 2.4 litres of petrol. How much distance will it cover in 1 litre of petrol?', '43.2 ÷ 2.4 = 432 ÷ 24 = 18 km/litre.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d57a7bab-d15d-4566-aa86-4eda94842c1b', '18 km (43.2 ÷ 2.4 = 432 ÷ 24 = 18 km)', true, 'e771645c-fd32-4c5b-809d-c37f07cbcdb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd1d8c1a-312f-42fc-b344-5722a6423e16', '16 km', false, 'e771645c-fd32-4c5b-809d-c37f07cbcdb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b3609a8-408c-4e8b-b15c-f0133fc5510e', '20 km', false, 'e771645c-fd32-4c5b-809d-c37f07cbcdb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2cf5b73-0131-465e-8ce0-395c58f7dc12', '14.5 km', false, 'e771645c-fd32-4c5b-809d-c37f07cbcdb2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53c8c72d-c9f6-4e11-a8d9-d034dc070e3b', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Which of the following products is strictly LESS than each of the two fractions multiplied?', 'When two proper fractions (<1) are multiplied, the product is smaller than either factor: 8/15 < 2/3 and 8/15 < 4/5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8c8f6f0-9a07-449f-a532-40b5bcd58b2f', '(2/3) × (4/5) = 8/15 (Product of two proper fractions is ALWAYS less than each fraction)', true, '53c8c72d-c9f6-4e11-a8d9-d034dc070e3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95b40a9d-3be9-4a3d-96ab-2ce5fdbd43bf', '(3/2) × (5/4) = 15/8', false, '53c8c72d-c9f6-4e11-a8d9-d034dc070e3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4694d9ad-f18c-4dba-b85f-b27f14bec8c8', '(4/3) × (2/5) = 8/15', false, '53c8c72d-c9f6-4e11-a8d9-d034dc070e3b');
