INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('854ce4f0-2540-423a-be58-ce05c4e361c5', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Medium', 'Express 200 rupees and 5 paise in rupees as a decimal:', '5 paise = ₹0.05 → ₹200.05.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a97b033-b58a-40d8-acf9-3bd2c9cca779', '₹200.05 (5 paise = 5/100 = ₹0.05 ⇒ ₹200 + 0.05 = ₹200.05)', true, '854ce4f0-2540-423a-be58-ce05c4e361c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('934c5854-d1d0-4ef8-8d30-235ad3ac13cb', '₹200.50', false, '854ce4f0-2540-423a-be58-ce05c4e361c5');
