INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd594d02-a880-4dd6-87ae-a839786a2bcf', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '19a2fca2-b90e-434a-8c61-173c1279b907');
