INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4d3d0ed-0891-45df-85dc-7abf6882d76d', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'Spot the IMPOSTER in the following mathematical fraction and decimal evaluations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5125552-0589-4cc6-a258-1759f5f90607', 'Statement 1', false, 'e4d3d0ed-0891-45df-85dc-7abf6882d76d');
