INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d34a72ed-60e1-4e48-818c-1e7a43582de3', 'Statement 3', false, 'e4d3d0ed-0891-45df-85dc-7abf6882d76d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('902f8d6b-e522-4602-a905-b8a54e7dfc48', 'Statement 4 (0.08 ÷ 0.4 = 0.2, NOT 2.0)', true, 'e4d3d0ed-0891-45df-85dc-7abf6882d76d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('069bc716-4a60-4ad5-87b2-1fb252a1bd09', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'Simplify the complex nested fractional expression:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7db82c0f-6fbe-4352-ab64-071a3c32f4b4', '12/5 = 2 2/5 = 2.4 ((10/3 × 9/5) ÷ 5/2 = 6 ÷ 5/2 = 6 × 2/5 = 12/5 = 2.4)', true, '069bc716-4a60-4ad5-87b2-1fb252a1bd09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b52aad20-1374-4043-9f02-0f78073b5f64', '3 1/5', false, '069bc716-4a60-4ad5-87b2-1fb252a1bd09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c9cdeee-e254-4fba-8f0a-7506d8150cc0', '1 4/5', false, '069bc716-4a60-4ad5-87b2-1fb252a1bd09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7c26871-2abf-43b9-8f8a-52ee4e9d2b4f', '4 1/2', false, '069bc716-4a60-4ad5-87b2-1fb252a1bd09');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2670dfb1-3f71-4175-b6f6-40d276802c5a', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'Match Column I (Fractions & Decimal Operations) with Column II (Exact Evaluated Values):
(a) 0.5 × 0.05      -> (i) 0.025
(b) 0.5 ÷ 0.05      -> (ii) 10
(c) 3/4 of 4/3      -> (iii) 1
(d) (2/5) ÷ (4/15)  -> (iv) 1.5 (3/2)', '0.5×0.05=0.025; 0.5/0.05=10; 3/4×4/3=1; 2/5÷4/15 = 2/5×15/4 = 3/2 = 1.5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06f2e4d4-3773-4f1b-afd0-905bd70cf029', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '2670dfb1-3f71-4175-b6f6-40d276802c5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3528222d-2d40-4bf0-93ca-759fc3e1ddb4', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '2670dfb1-3f71-4175-b6f6-40d276802c5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce1c8504-c62c-45a3-a76f-76c1f78b6548', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '2670dfb1-3f71-4175-b6f6-40d276802c5a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21909af9-6c9b-4229-b610-486e6fe889f9', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '2670dfb1-3f71-4175-b6f6-40d276802c5a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c7d9f72-2e5a-4aa5-810d-2e079a5c48a7', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'Read the statements regarding fractional arithmetic:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e272e6e4-9df6-4918-ab90-f4929323af23', 'All Statements 1, 2, and 3 are TRUE', true, '9c7d9f72-2e5a-4aa5-810d-2e079a5c48a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1be454d-565a-450d-ba5e-f407cfe7a631', 'Statements 1 and 2 only', false, '9c7d9f72-2e5a-4aa5-810d-2e079a5c48a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('680c71b0-806a-4c1d-8df1-8a30483d72cb', 'Statements 2 and 3 only', false, '9c7d9f72-2e5a-4aa5-810d-2e079a5c48a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e163ece-f36a-4832-9876-6088eaff53e5', 'Statements 1 and 3 only', false, '9c7d9f72-2e5a-4aa5-810d-2e079a5c48a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0a088c4-68d8-4a02-916a-ec9569867307', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'A rectangular field has length 35.75 m and breadth 18.4 m. A running track running along the perimeter is fenced at ₹25.50 per metre. What is the total cost of fencing the field?', 'Perimeter = 2 × (35.75 + 18.4) = 108.3 m. Cost = 108.3 × 25.50 = ₹2,761.65.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e6d418e-7cd4-4f0b-9348-0ed2bba67150', '₹2,761.65 (Perimeter = 2(35.75 + 18.4) = 2(54.15) = 108.3 m ; Cost = 108.3 × 25.50 = ₹2,761.65)', true, 'b0a088c4-68d8-4a02-916a-ec9569867307');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfce3e67-0689-4ff9-8749-176d7c0848a2', '₹2,500.00', false, 'b0a088c4-68d8-4a02-916a-ec9569867307');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6477603d-61f8-45f0-b5a5-3e2af8d81437', '₹2,840.50', false, 'b0a088c4-68d8-4a02-916a-ec9569867307');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e33229ff-ba47-465a-8fa8-8196b842134c', '₹3,120.75', false, 'b0a088c4-68d8-4a02-916a-ec9569867307');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f3cc0fb-7531-446d-bdfe-f06947835cd0', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'In a class of 40 students, 1/5 of the total students like to study English, 2/5 of the total students like to study Mathematics, and the remaining students like to study Science. What FRACTION of the total students like to study Science, and how many students is that?', 'Science fraction = 1 - (1/5 + 2/5) = 1 - 3/5 = 2/5. Students = 2/5 × 40 = 16 students.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0426aced-d658-4991-aada-295ce8b24efb', 'Fraction: 2/5 ; Number of students: 16 (English = 8, Math = 16 ; Science = 40 - 24 = 16 students = 16/40 = 2/5)', true, '9f3cc0fb-7531-446d-bdfe-f06947835cd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d13de39-71dc-4c68-aae0-0a5252f9f29d', 'Fraction: 1/5 ; Number of students: 8', false, '9f3cc0fb-7531-446d-bdfe-f06947835cd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdce3327-1f9a-47ea-8b4e-d46a104359a2', 'Fraction: 3/5 ; Number of students: 24', false, '9f3cc0fb-7531-446d-bdfe-f06947835cd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6956b879-0997-4cd8-9197-208cf20c1910', 'Fraction: 1/2 ; Number of students: 20', false, '9f3cc0fb-7531-446d-bdfe-f06947835cd0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53af3907-7039-4398-b482-c53a1fe69b32', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'If 12 boxes of equal weight weigh a total of 49.8 kg, how much will 25 such boxes weigh?', 'Weight of 1 box = 49.8 ÷ 12 = 4.15 kg. Weight of 25 boxes = 4.15 × 25 = 103.75 kg.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9692d662-a83d-4086-ae31-f6a2c97d5da1', '103.75 kg (1 box = 49.8 / 12 = 4.15 kg ; 25 boxes = 4.15 × 25 = 103.75 kg)', true, '53af3907-7039-4398-b482-c53a1fe69b32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1356ef5-c0d2-48c3-bad3-e058a051de28', '98.50 kg', false, '53af3907-7039-4398-b482-c53a1fe69b32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92cbb727-c078-4435-b669-5ee63745c745', '105.25 kg', false, '53af3907-7039-4398-b482-c53a1fe69b32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1c88206-2a1f-4cd3-bad5-16d5a5f2de78', '101.40 kg', false, '53af3907-7039-4398-b482-c53a1fe69b32');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82117d4b-99b5-4512-9837-cce6f473c4f8', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'Arrange the following fractions in DESCENDING order (largest to smallest):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0db7aee2-32a3-4d10-b050-a8427f106e93', '2/3 > 8/21 > 2/9 (Common denominator 63: 2/3 = 42/63 ; 8/21 = 24/63 ; 2/9 = 14/63)', true, '82117d4b-99b5-4512-9837-cce6f473c4f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83285eaf-1e2b-4c5a-bacc-cb8f4781876f', '2/9 > 8/21 > 2/3', false, '82117d4b-99b5-4512-9837-cce6f473c4f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ca01ee5-493a-482d-bc34-4c4bb74ac6d9', '8/21 > 2/3 > 2/9', false, '82117d4b-99b5-4512-9837-cce6f473c4f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3866fb75-6746-4229-9b5f-224080953921', '2/3 > 2/9 > 8/21', false, '82117d4b-99b5-4512-9837-cce6f473c4f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('102091af-80d5-4f1b-ba79-db99b936db34', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'Evaluate: (0.2 × 0.2 × 0.2) + (0.3 × 0.3 × 0.3):', '0.2³ = 0.008; 0.3³ = 0.027. Sum = 0.008 + 0.027 = 0.035.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75d723d8-bfdf-4954-a323-832b229d2ca3', '0.035 (0.008 + 0.027 = 0.035)', true, '102091af-80d5-4f1b-ba79-db99b936db34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecbc2917-f7f9-4cbc-ad5f-14db514570fd', '0.35', false, '102091af-80d5-4f1b-ba79-db99b936db34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94d7ebfd-ecdd-496d-8d2b-681836d01028', '0.0035', false, '102091af-80d5-4f1b-ba79-db99b936db34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64b0b6bb-3072-459a-ba91-bf7b8f6d4e76', '0.05', false, '102091af-80d5-4f1b-ba79-db99b936db34');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8057d1a3-ae6e-4448-b405-8a203fd6ed89', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'A car covers a distance of 89.1 km in 2.2 hours. What is the average distance covered by it in 1 hour?', 'Speed = 89.1 ÷ 2.2 = 891 ÷ 22 = 40.5 km/h.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27a6c891-3b57-4e17-b1d5-6a2a97e937ca', '40.5 km (89.1 ÷ 2.2 = 891 ÷ 22 = 40.5 km/h)', true, '8057d1a3-ae6e-4448-b405-8a203fd6ed89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7391e71e-1c70-4221-8309-208c0c87e927', '42.0 km', false, '8057d1a3-ae6e-4448-b405-8a203fd6ed89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f16de8fc-ad1d-446c-bace-13b041fe9520', '39.5 km', false, '8057d1a3-ae6e-4448-b405-8a203fd6ed89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36f1e10a-9506-422a-8658-9fe24b091b02', '41.5 km', false, '8057d1a3-ae6e-4448-b405-8a203fd6ed89');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5eaa65e-a54c-449b-bd67-c0be40a02eb8', 'Class 7', 'Mathematics', 'Chapter 2: Fractions and Decimals', 'Hard', 'Why is the rigorous understanding of rational fractional division (multiplying by reciprocal) and decimal positional scaling foundational in quantitative computing and applied science?', 'Rational fractions and decimal scaling form the basis of continuous mathematical analysis, dimensional normalization, and numerical algorithms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07b76050-d8a0-4f70-8915-2f47513ac695', 'It allows precise non-integer continuous calculations, algorithmic scaling, unit conversions, and floating-point error control across physics and computational math', true, 'a5eaa65e-a54c-449b-bd67-c0be40a02eb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d548514-e806-4e49-a007-eca515a2e178', 'Because computers can only understand whole numbers', false, 'a5eaa65e-a54c-449b-bd67-c0be40a02eb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c87047b7-52b4-421e-aa68-a51234ec4a11', 'Because fractions eliminate decimals', false, 'a5eaa65e-a54c-449b-bd67-c0be40a02eb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80462452-a13d-4ab6-9861-c22e005f2475', 'Because division by zero is allowed in decimals', false, 'a5eaa65e-a54c-449b-bd67-c0be40a02eb8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dfba0d78-c941-4f1c-80e7-fe78db321f00', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'In Vasantha Surya''s lively story ''A Gift of Chappals'', who went to her aunt Rukku Manni''s house with her grandmother Tapi in Madras (Chennai)?', 'Young Mridu visits her aunt Rukku Manni''s house accompanied by her grandmother (Tapi).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1d10f7a-3c02-46e7-b461-1235326f93de', 'Mridu', true, 'dfba0d78-c941-4f1c-80e7-fe78db321f00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a24e0c0-def3-4a78-8e91-f89977713e88', 'Lalli', false, 'dfba0d78-c941-4f1c-80e7-fe78db321f00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12411cef-4dde-441b-a7df-0c92cbf4d6c5', 'Meena', false, 'dfba0d78-c941-4f1c-80e7-fe78db321f00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ba47868-01b1-48f7-951b-e2feab60c878', 'Rukku Manni', false, 'dfba0d78-c941-4f1c-80e7-fe78db321f00');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e11d0985-f485-411c-ac2b-3544058054a3', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'What did Ravi and Meena secretly show Mridu hidden inside a torn football lined with sacking in the backyard behind a bitter-berry bush?', 'Ravi and Meena harbored a secret stray kitten drinking milk from a coconut shell in the backyard.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a716088d-d39c-488c-82c7-0b34cf356bff', 'A tiny kitten lapping milk from a coconut half-shell', true, 'e11d0985-f485-411c-ac2b-3544058054a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f6bc696-461c-46bc-b1ce-f50f1345edba', 'A puppy', false, 'e11d0985-f485-411c-ac2b-3544058054a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1649a390-f550-40fd-bb86-de7972a97e69', 'A baby parrot', false, 'e11d0985-f485-411c-ac2b-3544058054a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('959297f4-a8ad-4de5-b89d-6c67c7548fa5', 'A treasure chest', false, 'e11d0985-f485-411c-ac2b-3544058054a3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52506f29-426b-410d-85e5-ea76c77ebe73', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'What grand, aristocratic name did Ravi give to the secret little kitten?', 'Ravi fancifully claimed the kitten was descended from the Pallava royal emblem: Mahendravarma Pallava Poonai (M.P. Poonai).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09109494-e5a2-4fe0-8508-8553563db422', 'Mahendravarma Pallava Poonai (M.P. Poonai / Mahendran for short)', true, '52506f29-426b-410d-85e5-ea76c77ebe73');
