INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a9cfe79-148e-4589-b7e7-69335962afb8', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'What musical instrument was Lalli struggling and screeching to play while taking music lessons from the music master?', 'Lalli was awkwardly learning to play the violin, making screeching ''kreech'' noises resembling a derailed train.', NOW()) ON CONFLICT DO NOTHING;
