INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('69929e26-5512-4835-a609-c810feda39c3', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'How did the author humorously describe the physical appearance of the bald-headed Music Master?', 'The music master is caricatured with a bony frame, oiled tuft, glistening diamond ring, and gold chain.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73ef39b1-16f0-464f-af56-433e94431839', 'A bony figure with a mostly bald head fringed with oiled black hair tied in an old-fashioned tuft, wearing a shining gold chain and diamond ring', true, '69929e26-5512-4835-a609-c810feda39c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14e066e3-94bd-4180-a923-fc20b4903a00', 'A giant man with a long white beard', false, '69929e26-5512-4835-a609-c810feda39c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf982323-3377-47c8-a24b-50ef9f669dff', 'A young boy with sunglasses', false, '69929e26-5512-4835-a609-c810feda39c3');
