INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('956fce0f-4fc1-4651-b5c0-a57a85fc4ca1', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'Why was the poor Beggar groaning and leaning against the neem tree in the garden?', 'Walking barefoot on sun-baked asphalt caused severe blisters on the impoverished beggar''s soles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f23cdb3-6c96-43cf-9bb7-1765b8d5d007', 'The scorching afternoon tar road was boiling hot and had caused painful, peeling pink blisters on the soles of his bare feet', true, '956fce0f-4fc1-4651-b5c0-a57a85fc4ca1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de460416-4345-4d4b-9884-79c1c709c8ac', 'Because he wanted to steal mangoes', false, '956fce0f-4fc1-4651-b5c0-a57a85fc4ca1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61851217-0c29-435c-9fd0-e92711caab92', 'Because he was singing a song', false, '956fce0f-4fc1-4651-b5c0-a57a85fc4ca1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87d91742-276d-4220-83ca-56d7813a1485', 'Because he lost his glasses', false, '956fce0f-4fc1-4651-b5c0-a57a85fc4ca1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a014f56c-6f51-4948-9643-7c7cf65fff0e', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'What did the compassionate children (Ravi, Meena, and Mridu) decide to give to the blistered barefoot beggar?', 'Pitying his blistered feet, the children gifted the music master''s sturdy chappals to the beggar.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5edd7403-cc3c-4dfe-a339-0d35f872d528', 'The large, grey, dusty pair of chappals lying near the verandah (which belonged to the Music Master)', true, 'a014f56c-6f51-4948-9643-7c7cf65fff0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86fec9d9-de7c-4c65-ab5c-21b94e0691f0', 'A bag of gold coins', false, 'a014f56c-6f51-4948-9643-7c7cf65fff0e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb4342b5-d3ab-48cb-b169-90e57395d5fe', 'A pair of roller skates', false, 'a014f56c-6f51-4948-9643-7c7cf65fff0e');
