INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1cebbe3d-f982-43db-b545-02351f8ce2ce', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'To pacify the furious, search-weary Music Master whose chappals had vanished, whose brand new chappals did Rukku Manni give to him?', 'Rukku Manni surrendered Gopu Mama''s pristine chappals to appease the aggrieved music teacher.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b582132c-4aa5-4178-93cf-6278aa09a747', 'Gopu Mama''s hardly-worn chappals', true, '1cebbe3d-f982-43db-b545-02351f8ce2ce');
