INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c65085b2-31a9-4bf7-8d21-4173626d136a', 'Paati''s sandals', false, '1cebbe3d-f982-43db-b545-02351f8ce2ce');
