INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4af4ee3-aa43-46df-9633-96c3ed68e05e', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'In D.J. Enright''s poem ''The Rebel'', what does the Rebel do when everybody else has short hair?', 'Enright contrasts non-conformist behavior: when others cut hair short, the rebel grows long hair.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e2bd4e0-08b5-4f36-a1b8-ef102184ddaa', 'The rebel lets his hair grow long', true, 'e4af4ee3-aa43-46df-9633-96c3ed68e05e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58a6fd4b-d971-49bf-b288-c2d7e3bf0246', 'He cuts his hair off completely', false, 'e4af4ee3-aa43-46df-9633-96c3ed68e05e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49b59848-e7e8-45fc-b712-611dc759f642', 'He paints his hair blue', false, 'e4af4ee3-aa43-46df-9633-96c3ed68e05e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('906794fc-bf5d-4309-b88c-80e9c708bca0', 'He wears a hat', false, 'e4af4ee3-aa43-46df-9633-96c3ed68e05e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ce1fd0da-3306-473c-9a6e-a1cfd83d6dc3', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'In ''The Rebel'', what does the Rebel express when everybody else is praising the bright warm Sun?', 'The rebel systematically seeks contrast: desiring rain during sunshine and sunshine during rain.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30d59e73-18e3-4447-8cc2-c26fca5f0868', 'The rebel remarks on the need for Rain', true, 'ce1fd0da-3306-473c-9a6e-a1cfd83d6dc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('026d51cb-1387-4aef-a4d2-e7d6563e00f5', 'The rebel wears sunglasses', false, 'ce1fd0da-3306-473c-9a6e-a1cfd83d6dc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e940c61b-b692-4273-9d18-ab2e57b4cdef', 'The rebel praises the moon', false, 'ce1fd0da-3306-473c-9a6e-a1cfd83d6dc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72d70284-7550-440a-a722-aca247665db1', 'The rebel stays asleep', false, 'ce1fd0da-3306-473c-9a6e-a1cfd83d6dc3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b4d3edd-29bc-473f-b584-6fda89fc9b83', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'What kind of sentence expresses a direct command, request, or advice (e.g. ''Don''t make that noise!'', ''Please give him chappals.'')?', 'Imperative sentences issue orders, prohibitions, entreaties, or instructional advice.', NOW()) ON CONFLICT DO NOTHING;
