INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cebcdac-dff8-4676-91c2-aeba673d7902', 'Interrogative Sentence', false, '2b4d3edd-29bc-473f-b584-6fda89fc9b83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac1e5ed6-ac55-46c5-8f42-d4109db2acbe', 'Exclamatory Sentence', false, '2b4d3edd-29bc-473f-b584-6fda89fc9b83');
