INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1dbe6945-84bc-4a04-a786-fd01a9d7687c', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Easy', 'What is the past continuous tense form of the verb ''dig'' for a plural subject (They)?', 'Past Continuous plural: were + verb-ing → ''were digging''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a7882a7-3b7a-4a8f-827d-3786d439ae6c', 'They were digging', true, '1dbe6945-84bc-4a04-a786-fd01a9d7687c');
