INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c274d0d-acd8-4c89-8ff9-4108de6ab85a', 'They are digging', false, '1dbe6945-84bc-4a04-a786-fd01a9d7687c');
