INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1f822747-e17a-4fad-ab3f-5ba0789fda38', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'How did Ravi cleverly smuggle milk from the kitchen for the secret kitten without Paati suspecting him?', 'Ravi staged drinking the milk under Paati''s watchful eye before dashing to feed the kitten.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fa0c17a-ba90-4a19-b25d-2ca6323f8577', 'He took milk in a glass, pretending he was very hungry; when Paati saw him, he drank most of it right in front of her to prove he was drinking it, ran out, poured the remaining milk into the coconut shell, and quickly washed the glass', true, '1f822747-e17a-4fad-ab3f-5ba0789fda38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55e97789-7f88-4aec-979c-53527fec367c', 'He bought milk from a store', false, '1f822747-e17a-4fad-ab3f-5ba0789fda38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc28b210-4699-40fe-99da-de2da7557183', 'He told Paati the truth directly', false, '1f822747-e17a-4fad-ab3f-5ba0789fda38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c5f3760-b8b2-417d-a022-69cfe24ca22d', 'He hid a cow in the garden', false, '1f822747-e17a-4fad-ab3f-5ba0789fda38');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9da5606-4fa1-44c3-a4e1-b7b5419a13e7', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'What humorous comparison did the author draw between the Music Master''s violin playing and Lalli''s violin playing?', 'Vasantha Surya contrasts the master''s melodic precision with Lalli''s discordant screeching derailments.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f3ae8f4-77c6-4d9c-ad52-94b24e1b6d36', 'The music master''s notes glided smoothly on melody tracks like a train on smooth rails, while Lalli went off the rails completely, screeching and derailing constantly', true, 'e9da5606-4fa1-44c3-a4e1-b7b5419a13e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d591a65-2137-4f23-906f-cfd153a45045', 'Lalli played better than the teacher', false, 'e9da5606-4fa1-44c3-a4e1-b7b5419a13e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2e9c428-ee86-45e7-801d-fae1097943c2', 'Both sounded like sweet singing birds', false, 'e9da5606-4fa1-44c3-a4e1-b7b5419a13e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dbdea1c-3bc2-4393-9f59-c1cc0fe30cec', 'Both played with their eyes closed', false, 'e9da5606-4fa1-44c3-a4e1-b7b5419a13e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f122cbde-3a63-450b-9352-dbe2dd860655', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'Why did Ravi argue with Rukku Manni about ''Karna'' from the Mahabharata when she scolded him for giving away the music master''s chappals?', 'Ravi pointed out adult moral contradiction: preaching the legendary charity of Karna while penalizing genuine compassionate giving.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('174c9365-9382-4acb-83b6-ee62e4a3e257', 'Ravi argued that adults always preach about being generous and giving to the needy like the great giver Karna, yet get angry when children actually practice true generosity', true, 'f122cbde-3a63-450b-9352-dbe2dd860655');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3198b552-e42b-4333-9318-cb34f0507503', 'Because Ravi wanted to become a king like Karna', false, 'f122cbde-3a63-450b-9352-dbe2dd860655');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1e917d4-8818-42fa-be8f-4b6d779dffa8', 'Because Karna was a music master', false, 'f122cbde-3a63-450b-9352-dbe2dd860655');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7797ebf9-6a37-4efb-99fb-6ae25884cc0a', 'Because Karna had chappals made of gold', false, 'f122cbde-3a63-450b-9352-dbe2dd860655');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d1b02de5-de89-431d-ab81-91e39278dd4f', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'How did Rukku Manni react after the Music Master left with Gopu Mama''s chappals when she thought of Gopu Mama coming home from office?', 'Rukku Manni''s exasperation melts into rueful humor anticipating Gopu Mama''s predictable evening reaction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bebc06c1-dc2e-4d6f-9e5c-a2b0b6a794f9', 'Her anger dissolved into laughter wondering what excuse she would give Gopu Mama, who always kicks off his shoes and wants his chappals the moment he enters the house', true, 'd1b02de5-de89-431d-ab81-91e39278dd4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36390f0d-4148-4e07-8c54-c81df676a7d8', 'She started crying loudly', false, 'd1b02de5-de89-431d-ab81-91e39278dd4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('084fef8f-2c78-4127-abc9-7dc0e53a7d26', 'She punished Ravi with no food', false, 'd1b02de5-de89-431d-ab81-91e39278dd4f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('119cafee-d882-4138-acaa-9ef836e1c49f', 'She chased the music master down the street', false, 'd1b02de5-de89-431d-ab81-91e39278dd4f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e47df864-fe0e-480c-89ae-8cbf0e0e278d', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'In ''The Rebel'', what social value or perspective does the poet conclude with regarding rebels in society?', 'Enright balances social utility with personal cost: non-conformity enriches cultural vitality but invites social friction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('595f3d7b-45bc-43ca-b25a-ca0ef88d1a90', 'It is good that we have rebels because they bring diversity and challenge rigid conformity, but it is not very good to BE one yourself because society often isolates and misunderstands them', true, 'e47df864-fe0e-480c-89ae-8cbf0e0e278d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66b02c30-1f6e-44aa-9c9c-7d63b87fd610', 'Rebels should all be put in prison', false, 'e47df864-fe0e-480c-89ae-8cbf0e0e278d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e094ff6-f3a9-4461-b4c5-a419ae09f049', 'Everyone must become a rebel', false, 'e47df864-fe0e-480c-89ae-8cbf0e0e278d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5e097f8-668c-4f58-836e-be8afc4970f5', 'Rebels are always evil', false, 'e47df864-fe0e-480c-89ae-8cbf0e0e278d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('af2a210c-3d92-4522-a3dd-fbed4e8ee82b', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Medium', 'Identify the correct meaning of the underlined idiom in: ''The music master''s eyes **lit up** when he saw Gopu Mama''s brand new chappals.''', '''Eyes lit up'' idiomatically conveys spontaneous delight and concealed covetousness.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('916ad7e8-be1d-4d1f-8bca-e57b21aa1160', 'Showed sudden, unmistakable delight, greed, and satisfaction', true, 'af2a210c-3d92-4522-a3dd-fbed4e8ee82b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf6bb363-7979-491e-8a4c-a9c40097ded9', 'Caught fire literally', false, 'af2a210c-3d92-4522-a3dd-fbed4e8ee82b');
