INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('668bc7d6-6a27-4c30-9d27-5ddbb111b14a', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Hard', 'Match Column I (Characters / Elements) with Column II (Contextual Actions in Chapter 2):
