INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a0ba153-48da-4aad-ae78-dabc0d13bbf9', 'The chappals were actually decrepit, faded grey with dust and toe-marks, but he exaggerated their value out of greedy vanity to demand a new replacement', true, 'c92aa35c-cd2c-462e-b9e6-396533cf5420');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a279997-b70c-427f-860b-e81c9199fe36', 'The chappals were made of pure platinum', false, 'c92aa35c-cd2c-462e-b9e6-396533cf5420');
