INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('610f6ca5-d9e9-4c2a-8064-92264deab163', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Hard', 'Which of the following demonstrates the correct use of INVERSION after a negative adverb in formal literary English?', 'Negative adverbial inversion: ''Hardly had [subject] [past participle] when...''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8adabc4e-da65-48fd-b18d-8aecbccab240', '''Hardly had the beggar sat down when Rukku Manni ordered him to leave.''', true, '610f6ca5-d9e9-4c2a-8064-92264deab163');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27f4b449-1018-4646-a07d-8a2e51c5b45d', '''Hardly the beggar had sat down when Rukku Manni ordered him.''', false, '610f6ca5-d9e9-4c2a-8064-92264deab163');
