INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3fc220bb-2a47-4349-acb0-4e77c7aeb6e8', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Hard', 'What humorous family dynamic is captured when Ravi says about Gopu Mama: ''He''s always in such a hurry to throw off his shoes and socks and get into his chappals as soon as he comes home''?', 'The detail grounds the climax in recognizable domestic realism, creating anticipatory comedic tension.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46170116-157a-4ef3-b983-e14741d3f953', 'The universal domestic habit of working adults shedding formal office attire for casual comfort, setting up the impending humorous confrontation', true, '3fc220bb-2a47-4349-acb0-4e77c7aeb6e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1af3338-2973-47d1-b36f-53ae8991fbf3', 'That Gopu Mama never goes to office', false, '3fc220bb-2a47-4349-acb0-4e77c7aeb6e8');
