INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d880b9d0-c245-436d-b195-987d4372ccee', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Hard', 'In ''The Rebel'', when everybody goes to the meeting, what does the Rebel do?', 'Textual line: ''When everybody goes to the meeting, / The rebel stays at home and reads a book''.', NOW()) ON CONFLICT DO NOTHING;
