INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5f4cf89-e78e-4ea4-ba65-4fac562b7380', 'Ravi argued that Karna had not given away other people''s things, but had given away what was his own.', true, 'c0d55db6-b21f-493a-acd9-184056ec606d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('566efcb4-8e18-42e5-8327-377b05a22fb8', 'Ravi says that Karna gives away other people''s things.', false, 'c0d55db6-b21f-493a-acd9-184056ec606d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cb9b458-ef79-4595-b694-00efed70d93a', 'Ravi asked why Karna gave away his own things.', false, 'c0d55db6-b21f-493a-acd9-184056ec606d');
