INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eccfb250-b86b-446c-ab53-412775f69655', 'Class 7', 'English', 'Chapter 2: A Gift of Chappals & The Rebel', 'Hard', 'What common ethical thread unites the narrative of ''A Gift of Chappals'' with the poetic philosophy of ''The Rebel''?', 'Both texts champion autonomous moral agency and empathetic non-conformity against rigid conventional orthodoxies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ba3a0c5-e66c-49eb-998e-837c16f53594', 'Both celebrate the courage of independent conscience—whether in children defying social norms to alleviate real suffering or in individuals resisting unthinking conformity', true, 'eccfb250-b86b-446c-ab53-412775f69655');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30a26e5e-b14d-4fd5-bf39-53a7a3fe37e5', 'Both advocate punishing all children', false, 'eccfb250-b86b-446c-ab53-412775f69655');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8813559-05e5-449a-87a0-368472e88577', 'Both state that music is unnecessary', false, 'eccfb250-b86b-446c-ab53-412775f69655');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f00830f-cb90-4c2c-a420-ff78d49ed48e', 'Both teach that one should never buy new shoes', false, 'eccfb250-b86b-446c-ab53-412775f69655');
