INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('187bc290-00e7-4d68-b9b3-470db84e9c99', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is the unique evolutionary feature of Monotremes (such as the Duck-billed Platypus and Echidna of Australia)?', 'Monotremes are oviparous (egg-laying) mammals possessing mammary gland milk secretion and cloacal anatomy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6587b983-e65f-4aed-a26f-5910c23685f1', 'They are the ONLY surviving mammals that lay EGGS instead of giving birth to live young, yet suckle their hatched young with mother''s milk', true, '187bc290-00e7-4d68-b9b3-470db84e9c99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5f7de81-7cf1-478d-93ea-9dfb18f6ff97', 'They have scales like fish', false, '187bc290-00e7-4d68-b9b3-470db84e9c99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d382437c-2d0c-4194-ac7c-e2cda13a1dd9', 'They can breathe underwater without lungs', false, '187bc290-00e7-4d68-b9b3-470db84e9c99');
