INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('29a4376c-dc77-417b-942b-918b2a91dd66', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is the unique biological feature of Marsupial mammals (such as Kangaroos, Koalas, and Wombats)?', 'Marsupials possess a short gestation period followed by post-natal lactation development inside a ventral pouch (marsupium).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01a7c5fb-cc69-449b-a98d-10525d1e4342', 'Females give birth to tiny, underdeveloped embryonic young that crawl into an external maternal abdominal pouch (Marsupium) to nurse and complete development', true, '29a4376c-dc77-417b-942b-918b2a91dd66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c5c27d4-1f68-4676-aa27-ce7ac443fd91', 'They can fly like eagles', false, '29a4376c-dc77-417b-942b-918b2a91dd66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37440c84-2121-4f71-a52d-15fe34dab309', 'They are cold-blooded like snakes', false, '29a4376c-dc77-417b-942b-918b2a91dd66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ac12d94-2fdb-4fb3-a114-ece806496737', 'They have blue fur', false, '29a4376c-dc77-417b-942b-918b2a91dd66');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4dae0cac-9cf9-46ac-bd01-4c38aa1ea4be', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is ''Echolocation'' used by Bats and Toothed Whales (Dolphins) to hunt prey and navigate in total darkness?', 'Biological sonar/echolocation computes spatial acoustic topographies from reflected ultrasonic wave reflections.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('724187f9-4370-4634-890a-4f173db2b3f8', 'Emitting high-frequency ultrasound sound pulses and listening to returning reflected echoes to calculate the exact distance, shape, and speed of objects', true, '4dae0cac-9cf9-46ac-bd01-4c38aa1ea4be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dead8041-2749-4d28-8436-420ffb71e76b', 'Using thermal heat vision', false, '4dae0cac-9cf9-46ac-bd01-4c38aa1ea4be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('580f01a2-6dc9-4b70-9254-6189131fe377', 'Smelling underwater', false, '4dae0cac-9cf9-46ac-bd01-4c38aa1ea4be');
