INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9050efcd-7997-4c1f-8764-325393a3ae23', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'Which marine reptile undertakes epic multi-thousand-kilometer trans-oceanic migrations to nest in millions simultaneously (''Arribada'') on the beaches of Gahirmatha and Rushikulya in Odisha?', 'Gahirmatha Marine Sanctuary in Odisha is the world''s largest mass-nesting rookery (Arribada) for Olive Ridley sea turtles.', NOW()) ON CONFLICT DO NOTHING;
