INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c42b438e-abca-415f-bb61-8f7655b828c4', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is the specialized physiological adaptation that allows Camels to survive weeks in scorching desert heat without drinking water?', 'Fat oxidation in humps, non-nucleated oval erythrocytes, high renal water reabsorption, and variable body temperature allow camel xerophilic survival.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a42ee53-d68a-409e-b8e4-101480fbb886', 'Storing energy-rich fat in their humps (which metabolizes into metabolic water and calories), having oval red blood cells that withstand dehydration, and minimizing sweat/urine loss', true, 'c42b438e-abca-415f-bb61-8f7655b828c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3426e9e4-c463-4f2e-a82c-58f778b82bc8', 'Storing 100 litres of liquid water in their stomach', false, 'c42b438e-abca-415f-bb61-8f7655b828c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('912e0751-616c-4660-857a-94b500135308', 'Drinking seawater directly', false, 'c42b438e-abca-415f-bb61-8f7655b828c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da1dc326-dbad-462e-a99d-a3a0bebd78a2', 'Sweating 50 litres of water an hour', false, 'c42b438e-abca-415f-bb61-8f7655b828c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('017195cc-310e-463d-892a-d1c7d5456943', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is the venomous snake in the world that builds dedicated leaf-litter nests to incubate its eggs, growing up to 5.5 metres long?', 'The King Cobra is the world''s longest venomous snake and the only snake that constructs dedicated botanical nests for maternal incubation.', NOW()) ON CONFLICT DO NOTHING;
