INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d398a63b-45ef-4e78-b55f-c8bf29e230d5', 'Russell''s Viper', false, '017195cc-310e-463d-892a-d1c7d5456943');
