INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9fc1916-a8a8-4af1-967b-7660ff7c4492', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is the specialized adaptation of the Arctic Polar Bear (Ursus maritimus) that keeps it warm in freezing sub-zero temperatures?', 'Subcutaneous blubber, dense underfur, hollow photon-scattering guard hairs, and melanin-rich black heat-absorbing epidermis insulate polar bears.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b7b78d5-37b5-4532-a4d7-ac2fe4e14b55', 'A thick 10 cm layer of insulating subcutaneous fat (blubber), two dense fur coats, and black skin underneath translucent hollow hair fibers that absorb solar heat', true, 'e9fc1916-a8a8-4af1-967b-7660ff7c4492');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78e77ea4-9332-4620-b1f9-490eb6949180', 'Feathers on its paws', false, 'e9fc1916-a8a8-4af1-967b-7660ff7c4492');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('345609bd-f771-43c9-b1d5-5542c846fabe', 'Drinking boiling water', false, 'e9fc1916-a8a8-4af1-967b-7660ff7c4492');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93945d2f-d34a-49c3-808a-14053adfd4b7', 'Sleeping for 10 years without waking', false, 'e9fc1916-a8a8-4af1-967b-7660ff7c4492');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8c34db10-9eba-4bd3-9b02-ab375d9bac8c', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'Which Indian state has the LARGEST number of wild Bengal Tigers according to the National Tiger Census (over 780 tigers)?', 'Madhya Pradesh leads national tiger counts with 785 tigers, earning its designation as the Tiger State of India.', NOW()) ON CONFLICT DO NOTHING;
