INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8adec52-6036-4bae-a795-f80f87894355', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is ''Coral Bleaching'' in ocean ecosystems?', 'Thermal ocean stress disrupts the mutualism between scleractinian corals and endosymbiotic zooxanthellae, resulting in bleaching.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8c9b23a-fd3d-4410-a98b-853221a5de3d', 'Rising sea water temperatures cause stressed coral polyps to expel their symbiotic photosynthetic algae (Zooxanthellae), turning corals ghostly white and risking mass mortality', true, 'e8adec52-6036-4bae-a795-f80f87894355');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('742bce1f-ca0a-4b7b-9b90-7e3d7250fc3b', 'Corals being painted with white bleach', false, 'e8adec52-6036-4bae-a795-f80f87894355');
