INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f93250ef-db38-40d7-8fc8-4fd0b76f9260', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is the ONLY species of deer in the world where both males and females grow branched antlers?', 'Reindeer (Rangifer tarandus) are unique among cervids in that both stags and hinds grow annual branched bone antlers.', NOW()) ON CONFLICT DO NOTHING;
