INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('00dfacb5-0568-400c-9c53-1f8c4535af44', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Medium', 'What is the famous national park in Karnataka, part of the Nilgiri Biosphere Reserve, renowned for having the largest wild Asian elephant concentration in Asia?', 'The contiguous Nagarhole-Bandipur-Mudumalai complex holds the highest global density of wild Asian elephants.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00d42240-f992-4d8d-9d80-102c7169e8b1', 'Nagarhole National Park (Rajiv Gandhi National Park) and Bandipur', true, '00dfacb5-0568-400c-9c53-1f8c4535af44');
