INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('83c14e39-7639-4b22-abdf-fe5139a6f57f', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'What is the international conservation convention CITES (Convention on International Trade in Endangered Species of Wild Fauna and Flora)?', 'CITES (1975) accords international trade protections across 38,000+ species via tiered Appendices (I, II, III).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33441aea-5b65-4b54-938d-5126e656600a', 'A legally binding global treaty regulating and banning commercial international trade in endangered wildlife specimens (ivory, tiger skins, rhino horns, exotic timber) to ensure species survival', true, '83c14e39-7639-4b22-abdf-fe5139a6f57f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19c5ca2e-b9dd-4c0b-87e3-82a317560dd1', 'A treaty that encourages hunting in all national parks', false, '83c14e39-7639-4b22-abdf-fe5139a6f57f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02078252-dd0d-40c0-ae44-1eb66fd7fb98', 'A convention that sells wild animals in markets', false, '83c14e39-7639-4b22-abdf-fe5139a6f57f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec54ebbc-9f0d-48bb-9f76-8c14ef30078a', 'A club of zoo owners', false, '83c14e39-7639-4b22-abdf-fe5139a6f57f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('766946fa-e4cf-46d8-9485-e9188fd38fec', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'Match Column I (Unique Animals) with Column II (Evolutionary Superpowers):
(a) Axolotl (Mexican Salamander) -> (i) Full regeneration of lost limbs, spinal cord & heart
(b) Tardigrade (Water Bear)       -> (ii) Survives vacuum of space, radiation & -200°C via cryptobiosis
(c) Immortal Jellyfish           -> (iii) Reverts adult medusa cells back to polyp stage endlessly
(d) Peregrine Falcon             -> (iv) Fastest dive speed on Earth (over 380 km/h)', 'Axolotl = limb regeneration; Tardigrade = extreme cryptobiosis; Turritopsis dohrnii = biological immortality; Peregrine = 380 km/h dive.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d42d04da-1f82-4a83-a21b-97142bb1c0b5', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '766946fa-e4cf-46d8-9485-e9188fd38fec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('247c1e0a-d048-4c7d-ac64-608188a282b0', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '766946fa-e4cf-46d8-9485-e9188fd38fec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdd82897-f5a3-473d-887b-b6401f41e49d', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '766946fa-e4cf-46d8-9485-e9188fd38fec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc0a7a9c-dce5-4b89-8868-3c5f30d9f1c3', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '766946fa-e4cf-46d8-9485-e9188fd38fec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('618470b6-659e-47b9-bb2a-ded07994d93d', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'Read the statements regarding biodiversity hotspots in India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51525a56-405c-4347-9910-06b39daf6158', 'Statements 1 and 2 only', true, '618470b6-659e-47b9-bb2a-ded07994d93d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9720116c-0f84-438b-81f1-81f11fa2d0ca', 'Statements 2 and 3 only', false, '618470b6-659e-47b9-bb2a-ded07994d93d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1da8fce8-ceb7-401f-8a0f-a66d96d11b1d', 'Statements 1 and 3 only', false, '618470b6-659e-47b9-bb2a-ded07994d93d');
