INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dda38ed9-db5b-433b-83eb-81e993d2829c', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'What is the unique deep-sea biological phenomenon where 90% of abyssal marine organisms generate their own cold biological light through the enzyme luciferase?', 'Bioluminescence oxidizes luciferin substrate catalyzed by luciferase, producing cold photon emission for communication and predation in dark depths.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('780c03ae-ece9-475c-8cc3-2f55c0f2dd29', 'Bioluminescence', true, 'dda38ed9-db5b-433b-83eb-81e993d2829c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3ca487f-9fec-4749-8aac-e3ca57cac26c', 'Photosynthesis', false, 'dda38ed9-db5b-433b-83eb-81e993d2829c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e27731b-b0c3-46a5-9255-239d2b2ef651', 'Chemosynthesis', false, 'dda38ed9-db5b-433b-83eb-81e993d2829c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4ebf687-3914-4b1a-a128-adb7dc37b3c8', 'Bioaccumulation', false, 'dda38ed9-db5b-433b-83eb-81e993d2829c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e9f995f-55af-47cc-a5df-1fda3d77d9a8', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'Why was the ''Bishnoi Community'' of Rajasthan historically celebrated for world-pioneering environmental martyrdom in 1730 at Khejarli?', 'In 1730, Amrita Devi and 363 Bishnoi martyrs gave their lives protecting Prosopis cineraria (Khejri) trees, inspiring the modern Chipko movement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('898b5b45-f2a0-4b72-a3c2-c808190de13a', 'Amrita Devi Bishnoi and 363 Bishnois sacrificed their lives hugging sacred Khejri trees to prevent them from being felled by royal soldiers', true, '9e9f995f-55af-47cc-a5df-1fda3d77d9a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff9642af-d54f-4d61-a9a9-d72eaf539cc9', 'They discovered diamond mines in the desert', false, '9e9f995f-55af-47cc-a5df-1fda3d77d9a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51fc69bb-04be-4de8-8169-302c2dbbd59c', 'They built the first zoo in India', false, '9e9f995f-55af-47cc-a5df-1fda3d77d9a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93c46665-8a2d-4e77-a14b-127ba35a305a', 'They invented solar powered cars', false, '9e9f995f-55af-47cc-a5df-1fda3d77d9a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('078ed4c0-10ec-4b3c-b72e-63bf18c7ea8f', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'What is the specialized migratory adaptation of the Arctic Tern (Sterna paradisaea) that makes it the champion world traveler?', 'The Arctic Tern completes the longest circumpolar pole-to-pole migration on Earth (~90,000 km annually).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e17918b-53a9-4c4c-b60a-bdcb8e97017c', 'It undertakes an annual round-trip migration of over 70,000 to 90,000 km between the Arctic and Antarctic, experiencing two summers a year', true, '078ed4c0-10ec-4b3c-b72e-63bf18c7ea8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f48ae518-4ac6-4da3-87a0-031e35f7d1b8', 'It flies to the moon and back', false, '078ed4c0-10ec-4b3c-b72e-63bf18c7ea8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e3fc063-4dc9-4936-b562-9760a7e24bf4', 'It swims across the bottom of the ocean', false, '078ed4c0-10ec-4b3c-b72e-63bf18c7ea8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0aa6310-b037-4ad1-8568-cc55962d5cd7', 'It stays asleep while flying for 20 years', false, '078ed4c0-10ec-4b3c-b72e-63bf18c7ea8f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10dd4df7-3261-492f-80ce-0e6fa9197b93', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'What is ''Biomagnification'' (Biological Magnification) in wildlife food chains?', 'Lipophilic xenobiotics resist metabolic breakdown, bio-accumulating exponentially toward apex trophic consumers (e.g. raptor eggshell thinning).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aef8ff53-44bc-47b5-89e1-2f93e6069ff1', 'The progressive increase in concentration of persistent toxic non-biodegradable chemicals (like DDT, heavy metals, microplastics) at each successively higher trophic level', true, '10dd4df7-3261-492f-80ce-0e6fa9197b93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9f35302-04b2-44dc-ae42-04e4ffb41d68', 'Animals growing bigger in size every year', false, '10dd4df7-3261-492f-80ce-0e6fa9197b93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5740804f-bdfe-4b5f-8bb5-9396ee59e789', 'Looking at animals through a giant magnifying glass', false, '10dd4df7-3261-492f-80ce-0e6fa9197b93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89dde118-066a-4100-acc9-c911324dd958', 'Plants producing double the flowers in spring', false, '10dd4df7-3261-492f-80ce-0e6fa9197b93');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5fe3144-b6c5-4d8b-804e-d0cbb96d9df7', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'What is the critically endangered avian raptor of India whose population plummeted by 99% due to toxic veterinary residues of the anti-inflammatory drug ''Diclofenac'' in cattle carcasses?', 'Diclofenac ingested from livestock carcasses caused catastrophic visceral gout and renal failure in Gyps vultures across South Asia.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7f79029-f5b0-4364-acb9-eebe65c2a724', 'Indian Vulture (Gyps indicus) and White-rumped Vulture', true, 'e5fe3144-b6c5-4d8b-804e-d0cbb96d9df7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b75c7afc-605b-45d2-b39a-539f314b9cfa', 'Great Indian Hornbill', false, 'e5fe3144-b6c5-4d8b-804e-d0cbb96d9df7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7026d1e6-9573-43b2-b072-5eba49b4fc85', 'Peregrine Falcon', false, 'e5fe3144-b6c5-4d8b-804e-d0cbb96d9df7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7de84435-fc32-4d61-998b-655f573dfded', 'Golden Eagle', false, 'e5fe3144-b6c5-4d8b-804e-d0cbb96d9df7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f49ed537-e1d2-4ce6-a047-e144768f357d', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'What is the unique ecosystem function performed by the ''Mangrove Sundari Trees'' in the Sundarbans against cyclones and tidal storm surges?', 'Rhizophora and Heritiera prop root lattices attenuate hydrodynamic kinetic energy from severe tropical cyclonic surges.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ac2ea5a-d179-4b3c-b4ef-7498e9d6c2e7', 'Their dense interlaced stilt and prop root systems dissipate up to 66% of cyclonic wave energy, acting as resilient bio-shields preventing coastal soil erosion', true, 'f49ed537-e1d2-4ce6-a047-e144768f357d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11c1879a-217e-4ecf-a008-fb52e44bfb0d', 'They produce poisonous gas against storms', false, 'f49ed537-e1d2-4ce6-a047-e144768f357d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f30cc54-494f-4ba2-9458-5487329fb1d1', 'They absorb all salt from the sea', false, 'f49ed537-e1d2-4ce6-a047-e144768f357d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0d41dcb-27dc-4347-a019-35142b351513', 'They make rain fall backwards', false, 'f49ed537-e1d2-4ce6-a047-e144768f357d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e60b085-7203-45df-9748-51bdd557daa4', 'Class 7', 'GK', 'Chapter 2: Animal Kingdom, Flora, Fauna & Global Wildlife Conservation', 'Hard', 'What ultimate moral and scientific mandate concludes our understanding of the Global Animal Kingdom and Wildlife Conservation?', 'Ecosystem stability and human biospheric survival depend directly on preserving biodiversity, genetic resilience, and ecological networks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39d3972e-9337-4215-b034-fb1d69b5c361', 'Biodiversity is the living life-support infrastructure of planet Earth; preserving intact habitats, ecological corridors, and endangered species is essential for the survival of human civilization itself', true, '5e60b085-7203-45df-9748-51bdd557daa4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d498702-635b-4073-8370-d8ce50a46128', 'Wild animals should be completely replaced by domesticated pets', false, '5e60b085-7203-45df-9748-51bdd557daa4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64da0f3a-39f0-4995-9b5d-cfcc3c78b350', 'Deforestation is necessary to eliminate all wild predators', false, '5e60b085-7203-45df-9748-51bdd557daa4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07c7c8d2-fe68-46cc-b582-db751085e198', 'Only animals useful to human commerce deserve protection', false, '5e60b085-7203-45df-9748-51bdd557daa4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d50aba8-c039-4344-bccb-acf8eb39afab', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Easy', 'In the 8th century, who was the Rashtrakuta chief who overthrew his Chalukya overlord and performed the famous ''Hiranya-garbha'' (Golden Womb) rebirth ritual to claim Kshatriya status?', 'Rashtrakuta chief Dantidurga performed the Hiranya-garbha ritual with Brahmana priests to ritually transform into a Kshatriya monarch.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdfbb766-5f11-428e-a515-e55cf57a74fd', 'Dantidurga', true, '8d50aba8-c039-4344-bccb-acf8eb39afab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6d822eb-68d1-4b42-b391-c2527484a1f9', 'Pulakeshin II', false, '8d50aba8-c039-4344-bccb-acf8eb39afab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1445b3a-c274-43c1-a490-d733b8fbfd28', 'Rajaraja I', false, '8d50aba8-c039-4344-bccb-acf8eb39afab');
