INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5f49380-001b-4e15-ad34-caad001fb0f3', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Easy', 'What does the Sanskrit term ''Hiranya-garbha'' literally translate to?', 'Hiranya (gold) + Garbha (womb) symbolizes ritual rebirth as an anointed Kshatriya ruler.', NOW()) ON CONFLICT DO NOTHING;
