INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d807e816-647a-4ce2-848a-45380a561df4', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Easy', 'Which three major medieval Indian dynasties fought the centuries-long famous ''Tripartite Struggle'' for control over the prized strategic city of KANNAUJ in the Gangetic valley?', 'The Tripartite Struggle pitted the Gurjara-Pratiharas (West/North), Palas (East/Bengal), and Rashtrakutas (Deccan) over Kannauj.', NOW()) ON CONFLICT DO NOTHING;
