INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('24a61c80-eb4f-44ca-b027-2bc59009f555', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Easy', 'Which famous Chahamana (Chauhan) ruler defeated the Afghan ruler Sultan Muhammad Ghori in the First Battle of Tarain in 1191 CE?', 'Prithviraja III defeated Muhammad Ghori at Tarain in 1191 CE (though lost the second battle in 1192 CE).', NOW()) ON CONFLICT DO NOTHING;
