INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a86a2c80-6119-49b0-9874-cca1b2256663', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Easy', 'Who was the founder of the Imperial Chola dynasty who captured the Kaveri delta from the Muttaraiyar chiefs in the middle of the 9th century and built Thanjavur?', 'Vijayalaya Chola captured Thanjavur (Tanjore) c. 850 CE, establishing the imperial Chola dynastic capital.', NOW()) ON CONFLICT DO NOTHING;
