INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f7d384e-cb1b-45cd-a7c5-56b4823678a4', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Easy', 'Who was considered the most powerful and celebrated Chola ruler, ascending the throne in 985 CE, who built the grand Brihadisvara Temple at Thanjavur?', 'Rajaraja I (r. 985–1014 CE) reorganized Chola administration, commanded powerful naval armadas, and built the colossal Brihadisvara Temple.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d46aca50-5a6f-45c1-93ff-2e869ec1cb71', 'Rajaraja I (Rajaraja Chola)', true, '2f7d384e-cb1b-45cd-a7c5-56b4823678a4');
