INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3594b013-db4b-40be-9e84-59bd0520d21e', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Easy', 'Which ambitious Chola king (son of Rajaraja I) marched his armies north to the Ganga river, built the magnificent new capital ''Gangaikondacholapuram'', and launched naval expeditions to conquer Srivijaya (Southeast Asia)?', 'Rajendra I assumed the title ''Gangaikondachola'' (Conqueror of the Ganga) and founded Gangaikondacholapuram in 1025 CE.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe133215-2cf7-4412-ac09-d7a7cda7537e', 'Rajendra I', true, '3594b013-db4b-40be-9e84-59bd0520d21e');
