INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e10f23e4-98e1-4937-af68-6be7fdfcf88c', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Easy', 'What world-renowned fine metallic art form reached its supreme zenith of aesthetic elegance during the Chola period (such as the famous dancing Nataraja Shiva)?', 'Chola cire-perdue (lost-wax) bronze sculptures, particularly the Nataraja cosmic dancer, are celebrated among the finest in world art.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35fe1284-1db4-4f2d-af67-bdada6e94564', 'Chola Lost-Wax Bronze Sculptures', true, 'e10f23e4-98e1-4937-af68-6be7fdfcf88c');
