INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b223570-f21f-4f89-a0dc-72173556e616', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Easy', 'In Chola rural administration, what was a settlement / village assembly of peasant cultivators called?', 'The ''Ur'' was the autonomous village assembly of non-Brahmana peasant landholders in the Chola realm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b457ea18-4310-4657-b12d-78e66acb1f15', 'Ur', true, '2b223570-f21f-4f89-a0dc-72173556e616');
