INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07958619-543c-4c97-863c-334bf86382f5', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Easy', 'In Chola administration, what was an assembly of prominent Brahmana landholders governing a Brahmadeya (tax-free land grant) village called?', 'The ''Sabha'' was the democratic council of learned Brahmana landholders managing Brahmadeya villages through specialized committees.', NOW()) ON CONFLICT DO NOTHING;
