INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('671906ab-2065-4ec4-a2e3-0b7d811d27be', 'Nagaram', false, '07958619-543c-4c97-863c-334bf86382f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c39b84f-0617-4f37-93a2-7957df6c8383', 'Valanadu', false, '07958619-543c-4c97-863c-334bf86382f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e47efd3-5505-4eb2-bcf7-6e17e3d850d2', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Easy', 'Which famous Tamil Nadu temple inscription in Kanchipuram district provides detailed, exact rules and democratic lottery qualification procedures for election to the Sabha committees?', 'The 10th-century Parantaka I Uttaramerur inscriptions lay down precise democratic eligibility criteria and the pot-lottery (Kudavolai) voting system.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4714f99f-a45f-42ab-9f11-4e2c091f9f39', 'Uttaramerur Inscription', true, '2e47efd3-5505-4eb2-bcf7-6e17e3d850d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('433ec4c7-cf42-4a4a-a66e-8103d0e7746b', 'Aihole Inscription', false, '2e47efd3-5505-4eb2-bcf7-6e17e3d850d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bf7c308-67c4-4f05-8f65-df6b3df5502e', 'Prayag Prashasti', false, '2e47efd3-5505-4eb2-bcf7-6e17e3d850d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db53e759-f1d8-4d5c-94f0-a646dc42b30f', 'Hathigumpha Inscription', false, '2e47efd3-5505-4eb2-bcf7-6e17e3d850d2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96022d66-0ef0-4e62-987d-8bbd1924675a', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'How did Kadamba Mayurasharman and Gurjara-Pratihara Harichandra establish their royal dynasties in Karnataka and Rajasthan despite being Brahmanas by birth?', 'Brahmana chiefs Mayurasharman and Harichandra abandoned sacerdotal duties, taking up arms to establish Kadamba and Pratihara kingdoms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6158e367-5709-4d5e-85b2-6c092fe99a3a', 'They gave up their traditional priestly vocations, took up arms and military warfare, and successfully carved out independent sovereign kingdoms by force', true, '96022d66-0ef0-4e62-987d-8bbd1924675a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96370a9f-7de1-4121-9a3d-e70b5f82edd8', 'They were crowned by Roman emperors', false, '96022d66-0ef0-4e62-987d-8bbd1924675a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5227715-830d-4f87-9a4b-1859f7c0082c', 'They inherited the kingdoms from Buddhist monks', false, '96022d66-0ef0-4e62-987d-8bbd1924675a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f459d86-1ef8-4516-bb46-a162fdc54805', 'They purchased the land with Greek gold', false, '96022d66-0ef0-4e62-987d-8bbd1924675a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0e5b4662-cf61-46ef-a963-28ec8601659c', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'What was the ''Kudavolai'' system of democratic committee selection recorded in the Uttaramerur inscription of the Cholas?', 'The Kudavolai pot-lottery system selected committee members (Variyams) for irrigation, gardens, and temples via blind ballot draws.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad24d7cc-ef95-48f7-8b5b-e4e7cd20fa1e', 'Names of eligible candidates were written on palm-leaf tickets, placed in an earthenware pot, and a young boy was asked to pick tickets one by one to form specialized governing committees (Variyams)', true, '0e5b4662-cf61-46ef-a963-28ec8601659c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9d871d2-9ed9-4256-a8b2-a317b71b8ec7', 'Candidates fought a sword duel', false, '0e5b4662-cf61-46ef-a963-28ec8601659c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('116c6123-f6ba-4c04-a7f4-efab0d4b9a0a', 'The King chose his family members only', false, '0e5b4662-cf61-46ef-a963-28ec8601659c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d405889a-854a-49aa-a782-22b1effdc4b6', 'People raised hands in a large stadium', false, '0e5b4662-cf61-46ef-a963-28ec8601659c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dcc6f612-1bbe-44bc-a707-933ba29eaf06', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'What rigorous eligibility criteria were mandated for a candidate to contest election to the Chola Sabha committees at Uttaramerur?', 'Uttaramerur rules: age 35–70, Vedic literacy, property ownership, financial integrity, and mandatory 3-year term rotation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a991e717-8463-47f3-8085-df4fbf3038f0', 'Must own tax-paying land, have a private house, be aged 35–70, possess knowledge of the Vedas, be honest, and must NOT have served on any committee in the previous 3 years', true, 'dcc6f612-1bbe-44bc-a707-933ba29eaf06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fb3eb1f-ca3e-4732-a3bd-8d625d937b0e', 'Must be the richest merchant in the city', false, 'dcc6f612-1bbe-44bc-a707-933ba29eaf06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4d8dfae-a4af-4ed2-80f9-899fa2f685c5', 'Must have won at least 10 wars', false, 'dcc6f612-1bbe-44bc-a707-933ba29eaf06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72b94379-fb85-4438-951b-74493713be7f', 'Must be a relative of the King', false, 'dcc6f612-1bbe-44bc-a707-933ba29eaf06');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a2a33454-6776-41a6-9c08-282b87fd9698', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'Why was Kalhana''s Sanskrit historical chronicle ''Rajatarangini'' unique and remarkably distinct from typical contemporary court Prashastis?', 'Kalhana practiced critical historiography: cross-examining multiple epigraphic sources and offering candid critiques of royal misrule.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ace23a86-d8bf-43a8-a9e2-6de96ab11118', 'Unlike eulogistic court poets who only praised monarchs, Kalhana critically analyzed inscriptions, coins, and earlier chronicles, openly criticizing rulers for bad policies and unjust governance', true, 'a2a33454-6776-41a6-9c08-282b87fd9698');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc6d4574-37fb-452f-907b-e868fbe5669e', 'Because it was written in Persian poetry', false, 'a2a33454-6776-41a6-9c08-282b87fd9698');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bbc957f-f25e-4e4b-9c9e-b25ea98c18a8', 'Because Kalhana was an Arab cartographer', false, 'a2a33454-6776-41a6-9c08-282b87fd9698');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b20a0b05-f480-4f54-ae3a-6925cf0c970a', 'Because it contains only fictional fairy tales', false, 'a2a33454-6776-41a6-9c08-282b87fd9698');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2dae163a-6f3d-497e-a105-e747ce5af226', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'Why did Mahmud of Ghazni (ruler of Ghazni, Afghanistan) repeatedly raid and plunder wealthy northern Indian temple cities (such as Somnath in Gujarat) between 1000 and 1025 CE?', 'Mahmud of Ghazni raided temple treasuries (Somnath 1026 CE) to finance Central Asian military expansions and embellish Ghazni.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eda6f98d-f825-4da6-a05c-a177078e143d', 'To loot immense accumulated gold and diamond temple wealth to finance his imperial campaigns, armies, and grand capital city of Ghazni in Central Asia', true, '2dae163a-6f3d-497e-a105-e747ce5af226');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71352add-56fe-40a0-abfe-37b251eb2621', 'To build Hindu temples in Afghanistan', false, '2dae163a-6f3d-497e-a105-e747ce5af226');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99e953a5-b1e9-40ed-b70b-d8134c4d53f3', 'To settle down as a farmer in Gujarat', false, '2dae163a-6f3d-497e-a105-e747ce5af226');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2711f9d9-7fd6-4084-a196-0ea69864e621', 'To study Sanskrit literature in Varanasi', false, '2dae163a-6f3d-497e-a105-e747ce5af226');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8813b12-3686-4e93-acdc-2919033a09f3', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'Who was the profound Persian scholar and polymath whom Mahmud of Ghazni brought to India to study Indian culture, who authored the definitive encyclopedic work ''Kitab al-Hind''?', 'Al-Biruni mastered Sanskrit and consulted Brahmana pandits to author ''Kitab al-Hind'' (1030 CE), a masterwork on Indian science, religion, and philosophy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21e3c83d-86b0-4bc2-a039-c6953b941607', 'Al-Biruni (Abu Rayhan al-Biruni)', true, 'c8813b12-3686-4e93-acdc-2919033a09f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d72799a0-1622-48e3-aa09-9b11735d7430', 'Ibn Battuta', false, 'c8813b12-3686-4e93-acdc-2919033a09f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f8fc0eb-e8fc-4207-a08f-58122f4c2783', 'Ziauddin Barani', false, 'c8813b12-3686-4e93-acdc-2919033a09f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43fb4879-c251-4f60-8132-d1893a8cb525', 'Amir Khusrau', false, 'c8813b12-3686-4e93-acdc-2919033a09f3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ab83d85-3ae1-45db-9354-378a477af8aa', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'What agricultural and hydraulic revolution engineered by the Cholas transformed the Kaveri delta into the granary of South India?', 'Chola hydraulic engineering: sluices, bunds, inter-connected irrigation canals, and community rainfed tanks (eris) yielding 2–3 rice crops annually.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cff875b8-f70b-41ff-9b4e-de4fe0421dad', 'Constructing massive river embankments to prevent flooding, digging extensive canal networks to channel Kaveri waters directly into paddy fields, and building enormous water storage tanks (Eris)', true, '6ab83d85-3ae1-45db-9354-378a477af8aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('660d6e4d-a2ab-4291-835f-6e37dc601a8d', 'Spraying chemical fertilizers imported from China', false, '6ab83d85-3ae1-45db-9354-378a477af8aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8db3bdae-7a0f-46e5-835b-f79a32b377f7', 'Building glass greenhouses across all farms', false, '6ab83d85-3ae1-45db-9354-378a477af8aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e01842c3-c88f-49e8-97bb-f31934dfbd05', 'Planting only wheat in coastal mud', false, '6ab83d85-3ae1-45db-9354-378a477af8aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4cd625e8-dba9-4903-915e-c3d09494fa0d', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'In Chola inscriptions, what did the term ''Brahmadeya'' signify?', 'Brahmadeya was revenue-exempt land granted by monarchs to Brahmanas to promote Vedic learning and agricultural settlement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14255122-6c1c-4d65-91c8-72be60661c64', 'Tax-free agricultural land gifted as a royal endowment to learned Brahmanas', true, '4cd625e8-dba9-4903-915e-c3d09494fa0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ab0ae0b-5ab0-436c-b6d8-5c41c70db8dc', 'Land gifted to military generals', false, '4cd625e8-dba9-4903-915e-c3d09494fa0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20938ab1-5231-4e77-85e0-8d95c77722a3', 'Land belonging to non-Brahmana peasants', false, '4cd625e8-dba9-4903-915e-c3d09494fa0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('356fc333-d58f-4727-8cc1-afe274d8e94d', 'Land maintained for royal hunting', false, '4cd625e8-dba9-4903-915e-c3d09494fa0d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a24f12c-2994-45f7-a32e-a02670d6054b', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'What were the administrative territorial divisions in the Chola Empire called (from largest to smallest)?', 'Chola administrative hierarchy: Mandalam (province) → Valanadu (district) → Nadu (taluk/village cluster) → Grama/Ur (village unit).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a048f8d9-f364-4d0f-95d0-94b771d601f6', 'Mandalams (Provinces) -> Valanadus (Districts) -> Nadus (Groups of villages) -> Grama / Ur (Village)', true, '8a24f12c-2994-45f7-a32e-a02670d6054b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39818619-fcc0-43da-aa17-dc3d3b8c7aab', 'States -> Cities -> Towns -> Houses', false, '8a24f12c-2994-45f7-a32e-a02670d6054b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6fa0393-47d5-48e9-bf8d-d085bfb7301c', 'Janapadas -> Mahajanapadas -> Empires', false, '8a24f12c-2994-45f7-a32e-a02670d6054b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14ed6045-9566-484e-8a15-8e0c4042cf0c', 'Subas -> Sarkars -> Parganas', false, '8a24f12c-2994-45f7-a32e-a02670d6054b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f098555-8d08-4514-9449-251bef45c0d4', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'In the 400 different tax terms recorded in Chola inscriptions, what was ''Vetti'' and ''Kadamai''?', 'Chola fiscal records (e.g. Thanjavur): Vetti represented uncompensated corvée forced labor, while Kadamai was agricultural land revenue.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9b2d4ed-7002-477a-b97b-13e3602a0532', '''Vetti'' was tax taken not in cash but in the form of FORCED LABOUR ; ''Kadamai'' was land revenue tax', true, '4f098555-8d08-4514-9449-251bef45c0d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d08cb872-0b80-48cd-b3a2-8fdb198b41ea', '''Vetti'' was a tax on horses ; ''Kadamai'' was a tax on houses', false, '4f098555-8d08-4514-9449-251bef45c0d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccc0f973-dd32-47eb-8f26-db1a5f97206e', '''Vetti'' was tax on gold ; ''Kadamai'' was tax on silk', false, '4f098555-8d08-4514-9449-251bef45c0d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4f79023-d02f-4ec6-9b3b-8d1b774c095d', 'Both were voluntary donations', false, '4f098555-8d08-4514-9449-251bef45c0d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3dafe583-daed-4452-baf7-b516a09708fd', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'What happened to the Gurjara-Pratiharas, Rashtrakutas, and Palas at the end of the long Tripartite Struggle?', 'Protracted attrition over Kannauj drained the treasuries of all three empires, fragmenting northern and peninsular India into smaller Rajput and Deccan states.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47ad6866-3b6c-49ba-88a6-42f582d665c7', 'All three dynasties exhausted their military and economic resources in continuous war, leading to their mutual decline and replacement by feudatories (like Chauhans, Paramaras, Senas)', true, '3dafe583-daed-4452-baf7-b516a09708fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f316bbda-cfe1-49c8-abe1-fde622c39aad', 'They formed a single combined world empire', false, '3dafe583-daed-4452-baf7-b516a09708fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0802f1bb-8b29-43e4-b5dd-77c4397c7e0e', 'They ruled India together until the 19th century', false, '3dafe583-daed-4452-baf7-b516a09708fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a03d90a7-996a-467c-b223-f98dfac8c03f', 'They all migrated to Rome', false, '3dafe583-daed-4452-baf7-b516a09708fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4f2cebf-6a5a-486e-b944-f4eab2bb8ff0', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'What grand titles did powerful medieval monarchs adopt to display imperial sovereignty (e.g. Tribhuvana-chakravartin)?', 'Medieval monarchs adopted grandiloquent imperial epithets (Maharajadhiraja, Tribhuvana-chakravartin) to project absolute cosmological authority.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad80cc26-d62b-4722-a965-50a760faab41', 'Maharajadhiraja (Great King of Kings) and Tribhuvana-chakravartin (Lord of the Three Worlds)', true, 'f4f2cebf-6a5a-486e-b944-f4eab2bb8ff0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bb3cff4-892f-468f-923c-7cefe3c26369', 'Raja only', false, 'f4f2cebf-6a5a-486e-b944-f4eab2bb8ff0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('befe97ac-5d03-4a2b-ad49-f2916c67b30e', 'Samanta', false, 'f4f2cebf-6a5a-486e-b944-f4eab2bb8ff0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('558ebdbc-8d4e-436a-8b17-f6b16fad14f2', 'Gramani', false, 'f4f2cebf-6a5a-486e-b944-f4eab2bb8ff0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f306265-ce99-4273-b448-b87d6f5dbe63', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'In Chola land classification, what was ''Vellanvagai'' land?', 'Vellanvagai designated agricultural land holdings belonging to non-Brahmana Vellalar peasant proprietors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02a34f79-a0d3-4a7b-ad6c-4b833372624a', 'Land of non-Brahmana peasant proprietors', true, '7f306265-ce99-4273-b448-b87d6f5dbe63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd78a3a2-4a77-4742-a2cd-25934d905771', 'Land gifted to temples', false, '7f306265-ce99-4273-b448-b87d6f5dbe63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19deea6e-7b1f-4a14-8f6d-b55e44002f3c', 'Land for maintenance of schools', false, '7f306265-ce99-4273-b448-b87d6f5dbe63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f54f08e4-17fa-4fa4-a5fb-fa91cef7e126', 'Land gifted to Jain institutions', false, '7f306265-ce99-4273-b448-b87d6f5dbe63');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8e175da-6bc4-4fc1-b1d6-12137e86f074', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'In Chola land classification, what was ''Shalabhoga'' land?', '''Shala'' (school) + ''Bhoga'' (endowment): Shalabhoga was land reserved exclusively to fund educational academies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87a2bf4a-5260-4204-8db5-38fecb45da56', 'Land granted for the maintenance of a school (shala)', true, 'c8e175da-6bc4-4fc1-b1d6-12137e86f074');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a431933a-cb9f-4d3f-b0d2-3f058115e8c4', 'Land gifted to temples', false, 'c8e175da-6bc4-4fc1-b1d6-12137e86f074');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d283b147-18f8-45b2-b3d2-e93ab584b867', 'Land for cattle grazing', false, 'c8e175da-6bc4-4fc1-b1d6-12137e86f074');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ce648b6-7d1f-40c1-808c-3ed12cb3c7b1', 'Land given to palace cooks', false, 'c8e175da-6bc4-4fc1-b1d6-12137e86f074');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f641490-c3be-4a7a-b37a-5b0e5b5d3296', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'In Chola land classification, what was ''Devadana'' (or Tirunamattukkani)?', 'Devadana (gift to gods) lands generated perennial revenue to maintain temple rituals, priests, musicians, and festivals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e36c104-eb92-4dfe-863a-af6975bf416f', 'Land gifted directly to temples as sacred endowments', true, '7f641490-c3be-4a7a-b37a-5b0e5b5d3296');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff04c42b-2d56-409b-930f-fa6d9769e901', 'Land gifted to soldiers', false, '7f641490-c3be-4a7a-b37a-5b0e5b5d3296');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0620874-785c-4853-bb1e-b2550f753ebf', 'Land belonging to the king', false, '7f641490-c3be-4a7a-b37a-5b0e5b5d3296');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b72c143f-706f-4bb0-9181-a63a91163878', 'Forest land', false, '7f641490-c3be-4a7a-b37a-5b0e5b5d3296');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a121993c-2dfc-4767-8f48-310ef0e4914e', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Medium', 'What was ''Pallichchhandam'' in Chola land grants?', 'Pallichchhandam represented tax-free land endowments donated to support Jain monastic establishments (basadis).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0ad1908-ea01-49b7-a2f1-a86e615dca11', 'Land donated to Jaina institutions and basadis', true, 'a121993c-2dfc-4767-8f48-310ef0e4914e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1bf17cc-0df6-4735-9609-b58d7622b146', 'Land for Buddhist stupas', false, 'a121993c-2dfc-4767-8f48-310ef0e4914e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('440515ce-9a93-4ee1-89a1-80bf4ffd2a82', 'Land for building roads', false, 'a121993c-2dfc-4767-8f48-310ef0e4914e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc7c962f-822d-49af-a83f-c834debfb6a8', 'Land for royal stables', false, 'a121993c-2dfc-4767-8f48-310ef0e4914e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('312aaf9d-389f-4fef-a040-dfc6c578cccd', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d45178b-9a6e-47c5-b4f0-d027890dd0ee', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '312aaf9d-389f-4fef-a040-dfc6c578cccd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09c300a3-3e2c-459c-a10c-842a1ff98ecc', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '312aaf9d-389f-4fef-a040-dfc6c578cccd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a73f7b69-cd64-4402-a8f7-5cbc9bc37348', '(A) is true, but (R) is false.', false, '312aaf9d-389f-4fef-a040-dfc6c578cccd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a66817cc-f1dd-4749-bbf8-27fbada073c0', '(A) is false, but (R) is true.', false, '312aaf9d-389f-4fef-a040-dfc6c578cccd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('434615f8-daeb-43d6-ba01-fc74893b8e34', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'Spot the IMPOSTER in the following group of early medieval dynasties matched with their core geographical heartlands:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62d9bf86-d062-4161-b7b6-08028fa96663', 'Match 1', false, '434615f8-daeb-43d6-ba01-fc74893b8e34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b0cf54c-1fe5-4890-a6b0-4ca142b58bcd', 'Match 2', false, '434615f8-daeb-43d6-ba01-fc74893b8e34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15db9db8-2ae7-4441-bbcb-d9c8653a94dc', 'Match 3', false, '434615f8-daeb-43d6-ba01-fc74893b8e34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a09037b-6da2-4c49-880a-09795672da08', 'Match 4 (Cholas ruled the Kaveri Delta and Tamil Country in South India, NOT Punjab/Kashmir)', true, '434615f8-daeb-43d6-ba01-fc74893b8e34');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d7885ba-7080-441d-a8f4-751bb17f669b', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'Analyze the ''Lost-Wax Technique'' (Cire Perdue) perfected by Chola master bronze craftsmen:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28e29840-f798-4762-b869-5b1115a55310', 'Sculpt a detailed beeswax model -> coat with fine clay & dry -> heat to melt and drain wax out through a hole -> pour molten bronze into the hollow clay mold -> cool and break clay casing to polish the bronze statue', true, '4d7885ba-7080-441d-a8f4-751bb17f669b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ecd30a3-f815-4cb3-9509-d689631600dd', 'Carve bronze with a hammer directly from stone', false, '4d7885ba-7080-441d-a8f4-751bb17f669b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9151e82e-b7a2-4012-9aab-ada31e28a5b1', 'Pour cold water on hot copper sheets', false, '4d7885ba-7080-441d-a8f4-751bb17f669b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f99504af-c64c-4130-b872-4a1bb1d1657a', 'Dip wooden statues into gold paint', false, '4d7885ba-7080-441d-a8f4-751bb17f669b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e7dd468b-74ca-49ca-a056-7090b34d0900', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'Match Column I (Chola Land Terms) with Column II (Exact Definitions from Inscriptions):
(a) Vellanvagai    -> (i) Land of non-Brahmana peasant proprietors
(b) Brahmadeya      -> (ii) Land gifted to Brahmanas
(c) Shalabhoga      -> (iii) Land for the maintenance of a school
(d) Pallichchhandam -> (iv) Land donated to Jaina institutions', 'Vellanvagai = peasant land; Brahmadeya = Brahmana grant; Shalabhoga = school; Pallichchhandam = Jain grant.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d934f58-6232-4028-b0bb-febacdbdd5f1', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'e7dd468b-74ca-49ca-a056-7090b34d0900');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43a4c811-d386-4696-9afe-b678e540df24', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'e7dd468b-74ca-49ca-a056-7090b34d0900');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da060155-60fd-405a-844f-abf7ddc47b68', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'e7dd468b-74ca-49ca-a056-7090b34d0900');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd93fb1d-910c-4a4b-9765-c32d11472cd0', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'e7dd468b-74ca-49ca-a056-7090b34d0900');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('72fff6b3-255d-4f82-b612-c700078552f2', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'Read the statements regarding the Battle of Tarain:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4253782-0189-4a41-8064-9168300bcfa9', 'Statements 1 and 2 only', true, '72fff6b3-255d-4f82-b612-c700078552f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9574933a-4f67-4625-9b23-f1be621ad003', 'Statements 2 and 3 only', false, '72fff6b3-255d-4f82-b612-c700078552f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3103ace-d7b6-43c9-afb1-e3f4d72436e0', 'Statements 1 and 3 only', false, '72fff6b3-255d-4f82-b612-c700078552f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b0ebd69-1198-41de-a077-cd3b5946a668', 'All Statements 1, 2, and 3', false, '72fff6b3-255d-4f82-b612-c700078552f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f7ccae1b-c72d-4634-ae1d-858eb7826a4b', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'Why did medieval kings deliberately build colossal, soaring stone temples and adorn them with lavish gold and jewel endowments?', 'Monumental temple patronage legitimized royal sovereignty, embodying divine kingship and cementing fiscal-agrarian hegemony.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd51e799-13d6-4e62-97de-5faf5b8eab4e', 'To proclaim their supreme wealth, imperial power, piety, and divine sanction, while creating economic patronage networks with local elites', true, 'f7ccae1b-c72d-4634-ae1d-858eb7826a4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddd49fbc-53a9-4fd6-b056-dafa6d60f107', 'Because temples were used as prisons for soldiers', false, 'f7ccae1b-c72d-4634-ae1d-858eb7826a4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea3f73f8-f841-4abb-91d2-2968d1b0240b', 'Because stone was the only building material available', false, 'f7ccae1b-c72d-4634-ae1d-858eb7826a4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e2ee882-a57f-470f-888a-508bdb7513e7', 'To hide from invading foreign armies', false, 'f7ccae1b-c72d-4634-ae1d-858eb7826a4b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18e0c0bd-48d5-441e-8fd4-081e34734e7f', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'How did the Chola navy under Rajaraja I and Rajendra I achieve maritime hegemony across the Bay of Bengal (often called the ''Chola Lake'')?', 'Chola blue-water thalassocracy secured maritime trade networks across the Malacca Straits, trading with Song Dynasty China.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('390967ab-083e-4faf-953e-fcb6ed437c6f', 'They constructed a powerful high-seas naval fleet that conquered the Maldives, Sri Lanka, and launched maritime expeditions against the Srivijaya Empire (Sumatra/Malaysia) to protect strategic trade routes to China', true, '18e0c0bd-48d5-441e-8fd4-081e34734e7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd7c5fa8-620e-484b-aa79-d1eac2aadff5', 'They hired European pirate ships', false, '18e0c0bd-48d5-441e-8fd4-081e34734e7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a53b03b-5e52-4ce6-84c0-961630de0a0d', 'They built bridges across the entire ocean', false, '18e0c0bd-48d5-441e-8fd4-081e34734e7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b166d65-c5f2-403d-92a3-772308bcc939', 'They drained the Bay of Bengal', false, '18e0c0bd-48d5-441e-8fd4-081e34734e7f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4734baa3-bbaa-49d5-a5f6-020870bc9ef8', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'What democratic safeguard was enforced in the Uttaramerur Sabha election rules to prevent corruption, dynastic entrenchment, and power abuse?', 'Mandatory 3-year term limits and strict financial account auditing barred entrenched dynastic oligarchies in the Sabha.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a09f528-8d44-4b89-954c-24f2d939854e', 'Anyone who had been a member of any committee for the past 3 years, or who had failed to submit full audited financial accounts of his past committee tenure, was STRICTLY DISQUALIFIED from contesting', true, '4734baa3-bbaa-49d5-a5f6-020870bc9ef8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e4de0e8-cde5-44e7-9b11-cfbd3b0d94f2', 'Candidates had to pay 100 gold coins to vote', false, '4734baa3-bbaa-49d5-a5f6-020870bc9ef8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07dd0d4c-8277-48ee-ab2f-da78209ff124', 'Only the oldest man in the village could rule', false, '4734baa3-bbaa-49d5-a5f6-020870bc9ef8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bda4c10d-5a72-489b-9eb9-14e7ac6627fc', 'Votes were decided by sword fighting', false, '4734baa3-bbaa-49d5-a5f6-020870bc9ef8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('348a76af-001a-4984-b810-cb4ec2b3a8a6', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'Consider four prominent rulers of early medieval India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f57cc936-ae6b-4818-83e2-acd8b9f9c9ba', 'Ruler 3 (Rajendra I Chola)', true, '348a76af-001a-4984-b810-cb4ec2b3a8a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0ce9af5-3509-43d5-8f7e-9d51e55f47b5', 'Ruler 1', false, '348a76af-001a-4984-b810-cb4ec2b3a8a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cecdb26c-83d6-4146-a845-10eab0bc1e27', 'Ruler 2', false, '348a76af-001a-4984-b810-cb4ec2b3a8a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd77437c-f4bf-48a2-84cb-a8cb61a19cf7', 'Ruler 4', false, '348a76af-001a-4984-b810-cb4ec2b3a8a6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74cc0756-7993-4422-bd30-bfa170d4aeb5', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'What was the role of the ''Nagaram'' in the Chola imperial commercial economy?', 'Nagarams (like Ayyavole and Manigramam guilds) managed civic urban commerce, merchant law, and maritime emporiums.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e04895e2-2213-4546-9cd4-546b29f9e2a3', 'Merchant associations and trading guilds that maintained commercial markets, levied local trade tariffs, and performed municipal administrative functions in mercantile towns', true, '74cc0756-7993-4422-bd30-bfa170d4aeb5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13ac44ac-0b88-4e13-9683-16a05b81d714', 'Peasant farming assemblies in forests', false, '74cc0756-7993-4422-bd30-bfa170d4aeb5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51cd7a27-f1f2-4dbc-afb5-f8253957a437', 'Assemblies of temple dancers only', false, '74cc0756-7993-4422-bd30-bfa170d4aeb5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e00bb61d-3176-4c3b-91de-3dfd60ef16a6', 'The King''s personal bodyguard unit', false, '74cc0756-7993-4422-bd30-bfa170d4aeb5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63a16ece-b54d-4162-a51a-d7c91bb5ec9c', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'Why is the 9th–12th century Chola administration celebrated by modern political scientists as a pioneer of ''Decentralized Grassroots Democracy''?', 'The Chola state balanced centralized imperial thalassocracy with highly autonomous, democratic village-level communal governance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c7c2da9-f12d-4e77-86a5-270c94f62707', 'While maintaining an overarching imperial defense and foreign policy, local village assemblies (Urs and Sabhas) enjoyed complete self-governance, running committees for canals, dispute settlement, and local taxation', true, '63a16ece-b54d-4162-a51a-d7c91bb5ec9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7d3a2ea-f93a-4e50-bbc4-e23ebe6194d8', 'Because the Cholas had no central king', false, '63a16ece-b54d-4162-a51a-d7c91bb5ec9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0906d3d-5475-48b8-8b8c-1745a9e61808', 'Because elections were held on modern electronic machines', false, '63a16ece-b54d-4162-a51a-d7c91bb5ec9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bd77ded-8031-468b-91fe-1c9549cff648', 'Because all land was owned by the British', false, '63a16ece-b54d-4162-a51a-d7c91bb5ec9c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89a7a674-535c-49e6-be5f-96ab5cc21f68', 'Class 7', 'Social Science', 'Chapter 2: New Kings and Kingdoms', 'Hard', 'What master historical synthesis is established in Chapter 2 of NCERT Class 7 History?', 'Chapter 2 illuminates the rise of dynamic regional kingdoms, military statecraft, temple-centered urbanization, and grassroots rural democracy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f9b78b0-d745-45fd-8d39-14f1dfd5a4be', 'The transition from early feudal chieftains (Samantas) to powerful regional and pan-regional imperial dynasties, characterized by grand temple building, sophisticated hydraulic agrarian engineering, fine bronze arts, and self-governing local village institutions', true, '89a7a674-535c-49e6-be5f-96ab5cc21f68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87e3be26-febc-4816-824f-944ce97d7df6', 'A period of total darkness without any kings or art', false, '89a7a674-535c-49e6-be5f-96ab5cc21f68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8286d1c0-4427-4d31-9a32-4e851d959b84', 'The complete destruction of all agriculture', false, '89a7a674-535c-49e6-be5f-96ab5cc21f68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1a58971-69bf-4fb7-9b88-f5c43bc9fb28', 'The end of Indian history', false, '89a7a674-535c-49e6-be5f-96ab5cc21f68');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('42607f87-6b24-4970-8d12-a55c6d4ee80e', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'भाषा की वह सबसे छोटी मूल मौखिक या लिखित इकाई, जिसके और टुकड़े (खंड) नहीं किए जा सकते, उसे क्या कहते हैं?', 'वर्ण भाषा की सूक्ष्मतम अविभाज्य मूल ध्वनि-इकाई है (जैसे: अ, इ, क्, ख्)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb3e1b2a-5e6c-40ef-9351-6c1e04164ef0', 'वर्ण (या ध्वनि / Letter)', true, '42607f87-6b24-4970-8d12-a55c6d4ee80e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5274f413-f23e-4400-8fb6-c5437f36ae72', 'शब्द', false, '42607f87-6b24-4970-8d12-a55c6d4ee80e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a8a8491-80f8-4967-b372-375817bd99f6', 'वाक्य', false, '42607f87-6b24-4970-8d12-a55c6d4ee80e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc127a79-ccdf-4183-ab2d-f96e21524fb4', 'पद', false, '42607f87-6b24-4970-8d12-a55c6d4ee80e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('391d291c-17a3-462f-8b65-e2445fe7fd75', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'किसी भाषा के वर्णों के व्यवस्थित, क्रमबद्ध और मानक समूह को क्या कहते हैं?', 'वर्णों के व्यवस्थित एवं प्रामाणिक समूह को ''वर्णमाला'' कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57211070-f250-4b0f-a921-27d1f257369a', 'वर्णमाला (Alphabet)', true, '391d291c-17a3-462f-8b65-e2445fe7fd75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('416b232b-85d5-4624-9216-f1c297b8d5af', 'शब्दकोश', false, '391d291c-17a3-462f-8b65-e2445fe7fd75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff90d6af-3148-46b9-9703-62130b0e8aee', 'व्याकरण', false, '391d291c-17a3-462f-8b65-e2445fe7fd75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10ed4a96-a83c-4f1e-b477-53c90bceb830', 'लिपि', false, '391d291c-17a3-462f-8b65-e2445fe7fd75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('86e3d231-df69-406e-bee1-555e5746ef15', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'हिंदी वर्णमाला में वर्णों को मुख्य रूप से कितने वर्गों/भेदों में बाँटा गया है?', 'वर्णों के दो मूल भेद हैं: स्वर (स्वतंत्र उच्चरित ध्वनियाँ) तथा व्यंजन (स्वरों की सहायता से उच्चरित ध्वनियाँ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45bbb210-0376-432d-b2e2-74dac898ff70', 'दो भेद (1. स्वर - Vowels, 2. व्यंजन - Consonants)', true, '86e3d231-df69-406e-bee1-555e5746ef15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef1edce9-ad90-4029-9a01-f3444203714a', 'चार भेद', false, '86e3d231-df69-406e-bee1-555e5746ef15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57a9571a-ad74-4f31-8b7d-acae460bb4f4', 'तीन भेद', false, '86e3d231-df69-406e-bee1-555e5746ef15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12aa42c2-c83c-456f-a93c-85f1a58f1281', 'पाँच भेद', false, '86e3d231-df69-406e-bee1-555e5746ef15');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3fde86ae-6b1a-4bbf-acf3-dc4c8ba9c946', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'जिन वर्णों का उच्चारण बिना किसी अन्य वर्ण की सहायता के स्वतंत्र रूप से होता है, उन्हें क्या कहते हैं?', 'स्वतंत्र रूप से अबाध गति से उच्चरित ध्वनियाँ ''स्वर'' कहलाती हैं (हिंदी में कुल 11 स्वर हैं)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd5b1e61-8009-46f0-922e-f42e710900b4', 'स्वर (Vowels)', true, '3fde86ae-6b1a-4bbf-acf3-dc4c8ba9c946');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00dd260d-53e6-4b0b-92f9-d4c2611389a1', 'व्यंजन', false, '3fde86ae-6b1a-4bbf-acf3-dc4c8ba9c946');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cb99457-05d7-4f27-a1b1-9f697aa97338', 'संयुक्त व्यंजन', false, '3fde86ae-6b1a-4bbf-acf3-dc4c8ba9c946');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e377252-a736-4430-8bc6-92fa3ca0e1b5', 'अयोगवाह', false, '3fde86ae-6b1a-4bbf-acf3-dc4c8ba9c946');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5e311e1-a6a2-4cda-ac39-0ebb6c83b0b0', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'हिंदी वर्णमाला में मानक स्वरों की कुल संख्या कितनी है?', 'हिंदी वर्णमाला में 11 मानक स्वर होते हैं (अं और अः को अयोगवाह माना जाता है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e43bebc-2aa5-4901-9a24-c6c037343288', '11 स्वर (अ, आ, इ, ई, उ, ऊ, ऋ, ए, ऐ, ओ, औ)', true, 'a5e311e1-a6a2-4cda-ac39-0ebb6c83b0b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6087fab6-47e4-45e3-a2d3-600a08902854', '13 स्वर', false, 'a5e311e1-a6a2-4cda-ac39-0ebb6c83b0b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d54cb9cd-015b-4186-b686-d4ad71b1ca14', '10 स्वर', false, 'a5e311e1-a6a2-4cda-ac39-0ebb6c83b0b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dde09db-ffb5-4421-a941-cc4d6e79a50f', '12 स्वर', false, 'a5e311e1-a6a2-4cda-ac39-0ebb6c83b0b0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f395d220-99fd-4ed9-a1cb-b9c1b815c8f2', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'जिन स्वरों के उच्चारण में सबसे कम समय (एक मात्रा का समय) लगता है, उन्हें क्या कहते हैं?', 'एकमात्रिक मूल स्वर ''ह्रस्व स्वर'' कहलाते हैं (अ, इ, उ, ऋ - कुल 4)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44fb504d-889c-4116-a024-958e966885fb', 'ह्रस्व स्वर (Short Vowels : अ, इ, उ, ऋ)', true, 'f395d220-99fd-4ed9-a1cb-b9c1b815c8f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34132031-eb8b-46c6-bb26-662a6b3e7bb3', 'दीर्घ स्वर', false, 'f395d220-99fd-4ed9-a1cb-b9c1b815c8f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd409ceb-d534-447f-a02b-ade05e6e85b0', 'प्लुत स्वर', false, 'f395d220-99fd-4ed9-a1cb-b9c1b815c8f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b286859-112e-43b7-9c84-ecea416cb3dd', 'संयुक्त स्वर', false, 'f395d220-99fd-4ed9-a1cb-b9c1b815c8f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('654d6074-4ae6-4cbf-a981-c0322490a993', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'जिन स्वरों के उच्चारण में ह्रस्व स्वर से दोगुना समय (दो मात्राओं का समय) लगता है, उन्हें क्या कहते हैं?', 'द्विमात्रिक स्वर ''दीर्घ स्वर'' कहलाते हैं (कुल 7 स्वर)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e3f8e60-7aad-4db3-a8ee-bdcb520a8c0e', 'दीर्घ स्वर (Long Vowels : आ, ई, ऊ, ए, ऐ, ओ, औ)', true, '654d6074-4ae6-4cbf-a981-c0322490a993');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3544922b-1105-43c6-838c-a4906030cc94', 'ह्रस्व स्वर', false, '654d6074-4ae6-4cbf-a981-c0322490a993');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce6d6876-9c20-44e2-8238-4c4ba40107e2', 'प्लुत स्वर', false, '654d6074-4ae6-4cbf-a981-c0322490a993');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('907db9a1-4cd1-4a83-81b2-af2e850e6650', 'अयोगवाह', false, '654d6074-4ae6-4cbf-a981-c0322490a993');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a76fa710-6d9b-477f-b7c5-3dd226ef1687', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'जिन वर्णों का उच्चारण स्वरों की सहायता के बिना नहीं किया जा सकता, उन्हें क्या कहते हैं?', 'स्वरों की सहायता से बोले जाने वाले वर्ण ''व्यंजन'' कहलाते हैं (प्रत्येक व्यंजन में ''अ'' स्वर अंतर्निहित होता है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8fb246b-a8a8-497b-9e01-a15aed41efdc', 'व्यंजन (Consonants)', true, 'a76fa710-6d9b-477f-b7c5-3dd226ef1687');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10cc1cfd-cb61-4908-9fa6-3bfc4b5860bb', 'स्वर', false, 'a76fa710-6d9b-477f-b7c5-3dd226ef1687');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c73baaf-c20a-4293-9cab-bfab791367fe', 'अनुस्वार', false, 'a76fa710-6d9b-477f-b7c5-3dd226ef1687');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4e71c1e-98f0-41aa-87a9-e2921e3df0d2', 'विसर्ग', false, 'a76fa710-6d9b-477f-b7c5-3dd226ef1687');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('701f7323-aad0-4701-b679-a300f01ff6b7', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'हिंदी वर्णमाला में स्पर्श व्यंजनों (क-वर्ग से प-वर्ग तक) की कुल संख्या कितनी है?', 'कवर्ग, चवर्ग, टवर्ग, तवर्ग और पवर्ग में 5-5 वर्ण मिलकर कुल 25 ''स्पर्श व्यंजन'' बनाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80af8cc4-6cdb-432a-82b3-9a77d2dc3575', '25 व्यंजन (5 वर्ग × 5 वर्ण = 25)', true, '701f7323-aad0-4701-b679-a300f01ff6b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3158e4e3-78c0-4878-869b-0bac0c7b32e5', '33', false, '701f7323-aad0-4701-b679-a300f01ff6b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ebf5027-be78-4e0f-9522-6bf1bef16c1f', '11', false, '701f7323-aad0-4701-b679-a300f01ff6b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57e0311d-043d-46c0-8d2f-548c5a8cc9c6', '4', false, '701f7323-aad0-4701-b679-a300f01ff6b7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fdbacc05-0697-4845-a524-b28f056be5e4', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'हिंदी में ''क्ष, त्र, ज्ञ, श्र'' वर्णों को किस श्रेणी में रखा जाता है?', 'दो भिन्न व्यंजनों के संयोग से बने वर्ण ''संयुक्त व्यंजन'' हैं (क्+ष्=क्ष, त्+र्=त्र, ज्+ञ्=ज्ञ, श्+र्=श्र)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b80371d6-cca5-411e-b9fe-1fc8bd528700', 'संयुक्त व्यंजन (Compound Consonants)', true, 'fdbacc05-0697-4845-a524-b28f056be5e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4a5ce05-fa53-489f-a733-164f9aaa6b4e', 'स्पर्श व्यंजन', false, 'fdbacc05-0697-4845-a524-b28f056be5e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77e1498d-7a91-4ce0-87bf-8e625e5ab1f9', 'अंतःस्थ व्यंजन', false, 'fdbacc05-0697-4845-a524-b28f056be5e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('897626a3-75ee-49e1-be26-786ca6887ef9', 'ऊष्म व्यंजन', false, 'fdbacc05-0697-4845-a524-b28f056be5e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31f7730b-3bc3-40c8-af5a-2a9842bf0785', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'शिरोरेखा के ऊपर बिंदु (ं) के रूप में प्रयुक्त होने वाले नासिक्य चिह्न को व्याकरण में क्या कहते हैं?', 'पंचम वर्ण के स्थान पर प्रयुक्त बिंदु प्रतीक ''अनुस्वार'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb84453d-460e-4380-9f12-693a8f1441f3', 'अनुस्वार (Anusvara - जैसे: गंगा, चंचल, पतंग)', true, '31f7730b-3bc3-40c8-af5a-2a9842bf0785');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d265f67a-6b99-4c3e-b537-94860cadbfab', 'अनुनासिक (चन्द्रबिन्दु)', false, '31f7730b-3bc3-40c8-af5a-2a9842bf0785');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb6c8dcc-4bfe-4974-ad21-e00524b47b4b', 'विसर्ग', false, '31f7730b-3bc3-40c8-af5a-2a9842bf0785');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d34322c5-eb78-443c-b7d6-1e851fb98117', 'हलंत', false, '31f7730b-3bc3-40c8-af5a-2a9842bf0785');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d26d16a5-6911-4973-9c94-46cbbacc52d3', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Easy', 'शिरोरेखा के ऊपर चन्द्रबिन्दु (ँ) के रूप में प्रयुक्त होने वाले ध्वनि चिह्न (जिसका उच्चारण मुख और नाक दोनों से होता है) को क्या कहते हैं?', 'मुख और नासिका दोनों के संयुक्त वायु-प्रवाह से उच्चरित स्वर ''अनुनासिक'' (चन्द्रबिन्दु ँ) कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d74ec735-7c20-48fd-b54e-3132a78c8f14', 'अनुनासिक (Anunasika - जैसे: चाँद, आँख, गाँव)', true, 'd26d16a5-6911-4973-9c94-46cbbacc52d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5479c7bf-47e0-42a7-9930-eee6eaae1433', 'अनुस्वार', false, 'd26d16a5-6911-4973-9c94-46cbbacc52d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('056f9fc0-153e-4a8f-aef7-bf4b84d0a511', 'विसर्ग', false, 'd26d16a5-6911-4973-9c94-46cbbacc52d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef1d65eb-1454-4507-8be4-6ffd7f82d098', 'नुक्ता', false, 'd26d16a5-6911-4973-9c94-46cbbacc52d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8725ccbf-fd58-4e27-b418-86091a28f0e6', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', 'अंतःस्थ व्यंजन (Semi-vowels) के अंतर्गत कौन-से चार वर्ण आते हैं?', 'स्वर और व्यंजन के मध्य स्थित वायु-प्रवाह वाले वर्ण ''य, र, ल, व'' अंतःस्थ व्यंजन कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe915894-b759-4d49-91f6-fc85c78e50a1', 'य, र, ल, व (Y, R, L, V)', true, '8725ccbf-fd58-4e27-b418-86091a28f0e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d8f830a-8a2f-4f72-a2d9-99cafda55266', 'श, ष, स, ह', false, '8725ccbf-fd58-4e27-b418-86091a28f0e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a439ef07-7757-4f5b-bf6e-377ceb710a1a', 'क, ख, ग, घ', false, '8725ccbf-fd58-4e27-b418-86091a28f0e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af3fd92a-ba3e-4367-a713-1740f785742e', 'च, छ, ज, झ', false, '8725ccbf-fd58-4e27-b418-86091a28f0e6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31915817-fa9b-4888-8a8f-edfb8f99bf42', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', 'ऊष्म व्यंजन (Sibilants / Fricatives) के अंतर्गत कौन-से चार वर्ण आते हैं जिनके उच्चारण में मुख से रगड़ खाकर गर्म वायु निकलती है?', 'उच्चारण घर्षण से ऊष्मा उत्पन्न करने वाले वर्ण ''श, ष, स, ह'' ऊष्म व्यंजन कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfb7ee9d-5f8d-4808-baed-5cf16fc19c27', 'श, ष, स, ह (Sh, Sh, S, H)', true, '31915817-fa9b-4888-8a8f-edfb8f99bf42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26a1497e-bbc4-4abb-a2a4-36ee2b9fa931', 'य, र, ल, व', false, '31915817-fa9b-4888-8a8f-edfb8f99bf42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e397432-1993-4e62-aa9e-2ade923315fd', 'क्ष, त्र, ज्ञ, श्र', false, '31915817-fa9b-4888-8a8f-edfb8f99bf42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7b3689f-278f-4e1d-9601-63f25cab2f16', 'ट, ठ, ड, ढ', false, '31915817-fa9b-4888-8a8f-edfb8f99bf42');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('033d4886-d18f-4a74-8873-25b0e4053437', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''क, ख, ग, घ, ङ'' और स्वर ''अ, आ'' का उच्चारण मुख के किस स्थान से होता है?', 'कंठ (गले) से उच्चरित होने वाली ध्वनियाँ ''कंठ्य'' कहलाती हैं (अकुहविसर्जनीयानां कण्ठः)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65591e7d-4d2c-40d1-a1ba-11851bcb1236', 'कंठ से (कंठ्य ध्वनियाँ / Velar)', true, '033d4886-d18f-4a74-8873-25b0e4053437');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ee059f3-4cdf-4253-b5f0-63c5e311b4fb', 'तालु से (तालव्य)', false, '033d4886-d18f-4a74-8873-25b0e4053437');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55ac125f-b098-4e82-9a61-159bbba77759', 'मूर्धा से (मूर्धन्य)', false, '033d4886-d18f-4a74-8873-25b0e4053437');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8776d6c-3c10-4dac-bff3-039bf2b6f91e', 'दाँतों से (दंत्य)', false, '033d4886-d18f-4a74-8873-25b0e4053437');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46177f20-2dbf-478a-844f-addeda603c7b', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''च, छ, ज, झ, ञ'' और स्वर ''इ, ई'' तथा ''य, श'' का उच्चारण स्थान क्या है?', 'जिह्वा के तालु स्पर्श से उच्चरित ध्वनियाँ ''तालव्य'' कहलाती हैं (इचुयशानां तालु)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c66fc5a5-e758-4b50-98fe-fc651982178b', 'तालु (तालव्य ध्वनियाँ / Palatal)', true, '46177f20-2dbf-478a-844f-addeda603c7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cc8d66e-1b5f-45cc-9131-b898f12520ab', 'कंठ', false, '46177f20-2dbf-478a-844f-addeda603c7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2460425-009a-4c15-bad9-f726a9c30355', 'ओष्ठ', false, '46177f20-2dbf-478a-844f-addeda603c7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea94713e-dfa4-4407-a136-a97fd674f8ae', 'दंत', false, '46177f20-2dbf-478a-844f-addeda603c7b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('54f23db7-9a7f-4f45-b663-0420ad6d4fca', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''ट, ठ, ड, ढ, ण'' और स्वर ''ऋ'' तथा ''र, ष'' का उच्चारण स्थान क्या है?', 'मूर्धा (कठोर तालु के अग्र भाग) से उच्चरित ध्वनियाँ ''मूर्धन्य'' कहलाती हैं (ऋटुरषाणां मूर्धा)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('762f9b63-9f74-45e9-a9f1-2a44eb799d6f', 'मूर्धा (मूर्धन्य ध्वनियाँ / Retroflex)', true, '54f23db7-9a7f-4f45-b663-0420ad6d4fca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d679eb8-2192-4dea-8ac4-1414f4796d9f', 'दंत', false, '54f23db7-9a7f-4f45-b663-0420ad6d4fca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab489b5a-a559-4c19-8e81-478e48db75ed', 'ओष्ठ', false, '54f23db7-9a7f-4f45-b663-0420ad6d4fca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcb55530-5736-4394-b168-1435c9bb841b', 'कंठ', false, '54f23db7-9a7f-4f45-b663-0420ad6d4fca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d77dc31a-da6a-4226-9661-609348ca1105', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''त, थ, द, ध, न'' और ''ल, स'' का उच्चारण स्थान क्या है?', 'जिह्वा के दाँतों के स्पर्श से उच्चरित ध्वनियाँ ''दंत्य'' कहलाती हैं (लृतुलसानां दन्ताः)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa4e38a3-b52d-4fc3-9e00-4cf04108e897', 'दाँत (दंत्य ध्वनियाँ / Dental)', true, 'd77dc31a-da6a-4226-9661-609348ca1105');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8243704-e104-48a1-97e1-d6ea41f8cb6b', 'ओष्ठ', false, 'd77dc31a-da6a-4226-9661-609348ca1105');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfac4776-522e-4aeb-bd94-bb23d400b9f4', 'कंठ', false, 'd77dc31a-da6a-4226-9661-609348ca1105');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ee9f296-bc46-44da-9198-71f63948d2d8', 'मूर्धा', false, 'd77dc31a-da6a-4226-9661-609348ca1105');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2558cd17-023c-47a7-969c-4d3cd498bdd5', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''प, फ, ब, भ, म'' और स्वर ''उ, ऊ'' का उच्चारण स्थान क्या है?', 'दोनों ओष्ठों के परस्पर संसर्ग से उच्चरित ध्वनियाँ ''ओष्ठ्य'' कहलाती हैं (उपूपध्मानीयानामोष्ठौ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('781d5e07-6219-4ce4-ae16-b45a1909229e', 'दोनों होंठ (ओष्ठ्य ध्वनियाँ / Labial)', true, '2558cd17-023c-47a7-969c-4d3cd498bdd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00c55149-c6e5-4765-a252-23de06d1c2a8', 'दाँत', false, '2558cd17-023c-47a7-969c-4d3cd498bdd5');
