INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5cca2df0-8144-4486-92ed-28a3f458394b', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', 'जब एक ही व्यंजन ध्वनि दो बार लगातार संयुक्त होकर आए (पहला स्वर-रहित और दूसरा स्वर-सहित, जैसे: ''पक्का'', ''दिल्ली'', ''बच्चा'', ''सच्चा''), तब उसे क्या कहते हैं?', 'समान व्यंजन का स्वररहित और स्वरसहित युग्म ''द्वित्व व्यंजन'' कहलाता है (क्+क = क्क, ल्+ल = ल्ल)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8d23e70-f3f9-4d29-a5b4-08df3269b7f0', 'द्वित्व व्यंजन (Geminate Consonants)', true, '5cca2df0-8144-4486-92ed-28a3f458394b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5607198-d2d0-410d-a603-92ba2ba8ed2e', 'संयुक्त व्यंजन', false, '5cca2df0-8144-4486-92ed-28a3f458394b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eda42eda-c5cc-41d2-a11b-596bf85f2044', 'स्पर्श व्यंजन', false, '5cca2df0-8144-4486-92ed-28a3f458394b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76cc4258-e119-49ed-b807-bf3daf932ebd', 'अयोगवाह', false, '5cca2df0-8144-4486-92ed-28a3f458394b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c26ab6c-5302-4109-a91d-6054961bed1e', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''ज्ञ'' संयुक्त व्यंजन किन दो वर्णों के शुद्ध संयोग से बनता है?', '''ज्ञ'' वर्ण का मानक व्याकरणिक निर्माण ''ज्'' और ''ञ्'' के योग से होता है (ज् + ञ् = ज्ञ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c95477a2-fc2d-4362-bdee-af329aabc9c0', 'ज् + ञ् + अ (J + Nya)', true, '5c26ab6c-5302-4109-a91d-6054961bed1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('796fbad7-8013-45fc-9dc8-9b32cf55c148', 'ग् + य् + अ', false, '5c26ab6c-5302-4109-a91d-6054961bed1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47e29d52-568b-4a3e-ab48-81cff915260b', 'ज् + य् + अ', false, '5c26ab6c-5302-4109-a91d-6054961bed1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b343e48e-8434-417c-96b2-6c1c3d0d674b', 'द् + य् + अ', false, '5c26ab6c-5302-4109-a91d-6054961bed1e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0718c2b0-76da-4304-bd2b-cd2fcb325f1d', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''श्र'' संयुक्त व्यंजन किन दो वर्णों के संयोग से बनता है?', '''श्र'' वर्ण का निर्माण तालव्य ''श्'' और ''र्'' के मेल से होता है (श् + र् = श्र, जैसे: श्री, श्रम)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca1a4170-2eca-4dec-9bad-c9dbcf7b64be', 'श् + र् + अ (Sh + R)', true, '0718c2b0-76da-4304-bd2b-cd2fcb325f1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2f7ea6d-4a06-4db2-a8ed-a9fa9072ae5b', 'ष् + र् + अ', false, '0718c2b0-76da-4304-bd2b-cd2fcb325f1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5904fde-f09c-47ef-8c55-ffe30ca2547d', 'स् + र् + अ', false, '0718c2b0-76da-4304-bd2b-cd2fcb325f1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6b4cdb1-d0c5-4dc8-b640-59dac4074b4c', 'छ् + र् + अ', false, '0718c2b0-76da-4304-bd2b-cd2fcb325f1d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ad7fa18-da28-461e-968d-6cb69ea3af88', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''उद्यान'' शब्द का शुद्ध वर्ण-विच्छेद क्या होगा?', 'उ + द् + य् + आ + न् + अ = उद्यान (द्+य् = द्य)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f036397e-572b-4526-8a99-bd3c9355a5ba', 'उ + द् + य् + आ + न् + अ', true, '6ad7fa18-da28-461e-968d-6cb69ea3af88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89a9c358-7cfc-4d3a-9fb5-5ecd8d90f0f4', 'उ + द् + आ + य् + न् + अ', false, '6ad7fa18-da28-461e-968d-6cb69ea3af88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12895f81-1a06-4c64-9a7a-1d11bc28cdf4', 'उद् + या + न', false, '6ad7fa18-da28-461e-968d-6cb69ea3af88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a51cfef-da18-4a1d-9ecb-bdbe5b902bfc', 'उ + द्या + न् + अ', false, '6ad7fa18-da28-461e-968d-6cb69ea3af88');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a6df8df7-39d4-4276-bbfb-749aead7dd47', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''कृपा'' शब्द का शुद्ध वर्ण-विच्छेद क्या होगा?', 'क व्यंजन में ''ऋ'' स्वर की मात्रा + प् + आ = क् + ऋ + प् + आ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4db7c62-bc06-4137-94fb-9192231cabf9', 'क् + ऋ + प् + आ', true, 'a6df8df7-39d4-4276-bbfb-749aead7dd47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('157fad9b-0174-47ca-807d-bf885030da9d', 'क् + र् + इ + प् + आ', false, 'a6df8df7-39d4-4276-bbfb-749aead7dd47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d60d525-e2a1-404e-93ab-ff6aeedf24c3', 'क् + ऋ + पा', false, 'a6df8df7-39d4-4276-bbfb-749aead7dd47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27cffb35-075a-417d-8946-bd048b7344b3', 'कृ + प् + आ', false, 'a6df8df7-39d4-4276-bbfb-749aead7dd47');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('69e49164-8e5f-486f-8ef0-7f0a5e11b052', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', 'उर्दू, अरबी, फ़ारसी तथा अंग्रेज़ी से हिंदी में आए विदेशी शब्दों के शुद्ध उच्चारण हेतु वर्णों के नीचे लगाए जाने वाले बिंदु (जैसे: ज़, फ़, क़, ख़, ग़) को क्या कहते हैं?', 'आगत ध्वनियों के तल में लगने वाला लघु बिंदु ''नुक्ता'' कहलाता है (जैसे: ज़मीन, फ़िल्म)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ce5324b-f4c9-42b8-ab15-b4ef5072674f', 'नुक्ता (Nukta)', true, '69e49164-8e5f-486f-8ef0-7f0a5e11b052');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b0a8d6f-b98e-4dc2-a909-f95b7ae0b89b', 'अनुस्वार', false, '69e49164-8e5f-486f-8ef0-7f0a5e11b052');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eaae77c4-31d0-4347-b33c-0c5df6742fb8', 'विसर्ग', false, '69e49164-8e5f-486f-8ef0-7f0a5e11b052');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ef6aaad-6bf6-4691-8add-47cb22d6944e', 'हलंत', false, '69e49164-8e5f-486f-8ef0-7f0a5e11b052');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d32a2b0-366b-4ec3-8430-7781392e101b', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', 'अयोगवाह (Ayogavaha) किन्हें कहा जाता है, जो न तो पूर्ण स्वर होते हैं और न पूर्ण व्यंजन?', 'जो योग न होने पर भी साथ वहन करें, वे ''अयोगवाह'' कहलाते हैं (अनुस्वार अं तथा विसर्ग अः)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d330e926-79ca-4b7d-a355-1e69786176f9', 'अनुस्वार (अं) और विसर्ग (अः)', true, '7d32a2b0-366b-4ec3-8430-7781392e101b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e795787-3cfa-46ef-af99-6b3065cb64d6', 'क्ष और त्र', false, '7d32a2b0-366b-4ec3-8430-7781392e101b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5161c30f-769a-4ba8-82fe-972e9444d62a', 'य और र', false, '7d32a2b0-366b-4ec3-8430-7781392e101b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c667f33c-31e2-472a-ad30-29017c3a439b', 'ड और ढ', false, '7d32a2b0-366b-4ec3-8430-7781392e101b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a89fe69-dcdb-4b17-9ac8-643505403943', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''र्'' के विभिन्न रूपों में ''पर्वत'' और ''कर्म'' में प्रयुक्त शिरोरेखा के ऊपर लगने वाले ''र्'' के रूप को क्या कहते हैं?', 'स्वररहित ''र्'' जब अगले व्यंजन के ऊपर शिरोरेखा पर बैठता है, तो उसे ''रेफ़'' कहते हैं (प्+अ+र्+व्+अ+त्+अ = पर्वत)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4242c17-fe42-4444-aa63-aedb31081077', 'रेफ़ (Reph - स्वर रहित र्)', true, '8a89fe69-dcdb-4b17-9ac8-643505403943');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c63c159-b97e-432c-935a-a19353c60b88', 'पदेन', false, '8a89fe69-dcdb-4b17-9ac8-643505403943');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01216420-341d-4f23-9855-5d3d794d9056', 'ऋ की मात्रा', false, '8a89fe69-dcdb-4b17-9ac8-643505403943');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('530354a1-48ce-4428-ac61-f41773d06b57', 'हलंत', false, '8a89fe69-dcdb-4b17-9ac8-643505403943');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4538e35-bccf-455f-aceb-649c13a74442', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Medium', '''क्रम'' और ''प्रकाश'' में व्यंजन के पैरों में लगने वाले ''र्'' के रूप को क्या कहते हैं?', 'स्वरसहित ''र्'' जब पूर्ववर्ती स्वररहित व्यंजन के चरण में जुड़ता है, तो उसे ''पदेन'' कहते हैं (क्+र् = क्र)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3098e9a3-6aac-4fa4-be70-bb2a623a0525', 'पदेन (Paden - स्वर सहित र्)', true, 'e4538e35-bccf-455f-aceb-649c13a74442');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4220edaf-91b3-4372-bc73-67f5896fbfee', 'रेफ़', false, 'e4538e35-bccf-455f-aceb-649c13a74442');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42b6a1be-7445-4af9-9ee7-210c5089a584', 'अनुस्वार', false, 'e4538e35-bccf-455f-aceb-649c13a74442');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7fc3a4c-6c09-4a93-b25e-b5c3012bafe0', 'विसर्ग', false, 'e4538e35-bccf-455f-aceb-649c13a74442');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('139fdd94-e4df-4b53-9627-1cf48fec6619', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a3b7155-8ba3-4884-87bf-e973ebe52f66', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '139fdd94-e4df-4b53-9627-1cf48fec6619');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b987660e-64dc-4336-b6f6-c530464c0a3b', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '139fdd94-e4df-4b53-9627-1cf48fec6619');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('146fca36-4cbf-4bc3-a2e9-1bae16a9c904', '(A) सही है, परन्तु (R) गलत है।', false, '139fdd94-e4df-4b53-9627-1cf48fec6619');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85115128-9a95-448d-a992-259132b942d3', '(A) गलत है, परन्तु (R) सही है।', false, '139fdd94-e4df-4b53-9627-1cf48fec6619');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6bfd4f60-ad8a-493a-a930-7097dd80dd05', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'Spot the IMPOSTER in the following group of वर्ण और उनके उच्चारण स्थानों के युग्म में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0df10e5d-8f13-4266-a625-325655b6ec2a', 'क - कंठ्य', false, '6bfd4f60-ad8a-493a-a930-7097dd80dd05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9898a064-92d3-4c95-932c-111d962cc187', 'च - तालव्य', false, '6bfd4f60-ad8a-493a-a930-7097dd80dd05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('861f3f5f-5071-4c93-adbc-f414fdb3de84', 'त - दंत्य', false, '6bfd4f60-ad8a-493a-a930-7097dd80dd05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a91dca3-0156-4e20-ad67-1d5308cce357', 'प - मूर्धन्य (प वर्ग ओष्ठ्य ध्वनियाँ हैं, मूर्धन्य नहीं)', true, '6bfd4f60-ad8a-493a-a930-7097dd80dd05');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3405dcb0-2f6c-4078-9b08-7433d3b5f3d9', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'सुमेलित कीजिए (वर्ण-विच्छेद और उनके शुद्ध मानक शब्द):
(क) क् + ष् + अ + त् + र् + इ + य् + अ -> (i) क्षत्रिय
(ख) श् + र् + ऋ + ङ् + ग् + आ + र् + अ -> (ii) शृंगार
(ग) द् + व् + आ + र् + इ + क् + आ     -> (iii) द्वारिका / द्वारका
(घ) व् + इ + ज् + ञ् + आ + न् + अ     -> (iv) विज्ञान', 'क्+ष् = क्ष; श्+ऋ = शृ (शृंगार); द्+व् = द्व; ज्+ञ् = ज्ञ (विज्ञान)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4d0ac8a-74e5-46a5-8680-76eb1ead28c9', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, '3405dcb0-2f6c-4078-9b08-7433d3b5f3d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d283f23b-2fc2-4a08-a0b3-3f2b8592ce79', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '3405dcb0-2f6c-4078-9b08-7433d3b5f3d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e726287e-afa5-4955-96b0-aecccb9277e6', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '3405dcb0-2f6c-4078-9b08-7433d3b5f3d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b51691d3-70cd-472e-a6b9-6b3332c6e5b6', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '3405dcb0-2f6c-4078-9b08-7433d3b5f3d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f833da8c-6130-4bea-9c57-1956a6de261d', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', '''शृंगार'' शब्द की मानक शुद्ध वर्तनी और वर्ण संरचना क्या है?', 'मानक वर्तनी: ''श्'' में ''ऋ'' जुड़ने पर ''शृ'' बनता है; ''श्रृ'' अशुद्ध द्वित्व दोष है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39e823c2-581d-40f7-a5ef-b7f979be22e5', '''शृंगार'' (तालव्य ''श्'' में स्वर ''ऋ'' की मात्रा जुड़ने पर ''शृ'' बनता है ; इसमें ''र'' का पदेन नहीं लगता)', true, 'f833da8c-6130-4bea-9c57-1956a6de261d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdd1e58f-718c-406d-96e9-4e042fc1adff', '''श्रृंगार'' (अशुद्ध रूप जिसमें श् + र् + ऋ दो बार र् लगा दिया जाता है)', false, 'f833da8c-6130-4bea-9c57-1956a6de261d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31ec5ee3-088b-467b-b84e-099bc015e52d', '''सिंगार''', false, 'f833da8c-6130-4bea-9c57-1956a6de261d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97987ede-8cf6-46a2-a29d-a1ba201a04fa', '''श्रिंगार''', false, 'f833da8c-6130-4bea-9c57-1956a6de261d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b2c8cea-47a5-438c-80e6-454706d2aba7', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'अल्पप्राण (Unaspirated) और महाप्राण (Aspirated) व्यंजनों में क्या वैज्ञानिक अंतर होता है?', 'अल्पप्राण (क, ग, ङ / 1,3,5) में न्यूनतम वायु-प्रक्षेप; महाप्राण (ख, घ / 2,4) में सघोष हकार ध्वनि का विमोचन होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c9d44ba-daf3-4963-a31d-f1c8e3400db0', 'अल्पप्राण के उच्चारण में मुख से कम श्वास-वायु निकलती है (प्रत्येक वर्ग का 1, 3, 5 वर्ण) ; जबकि महाप्राण के उच्चारण में ''ह'' जैसी भारी श्वास-वायु निकलती है (प्रत्येक वर्ग का 2 और 4 वर्ण)', true, '3b2c8cea-47a5-438c-80e6-454706d2aba7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1153b93-c60f-4002-8bf8-66e626aa3cf0', 'अल्पप्राण केवल स्वर होते हैं', false, '3b2c8cea-47a5-438c-80e6-454706d2aba7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75366693-729e-47da-9145-0afc252cf814', 'महाप्राण केवल विसर्ग में होते हैं', false, '3b2c8cea-47a5-438c-80e6-454706d2aba7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7a3a04a-ed2c-4506-84b0-26a312da5c31', 'दोनों में कोई अंतर नहीं है', false, '3b2c8cea-47a5-438c-80e6-454706d2aba7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c2b2765-92c3-4f12-a539-6573117ecde5', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'घोष (सघोष / Voiced) और अघोष (Voiceless) ध्वनियों में स्वर-तंत्रियों (Vocal Cords) का क्या कार्य होता है?', 'सघोष में स्वरतंत्री का ध्वनिक कंपन (3,4,5 + स्वर); अघोष में कंपन का अभाव (1,2 + श,ष,स)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06970f0e-a7e4-4f66-b2b8-fef785573a33', 'घोष ध्वनियों के उच्चारण में स्वर-तंत्रियों में कंपन (Ghosha) होता है (वर्गों के 3, 4, 5 वर्ण + सभी स्वर) ; जबकि अघोष ध्वनियों में स्वर-तंत्रियों में कंपन नहीं होता (वर्गों के 1 और 2 वर्ण + श, ष, स)', true, '0c2b2765-92c3-4f12-a539-6573117ecde5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32999420-ae03-47c6-ad1d-20837c1f5975', 'अघोष ध्वनियाँ केवल कानों में सुनाई देती हैं', false, '0c2b2765-92c3-4f12-a539-6573117ecde5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7aa1750-1271-438a-900c-996810fcdd99', 'घोष ध्वनियाँ केवल गाई जाती हैं', false, '0c2b2765-92c3-4f12-a539-6573117ecde5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4dab35c-0f6a-4e30-8b8f-130094dadfff', 'स्वर-तंत्रियों का ध्वनि से कोई संबंध नहीं है', false, '0c2b2765-92c3-4f12-a539-6573117ecde5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d1cdec57-b8b8-4401-9f66-0f5365ce9f7b', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'उच्छिप्त (तातंजात / Flap) व्यंजन किन्हें कहा जाता है जिनके उच्चारण में जिह्वा मूर्धा को छूकर झटके से नीचे गिरती है?', '''ड़'' और ''ढ़'' उच्छिप्त व्यंजन हैं जो कभी किसी शब्द के आरंभ में प्रयुक्त नहीं होते (जैसे: सड़क, पढ़ना)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1ee3d7e-4e69-40b2-9a8f-08b2c17a3b6a', 'ड़ और ढ़ (Dda and Ddha)', true, 'd1cdec57-b8b8-4401-9f66-0f5365ce9f7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fc43aa6-eaf3-403f-9ac6-f7bde3d8eefc', 'ड और ढ', false, 'd1cdec57-b8b8-4401-9f66-0f5365ce9f7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c60dd163-c236-43cf-af02-183a014fbeff', 'त और थ', false, 'd1cdec57-b8b8-4401-9f66-0f5365ce9f7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fc128c1-fb8a-4e37-bbcd-30de64ff6f69', 'य और व', false, 'd1cdec57-b8b8-4401-9f66-0f5365ce9f7b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('28571487-f23c-4b1b-983c-7818f9fcaf56', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'मानक हिंदी वर्तनी के केंद्रीय नियम के अनुसार, संयुक्त क्रियाओं और ''गए / गए'' तथा ''हुए / हुए'' में से मानक रूप किसे माना गया है?', 'केंद्रीय हिंदी निदेशालय के अनुसार जहाँ स्वर का स्वाभाविक उच्चारण हो, वहाँ ''गए, नए, हुए'' मानक रूप हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eedb4dce-35eb-41a4-9c85-82f395ba3005', 'स्वर रूप ''गए, नए, हुए, चाहिए'' को मानक माना गया है (य-श्रुति के स्थान पर मूल स्वर रूप)', true, '28571487-f23c-4b1b-983c-7818f9fcaf56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e85ae7d1-dec3-4666-b2f3-4348eee0d147', 'गये और नये को केवल माना गया है', false, '28571487-f23c-4b1b-983c-7818f9fcaf56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77a50327-129b-4cf8-adfa-4613c5449bc8', 'दोनों को अमान्य किया गया है', false, '28571487-f23c-4b1b-983c-7818f9fcaf56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d750938-0ea0-4e25-b40c-ed11d9e82691', 'केवल संस्कृत शब्दों को माना गया है', false, '28571487-f23c-4b1b-983c-7818f9fcaf56');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe8d9c48-0949-4213-a27c-ba4becb83af4', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'प्लुत स्वर (Protracted Vowel) का प्रयोग हिंदी और संस्कृत में कहाँ किया जाता है?', 'त्रिमात्रिक दीर्घतम स्वर ''प्लुत स्वर'' (प्रतीक ३) दूर से संबोधन और ॐ के नाद में प्रयुक्त होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c2ec231-bcb7-4ca4-b5a8-5cc318723ece', 'किसी को दूर से पुकारने, रोने, गाने या ॐ (ओ३म्) के उच्चारण में जहाँ स्वर को तीन मात्राओं तक लंबा खींचा जाता है', true, 'fe8d9c48-0949-4213-a27c-ba4becb83af4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1717e26c-40c6-4e17-ab12-1bf9e1837d3a', 'केवल मौन रहने पर', false, 'fe8d9c48-0949-4213-a27c-ba4becb83af4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a60d656f-aefd-4c3f-b9a9-930cfe13823b', 'केवल विराम चिह्नों में', false, 'fe8d9c48-0949-4213-a27c-ba4becb83af4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d9dc3ed-7053-407e-aaa9-83cfe2cfcf02', 'साधारण बोलचाल में', false, 'fe8d9c48-0949-4213-a27c-ba4becb83af4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e0a2e4f3-4043-465e-a962-c6563e75b5ad', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', '''उज्ज्वल'' शब्द की शुद्ध मानक वर्तनी क्या है और इसमें कौन-सा व्यंजन नियम प्रयुक्त हुआ है?', 'उत् + ज्वल: त् का ज् में परिवर्तन → दोनों ''ज'' अर्द्ध (ज्ज्) होकर ''उज्ज्वल'' बनाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf49db5c-80a0-43a5-97a3-9ed69fe5fa76', '''उज्ज्वल'' (उत् + ज्वल = उज्ज्वल, जिसमें दोनों ''ज'' स्वर-रहित / आधे ''ज्ज्'' होते हैं)', true, 'e0a2e4f3-4043-465e-a962-c6563e75b5ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ade6afc0-716d-42e3-bd1a-54becf2a1ac6', '''उज्वल''', false, 'e0a2e4f3-4043-465e-a962-c6563e75b5ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3c55e1b-cc63-4d14-baa4-8a2912ed2699', '''उज्जवल''', false, 'e0a2e4f3-4043-465e-a962-c6563e75b5ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('732b6720-f1ff-486c-995f-7f379ecf0e47', '''उजवल''', false, 'e0a2e4f3-4043-465e-a962-c6563e75b5ad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ca93092-e2f7-4eab-8ee3-08983f2f2a5d', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'हिंदी में ''ऋ'' स्वर का मानक उच्चारण और लिपि प्रयोग क्या है?', '''ऋ'' तत्सम संस्कृत मूल स्वर है; देवनागरी में इसकी मात्रा (ृ) केवल व्यंजनों के पाद में जुड़ती है (जैसे: कृपा, मातृ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbaa27cc-e9d8-4693-8dbc-e4269d3c2679', '''ऋ'' एक तत्सम संस्कृत स्वर है जिसका आधुनिक हिंदी में उच्चारण ''रि'' जैसा होता है, किन्तु यह मूल रूप से स्वर माना जाता है (जैसे: ऋषि, ऋतु, ऋण)', true, '1ca93092-e2f7-4eab-8ee3-08983f2f2a5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ed86083-16ea-4d11-b977-ae37588311ef', '''ऋ'' केवल एक व्यंजन है', false, '1ca93092-e2f7-4eab-8ee3-08983f2f2a5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e86e1202-2e47-4a8f-bbd3-308f2100f317', '''ऋ'' का हिंदी में कोई प्रयोग नहीं है', false, '1ca93092-e2f7-4eab-8ee3-08983f2f2a5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b60dfb96-ca75-4bab-961a-b379d885ad1d', '''ऋ'' केवल नाम के आगे लगता है', false, '1ca93092-e2f7-4eab-8ee3-08983f2f2a5d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f30233a8-6747-4ba4-af16-10ec49155f98', 'Class 7', 'Hindi Grammar', 'Chapter 2: वर्ण विचार एवं वर्तनी', 'Hard', 'वर्ण विचार और मानक वर्तनी के सम्यक अध्ययन का भाषा अधिगम में क्या सर्वोच्च महत्व है?', 'वर्ण विचार भाषाशास्त्र का मूलाधार है, जो उच्चारण-स्थान की शुद्धता, ध्वनिविज्ञान और वर्तनी मानकीकरण को परिपुष्ट करता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('129a20dd-f645-495f-acb7-48ff87bedd28', 'यह भाषा की नींव को सुदृढ़ करता है, अशुद्ध उच्चारण तथा वर्तनी दोषों का पूर्ण निवारण कर वैज्ञानिक एवं प्रामाणिक भाषा-दक्षता प्रदान करता है', true, 'f30233a8-6747-4ba4-af16-10ec49155f98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bbd9b85-8b53-4339-8f28-0385202bdb3c', 'यह केवल वर्णों को रटने का साधन है', false, 'f30233a8-6747-4ba4-af16-10ec49155f98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3496b60-1384-49ef-a729-12e200e55565', 'इसका व्याकरण से कोई संबंध नहीं है', false, 'f30233a8-6747-4ba4-af16-10ec49155f98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3643f10-ca42-4be9-9783-718bbc64fbd5', 'यह केवल परीक्षाओं में अंक लाने के लिए है', false, 'f30233a8-6747-4ba4-af16-10ec49155f98');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02b24bb2-6607-49dc-9ed5-fd18ab1135c9', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'A reliable, scientific numerical measure of the degree of hotness or coldness of an object is called its:', 'Temperature is the objective physical quantity measuring the average kinetic energy of constituent particles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3ce4e21-5ffe-4af1-93ff-73a4de049b4b', 'Temperature', true, '02b24bb2-6607-49dc-9ed5-fd18ab1135c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4fd5d6e-f0fe-4a25-9850-46878400acc1', 'Heat energy', false, '02b24bb2-6607-49dc-9ed5-fd18ab1135c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b87b83d9-28ae-4f60-85e9-dd80b4fb320c', 'Density', false, '02b24bb2-6607-49dc-9ed5-fd18ab1135c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98059c0c-66a8-4bea-b421-6d03889cdc67', 'Pressure', false, '02b24bb2-6607-49dc-9ed5-fd18ab1135c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b5b1945-ba8b-4f9f-b9d7-86eefaba57f8', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'The device used specifically to measure the temperature of the human body is called a:', 'A clinical thermometer measures human body temperature across a narrow physiological range.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cb30b11-817c-437f-894f-9d308c7856d4', 'Clinical Thermometer', true, '9b5b1945-ba8b-4f9f-b9d7-86eefaba57f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb249d4b-290f-4444-a601-642a05b031f3', 'Laboratory Thermometer', false, '9b5b1945-ba8b-4f9f-b9d7-86eefaba57f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8afd9f5e-47fe-4d57-8c12-b04252af7330', 'Barometer', false, '9b5b1945-ba8b-4f9f-b9d7-86eefaba57f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c911f73-a333-49a2-a2d7-229d24c5a8b6', 'Speedometer', false, '9b5b1945-ba8b-4f9f-b9d7-86eefaba57f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9c46f20-ad1f-4e33-b830-282005866647', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'What is the temperature scale range of a standard Clinical Thermometer in Celsius degrees?', 'Clinical thermometers span 35°C to 42°C because human body temperature rarely drops below 35°C or exceeds 42°C.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b130d8c-eb42-4c15-a355-413d86dc16a1', '35°C to 42°C', true, 'e9c46f20-ad1f-4e33-b830-282005866647');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cc75db0-e616-4334-ae43-c780b1a7204f', '-10°C to 110°C', false, 'e9c46f20-ad1f-4e33-b830-282005866647');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87d10cfb-ce9a-448a-b42c-50632aa6fed8', '0°C to 100°C', false, 'e9c46f20-ad1f-4e33-b830-282005866647');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('739d5788-a8f7-4735-9a18-3d0fd211835a', '32°F to 212°F only', false, 'e9c46f20-ad1f-4e33-b830-282005866647');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('057c49e4-5e4e-4ea1-a05f-48f7140fc40f', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'What is the normal healthy average temperature of the human body on the Celsius scale?', 'Standard basal human homeostatic body temperature averages 37.0°C (98.6°F).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46ddea5c-54a1-4d9b-bb87-f047f75bd35e', '37°C (98.6°F)', true, '057c49e4-5e4e-4ea1-a05f-48f7140fc40f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d542482-beb0-488d-b78e-09dd2d7247bd', '35°C', false, '057c49e4-5e4e-4ea1-a05f-48f7140fc40f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5269d345-1fee-40dc-9957-287e9ad59cf4', '39°C', false, '057c49e4-5e4e-4ea1-a05f-48f7140fc40f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16b25ee5-1d28-4eaf-8da2-b4eb32d00740', '100°C', false, '057c49e4-5e4e-4ea1-a05f-48f7140fc40f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba954bee-998c-4a05-bedd-ab27cf2cdf91', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'What is the standard measurement range of a Laboratory Thermometer?', 'Laboratory thermometers generally span from -10°C up to 110°C to measure physical and chemical reactions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ec19a06-214d-43c2-8bff-78f996bf0659', '-10°C to 110°C', true, 'ba954bee-998c-4a05-bedd-ab27cf2cdf91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('844aacab-ded1-4026-b76a-879b3f3fceec', '35°C to 42°C', false, 'ba954bee-998c-4a05-bedd-ab27cf2cdf91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16ac143f-a7a3-42ab-b4b2-dc5395649da1', '0°C to 50°C', false, 'ba954bee-998c-4a05-bedd-ab27cf2cdf91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e4040ae-5283-4c4c-8752-5ed0673fdf7f', '-50°C to 200°C', false, 'ba954bee-998c-4a05-bedd-ab27cf2cdf91');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4ebf5c6-f544-4f72-9079-55ce9164c394', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'The process by which heat is transferred from the hotter end to the colder end of a SOLID object without the actual movement of its particles is called:', 'Conduction is solid-state thermal energy transfer through vibrational atomic collisions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a79b658-3be0-4f01-ab9b-09e681c07dbe', 'Conduction', true, 'c4ebf5c6-f544-4f72-9079-55ce9164c394');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('441eab27-1043-41c7-82b9-3447c6f57007', 'Convection', false, 'c4ebf5c6-f544-4f72-9079-55ce9164c394');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a014b415-714c-417f-9149-7c8c3e07a4f1', 'Radiation', false, 'c4ebf5c6-f544-4f72-9079-55ce9164c394');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5c3f560-d14e-4eb2-98eb-5f75ec9e0be9', 'Insulation', false, 'c4ebf5c6-f544-4f72-9079-55ce9164c394');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73adcea8-be13-47e2-9e81-798199dc0b64', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'Materials that allow heat to pass through them easily and rapidly (such as copper, aluminium, iron) are called:', 'Thermal conductors possess free electrons facilitating rapid kinetic energy transfer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c52a077d-b0a5-4be5-a11c-43ed355a368d', 'Conductors of Heat', true, '73adcea8-be13-47e2-9e81-798199dc0b64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('156c76c2-75ab-4046-8b98-995c9fb0b639', 'Insulators', false, '73adcea8-be13-47e2-9e81-798199dc0b64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b22783e-f27a-4dda-abca-4c3276a9a705', 'Semiconductors', false, '73adcea8-be13-47e2-9e81-798199dc0b64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8638857-d49f-42dd-bbfb-d65cb928e475', 'Radiators', false, '73adcea8-be13-47e2-9e81-798199dc0b64');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31a806bd-2c82-4314-937d-bb96eb33ac92', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'Materials that do not allow heat to pass through them easily (such as wood, plastic, rubber, air) are called:', 'Thermal insulators have high thermal resistance, impeding heat flux.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fcfda00-11af-49b8-9f3d-02865a749831', 'Insulators (Poor Conductors)', true, '31a806bd-2c82-4314-937d-bb96eb33ac92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2dd50b4-b3a9-466a-9cd7-03cb649c5acb', 'Good Conductors', false, '31a806bd-2c82-4314-937d-bb96eb33ac92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2fc8699-ca99-4bad-b2fd-682cddc40dd3', 'Metals', false, '31a806bd-2c82-4314-937d-bb96eb33ac92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4fe289b-65ae-4a86-93c0-3d7d4c99e428', 'Absorbers', false, '31a806bd-2c82-4314-937d-bb96eb33ac92');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dfaa8e83-c891-45f4-974d-d26b1771c6a7', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'The mode of heat transfer in LIQUIDS and GASES where the fluid particles themselves move physically from hotter to colder regions is called:', 'Convection is bulk macroscopic fluid transport driven by buoyancy and thermal density differentials.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fd4028b-811a-4af0-bc38-1c14535f4a41', 'Convection', true, 'dfaa8e83-c891-45f4-974d-d26b1771c6a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ca1e251-116a-43f2-8a6a-ba611f4d1298', 'Conduction', false, 'dfaa8e83-c891-45f4-974d-d26b1771c6a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a660d7b-ab5f-49ad-9f1b-27487b3b6841', 'Radiation', false, 'dfaa8e83-c891-45f4-974d-d26b1771c6a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e36fbb2a-a284-47c0-9c9d-d1cf5d93164c', 'Refraction', false, 'dfaa8e83-c891-45f4-974d-d26b1771c6a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ec3cc18-3434-426f-bf47-01ac1977026e', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'The mode of heat transfer that does NOT require any material medium and can travel through a vacuum (such as sunlight reaching Earth) is called:', 'Thermal radiation propagates as electromagnetic infrared photons across spatial vacuum.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('450459d6-8d1c-4a8b-b048-b30743e4b679', 'Radiation', true, '2ec3cc18-3434-426f-bf47-01ac1977026e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('729c3bd3-f115-4a6a-a7d3-d87382ccc821', 'Conduction', false, '2ec3cc18-3434-426f-bf47-01ac1977026e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d4cf98b-7a06-45eb-a520-8766910ee882', 'Convection', false, '2ec3cc18-3434-426f-bf47-01ac1977026e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c3c64c2-c761-4f3b-9db9-b7bdc7e46481', 'Advection', false, '2ec3cc18-3434-426f-bf47-01ac1977026e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2a7ce10-27b0-4cd0-89f6-38100327a667', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'In coastal areas during the DAYTIME, cool breeze blowing from the sea towards the land is called:', 'During the day, land heats faster than water, creating lower pressure that draws cool oceanic air inland as Sea Breeze.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38f99783-07fc-4791-8e10-bb8809078982', 'Sea Breeze', true, 'c2a7ce10-27b0-4cd0-89f6-38100327a667');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce98416e-e5b9-46ab-ab59-05cf888762da', 'Land Breeze', false, 'c2a7ce10-27b0-4cd0-89f6-38100327a667');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('109b1324-16bd-4156-8358-db10d3e11f1c', 'Monsoon', false, 'c2a7ce10-27b0-4cd0-89f6-38100327a667');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b62f7e86-90f2-47a3-9d57-967822d00588', 'Cyclone', false, 'c2a7ce10-27b0-4cd0-89f6-38100327a667');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e325157-e37a-4767-b038-f2dc002ca397', 'Class 7', 'Science', 'Chapter 3: Heat', 'Easy', 'In coastal areas during the NIGHT-TIME, cool breeze blowing from the land towards the sea is called:', 'At night, land cools faster than the sea, so air over warmer ocean rises and cool land air flows seaward as Land Breeze.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a830b19-a015-4c19-a3f2-84436177cd8e', 'Land Breeze', true, '6e325157-e37a-4767-b038-f2dc002ca397');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('888bf6a4-b98b-4b3f-87c5-5a99f07321ec', 'Sea Breeze', false, '6e325157-e37a-4767-b038-f2dc002ca397');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06708b31-537f-4dee-80a5-9f67b847c042', 'Trade Wind', false, '6e325157-e37a-4767-b038-f2dc002ca397');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f74745a3-d2b8-4cb1-b52a-b16fc1f031ba', 'Tornado', false, '6e325157-e37a-4767-b038-f2dc002ca397');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b686af46-01b9-4b86-ab39-17bcd9b5b597', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'What is the structural purpose of the tiny ''Kink'' (constriction) in the capillary tube just above the bulb of a traditional mercury clinical thermometer?', 'The capillary kink introduces mechanical surface tension resistance, preserving the peak mercury reading.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e9eb083-212c-4ef1-84ca-f46156d772d1', 'It prevents the mercury level from falling down on its own when removed from the patient''s mouth, allowing accurate reading', true, 'b686af46-01b9-4b86-ab39-17bcd9b5b597');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7633d099-4d57-45c2-8d06-08ddfb7986d2', 'It makes the mercury flow faster', false, 'b686af46-01b9-4b86-ab39-17bcd9b5b597');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('184bfbb3-623c-4121-b1b1-896a11c65c06', 'It prevents the thermometer from breaking', false, 'b686af46-01b9-4b86-ab39-17bcd9b5b597');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d9d08dd-8f54-4ba4-a2cf-73bc224c6661', 'It colors the mercury silver', false, 'b686af46-01b9-4b86-ab39-17bcd9b5b597');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04d06363-77d6-4feb-a6b4-e8eced7944c8', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why should a clinical thermometer NEVER be washed or sterilized in boiling hot water?', 'High hydrothermal thermal expansion overpressurizes the narrow sealed glass bore, risking explosive rupture.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('400d812e-05fb-4e27-a511-668a2c17e355', 'Boiling water (100°C) far exceeds the 42°C upper limit; extreme mercury thermal expansion will shatter the glass capillary bulb', true, '04d06363-77d6-4feb-a6b4-e8eced7944c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2e24e77-2372-4890-96d1-d665293c932f', 'Because hot water turns mercury into water', false, '04d06363-77d6-4feb-a6b4-e8eced7944c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69ca73dc-2a52-42e7-85be-137d735104ab', 'Because boiling water erases the painted numbers', false, '04d06363-77d6-4feb-a6b4-e8eced7944c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5dee380-854e-40ef-9069-61df5728c61c', 'Because glass melts at 100°C', false, '04d06363-77d6-4feb-a6b4-e8eced7944c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9bf0a95b-60ff-4757-a777-ef23e19cb310', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why are digital thermometers rapidly replacing traditional mercury glass thermometers in clinics and homes?', 'Elemental mercury is a potent neurotoxin; digital thermistors eliminate breakage contamination hazards.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64c6be55-24fb-4dc5-b79d-34c4a0ed90db', 'Mercury is a toxic, hazardous heavy metal that is extremely difficult to dispose of safely if the glass thermometer breaks', true, '9bf0a95b-60ff-4757-a777-ef23e19cb310');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d4fe82b-012c-4b63-b236-1602baca8159', 'Digital thermometers use laser light', false, '9bf0a95b-60ff-4757-a777-ef23e19cb310');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f46f034d-9bee-4a89-8270-5cf5df26afdf', 'Mercury has stopped being manufactured worldwide', false, '9bf0a95b-60ff-4757-a777-ef23e19cb310');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('940dd7f3-bd26-483c-8a7d-a442a422e7d6', 'Digital thermometers are made of pure gold', false, '9bf0a95b-60ff-4757-a777-ef23e19cb310');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a19c95bb-7106-4db6-985f-d854824300cd', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why do we prefer to wear light-colored or white clothes in hot summer and dark/black clothes in cold winter?', 'High albedo white surfaces reflect incident thermal radiation, while black surfaces have high infrared emissivity and absorptivity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5188e267-3594-413a-aff8-29f1f91c349f', 'Light-colored clothes reflect most radiant heat keeping us cool; dark clothes absorb more radiant heat keeping us warm', true, 'a19c95bb-7106-4db6-985f-d854824300cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7474d99f-b18e-40c4-91ac-fb03246ec82c', 'White clothes are lighter in physical weight', false, 'a19c95bb-7106-4db6-985f-d854824300cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b70c3d8-7ac2-4c75-a5fc-77a4da57ff81', 'Dark clothes produce their own electricity', false, 'a19c95bb-7106-4db6-985f-d854824300cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2b05a94-067f-45ad-9d3e-d694ae86ac75', 'Light colors keep mosquitoes away', false, 'a19c95bb-7106-4db6-985f-d854824300cd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4dcfaa2-b1b1-45d7-b97e-18c12f84ed69', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why does wearing TWO thin woolen sweaters keep us significantly WARMER in winter than wearing one single thick woolen sweater of equal thickness?', 'Trapped air gaps provide high boundary-layer thermal insulation due to air''s low thermal conductivity (k ≈ 0.026 W/m·K).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('423f0775-15e9-4b8c-af0c-0807acd40975', 'A layer of still air is trapped between the two thin sweaters; air is an excellent thermal insulator that prevents body heat from escaping', true, 'f4dcfaa2-b1b1-45d7-b97e-18c12f84ed69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6cab6d7-0f79-458f-abe3-32d1b96bd669', 'Two sweaters create friction that generates fire', false, 'f4dcfaa2-b1b1-45d7-b97e-18c12f84ed69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b849484f-ed7e-447f-a347-e2a9877928c4', 'Two sweaters weigh twice as much', false, 'f4dcfaa2-b1b1-45d7-b97e-18c12f84ed69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d78a93fe-b1ac-4c43-97d5-7f10bc594df5', 'One thick sweater attracts cold radiation', false, 'f4dcfaa2-b1b1-45d7-b97e-18c12f84ed69');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19af3039-8034-40e8-bd1d-20369708461c', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why are cooking utensils (like frying pans) made of metals like aluminium or stainless steel, but their handles are made of bakelite plastic or wood?', 'Engineered thermal partitioning: metallic cooking vessel conducts heat to food while thermoset bakelite handles insulate user grasp.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e7a4507-4e42-4d07-927b-b2611ea269d3', 'Metal pans conduct heat quickly to cook food, while plastic/wooden handles are poor conductors (insulators) allowing safe handling without burning hands', true, '19af3039-8034-40e8-bd1d-20369708461c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('705b2b3a-2ffa-4346-a36a-87e6ab1e2f91', 'Because plastic is too heavy to make pans', false, '19af3039-8034-40e8-bd1d-20369708461c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bee14f8-32b7-4519-809a-a04c0cd7762b', 'Because wood melts on fire', false, '19af3039-8034-40e8-bd1d-20369708461c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fb44cc1-d9cb-4e01-99cc-e78246d34a23', 'Because metal looks shiny', false, '19af3039-8034-40e8-bd1d-20369708461c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('21fc5eef-8a75-47dc-9e96-0b001a73d1a6', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'When heating water in a round-bottom flask, why does water at the bottom rise to the top while cold water from the sides moves downwards?', 'Thermal volumetric expansion reduces fluid density, initiating buoyancy-driven Rayleigh-Bénard convection loops.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96af0c13-fca4-4a7f-bbfd-79054effadb2', 'Heated water expands, becomes less dense (lighter), and rises; cooler, denser water from sides sinks to replace it, setting up Convection Currents', true, '21fc5eef-8a75-47dc-9e96-0b001a73d1a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('746e2ae8-83f0-4846-8071-0245154763f4', 'Heated water becomes heavier', false, '21fc5eef-8a75-47dc-9e96-0b001a73d1a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('431bb70d-ae6a-4a4e-b0e8-c39c9c26a2b9', 'Bubbles push the water down', false, '21fc5eef-8a75-47dc-9e96-0b001a73d1a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eac5a940-5011-41e7-81e4-c444f3cc8b61', 'Water molecules repel heat', false, '21fc5eef-8a75-47dc-9e96-0b001a73d1a6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06d95549-3de1-48c0-8fd1-6f8804034664', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why is a laboratory thermometer kept strictly vertical and read while ITS BULB IS STILL IMMERSED in the substance being measured?', 'Lacking a retentive kink, laboratory thermometers respond instantly to ambient thermal shifts upon removal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04111ce6-a31e-4961-99b4-6259c6f66350', 'Because it has NO kink; the moment it is removed from the substance, its mercury level immediately starts dropping or rising due to ambient air', true, '06d95549-3de1-48c0-8fd1-6f8804034664');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1246514f-2510-4318-ab26-8f3317a3c0ed', 'Because tilting breaks the glass', false, '06d95549-3de1-48c0-8fd1-6f8804034664');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f42a1ce-4c98-4abe-99fa-d5f4e119aa77', 'Because mercury evaporates outside', false, '06d95549-3de1-48c0-8fd1-6f8804034664');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ad39dac-9701-473d-ab1e-acc9c75d0033', 'Because laboratory thermometers only work under water', false, '06d95549-3de1-48c0-8fd1-6f8804034664');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e38d133-985e-4a0a-be93-7a6534ec47e8', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why do houses in hot tropical climates have their outer walls painted WHITE or light pastel colors?', 'Passive architectural cooling: high solar reflectance index (SRI) coatings minimize thermal envelope heat gain.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24c883bc-50de-4aa8-b9fc-52797975973c', 'White walls reflect the majority of incoming solar radiant heat, keeping the interiors significantly cooler', true, '7e38d133-985e-4a0a-be93-7a6534ec47e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42a5280c-d43b-43b0-8a71-79484a80f89c', 'White paint is waterproof only', false, '7e38d133-985e-4a0a-be93-7a6534ec47e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cd1e475-1bff-40cf-9e0a-42ea0d4e81b9', 'To make houses look bigger', false, '7e38d133-985e-4a0a-be93-7a6534ec47e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86da362e-bec9-4fd1-a77d-cd4120f121a0', 'White paint repels wind', false, '7e38d133-985e-4a0a-be93-7a6534ec47e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c97db7cd-289b-4d93-aadd-0ba9f0bdcc90', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why do rooms have electric room heaters placed on the floor and air-conditioners installed near the ceiling?', 'Optimized convective atmospheric circulation: dense chilled air descends while buoyant warm air ascends.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2cfd947-0451-4b5d-8016-e64c60d31373', 'Heated air expands, rises up to warm the whole room via convection; cold air from AC is dense and sinks down to cool the living space', true, 'c97db7cd-289b-4d93-aadd-0ba9f0bdcc90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24e5ae36-3462-4154-aa52-581c46617eed', 'To keep AC out of reach of children', false, 'c97db7cd-289b-4d93-aadd-0ba9f0bdcc90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d2aff0f-009b-46ec-a011-7381e6527231', 'Because heaters look better on floors', false, 'c97db7cd-289b-4d93-aadd-0ba9f0bdcc90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e70c036-f6a5-4ef4-8cbc-0e00c8a00b1a', 'Because ceilings are always hotter than floors', false, 'c97db7cd-289b-4d93-aadd-0ba9f0bdcc90');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34360453-8628-4924-8855-76a98306914a', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why does a metal chair feel much COLDER to touch than a wooden table in the same room during cold winter mornings?', 'Both objects are at thermal equilibrium; metal feels colder due to its high thermal effusivity rapidly conducting hand heat away.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10b1c37e-bf3e-4185-b32f-6ec3277dc1b9', 'Metal is a good conductor that rapidly draws heat away from your hand; wood is an insulator that conducts heat very slowly', true, '34360453-8628-4924-8855-76a98306914a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3649d55c-4dcf-4127-aa5f-46c1a24d1edd', 'The metal chair is actually at a lower temperature than the wooden table', false, '34360453-8628-4924-8855-76a98306914a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a010f4ba-01b4-43ba-ae3e-b5ccd84d67f8', 'Wood produces its own internal heat', false, '34360453-8628-4924-8855-76a98306914a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49cf0ac3-7355-497e-9c90-0fb1a52e16ae', 'Metal absorbs cold from the floor', false, '34360453-8628-4924-8855-76a98306914a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db35193c-9a6d-4186-b893-0b387f91931a', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'How does a double-walled thermos flask keep hot tea hot and cold water cold for hours?', 'Dewar flask design eliminates conduction/convection via evacuating interstitial air and halts radiation via reflective silvering.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('610a22ab-a141-470d-84dc-26d26d4d491f', 'A vacuum between double glass walls eliminates conduction and convection, while silvery mirrored surfaces reflect radiant heat back', true, 'db35193c-9a6d-4186-b893-0b387f91931a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c64a7f43-eeb8-4f63-948a-3296143a6ba6', 'It contains an internal battery heater', false, 'db35193c-9a6d-4186-b893-0b387f91931a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7397c4a2-4d4c-403e-9958-16271e8e2a51', 'It is made of thick lead', false, 'db35193c-9a6d-4186-b893-0b387f91931a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fe72bdc-d41b-47f9-a810-7e42821ed5ed', 'It freezes air around it', false, 'db35193c-9a6d-4186-b893-0b387f91931a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b666b41d-99ec-4c36-86ca-a9c3edcea2f4', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'What happens when you hold one hand above a burning candle flame and one hand on the side of the flame?', 'Thermal buoyancy channels convective heat plumes vertically above the flame; lateral heat transfer occurs solely by radiation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f62ffede-8302-41c1-9359-0edd5d3cfe4b', 'The hand above the flame feels much hotter because air above is heated by CONVECTION currents rising upward; the side hand feels only mild radiation', true, 'b666b41d-99ec-4c36-86ca-a9c3edcea2f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15089598-0d8b-44be-8d0e-3f5b6478a516', 'Both hands feel exactly the same heat', false, 'b666b41d-99ec-4c36-86ca-a9c3edcea2f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4537ec3-c8eb-4098-bc05-a0d3af7453a5', 'The side hand feels hotter', false, 'b666b41d-99ec-4c36-86ca-a9c3edcea2f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ad6e3e0-82e5-455a-96d7-b21f96f2a31f', 'Neither hand feels any heat', false, 'b666b41d-99ec-4c36-86ca-a9c3edcea2f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da5db607-e876-4780-8e3f-4fc019c67c8e', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'What is the relationship between Celsius (°C) and Fahrenheit (°F) temperature scales?', 'Linear thermometric conversion equation: °F = (°C × 9/5) + 32.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6312ff8f-cbea-4396-880c-3e9989f4a01d', 'F = (9/5 × C) + 32', true, 'da5db607-e876-4780-8e3f-4fc019c67c8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e03b555e-74f9-4fec-a2e1-76807397932e', 'F = (5/9 × C) - 32', false, 'da5db607-e876-4780-8e3f-4fc019c67c8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1e4388d-ae1c-493e-894b-b0f5d2af1dad', 'F = C + 100', false, 'da5db607-e876-4780-8e3f-4fc019c67c8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f7909cb-99f5-49aa-9c92-29a2ba362ff7', 'F = 2C + 32', false, 'da5db607-e876-4780-8e3f-4fc019c67c8e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('229f86d8-f92d-439f-b244-51166625a0fa', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'Why does wool fiber provide superior thermal warmth in winter garments?', 'Crimp morphology in wool keratin fibers creates macroscopic porous dead-air insulation lattices.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1513e0e3-5848-4de6-9937-288cc41d1394', 'Wool fibers have natural crimp/curls that trap substantial air pockets, and air is a poor conductor that traps body heat', true, '229f86d8-f92d-439f-b244-51166625a0fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a13f4aff-b23d-4c92-bbed-52f5e2d206e6', 'Wool produces chemical heat', false, '229f86d8-f92d-439f-b244-51166625a0fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85597ab5-57d2-4591-96d3-1697b4f64851', 'Wool absorbs sunlight into blood', false, '229f86d8-f92d-439f-b244-51166625a0fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62194bdf-af28-49c0-92aa-117c4b1a4782', 'Wool is a heavy metal', false, '229f86d8-f92d-439f-b244-51166625a0fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ce7a7436-d311-4bc2-8117-cf3766cf6a63', 'Class 7', 'Science', 'Chapter 3: Heat', 'Medium', 'What is ''Thermal Equilibrium'' between two contacting bodies?', 'Zeroth Law of Thermodynamics: thermal equilibrium is attained when thermodynamic temperature gradient equals zero (dT/dx = 0).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5d7a1dc-2339-40b0-a47d-14dc33cae4bf', 'The state where both bodies reach the exact same temperature, resulting in zero net transfer of heat energy between them', true, 'ce7a7436-d311-4bc2-8117-cf3766cf6a63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df383a5b-3389-4074-b837-851bfca33510', 'When both bodies melt', false, 'ce7a7436-d311-4bc2-8117-cf3766cf6a63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('711c8d00-b6d9-4579-95bb-c32317b5961a', 'When one body freezes the other', false, 'ce7a7436-d311-4bc2-8117-cf3766cf6a63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2f3dbc6-2f7b-45d6-a986-34d283b38917', 'When heat doubles in both bodies', false, 'ce7a7436-d311-4bc2-8117-cf3766cf6a63');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c1bce13-28a1-48d3-b424-be06cedef740', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('237ae28d-e111-4852-8ac9-29a9d0e670bf', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '4c1bce13-28a1-48d3-b424-be06cedef740');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b921b60-6282-46d5-b537-04c11bec9c27', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '4c1bce13-28a1-48d3-b424-be06cedef740');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b505061-a9d5-4fba-b052-0213245fbc27', '(A) is true, but (R) is false.', false, '4c1bce13-28a1-48d3-b424-be06cedef740');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a72cb442-0454-4907-a079-18be01bc1460', '(A) is false, but (R) is true.', false, '4c1bce13-28a1-48d3-b424-be06cedef740');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7aeccdbc-0a59-4137-9a2c-5a23e6d1ee37', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'Spot the IMPOSTER in the following group of heat transfer mechanisms and examples:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67c1705a-e5a5-41f4-a1f2-1db279e0a1d5', 'Example 1', false, '7aeccdbc-0a59-4137-9a2c-5a23e6d1ee37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e92d9db8-5238-4f0e-b044-ade6ef8091b9', 'Example 2', false, '7aeccdbc-0a59-4137-9a2c-5a23e6d1ee37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('559d9fc2-6ab2-4824-9994-5c9b0241fcad', 'Example 3', false, '7aeccdbc-0a59-4137-9a2c-5a23e6d1ee37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58ecb52e-16c8-4743-945c-5e86bedb0c8f', 'Example 4 (Circulating boiling water transfers heat by CONVECTION, not conduction)', true, '7aeccdbc-0a59-4137-9a2c-5a23e6d1ee37');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62079e58-585b-47ae-aeec-8c42a56e064f', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'A copper rod has wax drops fixed at intervals of 5 cm along its length with thumbtacks attached. The other end is heated over a burner flame. What is observed?', 'Fourier''s Law of Heat Conduction: thermal flux diffuses progressively along the longitudinal temperature gradient.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf9f7dea-3fbf-4ac1-80a9-3df3e3e7b80f', 'The wax drop closest to the burner flame melts first and its tack falls off, followed sequentially by successive drops, demonstrating linear thermal conduction along solids', true, '62079e58-585b-47ae-aeec-8c42a56e064f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1709a934-07d3-4d50-bf6c-8d1f9bc5f2cf', 'All wax drops melt simultaneously at the exact same second', false, '62079e58-585b-47ae-aeec-8c42a56e064f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c4bc12f-a7e8-4d2c-b903-60830de1aeb1', 'The farthest wax drop melts first', false, '62079e58-585b-47ae-aeec-8c42a56e064f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bced605-cb3d-4c9a-a8b9-945b201b4f5e', 'None of the wax drops melt', false, '62079e58-585b-47ae-aeec-8c42a56e064f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd7473d7-839e-4315-9dda-9beb57e6ed09', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'Match Column I (Thermal Concepts) with Column II (Scientific Principles):
(a) Clinical Thermometer -> (i) Has capillary kink & spans 35°C to 42°C
(b) Laboratory Thermometer-> (ii) Measures -10°C to 110°C without kink
(c) Sea Breeze            -> (iii) Daytime oceanic convective airflow to land
(d) Radiation             -> (iv) Infrared electromagnetic heat transfer without medium', 'Clinical = kink/35-42°C; Lab = -10-110°C; Sea breeze = daytime onshore; Radiation = electromagnetic vacuum transfer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48cba3f4-b218-45ca-a63a-8b85ccf5de9e', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'cd7473d7-839e-4315-9dda-9beb57e6ed09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f16708c-951b-4dc1-adfa-bfcb3463b67d', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'cd7473d7-839e-4315-9dda-9beb57e6ed09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab2bca90-9515-4a81-8d7b-d24460ef29e1', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'cd7473d7-839e-4315-9dda-9beb57e6ed09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7131a62f-6964-4cbb-a2c5-58b810b74cb7', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'cd7473d7-839e-4315-9dda-9beb57e6ed09');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c28523b-10a8-44ef-a2df-3aef6d5167d4', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'Read the statements regarding thermometry:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e9ed7c0-b206-4a87-b360-c2fa83baacc5', 'Statements 1 and 2 only', true, '1c28523b-10a8-44ef-a2df-3aef6d5167d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b10fde8f-e2ff-4353-9bcf-db07aa87bdfa', 'Statements 2 and 3 only', false, '1c28523b-10a8-44ef-a2df-3aef6d5167d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6e4a0ba-5457-4db4-82fb-5089db2cea26', 'Statements 1 and 3 only', false, '1c28523b-10a8-44ef-a2df-3aef6d5167d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a86f7f1d-a456-4041-96f0-8d717239deb5', 'All Statements 1, 2, and 3', false, '1c28523b-10a8-44ef-a2df-3aef6d5167d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5dca705a-5e23-498f-bc6e-f44d5dd1af7a', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'Why are stainless steel cooking pans frequently manufactured with a bonded COPPER BOTTOM plate?', 'Thermal conductivity of copper (k ≈ 385 W/m·K) exceeds stainless steel (k ≈ 15 W/m·K) by ~25×, eliminating localized hot spots.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed663667-9ce1-4c71-9d32-139da78349c1', 'Copper has much higher thermal conductivity than stainless steel, distributing heat uniformly across the base and eliminating localized food burning', true, '5dca705a-5e23-498f-bc6e-f44d5dd1af7a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4b62b38-cb59-4b20-a880-469370eeba81', 'Copper makes the pan heavier so it does not shake', false, '5dca705a-5e23-498f-bc6e-f44d5dd1af7a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6593195e-5369-4262-98b7-7e403514ebd7', 'Copper changes the color of food', false, '5dca705a-5e23-498f-bc6e-f44d5dd1af7a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eec82e1e-8335-4431-b443-58b7f108b8c7', 'Copper stops water from boiling', false, '5dca705a-5e23-498f-bc6e-f44d5dd1af7a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('815cc3e7-74a5-406a-a4f9-bf638b08bd1e', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'If 1 litre of water at 30°C is mixed thoroughly with 1 litre of water at 50°C in an insulated vessel, what will be the final equilibrium temperature?', 'Principle of Calorimetry for equal masses of identical fluid: T_final = (30 + 50) / 2 = 40°C.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d836505-7542-43c3-9d05-93a071adaba1', 'Between 30°C and 50°C (specifically 40°C)', true, '815cc3e7-74a5-406a-a4f9-bf638b08bd1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50074441-e7e5-459b-affb-edc2891bbf94', '80°C (30 + 50)', false, '815cc3e7-74a5-406a-a4f9-bf638b08bd1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b62f6c8a-f95e-4d06-9e01-25fcb5bdaf81', '20°C (50 - 30)', false, '815cc3e7-74a5-406a-a4f9-bf638b08bd1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('967665b6-0142-4918-83f9-0f6158258299', 'More than 50°C', false, '815cc3e7-74a5-406a-a4f9-bf638b08bd1e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0fceff54-7db6-4a58-ac50-34c8ffbcee89', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'An iron ball at 40°C is dropped into a mug containing water at 40°C. How will heat flow?', 'Thermal energy transfer requires a finite temperature gradient (ΔT ≠ 0); since ΔT = 0, net heat flux is zero.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6ac5ecf-1aa0-4b17-a268-6a2fa5c1ee7e', 'Heat will NOT flow from iron ball to water or from water to iron ball (Zero net heat flow due to thermal equilibrium)', true, '0fceff54-7db6-4a58-ac50-34c8ffbcee89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb5c8c6d-2fd2-4d70-a2a4-085f319943c0', 'Heat will flow from iron ball to water', false, '0fceff54-7db6-4a58-ac50-34c8ffbcee89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7802f60-da6c-4f10-b96b-6e65792c20b2', 'Heat will flow from water to iron ball', false, '0fceff54-7db6-4a58-ac50-34c8ffbcee89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca91b1d4-2f5e-4173-91be-dd7d1972b2ea', 'The temperature of both will increase to 80°C', false, '0fceff54-7db6-4a58-ac50-34c8ffbcee89');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1fb8cce1-a48a-4727-aeac-fc76c61aeddb', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'Why do birds fluff up their feathers during freezing winter mornings?', 'Piloerection expands boundary-layer air entrapment, increasing effective thermal resistance against ambient cold.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3122835-6cdb-48e8-a760-1d51913a0319', 'Fluffing feathers traps a thicker layer of stationary insulating air between plumage barbules, reducing convective and conductive body heat loss', true, '1fb8cce1-a48a-4727-aeac-fc76c61aeddb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f39d2d58-9341-409a-aecd-dbf9769383f6', 'To make themselves look bigger to predators', false, '1fb8cce1-a48a-4727-aeac-fc76c61aeddb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49356a10-1db5-4eb0-a291-d2178a025425', 'To absorb more rain', false, '1fb8cce1-a48a-4727-aeac-fc76c61aeddb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90109822-d08f-4981-aad8-7048acb0ad05', 'Because feathers become heavier in cold', false, '1fb8cce1-a48a-4727-aeac-fc76c61aeddb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f8cc38b5-ac87-493d-a0a2-85c144cc183d', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'Consider four identical metal blocks (Copper, Aluminium, Iron, Lead) of equal mass heated to 100°C and placed on a slab of ice. Which block melts the most ice?', 'Heat released Q = m·c·ΔT. Aluminium possesses the highest specific heat capacity (c ≈ 900 J/kg·K), yielding greatest enthalpy to melt ice.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6527bcd-b9d4-443d-a88d-505df04166f1', 'The block with the HIGHEST Specific Heat Capacity (Aluminium melts the most ice because it stores more thermal energy per unit mass)', true, 'f8cc38b5-ac87-493d-a0a2-85c144cc183d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b26b485-50a2-4eb4-8e30-e532d89f98ea', 'Lead block', false, 'f8cc38b5-ac87-493d-a0a2-85c144cc183d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd0bcb0f-1f86-4f39-9fcb-1577b5c38915', 'Iron block', false, 'f8cc38b5-ac87-493d-a0a2-85c144cc183d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7da82af8-74bb-4a83-b193-b76c948d2da5', 'All four melt the exact same amount of ice', false, 'f8cc38b5-ac87-493d-a0a2-85c144cc183d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b1e1691a-992f-4f1c-a161-d225a1cf9df6', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'Why does the greenhouse effect trap heat inside a glass greenhouse or parked closed car in the sun?', 'Spectral selectivity: shortwave solar photons penetrate glass, heating interior surfaces which re-radiate longwave IR blocked by glass.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40e8f63f-aa07-4caa-8575-cdcfa6d1c08a', 'Glass is transparent to short-wavelength solar radiant light but opaque to long-wavelength infrared thermal radiation emitted by interior surfaces, trapping heat energy inside', true, 'b1e1691a-992f-4f1c-a161-d225a1cf9df6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e88e9f88-6139-4d66-9297-23513853b71a', 'Glass produces heat from carbon dioxide', false, 'b1e1691a-992f-4f1c-a161-d225a1cf9df6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f82447a8-5c6e-406a-ba1f-72f6f6262009', 'Because glass turns sunlight into hot water', false, 'b1e1691a-992f-4f1c-a161-d225a1cf9df6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48c44ac0-79bc-487d-a0b4-6686e4c92866', 'Because car metal generates electricity', false, 'b1e1691a-992f-4f1c-a161-d225a1cf9df6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e86ae1a-2a84-45c1-aa72-a06ae8dc160c', 'Class 7', 'Science', 'Chapter 3: Heat', 'Hard', 'What fundamental thermodynamic principle summarizes Chapter 3 of NCERT Class 7 Science?', 'Chapter 3 provides an integrated thermodynamic foundation: modes of heat transfer, thermometry, meteorological breeze circulation, and thermal engineering.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c0c83c9-38ba-46e6-b98d-4be2343fa47a', 'Heat is thermal energy in transit driven by temperature differentials, propagating via Conduction in solids, Convection in fluids, and Radiation through vacuum, governing terrestrial weather, thermal insulation, and life adaptation', true, '7e86ae1a-2a84-45c1-aa72-a06ae8dc160c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7184bf98-3ddd-4f04-8f03-b2b0057d09b8', 'Heat and temperature are identical concepts', false, '7e86ae1a-2a84-45c1-aa72-a06ae8dc160c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2993732-a381-4a23-b219-8137c4028381', 'Heat only travels in metal wires', false, '7e86ae1a-2a84-45c1-aa72-a06ae8dc160c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b66099db-a50f-4394-8d95-9919145701e3', 'Vacuum can conduct heat by convection', false, '7e86ae1a-2a84-45c1-aa72-a06ae8dc160c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4672419-38fc-469c-b261-e9f0cc673e93', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Easy', 'The sum of all observations divided by the total number of observations is called the:', 'Mean = (Sum of all observations) / (Total number of observations).', NOW()) ON CONFLICT DO NOTHING;
