INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('39bd0dd8-9e54-4818-ba3b-e0208b8a7a5e', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Easy', 'Find the Arithmetic Mean of the first five Natural Numbers: 1, 2, 3, 4, 5:', 'Mean = (1+2+3+4+5)/5 = 15/5 = 3.', NOW()) ON CONFLICT DO NOTHING;
