INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('af7cfb69-c3e7-437e-ac7b-bf74f7479b7b', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Easy', 'Find the Range of the dataset: 32, 41, 28, 54, 35, 26, 33, 23, 38, 40:', 'Range = Max - Min = 54 - 23 = 31.', NOW()) ON CONFLICT DO NOTHING;
