INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('54c09961-b439-4405-a388-e2bdb6d11fb5', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Easy', 'What is the Probability (P) of tossing a fair coin and getting ''HEADS''?', 'P(Head) = 1/2 = 0.5.', NOW()) ON CONFLICT DO NOTHING;
