INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('510aec4e-cd7d-48b4-a592-b74577587b54', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Easy', 'When rolling a standard 6-sided die, what is the probability of rolling a number GREATER than 4 (i.e. 5 or 6)?', 'Favourable outcomes = {5, 6} (2 numbers). P = 2/6 = 1/3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85ac8a66-fdd2-4722-9b30-bf810af97455', '2/6 = 1/3 (Favourable: {5, 6} = 2 outcomes)', true, '510aec4e-cd7d-48b4-a592-b74577587b54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6face348-0d58-4146-a309-4aab80a951b0', '1/2', false, '510aec4e-cd7d-48b4-a592-b74577587b54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc0e42bc-ad29-4a92-83a0-87b550054e96', '1/6', false, '510aec4e-cd7d-48b4-a592-b74577587b54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b809511-2352-432b-8926-cda761adf29d', '4/6', false, '510aec4e-cd7d-48b4-a592-b74577587b54');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fa4c0ef-5dd7-4b99-97a4-41a630671494', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'A batsman scored the following runs in six innings: 36, 35, 50, 46, 60, 55. Calculate his Mean run score:', 'Total runs = 282. Innings = 6. Mean = 282 ÷ 6 = 47 runs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('453b3e44-6e05-4e9f-aa05-d674b73312d0', '47 runs ((36 + 35 + 50 + 46 + 60 + 55) / 6 = 282 / 6 = 47)', true, '7fa4c0ef-5dd7-4b99-97a4-41a630671494');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c4e73b9-d94c-4c07-b79c-0cae23cb35f5', '45 runs', false, '7fa4c0ef-5dd7-4b99-97a4-41a630671494');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0f516dd-90a3-4bd2-b1d0-0176f07c4e6c', '50 runs', false, '7fa4c0ef-5dd7-4b99-97a4-41a630671494');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a3fa7d1-c4ec-43cd-a069-d6e1173c26be', '48 runs', false, '7fa4c0ef-5dd7-4b99-97a4-41a630671494');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('40e6fe3c-6fec-4fbe-a64c-54bfd5687ace', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'The scores in mathematics test (out of 25) of 15 students are:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('421dd270-8066-41ad-ac89-c9387da36320', 'Mode = 20 (appears 4 times) ; Median = 20 (8th value in ordered list)', true, '40e6fe3c-6fec-4fbe-a64c-54bfd5687ace');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efab910a-7d60-44b5-865d-601879229e7f', 'Mode = 25 ; Median = 20', false, '40e6fe3c-6fec-4fbe-a64c-54bfd5687ace');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e503172a-8bdc-4a8d-910f-2928b20f9dff', 'Mode = 20 ; Median = 19', false, '40e6fe3c-6fec-4fbe-a64c-54bfd5687ace');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47900860-8763-4394-b802-80fddae1fd22', 'Mode = 20 ; Median = 23', false, '40e6fe3c-6fec-4fbe-a64c-54bfd5687ace');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9c98906-6347-4e85-b4f2-a1877680f871', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'The runs scored in a cricket match by 11 players are: 6, 15, 120, 50, 100, 80, 10, 15, 8, 10, 15.
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73d8b899-f096-4c52-87f8-7f5ccc2d929e', 'Mean = 39, Mode = 15, Median = 15', true, 'a9c98906-6347-4e85-b4f2-a1877680f871');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c81df85a-20bb-4878-926a-e7bf9ca2bafb', 'Mean = 45, Mode = 15, Median = 10', false, 'a9c98906-6347-4e85-b4f2-a1877680f871');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('349eecb5-c4f1-4f90-9b67-b994e4d43f98', 'Mean = 39, Mode = 10, Median = 15', false, 'a9c98906-6347-4e85-b4f2-a1877680f871');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06608dae-8303-4079-9d4a-af83304409e8', 'Mean = 50, Mode = 15, Median = 20', false, 'a9c98906-6347-4e85-b4f2-a1877680f871');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e7216b86-8105-46ad-8e52-aa2ff44b3f14', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'Can a dataset have MORE than one Mode (e.g. Bimodal or Multimodal data)?', 'Distributions with multiple distinct equal peak frequencies are bimodal or multimodal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f29f0a3-b127-49ef-b97c-1c4ec78bb901', 'Yes, if two or more observations share the highest frequency equally (e.g. in 2, 2, 3, 3, 4, both 2 and 3 are modes)', true, 'e7216b86-8105-46ad-8e52-aa2ff44b3f14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acae9887-533a-4e21-9bc5-09093f09dd83', 'No, data can only ever have one mode', false, 'e7216b86-8105-46ad-8e52-aa2ff44b3f14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca5c6e13-e2f6-4402-897a-8d53228b2101', 'Only if the data contains negative numbers', false, 'e7216b86-8105-46ad-8e52-aa2ff44b3f14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfa0241f-1ff0-404c-a427-ff8d5987b22e', 'Only when data has zero observations', false, 'e7216b86-8105-46ad-8e52-aa2ff44b3f14');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('12c4309a-01ce-4b17-860d-6f0f87205b21', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'The weights (in kg) of 15 students of a class are:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dc5884b-41dc-4c6f-b0da-5a6be255e98c', '38 kg and 43 kg (Both occur 3 times each - Bimodal dataset)', true, '12c4309a-01ce-4b17-860d-6f0f87205b21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('519d546d-18bd-447e-ac59-ca12c24c1bf8', 'Only 38 kg', false, '12c4309a-01ce-4b17-860d-6f0f87205b21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85125f82-9270-4e3a-8a76-ab4c5855f7e0', 'Only 43 kg', false, '12c4309a-01ce-4b17-860d-6f0f87205b21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43199254-aa99-4ee2-9360-63145da967bc', '40 kg', false, '12c4309a-01ce-4b17-860d-6f0f87205b21');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('90d20d65-306b-4117-b84d-7832a47232d8', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'Find the Median of the first seven Prime Numbers: 2, 3, 5, 7, 11, 13, 17:', 'Ordered 7 primes: 2, 3, 5, 7, 11, 13, 17. Median = 4th value = 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00fd43eb-759d-45a4-9f58-22b4f9747682', '7 (The 4th middle observation in the prime sequence)', true, '90d20d65-306b-4117-b84d-7832a47232d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e87688ad-83f8-4860-9a76-2f746fdf3789', '5', false, '90d20d65-306b-4117-b84d-7832a47232d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7c960a9-c84a-4704-9a17-6f0e582d7292', '11', false, '90d20d65-306b-4117-b84d-7832a47232d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5ffea53-020d-480c-b25b-264722cfa944', '8.28', false, '90d20d65-306b-4117-b84d-7832a47232d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e88844d-aad6-47e9-946f-000366c1c16f', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'What is the Probability of an ''IMPOSSIBLE EVENT'' (such as rolling a 7 on a standard 6-sided die)?', 'An impossible event has 0 favourable outcomes; P(Impossible) = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bae46149-6299-464e-986d-f6bbfc37b24c', '0 (Zero)', true, '3e88844d-aad6-47e9-946f-000366c1c16f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('397b88ed-d74d-42cd-90c6-810eeac05d2e', '1', false, '3e88844d-aad6-47e9-946f-000366c1c16f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('714f6c7b-e2d7-424c-bb3c-eed5d8c5986d', '1/2', false, '3e88844d-aad6-47e9-946f-000366c1c16f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c98a5292-1f25-4c66-99a9-03d4d392b68c', '-1', false, '3e88844d-aad6-47e9-946f-000366c1c16f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cbd968da-4a68-4d15-96d6-11acf789a6fa', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'What is the Probability of a ''CERTAIN / SURE EVENT'' (such as the Sun rising in the East tomorrow)?', 'A certain event is guaranteed to occur; P(Sure) = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f27fa245-e216-4142-b586-61d1ccb5adde', '1 (One / 100% certainty)', true, 'cbd968da-4a68-4d15-96d6-11acf789a6fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b15d95ed-9186-49a8-91d4-023bfc4aa181', '0', false, 'cbd968da-4a68-4d15-96d6-11acf789a6fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('215b57ba-a86a-4418-95ce-f53296ab7c93', '0.5', false, 'cbd968da-4a68-4d15-96d6-11acf789a6fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4fa3c9e-d014-426e-b123-df810bbdb705', 'Infinity', false, 'cbd968da-4a68-4d15-96d6-11acf789a6fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('713e2bbb-e80c-4b1d-8531-7660076e1e4b', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'There are 6 marbles in a box with numbers from 1 to 6 marked on each of them. What is the probability of drawing a marble with number 2?', 'Favourable outcome = 1 (marble 2). Total = 6. P = 1/6.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc82c0da-2fbd-4bff-9fae-f106a624219b', '1/6', true, '713e2bbb-e80c-4b1d-8531-7660076e1e4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('353a8b51-ce58-4a67-9e92-73f41d5b15cd', '2/6 = 1/3', false, '713e2bbb-e80c-4b1d-8531-7660076e1e4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6885b5dc-3efd-430d-acd5-a793c232ddcf', '1/2', false, '713e2bbb-e80c-4b1d-8531-7660076e1e4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0a34031-b4ca-4c31-8ab3-8bb3307f74fd', '6/1', false, '713e2bbb-e80c-4b1d-8531-7660076e1e4b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5b6e9f2-e861-4a20-a55b-c764bd4da980', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'There are 6 marbles in a box numbered 1 to 6. What is the probability of drawing a marble with an EVEN number (2, 4, 6)?', 'Even outcomes = {2, 4, 6} (3 outcomes). P = 3/6 = 1/2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2900cdc8-9800-4982-923a-ad9a5a83d121', '3/6 = 1/2', true, 'c5b6e9f2-e861-4a20-a55b-c764bd4da980');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b4c5984-4cfa-4c7a-9e45-15fb9d4e2e72', '1/6', false, 'c5b6e9f2-e861-4a20-a55b-c764bd4da980');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0f3951a-b4b3-432c-ba86-59a03d09dc84', '2/6', false, 'c5b6e9f2-e861-4a20-a55b-c764bd4da980');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c7dc090-67e1-4665-8401-3fd58de137a8', '5/6', false, 'c5b6e9f2-e861-4a20-a55b-c764bd4da980');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b2f2641-bab1-49e3-82af-069027b22fd7', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'The Mean of 5 numbers is 20. If one number is excluded, their mean becomes 18. What is the excluded number?', 'Old sum = 5 × 20 = 100. New sum = 4 × 18 = 72. Excluded = 100 - 72 = 28.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65f465ba-6ba1-4a44-ae3c-8b02facee118', '28 (Sum of 5 numbers = 5 × 20 = 100 ; Sum of 4 numbers = 4 × 18 = 72 ; Excluded = 100 - 72 = 28)', true, '3b2f2641-bab1-49e3-82af-069027b22fd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c16d317f-ab0f-4836-aee4-7cd10f5f21ee', '24', false, '3b2f2641-bab1-49e3-82af-069027b22fd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6073e431-9850-411c-af28-f9f8750ebabd', '26', false, '3b2f2641-bab1-49e3-82af-069027b22fd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cc51c9a-bf89-49b1-9f24-36fe1eff24d1', '30', false, '3b2f2641-bab1-49e3-82af-069027b22fd7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dcf4d6d8-25ed-4b7e-90ab-573ee7ddb5d3', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'The Mean of 10 observations was calculated as 40. Later it was found that an observation 45 was misread as 15. What is the correct Mean?', 'Correct sum = 400 - 15 + 45 = 430. Correct mean = 430 ÷ 10 = 43.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('332b516f-8396-4f40-ae3f-626ab93bd474', '43 (Calculated sum = 400 ; Correct sum = 400 - 15 + 45 = 430 ; Correct mean = 430 / 10 = 43)', true, 'dcf4d6d8-25ed-4b7e-90ab-573ee7ddb5d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d428bc09-539e-4bdb-ba52-d428aa5e4227', '41.5', false, 'dcf4d6d8-25ed-4b7e-90ab-573ee7ddb5d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('816d52bf-9f57-4239-bd46-b1c336798239', '42', false, 'dcf4d6d8-25ed-4b7e-90ab-573ee7ddb5d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bf6b6c9-301d-4698-8527-10b253359a08', '45', false, 'dcf4d6d8-25ed-4b7e-90ab-573ee7ddb5d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fec98784-a10d-4f73-97d2-7e2d460ba94b', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'Which measure of central tendency is MOST suitable for a shopkeeper deciding which shoe size to stock in the largest quantity?', 'Mode reflects peak modal consumer demand for inventory stocking decisions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('906c1d78-9dde-41c4-830f-4f2af113923a', 'Mode (since it identifies the most popular, frequently purchased shoe size)', true, 'fec98784-a10d-4f73-97d2-7e2d460ba94b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82ae33fe-dcc2-4c47-b189-fecf75951a26', 'Mean', false, 'fec98784-a10d-4f73-97d2-7e2d460ba94b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc5ef961-2d8b-4410-b325-60283d155747', 'Median', false, 'fec98784-a10d-4f73-97d2-7e2d460ba94b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39e9a668-ba6f-496f-8e9d-b1ef63b41676', 'Range', false, 'fec98784-a10d-4f73-97d2-7e2d460ba94b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6cb724ac-6b63-4c7c-8645-062aec52df8a', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'Which measure of central tendency is preferred when a dataset contains extreme outlier values (e.g. salaries where one billionaire skews the average)?', 'Median is a non-parametric robust statistic unaffected by skewness or extreme outliers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('354835ac-ee55-46db-94af-440f175edbac', 'Median (because the median is resistant to extreme outliers)', true, '6cb724ac-6b63-4c7c-8645-062aec52df8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('204b07cd-543c-4876-9fac-233e9065e569', 'Mean (which gets heavily distorted by outliers)', false, '6cb724ac-6b63-4c7c-8645-062aec52df8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92ad964c-054e-4331-b29e-894b18ea2166', 'Range', false, '6cb724ac-6b63-4c7c-8645-062aec52df8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc12e155-e4cb-4bb9-9f0c-5107b79514ee', 'Total sum', false, '6cb724ac-6b63-4c7c-8645-062aec52df8a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0914ffde-f468-43bb-8a32-a177798597a8', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'On a bar graph, if a scale is chosen as 1 unit length = 10 students, what bar length in unit units represents 75 students?', 'Length = Value ÷ Scale factor = 75 ÷ 10 = 7.5 units.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6449db44-114f-484f-adcd-b13724d96bba', '7.5 units (75 / 10 = 7.5 units)', true, '0914ffde-f468-43bb-8a32-a177798597a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0e7c953-6532-4bef-a89e-2f9ffb9b88e2', '7 units', false, '0914ffde-f468-43bb-8a32-a177798597a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f204245f-e830-4017-9503-4bfbf268c2bd', '8 units', false, '0914ffde-f468-43bb-8a32-a177798597a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f0d45e9-1894-4c82-a807-099e68faa5fb', '75 units', false, '0914ffde-f468-43bb-8a32-a177798597a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b7dcdce-2233-440f-add9-2a196e419224', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Medium', 'What is the Median of the EVEN number of observations: 12, 14, 16, 18, 20, 22?', 'For n = 6 (even), Median is the mean of 3rd and 4th terms: (16 + 18)/2 = 17.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7737d50c-3731-4103-b28f-bd6c82eed85a', '17 (Average of the two middle terms 16 and 18: (16 + 18) / 2 = 34 / 2 = 17)', true, '3b7dcdce-2233-440f-add9-2a196e419224');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc9558c9-6310-49a2-b733-384ff11c9dcb', '16', false, '3b7dcdce-2233-440f-add9-2a196e419224');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04800c46-72d8-4a8d-b331-d77731e29a0c', '18', false, '3b7dcdce-2233-440f-add9-2a196e419224');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('590564f0-7971-41a2-a1de-255d52a682ee', '16.5', false, '3b7dcdce-2233-440f-add9-2a196e419224');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ef275b7-b357-4c0a-a073-fdc489d3706b', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccc109fd-4899-47da-abe9-9bbcce4bb703', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '3ef275b7-b357-4c0a-a073-fdc489d3706b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d25f030a-e02c-4453-b008-21c93bd0dbb4', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '3ef275b7-b357-4c0a-a073-fdc489d3706b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93092eda-0fac-43d3-baa3-9a6333347ee4', '(A) is true, but (R) is false.', false, '3ef275b7-b357-4c0a-a073-fdc489d3706b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e8a8f8f-1c3c-46c6-9c0a-ca1326907698', '(A) is false, but (R) is true.', false, '3ef275b7-b357-4c0a-a073-fdc489d3706b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38ea342a-2b44-4677-ba5e-e7b637b16d1a', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'Spot the IMPOSTER among the following statements regarding Central Tendency:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c77a269-39af-493f-ba65-92d913407f44', 'Statement 1', false, '38ea342a-2b44-4677-ba5e-e7b637b16d1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a855f67-a818-4588-a96c-f8449a68bd07', 'Statement 2 (Mean is NOT necessarily one of the numbers in the data, e.g. Mean of 2 and 3 is 2.5)', true, '38ea342a-2b44-4677-ba5e-e7b637b16d1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('536cf20d-464a-42ba-9df4-aa7f91e0195a', 'Statement 3', false, '38ea342a-2b44-4677-ba5e-e7b637b16d1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5edc92fe-5ae8-497e-b00a-8c0ae7311c3a', 'Statement 4', false, '38ea342a-2b44-4677-ba5e-e7b637b16d1a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b565a1b1-e13a-4f61-a29e-640751bd505b', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'The mean weight of a group of 20 boys is 52 kg, and the mean weight of another group of 30 boys is 47 kg. Find the COMBINED mean weight of all 50 boys:', 'Weighted average = (20×52 + 30×47) / 50 = (1040 + 1410)/50 = 2450/50 = 49 kg.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f420fc0-f0c0-4721-8238-0a585fa5698a', '49 kg (Total weight = (20 × 52) + (30 × 47) = 1040 + 1410 = 2450 kg ; Combined mean = 2450 / 50 = 49 kg)', true, 'b565a1b1-e13a-4f61-a29e-640751bd505b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c170dd3-1192-408b-a8ef-d52f104e0c16', '49.5 kg', false, 'b565a1b1-e13a-4f61-a29e-640751bd505b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb2e792b-db73-4c98-b99c-5135c8f27e45', '48 kg', false, 'b565a1b1-e13a-4f61-a29e-640751bd505b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a8887cd-d47d-4b57-8a63-8a8052650dca', '50 kg', false, 'b565a1b1-e13a-4f61-a29e-640751bd505b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9a5a8b5-9553-4951-bdc4-535e48c03d0a', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'Match Column I (Statistical Concepts) with Column II (Properties & Formulas):
(a) Arithmetic Mean -> (i) Sum of observations / Number of observations
(b) Median          -> (ii) Middle value dividing ordered data into two halves
(c) Mode            -> (iii) Value with the maximum frequency
(d) Range           -> (iv) Spread of data (Maximum - Minimum)', 'Mean = sum/n; Median = middle; Mode = max frequency; Range = max - min.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('033edac6-f2b9-4d8a-bf1b-c2d878ad869b', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'f9a5a8b5-9553-4951-bdc4-535e48c03d0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33ebc340-e391-4c32-bd5f-5405731fe565', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'f9a5a8b5-9553-4951-bdc4-535e48c03d0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8af0386c-139d-4f30-b6b8-ee1c2ec978ec', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'f9a5a8b5-9553-4951-bdc4-535e48c03d0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e862b5f2-b1df-4bf0-a847-2994da5bfb02', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'f9a5a8b5-9553-4951-bdc4-535e48c03d0a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('194c4b5b-8035-45f4-9424-dc267539d2a3', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'Read the statements regarding Probability:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('601e47e0-108d-45d9-9cca-41215ab12d51', 'Statements 1 and 2 only', true, '194c4b5b-8035-45f4-9424-dc267539d2a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e8ff7dc-6502-4526-b3f7-6bf4deb43673', 'Statements 2 and 3 only', false, '194c4b5b-8035-45f4-9424-dc267539d2a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d573fbab-9b92-401e-9149-70dbd29d2c6b', 'Statements 1 and 3 only', false, '194c4b5b-8035-45f4-9424-dc267539d2a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('faf32ffc-0c56-4714-a5c1-81e9faf603e2', 'All Statements 1, 2, and 3', false, '194c4b5b-8035-45f4-9424-dc267539d2a3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('61170a54-e3e4-4920-9c7c-2dbc55a15599', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'The following observations are arranged in ascending order: 11, 14, 15, 17, x + 1, 2x - 1, 30, 32, 35, 41.
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce64c12c-5f18-4ca3-a0a2-435fd2ceeb73', 'x = 16 (Middle two terms are (x+1) and (2x-1) ; Median = [(x+1)+(2x-1)] / 2 = 3x/2 = 24 ⇒ 3x = 48 ⇒ x = 16)', true, '61170a54-e3e4-4920-9c7c-2dbc55a15599');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2aedddc-b9fb-4562-9f62-0deeee7d7e21', 'x = 14', false, '61170a54-e3e4-4920-9c7c-2dbc55a15599');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b718220-e16f-40fa-b1a9-69e2659cf05d', 'x = 18', false, '61170a54-e3e4-4920-9c7c-2dbc55a15599');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19d11700-7b84-4311-91a9-a6b6016911d7', 'x = 15', false, '61170a54-e3e4-4920-9c7c-2dbc55a15599');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1803c757-bd48-4b54-a888-5330d989f8fa', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'A spinning wheel has 8 equal sectors: 3 Green, 2 Blue, 2 Red, and 1 Yellow. What is the probability of the pointer landing on a sector that is NOT GREEN?', 'P(Not Green) = 1 - P(Green) = 1 - 3/8 = 5/8.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('481c8ab8-9ad8-4a32-9f60-bd2522dd1aa5', '5/8 (Non-green sectors = 2 Blue + 2 Red + 1 Yellow = 5 sectors ; P = 5/8)', true, '1803c757-bd48-4b54-a888-5330d989f8fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a02e71b4-b573-4e00-83f5-8ff416aec1b5', '3/8', false, '1803c757-bd48-4b54-a888-5330d989f8fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbdbea75-2a87-4b35-8c93-c016fb505328', '1/2', false, '1803c757-bd48-4b54-a888-5330d989f8fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a68e46ab-2357-46a0-a5c8-dd51e5b9b821', '7/8', false, '1803c757-bd48-4b54-a888-5330d989f8fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27f1a293-a1e4-4c84-881c-921467505271', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'If every observation in a dataset is MULTIPLIED by 3, what happens to the Mean and Range of the dataset?', 'Linear transformation scaling: multiplying every value x_i by scalar ''c'' scales both mean and range by factor ''c''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32418a84-f36c-40ac-8b39-78c297827a1a', 'Both the Mean and the Range become 3 times the original (New Mean = 3 × Old Mean ; New Range = 3 × Old Range)', true, '27f1a293-a1e4-4c84-881c-921467505271');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65506923-9f46-4457-87d9-295e0e553739', 'Mean triples but Range remains unchanged', false, '27f1a293-a1e4-4c84-881c-921467505271');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bda4249-599d-4a31-9d06-a6c8dc23090f', 'Range triples but Mean remains unchanged', false, '27f1a293-a1e4-4c84-881c-921467505271');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae2a7f09-b98c-45af-8501-f23ecc3f701a', 'Neither changes', false, '27f1a293-a1e4-4c84-881c-921467505271');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ae678be-9303-4322-ab68-c184ba555e26', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'If the constant 5 is ADDED to every observation in a dataset, what happens to the Mean and Range?', 'Location shift translation adds constant ''k'' to mean, but distance measure Range remains invariant.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a89bf70-944d-4aed-a3bf-4438de75b238', 'The Mean increases by 5, but the Range remains COMPLETELY UNCHANGED (since (Max + 5) - (Min + 5) = Max - Min)', true, '7ae678be-9303-4322-ab68-c184ba555e26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ab3c0a1-4bbc-4b24-a699-c6631bd5cf74', 'Both Mean and Range increase by 5', false, '7ae678be-9303-4322-ab68-c184ba555e26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35eb8081-b366-40a1-bdd6-a0e3a324fcc3', 'Mean remains unchanged, Range increases by 5', false, '7ae678be-9303-4322-ab68-c184ba555e26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bb51c19-e65f-474e-827b-891fae1d1d84', 'Neither changes', false, '7ae678be-9303-4322-ab68-c184ba555e26');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('147f5e39-f14e-416d-9692-f22a9057d2a0', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'Consider a dataset of 5 distinct positive integers whose Mean is 12 and Median is 14. What is the MAXIMUM possible value that the largest number can take?', 'To maximize x₅: choose minimum distinct integers x₁=1, x₂=2, x₃=14 (median), x₄=15. Sum = 32 + x₅ = 60 → x₅ = 28.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bba9519c-d4b3-48f0-a9ee-7de2ba635e02', '28 (To maximize 5th number, minimize 1st, 2nd, and 4th: values = 1, 2, 14, 15, x ; Sum = 5 × 12 = 60 ⇒ 1 + 2 + 14 + 15 + x = 60 ⇒ 32 + x = 60 ⇒ x = 28)', true, '147f5e39-f14e-416d-9692-f22a9057d2a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3e9ab93-0b85-4a15-9182-3505f74a033e', '30', false, '147f5e39-f14e-416d-9692-f22a9057d2a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62d5b2b6-5246-4f47-ba9b-0ccd6c37c9ed', '26', false, '147f5e39-f14e-416d-9692-f22a9057d2a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f2285a1-777f-4548-ba8d-fde1db09ac5f', '32', false, '147f5e39-f14e-416d-9692-f22a9057d2a0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('825546ec-717d-4270-bed4-a32008e4d86d', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'A bag contains 5 red balls, 8 white balls, 4 green balls, and 7 black balls. One ball is drawn at random. What is the probability that the drawn ball is NEITHER white NOR black?', 'Total balls = 5+8+4+7 = 24. Neither white nor black = Red (5) + Green (4) = 9. P = 9/24 = 3/8.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04467942-222c-4d5e-81f0-4dda038ea264', '9/24 = 3/8 (Total balls = 24 ; Favourable = Red + Green = 5 + 4 = 9 balls ; P = 9/24 = 3/8)', true, '825546ec-717d-4270-bed4-a32008e4d86d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6b65a1a-a6c3-4bbc-bc4c-8137602f770b', '15/24', false, '825546ec-717d-4270-bed4-a32008e4d86d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10835aeb-bde6-443d-8af5-1644c52dbfdf', '5/24', false, '825546ec-717d-4270-bed4-a32008e4d86d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35bcc637-8b7f-4fba-b1c7-c5c0fe8b5bb1', '1/3', false, '825546ec-717d-4270-bed4-a32008e4d86d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff611100-1428-480f-a1c9-b9191322e7b7', 'Class 7', 'Mathematics', 'Chapter 3: Data Handling', 'Hard', 'Why is Data Handling and Statistical Analysis considered the foundation of modern data science, machine learning, economic planning, and scientific decision-making?', 'Descriptive and inferential statistics provide the foundational mathematical framework for data science, modeling uncertainty, and decision analytics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2253f285-2d00-4777-ad38-e2d3df99da6e', 'It transforms raw unorganized measurements into meaningful summaries, measures variability, identifies patterns, and models empirical probability for evidence-based predictions', true, 'ff611100-1428-480f-a1c9-b9191322e7b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('100b9834-d295-407d-b0a4-23add784bbc4', 'Because statistics eliminates the need for data collection', false, 'ff611100-1428-480f-a1c9-b9191322e7b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('375ac88a-6be0-4d19-8d99-bf8f91a19bfd', 'Because averages are the only numbers used in computers', false, 'ff611100-1428-480f-a1c9-b9191322e7b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('893b5457-45c0-4f3b-b6a3-90c56a43cfd7', 'Because probability guarantees 100% certainty in all future events', false, 'ff611100-1428-480f-a1c9-b9191322e7b7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e17b4cff-b327-46de-a672-0df7ba793ff9', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'In the comic story ''Gopal and the Hilsa-fish'', what seasonal topic was EVERYONE in the kingdom—from fishermen to courtiers and the King—obsessively talking about?', 'It was the season for Hilsa-fish, and people could talk of nothing else.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7739f502-60ea-4aff-b14d-0bdbacd53883', 'Hilsa-fish', true, 'e17b4cff-b327-46de-a672-0df7ba793ff9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f80d9fb-2b15-4006-96ac-964d60aa9aab', 'A cricket tournament', false, 'e17b4cff-b327-46de-a672-0df7ba793ff9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73cd3184-b8ec-41f8-8ae1-9726fcc579a4', 'A royal wedding', false, 'e17b4cff-b327-46de-a672-0df7ba793ff9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1d97f6e-9af1-470a-b8be-2e7fd1b9bf97', 'A foreign war', false, 'e17b4cff-b327-46de-a672-0df7ba793ff9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9310388e-0570-4e21-8128-031908433b19', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'What challenge did the King throw to his witty, clever courtier Gopal?', 'The King challenged Gopal to bring a giant Hilsa to the palace without anyone mentioning the fish.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0d89413-e6ea-40ce-937b-5de4c5b9054f', 'To buy a huge Hilsa-fish and bring it all the way to the royal palace without a single person asking him even ONE question about the fish on the way', true, '9310388e-0570-4e21-8128-031908433b19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d36e466a-64ae-4bbe-bbbe-6935f6df761c', 'To catch 1,000 fish in one hour', false, '9310388e-0570-4e21-8128-031908433b19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41fabb18-2be8-45ad-b9d9-d8cae49a43d1', 'To cook the most delicious fish curry', false, '9310388e-0570-4e21-8128-031908433b19');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8da399da-aa90-4646-9ac9-ecd67915c889', 'To swim across the ocean', false, '9310388e-0570-4e21-8128-031908433b19');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67c95128-66ca-45b4-ba10-9f850a90bbef', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'How did Gopal bizarrely disguise himself before going to the marketplace to buy the Hilsa-fish?', 'Gopal half-shaved, smeared ash over his face, and donned tattered rags to look like a madman.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76f9ef7a-c399-4a39-b6db-c46b4d5c26d2', 'He half-shaved his face, smeared dark ash all over his body, and wore filthy, torn rags', true, '67c95128-66ca-45b4-ba10-9f850a90bbef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4fe9ce6-60c3-4e0e-b2b1-8a04b30fbf32', 'He dressed up as a wealthy foreign prince', false, '67c95128-66ca-45b4-ba10-9f850a90bbef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38d83227-91ca-442d-95db-03a57f090c38', 'He wore golden royal armor', false, '67c95128-66ca-45b4-ba10-9f850a90bbef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c97542e1-6456-41fe-b0bb-dc07ae0a5aa0', 'He disguised himself as an old woman', false, '67c95128-66ca-45b4-ba10-9f850a90bbef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ddeefee-0214-4495-beb5-08ff4faa8ca3', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'What did Gopal''s wife think when she saw him half-shaven and smearing ash on himself?', 'Gopal''s wife was bewildered and exclaimed that he had lost his sanity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73f843d8-f740-4ba1-b5d8-767b83ad4864', 'She was shocked and thought he had gone completely MAD', true, '6ddeefee-0214-4495-beb5-08ff4faa8ca3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c958037f-029f-489d-b589-000946a897f2', 'She thought he was going to a wedding', false, '6ddeefee-0214-4495-beb5-08ff4faa8ca3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('839c72b8-be90-4b7c-b917-01f74d438fb2', 'She asked him for money', false, '6ddeefee-0214-4495-beb5-08ff4faa8ca3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('657627c3-0130-4295-ad26-7a2f4037325c', 'She did not notice anything', false, '6ddeefee-0214-4495-beb5-08ff4faa8ca3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4fadd75c-ea50-4f42-a3df-390a7544009f', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'What did people on the streets and in the market say when Gopal walked past holding the giant Hilsa-fish?', 'People were so transfixed by Gopal''s bizarre comical appearance that no one paid attention to the fish.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46773b99-c9ce-4e28-9298-2f76705293f9', '"Look at that man! Isn''t he comical? He must be a madman or a mystic!" (No one noticed the fish at all!)', true, '4fadd75c-ea50-4f42-a3df-390a7544009f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49da4b95-b4b3-42fa-b7f4-89131cfc4cc2', '"Look at that huge Hilsa-fish!"', false, '4fadd75c-ea50-4f42-a3df-390a7544009f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb1b476c-47fb-497a-a566-93b3913d0129', '"How much did the fish cost?"', false, '4fadd75c-ea50-4f42-a3df-390a7544009f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cd8fc86-37d9-4b63-90ba-2dfeca128e6f', '"Where did you catch that fish?"', false, '4fadd75c-ea50-4f42-a3df-390a7544009f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('390ec4fc-b965-4c81-b7bf-8b94bbcf90a7', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'What happened when Gopal reached the palace gates?', 'Barred by guards, Gopal sang and danced wildly until the curious King ordered him inside.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31c642cb-31c9-4117-8b82-ecc6e5b26af3', 'The guards stopped him from entering; Gopal began to dance and sing loudly until the King ordered the noisy madman brought before him', true, '390ec4fc-b965-4c81-b7bf-8b94bbcf90a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf061f96-6c38-4fa3-a0b2-995e09258991', 'The guards welcomed him with flowers', false, '390ec4fc-b965-4c81-b7bf-8b94bbcf90a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4e150b7-0034-4a93-ac7f-4b41d0f24751', 'The guards stole his fish', false, '390ec4fc-b965-4c81-b7bf-8b94bbcf90a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14e0e8be-4194-4bcf-b7d0-5616997afe54', 'Gopal climbed over the palace wall', false, '390ec4fc-b965-4c81-b7bf-8b94bbcf90a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4bb50d47-ca5f-4d23-a931-c9709e184301', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'How did the King react when he realized Gopal had successfully accomplished the impossible challenge?', 'The King laughed heartily and lauded Gopal''s extraordinary wit in fulfilling the challenge.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6697cef-de52-43a8-a506-5d23a235211c', 'He burst into hearty laughter and congratulated Gopal for achieving the impossible once again', true, '4bb50d47-ca5f-4d23-a931-c9709e184301');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c0823d7-cace-43b5-af2c-71aa4aece803', 'He was very angry and sent Gopal to prison', false, '4bb50d47-ca5f-4d23-a931-c9709e184301');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58db6709-67cf-4b80-a0e4-5c8d85b4d6ea', 'He refused to give Gopal any reward', false, '4bb50d47-ca5f-4d23-a931-c9709e184301');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83a4b86d-5a2d-4021-be76-f8651571a21d', 'He ordered the fish thrown away', false, '4bb50d47-ca5f-4d23-a931-c9709e184301');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('485c7cd1-ffc1-43bf-bdd2-0ddb47489089', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'In Frank Flynn''s evocative poem ''The Shed'', where is the mysterious old shed located?', 'The poem begins: ''There''s a shed at the bottom of our garden...''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7140f7f-b216-4ff9-bf66-4332a90d9151', 'At the bottom of the garden', true, '485c7cd1-ffc1-43bf-bdd2-0ddb47489089');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a70395fb-011c-4ccd-95d8-a6ba8d3d44c5', 'On top of a hill', false, '485c7cd1-ffc1-43bf-bdd2-0ddb47489089');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4555cf94-a8cd-4a81-8bec-bb9f3f8d44bd', 'Inside the forest', false, '485c7cd1-ffc1-43bf-bdd2-0ddb47489089');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de53288b-01b7-4a42-a3c3-e633f3670a67', 'Behind the school', false, '485c7cd1-ffc1-43bf-bdd2-0ddb47489089');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ce52bd24-0019-4a42-8424-771ee9281f66', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'In ''The Shed'', what is hanging across the shed door, and what sound do the rusty hinges make in the wind?', 'Flynn describes the spider''s web across the door and the creaking of rusty hinges when the poet lies in bed.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('761b4dce-e4c2-4cb7-b837-e3c5e6f3dc43', 'A Spider''s web hangs across the door ; the rusty hinges Creak in the wind', true, 'ce52bd24-0019-4a42-8424-771ee9281f66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4d1727f-8e23-4b11-aef3-de0d95fd24e3', 'A golden lock ; they ring like bells', false, 'ce52bd24-0019-4a42-8424-771ee9281f66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05b3d18b-ac43-41b0-86c0-d7af689d40c1', 'A green curtain ; they make no sound', false, 'ce52bd24-0019-4a42-8424-771ee9281f66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e57f938-0eda-48a7-a1e1-40a7877f67ef', 'A heavy iron chain ; they whistle', false, 'ce52bd24-0019-4a42-8424-771ee9281f66');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cda4de74-4917-4fec-bfc9-1c20e00f04b0', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'What scary warning does the speaker''s brother give him about the old shed?', 'The brother frightens him with tales of a head-chopping ghost hiding beneath rotten floorboards.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('428b3b52-2b90-4b41-922d-e0266f4aaa9e', 'There is a Ghost hiding under the rotten floorboards who will jump out and chop off his head if he dares to step inside', true, 'cda4de74-4917-4fec-bfc9-1c20e00f04b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('265ef100-e6d5-4b57-89c0-15a86b81daf5', 'There are poisonous snakes inside', false, 'cda4de74-4917-4fec-bfc9-1c20e00f04b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5460eb11-0fab-4f01-b6cb-b03e49b89434', 'There is a wild bear inside', false, 'cda4de74-4917-4fec-bfc9-1c20e00f04b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('869839b7-4872-45c7-9faa-1d9b8ebd2d13', 'The roof will fall on him', false, 'cda4de74-4917-4fec-bfc9-1c20e00f04b0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd8120e5-fa2b-43c7-b939-f4adb383d926', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'What is a ''Reported Question'' in English grammar?', 'Reported questions transform direct inquiries into indirect assertive clauses without inversion or question marks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a905c941-45a4-4f38-8310-a830b1b3ff75', 'Converting a direct interrogative question into an indirect declarative reported statement using ''if/whether'' or ''Wh-'' words without question marks', true, 'fd8120e5-fa2b-43c7-b939-f4adb383d926');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a3c736c-7bce-471b-aef2-2fec194d8dcf', 'Shouting a question loudly', false, 'fd8120e5-fa2b-43c7-b939-f4adb383d926');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8551cdec-251b-4e80-8e27-b65a0e69b55d', 'Writing a question in bold', false, 'fd8120e5-fa2b-43c7-b939-f4adb383d926');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93f20856-b411-4adb-9525-28c3a0582c02', 'Asking a question on television', false, 'fd8120e5-fa2b-43c7-b939-f4adb383d926');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68360b9e-641d-4f52-9ea3-25c579076c12', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Easy', 'What is the past tense of the irregular verb ''Smear'' as used in ''Gopal smeared ash on himself''?', 'The past tense of the regular verb ''smear'' is ''smeared''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21544e54-4a73-486a-89d5-616e18d99556', 'Smeared', true, '68360b9e-641d-4f52-9ea3-25c579076c12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8523aa85-4400-4065-aa21-2993131813df', 'Smearing', false, '68360b9e-641d-4f52-9ea3-25c579076c12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf49dbff-82a8-4e9f-beaf-4a43e1a8cc3f', 'Smear', false, '68360b9e-641d-4f52-9ea3-25c579076c12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ede706f-5a13-44e3-94c7-b054b0e0653c', 'Smearned', false, '68360b9e-641d-4f52-9ea3-25c579076c12');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('812c5463-a2ae-420b-8ec4-49eeeb3e6290', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Medium', 'What clever psychological principle did Gopal exploit to win the King''s challenge?', 'Gopal manipulated human cognitive salience: overpowering the seasonal obsession with a dramatic personal spectacle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c53ddf58-4e4d-41d4-9932-eee1b7d83c33', 'The power of visual distraction: by creating an outrageous, shocking visual spectacle of himself, he diverted human curiosity completely away from the fish', true, '812c5463-a2ae-420b-8ec4-49eeeb3e6290');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29ed184f-d08f-4460-a692-d88c8699ba5a', 'He hid the fish inside a wooden box', false, '812c5463-a2ae-420b-8ec4-49eeeb3e6290');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b4d95d5-7a35-46d8-8506-ed449af7ad4f', 'He cast a sleeping spell on everyone', false, '812c5463-a2ae-420b-8ec4-49eeeb3e6290');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dac5def9-0b31-4c64-b7fa-6a575f8b0d5c', 'He walked through secret underground tunnels', false, '812c5463-a2ae-420b-8ec4-49eeeb3e6290');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d0aa07f-481c-432c-9fd2-acb2e91d65e6', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Medium', 'In ''The Shed'', why does the speaker realize that his brother is lying about the ghost?', 'The speaker rationally deduces his brother''s territorial motive: inventing ghost tales to monopolize the shed.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00d5fe2d-c901-40ec-a5ad-1f2d99587c6b', 'His brother tells lies to keep the shed as his own private secret den, and the speaker sees no real ghost or spider webs anymore', true, '1d0aa07f-481c-432c-9fd2-acb2e91d65e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('700d27cf-c95b-43b9-bfc8-f7b172ea3b86', 'Because ghosts only live in castles', false, '1d0aa07f-481c-432c-9fd2-acb2e91d65e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13d31cdc-29c2-431e-9292-9a7bd33fb61c', 'Because the shed was built yesterday', false, '1d0aa07f-481c-432c-9fd2-acb2e91d65e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7093ce06-2eb7-42e5-861b-43a3792e9915', 'Because his mother told him there are no ghosts', false, '1d0aa07f-481c-432c-9fd2-acb2e91d65e6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f8dfb4a-08e6-4aac-96ef-47c4c46ab574', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Medium', 'What is the subtle psychological nuance in the poet''s final declaration at the end of ''The Shed'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca504b3f-85ea-4d0a-99e3-4e219a298342', 'A realistic portrayal of growing childhood courage mixed with lingering, natural hesitation and caution before conquering the unknown', true, '8f8dfb4a-08e6-4aac-96ef-47c4c46ab574');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dceeaa2-5af9-4d73-9ee8-9a59374cec48', 'The poet decided never to enter the shed', false, '8f8dfb4a-08e6-4aac-96ef-47c4c46ab574');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7b6ec42-5433-41b0-97f7-8ab382ff7816', 'The poet was terrified and ran away forever', false, '8f8dfb4a-08e6-4aac-96ef-47c4c46ab574');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35ab6aac-bc0f-4dbe-9aaa-4ac9ec3ee49f', 'The poet lost the key to the shed', false, '8f8dfb4a-08e6-4aac-96ef-47c4c46ab574');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e720bc54-e228-4bc5-b19d-588b12fb49ad', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Medium', 'Convert the Direct Speech question into INDIRECT SPEECH:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d75005d6-25be-44a4-ae25-aadb379926ed', 'The King asked Gopal why he was dressed up in that ridiculous fashion.', true, 'e720bc54-e228-4bc5-b19d-588b12fb49ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19a3ab92-404b-43bb-90a7-c3a96e9d88a3', 'The King asked Gopal that why are you dressed up.', false, 'e720bc54-e228-4bc5-b19d-588b12fb49ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6134c84f-2b71-4df5-888c-a2ca2f4c2f50', 'The King asked Gopal why was he dressed up in this fashion.', false, 'e720bc54-e228-4bc5-b19d-588b12fb49ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bc3c93c-054e-4c27-ae99-042e6a44fcc8', 'The King ordered Gopal why he is dressing.', false, 'e720bc54-e228-4bc5-b19d-588b12fb49ad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('42c55dbc-b1ee-4a28-bdae-2e87ab82ae3a', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Medium', 'Convert the Direct Speech into INDIRECT SPEECH:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('080500aa-92d4-4fc2-ade3-3b693dc426ee', 'The woman asked her husband what the matter was with him.', true, '42c55dbc-b1ee-4a28-bdae-2e87ab82ae3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64714234-dc29-45a0-84b9-d41d92d27278', 'The woman asked her husband what was the matter with you.', false, '42c55dbc-b1ee-4a28-bdae-2e87ab82ae3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5e220bd-9c1a-4221-853a-989be3fadf81', 'The woman told her husband that what is the matter.', false, '42c55dbc-b1ee-4a28-bdae-2e87ab82ae3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1229bbe-ce1c-4a1c-975e-6c4a52f2dec7', 'The woman asked her husband if what was the matter.', false, '42c55dbc-b1ee-4a28-bdae-2e87ab82ae3a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ea404c5-83e8-4fd1-93c5-490293bb9255', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Medium', 'What is the meaning of the word ''Comical'' in: ''Look at that man! Isn''t he comical?''?', '''Comical'' denotes evoking laughter through absurd, eccentric, or amusing incongruity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e45a219-01b6-49fe-8ee0-6f637ad6a003', 'Funny, amusing, and causing laughter due to absurd appearance', true, '3ea404c5-83e8-4fd1-93c5-490293bb9255');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dfbc452-864e-411e-9966-4c5e025b9613', 'Very dangerous and angry', false, '3ea404c5-83e8-4fd1-93c5-490293bb9255');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7a2aeed-ae7b-41ff-820c-7b7d10b971f3', 'Extremely sad', false, '3ea404c5-83e8-4fd1-93c5-490293bb9255');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40bce298-913f-4ab3-aa63-bb18d18c2a39', 'Very handsome', false, '3ea404c5-83e8-4fd1-93c5-490293bb9255');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4423662-ccb6-43a7-9b28-84ffb2280c88', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Medium', 'What is the meaning of the word ''Mystic'' in: ''Hush, I think he is a mystic!''?', '''Mystic'' describes an ascetic seeker of spiritual mysteries whose eccentric exterior defies mundane social conventions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd91cb56-127f-49b0-af89-11567a75e93f', 'A spiritual person who seeks direct communion with divine/unseen truths, often behaving outside ordinary social norms', true, 'c4423662-ccb6-43a7-9b28-84ffb2280c88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6a4479c-efb8-4320-b461-a0b33ec5860f', 'A thief stealing fish', false, 'c4423662-ccb6-43a7-9b28-84ffb2280c88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dfa9391-c86d-4f2b-975f-6226aa092f5e', 'A doctor in the palace', false, 'c4423662-ccb6-43a7-9b28-84ffb2280c88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('156d66c5-9ee1-40bf-96c7-b454d8a4c129', 'A foreign merchant', false, 'c4423662-ccb6-43a7-9b28-84ffb2280c88');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7afde55-c185-4a8d-b442-7d8a12cdb659', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Medium', 'In ''The Shed'', how does the poet describe the dusty old window on the side?', 'Flynn describes the three cracked windowpanes evoking juvenile sensory apprehensions of watchful unseen presences.', NOW()) ON CONFLICT DO NOTHING;
