INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8820d429-7342-4aa7-acbe-8f093eabfebf', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Medium', 'Identify the figure of speech in: ''The rusty hinges of the old shed door groaned in the midnight wind.''', 'Personification endows the creaking mechanical hinges with the somatic human expression of groaning.', NOW()) ON CONFLICT DO NOTHING;
