INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('140d09bd-04b6-4e76-853d-009397403c8a', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Medium', 'Choose the sentence that correctly transforms: ''Bring the man to me at once!'' (Active Voice) into PASSIVE VOICE:', 'Imperative passive structure: ''Let + object + be + past participle'' → ''Let the man be brought to me at once!''.', NOW()) ON CONFLICT DO NOTHING;
