INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c090cd0d-ce01-4bae-9b11-3873bd2f2442', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Medium', 'What is the meaning of the phrasal verb ''To bring about'' in: ''Gopal brought about a complete change in the King''s mood.''?', '''To bring about'' means to cause or effectuate a transformation.', NOW()) ON CONFLICT DO NOTHING;
