INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4b67188-efd0-43f0-9a3d-a6582c56955a', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Medium', 'What is the tone of the poem ''The Shed''?', 'The poem establishes an eerie, gothic childhood atmosphere evolving toward rational resolution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f539c1dc-bab7-4867-891c-d8f58549278c', 'Mysterious, eerie, and atmospheric, transitioning into rational courage and reflective curiosity', true, 'e4b67188-efd0-43f0-9a3d-a6582c56955a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f24f72f0-c47a-4b06-bc77-c118ede7e2aa', 'Furious and violent', false, 'e4b67188-efd0-43f0-9a3d-a6582c56955a');
