INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8a6d355-b589-4621-a880-57bd34b3b397', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'ba4a4472-2b42-44b8-9042-b4bf1d2ffe2e');
