INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc99bd6b-feb4-4114-8d96-5fa63dafbbd9', 'Element 1', false, '85878e0b-9ce9-4c60-adfd-e91dab013eda');
