INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b9d00a87-66b8-48ae-a768-3ed4b5774c98', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'Analyze the structural contrast between Gopal''s external physical appearance and his internal intellect:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('147abb0d-8d80-4a2c-81cc-fc76d0990313', 'Outwardly he appeared as a deranged, half-shaven, ash-smeared madman in rags, but inwardly he was operating with supreme tactical intellect and calculated rationality', true, 'b9d00a87-66b8-48ae-a768-3ed4b5774c98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('216b449c-978b-4660-a020-be9ff0ace6c0', 'He was genuinely mad and forgot what he was doing', false, 'b9d00a87-66b8-48ae-a768-3ed4b5774c98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae598b6d-26ff-4f01-9197-f2b06acb6c14', 'He wanted to become a real beggar', false, 'b9d00a87-66b8-48ae-a768-3ed4b5774c98');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('124823e7-0932-4095-b538-03ad8184f711', 'He was trying to hide from the police', false, 'b9d00a87-66b8-48ae-a768-3ed4b5774c98');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b4aaeaa-4ca5-4a9a-9c66-2ecb082f6967', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'Match Column I (Characters / Poetic Imagery) with Column II (Symbolic Meanings):
(a) The Hilsa-fish       -> (i) The all-consuming, trivial seasonal obsession of society
(b) The Ash and Rags     -> (ii) Deliberate sensory distraction to bypass collective prejudice
(c) The Rotten Floorboard-> (iii) The dark, unseen realm of childhood fear and superstition
(d) ''Not just yet...''   -> (iv) The realistic boundary of growing courage before action', 'Hilsa = obsession; Ash/rags = calculated distraction; Floorboard = childhood fear; Not yet = threshold of maturity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b99e69fc-7756-46b1-bf12-ced1b0b6efd4', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '9b4aaeaa-4ca5-4a9a-9c66-2ecb082f6967');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca5d7be1-71e7-40dd-8767-d0514e6a0ffd', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '9b4aaeaa-4ca5-4a9a-9c66-2ecb082f6967');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c423383f-5a70-4366-b468-7a03731dbb2b', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '9b4aaeaa-4ca5-4a9a-9c66-2ecb082f6967');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d18b10d-ee10-46df-88c0-999c1c6139a9', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '9b4aaeaa-4ca5-4a9a-9c66-2ecb082f6967');
