INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73e5c33b-2446-4828-a69d-c36729ada756', 'Statements 1 and 2 only', true, '3fcfebf9-7392-4591-8870-5aeb2a12882e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54857b09-b054-457b-b661-b939ec89d6ab', 'Statements 2 and 3 only', false, '3fcfebf9-7392-4591-8870-5aeb2a12882e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4be1e3fe-c884-4d76-bc2e-bb6789ba7dc6', 'Statements 1 and 3 only', false, '3fcfebf9-7392-4591-8870-5aeb2a12882e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d255b121-426f-45c8-adda-822d5e388c5a', 'All Statements 1, 2, and 3', false, '3fcfebf9-7392-4591-8870-5aeb2a12882e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d4dbb84-3651-43a8-b8d3-f0b80da82f3d', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'Identify the grammatical role of the underlined clause in: ''I know **that there isn''t really a ghost**.''', '''That there isn''t really a ghost'' functions as a Noun Clause object answering ''what is known''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99a0bd36-99c0-414e-8a06-2e5de4df1f2f', 'Noun Clause acting as the direct object of the transitive verb ''know''', true, '6d4dbb84-3651-43a8-b8d3-f0b80da82f3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25fbc7ad-491f-4efd-8dd6-c9c2335bc9d8', 'Adverb Clause of Reason', false, '6d4dbb84-3651-43a8-b8d3-f0b80da82f3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5393fb8-a676-4e6e-ae4d-d5ee4632bba5', 'Adjective Clause qualifying ''I''', false, '6d4dbb84-3651-43a8-b8d3-f0b80da82f3d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2faab984-ee2e-4151-b3b3-4f39119ecae9', 'Prepositional Phrase', false, '6d4dbb84-3651-43a8-b8d3-f0b80da82f3d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2752c9e9-f1f5-49be-a7d6-5d90b2e91d23', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'Which of the following sentences exhibits correct SUBJUNCTIVE MOOD expressing an imaginary hypothetical situation?', 'Hypothetical conditional subjunctive: ''If I were to peer... I would find''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c42bf6fd-eb4d-4a5a-b342-980df0b430b7', '''If I were to peer through that window, I would find only dusty old cobwebs.''', true, '2752c9e9-f1f5-49be-a7d6-5d90b2e91d23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6c13060-8aed-4021-b0dc-7207e9f2779a', '''If I was to peer through that window, I will find.''', false, '2752c9e9-f1f5-49be-a7d6-5d90b2e91d23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6361d691-9279-4a31-ac44-5d6618df25ca', '''If I am peering through that window, I would found.''', false, '2752c9e9-f1f5-49be-a7d6-5d90b2e91d23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56e8d73f-0ae0-470e-9171-62d9391706a6', '''If I peer through that window, I had found.''', false, '2752c9e9-f1f5-49be-a7d6-5d90b2e91d23');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f19902b8-b9cb-45b2-a5f1-7a70e187d0bb', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'What is the psychological function of ''The Shed'' as an architectural motif in children''s literature?', 'The garden shed functions as a liminal psychological space where adolescent rationality conquers gothic fears.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2316a669-f42e-45d6-949a-be5205acada6', 'It serves as a liminal space representing the mysterious unknown, the repository of childhood superstitions, and the eventual triumph of empirical rationality over irrational fear', true, 'f19902b8-b9cb-45b2-a5f1-7a70e187d0bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c065844-3b21-4aab-9d3f-b1c39788b6ee', 'It represents a prison for bad students', false, 'f19902b8-b9cb-45b2-a5f1-7a70e187d0bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d836d24-7d38-473a-a1f3-8470e8126c2e', 'It shows the importance of building garden toolboxes', false, 'f19902b8-b9cb-45b2-a5f1-7a70e187d0bb');
