INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c1eb093-e618-4d70-818d-34682c0a0aa1', '''Not a word was mentioned about the Hilsa-fish by anyone.''', true, 'cc816370-2414-4598-b40c-c4045bd7a162');
