INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0cc25ac7-bf02-429b-8bc2-f133c8a429cd', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'In ''The Shed'', why does the speaker note that: ''The spider has been gone from his web since I don''t know when''?', 'Observing the absent spider provides empirical validation dispelling mythic ghostly terror.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b63120fc-3bae-461a-a6be-48c1eb95f5bf', 'It is the speaker''s empirical observation proving that the shed is abandoned and dormant, exposing his brother''s ghost tales as groundless fabrications', true, '0cc25ac7-bf02-429b-8bc2-f133c8a429cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5b98aab-8246-4baf-b527-d1920006eec0', 'Because the spider flew to another country', false, '0cc25ac7-bf02-429b-8bc2-f133c8a429cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('688eb51f-11d4-481e-963f-87b3a701fa36', 'Because the ghost ate the spider', false, '0cc25ac7-bf02-429b-8bc2-f133c8a429cd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24b067e7-88b2-4883-af29-d3c184cf5fa9', 'Because the speaker sprayed pesticide', false, '0cc25ac7-bf02-429b-8bc2-f133c8a429cd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb540cc2-4b1b-4dc1-bb83-55fd5ac9b3f8', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'What comedic technique is used when Gopal''s wife shouts from the door: ''Why are you smearing yourself with ash? What is the matter with you?'' while Gopal calmly repeats: ''I''m telling you, I''m dressing up to buy a Hilsa-fish!''?', 'Deadpan comic incongruity: pairing extreme physical absurdity with serene, literal mundane justification.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b59c56af-ad0f-4fa7-a084-a8d8ab9e8efe', 'Comic Incongruity and deadpan repetition (mismatch between bizarre visual madness and completely calm, matter-of-fact dialogue)', true, 'cb540cc2-4b1b-4dc1-bb83-55fd5ac9b3f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('482bbeb1-c732-4882-95c7-a2768a6aa5d5', 'Tragic sorrow', false, 'cb540cc2-4b1b-4dc1-bb83-55fd5ac9b3f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('640d48e0-6c46-4280-ac5b-03dc5815977d', 'Violent anger', false, 'cb540cc2-4b1b-4dc1-bb83-55fd5ac9b3f8');
