INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d447b29-c426-4d13-ad2d-1ab91bf2e63d', 'Class 7', 'English', 'Chapter 3: Gopal and the Hilsa-fish & The Shed', 'Hard', 'What master life philosophy links both the prose and poetic selections in Chapter 3 of NCERT Class 7 English?', 'Chapter 3 integrates intellectual ingenuity (Gopal) with psychological courage confronting the unknown (The Shed).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d13dbbe8-f47c-451d-b26b-6e2a93e3a097', 'True intellect and courage conquer all challenges—whether using sharp lateral wit to outmaneuver societal obsessions or applying rational courage to overcome fear of the dark and unknown', true, '3d447b29-c426-4d13-ad2d-1ab91bf2e63d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3ba20e3-5d70-482d-85af-e701591e0b31', 'That fish is the only food worth eating', false, '3d447b29-c426-4d13-ad2d-1ab91bf2e63d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48df6513-54a4-4015-9445-1e5c28848b5b', 'That garden sheds should always be locked', false, '3d447b29-c426-4d13-ad2d-1ab91bf2e63d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7e32db8-15a8-4ed9-898c-7252cd173282', 'That courtiers should never obey kings', false, '3d447b29-c426-4d13-ad2d-1ab91bf2e63d');
