INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fc769d8-adc6-4b0e-aaff-e8dea2e1f73d', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'db58e604-bdfd-4a69-aa9f-8f42b6ce1397');
