INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('836ee4ea-39f3-4c83-b705-dc431046de27', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'Spot the IMPOSTER in the following group of World Landforms matched with their Continents:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a62cb87b-24cb-4753-bc74-200e74f54b55', 'Match 1', false, '836ee4ea-39f3-4c83-b705-dc431046de27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fda5a7ad-54ad-4e8f-a3c8-c4b120299a3a', 'Match 2', false, '836ee4ea-39f3-4c83-b705-dc431046de27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2df7c74b-8ced-4310-b3cb-854c5bf44abe', 'Match 3', false, '836ee4ea-39f3-4c83-b705-dc431046de27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52a27eba-643a-4cf9-92d4-66ce8fa61a14', 'Match 4 (Mount Elbrus is in the Caucasus Mountains of EUROPE/Russia ; Mount Kosciuszko is in Australia)', true, '836ee4ea-39f3-4c83-b705-dc431046de27');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3aa7b148-cda4-45da-aac3-1cab9d8268e3', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'What is an ''Isthmus'' versus a ''Strait'' in physical geography?', 'Isthmus = terrestrial bridge between landmasses; Strait = navigable nautical channel between waterbodies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29ca4370-8864-4bab-b107-2e69caca7978', 'An Isthmus is a narrow strip of LAND connecting two larger landmasses (e.g. Isthmus of Panama) ; a Strait is a narrow body of WATER connecting two larger water bodies (e.g. Strait of Gibraltar)', true, '3aa7b148-cda4-45da-aac3-1cab9d8268e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90450825-ca34-48f5-a876-aea1a327327f', 'An isthmus is made of ice, a strait is made of rock', false, '3aa7b148-cda4-45da-aac3-1cab9d8268e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b27f77c-3e23-4ccb-80e5-eecf016a146d', 'A strait is a river in a desert', false, '3aa7b148-cda4-45da-aac3-1cab9d8268e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7797962-f643-4194-8577-f9537fb79aac', 'Both are identical terms for mountains', false, '3aa7b148-cda4-45da-aac3-1cab9d8268e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('460c8cd0-8591-4788-8240-a7331796c673', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'Match Column I (Famous Global Landmarks) with Column II (Country / Architectural Feature):
(a) Taj Mahal         -> (i) White marble mausoleum in Agra, India (Mughal architecture)
(b) Colosseum         -> (ii) Flavian amphitheatre in Rome, Italy (Roman architecture)
(c) Chichen Itza      -> (iii) El Castillo step pyramid in Yucatan, Mexico (Maya civilization)
(d) Christ the Redeemer-> (iv) Art Deco statue atop Corcovado mountain in Rio de Janeiro, Brazil', 'Taj Mahal = Mughal marble; Colosseum = Roman arena; Chichen Itza = Maya pyramid; Christ the Redeemer = Rio Art Deco.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05a46568-7383-44ec-b046-fb8e3a975384', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '460c8cd0-8591-4788-8240-a7331796c673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('214f748f-72a3-474d-9e8b-19e9bb5f8ee3', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '460c8cd0-8591-4788-8240-a7331796c673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('805ccef6-74f5-480c-b8b7-113870d08882', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '460c8cd0-8591-4788-8240-a7331796c673');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9362d813-dfd2-420c-827f-35c696735890', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '460c8cd0-8591-4788-8240-a7331796c673');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be502229-58d5-46ab-9de9-990ae9a29ecb', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'Read the statements regarding extreme global geography:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c76d7f9e-3ece-48a2-b477-aa649fcaa5a4', 'Statements 1 and 2 only', true, 'be502229-58d5-46ab-9de9-990ae9a29ecb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd305c7b-a7f1-44bf-abf6-ef201e25b6c3', 'Statements 2 and 3 only', false, 'be502229-58d5-46ab-9de9-990ae9a29ecb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc42ab8e-2f81-438c-b0f1-cb6152c29d85', 'Statements 1 and 3 only', false, 'be502229-58d5-46ab-9de9-990ae9a29ecb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07fa69da-e2d3-4e4c-81fd-a3f10dd850ff', 'All Statements 1, 2, and 3', false, 'be502229-58d5-46ab-9de9-990ae9a29ecb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e17f8d8-d5cd-4b1c-aeda-7c49bb300159', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'Why is the Mariana Trench so deep, and what geological process formed it?', 'Convergent tectonic plate subduction forces heavy oceanic crust into the upper asthenosphere, carving deep bathymetric trenches.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('128e7cf7-4c5b-49a9-b1f7-2c102248cd8f', 'Subduction: the older, denser Pacific tectonic plate is being forced beneath the smaller Mariana plate into the Earth''s mantle', true, '2e17f8d8-d5cd-4b1c-aeda-7c49bb300159');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4db9d46a-6ed2-49a7-9a9e-78ee0c8708e5', 'Two continents collided to form a mountain', false, '2e17f8d8-d5cd-4b1c-aeda-7c49bb300159');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b479d7a4-8ecd-41b5-8675-c8414cfc5899', 'A giant meteor impacted the Pacific Ocean', false, '2e17f8d8-d5cd-4b1c-aeda-7c49bb300159');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b230ce4-093d-4ae2-8426-0d07950fef55', 'An underground nuclear explosion', false, '2e17f8d8-d5cd-4b1c-aeda-7c49bb300159');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4fbb407-1402-4f8b-a1d7-efa0a985677b', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'What is the ''Great Rift Valley'' of East Africa stretching over 6,000 km from the Red Sea to Mozambique?', 'The East African Rift is an active intra-continental divergent plate boundary driving continental breakup.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa7aa950-c4bf-43eb-8b38-4f0c518bd986', 'A divergent geological rift system where the African tectonic plate is actively splitting into two new tectonic plates (Somali and Nubian plates)', true, 'd4fbb407-1402-4f8b-a1d7-efa0a985677b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3c9cf43-5ef4-4612-95fd-9890b1f13e74', 'A human-made canal for shipping', false, 'd4fbb407-1402-4f8b-a1d7-efa0a985677b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d668a9e-0a02-428f-9c62-120c1abe6c5b', 'A dried-up ancient riverbed', false, 'd4fbb407-1402-4f8b-a1d7-efa0a985677b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b33e5127-6287-4562-8710-6935faed1a57', 'A crater formed by a volcanic explosion', false, 'd4fbb407-1402-4f8b-a1d7-efa0a985677b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('909b7dd1-5613-4806-a1e3-2494da1cf209', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'Consider four capital cities located along famous global rivers:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca75c869-43eb-48a4-9eb1-1375aba47df5', 'Rivers provided perennial freshwater, fertile alluvial soil, critical inland navigation, and vital trade connectivity for ancient urban civilizations', true, '909b7dd1-5613-4806-a1e3-2494da1cf209');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d6b7016-a282-4cf9-9426-26b942463a8e', 'Because kings liked swimming competitions', false, '909b7dd1-5613-4806-a1e3-2494da1cf209');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bb80fbd-6189-472b-bfb3-23c7ad0dcc8f', 'Because bridges could only be built in cities', false, '909b7dd1-5613-4806-a1e3-2494da1cf209');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07fbc8af-b973-429e-91df-bb04a0871923', 'Because stone was only found underwater', false, '909b7dd1-5613-4806-a1e3-2494da1cf209');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8bcc9236-2312-409c-8ab9-6b6d73db2554', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'What is the scientific term for an archipelago of coral islands enclosing a central shallow seawater lagoon?', 'An atoll is a ring-shaped coral reef rim surrounding a lagoon, formed over subsiding volcanic islands (Darwin''s theory).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a0e3485-6020-4b4e-b445-cdfcc8dd6d8a', 'Atoll (e.g. Lakshadweep and Maldives)', true, '8bcc9236-2312-409c-8ab9-6b6d73db2554');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44db728e-861a-4060-ba6d-8ca3d8bcb623', 'Peninsula', false, '8bcc9236-2312-409c-8ab9-6b6d73db2554');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fa609fc-c853-4f40-a1f0-6a8e95883691', 'Fjord', false, '8bcc9236-2312-409c-8ab9-6b6d73db2554');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2857c578-02bf-4096-931b-4cd16e298ec7', 'Delta', false, '8bcc9236-2312-409c-8ab9-6b6d73db2554');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03970663-9e1a-4dc5-843a-db8cb2fb9acc', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'What is the unique geographical status of the city of ISTANBUL in Turkey?', 'Istanbul spans the Bosphorus Strait, straddling European Thrace and Asian Anatolia.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4937757e-0141-47fd-b26e-bd996a2c38c9', 'It is the ONLY transcontinental metropolis in the world located simultaneously on TWO continents (Europe and Asia), separated by the Bosphorus Strait', true, '03970663-9e1a-4dc5-843a-db8cb2fb9acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3412ea16-27e6-44da-adac-abcb52d7f566', 'It is located under the ocean', false, '03970663-9e1a-4dc5-843a-db8cb2fb9acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ab0f344-db0a-4869-b4be-54421f3800dd', 'It has no land roads', false, '03970663-9e1a-4dc5-843a-db8cb2fb9acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aed15ae9-603e-487c-a9bd-a8dfdc4253a2', 'It is governed by the United Nations directly', false, '03970663-9e1a-4dc5-843a-db8cb2fb9acc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b160714d-e79e-4720-9c2b-140dff7593dd', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'What is the ''Sargasso Sea'' in the North Atlantic Ocean?', 'The Sargasso Sea is defined exclusively by ocean current gyres (Gulf Stream, North Atlantic Current, Canary Current, North Equatorial Current).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65d2a66f-b9c1-4045-bcec-d72f6b226223', 'The ONLY sea in the world that has NO land boundaries/shores, bounded entirely by four ocean currents forming the North Atlantic Gyre', true, 'b160714d-e79e-4720-9c2b-140dff7593dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b43c5be-95fa-42bb-9b19-c6110151c6a0', 'A sea of fresh milk', false, 'b160714d-e79e-4720-9c2b-140dff7593dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b0fddf8-6190-4e21-a5be-99de527195d5', 'An underground sea inside a cavern', false, 'b160714d-e79e-4720-9c2b-140dff7593dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6a57a5c-5a53-418d-aa9b-d976888b78b2', 'A frozen sea in the Sahara Desert', false, 'b160714d-e79e-4720-9c2b-140dff7593dd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b4a945d7-51ca-449b-a5a9-260a9f7bfcd1', 'Class 7', 'GK', 'Chapter 3: World Geography, Continents, Oceans & Famous Global Landmarks', 'Hard', 'What profound planetary perspective is revealed through the comprehensive study of World Geography and Landmarks?', 'World Geography unifies geomorphic planetary dynamics with anthropogenic cultural adaptations across diverse biomes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5f2870b-fd97-41ca-ad0d-3f5a4721f36c', 'Earth is a dynamic, interconnected planetary biosphere where physical plate tectonics, atmospheric currents, oceanic gyres, and cultural human civilizations form an interdependent global tapestry', true, 'b4a945d7-51ca-449b-a5a9-260a9f7bfcd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b38e364c-5fc9-4215-8933-7697109af636', 'Continents are fixed and never change over billions of years', false, 'b4a945d7-51ca-449b-a5a9-260a9f7bfcd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23651a25-47e1-40b4-8685-1a5fa8ccd466', 'All countries have identical climates and landforms', false, 'b4a945d7-51ca-449b-a5a9-260a9f7bfcd1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b23d66f0-6d5e-4c98-9c94-924cd2ed1453', 'Human civilization developed independently of geographic rivers and resources', false, 'b4a945d7-51ca-449b-a5a9-260a9f7bfcd1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e09f201-2c69-453c-b25d-424643764027', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Easy', 'Under the rule of which Rajput dynasty did the city of Delhi first become the capital of a kingdom in the 12th century?', 'Delhi first became a capital under the Tomara Rajputs, who were subsequently defeated by the Chauhans of Ajmer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6354b770-35d6-4c42-8f07-7b7110e372cf', 'Tomara Rajputs (later defeated by Chauhans / Chahamanas of Ajmer)', true, '9e09f201-2c69-453c-b25d-424643764027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce3adfd8-83fa-450d-bf47-f622e7e8a694', 'Cholas', false, '9e09f201-2c69-453c-b25d-424643764027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d54d3480-8a62-43ad-b052-326871bd4cbd', 'Guptas', false, '9e09f201-2c69-453c-b25d-424643764027');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98b1db04-0b4a-41d5-8717-28cfa5445a1e', 'Mauryas', false, '9e09f201-2c69-453c-b25d-424643764027');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d8b6c8d-621c-4a3a-96df-58783871f65e', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Easy', 'What were the commercial coins minted in Delhi that had a wide circulation across medieval trade routes called?', 'Coins minted in medieval Delhi were widely recognized as ''Dehliwal''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8821ae9d-5598-4ff1-898a-de50e4395c13', 'Dehliwal', true, '8d8b6c8d-621c-4a3a-96df-58783871f65e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a0a4228-4f47-42c5-84d2-8a012bfdce48', 'Dinar', false, '8d8b6c8d-621c-4a3a-96df-58783871f65e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3be78895-a729-47e3-9ffd-aea65bd33960', 'Tanka', false, '8d8b6c8d-621c-4a3a-96df-58783871f65e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65966392-9b93-42a9-976a-c0a90dbf3e30', 'Rupee', false, '8d8b6c8d-621c-4a3a-96df-58783871f65e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5540c076-d75d-4bfa-ae06-d35c7b1f653d', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Easy', 'What is the historical term for Persian histories/chronicles written by literate secretaries, administrators, and poets in the Delhi Sultanate?', 'Tarikh/Tawarikh were court histories written in Persian, the official administrative language of the Delhi Sultanate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29275d95-726b-4317-b2e2-c7cd681dfd0a', 'Tarikh (singular) / Tawarikh (plural)', true, '5540c076-d75d-4bfa-ae06-d35c7b1f653d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6c2ba4b-e639-49f5-b165-5ca3c867eec5', 'Prashasti', false, '5540c076-d75d-4bfa-ae06-d35c7b1f653d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9e2c93d-8fca-48d8-b063-78fb974986c3', 'Vedas', false, '5540c076-d75d-4bfa-ae06-d35c7b1f653d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('857d5b2e-0150-4f6b-94e5-ed0f0289a234', 'Upanishad', false, '5540c076-d75d-4bfa-ae06-d35c7b1f653d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e1925fc-f3b2-4155-a5a3-bd7dc1f74793', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Easy', 'Who was the FIRST and ONLY female Muslim monarch to sit on the throne of the Delhi Sultanate (daughter of Sultan Iltutmish) in 1236 CE?', 'Raziyya Sultan ruled from 1236 to 1240 CE as recognized by chronicler Minhaj-i Siraj.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bf5e72d-4fdd-41b0-b22f-916fbf611232', 'Raziyya Sultan (Sultana Raziyya)', true, '7e1925fc-f3b2-4155-a5a3-bd7dc1f74793');
