INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27fe0e47-0a00-453b-b39c-b57019519525', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Easy', 'What was a fortified settlement with soldiers stationed permanently for military defense in the Delhi Sultanate called?', 'A garrison town was a heavily fortified urban military base garrisoned with soldiers.', NOW()) ON CONFLICT DO NOTHING;
