INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0e61a476-3482-465c-a92f-7dbec0b69afc', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Easy', 'What were the special military slaves purchased for military service and trained with great care by early Delhi Sultans (especially Iltutmish) called in Persian?', '''Bandagan'' (plural of banda) were elite military slaves trusted by Sultans over hereditary aristocrats.', NOW()) ON CONFLICT DO NOTHING;
