INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('83fdc328-19d9-4f36-9007-fb5ad69c388b', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Easy', 'What was a territorial revenue assignment (land territory) granted to military commanders by the Sultans called?', 'An ''Iqta'' was a provincial revenue tract assigned to commanders (Iqtadars/Muqtis).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40f90f32-4236-4735-ad83-181747563d78', 'Iqta', true, '83fdc328-19d9-4f36-9007-fb5ad69c388b');
