INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c33e7ab6-f748-47bc-aeef-87fefecbf44e', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Easy', 'What were the military governors or holders of an Iqta land assignment called?', 'Iqtadars (or Muqtis) governed Iqtas, maintaining soldiers and collecting territorial revenues.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbf118ca-c7c7-427d-a1e0-b2d23501c7f4', 'Iqtadar or Muqti', true, 'c33e7ab6-f748-47bc-aeef-87fefecbf44e');
