INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11c14158-e2fd-4e06-ae96-3fde91105306', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Easy', 'What was the agricultural land tax levied on peasant produce, accounting for about 50% of the peasant''s crop yield under Alauddin Khalji?', 'Kharaj was the standard 50% agricultural crop tax levied directly on cultivators.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5a1008b-56c6-4ae2-a069-70db2002dbcc', 'Kharaj', true, '11c14158-e2fd-4e06-ae96-3fde91105306');
