INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c45cd61-f746-444b-95aa-bec1a3e11cac', 'Chauth', false, '11c14158-e2fd-4e06-ae96-3fde91105306');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('caf5af38-b395-4593-875f-44eba2672bf9', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Easy', 'Who was the notorious Central Asian Mongol conqueror whose forces invaded Transoxiana in 1219 and repeatedly attacked the Delhi Sultanate?', 'Genghis Khan unified the Mongols, invading Khwarizm and pressing against the northwest frontiers of India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a72c6b68-b60c-4af8-8f1e-a57d78e33acb', 'Genghis Khan (Chingiz Khan)', true, 'caf5af38-b395-4593-875f-44eba2672bf9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b690365e-8983-4c72-a3e0-e730bccad1b9', 'Timur', false, 'caf5af38-b395-4593-875f-44eba2672bf9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('320b0081-90e6-4ec7-afd9-97afcdb64822', 'Babur', false, 'caf5af38-b395-4593-875f-44eba2672bf9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c728077-f389-49d5-88d7-2da699a46c9d', 'Hulagu Khan', false, 'caf5af38-b395-4593-875f-44eba2672bf9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9103eb39-9628-4462-bf86-2c538550498a', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Easy', 'Which Moroccan traveler arrived in India during the 14th-century reign of Sultan Muhammad Tughluq and left an invaluable travelogue (Rihla)?', 'Ibn Battuta from Tangier, Morocco, served as Qazi of Delhi under Muhammad Tughluq and documented Sultanate governance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3dcca68-e98f-4e6f-a406-dc7294410960', 'Ibn Battuta', true, '9103eb39-9628-4462-bf86-2c538550498a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6770f5cd-0d08-45c7-824e-ee54ea3f1ad4', 'Marco Polo', false, '9103eb39-9628-4462-bf86-2c538550498a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1aebf6ae-6f11-4a17-a372-312307cc6093', 'Al-Biruni', false, '9103eb39-9628-4462-bf86-2c538550498a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fd94651-a537-4d3f-9478-c89a40ae30e0', 'Duarte Barbosa', false, '9103eb39-9628-4462-bf86-2c538550498a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0316ba17-f9f2-458b-8cdf-b9ff2f481a2b', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'What was the ''Circle of Justice'' (Fakhr-i Mudabbir, 13th century) that explained the interdependent relationship between the King, soldiers, peasants, and state revenue?', 'The Circle of Justice (Daira-i Adalat) linked monarchical survival directly to peasant prosperity and judicial equity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc84238d-8d46-44b6-81ae-3f08e99a1be1', 'A king cannot survive without soldiers -> Soldiers cannot live without salaries -> Salaries come from revenue collected from peasants -> Peasants can pay revenue only when they are prosperous and happy -> This happens when the king promotes justice and honest governance', true, '0316ba17-f9f2-458b-8cdf-b9ff2f481a2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcf39477-8fc6-4381-bd2f-0565813d6d22', 'A circle drawn on the ground for duels', false, '0316ba17-f9f2-458b-8cdf-b9ff2f481a2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('416ed7e3-a688-4878-b93e-652055a84ffe', 'A round table where judges sit', false, '0316ba17-f9f2-458b-8cdf-b9ff2f481a2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c25d1efe-591d-4c5f-b2d9-fc63d3a5d11b', 'A magic circle protecting Delhi forts', false, '0316ba17-f9f2-458b-8cdf-b9ff2f481a2b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('920cb64f-52c2-4b6a-89c6-8976920c01ca', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'Why did the 13th-century chronicler Minhaj-i Siraj acknowledge that Raziyya was more able and qualified than all her brothers, yet felt uncomfortable with her rule?', 'Minhaj articulated medieval patriarchal ideology: viewing female monarchs as disrupting divine gender hierarchies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7e3c34f-03cc-45d5-a778-91f9b8192e53', 'He believed that female sovereignty violated the patriarchal ideal social order ordained by God, where women were supposed to be subordinate to men', true, '920cb64f-52c2-4b6a-89c6-8976920c01ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c5e98de-87f2-48ce-b097-d91fc8b89e0b', 'Because Raziyya lost all wars', false, '920cb64f-52c2-4b6a-89c6-8976920c01ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('413d9067-c619-4453-9c4a-68be50475db9', 'Because Raziyya could not read Persian', false, '920cb64f-52c2-4b6a-89c6-8976920c01ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e361146f-4cc8-4903-883d-ad768e50fe3d', 'Because Raziyya gave all kingdom wealth to foreign traders', false, '920cb64f-52c2-4b6a-89c6-8976920c01ca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7283283c-22aa-4475-a904-ec1b63a267e7', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'Why did early Delhi Sultans (like Iltutmish) prefer to appoint their purchased military slaves (Bandagan) to high governorships rather than traditional noble aristocrats?', 'Royal patronage of Bandagan secured a dedicated praetorian corps personally beholden to the Sultan alone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b458f964-8291-4b5a-aa76-30459883190a', 'Slaves had no family lineage or hereditary local loyalties; they were entirely dependent on the Sultan for their livelihood and were exceptionally loyal and obedient', true, '7283283c-22aa-4475-a904-ec1b63a267e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1db869d6-50ae-4d79-9d4d-903f6f635df2', 'Because slaves cost no money', false, '7283283c-22aa-4475-a904-ec1b63a267e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2ee4799-5852-43f5-865d-4f1c00587fa4', 'Because noble aristocrats could not fight wars', false, '7283283c-22aa-4475-a904-ec1b63a267e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f6f7522-1a3c-495b-8c20-2b63092fd09c', 'Because slaves knew magic', false, '7283283c-22aa-4475-a904-ec1b63a267e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b45f514f-2c7a-4e29-8fe3-f819e1b8cb5c', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'How did Alauddin Khalji maintain strict control over his Muqtis (Iqtadars) to prevent corruption and rebellion?', 'Alauddin enforced non-hereditary tenure, frequent transfers, and rigorous auditing of Muqti revenue and troop contingents.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91b064d6-009e-42a3-9c30-5c31dea35a5f', 'Their offices were made non-hereditary, Iqtas were assigned for short periods before frequent transfers, and state accountants were appointed to audit revenues and verify troop numbers', true, 'b45f514f-2c7a-4e29-8fe3-f819e1b8cb5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cee9e8f-322c-4368-b102-9cd66f2aa732', 'He let Muqtis keep all taxes without auditing', false, 'b45f514f-2c7a-4e29-8fe3-f819e1b8cb5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cfb8fa4-2d7a-4a72-b839-861972960bc9', 'He abolished all soldiers', false, 'b45f514f-2c7a-4e29-8fe3-f819e1b8cb5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cf1f715-3cd4-4a9f-8b01-c19afe39380e', 'He gave Muqtis absolute permanent ownership of lands', false, 'b45f514f-2c7a-4e29-8fe3-f819e1b8cb5c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('103b4695-89bd-4146-a275-96235b53489c', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'What market and price control measures did Alauddin Khalji implement in Delhi to maintain a large standing army at sustainable costs against Mongol invasions?', 'Alauddin''s economic reforms: price caps, state grain silos, and market superintendents (Shahna-i Mandi) to sustain military mobilization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5bb1ce1-25b4-4693-9af4-0e172be60066', 'He strictly fixed the maximum selling prices of all commodities (grains, cloth, sugar, horses), appointed market inspectors (Shahna-i Mandi), and harshly punished any merchant who cheated or overcharged', true, '103b4695-89bd-4146-a275-96235b53489c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ef82216-5c9e-4516-bd99-12c963126372', 'He doubled the price of all foods', false, '103b4695-89bd-4146-a275-96235b53489c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b6c012c-8e00-4182-b489-9142ac43be95', 'He banned all private markets completely', false, '103b4695-89bd-4146-a275-96235b53489c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d796777d-ee85-44c3-be85-974eea1093ef', 'He printed unlimited paper money', false, '103b4695-89bd-4146-a275-96235b53489c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6bd0071d-abf0-40c1-b573-4f5b53133906', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'What was Sultan Muhammad bin Tughluq''s infamous ''Token Currency'' experiment and why did it fail disastrously?', 'Unminted token brass/copper tokens were easily counterfeited by artisans, bankrupting the imperial exchequer (Gresham''s Law).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d985f5b3-e8c6-4c86-99a9-8cdc2fa42a9a', 'He issued cheap copper and brass coins having the same face value as silver Tankas; people easily forged the simple copper coins at home, paid taxes in fake tokens, and hoarded genuine gold and silver coins', true, '6bd0071d-abf0-40c1-b573-4f5b53133906');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2a94e6d-4384-46c5-9b1e-dfe69e2d51c1', 'Because copper turned into water', false, '6bd0071d-abf0-40c1-b573-4f5b53133906');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('097e272f-cf75-4096-836d-7b64d20bae2f', 'Because people threw coins into the river', false, '6bd0071d-abf0-40c1-b573-4f5b53133906');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2d360dd-0a33-4bf3-8841-0f83356b89d5', 'Because the coins had no numbers written on them', false, '6bd0071d-abf0-40c1-b573-4f5b53133906');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1215b7e6-65d6-4a91-9fa8-639a6df9b5d8', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'What was Muhammad bin Tughluq''s controversial decision to shift the imperial capital from Delhi to DAULATABAD (Devagiri in Deccan)?', 'The forced relocation to Daulatabad (1327 CE) caused widespread fatalities during the transit and was subsequently abandoned.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('063e9165-2be5-45d2-b0f2-533708cca4c0', 'He wanted to govern southern peninsular India and defend against northern Mongol attacks more effectively, but forced the entire population of Delhi to march 1,500 km south, causing immense suffering', true, '1215b7e6-65d6-4a91-9fa8-639a6df9b5d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41252ee3-6479-4d32-b156-54d11e19e2f7', 'Because Delhi ran out of drinking water', false, '1215b7e6-65d6-4a91-9fa8-639a6df9b5d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55db504e-e2e9-4fdf-a896-f3700d20175b', 'Because Daulatabad had gold houses', false, '1215b7e6-65d6-4a91-9fa8-639a6df9b5d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('764a06ae-9c82-4266-acdc-3edd0661bc56', 'Because he wanted to move to Europe', false, '1215b7e6-65d6-4a91-9fa8-639a6df9b5d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11ff0b7e-f3b2-4a03-ba7c-d82791fcb4ba', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'In mosque architecture, what is the orientation towards Mecca that Indian Muslims face during prayer (towards the West) called?', 'Qibla is the sacred directional orientation toward the Kaaba in Mecca (due West from the Indian subcontinent).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('233308c6-b25c-4a08-91aa-e2f4100bbbc0', 'Qibla', true, '11ff0b7e-f3b2-4a03-ba7c-d82791fcb4ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b52313b9-14f2-478e-9cb3-eeceb8f60791', 'Mihrab', false, '11ff0b7e-f3b2-4a03-ba7c-d82791fcb4ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90a0a55f-ead4-496b-b4fd-4d69a6855c14', 'Minaret', false, '11ff0b7e-f3b2-4a03-ba7c-d82791fcb4ba');
