INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37bb43ac-c6a8-4167-8f7c-6804ee2b9b32', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'What were the five distinct ruling dynasties of the Delhi Sultanate in chronological order (1206 to 1526 CE)?', 'Chronological sequence: Mamluks (1206–1290) → Khaljis (1290–1320) → Tughluqs (1320–1414) → Sayyids (1414–1451) → Lodis (1451–1526).', NOW()) ON CONFLICT DO NOTHING;
