INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('771e80c1-c3ba-423b-a6dc-d76801813d67', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'Which ambitious Afghan ruler defeated Mughal Emperor Humayun in 1540 and established the Sur Empire, creating an administrative model later adopted by Emperor Akbar?', 'Sher Shah Suri (r. 1540–1545 CE) standardized silver Rupiya currency, built the Grand Trunk Road, and designed administrative revenue systems.', NOW()) ON CONFLICT DO NOTHING;
