INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('334ac800-7f13-4897-8e70-808522e1ec0a', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'What was the massive congregational mosque built by the Delhi Sultans in their first city (Dehli-i Kuhna) called?', 'Quwwat al-Islam mosque and Qutb Minar were initiated by Qutbuddin Aibak and expanded by Iltutmish and Alauddin Khalji.', NOW()) ON CONFLICT DO NOTHING;
