INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d140450-429a-4d34-8c49-22a70e7b28d7', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'Who was the military general under Alauddin Khalji who led sensational military campaigns deep into South India (Warangal, Dwarasamudra, Madurai)?', 'Malik Kafur commanded Alauddin''s southern military expeditions between 1309 and 1311 CE, extracting vast tribute in elephants and gold.', NOW()) ON CONFLICT DO NOTHING;
