INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b69d1ed-7b26-4f53-ba82-9e19b95ddd80', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'What was the primary language of administration and official court record-keeping throughout the Delhi Sultanate?', 'Persian was the elite court language and bureaucratic administrative medium of the Delhi Sultanate.', NOW()) ON CONFLICT DO NOTHING;
