INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('83f77b6c-cbee-49e3-9633-861741356ae9', 'Class 7', 'Social Science', 'Chapter 3: Delhi: 12th to 15th Century', 'Medium', 'Why did author Ziauddin Barani criticize Sultan Muhammad Tughluq for appointing wine distillers, barbers, cooks, and gardeners to high administrative posts?', 'Barani''s conservative aristocratic perspective decried merit-based or non-noble appointments as a decline of imperial judgment.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52055ac3-012b-4152-9b31-a494483b6048', 'Barani reflected aristocratic elite bias and lamented the loss of aristocratic monopoly over state power to low-born individuals', true, '83f77b6c-cbee-49e3-9633-861741356ae9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0c55e8b-ead6-420f-bee2-2fbc1cc3f471', 'Because the appointees could not cook well', false, '83f77b6c-cbee-49e3-9633-861741356ae9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc2a7373-4ee8-4a6f-ac6c-85cb4df9d71f', 'Because the appointees were foreigners from England', false, '83f77b6c-cbee-49e3-9633-861741356ae9');
