INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abc8c1c7-2a27-4cd5-b94c-e9f7cae466ad', 'तत्सम शब्द', false, '3dbead6b-97e3-4ac8-b8da-95dc942ee7f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a07bfd6b-639c-4b99-82f3-7eae71049ac5', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Easy', 'दो या दो से अधिक सार्थक शब्दों या शब्दांशों के योग से बनने वाले शब्द क्या कहलाते हैं?', 'सार्थक खंडों के योग से बने नए शब्द ''यौगिक शब्द'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
