INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5ead900a-4559-447a-89c4-eafdc4ac77d4', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Easy', 'वे यौगिक शब्द जो अपने सामान्य अर्थ को छोड़कर किसी विशेष अर्थ (विशिष्ट रूढ़ अर्थ) के लिए प्रसिद्ध हो जाते हैं, उन्हें क्या कहते हैं?', 'यौगिक होकर भी किसी रूढ़ लाक्षणिक अर्थ को प्रकट करने वाले शब्द ''योगरूढ़'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7af1a3a0-7667-4f04-9127-397849b4a28f', 'योगरूढ़ शब्द (जैसे: पंकज = कीचड़ में जन्मा कमल, दशानन = रावण, लंबोदर = गणेश)', true, '5ead900a-4559-447a-89c4-eafdc4ac77d4');
