INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b7f61eb-1745-4ae2-92c4-01673029d6b8', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Easy', 'प्रयोग / व्याकरणिक प्रकार्य (विकार) के आधार पर शब्द के मुख्य रूप से दो भेद कौन-से होते हैं?', 'व्याकरणिक विकार के 2 भेद हैं: विकारी (संज्ञा, सर्वनाम, विशेषण, क्रिया) और अविकारी/अव्यय।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bdc3763-e4e3-4518-af52-2cbea82f73fe', 'विकारी शब्द (Mutable) और अविकारी शब्द (Immutable / अव्यय)', true, '6b7f61eb-1745-4ae2-92c4-01673029d6b8');
