INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0af5118-18f2-4a9e-b46b-6efcd0553e13', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Easy', 'जिन शब्दों का रूप लिंग, वचन, कारक और काल के प्रभाव से बदल जाता है (परिवर्तित होता है), उन्हें क्या कहते हैं?', 'लिंग, वचन, कारक के अनुसार रूपांतरित होने वाले शब्द ''विकारी'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
