INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a3046f44-da5d-4306-a1ed-05298eb3bc5e', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Medium', 'जिन शब्दों के रूप में लिंग, वचन, कारक या काल के कारण कभी कोई परिवर्तन नहीं होता (सदा एक समान रहते हैं), उन्हें क्या कहते हैं?', 'न व्यय इति अव्यय: जो कभी रूपांतरित न हों, वे ''अविकारी / अव्यय'' कहलाते हैं (क्रियाविशेषण, समुच्चयबोधक, संबंधबोधक, विस्मयादिबोधक, निपात)।', NOW()) ON CONFLICT DO NOTHING;
