INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53527cc0-98f4-40a6-8384-b03a475f7924', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Medium', 'अर्थ के आधार पर जिन शब्दों का एक निश्चित अर्थ निकलता है, उन्हें ''सार्थक'' कहते हैं ; जबकि जिनका कोई स्वतंत्र अर्थ नहीं होता (जैसे: पानी-वानी, चाय-वाय, रोटी-वोटी में ''वानी, वाय, वोटी'') उन्हें क्या कहते हैं?', 'जिन ध्वनियों का कोई स्वतंत्र शब्दकोशीय अर्थ नहीं होता, वे बोलचाल के ''निरर्थक शब्द'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('292ae902-a957-437e-ab25-c60adecfb5eb', 'निरर्थक शब्द', true, '53527cc0-98f4-40a6-8384-b03a475f7924');
