INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43cfffa1-b3a8-41c8-ac19-49c832f0680f', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Medium', 'समान अर्थ प्रकट करने वाले भिन्न-भिन्न शब्दों (जैसे: सूर्य = रवि, भानु, दिनकर, भास्कर) को क्या कहते हैं?', 'समान अर्थ वाले पर्यायवाची (समानार्थी) शब्द कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
