INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('deb9cc4a-8dc9-401d-b96d-61df7cdc54ad', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Medium', 'परस्पर विपरीत (उल्टा) अर्थ प्रकट करने वाले शब्दों (जैसे: सत्य - असत्य, अमृत - विष, अनुराग - विराग) को क्या कहते हैं?', 'विपरीत भाव/अर्थ देने वाले शब्द ''विलोम'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
