INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c6d624f-e02b-4c26-a570-07870440c0f6', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Medium', 'जिन शब्दों के एक से अधिक अर्थ होते हैं (जैसे: ''कर'' = हाथ, टैक्स, किरण, सूंड), उन्हें क्या कहते हैं?', 'प्रसंगानुसार भिन्न-भिन्न अर्थ देने वाले शब्द ''अनेकार्थी शब्द'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
