INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3be6832b-a919-429c-aa0d-c75ffd756adb', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Medium', 'जो शब्द सुनने और पढ़ने में लगभग एक समान लगते हैं परन्तु उनके अर्थ में भारी अंतर होता है (जैसे: ''अनल'' = आग और ''अनिल'' = वायु), उन्हें क्या कहते हैं?', 'समान ध्वन्यात्मक आभास वाले भिन्न अर्थी शब्द ''श्रुतिसम भिन्नार्थक'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
