INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e506eaf-876a-4f02-803a-407ff02fabc8', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Medium', '''दशानन'' (दस आननों वाला) शब्द किस वर्ग का शब्द है?', 'दश + आनन यौगिक होकर रावण के लिए विशेष अर्थ में निश्चित होने से ''योगरूढ़'' है।', NOW()) ON CONFLICT DO NOTHING;
