INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c65895a1-5149-4481-b439-8ec70e931859', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Medium', 'पुर्तगाली भाषा से हिंदी में आए शब्दों का सही युग्म कौन-सा है?', 'पुर्तगाली व्यापारियों से हिंदी में आए शब्द: आलू, बाल्टी, साबुन, तौलिया, चाबी, आलमारी, गमला।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1882a2c-67cd-4f39-b48e-779603ad174e', 'आलू, बाल्टी, साबुन, तोलिया, कमरा', true, 'c65895a1-5149-4481-b439-8ec70e931859');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef718c6e-07c4-4000-932d-0e430e1486d1', 'स्कूल, डॉक्टर', false, 'c65895a1-5149-4481-b439-8ec70e931859');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2880bc9e-1553-4a78-ab5a-c5495bd902c2', 'किताब, अखबार', false, 'c65895a1-5149-4481-b439-8ec70e931859');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37e3a193-bafa-4f08-b4c9-7d13e9fb4358', 'कैंची, तोप', false, 'c65895a1-5149-4481-b439-8ec70e931859');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('09b34a62-e377-430d-bcbc-3225c6cba238', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Medium', 'तुर्की भाषा से हिंदी में आए प्रमुख शब्दों का सही समूह कौन-सा है?', 'तुर्की मूल के शब्द: कैंची, तोप, बारूद, बेगम, तलाश, चाकू, बहादुर।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a637301-08af-43df-a3b4-60e096a9b60a', 'कैंची, तोप, बारूद, बेगम, कुली', true, '09b34a62-e377-430d-bcbc-3225c6cba238');
