INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc97a6fa-cef1-4a2d-9977-23e2aa3c7f3d', 'स्टेशन, रेल', false, '09b34a62-e377-430d-bcbc-3225c6cba238');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa08d09c-8c55-455e-b695-17ba258ab225', 'अदालत, वकील', false, '09b34a62-e377-430d-bcbc-3225c6cba238');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2564c9a9-618d-4267-aa2f-f913cba61dc8', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a047203-5823-4749-9523-e28e41992440', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '2564c9a9-618d-4267-aa2f-f913cba61dc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2eb067e5-0ccf-44a9-aa9c-a6215059a9ad', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '2564c9a9-618d-4267-aa2f-f913cba61dc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dcb614f-95f5-4eb6-989b-76acbae3a541', '(A) सही है, परन्तु (R) गलत है।', false, '2564c9a9-618d-4267-aa2f-f913cba61dc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('461a4b54-4347-434a-b8ba-39a277e979dd', '(A) गलत है, परन्तु (R) सही है।', false, '2564c9a9-618d-4267-aa2f-f913cba61dc8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f52c76b3-3608-4b6b-8312-b1d068749cd7', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'Spot the IMPOSTER in the following group of तत्सम - तद्भव युग्मों में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96341914-b740-4f3e-bf9f-4d334d722076', 'युग्म 1', false, 'f52c76b3-3608-4b6b-8312-b1d068749cd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25d0da84-f708-4f98-8957-8ac42e7d9c5b', 'युग्म 2', false, 'f52c76b3-3608-4b6b-8312-b1d068749cd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4288b263-0374-4ad2-af7e-0e521c986807', 'युग्म 3', false, 'f52c76b3-3608-4b6b-8312-b1d068749cd7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88d22f5d-f053-4c5a-8ed0-449412c6bb75', 'युग्म 4 (अग्नि का तद्भव ''आग'' होता है, ''पानी'' नहीं)', true, 'f52c76b3-3608-4b6b-8312-b1d068749cd7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c0677a3-e9ba-4df2-a68c-5e0fd94f33cc', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'सुमेलित कीजिए (शब्द और उनका उत्पत्तिगत भाषाई स्रोत):
(क) कूप, दंत, मुख     -> (i) तत्सम शब्द (संस्कृत)
(ख) हाथ, कुआँ, दाँत    -> (ii) तद्भव शब्द
(ग) पगड़ी, लोटा, जूता  -> (iii) देशज शब्द
(घ) लालटेन, डॉक्टर, पेन-> (iv) विदेशी / आगत शब्द', 'कूप/दंत = तत्सम; हाथ/कुआँ = तद्भव; लोटा/पगड़ी = देशज; लालटेन (lantern)/पेन = विदेशी।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b417243-be14-44fa-9060-a2d9dc4b968f', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, '0c0677a3-e9ba-4df2-a68c-5e0fd94f33cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c375e03-be22-4961-9277-626e8c9c60f2', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '0c0677a3-e9ba-4df2-a68c-5e0fd94f33cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5ec1139-56fc-49c5-a55c-3ba3d4b2a932', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '0c0677a3-e9ba-4df2-a68c-5e0fd94f33cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9273685-bbea-4f64-b94a-2eec0a762b58', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '0c0677a3-e9ba-4df2-a68c-5e0fd94f33cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96139d40-1cc8-4223-9df5-3c683a41a994', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'श्रुतिसम भिन्नार्थक शब्दों ''कुल'' और ''कूल'' का क्रमशः शुद्ध अर्थ क्या है?', 'कुल (ह्रस्व उ) = वंश/समग्र; कूल (दीर्घ ऊ) = नदी का किनारा/तट।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3db814a0-e095-422a-9bcf-bd2f55c5a8d8', '''कुल'' = वंश / सब (Total/Family) ; ''कूल'' = किनारा / तट (Bank of river)', true, '96139d40-1cc8-4223-9df5-3c683a41a994');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36520d08-99e5-413f-ba64-59ddfbf06ca9', '''कुल'' = ठंडा ; ''कूल'' = परिवार', false, '96139d40-1cc8-4223-9df5-3c683a41a994');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb6920ff-b2e3-495d-9387-0950a571972a', '''कुल'' = किनारा ; ''कूल'' = वंश', false, '96139d40-1cc8-4223-9df5-3c683a41a994');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26cc3427-37b8-4965-9f42-a87c2f08126a', 'दोनों का अर्थ ''पानी'' है', false, '96139d40-1cc8-4223-9df5-3c683a41a994');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('133ceaa9-9146-47fa-89e9-44151dcccab7', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'श्रुतिसम भिन्नार्थक शब्दों ''गृह'' और ''ग्रह'' का क्रमशः सही अर्थ क्या है?', 'गृह (ऋ की मात्रा) = आवास/घर; ग्रह (पदेन र) = आकाशीय खगोलीय पिंड (Planet)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74812d2e-e0a9-4c56-8af3-8514b46198a5', '''गृह'' = घर (House) ; ''ग्रह'' = आकाशीय पिंड / नक्षत्र (Planet - जैसे: सूर्य, मंगल)', true, '133ceaa9-9146-47fa-89e9-44151dcccab7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19eca3ac-c67f-4392-ab98-1064b93ea84b', '''गृह'' = नक्षत्र ; ''ग्रह'' = घर', false, '133ceaa9-9146-47fa-89e9-44151dcccab7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfbf3bba-d832-4cdd-922c-01f7117e2d56', 'दोनों का अर्थ ''सूर्य'' है', false, '133ceaa9-9146-47fa-89e9-44151dcccab7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0158b7e1-3d37-422d-9643-1874abf4079e', 'दोनों का अर्थ ''दुकान'' है', false, '133ceaa9-9146-47fa-89e9-44151dcccab7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f94c1def-a58d-453e-b385-b5084eaf3949', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'अनेकार्थी शब्द ''कनक'' के तीन प्रमुख संदर्भगत अर्थ क्या हैं?', '''कनक कनक ते सौगुनी...'' कनक के प्रमुख अर्थ: स्वर्ण (सोना), धतूरा और गेहूँ हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62ad1a2b-4a33-4183-8fc8-58ef79eeae18', 'सोना (Gold), धतूरा (Poisonous plant), और गेहूँ (Wheat)', true, 'f94c1def-a58d-453e-b385-b5084eaf3949');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('629ce7f8-6a79-4956-88a9-64cbf551049d', 'चाँदी, लोहा, और पीतल', false, 'f94c1def-a58d-453e-b385-b5084eaf3949');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2bf1139-0d67-4700-9ad2-e1096ee5c50f', 'पेड़, फल, और फूल', false, 'f94c1def-a58d-453e-b385-b5084eaf3949');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9202b334-5fa3-467a-82b9-2266f0535ee7', 'आकाश, बादल, और वर्षा', false, 'f94c1def-a58d-453e-b385-b5084eaf3949');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68ed71f7-0572-4c06-b54f-a64e9f5e3259', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'अनेकार्थी शब्द ''अंबर'' के दो मुख्य अर्थ क्या हैं?', 'अंबर = नभ/गगन (आकाश) तथा वस्त्र/पट (कपड़ा - जैसे: पीतांबर)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('899bc584-1891-46fc-9065-7ac3f445a2a8', 'आकाश (Sky) और वस्त्र / कपड़ा (Cloth)', true, '68ed71f7-0572-4c06-b54f-a64e9f5e3259');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f825ec4-0b48-43dc-916f-d2f88fe65a84', 'धरती और पाताल', false, '68ed71f7-0572-4c06-b54f-a64e9f5e3259');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5b31c4b-ec81-46cc-bf60-b93b99e9a794', 'पानी और आग', false, '68ed71f7-0572-4c06-b54f-a64e9f5e3259');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cf4ff0a-ba6e-4456-beb7-d6fd3ef9cf37', 'राजा और रानी', false, '68ed71f7-0572-4c06-b54f-a64e9f5e3259');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5087d6c1-fec5-4d1e-9872-7eebe0c5a940', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'अरबी और फ़ारसी भाषा से हिंदी में आए शब्दों का कौन-सा समूह पूर्णतः शुद्ध है?', 'कानून/फैसला/तारीख = अरबी; कागज़/चश्मा/बाज़ार/शादी = फ़ारसी।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dae74e3-3b02-4158-8805-c33cae963a56', 'अरबी: कानून, फैसला, अमीर, तारीख ; फ़ारसी: कागज़, चश्मा, ज़मीन, बाज़ार, शादी', true, '5087d6c1-fec5-4d1e-9872-7eebe0c5a940');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07ccd089-b538-4a42-a000-72db911f8bf1', 'अरबी: स्कूल, पेन ; फ़ारसी: डॉक्टर, बस', false, '5087d6c1-fec5-4d1e-9872-7eebe0c5a940');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44809d90-8053-4a44-b43d-ed32b21f64a5', 'अरबी: चाय, लीची ; फ़ारसी: रिक्शा, सुनामी', false, '5087d6c1-fec5-4d1e-9872-7eebe0c5a940');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b056b1d9-e863-4860-a38d-876caaef1ad7', 'अरबी: कुर्ता, कैंची ; फ़ारसी: तोप, बारूद', false, '5087d6c1-fec5-4d1e-9872-7eebe0c5a940');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a025145f-4620-4af0-af1c-b82b133cf2e8', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'चीनी भाषा और जापानी भाषा से हिंदी में आए शब्दों का सही युग्म कौन-सा है?', 'चीनी मूल: चाय, लीची, चीकू; जापानी मूल: रिक्शा (Jinrikisha), सुनामी (Tsunami)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27f6fd69-45b4-4c54-96ad-ede84bb68e04', 'चीनी भाषा: चाय, लीची ; जापानी भाषा: रिक्शा, सुनामी', true, 'a025145f-4620-4af0-af1c-b82b133cf2e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('baae9760-81fe-4939-9684-b2996515e36d', 'चीनी भाषा: साबुन, बाल्टी ; जापानी भाषा: स्कूल, बस', false, 'a025145f-4620-4af0-af1c-b82b133cf2e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c06a63a-832b-4611-be19-b4173ea14dba', 'चीनी भाषा: तोप, बारूद ; जापानी भाषा: वकील, अदालत', false, 'a025145f-4620-4af0-af1c-b82b133cf2e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('032f5b2b-e852-4120-b4bc-2c79a44e064d', 'चीनी भाषा: रोटी, पानी ; जापानी भाषा: घर, मकान', false, 'a025145f-4620-4af0-af1c-b82b133cf2e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1dd491d-34fd-494e-b3bb-6e705e797a08', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'योगरूढ़ शब्दों में कौन-सा समास विशेष रूप से अंतर्निहित होता है?', 'सभी बहुव्रीहि समास के समस्त पद रचना की दृष्टि से ''योगरूढ़ शब्द'' होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0aa4de49-9a36-4bf3-932e-9ff51bdad03f', 'बहुव्रीहि समास (जिसमें दोनों पद मिलकर किसी तीसरे अन्य पद की विशेषता बताते हैं, जैसे: चक्रपाणि = विष्णु)', true, 'f1dd491d-34fd-494e-b3bb-6e705e797a08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43e51bcb-8493-48c8-b70b-4f61612f9e9c', 'द्वंद्व समास', false, 'f1dd491d-34fd-494e-b3bb-6e705e797a08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee6ecc57-356d-4d2a-a521-52b467d8c09e', 'अव्ययीभाव समास', false, 'f1dd491d-34fd-494e-b3bb-6e705e797a08');
