INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f274466-24d0-4dcb-beee-850f1c65be59', 'संस्कृत (''छाया'') + फ़ारसी प्रत्यय (''दार'') = छायादार', true, '2a71dd14-89af-40a6-86ac-59aa3efe9c19');
