INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ac7258a-11fa-46b5-b815-ef1d5326dbeb', 'पुर्तगाली + जापानी', false, '2a71dd14-89af-40a6-86ac-59aa3efe9c19');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1669a85e-72df-4b1d-a025-574b438432a1', 'Class 7', 'Hindi Grammar', 'Chapter 3: शब्द विचार', 'Hard', 'शब्द विचार (Morphology) के विशद अध्ययन का भाषा प्रयोग में क्या केंद्रीय निष्कर्ष है?', 'अध्याय 3 हिंदी की समावेशी बहु-सांस्कृतिक शब्द-संपदा, व्युत्पत्ति-सौंदर्य और समृद्ध पद-विन्यास को प्रतिपादित करता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87b1b150-3625-49c0-b081-3c92d0552deb', 'हिंदी शब्द संपदा एक अविरल प्रवाहमयी नदी के समान है, जिसने संस्कृत की तत्सम-तद्भव परंपरा, देशज बोलियों की मौलिकता और विदेशी भाषाओं के आगत शब्दों को आत्मसात कर अद्भुत अभिव्यक्ति-क्षमता प्राप्त की है', true, '1669a85e-72df-4b1d-a025-574b438432a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1220c601-1355-4929-8719-14a9f5af1ec7', 'शब्दों का केवल एक ही अर्थ होना चाहिए', false, '1669a85e-72df-4b1d-a025-574b438432a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1607eaee-3f61-45de-a7af-6d007c70ba92', 'विदेशी शब्दों का प्रयोग पूरी तरह बंद होना चाहिए', false, '1669a85e-72df-4b1d-a025-574b438432a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b83465a6-df87-40d2-9748-681795e4338d', 'शब्द विचार केवल प्राथमिक स्तर की पढ़ाई है', false, '1669a85e-72df-4b1d-a025-574b438432a1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6b77434-95ef-4d93-b021-e3fcade1c1f3', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Easy', 'Chemical substances that have a characteristic SOUR taste and turn Blue Litmus paper RED are called:', 'Acids (from Latin ''acere'' meaning sour) taste sour and turn blue litmus red.', NOW()) ON CONFLICT DO NOTHING;
