INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4ceee0c-3a1b-40b8-b999-2543fd4a4225', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Easy', 'The chemical reaction between an Acid and a Base to form Salt and Water with the evolution of heat is called:', 'Acid + Base → Salt + Water + Heat (Exothermic Neutralization).', NOW()) ON CONFLICT DO NOTHING;
