INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7ff59e9-cbfa-4c41-a5fc-8543d6d4d8a1', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Easy', 'What color does the synthetic indicator Phenolphthalein show in a BASIC solution?', 'Phenolphthalein turns vivid pink in alkaline/basic solutions (pH > 8.2) and remains colorless in acidic solutions.', NOW()) ON CONFLICT DO NOTHING;
