INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ad6acb5-9563-4046-af6b-0f17ffbb81f9', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Easy', 'What is the chemical name of Slaked Lime / Lime Water used to test carbon dioxide?', 'Lime water is a saturated aqueous solution of Calcium Hydroxide [Ca(OH)₂].', NOW()) ON CONFLICT DO NOTHING;
