INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d27a9c7-c46f-485a-9041-3140abcaa614', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What happens when a yellow turmeric stain on a white shirt is scrubbed with washing SOAP?', 'Curcumin in turmeric acts as a natural indicator, shifting from yellow to reddish-brown in basic alkaline media (soap).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49d5a5d7-9175-413e-bd79-248f759f3bd2', 'The yellow turmeric stain turns REDDISH-BROWN because soap is basic in nature; when washed with plenty of water, it turns yellow again', true, '9d27a9c7-c46f-485a-9041-3140abcaa614');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94dca450-b1a6-4c01-bed3-830ae1e0361c', 'The stain turns blue', false, '9d27a9c7-c46f-485a-9041-3140abcaa614');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd606dee-4226-4bbe-bf68-d977519788c7', 'The stain disappears completely', false, '9d27a9c7-c46f-485a-9041-3140abcaa614');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ea156a3-25c4-4ccb-aa6f-b50cc75567b3', 'The shirt catches fire', false, '9d27a9c7-c46f-485a-9041-3140abcaa614');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('685c3946-0a89-4132-bad9-0c191e346dd8', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'How does natural China Rose (Hibiscus) indicator change color in acidic and basic solutions?', 'China rose anthocyanin extract turns acidic solutions dark magenta/pink and basic solutions bright green.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd33bb46-1550-4a71-91ff-7deca2fa66d9', 'Turns ACIDIC solutions to DARK PINK (Magenta) and BASIC solutions to GREEN', true, '685c3946-0a89-4132-bad9-0c191e346dd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35af48d4-0f23-46f7-b8cb-c2d38be407a7', 'Turns acidic to green and basic to pink', false, '685c3946-0a89-4132-bad9-0c191e346dd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9aa3baeb-4f8c-4925-a1a1-ce604054a85b', 'Turns both solutions blue', false, '685c3946-0a89-4132-bad9-0c191e346dd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09343734-40a3-449b-93a4-d9d5903d925b', 'Shows no color change in either', false, '685c3946-0a89-4132-bad9-0c191e346dd8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7af0b9f4-4b7c-48dc-a308-9b8de08ab4ad', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'Why is Calamine lotion (containing Zinc Carbonate) or moist Baking Soda applied to skin after an Ant bite?', 'Basic calamine (ZnCO₃) or sodium hydrogen carbonate (NaHCO₃) chemically neutralizes injected acidic formic acid.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0487aa89-3298-4eb0-a5ac-9454befb7c4b', 'Zinc carbonate and baking soda are mild BASES that neutralize the acidic formic acid injected by the ant bite, relieving pain', true, '7af0b9f4-4b7c-48dc-a308-9b8de08ab4ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0d50463-a2c8-48af-924e-04dfb1cdbc3d', 'To kill the ant', false, '7af0b9f4-4b7c-48dc-a308-9b8de08ab4ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3758962-6a13-4f10-8a1a-1e9a0b39b739', 'Because calamine is an acid', false, '7af0b9f4-4b7c-48dc-a308-9b8de08ab4ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44364a5d-86f1-4331-a977-73a6163ce24e', 'To make the skin waterproof', false, '7af0b9f4-4b7c-48dc-a308-9b8de08ab4ad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e681dd0a-3561-4517-a3cd-4eac3ea27f37', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'Why must agricultural soil that has become too ACIDIC due to excessive chemical fertilizer use be treated with Quicklime (Calcium Oxide) or Slaked Lime (Calcium Hydroxide)?', 'Liming agricultural soil neutralizes toxic soil acidity, optimizing nutrient uptake.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('775e54fa-1a77-4069-9fe3-b08d317eb505', 'Quicklime and slaked lime are BASES that neutralize soil acidity, restoring the optimal neutral pH for healthy plant root growth', true, 'e681dd0a-3561-4517-a3cd-4eac3ea27f37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b60e7278-1475-4150-a6b4-dcce9c510ba0', 'To add color to the soil', false, 'e681dd0a-3561-4517-a3cd-4eac3ea27f37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4aaf5507-bcd0-41f0-9c97-b704e265ed46', 'To kill earthworms', false, 'e681dd0a-3561-4517-a3cd-4eac3ea27f37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c6e2904-c1ea-48df-a6c9-369890594d54', 'To make the soil sandy', false, 'e681dd0a-3561-4517-a3cd-4eac3ea27f37');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7297f4f4-d5e7-48eb-a45d-349e868db40e', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'If agricultural soil is too BASIC (alkaline), what is added to improve soil fertility?', 'Decaying organic compost/manure releases humic and fulvic acids, neutralizing alkaline soil.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60aad0bd-ba24-4050-b80c-5d63f6bd2435', 'Organic Matter / Manure (which decomposes to release natural acids that neutralize the basic soil)', true, '7297f4f4-d5e7-48eb-a45d-349e868db40e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('702e72f3-118f-470e-88da-365696f274fe', 'More quicklime', false, '7297f4f4-d5e7-48eb-a45d-349e868db40e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fad571de-9d3d-4fa3-b6dd-052ab1d715e2', 'Baking soda', false, '7297f4f4-d5e7-48eb-a45d-349e868db40e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9778480e-068a-4a18-a4ea-c70601a4cbce', 'Bleaching powder', false, '7297f4f4-d5e7-48eb-a45d-349e868db40e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a67933b3-997c-433d-a523-f1082d6d0cab', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'Why must acidic factory effluents and industrial chemical waste be strictly treated with basic substances before being discharged into rivers?', 'Neutralization of industrial effluents prevents aquatic ecotoxicity and preserves aquatic biodiversity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f68a8dad-50ce-43d5-aec1-5498b21451a9', 'Untreated acidic waste drastically lowers river water pH, poisoning and killing fish, aquatic organisms, and destroying freshwater ecosystems', true, 'a67933b3-997c-433d-a523-f1082d6d0cab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77c889c7-8383-4cba-826f-cf23a202a34b', 'To change the color of river water to red', false, 'a67933b3-997c-433d-a523-f1082d6d0cab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('801bdad9-7883-4f05-9c69-df34bdb5f469', 'To make water boil', false, 'a67933b3-997c-433d-a523-f1082d6d0cab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('531a7ab7-cd0b-4467-b4c4-8f6b2cbe6fdf', 'Because fish like drinking base', false, 'a67933b3-997c-433d-a523-f1082d6d0cab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('21237f31-4e02-47ee-a2dc-ccc6d3655d51', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What is ''Acid Rain'' and what atmospheric pollutant gases cause it?', 'Atmospheric SO₂ and NO₂ form H₂SO₄ and HNO₃, causing acid precipitation (pH < 5.6) damaging monuments (Taj Mahal marble cancer).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('463ebf93-d354-4d9a-b464-cb09d6a6a9bb', 'Rain containing excessive dissolved acids formed when atmospheric pollutants like Sulfur Dioxide (SO₂) and Nitrogen Dioxide (NO₂) react with rain droplets to form Sulfuric and Nitric acids', true, '21237f31-4e02-47ee-a2dc-ccc6d3655d51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8527e742-039d-4cbb-a30e-decc37965c58', 'Rain of pure hydrochloric acid falling from clouds', false, '21237f31-4e02-47ee-a2dc-ccc6d3655d51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0089982-a31c-438e-9da6-bcd45ad7c2b2', 'Rain caused by burning wood only', false, '21237f31-4e02-47ee-a2dc-ccc6d3655d51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f436dcc-56b8-4d87-b812-435c4befc277', 'Rain containing lemon juice', false, '21237f31-4e02-47ee-a2dc-ccc6d3655d51');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('80a33f36-ee5c-4f98-8d74-6c5f2373e063', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What organic acid is naturally found in Tamarind (Imli), unripened green Grapes, and raw Mangoes?', 'Tartaric acid is a dicarboxylic organic acid abundant in tamarind and unripe grapes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b19320b3-b548-4d08-a41b-1d83ec94f1ef', 'Tartaric Acid', true, '80a33f36-ee5c-4f98-8d74-6c5f2373e063');
