INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efa6a17b-94f1-4290-904b-cf0d3bb4e09d', 'Lactic Acid', false, '80a33f36-ee5c-4f98-8d74-6c5f2373e063');
