INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2117f8c6-a697-4773-b9c9-d80e1ea72a1f', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What acid is naturally present in Spinach (Palak) and Tomatoes?', 'Spinach and tomatoes contain naturally occurring Oxalic Acid.', NOW()) ON CONFLICT DO NOTHING;
