INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2b99123-ff0f-4ac2-a04c-abd34e29edf2', 'Formic Acid', false, '2117f8c6-a697-4773-b9c9-d80e1ea72a1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c551304-dacb-47e5-85dc-aa026ef83946', 'Sulfuric Acid', false, '2117f8c6-a697-4773-b9c9-d80e1ea72a1f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('363b561f-7ee6-4524-918b-a68dadd36a41', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What is the chemical name and formula of Common Salt used in daily food?', 'Common table salt is Sodium Chloride (NaCl), formed by neutralizing HCl with NaOH.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0be7a660-c7ad-460b-b66a-33b72b66513a', 'Sodium Chloride (NaCl)', true, '363b561f-7ee6-4524-918b-a68dadd36a41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b29870b-dd6f-477f-8beb-7287f4f98ea6', 'Sodium Bicarbonate (NaHCO₃)', false, '363b561f-7ee6-4524-918b-a68dadd36a41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d43173da-6642-4f1d-a3f9-dfbe29e44ca4', 'Calcium Chloride (CaCl₂)', false, '363b561f-7ee6-4524-918b-a68dadd36a41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f91c6498-87cc-4dac-8ea7-ed10f4a4208d', 'Potassium Chloride (KCl)', false, '363b561f-7ee6-4524-918b-a68dadd36a41');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b139aee-8d29-4ea6-a9ff-1b71bbc7052a', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What happens to the temperature of the reaction mixture during a Neutralization Reaction in a test tube?', 'Enthalpy of neutralization: H⁺(aq) + OH⁻(aq) → H₂O(l) + 57.3 kJ/mol (exothermic heat release).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12cfe8db-8dbc-40b6-b5a3-146e0992a8e7', 'The temperature INCREASES (the test tube feels hot because neutralization is an exothermic reaction that releases heat energy)', true, '8b139aee-8d29-4ea6-a9ff-1b71bbc7052a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7346d8e4-9837-4531-9425-7c155bcd0096', 'The temperature decreases and turns into ice', false, '8b139aee-8d29-4ea6-a9ff-1b71bbc7052a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('170fff58-deef-4aa9-8d4b-6bed16655f98', 'The temperature remains exactly unchanged', false, '8b139aee-8d29-4ea6-a9ff-1b71bbc7052a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f79585f-9710-4761-833b-e9eab5599ed0', 'The mixture catches fire instantly', false, '8b139aee-8d29-4ea6-a9ff-1b71bbc7052a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a0ca4377-7dfb-4c2c-a13b-b200dbaffa2e', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'Which base is used in window-cleaning fluids and glass sprays?', 'Ammonium hydroxide [NH₄OH] dissolves grease cleanly without leaving residue on glass windows.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba4f79dd-fab6-4cf1-8508-3a3462ae775a', 'Ammonium Hydroxide [NH₄OH]', true, 'a0ca4377-7dfb-4c2c-a13b-b200dbaffa2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a86c0bc-40b0-4de6-88df-03783c9dd00a', 'Sodium Hydroxide [NaOH]', false, 'a0ca4377-7dfb-4c2c-a13b-b200dbaffa2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0567467a-9d5e-419c-aee3-84ee4d5f7b8e', 'Calcium Hydroxide [Ca(OH)₂]', false, 'a0ca4377-7dfb-4c2c-a13b-b200dbaffa2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfa5900e-5abc-4be8-a0ec-cf41dfeaf2d8', 'Magnesium Hydroxide [Mg(OH)₂]', false, 'a0ca4377-7dfb-4c2c-a13b-b200dbaffa2e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98bacf70-b96c-4d2e-9287-740f3bcc3ccb', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'Which strong base is used in manufacturing hard bar soaps and unclogging drain pipes?', 'Sodium hydroxide (NaOH / caustic soda) saponifies fats in soap making and dissolves organic drain blockages.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9791a03-6ddc-4b81-8570-340e6721de16', 'Sodium Hydroxide (Caustic Soda - NaOH)', true, '98bacf70-b96c-4d2e-9287-740f3bcc3ccb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7ae17cc-c5c7-4784-aadc-00eeac97ebfb', 'Lactic Acid', false, '98bacf70-b96c-4d2e-9287-740f3bcc3ccb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57e4cdca-d4b1-4358-b6e7-871924a2114e', 'Magnesium Hydroxide', false, '98bacf70-b96c-4d2e-9287-740f3bcc3ccb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e04064f-45ff-4e3d-87d8-ab839f9f0d17', 'Ammonium Hydroxide', false, '98bacf70-b96c-4d2e-9287-740f3bcc3ccb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5586dac4-a3a6-4f21-9823-8ae79c713771', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What is the nature of a solution that shows NO color change on both Red Litmus paper and Blue Litmus paper?', 'Neutral solutions (pH = 7) exhibit no proton exchange with litmus dye, causing zero color change.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e0c65a6-092c-449b-9973-f7ce402c323e', 'Neutral Solution (such as pure distilled water, sugar solution, or common salt solution)', true, '5586dac4-a3a6-4f21-9823-8ae79c713771');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('794c41a9-4fc3-40b5-88ed-fd2febff8fb3', 'Strongly Acidic Solution', false, '5586dac4-a3a6-4f21-9823-8ae79c713771');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1666421-15f0-49a0-b24f-7b249e51e078', 'Strongly Basic Solution', false, '5586dac4-a3a6-4f21-9823-8ae79c713771');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a258f420-6143-4ed4-be53-703796209b7e', 'Corrosive Acid', false, '5586dac4-a3a6-4f21-9823-8ae79c713771');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f25cc11e-1109-442a-946e-d674d0293f4a', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What is Ascorbic Acid commonly known as in human nutrition?', 'Ascorbic acid is Vitamin C, found abundantly in amla (Indian gooseberry) and citrus fruits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61317db5-8e10-4666-8204-d8e2a067f54b', 'Vitamin C (essential for immune health and preventing scurvy)', true, 'f25cc11e-1109-442a-946e-d674d0293f4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15e4a146-dd4e-401d-b5aa-940d77560976', 'Vitamin A', false, 'f25cc11e-1109-442a-946e-d674d0293f4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6912ae5d-6b7d-4007-accb-171b802912e9', 'Vitamin D', false, 'f25cc11e-1109-442a-946e-d674d0293f4a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad37dbef-e648-4a26-9497-6ae87bcad87a', 'Vitamin B12', false, 'f25cc11e-1109-442a-946e-d674d0293f4a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1fcfe390-be97-47cd-968a-ec69f693be87', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Medium', 'What happens when dilute Hydrochloric Acid (HCl) is mixed with Sodium Hydroxide (NaOH) in equal proportions?', 'Equimolar strong acid-strong base neutralization yields neutral aqueous NaCl and water: HCl + NaOH → NaCl + H₂O + ΔH.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('176a823f-e691-4b30-a63a-dd6b9fe7ff68', 'They neutralize each other completely to produce neutral Sodium Chloride (NaCl), Water (H₂O), and heat: HCl + NaOH -> NaCl + H₂O', true, '1fcfe390-be97-47cd-968a-ec69f693be87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('552b1861-0b1a-4665-8b42-8aec9b71e820', 'They produce poisonous chlorine gas only', false, '1fcfe390-be97-47cd-968a-ec69f693be87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a847f94c-a9b4-4e06-a21d-c00ca14f262a', 'They turn into pure alcohol', false, '1fcfe390-be97-47cd-968a-ec69f693be87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3250ca27-83c9-479a-ac7b-ce81ced23592', 'They freeze into solid dry ice', false, '1fcfe390-be97-47cd-968a-ec69f693be87');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5a91af4-44f2-4d50-8a5b-ff87b4556e5b', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8eccc9b0-7248-46fa-b963-69a076f98601', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'e5a91af4-44f2-4d50-8a5b-ff87b4556e5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7527a8f1-78ff-4016-8b05-59f478135b06', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'e5a91af4-44f2-4d50-8a5b-ff87b4556e5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69a1dc7a-0e0c-4ecb-a483-8e6c13e1c2ec', '(A) is true, but (R) is false.', false, 'e5a91af4-44f2-4d50-8a5b-ff87b4556e5b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71d81dbc-96b1-4ead-ace6-25ed60de9c33', '(A) is false, but (R) is true.', false, 'e5a91af4-44f2-4d50-8a5b-ff87b4556e5b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6aa9f12a-6e0e-409c-8681-bc78cf734b87', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'Spot the IMPOSTER in the following group of naturally occurring organic acids and their biological sources:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39476a25-8cea-40cf-b0bb-ceb66ae87123', 'Pair 1', false, '6aa9f12a-6e0e-409c-8681-bc78cf734b87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5bb3bea-2b76-4efe-b47f-6299b0b6fe26', 'Pair 2', false, '6aa9f12a-6e0e-409c-8681-bc78cf734b87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84646838-fc07-4a91-883c-39bc56c66206', 'Pair 3', false, '6aa9f12a-6e0e-409c-8681-bc78cf734b87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('addc2ab6-106c-4456-8c7c-113f4a6e8c4b', 'Pair 4 (Lemon contains CITRIC ACID, NOT mineral Hydrochloric Acid)', true, '6aa9f12a-6e0e-409c-8681-bc78cf734b87');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('00d5971d-3cbc-4b76-97f6-6f3d147edb77', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'A student is given three unlabeled test tubes containing: (A) Dilute Hydrochloric Acid, (B) Sodium Hydroxide solution, and (C) Distilled Water. She has ONLY Phenolphthalein indicator. How can she identify all three liquids?', 'Sequential titration logic: base triggers pink chromophore; acid neutralizes pink back to colorless; water maintains diluted pink.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a7a1db9-fab8-4097-acd6-6f589e7fb3a3', 'Add phenolphthalein to all 3: tube turning PINK is Base (B) ; mix pink solution into remaining two: the one that de-colorizes pink back to colorless is Acid (A), and the one that simply dilutes pink is Water (C)', true, '00d5971d-3cbc-4b76-97f6-6f3d147edb77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89e3c556-ebd7-4539-9951-d2fe685d3b22', 'Drink all three liquids to taste them', false, '00d5971d-3cbc-4b76-97f6-6f3d147edb77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dbb8d3e-5ba5-4430-b0f8-0aeb278b0ceb', 'Heat all three until they explode', false, '00d5971d-3cbc-4b76-97f6-6f3d147edb77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf808576-5924-4f3e-bd08-03d25974da21', 'Phenolphthalein cannot identify them without litmus', false, '00d5971d-3cbc-4b76-97f6-6f3d147edb77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75db16f9-a5b8-42ad-9ab9-c751d8a3bdff', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'Match Column I (Natural Indicators) with Column II (Color in Acid vs Base):
(a) Litmus Paper         -> (i) Red in Acid ; Blue in Base
(b) Turmeric Paste       -> (ii) Yellow in Acid ; Reddish-brown in Base
(c) China Rose Extract   -> (iii) Dark Pink/Magenta in Acid ; Green in Base
(d) Phenolphthalein      -> (iv) Colorless in Acid ; Pink in Base', 'Litmus = Red/Blue; Turmeric = Yellow/Red-brown; China rose = Magenta/Green; Phenolphthalein = Colorless/Pink.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddd9eb76-4b8e-4809-8889-1ffde68ef607', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '75db16f9-a5b8-42ad-9ab9-c751d8a3bdff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e1a4c8a-4c96-4446-99bd-33dfc5df650a', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '75db16f9-a5b8-42ad-9ab9-c751d8a3bdff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9ac8813-7d90-4a6e-9d93-a19bcc113dfb', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '75db16f9-a5b8-42ad-9ab9-c751d8a3bdff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9201ca51-e2b5-47da-8cd2-c758fd9c374c', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '75db16f9-a5b8-42ad-9ab9-c751d8a3bdff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bcfb91d6-d0a5-4587-8c78-26152e0fe430', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'Read the statements regarding salts formed in neutralization reactions:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68bd5d1b-0947-4160-acca-490041b75ba7', 'Statements 1 and 2 only', true, 'bcfb91d6-d0a5-4587-8c78-26152e0fe430');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e66ca78-3dd8-4387-9e26-1caf69980414', 'Statements 2 and 3 only', false, 'bcfb91d6-d0a5-4587-8c78-26152e0fe430');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51ef9868-136d-4b84-93bd-5c22c4d6585d', 'Statements 1 and 3 only', false, 'bcfb91d6-d0a5-4587-8c78-26152e0fe430');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb8f618c-3157-481d-abe2-84acc13f3078', 'All Statements 1, 2, and 3', false, 'bcfb91d6-d0a5-4587-8c78-26152e0fe430');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c8b3e48-c3c3-4fae-821a-bbe47ef125be', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'Why should sour and acidic foodstuffs (such as curd, pickles, lemon juice, vinegar) NEVER be stored in Brass, Copper, or Bronze metal containers?', 'Acidic corrosion of copper/brass yields toxic verdigris and cupric/zinc salts, causing heavy metal toxicity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('241ca3ac-119d-4ba0-84ca-867be3b6fd19', 'Organic acids react with copper and zinc to form toxic, poisonous metallic salts that can cause severe food poisoning', true, '0c8b3e48-c3c3-4fae-821a-bbe47ef125be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ed14ba8-ef7f-4c31-8812-258ce2d8ad5c', 'Because curd makes brass melt into water', false, '0c8b3e48-c3c3-4fae-821a-bbe47ef125be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36d0e96d-5101-4272-89f7-0176c518da8f', 'Because brass makes curd taste like honey', false, '0c8b3e48-c3c3-4fae-821a-bbe47ef125be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3e95bcd-970d-412e-bbb1-459b32e4c2a6', 'Because copper turns into gold in acid', false, '0c8b3e48-c3c3-4fae-821a-bbe47ef125be');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4cb5aaa1-10f6-409d-8cef-4af5de5b13e1', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'What is the difference between an ''Organic Acid'' and a ''Mineral Acid''?', 'Organic acids contain carbon carboxylic chains (weak electrolytes); mineral acids are inorganic strong protic acids.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb46b069-db05-4394-a431-3eae9b5fd90a', 'Organic acids are naturally occurring weak acids derived from plants and animals (e.g. citric, lactic, acetic) ; Mineral acids are strong synthetic laboratory acids derived from minerals (e.g. HCl, H₂SO₄, HNO₃)', true, '4cb5aaa1-10f6-409d-8cef-4af5de5b13e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32ce21e4-95a7-45aa-8d19-35430f3cb3e7', 'Organic acids are made of rock, mineral acids are made of water', false, '4cb5aaa1-10f6-409d-8cef-4af5de5b13e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9679957-83a4-4c47-830d-dd74e08f67b1', 'Mineral acids can be safely drunk by humans', false, '4cb5aaa1-10f6-409d-8cef-4af5de5b13e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf0c377e-6c77-45f0-9b15-abbd507d42bb', 'Both are identical in chemical strength', false, '4cb5aaa1-10f6-409d-8cef-4af5de5b13e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b5cbb94c-76f8-4197-9698-3163887c84ac', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'Consider four household substances:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b258250b-fd82-41c9-b26d-e663733f59d6', 'Substances 2 and 4 (Soap solution and Baking soda solution, because both are basic)', true, 'b5cbb94c-76f8-4197-9698-3163887c84ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d2aa0a0-66ed-4d4d-bfce-0f0139ccdf11', 'Substances 1 and 3', false, 'b5cbb94c-76f8-4197-9698-3163887c84ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cb6a989-36f7-477b-a1f6-6a2f2be96bc9', 'Substance 1 only', false, 'b5cbb94c-76f8-4197-9698-3163887c84ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e15c5910-77f3-4dc2-b693-f062e21f863b', 'Substance 3 only', false, 'b5cbb94c-76f8-4197-9698-3163887c84ac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e7de651a-530d-4d0a-bdb4-e5b26358141c', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'Why does adding a few drops of universal indicator to a solution provide far more diagnostic information than litmus paper?', 'Universal indicator displays a multi-spectral chromatic gradient mapping directly to the continuous 0–14 pH scale.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23a4b0d2-5a71-4d14-872b-f3e7b73cc126', 'Universal indicator is a blend of indicators that displays a continuous spectrum of colors corresponding to specific pH values from 0 to 14, indicating exact strength rather than just acid/base binary', true, 'e7de651a-530d-4d0a-bdb4-e5b26358141c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2d56fc4-4c2a-4b5a-8435-2c95a7f40463', 'Because universal indicator is made of silver', false, 'e7de651a-530d-4d0a-bdb4-e5b26358141c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82c355a1-fc20-4c07-aa94-fbe636b955b3', 'Because litmus paper works only in sunlight', false, 'e7de651a-530d-4d0a-bdb4-e5b26358141c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c17d6e6a-fb28-4789-93ee-a70d6359139b', 'Because universal indicator turns everything gold', false, 'e7de651a-530d-4d0a-bdb4-e5b26358141c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d780b91c-26b7-4dbc-915b-1cd067f4882d', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'Why does our stomach produce Hydrochloric Acid (HCl) naturally during digestion, and why does Hyperacidity require antacids?', 'Physiological balance: gastric parietal cells secrete HCl for pepsinogen activation; hyperchlorhydria is buffered via basic antacids.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7c1da0d-f76e-44f0-a074-bcf1959c409c', 'Gastric HCl creates an optimal acidic environment (pH ~1.5) for the protein enzyme pepsin; excess acid secretion causes painful gastritis and heartburn, requiring basic antacids (Mg(OH)₂) to neutralize excess H⁺ ions', true, 'd780b91c-26b7-4dbc-915b-1cd067f4882d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75e068cf-1e2b-4af2-a7e1-9393f1e7b3c6', 'HCl is produced to burn bones', false, 'd780b91c-26b7-4dbc-915b-1cd067f4882d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f54ceba-f84a-4d58-b248-f0d5a672641e', 'Antacids turn stomach acid into milk', false, 'd780b91c-26b7-4dbc-915b-1cd067f4882d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('989c32b7-d524-45d7-bc86-ae182710e08d', 'The stomach produces acid only when we sleep', false, 'd780b91c-26b7-4dbc-915b-1cd067f4882d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b1979db-5f3e-427e-b58e-551036970009', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'What is the chemical reaction when Baking Soda (Sodium Hydrogen Carbonate) reacts with Vinegar (Acetic Acid)?', 'Carbonate-acid effervescence: NaHCO₃ + CH₃COOH → CH₃COONa (sodium acetate) + H₂O + CO₂↑.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2711e2f1-913a-4422-869d-f767b083ea7b', 'NaHCO₃ + CH₃COOH -> CH₃COONa + H₂O + CO₂ (vigorous effervescence of Carbon Dioxide gas bubbles)', true, '6b1979db-5f3e-427e-b58e-551036970009');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('480415af-15fb-4234-9ca2-6560ef47e688', 'They freeze into ice instantly', false, '6b1979db-5f3e-427e-b58e-551036970009');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50c97490-cabc-41ca-8c14-e788aeb20699', 'They form pure oxygen gas', false, '6b1979db-5f3e-427e-b58e-551036970009');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f83987da-f9b3-4d35-ab48-21de1b93ff85', 'No reaction occurs', false, '6b1979db-5f3e-427e-b58e-551036970009');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66e155fd-4aa5-4543-801a-f16cdd58d93a', 'Class 7', 'Science', 'Chapter 4: Acids, Bases and Salts', 'Hard', 'What overarching chemical principle summarizes Chapter 4 of NCERT Class 7 Science?', 'Chapter 4 establishes the fundamental aqueous chemical taxonomy: acid-base dissociation, indicator mechanisms, and neutralization equilibria.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf6b5fc1-af4a-40e5-bb9d-310576c15a83', 'Acids, Bases, and Salts form the foundational triad of chemical reactivity, where acid-base neutralization governs physiological homeostasis, agricultural soil fertility, industrial environmental safety, and natural indicator chemistry', true, '66e155fd-4aa5-4543-801a-f16cdd58d93a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3463bbf-980f-4fd5-8c5b-891e93e90ea9', 'All chemicals are dangerous acids', false, '66e155fd-4aa5-4543-801a-f16cdd58d93a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e764ec5b-34a8-4f0e-8f53-90414be68f1d', 'Salts cannot dissolve in water', false, '66e155fd-4aa5-4543-801a-f16cdd58d93a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6af8afda-1900-41ef-b9dc-ead2dd27f3e7', 'Indicators change color only in darkness', false, '66e155fd-4aa5-4543-801a-f16cdd58d93a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b84fb6c1-f29e-48c0-a172-b2b38948b045', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'A mathematical statement of equality containing an ''equals'' sign (=) and at least one unknown variable is called an:', 'An equation is a condition on a variable stating that two mathematical expressions are strictly equal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c109abda-7a69-42b9-a90a-5fd33a9b1471', 'Equation', true, 'b84fb6c1-f29e-48c0-a172-b2b38948b045');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e326ecfb-2197-4c2e-8302-cdd6051ffa5d', 'Expression', false, 'b84fb6c1-f29e-48c0-a172-b2b38948b045');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd50cc1e-3bf9-4822-b011-8b877665ae61', 'Inequality', false, 'b84fb6c1-f29e-48c0-a172-b2b38948b045');
