INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1135a84-37b0-48e8-a4d1-4d524a860375', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Solve the simple linear equation: x + 4 = 15:', 'Transposing +4 to the RHS: x = 15 - 4 = 11.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6599456-f103-4c7c-af62-357979fa10bf', 'x = 11 (x = 15 - 4 = 11)', true, 'e1135a84-37b0-48e8-a4d1-4d524a860375');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d63ff8c8-e8bb-4fa4-b807-983c7ac9c0e1', 'x = 19', false, 'e1135a84-37b0-48e8-a4d1-4d524a860375');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcdb6cec-f974-471b-bc1e-173e38f7af9f', 'x = 60', false, 'e1135a84-37b0-48e8-a4d1-4d524a860375');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d676cfb5-ffc1-4493-8011-b444d0496391', 'x = 15/4', false, 'e1135a84-37b0-48e8-a4d1-4d524a860375');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecc72f17-7565-482c-a59d-54932f63e97f', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Solve for y: y - 7 = 13:', 'Transposing -7 to the RHS: y = 13 + 7 = 20.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfd71012-e015-4acd-9446-4cad7f87bbdf', 'y = 20 (y = 13 + 7 = 20)', true, 'ecc72f17-7565-482c-a59d-54932f63e97f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f72095dc-3d42-4f4e-91c2-a5817467fb36', 'y = 6', false, 'ecc72f17-7565-482c-a59d-54932f63e97f');
