INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b048788-75aa-4e65-bc60-b4e0a184ea4f', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Solve the equation: 5m = 35:', 'Dividing both sides by 5: m = 35 ÷ 5 = 7.', NOW()) ON CONFLICT DO NOTHING;
