INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('254521d1-5010-492f-a9b9-e1df91a411ae', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Solve for p: p / 4 = 9:', 'Multiplying both sides by 4: p = 9 × 4 = 36.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dcfb83a-0362-486e-9d6c-ea60a5be1432', 'p = 36 (p = 9 × 4 = 36)', true, '254521d1-5010-492f-a9b9-e1df91a411ae');
