INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e97fd9a-3468-48f2-a36c-5b180cec7c61', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'What is the value of the variable that satisfies and makes the equation true called?', 'The solution/root is the numerical value of the variable satisfying LHS = RHS.', NOW()) ON CONFLICT DO NOTHING;
