INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c0b3d94-f1cd-4e9d-8188-a7d3ee004161', 'Coefficient', false, '7e97fd9a-3468-48f2-a36c-5b180cec7c61');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1aadc75-c9c9-4a28-8fe5-0e9655290b5a', 'Degree', false, '7e97fd9a-3468-48f2-a36c-5b180cec7c61');
