INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13a54ce8-f11d-4907-93ec-ad3abe301ab0', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Write the mathematical equation for: ''The sum of numbers x and 4 is 9'':', '''Sum of x and 4 is 9'' directly translates algebraically to: x + 4 = 9.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b87de5db-c279-4d2a-ac1f-f9d3d92c385c', 'x + 4 = 9', true, '13a54ce8-f11d-4907-93ec-ad3abe301ab0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('709fcc6f-7791-4c47-81a1-b97db77c5b1c', 'x - 4 = 9', false, '13a54ce8-f11d-4907-93ec-ad3abe301ab0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d77be686-5720-4b3b-bdf8-9f30a46d9558', '4x = 9', false, '13a54ce8-f11d-4907-93ec-ad3abe301ab0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2183618-e465-47e3-8bae-aecc8b58ac98', 'x / 4 = 9', false, '13a54ce8-f11d-4907-93ec-ad3abe301ab0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('284b4ffd-9a35-40f6-b57c-3efdc855871d', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Write the mathematical equation for: ''Ten times ''a'' is 70'':', '''10 times a is 70'' translates to: 10a = 70.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a48c92e5-c339-43bc-adcf-6263d4792265', '10a = 70', true, '284b4ffd-9a35-40f6-b57c-3efdc855871d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff167cdc-f4d1-49db-ad3d-1ae8b53a761d', 'a + 10 = 70', false, '284b4ffd-9a35-40f6-b57c-3efdc855871d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1a4d6b2-0671-4501-8269-7bd094698f02', 'a / 10 = 70', false, '284b4ffd-9a35-40f6-b57c-3efdc855871d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27305430-195a-4515-85b5-b6f10b118872', '10 - a = 70', false, '284b4ffd-9a35-40f6-b57c-3efdc855871d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f55120bf-a94a-46fa-8d50-30c3fc1354a7', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'When a term with a POSITIVE sign is transposed from the LHS to the RHS of an equation, its sign changes to:', 'Transposing a term across the ''='' sign inverts its arithmetic operation (+ becomes -).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3cc18d0-caf9-4bff-9549-351ccf14f722', 'Negative sign (-)', true, 'f55120bf-a94a-46fa-8d50-30c3fc1354a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46868833-2fa5-4905-a16f-a9062517e1d9', 'Positive sign (+)', false, 'f55120bf-a94a-46fa-8d50-30c3fc1354a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8e88a29-a0cd-4b8f-b805-3e997f05b71a', 'Multiplication sign', false, 'f55120bf-a94a-46fa-8d50-30c3fc1354a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb2dac78-f7ca-478b-a0a7-6ffcd7790709', 'Division sign', false, 'f55120bf-a94a-46fa-8d50-30c3fc1354a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b8540a46-6d55-4297-a992-bf5aad8349b5', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Solve the equation: 2n + 5 = 19:', '2n = 19 - 5 = 14 → n = 14 / 2 = 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9ad52f0-7477-4323-95de-9da03daeff74', 'n = 7 (2n = 19 - 5 = 14 ⇒ n = 14 / 2 = 7)', true, 'b8540a46-6d55-4297-a992-bf5aad8349b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1208f43e-717c-4b37-96fe-7af80fde8b43', 'n = 12', false, 'b8540a46-6d55-4297-a992-bf5aad8349b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e37b31db-5b51-4f7c-bf95-02fc3e504ef6', 'n = 14', false, 'b8540a46-6d55-4297-a992-bf5aad8349b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7c030a0-45b1-49d0-991a-4c0d74ffe25c', 'n = 24', false, 'b8540a46-6d55-4297-a992-bf5aad8349b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d2a0b9ff-e572-4264-a99e-8d77b998fdea', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Check if x = 3 is a solution to the equation 4x - 3 = 9:', 'Substituting x = 3: 4(3) - 3 = 12 - 3 = 9 = RHS. The equation is satisfied.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63cb202a-9026-44d6-ac9f-b495b94b1b3d', 'Yes, x = 3 is a solution (LHS = 4(3) - 3 = 12 - 3 = 9 = RHS)', true, 'd2a0b9ff-e572-4264-a99e-8d77b998fdea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fea3299-336c-432f-93e4-e6f81f6449fe', 'No, because LHS = 15', false, 'd2a0b9ff-e572-4264-a99e-8d77b998fdea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6876bff4-27f8-48e3-8645-0c5491ebe451', 'No, because LHS = 5', false, 'd2a0b9ff-e572-4264-a99e-8d77b998fdea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e618e3dc-d693-45f4-826e-fde488442f2f', 'Cannot be determined', false, 'd2a0b9ff-e572-4264-a99e-8d77b998fdea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8bc281ed-108f-4160-a76f-ee2fe8f02b27', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Easy', 'Solve for z: 3z = 0:', '3z = 0 → z = 0 / 3 = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f658f12-8c4e-4efb-9e5b-fe156786e531', 'z = 0 (z = 0 / 3 = 0)', true, '8bc281ed-108f-4160-a76f-ee2fe8f02b27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf85196b-5f79-4a91-bede-a7f67c6da5db', 'z = 3', false, '8bc281ed-108f-4160-a76f-ee2fe8f02b27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('409b69d8-c852-4394-88d9-3eb189e73e04', 'z = 1/3', false, '8bc281ed-108f-4160-a76f-ee2fe8f02b27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5603b85a-e472-4193-a90e-247bfe598dde', 'Undefined', false, '8bc281ed-108f-4160-a76f-ee2fe8f02b27');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2a1b4c8f-ce29-458d-adf4-31c973984904', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Solve the linear equation: 3(n - 5) = 21:', '3(n - 5) = 21 → n - 5 = 7 → n = 12.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adef5fc4-c23a-49ec-8ecc-4f0be2c17bc8', 'n = 12 (n - 5 = 21 / 3 = 7 ⇒ n = 7 + 5 = 12)', true, '2a1b4c8f-ce29-458d-adf4-31c973984904');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2646f6b1-bf92-4937-9fbb-8559cf26d26c', 'n = 8', false, '2a1b4c8f-ce29-458d-adf4-31c973984904');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e7adb69-ff9a-43d9-87ab-0ce674f7e39a', 'n = 2', false, '2a1b4c8f-ce29-458d-adf4-31c973984904');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fd584b8-0ad4-4621-8b5b-8b3bad7e5bb3', 'n = 16', false, '2a1b4c8f-ce29-458d-adf4-31c973984904');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6a93e304-7e16-4255-b212-4dd83699b2fe', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Solve for p: -4(2 + p) = 8:', '2 + p = 8 ÷ (-4) = -2 → p = -2 - 2 = -4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f9c75f2-11c3-456f-9d62-c4a93a2d501a', 'p = -4 (2 + p = 8 / -4 = -2 ⇒ p = -2 - 2 = -4)', true, '6a93e304-7e16-4255-b212-4dd83699b2fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a566d033-436a-4917-bb74-04565910e102', 'p = 4', false, '6a93e304-7e16-4255-b212-4dd83699b2fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ad0eeaf-cb7e-41ee-bfea-e7982b76574f', 'p = 0', false, '6a93e304-7e16-4255-b212-4dd83699b2fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f91da4d3-4122-4f6a-a50b-9d0f0c722099', 'p = -2', false, '6a93e304-7e16-4255-b212-4dd83699b2fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('51d379b0-1380-4c1b-82c6-b90421b31dea', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Solve the equation: 4 + 5(p - 1) = 34:', '5(p - 1) = 30 → p - 1 = 6 → p = 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46fa11cf-9b05-4d5d-a9f4-3884355f0b4b', 'p = 7 (5(p - 1) = 34 - 4 = 30 ⇒ p - 1 = 6 ⇒ p = 7)', true, '51d379b0-1380-4c1b-82c6-b90421b31dea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d816df1d-daed-4143-9f4b-277862f9255d', 'p = 6', false, '51d379b0-1380-4c1b-82c6-b90421b31dea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1387b91c-c0b7-4119-b9ea-dedd91189b64', 'p = 8', false, '51d379b0-1380-4c1b-82c6-b90421b31dea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('301a378b-8481-45d4-81cd-ee9354577069', 'p = 5', false, '51d379b0-1380-4c1b-82c6-b90421b31dea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6721ab26-2a32-4ab9-ac06-2cb1646f7ea2', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Solve the equation: 16 = 4 + 3(t + 2):', '12 = 3(t + 2) → t + 2 = 4 → t = 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adbb8eff-d9a5-4e69-8afe-2780b6ca0bbf', 't = 2 (16 - 4 = 3(t + 2) ⇒ 12 = 3(t + 2) ⇒ t + 2 = 4 ⇒ t = 2)', true, '6721ab26-2a32-4ab9-ac06-2cb1646f7ea2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d035007c-d387-4ea6-881b-6658d01a032e', 't = 4', false, '6721ab26-2a32-4ab9-ac06-2cb1646f7ea2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18cb5f21-dc83-43a9-bd9a-fc7619326843', 't = 6', false, '6721ab26-2a32-4ab9-ac06-2cb1646f7ea2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c866d4ec-195d-4af0-8f07-6b41b4ef47c0', 't = 0', false, '6721ab26-2a32-4ab9-ac06-2cb1646f7ea2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a594a6f-084a-4d1f-a85f-338654e7aed9', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'The teacher tells the class that the highest marks obtained by a student in her class is twice the lowest marks plus 7. If the highest marks is 87, find the LOWEST marks:', 'Equation: 2l + 7 = 87 → 2l = 80 → l = 40 marks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20284264-8bda-4ea1-8688-eb85b68d6756', '40 (Let lowest = l ; 2l + 7 = 87 ⇒ 2l = 80 ⇒ l = 40)', true, '8a594a6f-084a-4d1f-a85f-338654e7aed9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfeb74d3-bbd0-43d6-bddd-f03e45a680a0', '45', false, '8a594a6f-084a-4d1f-a85f-338654e7aed9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb01cc78-87a3-441c-ad73-3e24f7773948', '35', false, '8a594a6f-084a-4d1f-a85f-338654e7aed9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab6aab83-db22-4893-bab0-36d45da74c32', '50', false, '8a594a6f-084a-4d1f-a85f-338654e7aed9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c690a0a5-defc-499f-8ed2-25a121057ae2', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'In an isosceles triangle, the base angles are equal. The vertex angle is 40°. What are the base angles of the triangle?', 'Sum of angles in a triangle = 180°. 2b + 40° = 180° → 2b = 140° → b = 70°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16fc66c5-b6be-4e7e-8315-41f7b11cc36f', '70° each (Let base angle = b ; b + b + 40° = 180° ⇒ 2b = 140° ⇒ b = 70°)', true, 'c690a0a5-defc-499f-8ed2-25a121057ae2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e22ae09-d472-4baf-88d3-0cf076634b55', '60° each', false, 'c690a0a5-defc-499f-8ed2-25a121057ae2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fefc537e-e54b-4b2f-abc4-ece807c64091', '80° each', false, 'c690a0a5-defc-499f-8ed2-25a121057ae2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d5abb1f-4866-4f10-ace1-f7ef653df7d2', '50° each', false, 'c690a0a5-defc-499f-8ed2-25a121057ae2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41419a7a-cd76-4cf9-b706-ecdd851c4f02', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Laxmi''s father is 49 years old. He is 4 years older than three times Laxmi''s age. What is Laxmi''s age?', '3y + 4 = 49 → 3y = 45 → y = 15 years.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c01f5a5d-a2af-4f8d-bdc7-52596eb3b1cf', '15 years (Let Laxmi''s age = y ; 3y + 4 = 49 ⇒ 3y = 45 ⇒ y = 15 years)', true, '41419a7a-cd76-4cf9-b706-ecdd851c4f02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29a83602-d7c2-4a84-898e-8d488f2ec937', '12 years', false, '41419a7a-cd76-4cf9-b706-ecdd851c4f02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef0f67ec-48c4-4957-8d17-1fad73e6086b', '16 years', false, '41419a7a-cd76-4cf9-b706-ecdd851c4f02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('098df3ae-5690-4dd3-94eb-7b1bc1399fe6', '18 years', false, '41419a7a-cd76-4cf9-b706-ecdd851c4f02');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a5f9d92-f2c0-4d07-9213-b4d53f401222', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Sachin scored twice as many runs as Rahul. Together, their runs fell two short of a double century (200 - 2 = 198). How many runs did Sachin score?', '3r = 198 → Rahul = 66 runs; Sachin = 2 × 66 = 132 runs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('778c7fa6-f9bf-402a-83dd-8eb29ba38bab', '132 runs (Let Rahul = r, Sachin = 2r ; r + 2r = 198 ⇒ 3r = 198 ⇒ r = 66 ⇒ Sachin = 2 × 66 = 132 runs)', true, '0a5f9d92-f2c0-4d07-9213-b4d53f401222');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a54501a3-f59f-4df4-a20d-3b2bfb7be3aa', '66 runs', false, '0a5f9d92-f2c0-4d07-9213-b4d53f401222');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bcaaba2-f42f-4eb6-b670-28a4193ba4d3', '100 runs', false, '0a5f9d92-f2c0-4d07-9213-b4d53f401222');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55559540-d255-4efd-94f1-61704c68c45e', '120 runs', false, '0a5f9d92-f2c0-4d07-9213-b4d53f401222');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a27fc020-1864-425a-8cd1-ed8b68ba1c26', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'People of Sundargram planted trees in the village garden. The number of non-fruit trees was two more than three times the number of fruit trees. What was the number of fruit trees planted if the number of non-fruit trees was 77?', '3f + 2 = 77 → 3f = 75 → f = 25 fruit trees.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('347bfe28-d61b-49ce-b2a4-85242f5f56d6', '25 fruit trees (3f + 2 = 77 ⇒ 3f = 75 ⇒ f = 25)', true, 'a27fc020-1864-425a-8cd1-ed8b68ba1c26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a53321b-b843-4200-9aed-5c6e15cec215', '20 fruit trees', false, 'a27fc020-1864-425a-8cd1-ed8b68ba1c26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0eb0f17-f47f-4ada-9ede-b2c75c2ee8b7', '30 fruit trees', false, 'a27fc020-1864-425a-8cd1-ed8b68ba1c26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8d0448a-8ab3-4e84-9ada-54a48980342c', '28 fruit trees', false, 'a27fc020-1864-425a-8cd1-ed8b68ba1c26');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6a33890-bb42-450c-acdb-8a1f17ef5836', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Solve the equation: 0 = 16 + 4(m - 6):', '4(m - 6) = -16 → m - 6 = -4 → m = 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af3d3513-2837-49bc-a611-098686a484ac', 'm = 2 (-16 = 4(m - 6) ⇒ -4 = m - 6 ⇒ m = -4 + 6 = 2)', true, 'c6a33890-bb42-450c-acdb-8a1f17ef5836');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d719219-82a1-4b71-9bb4-b8b92eabaadf', 'm = -2', false, 'c6a33890-bb42-450c-acdb-8a1f17ef5836');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e890de26-ffcb-4acb-b6b2-7e324b077dbb', 'm = 6', false, 'c6a33890-bb42-450c-acdb-8a1f17ef5836');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('904b6f5d-5dd9-49a9-a3e6-ad669eaaaaa2', 'm = 10', false, 'c6a33890-bb42-450c-acdb-8a1f17ef5836');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('abd6987d-9a46-4893-8b09-7ff6a51ce0b1', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Construct an equation starting with the solution x = -2:', 'Starting from x = -2: Multiply by 3 → 3x = -6 → Add 6 → 3x + 6 = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3f4128a-40a8-4f10-8eda-4a4b0cc5b08a', '3x + 6 = 0 (since 3(-2) + 6 = -6 + 6 = 0)', true, 'abd6987d-9a46-4893-8b09-7ff6a51ce0b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48118962-0e55-415c-9bde-3fef69d9ca01', '3x - 6 = 0', false, 'abd6987d-9a46-4893-8b09-7ff6a51ce0b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2faa9cd-f3a7-494d-8a15-d39d500ab49b', '2x + 5 = 10', false, 'abd6987d-9a46-4893-8b09-7ff6a51ce0b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8f0677d-122b-4c1e-99d6-ce8470cda219', 'x + 4 = 1', false, 'abd6987d-9a46-4893-8b09-7ff6a51ce0b1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb82491e-d90a-4316-b506-f52eb8607acc', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'If 1/5 of a number minus 4 gives 3, what is the number?', 'n/5 - 4 = 3 → n/5 = 7 → n = 35.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('176be011-6fd7-48da-a2cb-07fdd759d6ce', '35 (n/5 - 4 = 3 ⇒ n/5 = 7 ⇒ n = 35)', true, 'cb82491e-d90a-4316-b506-f52eb8607acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92667762-4184-47dd-b9f0-598e3251408e', '25', false, 'cb82491e-d90a-4316-b506-f52eb8607acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51930b08-f2ba-451c-92d0-f12190a03f4e', '40', false, 'cb82491e-d90a-4316-b506-f52eb8607acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ab25685-f063-4526-a764-88709f4710f4', '30', false, 'cb82491e-d90a-4316-b506-f52eb8607acc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2bd1fdc4-23c8-43f1-b040-233acc5d4d42', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Irfan says that he has 7 marbles more than 5 times the marbles Parmit has. Irfan has 37 marbles. How many marbles does Parmit have?', '5m + 7 = 37 → 5m = 30 → m = 6 marbles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a19f6b8-11d5-44ef-9a0a-c151e97c8062', '6 marbles (5m + 7 = 37 ⇒ 5m = 30 ⇒ m = 6)', true, '2bd1fdc4-23c8-43f1-b040-233acc5d4d42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('894a65e2-e299-4e6b-a2cd-28f3863ce361', '8 marbles', false, '2bd1fdc4-23c8-43f1-b040-233acc5d4d42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e99419e4-b74b-4a0d-aae1-f5592b2bedae', '5 marbles', false, '2bd1fdc4-23c8-43f1-b040-233acc5d4d42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('870b96fc-d00e-4516-b57d-97bc4918415b', '7 marbles', false, '2bd1fdc4-23c8-43f1-b040-233acc5d4d42');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5dc3a5d-c203-4fc8-be5f-e47586bfa3eb', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Solve the equation: 7m + 19/2 = 13:', '7m = 13 - 9.5 = 3.5 = 7/2 → m = (7/2)/7 = 1/2 = 0.5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b535295-f592-4684-814a-071b019004ac', 'm = 1/2 (7m = 13 - 19/2 = 26/2 - 19/2 = 7/2 ⇒ m = (7/2) / 7 = 1/2)', true, 'a5dc3a5d-c203-4fc8-be5f-e47586bfa3eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7eeefa06-788a-4114-a8bc-f918a76b8cdf', 'm = 2', false, 'a5dc3a5d-c203-4fc8-be5f-e47586bfa3eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6de16586-14c4-4c5f-8804-43d7719fda5b', 'm = 7', false, 'a5dc3a5d-c203-4fc8-be5f-e47586bfa3eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d38816a-d605-4aa8-aefa-40d224e9d24a', 'm = 1', false, 'a5dc3a5d-c203-4fc8-be5f-e47586bfa3eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('498c8663-b808-48a2-8b63-199f2c2c9050', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'When I subtracted 11 from twice a number, the result was 15. What is the number?', '2x - 11 = 15 → 2x = 26 → x = 13.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eeaa7275-ad60-484a-9e51-d6327bd9b547', '13 (2x - 11 = 15 ⇒ 2x = 26 ⇒ x = 13)', true, '498c8663-b808-48a2-8b63-199f2c2c9050');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71499cc3-023b-404a-876a-8bbdc4a65f7e', '14', false, '498c8663-b808-48a2-8b63-199f2c2c9050');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18aa60ba-f201-4169-89ae-c98237ba3c99', '12', false, '498c8663-b808-48a2-8b63-199f2c2c9050');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b96d96f-01b3-4d23-9cd1-23ee132229a2', '15', false, '498c8663-b808-48a2-8b63-199f2c2c9050');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9be40c4-09db-462e-bb57-0f8ff6d87cce', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Medium', 'Solve: (5/2)x = 25/4:', 'x = (25/4) × (2/5) = (25×2)/(4×5) = 50/20 = 5/2 = 2.5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('621b8506-68ae-416f-948a-a7a907f496e2', 'x = 5/2 = 2.5 (x = (25/4) × (2/5) = 5/2)', true, 'f9be40c4-09db-462e-bb57-0f8ff6d87cce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8385e921-3e71-43a1-8895-2e4aaf6a5177', 'x = 5', false, 'f9be40c4-09db-462e-bb57-0f8ff6d87cce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c37ed022-6b46-435f-9086-24362352711b', 'x = 2', false, 'f9be40c4-09db-462e-bb57-0f8ff6d87cce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e454a783-509d-419f-9805-0b3cba6d2874', 'x = 1/2', false, 'f9be40c4-09db-462e-bb57-0f8ff6d87cce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('edf570a1-70ec-42c8-a610-a6d1df9ad864', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43ba0a3f-11c8-40c2-8318-4497c11f55bf', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'edf570a1-70ec-42c8-a610-a6d1df9ad864');
