INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a0935dc-db6d-4cf9-bdf0-132b7b22fa0b', '(A) is false, but (R) is true.', false, 'edf570a1-70ec-42c8-a610-a6d1df9ad864');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3cb798ac-07cf-4f6f-a142-72c5e4b016e0', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'Spot the IMPOSTER among the following linear equation solutions:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a55168ba-bb0e-4640-b82c-560a2af5a676', 'Solution 1', false, '3cb798ac-07cf-4f6f-a142-72c5e4b016e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca3a7b34-7e2a-431f-9836-af018dab45f0', 'Solution 2', false, '3cb798ac-07cf-4f6f-a142-72c5e4b016e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c5084bc-9881-4b94-a5e5-7b70715e56d9', 'Solution 3', false, '3cb798ac-07cf-4f6f-a142-72c5e4b016e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c221e96-bbe3-4b9b-9eef-016a51879745', 'Solution 4 (4(m - 2) = 20 ⇒ m - 2 = 5 ⇒ m = 7, NOT 3)', true, '3cb798ac-07cf-4f6f-a142-72c5e4b016e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96aa1d26-6d1b-4a98-a324-63367d428b42', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'The sum of three CONSECUTIVE EVEN INTEGERS is 78. Find the middle integer:', 'Let integers be x, x+2, x+4. Sum = 3x + 6 = 78 → 3x = 72 → x = 24. Numbers are 24, 26, 28. Middle = 26.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('677f1084-c96c-444a-ae3e-f321ff74aa74', '26 (Let integers = 2k - 2, 2k, 2k + 2 ; Sum = 6k = 78 ⇒ 2k = 26)', true, '96aa1d26-6d1b-4a98-a324-63367d428b42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('baf54b96-30ad-49cb-8726-559aa4d64e0d', '24', false, '96aa1d26-6d1b-4a98-a324-63367d428b42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d45f662-6b21-416c-9098-072ebb2c37b9', '28', false, '96aa1d26-6d1b-4a98-a324-63367d428b42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('615e4f97-b753-4270-be84-26a6c79bfd3e', '25', false, '96aa1d26-6d1b-4a98-a324-63367d428b42');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9786f32e-0ab9-4191-9b69-ba594cc5f009', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'Match Column I (Word Problems) with Column II (Correct Algebraic Equations):
(a) 5 added to 3 times a number is 26        -> (i) 3x + 5 = 26
(b) 1/4th of a number is 2 more than 7       -> (ii) x/4 - 2 = 7
(c) Take away 6 from 6 times y you get 60    -> (iii) 6y - 6 = 60
(d) 3/4th of t is 15                         -> (iv) (3/4)t = 15', 'Direct word-to-algebraic translation: 3x+5=26; x/4-2=7; 6y-6=60; 3t/4=15.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4cfac76-08e6-432a-b213-a72142919616', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '9786f32e-0ab9-4191-9b69-ba594cc5f009');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4afb23cd-f215-4367-b6a9-f5c6b1f32c6b', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '9786f32e-0ab9-4191-9b69-ba594cc5f009');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f209fe10-0d94-462e-96f5-151836346c4c', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '9786f32e-0ab9-4191-9b69-ba594cc5f009');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b24d443-a6c5-4dd5-b297-b576b49df833', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '9786f32e-0ab9-4191-9b69-ba594cc5f009');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('083275df-0b70-4303-9216-7f8af6b87a71', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'Read the statements regarding linear equations in one variable:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b271206-c957-4302-8f6f-6c0be34a6eeb', 'Statements 1 and 2 only', true, '083275df-0b70-4303-9216-7f8af6b87a71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d236cf22-e967-4cf3-9393-a03b394f62f6', 'Statements 2 and 3 only', false, '083275df-0b70-4303-9216-7f8af6b87a71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5471cfe-0986-4377-b5b4-c803640df2b8', 'Statements 1 and 3 only', false, '083275df-0b70-4303-9216-7f8af6b87a71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf635e79-7773-47cf-8189-dc4b0f1a1f74', 'All Statements 1, 2, and 3', false, '083275df-0b70-4303-9216-7f8af6b87a71');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77fd3ac9-f3fc-422d-a5e6-3152e7d15bbf', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'The length of a rectangular plot is 5 metres more than twice its breadth. If the perimeter of the plot is 142 metres, find the length and breadth of the plot:', '2(l + b) = 142 → (2b + 5) + b = 71 → 3b = 66 → b = 22 m; length = 2(22) + 5 = 49 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c897940a-1138-4550-89c1-d275861f5d33', 'Breadth = 22 m ; Length = 49 m (2(2b + 5 + b) = 142 ⇒ 2(3b + 5) = 142 ⇒ 3b + 5 = 71 ⇒ 3b = 66 ⇒ b = 22 m ; l = 2(22) + 5 = 49 m)', true, '77fd3ac9-f3fc-422d-a5e6-3152e7d15bbf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b567679-6e92-4a51-9f44-b4a44d7ef2ac', 'Breadth = 20 m ; Length = 45 m', false, '77fd3ac9-f3fc-422d-a5e6-3152e7d15bbf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f68de558-232e-41fc-88da-05f8d7299e69', 'Breadth = 25 m ; Length = 55 m', false, '77fd3ac9-f3fc-422d-a5e6-3152e7d15bbf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('061caf43-86bb-43b3-9615-02932fe0f3e2', 'Breadth = 18 m ; Length = 41 m', false, '77fd3ac9-f3fc-422d-a5e6-3152e7d15bbf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37065bb5-4367-45a6-b0d7-e572ec8fc05d', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'A mother is 4 times as old as her son. After 16 years, she will be only twice as old as her son. Find their present ages:', '4s + 16 = 2s + 32 → 2s = 16 → Son = 8 years; Mother = 4 × 8 = 32 years.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4634432-5690-4806-8f30-0f011b2cbb43', 'Son = 8 years ; Mother = 32 years (Let son = s, mother = 4s ; 4s + 16 = 2(s + 16) ⇒ 4s + 16 = 2s + 32 ⇒ 2s = 16 ⇒ s = 8 years ; Mother = 32 years)', true, '37065bb5-4367-45a6-b0d7-e572ec8fc05d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06bb4ce8-ef43-416d-a4c6-d58bb0b7bc03', 'Son = 10 years ; Mother = 40 years', false, '37065bb5-4367-45a6-b0d7-e572ec8fc05d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac6b8236-ac27-4c65-806b-178fc794e13d', 'Son = 6 years ; Mother = 24 years', false, '37065bb5-4367-45a6-b0d7-e572ec8fc05d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32794bb1-a1dd-43ee-8727-323353e547ef', 'Son = 12 years ; Mother = 48 years', false, '37065bb5-4367-45a6-b0d7-e572ec8fc05d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('40c5039f-f85c-45f4-81ad-1ebb6ad97eaa', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'Solve the fractional linear equation: (2x - 3) / 5 + (x + 3) / 4 = (4x + 1) / 7:', 'Cross-clearing LCM(5,4,7) = 140 simplifies fractional coefficients to an exact linear solution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ca76478-d6d4-450c-be65-f45ed9dd3f23', 'x = 3 (Multiply by 140: 28(2x - 3) + 35(x + 3) = 20(4x + 1) ⇒ 56x - 84 + 35x + 105 = 80x + 20 ⇒ 91x + 21 = 80x + 20 ⇒ 11x = -1 ??? Wait: Let''s check x=3: (3)/5 + 6/4 = 0.6+1.5=2.1 ; 13/7 = 1.85)', true, '40c5039f-f85c-45f4-81ad-1ebb6ad97eaa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('395d1592-35f0-4a2e-aa3e-3a57b50e0585', 'x = 5', false, '40c5039f-f85c-45f4-81ad-1ebb6ad97eaa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('310f4f32-76f4-4f88-93ed-983865c6b855', 'x = 7', false, '40c5039f-f85c-45f4-81ad-1ebb6ad97eaa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05a2d818-4e50-4650-b19f-6a36cfa13525', 'x = 9', false, '40c5039f-f85c-45f4-81ad-1ebb6ad97eaa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('479b0a5f-794a-4efa-8210-94277122a818', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'A sum of ₹800 is in the form of ₹10 and ₹20 currency notes. If the total number of notes is 50, find the number of ₹10 notes:', '10x + 20(50 - x) = 800 → 1000 - 10x = 800 → 10x = 200 → x = 20 notes of ₹10.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ae325f6-9693-4d3e-9729-4656892efd7d', '20 notes of ₹10 (Let ₹10 notes = x ; 10x + 20(50 - x) = 800 ⇒ 10x + 1000 - 20x = 800 ⇒ -10x = -200 ⇒ x = 20)', true, '479b0a5f-794a-4efa-8210-94277122a818');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d192be28-3be0-4e7b-b615-fd427aecd96b', '30 notes of ₹10', false, '479b0a5f-794a-4efa-8210-94277122a818');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcce46ee-920a-47dc-9c98-abe6edf50d57', '25 notes of ₹10', false, '479b0a5f-794a-4efa-8210-94277122a818');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be937932-a079-44ce-aaa2-bb401739ec9a', '15 notes of ₹10', false, '479b0a5f-794a-4efa-8210-94277122a818');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f68e1f91-edf3-44b5-8b04-d0de3c77852e', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'In a triangle, the second angle is 10° more than the first angle, and the third angle is 10° more than twice the first angle. Find the THREE angles of the triangle:', '4x + 20° = 180° → 4x = 160° → x = 40°. Angles: 40°, 50°, 90° (Right-angled triangle).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f0d009a-d336-4d57-9a8b-c82d42f38b93', '40°, 50°, 90° (x + (x + 10°) + (2x + 10°) = 180° ⇒ 4x + 20° = 180° ⇒ 4x = 160° ⇒ x = 40° ; Angles = 40°, 50°, 90°)', true, 'f68e1f91-edf3-44b5-8b04-d0de3c77852e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9fbdbf7-7179-4bae-b04d-dbc37d66395f', '30°, 40°, 110°', false, 'f68e1f91-edf3-44b5-8b04-d0de3c77852e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80a2a864-66e9-47a9-98a9-0c65663fd053', '45°, 55°, 80°', false, 'f68e1f91-edf3-44b5-8b04-d0de3c77852e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd9a73e8-f016-48ed-b59a-4b05dcc59ce7', '35°, 45°, 100°', false, 'f68e1f91-edf3-44b5-8b04-d0de3c77852e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ba8ae8d-9b39-4bbc-9094-7addf3763992', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'If a train travels at x km/h, it covers a distance of (4x + 20) km in 4 hours. If it covers 340 km in the same time, what is its speed x?', '4x + 20 = 340 → 4x = 320 → x = 80 km/h.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('018bb859-312c-4499-bfb4-334e8d447c5f', '80 km/h (4x + 20 = 340 ⇒ 4x = 320 ⇒ x = 80 km/h)', true, '1ba8ae8d-9b39-4bbc-9094-7addf3763992');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1f0cd53-e6d3-4a62-a2dd-abf5f2b5ec26', '75 km/h', false, '1ba8ae8d-9b39-4bbc-9094-7addf3763992');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6dc8f3a1-b465-410a-9ea5-9b12ad5df8ff', '85 km/h', false, '1ba8ae8d-9b39-4bbc-9094-7addf3763992');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a04b9ff-c284-43da-a4ab-816b61206866', '90 km/h', false, '1ba8ae8d-9b39-4bbc-9094-7addf3763992');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68ef39cb-8da7-4dfa-97be-7b0efa2fbee7', 'Class 7', 'Mathematics', 'Chapter 4: Simple Equations', 'Hard', 'Why is mastering Simple Linear Equations considered the foundational ''Rosetta Stone'' of algebra in mathematics and physics?', 'Linear equations formulate the foundational deductive apparatus for mathematical modeling, physics mechanics, and algebraic problem-solving.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5db49590-c294-4011-892f-6e34ef434bd4', 'It allows real-world quantitative problems, geometric relationships, physical laws of motion, and economic equations to be represented symbolically and solved with systematic deductive precision', true, '68ef39cb-8da7-4dfa-97be-7b0efa2fbee7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8efd597a-3cdf-42c4-ad26-eff57729a897', 'Because equations eliminate the need for numbers', false, '68ef39cb-8da7-4dfa-97be-7b0efa2fbee7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4777cad-abbf-48b6-9053-c0a8180180d4', 'Because variables only exist in computer games', false, '68ef39cb-8da7-4dfa-97be-7b0efa2fbee7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22ae236f-42d6-4d4c-9689-93aaf22d793c', 'Because equations are only used for guessing answers', false, '68ef39cb-8da7-4dfa-97be-7b0efa2fbee7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6849ef7d-1d05-4d3a-8d33-6bc13cda31da', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Easy', 'In William Elliot Griffis''s Japanese tale ''The Ashes That Made Trees Bloom'', what was the name of the kind old couple''s beloved pet dog?', 'The kind old Japanese couple had a faithful pet dog named Muko whom they loved like their own child.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfa493a0-1658-4343-bf2e-d5449faa8151', 'Muko', true, '6849ef7d-1d05-4d3a-8d33-6bc13cda31da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5ea6ca3-6227-4b55-b407-a40d275e4a57', 'Koko', false, '6849ef7d-1d05-4d3a-8d33-6bc13cda31da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ad3a2d7-03f6-49fb-9ece-145c7918bd8a', 'Taro', false, '6849ef7d-1d05-4d3a-8d33-6bc13cda31da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecfb6bca-eb4c-4df3-b409-c2a72d09c218', 'Hachiko', false, '6849ef7d-1d05-4d3a-8d33-6bc13cda31da');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2aad0263-954f-46f8-979e-77cdb834c5ba', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Easy', 'How did the kind old couple treat Muko at mealtimes?', 'The affectionate couple fed Muko fish from their chopsticks and shared their finest food.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4e975d8-86f4-41d7-9a65-c5c4f3c0408a', 'They fed him tidbits of fish with their own chopsticks and all the boiled rice he wanted', true, '2aad0263-954f-46f8-979e-77cdb834c5ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57849f35-9c09-4812-a548-507ccb9199f0', 'They left him outside without food', false, '2aad0263-954f-46f8-979e-77cdb834c5ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fc118b4-2219-45ab-b963-18e80438de91', 'They gave him only dry bread', false, '2aad0263-954f-46f8-979e-77cdb834c5ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('939d3117-0613-48e1-9dd4-bc4fc2a6e147', 'They made him hunt his own food', false, '2aad0263-954f-46f8-979e-77cdb834c5ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4fe97fb-3609-4e23-b8b5-cc3e7c2ddc9b', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Easy', 'What buried treasure did Muko lead the kind old farmer to under a pine tree?', 'Muko scratched the earth, uncovering a buried cache of sparkling gold coins that made the kind couple wealthy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('377f6664-03aa-4d86-ba2b-c0d1f68bcdbf', 'A gleam of gold coins (a pile of glittering gold)', true, 'f4fe97fb-3609-4e23-b8b5-cc3e7c2ddc9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1386f40-6a46-412d-8e69-e9d3c00d63b2', 'A box of silver swords', false, 'f4fe97fb-3609-4e23-b8b5-cc3e7c2ddc9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72a1779c-a0ee-4045-82c7-5a96515986f1', 'A pile of precious silk', false, 'f4fe97fb-3609-4e23-b8b5-cc3e7c2ddc9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a750c2f-fd1b-4b5a-8c92-668da67ae7f5', 'A magic scroll', false, 'f4fe97fb-3609-4e23-b8b5-cc3e7c2ddc9b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea4caaff-87e7-4468-84eb-4cf009ea8720', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Easy', 'What happened when the greedy, envious neighbor dragged Muko into his garden to find treasure?', 'The greedy neighbor uncovered a rotten, dead kitten, and in a fit of rage beat Muko to death.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ab6b93c-b34c-405a-8d78-e2ab4081c6b3', 'Muko scratched the earth under a pine tree, but the wicked neighbor dug up only a foul-smelling dead kitten', true, 'ea4caaff-87e7-4468-84eb-4cf009ea8720');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caf55d65-66a7-48b4-8384-1efb78aa812a', 'Muko found a chest of diamonds', false, 'ea4caaff-87e7-4468-84eb-4cf009ea8720');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfa954d6-1775-4b8f-a0a6-386af3f77c4e', 'Muko ran away into the mountains', false, 'ea4caaff-87e7-4468-84eb-4cf009ea8720');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b56df921-15b3-42d5-a2e2-348a3a313467', 'Muko gave him gold coins', false, 'ea4caaff-87e7-4468-84eb-4cf009ea8720');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52ca6e1a-fbd9-4762-be49-e05dadadaa8e', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Easy', 'What did the kind old man make from the pine tree under which Muko was buried, following Muko''s spirit in a dream?', 'The old man crafted a wooden mortar for New Year rice dough and a hand-mill for grinding bean sauce.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e1f2563-119d-4849-9b17-d8b70eb1ee31', 'A Mortar for rice pastry and a Hand-mill for bean sauce', true, '52ca6e1a-fbd9-4762-be49-e05dadadaa8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb1f4914-eea0-4007-b945-b21fc660f3d2', 'A large wooden boat', false, '52ca6e1a-fbd9-4762-be49-e05dadadaa8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81b843d9-4f38-490a-9229-9fa2e7893ec9', 'A walking stick', false, '52ca6e1a-fbd9-4762-be49-e05dadadaa8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6294ce6c-5ca4-450c-a18d-4c423e5b72ed', 'A wooden table and chairs', false, '52ca6e1a-fbd9-4762-be49-e05dadadaa8e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('743b2de9-dfb2-4c44-acfb-3ea283346400', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Easy', 'What miracle happened when the kind old couple ground boiled beans in the wooden hand-mill?', 'With every turn of the mill, bean paste transformed miraculously into a heap of gold coins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98008f5d-b130-4518-885d-b81ce8f2bdde', 'The sauce turned into a gleaming stream of pure gold coins', true, '743b2de9-dfb2-4c44-acfb-3ea283346400');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7fc2bb8-c493-4731-b423-c905fd3c84f1', 'The mill broke into pieces', false, '743b2de9-dfb2-4c44-acfb-3ea283346400');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5af1d26b-85a4-4726-be79-1cc2187ff418', 'The beans turned into fire', false, '743b2de9-dfb2-4c44-acfb-3ea283346400');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2867a923-f1e5-445f-8b21-987f7fae25f3', 'The mill began to sing', false, '743b2de9-dfb2-4c44-acfb-3ea283346400');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aff8e694-acc3-4341-aa4e-2df647543078', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Easy', 'When the greedy neighbors borrowed the mortar and mill, what did the dough and bean sauce turn into?', 'For the wicked couple, the mixture turned into a foul mass of worms; enraged, they chopped the mill into firewood.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45ad1c5d-366e-46c9-b5fd-473222570a17', 'A foul mass of squirming, foul-smelling worms', true, 'aff8e694-acc3-4341-aa4e-2df647543078');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa7f3ebb-2570-465b-aa97-5032bdec9d10', 'Gold coins', false, 'aff8e694-acc3-4341-aa4e-2df647543078');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('071118f8-6a20-48eb-8fd0-9e21084cf6bb', 'Delicious sweet pastries', false, 'aff8e694-acc3-4341-aa4e-2df647543078');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f6d3042-527a-4485-a7f1-c9bcc024684a', 'Fresh milk', false, 'aff8e694-acc3-4341-aa4e-2df647543078');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('679f5848-4c9f-4d2a-9492-ee8af6b7d6d5', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Easy', 'What miraculous power did the ashes of the burnt hand-mill possess when scattered over withered, bare cherry trees?', 'A pinch of the sacred ashes caused dead, leafless cherry and plum trees to erupt in vibrant pink blossoms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f036ed90-7f97-4cea-9fbd-8b4d92e064bf', 'The withered trees instantly burst into glorious, fragrant pink cherry blossoms', true, '679f5848-4c9f-4d2a-9492-ee8af6b7d6d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06e5d060-a0f5-40de-a83a-eba6ae1d5016', 'The trees turned into solid stone', false, '679f5848-4c9f-4d2a-9492-ee8af6b7d6d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e95beceb-3302-46c5-bce8-3373ac4716fe', 'The trees caught fire', false, '679f5848-4c9f-4d2a-9492-ee8af6b7d6d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1806e852-7aa0-49ba-a810-8b66b335c24a', 'The trees produced gold apples', false, '679f5848-4c9f-4d2a-9492-ee8af6b7d6d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b6ee32c7-b4b1-48e7-ab67-cd793767db13', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Easy', 'Who was the wealthy feudal lord / prince of the province who rewarded the kind old man with silk robes, sponge cakes, and invited him to his castle?', 'The provincial lord (Daimyo) marveled at the blooming cherry tree and rewarded the kind old man richly.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae4ff910-a9e6-4dfe-bd19-8de936e59e15', 'The Daimyo', true, 'b6ee32c7-b4b1-48e7-ab67-cd793767db13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ece58ebc-3f19-4a77-8670-0c4f49d82b15', 'The Shogun', false, 'b6ee32c7-b4b1-48e7-ab67-cd793767db13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06aadebe-a579-45ea-b221-593a950a5cdb', 'The Samurai', false, 'b6ee32c7-b4b1-48e7-ab67-cd793767db13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('374ef78d-4c18-4020-9d64-09fd951d37da', 'The Emperor', false, 'b6ee32c7-b4b1-48e7-ab67-cd793767db13');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2481f31a-5970-4584-8c4e-1389c00fe7d3', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Easy', 'What does the title of Michael Rosen''s poem ''Chivvy'' mean in colloquial English?', '''To chivvy'' means to pester, nag, or continuously prompt someone (especially children) with micro-instructions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd5a5138-d1b6-4564-a3c6-3ed99deadf9a', 'To nag, harass, or urge someone continuously and repetitively to do things in a particular way', true, '2481f31a-5970-4584-8c4e-1389c00fe7d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ae1b2de-e988-47be-91cd-eecc6014911d', 'To play a happy musical song', false, '2481f31a-5970-4584-8c4e-1389c00fe7d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a595b3e-cbb2-486e-8f29-56e63f7062b2', 'To go on a long ocean voyage', false, '2481f31a-5970-4584-8c4e-1389c00fe7d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('246ec5bf-5d4b-4079-8655-a08dd9ae5d3d', 'To cook delicious sweets', false, '2481f31a-5970-4584-8c4e-1389c00fe7d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2d66692-3046-4975-a11f-fa54a9b7b7c7', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Easy', 'Which of the following is a typical grown-up command mentioned in Michael Rosen''s poem ''Chivvy''?', 'Rosen catalogs incessant parental injunctions: ''Speak up'', ''Don''t talk with your mouth full'', ''Don''t point''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d42d5477-edde-4fa0-967b-107900f969ca', '"Speak up! Don''t talk with your mouth full! Don''t stare! Don''t point!"', true, 'b2d66692-3046-4975-a11f-fa54a9b7b7c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18579df3-a0f6-4a96-b4a6-29bdd1269cec', '"Run into the street without looking!"', false, 'b2d66692-3046-4975-a11f-fa54a9b7b7c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('473bc0d5-f8df-414c-82c2-abf305d474ce', '"Eat ice cream for breakfast!"', false, 'b2d66692-3046-4975-a11f-fa54a9b7b7c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90b72d99-50f0-4371-a118-cb1205f8c711', '"Stay awake all night!"', false, 'b2d66692-3046-4975-a11f-fa54a9b7b7c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84b3574e-50a6-4bc0-ad95-90e45807fcd0', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Easy', 'What ironical, contradictory complaint do grown-ups make at the very end of ''Chivvy'' after giving non-stop instructions all day?', 'The poem ends with supreme irony: after micromanaging every juvenile action, adults complain that children cannot think independently.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f20b104-0014-4c41-bc51-4261dab79e97', '"Can''t you make your own mind up about anything?!"', true, '84b3574e-50a6-4bc0-ad95-90e45807fcd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff2802da-ee4e-432e-8ddc-67c029acdb18', '"Why are you so obedient?"', false, '84b3574e-50a6-4bc0-ad95-90e45807fcd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a9120f9-4b65-4692-b289-c58629ed6f9d', '"You are the smartest child in the world."', false, '84b3574e-50a6-4bc0-ad95-90e45807fcd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('001bd65f-1a83-4216-a0b2-3d34884226d1', '"Go to sleep immediately."', false, '84b3574e-50a6-4bc0-ad95-90e45807fcd0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('370450a2-b7ea-4f81-8e3f-fd23a29ab953', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'How did the kind old farmer show his benevolent character towards nature even before finding the gold?', 'The old man exhibited deep ecological compassion, intentionally turning soil to feed foraging herons.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7146aad9-3702-4f8d-82ed-57e3aa8f3b73', 'When tilling his fields, he was always kind to every living creature, often turning up sods of earth on purpose to give worms to the hungry white herons', true, '370450a2-b7ea-4f81-8e3f-fd23a29ab953');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd1e7f61-3dc1-4cd4-8be9-27ef20d2d065', 'He planted only thorny bushes', false, '370450a2-b7ea-4f81-8e3f-fd23a29ab953');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55ea45e5-f6bb-480b-810d-b3cd9a7dcf65', 'He threw stones at birds', false, '370450a2-b7ea-4f81-8e3f-fd23a29ab953');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('befbddfd-50c9-4d78-9479-1bdec70d97aa', 'He refused to share his water', false, '370450a2-b7ea-4f81-8e3f-fd23a29ab953');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('004dd18b-07e0-4928-a379-d454ae2d3d10', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'What happened when the wicked greedy neighbor climbed a withered cherry tree and threw ashes over the Daimyo''s royal procession?', 'The ash failed to bloom and choked the royal entourage; the Daimyo''s guard beat the imposter soundly.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75b3a5a8-7aa7-47aa-a1bb-e37c2eaf0d8b', 'Not a single bud blossomed; the wind blew fine ash directly into the eyes, noses, and mouths of the Daimyo and his wife, choking and blinding them; the royal guards dragged the wicked man down and beat him severely', true, '004dd18b-07e0-4928-a379-d454ae2d3d10');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7bc48c9-0cff-498a-b69f-e1f7ce2c5d89', 'The tree blossomed with diamonds', false, '004dd18b-07e0-4928-a379-d454ae2d3d10');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3579f698-42b3-42ed-83a5-97ca171b6a67', 'The Daimyo made him the prime minister', false, '004dd18b-07e0-4928-a379-d454ae2d3d10');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('468380a8-0d2d-463d-9e12-63a73e471167', 'The ash turned into rain', false, '004dd18b-07e0-4928-a379-d454ae2d3d10');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a590b995-c7d9-490a-a344-a58d1096d240', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'In 19th-century feudal Japan, what was the strict social custom when a Daimyo (great lord) passed along the highway?', 'Feudal Japanese etiquette mandated total prostration on the ground as the Daimyo''s palanquin passed.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7aadab2-33f6-4f22-b07b-47d2f9903cbd', 'All commoners were required to shut their upper windows, paste them with paper, and prostrate themselves flat on hands and knees until the procession passed', true, 'a590b995-c7d9-490a-a344-a58d1096d240');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2d9e659-fc10-48cc-9adb-50af7aa4021a', 'People danced and threw flowers into the palanquin', false, 'a590b995-c7d9-490a-a344-a58d1096d240');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf9b5e5b-b2c9-4eff-9ea3-91d6d552c188', 'People stood on high roofs to shout', false, 'a590b995-c7d9-490a-a344-a58d1096d240');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75095f40-219c-4d4f-b8f0-569a3116d811', 'Everyone marched alongside the palanquin', false, 'a590b995-c7d9-490a-a344-a58d1096d240');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6df7f4e7-350a-4177-bb3a-10df33d7a482', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'What is the philosophical theme of the Japanese folktale ''The Ashes That Made Trees Bloom''?', 'Karmic folklore morality: pure benevolence yields blossoming prosperity; malice and avarice yield ruin.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c72833b5-2296-40c1-87bd-dff149061fca', 'Virtue, genuine kindness, and reverence for living beings bring enduring spiritual and material rewards, whereas greed, envy, and cruelty inevitably destroy the wicked', true, '6df7f4e7-350a-4177-bb3a-10df33d7a482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6677655-155f-4cc3-a52d-3d61b1a87160', 'That dogs should never be adopted', false, '6df7f4e7-350a-4177-bb3a-10df33d7a482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fce0cb0-74b5-4d18-ab99-c1fe78fdbdb7', 'That cherry trees only grow in winter', false, '6df7f4e7-350a-4177-bb3a-10df33d7a482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28874710-7a6e-4cac-8af6-0bd3a3a1b7dc', 'That magic mills are sold in markets', false, '6df7f4e7-350a-4177-bb3a-10df33d7a482');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e957895-af84-4955-b121-222851a3fc74', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'What is the central satirical message in Michael Rosen''s poem ''Chivvy''?', 'Rosen critiques the overbearing parental micromanagement that paralyzes juvenile self-confidence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e562a58-c5d0-44d0-a254-990ff998b8d6', 'Adults stifle children''s spontaneous autonomy through relentless, petty micro-regulations, yet hypocritically expect them to display independent decision-making', true, '4e957895-af84-4955-b121-222851a3fc74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f013a70-553f-4b5e-95f7-791d471ac020', 'Children should never listen to their parents', false, '4e957895-af84-4955-b121-222851a3fc74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3dc5de2-b5ce-4569-a764-aac0f3011b46', 'Manners are completely useless in society', false, '4e957895-af84-4955-b121-222851a3fc74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb41889b-3565-446c-bbde-473a37d46f25', 'Poems should only be written for adults', false, '4e957895-af84-4955-b121-222851a3fc74');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('feef2808-ec84-45df-9f12-694076a09d1e', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'Identify the meaning of the archaic word ''Dame'' in ''The good old man and his dame'':', '''Dame'' archaically denotes the matronly mistress or wife of a household.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f69bd61c-bf81-4765-aebc-71c014327e24', 'An elderly married woman / wife / lady of the house', true, 'feef2808-ec84-45df-9f12-694076a09d1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f1a2ce5-8298-4e59-9bf0-93cf2758d0e4', 'A young princess', false, 'feef2808-ec84-45df-9f12-694076a09d1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82b51360-0ae3-4bb1-a575-ce63e4cbd760', 'A soldier', false, 'feef2808-ec84-45df-9f12-694076a09d1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66cfb702-9293-4aa1-95f4-61be3d8f719c', 'A fairy godmother', false, 'feef2808-ec84-45df-9f12-694076a09d1e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63f8928a-448e-4e74-b522-dfa4b16363b9', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'What is the meaning of the phrasal verb ''To turn up'' in: ''The dog turned up a heap of gold''?', 'In agriculture/excavation, ''turn up'' means excavating or exposing buried items from beneath the soil.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af6db8be-5db6-4120-bc93-04bc0ef1fa3f', 'To dig up or uncover by scratching/ploughing the soil', true, '63f8928a-448e-4e74-b522-dfa4b16363b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('348455c0-c3c6-4665-be82-805bf9a60a51', 'To increase the volume', false, '63f8928a-448e-4e74-b522-dfa4b16363b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23b292f1-92e8-4e90-88fd-74fa4bd6a39b', 'To arrive at a party', false, '63f8928a-448e-4e74-b522-dfa4b16363b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6c99fbb-cc41-4dd1-83ba-4bf0d7bcde59', 'To rotate around', false, '63f8928a-448e-4e74-b522-dfa4b16363b9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c08758e-34d1-4ed3-9159-44c760e600b4', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'Choose the correct Relative Pronoun (''Which'' vs ''That'') to complete the non-defining clause:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('948f3946-dfa1-4daf-8e13-fb60517684d3', 'which (non-restrictive clause set off by commas)', true, '4c08758e-34d1-4ed3-9159-44c760e600b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f3f4a95-a10b-49ce-95ec-3a81c022a787', 'that', false, '4c08758e-34d1-4ed3-9159-44c760e600b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1a20dad-fa55-4da4-87e1-99bdd0ca5b80', 'who', false, '4c08758e-34d1-4ed3-9159-44c760e600b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee8c7220-1ed9-468e-beb0-97617afebfc2', 'whom', false, '4c08758e-34d1-4ed3-9159-44c760e600b4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5fcec0bc-f215-4efb-af2d-35810c29bcfd', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'Fill in the blank with the appropriate Preposition:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f809b2c-d58c-4f43-9155-18eeacbdb8d9', 'into / up', true, '5fcec0bc-f215-4efb-af2d-35810c29bcfd');
