INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('743a7fbe-b6b0-42e6-876c-ed1aa7450ccc', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'What is the SYNONYM of the word ''Covetous'' in: ''The covetous neighbor wanted the magic mill''?', '''Covetous'' means yearning greedily for another person''s possessions.', NOW()) ON CONFLICT DO NOTHING;
