INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1108d525-cf70-4a36-981b-9035212106b0', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'What is the ANTONYM of ''Withered'' in: ''The withered cherry tree burst into bloom''?', 'The antonym of ''withered'' (shriveled/desiccated) is ''flourishing'' or ''blooming''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5093ac2-e37a-4e0b-a791-08e0942f56c8', 'Flourishing / Lush / Blooming', true, '1108d525-cf70-4a36-981b-9035212106b0');
