INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93425172-b481-47d8-ad5c-f0f5d87d9805', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'What poetic device is prominent in the short, staccato imperative lines of ''Chivvy'' (''Sit up'', ''Say please'', ''Less noise'')?', 'Short, brisk imperative clauses rhythmically recreate the relentless cadence of adult nagging.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('153376b2-3ba0-4870-b8f3-0b90d546ce87', 'Imperative Monosyllabic Cadence (mimicking sharp, repetitive parental drill commands)', true, '93425172-b481-47d8-ad5c-f0f5d87d9805');
