INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2496fc9b-f613-4b10-8f72-2ec43608bd05', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'Identify the part of speech of the underlined word in: ''The dog ran **friskily** around the garden.''', '''Friskily'' is an adverb of manner modifying the intransitive verb ''ran''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c084741-10fc-4659-b984-b8d405a4807b', 'Adverb of Manner (describing HOW the dog ran)', true, '2496fc9b-f613-4b10-8f72-2ec43608bd05');
