INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('973e1372-2d28-4352-ac9a-9e9c98307d67', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Medium', 'In ''Chivvy'', what are children told to do with their elbows at the dinner table?', 'A classic dining etiquette rule featured in the poem: ''Take your elbows off the table''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bae75224-79f9-4d52-935d-ce09a5d4c867', '"Take your elbows OFF the table!"', true, '973e1372-2d28-4352-ac9a-9e9c98307d67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcc3cf03-6f9f-43b6-8b43-a95afc396785', '"Put your elbows on the plate!"', false, '973e1372-2d28-4352-ac9a-9e9c98307d67');
