INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d5597e7a-b7c0-4337-a9a7-5847fba64fed', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Hard', 'What cultural resonance does the ''Cherry Blossom'' (Sakura) hold in Japanese aesthetics as portrayed in this folktale?', 'Sakura (cherry blossom) in Japanese folklore represents ephemeral beauty, spiritual resurrection, and the auspicious triumph of pure virtue.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50a9a358-d5b6-4321-bd18-d601927eea97', 'Sakura symbolizes purity, spring renewal, the blossoming of divine grace, and the transient beauty of life restored through moral goodness', true, 'd5597e7a-b7c0-4337-a9a7-5847fba64fed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f004ded-1c82-4f50-be08-f21c05ebffff', 'It is a symbol of war and destruction', false, 'd5597e7a-b7c0-4337-a9a7-5847fba64fed');
