INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd5b797a-0002-42ea-80d7-dd5e4ba20ea3', 'It represents dark winter nights', false, 'd5597e7a-b7c0-4337-a9a7-5847fba64fed');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('533ec782-abae-45f7-bfb0-dd54bc184388', 'Class 7', 'English', 'Chapter 4: The Ashes That Made Trees Bloom & Chivvy', 'Hard', 'What comprehensive ethical lesson links Chapter 4 of NCERT Class 7 English?', 'Chapter 4 weaves together ecological compassion, karmic benevolence, and insightful pedagogy balancing discipline with autonomy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a5ac468-7b71-4610-bc0e-0a23b25fa41f', 'True human dignity flourishes through unconditional kindness, respect for life, and understanding the delicate balance between guided discipline and nurturing independent personal thought', true, '533ec782-abae-45f7-bfb0-dd54bc184388');
