INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b6d783cb-cfd1-40eb-a6cd-8e111a34730b', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'Spot the IMPOSTER in the following group of Inventors and their groundbreaking technological breakthroughs:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cb4408b-5d85-4dc5-950d-ddaa3f4b2436', 'Breakthrough 1', false, 'b6d783cb-cfd1-40eb-a6cd-8e111a34730b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ae3cf84-c87c-4b34-996e-fe1b310814e6', 'Breakthrough 2', false, 'b6d783cb-cfd1-40eb-a6cd-8e111a34730b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3d7444d-4e0b-4797-8bbe-9259abfd0227', 'Breakthrough 3', false, 'b6d783cb-cfd1-40eb-a6cd-8e111a34730b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59d29d69-817f-4acc-a203-60a8794a9295', 'Breakthrough 4 (Wright Brothers invented the FIRST AIRPLANE, not nuclear power plants)', true, 'b6d783cb-cfd1-40eb-a6cd-8e111a34730b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d107374-17d6-475a-99f6-af81c990a3c4', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'What is the historical significance of the ''Columbian Exchange'' resulting from Christopher Columbus''s 1492 transatlantic voyage?', 'The Columbian Exchange fundamentally reorganized global ecology, nutrition (potatoes, maize to Eurasia; wheat, livestock to Americas), and demographics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b55bedbd-7515-4060-8622-e2aa8ec064cc', 'The massive global transfer of agricultural crops (potatoes, maize, tomatoes, chillies), animals, populations, and infectious diseases between the Old World (Afro-Eurasia) and New World (Americas) that permanently transformed global diets and demographics', true, '7d107374-17d6-475a-99f6-af81c990a3c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('164fa076-20da-4706-a7b5-da737b09a82a', 'An agreement to sell Spanish ships to Asian kings', false, '7d107374-17d6-475a-99f6-af81c990a3c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('253f3ac5-51c7-41e6-9a85-baa8edc01f5a', 'A chess tournament played in 1492', false, '7d107374-17d6-475a-99f6-af81c990a3c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c70de6c5-8299-4f2d-9540-65ba5155cf53', 'The discovery of Antarctica', false, '7d107374-17d6-475a-99f6-af81c990a3c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d62fc27-d30a-4950-8828-e13a1b6c8dda', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'Match Column I (Great Pioneers) with Column II (Monumental Milestone):
(a) Galileo Galilei       -> (i) Telescopic discovery of Jupiter''s 4 moons & lunar craters
(b) Isaac Newton          -> (ii) Universal Law of Gravitation & Three Laws of Motion
(c) Charles Darwin        -> (iii) Theory of Evolution by Natural Selection (Origin of Species)
(d) Albert Einstein       -> (iv) Special & General Theory of Relativity (E = mc²)', 'Galileo = observational astronomy; Newton = classical mechanics; Darwin = natural selection; Einstein = relativistic physics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e745f49d-46a5-4df4-97a5-a6cb4d7633f0', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '4d62fc27-d30a-4950-8828-e13a1b6c8dda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c15fe17-bb0b-456f-8ff5-3d563e4b5268', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '4d62fc27-d30a-4950-8828-e13a1b6c8dda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1811b17a-a622-41f4-9b75-c32573a15781', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '4d62fc27-d30a-4950-8828-e13a1b6c8dda');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f068bdc6-ef4a-4e3a-8851-06c5bbb56691', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '4d62fc27-d30a-4950-8828-e13a1b6c8dda');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18afcbf9-99c0-4a1c-b79c-68da9f366d0f', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'Read the statements regarding space exploration milestones:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6277523b-77eb-428f-b483-09ea2c118f5d', 'Statements 1 and 2 only', true, '18afcbf9-99c0-4a1c-b79c-68da9f366d0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2abddcf-b29a-4ebd-b5cc-0c5824437e70', 'Statements 2 and 3 only', false, '18afcbf9-99c0-4a1c-b79c-68da9f366d0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f52d211-a03c-448b-b631-8ead810fbc92', 'Statements 1 and 3 only', false, '18afcbf9-99c0-4a1c-b79c-68da9f366d0f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23d603b5-7f79-4c60-af49-a4ba9f304c47', 'All Statements 1, 2, and 3', false, '18afcbf9-99c0-4a1c-b79c-68da9f366d0f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81b32847-0cd1-4a1a-a32b-0b78be8cd7d8', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'Who was the British mathematician and logician who broke the German ''Enigma'' naval code during World War II at Bletchley Park and laid the theoretical foundations of Artificial Intelligence and Computer Science (Turing Machine)?', 'Alan Turing engineered the Bombe codebreaking machine, formulated the Turing Machine universal computation model, and proposed the Turing Test for AI.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78f11c94-50e7-499d-8e97-14f76b489045', 'Alan Turing', true, '81b32847-0cd1-4a1a-a32b-0b78be8cd7d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb2a38c9-b285-4c15-92ef-cc8a312bc2d2', 'John von Neumann', false, '81b32847-0cd1-4a1a-a32b-0b78be8cd7d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe4a118c-4214-42bc-a811-6a1c84296590', 'Claude Shannon', false, '81b32847-0cd1-4a1a-a32b-0b78be8cd7d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('528337e0-dc5c-4196-a152-c6a586d63daa', 'Norbert Wiener', false, '81b32847-0cd1-4a1a-a32b-0b78be8cd7d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('44ea7dc8-3980-49d3-aa6c-6d3b566d5edb', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'What was the revolutionary medical discovery made by Edward Jenner in 1796 that transformed public health worldwide?', 'Jenner''s cowpox-smallpox cross-immunity trial established the scientific doctrine of vaccination (from Latin ''vacca'' meaning cow).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f65c5ea3-c309-4b3c-8a6f-851a723c168c', 'Inoculating humans with mild Cowpox blister fluid conferred immune protection (cross-immunity) against lethal Smallpox without causing fatal disease', true, '44ea7dc8-3980-49d3-aa6c-6d3b566d5edb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c7fd883-31ee-40bb-a659-6dd9300eba07', 'He discovered that boiling water prevents broken bones', false, '44ea7dc8-3980-49d3-aa6c-6d3b566d5edb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d658a635-aa5f-4349-99c5-a9cf379ea18f', 'He created synthetic aspirin pills', false, '44ea7dc8-3980-49d3-aa6c-6d3b566d5edb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a89bc74c-1b92-46c6-bcd6-84473be1d6ce', 'He proved that diseases are caused by bad smells (miasma)', false, '44ea7dc8-3980-49d3-aa6c-6d3b566d5edb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7aa3dc56-f7e1-4f31-80e5-f3f6ac6b1c03', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'Consider four foundational inventions:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89806044-05e0-4272-a6cf-17154f30e00f', 'Each invention radically accelerated the velocity and scale of human communication, energy transformation, and global knowledge distribution', true, '7aa3dc56-f7e1-4f31-80e5-f3f6ac6b1c03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f28eb2f4-9120-4288-960c-f8fb30685b78', 'They were all invented in the same country', false, '7aa3dc56-f7e1-4f31-80e5-f3f6ac6b1c03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3afd3b3-5458-4549-b58a-4b8ef20a1d6a', 'They all use steam energy', false, '7aa3dc56-f7e1-4f31-80e5-f3f6ac6b1c03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d52f437f-e534-4a0e-831d-52d58d06057d', 'They all operate on batteries', false, '7aa3dc56-f7e1-4f31-80e5-f3f6ac6b1c03');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b74e382-63fc-42fe-a44c-8b0ba6262ca2', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'Why was the discovery of the double helix structure of DNA by James Watson, Francis Crick, and Rosalind Franklin in 1953 so monumental?', 'Elucidating the double helical base-pairing (A-T, G-C) architecture of DNA launched molecular biology, biotechnology, and genomic medicine.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf594738-00d8-4622-94a2-2ebe46b35d96', 'It unlocked the molecular genetic code of all biological life, revealing how hereditary information is stored, replicated, and expressed across generations', true, '9b74e382-63fc-42fe-a44c-8b0ba6262ca2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d04756b6-2e3f-4cbf-aefa-1b03f0cbdbb5', 'It proved that cells are made of stone', false, '9b74e382-63fc-42fe-a44c-8b0ba6262ca2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('642fef1c-847e-41a6-9b87-270fa9c91583', 'It allowed humans to stop eating food', false, '9b74e382-63fc-42fe-a44c-8b0ba6262ca2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7105ce49-c1c3-4032-a34e-01e61bf43a84', 'It proved that blood has no cells', false, '9b74e382-63fc-42fe-a44c-8b0ba6262ca2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6987ef0-4b89-4e70-94a1-ef158d0ebbb8', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'What was the navigational breakthrough invented by John Harrison in the 18th century (the Marine Chronometer H4)?', 'Harrison''s H4 chronometer solved the famous ''Longitude Problem'', enabling precise oceanic navigational positioning.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bee18f38-7f15-4f4a-846a-a494e219dd15', 'A precise mechanical clock that kept exact time at sea despite ship motion and temperature changes, enabling sailors to calculate exact LONGITUDE and preventing shipwrecks', true, 'f6987ef0-4b89-4e70-94a1-ef158d0ebbb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35eaa7de-76e4-4d0e-a628-f054e2435626', 'A compass that pointed south', false, 'f6987ef0-4b89-4e70-94a1-ef158d0ebbb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04d285c6-2313-42a5-b2d9-6e3bed412f04', 'A waterproof sail', false, 'f6987ef0-4b89-4e70-94a1-ef158d0ebbb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82f78288-8dad-4179-91d1-dabfbe83896a', 'A telescope that saw through clouds', false, 'f6987ef0-4b89-4e70-94a1-ef158d0ebbb8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d3eae67-d36c-443d-a85f-fe66ca36c981', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'Who was the Polish astronomer whose 1543 book ''De revolutionibus orbium coelestium'' shattered the 1,400-year Geocentric Ptolemaic model and proved the HELIOCENTRIC model (Earth orbits the Sun)?', 'Copernicus displaced Earth from the cosmological center, proposing the heliocentric planetary system and igniting the Scientific Revolution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d411b4fb-57a1-4c61-afc1-609f982cfc59', 'Nicolaus Copernicus', true, '9d3eae67-d36c-443d-a85f-fe66ca36c981');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6744662b-2d8f-451d-bcfc-f3fc396d481b', 'Tycho Brahe', false, '9d3eae67-d36c-443d-a85f-fe66ca36c981');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78bc7916-eba2-46a4-9a2d-37c94073d24d', 'Aristotle', false, '9d3eae67-d36c-443d-a85f-fe66ca36c981');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8463d148-02bd-405c-8df2-3953d278509a', 'Ptolemy', false, '9d3eae67-d36c-443d-a85f-fe66ca36c981');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1776c62a-2312-4f32-8850-29be227c8187', 'Class 7', 'GK', 'Chapter 4: World History, Great Inventions, Discoveries & Famous Explorers', 'Hard', 'What unifying human spirit is celebrated through the history of Great Inventions, Discoveries, and Explorations?', 'Chapter 4 synthesizes the relentless human drive for scientific discovery, geographic exploration, and transformative technological innovation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ded714bd-bed3-4c72-ac31-ba3af340157f', 'Humanity''s relentless curiosity, resilience, and courage to question prevailing orthodoxies, venture into uncharted frontiers, and innovate technologies that elevate human civilization', true, '1776c62a-2312-4f32-8850-29be227c8187');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d065027-4751-4d78-a607-8f5596d5bd8e', 'That all discoveries were made by pure accident without effort', false, '1776c62a-2312-4f32-8850-29be227c8187');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2684e777-8adb-47cf-809b-cb9b84d4543c', 'That exploration has completely finished on Earth and in space', false, '1776c62a-2312-4f32-8850-29be227c8187');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0257b559-34e1-4fdd-b09c-e4bc4179dc9b', 'That technology always reduces human happiness', false, '1776c62a-2312-4f32-8850-29be227c8187');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('af9c21ba-789d-40d1-841e-dbb79007aea7', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'From which two great historical royal lineages were the Mughals descended?', 'Maternal descent from Genghis Khan (d. 1227) and paternal lineage from Timur (d. 1404).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66e62a73-c863-40ac-ac62-4514ee0eeda4', 'On their mother''s side from Genghis Khan (Mongol ruler) and on their father''s side from Timur (ruler of Iran, Iraq, and Central Asia)', true, 'af9c21ba-789d-40d1-841e-dbb79007aea7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c602697-6269-41d7-88fa-a4ddf90e9fab', 'From Alexander the Great and Julius Caesar', false, 'af9c21ba-789d-40d1-841e-dbb79007aea7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b3e5720-3cf3-437d-8461-3a865a66eff3', 'From Ashoka and Chandragupta Maurya', false, 'af9c21ba-789d-40d1-841e-dbb79007aea7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fd7d93e-938a-4b48-8ebc-3e49f95f6e1e', 'From the Ottoman Sultans and Roman Emperors', false, 'af9c21ba-789d-40d1-841e-dbb79007aea7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c886ca9-1e88-4b52-bc73-6fdceadcf092', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'Who was the founder of the Mughal Empire in India, who defeated Ibrahim Lodi in the First Battle of Panipat in 1526 CE?', 'Babur captured Delhi and Agra in 1526 after defeating Ibrahim Lodi at the First Battle of Panipat.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0adf322-7612-4b8f-9576-4729046436c8', 'Babur (Zahiruddin Muhammad Babur)', true, '9c886ca9-1e88-4b52-bc73-6fdceadcf092');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a96ea08e-aff8-4e9a-ba50-4575b180b69b', 'Akbar', false, '9c886ca9-1e88-4b52-bc73-6fdceadcf092');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7afc9f88-0bd7-40a2-b63d-1ff27d73e94e', 'Humayun', false, '9c886ca9-1e88-4b52-bc73-6fdceadcf092');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c79a84a1-ea08-4f4e-aed4-1b67f5761a3c', 'Jahangir', false, '9c886ca9-1e88-4b52-bc73-6fdceadcf092');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3f85ce4e-1b6e-4d75-a76d-ddd84b5d101b', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'Which battle fought in 1527 CE cemented Babur''s control over northern India by defeating Rana Sanga of Mewar and his Rajput confederacy?', 'In 1527 at Khanwa, Babur defeated Rana Sanga and his Rajput allies, securing the Gangetic heartland.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6acf3f50-f4b2-4b85-9fe1-84ef7da5c65b', 'Battle of Khanwa', true, '3f85ce4e-1b6e-4d75-a76d-ddd84b5d101b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33a66e39-44ba-48ee-b221-1b5e98c16fe4', 'Battle of Chanderi', false, '3f85ce4e-1b6e-4d75-a76d-ddd84b5d101b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5de82ad-1483-450d-9a5c-b1b4d8574077', 'Battle of Ghagra', false, '3f85ce4e-1b6e-4d75-a76d-ddd84b5d101b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2201863a-bf83-4c43-a96c-accdc55d2d8b', 'Battle of Haldighati', false, '3f85ce4e-1b6e-4d75-a76d-ddd84b5d101b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a9c8a897-727e-429d-b2c9-41630d41a9fb', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'Who ascended the Mughal throne at the age of 13 in 1556 CE under the guardianship of Bairam Khan, expanding the empire into a pan-subcontinental powerhouse?', 'Akbar ascended the throne in 1556 at Kalanaur (Punjab) at age 13, guided by his regent Bairam Khan.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c356244-bb69-4b9b-b52c-305d850a959b', 'Akbar the Great (Jalaluddin Muhammad Akbar)', true, 'a9c8a897-727e-429d-b2c9-41630d41a9fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee09e87f-3206-46b0-810c-9d2985d74eff', 'Humayun', false, 'a9c8a897-727e-429d-b2c9-41630d41a9fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b1ac50d-a6c4-4b57-8a23-49dbe54f46e2', 'Shah Jahan', false, 'a9c8a897-727e-429d-b2c9-41630d41a9fb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aa49422-886d-488d-9333-d03db40e88be', 'Aurangzeb', false, 'a9c8a897-727e-429d-b2c9-41630d41a9fb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb59ae07-9e63-4a5d-aa17-51c23982335b', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'What was the administrative and military ranking system introduced by Akbar to organize imperial nobility and soldiers called?', 'Akbar instituted the Mansabdari system to structure military command, noble status, and official salary.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fc87d8f-c352-43bc-854d-8d5237a24349', 'Mansabdari System', true, 'cb59ae07-9e63-4a5d-aa17-51c23982335b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3ebcfc2-2cb9-4739-96c4-fd1e3669c506', 'Iqta System', false, 'cb59ae07-9e63-4a5d-aa17-51c23982335b');
