INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f79cffa2-1e53-4274-ada8-f7b937409407', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'In the Mansabdari system, what did the numerical rank ''ZAT'' determine?', 'Zat was the numerical index determining personal prestige, protocol ranking, and salary scale.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('968de546-93f9-424f-985b-c93c86cc372b', 'The noble''s personal position, hierarchical status in the court, and official monetary salary', true, 'f79cffa2-1e53-4274-ada8-f7b937409407');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efcbaf6a-2f7c-4f98-9cbb-b332f86802da', 'The number of elephants', false, 'f79cffa2-1e53-4274-ada8-f7b937409407');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b99fb60a-54c6-4764-9d52-6529389631c6', 'The number of palaces owned', false, 'f79cffa2-1e53-4274-ada8-f7b937409407');
