INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67b38a6a-5972-48b1-8fbb-eb9815ddb4ac', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'In the Mansabdari system, what did the numerical rank ''SAWAR'' specify?', 'Sawar rank fixed the military cavalry contingent (horsemen) the officer was legally obligated to muster.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db923f58-08b9-4e37-9bf4-eeb54432b54e', 'The exact number of maintained cavalrymen (horsemen) the Mansabdar was required to maintain for state service', true, '67b38a6a-5972-48b1-8fbb-eb9815ddb4ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86f38370-4834-4660-afaf-c8f83691a079', 'The number of horses in the royal stable', false, '67b38a6a-5972-48b1-8fbb-eb9815ddb4ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb59d508-b587-4a32-951a-f62c973db09b', 'The number of cannons', false, '67b38a6a-5972-48b1-8fbb-eb9815ddb4ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('988aa910-470a-4996-8981-7012ea49cdea', 'The number of villages owned', false, '67b38a6a-5972-48b1-8fbb-eb9815ddb4ac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59d97277-2fe0-42f4-b388-2995404f599e', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'What were the revenue assignments from which Mansabdars received their salaries (similar to Sultanate Iqtas) called?', 'Jagirs were revenue-yielding territorial tracts granted to Mansabdars to cover their sanctioned salary allowances.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a404e1d-5f03-41b5-9f4f-84df9ea99082', 'Jagirs (and the holders were called Jagirdars)', true, '59d97277-2fe0-42f4-b388-2995404f599e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb618770-4513-4fc4-a0c1-88ea412e75ef', 'Zabt', false, '59d97277-2fe0-42f4-b388-2995404f599e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddad63d2-9e6b-4461-97df-08aa695942dd', 'Subas', false, '59d97277-2fe0-42f4-b388-2995404f599e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32a90169-d0e0-446a-b004-a63b31d58c6e', 'Parganas', false, '59d97277-2fe0-42f4-b388-2995404f599e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59e262de-299c-4a42-878f-f4952eed6eab', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'Who was Akbar''s brilliant Revenue Minister who carried out a careful 10-year survey (1570–1580) of crop yields, prices, and cultivated areas to establish the ''Zabt'' revenue system?', 'Raja Todar Mal formulated the ''Ain-i Dahsala'' (10-year revenue assessment) and Zabt cash-revenue schedules.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3a5c7f9-6e0d-42d1-8fee-f10b6c3fe39f', 'Raja Todar Mal', true, '59e262de-299c-4a42-878f-f4952eed6eab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0264c3d1-126e-4f6d-b4dd-46003598992c', 'Raja Man Singh', false, '59e262de-299c-4a42-878f-f4952eed6eab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fada4d7c-c9a4-4c07-a0e2-3317e03eca0f', 'Birbal (Mahesh Das)', false, '59e262de-299c-4a42-878f-f4952eed6eab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb6043a8-fd2a-4d3e-98ad-c0afc35010e3', 'Abul Fazl', false, '59e262de-299c-4a42-878f-f4952eed6eab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe78da33-69c3-4a2c-abf0-65ba70d0b5e1', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'Who was Akbar''s close friend, courtier, and court historian who wrote the monumental three-volume official history ''Akbar Nama'' and ''Ain-i Akbari''?', 'Abul Fazl composed the Akbar Nama (Vol 1: ancestors, Vol 2: Akbar''s reign) and Vol 3: Ain-i Akbari (administration and statistics).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64e3f2f0-face-43b7-8c75-0524deb87685', 'Abul Fazl', true, 'fe78da33-69c3-4a2c-abf0-65ba70d0b5e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7874b470-ebfd-4e83-a502-df695d50c203', 'Faizi', false, 'fe78da33-69c3-4a2c-abf0-65ba70d0b5e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c08c662-446c-42a5-bdba-7f8a89ffc13f', 'Badauni', false, 'fe78da33-69c3-4a2c-abf0-65ba70d0b5e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33391725-1a04-4c52-a307-5457ad6c38f7', 'Ziauddin Barani', false, 'fe78da33-69c3-4a2c-abf0-65ba70d0b5e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('51f86b6d-c3b6-4a1e-83b2-9c54d3a0d48b', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'What was the philosophical doctrine of ''Universal Peace'' and religious tolerance formulated by Akbar and Abul Fazl called?', 'Sulh-i Kul (peace with all) promoted universal religious tolerance and justice without sectarian discrimination.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9904134-a184-44d6-af6e-7675b1d68b03', 'Sulh-i Kul (Universal Peace / Absolute Tolerance)', true, '51f86b6d-c3b6-4a1e-83b2-9c54d3a0d48b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e611ab4c-29b6-4607-90e6-1b496ffdca86', 'Din-i Ilahi', false, '51f86b6d-c3b6-4a1e-83b2-9c54d3a0d48b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b538b440-5856-48bd-aeee-b0224a2f7fdb', 'Zabt', false, '51f86b6d-c3b6-4a1e-83b2-9c54d3a0d48b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b0c69e3-88ef-4ebc-bfbe-2057fb015de4', 'Mansab', false, '51f86b6d-c3b6-4a1e-83b2-9c54d3a0d48b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b8e1116-562f-44d0-bba7-20b2cd5fd40c', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Easy', 'In which hall of inter-faith discussions built at Fatehpur Sikri in 1575 did Akbar hold spiritual dialogues with theologians of diverse religions (Ulama, Brahmins, Jesuit priests, Zoroastrians)?', 'The Ibadat Khana at Fatehpur Sikri hosted comparative theological debates leading Akbar to develop Sulh-i Kul.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5e91aee-12bf-4749-be55-1ee20010fe0c', 'Ibadat Khana (House of Worship)', true, '0b8e1116-562f-44d0-bba7-20b2cd5fd40c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd2d88d7-e55c-4cb5-b477-57138cce7677', 'Diwan-i Aam', false, '0b8e1116-562f-44d0-bba7-20b2cd5fd40c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9ea9016-6c7a-4c54-b985-217d31f586e3', 'Diwan-i Khas', false, '0b8e1116-562f-44d0-bba7-20b2cd5fd40c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c70e3fc3-4b93-4dea-8dac-df1df11d438a', 'Buland Darwaza', false, '0b8e1116-562f-44d0-bba7-20b2cd5fd40c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9be3f859-e221-4bc6-838e-b562b37806ee', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'What was the Mughal custom of dynastic succession regarding the inheritance of royal power?', 'The Mughals rejected strict primogeniture, adhering to Timurid coparcenary partition which sparked violent fratricidal succession wars.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cedc2f5-50a8-4f4f-ae9b-d9cc9fa2fe93', 'Coparcenary Inheritance (Timurid tradition of dividing the empire among all brothers / sons), which frequently triggered bitter wars of succession among royal princes', true, '9be3f859-e221-4bc6-838e-b562b37806ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('753ff4f1-2f1b-4538-ba56-7dea880be446', 'Strict Primogeniture (only the eldest son inherits everything)', false, '9be3f859-e221-4bc6-838e-b562b37806ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fdc5a11-0e17-4392-9142-0d3dad57e375', 'Election by public voting', false, '9be3f859-e221-4bc6-838e-b562b37806ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ea8fcd8-ed11-44f2-a613-9125566ada0e', 'The crown was passed to the King''s uncle', false, '9be3f859-e221-4bc6-838e-b562b37806ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6dec665e-4c81-41fa-a3c1-4c207da00f51', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'How did Akbar build a lasting alliance with Rajput rulers (such as the Kachhwahas of Amber) to consolidate his pan-Indian empire?', 'Akbar''s Rajput policy combined diplomatic respect, matrimonial ties, high court ranks (Man Singh), and autonomy over Watan Jagirs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d36622b2-47e2-4ec6-ad47-c7779c698964', 'He respected Rajput martial honor, formed marital matrimonial alliances, granted high Mansabdari military commands to Rajput chiefs, and restored conquered lands as hereditary ''Watan Jagirs''', true, '6dec665e-4c81-41fa-a3c1-4c207da00f51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0abf42bf-31b5-4ef4-958c-e5e5bea033aa', 'He imprisoned all Rajput kings', false, '6dec665e-4c81-41fa-a3c1-4c207da00f51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17688960-4aea-4a7c-93b6-8337a314213a', 'He banned Rajput culture', false, '6dec665e-4c81-41fa-a3c1-4c207da00f51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('557f3b27-01e9-4f3e-8367-3450e174af40', 'He forced Rajputs to migrate to Iran', false, '6dec665e-4c81-41fa-a3c1-4c207da00f51');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aad63ea0-4d37-4c40-ab20-fa69a7b2e53b', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'Who was Mehr-un-Nisa (Empress Nur Jahan) and what immense political authority did she exercise during the reign of Emperor Jahangir?', 'Nur Jahan exercised supreme administrative co-sovereignty, issuing sovereign farmans and appearing on imperial coinage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95cdf8b1-c6f3-4243-9361-65ee8a029f2c', 'She was Jahangir''s brilliant, exceptionally influential empress who held supreme imperial power, issued royal farmans (orders), and had coins minted jointly in her name alongside the Emperor', true, 'aad63ea0-4d37-4c40-ab20-fa69a7b2e53b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad58bcc0-6129-425e-ad73-8d63a0962f9f', 'She was a court poetess with no political power', false, 'aad63ea0-4d37-4c40-ab20-fa69a7b2e53b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd735cfa-5b0b-46de-8360-c2f71440967f', 'She lived in exile outside India', false, 'aad63ea0-4d37-4c40-ab20-fa69a7b2e53b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e851e03f-6e1f-489e-87eb-45a362c676f3', 'She was the ruler of Bengal', false, 'aad63ea0-4d37-4c40-ab20-fa69a7b2e53b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77f4a825-2f92-4f3b-870c-d5a2f2bd0533', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'What was the administrative division of the Mughal Empire under Akbar?', 'Suba (governed by Subadar and financial Diwan) → Sarkar (district under Faujdar) → Pargana (under Shiqdar and Amil) → Grama.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f559f13-8d6e-49d7-b2e9-51154d45f911', 'The empire was divided into Subas (provinces) governed by a Subadar ; each Suba was subdivided into Sarkars (districts) and Parganas (sub-districts/parishes)', true, '77f4a825-2f92-4f3b-870c-d5a2f2bd0533');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1e1ff04-2919-4bea-89e5-e55a2b47c719', 'The empire had no provinces', false, '77f4a825-2f92-4f3b-870c-d5a2f2bd0533');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cbddded-b622-47f3-9b4d-756ffa6f7845', 'The empire was divided into 100 kingdoms', false, '77f4a825-2f92-4f3b-870c-d5a2f2bd0533');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc8aa2b8-3048-4f71-8a68-5d50f25b359b', 'The empire was divided into two halves: North and South', false, '77f4a825-2f92-4f3b-870c-d5a2f2bd0533');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('abfae37d-423c-44ac-97cb-90b8290202fa', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'In Mughal provincial administration, who were the ''Subadar'' and the ''Diwan'' of a province (Suba)?', 'Mughal checks-and-balances: executive-military authority resided in the Subadar; fiscal-financial authority resided independently in the Diwan.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73a4f9d5-cc8c-4f9e-93c9-3dc2f93a15c2', 'The Subadar carried out political and military functions ; the Diwan was the financial officer responsible for revenue collection and accounting', true, 'abfae37d-423c-44ac-97cb-90b8290202fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('920a9dca-f616-4292-81f4-2110a3716b30', 'The Subadar was a doctor ; the Diwan was a teacher', false, 'abfae37d-423c-44ac-97cb-90b8290202fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ac453b4-5fa6-41b6-8de8-3dc7c0713ad0', 'Both were palace musicians', false, 'abfae37d-423c-44ac-97cb-90b8290202fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edd6eefe-2a5c-459d-a504-e725644b0b79', 'The Diwan was the supreme general and Subadar was the cook', false, 'abfae37d-423c-44ac-97cb-90b8290202fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6004f799-53e7-4722-ab71-2b9c44b21c86', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'What was the ''Zabt'' revenue system formulated by Todar Mal?', 'Zabt established empirical crop-specific cash schedules based on standard land measurement (bigha/jarib) and 10-year price averages.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d4d4b21-4756-40c3-a11e-f881d0603894', 'A scientific revenue system where agricultural land was physically surveyed/measured, crop yields and market price indices over 10 years were calculated, and each crop was assigned a fixed cash revenue tax schedule', true, '6004f799-53e7-4722-ab71-2b9c44b21c86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ab9fb37-b60b-4473-aa1f-12ef8429c55f', 'A tax on all horses', false, '6004f799-53e7-4722-ab71-2b9c44b21c86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a97d074-e641-4471-a65b-d58d30994c63', 'A system where soldiers took all food by force', false, '6004f799-53e7-4722-ab71-2b9c44b21c86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6a34061-967b-4c2f-b3e1-83c016a28c40', 'A tax only on foreign traders', false, '6004f799-53e7-4722-ab71-2b9c44b21c86');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc310a49-a3a7-4d6d-8147-84a8e3b6968f', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'In Mughal society, what blanket umbrella term was used to describe all rural intermediaries—whether powerful local village headmen (Muqaddams/Chaudhuris) or hereditary regional chieftains?', 'The Mughals employed ''Zamindar'' generically for all rural landed intermediaries collecting agricultural surplus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29851fc2-5014-46af-9538-5604af604774', 'Zamindars', true, 'fc310a49-a3a7-4d6d-8147-84a8e3b6968f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25a7b677-8da1-4480-b746-d813c5b034dd', 'Mansabdars', false, 'fc310a49-a3a7-4d6d-8147-84a8e3b6968f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf01cb3d-4b42-40e8-b2c1-35a9bd6063e3', 'Jagirdars', false, 'fc310a49-a3a7-4d6d-8147-84a8e3b6968f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1efcf916-bb69-4ca3-bee7-31a13b85715b', 'Subadars', false, 'fc310a49-a3a7-4d6d-8147-84a8e3b6968f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5958cbaa-7f5b-4804-b1e5-314c98c750ae', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'Why did the Sisodiya Rajputs of Mewar refuse to accept Mughal authority for a long time, and how did the Mughals treat them when they finally surrendered to Jahangir in 1614?', 'Jahangir preserved Sisodiya dignity by restoring Mewar as a hereditary Watan Jagir exempt from personal court attendance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('729fa4e5-fc62-494e-b226-663efc6785e9', 'Mewar resisted fiercely under Maharana Pratap ; upon submission under Rana Amar Singh, Jahangir treated them with honorable nobility, returning their entire territory as a Watan Jagir', true, '5958cbaa-7f5b-4804-b1e5-314c98c750ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e8c6661-d964-47f5-bb6c-8b9474301937', 'Jahangir executed all Mewar princes', false, '5958cbaa-7f5b-4804-b1e5-314c98c750ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa852b31-ecf0-4dd6-97d7-68c9dc572afd', 'Jahangir annexed Mewar and destroyed its forts', false, '5958cbaa-7f5b-4804-b1e5-314c98c750ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31bea229-0f9e-4185-870d-b67255017fe5', 'Mewar was given to foreign merchants', false, '5958cbaa-7f5b-4804-b1e5-314c98c750ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b952f5af-3de4-4979-92cb-93b27036f53a', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'Why did Aurangzeb''s long, grinding 25-year military campaigns in the Deccan (1681–1707) lead to the severe exhaustion and eventual decline of the Mughal Empire?', 'Aurangzeb''s Deccan ulcer drained the empire''s fiscal resources, disrupted Jagirdari stability, and triggered administrative paralysis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4af63763-76ff-40c1-82bb-db323a550e5d', 'Endless Deccan wars drained imperial treasuries, overextended military logistics, sparked protracted guerilla warfare with Marathas, and caused the collapse of administrative supervision in the northern heartland', true, 'b952f5af-3de4-4979-92cb-93b27036f53a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0876768-572f-40f9-80b2-ec45dfeb5352', 'Because Aurangzeb gave up his empire to become a monk', false, 'b952f5af-3de4-4979-92cb-93b27036f53a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3517cb0-9549-4280-9aa8-1b97ce3e481b', 'Because the Deccan had no soldiers', false, 'b952f5af-3de4-4979-92cb-93b27036f53a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4e8cb37-6845-4c53-8b23-ca508a5c1944', 'Because the British invaded Delhi in 1682', false, 'b952f5af-3de4-4979-92cb-93b27036f53a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a032fc13-f2cd-45f5-ab0d-ac9e1195f5f0', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'What was the ''Jagirdari Crisis'' that crippled the Mughal administration in the late 17th century under Aurangzeb?', 'Shortage of revenue-bearing paibaqi land caused the Jagirdari crisis, triggering agrarian distress and peasant rebellions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7360dc25-a1c4-44ec-9691-06a54b659922', 'The massive inflation in the number of Mansabdars created a severe shortage of productive Jagirs; Jagirdars ruthlessly squeezed peasants for maximum revenue during their brief assignments', true, 'a032fc13-f2cd-45f5-ab0d-ac9e1195f5f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f88fada-6f61-4c6d-ae9c-1e70540c2039', 'All Jagirs were destroyed by floods', false, 'a032fc13-f2cd-45f5-ab0d-ac9e1195f5f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1461899-68fa-4626-ae90-ddb198907925', 'Mansabdars refused to accept lands', false, 'a032fc13-f2cd-45f5-ab0d-ac9e1195f5f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9f7289b-f1fa-4aed-9dfa-476a30b46054', 'Jagirs were banned by imperial law', false, 'a032fc13-f2cd-45f5-ab0d-ac9e1195f5f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5dc95ce2-b776-4182-a770-18d30223f355', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'Which Maratha warrior king established an independent Maratha kingdom, using brilliant guerilla warfare (Ganimi Kava) against Aurangzeb''s armies and escaped from house arrest in Agra in 1666?', 'Chhatrapati Shivaji Maharaj forged an autonomous Maratha swarajya, defying Mughal hegemony via mobile guerrilla tactics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fa3d567-4b6a-4f20-aa3f-d5f441b3b092', 'Chhatrapati Shivaji Maharaj', true, '5dc95ce2-b776-4182-a770-18d30223f355');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cd00e72-e481-43e2-9435-b809e7a1ae61', 'Sambhaji', false, '5dc95ce2-b776-4182-a770-18d30223f355');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('108de07f-d862-42f5-80dc-49892e05924e', 'Peshwa Baji Rao I', false, '5dc95ce2-b776-4182-a770-18d30223f355');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12c89b0f-6930-4b4c-9640-a991ba4d59f8', 'Shahji Bhonsle', false, '5dc95ce2-b776-4182-a770-18d30223f355');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0581169b-f592-43b9-a222-05d9f46736af', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'What is the third volume of Abul Fazl''s Akbar Nama called, which contains rich statistical details about crops, yields, prices, wages, administrative regulations, and cultural traditions?', 'The Ain-i Akbari constitutes the definitive imperial gazetteer and administrative-statistical compendium of Akbar''s reign.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3ffe642-7d49-42f2-8c3e-96487cf06422', 'Ain-i Akbari', true, '0581169b-f592-43b9-a222-05d9f46736af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba720cd3-7035-4f63-ae98-3dc2ba03a6d5', 'Tuzuk-i Baburi', false, '0581169b-f592-43b9-a222-05d9f46736af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6bfbb88-f676-4782-9b74-702a67082489', 'Padshahnama', false, '0581169b-f592-43b9-a222-05d9f46736af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1007dfd-1625-4410-8e8e-a9af6b270553', 'Humayun-nama', false, '0581169b-f592-43b9-a222-05d9f46736af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('659ae428-7d23-464b-8263-5cd35af27e88', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'Which Mughal prince translated fifty Upanishads from Sanskrit into Persian (''Sirr-i Akbar'' / The Greatest Secret), appreciating the unity of divine truth across Hinduism and Islam?', 'Dara Shikoh was a philosopher-prince who translated the Upanishads and authored ''Majma-ul-Bahrain'' (Mingling of Two Oceans).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11675ca9-8304-43b0-b75a-acb901bc13b8', 'Dara Shikoh (eldest son of Shah Jahan)', true, '659ae428-7d23-464b-8263-5cd35af27e88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('318a8043-889e-4674-a4bb-13adcc7371e9', 'Aurangzeb', false, '659ae428-7d23-464b-8263-5cd35af27e88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe4e3702-b077-4112-aab2-4b5d6faee037', 'Murad Bakhsh', false, '659ae428-7d23-464b-8263-5cd35af27e88');
