INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('668e3bd4-b4eb-4d67-bdd9-63f503d73af2', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'What was the ''Kotwal'' in Mughal urban municipal administration?', 'The Kotwal exercised municipal police, judicial oversight, market weights inspection, and urban safety policing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fd7ca7d-5a4f-4da6-9d9c-a161a62a67ba', 'The chief town police officer responsible for urban law and order, night patrols, market surveillance, and citizen registry', true, '668e3bd4-b4eb-4d67-bdd9-63f503d73af2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbe70f37-b4d3-421a-8353-1ff3d97984c8', 'The royal chef in Delhi', false, '668e3bd4-b4eb-4d67-bdd9-63f503d73af2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82350608-1f0f-4f9a-a308-fad6c4cb741f', 'The head priest of the mosque', false, '668e3bd4-b4eb-4d67-bdd9-63f503d73af2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12f3c031-01e0-43d9-872c-1749211ecf6f', 'The commander of royal ships', false, '668e3bd4-b4eb-4d67-bdd9-63f503d73af2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6837ebe-d773-4836-bba5-66e4495f8e11', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'Which rebellious son of Aurangzeb received military support from the Marathas and the Deccan Sultanate before fleeing to Safavid Iran in 1681?', 'Prince Akbar revolted against his father Aurangzeb in 1681, allied with Sambhaji, and sought refuge with the Safavid Shah of Persia.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d770dba-51a8-4f99-8f31-bd9576e5ed88', 'Prince Akbar (Muhammad Akbar)', true, 'c6837ebe-d773-4836-bba5-66e4495f8e11');
