INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b4ab2656-9771-41d1-bc87-f0256669c1e6', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Medium', 'What magnificent white marble mausoleum did Emperor Shah Jahan construct in Agra along the Yamuna river in memory of his beloved wife Mumtaz Mahal?', 'The Taj Mahal is the supreme masterpiece of Indo-Islamic symmetry, Pietra Dura inlay, and domed architectural engineering.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67c71713-b1ef-4c25-adc5-fb01c2966aba', 'The Taj Mahal (built between 1632 and 1648 CE)', true, 'b4ab2656-9771-41d1-bc87-f0256669c1e6');
