INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6c94736c-8d8e-45a4-a59c-732914e369ae', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'Spot the IMPOSTER in the following chronological sequence of Mughal Emperors and their major architectural/political milestones:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d496efe3-0729-4f8d-97ea-e0639f4c64ad', 'Milestone 1', false, '6c94736c-8d8e-45a4-a59c-732914e369ae');
