INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81e271c3-249a-4b1f-a5aa-44f4bbc77435', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'Analyze the fiscal disparity in the Mughal Empire revealed in official records:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf99ecc7-c282-4c19-b8fc-4dfbf3e92e49', '61.5% of the total estimated revenue of the empire was concentrated in the hands of this tiny elite of 445 nobles', true, '81e271c3-249a-4b1f-a5aa-44f4bbc77435');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63332291-f2d6-4fdd-899e-bda6dc0d0c45', '10% of the total revenue', false, '81e271c3-249a-4b1f-a5aa-44f4bbc77435');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f6af65f-41c6-41e7-b599-c5ccb6c79d9f', '100% of the total revenue', false, '81e271c3-249a-4b1f-a5aa-44f4bbc77435');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cd4e2e1-48ae-4c59-a3ae-53b31f293be8', '5% of the total revenue', false, '81e271c3-249a-4b1f-a5aa-44f4bbc77435');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f268972d-648d-4801-adc0-8d7d28cfb577', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'Match Column I (Mughal Administrative Terms) with Column II (Exact Functional Meanings):
(a) Subadar -> (i) Provincial governor commanding political and military administration
(b) Diwan   -> (ii) Provincial chief revenue and finance officer
(c) Bakhshi -> (iii) Imperial military paymaster responsible for troop muster
(d) Sadr    -> (iv) Minister in charge of religious and charitable patronage', 'Subadar = governor; Diwan = finance; Bakhshi = military paymaster; Sadr = ecclesiastical/charitable minister.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2ce6f83-f558-4b15-b7ce-82de57de6a98', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'f268972d-648d-4801-adc0-8d7d28cfb577');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5decb6e2-37ec-4485-ac1a-06421d74f0d4', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'f268972d-648d-4801-adc0-8d7d28cfb577');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9727e36-a5d8-481c-ad30-52d45559ad8b', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'f268972d-648d-4801-adc0-8d7d28cfb577');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bfabbf5-72db-4c45-bf5a-ebe6c556c4c9', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'f268972d-648d-4801-adc0-8d7d28cfb577');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7be5837c-d732-4b9b-a696-f89bd27ea8fe', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'Read the statements regarding Akbar''s religious policy:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1df3e64-6a06-413f-98d2-5c8e5bb91b9f', 'Statements 1 and 2 only', true, '7be5837c-d732-4b9b-a696-f89bd27ea8fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9681106-1fc7-44ee-b201-db67067df4c1', 'Statements 2 and 3 only', false, '7be5837c-d732-4b9b-a696-f89bd27ea8fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d28198b-1cbe-4a21-88e4-d557872d1901', 'Statements 1 and 3 only', false, '7be5837c-d732-4b9b-a696-f89bd27ea8fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('947b39af-9528-4a53-a2f9-36a83a68aa14', 'All Statements 1, 2, and 3', false, '7be5837c-d732-4b9b-a696-f89bd27ea8fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0ff399b-300e-4ec1-8133-a096a038cb10', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'Why did the Mughals prefer not to be called ''Moghol / Mongol'' and took great pride in their ''Timurid'' paternal lineage?', 'The dynasty distanced itself from the gory memory of Genghisid massacres, glorifying their Timurid renaissance patrimony.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e86fccdd-3b72-4d4e-9427-3228214a2e75', 'The name Mongol was historically associated with Genghis Khan''s brutal massacres of countless innocent people, whereas their ancestor Timur had captured Delhi in 1398 with great royal prestige', true, 'c0ff399b-300e-4ec1-8133-a096a038cb10');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('452cd4e9-1800-4d08-9946-e0cfa91565c7', 'Because Timur was a European king', false, 'c0ff399b-300e-4ec1-8133-a096a038cb10');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbea6e7c-dfeb-47d8-bb2d-6f7c23cc56bf', 'Because Mongols had no horses', false, 'c0ff399b-300e-4ec1-8133-a096a038cb10');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecb777f7-b4f6-4c23-9fb2-caddae0b8078', 'Because Babur could not speak Persian', false, 'c0ff399b-300e-4ec1-8133-a096a038cb10');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d1515b51-b563-46df-9692-44012449f77d', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'How did the introduction of Field Artillery (cannons and matchlocks) revolutionize military warfare in India during Babur''s 1526 Panipat campaign?', 'Babur deployed Ottoman tactical innovation: chaining baggage wagons to shield matchlock gunners, supported by deadly flanking cavalry encirclement (Tulghuma).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5e190cc-32e3-4889-b435-218aee169799', 'Babur combined gunpowder artillery carts (Rumi device) with rapid flanking cavalry maneuvers (Tulghuma), completely decimating Ibrahim Lodi''s massive static war elephant army', true, 'd1515b51-b563-46df-9692-44012449f77d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cd3c99d-709e-483b-ae38-853851dd8990', 'Artillery made soldiers walk backwards', false, 'd1515b51-b563-46df-9692-44012449f77d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('817dde7b-e25e-4799-8166-0ac44f9f5511', 'Artillery destroyed all food in India', false, 'd1515b51-b563-46df-9692-44012449f77d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b4dc2de-554b-475c-bec4-526ab0eb02c0', 'Cannons were made of wood and burned down', false, 'd1515b51-b563-46df-9692-44012449f77d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75760fa1-c9a0-4639-9b0e-bdb1f47a7105', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'What was the structural relationship between the Mughal Emperor, the Zamindars, and the Peasantry?', 'Local Zamindars held traditional kinship ties with village cultivators; imperial over-exploitation frequently triggered joint agrarian revolts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c5c057b-158c-4398-9151-27ad55f9addc', 'Peasants produced the agrarian wealth; Zamindars collected the produce and shared local caste/lineage ties with peasants, occasionally leading armed peasant rebellions against excessive central Mughal tax demands', true, '75760fa1-c9a0-4639-9b0e-bdb1f47a7105');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('802e4220-1e91-41c9-bd61-90650e41513a', 'Zamindars gave all their land to the Emperor for free', false, '75760fa1-c9a0-4639-9b0e-bdb1f47a7105');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c149c90-6dff-4f71-93af-36c75291dfec', 'Peasants were paid salaries in gold by the Emperor', false, '75760fa1-c9a0-4639-9b0e-bdb1f47a7105');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aec2083-a932-4d12-878e-0662563de10b', 'There were no taxes in the Mughal Empire', false, '75760fa1-c9a0-4639-9b0e-bdb1f47a7105');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed330665-605e-41ef-9481-f7c2feffb49a', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'Consider four key regions that mounted fierce resistance against Mughal expansion in the 17th century:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8887f026-437a-4f8e-bad3-e497d8f9aa67', 'They leveraged rugged regional terrain, intense local community cohesion, and decentralized mobile warfare to resist centralized imperial domination', true, 'ed330665-605e-41ef-9481-f7c2feffb49a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ac1a5c6-1f00-459f-b994-33f5728aa56b', 'They all surrendered without fighting', false, 'ed330665-605e-41ef-9481-f7c2feffb49a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94aab2c7-4b88-4321-b438-ef769e68bfe0', 'They allied with the British against the Mughals', false, 'ed330665-605e-41ef-9481-f7c2feffb49a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eab5ad62-58c9-4f2e-be60-0e38b39de64c', 'They abandoned their lands and moved to Central Asia', false, 'ed330665-605e-41ef-9481-f7c2feffb49a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c637abd-9386-4409-95fa-d41d7b52a357', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'Why is Abul Fazl''s ''Ain-i Akbari'' celebrated by modern socio-economic historians as a pioneering masterwork of statistical administration?', 'The Ain-i Akbari is a landmark in quantitative historiography, offering quantitative demographic, agricultural, and administrative inventories.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6c853e2-9684-4f5a-81da-933cb293a2cd', 'It provides rigorous empirical statistical surveys of agricultural revenue, price tables, daily wages, military rolls, fauna, flora, and socio-religious traditions across all 15 Subas of Akbar''s empire', true, '9c637abd-9386-4409-95fa-d41d7b52a357');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4decce92-961c-49ad-8c8b-89904d9454cf', 'It is a fictional novel of magic and fantasy', false, '9c637abd-9386-4409-95fa-d41d7b52a357');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29dcdfe2-0b92-427c-8920-f78b6374e16b', 'It was written in modern English', false, '9c637abd-9386-4409-95fa-d41d7b52a357');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('485aa4a0-7b7c-4c74-aa39-aa7cb3f8e1e6', 'It contains no numbers or records', false, '9c637abd-9386-4409-95fa-d41d7b52a357');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c20c4b54-ca3a-48cb-a1f7-d4c5ff5ef266', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'What architectural innovation distinguishes the ''Charbagh'' (Four-Gardens) layout perfected by Mughal emperors (e.g. Humayun''s Tomb, Shalimar Gardens)?', 'Charbagh architecture geometricizes Persian paradise garden symbology: quadripartite orthogonal grids bisected by flowing water channels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b13507ec-31ea-45d4-ab65-bba550c20768', 'A grand rectangular walled enclosure divided into four symmetrical quadrangles by intersecting, axial raised artificial water channels and walkways, symbolizing the four rivers of Paradise', true, 'c20c4b54-ca3a-48cb-a1f7-d4c5ff5ef266');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d094a12-1558-465b-8ed0-f303b490387f', 'A garden with only four flowers', false, 'c20c4b54-ca3a-48cb-a1f7-d4c5ff5ef266');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ddfac5d-621c-45ab-bb51-a291db31e6a9', 'A circular maze made of glass', false, 'c20c4b54-ca3a-48cb-a1f7-d4c5ff5ef266');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e60532e-d054-412c-9323-e85fbe554014', 'A underground garden without sunlight', false, 'c20c4b54-ca3a-48cb-a1f7-d4c5ff5ef266');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3277ea0-a035-4074-9675-03e6b9024d04', 'Class 7', 'Social Science', 'Chapter 4: The Mughal Empire', 'Hard', 'What overarching historical legacy defines Chapter 4 of NCERT Class 7 History regarding the Mughal Empire?', 'Chapter 4 synthesizes the political institutionalization, fiscal centralization, architectural elegance, and cultural pluralism of the Mughal Empire.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68481291-1a1d-48e7-b17e-07183c84ae18', 'The creation of a pan-Indian empire that established enduring administrative frameworks, standardized revenue and coinage systems, synthesized composite Indo-Islamic art and architecture, and promoted cultural pluralism under Sulh-i Kul', true, 'd3277ea0-a035-4074-9675-03e6b9024d04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('910c0e82-6087-4069-9bdd-45461a0e5149', 'A period of constant darkness with no administration', false, 'd3277ea0-a035-4074-9675-03e6b9024d04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('070d3f0a-2679-4dbc-8fa7-e381967e4275', 'The complete end of all Indian culture', false, 'd3277ea0-a035-4074-9675-03e6b9024d04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0672d1cf-3a0b-450d-bea2-6b5077f2fc97', 'An empire that lasted only two weeks', false, 'd3277ea0-a035-4074-9675-03e6b9024d04');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f51dff69-761c-452d-b141-b4b955c37445', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', 'वे शब्दांश जो किसी मूल शब्द के पहले (आरंभ में) जुड़कर उसके अर्थ में परिवर्तन या विशेषता ला देते हैं, उन्हें व्याकरण में क्या कहते हैं?', 'उप + सर्ग: मूल शब्द के पूर्व में जुड़कर अर्थ बदलने वाले सार्थक शब्दांश ''उपसर्ग'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20003290-191d-491f-9699-8e8d7916db36', 'उपसर्ग (Prefix)', true, 'f51dff69-761c-452d-b141-b4b955c37445');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73487341-7292-4d0a-b4f8-59eac601c23c', 'प्रत्यय (Suffix)', false, 'f51dff69-761c-452d-b141-b4b955c37445');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('214ca276-e00a-48ae-b699-6ebf93af6a5b', 'समास', false, 'f51dff69-761c-452d-b141-b4b955c37445');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4fa02d6-9389-41f6-a39d-7fc560772502', 'संधि', false, 'f51dff69-761c-452d-b141-b4b955c37445');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3c241668-3624-4974-afcc-902fad9b5363', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', 'वे शब्दांश जो किसी मूल शब्द के अंत (पीछे) में जुड़कर नए शब्द का निर्माण करते हैं और उसके अर्थ में विशेषता लाते हैं, उन्हें क्या कहते हैं?', 'प्रति + अय: शब्दों के अंत में जुड़कर नया अर्थ उत्पन्न करने वाले शब्दांश ''प्रत्यय'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b440c572-053b-497d-bb76-a654ad4d322e', 'प्रत्यय (Suffix)', true, '3c241668-3624-4974-afcc-902fad9b5363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09b0a153-1094-44b3-99c6-f91d3afe1638', 'उपसर्ग', false, '3c241668-3624-4974-afcc-902fad9b5363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56bf3ab6-57a8-4b59-83f6-6f0479e9219f', 'कारक', false, '3c241668-3624-4974-afcc-902fad9b5363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a64e595f-1a2c-4bd9-9da0-cf55fd61c3e7', 'अव्यय', false, '3c241668-3624-4974-afcc-902fad9b5363');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b801a9ca-6d9f-4a32-bf0d-6c7dc7fa5f47', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', 'हिंदी में प्रयुक्त उपसर्गों को मुख्य रूप से कितने वर्गों में बाँटा गया है?', 'उपसर्गों के 3 मुख्य स्रोत हैं: संस्कृत (तत्सम), हिंदी (तद्भव), तथा उर्दू-फ़ारसी (आगत)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65e0ad42-7c41-43ca-b777-574254624c50', 'तीन प्रमुख वर्गों में (1. संस्कृत के तत्सम उपसर्ग, 2. हिंदी के तद्भव उपसर्ग, 3. उर्दू-फ़ारसी के विदेशी उपसर्ग)', true, 'b801a9ca-6d9f-4a32-bf0d-6c7dc7fa5f47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55ca4de7-9ae2-40f2-a08c-42405cad1c2f', 'दो वर्गों में', false, 'b801a9ca-6d9f-4a32-bf0d-6c7dc7fa5f47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('462d84bb-f594-4647-b655-691eac4782c3', 'पाँच वर्गों में', false, 'b801a9ca-6d9f-4a32-bf0d-6c7dc7fa5f47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4098ed2-507e-4455-a2c4-1708c6040d13', 'चार वर्गों में', false, 'b801a9ca-6d9f-4a32-bf0d-6c7dc7fa5f47');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('790bde62-177c-466e-9188-417b29b81ad4', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', '''अति'' (संस्कृत उपसर्ग - अर्थ: अधिक/परे) से बना शुद्ध शब्द कौन-सा है?', 'अति + अधिक = अत्यधिक (यण संधि के साथ ''अति'' उपसर्ग का प्रयोग)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6cec02c-6523-471a-9d01-71ff09f6a40c', 'अत्यधिक (अति + अधिक) / अत्यंत', true, '790bde62-177c-466e-9188-417b29b81ad4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7146efeb-d18b-40bb-84d9-671b82d5651c', 'अधिकार', false, '790bde62-177c-466e-9188-417b29b81ad4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba61e974-9242-4a70-8034-7e40d3101627', 'अभिमान', false, '790bde62-177c-466e-9188-417b29b81ad4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41b81b1c-623e-48a9-b701-0a9d0f003de8', 'अनुवाद', false, '790bde62-177c-466e-9188-417b29b81ad4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da2f3ac2-38d2-4ef1-bf10-9b29179a86ab', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', '''प्र'' उपसर्ग (अर्थ: अधिक/आगे) से बने शब्दों का सही समूह कौन-सा है?', 'प्र + हार = प्रहार, प्र + गति = प्रगति, प्र + बल = प्रबल।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c172ed1-aab3-4fa5-9869-8d1b82b07d9d', 'प्रहार, प्रगति, प्रबल, प्रसिद्ध', true, 'da2f3ac2-38d2-4ef1-bf10-9b29179a86ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a4f1226-4e05-43b0-b492-9854f9c2084f', 'अपमान, अपराध', false, 'da2f3ac2-38d2-4ef1-bf10-9b29179a86ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5864fb7-806b-4e65-a0a4-7a7c95620e42', 'अनुज, अनुराग', false, 'da2f3ac2-38d2-4ef1-bf10-9b29179a86ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4b5da86-7b79-4184-a8c1-f9ce2b7033c8', 'उपकार, उपवन', false, 'da2f3ac2-38d2-4ef1-bf10-9b29179a86ab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dcdfb32c-6173-449f-aed0-aff35a0f7953', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', 'हिंदी के तद्भव उपसर्ग ''अ'' / ''अन'' (अर्थ: अभाव/निषेध) से बने शब्दों का सही उदाहरण कौन-सा है?', 'अ + काल = अकाल; अन + पढ़ = अनपढ़; अन + जान = अनजान।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e34064a7-a6c7-4cbe-9038-531114191896', 'अछूत, अकाल, अनपढ़, अनजान', true, 'dcdfb32c-6173-449f-aed0-aff35a0f7953');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3edf1654-705a-455f-98a6-800209afdf50', 'सुपुत्र, सुगम', false, 'dcdfb32c-6173-449f-aed0-aff35a0f7953');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('958d3373-bf6d-4d66-999c-65404cdeb2c6', 'कुपुत्र, कुकर्म', false, 'dcdfb32c-6173-449f-aed0-aff35a0f7953');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8231d3d6-e1ca-44d6-89db-165401817adc', 'भरपेट, भरपूर', false, 'dcdfb32c-6173-449f-aed0-aff35a0f7953');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e0649aeb-11b0-4b74-a1c6-606099eac0f1', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', 'उर्दू-फ़ारसी उपसर्ग ''बे'' (अर्थ: बिना / रहित) से बने शब्दों का सही समूह कौन-सा है?', 'बे + कसूर = बेकसूर, बे + इमान = बेइमान, बे + परवाह = बेपरवाह।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f40a545-0b30-45a9-baf1-a571222f497f', 'बेकसूर, बेइमान, बेपरवाह, बेदाग', true, 'e0649aeb-11b0-4b74-a1c6-606099eac0f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97e5d287-d008-40c4-84f6-fcbb78cf2134', 'लापरवाह, लावारिस', false, 'e0649aeb-11b0-4b74-a1c6-606099eac0f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31e801e0-c2d7-4453-9f18-14a1b6341b44', 'बदनाम, बदसूरत', false, 'e0649aeb-11b0-4b74-a1c6-606099eac0f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7608939c-8b31-4cd4-9572-8eb01d08d0bd', 'खुशनसीब, खुशबू', false, 'e0649aeb-11b0-4b74-a1c6-606099eac0f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2987920-e8da-4085-a374-69bd30596b41', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', 'प्रत्यय के मुख्य रूप से कितने भेद होते हैं?', 'प्रत्यय के दो मूल भेद हैं: कृत प्रत्यय (धातु/क्रिया के साथ) तथा तद्धित प्रत्यय (संज्ञा/सर्वनाम/विशेषण के साथ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c64f5c1-b44a-489e-9269-6ab5d8374c9d', 'दो भेद (1. कृत / कृदंत प्रत्यय - क्रिया/धातु के अंत में, 2. तद्धित प्रत्यय - संज्ञा/सर्वनाम/विशेषण के अंत में)', true, 'c2987920-e8da-4085-a374-69bd30596b41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcdc1fdb-428c-4738-b1d3-57abe0065b69', 'चार भेद', false, 'c2987920-e8da-4085-a374-69bd30596b41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fe6d73d-5e42-4d68-9b57-8be2cb736c77', 'तीन भेद', false, 'c2987920-e8da-4085-a374-69bd30596b41');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17afc64a-1bdf-4562-89c9-8d52e623c186', 'पाँच भेद', false, 'c2987920-e8da-4085-a374-69bd30596b41');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('235b0226-2c9a-46ad-b34c-000a6dd810b2', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', 'क्रिया की मूल धातु के अंत में जुड़कर संज्ञा या विशेषण शब्द बनाने वाले प्रत्यय क्या कहलाते हैं?', 'धातु/क्रिया के अंत में प्रयुक्त प्रत्यय ''कृत प्रत्यय'' तथा निर्मित शब्द ''कृदंत'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45208968-037a-4d90-af04-f745e3526ff3', 'कृत प्रत्यय / कृदंत (जैसे: लिख् + आवट = लिखावट, पढ़् + आकू = पढ़ाकू)', true, '235b0226-2c9a-46ad-b34c-000a6dd810b2');
