INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca94854f-6572-4748-a752-a1803d46d97a', 'उपसर्ग', false, '235b0226-2c9a-46ad-b34c-000a6dd810b2');
