INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13a013a8-cc7f-410d-8f20-4045bdd828f1', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', 'संज्ञा, सर्वनाम और विशेषण शब्दों के अंत में जुड़कर नए शब्द बनाने वाले प्रत्यय क्या कहलाते हैं?', 'संज्ञा, सर्वनाम व विशेषण में जुड़ने वाले प्रत्यय ''तद्धित'' तथा निर्मित शब्द ''तद्धितांत'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
