INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bdcb1a53-185c-4f06-9c04-a49276ce1d39', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', '''मिठास'' शब्द में मूल शब्द और प्रत्यय क्या है?', 'विशेषण ''मीठा'' में भाववाचक तद्धित प्रत्यय ''आस'' जुड़ने से ''मिठास'' बनता है।', NOW()) ON CONFLICT DO NOTHING;
