INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cca2d359-d60a-4c6b-a0ff-f59275afd806', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Easy', '''लिखावट'' शब्द में कौन-सा प्रत्यय प्रयुक्त हुआ है?', 'लिख् धातु में भाववाचक कृत प्रत्यय ''आवट'' जुड़ने से ''लिखावट'' शब्द बनता है।', NOW()) ON CONFLICT DO NOTHING;
