INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b0a2065-afbe-4c6a-a687-3cbe9e674f71', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''दुर्'' (संस्कृत उपसर्ग - अर्थ: बुरा/कठिन) से बने शब्दों का सही समूह कौन-सा है?', 'दुर् + लभ = दुर्लभ; दुर् + आचार = दुराचार; दुर् + गम = दुर्गम; दुर् + बल = दुर्बल।', NOW()) ON CONFLICT DO NOTHING;
