INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea1f93a0-45ee-45d3-8137-44c51187affe', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''सम्'' (संस्कृत उपसर्ग - अर्थ: अच्छी तरह / पूर्णता) से बने शब्दों का सही उदाहरण कौन-सा है?', 'सम् + मान = सम्मान; सम् + तोष = संतोष (अनुस्वार रूप); सम् + कार = संस्कार।', NOW()) ON CONFLICT DO NOTHING;
