INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be123405-2c92-4d04-af53-4fd1a4a24c45', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''अभि'' उपसर्ग (अर्थ: सामने/श्रेष्ठ) से बने शब्दों का सही समूह कौन-सा है?', 'अभि + मान = अभिमान; अभि + नय = अभिनय; अभि + वादन = अभिवादन।', NOW()) ON CONFLICT DO NOTHING;
