INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3cdb232-8f7d-463a-929e-654c46d00abe', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''इक'' प्रत्यय जुड़ने पर मूल शब्द के प्रथम स्वर में होने वाले दीर्घीकरण का सही उदाहरण कौन-सा है?', '''इक'' प्रत्यय आदि-स्वर वृद्धि करता है: अ→आ (सामाजिक), इ→ऐ (ऐतिहासिक), उ→औ (भौगोलिक)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afd0765e-2f7a-4cb3-a6ff-f4e1e951ff62', 'समाज + इक = सामाजिक ; इतिहास + इक = ऐतिहासिक ; भूगोल + इक = भौगोलिक ; धर्म + इक = धार्मिक', true, 'f3cdb232-8f7d-463a-929e-654c46d00abe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('667883a6-42f6-4cd0-91bf-6e56c53bad03', 'समाज + इक = समाजक', false, 'f3cdb232-8f7d-463a-929e-654c46d00abe');
