INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff910c48-7121-4b90-a4e8-1537208895f6', 'धर्म + इक = धर्मक', false, 'f3cdb232-8f7d-463a-929e-654c46d00abe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d652a349-78d2-4441-bdce-9e9586d37652', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''इत'' प्रत्यय से बने शब्दों का सही समूह कौन-सा है?', 'हर्ष + इत = हर्षित; शिक्षा + इत = शिक्षित; पुष्प + इत = पुष्पित।', NOW()) ON CONFLICT DO NOTHING;
