INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b41aa682-94ef-4674-ad83-5aadab25effb', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''वान'' और ''वती'' प्रत्यय से बने शब्दों का सही उदाहरण कौन-सा है?', 'धन + वान = धनवान (पुल्लिंग) / धनवती (स्त्रीलिंग)।', NOW()) ON CONFLICT DO NOTHING;
