INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fdb0cceb-d11c-47e1-bfdd-378373a4c0f7', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''वाला'' कर्तृवाचक प्रत्यय से बने शब्दों का सही समूह कौन-सा है?', 'संज्ञा + वाला = कर्ता सूचक शब्द (दूधवाला, फलवाला)।', NOW()) ON CONFLICT DO NOTHING;
