INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f7d964f-6d0a-4ebd-8fa2-4da1095a991d', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''घबराहट'' शब्द में मूल शब्द और प्रत्यय का सही विग्रह क्या है?', 'घबराना क्रिया की धातु में भाववाचक कृत प्रत्यय ''आहट'' जुड़कर ''घबराहट'' बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cba8750-ed5f-4fcb-8bf7-41b12a640c62', 'घबराना (या घबरा) + आहट (प्रत्यय)', true, '6f7d964f-6d0a-4ebd-8fa2-4da1095a991d');
