INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ee444a0-05e2-42da-8daf-ec663b3762c8', 'घबराह + ट', false, '6f7d964f-6d0a-4ebd-8fa2-4da1095a991d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f911c8ed-ff38-4842-a914-227266339db5', 'घबर + आहट', false, '6f7d964f-6d0a-4ebd-8fa2-4da1095a991d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0986241-100a-4565-b069-f84bd34c1a09', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', 'निम्नलिखित में से किस शब्द में उपसर्ग और प्रत्यय दोनों का एक साथ प्रयोग हुआ है?', 'अप (उपसर्ग) + मान (मूल शब्द) + इत (प्रत्यय) = अपमानित।', NOW()) ON CONFLICT DO NOTHING;
