INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aea60aa0-5f3b-4563-b4e7-41a5c104aad3', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', 'निम्नलिखित में से किस शब्द में उपसर्ग और प्रत्यय दोनों प्रयुक्त हुए हैं?', 'अ (उपसर्ग) + लोक (मूल शब्द) + इक (प्रत्यय) = अलौकिक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73a14125-48cd-4492-91ba-8b4b8b73af0f', '''अलौकिक'' (अ [उपसर्ग] + लोक [मूल शब्द] + इक [प्रत्यय])', true, 'aea60aa0-5f3b-4563-b4e7-41a5c104aad3');
