INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59f7ffe0-03a4-4bd8-ae21-7068e588e972', '''खिलाड़ी''', false, 'aea60aa0-5f3b-4563-b4e7-41a5c104aad3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d660cd7e-9688-429a-ae6d-3f5bf8fae4be', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''परोपकार'' शब्द में कौन-सा उपसर्ग प्रयुक्त हुआ है?', 'पर (दूसरा) + उपकार = परोपकार (अ + उ = ओ, गुण संधि)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('267de01a-0a57-450b-9678-d53085f8df32', 'पर (पर + उपकार = परोपकार, गुण संधि के साथ)', true, 'd660cd7e-9688-429a-ae6d-3f5bf8fae4be');
