INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66eb29dd-a717-4868-8fa2-66ddab361ee8', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Medium', '''प्रत्येक'' शब्द में कौन-सा उपसर्ग प्रयुक्त हुआ है?', 'प्रति + एक = प्रत्येक (इ + ए = ये, यण संधि)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f64f5ed5-9e41-4a6f-89d6-c4739ec436af', 'प्रति (प्रति + एक = प्रत्येक, यण संधि के साथ)', true, '66eb29dd-a717-4868-8fa2-66ddab361ee8');
