INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e36b7350-a0d0-4f3b-b3e4-3a39fd9bc2b8', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aad7ed39-3dda-4013-ac7d-afe4b78d7d8f', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'e36b7350-a0d0-4f3b-b3e4-3a39fd9bc2b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b581384f-7994-4b6e-937e-205c22bde17e', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'e36b7350-a0d0-4f3b-b3e4-3a39fd9bc2b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c15a406-d52b-4bf1-9eb5-3f668551ab88', '(A) सही है, परन्तु (R) गलत है।', false, 'e36b7350-a0d0-4f3b-b3e4-3a39fd9bc2b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46e9b943-45da-4467-b67a-a1c9dc65fbd7', '(A) गलत है, परन्तु (R) सही है।', false, 'e36b7350-a0d0-4f3b-b3e4-3a39fd9bc2b8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('978bd70e-3cec-4f23-a3bb-e5c8de30406a', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'Spot the IMPOSTER in the following group of उपसर्ग और उनसे बने शब्दों में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('019c887a-a876-49c1-8534-5fbe820b6198', 'युग्म 1', false, '978bd70e-3cec-4f23-a3bb-e5c8de30406a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a50c097-735e-423b-886c-f88ca08aa478', 'युग्म 2', false, '978bd70e-3cec-4f23-a3bb-e5c8de30406a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f355616c-f021-44d3-9d8a-a22bb2c59f67', 'युग्म 3', false, '978bd70e-3cec-4f23-a3bb-e5c8de30406a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70ffad66-45f1-4313-be30-795276e89ff0', 'युग्म 4 (अनादर, अनहोनी में ''अन् / अन'' उपसर्ग है, ''अति'' नहीं)', true, '978bd70e-3cec-4f23-a3bb-e5c8de30406a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('799cd806-56f2-4bf3-83ca-46bda101e0e2', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'सुमेलित कीजिए (उपसर्ग और उनके अर्थ):
(क) उत् / उद् -> (i) ऊपर, श्रेष्ठ, ऊँचा (जैसे: उत्कर्ष, उन्नति)
(ख) दुर् / दुस् -> (ii) बुरा, कठिन, दुष्ट (जैसे: दुर्जन, दुस्साहस)
(ग) परा       -> (iii) विपरीत, पीछे, नाश (जैसे: पराजय, पराभव)
(घ) प्रति     -> (iv) प्रत्येक, सामने, विरुद्ध (जैसे: प्रतिकूल, प्रतिध्वनि)', 'उत् = ऊँचा; दुर् = बुरा; परा = विपरीत/पराजय; प्रति = प्रत्येक/सामने।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('033c5346-4ba9-450d-8fc3-bc71bc274726', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, '799cd806-56f2-4bf3-83ca-46bda101e0e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76a9c06d-15cc-48e9-add2-b40d88462316', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '799cd806-56f2-4bf3-83ca-46bda101e0e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be1b8390-93fb-49c7-aa1f-3201b198a0ac', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '799cd806-56f2-4bf3-83ca-46bda101e0e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fbd2441-2a67-4065-80aa-0c8c740e47d0', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '799cd806-56f2-4bf3-83ca-46bda101e0e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1010a0fd-0b05-4754-8eee-6f328f0e4c55', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'निम्नलिखित में से किस शब्द में ''निर्'' उपसर्ग प्रयुक्त हुआ है?', 'निर् + आकार = निराकार; निर् + अपराध = निरपराध (नियम/निबंध में ''नि'' उपसर्ग है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d38ac052-a915-4cb7-8c6c-e7ab8e9e7d57', '''निराकार'' (निर् + आकार = निराकार) और ''निरपराध'' (निर् + अपराध = निरपराध)', true, '1010a0fd-0b05-4754-8eee-6f328f0e4c55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8345fc1-4468-452d-8690-dcd7d5ce86af', '''नियम''', false, '1010a0fd-0b05-4754-8eee-6f328f0e4c55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0e29ec1-a974-4536-aa44-174cf088931f', '''निबंध''', false, '1010a0fd-0b05-4754-8eee-6f328f0e4c55');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be7feb6f-46f4-4991-89ed-5e4d57c7e601', '''निवास''', false, '1010a0fd-0b05-4754-8eee-6f328f0e4c55');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2493049d-de1d-4c1b-a493-28f7dada4492', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', '''उन्नति'' शब्द का शुद्ध उपसर्ग-विच्छेद क्या होगा?', 'उत् + नति = उन्नति (त् के बाद न आने पर त् का न् हो जाता है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec0f2c3a-aaf9-4580-9985-5d04d045746e', 'उत् + नति (व्यंजन संधि के नियमानुसार ''त्'' का ''न्'' में परिवर्तन)', true, '2493049d-de1d-4c1b-a493-28f7dada4492');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aea8b9e4-d23d-4ee7-933d-98c2f0c7e8c1', 'उद् + नति', false, '2493049d-de1d-4c1b-a493-28f7dada4492');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('049778d1-d462-45de-aed3-f324e3dfcdf8', 'उन् + नति', false, '2493049d-de1d-4c1b-a493-28f7dada4492');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc602eff-a5e6-40cb-9490-0a9b308e8405', 'उ + नति', false, '2493049d-de1d-4c1b-a493-28f7dada4492');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6101b858-a1dd-43e5-a200-5eb49a419b69', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'निम्नलिखित में से किस शब्द में ''कु'' उपसर्ग नहीं लगा है?', '''कुसुम'' (फूल) रूढ़ मूल शब्द है; बाकी तीनों में ''कु'' (बुरा) उपसर्ग है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f6ce2b5-04a7-4f8f-b1de-38471af045b0', '''कुसुम'' (क्योंकि यह एक रूढ़ मूल शब्द है, इसमें ''कु'' उपसर्ग नहीं है)', true, '6101b858-a1dd-43e5-a200-5eb49a419b69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcae980c-682d-4eed-b06a-6a6c2096fac5', '''कुकर्म''', false, '6101b858-a1dd-43e5-a200-5eb49a419b69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59479f0d-5069-4308-b800-622a4c0ab328', '''कुपात्र''', false, '6101b858-a1dd-43e5-a200-5eb49a419b69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b70e6b9-2a25-4a0e-b364-0a783a2c4307', '''कुपुत्र''', false, '6101b858-a1dd-43e5-a200-5eb49a419b69');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d79c24e3-c922-44f1-86a8-011d4852b7b2', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', '''ऐतिहासिक'' और ''वैधानिक'' शब्दों में मूल शब्द और प्रत्यय क्या हैं?', '''इक'' प्रत्यय से इ→ऐ (इतिहास→ऐतिहासिक) तथा इ→ऐ (विधान→वैधानिक)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1523c7b6-ad02-469f-8f29-6e88462267dd', 'इतिहास + इक = ऐतिहासिक ; विधान + इक = वैधानिक', true, 'd79c24e3-c922-44f1-86a8-011d4852b7b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5da132c-d08c-41e9-870a-9651ca46c6f2', 'ऐतिहास + इक ; वैधान + इक', false, 'd79c24e3-c922-44f1-86a8-011d4852b7b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0d727d0-5f89-490d-bc16-565a27ca2487', 'इतिहास + क ; विधान + क', false, 'd79c24e3-c922-44f1-86a8-011d4852b7b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6eac8eed-4da9-49cf-9006-55616db0cab2', 'इति + हासिक ; वि + धानिक', false, 'd79c24e3-c922-44f1-86a8-011d4852b7b2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('95edf7be-6d08-4dd3-bdae-41cdb37ad610', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'निम्नलिखित में से किस शब्द में दो उपसर्गों का एक साथ प्रयोग हुआ है?', 'पर्यावरण = परि + आ + वरण (दो उपसर्ग); असुरक्षित = अ + सु + रक्षित (दो उपसर्ग)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73d8fcfc-e475-4248-a043-6c9afe4caff4', '''पर्यावरण'' (परि + आ + वरण = पर्यावरण) और ''असुरक्षित'' (अ + सु + रक्षित)', true, '95edf7be-6d08-4dd3-bdae-41cdb37ad610');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac466b53-1ea3-45e6-a4ea-11781a53406d', '''अतिवृष्टि''', false, '95edf7be-6d08-4dd3-bdae-41cdb37ad610');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffaeef66-f339-4008-a7ec-5f2b37b52470', '''दुर्लभ''', false, '95edf7be-6d08-4dd3-bdae-41cdb37ad610');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89b906ee-4043-416d-8af0-600fcbae803b', '''अनपढ़''', false, '95edf7be-6d08-4dd3-bdae-41cdb37ad610');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6385289b-f421-42ee-8eca-ae616c35eae0', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'निम्नलिखित में से किस शब्द में दो प्रत्ययों का एक साथ प्रयोग हुआ है?', 'राष्ट्र + ईय = राष्ट्रीय + ता = राष्ट्रीयता (दो तद्धित प्रत्ययों का क्रमिक संयोग)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b47e807a-5223-4741-b4f3-4e34825b63fe', '''राष्ट्रीयता'' (राष्ट्र + ईय [प्रत्यय 1] + ता [प्रत्यय 2] = राष्ट्रीयता)', true, '6385289b-f421-42ee-8eca-ae616c35eae0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b615c89-c9d0-4915-a51c-645654c10733', '''मानवता''', false, '6385289b-f421-42ee-8eca-ae616c35eae0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abac58c2-ae1c-4ce3-9d55-8d3e6ef35041', '''सुंदरता''', false, '6385289b-f421-42ee-8eca-ae616c35eae0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37edad9f-bb84-4022-ac95-2b40caee3d41', '''लिखाई''', false, '6385289b-f421-42ee-8eca-ae616c35eae0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('393a5ac0-c64e-4037-8a9a-421e17a135fe', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', '''सदाचार'' और ''सज्जन'' शब्दों में कौन-सा संस्कृत उपसर्ग प्रयुक्त हुआ है?', 'संस्कृत तत्सम उपसर्ग ''सत्'' (सत्+आचार=सदाचार, सत्+जन=सज्जन)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b331e5c-a822-47c6-992c-4e3921cac73a', '''सत्'' उपसर्ग (सत् + आचार = सदाचार ; सत् + जन = सज्जन)', true, '393a5ac0-c64e-4037-8a9a-421e17a135fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb338c69-7ca4-4a98-bae9-d04544e7c39e', '''सद्''', false, '393a5ac0-c64e-4037-8a9a-421e17a135fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('720a23cc-52bb-4ae2-81bb-2f344949574b', '''स''', false, '393a5ac0-c64e-4037-8a9a-421e17a135fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d6d29c1-a2a1-4897-b1f2-c4776ec533b9', '''सम्''', false, '393a5ac0-c64e-4037-8a9a-421e17a135fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('26d23a87-3bf7-4c3e-a5ab-2a4f0ee68bdc', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'उर्दू-फ़ारसी के उपसर्ग ''ना'' (अर्थ: अभाव/नहीं) से बने शब्दों का शुद्ध समूह कौन-सा है?', 'ना + लायक = नालायक; ना + पसंद = नापसंद; ना + बालिग = नाबालिग।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d2b0a53-c8cd-42c5-8f68-62f7445130df', 'नालायक, नापसंद, नादान, नाबालिग, नामुमकिन', true, '26d23a87-3bf7-4c3e-a5ab-2a4f0ee68bdc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22efecdd-576d-4e33-a820-93e8ef3766a2', 'नाता, नाग', false, '26d23a87-3bf7-4c3e-a5ab-2a4f0ee68bdc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b652fd15-7119-4933-b55b-e621706d0bbb', 'नान, नाशपाती', false, '26d23a87-3bf7-4c3e-a5ab-2a4f0ee68bdc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b34323d-cb05-458f-a7bb-978956986741', 'नारी, नाटक', false, '26d23a87-3bf7-4c3e-a5ab-2a4f0ee68bdc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('317995fb-47e1-48e5-b6e2-4bc08d5313ce', 'Class 7', 'Hindi Grammar', 'Chapter 4: उपसर्ग और प्रत्यय', 'Hard', 'उपसर्ग और प्रत्यय (Affixation) के सम्यक अध्ययन का हिंदी भाषा की शब्द-रचना में क्या सर्वोच्च योगदान है?', 'उपसर्ग और प्रत्यय शब्द-निर्माण की सर्वाधिक उर्वर रचनात्मक प्रविधियाँ हैं जो भाषा की शब्द-संपदा का असीमित विस्तार करती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d6ec0a1-2362-40bf-be94-5ccff5f91f90', 'यह सीमित मूल शब्दों से सहस्रों नवीन, सूक्ष्म, भावपूर्ण और पारिभाषिक शब्दों के सृजन की अद्भुत वैज्ञानिक सामर्थ्य प्रदान करता है, जिससे भाषा का शब्द-भंडार अनंत रूप से समृद्ध होता है', true, '317995fb-47e1-48e5-b6e2-4bc08d5313ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2c118b5-dd96-4f1a-8138-9a38f75e8f2a', 'यह शब्दों को छोटा करने का एकमात्र तरीका है', false, '317995fb-47e1-48e5-b6e2-4bc08d5313ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56be05ab-60e1-4031-9360-c9f1e7b430d4', 'इसका व्याकरण में कोई विशेष प्रयोग नहीं है', false, '317995fb-47e1-48e5-b6e2-4bc08d5313ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('703a1d8b-71bc-4cd6-aa79-9889be39d31d', 'यह केवल परीक्षा में एक अंक के लिए पढ़ा जाता है', false, '317995fb-47e1-48e5-b6e2-4bc08d5313ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('df36322e-3008-4355-8e40-6b6c31100b2a', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'A change in which a substance undergoes a change in its physical properties (shape, size, color, or state) WITHOUT the formation of any new chemical substance is called a:', 'Physical changes alter physical dimensions or phase state without altering chemical composition or forming new molecular species.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('684386ff-154a-432f-b64e-a4eff0e820d9', 'Physical Change', true, 'df36322e-3008-4355-8e40-6b6c31100b2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('944d98fa-00d6-413c-976c-ba405589f0a9', 'Chemical Change', false, 'df36322e-3008-4355-8e40-6b6c31100b2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('179c69b8-8c6d-498d-b396-bd052d63a990', 'Rusting', false, 'df36322e-3008-4355-8e40-6b6c31100b2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85447b93-cee3-4cde-b949-b7b77805ebc6', 'Neutralization', false, 'df36322e-3008-4355-8e40-6b6c31100b2a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9b81843-a84d-4dc0-a1c5-1f46f595c17b', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'A change in which one or more completely NEW substances with entirely different chemical properties are formed is called a:', 'A chemical change involves rearrangement of chemical bonds yielding distinct product substances.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46d599c7-e816-4954-a72f-fdc697c7d921', 'Chemical Change (Chemical Reaction)', true, 'f9b81843-a84d-4dc0-a1c5-1f46f595c17b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('867a82a5-4a0d-45f6-a7a9-d2b5ff45f7db', 'Physical Change', false, 'f9b81843-a84d-4dc0-a1c5-1f46f595c17b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d330766-63fb-484a-ae93-493d590d814f', 'Melting', false, 'f9b81843-a84d-4dc0-a1c5-1f46f595c17b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6351447-e051-4a88-bb96-42707845cd50', 'Evaporation', false, 'f9b81843-a84d-4dc0-a1c5-1f46f595c17b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f20ed121-52af-4a7a-9402-2ca82a698f7a', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'Which of the following is an example of a REVERSIBLE PHYSICAL CHANGE?', 'Melting of ice is a reversible physical phase transition (H₂O solid ⇌ H₂O liquid).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('241b26b0-2118-4124-a343-a2479e245be0', 'Melting of Ice into Water', true, 'f20ed121-52af-4a7a-9402-2ca82a698f7a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f15bcdea-e026-48da-8be0-eff67569b189', 'Burning of paper into ash', false, 'f20ed121-52af-4a7a-9402-2ca82a698f7a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4809190b-13a9-428f-ab05-408c9f4d79e3', 'Rusting of iron', false, 'f20ed121-52af-4a7a-9402-2ca82a698f7a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa8a6604-6531-4061-94fe-a469a77dad5c', 'Cooking of food', false, 'f20ed121-52af-4a7a-9402-2ca82a698f7a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56fc2df3-5cff-43bc-a581-85d12a6473f4', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'What white powdery substance is formed when a Magnesium ribbon is burned in air with a dazzling white flame?', 'Magnesium reacts vigorously with atmospheric oxygen to produce Magnesium Oxide powder: 2Mg + O₂ → 2MgO.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a31b05c9-8feb-4b40-9b4d-effc595e6fb5', 'Magnesium Oxide (MgO)', true, '56fc2df3-5cff-43bc-a581-85d12a6473f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1178d62-7d00-4bc3-ba58-03c91cd459d8', 'Magnesium Hydroxide', false, '56fc2df3-5cff-43bc-a581-85d12a6473f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4856bf7-5a09-4c8f-b9d5-7148c9ad1b64', 'Magnesium Chloride', false, '56fc2df3-5cff-43bc-a581-85d12a6473f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8097bd1-91a3-4762-b03a-ba968961395b', 'Magnesium Carbonate', false, '56fc2df3-5cff-43bc-a581-85d12a6473f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6a4ff775-fa50-477b-908f-c3d352597635', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'What new chemical substance is formed when Magnesium Oxide ash (MgO) is dissolved thoroughly in water?', 'MgO + H₂O → Mg(OH)₂ (a basic metal hydroxide turning red litmus blue).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a405e0e-c563-4496-b5fc-6f5548d6dfed', 'Magnesium Hydroxide [Mg(OH)₂] - which turns Red Litmus paper BLUE (Basic in nature)', true, '6a4ff775-fa50-477b-908f-c3d352597635');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2b15232-9366-4b44-b6a4-25f867f1f741', 'Hydrochloric acid', false, '6a4ff775-fa50-477b-908f-c3d352597635');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4ae5c45-1025-41b3-8401-80ac37cb4f80', 'Magnesium metal', false, '6a4ff775-fa50-477b-908f-c3d352597635');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4e42d6f-44b8-484d-8cb4-f3871b3391d6', 'Hydrogen gas', false, '6a4ff775-fa50-477b-908f-c3d352597635');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2274dd52-c347-4087-bbcb-49c96ed1b1e0', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'What two essential conditions are mandatory for the RUSTING of Iron to occur?', 'Rusting of iron is an electrochemical corrosion process requiring simultaneous exposure to oxygen and moisture: 4Fe + 3O₂ + xH₂O → 2Fe₂O₃·xH₂O.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('367bea48-6794-4107-8979-acf19cdbde1f', 'Both Oxygen (air) and Water (or moisture/water vapor)', true, '2274dd52-c347-4087-bbcb-49c96ed1b1e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d5b9e88-b905-4aaa-b00b-e0fe6bc53a88', 'Only dry oxygen', false, '2274dd52-c347-4087-bbcb-49c96ed1b1e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49388424-db06-4799-a0d1-9bbfa3653228', 'Only water without air', false, '2274dd52-c347-4087-bbcb-49c96ed1b1e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d83f466-29d0-4e89-82ce-c7fe38b77797', 'Only sunlight', false, '2274dd52-c347-4087-bbcb-49c96ed1b1e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c143979b-e0b7-4932-b1be-ff8770dc9e71', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'The industrial process of depositing a protective thin layer of metal ZINC on iron objects to prevent rusting is called:', 'Galvanization coats ferrous metals with sacrificial zinc to shield against moisture and oxygen.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e8a6098-d54d-49ff-8155-3f11f19eb328', 'Galvanization', true, 'c143979b-e0b7-4932-b1be-ff8770dc9e71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81612aff-15ad-4ed1-a98f-74992d87e638', 'Crystallization', false, 'c143979b-e0b7-4932-b1be-ff8770dc9e71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62370574-06bd-467e-9ddb-eee0ee94f5df', 'Neutralization', false, 'c143979b-e0b7-4932-b1be-ff8770dc9e71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f5e91bf-1fa0-457c-8111-883c6e7188e2', 'Vulcanization', false, 'c143979b-e0b7-4932-b1be-ff8770dc9e71');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e16f41f-dbf8-49d7-9aa6-fa87b5cdd0f5', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'What is Stainless Steel made of that gives it permanent resistance to rusting?', 'Stainless steel is a corrosion-resistant alloy of iron, carbon, chromium (≥10.5%), nickel, and manganese forming a self-healing passive oxide film.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66c8b923-a138-49ed-b5e1-a7bdbf30703c', 'Iron mixed/alloyed with Carbon and metals like Chromium, Nickel, and Manganese', true, '8e16f41f-dbf8-49d7-9aa6-fa87b5cdd0f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e03792d2-fcbe-46dc-9373-7cdc78d9c940', 'Pure gold', false, '8e16f41f-dbf8-49d7-9aa6-fa87b5cdd0f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34d58fc7-e2ac-41fb-8da9-2a1637f2a4f1', 'Iron painted with white plastic', false, '8e16f41f-dbf8-49d7-9aa6-fa87b5cdd0f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65e70b1f-96af-4afa-94dd-94aaa90088fe', 'Pure aluminum', false, '8e16f41f-dbf8-49d7-9aa6-fa87b5cdd0f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('637a0fa2-cdd4-4cbf-a78c-be23868166ef', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'The physical purification process of obtaining large, pure geometric crystals of a substance (such as Copper Sulphate) from its saturated hot solution is called:', 'Crystallization is a physical separation and purification technique yielding highly ordered crystalline solids.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d48cef1b-05fc-47a1-ac4a-d5d28f034b78', 'Crystallization', true, '637a0fa2-cdd4-4cbf-a78c-be23868166ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddae62ff-e893-4ec2-88bc-7d6d1652abc0', 'Evaporation', false, '637a0fa2-cdd4-4cbf-a78c-be23868166ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96a55248-ebb7-47f1-be2d-a03a15740798', 'Sedimentation', false, '637a0fa2-cdd4-4cbf-a78c-be23868166ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24c97128-27f2-4f53-b161-62bd518fc5ce', 'Condensation', false, '637a0fa2-cdd4-4cbf-a78c-be23868166ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7095a40d-0ec4-4634-943c-c6e7b737344f', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'What gas turns clear Lime Water milky when passed through it?', 'CO₂ reacts with lime water [Ca(OH)₂] to precipitate insoluble white Calcium Carbonate (CaCO₃), turning the solution milky.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0a334c4-b19f-468e-a0eb-6405caaa25b2', 'Carbon Dioxide (CO₂)', true, '7095a40d-0ec4-4634-943c-c6e7b737344f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2dfba1a-3d39-43fd-b4f1-818860ec2bfa', 'Oxygen (O₂)', false, '7095a40d-0ec4-4634-943c-c6e7b737344f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('723afd00-e21e-48e9-beaf-4bd033550731', 'Nitrogen (N₂)', false, '7095a40d-0ec4-4634-943c-c6e7b737344f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7816578c-af30-4de0-b77f-40c592a6a8e1', 'Hydrogen (H₂)', false, '7095a40d-0ec4-4634-943c-c6e7b737344f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2254854-85ea-4a51-ae09-c64a2962ef71', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'When an iron nail is dropped into a blue Copper Sulphate solution (CuSO₄), why does the solution color turn GREEN after an hour?', 'Single displacement reaction: Fe + CuSO₄ (blue) → FeSO₄ (green) + Cu (reddish-brown deposit on nail).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb37d50e-d009-42b6-b219-fc0d1fbb727d', 'Iron is more reactive than copper and displaces it, forming green Iron Sulphate (FeSO₄) solution', true, 'c2254854-85ea-4a51-ae09-c64a2962ef71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a5be852-3833-4ebb-bf02-fab6c59f9203', 'Because the nail absorbs all blue paint', false, 'c2254854-85ea-4a51-ae09-c64a2962ef71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b97d9ef-8bdf-4b80-9837-52575a5e2bd8', 'Because algae grows inside the water', false, 'c2254854-85ea-4a51-ae09-c64a2962ef71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17962e97-dd14-4dc7-a250-249bb812e941', 'Because copper turns green', false, 'c2254854-85ea-4a51-ae09-c64a2962ef71');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73cc6aff-b2cb-4b1c-9f9e-2cda2d4a3567', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Easy', 'What color is the thin metal coating deposited on the iron nail in the Copper Sulphate experiment?', 'Elemental metallic copper (Cu) precipitates as a fine reddish-brown coating on the submerged iron nail.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce4d03b0-2b9d-4a20-85ae-48a904bf3e99', 'Brown / Reddish-brown (pure metallic Copper)', true, '73cc6aff-b2cb-4b1c-9f9e-2cda2d4a3567');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34fbdada-f74a-4a6d-bad7-7265502d68c8', 'Silver', false, '73cc6aff-b2cb-4b1c-9f9e-2cda2d4a3567');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('820c89ba-c45d-4cfd-8a91-122041eade38', 'Yellow', false, '73cc6aff-b2cb-4b1c-9f9e-2cda2d4a3567');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2758405b-6944-42a2-95bf-7e428662471c', 'Black', false, '73cc6aff-b2cb-4b1c-9f9e-2cda2d4a3567');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3a91883b-ff48-4ea8-8483-6ecc40e47813', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why is the BURNING of a candle considered BOTH a Physical Change and a Chemical Change simultaneously?', 'Dual phenomenon: phase transition of solid wax to liquid wax is physical; exothermic hydrocarbon combustion is chemical.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53c0976b-a473-480f-8229-f8e6de23a347', 'Melting and solidification of wax is a Physical Change ; while burning of molten wax vapor in air to produce CO₂, water vapor, heat, and light is a Chemical Change', true, '3a91883b-ff48-4ea8-8483-6ecc40e47813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd1221a6-5adf-4feb-96dd-b1eb5955f7bf', 'Because the thread grows longer', false, '3a91883b-ff48-4ea8-8483-6ecc40e47813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('900c9cdc-ec68-4358-8336-7835cbb8a5c8', 'Because the glass melts', false, '3a91883b-ff48-4ea8-8483-6ecc40e47813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5c98cb4-0ae4-4252-96bb-a2651982e71e', 'Because wax turns into water', false, '3a91883b-ff48-4ea8-8483-6ecc40e47813');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('768d69e7-6cc7-4897-ad58-0ec8ba48f556', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why do iron ships, bridges, and metal structures rust MUCH FASTER in coastal marine environments (near the sea) than in inland dry areas?', 'Saline marine electrolyte solutions increase ionic conductivity, accelerating galvanic redox corrosion of iron.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('902dbe2b-9a89-4653-8b79-ed7d21c6fc1e', 'Seawater contains high concentrations of dissolved mineral SALTS (NaCl) which act as an electrolyte, dramatically accelerating the electrochemical rate of rust formation', true, '768d69e7-6cc7-4897-ad58-0ec8ba48f556');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd1acd57-a382-4090-8ad3-655769d244ec', 'Because sea fish eat the iron', false, '768d69e7-6cc7-4897-ad58-0ec8ba48f556');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fa701c2-1795-481f-9d3f-0aa1cb453e22', 'Because sea water is colder', false, '768d69e7-6cc7-4897-ad58-0ec8ba48f556');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('beadf9f3-237f-4ceb-b8a5-4f961610799b', 'Because ships move faster in oceans', false, '768d69e7-6cc7-4897-ad58-0ec8ba48f556');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91ebb280-2299-4038-a853-e747f1bd5b34', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'What happens when Baking Soda (Sodium Hydrogen Carbonate) is mixed with Vinegar (Acetic Acid) in a test tube, and the resulting gas is bubbled into Lime Water?', 'Effervescence of CO₂: NaHCO₃ + CH₃COOH → CH₃COONa + H₂O + CO₂↑. CO₂ + Ca(OH)₂ → CaCO₃↓ (milky) + H₂O.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99663b28-7509-4611-8812-0417ea17f1b1', 'A vigorous hissing sound produces Carbon Dioxide (CO₂) gas ; when bubbled through lime water, it forms insoluble white Calcium Carbonate (CaCO₃), making it MILKY', true, '91ebb280-2299-4038-a853-e747f1bd5b34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('316238e7-0c80-43ec-8184-038293bbb1d8', 'The test tube turns into ice', false, '91ebb280-2299-4038-a853-e747f1bd5b34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('486f008f-a02d-45fb-87c7-afe113ecf733', 'Lime water turns bright yellow', false, '91ebb280-2299-4038-a853-e747f1bd5b34');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd2b5dd9-7878-49e9-a53b-07232b735879', 'No gas is produced', false, '91ebb280-2299-4038-a853-e747f1bd5b34');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('879424bd-b588-4e41-a190-4efffa2adc8b', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why is the Digestion of food inside our alimentary canal classified strictly as a Chemical Change?', 'Enzymatic hydrolysis breaks covalent macromolecular bonds, producing irreversible monomer biochemical entities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e229257b-8273-47f7-94c4-4545849067a9', 'Digestive enzymes chemically hydrolyze complex starch, proteins, and fats into entirely new, simpler absorbable monomer molecules (glucose, amino acids) that cannot be reversed back into food', true, '879424bd-b588-4e41-a190-4efffa2adc8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e08595a9-a5f2-4a56-9553-211f4677cb88', 'Because food just gets chewed smaller', false, '879424bd-b588-4e41-a190-4efffa2adc8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f4e9384-2686-4660-b2db-8aa9253306d1', 'Because water dissolves food physically', false, '879424bd-b588-4e41-a190-4efffa2adc8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44c9ef04-31a9-4a50-a04e-300e7507e8bb', 'Because the stomach is a blender', false, '879424bd-b588-4e41-a190-4efffa2adc8b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2efc863b-24c5-4e31-99f1-13af203e7d0a', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why does a freshly cut slice of an Apple or Brinjal (Eggplant) turn BROWN when left exposed to air for a few minutes?', 'Enzymatic browning: polyphenol oxidases catalyze oxidation of phenolic compounds into quinones and melanin pigments.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a42f502-5186-437e-99be-33b64ef50f43', 'Polyphenol oxidase enzymes inside the apple react with atmospheric oxygen to form brown melanin pigments in an irreversible oxidation chemical reaction', true, '2efc863b-24c5-4e31-99f1-13af203e7d0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17c2b9fa-3ca9-4d7a-9e52-dea793886b7b', 'Dust settles on the apple', false, '2efc863b-24c5-4e31-99f1-13af203e7d0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd302963-6fc4-43fa-9207-a20875c0d6db', 'The apple loses water and shrinks', false, '2efc863b-24c5-4e31-99f1-13af203e7d0a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca9493f1-2f57-49fc-8a8f-96344106f1ab', 'The apple turns into wood', false, '2efc863b-24c5-4e31-99f1-13af203e7d0a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b0a9623-296c-4187-ac9d-3df8b1f9457b', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'What observable accompanying signs typically indicate that a Chemical Reaction has occurred?', 'Enthalpy changes, gas evolution, chromophoric shifts, odor generation, and precipitation characterize chemical changes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7e9d4a1-cc1b-4db0-b71d-dd044757d452', 'Evolution of gas, production of heat/light/sound, noticeable change in color, emission of a new smell, or formation of a precipitate', true, '1b0a9623-296c-4187-ac9d-3df8b1f9457b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cea5be75-1612-48cf-a7b0-33a6e2a3adbc', 'Only change in size', false, '1b0a9623-296c-4187-ac9d-3df8b1f9457b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b0f1e44-ac3b-46cd-aa37-790ab8f5f538', 'Only change in temperature without any new substance', false, '1b0a9623-296c-4187-ac9d-3df8b1f9457b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf1e1fdf-c622-49fe-b173-917c417eea0e', 'The substance becomes invisible', false, '1b0a9623-296c-4187-ac9d-3df8b1f9457b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf70cc47-0c2c-41ff-bcbf-f1a3008a432b', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why is Photosynthesis in green plants classified as a Chemical Change?', '6CO₂ + 6H₂O + hν → C₆H₁₂O₆ + 6O₂ (anabolic synthesis of new carbohydrates).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('691805af-d18e-4653-b475-4acf1397a980', 'Carbon dioxide and water react in the presence of chlorophyll and sunlight to synthesize an entirely new chemical substance (Glucose) and release Oxygen gas', true, 'cf70cc47-0c2c-41ff-bcbf-f1a3008a432b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47324040-12a8-4269-b95b-6e7c3811edac', 'Because leaves stay green', false, 'cf70cc47-0c2c-41ff-bcbf-f1a3008a432b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('196c66b3-626f-4041-bb7d-efc5fd937673', 'Because sunlight warms the leaves physically', false, 'cf70cc47-0c2c-41ff-bcbf-f1a3008a432b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('177e9a23-15d7-4a24-bde5-42c875c27743', 'Because water evaporates from leaves', false, 'cf70cc47-0c2c-41ff-bcbf-f1a3008a432b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('40ce003c-fd7a-4830-89be-7ea32f837855', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why is cutting a log of wood into small pieces a PHYSICAL change, while burning that wood is a CHEMICAL change?', 'Mechanical severance preserves cellulose chemistry (physical); pyrolytic combustion oxidizes organic polymers into CO₂ and minerals (chemical).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86372c75-5d68-4ebd-889f-369f86e5f091', 'Cutting alters only size/shape without making a new substance ; burning reacts with oxygen to form ash, smoke, CO₂, and heat, which cannot be reversed', true, '40ce003c-fd7a-4830-89be-7ea32f837855');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08028690-5b95-4a02-9590-faf4ed7b0cde', 'Cutting makes new wood', false, '40ce003c-fd7a-4830-89be-7ea32f837855');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56b87ce7-d1b1-428e-a6b9-15155936ef2e', 'Burning is reversible', false, '40ce003c-fd7a-4830-89be-7ea32f837855');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92a98373-aff3-4ec6-a377-bfa433ed0295', 'Both are physical changes', false, '40ce003c-fd7a-4830-89be-7ea32f837855');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9fb46cfc-9ae0-45ac-9eb1-b011bec93273', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'What protective role does the Ozone Layer (O₃) in the stratosphere play by undergoing a continuous chemical change?', 'Photochemical Chapman cycle: O₃ + UV photon → O₂ + O· (absorbing lethal UV-B/UV-C radiation).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('391d8eb1-2fef-4338-b212-43bcfaa785f3', 'It absorbs harmful high-energy Ultraviolet (UV) radiation from the Sun and breaks down into Oxygen (O₂); absorbing UV prevents skin cancer and cataracts', true, '9fb46cfc-9ae0-45ac-9eb1-b011bec93273');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4c615d0-b889-4af3-b2e3-6dfa4671f65e', 'It makes the sky blue', false, '9fb46cfc-9ae0-45ac-9eb1-b011bec93273');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('791f41d4-0a76-46d4-b5fa-cbee1f0ffe2d', 'It brings rain clouds', false, '9fb46cfc-9ae0-45ac-9eb1-b011bec93273');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ad78ca9-903c-491d-bcf2-6dd629365e0c', 'It keeps the Earth warm by burning', false, '9fb46cfc-9ae0-45ac-9eb1-b011bec93273');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('79d4a8a8-1b89-499e-ab2d-b0f06adbd8fc', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why is the explosion of a Firecracker considered a Chemical Change?', 'Exothermic deflagration of oxidizers (KNO₃) and fuels (S, C) produces light, shockwaves, and gaseous products.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed94eea9-b3b8-46d0-bc8f-c906fbcaefb8', 'Gunpowder and chemicals react rapidly with oxygen, producing heat, brilliant light, explosive sound, and unpleasant sulfur gases', true, '79d4a8a8-1b89-499e-ab2d-b0f06adbd8fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ad6b093-0271-4935-986c-a089a3bbb302', 'Because firecrackers can be re-exploded', false, '79d4a8a8-1b89-499e-ab2d-b0f06adbd8fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('526307b8-f76e-43a0-86d3-a898b221091b', 'Because firecrackers change only shape', false, '79d4a8a8-1b89-499e-ab2d-b0f06adbd8fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05f5d7e1-887c-4e45-857b-075aa7a69247', 'Because firecrackers turn into water', false, '79d4a8a8-1b89-499e-ab2d-b0f06adbd8fc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c169ed66-e231-47c7-922c-0d2b27e0cf8a', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'How can Copper Sulphate crystals be prepared in the laboratory?', 'Supersaturation crystallization: dissolving solute at elevated temperature and slow cooling precipitates pure CuSO₄·5H₂O crystals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23854658-9888-49b9-a56c-d5182322d87a', 'Boil water, add dilute Sulfuric acid, slowly stir in Copper Sulphate powder until no more dissolves (saturated), filter while hot, and let it cool undisturbed to form blue crystals', true, 'c169ed66-e231-47c7-922c-0d2b27e0cf8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd794337-87ea-4957-a0f7-1a020bf05fe9', 'Mix copper with cold tap water', false, 'c169ed66-e231-47c7-922c-0d2b27e0cf8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82303f4e-2e05-44f9-9f3e-4e3c9c0fc493', 'Burn copper metal over a flame', false, 'c169ed66-e231-47c7-922c-0d2b27e0cf8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b8a4487-723e-43db-90f2-c6be05dbfa09', 'Freeze copper in ice', false, 'c169ed66-e231-47c7-922c-0d2b27e0cf8a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8f81291-9079-4483-a4a9-389c7e48a17e', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why is tearing a piece of paper into 100 tiny pieces classified as a Physical Change?', 'Mechanical subdivision alters surface area and macroscopic geometry while molecular cellulose composition remains intact.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d9c846c-3ffe-4fe4-87f3-cde2ce0f9a57', 'Each tiny scrap is still chemically made of the exact same Cellulose fibers; no new chemical substance is formed', true, 'c8f81291-9079-4483-a4a9-389c7e48a17e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('836dc63b-edc7-4a2e-8d4e-83b3deaced2a', 'Because the scraps can be glued back', false, 'c8f81291-9079-4483-a4a9-389c7e48a17e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de8d86c4-e7c0-4f44-b4bd-c4429204f8d5', 'Because the paper disappears', false, 'c8f81291-9079-4483-a4a9-389c7e48a17e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0466fc73-cafd-4d67-a556-3a1b125b5b27', 'Because paper turns into plastic', false, 'c8f81291-9079-4483-a4a9-389c7e48a17e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38d7e23c-0282-4cb9-b21f-5cf82c584408', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'What is the chemical formula of Rust formed on iron?', 'Rust is porous, reddish-brown hydrated ferric oxide: Fe₂O₃·xH₂O.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c3443ef-9642-4803-953b-2677d6c343a3', 'Hydrated Iron(III) Oxide [Fe₂O₃·xH₂O]', true, '38d7e23c-0282-4cb9-b21f-5cf82c584408');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b84a578-756a-486d-93a5-9f047a6d0cdf', 'Iron Sulphide [FeS]', false, '38d7e23c-0282-4cb9-b21f-5cf82c584408');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55eb1049-3d8a-4817-b016-0bcd84c5d468', 'Iron Carbonate [FeCO₃]', false, '38d7e23c-0282-4cb9-b21f-5cf82c584408');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cd2faa6-7e1a-4878-a123-21b3d61124e8', 'Iron Hydroxide only [Fe(OH)₂]', false, '38d7e23c-0282-4cb9-b21f-5cf82c584408');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74d29838-287f-449f-b2f4-984e6290dc07', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why are overhead water transmission pipes and iron railings in houses galvanized?', 'Galvanized zinc provides a physical barrier and sacrificial anodic protection against rusting.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1453ff4-1d10-41db-a6bc-f413a20f5402', 'The zinc coating prevents direct contact of iron with atmospheric oxygen and water, preventing rust corrosion', true, '74d29838-287f-449f-b2f4-984e6290dc07');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('543fad1d-5036-4ecb-baa2-3e8d492a91eb', 'To make water flow faster', false, '74d29838-287f-449f-b2f4-984e6290dc07');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('996330c3-c16a-49d1-874e-666cff7c89e0', 'To make pipes look shiny', false, '74d29838-287f-449f-b2f4-984e6290dc07');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47b8b130-9eb4-406d-bfda-fa56201b4900', 'To heat the water', false, '74d29838-287f-449f-b2f4-984e6290dc07');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14a76496-cb8d-444c-b0fc-90e3cfab167a', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'Why does blowing breath through a straw into lime water turn it milky faster than letting it sit in open air?', 'Exhaled metabolic CO₂ (~40,000 ppm) rapidly precipitates calcium carbonate in Ca(OH)₂ solution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fa5caa7-7c3e-4d04-89ad-fe9cb1e8ae29', 'Exhaled human breath contains a much higher concentration of Carbon Dioxide (~4% CO₂) than ambient atmospheric air (~0.04% CO₂)', true, '14a76496-cb8d-444c-b0fc-90e3cfab167a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37899b79-3995-40bf-b5a1-23852b4fcc22', 'Exhaled breath contains water', false, '14a76496-cb8d-444c-b0fc-90e3cfab167a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75a535b8-a86f-4d9a-98fa-0472c60c7a3b', 'Exhaled breath is hot', false, '14a76496-cb8d-444c-b0fc-90e3cfab167a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96260e0c-3df2-4d81-9885-40783869e7da', 'Exhaled breath contains oxygen', false, '14a76496-cb8d-444c-b0fc-90e3cfab167a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10dae0a7-0a10-485e-b088-3e95ee7544f5', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Medium', 'What happens when glowing red-hot charcoal reacts with air?', 'C(s) + O₂(g) → CO₂(g) + ΔH (exothermic chemical combustion).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1786c0bb-9602-46fb-822f-c84211800deb', 'Carbon in charcoal combusts with oxygen to produce Carbon Dioxide gas (CO₂), heat, and light: C + O₂ -> CO₂ (Chemical Change)', true, '10dae0a7-0a10-485e-b088-3e95ee7544f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07f05d1e-d318-4c6f-bab2-daf8480e7c1e', 'It turns into pure water', false, '10dae0a7-0a10-485e-b088-3e95ee7544f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a03c9f7d-fc75-4350-9844-3c59c4c52899', 'It becomes colder', false, '10dae0a7-0a10-485e-b088-3e95ee7544f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('384c7fb6-8f8b-47cb-856e-01e66d5eeedd', 'It changes only into ice', false, '10dae0a7-0a10-485e-b088-3e95ee7544f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0de62a7c-1400-41e0-b02e-c2ef05f66efb', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db19f6c4-743a-4a45-b40a-8501a1a0b178', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '0de62a7c-1400-41e0-b02e-c2ef05f66efb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abf998d3-686b-4851-b2a7-6189efe9267a', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '0de62a7c-1400-41e0-b02e-c2ef05f66efb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1079e26d-57d5-4583-92a1-115d89fa7357', '(A) is true, but (R) is false.', false, '0de62a7c-1400-41e0-b02e-c2ef05f66efb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('433b2ace-5d42-4078-8dfd-edb5346691d4', '(A) is false, but (R) is true.', false, '0de62a7c-1400-41e0-b02e-c2ef05f66efb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('60a08e0f-a51b-4045-a2f6-5edd03e3e60a', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'Spot the IMPOSTER in the following group of Changes and their scientific classifications:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb9706a9-310c-43d7-ae49-52dc3595c932', 'Change 1', false, '60a08e0f-a51b-4045-a2f6-5edd03e3e60a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b912c2bd-c544-4a63-80dc-653ecec2dd43', 'Change 2', false, '60a08e0f-a51b-4045-a2f6-5edd03e3e60a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96de7880-c1cb-4179-aea2-c1f60761bfb0', 'Change 3', false, '60a08e0f-a51b-4045-a2f6-5edd03e3e60a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9aafe92f-21c3-46b0-aa0c-1e9f1b89b6d6', 'Change 4 (Photosynthesis is a profound CHEMICAL CHANGE, not a physical change)', true, '60a08e0f-a51b-4045-a2f6-5edd03e3e60a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9443b90c-9c05-4280-8abe-9f527860ad53', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'In the reaction between Copper Sulphate and Iron:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bae08e43-ee16-4609-b2d2-87f4c0113b10', 'Single Displacement (Redox) Reaction: Iron is more electrochemically reactive than copper, so it loses electrons and displaces copper from its sulfate solution', true, '9443b90c-9c05-4280-8abe-9f527860ad53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62e75863-7821-4329-83e6-9d72b7b50909', 'Double Decomposition Reaction', false, '9443b90c-9c05-4280-8abe-9f527860ad53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14638b82-965f-43c2-a45f-6e73949064c3', 'Neutralization Reaction', false, '9443b90c-9c05-4280-8abe-9f527860ad53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f52eeff-252c-4600-a0e0-ec9d73e43e22', 'Physical Phase Change', false, '9443b90c-9c05-4280-8abe-9f527860ad53');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b1bb939e-2bb8-4f88-ac0b-ef316f87f83e', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'Match Column I (Chemical Processes) with Column II (Essential Chemical Equations):
(a) Burning of Magnesium ribbon  -> (i) 2Mg + O₂ -> 2MgO
(b) Making Milk of Magnesia      -> (ii) MgO + H₂O -> Mg(OH)₂
(c) Lime water turning milky     -> (iii) CO₂ + Ca(OH)₂ -> CaCO₃ + H₂O
(d) Iron rusting                 -> (iv) 4Fe + 3O₂ + 2xH₂O -> 2Fe₂O₃·xH₂O', 'Exact stoichiometric equations for the four foundational chemical reactions studied in Class 7 Chapter 5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7664a27-eb17-444a-93b6-c9fc054ba2cc', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'b1bb939e-2bb8-4f88-ac0b-ef316f87f83e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7fa4e3c-2b72-43c5-ad11-004d00d810ca', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'b1bb939e-2bb8-4f88-ac0b-ef316f87f83e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28e9feeb-1143-4ad5-9a60-309659639951', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'b1bb939e-2bb8-4f88-ac0b-ef316f87f83e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4892cc8f-7805-46f3-9679-13630f1303c6', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'b1bb939e-2bb8-4f88-ac0b-ef316f87f83e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d1117f5-d1fb-49dd-9146-3330f15ad9a2', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'Read the statements regarding physical and chemical changes:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad189bc7-af4a-426d-974e-8ceda69bec2b', 'Statements 1 and 2 only', true, '0d1117f5-d1fb-49dd-9146-3330f15ad9a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('337a81ab-d276-40ba-810f-31e24f2b2329', 'Statements 2 and 3 only', false, '0d1117f5-d1fb-49dd-9146-3330f15ad9a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d4ba9d2-b0e0-4cc4-8a77-2bb0ffa4f7d8', 'Statements 1 and 3 only', false, '0d1117f5-d1fb-49dd-9146-3330f15ad9a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef7de168-040d-47b7-af85-781f209f8774', 'All Statements 1, 2, and 3', false, '0d1117f5-d1fb-49dd-9146-3330f15ad9a2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4c2303c-e958-4efa-b5e4-d0d76df15479', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'Why does applying a coat of paint or grease on an iron object prevent rusting only as long as the paint layer remains intact?', 'Barrier coatings prevent contact between iron and ambient moisture/O₂; breaches initiate localized crevice corrosion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29b0b2e7-f69b-41a7-8c9e-5c9e14939d16', 'Paint acts as a physical barrier preventing atmospheric oxygen and moisture from contacting iron atoms; any scratch exposes iron, initiating rapid localized galvanic rusting', true, 'e4c2303c-e958-4efa-b5e4-d0d76df15479');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fccb3f4a-b3f6-47e5-94de-e18fa122dca9', 'Because paint kills bacteria', false, 'e4c2303c-e958-4efa-b5e4-d0d76df15479');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('325f9db4-099b-45db-a14b-c16d8690c5a5', 'Because paint turns iron into plastic', false, 'e4c2303c-e958-4efa-b5e4-d0d76df15479');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25ab7e6e-8627-4325-8ca5-68e4989eb55c', 'Because grease makes iron colder', false, 'e4c2303c-e958-4efa-b5e4-d0d76df15479');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3dd0fc09-4623-4e38-a875-0467ccd6c179', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'What is the crucial scientific difference between EVAPORATION (to dryness) and CRYSTALLIZATION when purifying dissolved solids?', 'Crystallization purifies by lattice exclusion (impurities remain in mother liquor), preventing thermal decomposition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7aaa07c-0ee6-4788-942a-6a83ef72dcc2', 'Evaporation to dryness can decompose heat-sensitive substances or leave soluble impurities mixed in ; Crystallization precipitates pure geometric crystals from cooled saturated solutions, leaving impurities in the mother liquor', true, '3dd0fc09-4623-4e38-a875-0467ccd6c179');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93a70cef-774d-4a42-9ec7-22bf6e6d433d', 'Evaporation produces crystals and crystallization produces steam', false, '3dd0fc09-4623-4e38-a875-0467ccd6c179');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('566d0cc9-dc28-4a57-847a-fdb95fc5a231', 'Crystallization is a chemical change while evaporation is not', false, '3dd0fc09-4623-4e38-a875-0467ccd6c179');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('684298ec-a06e-4655-bd75-eec9e1ee678f', 'There is no difference', false, '3dd0fc09-4623-4e38-a875-0467ccd6c179');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d839c5eb-abb0-4fea-bb52-6803b7cb6799', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'Consider four events:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5803c202-372b-4868-845f-4d3eb0bda892', 'Events 2 and 4 (Fermentation and Digestion)', true, 'd839c5eb-abb0-4fea-bb52-6803b7cb6799');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce41f7a4-d6e1-4752-a4ee-71ba52535d6f', 'Events 1 and 3', false, 'd839c5eb-abb0-4fea-bb52-6803b7cb6799');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36e236bb-f64a-4cc5-8176-1ef160658198', 'Events 1 and 2', false, 'd839c5eb-abb0-4fea-bb52-6803b7cb6799');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5afe5e16-98d7-42d0-9189-c040e63a3ca8', 'Events 3 and 4', false, 'd839c5eb-abb0-4fea-bb52-6803b7cb6799');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75ec30eb-4560-4793-b31a-1595371b913d', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'What happens when excess Carbon Dioxide gas is continuously bubbled into milky lime water for a prolonged duration?', 'CaCO₃ + H₂O + excess CO₂ → Ca(HCO₃)₂ (soluble calcium bicarbonate), clearing the milkiness.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b33d78f6-1d8c-45ab-be34-2cdce0707f44', 'The milkiness DISAPPEARS and the solution becomes completely clear again because insoluble Calcium Carbonate converts into soluble Calcium Hydrogen Carbonate [Ca(HCO₃)₂]', true, '75ec30eb-4560-4793-b31a-1595371b913d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a871b2b-71cd-4141-bec9-b977c4e5f225', 'The solution explodes', false, '75ec30eb-4560-4793-b31a-1595371b913d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49f055db-e246-4936-8084-f347d6742d67', 'The milkiness turns black', false, '75ec30eb-4560-4793-b31a-1595371b913d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c688c21b-32af-4b9e-aaf6-9684c90f0637', 'The solution freezes solid', false, '75ec30eb-4560-4793-b31a-1595371b913d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a30a30d-75a5-43bd-a211-7625cc69f20a', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'Why is the rusting of iron an electrochemical REDOX (Reduction-Oxidation) reaction?', 'Corrosion kinetics: Anodic oxidation Fe → Fe²⁺ + 2e⁻ coupled to cathodic reduction O₂ + 4H⁺ + 4e⁻ → 2H₂O.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c01be0d8-2e05-4f0b-bb84-5a425d13f7ab', 'Iron atoms lose electrons (Oxidation: Fe -> Fe²⁺ + 2e⁻) and atmospheric Oxygen molecules gain electrons in the presence of water (Reduction), forming hydrated iron oxide', true, '9a30a30d-75a5-43bd-a211-7625cc69f20a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acd3baf4-c8c5-498d-a0a9-337e413496b1', 'Iron gains protons from water', false, '9a30a30d-75a5-43bd-a211-7625cc69f20a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7cee7bc-2786-4e20-b5e8-1fae27319348', 'Oxygen turns into hydrogen', false, '9a30a30d-75a5-43bd-a211-7625cc69f20a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f604fafe-5b4c-4be2-a5b3-7c25bbde2a4f', 'Iron melts into liquid', false, '9a30a30d-75a5-43bd-a211-7625cc69f20a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0bee52a2-17f2-4d5e-96f2-ba58b0e518a5', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'What happens during the Sublimation of Camphor or Ammonium Chloride when heated in a china dish covered with an inverted glass funnel?', 'Sublimation is a physical phase transition: solid ⇌ vapor without passing through intermediate liquid state.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('612e3126-4f1b-4c4b-b7f4-d3b31ae256bb', 'Solid camphor changes directly into gas vapors upon heating without passing through the liquid phase, condensing back to pure solid crystals on the cool funnel neck (Physical Change)', true, '0bee52a2-17f2-4d5e-96f2-ba58b0e518a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e1f80d9-2b2a-4e08-ba19-e921686ffb3e', 'It burns into black ash permanently', false, '0bee52a2-17f2-4d5e-96f2-ba58b0e518a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c5f7f5c-8f61-489d-bf77-4538997ac50b', 'It turns into liquid water', false, '0bee52a2-17f2-4d5e-96f2-ba58b0e518a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e8c892b-a4fd-4792-a59c-ebcc8dcdb202', 'It reacts with glass to form acid', false, '0bee52a2-17f2-4d5e-96f2-ba58b0e518a5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94ec5173-43ea-43b2-98d3-05a9b852c8c8', 'Class 7', 'Science', 'Chapter 5: Physical and Chemical Changes', 'Hard', 'What comprehensive scientific principle summarizes Chapter 5 of NCERT Class 7 Science?', 'Chapter 5 integrates the molecular taxonomy of matter: phase transitions, stoichiometry of chemical reactions, corrosion mechanisms, and purification metallurgy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caab22ba-2228-4f37-af44-af30eafc8423', 'Matter undergoes physical transformations altering state and shape without changing chemical identity, alongside profound chemical reactions that synthesize new substances, drive biological metabolism, power metallurgy, and govern natural biogeochemical cycles', true, '94ec5173-43ea-43b2-98d3-05a9b852c8c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9acae8c-448b-49bb-8986-dcca30ced535', 'All physical changes are chemical changes', false, '94ec5173-43ea-43b2-98d3-05a9b852c8c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d660f97b-cdbd-4609-b3fb-e8f85af7dc78', 'Chemical reactions only happen in laboratories', false, '94ec5173-43ea-43b2-98d3-05a9b852c8c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b560fc2-957e-4a82-abc1-6c6ed7e0e088', 'Rusting can be prevented by heating iron to 1,000°C', false, '94ec5173-43ea-43b2-98d3-05a9b852c8c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e565a27-a830-47bf-ad72-8d4d96165799', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'When the sum of the measures of two angles is exactly 90°, the angles are called:', 'Two angles are complementary if their sum is 90° (∠A + ∠B = 90°).', NOW()) ON CONFLICT DO NOTHING;
