INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4baa5c0-dfd9-4e6f-8eaf-533bcf0e2993', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'Find the Complement of the angle 30°:', 'Complement = 90° - 30° = 60°.', NOW()) ON CONFLICT DO NOTHING;
