INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('634c77fa-d7f7-4edb-9667-b57fc799f8d9', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'An angle which is equal to its own Supplement is:', 'x + x = 180° → 2x = 180° → x = 90°.', NOW()) ON CONFLICT DO NOTHING;
