INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7891ab05-4228-4896-a26c-496a233f430a', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'When two lines intersect at a point, the vertically opposite angles formed are ALWAYS:', 'Vertically opposite angles formed by intersecting lines are congruent (equal in measure).', NOW()) ON CONFLICT DO NOTHING;
