INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37eff901-9ce8-4028-8bb1-8048193cb07a', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'A pair of adjacent angles whose non-common arms form a straight line (sum = 180°) is called a:', 'A linear pair consists of two adjacent angles whose sum is 180° on a straight line.', NOW()) ON CONFLICT DO NOTHING;
