INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b73f95e4-b492-4e60-ad29-52a5c4b8c184', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'If two parallel lines are cut by a transversal, each pair of Alternate Interior Angles is:', 'Alternate interior angles formed by parallel lines cut by a transversal are equal (Z-property).', NOW()) ON CONFLICT DO NOTHING;
