INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e95ccae4-3529-4a56-88e9-8308837d222c', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'If two parallel lines are cut by a transversal, each pair of Corresponding Angles is:', 'Corresponding angles situated in identical relative positions at each intersection are equal (F-property).', NOW()) ON CONFLICT DO NOTHING;
