INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53090996-88e4-4253-a98a-68c1848fd6c8', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Easy', 'If two parallel lines are cut by a transversal, the interior angles on the SAME SIDE of the transversal are:', 'Consecutive interior angles on the same side of a transversal intersecting parallel lines sum to 180° (C-property).', NOW()) ON CONFLICT DO NOTHING;
