INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc349433-8d9d-49c3-a443-fd48fd9339de', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'Two complementary angles are in the ratio 2 : 3. Find the measure of both angles:', '5x = 90° → x = 18°. Angles are 2(18) = 36° and 3(18) = 54°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('766967b4-49eb-41e6-98e1-957d61e86942', '36° and 54° (2x + 3x = 90° ⇒ 5x = 90° ⇒ x = 18° ⇒ 2(18) = 36°, 3(18) = 54°)', true, 'cc349433-8d9d-49c3-a443-fd48fd9339de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d11e2d8-9436-4462-afb2-6838dad0c850', '30° and 60°', false, 'cc349433-8d9d-49c3-a443-fd48fd9339de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccb319ce-29b5-4e4d-b0fe-61343ade92fa', '40° and 50°', false, 'cc349433-8d9d-49c3-a443-fd48fd9339de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d399d4a8-65f5-4319-8b2f-ed3bed4d7cdc', '20° and 70°', false, 'cc349433-8d9d-49c3-a443-fd48fd9339de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4fa9caa-258e-4304-850a-9e5b429f59a3', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'Two supplementary angles are in the ratio 4 : 5. Find the measure of the larger angle:', '9x = 180° → x = 20°. Larger angle = 5 × 20° = 100°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e53147de-9e3b-44b5-a84e-78d9ee8a58f5', '100° (4x + 5x = 180° ⇒ 9x = 180° ⇒ x = 20° ⇒ Larger = 5(20) = 100°)', true, 'f4fa9caa-258e-4304-850a-9e5b429f59a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff44e718-ab3c-4578-bdea-8fc8a619da11', '80°', false, 'f4fa9caa-258e-4304-850a-9e5b429f59a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0992f4c6-355e-4f5b-ac59-25ac9a7bfb87', '120°', false, 'f4fa9caa-258e-4304-850a-9e5b429f59a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a1e9667-0696-408a-8036-afa72b87cc4b', '90°', false, 'f4fa9caa-258e-4304-850a-9e5b429f59a3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88706623-9b0f-491b-baa2-cf6e7bdebcf0', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'An angle is 24° more than its Complement. Find the measure of the angle:', 'x - (90 - x) = 24 → 2x = 114 → x = 57° (Complement = 33°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('335d4c71-9b9d-4708-a8df-16e43a3f1aae', '57° (x = (90° - x) + 24° ⇒ 2x = 114° ⇒ x = 57°)', true, '88706623-9b0f-491b-baa2-cf6e7bdebcf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6630b336-5874-4cdf-a238-71aa5aa78d4d', '33°', false, '88706623-9b0f-491b-baa2-cf6e7bdebcf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('523b48a1-082f-4e8d-ab32-f3692afb7c14', '66°', false, '88706623-9b0f-491b-baa2-cf6e7bdebcf0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebb86448-7945-4752-a720-3fa32d82d438', '48°', false, '88706623-9b0f-491b-baa2-cf6e7bdebcf0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('24b3db09-5347-42b6-80b8-e56e559c2c6b', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'An angle is 44° less than its Supplement. Find the measure of the angle:', 'x = 180 - x - 44 → 2x = 136 → x = 68° (Supplement = 112°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cdaa7ed-6028-4534-961c-b352b9c1e14f', '68° (x = (180° - x) - 44° ⇒ 2x = 136° ⇒ x = 68°)', true, '24b3db09-5347-42b6-80b8-e56e559c2c6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c90adeee-fe49-4629-b09b-c7d96c6e02c1', '112°', false, '24b3db09-5347-42b6-80b8-e56e559c2c6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b551e01-8d2a-4271-815f-8d92aa9675b3', '72°', false, '24b3db09-5347-42b6-80b8-e56e559c2c6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19ded955-5294-4c85-8054-0d2b0cfd8732', '56°', false, '24b3db09-5347-42b6-80b8-e56e559c2c6b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('57cfe2cf-d701-4cb0-b3a6-5fadc60bb98c', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'Two lines AB and CD intersect at point O. If ∠AOC = 50°, find the measure of ∠BOD and ∠AOD:', 'Vertically opposite ∠BOD = ∠AOC = 50°. Linear pair ∠AOD = 180° - 50° = 130°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1d17edb-d9a1-42da-b451-c0610d2169f6', '∠BOD = 50° (vertically opposite) ; ∠AOD = 130° (linear pair: 180° - 50° = 130°)', true, '57cfe2cf-d701-4cb0-b3a6-5fadc60bb98c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9215c45d-5f1c-484a-a09f-b27b7ef822a4', '∠BOD = 130° ; ∠AOD = 50°', false, '57cfe2cf-d701-4cb0-b3a6-5fadc60bb98c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c0c89d3-b229-403d-963f-9a7a7e88f983', '∠BOD = 50° ; ∠AOD = 50°', false, '57cfe2cf-d701-4cb0-b3a6-5fadc60bb98c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7005d32a-0023-4153-baf5-6383e3c94bf3', '∠BOD = 40° ; ∠AOD = 140°', false, '57cfe2cf-d701-4cb0-b3a6-5fadc60bb98c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('518820a7-c98c-469a-9a80-c51aa24e0e99', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'In the given linear pair, two angles are (2x - 10)° and (3x + 20)°. Find the value of x:', '5x + 10 = 180 → 5x = 170 → x = 34. (Angles: 58° and 122°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38e5db9a-6e5d-4ed2-849b-029dc65169a8', 'x = 34 ((2x - 10) + (3x + 20) = 180° ⇒ 5x + 10 = 180° ⇒ 5x = 170° ⇒ x = 34)', true, '518820a7-c98c-469a-9a80-c51aa24e0e99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc6c94e9-d79b-4871-accc-879f247c28ed', 'x = 30', false, '518820a7-c98c-469a-9a80-c51aa24e0e99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19b348ec-b4ca-4875-a2e7-94b37f9c75a0', 'x = 35', false, '518820a7-c98c-469a-9a80-c51aa24e0e99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9eff8ec-7421-4de4-a09f-f2e530b6c23d', 'x = 38', false, '518820a7-c98c-469a-9a80-c51aa24e0e99');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c9f33662-1ff5-4dde-bf88-38e679352c26', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'Can two ACUTE angles be supplementary to each other?', 'If ∠A < 90° and ∠B < 90°, ∠A + ∠B < 180°, so two acute angles can never be supplementary.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45b3fa8c-28a5-4d17-b5c9-bd8e7294b387', 'No, because acute angles are strictly < 90°, so their sum is ALWAYS strictly < 180°', true, 'c9f33662-1ff5-4dde-bf88-38e679352c26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f803b0fc-4586-4ef2-8bd4-b067b75e9e39', 'Yes, if both angles are 45°', false, 'c9f33662-1ff5-4dde-bf88-38e679352c26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d85b9e09-a236-4900-a9f5-50b122b6a219', 'Yes, in right-angled triangles', false, 'c9f33662-1ff5-4dde-bf88-38e679352c26');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fca39e5c-d9bc-4ccb-99a1-c79a19b47555', 'Always yes', false, 'c9f33662-1ff5-4dde-bf88-38e679352c26');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eb78acfd-91d1-4201-a948-46188ba07ec3', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'Can two OBTUSE angles be supplementary to each other?', 'If ∠A > 90° and ∠B > 90°, ∠A + ∠B > 180°, so two obtuse angles can never be supplementary.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ab2721b-ab02-4153-8f8c-c9a765ad3ece', 'No, because obtuse angles are strictly > 90°, so their sum is ALWAYS strictly > 180°', true, 'eb78acfd-91d1-4201-a948-46188ba07ec3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9773252-b6bd-4f8e-9172-9d7c08795da9', 'Yes, if both are 100°', false, 'eb78acfd-91d1-4201-a948-46188ba07ec3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('121039f6-2428-4c92-bb83-6711d000032a', 'Yes, in pentagons', false, 'eb78acfd-91d1-4201-a948-46188ba07ec3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e562c88-f622-4ddb-8673-f28002d0f8f6', 'Always yes', false, 'eb78acfd-91d1-4201-a948-46188ba07ec3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d368944c-192f-405a-8c90-49050b4c57a9', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'Can two RIGHT angles be supplementary to each other?', 'Two right angles (90° + 90° = 180°) are always supplementary.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('062e1840-450e-4e9c-8771-f1bc8a032bad', 'Yes, because 90° + 90° = exactly 180°', true, 'd368944c-192f-405a-8c90-49050b4c57a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41360bbb-d2f8-48c1-a4f9-357d6b13b833', 'No, right angles can only be complementary', false, 'd368944c-192f-405a-8c90-49050b4c57a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c00fe3c-aa7d-468f-a9e5-d64cddea8146', 'Only in squares', false, 'd368944c-192f-405a-8c90-49050b4c57a9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a209314b-aaa1-46d4-a9f9-c21be50a0014', 'Never', false, 'd368944c-192f-405a-8c90-49050b4c57a9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('647f06dc-1435-4c2d-9e93-d40cc8fe6f40', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'If line l is parallel to line m (l ∥ m) and a transversal t cuts them, one of the interior angles is 65°. What is the measure of the alternate interior angle?', 'Alternate interior angles formed by parallel lines cut by a transversal are equal: 65°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('218f73b4-5f0a-41a1-8f69-38cc3aa6dbd5', '65° (Alternate interior angles are equal)', true, '647f06dc-1435-4c2d-9e93-d40cc8fe6f40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6def852d-6719-4aa1-8fcf-2896d7b3d947', '115°', false, '647f06dc-1435-4c2d-9e93-d40cc8fe6f40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('912b2663-13d7-4932-b254-e4a3e8aa0409', '25°', false, '647f06dc-1435-4c2d-9e93-d40cc8fe6f40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b97b9cf-08d7-41cd-bad4-32280d89c54e', '90°', false, '647f06dc-1435-4c2d-9e93-d40cc8fe6f40');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2244da6-34b5-4e2e-af1a-d2f00e99cecd', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'If line l is parallel to line m (l ∥ m) and a transversal cuts them, one interior angle is 70°. What is the interior angle on the SAME SIDE of the transversal?', 'Interior angles on the same side sum to 180°: 180° - 70° = 110°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c8f9983-aa1a-4a05-9b1c-5688cc4d1ba4', '110° (Consecutive interior angles are supplementary: 180° - 70° = 110°)', true, 'c2244da6-34b5-4e2e-af1a-d2f00e99cecd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd0953a5-011f-4f23-ada3-047ff8be8dd9', '70°', false, 'c2244da6-34b5-4e2e-af1a-d2f00e99cecd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('597fb246-27ab-4c27-8496-41b04eaea1ac', '20°', false, 'c2244da6-34b5-4e2e-af1a-d2f00e99cecd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d5ab7ca-d2e3-4196-9f25-2a8631199822', '180°', false, 'c2244da6-34b5-4e2e-af1a-d2f00e99cecd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d9a8ac06-7568-4b41-8d88-048e1e175f7a', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'Three angles at a point on a straight line are x°, (x + 20)°, and (x + 40)°. Find the value of x:', '3x + 60° = 180° → 3x = 120° → x = 40°. (Angles: 40°, 60°, 80°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5b52c2f-91ee-40a0-843a-32260de0eb72', 'x = 40 (x + (x + 20) + (x + 40) = 180° ⇒ 3x + 60 = 180° ⇒ 3x = 120° ⇒ x = 40)', true, 'd9a8ac06-7568-4b41-8d88-048e1e175f7a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cb3cbfa-4c38-4ba9-9c62-e711fd766ebf', 'x = 30', false, 'd9a8ac06-7568-4b41-8d88-048e1e175f7a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('039878cc-7657-458e-abf6-8f4d4f2edb63', 'x = 50', false, 'd9a8ac06-7568-4b41-8d88-048e1e175f7a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac92ad46-0758-4404-a421-fd583a2db6c1', 'x = 45', false, 'd9a8ac06-7568-4b41-8d88-048e1e175f7a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e4bb154-5681-4cd7-8d40-1c2e359ca8c8', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'In the figure, four rays meet at a common point O. What is the sum of all angles around a point?', 'The sum of all angles around a single point in a plane is 360° (complete angle).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87620d14-4901-4a0b-b292-df19cad9cef7', '360° (Complete Angle)', true, '2e4bb154-5681-4cd7-8d40-1c2e359ca8c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b4032cf-8d35-4caa-aa02-f74b06782102', '180°', false, '2e4bb154-5681-4cd7-8d40-1c2e359ca8c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8c6f217-2013-4efe-85dc-897ba99a0c04', '270°', false, '2e4bb154-5681-4cd7-8d40-1c2e359ca8c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e6428ea-c416-4d2f-b836-b0653944154e', '90°', false, '2e4bb154-5681-4cd7-8d40-1c2e359ca8c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f66ab626-211b-48e2-87f9-c3ac6f767ea8', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'Two parallel lines are cut by a transversal. If a pair of corresponding angles is represented by (3x - 15)° and (2x + 10)°, find the value of x:', 'Corresponding angles are equal: 3x - 15 = 2x + 10 → x = 25. (Angle = 60°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0163d779-5200-4c1a-a594-2584b2e4e51a', 'x = 25 (3x - 15 = 2x + 10 ⇒ x = 25)', true, 'f66ab626-211b-48e2-87f9-c3ac6f767ea8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28b8a2ef-87a7-42a5-941f-77a4714a8706', 'x = 20', false, 'f66ab626-211b-48e2-87f9-c3ac6f767ea8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e4ad7fe-4c53-496f-bbda-41d6aeda51e6', 'x = 30', false, 'f66ab626-211b-48e2-87f9-c3ac6f767ea8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba268068-a688-4d57-aff6-1ec4bb6c57f0', 'x = 15', false, 'f66ab626-211b-48e2-87f9-c3ac6f767ea8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b051ad63-ab19-4fa4-9b0a-e0d27a38399d', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'If an angle is five times its own Complement, what is the measure of the angle?', 'x = 5(90 - x) → 6x = 450 → x = 75° (Complement = 15°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec49af4a-d102-4c87-8165-ba26732d7b5f', '75° (x = 5(90° - x) ⇒ x = 450° - 5x ⇒ 6x = 450° ⇒ x = 75°)', true, 'b051ad63-ab19-4fa4-9b0a-e0d27a38399d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('139b880d-a20b-4d64-b6c1-ee3ee8e551ec', '15°', false, 'b051ad63-ab19-4fa4-9b0a-e0d27a38399d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('801cf287-bde4-4b76-9e50-393e3ab88b32', '60°', false, 'b051ad63-ab19-4fa4-9b0a-e0d27a38399d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d4cf497-fbcd-44c9-8001-037bc6afbcde', '80°', false, 'b051ad63-ab19-4fa4-9b0a-e0d27a38399d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4bc98d09-aee0-4c52-9474-a4ff59239276', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Medium', 'What geometric condition PROVES that two lines are parallel when intersected by a transversal?', 'Euclidean parallel postulates: equality of corresponding/alternate angles or supplementarity of interior angles proves parallelism.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a50f0b9b-909a-4f6f-b0da-92c3a3708b60', 'Any one of the three: (1) Alternate interior angles are equal, OR (2) Corresponding angles are equal, OR (3) Consecutive interior angles are supplementary', true, '4bc98d09-aee0-4c52-9474-a4ff59239276');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13b849de-4eb3-432b-b8da-bebc0e3a6a27', 'The lines meet at a point', false, '4bc98d09-aee0-4c52-9474-a4ff59239276');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d68adff-68f3-4ba2-98c3-fe86a9a7d5f9', 'The lines are perpendicular', false, '4bc98d09-aee0-4c52-9474-a4ff59239276');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e204aea8-013a-4b74-8ab8-223acfe8e590', 'The lines are drawn in blue color', false, '4bc98d09-aee0-4c52-9474-a4ff59239276');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3609069-e2ff-47ca-b619-3973c267e813', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97fb9c7f-cab4-46fc-8304-2c72f5d35ce0', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'c3609069-e2ff-47ca-b619-3973c267e813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4de7297-acfe-4f97-bb99-429610cbe8c0', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'c3609069-e2ff-47ca-b619-3973c267e813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f46ca362-2f37-4135-816b-4bbca3c112a4', '(A) is true, but (R) is false.', false, 'c3609069-e2ff-47ca-b619-3973c267e813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d07ca7d-78d4-4e32-86b0-edb68a55a7cc', '(A) is false, but (R) is true.', false, 'c3609069-e2ff-47ca-b619-3973c267e813');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6fd36a7-34dc-467e-8250-13347735568b', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'Spot the IMPOSTER among the following geometric statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44df5888-24fe-4c88-8089-fcc6c65c10cd', 'Statement 1', false, 'd6fd36a7-34dc-467e-8250-13347735568b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('795b088f-d41c-44d4-b55c-e31c4b8059e4', 'Statement 2', false, 'd6fd36a7-34dc-467e-8250-13347735568b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30e39e52-4e2b-4190-b075-260f73cc0e0e', 'Statement 3', false, 'd6fd36a7-34dc-467e-8250-13347735568b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2af3228e-a53c-4691-a019-21a4852099f1', 'Statement 4 (Two obtuse angles sum to > 180°, so they can NEVER form a linear pair)', true, 'd6fd36a7-34dc-467e-8250-13347735568b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3d8d367-ada8-47f8-bf92-45f0ffb07dfc', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'In the figure, AB ∥ CD and CD ∥ EF. If y : z = 3 : 7, find the angle x (where x and y are consecutive interior angles between AB and CD, and x and z are alternate interior angles between AB and EF):', 'x = z (alternate angles across AB ∥ EF). y + z = 180° → 10k = 180° → k = 18° → z = 126° → x = 126°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('652cb8e0-193f-4bf3-8e14-199b9c21a7c4', 'x = 126° (Since AB ∥ EF, x = z ; Consecutive interior: x + y = 180° ⇒ z + y = 180° ; y:z = 3:7 ⇒ 10k = 180° ⇒ k = 18° ⇒ z = 7(18) = 126° ⇒ x = 126°)', true, 'c3d8d367-ada8-47f8-bf92-45f0ffb07dfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c10bdddc-5b12-4da7-8504-496e48e32a7a', 'x = 54°', false, 'c3d8d367-ada8-47f8-bf92-45f0ffb07dfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa7e6b87-514d-4346-8541-072528aabb6e', 'x = 135°', false, 'c3d8d367-ada8-47f8-bf92-45f0ffb07dfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37fc82f6-377a-48d5-9883-2293f4324222', 'x = 120°', false, 'c3d8d367-ada8-47f8-bf92-45f0ffb07dfc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d926073-f7c4-4d76-886d-6b86462c40aa', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'Match Column I (Angle Relationships for Parallel Lines) with Column II (Geometric Letter Mnemonics / Properties):
(a) Corresponding Angles         -> (i) ''F'' Shape / Congruent (Equal)
(b) Alternate Interior Angles    -> (ii) ''Z'' Shape / Congruent (Equal)
(c) Consecutive Interior Angles  -> (iii) ''C'' or ''U'' Shape / Supplementary (Sum = 180°)
(d) Vertically Opposite Angles   -> (iv) ''X'' Shape / Congruent (Equal)', 'F = Corresponding; Z = Alternate; C = Consecutive interior; X = Vertically opposite.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b37e82c-7e1f-4a09-964f-ace9d04148a7', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '3d926073-f7c4-4d76-886d-6b86462c40aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d15db026-787b-40ec-9cb3-82ba37994de8', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '3d926073-f7c4-4d76-886d-6b86462c40aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b17a9168-99ae-462e-987c-6522fd6b2cc8', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '3d926073-f7c4-4d76-886d-6b86462c40aa');
