INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10f416ff-04aa-4de7-b505-9c88cbd89cb0', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'Read the statements regarding lines and rays:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('086eac0a-d9a3-4c8e-9248-777526aad6fd', 'Statements 1 and 2 only', true, '10f416ff-04aa-4de7-b505-9c88cbd89cb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4031f571-3b1c-4223-b7d4-d09766e75ec8', 'Statements 2 and 3 only', false, '10f416ff-04aa-4de7-b505-9c88cbd89cb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('316e89b7-a1be-48b2-8903-9a4ac8fe080c', 'Statements 1 and 3 only', false, '10f416ff-04aa-4de7-b505-9c88cbd89cb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('110d0e53-234a-425a-a08d-6e9b5ee8b6e5', 'All Statements 1, 2, and 3', false, '10f416ff-04aa-4de7-b505-9c88cbd89cb0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc72e3be-612b-45d8-9bbe-24361e7c92f6', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'An angle''s supplement is 10° more than THREE TIMES its complement. Find the measure of the angle:', '180 - x = 3(90 - x) + 10 → 180 - x = 280 - 3x → 2x = 100 → x = 50°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26993eaf-9b2d-48c2-a40a-a7d69984dc20', '50° (180° - x = 3(90° - x) + 10° ⇒ 180° - x = 270° - 3x + 10° ⇒ 2x = 100° ⇒ x = 50°)', true, 'cc72e3be-612b-45d8-9bbe-24361e7c92f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10143169-41d6-4967-9077-477abc0fa3d9', '40°', false, 'cc72e3be-612b-45d8-9bbe-24361e7c92f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fda3eb6-59bb-4098-ab90-7f9daf8dd099', '60°', false, 'cc72e3be-612b-45d8-9bbe-24361e7c92f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f17cf4f5-3b97-4854-b4ac-7059d80a4c11', '45°', false, 'cc72e3be-612b-45d8-9bbe-24361e7c92f6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4627d5e9-82fa-4a98-8f66-09b7ab7d635e', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'In the figure, arms of two angles are parallel (AB ∥ DE and BC ∥ EF). If ∠ABC = 70°, what is the measure of ∠DEF?', 'Parallel arms theorem: if both angle pairs point in the same directional orientation, ∠DEF = ∠ABC = 70°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a672fcf-43a5-41cf-8b85-18ce96ab19b9', '70° (Angles with mutually parallel arms are either equal or supplementary ; here both are acute, so ∠DEF = 70°)', true, '4627d5e9-82fa-4a98-8f66-09b7ab7d635e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c66a3008-a782-403d-8dbb-c5a7597af62d', '110°', false, '4627d5e9-82fa-4a98-8f66-09b7ab7d635e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3bde369-4d44-4669-899d-3daab94f09b1', '20°', false, '4627d5e9-82fa-4a98-8f66-09b7ab7d635e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19888cd8-8ba7-476f-84a1-84c1081e6a9e', '90°', false, '4627d5e9-82fa-4a98-8f66-09b7ab7d635e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5dc8a9e0-2a4a-406d-899f-95918b2455b4', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'If the bisectors of two adjacent supplementary angles are drawn, what is the exact angle formed BETWEEN THE TWO BISECTORS?', 'Half of supplementary linear pair: θ/2 + (180 - θ)/2 = 90° (perpendicular angle bisectors).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8ea8bbb-5a13-4828-8e78-9974dd63cf85', '90° (Always a RIGHT ANGLE: if ∠1 + ∠2 = 180°, then ∠1/2 + ∠2/2 = 180°/2 = 90°)', true, '5dc8a9e0-2a4a-406d-899f-95918b2455b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ebf6311-4c01-4260-96db-777ed119a3d2', '45°', false, '5dc8a9e0-2a4a-406d-899f-95918b2455b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e16e7e21-a321-414e-b4c5-0df09b92fbcc', '180°', false, '5dc8a9e0-2a4a-406d-899f-95918b2455b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d180bae5-0c42-48af-881a-bd7482f2ce49', '60°', false, '5dc8a9e0-2a4a-406d-899f-95918b2455b4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba471ab2-e507-4668-94e0-f7eec1861f62', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'Two parallel lines l and m are cut by transversal t. The interior angles on the same side are (2x + 30)° and (3x - 20)°. Find the value of x and both angles:', '5x + 10 = 180 → 5x = 170 → x = 34. Angle 1 = 2(34)+30 = 98°; Angle 2 = 3(34)-20 = 82°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2026ce5-8b17-4ba3-b90e-f2f6be7e6675', 'x = 34 ; Angles are 98° and 82° ((2x + 30) + (3x - 20) = 180° ⇒ 5x + 10 = 180° ⇒ 5x = 170° ⇒ x = 34 ⇒ Angles: 98°, 82°)', true, 'ba471ab2-e507-4668-94e0-f7eec1861f62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01325a4d-ada0-40be-bb04-4eb1bad753e2', 'x = 30 ; Angles are 90°, 90°', false, 'ba471ab2-e507-4668-94e0-f7eec1861f62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eedff897-3534-49be-b03a-e2960260eaab', 'x = 32 ; Angles are 94°, 86°', false, 'ba471ab2-e507-4668-94e0-f7eec1861f62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('433e0621-561e-43f1-b646-34d5e8bfa996', 'x = 35 ; Angles are 100°, 80°', false, 'ba471ab2-e507-4668-94e0-f7eec1861f62');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88cddc74-bf1d-4b51-b1ed-c36705f3c341', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'Line l ∥ line m. A transversal intersects them. If the exterior angle is (5x - 25)° and its alternate exterior angle is (3x + 15)°, find the measure of this angle:', 'Alternate exterior angles are equal: 5x - 25 = 3x + 15 → 2x = 40 → x = 20. Angle = 5(20) - 25 = 75°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88161d2e-cf88-4c42-b017-0bb853b0a7cc', '75° (5x - 25 = 3x + 15 ⇒ 2x = 40 ⇒ x = 20 ⇒ Angle = 5(20) - 25 = 75°)', true, '88cddc74-bf1d-4b51-b1ed-c36705f3c341');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9116190-5958-4915-a5fe-2958c8a6cee9', '65°', false, '88cddc74-bf1d-4b51-b1ed-c36705f3c341');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a44ef50f-dd9b-4c1f-b060-8680ced68b82', '85°', false, '88cddc74-bf1d-4b51-b1ed-c36705f3c341');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48de18e1-e156-4520-8998-c1649557a3b2', '90°', false, '88cddc74-bf1d-4b51-b1ed-c36705f3c341');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f923020-c8f6-43f9-9720-bd3634cdf8a0', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'If two parallel lines are intersected by a transversal, what quadrilateral is formed by the bisectors of ALL four interior angles?', 'Interior angle bisectors intersect at 90° and form parallel opposite segments, proving the enclosed quadrilateral is a rectangle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fe36a08-26f4-4bc6-ae4b-6ec71d49a198', 'A RECTANGLE (All four interior angles of the formed quadrilateral are 90°, and opposite sides are parallel)', true, '7f923020-c8f6-43f9-9720-bd3634cdf8a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82ddd8d8-fdd1-47aa-90fb-ebc369efcc77', 'A Square only', false, '7f923020-c8f6-43f9-9720-bd3634cdf8a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d390e31d-cc75-40e1-81cc-1a6a7f1eced3', 'A Rhombus', false, '7f923020-c8f6-43f9-9720-bd3634cdf8a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bbb174a-5386-4932-a913-c47f9479466f', 'A Trapezium', false, '7f923020-c8f6-43f9-9720-bd3634cdf8a0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7332ceed-74ba-4a7c-89e4-f1355d9a4398', 'Class 7', 'Mathematics', 'Chapter 5: Lines and Angles', 'Hard', 'Why is the rigorous understanding of Lines, Transversals, and Angles foundational in structural engineering, architecture, optical ray tracing, and computer graphics?', 'Euclidean parallel line theory and angle relationships form the mathematical bedrock of structural mechanics, optics, spatial modeling, and vector graphics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2858ac09-362b-43a6-9deb-3a570c03517d', 'It provides the exact trigonometric and geometric axioms governing coordinate transformations, structural load balance in trusses, ray reflection/refraction, and 3D rendering projections', true, '7332ceed-74ba-4a7c-89e4-f1355d9a4398');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d456f646-ea04-462c-9ffe-e00244f9f060', 'Because angles are only used to draw circles', false, '7332ceed-74ba-4a7c-89e4-f1355d9a4398');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('653c2b5f-612a-468d-b518-c62963d2e2e4', 'Because parallel lines do not exist in reality', false, '7332ceed-74ba-4a7c-89e4-f1355d9a4398');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a1dec3d-2d16-4449-94e6-8c3c5cb5b921', 'Because transversal lines eliminate the need for calculations', false, '7332ceed-74ba-4a7c-89e4-f1355d9a4398');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e7e0f045-6716-4b0a-ace1-27b5a34dbaf1', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'In John Galsworthy''s moving classic story ''Quality'', who was Mr. Gessler?', 'Mr. Gessler was an artisanal German bootmaker living in London, devoted entirely to the perfection of his craft.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('055cc6e9-f212-4d64-8ea3-3b96c0f28b7e', 'A master German bootmaker who lived in London and made boots of supreme perfection and artistic quality', true, 'e7e0f045-6716-4b0a-ace1-27b5a34dbaf1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acb2eac6-82ea-411b-911d-881e501db3ab', 'A wealthy factory owner', false, 'e7e0f045-6716-4b0a-ace1-27b5a34dbaf1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9a3512f-b6ba-4353-94d1-4b136a964cdf', 'A famous theater actor', false, 'e7e0f045-6716-4b0a-ace1-27b5a34dbaf1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5838e4dd-0977-48c4-90b2-460df14ad2ee', 'A royal doctor', false, 'e7e0f045-6716-4b0a-ace1-27b5a34dbaf1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8fb249bf-0ad4-4b13-92eb-2484f0bd3824', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'Where was Mr. Gessler''s quiet little boot-making shop situated in London?', 'Gessler Brothers'' shop was nestled in a distinguished, quiet by-street in London''s fashionable West End.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfb8f928-583a-4607-b179-4a1447b1d310', 'In a small by-street in the fashionable West End of London', true, '8fb249bf-0ad4-4b13-92eb-2484f0bd3824');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d563fc66-27d8-4161-84ae-2e8887b7ea2b', 'In the center of a crowded marketplace', false, '8fb249bf-0ad4-4b13-92eb-2484f0bd3824');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f033fab7-e906-44c6-a619-08942eb5cf75', 'Inside a large department store', false, '8fb249bf-0ad4-4b13-92eb-2484f0bd3824');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7be31e98-7b5b-41e5-96b2-b20b83f3f733', 'Near London harbor', false, '8fb249bf-0ad4-4b13-92eb-2484f0bd3824');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5ab46996-eefd-43b7-a904-286af2b594f4', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'What was uniquely displayed in the modest shop-window of Gessler Brothers?', 'The shop had quiet dignity: no boastful signs, merely ''Gessler Brothers'' and a few masterfully crafted display boots.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d73f724e-eec4-4b83-8643-f8dd622feffc', 'No sign above except the name ''Gessler Brothers'', and in the window a few pairs of exquisite bespoke handmade boots', true, '5ab46996-eefd-43b7-a904-286af2b594f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5d218c5-ddc0-4fc9-8f7b-f5bfea4ba842', 'Dozens of colorful neon lights', false, '5ab46996-eefd-43b7-a904-286af2b594f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec65b776-9483-4919-87fb-d5f0d25de745', 'Piles of factory-made cheap shoes', false, '5ab46996-eefd-43b7-a904-286af2b594f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae7e1e8b-c4b4-445c-b6ec-a6914e4b9604', 'Gold and diamond jewelry', false, '5ab46996-eefd-43b7-a904-286af2b594f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c596422-6211-46f3-ba43-322e3c96571e', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'How did entering Mr. Gessler''s shop feel to the narrator, comparing it to a sacred place?', 'Galsworthy compares entering Gessler''s shop to entering a church, permeated by the solemn scent of fine leather.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b414930e-58fc-45cb-9536-9d13268f8b0e', 'It felt quiet and reverent, as if entering a Church, where one sat on a single wooden chair waiting with respect', true, '5c596422-6211-46f3-ba43-322e3c96571e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a312c93-5194-458a-be9d-30f64f662523', 'It felt like a noisy railway station', false, '5c596422-6211-46f3-ba43-322e3c96571e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6f86499-1736-4c1d-aa9e-aef4af1a26e2', 'It felt like a crowded schoolroom', false, '5c596422-6211-46f3-ba43-322e3c96571e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22ee7d71-5b75-4c4a-aa82-a508aeca12c9', 'It felt like a chaotic street market', false, '5c596422-6211-46f3-ba43-322e3c96571e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c9b6623b-4068-4049-8b16-7973ef36002d', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'What famous sentence in his guttural German accent did Mr. Gessler say when the author asked if making boots was hard?', 'Mr. Gessler considered his bespoke craft an exalted vocation: ''Id is an Ardt!''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dcbca07-43c3-4d9c-9db4-3720bea63b63', '"Id is an Ardt!" (It is an Art!)', true, 'c9b6623b-4068-4049-8b16-7973ef36002d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61d36dad-94be-4744-a814-13cc7d0c2f00', '"Id is for money!"', false, 'c9b6623b-4068-4049-8b16-7973ef36002d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56ef0345-0998-4435-abdd-c36b370f670b', '"Id is very easy!"', false, 'c9b6623b-4068-4049-8b16-7973ef36002d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66f4522c-f4b7-42e5-8131-6764fac772d1', '"Id is a factory job!"', false, 'c9b6623b-4068-4049-8b16-7973ef36002d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d25b01a-8f53-4c60-ad32-6f10a9da5827', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'What distinguished Mr. Gessler''s boots from all mass-produced commercial shoes?', 'Gessler''s boots embodied immaculate bespoke fit, finest leather selection, and astonishing durability.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc8eb9a0-3a92-450a-b581-f412f7def0d4', 'They fitted perfectly, were made of the finest top-grade leather, and lasted extraordinarily long without losing shape', true, '1d25b01a-8f53-4c60-ad32-6f10a9da5827');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('547ef645-dca4-467c-b26a-f80c46db88f2', 'They were very cheap and broke in a week', false, '1d25b01a-8f53-4c60-ad32-6f10a9da5827');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21edc53b-40cb-4562-b050-07ded16200fc', 'They had flashing electric lights', false, '1d25b01a-8f53-4c60-ad32-6f10a9da5827');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38314225-c80e-4c03-b674-e0d3e466100f', 'They were made of plastic', false, '1d25b01a-8f53-4c60-ad32-6f10a9da5827');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5477460-e22f-46a4-aa54-e99caab40ac8', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'Why did Mr. Gessler lose his business customers and face immense financial hardship over the years?', 'Corporate mass advertising crushed individual artisanry: ''Dey get id all... by adverdisement, nod by work''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7566607a-1480-4b19-8caa-9138b1888300', 'Large commercial shoe corporations took away customers through aggressive mass advertising rather than genuine quality of craftsmanship', true, 'a5477460-e22f-46a4-aa54-e99caab40ac8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da626412-412d-407e-a50a-7e8283462e37', 'Because he forgot how to make boots', false, 'a5477460-e22f-46a4-aa54-e99caab40ac8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04d3af8b-0e92-48e9-b15f-0bc75099203f', 'Because he moved to another country', false, 'a5477460-e22f-46a4-aa54-e99caab40ac8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2b69290-c43d-4b42-b5d0-487bfa308a82', 'Because people stopped wearing shoes', false, 'a5477460-e22f-46a4-aa54-e99caab40ac8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e417149-333e-4e8b-b745-8de31dd4b011', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'What tragic fate befell Mr. Gessler at the end of the story?', 'The English shopman sadly reveals: ''Slow starvation, the doctor called it... he never gave himself time to eat''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73cfb552-631c-408e-b8b4-74b7fb9d108a', 'He died of slow starvation because he spent every penny on fine leather and shop rent without keeping enough food for himself', true, '1e417149-333e-4e8b-b745-8de31dd4b011');
