INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98822d72-61d2-45f6-b6f0-d59cedf94684', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'In Shirley Bauer''s poem ''Trees'', who are trees primarily for according to the opening stanzas?', 'The poem begins: ''Trees are for birds. / Trees are for children.''.', NOW()) ON CONFLICT DO NOTHING;
