INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66012123-2b5f-4c51-b3ed-3190e7143ad1', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'What recreational games and structures do children build in and around trees in the poem ''Trees''?', 'Bauer highlights childhood delights: building treehouses, swinging on boughs, and playing hide and seek.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8032545c-e60d-4291-94a8-c1138a43a7fd', 'Treehouses to live in, swings to swing on, and hiding spots to play ''Hide and Seek''', true, '66012123-2b5f-4c51-b3ed-3190e7143ad1');
