INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4cd301b-ce44-4e47-9465-a2a8d4a5e37c', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Easy', 'What seasonal comfort do trees provide during hot summer months?', 'Textual line: ''Trees are to make cool shade in summer''.', NOW()) ON CONFLICT DO NOTHING;
