INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0472a359-e3f3-4910-8c28-4545f6ea93b3', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'What did Mr. Gessler do when the narrator once mentioned that a particular pair of boots had creaked?', 'Gessler''s uncompromising professional pride: ''Send dem back... I will look ad dem. If I can do noding... I dake dem off your bill''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee853140-4c31-4bd7-9630-d243d7cdeadc', 'He was deeply astonished, looked at the narrator incredulously, and promised with immense integrity to examine them and take them off the bill if he could not fix them', true, '0472a359-e3f3-4910-8c28-4545f6ea93b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a143296b-0610-4cb7-8029-086391c7bebb', 'He shouted angrily and threw the author out', false, '0472a359-e3f3-4910-8c28-4545f6ea93b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0672a9a0-0004-484f-9ed3-2e1e51c297b3', 'He denied that he ever made the boots', false, '0472a359-e3f3-4910-8c28-4545f6ea93b3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04d659bf-9fcc-408c-9d42-43fbff924d59', 'He laughed and ignored the author', false, '0472a359-e3f3-4910-8c28-4545f6ea93b3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0dad3128-d0b2-468c-b3fb-4d979d196d22', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'Why did Mr. Gessler touch the author''s shoe with his finger when the author once absent-mindedly entered wearing shoes bought from a large commercial firm?', 'Gessler''s master eye pinpointed the factory defect instantly: ''Dose big virms ''ave no self-respect... Id ''urds you dere''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d96f0f1d-f7a1-4e6b-88da-46faa2cfb613', 'He immediately pressed the exact spot where the factory boot pinched the author''s foot, remarking sadly how big corporations exploit advertising without giving comfort', true, '0dad3128-d0b2-468c-b3fb-4d979d196d22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46aaa89f-5ef6-4a80-860e-37e5cbb54840', 'He wanted to polish the shoe', false, '0dad3128-d0b2-468c-b3fb-4d979d196d22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6f9ca4c-aa10-4119-99c3-32dc587b880f', 'He wanted to steal the shoe', false, '0dad3128-d0b2-468c-b3fb-4d979d196d22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('692e7589-bd8d-40c1-b3f3-0ae707def035', 'He did not care about the shoe', false, '0dad3128-d0b2-468c-b3fb-4d979d196d22');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3bc1bd0-21bf-42c3-b7d6-f48d2152d390', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'What tribute did the young English shop assistant pay to Mr. Gessler after his passing?', 'The English successor honors Gessler''s uncompromising genius: ''He made the best boots in London... Never made a better boot in his life''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('814165b0-5903-4236-a244-d0827f6a259e', '"He made the best boots in London! Look at the leather he used, and he never compromised on time. He was a character who competed with nobody and starved for his art."', true, 'c3bc1bd0-21bf-42c3-b7d6-f48d2152d390');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f59d43c-2911-4111-bdcc-bde9c5d651ac', 'He said Mr. Gessler was a bad shoemaker', false, 'c3bc1bd0-21bf-42c3-b7d6-f48d2152d390');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b005964c-abe5-45f1-bc4e-edb224fd1529', 'He said Mr. Gessler was very lazy', false, 'c3bc1bd0-21bf-42c3-b7d6-f48d2152d390');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1a92d02-d090-4a55-9ca0-9046b89e5e12', 'He said Mr. Gessler was rich', false, 'c3bc1bd0-21bf-42c3-b7d6-f48d2152d390');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bdc42313-a1b2-483c-8f28-ae4eca9f38ce', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'In the poem ''Trees'', what do fathers say when autumn leaves fall from trees?', 'Fathers view autumn pragmatically: ''What a lot of leaves to rake this fall!''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9138fb7-a6af-4445-b9fa-439f17218688', '"What a lot of leaves to rake this fall!"', true, 'bdc42313-a1b2-483c-8f28-ae4eca9f38ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a392b6b7-80c0-4cc4-9605-c577dbb6deab', '"Let''s plant more flowers!"', false, 'bdc42313-a1b2-483c-8f28-ae4eca9f38ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfe7d467-1890-49eb-944e-02a98a38a4aa', '"Winter is over!"', false, 'bdc42313-a1b2-483c-8f28-ae4eca9f38ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80e51b31-8e08-439f-8ee5-ce034a0014bd', '"Look at the apples!"', false, 'bdc42313-a1b2-483c-8f28-ae4eca9f38ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e50d6914-4175-46cc-b587-39be431a1911', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'In the poem ''Trees'', what do mothers say when looking at lush green trees?', 'Mothers view the scenic visual aesthetic: ''What a lovely picture to paint!''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc7c4bbe-2bf5-41c0-b7c8-df51517c89d8', '"What a lovely picture to paint!"', true, 'e50d6914-4175-46cc-b587-39be431a1911');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f223665a-1c95-4c12-937c-7a21779991ad', '"Cut down the tree immediately!"', false, 'e50d6914-4175-46cc-b587-39be431a1911');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e997a7bf-a283-44d5-90ba-af09cc3d86ba', '"Where are my keys?"', false, 'e50d6914-4175-46cc-b587-39be431a1911');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cd6a5da-63c2-4b5c-a755-eb259cbf918a', '"The tree is too big!"', false, 'e50d6914-4175-46cc-b587-39be431a1911');
