INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93fbcede-9372-416b-a79e-de660b300fed', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'What is the meaning of the word ''Splendid'' in: ''The boots were of splendid quality''?', '''Splendid'' denotes magnificent, outstanding artistic and functional excellence.', NOW()) ON CONFLICT DO NOTHING;
