INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1636da20-becd-42b4-87ff-31338d817ecd', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'Identify the meaning of ''Timber'' in the poetic line: ''Trees are to be chopped down and called TIMBER-R-R''?', '''Timber'' designates processed commercial lumber/wood for construction and carpentry.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fed8c2ed-a980-4d1c-af4d-1c101ec6c9fc', 'Wood prepared for building houses, carpentry, and furniture', true, '1636da20-becd-42b4-87ff-31338d817ecd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0d19dcc-4522-431b-ad5d-b59bc231a948', 'A musical instrument', false, '1636da20-becd-42b4-87ff-31338d817ecd');
