INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f87f12a8-dbff-4cd5-ba55-983c08b31372', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'Choose the correct Adverb of Degree in: ''Mr. Gessler was **extremely** passionate about his craft.''', '''Extremely'' is an adverb of degree quantifying the intensity of the adjective ''passionate''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddcac714-1bb1-4e98-a616-882bb833109d', 'extremely (modifying the adjective ''passionate'')', true, 'f87f12a8-dbff-4cd5-ba55-983c08b31372');
