INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4686d58-e203-4cf1-bcf8-c2e43e96214c', 'Inventive skill, cleverness, and creative originality', true, 'bb2d74df-ced2-4c98-ad54-c13a73821cb4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8cc3e77-5c00-40f7-aa33-5e7409f21478', 'Foolishness', false, 'bb2d74df-ced2-4c98-ad54-c13a73821cb4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2098a2ed-f19b-4ef3-89a6-898dd1e5a81f', 'Laziness', false, 'bb2d74df-ced2-4c98-ad54-c13a73821cb4');
