INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a604a28c-d041-46de-920b-e21592c03580', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'What is the ANTONYM of ''Bespoke'' (custom-made / tailor-made)?', 'The antonym of ''bespoke'' (individually tailored) is ''mass-produced'' or ''ready-made''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e2d0976-69fc-4ee5-9b51-13c8a848c49a', 'Mass-produced / Ready-made / Factory-made', true, 'a604a28c-d041-46de-920b-e21592c03580');
