INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a33ebed1-954c-4d5e-9bbe-00682e7cc8ef', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'Choose the correctly framed question using the Wh-word ''Why'':', 'Past interrogative syntax: Wh-word + did + subject + base verb (''Why did Mr. Gessler refuse...'').', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5217bbbd-3b1b-4a64-9b3f-718a2290e885', '"Why did Mr. Gessler refuse to compromise on the quality of his leather?"', true, 'a33ebed1-954c-4d5e-9bbe-00682e7cc8ef');
