INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d601af91-9ef6-49ad-8eaf-936baa79c521', '"Why was Mr. Gessler refuse?"', false, 'a33ebed1-954c-4d5e-9bbe-00682e7cc8ef');
