INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ff98dfd-fa8f-4e68-bebc-25cc3b726993', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'Identify the figure of speech in: ''The solemn shop was like a temple of leather.''', 'Simile uses ''like'' to explicitly compare the quiet reverence of the boot shop to a sacred temple.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('087c2ec4-fba6-45c9-bae1-974ce47f6982', 'Simile (explicit comparison using ''like'')', true, '8ff98dfd-fa8f-4e68-bebc-25cc3b726993');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc834f9c-2f7e-4957-a198-fdcd4c5d67f0', 'Metaphor', false, '8ff98dfd-fa8f-4e68-bebc-25cc3b726993');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0e8272a-46eb-4971-95ea-29504159db70', 'Personification', false, '8ff98dfd-fa8f-4e68-bebc-25cc3b726993');
