INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db05a734-c525-49a3-9fed-838952fae268', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'What is the meaning of the phrasal verb ''To take off'' in: ''He offered to take the boots off the bill''?', 'In commerce, ''to take off the bill'' means to refund or deduct the cost.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24d57898-7adb-4882-b9d4-f5fe930b7815', 'To deduct or remove from the total amount charged', true, 'db05a734-c525-49a3-9fed-838952fae268');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37a751ca-43e1-43dc-b81c-1627104c8bc8', 'To fly an aeroplane', false, 'db05a734-c525-49a3-9fed-838952fae268');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('688e9d3e-d983-4ebf-9bb9-cd7b949a8600', 'To remove shoes', false, 'db05a734-c525-49a3-9fed-838952fae268');
