INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d63b21c-8f82-4124-93ba-be4c08cdf2d2', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Medium', 'Choose the correct spelling:', 'Correct orthography: I-N-C-O-M-P-R-E-H-E-N-S-I-B-L-E.', NOW()) ON CONFLICT DO NOTHING;
