INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc6f04a7-00e0-4792-ad70-64ddd166b46b', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '3881dd77-dc93-442a-8a2f-1dba9c4c3b8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc78870d-9ad4-4447-bf3a-2d3af116911d', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '3881dd77-dc93-442a-8a2f-1dba9c4c3b8f');
