INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e078915-dd39-4434-aa91-8573a10207d9', '(A) is false, but (R) is true.', false, '3881dd77-dc93-442a-8a2f-1dba9c4c3b8f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c963ccc1-391c-4be6-b307-dee474d5a52b', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Hard', 'Spot the IMPOSTER in the following character attributes of Mr. Gessler:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21c8ef69-459e-4ab9-997f-f0cb1dfc5a5a', 'Attribute 1', false, 'c963ccc1-391c-4be6-b307-dee474d5a52b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2008b8e-e014-4694-a947-e2bad0b5bcd9', 'Attribute 2', false, 'c963ccc1-391c-4be6-b307-dee474d5a52b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be895e6e-612b-4b31-90fd-7bac5a560ec7', 'Attribute 3', false, 'c963ccc1-391c-4be6-b307-dee474d5a52b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dd116eb-a0b7-4389-b700-f595396b5476', 'Attribute 4 (Mr. Gessler died of starvation in poverty ; he NEVER sold plastic shoes)', true, 'c963ccc1-391c-4be6-b307-dee474d5a52b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d2a04994-fdc8-4398-be04-62de6e52f0ef', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Hard', 'Analyze the linguistic characterization of Mr. Gessler:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77f0193e-f5a3-4a4a-9329-e86d01c5a5db', 'To preserve the poignant, authentic dignity of an immigrant artisan struggling in London, rendering his tragic dedication deeply intimate and visceral to the reader', true, 'd2a04994-fdc8-4398-be04-62de6e52f0ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edda8334-2fd4-4182-95fd-1c3126db34b5', 'To make fun of German accents', false, 'd2a04994-fdc8-4398-be04-62de6e52f0ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('579516e6-673c-4aa8-a3f2-079bcdd5cf31', 'Because the author did not know English', false, 'd2a04994-fdc8-4398-be04-62de6e52f0ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db078dbf-de81-4bda-9d92-b55ea315bd5a', 'To show that Mr. Gessler could not speak', false, 'd2a04994-fdc8-4398-be04-62de6e52f0ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('24578cbc-16e4-4359-a7c8-8d8b758054d9', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Hard', 'Match Column I (Literary / Poetic Elements) with Column II (Symbolic Interpretations):
(a) Gessler''s Last Boots  -> (i) Transcendent masterpieces of leather art created at the cost of the artist''s life
(b) Big Advertised Firms  -> (ii) The soulless machinery of corporate commercialism
(c) Cool Shade in Summer  -> (iii) Trees as generous, unconditional providers of comfort
(d) Leaves to Rake in Fall-> (iv) The mundane domestic chore contrasted with poetic wonder', 'Boots = artistic masterpiece; Big firms = industrial greed; Shade = natural benevolence; Leaves = domestic reality.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59a76538-13bf-416f-a18b-7fe77368efbf', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '24578cbc-16e4-4359-a7c8-8d8b758054d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e40aeed-73f7-4118-af6a-d56d45ce348f', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '24578cbc-16e4-4359-a7c8-8d8b758054d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aff96671-f72d-421d-af99-ee915c2c7440', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '24578cbc-16e4-4359-a7c8-8d8b758054d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c44da355-a9c4-4368-be3c-8f72e556ae4d', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '24578cbc-16e4-4359-a7c8-8d8b758054d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4aac696-8f4e-4adb-99d4-5b84f9caeecf', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Hard', 'Read the statements regarding Shirley Bauer''s poem ''Trees'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bb44811-a11a-4f71-a789-ca8fc5a419bb', 'Statements 1 and 2 only', true, 'd4aac696-8f4e-4adb-99d4-5b84f9caeecf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d16977e0-04d3-4fbd-ade4-346457f2dc72', 'Statements 2 and 3 only', false, 'd4aac696-8f4e-4adb-99d4-5b84f9caeecf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4a00f73-47f5-473d-8340-bb085202e2b9', 'Statements 1 and 3 only', false, 'd4aac696-8f4e-4adb-99d4-5b84f9caeecf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ce82b31-e75c-492f-86bd-7ddde6757f9b', 'All Statements 1, 2, and 3', false, 'd4aac696-8f4e-4adb-99d4-5b84f9caeecf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aebaeaef-0d40-459d-9f61-9f40670710ca', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Hard', 'Transform the complex sentence into a SIMPLE SENTENCE:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4e760cb-8c94-48e8-bb80-43b0c1efa52e', '''Having spent all his money on fine leather and rent, Mr. Gessler had no money left for food.''', true, 'aebaeaef-0d40-459d-9f61-9f40670710ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c86a4c19-52bf-4a65-a318-7258d8c0d235', '''Mr. Gessler spent all money so he had no food.''', false, 'aebaeaef-0d40-459d-9f61-9f40670710ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f08c09e7-5954-4517-a0ab-6f671cb1a6b6', '''Mr. Gessler had no food and he spent money.''', false, 'aebaeaef-0d40-459d-9f61-9f40670710ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a98f8607-a3a3-4568-9dba-5c14d81b54a0', '''Since Mr. Gessler spent money he had no food.''', false, 'aebaeaef-0d40-459d-9f61-9f40670710ca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5a98cca-5f2e-4131-91ba-269f9c2a7b23', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Hard', 'Identify the grammatical role of the underlined clause in: ''He gave him a piece of leather **which was of magnificent quality**.''', '''Which was of magnificent quality'' is a defining relative clause qualifying the noun ''leather''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da27c732-29d9-4ce3-b7e1-11a9eb61ad9a', 'Adjective (Relative) Clause modifying the antecedent noun ''leather''', true, 'a5a98cca-5f2e-4131-91ba-269f9c2a7b23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d1505fd-04db-4bdc-9a22-1612117c52f2', 'Noun Clause acting as subject', false, 'a5a98cca-5f2e-4131-91ba-269f9c2a7b23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23779fde-d015-4cc8-bea0-0889ff59c304', 'Adverb Clause of Condition', false, 'a5a98cca-5f2e-4131-91ba-269f9c2a7b23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a7a7cac-0a17-42e1-8799-0eaf9963c975', 'Prepositional Phrase', false, 'a5a98cca-5f2e-4131-91ba-269f9c2a7b23');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1454e87f-0c4e-49f0-9fe1-9f448f21bfc6', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Hard', 'What is the economic tragedy highlighted when Mr. Gessler explains:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16ea54a2-64cb-44e2-b674-5bd8fb29bbec', 'Information asymmetry and marketing manipulation in industrial economics: consumer demand is captured by mass advertising monopolies rather than organic product merit, bankrupting true artisans', true, '1454e87f-0c4e-49f0-9fe1-9f448f21bfc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80774a54-d9cd-44b4-902e-fab8c6cfa4c1', 'That shoemakers should never buy leather', false, '1454e87f-0c4e-49f0-9fe1-9f448f21bfc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6bb6f25-7db4-48ea-b4e4-ca0d9f2fff41', 'That boots should only be made in winter', false, '1454e87f-0c4e-49f0-9fe1-9f448f21bfc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2681e7c-a754-438b-95f4-4a0f660cfe11', 'That all advertising is illegal', false, '1454e87f-0c4e-49f0-9fe1-9f448f21bfc6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8d07ab07-2e47-49f0-a195-57cf12e07cd3', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Hard', 'In the poem ''Trees'', what dual perspective is juxtaposed in the lines about autumn:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4442a707-f8a8-49b2-84a4-f29702bafd75', 'A charming contrast between artistic aesthetic appreciation and practical domestic labor evoked by the exact same natural phenomenon', true, '8d07ab07-2e47-49f0-a195-57cf12e07cd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93f40159-6db8-42bc-a721-583f8c7dda0c', 'A bitter quarrel between parents', false, '8d07ab07-2e47-49f0-a195-57cf12e07cd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76c8bfa8-9b4e-40c4-a363-c5a34f93a7b6', 'That fathers dislike trees', false, '8d07ab07-2e47-49f0-a195-57cf12e07cd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d05f0de1-8450-4be0-89f0-038436d02553', 'That mothers paint trees on walls', false, '8d07ab07-2e47-49f0-a195-57cf12e07cd3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6bc6b398-5b2c-439b-b6c6-00c3be00dafe', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Hard', 'Why did the author order several extra pairs of boots from Mr. Gessler whenever he visited, even when he did not urgently need them?', 'The narrator''s repeated orders were altruistic acts of quiet patronage to sustain the noble craftsman.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3ef0cb0-fee6-48b2-903c-90c39be175f7', 'Out of deep, compassionate respect and affection, wanting to support the struggling master craftsman financially without wounding his fierce artisanal pride', true, '6bc6b398-5b2c-439b-b6c6-00c3be00dafe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ffd6c81-a000-408b-a3e0-1a1087a0e9a7', 'Because he wanted to sell them for profit', false, '6bc6b398-5b2c-439b-b6c6-00c3be00dafe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ad23305-a723-4093-9e3d-d1e1441667b7', 'Because he collected 1,000 shoes', false, '6bc6b398-5b2c-439b-b6c6-00c3be00dafe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9786148-de5e-4075-970d-9e546cfe49bc', 'Because Mr. Gessler forced him to buy', false, '6bc6b398-5b2c-439b-b6c6-00c3be00dafe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ed7e7cf-7744-4f00-a106-8704566cc3af', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Hard', 'What is the literary significance of the single-word title ''QUALITY'' in Galsworthy''s story?', '''Quality'' operates as a profound philosophical motif: physical excellence fused with uncompromising spiritual and vocational integrity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5a4296a-1798-4794-b4b0-522291d4f325', 'It represents not merely the physical excellence of boots, but the moral, spiritual, and artistic integrity of an uncorrupted human soul dedicated entirely to perfection', true, '0ed7e7cf-7744-4f00-a106-8704566cc3af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae98f5ea-7212-4045-aa96-efba387cb7dd', 'It is the name of a shoe brand in London', false, '0ed7e7cf-7744-4f00-a106-8704566cc3af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0651f6d4-ec0a-4eb2-ad95-f72322ee5ead', 'It refers to the price of leather in shops', false, '0ed7e7cf-7744-4f00-a106-8704566cc3af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88e3a00f-e71a-465f-9aad-36048bccedf2', 'It means making shoes quickly', false, '0ed7e7cf-7744-4f00-a106-8704566cc3af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd1206a5-05ec-43bc-9e9f-3821e78bd1c4', 'Class 7', 'English', 'Chapter 5: Quality & Trees', 'Hard', 'What overarching humanist philosophy unites both selections in Chapter 5 of NCERT Class 7 English?', 'Chapter 5 integrates environmental gratitude with reverence for uncorrupted human devotion to craftsmanship and beauty.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbca9d0d-503d-4139-85db-1943272fb798', 'Reverence for authentic value—whether celebrating the generous, quiet beauty of trees enriching the ecosystem or honoring the noble integrity of dedicated craftsmen who pour their souls into their art', true, 'dd1206a5-05ec-43bc-9e9f-3821e78bd1c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b096f13-1201-4d46-b2a7-cbd3a3d46c52', 'That factories are always superior to human hands', false, 'dd1206a5-05ec-43bc-9e9f-3821e78bd1c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c41e440-bff7-445b-8455-2883e2d1d8a3', 'That trees should be chopped down for paper', false, 'dd1206a5-05ec-43bc-9e9f-3821e78bd1c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b77ea058-e1b7-477f-b3ba-028a4596a886', 'That shoes should be made only of wood', false, 'dd1206a5-05ec-43bc-9e9f-3821e78bd1c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a00a1126-9b91-430b-bb93-e67dc4671cf2', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Easy', 'Which is the CLOSEST planet to the Sun in our solar system, completing one orbit in just 88 Earth days?', 'Mercury orbits closest to the Sun at an average distance of ~57.9 million km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00bd6735-4cbe-4011-9a21-c96094e72c74', 'Mercury', true, 'a00a1126-9b91-430b-bb93-e67dc4671cf2');
