INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e970b2f9-a6be-474e-957b-df6794b948a0', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Medium', 'Where is the main Asteroid Belt in our solar system situated?', 'The Asteroid Belt is a circumstellar disc located between the orbits of Mars and Jupiter containing Ceres, Vesta, Pallas, and Hygiea.', NOW()) ON CONFLICT DO NOTHING;
