INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6c43f7c1-6775-47b3-be30-d9a078197f7f', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Medium', 'Why was PLUTO reclassified from a full ''planet'' to a ''dwarf planet'' by the International Astronomical Union (IAU) in August 2006?', 'Pluto shares its orbital zone with numerous trans-Neptunian Kuiper belt objects, failing the dynamic orbit clearance criterion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('321163e2-8ead-426a-9a2e-81d811e6da5f', 'It failed to meet the third criterion: it has NOT ''cleared the neighborhood around its orbit'' of other Kuiper Belt debris', true, '6c43f7c1-6775-47b3-be30-d9a078197f7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34f35b8f-9d98-403f-b6ae-13fa1861c30e', 'Because Pluto melted completely', false, '6c43f7c1-6775-47b3-be30-d9a078197f7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b1d3c1d-89de-4d19-b568-336a202a3846', 'Because Pluto stopped orbiting the Sun', false, '6c43f7c1-6775-47b3-be30-d9a078197f7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ea4529a-b972-40bd-8d51-c3e5a083f836', 'Because Pluto collided with Mars', false, '6c43f7c1-6775-47b3-be30-d9a078197f7f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c08a2cb-30a0-4f41-8810-93686b828e19', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Medium', 'What is an ''Astronomical Unit'' (AU) commonly used in planetary astronomy?', '1 AU = 149,597,870,700 metres (~150 million km), the baseline metric for interplanetary distances.', NOW()) ON CONFLICT DO NOTHING;
