INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d1beed5-9762-4fac-9170-9619ba94bade', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Medium', 'What is the nuclear reaction that powers our Sun and all main-sequence stars in the universe, releasing enormous light and heat?', 'Proton-proton chain nuclear fusion converts 600 million tons of hydrogen into helium every second in the Sun''s core.', NOW()) ON CONFLICT DO NOTHING;
