INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d3c5bf0-5632-48bf-8323-31fd835150e9', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'What is the ''Chandrasekhar Limit'' discovered by Indian-American Nobel Laureate Subrahmanyan Chandrasekhar?', 'The Chandrasekhar limit (M ≈ 1.44 M_☉) dictates the relativistic quantum threshold separating white dwarf stability from supernova collapse.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c54fb8a0-9072-40f6-a1ed-82146c9b69ab', 'The maximum stable theoretical mass (approx. 1.44 Solar Masses) of a White Dwarf star, beyond which electron degeneracy pressure fails and the star collapses into a Neutron Star or Black Hole', true, '1d3c5bf0-5632-48bf-8323-31fd835150e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a257cdf-596d-4e3a-9e86-dd437e761cc9', 'The maximum speed of a rocket', false, '1d3c5bf0-5632-48bf-8323-31fd835150e9');
