INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9430a308-d30b-4991-8201-1489f08d6c78', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'Match Column I (Cosmic Mysteries) with Column II (Astrophysical Explanations):
(a) Dark Matter        -> (i) Invisible mass (~27% of universe) inferred via gravitational lensing
(b) Dark Energy        -> (ii) Unknown force (~68% of universe) driving accelerated cosmic expansion
(c) Cosmic Inflation   -> (iii) Exponential superluminal expansion of spacetime 10⁻³⁶ s after Big Bang
(d) Gravitational Waves-> (iv) Ripples in spacetime fabric generated by colliding black holes (LIGO)', 'Dark Matter = gravitational scaffolding; Dark Energy = cosmic acceleration; Inflation = exponential early growth; Gravitational waves = spacetime ripples.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a3c8638-ff0b-4d65-9aa6-9dfa231e4889', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '9430a308-d30b-4991-8201-1489f08d6c78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00660b83-ccf0-42d9-8227-d3de49081735', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '9430a308-d30b-4991-8201-1489f08d6c78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8160b46e-79c7-4355-93d1-ba8413472920', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '9430a308-d30b-4991-8201-1489f08d6c78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22f7544d-72ca-4a8e-9583-67af739fa18f', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '9430a308-d30b-4991-8201-1489f08d6c78');
