INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b95e22af-d80c-40ec-9515-4683c0427b27', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'What is the ''Habitable Zone'' (or Goldilocks Zone) around a host star in astrophysics?', 'Circumstellar Habitable Zone: stellar radiative equilibrium permitting liquid water (0°C to 100°C) on rocky exoplanets.', NOW()) ON CONFLICT DO NOTHING;
