INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dad7b116-87f0-4eb7-9774-1ae93d8a78bb', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'What was the landmark breakthrough achieved by the Event Horizon Telescope (EHT) collaboration in 2019?', 'The EHT linked radio telescopes globally via VLBI, capturing the first direct shadow of the 6.5-billion-solar-mass black hole in M87*.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('366e7225-58d9-48e9-ae9e-876d1c099153', 'Capturing the world''s FIRST DIRECT SHADOW IMAGE of a Supermassive Black Hole (in galaxy M87)', true, 'dad7b116-87f0-4eb7-9774-1ae93d8a78bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54e975d8-e10e-4d45-aa5e-7cc05133283e', 'Landing humans on Jupiter', false, 'dad7b116-87f0-4eb7-9774-1ae93d8a78bb');
