INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('617021eb-4538-4263-89c0-b8899b69c867', 'Indigenous, frugal engineering excellence and world-leading deep-space exploration capabilities at unparalleled cost-efficiency', true, 'd9a143fc-161d-455c-b5c8-6e9fed50589e');
