INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0fcf25d0-b45e-4056-b418-68b4fcbe554c', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'What is ''Gravitational Lensing'' predicted by Albert Einstein''s General Relativity?', 'General Relativity: massive energy densities curve spacetime geodesics, bending and magnifying background electromagnetic photons.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9efa6fb7-e602-4e04-9247-9093204d8dd3', 'Massive celestial objects (like galaxy clusters) warp the fabric of spacetime around them, bending the path of light from background objects like a giant cosmic lens', true, '0fcf25d0-b45e-4056-b418-68b4fcbe554c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d74ea601-ab1b-4704-ac79-9df937940110', 'Looking at stars through a pair of reading glasses', false, '0fcf25d0-b45e-4056-b418-68b4fcbe554c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0b1a87f-74d0-4fb3-8528-9d3f00adcd81', 'Gravity making planets shine brighter', false, '0fcf25d0-b45e-4056-b418-68b4fcbe554c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84eddfdc-d03a-40d2-894c-79a3c39daadb', 'Stars turning into glass lenses', false, '0fcf25d0-b45e-4056-b418-68b4fcbe554c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3734aab6-bfeb-4ab9-9188-b878370a79ae', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'What is the theoretical maximum velocity limit for the propagation of any physical information, matter, or light across the universe?', 'Special Relativity: c = 299,792,458 m/s represents the universal invariant speed limit of causality.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d309f2ee-1bc3-41ba-ba15-653467451dfa', '299,792,458 metres per second (approx. 300,000 km/s - The Speed of Light ''c'')', true, '3734aab6-bfeb-4ab9-9188-b878370a79ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b0c9d2d-11c2-4f06-861b-d35b80514375', '1,000 km/s', false, '3734aab6-bfeb-4ab9-9188-b878370a79ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7545085a-b4d4-4aaf-b6d7-d3267f6b71ef', '100,000 km/s', false, '3734aab6-bfeb-4ab9-9188-b878370a79ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d07a0c6c-a8ad-44ac-bbc6-565d0866bd52', 'Infinite speed', false, '3734aab6-bfeb-4ab9-9188-b878370a79ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecbf21bf-979e-46c8-9497-59bd0c769597', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'Why do astronauts experience weightlessness inside the International Space Station (ISS) in Low Earth Orbit?', 'Earth''s gravity at 400 km is ~90% of sea level; apparent microgravity results from continuous orbital free-fall.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e1e1657-ef5a-480d-89c2-923841e49a08', 'The ISS and astronauts are in a continuous, perpetual state of FREE FALL around the Earth (falling forward at orbital speed equal to Earth''s curvature)', true, 'ecbf21bf-979e-46c8-9497-59bd0c769597');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fbe134e-66d4-4b4a-8d0b-d85147dcd5a7', 'Because there is zero gravity in orbit', false, 'ecbf21bf-979e-46c8-9497-59bd0c769597');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6727a5e3-402c-42dd-88a2-7592b0967dcb', 'Because the ISS has an anti-gravity engine', false, 'ecbf21bf-979e-46c8-9497-59bd0c769597');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d65d448d-f649-4105-80d3-c2c8c4d20342', 'Because Earth''s gravity stops at 100 km', false, 'ecbf21bf-979e-46c8-9497-59bd0c769597');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa3a9c35-68d2-4e0d-90d2-355b6c21aeab', 'Class 7', 'GK', 'Chapter 5: Science, Space Technology, Astronomy & The Universe', 'Hard', 'What ultimate cosmic perspective is illuminated by modern Space Science, Astronomy, and the Universe?', 'Astrophysics reveals our cosmological kinship: nucleosynthesis in dying stars created the biogenic elements (C, N, O, Fe) composing human life.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ac9488d-cf4d-45d1-a617-7d6b13db7bfe', 'Human beings are composed of ''stardust'' (elements forged inside exploding ancient stars), inhabiting a fragile ''Pale Blue Dot'' in a vast, majestic 13.8-billion-year-old cosmic web', true, 'aa3a9c35-68d2-4e0d-90d2-355b6c21aeab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9314af97-4a0f-4d07-80cf-7a52f4275cd7', 'Earth is the absolute geometric center of the universe', false, 'aa3a9c35-68d2-4e0d-90d2-355b6c21aeab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c4c5082-ff46-4330-a21e-88e9429ea44c', 'Space exploration has revealed all secrets of the universe', false, 'aa3a9c35-68d2-4e0d-90d2-355b6c21aeab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abec8aee-5730-4c4e-9a6b-68a8cc7e93ff', 'The universe will stop existing tomorrow', false, 'aa3a9c35-68d2-4e0d-90d2-355b6c21aeab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('26de79da-ec43-4ac1-86bc-f5228469275c', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'Between the 8th and 18th centuries, what two main categories of structural buildings were constructed by kings and their officers?', 'Medieval monument architecture comprised royal monumental structures (forts, tombs, palaces) and public civic infrastructure (tanks, stepwells, mosques, bazaars).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c3745b1-7d36-4049-8cd8-6840173d10ef', '1. Forts, palaces, and royal tombs (safe, protected places of grand rest) ; 2. Temples, mosques, tanks, wells, caravan serais, and bazaars (structures meant for public use)', true, '26de79da-ec43-4ac1-86bc-f5228469275c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('720143cd-74e2-4cdd-9924-b7769fec7cf4', 'Only wooden huts and tents', false, '26de79da-ec43-4ac1-86bc-f5228469275c');
