INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53d71a50-c436-49d5-aca9-7c3e45476536', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'What was the traditional Indian architectural style where roofs, doors, and windows were made by placing a horizontal beam across two vertical pillars called?', 'Trabeate/Corbelled architecture utilizes post-and-lintel structural beams across vertical support columns.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab259ebd-4784-4da5-94a8-d27cf92468c8', 'Trabeate (or Corbelled) Architectural Style', true, '53d71a50-c436-49d5-aca9-7c3e45476536');
