INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2806e648-e5c9-4616-98a7-be017e8b54d7', 'Gothic Style', false, '53d71a50-c436-49d5-aca9-7c3e45476536');
