INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('354ae509-f40d-4d4f-9322-6591a1c0db46', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'From the 12th century, what new technological architectural style emerged where the weight of the superstructure above doors and windows was carried by true circular ARCHES with a central Keystone?', 'Arcuate architecture distributes structural loads through true compressive voussoir arches stabilized by a central keystone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de283973-393e-4d90-9585-a0750a980c5f', 'Arcuate Architectural Style', true, '354ae509-f40d-4d4f-9322-6591a1c0db46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1e66673-31bc-4a42-bd16-5894e9c8b317', 'Trabeate Style', false, '354ae509-f40d-4d4f-9322-6591a1c0db46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d104ceaa-02b6-4122-b89b-a0c028cdf9dc', 'Corbelled Style', false, '354ae509-f40d-4d4f-9322-6591a1c0db46');
