INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('914993b1-47c0-489e-b794-9cb14b4b11d2', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'What high-quality cementing material mixed with stone chips became increasingly used in 12th-century large-scale construction, hardening rapidly into stone-like mortar?', 'Limestone cement mortar set rapidly with great tensile resilience, facilitating massive domes and arches.', NOW()) ON CONFLICT DO NOTHING;
