INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4f880b3-cbbe-4ba7-bbaf-25f86d374582', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'What is a large traditional multi-storied stepped well with underground descending flights of stone stairs to reach the water reservoir called?', 'Baolis/Vavs are sub-surface stepped wells engineered for arid water storage, subterranean cooling, and public respite.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9407f4bc-c4ea-4a8f-9ffa-6717a09dfbe0', 'Baoli (or Vav / Stepwell)', true, 'c4f880b3-cbbe-4ba7-bbaf-25f86d374582');
