INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7b41acb6-b128-4228-8225-afd3afac5762', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'What is the fine art technique of inlaying polished colored stones (like lapis lazuli, onyx, and jasper) into marble depressions to create floral patterns called?', 'Pietra Dura (Parchin Kari) inlays semi-precious gem stones into carved marble cavities to create radiant natural motifs.', NOW()) ON CONFLICT DO NOTHING;
