INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('759da518-33d2-4610-a7eb-3c5836498aff', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'What was the formal garden layout favored by Mughal emperors, divided symmetrically into four equal quadrants by artificial water channels, called?', 'Chahar Bagh is the quadripartite symmetrical garden layout divided by axial intersecting water rills.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ecfee85-5b1d-459b-a04f-408f5ea1866e', 'Chahar Bagh (Charbagh)', true, '759da518-33d2-4610-a7eb-3c5836498aff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95127689-fad2-40e0-b930-0df70ab33a8c', 'Botanical Garden', false, '759da518-33d2-4610-a7eb-3c5836498aff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25f11d6b-1c98-4b78-b9f7-0891b28b7859', 'Hanging Gardens', false, '759da518-33d2-4610-a7eb-3c5836498aff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aecd49d-eefb-4e3d-a335-6c934cc72e3f', 'Rock Garden', false, '759da518-33d2-4610-a7eb-3c5836498aff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30d1f21c-ef2b-4bc3-a337-c4de316e6f76', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'What holy central Sikh shrine and stepped Amrit Sarovar tank was constructed at Amritsar under Guru Arjan Dev in the late 16th century?', 'Guru Arjan Dev constructed the Harmandir Sahib in the center of the holy Amrit Sarovar lake in Amritsar.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7e455ea-3d80-48ca-bd7e-74dc383a4ef2', 'Harmandir Sahib (The Golden Temple)', true, '30d1f21c-ef2b-4bc3-a337-c4de316e6f76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f62d224c-fef6-4bc7-bb14-c188005705d8', 'Bangla Sahib', false, '30d1f21c-ef2b-4bc3-a337-c4de316e6f76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('273ca326-4f6f-4b57-b6d2-24af9774fd1b', 'Sis Ganj Sahib', false, '30d1f21c-ef2b-4bc3-a337-c4de316e6f76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('400efac5-6b1a-4cd6-8a41-bf5a48a0cf7e', 'Patna Sahib', false, '30d1f21c-ef2b-4bc3-a337-c4de316e6f76');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87a63a6e-ca0f-485a-abb2-f37207ae1c08', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Easy', 'Who built the monumental 73-metre high sandstone Qutb Minar tower in Delhi, initiating its construction around 1199 CE?', 'Qutbuddin Aibak built the base balcony of Qutb Minar in 1199; Iltutmish added three upper storeys c. 1220.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e227b2ab-ba07-4afd-9af5-ad8fd31d115f', 'Qutbuddin Aibak (completed by Iltutmish and repaired by Firuz Tughluq)', true, '87a63a6e-ca0f-485a-abb2-f37207ae1c08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c159b5cd-fb3b-44b0-afd8-c212d8bb57a6', 'Alauddin Khalji', false, '87a63a6e-ca0f-485a-abb2-f37207ae1c08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d81fab34-825d-4251-9c62-6659d996d938', 'Babur', false, '87a63a6e-ca0f-485a-abb2-f37207ae1c08');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9fd4219-f640-4857-b560-fb31ce6edaeb', 'Shah Jahan', false, '87a63a6e-ca0f-485a-abb2-f37207ae1c08');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('351a5c22-8b8d-40d1-845d-1105eb2cc02b', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'How was the massive 90-tonne single granite stone placed atop the 60-metre high Shikhara of the Rajarajeshvara Temple at Thanjavur without modern cranes?', 'Chola master engineers constructed a 4-km earthen inclined gradient from the village of Charupallam to haul the 90-ton monolithic cupola.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5904133a-5084-47d0-94aa-de0f2b8b5a74', 'Architects built an inclined earth ramp (over 4 km long) starting from a nearby village, rolling the heavy stone all the way up on log rollers to the temple pinnacle', true, '351a5c22-8b8d-40d1-845d-1105eb2cc02b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6390b9cc-3fcd-467e-aa14-fddf3900bac1', 'They pulled it with a giant rope from the clouds', false, '351a5c22-8b8d-40d1-845d-1105eb2cc02b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fb405cd-2137-42f8-bdbf-0c8a70f3fef7', 'They dropped it from an airplane', false, '351a5c22-8b8d-40d1-845d-1105eb2cc02b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('038a93bb-a211-41c1-98a5-d624bd1bc448', 'The stone was made of foam', false, '351a5c22-8b8d-40d1-845d-1105eb2cc02b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('290cd0be-5c4b-4a32-8c95-a0c720457389', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'Why did medieval kings target, desecrate, and loot the main structural temples of rival kingdoms during military invasions?', 'Monumental temples embodied royal majesty and divine charisma; their targeted destruction symbolized the total subjugation of the rival state.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2e1b9ed-0d63-4c14-9ba2-4514be60c9ec', 'Temples were supreme symbols of a king''s political power, imperial wealth, and divine legitimacy; destroying the rival''s temple proclaimed total conquest and humiliated the defeated dynasty', true, '290cd0be-5c4b-4a32-8c95-a0c720457389');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ea3431d-2f0d-4980-b919-641ddacc3ab7', 'Because rival soldiers hid inside temples', false, '290cd0be-5c4b-4a32-8c95-a0c720457389');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a289c70-f9ae-45c7-987b-3636e3ff36df', 'Because temples were made of wood', false, '290cd0be-5c4b-4a32-8c95-a0c720457389');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a4bfe1d-f088-4ecd-a61e-28f9e6ff5e6c', 'Because kings wanted to build roads over them', false, '290cd0be-5c4b-4a32-8c95-a0c720457389');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8cd8d11b-7a5d-42f2-9c65-a1bc3c4a1122', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'When the 9th-century Pandyan King Shrimara Shrivallabha invaded Sri Lanka and defeated King Sena I, what precious Buddhist relic did he carry away?', 'The Mahavamsa chronicles that Shrimara seized the golden Buddha image from the Jewel Palace, which Sena II later invaded Madurai to recover.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3081e71a-bd40-4281-bb5e-1df9458b0713', 'The colossal jewel-encrusted Golden Statue of the Buddha from the Jewel Palace and all golden images from monasteries', true, '8cd8d11b-7a5d-42f2-9c65-a1bc3c4a1122');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('920b382d-d1a4-4fda-9ead-2542139ca1d1', 'A silver ship', false, '8cd8d11b-7a5d-42f2-9c65-a1bc3c4a1122');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('839eb35e-6f2b-4cf0-bf2b-727ac1f192be', 'A sacred wooden chariot', false, '8cd8d11b-7a5d-42f2-9c65-a1bc3c4a1122');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f040c702-b290-474d-91e6-4c33d2c359b2', 'A bronze bell only', false, '8cd8d11b-7a5d-42f2-9c65-a1bc3c4a1122');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('084a7d09-51b6-4708-a7f8-e299a5d45682', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'Why did the 11th-century Chola King Rajendra I build a magnificent Shiva temple in his capital and fill it with captured statues from defeated rulers (Chalukyas, Palas, Kalingas)?', 'Rajendra I transformed his imperial temple into a pan-subcontinental trophy pavilion housing deities seized from vanquished rivals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45efc758-bb3f-4535-8513-3a50b4388448', 'To celebrate imperial pan-Indian hegemony by displaying captured sacred trophies (Ganesha, Durga, Nandi, Bhairava, Kali) from all four corners of the subcontinent', true, '084a7d09-51b6-4708-a7f8-e299a5d45682');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('757db26f-b64d-40ed-8e84-dcfe961ef54a', 'Because he did not have sculptors in his kingdom', false, '084a7d09-51b6-4708-a7f8-e299a5d45682');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f336625-b4be-4275-be1d-a4fca837a317', 'To sell them in foreign markets', false, '084a7d09-51b6-4708-a7f8-e299a5d45682');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4189fc10-3549-488d-92cf-66326a7bf23e', 'To hide them from his people', false, '084a7d09-51b6-4708-a7f8-e299a5d45682');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4373132f-2240-4802-9f8c-5a725e397d5c', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'In Shah Jahan''s newly constructed capital city of Shahjahanabad (Delhi), where was the grand imperial Red Fort situated along the river Yamuna?', 'Shah Jahan adapted the riverfront garden topology, positioning the imperial palace directly on the Yamuna to control riverine access.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c82f239-5093-4c41-bc2f-a680e698c12c', 'Directly overlooking the riverbank of Yamuna in a ''River-Front Garden'' layout, with only select favored princes (like Dara Shikoh) granted river access', true, '4373132f-2240-4802-9f8c-5a725e397d5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dde7440-3030-47ea-9a7e-40812271072e', 'In the middle of a desert away from water', false, '4373132f-2240-4802-9f8c-5a725e397d5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f1a78ef-889b-47d0-be6b-48a030cb5bd4', 'On top of the Himalayas', false, '4373132f-2240-4802-9f8c-5a725e397d5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51e6c57e-70b2-46dd-a386-4dfe116d8636', 'Inside an underground cave', false, '4373132f-2240-4802-9f8c-5a725e397d5c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aea6f11a-a678-43fc-b2f4-ccd0e66202af', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What architectural connection did Shah Jahan create between the Emperor''s Throne (Diwan-i Aam) and divine justice in the Red Fort at Delhi?', 'Pietra dura inlays of Orpheus taming beasts behind Shah Jahan''s jharokha symbolized royal justice reconciling fierce discord into harmonious peace.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42e324d5-9abc-4130-be92-b5d18b505ea8', 'Behind the throne was a series of Pietra Dura panels depicting the Greek god Orpheus playing his lute (taming savage beasts), symbolizing that the King''s justice treats the high and low as equals in peace', true, 'aea6f11a-a678-43fc-b2f4-ccd0e66202af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96181fd1-ca45-480e-aeeb-4e43b3403a2d', 'The throne was carved from a single diamond', false, 'aea6f11a-a678-43fc-b2f4-ccd0e66202af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13452936-9213-4d35-a2b5-be28fec8bfe7', 'The throne had cannons pointed at the crowd', false, 'aea6f11a-a678-43fc-b2f4-ccd0e66202af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec0e65e4-89d9-436e-9918-19da78762136', 'The throne was suspended in mid-air with magnets', false, 'aea6f11a-a678-43fc-b2f4-ccd0e66202af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88868a1e-5217-4824-89fb-958c36023c97', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What is the ''Bangla Dome'' / thatched roof architectural adaptation adopted by Mughal emperors into their stone palace architecture?', 'Mughal architects adapted regional Bengali vaulted hut profiles (''Bangla dome'') into imperial marble and sandstone pavilions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27a34b2a-64b8-491e-bac3-7165351e169d', 'A graceful curved roof modeled on the traditional curved bamboo thatched roofs of Bengal huts, used in Agra Fort and Fatehpur Sikri', true, '88868a1e-5217-4824-89fb-958c36023c97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('551912f4-0a5a-41d0-a0de-54c47b732ec3', 'A flat stone roof', false, '88868a1e-5217-4824-89fb-958c36023c97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c3ef5d1-6645-49b4-83b7-89c66b5b4382', 'A pyramid made of glass', false, '88868a1e-5217-4824-89fb-958c36023c97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3a304c2-2351-44db-9afd-a778b245fca1', 'A tower made of metal', false, '88868a1e-5217-4824-89fb-958c36023c97');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fb2635b9-f089-4af7-8be4-9c77c9d08f47', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'How did architectural styles cross-pollinate across regions during the 16th–17th centuries (e.g. temples in Vrindavan near Mathura)?', 'Cross-cultural architectural synthesis: Govind Deva temple''s ribbed vaulting in red sandstone mirrored Akbar''s Fatehpur Sikri palace engineering.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c43b6e07-57bf-41f5-8a50-e4d99f7f51e2', 'Temples in Vrindavan (like the Govind Deva temple, 1590) featured high intersecting ceiling arches constructed in architectural styles identical to Mughal palaces in Fatehpur Sikri', true, 'fb2635b9-f089-4af7-8be4-9c77c9d08f47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd8c9964-ab80-4502-a749-c06aba1c9e43', 'Temples were built in Greek and Roman style', false, 'fb2635b9-f089-4af7-8be4-9c77c9d08f47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c80f70ee-7898-4a85-803f-ba2391b7a313', 'Temples were imported from Europe', false, 'fb2635b9-f089-4af7-8be4-9c77c9d08f47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e97f75e-0475-410a-8ba9-192462f0d946', 'Temples were built with no roofs', false, 'fb2635b9-f089-4af7-8be4-9c77c9d08f47');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87498935-5fbf-4aee-90cb-b42d163bc7f3', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What was the ''Garbhagriha'' in a classical Hindu temple?', 'The Garbhagriha (womb-chamber) is the central, sacred nucleus of a Hindu temple enshrining the principal consecrated deity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d886912-7455-45df-8b1e-0fedaf39220f', 'The innermost sacred sanctum sanctorum where the main deity''s idol / murti was installed and consecrated for ritual worship', true, '87498935-5fbf-4aee-90cb-b42d163bc7f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fddcb02-3fd7-4718-a284-54c0c808e1cd', 'The kitchen of the temple', false, '87498935-5fbf-4aee-90cb-b42d163bc7f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c4d6379-e444-4766-aad4-f0430db4ab18', 'The royal stable for elephants', false, '87498935-5fbf-4aee-90cb-b42d163bc7f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32a7eb84-2990-4158-b5bb-5bae0c1b3c4d', 'The outdoor garden', false, '87498935-5fbf-4aee-90cb-b42d163bc7f3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a11d46f5-ace8-46a5-92fa-9f6c951cc9f6', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What was the ''Mandapa'' in classical temple architecture?', 'The Mandapa is the pillared congregational hall preceding the garbhagriha in Nagara and Dravida temple layouts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67734418-cb86-422b-bd78-73b740e8b2a4', 'The pillared assembly hall where devotees gathered, sacred dances were performed, and religious rituals were conducted', true, 'a11d46f5-ace8-46a5-92fa-9f6c951cc9f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4258f188-069a-4ee3-ae66-e14e270ad735', 'The main tower over the deity', false, 'a11d46f5-ace8-46a5-92fa-9f6c951cc9f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c1c64eb-aa61-46de-9fff-07175d076275', 'The water well outside', false, 'a11d46f5-ace8-46a5-92fa-9f6c951cc9f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4407902a-212d-4d82-9456-02221e34d084', 'The outer boundary wall', false, 'a11d46f5-ace8-46a5-92fa-9f6c951cc9f6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('152ea80b-4654-41fe-bf5a-526ddbc20827', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What was the ''Shikhara'' (or Vimana in South India)?', 'The Shikhara/Vimana is the towering architectural mountain spire rising majestically above the central sanctum.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55036c1d-3dac-423a-9c96-0fa3ee0b9b5f', 'The towering, rising conical superstructure/spire constructed directly over the Garbhagriha sanctum sanctorum', true, '152ea80b-4654-41fe-bf5a-526ddbc20827');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1f86a39-4248-4d7d-8639-77ef9bccc446', 'The temple entrance gate', false, '152ea80b-4654-41fe-bf5a-526ddbc20827');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12fb3969-af17-4af9-9a9f-6e5af657b328', 'The water tank', false, '152ea80b-4654-41fe-bf5a-526ddbc20827');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b03546a5-e761-4b7e-87be-20e7b95ff124', 'The temple floor', false, '152ea80b-4654-41fe-bf5a-526ddbc20827');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2cc4ef6-f82c-4fd3-ae0d-2021e60da864', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What was the ''Gopuram'' in South Indian Dravida temple complexes (such as Madurai and Thanjavur)?', 'Gopurams are monumental, multi-tiered sculpted gateway towers dominating the perimeter walls of Dravidian temple cities.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e1c21ff-89c5-4a24-ad9d-df8d2fd7ae0d', 'The towering, colossal, richly sculpted monumental entrance gateway leading into the temple enclosure', true, 'b2cc4ef6-f82c-4fd3-ae0d-2021e60da864');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('873fd0ae-036a-4c89-900b-149e313c4241', 'The inner room of the priest', false, 'b2cc4ef6-f82c-4fd3-ae0d-2021e60da864');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40133a27-1808-4b62-8adf-4c2c9fb7dd89', 'The stone pillar for tying horses', false, 'b2cc4ef6-f82c-4fd3-ae0d-2021e60da864');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb9d3f7d-05b3-426c-81ee-bd64b9de67a8', 'The kitchen for preparing prasad', false, 'b2cc4ef6-f82c-4fd3-ae0d-2021e60da864');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca849bab-9c96-4999-a9e8-035a414924d8', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What is the famous ''Rani ki Vav'' (The Queen''s Stepwell) in Patan, Gujarat, recognized as a UNESCO World Heritage site?', 'Rani ki Vav (built by Queen Udayamati c. 1063 CE) is a 7-tiered inverted temple stepwell celebrating subterranean sacred hydraulics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e429ba26-9f0a-405f-8622-4adde5ebf283', 'An intricately carved seven-level inverted underground stepwell temple adorned with over 500 principal sculptures of Vishnu and his avatars', true, 'ca849bab-9c96-4999-a9e8-035a414924d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af53b442-ab1a-44c2-8c88-24ce2ccc3b1c', 'A modern water dam', false, 'ca849bab-9c96-4999-a9e8-035a414924d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75010b89-403e-4b5b-a725-5e4402c33e75', 'A floating boat', false, 'ca849bab-9c96-4999-a9e8-035a414924d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb711778-478a-4077-873c-2200fe44ef5f', 'A royal palace on a mountain', false, 'ca849bab-9c96-4999-a9e8-035a414924d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e972010-1ddc-4213-95f7-f6f769ceaf8d', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What is the ''Pishtaq'' in Indo-Islamic architecture?', 'A Pishtaq is a monumental projecting formal portal framing a central vaulted iwan arch.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e19da4e-ff5f-43ad-9c64-9bd0ceb7172a', 'The towering, majestic monumental arched gateway framing the entrance of a mosque, tomb, or palace (such as at Humayun''s Tomb and Taj Mahal)', true, '1e972010-1ddc-4213-95f7-f6f769ceaf8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ad6889b-aee0-4c6d-8b38-f0c8a3942719', 'The minaret staircase', false, '1e972010-1ddc-4213-95f7-f6f769ceaf8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0db028c7-47b6-4023-b887-6c142f08a7d1', 'The floor carpet', false, '1e972010-1ddc-4213-95f7-f6f769ceaf8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7e13bc3-bda2-4547-9c12-2a42b28a1b9c', 'The water fountain', false, '1e972010-1ddc-4213-95f7-f6f769ceaf8d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd5e31b2-2b6c-48d5-a487-c350c8a7cb2d', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What was the ''Hasht Bihisht'' (Eight Paradises) architectural floor plan introduced during Mughal tomb construction (e.g. Humayun''s Tomb)?', 'Hasht Bihisht is an octagonal radial architectural plan featuring 8 perimeter chambers radiating around a central domed chamber.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4392309-9a47-4b5b-9a90-8affb6d51a93', 'A central octagonal hall surrounded by eight interconnected rooms on two levels, symbolizing the eight heavenly paradises of Islamic cosmology', true, 'dd5e31b2-2b6c-48d5-a487-c350c8a7cb2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19f5285b-03c1-42b0-959d-c81a7dc2f7b9', 'A building with eight doors and no windows', false, 'dd5e31b2-2b6c-48d5-a487-c350c8a7cb2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92c00ae7-66b1-491e-b968-42f3a1dd9d40', 'A garden with eight flowers', false, 'dd5e31b2-2b6c-48d5-a487-c350c8a7cb2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f36b6053-0d52-46df-8bc3-98418dce6d98', 'A fortress with eight cannons', false, 'dd5e31b2-2b6c-48d5-a487-c350c8a7cb2d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ee94902e-8faf-4848-a459-91f578d5e06a', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Medium', 'What was the architectural purpose of constructing magnificent public water reservoirs (such as Hauz Khas and Baolis) by medieval monarchs?', 'Public hydraulic endowments (hauz, baolis, tanks) fused utilitarian water security with the moral prestige of benevolent kingship.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e9200f0-0053-4448-88f9-7b2499bf81fb', 'To ensure reliable water security for urban citizens, while earning universal moral praise, religious merit, and cementing benevolent royal legitimacy', true, 'ee94902e-8faf-4848-a459-91f578d5e06a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71d8a142-256a-4ddc-ab90-888481aa42df', 'To breed exotic sharks', false, 'ee94902e-8faf-4848-a459-91f578d5e06a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0989cfe-39ef-425e-be68-e196519454a2', 'To hold boat races every day', false, 'ee94902e-8faf-4848-a459-91f578d5e06a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('113654fb-4c2a-4e0a-bbc0-eb7548b791e2', 'To flood the city in times of war', false, 'ee94902e-8faf-4848-a459-91f578d5e06a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('adcdeae8-6974-4c23-86b5-323c3f77b19c', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f5abb93-5d28-4f82-ad3c-a3820a085776', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'adcdeae8-6974-4c23-86b5-323c3f77b19c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('779ca7d8-e57f-48b5-b984-96faa2d374ba', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'adcdeae8-6974-4c23-86b5-323c3f77b19c');
