INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3b18b91-bb21-4601-aff5-29ef26504833', '(A) is false, but (R) is true.', false, 'adcdeae8-6974-4c23-86b5-323c3f77b19c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4ecf4cb-ef50-4b63-b520-6944857fb2fa', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'Spot the IMPOSTER in the following architectural styles and their structural features:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab8bd359-deb5-47be-b819-ed2122ec6b0b', 'Style 1', false, 'f4ecf4cb-ef50-4b63-b520-6944857fb2fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d729d77-7b7d-43a7-8b2b-195f5a759f27', 'Style 2', false, 'f4ecf4cb-ef50-4b63-b520-6944857fb2fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6154513b-8d3e-4d72-aa96-2e796d04c26e', 'Style 3', false, 'f4ecf4cb-ef50-4b63-b520-6944857fb2fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89299b3b-2f0a-462d-850b-e92e38f19971', 'Style 4 (Corbelled arches used stepped horizontal cantilevered stone courses, NOT modern steel cables)', true, 'f4ecf4cb-ef50-4b63-b520-6944857fb2fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa96f207-6caf-459f-861b-021ac31ced36', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'Analyze the engineering transition from Humayun''s Tomb (1570) to the Taj Mahal (1648):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c463559-51f5-40ca-bcd3-a0d5766c8560', 'Evolution from red sandstone with marble trim to pure pristine Makrana white marble, perfected double-dome engineering with slender bulbous silhouettes, elevated riverfront garden placement, and flawless bilateral symmetry', true, 'aa96f207-6caf-459f-861b-021ac31ced36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64784938-a515-492d-827a-0f962c1535a2', 'Transition from stone to brick and mud', false, 'aa96f207-6caf-459f-861b-021ac31ced36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f79f12c-2b62-4380-be19-37ffe9340c88', 'Replacement of gardens with stone courtyards', false, 'aa96f207-6caf-459f-861b-021ac31ced36');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe8cef1a-6b95-4621-83c8-30351151b2a3', 'Abandonment of domes for flat wooden roofs', false, 'aa96f207-6caf-459f-861b-021ac31ced36');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bab36931-65af-49b6-93ff-af832bfc740c', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'Match Column I (Monumental Structures) with Column II (Patron King / Dynasty & Location):
(a) Kandariya Mahadeva Temple -> (i) Chandela King Dhangadeva (Khajuraho, MP)
(b) Brihadisvara Temple        -> (ii) Chola King Rajaraja I (Thanjavur, Tamil Nadu)
(c) Qutb Minar Balconies      -> (iii) Qutbuddin Aibak & Iltutmish (Delhi)
(d) Red Fort Throne & Diwan   -> (iv) Mughal Emperor Shah Jahan (Shahjahanabad / Delhi)', 'Exact attribution: Kandariya = Chandela Dhangadeva; Brihadisvara = Chola Rajaraja; Qutb Minar = Aibak/Iltutmish; Red Fort = Shah Jahan.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2848cf9-98e3-4cd7-b53d-d4c41f004ba6', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'bab36931-65af-49b6-93ff-af832bfc740c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6719801e-caf7-4972-ab95-9647bb988cc1', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'bab36931-65af-49b6-93ff-af832bfc740c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2356fd05-9933-4b3d-993f-720c7d9872cb', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'bab36931-65af-49b6-93ff-af832bfc740c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('049d287a-727d-477d-8775-96f6551cdf7c', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'bab36931-65af-49b6-93ff-af832bfc740c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ba3d8b1-96f4-4d03-a20a-ae8d72a31936', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'Read the statements regarding hydraulic architecture in medieval India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec100f79-1de0-44de-b9e9-2af76ed36045', 'Statements 1 and 2 only', true, '8ba3d8b1-96f4-4d03-a20a-ae8d72a31936');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a43a9a4d-d5ae-4578-abbd-50d539d5f8d5', 'Statements 2 and 3 only', false, '8ba3d8b1-96f4-4d03-a20a-ae8d72a31936');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de02f3b9-a55c-45ff-87de-1006f06d5bb0', 'Statements 1 and 3 only', false, '8ba3d8b1-96f4-4d03-a20a-ae8d72a31936');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5b34840-b59a-44e5-b6bb-e9899996b475', 'All Statements 1, 2, and 3', false, '8ba3d8b1-96f4-4d03-a20a-ae8d72a31936');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bee9b8e1-84d8-4d94-bd5b-2e9481272184', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'How did the ''Double Dome'' architectural innovation (seen in Humayun''s Tomb and the Taj Mahal) solve a complex structural and aesthetic engineering challenge?', 'Double-dome engineering decoupled exterior monumental elevation from interior volumetric proportions, preventing cavernous acoustic distortion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40942cc9-a171-4bc5-a67d-ad8f356631f7', 'The outer dome provided an imposing, soaring silhouette visible from miles away on the exterior, while the lower inner dome created a proportionate, intimate ceiling inside the central tomb chamber', true, 'bee9b8e1-84d8-4d94-bd5b-2e9481272184');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74cde8dc-deb9-49e8-95df-600c943cde99', 'It trapped hot air between two domes to heat the tomb', false, 'bee9b8e1-84d8-4d94-bd5b-2e9481272184');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f176283d-1801-4c35-8c89-4054d39f1a65', 'It was built to store water between the domes', false, 'bee9b8e1-84d8-4d94-bd5b-2e9481272184');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98df0f44-30e1-454b-9ad6-382e04234d3b', 'It was made of glass to let rain in', false, 'bee9b8e1-84d8-4d94-bd5b-2e9481272184');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7b942a8e-2593-41ba-bb3f-41ea46445a9d', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'Why did Akbar''s palace complex at Fatehpur Sikri incorporate extensive architectural traditions from Gujarat and Malwa (e.g. Jodha Bai''s palace)?', 'Akbar''s Fatehpur Sikri celebrated imperial syncretism by integrating Gujarati carved timber brackets, jalis, and Malwa torana motifs into sandstone palaces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9e88bc0-f3cd-43e5-a773-05c9123f4019', 'Akbar deliberately employed master stone craftsmen from newly conquered Gujarat and Malwa, creating an eclectic, syncretic architectural style that visually united his composite empire', true, '7b942a8e-2593-41ba-bb3f-41ea46445a9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6917ce12-162b-4748-bbcf-75da7ee6d582', 'Because there were no stone carvers in Agra', false, '7b942a8e-2593-41ba-bb3f-41ea46445a9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb560036-f4a7-4302-af62-c79037922309', 'Because Malwa was located in Europe', false, '7b942a8e-2593-41ba-bb3f-41ea46445a9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16693609-2b2b-4ead-9966-7c0600c85531', 'Because Akbar wanted to demolish Fatehpur Sikri', false, '7b942a8e-2593-41ba-bb3f-41ea46445a9d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a6e76d1-4f19-477f-8bd2-639d2b3c08fe', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'What is the structural significance of the ''Keystone'' in true Arcuate architecture?', 'The keystone is the critical central crown voussoir of a stone arch that locks the masonry in self-supporting compression.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a955b9c4-188b-4444-af58-278675a51d24', 'The wedge-shaped stone at the central apex of an arch that locks all the surrounding arch stones (voussoirs) together in compressive equilibrium, transferring load downwards to the pillars', true, '0a6e76d1-4f19-477f-8bd2-639d2b3c08fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43b339c8-016f-443c-97f2-d49243b73656', 'A stone made of pure gold for decoration', false, '0a6e76d1-4f19-477f-8bd2-639d2b3c08fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5270d31b-231d-4ffc-88f7-205ea373a09f', 'A key used to lock the palace gate', false, '0a6e76d1-4f19-477f-8bd2-639d2b3c08fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e8d2462-f11b-427f-aa90-867cdc4dd353', 'The foundation stone buried in the dirt', false, '0a6e76d1-4f19-477f-8bd2-639d2b3c08fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2fd17d15-f8b0-42b2-9a39-74286332c2f8', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'Consider four monumental ceiling engineering techniques in medieval India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36338334-b9e6-4a47-a9d7-a1e5b688ecbb', 'Extraordinary indigenous engineering versatility that continuously synthesized structural mechanics, regional cultural motifs, and aesthetic majesty', true, '2fd17d15-f8b0-42b2-9a39-74286332c2f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('979f34e9-4914-477d-9209-f56e2b5336c4', 'That builders only knew how to make flat wooden roofs', false, '2fd17d15-f8b0-42b2-9a39-74286332c2f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba27cbbd-dbf5-43fd-a886-07273cc55a99', 'That all buildings were copied from Roman blueprints', false, '2fd17d15-f8b0-42b2-9a39-74286332c2f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4416be6d-2707-4b13-9a34-b1c874d83205', 'That medieval buildings had no roofs', false, '2fd17d15-f8b0-42b2-9a39-74286332c2f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a0933b1-f870-49e8-aba9-61090d5d137b', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'Why was the construction of the 60-metre Shikhara of Brihadisvara Temple at Thanjavur considered an unprecedented structural marvel of the 11th century?', 'Thanjavur''s Brihadisvara temple stands as an all-granite interlocking structural tour-de-force, towering 66 m without binding cement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46575071-850f-4392-9be9-b7b9a830eac2', 'Granite was not available locally and had to be transported from distant quarries; the entire colossal multi-tiered temple was built without mortar using interlocking precision dry masonry', true, '9a0933b1-f870-49e8-aba9-61090d5d137b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89fedcef-9669-4399-9b20-7895b04c5132', 'It was built under the ocean', false, '9a0933b1-f870-49e8-aba9-61090d5d137b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de1f19ee-4acb-4d14-9feb-8a81839f9ec3', 'It was built out of solid ice', false, '9a0933b1-f870-49e8-aba9-61090d5d137b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92960bf1-e113-4ede-9d27-5a9de43af518', 'It was built in one single hour', false, '9a0933b1-f870-49e8-aba9-61090d5d137b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cee13b56-c0e4-4733-9e98-cb99f160769d', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'What was the symbolic function of ''Jharokha Darshan'' in Shah Jahan''s palace architecture in the Red Fort?', 'Jharokha Darshan institutionalized divine monarchical viewing, projecting the Emperor as the illuminating cosmic patriarch before his subjects.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8163e286-356a-433b-bb27-f1b6951a37cd', 'The elevated royal balcony from which the Emperor appeared every morning at sunrise to the assembled common public below, blending Hindu concepts of divine vision (darshan) with imperial kingship', true, 'cee13b56-c0e4-4733-9e98-cb99f160769d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cd4e1cf-0e49-4336-b6a8-7363a8c9369e', 'A window used to throw garbage', false, 'cee13b56-c0e4-4733-9e98-cb99f160769d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9dc2536-b2d8-4267-ab07-149fee28dbd4', 'A balcony for feeding pigeons only', false, 'cee13b56-c0e4-4733-9e98-cb99f160769d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2dc1695-4a34-4f55-9c37-2d31c4aaddd6', 'A secret door for escaping wars', false, 'cee13b56-c0e4-4733-9e98-cb99f160769d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d682211-8236-409e-92c8-0bcbfb071746', 'Class 7', 'Social Science', 'Chapter 5: Rulers and Buildings', 'Hard', 'What master architectural legacy defines Chapter 5 of NCERT Class 7 History?', 'Chapter 5 illuminates the technical, stylistic, and ideological evolution of India''s monumental architecture across a millennium of dynamic synthesis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2d75b8a-7b5c-4765-965e-23d402fa7069', 'The evolution of magnificent engineering virtuosity across Hindu temple sacred geography, Indo-Islamic structural arcuate and dome innovations, Chahar Bagh symmetry, and rich cross-regional architectural synthesis that permanently shaped India''s built heritage', true, '4d682211-8236-409e-92c8-0bcbfb071746');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5804ffb-8d9f-4d18-8d5e-b662c6a97cc7', 'A period of total architectural ruin', false, '4d682211-8236-409e-92c8-0bcbfb071746');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('224f39e4-6ce3-4ae8-88cb-9d528c0d65a1', 'The destruction of all stone masonry', false, '4d682211-8236-409e-92c8-0bcbfb071746');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b889349-06f8-4343-906d-643973cc3d00', 'The end of building construction in India', false, '4d682211-8236-409e-92c8-0bcbfb071746');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5626a6b7-ab5d-47ce-b985-739d2b223002', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'दो या दो से अधिक शब्दों के परस्पर मेल (संक्षिप्तिकरण) से एक नवीन एवं सार्थक शब्द बनाने की व्याकरणिक प्रक्रिया को क्या कहते हैं?', 'सम् + आस (पास बैठाना): दो या अधिक पदों के संक्षिप्तिकरण से नए सार्थक शब्द निर्माण की विधि ''समास'' कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c529c687-4150-4ea2-8364-cc460d7dd30c', 'समास (Compound)', true, '5626a6b7-ab5d-47ce-b985-739d2b223002');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23b9e855-996b-44b3-b654-6f675f9089e2', 'संधि', false, '5626a6b7-ab5d-47ce-b985-739d2b223002');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45b74f5d-8ca9-4c43-8f25-49e3b8c7bdee', 'उपसर्ग', false, '5626a6b7-ab5d-47ce-b985-739d2b223002');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c70ed8a9-4835-49f0-a47e-12d1c125412d', 'प्रत्यय', false, '5626a6b7-ab5d-47ce-b985-739d2b223002');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a409efe-89e3-43ee-8398-a7e8833d0429', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'समास के नियमों से बने नए संक्षिप्त शब्द को व्याकरण में क्या कहते हैं?', 'समास रचना से निर्मित नया संक्षिप्त शब्द ''समस्त पद'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fedda2b0-2866-42a7-b300-ce262045a16b', 'समस्त पद / सामासिक पद (जैसे: ''रसोईघर'', ''राजपुत्र'')', true, '0a409efe-89e3-43ee-8398-a7e8833d0429');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3843bf49-75bc-4217-b2b8-a28ae02d876e', 'संधि पद', false, '0a409efe-89e3-43ee-8398-a7e8833d0429');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d95bb4a7-98c7-41fc-a7a0-bdf4b3e1ee2c', 'उपसर्ग पद', false, '0a409efe-89e3-43ee-8398-a7e8833d0429');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4afbd959-2922-4e97-b069-d2ef1be454d5', 'कारक', false, '0a409efe-89e3-43ee-8398-a7e8833d0429');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f712f2a3-8866-4413-9237-a239a5b71302', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'समस्त पद के सभी पदों को अलग-अलग करके उनके परस्पर संबंध को स्पष्ट करने की प्रक्रिया को क्या कहते हैं?', 'सामासिक पद के घटकों को कारक-चिह्नों सहित पृथक करना ''समास-विग्रह'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('263dec76-363c-4f35-8ae8-9b8f9dff1222', 'समास-विग्रह (जैसे: रसोई के लिए घर)', true, 'f712f2a3-8866-4413-9237-a239a5b71302');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95d7c355-084d-4924-8c5d-dcd95db5b658', 'संधि-विच्छेद', false, 'f712f2a3-8866-4413-9237-a239a5b71302');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ddb5cfe-c201-4810-a994-8844841253f2', 'वर्ण-विच्छेद', false, 'f712f2a3-8866-4413-9237-a239a5b71302');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4314a338-05e0-4512-8f74-49cf3c198838', 'उपसर्ग विच्छेद', false, 'f712f2a3-8866-4413-9237-a239a5b71302');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3ee2495-86da-4ee0-9c3a-e8b03184790d', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'हिंदी व्याकरण में समास के मुख्य रूप से कितने भेद होते हैं?', 'समास के 6 प्रमुख भेद हैं: अव्ययीभाव, तत्पुरुष, कर्मधारय, द्विगु, द्वंद्व, और बहुव्रीहि।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2284cd56-32a9-4333-9161-8ebaded6397e', 'छह भेद (1. अव्ययीभाव, 2. तत्पुरुष, 3. कर्मधारय, 4. द्विगु, 5. द्वंद्व, 6. बहुव्रीहि)', true, 'c3ee2495-86da-4ee0-9c3a-e8b03184790d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c1cf7c6-cdc7-41f0-b86c-838382b447a4', 'चार भेद', false, 'c3ee2495-86da-4ee0-9c3a-e8b03184790d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a10dd9ad-fdcd-4c86-ade2-cde99d09a887', 'पाँच भेद', false, 'c3ee2495-86da-4ee0-9c3a-e8b03184790d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44b747d0-1fed-41d3-8bb4-1f3d495f321a', 'तीन भेद', false, 'c3ee2495-86da-4ee0-9c3a-e8b03184790d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('57428d19-bf55-4964-972b-064971d14dc0', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'जिस समास का पहला पद (पूर्व पद) अव्यय तथा प्रधान हो और समस्त पद भी अव्यय बन जाए, उसे क्या कहते हैं?', 'पूर्व पद अव्यय और प्रधान होने पर ''अव्ययीभाव समास'' होता है (यथाशक्ति = शक्ति के अनुसार)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caf687b3-c4b5-40ea-824a-69889b597941', 'अव्ययीभाव समास (जैसे: यथाशक्ति, प्रतिदिन, आजन्म, भरपेट)', true, '57428d19-bf55-4964-972b-064971d14dc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81584bfb-c59c-40ea-b307-7fe38711d183', 'तत्पुरुष समास', false, '57428d19-bf55-4964-972b-064971d14dc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c5b6e2a-1d46-4222-83e7-41aa46aeb399', 'द्विगु समास', false, '57428d19-bf55-4964-972b-064971d14dc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b384a4c2-825f-465c-99a2-1072700976e0', 'द्वंद्व समास', false, '57428d19-bf55-4964-972b-064971d14dc0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04b0a344-e213-4332-995a-5bbe85b61385', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'जिस समास में दूसरा पद (उत्तर पद) प्रधान होता है तथा दोनों पदों के बीच कारक-विभक्ति चिह्नों (का, के, की, से, के लिए, में, पर) का लोप हो जाता है, उसे क्या कहते हैं?', 'उत्तर पद प्रधान और कारक चिह्नों के लोप वाला समास ''तत्पुरुष समास'' कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d2a1e18-e050-43dd-b427-8090efd3ed40', 'तत्पुरुष समास (जैसे: राजमहल = राजा का महल, देशप्रेम = देश के लिए प्रेम)', true, '04b0a344-e213-4332-995a-5bbe85b61385');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8e11c42-5605-4329-9a74-28750ac06e54', 'अव्ययीभाव समास', false, '04b0a344-e213-4332-995a-5bbe85b61385');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3002ddde-5322-4a17-8b6f-1a89daade432', 'द्विगु समास', false, '04b0a344-e213-4332-995a-5bbe85b61385');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e377501f-8746-47e1-9a0f-2c3bbf232203', 'बहुव्रीहि समास', false, '04b0a344-e213-4332-995a-5bbe85b61385');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3c30e706-2219-4018-a055-92a12467c692', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'जिस समास का पहला पद संख्यावाचक विशेषण हो और समस्त पद किसी समूह (समाहार) का बोध कराए, उसे क्या कहते हैं?', 'संख्या-पूर्व पद समाहारक समास ''द्विगु समास'' कहलाता है (चौराहा = चार राहों का समाहार)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5f27f20-2215-4cf8-a1fe-27bf0e66cd59', 'द्विगु समास (जैसे: त्रिफला, चौराहा, तिरंगा, पंचवटी, नवग्रह)', true, '3c30e706-2219-4018-a055-92a12467c692');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75589a3c-020b-4f5d-9fbc-1c853e2abf33', 'द्वंद्व समास', false, '3c30e706-2219-4018-a055-92a12467c692');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f26d669a-1e88-43f5-8245-8df96d42d3f6', 'कर्मधारय समास', false, '3c30e706-2219-4018-a055-92a12467c692');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca00532c-3532-462f-8c0b-173754710338', 'अव्ययीभाव समास', false, '3c30e706-2219-4018-a055-92a12467c692');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb18b79e-44c2-4991-b280-6c432a7d4bf8', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'जिस समास में दोनों पद (पूर्व पद और उत्तर पद) समान रूप से प्रधान हों और विग्रह करने पर ''और'', ''या'', ''तथा'' योजक शब्द लगे, उसे क्या कहते हैं?', 'उभय-पद प्रधान समास ''द्वंद्व समास'' कहलाता है (दिन-रात = दिन और रात)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('800340c3-841c-4356-a731-3f1f9c673eb4', 'द्वंद्व समास (जैसे: माता-पिता = माता और पिता, सुख-दुख = सुख और दुख)', true, 'bb18b79e-44c2-4991-b280-6c432a7d4bf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33504796-68cc-4166-8b32-7895290fb2a8', 'द्विगु समास', false, 'bb18b79e-44c2-4991-b280-6c432a7d4bf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dda6a700-58ab-401b-a7d5-98277d16b7b1', 'तत्पुरुष समास', false, 'bb18b79e-44c2-4991-b280-6c432a7d4bf8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9740767e-cf81-4562-954d-b18ae9874f2a', 'कर्मधारय समास', false, 'bb18b79e-44c2-4991-b280-6c432a7d4bf8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8c8fe16c-45bd-4513-b277-3f450c25cfa1', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'जिस समास में दोनों पदों के बीच विशेषण-विशेष्य अथवा उपमान-उपमेय का संबंध हो और उत्तर पद प्रधान हो, उसे क्या कहते हैं?', 'विशेषण-विशेष्य / उपमान-उपमेय युक्त समास ''कर्मधारय समास'' कहलाता है (महात्मा = महान है जो आत्मा)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eee14627-6c07-4627-a854-78b6c3a29c60', 'कर्मधारय समास (जैसे: नीलकमल = नीला है जो कमल, चरणकमल = कमल के समान चरण)', true, '8c8fe16c-45bd-4513-b277-3f450c25cfa1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0ac712e-27cd-41d4-8b71-e671e109bc53', 'अव्ययीभाव समास', false, '8c8fe16c-45bd-4513-b277-3f450c25cfa1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f0d7574-3f52-4708-b1fa-058adea55b9c', 'द्वंद्व समास', false, '8c8fe16c-45bd-4513-b277-3f450c25cfa1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47bebbd8-bc76-4ff9-b762-9679a6f43bf0', 'द्विगु समास', false, '8c8fe16c-45bd-4513-b277-3f450c25cfa1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fde7b83b-8ef9-4c37-9742-5c2047c43454', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', 'जिस समास में दोनों पदों में से कोई भी पद प्रधान नहीं होता, बल्कि दोनों पद मिलकर किसी तीसरे अन्य विशेष पद (संज्ञा) की ओर संकेत करते हैं, उसे क्या कहते हैं?', 'अन्य-पद प्रधान समास ''बहुव्रीहि समास'' कहलाता है (पीतांबर = पीत हैं अंबर जिसके अर्थात श्रीकृष्ण)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9713dfb-3492-4369-b00a-cae15ac58dd9', 'बहुव्रीहि समास (जैसे: गजानन = गज के समान आनन है जिसका अर्थात गणेश, दशानन = रावण)', true, 'fde7b83b-8ef9-4c37-9742-5c2047c43454');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15d37c4a-fae0-473a-8bdd-33cea2e1a939', 'तत्पुरुष समास', false, 'fde7b83b-8ef9-4c37-9742-5c2047c43454');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('204dc7f8-3698-45a7-94d6-224e74feedd3', 'कर्मधारय समास', false, 'fde7b83b-8ef9-4c37-9742-5c2047c43454');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1a6eb0d-3561-4117-95b8-a6475bd0104f', 'अव्ययीभाव समास', false, 'fde7b83b-8ef9-4c37-9742-5c2047c43454');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f2b4cf46-4688-4e20-8003-8a84a9440750', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Easy', '''राजपुत्र'' समस्त पद का सही समास-विग्रह क्या होगा?', 'राजपुत्र = राजा का पुत्र (षष्ठी संबंध कारक विभक्ति ''का'' का लोप होने से संबंध तत्पुरुष)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('877a62f3-60e7-4d2f-8026-472da9757b16', 'राजा का पुत्र (संबंध तत्पुरुष समास)', true, 'f2b4cf46-4688-4e20-8003-8a84a9440750');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dbbbda6-8250-4afb-b980-300a0de50b53', 'राजा और पुत्र', false, 'f2b4cf46-4688-4e20-8003-8a84a9440750');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27543f49-5352-4ace-8a35-e752a0f3afa8', 'राजा के लिए पुत्र', false, 'f2b4cf46-4688-4e20-8003-8a84a9440750');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81db3c8a-489b-4a41-8e0e-dd9e833ec62a', 'राजा में पुत्र', false, 'f2b4cf46-4688-4e20-8003-8a84a9440750');
