INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('842ba118-e315-4188-ab55-c3361728bf99', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Medium', '''नीलकंठ'' शब्द का कर्मधारय और बहुव्रीहि दोनों समासों में क्या अलग-अलग विग्रह होगा?', 'कर्मधारय (नीला है जो कंठ - विशेषण-विशेष्य) ; बहुव्रीहि (नीला है कंठ जिसका अर्थात् शिव - रूढ़ अन्य पद)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a48a1dfd-cc83-43de-aa0d-2ab636743de4', 'कर्मधारय विग्रह: ''नीला है जो कंठ'' ; बहुव्रीहि विग्रह: ''नीला है कंठ जिसका अर्थात् भगवान शिव''', true, '842ba118-e315-4188-ab55-c3361728bf99');
