INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81030d9e-c3eb-4a6e-ad3b-dff2f5286af9', 'नीलकंठ केवल तत्पुरुष समास है', false, '842ba118-e315-4188-ab55-c3361728bf99');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82411957-ceb8-4360-9f4f-75b27ac52230', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Medium', '''दशानन'' शब्द का द्विगु और बहुव्रीहि दोनों समासों में क्या अलग-अलग विग्रह होगा?', 'संख्या समाहार = द्विगु ; विशिष्ट व्यक्ति (रावण) की ओर रूढ़ संकेत = बहुव्रीहि समास।', NOW()) ON CONFLICT DO NOTHING;
