INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad1917dd-89d0-4020-82fe-89fe9a906b6d', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Medium', '''रातों-रात'' और ''दिनों-दिन'' शब्दों में कौन-सा समास है?', 'एक ही शब्द की पुनरावृत्ति से अव्यय बनने पर ''अव्ययीभाव समास'' होता है (रात ही रात में = रातों-रात)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b98c216-2a9e-4bef-ad9b-3e469ba9df72', 'अव्ययीभाव समास (समान शब्द की पुनरुक्ति से निर्मित अव्यय पद)', true, 'ad1917dd-89d0-4020-82fe-89fe9a906b6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d664a0c-034f-4e89-9396-f18201061ecf', 'द्वंद्व समास', false, 'ad1917dd-89d0-4020-82fe-89fe9a906b6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1034379d-20b6-4b13-9518-b2c4e18a9113', 'द्विगु समास', false, 'ad1917dd-89d0-4020-82fe-89fe9a906b6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f87864a-600f-4579-9a02-f247f368a3f0', 'कर्मधारय समास', false, 'ad1917dd-89d0-4020-82fe-89fe9a906b6d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22ee22a8-fb9a-437c-a441-c413c1175cc7', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Medium', '''वनवास'' समस्त पद का सही समास-विग्रह क्या होगा?', 'वन में वास = अधिकरण तत्पुरुष (सप्तमी विभक्ति ''में'' का लोप)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e736ded-062d-45af-9daa-a6f3a71ec539', 'वन में वास (अधिकरण तत्पुरुष समास)', true, '22ee22a8-fb9a-437c-a441-c413c1175cc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee8ba3fd-98d8-4c79-8182-cc0f3a249431', 'वन का वास', false, '22ee22a8-fb9a-437c-a441-c413c1175cc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('056a428f-f844-419d-8e25-661d29776a50', 'वन के लिए वास', false, '22ee22a8-fb9a-437c-a441-c413c1175cc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('713bc459-c702-424f-a341-463ba35b6f5a', 'वन से वास', false, '22ee22a8-fb9a-437c-a441-c413c1175cc7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59713b25-71f6-4d09-9dd4-0b7509a59c81', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Medium', 'जिस तत्पुरुष समास में पहला पद निषेधवाचक (नकारात्मक - जैसे: न, अ, अन) होता है (जैसे: अनदेखा, अनहोनी, अन्याय, अधर्म), उसे क्या कहते हैं?', 'नकारात्मक अभाव सूचक पूर्व पद (अ/अन/न) वाला समास ''नञ् तत्पुरुष'' कहलाता है (न न्याय = अन्याय)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dde560d1-8bd7-4e52-8ed7-2c2603c2ba05', 'नञ् तत्पुरुष समास (Negative Compound)', true, '59713b25-71f6-4d09-9dd4-0b7509a59c81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd76214b-de46-4d04-b6c2-0132bd647a82', 'कर्म तत्पुरुष', false, '59713b25-71f6-4d09-9dd4-0b7509a59c81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('400a1273-6427-4499-843f-fcc863033083', 'अपादान तत्पुरुष', false, '59713b25-71f6-4d09-9dd4-0b7509a59c81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cbc739b-0bb4-474f-8ea4-a80a126bddb8', 'अव्ययीभाव समास', false, '59713b25-71f6-4d09-9dd4-0b7509a59c81');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('26944a8f-52ce-4471-aab3-57d1b45dcf3e', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Medium', '''पंचामृत'' समस्त पद का सही समास-विग्रह और समास का नाम क्या होगा?', 'पाँच द्रव्यों (दूध, दही, घी, शहद, गंगाजल) का समाहार = द्विगु समास।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45d9647d-eb74-496d-9dc3-3f17bfce4e96', 'पाँच अमृतरूपी द्रव्यों का समाहार (द्विगु समास)', true, '26944a8f-52ce-4471-aab3-57d1b45dcf3e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcdbc262-3616-4a09-8805-624af4d9b1be', 'पाँच और अमृत (द्वंद्व)', false, '26944a8f-52ce-4471-aab3-57d1b45dcf3e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03c6e218-3923-48da-b861-15809f14af70', 'अमृत है जो पाँच (कर्मधारय)', false, '26944a8f-52ce-4471-aab3-57d1b45dcf3e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91fbea5c-98c9-4e2b-a14c-c96ac769e554', 'पाँच का अमृत (तत्पुरुष)', false, '26944a8f-52ce-4471-aab3-57d1b45dcf3e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc2b6cdf-236e-4324-ac53-71f1fc56e330', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b36b711-62d7-4354-af84-3cdc2f09ee41', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'fc2b6cdf-236e-4324-ac53-71f1fc56e330');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12a22a98-dc4e-454f-9e12-7767b2851eb4', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'fc2b6cdf-236e-4324-ac53-71f1fc56e330');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f2f21f0-7e18-43de-9154-a74a666a7b47', '(A) सही है, परन्तु (R) गलत है।', false, 'fc2b6cdf-236e-4324-ac53-71f1fc56e330');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5f6ce00-7d32-406c-9999-a98b9fc6297d', '(A) गलत है, परन्तु (R) सही है।', false, 'fc2b6cdf-236e-4324-ac53-71f1fc56e330');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5203764f-7c1c-46fd-aade-07f3d2fc877a', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', 'Spot the IMPOSTER in the following group of समस्त पद और उनके समास भेदों में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0192788-a804-455a-b974-a33e507d207c', 'युग्म 1', false, '5203764f-7c1c-46fd-aade-07f3d2fc877a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49b664c5-57d4-488e-b5bb-59148fe1823a', 'युग्म 2', false, '5203764f-7c1c-46fd-aade-07f3d2fc877a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bc455de-f7d3-4133-b833-609b153827f4', 'युग्म 3', false, '5203764f-7c1c-46fd-aade-07f3d2fc877a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23e35463-e683-48b7-9de1-76f2ee9244ee', 'युग्म 4 (माता-पिता ''द्वंद्व समास'' है, बहुव्रीहि नहीं)', true, '5203764f-7c1c-46fd-aade-07f3d2fc877a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e015798b-eb53-4164-a35b-ea9251d76914', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', 'सुमेलित कीजिए (समस्त पद और उनके समास भेद):
(क) चतुर्मुख (चार हैं मुख जिसके अर्थात् ब्रह्मा) -> (i) बहुव्रीहि समास
(ख) त्रिवेणी (तीन वेणियों का समाहार)            -> (ii) द्विगु समास
(ग) नरसिंह (सिंह के समान नर)                   -> (iii) कर्मधारय समास
(घ) बेखटके (बिना खटके के)                      -> (iv) अव्ययीभाव समास', 'चतुर्मुख = ब्रह्मा (बहुव्रीहि); त्रिवेणी = 3 नदियों का समाहार (द्विगु); नरसिंह = उपमान-उपमेय (कर्मधारय); बेखटके = अव्ययीभाव।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('327abd65-424e-4b01-96e0-10672b5f7a51', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, 'e015798b-eb53-4164-a35b-ea9251d76914');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f950371d-e2c9-4c06-97fe-c7ac687c0cc9', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, 'e015798b-eb53-4164-a35b-ea9251d76914');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d8efdf4-0160-477e-8e8b-0a45463ace80', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, 'e015798b-eb53-4164-a35b-ea9251d76914');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf2b374b-42d9-441a-99ec-6096ebb7bdd2', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, 'e015798b-eb53-4164-a35b-ea9251d76914');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2badfc4a-c873-4533-92aa-87f6e723181b', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', '''चक्रपाणि'' (चक्र है पाणि/हाथ में जिसके अर्थात् भगवान विष्णु) और ''त्रिनेत्र'' (तीन नेत्र हैं जिसके अर्थात् भगवान शिव) में कौन-सा समास है?', 'अन्य विशिष्ट ईश्वरीय सत्ता (विष्णु/शिव) को ध्वनित करने के कारण ''बहुव्रीहि समास'' है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f5c79f7-a1f3-44c3-a225-89d9b9a27b2b', 'बहुव्रीहि समास (क्योंकि दोनों पद मिलकर किसी अन्य विशिष्ट देवता की ओर रूढ़ संकेत कर रहे हैं)', true, '2badfc4a-c873-4533-92aa-87f6e723181b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ae45409-1644-44cb-8ba2-63cff5a43f30', 'द्विगु समास', false, '2badfc4a-c873-4533-92aa-87f6e723181b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9eed5015-dbf8-4120-a5c7-5d0322ab5282', 'कर्मधारय समास', false, '2badfc4a-c873-4533-92aa-87f6e723181b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('991079a9-caa6-4a78-8c8c-e0e1f12d3e28', 'तत्पुरुष समास', false, '2badfc4a-c873-4533-92aa-87f6e723181b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18cc3a68-12f6-4a27-b84b-4a9bb512c45b', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', '''कर्मधारय समास'' और ''बहुव्रीहि समास'' में निर्णय करने का सबसे प्रामाणिक व्याकरणिक आधार क्या है?', 'समास का निर्धारण विग्रह की प्रकृति पर निर्भर करता है: विशेषणात्मक विग्रह = कर्मधारय; अन्य-पदवाची विग्रह = बहुव्रीहि।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ca04b0b-7ae2-432a-9209-34df0282fae5', 'समास-विग्रह ही निर्णय करता है: यदि विग्रह विशेषण-विशेष्य के रूप में हो तो ''कर्मधारय'' होगा ; यदि विग्रह किसी अन्य तीसरे पद के रूढ़ अर्थ में हो तो ''बहुव्रीहि'' होगा', true, '18cc3a68-12f6-4a27-b84b-4a9bb512c45b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f3337eb-36a3-406f-a7af-c111e09009f1', 'शब्द का पहला अक्षर', false, '18cc3a68-12f6-4a27-b84b-4a9bb512c45b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e96a0de-7016-4c35-ba0d-2125e3de7183', 'शब्द में कितने वर्ण हैं', false, '18cc3a68-12f6-4a27-b84b-4a9bb512c45b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22452fbb-771b-4829-9487-5b358a9a1c66', 'शब्द किस भाषा का है', false, '18cc3a68-12f6-4a27-b84b-4a9bb512c45b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('01ae437c-3e8b-4956-a99e-1a3bff7b8af7', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', 'निम्नलिखित में से किस समस्त पद में ''अपादान तत्पुरुष समास'' है?', 'पथ से भ्रष्ट / देश से निकाला में अलगाव/वियोग सूचक ''से'' विभक्ति का लोप होने से ''अपादान तत्पुरुष'' है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e428189-2d51-4051-8bab-37e630415bbd', '''पथभ्रष्ट'' (पथ से भ्रष्ट / अलग होना) और ''देशनिकाला'' (देश से निकाला)', true, '01ae437c-3e8b-4956-a99e-1a3bff7b8af7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a5383c5-02b9-4c85-9401-d8e6e597c929', '''रसभरा''', false, '01ae437c-3e8b-4956-a99e-1a3bff7b8af7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ac4871a-d124-4f27-8ffa-4f6583b914b6', '''मूर्तिकार''', false, '01ae437c-3e8b-4956-a99e-1a3bff7b8af7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39e5b7e1-667d-400a-8e7a-12c28b91984b', '''रसोईघर''', false, '01ae437c-3e8b-4956-a99e-1a3bff7b8af7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('478f906d-e280-436d-bc18-43836f0fbf6a', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', '''दाल-रोटी'', ''छोटा-बड़ा'', ''ऊँच-नीच'', ''हानि-लाभ'' में कौन-सा समास है?', 'उभय-पद प्रधान द्वंद्व समास (दाल और रोटी, हानि या लाभ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d97c410a-50ee-49e0-ab67-59015ec0b864', 'द्वंद्व समास (दोनों पद प्रधान, विग्रह में ''और'' या ''या'' का प्रयोग)', true, '478f906d-e280-436d-bc18-43836f0fbf6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79ffe176-cc90-4072-95a1-dd1740849dd8', 'द्विगु समास', false, '478f906d-e280-436d-bc18-43836f0fbf6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10ccc992-5b1b-4e9c-8483-8f0efd87fd6e', 'कर्मधारय समास', false, '478f906d-e280-436d-bc18-43836f0fbf6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6fba426-5a0b-40b8-b9d8-77dca2f4171a', 'बहुव्रीहि समास', false, '478f906d-e280-436d-bc18-43836f0fbf6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('429a272a-6edb-470a-ba1d-caa77ca65ddd', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', '''महात्मा'' और ''परमानंद'' में कौन-सा समास है?', 'विशेषण-विशेष्य संबंध होने के कारण ''कर्मधारय समास'' है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce8bbec5-5e18-41a7-baa2-e7ded834501c', 'कर्मधारय समास (महान है जो आत्मा ; परम है जो आनंद - विशेषण-विशेष्य संबंध)', true, '429a272a-6edb-470a-ba1d-caa77ca65ddd');
