INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64e7b112-ced5-412b-95ab-48cbeafde126', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', '''दिशानिर्देश'' और ''मार्गदर्शन'' में कौन-सा तत्पुरुष समास है?', 'दिशा का निर्देश / मार्ग का दर्शन = संबंध तत्पुरुष (''का'' विभक्ति का लोप)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('772cb51b-e512-4766-8062-f717ec22f37c', 'संबंध तत्पुरुष समास (दिशा का निर्देश ; मार्ग का दर्शन)', true, '64e7b112-ced5-412b-95ab-48cbeafde126');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb4e87d5-1ce1-47b7-bf07-6bc6ccd24475', 'करण तत्पुरुष', false, '64e7b112-ced5-412b-95ab-48cbeafde126');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69ca9c33-caf7-47b4-a9ac-0ccc0a947626', 'अपादान तत्पुरुष', false, '64e7b112-ced5-412b-95ab-48cbeafde126');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d54806b6-aa82-41ba-9950-2a48dff8ce5f', 'कर्म तत्पुरुष', false, '64e7b112-ced5-412b-95ab-48cbeafde126');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6055b1b-b37c-4bbf-9aaa-d480f6b70ffb', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', 'निम्नलिखित में से कौन-सा समस्त पद ''अव्ययीभाव समास'' का उदाहरण नहीं है?', '''गंगाजल'' संबंध तत्पुरुष है; आजन्म, प्रत्यक्ष (प्रति+अक्ष) और बेखटके अव्ययीभाव समास हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b710831-795f-4f11-8860-4b29b2daf71d', '''गंगाजल'' (क्योंकि यह ''गंगा का जल'' संबंध तत्पुरुष समास है, अव्ययीभाव नहीं)', true, 'e6055b1b-b37c-4bbf-9aaa-d480f6b70ffb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43491f93-c6bd-4181-91a5-0e5826c282c8', '''आजन्म''', false, 'e6055b1b-b37c-4bbf-9aaa-d480f6b70ffb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8a25d5a-bca3-4aaa-ac48-3bc028b119a0', '''प्रत्यक्ष''', false, 'e6055b1b-b37c-4bbf-9aaa-d480f6b70ffb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3db61697-114f-42e3-a58d-afce74bc12d6', '''बेखटके''', false, 'e6055b1b-b37c-4bbf-9aaa-d480f6b70ffb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c75a9450-c0ba-4568-bbd4-7d623179aad2', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', '''शताब्दी'' समस्त पद का शुद्ध समास-विग्रह क्या होगा?', 'शत + अब्द (वर्ष) = सौ वर्षों का समाहार (द्विगु समास)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1419f55-4790-408e-bc71-ab74584aed91', 'सौ अब्दों (वर्षों) का समाहार (द्विगु समास)', true, 'c75a9450-c0ba-4568-bbd4-7d623179aad2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac73e147-ee12-47bb-aad8-2422bf99d9f0', 'सौ और वर्ष', false, 'c75a9450-c0ba-4568-bbd4-7d623179aad2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edbf586a-5c7f-4511-b7d4-9740f9bcbfe3', 'वर्ष है जो सौ', false, 'c75a9450-c0ba-4568-bbd4-7d623179aad2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42700f6d-412f-4671-86f9-8bd251a1a9c4', 'सौ का वर्ष', false, 'c75a9450-c0ba-4568-bbd4-7d623179aad2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58e9fa73-2a2f-4aee-8f84-304c2f9d430a', 'Class 7', 'Hindi Grammar', 'Chapter 5: समास', 'Hard', 'समास (Compounding) के सम्यक अध्ययन का हिंदी भाषा में क्या सर्वोच्च व्यावहारिक महत्व है?', 'समास भाषा का संक्षेपण-कौशल है, जो वाक्य-विन्यास में लाघव, प्रभावोत्पादकता और ओजस्वी सौंदर्य का संचार करता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27110ca2-ad1c-4350-b669-057fbb306551', 'समास भाषा को संक्षिप्त, चुस्त, प्रभावशाली, लालित्यपूर्ण और अर्थगर्भित बनाता है, जिससे विस्तृत विचारों को कम से कम शब्दों में सौंदर्यपूर्ण ढंग से व्यक्त किया जा सकता है', true, '58e9fa73-2a2f-4aee-8f84-304c2f9d430a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47857e49-2a25-4f0f-b7cd-0d4b383e9fc5', 'समास केवल शब्दों को लंबा करता है', false, '58e9fa73-2a2f-4aee-8f84-304c2f9d430a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc6c55aa-f65f-4c82-8d4f-36b278a07a28', 'समास का वाक्यों में कोई प्रयोग नहीं होता', false, '58e9fa73-2a2f-4aee-8f84-304c2f9d430a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5011b96-b79c-4550-a95a-e016ade6fd1e', 'समास केवल कविता में प्रयुक्त होता है', false, '58e9fa73-2a2f-4aee-8f84-304c2f9d430a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89bce1ca-fe99-402a-8e68-2c4b614d8ae8', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'The biochemical process of breakdown of food (glucose) in the cells with the release of biological energy (ATP) is called:', 'Cellular respiration is the biochemical catabolism of glucose inside cells to liberate metabolic energy in the form of ATP.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a156d58-c122-4236-9397-525cc4f1be69', 'Cellular Respiration', true, '89bce1ca-fe99-402a-8e68-2c4b614d8ae8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('845c15b9-7a60-45d4-9c24-386d41b86c1a', 'Digestion', false, '89bce1ca-fe99-402a-8e68-2c4b614d8ae8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84ad2568-4c98-46ae-8e55-b7e2b406059a', 'Photosynthesis', false, '89bce1ca-fe99-402a-8e68-2c4b614d8ae8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b00f9ca-a289-4095-9318-022e542eb1f6', 'Transpiration', false, '89bce1ca-fe99-402a-8e68-2c4b614d8ae8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d0b754d-c205-4243-bbc2-235221b8cf17', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'When the breakdown of glucose occurs in the PRESENCE of Oxygen gas, yielding carbon dioxide, water, and large energy, it is called:', 'Aerobic respiration breaks down glucose completely in the presence of O₂: C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + Energy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e689a75-32b1-4fb1-ac86-75da0d512e68', 'Aerobic Respiration', true, '5d0b754d-c205-4243-bbc2-235221b8cf17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75e2b952-0fc7-41e7-8fe8-cba56bca7bd6', 'Anaerobic Respiration', false, '5d0b754d-c205-4243-bbc2-235221b8cf17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2941e4f-4f4d-4535-a651-2fed9fd439e8', 'Fermentation', false, '5d0b754d-c205-4243-bbc2-235221b8cf17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83e2f7a1-49c2-46c8-bb2c-8ed8c6b35f09', 'Breathing', false, '5d0b754d-c205-4243-bbc2-235221b8cf17');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d406d367-654e-4696-88fa-547649e8f791', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'When the breakdown of glucose occurs in the ABSENCE of Oxygen (such as in single-celled Yeast), it is called:', 'Anaerobic respiration occurs without oxygen: Glucose → Alcohol (Ethanol) + Carbon dioxide + Energy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fb19fb9-1fad-42f0-bd9f-f0c39af1a0fc', 'Anaerobic Respiration (Fermentation)', true, 'd406d367-654e-4696-88fa-547649e8f791');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30e5d704-4070-40a0-9af8-60f6ae7ee69f', 'Aerobic Respiration', false, 'd406d367-654e-4696-88fa-547649e8f791');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6a66777-8a21-47bc-9af6-c78419d5783d', 'Combustion', false, 'd406d367-654e-4696-88fa-547649e8f791');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d573ff7-3547-4503-a370-c1cb2d69e1d7', 'Inhalation', false, 'd406d367-654e-4696-88fa-547649e8f791');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2a70c203-8dc9-4ce3-b9c0-5cc7fd7d9fb4', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'What single-celled anaerobic fungus is widely used in breweries to make Wine and in bakeries to make fluffy Bread?', 'Yeast respires anaerobically, producing ethanol (for alcoholic beverages) and CO₂ gas (which causes bread dough to rise).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('117ae39c-1fa1-491f-b7fd-fd3460497b4d', 'Yeast (Saccharomyces cerevisiae)', true, '2a70c203-8dc9-4ce3-b9c0-5cc7fd7d9fb4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ff1d574-83e5-4378-be3d-4d60bf88dcad', 'Amoeba', false, '2a70c203-8dc9-4ce3-b9c0-5cc7fd7d9fb4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de50d14b-c468-454d-b531-dced66bb9452', 'Paramecium', false, '2a70c203-8dc9-4ce3-b9c0-5cc7fd7d9fb4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ebc2a8e-1d09-4b7b-a37f-4e6e93696a11', 'Bread mold (Rhizopus)', false, '2a70c203-8dc9-4ce3-b9c0-5cc7fd7d9fb4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4a64961e-3a15-4a5c-aa28-e5c683351454', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'During heavy, rigorous exercise or fast running, the accumulation of which chemical substance in muscle cells causes painful MUSCLE CRAMPS?', 'Under temporary oxygen deficit during strenuous exercise, muscle cells respire anaerobically, producing lactic acid: Glucose → Lactic acid + Energy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6f0049e-c8dc-4e34-ae0a-6929aac441ab', 'Lactic Acid', true, '4a64961e-3a15-4a5c-aa28-e5c683351454');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f593222b-6029-4950-833c-1f62bb0ef6d8', 'Hydrochloric Acid', false, '4a64961e-3a15-4a5c-aa28-e5c683351454');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccc8a82c-074c-48e9-b5b4-d012cc11230a', 'Acetic Acid', false, '4a64961e-3a15-4a5c-aa28-e5c683351454');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4e9faf2-afcd-4240-bcbf-33ffff1f5c8d', 'Citric Acid', false, '4a64961e-3a15-4a5c-aa28-e5c683351454');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8bdc101e-1249-4fb8-be94-ca1bfdfc2185', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'How does taking a hot water bath or receiving a vigorous body massage provide immediate relief from muscle cramps?', 'Enhanced circulatory perfusion restores oxygen levels, metabolizing lactic acid into CO₂ and H₂O.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57cd7f73-664b-4412-88e5-9528f1943b05', 'It improves blood circulation, increasing the oxygen supply to muscle cells which oxidizes accumulated lactic acid completely into CO₂ and water', true, '8bdc101e-1249-4fb8-be94-ca1bfdfc2185');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb1dd999-5ca7-4a0a-b0ad-7e9eef008b60', 'It cools the skin', false, '8bdc101e-1249-4fb8-be94-ca1bfdfc2185');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0157f758-e56b-43f9-b7f5-7011f365aa67', 'It removes water from muscles', false, '8bdc101e-1249-4fb8-be94-ca1bfdfc2185');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94aa422e-0baa-4feb-b303-a67489ae66bb', 'It stops blood flow', false, '8bdc101e-1249-4fb8-be94-ca1bfdfc2185');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db76e88e-7885-4473-8adc-4ad5fb36388a', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'What is the normal resting Breathing Rate (breaths per minute) of an average adult human being at rest?', 'A healthy resting human adult breathes approximately 15 to 18 times per minute.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f39eed1-7df2-427c-9b0c-804a62b1260d', '15 to 18 breaths per minute', true, 'db76e88e-7885-4473-8adc-4ad5fb36388a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56cf6072-1916-40e8-a22b-0f45a62a16e4', '40 to 50 breaths per minute', false, 'db76e88e-7885-4473-8adc-4ad5fb36388a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55270342-60ca-4766-b9bc-cc0b28cdf20f', '5 to 8 breaths per minute', false, 'db76e88e-7885-4473-8adc-4ad5fb36388a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('481b7305-3b19-4f37-956a-549c96198765', '60 to 70 breaths per minute', false, 'db76e88e-7885-4473-8adc-4ad5fb36388a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0648da36-fd43-42ee-8437-1899bd958ee6', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'What large, muscular dome-shaped sheet forms the floor of the human chest (thoracic) cavity and moves during breathing?', 'The diaphragm is the primary muscular partition separating the thoracic cavity from the abdominal cavity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ce30527-f7a8-4f04-8874-63681545b863', 'The Diaphragm', true, '0648da36-fd43-42ee-8437-1899bd958ee6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f9d1728-3bef-4d48-a355-f7874961710d', 'The Trachea', false, '0648da36-fd43-42ee-8437-1899bd958ee6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1f72a45-f414-4c37-b74b-21169591f84f', 'The Bronchus', false, '0648da36-fd43-42ee-8437-1899bd958ee6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d074a09d-2c35-40bc-9a05-4659fd32104c', 'The Rib cage', false, '0648da36-fd43-42ee-8437-1899bd958ee6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8f38a0c-544c-402d-bda7-50a43f048b76', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'Through which specialized respiratory organs do Fish breathe dissolved oxygen in water?', 'Fish utilize richly vascularized gill filaments with thin membranes to extract dissolved oxygen from water.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d031987-a8cf-4146-b2dc-0b46848c21a6', 'Gills (vascularized filamentous branchiae)', true, 'd8f38a0c-544c-402d-bda7-50a43f048b76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc202946-8af9-4aa8-aa2a-522367ee4c49', 'Lungs', false, 'd8f38a0c-544c-402d-bda7-50a43f048b76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14d850ca-772c-4490-bc8d-c7765778a29d', 'Skin only', false, 'd8f38a0c-544c-402d-bda7-50a43f048b76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('747d5053-55db-44a5-b899-211d416d45cc', 'Tracheae', false, 'd8f38a0c-544c-402d-bda7-50a43f048b76');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4df3705-f4cd-4935-adfe-bca4431d3efc', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'Through which organ does an Earthworm exchange respiratory gases (O₂ and CO₂)?', 'Earthworms absorb oxygen and expel CO₂ directly by diffusion through their moist, mucus-coated skin.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da811c5e-b945-4daf-8930-fcfe549dd9e7', 'Its thin, moist, and slimy skin (Cutaneous respiration)', true, 'f4df3705-f4cd-4935-adfe-bca4431d3efc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03f1593a-b6e6-41c8-9909-ffdaaf8cd2e1', 'Lungs', false, 'f4df3705-f4cd-4935-adfe-bca4431d3efc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bf3c45c-b3ca-418d-a0c7-9afcbe8f4f25', 'Gills', false, 'f4df3705-f4cd-4935-adfe-bca4431d3efc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2551d40d-c17a-4cee-8288-682901d8627a', 'Spiracles', false, 'f4df3705-f4cd-4935-adfe-bca4431d3efc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8c6b98d-a466-4f5c-b8e2-58a0cfb5ec02', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'Through which small lateral openings and network of air tubes do Cockroaches and insects breathe?', 'Insects have lateral body pores called spiracles connecting to a branching network of air tubes (tracheae).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('032cee83-e638-4e7b-b38e-1c4352d1d979', 'Spiracles and Tracheal Tubes (Tracheae)', true, 'd8c6b98d-a466-4f5c-b8e2-58a0cfb5ec02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42b3dfc7-0774-4385-b3fd-510dd57bdce8', 'Gills', false, 'd8c6b98d-a466-4f5c-b8e2-58a0cfb5ec02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a355288b-52d6-4179-a1aa-cbc254fd0a62', 'Lungs', false, 'd8c6b98d-a466-4f5c-b8e2-58a0cfb5ec02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34e052d4-c2b1-443d-a857-ffd087dbc1e9', 'Moist skin', false, 'd8c6b98d-a466-4f5c-b8e2-58a0cfb5ec02');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5687e10f-829f-413d-8b3c-ce73732cdf76', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Easy', 'What tiny microscopic pores on the surface of plant leaves facilitate the exchange of Oxygen and Carbon Dioxide during respiration and photosynthesis?', 'Stomata surrounded by specialized guard cells regulate gaseous exchange and transpiration in plant leaves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('131d650a-77ac-4860-9e12-533db910cefb', 'Stomata (guarded by Guard Cells)', true, '5687e10f-829f-413d-8b3c-ce73732cdf76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7f25e30-ddb5-4706-bb7b-7b88db9c6059', 'Xylem vessels', false, '5687e10f-829f-413d-8b3c-ce73732cdf76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('281416b8-289e-4181-bb20-85a0851f033b', 'Phloem tubes', false, '5687e10f-829f-413d-8b3c-ce73732cdf76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd60fa7c-7810-4d93-be19-bb1a3e49b3a2', 'Root caps', false, '5687e10f-829f-413d-8b3c-ce73732cdf76');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b6fe3cce-ca42-4c2a-a5ed-bc1ca5d171a1', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'What mechanical movements occur in the rib cage and diaphragm during human INHALATION (breathing in)?', 'Inhalation: external intercostal muscles elevate ribs (up/out), diaphragm flattens down, expanding lung volume and dropping intrapulmonary pressure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7696dde9-cdbb-4543-af4b-0d86a531f0ec', 'The Ribs move UP and OUTWARDS, the Diaphragm contracts and moves DOWNWARDS, increasing the thoracic volume, lowering pressure, and drawing air in', true, 'b6fe3cce-ca42-4c2a-a5ed-bc1ca5d171a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bddb822-1fe3-47c6-b55e-57e55f6d5eb6', 'The Ribs move down and in, and diaphragm moves up', false, 'b6fe3cce-ca42-4c2a-a5ed-bc1ca5d171a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d44695c-28a7-46a8-a08d-9580a22cbdee', 'The lungs stop moving', false, 'b6fe3cce-ca42-4c2a-a5ed-bc1ca5d171a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ed8483e-0510-49dc-8876-3350c161f850', 'The stomach contracts only', false, 'b6fe3cce-ca42-4c2a-a5ed-bc1ca5d171a1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73a8694b-bdfd-4927-94ec-4b0fe3ce8f2d', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'What mechanical movements occur during human EXHALATION (breathing out)?', 'Exhalation: intercostal muscles relax, ribs depress down/in, diaphragm arches up to resting dome position, compressing thoracic space.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1fd8ece-f567-406d-a3c6-3e8f46cc4011', 'The Ribs move DOWN and INWARDS, the Diaphragm relaxes and arches UPWARDS into its dome shape, reducing thoracic volume and expelling air', true, '73a8694b-bdfd-4927-94ec-4b0fe3ce8f2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c798da1-cc93-44fd-9b14-49f22c9aeb9b', 'The Ribs move up and outwards', false, '73a8694b-bdfd-4927-94ec-4b0fe3ce8f2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f28d7936-85b5-4e81-835a-289a56dc584f', 'The Diaphragm moves down', false, '73a8694b-bdfd-4927-94ec-4b0fe3ce8f2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a4ae4e1-ac01-4c1d-8d5c-b366c0c7c00a', 'The chest expands', false, '73a8694b-bdfd-4927-94ec-4b0fe3ce8f2d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('620e9ef4-351d-4c86-9063-c1104e9eca18', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'How does the percentage composition of Inhaled Air compare with Exhaled Air in human beings?', 'Human respiration extracts ~4.6% oxygen from inhaled air and enriches exhaled air with ~4.4% CO₂ alongside saturated water vapor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67282cf1-49a8-4020-82c3-9c886a5022ab', 'Inhaled Air: 21% O₂ and 0.04% CO₂ ; Exhaled Air: 16.4% O₂ and 4.4% CO₂', true, '620e9ef4-351d-4c86-9063-c1104e9eca18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b759895-2b24-4603-a452-c5cbe9cc26f9', 'Inhaled Air: 100% O₂ ; Exhaled Air: 100% CO₂', false, '620e9ef4-351d-4c86-9063-c1104e9eca18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30634c3b-2717-459e-ac30-2304274cd2fb', 'Inhaled Air: 0% O₂ ; Exhaled Air: 21% CO₂', false, '620e9ef4-351d-4c86-9063-c1104e9eca18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5fc1ead-c57c-4846-bbce-d7623e61b4a7', 'Inhaled Air and Exhaled Air are identical', false, '620e9ef4-351d-4c86-9063-c1104e9eca18');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('844bcf05-8ca0-4f0c-8219-300b6b7392fd', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'How do adult Frogs breathe in their dual (amphibious) habitats?', 'Amphibian respiration: terrestrial lung ventilation supplemented by aquatic cutaneous microvascular diffusion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67e5c78f-ce40-4248-b765-fc8da23c342f', 'On land they breathe through a pair of Lungs (pulmonary respiration) ; in water they breathe through their moist, slimy Skin (cutaneous respiration)', true, '844bcf05-8ca0-4f0c-8219-300b6b7392fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b11c7684-21b2-47d5-9785-a2a099f8c849', 'They only breathe through gills', false, '844bcf05-8ca0-4f0c-8219-300b6b7392fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0091bfe-8912-4ee9-bce8-3443ebaa85ee', 'They only breathe through lungs', false, '844bcf05-8ca0-4f0c-8219-300b6b7392fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ab07a46-27be-4231-97a9-f71ff7587c53', 'They do not breathe in water', false, '844bcf05-8ca0-4f0c-8219-300b6b7392fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9bf18224-8d5e-4905-bbb4-2aa027472d2c', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'Why do plant roots die and rot if a potted plant is over-watered continuously for many days (waterlogging)?', 'Waterlogging creates soil anoxia; root cells cannot perform aerobic respiration to generate ATP for active mineral transport, causing asphyxiation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7b89d9b-c5fb-490f-85e3-dc9b0c870a3b', 'Water fills all the microscopic air spaces between soil particles, cutting off oxygen supply to root cells, preventing cellular respiration', true, '9bf18224-8d5e-4905-bbb4-2aa027472d2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d4f4c2a-cc4d-43e6-b52d-a9a659bf265e', 'Because roots drink too much water and explode', false, '9bf18224-8d5e-4905-bbb4-2aa027472d2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd392a1c-783c-4adb-a6e9-95d2e49a112d', 'Because water turns into acid', false, '9bf18224-8d5e-4905-bbb4-2aa027472d2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44b87a14-4314-4cff-9ef7-8c5881c6bc88', 'Because sunlight cannot reach the leaves', false, '9bf18224-8d5e-4905-bbb4-2aa027472d2c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('01315a2e-f3ea-4093-a870-098cf4026194', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'Why does breathing become much faster and deeper during vigorous physical exercise (like running or swimming)?', 'Elevated metabolic rate increases oxygen consumption and arterial CO₂ tension (hypercapnia), triggering central chemoreceptors to elevate ventilation rate.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6a0e3c9-9a51-4c87-87b0-0238bef505cf', 'Working muscle cells demand more energy (ATP) rapidly, requiring increased Oxygen intake to accelerate aerobic respiration and quickly eliminate excess CO₂', true, '01315a2e-f3ea-4093-a870-098cf4026194');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41d5b60c-968f-4089-960d-bd387dce26d2', 'Because the lungs shrink in cold air', false, '01315a2e-f3ea-4093-a870-098cf4026194');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5df723aa-3179-4e92-8fc6-4f6eda887ccb', 'Because the heart stops beating', false, '01315a2e-f3ea-4093-a870-098cf4026194');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('586b49fa-2772-4348-b52f-4839cb232a75', 'To cool the shoes', false, '01315a2e-f3ea-4093-a870-098cf4026194');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35be1675-62fd-4335-8c09-e6b5cebde04f', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'Why do we sneeze when we inhale foreign irritants (like dust particles, smoke, or pollen)?', 'The sternutatory (sneeze) reflex forcefully expels air (~150 km/h) to cleanse the upper respiratory epithelium of particulate irritants.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f322cd6-2d04-40bf-8b3a-8108afc6a8df', 'The irritants trigger sensory nerves in the nasal lining, initiating a powerful reflex violent expulsion of air to clear foreign contaminants from the nasal tract', true, '35be1675-62fd-4335-8c09-e6b5cebde04f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0212e3b-ca4d-4f8c-b831-72cc97601685', 'To exercise chest muscles', false, '35be1675-62fd-4335-8c09-e6b5cebde04f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8eba7c57-697e-4af6-a090-5e6071f34e90', 'To cool the brain', false, '35be1675-62fd-4335-8c09-e6b5cebde04f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f814ee1-6f0a-4d38-b3d9-a47df0001060', 'Because the stomach is full', false, '35be1675-62fd-4335-8c09-e6b5cebde04f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52daa08e-fc66-4173-b267-f80ade3a473a', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'Why does a mirror fog up when you exhale your breath closely onto its clean glass surface?', 'Cellular respiration produces water vapor byproduct (C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O); exhaled warm vapor condenses on cool glass.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fbf6036-b56e-433b-a28f-f736bbab2e4c', 'Warm exhaled breath is saturated with Water Vapor produced during cellular respiration, which immediately condenses into tiny liquid droplets on the cooler glass surface', true, '52daa08e-fc66-4173-b267-f80ade3a473a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eac8f07c-461d-48a0-90f9-78c5e7c40a88', 'Dust settles on the mirror', false, '52daa08e-fc66-4173-b267-f80ade3a473a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6e59afe-42af-40ef-912f-12725dcc9c11', 'The mirror glass melts', false, '52daa08e-fc66-4173-b267-f80ade3a473a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('631b57a5-7791-482d-a75d-77df9c0e92de', 'The mirror absorbs carbon dioxide', false, '52daa08e-fc66-4173-b267-f80ade3a473a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3a726117-7d5f-4ef3-9055-f1ac366e6077', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'How do Whale and Dolphin mammals breathe while swimming underwater in oceans?', 'Cetaceans are air-breathing mammals with lungs that surface to exchange tidal volume via dorsal blowholes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9068b92-8c9e-44a9-87a7-09e4ea05bf35', 'They do NOT have gills; they possess Lungs and must periodically surface to inhale fresh atmospheric air through a Blowhole located atop their heads', true, '3a726117-7d5f-4ef3-9055-f1ac366e6077');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8d2e5fa-d71c-4ea7-8e4a-f3a29f87335c', 'They breathe through gills like fish', false, '3a726117-7d5f-4ef3-9055-f1ac366e6077');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5977049a-c3bc-4c1a-b6b7-6ea7c45522eb', 'They absorb oxygen through their fins', false, '3a726117-7d5f-4ef3-9055-f1ac366e6077');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dc5a0c2-d8a8-46b7-8e06-07534c2f92f0', 'They do not breathe oxygen', false, '3a726117-7d5f-4ef3-9055-f1ac366e6077');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('05cea617-cffe-4fe8-9772-07925e5499c0', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'In the human respiratory tract, what is the role of the fine Mucus and tiny Cilia lining the nasal passages?', 'Mucociliary escalator: goblet cell mucus traps airborne particulates while ciliated epithelium propels debris pharyngeally.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44d5499e-cd04-4689-bfe3-2b6eef2d240d', 'They trap dust, pollen, soot particles, and microbes from inhaled air, warming and humidifying the air before it reaches the delicate lungs', true, '05cea617-cffe-4fe8-9772-07925e5499c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a44865f-8242-4a35-8bca-73e830ed5942', 'They cool the lungs to 0°C', false, '05cea617-cffe-4fe8-9772-07925e5499c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5be8ff64-ed85-4030-a004-9633ed6fd771', 'They make speaking louder', false, '05cea617-cffe-4fe8-9772-07925e5499c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c52393a9-b94a-4576-b656-eec7abe2fdcc', 'They produce digestive enzymes', false, '05cea617-cffe-4fe8-9772-07925e5499c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e044be77-1159-413a-9d33-9300323a1865', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'What are ''Lenticels'' in woody trees and stems?', 'Lenticels are specialized loosely-packed cork cell fissures in woody periderm enabling gas diffusion into internal parenchyma.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0591ad14-982f-46a7-a537-3d26a1f0c2cf', 'Small porous openings on the woody bark of old stems and roots that facilitate continuous respiratory gas exchange (O₂ and CO₂)', true, 'e044be77-1159-413a-9d33-9300323a1865');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b086681b-a7b4-4668-84ce-24a2a38d2a3c', 'Flower buds', false, 'e044be77-1159-413a-9d33-9300323a1865');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b82d119-55c9-48a6-ade7-709068529083', 'Roots that store sugar', false, 'e044be77-1159-413a-9d33-9300323a1865');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c030611b-2243-4225-a2ba-24506ac3554d', 'Leaves that produce poison', false, 'e044be77-1159-413a-9d33-9300323a1865');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc6b6778-350c-4e96-890c-e55e7ba919a6', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'What happens in a bell-jar and Y-tube plastic bottle model when the rubber sheet tied at the bottom is PULLED DOWNWARDS?', 'Simulating Boyle''s Law: downward displacement of the rubber diaphragm expands internal volume, reducing chamber pressure and inflating lung balloons.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6736f5be-9a8a-4c8b-b6cc-12a874b794b4', 'The volume inside the bottle increases, air pressure drops, and atmospheric air rushes in to INFLATE the two small balloons (simulating lungs)', true, 'fc6b6778-350c-4e96-890c-e55e7ba919a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93591259-86de-4c21-9b40-6237883f83f2', 'The balloons deflate', false, 'fc6b6778-350c-4e96-890c-e55e7ba919a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e17bb2d-f665-4d94-bfb3-5234104ed331', 'The bottle cracks', false, 'fc6b6778-350c-4e96-890c-e55e7ba919a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa73d218-69f8-4ada-8afc-0dc726804735', 'Water fills the bottle', false, 'fc6b6778-350c-4e96-890c-e55e7ba919a6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d911aec-a9d9-454a-9b83-b216cd1f17c8', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'Why do mountaineers climbing Mount Everest carry portable Oxygen Cylinders with them?', 'High-altitude hypobaric hypoxia: barometric pressure drops with altitude, reducing alveolar oxygen partial pressure (pO₂).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09473ba5-0395-4322-ae97-1967fed230f4', 'At high altitudes, the atmospheric pressure and amount of available oxygen in the thin air is drastically lower than at sea level', true, '5d911aec-a9d9-454a-9b83-b216cd1f17c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('685bddbe-646d-4853-9952-07dfec46ac9f', 'To make their backpacks heavier', false, '5d911aec-a9d9-454a-9b83-b216cd1f17c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e9a1508-9dea-4418-a755-a6c0503e66fb', 'To light campfires', false, '5d911aec-a9d9-454a-9b83-b216cd1f17c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8894f9f7-aa71-4453-9214-0060baca8554', 'Because mountains have no wind', false, '5d911aec-a9d9-454a-9b83-b216cd1f17c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d314e87-83f4-45a7-b4df-de85e10f1655', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'Why is yawning often triggered when we are sleepy, bored, or tired?', 'Shallow hypoventilation during drowsiness triggers reflex deep inspiratory yawning to expand collapsed alveoli and oxygenate blood.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('118d8955-62e9-4e36-84f9-07fb2eab2808', 'When we are sleepy, our breathing rate slows down, causing oxygen levels in the blood to drop; a deep yawn takes in a large volume of oxygen to restore alertness', true, '7d314e87-83f4-45a7-b4df-de85e10f1655');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa34174d-60ee-4e8b-b52e-9663a6621159', 'Because the jaw muscles are tired', false, '7d314e87-83f4-45a7-b4df-de85e10f1655');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bf94195-c4f1-4149-960c-f625bc9696cd', 'To make ourselves fall asleep faster', false, '7d314e87-83f4-45a7-b4df-de85e10f1655');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a73f222e-3350-4558-a087-c456ef5d78a7', 'Because of loud noises', false, '7d314e87-83f4-45a7-b4df-de85e10f1655');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('749ed9e4-1dcc-40b4-b3bd-bad4eb6ff173', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'What is the respiratory pigment in human red blood cells (RBCs) that binds with Oxygen to form Oxyhemoglobin for transport to all body cells?', 'Hemoglobin (Hb) tetramer binds up to four O₂ molecules forming oxyhemoglobin (HbO₈) for systemic cellular delivery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e2be22b-8f35-4d51-b5fa-5feba568bf1f', 'Hemoglobin (iron-containing protein)', true, '749ed9e4-1dcc-40b4-b3bd-bad4eb6ff173');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d93af29-9259-4e3d-8399-e0b87b3f8472', 'Chlorophyll', false, '749ed9e4-1dcc-40b4-b3bd-bad4eb6ff173');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e440253e-645b-49f8-87af-b7794695b6b1', 'Melanin', false, '749ed9e4-1dcc-40b4-b3bd-bad4eb6ff173');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef78aceb-2b0d-4bf0-8cc4-341f5c074f75', 'Keratin', false, '749ed9e4-1dcc-40b4-b3bd-bad4eb6ff173');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20e1fed4-5369-493b-b349-c62bd010bd1c', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Medium', 'In what way is Breathing fundamentally different from Cellular Respiration?', 'Breathing is organismal biophysical ventilation; cellular respiration is enzymatic intracellular mitochondrial ATP bioenergetics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21104f81-160e-44ef-9803-5b6619bbf720', 'Breathing is a physical mechanical process of inhaling O₂ and exhaling CO₂ ; Cellular Respiration is a biochemical intracellular catabolic reaction that breaks down glucose to release energy', true, '20e1fed4-5369-493b-b349-c62bd010bd1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91c8b0ce-3027-4998-b114-4734109469bc', 'Breathing produces food and respiration destroys food', false, '20e1fed4-5369-493b-b349-c62bd010bd1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99aed899-7d27-4b63-a0a8-581a244abe9b', 'Breathing only happens in plants', false, '20e1fed4-5369-493b-b349-c62bd010bd1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('163aeca6-beef-44f2-b56c-2cc9b4d73ae5', 'Both are exactly the same thing', false, '20e1fed4-5369-493b-b349-c62bd010bd1c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ef4c6246-1694-4609-b0a4-e3293d6d09b2', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a67b0021-9f91-481a-82bf-36af79bb3d49', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'ef4c6246-1694-4609-b0a4-e3293d6d09b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('721d5b38-f81a-4cce-bc86-f85ef5f14df3', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'ef4c6246-1694-4609-b0a4-e3293d6d09b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cf7624e-754f-440f-ae77-da20965a0e26', '(A) is true, but (R) is false.', false, 'ef4c6246-1694-4609-b0a4-e3293d6d09b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('475f4b95-df8d-4ecf-aee5-5bf6eba382dc', '(A) is false, but (R) is true.', false, 'ef4c6246-1694-4609-b0a4-e3293d6d09b2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e1f5cf9-a03b-4b1c-a96a-6e41fb9ea11f', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'Spot the IMPOSTER in the following animal respiratory adaptations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dbe4073-a9d2-4a9f-a601-5898d46a0ffc', 'Adaptation 1', false, '8e1f5cf9-a03b-4b1c-a96a-6e41fb9ea11f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72dffebf-66e9-481b-8ed8-be10442c55e3', 'Adaptation 2', false, '8e1f5cf9-a03b-4b1c-a96a-6e41fb9ea11f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bc93dea-9682-4ce3-b024-6231a4b6f161', 'Adaptation 3', false, '8e1f5cf9-a03b-4b1c-a96a-6e41fb9ea11f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4dce504-e374-4867-9b5b-e789d0278036', 'Adaptation 4 (Frog tadpoles breathe through GILLS in aquatic larval stage ; lungs develop upon metamorphosis)', true, '8e1f5cf9-a03b-4b1c-a96a-6e41fb9ea11f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9410638c-7c35-427f-8158-02c0345a6cf2', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'In the countercurrent exchange mechanism operating in Fish Gills:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31c4c486-7e62-4b5b-936c-cc484e64cd28', 'Countercurrent flow maintains a continuous, steep oxygen concentration gradient across the entire length of the capillary bed, extracting over 80% of dissolved oxygen from water', true, '9410638c-7c35-427f-8158-02c0345a6cf2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4087fe9-14ae-4e62-aa02-b48e9677d175', 'To prevent water from entering the stomach', false, '9410638c-7c35-427f-8158-02c0345a6cf2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca28bbf2-b14d-45a1-a021-c918ad003184', 'To make the fish swim backwards', false, '9410638c-7c35-427f-8158-02c0345a6cf2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92238dd0-a702-48cf-927b-50d64a060df3', 'To warm up the ocean water', false, '9410638c-7c35-427f-8158-02c0345a6cf2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('afb3f302-1e67-4842-b2f0-76d79be2cb4d', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'Match Column I (Organisms) with Column II (Primary Respiratory Mechanism / Pathway):
(a) Yeast cells          -> (i) Anaerobic Fermentation yielding Ethanol + CO₂
(b) Active human muscles -> (ii) Anaerobic Glycolysis yielding Lactic Acid
(c) Cockroach            -> (iii) Network of Tracheal tubes carrying air directly to cells
(d) Plant roots          -> (iv) Root hairs absorbing soil air from particle interstices', 'Exact biological mapping: Yeast = ethanol fermentation; Muscle deficit = lactic acid; Insect = tracheae; Root = soil interstitial diffusion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5297c34-2c65-4494-876d-00db6750f5b0', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'afb3f302-1e67-4842-b2f0-76d79be2cb4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d54c466d-d169-44e9-bf89-dc536c687414', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'afb3f302-1e67-4842-b2f0-76d79be2cb4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70a6d85b-101e-4d97-a111-aadb4ba6e0ce', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'afb3f302-1e67-4842-b2f0-76d79be2cb4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14377a22-3f01-414b-9c27-34b8d7b26191', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'afb3f302-1e67-4842-b2f0-76d79be2cb4d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49d65d5d-45b9-4cfe-ad94-620336893417', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'Read the statements regarding plant respiration:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('298bbefb-2285-4c54-b9f4-64789824f782', 'Statements 1 and 2 only', true, '49d65d5d-45b9-4cfe-ad94-620336893417');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee33b04e-7f2b-4687-b6af-6a02c5455af2', 'Statements 2 and 3 only', false, '49d65d5d-45b9-4cfe-ad94-620336893417');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('457e85a1-aeab-4af7-a06a-14f1d1a64282', 'Statements 1 and 3 only', false, '49d65d5d-45b9-4cfe-ad94-620336893417');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2471daff-c564-4972-965b-b58560f38834', 'All Statements 1, 2, and 3', false, '49d65d5d-45b9-4cfe-ad94-620336893417');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('290f48cf-52d6-45ae-9ef3-696c9d05a12d', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'What is the structural and physiological significance of the microscopic ''Alveoli'' (air sacs) in human lungs?', 'Human lungs contain ~300-500 million alveoli, creating an enormous ~80 m² microvascular surface area for Fickian gas diffusion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bb4d7a5-7bee-47bc-b1b2-f590eddeb542', 'Millions of thin-walled alveoli provide an immense total surface area (~80 m², size of a tennis court) densely wrapped in capillaries for rapid gas diffusion', true, '290f48cf-52d6-45ae-9ef3-696c9d05a12d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d54a4fa-b1ec-4089-a06f-c29567b0b259', 'They store food inside the lungs', false, '290f48cf-52d6-45ae-9ef3-696c9d05a12d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('171ddee1-e8f0-4c35-a0f5-ac7f19d35e4a', 'They pump blood directly to the brain', false, '290f48cf-52d6-45ae-9ef3-696c9d05a12d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e359b15b-a9c0-4188-9b0c-63199108afcc', 'They filter water out of blood', false, '290f48cf-52d6-45ae-9ef3-696c9d05a12d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97f243b8-320f-42fb-9708-48f1de801f37', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'Why do insect tracheal respiratory systems impose a strict physical upper limit on the maximum body size an insect can achieve?', 'Diffusion kinetics (scaling as distance squared) restrict effective tracheal oxygen delivery to small body lengths under modern 21% atmospheric O₂.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30197215-c9e5-42f1-bbeb-08963ad84488', 'Tracheal gas transport relies primarily on passive gaseous diffusion through narrow tubes; over longer body distances (> a few centimeters), oxygen diffusion slows down drastically', true, '97f243b8-320f-42fb-9708-48f1de801f37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b69d765-64f7-461c-8844-b0a57141b270', 'Because insect legs cannot support weight', false, '97f243b8-320f-42fb-9708-48f1de801f37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb5a99b7-95be-4e39-8b50-4743431da89c', 'Because insects have no eyes', false, '97f243b8-320f-42fb-9708-48f1de801f37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f012ec8-c327-433b-aa48-e0a44e2e24dc', 'Because insects do not eat meat', false, '97f243b8-320f-42fb-9708-48f1de801f37');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('145d74a1-2d4f-47b2-bf55-541cc55ec87f', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'Consider four physiological states:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5309e298-028b-441c-b903-699dc3f88de5', '1 < 4 < 2 < 3', true, '145d74a1-2d4f-47b2-bf55-541cc55ec87f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e223b68-37c6-4315-87c8-0ac8f80a6fcf', '3 < 2 < 4 < 1', false, '145d74a1-2d4f-47b2-bf55-541cc55ec87f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2a9aa20-4f0b-41c5-925e-5723ce41cafb', '4 < 1 < 2 < 3', false, '145d74a1-2d4f-47b2-bf55-541cc55ec87f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7511412e-6b5d-4a2d-a107-6231d5061cb9', '2 < 4 < 1 < 3', false, '145d74a1-2d4f-47b2-bf55-541cc55ec87f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d1fca350-6519-4e41-8dc1-00dc570e8531', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'Why does Carbon Monoxide (CO) gas poisoning cause rapid asphyxiation and death even when ambient oxygen is present?', 'CO binds competitively to heme iron with >200× affinity, stabilizing the R-state and preventing allosteric O₂ delivery to brain and heart.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a705c79c-2027-4427-9a62-2708e2cc114c', 'Carbon monoxide has an affinity for Hemoglobin over 200 times higher than oxygen, forming stable Carboxyhemoglobin and completely blocking oxygen transport to tissues', true, 'd1fca350-6519-4e41-8dc1-00dc570e8531');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7496ceaa-69d9-408e-bdf8-7f9eabc6d87c', 'CO freezes the lungs instantly', false, 'd1fca350-6519-4e41-8dc1-00dc570e8531');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04a39f57-6e3f-4242-badd-7b4f3466bd04', 'CO destroys all bones in the body', false, 'd1fca350-6519-4e41-8dc1-00dc570e8531');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d159fca7-9654-4e05-ae50-e499f3364149', 'CO turns blood into water', false, 'd1fca350-6519-4e41-8dc1-00dc570e8531');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('210ba30c-ac0c-4cc1-abc0-1353d813cf65', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'What is ''Oxygen Debt'' incurred during strenuous anaerobic exercise?', 'Excess Post-exercise Oxygen Consumption (EPOC / oxygen debt) metabolizes lactic acid via the Cori cycle in hepatocytes and restabilizes homeostatic reserves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f7ee342-114c-41e0-8baf-0b958de8904f', 'The extra volume of oxygen required after exercise to oxidize accumulated lactic acid in the liver back into pyruvate/glucose and replenish ATP/phosphocreatine reserves', true, '210ba30c-ac0c-4cc1-abc0-1353d813cf65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e7a308b-cd90-4994-8401-8d78d528a96a', 'The amount of money paid for oxygen cylinders', false, '210ba30c-ac0c-4cc1-abc0-1353d813cf65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('232ea509-2c76-4bb7-9c48-416209c0609b', 'The loss of breath during swimming', false, '210ba30c-ac0c-4cc1-abc0-1353d813cf65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b02c562-adda-4b44-ad45-f10acd0441ce', 'The oxygen stored in the stomach', false, '210ba30c-ac0c-4cc1-abc0-1353d813cf65');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('629df247-c7d9-4e79-8d04-ed850a27f22b', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'How do mangrove plants (like Rhizophora) growing in oxygen-poor, saline waterlogged coastal marshes breathe?', 'Halophytic mangroves deploy negatively geotropic pneumatophores (respiratory knee-roots) equipped with lenticels and aerenchyma for subterranean aeration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('667cfd85-de38-4afa-a8cf-b3dd68e9b68f', 'They produce specialized vertical aerial roots called ''Pneumatophores'' (breathing roots) that grow upwards out of the water and mud with lenticels to intake air', true, '629df247-c7d9-4e79-8d04-ed850a27f22b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e501677a-810f-4934-8299-54591f52c2eb', 'They absorb oxygen through ocean fish', false, '629df247-c7d9-4e79-8d04-ed850a27f22b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('072fb289-e119-4755-b714-d1a8c15ee455', 'They do not require oxygen', false, '629df247-c7d9-4e79-8d04-ed850a27f22b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9633c793-ff06-4a7e-a7a8-c5e52938d449', 'They grow only under sand', false, '629df247-c7d9-4e79-8d04-ed850a27f22b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10dee5fe-5985-40d7-9ee4-44be9bb788dd', 'Class 7', 'Science', 'Chapter 6: Respiration in Organisms', 'Hard', 'What overarching bioenergetic reality is established in Chapter 6 of NCERT Class 7 Science?', 'Chapter 6 illuminates the bioenergetic unity of life: metabolic breakdown of glucose to generate ATP through aerobic and anaerobic evolutionary pathways.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73d74aae-d752-4aaf-93a6-9c779c386a32', 'Respiration is the universal cellular engine of all biological life, converting chemical potential energy stored in organic nutrients into kinetic metabolic ATP that powers growth, repair, movement, and physiological homeostasis across every living kingdom', true, '10dee5fe-5985-40d7-9ee4-44be9bb788dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f1f524d-0453-4705-bcba-777b7dcfc963', 'That only animals need energy to survive', false, '10dee5fe-5985-40d7-9ee4-44be9bb788dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef5ec5e4-c3f5-4543-83b7-eee1f71de23e', 'That respiration only occurs during running', false, '10dee5fe-5985-40d7-9ee4-44be9bb788dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04cb0497-b0d4-48bd-875e-5f0a2d235bc3', 'That breathing and burning wood are identical processes', false, '10dee5fe-5985-40d7-9ee4-44be9bb788dd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18e8896f-b974-4724-857c-333f45ade076', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'A line segment connecting a vertex of a triangle to the MIDPOINT of the opposite side is called a:', 'A median connects a triangle''s vertex to the midpoint of the opposing side. Every triangle has 3 medians meeting at the centroid.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20490803-4f47-44cf-9f50-f588f45ab428', 'Median', true, '18e8896f-b974-4724-857c-333f45ade076');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a70fb9d-052d-40b4-b7f8-1499420da355', 'Altitude', false, '18e8896f-b974-4724-857c-333f45ade076');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aca991d3-eb05-4850-91b0-ccb67fc210ba', 'Angle Bisector', false, '18e8896f-b974-4724-857c-333f45ade076');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca1f9465-f63b-4843-9ec8-f02217df640d', 'Perpendicular Bisector', false, '18e8896f-b974-4724-857c-333f45ade076');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8dcd040-75d1-4812-9e9e-7ddb486d45e1', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'The perpendicular line segment drawn from a vertex of a triangle to the opposite side (or its extension) is called an:', 'An altitude is the perpendicular line dropped from a vertex to the opposite base line.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77343ec2-be0d-48ad-8afc-2dd20f52870f', 'Altitude (or Height)', true, 'c8dcd040-75d1-4812-9e9e-7ddb486d45e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0a696af-3673-4a01-9a2f-0f1e40a9d444', 'Median', false, 'c8dcd040-75d1-4812-9e9e-7ddb486d45e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('094f94f6-d0df-4243-bad9-b3e7f32e6511', 'Hypotenuse', false, 'c8dcd040-75d1-4812-9e9e-7ddb486d45e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2d13763-0149-4fe4-9917-786644dbf165', 'Diagonal', false, 'c8dcd040-75d1-4812-9e9e-7ddb486d45e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7119b7f7-b69a-47ec-9a61-3d4f61a480eb', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'What is the sum of the measures of all three interior angles of ANY triangle on a flat plane (Angle Sum Property)?', 'Euclidean angle sum property: ∠A + ∠B + ∠C = 180° for all triangles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b54f036b-73d3-4829-a396-0ca7a4991a41', '180° (Two Right Angles)', true, '7119b7f7-b69a-47ec-9a61-3d4f61a480eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ce28e0e-c944-4f90-853f-aa53c9b6c6e4', '360°', false, '7119b7f7-b69a-47ec-9a61-3d4f61a480eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d427259-a517-4914-946f-9bae0cc99b11', '90°', false, '7119b7f7-b69a-47ec-9a61-3d4f61a480eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dc5bb07-e6d4-4439-ba33-64f441fcf48b', '270°', false, '7119b7f7-b69a-47ec-9a61-3d4f61a480eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e59c54e-14ae-4b19-8ed9-ebb2edc7fd78', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'According to the Exterior Angle Property of a triangle, an exterior angle is ALWAYS equal to:', 'Exterior Angle Property: ∠Ext = ∠Int_opp1 + ∠Int_opp2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2d8831f-c66c-429a-8f51-3ad073800bd1', 'The sum of its two interior opposite angles', true, '4e59c54e-14ae-4b19-8ed9-ebb2edc7fd78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f951fb8-c2f8-4d9d-a82f-7aca28c318c6', '180° minus the adjacent angle only', false, '4e59c54e-14ae-4b19-8ed9-ebb2edc7fd78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f832543c-4aee-4c65-9644-efa426abc6fe', '90°', false, '4e59c54e-14ae-4b19-8ed9-ebb2edc7fd78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('832a6f37-92c4-4ead-90ad-a9b7a6d2d643', 'The sum of all three angles', false, '4e59c54e-14ae-4b19-8ed9-ebb2edc7fd78');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2c0ec03e-4beb-4816-aecd-ef8fbe810cf5', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'In an Equilateral Triangle, what is the measure of EACH of the three interior angles?', 'All three sides and all three angles are equal in an equilateral triangle: 180° / 3 = 60°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a3e8e46-a5c7-4711-bd80-0b6981592fb3', '60° (All three angles are strictly equal: 180° / 3 = 60°)', true, '2c0ec03e-4beb-4816-aecd-ef8fbe810cf5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cfb98c9-237e-4183-b975-ff8a23fed859', '45°', false, '2c0ec03e-4beb-4816-aecd-ef8fbe810cf5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9abe537-ef0c-42bc-b59c-ec276bb5618c', '90°', false, '2c0ec03e-4beb-4816-aecd-ef8fbe810cf5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08e8e72d-497a-4a28-be27-3e731848b49c', '30°', false, '2c0ec03e-4beb-4816-aecd-ef8fbe810cf5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6fa5b116-f859-460e-9173-6c198dc10822', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'In an Isosceles Triangle, if two sides are equal in length, what is true about the angles OPPOSITE to those equal sides?', 'Base angles theorem: in an isosceles triangle, angles opposite to equal sides are congruent.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca2d542d-ff5a-46c7-a535-169fbc61af65', 'The angles opposite to equal sides are ALWAYS equal in measure', true, '6fa5b116-f859-460e-9173-6c198dc10822');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('700355eb-f077-4597-9c75-25fb80d1ec9b', 'They sum to 90°', false, '6fa5b116-f859-460e-9173-6c198dc10822');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('011bd62c-1469-41e8-992f-6546f16e95ad', 'They are unequal', false, '6fa5b116-f859-460e-9173-6c198dc10822');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efaa79fd-34d0-4a64-8546-ff70fd63d3c3', 'One is always 90°', false, '6fa5b116-f859-460e-9173-6c198dc10822');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d773222-6a96-48a5-b7ad-8d1ce75d6813', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'According to the Triangle Inequality Property, the sum of the lengths of any two sides of a triangle must ALWAYS be:', 'Triangle inequality axiom: for any valid triangle with side lengths a, b, c: a + b > c, b + c > a, and c + a > b.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47e85772-0425-4376-a040-d6acac6b8993', 'Strictly GREATER than the length of the third side (a + b > c)', true, '9d773222-6a96-48a5-b7ad-8d1ce75d6813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3608fd21-3e47-4e75-b3d8-5d697f5632c1', 'Equal to the third side', false, '9d773222-6a96-48a5-b7ad-8d1ce75d6813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f0ee6ad-946d-486f-b29b-afc1dd46955a', 'Less than the third side', false, '9d773222-6a96-48a5-b7ad-8d1ce75d6813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47934cdc-f24e-48b0-a585-a2575e077fff', 'Zero', false, '9d773222-6a96-48a5-b7ad-8d1ce75d6813');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('375cf895-6c17-438c-af65-048bb6ea0e63', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'In a Right-Angled Triangle, the side opposite to the 90° right angle is the longest side, called the:', 'The hypotenuse is the side opposing the 90° right angle and is the longest side of a right-angled triangle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('890f4474-aa42-4b8e-a1c8-6ba7a7e2297f', 'Hypotenuse', true, '375cf895-6c17-438c-af65-048bb6ea0e63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4612ed72-11f3-48e4-b09a-9d8c8cb454b1', 'Base', false, '375cf895-6c17-438c-af65-048bb6ea0e63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcfbe105-3ce9-422f-a657-68adf4b8218d', 'Altitude', false, '375cf895-6c17-438c-af65-048bb6ea0e63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('486e352a-660b-4261-ae33-2c2356336b1f', 'Median', false, '375cf895-6c17-438c-af65-048bb6ea0e63');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18920021-92d2-490c-ac51-a1af96992cd0', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'What is the famous Pythagoras Theorem formula for a right-angled triangle with legs a, b and hypotenuse c?', 'Pythagorean Theorem: in any right-angled triangle, Hypotenuse² = Perpendicular² + Base² (c² = a² + b²).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02ac4394-7b3c-4242-b4d1-2736b6dda419', 'a² + b² = c² (Hypotenuse² = Base² + Perpendicular²)', true, '18920021-92d2-490c-ac51-a1af96992cd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51dac72c-4f2c-4855-9b68-acef30baebb3', 'a + b = c', false, '18920021-92d2-490c-ac51-a1af96992cd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d09446e-821c-4630-bedf-9cce84967722', 'a² - b² = c²', false, '18920021-92d2-490c-ac51-a1af96992cd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19cbbe8f-11cd-4621-8caf-bc239caf30fc', 'a × b = c²', false, '18920021-92d2-490c-ac51-a1af96992cd0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da5448b0-6b67-46c1-befb-f03c77a92777', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'Two angles of a triangle are 50° and 70°. Find the measure of the third angle:', 'Third angle = 180° - (50° + 70°) = 180° - 120° = 60°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5696dc19-6a82-497f-844d-80d9dc36b8f3', '60° (180° - (50° + 70°) = 180° - 120° = 60°)', true, 'da5448b0-6b67-46c1-befb-f03c77a92777');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e80dd0b4-d414-44c0-b923-d1bc171090c1', '50°', false, 'da5448b0-6b67-46c1-befb-f03c77a92777');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f72fb452-4503-4864-a261-8948ac4eb90e', '70°', false, 'da5448b0-6b67-46c1-befb-f03c77a92777');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('370f6983-58a2-4d0e-8432-16b06fe254e2', '80°', false, 'da5448b0-6b67-46c1-befb-f03c77a92777');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('650f2b78-41eb-4e72-b691-c3e3fe34e6c5', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'An exterior angle of a triangle is 110°, and one of the interior opposite angles is 40°. Find the other interior opposite angle:', 'Ext angle = Int1 + Int2 → 110° = 40° + x → x = 70°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f9f55b6-3de0-425e-afb2-491377a04ad4', '70° (110° - 40° = 70°)', true, '650f2b78-41eb-4e72-b691-c3e3fe34e6c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3573492-6a17-41d2-8ae9-215fd46a6784', '80°', false, '650f2b78-41eb-4e72-b691-c3e3fe34e6c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('373e482b-563c-4675-9a66-bac582207523', '60°', false, '650f2b78-41eb-4e72-b691-c3e3fe34e6c5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51f15a64-c1fd-4407-8cf8-3e99717b69f9', '50°', false, '650f2b78-41eb-4e72-b691-c3e3fe34e6c5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38d7ecd5-bc70-4b59-9f77-e61cce180cb0', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Easy', 'Can a triangle have two RIGHT angles (90° + 90°)?', 'Two 90° angles sum to 180°, which violates the angle sum property since the third angle must be strictly positive.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('567db236-38b8-4e82-b1a6-ef7c5e3e5e76', 'No, because two right angles sum to 180°, leaving 0° for the third angle, making a triangle impossible', true, '38d7ecd5-bc70-4b59-9f77-e61cce180cb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f5778e8-1f5c-4fc2-9cee-215695428c2d', 'Yes, in right isosceles triangles', false, '38d7ecd5-bc70-4b59-9f77-e61cce180cb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6ff720d-a1c8-455b-8159-4a11fd84eb1d', 'Yes, in large triangles', false, '38d7ecd5-bc70-4b59-9f77-e61cce180cb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1be575ee-5dd5-4032-836b-f98dcfda2f50', 'Always yes', false, '38d7ecd5-bc70-4b59-9f77-e61cce180cb0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('671a89da-12b9-4485-8f00-6dfd12fa93da', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'The three interior angles of a triangle are in the ratio 1 : 2 : 3. Find the measure of each angle:', '6x = 180° → x = 30°. Angles are 1(30) = 30°, 2(30) = 60°, and 3(30) = 90°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42c93e86-7baa-4e75-9fb9-46517f87390d', '30°, 60°, and 90° (x + 2x + 3x = 180° ⇒ 6x = 180° ⇒ x = 30° ⇒ 30°, 60°, 90°)', true, '671a89da-12b9-4485-8f00-6dfd12fa93da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a33ff98c-84fe-4c5d-af93-9d9a96a7c86c', '20°, 40°, 120°', false, '671a89da-12b9-4485-8f00-6dfd12fa93da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('902fde2f-cef6-45c7-b966-621227aa441b', '45°, 45°, 90°', false, '671a89da-12b9-4485-8f00-6dfd12fa93da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a83dcda-eb90-4248-9545-edff33cbad1a', '30°, 75°, 75°', false, '671a89da-12b9-4485-8f00-6dfd12fa93da');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2a4c5fb7-57cb-45da-bd02-8b74b2cb021c', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'In an Isosceles Triangle, the vertex angle is 40°. What is the measure of each equal base angle?', '2x + 40° = 180° → 2x = 140° → x = 70°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('364dd5ec-605a-4916-ae20-d0e1dd6fcdc9', '70° each ((180° - 40°) / 2 = 140° / 2 = 70°)', true, '2a4c5fb7-57cb-45da-bd02-8b74b2cb021c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a8799b4-da96-4540-b0cd-24acc90d45ae', '60° each', false, '2a4c5fb7-57cb-45da-bd02-8b74b2cb021c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba2a2a33-1883-4e2f-b66c-4ca911d30f12', '80° each', false, '2a4c5fb7-57cb-45da-bd02-8b74b2cb021c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32e7ebef-80a1-47c2-8df0-43d220c07937', '50° each', false, '2a4c5fb7-57cb-45da-bd02-8b74b2cb021c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e0973a4-dfee-41c6-8c70-e9d4169374d3', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'Which of the following sets of side lengths CAN form a valid triangle?', 'Only 6, 8, 10 satisfies the strict triangle inequality theorem (6 + 8 = 14 > 10).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78077b2e-88fc-4693-8eb4-6851c54d8028', '6 cm, 8 cm, 10 cm (Since 6 + 8 > 10, 6 + 10 > 8, and 8 + 10 > 6)', true, '3e0973a4-dfee-41c6-8c70-e9d4169374d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('add42e36-f44a-49f7-aaf7-036f345b41b0', '2 cm, 3 cm, 6 cm (2 + 3 = 5 < 6, impossible)', false, '3e0973a4-dfee-41c6-8c70-e9d4169374d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bda41387-55c5-4b58-a4e6-793331386eb8', '3 cm, 4 cm, 7 cm (3 + 4 = 7, not strictly greater, impossible)', false, '3e0973a4-dfee-41c6-8c70-e9d4169374d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('070dbf0a-e738-4fdc-8d02-51953460304e', '1 cm, 2 cm, 5 cm (1 + 2 = 3 < 5, impossible)', false, '3e0973a4-dfee-41c6-8c70-e9d4169374d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3a59c9ca-18a6-45b8-a0ae-e963e51a5b66', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'In a right-angled triangle, the lengths of the two legs are 3 cm and 4 cm. What is the length of the hypotenuse?', 'c = √(3² + 4²) = √(9 + 16) = √25 = 5 cm (classic 3-4-5 Pythagorean triplet).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64e69dcb-fdd3-4eda-a827-ac951553b883', '5 cm (Hypotenuse = √(3² + 4²) = √(9 + 16) = √25 = 5 cm)', true, '3a59c9ca-18a6-45b8-a0ae-e963e51a5b66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44734c57-80cd-48a9-9d47-0936f202efed', '7 cm', false, '3a59c9ca-18a6-45b8-a0ae-e963e51a5b66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70cb41fb-7b3f-46fb-af93-aeefdc2aa0de', '6 cm', false, '3a59c9ca-18a6-45b8-a0ae-e963e51a5b66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cae190fa-af30-4c59-8644-67f90a6c035f', '8 cm', false, '3a59c9ca-18a6-45b8-a0ae-e963e51a5b66');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('639d7cc2-c280-4e8f-a5a3-1c771b019ef1', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'A 15 m long ladder reaches a window 12 m high from the ground on placing it against a wall. Find the distance of the foot of the ladder from the wall:', 'Base = √(15² - 12²) = √(225 - 144) = √81 = 9 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('833bdec7-c57f-44ee-87ac-6ffb1e8c6ad5', '9 m (Distance = √(15² - 12²) = √(225 - 144) = √81 = 9 m)', true, '639d7cc2-c280-4e8f-a5a3-1c771b019ef1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1362dc32-1f64-4f4f-9e7d-555429f0e48f', '6 m', false, '639d7cc2-c280-4e8f-a5a3-1c771b019ef1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe334100-7d49-4e0d-96db-d3db9ddafdf6', '8 m', false, '639d7cc2-c280-4e8f-a5a3-1c771b019ef1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac3a220a-abed-4073-a4a3-862ed788785c', '10 m', false, '639d7cc2-c280-4e8f-a5a3-1c771b019ef1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('078575d9-4a0c-4aa8-91ae-5363b3111862', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'The lengths of two sides of a triangle are 12 cm and 15 cm. Between what two whole numbers must the length of the third side lie?', 'Third side range: (15 - 12) < side < (15 + 12) → 3 cm < x < 27 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5e1cc1a-f20f-4cbc-97b0-8a7718d23dee', 'Between 3 cm and 27 cm (Difference: 15 - 12 = 3 cm < third side < Sum: 15 + 12 = 27 cm)', true, '078575d9-4a0c-4aa8-91ae-5363b3111862');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfe34949-5948-4543-8dd7-fbb2bab7cf2e', 'Between 12 cm and 15 cm', false, '078575d9-4a0c-4aa8-91ae-5363b3111862');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6438f3f8-7392-4b2c-9f61-6ed61f7348c2', 'Between 0 cm and 12 cm', false, '078575d9-4a0c-4aa8-91ae-5363b3111862');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec0170ad-9e61-4a14-bf82-e1db146c9ca1', 'Between 5 cm and 30 cm', false, '078575d9-4a0c-4aa8-91ae-5363b3111862');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88573282-20fc-4599-ad66-0c7c63e8be21', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'A tree broke at a height of 5 m from the ground and its top touched the ground at a distance of 12 m from the base of the tree. Find the ORIGINAL full height of the tree:', 'Hypotenuse = √(5² + 12²) = 13 m. Total original tree height = standing trunk (5 m) + fallen crown (13 m) = 18 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e262bf94-2770-451a-a82b-c99b7badaebe', '18 m (Broken broken part = √(5² + 12²) = √(25 + 144) = √169 = 13 m ; Total height = 5 + 13 = 18 m)', true, '88573282-20fc-4599-ad66-0c7c63e8be21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6b0ce15-8ac8-4176-9606-640d5e50fa11', '17 m', false, '88573282-20fc-4599-ad66-0c7c63e8be21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4fb7704-b302-4403-8159-0a47bce12743', '13 m', false, '88573282-20fc-4599-ad66-0c7c63e8be21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('763125db-094f-49e1-8b21-844d48b3e2c8', '20 m', false, '88573282-20fc-4599-ad66-0c7c63e8be21');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31c0a075-6a77-4d33-b34d-ec24930c761d', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'In ΔABC, if ∠B = 35° and ∠C = 55°, which of the following is true?', '∠A = 180° - 90° = 90°. The right angle is at A, so opposite side BC is the hypotenuse: AB² + AC² = BC².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81b783f6-cb80-446d-b42b-83cfa10e2747', 'AB² + BC² = AC² is FALSE, but AB² + AC² = BC² is TRUE (Since ∠A = 180° - (35°+55°) = 90°, so BC is the hypotenuse: AB² + AC² = BC²)', true, '31c0a075-6a77-4d33-b34d-ec24930c761d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9da264a9-8fe3-425b-aca1-1f5b625497c2', 'AB² + BC² = AC²', false, '31c0a075-6a77-4d33-b34d-ec24930c761d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4c6dcfd-1c13-43b3-9024-f287586b3481', 'BC² + AC² = AB²', false, '31c0a075-6a77-4d33-b34d-ec24930c761d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c13bb3d-af1f-4097-b745-433c0fa21fed', 'AB + BC = AC', false, '31c0a075-6a77-4d33-b34d-ec24930c761d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('032ee04b-702d-42a0-a41d-9ba94c24725b', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'Find the perimeter of the rectangle whose length is 40 cm and diagonal is 41 cm:', 'Width = √(41² - 40²) = √81 = 9 cm. Perimeter = 2(l + w) = 2(40 + 9) = 98 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('050103a6-02a0-4203-a94c-ee0d798d5bac', '98 cm (Breadth = √(41² - 40²) = √(1681 - 1600) = √81 = 9 cm ; Perimeter = 2(40 + 9) = 2(49) = 98 cm)', true, '032ee04b-702d-42a0-a41d-9ba94c24725b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b13570d3-014b-47c1-8ba9-bc83306f6973', '82 cm', false, '032ee04b-702d-42a0-a41d-9ba94c24725b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8c32f5b-12f5-4a22-ba8a-0b34395e2941', '100 cm', false, '032ee04b-702d-42a0-a41d-9ba94c24725b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('041e9835-9390-42fb-8216-b26fe28682b7', '90 cm', false, '032ee04b-702d-42a0-a41d-9ba94c24725b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04d661e1-3b70-4b95-a47b-86d6e0bd534e', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'The diagonals of a rhombus measure 16 cm and 12 cm. Find its perimeter:', 'Rhombus side = √(8² + 6²) = 10 cm. Perimeter = 4 × 10 = 40 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('062b5123-0322-41a6-bb8f-b597840c7637', '40 cm (Diagonals bisect at 90°: half-lengths are 8 cm and 6 cm ; Side = √(8² + 6²) = √(64 + 36) = √100 = 10 cm ; Perimeter = 4 × 10 = 40 cm)', true, '04d661e1-3b70-4b95-a47b-86d6e0bd534e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bde6280-eea5-46e2-afe2-b1b7073a3188', '28 cm', false, '04d661e1-3b70-4b95-a47b-86d6e0bd534e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f68d18d-dce1-478f-ae18-30a9ebcd60b0', '48 cm', false, '04d661e1-3b70-4b95-a47b-86d6e0bd534e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9aa22ab-52a1-4746-aace-4fae56531bfe', '56 cm', false, '04d661e1-3b70-4b95-a47b-86d6e0bd534e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc8a9857-5bcf-45ff-9b67-833fcd038987', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'Can an OBTUSE-ANGLED triangle have an altitude that lies OUTSIDE the triangle?', 'In an obtuse triangle, altitudes drawn from acute vertices fall on extended bases outside the triangular boundary.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b17e3ec1-113c-4f2e-8865-9095d4b43164', 'Yes, two of the altitudes in an obtuse-angled triangle fall outside the triangle onto the extended opposite sides', true, 'cc8a9857-5bcf-45ff-9b67-833fcd038987');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c455337-417d-4af5-9db1-30b797d87228', 'No, altitudes are always strictly inside', false, 'cc8a9857-5bcf-45ff-9b67-833fcd038987');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b7787e4-138b-488c-8d97-efffe763b215', 'Only in right triangles', false, 'cc8a9857-5bcf-45ff-9b67-833fcd038987');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abb7c73c-9ebd-44fe-b15c-23247ea3c6d9', 'Never', false, 'cc8a9857-5bcf-45ff-9b67-833fcd038987');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d308147-f7c9-4c7d-9a0c-5ddb4550041d', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'In ΔPQR, D is the midpoint of side QR. What is line segment PM (where PM ⊥ QR) and line segment PD?', 'PM is perpendicular (altitude); PD joins vertex P to midpoint D of base QR (median).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9862aec0-7903-4433-ab67-83d6f79def68', 'PM is an ALTITUDE ; PD is a MEDIAN', true, '0d308147-f7c9-4c7d-9a0c-5ddb4550041d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cbe00cd-3d12-4043-a38a-881fef41edf8', 'PM is a median ; PD is an altitude', false, '0d308147-f7c9-4c7d-9a0c-5ddb4550041d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('879151ed-47e3-40e3-87a6-fc7791ccca24', 'Both are medians', false, '0d308147-f7c9-4c7d-9a0c-5ddb4550041d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('789c0532-782b-48e2-8dfd-6fdb9763d876', 'Both are altitudes', false, '0d308147-f7c9-4c7d-9a0c-5ddb4550041d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ac78ce5-4ebf-454a-847d-c66a969ec74b', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'An exterior angle of a triangle is 120°, and the two interior opposite angles are EQUAL to each other. Find the measure of each interior opposite angle:', 'x + x = 120° → 2x = 120° → x = 60°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54169822-9a6a-4afc-95a1-9d4b52ee98d1', '60° each (2x = 120° ⇒ x = 60°)', true, '2ac78ce5-4ebf-454a-847d-c66a969ec74b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c535a1fa-cd6a-4a20-a688-0338dc89ae6f', '50° each', false, '2ac78ce5-4ebf-454a-847d-c66a969ec74b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2c49318-2a6d-4f62-b5bd-75bb6d1814f1', '40° each', false, '2ac78ce5-4ebf-454a-847d-c66a969ec74b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbfcab89-b869-4f15-b9e1-101e1ce06c9f', '70° each', false, '2ac78ce5-4ebf-454a-847d-c66a969ec74b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5b80319b-7eba-47e3-8a7d-9142aaa878f3', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'One of the acute angles of a right-angled triangle is 35°. What is the measure of the other acute angle?', 'The two acute angles in a right-angled triangle are complementary: 90° - 35° = 55°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('345ddbe2-8017-47fe-abda-34fb5f0ccca8', '55° (90° - 35° = 55°)', true, '5b80319b-7eba-47e3-8a7d-9142aaa878f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('224f8196-3856-41df-a0ab-7b70ac58cca5', '45°', false, '5b80319b-7eba-47e3-8a7d-9142aaa878f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd880d3b-b283-4beb-a90a-f08d218617ff', '65°', false, '5b80319b-7eba-47e3-8a7d-9142aaa878f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82502d04-511b-4f55-9d4a-1040cd2fd997', '35°', false, '5b80319b-7eba-47e3-8a7d-9142aaa878f3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b9378d8e-8c5f-42f4-b188-63da159a930f', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'In an equilateral triangle ΔABC, an altitude AD is drawn from A to BC. What special property does AD have?', 'Symmetry of equilateral triangles: altitude, median, angle bisector, and perpendicular bisector coincide along the same axis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a00901a-c51b-4afa-be3f-e41683691b5a', 'In an equilateral triangle, Altitude AD is ALSO the Median (it bisects the opposite side BC) and also the Angle Bisector of ∠A', true, 'b9378d8e-8c5f-42f4-b188-63da159a930f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8c49db2-be61-4f91-aae3-8b62ff15380e', 'AD only measures 1 cm', false, 'b9378d8e-8c5f-42f4-b188-63da159a930f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50620047-6232-47f5-963f-47e03876066b', 'AD is parallel to BC', false, 'b9378d8e-8c5f-42f4-b188-63da159a930f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8dd0a8b-1327-498f-b49a-8fcbed55f0d8', 'AD lies outside the triangle', false, 'b9378d8e-8c5f-42f4-b188-63da159a930f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d665075c-f364-4171-9666-41e77e6a522c', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Medium', 'Which of the following is a classic PYTHAGOREAN TRIPLET?', '5² + 12² = 25 + 144 = 169 = 13², confirming (5, 12, 13) is a primitive Pythagorean triplet.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2576f9af-78e4-46a3-9df9-62b752bd5e9a', '(5, 12, 13) since 5² + 12² = 25 + 144 = 169 = 13²', true, 'd665075c-f364-4171-9666-41e77e6a522c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c2ed9fa-c4ca-4b04-b4b9-7df75c0b30e8', '(4, 5, 6)', false, 'd665075c-f364-4171-9666-41e77e6a522c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2269f11f-fb4a-41af-ae4f-f6b3bdc1d658', '(2, 3, 4)', false, 'd665075c-f364-4171-9666-41e77e6a522c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1bd1cec-0e74-40ce-a4aa-5ad61c6e8a8d', '(6, 7, 8)', false, 'd665075c-f364-4171-9666-41e77e6a522c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3633490-3462-4fd3-9eac-90f9782bfd7b', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('918bbd2d-e40d-45cb-9a2a-023af9e79c5c', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'f3633490-3462-4fd3-9eac-90f9782bfd7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cb932bf-079d-4d29-8b54-3ca55955d5ac', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'f3633490-3462-4fd3-9eac-90f9782bfd7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba56c776-4a11-4914-9af4-af0e0ca716a1', '(A) is true, but (R) is false.', false, 'f3633490-3462-4fd3-9eac-90f9782bfd7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea07221e-4461-44aa-ad8b-609fcac4e9f3', '(A) is false, but (R) is true.', false, 'f3633490-3462-4fd3-9eac-90f9782bfd7b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5c04ce6-a621-4944-a5a7-0763996c55cf', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'Spot the IMPOSTER in the following geometric triangle theorems:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('749d3e93-76fd-41a7-ae06-67ea4787a501', 'Theorem 1', false, 'a5c04ce6-a621-4944-a5a7-0763996c55cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c66de5f-efaf-4c65-8c34-d11433d91aa9', 'Theorem 2', false, 'a5c04ce6-a621-4944-a5a7-0763996c55cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59fd2f66-227e-4e4c-9e13-b47caa55ecc4', 'Theorem 3', false, 'a5c04ce6-a621-4944-a5a7-0763996c55cf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95a7ed49-80de-42e4-bac3-c43084e0f897', 'Theorem 4 (In any triangle, the LONGEST side is opposite to the LARGEST angle, not the smallest)', true, 'a5c04ce6-a621-4944-a5a7-0763996c55cf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae7aa6bb-3c5e-497e-9290-8e3a016c02e2', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'In ΔABC, AM is a median on side BC. Prove that:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e15b4ce5-369c-414f-85c0-af9b114030f3', 'In ΔABM: AB + BM > AM ; In ΔACM: AC + MC > AM ; Adding both: AB + (BM + MC) + AC > 2AM ⇒ AB + BC + CA > 2AM', true, 'ae7aa6bb-3c5e-497e-9290-8e3a016c02e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bacb9d6c-d98d-4d59-94b8-ea38de49afbb', 'Because all sides of ΔABC are equal to AM', false, 'ae7aa6bb-3c5e-497e-9290-8e3a016c02e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2943af7-b077-434f-9e88-a4d445032470', 'Because AM is perpendicular to BC', false, 'ae7aa6bb-3c5e-497e-9290-8e3a016c02e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a40c0513-13b0-4fc8-89a7-554fa4fb67b2', 'Because triangles have no perimeter', false, 'ae7aa6bb-3c5e-497e-9290-8e3a016c02e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77e60635-7855-411d-91ce-498ada6df2d8', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'Match Column I (Triangle Concurrence Centers) with Column II (Defining Line Intersections):
(a) Centroid      -> (i) Concurrence point of all 3 Medians (divides each median in 2:1 ratio)
(b) Orthocentre   -> (ii) Concurrence point of all 3 Altitudes
(c) Incentre      -> (iii) Concurrence point of all 3 Internal Angle Bisectors
(d) Circumcentre  -> (iv) Concurrence point of all 3 Perpendicular Bisectors of sides', 'Centroid = medians; Orthocentre = altitudes; Incentre = angle bisectors; Circumcentre = perpendicular bisectors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('225da6d5-d823-4f42-90a3-4f026197ea33', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '77e60635-7855-411d-91ce-498ada6df2d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fece498f-e483-443a-9300-7429bd7e72f1', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '77e60635-7855-411d-91ce-498ada6df2d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8c1b4f1-bc18-487e-8b89-d48389324dd5', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '77e60635-7855-411d-91ce-498ada6df2d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d8271fb-2141-423e-a80d-b1494aacd2e1', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '77e60635-7855-411d-91ce-498ada6df2d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('224822d1-097d-4f42-b5c9-b5d918b91d9b', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'Read the statements regarding right triangles and Pythagoras property:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('131f8c6a-bd53-43b7-910a-52c265dee270', 'Statements 1 and 2 only', true, '224822d1-097d-4f42-b5c9-b5d918b91d9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('392ae58c-0158-4311-833b-e1919a9973ef', 'Statements 2 and 3 only', false, '224822d1-097d-4f42-b5c9-b5d918b91d9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4350fe5d-5451-496d-8f87-bd4c8860a66b', 'Statements 1 and 3 only', false, '224822d1-097d-4f42-b5c9-b5d918b91d9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecb6ff76-7db5-4a3e-be7e-0abf3994547c', 'All Statements 1, 2, and 3', false, '224822d1-097d-4f42-b5c9-b5d918b91d9b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('594a8984-f2cf-45eb-ab69-17f15e2b3865', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'In a quadrilateral ABCD, prove that:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3846222-54e5-457e-bc09-b27a1b27f475', 'In ΔABC: AB + BC > AC ; In ΔADC: CD + DA > AC ; In ΔABD: AB + DA > BD ; In ΔBCD: BC + CD > BD ; Adding all four inequalities and dividing by 2 gives AB + BC + CD + DA > AC + BD', true, '594a8984-f2cf-45eb-ab69-17f15e2b3865');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc99e0d6-fcf4-4e38-8b9c-d0e879fb3c1b', 'Because diagonals are always zero', false, '594a8984-f2cf-45eb-ab69-17f15e2b3865');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f2e4108-965b-4d31-ac0e-408ce2c3bfe5', 'Because all quadrilaterals are squares', false, '594a8984-f2cf-45eb-ab69-17f15e2b3865');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76d2ce7a-0498-4828-9769-ed696578f8a0', 'Because perimeter equals area', false, '594a8984-f2cf-45eb-ab69-17f15e2b3865');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e31a6ae7-0ffb-4cc2-b9ff-b9247185f373', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'Let O be any interior point in ΔABC. Which of the following inequalities is strictly true?', 'Triangle inequality on the three sub-triangles meeting at O gives 2(OA + OB + OC) > AB + BC + CA → OA + OB + OC > ½(AB + BC + CA).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caa89109-41ed-4a8d-919a-2c0dc81278ac', 'OA + OB + OC > 1/2 (AB + BC + CA) (In ΔOAB: OA + OB > AB ; ΔOBC: OB + OC > BC ; ΔOCA: OC + OA > CA ; Adding gives 2(OA+OB+OC) > AB+BC+CA)', true, 'e31a6ae7-0ffb-4cc2-b9ff-b9247185f373');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8a7ce82-c7c2-4f88-90aa-50944c6bf587', 'OA + OB + OC < 1/2 (AB + BC + CA)', false, 'e31a6ae7-0ffb-4cc2-b9ff-b9247185f373');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ac1cef0-1035-41c1-a81d-035a59e31b67', 'OA + OB + OC = AB + BC + CA', false, 'e31a6ae7-0ffb-4cc2-b9ff-b9247185f373');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e24cfa5-c5b0-41b8-83c0-1c86218cff83', 'OA = OB = OC = 0', false, 'e31a6ae7-0ffb-4cc2-b9ff-b9247185f373');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6bd3c122-f03b-462a-95ef-009bc0174295', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'In an isosceles right-angled triangle, if each of the two equal perpendicular legs is of length ''x'', what is the length of the hypotenuse?', 'c = √(x² + x²) = √(2x²) = x√2 (the 45°-45°-90° special right triangle).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('913d2412-e8b9-4ff4-8fe7-dbe4b053b6e1', 'x√2 (Hypotenuse = √(x² + x²) = √(2x²) = x√2)', true, '6bd3c122-f03b-462a-95ef-009bc0174295');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57b67119-56f4-467a-913b-99a813924afd', '2x', false, '6bd3c122-f03b-462a-95ef-009bc0174295');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ff9abab-f362-419f-ab9a-ad771daccebb', 'x / 2', false, '6bd3c122-f03b-462a-95ef-009bc0174295');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('243dcfb6-5838-4cad-9d36-baa1ab1c04eb', 'x²', false, '6bd3c122-f03b-462a-95ef-009bc0174295');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e33771f-a517-48c6-805d-6ca59a58b240', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'Two poles of height 6 m and 11 m stand vertically on a plane ground. If the horizontal distance between their feet is 12 m, find the direct distance between their tops:', 'Right triangle formed with base 12 m and vertical height (11 - 6) = 5 m. Distance = √(5² + 12²) = 13 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31371bc3-6f57-4ad3-bdbd-deafabaf917f', '13 m (Vertical difference = 11 - 6 = 5 m ; Top distance = √(5² + 12²) = √(25 + 144) = √169 = 13 m)', true, '6e33771f-a517-48c6-805d-6ca59a58b240');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f803ae1c-c7f8-409e-a40b-ec2584ef5cd2', '12 m', false, '6e33771f-a517-48c6-805d-6ca59a58b240');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27919926-109f-401f-ae5d-9834140b94e4', '14 m', false, '6e33771f-a517-48c6-805d-6ca59a58b240');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd1b9da9-a527-4730-a442-47430ddd0bc5', '15 m', false, '6e33771f-a517-48c6-805d-6ca59a58b240');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23610905-33c4-4a8a-85ad-ec66070ca2c7', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'In ΔPQR, the bisectors of interior ∠Q and interior ∠R meet at point O. What is the measure of ∠QOR in terms of ∠P?', 'In ΔQOR: ∠QOR = 180° - (∠Q/2 + ∠R/2) = 180° - ((180° - ∠P)/2) = 180° - 90° + ∠P/2 = 90° + ∠P/2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed1552f5-8acd-4fef-911f-b8a80ea89e2c', '∠QOR = 90° + (1/2) ∠P', true, '23610905-33c4-4a8a-85ad-ec66070ca2c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e09f4bee-657a-4212-8ce5-3dbced07b200', '∠QOR = 90° - (1/2) ∠P', false, '23610905-33c4-4a8a-85ad-ec66070ca2c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7994909b-a3a6-4b5b-93c8-a491768ea22a', '∠QOR = 180° - ∠P', false, '23610905-33c4-4a8a-85ad-ec66070ca2c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e764a9a-ca2b-42c9-8af7-03bcf9daa043', '∠QOR = 2 ∠P', false, '23610905-33c4-4a8a-85ad-ec66070ca2c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6270fe82-598c-4028-b22a-a86f262bcf1b', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'If a line segment drawn from a vertex of a triangle is BOTH an altitude and a median to the opposite side, what type of triangle is it?', 'By SAS congruence of the two divided sub-triangles (common altitude, equal divided base, 90° angle), the adjacent sides are equal, proving it is isosceles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90c029a6-1981-4c4e-8844-9adce3831ab3', 'It is at least an ISOSCELES TRIANGLE (and if true for all 3 vertices, an Equilateral Triangle)', true, '6270fe82-598c-4028-b22a-a86f262bcf1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54c5b304-9bc8-4c3c-ab91-7033fa94829c', 'It is a Scalene triangle only', false, '6270fe82-598c-4028-b22a-a86f262bcf1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c66ebc64-7ce8-4004-9527-d627f016e0da', 'It is a circle', false, '6270fe82-598c-4028-b22a-a86f262bcf1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be504082-48e0-46d5-b401-8aef3c3c289e', 'It is an impossible line', false, '6270fe82-598c-4028-b22a-a86f262bcf1b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32dba2e1-e44f-4684-a633-2e03db328700', 'Class 7', 'Mathematics', 'Chapter 6: The Triangle and its Properties', 'Hard', 'Why is the Triangle considered the most rigid and fundamental structural element in civil engineering, bridge truss design, and geodesic domes?', 'Triangulation provides structural rigidity (SSS uniqueness theorem): pin-jointed triangular frames cannot flex under shear loads.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c2f0842-41f4-4f42-93cd-dff1c4250f40', 'A triangle is geometrically RIGID: once the three side lengths are fixed, its angles are locked and cannot deform without bending or breaking the sides (unlike quadrilaterals)', true, '32dba2e1-e44f-4684-a633-2e03db328700');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c525becd-8515-4ecb-a11c-9720540d6043', 'Because triangles are made of gold', false, '32dba2e1-e44f-4684-a633-2e03db328700');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e69f25ca-57aa-4dd5-ad01-8e40d659a8c9', 'Because triangles have zero weight', false, '32dba2e1-e44f-4684-a633-2e03db328700');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab933cab-1481-4c23-bc87-195445afcfa1', 'Because triangles eliminate gravity', false, '32dba2e1-e44f-4684-a633-2e03db328700');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e46a84ef-7f2d-42f1-9e61-f19f2f80c675', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'In Sharada Dwivedi''s story ''Expert Detectives'' (from ''The Broken Flute''), what is the nickname and real age of the boy Nishad?', 'Nishad is a 7-year-old boy nicknamed ''Seven'' because Nishad is the seventh musical note in the Indian classical octave (Sa-Re-Ga-Ma-Pa-Dha-Ni).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd102535-7854-47d0-8b7b-ad369258cd21', 'Seven (a 7-year-old boy named because his name refers to the 7th musical note ''Ni'')', true, 'e46a84ef-7f2d-42f1-9e61-f19f2f80c675');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5ee1cd6-8933-4fee-aa4d-7b9f328ffbe7', 'Ten (a 10-year-old boy)', false, 'e46a84ef-7f2d-42f1-9e61-f19f2f80c675');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10494b08-b2e1-4f82-bf10-90b67d6054da', 'Five (a 5-year-old boy)', false, 'e46a84ef-7f2d-42f1-9e61-f19f2f80c675');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09ed1729-fc66-4415-aa67-d781d18887fc', 'Miko', false, 'e46a84ef-7f2d-42f1-9e61-f19f2f80c675');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0323729-603e-406b-92bf-db6d325b4dff', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'Who is Nishad''s 10-year-old elder sister who acts as the self-appointed lead detective?', 'Maya is Nishad''s 10-year-old sister who investigates their mysterious neighbor Mr. Nath.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b52038fe-82d9-4215-81ef-b0e6fee1cffd', 'Maya', true, 'c0323729-603e-406b-92bf-db6d325b4dff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d2c75d7-73ee-440b-afd6-9b61bffd9400', 'Rani', false, 'c0323729-603e-406b-92bf-db6d325b4dff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd1e70c5-59e2-40d5-9cc7-15c02339425d', 'Meena', false, 'c0323729-603e-406b-92bf-db6d325b4dff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a935b673-6c20-4e86-90ec-0a9403a6b3a7', 'Shreya', false, 'c0323729-603e-406b-92bf-db6d325b4dff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ad05d7e-c6a8-4dc6-b40d-3dee7e422299', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'Who is the quiet, gaunt, scar-faced tenant in Room No. 10 at Shankar House whom Maya suspects of being a dangerous criminal?', 'Mr. Nath is the recluse tenant living in Room 10 of Shankar House, treated by their mother at her clinic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4459996f-5d85-4adc-b06f-dc273d206e97', 'Mr. Nath', true, '1ad05d7e-c6a8-4dc6-b40d-3dee7e422299');
