INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73af597f-6e07-46b3-ba6e-266e0a609b3b', 'Mr. Mehta', false, '1ad05d7e-c6a8-4dc6-b40d-3dee7e422299');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c84259d3-4b6a-43de-823e-559152959078', 'Ramesh', false, '1ad05d7e-c6a8-4dc6-b40d-3dee7e422299');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31ef4ee3-21a3-4094-bba2-3db88acb265b', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'What profession does Maya and Nishad''s mother practice?', 'Their mother is a physician/doctor who knows Mr. Nath as a quiet, polite patient at her clinic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64790c73-3d3d-4d9d-9ac2-2a4276a99047', 'A Doctor (practicing at her medical clinic)', true, '31ef4ee3-21a3-4094-bba2-3db88acb265b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd5ac4f8-3f69-4baa-87a0-7bcc7446297d', 'A School Teacher', false, '31ef4ee3-21a3-4094-bba2-3db88acb265b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44ba2054-93b8-4552-9a32-7c3ad0e05088', 'A Police Detective', false, '31ef4ee3-21a3-4094-bba2-3db88acb265b');
