INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a1081b7-205d-46c6-afae-6b6631f4892b', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'Who delivers two daily meals and two cups of tea to Mr. Nath''s room from the restaurant downstairs?', 'Ramesh, a worker from the restaurant downstairs, delivers Mr. Nath''s fixed meals (two chapatis, dal, and a vegetable) and tea.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf2d4eb6-67a4-44e2-8896-da1980dfb91f', 'Ramesh', true, '9a1081b7-205d-46c6-afae-6b6631f4892b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03e8e092-8ad4-4243-a31e-073436152bff', 'Suresh', false, '9a1081b7-205d-46c6-afae-6b6631f4892b');
