INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6edb2016-834e-4c05-a015-9223162e4c4b', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'What unusual visitor comes to see Mr. Nath every SUNDAY afternoon at Shankar House?', 'Ramesh informs Nishad that every Sunday, a tall, fair, stout, bespectacled visitor visits Mr. Nath and chats incessantly.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43623940-0515-4734-a156-5cc73dbd1b6f', 'A tall, fair, stout man wearing spectacles who talks a great deal', true, '6edb2016-834e-4c05-a015-9223162e4c4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5391678-04a8-4314-ab59-a867beef8896', 'A police inspector in uniform', false, '6edb2016-834e-4c05-a015-9223162e4c4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac86a476-8ceb-4973-8050-440aa3f06cef', 'A magician with a trunk', false, '6edb2016-834e-4c05-a015-9223162e4c4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8d5179a-9b35-4e4c-b708-72246ac9d3e1', 'A young schoolboy', false, '6edb2016-834e-4c05-a015-9223162e4c4b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99f9d98b-e42b-4682-9f61-78d8e95fc999', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'What sweet treat did Nishad thrust into Mr. Nath''s hand during his unexpected visit to Room 10?', 'Moved by Mr. Nath''s gaunt, starving appearance, Nishad generously thrust a bar of chocolate into his palm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('675518d6-a319-456f-846e-049975129e0c', 'A bar of chocolate', true, '99f9d98b-e42b-4682-9f61-78d8e95fc999');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ea7c0fc-cf95-450a-b1ee-8bf30f320a2e', 'An ice cream cone', false, '99f9d98b-e42b-4682-9f61-78d8e95fc999');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48f113d9-8360-477c-9baa-d770b99f8304', 'A box of laddus', false, '99f9d98b-e42b-4682-9f61-78d8e95fc999');
