INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f66e0ec-6825-41b4-9f57-8e2cf48068c4', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'What does Maya write at the top of her investigative fact sheet in large block letters?', 'Maya wrote the dramatic heading: ''CATCHING A CROOK — Expert Detectives: Nishad and Maya Pandit (By Appointment to the Whole World)''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89cec214-d9f2-46e5-af09-09b2d6bae4b8', '"CATCHING A CROOK — Expert Detectives: Nishad and Maya Pandit (By Appointment to the Whole World)"', true, '8f66e0ec-6825-41b4-9f57-8e2cf48068c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6104c56f-2de0-48a3-b9ac-11e408b9ee75', '"HOW TO BECOME A POLICE OFFICER"', false, '8f66e0ec-6825-41b4-9f57-8e2cf48068c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('473ba43b-771a-4169-8498-cfbbcf248d3f', '"RECIPE FOR CHOCOLATE CAKE"', false, '8f66e0ec-6825-41b4-9f57-8e2cf48068c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('161c6052-9433-4f69-a5f7-ea56ce19e009', '"MY SCHOOL HOMEWORK"', false, '8f66e0ec-6825-41b4-9f57-8e2cf48068c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('05f8fcc0-a64c-4726-82cc-3d40036eb112', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'In Maude Rubin''s poem ''Mystery of the Talking Fan'', what was the ''talking'' or ''chattering'' sound made by the ceiling fan?', 'The fan''s ''talk'' was the dry, un-oiled rhythmic mechanical squeak of its electric motor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbd8fe92-4016-4d5b-ba25-46546038622d', 'An electrical squeak and mechanical whirring sound caused by lack of lubricating oil in its motor', true, '05f8fcc0-a64c-4726-82cc-3d40036eb112');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85bb6972-2406-4403-b9cf-d33075634098', 'Real human words spoken by a ghost', false, '05f8fcc0-a64c-4726-82cc-3d40036eb112');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c86f2a05-76a8-43bc-8f1d-7bf49e172913', 'Music from a radio', false, '05f8fcc0-a64c-4726-82cc-3d40036eb112');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c60e604-0dcc-46fd-bed2-0695d8413875', 'The sound of wind blowing through an open window', false, '05f8fcc0-a64c-4726-82cc-3d40036eb112');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae8dcbbe-b2e0-4d95-a1bf-5cb014ba4848', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'How did the ''mystery'' of the talking fan suddenly come to an end?', 'The poem ends: ''He ran as still as water'' once somebody oiled its whirling motor, solving the mystery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1641f52-579e-4cb9-8d8c-0969b9d68b8b', 'Somebody oiled its little whirling electric motor, and thereafter it ran as still and smooth as water', true, 'ae8dcbbe-b2e0-4d95-a1bf-5cb014ba4848');
