INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e17a31db-6e85-4b7d-9471-b27094ea3a06', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Easy', 'What prefix can be added to the word ''Patient'' to mean ''Unable to wait calmly''?', 'The negative prefix ''im-'' attaches to roots starting with labial consonants (m/p): im + patient = impatient.', NOW()) ON CONFLICT DO NOTHING;
