INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a9340a6-ff11-4827-aca7-6076d3e93534', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Medium', 'Why do Maya and Nishad have opposing viewpoints about Mr. Nath?', 'Maya views Mr. Nath through sensational detective melodrama; Nishad views him through compassionate human empathy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2e5147f-9f54-4d95-8034-c2a6d56082fe', 'Maya believes Mr. Nath is a dangerous fugitive criminal hiding millions in stolen loot ; Nishad empathizes with him as a lonely, impoverished, sick man who needs a friend', true, '7a9340a6-ff11-4827-aca7-6076d3e93534');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7240df04-d546-48ad-bc51-09e9335340e0', 'Maya thinks he is a doctor and Nishad thinks he is a teacher', false, '7a9340a6-ff11-4827-aca7-6076d3e93534');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb5cdfcc-bc91-40f9-9b84-f8cf30dfed59', 'Both think he is a king', false, '7a9340a6-ff11-4827-aca7-6076d3e93534');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edc550c5-1056-4db3-80b2-ce70ef1a6a1d', 'Neither cares about him', false, '7a9340a6-ff11-4827-aca7-6076d3e93534');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('373665e9-dbab-4886-a946-7ee6664df53c', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Medium', 'How does Maya explain the burn scars on Mr. Nath''s face, and what does their mother say about them?', 'Maya melodramatically assumes police shootout wounds; their doctor mother confirms they are medical burn scars.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce5c31b1-7361-4926-b792-5af743d9886a', 'Maya theorizes the police shot or burned him during a shootout ; Mama explains that they are severe burn scars from an accidental fire', true, '373665e9-dbab-4886-a946-7ee6664df53c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a75c303-bb50-4662-be5b-727651522aec', 'Maya says he was born with them', false, '373665e9-dbab-4886-a946-7ee6664df53c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d1bdb62-143d-411a-92d8-8fc96dfc1f72', 'Mama says he got them from an animal bite', false, '373665e9-dbab-4886-a946-7ee6664df53c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11209af2-8281-4878-9873-d24dd9425bf4', 'Maya says he painted them', false, '373665e9-dbab-4886-a946-7ee6664df53c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd9d1a7f-afba-4c29-bd13-a1e9392646e7', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Medium', 'What reason does Maya offer for why Mr. Nath has no friends and never talks to anyone at Shankar House?', 'Maya rationalizes his reclusive isolation as a criminal strategy to evade identification.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fda4f78-181d-44b3-8144-711d2ea0aadd', 'She claims he is terrified that someone might recognize him and inform the police about his criminal identity', true, 'fd9d1a7f-afba-4c29-bd13-a1e9392646e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35d2d8a4-49fb-44d2-9cb0-42a846b9e582', 'Because he does not know any language', false, 'fd9d1a7f-afba-4c29-bd13-a1e9392646e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9593f5f4-638f-4268-af78-203ac9feb57a', 'Because he is deaf', false, 'fd9d1a7f-afba-4c29-bd13-a1e9392646e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dffd91b-1b41-4a2a-913c-3cf6aa355932', 'Because he owns the whole building', false, 'fd9d1a7f-afba-4c29-bd13-a1e9392646e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c304121-bf26-4bba-a940-833258e1a12e', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Medium', 'What conclusion does Nishad reach after visiting Mr. Nath, refusing to support Maya''s criminal accusations?', 'Nishad rebels against Maya''s prejudice, asserting his determination to offer genuine friendship to the isolated man.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b341b75c-04eb-4192-89c6-900a23d6ae7a', 'He declares: "I like him, and I''m going to try and be his friend! How can a lonely, poor man be a bad crook?"', true, '1c304121-bf26-4bba-a940-833258e1a12e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a6cacbe-392d-4b62-bc69-cba7aa546306', 'He agrees to call the police immediately', false, '1c304121-bf26-4bba-a940-833258e1a12e');
