INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('366bc665-4e4d-4d7a-bb88-626a428c4930', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Medium', 'What gives Nishad the golden opportunity to enter Mr. Nath''s room at Shankar House?', 'Nishad''s stray marble rolled under Mr. Nath''s door, granting him direct personal entry.', NOW()) ON CONFLICT DO NOTHING;
