INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b11c1a05-6bec-46e4-a2a5-f40318d7a8d2', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Medium', 'Why did Ramesh describe Mr. Nath as a generous customer despite his simple meals?', 'Ramesh praised Mr. Nath''s quiet nobility: ''He pays cash and tips well''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af7b4912-f97f-4565-ad58-1746faa3a557', 'Mr. Nath paid cash promptly and always gave Ramesh a handsome, generous TIP every single time', true, 'b11c1a05-6bec-46e4-a2a5-f40318d7a8d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec6e2743-263b-4d67-993b-69f81f6c33a8', 'Mr. Nath cooked food for Ramesh', false, 'b11c1a05-6bec-46e4-a2a5-f40318d7a8d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('920a542b-59d3-4437-857e-ccc0cb627326', 'Mr. Nath gave Ramesh golden coins', false, 'b11c1a05-6bec-46e4-a2a5-f40318d7a8d2');
