INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01893293-68e3-46e3-8709-4c3108d009ad', 'Judging others based on physical scars, reclusive habits, or gossip without verified evidence leads to cruel prejudice, whereas genuine kindness and empathy uncover human truth', true, '0158d2b6-31e8-4bbd-aa8d-31cf976c93a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('301ec0bb-a732-4e46-938f-e3fdcead57b2', 'Children should always report their neighbors to the police', false, '0158d2b6-31e8-4bbd-aa8d-31cf976c93a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31ad069f-91fd-4068-8445-0ebc2b04e98c', 'Detectives should never listen to doctors', false, '0158d2b6-31e8-4bbd-aa8d-31cf976c93a2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f24338d8-b4f2-4af1-8b25-4045223ac59b', 'People with scars are always dangerous', false, '0158d2b6-31e8-4bbd-aa8d-31cf976c93a2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ed6b3a0-9ab1-46ac-8588-bf4d18ef2c36', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Hard', 'Match Column I (Characters in Expert Detectives) with Column II (Dominant Behavioral Traits):
(a) Maya       -> (i) Imaginative, assertive, obsessed with sensational detective tropes
(b) Nishad     -> (ii) Intuitive, sensitive, compassionate, prioritizing human connection
(c) Mr. Nath   -> (iii) Reclusive, convalescing patient bearing physical and emotional scars
(d) Ramesh     -> (iv) Observant, pragmatic restaurant worker who values prompt payment and tips', 'Accurate characterization: Maya (sensationalist); Nishad (empathetic); Mr. Nath (reclusive patient); Ramesh (pragmatic worker).', NOW()) ON CONFLICT DO NOTHING;
