INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74b29aa1-2d8b-4165-83f6-bf936355a635', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Hard', 'Why does Nishad storm out of the room at the end of the chapter with his arms folded stubbornly?', 'Nishad takes an ethical stand against Maya''s groundless accusations, choosing personal integrity over sibling complicity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a8645a3-2970-4612-b15f-59cae7dacbe0', 'Because he refuses to participate in Maya''s unkind, unverified witch-hunt against Mr. Nath and intends to follow his conscience to befriend him', true, '74b29aa1-2d8b-4165-83f6-bf936355a635');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5db89c07-a30e-4fb5-a7dd-a2a5f9b80974', 'Because he lost his chocolate bar', false, '74b29aa1-2d8b-4165-83f6-bf936355a635');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87e13f49-6138-4440-9de6-0fb39f12612f', 'Because Maya tore his notebook', false, '74b29aa1-2d8b-4165-83f6-bf936355a635');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1719d065-7500-42da-86ae-09a0b8a1d3e4', 'Because it started raining heavily', false, '74b29aa1-2d8b-4165-83f6-bf936355a635');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e2bb72e6-4441-4eba-99c6-15af72959e3c', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Hard', 'What is the metaphorical significance of the ceiling fan in Maude Rubin''s poem?', 'Rubin illustrates the poetic transformation of mundane mechanical friction into an imaginative narrative, effortlessly resolved by rational care.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae43e844-585f-4fbf-9708-6a04b27b55b0', 'It represents how everyday mundane objects can spark childlike wonder and imagination, until simple scientific logic demystifies the phenomenon', true, 'e2bb72e6-4441-4eba-99c6-15af72959e3c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7976e194-2dda-4fba-a6cd-82c32d7a316d', 'It symbolizes a spaceship', false, 'e2bb72e6-4441-4eba-99c6-15af72959e3c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a47ea0ba-90c9-4b40-9f0b-73acaf1c894c', 'It represents an evil monster', false, 'e2bb72e6-4441-4eba-99c6-15af72959e3c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1145eddd-b1fb-4139-b9d6-43abbcc95911', 'It shows that electricity is dangerous', false, 'e2bb72e6-4441-4eba-99c6-15af72959e3c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b423ecd-ccf1-455b-8059-8a1fdbeae19e', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Hard', 'What does the narrator mean by ''Electrical his chatter'' in the poem?', '''Electrical his chatter'' poeticizes the humming acoustic vibration created by the alternating electric current in the dry motor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf1e512c-5db1-42e6-9f74-8577bb9cf43b', 'The noise of the fan was produced by electrical currents driving the friction in the unlubricated motor', true, '3b423ecd-ccf1-455b-8059-8a1fdbeae19e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f021ee68-9265-4ad4-87e8-f6b378465c53', 'The fan was connected to a telephone', false, '3b423ecd-ccf1-455b-8059-8a1fdbeae19e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29a107da-94ce-42e1-bcbb-b5ad5aa0684b', 'The fan was speaking about batteries', false, '3b423ecd-ccf1-455b-8059-8a1fdbeae19e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6c3637c-39a5-4ec4-97d1-058ded673516', 'The fan gave people electric shocks', false, '3b423ecd-ccf1-455b-8059-8a1fdbeae19e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('edc82bec-765c-4a6e-bb26-29e90dad502d', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Hard', 'Which of the following lines from ''Mystery of the Talking Fan'' contains an acoustic auditory image?', '''Electrical his chatter'' and ''couldn''t quite hear'' appeal directly to auditory sensory imagery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('043f9c3f-ad76-4bcf-881a-c508a5f11960', '"Electrical his chatter / I couldn''t quite hear what he said"', true, 'edc82bec-765c-4a6e-bb26-29e90dad502d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da00477d-0613-456c-93f0-274e9e4fd269', '"He ran as still as water"', false, 'edc82bec-765c-4a6e-bb26-29e90dad502d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b989450-998a-49e5-9cd8-830284e78229', '"Somebody oiled his little whirling motor"', false, 'edc82bec-765c-4a6e-bb26-29e90dad502d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39a9207d-3081-4ac7-87d3-61185aef91ee', '"All the mystery was spoiled"', false, 'edc82bec-765c-4a6e-bb26-29e90dad502d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5b474df4-a3d8-4bf5-9bc8-3cd1f7b77f65', 'Class 7', 'English', 'Chapter 6: Expert Detectives & Mystery of the Talking Fan', 'Hard', 'What overarching moral theme unites Chapter 6 of NCERT Class 7 English?', 'Chapter 6 celebrates critical thinking, the rejection of hasty prejudice, and the supremacy of empathetic human understanding.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61c6d9a9-f2cf-491c-8035-9255db814619', 'The necessity of looking beyond surface appearances—whether investigating human character with empathy and truth rather than sensational bias, or demystifying mechanical curiosities through rational understanding', true, '5b474df4-a3d8-4bf5-9bc8-3cd1f7b77f65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34912f86-da57-4a25-a838-37e03acd1a25', 'That children should never play with marbles', false, '5b474df4-a3d8-4bf5-9bc8-3cd1f7b77f65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37ec8b58-af3f-4253-bcb9-f8d1442db9eb', 'That fans should be removed from houses', false, '5b474df4-a3d8-4bf5-9bc8-3cd1f7b77f65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('307193ce-9072-4488-8b09-2b50aec31616', 'That doctors should never treat patients', false, '5b474df4-a3d8-4bf5-9bc8-3cd1f7b77f65');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6cc905cb-e6ad-48b2-8b5e-84da788c0946', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'In which year was the United Nations (UN) founded to maintain international peace and security following the devastation of World War II?', 'The UN Charter was signed on 26 June 1945 and entered into force on 24 October 1945 (celebrated globally as United Nations Day).', NOW()) ON CONFLICT DO NOTHING;
