INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('679d8ac9-50c7-4cbd-b5ba-89606fbed2c3', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'How many permanent members (P5) with VETO POWER are there in the United Nations Security Council (UNSC)?', 'The UNSC has 5 permanent members (US, UK, France, Russia, China) with veto power, alongside 10 non-permanent members elected for 2-year terms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4ce7dbc-d00e-45b1-8f7f-eb6103368cfe', '5 Permanent Members (United States, United Kingdom, France, Russia, and China)', true, '679d8ac9-50c7-4cbd-b5ba-89606fbed2c3');
