INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d144265-d36b-4cbc-b5c4-7b36afd6f44b', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'Where is the International Court of Justice (ICJ) — the principal judicial organ of the UN — located?', 'The ICJ sits at the Peace Palace in The Hague, Netherlands; it is the only principal UN organ not located in New York.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6ecc423-d721-44d5-9258-9649aeec2978', 'The Hague, Netherlands (Peace Palace)', true, '7d144265-d36b-4cbc-b5c4-7b36afd6f44b');
