INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b65f54bf-1262-4557-a81a-d56acd6f8631', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'Which specialized UN agency is responsible for international public health, disease eradication, and pandemic response, headquartered in Geneva?', 'The WHO (founded 7 April 1948, celebrated as World Health Day) directs global health guidelines and disease surveillance from Geneva.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35963f64-1737-4f09-8691-2a1787ba99f5', 'World Health Organization (WHO)', true, 'b65f54bf-1262-4557-a81a-d56acd6f8631');
