INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b513ea7-c113-48ff-8771-46c3a06d0025', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'Which UN agency is dedicated to protecting children''s rights, healthcare, nutrition, and education worldwide, headquartered in New York?', 'UNICEF provides humanitarian and developmental aid to children in over 190 countries and territories.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d61ed043-6be2-499f-983a-301fa0a2f616', 'UNICEF (United Nations Children''s Fund)', true, '8b513ea7-c113-48ff-8771-46c3a06d0025');
