INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca433e53-a003-40b8-a1b1-b398a183e94c', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'Which UN agency promotes international peace through education, the sciences, culture, and World Heritage Sites, headquartered in Paris, France?', 'UNESCO (United Nations Educational, Scientific and Cultural Organization) oversees cultural preservation, literacy, and World Heritage classifications.', NOW()) ON CONFLICT DO NOTHING;
