INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d81efda3-ef43-4348-bc41-19b8e83409cb', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'Which global financial institutions (the Bretton Woods twins) provide loans and financial stability to member nations, headquartered in Washington, D.C.?', 'The World Bank (reconstruction & development) and IMF (monetary stability & balance of payments) were founded at Bretton Woods in 1944.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8ebe8fd-10c5-415e-ba47-124c48fecf9c', 'The World Bank and the International Monetary Fund (IMF)', true, 'd81efda3-ef43-4348-bc41-19b8e83409cb');
