INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a32f19d7-8cba-47a7-aa40-ae49319559d4', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'Which international organization regulates global international trade rules between nations, headquartered in Geneva, Switzerland?', 'The WTO (established 1 January 1995 succeeding GATT) establishes multilateral trade agreements and arbitrates trade disputes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae681d48-a0d9-4fd4-9d15-6a6d0c99fb62', 'World Trade Organization (WTO)', true, 'a32f19d7-8cba-47a7-aa40-ae49319559d4');
