INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3b10194-90b4-48c3-b891-eb86cd92046b', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'What was the theme of the historic G20 Summit hosted by India in New Delhi in September 2023 under its presidency?', 'India''s G20 presidency theme was ''Vasudhaiva Kutumbakam'' (One Earth · One Family · One Future), drawn from the ancient Maha Upanishad.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69a8acab-d026-437c-a971-1b3ce0319d9e', '"Vasudhaiva Kutumbakam" — ''One Earth, One Family, One Future''', true, 'f3b10194-90b4-48c3-b891-eb86cd92046b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c7bb153-ec37-4d17-a9cb-dd78abeee4f0', '"Peace through Strength"', false, 'f3b10194-90b4-48c3-b891-eb86cd92046b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3843e05-6976-4401-8419-4a6eeec7576a', '"Trade without Borders"', false, 'f3b10194-90b4-48c3-b891-eb86cd92046b');
