INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45b78ea1-6272-477d-9914-183ba2557c09', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'What does the geopolitical grouping acronym ''BRICS'' stand for?', 'BRICS brings together major emerging economies: Brazil, Russia, India, China, and South Africa (expanded with new member nations in 2024).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46b0abb1-db95-4bd7-9946-d617b5733d8e', 'Brazil, Russia, India, China, and South Africa', true, '45b78ea1-6272-477d-9914-183ba2557c09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12864905-139e-4c58-a73a-dc0192d17561', 'Britain, Russia, Italy, Canada, and Spain', false, '45b78ea1-6272-477d-9914-183ba2557c09');
