INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f26b89b-d734-42d1-9231-58eaa19b64b9', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Easy', 'What is the primary objective of the historic 2015 ''Paris Climate Agreement'' (COP21)?', 'The legally binding Paris Agreement commits 196 parties to hold anthropogenic global temperature rise well below 2.0°C and strive for 1.5°C.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b0eacf9-f8aa-4e8e-aa6b-4fe43479d506', 'To limit global warming to well below 2°C (preferably to 1.5°C) above pre-industrial levels', true, '7f26b89b-d734-42d1-9231-58eaa19b64b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3a2b20c-fe0c-4fd9-a036-c929a4eccef1', 'To ban all cars worldwide', false, '7f26b89b-d734-42d1-9231-58eaa19b64b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c22e23c8-221f-4924-8259-a9ad645b6544', 'To build a wall around Antarctica', false, '7f26b89b-d734-42d1-9231-58eaa19b64b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bf6b34c-875c-447e-a643-f2dc82ea9823', 'To stop using electricity', false, '7f26b89b-d734-42d1-9231-58eaa19b64b9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5965c627-1715-46b0-ab2f-5afe44ee89b7', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What is the ''General Assembly'' (UNGA) of the United Nations often referred to in international relations?', 'The UNGA is the principal deliberative organ where all 193 sovereign member states participate on sovereign equality principles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc428c7c-9e2c-4a4f-98d9-bfd8413e9472', 'The ''Town Hall of the World'' (where all 193 member states have equal representation and 1 vote each)', true, '5965c627-1715-46b0-ab2f-5afe44ee89b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a9249b8-210e-4a42-8b15-459e582f201e', 'The World Court', false, '5965c627-1715-46b0-ab2f-5afe44ee89b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed5d431f-39f7-48e2-a470-f8ca1357a04c', 'The Military Command of Earth', false, '5965c627-1715-46b0-ab2f-5afe44ee89b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('651ffb66-e344-40b3-9e60-981d63b0b5f3', 'The Global Police Station', false, '5965c627-1715-46b0-ab2f-5afe44ee89b7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9dd1a3f8-81bf-4b5b-8dd1-dda4ff11847e', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'Which regional intergovernmental organization comprises 10 Southeast Asian nations (e.g. Indonesia, Singapore, Malaysia, Thailand, Vietnam)?', 'ASEAN (founded 1967 in Bangkok) fosters regional economic integration, security, and cultural collaboration across 10 Southeast Asian states.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81fb7055-a8c7-43a3-bc71-0fbb2a9a5e0a', 'ASEAN (Association of Southeast Asian Nations)', true, '9dd1a3f8-81bf-4b5b-8dd1-dda4ff11847e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20c024f6-407f-423d-bef6-03a2b53accb4', 'SAARC', false, '9dd1a3f8-81bf-4b5b-8dd1-dda4ff11847e');
