INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4e7266e-caa0-4acd-9b27-a5f50841f907', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What is the ''QUAD'' (Quadrilateral Security Dialogue) diplomatic partnership between four major democratic nations in the Indo-Pacific?', 'The QUAD comprises India, the US, Japan, and Australia, advancing a free, open, and resilient Indo-Pacific maritime order.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b58f4bfc-9251-42ab-9898-52002c360d3e', 'India, the United States, Japan, and Australia', true, 'c4e7266e-caa0-4acd-9b27-a5f50841f907');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ae737cc-6408-4a79-a817-b73af8e4fbb7', 'India, China, Russia, and Brazil', false, 'c4e7266e-caa0-4acd-9b27-a5f50841f907');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2f1975f-d9c1-451c-be9f-ab3a0abbabf2', 'US, UK, France, and Germany', false, 'c4e7266e-caa0-4acd-9b27-a5f50841f907');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b3191c2-7047-4851-b966-ac2aeb7f5b91', 'Japan, South Korea, Taiwan, and Singapore', false, 'c4e7266e-caa0-4acd-9b27-a5f50841f907');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7d6e856-64af-4105-a505-15d94afa18b5', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'Which international organization of 12 petroleum-exporting nations coordinates petroleum policies to stabilize international oil markets, headquartered in Vienna?', 'OPEC (headquartered in Vienna, Austria) coordinates crude oil production quotas among member states to regulate global petroleum pricing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35e173b9-4662-4e5d-af52-88cb618b0f06', 'OPEC (Organization of the Petroleum Exporting Countries)', true, 'b7d6e856-64af-4105-a505-15d94afa18b5');
