INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77b611ee-4991-46c3-b3fe-fdf7d9746735', 'OECD', false, 'b7d6e856-64af-4105-a505-15d94afa18b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('040dda4f-4d50-42a9-a28a-13d07d66d974', 'APEC', false, 'b7d6e856-64af-4105-a505-15d94afa18b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a596c0f-fbb8-498b-b8d8-b91ce5e1ff17', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What are the ''Geneva Conventions'' in international humanitarian law?', 'The 1949 Geneva Conventions codify the core tenets of international humanitarian law (jus in bello), protecting non-combatants and war victims.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e24a91f-0b9e-4525-bf27-89af982127e4', 'Four landmark international treaties that establish the legal standards for humanitarian treatment of wounded soldiers, prisoners of war (POWs), and civilians during armed conflicts', true, '1a596c0f-fbb8-498b-b8d8-b91ce5e1ff17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b5e9a25-90bd-4508-a810-3ff34c188c2d', 'A treaty regulating air travel tickets', false, '1a596c0f-fbb8-498b-b8d8-b91ce5e1ff17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4952cf0-df09-486d-bcd0-70938001add5', 'An agreement on international banking passwords', false, '1a596c0f-fbb8-498b-b8d8-b91ce5e1ff17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4752a08-1fe3-41ad-ba82-900bcd7f6795', 'A trade deal on Swiss chocolates', false, '1a596c0f-fbb8-498b-b8d8-b91ce5e1ff17');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9ea417b5-8ab7-409d-ba22-db3bd4dab4c1', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What is the ''International Atomic Energy Agency'' (IAEA), headquartered in Vienna, Austria?', 'The IAEA (established 1957) monitors nuclear safeguards, promotes civilian nuclear technology, and verifies non-proliferation treaties.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('965337bb-02f5-4757-89f4-d4bd992a4af1', 'The ''Atoms for Peace'' world organization that promotes peaceful uses of nuclear energy and conducts inspections to prevent nuclear weapon proliferation', true, '9ea417b5-8ab7-409d-ba22-db3bd4dab4c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c914680-6e0b-4c32-9a5d-2be2acf73bc2', 'A company that builds nuclear weapons', false, '9ea417b5-8ab7-409d-ba22-db3bd4dab4c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bc590b9-f690-4121-855f-fb139bf93bc9', 'A committee that sells electricity', false, '9ea417b5-8ab7-409d-ba22-db3bd4dab4c1');
