INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be4b1a4d-23bb-42a5-bbc8-09fed7e996ab', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'Where is the Secretariat of SAARC (South Asian Association for Regional Cooperation) located?', 'The SAARC Secretariat was established in Kathmandu, Nepal in 1987 to facilitate regional dialogue across 8 South Asian member states.', NOW()) ON CONFLICT DO NOTHING;
