INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93c06d19-575f-4554-bb40-cfe95ba15969', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What is the ''Universal Declaration of Human Rights'' (UDHR) adopted by the UN General Assembly on 10 December 1948?', 'Adopted under the leadership of Eleanor Roosevelt on 10 Dec 1948 in Paris, the UDHR articulates inalienable human dignities and fundamental liberties.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b014335-79fe-41cd-8a33-c809adfada5f', 'A milestone milestone proclamation setting out 30 fundamental human rights to be universally protected for all human beings everywhere (celebrated as Human Rights Day)', true, '93c06d19-575f-4554-bb40-cfe95ba15969');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28e16e45-e4ab-4d45-b9dd-f21812e38be5', 'A constitution for the United States', false, '93c06d19-575f-4554-bb40-cfe95ba15969');
