INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b2990a7-01c6-4ca0-8593-1ec849b5b35f', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'Which global environmental treaty signed in 1987 successfully phased out ozone-depleting substances (Chlorofluorocarbons / CFCs)?', 'The 1987 Montreal Protocol is celebrated as the most universally ratified and successful multilateral environmental treaty, healing the stratospheric ozone layer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3513f97b-2c71-446e-a381-95604a9d88a0', 'The Montreal Protocol', true, '2b2990a7-01c6-4ca0-8593-1ec849b5b35f');
