INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e21a1658-e408-4145-9e8d-1196d716b565', 'The Paris Agreement', false, '2b2990a7-01c6-4ca0-8593-1ec849b5b35f');
