INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f6f902c7-b589-4ff9-876c-6ce47c5c168b', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What is ''INTERPOL'' (International Criminal Police Organization), headquartered in Lyon, France?', 'Interpol enables law enforcement agencies worldwide to share biometric databases, track transnational criminals, and issue Red Notices.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fe5480b-eb14-4213-8ef9-6bd7ab6536a9', 'The world''s largest international police organization that facilitates cross-border police cooperation and crime control across 196 member countries', true, 'f6f902c7-b589-4ff9-876c-6ce47c5c168b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bbe3a6d-0d50-419e-b3ad-8a2a6ea35a7b', 'A global court that sentences kings', false, 'f6f902c7-b589-4ff9-876c-6ce47c5c168b');
