INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7cfbeaa6-2f1f-438d-b59d-9de04cd1f5eb', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'Which specialized UN agency leads international efforts to defeat hunger, improve agricultural nutrition, and food security, headquartered in Rome, Italy?', 'The FAO (founded 16 October 1945, World Food Day) coordinates global agrarian development and famine mitigation from Rome.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04dbc38a-1ff8-4409-931b-337e98f249a9', 'Food and Agriculture Organization (FAO)', true, '7cfbeaa6-2f1f-438d-b59d-9de04cd1f5eb');
