INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bffe3105-30b9-4dd6-86b3-d5832414ea7d', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What is the ''European Union'' (EU)?', 'The EU represents a unique economic and political bloc established by the Maastricht Treaty (1993), governing a single market and freedom of movement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ec1048f-9622-4adb-9d12-b99d804189fa', 'A supranational political and economic union of 27 European member states with a single market, common policies, and a shared currency (the Euro in the Eurozone)', true, 'bffe3105-30b9-4dd6-86b3-d5832414ea7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('302847a1-f0cc-4056-bb18-6b8bdeaac582', 'A military alliance of 5 countries', false, 'bffe3105-30b9-4dd6-86b3-d5832414ea7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eacfa3a9-8920-4148-9def-4f44ffbc4fbf', 'A football league only', false, 'bffe3105-30b9-4dd6-86b3-d5832414ea7d');
