INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('83ca1e14-94df-475c-af2c-b7f6e77f625b', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What is ''NATO'' (North Atlantic Treaty Organization)?', 'NATO was established by the 1949 Washington Treaty, anchored on collective defense solidarity among transatlantic allies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f29efb94-0a4e-4e6b-ab87-ec6ddb27428b', 'A collective defense military alliance between 32 North American and European countries governed by Article 5 (an armed attack against one is an attack against all)', true, '83ca1e14-94df-475c-af2c-b7f6e77f625b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87c150fd-c2cb-4a5e-8377-d01009f62785', 'A global trade network for cars', false, '83ca1e14-94df-475c-af2c-b7f6e77f625b');
