INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8456504-f56a-49b3-a01b-d2af45fe4eed', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What are the 17 global goals adopted by all UN Member States in 2015 as a universal call to action to end poverty, protect the planet, and ensure peace by 2030 called?', 'The UN 2030 Agenda encompasses 17 Sustainable Development Goals (SDGs) tackling poverty, inequality, climate action, clean energy, and education.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a134767-ddd9-4750-989b-fdab46e13731', 'Sustainable Development Goals (SDGs / 2030 Agenda)', true, 'c8456504-f56a-49b3-a01b-d2af45fe4eed');
