INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e477b26d-d6f2-4b12-a8f5-92c62a0b37fa', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'Which Indian diplomat served as the FIRST woman President of the United Nations General Assembly in 1953?', 'Vijaya Lakshmi Pandit was elected as the 8th President of the UN General Assembly in 1953, the first female diplomat to hold this supreme post.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd8f9135-ec8e-4672-86a8-77df9ac86a96', 'Vijaya Lakshmi Pandit', true, 'e477b26d-d6f2-4b12-a8f5-92c62a0b37fa');
