INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47be6734-63d0-4409-8950-f958d5b3cd92', 'Indira Gandhi', false, 'e477b26d-d6f2-4b12-a8f5-92c62a0b37fa');
