INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d9a71004-0efd-4795-8a57-556b266bd489', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Medium', 'What is the ''International Red Cross and Red Crescent Movement'', awarded three Nobel Peace Prizes, dedicated to?', 'Founded by Henry Dunant in 1863, the ICRC delivers frontline medical relief under strict humanitarian neutrality.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9350c49e-6834-4c1a-a509-4941cff499ad', 'Providing neutral, impartial humanitarian protection and medical assistance to victims of armed conflicts and natural disasters worldwide', true, 'd9a71004-0efd-4795-8a57-556b266bd489');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6df66d9-ef7d-4cc1-a95d-c14265463f9a', 'Building commercial hospitals for profit', false, 'd9a71004-0efd-4795-8a57-556b266bd489');
