INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be4819e7-3273-4e6e-94ce-2f8f0144a100', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba1915e9-6244-4a70-928c-da9cad261de6', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'be4819e7-3273-4e6e-94ce-2f8f0144a100');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7698374-3887-4d32-87dd-eb2ac941c58d', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'be4819e7-3273-4e6e-94ce-2f8f0144a100');
