INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d66a345a-a226-451b-8075-ec2671a80fc1', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'What historic achievement was realized at the New Delhi G20 Summit in September 2023 under India''s leadership regarding multilateral representation?', 'India championed the formal inclusion of the 55-nation African Union as a permanent member, transforming G20 into a truly representative global forum.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6f41463-5161-466d-a57e-f4d1538b25c4', 'The induction of the AFRICAN UNION (comprising 55 African nations) as a permanent full member of the G20, amplifying Global South representation', true, 'd66a345a-a226-451b-8075-ec2671a80fc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9b13c8a-f8b0-4250-a7f8-b6adc5120ab9', 'The dissolution of the United Nations', false, 'd66a345a-a226-451b-8075-ec2671a80fc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('889618ef-635a-4a9c-9a2f-b70fdbd0dd35', 'The creation of a single global currency', false, 'd66a345a-a226-451b-8075-ec2671a80fc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad30d360-07b0-463a-816a-6c2103433a11', 'The banning of all sea trade', false, 'd66a345a-a226-451b-8075-ec2671a80fc1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5ece2784-b04e-4f88-ac05-60338ea53717', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'Match Column I (UN Specialized Organs / Agencies) with Column II (Mandates / Responsibilities):
(a) UNHCR -> (i) Protection and humanitarian assistance for refugees and displaced persons
(b) UNEP  -> (ii) Environmental agenda, climate governance, and biodiversity conservation
(c) ILO   -> (iii) Setting international labor standards, worker rights, and social justice
(d) WIPO  -> (iv) Protection and promotion of Intellectual Property (patents, copyrights)', 'UNHCR = Refugees; UNEP = Environment; ILO = Labor standards; WIPO = Intellectual property rights.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('845a8f8d-d4a3-476b-b8d1-211cfdb9ea47', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '5ece2784-b04e-4f88-ac05-60338ea53717');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b767ee1-bde8-4438-bea3-31ffde7d7604', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '5ece2784-b04e-4f88-ac05-60338ea53717');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('928619ab-31f7-43cf-95b3-898650dc65d5', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '5ece2784-b04e-4f88-ac05-60338ea53717');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cef2003c-7042-4874-9980-c4f443d1d59e', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '5ece2784-b04e-4f88-ac05-60338ea53717');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('15cff421-444a-4d7d-8bab-d653ae834482', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'Read the statements regarding the Non-Aligned Movement (NAM):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4a843b7-2d88-4054-8662-2c37a2579241', 'Statements 1 and 2 only', true, '15cff421-444a-4d7d-8bab-d653ae834482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f98db333-6a63-49ca-9a7d-99b47acf749a', 'Statements 2 and 3 only', false, '15cff421-444a-4d7d-8bab-d653ae834482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d4d6e42-95cb-4f10-9f31-5d3a35af5651', 'Statements 1 and 3 only', false, '15cff421-444a-4d7d-8bab-d653ae834482');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c17a3c4-cd7f-45e1-ae1c-8ab22501a068', 'All Statements 1, 2, and 3', false, '15cff421-444a-4d7d-8bab-d653ae834482');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d715f5ab-d3fa-47ac-92d7-b64895ed8863', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'What is the ''International Criminal Court'' (ICC) established by the 1998 Rome Statute?', 'The ICC (based in The Hague) exercises jurisdiction over individuals for core atrocity crimes under the principle of complementarity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('630954c6-76ab-4d43-826d-7a68b8c59bfc', 'A permanent independent judicial institution that prosecutes individuals accused of the gravest international crimes: Genocide, Crimes Against Humanity, War Crimes, and the Crime of Aggression', true, 'd715f5ab-d3fa-47ac-92d7-b64895ed8863');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34b41c09-6f55-4d63-837b-c775a54681fc', 'A court for traffic violations between countries', false, 'd715f5ab-d3fa-47ac-92d7-b64895ed8863');
