INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46587b1f-8de6-4e30-b713-5bcee3fc3f4a', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'What is the ''Common But Differentiated Responsibilities'' (CBDR) principle in international environmental treaties (UNFCCC)?', 'CBDR recognizes historical emission asymmetries, establishing that developed economies must lead emissions reductions and fund adaptation in the developing world.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('375f2c1f-d6d3-44ed-b6fa-44556f926fb8', 'All countries must address climate change, but developed nations that historically emitted the vast majority of greenhouse gases must take greater mitigation responsibility and provide climate finance to developing nations', true, '46587b1f-8de6-4e30-b713-5bcee3fc3f4a');
