INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4cd82142-cde1-433c-bb4a-e30d88424d6f', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'What is the ''Shanghai Cooperation Organisation'' (SCO)?', 'The SCO (founded 2001, headquartered in Beijing) coordinates Eurasian regional security (RATS), counter-terrorism, and trade integration.', NOW()) ON CONFLICT DO NOTHING;
