INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc99a5c7-7228-4996-a573-6f16aae2a2fa', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'What is ''UN Peacekeeping'' and what iconic gear distinguishes UN peacekeeping troops worldwide?', 'UN ''Blue Helmets'' maintain ceasefire monitoring and civilian protection (with India historically being among the largest troop-contributing nations).', NOW()) ON CONFLICT DO NOTHING;
