INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('004ee36d-51bb-4681-80f2-9823bbddc25b', 'Class 7', 'GK', 'Chapter 6: World Organizations, Treaties, Summits & Global Governance', 'Hard', 'What core vision for global humanity is embodied in Chapter 6 of General Knowledge?', 'Chapter 6 synthesizes global governance architecture, multilateral treaty frameworks, and the collective imperative for international cooperation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c58fc9a-6cff-49ce-8dc9-93c429d51caf', 'Multilateral diplomacy, international law, and global cooperation are essential instruments to resolve armed conflicts, eliminate poverty and disease, combat climate change, and build an inclusive, peaceful global community', true, '004ee36d-51bb-4681-80f2-9823bbddc25b');
