INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91e5ed46-8783-48a5-9ff1-84ec0493f218', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Easy', 'What historic capital city of the Cholas was a premier administrative center, temple town, and thriving hub of craftspersons on the Kaveri river delta?', 'Thanjavur was the majestic Chola capital, home to the Brihadisvara Temple, royal palaces, silk weavers, and bronze sculptors.', NOW()) ON CONFLICT DO NOTHING;
