INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1d1f7fe-6461-4e80-b683-13c8d541b1b5', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Easy', 'Which city in Rajasthan grew as a premier pilgrimage center around the Dargah of the revered 12th-century Sufi saint Khwaja Muinuddin Chishti and the sacred Pushkar lake?', 'Ajmer was a Chauhan capital and celebrated religious pilgrimage center housing the Chishti Dargah and ancient Pushkar lake.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4f787f4-e462-479a-b65e-76261b89460a', 'Ajmer', true, 'f1d1f7fe-6461-4e80-b683-13c8d541b1b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07e7159f-18f9-4300-bf7c-c144542372f0', 'Jaipur', false, 'f1d1f7fe-6461-4e80-b683-13c8d541b1b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cdad8cf-0041-449f-9349-92389837843d', 'Jodhpur', false, 'f1d1f7fe-6461-4e80-b683-13c8d541b1b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60c2578a-fa57-423c-b00a-1394fa5d9a30', 'Udaipur', false, 'f1d1f7fe-6461-4e80-b683-13c8d541b1b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a4fe72fe-8589-403b-b6ea-041dd895cebf', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Easy', 'What prominent weaver communities of South India, such as the Saliyar and Kaikkolar, grew wealthy by donating large sums to monumental temple complexes?', 'The Saliyar and Kaikkolar textile weavers accumulated substantial wealth supplying temple flags, festival cloth, and royal garments.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba2e9758-9870-4a3c-b51e-a3f13f9bbeb9', 'Saliyar and Kaikkolar Weavers', true, 'a4fe72fe-8589-403b-b6ea-041dd895cebf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afccf644-50a6-4460-a504-1a4c24a34ed0', 'Banjaras', false, 'a4fe72fe-8589-403b-b6ea-041dd895cebf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d22ced2-5cb9-40e9-a159-10ac70e8b86e', 'Lohar blacksmiths', false, 'a4fe72fe-8589-403b-b6ea-041dd895cebf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e02d476e-9d1c-40e4-9e73-eeea36da83a2', 'Badhai carpenters', false, 'a4fe72fe-8589-403b-b6ea-041dd895cebf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30cd51e8-24fa-4ace-885a-9d43d39a26bd', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'Why was Thanjavur considered a classic multifunctional town in medieval South India?', 'Thanjavur exemplified urban multifunctionality: combining administrative governance, temple-centered urbanization, and vibrant craft guilds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e176985e-c4d8-460b-9a70-6e1b02a514d7', 'It simultaneously performed three vital urban roles: an Administrative capital with royal courts, a sacred Temple Town with bustling pilgrim festivals, and a commercial Craft Center for bronze casting and silk weaving', true, '30cd51e8-24fa-4ace-885a-9d43d39a26bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9099f588-777e-4304-9bc2-eeffd3c7b1f5', 'Because it had no temples', false, '30cd51e8-24fa-4ace-885a-9d43d39a26bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41a6a2f2-a08f-4094-ae84-c98121430447', 'Because only farmers lived there', false, '30cd51e8-24fa-4ace-885a-9d43d39a26bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5218d43d-dc04-4441-8812-798e3a1d0342', 'Because it was an underground town', false, '30cd51e8-24fa-4ace-885a-9d43d39a26bd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f7c340d2-5465-4147-b61c-21242f6bd8b8', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'How did Temple Towns (like Kanchipuram, Madurai, Tirupati, and Somnath) drive intense economic urbanization in medieval India?', 'Temple urbanization: temple endowments generated agrarian surpluses, financed credit networks, and fostered dense markets around sacred precincts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb796f80-ab26-4bf9-8cc4-ea6e2e157daf', 'Temples were endowed with massive royal land grants and gold; temple authorities invested their wealth in banking and trade, attracting large populations of priests, artisans, dancers, merchants, and pilgrims to settle permanently', true, 'f7c340d2-5465-4147-b61c-21242f6bd8b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a084d46-dd09-420f-8871-bf43e8cc2b63', 'Temples forced all citizens to become soldiers', false, 'f7c340d2-5465-4147-b61c-21242f6bd8b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f163c7b9-7e58-413b-9d7d-4ef2b17e2b68', 'Temples banned all buying and selling', false, 'f7c340d2-5465-4147-b61c-21242f6bd8b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4231c5f9-4990-428f-845d-91402ed9e715', 'Temples were closed to the public', false, 'f7c340d2-5465-4147-b61c-21242f6bd8b8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f2b9ce5f-0aff-4203-bc41-b4c0d32cfc7d', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'How were the colossal stone fortifications of Hampi built without using any mortar or cementing material?', 'Domingo Paes and archaeological records show Hampi''s walls used precision interlocking dry-stone masonry without mortar.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76b3044b-4f27-4b8b-b7c0-d58607dfe317', 'The massive granite stone blocks were shaped with interlocking wedges and grooves, fitting tightly together like jigsaw puzzle pieces using pure dry masonry', true, 'f2b9ce5f-0aff-4203-bc41-b4c0d32cfc7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a4e7680-c12b-45cb-bd3e-d374e3647d8b', 'They were glued with clay', false, 'f2b9ce5f-0aff-4203-bc41-b4c0d32cfc7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98f155b2-c4c4-4bd4-90ec-53391bfaff61', 'They were melted together with fire', false, 'f2b9ce5f-0aff-4203-bc41-b4c0d32cfc7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ac2dee3-1203-4186-9e0e-5100b75bb1d9', 'They were tied with ropes', false, 'f2b9ce5f-0aff-4203-bc41-b4c0d32cfc7d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02c2bfa7-c553-42ca-a4fe-80dbf94720e6', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'What magnificent multi-pillared musical pavilion and chariot shrine in Hampi is dedicated to Lord Vishnu?', 'The Vittala temple in Hampi features the iconic monolithic Stone Chariot and pillared halls designed to resonate like musical instruments.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55570e6b-5705-4ff6-b3c0-342335bf17aa', 'The Vittala Temple (with its famous Stone Chariot and musical pillars)', true, '02c2bfa7-c553-42ca-a4fe-80dbf94720e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98a89cb0-5505-46c9-be06-16a812ad8dcf', 'The Virupaksha Temple', false, '02c2bfa7-c553-42ca-a4fe-80dbf94720e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8d72308-5b93-45e2-9b2d-f63d2620232b', 'The Lotus Mahal', false, '02c2bfa7-c553-42ca-a4fe-80dbf94720e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00cd6319-5b3e-4a2a-94c6-d4267f169617', 'The Queen''s Bath', false, '02c2bfa7-c553-42ca-a4fe-80dbf94720e6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2001c6c0-0957-41a2-b8e8-e77759db2a97', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'What was the ''Mahanavami'' festival celebrated with immense royal pomp and military reviews on the grand Mahanavami Dibba platform at Hampi?', 'The Vijayanagara kings used the Mahanavami platform to project imperial sovereignty, review armed contingents, and collect feudal tribute.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7537c571-1e0b-462b-8770-8d1f5efcd6e8', 'A 9-day grand festival (modern Navaratri / Durga Puja in the south) where the King received tribute from subordinate nayakas, inspected armies, and held wrestling and dance spectacles', true, '2001c6c0-0957-41a2-b8e8-e77759db2a97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('743c432c-032a-4c0d-95e7-10a3cad6173e', 'A harvest festival for rice', false, '2001c6c0-0957-41a2-b8e8-e77759db2a97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('069b53bf-3665-47e5-852c-1c978ce44c55', 'A celebration for the new year only', false, '2001c6c0-0957-41a2-b8e8-e77759db2a97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72aa7d06-783a-466e-926d-92024090135d', 'A feast for foreign ambassadors only', false, '2001c6c0-0957-41a2-b8e8-e77759db2a97');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4ac773e6-417a-4d9d-9b2a-a45e149c7509', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'In what decisive battle in 1565 CE was the Vijayanagara Empire defeated, leading to the sacking and ruin of the city of Hampi?', 'In 1565 at Talikota, the unified confederacy of Deccan Sultanates crushed Rama Raya''s army, pillaging Hampi.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af253b68-7d3e-4f43-bb4f-408ab9c4cdc2', 'The Battle of Talikota (Rakshasi-Tangadi), fought against the combined armies of the Deccan Sultanates (Bijapur, Golconda, Ahmadnagar, Bidar)', true, '4ac773e6-417a-4d9d-9b2a-a45e149c7509');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0febb78e-aef8-4dee-9a1d-4e5ee9a24c14', 'The Battle of Panipat', false, '4ac773e6-417a-4d9d-9b2a-a45e149c7509');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6d553d7-9844-4e01-8bb7-3cb3c96e0267', 'The Battle of Plassey', false, '4ac773e6-417a-4d9d-9b2a-a45e149c7509');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d94f615-ba57-4483-9cd3-9b1fd2926619', 'The Battle of Khanwa', false, '4ac773e6-417a-4d9d-9b2a-a45e149c7509');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8a1fa596-62b4-456e-9900-cb50fba967dc', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'Why was Surat called a cosmopolitan city in the 17th century?', 'Surat was a global cosmopolitan entrepôt hosting multi-ethnic merchant houses, textile markets, and European chartered company factories.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d1fc4df-b248-4940-9025-7bf14d48f963', 'People of all castes, creeds, and nationalities (Indians, Persians, Arabs, Portuguese, Dutch, English, and French) lived, traded, and established commercial factories there', true, '8a1fa596-62b4-456e-9900-cb50fba967dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9070af7-eeb9-4f79-87bd-90a0bd66d01a', 'Because everyone spoke only one language', false, '8a1fa596-62b4-456e-9900-cb50fba967dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ff0319f-59aa-40c5-afd0-790a8d2b9865', 'Because it had only one shop', false, '8a1fa596-62b4-456e-9900-cb50fba967dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dd5c5b3-ea63-46ae-af0e-7fb3983090af', 'Because only kings were allowed to enter', false, '8a1fa596-62b4-456e-9900-cb50fba967dc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d4498a7-408c-400c-87f9-00b346c66c37', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'What specialty luxury cotton textile produced in Surat was famous across Asian and European markets for its woven gold-thread borders (Zari)?', 'Surat''s zari textiles (brocades with real gold and silver threads) were exported widely across West Asia, Africa, and Europe.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4683d597-85a4-40e1-8c27-5ec730e1eedd', 'Zari-bordered Cotton and Silk Textiles (Zardozi)', true, '1d4498a7-408c-400c-87f9-00b346c66c37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17e15e76-ca7d-4e92-8028-eac9e06b2278', 'Kalamkari prints', false, '1d4498a7-408c-400c-87f9-00b346c66c37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc7a9131-e505-4ab0-95bb-4e3712d3b63c', 'Chintz prints', false, '1d4498a7-408c-400c-87f9-00b346c66c37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f87b6738-9c9f-491f-9ff3-51ed07505601', 'Muslin only', false, '1d4498a7-408c-400c-87f9-00b346c66c37');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ccd7a1e-813a-4f22-a4d4-2b0da4e140cc', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'What caused the commercial decline of Surat towards the late 17th and early 18th century?', 'Surat''s decline followed Mughal imperial decentralization, Maratha raids (1664/1670), and the shift of English headquarters to Bombay.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0af55de-f4b2-4876-8ca3-ae0017a2db6e', 'Loss of markets due to the decline of the Mughal Empire, control of sea trade routes by the Portuguese, and the rise of Bombay (Mumbai) as the English East India Company''s headquarters in 1668', true, '3ccd7a1e-813a-4f22-a4d4-2b0da4e140cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77a4f41a-f603-475c-9ba8-2740c14d24ef', 'Surat was swallowed by an earthquake', false, '3ccd7a1e-813a-4f22-a4d4-2b0da4e140cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2d6559d-9677-4966-8513-7b7e3ae110c6', 'All merchants stopped wearing clothes', false, '3ccd7a1e-813a-4f22-a4d4-2b0da4e140cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('100a6aa3-86d1-4bda-bbdd-14b651c5f32f', 'The river dried up in one day', false, '3ccd7a1e-813a-4f22-a4d4-2b0da4e140cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('51e61587-28e2-4bc9-b463-c38640441727', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'Why did the Golconda rulers enforce a strict royal monopoly on the sale of textiles, spices, and diamonds in Masulipatnam?', 'The Qutb Shahi kings imposed state monopolies to prevent monopolistic takeover of maritime commerce by the Dutch and English companies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91779609-7de8-47bf-af78-20f3e4167093', 'To prevent the trade from passing entirely into the hands of competing European East India companies (Dutch and English)', true, '51e61587-28e2-4bc9-b463-c38640441727');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ba7b98e-c976-45ae-97c7-6bae2f606345', 'Because they wanted to stop all trade', false, '51e61587-28e2-4bc9-b463-c38640441727');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ff78a98-1cd1-4835-a043-11d073a6ebb7', 'Because they had no money to buy food', false, '51e61587-28e2-4bc9-b463-c38640441727');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4adaf32e-3c75-432a-beae-399392a22073', 'To destroy the city of Masulipatnam', false, '51e61587-28e2-4bc9-b463-c38640441727');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d32e37a-74ad-40bd-b01f-87168f17d628', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'What is ''Kalamkari'' textile art, which flourished in Masulipatnam and Kalahasti?', 'Kalamkari (Kalam = pen, Kari = craftsmanship) employs natural mordants and vegetable dyes applied with bamboo pens on cotton cloth.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc1eadaf-0d6a-4682-a056-40d7ab24774d', 'The traditional craft of hand-painting or block-printing intricate floral and mythological motifs on cotton fabric using a natural bamboo reed pen (''Kalam'') and vegetable dyes', true, '6d32e37a-74ad-40bd-b01f-87168f17d628');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53de18f2-7ea5-4177-aeb7-dbd0ebebf42b', 'Knitting wool with metal needles', false, '6d32e37a-74ad-40bd-b01f-87168f17d628');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e452636c-b654-488b-a25e-3d658011058d', 'Stitching shoes with leather', false, '6d32e37a-74ad-40bd-b01f-87168f17d628');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f366b3e-2047-4c05-8d4e-0cabe8aba70b', 'Painting on glass plates', false, '6d32e37a-74ad-40bd-b01f-87168f17d628');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('80998a5d-83b1-42fd-a3f8-71394ca30139', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'What was the ''Panchalas'' or ''Vishwakarma'' community of craftspersons, comprising goldsmiths, bronzesmiths, blacksmiths, masons, and carpenters?', 'The Vishwakarma (Panchala) collective united five master artisan castes essential to temple architecture, metallurgy, and royal infrastructure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('103ebefc-3d85-4ad2-9083-e7daa200a0cc', 'Essential skilled builders and artisans who built monumental temples, royal palaces, massive tanks, and manufactured metal implements and idols', true, '80998a5d-83b1-42fd-a3f8-71394ca30139');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75f4c770-0277-4694-8f5b-4778f29953d6', 'A group of wandering musicians only', false, '80998a5d-83b1-42fd-a3f8-71394ca30139');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bd0a6fc-e79e-4662-be57-7f7cb574a567', 'Soldiers who guarded fort gates', false, '80998a5d-83b1-42fd-a3f8-71394ca30139');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('faa889bc-3ec8-4916-81d8-77debd1c0743', 'Farmers who grew only wheat', false, '80998a5d-83b1-42fd-a3f8-71394ca30139');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('300d43b9-55ea-4b7f-9c85-16e2446519b2', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'What were the ''Black Towns'' established by the British East India Company in newly rising port cities like Madras (Chennai), Bombay, and Calcutta?', 'Colonial racial spatial segregation: European administrators occupied fortified ''White Towns'', confining indigenous artisans to ''Black Towns''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a81273f1-e0f8-4dd8-88f5-6f87cef2d05e', 'Segregated native quarters where Indian weavers, artisans, and merchant middlemen were forced to live and work, separate from the ''White'' residential forts (Fort St. George / Fort William)', true, '300d43b9-55ea-4b7f-9c85-16e2446519b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed2d075d-11ee-492d-aaca-0f3209ad165b', 'Towns where coal was mined', false, '300d43b9-55ea-4b7f-9c85-16e2446519b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d49e4f39-996b-46e0-81c5-5470606f5457', 'Towns painted with black paint', false, '300d43b9-55ea-4b7f-9c85-16e2446519b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cd260da-a7b7-4574-9390-d23acb260596', 'Towns with no street lamps', false, '300d43b9-55ea-4b7f-9c85-16e2446519b2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba4c6399-b430-42f2-a0d8-dacb03d1a2f0', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'Which Indian merchant banking family in Murshidabad (Bengal) became fabulously wealthy and wielded enormous political influence in 18th-century Bengal?', 'The House of Jagat Seth (''Banker of the World'') controlled Bengal''s mint, revenue remittances, and treasury operations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f9cd3b1-2076-441c-891e-cf27923e51eb', 'The House of Jagat Seth', true, 'ba4c6399-b430-42f2-a0d8-dacb03d1a2f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33051048-55dc-43d9-a040-ffba945757d4', 'The Oswal Bankers', false, 'ba4c6399-b430-42f2-a0d8-dacb03d1a2f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d22b36ef-ebc9-4891-a4fa-78360d4560a5', 'The Chettiar Trust', false, 'ba4c6399-b430-42f2-a0d8-dacb03d1a2f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3075152f-46cf-4374-9142-4b3d31847912', 'The Peshwas', false, 'ba4c6399-b430-42f2-a0d8-dacb03d1a2f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b1baa6ad-7280-48ab-a1af-69689e07b3d8', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'What was the system of ''Advances'' (Dadni system) introduced by European trading companies that stripped Indian weavers of their economic independence?', 'The Dadni advance system bonded weavers to company procurement contracts, extinguishing their freedom to negotiate market prices.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbaf24d3-78ef-4dc1-8d1e-920e1238351c', 'Weavers took cash loans in advance from European agents and were legally locked into producing cloth exclusively for that company at low fixed prices, unable to sell in the open market', true, 'b1baa6ad-7280-48ab-a1af-69689e07b3d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06b794f7-e4a3-4be1-bad2-33eae4ed1d06', 'Weavers were given free houses', false, 'b1baa6ad-7280-48ab-a1af-69689e07b3d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6aad2090-79cc-4f43-8e16-c304a8d4830e', 'Weavers were trained to be ship captains', false, 'b1baa6ad-7280-48ab-a1af-69689e07b3d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1777854f-0d71-4211-b227-aaf4c5e690b2', 'Weavers were paid double wages', false, 'b1baa6ad-7280-48ab-a1af-69689e07b3d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c6bd795e-d777-4b26-b905-a2d3754516fc', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Medium', 'Why was bronze considered an ideal metal alloy for casting sacred temple idols in medieval India?', 'High-tin bell metal bronze provided superior fluidity for intricate cire-perdue molds, corrosion resistance, and sonorous resonance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a2e4be5-bbcc-480b-b2ac-00bf12ed7010', 'Bronze is an alloy of Copper and Tin (Bell Metal contains greater tin), which does not rust, produces a melodious bell-like chime when struck, and allows intricate high-definition casting', true, 'c6bd795e-d777-4b26-b905-a2d3754516fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b485d66-40b8-4d73-ae34-398354b29093', 'Because bronze is soft like butter', false, 'c6bd795e-d777-4b26-b905-a2d3754516fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69d89dbb-11f2-45c5-9960-f1e545dddcef', 'Because bronze melts in cold water', false, 'c6bd795e-d777-4b26-b905-a2d3754516fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c69037b-ec5a-4276-9192-f2abc023e599', 'Because bronze is made of pure wood', false, 'c6bd795e-d777-4b26-b905-a2d3754516fc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d2e2adb-3542-4e36-84db-7ec435cca720', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b53cef7e-79b3-4fda-bdd2-6c0bc6b93e9d', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '3d2e2adb-3542-4e36-84db-7ec435cca720');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05268055-17d0-4b3e-b595-3b7fe5dafb2f', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '3d2e2adb-3542-4e36-84db-7ec435cca720');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1806f09a-729a-433c-9278-5511bcd2bfee', '(A) is true, but (R) is false.', false, '3d2e2adb-3542-4e36-84db-7ec435cca720');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ff86f02-81d9-42d3-a032-e08301bb4386', '(A) is false, but (R) is true.', false, '3d2e2adb-3542-4e36-84db-7ec435cca720');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0189683c-a781-4f69-825c-2709a5d48c69', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'Spot the IMPOSTER in the following medieval Indian craft centers and their signature artisanal products:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0285b0dd-92e4-4891-9011-867d661e14b1', 'Center 1', false, '0189683c-a781-4f69-825c-2709a5d48c69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a6cff2f-38e5-423b-959b-0493993e8b76', 'Center 2', false, '0189683c-a781-4f69-825c-2709a5d48c69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6981ac69-718b-405c-a057-f35692652161', 'Center 3', false, '0189683c-a781-4f69-825c-2709a5d48c69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5484fdee-d53b-4fea-83b2-45e4a4e07fd2', 'Center 4 (Thanjavur was celebrated for CHOLA BRONZE IDOL CASTING and silk weaving, not 19th-century railway engines)', true, '0189683c-a781-4f69-825c-2709a5d48c69');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8bdd743e-a742-4bf5-bb4d-cfc9bb3af524', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'Analyze the shifting spatial dynamics of urbanization in 17th–18th century India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ca54f8e-024a-4284-82d3-f8148eb7efbd', 'European chartered companies secured naval hegemony, monopolized maritime shipping routes, redirected raw materials to their fortified presidency ports, and forced weavers into subordinated wage-labor networks', true, '8bdd743e-a742-4bf5-bb4d-cfc9bb3af524');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('779001dd-e255-4016-9726-4ce7e5cf3d48', 'Because all artisans voluntarily left India', false, '8bdd743e-a742-4bf5-bb4d-cfc9bb3af524');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e6638ae-d301-4fd2-8299-a6fba07e1856', 'Because the Indian Ocean dried up', false, '8bdd743e-a742-4bf5-bb4d-cfc9bb3af524');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c141e796-217e-4467-ab0f-a6032835d53d', 'Because European ships were made of glass', false, '8bdd743e-a742-4bf5-bb4d-cfc9bb3af524');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc367189-6421-45e9-aa27-10f34ccf3c8d', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'Match Column I (Medieval Trade / Craft Centers) with Column II (Prominent Distinctive Characteristics):
(a) Hampi        -> (i) Fortified capital with interlocking mortar-less granite masonry & lively bazaars
(b) Surat        -> (ii) Emporium of Western trade, pilgrim port to Mecca, famous for Zari & Hundis
(c) Masulipatnam -> (iii) Coromandel port city, center of Kalamkari cottons & Qutb Shahi monopolies
(d) Murshidabad  -> (iv) Bengal silk capital on Bhagirathi river, home to the wealthy Jagat Seths', 'Accurate historical profiling: Hampi (Vijayanagara); Surat (Mughal emporium); Masulipatnam (Coromandel port); Murshidabad (Bengal silk & banking).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19abfe99-16c2-405c-815f-a21eaae65487', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'cc367189-6421-45e9-aa27-10f34ccf3c8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbc16be5-d7e1-4f40-87bb-8ae864b12b9f', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'cc367189-6421-45e9-aa27-10f34ccf3c8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30dc68a2-935a-48e2-b882-37ebd3891bde', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'cc367189-6421-45e9-aa27-10f34ccf3c8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00c44db1-9cdc-4ccf-97f5-b2dd7a130d6e', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'cc367189-6421-45e9-aa27-10f34ccf3c8d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f07ab75b-406a-4d6c-b84b-26b594507a56', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'Read the statements regarding the Lost-Wax (Cire Perdue) bronze casting technique:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('964525f6-9eac-46a7-8243-ac9c7f76b917', 'All Statements 1, 2, and 3 are TRUE', true, 'f07ab75b-406a-4d6c-b84b-26b594507a56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8249788b-2c42-49f4-824e-ce455ea7356b', 'Statements 1 and 2 only', false, 'f07ab75b-406a-4d6c-b84b-26b594507a56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14641238-33ff-4c70-bccc-34de2c660c0e', 'Statements 2 and 3 only', false, 'f07ab75b-406a-4d6c-b84b-26b594507a56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80cf39ec-f1d0-4f64-8d99-d3d1eaa0d205', 'Statements 1 and 3 only', false, 'f07ab75b-406a-4d6c-b84b-26b594507a56');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('678944eb-a080-4788-8b8d-df1f9e596b79', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'What was the socio-economic role of ''Samantas'' (feudal lords / chiefs) in the emergence of small medieval towns (Mandapikas and Hattas)?', 'Feudal lords extracted tolls on commodities (sugar, butter, cloth, salt) and patronized temple endowments with inscribed taxation rights.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b818fdb1-e830-4711-94be-8119c1cfa313', 'Samantas built fortified palaces near markets, levied commercial transit tolls on traders, and donated the right to collect market taxes to temples in exchange for religious legitimacy', true, '678944eb-a080-4788-8b8d-df1f9e596b79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43aa1444-c17c-460e-8c72-a932ee0dc394', 'Samantas lived as forest hermits', false, '678944eb-a080-4788-8b8d-df1f9e596b79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9354b623-a553-445c-a170-91698b9720ca', 'Samantas abolished all private trade', false, '678944eb-a080-4788-8b8d-df1f9e596b79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3bc1a41-73c6-4d01-9437-235e19053deb', 'Samantas built ships to invade Europe', false, '678944eb-a080-4788-8b8d-df1f9e596b79');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f87e561-8d01-4a0e-a3b5-856bae477355', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'Why did European travel chroniclers like Domingo Paes (Portuguese) and Duarte Barbosa express immense awe at the wealth of Hampi''s bazaars?', 'Paes and Barbosa documented open street diamond markets, global equine trade, and bustling multi-ethnic commerce in 16th-century Vijayanagara.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e8f183d-fd5e-4302-9a6c-996ef60f26e4', 'The markets were overflowing with ruby, diamond, and pearl jewelry sold openly on streets, alongside Persian war horses, fine textiles, and precious spices', true, '7f87e561-8d01-4a0e-a3b5-856bae477355');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67c2143d-3538-4c67-b118-fdfdad3cbd1b', 'Because Hampi had no people', false, '7f87e561-8d01-4a0e-a3b5-856bae477355');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80f4ca86-6146-4bf6-9046-f5bc6425f6a0', 'Because everything was made of iron', false, '7f87e561-8d01-4a0e-a3b5-856bae477355');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dee306ab-590b-4199-97bf-837299cc9892', 'Because all goods were imported from America', false, '7f87e561-8d01-4a0e-a3b5-856bae477355');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27708856-2d7c-4eb6-8065-b7b829d84a51', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'How did the ''Kalamkari'' textiles of Golconda and Coromandel conquer international trade networks in Southeast Asia and Europe?', 'Indian mordant-dyeing chemistry created vibrant, wash-fast calicos and chintzes, making Indian textiles the preeminent global trade currency.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1becac3c-db00-4e1e-8ace-71c83235c7c4', 'Their brilliant natural vegetable dyes were exceptionally color-fast (resisting fading upon washing), while their exotic hand-painted Chintz designs appealed to European nobility and Indonesian spice traders', true, '27708856-2d7c-4eb6-8065-b7b829d84a51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('583015ee-8d2f-48cb-8a77-a179a67f9dfb', 'Because they were made of plastic', false, '27708856-2d7c-4eb6-8065-b7b829d84a51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80c59add-5583-4ce8-b5fd-32ca9394b545', 'Because they were given away for free', false, '27708856-2d7c-4eb6-8065-b7b829d84a51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01bc7ca9-b315-4888-8a36-317733971367', 'Because European factories could not make any cloth', false, '27708856-2d7c-4eb6-8065-b7b829d84a51');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b67ea435-37ee-42a0-83a7-88e450262d5e', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'Consider four merchant trading communities of medieval India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2cd99a4-d809-4bbf-a7e8-d48fff284ebe', 'They integrated diverse geographic regions into a unified trans-continental commercial and financial web, facilitating commodity exchange and capital flows', true, 'b67ea435-37ee-42a0-83a7-88e450262d5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6934e05-6890-436b-9e2d-8c1a2ed1f121', 'They only traded within their own single villages', false, 'b67ea435-37ee-42a0-83a7-88e450262d5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('416796f7-afce-4adb-a563-aa2cc7fd5b0a', 'They destroyed all money and used barter only', false, 'b67ea435-37ee-42a0-83a7-88e450262d5e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5faa51fc-6df1-490c-9afc-1ec572b5c3eb', 'They served exclusively as palace cooks', false, 'b67ea435-37ee-42a0-83a7-88e450262d5e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a22f3957-f2c5-4e98-b03f-09f81d689396', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'What does the English traveler Peter Mundy''s 17th-century eyewitness account reveal about the logistical scale of a Banjara ''Tanda''?', 'Peter Mundy recorded giant Banjara tandas with over 14,000 oxen transporting grain, functioning as autonomous nomadic freight corporations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f26d775-b436-4016-a488-77d93d80e82f', 'A single Tanda caravan comprised up to 14,000 to 20,000 bullocks laden with grain, moving with families, children, and livestock over hundreds of miles to feed cities and military camps', true, 'a22f3957-f2c5-4e98-b03f-09f81d689396');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01d99c2f-d2b4-47bb-8485-56f74d49f281', 'Banjaras traveled in flying carts', false, 'a22f3957-f2c5-4e98-b03f-09f81d689396');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7399f30-a6cd-4860-80b7-dcb87493b522', 'Banjaras carried goods on their heads only', false, 'a22f3957-f2c5-4e98-b03f-09f81d689396');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63ff1a6b-8eba-418c-a36f-1b292bbec484', 'A Tanda had only one donkey', false, 'a22f3957-f2c5-4e98-b03f-09f81d689396');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('50a510a4-30d5-4acb-8a26-8255ba261b18', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'How did the invention and usage of the ''Hundi'' demonstrate the sophisticated level of financial capitalism in medieval India?', 'Hundis reflected mature indigenous mercantile capitalism, combining credit discounting, foreign exchange, and risk-hedged capital remittance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e2d134a-9cee-496e-8cb6-49cff9f089bc', 'It proved the existence of an intricate inter-regional banking network based on trust, merchant creditworthiness, and standardized financial instruments operating across thousands of kilometers', true, '50a510a4-30d5-4acb-8a26-8255ba261b18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67034d38-f6ab-40c4-9d27-6ad7594ab131', 'It showed that paper did not exist', false, '50a510a4-30d5-4acb-8a26-8255ba261b18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fcc1ae0-ee92-453b-9d7a-b987f3789421', 'It proved that kings had no gold', false, '50a510a4-30d5-4acb-8a26-8255ba261b18');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9b732e1-d5b1-4eb6-be54-f91b307af563', 'It was used to buy ships from pirates', false, '50a510a4-30d5-4acb-8a26-8255ba261b18');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2664db4f-7130-4162-88dd-687177843efb', 'Class 7', 'Social Science', 'Chapter 6: Towns, Traders and Craftspersons', 'Hard', 'What master socio-economic narrative is highlighted in Chapter 6 of NCERT Class 7 History?', 'Chapter 6 celebrates the economic sophistication, architectural vibrancy, artisanal mastery, and global trade preeminence of medieval India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd18cf71-aaa3-4d3d-a8a0-bb2fd287a2a4', 'The vibrancy of medieval Indian urban life, where specialized artisans, flourishing merchant guilds, dynamic pilgrimage temple towns, and world-class manufacturing ports formed a globally dominant trade ecosystem before colonial restructuring', true, '2664db4f-7130-4162-88dd-687177843efb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83c96696-5583-464b-9597-df209efbeb07', 'A period of total poverty and complete trade collapse', false, '2664db4f-7130-4162-88dd-687177843efb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aad9ccf6-9ae3-4065-afe3-3b20c661d6bf', 'An era without any towns or crafts', false, '2664db4f-7130-4162-88dd-687177843efb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6b5a9c6-d2e1-4414-ba35-bff18ef9e84c', 'The destruction of all Indian textiles', false, '2664db4f-7130-4162-88dd-687177843efb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cbfffcf3-0116-431e-af81-30e0a2cb6fc6', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', 'किसी व्यक्ति, वस्तु, स्थान, प्राणी या भाव के नाम का बोध कराने वाले सार्थक शब्दों को व्याकरण में क्या कहते हैं?', 'संज्ञा: किसी व्यक्ति, वस्तु, स्थान, प्राणी या भाव के नाम को संज्ञा कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be9befa7-390a-4abf-bc54-f387b28fb4fe', 'संज्ञा (Noun)', true, 'cbfffcf3-0116-431e-af81-30e0a2cb6fc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f57811b-9cfd-4640-9e3f-d25ed115036b', 'सर्वनाम', false, 'cbfffcf3-0116-431e-af81-30e0a2cb6fc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23c834f0-33cd-48d8-b5af-d10c022487bb', 'विशेषण', false, 'cbfffcf3-0116-431e-af81-30e0a2cb6fc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43f307f1-8462-481b-8c2c-1d1dcfb4a424', 'क्रिया', false, 'cbfffcf3-0116-431e-af81-30e0a2cb6fc6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9758fc44-0963-4ae6-857e-c50ce7a03592', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', 'हिंदी व्याकरण में संज्ञा के मुख्य रूप से कितने भेद माने गए हैं?', 'संज्ञा के 3 मुख्य भेद हैं: व्यक्तिवाचक, जातिवाचक (जिसके अंतर्गत द्रव्यवाचक व समूहवाचक आते हैं), और भाववाचक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc01bd23-b472-40c6-bc97-b08b46db3e95', 'तीन मुख्य भेद (1. व्यक्तिवाचक संज्ञा, 2. जातिवाचक संज्ञा, 3. भाववाचक संज्ञा)', true, '9758fc44-0963-4ae6-857e-c50ce7a03592');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75109031-887f-4347-8b45-d22674702d5e', 'पाँच मुख्य भेद', false, '9758fc44-0963-4ae6-857e-c50ce7a03592');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cdb1919-1368-4010-9555-bca4aa7385f4', 'दो मुख्य भेद', false, '9758fc44-0963-4ae6-857e-c50ce7a03592');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3327e948-890b-46cb-ace2-945c9c6b9e5a', 'चार मुख्य भेद', false, '9758fc44-0963-4ae6-857e-c50ce7a03592');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa12efa9-f95e-4083-a4c1-c1b95e4e7d42', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', 'जिन संज्ञा शब्दों से किसी एक ''विशेष'' व्यक्ति, विशेष प्राणी, विशेष वस्तु या विशेष स्थान का बोध होता है, उन्हें क्या कहते हैं?', 'किसी विशिष्ट सत्ता, व्यक्ति या भौगोलिक नाम का बोध कराने वाले शब्द ''व्यक्तिवाचक संज्ञा'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80919f74-3059-4f93-803e-8d106942cda5', 'व्यक्तिवाचक संज्ञा (Proper Noun - जैसे: भारत, गंगा, हिमालय, महात्मा गांधी, रामायण)', true, 'aa12efa9-f95e-4083-a4c1-c1b95e4e7d42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89159f35-bc0e-4130-ae56-6e9d84523c9f', 'जातिवाचक संज्ञा', false, 'aa12efa9-f95e-4083-a4c1-c1b95e4e7d42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('680c5d4c-92cd-4006-b790-8f1dfb7a182b', 'भाववाचक संज्ञा', false, 'aa12efa9-f95e-4083-a4c1-c1b95e4e7d42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc3fb6ce-4943-4726-84b9-2510303bcfa3', 'द्रव्यवाचक संज्ञा', false, 'aa12efa9-f95e-4083-a4c1-c1b95e4e7d42');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bfcd4870-f241-45ac-9413-20d334051999', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', 'जिन संज्ञा शब्दों से किसी प्राणी, वस्तु या स्थान की ''संपूर्ण जाति या वर्ग'' का बोध होता है, उन्हें क्या कहते हैं?', 'संपूर्ण प्रजाति, वर्ग या श्रेणी का सामान्य बोध कराने वाले शब्द ''जातिवाचक संज्ञा'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4281ad8-9992-493a-99f8-5d9e4fdf14b0', 'जातिवाचक संज्ञा (Common Noun - जैसे: नदी, पर्वत, लड़का, देश, नगर, पुस्तक)', true, 'bfcd4870-f241-45ac-9413-20d334051999');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80fac516-f0ba-475a-a9b3-434ba1af36ae', 'व्यक्तिवाचक संज्ञा', false, 'bfcd4870-f241-45ac-9413-20d334051999');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d225645-4259-4d8b-9807-de79e9a19693', 'भाववाचक संज्ञा', false, 'bfcd4870-f241-45ac-9413-20d334051999');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88e87f0c-baa5-49f0-ac5e-13849cf279db', 'सर्वनाम', false, 'bfcd4870-f241-45ac-9413-20d334051999');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('21926978-5e5d-4354-9c99-0945a5c6ff17', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', 'जिन शब्दों से किसी पदार्थ के गुण, दोष, दशा, अवस्था, स्वभाव या भाव का बोध होता है और जिन्हें केवल अनुभव किया जा सकता है, उन्हें क्या कहते हैं?', 'अमूर्त गुण, भाव, दशा और अवस्था का बोध कराने वाले शब्द ''भाववाचक संज्ञा'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d081cff6-ef37-42a4-b824-2d99714791db', 'भाववाचक संज्ञा (Abstract Noun - जैसे: मिठास, बचपन, सुंदरता, क्रोध, ईमानदारी, बुढ़ापा)', true, '21926978-5e5d-4354-9c99-0945a5c6ff17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('497d3b2e-51a1-4649-935b-75a8047a48cc', 'जातिवाचक संज्ञा', false, '21926978-5e5d-4354-9c99-0945a5c6ff17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53c2910c-6d49-4a02-9016-2697d844d29c', 'द्रव्यवाचक संज्ञा', false, '21926978-5e5d-4354-9c99-0945a5c6ff17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77227e5a-9fbb-4617-96c7-e3b687caca3d', 'व्यक्तिवाचक संज्ञा', false, '21926978-5e5d-4354-9c99-0945a5c6ff17');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d55f3bf2-2238-44d8-a1ca-9050d75be764', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', 'जिन संज्ञा शब्दों से किसी धातु, द्रव्य, तरल या ठोस पदार्थ का बोध होता है जिन्हें नापा या तौला जा सकता है, उन्हें क्या कहते हैं?', 'माप-तोल योग्य धातुओं, खनिजों और द्रवों के नाम ''द्रव्यवाचक संज्ञा'' (जातिवाचक का उप-भेद) कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55327024-855c-4634-8c90-1c7de2509e17', 'द्रव्यवाचक संज्ञा (Material Noun - जैसे: सोना, चाँदी, दूध, पानी, तेल, गेहूँ)', true, 'd55f3bf2-2238-44d8-a1ca-9050d75be764');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d82bb5f-ae3a-4487-8e81-251a9e50043f', 'समूहवाचक संज्ञा', false, 'd55f3bf2-2238-44d8-a1ca-9050d75be764');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('341279af-08c1-46ab-880b-c0c4c4ae5e5b', 'भाववाचक संज्ञा', false, 'd55f3bf2-2238-44d8-a1ca-9050d75be764');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('990ed941-aa55-4090-b9cb-ffd5d955eeac', 'व्यक्तिवाचक संज्ञा', false, 'd55f3bf2-2238-44d8-a1ca-9050d75be764');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4230a53b-490d-41e5-b951-0cdd056cb282', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', 'जिन संज्ञा शब्दों से व्यक्तियों या वस्तुओं के ''समूह अथवा समुदाय'' का बोध होता है, उन्हें क्या कहते हैं?', 'समूह या झुंड का एकवचन रूप में बोध कराने वाले शब्द ''समूहवाचक संज्ञा'' कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce78afb4-2778-4e3d-85d8-02f43b6ddaf7', 'समूहवाचक / समुदायवाचक संज्ञा (Collective Noun - जैसे: कक्षा, सेना, सभा, झुंड, भीड़, गुच्छा)', true, '4230a53b-490d-41e5-b951-0cdd056cb282');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72b5361e-9ff4-4732-915e-11473000673e', 'द्रव्यवाचक संज्ञा', false, '4230a53b-490d-41e5-b951-0cdd056cb282');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ffb0373-de53-4c0a-ada4-2de0bf909e0a', 'व्यक्तिवाचक संज्ञा', false, '4230a53b-490d-41e5-b951-0cdd056cb282');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9efffcc-1368-4dee-854e-dd9f08bcb4e5', 'भाववाचक संज्ञा', false, '4230a53b-490d-41e5-b951-0cdd056cb282');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3eb92208-ba34-426b-a0d1-fa840c6e790e', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', '''गंगा भारत की सबसे पवित्र नदी है।'' वाक्य में ''गंगा'' और ''नदी'' क्रमशः कौन-सी संज्ञाएँ हैं?', '''गंगा'' एक विशिष्ट नदी का नाम है (व्यक्तिवाचक); ''नदी'' संपूर्ण जलधाराओं की जाति है (जातिवाचक)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d0867be-164a-4823-b576-2d30835d3868', '''गंगा'' व्यक्तिवाचक संज्ञा है और ''नदी'' जातिवाचक संज्ञा है', true, '3eb92208-ba34-426b-a0d1-fa840c6e790e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43cd37e2-83c5-4679-9b61-285333535d32', 'दोनों व्यक्तिवाचक हैं', false, '3eb92208-ba34-426b-a0d1-fa840c6e790e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c28e57c-28a4-4eff-a6ab-184853e1a546', 'दोनों जातिवाचक हैं', false, '3eb92208-ba34-426b-a0d1-fa840c6e790e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cf8bb89-2b22-4455-83a2-37bfe47c4d12', '''गंगा'' भाववाचक है और ''नदी'' द्रव्यवाचक है', false, '3eb92208-ba34-426b-a0d1-fa840c6e790e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aac42252-d718-4d63-86a4-a4d1f822f9d8', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', '''बच्चा'' जातिवाचक संज्ञा शब्द से बनने वाली सही भाववाचक संज्ञा क्या होगी?', '''बच्चा'' में ''पन'' प्रत्यय लगने से भाववाचक संज्ञा ''बचपन'' बनती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5a61527-56b8-4301-803a-1918c5a59405', 'बचपन', true, 'aac42252-d718-4d63-86a4-a4d1f822f9d8');
