INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('690438e1-ca42-4032-b46f-b24ca222b19d', 'बचपनापन', false, 'aac42252-d718-4d63-86a4-a4d1f822f9d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('087921f4-a791-4faf-aee2-fa98688ea050', 'बालक', false, 'aac42252-d718-4d63-86a4-a4d1f822f9d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77e71735-c4a7-4343-b63c-5c47c5deb0cc', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', '''सुंदर'' विशेषण शब्द से बनने वाली शुद्ध भाववाचक संज्ञा कौन-सी है?', 'सुंदर + ता = सुंदरता ; सुंदर + य = सौंदर्य (भाववाचक संज्ञाएँ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ddc269d-8494-4dda-ab14-a712c9e7cd55', 'सुंदरता अथवा सौंदर्य', true, '77e71735-c4a7-4343-b63c-5c47c5deb0cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0edf81cf-04ea-4f86-b237-b6efd6eedba8', 'सुंदरी', false, '77e71735-c4a7-4343-b63c-5c47c5deb0cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ec061ad-51df-40a6-8b31-82a6f1c37455', 'सुंदरतम', false, '77e71735-c4a7-4343-b63c-5c47c5deb0cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57d87b8d-dc2a-4070-99b5-fd9a06e88e55', 'सुंदरपना', false, '77e71735-c4a7-4343-b63c-5c47c5deb0cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0287a50f-7b81-4b5b-8ded-d699338c592a', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', '''हँसना'' क्रिया शब्द से बनने वाली सही भाववाचक संज्ञा क्या है?', '''हँसना'' क्रिया में ''ई'' प्रत्यय जुड़ने से भाववाचक संज्ञा ''हँसी'' बनती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('672bbef6-f573-4ba1-9316-19cadaf28499', 'हँसी', true, '0287a50f-7b81-4b5b-8ded-d699338c592a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29cce0ab-8648-4a96-8445-20e3b6ca0dc7', 'हँसोड़', false, '0287a50f-7b81-4b5b-8ded-d699338c592a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24515c31-f648-406c-b6d0-f59a0760760a', 'हँसमुख', false, '0287a50f-7b81-4b5b-8ded-d699338c592a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d30eeee-b3ec-4e61-901f-83b8e05de6e5', 'हँसनापन', false, '0287a50f-7b81-4b5b-8ded-d699338c592a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0fc25f6b-9afc-44dc-b388-49987136e9f8', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Easy', 'निम्नलिखित में से ''समूहवाचक संज्ञा'' का सही उदाहरण कौन-सा है?', 'सेना, कक्षा, गुच्छा, भीड़ - व्यक्तियों/वस्तुओं के समूह का बोध कराते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ffc3349-9d74-4d5e-b385-99fac3a2a461', 'सेना, कक्षा, चाबियों का गुच्छा, भीड़', true, '0fc25f6b-9afc-44dc-b388-49987136e9f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('052e0a62-1037-4318-a366-1b2578306981', 'सोना, चाँदी', false, '0fc25f6b-9afc-44dc-b388-49987136e9f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29a438e7-5ccf-45c4-a203-487e04bfe69b', 'मिठास, खटास', false, '0fc25f6b-9afc-44dc-b388-49987136e9f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc3e5b18-2d8c-41ef-bea1-ebac4ab6c4c0', 'राम, श्याम', false, '0fc25f6b-9afc-44dc-b388-49987136e9f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0ba5fc8-2ad8-4147-839d-cbcbf9a81a11', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', 'भाववाचक संज्ञाओं का निर्माण मुख्य रूप से कितने प्रकार के शब्दों से किया जाता है?', 'भाववाचक संज्ञाएँ 5 स्रोतों से बनती हैं: जातिवाचक संज्ञा (मित्र→मित्रता), सर्वनाम (अपना→अपनत्व), विशेषण (मीठा→मिठास), क्रिया (लिखना→लिखाई), अव्यय (दूर→दूरी)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4cbc02f-6a09-4fa5-b5a1-fc480b479679', 'पाँच प्रकार के शब्दों से (1. जातिवाचक संज्ञा से, 2. सर्वनाम से, 3. विशेषण से, 4. क्रिया से, 5. अव्यय से)', true, 'c0ba5fc8-2ad8-4147-839d-cbcbf9a81a11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a4285f5-f599-4eec-b613-00d62e41980e', 'दो प्रकार के शब्दों से', false, 'c0ba5fc8-2ad8-4147-839d-cbcbf9a81a11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac2ee4da-7d5b-4e89-9584-b7dc01e394d2', 'आठ प्रकार के शब्दों से', false, 'c0ba5fc8-2ad8-4147-839d-cbcbf9a81a11');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2e50b24-60d0-4409-aea3-d77483082ab3', 'केवल क्रियाओं से', false, 'c0ba5fc8-2ad8-4147-839d-cbcbf9a81a11');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('763c2cc4-7dd1-4cb0-9875-acebd1f52fa1', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', 'सर्वनाम शब्दों से बनी भाववाचक संज्ञाओं का सही समूह कौन-सा है?', 'सर्वनाम ''अपना, मम, निज, सर्व'' से ''अपनत्व, ममता, निजत्व, सर्वस्व'' बनते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c021da91-4da1-4a3e-add8-f582583ffcfd', 'अपना -> अपनत्व / अपनापन ; मम -> ममता / ममत्व ; निज -> निजत्व ; सर्व -> सर्वस्व', true, '763c2cc4-7dd1-4cb0-9875-acebd1f52fa1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c08d39c0-1cb3-4554-bb3d-0745b44d2bed', 'लड़का -> लड़कपन', false, '763c2cc4-7dd1-4cb0-9875-acebd1f52fa1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e427edc-c81d-4063-b40f-e9ad94b53612', 'सफेद -> सफेदी', false, '763c2cc4-7dd1-4cb0-9875-acebd1f52fa1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab8f428d-bbdb-4007-ba5b-45ec9969deb1', 'पढ़ना -> पढ़ाई', false, '763c2cc4-7dd1-4cb0-9875-acebd1f52fa1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('69bd5844-7443-446e-8950-09efb163605f', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', 'विशेषण शब्दों से बनी भाववाचक संज्ञाओं का सही समूह कौन-सा है?', 'विशेषण ''मीठा, चतुर, वीर, आलसी, कठोर'' से ''मिठास, चतुराई, वीरता, आलस्य, कठोरता'' बनते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d31b22e8-cdd8-4ecc-9fae-6912a2e33055', 'मीठा -> मिठास ; चतुर -> चतुराई ; वीर -> वीरता ; आलसी -> आलस्य ; कठोर -> कठोरता', true, '69bd5844-7443-446e-8950-09efb163605f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afad9634-b795-4439-874e-cff7b1912a12', 'मनुष्य -> मनुष्यता', false, '69bd5844-7443-446e-8950-09efb163605f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14c097aa-3059-4b73-b502-f1059d6cdf47', 'हँसना -> हँसी', false, '69bd5844-7443-446e-8950-09efb163605f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7264a5f7-ae17-4728-9841-261e25d04904', 'अहम -> अहंकार', false, '69bd5844-7443-446e-8950-09efb163605f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e779f69a-1f40-4b3a-8a29-275aae72bf63', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', 'क्रिया शब्दों से बनी भाववाचक संज्ञाओं का सही समूह कौन-सा है?', 'क्रिया ''सजाना, थकना, चढ़ना, बहना, दौड़ना'' से ''सजावट, थकावट, चढ़ाई, बहाव, दौड़'' बनते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe71ff4c-8bb3-440c-b30c-7a1ac7b33095', 'सजाना -> सजावट ; थकना -> थकावट / थकान ; चढ़ना -> चढ़ाई ; बहना -> बहाव ; दौड़ना -> दौड़', true, 'e779f69a-1f40-4b3a-8a29-275aae72bf63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad1cdcf6-585f-4656-8a02-7808cfc73404', 'पशु -> पशुता', false, 'e779f69a-1f40-4b3a-8a29-275aae72bf63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('340db406-2fde-4403-ac5b-5a42f25663ca', 'सुंदर -> सुंदरता', false, 'e779f69a-1f40-4b3a-8a29-275aae72bf63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2a4a19d-e5d6-4305-9f56-67fe0297df0f', 'आप -> आपा', false, 'e779f69a-1f40-4b3a-8a29-275aae72bf63');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0c3be55-b175-4d5e-964d-a618b5057b87', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', 'अव्यय शब्दों से बनी भाववाचक संज्ञाओं का सही समूह कौन-सा है?', 'अव्यय ''निकट, दूर, मना, शीघ्र'' से ''निकटता, दूरी, मनाही, शीघ्रता'' भाववाचक संज्ञाएँ बनती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e83041d3-8383-4e57-afa7-a48a1dc1256b', 'निकट -> निकटता ; दूर -> दूरी ; मना -> मनाही ; शीघ्र -> शीघ्रता ; नीचे -> नीचाई', true, 'd0c3be55-b175-4d5e-964d-a618b5057b87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3744b44-9b15-423c-b72e-75fd1062f2d6', 'बालक -> बालपन', false, 'd0c3be55-b175-4d5e-964d-a618b5057b87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('033bd882-34ea-41b6-966f-7ca57ba6060f', 'गर्म -> गर्मी', false, 'd0c3be55-b175-4d5e-964d-a618b5057b87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68b4d28d-4ed7-40cb-9dfd-e784dab31760', 'लिखना -> लेख', false, 'd0c3be55-b175-4d5e-964d-a618b5057b87');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('949a13cd-59ac-49c5-ad37-85f977c5b205', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', '''आज के युग में भी हरिश्चंद्रों की कमी नहीं है।'' वाक्य में रेखांकित शब्द ''हरिश्चंद्रों'' किस संज्ञा के रूप में प्रयुक्त हुआ है?', 'जब कोई व्यक्तिवाचक नाम अपने विशिष्ट गुण के कारण पूरे वर्ग/जाति का प्रतीक बन जाए (और बहुवचन में प्रयुक्त हो), तो वह जातिवाचक संज्ञा बन जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9611d211-7f21-480b-a1d5-5b5485c4a372', 'जातिवाचक संज्ञा के रूप में (क्योंकि यहाँ ''हरिश्चंद्र'' किसी एक व्यक्ति का नाम न होकर ''सत्यवादी एवं निष्ठावान व्यक्तियों के संपूर्ण वर्ग'' का बोध करा रहा है)', true, '949a13cd-59ac-49c5-ad37-85f977c5b205');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1cd7ce7-d009-419d-beac-6b1819868625', 'व्यक्तिवाचक संज्ञा के रूप में', false, '949a13cd-59ac-49c5-ad37-85f977c5b205');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('847c160f-180c-4e4f-b0aa-151578fd1be4', 'भाववाचक संज्ञा के रूप में', false, '949a13cd-59ac-49c5-ad37-85f977c5b205');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da54da87-c800-4d96-835e-8744271bf565', 'द्रव्यवाचक संज्ञा के रूप में', false, '949a13cd-59ac-49c5-ad37-85f977c5b205');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b8d0feb4-dc11-4b42-a898-04be2e7710c1', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', '''गांधीजी ने देश को सत्य और अहिंसा का पाठ पढ़ाया।'' वाक्य में ''गांधीजी'' किस संज्ञा के रूप में प्रयुक्त हुआ है?', 'जब कोई जातिसूचक शब्द किसी एक ही विशिष्ट ऐतिहासिक महापुरुष के लिए रूढ़ हो जाता है (जैसे: गांधीजी, नेताजी, शास्त्रीजी), तो वह व्यक्तिवाचक संज्ञा बन जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e547211-1aa4-46f7-9c5e-2600e4b5c829', 'व्यक्तिवाचक संज्ञा के रूप में (यद्यपि ''गांधी'' एक जाति/उपनाम है, परन्तु यहाँ यह केवल एक विशिष्ट व्यक्ति ''महात्मा मोहनदास करमचंद गांधी'' के लिए रूढ़ हुआ है)', true, 'b8d0feb4-dc11-4b42-a898-04be2e7710c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('051c94d8-3a8b-4645-9c10-3270702b6452', 'जातिवाचक संज्ञा के रूप में', false, 'b8d0feb4-dc11-4b42-a898-04be2e7710c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7daac8d-169a-48e5-8cdb-ee10cb050612', 'भाववाचक संज्ञा के रूप में', false, 'b8d0feb4-dc11-4b42-a898-04be2e7710c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91998ae1-6d9c-4f7d-879e-d3808e1d2adc', 'समूहवाचक संज्ञा के रूप में', false, 'b8d0feb4-dc11-4b42-a898-04be2e7710c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f58e3fc-1ded-4da5-9678-ff2161406929', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', '''बुढ़ापा मनुष्य के जीवन का एक अभिशाप है।'' वाक्य में ''बुढ़ापा'' कौन-सी संज्ञा है?', '''बुढ़ापा'' ''बूढ़ा'' विशेषण/जातिवाचक से बनी अवस्था-सूचक भाववाचक संज्ञा है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3b935f8-778f-47e3-a434-7560fd88c3fc', 'भाववाचक संज्ञा (अवस्था सूचक)', true, '2f58e3fc-1ded-4da5-9678-ff2161406929');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3daaf201-bcc6-4f53-8401-cc92c41eb074', 'जातिवाचक संज्ञा', false, '2f58e3fc-1ded-4da5-9678-ff2161406929');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16545fef-157c-42f9-969d-c30a821bfbb6', 'व्यक्तिवाचक संज्ञा', false, '2f58e3fc-1ded-4da5-9678-ff2161406929');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7535849d-d4a8-46ff-8bc8-b0ecb3915fbd', 'द्रव्यवाचक संज्ञा', false, '2f58e3fc-1ded-4da5-9678-ff2161406929');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18c63872-12d0-4eb3-b1bb-ca5b80e04b00', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', '''पंडित'' जातिवाचक संज्ञा से बनने वाली शुद्ध भाववाचक संज्ञा क्या होगी?', '''पंडित'' में ''य'' प्रत्यय जुड़ने से आदि-स्वर वृद्धि होकर शुद्ध भाववाचक संज्ञा ''पांडित्य'' बनती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ff19b46-f2fa-4dde-816d-3904f0d5db14', 'पांडित्य (अथवा पांडित्यभाव)', true, '18c63872-12d0-4eb3-b1bb-ca5b80e04b00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e268ca5-ddb2-4953-a0ab-2eb71e50e0b1', 'पंडिताई', false, '18c63872-12d0-4eb3-b1bb-ca5b80e04b00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdeab0fd-73aa-4d95-9248-b8499c726e80', 'पंडितजी', false, '18c63872-12d0-4eb3-b1bb-ca5b80e04b00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('746dd10d-b174-45ca-b23a-53d3529d968c', 'पंडिताइन', false, '18c63872-12d0-4eb3-b1bb-ca5b80e04b00');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b3bd76c-918e-45cc-b2b3-e89d95d40888', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', 'निम्नलिखित में से कौन-सा शब्द ''भाववाचक संज्ञा'' नहीं है?', '''मिठाई'' मूर्त खाद्य पदार्थ (जातिवाचक) है; अमूर्त स्वाद का भाव ''मिठास'' (भाववाचक संज्ञा) है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28ca2597-d7d0-4cd4-8379-8dbd3dc4c895', '''मिठाई'' (क्योंकि मिठाई एक खाद्य वस्तु है - जातिवाचक संज्ञा है ; इसकी भाववाचक संज्ञा ''मिठास'' होती है)', true, '8b3bd76c-918e-45cc-b2b3-e89d95d40888');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d272a711-1873-41b7-a84b-2edb63383e36', '''मिठास''', false, '8b3bd76c-918e-45cc-b2b3-e89d95d40888');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ca6d10c-8077-4dcd-8917-c4d57a6222a9', '''सुंदरता''', false, '8b3bd76c-918e-45cc-b2b3-e89d95d40888');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75afee42-92f2-444a-b2c9-d19e356f3010', '''चतुराई''', false, '8b3bd76c-918e-45cc-b2b3-e89d95d40888');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6fe193f7-c3df-4a35-b7db-3955c15eb94e', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', '''सोना, चाँदी, ताँबा, पीतल, लोहा'' किस संज्ञा वर्ग के अंतर्गत आते हैं?', 'सभी धातुएँ और खनिज पदार्थ ''द्रव्यवाचक संज्ञा'' के अंतर्गत आते हैं।', NOW()) ON CONFLICT DO NOTHING;
