INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba3f59d2-93d4-4655-b643-dc0628dde815', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', '''सभा में सैकड़ों लोग उपस्थित थे।'' वाक्य में ''सभा'' शब्द कौन-सी संज्ञा है?', '''सभा'' जनसमूह का बोध कराती है, अतः यह समूहवाचक संज्ञा है।', NOW()) ON CONFLICT DO NOTHING;
