INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('414665a9-2c22-4aab-93e1-68c9fab60130', 'व्यक्तिवाचक संज्ञा', false, 'ba3f59d2-93d4-4655-b643-dc0628dde815');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82e3e2be-2120-4e62-a2ab-a47e54011475', 'भाववाचक संज्ञा', false, 'ba3f59d2-93d4-4655-b643-dc0628dde815');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('544cc059-11df-4c30-8049-1a1a7d25e4a0', 'द्रव्यवाचक संज्ञा', false, 'ba3f59d2-93d4-4655-b643-dc0628dde815');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('212b870a-fb58-42b5-aaff-7e5622bebb03', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', '''शत्रु'' जातिवाचक संज्ञा से बनने वाली शुद्ध भाववाचक संज्ञा क्या होगी?', 'शत्रु + ता = शत्रुता (भाववाचक संज्ञा)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c64de71-e83d-4059-a653-cc460b7d8900', 'शत्रुता (अथवा शत्रुत्व)', true, '212b870a-fb58-42b5-aaff-7e5622bebb03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dd5cc33-c47a-4a11-98c8-1a98e7eb6586', 'शत्रुगण', false, '212b870a-fb58-42b5-aaff-7e5622bebb03');
