INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('302e0e34-b5f2-4be1-b077-e453ad23d134', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', '''अमर'' विशेषण से बनने वाली सही भाववाचक संज्ञा क्या होगी?', 'अमर + ता = अमरता ; अमर + त्व = अमरत्व (भाववाचक संज्ञा)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c420015-d1ef-407a-8098-567407c390fc', 'अमरता अथवा अमरत्व', true, '302e0e34-b5f2-4be1-b077-e453ad23d134');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b11e105-9a15-48f3-96ed-496f66472889', 'अमराई', false, '302e0e34-b5f2-4be1-b077-e453ad23d134');
