INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('020f4dc4-d0d4-4148-b7c9-0a1c21139f6a', 'अमरपन', false, '302e0e34-b5f2-4be1-b077-e453ad23d134');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a1df0f07-d947-436a-9460-e19a925b0654', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', '''सच्चा'' विशेषण से बनने वाली शुद्ध भाववाचक संज्ञा क्या है?', 'सच्चा + आई = सच्चाई (भाववाचक संज्ञा)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db60e36c-5814-4dce-9d30-cadc68194299', 'सच्चाई', true, 'a1df0f07-d947-436a-9460-e19a925b0654');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62658c90-fd8d-406f-8c56-fdda360dcb70', 'सच्चापन', false, 'a1df0f07-d947-436a-9460-e19a925b0654');
