INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a543f6d4-5f44-43c3-b336-b9995f43887f', 'सच्ची', false, 'a1df0f07-d947-436a-9460-e19a925b0654');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93100a78-157d-4fa3-b5c8-edea72182951', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Medium', 'जब कोई भाववाचक संज्ञा शब्द ''बहुवचन'' रूप में प्रयुक्त होता है (जैसे: बुराई -> बुराइयाँ, दूरी -> दूरियाँ, प्रार्थना -> प्रार्थनाएँ), तब वह किस संज्ञा में परिवर्तित हो जाता है?', 'महत्वपूर्ण व्याकरणिक नियम: भाववाचक संज्ञाएँ सदैव एकवचन होती हैं; बहुवचन रूप में वे जातिवाचक संज्ञा बन जाती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a16bf7a-7a1c-4bd9-a0f0-bcda34e16ecd', 'जातिवाचक संज्ञा में (क्योंकि भाववाचक संज्ञाएँ सदैव एकवचन में होती हैं ; बहुवचन बनते ही वे जातिवाचक बन जाती हैं)', true, '93100a78-157d-4fa3-b5c8-edea72182951');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec46b5d9-47ab-4033-a51d-ba8719b3f74b', 'व्यक्तिवाचक संज्ञा में', false, '93100a78-157d-4fa3-b5c8-edea72182951');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea7d1044-25e2-4ef8-a7b6-f8519129ac23', 'द्रव्यवाचक संज्ञा में', false, '93100a78-157d-4fa3-b5c8-edea72182951');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f61b92fd-aef2-43ca-a396-1c69b5d53d85', 'समूहवाचक संज्ञा में', false, '93100a78-157d-4fa3-b5c8-edea72182951');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f8b89728-c736-4b52-80b4-0742a7643844', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffcb1a11-eb9f-4a23-a7ff-ad99211dab15', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'f8b89728-c736-4b52-80b4-0742a7643844');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4957faa9-47a7-4b9f-85f6-8e44cc8ad97a', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'f8b89728-c736-4b52-80b4-0742a7643844');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3700b73b-771c-4f0a-b5d4-d03868ecbd8f', '(A) सही है, परन्तु (R) गलत है।', false, 'f8b89728-c736-4b52-80b4-0742a7643844');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d64ae8ba-7cb6-4296-b1ac-c4697bd659ea', '(A) गलत है, परन्तु (R) सही है।', false, 'f8b89728-c736-4b52-80b4-0742a7643844');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('825d647c-857c-44a7-92df-21a4e25fe855', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', 'Spot the IMPOSTER in the following group of मूल शब्द और उनसे निर्मित भाववाचक संज्ञाओं में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2589c0a1-86cc-44c2-8151-ac74eb377984', 'युग्म 1', false, '825d647c-857c-44a7-92df-21a4e25fe855');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30493353-1c61-40c4-a2aa-f6a9de9c242b', 'युग्म 2', false, '825d647c-857c-44a7-92df-21a4e25fe855');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('432b6f29-ae38-4414-b452-5da76c5527fd', 'युग्म 3', false, '825d647c-857c-44a7-92df-21a4e25fe855');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61722cb5-d624-4c88-8769-25ee2c3de8ef', 'युग्म 4 (''पनियाना'' एक नामधातु क्रिया है, भाववाचक संज्ञा नहीं)', true, '825d647c-857c-44a7-92df-21a4e25fe855');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2acf6baf-fef2-4518-8898-005904f39ddb', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', 'सुमेलित कीजिए (संज्ञा शब्द और उनके सही भेद):
(क) रामायण     -> (i) व्यक्तिवाचक संज्ञा
(ख) पर्वत      -> (ii) जातिवाचक संज्ञा
(ग) ममता       -> (iii) भाववाचक संज्ञा
(घ) तेल        -> (iv) द्रव्यवाचक संज्ञा', 'रामायण = ग्रंथ का विशिष्ट नाम (व्यक्तिवाचक); पर्वत = जातिवाचक; ममता = भाववाचक; तेल = द्रव्यवाचक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39b65de0-0636-46b3-84fc-3e511f99f25e', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, '2acf6baf-fef2-4518-8898-005904f39ddb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c92bb0c-ee52-4897-ba39-a4cbf1b3fb03', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '2acf6baf-fef2-4518-8898-005904f39ddb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('286b1f3c-54d0-4bb1-8840-37cbc263726d', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '2acf6baf-fef2-4518-8898-005904f39ddb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e070516e-4948-4b26-827e-00230f8a0be2', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '2acf6baf-fef2-4518-8898-005904f39ddb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8334b563-0457-4499-8ad8-03b3e644548e', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', '''नेताजी ने आजाद हिंद फौज का गठन किया था।'' वाक्य में ''नेताजी'' किस संज्ञा का उदाहरण है?', 'जातिवाचक शब्द ''नेताजी'' केवल नेताजी सुभाष चंद्र बोस के अर्थ में रूढ़ होने के कारण व्यक्तिवाचक संज्ञा है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3d81a8f-d893-42e6-91b6-06f6ca9cabba', 'व्यक्तिवाचक संज्ञा का (क्योंकि ''नेता'' जातिवाचक संज्ञा होते हुए भी यहाँ केवल ''सुभाष चंद्र बोस'' के लिए रूढ़ है)', true, '8334b563-0457-4499-8ad8-03b3e644548e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89728814-2ca0-4b24-a953-45f9f4cb0ce3', 'जातिवाचक संज्ञा का', false, '8334b563-0457-4499-8ad8-03b3e644548e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('427c0738-87e5-4e40-bd42-930a16cc107b', 'भाववाचक संज्ञा का', false, '8334b563-0457-4499-8ad8-03b3e644548e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dea9ac2-51e2-4bb2-bbda-00b43228d1b3', 'समूहवाचक संज्ञा का', false, '8334b563-0457-4499-8ad8-03b3e644548e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2dae66b4-72bb-454c-aaf2-25ce16d900bc', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', 'निम्नलिखित वाक्यों में से किस वाक्य में ''भाववाचक संज्ञा'' का सही प्रयोग हुआ है?', '''मिठास'' और ''दया'' अमूर्त आंतरिक अनुभूतियाँ हैं, अतः वे शुद्ध भाववाचक संज्ञाएँ हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14fe732a-3ada-462c-8369-91aa1f913002', '''उसकी वाणी में अपार मिठास और हृदय में दया है।'' (''मिठास'' और ''दया'' भाववाचक संज्ञाएँ हैं)', true, '2dae66b4-72bb-454c-aaf2-25ce16d900bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7c6ff70-8e7e-4ddc-af9c-7616e5d7003a', '''वह रोज चार मीठे सेब खाता है।''', false, '2dae66b4-72bb-454c-aaf2-25ce16d900bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8b40c09-5b4e-48cc-b5a9-763a9e0b75c3', '''दुकानदार बहुत सारी मिठाइयाँ बेच रहा है।''', false, '2dae66b4-72bb-454c-aaf2-25ce16d900bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ece8d436-9ff4-43b7-b64a-d085baddafc2', '''मिठाई की दुकान खुली है।''', false, '2dae66b4-72bb-454c-aaf2-25ce16d900bc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c89a8197-d886-42a0-93e5-7c7538caa363', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', '''व्यक्तिवाचक संज्ञा'' और ''जातिवाचक संज्ञा'' में मूलभूत व्याकरणिक अंतर क्या है?', 'व्यक्तिवाचक संज्ञा अनन्य, अद्वितीय और विशिष्ट सत्ता की परिचायक है; जातिवाचक संज्ञा संपूर्ण समरूप वर्ग की सामान्य संज्ञा है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d37ad21c-a222-45f7-9551-564de12e609e', 'व्यक्तिवाचक संज्ञा एकवचनीय, अद्वितीय और विशिष्ट सत्ता का नाम होती है ; जबकि जातिवाचक संज्ञा संपूर्ण समजातीय वर्ग/श्रेणी का सामान्य नाम होती है और इसका बहुवचन बनाया जा सकता है', true, 'c89a8197-d886-42a0-93e5-7c7538caa363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68def654-7fe6-4d92-9f98-df39de53a4b5', 'व्यक्तिवाचक संज्ञा केवल जानवरों की होती है', false, 'c89a8197-d886-42a0-93e5-7c7538caa363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e620779e-f8bf-41be-af04-51c6bb26e403', 'जातिवाचक संज्ञा केवल मनुष्यों की होती है', false, 'c89a8197-d886-42a0-93e5-7c7538caa363');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd36b0ba-50e0-47c6-9974-ee07dd7e40ac', 'दोनों में कोई अंतर नहीं होता', false, 'c89a8197-d886-42a0-93e5-7c7538caa363');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b8af1eb-6568-4e54-b257-6c7b8a8e8ff7', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', '''अहं'' सर्वनाम से बनने वाली भाववाचक संज्ञा क्या होगी?', '''अहं'' संस्कृत सर्वनाम में ''कार'' प्रत्यय जुड़ने से भाववाचक संज्ञा ''अहंकार'' बनती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c39f426b-89bd-4c71-85fb-adab4415e637', 'अहंकार (अथवा अहंता)', true, '8b8af1eb-6568-4e54-b257-6c7b8a8e8ff7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('803ef00d-3ae6-47e1-a6bc-64814bdf381c', 'अहंकारी', false, '8b8af1eb-6568-4e54-b257-6c7b8a8e8ff7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f2672f3-f923-4735-bed8-a16e31bda020', 'अहंवादी', false, '8b8af1eb-6568-4e54-b257-6c7b8a8e8ff7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('851101de-90d3-4025-87fa-4f5a1a7f5ab3', 'अहंभावक', false, '8b8af1eb-6568-4e54-b257-6c7b8a8e8ff7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5fb7340-9138-41f9-932c-32051971dcc7', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', '''पुरुष'' जातिवाचक संज्ञा से बनने वाली शुद्ध भाववाचक संज्ञा क्या होगी?', '''पुरुष'' में ''अण्/य'' प्रत्यय से स्वर-वृद्धि होकर ''पौरुष'' तथा ''त्व'' प्रत्यय से ''पुरुषत्व'' बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac0ba640-50f3-47d7-a797-fb068edd4dcf', 'पौरुष (अथवा पुरुषत्व)', true, 'e5fb7340-9138-41f9-932c-32051971dcc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('150a969b-c5d7-4d16-bd36-f329d6c2f0c2', 'पुरुषार्थी', false, 'e5fb7340-9138-41f9-932c-32051971dcc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2654a784-7ee3-41a2-b1cd-b114b32495d8', 'पुरुषोत्तम', false, 'e5fb7340-9138-41f9-932c-32051971dcc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e54621a7-6b28-4b80-89e7-8631da6a0955', 'महापुरुष', false, 'e5fb7340-9138-41f9-932c-32051971dcc7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('311a39f7-7a17-4092-93db-5b351b3839fa', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', 'निम्नलिखित में से कौन-सा समूह केवल और केवल ''भाववाचक संज्ञाओं'' का है?', 'धैर्य, चतुराई, ईर्ष्या, सौंदर्य, वात्सल्य, करुणा - सभी अमूर्त आंतरिक गुण/भाव हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f3cbad4-60fb-4c95-97d2-db1acf2c5fbd', 'धैर्य, चतुराई, ईर्ष्या, सौंदर्य, वात्सल्य, करुणा', true, '311a39f7-7a17-4092-93db-5b351b3839fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ff1e9f0-020d-46d9-8893-76898f08683c', 'नदी, नगर, पर्वत, देश', false, '311a39f7-7a17-4092-93db-5b351b3839fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fbf47be-050c-47cd-b0c5-7966bcd76077', 'सोना, घी, तेल, दूध', false, '311a39f7-7a17-4092-93db-5b351b3839fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b4d883e-4497-4789-8f5f-c31a073b2ee9', 'कक्षा, सेना, सभा, दल', false, '311a39f7-7a17-4092-93db-5b351b3839fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('73f623f1-bcd0-409f-beae-e819ace894ff', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', '''शास्त्र'' जातिवाचक संज्ञा से बनने वाली सही भाववाचक संज्ञा क्या होगी?', 'शास्त्र + ईय = शास्त्रीय + ता = शास्त्रीयता (भाववाचक संज्ञा)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85204ad4-062e-4e0c-ae51-ccbdf32c44e2', 'शास्त्रीयता', true, '73f623f1-bcd0-409f-beae-e819ace894ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e4f738b-b2f6-4693-8227-72857c65230d', 'शास्त्रज्ञ', false, '73f623f1-bcd0-409f-beae-e819ace894ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f832589b-c04f-4733-9eb4-509f52ff879a', 'शास्त्रार्थ', false, '73f623f1-bcd0-409f-beae-e819ace894ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c95acd4-bcac-492f-aae4-a67bf1b2edaf', 'शास्त्रकार', false, '73f623f1-bcd0-409f-beae-e819ace894ff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7af3ba97-d13c-41ee-b4b3-0f5dfa7d4003', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', '''कुशल'' विशेषण से बनने वाली शुद्ध भाववाचक संज्ञा क्या होगी?', 'कुशल + अण् = कौशल (आदि-स्वर वृद्धि उ→औ) अथवा कुशल + ता = कुशलता।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60b1c02c-69c7-4a8b-a93b-a0fab2249906', 'कौशल (अथवा कुशलता)', true, '7af3ba97-d13c-41ee-b4b3-0f5dfa7d4003');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c6233a5-39ab-4fe4-813f-2e270609c356', 'कुशलतापूर्वक', false, '7af3ba97-d13c-41ee-b4b3-0f5dfa7d4003');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('844ee10f-c8b5-4298-8db2-e14f7f15a160', 'कुशलतापन', false, '7af3ba97-d13c-41ee-b4b3-0f5dfa7d4003');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb3609ec-b18f-47a9-92c5-54c2e6f87635', 'कुशली', false, '7af3ba97-d13c-41ee-b4b3-0f5dfa7d4003');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('298adea0-eccc-48b3-89ad-fd320138c45b', 'Class 7', 'Hindi Grammar', 'Chapter 6: संज्ञा और उसके भेद', 'Hard', 'संज्ञा (Noun) के सम्यक ज्ञान का संपूर्ण हिंदी भाषा और व्याकरण में क्या मूलभूत केंद्रीय स्थान है?', 'संज्ञा समूची भाषा का संज्ञानात्मक और व्यावहारिक मेरुदंड है, जो समस्त जगत की सत्ता को नाम और संप्रेषणीयता प्रदान करती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('197540f0-2733-4998-897a-fbd9c95ae129', 'संज्ञा भाषा का मूलभूत नामकरण-आधार (Nominal Backbone) है, जिसके बिना संसार की किसी भी सत्ता का प्रत्यक्षीकरण, विचार-संप्रेषण, वाक्य-रचना और अन्य विकारी पदों (सर्वनाम, विशेषण, क्रिया, कारक) का निर्धारण असंभव है', true, '298adea0-eccc-48b3-89ad-fd320138c45b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f238491a-dd43-4df4-bdf1-fb1752461d3a', 'संज्ञा केवल शब्दकोश का एक छोटा सा अंश है', false, '298adea0-eccc-48b3-89ad-fd320138c45b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc699908-45f4-4145-9675-e27966e78b32', 'संज्ञा का वाक्यों में कोई विशेष महत्व नहीं होता', false, '298adea0-eccc-48b3-89ad-fd320138c45b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9abfb85f-c9fc-4a7a-862c-f80eb04aa6e1', 'संज्ञा केवल बच्चों के सीखने के लिए होती है', false, '298adea0-eccc-48b3-89ad-fd320138c45b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e49520c5-4e70-4509-b9da-d233aae2004d', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'What is the fluid connective tissue in humans that transports oxygen, nutrients, hormones, and metabolic wastes throughout the body?', 'Blood is the primary circulating fluid comprising plasma, erythrocytes (RBCs), leukocytes (WBCs), and thrombocytes (platelets).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3428c42-0e7a-49fe-bb4e-1a1c6cc38ead', 'Blood', true, 'e49520c5-4e70-4509-b9da-d233aae2004d');
