INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('deaec897-a62e-4146-8b7c-7261c90d916a', 'Saliva', false, 'e49520c5-4e70-4509-b9da-d233aae2004d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8cbf2d4-4ec7-4a6b-9038-8a783cfbc4dc', 'Urine', false, 'e49520c5-4e70-4509-b9da-d233aae2004d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cbcb39cb-7663-4ea7-8542-306b7f4364f3', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'What is the straw-colored fluid matrix part of blood in which all blood cells are suspended?', 'Plasma is the liquid extracellular matrix containing 90–92% water, dissolved proteins, glucose, minerals, and waste products.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a44b6fe7-d917-42f8-acce-5fef5d0cc5f5', 'Plasma (constituting ~55% of blood volume)', true, 'cbcb39cb-7663-4ea7-8542-306b7f4364f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('192a2898-0a20-4cae-aa4e-01eee982367c', 'Hemoglobin', false, 'cbcb39cb-7663-4ea7-8542-306b7f4364f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad571469-b93d-49db-b5d8-c5b7d82d0fcd', 'Platelet', false, 'cbcb39cb-7663-4ea7-8542-306b7f4364f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d6eaee3-a7fe-4eb5-82a9-b015aacc7da1', 'Serum', false, 'cbcb39cb-7663-4ea7-8542-306b7f4364f3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4021cbc5-5010-4a91-bdd9-f4bcd0b78498', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'Which red iron-containing protein pigment in Red Blood Cells (RBCs) binds with Oxygen to carry it to all body cells?', 'Hemoglobin in RBCs binds O₂ to form oxyhemoglobin, imparting the characteristic red color to blood.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ade36e56-2e63-4a4e-9ade-da42db05c5ed', 'Hemoglobin', true, '4021cbc5-5010-4a91-bdd9-f4bcd0b78498');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dda4ccdc-7930-4f4d-a092-7cd87245fb9c', 'Chlorophyll', false, '4021cbc5-5010-4a91-bdd9-f4bcd0b78498');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe68f5ce-3dbf-4deb-84f0-c03471ca983a', 'Myoglobin', false, '4021cbc5-5010-4a91-bdd9-f4bcd0b78498');
