INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c91875d6-9bfb-4d60-8392-f63bb8b64ff6', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'Which blood cells act as the body''s immune soldiers, fighting and destroying disease-causing germs and foreign microbes?', 'White Blood Cells (Leukocytes) produce antibodies and perform phagocytosis to neutralize pathogens.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fec8126-ef76-4024-bb7e-6cc02eeff66f', 'White Blood Cells (WBCs / Leukocytes)', true, 'c91875d6-9bfb-4d60-8392-f63bb8b64ff6');
