INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f9539d4-acfe-4e0e-be31-f4b1dfa99cb5', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'Which cellular fragments in blood form a dark red clot over cuts and wounds to prevent excessive fatal bleeding?', 'Platelets initiate the coagulation cascade, forming fibrin mesh clots to seal broken blood vessels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13434476-a2f7-41bc-843f-06fa26789377', 'Platelets (Thrombocytes)', true, '0f9539d4-acfe-4e0e-be31-f4b1dfa99cb5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('594713c5-70ad-42b8-a31a-6cff6ce2a4e1', 'Red Blood Cells', false, '0f9539d4-acfe-4e0e-be31-f4b1dfa99cb5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa8cf946-fd4f-4ea2-8d40-bd9c5339f114', 'White Blood Cells', false, '0f9539d4-acfe-4e0e-be31-f4b1dfa99cb5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b903eb4e-6efb-4b6a-bf99-1a01792a62ef', 'Hemoglobin', false, '0f9539d4-acfe-4e0e-be31-f4b1dfa99cb5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03c8060d-b0d2-4fce-a41f-5f49279db1b9', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'Which blood vessels carry oxygen-rich blood away from the heart to all parts of the body under high pressure, having thick elastic walls?', 'Arteries possess thick, muscular, elastic walls to withstand pulsatile high hydrostatic systolic blood pressure from the heart.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6632444b-baed-4a9b-a4e2-194a0a8042dd', 'Arteries', true, '03c8060d-b0d2-4fce-a41f-5f49279db1b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22277057-9848-4f64-b311-19dcbb52f097', 'Veins', false, '03c8060d-b0d2-4fce-a41f-5f49279db1b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3aad1b09-a1b8-4063-816a-d14163c844ce', 'Capillaries', false, '03c8060d-b0d2-4fce-a41f-5f49279db1b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbf76a8a-6001-4546-bbb7-033687ac4af2', 'Vena Cava', false, '03c8060d-b0d2-4fce-a41f-5f49279db1b9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1646db0f-b5cb-4bac-9b95-5556ec7de77b', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'Which blood vessels carry carbon dioxide-rich deoxygenated blood from all organs back towards the heart, having internal VALVES to prevent backflow?', 'Veins are thin-walled, low-pressure vessels equipped with unidirectional semilunar valves ensuring forward blood flow to the heart.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89bce90e-e997-4a46-a552-797863f3c21a', 'Veins', true, '1646db0f-b5cb-4bac-9b95-5556ec7de77b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c2aec84-fff8-4167-b257-fc91e20cb7a7', 'Arteries', false, '1646db0f-b5cb-4bac-9b95-5556ec7de77b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57d485ce-9df5-40d3-891e-8eeccf1c9d28', 'Aorta', false, '1646db0f-b5cb-4bac-9b95-5556ec7de77b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f0a2ea4-e1d2-4d3c-95a6-df09b7f0ac9a', 'Capillaries', false, '1646db0f-b5cb-4bac-9b95-5556ec7de77b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5b95bd5c-d3cd-40c1-a772-21dab0ea3d1f', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'What is the rhythmic throbbing felt in the radial artery at the wrist caused by blood surging through arteries called?', 'The arterial pulse reflects ventricular systole; normal human resting pulse rate ranges between 72–80 bpm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e2dbef0-a65b-4dbd-bef7-25887705d5bf', 'Pulse (normal resting rate is 72 to 80 beats per minute)', true, '5b95bd5c-d3cd-40c1-a772-21dab0ea3d1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a04df53-714a-4aae-943e-78da155694ba', 'Blood Pressure', false, '5b95bd5c-d3cd-40c1-a772-21dab0ea3d1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3541d411-81d4-4ca5-9c79-074b24ed2985', 'Heart Murmur', false, '5b95bd5c-d3cd-40c1-a772-21dab0ea3d1f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3504f25-7475-4289-a196-3626a6c58817', 'Respiration', false, '5b95bd5c-d3cd-40c1-a772-21dab0ea3d1f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb2338c7-d364-4c54-b0fe-f050019d4eec', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'How many muscular pumping chambers are there in the human heart to prevent the mixing of oxygenated and deoxygenated blood?', 'The human heart has 4 chambers: Right/Left Atria and Right/Left Ventricles, partitioned by an interventricular septum.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4186c1ae-4127-481a-96e3-77ccd99aa0ff', '4 Chambers (Two upper Atria and two lower Ventricles separated by a muscular Septum)', true, 'bb2338c7-d364-4c54-b0fe-f050019d4eec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f931a2e8-35c2-4fa1-a3f1-260fc3281ad7', '2 Chambers', false, 'bb2338c7-d364-4c54-b0fe-f050019d4eec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2c2c4bc-bbac-4637-bf92-367534d252d8', '3 Chambers', false, 'bb2338c7-d364-4c54-b0fe-f050019d4eec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffb00c33-4407-4b95-ab09-43f84689a1eb', '6 Chambers', false, 'bb2338c7-d364-4c54-b0fe-f050019d4eec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fea4e978-e02a-4032-bbed-8151edb562f8', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'What medical acoustic instrument invented by René Laennec in 1816 is used by doctors to amplify and listen to heartbeat sounds?', 'A stethoscope uses a chest diaphragm, acoustic tube, and earpieces to auscultate cardiac valve closure sounds (Lub-Dub).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('525dad34-d2a5-4ee5-aeb0-8fa8606db552', 'Stethoscope', true, 'fea4e978-e02a-4032-bbed-8151edb562f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c85f770-93e2-42da-bdd5-29f650953c6a', 'Sphygmomanometer', false, 'fea4e978-e02a-4032-bbed-8151edb562f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d33390cb-8c25-4dce-ba70-464ab377f62a', 'Thermometer', false, 'fea4e978-e02a-4032-bbed-8151edb562f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24172673-e91d-4a3b-987f-44c641c762a8', 'Microscope', false, 'fea4e978-e02a-4032-bbed-8151edb562f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('75a318b1-2ac9-4e04-aad4-f6427e279dd8', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'Which specialized vascular conducting tissue transports Water and dissolved mineral nutrients UPWARDS from roots to leaves in plants?', 'Xylem vessels form a continuous microscopic hydraulic pipeline conducting water and minerals from soil to leaves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5430123-f046-4244-a5f6-8968f7586133', 'Xylem (Vascular tissue)', true, '75a318b1-2ac9-4e04-aad4-f6427e279dd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce30d356-7c29-4320-bd45-63cce68982c7', 'Phloem', false, '75a318b1-2ac9-4e04-aad4-f6427e279dd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d93b9227-5faf-4450-9ce7-21906783cc5a', 'Cortex', false, '75a318b1-2ac9-4e04-aad4-f6427e279dd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26738f69-386a-4b3e-80a7-1fa69c4a3581', 'Stomata', false, '75a318b1-2ac9-4e04-aad4-f6427e279dd8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('92f4bab9-7c4e-4c35-bac0-a2285362bde5', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Easy', 'Which vascular conducting tissue transports synthesized Food (sucrose/glucose) from the green leaves to all non-photosynthetic parts of the plant?', 'Phloem sieve tubes and companion cells translocate organic food bidirectional throughout the plant.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cba58b21-33e7-4dad-a4b8-275c846e5cb9', 'Phloem (Translocation)', true, '92f4bab9-7c4e-4c35-bac0-a2285362bde5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('519d7bb8-6704-4ea4-ae56-be1e708ac718', 'Xylem', false, '92f4bab9-7c4e-4c35-bac0-a2285362bde5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42f86cf7-8d58-41e6-ae18-2f2f53e9ef82', 'Root hairs', false, '92f4bab9-7c4e-4c35-bac0-a2285362bde5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15304009-19b6-4ecf-8f6e-37c8f83e4e91', 'Epidermis', false, '92f4bab9-7c4e-4c35-bac0-a2285362bde5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6cc84136-888d-4c82-96ac-10e0cc11e678', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'Which is the ONLY artery in the human body that carries DEOXYGENATED (CO₂-rich) blood?', 'By definition, arteries carry blood away from the heart; the pulmonary artery delivers deoxygenated venous blood to pulmonary alveoli.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69337241-3530-4dde-81ec-08625792ebff', 'The Pulmonary Artery (carries deoxygenated blood from the right ventricle to the lungs)', true, '6cc84136-888d-4c82-96ac-10e0cc11e678');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('844e9781-8ce1-4836-be47-f4701243f98b', 'The Aorta', false, '6cc84136-888d-4c82-96ac-10e0cc11e678');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e96b7e46-aba4-4eb3-90f1-c8eaf82f96a2', 'The Renal Artery', false, '6cc84136-888d-4c82-96ac-10e0cc11e678');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1509c611-4d73-4802-a638-5f27621fe8c4', 'The Carotid Artery', false, '6cc84136-888d-4c82-96ac-10e0cc11e678');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5111a94a-919c-4682-ac69-b6ea0c5f968e', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'Which is the ONLY vein in the human body that carries OXYGENATED (O₂-rich) blood?', 'Pulmonary veins drain oxygenated blood from pulmonary capillaries directly into the left atrium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88686bed-8aca-4eea-a9d7-d6c3823828f9', 'The Pulmonary Vein (carries oxygenated blood from the lungs back to the left atrium of the heart)', true, '5111a94a-919c-4682-ac69-b6ea0c5f968e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('356d87e8-b5dd-4650-8338-8d3b90d2cee0', 'The Superior Vena Cava', false, '5111a94a-919c-4682-ac69-b6ea0c5f968e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a77b12d-c78b-4d47-95c7-a1b014965ac7', 'The Inferior Vena Cava', false, '5111a94a-919c-4682-ac69-b6ea0c5f968e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0aed0da-4a9c-4f03-b5b5-341999978497', 'The Jugular Vein', false, '5111a94a-919c-4682-ac69-b6ea0c5f968e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('735995ae-2826-454d-a807-1316057e985d', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What are the microscopic, extremely thin single-cell-walled blood vessels connecting arterioles to venules, where diffusion of gases, glucose, and wastes occurs?', 'Capillaries have single-cell endothelial walls (diameter ~7-8 µm) permitting rapid nutrient, waste, and gas exchange.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11e0e832-ded7-45c5-9ff6-d0f8b82525fa', 'Capillaries', true, '735995ae-2826-454d-a807-1316057e985d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81031ece-ee45-4179-907e-a63f2a38e9ae', 'Arteries', false, '735995ae-2826-454d-a807-1316057e985d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52150e4b-bdbf-42eb-bddf-9169753a133e', 'Veins', false, '735995ae-2826-454d-a807-1316057e985d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('216694e0-262b-40f3-b8a3-e67f9b7e4e40', 'Aorta', false, '735995ae-2826-454d-a807-1316057e985d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('311a7c7a-4e42-45fb-b323-3c79839d41bf', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What is the biological mechanism of ''Transpiration'' in plants and what vital cooling/suction force does it generate?', 'Transpiration generates negative hydrostatic tension (transpirational pull / cohesion-tension theory) elevating sap through xylem.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a837d4d4-0247-4e18-9d67-5b3059cff1d2', 'Evaporation of water vapor through stomata creates a continuous negative suction pressure (Transpirational Pull) that pulls water hundreds of feet high in tall trees while cooling the foliage', true, '311a7c7a-4e42-45fb-b323-3c79839d41bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76fc4f5c-af4c-43b5-a546-0e789de84f59', 'Absorption of carbon dioxide by roots', false, '311a7c7a-4e42-45fb-b323-3c79839d41bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('762ea6a7-d7e1-4ba1-ad96-5af467a029f6', 'Release of oxygen into the soil', false, '311a7c7a-4e42-45fb-b323-3c79839d41bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('648be37d-a47e-438a-abb0-2e66e8ca982a', 'Transport of sugars to roots', false, '311a7c7a-4e42-45fb-b323-3c79839d41bf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66187e60-af1c-4542-93a6-5c7897263d67', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What is the main toxic nitrogenous excretory waste filtered and removed from human blood by the Kidneys?', 'Human excretion is ureotelic: hepatic deamination converts toxic ammonia into urea, which is cleared by renal filtration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9922662a-5e85-486e-88f5-0569c601e648', 'Urea', true, '66187e60-af1c-4542-93a6-5c7897263d67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b4072ba-0566-498a-b346-4262e0d42019', 'Uric Acid only', false, '66187e60-af1c-4542-93a6-5c7897263d67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6548c4e9-881b-4ae1-a4f4-d54503bf5abd', 'Ammonia gas only', false, '66187e60-af1c-4542-93a6-5c7897263d67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a078678-acc3-4abc-866c-80a58d23acfe', 'Carbon Dioxide', false, '66187e60-af1c-4542-93a6-5c7897263d67');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b1a1919-369a-4eac-a626-4d7f677e4755', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What is the average normal chemical composition of human Urine excreted by a healthy adult (approx. 1.0 to 1.8 liters per day)?', 'Normal urine consists of ~95% water, 2.5% urea, and 2.5% dissolved mineral ions (sodium, potassium, creatinine, phosphates).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5f72858-ed24-451c-811d-8f063bb71580', '95% Water, 2.5% Urea, and 2.5% other metabolic waste salts and minerals', true, '6b1a1919-369a-4eac-a626-4d7f677e4755');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b127886-7569-45f2-b049-803e5be88d4e', '50% Water and 50% Sugar', false, '6b1a1919-369a-4eac-a626-4d7f677e4755');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b613104-1a7e-4ba0-8fc3-9d94fe711e70', '100% pure Water', false, '6b1a1919-369a-4eac-a626-4d7f677e4755');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7da779f9-e01f-4431-ae11-23f97c07d460', '90% Acid and 10% Blood', false, '6b1a1919-369a-4eac-a626-4d7f677e4755');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b3221bfd-022d-4a88-905c-8f6ef62714a0', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What is the correct pathway of Urine from formation to discharge in the human excretory system?', 'Renal glomeruli filter blood → nephron tubules drain into ureters → stored in urinary bladder → voided via urethra.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3eb8da58-3eab-4612-9394-9dad973bf5cd', 'Kidneys -> Ureters (muscular tubes) -> Urinary Bladder (storage pouch) -> Urethra (muscular exit opening)', true, 'b3221bfd-022d-4a88-905c-8f6ef62714a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f928afb6-9fad-43f8-96e5-1bdb012d7382', 'Kidneys -> Urethra -> Bladder -> Ureters', false, 'b3221bfd-022d-4a88-905c-8f6ef62714a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56ed0bde-db03-4ef1-ab79-169ec7e959bf', 'Bladder -> Kidneys -> Ureters -> Urethra', false, 'b3221bfd-022d-4a88-905c-8f6ef62714a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecbe16ad-3d4f-404f-92c5-04946b9891c9', 'Ureters -> Kidneys -> Bladder -> Urethra', false, 'b3221bfd-022d-4a88-905c-8f6ef62714a0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e37c7522-15a9-4f40-8037-0b76904c88e2', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What is the medical procedure of ''Dialysis'' used when a patient experiences acute or chronic Renal (Kidney) Failure?', 'Hemodialysis circulates patient blood through dialyzer semi-permeable cartridges to clear metabolic toxins and normalize electrolytes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1abae3b5-3793-4fba-9621-ddd2dfb758ca', 'An artificial kidney machine periodically filters toxic nitrogenous wastes, urea, and excess salts from the patient''s blood through semi-permeable membranes', true, 'e37c7522-15a9-4f40-8037-0b76904c88e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a75fdd7-692e-43ca-9778-219e613ca088', 'Injecting water directly into the heart', false, 'e37c7522-15a9-4f40-8037-0b76904c88e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e147fde-01ca-4c3e-97f2-4ad9fca8c10f', 'Pumping oxygen into the stomach', false, 'e37c7522-15a9-4f40-8037-0b76904c88e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ae95ca5-c4bb-41ac-8313-fba15ebb03c0', 'A surgery to replace bones', false, 'e37c7522-15a9-4f40-8037-0b76904c88e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('70724261-1b0c-41ed-a3cc-19251d0d6f82', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'Why do we develop white salty patches on our cotton clothes under the armpits on hot summer days?', 'Eccrine sweat evaporation cools the epidermis (latent heat of vaporization), leaving solute sodium chloride residues on clothing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8692f768-5026-4fa5-8b30-515fe4f75f4e', 'Sweat glands secrete sweat containing water and dissolved mineral SALTS (NaCl) ; as water evaporates to cool the body, white solid salt crystals are left behind on fabric', true, '70724261-1b0c-41ed-a3cc-19251d0d6f82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38f7cadb-b86d-4cfd-9175-41f2b1d632ff', 'Dust settles from the ceiling', false, '70724261-1b0c-41ed-a3cc-19251d0d6f82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9236e52-6ce0-482d-b8a8-6f5c14486c6f', 'The cloth bleach dissolves', false, '70724261-1b0c-41ed-a3cc-19251d0d6f82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2dc6b7b-78d7-4e14-9365-8d0132a88c85', 'Bacteria produce salt', false, '70724261-1b0c-41ed-a3cc-19251d0d6f82');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da6188c9-c38b-43e9-b230-eac786e20491', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'Why do simple aquatic organisms like Sponges (Porifera) and Hydra NOT possess any specialized circulatory system or blood?', 'Sponges and Hydra have diploblastic body plans where ambient aquatic currents directly service cellular diffusion without vascular tissue.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4b2dc16-9978-449b-9039-59703b9563cc', 'Water circulating through their porous body cavities continuously brings food and oxygen directly to all cells and washes away carbon dioxide and waste products', true, 'da6188c9-c38b-43e9-b230-eac786e20491');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3a89abc-c902-4040-8fb9-50133cee976c', 'Because they have no cells', false, 'da6188c9-c38b-43e9-b230-eac786e20491');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f96dee7-3111-4765-a74e-7f6a88e43a35', 'Because they live in trees', false, 'da6188c9-c38b-43e9-b230-eac786e20491');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba55c8e6-a04b-4681-b560-c79b57cb756e', 'Because they produce pure gold', false, 'da6188c9-c38b-43e9-b230-eac786e20491');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5aeffdc7-5d15-427b-bc24-28d9fc6f125b', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'How do Root Hairs in plants increase the absorption of water and dissolved minerals from the soil?', 'Unicellular root hair extensions amplify root surface area thousands-fold, driving water uptake via osmotic potential gradients.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4def370-e933-41f3-af77-11748d22e69d', 'They massively increase the total surface area of root epidermal contact with soil capillary water films, facilitating rapid Osmosis', true, '5aeffdc7-5d15-427b-bc24-28d9fc6f125b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae007cf3-bccb-4bfd-b04d-a441b8af5ed9', 'They drill deep holes like metal drills', false, '5aeffdc7-5d15-427b-bc24-28d9fc6f125b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68798c4b-9b1e-48ce-a575-a99a826cdb72', 'They produce heat to melt soil', false, '5aeffdc7-5d15-427b-bc24-28d9fc6f125b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7ae4161-460c-4de6-9004-2afd96f66eff', 'They turn soil into sand', false, '5aeffdc7-5d15-427b-bc24-28d9fc6f125b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6fb62c73-ca06-4f6f-b9d3-6f22c770a7e6', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'In what form do Birds, Lizards, and Snakes (terrestrial reptiles) excrete nitrogenous waste to conserve precious body water?', 'Uricotelic adaptation: birds and reptiles precipitate non-toxic insoluble uric acid paste to minimize evaporative water loss.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41c5039c-f421-4cbc-a139-3e9d519ff028', 'Semi-solid white paste composed of insoluble URIC ACID', true, '6fb62c73-ca06-4f6f-b9d3-6f22c770a7e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc69bc88-5477-43bd-a789-f125c74bf9fa', 'Liquid ammonia in large water volume', false, '6fb62c73-ca06-4f6f-b9d3-6f22c770a7e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b363a53-3567-4584-b109-f651358f3ff8', 'Liquid urea', false, '6fb62c73-ca06-4f6f-b9d3-6f22c770a7e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2288003-bf13-4cf9-aa99-a11b8d1aa91c', 'Dry carbon powder', false, '6fb62c73-ca06-4f6f-b9d3-6f22c770a7e6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62b4fef8-3f74-4ec8-a404-73e17fce1bd8', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'In what form do aquatic freshwater Fish excrete their nitrogenous waste directly into surrounding water?', 'Ammonotelic fish diffuse toxic ammonia directly across branchial gill membranes into the surrounding aquatic sink.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0187954f-31f0-4ce0-9743-508a859fa517', 'Readily soluble gaseous AMMONIA (Ammonotelic excretion)', true, '62b4fef8-3f74-4ec8-a404-73e17fce1bd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec5ed49f-6b71-45ba-8d65-1d221435e934', 'Insoluble uric acid crystals', false, '62b4fef8-3f74-4ec8-a404-73e17fce1bd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c8b71e5-714b-4265-83e7-ccf9689b0aa4', 'Solid urea pellets', false, '62b4fef8-3f74-4ec8-a404-73e17fce1bd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11d34d60-46fb-4bdc-9422-8dfd419de66e', 'Gaseous nitrogen', false, '62b4fef8-3f74-4ec8-a404-73e17fce1bd8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ee203d10-ae1e-4929-a3ac-2b3e51bb24fd', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What is the primary function of the ''Septum'' dividing the left and right halves of the human heart?', 'The cardiac septum enforces complete separation of pulmonary and systemic circulations, maximizing arterial oxygen saturation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d292f8d7-7700-4b78-84a2-12672b7199d4', 'It acts as a complete muscular dividing wall preventing oxygen-rich blood on the left side from mixing with carbon dioxide-rich blood on the right side', true, 'ee203d10-ae1e-4929-a3ac-2b3e51bb24fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c91d1ef-dc57-4d78-a93d-75e354c3170f', 'It filters water from blood', false, 'ee203d10-ae1e-4929-a3ac-2b3e51bb24fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14e9dbba-7452-4ace-bed9-d710d004a756', 'It cools the heart muscle', false, 'ee203d10-ae1e-4929-a3ac-2b3e51bb24fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('918d4137-8375-49fb-86a8-37ed4e799bc7', 'It produces new red blood cells', false, 'ee203d10-ae1e-4929-a3ac-2b3e51bb24fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52f4c8c5-715b-4028-9afc-723aa9f1d079', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What makes the ''Lub-Dub'' sound heard through a stethoscope during each complete cardiac cycle?', 'First heart sound S₁ (''Lub'') = AV (tricuspid/mitral) valve closure; Second sound S₂ (''Dub'') = semilunar (aortic/pulmonic) valve closure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1084c681-ce80-4670-a492-e39eca25371b', 'The rhythmic, rapid closure of cardiac valves (Atrioventricular valves snapping shut for ''Lub'', and Semilunar aortic/pulmonary valves for ''Dub'')', true, '52f4c8c5-715b-4028-9afc-723aa9f1d079');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0b126ad-6127-44f4-98e5-091beb66c7ce', 'Blood splashing against the ribs', false, '52f4c8c5-715b-4028-9afc-723aa9f1d079');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8468fd6-6206-4fa2-bec9-4b795a3c17df', 'Air rushing into the lungs', false, '52f4c8c5-715b-4028-9afc-723aa9f1d079');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a379e74d-0b4a-4348-b0bc-af6ff71efd65', 'The heart rubbing against the stomach', false, '52f4c8c5-715b-4028-9afc-723aa9f1d079');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a37568a3-f6f6-4661-907e-23a09d6e5e03', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Medium', 'What happens when a leafy balsam plant stem is kept in water colored with Red Ink (Eosin) for a few hours?', 'Classic xylem transport demonstration: capillary xylem tracheary elements conduct eosin dye upwards into leaf petiole veins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48e3d967-82c3-40ef-852e-eb4215315dcf', 'The red colored water travels UPWARDS through the Xylem vessels, staining the stem vascular bundles and leaf veins distinctly red', true, 'a37568a3-f6f6-4661-907e-23a09d6e5e03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06e21f3e-74d7-4986-9606-d5d623e0090c', 'The leaves turn completely black', false, 'a37568a3-f6f6-4661-907e-23a09d6e5e03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a505fa42-a81c-432c-ba73-a11bc0c5ffc1', 'The plant catches fire', false, 'a37568a3-f6f6-4661-907e-23a09d6e5e03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c19e21a6-ce94-44c1-9323-53a30a9ad380', 'The roots dissolve', false, 'a37568a3-f6f6-4661-907e-23a09d6e5e03');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b599a760-54fb-4807-9204-d19f315d68d4', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bd37dab-c821-4e0b-87a2-f04316fbc4be', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'b599a760-54fb-4807-9204-d19f315d68d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebca02b5-4a26-4c24-b578-030960218911', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'b599a760-54fb-4807-9204-d19f315d68d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d70a54b-2f1e-487d-826c-f9a10d348144', '(A) is true, but (R) is false.', false, 'b599a760-54fb-4807-9204-d19f315d68d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8464a50e-93b6-41d6-a8aa-f0d22e36d628', '(A) is false, but (R) is true.', false, 'b599a760-54fb-4807-9204-d19f315d68d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1af3b915-85ee-42dc-ba9f-e9500b5257f4', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'Spot the IMPOSTER in the following group of Nitrogenous Excretory Products and their animal classifications:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73886a6c-0711-4b01-a4ad-ddaae28d7ee5', 'Classification 1', false, '1af3b915-85ee-42dc-ba9f-e9500b5257f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12a11244-faf8-4c4b-9c5e-8332b08b0b74', 'Classification 2', false, '1af3b915-85ee-42dc-ba9f-e9500b5257f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad352d3f-084e-4ee1-af5e-ddbdf16516be', 'Classification 3', false, '1af3b915-85ee-42dc-ba9f-e9500b5257f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d3df4ca-c780-42db-b380-486b518e683a', 'Classification 4 (Frogs and Earthworms excrete Urea and Ammonia, NEVER gold)', true, '1af3b915-85ee-42dc-ba9f-e9500b5257f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('736d5451-56ef-46a7-b823-ee5082bae4a1', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'Trace the EXACT pathway of deoxygenated blood entering the human heart from body tissues until it leaves as oxygenated blood for systemic distribution:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a742892b-3ef2-4cee-9842-046fc26b3066', 'The LEFT VENTRICLE (which pumps oxygenated blood under immense pressure into the systemic Aorta)', true, '736d5451-56ef-46a7-b823-ee5082bae4a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58245cfd-ec60-4f57-894a-c976e61de688', 'The Right Atrium', false, '736d5451-56ef-46a7-b823-ee5082bae4a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('274064cb-664d-4d8d-9786-f4cebc64a99f', 'The Left Atrium', false, '736d5451-56ef-46a7-b823-ee5082bae4a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69bf7349-3364-46f1-888b-74c0dbaadf94', 'The Right Ventricle', false, '736d5451-56ef-46a7-b823-ee5082bae4a1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('529c591e-8a37-4a7d-bfb2-b58b0ad965ea', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'Match Column I (Vascular / Circulatory Components) with Column II (Physiological Functions):
(a) Xylem Tracheids & Vessels -> (i) Unidirectional upward conduction of water & minerals via transpirational tension
(b) Phloem Sieve Tubes         -> (ii) Bidirectional translocation of synthesized sucrose/photosynthates
(c) Blood Platelets            -> (iii) Hemostasis and thromboplastin cascade for clot formation
(d) Renal Nephrons             -> (iv) Ultrafiltration and selective reabsorption to produce urine', 'Xylem = water tension; Phloem = food translocation; Platelets = coagulation; Nephrons = renal filtration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15e5f959-665b-4326-8b40-815714b8a99c', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '529c591e-8a37-4a7d-bfb2-b58b0ad965ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65e4e6b4-8e7e-479a-8542-dbf597479223', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '529c591e-8a37-4a7d-bfb2-b58b0ad965ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c680e51-9f3b-4f6d-a602-a4a3d6795d90', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '529c591e-8a37-4a7d-bfb2-b58b0ad965ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e4d4031-d90d-40b7-af58-33c996b5650f', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '529c591e-8a37-4a7d-bfb2-b58b0ad965ea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b517134-0e68-417f-83ad-db810c385cb9', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'Read the statements regarding physiological transport in plants:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a08f5fe9-8518-47b7-9d5c-628ad1e036b0', 'Statements 1 and 2 only', true, '9b517134-0e68-417f-83ad-db810c385cb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dae6572-e803-4111-8543-60ae92f7b5b5', 'Statements 2 and 3 only', false, '9b517134-0e68-417f-83ad-db810c385cb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('280e1811-0de3-43ae-84e5-1a175be2eb61', 'Statements 1 and 3 only', false, '9b517134-0e68-417f-83ad-db810c385cb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e702d051-84cd-45f3-b879-b1b8dbed762c', 'All Statements 1, 2, and 3', false, '9b517134-0e68-417f-83ad-db810c385cb9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c93b40e0-40cd-485b-ae02-2e406e13679f', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'What physical-chemical properties of water molecules explain how tall redwood trees sustain unbroken water columns in xylem without snapping under massive tension?', 'Dixon-Joly Cohesion-Tension theory: hydrogen bonding provides immense tensile strength (>100 atm) resisting cavitation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45f6744c-4dd5-49fc-8148-1fb91e1ed782', 'Cohesion (mutual attraction between water molecules) and Adhesion (attraction between water molecules and hydrophilic xylem cellulose walls)', true, 'c93b40e0-40cd-485b-ae02-2e406e13679f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7388818d-54dd-4c5f-8086-86b508d40c74', 'Water molecules turning into ice inside the stem', false, 'c93b40e0-40cd-485b-ae02-2e406e13679f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('418cb0f9-e0ac-4889-837f-7d4448e6fdd3', 'Magnetic attraction between roots and clouds', false, 'c93b40e0-40cd-485b-ae02-2e406e13679f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bca7a310-8e4f-47b7-aa99-724f2c28b41c', 'Air bubbles pushing the water', false, 'c93b40e0-40cd-485b-ae02-2e406e13679f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e167c873-a080-402f-b8d7-2d73f74135f0', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'Why is William Harvey (1578–1657) celebrated as a founding father of modern physiology for his discovery of blood circulation?', 'Harvey''s ''De Motu Cordis'' (1628) established closed unidirectional hemodynamics driven by mechanical ventricular pumping.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec39d394-4310-4762-a51b-6d1afe3cefbf', 'He disproved Galen''s 1,400-year doctrine by experimentally demonstrating that the heart acts as a muscular pump circulating a fixed volume of blood unidirectionally through closed circuits of arteries and veins', true, 'e167c873-a080-402f-b8d7-2d73f74135f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5de8e8aa-f219-46da-9a79-10430f61aa78', 'He invented blood transfusions in 1500', false, 'e167c873-a080-402f-b8d7-2d73f74135f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20b62931-8389-4945-b6c8-0e71aefb7417', 'He discovered that blood has no cells', false, 'e167c873-a080-402f-b8d7-2d73f74135f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecd8ed91-6d0c-48b3-8d2d-f95b3a696914', 'He proved that the liver pumps blood to the lungs', false, 'e167c873-a080-402f-b8d7-2d73f74135f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9308304f-c709-4955-bdbf-d095351e4413', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'Consider four physiological events:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0f6024e-4900-4a2c-b03e-0319e3c9adc9', 'All 1, 2, 3, and 4', true, '9308304f-c709-4955-bdbf-d095351e4413');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68b40015-cd32-4b95-93d5-d3d413be9887', '1 and 2 only', false, '9308304f-c709-4955-bdbf-d095351e4413');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('725abd6d-b732-4eb8-9023-00f0f6d31f0b', '3 and 4 only', false, '9308304f-c709-4955-bdbf-d095351e4413');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('955ff847-8bb3-477b-853f-dcb53d3d03a4', '1 and 3 only', false, '9308304f-c709-4955-bdbf-d095351e4413');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf90e92f-115c-4dd0-a1fa-ec2e0f584481', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'What happens during ''Kidney Dialysis'' when blood is drawn from a patient''s radial artery?', 'Dialysis relies on concentration gradients across semi-permeable cellophane: metabolic wastes diffuse into dialysate while cellular components return safely.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff5c96d5-2305-417d-9639-520d13a789c0', 'Blood is mixed with an anticoagulant (heparin), passed through dialyzing cellophane tubes bathed in isotonic dialyzing fluid lacking nitrogenous wastes, where urea diffuses out, and purified blood is returned via a vein', true, 'cf90e92f-115c-4dd0-a1fa-ec2e0f584481');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92fcf1e3-2496-4e10-81f3-18da0c6fbdf9', 'Blood is boiled to kill germs', false, 'cf90e92f-115c-4dd0-a1fa-ec2e0f584481');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e909b2c-040b-4d21-9d35-1468b292f759', 'Blood is replaced entirely with water', false, 'cf90e92f-115c-4dd0-a1fa-ec2e0f584481');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9655196d-8fb8-4d4e-acf4-2c1b954e7246', 'All white blood cells are removed permanently', false, 'cf90e92f-115c-4dd0-a1fa-ec2e0f584481');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91798953-117a-4b01-bf7d-428156294db2', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'Why does the left side of the heart handle ONLY oxygenated blood while the right side handles ONLY deoxygenated blood in mammals and birds?', 'Endothermic homeothermy demands high ATP turnover, requiring complete separation of systemic and pulmonary hemodynamics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c12a5de0-cead-4eef-8de6-b5de1315b75d', 'High metabolic rates of warm-blooded endotherms require maximum oxygen supply to generate cellular body heat and sustain constant body temperature', true, '91798953-117a-4b01-bf7d-428156294db2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec40b16a-650d-4972-9899-2e6e02a31bde', 'Because mammals have no veins', false, '91798953-117a-4b01-bf7d-428156294db2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff553c7a-fe1a-4035-b1d0-e28a3be5aa29', 'Because birds have no lungs', false, '91798953-117a-4b01-bf7d-428156294db2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15d5a06d-fb6d-4caf-86a5-6fd8782e4484', 'To keep the lungs cold', false, '91798953-117a-4b01-bf7d-428156294db2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8e9fc01-5c17-4530-b097-d38cfd0a3a94', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'What would happen to a plant if all its Phloem tissue were carefully removed in a continuous ring around the stem (Girdling / Ringing experiment)?', 'Malpighi''s girdling experiment proves phloem translocates carbohydrates: removing the phloem ring starves root parenchyma, collapsing active ion uptake.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2be310df-84e3-4c18-abc2-9b62b8e00818', 'Photosynthesized sugars cannot reach the subterranean roots; the roots starve and die first, followed by the death of the entire plant', true, 'e8e9fc01-5c17-4530-b097-d38cfd0a3a94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acd4378f-e4cf-4159-b7ab-439e712982d2', 'The plant grows twice as fast', false, 'e8e9fc01-5c17-4530-b097-d38cfd0a3a94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc8c0488-f3c5-46a4-95cc-88de1de47aae', 'Water immediately stops reaching the leaves', false, 'e8e9fc01-5c17-4530-b097-d38cfd0a3a94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12159ab7-76c6-44e2-9bce-0dc7a5a90667', 'The leaves turn into flowers', false, 'e8e9fc01-5c17-4530-b097-d38cfd0a3a94');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecf7a60b-7489-437e-8e82-86388493d7e0', 'Class 7', 'Science', 'Chapter 7: Transportation in Animals and Plants', 'Hard', 'What overarching biological principle is established in Chapter 7 of NCERT Class 7 Science?', 'Chapter 7 synthesizes organismal transport and excretion: convective hemodynamics, renal ultrafiltration, and botanical vascular sap translocation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f0f2804-6ef4-4867-9fb4-12ce3f3783bf', 'Complex multicellular organisms require specialized vascular internal transport networks (blood circulation and plant vascular bundles) and waste excretion systems to maintain cellular homeostasis, nutrient delivery, and metabolic balance across trillions of cells', true, 'ecf7a60b-7489-437e-8e82-86388493d7e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fc8673d-cbc9-436f-a6ac-5e793311721c', 'That small animals do not need any food', false, 'ecf7a60b-7489-437e-8e82-86388493d7e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e867b7c-b245-46d7-846a-87bc333648da', 'That plants have hearts like mammals', false, 'ecf7a60b-7489-437e-8e82-86388493d7e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a191fc5-508a-45e8-ac6c-4c49e636b5b8', 'That blood only moves when humans run', false, 'ecf7a60b-7489-437e-8e82-86388493d7e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('57607850-5513-4fe6-8e1a-3c71819a90b1', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'Find the Ratio of 5 m to 10 km in its simplest form:', 'Units must match: 10 km = 10,000 m. Ratio = 5 m : 10,000 m = 1 : 2000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87fc6454-834e-409b-a614-21287bbffc12', '1 : 2000 (10 km = 10,000 m ; 5 / 10,000 = 1 / 2000)', true, '57607850-5513-4fe6-8e1a-3c71819a90b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5972eab2-f74e-40c2-982e-d28766aa16d9', '1 : 2', false, '57607850-5513-4fe6-8e1a-3c71819a90b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cec6e76-ce94-47d7-ada6-f04c74392926', '1 : 200', false, '57607850-5513-4fe6-8e1a-3c71819a90b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bebd118-3c9a-452a-b435-a352e5ad36f9', '1 : 20', false, '57607850-5513-4fe6-8e1a-3c71819a90b1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36a0dce4-4115-4fb5-b752-1a6cb6eb2fc6', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'Find the Ratio of 50 paise to Rs 5 in its simplest form:', 'Rs 5 = 500 paise. Ratio = 50 : 500 = 1 : 10.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0ea5a29-ce2f-4a5a-ab33-34dc11b79012', '1 : 10 (Rs 5 = 500 paise ; 50 / 500 = 1 / 10)', true, '36a0dce4-4115-4fb5-b752-1a6cb6eb2fc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35e2a766-08db-4329-b17b-34829bf12e33', '1 : 100', false, '36a0dce4-4115-4fb5-b752-1a6cb6eb2fc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7d71d41-9ee9-4bab-8df5-e01d3d4bbd03', '1 : 5', false, '36a0dce4-4115-4fb5-b752-1a6cb6eb2fc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a74dcf6e-a122-4498-893d-8e33352e849a', '10 : 1', false, '36a0dce4-4115-4fb5-b752-1a6cb6eb2fc6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f15386e-b6e3-4203-8f0b-a3a465124ad2', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'Convert the fraction 3/4 into a Percentage:', 'Fraction to percentage: (3/4) × 100% = 75%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d7c688e-0e29-45a6-8547-9e8f363c83b3', '75% ((3 / 4) × 100% = 75%)', true, '4f15386e-b6e3-4203-8f0b-a3a465124ad2');
