INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b6d3a16-dee4-4e0b-ba79-e112fac969ac', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'Convert 65% into a Fraction in its simplest reduced form:', '65% = 65/100 = 13/20.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c6d1645-9e26-43e2-9c61-b021eef26156', '13/20 (65 / 100 = 13 / 20)', true, '2b6d3a16-dee4-4e0b-ba79-e112fac969ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1b9d378-93b7-4627-89c1-5d8ccfdb116f', '13/25', false, '2b6d3a16-dee4-4e0b-ba79-e112fac969ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d014560c-16a3-4c18-a3a1-3b1e7d53d22e', '65/10', false, '2b6d3a16-dee4-4e0b-ba79-e112fac969ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f757fd1-5f2e-47ee-b3f8-6a816c553463', '3/5', false, '2b6d3a16-dee4-4e0b-ba79-e112fac969ac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc434f6b-5d71-4189-8c57-575203a149ef', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'Find 15% of 250:', '15% of 250 = 0.15 × 250 = 37.5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a7cf798-f98a-4bda-b313-b801591b2580', '37.5 ((15 / 100) × 250 = 37.5)', true, 'fc434f6b-5d71-4189-8c57-575203a149ef');
