INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6442a832-8f10-4bd4-82d6-f33965614ff0', '32.5', false, 'fc434f6b-5d71-4189-8c57-575203a149ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed01663c-2312-4c7b-8dc8-1fee35e993b8', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'Convert the decimal 0.65 into a Percentage:', '0.65 × 100% = 65%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c497a59b-5990-49a4-a8c2-5d8562e0844c', '65% (0.65 × 100% = 65%)', true, 'ed01663c-2312-4c7b-8dc8-1fee35e993b8');
