INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62d59b86-394d-4c31-b542-e058e918e404', '650%', false, 'ed01663c-2312-4c7b-8dc8-1fee35e993b8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14fd560b-c326-4ef6-8fab-83ad94b0f7e2', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'If Selling Price (SP) is GREATER than Cost Price (CP), the transaction results in a:', 'When SP > CP, there is a profit: Profit = SP - CP.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d66b61d-8545-4a44-83ed-e9152d797fa2', 'Profit (Profit = SP - CP)', true, '14fd560b-c326-4ef6-8fab-83ad94b0f7e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6abd6cfd-6486-4332-b3b6-0aaf3eafd3ad', 'Loss (Loss = CP - SP)', false, '14fd560b-c326-4ef6-8fab-83ad94b0f7e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3858e18f-a412-4b7a-a03f-b82a09deb9a3', 'No Profit No Loss', false, '14fd560b-c326-4ef6-8fab-83ad94b0f7e2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9575ec67-7326-4b5d-b943-ac343e89b028', 'Discount', false, '14fd560b-c326-4ef6-8fab-83ad94b0f7e2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('65abb4cd-e9b8-4507-a263-3f2cdc186b3a', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'If Cost Price (CP) is GREATER than Selling Price (SP), the transaction results in a:', 'When CP > SP, the seller incurs a loss: Loss = CP - SP.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('486b849a-83b7-4248-b58f-e77d7697e47f', 'Loss (Loss = CP - SP)', true, '65abb4cd-e9b8-4507-a263-3f2cdc186b3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6866ef5e-3245-422c-ba3e-a539d8105f5e', 'Profit', false, '65abb4cd-e9b8-4507-a263-3f2cdc186b3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('781f221e-346e-4f51-ab5f-037fb54e36ec', 'Interest', false, '65abb4cd-e9b8-4507-a263-3f2cdc186b3a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2231c997-b9cc-49e7-a405-be4e0f20da6d', 'Amount', false, '65abb4cd-e9b8-4507-a263-3f2cdc186b3a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea9e66aa-2251-4259-93ee-387b66e5cd54', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'What is the standard formula for calculating SIMPLE INTEREST (SI)?', 'Simple Interest formula: SI = (Principal × Rate × Time) / 100.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd238285-ad21-482c-99e0-a64ca24f8c07', 'SI = (P × R × T) / 100 (where P = Principal, R = Rate % per annum, T = Time in years)', true, 'ea9e66aa-2251-4259-93ee-387b66e5cd54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1a25cc2-b5ea-40f7-9a0e-e25df6f8e80a', 'SI = P + R + T', false, 'ea9e66aa-2251-4259-93ee-387b66e5cd54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b97f667f-3d21-48d5-aa32-dd3ee05e4cd9', 'SI = (P × R) / T', false, 'ea9e66aa-2251-4259-93ee-387b66e5cd54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0872306-0763-4e61-b7f0-5072b7223bbe', 'SI = P × (1 + R/100)', false, 'ea9e66aa-2251-4259-93ee-387b66e5cd54');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87fbad1d-1bed-4adc-a69c-065e004f6f56', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'What is the total Amount (A) paid at the end of the loan tenure?', 'Total Amount A = Principal + Simple Interest (A = P + SI).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c17fae49-a088-44d5-9dca-f2daa21323bb', 'Amount = Principal + Simple Interest (A = P + SI)', true, '87fbad1d-1bed-4adc-a69c-065e004f6f56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('274d3ac1-1958-4434-b368-ef6992598dca', 'Amount = Principal - Simple Interest', false, '87fbad1d-1bed-4adc-a69c-065e004f6f56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d99ebe32-da28-48b2-89e5-46f84a47098a', 'Amount = Principal × Rate', false, '87fbad1d-1bed-4adc-a69c-065e004f6f56');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bae33d8c-6195-4c41-b379-8d320733e484', 'Amount = SI / Time', false, '87fbad1d-1bed-4adc-a69c-065e004f6f56');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1a7e9e6-2cfd-49b3-b284-816f8d92e78e', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'An item bought for Rs 200 is sold for Rs 250. Find the Profit Percentage:', 'Profit = 250 - 200 = 50. Profit % = (50/200) × 100 = 25%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b183cd90-8588-4307-8edb-81fd3c9ff64d', '25% (Profit = 250 - 200 = Rs 50 ; Profit % = (50 / 200) × 100% = 25%)', true, 'e1a7e9e6-2cfd-49b3-b284-816f8d92e78e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4734def6-613c-4b50-b5e4-ddfaf7253bf1', '20%', false, 'e1a7e9e6-2cfd-49b3-b284-816f8d92e78e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23b46311-7190-44de-a079-9043d7b1ff27', '50%', false, 'e1a7e9e6-2cfd-49b3-b284-816f8d92e78e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a74d78c8-0efe-42f2-b919-1727d57cb895', '30%', false, 'e1a7e9e6-2cfd-49b3-b284-816f8d92e78e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45794074-1ca3-40ed-a485-ba18ae177c67', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Easy', 'Find the Simple Interest on Rs 1,000 for 2 years at 5% per annum:', 'SI = (1000 × 5 × 2)/100 = Rs 100.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fe19abc-9298-4416-8e1d-165125241d59', 'Rs 100 (SI = (1000 × 5 × 2) / 100 = Rs 100)', true, '45794074-1ca3-40ed-a485-ba18ae177c67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13d1bb28-422e-4cbe-ab56-3f096e2007af', 'Rs 50', false, '45794074-1ca3-40ed-a485-ba18ae177c67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf53c35e-149d-49ad-a0a6-bc61fc8e5028', 'Rs 200', false, '45794074-1ca3-40ed-a485-ba18ae177c67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44e2746d-dbc8-4856-af3b-c3adaa90558d', 'Rs 150', false, '45794074-1ca3-40ed-a485-ba18ae177c67');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('267e32e5-7af9-4ad5-a3b2-10f81992f6d3', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'Out of 25 students in a class, 72% are good in mathematics. How many students are NOT good in mathematics?', '28% of 25 = 0.28 × 25 = 7 students.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eec6c98d-afb1-4019-aee5-fa4f2652a7d9', '7 students (Not good % = 100% - 72% = 28% ; Number = (28 / 100) × 25 = 7 students)', true, '267e32e5-7af9-4ad5-a3b2-10f81992f6d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61bf4e8d-1b37-4493-aed2-93611f338ffd', '18 students', false, '267e32e5-7af9-4ad5-a3b2-10f81992f6d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa97afc3-2b49-423e-b6bd-81e2a11445da', '5 students', false, '267e32e5-7af9-4ad5-a3b2-10f81992f6d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f03da9d7-d2ca-4ecc-9d02-5ae035a9fdec', '8 students', false, '267e32e5-7af9-4ad5-a3b2-10f81992f6d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63d36854-8f86-4874-9027-9322194c61d3', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'A football team won 10 matches out of the total number of matches they played. If their win percentage was 40%, how many total matches did they play in all?', '0.40 × x = 10 → x = 10 / 0.40 = 25 matches.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32c51ed8-8852-427d-a32d-21938a2b4fc4', '25 matches (40% of Total = 10 ⇒ (40/100) × x = 10 ⇒ x = 10 × (100/40) = 25 matches)', true, '63d36854-8f86-4874-9027-9322194c61d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48b11265-60ba-43e3-8e02-06bd0b85f910', '20 matches', false, '63d36854-8f86-4874-9027-9322194c61d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('619b2caf-1f68-4b31-9f5f-5b7a8ee84787', '30 matches', false, '63d36854-8f86-4874-9027-9322194c61d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffe3a4bc-9bc3-4d80-9e27-0a605a571f52', '40 matches', false, '63d36854-8f86-4874-9027-9322194c61d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('44198431-c9ae-49aa-b6f4-2911ea7f3d62', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'If Chameli had Rs 600 left after spending 75% of her money, how much did she have in the beginning?', '25% of x = 600 → x = 600 × 4 = Rs 2,400.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e153b3f-4dd5-4e73-a978-2f95bf1c9c19', 'Rs 2,400 (Remaining % = 100% - 75% = 25% ; 25% of Total = 600 ⇒ (1/4) × x = 600 ⇒ x = Rs 2,400)', true, '44198431-c9ae-49aa-b6f4-2911ea7f3d62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e88eedb-2ab0-43d1-8569-d2884a50ee99', 'Rs 1,800', false, '44198431-c9ae-49aa-b6f4-2911ea7f3d62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75d578ec-8177-41cc-b909-75913bb443d7', 'Rs 3,000', false, '44198431-c9ae-49aa-b6f4-2911ea7f3d62');
