INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9bd18c3-a923-4883-ac3b-e72484fd2cf7', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'The population of a city decreased from 25,000 to 24,500. Find the Percentage Decrease:', '% Decrease = (500 / 25000) × 100 = 2%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a84091d4-c55e-4e21-99ab-0101a523fec1', '2% (Decrease = 25,000 - 24,500 = 500 ; % Decrease = (500 / 25,000) × 100% = 2%)', true, 'e9bd18c3-a923-4883-ac3b-e72484fd2cf7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c7c9570-a71f-424f-8266-b10fc7af86f7', '5%', false, 'e9bd18c3-a923-4883-ac3b-e72484fd2cf7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc60bbe2-9c29-4a02-b685-f9b60b52913d', '2.5%', false, 'e9bd18c3-a923-4883-ac3b-e72484fd2cf7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c51d5bf-cabb-428e-8e6f-a7b6aa07f7bc', '4%', false, 'e9bd18c3-a923-4883-ac3b-e72484fd2cf7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d77f386d-efae-4c84-935e-109647fb5f86', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'I bought a TV for Rs 10,000 and sold it at a Profit of 20%. How much money do I get for it (Selling Price)?', 'SP = CP × (1 + 20/100) = 10,000 × 1.20 = Rs 12,000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e21ff7b0-2dd0-47c9-b5ab-8d6791cb0319', 'Rs 12,000 (Profit = 20% of 10,000 = Rs 2,000 ; SP = 10,000 + 2,000 = Rs 12,000)', true, 'd77f386d-efae-4c84-935e-109647fb5f86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b0f1471-1f8f-4eab-ae20-83eca2ea0237', 'Rs 11,000', false, 'd77f386d-efae-4c84-935e-109647fb5f86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71aa7802-45db-4f2f-b3eb-a03762d079d3', 'Rs 12,500', false, 'd77f386d-efae-4c84-935e-109647fb5f86');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cdd4e43-8a1a-47c3-8814-e3f3f76e6cbb', 'Rs 8,000', false, 'd77f386d-efae-4c84-935e-109647fb5f86');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5b2dc6d7-931f-4122-b836-39ca3e580bb8', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'Juhi sells a washing machine for Rs 13,500. She loses 20% in the bargain. What was the price at which she bought it (Cost Price)?', 'CP = SP / (1 - 0.20) = 13,500 / 0.80 = Rs 16,875.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1809e7aa-054e-4b43-ae4c-80198ae75d76', 'Rs 16,875 (SP = CP × (1 - Loss%) ⇒ 13,500 = CP × 0.80 ⇒ CP = 13,500 / 0.80 = Rs 16,875)', true, '5b2dc6d7-931f-4122-b836-39ca3e580bb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9c2598e-7412-4660-b570-7ca0789ed6fb', 'Rs 16,200', false, '5b2dc6d7-931f-4122-b836-39ca3e580bb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f05b2731-6f7b-47e7-a99f-276b62b988ae', 'Rs 15,000', false, '5b2dc6d7-931f-4122-b836-39ca3e580bb8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd9b83e8-7e87-49c7-b187-649cea02ad30', 'Rs 17,500', false, '5b2dc6d7-931f-4122-b836-39ca3e580bb8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('049bbdf1-4775-49c3-9fd4-6c963754935a', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'Find the Amount to be paid at the end of 3 years on Principal = Rs 1,200 at 12% per annum:', 'SI = (1200 × 12 × 3)/100 = 432. Amount = 1200 + 432 = Rs 1,632.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b93905b4-360a-4707-9e30-21043f3b3504', 'Rs 1,632 (SI = (1200 × 12 × 3) / 100 = Rs 432 ; Amount = 1200 + 432 = Rs 1,632)', true, '049bbdf1-4775-49c3-9fd4-6c963754935a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60466e86-6624-4024-95de-f9f864445a1f', 'Rs 1,532', false, '049bbdf1-4775-49c3-9fd4-6c963754935a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef17f657-94d0-45c6-9715-addb9c149cf3', 'Rs 1,732', false, '049bbdf1-4775-49c3-9fd4-6c963754935a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58004d08-35c4-470b-b8ea-370c8340064c', 'Rs 1,432', false, '049bbdf1-4775-49c3-9fd4-6c963754935a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f2f0c0f8-2aa5-4399-8178-de974a72f16f', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'What Rate gives Rs 280 as interest on a sum of Rs 56,000 in 2 years?', 'R = (280 × 100) / (56000 × 2) = 28000 / 112000 = 0.25%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('543eb32e-e73f-4049-b652-38a5e3aa5d5a', '0.25% p.a. (R = (SI × 100) / (P × T) = (280 × 100) / (56,000 × 2) = 28,000 / 112,000 = 0.25% or 1/4%)', true, 'f2f0c0f8-2aa5-4399-8178-de974a72f16f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cfba2aa-9666-414d-acbb-0f030b71d5c8', '2.5%', false, 'f2f0c0f8-2aa5-4399-8178-de974a72f16f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48091e5b-0a4b-4104-8385-f37c5365b2ed', '0.5%', false, 'f2f0c0f8-2aa5-4399-8178-de974a72f16f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb2f14cd-0a43-4545-b24b-f39b51053549', '1%', false, 'f2f0c0f8-2aa5-4399-8178-de974a72f16f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ab01eff-8998-4dbd-8c9d-a178ae7a1172', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'If Meena gives an interest of Rs 45 for one year at 9% rate p.a., what is the sum (Principal) she has borrowed?', 'P = (45 × 100)/(9 × 1) = 4500 / 9 = Rs 500.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('147d4989-2938-42f9-b7af-ed088e3af6b1', 'Rs 500 (P = (SI × 100) / (R × T) = (45 × 100) / (9 × 1) = 4500 / 9 = Rs 500)', true, '7ab01eff-8998-4dbd-8c9d-a178ae7a1172');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fbab666-844e-4384-8024-0a76ada8ffe4', 'Rs 450', false, '7ab01eff-8998-4dbd-8c9d-a178ae7a1172');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e84add7f-c9b6-4acd-bc3b-9b3c8fd88580', 'Rs 550', false, '7ab01eff-8998-4dbd-8c9d-a178ae7a1172');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca24f6eb-02f3-4402-9472-aba3390f015c', 'Rs 600', false, '7ab01eff-8998-4dbd-8c9d-a178ae7a1172');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4789fa34-5b57-437a-a22a-0132adb4cf16', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'The angles of a triangle are in the ratio 2 : 3 : 4. Find the measure of each angle in degrees and in percentages of the total sum (180°):', 'Parts: 2+3+4=9. Angles: 2/9(180)=40°, 3/9(180)=60°, 4/9(180)=80°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b2025fa-6b0f-4490-901e-9adde216716c', '40° (22.2%), 60° (33.3%), and 80° (44.4%) (Sum of parts = 9 ; (2/9)×180 = 40°, (3/9)×180 = 60°, (4/9)×180 = 80°)', true, '4789fa34-5b57-437a-a22a-0132adb4cf16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b3a097f-6464-4a1c-8349-878232b3818c', '30°, 60°, 90°', false, '4789fa34-5b57-437a-a22a-0132adb4cf16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a5632bb-96f1-40b2-b651-128819c96209', '20°, 40°, 120°', false, '4789fa34-5b57-437a-a22a-0132adb4cf16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2adad128-1956-4c53-9a28-955782f1e0e9', '50°, 60°, 70°', false, '4789fa34-5b57-437a-a22a-0132adb4cf16');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e1856b8-245e-4b32-a75b-79333d882379', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'A skirt is bought for Rs 250 and sold for Rs 150. Find the Loss Percentage:', 'Loss % = (100/250) × 100 = 40%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('402d1def-9afc-4287-b0a1-2873f2151a38', '40% (Loss = 250 - 150 = Rs 100 ; Loss % = (100 / 250) × 100% = 40%)', true, '7e1856b8-245e-4b32-a75b-79333d882379');
