INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d24230f-b4a7-428f-a791-61caa34918d6', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'An alloy contains 30% copper, 40% zinc, and the remaining is nickel. Find the percentage of nickel in the alloy:', '100% - (30% + 40%) = 30%.', NOW()) ON CONFLICT DO NOTHING;
