INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7b96e1c-e1ac-47e3-9e12-056e27fffc17', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'A gardener bought a plant for Rs 120 and sold it for Rs 150. Find the profit percentage:', 'Profit % = (30/120) × 100 = 25%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('633531e2-b4de-487c-b74c-635935022e46', '25% (Profit = 150 - 120 = 30 ; Profit % = (30 / 120) × 100% = 25%)', true, 'b7b96e1c-e1ac-47e3-9e12-056e27fffc17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('470f833c-b29c-43c9-b0af-8a4b219bfb2c', '20%', false, 'b7b96e1c-e1ac-47e3-9e12-056e27fffc17');
