INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf3a099e-41d9-489c-bca6-9c1571488701', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'A shopkeeper sells 1 dozen eggs for Rs 48, making a profit of 20%. What was the cost price of 1 dozen eggs?', 'CP = 48 / 1.20 = Rs 40.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b41307e5-2a07-4e69-9acf-685a731cf5f2', 'Rs 40 (CP = SP / 1.20 = 48 / 1.20 = Rs 40)', true, 'cf3a099e-41d9-489c-bca6-9c1571488701');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b97a3bb-bf75-49a4-a23a-4b972a1ed955', 'Rs 38', false, 'cf3a099e-41d9-489c-bca6-9c1571488701');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c2dc75b-531b-4a8a-8dcc-182773016f68', 'Rs 42', false, 'cf3a099e-41d9-489c-bca6-9c1571488701');
