INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('447640b0-4a73-4a9e-afd0-d757bf2aa085', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'In a city, 30% are females, 40% are males, and the remaining are children. What percentage are children?', '100% - 70% = 30%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c702dfd-3e95-42f9-a765-1a8b805d64f7', '30% (Children % = 100% - (30% + 40%) = 30%)', true, '447640b0-4a73-4a9e-afd0-d757bf2aa085');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eaf1de1f-4421-46e2-96f5-9cdf9dfb0578', '20%', false, '447640b0-4a73-4a9e-afd0-d757bf2aa085');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54ea81cb-1fd9-412a-b1f5-c6dbadacc25d', '40%', false, '447640b0-4a73-4a9e-afd0-d757bf2aa085');
