INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('312d8975-1589-4482-a756-9a674a3927fa', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Medium', 'Find the ratio of the speed of a cycle (15 km/h) to the speed of a scooter (30 km/h):', 'Ratio = 15 : 30 = 1 : 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a79f1dd3-0d91-4da5-ba39-133116831805', '1 : 2 (15 / 30 = 1 / 2)', true, '312d8975-1589-4482-a756-9a674a3927fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b903be2-fd66-441b-a9bd-634486f922fb', '2 : 1', false, '312d8975-1589-4482-a756-9a674a3927fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('326b6fa7-2b14-4ac2-9a39-f8550e0bc4e6', '1 : 3', false, '312d8975-1589-4482-a756-9a674a3927fa');
