INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b9df48d-2bd3-40cb-bb8d-0e359e876e4b', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ce287ec-f43f-4da6-b930-f3667d608b68', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '3b9df48d-2bd3-40cb-bb8d-0e359e876e4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7a81ea9-fb15-4894-a13e-892596fc3998', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '3b9df48d-2bd3-40cb-bb8d-0e359e876e4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c0bda56-5114-44fd-b379-1a756ae8e95c', '(A) is true, but (R) is false.', false, '3b9df48d-2bd3-40cb-bb8d-0e359e876e4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ff14e38-2dc8-4a57-ad5d-575140d5d922', '(A) is false, but (R) is true.', false, '3b9df48d-2bd3-40cb-bb8d-0e359e876e4b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e20d12c-72fd-4d2a-81b6-4ad644c2b18a', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'Spot the IMPOSTER in the following commercial arithmetic equivalence relations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db50f19c-32b2-4914-91e8-0a79e070894b', 'Equivalence 1', false, '7e20d12c-72fd-4d2a-81b6-4ad644c2b18a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7922390-9fc0-492f-9b94-5e1cc090ea5d', 'Equivalence 2', false, '7e20d12c-72fd-4d2a-81b6-4ad644c2b18a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a2ac678-12b5-4560-a8d0-b696326aa9e3', 'Equivalence 3', false, '7e20d12c-72fd-4d2a-81b6-4ad644c2b18a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f096537-fc9e-4b36-86ef-c7f87b7f897a', 'Equivalence 4 (2/3 is equal to 66.67% or 66 2/3%, NOT 75% ; 3/4 is 75%)', true, '7e20d12c-72fd-4d2a-81b6-4ad644c2b18a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d9d452b4-0d5f-442d-97d3-d4492c585be7', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'A sum of money doubles itself in 8 years under Simple Interest. What is the annual Rate of Interest?', 'SI = P → P = (P × R × 8) / 100 → R = 100 / 8 = 12.5% per annum.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5876207e-dc5c-4f82-8c17-7d44c14c3647', '12.5% p.a. (Let Principal = P ; Since money doubles, Amount = 2P, so SI = P ; SI = (P × R × 8)/100 ⇒ P = (P × R × 8)/100 ⇒ R = 100 / 8 = 12.5% p.a.)', true, 'd9d452b4-0d5f-442d-97d3-d4492c585be7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('159a7dd2-4c15-4b02-a70f-55ad1814b480', '10% p.a.', false, 'd9d452b4-0d5f-442d-97d3-d4492c585be7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd64e90c-8c6c-4762-a8d4-1a55a92f46e6', '15% p.a.', false, 'd9d452b4-0d5f-442d-97d3-d4492c585be7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f267786-ad12-4eda-962b-002978e80101', '8% p.a.', false, 'd9d452b4-0d5f-442d-97d3-d4492c585be7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2c837f46-feea-4b9b-a126-1ea8ef12b560', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'Match Column I (Commercial Math Problems) with Column II (Exact Solutions):
(a) Convert 5/8 to Percentage               -> (i) 62.5%
(b) Increase in price from Rs 20 to Rs 25    -> (ii) 25% Increase
(c) Simple Interest on Rs 5000 @ 10% for 3 yr-> (iii) Rs 1,500
(d) Loss % when CP = Rs 50 and SP = Rs 40    -> (iv) 20% Loss', '5/8 = 62.5%; (5/20)×100 = 25%; (5000×10×3)/100 = 1500; (10/50)×100 = 20%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52cf4998-74c0-40a3-8bd3-5256e8243c77', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '2c837f46-feea-4b9b-a126-1ea8ef12b560');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ac0390b-e47f-4391-9a7d-951e7ac73c8e', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '2c837f46-feea-4b9b-a126-1ea8ef12b560');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42a1ada0-3005-4876-828e-e1e45524ef79', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '2c837f46-feea-4b9b-a126-1ea8ef12b560');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85945e1a-ab1a-4bc8-9cd2-2f7532344d78', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '2c837f46-feea-4b9b-a126-1ea8ef12b560');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba1fdf67-738b-455d-b342-b7e4d29b40e7', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'Read the statements regarding price variations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22f7b0d6-50ab-42bf-bdfb-21cd2f5dcd67', 'Statements 1 and 2 only', true, 'ba1fdf67-738b-455d-b342-b7e4d29b40e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fa524f2-f607-4f5d-996d-549ade78c311', 'Statements 2 and 3 only', false, 'ba1fdf67-738b-455d-b342-b7e4d29b40e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34952dad-673d-4f7e-a3f2-3e178c7db509', 'Statements 1 and 3 only', false, 'ba1fdf67-738b-455d-b342-b7e4d29b40e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5a7ec88-f4d5-4ec4-98ce-3b8cdc0b13ef', 'All Statements 1, 2, and 3', false, 'ba1fdf67-738b-455d-b342-b7e4d29b40e7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8dc3faf1-b119-4f8f-900e-42d4b52e3dbe', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'If the Cost Price of 12 pens is equal to the Selling Price of 15 pens, find the Gain or Loss percentage:', 'Loss % = (15 - 12) / 15 × 100 = (3/15) × 100 = 20% loss.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fedc0fec-492a-42da-b1a6-88e53bae4fe0', '20% Loss (Let CP of 1 pen = Rs 1 ; CP of 15 pens = Rs 15 ; SP of 15 pens = CP of 12 pens = Rs 12 ; Loss = 15 - 12 = Rs 3 ; Loss % = (3 / 15) × 100% = 20%)', true, '8dc3faf1-b119-4f8f-900e-42d4b52e3dbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f0c03ff-4a62-4a5a-80a4-cd58a16e6c05', '25% Profit', false, '8dc3faf1-b119-4f8f-900e-42d4b52e3dbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50b49478-fe15-4250-b7e5-50771a7beb50', '20% Profit', false, '8dc3faf1-b119-4f8f-900e-42d4b52e3dbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb9b92f4-6f27-49cb-9b3a-c0aa3a06a0c3', '25% Loss', false, '8dc3faf1-b119-4f8f-900e-42d4b52e3dbe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53f3324d-c44c-42f4-b85a-7ec7860b98ab', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'A sum of money invested at Simple Interest amounts to Rs 850 in 3 years and to Rs 925 in 4 years. Find the Principal sum and the annual Rate of Interest:', 'Annual SI = 925 - 850 = Rs 75. P = 850 - 3(75) = Rs 625. R = (75 × 100)/(625 × 1) = 12%.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2d96c2e-109a-4f03-aca2-a79169872b8d', 'Principal = Rs 625 ; Rate = 12% p.a. (SI for 1 year = 925 - 850 = Rs 75 ; SI for 3 years = 75 × 3 = Rs 225 ; Principal = 850 - 225 = Rs 625 ; Rate = (75 × 100) / (625 × 1) = 12% p.a.)', true, '53f3324d-c44c-42f4-b85a-7ec7860b98ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eededb6d-6d92-46d1-9cbd-497602030350', 'Principal = Rs 600 ; Rate = 10%', false, '53f3324d-c44c-42f4-b85a-7ec7860b98ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b3520e1-528a-4909-95bf-072c49af5b6c', 'Principal = Rs 650 ; Rate = 14%', false, '53f3324d-c44c-42f4-b85a-7ec7860b98ab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7cdfc59-a629-418b-8dac-5dad510f6acc', 'Principal = Rs 700 ; Rate = 8%', false, '53f3324d-c44c-42f4-b85a-7ec7860b98ab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76a3648d-5817-443d-ba55-b8117712358e', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'In an election between two candidates, the winning candidate secured 58% of the total valid votes and won by a majority of 4,800 votes. Find the total number of valid votes polled:', 'Vote differential = 58% - 42% = 16%. Total votes = 4,800 / 0.16 = 30,000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7910998a-59ad-4ffb-bc8e-7dbc1073195c', '30,000 votes (Winner % = 58% ; Loser % = 42% ; Margin = 58% - 42% = 16% ; 16% of Total = 4,800 ⇒ Total = (4800 / 16) × 100 = 30,000 votes)', true, '76a3648d-5817-443d-ba55-b8117712358e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f091f18-fb64-4cf0-a77e-a0132bcb9202', '25,000 votes', false, '76a3648d-5817-443d-ba55-b8117712358e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26b1d19e-808c-4559-8255-c334e1d982e3', '35,000 votes', false, '76a3648d-5817-443d-ba55-b8117712358e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e6c79dd-7734-4b3f-bc03-dc15c82930ca', '40,000 votes', false, '76a3648d-5817-443d-ba55-b8117712358e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3ccf6b2-742b-42a2-9a86-93608ee65a03', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'A man sold two fans for Rs 990 each. On one he gained 10% and on the other he lost 10%. Find his overall Gain or Loss percentage on the entire whole transaction:', 'When SP is identical with ±x% gain/loss, there is always a net loss of (x/10)²% = (10/10)²% = 1% loss.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e5df0dc-9f8a-42e5-8aa0-be2936c0b622', '1% Loss (CP1 = 990 / 1.10 = Rs 900 ; CP2 = 990 / 0.90 = Rs 1100 ; Total CP = 2000 ; Total SP = 1980 ; Net Loss = Rs 20 ; Loss % = (20 / 2000) × 100% = 1%)', true, 'd3ccf6b2-742b-42a2-9a86-93608ee65a03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f7e84a1-102e-4fa0-afd4-ee385da32d35', 'No profit no loss', false, 'd3ccf6b2-742b-42a2-9a86-93608ee65a03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c89582e-55c1-42f9-9df9-48b441106831', '1% Gain', false, 'd3ccf6b2-742b-42a2-9a86-93608ee65a03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ebb6a04-8072-4949-8fbc-4485335abe6e', '2% Loss', false, 'd3ccf6b2-742b-42a2-9a86-93608ee65a03');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e70eddf0-261d-41f4-860b-f7edde72ac96', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'The salary of an officer was increased by 20%. By what percentage must the new salary be reduced to bring it back to the original initial salary level?', '% Reduction = (r / (100 + r)) × 100% = (20 / 120) × 100 = 16.67% (or 16 2/3%).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('400828e5-5556-4f5b-82c4-cfe71c583736', '16 2/3% or 16.67% (Let original = 100 ⇒ New = 120 ; Reduction required = 20 ; % Reduction = (20 / 120) × 100% = 100 / 6 = 16.67%)', true, 'e70eddf0-261d-41f4-860b-f7edde72ac96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24473062-d6ef-4797-b422-fd1d96769d9e', '20%', false, 'e70eddf0-261d-41f4-860b-f7edde72ac96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59a0150e-35dc-4116-ae73-f0bbafb8b2d5', '25%', false, 'e70eddf0-261d-41f4-860b-f7edde72ac96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07a4ca24-53fe-4797-b33f-aac61cedbfc0', '15%', false, 'e70eddf0-261d-41f4-860b-f7edde72ac96');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6aa784fa-d49b-4a22-a6f4-42bb846f75bb', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'At what rate percent per annum simple interest will a sum of money TRIPLE itself in 16 years?', 'SI = 2P → 2P = (P × R × 16)/100 → R = 200 / 16 = 12.5% per annum.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9666ce94-1dd1-4d8e-ac3a-e5440340b09b', '12.5% p.a. (Amount = 3P ⇒ SI = 2P ; 2P = (P × R × 16) / 100 ⇒ R = 200 / 16 = 12.5% p.a.)', true, '6aa784fa-d49b-4a22-a6f4-42bb846f75bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffebf17b-f5b5-4b7e-8b67-72172c9ad0f8', '10% p.a.', false, '6aa784fa-d49b-4a22-a6f4-42bb846f75bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4921fcb0-5635-49f4-bab3-d99b2eb7a0ef', '15% p.a.', false, '6aa784fa-d49b-4a22-a6f4-42bb846f75bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bfc8817-c843-42d4-82ff-19152a7fe809', '16% p.a.', false, '6aa784fa-d49b-4a22-a6f4-42bb846f75bb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2a4294de-1b8e-42ba-81c7-e3d21a3267f4', 'Class 7', 'Mathematics', 'Chapter 7: Comparing Quantities', 'Hard', 'Why is the mathematical mastery of Comparing Quantities (Ratios, Percentages, Profit-Loss, and Simple Interest) fundamental across economics, financial literacy, demographic statistics, and everyday commerce?', 'Quantitative comparison frameworks underwrite modern financial literacy, economic metric normalization, accounting standards, and risk-adjusted capital pricing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('914685da-c0b0-4174-bede-ab126f14d1ed', 'It provides the universal quantitative language for normalizing scales, calculating financial returns on capital, evaluating economic growth rates, and making sound personal financial decisions', true, '2a4294de-1b8e-42ba-81c7-e3d21a3267f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96231b8d-12b9-410b-bd68-3440515dde64', 'Because numbers are only used to count coins', false, '2a4294de-1b8e-42ba-81c7-e3d21a3267f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2df04d97-0ab2-4d8e-90c3-f8459f69ddf8', 'Because percentage was invented to make math harder', false, '2a4294de-1b8e-42ba-81c7-e3d21a3267f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26ad1497-222a-45c1-8326-d158b86b55c2', 'Because interest is paid only in gold', false, '2a4294de-1b8e-42ba-81c7-e3d21a3267f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eabfcc7c-9e8a-4a94-9e1d-2b1e06674765', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'In Roald Dahl''s imaginative excerpt ''The Invention of Vita-Wonk'', who is the eccentric, brilliant chocolatier and inventor?', 'Mr. Willy Wonka is the legendary eccentric inventor from Roald Dahl''s ''Charlie and the Great Glass Elevator''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f772327-aacc-4844-bdf2-c87fc6fdc8bd', 'Mr. Willy Wonka', true, 'eabfcc7c-9e8a-4a94-9e1d-2b1e06674765');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e78ed04-90b0-48cd-a51f-83b554f80286', 'Charlie Bucket', false, 'eabfcc7c-9e8a-4a94-9e1d-2b1e06674765');
