INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41abce2c-b6ea-4797-a734-e64da4f1a1ff', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'What medicine did Mr. Willy Wonka first invent that made people become so much younger that some people vanished into negative ages (like minus eighty-seven)?', 'Wonka-Vite made people younger; but being too potent, it made some people have negative ages (minus 87) where they had to wait 87 years to be born!', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dbc8b4e-508c-428a-b119-d786fe05c526', 'Wonka-Vite', true, '41abce2c-b6ea-4797-a734-e64da4f1a1ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23f33463-87b6-4e84-b568-7956368d6189', 'Vita-Wonk', false, '41abce2c-b6ea-4797-a734-e64da4f1a1ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36d755d9-87d4-4ff7-935d-95722eaa50ae', 'Everlasting Gobstopper', false, '41abce2c-b6ea-4797-a734-e64da4f1a1ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a407d22-eea4-4364-a737-9a9e90c56943', 'Fizzing Whizzpopper', false, '41abce2c-b6ea-4797-a734-e64da4f1a1ff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7d57a93-e875-41c8-9c6f-a9125b3a9de8', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'What opposite new medicine does Mr. Willy Wonka set out to invent to make people grow older and reverse the negative age catastrophe?', 'To undo the effects of Wonka-Vite, Mr. Wonka creates ''Vita-Wonk'' to age people up.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('768c3ba6-eb44-4611-802c-4dcdc267048f', 'Vita-Wonk', true, 'c7d57a93-e875-41c8-9c6f-a9125b3a9de8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae16504c-49b8-4ae0-82fe-ca6dfa81694a', 'Wonka-Vite', false, 'c7d57a93-e875-41c8-9c6f-a9125b3a9de8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e90d4db5-99c8-4ba8-95af-5e888da74e4b', 'Snozzberry Syrup', false, 'c7d57a93-e875-41c8-9c6f-a9125b3a9de8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c99757c-4a98-46a9-bea4-446de6861718', 'Magic Toffee', false, 'c7d57a93-e875-41c8-9c6f-a9125b3a9de8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1339cd2c-e515-4d7c-ad83-d8605cc2a3b1', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'What is the OLDEST living thing on Earth from which Mr. Wonka collects sap for Vita-Wonk?', 'Mr. Wonka explains to Charlie that Bristlecone pines living on the slopes of Wheeler Peak in Nevada live over 4,000 years.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8358751-55f8-4b65-a072-82de1dd4ae0e', 'The Bristlecone Pine tree (living over 4,000 years on Wheeler Peak)', true, '1339cd2c-e515-4d7c-ad83-d8605cc2a3b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f98e74ff-92d6-403e-a7f3-36ab72f8b333', 'An Oak tree', false, '1339cd2c-e515-4d7c-ad83-d8605cc2a3b1');
