INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dbaface1-1a13-4f4d-978f-74db1ef28107', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'Which 20-year-old brave volunteer was given four drops of oily black Vita-Wonk liquid to test its aging power?', 'A brave 20-year-old Oompa-Loompa volunteer swallowed the four drops of oily black Vita-Wonk.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36559d7c-027f-475c-ab58-07b54198b62b', 'An Oompa-Loompa volunteer named Oompa-Loompa', true, 'dbaface1-1a13-4f4d-978f-74db1ef28107');
