INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('240d4d50-62b8-4911-a8ba-b9cf243364b3', 'Augustus Gloop', false, 'dbaface1-1a13-4f4d-978f-74db1ef28107');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d86d3b52-dbaa-4294-94a2-b2c445c90bbd', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'What dramatic physical transformation happened to the 20-year-old volunteer after swallowing the four drops of Vita-Wonk?', 'Vita-Wonk aged the 20-year-old instantly into a 75-year-old wrinkly man, proving the invention''s success.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e99837e-0ce8-4cd0-a09d-f90a4d4cc8ec', 'He began wrinkling and shriveling up, his hair dropped off, his teeth fell out, and he instantly became a feeble old fellow of SEVENTY-FIVE (75 years old)!', true, 'd86d3b52-dbaa-4294-94a2-b2c445c90bbd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f83f487-bc15-4f38-acf6-30bf8b9060fb', 'He turned into a giant green tree', false, 'd86d3b52-dbaa-4294-94a2-b2c445c90bbd');
