INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('427d94ae-afc7-4f9e-ae1d-3aa8a694b90b', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'In Kit Wright''s humorous poem ''Dad and the Cat and the Tree'', where was the cat stuck?', 'The poem begins: ''This morning a cat got stuck in our tree. / Dad said, "Right, just leave it to me."''.', NOW()) ON CONFLICT DO NOTHING;
