INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0d784ab-2f32-4f8f-a699-fb78e1ad701a', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'What boastful remark did Dad make to Mum before attempting to rescue the cat from the tree?', 'Dad overconfidently dismisses Mum''s warnings: ''A climber like me? Child''s play, this is!''.', NOW()) ON CONFLICT DO NOTHING;
