INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e87b4cc4-fd03-47c6-b248-5e49254ef47e', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Easy', 'What hilarious twist occurs at the end of the poem when Dad tries ''PLAN C'' and leaps from the garden wall into the tree?', 'Ironical climax: the cat leaps safely to the ground unharmed, leaving boastful Dad stuck in the tree crook.', NOW()) ON CONFLICT DO NOTHING;
