INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bb2217d2-1089-468b-b27d-938d98e5c8fa', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Medium', 'How did Mr. Willy Wonka travel across the globe to collect bits and pieces from the world''s most ancient creatures?', 'Wonka zoomed across the planet in his fantastical Great Glass Elevator to harvest ancient specimen samples.', NOW()) ON CONFLICT DO NOTHING;
