INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('029968f6-195b-48fa-a7a6-ec5650ea8bf5', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Hard', 'Identify the grammatical role of the underlined participial clause in: ''**Leaping from the garden wall**, Dad crashed straight into the crook of the tree.''', '''Leaping from the garden wall'' is an introductory participial phrase describing Dad''s dynamic action modifying the main clause.', NOW()) ON CONFLICT DO NOTHING;
