INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ba97314-5b29-43b6-b260-b1f4bbe889ae', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Hard', 'Why does Roald Dahl emphasize the precise botanical reality of the ''Bristlecone Pine'' in his dialogue with Charlie?', 'Dahl grounds his fantasy in genuine botanical awe: the ancient Bristlecone pine (Pinus longaeva) really is Earth''s oldest living non-clonal organism.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0daf8334-4977-4fd8-8644-dae40e0f2c17', 'To anchor his fantastical narrative in authentic natural wonder, proving to children that nature''s real living marvels are often more incredible than fiction', true, '0ba97314-5b29-43b6-b260-b1f4bbe889ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0dc4ee9d-f954-4503-8253-94f480d4e96c', 'To encourage people to cut down trees', false, '0ba97314-5b29-43b6-b260-b1f4bbe889ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d649253-8d80-443d-8f32-57dea457e02f', 'To sell wood furniture', false, '0ba97314-5b29-43b6-b260-b1f4bbe889ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('525ddabc-7fb7-4c31-b721-a5747bcb05ba', 'Because Dahl lived in Nevada', false, '0ba97314-5b29-43b6-b260-b1f4bbe889ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f10eebfa-d38e-4f6c-989c-798f047806ec', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Hard', 'In the rhythm and rhyme scheme of ''Dad and the Cat and the Tree'', what poetic form enhances the fast-paced slapstick delivery?', 'Bouncy ballad quatrains with sharp rhyming couplets propel the slapstick narrative forward with brisk comedic timing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb34270a-b38f-44dc-b7b3-211a85f9c52d', 'Rhyming quatrains (AABB / ABCB) with lively, bouncy anapestic and iambic meter that mimics the escalating cadence of cartoon physical comedy', true, 'f10eebfa-d38e-4f6c-989c-798f047806ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9008f521-85a6-448b-998e-833eeb6efe57', 'Sombre funeral elegiac verse', false, 'f10eebfa-d38e-4f6c-989c-798f047806ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70cb3041-acfb-4b2b-86b6-d2cac6c6b814', 'Unrhymed blank verse in sonnet form', false, 'f10eebfa-d38e-4f6c-989c-798f047806ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e98929d-11fa-47a0-97b9-906e145ddb74', 'Ancient Greek hexameter', false, 'f10eebfa-d38e-4f6c-989c-798f047806ec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3c288105-8bb9-4b03-9137-d63a6658f1d8', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Hard', 'What does the phrase ''Rubbed his hands together'' signify when Mr. Willy Wonka proclaims the success of his invention?', 'Rubbing hands together is a kinetic body language idiom expressing eager anticipation and triumphant professional delight.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6029d12-81f4-41ba-a81e-5e4c2a62bdf9', 'A universal human physical gesture denoting extreme excitement, triumphant satisfaction, and anticipation of success', true, '3c288105-8bb9-4b03-9137-d63a6658f1d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ba2d17f-2df2-4e7e-98d4-99516c67c0aa', 'That his hands were very cold', false, '3c288105-8bb9-4b03-9137-d63a6658f1d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c943922e-b59f-4d89-9e37-2f9bd635485e', 'That he wanted to wash his hands', false, '3c288105-8bb9-4b03-9137-d63a6658f1d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7016e00-87b4-4976-8ae0-676feb0ab366', 'That he was angry at Charlie', false, '3c288105-8bb9-4b03-9137-d63a6658f1d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a23b3531-7ddc-481b-bf13-06e7cc8fa9fd', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Hard', 'Which of the following lines from the poem contains an ONOMATOPOEIC sound word?', '''SMACK!'' is an onomatopoeic auditory word recreating the sharp physical acoustic impact of landing on the ground.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f26ad5c9-d0df-4614-a12b-69821eb75881', '"The bough broke — SMACK! / Dad grovelled."', true, 'a23b3531-7ddc-481b-bf13-06e7cc8fa9fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d06e6dd5-8ed5-4f85-b3ad-c3c6a67c5b80', '"A climber like me?"', false, 'a23b3531-7ddc-481b-bf13-06e7cc8fa9fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('128b914d-046c-4cc0-809b-567070cc3619', '"This morning a cat got stuck in our tree."', false, 'a23b3531-7ddc-481b-bf13-06e7cc8fa9fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be62fb49-4ce2-4848-a2fb-194c767bf764', '"Smiling and smirking, smug as can be."', false, 'a23b3531-7ddc-481b-bf13-06e7cc8fa9fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('39c6823e-1c89-4cfa-8ef3-8345d951d1fd', 'Class 7', 'English', 'Chapter 7: The Invention of Vita-Wonk & Dad and the Cat and the Tree', 'Hard', 'What overarching literary value unites Chapter 7 of NCERT Class 7 English?', 'Chapter 7 champions the vitality of imaginative storytelling, joyful wordplay, and the playful subversion of self-serious adult authority.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac870985-03b1-42d6-a6c4-b897122ddea6', 'The celebration of exuberant literary imagination, boundless creative curiosity, and the therapeutic power of lighthearted humor in transforming everyday life into whimsical wonder', true, '39c6823e-1c89-4cfa-8ef3-8345d951d1fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36b73eaa-1819-46f4-8985-5559cfaf73ab', 'That climbing trees is strictly forbidden by law', false, '39c6823e-1c89-4cfa-8ef3-8345d951d1fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89c10cfb-6390-4543-811e-92ba9618fd52', 'That medicines should be mixed with tea', false, '39c6823e-1c89-4cfa-8ef3-8345d951d1fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f2344c8-0155-4600-8032-de86a17159ec', 'That cats are always smarter than humans', false, '39c6823e-1c89-4cfa-8ef3-8345d951d1fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('886dcb1e-4c51-4f3e-b882-291537e1dc12', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'Who is celebrated as the ''Father of the Indian Constitution'' and was the Chairman of the Drafting Committee of the Constituent Assembly?', 'Dr. Bhimrao Ramji Ambedkar chaired the Drafting Committee, shaping the foundational democratic architecture of the Indian Republic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab4f91a0-6e49-4c07-b55c-c5ba44065891', 'Dr. B.R. Ambedkar', true, '886dcb1e-4c51-4f3e-b882-291537e1dc12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73de3493-9579-4d2b-a341-ed6ecb8d4f74', 'Dr. Rajendra Prasad', false, '886dcb1e-4c51-4f3e-b882-291537e1dc12');
