INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8bfeed79-9b6c-4f50-bee2-26c775346a58', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'On which historic date did the Constitution of India come into full legal effect, celebrated annually as REPUBLIC DAY?', 'The Constitution came into force on 26 January 1950, commemorating the 1930 Purna Swaraj declaration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34ae15bc-82da-4f65-a122-ec4a59c53187', '26 January 1950', true, '8bfeed79-9b6c-4f50-bee2-26c775346a58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40af6cbf-9c6b-44f8-99ac-35e7c2132e30', '15 August 1947', false, '8bfeed79-9b6c-4f50-bee2-26c775346a58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('360eb885-e715-44c5-8a03-bd93cf169f3d', '26 November 1949', false, '8bfeed79-9b6c-4f50-bee2-26c775346a58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4912d6c1-f534-40f2-9aed-abd687f403d7', '2 October 1950', false, '8bfeed79-9b6c-4f50-bee2-26c775346a58');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49ea0907-4646-4f37-8201-135f170007bc', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'On which date is ''Constitution Day'' (Samvidhan Divas) celebrated in India to commemorate the formal adoption of the Constitution by the Constituent Assembly in 1949?', 'The Constituent Assembly adopted the Constitution on 26 November 1949, observed nationally as Samvidhan Divas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00d16b21-6034-4e44-a7a8-8d17637271cb', '26 November', true, '49ea0907-4646-4f37-8201-135f170007bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1293cbce-9481-4b84-a374-fbc3ef544a80', '26 January', false, '49ea0907-4646-4f37-8201-135f170007bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84ee9788-b2be-4b64-a6d0-323326bbf9bc', '15 August', false, '49ea0907-4646-4f37-8201-135f170007bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e711853-cf95-4a48-86fc-324e4e803b72', '30 January', false, '49ea0907-4646-4f37-8201-135f170007bc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c85e7043-f670-48a9-b53c-2a7a01e42e9d', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'Who was the elected permanent President of the Constituent Assembly of India and the First President of independent India?', 'Dr. Rajendra Prasad presided over the Constituent Assembly from Dec 1946 until its conclusion and served as India''s first President.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9394ff12-b8e4-4050-9b5e-00d0e98d1038', 'Dr. Rajendra Prasad', true, 'c85e7043-f670-48a9-b53c-2a7a01e42e9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d590930-e113-40f1-a6c7-6d8c92324352', 'Dr. B.R. Ambedkar', false, 'c85e7043-f670-48a9-b53c-2a7a01e42e9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d0cbe72-02f1-4d28-894f-e18a60e4ec31', 'Dr. S. Radhakrishnan', false, 'c85e7043-f670-48a9-b53c-2a7a01e42e9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f01fdac1-7efb-4e91-b73a-df1bff242401', 'C. Rajagopalachari', false, 'c85e7043-f670-48a9-b53c-2a7a01e42e9d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5766b897-7bcc-4b94-a4d3-8d2b1566441a', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'What is the introductory opening statement of the Constitution that outlines the core philosophy, values, and objectives of the Indian Republic called?', 'The Preamble proclaims India as a ''Sovereign Socialist Secular Democratic Republic'' securing Justice, Liberty, Equality, and Fraternity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48377deb-09fa-41ed-93de-144c7ea32eac', 'The Preamble', true, '5766b897-7bcc-4b94-a4d3-8d2b1566441a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00e5a046-e75f-4428-9c8a-39b259bae5f9', 'The Index', false, '5766b897-7bcc-4b94-a4d3-8d2b1566441a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1688420-3f4b-4bcb-aef4-4e8372ff0383', 'The Schedule', false, '5766b897-7bcc-4b94-a4d3-8d2b1566441a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dab5ff3b-363d-46c3-851a-238748a070e3', 'The Directive Principles', false, '5766b897-7bcc-4b94-a4d3-8d2b1566441a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('84bb57e4-70b9-4b78-b28c-dc2c3ddac890', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'How many broad categories of Fundamental Rights are guaranteed to all Indian citizens under Part III of the Constitution (Articles 12–35)?', 'The Constitution guarantees 6 Fundamental Rights (the 44th Amendment in 1978 removed the Right to Property as a fundamental right).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ab30e3a-dde2-43dd-83f4-4a2bb0414857', '6 Fundamental Rights (Right to Equality, Freedom, Against Exploitation, Freedom of Religion, Cultural/Educational, and Constitutional Remedies)', true, '84bb57e4-70b9-4b78-b28c-dc2c3ddac890');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01630241-53f1-4e03-8e5e-f4540b050b4f', '7 Fundamental Rights (Right to Property was deleted)', false, '84bb57e4-70b9-4b78-b28c-dc2c3ddac890');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7df44e4e-1183-42db-ac50-e0498e054088', '10 Fundamental Rights', false, '84bb57e4-70b9-4b78-b28c-dc2c3ddac890');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02837713-bb71-4e23-a734-c56ef17f8a8f', '4 Fundamental Rights', false, '84bb57e4-70b9-4b78-b28c-dc2c3ddac890');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0c51d46f-f933-4170-a7e5-ac2fb16016ad', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'Which Fundamental Right under Article 32 was described by Dr. B.R. Ambedkar as the "Heart and Soul of the Constitution"?', 'Article 32 empowers the Supreme Court to issue writs (Habeas Corpus, Mandamus, etc.) to enforce fundamental rights.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4254ad9c-283d-43e6-82f7-28ee937290e2', 'Right to Constitutional Remedies (the right to petition the Supreme Court directly via writs)', true, '0c51d46f-f933-4170-a7e5-ac2fb16016ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6497170c-7abd-48b8-b3a7-fb018d8d03c6', 'Right to Equality', false, '0c51d46f-f933-4170-a7e5-ac2fb16016ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('330ce078-c36e-4a91-b93f-538cc5e865aa', 'Right to Freedom', false, '0c51d46f-f933-4170-a7e5-ac2fb16016ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f134a1e6-ec9e-41d6-af8e-b1828a83e8ca', 'Right to Education', false, '0c51d46f-f933-4170-a7e5-ac2fb16016ad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31f5099a-1091-4d0f-8c70-3c0b5adb4620', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'Who is the Constitutional Head of State of the Republic of India and the Supreme Commander of the Indian Armed Forces?', 'The President is the executive Head of State and supreme commander of the army, navy, and air force under Article 53.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed1afadc-77bb-4e8f-99a8-ceda6db5e97a', 'The President of India', true, '31f5099a-1091-4d0f-8c70-3c0b5adb4620');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be1cdcbe-fa3d-4e5c-950d-ed11d5a51b94', 'The Prime Minister', false, '31f5099a-1091-4d0f-8c70-3c0b5adb4620');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67713430-4a44-4126-9fc7-960e89df7633', 'The Chief Justice of India', false, '31f5099a-1091-4d0f-8c70-3c0b5adb4620');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93abba80-91a9-4084-b7b4-6466e8d1d0a0', 'The Defence Minister', false, '31f5099a-1091-4d0f-8c70-3c0b5adb4620');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97cb9047-b47f-4d3e-80b1-2becfd9fe429', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'What are the two houses of the bicameral Parliament of India (Sansad)?', 'The Union Parliament comprises the President, Lok Sabha (directly elected lower house), and Rajya Sabha (states'' council upper house).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98e07ac6-ca6b-4961-b108-45eff4a79770', 'The Lok Sabha (House of the People) and the Rajya Sabha (Council of States)', true, '97cb9047-b47f-4d3e-80b1-2becfd9fe429');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17cf386c-c191-409e-b726-9f46f99c0de6', 'The Senate and House of Representatives', false, '97cb9047-b47f-4d3e-80b1-2becfd9fe429');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12bfb9da-8576-418d-94c3-f2dc0f74c094', 'The Vidhan Sabha and Vidhan Parishad', false, '97cb9047-b47f-4d3e-80b1-2becfd9fe429');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68d2366b-a765-4c42-a0a0-8cfdcbcbe0d6', 'The Supreme Court and High Court', false, '97cb9047-b47f-4d3e-80b1-2becfd9fe429');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3a391453-634b-4e8f-b502-c9cca78e9030', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'What is the highest judicial court of appeal and custodian of the Constitution in India, headquartered on Tilak Marg in New Delhi?', 'The Supreme Court of India (inaugurated 28 January 1950) is the apex judicial forum and constitutional interpreter.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ffd8be8-1a2b-4def-a585-6ba87d25b6df', 'The Supreme Court of India', true, '3a391453-634b-4e8f-b502-c9cca78e9030');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9a9346d-0975-4602-a6f9-0f47e657542c', 'The High Court of Delhi', false, '3a391453-634b-4e8f-b502-c9cca78e9030');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7fa0af3-60f2-4a43-9971-cf625670a7a4', 'The National Green Tribunal', false, '3a391453-634b-4e8f-b502-c9cca78e9030');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9014958d-e320-464e-83a0-55f8ec776a31', 'The Parliament', false, '3a391453-634b-4e8f-b502-c9cca78e9030');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d4aa708-1745-4c80-bd30-20c446f01314', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'What is the minimum voting age for Indian citizens in general elections under the Universal Adult Suffrage principle (lowered from 21 by 61st Amendment)?', 'The 61st Constitutional Amendment Act (1988) amended Article 326 to lower the voting age from 21 to 18 years.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d208d583-3411-4429-9f98-f24051c53292', '18 years', true, '4d4aa708-1745-4c80-bd30-20c446f01314');
