INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b0cace4-ecd0-4ac0-8d50-001a70f2bb95', '25 years', false, '4d4aa708-1745-4c80-bd30-20c446f01314');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9df0c47f-b0ce-480d-b0c6-fe73e4ead986', '16 years', false, '4d4aa708-1745-4c80-bd30-20c446f01314');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('956c53b8-cce3-4684-8b56-99a655f67c88', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Easy', 'Which independent constitutional body conducts free and fair elections to the Lok Sabha, Rajya Sabha, State Legislatures, and the offices of President and Vice President of India?', 'The Election Commission of India (established 25 Jan 1950, National Voters'' Day) oversees federal and state electoral processes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('228581af-8c4a-499c-901b-2752429115ae', 'Election Commission of India (ECI - Article 324)', true, '956c53b8-cce3-4684-8b56-99a655f67c88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('446966dd-2fc0-4e96-ad9d-e747a72c719b', 'UPSC', false, '956c53b8-cce3-4684-8b56-99a655f67c88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c32abda2-6422-460e-bc01-b3b2aa4a9d06', 'NITI Aayog', false, '956c53b8-cce3-4684-8b56-99a655f67c88');
