INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a93fdf13-4020-408e-b515-ee805b4c7af8', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What are the ''Directive Principles of State Policy'' (DPSP) contained in Part IV (Articles 36–51) of the Indian Constitution, borrowed from the Irish Constitution?', 'DPSPs are socio-economic governance charters guiding state legislation towards establishing an equitable welfare society.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('601f64a6-1986-4f2f-bdac-9492affb9744', 'Non-justiciable constitutional guidelines and moral directives for the government to establish a Welfare State and achieve social-economic democracy', true, 'a93fdf13-4020-408e-b515-ee805b4c7af8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('602badc7-c45a-43cd-b077-d51bf77ff3e5', 'Rules for arresting criminals', false, 'a93fdf13-4020-408e-b515-ee805b4c7af8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe272708-a7ae-43c2-a4c2-69ea6b8fd286', 'Laws on international trade', false, 'a93fdf13-4020-408e-b515-ee805b4c7af8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8fe082b-b343-4396-b89f-41914cfc24f9', 'Military commands', false, 'a93fdf13-4020-408e-b515-ee805b4c7af8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('032b8cba-730c-427f-b564-802600d9615d', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'Which constitutional amendment in 1976 (known as the ''Mini-Constitution'') added the words ''SOCIALIST'', ''SECULAR'', and ''INTEGRITY'' to the Preamble, and inserted Fundamental Duties (Article 51A)?', 'The 42nd Amendment Act (1976) introduced secular-socialist preambular values and Part IV-A (Fundamental Duties) upon Swaran Singh Committee advice.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bda53f53-7a0c-4afd-b9df-200980c635de', 'The 42nd Constitutional Amendment Act, 1976', true, '032b8cba-730c-427f-b564-802600d9615d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('587657ef-9bef-4303-b9fe-41ca50a1db82', 'The 44th Amendment', false, '032b8cba-730c-427f-b564-802600d9615d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a177c45c-5660-42ec-8bcc-a750bec3c529', 'The 86th Amendment', false, '032b8cba-730c-427f-b564-802600d9615d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b554afc1-dfca-4db0-b4b0-f59f43d25a57', 'The 73rd Amendment', false, '032b8cba-730c-427f-b564-802600d9615d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6a084fda-a272-4c18-9245-9bea5d6a19d9', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'Which Fundamental Right was inserted under Article 21A by the 86th Constitutional Amendment Act in 2002, making free and compulsory education for all children aged 6 to 14 years a fundamental right?', 'Article 21A guarantees free, compulsory elementary education for children aged 6–14 as an enforceable fundamental right.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b848a7d-b9ba-4519-9f32-95138dcd5429', 'Right to Education (RTE)', true, '6a084fda-a272-4c18-9245-9bea5d6a19d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80615085-9f43-4f80-af7a-acd2cce2aa15', 'Right to Health', false, '6a084fda-a272-4c18-9245-9bea5d6a19d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d44d429-9a65-4b94-af5a-aef56617e258', 'Right to Work', false, '6a084fda-a272-4c18-9245-9bea5d6a19d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7b220cd-2e90-4f05-a940-6fdf5e48753e', 'Right to Clean Air', false, '6a084fda-a272-4c18-9245-9bea5d6a19d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8eb062dd-33ad-47b9-ab1f-e6f30a756fcc', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'Who is the ex-officio Chairman of the Rajya Sabha (Upper House of Parliament)?', 'Under Article 64, the Vice President of India is the ex-officio Chairman of the Rajya Sabha.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d51bee0b-0fa1-4ebd-86c3-ca7c7174f931', 'The Vice President of India', true, '8eb062dd-33ad-47b9-ab1f-e6f30a756fcc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db564613-27b1-4383-bf81-447690ae174c', 'The Prime Minister', false, '8eb062dd-33ad-47b9-ab1f-e6f30a756fcc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('624e4931-3a0b-430d-97c1-0f2849699a31', 'The Chief Justice of India', false, '8eb062dd-33ad-47b9-ab1f-e6f30a756fcc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('664087cd-2e4b-4ef6-b01e-cb51b2c0cbe8', 'The Lok Sabha Speaker', false, '8eb062dd-33ad-47b9-ab1f-e6f30a756fcc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a07bf27c-68ab-4424-b272-140c26cfc20f', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What are the three lists of legislative subjects in the Seventh Schedule dividing powers between the Central Union and State Governments?', 'The Seventh Schedule demarcates legislative competence: Union List (exclusive Centre), State List (exclusive States), Concurrent List (shared jurisdiction).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fbc6915-9c9d-4acd-8c5a-29cd5cc2509e', '1. Union List (Defence, Foreign Affairs, Railways) ; 2. State List (Police, Agriculture, Health) ; 3. Concurrent List (Education, Forests, Marriage)', true, 'a07bf27c-68ab-4424-b272-140c26cfc20f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed35ced8-09b2-4cd0-9d7a-a7e535c69abb', 'Civil List, Military List, Tax List', false, 'a07bf27c-68ab-4424-b272-140c26cfc20f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('764e5d91-117e-4f23-bc0b-631bc76d786e', 'Northern List, Southern List, Eastern List', false, 'a07bf27c-68ab-4424-b272-140c26cfc20f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('166e2104-d7b1-4d6f-afc2-fc609e5dbb53', 'Urban List, Rural List, Forest List', false, 'a07bf27c-68ab-4424-b272-140c26cfc20f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3e1e83c4-bbdd-4476-bac8-5fa2ea4c2466', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What historic constitutional amendments (73rd and 74th Amendments in 1992) institutionalized the third tier of local self-government in India?', 'The 73rd and 74th Amendments established three-tier Panchayati Raj (Gram, Block, Zilla) and Urban Local Bodies with mandatory reservations for women.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1eba5c7-d009-4b03-8b64-697a035427b7', 'Panchayati Raj Institutions (Rural local governance) and Urban Municipalities / Municipal Corporations', true, '3e1e83c4-bbdd-4476-bac8-5fa2ea4c2466');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42c69e22-213f-44c1-98fb-115f68d97208', 'Creation of new High Courts', false, '3e1e83c4-bbdd-4476-bac8-5fa2ea4c2466');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8a0c985-f064-42c9-8515-cb8ba87de96e', 'GST Council formation', false, '3e1e83c4-bbdd-4476-bac8-5fa2ea4c2466');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4218cebb-875d-4395-84bb-0380e0296c63', 'Abolition of Privy Purses', false, '3e1e83c4-bbdd-4476-bac8-5fa2ea4c2466');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fde8dd06-d1ff-4712-96fc-1773ab663e7f', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What is the ''Comptroller and Auditor General of India'' (CAG - Article 148), often described as the ''Guardian of the Public Purse''?', 'The CAG performs independent audit surveillance over the Consolidated Funds of Union and States, reporting to Parliament via PAC.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d0905fd-597e-4be3-a8c6-97e52e23a386', 'An independent constitutional authority that audits all receipts and expenditure of the Government of India and State Governments to ensure financial accountability', true, 'fde8dd06-d1ff-4712-96fc-1773ab663e7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7d86847-1729-4118-b94a-35fb4877f86f', 'The minister who collects income tax', false, 'fde8dd06-d1ff-4712-96fc-1773ab663e7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abda2181-1863-41d2-9b63-6237c8123fa1', 'The head of commercial banks', false, 'fde8dd06-d1ff-4712-96fc-1773ab663e7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28351e6a-bdd4-432d-b09d-b9df7969cc35', 'The manager of the stock exchange', false, 'fde8dd06-d1ff-4712-96fc-1773ab663e7f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d819e1d-108a-4a84-b124-7de3b957278b', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What is the landmark ''Basic Structure Doctrine'' formulated by the Supreme Court of India in the famous 1973 Kesavananda Bharati case?', 'The 13-judge Kesavananda Bharati bench established that constitutional amendment powers cannot dismantle the foundational basic structure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3823fbfe-b29e-4ba9-be90-07675c00ec5a', 'Parliament has the power to amend the Constitution under Article 368, but CANNOT alter, destroy, or abrogate the ''Basic Structure'' (Democracy, Secularism, Judicial Review, Rule of Law)', true, '4d819e1d-108a-4a84-b124-7de3b957278b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bdec7ce-4b41-4639-95c3-a2e5657ddcf1', 'All laws must be written in Sanskrit', false, '4d819e1d-108a-4a84-b124-7de3b957278b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e85ced3c-86fe-420b-826f-f591b1c6adc5', 'The Prime Minister cannot travel abroad', false, '4d819e1d-108a-4a84-b124-7de3b957278b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6caf589-4e3f-4c74-894d-49ae0476f040', 'Parliament cannot pass any budget', false, '4d819e1d-108a-4a84-b124-7de3b957278b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b83ac31-787a-48f3-ab34-e33b84f0687a', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What does ''Sovereign'' mean in the Preamble of the Indian Constitution?', '''Sovereign'' signifies absolute national independence and supreme jurisdictional authority free from external hegemony.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88d9c7cd-783b-41e8-ace7-b95d6eb0de40', 'India is completely independent, supreme, and free from any foreign control or external dictation in making internal and external decisions', true, '2b83ac31-787a-48f3-ab34-e33b84f0687a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e2017fb-8886-4d58-bc6c-e919872d291e', 'India is ruled by a king', false, '2b83ac31-787a-48f3-ab34-e33b84f0687a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('697fb15e-0a6d-4188-b845-69485077db1f', 'India has no borders', false, '2b83ac31-787a-48f3-ab34-e33b84f0687a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f78bd815-e69e-4576-a6b5-7c0e0b9fceaf', 'India is an island', false, '2b83ac31-787a-48f3-ab34-e33b84f0687a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7bfd394b-7f82-44da-87a8-12c88051a738', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What does ''Secular'' mean in the context of the Indian democratic model (Sarva Dharma Sambhava)?', 'Indian secularism maintains principled distance and equal patronage towards all faiths, protecting religious freedoms under Articles 25–28.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52b79f1d-f8e9-4207-8e06-37367a1d1ebc', 'The State has no official state religion and accords equal respect, protection, and freedom to all religions without discriminating against any citizen', true, '7bfd394b-7f82-44da-87a8-12c88051a738');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93a7847b-e877-41ca-9a94-8c03ca4e64ca', 'The State bans all religions', false, '7bfd394b-7f82-44da-87a8-12c88051a738');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79bc2b73-b911-46ae-a911-f9c743fdef82', 'Only one religion is allowed in schools', false, '7bfd394b-7f82-44da-87a8-12c88051a738');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd58e487-e065-40bd-ae8d-663ad67cee7e', 'Citizens are not allowed to pray', false, '7bfd394b-7f82-44da-87a8-12c88051a738');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96ceef00-6f26-45d9-b183-a7ce05dd2c76', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'How is the President of India elected?', 'Article 54: The President is elected through proportional representation with single transferable vote by elected MPs and MLAs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('283a4706-0a88-4e53-8601-5c008aec8411', 'Indirectly by an Electoral College consisting of elected members of both Houses of Parliament (Lok Sabha & Rajya Sabha) and elected MLAs of all State Legislative Assemblies', true, '96ceef00-6f26-45d9-b183-a7ce05dd2c76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38218c15-916e-435f-bb5b-039ee1ffa8c7', 'Direct voting by all citizens', false, '96ceef00-6f26-45d9-b183-a7ce05dd2c76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72e31892-7d2d-45c0-b43d-ed3882f07565', 'Nominated by the Supreme Court', false, '96ceef00-6f26-45d9-b183-a7ce05dd2c76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac6c638f-ab44-453c-a5f2-d07f495a1b3e', 'Selected by previous President', false, '96ceef00-6f26-45d9-b183-a7ce05dd2c76');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d17771bf-55c4-4284-b990-1a92b08630c3', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What is the maximum strength of members in the Lok Sabha permitted by the Constitution?', 'Article 81: Lok Sabha maximum ceiling is 550 (up to 530 from States, up to 20 from UTs; Anglo-Indian nomination was discontinued by 104th Amendment).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a596248b-8b37-4fcb-a8f6-107479c7f010', '550 members (representing States and Union Territories)', true, 'd17771bf-55c4-4284-b990-1a92b08630c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cbe8e71-eb26-43a6-9564-2aba11448679', '250 members', false, 'd17771bf-55c4-4284-b990-1a92b08630c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bb9d348-4bee-4ed1-9a95-3642d425b455', '100 members', false, 'd17771bf-55c4-4284-b990-1a92b08630c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('732680b2-7cb2-4b28-8990-17b6691ad32b', '700 members', false, 'd17771bf-55c4-4284-b990-1a92b08630c3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59eb5932-8db4-4be4-ae18-fe98be8bfb40', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What is the maximum strength of members in the Rajya Sabha?', 'Article 80: Rajya Sabha has up to 250 members: 238 state/UT representatives and 12 presidential nominees with specialized eminence.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b343a8b-3a03-47c9-bc6e-ce83591fae7e', '250 members (238 elected from States/UTs + 12 nominated by the President for literature, science, art, and social service)', true, '59eb5932-8db4-4be4-ae18-fe98be8bfb40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('799d6055-2737-420d-acea-f52c09f3b229', '550 members', false, '59eb5932-8db4-4be4-ae18-fe98be8bfb40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8c92ede-86f8-4321-9ace-1537670938b4', '300 members', false, '59eb5932-8db4-4be4-ae18-fe98be8bfb40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77ef8b5c-4cb8-47a5-9e54-89ac9efc7369', '150 members', false, '59eb5932-8db4-4be4-ae18-fe98be8bfb40');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('522f316b-d33c-4280-b0e8-dc14ef4a1b3b', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What is a ''Money Bill'' in the Indian Parliament, and which House has exclusive, overriding authority over it?', 'Money bills originate exclusively in the Lok Sabha; the Rajya Sabha has only 14 days to suggest non-binding recommendations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9646d999-065b-4536-b2b2-7b834e863d42', 'A Bill dealing with taxation and government expenditure (Article 110) ; it can ONLY be introduced in the LOK SABHA with the prior recommendation of the President', true, '522f316b-d33c-4280-b0e8-dc14ef4a1b3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae316cc6-c23e-499f-aa31-e30f92031c8f', 'A bill that can only be introduced in Rajya Sabha', false, '522f316b-d33c-4280-b0e8-dc14ef4a1b3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12a7df93-62a3-4449-bb77-b0f52de82014', 'A bill passed by the Supreme Court', false, '522f316b-d33c-4280-b0e8-dc14ef4a1b3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('168e1c1d-124f-4de6-a1cf-a3bba2e03575', 'A bill passed by municipal ward councils', false, '522f316b-d33c-4280-b0e8-dc14ef4a1b3b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('83422d26-6ac4-4ab1-8890-d44380708aeb', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What is ''Judicial Review'' exercised by the Supreme Court and High Courts of India?', 'Articles 13, 32, and 226 empower the higher judiciary to invalidate ultra vires statutes violating constitutional mandates.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1833cfb-00aa-4220-aa0f-8fdacc60a4de', 'The constitutional power to examine the constitutional validity of legislative enactments and executive orders, and declare them NULL and VOID if they violate Fundamental Rights', true, '83422d26-6ac4-4ab1-8890-d44380708aeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2e519d4-fd04-4724-b66c-04e429080e22', 'The power of judges to change their salaries', false, '83422d26-6ac4-4ab1-8890-d44380708aeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10396055-c68d-41eb-aec9-57b8b7388876', 'The right of the police to make laws', false, '83422d26-6ac4-4ab1-8890-d44380708aeb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e63669a-ea08-45a5-8264-9779cf8dc982', 'The review of school exam papers', false, '83422d26-6ac4-4ab1-8890-d44380708aeb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4402c918-339d-4528-82bf-fcc3a0cfdaf3', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Medium', 'What is the ''Right to Information'' (RTI) Act passed by the Indian Parliament in 2005?', 'The RTI Act (2005) enforces participatory transparency, enabling citizens to inspect government files and demand institutional accountability.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2c735d1-b5f1-46e9-b992-e150f909c645', 'A landmark transparency law empowering citizens to request and receive certified information from public authorities, curbing corruption and promoting accountability', true, '4402c918-339d-4528-82bf-fcc3a0cfdaf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad5e3b5a-8a54-4f4b-b8d4-7549153e7009', 'A law that bans newspapers', false, '4402c918-339d-4528-82bf-fcc3a0cfdaf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a67bfd62-8093-4fe7-8bb1-ee28b92d865c', 'A secret government code', false, '4402c918-339d-4528-82bf-fcc3a0cfdaf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54979b3e-d0c1-4441-8386-ea4d0d4379ce', 'A rule on television commercials', false, '4402c918-339d-4528-82bf-fcc3a0cfdaf3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a87bfef0-d2e9-4810-986b-37134a98cc90', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e8f4baf-e8ff-45a0-ab2b-7140fa4583b9', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'a87bfef0-d2e9-4810-986b-37134a98cc90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('856881da-6808-4136-8224-545d54bf2c02', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'a87bfef0-d2e9-4810-986b-37134a98cc90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('688ecbb9-cd9f-44cd-9774-d258d92e6ebb', '(A) is true, but (R) is false.', false, 'a87bfef0-d2e9-4810-986b-37134a98cc90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1233506a-30dc-4080-a0c8-4c9f86af86fe', '(A) is false, but (R) is true.', false, 'a87bfef0-d2e9-4810-986b-37134a98cc90');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4d22f14-196e-439d-8b20-d5bd43b9be33', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'Spot the IMPOSTER in the following constitutional bodies and their corresponding Articles in the Indian Constitution:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('259e890e-d7f9-4b9d-a134-238ecc807d70', 'Body 1', false, 'c4d22f14-196e-439d-8b20-d5bd43b9be33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea1467d9-884e-473a-950a-fe103fd84b2f', 'Body 2', false, 'c4d22f14-196e-439d-8b20-d5bd43b9be33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa76257d-aac1-4964-87e7-e05072628fba', 'Body 3', false, 'c4d22f14-196e-439d-8b20-d5bd43b9be33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa320d20-5066-4680-be90-bf76aa953ae6', 'Body 4 (The Finance Commission is constituted under ARTICLE 280, not Article 500 ; the Constitution has only 395 original articles)', true, 'c4d22f14-196e-439d-8b20-d5bd43b9be33');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d8b1a4e-2d04-4103-8904-3f48d6e8aefb', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'Match Column I (Constitutional Writs under Articles 32 and 226) with Column II (Latin Meanings and Applications):
(a) Habeas Corpus -> (i) ''To have the body'' (releases a person unlawfully detained by state/police)
(b) Mandamus      -> (ii) ''We Command'' (orders a public official to perform their mandatory statutory duty)
(c) Prohibition   -> (iii) Orders a lower court/tribunal to cease proceedings exceeding its jurisdiction
(d) Quo-Warranto  -> (iv) ''By what warrant'' (inquires into the legality of a person holding a public office)', 'Habeas Corpus = personal liberty; Mandamus = public duty command; Prohibition = jurisdiction restraint; Quo-Warranto = title to public office.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4245ef32-f61d-4a72-817c-eec0b0236af7', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '3d8b1a4e-2d04-4103-8904-3f48d6e8aefb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6031e92-c75b-47c2-a914-a3585cbe5c26', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '3d8b1a4e-2d04-4103-8904-3f48d6e8aefb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b4e6e72-c102-4411-b3a0-d1ebfd4b2a53', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '3d8b1a4e-2d04-4103-8904-3f48d6e8aefb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d650346-d923-4f87-86d0-18ea5e05e3b3', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '3d8b1a4e-2d04-4103-8904-3f48d6e8aefb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19348836-e763-4f63-a6d4-4044ca5e01d1', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'Read the statements regarding the Emergency Provisions in the Indian Constitution (Part XVIII):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc2cd713-27d1-4c65-b99a-7577ee5585bd', 'Statements 1 and 2 only', true, '19348836-e763-4f63-a6d4-4044ca5e01d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a532564b-622c-4669-bc21-8b2a5050baff', 'Statements 2 and 3 only', false, '19348836-e763-4f63-a6d4-4044ca5e01d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5130d8e-95e2-480a-9b07-248a2cf20e5d', 'Statements 1 and 3 only', false, '19348836-e763-4f63-a6d4-4044ca5e01d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6fff7bc-eeb2-4010-b33b-bd202a744a5e', 'All Statements 1, 2, and 3', false, '19348836-e763-4f63-a6d4-4044ca5e01d1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1df9d119-0a0c-4328-99d0-9f934bc535b9', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'What constitutes the ''Doctrine of Separation of Powers'' embedded with ''Checks and Balances'' in Indian parliamentary democracy?', 'Indian tripartite governance balances functional separation with mutual accountability (judicial review of laws, legislative oversight of ministers).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('664c2aa4-fcf4-4313-8512-c865ff20ab08', 'The Legislature makes laws, the Executive implements laws, and the Judiciary interprets laws and invalidates unconstitutional actions, ensuring no branch exercises absolute tyranny', true, '1df9d119-0a0c-4328-99d0-9f934bc535b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f67fce32-4f00-4646-96ec-d3daa4464f08', 'The army controls all political leaders', false, '1df9d119-0a0c-4328-99d0-9f934bc535b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf8af574-d51d-4d07-b51a-200a6a478ba3', 'The President writes all court judgments', false, '1df9d119-0a0c-4328-99d0-9f934bc535b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1de41367-4a14-4552-aa70-1a6748393cbf', 'Ministers serve as judges in court', false, '1df9d119-0a0c-4328-99d0-9f934bc535b9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ee8e1829-1496-4efe-9255-89c3054bff1c', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'What is the procedure for the IMPEACHMENT of the President of India under Article 61 of the Constitution?', 'Article 61 prescribes stringent two-thirds total membership super-majority in both Houses for presidential impeachment on constitutional violations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aca00c49-5a2d-4cd5-afbd-8f2694397ccc', 'A quasi-judicial resolution passed by a special majority of NOT LESS THAN TWO-THIRDS of the total membership of both Houses of Parliament on grounds of ''Violation of the Constitution''', true, 'ee8e1829-1496-4efe-9255-89c3054bff1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e1cc5be-626e-49a1-a344-5396684c0bf0', 'A simple majority vote in Lok Sabha only', false, 'ee8e1829-1496-4efe-9255-89c3054bff1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c8e8f1e-1000-4de0-a99f-f2ac09606b68', 'An order passed by the Chief Justice of India', false, 'ee8e1829-1496-4efe-9255-89c3054bff1c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20bd9a18-0199-4393-b7c5-59d9b65186b5', 'A public referendum', false, 'ee8e1829-1496-4efe-9255-89c3054bff1c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9806547b-365e-49bf-a15a-910a4e9be554', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'Consider four features of the Indian Constitution:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('538160e5-9f0e-478e-a8f1-9e3bfaea0f81', 'A masterful comparative constitutional achievement that adapted the world''s finest democratic practices to India''s unique civilizational pluralism', true, '9806547b-365e-49bf-a15a-910a4e9be554');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33a6936b-758f-4f75-93a8-32ca62d1fb0b', 'A careless copy of other countries'' rules', false, '9806547b-365e-49bf-a15a-910a4e9be554');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1aba0c7c-ad07-49b1-8262-0d8d78448b39', 'An accidental document created in a few days', false, '9806547b-365e-49bf-a15a-910a4e9be554');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5fa4d16-14d5-4122-b6ca-2b5c031d848b', 'A document that applies only to cities', false, '9806547b-365e-49bf-a15a-910a4e9be554');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f033692-a924-4675-a54e-66b61697a7d3', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'What is the significance of the 101st Constitutional Amendment Act (2016) in Indian cooperative fiscal federalism?', 'The 101st Amendment revolutionized indirect taxation via ''One Nation, One Tax'', creating the federal consensus GST Council.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb1f48b5-cbfd-4c80-beac-330ef308a766', 'The introduction of the unified Goods and Services Tax (GST) and the constitutional establishment of the joint Centre-State GST Council (Article 279A)', true, '8f033692-a924-4675-a54e-66b61697a7d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d7116fd-d953-4ecb-b319-94d6cff5dc88', 'The nationalization of private banks', false, '8f033692-a924-4675-a54e-66b61697a7d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7a8e50e-d2b3-4e14-b1f0-a50c6359c624', 'The abolition of states', false, '8f033692-a924-4675-a54e-66b61697a7d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fbfccd8-7d74-42cd-9713-db21abcbf627', 'The introduction of a new national anthem', false, '8f033692-a924-4675-a54e-66b61697a7d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f83d3b3c-b338-462a-9df5-0f58f1b031da', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'What is the constitutional role of the ''Attorney General for India'' (Article 76)?', 'The Attorney General is the principal legal advisor to the Union and represents the Union Government in supreme appellate litigation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c344963a-1379-40c3-a0e9-28f9cc7f9cc8', 'The highest law officer of the Government of India, appointed by the President, who gives legal counsel to the Union government and has the right of audience in all courts in India', true, 'f83d3b3c-b338-462a-9df5-0f58f1b031da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f2f01e7-3732-4152-b0b0-80b3e22a4ae2', 'The chief of police', false, 'f83d3b3c-b338-462a-9df5-0f58f1b031da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61e5f729-558d-401d-b2fa-c74eb194dc05', 'The commander of the navy', false, 'f83d3b3c-b338-462a-9df5-0f58f1b031da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3852c002-f2f5-46ad-8cc2-84c6f11ee6b1', 'The governor of the Reserve Bank', false, 'f83d3b3c-b338-462a-9df5-0f58f1b031da');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae3b5120-3c84-47ee-afaf-a1a869332bd2', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'Why is Article 21 (Protection of Life and Personal Liberty) regarded as the expansive cornerstone of human rights jurisprudence in India?', 'The Supreme Court expanded Article 21 to enshrine substantive due process, privacy, environmental rights, and human dignity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27eb37f1-f4b2-416c-9445-c792b8edc944', 'Through progressive judicial interpretations (Maneka Gandhi, Puttaswamy cases), it now encompasses the Right to Privacy, Right to Clean Environment, Right to Livelihood, and Right to Dignity', true, 'ae3b5120-3c84-47ee-afaf-a1a869332bd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fda755d3-ba86-4b33-999d-357f8e13f79a', 'It allows citizens to break traffic laws', false, 'ae3b5120-3c84-47ee-afaf-a1a869332bd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb7ab075-a3e8-4702-89a6-d2d3d2988b27', 'It guarantees free movie tickets', false, 'ae3b5120-3c84-47ee-afaf-a1a869332bd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e725223-9c5e-4e96-b877-69fe4861d3c4', 'It applies only to foreign ambassadors', false, 'ae3b5120-3c84-47ee-afaf-a1a869332bd2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8544c875-89d9-43c7-990b-92ab380506ac', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'What was the landmark 106th Constitutional Amendment Act (Nari Shakti Vandan Adhiniyam) passed by Parliament in 2023?', 'The 106th Amendment mandates 33% constitutional reservation for women in legislative bodies to enhance democratic gender parity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e1325bd-b7f8-4394-a21a-df9719fb720d', 'Reserving 33% (one-third) of seats for WOMEN in the Lok Sabha, State Legislative Assemblies, and the Delhi Legislative Assembly', true, '8544c875-89d9-43c7-990b-92ab380506ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0448c60-26cc-4bd9-8f26-6460ec65cdf1', 'Making women eligible for driving licenses', false, '8544c875-89d9-43c7-990b-92ab380506ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8387aaa-cd62-465d-86e9-35d4dfd760db', 'Abolishing all taxes for women', false, '8544c875-89d9-43c7-990b-92ab380506ac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5ad023f-dad8-494b-b562-1df3b343b9f2', 'Granting free electricity to women', false, '8544c875-89d9-43c7-990b-92ab380506ac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('abb8d4e3-c6b6-4513-a970-070055413afc', 'Class 7', 'GK', 'Chapter 7: Indian Polity, Constitution, Fundamental Rights & Governance', 'Hard', 'What core vision of constitutional patriotism and civic responsibility is established in Chapter 7 of General Knowledge?', 'Chapter 7 synthesizes constitutional democracy, rule of law, institutional checks and balances, and civic empowerment in the Republic of India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4306e5b8-ad2d-4415-a564-12f2de723e8f', 'The Constitution is a living, sacred covenant of sovereign democratic self-governance, requiring vigilant citizens who cherish liberty, protect equality, defend institutional integrity, and fulfill their fundamental duties', true, 'abb8d4e3-c6b6-4513-a970-070055413afc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b203e42-0ebe-431a-bdb0-544bbc19660c', 'That the Constitution is an unchangeable ancient stone that citizens should ignore', false, 'abb8d4e3-c6b6-4513-a970-070055413afc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e45456b8-4092-4725-9f1a-3c4487bad934', 'That democracy works without citizens taking part in elections', false, 'abb8d4e3-c6b6-4513-a970-070055413afc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('105458b4-ba37-405a-92d5-a85d87ab54b6', 'That laws apply only to the poor', false, 'abb8d4e3-c6b6-4513-a970-070055413afc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e569f492-41a3-40b7-8ea0-ed226dd5815f', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'What distinct social organization characterized tribal societies compared to the caste-based (Varna) societies of medieval India?', 'Tribal communities organized social life around kinship bonds, communal land ownership, and egalitarian clan structures without Brahmanical varna hierarchies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a8de0b6-c6d1-427b-b0ad-b983d6903250', 'Tribal societies did NOT follow rigid social rules and caste divisions prescribed by Brahmans; they were organized into egalitarian kinship / clan groups with shared natural resources', true, 'e569f492-41a3-40b7-8ea0-ed226dd5815f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e166ecc3-f6e9-4794-b797-2f0e8c23c75a', 'They had hundreds of rigid sub-castes', false, 'e569f492-41a3-40b7-8ea0-ed226dd5815f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c843fc5-2f79-4947-97f6-449087a087c8', 'They lived only in marble palaces', false, 'e569f492-41a3-40b7-8ea0-ed226dd5815f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27212103-843e-43b6-9875-49f9d7721745', 'They were ruled by foreign emperors', false, 'e569f492-41a3-40b7-8ea0-ed226dd5815f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30ab2b5c-aa41-4d25-9270-fe20372118fa', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'Which vast forested region of central India (comprising modern Madhya Pradesh, Chhattisgarh, and Maharashtra) was the homeland of the GONDS?', 'Gondwana was the historical central Indian forest region where Gond kingdoms practiced shifting cultivation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a6ca012-f610-436f-af47-ceb14f0c4821', 'Gondwana (''Country inhabited by Gonds'')', true, '30ab2b5c-aa41-4d25-9270-fe20372118fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60099636-4f95-4cb5-9377-75961b42e5cd', 'Brahmaputra Valley', false, '30ab2b5c-aa41-4d25-9270-fe20372118fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a005a3f9-d372-4e7c-95db-9a5a523683e9', 'Thar Desert', false, '30ab2b5c-aa41-4d25-9270-fe20372118fa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1aea00d-aa63-436e-963c-66454a39e759', 'Konkan Coast', false, '30ab2b5c-aa41-4d25-9270-fe20372118fa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eba365f2-fbe7-4b2c-a921-4ed2d3ce36c0', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'What rich Gond kingdom mentioned in the Akbar Nama contained 70,000 villages and grew wealthy by exporting wild elephants to other kingdoms?', 'Garha Katanga was a prosperous Gond kingdom ruling 70,000 villages, enriched through the capture and export of wild elephants.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f94ac077-0060-47d0-8d3b-d8ce7e9ac9f6', 'Garha Katanga', true, 'eba365f2-fbe7-4b2c-a921-4ed2d3ce36c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5749bb74-f929-45aa-aff2-539bbfee63d8', 'Chanda', false, 'eba365f2-fbe7-4b2c-a921-4ed2d3ce36c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a57e4ffe-5f93-436d-9d40-19c2c7d05a70', 'Deogarh', false, 'eba365f2-fbe7-4b2c-a921-4ed2d3ce36c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90c59b1b-ee85-4423-a8b4-1b20872bdbd8', 'Kherla', false, 'eba365f2-fbe7-4b2c-a921-4ed2d3ce36c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a45993ee-91f9-4677-98b6-b5c7f03a33ef', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'Which brave, heroic Rajput princess married the Gond King Dalpat and ruled Garha Katanga on behalf of her young son Bir Narain, dying in battle against the Mughal general Asaf Khan in 1565?', 'Rani Durgavati of Garha Katanga (daughter of Chandel king Salbahan) fought valiantly against Asaf Khan''s Mughal invasion until her martyrdom.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7a0e5a9-f515-4c2f-a734-672b4f75b8f8', 'Rani Durgavati', true, 'a45993ee-91f9-4677-98b6-b5c7f03a33ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53676f7e-b710-40a1-9f1e-79ea2bbe2f94', 'Rani Lakshmibai', false, 'a45993ee-91f9-4677-98b6-b5c7f03a33ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9f1ee21-6565-40e8-90ec-c3420bdb05f4', 'Rani Padmini', false, 'a45993ee-91f9-4677-98b6-b5c7f03a33ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d442b30d-2ce1-4f09-adce-1258a20b3b48', 'Rani Rudrama Devi', false, 'a45993ee-91f9-4677-98b6-b5c7f03a33ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4cfafc3-79de-4b01-867c-96948be2f790', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'Which powerful tribal community migrated from present-day Myanmar into the Brahmaputra River valley (Assam) in the 13th century, establishing a flourishing independent state?', 'The Tai-Ahom people under Sukapha settled the upper Brahmaputra valley in 1228 CE, creating the mighty Ahom kingdom.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15e18c1b-5c96-4cf9-99cf-5df6de5e74d2', 'The Ahoms (led by Chaolung Sukapha)', true, 'd4cfafc3-79de-4b01-867c-96948be2f790');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5983d9df-b53b-446f-8e35-f6ef965396d3', 'The Gonds', false, 'd4cfafc3-79de-4b01-867c-96948be2f790');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca78b90e-cc55-41c3-ada5-8df859410330', 'The Bhils', false, 'd4cfafc3-79de-4b01-867c-96948be2f790');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83798182-8da9-4c52-9915-e7b5be94da21', 'The Santhals', false, 'd4cfafc3-79de-4b01-867c-96948be2f790');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc2a6d53-92e0-4705-91ab-2dca8a6349f0', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'What were historical historical chronicles and official state records written in the Ahom language and later in Assamese called?', 'Buranjis are the invaluable historical chronicles written by Ahom court scribes recording political and diplomatic history.', NOW()) ON CONFLICT DO NOTHING;
