INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a603abec-73f3-41ed-aa06-c205a4359244', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'In the Ahom state, what were the adult male villagers who were legally obliged to render compulsory rotational labor for public works called?', 'Under the Ahom Paik system, each village supplied rotational corvée laborers (Paiks) for constructing dykes, canals, and military service.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3792f758-33da-402d-8f0a-6ba5eb6c8bc9', 'Paiks', true, 'a603abec-73f3-41ed-aa06-c205a4359244');
