INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52823237-fb34-4450-936b-93b22a48bddd', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'In Ahom society, what were the clans or collective administrative units that controlled several villages called?', 'A Khel was a clan-based corporate unit commanding specific Paiks and distributing village land.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fde7ac0a-03bb-449e-abab-8eea5ba6e4d6', 'Khels', true, '52823237-fb34-4450-936b-93b22a48bddd');
