INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ca2eb01-793c-4a46-bdd9-e75dfcfac843', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'Which major warrior tribes dominated the Punjab region during the 13th and 14th centuries (whose chief Kamal Khan Gakkhar was made a noble by Akbar)?', 'The Khokhars and Gakkhars were influential martial tribes of Punjab; Emperor Akbar appointed Gakkhar chief Kamal Khan as a high Mansabdar.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6910f3fb-0d8f-4be1-9328-68ca55798aaa', 'Khokhars and Gakkhars', true, '1ca2eb01-793c-4a46-bdd9-e75dfcfac843');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9a1fa5d-7c3c-444a-b8f8-76dbfed33e83', 'Bhils and Kolis', false, '1ca2eb01-793c-4a46-bdd9-e75dfcfac843');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef3d069d-2c91-41d5-93e0-b1b710aed6fc', 'Ahoms and Nagas', false, '1ca2eb01-793c-4a46-bdd9-e75dfcfac843');
