INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ce7d45f-686c-4a24-b3de-cf1e63e6bdb2', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'Which large tribal group inhabited the forested hilly regions of the Western Ghats and Central India across Rajasthan, Gujarat, and Maharashtra?', 'The Bhils spread across the Western Ghats and Vindhyas, transitioning between hunter-gathering, shifting farming, and archery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5634b71b-d2b1-409e-a53c-4d84589b8a84', 'The Bhils (and Kolis)', true, '1ce7d45f-686c-4a24-b3de-cf1e63e6bdb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b640e7c-5ed6-46de-9d12-1af3ee63423d', 'The Ahoms', false, '1ce7d45f-686c-4a24-b3de-cf1e63e6bdb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2b6a16c-7b89-445d-93cb-f1ac9161cf2a', 'The Gakkhars', false, '1ce7d45f-686c-4a24-b3de-cf1e63e6bdb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dba77047-90a6-4753-a4fd-5bfd8ac28efb', 'The Cheros', false, '1ce7d45f-686c-4a24-b3de-cf1e63e6bdb2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('51b7bdce-1aa5-4182-a908-6868e5d3e67b', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'What agricultural method involving cutting and burning trees and bushes in forest plots to plant crops in the fertile ash for a few years was practiced by Gonds?', 'Shifting cultivation (slash-and-burn) was the traditional agrarian system of forest-dwelling tribal communities like the Gonds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('962ac6dc-2a2e-494b-94f8-20faec2fcce9', 'Shifting Cultivation (Jhum / Podu)', true, '51b7bdce-1aa5-4182-a908-6868e5d3e67b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7aef4098-1331-48ff-b163-971d3581a99c', 'Terrace Farming only', false, '51b7bdce-1aa5-4182-a908-6868e5d3e67b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30c55819-784a-43e1-a91f-3a13e7852cb9', 'Hydroponics', false, '51b7bdce-1aa5-4182-a908-6868e5d3e67b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('907ae3e7-6fe4-4cd5-aa7b-5de680116756', 'Plantation Farming', false, '51b7bdce-1aa5-4182-a908-6868e5d3e67b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('44df1553-b230-49d8-9d8e-4ca21f4f7b62', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Easy', 'Which pastoral shepherd tribe lived in the western Himalayas (Himachal Pradesh), migrating with sheep and goat herds according to seasons?', 'The Gaddis are transhumant pastoral shepherds of the western Himalayas migrating between alpine meadows and valley winters.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63c5e4d9-02b8-4562-a807-ed3b85b1b4fb', 'Gaddis (and Gujjar Bakarwals)', true, '44df1553-b230-49d8-9d8e-4ca21f4f7b62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c45464b0-8b93-4e19-b7b2-5c55b8b621ff', 'Ahoms', false, '44df1553-b230-49d8-9d8e-4ca21f4f7b62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff58bdf3-00ae-4cd2-8a22-1a18b678e919', 'Gonds', false, '44df1553-b230-49d8-9d8e-4ca21f4f7b62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64e14bfd-4f9a-4d1f-8330-27d92a4a2ab1', 'Cheros', false, '44df1553-b230-49d8-9d8e-4ca21f4f7b62');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2a676a6-6014-4de4-b7d5-b0027064c2aa', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'What was the administrative division hierarchy of the centralized Gond kingdom of Garha Katanga?', 'Gond administrative structure: Garh (clan territory) → Chaurasi (84 villages) → Barhot (12 villages).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('629fb84b-9ed0-4562-bfaf-35312b7bc28b', 'Kingdom was divided into Garhs (controlled by Gond clans) ; each Garh was divided into Chaurasis (units of 84 villages) ; each Chaurasi was subdivided into Barhots (units of 12 villages)', true, 'c2a676a6-6014-4de4-b7d5-b0027064c2aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7860bbe9-a37a-48e7-b7e6-fb9ce3c23b5c', 'Kingdom -> Suba -> Sarkar -> Pargana', false, 'c2a676a6-6014-4de4-b7d5-b0027064c2aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55180631-0850-46e6-9416-b9bc032caf98', 'Kingdom was divided into 1,000 islands', false, 'c2a676a6-6014-4de4-b7d5-b0027064c2aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5aa8b623-11d7-411b-8646-b401955920b6', 'Kingdom had no divisions', false, 'c2a676a6-6014-4de4-b7d5-b0027064c2aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f396bae-4b8d-4977-996c-15e7ff913e50', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'Why did the Gond Raja of Garha Katanga, Aman Das, adopt the prestigious title of ''Sangram Shah''?', 'Gond chieftains Sanskritized their identity (Rajputization) by assuming Kshatriya titles (Sangram Shah) and forming Rajput matrimonial alliances.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd996f47-9fad-4352-9e47-f99ac42297f5', 'To elevate his social and political status to that of a Kshatriya / Rajput ruler, seeking parity with established northern dynasties', true, '4f396bae-4b8d-4977-996c-15e7ff913e50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f876cd4-8592-441a-871e-aa90b3fc1d47', 'Because he won an Olympic medal', false, '4f396bae-4b8d-4977-996c-15e7ff913e50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae571ab7-b651-4e04-81bd-e68be4250950', 'Because the British gave him the title', false, '4f396bae-4b8d-4977-996c-15e7ff913e50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25866b30-9f4b-467d-a68e-628311d70dbc', 'Because he moved to Europe', false, '4f396bae-4b8d-4977-996c-15e7ff913e50');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c7ed4a7-3e71-47b0-b023-a7aed519a823', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'How did the introduction of advanced Gunpowder and Firearms in the 16th century transform the military strength of the Ahom kingdom?', 'The Ahoms developed advanced indigenous pyrotechnic ballistics, manufacturing high-grade gunpowder and cannons from the 1530s.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1a07642-7b3c-46f0-bf53-283ca213c1ce', 'The Ahoms quickly mastered metallurgy to manufacture high-quality gunpowder and cast heavy bronze cannons as early as the 1530s, successfully repelling numerous invasions', true, '5c7ed4a7-3e71-47b0-b023-a7aed519a823');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1b50fbf-aaa4-4bb5-be00-9a10b9cd711a', 'They bought weapons from China only', false, '5c7ed4a7-3e71-47b0-b023-a7aed519a823');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7a844dd-b139-44fc-ac5e-adf4218d58b9', 'Gunpowder destroyed the Ahom kingdom immediately', false, '5c7ed4a7-3e71-47b0-b023-a7aed519a823');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b57496c-6252-4c43-a0b8-aa447af85ca7', 'They banned all weapons', false, '5c7ed4a7-3e71-47b0-b023-a7aed519a823');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('013f0e58-631b-4f1a-bc3c-427575dfc600', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'Under which Mughal general was an army sent in 1662 to invade the Ahom kingdom, capturing the capital Garhgaon after fierce Ahom resistance?', 'Mir Jumla captured Garhgaon in 1662, but protracted guerrilla warfare and monsoon pestilence forced a Mughal treaty.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8caef560-e5ae-406c-8c26-b90137edf908', 'Mir Jumla (Governor of Bengal under Aurangzeb)', true, '013f0e58-631b-4f1a-bc3c-427575dfc600');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de009562-7543-42e5-ab6f-1e5b8a3a6e4a', 'Raja Man Singh', false, '013f0e58-631b-4f1a-bc3c-427575dfc600');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2049a043-4a31-485c-9e43-7fbd26620b89', 'Bairam Khan', false, '013f0e58-631b-4f1a-bc3c-427575dfc600');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bae4b45-02a0-436e-a366-1a60df4d3691', 'Shaista Khan', false, '013f0e58-631b-4f1a-bc3c-427575dfc600');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e91abe9-16ac-46bf-b0ef-44a38c507125', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'Under which great Ahom King (reigned 1696–1714) did Hinduism become the predominant religion, while Ahom kings retained their traditional Tai cultural customs?', 'King Rudra Singha patronized Brahmanical Vaishnavism and built the grand amphitheater Rang Ghar while preserving Tai ancestral rituals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a790d1f8-a7ce-45dd-a9af-cbaa5b551a21', 'Rudra Singha (Sukhrungphaa)', true, '6e91abe9-16ac-46bf-b0ef-44a38c507125');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e05a3d4f-b280-41fb-83c8-8235e6a4f7ca', 'Sukapha', false, '6e91abe9-16ac-46bf-b0ef-44a38c507125');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26679785-dffb-4a12-aa4d-3535ed25a7d8', 'Pratap Singha', false, '6e91abe9-16ac-46bf-b0ef-44a38c507125');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5e49248-3de2-4010-94df-27b87f9f7b01', 'Gadadhar Singha', false, '6e91abe9-16ac-46bf-b0ef-44a38c507125');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f2e8231-75dc-4597-bba4-647429d0c2c1', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'What was the ''Tanda'' of the Banjaras described in Emperor Jahangir''s memoirs (Tuzuk-i Jahangiri)?', 'Jahangir recorded that Banjaras transported grain on bullocks from villages into towns: ''A tanda consists of many families... moving up to 100,000 oxen''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd944982-bc31-4c5a-b1ea-2a2f2b1a5a12', 'A massive mobile nomadic convoy/caravan of Banjara trader families moving with thousands of pack-bullocks loaded with grain to sell in town markets and provision Mughal armies', true, '8f2e8231-75dc-4597-bba4-647429d0c2c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c04bd313-147d-44bb-9228-ed7d2c243549', 'A musical instrument', false, '8f2e8231-75dc-4597-bba4-647429d0c2c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a886724e-9efc-406f-9bc5-49c0935e59df', 'A stone fort in the forest', false, '8f2e8231-75dc-4597-bba4-647429d0c2c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('628b8bee-96a0-4bda-a164-063ccea1571e', 'A type of food', false, '8f2e8231-75dc-4597-bba4-647429d0c2c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab3b12dc-29c3-47a1-b767-afca9f09ea12', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'How did economic exchange operate between Pastoral Nomads and settled agricultural villagers?', 'Symbiotic rural-pastoral barter: pastoralists bartered pastoral commodities (ghee, wool, pack-animals) for agrarian food grains and textiles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efafb458-9d45-4859-9ae6-3127be6b0a75', 'Pastoral nomads exchanged animal products (ghee, wool, hides, milk) with settled farmers in return for agricultural grain, cloth, metal utensils, and salt', true, 'ab3b12dc-29c3-47a1-b767-afca9f09ea12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b9a1529-8414-4481-b360-d3c5d9d6b9d7', 'They had no contact with farmers', false, 'ab3b12dc-29c3-47a1-b767-afca9f09ea12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('000804a1-bc19-41d2-9c75-a42c211792fb', 'Nomads gave gold and bought land', false, 'ab3b12dc-29c3-47a1-b767-afca9f09ea12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cc46846-43bb-4e52-9374-0be2b0649a1d', 'Farmers became nomads every winter', false, 'ab3b12dc-29c3-47a1-b767-afca9f09ea12');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('161e2f63-5407-44ea-93f3-7263aaf9a0df', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'Which powerful tribal chieftaincy in Bihar and Jharkhand was attacked and defeated by Akbar''s general Raja Man Singh in 1591, yielding vast booty?', 'Raja Man Singh defeated the Chero chief in 1591, seizing wealth and elephants, though complete subjugation occurred under Aurangzeb.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36664a2d-cc0d-449b-a2ea-d30c2a2fbf1c', 'The Cheros', true, '161e2f63-5407-44ea-93f3-7263aaf9a0df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6dba6c3-672f-40c5-8584-a60dc9bb2714', 'The Santhals', false, '161e2f63-5407-44ea-93f3-7263aaf9a0df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e527eb64-b98b-4264-a85d-189f62bd0ab8', 'The Ahoms', false, '161e2f63-5407-44ea-93f3-7263aaf9a0df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89fe5ff0-6258-4352-b7ea-db6e8e99515b', 'The Gakkhars', false, '161e2f63-5407-44ea-93f3-7263aaf9a0df');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dbf873bc-46dd-46fc-b417-4c090bfca40e', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'How did the proliferation of specialized crafts and professional occupational groups lead to the emergence of ''JATIS'' (sub-castes) within the Varna system?', 'Economic diversification spawned Jatis: specialized artisanal, mercantile, and tribal communities were accommodated as discrete jatis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cfd15ee-638f-4b4e-a149-215f6c45ffa5', 'As the economy grew more complex, specialized occupational groups (smiths, carpenters, masons, sculptors) were recognized by Brahmans as distinct Jatis within the social framework', true, 'dbf873bc-46dd-46fc-b417-4c090bfca40e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18323eeb-756d-4efe-9c73-6125b3889092', 'The Varna system was abolished completely', false, 'dbf873bc-46dd-46fc-b417-4c090bfca40e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86e8023d-4c78-46da-9da0-06c086fddb7d', 'All craftspersons were made kings', false, 'dbf873bc-46dd-46fc-b417-4c090bfca40e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30e522f0-aacb-4688-b10b-858eaaf350ab', 'Jatis were introduced by foreign traders', false, 'dbf873bc-46dd-46fc-b417-4c090bfca40e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('92037eeb-ac4d-4cbe-b93b-458eb6170589', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'What agricultural innovation in Wet-Rice Cultivation was introduced by the Ahoms in the Brahmaputra valley?', 'Ahoms engineered wet-rice hydraulic ecology: building bunds, earthen dykes, and canal networks across floodplains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ec8992e-7059-4635-9acc-f7bb3f8a1c3c', 'Advanced wet rice transplantation techniques, construction of extensive flood-control dykes and irrigation canals', true, '92037eeb-ac4d-4cbe-b93b-458eb6170589');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c547e9f-37c9-4311-a882-1b08b75792ff', 'Growing rice without water in deserts', false, '92037eeb-ac4d-4cbe-b93b-458eb6170589');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc57198f-4ace-468a-b0c3-6bdf24e07911', 'Importing rice from Europe', false, '92037eeb-ac4d-4cbe-b93b-458eb6170589');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0848634-438f-44ae-92e0-a78e3ef76510', 'Using tractors and chemical fertilizers', false, '92037eeb-ac4d-4cbe-b93b-458eb6170589');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66f4dda0-d38b-44dd-a3c2-e94d5d0fd561', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'What happened when the Mughals under Asaf Khan conquered Garha Katanga in 1565?', 'The Mughals appropriated Garha Katanga''s legendary treasury of gold and elephants, establishing indirect suzerainty.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b5e40f0-2fdc-4c13-8249-fd5c50eba597', 'The Mughals captured immense booty in precious gold coins and thousands of wild elephants, annexing a part and granting the rest to Bir Narain''s uncle Chhatar Shah', true, '66f4dda0-d38b-44dd-a3c2-e94d5d0fd561');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb50b939-4b4f-41e0-9744-3fa8293b4cd9', 'They destroyed all houses and left', false, '66f4dda0-d38b-44dd-a3c2-e94d5d0fd561');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10c49ba3-0e30-4580-aa67-65911725cc82', 'They made Rani Durgavati the Mughal Empress', false, '66f4dda0-d38b-44dd-a3c2-e94d5d0fd561');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8398d533-51f3-4c75-9f52-7092e1a0c5dd', 'They planted a forest over the kingdom', false, '66f4dda0-d38b-44dd-a3c2-e94d5d0fd561');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7aa6ab34-ff1f-497f-a193-9820f1308e60', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'Which martial tribes inhabited the rugged Balochistan desert frontiers in the northwest of the subcontinent?', 'The Balochis formed a major confederacy of clan-based pastoral and warrior tribes across the northwestern arid frontiers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c453a226-5de6-4968-92eb-f149b025ac9b', 'The Balochis (divided into many powerful clans under chieftains)', true, '7aa6ab34-ff1f-497f-a193-9820f1308e60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0b2de70-c6f8-4a92-b170-27d380dd635d', 'The Ahoms', false, '7aa6ab34-ff1f-497f-a193-9820f1308e60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a4cf6c6-1e6d-4231-97c8-92e4376d6ab2', 'The Gonds', false, '7aa6ab34-ff1f-497f-a193-9820f1308e60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9f28f23-2e2a-496e-9012-e706dfd56b32', 'The Santhals', false, '7aa6ab34-ff1f-497f-a193-9820f1308e60');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7b494793-08cc-4dd6-b57d-05f4b72d0c2f', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'Which tribal kingdoms inhabited the forested plateaus of Chota Nagpur and Odisha during the medieval era?', 'The Mundas, Santhals, and Oraons inhabited the mineral-rich Chota Nagpur plateau and forested Odisha tracts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b35d81d-6254-4886-9985-80a1369e9ae7', 'The Mundas and Santhals', true, '7b494793-08cc-4dd6-b57d-05f4b72d0c2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ef5d14b-6fdd-4420-a7d3-52608604f5e4', 'The Ahoms', false, '7b494793-08cc-4dd6-b57d-05f4b72d0c2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e431b38a-48e5-4269-9594-da62d13e47d0', 'The Kolis', false, '7b494793-08cc-4dd6-b57d-05f4b72d0c2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('596ac61f-2b1d-4c74-97f4-5a0503b56ac0', 'The Gakkhars', false, '7b494793-08cc-4dd6-b57d-05f4b72d0c2f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('346014b0-1df2-4ccd-8278-cd82598ad25f', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'What were the ''Itinerant Groups'' in medieval society?', 'Itinerant groups included nomadic blacksmiths, rope-makers, acrobats, and bards servicing rural communities on seasonal circuits.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1097738-6292-42a0-870c-ca7fe9c5a83a', 'Mobile craftspersons, entertainers, pedlars, and puppeteers who traveled from village to village practicing their occupation and trade', true, '346014b0-1df2-4ccd-8278-cd82598ad25f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72df12e8-1b96-4e26-a001-6ec751b2c2ee', 'Kings who lived in tents', false, '346014b0-1df2-4ccd-8278-cd82598ad25f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b76f48a-63e4-4f40-9185-45c60be97a45', 'Priests who never walked', false, '346014b0-1df2-4ccd-8278-cd82598ad25f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6a84d80-80d8-4072-84c4-1ff62a94270d', 'Soldiers guarding fort gates', false, '346014b0-1df2-4ccd-8278-cd82598ad25f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('adb3b881-016d-489e-bf3b-7406c62cc83f', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'What was the ''Khel'' census mechanism used by Ahom kings to manage labor and military manpower?', 'The Ahom administration took regular Paik censuses, re-allocating corvée labor between densely and sparsely populated khels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a2cbe51-5b41-4f97-afa8-12e601291e79', 'A regular population census was taken; villages with large populations were forced to transfer Paik laborers to sparsely populated areas to balance labor resources', true, 'adb3b881-016d-489e-bf3b-7406c62cc83f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('727da408-f33e-4bda-9be0-a1f82b2e34c7', 'Every person was given gold coins', false, 'adb3b881-016d-489e-bf3b-7406c62cc83f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b184acf6-90c7-4b2d-9503-0f94d3e760ad', 'People were counted by measuring their height', false, 'adb3b881-016d-489e-bf3b-7406c62cc83f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cab054f-2b1a-41c1-b629-50fe364ed282', 'Only horses were counted', false, 'adb3b881-016d-489e-bf3b-7406c62cc83f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c939864-5852-452d-86c9-cf94fc533a06', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Medium', 'Why did Brahman scholars gain immense influence in Gond and Ahom royal courts in the 16th and 17th centuries?', 'Tribal rulers patronized Brahmans with land grants to legitimize their emergent monarchies within the pan-Indian royal pantheon.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba76eeab-1830-40fd-8cf7-87a2b97a6cee', 'Tribal kings granted generous tax-free land endowments (Brahmadeya) to Brahmans to obtain Sanskrit genealogical legitimacy, Kshatriya status, and rituals for statecraft', true, '4c939864-5852-452d-86c9-cf94fc533a06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5bc261a-4e6b-4c45-8f23-12814ffe3a61', 'Brahmans were the only soldiers in the kingdom', false, '4c939864-5852-452d-86c9-cf94fc533a06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b59e65b-5c9f-4bab-8319-1d43d5b2eb81', 'Brahmans built all cannons', false, '4c939864-5852-452d-86c9-cf94fc533a06');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5323cb1-94ed-4254-a6df-8a21d42297b8', 'Brahmans controlled the elephant trade', false, '4c939864-5852-452d-86c9-cf94fc533a06');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('032fd5be-214a-4119-8a88-176777841470', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e8608b6-0608-4408-a691-726eeceb3e6b', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '032fd5be-214a-4119-8a88-176777841470');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2011657a-ee78-4c69-98b2-467ab6d961d0', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '032fd5be-214a-4119-8a88-176777841470');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78d1cb01-d3b0-47d1-bce7-486f1e5be185', '(A) is true, but (R) is false.', false, '032fd5be-214a-4119-8a88-176777841470');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a45fd51-7b46-4197-8c8a-86dcd395ef2c', '(A) is false, but (R) is true.', false, '032fd5be-214a-4119-8a88-176777841470');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1448149-0b1f-4027-8eb0-b156ad6db4bf', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'Spot the IMPOSTER in the following group of Tribal Communities and their historical regional homelands:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56ce73aa-4243-4364-8c24-591435849ad3', 'Tribe 1', false, 'f1448149-0b1f-4027-8eb0-b156ad6db4bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e401b25-0b3f-476d-b183-1a733ddaedf1', 'Tribe 2', false, 'f1448149-0b1f-4027-8eb0-b156ad6db4bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9311f809-eb00-46db-91c1-e4aa220b4404', 'Tribe 3', false, 'f1448149-0b1f-4027-8eb0-b156ad6db4bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db2657f9-4c0d-4e97-bad1-0353b73b2e9b', 'Tribe 4 (The Khokhars were a powerful martial tribe of the PUNJAB region, not ocean reefs)', true, 'f1448149-0b1f-4027-8eb0-b156ad6db4bf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81d5127e-9e26-4e5a-bd71-61fc8965a7d0', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'Analyze the state formation process in the Ahom kingdom:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d33a836-e035-4825-9e33-6b2f5695d12a', 'They suppressed the older feudal lords (Bhuiyans), annexed neighboring kingdoms (Chhutiyas, Koch-Hajo), built extensive hydraulic dykes, and instituted the Paik rotational labor system backed by gunpowder ballistics', true, '81d5127e-9e26-4e5a-bd71-61fc8965a7d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3337b12-0610-4da5-97a3-c40f588e67a2', 'They moved the entire population to Tibet', false, '81d5127e-9e26-4e5a-bd71-61fc8965a7d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f2de508-0d3f-4576-86dc-59fb83886c74', 'They abolished agriculture and became pure hunter-gatherers', false, '81d5127e-9e26-4e5a-bd71-61fc8965a7d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ae70471-8fec-44e8-9fe4-6fb7be762cc7', 'They signed a treaty with Roman emperors', false, '81d5127e-9e26-4e5a-bd71-61fc8965a7d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be37959d-d790-40b0-a6d8-8626a19dc704', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'Match Column I (Tribal & Administrative Terminology) with Column II (Exact Historical Meanings):
(a) Chaurasi  -> (i) Unit of 84 villages in the Gond Garh administrative hierarchy
(b) Barhot    -> (ii) Sub-unit of 12 villages under a Chaurasi
(c) Buranji   -> (iii) Official historical chronicles written in Ahom and Assamese
(d) Paik      -> (iv) Obligatory rotational corvée laborer in the Ahom state system', 'Chaurasi = 84 villages; Barhot = 12 villages; Buranji = chronicle; Paik = corvée laborer.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a11d3296-d207-409c-8429-a2a0c8372b88', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'be37959d-d790-40b0-a6d8-8626a19dc704');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8466e121-f903-4a4b-bca5-d8dd321d398e', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'be37959d-d790-40b0-a6d8-8626a19dc704');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8496f4fe-5486-4e7e-8aec-15f77c459a8d', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'be37959d-d790-40b0-a6d8-8626a19dc704');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64742e8c-e91a-438f-bf4f-43e54fb9be03', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'be37959d-d790-40b0-a6d8-8626a19dc704');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7bc6547c-0443-418a-8ff5-73ae75171ecf', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'Read the statements regarding the transition from Varna to Jati:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('054bab52-4fb6-45f1-b19f-eed7c1a052e4', 'Statements 1 and 2 only', true, '7bc6547c-0443-418a-8ff5-73ae75171ecf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ebff50d-3f8f-4a37-a217-39001e2621d7', 'Statements 2 and 3 only', false, '7bc6547c-0443-418a-8ff5-73ae75171ecf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5dcfb4b-a845-4bf0-95e5-09d162611295', 'Statements 1 and 3 only', false, '7bc6547c-0443-418a-8ff5-73ae75171ecf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a916152-ed3f-4563-a266-f6757ee82d3a', 'All Statements 1, 2, and 3', false, '7bc6547c-0443-418a-8ff5-73ae75171ecf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ffd6c61f-eb22-4360-861f-20e0c05b54dc', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'Why was the heroic defense and martyrdom of Rani Durgavati of Garha Katanga (1565) celebrated in central Indian folklore?', 'Rani Durgavati''s resistance against Mughal imperial expansion embodies the indomitable martial pride of indigenous central Indian rulers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf069e83-6a50-424c-93dc-27ca463ff85a', 'She chose death in battle over surrender to Mughal subjugation, fighting with immense military valor alongside her wounded son to defend the sovereignty of her Gond kingdom', true, 'ffd6c61f-eb22-4360-861f-20e0c05b54dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52595bea-a5a3-406b-a70b-ff936ddbbe80', 'Because she built the Taj Mahal', false, 'ffd6c61f-eb22-4360-861f-20e0c05b54dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e28892d-865c-4c90-9a40-9cc32abea35f', 'Because she gave up her kingdom to live in a forest', false, 'ffd6c61f-eb22-4360-861f-20e0c05b54dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b68eac56-3b97-4481-98fc-643b02b64809', 'Because she defeated the British in 1565', false, 'ffd6c61f-eb22-4360-861f-20e0c05b54dc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dfeea627-2bde-4752-9535-e1c1aca9b5e5', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'How did the Paik labor system in Ahom Assam differ from traditional feudal slavery?', 'The Paik system was a reciprocal corvée obligation anchored in inalienable clan land tenure rather than chattel slavery.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8e47cac-b6c5-4148-8467-ca05ab21870e', 'Paiks were free village peasants who contributed rotational state service (military, dyke construction) in exchange for community-allocated agricultural land that could not be taken away by the King without clan approval', true, 'dfeea627-2bde-4752-9535-e1c1aca9b5e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81615dc7-a244-45e0-809a-434062bf106e', 'Paiks were bought and sold in markets as slaves', false, 'dfeea627-2bde-4752-9535-e1c1aca9b5e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1d9ec34-c70f-4339-9bd0-daf52bbe4ddd', 'Paiks were foreign prisoners of war', false, 'dfeea627-2bde-4752-9535-e1c1aca9b5e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('282f99d1-a52e-47a4-aef0-553badc7e991', 'Paiks were only employed as palace cooks', false, 'dfeea627-2bde-4752-9535-e1c1aca9b5e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89f56f03-df94-47df-9c99-1609887b1242', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'What socio-religious transformation occurred as tribal states became large, centralized monarchies?', 'State centralization fostered syncretic integration: tribal deities (e.g. Kamakhya, Jagannath) were incorporated into Brahmanical temple worship.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bce8e2f-cc11-49fb-9ba0-f0320c01b7ae', 'Indigenous animistic and ancestral tribal deities were synthesized with Puranic Hindu pantheons, leading to composite temple patronage under royal sponsorship', true, '89f56f03-df94-47df-9c99-1609887b1242');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d2468f3-5cf6-4b87-9ef9-2fa46f0d4d81', 'All tribal languages were completely banned', false, '89f56f03-df94-47df-9c99-1609887b1242');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e2e0245-f4b0-4361-92da-3d0f1136bb9f', 'Tribal people were forced to move out of India', false, '89f56f03-df94-47df-9c99-1609887b1242');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('449a5adc-b0d2-402c-a301-7a99ed8195ca', 'Monarchy was abolished', false, '89f56f03-df94-47df-9c99-1609887b1242');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6093623e-21b3-4bf1-a265-43caa7e66b88', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'Consider four regional tribal communities of medieval India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3faba2cc-b40f-43a4-8177-31d4e9048231', 'They developed powerful centralized kingdoms or formidable martial resistance networks that negotiated with or contested Mughal imperial expansion', true, '6093623e-21b3-4bf1-a265-43caa7e66b88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('929a90b3-dad5-4ef9-83ba-0e4f18e66420', 'They had no chiefs or leaders', false, '6093623e-21b3-4bf1-a265-43caa7e66b88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('673fab0d-8b80-4dd1-93f3-28099ae04aef', 'They all converted to European religions in 1500', false, '6093623e-21b3-4bf1-a265-43caa7e66b88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b92a2f56-97ee-4fe7-9049-103f802ca263', 'They lived only on oceanic islands', false, '6093623e-21b3-4bf1-a265-43caa7e66b88');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e65cc404-19de-4474-b57c-8a4135c0234e', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'Why did the Ahom kingdom successfully resist Mughal conquest for over a century, despite repeated Mughal campaigns?', 'Ahom military resilience: naval riverine mastery (Battle of Saraighat 1671 under Lachit Borphukan), guerrilla tactics, and dense terrain.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b58ca6d-42ae-4c59-9bb9-d969b477e9c1', 'The Ahoms mastered guerrilla warfare in dense riverine terrain, constructed formidable mud and brick fortifications, utilized rapid war-boat naval fleets on the Brahmaputra, and deployed effective firearms', true, 'e65cc404-19de-4474-b57c-8a4135c0234e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5fc8d0b-5b79-4e23-a967-7d7319ddc2e6', 'Because the Mughals never entered Assam', false, 'e65cc404-19de-4474-b57c-8a4135c0234e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d12fc0f-16e4-4c85-9e65-43f342e18dd6', 'Because Assam had no rivers', false, 'e65cc404-19de-4474-b57c-8a4135c0234e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d260d566-66c2-49eb-aa58-f297f41fc4e5', 'Because the British defended Assam', false, 'e65cc404-19de-4474-b57c-8a4135c0234e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd1d92ec-36ab-49f3-ad4b-30dc3d8c5561', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'What was the significance of ''Buranjis'' for modern historiography of Northeast India?', 'Buranjis constitute an unprecedented tradition of secular, chronological historiography in medieval Northeast India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7749e810-e6c7-4196-9bba-d524b2f5a07a', 'They provide a continuous, meticulously detailed chronological record of diplomacy, wars, treaties, administrative censuses, and royal successions over 600 years', true, 'dd1d92ec-36ab-49f3-ad4b-30dc3d8c5561');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79e8ac0e-0cf0-4065-a3fd-3b9e85fe884e', 'They are fictional mythological poems only', false, 'dd1d92ec-36ab-49f3-ad4b-30dc3d8c5561');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3e379bf-2d5e-429b-a25b-ed48e8bd2b20', 'They were written in modern English', false, 'dd1d92ec-36ab-49f3-ad4b-30dc3d8c5561');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f40212bb-012f-4868-be87-6cccbbd26cdd', 'They contain no historical dates', false, 'dd1d92ec-36ab-49f3-ad4b-30dc3d8c5561');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cc0256b2-e252-4485-b4ea-093296fa201c', 'Class 7', 'Social Science', 'Chapter 7: Tribes, Nomads and Settled Communities', 'Hard', 'What master historical synthesis is illuminated in Chapter 7 of NCERT Class 7 History?', 'Chapter 7 restores historical balance by highlighting the agency, statecraft, and cultural contributions of indigenous tribal and pastoral societies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99000af1-f77c-4ff8-b797-186c09bd682f', 'Indian medieval history was shaped as much by dynamic tribal kingdoms, nomadic pastoralists, and frontier societies as by settled empires, revealing a vibrant pluralistic subcontinent defined by continuous cultural synthesis and political adaptation', true, 'cc0256b2-e252-4485-b4ea-093296fa201c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce381509-e3c6-4ce2-b37b-ed6cf4a4ac4a', 'That only kings living in Delhi mattered in Indian history', false, 'cc0256b2-e252-4485-b4ea-093296fa201c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('babf3c43-5e35-4458-8f48-80502f84c37d', 'That tribal societies had no culture or history', false, 'cc0256b2-e252-4485-b4ea-093296fa201c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ad98a16-deb1-4346-8d7e-29f25ec88373', 'That India was completely uniform without any regional diversity', false, 'cc0256b2-e252-4485-b4ea-093296fa201c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38d551ac-fd7b-45b9-ac7b-7573fc1f338d', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', 'संज्ञा के जिस रूप से किसी व्यक्ति, प्राणी या वस्तु के पुरुष जाति अथवा स्त्री जाति होने का बोध होता है, उसे व्याकरण में क्या कहते हैं?', 'लिंग: संज्ञा के जिस रूप से पुरुष या स्त्री जाति का बोध हो, उसे लिंग कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('939cf3b0-6fa4-4fdf-a946-9283e4db4535', 'लिंग (Gender)', true, '38d551ac-fd7b-45b9-ac7b-7573fc1f338d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e000611a-075b-4570-8657-1472e161e1fb', 'वचन (Number)', false, '38d551ac-fd7b-45b9-ac7b-7573fc1f338d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd38df7b-ec9d-4bc2-8e5c-f8d140c4806f', 'कारक (Case)', false, '38d551ac-fd7b-45b9-ac7b-7573fc1f338d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abdcd98e-8a89-4563-b337-ad52533a9be9', 'काल (Tense)', false, '38d551ac-fd7b-45b9-ac7b-7573fc1f338d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8eb9e64-fa8d-4654-8227-4d7903fa51a4', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', 'हिंदी भाषा में लिंग के मुख्य रूप से कितने भेद होते हैं?', 'संस्कृत में 3 लिंग होते हैं, परन्तु हिंदी व्याकरण में केवल 2 लिंग होते हैं: पुल्लिंग और स्त्रीलिंग।', NOW()) ON CONFLICT DO NOTHING;
