INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f159ece7-a68a-4945-9e5f-a360c50e118e', 'तीन भेद (क्लीवलिंग सहित)', false, 'c8eb9e64-fa8d-4654-8227-4d7903fa51a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82abfa88-643e-4dca-9683-6e32e110f10f', 'चार भेद', false, 'c8eb9e64-fa8d-4654-8227-4d7903fa51a4');
