INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('92985a99-4717-4f33-99dc-f348f0347da0', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', 'शब्द के जिस रूप से किसी वस्तु, प्राणी या पदार्थ के ''एक'' अथवा ''एक से अधिक'' होने का बोध होता है, उसे क्या कहते हैं?', 'वचन: संज्ञा, सर्वनाम, विशेषण या क्रिया के जिस रूप से संख्या (एकत्व या अनेकत्व) का बोध हो, उसे वचन कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a3e13b4-a1b2-4060-b0c8-119813ab6685', 'वचन (Number)', true, '92985a99-4717-4f33-99dc-f348f0347da0');
