INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9f487cbe-df64-468f-8545-76d97345cf8e', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', 'हिंदी में वचन के कितने भेद होते हैं?', 'हिंदी में केवल 2 वचन होते हैं: एकवचन (Singular) और बहुवचन (Plural)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a60f17c-a90f-4e3a-9932-c32392ccb693', 'दो भेद (1. एकवचन, 2. बहुवचन)', true, '9f487cbe-df64-468f-8545-76d97345cf8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71336ad9-678c-4f5d-88de-24a6b75d1ca7', 'तीन भेद (द्विवचन सहित)', false, '9f487cbe-df64-468f-8545-76d97345cf8e');
