INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9adbb527-8faa-49dd-8999-23607bd09a8d', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', 'दिनों के नाम (सोमवार, मंगलवार), महीनों के नाम (जनवरी, मार्च, चैत्र) तथा पर्वतों के नाम (हिमालय, विंध्याचल) सामान्यतः किस लिंग में होते हैं?', 'दिनों, महीनों, पर्वतों, देशों, ग्रहों (पृथ्वी को छोड़कर) और समुद्रों के नाम सदैव पुल्लिंग होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0cfc456-d16a-4ad5-8e12-f56415af450b', 'नित्य पुल्लिंग में', true, '9adbb527-8faa-49dd-8999-23607bd09a8d');
