INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5434d5ce-ba35-4df1-a3aa-e1b049b6fac2', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', 'भाषाओं के नाम (हिंदी, अंग्रेजी, संस्कृत), लिपियों के नाम (देवनागरी, रोमन) तथा नदियों के नाम (गंगा, यमुना) सामान्यतः किस लिंग में होते हैं?', 'भाषाओं, बोलियों, लिपियों, नदियों (सिंधु/ब्रह्मपुत्र नद को छोड़कर) और तिथियों के नाम स्त्रीलिंग होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a20acb23-8102-4805-9b03-acf40d713566', 'नित्य स्त्रीलिंग में', true, '5434d5ce-ba35-4df1-a3aa-e1b049b6fac2');
