INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('33db3f07-cc4a-4ce0-b2ec-149d89b2abe9', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', '''प्राण, दर्शन, हस्ताक्षर, आँसू, होश, बाल'' शब्द हिंदी में सदैव किस वचन में प्रयुक्त होते हैं?', 'प्राण, दर्शन, आँसू, हस्ताक्षर, होश, बाल, लोग - ये शब्द हिंदी में नित्य बहुवचन होते हैं (जैसे: मेरे प्राण निकल गए)।', NOW()) ON CONFLICT DO NOTHING;
