INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bb841a8-56f0-457d-a020-747e1daa769e', 'द्विवचन में', false, '9c9938be-f668-4c2d-ab31-33c2c5e94801');
