INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62cc743c-70d2-45bf-96d2-b06c0a2260d5', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Easy', '''लड़का'' शब्द का सही बहुवचन रूप क्या होगा?', 'आकारांत पुल्लिंग शब्द का बहुवचन ''आ'' को ''ए'' में बदलकर ''लड़के'' बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1abf9bd-2bce-4a6e-af63-fb3f4145f687', 'लड़के', true, '62cc743c-70d2-45bf-96d2-b06c0a2260d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da7c36dd-42c3-4c4d-907e-fe73ec5921b2', 'लड़कों', false, '62cc743c-70d2-45bf-96d2-b06c0a2260d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c42d198-c9be-4875-b065-f141439d0122', 'लड़काएँ', false, '62cc743c-70d2-45bf-96d2-b06c0a2260d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('988681a5-3b60-4b93-b174-89ebf751b592', 'लड़कियाँ', false, '62cc743c-70d2-45bf-96d2-b06c0a2260d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e7fae288-9ba8-488d-8f46-7d7d83e1be40', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''नेता'' शब्द का शुद्ध स्त्रीलिंग रूप क्या होगा?', 'संस्कृत ''ता'' अंत वाले पुल्लिंग शब्दों का स्त्रीलिंग ''त्री'' होता है: नेता→नेत्री, अभिनेता→अभिनेत्री, दाता→दात्री।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a05d4bb5-02b9-4c5e-9a10-be4fed3a9f56', 'नेत्री', true, 'e7fae288-9ba8-488d-8f46-7d7d83e1be40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1af55a1c-c768-42e1-b6a2-9afbc6f5af3e', 'नेतिन', false, 'e7fae288-9ba8-488d-8f46-7d7d83e1be40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('874e21b1-c761-4b5e-b932-09bfa86637d2', 'नेताइन', false, 'e7fae288-9ba8-488d-8f46-7d7d83e1be40');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cc46aef-ea92-4c86-9d49-1a63e044e265', 'नेतिक', false, 'e7fae288-9ba8-488d-8f46-7d7d83e1be40');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6055d3e-3c70-48ed-892b-06482cc225a3', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''सम्राट'' शब्द का सही स्त्रीलिंग रूप क्या होगा?', '''सम्राट'' का मानक स्त्रीलिंग ''साम्राज्ञी'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9e92c24-9c3e-4c35-b30f-7ebe02862b53', 'साम्राज्ञी', true, 'd6055d3e-3c70-48ed-892b-06482cc225a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09f7ca8b-1fdc-4f79-a417-6efd7791e5cb', 'सम्राटी', false, 'd6055d3e-3c70-48ed-892b-06482cc225a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa34ed8f-9852-4616-ab8d-7f356f6af86b', 'सम्राटिन', false, 'd6055d3e-3c70-48ed-892b-06482cc225a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efa8780a-2164-42d2-99d5-f8108d41fb19', 'रानी', false, 'd6055d3e-3c70-48ed-892b-06482cc225a3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4af84222-6cc3-4de2-b1b9-85db06f69298', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', 'इकारांत और ईकारांत स्त्रीलिंग शब्दों (जैसे: नदी, लड़की, साड़ी) का बहुवचन बनाते समय क्या नियम लागू होता है?', 'ईकारांत स्त्रीलिंग का बहुवचन: ई→इ + याँ (नदी→नदियाँ, दवाई→दवाइयाँ, नीति→नीतियाँ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('188a555e-50ea-4e40-9208-1b68b355ab1f', 'अंतिम दीर्घ ''ई'' को ह्रस्व ''इ'' में बदलकर अंत में ''याँ'' जोड़ दिया जाता है (जैसे: नदी -> नदियाँ, लड़की -> लड़कियाँ, साड़ी -> साड़ियाँ)', true, '4af84222-6cc3-4de2-b1b9-85db06f69298');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a4b2e49-a70a-4809-97fe-4116594e95a9', 'केवल बिंदी लगा दी जाती है', false, '4af84222-6cc3-4de2-b1b9-85db06f69298');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec2febec-5d8b-4350-a837-11fe97233095', 'शब्द को वैसे ही छोड़ दिया जाता है', false, '4af84222-6cc3-4de2-b1b9-85db06f69298');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f780567d-58d3-4138-88b6-141bdd9763f6', 'शब्द के अंत में ''ए'' जोड़ा जाता है', false, '4af84222-6cc3-4de2-b1b9-85db06f69298');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('477d0106-8445-48c2-a219-501a68a4a256', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', 'आदर और सम्मान प्रकट करने के लिए एकवचन संज्ञा (जैसे: गुरुजी, पिताजी, महात्मा गांधी) के साथ किस वचन की क्रिया का प्रयोग किया जाता है?', 'हिंदी में पूज्य एवं आदरणीय व्यक्तियों के लिए एकवचन कर्ता होते हुए भी क्रिया ''आदरार्थक बहुवचन'' में प्रयुक्त होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c408c9f-7e22-43ea-89a9-d57970e89437', 'बहुवचन की क्रिया का प्रयोग (आदरार्थक बहुवचन - जैसे: ''गांधीजी सत्य बोलते थे'', ''गुरुजी आ रहे हैं'')', true, '477d0106-8445-48c2-a219-501a68a4a256');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4621f08-46e5-49b9-a1dd-baf9ab77b4d8', 'एकवचन की क्रिया का ही प्रयोग होता है', false, '477d0106-8445-48c2-a219-501a68a4a256');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74ee1953-8b3e-447f-a3f7-bb3fbb094105', 'भविष्यत काल की क्रिया का प्रयोग', false, '477d0106-8445-48c2-a219-501a68a4a256');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c371a351-1489-492d-969d-9e07ec509f00', 'क्रिया का लोप हो जाता है', false, '477d0106-8445-48c2-a219-501a68a4a256');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2480318a-80b7-4150-9087-71a33a7f9d76', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''चिड़िया'' और ''डिबिया'' जैसे ''या'' अंत वाले स्त्रीलिंग शब्दों का बहुवचन कैसे बनाया जाता है?', '''या'' अंत वाले स्त्रीलिंग शब्दों के ऊपर चन्द्रबिन्दु लगाकर बहुवचन बनता है: चिड़िया→चिड़ियाँ, डिबिया→डिबियाँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e698504-a92c-49e9-926f-25ca8e13ccfd', 'अंतिम ''या'' के ऊपर अनुनासिक (चन्द्रबिन्दु - ''याँ'') लगाकर (जैसे: चिड़िया -> चिड़ियाँ, डिबिया -> डिबियाँ, गुड़िया -> गुड़ियाँ)', true, '2480318a-80b7-4150-9087-71a33a7f9d76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('036329d4-8979-4efb-a676-855bda9ad416', '''या'' को हटाकर ''ए'' लगाकर', false, '2480318a-80b7-4150-9087-71a33a7f9d76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ae45213-2115-4024-b94b-b6527ee01bd1', 'शब्द में कोई परिवर्तन नहीं होता', false, '2480318a-80b7-4150-9087-71a33a7f9d76');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e540304-c6be-49b3-9d32-4794b4f550c8', '''या'' के आगे ''गण'' जोड़कर', false, '2480318a-80b7-4150-9087-71a33a7f9d76');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37ad3110-7172-4910-bca9-ee50806842d6', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''अध्यापक'' शब्द का आदरसूचक बहुवचन बनाने के लिए कौन-सा समूहवाचक प्रत्यय जोड़ा जाता है?', 'गण्य व्यक्तियों के बहुवचन हेतु ''गण, वृंद, जन, वर्ग'' जुड़ता है: अध्यापकगण, मुनिवृंद, भक्तजन, अधिकारीवर्ग।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fb732dc-4d24-4ee0-a705-c46e069db6e4', 'अध्यापकगण (गण / वृंद / जन / वर्ग)', true, '37ad3110-7172-4910-bca9-ee50806842d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('408efe1b-4d1e-4472-8597-b1ffa3fba01f', 'अध्यापिकाएँ', false, '37ad3110-7172-4910-bca9-ee50806842d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b87419b7-6b30-414b-a4a3-120c21da741c', 'अध्यापकों', false, '37ad3110-7172-4910-bca9-ee50806842d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('952a4d05-759b-4bb1-9632-5411a888decd', 'अध्यापकी', false, '37ad3110-7172-4910-bca9-ee50806842d6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b29451cb-8fc0-425e-a1a6-2fd05e99d442', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''साधु'' शब्द का स्त्रीलिंग रूप क्या होगा?', '''साधु'' का मानक स्त्रीलिंग रूप ''साध्वी'' होता है।', NOW()) ON CONFLICT DO NOTHING;
