INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a49f76aa-ad48-492e-945b-53fb433adf94', 'साधुनी', false, 'b29451cb-8fc0-425e-a1a6-2fd05e99d442');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f931c46d-4d61-4d35-9e5d-9636b3a3a5a5', 'साधुइन', false, 'b29451cb-8fc0-425e-a1a6-2fd05e99d442');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83258c01-a7a4-46b9-8798-12df314f17b6', 'साधिका', false, 'b29451cb-8fc0-425e-a1a6-2fd05e99d442');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3a51f038-7d32-4d6b-a42c-7feaefb8f01d', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''वर'' शब्द का सही स्त्रीलिंग रूप क्या है?', 'संस्कृत तत्सम युग्म: वर (वर) का स्त्रीलिंग ''वधू'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04d86819-144b-4163-9155-c96a2aaf0f42', 'वधू', true, '3a51f038-7d32-4d6b-a42c-7feaefb8f01d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec6817dd-6a46-4839-b914-ede539ca26ea', 'कन्या', false, '3a51f038-7d32-4d6b-a42c-7feaefb8f01d');
