INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('955813ed-745c-40ca-8ab8-a8fade10ef75', 'स्त्री', false, '3a51f038-7d32-4d6b-a42c-7feaefb8f01d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('823afe4e-b753-4831-9f18-c852ec46318c', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''वधू'' शब्द का शुद्ध बहुवचन रूप क्या होगा?', 'ऊकारांत स्त्रीलिंग का बहुवचन: ऊ→उ + एँ (वधू→वधुएँ, बहू→बहुएँ)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b3cf09c-c24c-4226-b74c-f44fb9d0a3d5', 'वधुएँ (दीर्घ ''ऊ'' ह्रस्व ''उ'' में बदलकर ''एँ'' जुड़ता है)', true, '823afe4e-b753-4831-9f18-c852ec46318c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa7a65fe-209d-42b7-b98e-da7b4831b66c', 'वधुओं', false, '823afe4e-b753-4831-9f18-c852ec46318c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0a1a821-3cb5-4a5f-90b3-e179488fd567', 'वधुएं', false, '823afe4e-b753-4831-9f18-c852ec46318c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1db758af-5aa0-416a-b8a3-4c662da6c2cc', 'वधु', false, '823afe4e-b753-4831-9f18-c852ec46318c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca8cbac0-d2ac-4676-b580-f6f0cb1c6bc4', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', 'निम्नलिखित में से कौन-सा शब्द ''नित्य स्त्रीलिंग'' है, जिसका पुल्लिंग बनाने के लिए ''नर'' शब्द जोड़ना पड़ता है?', 'मक्खी, कोयल, तितली, मछली, चील नित्य स्त्रीलिंग हैं; इनका पुल्लिंग ''नर मक्खी, नर कोयल'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bfaefc1-e6df-4e31-b173-b2eec5438fc5', 'मक्खी (नर मक्खी), तितली (नर तितली), मछली (नर मछली), चील (नर चील)', true, 'ca8cbac0-d2ac-4676-b580-f6f0cb1c6bc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f72fe9a1-8cee-45eb-abf6-299c33aad02a', 'शेर', false, 'ca8cbac0-d2ac-4676-b580-f6f0cb1c6bc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc5b8db7-acde-402a-8713-199f473a285f', 'बैल', false, 'ca8cbac0-d2ac-4676-b580-f6f0cb1c6bc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f09d38c1-1aae-4555-9c11-d9cc676d1dc3', 'घोड़ा', false, 'ca8cbac0-d2ac-4676-b580-f6f0cb1c6bc4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('24473799-47c0-4664-8908-314aba46a5e3', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', 'निम्नलिखित में से कौन-सा शब्द ''नित्य पुल्लिंग'' है, जिसका स्त्रीलिंग बनाने के लिए ''मादा'' शब्द जोड़ना पड़ता है?', 'तोता, भालू, चीता, उल्लू, खटमल, मच्छर नित्य पुल्लिंग हैं; इनका स्त्रीलिंग ''मादा तोता, मादा भालू'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53c1ea78-e630-4360-9022-b6a3f4428f51', 'तोता (मादा तोता), भालू (मादा भालू), चीता (मादा चीता), खटमल (मादा खटमल)', true, '24473799-47c0-4664-8908-314aba46a5e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33408cf5-42ed-4d78-adfb-3d4cfde1a418', 'गाय', false, '24473799-47c0-4664-8908-314aba46a5e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3a96690-1a4c-4778-b077-d0b6641faa93', 'बकरी', false, '24473799-47c0-4664-8908-314aba46a5e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc836629-79c7-4b17-9756-917f8eaa9ff1', 'दासी', false, '24473799-47c0-4664-8908-314aba46a5e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6aeefec-a260-409e-b5cb-8a2aac82f5b9', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''दवा'' शब्द का शुद्ध बहुवचन रूप क्या होगा?', 'आकारांत स्त्रीलिंग ''दवा'' का बहुवचन ''दवाएँ'' होता है (''दवाई'' का बहुवचन ''दवाइयाँ'' होता है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de5c4b1a-3ed7-4153-9ee9-8e83d6330827', 'दवाएँ', true, 'e6aeefec-a260-409e-b5cb-8a2aac82f5b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f05cfe2e-5707-456b-9a6a-bde5ba18b48f', 'दवाइयाँ (दवाई का बहुवचन)', false, 'e6aeefec-a260-409e-b5cb-8a2aac82f5b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f31ff013-5517-4f2c-be66-c87f1131e71a', 'दवाओं', false, 'e6aeefec-a260-409e-b5cb-8a2aac82f5b9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96364eac-20c1-43b1-b658-b64cd150d054', 'दवाई', false, 'e6aeefec-a260-409e-b5cb-8a2aac82f5b9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b77ecc7-590c-4698-9c37-67ddf204382a', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', 'निम्नलिखित में से कौन-सा शब्द ''उभयलिंगी'' (Common Gender - पुरुष और स्त्री दोनों के लिए समान रूप से प्रयुक्त) पदनाम है?', 'उच्च पदनाम एवं व्यवसाय (राष्ट्रपति, प्रधानमंत्री, डॉक्टर, प्रोफेसर) उभयलिंगी होते हैं, जिनका लिंग क्रिया से स्पष्ट होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('285e69f3-3f16-4ed0-be6e-04c5fc6d26df', 'डॉक्टर, राष्ट्रपति, प्रधानमंत्री, इंजीनियर, मंत्री, मैनेजर', true, '3b77ecc7-590c-4698-9c37-67ddf204382a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0220643-a2a3-4aff-820c-6be50833c1c1', 'अभिनेता', false, '3b77ecc7-590c-4698-9c37-67ddf204382a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3ec0c5b-345b-4dd2-a278-3fbc4e1c178e', 'गायक', false, '3b77ecc7-590c-4698-9c37-67ddf204382a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a70b3ff0-d9f8-4507-8c36-d1d2483a8b0e', 'धोबी', false, '3b77ecc7-590c-4698-9c37-67ddf204382a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe2176cf-c35d-4743-8543-6ffc0b50572c', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''पुस्तक'' शब्द का सही बहुवचन रूप क्या होगा?', 'अकारांत स्त्रीलिंग शब्द का बहुवचन ''अ'' के स्थान पर ''एं'' (अनुस्वार युक्त) लगाकर ''पुस्तकें'' बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc4645c6-4268-44f9-a4ad-2f8accc3d1b6', 'पुस्तकें', true, 'fe2176cf-c35d-4743-8543-6ffc0b50572c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af1998b4-1c34-44ac-8ef6-9d60328bb56c', 'पुस्तकों', false, 'fe2176cf-c35d-4743-8543-6ffc0b50572c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa2e2083-fb56-493f-8578-77dbdf327a03', 'पुस्तकिया', false, 'fe2176cf-c35d-4743-8543-6ffc0b50572c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07d92580-1a72-4c20-9545-8c0ef2a06e3c', 'पुस्तकाएं', false, 'fe2176cf-c35d-4743-8543-6ffc0b50572c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('628f7983-a1ff-49c8-999b-ee1414349170', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''माला'' शब्द का सही बहुवचन रूप क्या होगा?', 'आकारांत स्त्रीलिंग के अंत में ''एँ'' जोड़कर बहुवचन बनता है: माला→मालाएँ, लता→लताएँ।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4219ad42-ce8a-4d71-b10e-861d5cda18cd', 'मालाएँ', true, '628f7983-a1ff-49c8-999b-ee1414349170');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7308d19b-fa8e-4c98-98c6-75a3e2bfc01b', 'मालाएं', false, '628f7983-a1ff-49c8-999b-ee1414349170');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ffa09b7-9acb-4a9e-9aed-66945a0ecf60', 'मालाओं', false, '628f7983-a1ff-49c8-999b-ee1414349170');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61dcc86f-3fde-472e-9315-8cfd35937431', 'माली', false, '628f7983-a1ff-49c8-999b-ee1414349170');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d417144-bb9e-426b-8f60-3f26b21ec945', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Medium', '''दही'' शब्द व्याकरण की दृष्टि से किस लिंग के अंतर्गत आता है?', 'दही, घी, मोती, पानी, पानी, तेल - ये इकारांत अपवाद शब्द हिंदी में नित्य पुल्लिंग होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd4a50a7-df6c-4ce0-9d7a-b3aa6089f830', 'पुल्लिंग (जैसे: ''दही बहुत खट्टा है'', ''दही जम गया'')', true, '3d417144-bb9e-426b-8f60-3f26b21ec945');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb306e67-a91c-49e7-894f-698e8d414577', 'स्त्रीलिंग', false, '3d417144-bb9e-426b-8f60-3f26b21ec945');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d73be388-52d7-40ab-b187-50143ac4b7e9', 'उभयलिंग', false, '3d417144-bb9e-426b-8f60-3f26b21ec945');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('597a9e64-5b59-412b-b470-7188e874da09', 'नपुंसकलिंग', false, '3d417144-bb9e-426b-8f60-3f26b21ec945');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ec4246ef-0f98-4f4f-8fb5-47128ee7e77a', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08e894ef-d0dd-4a1e-b50c-0e792d5a6a6a', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'ec4246ef-0f98-4f4f-8fb5-47128ee7e77a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57912a0f-1121-4ff7-82f4-c4a14c1befe2', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'ec4246ef-0f98-4f4f-8fb5-47128ee7e77a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a144390-ade7-40a3-bf50-8b570533ed73', '(A) सही है, परन्तु (R) गलत है।', false, 'ec4246ef-0f98-4f4f-8fb5-47128ee7e77a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83de3d82-daa7-496f-a01f-5dec7652b66f', '(A) गलत है, परन्तु (R) सही है।', false, 'ec4246ef-0f98-4f4f-8fb5-47128ee7e77a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e221c275-4f38-45c8-84ea-93de6dccc011', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', 'Spot the IMPOSTER in the following group of पुल्लिंग-स्त्रीलिंग युग्मों में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cb4c417-2d93-4c24-9046-54c441754c91', 'युग्म 1', false, 'e221c275-4f38-45c8-84ea-93de6dccc011');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0105eb76-475a-4990-a87c-2c85cb779136', 'युग्म 2', false, 'e221c275-4f38-45c8-84ea-93de6dccc011');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7b936e1-db59-4ac6-8e76-a5b36b83b04d', 'युग्म 3', false, 'e221c275-4f38-45c8-84ea-93de6dccc011');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('881f62e2-d222-4797-ac79-38e60f4892d6', 'युग्म 4 (''धावक'' का शुद्ध स्त्रीलिंग ''धाविका'' होता है, धावकी नहीं)', true, 'e221c275-4f38-45c8-84ea-93de6dccc011');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8af0d50-ef71-4f38-9419-d07ccd83cc69', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', 'सुमेलित कीजिए (शब्द और उनका नित्य वचन व्यवहार):
(क) हस्ताक्षर -> (i) नित्य बहुवचन
(ख) जनता     -> (ii) नित्य एकवचन
(ग) दर्शन     -> (iii) नित्य बहुवचन
(घ) दूध       -> (iv) नित्य एकवचन', 'हस्ताक्षर/दर्शन = नित्य बहुवचन; जनता/दूध = नित्य एकवचन।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6637f73-0b44-451f-84c4-877fa8aafa8d', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, 'd8af0d50-ef71-4f38-9419-d07ccd83cc69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df9311a2-b28f-4765-a439-48c5aabb6fa5', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, 'd8af0d50-ef71-4f38-9419-d07ccd83cc69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2da9d96-c212-4f8f-85f7-ea2ac14160d6', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, 'd8af0d50-ef71-4f38-9419-d07ccd83cc69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98590ef6-e88e-4bea-8c51-a203f8d29c2b', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, 'd8af0d50-ef71-4f38-9419-d07ccd83cc69');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8c737915-2a80-468e-aa88-54abe221654b', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', 'कारक-विभक्ति सहित (सप्रत्यय) होने पर किसी भी संज्ञा शब्द का बहुवचन बनाने के लिए कौन-सा प्रत्यय अनिवार्य रूप से प्रयुक्त होता है?', 'तिर्यक रूप (Oblique Plural): कारक विभक्ति चिह्नों के साथ सभी संज्ञाओं का बहुवचन ''ओं/यों'' से बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a610c5b-f4b7-4b49-b932-6cfeefed1ba8', '''ओं'' अथवा ''यों'' प्रत्यय (तिर्यक बहुवचन - जैसे: लड़कों ने, नदियों में, घरों पर, माताओं को)', true, '8c737915-2a80-468e-aa88-54abe221654b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39bd2e3e-2add-4503-b793-55a1881ad9e8', '''एँ'' प्रत्यय', false, '8c737915-2a80-468e-aa88-54abe221654b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08d07599-8a2b-4b28-bd0c-ca6841b6898a', '''गण'' प्रत्यय', false, '8c737915-2a80-468e-aa88-54abe221654b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d0246b9-a7c2-41ea-8c2a-4b98f13cf4ab', '''याँ'' प्रत्यय', false, '8c737915-2a80-468e-aa88-54abe221654b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf3107b5-59dd-4274-9b2d-38ddd61e7cff', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', '''हाथी'' शब्द का शुद्ध स्त्रीलिंग रूप क्या होगा?', 'हाथी + इनी = हथिनी (मानक वर्तनी)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c6520e4-4bd3-484f-89ec-c72d8f874895', 'हथिनी (दीर्घ ''ई'' का ह्रस्व ''इ'' में परिवर्तन होकर ''इनी'' प्रत्यय)', true, 'bf3107b5-59dd-4274-9b2d-38ddd61e7cff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81006406-f457-4d60-b161-4d4e042ebf85', 'हाथिन', false, 'bf3107b5-59dd-4274-9b2d-38ddd61e7cff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b61d9bf5-cbd6-4cfa-8e97-cf276c0bbe61', 'हाथिनी', false, 'bf3107b5-59dd-4274-9b2d-38ddd61e7cff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49089d1c-2f18-4544-b98a-d1e8cbf0943d', 'हथनी', false, 'bf3107b5-59dd-4274-9b2d-38ddd61e7cff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b48b0f4e-f8a4-471f-a89b-e0fcf7b72bc4', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', '''महान'' विशेषण का शुद्ध स्त्रीलिंग रूप क्या होगा?', 'संस्कृत तत्सम ''महान्'' (पुल्लिंग) का स्त्रीलिंग रूप ''महती'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13aa8b92-0f53-4635-81a7-11f455818558', 'महती (जैसे: ''महती कृपा'')', true, 'b48b0f4e-f8a4-471f-a89b-e0fcf7b72bc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('766aecf5-9bbb-4e5a-a259-bd64bb4bd4a8', 'महानी', false, 'b48b0f4e-f8a4-471f-a89b-e0fcf7b72bc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfbf0291-348e-4a99-9194-ad3a2e256763', 'महानता', false, 'b48b0f4e-f8a4-471f-a89b-e0fcf7b72bc4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c95d058-8a34-4f27-9fb5-04de224e4d63', 'महिषी', false, 'b48b0f4e-f8a4-471f-a89b-e0fcf7b72bc4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f5589bc8-04a3-494a-8ebc-4b0d15ed6615', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', 'निम्नलिखित वाक्यों में से ''व्याकरणिक दृष्टि से पूर्णतः शुद्ध वाक्य'' का चयन कीजिए:', 'पिताजी के सम्मान में आदरार्थक बहुवचन ''आए हैं'' शुद्ध है; जनता एकवचन है और प्राण बहुवचन है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d85390b8-d95e-4009-affd-1b95fe94a73c', '''कल रात मेरे पिताजी दिल्ली से लौट आए हैं।'' (आदरार्थक बहुवचन क्रिया का शुद्ध प्रयोग)', true, 'f5589bc8-04a3-494a-8ebc-4b0d15ed6615');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28195417-17ac-4c65-825d-f2725e4e855e', '''कल रात मेरा पिताजी दिल्ली से लौट आया।''', false, 'f5589bc8-04a3-494a-8ebc-4b0d15ed6615');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab05ffe1-22cb-49a7-ba2e-bf6896c35079', '''वहाँ बहुत सारे जनता उपस्थित थे।''', false, 'f5589bc8-04a3-494a-8ebc-4b0d15ed6615');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0d24acb-be8d-4be5-a4e6-cc3e70fd3d8f', '''उसका प्राण निकल गया।''', false, 'f5589bc8-04a3-494a-8ebc-4b0d15ed6615');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f88aeb7-a3cf-44e2-bb31-bbeca771ba42', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', 'निम्नलिखित में से किस विकल्प के सभी शब्द ''पुल्लिंग'' हैं?', 'दूध, दही, मोती, पानी, घी, रत्न (हीरा, पन्ना) और पर्वत (हिमालय) सभी शुद्ध पुल्लिंग शब्द हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('846785e3-9ef0-4c5f-9a55-6a801c03d11a', 'दूध, दही, मोती, पानी, घी, हीरा, पन्ना, हिमालय', true, '5f88aeb7-a3cf-44e2-bb31-bbeca771ba42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b19f7030-6236-498e-8077-d1352707bedd', 'गंगा, यमुना, देवनागरी, रोटी, दाल', false, '5f88aeb7-a3cf-44e2-bb31-bbeca771ba42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f05b56b1-cc28-4910-b8a8-0ddfcc831ec1', 'पुस्तक, कलम, मेज, कुर्सी', false, '5f88aeb7-a3cf-44e2-bb31-bbeca771ba42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9ec1930-04c6-4bfd-b6e9-f7f82c0efc37', 'मक्खी, कोयल, तितली, चील', false, '5f88aeb7-a3cf-44e2-bb31-bbeca771ba42');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa90c0cb-0c4d-49d2-9489-7cf6d978f24e', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', '''भविष्यद्वक्ता'' शब्द का सही स्त्रीलिंग रूप क्या होगा?', 'वक्ता→वक्त्री के नियमानुसार ''भविष्यद्वक्ता'' का स्त्रीलिंग ''भविष्यद्वक्त्री'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75ac46d3-1727-4855-9720-189092ac569b', 'भविष्यद्वक्त्री', true, 'aa90c0cb-0c4d-49d2-9489-7cf6d978f24e');
