INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bfcfbca4-d497-4ef5-b365-86212b3c4895', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', '''ताश के पत्तों में राजा और रानी होते हैं।'' वाक्य में ''राजा'' का स्त्रीलिंग ''रानी'' है। ''नर'' का स्त्रीलिंग ''नारी'' है। ''युवक'' का स्त्रीलिंग क्या होगा?', '''युवक'' का मानक तत्सम स्त्रीलिंग ''युवती'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f179a724-d347-4b2e-9052-09755ee11ac1', 'युवती', true, 'bfcfbca4-d497-4ef5-b365-86212b3c4895');
