INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6fbc5e47-f528-4270-94a3-28be4ab0ea4a', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', '''ऋषि'' शब्द का सही स्त्रीलिंग रूप क्या होगा?', '''ऋषि'' का वैदिक एवं मानक स्त्रीलिंग ''ऋषिका'' होता है।', NOW()) ON CONFLICT DO NOTHING;
