INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f0f782d6-6f12-4c92-99f4-1c63cf0a0e8e', 'Class 7', 'Hindi Grammar', 'Chapter 7: लिंग और वचन', 'Hard', 'लिंग और वचन (Gender & Number Agreement) के सम्यक ज्ञान का हिंदी वाक्य-रचना और क्रिया-अन्विति में क्या सर्वोच्च महत्व है?', 'हिंदी एक अत्यधिक अन्विति-प्रवण (Agreement-rich) भाषा है, जहाँ क्रिया और विशेषण का रूप लिंग-वचन के आधार पर ही निर्धारित होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b95a0ee0-6441-4fab-ab5d-cf249f8ddcc5', 'हिंदी में क्रिया, विशेषण और सर्वनाम के रूप कर्ता और कर्म के लिंग एवं वचन के अनुसार परिवर्तित (विकृत) होते हैं ; इनके अशुद्ध ज्ञान से समूची वाक्य-संरचना अशुद्ध और हास्यास्पद हो जाती है', true, 'f0f782d6-6f12-4c92-99f4-1c63cf0a0e8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77e5a518-c2c4-4f9e-94a4-b3bbcf08b114', 'लिंग और वचन केवल प्राथमिक कक्षाओं का विषय है', false, 'f0f782d6-6f12-4c92-99f4-1c63cf0a0e8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('540aab95-d203-46b2-a090-c645a149a5ec', 'हिंदी में लिंग और वचन का क्रिया पर कोई प्रभाव नहीं पड़ता', false, 'f0f782d6-6f12-4c92-99f4-1c63cf0a0e8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9f92e58-ffae-4c23-9404-81d0c257a5dd', 'इसका केवल वर्तनी में थोड़ा प्रयोग होता है', false, 'f0f782d6-6f12-4c92-99f4-1c63cf0a0e8e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11120911-dfc8-41fa-b2a4-239e5da592af', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'The biological production of new individual offspring from their parent organisms is called:', 'Reproduction is the biological process by which existing parent organisms produce new offspring of their own kind.', NOW()) ON CONFLICT DO NOTHING;
