INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e35e28d-ec2c-4d6c-a059-6f43f192a8bd', 'Photosynthesis', false, '11120911-dfc8-41fa-b2a4-239e5da592af');
