INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e735812-6bb9-4209-86ce-62e4d34fa610', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'What mode of plant reproduction produces new plants WITHOUT the involvement or production of seeds?', 'Asexual reproduction (including vegetative propagation, budding, fragmentation, spore formation) generates new plants without seeds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3dece41d-d85f-45a0-af92-96e61903d5b5', 'Asexual Reproduction (Vegetative Propagation)', true, '8e735812-6bb9-4209-86ce-62e4d34fa610');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad7ebfc9-c7ee-4ba0-91d4-b262414075ba', 'Sexual Reproduction', false, '8e735812-6bb9-4209-86ce-62e4d34fa610');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ac8cd10-93cd-4bdd-b125-bd41dd525137', 'Pollination', false, '8e735812-6bb9-4209-86ce-62e4d34fa610');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e41bcad-c860-47df-bd51-1e5300a981c3', 'Fertilization', false, '8e735812-6bb9-4209-86ce-62e4d34fa610');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('071bbb20-2422-4a97-b773-3d6feef013a6', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'What are the vegetative parts of a plant that can produce new plants in Vegetative Propagation?', 'Vegetative propagation utilizes non-floral somatic organs: roots, modified stems, and foliar leaves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd105393-8280-403e-a349-30a19c6a7e18', 'Roots, Stems, and Leaves', true, '071bbb20-2422-4a97-b773-3d6feef013a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('746a4d09-b282-41d1-8839-51ff77f6f893', 'Flowers and Fruit only', false, '071bbb20-2422-4a97-b773-3d6feef013a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c75984f-50d5-4afe-bcfe-bfb47ff5d151', 'Seeds only', false, '071bbb20-2422-4a97-b773-3d6feef013a6');
