INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35ef3315-15af-4cca-b4ad-cab1d9d0bb1c', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'What are the small vegetative scars/notches on a Potato tuber that contain buds capable of growing into new potato plants called?', 'Potato tubers are modified underground storage stems with nodal ''eyes'' containing vegetative axillary buds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('baa56d04-6d46-454f-84a5-702a1bd88924', 'Eyes of the Potato', true, '35ef3315-15af-4cca-b4ad-cab1d9d0bb1c');
