INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6442d30a-1bb8-4700-a0b1-958064605f4d', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'Which plant reproduces vegetatively by producing adventitious vegetative buds along the margins of its thick fleshy LEAVES?', 'Bryophyllum reproduces foliar vegetatively: marginal leaf notches develop adventitious plantlets that root upon falling onto moist soil.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cabe901-f1ed-4431-bb8f-c01bbfc09e42', 'Bryophyllum (Sprout Leaf plant)', true, '6442d30a-1bb8-4700-a0b1-958064605f4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('603bcfa2-1fce-446b-b174-9e16aa861f70', 'Rose', false, '6442d30a-1bb8-4700-a0b1-958064605f4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7228dbb-55b2-4dec-93c0-2e6b5bb79e44', 'Mango', false, '6442d30a-1bb8-4700-a0b1-958064605f4d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8adb7028-f655-4833-badf-963aff8bba6a', 'Wheat', false, '6442d30a-1bb8-4700-a0b1-958064605f4d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30bee757-190d-42ad-ae05-cdc32fb8948e', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'What is the primary reproductive organ of a flowering plant for Sexual Reproduction?', 'Flowers are specialized angiosperm reproductive shoots bearing male (stamens) and female (carpels/pistils) organs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9916efc-70fc-44f6-b83c-3af8cd2b31d7', 'The Flower', true, '30bee757-190d-42ad-ae05-cdc32fb8948e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05fa2fc1-1772-45e0-8cd0-99270f41723d', 'The Leaf', false, '30bee757-190d-42ad-ae05-cdc32fb8948e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21867aea-0247-4da6-9c5f-45c3084dbd68', 'The Stem', false, '30bee757-190d-42ad-ae05-cdc32fb8948e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('761d5f82-2c18-4868-aeb6-61f37d6cf4cb', 'The Root', false, '30bee757-190d-42ad-ae05-cdc32fb8948e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64b59d12-2b7c-4511-92a9-e1db08392337', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'What is the MALE reproductive organ of a flower called, consisting of an Anther and Filament?', 'The stamen is the male floral organ comprising a filament supporting a terminal anther that synthesizes pollen grains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18b8ec13-0127-4715-80b2-9872537aded1', 'Stamen (Androecium)', true, '64b59d12-2b7c-4511-92a9-e1db08392337');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('165fe126-f989-4f56-95d9-228f1a1c732e', 'Pistil (Carpel)', false, '64b59d12-2b7c-4511-92a9-e1db08392337');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('764d3150-92cf-4a8a-ab7b-dc9f92e80ad2', 'Petal', false, '64b59d12-2b7c-4511-92a9-e1db08392337');
