INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0d6979f-a818-40ed-9255-1171caa4ccd3', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'What is the FEMALE reproductive organ of a flower called, consisting of Stigma, Style, and Ovary?', 'The pistil/carpel consists of a receptive stigma, slender style, and a basal ovary enclosing ovules with egg cells.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b7221a7-1a54-482f-a8c4-a2e731112d6a', 'Pistil (or Carpel / Gynoecium)', true, 'c0d6979f-a818-40ed-9255-1171caa4ccd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3189dce-ca38-43b5-a0c5-4c3fcaa0633d', 'Stamen', false, 'c0d6979f-a818-40ed-9255-1171caa4ccd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('407ce234-6d12-456b-9c4d-49c7652e6ba5', 'Anther', false, 'c0d6979f-a818-40ed-9255-1171caa4ccd3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b574c0f1-738e-4982-b2dd-cf9d1bac17b3', 'Filament', false, 'c0d6979f-a818-40ed-9255-1171caa4ccd3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed1323e9-104f-4548-9637-b1bdf97ba045', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'Flowers that contain EITHER only stamens (male) OR only pistils (female) — like Papaya, Corn, and Cucumber — are called:', 'Unisexual (imperfect) flowers possess either androecium or gynoecium exclusively (e.g. dioecious papaya, monoecious maize).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67e982cb-d6d1-4b22-8933-d1b6e419689b', 'Unisexual Flowers', true, 'ed1323e9-104f-4548-9637-b1bdf97ba045');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f7231fa-279c-433a-bea4-27026a3c9e22', 'Bisexual Flowers', false, 'ed1323e9-104f-4548-9637-b1bdf97ba045');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('251062fc-eeb6-4b87-9e6e-47d63a92b6fb', 'Complete Flowers', false, 'ed1323e9-104f-4548-9637-b1bdf97ba045');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1888f683-c9be-4bf4-a8a5-4bce6ddcae28', 'Asexual Flowers', false, 'ed1323e9-104f-4548-9637-b1bdf97ba045');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('361b5e91-7097-418a-925c-cf506e94a057', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'Flowers that contain BOTH stamens and pistil within the same flower — like Mustard, Rose, and Petunia — are called:', 'Bisexual (hermaphroditic/perfect) flowers bear functional stamens and carpels in the same floral whorl.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34953bc2-6cfb-49aa-bf4c-6a8977df8fb1', 'Bisexual Flowers (Hermaphrodite)', true, '361b5e91-7097-418a-925c-cf506e94a057');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d6d8db1-57bf-44cd-8a8f-4652856c7812', 'Unisexual Flowers', false, '361b5e91-7097-418a-925c-cf506e94a057');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dd6ce3d-fd13-4742-9e14-d3d0ed1d9b39', 'Sterile Flowers', false, '361b5e91-7097-418a-925c-cf506e94a057');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9797ad23-696a-4a6c-8498-5999ca0043ae', 'Buds', false, '361b5e91-7097-418a-925c-cf506e94a057');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1dd23244-05f4-4d8f-971e-e14cea8d3dea', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'The transfer of pollen grains from the anther to the stigma of a flower is called:', 'Pollination is the mechanical transference of pollen grains from anther to receptive stigma by wind, water, or biotic vectors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('518714ff-1eed-4b89-92ed-d4ec798e8561', 'Pollination', true, '1dd23244-05f4-4d8f-971e-e14cea8d3dea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('994d39d0-14db-42f6-9e89-0eb87a9f66a4', 'Fertilization', false, '1dd23244-05f4-4d8f-971e-e14cea8d3dea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82a3a807-2cba-4670-93b5-e8188f7872b7', 'Transpiration', false, '1dd23244-05f4-4d8f-971e-e14cea8d3dea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2d312de-a3eb-4252-a46d-721a26e077b6', 'Germination', false, '1dd23244-05f4-4d8f-971e-e14cea8d3dea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0cd007fa-07f7-4283-918a-b584cb483833', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Easy', 'The process of fusion of the male gamete with the female gamete (egg cell) to form a single-celled ZYGOTE is called:', 'Fertilization (syngamy) is the fusion of haploid male and female gametic nuclei inside the embryo sac to form a diploid zygote.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('923ffb67-082b-448f-9a23-38855527a30c', 'Fertilization (Syngamy)', true, '0cd007fa-07f7-4283-918a-b584cb483833');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa000fc4-6726-4829-af51-231cdfe3f589', 'Pollination', false, '0cd007fa-07f7-4283-918a-b584cb483833');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6303691-e3a4-4328-878b-a793c6fe48ee', 'Budding', false, '0cd007fa-07f7-4283-918a-b584cb483833');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1259d00-78e1-4d4d-84b6-ad78ba55f2d7', 'Fragmentation', false, '0cd007fa-07f7-4283-918a-b584cb483833');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82936f15-407c-4183-935f-c8ef0ba491d0', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'How does single-celled Yeast reproduce asexually under favorable nutrient conditions?', 'Yeast multiplies rapidly via asymmetric mitotic budding: blastospores pinch off or form pseudo-mycelial chains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bc64259-1e38-401f-bc65-6961e146d2d2', 'By BUDDING: a small bulb-like projection (bud) gradually grows from the parent cell, receives a replicated nucleus, and detaches to form a new yeast cell', true, '82936f15-407c-4183-935f-c8ef0ba491d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfa74e09-bc51-47e5-a2e2-e3c4ab3a4583', 'By producing large flowers', false, '82936f15-407c-4183-935f-c8ef0ba491d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c303817e-63f1-44e1-ba4e-63aee429b91b', 'By laying eggs', false, '82936f15-407c-4183-935f-c8ef0ba491d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15aadf85-d1b1-468f-a9f7-ae9197fe6052', 'By forming seeds inside fruits', false, '82936f15-407c-4183-935f-c8ef0ba491d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba9b1f24-f114-4fd8-b1d6-f3476453be2c', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'How do green filamentous Algae (like Spirogyra) multiplying rapidly in stagnant ponds reproduce asexually?', 'Spirogyra undergoes vegetative fragmentation: mechanical cleavage of multicellular filaments yields independent surviving clones.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39792da8-d2fb-43cd-b4ae-dddba1754ab6', 'By FRAGMENTATION: the long green filament breaks into two or more fragments, and each fragment grows into a complete new individual', true, 'ba9b1f24-f114-4fd8-b1d6-f3476453be2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f806e6a4-e3f6-4c49-85b9-028658c15ddb', 'By flying through the air', false, 'ba9b1f24-f114-4fd8-b1d6-f3476453be2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9f96839-4e65-45ad-a82f-70932a0d9552', 'By forming woody cones', false, 'ba9b1f24-f114-4fd8-b1d6-f3476453be2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bca78377-14eb-4fdd-bc70-588cd438da62', 'By underground tubers', false, 'ba9b1f24-f114-4fd8-b1d6-f3476453be2c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7700eedc-3e2c-4252-9310-cd2ec16ef2d0', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'How do Fungi (like Bread Mold / Rhizopus), Mosses, and Ferns reproduce asexually?', 'Sporogenesis: sporangiophores bear resistant haploid sporangiospores capable of withstanding environmental desiccation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09b03504-5ce2-4ed8-bdd9-eb6cfd63665d', 'By SPORE FORMATION: microscopic spores protected by a hard, thick protective coat inside Sporangia disperse in air and germinate in moist conditions', true, '7700eedc-3e2c-4252-9310-cd2ec16ef2d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5481d4fc-28fc-4e97-89df-d5f81c656d72', 'By producing honey', false, '7700eedc-3e2c-4252-9310-cd2ec16ef2d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24095eab-7dc2-4c43-8c24-4dd882b70825', 'By seeds in fruits', false, '7700eedc-3e2c-4252-9310-cd2ec16ef2d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d359deb-0075-400c-88e6-51b459adf815', 'By root cuttings only', false, '7700eedc-3e2c-4252-9310-cd2ec16ef2d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53ffa2d5-9324-4349-a70e-69f77131de31', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'What is the difference between SELF-POLLINATION and CROSS-POLLINATION?', 'Self-pollination (autogamy/geitonogamy) transfers pollen within the same genetic individual; cross-pollination (xenogamy) transfers pollen between distinct plants.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f5f617a-63ca-4b24-a1cd-a14b584427f0', 'Self-pollination occurs when pollen lands on the stigma of the SAME flower or another flower on the SAME plant ; Cross-pollination occurs when pollen lands on a flower of a DIFFERENT plant of the same kind', true, '53ffa2d5-9324-4349-a70e-69f77131de31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('698460ea-db04-484e-a360-236d34222437', 'Self-pollination is done by birds only', false, '53ffa2d5-9324-4349-a70e-69f77131de31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90d58b03-a233-4f87-a91b-62bfb5a75fdc', 'Cross-pollination occurs only in winter', false, '53ffa2d5-9324-4349-a70e-69f77131de31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30c50d5e-523d-4a5f-af6f-d4a7ce01179e', 'Both are identical processes', false, '53ffa2d5-9324-4349-a70e-69f77131de31');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('544bfda4-6910-475d-8e40-ff486f80dc28', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'After successful fertilization in a flower, what do the OVARY and the OVULE develop into?', 'Post-fertilization morphogenesis: pericarp ovary wall develops into fruit; fertilized integumented ovules mature into seeds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f32ec9e6-abcd-4511-a43c-6bbca465b11b', 'The OVARY ripens into the FRUIT ; and the OVULES develop into SEEDS containing the embryo', true, '544bfda4-6910-475d-8e40-ff486f80dc28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b202bbb6-6a1a-4e4c-a66c-2d1bebe4aee8', 'The ovary becomes a leaf and ovule becomes a flower', false, '544bfda4-6910-475d-8e40-ff486f80dc28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d151efe0-6aec-4f97-9c56-bb956a8f0f90', 'The ovary becomes root and ovule becomes stem', false, '544bfda4-6910-475d-8e40-ff486f80dc28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a277277-23f2-4f6f-8017-a08c24e5026b', 'Both turn into pollen grains', false, '544bfda4-6910-475d-8e40-ff486f80dc28');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c2b3014-3ac5-4418-9cde-5fe5ffb34010', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'Which of the following plants reproduces vegetatively through modified underground STEM RHIZOMES containing nodes and scaly buds?', 'Ginger (Zingiber) and Turmeric (Curcuma) propagate vegetatively via horizontal subterranean rhizomes bearing dormant axillary buds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('913f6e17-0038-4335-bd95-730acd1194cc', 'Ginger and Turmeric', true, '4c2b3014-3ac5-4418-9cde-5fe5ffb34010');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef09ab7f-b76f-49c0-8243-21be70ae2a06', 'Sweet Potato', false, '4c2b3014-3ac5-4418-9cde-5fe5ffb34010');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9be88c6f-a995-4899-b92c-4d306a36265d', 'Dahlia', false, '4c2b3014-3ac5-4418-9cde-5fe5ffb34010');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a556924d-221f-4c45-a257-11bc1a84ffae', 'Bryophyllum', false, '4c2b3014-3ac5-4418-9cde-5fe5ffb34010');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('638a4760-9705-4559-bd74-068609150ce9', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'Which plants reproduce vegetatively through fleshy swollen ROOT TUBERS?', 'Sweet potato (Ipomoea batatas) and Dahlia develop adventitious root tubers that sprout vegetative shoots.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2e8ed5c-9ca6-411a-966d-5449385bad5e', 'Sweet Potato and Dahlia', true, '638a4760-9705-4559-bd74-068609150ce9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c028d97-5d89-4acd-aea3-c954c000e5a7', 'Potato and Ginger', false, '638a4760-9705-4559-bd74-068609150ce9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c5625bc-06bb-4bba-8ffb-34c6f023d46c', 'Rose and Jasmine', false, '638a4760-9705-4559-bd74-068609150ce9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee37ee88-d558-463a-a5eb-bd0e6c88860b', 'Bryophyllum', false, '638a4760-9705-4559-bd74-068609150ce9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ec0b9ee-9763-4847-b3dd-de65da68cd94', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'Why are light, winged seeds (such as Drumstick and Maple) and hairy parachutes (such as Aak / Madar and Dandelion) dispersed by WIND?', 'Anemochory adaptations: aerodynamic samara wings (Acer, Moringa) and pappus hair tufts (Calotropis, Taraxacum) facilitate wind buoyancy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98f569d4-961e-4603-9e40-923fffda07d2', 'Their lightweight wings and tufts of fine hair act like aerodynamic sails and parachutes, allowing air currents to carry them far away', true, '7ec0b9ee-9763-4847-b3dd-de65da68cd94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf98f3af-745e-49fb-9bb8-420ac3716116', 'Because wind eats the seeds', false, '7ec0b9ee-9763-4847-b3dd-de65da68cd94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb3ac793-1845-4f66-9c4e-f61696de14d7', 'Because birds blow on them', false, '7ec0b9ee-9763-4847-b3dd-de65da68cd94');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f84fc0c-af12-47c3-8841-7c778d3a87bc', 'Because they are sticky', false, '7ec0b9ee-9763-4847-b3dd-de65da68cd94');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d4f5b6b8-1419-4a6e-9869-9eb014f85481', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'How are fibrous, buoyant fruits like the Coconut (Cocos nucifera) dispersed across distant islands?', 'Hydrochory adaptation: fibrous air-trapping coir mesocarp and impervious endocarp allow coconuts to float across marine currents.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be6ffabf-f9e9-4981-b99d-4cc8654b9038', 'By WATER: the thick, spongy, fibrous mesocarp traps air, making coconuts float effortlessly across ocean waves for thousands of miles', true, 'd4f5b6b8-1419-4a6e-9869-9eb014f85481');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35950b75-107f-43f2-9984-30c66ad517cf', 'By wind blowing them in clouds', false, 'd4f5b6b8-1419-4a6e-9869-9eb014f85481');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a340fa0-c253-4b7c-a289-6ce6ef87d0e5', 'By birds carrying whole coconuts', false, 'd4f5b6b8-1419-4a6e-9869-9eb014f85481');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd01df14-25b1-47e2-9a23-91916493bb70', 'By exploding into pieces', false, 'd4f5b6b8-1419-4a6e-9869-9eb014f85481');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc1e1b33-adb3-451b-bb2a-0f57f34d1147', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'How are spiny seeds equipped with sharp hooks (such as Xanthium and Urena) dispersed to new habitats?', 'Epizoochory adaptation: stiff hooked spines on Xanthium burs latch onto animal pelts and fleece for long-distance transport.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06172c37-326d-484b-b900-af29df7af569', 'By ANIMALS: their hooked spines cling stubbornly to the fur of passing animals or human clothing and get transported far away', true, 'fc1e1b33-adb3-451b-bb2a-0f57f34d1147');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a473609-c309-4d3f-8ea3-eb361bd0c7dc', 'By swimming in rivers', false, 'fc1e1b33-adb3-451b-bb2a-0f57f34d1147');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e80c947f-402c-4f48-bbf3-97bc52c2136e', 'By flying with wings', false, 'fc1e1b33-adb3-451b-bb2a-0f57f34d1147');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fadd908-8bdb-4fbc-87c6-4687d79c8d2f', 'By melting in the sun', false, 'fc1e1b33-adb3-451b-bb2a-0f57f34d1147');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('adb5ebf0-5af2-46de-a915-bff0bb7a5497', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'How do Castor and Balsam plants disperse their seeds through sudden explosive mechanical action?', 'Autochory / Ballochory: desiccation creates hygroscopic tissue tension that ruptures the capsule explosively, projecting seeds meters away.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99e051ef-86a7-4326-8a55-0a22d920ceb6', 'Their ripe seed pods burst open suddenly with explosive jerks upon drying, flinging the seeds forcefully far away from the parent plant', true, 'adb5ebf0-5af2-46de-a915-bff0bb7a5497');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a0506c3-9cf1-4975-8a2c-0e5ad155a7a2', 'By floating in water', false, 'adb5ebf0-5af2-46de-a915-bff0bb7a5497');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f196867-906a-4dff-a8ce-0f5549b5267e', 'By emitting sweet perfume', false, 'adb5ebf0-5af2-46de-a915-bff0bb7a5497');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d366da2-6e5c-4721-a267-98c8f0a810e8', 'By growing underground', false, 'adb5ebf0-5af2-46de-a915-bff0bb7a5497');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58c26d41-b1e9-4413-b96c-99642eea5522', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'What is the horticultural advantage of Vegetative Propagation (like stem cuttings in Roses, Sugarcane, and Grapes) for farmers?', 'Vegetative cloning bypasses juvenile seed dormancy, accelerates fruiting, and guarantees 100% true-to-type genetic fidelity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31068469-fd12-4540-8c9d-5cfa8e18ace2', 'Plants grown vegetatively take much less time to bear flowers and fruits, and are exact genetic clones preserving all desirable parental qualities', true, '58c26d41-b1e9-4413-b96c-99642eea5522');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53948657-0962-42fb-8656-4c442b6ceb5b', 'They produce seeds with random changes', false, '58c26d41-b1e9-4413-b96c-99642eea5522');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21ffbea6-397b-4d88-9322-7c8c523bf62e', 'They do not need water or soil', false, '58c26d41-b1e9-4413-b96c-99642eea5522');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c3ee1af-8f65-43ea-a2d8-e9cabbbfcb16', 'They never grow leaves', false, '58c26d41-b1e9-4413-b96c-99642eea5522');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4cb998ce-8346-4b6e-b18c-3bcf755b3257', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'What grows out of a pollen grain after it lands on the sticky receptive stigma of a compatible flower?', 'Chemotropic pollen tube germination: the tube cell elongates through stylar transmitting tissue, conveying sperm nuclei to the micropyle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2fccdd9-e737-4753-b908-41ba766dc163', 'A long Pollen Tube that grows downwards through the style to deliver male gametes into the ovary''s ovule', true, '4cb998ce-8346-4b6e-b18c-3bcf755b3257');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48769973-05e5-441a-92eb-d3d96a159883', 'A new green leaf', false, '4cb998ce-8346-4b6e-b18c-3bcf755b3257');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a48c637f-9024-45af-85b2-c731323f4f9a', 'A root hair', false, '4cb998ce-8346-4b6e-b18c-3bcf755b3257');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfdde91f-a727-4901-b4c0-8e12d1ff5fcc', 'A seed coat', false, '4cb998ce-8346-4b6e-b18c-3bcf755b3257');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa09a3d4-556b-4317-804b-13d3480ba78a', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'Why do insect-pollinated flowers (like Rose, Jasmine, and Sunflower) possess brightly colored petals, sweet fragrance, and sugary nectar?', 'Entomophilous floral syndrome: chromatic showy corollas, volatile terpenes, and nectar rewards co-evolved to attract insect pollinators.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('194e46c9-fead-4121-b53a-50be0b8aa8b1', 'To attract insect pollinators (bees, butterflies) which brush against anthers and carry sticky pollen grains to other flowers', true, 'aa09a3d4-556b-4317-804b-13d3480ba78a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c659369-ea13-4962-8bba-7c04c10d64e3', 'To scare away all insects', false, 'aa09a3d4-556b-4317-804b-13d3480ba78a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aea35f5c-6d79-4723-94fe-1c26863b4434', 'To cool the flower during hot days', false, 'aa09a3d4-556b-4317-804b-13d3480ba78a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b15f0132-c387-4023-855b-f21407535a5a', 'To produce green chlorophyll', false, 'aa09a3d4-556b-4317-804b-13d3480ba78a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38056490-a2b6-4163-9202-913c228b17e4', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'What are the distinguishing characteristics of Wind-Pollinated flowers (like Grasses, Corn, and Wheat)?', 'Anemophilous floral syndrome: reduced perianth, non-sticky aerodynamically buoyant pollen produced in billions, and plumose stigmas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c9e308b-45ba-4527-9eeb-aa3fc7f365ce', 'They have small, dull non-scented flowers, enormous quantities of light dry powdery pollen, and large feathery stigmas exposed to catch windborne pollen', true, '38056490-a2b6-4163-9202-913c228b17e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d98512b-e56c-4275-9c2b-192ec376fd66', 'They have giant sweet-smelling red petals', false, '38056490-a2b6-4163-9202-913c228b17e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3126394d-f451-4c48-bcec-830b13fc651d', 'They produce thick sticky nectar', false, '38056490-a2b6-4163-9202-913c228b17e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cb7e3bc-e945-4943-9cb1-55e19863bd6d', 'They open only underwater', false, '38056490-a2b6-4163-9202-913c228b17e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('05df1b66-b7ba-4436-b419-29474415f2d4', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Medium', 'Why is Seed Dispersal essential for the healthy survival and distribution of plant species?', 'Seed dispersal reduces density-dependent sibling competition, mitigates pathogen transmission, and colonizes novel ecological niches.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9097d2ef-a914-4dda-a008-e936298d7776', 'It prevents intense competition for sunlight, water, minerals, and space among seedlings near the parent plant, while invading new geographic habitats', true, '05df1b66-b7ba-4436-b419-29474415f2d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b62834f5-a21a-4341-87e0-cc558a915ac8', 'It destroys old plants', false, '05df1b66-b7ba-4436-b419-29474415f2d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2378e69-4e69-4c9e-b7d8-aa4f056b36b2', 'It keeps all seeds in one single spot', false, '05df1b66-b7ba-4436-b419-29474415f2d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9705cc66-5348-4e5a-a5e0-3a1729394030', 'It stops plants from growing', false, '05df1b66-b7ba-4436-b419-29474415f2d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e5813e1-9e2f-4d20-b35f-f92a8a291cd5', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5a0deba-0110-43f0-99ac-80439ac22751', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '4e5813e1-9e2f-4d20-b35f-f92a8a291cd5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da5dcc54-8d6c-459e-b159-eca46a84a13d', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '4e5813e1-9e2f-4d20-b35f-f92a8a291cd5');
