INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7e54009-b47d-4199-9d2d-5939dae42754', 'Class 7', 'Science', 'Chapter 8: Reproduction in Plants', 'Hard', 'Spot the IMPOSTER in the following group of Plants and their specific Modes of Asexual Reproduction:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('073acaf9-a6d9-45a3-acb2-154ec5f7af78', 'Mode 1', false, 'b7e54009-b47d-4199-9d2d-5939dae42754');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0eb28ae6-162f-4703-a21d-2527ae5c84f3', 'Mode 2', false, 'b7e54009-b47d-4199-9d2d-5939dae42754');
