INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1162adec-9a1c-4b5b-91ef-1215bedfb4bb', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Which of the following rational numbers is GREATER: -4/5 or -5/6?', '-24/30 > -25/30, hence -4/5 > -5/6.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7110c936-6d04-4087-bfda-6abe6e96fbf3', '-4/5 is greater (Convert to common denominator 30: -4/5 = -24/30 and -5/6 = -25/30 ; Since -24 > -25, -4/5 > -5/6)', true, '1162adec-9a1c-4b5b-91ef-1215bedfb4bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac5990b0-25a5-429c-8b46-cb67e4e42878', '-5/6 is greater', false, '1162adec-9a1c-4b5b-91ef-1215bedfb4bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48bb94f7-68ad-4818-99a1-ab6fa83ebd05', 'Both are equal', false, '1162adec-9a1c-4b5b-91ef-1215bedfb4bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8eaff7b6-07ad-4f5c-8d44-3d4e3b847198', 'Cannot be compared', false, '1162adec-9a1c-4b5b-91ef-1215bedfb4bb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5a2be55-912a-4f47-b015-66e33e7313d8', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Express -3/5 as a rational number with Denominator = 20:', '(-3 × 4)/(5 × 4) = -12/20.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58ea95a4-4d9e-4450-b05c-28b56bd8fb1a', '-12/20 (Multiply numerator and denominator by 4: (-3 × 4)/(5 × 4) = -12/20)', true, 'c5a2be55-912a-4f47-b015-66e33e7313d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2799693a-6144-45d5-af29-a9a0f4c36794', '-15/20', false, 'c5a2be55-912a-4f47-b015-66e33e7313d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75287dd7-61a8-4851-ae7e-0bc6639c463b', '-9/20', false, 'c5a2be55-912a-4f47-b015-66e33e7313d8');
