INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c30dd9d-c4eb-4de4-972b-127e4689e0e9', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Which pair of rational numbers represents the SAME EQUIVALENT rational number?', '-16/20 = -4/5 and 20/(-25) = -4/5, making them strictly equivalent.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bd8a80e-cb4e-420b-a3ca-1e6f52f19277', '-16/20 and 20/-25 (Both simplify to -4/5 in standard form)', true, '9c30dd9d-c4eb-4de4-972b-127e4689e0e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a9e927c-cb83-4202-a35a-53736a0b3e6e', '-7/21 and 3/9', false, '9c30dd9d-c4eb-4de4-972b-127e4689e0e9');
