INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad749cf7-0a19-4910-9c1b-1776154fbdaa', '1/3 and -1/9', false, '9c30dd9d-c4eb-4de4-972b-127e4689e0e9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ce12f289-3785-463b-b997-a282d81e3971', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Find the Value of: (-4/5) × (-5/4):', '(-4/5) × (-5/4) = 20/20 = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6eda600-d3b4-45ef-9713-7d4111d95569', '1 (Product of a non-zero rational number and its reciprocal is always 1)', true, 'ce12f289-3785-463b-b997-a282d81e3971');
