INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a4f31b26-ab1f-4c68-be8e-c618a4250a7c', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Find the Value of: (-7/12) ÷ (-2/13):', '(-7/12) ÷ (-2/13) = (-7/12) × (-13/2) = 91/24.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54cbaa8b-1665-41d4-8416-121cf5fbfe2f', '91/24 ((-7/12) × (-13/2) = 91 / 24)', true, 'a4f31b26-ab1f-4c68-be8e-c618a4250a7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f2e5eb7-901d-4e54-89f3-2d86598ef01a', '-91/24', false, 'a4f31b26-ab1f-4c68-be8e-c618a4250a7c');
