INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c7c2436-c006-47af-804f-46ea686ba0f6', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'What number should be added to -5/8 so as to get -3/2?', 'x = -3/2 - (-5/8) = -12/8 + 5/8 = -7/8.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b68f51d-f031-4cc4-a9bc-69e5b3fa86f4', '-7/8 (x = -3/2 - (-5/8) = -3/2 + 5/8 = (-12 + 5)/8 = -7/8)', true, '9c7c2436-c006-47af-804f-46ea686ba0f6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cebc545-9c6c-4b7b-9626-bf0de2968699', '7/8', false, '9c7c2436-c006-47af-804f-46ea686ba0f6');
