INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23c8af99-9678-4727-bd85-92d91fc56ed6', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'What number should be subtracted from -2/3 to get -1/6?', '-2/3 - x = -1/6 → x = -2/3 + 1/6 = -3/6 = -1/2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('beddb589-8811-4863-b77c-c6dda6b26e34', '-1/2 (x = -2/3 - (-1/6) = -2/3 + 1/6 = (-4 + 1)/6 = -3/6 = -1/2)', true, '23c8af99-9678-4727-bd85-92d91fc56ed6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a95685d7-e75a-4d5b-b875-b9cc4663a16d', '1/2', false, '23c8af99-9678-4727-bd85-92d91fc56ed6');
