INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ac61e4e2-2237-4b17-9b9f-9c9b3733293c', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'The product of two rational numbers is -9/16. If one of the numbers is -4/3, find the other number:', 'x = (-9/16) ÷ (-4/3) = (-9/16) × (-3/4) = 27/64.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd54d30a-5f40-451b-b2b3-175fa4b7b2e8', '27/64 (Other number = (-9/16) ÷ (-4/3) = (-9/16) × (-3/4) = 27 / 64)', true, 'ac61e4e2-2237-4b17-9b9f-9c9b3733293c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bcb23aa-cd46-4b1c-a9b9-709966888826', '-27/64', false, 'ac61e4e2-2237-4b17-9b9f-9c9b3733293c');
