INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7659c34f-c7d3-4616-aad1-572a4e8de7c9', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Write three rational numbers between -2 and -1:', '-2 = -8/4 and -1 = -4/4. Intervening rational numbers: -7/4, -6/4, -5/4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88e2febc-f257-4b3e-b634-22ba6274e770', '-7/4, -6/4 (-3/2), and -5/4 (Converting to denominator 4: -8/4 and -4/4)', true, '7659c34f-c7d3-4616-aad1-572a4e8de7c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2950c662-0d2b-4a50-bc29-5041425465f7', '-1/2, 0, 1/2', false, '7659c34f-c7d3-4616-aad1-572a4e8de7c9');
