INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cd0e5cc9-be61-429f-9a45-480b51fbf7f5', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Arrange the rational numbers -3/5, -2/5, -1/5 in ASCENDING order (smallest to largest):', 'With identical positive denominators, compare numerators: -3 < -2 < -1, so -3/5 < -2/5 < -1/5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77c99eca-98ef-4cf5-b09e-2e37e88e134a', '-3/5 < -2/5 < -1/5', true, 'cd0e5cc9-be61-429f-9a45-480b51fbf7f5');
