INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('461ca111-b64e-4d6b-ba0d-69d32dd35aba', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Medium', 'Find the mean (average) of the rational numbers 1/3 and 1/2:', 'Mean = ½(1/3 + 1/2) = ½(5/6) = 5/12 (lies strictly between 1/3 and 1/2).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('156193bd-bc60-420c-9279-b17e21c092d3', '5/12 (Mean = (1/3 + 1/2) / 2 = (5/6) / 2 = 5/12)', true, '461ca111-b64e-4d6b-ba0d-69d32dd35aba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('904e411b-5f78-4a11-abc1-fd5e4e3a00de', '2/5', false, '461ca111-b64e-4d6b-ba0d-69d32dd35aba');
