INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29d483f1-a34f-4fd9-bb0b-b52d00575976', 'Property 1', false, '8ac1fdb1-e134-4ace-ad8a-af472329bcba');
