INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b485588f-052a-4d0e-b828-df3a7354261d', 'Property 3', false, '8ac1fdb1-e134-4ace-ad8a-af472329bcba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f069771a-bb2b-45bd-a253-c5c63d5be5e2', 'Property 4 (Subtraction is NOT commutative ; for example: 2/3 - 1/3 = 1/3 ≠ 1/3 - 2/3 = -1/3)', true, '8ac1fdb1-e134-4ace-ad8a-af472329bcba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('727f8f20-631b-46a4-8423-02369b1e3f46', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'Evaluate the arithmetic expression using distributive property:
(-3/5) × (3/7) + (2/5) × (3/7):', 'Distributive property: 3/7 × (-3/5 + 2/5) = 3/7 × (-1/5) = -3/35.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bb6dda2-a143-467f-9e96-9231edb3404e', '-3/35 ((3/7) × (-3/5 + 2/5) = (3/7) × (-1/5) = -3 / 35)', true, '727f8f20-631b-46a4-8423-02369b1e3f46');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ec74e34-052c-451c-ab79-9ecb5d296ea1', '3/35', false, '727f8f20-631b-46a4-8423-02369b1e3f46');
