INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9ac9dce-08b1-4776-bcaa-b7ce729cb3b5', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'Match Column I (Rational Operations) with Column II (Evaluated Values in Simplest Form):
(a) (-3/7) + (5/14)        -> (i) -1/14
(b) (-2/3) - (-5/6)        -> (ii) 1/6
(c) (-8/9) × (-27/16)      -> (iii) 3/2
(d) (-3/5) ÷ (9/10)        -> (iv) -2/3', '(-6+5)/14 = -1/14; (-4+5)/6 = 1/6; (8×27)/(9×16) = 3/2; (-3/5)×(10/9) = -2/3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2ea494e-ec3e-4912-9f51-dfcbf52da3cc', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'e9ac9dce-08b1-4776-bcaa-b7ce729cb3b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddddf796-2b08-4883-b3b0-70a060fcfe58', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'e9ac9dce-08b1-4776-bcaa-b7ce729cb3b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23beddce-6759-4302-9e5f-2202c25c99f5', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'e9ac9dce-08b1-4776-bcaa-b7ce729cb3b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58577d91-62fa-4566-bced-1fad04f199d1', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'e9ac9dce-08b1-4776-bcaa-b7ce729cb3b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e34abc6f-410b-4e64-ac4b-c023db1b063f', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'Read the statements regarding number classifications:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c691ac91-2d39-4d19-b26d-c05a9cfda401', 'Statements 1 and 2 only', true, 'e34abc6f-410b-4e64-ac4b-c023db1b063f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c984ea2a-ec28-4f16-ace4-7b7692fe14cc', 'Statements 2 and 3 only', false, 'e34abc6f-410b-4e64-ac4b-c023db1b063f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b10f915-f0df-4ed4-9dfc-2f3a6b60593d', 'Statements 1 and 3 only', false, 'e34abc6f-410b-4e64-ac4b-c023db1b063f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0c18391-0c88-46d6-ab1f-c9c2c35d8d54', 'All Statements 1, 2, and 3', false, 'e34abc6f-410b-4e64-ac4b-c023db1b063f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c72ec8b-8087-4e83-91ef-ab310d762688', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'If x = -2/3 and y = 4/5, verify that |x + y| ≤ |x| + |y| (Triangle Inequality for Rational Numbers):', 'Absolute value triangle inequality: |(-2/3) + (4/5)| = 2/15 ≤ |-2/3| + |4/5| = 22/15.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47a7b894-2a0d-431d-b479-448d88535d3a', '|x + y| = |-2/3 + 4/5| = |2/15| = 2/15 ; |x| + |y| = 2/3 + 4/5 = 22/15 ; Since 2/15 < 22/15, the inequality strictly holds true', true, '1c72ec8b-8087-4e83-91ef-ab310d762688');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5411fe9e-0e2a-4bf4-a90b-40cde9a20af3', '|x + y| = 22/15', false, '1c72ec8b-8087-4e83-91ef-ab310d762688');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('751ee4f0-d60c-43c8-8551-7f6c56ece4a0', '|x| + |y| = 2/15', false, '1c72ec8b-8087-4e83-91ef-ab310d762688');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c8cf59e-d244-458e-927d-d4731ba931de', 'The inequality is false', false, '1c72ec8b-8087-4e83-91ef-ab310d762688');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7c8759f-b002-457c-a212-9ed3a615d61e', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'Find the rational number exactly HALFWAY (the midpoint) between -3/4 and 5/6:', 'Midpoint = ½((-9/12) + (10/12)) = ½(1/12) = 1/24.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cb06733-5021-4646-9ffb-3648b6b23e8d', '1/24 (Midpoint = 1/2 × (-3/4 + 5/6) = 1/2 × ((-9 + 10) / 12) = 1/2 × (1/12) = 1/24)', true, 'd7c8759f-b002-457c-a212-9ed3a615d61e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e040916a-90ec-41bd-a0ae-8fcf19228b20', '1/12', false, 'd7c8759f-b002-457c-a212-9ed3a615d61e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c9ddc19-1f95-41fd-af8c-6b9d5173354b', '-1/24', false, 'd7c8759f-b002-457c-a212-9ed3a615d61e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2aa5d227-d614-4b22-b0b9-811d36f09710', '1/6', false, 'd7c8759f-b002-457c-a212-9ed3a615d61e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3cc72b93-6dc4-4250-9c51-389cbddae81a', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'A car is traveling at an average speed of 40 2/5 km/h. How much distance will it cover in 7 1/2 hours?', 'Distance = (202/5) × (15/2) = 101 × 3 = 303 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e9eaee9-c467-43c1-867c-51abd2a00c3d', '303 km (Speed = 202/5 km/h ; Time = 15/2 h ; Distance = (202/5) × (15/2) = (202 × 3) / 2 = 101 × 3 = 303 km)', true, '3cc72b93-6dc4-4250-9c51-389cbddae81a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30e07537-05f5-4cf7-bb96-f1cc246d1bde', '300 km', false, '3cc72b93-6dc4-4250-9c51-389cbddae81a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b05ec5a3-3d30-4c75-8a46-cae1c590cc61', '295 km', false, '3cc72b93-6dc4-4250-9c51-389cbddae81a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97926695-89fe-4f16-aaa1-4bcf19a20b24', '310 km', false, '3cc72b93-6dc4-4250-9c51-389cbddae81a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2c8dfe36-075c-4b2d-ae3f-8b8cd181df43', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'From a rope of length 11 metres, two pieces of lengths 2 3/5 m and 3 3/10 m are cut off. What is the length of the REMAINING rope?', 'Total cut = 5.9 m. Remaining = 11 - 5.9 = 5.1 m = 51/10 = 5 1/10 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('459b5c9e-e4a2-428e-97de-3f3db9483e75', '5 1/10 m (Total cut = 13/5 + 33/10 = 26/10 + 33/10 = 59/10 m ; Remaining = 11 - 59/10 = (110 - 59)/10 = 51/10 = 5 1/10 m)', true, '2c8dfe36-075c-4b2d-ae3f-8b8cd181df43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfc2be79-276d-4fd6-a813-7581d539b464', '4 9/10 m', false, '2c8dfe36-075c-4b2d-ae3f-8b8cd181df43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7599757d-d63a-4696-97e8-c10f4bc31bcc', '5 3/10 m', false, '2c8dfe36-075c-4b2d-ae3f-8b8cd181df43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1a9f9c4-9c61-47a9-beb1-0a5857bf540f', '6 1/10 m', false, '2c8dfe36-075c-4b2d-ae3f-8b8cd181df43');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3351ddc-4d9b-43af-809e-a5dd651b1040', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'Divide the sum of 65/12 and 8/3 by their difference:', 'Sum = 97/12. Difference = 33/12. Quotient = (97/12) / (33/12) = 97/33.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6639700a-5b46-4636-9714-69471ca0d6a5', '97/33 (Sum = 65/12 + 32/12 = 97/12 ; Difference = 65/12 - 32/12 = 33/12 ; Division = (97/12) ÷ (33/12) = 97 / 33)', true, 'c3351ddc-4d9b-43af-809e-a5dd651b1040');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b074addf-f4d0-4459-8cff-5169a3c3cc84', '33/97', false, 'c3351ddc-4d9b-43af-809e-a5dd651b1040');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e51d84c7-837d-4a35-bc0c-e25f4375e53e', '97/12', false, 'c3351ddc-4d9b-43af-809e-a5dd651b1040');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('051c05ac-a8c2-4b41-a4c1-a8031b99f08b', '33/12', false, 'c3351ddc-4d9b-43af-809e-a5dd651b1040');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a0f1b213-16f6-4b31-aca3-721a33910708', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'If a = 1/2, b = -1/3, and c = 2/5, verify the Associative Law of Addition: (a + b) + c = a + (b + c):', 'Both sides evaluate identically to 17/30, demonstrating associativity of rational addition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78aa0a44-3593-4594-8537-3d220e7ced58', '(1/2 + (-1/3)) + 2/5 = (1/6) + 2/5 = (5 + 12)/30 = 17/30 ; 1/2 + (-1/3 + 2/5) = 1/2 + (1/15) = (15 + 2)/30 = 17/30 (Verified)', true, 'a0f1b213-16f6-4b31-aca3-721a33910708');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3669560-4833-4b86-b2e2-a2723974fa45', '17/30 and 19/30 (False)', false, 'a0f1b213-16f6-4b31-aca3-721a33910708');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec0145dc-4efd-4a54-938f-372a878163d8', '15/30', false, 'a0f1b213-16f6-4b31-aca3-721a33910708');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0426371f-ed6f-4326-bc6a-a641bf54a425', '0', false, 'a0f1b213-16f6-4b31-aca3-721a33910708');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9477319c-e3ee-4d71-a352-0b307b0215e9', 'Class 7', 'Mathematics', 'Chapter 8: Rational Numbers', 'Hard', 'Why is the algebraic Field of Rational Numbers (ℚ) indispensable in scientific measurement, engineering calibrations, and computational arithmetic?', 'The rational field ℚ provides the rigorous mathematical infrastructure for fractional ratios, dimensional analysis, and digital arithmetic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e36548f8-b01c-42fd-b07e-77e065ca6b69', 'Rational numbers provide the exact fractional precision required for discrete physics ratios, scale conversions, financial balance accounting, and floating-point numeric approximations', true, '9477319c-e3ee-4d71-a352-0b307b0215e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36bd1e01-49bc-41f1-8b06-ea4084cec411', 'Because rational numbers are the only numbers that exist', false, '9477319c-e3ee-4d71-a352-0b307b0215e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3d77b68-c48f-4286-990d-beb280497d20', 'Because rational numbers eliminate the need for division', false, '9477319c-e3ee-4d71-a352-0b307b0215e9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de439cbd-c94a-41f5-9378-0bf4eef309d5', 'Because rational numbers are always whole integers', false, '9477319c-e3ee-4d71-a352-0b307b0215e9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6add942f-3167-40fe-ac18-331910277d02', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'What was early primitive man''s initial attitude toward fire before understanding its scientific nature?', 'Early humans feared fire because of its destructive devastation in volcanic eruptions and lightning forest fires.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22cde30e-936e-4317-a286-1f177e7d7e2c', 'Early humans were deeply frightened of fire, viewing it as a mysterious, terrifying, and dangerous destructive force', true, '6add942f-3167-40fe-ac18-331910277d02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a35575ef-b3e1-411e-9a57-229386180bad', 'They loved fire and played with it', false, '6add942f-3167-40fe-ac18-331910277d02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2813e602-6f36-4e4b-94d6-625dc9f97020', 'They ignored fire completely', false, '6add942f-3167-40fe-ac18-331910277d02');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18f71a83-ea59-4c06-b1eb-2a91e49b2de7', 'They kept fire in ice boxes', false, '6add942f-3167-40fe-ac18-331910277d02');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d477c08-b1a5-495b-8943-de739c43496f', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'Scientifically, what three essential things are required to make and sustain FIRE?', 'Fire triangle: Fuel + Oxygen (from air) + Heat (reaching ignition temperature) are the three mandatory elements.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16fbc54b-99de-4a1e-b687-946f40b69b82', 'Fuel, Oxygen, and Heat', true, '5d477c08-b1a5-495b-8943-de739c43496f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0920b2e0-b8ed-4dc7-badd-60a267a13d71', 'Water, Wood, and Air', false, '5d477c08-b1a5-495b-8943-de739c43496f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e7f7c64-1582-4cb5-8eae-caf542443209', 'Coal, Ice, and Smoke', false, '5d477c08-b1a5-495b-8943-de739c43496f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16b7babf-4021-487e-8ed3-88d126fc52d7', 'Gasoline, Sand, and Wind', false, '5d477c08-b1a5-495b-8943-de739c43496f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47204f82-b4ec-4b4b-a7fc-40d602adb0c0', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'What is the particular minimum temperature at which a specific fuel begins to catch fire and burn called?', 'The minimum temperature at which a combustible fuel begins burning is its ''flash point'' or ''kindling temperature''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('726acdb3-dd86-4d41-b5f2-03a742842ce6', 'Flash Point (or Kindling Temperature)', true, '47204f82-b4ec-4b4b-a7fc-40d602adb0c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdb8aa26-c541-4153-a18c-ecac8f545a1a', 'Boiling Point', false, '47204f82-b4ec-4b4b-a7fc-40d602adb0c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc64c2ef-64ed-4c1f-a878-211ec2b1bd1e', 'Freezing Point', false, '47204f82-b4ec-4b4b-a7fc-40d602adb0c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6fbc046-d557-424d-9e15-8dc5b6099087', 'Melting Point', false, '47204f82-b4ec-4b4b-a7fc-40d602adb0c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b591265-99a7-49b2-b375-8b0d28f60a9b', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'Why is Fire described as ''a good servant but a bad master'' in the prose text?', 'The proverb highlights that controlled combustion serves human civilization, whereas runaway infernos cause catastrophic destruction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ec98572-7c8c-42de-bb06-16bf5fff951e', 'As long as fire is kept under control, it is incredibly useful for cooking, heating, and generating power ; but if it gets out of control, it destroys homes, forests, and lives', true, '6b591265-99a7-49b2-b375-8b0d28f60a9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f934726d-0e11-43f6-ae01-e2aece603482', 'Because fire works in restaurants', false, '6b591265-99a7-49b2-b375-8b0d28f60a9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8ea96a3-a0fa-4f07-98a5-d563f4f41d2a', 'Because fire can be bought in shops', false, '6b591265-99a7-49b2-b375-8b0d28f60a9b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47b9d1d9-d555-4d1c-bdfd-b0b08d410100', 'Because fire only burns in winter', false, '6b591265-99a7-49b2-b375-8b0d28f60a9b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6105aac4-0325-4a48-863a-6c5657842a91', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'What are the three fundamental ways to extinguish or put out a fire?', 'Extinguishing fire involves breaking the fire triangle: fuel starvation, oxygen smothering, or thermal cooling.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c7e917d-0700-4e6d-a55b-3dd8289bfbcd', '1. Take away the Fuel ; 2. Prevent Oxygen from reaching it (smothering) ; 3. Remove the Heat / bring temperature below flash point (spraying water)', true, '6105aac4-0325-4a48-863a-6c5657842a91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9626f08-3226-4ad1-bd7b-db7ec613ab6a', '1. Add more wood ; 2. Blow air ; 3. Pour oil', false, '6105aac4-0325-4a48-863a-6c5657842a91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0b8a787-8371-4398-b45c-1baa83a50c9f', '1. Run away ; 2. Close eyes ; 3. Shout', false, '6105aac4-0325-4a48-863a-6c5657842a91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85b08f16-016a-4dbe-91d4-4b6b367c33e7', '1. Paint the walls ; 2. Open windows ; 3. Plant trees', false, '6105aac4-0325-4a48-863a-6c5657842a91');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('192fc57b-0af3-497f-aa1e-76852fdf34fd', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'Why should Water NEVER be used to extinguish an Electrical Fire or an Oil Fire?', 'Tap water conducts lethal current in electrical fires, and low-density oil floats atop water, spreading flames.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de8fcb73-0772-425b-9e8b-899fa3a55f62', 'Water conducts electricity (risking lethal electric shocks) ; and burning oil floats on water and spreads the blazing fire everywhere', true, '192fc57b-0af3-497f-aa1e-76852fdf34fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e057eba8-713e-4d9e-950d-2084f35c05d9', 'Because water catches fire', false, '192fc57b-0af3-497f-aa1e-76852fdf34fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1f62dc0-da4c-433c-961d-d49ce104cc8c', 'Because water turns into oil', false, '192fc57b-0af3-497f-aa1e-76852fdf34fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbb083cc-63e7-4ca8-943a-09ce305e2db9', 'Because water is too expensive', false, '192fc57b-0af3-497f-aa1e-76852fdf34fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('15ba77e0-501f-418d-ab40-f7f91ac34b84', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'What type of fire extinguisher is safest and most effective for combating Electrical and Oil fires?', 'CO₂ extinguishers displace oxygen and do not conduct electricity, suffocating oil and electrical fires safely.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff5540f8-8822-4a89-bb32-358896bd4eb4', 'Carbon Dioxide (CO₂) Fire Extinguisher', true, '15ba77e0-501f-418d-ab40-f7f91ac34b84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc9bb0a2-7718-4f63-89ff-0cc441a67a44', 'Plain tap water bucket', false, '15ba77e0-501f-418d-ab40-f7f91ac34b84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2d428e9-c80c-4998-b8ee-c1d38205719d', 'Blowing breath', false, '15ba77e0-501f-418d-ab40-f7f91ac34b84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94f2cfc7-ae4f-4816-b4f5-8f31efff9502', 'Spreading paper', false, '15ba77e0-501f-418d-ab40-f7f91ac34b84');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a936bb4-4c72-4982-96c4-cdde335d8165', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'In Lois Brandt Phillips''s poem ''Meadow Surprises'', what two sensory habits must a visitor have to discover hidden wonders in a meadow?', 'The poem begins: ''Meadows have surprises, / You can find them if you look; / Walk softly through the velvet grass, / And listen by the brook.''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a64f265-68ed-43e3-8b75-60ceb9d78dfe', 'A keen, observant Eye and a sharp, patient Ear', true, '1a936bb4-4c72-4982-96c4-cdde335d8165');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c30e8bd6-e936-4861-ad2f-51e2d319a7cb', 'A loud voice and big boots', false, '1a936bb4-4c72-4982-96c4-cdde335d8165');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87836c34-d0bb-461f-a991-b830c8867acc', 'A camera and a telephone', false, '1a936bb4-4c72-4982-96c4-cdde335d8165');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffe5ffbe-5427-48b5-bdfb-a88dcf5dcb45', 'A net and a cage', false, '1a936bb4-4c72-4982-96c4-cdde335d8165');
