INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('df800f07-9c6e-4f64-a8d7-a5dd8402e869', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Easy', 'What meadow dwellings and animal homes are mentioned in ''Meadow Surprises''?', 'The poem catalogs natural habitats: ''Burrows in the ground, / A nest beneath tall grasses, / The ant''s amazing mound.''.', NOW()) ON CONFLICT DO NOTHING;
