INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0358c5c-535b-4215-bd89-4e5af099461f', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'What is the chemical reaction called when oxygen in the air combines rapidly with carbon and hydrogen in a fuel to release heat and light?', 'Combustion is the rapid exothermic oxidation of hydrocarbons yielding CO₂, H₂O, heat, and radiant photon emission (light).', NOW()) ON CONFLICT DO NOTHING;
