INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc7dd20b-8306-4a0f-86c3-5d60e305e1e4', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'How did people fight fires in towns before the advent of organized fire brigades and motorized fire engines?', 'Historic firefighting utilized bucket chains where lines of citizens swiftly relayed water buckets from hydrants/wells to the flames.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d708481-ec62-4e31-8541-060826bad83d', 'People formed human bucket brigades, passing buckets of water hand-to-hand from nearby wells and ponds to pour onto the burning building', true, 'fc7dd20b-8306-4a0f-86c3-5d60e305e1e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa773dfa-76d1-4959-bc77-14d05715046e', 'They waited for winter rain', false, 'fc7dd20b-8306-4a0f-86c3-5d60e305e1e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02d6d4cd-43a3-4faf-a85e-45826dc4c46c', 'They blew on the fire with fans', false, 'fc7dd20b-8306-4a0f-86c3-5d60e305e1e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78f0ff3f-4624-46ff-b358-837c964d7fe2', 'They covered the town with blankets', false, 'fc7dd20b-8306-4a0f-86c3-5d60e305e1e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bdd2082e-7b5a-45e0-8095-b3dcce91ffc5', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'Why do modern city building construction laws require leaving open space between large buildings?', 'Fire safety building codes mandate setback spaces to create thermal firebreaks that prevent structural flame leap.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b439d178-2827-4c1f-8fe1-900e0faecf69', 'To reduce the risk of fire jumping and spreading from one structure to neighboring buildings', true, 'bdd2082e-7b5a-45e0-8095-b3dcce91ffc5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13277c62-9038-4774-b704-b29fec54c945', 'To build wider roads for racing', false, 'bdd2082e-7b5a-45e0-8095-b3dcce91ffc5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14d91f7a-6c5b-49c2-9407-5008ed602852', 'To let wild animals walk through', false, 'bdd2082e-7b5a-45e0-8095-b3dcce91ffc5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2b82e60-638b-4634-a233-44cf699bd7af', 'To plant vegetable gardens', false, 'bdd2082e-7b5a-45e0-8095-b3dcce91ffc5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f83e2d1-7499-46d1-aa82-01d17658a00d', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'How does throwing a damp, heavy blanket or sack over a small kitchen fire extinguish it immediately?', 'Fire blankets smother flames by oxygen starvation, dropping O₂ below the 16% threshold needed for combustion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb48def5-d819-41ed-8c44-46a503b2dd60', 'It cuts off the supply of atmospheric Oxygen from reaching the burning fuel, instantly smothering the flame', true, '4f83e2d1-7499-46d1-aa82-01d17658a00d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1a9f8bf-75a2-4b6d-aedd-6cf5e654ce65', 'It makes the fire hotter', false, '4f83e2d1-7499-46d1-aa82-01d17658a00d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44e45018-f448-4eb9-b63d-c036b068105e', 'It adds fuel to the fire', false, '4f83e2d1-7499-46d1-aa82-01d17658a00d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90bd447a-405c-4aa3-8188-31ad1553ddb7', 'It makes the fire disappear into the blanket', false, '4f83e2d1-7499-46d1-aa82-01d17658a00d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18093a32-fc00-48e9-9997-6e42236ca1b7', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'What is the poetic metaphor in describing a butterfly''s mouthparts as ''Drinking Straws'' in ''Meadow Surprises''?', 'The metaphor illuminates insect anatomy: the elongated tubular proboscis acts like an organic drinking straw siphoning nectar.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7fc40a2-3602-4327-a634-2ba92263e14c', 'It poetically visualizes the butterfly''s coiled tubular proboscis that unrolls to siphon sweet liquid nectar from flower chalices', true, '18093a32-fc00-48e9-9997-6e42236ca1b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('007898ca-dfd6-4321-b3ee-ed1e46ff3334', 'The butterfly carries plastic straws from a store', false, '18093a32-fc00-48e9-9997-6e42236ca1b7');
