INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27de49c1-3af8-46e7-b8d1-7099e8da3a45', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'What is the meaning of the word ''Smother'' in firefighting contexts?', '''Smother'' means suffocating or extinguishing combustion by cutting off atmospheric oxygen.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb64c0e3-47c3-4297-be8a-3ef50c64bb73', 'To extinguish a fire by depriving it of air and cutting off oxygen supply', true, '27de49c1-3af8-46e7-b8d1-7099e8da3a45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d8a1b1b-2a55-4ae4-a91b-c253ccda9388', 'To burn brightly', false, '27de49c1-3af8-46e7-b8d1-7099e8da3a45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b370174-a7cd-4161-a666-91dfd85418b7', 'To pour gasoline on fire', false, '27de49c1-3af8-46e7-b8d1-7099e8da3a45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0eb7b4b9-432b-47ae-9009-2d3a6adc42fc', 'To heat up metal', false, '27de49c1-3af8-46e7-b8d1-7099e8da3a45');
