INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3f2059b-a880-46d6-8bc8-763a6bda91c5', '''High-pressure water was sprayed onto the burning roof by the firefighters.''', true, '099f1cae-15e4-45c1-a4ea-abccacb1a812');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3984de1c-20c6-47b5-ab13-1ea87c50075d', '''The burning roof sprayed high-pressure water by firefighters.''', false, '099f1cae-15e4-45c1-a4ea-abccacb1a812');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c77fe38e-0333-4503-a7a0-db1a20054a73', '''Water had been spraying by the firefighters.''', false, '099f1cae-15e4-45c1-a4ea-abccacb1a812');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f4c2874-b83a-4455-8585-79481361a8f3', '''Firefighters were sprayed by the burning roof.''', false, '099f1cae-15e4-45c1-a4ea-abccacb1a812');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e28e7ffe-cc04-40c4-a15d-b74a936a57c1', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'What is the meaning of ''Airy parachutes'' in the description of a mature Dandelion flower?', '''Airy parachutes'' poeticizes the pappus parachute hairs of dandelion seeds designed for wind dispersal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('399c0e4b-c936-4972-824a-4ecff95507a9', 'The lightweight, feathery white pappus seed-heads that float effortlessly on air breezes like tiny parachutes', true, 'e28e7ffe-cc04-40c4-a15d-b74a936a57c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04952455-4df5-4d02-9426-820f36e0fc4d', 'Parachutes used by skydivers in a meadow', false, 'e28e7ffe-cc04-40c4-a15d-b74a936a57c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75dd3473-890c-4678-b63c-ea740cfb8327', 'Plastic toys dropped from planes', false, 'e28e7ffe-cc04-40c4-a15d-b74a936a57c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74db4742-8714-4ef5-95dd-cd2f809a30a0', 'Yellow petals that fall on ground', false, 'e28e7ffe-cc04-40c4-a15d-b74a936a57c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fa1fcea3-1cf2-4512-8e53-1ea4133d35bb', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Medium', 'What happens when you blow gently on a dandelion seed-head according to the poem?', 'Line from poem: ''Airy parachutes that flutter when you blow''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91b30a0a-ec0e-484d-86ae-932c88382580', 'The tiny parachute seeds detach and flutter away through the air', true, 'fa1fcea3-1cf2-4512-8e53-1ea4133d35bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('927b6f21-9f41-4c6e-aa0b-43f2d5e0c09a', 'The flower turns into a yellow rose', false, 'fa1fcea3-1cf2-4512-8e53-1ea4133d35bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2513183e-d5f6-4560-bdad-de9ccf3b321d', 'The flower disappears into water', false, 'fa1fcea3-1cf2-4512-8e53-1ea4133d35bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ade55497-4655-41fd-83a6-1aeb52f5e46f', 'The flower catches fire', false, 'fa1fcea3-1cf2-4512-8e53-1ea4133d35bb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('519f565c-7168-4c30-aabb-b6e0eef26340', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5ae7b3d-b1bc-40bf-9bd2-d0b9f9367400', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '519f565c-7168-4c30-aabb-b6e0eef26340');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4a50e59-67d3-4a4b-9035-146e274cedd8', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '519f565c-7168-4c30-aabb-b6e0eef26340');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d45b1a3a-1daf-4d72-9910-4d34b57d12fd', '(A) is true, but (R) is false.', false, '519f565c-7168-4c30-aabb-b6e0eef26340');
