INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f0395387-6c91-48ab-a79b-d0c1cf8321cb', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'Spot the IMPOSTER in the following methods of Firefighting and their scientific operational principles:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6861f7f7-34e6-4157-86a5-92c391e6cd3a', 'Method 1', false, 'f0395387-6c91-48ab-a79b-d0c1cf8321cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e39e0ada-42c5-4e8e-8fc5-8d5ee1698d07', 'Method 2', false, 'f0395387-6c91-48ab-a79b-d0c1cf8321cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c840374-7d58-478c-8429-861e45e4b28e', 'Method 3', false, 'f0395387-6c91-48ab-a79b-d0c1cf8321cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36608cd8-e178-48a9-9845-11e803e23d1f', 'Method 4 (Alcohol and Gasoline are HIGHLY INFLAMMABLE FUELS that will violently explode and feed the fire, NOT cool it)', true, 'f0395387-6c91-48ab-a79b-d0c1cf8321cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa23406e-4f13-4656-8a72-850f75be5fd8', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'Analyze the environmental aesthetics in Lois Brandt Phillips''s ''Meadow Surprises'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd95ca0f-5e72-4aa3-86f5-b8a5bfd6a7c2', 'Nature does not shout its beauty; discovering the rich biodiversity of meadows (micro-habitats, animal architecture, camouflage) requires gentle stillness, patient observation, and deep reverence', true, 'aa23406e-4f13-4656-8a72-850f75be5fd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5dee0ba5-4dc7-469c-9e65-b787b7378cac', 'Meadows are empty fields with nothing to see', false, 'aa23406e-4f13-4656-8a72-850f75be5fd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ff980cf-daa5-415c-896e-f8613390ec74', 'Children should run loudly to scare all animals away', false, 'aa23406e-4f13-4656-8a72-850f75be5fd8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e89820e-cef5-4f7d-84ff-58cf230b51f4', 'Meadows should be paved over with concrete', false, 'aa23406e-4f13-4656-8a72-850f75be5fd8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6af47d14-d611-451c-97a8-c7c745abe8ef', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'Match Column I (Fire Safety & Poetic Images) with Column II (Scientific & Literary Mechanisms):
(a) Fire Triangle               -> (i) The tripartite triad of Fuel, Oxygen, and Ignition Heat
(b) Flash Point                 -> (ii) The critical kindling temperature threshold initiating combustion
(c) Butterfly''s Drinking Straws -> (iii) Extended tubular proboscis harvesting floral nectar
(d) Dandelion Airy Parachutes   -> (iv) Anemochorous pappus seed adaptations for wind dispersal', 'Fire Triangle = fuel/O₂/heat; Flash point = ignition temp; Proboscis = drinking straw; Pappus = airy parachute.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b0af237-ee20-47bc-aeb0-dac8bfa1937a', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '6af47d14-d611-451c-97a8-c7c745abe8ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bb53ca9-7812-4891-8642-a9e6fb82622b', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '6af47d14-d611-451c-97a8-c7c745abe8ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('143426ce-8be0-452f-a786-5e4c9e5267ef', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '6af47d14-d611-451c-97a8-c7c745abe8ef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76d16f05-79fb-4505-837e-026a798b4980', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '6af47d14-d611-451c-97a8-c7c745abe8ef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('71f736cf-7d60-43b8-a14d-94b97204a3c0', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'Read the statements regarding historical firefighting:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ec34a4e-ff26-4672-8e88-7c1fa36439f2', 'Statements 1 and 2 only', true, '71f736cf-7d60-43b8-a14d-94b97204a3c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3aa12b1-21ee-4a8a-99fe-2c6604918ccd', 'Statements 2 and 3 only', false, '71f736cf-7d60-43b8-a14d-94b97204a3c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88195e67-05a3-4b33-8987-2c7e4bfc1bcd', 'Statements 1 and 3 only', false, '71f736cf-7d60-43b8-a14d-94b97204a3c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af85be4d-20bd-4faa-844b-1f618bb7e56e', 'All Statements 1, 2, and 3', false, '71f736cf-7d60-43b8-a14d-94b97204a3c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e77c0c9-ee4e-4c01-8f1d-09ef4ce441c1', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'Identify the grammatical role of the underlined clause in: ''When a fire breaks out, **firefighters immediately rush to the scene**.''', '''Firefighters immediately rush to the scene'' is the independent principal clause preceded by the temporal subordinate clause.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74af9efe-c807-41af-b25f-2cb067a6c66c', 'Main (Independent) Clause expressing the primary action', true, '5e77c0c9-ee4e-4c01-8f1d-09ef4ce441c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f89b349-34ae-4f33-bf8a-b25f028d45a7', 'Dependent Adverb Clause of Time', false, '5e77c0c9-ee4e-4c01-8f1d-09ef4ce441c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40efb1c2-51d0-476a-a20f-e283bcc33e9f', 'Noun Clause in apposition', false, '5e77c0c9-ee4e-4c01-8f1d-09ef4ce441c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad3c0012-2631-4d79-ad40-49e9f9ae95f2', 'Relative Clause', false, '5e77c0c9-ee4e-4c01-8f1d-09ef4ce441c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fb5854ea-031f-4ffe-afd6-43c9902bc34a', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'Why does spraying water on a normal wood or paper fire put it out effectively?', 'Thermodynamics of water dousing: massive enthalpy absorption lowers temperature below flash point, while expanding steam blankets oxygen.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd97881c-9ea8-4af2-8962-04dc6f40c145', 'Water absorbs vast amounts of thermal heat energy (high specific heat and latent heat of vaporization), dropping the fuel''s temperature below its kindling flash point, while steam blocks surrounding oxygen', true, 'fb5854ea-031f-4ffe-afd6-43c9902bc34a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f49ab9f7-afc3-403f-87e1-3178ddadb8f9', 'Water turns the wood into metal', false, 'fb5854ea-031f-4ffe-afd6-43c9902bc34a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64a5c721-f257-4013-9698-f59277aa3bf5', 'Water produces freezing ice instantly', false, 'fb5854ea-031f-4ffe-afd6-43c9902bc34a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1d0c82f-36be-4311-91ee-c960a52598b7', 'Water creates chemical poison for fire', false, 'fb5854ea-031f-4ffe-afd6-43c9902bc34a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36d5eb30-941b-4db0-817f-3b8e52233867', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'In ''Meadow Surprises'', what camouflage survival mechanism of the rabbit is highlighted in the lines:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c681f99-4905-4425-9ec3-205d30fbeddd', 'Crypsis / Freezing behavior: prey animals blend motionless with meadow background to evade visual predator detection until forced into explosive flight', true, '36d5eb30-941b-4db0-817f-3b8e52233867');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8700c05-461a-4f25-85be-f268e2598338', 'Rabbits change their skin color like chameleons', false, '36d5eb30-941b-4db0-817f-3b8e52233867');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('108ddcbc-2328-4862-9650-36322f78cb9b', 'Rabbits become invisible with magic', false, '36d5eb30-941b-4db0-817f-3b8e52233867');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09b9417d-d7be-41a3-818e-8d8c969e7995', 'Rabbits dig holes with their ears', false, '36d5eb30-941b-4db0-817f-3b8e52233867');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0cb4c4b5-f79d-4509-8a71-e3cf24203371', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'What is the ecological significance of the ''Ant''s amazing mound'' mentioned in the poem?', 'Formicary ant mounds are sophisticated subterranean bio-architectural complexes regulating ventilation, brood humidity, and colony defense.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c14dd5ba-1737-4e17-8dcc-89e7b4ddac14', 'It represents a marvel of social insect architectural engineering, featuring complex subterranean galleries for fungal cultivation, brood chambers, and thermal regulation', true, '0cb4c4b5-f79d-4509-8a71-e3cf24203371');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc70ffb1-5fcc-4f50-b12b-2f563626f697', 'It is a pile of trash left by hikers', false, '0cb4c4b5-f79d-4509-8a71-e3cf24203371');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53afe179-ddfb-4a39-ad78-d401873acb9d', 'It is a natural rock formation', false, '0cb4c4b5-f79d-4509-8a71-e3cf24203371');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03eca9b0-4ad3-4280-bbbe-a91da66e6ee0', 'It is built by meadow birds', false, '0cb4c4b5-f79d-4509-8a71-e3cf24203371');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb6adc98-423a-40cf-acc3-58b89c8c7b13', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'Which of the following sentences correctly utilizes the Conditional Clause (Type 1) for fire safety?', 'Standard first conditional syntax: If + simple present (''see''), main clause modal + base verb (''should report'').', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59348b37-2ddb-499f-aea7-db9d4da09452', '"If you see a fire hazard in your building, you should immediately report it to the fire officer."', true, 'cb6adc98-423a-40cf-acc3-58b89c8c7b13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92fd84ea-d2b4-4046-a3d8-0ea5481f682f', '"If you saw fire, you will run."', false, 'cb6adc98-423a-40cf-acc3-58b89c8c7b13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d5968b4-42f8-4dbd-a56c-2ef281dae6c5', '"If fire is burning, water had been sprayed."', false, 'cb6adc98-423a-40cf-acc3-58b89c8c7b13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d71cd42-5baf-4760-9d0f-67a7b894345f', '"If fuel burns, smoke was rising."', false, 'cb6adc98-423a-40cf-acc3-58b89c8c7b13');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f265be41-545a-46b4-a375-d0c5e0948e5c', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'What sensory contrast is created between the prose ''Fire: Friend and Foe'' and the poem ''Meadow Surprises''?', 'Chapter 8 creates thematic balance: industrial thermodynamics and civic safety paired with contemplative botanical and ecological wonder.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('341d609b-bbc8-48df-80d9-d5518a118e69', 'The prose explores the fierce, energetic thermodynamic power of combustion and human technology, while the poem invites gentle, contemplative immersion in the quiet micro-wonders of living nature', true, 'f265be41-545a-46b4-a375-d0c5e0948e5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('430a3119-3baa-45c5-95bf-264c8e956aed', 'Both texts describe destructive earthquakes', false, 'f265be41-545a-46b4-a375-d0c5e0948e5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58f0712f-e456-4646-b1c2-729e9243ca38', 'Both texts are mathematical formulas', false, 'f265be41-545a-46b4-a375-d0c5e0948e5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1bd870d-8194-43c9-b80b-3db81c04bb31', 'There is no contrast', false, 'f265be41-545a-46b4-a375-d0c5e0948e5c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c4bee22-656d-47f3-a24e-b99b4b596077', 'Class 7', 'English', 'Chapter 8: Fire: Friend and Foe & Meadow Surprises', 'Hard', 'What overarching humanist education unites Chapter 8 of NCERT Class 7 English?', 'Chapter 8 bridges physical science literacy, civic safety protocols, and ecological sensitivity to the natural world.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9ee91f14-c40f-4bb8-a7f6-ebd1ad04ba26', 'Scientific literacy, safety consciousness, and environmental mindfulness—equipping young minds to master dangerous physical forces responsibly while nurturing gentle curiosity for nature''s delicate ecosystems', true, '9c4bee22-656d-47f3-a24e-b99b4b596077');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cbd2b03-5639-4070-b132-4485d7d36b1f', 'That humans should never explore meadows', false, '9c4bee22-656d-47f3-a24e-b99b4b596077');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41602ff5-ce78-4223-be68-35b510574641', 'That fire should never be used for any purpose', false, '9c4bee22-656d-47f3-a24e-b99b4b596077');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c89034e-1319-4248-a879-18bd3594ea31', 'That animals should be kept in cages', false, '9c4bee22-656d-47f3-a24e-b99b4b596077');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad6778b4-f50e-441c-8ce4-f62aa76a278c', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Easy', 'Which is the HIGHEST mountain peak in India (located in the Karakoram range in Ladakh / Gilgit-Baltistan), standing at 8,611 metres?', 'K2 (8,611 m) is the highest peak in India and second highest on Earth; Kanchenjunga (8,586 m) in Sikkim is the highest peak entirely in undisputed Indian territory.', NOW()) ON CONFLICT DO NOTHING;
