INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d655ae07-dab3-41b9-905c-413c7b052c4b', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'Which is the HIGHEST peak in the Western Ghats (and in the entire Peninsular South India), located in the Anamalai Hills of Kerala at 2,695 metres?', 'Anamudi (''Elephant''s head'', 2,695 m) in Kerala is the undisputed highest peak in South India and the Western Ghats.', NOW()) ON CONFLICT DO NOTHING;
