INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27502c05-50c4-4fd6-aa3b-c17af9f0c249', 'Vindhyas, Satpuras, and Aravallis', false, '9486b0f3-2f36-45dc-9877-72d4d7b93c65');
