INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7bfa92af-355e-417e-aac6-155b5c730a16', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'Which two major Peninsular Indian rivers flow WESTWARDS through fault-formed Rift Valleys and drain into the Arabian Sea without forming deltas?', 'The Narmada (in rift between Vindhyas and Satpuras) and Tapi flow westwards into the Gulf of Khambhat, creating estuaries rather than deltas.', NOW()) ON CONFLICT DO NOTHING;
