INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('207e4042-e264-4976-b587-da200e1b45c8', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'Which is the LARGEST coastal brackish water lagoon lake in India (and second largest in the world), located in Odisha?', 'Chilika Lake in Odisha is Asia''s largest brackish lagoon, celebrated for wintering migratory waterfowl and Irrawaddy dolphins.', NOW()) ON CONFLICT DO NOTHING;
