INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f57ee454-8aa0-4f86-8f51-63edb25f7f7d', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'What is the unique ''Floating National Park'' in the world (Keibul Lamjao National Park) situated on Loktak Lake in Manipur, home to the endangered Sangai brow-antlered deer?', 'Keibul Lamjao on Loktak Lake is the world''s only floating national park, supported by floating biomass mats known as Phumdis.', NOW()) ON CONFLICT DO NOTHING;
