INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('85f52ea2-55d9-4a1b-8981-c96c4c5085d6', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'What are the two major seasonal branches of the advancing South-West Summer Monsoon that brings over 75% of India''s annual rainfall between June and September?', 'The SW monsoon splits into the Arabian Sea branch (striking the Western Ghats) and the Bay of Bengal branch (striking the Northeast and Gangetic plains).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('961ab152-fcca-4fb0-8d76-be09332fb116', 'The Arabian Sea Branch and the Bay of Bengal Branch', true, '85f52ea2-55d9-4a1b-8981-c96c4c5085d6');
