INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3229d1da-a51f-4c83-8e78-efdf026d694d', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'Which Indian coastal region receives the majority of its annual rainfall during the RETREATING North-East Winter Monsoon (October–November)?', 'Retreating NE monsoon winds pick up moisture over the Bay of Bengal and deposit heavy winter precipitation along the Coromandel coast.', NOW()) ON CONFLICT DO NOTHING;
