INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('64960734-9c1b-4282-bcff-46da39f15c03', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'What are the four physical soil zones of the Northern Plains from north to south along the Himalayan foothills?', 'Northern plains geomorphology: Bhabar (porous gravels) → Terai (swampy re-emergence) → Bhangar (older alluvium) → Khadar (annual renewed silt).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e17641a0-3835-49b8-a1f6-2ec8c111bcd8', 'Bhabar (pebble zone where streams disappear) -> Terai (marshy wet jungle) -> Bhangar (older alluvial terrace) -> Khadar (new fertile flood plain)', true, '64960734-9c1b-4282-bcff-46da39f15c03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33be2b62-23cd-4e1c-b57e-5ffdd65ae85f', 'Desert -> Forest -> Sand -> Mud', false, '64960734-9c1b-4282-bcff-46da39f15c03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cba1386e-60be-49e8-9f55-bb8f303c798c', 'Black soil -> Red soil -> Laterite -> Peaty', false, '64960734-9c1b-4282-bcff-46da39f15c03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdb0b776-b8ff-4258-8cbd-51bc2b7a0a1d', 'Mountain -> River -> Ocean -> Delta', false, '64960734-9c1b-4282-bcff-46da39f15c03');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('01ba4b0b-f49d-4381-af55-7bb5ccced2f7', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'Which fertile soil formed from the weathering of ancient Deccan lava flows (basalt) is ideal for growing COTTON in Maharashtra and Gujarat?', 'Regur (Black Soil) is rich in clay minerals, highly moisture-retentive, and renowned for cotton agriculture.', NOW()) ON CONFLICT DO NOTHING;
