INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cea7309-551f-4f4f-a58a-7a6f533adf2e', 'Red Soil', false, '01ba4b0b-f49d-4381-af55-7bb5ccced2f7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6df77b87-8f39-4a03-8ebc-d1f603472b3d', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Medium', 'Where do the Western Ghats and the Eastern Ghats mountain ranges converge in South India?', 'The Western and Eastern Ghats meet at the Nilgiri orographic node in Tamil Nadu/Karnataka/Kerala.', NOW()) ON CONFLICT DO NOTHING;
