INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4dbb4cae-f230-4ae1-a449-a436353086b5', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'What are the ''Western Disturbances'' that bring crucial winter rainfall and snowfall to Northwest India (Punjab, Haryana, Jammu & Kashmir, Himachal)?', 'Mediterranean extratropical depressions transported via westerly jet streams sustain the vital winter Rabi wheat harvest.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b02a32c6-7189-48ba-844d-da5f7ccc3300', 'Extratropical cyclonic low-pressure storms originating over the Mediterranean Sea, steered into northwest India by the Subtropical Westerly Jet Stream', true, '4dbb4cae-f230-4ae1-a449-a436353086b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acaeabdf-d017-4060-83d7-233fa49e2c6d', 'Dust storms blowing from the Thar desert', false, '4dbb4cae-f230-4ae1-a449-a436353086b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae338478-6adf-4216-842a-823b3b498ef2', 'Cyclones rising from the Indian Ocean', false, '4dbb4cae-f230-4ae1-a449-a436353086b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecd4a687-1178-425d-b1b6-ef09a84b08e1', 'Winds blowing from the South Pole', false, '4dbb4cae-f230-4ae1-a449-a436353086b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f331b66-0c14-47f1-bb61-28aa4dbe4a9d', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'Match Column I (Indian Biosphere Reserves / National Parks) with Column II (Keystone Flora/Fauna & Geographic Features):
(a) Gulf of Mannar       -> (i) Marine Biosphere Reserve famous for Dugongs (Sea Cows) & coral reefs
(b) Sundarbans           -> (ii) Mangrove ecosystem, Royal Bengal Tiger, Sundari trees & estuarine crocodiles
(c) Great Rann of Kutch  -> (iii) White salt desert sanctuary of the Indian Wild Ass (Khur)
(d) Hemis National Park  -> (iv) High-altitude Ladakh park, global capital of the Snow Leopard', 'Gulf of Mannar = Dugongs; Sundarbans = Mangrove tigers; Rann of Kutch = Wild Ass; Hemis = Snow Leopards.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5911b495-43f1-4ae5-a2ed-bf22b5014e7d', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '8f331b66-0c14-47f1-bb61-28aa4dbe4a9d');
