INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da899009-47dc-4954-b6b8-a3fe2c8e6b12', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'What is the strategic and ecological significance of the ''Siliguri Corridor'' (often called the ''Chicken''s Neck'')?', 'The Siliguri Corridor is the critical geopolitical chokepoint linking mainland India to the eight northeastern sister states.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18913e40-a1e8-4ab9-b7e7-63b04d2e1488', 'A narrow strip of land in West Bengal (~22 km wide at its narrowest) connecting the entire eight states of Northeast India with the rest of mainland India', true, 'da899009-47dc-4954-b6b8-a3fe2c8e6b12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3020ac72-54c8-4394-88c8-68dfa1b1e18b', 'A bridge between India and Sri Lanka', false, 'da899009-47dc-4954-b6b8-a3fe2c8e6b12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b37f4ca-aece-43d5-a5be-6a6eeecce8fb', 'A mountain pass to Afghanistan', false, 'da899009-47dc-4954-b6b8-a3fe2c8e6b12');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e81b53be-163d-4545-bc65-eeda733b9965', 'A canal through the Thar desert', false, 'da899009-47dc-4954-b6b8-a3fe2c8e6b12');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e58eb66-6352-4068-b2a4-ad08261cd85d', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'Why is the Chota Nagpur Plateau in eastern India celebrated as the ''Ruhr of India''?', 'Like Germany''s Ruhr basin, the Chota Nagpur plateau is India''s mineral heartland, powering the nation''s steel and heavy manufacturing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c7eb3a9-377c-44ad-a133-50897626f282', 'It contains the richest concentration of metallic and mineral wealth in India, including massive reserves of Iron Ore, Coal (Jharia, Bokaro), Mica, Bauxite, and Uranium', true, '2e58eb66-6352-4068-b2a4-ad08261cd85d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e45384cf-53df-4447-a7d0-4cd37316ffaf', 'Because it has the most rivers', false, '2e58eb66-6352-4068-b2a4-ad08261cd85d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('948422b9-660a-4028-90cd-5aacaae76638', 'Because it is covered in snow all year', false, '2e58eb66-6352-4068-b2a4-ad08261cd85d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95fb3dc2-e29e-492f-b5b0-97a36a247ac0', 'Because it produces gold only', false, '2e58eb66-6352-4068-b2a4-ad08261cd85d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d33f7cbf-1f4d-4dd7-858b-e7c429c9bcb0', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'Consider four major multi-purpose river valley projects in India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3af1b653-8d86-4262-88cc-03aa41f7d873', 'Hydroelectric power generation, extensive canal irrigation networks for agriculture, flood mitigation, and industrial drinking water security', true, 'd33f7cbf-1f4d-4dd7-858b-e7c429c9bcb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d3da40a-0647-4541-8b04-c6a8696e87c4', 'They stop all rivers from flowing', false, 'd33f7cbf-1f4d-4dd7-858b-e7c429c9bcb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40b8628a-3a77-454a-b34c-8f0b1b1e328e', 'They are built only for boating tourist sports', false, 'd33f7cbf-1f4d-4dd7-858b-e7c429c9bcb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('182ca21e-68ae-4b9b-8374-f0f6ae2841cf', 'They turn fresh water into salt water', false, 'd33f7cbf-1f4d-4dd7-858b-e7c429c9bcb0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae427e47-7b5f-4079-94e8-602f16d98967', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'What is the ''Tropical Evergreen Forest'' biome in India (found in the Western Ghats, Northeast India, and Andaman & Nicobar)?', 'Tropical evergreen rainforests exhibit complex vertical stratification, dense multi-tiered canopies, and immense biodiversity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a149398-b2d8-4d51-bd2f-2fe260e863d4', 'Dense, multi-layered rain forests receiving >200 cm rainfall with trees (Rosewood, Mahogany, Ebony) that do not shed leaves simultaneously, remaining green throughout the year', true, 'ae427e47-7b5f-4079-94e8-602f16d98967');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc674b29-89e8-491e-8545-bdc26a74fbc3', 'Forests with thorny bushes and no leaves', false, 'ae427e47-7b5f-4079-94e8-602f16d98967');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9cbae94-a71a-4cd4-9f96-7adcd62b0097', 'Forests that only grow in snow', false, 'ae427e47-7b5f-4079-94e8-602f16d98967');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c67d4dcc-dbcb-4f49-af1c-9f938ad7b515', 'Forests of pure pine needles', false, 'ae427e47-7b5f-4079-94e8-602f16d98967');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('626b97f5-29d2-4f25-8d73-8ced78af6843', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'What is the ''Indira Point'' in the Nicobar Islands?', 'Indira Point on Great Nicobar (submerged partially in the 2004 tsunami) marks India''s southernmost geographical point.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d0257e0-5086-4e2c-ba3b-88a6c15fbb1d', 'The southernmost geographic point of the sovereign territory of the Republic of India (located at 6° 45'' N on Great Nicobar Island)', true, '626b97f5-29d2-4f25-8d73-8ced78af6843');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('590bc65a-937f-4e95-82bf-3d6a58a44b9c', 'The northernmost point in Kashmir', false, '626b97f5-29d2-4f25-8d73-8ced78af6843');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62c2c423-6a6f-4e11-a5fd-1416c136a02d', 'The highest peak in Rajasthan', false, '626b97f5-29d2-4f25-8d73-8ced78af6843');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c23f6c5a-5888-46e0-86df-c1e2cd0f67d5', 'The easternmost point in Arunachal Pradesh', false, '626b97f5-29d2-4f25-8d73-8ced78af6843');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fff56d1f-77fe-4dd3-9fb6-0a491e1f68d4', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'Why is the Western Ghats recognized by UNESCO as one of the world''s eight ''Hottest Hotspots'' of Biological Diversity?', 'The Western Ghats harbor immense floral/faunal endemism (Lion-tailed macaque, Nilgiri tahr, Malabar gliders) under acute conservation vulnerability.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('748dff0c-2062-4f5d-94dd-9149bb0e74a8', 'It harbors thousands of endemic species of flora, fauna, birds, amphibians, and reptiles found nowhere else on Earth, amidst high anthropogenic habitat pressure', true, 'fff56d1f-77fe-4dd3-9fb6-0a491e1f68d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8876674f-c875-4e86-9861-db534ce31575', 'Because it is the hottest desert on Earth', false, 'fff56d1f-77fe-4dd3-9fb6-0a491e1f68d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c1257f2-eb69-489f-b5d1-12c6ac8f89be', 'Because it has no trees', false, 'fff56d1f-77fe-4dd3-9fb6-0a491e1f68d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78fc9575-ec65-4ee8-af66-0b3030fcda85', 'Because it has active gold mines', false, 'fff56d1f-77fe-4dd3-9fb6-0a491e1f68d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a36f8d6-2dca-4cbd-88e1-c82631f331c7', 'Class 7', 'GK', 'Chapter 8: Indian Geography, Physical Features, Climate & Resources', 'Hard', 'What overarching geographic reality defines the Indian Subcontinent in Chapter 8 of General Knowledge?', 'Chapter 8 synthesizes India''s diverse physiography, drainage basins, tropical monsoon meteorology, and precious mineral-ecological patrimony.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('248ef95b-8de0-4ed4-866a-ee0f37c12754', 'An extraordinary physical mosaic uniting towering Himalayan snow ranges, fertile riverine alluvial plains, ancient mineral-rich plateaus, sun-drenched coastlines, and monsoon rhythms that sustain India''s immense biological and civilizational vitality', true, '7a36f8d6-2dca-4cbd-88e1-c82631f331c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('634189c3-b2f6-49c4-b313-32b13b98f335', 'A uniform desert with no physical variation', false, '7a36f8d6-2dca-4cbd-88e1-c82631f331c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2126bdc-821c-4645-a37f-3599b62783b4', 'An island completely cut off from the rest of the world', false, '7a36f8d6-2dca-4cbd-88e1-c82631f331c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27940d83-ba75-49aa-860a-3bb4c0f6e007', 'A land without any rivers or forests', false, '7a36f8d6-2dca-4cbd-88e1-c82631f331c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0da1bc7d-5608-4aec-9930-d52f30ddda95', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Easy', 'In medieval South India (7th to 9th centuries), who were the poet-saints who led the vibrant Bhakti movement devoted to LORD SHIVA?', 'The Nayanars were 63 Shaivite Bhakti saints belonging to diverse caste backgrounds (potters, untouchables, peasants, kings).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a9aff17-5648-4ce9-aa6b-08db09b6b8a4', 'The Nayanars (63 Nayanars including Appar, Sambandar, Sundarar)', true, '0da1bc7d-5608-4aec-9930-d52f30ddda95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95e52c36-2995-458c-93d7-99f55f3de3ca', 'The Alvars', false, '0da1bc7d-5608-4aec-9930-d52f30ddda95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eeb8861b-77bb-4965-8381-114344180ac9', 'The Sufis', false, '0da1bc7d-5608-4aec-9930-d52f30ddda95');
