INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a1f66955-1e9d-4953-9eff-47b3fc5ca039', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Easy', 'Who were the South Indian Bhakti poet-saints who immersed themselves in passionate devotion to LORD VISHNU?', 'The 12 Alvars were Vaishnavite mystic saints whose devotional Tamil songs were compiled in the sacred Divya Prabandham.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ad2edb6-cb01-4655-a82e-00ec876925d0', 'The Alvars (12 Alvars including Periyalvar, Andal, Nammalvar)', true, 'a1f66955-1e9d-4953-9eff-47b3fc5ca039');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bef385fa-ca75-48c5-8350-553dd26a0cba', 'The Nayanars', false, 'a1f66955-1e9d-4953-9eff-47b3fc5ca039');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b20530e-1cb3-46b5-99c9-f1d9a96f21b1', 'The Virashaivas', false, 'a1f66955-1e9d-4953-9eff-47b3fc5ca039');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a12bc707-a3b1-409f-acd3-526e6421f1e7', 'The Yogis', false, 'a1f66955-1e9d-4953-9eff-47b3fc5ca039');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f7825724-57ba-4a78-9e45-2eb9f266df83', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Easy', 'Who was the only celebrated WOMAN Alvar saint among the twelve Alvars, known for her deeply emotional devotional poetry to Lord Krishna (Ranganatha)?', 'Andal (daughter of Periyalvar) is the revered female Alvar saint who composed the Thiruppavai in ecstatic devotion to Lord Vishnu.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23c08148-c030-4b6d-b527-b7acfb535158', 'Andal (Kodhai)', true, 'f7825724-57ba-4a78-9e45-2eb9f266df83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10265c85-3866-49ba-8ecf-bdaa760ec0dc', 'Akkamahadevi', false, 'f7825724-57ba-4a78-9e45-2eb9f266df83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85776453-9dfe-4e1a-b481-480ee04d4217', 'Mirabai', false, 'f7825724-57ba-4a78-9e45-2eb9f266df83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('183f2562-2b71-4ef5-a8cc-447e3e5fef19', 'Muktabai', false, 'f7825724-57ba-4a78-9e45-2eb9f266df83');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49c053cc-f0d6-4a40-8511-b3fbcbabfa95', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Easy', 'Which 12th-century socio-religious movement in Karnataka was initiated by Basavanna, Allama Prabhu, and Akkamahadevi, advocating equality of all humans and rejecting caste discrimination and idol worship?', 'Basavanna and his companions founded the Virashaiva movement, rejecting ritual orthodoxy, caste hierarchies, and the mistreatment of women.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a02b9476-1249-420c-b0bd-15bfc62ec257', 'The Virashaiva (Lingayat) Movement', true, '49c053cc-f0d6-4a40-8511-b3fbcbabfa95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4895428e-63a4-4c43-ab3a-c81e89df3a27', 'The Chisti Movement', false, '49c053cc-f0d6-4a40-8511-b3fbcbabfa95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89b5a7a3-2cb8-478f-b086-6c8149c2110c', 'The Nathpanthi Movement', false, '49c053cc-f0d6-4a40-8511-b3fbcbabfa95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de7a652d-d2df-4544-a876-beb77586cf94', 'The Alvar Movement', false, '49c053cc-f0d6-4a40-8511-b3fbcbabfa95');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d1778a70-7994-4024-a528-55be2e2a6e15', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Easy', 'Which local temple deity at Pandharpur in Maharashtra became the supreme focus of the Varkari Bhakti tradition led by Jnaneshwar, Namdev, Eknath, and Tukaram?', 'The Varkari sect centered on the worship of Lord Vitthala (Vithoba) in the grand temple at Pandharpur on the Bhima river.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bbdbc2a-1b00-4329-8f80-e5c9503992e1', 'Lord Vitthala (a manifestation of Lord Vishnu / Krishna)', true, 'd1778a70-7994-4024-a528-55be2e2a6e15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24ff5e89-86c6-45be-a622-77d4d6ab6e66', 'Lord Shiva', false, 'd1778a70-7994-4024-a528-55be2e2a6e15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b8a648b-8f4a-4e3f-82bf-2c06afcb40af', 'Lord Murugan', false, 'd1778a70-7994-4024-a528-55be2e2a6e15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc524a27-ec8d-4537-b8df-9274d1778b62', 'Lord Ganesha', false, 'd1778a70-7994-4024-a528-55be2e2a6e15');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('43fc8583-2bf4-4881-a9eb-e4baea2c5b91', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Easy', 'Who was the 15th-century mystic weaver-poet of Varanasi who expressed his passionate devotion to formless God (Nirguna Bhakti) through rhyming couplets called Sakhis and Pads?', 'Sant Kabir preached formless monotheism, fiercely mocking external religious rituals, hypocrisy, and caste prejudices in Hinduism and Islam.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e0ec304-0ed6-4c96-95e0-00316c33efaa', 'Kabir Das (Sant Kabir)', true, '43fc8583-2bf4-4881-a9eb-e4baea2c5b91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ebf18de-fdfc-4fc5-9a47-d815a97d574c', 'Tulsidas', false, '43fc8583-2bf4-4881-a9eb-e4baea2c5b91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea398885-3414-40f5-9bdc-d9cce6da74bd', 'Surdas', false, '43fc8583-2bf4-4881-a9eb-e4baea2c5b91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae0a14bc-6177-4896-a10d-dc1701a05e3d', 'Ramananda', false, '43fc8583-2bf4-4881-a9eb-e4baea2c5b91');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('001fadd7-26fb-4e2a-a3df-80497603fb62', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Easy', 'Who was the founder of SIKHISM, born at Talwandi (Nankana Sahib in Pakistan) in 1469, who emphasized devotion to One Formless Creator (Ik Onkar) and set up the Langar community kitchen?', 'Guru Nanak Dev Ji founded Sikhism, established the sacred congregation (Dharamsal/Sangat), and instituted the egalitarian community kitchen (Langar).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('297f6f9d-5ebb-4f4c-aa9f-77ef704b731e', 'Guru Nanak Dev Ji', true, '001fadd7-26fb-4e2a-a3df-80497603fb62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73ad21bd-b45e-440a-be7d-49942e999bea', 'Guru Gobind Singh Ji', false, '001fadd7-26fb-4e2a-a3df-80497603fb62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ddb3b21-f6bc-415f-a48c-c832c281f08f', 'Guru Arjan Dev Ji', false, '001fadd7-26fb-4e2a-a3df-80497603fb62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbef4069-a595-481f-ad34-f2ad1147ea78', 'Guru Tegh Bahadur Ji', false, '001fadd7-26fb-4e2a-a3df-80497603fb62');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('29af3228-4028-47ce-b730-38e5e9c291cc', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Easy', 'Who was the 5th Sikh Guru who compiled the holy hymns of Guru Nanak and other Bhakti and Sufi saints (Kabir, Baba Farid, Namdev) into the Adi Granth in 1604?', 'Guru Arjan Dev Ji compiled the Adi Granth in 1604 at Amritsar, which was later consecrated as the eternal Guru Granth Sahib by Guru Gobind Singh in 1708.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f26c5fa-2520-4415-8c35-b9350e66cc0a', 'Guru Arjan Dev Ji', true, '29af3228-4028-47ce-b730-38e5e9c291cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1681a3fe-3e67-4a15-80ed-7a25b59117e0', 'Guru Nanak Dev Ji', false, '29af3228-4028-47ce-b730-38e5e9c291cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c34b827b-df0d-47df-993a-bc5afc0fef06', 'Guru Angad Dev Ji', false, '29af3228-4028-47ce-b730-38e5e9c291cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef4f27df-3a5a-44c8-b8c4-d80bbaf8f672', 'Guru Gobind Singh Ji', false, '29af3228-4028-47ce-b730-38e5e9c291cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('08fd41a2-8d47-4ee3-a871-b78c74fb69a8', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Easy', 'Who was the Rajput princess of Mewar who rejected royal luxury and became an ardent, fearless disciple of the saint Ravidas, composing passionate devotional Bhajans to Lord Krishna (Giridhar Gopal)?', 'Mirabai defied royal patriarchal conventions, dedicating her life to pure Saguna Krishna devotion and egalitarian saintly fellowship.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08248092-2e17-40e9-a4a1-bde18a7aaaec', 'Mirabai', true, '08fd41a2-8d47-4ee3-a871-b78c74fb69a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39cc1442-23d3-45d6-81e9-489a7fb6c3e3', 'Rani Padmini', false, '08fd41a2-8d47-4ee3-a871-b78c74fb69a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34dbf8f1-172e-41d5-b557-35abbadbf26f', 'Rani Durgavati', false, '08fd41a2-8d47-4ee3-a871-b78c74fb69a8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ae6806e-44a0-4361-86ab-5fff4f8f0590', 'Sakkubai', false, '08fd41a2-8d47-4ee3-a871-b78c74fb69a8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e2bb1e90-96fa-4888-8830-15eb81088756', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Easy', 'Who composed the monumental epic ''Ramcharitmanas'' in the Awadhi dialect of Hindi, portraying Lord Rama as the supreme embodiment of compassion and devotion?', 'Sant Tulsidas authored the beloved Ramcharitmanas in vernacular Awadhi, making Rama''s life accessible to millions across North India.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3830d97d-1044-4406-831c-dde6eda8dcad', 'Sant Tulsidas', true, 'e2bb1e90-96fa-4888-8830-15eb81088756');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1f70aa3-3298-428f-81a3-11ef346540d9', 'Surdas', false, 'e2bb1e90-96fa-4888-8830-15eb81088756');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a65ed2b3-d4f1-4a4e-8dfd-5f577cfc13c9', 'Kabir', false, 'e2bb1e90-96fa-4888-8830-15eb81088756');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b89804d9-b462-447b-9993-d29bb01e586a', 'Valmiki', false, 'e2bb1e90-96fa-4888-8830-15eb81088756');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('520c1c40-ef7a-45d1-a60c-da165ccf925f', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Easy', 'Which revered Sufi saint of the Chishti order made AJMER in Rajasthan his spiritual hospice, drawing millions of pilgrims to his sacred Dargah?', 'Khwaja Muinuddin Chishti (1142–1236) established the Chishti silsila in Ajmer, preaching universal love, tolerance, and service to the destitute.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c2fc82c-4625-4df4-9ae6-0d0995336004', 'Khwaja Muinuddin Chishti (Gharib Nawaz)', true, '520c1c40-ef7a-45d1-a60c-da165ccf925f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c661cbd0-787a-4860-a959-6f99965a018d', 'Qutbuddin Bakhtiyar Kaki', false, '520c1c40-ef7a-45d1-a60c-da165ccf925f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cf0f62a-543b-4286-911f-9697b5e7a9bb', 'Baba Farid', false, '520c1c40-ef7a-45d1-a60c-da165ccf925f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b1b161c-bca6-4f5b-bcbd-4b1fb3111f95', 'Hazrat Nizamuddin Auliya', false, '520c1c40-ef7a-45d1-a60c-da165ccf925f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('761eec68-e52d-459c-8738-29500c383e78', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Easy', 'Which 15th-century saint-reformer introduced the ''Ekasarana Dharma'' (devotion to One Supreme Lord Krishna) in Assam, pioneering devotional music (Borgeet) and community prayer halls (Namghars)?', 'Srimanta Sankaradeva founded the Neo-Vaishnavite movement in Assam, establishing Satras and village Namghars (prayer houses).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('277a8b1e-7c31-4fd6-a167-6617d14a403b', 'Srimanta Sankaradeva', true, '761eec68-e52d-459c-8738-29500c383e78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb9aa418-8b85-4738-a446-2bf2881ba34f', 'Chaitanya Mahaprabhu', false, '761eec68-e52d-459c-8738-29500c383e78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7a1f136-e22b-4f18-ba5f-d0abdf90a825', 'Ramananda', false, '761eec68-e52d-459c-8738-29500c383e78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('636fca59-fc87-4127-be76-b9a1b1c168ea', 'Tukaram', false, '761eec68-e52d-459c-8738-29500c383e78');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c60fee3b-69c8-4ba2-8b2d-cabdc3caac7d', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What was Shankara''s philosophical doctrine of ''ADVAITA'' (Non-dualism) propounded in the 8th century in Kerala?', 'Adi Shankaracharya preached Advaita: absolute non-dual monism where Brahman alone is real, the empirical world is Maya, and Atman is Brahman.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31d7020d-c64b-41aa-aa06-06f32c1a2978', 'The fundamental oneness and identity of the individual soul (Atman) with the ultimate Supreme Reality (Brahman) ; the world is Maya (illusion) and true liberation comes through knowledge (Jnana)', true, 'c60fee3b-69c8-4ba2-8b2d-cabdc3caac7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c04b1ff-6ce4-45f6-9ea8-7a1be19e8cb2', 'That there are thousands of separate supreme gods', false, 'c60fee3b-69c8-4ba2-8b2d-cabdc3caac7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cabdd6d-bf23-4141-a6ee-e309f00806c6', 'That the world is made of pure gold', false, 'c60fee3b-69c8-4ba2-8b2d-cabdc3caac7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('feda8727-f044-40b9-919a-0c591b3010c2', 'That humans can never attain salvation', false, 'c60fee3b-69c8-4ba2-8b2d-cabdc3caac7d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89823d7d-5b43-4aa5-aac3-00e8877b8d8a', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What was Ramanuja''s 11th-century philosophical doctrine of ''VISHISHTADVAITA'' (Qualified Non-dualism) preached in Tamil Nadu?', 'Ramanuja harmonized Vedanta with Bhakti: the individual soul is an organic part (amsha) of Vishnu, finding salvation through loving surrender (Prapatti).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b0733a4-87f6-4e54-8727-4ace69c26f08', 'The individual soul remains distinct and qualified even when united with the Supreme Brahman through passionate, loving devotion (Bhakti) to Vishnu', true, '89823d7d-5b43-4aa5-aac3-00e8877b8d8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56ba056b-a7e9-432e-964b-af28bc85dc2b', 'That God has no love for humans', false, '89823d7d-5b43-4aa5-aac3-00e8877b8d8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20d25ca9-8f2d-48b2-86d1-6c0a656f4ceb', 'That all rituals must be conducted in silence', false, '89823d7d-5b43-4aa5-aac3-00e8877b8d8a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28b84d22-c778-432d-87ac-f635e8393885', 'That souls are completely destroyed after death', false, '89823d7d-5b43-4aa5-aac3-00e8877b8d8a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('018643d0-3fa0-4e3e-bd98-82464caafffc', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What are the famous canonical song anthologies of the Nayanars and the Alvars called in Tamil literature?', 'Nayanar hymns are compiled in the 12 Tirumurais (including Tevaram & Tiruvacakam); Alvar hymns comprise the 4,000 verses of the Divya Prabandham.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdbc4360-5b28-462f-8f2e-69eea92698cd', 'Nayanars: ''Tevaram'' and ''Tiruvacakam'' ; Alvars: ''Divya Prabandham''', true, '018643d0-3fa0-4e3e-bd98-82464caafffc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d7efc3a-3daf-4f53-86af-cde00dbb96cd', 'Vedas and Upanishads', false, '018643d0-3fa0-4e3e-bd98-82464caafffc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01c0423e-6150-408c-ac61-b18eae8036d1', 'Ramayana and Mahabharata', false, '018643d0-3fa0-4e3e-bd98-82464caafffc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9b4fc4e-7501-4d8d-85c9-1b97ef281f35', 'Puranas and Gita', false, '018643d0-3fa0-4e3e-bd98-82464caafffc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('93432505-c8c4-46d9-9985-b2f297d805dd', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What radical social reform did the Virashaiva Vachana literature champion in 12th-century medieval society?', 'Virashaiva Vachanas (by Basavanna, Allama, Akkamahadevi) attacked caste oppression, empty ritualism, and patriarchal subordination of women.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('889e10a9-b7c8-4687-b190-27524fad9e45', 'Fierce denunciation of caste hierarchies, untouchability, sacrificial animal slaughter, and ritual pollution, while asserting the spiritual equality and independence of women', true, '93432505-c8c4-46d9-9985-b2f297d805dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72627db7-e1eb-4f8d-993e-de8b4cc31d4c', 'Building large stone prisons', false, '93432505-c8c4-46d9-9985-b2f297d805dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b9ae26d-f412-425d-855b-7b106d17af5d', 'Banning all books and music', false, '93432505-c8c4-46d9-9985-b2f297d805dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2d61712-f5a9-4597-8690-733ebc12585e', 'Forcing people to fast every day', false, '93432505-c8c4-46d9-9985-b2f297d805dd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4cdb8fa-cd66-40d7-be54-e49d022f6637', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'Why did the medieval Bhakti saints of Maharashtra (Jnaneshwar, Eknath, Tukaram) REJECT the traditional concept of ascetic renunciation (Sannyasa)?', 'The Marathi saints humanized Bhakti: Tukaram proclaimed that he who recognizes the suffering of the distressed as his own is a true saint.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fd25f0b-64ed-4e3e-9763-81cb2ce59597', 'They believed true spirituality lay in living as ordinary householders, earning an honest livelihood, and serving fellow human beings in distress with compassion (active social service)', true, 'e4cdb8fa-cd66-40d7-be54-e49d022f6637');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa71795f-3a74-470c-8fab-4753b7fff8e7', 'Because they wanted to become wealthy kings', false, 'e4cdb8fa-cd66-40d7-be54-e49d022f6637');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0a37ed1-ead9-4ede-a5a4-e85d7d918054', 'Because they disliked nature', false, 'e4cdb8fa-cd66-40d7-be54-e49d022f6637');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e87ca007-e226-4379-b81a-6088cef03503', 'Because forests were too cold', false, 'e4cdb8fa-cd66-40d7-be54-e49d022f6637');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7489e65-da4f-463e-b4e7-e50e094490f2', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What were the ''Khanqahs'' of the Sufi masters in medieval India?', 'Khanqahs served as inclusive spiritual hospices where people of all faiths gathered for discourse, music, blessings, and community meals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab17d88c-eb62-40a2-88bf-c173bb355140', 'Hospices and community centers where Sufi Pir masters taught disciples, hosted spiritual assemblies (Sama), and fed travelers, nobles, and commoners from all walks of life', true, 'c7489e65-da4f-463e-b4e7-e50e094490f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('006ee6d9-0575-444b-bf8f-41fc44f6e3f4', 'Military forts for weapons', false, 'c7489e65-da4f-463e-b4e7-e50e094490f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99daf775-2504-46b9-b46e-6d0aae3aad41', 'Royal tax collection offices', false, 'c7489e65-da4f-463e-b4e7-e50e094490f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a3c1520-053a-4f96-89d6-323a1e9445a5', 'Prisons for criminals', false, 'c7489e65-da4f-463e-b4e7-e50e094490f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e1ad686-0cf9-4322-8f11-cc85584cdccc', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What is ''Zikr'' and ''Sama'' in the devotional spiritual practice of Sufi mysticism?', 'Sufi praxis: Zikr (contemplative remembrance of God) and Sama (ecstatic mystical music/qawwali) dissolve ego in divine love.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95c0a98d-526c-4791-aa49-e49bc33fd03c', 'Zikr is the rhythmic chanting/repetition of the divine Name of God ; Sama is spiritual music and audition evoking divine ecstatic love', true, '8e1ad686-0cf9-4322-8f11-cc85584cdccc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d68a3968-7ce0-482d-8255-743a7969bd95', 'Zikr is sword fighting and Sama is swimming', false, '8e1ad686-0cf9-4322-8f11-cc85584cdccc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18ad33af-c467-47e3-8865-0d3b5624218a', 'Zikr is eating food and Sama is sleeping', false, '8e1ad686-0cf9-4322-8f11-cc85584cdccc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21eeca6f-f9d0-4e69-9044-10705fa932b2', 'Both are names of desert horses', false, '8e1ad686-0cf9-4322-8f11-cc85584cdccc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ebcbc32-69d8-45ef-a343-f1c892616491', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What were the core principles of Guru Nanak''s spiritual teachings summarized in three cardinal pillars?', 'Guru Nanak''s core triadic ethics: Nam Japna (devotional remembrance), Kirt Karna (honest labor), and Vand Chhakna (charitable sharing).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5365970d-13d6-4d9e-b8b7-b1c3a437deaa', '1. Nam Japna (Chanting the Name of God) ; 2. Kirt Karna (Honest, ethical labor) ; 3. Vand Chhakna (Sharing one''s earnings with others in charity)', true, '8ebcbc32-69d8-45ef-a343-f1c892616491');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2178314-1171-448d-813a-a0f3887e508d', 'Fasting, Penance, and Forest Exile', false, '8ebcbc32-69d8-45ef-a343-f1c892616491');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b3ae488-64c3-4919-abe0-a2e36bfe33c7', 'Sacrifice, Rituals, and Pilgrimages', false, '8ebcbc32-69d8-45ef-a343-f1c892616491');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6913b00e-9e43-4599-ab90-5f93e625d1fd', 'Wars, Conquests, and Taxes', false, '8ebcbc32-69d8-45ef-a343-f1c892616491');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('857a2a1f-4eb9-4ba1-b9fe-736f6b3d0494', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What was the historical significance of the ''Langar'' (community kitchen) instituted by Guru Nanak and expanded by Guru Angad and Guru Amar Das?', 'Langar institutionalized radical social equality: emperor and peasant sat side by side in pangat, sharing identical food prepared communally.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13103b76-6d27-4686-8d70-d726f7f6c3fd', 'People of ALL castes, religions, and social backgrounds sat together on the floor (Pangat) to eat the exact same meal together, completely destroying caste taboos and untouchability', true, '857a2a1f-4eb9-4ba1-b9fe-736f6b3d0494');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86ac2d47-767a-417d-b3ba-5f03cd6f3a27', 'It was a restaurant for wealthy merchants', false, '857a2a1f-4eb9-4ba1-b9fe-736f6b3d0494');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dba7a25c-29a7-4ecc-bb37-b5811ef551c2', 'It was a feast held only once a year', false, '857a2a1f-4eb9-4ba1-b9fe-736f6b3d0494');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('908c38e4-a15e-42b1-bb91-debbbb99073e', 'Only kings were allowed to eat there', false, '857a2a1f-4eb9-4ba1-b9fe-736f6b3d0494');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('903c56ef-c3cd-4ab6-b2ef-8801eadef8ce', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'Why did the Mughal Emperor Jahangir view the growing influence and autonomous political-military stature of Guru Arjan Dev Ji as a potential threat, leading to the Guru''s martyrdom in 1606?', 'Jahangir recorded in Tuzuk that the expanding spiritual authority of Guru Arjan Dev threatened imperial control, prompting state persecution.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b29f4c7-16c6-49fa-821f-d94ba7e2c3cc', 'The Sikh community had transformed into a dynamic, prosperous, self-governing socio-religious brotherhood centered at Amritsar, attracting large numbers of both Hindu and Muslim followers', true, '903c56ef-c3cd-4ab6-b2ef-8801eadef8ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95d94b91-7161-4a81-bbea-ad3aa31cc3e3', 'Because Guru Arjan refused to pay road tax', false, '903c56ef-c3cd-4ab6-b2ef-8801eadef8ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e729d45a-e7d9-45a4-9586-91e49c5d4a65', 'Because the Sikhs built a navy', false, '903c56ef-c3cd-4ab6-b2ef-8801eadef8ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7919a7f3-4ddf-464d-84ca-a011abb515e4', 'Because of a boundary dispute over a farm', false, '903c56ef-c3cd-4ab6-b2ef-8801eadef8ce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2fddf778-4df0-447f-acbd-12dc650aaac3', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'Who founded the ''Khalsa Panth'' (the community of the pure saint-soldiers) at Anandpur Sahib on Baisakhi Day in 1699, forging the Sikhs into a formidable martial and spiritual brotherhood?', 'Guru Gobind Singh Ji established the Khalsa in 1699 with the Five Ks (Kesh, Kangha, Kara, Kachhera, Kirpan) to defend justice against tyranny.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ec07a31-29de-45a0-a442-a0590b34a385', 'Guru Gobind Singh Ji (the 10th Sikh Guru)', true, '2fddf778-4df0-447f-acbd-12dc650aaac3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e224f66-6bf6-453a-a48e-bc2375116246', 'Guru Nanak Dev Ji', false, '2fddf778-4df0-447f-acbd-12dc650aaac3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08b34c39-0460-4728-9df2-828e41782559', 'Guru Tegh Bahadur Ji', false, '2fddf778-4df0-447f-acbd-12dc650aaac3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84caf2f8-8b01-4c7d-8927-687a3bbfa44f', 'Banda Singh Bahadur', false, '2fddf778-4df0-447f-acbd-12dc650aaac3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('455b363b-893b-4eac-87a5-fc64725c5ee2', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'Which blind poet of Braj composed the monumental devotional anthology ''Sursagar'', celebrating the childhood lilas of Lord Krishna in Brajbhasha?', 'Surdas (a disciple of Vallabhacharya) composed the Sursagar, Sur Saravali, and Sahitya Lahari celebrating Krishna''s Vatsalya and Madhurya rasas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e5fb5d5-01d3-4c8a-af53-50e26f7c183b', 'Sant Surdas', true, '455b363b-893b-4eac-87a5-fc64725c5ee2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dab4bae7-26d3-425c-aada-4dcf5a0b8221', 'Tulsidas', false, '455b363b-893b-4eac-87a5-fc64725c5ee2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('241ba7a7-9444-45f2-bae2-29c48ffc0655', 'Kabir', false, '455b363b-893b-4eac-87a5-fc64725c5ee2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ec1c58c-f9e6-4b4b-b585-8ade84ab54bf', 'Raskhan', false, '455b363b-893b-4eac-87a5-fc64725c5ee2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae58add0-ede2-4273-92af-14a9b7992456', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What was the ''Ekasarana Dharma'' propagated by Sankaradeva in Assam?', 'Sankaradeva''s Ekasarana Dharma focused on monotheistic Krishna bhakti centered on congregational chanting in village Namghars.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7dbac0c-dcc8-4965-bef3-1f6640059e02', 'Devotional surrender to the Supreme Lord Krishna alone, discarding idol worship and complex rituals, and seeking spiritual solace in chanting the Name of God (Nam-Kirtan)', true, 'ae58add0-ede2-4273-92af-14a9b7992456');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('baefd81e-b2b8-4e62-a98c-f0fb03013120', 'Worship of 100 deities simultaneously', false, 'ae58add0-ede2-4273-92af-14a9b7992456');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc9e427d-e75c-4f46-b4ab-1ce61d92d243', 'Renunciation of all food', false, 'ae58add0-ede2-4273-92af-14a9b7992456');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8cc30857-9b57-4aa4-9b62-168e76c79794', 'Building giant stone statues', false, 'ae58add0-ede2-4273-92af-14a9b7992456');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('39afeca6-f812-48c3-bd82-a237ac750779', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'What were the ''Nathpanthis, Siddhas, and Yogis'' who challenged conventional ritual orthodoxy in northern India?', 'Nathpanthis and Yogis (associated with Gorakhnath) taught Hatha Yoga, breath control, and inner esoteric realization beyond ritual dogma.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc65a6c2-9191-4167-bd9e-831bff0e7258', 'Renouncers from lower artisanal groups who advocated intense meditation on formless reality, breathing exercises (Pranayama), yogasanas, and mind-body purification to attain liberation', true, '39afeca6-f812-48c3-bd82-a237ac750779');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e51e315f-5d9f-4508-8354-99c7609416ef', 'Royal priests in Delhi palaces', false, '39afeca6-f812-48c3-bd82-a237ac750779');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfd3323b-9676-4e18-990b-acd256207bdc', 'Foreign merchants who sold silk', false, '39afeca6-f812-48c3-bd82-a237ac750779');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93ca8ea7-cead-4b73-bae7-5e4bfdd32c5b', 'Soldiers who fought on horses', false, '39afeca6-f812-48c3-bd82-a237ac750779');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a43e583b-4e80-4ae5-820e-3e9bd98c919d', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'Who was the revered 14th-century Sufi saint of Delhi known as ''Mehboob-e-Ilahi'' (Beloved of God), who lived in Ghyaspur (Delhi) and inspired Amir Khusrau?', 'Hazrat Nizamuddin Auliya preached boundless charity and tolerance; his court disciple Amir Khusrau pioneered Hindavi and Qawwali music.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1838a263-58ff-4811-b552-a7299f655ec0', 'Hazrat Nizamuddin Auliya', true, 'a43e583b-4e80-4ae5-820e-3e9bd98c919d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('955c0e14-c63b-4021-b12f-02db45c5fc04', 'Khwaja Muinuddin Chishti', false, 'a43e583b-4e80-4ae5-820e-3e9bd98c919d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6025a831-bdec-4178-80f1-b25fbc5902ae', 'Baba Farid', false, 'a43e583b-4e80-4ae5-820e-3e9bd98c919d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efc05188-7982-4cb2-b363-9a78b5d23362', 'Qutbuddin Bakhtiyar Kaki', false, 'a43e583b-4e80-4ae5-820e-3e9bd98c919d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66190996-14a4-420a-b9c5-f2ddaaaea5b0', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Medium', 'In what language did Kabir compose his powerful verses (Sakhis, Dohas, and Rekhtas)?', 'Kabir wrote in direct, forceful vernacular Hindi (Saddukkadi), utilizing sharp colloquial idioms that pierced through scholastic pretension.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e31313d4-2ef6-413d-96b9-65353f8b1d5d', 'In the rough, rustic colloquial vernacular Hindi of the common people (Saddukkadi / Khari Boli / Bhojpuri), making them directly accessible to ordinary peasants and weavers', true, '66190996-14a4-420a-b9c5-f2ddaaaea5b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74305bbf-8f5a-4e3b-8e52-401177a35427', 'In difficult classical Sanskrit only', false, '66190996-14a4-420a-b9c5-f2ddaaaea5b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9fb6eb9-b185-4ae5-add7-e9ba0e560cb5', 'In ancient Latin', false, '66190996-14a4-420a-b9c5-f2ddaaaea5b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8977b9c-2356-47fa-b8ba-7e5035d4b5ba', 'In Portuguese', false, '66190996-14a4-420a-b9c5-f2ddaaaea5b0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab3e7055-5144-4033-91d7-6e4f7b33eaf4', 'Class 7', 'Social Science', 'Chapter 8: Devotional Paths to the Divine', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e020b4ea-043b-402b-84b3-44986977efa0', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'ab3e7055-5144-4033-91d7-6e4f7b33eaf4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58c9b1f1-57ec-44d6-b913-c5d8d2f5c9ef', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'ab3e7055-5144-4033-91d7-6e4f7b33eaf4');
