INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fd6cf59-b0aa-4184-833c-021d146fcf01', 'अनिश्चयवाचक सर्वनाम', false, '3806333c-c942-4df4-9ba6-47e319c37de8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49c69c07-ec83-4774-8451-6f72c48cf8f5', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Easy', '''मैं अपना काम स्वयं (खुद / अपने आप) करूँगा।'' वाक्य में ''स्वयं'' और ''अपने आप'' किस प्रकार का सर्वनाम है?', 'निजवाचक सर्वनाम: कर्ता अपने लिए जिन शब्दों का प्रयोग करता है (स्वयं, खुद, अपने आप, आप ही)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bb65087-7e3e-4cd2-8a79-bee50ee7e8be', 'निजवाचक सर्वनाम (Reflexive Pronoun)', true, '49c69c07-ec83-4774-8451-6f72c48cf8f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fafa76d9-62ff-49b1-a265-4769d7b18ac2', 'पुरुषवाचक सर्वनाम', false, '49c69c07-ec83-4774-8451-6f72c48cf8f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9a64bac-50ae-44a2-9724-683758d219fc', 'निश्चयवाचक सर्वनाम', false, '49c69c07-ec83-4774-8451-6f72c48cf8f5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11889944-fa0c-42be-8547-ede2c6c37fd2', 'प्रश्नवाचक सर्वनाम', false, '49c69c07-ec83-4774-8451-6f72c48cf8f5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a1017a5b-91a1-45b5-8ca4-7285bec99cd2', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Easy', 'हिंदी भाषा में मूल सर्वनाम शब्दों की संख्या कुल कितनी मानी जाती है?', 'हिंदी व्याकरण में 11 मूल (मौलिक) सर्वनाम माने गए हैं: मैं, तू, आप, यह, वह, जो, सो, कोई, कुछ, कौन, क्या।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f31b43d-5878-47e4-9742-406ec8b1f9a3', '11 मूल सर्वनाम (मैं, तू, आप, यह, वह, जो, सो, कोई, कुछ, कौन, क्या)', true, 'a1017a5b-91a1-45b5-8ca4-7285bec99cd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da7dca50-214d-4a37-8361-a47048e59ab5', '5 मूल सर्वनाम', false, 'a1017a5b-91a1-45b5-8ca4-7285bec99cd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d57472e8-0ad2-4c4a-85af-5a9b1f8bc466', '20 मूल सर्वनाम', false, 'a1017a5b-91a1-45b5-8ca4-7285bec99cd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee016db3-82f7-4206-b3f8-d4456f551941', '7 मूल सर्वनाम', false, 'a1017a5b-91a1-45b5-8ca4-7285bec99cd2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4dec4d0f-1cbf-48d0-899e-ba17e3a6ec90', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', 'निश्चयवाचक सर्वनाम और सार्वनामिक विशेषण में क्या मुख्य अंतर होता है?', '''यह मेरी पुस्तक है'' = निश्चयवाचक सर्वनाम; ''यह पुस्तक मेरी है'' = सार्वनामिक विशेषण (संज्ञा से पूर्व प्रयुक्त)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5145fef-26c0-4a0f-9270-f1126c0ccb78', 'जब ''यह'' या ''वह'' अकेले आकर संज्ञा के स्थान पर प्रयुक्त हों, तो वे ''निश्चयवाचक सर्वनाम'' होते हैं (जैसे: ''यह मेरा घर है'') ; परन्तु जब वे संज्ञा से ठीक पहले लगकर उसकी विशेषता बताएँ, तो वे ''सार्वनामिक विशेषण'' बन जाते हैं (जैसे: ''यह घर मेरा है'')', true, '4dec4d0f-1cbf-48d0-899e-ba17e3a6ec90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18b96ed2-7279-4557-ab24-670d572b8969', 'दोनों में कोई अंतर नहीं होता', false, '4dec4d0f-1cbf-48d0-899e-ba17e3a6ec90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d72ee7b-322b-4255-b768-257689dd8deb', 'सार्वनामिक विशेषण केवल पुल्लिंग होते हैं', false, '4dec4d0f-1cbf-48d0-899e-ba17e3a6ec90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b802002b-fbfe-4805-a29c-05301eaa2dde', 'सर्वनाम कभी वाक्य में प्रयुक्त नहीं हो सकते', false, '4dec4d0f-1cbf-48d0-899e-ba17e3a6ec90');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('06979817-11b6-4f17-8dde-5dd32a5ffb75', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''आप'' शब्द का प्रयोग मध्यम पुरुष और निजवाचक सर्वनाम—दोनों में किस प्रकार भिन्न अर्थ में होता है?', 'आदरार्थक मध्यम पुरुष: ''आप बैठिए''; निजवाचक (स्वयं के अर्थ में): ''वह अपने आप चला जाएगा''।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13316b90-987e-435d-b31f-eb96b8494d0a', 'श्रोता के आदर के लिए प्रयुक्त ''आप'' मध्यम पुरुष होता है (जैसे: ''आप कब आए?''); जबकि कर्ता द्वारा अपने लिए प्रयुक्त ''आप'' निजवाचक होता है (जैसे: ''मैं यह काम आप ही कर लूँगा'')', true, '06979817-11b6-4f17-8dde-5dd32a5ffb75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f25750e0-4ee4-4979-b3a9-6e870b95a2b4', 'दोनों सदैव एकवचन होते हैं', false, '06979817-11b6-4f17-8dde-5dd32a5ffb75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14884e47-5ff6-4a5b-b8f4-e8b46859d4b3', '''आप'' केवल बहुवचन में ही आता है', false, '06979817-11b6-4f17-8dde-5dd32a5ffb75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e4fccf4-a6ac-4509-b58e-8b3b019fdfcc', 'निजवाचक में ''आप'' का प्रयोग अशुद्ध है', false, '06979817-11b6-4f17-8dde-5dd32a5ffb75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87025516-9c0c-492e-b096-f813d2b59a45', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''जिसकी लाठी, उसकी भैंस।'' वाक्य में ''जिसकी'' और ''उसकी'' सर्वनाम के किस भेद के उदाहरण हैं?', '''जिसकी... उसकी'' परस्पर आश्रित उपवाक्यों में संबंध स्थापित करने वाले संबंधवाचक सर्वनाम हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c70800fe-00af-429d-b932-b104da67f53a', 'संबंधवाचक सर्वनाम', true, '87025516-9c0c-492e-b096-f813d2b59a45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a9a336b-b19b-4088-bd87-9bdd8577c6bf', 'निश्चयवाचक सर्वनाम', false, '87025516-9c0c-492e-b096-f813d2b59a45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2af2106-cafc-4acc-832b-207fab3da5e4', 'निजवाचक सर्वनाम', false, '87025516-9c0c-492e-b096-f813d2b59a45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae9ec52b-78db-41c7-ad5e-773ddf1f124e', 'अनिश्चयवाचक सर्वनाम', false, '87025516-9c0c-492e-b096-f813d2b59a45');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('060081d0-c0de-415c-9c05-b6e9867880b1', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''पानी में कुछ पड़ा है।'' वाक्य में ''कुछ'' का प्रयोग किस संदर्भ में हुआ है?', '''कुछ'' का प्रयोग अप्राणिवाचक (निर्जीव/द्रव्य) अनिश्चित वस्तुओं के लिए होता है (''कोई'' का सजीव प्राणियों के लिए)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2116b98a-49f6-46e5-8bed-97763b66b398', 'निर्जीव वस्तु या पदार्थ के लिए अनिश्चयवाचक सर्वनाम के रूप में', true, '060081d0-c0de-415c-9c05-b6e9867880b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6bd6dda-3ff7-489a-9189-38349ef7ff96', 'सजीव प्राणी के लिए', false, '060081d0-c0de-415c-9c05-b6e9867880b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d58eaa0-5bc3-4468-8b9b-4b0a46f88bf7', 'प्रश्न पूछने के लिए', false, '060081d0-c0de-415c-9c05-b6e9867880b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94018a44-647e-4ea7-b4a5-4a9df41f136b', 'निजवाचक सर्वनाम के रूप में', false, '060081d0-c0de-415c-9c05-b6e9867880b1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03817db0-c424-4a61-89b6-f93167e7714e', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''बाहर कोई आया है।'' वाक्य में ''कोई'' का प्रयोग किस संदर्भ में हुआ है?', '''कोई'' प्राणिवाचक अनिश्चयवाचक सर्वनाम है (जैसे: कोई आया है, किसी ने बुलाया है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45c69cb7-dc4a-4d5c-b293-16f0a7faa722', 'सजीव प्राणी (व्यक्ति) के लिए अनिश्चयवाचक सर्वनाम के रूप में', true, '03817db0-c424-4a61-89b6-f93167e7714e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a5df7c9-36f8-4f45-8732-593801503bf3', 'निर्जीव पदार्थ के लिए', false, '03817db0-c424-4a61-89b6-f93167e7714e');
