INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ee3dee8-77fd-4213-8695-af0fc912a660', 'उत्तम पुरुष के रूप में', false, '03817db0-c424-4a61-89b6-f93167e7714e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5b87f2ad-2116-4054-b2e7-7ad8e43d0984', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''तुमने क्या खाया है?'' वाक्य में ''क्या'' किस प्रकार का सर्वनाम है?', '''क्या'' अप्राणिवाचक प्रश्नवाचक सर्वनाम है (''कौन'' प्राणिवाचक प्रश्नवाचक है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aded8e47-9b80-481c-a8d1-5923bdc584e5', 'प्रश्नवाचक सर्वनाम (वस्तु/पदार्थ के संबंध में प्रश्न पूछने के लिए)', true, '5b87f2ad-2116-4054-b2e7-7ad8e43d0984');
