INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d9d7942-6b58-4d29-bbdc-be676cb8a4e2', 'निजवाचक सर्वनाम', false, '5b87f2ad-2116-4054-b2e7-7ad8e43d0984');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('567a399c-1c3c-4d99-96c9-aee69f14331f', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', 'सर्वनाम शब्दों में किस कारक की विभक्ति का प्रयोग कभी नहीं होता?', 'सर्वनाम शब्दों में केवल 7 कारकों (कर्ता से अधिकरण तक) की ही रूप-रचना होती है; संबोधन कारक सर्वनामों में नहीं होता।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57de11bb-eb6f-465c-ba4f-f6221350e7c8', 'संबोधन कारक (हे, अरे, भो का प्रयोग सर्वनामों के साथ नहीं होता)', true, '567a399c-1c3c-4d99-96c9-aee69f14331f');
