INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('260a2d0c-4153-4541-a104-0685f2441d66', 'अपादान कारक', false, '567a399c-1c3c-4d99-96c9-aee69f14331f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7e73a7f3-f79f-458e-9380-5e665c2dbd68', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''मैं'' (उत्तम पुरुष एकवचन) का करण कारक में एकवचन रूप क्या बनेगा?', 'मैं + से (करण कारक) = मुझसे / मेरे द्वारा।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56829cdf-7fb8-4f6d-8d1f-f176b7158336', 'मुझसे / मेरे द्वारा', true, '7e73a7f3-f79f-458e-9380-5e665c2dbd68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6953d214-37e4-4d40-8eeb-2c2e715209d3', 'मुझको', false, '7e73a7f3-f79f-458e-9380-5e665c2dbd68');
