INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('010d6d9f-0935-40e4-a991-b9985cb92fb2', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''वह'' (अन्य पुरुष एकवचन) का संप्रदान कारक में बहुवचन रूप क्या होगा?', 'वह (बहुवचन ''वे'') + को/के लिए = उन्हें / उनके लिए / उनको।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('880105ff-28c6-4c19-bdcc-59bf160302c2', 'उन्हें / उनके लिए / उनको', true, '010d6d9f-0935-40e4-a991-b9985cb92fb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef0771fa-806b-4bc9-8619-ae3792673dee', 'उसको', false, '010d6d9f-0935-40e4-a991-b9985cb92fb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18f1ea1d-c564-4547-b513-389aedb74bd9', 'उससे', false, '010d6d9f-0935-40e4-a991-b9985cb92fb2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9eb45cce-c22c-492f-96a7-094c5246497f', 'उसका', false, '010d6d9f-0935-40e4-a991-b9985cb92fb2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5618f15c-8efb-4a20-8ba5-c9ebcac91881', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', 'निम्नलिखित वाक्यों में से ''अशुद्ध सर्वनाम प्रयोग'' वाला वाक्य चुनिए:', 'हिंदी मानक व्याकरण में ''तेरे को / मेरे को'' अमानक और अशुद्ध है; इसके स्थान पर ''तुझे/तुम्हें'' और ''मुझसे'' का प्रयोग होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3313557-86fd-4b23-a15f-0dd0bc70efe3', '''तेरे को मेरे से क्या काम है?'' (अशुद्ध रूप ; शुद्ध होगा: ''तुम्हें मुझसे क्या काम है?'')', true, '5618f15c-8efb-4a20-8ba5-c9ebcac91881');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99b29e81-e4ee-4da4-b9ae-ae353e3d8429', '''आप यहाँ बैठिए।''', false, '5618f15c-8efb-4a20-8ba5-c9ebcac91881');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da61eca9-dd6d-49b2-a76b-e5f644fe2339', '''वह अपना काम कर रहा है।''', false, '5618f15c-8efb-4a20-8ba5-c9ebcac91881');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce819785-ced1-4ee0-9bba-934bb7815bcf', '''जो पढ़ेगा, वह पास होगा।''', false, '5618f15c-8efb-4a20-8ba5-c9ebcac91881');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2abc30e0-75f1-41e7-8b60-dd6a4825fe59', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''यह वही बालक है, जिसे कल पुरस्कार मिला था।'' वाक्य में ''जिसे'' सर्वनाम का कौन-सा रूप है?', '''जिसे'' संबंधवाचक सर्वनाम ''जो'' का कर्म कारक एकवचन रूप है (जो + को = जिसे)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2817a7f1-fc1b-4576-958c-7e927a5530e1', 'संबंधवाचक सर्वनाम (कर्म कारक रूप)', true, '2abc30e0-75f1-41e7-8b60-dd6a4825fe59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe52a819-4459-4909-8683-e910eb8bc977', 'निजवाचक सर्वनाम', false, '2abc30e0-75f1-41e7-8b60-dd6a4825fe59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33b5ffc1-c2dc-4bd2-9c3c-8d1421fa2a0f', 'अनिश्चयवाचक सर्वनाम', false, '2abc30e0-75f1-41e7-8b60-dd6a4825fe59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09b0a3ca-503d-423c-8075-cd470a7290d3', 'पुरुषवाचक सर्वनाम', false, '2abc30e0-75f1-41e7-8b60-dd6a4825fe59');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('af1a4fbc-22b1-4e97-894a-7f3ece487d6d', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''हम कल मुंबई जाएँगे।'' वाक्य में रेखांकित सर्वनाम ''हम'' किस वचन और पुरुष में है?', '''हम'' उत्तम पुरुष का बहुवचन रूप है (एकवचन ''मैं'' होता है)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b932c3b5-c0db-475a-818e-f24b2e1dde88', 'बहुवचन, उत्तम पुरुष', true, 'af1a4fbc-22b1-4e97-894a-7f3ece487d6d');
