INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b8be64f-6c67-4f12-988b-6e6ba52c5f34', 'एकवचन, उत्तम पुरुष', false, 'af1a4fbc-22b1-4e97-894a-7f3ece487d6d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3be5c76b-732a-4564-92b7-d26d2b9dec6d', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''उसकी गाय बहुत सीधी है।'' वाक्य में ''उसकी'' किस कारक का रूप है?', 'वह + का/के/की = उसका / उसकी / उसके (संबंध कारक)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f376f8b1-d5fb-4194-a7e9-2f55b3a598a1', 'संबंध कारक (वह + की = उसकी)', true, '3be5c76b-732a-4564-92b7-d26d2b9dec6d');
