INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96851b9e-40d9-47b6-89df-609967c49fce', 'अधिकरण कारक', false, '3be5c76b-732a-4564-92b7-d26d2b9dec6d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('098b7adc-0ef5-45e3-8f1f-9b6059d18d93', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''वे सब अपने घर चले गए।'' वाक्य में ''अपने'' किस सर्वनाम का उदाहरण है?', '''अपना / अपनी / अपने'' निजवाचक सर्वनाम के रूप हैं, जो कर्ता के स्वयं के संबंध का बोध कराते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b5fe124-9190-4c84-b780-3a4f8028d934', 'निजवाचक सर्वनाम (या संबंधवाचक निज रूप)', true, '098b7adc-0ef5-45e3-8f1f-9b6059d18d93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1d2d702-1657-47ec-a9b6-ea7669838b7a', 'प्रश्नवाचक सर्वनाम', false, '098b7adc-0ef5-45e3-8f1f-9b6059d18d93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92dc63e5-db1b-4b9e-bc7c-12f76885ed16', 'अनिश्चयवाचक सर्वनाम', false, '098b7adc-0ef5-45e3-8f1f-9b6059d18d93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4166cc8-ffb1-4a1c-9795-7d0c27415145', 'मध्यम पुरुष', false, '098b7adc-0ef5-45e3-8f1f-9b6059d18d93');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b59931fb-56ba-4e1b-b110-936338009e35', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''कोई तुम्हें बुला रहा है।'' वाक्य में ''कोई'' और ''तुम्हें'' क्रमशः कौन-से सर्वनाम हैं?', '''कोई'' अनिश्चयवाचक है और ''तुम्हें'' मध्यम पुरुष (तुम + को) है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dda7da04-5764-449f-a028-7c8c921497df', '''कोई'' = अनिश्चयवाचक सर्वनाम ; ''तुम्हें'' = मध्यम पुरुषवाचक सर्वनाम', true, 'b59931fb-56ba-4e1b-b110-936338009e35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27928b2e-880a-4890-ae71-ec8205a8ce7a', '''कोई'' = निश्चयवाचक ; ''तुम्हें'' = उत्तम पुरुष', false, 'b59931fb-56ba-4e1b-b110-936338009e35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3c5e635-6cc3-4880-a06d-06b065565ed4', '''कोई'' = प्रश्नवाचक ; ''तुम्हें'' = निजवाचक', false, 'b59931fb-56ba-4e1b-b110-936338009e35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a11cd026-25b2-4f3f-8751-2c8e7e574229', 'दोनों निजवाचक हैं', false, 'b59931fb-56ba-4e1b-b110-936338009e35');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6fe8833b-6a2d-4e8a-895e-7fa1ee11165b', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Medium', '''सच्चा मित्र वही है, जो विपत्ति में काम आए।'' वाक्य में ''वही-जो'' किस सर्वनाम युग्म का बोध कराते हैं?', '''वही... जो'' सह-संबंधी सर्वनाम हैं जो दो उपवाक्यों को परस्पर जोड़ते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81f14d21-8e0e-46e2-af15-d2ba23220d88', 'संबंधवाचक सर्वनाम', true, '6fe8833b-6a2d-4e8a-895e-7fa1ee11165b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e04dd282-fe80-4db9-828c-0755fb6ef6f9', 'प्रश्नवाचक सर्वनाम', false, '6fe8833b-6a2d-4e8a-895e-7fa1ee11165b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59c3aab7-bc37-42f5-af21-6f5cf29048f0', 'अनिश्चयवाचक सर्वनाम', false, '6fe8833b-6a2d-4e8a-895e-7fa1ee11165b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1e53761-b3b1-4e37-9372-97a71a6996d3', 'निजवाचक सर्वनाम', false, '6fe8833b-6a2d-4e8a-895e-7fa1ee11165b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9789864c-da05-4fae-b713-40dcc49b090b', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c17dc3b4-d77c-4f46-b2d1-9f5554af906e', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '9789864c-da05-4fae-b713-40dcc49b090b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('361d92e9-1a26-4a8c-be0f-f8880c89a409', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '9789864c-da05-4fae-b713-40dcc49b090b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdf58ddf-9325-42c7-8526-9da4a12fe5b3', '(A) सही है, परन्तु (R) गलत है।', false, '9789864c-da05-4fae-b713-40dcc49b090b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b9fa281-b3ce-4aa2-a7a1-60048a0fe55c', '(A) गलत है, परन्तु (R) सही है।', false, '9789864c-da05-4fae-b713-40dcc49b090b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('62b80084-0e60-46ca-bb18-4642f6a6d521', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', 'Spot the IMPOSTER in the following group of सर्वनाम और उनके भेद वर्गीकरण में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02c17dfa-8786-4af1-99f9-1671f7d5b672', 'वर्गीकरण 1', false, '62b80084-0e60-46ca-bb18-4642f6a6d521');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9867e25e-e177-4139-8664-fd187356993a', 'वर्गीकरण 2', false, '62b80084-0e60-46ca-bb18-4642f6a6d521');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a18f677f-b246-44d8-a9dd-e29260de4632', 'वर्गीकरण 3', false, '62b80084-0e60-46ca-bb18-4642f6a6d521');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2e5a71c-5436-4086-8fd3-7209b573b4b6', 'वर्गीकरण 4 (''सुंदर'' सर्वनाम नहीं, बल्कि गुणवाचक विशेषण [Adjective] है)', true, '62b80084-0e60-46ca-bb18-4642f6a6d521');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c9d9306e-1161-4827-b7b2-35d3a0a6dbc6', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', 'सुमेलित कीजिए (सर्वनाम शब्द और उनका सही भेद):
(क) जो... सो -> (i) संबंधवाचक सर्वनाम
(ख) आप ही    -> (ii) निजवाचक सर्वनाम
(ग) कोई      -> (iii) अनिश्चयवाचक सर्वनाम
(घ) कौन      -> (iv) प्रश्नवाचक सर्वनाम', 'जो-सो = संबंधवाचक; आप ही = निजवाचक; कोई = अनिश्चयवाचक; कौन = प्रश्नवाचक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04de5cdd-6c21-4235-a094-c6829ba49f3e', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, 'c9d9306e-1161-4827-b7b2-35d3a0a6dbc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46a26028-d121-4126-9523-8aa26c549597', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, 'c9d9306e-1161-4827-b7b2-35d3a0a6dbc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e989e1a-abe1-4026-ab82-81d365fc1d03', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, 'c9d9306e-1161-4827-b7b2-35d3a0a6dbc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('190b045a-2ac9-475d-bc9c-e666098a320a', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, 'c9d9306e-1161-4827-b7b2-35d3a0a6dbc6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6df9dd7-f6e1-4c1b-b79b-49d9252d5ab1', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', 'निम्नलिखित वाक्यों में से किस वाक्य में ''निजवाचक सर्वनाम'' का बिल्कुल शुद्ध प्रयोग हुआ है?', '''स्वयं'' का प्रयोग कर्ता के अपने आत्म-बोध हेतु निजवाचक सर्वनाम के रूप में शुद्ध है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4a6f724-56f1-4669-b768-ad7ec48cf57b', '''मैं यह निबंध स्वयं अपने हाथों से लिखूँगा।''', true, 'd6df9dd7-f6e1-4c1b-b79b-49d9252d5ab1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54b470c3-57f6-40cb-a892-de2cc07a0054', '''आप भला तो जग भला'' में ''आप'' केवल अन्य पुरुष है।', false, 'd6df9dd7-f6e1-4c1b-b79b-49d9252d5ab1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2769f7ab-d82b-4ba7-9a0a-439b3fa0a27e', '''मुझको मेरे को काम करने दो।''', false, 'd6df9dd7-f6e1-4c1b-b79b-49d9252d5ab1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a27b9388-255a-487e-8d28-26aec0e76975', '''कोई ने मेरी पुस्तक चुरा ली।''', false, 'd6df9dd7-f6e1-4c1b-b79b-49d9252d5ab1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3f82148f-4ab5-49c8-9b0e-c66d9390b15e', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', '''यह'' सर्वनाम के तिर्यक (विभक्ति-सहित) एकवचन और बहुवचन रूप क्रमशः क्या होते हैं?', '''यह'' का तिर्यक रूप एकवचन में ''इस'' और बहुवचन में ''इन'' होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77f33c6f-f597-484d-a6a0-4a4dee91f129', 'एकवचन: ''इस'' (जैसे: इसने, इसको, इससे) ; बहुवचन: ''इन'' (जैसे: इन्होंने, इनको, इनसे)', true, '3f82148f-4ab5-49c8-9b0e-c66d9390b15e');
