INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c810fc8a-ef2a-4500-adbd-26ca8601848b', 'एकवचन: ''उस'' (जैसे: उसने, उसको, उससे) ; बहुवचन: ''उन'' (जैसे: उन्होंने, उनको, उनसे)', true, 'd17fa003-e833-461b-b48d-282b5fac2b58');
