INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('310a95fc-26ae-4918-9a0c-d898ee1d75e0', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', 'निम्नलिखित वाक्यों में से ''शुद्ध वाक्य'' का चयन कीजिए:', 'कर्ता के स्वयं के संदर्भ में ''मेरा/उसके/हमारा'' के स्थान पर ''अपना/अपनी/अपने'' का प्रयोग ही व्याकरणिक दृष्टि से शुद्ध होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0eaa903f-beea-40b1-b8ff-2667f106f96a', '''मैंने अपना काम समय पर पूरा कर लिया है।'' (शुद्ध निजवाचक अन्वय)', true, '310a95fc-26ae-4918-9a0c-d898ee1d75e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a6e6fc2-e0b9-431a-a3ec-da24fa0a6afc', '''मैंने मेरा काम समय पर पूरा कर लिया है।''', false, '310a95fc-26ae-4918-9a0c-d898ee1d75e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2cdc14e-6416-4f20-8434-57a02c093670', '''उसने उसके भाई को बुलाया।''', false, '310a95fc-26ae-4918-9a0c-d898ee1d75e0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d8625a6-db80-4c38-9564-69b643a6bf31', '''हम हमारा कर्तव्य जानते हैं।''', false, '310a95fc-26ae-4918-9a0c-d898ee1d75e0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bd6b3579-0489-4236-8458-f82cf470d06c', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', 'संयुक्त सर्वनाम (Compound Pronouns) जैसे ''कोई-न-कोई'', ''कुछ-न-कुछ'', ''जो-कोई'', ''सब-कुछ'' किस प्रकार के सर्वनाम होते हैं?', 'डॉ. दीमशित्स के अनुसार, ''कोई न कोई, कुछ न कुछ, जो कोई, सब कुछ'' संयुक्त सर्वनाम कहलाते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1804ca52-5839-4d9f-84ff-1ce7ad79a70c', 'जब दो या दो से अधिक सर्वनाम शब्द मिलकर एक विशिष्ट यौगिक सर्वनाम का निर्माण करते हैं', true, 'bd6b3579-0489-4236-8458-f82cf470d06c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c832a55b-ba6f-4f65-bd01-1c1f3764b3f1', 'क्रिया विशेषण होते हैं', false, 'bd6b3579-0489-4236-8458-f82cf470d06c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c024c5f-c6eb-42ec-9f1d-0ee30c850f4b', 'तद्धित प्रत्यय होते हैं', false, 'bd6b3579-0489-4236-8458-f82cf470d06c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f1909ee-aaa1-4049-a603-1cb166f34ceb', 'अव्ययीभाव समास के उदाहरण मात्र होते हैं', false, 'bd6b3579-0489-4236-8458-f82cf470d06c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9dea9b07-b941-42e0-96a3-2d00973d8399', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', '''गांधीजी राष्ट्रपिता कहलाए। आपने देश को अहिंसा का पाठ पढ़ाया।'' इस दूसरे वाक्य में ''आपने'' किस पुरुष का बोध करा रहा है?', 'किसी अनुपस्थित आदरणीय महापुरुष का परिचय देते समय ''आप'' का प्रयोग ''अन्य पुरुष'' के रूप में होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7d897ab-f4bc-45b8-acd5-fbb855a70732', 'अन्य पुरुष (आदरार्थक ऐतिहासिक महापुरुष के परिचय के संदर्भ में ''आप'' का अन्य पुरुष के रूप में प्रयोग)', true, '9dea9b07-b941-42e0-96a3-2d00973d8399');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b501d98a-4b6a-49da-b6ff-a3a64a9d6a6b', 'मध्यम पुरुष', false, '9dea9b07-b941-42e0-96a3-2d00973d8399');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b76cd89b-721b-43b7-9ff2-d5ba9b98f010', 'उत्तम पुरुष', false, '9dea9b07-b941-42e0-96a3-2d00973d8399');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cece9d6-348a-48c4-8641-b8662f53ead2', 'निजवाचक', false, '9dea9b07-b941-42e0-96a3-2d00973d8399');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('173bcc78-6d64-467b-89c6-cc2e205d7bdb', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', '''किस-किस ने अपना गृहकार्य नहीं किया?'' वाक्य में ''किस-किस'' किस प्रकार का सर्वनाम रूप है?', 'प्रश्नवाचक सर्वनाम की पुनरुक्ति (''किस-किस'', ''क्या-क्या'') बहुलता और व्यापकता का बोध कराती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1cd5987-8e13-40f4-b76b-a4fcdea9ef59', 'पुनरुक्त प्रश्नवाचक सर्वनाम (विस्तार एवं अनेकता का बोध कराने वाला)', true, '173bcc78-6d64-467b-89c6-cc2e205d7bdb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('067416dc-d154-452d-b785-e4af2e39e9b2', 'अनिश्चयवाचक सर्वनाम', false, '173bcc78-6d64-467b-89c6-cc2e205d7bdb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9e5a0fa-2f67-437c-84e3-b4c5dc9419a1', 'संबंधवाचक सर्वनाम', false, '173bcc78-6d64-467b-89c6-cc2e205d7bdb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('075b588f-dcb0-4a93-8dfb-7329bdcf8204', 'निजवाचक सर्वनाम', false, '173bcc78-6d64-467b-89c6-cc2e205d7bdb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22e1d57c-2f02-4105-b036-b1b76082fcca', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', '''जो करेगा, सो भरेगा।'' वाक्य में ''सो'' के स्थान पर आधुनिक मानक हिंदी में किस सर्वनाम का प्रयोग अधिक प्रचलित है?', 'प्राचीन हिंदी में ''सो'' संबंधवाचक था; आधुनिक मानक हिंदी में ''जो'' के सह-संबंधी के रूप में ''वह'' प्रयुक्त होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04c75edf-d19c-43cf-9c3e-a913a425bd04', 'वह (जैसे: ''जो करेगा, वह भरेगा'')', true, '22e1d57c-2f02-4105-b036-b1b76082fcca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a305d48-98e4-4a6e-b031-4060adcef2ef', 'यह', false, '22e1d57c-2f02-4105-b036-b1b76082fcca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('daf7599d-84d6-4434-a48e-e18313030be1', 'आप', false, '22e1d57c-2f02-4105-b036-b1b76082fcca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31e4ef01-3723-4ca6-846d-cce578d02eec', 'कुछ', false, '22e1d57c-2f02-4105-b036-b1b76082fcca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ff557ce-4624-4f70-995c-fe597dec76be', 'Class 7', 'Hindi Grammar', 'Chapter 8: सर्वनाम और उसके भेद', 'Hard', 'सर्वनाम (Pronoun) के सम्यक ज्ञान और सटीक प्रयोग का भाषा की अभिव्यक्ति में क्या सर्वोच्च महत्व है?', 'सर्वनाम संज्ञा की नीरस पुनरुक्ति दूर कर गद्य एवं पद्य में प्रवाहमयता, संक्षिप्तता और संरचनात्मक सुदृढ़ता प्रदान करते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04c3c190-e802-4a8e-ad2d-5fd279edd3af', 'सर्वनाम संज्ञा की अवांछित पुनरावृत्ति (Repetition) को रोककर भाषा में संक्षिप्तता, लालित्य, गतिशीलता और तार्किक सुसंबद्धता (Cohesion) स्थापित करते हैं', true, '0ff557ce-4624-4f70-995c-fe597dec76be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb26cff2-0f67-41ce-8031-5a6b6ac73f7e', 'सर्वनाम केवल काव्य में प्रयुक्त होते हैं', false, '0ff557ce-4624-4f70-995c-fe597dec76be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a36a0ed-454d-4cd1-8f17-1febae9d3216', 'सर्वनाम के बिना भी भाषा पूर्णतः शुद्ध रहती है', false, '0ff557ce-4624-4f70-995c-fe597dec76be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f225eddc-53b1-403f-872c-aaca77a0cc5e', 'सर्वनाम केवल संख्याओं को गिनने के काम आते हैं', false, '0ff557ce-4624-4f70-995c-fe597dec76be');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78be497f-853b-4ebb-842e-99a02e437b73', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'What is defined as the total distance covered by a moving object per unit of time?', 'Speed is the scalar physical rate of change of position: Speed = Distance covered / Time taken.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cbec60c-b287-40d7-8c51-483b321d8bc8', 'Speed (Speed = Distance / Time)', true, '78be497f-853b-4ebb-842e-99a02e437b73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dc6e6a1-7471-40e8-85ed-844bac2b62ff', 'Acceleration', false, '78be497f-853b-4ebb-842e-99a02e437b73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22137db7-6ddb-4725-bbe7-7ade2a199c49', 'Velocity only', false, '78be497f-853b-4ebb-842e-99a02e437b73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b36941f-1124-4d0a-be25-cf4c3e729e95', 'Force', false, '78be497f-853b-4ebb-842e-99a02e437b73');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7be7e457-8871-4a64-a80b-edb8d5312a45', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'What is the basic SI unit of SPEED?', 'The standard SI unit of distance is metre (m) and time is second (s), making the SI unit of speed m/s.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35eece72-0197-4f3e-9ebf-bde04b322498', 'Metre per second (m/s)', true, '7be7e457-8871-4a64-a80b-edb8d5312a45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa10b788-c83d-4fc8-94b1-207480c192ea', 'Kilometre per hour (km/h)', false, '7be7e457-8871-4a64-a80b-edb8d5312a45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('882fb905-0d81-43a7-b409-88d13b0e88a1', 'Metre per minute', false, '7be7e457-8871-4a64-a80b-edb8d5312a45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f56e0d43-e2db-419c-9b9e-7388a3cfdb1b', 'Centimetre per second', false, '7be7e457-8871-4a64-a80b-edb8d5312a45');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f20a91e-69a5-4595-b539-c22c69ebf07b', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'What is the basic SI unit of TIME?', 'The International System of Units (SI) base unit of time is the second (s).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4200add-a2eb-48a7-b598-d72189dd3ff4', 'Second (s)', true, '7f20a91e-69a5-4595-b539-c22c69ebf07b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7788185c-ce99-432e-9af9-57038395bc88', 'Minute (min)', false, '7f20a91e-69a5-4595-b539-c22c69ebf07b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a7b248a-253b-4f67-ac4f-a321e5b27244', 'Hour (h)', false, '7f20a91e-69a5-4595-b539-c22c69ebf07b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a0dc3c9-f490-480a-97ea-d52f627f4dc2', 'Day', false, '7f20a91e-69a5-4595-b539-c22c69ebf07b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e869404-3774-4325-950d-2c8653d4fb0d', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'What type of motion occurs when an object moves along a straight line with a CONSTANT speed?', 'Uniform rectilinear motion is motion in a straight path with invariant constant speed.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3f79fcd-8ec2-41c5-9376-67bf718cf320', 'Uniform Motion', true, '4e869404-3774-4325-950d-2c8653d4fb0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35758edd-419e-4004-b233-9c7438e1bae2', 'Non-uniform Motion', false, '4e869404-3774-4325-950d-2c8653d4fb0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c25eb2c5-af1c-4a14-b68f-460026a9e6a2', 'Circular Motion', false, '4e869404-3774-4325-950d-2c8653d4fb0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dff97a8e-cf0d-4886-92fe-6a3e94e68147', 'Periodic Motion', false, '4e869404-3774-4325-950d-2c8653d4fb0d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea5e434c-93e4-40ca-95be-a9478462e427', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'What is the to-and-fro oscillatory motion of a Simple Pendulum an example of?', 'A simple pendulum executes periodic oscillatory motion, repeating identical cycles at equal regular intervals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eeb39b72-7ab1-458c-8f9f-65e9c0e0de8c', 'Periodic Motion (or Oscillatory Motion)', true, 'ea5e434c-93e4-40ca-95be-a9478462e427');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0afb9105-856d-49c4-8c9f-570c552c68b0', 'Rectilinear Motion', false, 'ea5e434c-93e4-40ca-95be-a9478462e427');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('103ff4c6-b4a1-408b-a9ee-ce0f5952c65b', 'Rotational Motion', false, 'ea5e434c-93e4-40ca-95be-a9478462e427');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a284687c-c539-4baa-ba60-9e03018a6009', 'Random Motion', false, 'ea5e434c-93e4-40ca-95be-a9478462e427');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bbc7d509-70a2-43e0-8c24-ebe018266dae', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'What is the time taken by a pendulum to complete ONE FULL OSCILLATION called?', 'The Time Period of a pendulum is the duration required for one complete to-and-fro cycle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('800d6bfe-1453-4508-826d-791bf2d5aca3', 'Time Period (T)', true, 'bbc7d509-70a2-43e0-8c24-ebe018266dae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a109cc09-88d1-44d9-9b9f-419d363a8f64', 'Frequency', false, 'bbc7d509-70a2-43e0-8c24-ebe018266dae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91ae16eb-b75f-4d35-b2f8-1d037353d611', 'Amplitude', false, 'bbc7d509-70a2-43e0-8c24-ebe018266dae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('273981e5-cc8a-4b33-9be0-4be1845fc739', 'Speed', false, 'bbc7d509-70a2-43e0-8c24-ebe018266dae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6a5a4744-ebca-4cf3-8c4f-d7e548ee7282', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'Which ancient astronomical time-measuring instrument at Jantar Mantar (New Delhi and Jaipur) measures time by tracking the moving shadow of the Sun cast on a calibrated dial?', 'A sundial uses the gnomon''s solar shadow cast across graduated hour arcs to track solar time.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('549092d3-2df0-4935-8ab9-e10f4e6ff05d', 'Sundial (e.g. Samrat Yantra)', true, '6a5a4744-ebca-4cf3-8c4f-d7e548ee7282');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a73eca07-c120-4504-82a3-db9468c2685f', 'Water clock', false, '6a5a4744-ebca-4cf3-8c4f-d7e548ee7282');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ef70359-0042-4c55-9d68-0d64f167f21a', 'Sand hourglass', false, '6a5a4744-ebca-4cf3-8c4f-d7e548ee7282');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f669363e-a95d-4d47-9f9e-9a7478ee137a', 'Pendulum clock', false, '6a5a4744-ebca-4cf3-8c4f-d7e548ee7282');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77cf4ca6-689e-4db2-ad1e-f94508679754', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'Which dashboard instrument in automobiles records and indicates the INSTANTANEOUS speed of the vehicle in km/h?', 'A speedometer measures and displays the vehicle''s instantaneous travel speed in km/h.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95b65ba0-1133-40e4-9c0e-8549265ba67a', 'Speedometer', true, '77cf4ca6-689e-4db2-ad1e-f94508679754');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da49ac8b-0fff-4b27-ad56-f94d9163cfc0', 'Odometer', false, '77cf4ca6-689e-4db2-ad1e-f94508679754');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf3cafe2-a604-4aeb-b08a-9cca61d3e1cf', 'Thermometer', false, '77cf4ca6-689e-4db2-ad1e-f94508679754');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7fcd4ca-7c28-4798-ac96-c0a7de212f59', 'Barometer', false, '77cf4ca6-689e-4db2-ad1e-f94508679754');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c46f4190-b1ad-4c3d-9d9d-82fd11da19d0', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'Which vehicle dashboard instrument measures and displays the TOTAL DISTANCE traveled by the vehicle in kilometres?', 'An odometer (mileometer) computes total cumulative vehicular distance in kilometres.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a80c97b-eb8d-47cc-896d-8360f0a59fde', 'Odometer', true, 'c46f4190-b1ad-4c3d-9d9d-82fd11da19d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bee41e8-f8e5-44ab-bb7d-d19fc60c589b', 'Speedometer', false, 'c46f4190-b1ad-4c3d-9d9d-82fd11da19d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cb55a31-edaa-441a-ba86-a5e652d3dc9a', 'Altimeter', false, 'c46f4190-b1ad-4c3d-9d9d-82fd11da19d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07e1d69a-f24a-487f-8fd7-ddf8bd3fc2d6', 'Chronometer', false, 'c46f4190-b1ad-4c3d-9d9d-82fd11da19d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dfcbc7f4-43e3-4f41-a9f8-5f19c17f86a1', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'A car covers a distance of 100 km in 2 hours. What is the average speed of the car?', 'Average speed = Total distance / Total time = 100 km / 2 h = 50 km/h.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d01a4369-ed06-45e8-ab99-3dad83b70b09', '50 km/h (Speed = 100 km / 2 h = 50 km/h)', true, 'dfcbc7f4-43e3-4f41-a9f8-5f19c17f86a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e50ce2f4-5476-42ab-907d-9084fa8f4281', '200 km/h', false, 'dfcbc7f4-43e3-4f41-a9f8-5f19c17f86a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24ceab58-3c08-46a3-9f54-f125b091452b', '25 km/h', false, 'dfcbc7f4-43e3-4f41-a9f8-5f19c17f86a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('665c9e83-e502-4736-9d39-01b8eac58353', '100 km/h', false, 'dfcbc7f4-43e3-4f41-a9f8-5f19c17f86a1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ba679cf-4345-4c13-abd4-258ee3e3adb0', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'What shape does the Distance-Time Graph of an object moving with CONSTANT UNIFORM SPEED have?', 'For constant speed, distance is directly proportional to time (d = v·t), yielding a straight linear slope on a distance-time graph.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16472080-421b-4866-ae36-b4272bc2912a', 'A straight straight inclined line passing through the origin', true, '1ba679cf-4345-4c13-abd4-258ee3e3adb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc75589b-46d1-4f75-9892-d74596b71a0c', 'A curved wavy line', false, '1ba679cf-4345-4c13-abd4-258ee3e3adb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c783bcbb-1b47-4c28-8ae7-982894752545', 'A circle', false, '1ba679cf-4345-4c13-abd4-258ee3e3adb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0f73d6f-3a08-4bfc-ac01-0bc72db48a44', 'A zig-zag line', false, '1ba679cf-4345-4c13-abd4-258ee3e3adb0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b7bbdb5-628b-49d6-95fb-9dd1e18178aa', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Easy', 'What does a HORIZONTAL FLAT LINE parallel to the time axis on a Distance-Time Graph represent?', 'Zero slope (horizontal line) indicates distance remains constant as time elapses, meaning speed = 0 (object at rest).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40824a6d-035a-4e48-86f6-a56a787f29fd', 'The object is stationary (at rest / not moving)', true, '9b7bbdb5-628b-49d6-95fb-9dd1e18178aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73a13991-8a32-497d-84fe-54b20b4c383f', 'The object is moving at light speed', false, '9b7bbdb5-628b-49d6-95fb-9dd1e18178aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8a5c16e-c5b3-47ea-8f1f-bfe7adfe2887', 'The object is moving backwards', false, '9b7bbdb5-628b-49d6-95fb-9dd1e18178aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f05a008a-d8cc-4073-87af-8ad9cca75d0b', 'The object is accelerating', false, '9b7bbdb5-628b-49d6-95fb-9dd1e18178aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa957e97-af35-4b00-bd7b-869ebcc6a336', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'Which famous Italian scientist discovered that a pendulum of a given length always takes the EXACT SAME TIME to complete one oscillation (Isochronism of the Pendulum)?', 'Galileo observed swinging cathedral chandeliers and proved that pendulum period depends solely on length, independent of mass or small amplitude.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5938a408-35ad-4299-960a-1aa98a7630e7', 'Galileo Galilei (in 1583)', true, 'aa957e97-af35-4b00-bd7b-869ebcc6a336');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5ab1f78-3d20-4956-b891-1060c1f25ab4', 'Isaac Newton', false, 'aa957e97-af35-4b00-bd7b-869ebcc6a336');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cef16c8-9d63-4957-acba-1f2441f97262', 'Albert Einstein', false, 'aa957e97-af35-4b00-bd7b-869ebcc6a336');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95799f36-5384-4e5e-9768-e8ca745a0b0f', 'René Laennec', false, 'aa957e97-af35-4b00-bd7b-869ebcc6a336');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f2a8f871-e94d-416d-8124-33c80dbdba31', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'A simple pendulum takes 32 seconds to complete 20 full oscillations. What is the TIME PERIOD of the pendulum?', 'Time period T = 32 s / 20 = 1.6 seconds per oscillation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c13ea1e2-9af2-4b7d-8022-10d45ef5036f', '1.6 seconds (Time Period = Total time / Number of oscillations = 32 / 20 = 1.6 s)', true, 'f2a8f871-e94d-416d-8124-33c80dbdba31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('111f12c3-8a16-456c-83ec-564292ef0c38', '0.625 s', false, 'f2a8f871-e94d-416d-8124-33c80dbdba31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53160570-4462-46a7-a9dd-14a210861709', '640 s', false, 'f2a8f871-e94d-416d-8124-33c80dbdba31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('320a12eb-7b85-4fcb-aadb-e435efc33b3b', '2.0 s', false, 'f2a8f871-e94d-416d-8124-33c80dbdba31');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bdb1e784-423e-406f-8c40-179ab26369a4', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'Convert a speed of 72 km/h into metres per second (m/s):', 'Conversion factor: 1 km/h = 5/18 m/s. 72 × (5/18) = 20 m/s.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('292c699d-5cae-4728-b70f-b75e6922a03f', '20 m/s (72 × (5 / 18) = 4 × 5 = 20 m/s)', true, 'bdb1e784-423e-406f-8c40-179ab26369a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82a459d2-3e0a-4167-9bee-1e09020bf3e0', '25 m/s', false, 'bdb1e784-423e-406f-8c40-179ab26369a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51e92aae-3ace-4165-9514-9e166b7cc792', '15 m/s', false, 'bdb1e784-423e-406f-8c40-179ab26369a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('246566b7-31d1-480b-93fe-adbb01e8356c', '30 m/s', false, 'bdb1e784-423e-406f-8c40-179ab26369a4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55032a41-7529-4afb-885e-238d45dbc711', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'Convert a speed of 15 m/s into kilometres per hour (km/h):', 'Conversion factor: 1 m/s = 18/5 km/h. 15 × (18/5) = 54 km/h.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78e27c91-47b0-4242-a326-2d0c27253f17', '54 km/h (15 × (18 / 5) = 3 × 18 = 54 km/h)', true, '55032a41-7529-4afb-885e-238d45dbc711');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba75aaab-ecb8-4476-a4c2-4c3be3b2c708', '60 km/h', false, '55032a41-7529-4afb-885e-238d45dbc711');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71750b0f-49e5-4c1f-ab00-72b885acf723', '45 km/h', false, '55032a41-7529-4afb-885e-238d45dbc711');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecc0fe11-efb6-40bf-a754-87c616244c3f', '50 km/h', false, '55032a41-7529-4afb-885e-238d45dbc711');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('268cbdb1-6a44-4079-a7ca-329347a38c1b', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'A train is traveling at a speed of 90 km/h. How much distance in kilometres will it cover in 20 minutes?', '20 min = 1/3 h. Distance = 90 km/h × 1/3 h = 30 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5104324f-49fc-4b5c-a1a4-bd23dd399cff', '30 km (Time = 20/60 h = 1/3 h ; Distance = 90 × (1/3) = 30 km)', true, '268cbdb1-6a44-4079-a7ca-329347a38c1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b7f3b7f-2853-4906-aafd-4598efe506f9', '45 km', false, '268cbdb1-6a44-4079-a7ca-329347a38c1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('062b7436-885c-4bd1-9efe-3a63b5b56da8', '25 km', false, '268cbdb1-6a44-4079-a7ca-329347a38c1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c26a995b-22a7-40a7-8599-e6f20f293abb', '60 km', false, '268cbdb1-6a44-4079-a7ca-329347a38c1b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4c79a82-e660-4ad6-a73a-87558e1e2b81', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'The odometer of a car reads 57321.0 km at 08:30 AM. At 08:50 AM, the odometer reading increases to 57336.0 km. Calculate the speed of the car in km/min and km/h:', 'Δd = 15 km, Δt = 20 min (1/3 h). Speed = 15/20 = 0.75 km/min = 45 km/h.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3aea3430-7b7d-48ca-b71b-f3763f231982', '0.75 km/min and 45 km/h (Distance = 15 km ; Time = 20 min = 1/3 h ; Speed = 15 / 20 = 0.75 km/min ; Speed = 15 / (1/3) = 45 km/h)', true, 'e4c79a82-e660-4ad6-a73a-87558e1e2b81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('733e17a9-2551-4f34-abc1-7b9c34b4f796', '0.5 km/min and 30 km/h', false, 'e4c79a82-e660-4ad6-a73a-87558e1e2b81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb483c8b-9230-4e60-b5c6-615eb309ced7', '1.0 km/min and 60 km/h', false, 'e4c79a82-e660-4ad6-a73a-87558e1e2b81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e681763-e02b-4ee7-85e6-871af90b19aa', '0.8 km/min and 48 km/h', false, 'e4c79a82-e660-4ad6-a73a-87558e1e2b81');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('464df1a5-be9a-4a9f-824b-48bf135d3ece', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'Salma takes 15 minutes from her house to reach her school on a bicycle. If the bicycle has a speed of 2 m/s, calculate the distance between her house and school in metres and kilometres:', 'Time = 15 × 60 = 900 s. Distance = 2 m/s × 900 s = 1800 m = 1.8 km.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a5c0948-e862-4286-b3b5-bcb48501cf72', '1,800 m or 1.8 km (Time = 15 × 60 = 900 s ; Distance = 2 m/s × 900 s = 1,800 m = 1.8 km)', true, '464df1a5-be9a-4a9f-824b-48bf135d3ece');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08a8d5be-b4c6-4096-a0cf-f2878a304309', '1,200 m or 1.2 km', false, '464df1a5-be9a-4a9f-824b-48bf135d3ece');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef8d5861-c7ea-4424-90f8-8eef56cdb70d', '2,400 m or 2.4 km', false, '464df1a5-be9a-4a9f-824b-48bf135d3ece');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55dc3a73-a3a4-473b-92b0-a52b0ca7cf62', '1,500 m or 1.5 km', false, '464df1a5-be9a-4a9f-824b-48bf135d3ece');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5dd75376-d31e-4570-a889-bfee5d3b9bee', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'How do modern electronic Quartz Clocks and wristwatches measure time with extreme precision?', 'Piezoelectric quartz crystals oscillate at precisely 32,768 Hz when energized, providing accurate electronic frequency division.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('569873e4-2a53-4cfb-bc11-c109d93b4d2e', 'They contain a micro-electric circuit driven by the extremely steady, high-frequency piezoelectric vibrations of a tiny Quartz Crystal (32,768 Hz)', true, '5dd75376-d31e-4570-a889-bfee5d3b9bee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2772f5fa-0f9c-48fa-a176-8bda40ae4909', 'They have tiny gears moved by running water', false, '5dd75376-d31e-4570-a889-bfee5d3b9bee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d63b02a2-2f3e-443b-8882-d6d34402bb29', 'They contain tiny burning candles', false, '5dd75376-d31e-4570-a889-bfee5d3b9bee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3cec06d-8a42-4746-9a98-85f49b12fed0', 'They track shadows inside the watch', false, '5dd75376-d31e-4570-a889-bfee5d3b9bee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25d53d1a-10d8-44da-a1e4-858038c3b5b0', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'What physical property determines the Time Period of a simple pendulum?', 'Period T depends only on pendulum length L and gravitational acceleration g (T = 2π√(L/g)).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('410f2a0e-8e5b-4674-8542-0c6ea4d5c781', 'The LENGTH of the pendulum string (T = 2π√(L/g)) ; it is independent of the mass of the bob or small amplitude swings', true, '25d53d1a-10d8-44da-a1e4-858038c3b5b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81fef9db-13e2-49db-bb73-c12c2745cf54', 'The color of the bob', false, '25d53d1a-10d8-44da-a1e4-858038c3b5b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f44ecc1-e331-4ede-a503-1fcd4619f5d1', 'The heaviness of the bob only', false, '25d53d1a-10d8-44da-a1e4-858038c3b5b0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98de451a-b607-46f3-ad19-62ba2ded8e0f', 'The room temperature', false, '25d53d1a-10d8-44da-a1e4-858038c3b5b0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('960e39f3-478f-49f8-a286-610463c8173b', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'What does a CURVED line with increasing steepness on a Distance-Time Graph indicate?', 'A convex ascending curve shows that distance increases at an accelerating rate per unit time, indicating acceleration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b6eb567-fbf7-471b-93ef-75db9b69ef70', 'Non-uniform motion with accelerating (increasing) speed', true, '960e39f3-478f-49f8-a286-610463c8173b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64aeadf6-cbab-4d12-89c7-e2a8fc32bc5a', 'Uniform constant speed', false, '960e39f3-478f-49f8-a286-610463c8173b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fc0184f-ad91-4e16-9c86-8747aef6cca7', 'The object is at rest', false, '960e39f3-478f-49f8-a286-610463c8173b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4875abc5-91c0-4013-bc00-d4d38f32299a', 'The object is going backwards in time', false, '960e39f3-478f-49f8-a286-610463c8173b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e3dd648-d609-4cdc-957e-7a5f934d18f0', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'Which of the following natural events was used by ancient humans to measure a ''MONTH''?', 'Synodic lunar month: the 29.53-day cycle between successive new moons formed the basis of calendar months.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ceecb626-ea1b-45e9-941e-df4177ef98a8', 'The time between one New Moon and the NEXT New Moon (Lunar Cycle ~ 29.5 days)', true, '4e3dd648-d609-4cdc-957e-7a5f934d18f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a778da1-13c0-4939-bd63-c9419de28871', 'The time between one sunrise and the next', false, '4e3dd648-d609-4cdc-957e-7a5f934d18f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b0c25d2-c000-4529-b4c5-b12af859b0fd', 'The time taken for a tree to grow fruit', false, '4e3dd648-d609-4cdc-957e-7a5f934d18f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36abbbad-a8d8-4715-aac4-291dcef6febd', 'The time taken for a river to dry', false, '4e3dd648-d609-4cdc-957e-7a5f934d18f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d5e2d20e-ff78-4eac-8a3d-949fc22167e5', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'Which of the following natural events was used by ancient humans to measure a ''YEAR''?', 'The solar year is defined by Earth''s heliocentric orbital revolution (~365.25 days) governing the annual return of seasons.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e59039e2-d25f-4c23-8189-fe24f9fe7fef', 'The time taken by the Earth to complete one full revolution around the Sun (approx. 365 1/4 days, marked by seasonal cycles)', true, 'd5e2d20e-ff78-4eac-8a3d-949fc22167e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72cbb253-9ec1-4284-9da9-d663fefc46b4', 'The time between morning and evening', false, 'd5e2d20e-ff78-4eac-8a3d-949fc22167e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3651f1d-2b9d-46b6-a198-2f124efd0b80', 'The duration of a single rainfall', false, 'd5e2d20e-ff78-4eac-8a3d-949fc22167e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cecd98d-f0db-457c-ab24-11e515094b77', 'The life of a flower', false, 'd5e2d20e-ff78-4eac-8a3d-949fc22167e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('00d753d2-ac4a-4996-90e7-ba3a5ce17d79', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'A rocket travels at a speed of 8 km/s. How much time will it take to reach a satellite stationed 36,000 km away in orbit?', 'Time = 36,000 km / 8 km/s = 4500 seconds (75 minutes / 1.25 hours).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0aeacdb5-adc3-43b0-a2d6-7e09e6193c02', '4,500 seconds or 1.25 hours (Time = 36,000 / 8 = 4,500 s = 75 min = 1.25 h)', true, '00d753d2-ac4a-4996-90e7-ba3a5ce17d79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88ab12eb-7980-4647-8f6f-9b810e969a35', '3,600 seconds', false, '00d753d2-ac4a-4996-90e7-ba3a5ce17d79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d99c147-4adb-46bf-975b-431bb69a21a3', '4,000 seconds', false, '00d753d2-ac4a-4996-90e7-ba3a5ce17d79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e873c72-0ba5-4b82-9393-b38768dee5fa', '5,000 seconds', false, '00d753d2-ac4a-4996-90e7-ba3a5ce17d79');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('896d2556-c7a5-4f09-9f2d-b4785e8bbd71', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'If two cars A and B are moving in the same direction, and on a Distance-Time graph the line for Car A is STEEPER than the line for Car B, what does this conclude?', 'Slope of distance-time graph = Δd/Δt = Speed. Greater slope signifies higher velocity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bef03cb-8701-4137-806e-94be3ce73b0c', 'Car A is moving FASTER than Car B (Steeper slope = Higher speed)', true, '896d2556-c7a5-4f09-9f2d-b4785e8bbd71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ae239f8-e2b4-4ad4-9a17-fe33c7f6c740', 'Car B is faster than Car A', false, '896d2556-c7a5-4f09-9f2d-b4785e8bbd71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0ab5929-56fb-4f1e-889b-7de871c3975e', 'Both cars have equal speed', false, '896d2556-c7a5-4f09-9f2d-b4785e8bbd71');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63263f23-0dde-451b-9217-4edbee9db920', 'Car A has stopped moving', false, '896d2556-c7a5-4f09-9f2d-b4785e8bbd71');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a3fe907c-1402-4607-aedf-61badb2c9e15', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'What is the speed of a cheetah that runs a distance of 100 metres in exactly 4 seconds?', 'Speed = 100 m / 4 s = 25 m/s = 25 × 3.6 = 90 km/h.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd48eb82-7b31-4e3e-8c76-fbacd90a8068', '25 m/s or 90 km/h (Speed = 100 / 4 = 25 m/s ; 25 × (18/5) = 90 km/h)', true, 'a3fe907c-1402-4607-aedf-61badb2c9e15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ace19c8-b7f9-4fac-9c04-87f2a4a00206', '20 m/s or 72 km/h', false, 'a3fe907c-1402-4607-aedf-61badb2c9e15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f78c0234-d919-4412-a83c-4add7738d020', '30 m/s or 108 km/h', false, 'a3fe907c-1402-4607-aedf-61badb2c9e15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73c3e75a-cf26-4c9a-ac0f-228a173175da', '15 m/s or 54 km/h', false, 'a3fe907c-1402-4607-aedf-61badb2c9e15');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52fedad8-952b-4171-9745-3554e62aba1e', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Medium', 'What is the speed of sound in dry air at room temperature (approx. 20°C)?', 'The acoustic velocity of sound in dry air at 20°C is approximately 343 m/s (1,235 km/h).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab644885-8c67-4979-88e4-bc4b134d8b97', 'Approx. 343 m/s (approx. 1,235 km/h)', true, '52fedad8-952b-4171-9745-3554e62aba1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('242ae854-96b3-45e5-845d-b71ee8597cc9', '3,000 m/s', false, '52fedad8-952b-4171-9745-3554e62aba1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c6bc352-10f0-4d7e-b6bc-83397ed4fd3d', '30 m/s', false, '52fedad8-952b-4171-9745-3554e62aba1e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c72fe5e0-f538-44fc-96ef-8be49aaaea29', '300,000 km/s', false, '52fedad8-952b-4171-9745-3554e62aba1e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e3835096-2dd3-4983-824b-b6443921ff33', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee87dca0-338f-4b54-a15b-5236718d9013', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'e3835096-2dd3-4983-824b-b6443921ff33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fb08969-e308-4fa4-bf9b-759553a68637', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'e3835096-2dd3-4983-824b-b6443921ff33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c7c4c81-0e4d-4d8f-b7f7-70ef98c713f4', '(A) is true, but (R) is false.', false, 'e3835096-2dd3-4983-824b-b6443921ff33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14e3e004-ed17-4b4c-90cc-53776057461c', '(A) is false, but (R) is true.', false, 'e3835096-2dd3-4983-824b-b6443921ff33');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d662bbae-2334-4085-8ad9-5a65d5a0ab83', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'Spot the IMPOSTER in the following group of Time-Measuring Devices and their operating principles:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e835635c-9e57-479c-9c3c-0fefc9fcae6e', 'Device 1', false, 'd662bbae-2334-4085-8ad9-5a65d5a0ab83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70047d65-c472-4f06-91d7-4f53e9dbae14', 'Device 2', false, 'd662bbae-2334-4085-8ad9-5a65d5a0ab83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36b6ffb7-a3b3-4834-8bc6-779da57276e7', 'Device 3', false, 'd662bbae-2334-4085-8ad9-5a65d5a0ab83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c47500e3-1e47-4e69-979d-a7159e2e2d10', 'Device 4 (A simple pendulum uses MECHANICAL GRAVITATIONAL HARMONIC OSCILLATION, not burning gunpowder)', true, 'd662bbae-2334-4085-8ad9-5a65d5a0ab83');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3af65540-57cc-4612-93d8-15b16af3bc77', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'If a simple pendulum of length L has a time period of 2.0 seconds, what will happen to its time period if its length is increased by FOUR TIMES (4L)?', 'Formula T = 2π√(L/g). If length becomes 4L, new period T'' = √(4) × T = 2 × 2.0 = 4.0 s.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32f6a0bf-ec30-40a4-95ab-55acc85a36dc', 'The time period will DOUBLE to 4.0 seconds (Since T ∝ √L, T'' = √(4) × T = 2 × 2.0 = 4.0 s)', true, '3af65540-57cc-4612-93d8-15b16af3bc77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14feec74-32bf-4b25-8ffe-0f9336ec6b8f', 'The time period will quadruple to 8.0 s', false, '3af65540-57cc-4612-93d8-15b16af3bc77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c257060-a6a9-4daa-8739-318eb07418e3', 'The time period will reduce to 1.0 s', false, '3af65540-57cc-4612-93d8-15b16af3bc77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('038495a1-483f-4591-8924-9524d357c155', 'The time period remains unchanged at 2.0 s', false, '3af65540-57cc-4612-93d8-15b16af3bc77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('daada5dc-ee46-4bba-92cb-17ec005cef6e', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'Match Column I (Speed & Time Concepts) with Column II (Exact Definitions & Formulas):
(a) Speedometer          -> (i) Instantaneous vehicular speed in km/h
(b) Odometer             -> (ii) Cumulative distance traversed in km
(c) Slope of D-T Graph   -> (iii) Rate of change of distance yielding speed
(d) Atomic Clock (Cesium)-> (iv) Ultra-precise atomic microwave resonance (loss < 1 sec in millions of years)', 'Speedometer = instantaneous speed; Odometer = distance; Slope = speed; Cesium clock = atomic frequency standard.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2620de21-231b-44df-8dc0-cf9b3f70a46c', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'daada5dc-ee46-4bba-92cb-17ec005cef6e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('215bfb8c-6b0c-4090-a9ef-f37d5969da0c', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'daada5dc-ee46-4bba-92cb-17ec005cef6e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e8cfb98-9b78-4777-905a-040398502aa1', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'daada5dc-ee46-4bba-92cb-17ec005cef6e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50c2965d-ab4a-4816-9b5c-492d86a1bab2', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'daada5dc-ee46-4bba-92cb-17ec005cef6e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d2337644-abff-4ecb-9261-8449235a5bd6', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'Read the statements regarding kinematics:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3576edb-159d-4af9-9578-d1eccca5ed63', 'Statements 1 and 2 only', true, 'd2337644-abff-4ecb-9261-8449235a5bd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bae58ccc-d2cf-49fe-bbd5-a3185d428bfd', 'Statements 2 and 3 only', false, 'd2337644-abff-4ecb-9261-8449235a5bd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d25b1984-cff7-40d3-977d-d7227be320ee', 'Statements 1 and 3 only', false, 'd2337644-abff-4ecb-9261-8449235a5bd6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a63f9f33-461d-4613-bd70-0bb9673043ac', 'All Statements 1, 2, and 3', false, 'd2337644-abff-4ecb-9261-8449235a5bd6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('608cc963-89f3-4629-b715-617b9d9a8e64', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'A bus travels the first 30 km of its trip at a uniform speed of 30 km/h, and the next 30 km at a uniform speed of 60 km/h. What is the AVERAGE SPEED of the bus for the entire 60 km journey?', 'Harmonic average speed: Total distance (60 km) / Total time (1.5 h) = 40 km/h (NEVER arithmetic average (30+60)/2=45).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4117727-afb4-4a8f-8e13-8dd741b8a334', '40 km/h (Total Distance = 60 km ; Time 1 = 30/30 = 1 h ; Time 2 = 30/60 = 0.5 h ; Total Time = 1.5 h ; Avg Speed = 60 / 1.5 = 40 km/h)', true, '608cc963-89f3-4629-b715-617b9d9a8e64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33df2c6f-5944-4075-be36-1e1ccf35f43c', '45 km/h (Arithmetic mean error)', false, '608cc963-89f3-4629-b715-617b9d9a8e64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8896014e-4937-4d24-b84c-db5fc71f4e7f', '50 km/h', false, '608cc963-89f3-4629-b715-617b9d9a8e64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f66a9609-e0be-49a5-81f1-c54c66a89495', '35 km/h', false, '608cc963-89f3-4629-b715-617b9d9a8e64');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27275a2f-bc54-4c46-9cc2-a8b11f01fecc', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'Why do international scientific metrology standards define 1 Second using the Cesium-133 Atomic Clock rather than astronomical earth rotation?', 'SI second is defined by 9,192,631,770 hyperfine transitions of Cs-133 ground state, eliminating planetary rotational perturbations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ea8b35e-6222-483e-bd31-398ca49f6e05', 'Earth''s orbital rotation experiences slight irregularities due to tidal friction and mass redistribution, whereas the Cesium-133 atomic hyperfine transition frequency (9,192,631,770 Hz) is invariant and absolute', true, '27275a2f-bc54-4c46-9cc2-a8b11f01fecc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a89a8ceb-e0da-4dd1-9e3f-cf5f75b4966c', 'Because watches run out of batteries', false, '27275a2f-bc54-4c46-9cc2-a8b11f01fecc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00d4a371-488e-43af-9239-cc768e1e9679', 'Because the Sun is cooling down', false, '27275a2f-bc54-4c46-9cc2-a8b11f01fecc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1df283c-2fe5-42ce-ab11-3bb3670c6384', 'Because the moon is drifting away', false, '27275a2f-bc54-4c46-9cc2-a8b11f01fecc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9746e31b-d830-4237-ba81-2dceea60d637', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'Consider four kinematic events:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('033bbaac-bd4b-4025-a386-52387b917e78', 'Events 2 and 4 only', true, '9746e31b-d830-4237-ba81-2dceea60d637');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f82006a8-697b-4963-8187-5e717747f92a', 'Events 1 and 3 only', false, '9746e31b-d830-4237-ba81-2dceea60d637');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b703dc4e-8189-491e-a97c-b1fa0afe3676', 'Events 1, 2, and 4 only', false, '9746e31b-d830-4237-ba81-2dceea60d637');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54ccd514-8757-40d0-bf91-e0aaa62205d4', 'All 1, 2, 3, and 4', false, '9746e31b-d830-4237-ba81-2dceea60d637');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('736e0323-264f-47f8-b407-8c30cc7b40dc', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'What mathematical property explains why a Simple Pendulum''s time period remains CONSTANT even if its bob''s mass is increased from 50 g to 500 g?', 'Equivalence principle: gravitational mass equals inertial mass, so acceleration and period are strictly mass-independent.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e968a11-143f-42da-a680-5d416f9b94c9', 'In the pendulum equation T = 2π√(L/g), mass ''m'' does not appear; inertial resistance cancels gravitational restoring force identically for all masses', true, '736e0323-264f-47f8-b407-8c30cc7b40dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('144cdb0b-f90f-4b3d-bccb-24812ee57ab3', 'Because larger mass makes the pendulum longer', false, '736e0323-264f-47f8-b407-8c30cc7b40dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('486fdb97-8ca1-4ca4-b6e1-95a5c5a8a161', 'Because heavier bob pushes air away', false, '736e0323-264f-47f8-b407-8c30cc7b40dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c446682-64e6-48df-b8a0-a969568cda2b', 'Because gravity acts only on light objects', false, '736e0323-264f-47f8-b407-8c30cc7b40dc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ca83495-6e53-42b0-861c-e2e9f7638db1', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'If the Distance-Time graph of a moving vehicle is a straight line sloping DOWNWARDS from left to right, what does it signify?', 'Negative displacement slope indicates uniform return motion reducing distance relative to the frame of reference.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b021457-85eb-456c-8a37-682f6708d2c6', 'The vehicle is returning back towards the starting reference origin point at a uniform speed', true, '1ca83495-6e53-42b0-861c-e2e9f7638db1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7800bcb2-2cfe-45e0-ae63-bb939c88c3ca', 'The vehicle has negative mass', false, '1ca83495-6e53-42b0-861c-e2e9f7638db1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('162dca7f-0146-42e9-b37f-85e844a4a8b4', 'Time is moving backwards', false, '1ca83495-6e53-42b0-861c-e2e9f7638db1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5fc9c0f-941a-424c-9938-2d5f45bb66ce', 'The car is falling off a cliff', false, '1ca83495-6e53-42b0-861c-e2e9f7638db1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('21f503cf-6442-4dad-8e4d-4800615b5fde', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'How does GPS (Global Positioning System) navigation calculate a car''s real-time position and speed?', 'GPS trilateration measures nanosecond radio signal transit delays (d = c·Δt) from ≥4 atomic satellite clocks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fa54436-b03e-4b74-94cf-8bee6c43f1cd', 'By calculating precise time-of-flight radio signal delays from atomic clocks aboard multiple orbiting GPS satellites to triangulate position and velocity', true, '21f503cf-6442-4dad-8e4d-4800615b5fde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a600497-2679-4943-9fbd-3acc0b0e6ba5', 'By taking photos of road signs', false, '21f503cf-6442-4dad-8e4d-4800615b5fde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4712b38-c180-4ff4-b435-32e73b1f142f', 'By measuring air pressure around wheels', false, '21f503cf-6442-4dad-8e4d-4800615b5fde');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2dc47e5-cef3-426e-92d6-ce89d3b0caaa', 'By counting wheel revolutions only', false, '21f503cf-6442-4dad-8e4d-4800615b5fde');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6a44b15-5709-41e2-a1a8-9d39b9d73a2b', 'Class 7', 'Science', 'Chapter 9: Motion and Time', 'Hard', 'What master scientific principle is established in Chapter 9 of NCERT Class 7 Science?', 'Chapter 9 establishes fundamental kinematics: scalar rates, periodic isochronism, metrology history, and Cartesian graphical analysis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c55f1d8-e3f6-4b3b-980e-f9094973ccbd', 'Quantitative measurement of physical motion and temporal duration—from ancient shadow gnomons and pendulums to modern quartz oscillators and graphical kinematics—forms the bedrock of physics, astronomy, technology, and navigation', true, 'e6a44b15-5709-41e2-a1a8-9d39b9d73a2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('584139b6-454b-4317-b3e6-3b3b4edfd0d2', 'That time cannot be measured accurately', false, 'e6a44b15-5709-41e2-a1a8-9d39b9d73a2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a2a6065-0664-4d5f-9651-deff556f97c8', 'That speed is always random', false, 'e6a44b15-5709-41e2-a1a8-9d39b9d73a2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f23d2ee-90f2-4eea-a34a-170f5eb1a114', 'That clocks only work when someone watches them', false, 'e6a44b15-5709-41e2-a1a8-9d39b9d73a2b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba39b8f9-0acf-4722-ac27-4e249b286c6a', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'What is the formula for finding the PERIMETER of a Rectangle of length l and breadth b?', 'Rectangle perimeter P = 2(length + breadth).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('678a6744-0cde-4f66-9ff6-b973f517b9b2', 'Perimeter = 2 × (l + b)', true, 'ba39b8f9-0acf-4722-ac27-4e249b286c6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11fd997f-54dd-4a72-a6ea-f9f3d0998cc9', 'Perimeter = l × b', false, 'ba39b8f9-0acf-4722-ac27-4e249b286c6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ea6d4e6-4498-4cd6-9865-9310aee04806', 'Perimeter = 4 × l', false, 'ba39b8f9-0acf-4722-ac27-4e249b286c6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6de57961-cfed-4bd0-b950-245d4e54ab2e', 'Perimeter = l + b', false, 'ba39b8f9-0acf-4722-ac27-4e249b286c6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3f07fa3f-17ed-47c7-bc0e-047c1cc0b20f', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'What is the formula for the AREA of a Square of side ''a''?', 'Area of a square = side × side = a².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a13bdbd1-4e24-419e-9da7-05554d9e0672', 'Area = a² (Side × Side)', true, '3f07fa3f-17ed-47c7-bc0e-047c1cc0b20f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72c64942-547d-4486-bf19-511c40f99e0e', 'Area = 4 × a', false, '3f07fa3f-17ed-47c7-bc0e-047c1cc0b20f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8641dbac-20c0-43a2-b038-c7843416b2b8', 'Area = 2 × a', false, '3f07fa3f-17ed-47c7-bc0e-047c1cc0b20f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63db6598-7d22-4d90-9066-438d973da864', 'Area = a / 4', false, '3f07fa3f-17ed-47c7-bc0e-047c1cc0b20f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1354da85-250a-4585-bbb4-6771d249d9ee', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'What is the formula for the AREA of a PARALLELOGRAM with base ''b'' and corresponding height ''h''?', 'Area of a parallelogram = base × corresponding height (b × h).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92d11b9d-130f-4a01-996a-4c4368b04303', 'Area = Base × Height (b × h)', true, '1354da85-250a-4585-bbb4-6771d249d9ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8f72029-d1b0-49b7-bdba-4bd3a580d330', 'Area = 1/2 × b × h', false, '1354da85-250a-4585-bbb4-6771d249d9ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('690cbc32-1d61-48db-92ff-17585950f9ef', 'Area = 2 × (b + h)', false, '1354da85-250a-4585-bbb4-6771d249d9ee');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9755a170-48aa-45d7-87cc-7cec3f15adcc', 'Area = b² × h', false, '1354da85-250a-4585-bbb4-6771d249d9ee');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f0c6bb31-4cc8-470f-9267-cf267b93bfd9', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'What is the formula for the AREA of a TRIANGLE with base ''b'' and height ''h''?', 'A triangle is half of a parallelogram, so Area = 1/2 × base × height.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ce838ad-3d50-4c0f-b485-9c7816bc848a', 'Area = 1/2 × Base × Height (1/2 × b × h)', true, 'f0c6bb31-4cc8-470f-9267-cf267b93bfd9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be3dd76f-1f2a-426d-9a82-ed90fb2b38ca', 'Area = b × h', false, 'f0c6bb31-4cc8-470f-9267-cf267b93bfd9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('553d2a33-034a-4bf3-aeeb-d91abe987592', 'Area = 2 × b × h', false, 'f0c6bb31-4cc8-470f-9267-cf267b93bfd9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c86af440-622f-479f-b694-466bcd9f841a', 'Area = (b + h) / 2', false, 'f0c6bb31-4cc8-470f-9267-cf267b93bfd9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b32eaf86-8848-4423-add7-878c643d78c9', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'What is the formula for the CIRCUMFERENCE (perimeter) of a circle of radius ''r'' (or diameter ''d'')?', 'Circumference of a circle C = 2πr = πd.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7c5ec8f-0e5d-4604-bcb1-fffe6e57c13a', 'Circumference = 2πr (or πd)', true, 'b32eaf86-8848-4423-add7-878c643d78c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea801e9c-dd92-43f2-adf6-60d1ea87e1af', 'Circumference = πr²', false, 'b32eaf86-8848-4423-add7-878c643d78c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fec102b8-f8b8-42ca-b1a7-4f9ae35d3cd0', 'Circumference = 4πr', false, 'b32eaf86-8848-4423-add7-878c643d78c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d76168a-9443-4c36-b17a-30eb736941a8', 'Circumference = 2πr²', false, 'b32eaf86-8848-4423-add7-878c643d78c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74afb1f8-1005-40b5-8682-721af3abd260', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'What is the formula for the AREA of a Circle of radius ''r''?', 'Area enclosed by a circle A = πr².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdec7533-ba69-443c-be58-02d224aa5487', 'Area = πr²', true, '74afb1f8-1005-40b5-8682-721af3abd260');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ae9dd96-d0de-4531-9cf5-1b7ecc3989da', 'Area = 2πr', false, '74afb1f8-1005-40b5-8682-721af3abd260');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abbacb28-cc01-48d3-ae5d-8af440c2edf4', 'Area = πd', false, '74afb1f8-1005-40b5-8682-721af3abd260');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea187e8e-509f-41d1-843a-8702de51f435', 'Area = 4πr²', false, '74afb1f8-1005-40b5-8682-721af3abd260');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0373808f-d15b-4559-873a-b266d938e06c', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'How many square metres (m²) are there in 1 HECTARE?', '1 hectare = 10,000 m² (a square of 100 m × 100 m).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3e1d189-a3a6-4bf6-83fa-095338b99f11', '10,000 m² (1 Hectare = 100 m × 100 m = 10,000 m²)', true, '0373808f-d15b-4559-873a-b266d938e06c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02976cfc-fdc0-44e9-b97e-c17c91efc417', '1,000 m²', false, '0373808f-d15b-4559-873a-b266d938e06c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a625ba8-e57c-4a1b-a6ae-a0fcb5cada5e', '100 m²', false, '0373808f-d15b-4559-873a-b266d938e06c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8bb32d5-3d0b-4fc0-b20d-50f12d4d6e81', '100,000 m²', false, '0373808f-d15b-4559-873a-b266d938e06c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97a8fa17-8eaf-45e3-b149-9ee017946980', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'Find the Circumference of a circle of radius 14 cm (Take π = 22/7):', 'C = 2 × (22/7) × 14 = 88 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b4d26e1-6095-4dbf-8af8-f07442a28db9', '88 cm (C = 2 × (22/7) × 14 = 2 × 22 × 2 = 88 cm)', true, '97a8fa17-8eaf-45e3-b149-9ee017946980');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41b388e2-2470-4349-b0de-5cd578a3b3b6', '44 cm', false, '97a8fa17-8eaf-45e3-b149-9ee017946980');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45bedf7c-3537-406f-bd31-b9d1448343f2', '176 cm', false, '97a8fa17-8eaf-45e3-b149-9ee017946980');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fdf807e-70ed-4e32-8030-e76ad43072bf', '616 cm', false, '97a8fa17-8eaf-45e3-b149-9ee017946980');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a954f662-029a-4113-a7fc-d7dacb1ec5b5', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'Find the Area of a circle of radius 7 cm (Take π = 22/7):', 'Area = (22/7) × 7² = 154 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdd783f6-6c7e-49aa-9d87-89d501a71a31', '154 cm² (Area = (22/7) × 7 × 7 = 154 cm²)', true, 'a954f662-029a-4113-a7fc-d7dacb1ec5b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd36eb60-1425-489d-8341-8d4af061dd89', '44 cm²', false, 'a954f662-029a-4113-a7fc-d7dacb1ec5b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c55a66c-ebc2-496f-a67b-a1496f98bb3d', '308 cm²', false, 'a954f662-029a-4113-a7fc-d7dacb1ec5b5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('befe9c29-0b98-4b43-be91-13b2020d5f55', '77 cm²', false, 'a954f662-029a-4113-a7fc-d7dacb1ec5b5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('32adb3fc-cf5d-4fbb-abbc-b9405211f465', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'Find the Area of a square park whose perimeter is 320 m:', 'Side = 320 / 4 = 80 m. Area = 80² = 6,400 m².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33b43b9e-4146-4002-9497-099c36b4e27e', '6,400 m² (Side = 320 / 4 = 80 m ; Area = 80 × 80 = 6,400 m²)', true, '32adb3fc-cf5d-4fbb-abbc-b9405211f465');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('936069f4-0da0-40bc-9f9b-5bc810130a5b', '3,200 m²', false, '32adb3fc-cf5d-4fbb-abbc-b9405211f465');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7805da1b-7c03-42de-9064-1ae582479c35', '1,600 m²', false, '32adb3fc-cf5d-4fbb-abbc-b9405211f465');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28c8c584-0192-4b70-8604-cafc90072b62', '8,000 m²', false, '32adb3fc-cf5d-4fbb-abbc-b9405211f465');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1db14b8a-3b0f-4218-83a8-fe6656760472', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'Find the Area of a triangle with base = 15 cm and corresponding height = 6 cm:', 'Area = 1/2 × 15 × 6 = 45 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d859b8ca-7cbe-4579-9b4c-7bae34c29bd7', '45 cm² (Area = 1/2 × 15 × 6 = 15 × 3 = 45 cm²)', true, '1db14b8a-3b0f-4218-83a8-fe6656760472');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df8220c5-2b8a-4c91-b9c2-67fc09fb7a19', '90 cm²', false, '1db14b8a-3b0f-4218-83a8-fe6656760472');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6f5f7fe-dc84-4ee9-88eb-b201d8c3668c', '30 cm²', false, '1db14b8a-3b0f-4218-83a8-fe6656760472');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98ff8548-db6b-4ce1-a87b-53b8db514d26', '60 cm²', false, '1db14b8a-3b0f-4218-83a8-fe6656760472');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('29488001-b12e-4ae1-a967-1d1c2cbb1d70', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Easy', 'Find the Area of a parallelogram with base = 8 cm and height = 4.5 cm:', 'Area = 8 × 4.5 = 36 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6d9ada1-7271-4cb0-a08d-3a1f42dd3ca9', '36 cm² (Area = 8 × 4.5 = 36 cm²)', true, '29488001-b12e-4ae1-a967-1d1c2cbb1d70');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc808a96-ce20-4ff3-a352-2940bbdccd37', '18 cm²', false, '29488001-b12e-4ae1-a967-1d1c2cbb1d70');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54578d1c-71a2-46a3-bf5a-a39e42c198a9', '72 cm²', false, '29488001-b12e-4ae1-a967-1d1c2cbb1d70');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfd0086f-c8e9-4aca-ae32-33d7cab4ae75', '25 cm²', false, '29488001-b12e-4ae1-a967-1d1c2cbb1d70');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('351247e5-d4db-4d93-90f3-f9abb78635ea', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'A door of length 2 m and breadth 1 m is fitted in a wall. The length of the wall is 4.5 m and the breadth is 3.6 m. Find the cost of white washing the wall at the rate of Rs 20 per m²:', 'Area to whitewash = 16.2 - 2.0 = 14.2 m². Cost = 14.2 × 20 = Rs 284.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d20f23b4-5b6a-4392-b46e-c64c50571264', 'Rs 284 (Wall Area = 4.5 × 3.6 = 16.2 m² ; Door Area = 2 × 1 = 2 m² ; Area to whitewash = 16.2 - 2 = 14.2 m² ; Cost = 14.2 × 20 = Rs 284)', true, '351247e5-d4db-4d93-90f3-f9abb78635ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36ce9906-69e4-42f6-a77a-e3f8a8d8b55a', 'Rs 324', false, '351247e5-d4db-4d93-90f3-f9abb78635ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fde7697f-3000-49be-850d-d9f805d22d7c', 'Rs 260', false, '351247e5-d4db-4d93-90f3-f9abb78635ea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('605031a6-b917-4d52-b633-6009460bc3c5', 'Rs 300', false, '351247e5-d4db-4d93-90f3-f9abb78635ea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91d6c3cb-cdbb-4885-b958-bdfe42ed04a0', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'The area of a square and a rectangle are equal. If the side of the square is 40 cm and the breadth of the rectangle is 25 cm, find the length of the rectangle and its perimeter:', 'Area = 1600. Length = 1600 / 25 = 64 cm. Perimeter = 2(64 + 25) = 178 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('764b846c-e712-4a46-b2b3-c84d07c3dad6', 'Length = 64 cm ; Perimeter = 178 cm (Area = 40² = 1600 cm² ; Length = 1600 / 25 = 64 cm ; Perimeter = 2(64 + 25) = 2 × 89 = 178 cm)', true, '91d6c3cb-cdbb-4885-b958-bdfe42ed04a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21fbe990-3f36-4811-b970-452b55bee041', 'Length = 50 cm ; Perimeter = 150 cm', false, '91d6c3cb-cdbb-4885-b958-bdfe42ed04a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e236a761-d5c8-47ef-9dd9-2c24851385d1', 'Length = 60 cm ; Perimeter = 170 cm', false, '91d6c3cb-cdbb-4885-b958-bdfe42ed04a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ced44368-107b-47f8-ba25-94bd9297b816', 'Length = 64 cm ; Perimeter = 160 cm', false, '91d6c3cb-cdbb-4885-b958-bdfe42ed04a0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7788186a-f201-4c0c-a6a9-4c82882b0c99', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'A wire is in the shape of a rectangle of length 40 cm and breadth 22 cm. If the SAME wire is rebent in the shape of a square, what will be the measure of each side of the square and which shape encloses more area?', 'Wire length = 124 cm. Square side = 31 cm. Area of square (961 cm²) > Area of rectangle (880 cm²).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48cf50cd-291d-4787-8262-4ead10453cba', 'Side of square = 31 cm ; The SQUARE encloses more area (Perimeter = 2(40+22) = 124 cm ; Side = 124/4 = 31 cm ; Square Area = 31² = 961 cm² > Rect Area = 40×22 = 880 cm²)', true, '7788186a-f201-4c0c-a6a9-4c82882b0c99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5538a124-4767-4b6a-84b7-1400aa8b6a89', 'Side = 30 cm ; Rectangle encloses more', false, '7788186a-f201-4c0c-a6a9-4c82882b0c99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a01ce759-b4bb-4bf2-9adf-46c75e741c1f', 'Side = 31 cm ; Both have equal area', false, '7788186a-f201-4c0c-a6a9-4c82882b0c99');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38dcb49f-0c5b-4b4c-8134-b15a008a0867', 'Side = 32 cm ; Square encloses more', false, '7788186a-f201-4c0c-a6a9-4c82882b0c99');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8aa43da4-294a-4273-ba18-9f52aefc2563', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'A garden is 90 m long and 75 m broad. A path 5 m wide is to be built outside and around it. Find the AREA OF THE PATH in m² and in hectares:', 'Outer rectangle = 100 × 85 = 8500 m². Inner = 90 × 75 = 6750 m². Path = 8500 - 6750 = 1750 m² = 0.175 hectare.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff356e04-7815-4419-afec-ee56dbe59983', '1,750 m² (0.175 hectares) (Outer dim = 100 m × 85 m ; Outer Area = 8,500 m² ; Inner Area = 90 × 75 = 6,750 m² ; Path Area = 8,500 - 6,750 = 1,750 m² = 0.175 ha)', true, '8aa43da4-294a-4273-ba18-9f52aefc2563');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c61db80-fb6e-4209-9024-db399397d034', '1,500 m² (0.15 ha)', false, '8aa43da4-294a-4273-ba18-9f52aefc2563');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec957e19-90e5-41cf-9727-93d3a4a1f09e', '2,000 m² (0.2 ha)', false, '8aa43da4-294a-4273-ba18-9f52aefc2563');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81761055-2a4f-4283-b7b0-bd90d242484d', '1,650 m² (0.165 ha)', false, '8aa43da4-294a-4273-ba18-9f52aefc2563');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a04b855-b0cf-4f7e-b7ab-442f15afb611', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'A picture is painted on a cardboard 8 cm long and 5 cm wide such that there is a margin of 1.5 cm along each of its sides. Find the total AREA OF THE MARGIN:', 'Outer = 40 cm². Inner = 5 × 2 = 10 cm². Margin = 40 - 10 = 30 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d880bcc-cacd-41aa-a2f9-3d1ec4fe106d', '30 cm² (Outer Area = 8 × 5 = 40 cm² ; Inner dim = (8 - 3) × (5 - 3) = 5 cm × 2 cm ; Inner Area = 10 cm² ; Margin Area = 40 - 10 = 30 cm²)', true, '1a04b855-b0cf-4f7e-b7ab-442f15afb611');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f47cf78-a60d-471f-860a-edef7a0bc33d', '25 cm²', false, '1a04b855-b0cf-4f7e-b7ab-442f15afb611');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('099dd7fa-65fc-4076-9ff5-f7039429534a', '35 cm²', false, '1a04b855-b0cf-4f7e-b7ab-442f15afb611');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80924fa4-bec4-400a-a1e8-f654740609eb', '20 cm²', false, '1a04b855-b0cf-4f7e-b7ab-442f15afb611');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae35d759-128d-4a2c-b4ed-a25e1ef78b85', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'Two cross roads, each of width 10 m, cut at right angles through the centre of a rectangular park of length 700 m and breadth 300 m and parallel to its sides. Find the total AREA OF THE ROADS:', 'Area of cross roads = 700(10) + 300(10) - 10² = 7000 + 3000 - 100 = 9,900 m².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81bbd1ee-8635-42a5-910f-335edf0a0656', '9,900 m² (0.99 hectares) (Road 1 = 700 × 10 = 7,000 ; Road 2 = 300 × 10 = 3,000 ; Common intersection = 10 × 10 = 100 ; Total = 7,000 + 3,000 - 100 = 9,900 m²)', true, 'ae35d759-128d-4a2c-b4ed-a25e1ef78b85');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c117ab31-d172-43d7-98f8-14de7b16990e', '10,000 m²', false, 'ae35d759-128d-4a2c-b4ed-a25e1ef78b85');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0123a5e5-c50e-4139-a8b6-ee87a4f19b70', '9,800 m²', false, 'ae35d759-128d-4a2c-b4ed-a25e1ef78b85');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('023936e9-b2c0-43a7-83ba-e715331ca52c', '9,500 m²', false, 'ae35d759-128d-4a2c-b4ed-a25e1ef78b85');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c09bfc7c-712f-47a4-b355-cb599c1c0c95', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'From a circular sheet of radius 4 cm, a concentric circle of radius 3 cm is removed. Find the AREA OF THE REMAINING SHEET (Take π = 3.14):', 'Remaining area = π(4² - 3²) = 3.14 × 7 = 21.98 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4449fa43-380f-41cf-a8c2-06f98b82ce83', '21.98 cm² (Area = π × (R² - r²) = 3.14 × (16 - 9) = 3.14 × 7 = 21.98 cm²)', true, 'c09bfc7c-712f-47a4-b355-cb599c1c0c95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92d439f4-1815-463b-a98b-e9c97048d1bc', '22.5 cm²', false, 'c09bfc7c-712f-47a4-b355-cb599c1c0c95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1960c4db-b97d-4ac4-b57b-42fe21f0079b', '20.84 cm²', false, 'c09bfc7c-712f-47a4-b355-cb599c1c0c95');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09dea0ac-3ea1-4662-b2e0-8c1986f5a5dd', '25.12 cm²', false, 'c09bfc7c-712f-47a4-b355-cb599c1c0c95');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5d2d58c-1bd6-47e0-827e-8337bb5b0bbb', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'A gardener wants to fence a circular garden of diameter 21 m. Find the length of rope he needs to purchase if he makes 2 rounds of fence, and the cost of rope at Rs 4 per metre (Take π = 22/7):', 'C = πd = (22/7) × 21 = 66 m. Two rounds = 132 m. Cost = 132 × 4 = Rs 528.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab06818c-350d-4bf8-84dc-789afc80206c', 'Length of rope = 132 m ; Cost = Rs 528 (Circumference = (22/7) × 21 = 66 m ; 2 rounds = 66 × 2 = 132 m ; Cost = 132 × 4 = Rs 528)', true, 'a5d2d58c-1bd6-47e0-827e-8337bb5b0bbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e296845-4ac0-418c-acfb-b24a827ad621', 'Length = 66 m ; Cost = Rs 264', false, 'a5d2d58c-1bd6-47e0-827e-8337bb5b0bbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6355996f-30c5-40cd-a32a-1ae3ba82bed1', 'Length = 132 m ; Cost = Rs 600', false, 'a5d2d58c-1bd6-47e0-827e-8337bb5b0bbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('746ab787-b623-4469-b9b8-9610dc754799', 'Length = 150 m ; Cost = Rs 528', false, 'a5d2d58c-1bd6-47e0-827e-8337bb5b0bbb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a392625a-f088-49e8-9fdb-c45c0ab90068', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'The circumference of a circle is 31.4 cm. Find the radius and the area of the circle (Take π = 3.14):', 'r = 31.4 / (2 × 3.14) = 5 cm. Area = 3.14 × 25 = 78.5 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cf10cca-5df1-4f24-983b-adcd7b6b696f', 'Radius = 5 cm ; Area = 78.5 cm² (2 × 3.14 × r = 31.4 ⇒ r = 5 cm ; Area = 3.14 × 5² = 3.14 × 25 = 78.5 cm²)', true, 'a392625a-f088-49e8-9fdb-c45c0ab90068');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20a1d136-4d6c-41d1-b393-eba87630f305', 'Radius = 10 cm ; Area = 314 cm²', false, 'a392625a-f088-49e8-9fdb-c45c0ab90068');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96de090c-5f24-42ef-a2f1-220826593988', 'Radius = 5 cm ; Area = 154 cm²', false, 'a392625a-f088-49e8-9fdb-c45c0ab90068');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f885a65-4597-4ef8-bd71-07b5a99d0222', 'Radius = 7 cm ; Area = 154 cm²', false, 'a392625a-f088-49e8-9fdb-c45c0ab90068');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94801820-e966-4ce8-b5b0-3720d1fedb89', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'A circular flower bed is surrounded by a path 4 m wide. The diameter of the flower bed is 66 m. What is the AREA OF THIS PATH? (Take π = 3.14)', 'Ring area = π(37² - 33²) = 3.14 × (70 × 4) = 3.14 × 280 = 879.2 m².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cba4ebf7-9725-47ca-aa85-d1b37a33ee4c', '879.2 m² (Inner radius r = 33 m ; Outer radius R = 33 + 4 = 37 m ; Path Area = π(R² - r²) = 3.14 × (37² - 33²) = 3.14 × (1369 - 1089) = 3.14 × 280 = 879.2 m²)', true, '94801820-e966-4ce8-b5b0-3720d1fedb89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77db2d7d-0628-4277-afe6-d0dbc05eae75', '850.5 m²', false, '94801820-e966-4ce8-b5b0-3720d1fedb89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f319ad2-94c7-401e-ae06-58e8891496c4', '900.2 m²', false, '94801820-e966-4ce8-b5b0-3720d1fedb89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a6b91fe-62e1-410a-948b-e2c2f182eb0a', '864.0 m²', false, '94801820-e966-4ce8-b5b0-3720d1fedb89');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5308b957-ca89-418f-b707-f4521c44774f', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'A circular flower garden has an area of 314 m². A sprinkler at the centre of the garden can cover an area that has a radius of 12 m. Will the sprinkler water the ENTIRE garden? (Take π = 3.14)', 'Garden radius = √(314/3.14) = 10 m. Sprinkler radius = 12 m > 10 m, so it covers the entire garden.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f2787a3-5733-4ecf-8646-d0436dde1ba6', 'Yes, because the sprinkler covers an area of 452.16 m² (π × 12² = 3.14 × 144 = 452.16 m²), which is greater than the garden''s area of 314 m²', true, '5308b957-ca89-418f-b707-f4521c44774f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fdf3542-f487-4669-8e2d-d2dc3a7a360b', 'No, the sprinkler only waters 200 m²', false, '5308b957-ca89-418f-b707-f4521c44774f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9d95264-d3b3-42bf-904c-9b872d8fadb0', 'No, because the radius is too small', false, '5308b957-ca89-418f-b707-f4521c44774f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e29c6781-cc3a-4476-b6c4-a0b936f60f3f', 'Cannot be determined', false, '5308b957-ca89-418f-b707-f4521c44774f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a47a127d-c73b-44d3-9f8d-2da309d571c3', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'How many times a wheel of radius 28 cm must rotate to go a distance of 352 m? (Take π = 22/7)', 'C = 2 × (22/7) × 28 = 176 cm = 1.76 m. Rotations = 352 / 1.76 = 200.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02bf1b0f-d0d5-4570-a110-ee03d3aca665', '200 rotations (Circumference = 2 × (22/7) × 28 = 176 cm = 1.76 m ; Rotations = 352 / 1.76 = 200)', true, 'a47a127d-c73b-44d3-9f8d-2da309d571c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1111a9c9-cbec-41b9-bf83-3475e9ea3ac2', '100 rotations', false, 'a47a127d-c73b-44d3-9f8d-2da309d571c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90a39bc5-5b14-4c2c-82b3-65711ad1ae36', '300 rotations', false, 'a47a127d-c73b-44d3-9f8d-2da309d571c3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a963548-709b-4300-bc06-5e63d3391ee7', '250 rotations', false, 'a47a127d-c73b-44d3-9f8d-2da309d571c3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6605e030-9b1b-44fb-a4df-d6647c5f4dbb', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'The minute hand of a circular clock is 15 cm long. How far does the TIP of the minute hand move in 1 hour? (Take π = 3.14)', 'Distance = 2πr = 2 × 3.14 × 15 = 94.2 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81899d16-e106-416f-bbf1-77f8c4cc915e', '94.2 cm (In 1 hour, the minute hand completes 1 full rotation = Circumference = 2 × 3.14 × 15 = 94.2 cm)', true, '6605e030-9b1b-44fb-a4df-d6647c5f4dbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab7ae2e9-49ca-4255-b9b3-54cada90ee52', '47.1 cm', false, '6605e030-9b1b-44fb-a4df-d6647c5f4dbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a40a036-be5d-456f-a170-a9a69f76e338', '150 cm', false, '6605e030-9b1b-44fb-a4df-d6647c5f4dbb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6406915f-71d2-4728-ba1b-fb13fb6aed05', '31.4 cm', false, '6605e030-9b1b-44fb-a4df-d6647c5f4dbb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77020ad4-6450-40da-9eb0-cc9d521b2301', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'The area of a triangle is 50 cm². If one of its sides is 20 cm, find the corresponding altitude (height) to that side:', '50 = ½(20)h → 10h = 50 → h = 5 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('766bac9f-ccbd-4469-bf18-51a48548d682', '5 cm (Area = 1/2 × b × h ⇒ 50 = 1/2 × 20 × h ⇒ 50 = 10h ⇒ h = 5 cm)', true, '77020ad4-6450-40da-9eb0-cc9d521b2301');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35c2b084-16e8-49a8-aa5f-dc7d642c9e0c', '10 cm', false, '77020ad4-6450-40da-9eb0-cc9d521b2301');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e58666f-5f8b-48d4-bacd-8debf6d41163', '2.5 cm', false, '77020ad4-6450-40da-9eb0-cc9d521b2301');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a143d057-4c5a-4f45-b884-00a1e4f83200', '4 cm', false, '77020ad4-6450-40da-9eb0-cc9d521b2301');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('062d7039-f601-4d45-9d22-52cea1870336', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'Find the perimeter of a semicircle of radius 7 cm including its diameter base (Take π = 22/7):', 'Perimeter of closed semicircle = πr + 2r = 22 + 14 = 36 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fecf99c-ad98-431e-a7d4-dd148b7320b7', '36 cm (Perimeter = πr + 2r = (22/7) × 7 + 14 = 22 + 14 = 36 cm)', true, '062d7039-f601-4d45-9d22-52cea1870336');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4ffc10d-13d0-4b0a-9d1a-4c5fcb051923', '44 cm', false, '062d7039-f601-4d45-9d22-52cea1870336');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef92eab7-be90-45de-8f05-3e22921495f7', '22 cm', false, '062d7039-f601-4d45-9d22-52cea1870336');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a772989f-f4ad-4dd0-baf1-24a044f01b2d', '29 cm', false, '062d7039-f601-4d45-9d22-52cea1870336');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1ff4267-85bb-4f40-b2e2-4be945d859f0', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Medium', 'Convert 5.4 m² into cm²:', '5.4 × 10,000 = 54,000 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('782c513e-0f5b-49f6-b2e1-e078a05b6b7b', '54,000 cm² (1 m² = 10,000 cm² ; 5.4 × 10,000 = 54,000 cm²)', true, 'f1ff4267-85bb-4f40-b2e2-4be945d859f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6d6266a-b7da-4431-880b-7c586c2355df', '540 cm²', false, 'f1ff4267-85bb-4f40-b2e2-4be945d859f0');
