INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d30af29-155b-43c3-b4df-45f9856f3ab8', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fb94319-a23f-44b0-9fcb-a1502a5bd4fa', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '2d30af29-155b-43c3-b4df-45f9856f3ab8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8320d17-c5c7-4eb5-8775-e98104dd3645', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '2d30af29-155b-43c3-b4df-45f9856f3ab8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3d6af1c-71ba-497e-a0c2-a13ea6556da1', '(A) is true, but (R) is false.', false, '2d30af29-155b-43c3-b4df-45f9856f3ab8');
