INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07e06a6f-db19-4ed3-99c9-99e5ce46968b', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'Spot the IMPOSTER in the following area and metric unit conversion formulas:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cafba99c-07cf-424f-a116-bbccad17dde5', 'Formula 1', false, '07e06a6f-db19-4ed3-99c9-99e5ce46968b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ec72d91-f56f-4d25-b877-637d799884ef', 'Formula 2', false, '07e06a6f-db19-4ed3-99c9-99e5ce46968b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f7765c1-c2a1-4dba-8d03-0272e20b6f32', 'Formula 3', false, '07e06a6f-db19-4ed3-99c9-99e5ce46968b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d2b7e7e-d65d-4bad-8e47-0546faca3aea', 'Formula 4 (Circumference is 2πr or πd ; πr² is the formula for the AREA of a circle)', true, '07e06a6f-db19-4ed3-99c9-99e5ce46968b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46fd995c-739f-4b80-b806-a04faf168a92', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'In ΔABC, right-angled at A, AD is perpendicular to BC. If AB = 5 cm, BC = 13 cm, and AC = 12 cm, find the Area of ΔABC and the length of AD:', 'Area = ½(5)(12) = 30 cm². Also 30 = ½(13)(AD) → AD = 60/13 ≈ 4.615 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d1d058d-69c4-4604-9d59-44897bca2c32', 'Area = 30 cm² ; AD = 4.61 cm (60/13 cm) (Area = 1/2 × 5 × 12 = 30 cm² ; Also Area = 1/2 × BC × AD ⇒ 30 = 1/2 × 13 × AD ⇒ AD = 60/13 ≈ 4.61 cm)', true, '46fd995c-739f-4b80-b806-a04faf168a92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b72e596b-4251-4499-9c49-7cdbbd67afd1', 'Area = 60 cm² ; AD = 5 cm', false, '46fd995c-739f-4b80-b806-a04faf168a92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2628469-1367-46bc-bb4a-7565d48e0246', 'Area = 30 cm² ; AD = 6 cm', false, '46fd995c-739f-4b80-b806-a04faf168a92');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('052e9a67-0aff-4392-9942-b4dfba1b4328', 'Area = 65 cm² ; AD = 4.61 cm', false, '46fd995c-739f-4b80-b806-a04faf168a92');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f85ac04c-d75e-4884-b6a0-67fb6dbb6e43', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'Match Column I (Geometric Figures with Dimensions) with Column II (Calculated Areas):
(a) Square of perimeter 60 cm              -> (i) 225 cm² (Side = 15 cm ; Area = 15² = 225)
(b) Circle of radius 7 cm                  -> (ii) 154 cm²
(c) Parallelogram (base 12 cm, height 8 cm)-> (iii) 96 cm²
(d) Triangle (base 14 cm, height 10 cm)    -> (iv) 70 cm²', 'Square: 15² = 225; Circle: 22/7(49) = 154; Parallelogram: 12×8 = 96; Triangle: ½(14)(10) = 70.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aefc4a40-ccdd-4d65-924b-4c8ef9ef658a', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'f85ac04c-d75e-4884-b6a0-67fb6dbb6e43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0917881e-0eb7-402a-b93b-b367b0a699ad', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'f85ac04c-d75e-4884-b6a0-67fb6dbb6e43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ede0acf9-f357-4440-bf65-3ec031fac9f4', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'f85ac04c-d75e-4884-b6a0-67fb6dbb6e43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bcfec3e-be10-4ea6-a6d1-b5cf28c85c83', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'f85ac04c-d75e-4884-b6a0-67fb6dbb6e43');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0ff9977-b8ec-4b1e-a4d8-a2c7c273da81', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'Read the statements regarding metric area relationships:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7883f514-9f42-4b5b-b95b-ffc2c42a697b', 'Statements 1 and 2 only', true, 'b0ff9977-b8ec-4b1e-a4d8-a2c7c273da81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8b7d32a-a37e-48d0-a4bc-fb5bf3a424a4', 'Statements 2 and 3 only', false, 'b0ff9977-b8ec-4b1e-a4d8-a2c7c273da81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2845b19-37e7-45b1-b5e2-449a70eaf0d3', 'Statements 1 and 3 only', false, 'b0ff9977-b8ec-4b1e-a4d8-a2c7c273da81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7bec38f-f074-4bd4-b331-b7c0d1b20bc9', 'All Statements 1, 2, and 3', false, 'b0ff9977-b8ec-4b1e-a4d8-a2c7c273da81');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('571f17f0-60e9-4e96-95c1-60666ee3a379', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'If the ratio of the areas of two circles is 49 : 64, find the RATIO OF THEIR CIRCUMFERENCES:', 'Circumference ratio equals radius ratio = √(49/64) = 7/8.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b04ae5bc-67d9-46f7-9cbe-4e4868fa4e90', '7 : 8 (Area ratio = (r1/r2)² = 49/64 ⇒ r1/r2 = 7/8 ; Circumference ratio = 2πr1 / 2πr2 = r1/r2 = 7 : 8)', true, '571f17f0-60e9-4e96-95c1-60666ee3a379');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bd5078b-7db2-4c87-a638-60e76c1da750', '49 : 64', false, '571f17f0-60e9-4e96-95c1-60666ee3a379');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef55637b-137f-47c3-bef9-44aca040a8d2', '14 : 16', false, '571f17f0-60e9-4e96-95c1-60666ee3a379');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1651143a-627b-4874-8445-cdaf56fdcb3b', '343 : 512', false, '571f17f0-60e9-4e96-95c1-60666ee3a379');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fb70176e-4146-4d64-8ec4-eaa2dc0a248d', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'A racetrack is in the form of a circular ring whose inner circumference is 352 m and outer circumference is 396 m. Find the WIDTH of the track (Take π = 22/7):', 'R = 396 / 44 × 7 = 63 m. r = 352 / 44 × 7 = 56 m. Width = 63 - 56 = 7 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3c43d8b-42ad-4a8b-8d18-4191062a2fda', '7 m (Outer radius R = 396 / (2 × 22/7) = 63 m ; Inner radius r = 352 / (2 × 22/7) = 56 m ; Width = R - r = 63 - 56 = 7 m)', true, 'fb70176e-4146-4d64-8ec4-eaa2dc0a248d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfc7db99-50d3-4060-a6c7-e3f71a93db74', '14 m', false, 'fb70176e-4146-4d64-8ec4-eaa2dc0a248d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de5dece0-21ae-4966-bfe5-79cb1b589cfa', '3.5 m', false, 'fb70176e-4146-4d64-8ec4-eaa2dc0a248d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73496715-d2d3-45ea-b270-1cfb8f1acb24', '10 m', false, 'fb70176e-4146-4d64-8ec4-eaa2dc0a248d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0dfb917b-1147-4b3e-97d2-e1b3816e1043', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'A wire loop of radius 21 cm is straightened and then bent into an equilateral triangle. Find the length of each side of the triangle (Take π = 22/7):', 'Wire perimeter = 2 × (22/7) × 21 = 132 cm. Side of triangle = 132 / 3 = 44 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b3f41de-6709-4c03-80d6-f1b10a66644b', '44 cm (Wire length = Circumference = 2 × (22/7) × 21 = 132 cm ; Side of equilateral triangle = 132 / 3 = 44 cm)', true, '0dfb917b-1147-4b3e-97d2-e1b3816e1043');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c002c769-28c1-44c2-88c9-715d5f7ff7c3', '33 cm', false, '0dfb917b-1147-4b3e-97d2-e1b3816e1043');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53c601a6-93da-4cc2-a392-6599204a9fb8', '22 cm', false, '0dfb917b-1147-4b3e-97d2-e1b3816e1043');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b7ee3b3-e16d-4dbe-a824-c497820ec7c7', '66 cm', false, '0dfb917b-1147-4b3e-97d2-e1b3816e1043');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2964aa51-734a-4715-bd2c-23479507c0c8', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'The base of a parallelogram is TWICE its height. If the area of the parallelogram is 512 cm², find its base and height:', '2h² = 512 → h = √256 = 16 cm. Base = 32 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccf2f67e-8131-4127-8fb6-66a5a997eb3d', 'Base = 32 cm ; Height = 16 cm (Area = b × h ⇒ (2h) × h = 512 ⇒ 2h² = 512 ⇒ h² = 256 ⇒ h = 16 cm ; b = 2 × 16 = 32 cm)', true, '2964aa51-734a-4715-bd2c-23479507c0c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('079109de-858a-46e3-98bc-99170e3b8919', 'Base = 16 cm ; Height = 8 cm', false, '2964aa51-734a-4715-bd2c-23479507c0c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('249d8c0c-5b45-4824-88c0-f6f655eca371', 'Base = 64 cm ; Height = 32 cm', false, '2964aa51-734a-4715-bd2c-23479507c0c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad932470-c043-432b-9df4-a2b00e0ef38a', 'Base = 24 cm ; Height = 12 cm', false, '2964aa51-734a-4715-bd2c-23479507c0c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0c29579-f0c5-4397-800c-1ba72c8a6b35', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'Four equal circles, each of radius 7 cm, are placed touching each other so that their centres form a square of side 14 cm. Find the AREA of the shaded space enclosed between the four circles (Take π = 22/7):', 'Area between 4 circles = a² - πr² = 14² - (22/7)(7²) = 196 - 154 = 42 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b95e8689-d098-454c-924e-4926f3dc555d', '42 cm² (Square Area = 14 × 14 = 196 cm² ; 4 quadrants = 1 full circle area = (22/7) × 7² = 154 cm² ; Enclosed Area = 196 - 154 = 42 cm²)', true, 'c0c29579-f0c5-4397-800c-1ba72c8a6b35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8013c5de-2d01-4fda-8e28-637d8b0cc034', '56 cm²', false, 'c0c29579-f0c5-4397-800c-1ba72c8a6b35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22076095-ce9e-47ae-8870-ef6cd2203a4e', '28 cm²', false, 'c0c29579-f0c5-4397-800c-1ba72c8a6b35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e46a8828-2c93-453f-bac2-5cd9275a6fd9', '36 cm²', false, 'c0c29579-f0c5-4397-800c-1ba72c8a6b35');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0aeab4da-79ff-4daa-8caa-3436daccf6f3', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'A copper wire when bent in the form of a square encloses an area of 484 cm². If the same wire is bent into a circle, find the area enclosed by the circle (Take π = 22/7):', 'Square side = 22 cm → P = 88 cm. Radius = 14 cm. Circle area = (22/7)(196) = 616 cm².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0fe8d16-24a0-4330-a4b7-36141bd1ef15', '616 cm² (Side of square = √484 = 22 cm ; Perimeter = 4 × 22 = 88 cm ; Circle radius = 88 / (2 × 22/7) = 14 cm ; Circle Area = (22/7) × 14² = 616 cm²)', true, '0aeab4da-79ff-4daa-8caa-3436daccf6f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a30be316-ab1e-4a3e-b798-8ff2bbf33890', '550 cm²', false, '0aeab4da-79ff-4daa-8caa-3436daccf6f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4816226-3cd7-4956-b498-2cb0aeb00095', '484 cm²', false, '0aeab4da-79ff-4daa-8caa-3436daccf6f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b55e9c5-17c0-4009-8579-c6798f64812a', '625 cm²', false, '0aeab4da-79ff-4daa-8caa-3436daccf6f3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e68f0a76-ad94-49ad-98a5-31dfd618e274', 'Class 7', 'Mathematics', 'Chapter 9: Perimeter and Area', 'Hard', 'Why is the geometric calculation of Perimeter and 2D Area vital across civil architecture, land revenue cartography, urban planning, and material engineering?', 'Perimeter and area calculations are the universal geometric foundations for material procurement, boundary demarcation, and structural design.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf3711c8-363c-4583-933f-ea10a0e775dc', 'It determines exact material quantities required for boundaries, fencing, tiling, paving, surface coatings, structural loads, and agricultural land taxation', true, 'e68f0a76-ad94-49ad-98a5-31dfd618e274');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98a418c2-2373-40e0-a7d5-2aeba8eea274', 'Because area is used only to draw circles', false, 'e68f0a76-ad94-49ad-98a5-31dfd618e274');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd780ffb-5271-429a-9e1e-56fad79550ab', 'Because perimeter is measured only with sticks', false, 'e68f0a76-ad94-49ad-98a5-31dfd618e274');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9466d1bc-576d-49a6-966b-3186a057b722', 'Because modern construction ignores geometry', false, 'e68f0a76-ad94-49ad-98a5-31dfd618e274');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('080c410a-7829-4019-b770-a6a76d3bb4c9', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'In Jerome K. Jerome''s comedic story ''A Bicycle in Good Repair'', what excursion was planned for the following day?', 'The narrator and an acquaintance arranged to go for a long bicycle ride together early the next morning.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5879e73-5e71-4cfe-be79-db9562c4049a', 'A long bicycle ride together out into the countryside', true, '080c410a-7829-4019-b770-a6a76d3bb4c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf65dad6-550e-476d-a319-a7ba00da927f', 'A train journey to London', false, '080c410a-7829-4019-b770-a6a76d3bb4c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce4f77c5-7246-4e01-b019-dd5269140310', 'A boat trip down the river', false, '080c410a-7829-4019-b770-a6a76d3bb4c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('932589e9-84ba-478d-975f-65ec1fbdcc9f', 'A mountain climbing hike', false, '080c410a-7829-4019-b770-a6a76d3bb4c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9709413-492c-4cad-aba9-98b797571b45', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'What did the acquaintance do to the bicycle as soon as he saw it, before they had even set off?', 'The acquaintance aggressively shook the bicycle: ''He took hold of it by the front wheel and the fork, and shook it violently.''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cca8c6c4-9765-4a7c-90c4-73e2a230a5d1', 'He shook it violently by the front wheel and handlebars, claiming the front wheel wobbled dangerously', true, 'e9709413-492c-4cad-aba9-98b797571b45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('132c51e2-5aaf-445c-a010-74cb91f43220', 'He rode it happily down the road', false, 'e9709413-492c-4cad-aba9-98b797571b45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61a7fa06-e4bc-4779-a3ad-f0ae36de28ae', 'He washed it with soap', false, 'e9709413-492c-4cad-aba9-98b797571b45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a5c112c-7558-47af-886c-4e0ccec90d4b', 'He painted it blue', false, 'e9709413-492c-4cad-aba9-98b797571b45');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30c8a3c0-0506-485d-a978-7ce3221b08fd', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'What small, rolling metal items spilled out everywhere across the gravel path when the acquaintance unscrewed the front wheel bearing?', 'Unscrewing the axle housing released a dozen little ball-bearings that rolled all over the gravel.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cb7ea7b-26c1-4d7b-b891-abda26d73161', 'Little steel ball-bearings (little balls)', true, '30c8a3c0-0506-485d-a978-7ce3221b08fd');
