INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6eaf568e-86ee-43a8-9b27-d5b23e994edf', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'Where did the narrator and his friend put the rescued ball-bearings for safekeeping?', 'They stored the collected ball bearings in the narrator''s hat, which was subsequently blown off by the wind.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cb424ba-b6fb-46d1-b3d1-1e8d376a8bdb', 'Inside the narrator''s Hat (which later blew away in the wind)', true, '6eaf568e-86ee-43a8-9b27-d5b23e994edf');
