INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76b233c8-d8f1-40f4-87c5-79b7de866c34', 'In a leather wallet', false, '6eaf568e-86ee-43a8-9b27-d5b23e994edf');
