INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a8aee76d-7a53-4256-85ab-7d2b258efeec', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'What part of the bicycle did the acquaintance next take to pieces, despite an experienced friend having advised the narrator NEVER to touch it?', 'He dismantled the gear-case, cutting it in two pieces, ignoring the advice to buy a new bicycle rather than tamper with it.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6945235-fc61-4e7a-b00c-4c36492163bf', 'The Gear-case', true, 'a8aee76d-7a53-4256-85ab-7d2b258efeec');
