INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01f1b731-6e04-4a17-be17-91baf78d428d', 'The Bell', false, 'a8aee76d-7a53-4256-85ab-7d2b258efeec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b03f9659-82f8-4828-a212-b238615dd8c4', 'The Brake levers', false, 'a8aee76d-7a53-4256-85ab-7d2b258efeec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b72678bd-bc75-46cd-a25b-07511012ed1a', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'What happened to the bicycle chain during the acquaintance''s destructive repair attempts?', 'Comedic incompetence: he first tightened the chain until it jammed, then loosened it until it hung double.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03a49fca-0783-448f-a999-c14e2ed6e93f', 'He tightened it until it would not move at all, and then loosened it until it was twice as loose as before', true, 'b72678bd-bc75-46cd-a25b-07511012ed1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9775175-4318-4034-8ddd-f0755de0ac2f', 'He threw it into the pond', false, 'b72678bd-bc75-46cd-a25b-07511012ed1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('faf2ac55-2adf-453f-b72b-7fc773b943fe', 'He tied it to a tree', false, 'b72678bd-bc75-46cd-a25b-07511012ed1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab6a7faa-04a7-4fe9-bb89-27f32dad4801', 'It turned into gold', false, 'b72678bd-bc75-46cd-a25b-07511012ed1a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d42dd7d-6ced-46c9-b523-331484e2225e', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'What physical condition were both the acquaintance and the bicycle in by late afternoon?', 'The scene ended in utter slapstick wreckage: a grease-stained man struggling against a wrecked bicycle on the lawn.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d7fc4d1-24e8-4342-a00e-7b7c3844fda4', 'The acquaintance was covered in black oil, grease, and dirt, bleeding from scratches, and the bicycle was lying in a mangled heap across the path', true, '1d42dd7d-6ced-46c9-b523-331484e2225e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fa48865-d009-48fe-87a1-cd45155b863b', 'Both were clean and ready for a race', false, '1d42dd7d-6ced-46c9-b523-331484e2225e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d93a255a-af13-494a-b69a-0bf5eacfd3b3', 'The bicycle had flown away', false, '1d42dd7d-6ced-46c9-b523-331484e2225e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aea36b7e-0368-4c13-802c-8c2fd6ef954f', 'They had ridden 50 miles', false, '1d42dd7d-6ced-46c9-b523-331484e2225e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9e435d0-a823-4731-8727-7527407d27eb', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'In Muriel L. Sonne''s poem ''Garden Snake'', what does the child do upon first spotting a snake in the garden?', 'The poem begins: ''I saw a snake and ran away... / Some snakes are dangerous, they say;''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e2266ee-cb7f-4cc5-ad73-5ea90ff8edfd', 'The child runs away in fright, believing that ''some snakes are dangerous''', true, 'f9e435d0-a823-4731-8727-7527407d27eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0cf200d1-c518-4c3d-b045-920e69ad12a9', 'The child tries to catch the snake with a stick', false, 'f9e435d0-a823-4731-8727-7527407d27eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dcf38ba-d5a3-4335-a492-36362b18103c', 'The child steps on the snake', false, 'f9e435d0-a823-4731-8727-7527407d27eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5600ff0f-b02e-4974-b120-c743a1804d81', 'The child takes a picture', false, 'f9e435d0-a823-4731-8727-7527407d27eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c351559c-aab4-4d36-b628-2ebc6e18bc22', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'What comforting and reassuring advice does Mother give to the frightened child in ''Garden Snake''?', 'Mother says: ''"that kind is good, / And eats up insects for his food." / So when he wiggles in the grass / I''ll stand aside and watch him pass''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e914935-98a5-4f86-a561-2014873a4eaa', 'She explains that the garden snake is completely harmless (''that kind is good'') and eats only ordinary garden insects for its food', true, 'c351559c-aab4-4d36-b628-2ebc6e18bc22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5bdb59b-277e-4bf2-a0f4-f40cfabb4941', 'She tells the child to kill the snake', false, 'c351559c-aab4-4d36-b628-2ebc6e18bc22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('baf374c1-9e50-449c-82c8-a6839a42e830', 'She tells the child to stay inside the house forever', false, 'c351559c-aab4-4d36-b628-2ebc6e18bc22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34da2591-345d-48ec-8dad-963c53d3c00e', 'She tells the child to call the police', false, 'c351559c-aab4-4d36-b628-2ebc6e18bc22');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6c53a403-39a1-4bb0-a74a-63846d78182d', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'How does the child''s perspective on the garden snake change by the end of the poem?', 'Ending lines: ''I''ll stand aside and watch him pass, / And tell myself, "There''s no mistake, / It''s just a harmless garden snake!"''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df4d2c96-985e-434f-92fa-0de6d9aa3f02', 'The child stands aside calmly to admire the harmless little green snake wriggling through the grass with affection and respect', true, '6c53a403-39a1-4bb0-a74a-63846d78182d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8149ec5-9b87-48fc-923c-7d4051973c7a', 'The child continues to scream in terror', false, '6c53a403-39a1-4bb0-a74a-63846d78182d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66753ac6-7bce-4f2a-ad84-0d5fb55a33ab', 'The child buys a pet dog', false, '6c53a403-39a1-4bb0-a74a-63846d78182d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d73402e-bf36-4b8a-9de1-1e303b4b9d24', 'The child moves to another city', false, '6c53a403-39a1-4bb0-a74a-63846d78182d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6a34d01c-f489-4f7f-9816-c1bc6783d3ff', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'What is the meaning of the word ''Wobble'' as applied to the bicycle wheel?', '''Wobble'' means an unsteady, irregular side-to-side oscillation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('124e852b-68ff-4894-a98f-f215e1ce1a7c', 'To move unsteadily from side to side in an unsteady manner', true, '6a34d01c-f489-4f7f-9816-c1bc6783d3ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1200da8c-caec-403f-bc37-e7164083af84', 'To roll very fast', false, '6a34d01c-f489-4f7f-9816-c1bc6783d3ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('954a61a1-26ff-48f8-9ac3-416d4a3becfd', 'To stop suddenly', false, '6a34d01c-f489-4f7f-9816-c1bc6783d3ff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d4f3137-3f52-45c1-b9f0-2a4cd8883468', 'To shine brightly', false, '6a34d01c-f489-4f7f-9816-c1bc6783d3ff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7a06627-fea3-4b0c-aec2-219dd6d52ed8', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Easy', 'What is the meaning of ''Wiggles'' in the description of the garden snake?', '''Wiggle'' describes the undulating serpentine lateral movement of a snake.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc8fe762-e6a5-4f8b-b83c-5ec7c8c2845c', 'Moves with quick, small, wave-like side-to-side undulating motions', true, 'c7a06627-fea3-4b0c-aec2-219dd6d52ed8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3049bd08-4463-4cbd-83d8-2c679959dbf1', 'Jumps up in the air', false, 'c7a06627-fea3-4b0c-aec2-219dd6d52ed8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45b98690-624c-49f5-b611-22a69a8f81f3', 'Stands completely still', false, 'c7a06627-fea3-4b0c-aec2-219dd6d52ed8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49b4f771-4000-4735-acf3-ca65b743a3c7', 'Flies with wings', false, 'c7a06627-fea3-4b0c-aec2-219dd6d52ed8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a078bb9c-ee8b-4e85-8287-685846e1346b', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'Why was the narrator unable to prevent his destructive acquaintance from completely dismantling his perfectly functioning bicycle?', 'Narrator''s comedic flaw: excessive English social politeness and self-doubt prevents him from stopping blatant mechanical vandalism.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbcb2100-51a4-433e-83e8-d9bfff6ce8ef', 'The narrator suffered from excessive politeness, timid hesitation, and a mistaken deference that made him afraid of hurting his friend''s enthusiastic self-confidence', true, 'a078bb9c-ee8b-4e85-8287-685846e1346b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('615fc5ce-618a-48c2-b5ca-7c097f8c2a9a', 'Because the acquaintance had a gun', false, 'a078bb9c-ee8b-4e85-8287-685846e1346b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25d882f7-0b61-40b4-b42a-1e454b88197b', 'Because the bicycle belonged to the acquaintance', false, 'a078bb9c-ee8b-4e85-8287-685846e1346b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1d17d1c-0e2a-4c9a-9f85-48bdd0d5579f', 'Because the narrator was fast asleep', false, 'a078bb9c-ee8b-4e85-8287-685846e1346b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be3c6aa1-1802-4c02-a522-7729f9617b6c', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'How did the acquaintance personify the bicycle during their furious physical struggle in the garden?', 'Hyperbolic comic personification: the bicycle becomes a combatant: ''Now he was on top of the bicycle, and now the bicycle was on top of him.''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3758c957-233b-48bd-95bd-9e7328b7ffa4', 'He treated the bicycle like a willful, vicious adversary that fought back, hit him over the head with the handlebars, and leaped onto him in the dirt', true, 'be3c6aa1-1802-4c02-a522-7729f9617b6c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb6a9cc5-4018-4808-941c-e3c66b881136', 'He treated it like a loyal horse', false, 'be3c6aa1-1802-4c02-a522-7729f9617b6c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a87dd4a9-e36e-4da9-8195-aaaa2793d561', 'He treated it like an electric train', false, 'be3c6aa1-1802-4c02-a522-7729f9617b6c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e3fdf74-e8ff-44ce-96aa-ae315fbd8481', 'He treated it like a clock', false, 'be3c6aa1-1802-4c02-a522-7729f9617b6c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5bc10c80-7ebe-4ead-8b65-375e5c583e04', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What is the central ecological theme of Muriel L. Sonne''s poem ''Garden Snake''?', 'The poem deconstructs the irrational ophidiophobia (fear of snakes), celebrating the ecological value of harmless garden reptiles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0197bb5-088b-484b-8ce0-8a19c5340123', 'Overcoming irrational fear of nature through knowledge: understanding that garden snakes are harmless, beneficial predators that control garden insect pests', true, '5bc10c80-7ebe-4ead-8b65-375e5c583e04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb349553-0d42-467f-b7b1-ee2831a01627', 'Teaching people how to build cages', false, '5bc10c80-7ebe-4ead-8b65-375e5c583e04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5459a999-4e4e-4b65-90c7-3f5ab3072a5d', 'Warning that all animals in gardens are poisonous', false, '5bc10c80-7ebe-4ead-8b65-375e5c583e04');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5c0aa77-f1dd-4830-861f-ce44b8d852a8', 'Explaining how to cut lawn grass', false, '5bc10c80-7ebe-4ead-8b65-375e5c583e04');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('26851f46-8f18-472a-9f30-e4d9931d627f', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What is the meaning of the idiom ''To take to pieces'' in: ''He took the gear-case to pieces''?', '''To take to pieces'' is an idiom meaning completely disassembling a mechanical device.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ce1c0ed-0780-4b72-af03-8336480a3256', 'To dismantle or disassemble into separate component parts', true, '26851f46-8f18-472a-9f30-e4d9931d627f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31624ec2-1a62-4d66-b936-316f699392cb', 'To throw away into a river', false, '26851f46-8f18-472a-9f30-e4d9931d627f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60bae7c6-7c22-41a8-be20-7f0545795a03', 'To break with a hammer', false, '26851f46-8f18-472a-9f30-e4d9931d627f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('266a6ede-661a-4bbd-8539-45cb042495df', 'To paint each piece a different color', false, '26851f46-8f18-472a-9f30-e4d9931d627f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8f28610-32bb-413a-be2f-bd47d97deeaf', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What is the meaning of the adjective ''Grotesque'' in: ''The bicycle looked a grotesque skeleton''?', '''Grotesque'' characterizes an incongruously distorted, bizarre, or deformed physical state.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ddbcd16-c1f4-436e-bdb2-ed3b9cbf1bd6', 'Comically or repulsively distorted, bizarre, and unnatural in appearance', true, 'c8f28610-32bb-413a-be2f-bd47d97deeaf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddd55b96-1a3a-417e-a1ed-5eff325fe808', 'Extremely beautiful and modern', false, 'c8f28610-32bb-413a-be2f-bd47d97deeaf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb3fcd92-9bb7-42e9-8e55-e34d67340785', 'Painted in bright red', false, 'c8f28610-32bb-413a-be2f-bd47d97deeaf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('927a4135-138c-4e75-8815-82ab4fc7c8d2', 'Small and delicate', false, 'c8f28610-32bb-413a-be2f-bd47d97deeaf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74969e79-f08e-4265-bedf-e8221f72cfbd', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'Fill in the blank with the appropriate preposition:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff045ef3-bfb4-4316-a618-bd3d1af05ac6', 'over', true, '74969e79-f08e-4265-bedf-e8221f72cfbd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9daf95ee-0682-49e2-827c-e43199bb8075', 'under', false, '74969e79-f08e-4265-bedf-e8221f72cfbd');
