INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('466334d6-e8ea-4bb7-b9d1-3bd47fe6a402', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What is the SYNONYM of ''Tenacity'' or ''Doggedness'' as shown by the friend in attempting to fix the bicycle?', '''Doggedness'' or ''tenacity'' denotes stubborn, unrelenting determination despite repeated failures.', NOW()) ON CONFLICT DO NOTHING;
