INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a643b3db-90f2-4e3a-a486-a665796d4670', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What is the ANTONYM of ''Harmless'' in: ''A harmless garden snake''?', 'The antonym of ''harmless'' is ''harmful'', ''dangerous'', or ''venomous''.', NOW()) ON CONFLICT DO NOTHING;
