INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d8a8d20-e87e-4851-8312-3c8c66773bc9', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'Identify the part of speech of the underlined word in: ''The wheel wobbled **violently** in his hands.''', '''Violently'' is an adverb of manner modifying the intransitive verb ''wobbled''.', NOW()) ON CONFLICT DO NOTHING;
