INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('131530c5-6f3b-4e3a-95a8-fa9bb86cfa79', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'Convert the sentence into INDIRECT SPEECH:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('859004a6-f8c0-481b-b2cc-f300308a69dc', 'Mother told me that that kind was good and ate insects for food.', true, '131530c5-6f3b-4e3a-95a8-fa9bb86cfa79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92a8ba66-6ecf-4771-8b32-69dd85f6db47', 'Mother said that that kind is good.', false, '131530c5-6f3b-4e3a-95a8-fa9bb86cfa79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60c02804-1a6f-40e9-84f7-78a2dd99a8fd', 'Mother asked if the snake eats insects.', false, '131530c5-6f3b-4e3a-95a8-fa9bb86cfa79');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('beb5c929-ac38-415f-b778-a839dfafffcf', 'Mother told me don''t touch the snake.', false, '131530c5-6f3b-4e3a-95a8-fa9bb86cfa79');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('248a65d8-de23-42de-b115-d26c786d4b7f', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What is the rhyming scheme of Muriel L. Sonne''s poem ''Garden Snake''?', 'The poem employs simple, musical AABB rhyming couplets throughout.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc488977-5a9a-4d41-a293-b75ded6ca512', 'AABB (Rhyming couplets: away/say, good/food, grass/pass, mistake/snake)', true, '248a65d8-de23-42de-b115-d26c786d4b7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35fd51ee-8ae3-49c3-b87a-cee6d6f7f8a0', 'ABAB', false, '248a65d8-de23-42de-b115-d26c786d4b7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2542359c-fe26-495e-82b4-070f3009d839', 'ABCB', false, '248a65d8-de23-42de-b115-d26c786d4b7f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c499843b-4e87-45b9-922f-b45c01ec20ae', 'AABBCC', false, '248a65d8-de23-42de-b115-d26c786d4b7f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4d45860-d03c-4a59-b6ea-b3aed8ef2269', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What is the comedic irony in the title ''A Bicycle in Good Repair''?', 'Situational irony: a flawless bicycle is dismantled into junk under the guise of an expert ''repair''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29fbeecb-cd62-46f1-a456-cd3794fc112b', 'The bicycle was initially in perfect working condition, but by the time the acquaintance finished ''repairing'' it, it was completely ruined and unusable', true, 'e4d45860-d03c-4a59-b6ea-b3aed8ef2269');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09b4dbff-a248-4c2e-8791-8e30e5169d1e', 'The bicycle had gold wheels', false, 'e4d45860-d03c-4a59-b6ea-b3aed8ef2269');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4331b754-ca32-4f76-9f63-ae6e7aef16ef', 'The bicycle won a race', false, 'e4d45860-d03c-4a59-b6ea-b3aed8ef2269');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21c253c5-442b-43ff-a4be-fd1f6be746bb', 'The bicycle turned into a car', false, 'e4d45860-d03c-4a59-b6ea-b3aed8ef2269');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca42178c-02aa-4dba-9c6c-e921baf26101', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What did the acquaintance say about the front wheel after putting it back together missing half its ball bearings?', 'He shrugs off the missing bearings: ''"It''ll do for the present,"'' despite egregious wobbling.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4b739e2-c6c5-477e-af36-b7a91e70664b', '"It''ll do for the present," though it wobbled like a child''s toy top', true, 'ca42178c-02aa-4dba-9c6c-e921baf26101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96e2dd37-9c20-4819-b1c3-55f3883800a2', '"It is as good as new!"', false, 'ca42178c-02aa-4dba-9c6c-e921baf26101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df87b069-59f4-4ae4-95e0-9d0e2338711b', '"We should buy a new wheel."', false, 'ca42178c-02aa-4dba-9c6c-e921baf26101');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d967a020-927a-4b6d-b6e1-e48833815875', '"It can fly now!"', false, 'ca42178c-02aa-4dba-9c6c-e921baf26101');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9eb0070f-ed7c-4d38-a7c8-316664a01d59', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'What happened when the friend tried to put the chain back on the bicycle?', 'The chain episode is a masterclass in clumsy tinkering, swinging between unyielding tension and dangling slack.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e22c24d2-b091-457c-9bcf-a47a58846ed2', 'He completely lost the screws, struggled for an hour, and made it alternately too tight and too loose', true, '9eb0070f-ed7c-4d38-a7c8-316664a01d59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99d3b374-3111-41f9-a7d7-a6bc98b9ce37', 'He fixed it in two seconds', false, '9eb0070f-ed7c-4d38-a7c8-316664a01d59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('044f9ff9-64fd-4d6a-a47c-86724275f395', 'He replaced it with a gold chain', false, '9eb0070f-ed7c-4d38-a7c8-316664a01d59');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20562f01-19aa-4785-83c2-28e76fff5f8b', 'He gave up and walked away', false, '9eb0070f-ed7c-4d38-a7c8-316664a01d59');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba6cf7b8-189b-4715-909e-6d21e22a46a4', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Medium', 'How did the narrator finally get rid of the exhausting friend at the end of the day?', 'The ordeal concludes with the narrator escorting the exhausted, blackened tinkerer to the railway station.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dac9338-e1d3-4764-b9b7-ef6f8836936b', 'He took him to the railway station, sent him off home on a train, and breathed a sigh of immense relief', true, 'ba6cf7b8-189b-4715-909e-6d21e22a46a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0045580d-59fd-4455-a1ba-4b40c5776726', 'He gave him the bicycle as a gift', false, 'ba6cf7b8-189b-4715-909e-6d21e22a46a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('359d4cc3-fd7b-4acc-b7b3-d1d9896d3442', 'He called the police', false, 'ba6cf7b8-189b-4715-909e-6d21e22a46a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('177016e5-cf38-45fa-84a2-f27e18598b0c', 'He invited him to stay for a month', false, 'ba6cf7b8-189b-4715-909e-6d21e22a46a4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b365857-d68f-4e23-a217-785c7d95b46b', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3a106ff-7445-4e0c-a841-d1dc80bd6c87', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '4b365857-d68f-4e23-a217-785c7d95b46b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b260afaf-f7cf-4ec2-b9ea-a68cb41db888', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '4b365857-d68f-4e23-a217-785c7d95b46b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f3bebe0-f52e-4728-b70c-171483cc305c', '(A) is true, but (R) is false.', false, '4b365857-d68f-4e23-a217-785c7d95b46b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f45a961-7c99-48ec-8e68-8fd8f2e3984f', '(A) is false, but (R) is true.', false, '4b365857-d68f-4e23-a217-785c7d95b46b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f9e2b60c-321a-4164-87cf-73c3d7367ea0', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'Spot the IMPOSTER in the following sequence of mechanical catastrophes inflicted on the bicycle by the friend:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2e09ae7-e893-4f3c-833b-58031bbf3e85', 'Event 1', false, 'f9e2b60c-321a-4164-87cf-73c3d7367ea0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('586c59d6-0e3e-432e-85f9-2354eb7d0b5c', 'Event 2', false, 'f9e2b60c-321a-4164-87cf-73c3d7367ea0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9325ccdd-d0ce-48cf-9d73-bf7a496345bb', 'Event 3', false, 'f9e2b60c-321a-4164-87cf-73c3d7367ea0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35c54163-964d-4613-af7b-73792fe42d3a', 'Event 4 (Supersonic rocket engines do NOT belong to Jerome''s Victorian Victorian bicycling comedy)', true, 'f9e2b60c-321a-4164-87cf-73c3d7367ea0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('acb8ba12-7634-48fc-a6de-c307e0e30ee8', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'Analyze the psychological shift in ''Garden Snake'':
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77a8c2d8-b994-42bc-97d1-adf0303fa8b9', 'The child moves from unthinking cultural fear (''Some snakes are dangerous, they say'') to informed scientific understanding (''that kind is good / eats insects''), replacing blind panic with serene appreciation', true, 'acb8ba12-7634-48fc-a6de-c307e0e30ee8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c66bf15a-8c4f-4f30-b15d-ad7e4526bda3', 'The child learns how to capture snakes in jars', false, 'acb8ba12-7634-48fc-a6de-c307e0e30ee8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91a9ecd4-cd78-4938-a1ad-55ed5ca2931b', 'The child decides never to enter a garden again', false, 'acb8ba12-7634-48fc-a6de-c307e0e30ee8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6360001-45e7-46bc-8752-db8e0ae657cf', 'The child buys poison to spray on grass', false, 'acb8ba12-7634-48fc-a6de-c307e0e30ee8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('48ad19b2-43b5-47dc-8e97-6ffbd731a7aa', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'Match Column I (Narrative Episodes / Literary Devices) with Column II (Comic & Thematic Functions):
(a) Ball-Bearings in Hat      -> (i) Slapstick disaster when the hat blows off and rolls away
(b) Bicycle Wrestling Match    -> (ii) Personification of the bicycle fighting back against its torturer
(c) Mother''s Reassurance      -> (iii) Voice of ecological wisdom dispelling irrational fears
(d) Over-polite Narrator       -> (iv) Comedic straight-man character enabling escalating chaos', 'Hat = slapstick loss; Wrestling = personification; Mother = ecological wisdom; Narrator = enabling straight-man.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('419008f0-b9e7-4409-8eea-756c538faaa3', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '48ad19b2-43b5-47dc-8e97-6ffbd731a7aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2acc2c33-696b-4cc0-a406-cdd7810267dc', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '48ad19b2-43b5-47dc-8e97-6ffbd731a7aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28120445-c386-4202-b9ed-e79cfc924667', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '48ad19b2-43b5-47dc-8e97-6ffbd731a7aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c24dc2cc-201f-4b37-b40c-79499a2831bc', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '48ad19b2-43b5-47dc-8e97-6ffbd731a7aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c27e8aa8-9ad5-4657-a2c7-6816e8064279', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'Read the statements regarding Jerome K. Jerome''s comedic style:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34b7f9ae-34f3-422a-9b80-c7f9bd7844e0', 'Statements 1 and 2 only', true, 'c27e8aa8-9ad5-4657-a2c7-6816e8064279');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7a98136-4b1a-4338-b460-dffa82a67181', 'Statements 2 and 3 only', false, 'c27e8aa8-9ad5-4657-a2c7-6816e8064279');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('793b88f5-26ce-4070-b2f9-ccaab5b16a68', 'Statements 1 and 3 only', false, 'c27e8aa8-9ad5-4657-a2c7-6816e8064279');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2068b781-fd65-4e66-9949-b400b0c9163c', 'All Statements 1, 2, and 3', false, 'c27e8aa8-9ad5-4657-a2c7-6816e8064279');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3f44447c-527c-4bc1-b393-837ed25ff552', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'Identify the figure of speech in: ''The bicycle seemed to have also developed a malicious temper, leaping up and hitting him violently with its pedal.''', 'Personification endows the mechanical bicycle with deliberate malicious temper and physical aggression.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a6794a0-57ac-46ff-aec0-90f36832f8c0', 'Personification (attributing malicious intent and agency to an inanimate machine)', true, '3f44447c-527c-4bc1-b393-837ed25ff552');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d3d93e4-9656-4e17-8719-6129f707ae8d', 'Hyperbole only', false, '3f44447c-527c-4bc1-b393-837ed25ff552');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c5bc2ba-d162-454c-8b3f-5cac3deaa894', 'Simile', false, '3f44447c-527c-4bc1-b393-837ed25ff552');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7593d855-439d-4738-b51f-b83605bb8c2d', 'Alliteration only', false, '3f44447c-527c-4bc1-b393-837ed25ff552');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36666f0b-be11-4dd0-b4fe-559ff2a3c37e', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'What is the grammatical construction in: ''Had the narrator spoken firmly at the beginning, the bicycle would not have been ruined.''?', 'Third conditional with inverted protasis (''Had he spoken'' = ''If he had spoken'') expressing counterfactual past regret.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16547cce-1fea-49bf-9cac-5f140a1a4c34', 'Third Conditional (Inverted condition with past perfect ''Had he spoken'' and conditional perfect ''would not have been ruined'')', true, '36666f0b-be11-4dd0-b4fe-559ff2a3c37e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b91c1e2-ba39-46ec-bd1f-5baabe462105', 'First Conditional', false, '36666f0b-be11-4dd0-b4fe-559ff2a3c37e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3518c7e-eb46-489e-8b2e-d2e2dd58b99a', 'Second Conditional', false, '36666f0b-be11-4dd0-b4fe-559ff2a3c37e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c790b1b9-9d15-43ac-845f-f02caa0a9092', 'Imperative sentence', false, '36666f0b-be11-4dd0-b4fe-559ff2a3c37e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('481a05be-96ff-482f-90e9-a663906a703f', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'Why does Jerome K. Jerome emphasize the advice given by the experienced friend regarding the ''gear-case''?', 'The gear-case warning reinforces the core comedic theme: unnecessary meddling with functional machines invites catastrophe.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('379121d6-af71-4bf0-91ed-07635d0f4c9e', 'To underscore the timeless golden rule of mechanics: ''If it ain''t broke, don''t fix it'' — and to highlight the folly of tampering with complex mechanisms without expertise', true, '481a05be-96ff-482f-90e9-a663906a703f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9669b63-a633-4486-b4dd-bdabfce2507f', 'To encourage people to destroy their bicycles', false, '481a05be-96ff-482f-90e9-a663906a703f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b620d92-b0c5-473f-b4fc-3215a95f4eec', 'To advertise gear-case manufacturers', false, '481a05be-96ff-482f-90e9-a663906a703f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca2ab029-5c45-4ff7-883e-0b469dde30d0', 'Because gear-cases are dangerous weapons', false, '481a05be-96ff-482f-90e9-a663906a703f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('08693d85-064d-4e42-88ac-00c69ea06461', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'In ''Garden Snake'', what does the phrase ''There''s no mistake'' emphasize in the final line?', '''There''s no mistake'' affirms total intellectual certainty: rational comprehension replaces superstitious dread.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb9c327d-3ccb-4fdd-999a-6b4c70dd33b7', 'The child''s newfound absolute confidence in scientific understanding, banishing all lingering doubts and fears', true, '08693d85-064d-4e42-88ac-00c69ea06461');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('793f5fec-fc72-44ce-8610-57bbe3562546', 'That the child made a mistake in an exam', false, '08693d85-064d-4e42-88ac-00c69ea06461');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e49bdb4d-1cfa-41bf-ae23-db8b6bba551e', 'That the snake was a toy', false, '08693d85-064d-4e42-88ac-00c69ea06461');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b54dc130-da5b-433a-ba22-0a95b3568141', 'That the mother was wrong', false, '08693d85-064d-4e42-88ac-00c69ea06461');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('39352e6b-e7a5-4eb6-ae8f-5e41ceb23f65', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'What tone permeates the narrator''s observation: ''He was a person of boundless energy and incurable optimism, which made him all the more dangerous.''?', 'Deadpan irony: cheerful optimism paired with total incompetence is humorously diagnosed as a perilous combination.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21e46859-76f7-4b74-9a1a-9c673ba70c0b', 'Dry, ironic, deadpan British humor highlighting the menace of enthusiastic incompetence', true, '39352e6b-e7a5-4eb6-ae8f-5e41ceb23f65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55530166-98e9-499d-af6e-e145f6e17e91', 'Furious hatred and violent anger', false, '39352e6b-e7a5-4eb6-ae8f-5e41ceb23f65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30727017-45b1-4e9f-a63c-ddce00178f9a', 'Tearful grief and despair', false, '39352e6b-e7a5-4eb6-ae8f-5e41ceb23f65');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4e3116c-7b9e-4b85-ad2f-61513397d137', 'Boring scientific recitation', false, '39352e6b-e7a5-4eb6-ae8f-5e41ceb23f65');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b019e8b-d8dd-44a8-a52f-3cac4f514acc', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'Which of the following proverbs best captures the central moral lesson of ''A Bicycle in Good Repair''?', 'The story epitomizes Pope''s adage ''A little learning is a dangerous thing'' applied to meddlesome tinkering.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c01f5496-364c-45dc-9fc9-f5ff1d807fe0', '"A little learning is a dangerous thing" / "Leave well enough alone"', true, '6b019e8b-d8dd-44a8-a52f-3cac4f514acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efa1b7c0-c6f5-4984-b4e1-f4133ee4989f', '"All that glitters is not gold"', false, '6b019e8b-d8dd-44a8-a52f-3cac4f514acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e656f963-c845-4c4e-bc61-782ba75cccd1', '"A rolling stone gathers no moss"', false, '6b019e8b-d8dd-44a8-a52f-3cac4f514acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f922b4aa-13b4-4804-9ddf-86e9ba16fe85', '"Look before you leap into water"', false, '6b019e8b-d8dd-44a8-a52f-3cac4f514acc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a5cf6a1-437b-40e1-adf1-72f557f4614b', 'Class 7', 'English', 'Chapter 9: A Bicycle in Good Repair & Garden Snake', 'Hard', 'What overarching humanist message unites Chapter 9 of NCERT Class 7 English?', 'Chapter 9 weaves together social psychology, self-assertiveness, comedic humility, and rational coexistence with nature.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('890f5281-628f-4b3e-b380-585649fdd0c7', 'The balance between polite social boundaries, humble self-awareness of one''s own limitations, and the courage to replace irrational superstitions with gentle ecological understanding', true, '7a5cf6a1-437b-40e1-adf1-72f557f4614b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8013a75f-9b83-4217-b035-9c65d60f762f', 'That bicycles should never be ridden by anyone', false, '7a5cf6a1-437b-40e1-adf1-72f557f4614b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34e3e088-93ee-404d-867e-825cf0bd49df', 'That snakes should be kept inside houses', false, '7a5cf6a1-437b-40e1-adf1-72f557f4614b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6ca382c-5bef-4808-93ad-d92dfb2c7630', 'That all repairs should be done with hammers', false, '7a5cf6a1-437b-40e1-adf1-72f557f4614b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c2343942-6278-44ec-af50-03deacf3ba68', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'In which year did the American Revolution reach its climax with the adoption of the historic ''Declaration of Independence'' on July 4?', 'The Second Continental Congress adopted the Declaration of Independence penned by Thomas Jefferson on 4 July 1776.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9fee8d9-8cff-4bdd-b43f-227fc0b0f63c', '1776', true, 'c2343942-6278-44ec-af50-03deacf3ba68');
