INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe21a9ff-698f-41df-a39a-c7c92fd3c2bb', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'What historic event on July 14, 1789, in Paris marked the explosive outbreak of the FRENCH REVOLUTION?', 'The storming of the royal fortress-prison Bastille on 14 July 1789 became the symbol of the French Revolution (celebrated as Bastille Day).', NOW()) ON CONFLICT DO NOTHING;
