INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('67373d74-a588-4edb-891d-d5b2dacc9b36', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'Who led the Bolsheviks in the 1917 October Russian Revolution to overthrow the Provisional Government and establish the world''s first socialist state (USSR)?', 'Vladimir Lenin led the Bolshevik party to victory in 1917 under the slogan ''Peace, Land, and Bread'', founding the Soviet Union.', NOW()) ON CONFLICT DO NOTHING;
