INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('140fa1aa-51f3-4b38-8359-2549cd5da0fd', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'Which aggressive military action by Nazi Germany on September 1, 1939, triggered the immediate outbreak of WORLD WAR II?', 'Hitler''s blitzkrieg invasion of Poland on 1 Sept 1939 forced Britain and France to declare war on Nazi Germany, igniting WWII.', NOW()) ON CONFLICT DO NOTHING;
