INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ff821d8-bbf0-4070-8ee4-2e593202c786', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'What surprise military strike by Imperial Japan on December 7, 1941, brought the United States directly into World War II?', 'Japan''s carrier air raid on Pearl Harbor crippled the US Pacific Fleet and prompted US President Franklin D. Roosevelt''s declaration of war.', NOW()) ON CONFLICT DO NOTHING;
