INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('437212c3-c1a3-484e-b7f3-ef40119ab7ee', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'What concrete barrier built in 1961 divided East and West Berlin during the Cold War, whose dramatic fall in November 1989 symbolized the collapse of communism in Eastern Europe?', 'The Berlin Wall fell on 9 November 1989, paving the way for German reunification and the dissolution of the Soviet bloc.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b08a3a3e-7ac3-44af-945a-2acb821676cb', 'The Berlin Wall', true, '437212c3-c1a3-484e-b7f3-ef40119ab7ee');
