INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('31c9e8ff-8878-49c2-9f4f-a0860a984037', 'The Maginot Line', false, '437212c3-c1a3-484e-b7f3-ef40119ab7ee');
