INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0804daea-b444-45d2-b5a2-e5b908a1dffe', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Easy', 'Who was the First Prime Minister of India who co-founded the NON-ALIGNED MOVEMENT (NAM) in 1961 along with President Tito of Yugoslavia and President Nasser of Egypt?', 'Jawaharlal Nehru, Josip Broz Tito, Gamal Abdel Nasser, Sukarno, and Kwame Nkrumah founded NAM in Belgrade (1961) to resist Cold War superpower blocs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2021478-ef1b-4b11-a967-501d8e6f8277', 'Pandit Jawaharlal Nehru', true, '0804daea-b444-45d2-b5a2-e5b908a1dffe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7ff2063-c6de-42ec-9401-80c4f0a45b08', 'Mahatma Gandhi', false, '0804daea-b444-45d2-b5a2-e5b908a1dffe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd6c6d89-d3d5-4837-adfc-192578498fcc', 'Sardar Patel', false, '0804daea-b444-45d2-b5a2-e5b908a1dffe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78b6a98e-b879-4f94-905f-188ce742247a', 'Dr. B.R. Ambedkar', false, '0804daea-b444-45d2-b5a2-e5b908a1dffe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ee92c0f2-f1e7-4d4e-86a8-e7e20970becd', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Boston Tea Party'' of December 16, 1773, that escalated tensions leading to the American Revolutionary War?', 'The Sons of Liberty dumped British tea to protest the Tea Act (1773), rallying the famous slogan ''No taxation without representation''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffda1c16-1f52-4c9c-9026-699a2bc265f7', 'American colonists disguised as Mohawk Indians dumped 342 chests of British East India Company tea into Boston Harbor to protest unfair taxation without representation', true, 'ee92c0f2-f1e7-4d4e-86a8-e7e20970becd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f150472b-6fc2-469c-a784-1fbec2ebef9a', 'A tea drinking festival in Boston', false, 'ee92c0f2-f1e7-4d4e-86a8-e7e20970becd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfbd69ce-118f-4443-99b4-71e024f32666', 'A British tea factory opening', false, 'ee92c0f2-f1e7-4d4e-86a8-e7e20970becd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06a3905d-eb50-4366-ac48-1975885e6190', 'A peaceful trade agreement between Britain and America', false, 'ee92c0f2-f1e7-4d4e-86a8-e7e20970becd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd4c9eb1-b390-49f0-9007-bc4fae0400d6', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Reign of Terror'' (1793–1794) during the French Revolution led by Maximilien Robespierre?', 'Robespierre''s Jacobin regime executed over 17,000 citizens by guillotine until Robespierre himself was overthrown in the Thermidorian Reaction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f164393-b6ca-4983-88d9-cf32e583c89f', 'A period where the Committee of Public Safety executed tens of thousands of suspected ''counter-revolutionaries'' using the Guillotine', true, 'fd4c9eb1-b390-49f0-9007-bc4fae0400d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21730b6d-1b08-47ea-afbd-73cd38bf194f', 'A war with Spain', false, 'fd4c9eb1-b390-49f0-9007-bc4fae0400d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f4576c2-4423-4505-8a24-089c0d8dd385', 'A famine caused by freezing winter', false, 'fd4c9eb1-b390-49f0-9007-bc4fae0400d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdb44db9-3b52-4634-9c7d-427ea3676067', 'A military coup by Napoleon', false, 'fd4c9eb1-b390-49f0-9007-bc4fae0400d6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('492cde05-fea4-46c1-bff1-a7b8a82ba895', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'Which battle in 1815 in modern-day Belgium marked the final, decisive military defeat of Emperor Napoleon Bonaparte?', 'Napoleon was decisively routed at Waterloo on 18 June 1815, leading to his exile on the remote South Atlantic island of Saint Helena.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ed6342d-bccf-454e-b3e3-355556b3bbb9', 'The Battle of Waterloo (defeated by Duke of Wellington and Blücher)', true, '492cde05-fea4-46c1-bff1-a7b8a82ba895');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc8be5c3-9c55-44c1-af72-d1366cfd54b7', 'The Battle of Austerlitz', false, '492cde05-fea4-46c1-bff1-a7b8a82ba895');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45ae6a37-edf5-495f-8802-57abb521acbf', 'The Battle of Trafalgar', false, '492cde05-fea4-46c1-bff1-a7b8a82ba895');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8953e9eb-5bb2-4714-8cbf-6eb73f1793a9', 'The Battle of Leipzig', false, '492cde05-fea4-46c1-bff1-a7b8a82ba895');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9fa71a0c-12d7-4b81-80a6-5fe51a58a4c4', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'Why is the Industrial Revolution considered a fundamental turning point in human civilization?', 'Mechanized mass manufacturing, urban industrialization, railways, and fossil energy fundamentally reshaped global demography and socio-economics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34e62059-2554-471f-ab1e-4a4420b2497d', 'It transformed agrarian, hand-craft economies into industrial, machine-driven manufacturing powerhouses fueled by steam, coal, electricity, and mass factory production', true, '9fa71a0c-12d7-4b81-80a6-5fe51a58a4c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('666d1542-0165-45e9-94b4-b86aa72105af', 'It abolished all farming forever', false, '9fa71a0c-12d7-4b81-80a6-5fe51a58a4c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8cd4539-4a32-45a1-bf4c-005a99bfda1e', 'It made everyone become soldiers', false, '9fa71a0c-12d7-4b81-80a6-5fe51a58a4c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22279d41-0138-4924-8e2d-643ee5d6eff3', 'It stopped world trade', false, '9fa71a0c-12d7-4b81-80a6-5fe51a58a4c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('70eaf2ea-d6e0-4286-b840-ea2b28f13fa1', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Great Depression'' that began with the catastrophic Wall Street Stock Market Crash in October 1929 (''Black Tuesday'')?', 'The 1929 crash plunged global economies into severe contraction, deflation, and catastrophic unemployment until WWII rearmament.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dd1b363-6721-44c4-89b3-8f6a5cafeb3c', 'The longest, deepest, and most widespread economic collapse of the 20th century, leading to mass unemployment, bank failures, and trade collapse worldwide', true, '70eaf2ea-d6e0-4286-b840-ea2b28f13fa1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9aede090-b4d0-4f08-9fc4-bcb1e65847b4', 'A medical disease in 1929', false, '70eaf2ea-d6e0-4286-b840-ea2b28f13fa1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d71e6a93-0256-413a-9a31-67521935b703', 'A storm that flooded America', false, '70eaf2ea-d6e0-4286-b840-ea2b28f13fa1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23391506-6b55-4e9c-8ef5-1c42fbbab2b8', 'A war between banks', false, '70eaf2ea-d6e0-4286-b840-ea2b28f13fa1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca68e3d2-64a2-468b-839f-865e60f4c9eb', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Battle of Stalingrad'' (1942–1943) in World War II, widely considered the decisive turning point on the European Eastern Front?', 'Stalingrad was the bloodiest battle in human history (~2 million casualties); the Soviet victory broke the backbone of the Wehrmacht.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f2f8d20f-098c-4a60-86d3-e0008a1bdf8e', 'The bloody Soviet defense that completely encircled and destroyed the German 6th Army, reversing the Nazi advance and beginning Germany''s retreat to Berlin', true, 'ca68e3d2-64a2-468b-839f-865e60f4c9eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95fab12e-0beb-497e-a464-e29f928f5287', 'A naval battle in the Atlantic', false, 'ca68e3d2-64a2-468b-839f-865e60f4c9eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25f10b62-6f78-4903-bcdf-5c4cf69cbf2e', 'An aerial dogfight over London', false, 'ca68e3d2-64a2-468b-839f-865e60f4c9eb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8456d73d-9bc2-4e0a-a75c-9b1f3a952557', 'A tank battle in North Africa', false, 'ca68e3d2-64a2-468b-839f-865e60f4c9eb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be3e67a3-af82-4a41-a1d8-03cae6bef9fe', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was ''D-Day'' (Operation Overlord) on June 6, 1944?', 'General Dwight D. Eisenhower commanded the largest amphibious armada in history landing across Normandy beaches on 6 June 1944.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aced2b06-8238-4737-8ae3-ec8e6bb4035a', 'The massive Allied amphibious invasion of Normandy (France) by American, British, and Canadian forces, establishing a western front to liberate Europe from Nazi occupation', true, 'be3e67a3-af82-4a41-a1d8-03cae6bef9fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1df4c084-e24c-4e5a-99b3-33ab71bb7e1f', 'The surrender of Japan', false, 'be3e67a3-af82-4a41-a1d8-03cae6bef9fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32e5668e-3f79-4b29-a1c1-cdee8ba192fb', 'The German invasion of Russia', false, 'be3e67a3-af82-4a41-a1d8-03cae6bef9fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8087e32e-abb7-48b5-886f-3e874718c86e', 'The signing of the UN Charter', false, 'be3e67a3-af82-4a41-a1d8-03cae6bef9fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ce23c0f-5a11-4ce4-a0e4-2eb9a0cac171', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Cuban Missile Crisis'' in October 1962 during the Cold War?', 'The 1962 crisis was the closest the Cold War came to full-scale thermonuclear war, resolved by Soviet missile withdrawal and US pledge not to invade Cuba.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b412eb3-ee8c-4b2a-9109-29a0b1ec617b', 'A perilous 13-day nuclear standoff between the USA (President Kennedy) and USSR (Premier Khrushchev) over Soviet nuclear missiles deployed in Cuba, bringing the world to the brink of nuclear war', true, '3ce23c0f-5a11-4ce4-a0e4-2eb9a0cac171');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dcb3bc5-0e63-4be7-bfe4-daea5b690ed7', 'A civil war in Cuba', false, '3ce23c0f-5a11-4ce4-a0e4-2eb9a0cac171');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26fb3b4c-788d-47c2-aaa9-44349b90816d', 'The invasion of Florida', false, '3ce23c0f-5a11-4ce4-a0e4-2eb9a0cac171');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3e06be3-a94e-477f-92a5-f7dffb43405c', 'A missile test in the Arctic', false, '3ce23c0f-5a11-4ce4-a0e4-2eb9a0cac171');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6d69ef3-9e7d-4658-b0be-b63e89da42ed', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Holocaust'' perpetrated by Nazi Germany during World War II?', 'The Shoah / Holocaust was the horrific Nazi genocide that exterminated two-thirds of European Jewry in gas chambers and death camps.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16b9e902-83c9-4c93-930b-5528a7cb39ad', 'The systematic, state-sponsored genocide of six million European Jews and millions of others (Roma, Slavs, dissidents) in industrialized extermination camps (like Auschwitz-Birkenau)', true, 'e6d69ef3-9e7d-4658-b0be-b63e89da42ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1de21577-65e9-4263-b5cd-de06ab63645f', 'A military parade in Berlin', false, 'e6d69ef3-9e7d-4658-b0be-b63e89da42ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72b57512-792f-405c-ae2e-689b74d93dcf', 'A medical experiment with antibiotics', false, 'e6d69ef3-9e7d-4658-b0be-b63e89da42ed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26780087-bc4f-4450-b3f9-950cc870fc35', 'A treaty between Germany and Italy', false, 'e6d69ef3-9e7d-4658-b0be-b63e89da42ed');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e46b390-62a8-4722-8d47-899581b6be93', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Marshall Plan'' (European Recovery Program) enacted by the United States in 1948?', 'Initiated by US Secretary of State George Marshall, the plan revived Western European industrial production and economic stability.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cabc13c5-9a98-4c6e-ba33-842b56460268', 'A massive American financial foreign-aid program ($13+ billion) to rebuild war-devastated Western European economies and prevent the spread of Soviet communism', true, '5e46b390-62a8-4722-8d47-899581b6be93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('966f294b-d545-4ea7-b04c-655275de60fe', 'A military plan to conquer Asia', false, '5e46b390-62a8-4722-8d47-899581b6be93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b33b6aa6-79c9-426b-a2b6-6230928aa727', 'A plan to build spaceships', false, '5e46b390-62a8-4722-8d47-899581b6be93');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f797718-7995-45b7-ba4a-36116c8e8da6', 'A treaty to divide Germany', false, '5e46b390-62a8-4722-8d47-899581b6be93');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd10da1d-3ae6-4c97-bb8f-f9caa4c1a530', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'Which international treaty signed in 1968 aimed at preventing the spread of nuclear weapons and promoting nuclear disarmament?', 'The NPT (1968) established three pillars: non-proliferation, peaceful use of nuclear technology, and disarmament.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c8d7230-2436-4bda-8871-e1d1a0b3861a', 'The Treaty on the Non-Proliferation of Nuclear Weapons (NPT)', true, 'fd10da1d-3ae6-4c97-bb8f-f9caa4c1a530');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f43692d9-4c92-4888-ab22-696b88577b55', 'The Kyoto Protocol', false, 'fd10da1d-3ae6-4c97-bb8f-f9caa4c1a530');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6736f4d9-9040-43a4-b30c-2be840d53f53', 'The Geneva Convention', false, 'fd10da1d-3ae6-4c97-bb8f-f9caa4c1a530');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2af07a45-fe7b-4997-9189-b9b09ab92217', 'The Warsaw Pact', false, 'fd10da1d-3ae6-4c97-bb8f-f9caa4c1a530');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98a40d06-b8f0-407c-9de2-434cd1c642e8', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Meiji Restoration'' (1868) in Japanese history?', 'The Meiji era transformed feudal samurai Japan into an industrialized, modernized constitutional empire in just a few decades.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('020bb246-53bf-41da-b45c-f75f25c7f304', 'The political revolution that ended the Tokugawa Shogunate, restored imperial rule under Emperor Meiji, and rapidly modernized and industrialized Japan into a global power', true, '98a40d06-b8f0-407c-9de2-434cd1c642e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4e5268d-3a2f-40b9-b444-3758ad04e833', 'The construction of Tokyo city', false, '98a40d06-b8f0-407c-9de2-434cd1c642e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2599668-aa2f-4a10-8ef3-d03de08d77f6', 'The adoption of Buddhism in Japan', false, '98a40d06-b8f0-407c-9de2-434cd1c642e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6a0e782-a2f4-4279-8772-1323971c9db3', 'The isolation of Japan from the world', false, '98a40d06-b8f0-407c-9de2-434cd1c642e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('10870927-c66f-4127-90ed-72ef94f9b7a6', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'Who was the South African anti-apartheid leader who spent 27 years imprisoned on Robben Island and became South Africa''s first black President in 1994?', 'Nelson Mandela led the ANC''s struggle against racial apartheid, earning the Nobel Peace Prize and inspiring global human rights.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('619e6ff6-2cdf-4a2b-942b-5c581fa1779c', 'Nelson Mandela', true, '10870927-c66f-4127-90ed-72ef94f9b7a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27d4468d-99d1-4f97-a350-432dad00a01b', 'Desmond Tutu', false, '10870927-c66f-4127-90ed-72ef94f9b7a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64a3ce61-93d5-4f40-864e-d7259f4bcc14', 'Kofi Annan', false, '10870927-c66f-4127-90ed-72ef94f9b7a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7014342-4188-46e5-aa26-b1a57e21ebb0', 'Robert Mugabe', false, '10870927-c66f-4127-90ed-72ef94f9b7a6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53a89907-a3a2-4a23-87d7-70ceed254499', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What was the ''Bandung Conference'' held in Indonesia in 1955?', 'The 1955 Bandung Conference articulated the Panchsheel principles and catalyzed the post-colonial Third World solidarity movement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8466d919-c945-4796-b7bf-3c1e415919f3', 'A landmark summit of 29 Asian and African nations promoting Afro-Asian economic and cultural cooperation and opposing colonialism, which laid the foundation for the Non-Aligned Movement', true, '53a89907-a3a2-4a23-87d7-70ceed254499');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b704e8b6-2fc0-48e9-93b9-a7601afbea6f', 'A trade summit of European bankers', false, '53a89907-a3a2-4a23-87d7-70ceed254499');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da84c856-07aa-4bb5-8b33-5ff601d2332d', 'A military meeting of NATO', false, '53a89907-a3a2-4a23-87d7-70ceed254499');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb9a6a6c-e582-40a1-9fab-2dbbddafda6f', 'A sports competition in Asia', false, '53a89907-a3a2-4a23-87d7-70ceed254499');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('adcd109e-05a9-4cb6-804c-1915c8e56918', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'What policies of ''Glasnost'' (Openness) and ''Perestroika'' (Restructuring) introduced by Soviet leader Mikhail Gorbachev in the late 1980s led to the dissolution of the Soviet Union in December 1991?', 'Gorbachev''s dual reforms intended to revitalize the USSR unleashed unstoppable democratic movements culminating in the peaceful collapse of the Soviet Union.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04a9b6a6-3667-453b-8707-e780c6831018', 'Political democratization, freedom of the press, and economic decentralization that unintentionally dismantled Soviet totalitarian control', true, 'adcd109e-05a9-4cb6-804c-1915c8e56918');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('775f2bfa-24ea-445f-b7a9-3946902910f4', 'A plan to start a war with China', false, 'adcd109e-05a9-4cb6-804c-1915c8e56918');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc423fda-26ca-4360-acfa-f1b9e21935c5', 'The banning of all private businesses', false, 'adcd109e-05a9-4cb6-804c-1915c8e56918');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cbc28c3-3862-4d35-8b25-878675d14897', 'The building of new missile bases', false, 'adcd109e-05a9-4cb6-804c-1915c8e56918');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e12b420-30bb-4cff-adf6-90c88bbaac27', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Medium', 'Which international treaty signed in 1992 created the European Union (EU) and laid the groundwork for the single European currency (the Euro)?', 'The Maastricht Treaty (1992) established the European Union, European citizenship, and the Economic and Monetary Union (Eurozone).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d840ae97-6b00-4bc4-9b71-b08bfd8cc0fc', 'The Maastricht Treaty', true, '9e12b420-30bb-4cff-adf6-90c88bbaac27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3a73bd5-c42a-4980-9552-2465d41f124b', 'The Treaty of Rome', false, '9e12b420-30bb-4cff-adf6-90c88bbaac27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b21af64-ad35-42d2-b1d8-0275e5eed846', 'The Schengen Agreement', false, '9e12b420-30bb-4cff-adf6-90c88bbaac27');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9270683c-a7cf-4972-8a69-15ad7c8d61c1', 'The Lisbon Treaty', false, '9e12b420-30bb-4cff-adf6-90c88bbaac27');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('83d67e25-4558-4e3a-9b77-ec8922edfcdd', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('829ff2a1-f443-45fb-a0cc-58b6e7b2b682', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '83d67e25-4558-4e3a-9b77-ec8922edfcdd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67c0ded3-b2d7-4f92-91d2-c74e5c77a69e', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '83d67e25-4558-4e3a-9b77-ec8922edfcdd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09985680-ebc4-4d2c-9e32-304e38021bcb', '(A) is true, but (R) is false.', false, '83d67e25-4558-4e3a-9b77-ec8922edfcdd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f279a474-a04c-4a9f-8b71-106014c7323d', '(A) is false, but (R) is true.', false, '83d67e25-4558-4e3a-9b77-ec8922edfcdd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7525eb5c-b9f4-4360-83cf-49d570bd4366', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'Spot the IMPOSTER in the following major World Revolutions and their defining historical milestones:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2741728d-1258-48bb-a727-d08da2b8ff14', 'Revolution 1', false, '7525eb5c-b9f4-4360-83cf-49d570bd4366');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25961ea4-437e-40f9-9e9e-2bbdb386751f', 'Revolution 2', false, '7525eb5c-b9f4-4360-83cf-49d570bd4366');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('605043e8-1595-421d-8ed2-6e784a8dbaca', 'Revolution 3', false, '7525eb5c-b9f4-4360-83cf-49d570bd4366');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9145465e-3929-4b4f-aa7e-85f465a8c5d4', 'Revolution 4 (The First Industrial Revolution involved steam engines, mechanized spinning jenny, and ironworks, NOT 21st-century smartphones)', true, '7525eb5c-b9f4-4360-83cf-49d570bd4366');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd97b75b-2619-405d-a213-cae83dca5a3c', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'Analyze the geopolitical mechanism of the ''Cold War'' (1947–1991):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd4d1701-3632-4a0e-bb7b-6cfb88df9b01', 'The two nuclear-armed superpowers (USA and USSR) never engaged in direct direct military combat against each other due to Mutually Assured Destruction (MAD), fighting instead through ideological rivalry, proxy wars (Korea, Vietnam), the nuclear arms race, and the Space Race', true, 'dd97b75b-2619-405d-a213-cae83dca5a3c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57eb6513-bd69-45ca-ac75-938650d0881f', 'Because all battles were fought in freezing Siberia', false, 'dd97b75b-2619-405d-a213-cae83dca5a3c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('458533d2-c5b4-44eb-b936-16961a834157', 'Because both countries banned the use of gunpowder', false, 'dd97b75b-2619-405d-a213-cae83dca5a3c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('345d600d-dedc-4b39-ab9a-ec6ff8792275', 'Because wars were fought only in winter months', false, 'dd97b75b-2619-405d-a213-cae83dca5a3c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f011a9ef-d97a-4722-8629-d2e9c0b47f4b', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'Match Column I (Historic Global Summits / Treaties) with Column II (Defining Historical Milestones):
(a) Treaty of Westphalia (1648) -> (i) Established modern nation-state sovereignty and diplomatic immunity
(b) Congress of Vienna (1815)     -> (ii) Restored European balance of power after the fall of Napoleon
(c) Yalta Conference (1945)      -> (iii) Churchill, Roosevelt, and Stalin planned the post-WWII division of Europe
(d) Geneva Conventions (1949)    -> (iv) Codified international humanitarian laws of war and prisoner protection', 'Westphalia = state sovereignty; Vienna = post-Napoleonic balance; Yalta = post-WWII spheres; Geneva = laws of war.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('682e0400-1067-4240-a298-415d8047e6a8', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'f011a9ef-d97a-4722-8629-d2e9c0b47f4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a240d0d-1eea-40bb-aaf2-27dfb3e19ee4', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'f011a9ef-d97a-4722-8629-d2e9c0b47f4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96d539ed-69e9-4e64-9e72-d0e9ce23c45d', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'f011a9ef-d97a-4722-8629-d2e9c0b47f4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66cf6969-bc65-41a3-a6fd-d49a4367aa1f', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'f011a9ef-d97a-4722-8629-d2e9c0b47f4b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23c2f35b-0926-47b8-b7f5-6b78d2426e5d', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'Read the statements regarding the Decolonization era (1945–1975):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9337581-b3fa-41aa-9497-f33b0bbebca4', 'Statements 1 and 2 only', true, '23c2f35b-0926-47b8-b7f5-6b78d2426e5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('048c547d-2e70-4ad1-a71b-1eea96aa2395', 'Statements 2 and 3 only', false, '23c2f35b-0926-47b8-b7f5-6b78d2426e5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b616b88-e3f7-4c1a-bf14-d04d8184f8e3', 'Statements 1 and 3 only', false, '23c2f35b-0926-47b8-b7f5-6b78d2426e5d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25c105f7-b98a-4d24-915a-ea8704df823c', 'All Statements 1, 2, and 3', false, '23c2f35b-0926-47b8-b7f5-6b78d2426e5d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fb44bd42-962f-41b1-b73d-89dcf7ec3762', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'What was the significance of the ''Nuremberg Trials'' (1945–1946) conducted after World War II?', 'Nuremberg established modern international criminal law: leaders cannot claim sovereign immunity or ''following orders'' for crimes against humanity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e179422d-12f6-49f4-9b1e-06a627665f8a', 'The historic international military tribunal that prosecuted top Nazi leaders for ''Crimes Against Peace'', ''War Crimes'', and ''Crimes Against Humanity'', establishing individual legal accountability under international law', true, 'fb44bd42-962f-41b1-b73d-89dcf7ec3762');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1273c407-3655-40bc-8fb9-870e1adb3f9d', 'A conference to set world oil prices', false, 'fb44bd42-962f-41b1-b73d-89dcf7ec3762');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51d828bc-0fea-454c-84d2-321ea5fd1c60', 'The division of Berlin into zones', false, 'fb44bd42-962f-41b1-b73d-89dcf7ec3762');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af1656db-88f9-4b49-a965-ef2e534de8e0', 'The creation of the Euro currency', false, 'fb44bd42-962f-41b1-b73d-89dcf7ec3762');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6975a406-4ffd-4792-86df-047ff8b8139c', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'What was the ''Space Race'' between the USA and the USSR during the Cold War?', 'The Space Race showcased ideological and technological superiority: Soviet orbital triumphs balanced by Apollo 11''s historic lunar landing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89cad378-657c-4eb3-b266-b5ab29ca6f00', 'A high-stakes scientific-technological competition for space dominance: USSR launched the first satellite (Sputnik, 1957) and first human in space (Yuri Gagarin, 1961) ; USA achieved the first manned Moon landing (Apollo 11, Neil Armstrong, 1969)', true, '6975a406-4ffd-4792-86df-047ff8b8139c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8754c6bf-88f1-44f2-89e9-24e0ec0a3367', 'A military battle fought with space laser weapons on Mars', false, '6975a406-4ffd-4792-86df-047ff8b8139c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d0cb86d-0517-4464-9eac-d7ebb73c2088', 'A race to build the tallest skyscraper', false, '6975a406-4ffd-4792-86df-047ff8b8139c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57b4529b-46df-4180-9c0b-b2f21d14b3e8', 'A telescope building competition', false, '6975a406-4ffd-4792-86df-047ff8b8139c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e5e7f1e-c05e-4565-9da8-ddb746e87799', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'Consider four major global economic and geopolitical institutions established at the 1944 Bretton Woods Conference:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78d24efd-68fa-48c8-9048-9a240c3f70fc', 'To prevent global depressions through stable international exchange rates, finance post-war reconstruction, and foster open multilateral international trade', true, '6e5e7f1e-c05e-4565-9da8-ddb746e87799');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bea6ec07-4cb1-4071-b9a6-8554df4eaf95', 'To enforce military occupation over poor nations', false, '6e5e7f1e-c05e-4565-9da8-ddb746e87799');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb7d470b-1e5e-4c83-9a83-7d03947545a4', 'To abolish all paper money worldwide', false, '6e5e7f1e-c05e-4565-9da8-ddb746e87799');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a86e080-3d25-407b-a205-cf3d1beaa58b', 'To print a single world newspaper', false, '6e5e7f1e-c05e-4565-9da8-ddb746e87799');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8faca086-285b-4087-96f6-4c0605690777', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'Why was the ''Suez Crisis'' (1956) a watershed moment in the decline of British and French imperial dominance?', 'The 1956 Suez debacle revealed that old European colonial powers could no longer exercise independent global military force without US consent.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a94c09c-23a3-4d9c-9b69-86a9489a6221', 'When Britain, France, and Israel invaded Egypt after President Nasser nationalized the Suez Canal, diplomatic condemnation and economic pressure from both the US and USSR forced a humiliating Anglo-French withdrawal, cementing the end of European imperial hegemony', true, '8faca086-285b-4087-96f6-4c0605690777');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00fd770e-822c-423a-90b8-efe12f15e21b', 'Because Egypt conquered all of Europe', false, '8faca086-285b-4087-96f6-4c0605690777');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d583ba0-f3b2-46a7-953f-ed97c42e045b', 'Because the canal was filled with concrete', false, '8faca086-285b-4087-96f6-4c0605690777');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6841a621-3c0d-4d7f-88bf-01573b43f316', 'Because Britain annexed Egypt permanently', false, '8faca086-285b-4087-96f6-4c0605690777');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34ea80ae-f97a-4cce-9386-f52cebf3d5a1', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'What is the historical significance of the ''Universal Declaration of Human Rights'' (UDHR) adopted by the UN General Assembly on December 10, 1948?', 'Adopted in Paris (10 Dec 1948, Human Rights Day), the 30 articles of the UDHR enshrine inalienable civil, political, economic, and social rights.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5a52594-63e4-4ef0-a974-459b2ad155ed', 'The first global proclamation of fundamental human rights to be universally protected for all human beings everywhere, authored by a diverse committee chaired by Eleanor Roosevelt', true, '34ea80ae-f97a-4cce-9386-f52cebf3d5a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abdcf5a7-4d56-4dce-9ec0-56b4585c58f5', 'A treaty that ended the Korean war', false, '34ea80ae-f97a-4cce-9386-f52cebf3d5a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d80ec2a-06a0-4aa0-9188-1dddfc2a66f7', 'A law allowing countries to buy nuclear weapons', false, '34ea80ae-f97a-4cce-9386-f52cebf3d5a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40be8539-f6e9-4bf4-ad94-9c4c7e31dff1', 'A rule on maritime fishing quotas', false, '34ea80ae-f97a-4cce-9386-f52cebf3d5a1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('466bfbae-726b-41fd-9b9f-a0cd1d2fa816', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'What historic transformation occurred in South Africa with the 1994 General Election?', 'The 1994 election birthed the multiracial ''Rainbow Nation'', inaugurating a democratic constitutional state underpinned by truth and reconciliation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30bbc586-1139-4953-bf34-24b866dede13', 'The peaceful end of four decades of institutionalized white-minority Apartheid, and the election of Nelson Mandela as President in the country''s first fully representative multiracial democratic election', true, '466bfbae-726b-41fd-9b9f-a0cd1d2fa816');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e6a6930-ca24-4831-b1a6-aabe5f920736', 'The partition of South Africa into four countries', false, '466bfbae-726b-41fd-9b9f-a0cd1d2fa816');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e02dd7da-b604-4ca3-b84b-6a610dab5d04', 'The coronation of a new British monarch', false, '466bfbae-726b-41fd-9b9f-a0cd1d2fa816');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd86ce14-1e04-4e41-a809-5b2ad6999040', 'The expulsion of all foreign diplomats', false, '466bfbae-726b-41fd-9b9f-a0cd1d2fa816');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('48352cde-7ef6-4f0e-8501-31c5a5fec003', 'Class 7', 'GK', 'Chapter 9: Modern World History, Revolutions, World Wars & Landmark Treaties', 'Hard', 'What overarching historical lesson is illuminated in Chapter 9 of General Knowledge?', 'Chapter 9 synthesizes modern revolutions, the trauma of total wars, the Cold War balance of power, decolonization, and the quest for universal human rights.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0482c055-e823-467a-9c5d-22eb9e5e93ee', 'Modern world history is a dynamic chronicle of humanity''s unrelenting struggle for liberty, equality, scientific modernization, and international legal institutions to replace imperial domination and catastrophic wars with peaceful global multilateral cooperation', true, '48352cde-7ef6-4f0e-8501-31c5a5fec003');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aff72784-25e6-4f89-af4b-62dec84641ec', 'That wars are always inevitable and peace is impossible', false, '48352cde-7ef6-4f0e-8501-31c5a5fec003');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11f2d1f5-183f-48dc-9e9c-1a274930df52', 'That only monarchs should rule the world', false, '48352cde-7ef6-4f0e-8501-31c5a5fec003');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d36c68b2-60fa-4da8-84ce-5714e6953435', 'That technology has never changed human society', false, '48352cde-7ef6-4f0e-8501-31c5a5fec003');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f68b0364-3eff-4c97-a6ce-97b7736f9ef6', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'Which 9th-century kingdom established in southwestern India (modern Kerala) introduced the MALAYALAM language and script in its official royal inscriptions?', 'The Chera kingdom of Mahodayapuram (est. 9th century) was one of the earliest examples of an Indian regional kingdom using a vernacular language (Malayalam) in official administrative records.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a81dcacd-0b58-46b0-b5b0-ffe0eadf3319', 'The Chera Kingdom of Mahodayapuram', true, 'f68b0364-3eff-4c97-a6ce-97b7736f9ef6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a40e4fbc-16e1-47fa-9c02-6eef860393d2', 'The Chola Kingdom', false, 'f68b0364-3eff-4c97-a6ce-97b7736f9ef6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fd3f085-8959-4d4f-9645-f6a2c2b78893', 'The Pandya Kingdom', false, 'f68b0364-3eff-4c97-a6ce-97b7736f9ef6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('863b9bcb-6e58-435e-94aa-6d937399627d', 'The Rashtrakuta Kingdom', false, 'f68b0364-3eff-4c97-a6ce-97b7736f9ef6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d04a7933-7b0f-4a28-88a0-9df99ad7c5f9', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'What is the 14th-century Sanskrit-Malayalam literary style called ''Manipravalam'' (literally meaning ''Diamonds and Corals'')?', 'Manipravalam (literally ''diamonds and corals'') combined Sanskrit and regional Malayalam, celebrated in the 14th-century text Lilathilakam.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('811945d2-b7ed-47b3-9511-c06165bca76c', 'A rich blend of two languages: Sanskrit and the regional Malayalam language in literary compositions', true, 'd04a7933-7b0f-4a28-88a0-9df99ad7c5f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d5fd15e-1d9c-441c-ab06-c91869f8b891', 'A technique for cutting jewelry', false, 'd04a7933-7b0f-4a28-88a0-9df99ad7c5f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('679ea45a-62c7-46c7-98aa-1467b2abe617', 'A style of temple architecture', false, 'd04a7933-7b0f-4a28-88a0-9df99ad7c5f9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6c93aae-aecf-44b6-98e4-20b61508e932', 'A type of silk saree', false, 'd04a7933-7b0f-4a28-88a0-9df99ad7c5f9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('163b7e68-a2fc-4302-b428-367fba6821a3', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'Which famous temple cult in Puri (Odisha) became the supreme centre of regional and religious identity, where the wooden deity was originally made by local tribal people and later identified with Lord Vishnu?', 'Lord Jagannath (Lord of the World) at Puri evolved from an indigenous tribal wooden deity into a pan-Indian manifestation of Vishnu/Krishna.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b10a552-5f59-4203-9c00-d6fa740d4db3', 'The Jagannath Cult at Puri', true, '163b7e68-a2fc-4302-b428-367fba6821a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04db0b56-fc31-4345-a5b9-6deb9d997888', 'The Meenakshi Cult', false, '163b7e68-a2fc-4302-b428-367fba6821a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e6b08e2-9ff8-4797-8ca6-df44814efea9', 'The Lingaraja Cult', false, '163b7e68-a2fc-4302-b428-367fba6821a3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f742ad1d-f7ad-4bad-93f9-cb61194fddf5', 'The Kamakhya Cult', false, '163b7e68-a2fc-4302-b428-367fba6821a3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d5658121-a501-4fb9-ae2a-31b05db06d88', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'Which 12th-century king of the Eastern Ganga dynasty decided to erect a magnificent temple for Purushottama Jagannath at Puri?', 'King Anantavarman of the Eastern Ganga dynasty initiated the construction of the monumental Puri Jagannath Temple in the 12th century.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('928fb1f4-20ec-4fd2-a10a-88d25d95cb03', 'King Anantavarman', true, 'd5658121-a501-4fb9-ae2a-31b05db06d88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95121492-91f9-4d86-814a-f7d84e4cc57f', 'King Anangabhima III', false, 'd5658121-a501-4fb9-ae2a-31b05db06d88');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b9c4b21-ea4c-4268-be93-f070ed44fcfb', 'King Kharavela', false, 'd5658121-a501-4fb9-ae2a-31b05db06d88');
