INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e1934abc-b647-4754-9029-1806fd2dd856', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'Which king in 1230 CE dedicated his entire kingdom to Lord Jagannath and proclaimed himself as the ''Deputy'' (Rauta) of the god?', 'King Anangabhima III dedicated his realm to Lord Jagannath, governing the Odishan state as the earthly servant/deputy of the deity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4af93e94-85a2-4685-a483-a3be54181bad', 'King Anangabhima III', true, 'e1934abc-b647-4754-9029-1806fd2dd856');
