INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6ad38d3f-8df9-4630-a274-87b24f2dab14', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'Which classical dance form of North India originated from a caste of temple storytellers (''Kathakars'') who illustrated mythological stories with gestures and songs?', 'Kathak evolved from North Indian temple bardic storytellers (katha-kars) performing dramatic gestures to narrate sacred epics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fdcd582-e7a6-439b-8eff-d67201387b8e', 'Kathak', true, '6ad38d3f-8df9-4630-a274-87b24f2dab14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d46f996-673f-4546-afcc-de8d254e62c5', 'Bharatanatyam', false, '6ad38d3f-8df9-4630-a274-87b24f2dab14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8be3669f-ac2f-4914-b954-d19ac8db5e06', 'Kathakali', false, '6ad38d3f-8df9-4630-a274-87b24f2dab14');
