INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c3507fca-0d97-4770-8d90-0436f00e7146', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'Under which Nawab of Awadh (1847–1856) did the Lucknow Gharana of KATHAK dance reach its golden age of artistic refinement?', 'Nawab Wajid Ali Shah was a passionate patron and maestro of Kathak, Thumri, and dramatic dance-dramas (Rahas) in Lucknow.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7eb31a17-8147-43d2-9041-a7a2bdccab05', 'Nawab Wajid Ali Shah', true, 'c3507fca-0d97-4770-8d90-0436f00e7146');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e9a494a-4aa7-4f57-9550-78dca7d75c8f', 'Nawab Asaf-ud-Daula', false, 'c3507fca-0d97-4770-8d90-0436f00e7146');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6b98cc5-5a7c-4cec-8e2f-5e244235fed4', 'Nawab Saadat Ali Khan', false, 'c3507fca-0d97-4770-8d90-0436f00e7146');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42d374f9-591b-4aa2-9bc9-a6cda759e9ec', 'Nawab Shuja-ud-Daula', false, 'c3507fca-0d97-4770-8d90-0436f00e7146');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff43aced-ad51-485d-b4b2-ec79380a999b', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'What are the two major traditional court ''Gharanas'' (schools/traditions) of KATHAK dance?', 'Kathak branched into the rhythmic, energetic Jaipur Gharana and the lyrical, expressive Lucknow and Banaras Gharanas.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f22e842-62c4-40af-8944-0e11c068ac84', 'The Jaipur Gharana and the Lucknow Gharana (along with Banaras)', true, 'ff43aced-ad51-485d-b4b2-ec79380a999b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6d99569-912b-40ff-b369-a9d682403bc7', 'The Delhi and Agra Gharana', false, 'ff43aced-ad51-485d-b4b2-ec79380a999b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3eeb6b91-2826-4d05-ae07-3852008b7836', 'The Gwalior and Patiala Gharana', false, 'ff43aced-ad51-485d-b4b2-ec79380a999b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad0ece4a-6c24-4bb9-9560-b3c03c4fede9', 'The Tanjore and Mysore Gharana', false, 'ff43aced-ad51-485d-b4b2-ec79380a999b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a22dd2c9-af74-45ad-8edc-0cc5af342acf', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'What are small-sized paintings executed in watercolours on cloth or handmade paper, known for intricate fine detailing, called?', 'Miniatures are delicate, small-scale paintings rendered with natural mineral/vegetable pigments and fine squirrel-hair brushes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('973b78a2-ad0f-4544-a9d1-854858a7c5a2', 'Miniature Paintings (Miniatures)', true, 'a22dd2c9-af74-45ad-8edc-0cc5af342acf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9032865d-01f9-4a6b-a03b-f6fe26fbdc7a', 'Fresco Murals', false, 'a22dd2c9-af74-45ad-8edc-0cc5af342acf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58cafe75-2bdd-4c09-aec3-6078fed19ae5', 'Oil Canvas', false, 'a22dd2c9-af74-45ad-8edc-0cc5af342acf');
