INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('facbf779-71ca-4d20-bb79-f97585aac466', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'Which bold, intense regional style of miniature painting developed in the Himalayan foothills (Basohli in modern Jammu and Kashmir), famous for illustrating Bhanudatta''s ''Rasamanjari''?', 'Basohli painting is renowned for bold, vibrant primary colors, passionate facial profiles, and expressive depictions of the Rasamanjari.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3a148d6-46d3-4596-a1e0-ba1d99469e12', 'Basohli Style of Painting', true, 'facbf779-71ca-4d20-bb79-f97585aac466');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4eb91585-6d8a-4db0-919f-60c07b0b2229', 'Kangra School', false, 'facbf779-71ca-4d20-bb79-f97585aac466');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59c31f39-5246-46ed-950a-8ea95ff5bc1e', 'Mewar School', false, 'facbf779-71ca-4d20-bb79-f97585aac466');
