INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('adbfe6ae-532e-47c9-92f4-4484364cdeef', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'Which lyrical Pahari miniature painting school developed in the Kangra valley of Himachal Pradesh by the mid-18th century, inspired by Vaishnavite traditions with soft colors and poetic treatment of Radha-Krishna?', 'The Kangra school under Raja Sansar Chand is celebrated for lyrical delicacy, rhythmic lines, and cool soft greens and blues portraying Krishna-bhakti.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7ea92ba-8783-47f2-b659-84d293dfc3e1', 'The Kangra School of Painting', true, 'adbfe6ae-532e-47c9-92f4-4484364cdeef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f665eea-1c1a-482c-b557-93ddec475edb', 'The Mughal School', false, 'adbfe6ae-532e-47c9-92f4-4484364cdeef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0082667d-ffe5-492e-b873-a62319407a4e', 'The Tanjore School', false, 'adbfe6ae-532e-47c9-92f4-4484364cdeef');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4120a7a1-bc0b-4299-af45-2909c9ea86c3', 'The Madhubani School', false, 'adbfe6ae-532e-47c9-92f4-4484364cdeef');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c29e2d34-15e7-4572-a558-cefda8c40a68', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Easy', 'From which ancient primary language did the BENGALI language evolve over centuries, absorbing words from Persian, Austro-Asiatic, and European languages?', 'Bengali derived from Sanskrit through Magadhi Prakrit, later enriching its lexicon with Persian, Arabic, Austric, and Portuguese loanwords.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b99cd39-1f97-4734-bc37-56efe16f5b97', 'Sanskrit (via Magadhi Prakrit)', true, 'c29e2d34-15e7-4572-a558-cefda8c40a68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb561530-58f8-4f16-9ca3-bd83dd50d7a3', 'Tamil', false, 'c29e2d34-15e7-4572-a558-cefda8c40a68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('919f4671-dce0-4e59-9bb8-86f4f18a0b12', 'Arabic', false, 'c29e2d34-15e7-4572-a558-cefda8c40a68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed8f6dbd-52f0-4ee8-bda0-1f2247e4265b', 'Greek', false, 'c29e2d34-15e7-4572-a558-cefda8c40a68');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa701e0f-8c5f-4ae0-bd7c-ec9380cb5346', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'What is the 14th-century grammatical and poetic treatise ''Lilathilakam'' famous for?', 'The Lilathilakam is a 14th-century linguistic masterpiece codifying the syntax, meter, and aesthetics of Manipravalam.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85f0cfea-c162-4372-9661-40e7f9ac08c7', 'It is the earliest extant text composed in Manipravalam, dealing with the grammar and poetics of the joint Malayalam-Sanskrit literary tradition', true, 'aa701e0f-8c5f-4ae0-bd7c-ec9380cb5346');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('255a595a-7c63-4a13-a319-739e87ec1981', 'It is a cookbook for royal feasts', false, 'aa701e0f-8c5f-4ae0-bd7c-ec9380cb5346');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2098993a-1112-4eeb-9e37-e8f61a19a3c7', 'It is a manual of sword fighting', false, 'aa701e0f-8c5f-4ae0-bd7c-ec9380cb5346');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a40c23aa-8062-4cf4-9ba6-604bda17f80b', 'It is a maritime trade law book', false, 'aa701e0f-8c5f-4ae0-bd7c-ec9380cb5346');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('878e7cb4-e807-4c13-8dc5-fc8445a0774a', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'Why did successive conquerors of Odisha (Mughals, Marathas, English East India Company) all attempt to establish control over the Jagannath Temple at Puri?', 'Puri Jagannath Temple was the sanctum of regional sovereignty; political legitimacy in Odisha was inextricably linked to temple patronage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('596f0dfc-2fb8-4c9a-8a8b-d957d896ba25', 'They realized that the Puri temple held supreme socio-cultural and political legitimacy among the local Odia people; controlling the temple made their rule acceptable to the local population', true, '878e7cb4-e807-4c13-8dc5-fc8445a0774a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57829682-e4aa-4786-b098-0e958e4143f2', 'Because the temple contained only gold cannons', false, '878e7cb4-e807-4c13-8dc5-fc8445a0774a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3e71b37-3f5a-47e4-8bdc-0198f9bc59e5', 'Because they wanted to destroy the temple completely', false, '878e7cb4-e807-4c13-8dc5-fc8445a0774a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b91fc21f-227d-4a15-ab48-b0c695c741da', 'Because the temple was a military fort', false, '878e7cb4-e807-4c13-8dc5-fc8445a0774a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dcdbfaec-cec1-4341-8e19-8cb5f25b63a7', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'How did Rajput heroic ideals, preserved in bardic poems and songs in Rajasthan, shape regional identity?', 'Charans and Bhats preserved epic bardic songs immortalizing Rajput chivalric codes, battlefield valor, and heroic self-sacrifice.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c261d1e7-13d3-4c32-990f-4cd8cbdc03af', 'They celebrated heroic martial valor, undying loyalty to clan and friendship, fearlessness in battle, choosing death over dishonor, and the tragic practice of Sati / Jauhar', true, 'dcdbfaec-cec1-4341-8e19-8cb5f25b63a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0a699b6-9ee1-4808-baa7-0de6f918dae8', 'They taught merchants how to trade silk', false, 'dcdbfaec-cec1-4341-8e19-8cb5f25b63a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('116cb7f8-70cc-4bf1-aef8-7d10be8d27b3', 'They banned all weapons in Rajasthan', false, 'dcdbfaec-cec1-4341-8e19-8cb5f25b63a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cb0290a-b51a-46da-8fbe-4c32e71d8dea', 'They encouraged soldiers to flee from battles', false, 'dcdbfaec-cec1-4341-8e19-8cb5f25b63a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03d0d36c-c508-4896-8dc0-dc03321169d1', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'How did the transition of Kathak from temple performance into Mughal court entertainment transform the dance form?', 'Mughal and Awadh royal courts refined Kathak: fusing devotional bhakti narratives with complex rhythmic footwork and virtuosic spins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cf7cec7-4cc1-4ec0-a957-d8fae066fa7e', 'It acquired its distinctive rapid, intricate footwork (Tatkar), dizzying pirouettes (Chakkars), elegant court costumes, and dramatic enactments of Radha-Krishna love stories (Rahas)', true, '03d0d36c-c508-4896-8dc0-dc03321169d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f2843e1-c026-484a-956c-17be46120436', 'It became a silent meditation without music', false, '03d0d36c-c508-4896-8dc0-dc03321169d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82fd6a95-6675-44ee-b2d4-1bbdae286658', 'It was banned by all emperors', false, '03d0d36c-c508-4896-8dc0-dc03321169d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3696d14f-5070-4419-af45-3ee131c11e42', 'It was performed only underwater', false, '03d0d36c-c508-4896-8dc0-dc03321169d1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7bfb143f-80e7-4770-b40b-0490eab60a05', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'What are the traditional thatched-roof architectural styles that inspired the famous medieval Brick and Terracotta Temples of Bengal?', 'Bengal temple architecture mimicked vernacular curved bamboo thatch roofs: Dochala (double-curved) and Chauchala (four-roofed pyramid).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3778d6f0-da11-492f-9c3b-ad1c1656177f', 'The ''Dochala'' (two-roofed curved bamboo hut structure) and the ''Chauchala'' (four-roofed structure with four triangular roofs meeting at a curved point)', true, '7bfb143f-80e7-4770-b40b-0490eab60a05');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5c4de84-98c5-44ec-9b24-4500b25730ae', 'The Gopuram and Mandapa style', false, '7bfb143f-80e7-4770-b40b-0490eab60a05');
