INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88359189-b4da-455e-94bc-cfd65a061c7d', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'Which historic town in Bankura district of West Bengal is world-famous for its magnificent 17th- and 18th-century Terracotta Temples built by Malla kings (like Shyam Rai and Jore Bangla)?', 'Bishnupur under the Malla dynasty flourished as a terracotta architectural capital, featuring intricately carved clay tile temples.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c03bd8a-33a1-4c42-b525-49c4522ff29d', 'Bishnupur (Malla Kingdom)', true, '88359189-b4da-455e-94bc-cfd65a061c7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f42381b5-e909-4910-a237-c9cb6a1edea5', 'Darjeeling', false, '88359189-b4da-455e-94bc-cfd65a061c7d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3259a82-34e4-4e6a-8ffc-55beb8b6c6da', 'Murshidabad', false, '88359189-b4da-455e-94bc-cfd65a061c7d');
