INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dc8b2ef8-8e5e-4b68-ad68-7735ce1768da', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'What are the two distinct major categories of early Bengali literature?', 'Early Bengali literature comprised elite Sanskritized written works (Mangalkavyas, Vaishnava padavali) and popular oral Nath folklore.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a5da4ac-f6cd-4dfa-9608-43b31690b2b0', '1. Sanskrit-derived literature (translations of Epics, Mangalkavyas, Chaitanya biographies) ; and 2. Independent vernacular Nath literature (songs of Maynamati and Gopichand, fairy tales of Thakurmar Jhuli, Pir tales)', true, 'dc8b2ef8-8e5e-4b68-ad68-7735ce1768da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('461293c0-264b-4912-b27f-c9e6f81069ff', 'Persian war novels and Greek dramas', false, 'dc8b2ef8-8e5e-4b68-ad68-7735ce1768da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52743f25-376d-4c0f-a585-d890208f6a84', 'Modern newspaper articles', false, 'dc8b2ef8-8e5e-4b68-ad68-7735ce1768da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68200023-245c-4ef8-ae17-df67fd7c6dcb', 'English legal documents', false, 'dc8b2ef8-8e5e-4b68-ad68-7735ce1768da');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6cfcd124-208a-4cbb-874a-21aea66e4796', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'Who were the ''Pirs'' in medieval Bengal, revered across religious boundaries by both Hindus and Muslims?', 'Pirs were charismatic frontier leaders, spiritual masters, and land colonizers in the Bengal delta, worshipped at shrines by all faiths.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62d37410-2c03-445f-b592-4ae540136bce', 'Community leaders, spiritual guides, Sufi saints, and pioneer forest settlers who cleared dense delta mangroves, brought order, and were believed to possess supernatural powers', true, '6cfcd124-208a-4cbb-874a-21aea66e4796');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('350676f7-5cfd-4d8c-ac66-1ec2f46006e1', 'Tax collectors who arrested villagers', false, '6cfcd124-208a-4cbb-874a-21aea66e4796');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('826655fd-54b2-41bf-a5f2-1548d0c158ac', 'Foreign silk merchants', false, '6cfcd124-208a-4cbb-874a-21aea66e4796');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0de68d5-022a-4248-b009-72acc0675896', 'Military captains of war fleets', false, '6cfcd124-208a-4cbb-874a-21aea66e4796');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0916528-fd9a-483f-b194-2ac697e5c4df', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'Which Mughal Emperor was a passionate patron of miniature painting who maintained grand royal imperial ateliers (Karkhanas) where master painters illustrated the Akbarnama?', 'Akbar and Jahangir patronized master miniature painters (Basawan, Daswant, Mansur, Abul Hasan), creating the celebrated Mughal imperial atelier.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('194f94ec-95b6-433c-aed6-26455e498888', 'Emperor Akbar (and Jahangir)', true, 'b0916528-fd9a-483f-b194-2ac697e5c4df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b900dea-eb57-4abe-9499-1bfac08cf2a9', 'Emperor Aurangzeb', false, 'b0916528-fd9a-483f-b194-2ac697e5c4df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c3a6b3d-6da2-4215-b2b2-63522c8ccaa7', 'Emperor Babur', false, 'b0916528-fd9a-483f-b194-2ac697e5c4df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f8ff0b9-df65-4a03-ba0e-8061970759b6', 'Emperor Bahadur Shah I', false, 'b0916528-fd9a-483f-b194-2ac697e5c4df');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('69d50aa6-9309-4958-ba2f-19b8c1b953ba', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'Why did master painters migrate away from Delhi to regional Rajput and Himalayan hill states (Pahari courts) in the early 18th century?', 'Mughal political fragmentation and Nadir Shah''s sack of Delhi triggered an artistic diaspora to Kangra, Basohli, Guler, and Rajasthan.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c95e2875-93a3-4c96-965c-d44e889721fc', 'The political decline and instability of the Mughal capital under Nadir Shah''s invasion (1739) and Aurangzeb''s disinterest in court arts prompted painters to seek patronage in flourishing regional courts', true, '69d50aa6-9309-4958-ba2f-19b8c1b953ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('114760bb-c21b-4b62-9a20-8d9268e399d9', 'Because Delhi ran out of paint', false, '69d50aa6-9309-4958-ba2f-19b8c1b953ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f64371d1-add5-4d85-9f7d-79372e741745', 'Because painters were banned from living in plains', false, '69d50aa6-9309-4958-ba2f-19b8c1b953ba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('877b84cf-ff77-419a-bac1-3b149a1e718a', 'Because the climate in Delhi became too hot', false, '69d50aa6-9309-4958-ba2f-19b8c1b953ba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('85c6694f-47db-4756-b20e-90cefd7aea45', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'What are the ''Mangalkavyas'' in medieval Bengali literature?', 'Mangalkavyas are auspicious verse epics recounting how local indigenous goddesses established their worship across rural Bengal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8326f580-516c-4d48-90a8-c453a63c9898', 'Eulogistic narrative poems praising local regional deities (such as Chandi, Manasa, and Dharma Thakur), ensuring prosperity and auspiciousness for devotees', true, '85c6694f-47db-4756-b20e-90cefd7aea45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42e5cba3-3cb4-427f-bae7-fd9310988aa4', 'Books on mathematical calculations', false, '85c6694f-47db-4756-b20e-90cefd7aea45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('498a7b12-86b4-40d1-8b02-af1fa839652d', 'War treaties signed with kings', false, '85c6694f-47db-4756-b20e-90cefd7aea45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5c30f1e-95cc-4462-b8f7-ecdc8e50143c', 'Medical prescriptions for diseases', false, '85c6694f-47db-4756-b20e-90cefd7aea45');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d267a1ea-9c13-4c06-b219-adae66613c64', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'Why did traditional fish eating become widely accepted in Bengali Hindu culture, even among high-caste Brahmans?', 'The Brihaddharma Purana adapted scriptural law to deltaic ecology, canonizing fish consumption among Bengali Brahmans.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13dd854f-25e4-4a6b-9231-12267d343473', 'In the riverine, flood-prone Bengal delta with thousands of rivers and ponds, rice and fish were the indispensable staples of life, leading the 13th-century Sanskrit text ''Brihaddharma Purana'' to explicitly permit local Brahmans to eat certain varieties of fish', true, 'd267a1ea-9c13-4c06-b219-adae66613c64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4266e14-0b19-4b31-8045-3dd91b19d106', 'Because the Mughal emperor ordered everyone to eat fish', false, 'd267a1ea-9c13-4c06-b219-adae66613c64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('669ce123-a29b-4395-b199-38ee7bcd9232', 'Because vegetables did not exist in Bengal', false, 'd267a1ea-9c13-4c06-b219-adae66613c64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0af7e63-e382-4a16-972d-9fd677b94b89', 'Because fish was used as money', false, 'd267a1ea-9c13-4c06-b219-adae66613c64');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b5bd8d3-269f-4a09-b663-aba8fb7c3546', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'What are the Eight Recognized Classical Dance Traditions of India recognized by the Sangeet Natak Akademi?', 'The 8 classical dance traditions codified by Sangeet Natak Akademi trace lineage to Bharata Muni''s ancient Natyashastra.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef29cd51-58a5-4c1f-882b-017999e317d0', 'Bharatanatyam (TN), Kathakali (Kerala), Kathak (North India), Odissi (Odisha), Kuchipudi (AP), Mohiniyattam (Kerala), Manipuri (Manipur), and Sattriya (Assam)', true, '2b5bd8d3-269f-4a09-b663-aba8fb7c3546');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e99b6257-2ad1-4cff-902b-74bd07919632', 'Bhangra, Garba, Giddha, Lavani, Bihu, Rouf, Dandiya, Chhau', false, '2b5bd8d3-269f-4a09-b663-aba8fb7c3546');
