INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d176418c-5279-4323-9d3b-290307fd3ff8', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'Which legendary miniature painting masterwork created in Kishangarh (Rajasthan) by artist Nihal Chand is celebrated as the ''Mona Lisa of India''?', 'The Kishangarh miniature portrait of ''Bani Thani'' (courtesan-poet of Raja Sawant Singh) by Nihal Chand is famed for stylized serpentine grace.', NOW()) ON CONFLICT DO NOTHING;
