INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd3234ca-74d4-418e-861d-975e1d4621af', 'Gita Govinda', false, 'd176418c-5279-4323-9d3b-290307fd3ff8');
