INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18eeea88-dfa2-4622-bfbc-70f344d4dc03', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'What distinct literary genre was the ''Maynamati-Gopichand'' cycle of songs in eastern India?', 'The Maynamati-Gopichand songs celebrate Queen Maynamati guiding her son into Gorakhnathi yogic initiation to conquer mortality.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54402e5d-2312-44df-94fd-03cb5e719cd9', 'Popular oral folk songs about Queen Maynamati and her son Prince Gopichand embracing the esoteric ascetic path of the Nathpanthi Yogis to attain immortality', true, '18eeea88-dfa2-4622-bfbc-70f344d4dc03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edc99f85-56aa-4a1e-a500-c0d7c0bca14d', 'A story of a sea voyage to Africa', false, '18eeea88-dfa2-4622-bfbc-70f344d4dc03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0b5ff5e-9db4-41d4-800c-6c084a876f77', 'A commercial trade ledger', false, '18eeea88-dfa2-4622-bfbc-70f344d4dc03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f10849c6-7029-4aa4-9bea-36b0d614e422', 'A military manual of archery', false, '18eeea88-dfa2-4622-bfbc-70f344d4dc03');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('54cb5bae-7058-4759-bc13-c52478d628ce', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Medium', 'What was the ''Gita Govinda'' composed by Jayadeva in 12th-century Bengal and Odisha, which inspired countless miniature paintings across India?', 'Jayadeva''s Gita Govinda revolutionized devotional aesthetics, providing the thematic source for Pahari and Rajasthani miniatures.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc995341-750b-4605-b473-5b2f1dda057c', 'An exquisite Sanskrit lyrical poem celebrating the passionate, mystical love of Lord Krishna and Radha in the springtime groves of Vrindavan', true, '54cb5bae-7058-4759-bc13-c52478d628ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6341c5e5-9fb2-4605-9c98-28a50927773d', 'A treatise on horse riding', false, '54cb5bae-7058-4759-bc13-c52478d628ce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0968bc42-4862-4506-a5fa-8b0eefdb214b', 'A book on fort construction', false, '54cb5bae-7058-4759-bc13-c52478d628ce');
