INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ce15dfdc-26ec-452b-8c3b-e3dd427ad38a', 'Class 7', 'Social Science', 'Chapter 9: The Making of Regional Cultures', 'Hard', 'Spot the IMPOSTER in the following group of Indian Classical Dance Traditions and their corresponding States of Origin:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18621288-2683-49ae-9e8d-c79d4f3769ad', 'Tradition 1', false, 'ce15dfdc-26ec-452b-8c3b-e3dd427ad38a');
