INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f3577780-35f7-4706-909e-54e28ab95f80', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', 'जो विशेषण शब्द संज्ञा या सर्वनाम की संख्या (गिनती) का बोध कराते हैं (जैसे: ''चार लड़के'', ''कुछ पुस्तकें''), वे क्या कहलाते हैं?', 'संख्यावाचक विशेषण: गणनीय वस्तुओं की निश्चित अथवा अनिश्चित संख्या का बोध कराने वाले शब्द।', NOW()) ON CONFLICT DO NOTHING;
