INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e2f1dbf-e2ac-4905-8a7e-05ced284a23e', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', 'जो विशेषण शब्द किसी वस्तु की नाप, तौल या मात्रा का बोध कराते हैं (जैसे: ''दो लीटर दूध'', ''पाँच किलो चीनी''), वे क्या कहलाते हैं?', 'परिमाणवाचक विशेषण: अगणनीय द्रव्य, धातु या पदार्थों के नाप-तौल का बोध कराने वाले शब्द।', NOW()) ON CONFLICT DO NOTHING;
