INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46c52938-aa05-4385-8085-b49c57fc7ad6', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', 'जब कोई सर्वनाम शब्द संज्ञा से ठीक पहले आकर उसकी विशेषता प्रकट करता है (जैसे: ''वह लड़का बहुत चतुर है'', ''यह पुस्तक मेरी है''), तो वह क्या कहलाता है?', 'सार्वनामिक विशेषण: जब सर्वनाम संज्ञा से पहले लगकर संज्ञा की ओर संकेत/विशेषता बताता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80b85ad9-836c-49dc-9fff-15e9ddf94042', 'सार्वनामिक विशेषण (या संकेतवाचक विशेषण)', true, '46c52938-aa05-4385-8085-b49c57fc7ad6');
