INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6597ac01-3627-4803-a049-9517dd92e583', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', '''कक्षा में तीस विद्यार्थी उपस्थित हैं।'' वाक्य में ''तीस'' किस प्रकार का विशेषण है?', '''तीस'' विद्यार्थियों की निश्चित गणनीय संख्या का बोध कराता है, अतः यह निश्चित संख्यावाचक विशेषण है।', NOW()) ON CONFLICT DO NOTHING;
