INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a68d4788-14c3-48b7-a3dc-56b221ad4153', 'गुणवाचक', false, '6597ac01-3627-4803-a049-9517dd92e583');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f98a7918-4713-4f84-b9c3-c75ef4dc98f2', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', '''बाजार से दो किलो टमाटर ले आओ।'' वाक्य में ''दो किलो'' किस प्रकार का विशेषण है?', '''दो किलो'' तौल (मात्रा) का निश्चित परिमाण बताता है, अतः यह निश्चित परिमाणवाचक विशेषण है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37111241-5d15-4271-978e-155e2b3aee05', 'निश्चित परिमाणवाचक विशेषण', true, 'f98a7918-4713-4f84-b9c3-c75ef4dc98f2');
