INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41017309-9816-4bde-83ce-040adccfaa83', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', '''भारत'' संज्ञा शब्द से बनने वाला उपयुक्त विशेषण क्या होगा?', 'भारत (संज्ञा) + ईय (प्रत्यय) = भारतीय (विशेषण, जैसे: ''भारतीय संस्कृति'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f2f7dab-0468-40cd-8209-a4bd86ed3988', 'भारतीय', true, '41017309-9816-4bde-83ce-040adccfaa83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('818e195e-52d7-4064-8704-a63640adedcc', 'भारतवासी', false, '41017309-9816-4bde-83ce-040adccfaa83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52c0ddc0-a0a6-42c0-bdce-ba5e7ea9a95a', 'भारतवर्ष', false, '41017309-9816-4bde-83ce-040adccfaa83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6c88469-d67e-41bc-a8ed-9938d8b0bd4b', 'भारती', false, '41017309-9816-4bde-83ce-040adccfaa83');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d00e4670-c43b-4094-9813-768e72e6b94e', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Easy', '''इतिहास'' संज्ञा शब्द से बनने वाला मानक विशेषण शब्द क्या होगा?', 'इतिहास में ''इक'' प्रत्यय लगने से आदि स्वर ''इ'' की वृद्धि ''ऐ'' होकर ''ऐतिहासिक'' बनता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e634c4ce-1f9c-4727-88c3-51d2a1c9b4a1', 'ऐतिहासिक (इतिहास + इक)', true, 'd00e4670-c43b-4094-9813-768e72e6b94e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0513fa83-71bc-4f65-8bea-d508241a26f5', 'इतिहासकार', false, 'd00e4670-c43b-4094-9813-768e72e6b94e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('694e15b9-0710-4c9c-a3de-b213d15289b5', 'ऐतिहास', false, 'd00e4670-c43b-4094-9813-768e72e6b94e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98a41bd0-ecc9-4ea2-81bb-661ef9fb4327', 'इतिहासी', false, 'd00e4670-c43b-4094-9813-768e72e6b94e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e030d12-c5b0-423a-8361-082c2e4fbde2', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', 'संख्यावाचक विशेषण और परिमाणवाचक विशेषण की पहचान करने का सबसे सरल और सटीक नियम क्या है?', 'गणनीय संज्ञाओं के साथ संख्यावाचक विशेषण तथा नाप-तौल योग्य अगणनीय संज्ञाओं के साथ परिमाणवाचक विशेषण आता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77589d0a-27df-48fe-ac1c-8e94d66e4e1e', 'यदि विशेष्य को ''गिना जा सकता है'' (Countable), तो वह ''संख्यावाचक'' है (जैसे: चार केले, दस पुस्तकें) ; यदि विशेष्य को ''नापा या तौला जाता है'' (Uncountable/Measurable), तो वह ''परिमाणवाचक'' है (जैसे: चार लीटर दूध, दो किलो दाल)', true, '5e030d12-c5b0-423a-8361-082c2e4fbde2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('441e7a01-7a79-4d30-981b-d904a0e9fd3e', 'दोनों में कोई अंतर नहीं है', false, '5e030d12-c5b0-423a-8361-082c2e4fbde2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d35799e-5167-4d7e-bfb8-0903465e0baa', 'संख्यावाचक केवल स्त्रीलिंग में आता है', false, '5e030d12-c5b0-423a-8361-082c2e4fbde2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed03b365-dfe3-4293-a162-aba311d2683f', 'परिमाणवाचक हमेशा बहुवचन होता है', false, '5e030d12-c5b0-423a-8361-082c2e4fbde2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19a61efe-cfc9-4075-811d-8d8397aec76b', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', '''मुझे थोड़ा पानी दीजिए।'' और ''सभा में थोड़े लोग आए थे।'' दोनों वाक्यों में प्रयुक्त ''थोड़ा / थोड़े'' क्रमशः किस भेद के अंतर्गत आते हैं?', 'पानी अगणनीय द्रव्य है (अनिश्चित परिमाण), जबकि लोग गणनीय प्राणी हैं (अनिश्चित संख्या)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ba64b13-baf5-45b2-abbc-1c915efdc5c6', '''थोड़ा पानी'' = अनिश्चित परिमाणवाचक विशेषण ; ''थोड़े लोग'' = अनिश्चित संख्यावाचक विशेषण', true, '19a61efe-cfc9-4075-811d-8d8397aec76b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9db3c7c3-2b97-4fcf-b133-c55070d219f0', 'दोनों संख्यावाचक हैं', false, '19a61efe-cfc9-4075-811d-8d8397aec76b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a175c07d-604b-4c89-ac2a-4223765d35e0', 'दोनों परिमाणवाचक हैं', false, '19a61efe-cfc9-4075-811d-8d8397aec76b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af3d6e6b-0112-4629-8388-d55089400980', 'दोनों सार्वनामिक विशेषण हैं', false, '19a61efe-cfc9-4075-811d-8d8397aec76b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('66549cdb-dd71-4666-9f5c-749dc2848c53', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', 'तुलना की दृष्टि से विशेषण की कुल कितनी अवस्थाएँ (Degrees of Comparison) होती हैं?', 'विशेषण की 3 अवस्थाएँ हैं: मूलावस्था (उच्च), उत्तरावस्था (उच्चतर), उत्तमावस्था (उच्चतम)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ac72798-0ce5-4ad8-bf88-7dc5d357e98b', 'तीन अवस्थाएँ (1. मूलावस्था [Positive], 2. उत्तरावस्था [Comparative - तर], 3. उत्तमावस्था [Superlative - तम])', true, '66549cdb-dd71-4666-9f5c-749dc2848c53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfdc15c3-a6c9-4ccf-9e7a-c30afc572995', 'दो अवस्थाएँ', false, '66549cdb-dd71-4666-9f5c-749dc2848c53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0359a214-1eb1-47fc-8b29-07d31263c06f', 'चार अवस्थाएँ', false, '66549cdb-dd71-4666-9f5c-749dc2848c53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41bbd744-e9f6-4298-8543-ef8528d93c52', 'पाँच अवस्थाएँ', false, '66549cdb-dd71-4666-9f5c-749dc2848c53');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d3ca0da2-caa4-4830-9fa9-cadeac594150', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Medium', '''सुंदर'' विशेषण की ''उत्तरावस्था'' (Comparative Degree) और ''उत्तमावस्था'' (Superlative Degree) क्रमशः क्या होंगी?', 'मूलावस्था = सुंदर; उत्तरावस्था = सुंदरतर; उत्तमावस्था = सुंदरतम।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a009bf8-7b2a-48a1-afa8-035850cdf121', 'सुंदरतर और सुंदरतम', true, 'd3ca0da2-caa4-4830-9fa9-cadeac594150');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30bc5ea1-578d-436c-ab4b-f391c2efedd5', 'सुंदरी और सुंदरा', false, 'd3ca0da2-caa4-4830-9fa9-cadeac594150');
