INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68b24e2d-f464-40d1-b01d-63b06cae0427', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c14a771d-8218-4603-bbe9-54e80683aefd', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '68b24e2d-f464-40d1-b01d-63b06cae0427');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f97403f4-ba15-4425-b299-55168c645d51', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '68b24e2d-f464-40d1-b01d-63b06cae0427');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8845ca06-90c6-4505-a4ec-d0c7a334d8e7', '(A) सही है, परन्तु (R) गलत है।', false, '68b24e2d-f464-40d1-b01d-63b06cae0427');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11e32da9-d3de-4634-a416-ff14b8a76d10', '(A) गलत है, परन्तु (R) सही है।', false, '68b24e2d-f464-40d1-b01d-63b06cae0427');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16b1d952-e520-4ba2-99b7-949f8238b04b', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', 'Spot the IMPOSTER in the following group of संज्ञा से बने विशेषण शब्दों में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8d0363a-43bb-429d-bdcd-fb4bb8e84e15', 'युग्म 1', false, '16b1d952-e520-4ba2-99b7-949f8238b04b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f042c40-59d7-4649-aec8-83f58548856a', 'युग्म 2', false, '16b1d952-e520-4ba2-99b7-949f8238b04b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7cde802-aa7e-4eb5-8d06-81ff4564fee4', 'युग्म 3', false, '16b1d952-e520-4ba2-99b7-949f8238b04b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0009f348-9a40-466c-a0be-4378f837df0f', 'युग्म 4 (''पढ़ना'' संज्ञा नहीं, बल्कि ''क्रिया'' [Verb] है ; अतः ''पढ़ाकू'' क्रिया से बना विशेषण है, संज्ञा से नहीं)', true, '16b1d952-e520-4ba2-99b7-949f8238b04b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7dd0251c-2194-4741-bacf-41b1fe50d5c8', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', 'सुमेलित कीजिए (विशेषण की तुलनात्मक अवस्थाएँ):
(क) लघु      -> (i) मूलावस्था (Positive Degree)
(ख) लघुतर    -> (ii) उत्तरावस्था (Comparative Degree)
(ग) लघुतम    -> (iii) उत्तमावस्था (Superlative Degree)
(घ) अति लघु   -> (iv) हिंदी में उत्तरावस्था/प्रविशेषण युक्त रूप', 'लघु = मूलावस्था; लघुतर = उत्तरावस्था; लघुतम = उत्तमावस्था।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ca8e1f9-827b-48ab-af89-f4e76a74b08d', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, '7dd0251c-2194-4741-bacf-41b1fe50d5c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67d2355e-1e07-4602-8695-3b3ca9a4bd3a', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '7dd0251c-2194-4741-bacf-41b1fe50d5c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e03f959d-6042-40b8-a988-2c18a0162a44', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '7dd0251c-2194-4741-bacf-41b1fe50d5c8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d2a203d-a138-49f4-a58b-8ada30121555', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '7dd0251c-2194-4741-bacf-41b1fe50d5c8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be2efd7e-3019-479d-a20c-f3441f2aaf37', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', '''उद्देश्य विशेषण'' (Attributive Adjective) और ''विधेय विशेषण'' (Predicative Adjective) में क्या व्याकरणिक अंतर होता है?', 'संज्ञा से पूर्व विशेषण = उद्देश्य विशेषण (''सफेद गाय''); संज्ञा के उपरांत विशेषण = विधेय विशेषण (''गाय सफेद है'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d940b66-dec3-4f9a-9008-4e89b9eb56e7', 'जब विशेषण विशेष्य (संज्ञा) से पहले आता है, तो वह ''उद्देश्य विशेषण'' कहलाता है (जैसे: ''काला घोड़ा दौड़ा'') ; जब विशेषण विशेष्य के बाद और क्रिया से पहले आता है, तो वह ''विधेय विशेषण'' कहलाता है (जैसे: ''घोड़ा काला है'')', true, 'be2efd7e-3019-479d-a20c-f3441f2aaf37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c437da1a-ded9-4d11-b3b8-5940708d7e0f', 'दोनों में कोई अंतर नहीं होता', false, 'be2efd7e-3019-479d-a20c-f3441f2aaf37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0c786e0-ea40-4102-ae42-24a09729b051', 'उद्देश्य विशेषण केवल स्त्रीलिंग होता है', false, 'be2efd7e-3019-479d-a20c-f3441f2aaf37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19daf47e-96de-4cef-b34a-2d4573e94299', 'विधेय विशेषण केवल भविष्यत काल में आता है', false, 'be2efd7e-3019-479d-a20c-f3441f2aaf37');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7d5b83f5-94f9-436a-9189-bb44c0316ba7', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', 'निम्नलिखित वाक्यों में से किस वाक्य में ''विधेय विशेषण'' का शुद्ध प्रयोग हुआ है?', '''मेरा कुर्ता बहुत पुराना है'' में ''पुराना'' विधेय भाग में विशेष्य के बाद आया है, अतः यह विधेय विशेषण है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4beb9bbb-0e97-4df4-a4b9-83447165fe37', '''मेरा कुर्ता बहुत पुराना है।'' (''पुराना'' विशेषण विशेष्य ''कुर्ता'' के बाद प्रयुक्त हुआ है)', true, '7d5b83f5-94f9-436a-9189-bb44c0316ba7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('715cda67-bba0-47f3-91f3-f8c8fce0d743', '''पुराना कुर्ता अलमारी में रखा है।''', false, '7d5b83f5-94f9-436a-9189-bb44c0316ba7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f763f00-cf7b-466e-acab-b9aab211f68e', '''सफेद हंस तैर रहा है।''', false, '7d5b83f5-94f9-436a-9189-bb44c0316ba7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df11da77-1563-45ad-9810-dd31f4feceff', '''मीठा आम खाओ।''', false, '7d5b83f5-94f9-436a-9189-bb44c0316ba7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07657100-992b-447b-a2b3-6f6c68458b82', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', '''शास्त्र'' संज्ञा शब्द से बनने वाला मानक व्याकरणिक विशेषण क्या होगा?', 'शास्त्र + ईय = शास्त्रीय (Classical, जैसे: शास्त्रीय नृत्य)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aad63414-8de9-4a09-8eff-779098731550', 'शास्त्रीय (शास्त्र + ईय, जैसे: शास्त्रीय संगीत)', true, '07657100-992b-447b-a2b3-6f6c68458b82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5aa17fd4-24a0-4bc4-8149-ed7213682793', 'शास्त्रज्ञ', false, '07657100-992b-447b-a2b3-6f6c68458b82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09a1c5d9-7685-4601-a417-f380a90c326e', 'शास्त्रार्थ', false, '07657100-992b-447b-a2b3-6f6c68458b82');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b9457ed-f6d9-4aeb-9112-fa50df95fba3', 'शास्त्री', false, '07657100-992b-447b-a2b3-6f6c68458b82');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a54d8d76-9fe0-461f-b5e8-e99698a49943', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', '''आत्मा'' संज्ञा शब्द से बनने वाला शुद्ध विशेषण रूप क्या होगा?', 'आत्मा + इक = आत्मिक (जैसे: आत्मिक शांति)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c3579c4-e1cf-4fc2-ac22-01629086902b', 'आत्मिक (आत्मा + इक)', true, 'a54d8d76-9fe0-461f-b5e8-e99698a49943');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21811652-fa75-4aef-8049-2728cd43642e', 'आत्मीय', false, 'a54d8d76-9fe0-461f-b5e8-e99698a49943');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90e3de1f-6650-46eb-98b4-890794a912f6', 'आत्मवान', false, 'a54d8d76-9fe0-461f-b5e8-e99698a49943');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58244094-c37b-4007-91ec-e31180e45eef', 'आत्मावान', false, 'a54d8d76-9fe0-461f-b5e8-e99698a49943');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5206fce7-455c-4652-836b-21170508571e', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', '''नगर'' और ''ग्राम'' शब्दों से बनने वाले विशेषण युग्म का सही चयन कीजिए:', 'नगर + इक = नागरिक; ग्राम + ईण = ग्रामीण।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49bfe6e2-29ec-45d5-99ca-1f4f8789332d', 'नागरिक और ग्रामीण (नगर + इक = नागरिक ; ग्राम + ईण = ग्रामीण)', true, '5206fce7-455c-4652-836b-21170508571e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39e8f50e-02c3-4126-8cf1-cb2bd1a95ae6', 'नगरी और ग्रामी', false, '5206fce7-455c-4652-836b-21170508571e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6069e047-ec0e-4fad-8f9a-f35f5eec12b0', 'नगरवासी और ग्रामवासी', false, '5206fce7-455c-4652-836b-21170508571e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9394417-4942-4f92-a17a-9d2e1ea94bdb', 'नगरिक और ग्रामीन', false, '5206fce7-455c-4652-836b-21170508571e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('48a94fe1-0527-41ef-9afb-991766f8ccc6', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', 'निम्नलिखित वाक्यों में से ''अशुद्ध विशेषण प्रयोग'' वाला वाक्य छाँटिए:', 'उत्तमावस्था में ''सबसे'' और ''तम'' प्रत्यय का एक साथ प्रयोग व्याकरणिक दृष्टि से वर्जित पुनरुक्ति दोष है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a972bd42-76ab-4984-91c5-3fb9db170dc2', '''वह बहुत सबसे सुंदरतम लड़की है।'' (अशुद्ध: ''सबसे'' और ''सुंदरतम'' दोनों का एक साथ प्रयोग पुनरुक्ति दोष है ; शुद्ध: ''वह सुंदरतम लड़की है'' या ''वह सबसे सुंदर लड़की है'')', true, '48a94fe1-0527-41ef-9afb-991766f8ccc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0beb5ee5-0b12-4e0e-b045-e2964d4a5ffb', '''वह बहुत परिश्रमी छात्र है।''', false, '48a94fe1-0527-41ef-9afb-991766f8ccc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62427d1c-0016-4ed0-8c8f-ba4661782038', '''गंगा भारत की सबसे पवित्र नदी है।''', false, '48a94fe1-0527-41ef-9afb-991766f8ccc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4a2146a-6a57-42d4-88ef-53e8da43ccea', '''यह पुस्तक अत्यंत उपयोगी है।''', false, '48a94fe1-0527-41ef-9afb-991766f8ccc6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35a5cd3f-e12c-425f-b177-39fdaf051ea8', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', '''व्यक्ति'' संज्ञा शब्द से बनने वाला सही विशेषण क्या होगा?', 'व्यक्ति + गत = व्यक्तिगत (Personal / Individual)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bac5501-db1b-4632-9a7e-3f209db5857c', 'व्यक्तिगत (व्यक्ति + गत, जैसे: व्यक्तिगत राय)', true, '35a5cd3f-e12c-425f-b177-39fdaf051ea8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a7d0788-fee2-48cd-9e3a-21e23a7be48a', 'व्यक्तित्व', false, '35a5cd3f-e12c-425f-b177-39fdaf051ea8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c346d177-d45c-4a00-91fd-04365489a8d8', 'व्यक्तिपरक', false, '35a5cd3f-e12c-425f-b177-39fdaf051ea8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f02ac9fe-fd0c-48a3-9580-12dec2b2d5ef', 'व्यक्तिमान', false, '35a5cd3f-e12c-425f-b177-39fdaf051ea8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cfb97ff8-d4d3-4e0b-93c6-8ed81807c9b7', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', '''रस'' संज्ञा शब्द से बनने वाला उपयुक्त विशेषण क्या होगा?', 'रस + ईला = रसीला (विशेषण)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a9d6211-d041-42b9-bb07-95c8e8a889fa', 'रसीला (जैसे: ''रसीला आम'')', true, 'cfb97ff8-d4d3-4e0b-93c6-8ed81807c9b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2002a3b5-2421-41cb-8316-fb78c033255a', 'रसायन', false, 'cfb97ff8-d4d3-4e0b-93c6-8ed81807c9b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4fbd43d5-b944-4960-8378-170c08742531', 'रसिकता', false, 'cfb97ff8-d4d3-4e0b-93c6-8ed81807c9b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcd2d9c0-52ba-4b75-8548-a85fe6a32e80', 'रसमयता', false, 'cfb97ff8-d4d3-4e0b-93c6-8ed81807c9b7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f1b9df7-35d0-405a-9fc6-52fa6e508fe7', 'Class 7', 'Hindi Grammar', 'Chapter 9: विशेषण और उसके भेद', 'Hard', 'विशेषण और विशेष्य के अन्वय (Agreement) का भाषा-सौंदर्य और वाक्य-शुद्धि में क्या सर्वोच्च महत्व है?', 'हिंदी में आकारांत विशेषणों का रूप विशेष्य के लिंग और वचन के अनुसार अनिवार्यतः रूपांतरित होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('665c1aff-3dd0-489f-994c-c53bb25c2f90', 'विशेषण का लिंग और वचन सदैव अपने विशेष्य (संज्ञा) के लिंग और वचन के अनुसार ही निर्धारित होता है (जैसे: ''अच्छा लड़का'', ''अच्छी लड़की'', ''अच्छे लड़के'') ; इस अन्वय के बिना भाषा अशुद्ध हो जाती है', true, '0f1b9df7-35d0-405a-9fc6-52fa6e508fe7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bc70869-2aba-47ce-a088-218e35c3344e', 'विशेषण का लिंग कभी नहीं बदलता', false, '0f1b9df7-35d0-405a-9fc6-52fa6e508fe7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61a29ebf-ccb5-4eec-8524-0d74a9d55eaa', 'विशेषण केवल वाक्यों को लंबा करने के लिए प्रयुक्त होते हैं', false, '0f1b9df7-35d0-405a-9fc6-52fa6e508fe7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e774b65-1f09-48c1-997f-2152f52c3259', 'विशेषण का भाषा में कोई महत्व नहीं है', false, '0f1b9df7-35d0-405a-9fc6-52fa6e508fe7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ec219e51-1b40-4bad-920d-b98778a4dfab', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'In standard circuit diagrams, how is an ELECTRIC CELL represented symbolically?', 'Symbolic convention: the longer, thinner parallel line represents the positive terminal (+), and the shorter, thicker line represents the negative terminal (-).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('841af2d9-faf4-4fd6-9e2b-204c1e351b7a', 'A long thin vertical line (representing the POSITIVE terminal) parallel to a shorter thick vertical line (representing the NEGATIVE terminal)', true, 'ec219e51-1b40-4bad-920d-b98778a4dfab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f827f15c-7bcc-49ee-86f1-c77399cca3dd', 'A complete closed circle with a cross', false, 'ec219e51-1b40-4bad-920d-b98778a4dfab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d485733b-c656-46c7-8593-67019e727a35', 'Two identical thick squares', false, 'ec219e51-1b40-4bad-920d-b98778a4dfab');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30cbd612-d2c9-4e86-8164-7bb1b1a210da', 'A wavy spiral line', false, 'ec219e51-1b40-4bad-920d-b98778a4dfab');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe5f735f-5c79-443f-b646-0927d518bb8b', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'A combination of two or more electric cells connected together in series is called a:', 'A battery is a connected group of electrochemical cells where the positive terminal of one cell connects to the negative terminal of the next.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f608ed9-e8a9-4129-91bf-56297ca4c34c', 'Battery', true, 'fe5f735f-5c79-443f-b646-0927d518bb8b');
