INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55a38985-7ab6-46f9-8c37-fb56e2312ec8', 'Fuse', false, 'fe5f735f-5c79-443f-b646-0927d518bb8b');
