INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a1e63915-53c5-4729-bc8d-ce29f343e7fd', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'What is the phenomenon where a conducting wire gets intensely HOT when an electric current passes through it called?', 'Joule''s heating effect: electrical resistance dissipates electric potential energy into thermal kinetic heat (H = I²Rt).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8854de0-7828-48dc-8610-27ae2cd022d8', 'Heating Effect of Electric Current (Joule Heating)', true, 'a1e63915-53c5-4729-bc8d-ce29f343e7fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b452cd4-ea10-4e4d-9b2d-f299fa9e5abc', 'Magnetic Effect', false, 'a1e63915-53c5-4729-bc8d-ce29f343e7fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7fd06f1-aca0-4252-a5e8-7c9fb12ab0ed', 'Chemical Effect', false, 'a1e63915-53c5-4729-bc8d-ce29f343e7fd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d39abcb-0810-45af-a504-4f12d7f8ad60', 'Cooling Effect', false, 'a1e63915-53c5-4729-bc8d-ce29f343e7fd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('895c9bc6-ea76-4139-82aa-6fe7b971fe42', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'What is the high-resistance metallic wire coil inside electric room heaters, electric irons, toasters, and geysers that glows red-hot to produce heat called?', 'An electric heating element is made of high-resistivity Nichrome alloy (nickel-chromium) that resists oxidation at high temperatures.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('551a4d2b-c674-4b40-9cb4-ae01bf5953fb', 'An Heating Element (made of Nichrome alloy)', true, '895c9bc6-ea76-4139-82aa-6fe7b971fe42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33cce7b9-38ff-45eb-8772-8e47b742b5df', 'A Filament', false, '895c9bc6-ea76-4139-82aa-6fe7b971fe42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c39f3cef-3209-4b80-a61e-d383641e7672', 'A Fuse wire', false, '895c9bc6-ea76-4139-82aa-6fe7b971fe42');
