INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('367d9782-36f8-4624-bff4-73b686da60c7', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'Which high-melting-point metal is used to make the thin glowing FILAMENT inside an incandescent electric bulb?', 'Tungsten has an exceptionally high melting point (~3,422°C), glowing white-hot to emit light without melting.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8253b858-a4c8-4141-9f1b-e047df8be3a0', 'Tungsten (melting point ~3,422°C)', true, '367d9782-36f8-4624-bff4-73b686da60c7');
