INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('18b7707e-a446-48db-8370-e832c6b83ee0', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'What is an Electric Fuse and what is its primary safety function in household electrical circuits?', 'An electric fuse prevents electrical fires and appliance damage by melting when current exceeds the rated safety threshold.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d7d3ba6-bdd7-40e0-8c5c-37ad70883218', 'A safety device containing a low-melting-point wire that melts and breaks the circuit if excessive dangerous electric current flows through it', true, '18b7707e-a446-48db-8370-e832c6b83ee0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37f39a7f-0e9f-4db0-bb4f-17bad82a54a0', 'A device to generate more electricity', false, '18b7707e-a446-48db-8370-e832c6b83ee0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45bcf8d2-7a42-4c00-8050-4029c621bde4', 'A switch that makes bulbs brighter', false, '18b7707e-a446-48db-8370-e832c6b83ee0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42088224-4b30-487c-961c-3f555a5e60cf', 'A meter to measure voltage', false, '18b7707e-a446-48db-8370-e832c6b83ee0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7beb3996-6edf-4561-b5ca-b8dfc38e7bcb', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'What modern automatic safety switches are increasingly replacing traditional melting wire fuses in household electrical wiring?', 'MCBs automatically trip and switch OFF when current exceeds safe limits, and can easily be reset manually without replacing wires.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17577e14-8b1c-4ffb-8272-84a76ef419fd', 'Miniature Circuit Breakers (MCBs)', true, '7beb3996-6edf-4561-b5ca-b8dfc38e7bcb');
