INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c1e3d1c-5cc3-4fee-b944-3b064d44a271', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'Which Danish physicist discovered in 1820 that an electric current flowing through a wire creates a MAGNETIC FIELD that deflects a nearby magnetic compass needle?', 'Hans Christian Oersted discovered electromagnetism in 1820 when he noticed an electric current deflects a magnetic compass needle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae858a2e-7fd3-4ef1-98e8-a8bf616d6f2c', 'Hans Christian Oersted', true, '9c1e3d1c-5cc3-4fee-b944-3b064d44a271');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5748f85e-5dc5-444c-b2e6-ec79d0b598fa', 'Michael Faraday', false, '9c1e3d1c-5cc3-4fee-b944-3b064d44a271');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f9f4644-4fd3-4a70-8c77-d0f59dff2fb0', 'Thomas Edison', false, '9c1e3d1c-5cc3-4fee-b944-3b064d44a271');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f58afa68-59bb-4de4-b9aa-c64ad274f1ec', 'James Watt', false, '9c1e3d1c-5cc3-4fee-b944-3b064d44a271');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59bd898d-570e-4972-9376-b68ced8f6014', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'A coil of insulated wire wound around an iron core that acts as a magnet only when electric current flows through it is called an:', 'An electromagnet is a temporary magnet whose magnetic field is generated and controlled by an electric current in its coil.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d09b95bf-6275-4870-91da-5fec76460eae', 'Electromagnet', true, '59bd898d-570e-4972-9376-b68ced8f6014');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b12eb616-337a-4999-a8f6-ba1ae6719111', 'Permanent Bar Magnet', false, '59bd898d-570e-4972-9376-b68ced8f6014');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f056f90c-c494-4565-a130-3ad9f5c9ea1b', 'Electric Cell', false, '59bd898d-570e-4972-9376-b68ced8f6014');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15133b06-5d34-4ccd-ae6c-ccd5f8398364', 'Electric Fuse', false, '59bd898d-570e-4972-9376-b68ced8f6014');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('824d7bd0-18f0-465d-ab52-1bc46f9ba5d9', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'What happens to the magnetic field of an Electromagnet when the electric current is switched OFF?', 'Electromagnets are temporary magnets made of soft iron cores that lose magnetic properties the moment current stops flowing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9815c9b4-1239-47c5-b7db-a438dd782590', 'It loses its magnetism almost immediately', true, '824d7bd0-18f0-465d-ab52-1bc46f9ba5d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('983be8aa-97f6-4ada-8480-49e665555328', 'It becomes twice as strong', false, '824d7bd0-18f0-465d-ab52-1bc46f9ba5d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e1b51f7-f475-408e-91ad-efb6555c758b', 'It explodes', false, '824d7bd0-18f0-465d-ab52-1bc46f9ba5d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98ebbca7-ca4d-4ede-bbb5-50b0eaccfb6f', 'It becomes a permanent magnet forever', false, '824d7bd0-18f0-465d-ab52-1bc46f9ba5d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6a48ff63-7c5e-4db9-a0af-6cc2999b8fd2', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'Which everyday electromechanical acoustic device operates using an Electromagnet, a soft iron armature, a striker hammer, and a brass gong?', 'An electric bell uses an electromagnet that attracts an iron armature, striking the gong and breaking the contact in a rapid make-and-break cycle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc9254b7-0675-4ff7-8194-7340ae6c88ce', 'An Electric Bell', true, '6a48ff63-7c5e-4db9-a0af-6cc2999b8fd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a10a1d8f-f842-41b6-96eb-510148e86c80', 'A Flashlight', false, '6a48ff63-7c5e-4db9-a0af-6cc2999b8fd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f496d8a-130c-4ffb-aa76-855b155c947a', 'An Electric Heater', false, '6a48ff63-7c5e-4db9-a0af-6cc2999b8fd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bfadc54-1cdf-4362-9aea-0b20ece0d14f', 'An Electric Iron', false, '6a48ff63-7c5e-4db9-a0af-6cc2999b8fd2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9770f3a3-d0ea-4ea1-a156-4f20cb673206', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Easy', 'Which standard certification mark issued by the Bureau of Indian Standards (BIS) should consumers look for on electrical appliances to ensure quality and safety?', 'The ISI certification mark guarantees that electrical appliances conform to national safety, efficiency, and quality standards.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4534cbf6-34ab-4f3a-89c0-193e50f9d9ed', 'ISI Mark', true, '9770f3a3-d0ea-4ea1-a156-4f20cb673206');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f56060fa-6f78-4045-aef7-a5e4a6cfd4d5', 'Agmark', false, '9770f3a3-d0ea-4ea1-a156-4f20cb673206');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46020664-14e3-4dff-a5fd-2dae6db8e6ac', 'FSSAI Mark', false, '9770f3a3-d0ea-4ea1-a156-4f20cb673206');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66d3f234-1a6e-4ca4-b3bb-1c4666e25cc8', 'Hallmark', false, '9770f3a3-d0ea-4ea1-a156-4f20cb673206');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03bdae3a-e8f9-4ba0-a46e-12c48eb852b6', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'Why are energy-efficient LED (Light Emitting Diode) bulbs and CFLs preferred over traditional incandescent filament bulbs?', 'LEDs use solid-state electroluminescence, consuming 80–90% less energy than resistive incandescent filament bulbs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9add7f03-daaf-49bb-aada-6f768da173db', 'Incandescent bulbs waste a large proportion of electrical energy as unwanted Heat, whereas LEDs convert almost all electrical energy directly into Light without heat wastage', true, '03bdae3a-e8f9-4ba0-a46e-12c48eb852b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92f681a5-b92c-48dd-8f6e-d65836a3d528', 'Incandescent bulbs are too bright for human eyes', false, '03bdae3a-e8f9-4ba0-a46e-12c48eb852b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c01cc854-472a-43d2-930c-255d740ddd94', 'LED bulbs do not require any electricity', false, '03bdae3a-e8f9-4ba0-a46e-12c48eb852b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01ca9caf-d20e-4be1-930f-dfaf03969a19', 'LED bulbs last only for one day', false, '03bdae3a-e8f9-4ba0-a46e-12c48eb852b6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('52b30681-ea46-41b7-a5c0-b043b58a1925', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'How should cells be arranged in a battery holder so that electric current flows properly?', 'Series electrochemical connection requires alternating polarities (+ to -) to add individual cell voltages together.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ab65fca-abd3-4ced-8d67-7f8a2ce3b8d4', 'The POSITIVE (+) terminal of one cell must be connected to the NEGATIVE (-) terminal of the next cell in a continuous series', true, '52b30681-ea46-41b7-a5c0-b043b58a1925');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00014876-e644-48f9-8b72-f3352d594d4f', 'Positive terminal must connect to positive terminal', false, '52b30681-ea46-41b7-a5c0-b043b58a1925');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b51640df-e332-49b8-b2f5-d8d947eae52b', 'Negative terminal must connect to negative terminal', false, '52b30681-ea46-41b7-a5c0-b043b58a1925');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5cf46fc-55aa-474f-81f5-0b77b3da0dde', 'Cells can be placed in any random direction', false, '52b30681-ea46-41b7-a5c0-b043b58a1925');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f896e2ef-4278-4001-abe4-5fe70f201321', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'What two dangerous electrical fault conditions cause an excessive, surging current to flow through domestic wiring, triggering fires or blowing fuses?', 'Short circuits bypass load resistance (R ≈ 0, surging I) and overloading draws additive current exceeding cable ampacity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdb78f52-ab0f-4ca1-9a76-19899e0e0d7f', '1. Short Circuit (direct contact between live and neutral wires due to damaged insulation) ; and 2. Overloading (connecting too many high-power appliances to a single socket)', true, 'f896e2ef-4278-4001-abe4-5fe70f201321');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2058b606-5205-4494-8e38-2e755bff37fc', 'High room temperature and heavy rain', false, 'f896e2ef-4278-4001-abe4-5fe70f201321');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8fa8f1a-3ac9-43a4-a0f0-16aeaad93f80', 'Turning on light bulbs during the day', false, 'f896e2ef-4278-4001-abe4-5fe70f201321');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e20ec09d-0686-4cff-98d2-91d844e13fbf', 'Using long wires', false, 'f896e2ef-4278-4001-abe4-5fe70f201321');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('55eb8ac0-5aa6-4c93-9ecf-72c6c246f31c', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'How can the magnetic strength of a simple solenoid Electromagnet be significantly INCREASED?', 'Magnetic flux density B is directly proportional to turn density and current (B = μ·n·I) around a ferromagnetic soft iron core.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46224774-cc5b-4557-8c33-cb9ce150058a', 'By increasing the number of turns of the insulated wire coil, and by increasing the magnitude of electric current flowing through it', true, '55eb8ac0-5aa6-4c93-9ecf-72c6c246f31c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94b18469-81a8-49ff-836d-30b3bc27bf71', 'By using a plastic core instead of iron', false, '55eb8ac0-5aa6-4c93-9ecf-72c6c246f31c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('634ac1c0-0aaf-4e93-8aa0-746a07361a4c', 'By reducing the number of turns to one', false, '55eb8ac0-5aa6-4c93-9ecf-72c6c246f31c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a98ba032-0d1d-4111-a8f7-cbb2f9679d80', 'By cooling the wire in ice', false, '55eb8ac0-5aa6-4c93-9ecf-72c6c246f31c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c0568e8-aa5f-4d35-a741-143a1fb57b75', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'Why should an ordinary copper wire NEVER be used as a replacement fuse wire in a fuse carrier?', 'Copper has a high melting point (~1,085°C), defeating the safety purpose of a calibrated low-melting-point lead-tin eutectic fuse wire.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20bead50-d5d9-47a9-b843-e7691b6ae755', 'Copper has a very high melting point and low resistance; it will NOT melt during heavy current overloads, causing house wires to catch fire and burn appliances', true, '1c0568e8-aa5f-4d35-a741-143a1fb57b75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fb220e6-68bd-4543-8000-1bc66dc99617', 'Copper does not conduct electricity', false, '1c0568e8-aa5f-4d35-a741-143a1fb57b75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d244e5c-d668-4ed6-8814-bfd33a2661f0', 'Copper attracts lightning', false, '1c0568e8-aa5f-4d35-a741-143a1fb57b75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7dbb7d09-1871-4959-8a13-ce8c31e3439c', 'Copper turns into water', false, '1c0568e8-aa5f-4d35-a741-143a1fb57b75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('de48ca21-089c-4aeb-9e1c-9bae6d1521bd', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'How does the ''Make-and-Break'' contact screw mechanism work in an Electric Bell?', 'The electromechanical contact interrupter self-oscillates: magnetic attraction breaks the circuit, spring restores contact, creating continuous ringing.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('209db1de-f9a8-4343-8397-4557b77d07bf', 'When the electromagnet attracts the iron armature to strike the gong, it pulls the contact strip away from the screw, breaking the circuit; the electromagnet loses magnetism, the spring pulls the armature back, re-establishing contact to repeat the cycle rapidly', true, 'de48ca21-089c-4aeb-9e1c-9bae6d1521bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b2306f9-031c-40e3-8586-df5f5bcb42c7', 'The bell is struck by hand', false, 'de48ca21-089c-4aeb-9e1c-9bae6d1521bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62324d47-0904-4191-b74d-5d940e176ce8', 'A motor rotates the bell', false, 'de48ca21-089c-4aeb-9e1c-9bae6d1521bd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46f9fe7f-e413-483f-a18b-434a268930fb', 'The bell rings by sound waves', false, 'de48ca21-089c-4aeb-9e1c-9bae6d1521bd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('732f1344-93e4-4d18-9398-fd718b22c0f4', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'Why are powerful industrial Electromagnets attached to giant cranes in junkyards and steel factories?', 'Heavy-duty lifting electromagnets switch magnetic hold instantaneously, revolutionizing scrap metal handling without mechanical hooks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdaf4cfe-5809-4f9b-9b73-68bf91de913f', 'To effortlessly lift, move, and sort heavy scrap iron, steel plates, and magnetic debris by simply turning the electric current ON to pick up and OFF to drop', true, '732f1344-93e4-4d18-9398-fd718b22c0f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fb2a223-89db-4ce7-aaa1-3649074148d8', 'To weld cars together', false, '732f1344-93e4-4d18-9398-fd718b22c0f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4a5ca17-e686-4886-8acd-1abf9583a49e', 'To generate electricity from trash', false, '732f1344-93e4-4d18-9398-fd718b22c0f4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46037421-b2fe-4ef5-aee3-e35361171e18', 'To paint steel beams', false, '732f1344-93e4-4d18-9398-fd718b22c0f4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1f8c92d8-5fda-416a-90d3-9268366b60a5', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'What is the medical application of tiny specialized Electromagnets in hospitals?', 'Eye surgeons use micro-electromagnets to non-invasively extract ferromagnetic foreign particles embedded in ocular tissues.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3de63115-5400-4969-b065-921874b0ba6a', 'Ophthalmic surgeons use miniature electromagnets to safely extract tiny accidental iron splinters from a patient''s eye', true, '1f8c92d8-5fda-416a-90d3-9268366b60a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21a3fc02-a751-4abd-b1aa-3dbba9466845', 'To heal broken bones', false, '1f8c92d8-5fda-416a-90d3-9268366b60a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90a6e794-65d1-40ff-8ac0-791aadb8f958', 'To test blood sugar', false, '1f8c92d8-5fda-416a-90d3-9268366b60a5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('121d3366-11b6-45ff-8c26-7d6a36c52973', 'To measure body temperature', false, '1f8c92d8-5fda-416a-90d3-9268366b60a5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d50ae7fb-d452-4457-b662-219b96c4035a', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'What physical factors determine the amount of heat produced in a current-carrying wire according to Joule''s Heating Law?', 'Joule''s heat H = I²Rt depends on current squared (I²), resistance R (governed by material ρ, length L, and cross-section A), and time t.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34649ab1-a367-43e3-a786-27a771811009', 'The Material of the wire (resistivity), its Length, its Thickness (cross-sectional area), and the Duration of time current flows through it (H ∝ I²Rt)', true, 'd50ae7fb-d452-4457-b662-219b96c4035a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ee7e3f9-ca9f-4dd3-a6e2-5aac52dc298a', 'The color of the wire only', false, 'd50ae7fb-d452-4457-b662-219b96c4035a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0681b42a-b2a5-4566-af78-4c84bebcdfd2', 'The atmospheric air pressure only', false, 'd50ae7fb-d452-4457-b662-219b96c4035a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d39ddf16-e7b4-4dcf-b224-38b77dcfefbf', 'The shape of the switch', false, 'd50ae7fb-d452-4457-b662-219b96c4035a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4a4b999a-d042-4ffe-964a-3c04a5880e81', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'What happens when a magnetic compass is placed near an electric wire and the switch is turned ON?', 'Oersted effect: the concentric magnetic field lines induced by the current exert a torque on the compass magnetic dipole.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f52c4f6-0616-4bfd-a6b9-bbdb861be597', 'The magnetic needle immediately deflects from its North-South alignment due to the magnetic field generated by the electric current', true, '4a4b999a-d042-4ffe-964a-3c04a5880e81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca6a7e13-142f-4d06-805e-6161955a86a2', 'The compass needle spins forever like a fan', false, '4a4b999a-d042-4ffe-964a-3c04a5880e81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb5bb3ce-7eb3-4e08-8a85-a5bba057c1a6', 'The compass catches fire', false, '4a4b999a-d042-4ffe-964a-3c04a5880e81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b853ce60-84fe-4a7c-bd7b-f357806798cb', 'Nothing happens to the compass', false, '4a4b999a-d042-4ffe-964a-3c04a5880e81');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e2e2346c-09d0-4293-9bbe-edd1a2ab2741', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'Why does the connecting copper wire in an electric circuit remain cool while the Nichrome element in an electric toaster glows bright red?', 'In a series circuit with constant current I, heat generation is directly proportional to resistance (H ∝ R); R_nichrome >> R_copper.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f0245fd-0776-407d-8a26-f4f97d29fa61', 'Copper has extremely low electrical resistance (producing negligible heat), whereas Nichrome has very high resistance and dissipates immense heat (H ∝ R)', true, 'e2e2346c-09d0-4293-9bbe-edd1a2ab2741');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11d3950d-aba7-4453-af0d-383b7a477db2', 'Copper is kept in water', false, 'e2e2346c-09d0-4293-9bbe-edd1a2ab2741');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0d9f18e-984d-45b5-b653-5e784c8c6504', 'Nichrome is painted red', false, 'e2e2346c-09d0-4293-9bbe-edd1a2ab2741');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70df19e7-d65b-4363-bc3d-ae245068e4cf', 'Copper has no current', false, 'e2e2346c-09d0-4293-9bbe-edd1a2ab2741');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ad93140b-3f49-4261-acad-9de5b84c5ded', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'What happens when the filament of an electric bulb breaks (burns out / gets ''fused'')?', 'A severed filament creates an open circuit (infinite resistance), arresting current flow through the bulb.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6d14495-b5ef-44d9-9369-894fbca88bb6', 'The electrical circuit becomes OPEN (broken), current stops flowing, and the bulb cannot emit light', true, 'ad93140b-3f49-4261-acad-9de5b84c5ded');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a79d67c1-7499-4a86-964a-0a3364f39cc5', 'The bulb shines twice as bright', false, 'ad93140b-3f49-4261-acad-9de5b84c5ded');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8453e352-121d-40e3-83d0-1fc52c8c7484', 'The battery charges automatically', false, 'ad93140b-3f49-4261-acad-9de5b84c5ded');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('862d407b-8a4e-4c97-b092-d8b501710c16', 'The bulb changes color to green', false, 'ad93140b-3f49-4261-acad-9de5b84c5ded');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a20d559-8eae-4ffc-bf1d-3c5ced22df74', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'Which of the following household appliances utilizes the HEATING effect of electric current?', 'Geysers, toasters, irons, and room heaters convert electrical energy into thermal energy via resistive Joule heating elements.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27d56126-6bad-46d8-9c59-af37417d67b3', 'Electric Geyser, Electric Toaster, Electric Iron, Room Heater', true, '0a20d559-8eae-4ffc-bf1d-3c5ced22df74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c29fe1d-0ad4-4e96-8fe3-20dd79fc431c', 'Electric Fan, Mixer Grinder, Washing Machine', false, '0a20d559-8eae-4ffc-bf1d-3c5ced22df74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73269fc9-0174-43e3-9d96-3cda5c521eba', 'Radio, Television, Mobile phone', false, '0a20d559-8eae-4ffc-bf1d-3c5ced22df74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e842f4c0-0b34-445a-9699-6dc81047dd9c', 'Refrigerator, Air Conditioner', false, '0a20d559-8eae-4ffc-bf1d-3c5ced22df74');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a92b59d-f800-4d44-825f-3aacb51f5463', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'Which of the following household appliances utilizes the MAGNETIC effect of electric current (Electric Motors)?', 'Electric motors in fans, washing machines, and pumps convert electrical energy into mechanical rotation via electromagnetic Lorentz forces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3ba5416-86d4-426f-9abe-82b7bd9d9e7b', 'Electric Fan, Washing Machine, Mixer Grinder, Water Pump', true, '1a92b59d-f800-4d44-825f-3aacb51f5463');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e0fe086-233b-4e7d-80df-f8f6c74eeefb', 'Electric Kettle, Immersion Rod, Electric Heater', false, '1a92b59d-f800-4d44-825f-3aacb51f5463');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ec3a62f-833a-490d-bae8-b7ec5196b2c4', 'Flashlight bulb, Candle, Lamp', false, '1a92b59d-f800-4d44-825f-3aacb51f5463');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b20eeb7b-640b-4d6c-b34a-61c5dce06f9a', 'Electric Iron', false, '1a92b59d-f800-4d44-825f-3aacb51f5463');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3496ce6b-b93d-4f2e-a542-cb82cbdeb71f', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'What is the function of a Switch (Key) in an electric circuit?', 'A switch mechanically bridges or opens circuit continuity to control current flow to electrical loads.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22021513-0565-487d-98aa-6b6e7c37088a', 'It is a simple deliberate device used to either close (COMPLETE) or open (BREAK) the electric circuit at will', true, '3496ce6b-b93d-4f2e-a542-cb82cbdeb71f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f231bb8e-b809-4802-9e64-c0e02ce54e55', 'It generates electric voltage', false, '3496ce6b-b93d-4f2e-a542-cb82cbdeb71f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0a23b10-b378-44f6-9ed4-9fe4d533ca95', 'It changes AC into DC', false, '3496ce6b-b93d-4f2e-a542-cb82cbdeb71f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cef286a-bfa7-4f0d-99f7-e3b351e3b368', 'It cools the wires', false, '3496ce6b-b93d-4f2e-a542-cb82cbdeb71f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('465953f8-5a4a-4397-bbcd-01916817a20e', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Medium', 'What is the core material traditionally used inside an electromagnet coil to achieve maximum temporary magnetic strength?', 'Soft iron possesses high magnetic permeability and low retentivity (coercivity), magnetizing strongly and demagnetizing instantly.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46ea5926-5f9c-4ae5-b356-e08a6d237b39', 'Soft Iron (due to high magnetic permeability and low retentivity)', true, '465953f8-5a4a-4397-bbcd-01916817a20e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c83778e5-db84-4785-93a0-6f6fda742c2d', 'Hard Steel', false, '465953f8-5a4a-4397-bbcd-01916817a20e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dee64db7-b184-497b-8973-3bab6dc5de8d', 'Wood', false, '465953f8-5a4a-4397-bbcd-01916817a20e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a99bb95d-c9e1-4af8-9810-302c4f36dd7e', 'Glass', false, '465953f8-5a4a-4397-bbcd-01916817a20e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23432a3b-066b-4550-8097-577eb0dd64be', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8f526c9-a544-4e35-893c-78bb7d4732af', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '23432a3b-066b-4550-8097-577eb0dd64be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24038000-3df2-449b-ab67-13a5a5920155', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '23432a3b-066b-4550-8097-577eb0dd64be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('41b352f2-ccf6-45ca-b2f0-fe8533cc0825', '(A) is true, but (R) is false.', false, '23432a3b-066b-4550-8097-577eb0dd64be');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e9f96d6-5805-4520-87df-501964dcb7fd', '(A) is false, but (R) is true.', false, '23432a3b-066b-4550-8097-577eb0dd64be');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2050929c-9ab8-4eaf-8b87-c3657dba94c0', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'Spot the IMPOSTER in the following group of Electrical Components and their standard circuit symbols:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9362e528-f1db-4da3-be0c-0e574886932b', 'Symbol 1', false, '2050929c-9ab8-4eaf-8b87-c3657dba94c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d2830628-4c2a-4270-ae0e-67e6224cd10a', 'Symbol 2', false, '2050929c-9ab8-4eaf-8b87-c3657dba94c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de44afbc-b71d-4c7e-bf38-599d2f4b2e99', 'Symbol 3', false, '2050929c-9ab8-4eaf-8b87-c3657dba94c0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f733f0ae-77f0-4f8d-a6ae-af4351f60a93', 'Symbol 4 (The standard symbol for an electric bulb is a circle with a LOOPED FILAMENT inside, NOT a live burning fire)', true, '2050929c-9ab8-4eaf-8b87-c3657dba94c0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7212da8f-2c0c-495e-846d-4ae21d7e2362', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'If an electric iron draws a current of 5 A from a 220 V supply line and has an internal resistance of 44 Ω, calculate the amount of HEAT energy generated in 10 minutes (600 seconds):', 'H = I²Rt = (25)(44)(600) = 660,000 J = 660 kJ.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dda6a10c-8d83-479d-8770-3007b7aa4e7e', '660,000 Joules or 660 kJ (Heat H = I² × R × t = 5² × 44 × 600 = 25 × 44 × 600 = 1,100 × 600 = 660,000 J)', true, '7212da8f-2c0c-495e-846d-4ae21d7e2362');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8961e1e7-cc43-4372-abe3-d9c41567eeaf', '330,000 J', false, '7212da8f-2c0c-495e-846d-4ae21d7e2362');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d2a2354-4cfa-4167-a195-11200e414cc7', '550,000 J', false, '7212da8f-2c0c-495e-846d-4ae21d7e2362');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec141b30-5a48-435d-afe2-1a235642150f', '440,000 J', false, '7212da8f-2c0c-495e-846d-4ae21d7e2362');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11ce080b-3f4f-41c0-809e-039805c4821c', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'Match Column I (Electrical Devices) with Column II (Core Physical Operating Principles):
(a) Electric Geyser   -> (i) High-resistance Joule heating effect in Nichrome
(b) Electric Bell     -> (ii) Rapid electromechanical make-and-break electromagnetic attraction
(c) Electric Fuse     -> (iii) Sacrificial thermal melting at rated ampacity threshold
(d) Magnetic Compass  -> (iv) Deflection by induced magnetic dipole torque around current', 'Geyser = Joule heating; Bell = make-break electromagnetism; Fuse = thermal melting; Compass = Oersted deflection.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5eca1fe1-cdba-45f0-ba63-9f9d42cb915d', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '11ce080b-3f4f-41c0-809e-039805c4821c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fb045c6-5dd7-4a72-a405-9d2d61dc29f1', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '11ce080b-3f4f-41c0-809e-039805c4821c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27f975a6-b297-49cc-8366-e1271ee2a64d', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '11ce080b-3f4f-41c0-809e-039805c4821c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44a0938f-24c5-4261-bbe2-810f0e82fbd7', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '11ce080b-3f4f-41c0-809e-039805c4821c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8cdedc9-b8b2-4d4f-9419-0018928c11db', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'Read the statements regarding electromagnetism:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4c42d19-5dc1-4445-9cf8-324d18fed354', 'Statements 1 and 2 only', true, 'c8cdedc9-b8b2-4d4f-9419-0018928c11db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0aea75bd-0234-4393-afd3-6c32f9d5550b', 'Statements 2 and 3 only', false, 'c8cdedc9-b8b2-4d4f-9419-0018928c11db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33688706-e29b-4077-8b4d-3137700027de', 'Statements 1 and 3 only', false, 'c8cdedc9-b8b2-4d4f-9419-0018928c11db');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efa1243c-709f-4b32-8c74-1ee602c2efa7', 'All Statements 1, 2, and 3', false, 'c8cdedc9-b8b2-4d4f-9419-0018928c11db');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19bf220e-ece9-4928-a4f3-6fed9c78e6f0', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'Why is an inert gas mixture (like Argon with Nitrogen) filled inside traditional incandescent glass light bulbs instead of ordinary air?', 'Inert argon/nitrogen atmosphere prevents high-temperature oxidation of tungsten and retards filament vaporization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72287b4c-e58e-4989-92bb-ce186782359e', 'Ordinary air contains Oxygen, which would instantly oxidize and burn up the white-hot Tungsten filament into smoke; inert Argon prevents oxidation and suppresses tungsten evaporation', true, '19bf220e-ece9-4928-a4f3-6fed9c78e6f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa0d6e20-ae52-4596-9cdc-384e6c22605b', 'To make the bulb lighter so it can float', false, '19bf220e-ece9-4928-a4f3-6fed9c78e6f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6228f077-bda9-4bd0-a9d8-08584c754238', 'Because argon is cheaper than air', false, '19bf220e-ece9-4928-a4f3-6fed9c78e6f0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bd4fbfd-1d9e-41f5-b93e-be7509c3005d', 'To produce colored sparks', false, '19bf220e-ece9-4928-a4f3-6fed9c78e6f0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('65e07756-0855-42eb-82a4-eb43a1773bd2', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'How do Maglev (Magnetic Levitation) high-speed bullet trains use superconducting Electromagnets to travel at speeds exceeding 500 km/h?', 'Electromagnetic suspension (EMS) and linear synchronous propulsion eliminate mechanical wheel-rail friction in Maglev transit.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a230b125-7cf4-429a-9135-14dc59a7c8be', 'Powerful electromagnets create magnetic repulsion that levitates the train frictionless above the guideway track, propelling it forward with alternating linear electromagnetic fields', true, '65e07756-0855-42eb-82a4-eb43a1773bd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98b854fd-0f99-4d44-9cd7-cb0c3cbce8e3', 'They burn coal in giant boilers', false, '65e07756-0855-42eb-82a4-eb43a1773bd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3aefc2ee-1942-4896-8ba5-ecabdbd4128a', 'They have giant rubber wheels moved by wind', false, '65e07756-0855-42eb-82a4-eb43a1773bd2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b32615d2-62fc-4cab-b70f-a9552105d672', 'They slide on ice tracks', false, '65e07756-0855-42eb-82a4-eb43a1773bd2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('112b9dcb-f4c6-4a54-b5bb-d0d20790aed7', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'Consider four circuit configurations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28ca905d-5c42-4077-b43f-431384686bdb', 'Configurations 1, 2, and 4 only', true, '112b9dcb-f4c6-4a54-b5bb-d0d20790aed7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9eeda14e-98e1-4ab1-8992-bb7c5ac85679', 'Configuration 3 only', false, '112b9dcb-f4c6-4a54-b5bb-d0d20790aed7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96fbae67-6d7f-44ff-ad60-18e8df5d8591', 'Configurations 2 and 3 only', false, '112b9dcb-f4c6-4a54-b5bb-d0d20790aed7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6524579-c482-4959-aa42-e70271f0068e', 'All 1, 2, 3, and 4', false, '112b9dcb-f4c6-4a54-b5bb-d0d20790aed7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7440d50-41ba-4539-a717-6e35916b0cc3', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'What physical property distinguishes a Bimetallic Strip used in thermal thermostat switches and thermal MCBs?', 'Differential linear thermal expansion (α_brass > α_iron) forces mechanical curvature that trips electrical contacts in thermal overloads.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b549415-e7d9-474c-9cf3-adeb40ba5c11', 'Two different metals (e.g. brass and iron) with different thermal expansion coefficients bonded together; differential expansion causes the strip to bend upon heating, breaking the circuit at a set temperature', true, 'b7440d50-41ba-4539-a717-6e35916b0cc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96ac190c-6709-4cb7-90d2-1004c6eee2df', 'It produces electricity from light', false, 'b7440d50-41ba-4539-a717-6e35916b0cc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eef79462-eee8-4b9f-bd54-43a5218f6e61', 'It turns into liquid metal', false, 'b7440d50-41ba-4539-a717-6e35916b0cc3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba6d37db-751b-4f9c-bae6-9321ecd43c62', 'It magnetizes wood', false, 'b7440d50-41ba-4539-a717-6e35916b0cc3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2752571b-0845-42d5-83ea-dae6f76d360e', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'Why does an electric heater element made of Nichrome (resistance ~50 Ω) glow red-hot, while the copper connecting cord (resistance ~0.05 Ω) supplying the exact same current remains completely cool to the touch?', 'Series current is uniform; thermal dissipation scales strictly with resistance (P = I²R), producing 1000× more heat in Nichrome.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b4762ff9-3400-4480-9433-3219d55e9350', 'Because power dissipation P = I²R is 1,000 times greater in the Nichrome element than in the copper leads carrying identical series current', true, '2752571b-0845-42d5-83ea-dae6f76d360e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('706301e9-e360-4cee-ba6c-926c3ed3b5fb', 'Because copper is insulated with cold water', false, '2752571b-0845-42d5-83ea-dae6f76d360e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53cc45e5-0674-4534-a7bc-c7b28ab2e4cd', 'Because current only enters the Nichrome', false, '2752571b-0845-42d5-83ea-dae6f76d360e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49f9a2c0-98b6-4522-849f-415ee2cf53cf', 'Because Nichrome absorbs cold from the room', false, '2752571b-0845-42d5-83ea-dae6f76d360e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c73c3e75-4b59-4291-a732-5d774594542c', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'What is the function of the permanent magnet inside an acoustic Loudspeaker when combined with an electromagnetic Voice Coil?', 'Electrodynamic speakers translate variable AC audio currents into mechanical diaphragmatic acoustic vibrations via Lorentz forces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8945bd0e-b1e0-43d5-9a89-ce9abc258521', 'Audio electrical signals passing through the voice coil generate fluctuating magnetic fields that interact with the permanent magnet, rapidly vibrating the speaker cone to produce audible sound waves', true, 'c73c3e75-4b59-4291-a732-5d774594542c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f25907f2-1b69-4f32-b999-81fd7f686c65', 'To keep the speaker cool', false, 'c73c3e75-4b59-4291-a732-5d774594542c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('919432ca-d002-462b-afdb-ecf3fe642383', 'To store digital songs', false, 'c73c3e75-4b59-4291-a732-5d774594542c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0997816f-7e6b-4f2b-90ab-dce7835e7de9', 'To filter radio stations', false, 'c73c3e75-4b59-4291-a732-5d774594542c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a75a910f-1eed-4604-9a46-bb48ba369a6b', 'Class 7', 'Science', 'Chapter 10: Electric Current and its Effects', 'Hard', 'What grand technological unification is established in Chapter 10 of NCERT Class 7 Science?', 'Chapter 10 unifies electro-thermal conversion, circuit schematic symbology, safety interruption, and foundational electromagnetism.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39d78578-0ba7-4918-875d-ead4c43ed74d', 'The profound transformation of electrical energy into thermal heat, radiant light, and controllable magnetic forces—underpinning the entire infrastructure of modern domestic appliances, electrical safety engineering, and electromechanical automation', true, 'a75a910f-1eed-4604-9a46-bb48ba369a6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2545ab46-d589-4bc2-a169-cdebf7470dda', 'That electricity is dangerous and should never be used', false, 'a75a910f-1eed-4604-9a46-bb48ba369a6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6706b6e1-56bf-4068-a48e-4e0800b2803e', 'That magnets have no connection to electricity', false, 'a75a910f-1eed-4604-9a46-bb48ba369a6b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9068d841-bd56-42af-b38d-fb6f8534b869', 'That all circuits must be powered by steam engines', false, 'a75a910f-1eed-4604-9a46-bb48ba369a6b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c8e7e81b-31bf-43d6-892f-e8eb1bacf36c', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'In an algebraic expression, a quantity that can take various numerical values is called a:', 'A variable is a letter or symbol that represents an unknown quantity capable of assuming different numerical values.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d526fb35-9472-4d7b-b940-d291183b3b1c', 'Variable (e.g. x, y, z, a, b)', true, 'c8e7e81b-31bf-43d6-892f-e8eb1bacf36c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c555e5df-72c2-4a99-ab34-001ec200e228', 'Constant', false, 'c8e7e81b-31bf-43d6-892f-e8eb1bacf36c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb03f54e-cf62-45aa-b88f-579fdcdafa27', 'Coefficient only', false, 'c8e7e81b-31bf-43d6-892f-e8eb1bacf36c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a429ee5-d35c-42f8-9b19-93ba219c2630', 'Exponent', false, 'c8e7e81b-31bf-43d6-892f-e8eb1bacf36c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07f65f48-953d-406a-89ce-38cdfcca2f2d', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'A quantity in an algebraic expression that has a FIXED numerical value is called a:', 'A constant is a term with a fixed, unchangeable numeric value.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c20366c-47f2-43d3-9f0e-d92d59eb0788', 'Constant (e.g. 4, -7, 100)', true, '07f65f48-953d-406a-89ce-38cdfcca2f2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f33672dc-18d0-42f5-aa19-214b24102d6b', 'Variable', false, '07f65f48-953d-406a-89ce-38cdfcca2f2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e8e03c8-0b8d-4f56-aa85-8bcd496cc283', 'Literal coefficient', false, '07f65f48-953d-406a-89ce-38cdfcca2f2d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afc7dea3-5709-4c0b-b615-39135a46a024', 'Degree', false, '07f65f48-953d-406a-89ce-38cdfcca2f2d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23e4a078-8e87-4841-b1d6-28bf69370da6', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'What are the TERMS of the algebraic expression 4x² - 3xy + 7?', 'Terms are parts of an expression separated by addition or subtraction: 4x², -3xy, and 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc4d42b9-5cfd-4aad-acea-49b7798518df', '4x², -3xy, and 7', true, '23e4a078-8e87-4841-b1d6-28bf69370da6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbd7f927-59b1-4ab0-99e5-df333c1a3815', '4x, 3xy, and 7', false, '23e4a078-8e87-4841-b1d6-28bf69370da6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c5c3751-9166-43cf-bd45-0a9368086b2a', '4, -3, and 7', false, '23e4a078-8e87-4841-b1d6-28bf69370da6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4db292dd-f784-4947-b599-804c953a05b7', 'x² and xy', false, '23e4a078-8e87-4841-b1d6-28bf69370da6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b917ed7b-dfaf-42b2-b45f-f780cb3cb370', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'In the algebraic term -7xy², what is the NUMERICAL COEFFICIENT?', 'The numerical factor in a term is its numerical coefficient (-7).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa3abc8a-3dbe-4c20-a821-71cbb1778749', '-7', true, 'b917ed7b-dfaf-42b2-b45f-f780cb3cb370');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('761de7c5-b921-4cef-865f-ffc8732fe1b6', '7', false, 'b917ed7b-dfaf-42b2-b45f-f780cb3cb370');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66c748c0-cda5-4974-ba1c-965d146767d5', 'xy²', false, 'b917ed7b-dfaf-42b2-b45f-f780cb3cb370');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eea9adb2-670c-40fe-992b-9aaa9627567a', '-7x', false, 'b917ed7b-dfaf-42b2-b45f-f780cb3cb370');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1aef8426-392f-44bf-b35d-4ca008ca0514', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'An algebraic expression containing exactly ONE single term (e.g. 7xy, -5x², 3) is called a:', 'A monomial is an algebraic expression consisting of a single term.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61c9b849-4a64-4588-89ff-ab6ee4caed76', 'Monomial', true, '1aef8426-392f-44bf-b35d-4ca008ca0514');
