INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7b0ee8b-fa77-47e9-8d9a-59f992c338a2', 'Trinomial', false, '1aef8426-392f-44bf-b35d-4ca008ca0514');
