INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fda8927a-fa2e-4bd8-96ff-cf4e2394fd8e', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'An algebraic expression containing exactly TWO unlike terms (e.g. a + b, 4l + 5m) is called a:', 'A binomial consists of exactly two non-zero unlike terms.', NOW()) ON CONFLICT DO NOTHING;
