INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e8fcb7a-d269-416d-b23b-e5a90ad9334b', 'Monomial', false, 'fda8927a-fa2e-4bd8-96ff-cf4e2394fd8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67f3536d-fd5c-46a7-9659-e26d30c2c7bf', 'Trinomial', false, 'fda8927a-fa2e-4bd8-96ff-cf4e2394fd8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06d7d65f-ed35-443a-b0d3-b903754a09bf', 'Constant', false, 'fda8927a-fa2e-4bd8-96ff-cf4e2394fd8e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23c432b1-97a4-4551-a831-93ec6f55ad47', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'An algebraic expression containing exactly THREE unlike terms (e.g. x + y + z, 2a - 3b + 5) is called a:', 'A trinomial contains exactly three non-zero unlike terms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6614d3a2-b657-4536-86b0-c33b4209254d', 'Trinomial', true, '23c432b1-97a4-4551-a831-93ec6f55ad47');
