INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf8caf7b-99f9-4eee-b710-662eb1ca6a0c', 'Binomial', false, '23c432b1-97a4-4551-a831-93ec6f55ad47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3a82e72-9a14-42ed-851d-11b9a04d8c4c', 'Degree', false, '23c432b1-97a4-4551-a831-93ec6f55ad47');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78f286f4-b436-4b0d-9c59-8c2cdff261a4', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'Terms that have the EXACT SAME algebraic variable factors and powers (e.g. 7x and -12x, or 3xy² and 8y²x) are called:', 'Like terms have identical variable components with matching exponents, differing only in numerical coefficients.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98589b18-b869-40bc-849c-bacabb799b10', 'Like Terms', true, '78f286f4-b436-4b0d-9c59-8c2cdff261a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cda217c-525e-4e22-8078-6945d973868f', 'Unlike Terms', false, '78f286f4-b436-4b0d-9c59-8c2cdff261a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73bb3770-636d-4117-a5ff-2c58e5265965', 'Constants', false, '78f286f4-b436-4b0d-9c59-8c2cdff261a4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccfb5079-717f-4443-a34e-e9a64b7cfb7d', 'Binomials', false, '78f286f4-b436-4b0d-9c59-8c2cdff261a4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ce329c8-df4f-48da-ab6c-858ae3f00b6a', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'Simplify by combining like terms: 12m² - 9m + 5m - 4m² - 7m + 10:', '(12-4)m² + (-9+5-7)m + 10 = 8m² - 11m + 10.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0e4ca0f-a94d-42c7-b986-d55f9068118d', '8m² - 11m + 10 ((12 - 4)m² + (-9 + 5 - 7)m + 10 = 8m² - 11m + 10)', true, '2ce329c8-df4f-48da-ab6c-858ae3f00b6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75181e64-391b-43eb-a5c9-74425244ceec', '16m² - 11m + 10', false, '2ce329c8-df4f-48da-ab6c-858ae3f00b6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ed69519-0a2b-408b-989d-95171d376fb1', '8m² + 11m - 10', false, '2ce329c8-df4f-48da-ab6c-858ae3f00b6a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4299e6d4-0d8a-473c-8378-fe67a5dd3481', '8m² - 21m + 10', false, '2ce329c8-df4f-48da-ab6c-858ae3f00b6a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a1455d61-fd29-4d56-9bef-4fbc78eb5d66', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'If m = 2, find the value of the algebraic expression 3m - 5:', '3(2) - 5 = 6 - 5 = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c685dafd-331e-4380-95f8-9b2bc1b7898f', '1 (3 × 2 - 5 = 6 - 5 = 1)', true, 'a1455d61-fd29-4d56-9bef-4fbc78eb5d66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d415a112-f565-4809-a8a8-0865127130c8', '-1', false, 'a1455d61-fd29-4d56-9bef-4fbc78eb5d66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1175e5a-daf3-474a-8948-21fe24565d76', '5', false, 'a1455d61-fd29-4d56-9bef-4fbc78eb5d66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc08e503-6f3d-40c1-a268-4bf3f6dc46dd', '6', false, 'a1455d61-fd29-4d56-9bef-4fbc78eb5d66');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f900caf5-ed7c-42b3-b3d3-139ac1a5687e', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'If x = -1, find the value of 2x² - x - 2:', '2(-1)² - (-1) - 2 = 2(1) + 1 - 2 = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1056323-5aa5-433c-9ca1-14cd590b6e43', '1 (2 × (-1)² - (-1) - 2 = 2 × 1 + 1 - 2 = 3 - 2 = 1)', true, 'f900caf5-ed7c-42b3-b3d3-139ac1a5687e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4937a5bf-98c5-4ad1-a9f9-ef511d76446e', '-1', false, 'f900caf5-ed7c-42b3-b3d3-139ac1a5687e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b4a67da-7c72-4280-ae4c-8b64e6596e52', '3', false, 'f900caf5-ed7c-42b3-b3d3-139ac1a5687e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6af7f9aa-00b9-44a3-919a-489b7fbaf09b', '0', false, 'f900caf5-ed7c-42b3-b3d3-139ac1a5687e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6245d93a-1a40-43ef-b484-e4d8fef3623a', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Easy', 'Subtract -5y² from y²:', 'y² - (-5y²) = y² + 5y² = 6y².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64e92e0e-ef04-467a-b3fb-aabbd6700996', '6y² (y² - (-5y²) = y² + 5y² = 6y²)', true, '6245d93a-1a40-43ef-b484-e4d8fef3623a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c729763d-c683-4a1b-b787-dab130e0c975', '-4y²', false, '6245d93a-1a40-43ef-b484-e4d8fef3623a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b80f18b4-2c91-42bb-91c2-928fccd2ebd2', '4y²', false, '6245d93a-1a40-43ef-b484-e4d8fef3623a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98f65cbf-8b64-4c95-bb52-b9b2ef96e638', '-6y²', false, '6245d93a-1a40-43ef-b484-e4d8fef3623a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d9f1089-ee46-4aa0-80c6-888270ed887c', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'Add the algebraic expressions: 7mn + 5, 12mn + 2, 9mn - 8, and -2mn - 3:', 'Sum of coefficients = (7+12+9-2)mn + (5+2-8-3) = 26mn - 4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82404753-b1cb-4cb9-806b-aa7b1cc0b7ea', '26mn - 4 ((7 + 12 + 9 - 2)mn + (5 + 2 - 8 - 3) = 26mn - 4)', true, '1d9f1089-ee46-4aa0-80c6-888270ed887c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bc6b007-ed10-461f-9786-38cc11ae4d38', '28mn - 4', false, '1d9f1089-ee46-4aa0-80c6-888270ed887c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b9bfc76-9906-4fbf-be10-9ba79a4b499c', '26mn + 4', false, '1d9f1089-ee46-4aa0-80c6-888270ed887c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eead0679-7918-4fa4-b1ca-983c1955b06a', '24mn - 6', false, '1d9f1089-ee46-4aa0-80c6-888270ed887c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6da10070-f840-4659-bf50-b7378c8f8e21', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'Subtract 24ab - 10b - 18a from 30ab + 12b + 14a:', '(30-24)ab + (12+10)b + (14+18)a = 6ab + 22b + 32a.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a58441c-27ee-4cb2-a616-4c2fa1546bda', '6ab + 22b + 32a ((30 - 24)ab + (12 - (-10))b + (14 - (-18))a = 6ab + 22b + 32a)', true, '6da10070-f840-4659-bf50-b7378c8f8e21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a96cee60-0c31-470f-b3b1-338d840e607d', '6ab + 2b - 4a', false, '6da10070-f840-4659-bf50-b7378c8f8e21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79b250fe-85f2-4791-8862-262e91e15352', '54ab + 22b + 32a', false, '6da10070-f840-4659-bf50-b7378c8f8e21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('669ede2d-fe4c-42d2-baf0-2c6ce6f169c2', '6ab + 22b - 4a', false, '6da10070-f840-4659-bf50-b7378c8f8e21');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f19b129c-cc25-4216-8e4a-7a4efa1d56b4', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'What should be added to x² + xy + y² to obtain 2x² + 3xy?', '(2x² + 3xy) - (x² + xy + y²) = x² + 2xy - y².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('672c7675-87fa-42fd-93f3-bd334252a878', 'x² + 2xy - y² ((2x² + 3xy) - (x² + xy + y²) = (2-1)x² + (3-1)xy - y² = x² + 2xy - y²)', true, 'f19b129c-cc25-4216-8e4a-7a4efa1d56b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f38934f6-8859-4b59-b4c2-8e20cbd2b8f1', 'x² + 4xy + y²', false, 'f19b129c-cc25-4216-8e4a-7a4efa1d56b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61b1006b-4957-4f9a-916c-be0de47f4500', '3x² + 4xy + y²', false, 'f19b129c-cc25-4216-8e4a-7a4efa1d56b4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad7e55f6-f137-44c9-aca3-d61b9f3a079a', '-x² - 2xy + y²', false, 'f19b129c-cc25-4216-8e4a-7a4efa1d56b4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('71a0ccab-09c4-40e8-bb14-dccc848cad5c', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'What should be subtracted from 2a + 8b + 10 to get -3a + 7b + 16?', '(2a + 8b + 10) - (-3a + 7b + 16) = 5a + b - 6.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('495e3350-e1b1-4f17-b511-3ddfeab65d75', '5a + b - 6 ((2a + 8b + 10) - (-3a + 7b + 16) = (2+3)a + (8-7)b + (10-16) = 5a + b - 6)', true, '71a0ccab-09c4-40e8-bb14-dccc848cad5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('200624b4-31bc-4c58-9800-0631c45bccfe', '-a + 15b + 26', false, '71a0ccab-09c4-40e8-bb14-dccc848cad5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8530c8d2-514e-4f1d-abb2-9c9468f749ad', '5a - b + 6', false, '71a0ccab-09c4-40e8-bb14-dccc848cad5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('286baa97-26af-4c72-9f54-0ed9389ffd73', '-5a - b + 6', false, '71a0ccab-09c4-40e8-bb14-dccc848cad5c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c795828-16d7-4868-ad4a-f448a237dc8b', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'From the sum of 3x - y + 11 and -y - 11, subtract 3x - y - 11:', 'Sum = 3x - 2y. Result = (3x - 2y) - (3x - y - 11) = -y + 11.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0d06332-29ad-4796-bd4d-a3a5aa8775cc', '-y + 11 (Sum = 3x - 2y ; Subtracting: (3x - 2y) - (3x - y - 11) = -2y + y + 11 = -y + 11)', true, '1c795828-16d7-4868-ad4a-f448a237dc8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c5db21d-75a8-49bd-a1bf-7e0d03bab350', 'y + 11', false, '1c795828-16d7-4868-ad4a-f448a237dc8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be083642-7b44-4a6a-8b10-50e27464f7db', '-y - 11', false, '1c795828-16d7-4868-ad4a-f448a237dc8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ada14163-758d-43ca-a687-f8c1d90dcd42', '6x - 3y', false, '1c795828-16d7-4868-ad4a-f448a237dc8b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('95b72e7c-53e3-4b51-9162-782e08f7b816', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'If a = 2 and b = -2, find the value of a² + ab + b²:', '2² + 2(-2) + (-2)² = 4 - 4 + 4 = 4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d55b33cf-76ca-4a12-a773-3ae669b4be01', '4 (2² + (2 × -2) + (-2)² = 4 - 4 + 4 = 4)', true, '95b72e7c-53e3-4b51-9162-782e08f7b816');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33b486e5-bcb6-47ca-806a-a3b9089cd619', '0', false, '95b72e7c-53e3-4b51-9162-782e08f7b816');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f512cbd9-870d-4232-894d-47211d2c580e', '8', false, '95b72e7c-53e3-4b51-9162-782e08f7b816');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a34b3d9-7f34-4173-bdd5-0c9afbf27424', '12', false, '95b72e7c-53e3-4b51-9162-782e08f7b816');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('30dcf3b5-8659-4195-a9a1-d370fd981743', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'If x = 0 and y = -1, find the value of 2x²y + 2xy² + xy:', '2(0)²(-1) + 2(0)(-1)² + (0)(-1) = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44ac1d9c-1f60-4a16-9dd9-2fce16b483bf', '0 (Since x = 0, every product term containing x becomes 0: 0 + 0 + 0 = 0)', true, '30dcf3b5-8659-4195-a9a1-d370fd981743');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70390276-ef62-4b71-9e4d-38fcf854726e', '-1', false, '30dcf3b5-8659-4195-a9a1-d370fd981743');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('719eab0c-24a1-4f99-9d68-5d5ec521c383', '2', false, '30dcf3b5-8659-4195-a9a1-d370fd981743');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0ad4195-892c-4294-8403-692b6797e11c', '-2', false, '30dcf3b5-8659-4195-a9a1-d370fd981743');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1395733-7506-4f45-9f9e-2ede5e9a6ab1', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'Simplify the expression and find its value when x = 3:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ab3b0e5-fa2e-4df3-869f-8da111975ae2', '39 (Expression = 2x² + 2xy - xy + 3 = 2x² + xy + 3 ; For x=3, y=2: 2(9) + (3×2) + 3 = 18 + 6 + 3 = 27 ... Wait: 2(3² + 3×2) + 3 - (3×2) = 2(9+6) + 3 - 6 = 30 + 3 - 6 = 27)', false, 'f1395733-7506-4f45-9f9e-2ede5e9a6ab1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff7bb884-752f-4fed-87f5-a693ab4effd1', '27 (2(9+6) + 3 - 6 = 30 + 3 - 6 = 27)', true, 'f1395733-7506-4f45-9f9e-2ede5e9a6ab1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('034aa6af-f235-4d85-a87d-c682b6da63c3', '33', false, 'f1395733-7506-4f45-9f9e-2ede5e9a6ab1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7326650a-5e25-4409-86f4-18f8b4eec38f', '24', false, 'f1395733-7506-4f45-9f9e-2ede5e9a6ab1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('251ad2e5-421c-48bb-b6b0-bfbecb375032', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'If the general nth term of a number sequence pattern is given by (3n + 1), find the 10th term and the 25th term of the sequence:', 'T₁₀ = 3(10) + 1 = 31. T₂₅ = 3(25) + 1 = 76.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb6bcd35-26ef-498a-a7a5-e4e993cabe23', '10th term = 31 ; 25th term = 76 (For n = 10: 3(10) + 1 = 31 ; For n = 25: 3(25) + 1 = 76)', true, '251ad2e5-421c-48bb-b6b0-bfbecb375032');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7410bcb6-2131-48cc-adff-270af0658748', '10th term = 30 ; 25th term = 75', false, '251ad2e5-421c-48bb-b6b0-bfbecb375032');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3b1234a-e246-49a6-a440-d7c208b1d848', '10th term = 34 ; 25th term = 79', false, '251ad2e5-421c-48bb-b6b0-bfbecb375032');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e290f1a9-72be-4ccd-90bc-3a7a101731a6', '10th term = 29 ; 25th term = 74', false, '251ad2e5-421c-48bb-b6b0-bfbecb375032');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1bb78da1-56ba-4db0-a84d-2afb5ed2bc00', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'Find the algebraic expression for the PERIMETER of an equilateral triangle of side ''s'':', 'Perimeter of an equilateral triangle = 3 × side = 3s.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1acf7c5-e6e4-43e2-9606-43e4d10221a6', '3s (Perimeter = s + s + s = 3s)', true, '1bb78da1-56ba-4db0-a84d-2afb5ed2bc00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('005caee2-2d13-4b4c-a749-43c6b98cea34', 's³', false, '1bb78da1-56ba-4db0-a84d-2afb5ed2bc00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02ed3139-24d5-44f6-980c-25cc4937a90c', '3 + s', false, '1bb78da1-56ba-4db0-a84d-2afb5ed2bc00');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3af0ca23-0886-4b87-bc07-21475585af59', 's² / 3', false, '1bb78da1-56ba-4db0-a84d-2afb5ed2bc00');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ae981e0-9094-4c18-9a70-0a4c24790714', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'What is the tree diagram factor representation of the term -ab + 2b² - 3a²?', 'Tree factor breakdown: -ab → (-1, a, b); 2b² → (2, b, b); -3a² → (-3, a, a).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92adb6d8-19c0-4cb8-9c32-234a30855efe', 'Terms: (-ab) with factors -1, a, b ; (2b²) with factors 2, b, b ; (-3a²) with factors -3, a, a', true, '3ae981e0-9094-4c18-9a70-0a4c24790714');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63a43970-0df0-4ea3-9f72-8125ed53f288', 'Terms: a, b, and 3', false, '3ae981e0-9094-4c18-9a70-0a4c24790714');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d753803-ace1-4ec7-96e7-74ceeb528429', 'Terms: a²b²', false, '3ae981e0-9094-4c18-9a70-0a4c24790714');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de2a3cd4-7807-4d84-8b9b-06bfd438461f', 'Factors are only positive numbers', false, '3ae981e0-9094-4c18-9a70-0a4c24790714');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2dadf60f-ccea-46a7-96fc-ba10c53f3c8b', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'Identify which pair consists of LIKE TERMS:', '14xy and 42yx are like terms because variable factors xy and yx are algebraically identical.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3eaca86-d646-4d4f-a19d-92ebf7bbe323', '-29x and -29y are unlike ; 14xy and 42yx are LIKE TERMS (xy = yx by commutative law)', true, '2dadf60f-ccea-46a7-96fc-ba10c53f3c8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3afea3b8-abee-4f21-b5e0-cd5fc946eb99', '1 and 100 are unlike', false, '2dadf60f-ccea-46a7-96fc-ba10c53f3c8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('316e01e6-00a2-4d47-a8ce-0836844e4f17', '4m²p and 4mp² are like', false, '2dadf60f-ccea-46a7-96fc-ba10c53f3c8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14fa51ad-3b5f-4451-97af-9866e81baeb0', '12xz and 12x²z² are like', false, '2dadf60f-ccea-46a7-96fc-ba10c53f3c8b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('74817a9c-1e22-4202-81f1-be44b408beb1', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'Find the value of (2a - 2b - 4) - (a - b) when a = 3 and b = 2:', '(2a - a) - (2b - b) - 4 = a - b - 4 = 3 - 2 - 4 = -3.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('861a1944-f2fc-4ec3-b39f-ec47994cf56d', '-3 ((2a - a) - (2b - b) - 4 = a - b - 4 = 3 - 2 - 4 = -3)', true, '74817a9c-1e22-4202-81f1-be44b408beb1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16fcab1d-d903-4f63-975e-31e199042fde', '-1', false, '74817a9c-1e22-4202-81f1-be44b408beb1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb49a4b1-3cfe-44d9-895c-4b94829b4e02', '3', false, '74817a9c-1e22-4202-81f1-be44b408beb1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('749dc673-09a6-4ffd-bb40-cadcd3d686c7', '-5', false, '74817a9c-1e22-4202-81f1-be44b408beb1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('71542157-b23c-4cc5-b53d-571a77fd2a77', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'If z = 10, find the value of z³ - 3(z - 10):', '10³ - 3(10 - 10) = 1000 - 0 = 1,000.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bbbc8e4-6789-4d6f-acfc-c78adc8b89f6', '1,000 (z³ - 3(z - 10) = 10³ - 3(10 - 10) = 1000 - 3(0) = 1,000)', true, '71542157-b23c-4cc5-b53d-571a77fd2a77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34736d9d-36c5-459b-8d13-496ca190716b', '970', false, '71542157-b23c-4cc5-b53d-571a77fd2a77');
