INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('69a1c11d-cf54-4f3b-87b4-719108ded7b8', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'What is the degree of the term 5x²y³?', 'Degree of a monomial term is the sum of exponents of its variable factors: 2 + 3 = 5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3630ca07-3194-49f1-9dc1-5d7223944bf6', '5 (Sum of exponents of variables = 2 + 3 = 5)', true, '69a1c11d-cf54-4f3b-87b4-719108ded7b8');
