INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0dca0b9c-5496-484a-801f-195dcc93f50f', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Medium', 'Write the algebraic expression for: ''Sum of numbers a and b subtracted from their product'':', 'Product = ab; Sum = (a + b). Subtraction of sum from product = ab - (a + b).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e2a1b63-82ab-4d16-bcfd-0a15e8a8b052', 'ab - (a + b)', true, '0dca0b9c-5496-484a-801f-195dcc93f50f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edbc8ce1-964e-4484-aa37-8550c0dc81bd', '(a + b) - ab', false, '0dca0b9c-5496-484a-801f-195dcc93f50f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80d4cf7c-2b8b-43cb-a0c0-5b68778bf223', 'ab + (a + b)', false, '0dca0b9c-5496-484a-801f-195dcc93f50f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b715aa7-c6ae-456e-a6f9-a6601690c357', 'ab / (a + b)', false, '0dca0b9c-5496-484a-801f-195dcc93f50f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ed93030-7031-4243-b84f-2b68b142458b', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4838a9e0-1eaa-4e26-a42a-dc95881e7c28', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '7ed93030-7031-4243-b84f-2b68b142458b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5906581c-d069-48e9-8658-f282a880340a', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '7ed93030-7031-4243-b84f-2b68b142458b');
