INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdc1a090-3f23-4522-92fb-0afe99a85cd1', 'Expression 1', false, '2bfb01f5-6b66-48f8-b880-4d8fb5d35529');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('491ec99f-6de6-4efa-86e5-feeb67d96287', 'Expression 2', false, '2bfb01f5-6b66-48f8-b880-4d8fb5d35529');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be7f9d46-2127-4bf4-a0c9-3588741778eb', 'Expression 3', false, '2bfb01f5-6b66-48f8-b880-4d8fb5d35529');
