INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7f38e705-beac-4d2d-959e-6eb5e1c4c9e1', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'If 2x² + x - a = 5 for x = 0, what is the value of ''a''?', '0 + 0 - a = 5 → -a = 5 → a = -5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51d5e8cd-303f-48f1-8eff-4e465b7a67f4', '-5 (Substitute x = 0: 2(0)² + (0) - a = 5 ⇒ -a = 5 ⇒ a = -5)', true, '7f38e705-beac-4d2d-959e-6eb5e1c4c9e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b16726e-8015-4e25-8f2f-9c874b176097', '5', false, '7f38e705-beac-4d2d-959e-6eb5e1c4c9e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5857d43-d1f0-47b7-98a1-13f7cf71bbd2', '0', false, '7f38e705-beac-4d2d-959e-6eb5e1c4c9e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45328e94-7810-4327-b36f-7a6299ba6aa4', '2', false, '7f38e705-beac-4d2d-959e-6eb5e1c4c9e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eda25257-5ea9-44c9-b5d2-c75047314b4b', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'Match Column I (Algebraic Word Statements) with Column II (Exact Algebraic Expressions):
(a) One-fourth of the product of p and q -> (i) 1/4 pq (or pq/4)
(b) Number 5 added to 3 times product of m & n -> (ii) 3mn + 5
(c) Product of y and z subtracted from 10 -> (iii) 10 - yz
(d) Number x multiplied by itself and added to y² -> (iv) x² + y²', '1/4 pq; 3mn + 5; 10 - yz; x² + y².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9206bad3-d9d9-4b31-8555-5bc73a841d25', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'eda25257-5ea9-44c9-b5d2-c75047314b4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7cf5591-440b-4e51-aaac-c3e4e6341c67', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'eda25257-5ea9-44c9-b5d2-c75047314b4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e121758-bb20-4e19-8570-4eec3c9b3be4', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'eda25257-5ea9-44c9-b5d2-c75047314b4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0a11005-8216-4926-b09a-c0aa2d2eaba8', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'eda25257-5ea9-44c9-b5d2-c75047314b4b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37cb0382-e21a-49bf-ac4e-8408c3246c3b', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'Read the statements regarding algebraic rules:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e103b92-6394-4570-bcc2-aa8ee404fcc1', 'Statements 1 and 2 only', true, '37cb0382-e21a-49bf-ac4e-8408c3246c3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a921886b-ff8a-4eae-8793-fd526c96be0c', 'Statements 2 and 3 only', false, '37cb0382-e21a-49bf-ac4e-8408c3246c3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('445ee085-abcd-42d8-b91b-28b16b167998', 'Statements 1 and 3 only', false, '37cb0382-e21a-49bf-ac4e-8408c3246c3b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d086c4e-6dd6-4fc9-a36a-297afb11e52f', 'All Statements 1, 2, and 3', false, '37cb0382-e21a-49bf-ac4e-8408c3246c3b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ae142e9-8f5d-45ea-90ce-e3053771d3c1', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'Simplify the complex algebraic expression:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('484f41bd-dbbf-49de-af7a-a660d5067a87', '4x² - 2x + 1 (3x² - [2x - x² + 4] + 5 = 3x² - 2x + x² - 4 + 5 = 4x² - 2x + 1)', true, '2ae142e9-8f5d-45ea-90ce-e3053771d3c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29d645b0-1acf-4902-b64d-3a4d28982d99', '2x² - 2x + 9', false, '2ae142e9-8f5d-45ea-90ce-e3053771d3c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4aed0916-b1d5-4c15-bcca-8e98e9eee0c8', '4x² + 2x - 1', false, '2ae142e9-8f5d-45ea-90ce-e3053771d3c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('821adb0b-8ad9-41d4-9baf-988f8278a186', '3x² - 2x + 1', false, '2ae142e9-8f5d-45ea-90ce-e3053771d3c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8747656f-b808-42f9-ac36-26c85144b3e3', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'If A = 3x² - 4x + 1, B = 5x² + 3x - 8, and C = 4x² - 7x + 3, find the expression (A + B - C):', '(3+5-4)x² + (-4+3+7)x + (1-8-3) = 4x² + 6x - 10.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('280a6692-08d0-4c60-9395-b56ec1ae44a0', '4x² + 6x - 10 ((3 + 5 - 4)x² + (-4 + 3 - (-7))x + (1 - 8 - 3) = 4x² + 6x - 10)', true, '8747656f-b808-42f9-ac36-26c85144b3e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52753f20-4dde-4fc1-aaff-664c94c725df', '4x² - 8x + 6', false, '8747656f-b808-42f9-ac36-26c85144b3e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6eb8dc05-5a23-4adc-bf49-3b12f908829a', '12x² - 8x - 4', false, '8747656f-b808-42f9-ac36-26c85144b3e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cfd34bce-21c9-4991-b71e-194cc21878b3', '4x² + 6x + 10', false, '8747656f-b808-42f9-ac36-26c85144b3e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('146f1e1f-7160-41c8-8683-229a3d4fbe50', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'A digital digit display uses matchsticks to form numbers. The number of matchsticks required to form ''n'' repeated digits of the numeral ''8'' follows the formula (5n + 1). How many matchsticks are needed to form 12 digits of ''8''?', 'Number of matchsticks = 5(12) + 1 = 61.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8876312f-fc55-4b13-b5de-40192450e389', '61 matchsticks (For n = 12: 5(12) + 1 = 60 + 1 = 61 matchsticks)', true, '146f1e1f-7160-41c8-8683-229a3d4fbe50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c696485e-b76f-43ce-9a87-7208fe71024c', '60 matchsticks', false, '146f1e1f-7160-41c8-8683-229a3d4fbe50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0efedf8d-8627-43ce-b0c1-a4d3ed1aa8cc', '65 matchsticks', false, '146f1e1f-7160-41c8-8683-229a3d4fbe50');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dea3f707-9fb8-47b8-9aa2-e41e9e99f314', '72 matchsticks', false, '146f1e1f-7160-41c8-8683-229a3d4fbe50');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d764f70-b6aa-4743-a9de-1f7baf8c5b13', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'If x = -2, y = -1, and z = 3, evaluate the algebraic expression: x³ + y³ + z³ - 3xyz:', 'Since x + y + z = -2 + (-1) + 3 = 0, the algebraic identity x³ + y³ + z³ - 3xyz = (x+y+z)(x²+y²+z²-xy-yz-zx) = 0.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81b3c814-1970-4712-aca5-0376fd87788e', '0 (x³ = -8 ; y³ = -1 ; z³ = 27 ; Sum = 18 ; 3xyz = 3(-2)(-1)(3) = 18 ; Value = 18 - 18 = 0)', true, '1d764f70-b6aa-4743-a9de-1f7baf8c5b13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1f36a0f-8470-4586-9842-8379d868b528', '36', false, '1d764f70-b6aa-4743-a9de-1f7baf8c5b13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38cb4ff5-2aa9-420b-b1ee-f4ae1b3c7112', '-18', false, '1d764f70-b6aa-4743-a9de-1f7baf8c5b13');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d24099c-fc92-418d-a0ae-80a1f0b75046', '18', false, '1d764f70-b6aa-4743-a9de-1f7baf8c5b13');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d8e5943c-75c7-4a1f-b5ea-607ab9362ba7', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'What is the coefficient of x²y in the algebraic expansion of 3(x²y - 2xy²) - 4(2x²y + 5xy²)?', '3x²y - 8x²y = -5x²y. The numerical coefficient is -5.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c42f19c-a8b0-4108-82db-e3e1f7887db4', '-5 (3x²y - 6xy² - 8x²y - 20xy² = (3 - 8)x²y - (6 + 20)xy² = -5x²y - 26xy² ; Coefficient of x²y is -5)', true, 'd8e5943c-75c7-4a1f-b5ea-607ab9362ba7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('836f4eb1-40a5-41c7-9ed9-eb5f3418532b', '5', false, 'd8e5943c-75c7-4a1f-b5ea-607ab9362ba7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('209703f4-0ab2-4de1-98a7-f6210c74d9bc', '-26', false, 'd8e5943c-75c7-4a1f-b5ea-607ab9362ba7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa60e9ba-f0a8-4d96-ae89-1402d4a29939', '-11', false, 'd8e5943c-75c7-4a1f-b5ea-607ab9362ba7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('167cfe1a-b737-4bd8-874f-12690d13f011', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'If p = -10, find the value of p² - 2p - 100:', '100 + 20 - 100 = 20.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5a9852f-e8e7-4f93-93e0-e7de0824bd6d', '20 ((-10)² - 2(-10) - 100 = 100 + 20 - 100 = 20)', true, '167cfe1a-b737-4bd8-874f-12690d13f011');
