INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37a889f8-4329-4e72-842a-447efffece6d', 'Class 7', 'Mathematics', 'Chapter 10: Algebraic Expressions', 'Hard', 'Why are Algebraic Expressions considered the fundamental generalized language of modern science, algorithms, and computational modeling?', 'Algebra abstracts arithmetic into symbolic generalizations, enabling formulation of physical laws, algorithmic proofs, and variable parametric modeling.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70eb32e3-f0a8-4c61-8364-46764770b2a4', 'They allow generalized mathematical laws, geometric formulas, physical principles, and algorithmic patterns to be stated concisely and manipulated systematically for any arbitrary inputs', true, '37a889f8-4329-4e72-842a-447efffece6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb8f451a-3e0c-4445-b32a-72a13242e268', 'Because letters take up less paper than numbers', false, '37a889f8-4329-4e72-842a-447efffece6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12927a96-3ac7-4d75-a2a4-b51320242c98', 'Because algebra eliminates the need for arithmetic', false, '37a889f8-4329-4e72-842a-447efffece6d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50c982af-1f1e-4ab9-87ad-fb8a6325dd10', 'Because computers only understand English letters', false, '37a889f8-4329-4e72-842a-447efffece6d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b16c0bd0-b917-46b7-9c99-2ebf68fc240e', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'Where and approximately how many centuries ago did the sport of CRICKET originate as a rural English bat-and-ball game?', 'Cricket grew out of traditional English bat-and-ball folk pastimes played over 500 years ago in rural southeastern England.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91f3f605-4851-40db-af7c-fbc2bac3b470', 'In England, over 500 years ago (16th century)', true, 'b16c0bd0-b917-46b7-9c99-2ebf68fc240e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e889258-bad1-44b6-9115-fba621a30a37', 'In Australia, 100 years ago', false, 'b16c0bd0-b917-46b7-9c99-2ebf68fc240e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86cd2652-9a79-4661-8f48-fa2b53cd76d2', 'In India, during the Mughal era', false, 'b16c0bd0-b917-46b7-9c99-2ebf68fc240e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50f39844-06bb-49c2-91b7-cf68b1ed464f', 'In America, in 1850', false, 'b16c0bd0-b917-46b7-9c99-2ebf68fc240e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49d95fff-ebd2-46be-a2b9-f3f3e21f1cc8', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'What was the shape of early cricket bats before the 1760s?', 'Early cricket was bowled underarm, so bats curved outwards at the base like hockey sticks to sweep the ball off the turf.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7eadfdcd-abc5-4ee0-a1ae-8fd038d3bb50', 'Curved at the bottom like modern Hockey Sticks (to hit the ball bowled underarm along the ground)', true, '49d95fff-ebd2-46be-a2b9-f3f3e21f1cc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb3e41c7-075e-47bd-aca9-e33fd071617e', 'Flat and straight like modern cricket bats', false, '49d95fff-ebd2-46be-a2b9-f3f3e21f1cc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88566663-25cc-4638-b957-15535f8173d8', 'Round like baseball bats', false, '49d95fff-ebd2-46be-a2b9-f3f3e21f1cc8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f71e04f-b70e-4d2d-865e-eb6bf3e7ab55', 'Square shaped like wooden boards', false, '49d95fff-ebd2-46be-a2b9-f3f3e21f1cc8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6b2259a3-3f3e-42d8-b5ad-cbf6bb613800', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'What is the fixed, standardized length of a cricket PITCH according to the official Laws of Cricket?', 'The Laws of Cricket specify pitch length precisely as 22 yards between the wickets, while ground boundary size remains variable.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6fc0acd-0ff8-4afd-9ddd-0a906e10d606', '22 Yards (66 feet / 20.12 metres)', true, '6b2259a3-3f3e-42d8-b5ad-cbf6bb613800');
