INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df736590-f78f-4d5a-82b1-e3eb45a14888', '25 Yards', false, '6b2259a3-3f3e-42d8-b5ad-cbf6bb613800');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc4495db-f365-4fe0-8476-1671c4fae011', '30 Yards', false, '6b2259a3-3f3e-42d8-b5ad-cbf6bb613800');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cddb3d67-d544-4c6d-a939-054022765a7a', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'Which famous London cricket club founded in 1787 became the supreme guardian and custodian of the Laws of Cricket?', 'The MCC (Marylebone Cricket Club), founded in 1787, framed the official Laws of Cricket and remains their custodian.', NOW()) ON CONFLICT DO NOTHING;
