INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77fd5d38-0462-46a6-a01d-ca4e5250017e', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'Which Indian community founded the FIRST Indian cricket club in Bombay (The Oriental Cricket Club) in 1848?', 'The Zoroastrian Parsi community of Bombay established the Oriental Cricket Club in 1848, pioneering Indian cricket.', NOW()) ON CONFLICT DO NOTHING;
