INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bdbc037b-ed94-4eed-b929-32413b945144', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'Who was India''s first great Test match batsman and captain in 1932, after whom the premier domestic first-class trophy is named?', 'C.K. Nayudu was India''s first Test captain when India entered the international Test arena at Lord''s in 1932.', NOW()) ON CONFLICT DO NOTHING;
