INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d786559-07b4-4cfa-bd04-8b0ef8d482ec', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'In what year did India play its first official Test match in England at Lord''s?', 'India played its inaugural Test match against England at Lord''s in June 1932.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc2aeb8e-683d-49cb-a3f0-c959cc454c22', '1932', true, '3d786559-07b4-4cfa-bd04-8b0ef8d482ec');
