INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('05012949-e983-49ef-ac9e-6f4ca24372a5', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'What natural, pre-industrial materials are traditional cricket bat and ball made from even today?', 'Unlike other modern games, cricket''s bat and ball equipment remains hand-crafted from natural timber willow, cane, cork, and leather.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91cc40bd-7f02-45d9-a943-c8e7edd38de5', 'Bat from Willow wood, cane, and twine ; Ball from leather, cork, and twine', true, '05012949-e983-49ef-ac9e-6f4ca24372a5');
