INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a569ed0f-44c2-471e-9293-f461d248b025', 'Glass and fiber', false, '05012949-e983-49ef-ac9e-6f4ca24372a5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2ff118c9-88f6-4923-a397-84c2ed1257a6', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'Which Australian television tycoon revolutionized modern cricket in 1977 by launching ''World Series Cricket'' with colored clothes, white balls, and day-night matches?', 'Kerry Packer signed the world''s best cricketers in 1977, transforming cricket into a televised spectacle with floodlit day-night games and colorful uniforms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a571c60-9033-4f0f-9220-f8e281c4ff7d', 'Kerry Packer', true, '2ff118c9-88f6-4923-a397-84c2ed1257a6');
