INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5abcb358-bcb5-4651-aca1-86dc86a0cdc9', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'Which country won the historic 1983 Cricket World Cup by defeating the mighty West Indies at Lord''s, transforming cricket into a national passion in India?', 'Kapil Dev''s ''Kapil''s Devils'' stunned the two-time champion West Indies at Lord''s on 25 June 1983, igniting modern Indian cricket mania.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24b5a16a-d0d0-4610-a4a6-a6006b885f6b', 'India (captained by Kapil Dev)', true, '5abcb358-bcb5-4651-aca1-86dc86a0cdc9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e8d1b30c-2e17-4543-a11f-59b084a082d3', 'England', false, '5abcb358-bcb5-4651-aca1-86dc86a0cdc9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7df11f8c-bdf8-413b-ae97-e9b1501a8e7e', 'Australia', false, '5abcb358-bcb5-4651-aca1-86dc86a0cdc9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05ef1612-88e5-45d8-858a-f6ac32050ee8', 'Pakistan', false, '5abcb358-bcb5-4651-aca1-86dc86a0cdc9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5fc9ad5a-3cce-4494-8c5c-66b93657532c', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'What is unique about the DURATION of a Test match in cricket compared to all other modern team sports?', 'Cricket is unique among modern sports: Test matches span 5 days (up to 30 hours of play) and can legitimately conclude in a draw.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('355c7c0f-cf2d-4c3d-9c6d-41b794a4295c', 'A Test match can last for FIVE FULL DAYS and can still end in a DRAW without a winner', true, '5fc9ad5a-3cce-4494-8c5c-66b93657532c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e243f36-dc1b-4aad-bfed-02492f833488', 'It lasts only for 90 minutes', false, '5fc9ad5a-3cce-4494-8c5c-66b93657532c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67037cc7-5aaf-4daf-9640-8a8972b9b15d', 'It is played over one hour', false, '5fc9ad5a-3cce-4494-8c5c-66b93657532c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ec455ed-84ea-4a5e-b468-ceb344c20c92', 'It never ends', false, '5fc9ad5a-3cce-4494-8c5c-66b93657532c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e654fbf8-b5c9-4f20-be14-818cb7b6d116', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Easy', 'What modern protective synthetic equipment was introduced to cricket only after the invention of vulcanized rubber in the 19th century?', 'Vulcanized rubber enabled the invention of padded batting gloves (1848) and protective leg-guard pads, followed by synthetic helmets.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d1b3034-59ea-48f6-88d5-a7fa8dec3461', 'Pads (Leg-guards) and Batting Gloves', true, 'e654fbf8-b5c9-4f20-be14-818cb7b6d116');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c70758f-d541-435b-8b95-1021f5fe5023', 'Wooden Wickets', false, 'e654fbf8-b5c9-4f20-be14-818cb7b6d116');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cbf80cb-1801-4d62-b7af-6821efc0230c', 'Leather Ball', false, 'e654fbf8-b5c9-4f20-be14-818cb7b6d116');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a915b8f-6fe2-4efe-b7bf-d781ee80adf6', 'Willow Bat', false, 'e654fbf8-b5c9-4f20-be14-818cb7b6d116');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('48c10b69-b7b6-46f2-b27b-5055672e4dbe', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'How did the introduction of pitching the ball through the air (instead of rolling it on the ground) in the 1760s transform cricket batting and bowling?', 'Airborne bowling introduced swing, seam, and deception in flight, prompting the invention of straight willow bats for precise defensive strokeplay.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39e68896-d888-4368-bf15-dc433cc0629a', 'Bowlers gained the ability to generate curved swing and spin in the air, forcing batsmen to replace curved hockey-style bats with straight, flat bats for timing and defense', true, '48c10b69-b7b6-46f2-b27b-5055672e4dbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1532854a-2c84-44fd-8262-1a6f5779b900', 'Batsmen started using baseball bats', false, '48c10b69-b7b6-46f2-b27b-5055672e4dbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f7c1dbb-d11b-41d9-a5f2-076f7564379a', 'Bowlers were forced to throw the ball like a stone', false, '48c10b69-b7b6-46f2-b27b-5055672e4dbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a79abb2b-3797-4c7b-ba35-9eee33bea115', 'The pitch was made round', false, '48c10b69-b7b6-46f2-b27b-5055672e4dbe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fee7b4a5-7be0-44c9-a4fc-71501a5bad2f', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'What was the social distinction between ''GENTLEMEN'' (Amateurs) and ''PLAYERS'' (Professionals) in historic English cricket?', 'Aristocratic class hierarchy: Gentlemen (unpaid amateur batsmen/captains) vs Players (hired working-class professional bowlers).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9025acf-45cc-4a07-999b-e774d6b992f1', 'Gentlemen were wealthy aristocratic aristocrats who played for leisure and honor without pay ; Players were working-class men paid wages to bowl and field', true, 'fee7b4a5-7be0-44c9-a4fc-71501a5bad2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b15b4da0-bad0-47db-9248-8b480c524252', 'Gentlemen were bowlers and Players were umpires', false, 'fee7b4a5-7be0-44c9-a4fc-71501a5bad2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3eb1cac9-2459-4c08-8c16-9249581e6494', 'Gentlemen played only in winter', false, 'fee7b4a5-7be0-44c9-a4fc-71501a5bad2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cea9bae8-cdbd-424c-97f2-8ce6c20e529d', 'There was no social distinction', false, 'fee7b4a5-7be0-44c9-a4fc-71501a5bad2f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13d34af1-c385-459c-a921-45d0b39ec214', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'Why does the shape and boundary size of cricket grounds vary so widely across the world (e.g. oval Melbourne vs round Chepauk), unlike football pitches?', 'Cricket''s pastoral origins on unfenced village greens created flexible boundary geometry while preserving fixed 22-yard pitch distances.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4041bfa-d94e-45a7-88c9-47da62d445fb', 'Cricket originated as a pre-industrial village green game where matches were played on open village commons without artificial boundary fences', true, '13d34af1-c385-459c-a921-45d0b39ec214');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78fda00d-7f48-4950-bd8d-f65c250ea56e', 'Because builders did not have tape measures', false, '13d34af1-c385-459c-a921-45d0b39ec214');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43e3cb87-dd35-40f6-9195-99e149843660', 'Because every country wanted a different shape', false, '13d34af1-c385-459c-a921-45d0b39ec214');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85bdfc71-34f6-4b5f-9105-cf2851f05264', 'Because round stadiums are cheaper', false, '13d34af1-c385-459c-a921-45d0b39ec214');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c579fce-e432-4c5e-a00a-32afc273a045', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'What was the famous ''Bombay Pentangular'' tournament played in colonial India based on?', 'The colonial Bombay tournament evolved from Triangular to Quadrangular to Pentangular, organized strictly along communal lines (opposed by Mahatma Gandhi).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc44bfcc-6876-4aaa-a5f6-a6f976143a27', 'Communal religious and ethnic teams: The Europeans, The Parsis, The Hindus, The Muslims, and The Rest', true, '9c579fce-e432-4c5e-a00a-32afc273a045');
