INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e7bf389-c4fe-4850-896f-0f1bd0ce78c9', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'How did the advent of Television and Satellite Broadcasting shift the global economic center of gravity of cricket from London to South Asia (India)?', 'Demographic and media revolution: South Asia''s colossal broadcast viewership made the subcontinental market the dominant financial engine of world cricket.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21a9bd7b-0262-4a33-b839-9c11a92dc9a9', 'South Asia possessed the largest television viewing audience and consumer marketplace in the cricket-playing world, generating massive advertising revenues that enriched the BCCI', true, '8e7bf389-c4fe-4850-896f-0f1bd0ce78c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1985b3f6-905c-4838-a9bb-7b295a5db8e2', 'Because India invented satellites', false, '8e7bf389-c4fe-4850-896f-0f1bd0ce78c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a620509-3e0f-4102-a4aa-d3e9aece451f', 'Because cricket was banned in England', false, '8e7bf389-c4fe-4850-896f-0f1bd0ce78c9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d346c5c5-9fcb-4567-8752-66c6deca862f', 'Because matches were played only in Delhi', false, '8e7bf389-c4fe-4850-896f-0f1bd0ce78c9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('37dd4cf1-e7c7-4a44-b732-1c2aa133aa43', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'Why was Palwankar Baloo, a legendary slow left-arm spinner of the Bombay Hindus team in the 1900s, a milestone figure in Indian social history?', 'Baloo Palwankar challenged untouchability through athletic brilliance, acclaimed by Dr. B.R. Ambedkar as a pioneer of Dalit social elevation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78a8e473-862f-497a-ae49-5ede8d1d1ecc', 'He was from the oppressed Dalit (Untouchable) community who broke caste barriers through his supreme cricketing genius, becoming India''s first great indigenous sporting hero', true, '37dd4cf1-e7c7-4a44-b732-1c2aa133aa43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c876be7f-260c-4cbe-948e-edbf9b576c1b', 'He was the first British governor', false, '37dd4cf1-e7c7-4a44-b732-1c2aa133aa43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('253ed4c6-c907-4d11-9463-6a24b7b536f5', 'He invented cricket shoes', false, '37dd4cf1-e7c7-4a44-b732-1c2aa133aa43');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20a64cb8-e48d-4044-ab9f-7e7bc6dcf19a', 'He was a royal prince', false, '37dd4cf1-e7c7-4a44-b732-1c2aa133aa43');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('03d326df-32d1-4be8-a5b8-801176755c69', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'What is the meaning of the English idiom ''It''s not cricket'' in conversational usage?', 'The Victorian idiom ''It''s not cricket'' signifies any conduct that violates the spirit of fair play, honor, and sportsmanship.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2221f1b6-01de-4f54-885b-41fcf0cb8813', 'It is unfair, dishonorable, or unsporting behavior', true, '03d326df-32d1-4be8-a5b8-801176755c69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27da5d25-4bc8-4ced-b5d9-83c13e1f2f4a', 'It is not a baseball match', false, '03d326df-32d1-4be8-a5b8-801176755c69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b43171b8-285e-4f9b-a09e-004689d47089', 'The weather is rainy', false, '03d326df-32d1-4be8-a5b8-801176755c69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb63b976-7af0-43ad-9484-af3686326afe', 'The ball is lost', false, '03d326df-32d1-4be8-a5b8-801176755c69');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e350ec9b-4693-450d-a9bd-266211191dac', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'What is the meaning of ''Decolonization'' in the context of international cricket history?', 'Decolonization transformed cricket from an instrument of imperial cultural hegemony into a vibrant arena of post-colonial national pride.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca4058aa-24d3-42b9-920b-f6d22a510080', 'The decline of British imperial administrative dominance over the game and the rise of formerly colonized nations (India, Pakistan, West Indies, Sri Lanka) as sovereign global cricket superpowers', true, 'e350ec9b-4693-450d-a9bd-266211191dac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4871102f-7c02-47e0-920e-fcc25e6a2c9b', 'Banning wooden bats', false, 'e350ec9b-4693-450d-a9bd-266211191dac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1c27350-938e-4ba1-87c0-cb682bd68e90', 'Changing the rules every year', false, 'e350ec9b-4693-450d-a9bd-266211191dac');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d78a406-9952-4a64-9f48-4c4a5f22b259', 'Playing matches without umpires', false, 'e350ec9b-4693-450d-a9bd-266211191dac');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('db769673-af5f-4039-bcec-e639e2aceaa2', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'What is the SYNONYM of ''Idiosyncrasy'' as applied to cricket''s unique rules?', '''Idiosyncrasy'' denotes an eccentric, highly distinctive individual peculiarity.', NOW()) ON CONFLICT DO NOTHING;
