INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd3da426-e039-4aff-a3b0-5c1131f0e780', 'Boring rule', false, 'db769673-af5f-4039-bcec-e639e2aceaa2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b299de1e-33de-41cd-84d7-9a7161c2077a', 'Mistake', false, 'db769673-af5f-4039-bcec-e639e2aceaa2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecc7c22b-e7ad-4f48-9c45-56afd5e01589', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'What is the ANTONYM of ''Amateur'' in sports terminology?', 'The antonym of ''amateur'' (playing unpaid for pleasure) is ''professional'' (earning a livelihood from the sport).', NOW()) ON CONFLICT DO NOTHING;
