INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('513afe3f-eb81-46f9-a677-9ef1b23cc824', '''The first Indian cricket club was established in Bombay by the Parsis.''', true, '234d5348-22ea-4ae9-b12c-c51e557c2d0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ac4ec60-2db6-4792-adf1-5dbe11ab6d9f', '''The first Indian cricket club established the Parsis in Bombay.''', false, '234d5348-22ea-4ae9-b12c-c51e557c2d0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f4bac59-720a-40a9-8697-034563652421', '''In Bombay had been established the first Indian cricket club.''', false, '234d5348-22ea-4ae9-b12c-c51e557c2d0d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83e5f682-e06d-44b2-bd84-826d88d40b1f', '''The Parsis were established by the first cricket club.''', false, '234d5348-22ea-4ae9-b12c-c51e557c2d0d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('68ffb21b-2a8c-4cad-8897-66c56f45a04d', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'Why did English colonists believe that cricket was a civilizing sport for colonized peoples?', 'British imperial ideology promoted cricket as a moralizing exercise in Victorian discipline, stoicism, and gentlemanly etiquette.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e29fc274-4c9b-44f9-bb4e-e63c0632a550', 'They believed it instilled Victorian virtues of fair play, imperial discipline, obedience to codified rules, and emotional self-control', true, '68ffb21b-2a8c-4cad-8897-66c56f45a04d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4bce805-f6e7-4c4e-812a-8d04f71818bf', 'Because cricket was easy to learn in a day', false, '68ffb21b-2a8c-4cad-8897-66c56f45a04d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d23f4e51-2e86-4dfa-9573-971fae9a7061', 'Because they wanted to sell bats', false, '68ffb21b-2a8c-4cad-8897-66c56f45a04d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65efb7db-0472-42e8-a02b-08a300d0a5b1', 'Because cricket had no rules', false, '68ffb21b-2a8c-4cad-8897-66c56f45a04d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5091f8f8-4c7d-4227-b20b-9fdf19d39207', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Medium', 'What technological revolution allowed millions of fans across small Indian towns and villages to watch international cricket live simultaneously?', 'Satellite television telecasts democraticized cricket viewing across rural and urban India, creating a shared national collective ritual.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b0c2912-82d9-46ce-8146-338eeb744f87', 'Satellite Television Broadcasting (Doordarshan and private satellite channels)', true, '5091f8f8-4c7d-4227-b20b-9fdf19d39207');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('356f7638-32ec-458a-8387-58b7f5249e39', 'Printed newspapers only', false, '5091f8f8-4c7d-4227-b20b-9fdf19d39207');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b13f32f1-d43f-4d49-bb00-7b57905015ba', 'Radio commentary in Morse code', false, '5091f8f8-4c7d-4227-b20b-9fdf19d39207');
