INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe36298c-a984-4dba-8af6-5dba631833f1', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '2d68a0cc-f54f-4f76-8630-dec4f7c48d78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f71cef58-21d6-4a9e-b486-7e44982263d1', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '2d68a0cc-f54f-4f76-8630-dec4f7c48d78');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38f90a1a-023a-4ec6-aebe-c5025b4c0da5', '(A) is true, but (R) is false.', false, '2d68a0cc-f54f-4f76-8630-dec4f7c48d78');
