INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d8d96c8-e010-480b-93e7-42e5102f1bf2', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Hard', 'Spot the IMPOSTER in the following historical timeline of cricket evolution:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d767619-fd86-442e-a589-115358a5ffc7', 'Event 1', false, '9d8d96c8-e010-480b-93e7-42e5102f1bf2');
