INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21d67387-b9f5-4ed3-9a00-a7d3d86edfe5', 'Event 3', false, '9d8d96c8-e010-480b-93e7-42e5102f1bf2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('704e1300-a350-4471-9510-f39c6a11b2eb', 'Event 4 (Hawk-Eye digital ball-tracking computer systems were developed in the 21st CENTURY [circa 2001], not the year 1500)', true, '9d8d96c8-e010-480b-93e7-42e5102f1bf2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('12267619-6e59-4557-8f40-82fc3c7f49df', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Hard', 'Analyze the social sociology of early cricket in colonial India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a5fdc2b-9431-4b06-844a-8bdea9c35f16', 'The Parsis were a wealthy, westernized commercial merchant community in Bombay with close business ties to the British East India Company, embracing English sports and culture early', true, '12267619-6e59-4557-8f40-82fc3c7f49df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('546bc287-9376-45ff-9621-23a7181cfe93', 'Because only Parsis were allowed to buy bats', false, '12267619-6e59-4557-8f40-82fc3c7f49df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83529419-706f-4616-bffd-c2a5dfe49d32', 'Because cricket was invented in Persia', false, '12267619-6e59-4557-8f40-82fc3c7f49df');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6f193e0-5984-40a0-8e4c-8611df73f63c', 'Because Parsis were professional athletes in Britain', false, '12267619-6e59-4557-8f40-82fc3c7f49df');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6bb18266-30b0-4404-bb49-76fe629bab5c', 'Class 7', 'English', 'Chapter 10: The Story of Cricket', 'Hard', 'Match Column I (Cricket Innovations / Historical Milestones) with Column II (Historical Causes & Consequences):
(a) Airborne Bowling (1760s)    -> (i) Prompted the invention of straight, flat willow bats
(b) Kerry Packer''s WSC (1977)    -> (ii) Inaugurated colored clothing, white balls, and day-night telecasts
(c) 1983 World Cup Victory       -> (iii) Catalyzed India''s commercial cricket boom and mass fanaticism
(d) Subcontinental TV Market     -> (iv) Shifted the global financial headquarters of cricket to South Asia', 'Airborne bowling = straight bats; Packer = colored kits & night games; 1983 victory = mass mania; TV market = shift to South Asia.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bf1d36b-c1be-422a-bb67-6f1c5fc68ea9', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '6bb18266-30b0-4404-bb49-76fe629bab5c');
