INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b581926-879f-41dd-ab22-e75691a44f61', 'John von Neumann', false, '585738cf-ebeb-432d-a29f-9135d8e376f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ace117ce-1797-4d65-999b-435263a610ca', 'Steve Jobs', false, '585738cf-ebeb-432d-a29f-9135d8e376f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e50e698-fbb9-4297-9c3e-b2bfc335bd44', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'Who was the English mathematician celebrated as the WORLD''S FIRST COMPUTER PROGRAMMER for publishing the first algorithm intended for Babbage''s Analytical Engine?', 'Ada Lovelace wrote the world''s first computer algorithm in 1843, foreseeing that computers could manipulate symbols and music.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4151f9f-c797-4d2f-be38-450bd1abf170', 'Ada Lovelace (Countess of Lovelace)', true, '6e50e698-fbb9-4297-9c3e-b2bfc335bd44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c90985b-cde5-4576-9fe9-a3cbead146af', 'Grace Hopper', false, '6e50e698-fbb9-4297-9c3e-b2bfc335bd44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dea99a5f-7f77-456e-8bd2-de58cb891ba9', 'Marie Curie', false, '6e50e698-fbb9-4297-9c3e-b2bfc335bd44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af86bac9-d15b-43ab-b93f-e519c8c00ba3', 'Katherine Johnson', false, '6e50e698-fbb9-4297-9c3e-b2bfc335bd44');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('459ce133-f44a-4183-822c-5fadde26b33a', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'Who is celebrated as the ''Father of Modern Computer Science and Artificial Intelligence'' for inventing the theoretical Turing Machine and cracking the Nazi Enigma cipher during WWII?', 'Alan Turing formalized algorithmic computation (Turing machine), broke the naval Enigma code at Bletchley Park, and proposed the Turing Test.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c537a192-11dc-44a4-845e-20a464917016', 'Alan Turing', true, '459ce133-f44a-4183-822c-5fadde26b33a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef99e2ad-fa6d-4b65-875d-bc556aefdb16', 'Tim Berners-Lee', false, '459ce133-f44a-4183-822c-5fadde26b33a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cab7b0a-5e7a-40cd-b9e1-a1d1ddd9b09d', 'Claude Shannon', false, '459ce133-f44a-4183-822c-5fadde26b33a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5658ee7d-e1f8-47c0-b964-e15f2e4374d3', 'Bill Gates', false, '459ce133-f44a-4183-822c-5fadde26b33a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87a6d3c6-1748-40ad-a6d5-9c9dc30e1401', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'Who invented the WORLD WIDE WEB (WWW) at CERN in 1989, designing HTML, HTTP, and the first web browser?', 'Sir Tim Berners-Lee invented the World Wide Web at CERN in 1989, releasing the technology royalty-free to the entire world.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d9a6ee0-4b4d-484c-a523-3c2d7e17cfd2', 'Sir Tim Berners-Lee', true, '87a6d3c6-1748-40ad-a6d5-9c9dc30e1401');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3be0ac28-547d-44f8-9113-be26a382ae02', 'Vint Cerf', false, '87a6d3c6-1748-40ad-a6d5-9c9dc30e1401');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0676564d-2974-48c7-8ff9-4ef1eccde2f6', 'Marc Andreessen', false, '87a6d3c6-1748-40ad-a6d5-9c9dc30e1401');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae20c518-e666-4ed6-a79f-b98ba007775c', 'Linus Torvalds', false, '87a6d3c6-1748-40ad-a6d5-9c9dc30e1401');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0a3011b2-a3da-418b-8027-55adb7cabc1d', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'Which Scottish physician-bacteriologist accidentally discovered the world''s first wonder antibiotic—PENICILLIN—from Penicillium mold in 1928?', 'Alexander Fleming discovered penicillin in 1928, revolutionizing modern medicine and saving hundreds of millions of lives from bacterial infections.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6329f343-68f1-4bba-bffa-b8401a2f37ec', 'Sir Alexander Fleming', true, '0a3011b2-a3da-418b-8027-55adb7cabc1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fd1be18-9cb6-4d3e-8e7f-1fd2c0840268', 'Louis Pasteur', false, '0a3011b2-a3da-418b-8027-55adb7cabc1d');
