INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3eb198a5-8d89-4373-871c-a62670de6f7f', 'Edward Jenner', false, '0a3011b2-a3da-418b-8027-55adb7cabc1d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('25fb2a91-2166-43ad-94eb-022711c3191a', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'Who developed the world''s FIRST VACCINE (for Smallpox) in 1796 using cowpox fluid, pioneering the field of Immunology?', 'Edward Jenner''s 1796 cowpox inoculation created the smallpox vaccine, leading to the global eradication of smallpox by the WHO in 1980.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2af065d8-1dc1-460a-91a3-9535776c3666', 'Edward Jenner', true, '25fb2a91-2166-43ad-94eb-022711c3191a');
