INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8204fafd-2152-4f08-9ef1-1aa89c5d888f', 'Louis Pasteur', false, '25fb2a91-2166-43ad-94eb-022711c3191a');
