INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04625aa0-16b7-45d1-9c37-9bbbd62f6319', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'Which two scientists discovered the 3D DOUBLE HELIX molecular structure of DNA in 1953 (building on Rosalind Franklin''s X-ray crystallography)?', 'Watson and Crick deduced the antiparallel double-helix structure of DNA in 1953, unlocking the genetic code of all biological life.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d088085-16b2-4738-a7e0-fcefee8612b2', 'James Watson and Francis Crick', true, '04625aa0-16b7-45d1-9c37-9bbbd62f6319');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62ff957e-6c9a-41db-ac79-2648dc4f3b0f', 'Gregor Mendel and Charles Darwin', false, '04625aa0-16b7-45d1-9c37-9bbbd62f6319');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9cd5747-79dd-4640-91b3-bfd46903f896', 'Louis Pasteur and Robert Hooke', false, '04625aa0-16b7-45d1-9c37-9bbbd62f6319');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50a010e7-8ddd-4a8c-95bb-ad8155e69eb8', 'Albert Einstein and Max Planck', false, '04625aa0-16b7-45d1-9c37-9bbbd62f6319');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('01373a33-ae58-46ff-8d16-637c513f8adf', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'What is Albert Einstein''s world-famous mass-energy equivalence equation derived from his Special Theory of Relativity (1905)?', 'E = mc² establishes that mass and energy are interchangeable, forming the foundational principle of nuclear energy and astrophysics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be1980d9-a38a-45ec-9568-478806a0c2a9', 'E = mc² (where E = Energy, m = mass, c = speed of light)', true, '01373a33-ae58-46ff-8d16-637c513f8adf');
