INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0f0d1e98-51d5-4069-9089-0c2fe2c3f275', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'Who created the FIRST PERIODIC TABLE of chemical elements in 1869, arranging elements by atomic mass and predicting undiscovered elements?', 'Russian chemist Dmitri Mendeleev organized elements into the periodic table, famously leaving empty gaps for then-unknown elements like Gallium and Germanium.', NOW()) ON CONFLICT DO NOTHING;
