INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe69bd03-f128-403b-bbb7-f268ac27ab15', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'What was the name of INDIA''S FIRST INDIGENOUS SUPERCOMPUTER, developed by the Centre for Development of Advanced Computing (C-DAC) in Pune in 1991 led by Dr. Vijay Bhatkar?', 'PARAM 8000 (1 Gigaflop) was India''s first supercomputer, designed and built indigenously by C-DAC in 1991.', NOW()) ON CONFLICT DO NOTHING;
