INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('507b6497-7a11-45ed-83b3-4aed17e3938f', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Easy', 'What does the technological abbreviation ''AI'' stand for in modern computer science?', 'Artificial Intelligence (AI) is the simulation of human intelligence processes by computer algorithms and machine learning neural networks.', NOW()) ON CONFLICT DO NOTHING;
