INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e40e6399-62d8-4c12-a8fd-3c935784949c', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Medium', 'What is ''Moore''s Law'', articulated by Intel co-founder Gordon Moore in 1965?', 'Moore''s Law accurately guided semiconductor miniaturization and exponential computational power scaling for over five decades.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2aafaa50-8dde-4a1e-8a2c-03866797ee7e', 'The empirical observation that the number of transistors on a microchip DOUBLES approximately every two years, while the cost of computers is halved', true, 'e40e6399-62d8-4c12-a8fd-3c935784949c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8eb2af7c-03b6-4f51-b4ea-a5487343a00b', 'That computers will stop working after 10 years', false, 'e40e6399-62d8-4c12-a8fd-3c935784949c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d056114-0465-41c0-8da8-fce6c2890a47', 'That software will replace all hardware', false, 'e40e6399-62d8-4c12-a8fd-3c935784949c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a7b4052-4aad-44b4-bf51-900b20d7b297', 'That electricity speed doubles every year', false, 'e40e6399-62d8-4c12-a8fd-3c935784949c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6c23ebc2-29ad-4edf-9de9-274da01017f9', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Medium', 'What fundamental transmission protocols developed by Vint Cerf and Bob Kahn in the 1970s form the technical backbone of the global INTERNET?', 'TCP/IP provides end-to-end packet routing and reassembly, establishing the foundational architecture of the global internet.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('654f5b96-1a2f-4e1d-baa4-b2ee7436dfc0', 'TCP/IP (Transmission Control Protocol / Internet Protocol)', true, '6c23ebc2-29ad-4edf-9de9-274da01017f9');
