INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c500884c-84ca-4f89-9f26-3befb960b1db', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Medium', 'What revolutionary technology powers ''Quantum Computers'', allowing them to perform complex calculations exponentially faster than classical supercomputers?', 'Quantum computers harness quantum mechanics (qubit superposition and entanglement) to solve complex optimization and cryptographic problems exponentially fast.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5334a5a7-2643-4f50-94ee-44a7f723668d', 'Quantum Qubits utilizing Superposition and Entanglement (operating simultaneously in 0 and 1 states)', true, 'c500884c-84ca-4f89-9f26-3befb960b1db');
