INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('167bd32c-0c7f-4677-a5fc-334852fe1e35', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Medium', 'What is ''Cloud Computing''?', 'Cloud computing (AWS, Google Cloud, Microsoft Azure) provides elastic, scalable on-demand compute and storage infrastructure over the internet.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbd8ae31-c7f2-4e1b-a497-3ff55406e0b4', 'The on-demand delivery of computing services (servers, storage, databases, networking, software) over the internet (''the cloud'') with pay-as-you-go pricing', true, '167bd32c-0c7f-4677-a5fc-334852fe1e35');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e72e47a6-9e6b-4465-833d-4fe94671381e', 'Computing during rainy weather', false, '167bd32c-0c7f-4677-a5fc-334852fe1e35');
