INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b827361b-036a-4fc2-8435-6d244cfc298f', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Medium', 'What is ''Blockchain'' technology, first implemented in 2008 by Satoshi Nakamoto for Bitcoin?', 'Blockchain provides tamper-proof, decentralized consensus verification for digital assets, smart contracts, and supply chain tracking.', NOW()) ON CONFLICT DO NOTHING;
