INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2c5c4fa0-e608-4c84-96b3-6f4da58cf235', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Medium', 'Which Indian scientist and polymath pioneered wireless radio microwave communications in 1895 and invented the ''Crescograph'' to measure plant growth?', 'J.C. Bose was a visionary pioneer of millimeter-wave radio optics, semiconductor crystal detectors, and plant biophysics.', NOW()) ON CONFLICT DO NOTHING;
