INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94a1ccce-9273-4579-a1b5-f2d1ff88100b', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Medium', 'For what groundbreaking discovery in physics was Sir C.V. Raman awarded the Nobel Prize in Physics in 1930, celebrated annually on February 28 as NATIONAL SCIENCE DAY in India?', 'The Raman Effect demonstrates quantum shifts in photon energy during light scattering, now used globally in non-destructive Raman spectroscopy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f9c1f8d-b62c-480d-9ef9-047dbc94e485', 'The ''Raman Effect'' (inelastic scattering of light photons when traveling through a transparent medium)', true, '94a1ccce-9273-4579-a1b5-f2d1ff88100b');
