INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b02a9b7-9f47-458b-b8ef-2905e2af09b3', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Medium', 'What historic achievement was accomplished by ISRO''s CHANDRAYAAN-3 mission on August 23, 2023?', 'Chandrayaan-3''s Vikram lander and Pragyan rover achieved a historic soft landing at Shiv Shakti Point near the Moon''s South Pole on 23 August 2023.', NOW()) ON CONFLICT DO NOTHING;
