INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('301bda87-428e-4257-ac84-8d8f2393eb2d', 'First manned mission to Mars', false, '3b02a9b7-9f47-458b-b8ef-2905e2af09b3');
