INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d10e92d8-2499-4669-af1d-07328a409b1c', 'An international 13-year scientific project that successfully mapped and sequenced all the 3 billion chemical base pairs of human DNA', true, '8431487d-efe5-4bb8-8357-7013a37590df');
