INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f53a4e34-94a0-4b9a-9ac6-b3abfdc91ce7', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Medium', 'What is ''CRISPR-Cas9'' gene editing technology discovered by Emmanuelle Charpentier and Jennifer Doudna (Nobel Prize in Chemistry 2020)?', 'CRISPR-Cas9 enables precise targeted genetic editing in living cells, transforming genetic therapy, oncology, and crop biotechnology.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ccef360b-f5ed-4cdd-a40d-33e0cca6b8ec', 'A revolutionary molecular ''scissors'' tool that allows scientists to edit, insert, or delete specific sections of DNA sequences with pinpoint precision', true, 'f53a4e34-94a0-4b9a-9ac6-b3abfdc91ce7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13daec11-4054-4940-b464-8d78908c86a9', 'A microscope that magnifies stars', false, 'f53a4e34-94a0-4b9a-9ac6-b3abfdc91ce7');
