INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b77dc3e2-07e2-4cdb-9332-ff3a6209b81a', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Medium', 'What is the primary semiconductor chemical element used to manufacture modern computer processor microchips and solar cells?', 'Silicon is the premier semiconductor element whose electrical conductivity can be precisely modulated by doping, powering all microelectronics.', NOW()) ON CONFLICT DO NOTHING;
