INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4953b703-eea4-422f-9aa7-b2f42ddf6b10', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Medium', 'What is ''Unified Payments Interface'' (UPI) developed by the National Payments Corporation of India (NPCI) in 2016?', 'UPI is a global fintech marvel, processing over 13 billion instant digital transactions per month across millions of small merchants.', NOW()) ON CONFLICT DO NOTHING;
