INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c213edf-8e8a-4d8e-a304-7598114db8a6', 'A credit card company', false, '4953b703-eea4-422f-9aa7-b2f42ddf6b10');
