INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('12a19538-69a1-487b-98c1-056b95f4c28b', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Medium', 'What is ''Cybersecurity'' in the digital era?', 'Cybersecurity deploys cryptography, firewalls, threat intelligence, and zero-trust architectures to defend digital infrastructure from cyber warfare and data breaches.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02d1a942-66c8-4b95-8e92-d268bc0a95da', 'The practice of protecting internet-connected systems (hardware, software, data) from malicious digital attacks, unauthorized access, ransomware, and identity theft', true, '12a19538-69a1-487b-98c1-056b95f4c28b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eaaae6d2-e175-4d61-8b3e-c98b0644d833', 'Locking computer screens with padlocks', false, '12a19538-69a1-487b-98c1-056b95f4c28b');
