INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('248a8a1a-a953-4410-9d53-887d60039916', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Medium', 'What is the ''James Webb Space Telescope'' (JWST) launched into space by NASA, ESA, and CSA in December 2021?', 'JWST uses a 6.5m beryllium-gold mirror at Sun-Earth L2, peering over 13.5 billion years into cosmic history in high-resolution infrared.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b9e067c-d6dc-478d-8088-04c9d8d546ed', 'The largest and most powerful infrared space telescope ever built, stationed at Lagrange Point 2 (L2) to observe the earliest stars and galaxies formed after the Big Bang', true, '248a8a1a-a953-4410-9d53-887d60039916');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('788025b4-bb8e-473c-8c0d-8be0e6f788ca', 'A radar station on Earth', false, '248a8a1a-a953-4410-9d53-887d60039916');
