INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('81ea8a1c-1fc2-4b16-ba97-6a0d23566162', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Hard', 'Analyze the operational mechanism of ''Large Language Models'' (LLMs) and Generative AI (like Transformer neural networks):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce6c6a00-89e3-45cd-b973-4733bb9305d3', 'By using deep multi-head attention neural networks trained on vast text corpora to predict the statistically most probable next word (token) in context', true, '81ea8a1c-1fc2-4b16-ba97-6a0d23566162');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78524682-1f09-4c1e-9c4e-22eb11d29621', 'By searching a dictionary and printing random words', false, '81ea8a1c-1fc2-4b16-ba97-6a0d23566162');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7230563c-655e-4370-b752-cdea178c2815', 'By copying sentences from encyclopedia books verbatim', false, '81ea8a1c-1fc2-4b16-ba97-6a0d23566162');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3db958b-6284-4808-8a9b-7b4568f8f657', 'By translating speech into Morse code', false, '81ea8a1c-1fc2-4b16-ba97-6a0d23566162');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c1b567e-42cc-4cd0-ab75-07d08e56e592', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Hard', 'Match Column I (Digital & Scientific Breakthroughs) with Column II (Pioneering Creators / Institutions):
(a) World Wide Web (1989)       -> (i) Tim Berners-Lee (CERN)
(b) Relational Database (RDBMS) -> (ii) Edgar F. Codd (IBM)
(c) CRISPR-Cas9 Gene Editing   -> (iii) Jennifer Doudna & Emmanuelle Charpentier
(d) Chandrayaan-3 Moon Landing  -> (iv) ISRO (India)', 'WWW = Berners-Lee; RDBMS = Codd; CRISPR = Doudna/Charpentier; Moon landing = ISRO.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49bce0eb-a997-4cb3-bc02-e1f7ab2014c1', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '9c1b567e-42cc-4cd0-ab75-07d08e56e592');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5155bedb-970c-44c7-83d7-275792d4a566', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '9c1b567e-42cc-4cd0-ab75-07d08e56e592');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b3ea15b-ffc7-4d13-885e-692bec3fff78', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '9c1b567e-42cc-4cd0-ab75-07d08e56e592');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e011078-2c39-49d2-aa13-cd3fd26519bf', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '9c1b567e-42cc-4cd0-ab75-07d08e56e592');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3307a030-d6cf-4dc0-ad4c-aee917fbb90f', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Hard', 'Read the statements regarding India''s Digital Public Infrastructure (DPI - ''India Stack''):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f02aeb2-a9ec-4803-924a-3d25a1335352', 'Statements 1 and 2 only', true, '3307a030-d6cf-4dc0-ad4c-aee917fbb90f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f558a790-849d-40f3-ac34-5cca78293398', 'Statements 2 and 3 only', false, '3307a030-d6cf-4dc0-ad4c-aee917fbb90f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f872ab8-dff3-45be-aef0-379f879f9e62', 'Statements 1 and 3 only', false, '3307a030-d6cf-4dc0-ad4c-aee917fbb90f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a31005db-5e55-42c5-a8e1-bd26337b09f2', 'All Statements 1, 2, and 3', false, '3307a030-d6cf-4dc0-ad4c-aee917fbb90f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('235c8611-2e6f-4c19-a2a8-828cc6637686', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Hard', 'What is the ''Higgs Boson'' (often colloquially called the ''God Particle'') discovered at CERN''s Large Hadron Collider in 2012?', 'The Higgs field mechanism (predicted by Peter Higgs and Satyendra Nath Bose''s quantum statistics) generates mass via spontaneous electroweak symmetry breaking.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('638bbb95-6057-4fc0-9403-e991ce3339fd', 'The fundamental quantum particle associated with the Higgs field, which imparts mass to all fundamental elementary particles (quarks, leptons, W/Z bosons)', true, '235c8611-2e6f-4c19-a2a8-828cc6637686');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed61e5a0-6047-4804-82fc-100a03e785e2', 'A particle of pure light', false, '235c8611-2e6f-4c19-a2a8-828cc6637686');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bd2b3f9-59dc-4656-9c2d-830a0fddcf86', 'A particle found only on the Moon', false, '235c8611-2e6f-4c19-a2a8-828cc6637686');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('253da036-223f-4bf3-91e1-f039565df88a', 'A chemical used to make computer screens', false, '235c8611-2e6f-4c19-a2a8-828cc6637686');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('20d3aeb3-f1a4-4031-a364-cfbb60200a32', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Hard', 'How does Public-Key Asymmetric Cryptography (RSA algorithm) secure worldwide online banking and encrypted communications?', 'RSA encryption relies on one-way trapdoor mathematical functions (prime factorization intractability) to secure digital signatures and SSL/TLS internet transactions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87ebea22-aa70-4d62-a7e0-00b8271f2c62', 'It uses a mathematically paired Public Key (for encryption) and Private Key (for decryption) based on the computational difficulty of factoring giant prime numbers', true, '20d3aeb3-f1a4-4031-a364-cfbb60200a32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea7a730b-f17a-4ca9-b6df-2c55db8b6c32', 'By storing passwords in paper envelopes', false, '20d3aeb3-f1a4-4031-a364-cfbb60200a32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbbbcf8b-0d04-4575-9028-141b029cb5ac', 'By turning text into random sounds', false, '20d3aeb3-f1a4-4031-a364-cfbb60200a32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('906b1532-f601-4bb6-bdce-133affc3f045', 'By changing computer clock times', false, '20d3aeb3-f1a4-4031-a364-cfbb60200a32');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c193a5ee-860a-4080-9113-f7fdc697979b', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Hard', 'Consider four milestone technological systems:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15728a7d-d4db-4cab-abd3-083095f9d283', 'They are all direct practical engineering applications derived from 20th-century breakthroughs in Quantum Mechanics and Solid-State Physics', true, 'c193a5ee-860a-4080-9113-f7fdc697979b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ef76447-2958-486b-a49f-c7226ce8f292', 'They were all invented in ancient Rome', false, 'c193a5ee-860a-4080-9113-f7fdc697979b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5cd0deb5-0c24-486f-b573-160fee7c7ee7', 'They all operate without any electricity', false, 'c193a5ee-860a-4080-9113-f7fdc697979b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('326c41c0-b70c-478c-80cb-be1fdf05fe64', 'They are used only in outer space', false, 'c193a5ee-860a-4080-9113-f7fdc697979b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('493bcd0e-3236-4bfb-95a8-73119828944c', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Hard', 'What is the ''Fermi Paradox'' in modern astronomy and astrophysics?', 'Enrico Fermi''s famous paradox highlights the tension between the billions of habitable stars in the Milky Way and the deafening silence of the cosmos.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94f77cb9-fd7f-4ac8-a0a9-a54a2995e91a', 'The glaring contradiction between the high mathematical probability of extraterrestrial intelligent civilizations in our vast galaxy and the complete absence of observational contact or evidence (''Where is everybody?'')', true, '493bcd0e-3236-4bfb-95a8-73119828944c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e05d2d57-0038-41db-9fd0-125e1dd880de', 'The paradox that stars are hotter than planets', false, '493bcd0e-3236-4bfb-95a8-73119828944c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6033016e-5753-4ecd-80ab-e0b22a367ad5', 'The problem of calculating the Moon''s weight', false, '493bcd0e-3236-4bfb-95a8-73119828944c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('30689d0a-61ee-44da-9ea2-fb591d3c9b28', 'The reason why the Sun rises in the east', false, '493bcd0e-3236-4bfb-95a8-73119828944c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2dfe2ba9-b202-4ef9-ac4b-d6966f45fd21', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Hard', 'Why was the 2019 Nobel Prize in Chemistry awarded to John Goodenough, Stanley Whittingham, and Akira Yoshino for developing the LITHIUM-ION BATTERY?', 'Lithium-ion intercalation electrochemistry catalyzed the mobile communication era and the renewable energy green transition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e683840d-ec3e-4a9b-adcc-685514e1468e', 'Lithium-ion batteries created a lightweight, compact, rechargeable energy storage revolution that untethered portable electronics (smartphones, laptops) and enabled electric vehicles (EVs)', true, '2dfe2ba9-b202-4ef9-ac4b-d6966f45fd21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('466ce02a-52b2-48f7-b0a8-64464897b2c7', 'Because they invented atomic bombs', false, '2dfe2ba9-b202-4ef9-ac4b-d6966f45fd21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dae4ed33-90e2-4fbb-ac93-bf205961618f', 'Because they discovered water on Mars', false, '2dfe2ba9-b202-4ef9-ac4b-d6966f45fd21');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0521e804-8ee6-4c10-8dfa-d8ef89910e8a', 'Because they built the first airplane', false, '2dfe2ba9-b202-4ef9-ac4b-d6966f45fd21');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5ca97af6-2dd5-426b-85e3-1ccc3246d886', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Hard', 'What is the mission of ISRO''s ''Aditya-L1'' spacecraft successfully launched in September 2023?', 'Aditya-L1 continuously monitors solar coronal heating, solar wind dynamics, and space weather without eclipse interruptions from Sun-Earth L1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25111366-aa19-4cad-a187-8e3ebe8471d6', 'India''s first dedicated space-based solar observatory, placed in a halo orbit around Lagrangian point L1 (~1.5 million km from Earth) to study solar flares and coronal mass ejections', true, '5ca97af6-2dd5-426b-85e3-1ccc3246d886');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c0cc308-10e8-4f18-84dc-a242b674679f', 'To land on Mars', false, '5ca97af6-2dd5-426b-85e3-1ccc3246d886');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9dee69f-5cb2-4615-9b28-6b9c7fc0be63', 'To drill deep inside the Earth''s core', false, '5ca97af6-2dd5-426b-85e3-1ccc3246d886');
