INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7726c041-1cda-43f2-bd77-bc6415890ef5', 'Class 7', 'GK', 'Chapter 10: Science, Inventions, Information Technology & Digital Era', 'Hard', 'What master vision of human progress and ethical responsibility is articulated in Chapter 10 of General Knowledge?', 'Chapter 10 synthesizes the arc of modern scientific discoveries, computational revolutions, space exploration, and humanist ethical stewardship.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08acc723-97b3-4c0f-a3c4-eccb27be60ea', 'Scientific curiosity and digital technological power must be harnessed ethically and inclusively to alleviate human suffering, bridge economic divides, protect ecological balance, and propel humanity toward a sustainable, enlightened future', true, '7726c041-1cda-43f2-bd77-bc6415890ef5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e780ade7-b3f4-47a4-92f0-f33b134eb121', 'That technology should be used only for war', false, '7726c041-1cda-43f2-bd77-bc6415890ef5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed635d09-be8f-46fd-a07e-be28a4292b6d', 'That scientific discoveries should be kept secret forever', false, '7726c041-1cda-43f2-bd77-bc6415890ef5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea26c4a5-3edf-403e-a1ab-f2133edb2f02', 'That computers will make human knowledge obsolete', false, '7726c041-1cda-43f2-bd77-bc6415890ef5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('752132c0-3732-4e56-93f0-d54f01052114', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Easy', 'Which Mughal Emperor''s long, exhausting 25-year military campaigns in the Deccan (1679–1707) severely depleted the financial and military resources of the Mughal Empire?', 'Aurangzeb''s protracted Deccan wars exhausted the imperial treasury, ruined Mughal armies, and left northern administration vulnerable to collapse.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9bb76556-6c02-4737-9242-adb2245e399f', 'Emperor Aurangzeb', true, '752132c0-3732-4e56-93f0-d54f01052114');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81397751-5846-47a9-8f48-e5775738d45e', 'Emperor Akbar', false, '752132c0-3732-4e56-93f0-d54f01052114');
