INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f50a7d62-cbb9-4ff1-a504-e9752c9354c4', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Easy', 'Which ruler of Iran invaded and plundered the Mughal capital of Delhi in 1739, carrying away the legendary Peacock Throne (Takht-i-Taus) and the Koh-i-Noor Diamond?', 'Nadir Shah of Persia sacked Delhi in 1739, looting an estimated 70 crore rupees in bullion, jewels, the Koh-i-Noor, and Shah Jahan''s Peacock Throne.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac26825b-45c6-467f-8085-0905fa27c17d', 'Nadir Shah', true, 'f50a7d62-cbb9-4ff1-a504-e9752c9354c4');
