INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('881a96aa-631c-4c40-8b4d-bf56f2104bad', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Easy', 'Which Afghan ruler invaded northern India FIVE TIMES between 1748 and 1761, culminating in the 3rd Battle of Panipat?', 'Ahmad Shah Abdali of Afghanistan invaded Punjab and Delhi repeatedly between 1748 and 1761, shattering Mughal authority.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9af803ba-8c6a-459c-81fa-070962b8d4e6', 'Ahmad Shah Abdali (Durrani)', true, '881a96aa-631c-4c40-8b4d-bf56f2104bad');
