INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('deb20b02-5e32-42d1-8ed5-ed76db9e7d97', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Easy', 'Who was appointed Subadar of Awadh in 1722 and founded the powerful autonomous state of AWADH?', 'Burhan-ul-Mulk Sa''adat Khan established Awadh''s autonomy in 1722, uniting the offices of Subadari, Diwani, and Faujdari in his person.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7d1a842-7c37-4d8f-bc89-4fe17063ad2b', 'Burhan-ul-Mulk Sa''adat Khan', true, 'deb20b02-5e32-42d1-8ed5-ed76db9e7d97');
