INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('831ff8af-3d7d-4be0-bfa2-42e59e2cebc1', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Easy', 'Who was appointed Naib Subadar (and later Subadar) of Bengal, transferring the provincial capital from Dacca to MURSHIDABAD?', 'Murshid Quli Khan consolidated Bengal as a virtually independent state, establishing Murshidabad as its administrative capital.', NOW()) ON CONFLICT DO NOTHING;
