INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e60bbdc-2116-4b5b-be03-f1fe50c99639', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Easy', 'Who founded the autonomous state of HYDERABAD in the Deccan in 1724 after escaping the faction-ridden Mughal court at Delhi?', 'Nizam-ul-Mulk Asaf Jah consolidated the six Deccan subas into the independent Nizamate of Hyderabad in 1724.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16dfba68-7534-4c2d-8e94-b57a6a2c9831', 'Nizam-ul-Mulk Asaf Jah (Chin Qilich Khan)', true, '5e60bbdc-2116-4b5b-be03-f1fe50c99639');
