INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7262cd1b-75c2-4e10-8608-42d3f95735e1', 'Class 7', 'Social Science', 'Chapter 10: Eighteenth-Century Political Formations', 'Easy', 'Which Rajput ruler of Amber (Jaipur) was a brilliant astronomer and statesman who founded the planned pink city of JAIPUR and built five astronomical observatories (Jantar Mantars)?', 'Sawai Raja Jai Singh II built Jaipur (1727) and five masonry observatories (Jantar Mantar) in Delhi, Jaipur, Ujjain, Mathura, and Varanasi.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3256340-4f61-4250-bb99-af7572218748', 'Sawai Raja Jai Singh (Jai Singh II)', true, '7262cd1b-75c2-4e10-8608-42d3f95735e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56290b14-a611-4e55-998c-ba37f9901f31', 'Raja Ajit Singh of Jodhpur', false, '7262cd1b-75c2-4e10-8608-42d3f95735e1');
