INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2f1dca60-327a-48a7-8997-f61319348ffe', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Easy', 'जिस क्रिया में कर्म उपस्थित होता है और क्रिया का फल कर्ता पर न पड़कर कर्म पर पड़ता है (जैसे: ''अमित पुस्तक पढ़ता है''), उसे क्या कहते हैं?', 'सकर्मक क्रिया: जिस क्रिया में कार्य का प्रभाव कर्म पर पड़ता है (''अमित पुस्तक पढ़ता है'' में ''पुस्तक'' कर्म है)।', NOW()) ON CONFLICT DO NOTHING;
