INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed9434b7-55f2-4902-afd8-353cadc6cbcc', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Easy', 'क्रिया के जिस रूप से कार्य के संपन्न होने के ''समय'' (Time) का बोध होता है, उसे व्याकरण में क्या कहते हैं?', 'काल: क्रिया के जिस रूप से उसके होने के समय का पता चले, उसे काल कहते हैं।', NOW()) ON CONFLICT DO NOTHING;
