INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1ab3b5b-9fe5-4c58-94b7-8105638793d8', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Easy', '''अध्यापक ने छात्रों को हिंदी पढ़ाई।'' इस वाक्य में ''पढ़ाई'' किस प्रकार की सकर्मक क्रिया है?', 'द्विकर्मक क्रिया: जिस क्रिया में दो कर्म होते हैं (किसे = छात्रों को, क्या = हिंदी)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ecebc2f-f230-4652-a3e2-1ad75b737d5b', 'द्विकर्मक क्रिया (इसमें दो कर्म हैं: ''छात्रों को'' [गौण कर्म] और ''हिंदी'' [मुख्य कर्म])', true, 'f1ab3b5b-9fe5-4c58-94b7-8105638793d8');
