INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c43d9906-8a49-405a-a666-5d918398f09b', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', 'सकर्मक और अकर्मक क्रिया की पहचान करने के लिए क्रिया के साथ कौन-से प्रश्नवाचक शब्द लगाकर प्रश्न पूछा जाता है?', 'पहचान नियम: क्रिया + ''क्या/किसे/किसको'' = उत्तर मिले तो सकर्मक, न मिले तो अकर्मक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f94747d1-cdb6-4e8e-8d4b-672afae03989', '''क्या'', ''किसे'' या ''किसको'' लगाकर (यदि उत्तर मिल जाए तो सकर्मक, और यदि उत्तर न मिले तो अकर्मक)', true, 'c43d9906-8a49-405a-a666-5d918398f09b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b7b6ced-156a-408d-8dd7-401a8640967e', '''कब'' और ''कहाँ'' लगाकर', false, 'c43d9906-8a49-405a-a666-5d918398f09b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf590b1f-eb8a-42f3-8364-4ffb8747d3d0', '''क्यों'' और ''कैसे'' लगाकर', false, 'c43d9906-8a49-405a-a666-5d918398f09b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d0e64d9-affa-4087-981f-a83065f2ef30', '''कितना'' लगाकर', false, 'c43d9906-8a49-405a-a666-5d918398f09b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89f3209c-0694-4a7c-a350-6ee2395024e6', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', 'जब कर्ता स्वयं कार्य न करके किसी अन्य को कार्य करने के लिए प्रेरित करता है (जैसे: ''माँ नौकरानी से कपड़े धुलवाती है''), तो उस क्रिया को क्या कहते हैं?', 'प्रेरणार्थक क्रिया: जहाँ कर्ता स्वयं कार्य न कर दूसरे को कार्य के लिए प्रेरित करे (लिखना → लिखाना / लिखवाना)।', NOW()) ON CONFLICT DO NOTHING;
