INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('be2e7ec7-a785-487f-8a8a-205464145dae', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', 'संज्ञा, सर्वनाम अथवा विशेषण शब्दों से बनने वाली क्रियाओं को क्या कहा जाता है (जैसे: हाथ → हथियाना, बात → बतियाना, शर्म → शर्माना, अपना → अपनाना)?', 'नामधातु क्रिया: संज्ञा, सर्वनाम और विशेषण शब्दों में प्रत्यय जोड़कर बनाई जाने वाली क्रियाएँ।', NOW()) ON CONFLICT DO NOTHING;
