INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('08658b00-fcfc-4fc5-b87c-4bd50d272819', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', 'जब मुख्य क्रिया से पहले कोई अन्य क्रिया संपन्न हो चुकी होती है और उसके अंत में ''कर'' या ''के'' जुड़ा होता है (जैसे: ''वह पढ़कर सो गया''), तो उस पहली क्रिया को क्या कहते हैं?', 'पूर्वकालिक क्रिया: मुख्य क्रिया से पूर्व समाप्त होने वाली क्रिया (जैसे: ''पढ़कर सो गया'' में ''पढ़कर'' पूर्वकालिक है)।', NOW()) ON CONFLICT DO NOTHING;
