INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c21efbfe-1e51-42b2-a992-a18e3cf8a67e', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', 'क्रिया के जिस रूप से यह ज्ञात हो कि कार्य भूतकाल में प्रारंभ हुआ था, परन्तु बोलते समय तक समाप्त नहीं हुआ था (जैसे: ''वर्षा हो रही थी'', ''अमित पढ़ रहा था''), उसे क्या कहते हैं?', 'अपूर्ण भूतकाल: भूतकाल में क्रिया की निरंतरता (असमाप्ति) का बोध कराता है।', NOW()) ON CONFLICT DO NOTHING;
