INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('422f3c6f-fd15-4954-9332-1fb61ea4daea', 'सकर्मक क्रिया, पूर्ण भूतकाल', false, '485984c2-9a59-413d-848a-c8cfa8ced8fc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6b310f8-21bf-4311-acf6-0358663ddec2', 'अकर्मक क्रिया, संभाव्य भविष्यत', false, '485984c2-9a59-413d-848a-c8cfa8ced8fc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2dca0aaf-037e-4545-b8cb-07aee86421c4', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Medium', 'भूतकाल के कुल कितने उप-भेद (Sub-types) होते हैं?', 'हिंदी व्याकरण में भूतकाल के 6 उपभेद होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0b0bafb-89c0-46dd-9d40-f172f452b771', '6 उप-भेद (सामान्य भूत, आसन्न भूत, पूर्ण भूत, अपूर्ण भूत, संदिग्ध भूत, हेतुहेतुमद्भूत)', true, '2dca0aaf-037e-4545-b8cb-07aee86421c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a81e6f6-1075-4cfe-a92c-e17eb79fa45b', '3 उप-भेद', false, '2dca0aaf-037e-4545-b8cb-07aee86421c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d0b89f7-32e1-47cd-814c-baf1771c219e', '4 उप-भेद', false, '2dca0aaf-037e-4545-b8cb-07aee86421c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2dbc6e22-e768-4632-bd1d-60883696a231', '5 उप-भेद', false, '2dca0aaf-037e-4545-b8cb-07aee86421c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf1139f1-0935-4d30-9d96-35467a2045bf', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34b3334d-c4cb-4192-b7a5-b495393f33c8', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'cf1139f1-0935-4d30-9d96-35467a2045bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e1caf9b-7fd4-4062-871a-617e0edcd526', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'cf1139f1-0935-4d30-9d96-35467a2045bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37f57a99-52b9-47bd-bf9f-a57151eeccd6', '(A) सही है, परन्तु (R) गलत है।', false, 'cf1139f1-0935-4d30-9d96-35467a2045bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ed7ea54-eddd-425c-8830-769f23155bf7', '(A) गलत है, परन्तु (R) सही है।', false, 'cf1139f1-0935-4d30-9d96-35467a2045bf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('07cc1437-920e-4140-8b2b-0ef81b8e6e8b', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', 'Spot the IMPOSTER in the following group of मूल धातु और उनसे बनी नामधातु क्रियाओं में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0adc3561-7250-4855-b7e9-0c397003fb84', 'युग्म 1', false, '07cc1437-920e-4140-8b2b-0ef81b8e6e8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('643c81dd-3339-46cd-b239-01a4dba7fe0c', 'युग्म 2', false, '07cc1437-920e-4140-8b2b-0ef81b8e6e8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df8f3993-e731-4079-b575-36e3e7365ed0', 'युग्म 3', false, '07cc1437-920e-4140-8b2b-0ef81b8e6e8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5c0ab61-30f9-4535-ad33-d0587940c714', 'युग्म 4 (''चलना'' क्रिया है और ''चलाना'' प्रेरणार्थक क्रिया है ; यह संज्ञा/सर्वनाम से बनी नामधातु क्रिया नहीं है)', true, '07cc1437-920e-4140-8b2b-0ef81b8e6e8b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9bca3f74-2199-4b49-90a7-327d7e0ea671', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', 'सुमेलित कीजिए (वाक्य और उनके काल का सही भेद):
(क) उसने खाना खाया था      -> (i) पूर्ण भूतकाल
(ख) वह पत्र लिख रहा था      -> (ii) अपूर्ण भूतकाल
(ग) वह घर पहुँच गया होगा    -> (iii) संदिग्ध भूतकाल
(घ) यदि वर्षा होती तो फसल अच्छी होती -> (iv) हेतुहेतुमद्भूत काल', 'खाया था = पूर्ण भूत; लिख रहा था = अपूर्ण भूत; गया होगा = संदिग्ध भूत; वर्षा होती तो = हेतुहेतुमद्भूत।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2641dd7c-a7c2-422f-8631-32df92d911a0', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, '9bca3f74-2199-4b49-90a7-327d7e0ea671');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdce3565-521b-4709-be6d-32255e61530a', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '9bca3f74-2199-4b49-90a7-327d7e0ea671');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b8f6efb-f4f6-4069-96b3-a6eeb8efa519', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '9bca3f74-2199-4b49-90a7-327d7e0ea671');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98619990-fe38-40e8-aadf-f69d3226fb3e', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '9bca3f74-2199-4b49-90a7-327d7e0ea671');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a3d59b60-1188-4e71-a669-1e3881d54c8d', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', 'सकर्मक क्रिया के दो भेद ''एककर्मक'' और ''द्विकर्मक'' में मुख्य कर्म और गौण कर्म की क्या विशेषता होती है?', 'गौण कर्म = सजीव + ''को'' (विभक्ति सहित); मुख्य कर्म = निर्जीव + क्रिया के सन्निकट (विभक्ति रहित)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91ef36c4-6225-4a01-b213-415be27d66ac', 'मुख्य कर्म प्रायः अप्राणिवाचक (निर्जीव) होता है और क्रिया के ठीक पहले आता है (बिना विभक्ति के) ; जबकि गौण कर्म प्राणिवाचक (सजीव) होता है और ''को'' विभक्ति सहित आता है (जैसे: ''उसने मुझे [गौण] पुस्तक [मुख्य] दी'')', true, 'a3d59b60-1188-4e71-a669-1e3881d54c8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2653f60-cccc-41a5-ac43-10cb7e24c5ba', 'दोनों कर्म हमेशा सजीव होते हैं', false, 'a3d59b60-1188-4e71-a669-1e3881d54c8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c237f630-2892-4cce-bb76-1a978882bce2', 'मुख्य कर्म हमेशा ''को'' से युक्त होता है', false, 'a3d59b60-1188-4e71-a669-1e3881d54c8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('267b6672-d543-4e3e-861c-aaa61b359bbe', 'द्विकर्मक क्रिया में केवल एक ही कर्म होता है', false, 'a3d59b60-1188-4e71-a669-1e3881d54c8d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('446aff7b-45f3-4fcc-b0cf-e39fb9502917', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', '''अकर्मक क्रिया'' का जब ''सकर्मक'' में रूपांतरण किया जाता है, तो कौन-सा युग्म शुद्ध है?', 'अकर्मक से सकर्मक रूपांतरण: गिरना→गिराना, कटना→काटना, मरना→मारना, खुलना→खोलना।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6254eea3-63ce-42e3-b761-fc1cd217d40d', 'गिरना (अकर्मक) -> गिराना (सकर्मक) ; कटना (अकर्मक) -> काटना (सकर्मक) ; मरना (अकर्मक) -> मारना (सकर्मक)', true, '446aff7b-45f3-4fcc-b0cf-e39fb9502917');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d288fa97-13e0-4054-82cd-c1dbc16cd217', 'रोना -> हँसना', false, '446aff7b-45f3-4fcc-b0cf-e39fb9502917');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01e62497-6700-424e-bd61-349d196c37f2', 'सोना -> जागना', false, '446aff7b-45f3-4fcc-b0cf-e39fb9502917');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f97f53b-c91a-4952-8e00-4ac94616f156', 'उड़ना -> दौड़ना', false, '446aff7b-45f3-4fcc-b0cf-e39fb9502917');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c72c33b4-1103-4fd8-ab99-66b5a5d51b1d', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', 'सहायक क्रिया (Auxiliary Verb) और रंजक क्रिया (Explicator) का मुख्य क्रिया के साथ क्या संबंध होता है?', 'सहायक क्रिया काल रूप बनाती है (''रहा है''); रंजक क्रिया संयुक्त क्रिया में अर्थगत छटा व तीव्रता जोड़ती है (''चल दिया'', ''हँस पड़ा'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('784602fe-9dd7-4101-b632-a879cf1c4a4d', 'सहायक क्रिया काल और वाच्य का निर्धारण करती है (जैसे: ''है'', ''था'', ''होगा'') ; जबकि रंजक क्रिया मुख्य क्रिया के अर्थ में विशिष्ट भाव, गतिशीलता या आकस्मिकता लाती है (जैसे: ''हँस पड़ा'', ''रो बैठा'')', true, 'c72c33b4-1103-4fd8-ab99-66b5a5d51b1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b0b4a3a-2e46-4506-8ea5-6aaf3d85b21f', 'सहायक क्रिया केवल स्त्रीलिंग होती है', false, 'c72c33b4-1103-4fd8-ab99-66b5a5d51b1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92309e90-5bed-4441-adea-6caa5fd287e9', 'रंजक क्रिया का कोई अर्थ नहीं होता', false, 'c72c33b4-1103-4fd8-ab99-66b5a5d51b1d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fee3e870-1d9a-43e1-b992-7fc3c0c3e7bd', 'दोनों मिलकर क्रिया को अकर्मक बनाती हैं', false, 'c72c33b4-1103-4fd8-ab99-66b5a5d51b1d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4d1faf9-666c-40c6-9417-d79d74cfca5f', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', 'निम्नलिखित वाक्यों में से ''द्विकर्मक क्रिया'' वाले वाक्य का चयन कीजिए:', '''किसे दिखाए'' = पर्यटकों को (गौण कर्म); ''क्या दिखाए'' = गुलाब (मुख्य कर्म) → द्विकर्मक क्रिया।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('995301a2-5c2c-4637-ba71-12d8ad0cbf24', '''माली ने पर्यटकों को सुंदर गुलाब दिखाए।'' (गौण कर्म: पर्यटकों को, मुख्य कर्म: सुंदर गुलाब)', true, 'e4d1faf9-666c-40c6-9417-d79d74cfca5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5008eac1-a039-477a-80e5-9a74d3bf129b', '''माली पौधों में पानी दे रहा है।''', false, 'e4d1faf9-666c-40c6-9417-d79d74cfca5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fec0090c-6488-494c-8b2a-f701e85b8f24', '''पर्यटक बगीचे में घूम रहे हैं।''', false, 'e4d1faf9-666c-40c6-9417-d79d74cfca5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('144e7a2d-be28-4826-991c-dc56ac9c7042', '''गुलाब बहुत सुंदर खिलते हैं।''', false, 'e4d1faf9-666c-40c6-9417-d79d74cfca5f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d2f0ce8e-b448-4331-8a95-50e61d345b64', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', '''वह प्रतिदिन पाँच किलोमीटर दौड़ता है।'' वाक्य में ''दौड़ता है'' क्रिया किस भेद की है?', '''पाँच किलोमीटर'' दूरी/मात्रा बताने वाला क्रियाविशेषण है, कर्म नहीं; ''दौड़ना'' नित्य अकर्मक क्रिया है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11e3b7f6-dbd1-47ec-a03c-ff20f69e7881', 'अकर्मक क्रिया (क्योंकि ''पाँच किलोमीटर'' यहाँ कर्म नहीं, बल्कि परिमाणवाचक क्रियाविशेषण है)', true, 'd2f0ce8e-b448-4331-8a95-50e61d345b64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfedbe26-711e-4b0b-af50-ca312c275679', 'सकर्मक क्रिया', false, 'd2f0ce8e-b448-4331-8a95-50e61d345b64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac79ac7d-212c-42af-94c8-83643bf1c706', 'द्विकर्मक क्रिया', false, 'd2f0ce8e-b448-4331-8a95-50e61d345b64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa82e69b-7ccb-42d9-9275-59cd80ec7f45', 'प्रेरणार्थक क्रिया', false, 'd2f0ce8e-b448-4331-8a95-50e61d345b64');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7400acba-23e7-49ce-8826-612e0c933cc0', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', '''अनुराग ने फल खाए।'' इस भूतकालिक वाक्य में कर्ता के साथ ''ने'' विभक्ति का प्रयोग क्यों हुआ?', 'हिंदी व्याकरण का स्वर्णिम नियम: भूतकाल में सकर्मक धातुओं के साथ कर्ता में ''ने'' का प्रयोग अनिवार्य है (Ergative construction)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f620ddd-26fe-4efb-b7d3-5d8162cb9eb9', 'सकर्मक क्रिया के भूतकाल (सामान्य, आसन्न, पूर्ण, संदिग्ध) में कर्ता के साथ ''ने'' परसर्ग (कारक चिह्न) का प्रयोग अनिवार्य होता है', true, '7400acba-23e7-49ce-8826-612e0c933cc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58989222-5452-4f3c-beb9-68d48fbfc6c8', 'क्योंकि अनुराग पुल्लिंग है', false, '7400acba-23e7-49ce-8826-612e0c933cc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fa01d25-ab5a-4957-bcac-104dabf4a0a1', 'क्योंकि फल बहुत मीठे थे', false, '7400acba-23e7-49ce-8826-612e0c933cc0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d360555c-69b1-44f5-a8db-bf401bb7ac3e', 'अकर्मक क्रिया के कारण', false, '7400acba-23e7-49ce-8826-612e0c933cc0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3076f62a-0396-4a70-96e3-5a440000432c', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', '''रामू चाय बना रहा होगा।'' इस वाक्य की क्रिया किस काल की है?', 'रहा होगा / ता होगा = संदिग्ध वर्तमान काल (''इस समय रामू चाय बना रहा होगा'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d79a138-d9aa-40de-998c-e9b589d3a674', 'संदिग्ध वर्तमान काल (वर्तमान में क्रिया के घटित होने में संदेह)', true, '3076f62a-0396-4a70-96e3-5a440000432c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6e2a9c9-3be4-414e-806a-c0f65fb28780', 'संदिग्ध भूतकाल', false, '3076f62a-0396-4a70-96e3-5a440000432c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f56f23c-fc11-486f-968a-2c798e2725fa', 'सामान्य भविष्यत काल', false, '3076f62a-0396-4a70-96e3-5a440000432c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73a8bf60-19e7-4535-bb50-b942beadbe15', 'अपूर्ण भूतकाल', false, '3076f62a-0396-4a70-96e3-5a440000432c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0eedeed1-f0a3-482d-a14b-2ddb9e8da1f3', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', '''यदि डॉक्टर समय पर आ जाते, तो रोगी की जान बच जाती।'' यह वाक्य किस काल का प्रतिनिधित्व करता है?', 'हेतुहेतुमद्भूत: भूतकाल में कार्य-कारण शर्त पूरी न होने पर क्रिया संपन्न न होने का बोध।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('305b1d4f-4c3d-4a6b-985b-e1db59e869bb', 'हेतुहेतुमद्भूत काल', true, '0eedeed1-f0a3-482d-a14b-2ddb9e8da1f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('104065c3-a567-4ecb-a0d5-27e4fc5f6919', 'संदिग्ध भूतकाल', false, '0eedeed1-f0a3-482d-a14b-2ddb9e8da1f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6400ea2-e868-42f0-b202-c042807e8a12', 'आसन्न भूतकाल', false, '0eedeed1-f0a3-482d-a14b-2ddb9e8da1f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18fcda7d-d8ac-4a77-a9ad-2d4c27754b4b', 'हेतुहेतुमद्भविष्यत काल', false, '0eedeed1-f0a3-482d-a14b-2ddb9e8da1f3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9865eeb-febc-490e-8465-6f1ca2c77a73', 'Class 7', 'Hindi Grammar', 'Chapter 10: क्रिया और काल', 'Hard', 'क्रिया और काल के गहन व्याकरणिक ज्ञान का भाषा में क्या सर्वोच्च महत्व है?', 'क्रिया वाक्य का अपरिहार्य संरचनात्मक नाभिक है; क्रिया और काल के शुद्ध अन्वय से ही भाषा में भाव, समय और सार्थकता की पूर्ण अभिव्यक्ति संभव है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fb91fda-a88a-4ca3-986e-16a0c4a4d976', 'क्रिया वाक्य का अनिवार्य केंद्रीय मेरुदंड (Spine) है जिसके बिना कोई वाक्य पूर्ण नहीं हो सकता ; काल क्रिया की समय-स्थिति और यथार्थता को सटीक संप्रेषित करता है', true, 'e9865eeb-febc-490e-8465-6f1ca2c77a73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2b89b0d-6712-48f5-8fdf-0c8ef3e82b8d', 'क्रिया केवल नाटकों में प्रयुक्त होती है', false, 'e9865eeb-febc-490e-8465-6f1ca2c77a73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c93bd1eb-966b-4106-a510-f2268bed1480', 'काल केवल ज्योतिष में प्रयुक्त होता है', false, 'e9865eeb-febc-490e-8465-6f1ca2c77a73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88b914a5-7821-4692-95b5-a0e67a69ed08', 'इनके बिना भी वाक्य रचना शुद्ध रहती है', false, 'e9865eeb-febc-490e-8465-6f1ca2c77a73');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('05d47195-c7b5-4684-a787-f37908e22601', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'Light travels along which geometric path through a uniform, transparent medium (Rectilinear Propagation of Light)?', 'Rectilinear propagation: light travels along straight lines, causing the formation of sharp shadows and pinhole camera images.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e77d3010-ea1f-4488-99b4-6e4a4bb07722', 'Straight Lines', true, '05d47195-c7b5-4684-a787-f37908e22601');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a8e49c8-42b7-4e69-911e-c65689855005', 'Curved circular lines', false, '05d47195-c7b5-4684-a787-f37908e22601');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe15e589-ba1b-4736-ae0e-9008255f84d2', 'Zig-zag paths', false, '05d47195-c7b5-4684-a787-f37908e22601');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3dc89dd-fce5-464e-b56c-b602c4bc819c', 'Spiral waves only', false, '05d47195-c7b5-4684-a787-f37908e22601');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6c26c7a3-ef56-413a-8840-20c9b4e61b63', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'What is the phenomenon of bouncing back of light rays from a polished, shiny, or reflective surface called?', 'Reflection is the change in direction and bouncing back of a light wavefront at an interface between two different media.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e339033-b1b9-4c4c-adeb-6e7967c1f486', 'Reflection of Light', true, '6c26c7a3-ef56-413a-8840-20c9b4e61b63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c466350f-b244-4fbb-b562-363e5d2ff1e3', 'Refraction of Light', false, '6c26c7a3-ef56-413a-8840-20c9b4e61b63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e6cb415-229e-4679-8d5a-02e8041fc25c', 'Dispersion of Light', false, '6c26c7a3-ef56-413a-8840-20c9b4e61b63');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a2157a6-97da-46fb-8ab1-a168d8041517', 'Absorption', false, '6c26c7a3-ef56-413a-8840-20c9b4e61b63');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96b0d05f-4cf4-40c1-b393-b0595933a6d5', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'What are the characteristics of an image formed by a flat PLANE MIRROR?', 'A plane mirror forms an erect, virtual image of identical size, located at the same distance behind the mirror as the object in front.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da12bb69-be19-4432-b218-90d484b202d2', 'Erect (upright), Virtual (cannot be obtained on a screen), Same size as the object, and Laterally Inverted', true, '96b0d05f-4cf4-40c1-b393-b0595933a6d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b42cfb93-1709-4b67-89d3-f28e200861b4', 'Inverted, Real, and Magnified', false, '96b0d05f-4cf4-40c1-b393-b0595933a6d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('637fced0-08be-487b-970f-aaf88b26737f', 'Real, Diminished, and Upside-down', false, '96b0d05f-4cf4-40c1-b393-b0595933a6d5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1a09fff-73bf-4c33-a3f5-266a33ec8b18', 'Virtual and ten times larger', false, '96b0d05f-4cf4-40c1-b393-b0595933a6d5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3175345a-0421-4812-9a9d-db04c300eb33', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'What optical phenomenon causes your right hand to appear as the left hand and your left hand to appear as the right hand in a mirror image?', 'Lateral inversion is the apparent sideways reversal of left and right in a planar reflection.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6d88df2-9def-4215-a336-20c1bc1adda0', 'Lateral Inversion', true, '3175345a-0421-4812-9a9d-db04c300eb33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d2ec0e7-f95a-4d38-871d-2ad32354029e', 'Refraction', false, '3175345a-0421-4812-9a9d-db04c300eb33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcff2433-ce34-4986-bb58-8ff37609899e', 'Dispersion', false, '3175345a-0421-4812-9a9d-db04c300eb33');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa0f6d1b-ea93-459b-af3a-5aa1231f2ca6', 'Total Internal Reflection', false, '3175345a-0421-4812-9a9d-db04c300eb33');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ed60ff52-13d9-4b71-a3ca-add5c5886bb9', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'Why is the word ''AMBULANCE'' written in reverse laterally inverted script (''ECNALUBMA'') on emergency medical vehicles?', 'Pre-inverting the lettering ensures that when viewed through a driver''s rear-view mirror, lateral inversion renders ''AMBULANCE'' right-side up.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c257717-8883-420e-947b-256e1b062339', 'So that drivers of vehicles ahead can read the word correctly as ''AMBULANCE'' in their rear-view mirrors and immediately give way', true, 'ed60ff52-13d9-4b71-a3ca-add5c5886bb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9493f29-b462-45e4-8877-cfec46e08888', 'It is a foreign language spelling', false, 'ed60ff52-13d9-4b71-a3ca-add5c5886bb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8ed1ccc-1158-4f01-b382-f22249ac0874', 'To confuse pedestrians on the road', false, 'ed60ff52-13d9-4b71-a3ca-add5c5886bb9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('255f4abf-8262-45a5-864b-1d914393a38e', 'It is an artistic design', false, 'ed60ff52-13d9-4b71-a3ca-add5c5886bb9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('95053403-9f19-457b-8abf-6e646488c25b', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'A spherical mirror whose reflecting surface is curved INWARDS (like the inside surface of a shining spoon) is called a:', 'A concave mirror has an inward-curving converging reflecting surface.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1983a8d-1ef6-42c1-bbff-ffd3bebe8d46', 'Concave Mirror', true, '95053403-9f19-457b-8abf-6e646488c25b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0bd4e36-54b7-42dd-b968-4ac1419480b3', 'Convex Mirror', false, '95053403-9f19-457b-8abf-6e646488c25b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9018664-bb40-4303-8fc9-bb1585663c80', 'Plane Mirror', false, '95053403-9f19-457b-8abf-6e646488c25b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e21ce62d-248a-4d69-82dd-8c53bf6eca8e', 'Cylindrical Mirror', false, '95053403-9f19-457b-8abf-6e646488c25b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d046ea3-34b4-4b28-b5fa-aa88fb3b0af3', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'A spherical mirror whose reflecting surface is curved OUTWARDS (like the back outer surface of a shining spoon) is called a:', 'A convex mirror has an outward-bulging diverging reflecting surface.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb22c60b-c19e-46ae-acd4-2ca8598eb484', 'Convex Mirror', true, '9d046ea3-34b4-4b28-b5fa-aa88fb3b0af3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4145f2c0-5bda-44c4-95d8-db32558df097', 'Concave Mirror', false, '9d046ea3-34b4-4b28-b5fa-aa88fb3b0af3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b719dce4-9e51-400e-9973-ad10c933b5b4', 'Plane Mirror', false, '9d046ea3-34b4-4b28-b5fa-aa88fb3b0af3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e293d7f-828e-411d-99dd-c410881505b8', 'Parabolic Mirror', false, '9d046ea3-34b4-4b28-b5fa-aa88fb3b0af3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f4b5e03-1bc4-4d29-a697-e3778af8dc8c', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'An image that can be formed and projected onto a physical SCREEN is called a:', 'A real image is formed by the actual physical intersection of reflected/refracted light rays and can be captured on a screen.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77023a40-749c-4e9b-ab6c-a4e6a4069735', 'Real Image', true, '5f4b5e03-1bc4-4d29-a697-e3778af8dc8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f128f167-7e73-4266-ade9-4ec6b2be4a0e', 'Virtual Image', false, '5f4b5e03-1bc4-4d29-a697-e3778af8dc8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50c4f94f-bedc-4fab-8448-bb2839af29a3', 'Lateral Image', false, '5f4b5e03-1bc4-4d29-a697-e3778af8dc8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff0cf46d-87f2-4e0a-a951-98f76ee4d2bd', 'Inverted Image only', false, '5f4b5e03-1bc4-4d29-a697-e3778af8dc8c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36230cf2-30ea-4ba0-b4da-f0182c24825c', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'An image that CANNOT be obtained or projected on a screen is called a:', 'A virtual image occurs where light rays only appear to diverge from a point behind the mirror/lens and cannot be captured on a screen.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('226c35a5-2862-4eb2-9806-acbad024bc72', 'Virtual Image', true, '36230cf2-30ea-4ba0-b4da-f0182c24825c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cade6206-1504-4fa5-8ed2-f8753cc5af98', 'Real Image', false, '36230cf2-30ea-4ba0-b4da-f0182c24825c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb2f6298-86d3-412b-b931-748e6cd491b3', 'Shadow', false, '36230cf2-30ea-4ba0-b4da-f0182c24825c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27d8c43c-cd06-492a-b8b3-900e8d918333', 'Magnified Image', false, '36230cf2-30ea-4ba0-b4da-f0182c24825c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d200e6de-fcf9-4953-becb-483d86a70d22', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'A transparent optical lens that is THICKER in the middle than at the edges, converging parallel light rays to a focus, is called a:', 'A convex lens is thicker at its center and converges incident parallel light rays toward a real focal point.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b81472fb-2900-46d5-8623-85484f62e590', 'Convex Lens (Converging Lens)', true, 'd200e6de-fcf9-4953-becb-483d86a70d22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5131f18-b4e0-4f79-a8f8-faaf4a9921c6', 'Concave Lens', false, 'd200e6de-fcf9-4953-becb-483d86a70d22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b38598a-d043-491d-a665-54ecd5e8abf0', 'Plane Lens', false, 'd200e6de-fcf9-4953-becb-483d86a70d22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea04ac38-491c-4aa2-80bd-5ba7d6642f35', 'Cylindrical Lens', false, 'd200e6de-fcf9-4953-becb-483d86a70d22');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('99ea7b37-31b5-4421-b8c2-8a8962307b60', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'A transparent optical lens that is THINNER in the middle than at the edges, diverging light rays outwards, is called a:', 'A concave lens is thinner at the center than at the periphery, causing parallel light rays to diverge.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40627eb6-be28-49d3-bbc0-1065848b9941', 'Concave Lens (Diverging Lens)', true, '99ea7b37-31b5-4421-b8c2-8a8962307b60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a83b061e-1107-4d8b-bd84-02e6bece6c13', 'Convex Lens', false, '99ea7b37-31b5-4421-b8c2-8a8962307b60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6dd49630-deb4-4e45-9bd8-106c2674fe49', 'Biconvex Lens', false, '99ea7b37-31b5-4421-b8c2-8a8962307b60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0111bb9-156d-463c-bc2d-40a22afc993f', 'Magnifying Lens', false, '99ea7b37-31b5-4421-b8c2-8a8962307b60');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('54b8c37d-8471-4f9a-8974-de1119afff81', 'Class 7', 'Science', 'Chapter 11: Light', 'Easy', 'White sunlight consists of how many distinct spectral colors that can be split by a glass prism (VIBGYOR)?', 'White light is a polychromatic mixture of seven constituent spectral wavelengths: Violet, Indigo, Blue, Green, Yellow, Orange, Red (VIBGYOR).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f4df2ad-89bd-4cb2-b162-f48048311398', 'Seven Colors (Violet, Indigo, Blue, Green, Yellow, Orange, Red)', true, '54b8c37d-8471-4f9a-8974-de1119afff81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10852109-8617-4786-9865-56f40903725e', 'Three Colors (Red, Blue, Green)', false, '54b8c37d-8471-4f9a-8974-de1119afff81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a4b14eb-9db7-4458-bdd1-c19bd81334f5', 'Five Colors', false, '54b8c37d-8471-4f9a-8974-de1119afff81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f184f51-8e0b-459d-9955-d498d652233a', 'Only One Color', false, '54b8c37d-8471-4f9a-8974-de1119afff81');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0291441-8a30-4331-a74d-1ed6eaf7e1d4', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'Which type of spherical mirror is used by Dentists to see an enlarged, magnified, and erect image of a patient''s teeth?', 'When an object is placed between the pole and principal focus of a concave mirror, it produces an erect, magnified, virtual image.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a242149b-239d-46f8-9dd4-c158c9c1c443', 'Concave Mirror (held close to the teeth within its focal length)', true, 'b0291441-8a30-4331-a74d-1ed6eaf7e1d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14d4e5b1-e0b6-40a5-9d4e-1975d1523b15', 'Convex Mirror', false, 'b0291441-8a30-4331-a74d-1ed6eaf7e1d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1bc2874c-295e-41d6-9a3d-e48aa2e4cec8', 'Plane Mirror', false, 'b0291441-8a30-4331-a74d-1ed6eaf7e1d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cee3f3d-6449-4d1a-888b-3bedbb1bbe04', 'Bifocal Mirror', false, 'b0291441-8a30-4331-a74d-1ed6eaf7e1d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b2acf761-9448-44f3-aaab-0ae7898aaad0', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'Why are CONVEX MIRRORS universally installed as side REAR-VIEW MIRRORS in cars, buses, and motorcycles?', 'Convex mirrors curve outwards, producing upright, diminished virtual images that capture an expansive panoramic field of traffic.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0670cb8-aa51-4529-b2ee-b3c3b51ffd39', 'They always form erect, diminished images and provide a vastly WIDER FIELD OF VIEW, allowing drivers to see large traffic behind them', true, 'b2acf761-9448-44f3-aaab-0ae7898aaad0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f1ce0f0-95b6-42f7-8404-78a4f22877e3', 'They magnify objects to look ten times closer', false, 'b2acf761-9448-44f3-aaab-0ae7898aaad0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bdeb6b6-69c3-4592-aff9-464b1935e6c1', 'They absorb heat from the road', false, 'b2acf761-9448-44f3-aaab-0ae7898aaad0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c41f93fa-1118-4450-9fc3-070d96d8f8ba', 'They glow in the dark', false, 'b2acf761-9448-44f3-aaab-0ae7898aaad0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4f646c07-8c37-47bc-a917-e4fc0ab68ad0', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'What type of spherical mirror is used as reflectors in automobile Headlights, Searchlights, and Solar Furnaces to throw powerful parallel beams of light?', 'Placing a lamp bulb at the focal point of a concave mirror produces a powerful, non-diverging parallel beam of reflected light.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b239ef34-323f-4c2a-9a64-192ef38ee853', 'Concave Mirrors (with the light bulb placed at its principal focus)', true, '4f646c07-8c37-47bc-a917-e4fc0ab68ad0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1cc5cfbb-78c9-47ce-aa53-1f55b244bc40', 'Convex Mirrors', false, '4f646c07-8c37-47bc-a917-e4fc0ab68ad0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b4f2f95-4433-4f9f-9548-f16b4a9793d5', 'Plane Mirrors', false, '4f646c07-8c37-47bc-a917-e4fc0ab68ad0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57958fb4-84f9-463b-a44a-242bf55b2a72', 'Cylindrical Mirrors', false, '4f646c07-8c37-47bc-a917-e4fc0ab68ad0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('946e2285-6ff6-45e3-8770-adc7fca3247e', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'What type of lens is used as a simple Handheld MAGNIFYING GLASS to read fine print or examine small insect parts?', 'A convex lens produces a magnified, upright, virtual image when an object is held within its focal distance (acting as a simple microscope).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24474dfb-6a85-4572-9aaf-f386a0e037b8', 'A Convex Lens (held close to the object)', true, '946e2285-6ff6-45e3-8770-adc7fca3247e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5abe722-2d60-4f64-a7f6-292f415ea2ab', 'A Concave Lens', false, '946e2285-6ff6-45e3-8770-adc7fca3247e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5837dd40-1924-4e76-b292-56aa06d97a0c', 'A Plane glass plate', false, '946e2285-6ff6-45e3-8770-adc7fca3247e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ffe2b07-b75c-4056-93dd-c2541926e6f5', 'A Tinted sunglasses lens', false, '946e2285-6ff6-45e3-8770-adc7fca3247e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d721275d-7b04-4e87-a7e9-3c465b26260d', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'What type of image is ALWAYS formed by a CONCAVE LENS, regardless of how far or close the object is placed?', 'A diverging concave lens always forms a virtual, erect, and diminished image located between the optical center and the principal focus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b39ecc0-77a7-414a-8720-a55cec454aec', 'Virtual, Erect (upright), and DIMINISHED (smaller in size than the object)', true, 'd721275d-7b04-4e87-a7e9-3c465b26260d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d928efbc-fc84-449c-9fdb-cbcf01b15bbd', 'Real, Inverted, and Magnified', false, 'd721275d-7b04-4e87-a7e9-3c465b26260d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80e13c0c-3074-4084-8bb0-0f984bb452a9', 'Real, Erect, and Same size', false, 'd721275d-7b04-4e87-a7e9-3c465b26260d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0727003-8a70-49a0-a71a-e2fe57ad91d8', 'Virtual and Magnified', false, 'd721275d-7b04-4e87-a7e9-3c465b26260d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('992d529e-c1a2-4a2e-80cc-3f86fd5224b7', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'What is the phenomenon of splitting white sunlight into its seven constituent spectral colors when passing through a triangular Glass Prism called?', 'Dispersion occurs because different wavelengths (colors) of light refract (bend) at slightly different angles when passing through glass.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0326f82f-0d7b-4f47-9181-c3d158897a14', 'Dispersion of Light', true, '992d529e-c1a2-4a2e-80cc-3f86fd5224b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b661f2f8-b220-4dee-90f7-74937048ed32', 'Reflection', false, '992d529e-c1a2-4a2e-80cc-3f86fd5224b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e10f13b5-b8f3-4685-8312-cb357ce71ea8', 'Scattering', false, '992d529e-c1a2-4a2e-80cc-3f86fd5224b7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('336d21dc-ff36-41df-ac5c-27476317f619', 'Diffraction', false, '992d529e-c1a2-4a2e-80cc-3f86fd5224b7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ee2966b6-f578-4c85-b5d7-8111921350f7', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'How is a natural RAINBOW formed in the sky after rain showers?', 'Atmospheric raindrops act as spherical prisms: refracting light on entry, internally reflecting it, and dispersing it upon exit into an arc.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1fdf26c-d48a-43fe-a149-24c76a8ad775', 'Millions of tiny suspended airborne raindrops act like miniature optical prisms, refracting, dispersing, and internally reflecting sunlight into a spectrum', true, 'ee2966b6-f578-4c85-b5d7-8111921350f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebeff67b-d35a-446f-b9db-f52b9ec147fd', 'Clouds paint colors in the sky with water', false, 'ee2966b6-f578-4c85-b5d7-8111921350f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f45eb81-52b5-4d4e-9c2b-81ce11a81b50', 'Sunlight reflects off ocean waves into the sky', false, 'ee2966b6-f578-4c85-b5d7-8111921350f7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd2b39ad-d462-4a6c-90cd-9b45a86e7033', 'Lightning leaves behind colored dust', false, 'ee2966b6-f578-4c85-b5d7-8111921350f7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba39ce34-6127-43f8-a4ee-f8389fefec60', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'What happens when a circular circular disc painted with all seven rainbow color segments (Newton''s Disc) is rotated RAPIDLY on its central axis?', 'Newton''s disc demonstrates additive color synthesis: rapid retinal persistence of vision (~1/16 s) superimposes the 7 colors into white light.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87ef1fd3-cb02-47ba-a21a-2e9ee6356877', 'The seven colors blend together due to the persistence of vision, and the disc appears completely WHITE (or pale grayish-white)', true, 'ba39ce34-6127-43f8-a4ee-f8389fefec60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07bfeb10-a742-4303-ad91-60bd8902d775', 'The disc turns solid black', false, 'ba39ce34-6127-43f8-a4ee-f8389fefec60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89e9e4c3-f090-4531-a176-d8b2f5b1cbfc', 'The disc catches fire', false, 'ba39ce34-6127-43f8-a4ee-f8389fefec60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('392bec2b-9421-411c-ad63-7febd50bc232', 'The disc becomes transparent like glass', false, 'ba39ce34-6127-43f8-a4ee-f8389fefec60');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8655025d-7311-4fa4-9f6e-0d5a8959649d', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'If an object is placed at a distance of 0.5 m in front of a flat plane mirror, what is the total distance between the OBJECT and its IMAGE?', 'Image distance behind mirror equals object distance in front (d = 0.5 m). Total distance between object and image = 0.5 + 0.5 = 1.0 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('110fd5a0-ebb3-44a3-b7ff-7087db8dfa16', '1.0 m (0.5 m in front + 0.5 m behind = 1.0 m)', true, '8655025d-7311-4fa4-9f6e-0d5a8959649d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12da2119-abc6-4ee3-8ec9-4dc94a2109a1', '0.5 m', false, '8655025d-7311-4fa4-9f6e-0d5a8959649d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('183b4435-b7be-4e38-bbdd-6826474a5ee1', '0.25 m', false, '8655025d-7311-4fa4-9f6e-0d5a8959649d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44159026-9ba9-4856-b2bd-282c6fcf0525', '2.0 m', false, '8655025d-7311-4fa4-9f6e-0d5a8959649d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb94cfa7-9ff4-4da1-9744-431bae12b8e3', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'David is observing his image in a plane mirror. The distance between the mirror and his image is 4 m. If he moves 1 m towards the mirror, what will be the new distance between David and his image?', 'When David moves 1 m closer, object distance = 4 - 1 = 3 m. Image distance = 3 m. Distance between David and his image = 3 + 3 = 6 m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b88883e3-5d10-49f2-afbf-5ed0b7c62c24', '6 m (New object distance = 3 m ; New image distance = 3 m ; Total = 3 + 3 = 6 m)', true, 'cb94cfa7-9ff4-4da1-9744-431bae12b8e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c53eab0-afc6-4773-9b23-4ae17b77373a', '8 m', false, 'cb94cfa7-9ff4-4da1-9744-431bae12b8e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10eb911f-f543-45de-93c2-9220864222e6', '4 m', false, 'cb94cfa7-9ff4-4da1-9744-431bae12b8e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e4a57d57-5d86-4d77-93c7-d47ae040c436', '5 m', false, 'cb94cfa7-9ff4-4da1-9744-431bae12b8e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('11add243-ae59-49e5-babc-1784b4902ce3', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'What happens when you focus direct bright sunlight onto a dry sheet of paper using a powerful CONVEX LENS for a couple of minutes?', 'A converging convex lens focuses incident solar irradiance into a tiny focal spot, concentrating thermal energy above the paper''s kindling point.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a5fb98e-a6a9-4cbb-82ea-147c6b615de9', 'The lens converges all solar rays to a single intense focal point; thermal concentration heats the paper until it scorches, smokes, and catches fire', true, '11add243-ae59-49e5-babc-1784b4902ce3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7956e156-6b7e-4c1e-b84f-8706768560eb', 'The paper turns into ice', false, '11add243-ae59-49e5-babc-1784b4902ce3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('57ddb0af-cc84-4fad-89db-957b73f2052f', 'The paper turns into a mirror', false, '11add243-ae59-49e5-babc-1784b4902ce3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f439c1db-9b67-438c-baab-f6cfc9afa481', 'The lens breaks into pieces', false, '11add243-ae59-49e5-babc-1784b4902ce3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1588944-55ab-48ee-a525-4e7756bd26c7', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'Why does the rear-view mirror of a car carry the printed safety warning: ''OBJECTS IN MIRROR ARE CLOSER THAN THEY APPEAR''?', 'Convex mirrors minify images to gain field-of-view; human visual perception equates smaller retinal size with greater distance.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bad319f3-ee4f-4149-a7b8-ea47b24163b3', 'Because convex mirrors form diminished (smaller) images, which makes approaching vehicles appear further away than their actual physical distance', true, 'f1588944-55ab-48ee-a525-4e7756bd26c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16ae1595-d0e0-4ed1-91fa-804478a0e85a', 'Because the mirror has a magnifier', false, 'f1588944-55ab-48ee-a525-4e7756bd26c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5936fb3d-8626-46df-9bc5-855f93055320', 'Because the glass is curved inwards', false, 'f1588944-55ab-48ee-a525-4e7756bd26c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd3cec22-212b-446a-a537-0851c811de94', 'Because the mirror works with radio waves', false, 'f1588944-55ab-48ee-a525-4e7756bd26c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a37e9ba8-2c82-4f63-840b-046e0f8ace80', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'Which color of light bends (refracts) the MOST and which color bends the LEAST when white light passes through a glass prism?', 'Cauchy''s dispersion formula: refractive index is inversely proportional to wavelength. High-frequency violet refracts most; low-frequency red refracts least.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('03bfce2a-eae9-4705-9614-d004d4348a20', 'VIOLET bends the most (shortest wavelength), and RED bends the least (longest wavelength)', true, 'a37e9ba8-2c82-4f63-840b-046e0f8ace80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('829e55e3-2126-4f32-bdb0-23c1a5ca5334', 'Red bends the most, and Violet bends the least', false, 'a37e9ba8-2c82-4f63-840b-046e0f8ace80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1953fcc9-8623-4929-9d9a-a87781ef92ab', 'Green bends the most, and Yellow bends the least', false, 'a37e9ba8-2c82-4f63-840b-046e0f8ace80');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33dd83f7-e0b8-42fa-ad49-18e2d1527808', 'All colors bend at the exact same angle', false, 'a37e9ba8-2c82-4f63-840b-046e0f8ace80');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe51377d-7775-48e7-ba40-19e8f1cd1850', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'What type of mirror is used in large Solar Cookers to concentrate solar energy onto cooking pots?', 'Large parabolic concave mirrors concentrate solar irradiance onto the focal point where cooking utensils are placed.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('12ad0dde-dbc6-4452-a37b-92557b4b4401', 'Concave Mirror (Converging reflector)', true, 'fe51377d-7775-48e7-ba40-19e8f1cd1850');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b401c014-b34e-4d1d-bf28-9b94a611f4fc', 'Convex Mirror', false, 'fe51377d-7775-48e7-ba40-19e8f1cd1850');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4a0f7691-cf0a-442f-b697-b8ab0c2df65e', 'Plane Mirror only', false, 'fe51377d-7775-48e7-ba40-19e8f1cd1850');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('049963cc-7902-415b-95ba-b9b385a5ed3b', 'Tinted dark glass', false, 'fe51377d-7775-48e7-ba40-19e8f1cd1850');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b1b4b0d5-2164-41ab-869c-1524584d0336', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'Which of the following optical instruments uses combinations of CONVEX LENSES to magnify distant celestial objects like the Moon and planets?', 'Refracting astronomical telescopes combine an objective convex lens of long focal length with an ocular eyepiece convex lens to resolve distant stars.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fbbbfb1-dc3b-4dbe-a250-7005b1918516', 'An Astronomical Telescope', true, 'b1b4b0d5-2164-41ab-869c-1524584d0336');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7acd627-fdba-4688-a8a7-f6bec3143f23', 'A Stethoscope', false, 'b1b4b0d5-2164-41ab-869c-1524584d0336');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ab3ca6c-9d28-40c1-81d6-e2c006fd2180', 'A Periscope', false, 'b1b4b0d5-2164-41ab-869c-1524584d0336');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('659bd7c2-19d8-418a-aaae-6b44e59fdf2e', 'A Barometer', false, 'b1b4b0d5-2164-41ab-869c-1524584d0336');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4d0142c6-1209-412b-82e6-b45b060e5775', 'Class 7', 'Science', 'Chapter 11: Light', 'Medium', 'What is the speed of light in vacuum (c)?', 'The universal speed of light in vacuum is approximately 299,792,458 m/s (≈ 3 × 10⁸ m/s or 300,000 km/s).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9738d361-2bef-4aae-8e82-c5621d2ac319', 'Approximately 3 × 10⁸ m/s (300,000 km/s)', true, '4d0142c6-1209-412b-82e6-b45b060e5775');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48cb9114-cf44-455b-b651-2b7c1dafe2fd', '3 × 10⁵ m/s', false, '4d0142c6-1209-412b-82e6-b45b060e5775');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0e2468d1-3853-4e36-9344-0ef8f1ecab70', '3,000 m/s', false, '4d0142c6-1209-412b-82e6-b45b060e5775');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3bab713-1ca1-45d2-814d-37df5fcbc29a', '300 m/s', false, '4d0142c6-1209-412b-82e6-b45b060e5775');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d54fb331-6e48-42c8-9139-c43ee10f6af5', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9ce82f5-6384-4352-a696-cb70aaabb369', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'd54fb331-6e48-42c8-9139-c43ee10f6af5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d909ed3-9693-495d-a445-aa3228e6ae3f', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'd54fb331-6e48-42c8-9139-c43ee10f6af5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06e66df2-0317-464c-a943-e86ac54d07c9', '(A) is true, but (R) is false.', false, 'd54fb331-6e48-42c8-9139-c43ee10f6af5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82ebc77f-fe2e-4533-a348-3899c06eeb3c', '(A) is false, but (R) is true.', false, 'd54fb331-6e48-42c8-9139-c43ee10f6af5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('420e46a6-4630-468a-9ceb-b43ba3d16fb0', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Spot the IMPOSTER in the following group of Optical Devices and their signature lens/mirror types:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3fc61787-9ca4-4fa6-ae07-e69593e736a9', 'Device 1', false, '420e46a6-4630-468a-9ceb-b43ba3d16fb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7693a5b-6be9-4154-bd2b-393f2c46281e', 'Device 2', false, '420e46a6-4630-468a-9ceb-b43ba3d16fb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70f98640-4b9a-4aee-b51a-a0e5040e41fd', 'Device 3', false, '420e46a6-4630-468a-9ceb-b43ba3d16fb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b550be3-eb64-4292-b75c-2366125421be', 'Device 4 (Astronomical refracting telescopes use precision high-purity CONVEX OPTICAL LENSES, not flat window glass)', true, '420e46a6-4630-468a-9ceb-b43ba3d16fb0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8dd894f9-7273-4e7a-bd78-7352f3551d58', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Sir Isaac Newton proved in 1666 that white light is a combination of colors by using two identical glass prisms. How did he conduct this experiment?', 'Newton''s classic recombination experiment: an inverted second prism cancels the angular dispersion of the first prism, synthesizing white light.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e6e8014-ab36-45e9-b722-ad22b79ee6f1', 'He placed a second identical inverted glass prism in the path of the dispersed spectrum from the first prism, recombining all seven colors back into a single beam of WHITE LIGHT', true, '8dd894f9-7273-4e7a-bd78-7352f3551d58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a3097b71-9a0b-4109-b465-d93eafcf8894', 'He painted the second prism with oil', false, '8dd894f9-7273-4e7a-bd78-7352f3551d58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe929bf3-3e0f-48a1-aac6-5aaa0506947c', 'He melted the second prism into water', false, '8dd894f9-7273-4e7a-bd78-7352f3551d58');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e41079e-4c49-44d8-b7ca-5e38df5ab709', 'He burned the light beam with a match', false, '8dd894f9-7273-4e7a-bd78-7352f3551d58');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bee5a908-1ba5-4628-baa3-1224dac95e57', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Match Column I (Optical Elements) with Column II (Image Characteristics & Applications):
(a) Plane Mirror    -> (i) Virtual, erect, identical size, lateral inversion
(b) Convex Mirror   -> (ii) Always virtual, erect, diminished with wide field of view
(c) Concave Mirror  -> (iii) Shaving & dental mirror (magnified virtual image when close)
(d) Concave Lens    -> (iv) Always virtual, erect, diminished; corrects myopia', 'Plane = identical size; Convex mirror = diminished wide field; Concave mirror = shaving/dental; Concave lens = diverging myopia correction.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e3f160a-6d38-409e-acb7-016e5a119237', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'bee5a908-1ba5-4628-baa3-1224dac95e57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0579c9a-54d3-42de-9cda-aa6f032d9588', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'bee5a908-1ba5-4628-baa3-1224dac95e57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('50a04940-794f-42f3-a24b-55c8187fa6d2', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'bee5a908-1ba5-4628-baa3-1224dac95e57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3707d0c-67c5-4aa9-bd93-94ca16cac672', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'bee5a908-1ba5-4628-baa3-1224dac95e57');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ff76ba9f-80c1-46d0-8fe8-d75338b2eb44', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Read the statements regarding optical reflection and refraction:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('310ea9e3-5a88-465c-8890-97283bf999e0', 'Statements 1 and 2 only', true, 'ff76ba9f-80c1-46d0-8fe8-d75338b2eb44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6dafc570-0f6e-4ab3-9771-58d2b8398a7a', 'Statements 2 and 3 only', false, 'ff76ba9f-80c1-46d0-8fe8-d75338b2eb44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f8f3aa85-8440-4f77-9e89-65f6102f106a', 'Statements 1 and 3 only', false, 'ff76ba9f-80c1-46d0-8fe8-d75338b2eb44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adc0a444-7f14-4c6e-8dcd-f1996fc0ad09', 'All Statements 1, 2, and 3', false, 'ff76ba9f-80c1-46d0-8fe8-d75338b2eb44');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cf520d53-737d-47bb-915f-929206935daf', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Why does a pencil partly immersed in a glass tumbler of water appear BENT or BROKEN at the water-air boundary?', 'Refraction at the planar water-air boundary shifts the apparent position of the submerged pencil tip upwards, creating an apparent bend.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a581bc9-b0df-4271-97f4-8f2b8ecd78c2', 'Due to Refraction: light rays emerging from the underwater portion of the pencil bend away from the normal as they pass from denser water into rarer air', true, 'cf520d53-737d-47bb-915f-929206935daf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1184ee7f-2fe9-4436-9a88-fa979ab639c4', 'Because water dissolves the pencil', false, 'cf520d53-737d-47bb-915f-929206935daf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('489e2f26-c975-43cb-bd3e-484179af3b33', 'Because water acts as a mirror', false, 'cf520d53-737d-47bb-915f-929206935daf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('791f23ce-fd23-4634-abe9-652f2ff3cc31', 'Because the glass is curved', false, 'cf520d53-737d-47bb-915f-929206935daf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a2169bdd-36f3-4698-b384-2f8b148a3670', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'How does a Periscope (used in submarines and military trenches) enable an observer to see objects over walls or above the water surface?', 'A periscope utilizes two plane mirrors set at 45° to provide twin successive 90° reflections, shifting the line of sight over obstacles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d57a2c3-277f-45ac-a0af-66314005fe59', 'It uses TWO parallel plane mirrors inclined at an angle of 45° to each other, successively reflecting light rays downwards through a tube', true, 'a2169bdd-36f3-4698-b384-2f8b148a3670');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7c01de9f-ab7d-4914-9168-f66e72616a5b', 'It uses an electric camera with a screen', false, 'a2169bdd-36f3-4698-b384-2f8b148a3670');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f53b68b-a5dc-467d-a81f-6a4947ad94b6', 'It uses two magnifying lenses only', false, 'a2169bdd-36f3-4698-b384-2f8b148a3670');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fedb3b12-366d-4646-bbb2-865b78c100f4', 'It works with sound waves', false, 'a2169bdd-36f3-4698-b384-2f8b148a3670');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4787d2cc-4833-4e8d-a3f1-939527f83b84', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Consider four optical scenarios:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37ddcf82-e680-44cb-ba39-5151d95df7a2', 'Scenario 4 only', true, '4787d2cc-4833-4e8d-a3f1-939527f83b84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36d1fc93-9dbc-4f26-91d5-30b13900ada5', 'Scenarios 1 and 2 only', false, '4787d2cc-4833-4e8d-a3f1-939527f83b84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9587008f-13f6-44a4-baeb-079cecef05e9', 'Scenarios 2 and 3 only', false, '4787d2cc-4833-4e8d-a3f1-939527f83b84');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4f2a7084-fb38-4d9e-8772-48aef11db5cb', 'All 1, 2, 3, and 4', false, '4787d2cc-4833-4e8d-a3f1-939527f83b84');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea3eb2b4-395a-44b6-b16e-bc7e365efa37', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Why does the primary rainbow always appear in the sky in the direction OPPOSITE to the position of the Sun (e.g. in the East in the late afternoon)?', 'Rainbow geometry requires anti-solar alignment: the observer''s back is to the sun so that internal reflection at ~40–42° enters the retina.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f06e56d-8122-4d34-b874-f48154f378ca', 'Because sunlight must enter the raindrops from behind the observer and be internally reflected back towards the observer''s eyes at an angle of ~42°', true, 'ea3eb2b4-395a-44b6-b16e-bc7e365efa37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('112c14db-d54f-4a30-883a-a6164ad47558', 'Because the Moon pulls the rainbow', false, 'ea3eb2b4-395a-44b6-b16e-bc7e365efa37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21f55cd1-efed-49d5-8a71-47c15a610df3', 'Because clouds only exist in the east', false, 'ea3eb2b4-395a-44b6-b16e-bc7e365efa37');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2cea07b-7867-4892-b44e-71478814f188', 'Because wind blows the colors opposite to the sun', false, 'ea3eb2b4-395a-44b6-b16e-bc7e365efa37');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca059186-2ae0-498b-9bba-c02eeff004d9', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'What is the optical mechanism of ''Persistence of Vision'' in human eye biology that makes motion pictures and Newton''s rotating color disc work?', 'Retinal photoreceptors retain photochemical activation for ~1/16 s (persistence of vision), enabling cinematic animation and color fusion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('80d802cf-551b-42d6-b32e-75b89ad42901', 'The visual impression of an image on the human retina remains for approximately 1/16th of a second after the light stimulus disappears, allowing sequential frames to blend seamlessly into continuous motion or white light', true, 'ca059186-2ae0-498b-9bba-c02eeff004d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c30cdcf-7bcd-4414-bf3f-e1176c3d4495', 'The eye stores images in memory for one hour', false, 'ca059186-2ae0-498b-9bba-c02eeff004d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df28a68d-b3fc-4b5e-9e2c-b8fe7a25fbd3', 'The eye blinks every second', false, 'ca059186-2ae0-498b-9bba-c02eeff004d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe037999-f9de-454d-b4cc-74be378793e7', 'The cornea turns into a prism', false, 'ca059186-2ae0-498b-9bba-c02eeff004d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('21dc5a54-2cdd-48f8-83ac-989d0098d0d4', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'Why are high-intensity parabolic Concave Mirrors used in solar thermal power plants (like Ivanpah or Bhadla Solar Park)?', 'Concentrated Solar Power (CSP) employs massive concave parabolic mirror fields to focus solar flux onto molten-salt heat exchangers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ffe39cf0-b836-4e51-9f1c-4a9e140f1c34', 'Thousands of giant concave mirrors (heliostats) track the Sun and concentrate thousands of megawatts of thermal solar flux onto a central molten-salt receiver tower to generate superheated steam for turbines', true, '21dc5a54-2cdd-48f8-83ac-989d0098d0d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9a8827d-56d8-47a2-8201-30b515f2b625', 'To produce cold water for cities', false, '21dc5a54-2cdd-48f8-83ac-989d0098d0d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('149b4c3f-57ef-4f1c-9f1c-eaa81a93d94b', 'To illuminate the night sky', false, '21dc5a54-2cdd-48f8-83ac-989d0098d0d4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('165ea863-3189-4fec-a4f4-7a3e6784ccdc', 'To reflect light away from the Earth', false, '21dc5a54-2cdd-48f8-83ac-989d0098d0d4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('921cc1dd-0e15-4364-8f5e-cd5f8ac8eedc', 'Class 7', 'Science', 'Chapter 11: Light', 'Hard', 'What grand unifying optical principle is established in Chapter 11 of NCERT Class 7 Science?', 'Chapter 11 establishes foundational geometric optics: rectilinear ray propagation, planar and spherical reflection/refraction, and chromatic dispersion.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08763a93-3d8d-4b2e-911b-5cc89e9898a8', 'Light—the primary medium of visual perception—governs rectilinear ray propagation, geometric reflection, refractive dispersion, and spherical image formation that underpins modern microscopy, vision correction, astronomical exploration, and solar energy technologies', true, '921cc1dd-0e15-4364-8f5e-cd5f8ac8eedc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7dabd71-79cd-49e8-b183-056aa0203084', 'That light has no physical laws', false, '921cc1dd-0e15-4364-8f5e-cd5f8ac8eedc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7b373f8-9106-4b0c-9a05-c93b5760daac', 'That colors exist only inside glass prisms', false, '921cc1dd-0e15-4364-8f5e-cd5f8ac8eedc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d06eeb70-7663-41ed-80b0-a5caf77667ba', 'That mirrors can only be made of silver', false, '921cc1dd-0e15-4364-8f5e-cd5f8ac8eedc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6425fafd-37b3-4d61-b6bd-89ff63786f15', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'In the exponential expression 10⁴, what is the BASE and what is the EXPONENT (Power)?', 'In aⁿ, ''a'' is the base that is repeatedly multiplied, and ''n'' is the exponent specifying how many times the base occurs as a factor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20aa44b1-dd01-473a-ac79-4a735398c4f1', 'Base = 10 and Exponent = 4', true, '6425fafd-37b3-4d61-b6bd-89ff63786f15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d617064-a086-45f6-826b-a30421a42eeb', 'Base = 4 and Exponent = 10', false, '6425fafd-37b3-4d61-b6bd-89ff63786f15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e546d0c8-d1db-48dd-afa7-905da3594646', 'Base = 40 and Exponent = 1', false, '6425fafd-37b3-4d61-b6bd-89ff63786f15');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8599ef4-0cbc-4514-9d9e-c81adf88c135', 'Base = 100 and Exponent = 4', false, '6425fafd-37b3-4d61-b6bd-89ff63786f15');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e0de98a-0011-45e7-87c7-e2cd6a297fce', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'What is the numerical value of 2⁶?', '2⁶ = 2 × 2 × 2 × 2 × 2 × 2 = 64.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b66250c-6a11-4e62-956a-17b2feb76eb9', '64 (2 × 2 × 2 × 2 × 2 × 2 = 64)', true, '5e0de98a-0011-45e7-87c7-e2cd6a297fce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56a008f7-f09d-4bb3-ac8e-f1eb07ad2698', '32', false, '5e0de98a-0011-45e7-87c7-e2cd6a297fce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a60e031-987c-4b1a-9590-a0cfafb77fc2', '12', false, '5e0de98a-0011-45e7-87c7-e2cd6a297fce');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56ba5d1f-34da-4e7f-be31-0caacdcf31e8', '128', false, '5e0de98a-0011-45e7-87c7-e2cd6a297fce');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3f299088-83dd-47b0-b339-ab7f5d095f14', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'Express 343 as a power of 7:', '343 = 7 × 49 = 7 × 7 × 7 = 7³.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb9d36a4-1298-4c37-b436-d7422e291d46', '7³ (7 × 7 × 7 = 49 × 7 = 343)', true, '3f299088-83dd-47b0-b339-ab7f5d095f14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f88d7a1-6f0e-49cc-b658-b941e2fdd262', '7⁴', false, '3f299088-83dd-47b0-b339-ab7f5d095f14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fce73f1a-87b6-4504-8ed1-7675bb255ffd', '7²', false, '3f299088-83dd-47b0-b339-ab7f5d095f14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09bdeb5c-cd8f-40e7-bbe6-08ba1d6db07a', '7⁵', false, '3f299088-83dd-47b0-b339-ab7f5d095f14');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1e87da8d-c733-48f1-8704-47b03fafb139', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'Which number is GREATER: 5³ or 3⁵?', '3⁵ = 243 and 5³ = 125; since 243 > 125, 3⁵ is greater.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98f8e48f-3671-45b7-986a-ecacf76f7d4f', '3⁵ is greater (3⁵ = 243, while 5³ = 125 ; 243 > 125)', true, '1e87da8d-c733-48f1-8704-47b03fafb139');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6976526-953d-411a-9360-ca3b4039677f', '5³ is greater', false, '1e87da8d-c733-48f1-8704-47b03fafb139');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d6373a4-6a1c-404b-8c1f-04f60d7b65dc', 'Both are equal', false, '1e87da8d-c733-48f1-8704-47b03fafb139');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e421d2e5-9c50-4fba-8c06-2b0ff72cd3b4', 'Cannot be determined', false, '1e87da8d-c733-48f1-8704-47b03fafb139');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('673403ee-5a0e-42a3-9d54-5a73ed5558a0', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'According to the Law of Exponents for MULTIPLICATION with the same base, what is (aᵐ × aⁿ) equal to?', 'Multiplication law of exponents: aᵐ × aⁿ = aᵐ⁺ⁿ.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('738c93e8-e4fd-495d-89f3-c01ef417a23a', 'aᵐ⁺ⁿ', true, '673403ee-5a0e-42a3-9d54-5a73ed5558a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('919e7fb4-9241-4ced-8c6f-ea819e042484', 'aᵐ⁻ⁿ', false, '673403ee-5a0e-42a3-9d54-5a73ed5558a0');
