INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d59a371-bd5c-4008-8bcc-ebc2cf135782', '(ab)ᵐ⁺ⁿ', false, '673403ee-5a0e-42a3-9d54-5a73ed5558a0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0f161c3-7354-42ef-9146-d81a5ce32d75', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'According to the Law of Exponents for DIVISION with the same base (where m > n), what is (aᵐ ÷ aⁿ) equal to?', 'Division law of exponents: aᵐ ÷ aⁿ = aᵐ⁻ⁿ.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f071c589-94a9-42a0-8d7d-143b2fe71957', 'aᵐ⁻ⁿ', true, 'd0f161c3-7354-42ef-9146-d81a5ce32d75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a030c583-2b57-427c-94ae-8f50c3f4865a', 'aᵐ⁺ⁿ', false, 'd0f161c3-7354-42ef-9146-d81a5ce32d75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d3e7d07-43af-4ab3-8d7f-7032f7766f69', 'aᵐ/ⁿ', false, 'd0f161c3-7354-42ef-9146-d81a5ce32d75');
