INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b460b253-ba77-4c1e-bbd2-0406024e02f1', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'What is (aᵐ)ⁿ (power of a power) equal to?', 'Power of a power rule: (aᵐ)ⁿ = aᵐⁿ.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0415fc6f-1a9c-4084-ab0e-8c00eec1732b', 'aᵐⁿ (a raised to the power m × n)', true, 'b460b253-ba77-4c1e-bbd2-0406024e02f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('981e4a86-ff51-47da-9818-5a96d326ddd2', 'aᵐ⁺ⁿ', false, 'b460b253-ba77-4c1e-bbd2-0406024e02f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adc442d3-4325-4c99-b711-74d41948275f', 'aᵐ⁻ⁿ', false, 'b460b253-ba77-4c1e-bbd2-0406024e02f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbe0a7aa-0910-4fab-a778-04665dc8744d', 'aᵐ/ⁿ', false, 'b460b253-ba77-4c1e-bbd2-0406024e02f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34397527-e3f9-4326-9e96-f63847f8366f', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'What is the value of any non-zero number raised to the power 0 (i.e. a⁰ where a ≠ 0)?', 'Zero exponent law: a⁰ = aᵐ⁻ᵐ = aᵐ / aᵐ = 1 for any non-zero base a.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45c665fc-cb1a-4190-94fe-12fa84c34eab', '1 (e.g. 7⁰ = 1, 100⁰ = 1, x⁰ = 1)', true, '34397527-e3f9-4326-9e96-f63847f8366f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('767dc9a3-179a-48a6-a313-9c7bbba1f8e8', '0', false, '34397527-e3f9-4326-9e96-f63847f8366f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be2a7fa6-1eb4-4c8a-aa79-50869c32115b', 'a', false, '34397527-e3f9-4326-9e96-f63847f8366f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7829a95d-b242-4f0a-90a8-42ad072c08d6', 'Infinity', false, '34397527-e3f9-4326-9e96-f63847f8366f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d41ab59c-f567-46f3-8bb9-9977295fdbd4', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'What is (-1) raised to an EVEN power (e.g. (-1)⁴, (-1)¹⁰⁰) equal to?', 'Negative one raised to any even natural power is always +1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('026d8b46-d940-4416-b487-b95a37bcff44', '+1', true, 'd41ab59c-f567-46f3-8bb9-9977295fdbd4');
