INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6b842fb-633d-40fd-b028-f37136932b1c', 'Even number', false, 'd41ab59c-f567-46f3-8bb9-9977295fdbd4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('173a44d9-15c1-4557-98f7-28300076855d', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'What is (-1) raised to an ODD power (e.g. (-1)³, (-1)⁵¹) equal to?', 'Negative one raised to any odd natural power is always -1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51edb56a-8c87-4ae8-9bb3-44bb221d268b', '-1', true, '173a44d9-15c1-4557-98f7-28300076855d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70587204-e4b6-4aba-9ed4-3aa72cca31de', '+1', false, '173a44d9-15c1-4557-98f7-28300076855d');
