INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ae6b5946-e4d8-4d44-a888-f02e9551f61c', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'Simplify: 3² × 3⁴ × 3⁸:', '3²⁺⁴⁺⁸ = 3¹⁴.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7e27ae0-ba22-4506-bf53-927501cf3ade', '3¹⁴ (3²⁺⁴⁺⁸ = 3¹⁴)', true, 'ae6b5946-e4d8-4d44-a888-f02e9551f61c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83609f81-0b7a-467c-8e64-d491b5e22ed2', '3⁶⁴', false, 'ae6b5946-e4d8-4d44-a888-f02e9551f61c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15f6da3b-44f4-4d84-9899-ea8809bdce97', '9¹⁴', false, 'ae6b5946-e4d8-4d44-a888-f02e9551f61c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acf255d6-85b6-477f-83b4-8140688a8924', '3¹⁶', false, 'ae6b5946-e4d8-4d44-a888-f02e9551f61c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('42ceb6bc-d031-4245-b14e-4d60e5179a4c', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Easy', 'Express the speed of light (300,000,000 m/s) in STANDARD SCIENTIFIC NOTATION:', 'Standard form: a number between 1.0 and 10.0 multiplied by a power of 10 → 3.0 × 10⁸ m/s.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e365c41c-0c85-4d4a-8eab-59fa48fc8e1f', '3.0 × 10⁸ m/s', true, '42ceb6bc-d031-4245-b14e-4d60e5179a4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9eea1e6-405c-4fd6-ba55-627140e65700', '30 × 10⁷ m/s', false, '42ceb6bc-d031-4245-b14e-4d60e5179a4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bf41035-b96d-4346-a68e-6b7d22058475', '0.3 × 10⁹ m/s', false, '42ceb6bc-d031-4245-b14e-4d60e5179a4c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b62eae4-677a-4ba4-baa4-ff7549733f97', '3.0 × 10⁶ m/s', false, '42ceb6bc-d031-4245-b14e-4d60e5179a4c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c212a55e-4c31-4d8d-a3b3-277a20c5f245', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Express 729 as a product of powers of prime factors in exponential form:', 'Prime factorization of 729 = 3⁶.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8572356a-078d-47be-8310-e5e17c547238', '3⁶ (729 = 3 × 3 × 3 × 3 × 3 × 3 = 3⁶)', true, 'c212a55e-4c31-4d8d-a3b3-277a20c5f245');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd733e60-8e46-473b-b9e0-8fcc3ec1d77e', '9³', false, 'c212a55e-4c31-4d8d-a3b3-277a20c5f245');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b912e9aa-f1f7-4d14-a9b4-5287433a981f', '3⁵ × 2', false, 'c212a55e-4c31-4d8d-a3b3-277a20c5f245');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac68af3d-447f-44b3-9b2e-7647af487983', '27²', false, 'c212a55e-4c31-4d8d-a3b3-277a20c5f245');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c81992b-7c47-429d-97d5-2f62d23991d6', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Express 108 × 192 as a product of prime factors only in exponential form:', '108 = 2² × 3³; 192 = 2⁶ × 3¹. Combined product = 2⁸ × 3⁴.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('60c60feb-38f3-4a89-a675-305b087685dc', '2⁸ × 3⁴ (108 = 2² × 3³ ; 192 = 2⁶ × 3¹ ; Product = 2²⁺⁶ × 3³⁺¹ = 2⁸ × 3⁴)', true, '4c81992b-7c47-429d-97d5-2f62d23991d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dde28dd0-ce3b-44f1-9736-b5201670d136', '2⁷ × 3⁵', false, '4c81992b-7c47-429d-97d5-2f62d23991d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('79d87008-318a-4ecb-8970-c998e29ec655', '2⁶ × 3⁴', false, '4c81992b-7c47-429d-97d5-2f62d23991d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78eccd81-dcea-4b99-910f-e3327bc4ff52', '2⁸ × 3⁵', false, '4c81992b-7c47-429d-97d5-2f62d23991d6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('162bc0f1-2976-4fe9-9a61-d214de221cea', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Simplify and write in exponential form: (2²⁰ ÷ 2¹⁵) × 2³:', '2²⁰⁻¹⁵ × 2³ = 2⁵ × 2³ = 2⁸.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78258c41-2197-46f6-9915-13c47ba03f4a', '2⁸ ((2²⁰⁻¹⁵) × 2³ = 2⁵ × 2³ = 2⁵⁺³ = 2⁸ = 256)', true, '162bc0f1-2976-4fe9-9a61-d214de221cea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f394d08d-c085-41d4-997b-684b9ee85b24', '2⁵', false, '162bc0f1-2976-4fe9-9a61-d214de221cea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1a8e4ff-cab0-4e94-921c-596b4f2ff9e0', '2¹⁰', false, '162bc0f1-2976-4fe9-9a61-d214de221cea');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c16d1d75-2445-4fd4-a5cc-3a6b6defe704', '2⁶', false, '162bc0f1-2976-4fe9-9a61-d214de221cea');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47bfb3bb-2432-4130-901a-7511c8aae608', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Simplify: (3⁰ + 2⁰) × 5⁰:', '3⁰ = 1, 2⁰ = 1, 5⁰ = 1 → (1 + 1) × 1 = 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f8669ee-cbcf-4785-a24a-d957f17cf752', '2 ((1 + 1) × 1 = 2 × 1 = 2)', true, '47bfb3bb-2432-4130-901a-7511c8aae608');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d08cb759-a364-41c9-885b-76969605f571', '1', false, '47bfb3bb-2432-4130-901a-7511c8aae608');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9b1b94f-57de-4464-a1a8-90f8f7c183c2', '0', false, '47bfb3bb-2432-4130-901a-7511c8aae608');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9919aa06-0651-49e8-800b-274cb4cfc155', '6', false, '47bfb3bb-2432-4130-901a-7511c8aae608');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('437a4833-6df7-4a45-aa1c-a1536a240d44', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Simplify: (3⁷ / (3⁴ × 3³)):', '3⁷ / 3⁷ = 3⁰ = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d64b0df8-fa42-434f-87bb-2b2fa62ce956', '1 (3⁷ / 3⁴⁺³ = 3⁷ / 3⁷ = 3⁷⁻⁷ = 3⁰ = 1)', true, '437a4833-6df7-4a45-aa1c-a1536a240d44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0fb2f07-1eca-46cb-9f71-8a589d1a7f79', '3', false, '437a4833-6df7-4a45-aa1c-a1536a240d44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e84c6f8e-547e-478b-bfa9-61ad7e3f76e7', '0', false, '437a4833-6df7-4a45-aa1c-a1536a240d44');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a61716c-1c9c-4735-aba8-cd650709c5dc', '9', false, '437a4833-6df7-4a45-aa1c-a1536a240d44');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f7de797b-80cb-4fb7-84ed-562e0706bc57', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Simplify and express in exponential form: (2³ × 3⁴ × 4) / (3 × 32):', '(2⁵ × 3⁴) / (2⁵ × 3¹) = 2⁰ × 3³ = 3³ = 27.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b65f9850-6388-436f-a44d-9c49d36fb4ee', '3³ (4 = 2² ; 32 = 2⁵ ; Numerator = 2³ × 2² × 3⁴ = 2⁵ × 3⁴ ; Denominator = 2⁵ × 3¹ ; Value = 2⁵⁻⁵ × 3⁴⁻¹ = 2⁰ × 3³ = 1 × 3³ = 3³ = 27)', true, 'f7de797b-80cb-4fb7-84ed-562e0706bc57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c87fe232-476b-4fa3-9a39-20a6065eb078', '3⁴', false, 'f7de797b-80cb-4fb7-84ed-562e0706bc57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68cfa056-1d1e-46a8-98d0-62bf9d417e1b', '2³ × 3²', false, 'f7de797b-80cb-4fb7-84ed-562e0706bc57');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4da2c2d8-7477-45dc-ad8c-ec237da0d33e', '3²', false, 'f7de797b-80cb-4fb7-84ed-562e0706bc57');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9eea2c36-b70d-425b-b613-9b5c9a36bb1a', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Simplify: (2⁸ × a⁵) / (4³ × a³):', '4³ = 2⁶. Result = 2⁸⁻⁶ × a⁵⁻³ = 2²a² = 4a².', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e2f506f-49ea-4755-a375-7ac3ab2417ea', '4a² or 2²a² (4³ = (2²)³ = 2⁶ ; Expression = (2⁸ / 2⁶) × (a⁵ / a³) = 2⁸⁻⁶ × a⁵⁻³ = 2² × a² = 4a²)', true, '9eea2c36-b70d-425b-b613-9b5c9a36bb1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4267879b-7acc-46fd-a893-16dea672a327', '2a²', false, '9eea2c36-b70d-425b-b613-9b5c9a36bb1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc701f41-1539-45db-9b7f-53a4e5e7f733', '8a³', false, '9eea2c36-b70d-425b-b613-9b5c9a36bb1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efd2bc28-72a0-48c3-a519-f1fa41f03e10', '2⁴a²', false, '9eea2c36-b70d-425b-b613-9b5c9a36bb1a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c0d9ffac-76cb-4d21-a35b-329d87b00319', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Expand the number 279,404 in expanded decimal exponential notation:', '279,404 = 2×10⁵ + 7×10⁴ + 9×10³ + 4×10² + 0×10¹ + 4×10⁰.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d70cd610-2e8f-497c-bbc5-34de62edf234', '2 × 10⁵ + 7 × 10⁴ + 9 × 10³ + 4 × 10² + 0 × 10¹ + 4 × 10⁰', true, 'c0d9ffac-76cb-4d21-a35b-329d87b00319');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a53f56a0-c9cf-4ab0-a4b8-1947c499a9a5', '2 × 10⁴ + 7 × 10³ + 9 × 10² + 4 × 10¹ + 4 × 10⁰', false, 'c0d9ffac-76cb-4d21-a35b-329d87b00319');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54d2a754-db7f-422f-b839-d8ee58d5ac98', '2 × 10⁶ + 7 × 10⁵ + 9 × 10⁴ + 4 × 10³ + 4 × 10²', false, 'c0d9ffac-76cb-4d21-a35b-329d87b00319');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3efc99f-1f50-426a-95a0-2b32a37c0a2f', '279 × 10³ + 404', false, 'c0d9ffac-76cb-4d21-a35b-329d87b00319');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e8abc08-446e-4a28-bda9-997bfef88072', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Find the number from the expanded form: 8 × 10⁴ + 6 × 10³ + 0 × 10² + 4 × 10¹ + 5 × 10⁰:', '80,000 + 6,000 + 0 + 40 + 5 = 86,045.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acaaee96-615c-45a1-9d97-b49054183edc', '86,045', true, '6e8abc08-446e-4a28-bda9-997bfef88072');
