INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5881fd60-2d46-4922-b9f3-e442e7e28c66', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'The distance between Sun and Earth is 149,600,000,000 metres. Express this distance in STANDARD SCIENTIFIC FORM:', '149,600,000,000 = 1.496 × 10¹¹ m.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59f0385d-6b1b-4991-9612-c5c284e9ac8f', '1.496 × 10¹¹ m', true, '5881fd60-2d46-4922-b9f3-e442e7e28c66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('43bc1bd2-e001-4a22-8fff-dedaeb212305', '14.96 × 10¹⁰ m', false, '5881fd60-2d46-4922-b9f3-e442e7e28c66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('386586d3-e4ea-4acb-a113-5cf74fbe771d', '149.6 × 10⁹ m', false, '5881fd60-2d46-4922-b9f3-e442e7e28c66');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1f83eb8-48ef-4747-bfd8-6c22cfc6226d', '1.496 × 10¹² m', false, '5881fd60-2d46-4922-b9f3-e442e7e28c66');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f32ee741-f728-4f88-95b3-d4862f231576', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'The population of India in a census was approximately 1,350,000,000. Express it in scientific standard form:', '1,350,000,000 = 1.35 × 10⁹.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91edd863-1d8c-492f-ab28-cb856f5864f2', '1.35 × 10⁹', true, 'f32ee741-f728-4f88-95b3-d4862f231576');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ee4e265-fe51-4ddb-8e20-bd2a962ca9bb', '13.5 × 10⁸', false, 'f32ee741-f728-4f88-95b3-d4862f231576');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de2504da-1f71-40ae-a7f6-7ef246b4461d', '135 × 10⁷', false, 'f32ee741-f728-4f88-95b3-d4862f231576');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('556d9035-bf8d-4c4d-bd9e-478d6543543f', '1.35 × 10¹⁰', false, 'f32ee741-f728-4f88-95b3-d4862f231576');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe3df2dc-6cc5-4783-b474-8e480fdf2650', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Compare the numbers: 2.7 × 10¹² and 1.5 × 10⁸:', 'Comparing exponents: 10¹² >> 10⁸, so 2.7 × 10¹² is roughly 18,000 times larger.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28d57b32-a368-463e-8016-f45207e7da50', '2.7 × 10¹² is vastly GREATER than 1.5 × 10⁸ (since 10¹² is 10,000 times larger than 10⁸)', true, 'fe3df2dc-6cc5-4783-b474-8e480fdf2650');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8268e0f-ed90-49f4-88a0-0d6b9327faae', '1.5 × 10⁸ is greater', false, 'fe3df2dc-6cc5-4783-b474-8e480fdf2650');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba19020e-ec11-4631-a851-8c6ade98a11e', 'Both are approximately equal', false, 'fe3df2dc-6cc5-4783-b474-8e480fdf2650');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aaa2e077-79a8-4396-8c99-d2313e19f6f6', 'Cannot be compared without full expansion', false, 'fe3df2dc-6cc5-4783-b474-8e480fdf2650');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('97665498-759d-4376-a628-75e26064d6fe', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Simplify: ((5²)³ × 5⁴) ÷ 5⁷:', '5⁶⁺⁴⁻⁷ = 5³ = 125.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13303d33-9112-4917-8d8f-e66be21581dd', '5³ or 125 ((5⁶ × 5⁴) ÷ 5⁷ = 5⁶⁺⁴ ÷ 5⁷ = 5¹⁰ ÷ 5⁷ = 5¹⁰⁻⁷ = 5³ = 125)', true, '97665498-759d-4376-a628-75e26064d6fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df91f845-fa50-4f27-a702-7b38410aea09', '5²', false, '97665498-759d-4376-a628-75e26064d6fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d39635fa-e953-421b-a954-d36ab2255033', '5⁵', false, '97665498-759d-4376-a628-75e26064d6fe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf1c35c7-7600-4533-aa8f-f183330c42e3', '1', false, '97665498-759d-4376-a628-75e26064d6fe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77a3c982-8646-4dff-b988-b5552572864b', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Simplify: (25 × 5² × t⁸) / (10³ × t⁴):', '(5⁴ × t⁸) / (2³ × 5³ × t⁴) = (5⁴⁻³ / 2³) × t⁸⁻⁴ = (5/8) t⁴.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8a60ee0-72d8-4b17-a9b1-aaf4e525b244', '(5 / 8) t⁴ (25 × 5² = 5² × 5² = 5⁴ = 625 ; 10³ = (2×5)³ = 2³ × 5³ = 8 × 125 = 1000 ; 625/1000 = 5/8 ; t⁸/t⁴ = t⁴)', true, '77a3c982-8646-4dff-b988-b5552572864b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('78c7a7d7-b484-46d2-8dab-b59737c0cf1d', '(5 / 4) t⁴', false, '77a3c982-8646-4dff-b988-b5552572864b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33f1be86-a96b-4d1b-8e59-1c1fb907873f', '(1 / 8) t⁴', false, '77a3c982-8646-4dff-b988-b5552572864b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7b32457-471f-4d76-a258-7c2a9d6fb7ef', '5t⁴', false, '77a3c982-8646-4dff-b988-b5552572864b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b9709c7-e458-4485-a730-bd22196f283c', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'Simplify: (3⁵ × 10⁵ × 25) / (5⁷ × 6⁵):', '(3⁵ × 2⁵ × 5⁷) / (3⁵ × 2⁵ × 5⁷) = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24df36b6-22d9-48d4-8913-8c0d623151ce', '1 (10⁵ = (2×5)⁵ = 2⁵ × 5⁵ ; 25 = 5² ; 6⁵ = (2×3)⁵ = 2⁵ × 3⁵ ; Numerator = 3⁵ × 2⁵ × 5⁵⁺² = 3⁵ × 2⁵ × 5⁷ ; Denominator = 5⁷ × 2⁵ × 3⁵ ; Value = 1)', true, '0b9709c7-e458-4485-a730-bd22196f283c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1e9aca7-dc08-46f6-adc1-00c7fa394dd9', '5', false, '0b9709c7-e458-4485-a730-bd22196f283c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eaa9d5a1-f44a-4983-b5c6-39bfb643e9f7', '0', false, '0b9709c7-e458-4485-a730-bd22196f283c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7facbba5-53be-4c68-af85-1ba1cef6800f', '10', false, '0b9709c7-e458-4485-a730-bd22196f283c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('016c6cf7-9866-466f-91a9-8d60a0b4df16', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Medium', 'If 2ⁿ = 128, find the value of n:', '2⁷ = 2 × 2 × 2 × 2 × 2 × 2 × 2 = 128, so n = 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a8f1625-b3dd-4f07-ae6e-ebacaa392c3a', 'n = 7 (2⁷ = 128)', true, '016c6cf7-9866-466f-91a9-8d60a0b4df16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d73a23b-ae1b-4eb5-a77f-a632fa45068b', 'n = 6', false, '016c6cf7-9866-466f-91a9-8d60a0b4df16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15d29cec-13c9-48cc-9f83-39b881c2c8b1', 'n = 8', false, '016c6cf7-9866-466f-91a9-8d60a0b4df16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11e6d351-3159-4516-a9c1-0ee790d133d8', 'n = 5', false, '016c6cf7-9866-466f-91a9-8d60a0b4df16');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bc38658d-2f6d-49e8-bbcd-235b77820c5f', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88e738c7-4e97-46d9-a46e-35f044640a46', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'bc38658d-2f6d-49e8-bbcd-235b77820c5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('511c1b24-6cbc-4b5c-b75c-c2ba33c77145', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'bc38658d-2f6d-49e8-bbcd-235b77820c5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11080c00-f052-4619-b0c7-0ff5e9bb8d57', '(A) is true, but (R) is false.', false, 'bc38658d-2f6d-49e8-bbcd-235b77820c5f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('20ddc34b-8fb7-4301-8b83-6d2017134220', '(A) is false, but (R) is true.', false, 'bc38658d-2f6d-49e8-bbcd-235b77820c5f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8bc5feb2-058f-4a70-aef5-c887782bbbd0', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'Spot the IMPOSTER in the following applications of Laws of Exponents:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cfd0d38-e9ae-4761-b19f-7ab62144e9e6', 'Application 1', false, '8bc5feb2-058f-4a70-aef5-c887782bbbd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('980390d4-2093-4996-b435-7c1fa1826307', 'Application 2', false, '8bc5feb2-058f-4a70-aef5-c887782bbbd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58632d55-da5c-47bc-b22b-03ce81965c0b', 'Application 3', false, '8bc5feb2-058f-4a70-aef5-c887782bbbd0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a818270c-a611-427a-9d4e-125688fd7258', 'Application 4 (2³ + 2⁴ = 8 + 16 = 24, whereas 2⁷ = 128 ; Exponents cannot be added under ADDITION)', true, '8bc5feb2-058f-4a70-aef5-c887782bbbd0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1d1d0e46-0e81-4550-a43e-12ad7fc641a0', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'If (2/9)³ × (2/9)⁻⁶ = (2/9)²ᵐ⁻¹, find the value of ''m'':', '3 - 6 = 2m - 1 → -3 = 2m - 1 → 2m = -2 → m = -1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d95f427-f289-4c34-a7fe-c2e7ede33c08', 'm = -1 (LHS = (2/9)³⁺⁽⁻⁶⁾ = (2/9)⁻³ ; Equating exponents: 2m - 1 = -3 ⇒ 2m = -2 ⇒ m = -1)', true, '1d1d0e46-0e81-4550-a43e-12ad7fc641a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fbeefa7-fe2d-4e87-9cda-446343d154c3', 'm = 1', false, '1d1d0e46-0e81-4550-a43e-12ad7fc641a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecad2755-0271-481d-8aa8-6568cfd63085', 'm = -2', false, '1d1d0e46-0e81-4550-a43e-12ad7fc641a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbd93df8-91c2-4b6b-8daa-9481f381f9cd', 'm = 0', false, '1d1d0e46-0e81-4550-a43e-12ad7fc641a0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0640018-a2ea-44c8-ba52-aa913893cfc6', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'Match Column I (Exponential Expressions) with Column II (Simplified Values):
(a) (-2)³ × (-10)³ -> (i) 8,000 ((-8) × (-1000) = 8,000)
(b) (-3)² × (-5)²  -> (ii) 225 (9 × 25 = 225)
(c) 0 × 10²⁰       -> (iii) 0
(d) (-1)⁵⁰⁰        -> (iv) +1', '(-2)³(-10)³ = 8000; (-3)²(-5)² = 225; 0×10²⁰ = 0; (-1)⁵⁰⁰ = 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47fe1442-bbb4-4527-b6ab-939df75f2b6c', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'd0640018-a2ea-44c8-ba52-aa913893cfc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fdeeee4-d98f-4e26-8593-516fbe2a14f1', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'd0640018-a2ea-44c8-ba52-aa913893cfc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca219e76-3986-4c0b-9b76-335a89deacae', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'd0640018-a2ea-44c8-ba52-aa913893cfc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8990c7af-f448-4221-8ce6-a7e6dad64f42', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'd0640018-a2ea-44c8-ba52-aa913893cfc6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e0ad417f-2862-4782-8e3d-ae3ee0c22e4b', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'Read the statements regarding exponential sizes:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fc59d93-bbed-4f83-a9e0-d1e44eb62f23', 'Statements 1 and 2 only', true, 'e0ad417f-2862-4782-8e3d-ae3ee0c22e4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02abe240-54cd-4160-8c08-c1ae7a66cdea', 'Statements 2 and 3 only', false, 'e0ad417f-2862-4782-8e3d-ae3ee0c22e4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2adf6737-5504-4adf-b04d-fd11d02c719a', 'Statements 1 and 3 only', false, 'e0ad417f-2862-4782-8e3d-ae3ee0c22e4b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fca9182a-ff11-4a2a-825c-6f388513d0ee', 'All Statements 1, 2, and 3', false, 'e0ad417f-2862-4782-8e3d-ae3ee0c22e4b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('70bca140-7370-43c2-958e-72be27fb033c', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'Evaluate the expression:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cfdf87b-678c-4a16-8a96-af1a60b4611a', '-9 ((-2)⁴ = 16 ; 3² = 9 ; 5⁰ = 1 ; Numerator = 16 × 9 × 1 = 144 ; Denominator = 16 × (-1) = -16 ; Value = 144 / -16 = -9)', true, '70bca140-7370-43c2-958e-72be27fb033c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bdb5252c-d1c7-4810-b1a7-8ab473ee32d3', '+9', false, '70bca140-7370-43c2-958e-72be27fb033c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa63a6ad-18f2-4e68-9456-36dd88cfb000', '-16', false, '70bca140-7370-43c2-958e-72be27fb033c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69e5284b-c5a4-4a56-bdae-0afd0c7aa9de', '0', false, '70bca140-7370-43c2-958e-72be27fb033c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5e5a025c-9f73-475d-bbd0-15d86f90f66f', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'If 5²ˣ⁺¹ ÷ 25 = 125, find the value of x:', '5²ˣ⁻¹ = 5³ → 2x - 1 = 3 → 2x = 4 → x = 2.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d423fcf-94b5-4930-b07b-dc3cd4c83d57', 'x = 2 (5²ˣ⁺¹ ÷ 5² = 5²ˣ⁺¹⁻² = 5²ˣ⁻¹ ; 125 = 5³ ; 2x - 1 = 3 ⇒ 2x = 4 ⇒ x = 2)', true, '5e5a025c-9f73-475d-bbd0-15d86f90f66f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8983ca12-9bb2-4e7e-9736-ce5460f37abe', 'x = 1', false, '5e5a025c-9f73-475d-bbd0-15d86f90f66f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbfc2bf0-090c-4524-b943-d780ef292852', 'x = 3', false, '5e5a025c-9f73-475d-bbd0-15d86f90f66f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16db58cc-81c9-4e1d-bc10-c0f2639ea330', 'x = 4', false, '5e5a025c-9f73-475d-bbd0-15d86f90f66f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bee6e5ed-87cc-4dbd-ab7e-422c9822b663', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'Express (3.2 × 10⁶) + (4.5 × 10⁵) in standard scientific form:', '3.2 × 10⁶ + 0.45 × 10⁶ = 3.65 × 10⁶.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac5c2edc-1e49-44a1-8ebf-b92727b98bf1', '3.65 × 10⁶ (Convert to matching exponent: 4.5 × 10⁵ = 0.45 × 10⁶ ; Sum = (3.2 + 0.45) × 10⁶ = 3.65 × 10⁶)', true, 'bee6e5ed-87cc-4dbd-ab7e-422c9822b663');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('779252a8-b836-4ab8-80f6-30826ea69114', '7.7 × 10¹¹', false, 'bee6e5ed-87cc-4dbd-ab7e-422c9822b663');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09ef916d-c414-4092-bd42-43d23dfdbc41', '7.7 × 10⁶', false, 'bee6e5ed-87cc-4dbd-ab7e-422c9822b663');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51c401ce-dc25-4128-8bd7-2d9b4c6cfe11', '3.65 × 10⁷', false, 'bee6e5ed-87cc-4dbd-ab7e-422c9822b663');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7a64f484-dc80-4322-94b9-5eecdbc8d689', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'If 3⁴ × 2⁵ × a = 12⁴, what is the value of ''a''?', '12⁴ = (3 × 4)⁴ = 3⁴ × 2⁸. LHS = 3⁴ × 2⁵ × a. Hence a = 2⁸ / 2⁵ = 2³ = 8.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72419c0e-0d09-4719-a02b-a590819273fc', 'a = 16 or 2⁴ (12⁴ = (3 × 2²)⁴ = 3⁴ × 2⁸ ; LHS = 3⁴ × 2⁵ × a ; Equating: 3⁴ × 2⁵ × a = 3⁴ × 2⁸ ⇒ a = 2⁸⁻⁵ = 2³ = 8 ... wait: (2²)⁴ = 2⁸ ; 2⁸ / 2⁵ = 2³ = 8)', false, '7a64f484-dc80-4322-94b9-5eecdbc8d689');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('130fba0e-aca4-4c4b-8de3-a1744f251fb2', 'a = 8 (2³ = 8)', true, '7a64f484-dc80-4322-94b9-5eecdbc8d689');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ecb56f1-cfd5-4ef6-9ca9-fac1d40dc9a9', 'a = 4', false, '7a64f484-dc80-4322-94b9-5eecdbc8d689');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52b4e69c-0aee-44da-880d-0294ffad0ebc', 'a = 2', false, '7a64f484-dc80-4322-94b9-5eecdbc8d689');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('15a23f85-c6c3-40c8-829a-69996469162f', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'A digital memory card has a capacity of 64 Gigabytes (GB). If 1 GB = 2³⁰ bytes, how many bytes of data can the card store in pure power of 2?', '64 × 2³⁰ = 2⁶ × 2³⁰ = 2³⁶ bytes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('894e6bc1-104b-48a6-8515-109e58df8170', '2³⁶ bytes (64 = 2⁶ ; Capacity = 2⁶ × 2³⁰ = 2⁶⁺³⁰ = 2³⁶ bytes)', true, '15a23f85-c6c3-40c8-829a-69996469162f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98bb39bf-ab0f-483b-a4a5-36b0662d3e9a', '2³⁴ bytes', false, '15a23f85-c6c3-40c8-829a-69996469162f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16507738-23fc-4297-a4d6-9663560df119', '2⁴⁰ bytes', false, '15a23f85-c6c3-40c8-829a-69996469162f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('573d16e8-be6d-4d0c-8152-a7c5aba080d7', '2³² bytes', false, '15a23f85-c6c3-40c8-829a-69996469162f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e5d4bd33-a987-4119-bde9-159460dc8f1b', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'Simplify: (a³b²c⁴)³ ÷ (a²bc³)²:', 'a⁹⁻⁴ b⁶⁻² c¹²⁻⁶ = a⁵b⁴c⁶.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd96cf6e-2293-4bde-b0dd-4eb0a906065f', 'a⁵b⁴c⁶ (Numerator = a⁹b⁶c¹² ; Denominator = a⁴b²c⁶ ; Quotient = a⁹⁻⁴ b⁶⁻² c¹²⁻⁶ = a⁵b⁴c⁶)', true, 'e5d4bd33-a987-4119-bde9-159460dc8f1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27aa2e36-b0c1-495d-90d4-5a8a83d06fac', 'a⁷b⁴c⁵', false, 'e5d4bd33-a987-4119-bde9-159460dc8f1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77bcbbeb-03dc-40f7-8c3b-502717916098', 'a⁵b²c⁶', false, 'e5d4bd33-a987-4119-bde9-159460dc8f1b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a6dc1fd-bf29-41f5-8b5a-ebb0917d347d', 'a⁶b⁴c⁶', false, 'e5d4bd33-a987-4119-bde9-159460dc8f1b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('01fc1297-f065-4617-bfbc-3caad093a96c', 'Class 7', 'Mathematics', 'Chapter 11: Exponents and Powers', 'Hard', 'Why is Exponential Notation and Standard Form indispensable across modern science, computer science, and astrophysics?', 'Exponential standard notation compresses extreme dynamic ranges spanning subatomic particle scales to cosmic galactic dimensions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a3e53d2-9a0e-4de6-8fa5-ec202871dd8d', 'It enables astronomical cosmic scales (like the mass of galaxies 10⁴² kg) and subatomic quantum scales (like Planck length 10⁻³⁵ m) to be written concisely, computed without errors, and manipulated systematically', true, '01fc1297-f065-4617-bfbc-3caad093a96c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4d5df5f-19ee-4542-be15-db33a5dc4ea8', 'Because zero takes too long to type', false, '01fc1297-f065-4617-bfbc-3caad093a96c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70c03766-77c2-4e64-8318-5b168206a271', 'Because calculators cannot display numbers without exponents', false, '01fc1297-f065-4617-bfbc-3caad093a96c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0939c5ae-07d3-438e-9dd6-c90b065ecea9', 'Because ordinary multiplication is banned in physics', false, '01fc1297-f065-4617-bfbc-3caad093a96c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fab92a3a-c55f-44d7-aaad-4551b9388d74', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'Who is the author of the celebrated science-fiction story ''An Alien Hand''?', 'Eminent Indian astrophysicist and science-fiction writer Dr. Jayant Narlikar authored ''An Alien Hand''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6e4ab43-853b-40e6-8107-4895559a65c9', 'Jayant Narlikar', true, 'fab92a3a-c55f-44d7-aaad-4551b9388d74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('733bbbc8-4e60-4c47-b3a7-96c0a61c23ce', 'Ruskin Bond', false, 'fab92a3a-c55f-44d7-aaad-4551b9388d74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05e5f1ed-e35e-40b2-ac3e-c38594893d5a', 'Satyajit Ray', false, 'fab92a3a-c55f-44d7-aaad-4551b9388d74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd6b3353-6f12-4550-b552-a725dc85d7fb', 'R.K. Narayan', false, 'fab92a3a-c55f-44d7-aaad-4551b9388d74');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('196f248a-dfc6-4adc-96db-bb1bebcb4ee1', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'Where do Tilloo and his family live in the story ''An Alien Hand''?', 'Tilloo and his parents reside in an underground subterranean habitat on Mars equipped with artificial life-support systems.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('826267b9-04d2-452a-a2fa-537b89fc85af', 'In a technologically advanced underground colony beneath the surface of the planet Mars', true, '196f248a-dfc6-4adc-96db-bb1bebcb4ee1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa610ff0-5f1b-48c1-a3bb-cf019f6a8264', 'On planet Earth in a cave', false, '196f248a-dfc6-4adc-96db-bb1bebcb4ee1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d2fc8fa-d3e6-4310-b588-354179cc1560', 'On the Moon inside a glass dome', false, '196f248a-dfc6-4adc-96db-bb1bebcb4ee1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('644b8c72-6667-4788-8ba7-311e76744172', 'On a space station orbiting Jupiter', false, '196f248a-dfc6-4adc-96db-bb1bebcb4ee1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88013d3d-ac19-42ef-9a80-d9093b8db213', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'Why were the inhabitants of Mars forced to abandon the surface and live underground?', 'Solar atmospheric cooling degraded the Martian surface environment, compelling the survivors to build subterranean biospheres.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef662fe3-5048-4a32-a18e-ff4f71ea08fa', 'The Sun grew hostile and cooled down, upsetting the delicate planetary climate and extinguishing surface life, water, and breathable atmosphere', true, '88013d3d-ac19-42ef-9a80-d9093b8db213');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('560d5314-3e19-423b-8bde-339baf7e817f', 'A foreign army attacked them', false, '88013d3d-ac19-42ef-9a80-d9093b8db213');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f21ca07-bd51-45a4-83ca-f24a4de3d55f', 'A flood drowned the planet', false, '88013d3d-ac19-42ef-9a80-d9093b8db213');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('469b512d-26c4-431c-8db4-a4ab7c4606b2', 'They loved living in tunnels', false, '88013d3d-ac19-42ef-9a80-d9093b8db213');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f02cf72e-6b2b-4601-a153-5cc1960c76e1', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'How did Tilloo''s father travel to work each day through the forbidden underground passage?', 'Tilloo''s father used an electronic security card (keycard) to unlock the sealed metal security doors leading to the surface passage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27e394ff-b557-4785-9f5b-49a2ac6e55a7', 'By swiping a specialized electronic security access card into the automatic door slot', true, 'f02cf72e-6b2b-4601-a153-5cc1960c76e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c99e586b-94b0-4bc0-95d0-fa8a3b32aff7', 'By speaking a magic password', false, 'f02cf72e-6b2b-4601-a153-5cc1960c76e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ce312c9-776d-4a66-9d28-290bcee4cd6f', 'By using a heavy iron key', false, 'f02cf72e-6b2b-4601-a153-5cc1960c76e1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b14c9796-f4cb-424b-8d42-107df35dda5b', 'By climbing a rope ladder', false, 'f02cf72e-6b2b-4601-a153-5cc1960c76e1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('400b5305-3787-447d-a939-51061456b389', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'What happened when curious Tilloo secretly took his father''s security card and entered the forbidden surface passage?', 'Automated biometric sensors detected Tilloo''s unauthorized entry, alerting security guards who safely returned him to his mother.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64244bfa-1641-450e-96bd-793ba10531e4', 'Hidden surveillance sensors and mechanical security devices detected him, photographed him, and security guards escorted him back home', true, '400b5305-3787-447d-a939-51061456b389');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cbaa7ee-17bf-4750-a45d-45af752789a6', 'He reached Earth in a rocket', false, '400b5305-3787-447d-a939-51061456b389');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a280e2f-f76e-45eb-8bcb-8ab3a75ae6b0', 'He was lost forever in the dark', false, '400b5305-3787-447d-a939-51061456b389');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f3c46dff-a550-44df-b7e7-80736f641de5', 'He found buried treasure', false, '400b5305-3787-447d-a939-51061456b389');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1924dcc5-a492-4043-9a41-68bf6136faed', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'What special equipment is necessary for Martian scientists to survive while working on the hostile surface of Mars?', 'Mars surface survival mandates an airtight spacesuit for thermal protection, pressure balance, and supplemental oxygen supply.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d529a29-7d86-4b17-a660-a1b740fd7188', 'A pressurized protective spacesuit with boots and an oxygen reservoir pack to withstand freezing cold and thin air', true, '1924dcc5-a492-4043-9a41-68bf6136faed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a37d9c6a-682c-447f-b2e8-d7647c669ce1', 'A warm woolen coat only', false, '1924dcc5-a492-4043-9a41-68bf6136faed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('983b4575-2762-459d-b42d-21b20339bf90', 'An umbrella and sunglasses', false, '1924dcc5-a492-4043-9a41-68bf6136faed');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc2302e7-5f03-4f8b-a1b1-fe17e258849d', 'Ordinary leather clothes', false, '1924dcc5-a492-4043-9a41-68bf6136faed');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('26f0a70c-ad08-4a31-8cae-db65c01e95cb', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'What unexpected celestial event created widespread commotion in the Martian Central Control Room?', 'The Central Control Room radar detected two unmanned interplanetary probes (NASA''s Viking orbiters/landers) heading toward Mars.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c5bdb00-81ec-4418-8a67-6bd1643c1c85', 'Two alien unmanned spacecraft approaching Mars from an unknown origin (Earth)', true, '26f0a70c-ad08-4a31-8cae-db65c01e95cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de32fb2c-c0be-4047-b2d2-7e060c4f346d', 'An asteroid colliding with the Sun', false, '26f0a70c-ad08-4a31-8cae-db65c01e95cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61b085d0-83c6-4b66-92f5-b17c719b3deb', 'A volcanic eruption underground', false, '26f0a70c-ad08-4a31-8cae-db65c01e95cb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3970222d-c70e-4517-b6be-0710e81a42ca', 'A complete electrical power blackout', false, '26f0a70c-ad08-4a31-8cae-db65c01e95cb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e70b80c-2fdf-4f04-9c5f-da564191085d', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'What mechanical part emerged from the landed alien spacecraft onto the Martian soil?', 'The Viking lander extended a telescopic mechanical sampler arm (an ''alien hand'') to scoop regolith soil for biological analysis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19e4c96f-8b84-4df2-ba97-2cf8484f280c', 'A metallic mechanical robotic arm (the ''alien hand'') reaching down to collect Martian soil samples', true, '6e70b80c-2fdf-4f04-9c5f-da564191085d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a285886b-bfae-4a81-83ec-703f9ef0dbb3', 'A laser gun', false, '6e70b80c-2fdf-4f04-9c5f-da564191085d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac960964-cf72-488f-a4c5-2edfe5c36a79', 'A giant video camera', false, '6e70b80c-2fdf-4f04-9c5f-da564191085d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7a7f2f9-fec9-4b3d-8c87-815061db8e73', 'A flag pole only', false, '6e70b80c-2fdf-4f04-9c5f-da564191085d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('656c2b7a-7689-4c0a-a21d-c6a213dcfad0', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'What irresistible object on the Control Room panel caught young Tilloo''s eye when he visited with his father?', 'A bright, prominent red button on the control console fascinated Tilloo, tempting his childish curiosity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a863815-c84a-46a6-8e96-9e0e1bfd421d', 'A prominent, glowing RED BUTTON on the control console', true, '656c2b7a-7689-4c0a-a21d-c6a213dcfad0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ecd9f802-3f74-48ea-b722-897b53f7d7fc', 'A bright green light', false, '656c2b7a-7689-4c0a-a21d-c6a213dcfad0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0015a2d9-b744-461f-93f6-61ebda5af9d5', 'A video game screen', false, '656c2b7a-7689-4c0a-a21d-c6a213dcfad0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71ee438a-a163-4583-bc24-3bf4a652b514', 'A telephone handset', false, '656c2b7a-7689-4c0a-a21d-c6a213dcfad0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f22ac4ae-9fa6-43f3-90a2-464b17dd18e3', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'What happened when Tilloo pressed the tempting red button on the console?', 'Pressing the red button activated an interference signal that rendered the mechanical robotic arm on the Martian surface inactive.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c27c483d-5dbd-47d2-8be9-f2ec5c67935d', 'A loud warning siren shrilled, and the mechanical robotic arm of the alien lander on the surface suddenly stopped functioning', true, 'f22ac4ae-9fa6-43f3-90a2-464b17dd18e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b56e7e7-f0a2-485a-b702-6ba2d0983c46', 'The Control Room exploded', false, 'f22ac4ae-9fa6-43f3-90a2-464b17dd18e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c519d3a9-1cb2-4b78-9c3e-7232383d6ff2', 'The spacecraft flew back to Earth', false, 'f22ac4ae-9fa6-43f3-90a2-464b17dd18e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4245ca8-b2f8-4f30-9412-d81a29453af6', 'Lights turned off completely', false, 'f22ac4ae-9fa6-43f3-90a2-464b17dd18e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0ff7344c-a215-4316-90b4-1285bbddffff', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'Who was the ''Alien'' in the title ''An Alien Hand'' from the perspective of the Martian inhabitants?', 'In a brilliant role-reversal twist, the ''aliens'' are human scientists on Earth whose robotic arm is probing Mars.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('309c0646-ff3e-42d6-8c6c-9db4967db640', 'Human beings on Earth (and NASA''s Viking robotic lander)', true, '0ff7344c-a215-4316-90b4-1285bbddffff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a84b7d2-6884-4443-9e1e-35a4663949ad', 'Monsters from another galaxy', false, '0ff7344c-a215-4316-90b4-1285bbddffff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('71299216-f903-4263-b9c9-b058febea746', 'A ghost in the underground tunnels', false, '0ff7344c-a215-4316-90b4-1285bbddffff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef593793-744b-4bd3-a581-25a122aed7d8', 'Tilloo''s father', false, '0ff7344c-a215-4316-90b4-1285bbddffff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9d3223a0-e966-46d7-a265-ec6e81ed3311', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Easy', 'What real-life NASA space exploration mission inspired Dr. Jayant Narlikar''s story ''An Alien Hand''?', 'NASA''s 1976 Viking 1 and 2 Mars lander missions with robotic soil-sampling arms inspired Narlikar''s imaginative perspective.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f4f0ccd-fe3c-4112-9d11-40701c82b8aa', 'The VIKING Mission to Mars (Viking 1 and Viking 2, 1976)', true, '9d3223a0-e966-46d7-a265-ec6e81ed3311');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b1ab76d-03cb-4408-b859-7a4d4a924de0', 'The Apollo 11 Moon landing', false, '9d3223a0-e966-46d7-a265-ec6e81ed3311');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b239a659-87c9-4827-8614-05edcd20c1aa', 'The Voyager 1 mission', false, '9d3223a0-e966-46d7-a265-ec6e81ed3311');
