INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b793b1e-ded3-4fc1-80d4-58293d3fb2af', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'What wise advice did Number One (the in-charge of defense) give to the President''s advisory council regarding the alien spacecraft?', 'Number One argued for strategic discretion: destroying the probes would reveal Martian presence and invite retaliatory exploration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11d409e5-bac3-49c0-90fd-4d9876fb38d0', 'He advised passive observation and non-interference, warning that destroying the spacecraft would reveal their existence and location to unknown alien civilizations', true, '2b793b1e-ded3-4fc1-80d4-58293d3fb2af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6053911b-060d-42d2-836f-ec3116ad400c', 'He advised shooting missiles at the spacecraft immediately', false, '2b793b1e-ded3-4fc1-80d4-58293d3fb2af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8460248a-91b8-4ad1-8319-05d4c1966a95', 'He advised inviting the aliens to dinner', false, '2b793b1e-ded3-4fc1-80d4-58293d3fb2af');
