INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d815ec3-6176-4db5-b4e6-98327c6b6f9a', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'What did Number Two (the chief scientist) conclude about the approaching alien spacecraft?', 'Number Two''s sensor telemetry confirmed the alien probes carried only robotic instruments without living biological crew.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94d13f84-eac6-4a83-abd6-a52d85789135', 'He confirmed that the spacecraft were completely unmanned and contained only automated electronic recording instruments, so passive non-interference posed zero danger', true, '5d815ec3-6176-4db5-b4e6-98327c6b6f9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1895332-4fcc-4807-a787-e6726a5040cd', 'He said the craft were filled with dangerous soldiers', false, '5d815ec3-6176-4db5-b4e6-98327c6b6f9a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc72995c-35d0-4a0d-bac4-a39eb4fd6dac', 'He thought they were birds', false, '5d815ec3-6176-4db5-b4e6-98327c6b6f9a');
