INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5cf18c0c-b2ad-4ef5-bfa7-c166f43af851', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'How did NASA scientists on Earth explain the sudden mechanical failure of the Viking lander''s robotic arm to news reporters?', 'NASA scientists treated the arm stoppage as an enigmatic electronic malfunction and restored functionality remotely via radio telecommands.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd1429f0-8f46-4fb8-98ab-3df86cc13dee', 'They announced that the mechanical arm had developed a minor unexpected technical glitch, but their Earth-based engineers were transmitting corrective radio signals to reactivate it', true, '5cf18c0c-b2ad-4ef5-bfa7-c166f43af851');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17332dd5-0896-4ec4-8845-0897c089b815', 'They announced they were attacked by Martians', false, '5cf18c0c-b2ad-4ef5-bfa7-c166f43af851');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e53538d-3aba-44e9-8298-992dfe014afb', 'They said the mission was abandoned', false, '5cf18c0c-b2ad-4ef5-bfa7-c166f43af851');
