INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e78f39a-f35f-4374-ba30-65e0eb88a6f9', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'What was the final conclusion reached by Earth scientists after analyzing the Martian soil samples collected by the Viking lander?', 'The ironic climax: NASA concluded Mars is lifeless, while the underground Martian civilization continues to flourish in secret.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f807e39-6127-44c5-bc73-65aa53eade82', 'The soil samples showed NO SIGNS OF LIFE, leaving Earth scientists disappointed, while the Martians remained safely hidden underground', true, '6e78f39a-f35f-4374-ba30-65e0eb88a6f9');
