INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('928818cd-f447-4f63-9a61-5fd0aac0b3dc', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'What literary technique is central to the narrative perspective of ''An Alien Hand''?', 'Perspective inversion: presenting humanity as mysterious ''aliens'' through the empathetic eyes of a Martian boy and his family.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88930619-6b4f-4cc7-b3d3-d80c27558919', 'Dramatic Irony and Role Reversal (narrating human space exploration from the viewpoint of the Martian natives)', true, '928818cd-f447-4f63-9a61-5fd0aac0b3dc');
