INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b22348de-9156-4329-b04b-abf2362638b1', 'Irrepressible curiosity, youthful adventure, and eagerness to explore the unknown', true, 'd410bdd2-7cbd-46e8-ae7e-cd9027ff727e');
