INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3f79cb3b-84ad-4baf-8fa1-28e36e425313', 'Class 7', 'English', 'Chapter 11: An Alien Hand', 'Medium', 'What is the meaning of the phrase ''A blessing in disguise''?', 'Idiom meaning: something that seems unfortunate at first (Tilloo getting caught / pressing button) but results in positive outcomes/safety.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1c048a6-60c8-4a5f-920f-5c8a04c405f0', 'An apparent misfortune or mistake that ultimately produces a beneficial outcome', true, '3f79cb3b-84ad-4baf-8fa1-28e36e425313');
