INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b5264d0-c183-4700-b906-9d6ffae7e107', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Easy', 'In financial stock markets, what does a ''BULL MARKET'' represent?', 'A Bull Market (derived from a bull thrusting its horns upward) signifies surging stock indices and robust investor optimism.', NOW()) ON CONFLICT DO NOTHING;
