INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1a735529-2cc5-4112-a1db-943ba6109bca', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Easy', 'In financial stock markets, what does a ''BEAR MARKET'' represent?', 'A Bear Market (derived from a bear swiping its paws downward) describes a prolonged downturn with widespread asset declines.', NOW()) ON CONFLICT DO NOTHING;
