INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0af20144-d53b-4430-b884-e40f67be76e2', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What is ''Foreign Direct Investment'' (FDI)?', 'FDI entails substantial long-term cross-border capital ownership, technology transfer, and direct operational management in foreign enterprises.', NOW()) ON CONFLICT DO NOTHING;
