INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf17646a-3cb3-4e67-8931-a49096e6a3e5', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What is the key difference between NOMINAL GDP and GDP measured at PURCHASING POWER PARITY (PPP)?', 'PPP adjustment compares real purchasing power across borders: India is the 5th largest economy by Nominal GDP, but 3rd largest by GDP (PPP).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d56e8bee-19c2-4365-a57d-9ade89da90d0', 'Nominal GDP converts national output into US Dollars using current market exchange rates ; GDP (PPP) adjusts for local price level differences and cost of living in each country', true, 'bf17646a-3cb3-4e67-8931-a49096e6a3e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9a8d434b-54ed-40e0-b10d-fb9aa2a2b554', 'Nominal GDP counts only food items', false, 'bf17646a-3cb3-4e67-8931-a49096e6a3e5');
