INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c16e1450-278b-4118-9bd0-8916c72626e0', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What is the ''REPO RATE'' (Repurchase Option Rate) set by the Reserve Bank of India (RBI)?', 'Repo rate is the RBI''s primary policy tool: raising repo rates tightens credit to quell inflation; lowering rates stimulates investment and growth.', NOW()) ON CONFLICT DO NOTHING;
