INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f751e63-baf0-4304-b0ec-7571b0170810', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What does ''Fiscal Deficit'' mean in government budgetary economics?', 'Fiscal deficit indicates the net amount of money the government must borrow to meet its spending requirements.', NOW()) ON CONFLICT DO NOTHING;
