INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('48704d35-3e36-4539-b9c8-6634f1cddc5c', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'Which Asian multilateral development bank headquartered in Manila, Philippines, was established in 1966 to foster economic growth and cooperation in the Asia-Pacific region?', 'The Asian Development Bank (ADB) provides loans, technical assistance, and equity investments to eradicate extreme poverty across Asia.', NOW()) ON CONFLICT DO NOTHING;
