INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('634867eb-b06a-4b8c-84e5-0cc7e5fd4f0b', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What is the ''NASDAQ'' stock exchange in the United States famous for?', 'NASDAQ (National Association of Securities Dealers Automated Quotations) is the flagship global exchange for high-growth technological innovators.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e1ff85a-65b2-4552-a016-00d999415e74', 'Being the world''s premier electronic, screen-based stock market specializing in global technology giants (such as Apple, Microsoft, Google, NVIDIA, Amazon)', true, '634867eb-b06a-4b8c-84e5-0cc7e5fd4f0b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f5e0864-fb4a-4f75-b440-e9acd359a44e', 'Trading only agricultural crops', false, '634867eb-b06a-4b8c-84e5-0cc7e5fd4f0b');
