INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb9cd0cf-fbe4-4ffe-9a09-09b494078522', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What is ''Global Supply Chain'' in international trade?', 'Global supply chains decompose manufacturing: e.g. a smartphone designed in California, chips made in Taiwan, assembled in India/China, and sold globally.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c928639d-fe48-4c7f-bcad-a587464a51f3', 'The integrated worldwide network of sourcing raw materials, manufacturing intermediate components across multiple nations, and distributing finished goods globally', true, 'cb9cd0cf-fbe4-4ffe-9a09-09b494078522');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c94923f-c1f8-44a1-bd33-9ba11d0ff1fb', 'A long iron chain used on container ships', false, 'cb9cd0cf-fbe4-4ffe-9a09-09b494078522');
