INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b7779984-2b27-4306-b98c-63aaec5d9fbb', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What is ''Microfinance'' pioneered by Nobel Peace laureate Muhammad Yunus (Grameen Bank)?', 'Microfinance empowers grassroots rural entrepreneurs through micro-credit, fostering financial inclusion and poverty eradication.', NOW()) ON CONFLICT DO NOTHING;
