INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3b2c5356-d7ab-4ce5-8e10-99f566520eef', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What is ''Cryptocurrency'' (like Bitcoin or Ethereum)?', 'Cryptocurrencies are cryptographically secured decentralized digital assets operating on distributed ledger technology.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4fb3684-2252-4bb2-9359-3a2cbe6214f6', 'A digital or virtual currency secured by cryptography and decentralized blockchain networks rather than issued by a central sovereign bank', true, '3b2c5356-d7ab-4ce5-8e10-99f566520eef');
