INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6a8be5e7-4a4b-42e8-845b-5659c2c1e83b', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What is a ''Free Trade Agreement'' (FTA) between countries?', 'FTAs dismantle tariff and non-tariff barriers, boosting mutual trade volumes and economic integration between partner nations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ac7f4e3-2015-40bc-81d4-eed5dd130ffd', 'A treaty between two or more nations to substantially eliminate tariffs, import duties, and trade quotas, fostering seamless cross-border commerce', true, '6a8be5e7-4a4b-42e8-845b-5659c2c1e83b');
