INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dab19a4a-4825-4565-90eb-04c6d7593d63', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Medium', 'What is ''Sovereign Wealth Fund'' (SWF)?', 'SWFs invest national surplus revenues internationally to generate intergenerational wealth, fiscal stability, and strategic asset diversification.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e85ff2f-ade6-4772-a206-13c7b641587a', 'A state-owned state investment fund comprising financial assets (stocks, bonds, real estate) financed by foreign exchange reserves or commodity revenues (like Norway''s Oil Fund or Abu Dhabi ADIA)', true, 'dab19a4a-4825-4565-90eb-04c6d7593d63');
