INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('34dbb9e9-3147-48ef-934d-9f10d01fb97f', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'e472f35b-28ba-4418-8a32-7d0821931a19');
