INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9882efe-f598-4940-b16c-9de4805a93e7', 'Institution 1', false, 'f1af12d3-fdd1-4082-9aa0-4a62cde25b4f');
