INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5ac347ee-0301-43df-a4d6-e161dfa43281', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'Analyze the monetary transmission mechanism of ''Quantitative Easing'' (QE) employed by major central banks during severe economic crises:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55442605-38bf-4079-bc21-bf73a5137b33', 'The central bank purchases large quantities of government bonds and financial assets from commercial markets, expanding the central bank''s balance sheet and injecting massive liquidity to lower long-term interest rates', true, '5ac347ee-0301-43df-a4d6-e161dfa43281');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc2defeb-3947-40de-b068-eff98b52e1a8', 'The government prints paper money and drops it from helicopters on streets', false, '5ac347ee-0301-43df-a4d6-e161dfa43281');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a1cc738-edd8-4501-9583-ecdc5a71c428', 'The central bank closes all private banks', false, '5ac347ee-0301-43df-a4d6-e161dfa43281');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cadee5d5-4b30-45d9-abdc-fee7df1129cc', 'The government increases taxes by 100%', false, '5ac347ee-0301-43df-a4d6-e161dfa43281');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2b8b34da-d041-453d-bfcf-02cbd6a031f1', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'Match Column I (Global Economic Indices / Concepts) with Column II (Economic Definitions):
(a) Consumer Price Index (CPI) -> (i) Measures average change in retail prices paid by households for a basket of goods
(b) Gini Coefficient          -> (ii) Statistical measure of income or wealth inequality within a nation (0 to 1)
(c) Purchasing Power Parity    -> (iii) Exchange rate theory equalizing the price of an identical basket of goods across currencies
(d) Special Drawing Rights (SDR) -> (iv) International reserve asset created by the IMF based on a basket of 5 currencies', 'CPI = retail inflation; Gini = inequality index; PPP = price parity; SDR = IMF supplementary reserve currency basket.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ab4bace2-1060-405d-a201-921bc6d9cd2f', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '2b8b34da-d041-453d-bfcf-02cbd6a031f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f08cf474-b67e-4a3a-a11e-89d5797a1e33', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '2b8b34da-d041-453d-bfcf-02cbd6a031f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44e95ee5-6716-4d65-a188-90978117bd7f', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '2b8b34da-d041-453d-bfcf-02cbd6a031f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bca3cb8a-0ec9-4cda-b19c-8e5d0493c70a', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '2b8b34da-d041-453d-bfcf-02cbd6a031f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('942b8705-ea33-497b-9bed-1d3664ffd4b6', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'Read the statements regarding India''s Foreign Trade and Forex Reserves:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3c6de27-03f9-4e89-8c86-9110f3dd4709', 'Statements 1 and 2 only', true, '942b8705-ea33-497b-9bed-1d3664ffd4b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45e11442-5a79-4101-aa82-5cc9e68a6f72', 'Statements 2 and 3 only', false, '942b8705-ea33-497b-9bed-1d3664ffd4b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d23b4e4-8541-4837-b838-be12b90a3672', 'Statements 1 and 3 only', false, '942b8705-ea33-497b-9bed-1d3664ffd4b6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48dac1ab-00eb-4906-b4ce-0a524eb57234', 'All Statements 1, 2, and 3', false, '942b8705-ea33-497b-9bed-1d3664ffd4b6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2cd260df-ad80-455f-b8c1-28430695d0a0', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'What was the ''Bretton Woods Conference'' of July 1944 in New Hampshire, USA?', 'Bretton Woods established the post-war multilateral architecture: institutionalizing the IMF, IBRD, and fixed-rate convertible dollar-gold standards.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('932b1fbc-9a32-401a-9f99-c478e520002c', 'A landmark gathering of 44 Allied nations that designed the post-WWII international monetary order, creating the IMF, the World Bank, and fixing gold-pegged exchange rates', true, '2cd260df-ad80-455f-b8c1-28430695d0a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73701fee-5fe6-4d16-9b9d-06ddff3c8f2c', 'A meeting to end World War I', false, '2cd260df-ad80-455f-b8c1-28430695d0a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e63df04d-bec0-4384-9488-a5559247268d', 'A conference that founded the European Union', false, '2cd260df-ad80-455f-b8c1-28430695d0a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65dc2ee0-bc80-4045-a223-09a120a4bbf7', 'A summit to establish oil pipelines', false, '2cd260df-ad80-455f-b8c1-28430695d0a0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dcca2e13-7eef-455f-aaa6-7f1e0ba118ec', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'What is ''De-Dollarization'' in contemporary global geopolitics?', 'De-dollarization seeks to mitigate sanctions risks, currency volatility, and extraterritorial jurisdiction by promoting alternative bilateral currency settlement mechanisms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b178850f-363b-4cca-bd70-ecc8370f7116', 'The strategic initiative by emerging economies (like BRICS) to reduce reliance on the US Dollar in bilateral trade settlement, using local national currencies (Rupee, Ruble, Yuan) and central bank digital currencies', true, 'dcca2e13-7eef-455f-aaa6-7f1e0ba118ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('73c81d7e-8a6e-4a26-95f2-fd745f578113', 'Banning all paper money completely', false, 'dcca2e13-7eef-455f-aaa6-7f1e0ba118ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('103aa1e8-c557-4561-902b-e8fbb49b4f41', 'A law forcing everyone to use gold coins only', false, 'dcca2e13-7eef-455f-aaa6-7f1e0ba118ec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10fcd2c4-b334-4a5e-a60a-ac1fba229d44', 'The closure of all American banks', false, 'dcca2e13-7eef-455f-aaa6-7f1e0ba118ec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('327f1cb5-c83f-48c9-bcc6-e683576fa067', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'Consider four financial instruments:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e30ff868-33d6-4da8-b8bb-454a4a70d125', 'Instrument 3 only (Treasury Bills)', true, '327f1cb5-c83f-48c9-bcc6-e683576fa067');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38bbd5a5-3158-4315-b0f5-b79eed58504b', 'Instruments 1 and 2 only', false, '327f1cb5-c83f-48c9-bcc6-e683576fa067');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea60ee75-737e-4f71-8cd2-da158e569ee9', 'Instruments 2 and 4 only', false, '327f1cb5-c83f-48c9-bcc6-e683576fa067');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a70137d-403f-4d45-9f90-7e7f7820f84d', 'All 1, 2, 3, and 4', false, '327f1cb5-c83f-48c9-bcc6-e683576fa067');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3bcf6ee4-1dd4-49e9-9d52-47688be9ed9e', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'What is the ''Triffin Dilemma'' in international economics?', 'Robert Triffin noted that the reserve currency issuer must run continuous balance of payments deficits to supply global liquidity, eventually undermining trust in its currency.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e26bec2d-8948-414c-83fa-90b35b4e923b', 'The fundamental conflict of interest between domestic monetary objectives and international obligations for a country whose national currency serves as the world''s global reserve currency', true, '3bcf6ee4-1dd4-49e9-9d52-47688be9ed9e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dad42e6a-e4ac-46d1-bdad-b04187b3d7dc', 'The problem of counting paper money in banks', false, '3bcf6ee4-1dd4-49e9-9d52-47688be9ed9e');
