INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('70f0b5c0-dcf7-4069-89a7-f9ddffc68485', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'Why is ''Venture Capital'' (VC) critical to the modern startup and innovation ecosystem?', 'Venture capital finances disruptive, high-risk innovation, creating global tech unicorns (fintech, AI, clean tech, biotech) that transform markets.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d167f3d1-decb-4ee6-8a61-9e39708ba9ec', 'It provides high-risk equity funding, mentorship, and strategic growth capital to early-stage technology startups with high growth potential before they achieve profitability', true, '70f0b5c0-dcf7-4069-89a7-f9ddffc68485');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('693abfa3-492a-4226-828b-6e314152e4fb', 'It lends money only to government departments', false, '70f0b5c0-dcf7-4069-89a7-f9ddffc68485');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b5b680e-3d42-4ed4-856a-e8b3b1cae37c', 'It insures houses against floods', false, '70f0b5c0-dcf7-4069-89a7-f9ddffc68485');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85637d9c-6ac7-4171-ae65-049b0da096d9', 'It manages pension funds for retired persons only', false, '70f0b5c0-dcf7-4069-89a7-f9ddffc68485');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da76a3a4-2d39-47dd-9d2e-2f612151a569', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'What is ''Financial Inclusion'' and why is it a cornerstone of modern national development strategy?', 'Financial inclusion (driven by Pradhan Mantri Jan Dhan Yojana and UPI) empowers vulnerable populations, reduces poverty, and formalizes the economy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bdb27d6-b513-4ca7-9788-0d176d81fecf', 'Ensuring that all individuals and businesses—especially marginalized, rural, and low-income populations—have universal access to useful, affordable formal financial products (banking accounts, savings, credit, insurance, digital payments)', true, 'da76a3a4-2d39-47dd-9d2e-2f612151a569');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4595fee2-19f0-4e0a-8972-7024a39b50a9', 'Making everyone pay the same income tax', false, 'da76a3a4-2d39-47dd-9d2e-2f612151a569');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('69e92bf3-924a-41b9-a188-8d230472569e', 'Giving free stock shares to all citizens', false, 'da76a3a4-2d39-47dd-9d2e-2f612151a569');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2270100-6c64-4d9f-9355-46d1cd691788', 'Banning all private banks', false, 'da76a3a4-2d39-47dd-9d2e-2f612151a569');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bbdd8eb5-5f26-46ec-8e86-e73d79ff99dc', 'Class 7', 'GK', 'Chapter 11: Global Economy, Trade, Financial Institutions & Global Markets', 'Hard', 'What overarching economic wisdom is synthesized in Chapter 11 of General Knowledge?', 'Chapter 11 synthesizes the dynamics of global finance: central banking, international development, multilateral trade, market mechanisms, and socio-economic equity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b594d5ef-f9bb-47a5-9a94-94ee309788fc', 'A healthy, equitable global economy requires prudent monetary policy, open rules-based international trade, ethical financial regulation, and inclusive financial systems that convert capital into sustainable human development, scientific innovation, and shared prosperity', true, 'bbdd8eb5-5f26-46ec-8e86-e73d79ff99dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3bacffb2-7a51-4bac-bd55-1ca83af586e1', 'That only stock brokers understand economics', false, 'bbdd8eb5-5f26-46ec-8e86-e73d79ff99dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4c1c359-5e32-4e2a-9d01-9b176c69c061', 'That trade between nations always causes conflict', false, 'bbdd8eb5-5f26-46ec-8e86-e73d79ff99dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0d2f029-4385-4b67-8061-ec1aee52560e', 'That economic growth has no relation to human well-being', false, 'bbdd8eb5-5f26-46ec-8e86-e73d79ff99dc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('773ba7b6-8388-4fad-8ffd-c9ef55c5b977', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'What is the outermost, thinnest solid layer of the Earth called?', 'The crust is the outermost solid lithospheric layer of the Earth, averaging 35 km on continental masses and only 5 km on ocean floors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa1da6fe-66b2-42ab-a6af-f523cfae2157', 'The Crust', true, '773ba7b6-8388-4fad-8ffd-c9ef55c5b977');
