INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7506ab30-e3d3-44e9-a441-bd5fb9736f80', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'What are the two main mineral constituents of the CONTINENTAL CRUST (often called ''SIAL'')?', 'The continental crust is composed predominantly of Silica and Alumina, hence abbreviated as SIAL.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee6fd59b-df21-4b52-a14d-b0b39551c116', 'Silica and Alumina (SIAL)', true, '7506ab30-e3d3-44e9-a441-bd5fb9736f80');
