INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('da362243-9cc6-4292-bd8d-ca563eb85528', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'What are the main mineral constituents of the OCEANIC CRUST (called ''SIMA'')?', 'The basaltic oceanic crust mainly comprises Silica and Magnesium, hence named SIMA.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ee82cf2-0c27-406d-b77a-2a1ca24424e0', 'Silica and Magnesium (SIMA)', true, 'da362243-9cc6-4292-bd8d-ca563eb85528');
