INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5c609b0f-12c5-41b3-b4c6-a64020148c93', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'What are the main mineral constituents of the innermost central layer of the Earth—the CORE (called ''NIFE'')?', 'The Earth''s core (radius ~3,500 km) is composed of heavy dense metals: Nickel (Ni) and Ferrous/Iron (Fe), termed NIFE.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec8af110-62ad-425d-aff1-701ad167180a', 'Nickel and Ferrous / Iron (NIFE)', true, '5c609b0f-12c5-41b3-b4c6-a64020148c93');
