INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a3910279-47be-454c-adf1-6adcb374b57e', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'Which layer of the Earth lies directly beneath the crust and extends to a depth of 2,900 km?', 'The mantle forms the intermediate layer of the Earth, extending to a depth of 2,900 km below the crust.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7d8f933-8926-4342-a470-e6ff2d4ab5d6', 'The Mantle (Asthenosphere)', true, 'a3910279-47be-454c-adf1-6adcb374b57e');
