INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca6318e6-b799-4e30-a6b7-884c4755212b', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'Rocks that are formed directly by the cooling and solidification of molten magma or lava are called:', 'Igneous rocks (Latin ''Ignis'' = fire) are the primary parent rocks formed directly from cooling magma or lava.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0151a59-f3d6-4b90-a42f-078d72382f49', 'Igneous Rocks (Primary Rocks)', true, 'ca6318e6-b799-4e30-a6b7-884c4755212b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9a84108-b5c7-4862-9a7e-041488526f8c', 'Sedimentary Rocks', false, 'ca6318e6-b799-4e30-a6b7-884c4755212b');
