INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d46f3cc-d242-4b8a-8c19-53f5726ad2b9', 'Fossil Rocks', false, 'ca6318e6-b799-4e30-a6b7-884c4755212b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c989c560-fb7a-4327-8633-962184a52b8d', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'Which type of igneous rock is formed when molten lava comes out onto the Earth''s surface and cools down RAPIDLY, forming fine-grained rocks like the Basalt of the Deccan Plateau?', 'Extrusive (volcanic) rocks cool rapidly on the surface, producing fine-grained crystalline structures like Basalt.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86daf495-408c-4aa3-9929-fcbd3cb7ab2d', 'Extrusive Igneous Rocks (e.g. Basalt)', true, 'c989c560-fb7a-4327-8633-962184a52b8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85967dbc-1d46-4ffa-a99d-23db69758130', 'Intrusive Igneous Rocks', false, 'c989c560-fb7a-4327-8633-962184a52b8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33a28688-9bd5-42c5-9a82-f718840c07b0', 'Sedimentary Rocks', false, 'c989c560-fb7a-4327-8633-962184a52b8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd36050b-2b05-4093-8e00-11e18ca0377a', 'Metamorphic Rocks', false, 'c989c560-fb7a-4327-8633-962184a52b8d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('26e933ba-85d1-473d-b251-62c35d90a504', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'Which type of igneous rock is formed when molten magma cools SLOWLY deep inside the Earth''s crust, forming large crystals like Granite?', 'Intrusive (plutonic) rocks cool slowly within the crust, forming coarse-grained crystalline textures like Granite.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5efbe57d-2cff-4ef4-b5ed-876ba6e23cd3', 'Intrusive Igneous Rocks (e.g. Granite)', true, '26e933ba-85d1-473d-b251-62c35d90a504');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('af9897c3-5c62-420f-9613-36059d1ed8f8', 'Extrusive Igneous Rocks', false, '26e933ba-85d1-473d-b251-62c35d90a504');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00fcfb3a-1c92-4c65-aae9-0f23bcabcb92', 'Sedimentary Rocks', false, '26e933ba-85d1-473d-b251-62c35d90a504');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e075fec0-e60f-4aec-a5d9-ec8c18b09fd1', 'Sandstone', false, '26e933ba-85d1-473d-b251-62c35d90a504');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('777df09e-f5dd-4ea7-a7a6-1f00360377cc', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'Rocks formed by the deposition, accumulation, and compression of mineral sediments and organic remains in layers (containing FOSSILS) are called:', 'Sedimentary rocks (Latin ''sedimentum'' = settle down) are layered strata formed by compacted sediments and frequently contain fossils.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a115906-d128-41c0-bcbc-b8caf4dee426', 'Sedimentary Rocks (e.g. Sandstone, Limestone, Shale)', true, '777df09e-f5dd-4ea7-a7a6-1f00360377cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e64fdcd-f9ec-41db-a805-76ec94beafb7', 'Igneous Rocks', false, '777df09e-f5dd-4ea7-a7a6-1f00360377cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38890562-390f-49c1-a3bd-b7c9730bea22', 'Metamorphic Rocks', false, '777df09e-f5dd-4ea7-a7a6-1f00360377cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('802128ed-9633-4435-840f-31207cacfb28', 'Basalt', false, '777df09e-f5dd-4ea7-a7a6-1f00360377cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fe2eb4bc-d320-4e72-a87e-c5b64dffcfbe', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'When igneous and sedimentary rocks undergo dramatic transformations under intense HEAT and extreme PRESSURE, what new class of rocks is formed?', 'Metamorphic rocks (Greek ''metamorphose'' = change of form) result from recrystallization under extreme heat and pressure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf9c08d7-32dd-4a2b-9fc0-1adbf61b2d0e', 'Metamorphic Rocks (e.g. Clay into Slate, Limestone into Marble)', true, 'fe2eb4bc-d320-4e72-a87e-c5b64dffcfbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3f39635-da81-4842-a6c0-0474cb8a0790', 'Primary Rocks', false, 'fe2eb4bc-d320-4e72-a87e-c5b64dffcfbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05c3c155-a811-438c-98f3-f834628939e8', 'Extrusive Rocks', false, 'fe2eb4bc-d320-4e72-a87e-c5b64dffcfbe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc8607d1-6b45-4de9-86f8-9acc0a3e7088', 'Magma', false, 'fe2eb4bc-d320-4e72-a87e-c5b64dffcfbe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba6a0619-1140-4e2d-9d11-27ea7e986a2a', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'The continuous geological transformation of one rock type into another under cyclical physical processes is known as the:', 'The rock cycle describes the cyclic transitions among igneous, sedimentary, and metamorphic rocks driven by geological forces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f02285eb-3ef5-4746-b663-2f878a50a912', 'The Rock Cycle', true, 'ba6a0619-1140-4e2d-9d11-27ea7e986a2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c91589e-204f-4510-b8c6-9041da704622', 'The Water Cycle', false, 'ba6a0619-1140-4e2d-9d11-27ea7e986a2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad301f39-4ecb-45a4-aae3-decc89ad9a01', 'The Nitrogen Cycle', false, 'ba6a0619-1140-4e2d-9d11-27ea7e986a2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e058558-61e9-4b82-a88e-50e08a4f846e', 'The Carbon Cycle', false, 'ba6a0619-1140-4e2d-9d11-27ea7e986a2a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d7004060-36e7-4f52-b01c-b8ded1ef3825', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Easy', 'Which white metamorphic rock, transformed from sedimentary limestone under high temperature, was used to construct the world-famous TAJ MAHAL at Agra?', 'Makrana white marble (metamorphosed limestone from Rajasthan) was used to construct the iconic Taj Mahal.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d01e1858-1f0f-488a-9132-ad4fe1f7b9fa', 'White Marble (Makrana Marble)', true, 'd7004060-36e7-4f52-b01c-b8ded1ef3825');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cadb949-b97e-40c6-a5cb-13410034f247', 'Red Sandstone', false, 'd7004060-36e7-4f52-b01c-b8ded1ef3825');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44962613-1c5b-40b1-a1dd-eeca5ddac82a', 'Granite', false, 'd7004060-36e7-4f52-b01c-b8ded1ef3825');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27a7b591-7fe9-4c72-bb28-65f5c729fad5', 'Basalt', false, 'd7004060-36e7-4f52-b01c-b8ded1ef3825');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('98a9f773-9d31-4865-8a16-95ee89df1591', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What is the fundamental difference between ENDOGENIC forces and EXOGENIC forces shaping the Earth''s surface?', 'Endogenic = internal tectonic/magmatic forces; Exogenic = external geomorphic weathering and erosional agents.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9973122-c364-4c11-bfef-53343c796765', 'Endogenic forces originate deep within the Earth''s interior (causing earthquakes, volcanic eruptions, and mountain building) ; Exogenic forces operate on the Earth''s exterior surface (weathering and erosion by rivers, wind, glaciers, sea waves)', true, '98a9f773-9d31-4865-8a16-95ee89df1591');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d08894a-3cd6-46d6-a275-1b199ca8627d', 'Endogenic forces are in oceans and Exogenic forces are in air', false, '98a9f773-9d31-4865-8a16-95ee89df1591');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0867eaa9-bbf7-4996-803b-d543fa08a3c6', 'Endogenic forces cause rain and Exogenic forces cause fire', false, '98a9f773-9d31-4865-8a16-95ee89df1591');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c618fb3-9004-49af-84e0-262dece6f456', 'There is no difference', false, '98a9f773-9d31-4865-8a16-95ee89df1591');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5d71a3f4-c877-494d-91a2-bad5cfcb1e64', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What is the place in the Earth''s crust where an earthquake vibration originates called, and what is the point on the surface directly above it called?', 'The focus is the subterranean seismic rupture origin; the epicenter is the surface point directly perpendicular above the focus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6b3ae8f-d735-4ebe-8318-430ea2aa6a6c', 'The origin point inside the crust is the FOCUS (Hypocenter) ; The point on the surface directly above the focus is the EPICENTER', true, '5d71a3f4-c877-494d-91a2-bad5cfcb1e64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90491737-c884-418b-ac8e-f7874e3fc74c', 'Surface is Focus and interior is Epicenter', false, '5d71a3f4-c877-494d-91a2-bad5cfcb1e64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d71b6035-75b7-4a16-802f-2e3dff3a235a', 'Both are called Crater', false, '5d71a3f4-c877-494d-91a2-bad5cfcb1e64');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb3f4162-36ce-49f1-b1f8-570c36600555', 'Both are called Magma Chamber', false, '5d71a3f4-c877-494d-91a2-bad5cfcb1e64');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f5a7252e-10f1-4152-841f-21d4b5e97647', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'Which scientific instrument is used to record and measure the vibrations and waves of an Earthquake?', 'Earthquake seismic tremors are recorded by seismographs, with magnitude quantified on the logarithmic Richter scale.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bd4242f-2c23-4262-8179-c9bf8e9a4b00', 'A Seismograph (and measured on the Richter Scale)', true, 'f5a7252e-10f1-4152-841f-21d4b5e97647');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8c05585b-7370-4890-af56-d7c186cbbbbf', 'A Barometer', false, 'f5a7252e-10f1-4152-841f-21d4b5e97647');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ebd5952-53fb-445d-910f-e4afa1803461', 'An Anemometer', false, 'f5a7252e-10f1-4152-841f-21d4b5e97647');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5760773-a149-4d65-aec3-98b61b46d770', 'A Hygrometer', false, 'f5a7252e-10f1-4152-841f-21d4b5e97647');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7fbbe788-bf78-4ad8-9d1c-1234bf7c895e', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What are the large S-shaped curves and loops formed by a meandering river across a flat valley plain called?', 'Meanders are sinuous serpentine curves formed along a mature river''s course by continuous lateral erosion and deposition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c38b279-8a5b-4109-b11b-23db1d913f70', 'Meanders', true, '7fbbe788-bf78-4ad8-9d1c-1234bf7c895e');
