INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('161176d4-8c48-4ab0-9c75-28d83b0afba5', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What happens when a river meander loop becomes so acute that the river cuts through the narrow neck, leaving behind a crescent-shaped cutoff water body?', 'An oxbow lake is a crescent-shaped cutoff lake formed when a river cuts straight through a meandering loop neck during floods.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52ec7b1e-884c-49a5-9357-753009e86a8e', 'An Oxbow Lake', true, '161176d4-8c48-4ab0-9c75-28d83b0afba5');
