INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e4d0f607-c749-4e2b-8d26-43d545d872a0', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What is the triangular landform formed at the mouth of a river where it enters the sea and deposits its entire sediment load called?', 'A delta is a triangular depositional landform formed at a river mouth by distributaries depositing silt into a standing sea/lake.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3704b487-23a8-4309-a58a-5f3e312311d9', 'A River Delta (like the Sundarbans Delta)', true, 'e4d0f607-c749-4e2b-8d26-43d545d872a0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9838af26-396e-4196-a5f5-382fff7ecd42', 'An Estuary', false, 'e4d0f607-c749-4e2b-8d26-43d545d872a0');
