INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5548673b-6a1e-4fff-b208-2edda306f228', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What are the isolated rock pillars left standing in the ocean after the roofs of ''Sea Arches'' collapse under relentless wave erosion called?', 'Coastal wave progression: sea cave → sea arch (roof pierced) → sea stack (roof collapses, leaving isolated vertical rock pillars).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46790bf6-a744-4b27-a7ef-a163388aa7b8', 'Sea Stacks', true, '5548673b-6a1e-4fff-b208-2edda306f228');
