INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b9736fc-875d-4b63-b831-0edc01ae0bf4', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What are the rock formations in hot deserts that have a narrow base and a wide top due to wind eroding the lower section faster than the upper part called?', 'Mushroom rocks develop in arid deserts because wind-borne sand abrasion is concentrated within 1 meter of the ground, undercutting rock bases.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7b6e8e20-2e77-4e9d-a5d6-15c546b9f2d6', 'Mushroom Rocks (Rock Pedestals)', true, '4b9736fc-875d-4b63-b831-0edc01ae0bf4');
