INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5fdb990a-36ef-41e4-94e1-7f2a79d8ee04', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What are the crescent-shaped or ridge-like mounds of sand deposited by desert winds called?', 'Sand dunes are dynamic depositional mounds of sand accumulated by aeolian wind action in desert landscapes.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e163aa3a-c4b4-4c54-aa64-0edd644f636c', 'Sand Dunes (Barchans)', true, '5fdb990a-36ef-41e4-94e1-7f2a79d8ee04');
