INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('70a1b4b8-9303-46bb-9474-08e1d36ec000', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What are the vast deposits of fine, yellowish, wind-blown silt found extensively in northern China called?', 'Loess is fine, mineral-rich, windblown silt deposited over extensive regional plains (notably in China''s Loess Plateau).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d740b0b5-bae8-4e9a-92be-f15fabb710fa', 'Loess Deposits', true, '70a1b4b8-9303-46bb-9474-08e1d36ec000');
