INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('026ad4a5-bbbb-496b-91c3-cac8093c5edb', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What are the ridges of rocks, gravel, sand, and clay deposited by melting glaciers along their valley margins called?', 'Glacial moraines are linear ridges of unsorted glacial till (boulders, gravel, sand, clay) dumped by retreating valley glaciers.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb18cd59-7bd7-46ff-999b-663aa1d56e02', 'Glacial Moraines', true, '026ad4a5-bbbb-496b-91c3-cac8093c5edb');
