INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('80339641-dd88-4e3a-af28-70b403bd31f9', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'Which of the following sedimentary rocks was extensively used to construct the historic RED FORT in Delhi?', 'The Mughal Red Fort in Delhi and Agra Fort were constructed using red quartzitic sandstone quarried in Rajasthan.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5abad155-93b8-4a3b-9bc7-6e259a2c5bbb', 'Red Sandstone', true, '80339641-dd88-4e3a-af28-70b403bd31f9');
