INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96f03aed-1019-4b9e-826e-1b46eb2e8c89', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What are ''Fossils'' found embedded within sedimentary rock strata?', 'Fossils are organic paleontological relics entombed within sedimentary depositional beds over geological epochs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c18905f4-8162-406c-a38e-83b34fb63008', 'The preserved mineralized remains, impressions, or traces of ancient dead plants, animals, and microorganisms trapped in layered rocks millions of years ago', true, '96f03aed-1019-4b9e-826e-1b46eb2e8c89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b8e1a546-af71-4e57-819e-65da7a447477', 'Magma bubbles', false, '96f03aed-1019-4b9e-826e-1b46eb2e8c89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e351e77-d3ef-4882-8d9a-1be2aeed2547', 'Precious jewels made in labs', false, '96f03aed-1019-4b9e-826e-1b46eb2e8c89');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d97d7ef3-fabf-44c3-92a4-6eade7b76b87', 'Pieces of broken pottery', false, '96f03aed-1019-4b9e-826e-1b46eb2e8c89');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('23a1feb3-d216-4673-90a5-826f0f128544', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What is the ''Asthenosphere'' in geology?', 'The ductile asthenosphere undergoes slow convection currents, transporting the rigid lithospheric tectonic plates floating above it.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f881f695-e0f1-4caf-81f6-338cea18ba8d', 'The semi-fluid, ductile upper region of the Earth''s mantle directly below the lithosphere where extreme heat permits solid rock to flow slowly, driving plate tectonics', true, '23a1feb3-d216-4673-90a5-826f0f128544');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c8077351-be56-4baf-a6f6-a8416d70547b', 'The layer of air around the Earth', false, '23a1feb3-d216-4673-90a5-826f0f128544');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2babfb1d-50f5-4f22-9b3c-8c748905c9cd', 'The bottom of the ocean', false, '23a1feb3-d216-4673-90a5-826f0f128544');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d427855-c751-42e0-9b35-ed0a556a82a4', 'The solid center of the core', false, '23a1feb3-d216-4673-90a5-826f0f128544');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('343bc5d4-65d1-464a-b16c-35c1680e8ec6', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'Why is the inner core of the Earth solid despite scorching temperatures exceeding 5,000°C?', 'Extreme lithostatic pressure (~3.6 million atmospheres) raises the melting point of iron-nickel, keeping the inner core solid.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('728ff138-43d7-46d3-a0b0-3a31ac16f019', 'The colossal, overwhelming overlying gravitational Pressure at the Earth''s center compresses the iron-nickel atoms into a solid crystalline state', true, '343bc5d4-65d1-464a-b16c-35c1680e8ec6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e813355-b4d9-4699-9262-5d9c289711d0', 'Because the core is made of ice', false, '343bc5d4-65d1-464a-b16c-35c1680e8ec6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de1317d5-cf47-4e2a-aa87-de4a8716bbf7', 'Because no heat reaches the center', false, '343bc5d4-65d1-464a-b16c-35c1680e8ec6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8099f012-b8d2-4b2b-ab14-b25120e193bc', 'Because the core rotates too fast', false, '343bc5d4-65d1-464a-b16c-35c1680e8ec6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45f43cd9-d7e9-4665-9ee0-95ce1b3da6f2', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Medium', 'What is the steep, nearly vertical rock face rising directly above sea water formed by continuous wave erosion called?', 'A sea cliff is a dramatic vertical coastal rock precipice produced by hydraulic wave action undercutting the shoreface.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('deaf4ba2-8c0f-4b10-b954-0aa0157d526a', 'A Sea Cliff', true, '45f43cd9-d7e9-4665-9ee0-95ce1b3da6f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e7e9fcd7-0d90-489e-b999-51712c206d8e', 'A Sea Arch', false, '45f43cd9-d7e9-4665-9ee0-95ce1b3da6f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9fb307d9-4ee7-411f-936f-a44e1c47b33f', 'A Beach', false, '45f43cd9-d7e9-4665-9ee0-95ce1b3da6f2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('63060bc0-8d74-4c4c-930c-6538a03f53cc', 'A Sand Spit', false, '45f43cd9-d7e9-4665-9ee0-95ce1b3da6f2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34c23c5c-83bc-48f6-a436-c7046326f13a', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('021483f7-5aa7-44f3-b164-90714af871ed', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '34c23c5c-83bc-48f6-a436-c7046326f13a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('029e6fcb-efa2-4965-860d-dfe1b2a27592', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '34c23c5c-83bc-48f6-a436-c7046326f13a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6abc9d2-23c4-403b-acfb-38f0cacc5468', '(A) is true, but (R) is false.', false, '34c23c5c-83bc-48f6-a436-c7046326f13a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f1166edc-bf5c-4d9a-b161-328b68380c39', '(A) is false, but (R) is true.', false, '34c23c5c-83bc-48f6-a436-c7046326f13a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cfc37cec-7293-4547-8b66-e2c2e99fe69d', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'Spot the IMPOSTER in the following rock types and their metamorphic transformations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f2e14b4-cb6e-4297-b4f3-16b57d73ffa1', 'Transformation 1', false, 'cfc37cec-7293-4547-8b66-e2c2e99fe69d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bc67f33-8089-4eb8-a781-cafcae14f65d', 'Transformation 2', false, 'cfc37cec-7293-4547-8b66-e2c2e99fe69d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a632363a-a64e-4876-96d5-45705c3d4656', 'Transformation 3', false, 'cfc37cec-7293-4547-8b66-e2c2e99fe69d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('28277315-1874-4f93-bf07-3c7eb7a6b0f5', 'Transformation 4 (Basalt is formed by the cooling of molten LAVA/MAGMA, NOT by freezing liquid water)', true, 'cfc37cec-7293-4547-8b66-e2c2e99fe69d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1b5d2bc7-4d0e-4d1e-9301-04e78c5f1200', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'Analyze the three types of seismic earthquake waves generated during a tectonic fault slip:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a8c60c1-cbed-4c5b-944c-877bba10d885', 'S-Waves completely disappear at the core-mantle boundary (2,900 km depth), proving conclusively that the Earth''s OUTER CORE is in a MOLTEN LIQUID state', true, '1b5d2bc7-4d0e-4d1e-9301-04e78c5f1200');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c17f9f4c-0d2f-4d0c-b619-ecb72d01f030', 'S-Waves prove that the whole Earth is hollow', false, '1b5d2bc7-4d0e-4d1e-9301-04e78c5f1200');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('92fbbbdc-cd0a-4946-b249-238d609cd808', 'S-Waves show that the core is made of diamond', false, '1b5d2bc7-4d0e-4d1e-9301-04e78c5f1200');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10b06590-b52d-4b15-b35c-5e4564e41c36', 'S-Waves reflect back into space', false, '1b5d2bc7-4d0e-4d1e-9301-04e78c5f1200');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c55a8736-0d3e-4611-a618-2706f1dc296f', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'Match Column I (Geomorphic Landforms) with Column II (Primary Natural Agents of Erosion / Deposition):
(a) Meanders and Oxbow Lakes -> (i) Running River Water (Fluvial agent)
(b) Mushroom Rocks and Dunes   -> (ii) Desert Wind Action (Aeolian agent)
(c) Moraines and U-Valleys    -> (iii) Moving Glacial Ice (Glacial agent)
(d) Sea Stacks and Sea Arches -> (iv) Coastal Ocean Waves (Marine agent)', 'Meanders = rivers; Mushroom rocks = wind; Moraines = glaciers; Stacks = sea waves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9557e995-2afc-4c45-83d7-837c1403e97c', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'c55a8736-0d3e-4611-a618-2706f1dc296f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b14c2a4a-757e-40a3-b616-9cca9face7da', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'c55a8736-0d3e-4611-a618-2706f1dc296f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ce0cbcd-1bd8-467d-9c58-65d41477ebc9', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'c55a8736-0d3e-4611-a618-2706f1dc296f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb356ecf-80a5-4ca8-9462-ec59cca2f2e8', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'c55a8736-0d3e-4611-a618-2706f1dc296f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f8bc6cdd-d5f9-4455-9ed1-dd6a1ffe608e', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'Read the statements regarding the Earth''s geological layers:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f7d0504-b762-413d-be6a-882027b02884', 'Statements 1 and 2 only', true, 'f8bc6cdd-d5f9-4455-9ed1-dd6a1ffe608e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84db7c96-6414-45db-b5a2-59f779a38565', 'Statements 2 and 3 only', false, 'f8bc6cdd-d5f9-4455-9ed1-dd6a1ffe608e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6715f07d-d141-4149-8ac8-580e0dfa8e36', 'Statements 1 and 3 only', false, 'f8bc6cdd-d5f9-4455-9ed1-dd6a1ffe608e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e0c7e1a-86df-4249-b42c-b0d824012d7b', 'All Statements 1, 2, and 3', false, 'f8bc6cdd-d5f9-4455-9ed1-dd6a1ffe608e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('964cd199-6b7d-4df5-a657-507e7ffab3d3', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'How did the massive volcanic lava plateaus (like the DECCAN TRAPS in western and central India) form around 66 million years ago?', 'The Deccan Traps formed via flood basalt volcanism during India''s passage over the Reunion thermal mantle plume in the Late Cretaceous.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e03a8da3-c6f4-466b-ad06-099af5d0d9c0', 'Enormous fissure eruptions poured millions of cubic kilometers of fluid basaltic magma over the landscape, creating thick horizontal flood-basalt lava sheets', true, '964cd199-6b7d-4df5-a657-507e7ffab3d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3474d491-8d33-4ed4-b043-ba1f107d4ed5', 'A giant meteor made of basalt crashed into India', false, '964cd199-6b7d-4df5-a657-507e7ffab3d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4964a19e-d133-4dd1-8279-765035f82e92', 'Basalt was washed down from the Himalayas by rivers', false, '964cd199-6b7d-4df5-a657-507e7ffab3d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08106885-300f-4838-ad78-7b852de41d91', 'Humans mined and piled up the basalt rocks', false, '964cd199-6b7d-4df5-a657-507e7ffab3d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ad72f7a-5f01-432d-b414-da317e0edd62', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'What is the crucial role of the Earth''s molten metallic liquid OUTER CORE in generating the GEOMAGNETIC FIELD (the Geodynamo)?', 'The convective geodynamo in the liquid iron outer core generates Earth''s magnetosphere, shielding life from lethal solar winds.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98898d23-4fed-4074-a4ae-65e61fe15c9d', 'Thermal convection currents of molten iron and nickel, combined with planetary Coriolis rotation, generate powerful electric currents that produce the Earth''s protective magnetic shield against solar radiation', true, '3ad72f7a-5f01-432d-b414-da317e0edd62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59d89068-dbef-407d-88ec-0dc9dfdd867e', 'It acts as a giant refrigerator cooling the crust', false, '3ad72f7a-5f01-432d-b414-da317e0edd62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4acf3fc7-d585-425d-848e-77932a98b68e', 'It generates ocean tides', false, '3ad72f7a-5f01-432d-b414-da317e0edd62');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a435dc9-ab83-47ae-80e2-0d56cf30efc7', 'It creates oxygen for the atmosphere', false, '3ad72f7a-5f01-432d-b414-da317e0edd62');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e8381e8-36fd-401e-88c7-4714f4e676a6', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'Consider four geographical features:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40babe95-e6e3-41fd-aaa2-eb4bbf749a82', 'Features 1, 2, and 3 only', true, '8e8381e8-36fd-401e-88c7-4714f4e676a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbcf5fad-2d91-4c0a-baef-2c1ee5b3d67f', 'Feature 4 only', false, '8e8381e8-36fd-401e-88c7-4714f4e676a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f04f3ba2-4a0e-4bd1-83ab-f1de79e866bd', 'Features 2 and 4 only', false, '8e8381e8-36fd-401e-88c7-4714f4e676a6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ceee55a8-0875-4fc2-b1cd-92b2ff080139', 'All 1, 2, 3, and 4', false, '8e8381e8-36fd-401e-88c7-4714f4e676a6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d07e5a61-3117-487a-bfcc-27dd5065cf2a', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'What is the geological origin of ''Natural Levees'' along the banks of mature lowland rivers?', 'Natural levees are coarse sediment embankments deposited parallel to river channels during flood overflows.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1c12573-ef9f-419a-b709-c1f19c1a612c', 'During seasonal overbank flooding, coarse sediments are deposited immediately along river margins where water velocity drops first, building elevated natural embankment ridges', true, 'd07e5a61-3117-487a-bfcc-27dd5065cf2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35d4c110-930f-4ff7-ac1f-389b2fa516cf', 'Humans constructed them with concrete', false, 'd07e5a61-3117-487a-bfcc-27dd5065cf2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4c49866c-12d5-4866-a700-a8f77f58f126', 'Wind blew sand onto the river banks', false, 'd07e5a61-3117-487a-bfcc-27dd5065cf2a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('deb087cc-5191-4840-8d0b-60dd9ab9018f', 'Earthquakes pushed the banks upwards', false, 'd07e5a61-3117-487a-bfcc-27dd5065cf2a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f50398f1-41be-4f9c-971e-8981028f9040', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'Why do metamorphic rocks often exhibit distinct parallel mineral bands, foliation, or striped textures (such as in Gneiss or Schist)?', 'Metamorphic foliation is the structural alignment of mineral grains perpendicular to principal tectonic stress directions under high P-T conditions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86305b9d-f109-449b-ac3c-ee2abe484ab2', 'Extreme directional tectonic pressure and shear stress force platy and elongated minerals to realign perpendicular to the compressive stress axis', true, 'f50398f1-41be-4f9c-971e-8981028f9040');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47aa847e-d295-4203-abca-a70e26551f1d', 'Because different colored paints were applied to them', false, 'f50398f1-41be-4f9c-971e-8981028f9040');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83b9a9a3-b9ed-4e02-9a86-1a0c24db4805', 'Because water carved lines into them', false, 'f50398f1-41be-4f9c-971e-8981028f9040');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fc81a882-28bd-4895-a1f6-a894bb1b6fec', 'Because they were made by lightning', false, 'f50398f1-41be-4f9c-971e-8981028f9040');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ab56cf13-21e8-4438-b33c-ac2f6109e402', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'What distinguishes a ''Mineral'' from an ordinary rock?', 'Minerals are homogeneous crystalline chemical compounds (e.g. Quartz, Feldspar, Calcite), whereas rocks are heterogeneous lithified aggregates.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b5cce01-ade2-4982-af0e-bc86178b64bd', 'A mineral is a naturally occurring inorganic substance with a definite chemical composition and an ordered internal atomic crystalline structure, whereas a rock is an aggregate of one or more minerals', true, 'ab56cf13-21e8-4438-b33c-ac2f6109e402');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61472278-a7ab-4cc6-915b-a03bdb9ebb31', 'Minerals are artificial man-made materials', false, 'ab56cf13-21e8-4438-b33c-ac2f6109e402');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82001e82-f1e9-4cdb-b55f-361e4249dc61', 'Rocks are always transparent', false, 'ab56cf13-21e8-4438-b33c-ac2f6109e402');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7e9b87f-008c-4e7f-ae8d-f07abd366da0', 'Minerals do not exist inside rocks', false, 'ab56cf13-21e8-4438-b33c-ac2f6109e402');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d211cb5f-2428-428c-9355-8d7af656428d', 'Class 7', 'Social Science', 'Chapter 11: Inside Our Earth, Rocks, Minerals & Dynamic Landforms', 'Hard', 'What master geographical insight is established in Chapter 11 of NCERT Class 7 Geography?', 'Chapter 11 establishes dynamic planetary geomorphology: the perpetual equilibrium between endogenic tectonic construction and exogenic denudational sculpting.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d55ee89-ab6c-4f1b-9f1d-bc1d8c37a44e', 'The Earth is a dynamic, living planet in perpetual transformation—where internal convective forces constantly build and reshape lithospheric crust, while external erosional agents continuously sculpt majestic landforms that sustain human agriculture, civilizational settlements, and mineral wealth', true, 'd211cb5f-2428-428c-9355-8d7af656428d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d5989cd4-2ff8-41c8-888a-877093ba1062', 'That the Earth''s surface never changes', false, 'd211cb5f-2428-428c-9355-8d7af656428d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea3db7df-9d57-4573-a8b2-9fa73b1c347e', 'That rocks have no economic or ecological value', false, 'd211cb5f-2428-428c-9355-8d7af656428d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aef3711e-fa92-4ab7-a63c-43036666b46f', 'That all continents will sink into the core tomorrow', false, 'd211cb5f-2428-428c-9355-8d7af656428d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3ed37ef0-74f5-4813-a353-048c365ccc10', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', 'जिन शब्दों के रूप में लिंग, वचन, कारक, काल आदि के प्रभाव से कभी कोई विकार (परिवर्तन) नहीं होता, उन्हें क्या कहते हैं?', 'अव्यय (अविकारी): जिनका रूप कभी नहीं बदलता (जैसे: और, किन्तु, धीरे-धीरे, प्रतिदिन, अरे, तक)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3409626f-686d-45cc-93a4-5f423a64ffa1', 'अव्यय या अविकारी शब्द (Indeclinable words)', true, '3ed37ef0-74f5-4813-a353-048c365ccc10');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bcb661d-421f-47b5-96d7-598ced039113', 'विकारी शब्द', false, '3ed37ef0-74f5-4813-a353-048c365ccc10');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da4d0400-29f0-4a0f-a2d5-29699d261a31', 'संज्ञा शब्द', false, '3ed37ef0-74f5-4813-a353-048c365ccc10');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d76a354e-0070-4f1b-a793-449dcbf7aba0', 'सर्वनाम शब्द', false, '3ed37ef0-74f5-4813-a353-048c365ccc10');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8bf11bea-1d53-4016-bb8c-0334927040da', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', 'हिंदी व्याकरण में अव्यय के मुख्य रूप से कितने भेद माने जाते हैं?', 'अव्यय के 5 भेद हैं: क्रियाविशेषण, संबंधबोधक, समुच्चयबोधक, विस्मयादिबोधक और निपात।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('520c6e33-47ed-40f7-a8bb-84c489e49464', '5 भेद (1. क्रियाविशेषण, 2. संबंधबोधक, 3. समुच्चयबोधक, 4. विस्मयादिबोधक, 5. निपात)', true, '8bf11bea-1d53-4016-bb8c-0334927040da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42b07373-a5b3-4fd7-9ebb-b5b8d79fe2fb', '2 भेद', false, '8bf11bea-1d53-4016-bb8c-0334927040da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('934311d2-dfdf-409e-b106-0113ab829452', '3 भेद', false, '8bf11bea-1d53-4016-bb8c-0334927040da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84907cf3-4f34-4e7d-8a6d-aacea027ea67', '8 भेद', false, '8bf11bea-1d53-4016-bb8c-0334927040da');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('196b1dc3-43bb-4b03-89aa-190530398d2b', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', 'क्रिया की विशेषता (समय, स्थान, परिमाण, रीति आदि) बताने वाले अव्यय शब्दों को क्या कहते हैं?', 'क्रियाविशेषण: जो अव्यय शब्द क्रिया के घटित होने की विशेषता (कब, कहाँ, कैसे, कितना) बताते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('76c21777-e670-40bf-b8fb-f8f51b45b43b', 'क्रियाविशेषण (Adverb)', true, '196b1dc3-43bb-4b03-89aa-190530398d2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d77fed99-fdce-494f-859d-9c13ea4cf795', 'विशेषण', false, '196b1dc3-43bb-4b03-89aa-190530398d2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef6ab801-316e-4b90-81ff-a25a2b9aab11', 'संबंधबोधक', false, '196b1dc3-43bb-4b03-89aa-190530398d2b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d43b4cae-0992-4a56-b6a7-fcd94ec3c492', 'समुच्चयबोधक', false, '196b1dc3-43bb-4b03-89aa-190530398d2b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('aa9e9a80-d812-4616-8e76-fdae9d3a5714', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', 'क्रियाविशेषण के मुख्य रूप से कितने भेद होते हैं?', 'क्रियाविशेषण के 4 भेद हैं: कालवाचक (कब), स्थानवाचक (कहाँ), परिमाणवाचक (कितना), रीतिवाचक (कैसे)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('007aa818-c486-4a36-9fe6-cb2c3a4e9af3', '4 भेद (1. कालवाचक, 2. स्थानवाचक, 3. परिमाणवाचक, 4. रीतिवाचक)', true, 'aa9e9a80-d812-4616-8e76-fdae9d3a5714');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de2fd880-8802-43e0-8b17-9c4ba7d4b11b', '2 भेद', false, 'aa9e9a80-d812-4616-8e76-fdae9d3a5714');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f295eb8-2462-41cc-9df7-5af6e9f4d43d', '6 भेद', false, 'aa9e9a80-d812-4616-8e76-fdae9d3a5714');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fad9a34-19c3-4071-942f-f3fb555e765a', '3 भेद', false, 'aa9e9a80-d812-4616-8e76-fdae9d3a5714');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f49e30d2-4f1a-455b-9279-e98a4304c6be', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', '''कछुआ धीरे-धीरे चलता है।'' वाक्य में ''धीरे-धीरे'' किस प्रकार का क्रियाविशेषण है?', '''धीरे-धीरे'' क्रिया के संपन्न होने की रीति (ढंग) बता रहा है, अतः यह रीतिवाचक क्रियाविशेषण है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a5e0409-c3cf-45b7-8e2f-6960c0c60e29', 'रीतिवाचक क्रियाविशेषण (Adverb of Manner - कैसे चलता है)', true, 'f49e30d2-4f1a-455b-9279-e98a4304c6be');
