INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('acbb9a9d-7205-419b-b12e-21d345d3fdd0', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', '''हम प्रतिदिन व्यायाम करते हैं।'' वाक्य में ''प्रतिदिन'' किस प्रकार का क्रियाविशेषण है?', '''प्रतिदिन'' क्रिया के होने का समय (काल) बता रहा है, अतः यह कालवाचक क्रियाविशेषण है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c0fff69-7425-4268-9f72-61780873f649', 'कालवाचक क्रियाविशेषण (Adverb of Time - कब करते हैं)', true, 'acbb9a9d-7205-419b-b12e-21d345d3fdd0');
