INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a8f41b82-0591-403c-94df-df6d369a2e42', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', '''बच्चे ऊपर खेल रहे हैं।'' वाक्य में ''ऊपर'' किस प्रकार का क्रियाविशेषण है?', '''ऊपर'' क्रिया के संपन्न होने का स्थान बता रहा है, अतः यह स्थानवाचक क्रियाविशेषण है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0741e809-1e77-4a52-8c9d-90b06dc1d36e', 'स्थानवाचक क्रियाविशेषण (Adverb of Place - कहाँ खेल रहे हैं)', true, 'a8f41b82-0591-403c-94df-df6d369a2e42');
