INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c763317e-300a-42e7-a7dd-0cb5001594b1', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', '''कम बोलो, अधिक काम करो।'' वाक्य में ''कम'' और ''अधिक'' किस प्रकार के क्रियाविशेषण हैं?', '''कम'' और ''अधिक'' क्रिया की मात्रा/परिमाण का बोध कराते हैं, अतः परिमाणवाचक क्रियाविशेषण हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aca941aa-cfed-4a31-816b-28aea46dfe33', 'परिमाणवाचक क्रियाविशेषण (Adverb of Quantity - कितना)', true, 'c763317e-300a-42e7-a7dd-0cb5001594b1');
