INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('549b5a19-4158-4948-b45c-c3a18f5eb082', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', 'जो अव्यय शब्द संज्ञा या सर्वनाम के बाद आकर उसका संबंध वाक्य के अन्य शब्दों से जोड़ते हैं (जैसे: ''के बिना'', ''के साथ'', ''के सामने''), वे क्या कहलाते हैं?', 'संबंधबोधक: संज्ञा/सर्वनाम के पीछे प्रयुक्त होकर वाक्य के अन्य पदों से संबंध बताने वाले अव्यय।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d070132c-03ad-4272-9c63-781876e9ff7d', 'संबंधबोधक अव्यय (Postposition)', true, '549b5a19-4158-4948-b45c-c3a18f5eb082');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4eb59a3-55e4-4281-8f3d-d4fa43bf3599', 'समुच्चयबोधक', false, '549b5a19-4158-4948-b45c-c3a18f5eb082');
