INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b70809f5-489c-425e-a494-af1baffad85d', 'क्रियाविशेषण', false, '549b5a19-4158-4948-b45c-c3a18f5eb082');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('695a2cda-677c-441b-b340-2596b4bb979a', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', 'दो शब्दों, वाक्यांशों या वाक्यों को आपस में जोड़ने वाले अव्यय शब्दों (जैसे: ''और'', ''किन्तु'', ''परन्तु'', ''क्योंकि'') को क्या कहते हैं?', 'समुच्चयबोधक (योजक): दो पदों, उपवाक्यों या वाक्यों को परस्पर जोड़ने वाले अव्यय शब्द।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42d1120c-8374-437b-9f5f-f56b03c01e9d', 'समुच्चयबोधक या योजक (Conjunction)', true, '695a2cda-677c-441b-b340-2596b4bb979a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44ef971a-ce6e-45a9-9de3-22956e2f6858', 'संबंधबोधक', false, '695a2cda-677c-441b-b340-2596b4bb979a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1782693-aff5-468e-a530-b07ba0d2bca4', 'विस्मयादिबोधक', false, '695a2cda-677c-441b-b340-2596b4bb979a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('033b6e4b-79cc-4912-8202-38d26e8c8998', 'निपात', false, '695a2cda-677c-441b-b340-2596b4bb979a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('56c364aa-24bb-47c6-a373-4f1792424672', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', 'हर्ष, शोक, भय, आश्चर्य, घृणा, चेतावनी आदि तीव्र मनोभावों को प्रकट करने वाले अव्यय (जैसे: ''अरे!'', ''वाह!'', ''शाबाश!'', ''हाय!'') क्या कहलाते हैं?', 'विस्मयादिबोधक: मनोभावों (आश्चर्य, दुःख, उल्लास) को व्यक्त करने वाले अव्यय, जिनके बाद ''!'' चिह्न लगता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5911cd2f-d612-47fd-a3ab-4c50d24a44f7', 'विस्मयादिबोधक अव्यय (Interjection)', true, '56c364aa-24bb-47c6-a373-4f1792424672');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4afbdbe3-7256-4254-9c80-1ce75ba87cb2', 'संबंधबोधक', false, '56c364aa-24bb-47c6-a373-4f1792424672');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c66012fc-a0f8-4bfb-9202-c3d320bc5b90', 'क्रियाविशेषण', false, '56c364aa-24bb-47c6-a373-4f1792424672');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('723b899f-86a3-4832-a2bf-054b5b6d14e3', 'निपात', false, '56c364aa-24bb-47c6-a373-4f1792424672');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35ef8abe-711f-4072-a53b-4acff3882959', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Easy', 'जो अव्यय शब्द किसी शब्द के बाद लगकर उसके अर्थ में विशेष ''बल'' (Emphasis) प्रदान करते हैं (जैसे: ''ही'', ''भी'', ''तो'', ''मात्र'', ''तक''), वे क्या कहलाते हैं?', 'निपात: किसी पद पर विशेष बल देने के लिए प्रयुक्त होने वाले अव्यय (जैसे: ''वह भी जाएगा'', ''तुम ही आओगे'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6059911c-463c-4864-972f-cef2d4df2998', 'निपात (Particles)', true, '35ef8abe-711f-4072-a53b-4acff3882959');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eea6f440-01f9-4285-abb0-7c2b11a1d5c0', 'क्रियाविशेषण', false, '35ef8abe-711f-4072-a53b-4acff3882959');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1403c2b-b3d7-44a9-b2ef-cc86d525a779', 'संबंधबोधक', false, '35ef8abe-711f-4072-a53b-4acff3882959');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2c85c919-f701-4343-b0f9-ef541601f796', 'विशेषण', false, '35ef8abe-711f-4072-a53b-4acff3882959');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53cf9434-7e70-4565-8cc1-a1116441be16', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', 'क्रियाविशेषण और विशेषण में क्या मूलभूत व्याकरणिक अंतर होता है?', 'विशेषण संज्ञा/सर्वनाम की विशेषता प्रकट करता है; क्रियाविशेषण क्रिया की विशेषता (ढंग/समय/स्थान/मात्रा) बताता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4c5270d-35b2-45a7-b6ed-18ca6459fd4f', 'विशेषण ''संज्ञा या सर्वनाम'' की विशेषता बताता है (जैसे: ''मीठा सेब'') ; जबकि क्रियाविशेषण ''क्रिया'' की विशेषता बताता है (जैसे: ''मधुर गाता है'')', true, '53cf9434-7e70-4565-8cc1-a1116441be16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('210090ee-a7a5-45a6-b349-2ea990188638', 'दोनों में कोई अंतर नहीं होता', false, '53cf9434-7e70-4565-8cc1-a1116441be16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3616bbb-b820-482d-9e50-8f1913b36da2', 'विशेषण केवल वाक्यों के अंत में आता है', false, '53cf9434-7e70-4565-8cc1-a1116441be16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4626d9d3-30af-40da-a424-ff485b5880c5', 'क्रियाविशेषण में विकार होता है', false, '53cf9434-7e70-4565-8cc1-a1116441be16');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cfeb9c05-2122-49c4-9e29-3dfefee6da4e', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', 'समुच्चयबोधक (योजक) के मुख्य रूप से दो भेद कौन-से होते हैं?', 'समुच्चयबोधक के 2 भेद हैं: समानाधिकरण (समान स्तर के उपवाक्यों को जोड़ने वाले) और व्यधिकरण (आश्रित उपवाक्य जोड़ने वाले)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de9d9329-364e-4177-a7c7-96d0bd53277b', '1. समानाधिकरण समुच्चयबोधक (और, तथा, या, किन्तु, परन्तु, इसलिए) ; 2. व्यधिकरण समुच्चयबोधक (क्योंकि, ताकि, यद्यपि-तथापि, जिससे कि)', true, 'cfeb9c05-2122-49c4-9e29-3dfefee6da4e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('caf49451-409b-4517-b030-c8fbe8c8e152', 'सकर्मक और अकर्मक', false, 'cfeb9c05-2122-49c4-9e29-3dfefee6da4e');
