INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf5531ba-1f12-47b6-8f9b-69281b83aee2', 'व्यक्तिवाचक और जातिवाचक', false, 'cfeb9c05-2122-49c4-9e29-3dfefee6da4e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd5e4ee5-da9e-4232-a063-eb58f129f4fb', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''विद्या के बिना जीवन व्यर्थ है।'' इस वाक्य में ''के बिना'' किस प्रकार का अव्यय है?', '''के बिना'' संज्ञा ''विद्या'' के बाद आकर वाक्य के अन्य शब्दों से संबंध जोड़ रहा है, अतः यह संबंधबोधक अव्यय है।', NOW()) ON CONFLICT DO NOTHING;
