INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7292c394-26b3-4c89-8543-ddfec0fca11f', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''वह विद्यालय नहीं गया क्योंकि वह बीमार था।'' इस वाक्य में ''क्योंकि'' किस प्रकार का समुच्चयबोधक है?', '''क्योंकि'' मुख्य उपवाक्य के साथ कारण बताने वाले आश्रित उपवाक्य को जोड़ता है, अतः यह कारणवाचक व्यधिकरण समुच्चयबोधक है।', NOW()) ON CONFLICT DO NOTHING;
