INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8f26b9ce-f684-4f3d-874d-5a31675a2753', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''शाबाश! तुमने परीक्षा में प्रथम स्थान प्राप्त किया।'' वाक्य में ''शाबाश!'' किस मनोभाव को प्रकट करने वाला विस्मयादिबोधक है?', '''शाबाश!'' प्रशंसा, उत्साह और अनुमोदन व्यक्त करने वाला विस्मयादिबोधक अव्यय है।', NOW()) ON CONFLICT DO NOTHING;
