INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3658269f-1886-4cdf-a82d-f8881cc96bf3', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''राम ने ही यह काम किया है।'' और ''राम ने यह काम भी किया है।'' में ''ही'' और ''भी'' निपात का क्या प्रभाव है?', '''ही'' सीमा/अवधारण (केवल वही) तथा ''भी'' समुच्चय/समावेश (वह भी) का विशिष्ट अर्थगत बल प्रदान करता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb29a599-517d-469f-b190-291ab954db9b', '''ही'' केवल राम पर अनन्य बल देता है (किसी अन्य ने नहीं) ; जबकि ''भी'' अतिरिक्तता/समावेश का बोध कराता है (अन्य के साथ राम ने भी)', true, '3658269f-1886-4cdf-a82d-f8881cc96bf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb9bf438-cf42-4473-81a1-b5eb5f120946', 'दोनों वाक्यों का अर्थ बिल्कुल एकसमान है', false, '3658269f-1886-4cdf-a82d-f8881cc96bf3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bfa779d5-6800-417a-8aac-8c6d3beb9918', 'निपात से वाक्य में कोई परिवर्तन नहीं होता', false, '3658269f-1886-4cdf-a82d-f8881cc96bf3');
