INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('733f1d1b-0c7b-450d-b1df-4539348cfaca', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''भीतर'' शब्द का प्रयोग निम्नलिखित दो वाक्यों में किस रूप में हुआ है?
