INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0030f18c-58f2-4747-a430-1a07762cd69c', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''वह दिनभर पढ़ता रहा।'' वाक्य में ''दिनभर'' में ''भर'' क्या है?', '''भर'' (जैसे: रातभर, दिनभर) व्याप्ति और सीमा पर बल देने वाला निपात है।', NOW()) ON CONFLICT DO NOTHING;
