INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e5c69ac2-f1ed-424c-8b47-0864a99d7d3b', 'प्रत्यय मात्र', false, '0030f18c-58f2-4747-a430-1a07762cd69c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54ea8bf9-98d2-4d2e-a694-3f74450decdb', 'कारक चिह्न', false, '0030f18c-58f2-4747-a430-1a07762cd69c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('41da668c-f429-4090-a4ef-dd0bfe917f68', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', '''अचानक बादल घिर आए और मूसलाधार वर्षा होने लगी।'' वाक्य में ''अचानक'' किस प्रकार का क्रियाविशेषण है?', '''अचानक / एकाएक / सहसा'' क्रिया के घटित होने की आकस्मिक रीति (ढंग) प्रकट करते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcd4f305-73b6-4350-a80f-12e211524780', 'रीतिवाचक क्रियाविशेषण (आकस्मिकता का ढंग)', true, '41da668c-f429-4090-a4ef-dd0bfe917f68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c749de33-2c53-4dc1-a402-1bfac7d13239', 'स्थानवाचक', false, '41da668c-f429-4090-a4ef-dd0bfe917f68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9f18150-29ee-46a5-9606-1a42beacbd5c', 'परिमाणवाचक', false, '41da668c-f429-4090-a4ef-dd0bfe917f68');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdd12174-eab0-4701-aca6-234e5a1e3b0a', 'कालवाचक', false, '41da668c-f429-4090-a4ef-dd0bfe917f68');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('12126911-487d-4eef-8f44-7ed1c668f3e5', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Medium', 'निम्नलिखित में से कौन-सा शब्द ''अव्यय'' (अविकारी) नहीं है?', '''सुंदर'' विशेषण (विकारी) है, जबकि ''और'', ''धीरे-धीरे'', ''किन्तु'' अपरिवर्तनशील अव्यय हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0049c79e-acea-4452-8341-91fa5acaa139', 'सुंदर (विशेषण - विकारी शब्द है ; जैसे: सुंदर, सुंदरी, सुंदरों)', true, '12126911-487d-4eef-8f44-7ed1c668f3e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6b523ec-50ea-46cc-bbe5-523145833622', 'और', false, '12126911-487d-4eef-8f44-7ed1c668f3e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fae5ede5-7dd1-470c-b870-bda69fc8ce47', 'धीरे-धीरे', false, '12126911-487d-4eef-8f44-7ed1c668f3e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('818519a1-3f85-4ee3-b246-23117e68f5f7', 'किन्तु', false, '12126911-487d-4eef-8f44-7ed1c668f3e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3bb9b5b5-99b2-482e-bf1c-396899334e31', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f211c337-d805-4dd0-b2f2-98a2e6bf7c9a', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, '3bb9b5b5-99b2-482e-bf1c-396899334e31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08d44068-1379-4e26-b996-c62665a6e13e', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, '3bb9b5b5-99b2-482e-bf1c-396899334e31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a806a11a-43f9-483a-a3e6-780a6572c011', '(A) सही है, परन्तु (R) गलत है।', false, '3bb9b5b5-99b2-482e-bf1c-396899334e31');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c59e858-fd9c-4c54-bf16-29b783783410', '(A) गलत है, परन्तु (R) सही है।', false, '3bb9b5b5-99b2-482e-bf1c-396899334e31');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3afaef7e-38cc-4d1d-a376-16b0ecaebe60', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', 'Spot the IMPOSTER in the following classification of अव्यय भेदों में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb96e530-b568-451e-86ff-15070133e50c', 'वर्ग 1', false, '3afaef7e-38cc-4d1d-a376-16b0ecaebe60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('100c6eed-6ef6-458d-b63b-a4d143bf4fbf', 'वर्ग 2', false, '3afaef7e-38cc-4d1d-a376-16b0ecaebe60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7e4bb4f-7b07-4628-8abc-29afe266ffd4', 'वर्ग 3', false, '3afaef7e-38cc-4d1d-a376-16b0ecaebe60');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bdf5d11-7a99-47f7-b330-3ae6957ba7b9', 'वर्ग 4 (''पुस्तक'' और ''हिमालय'' संज्ञा शब्द [विकारी] हैं, विस्मयादिबोधक अव्यय नहीं)', true, '3afaef7e-38cc-4d1d-a376-16b0ecaebe60');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('886ad49b-6f72-46e3-bd4e-bfa786254a54', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', 'सुमेलित कीजिए (क्रियाविशेषण के 4 भेद और उनके प्रश्नवाचक पहचान शब्द):
(क) कालवाचक क्रियाविशेषण   -> (i) ''कब'' (When)
(ख) स्थानवाचक क्रियाविशेषण -> (ii) ''कहाँ'' (Where)
(ग) परिमाणवाचक क्रियाविशेषण-> (iii) ''कितना'' (How much)
(घ) रीतिवाचक क्रियाविशेषण   -> (iv) ''कैसे / किस प्रकार'' (How)', 'काल = कब; स्थान = कहाँ; परिमाण = कितना; रीति = कैसे।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fbfa2f3-4788-405c-ae3a-d05211e3cbb0', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, '886ad49b-6f72-46e3-bd4e-bfa786254a54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19040bf4-8913-4f18-be96-e462260ade58', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '886ad49b-6f72-46e3-bd4e-bfa786254a54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62f67482-5686-4502-943a-3e3d038c88e7', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '886ad49b-6f72-46e3-bd4e-bfa786254a54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86dcd74a-fc04-4a31-9217-15b933dc225d', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '886ad49b-6f72-46e3-bd4e-bfa786254a54');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8e36ba37-00a8-422e-888d-da498c399b8e', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', 'समानाधिकरण समुच्चयबोधक के 4 उप-भेदों का सही मिलान कौन-सा है?', 'समानाधिकरण के 4 रूप: संयोजक (जोड़ने वाला), विभाजक (विकल्प), विरोधदर्शक (अंतर), परिणामदर्शक (फलस्वरूप)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('092853e1-b377-4901-8af3-da9bd8f7d213', '1. संयोजक (और, तथा) ; 2. विभाजक (या, अथवा) ; 3. विरोधदर्शक (किन्तु, परन्तु, मगर) ; 4. परिणामदर्शक (इसलिए, अतः, फलस्वरूप)', true, '8e36ba37-00a8-422e-888d-da498c399b8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8dbfc9b5-1f5a-44b0-9b6a-fc923746d8ee', 'संयोजक केवल स्त्रीलिंग होता है', false, '8e36ba37-00a8-422e-888d-da498c399b8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6af2f5a-44ae-4ab0-8aa0-f35e31c2beb4', 'विभाजक में हमेशा नकारात्मक क्रिया होती है', false, '8e36ba37-00a8-422e-888d-da498c399b8e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad64ba6e-a20e-445a-9707-5c6a6c0be98c', 'परिणामदर्शक केवल भविष्यत में आता है', false, '8e36ba37-00a8-422e-888d-da498c399b8e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('df9bdc78-9f0f-49cc-b30c-d6366c05011e', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', 'निम्नलिखित वाक्यों में से किस वाक्य में ''निपात'' का गलत स्थान पर प्रयोग होने से वाक्य का अभीष्ट अर्थ बदल गया है?', 'निपात का स्थान बदलने से वाक्य में बल और अर्थ का केंद्र पूरी तरह बदल जाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('04841561-df5e-4d0b-a947-6f63770e1652', '''केवल उसने मुझे एक पुस्तक दी।'' (अर्थ: सिर्फ उसी व्यक्ति ने दी, किसी और ने नहीं ; यदि ''उसने मुझे केवल एक पुस्तक दी'' लिखा जाए तो अर्थ: सिर्फ एक ही पुस्तक दी)', true, 'df9bdc78-9f0f-49cc-b30c-d6366c05011e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61b3bdd1-bc6a-4d80-be2d-cadc50ae593f', '''वह कल आएगा।''', false, 'df9bdc78-9f0f-49cc-b30c-d6366c05011e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08549275-be28-42f2-b012-d8edb8bc0b07', '''हम सब भारतवासी हैं।''', false, 'df9bdc78-9f0f-49cc-b30c-d6366c05011e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7855cc8a-7798-42fa-ab86-8e35fc6c231e', '''सत्य की सदैव विजय होती है।''', false, 'df9bdc78-9f0f-49cc-b30c-d6366c05011e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59501b27-9938-420b-b939-354153f513b1', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', '''यद्यपि वह निर्धन है तथापि अत्यंत ईमानदार है।'' वाक्य में ''यद्यपि...तथापि'' किस प्रकार का समुच्चयबोधक युग्म है?', '''यद्यपि...तथापि'' / ''यदि...तो'' संकेतवाचक व्यधिकरण समुच्चयबोधक युग्म (Correlative conjunctions) हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c771ed5d-4a53-4f04-a675-c444cde4f03a', 'संकेतवाचक / विरोधसूचक व्यधिकरण समुच्चयबोधक', true, '59501b27-9938-420b-b939-354153f513b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('155a161b-b2f1-44fc-a064-5d6c302db57b', 'संयोजक समानाधिकरण', false, '59501b27-9938-420b-b939-354153f513b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e2166333-7412-488c-9f85-c55b6facf7b7', 'विभाजक', false, '59501b27-9938-420b-b939-354153f513b1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba88f1e9-1aaa-4a25-8b09-c90e5e114ab1', 'उद्देश्यवाचक', false, '59501b27-9938-420b-b939-354153f513b1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('47a50a1d-1dc5-454c-90ce-1f2a7b344daf', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', 'क्रियाविशेषण की रचना के आधार पर ''मूल क्रियाविशेषण'' और ''यौगिक क्रियाविशेषण'' में क्या अंतर होता है?', 'मूल क्रियाविशेषण रूढ़ होते हैं; यौगिक क्रियाविशेषण प्रत्यय योग, समास अथवा शब्द-युग्मों की द्विरुक्ति से निर्मित होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c2367df-2684-43e6-813d-d3a1be577cb4', 'मूल क्रियाविशेषण बिना किसी प्रत्यय या रूपांतरण के स्वतंत्र रूप में आते हैं (जैसे: ठीक, अचानक, दूर, पास) ; जबकि यौगिक क्रियाविशेषण प्रत्यय, समास या द्विरुक्ति से बनते हैं (जैसे: प्रेमपूर्वक, हाथों-हाथ, धीरे-धीरे, प्रतिदिन)', true, '47a50a1d-1dc5-454c-90ce-1f2a7b344daf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10859f09-399f-4b62-be73-594e88445e3b', 'दोनों में कोई अंतर नहीं होता', false, '47a50a1d-1dc5-454c-90ce-1f2a7b344daf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1352c44-0740-468c-91ae-eaa97c577798', 'मूल क्रियाविशेषण केवल एक अक्षर का होता है', false, '47a50a1d-1dc5-454c-90ce-1f2a7b344daf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05420628-1c19-49c5-b80b-1355605539fa', 'यौगिक क्रियाविशेषण केवल संस्कृत में होते हैं', false, '47a50a1d-1dc5-454c-90ce-1f2a7b344daf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('568bed35-440f-43ab-bc14-c050c65f5509', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', '''सावधान! आगे गहरा गड्ढा है।'' वाक्य में ''सावधान!'' किस प्रकार का विस्मयादिबोधक है?', '''सावधान! / होशियार! / बचो!'' आने वाले खतरे के प्रति सतर्क करने वाले चेतावनीसूचक विस्मयादिबोधक अव्यय हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddcf731f-408a-4932-86b4-2a38a92ee535', 'चेतावनीसूचक विस्मयादिबोधक', true, '568bed35-440f-43ab-bc14-c050c65f5509');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6fffd417-372f-47c5-b648-3e2947037ae0', 'हर्षसूचक', false, '568bed35-440f-43ab-bc14-c050c65f5509');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f4773d7-4e38-4ff0-aead-8df5236d4460', 'शोकसूचक', false, '568bed35-440f-43ab-bc14-c050c65f5509');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ac229c7-61fc-4929-b7c7-300a1d91e951', 'संबोधनसूचक', false, '568bed35-440f-43ab-bc14-c050c65f5509');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9896d838-9bf5-4fd3-b80e-1572328fefc7', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', 'निम्नलिखित में से किस वाक्य में ''स्थानवाचक क्रियाविशेषण'' का शुद्ध प्रयोग हुआ है?', '''चारों ओर / इधर-उधर / सर्वत्र'' स्थान व दिशा का बोध कराने वाले स्थानवाचक क्रियाविशेषण हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fa53fa0-61e0-4dc7-80e1-029c119aabad', '''पक्षी आकाश में चारों ओर उड़ रहे हैं।'' (''चारों ओर'' क्रिया के घटित होने की दिशा/स्थान बता रहा है)', true, '9896d838-9bf5-4fd3-b80e-1572328fefc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca3e0c6b-fbaa-42e5-a704-f77f407bd501', '''वह कल आएगा।''', false, '9896d838-9bf5-4fd3-b80e-1572328fefc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc475bc3-723f-468e-8b7c-b7e70ea3b869', '''उसने बहुत खाया।''', false, '9896d838-9bf5-4fd3-b80e-1572328fefc7');
