INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9b43765a-61e9-4614-8ec5-79f93a957cfb', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', '''हाय! बेचारा दुर्घटना में घायल हो गया।'' वाक्य में ''हाय!'' किस मनोभाव को व्यक्त करता है?', '''हाय! / उफ़! / आह!'' दुःख, वेदना और शोक की तीव्र भावात्मक अभिव्यक्ति करते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db2ff319-7e6c-4cab-b8a4-6eef92d7b937', 'शोक / पीड़ा / सहानुभूति का भाव', true, '9b43765a-61e9-4614-8ec5-79f93a957cfb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('364d3b5d-d16c-4ead-bcc6-359003fa3c8d', 'प्रसन्नता का भाव', false, '9b43765a-61e9-4614-8ec5-79f93a957cfb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17bd3c70-4e3f-4146-b10f-3d3a037faed4', 'क्रोध का भाव', false, '9b43765a-61e9-4614-8ec5-79f93a957cfb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1fb16d4b-42d2-4038-9876-1c282072ba30', 'उल्लास का भाव', false, '9b43765a-61e9-4614-8ec5-79f93a957cfb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e7089a1c-3c98-41cd-92d2-e28a4402ee47', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', 'प्रमुख 9 निपातों (ही, भी, तो, तक, मात्र, भर, केवल, सा, जी) का वाक्य में क्या सर्वोच्च प्रयोजन होता है?', 'निपात वाक्य में विशेष अर्थगत अवधारण, आग्रह, सीमा अथवा बल की सूक्ष्म अभिव्यक्ति हेतु प्रयुक्त होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0936cc3-139b-4b51-a8e9-ff27d8525c20', 'ये किसी पद के साथ प्रयुक्त होकर उसके अर्थ को सीमित, निश्चित, विस्तारित या विशिष्ट भावात्मक बल (Emphatic force) प्रदान करते हैं', true, 'e7089a1c-3c98-41cd-92d2-e28a4402ee47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62aae26a-a990-4f68-824d-75b925ab57b8', 'ये केवल वाक्य को लंबा बनाते हैं', false, 'e7089a1c-3c98-41cd-92d2-e28a4402ee47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c70f96fc-c4a2-4f28-a2c0-3da1152ec0d1', 'ये संज्ञा का लिंग बदल देते हैं', false, 'e7089a1c-3c98-41cd-92d2-e28a4402ee47');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d0f821f-2a90-4272-927f-37c428f98efb', 'ये क्रिया को भूतकाल में बदल देते हैं', false, 'e7089a1c-3c98-41cd-92d2-e28a4402ee47');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('42e9e9f3-7e3c-434c-b84b-1f3b7039dec7', 'Class 7', 'Hindi Grammar', 'Chapter 11: अव्यय / अविकारी शब्द', 'Hard', 'अव्यय (अविकारी शब्दों) का हिंदी भाषा संरचना में क्या केंद्रीय महत्व है?', 'अव्यय भाषा की तार्किक सुसंबद्धता (Cohesion), मनोभाव प्रकटन और संश्लिष्ट वाक्य-संयोजन के अनिवार्य माध्यम हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('563c72ce-9937-4f9b-b91e-8f5e4961dd50', 'अव्यय भाषा को सुगठित, प्रवाहपूर्ण और तार्किक बनाते हैं; ये उपवाक्यों को जोड़ते हैं, क्रिया की सटीक परिस्थितियाँ स्पष्ट करते हैं, और भाषा में सूक्ष्म मनोभावों तथा अर्थ-बल का संचार करते हैं', true, '42e9e9f3-7e3c-434c-b84b-1f3b7039dec7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3708575e-3eb6-49b4-8543-68446bff945b', 'अव्यय केवल कविताओं में प्रयुक्त होते हैं', false, '42e9e9f3-7e3c-434c-b84b-1f3b7039dec7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b05d362-c6b4-416f-a618-8bced3ab1f97', 'इनके बिना भी भाषा का रूप अपरिवर्तित रहता है', false, '42e9e9f3-7e3c-434c-b84b-1f3b7039dec7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a98e71e-a443-491c-afb2-d3eeca1c3022', 'अव्यय का भाषा में कोई महत्व नहीं है', false, '42e9e9f3-7e3c-434c-b84b-1f3b7039dec7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ed07e6d-fd18-4270-b998-9b10e6f8323e', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'What is the continuous roof-like overhead layer formed by the leafy branches and foliage of tall trees in a dense forest called?', 'The canopy is the uppermost continuous ceiling formed by the interlocking leafy crowns of mature tall trees in a forest.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbc5b18f-4674-4eca-9a00-9d51622eeada', 'The Canopy', true, '7ed07e6d-fd18-4270-b998-9b10e6f8323e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('731d9d66-3cb0-4e00-8afb-a9d249dd7f7e', 'The Crown', false, '7ed07e6d-fd18-4270-b998-9b10e6f8323e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66e487bd-d34a-4813-b710-ce4a8208cfe3', 'The Understorey', false, '7ed07e6d-fd18-4270-b998-9b10e6f8323e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e50745aa-f13f-4334-91fd-f0c71515dfb3', 'The Forest Floor', false, '7ed07e6d-fd18-4270-b998-9b10e6f8323e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f1e25d3b-b56c-4de2-b7d9-e94531e1314e', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'What is the branchy upper part of an individual tree above the stem or trunk called?', 'The crown is the top portion of a tree comprising branches, twigs, and foliage radiating outward above the trunk.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bad4ef0-c275-4348-a64f-629e968035b7', 'The Crown of the tree', true, 'f1e25d3b-b56c-4de2-b7d9-e94531e1314e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efa257c9-676f-4f53-b256-76cc36592683', 'The Canopy', false, 'f1e25d3b-b56c-4de2-b7d9-e94531e1314e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f82f5a0-96b7-4ca9-aa78-631b9879d602', 'The Understorey', false, 'f1e25d3b-b56c-4de2-b7d9-e94531e1314e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd7f90fb-a358-4961-825d-0b8516ea8d3a', 'The Root system', false, 'f1e25d3b-b56c-4de2-b7d9-e94531e1314e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e77816a0-f16a-46e4-95e1-ad17509b9e73', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'What are the horizontal vegetation layers of smaller trees, shrubs, tall herbs, and grasses growing beneath the high canopy called?', 'The understorey consists of intermediate vegetation strata (small trees, shrubs, bushes, herbs) thriving in the shade below the canopy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5004eacd-5eb4-4a0e-92cf-dc8e71a117d8', 'The Understorey', true, 'e77816a0-f16a-46e4-95e1-ad17509b9e73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38812f64-1ace-476b-9b18-4560cb59a2d2', 'The Canopy', false, 'e77816a0-f16a-46e4-95e1-ad17509b9e73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1a24233c-adda-4fe2-b710-dab64bab8283', 'The Crown', false, 'e77816a0-f16a-46e4-95e1-ad17509b9e73');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e301b926-ec70-4725-a5b1-ec1786e86e03', 'The Soil layer', false, 'e77816a0-f16a-46e4-95e1-ad17509b9e73');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8b07a3bd-34c5-44ce-aae6-b9f5e61cab1a', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'Why are forests celebrated and referred to as the ''GREEN LUNGS'' of our planet?', 'Forests regulate planetary gas exchange: green plants fix carbon dioxide and release life-sustaining oxygen during photosynthesis.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11d5d51a-cc08-4889-8400-b7df25fdcfbf', 'Through photosynthesis, forest trees release vast amounts of OXYGEN into the atmosphere and absorb CARBON DIOXIDE, maintaining atmospheric gas balance', true, '8b07a3bd-34c5-44ce-aae6-b9f5e61cab1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e89a49ca-abd0-4154-9445-1e28ff4da951', 'Because trees are green in color', false, '8b07a3bd-34c5-44ce-aae6-b9f5e61cab1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e44f58aa-0138-4079-8304-81c134ad5a4d', 'Because leaves look like human lungs', false, '8b07a3bd-34c5-44ce-aae6-b9f5e61cab1a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5032bef1-bfe7-4aca-85e7-852a21d85458', 'Because animals sleep in forests', false, '8b07a3bd-34c5-44ce-aae6-b9f5e61cab1a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0b7fd730-c745-4c20-aede-3c765db821c4', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'What are the specialized micro-organisms (bacteria and fungi) that break down dead plant and animal matter into dark, nutrient-rich HUMUS called?', 'Decomposers recycle organic biomass by converting decaying detritus into dark fertile humus that replenishes soil nutrients.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('698e16f1-b214-456c-a584-9fee4fbbf55d', 'Decomposers (Saprophytes)', true, '0b7fd730-c745-4c20-aede-3c765db821c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb42d1a5-8d94-4a43-960c-ec09337390ba', 'Producers', false, '0b7fd730-c745-4c20-aede-3c765db821c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a218a83e-7d2f-4c3b-a1f4-396475b4ea9a', 'Herbivores', false, '0b7fd730-c745-4c20-aede-3c765db821c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52f6ab5c-5db0-4f07-a1bb-7b56ea3f36f7', 'Carnivores', false, '0b7fd730-c745-4c20-aede-3c765db821c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c71c35fe-2493-48b1-9a0d-a89dd5185559', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'How do forest tree root systems and the forest floor prevent destructive FLASH FLOODS and SOIL EROSION?', 'Forest leaf litter and dense root networks decelerate raindrops, arrest surface runoff, facilitate groundwater percolation, and bind topsoil.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('075b609b-c6ee-4e67-b8ea-b1b0e1711aba', 'The thick forest floor and root networks act as a giant natural sponge, slowing down rainwater runoff, allowing water to seep into the ground to recharge groundwater', true, 'c71c35fe-2493-48b1-9a0d-a89dd5185559');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ece76310-d601-4bd5-bd66-f66d2ed4f962', 'Trees block rain from falling from clouds', false, 'c71c35fe-2493-48b1-9a0d-a89dd5185559');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed9eeedd-7ce1-47ca-ad58-dc5bbc3d4a05', 'Trees push water into the ocean directly', false, 'c71c35fe-2493-48b1-9a0d-a89dd5185559');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0194d61-827c-485c-b5de-4100e2a75fa5', 'Trees turn rainwater into solid ice', false, 'c71c35fe-2493-48b1-9a0d-a89dd5185559');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6f58409e-523b-434a-9494-0879e2364249', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'What is ''SEWAGE'' in environmental science?', 'Sewage is municipal liquid waste carrying fecal matter, detergents, pathogens, organic refuse, and hazardous chemical contaminants.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2a0d00d-edeb-4c98-8040-23d41b69429c', 'Liquid wastewater produced by households, industries, hospitals, and commercial establishments carrying dissolved and suspended contaminants', true, '6f58409e-523b-434a-9494-0879e2364249');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bdc8745-2f49-4e86-a601-4fbdc0c04c2e', 'Clean drinking water from mountain streams', false, '6f58409e-523b-434a-9494-0879e2364249');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('252c13dd-5ba7-4def-9cbf-eb022a13315d', 'Rainwater stored in reservoirs', false, '6f58409e-523b-434a-9494-0879e2364249');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2916a7ac-1a60-4aa4-87cf-ffcbeb4a2a3b', 'Solid garbage collected in trucks', false, '6f58409e-523b-434a-9494-0879e2364249');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('36144df0-efe0-4ab3-8e65-92dd52d23b01', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'What does the technological abbreviation ''WWTP'' stand for in municipal water management?', 'A Wastewater Treatment Plant (WWTP) is a facility that removes physical, biological, and chemical pollutants from sewage water.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('839a29c0-d385-45f0-98e2-529d8da91197', 'Wastewater Treatment Plant', true, '36144df0-efe0-4ab3-8e65-92dd52d23b01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cc988d1-6699-4ec8-856b-cf035ee0edf5', 'Water Wind Turbine Project', false, '36144df0-efe0-4ab3-8e65-92dd52d23b01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e56fcea-354e-45ba-b9a6-dcac3f559148', 'Waste Weather Temperature Program', false, '36144df0-efe0-4ab3-8e65-92dd52d23b01');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('374e3e76-b833-45db-b397-48f049e1893f', 'Worldwide Tanker Petroleum', false, '36144df0-efe0-4ab3-8e65-92dd52d23b01');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a3635684-534a-4c8b-be6b-010bcd234f77', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'In the first primary stage of a WWTP, what mechanical filters are used to screen out large physical debris such as rags, plastic bottles, sticks, and cans?', 'Bar screens are vertical metal grids that intercept and remove coarse floating solids (plastics, rags, wood) from raw sewage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('610fb3f3-e1ee-43fb-b0d6-f0eb7d579a8b', 'Bar Screens', true, 'a3635684-534a-4c8b-be6b-010bcd234f77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3b46156d-ed3d-4f56-bb2c-61c9503e0556', 'Sand filters', false, 'a3635684-534a-4c8b-be6b-010bcd234f77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b733bec-11ca-49ef-9496-01dc5d760cad', 'Aeration tanks', false, 'a3635684-534a-4c8b-be6b-010bcd234f77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3a89f2d-478c-4d66-a304-f75e48c5d9b4', 'Chlorine chambers', false, 'a3635684-534a-4c8b-be6b-010bcd234f77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd18816a-8a82-4015-abeb-f36465e7dbfc', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'What is the semi-solid organic matter that settles at the bottom of the large central sedimentation tank (clarifier) in a WWTP called?', 'Sludge is the settled organic particulate matter scraped from clarifier bottoms, subsequently digested in anaerobic bio-reactors.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2bc0dac1-83ba-4585-9c23-fc308b3b9b20', 'Sludge (Primary / Activated Sludge)', true, 'dd18816a-8a82-4015-abeb-f36465e7dbfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce20a5c8-289b-438c-885b-fd1c5f348eb3', 'Grit', false, 'dd18816a-8a82-4015-abeb-f36465e7dbfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4903f593-02a3-4a0b-b6d0-71716441c93c', 'Scum', false, 'dd18816a-8a82-4015-abeb-f36465e7dbfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b7a1a9b-b199-42d1-9740-55355a21f9d1', 'Foam', false, 'dd18816a-8a82-4015-abeb-f36465e7dbfc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4e139b33-88fa-43d3-ac56-20af662f011e', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'What common disinfectant chemical (or gas) is added to treated wastewater before releasing it into rivers to kill harmful disease-causing microbes?', 'Chlorination (or UV irradiation/ozonation) oxidizes and eradicates pathogenic bacteria, viruses, and parasites before environmental discharge.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('090ea734-fddc-4980-abe8-f06e71c35c32', 'Chlorine (or Ozone / Ultraviolet Light)', true, '4e139b33-88fa-43d3-ac56-20af662f011e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d3bca170-15df-4fc9-81fa-8eb22dd4b754', 'Salt', false, '4e139b33-88fa-43d3-ac56-20af662f011e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c539815-9667-47e1-bc6b-ad569505eaa0', 'Sugar', false, '4e139b33-88fa-43d3-ac56-20af662f011e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('726ca7d4-2048-44fc-8616-a5cefa802e4d', 'Sulfuric acid', false, '4e139b33-88fa-43d3-ac56-20af662f011e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d6ab39cf-8904-4e48-9084-8a122fb5a7c7', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Easy', 'Which fast-growing tree species is recommended to be planted alongside wastewater sewage ponds because it absorbs surplus wastewater rapidly and releases pure water vapor into the air?', 'Eucalyptus trees have high transpiration rates, absorbing large volumes of wastewater and purifying groundwater bio-ecologically.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02e6a7d8-3931-4690-929c-8cc8fb65da99', 'Eucalyptus Trees', true, 'd6ab39cf-8904-4e48-9084-8a122fb5a7c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cdbe04e-e9d7-4d3d-bc48-11a4aa7c3bfc', 'Cactus', false, 'd6ab39cf-8904-4e48-9084-8a122fb5a7c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('127bc2fe-31b3-476c-96a0-390406de71d1', 'Banyan Tree', false, 'd6ab39cf-8904-4e48-9084-8a122fb5a7c7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd78f467-4586-401f-8475-a8bc0bc47238', 'Pine Tree', false, 'd6ab39cf-8904-4e48-9084-8a122fb5a7c7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('49cdaad6-6c4c-4a10-9bba-1dc24cf376d1', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'Why is a forest referred to as a ''DYNAMIC LIVING ENTITY — FULL OF LIFE AND VITALITY''?', 'Forest ecosystems exhibit complex trophic self-regulation: producers, consumers, and decomposers recycle matter in an enduring dynamic equilibrium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ebc9679c-24d7-47b2-b986-9d5a3a5fdfc3', 'It sustains an interconnected web of diverse flora, fauna, insects, and decomposers where nutrients are endlessly recycled, energy flows continuously, and life regenerates autonomously', true, '49cdaad6-6c4c-4a10-9bba-1dc24cf376d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a8b866e-0312-49d8-81ff-639df791b9d1', 'Because trees walk around at night', false, '49cdaad6-6c4c-4a10-9bba-1dc24cf376d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f791dd2-64c1-43ba-ab88-8af77efd138d', 'Because it is powered by electric generators', false, '49cdaad6-6c4c-4a10-9bba-1dc24cf376d1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e797203-aa18-422c-8d44-73a0dcbc8e9a', 'Because humans plant every tree every year', false, '49cdaad6-6c4c-4a10-9bba-1dc24cf376d1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58571f8e-c092-469d-93ec-c4e31e6d6918', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What occurs during the ''AERATION'' stage in a modern Wastewater Treatment Plant?', 'Aeration tanks supply dissolved oxygen to heterotrophic aerobic microorganisms, accelerating the biological decomposition of organic pollutants.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d77f158a-1b6a-4765-8d66-3671b272d268', 'Compressed air is vigorously pumped into clarified wastewater to stimulate the rapid growth of AEROBIC BACTERIA that consume human waste, food residue, and soaps', true, '58571f8e-c092-469d-93ec-c4e31e6d6918');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06a3ade8-2fc3-4411-a0bd-e0599601d7a8', 'Water is frozen into solid ice blocks', false, '58571f8e-c092-469d-93ec-c4e31e6d6918');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa3a1e8a-3ed4-4645-9cef-3bb557ca9dea', 'Water is boiled in giant furnaces', false, '58571f8e-c092-469d-93ec-c4e31e6d6918');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c18f6a7-bbc6-4029-b596-9f605768ccca', 'Chemicals are added to dye the water blue', false, '58571f8e-c092-469d-93ec-c4e31e6d6918');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82cc233b-3036-4ee5-b0d9-d7753775e6e4', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'How is the organic ''Sludge'' collected from clarifier tanks beneficially utilized in sustainable waste management?', 'Anaerobic sludge digestion yields methane-rich biogas for renewable energy and sterile bio-solids for agricultural soil fertilization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd124a47-9f12-4134-b43f-c551b4d9b2c4', 'It is transferred to closed digester tanks where ANAEROBIC BACTERIA decompose it, producing BIOGAS (used as fuel/electricity) and nutrient-rich manure for farming', true, '82cc233b-3036-4ee5-b0d9-d7753775e6e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51a10ce0-d098-4d7d-b15f-d5dd9a90b9b7', 'It is thrown into the ocean', false, '82cc233b-3036-4ee5-b0d9-d7753775e6e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('782150da-39e4-4885-ad80-e82161c20a5c', 'It is turned into plastic toys', false, '82cc233b-3036-4ee5-b0d9-d7753775e6e4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d18ea4fa-8639-4227-980a-28b5496ac5a7', 'It is burned as coal in train engines', false, '82cc233b-3036-4ee5-b0d9-d7753775e6e4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('174b5dac-8890-4ddc-adbb-08191ee288a7', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'Why should used cooking oils and animal fats NEVER be poured down domestic kitchen sink drains?', 'Cooking fats congeal into stubborn ''fatbergs'', obstructing sewer lines and coating soil particles, which impedes wastewater filtration.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85b35be8-090a-4f86-9428-2d163bde309e', 'Fats harden and solidify inside drain pipes, clogging plumbing, and in open drains they block soil pores, impairing natural water filtration', true, '174b5dac-8890-4ddc-adbb-08191ee288a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf6ee20e-a71d-439a-9a91-ec8aba18fd40', 'Fats attract fish into the pipes', false, '174b5dac-8890-4ddc-adbb-08191ee288a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27c6cab2-27c7-496a-9277-6c8b76c8c883', 'Fats make water smell like roses', false, '174b5dac-8890-4ddc-adbb-08191ee288a7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c72f868-8c81-44fe-be5c-c36f9163e242', 'Fats dissolve metal pipes instantly', false, '174b5dac-8890-4ddc-adbb-08191ee288a7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bce7405c-d9a3-42ba-b1ca-c746700044e6', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'Why should discarded chemical paints, solvents, motor oil, and expired medicines not be thrown into toilets or drains?', 'Toxic chemicals and pharmaceuticals poison the beneficial biocatalytic bacterial populations essential for biological sewage purification.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('917bd6b8-e1e7-432c-8ca1-3459a2f3559d', 'These toxic chemicals kill the beneficial microbes in wastewater treatment plants that naturally break down sewage waste', true, 'bce7405c-d9a3-42ba-b1ca-c746700044e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('514d5c5f-1284-4bef-bd9e-1d21736a3a87', 'They cause water to turn into solid rock', false, 'bce7405c-d9a3-42ba-b1ca-c746700044e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dffc20d-ec15-4fca-8f49-f5d99db87b58', 'They make water too clear to see', false, 'bce7405c-d9a3-42ba-b1ca-c746700044e6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bddd54b-d60a-4c10-b3ff-285d6eb22757', 'They freeze the sewer pipes', false, 'bce7405c-d9a3-42ba-b1ca-c746700044e6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('402590a1-1184-4819-b3bb-435c894cba28', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What is a ''Septic Tank'' on-site sewage disposal system?', 'Septic tanks provide decentralized on-site anaerobic sewage digestion and effluent soil absorption for unsewered locations.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be879db6-ca01-4980-a185-8e35a15bdc81', 'A watertight underground settling chamber where sewage decomposes anaerobically; suitable for isolated homes, rural hospitals, or clusters of houses without municipal sewer networks', true, '402590a1-1184-4819-b3bb-435c894cba28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('db6a659a-59d7-4753-b559-7b47c9a09aa3', 'A large tank that stores clean rainwater', false, '402590a1-1184-4819-b3bb-435c894cba28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e1e9ef64-7744-446d-b290-6c5c514893c1', 'A truck that transports bottled water', false, '402590a1-1184-4819-b3bb-435c894cba28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9813a6ad-d5d1-4fb4-8046-bd62d5432bcd', 'A chemical factory making fertilizers', false, '402590a1-1184-4819-b3bb-435c894cba28');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('90e4a8a5-7168-4650-a3d5-a18672b60abb', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What is the ''Vermi-Processing Toilet'' developed and tested successfully in India?', 'Vermi-toilets utilize earthworms to bioconvert human fecal sludge into odorless, pathogen-free, high-grade organic vermicompost.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01d2958e-aecd-423b-96f8-8024a3add4b4', 'A low-cost, hygienic, water-saving toilet system where earthworms (like red worms) completely process human excreta into high-nutrient vermicompost cakes', true, '90e4a8a5-7168-4650-a3d5-a18672b60abb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62eccac7-fd3b-473a-b360-c68c4bf35e17', 'A toilet with electric heaters', false, '90e4a8a5-7168-4650-a3d5-a18672b60abb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a459729-6bb1-40b5-b5e5-3a8d2bc0bd6e', 'A toilet connected to car engines', false, '90e4a8a5-7168-4650-a3d5-a18672b60abb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27628377-cfe3-41f3-a2ff-682f8e14285c', 'A toilet that uses chemical gases', false, '90e4a8a5-7168-4650-a3d5-a18672b60abb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e8352f72-c04c-4cd0-8c94-6559f88c85f8', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'How do forests influence the local atmospheric CLIMATE and the WATER CYCLE?', 'Evapotranspiration from forest canopies generates regional atmospheric moisture flux, lowering surface temperatures and promoting convective precipitation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('860dfaf1-390f-40a7-8bae-9d8700c7619b', 'Forests transpire enormous volumes of water vapor into the air through their leaves, cooling the ambient climate, increasing atmospheric humidity, and inducing rainfall', true, 'e8352f72-c04c-4cd0-8c94-6559f88c85f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fd6130cb-f779-48fb-93a5-5bfbc83ee7b3', 'Forests heat the air like stoves', false, 'e8352f72-c04c-4cd0-8c94-6559f88c85f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('105f1812-7003-4a7a-bf32-a4d8858c5126', 'Forests absorb all clouds', false, 'e8352f72-c04c-4cd0-8c94-6559f88c85f8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ee89446-68aa-4f67-9f64-34a0b43e4d5f', 'Forests stop winds from blowing', false, 'e8352f72-c04c-4cd0-8c94-6559f88c85f8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9a248d54-bd9a-4576-bc09-d4304c11663f', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'Consider a typical forest food chain: Grass → Insects → Frog → Snake → Eagle. What happens if all the FROGS are removed from this ecosystem?', 'Trophic cascade: removing intermediate secondary consumers (frogs) triggers pest outbreaks at lower levels and predator starvation at higher levels.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f091decf-5d62-4fff-a857-59f5e59e6e7e', 'The population of insects will explode and damage vegetation, while snakes will face food scarcity and starve, destabilizing the food web', true, '9a248d54-bd9a-4576-bc09-d4304c11663f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f0f54cdc-0875-4b56-9030-1f062087db79', 'Eagles will start eating grass', false, '9a248d54-bd9a-4576-bc09-d4304c11663f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2340b75e-59f1-4bfc-8779-8beb4ff35569', 'Nothing will change in the forest', false, '9a248d54-bd9a-4576-bc09-d4304c11663f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fcc29b0c-2fe5-41a7-a790-396a3a904f9b', 'Grass will stop growing', false, '9a248d54-bd9a-4576-bc09-d4304c11663f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('35522826-79fd-422f-95c2-9a87faec1e8c', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What is ''Scum'' in a WWTP sedimentation clarifier tank?', 'Low-density floatable contaminants (fats, oils, grease) float to the surface as scum and are skimmed off mechanically.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8652193-edc0-4f89-94b6-ea13204cc45f', 'Light, floatable impurities such as oils, grease, and fats that float on the water surface and are removed by a specialized mechanical skimmer', true, '35522826-79fd-422f-95c2-9a87faec1e8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fcd5423-efd6-47cd-9aaf-a5cecac8ad85', 'Heavy rocks at the bottom', false, '35522826-79fd-422f-95c2-9a87faec1e8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('267e80a0-269d-4fff-be37-32071693b0e2', 'Air bubbles in the pipes', false, '35522826-79fd-422f-95c2-9a87faec1e8c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10a71576-6ce4-4f19-a4ee-5235a282bd20', 'Clean water flowing out', false, '35522826-79fd-422f-95c2-9a87faec1e8c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('21e23419-cb2c-4cc5-8687-5ede11fb1976', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What is ''Grit and Sand Removal'' in a WWTP?', 'Velocity retardation in grit chambers causes dense mineral particles (sand, gravel) to precipitate out without settling organic matter.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fad4bbc8-0272-4c49-87df-71651c282a25', 'Wastewater passes through a tank at a reduced velocity so that heavy coarse sand, grit, and small pebbles settle down by gravity', true, '21e23419-cb2c-4cc5-8687-5ede11fb1976');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dee58ef9-6b45-4b38-a76c-884d96f7a4ce', 'Water is filtered through silk cloth', false, '21e23419-cb2c-4cc5-8687-5ede11fb1976');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1979b446-2b42-4801-8271-33154ef1f53c', 'Water is spun in a centrifuge', false, '21e23419-cb2c-4cc5-8687-5ede11fb1976');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f2c46a9-c105-42ef-8364-68649a642efb', 'Sand is added to make water cleaner', false, '21e23419-cb2c-4cc5-8687-5ede11fb1976');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3a439d48-0365-4265-990e-12fa7003168f', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'Why does deforestation lead to severe SOIL EROSION and LAND DEGRADATION?', 'Arbor root networks anchor soil horizons; deforested slopes suffer catastrophic topsoil sheet wash, rill erosion, and desertification.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bcc23b0-b794-480b-b571-219a63f8bfb0', 'Tree roots physically bind the soil together; in the absence of trees, heavy rain and wind wash away the fertile topsoil, turning fertile land into barren desert (desertification)', true, '3a439d48-0365-4265-990e-12fa7003168f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c7f02d38-0ad0-44dd-b6ba-8b736a200282', 'Because trees eat the soil', false, '3a439d48-0365-4265-990e-12fa7003168f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c8d0b55-aa3e-4880-b53d-cb76103cc9bf', 'Because dead roots turn into water', false, '3a439d48-0365-4265-990e-12fa7003168f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d11abd3d-6c4e-4bb4-ad8a-7aa465fb22a7', 'Because wind cannot blow in forests', false, '3a439d48-0365-4265-990e-12fa7003168f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5f08c94d-7a6a-4bab-91ff-e7997eda2d2c', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What deadly water-borne diseases are transmitted by untreated municipal sewage contaminating drinking water sources?', 'Untreated fecal wastewater contains microbial pathogens (Vibrio cholerae, Salmonella typhi, Entamoeba) that cause lethal diarrheal epidemics.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb41e876-b3f9-4f2b-a83d-19f0e5c8d1a1', 'Cholera, Typhoid, Dysentery, Hepatitis, and Polio', true, '5f08c94d-7a6a-4bab-91ff-e7997eda2d2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6354a9c-e466-43d7-8790-b36b2bd50d90', 'Malaria and Dengue only', false, '5f08c94d-7a6a-4bab-91ff-e7997eda2d2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb663206-ec86-4803-b781-602b6f502972', 'Asthma and Bronchitis', false, '5f08c94d-7a6a-4bab-91ff-e7997eda2d2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('675fd85e-37df-4af9-b124-5618c198e820', 'Diabetes and Hypertension', false, '5f08c94d-7a6a-4bab-91ff-e7997eda2d2c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59b7d738-cd75-4b25-a3c3-3da7e93f2c81', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What is ''Activated Sludge'' produced in the aeration tank of a WWTP?', 'Activated sludge is a living microbial floc of active aerobic decomposers that digest organic pollutants in aeration basins.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90ba4692-9b4d-447d-804f-62268329f59b', 'A concentrated biological mass consisting of millions of active aerobic bacteria, protozoa, and suspended organic matter (~97% water)', true, '59b7d738-cd75-4b25-a3c3-3da7e93f2c81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24eff3d2-8e9f-4f55-8e0e-bdaa7c7d0a84', 'A radioactive sludge', false, '59b7d738-cd75-4b25-a3c3-3da7e93f2c81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b20d616-abc0-45c0-b213-95ad39ccfa5d', 'Sludge mixed with gasoline', false, '59b7d738-cd75-4b25-a3c3-3da7e93f2c81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40a955a2-907a-48f6-8794-664817edd713', 'Solid plastic powder', false, '59b7d738-cd75-4b25-a3c3-3da7e93f2c81');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('031d040a-6431-4731-9861-4d0d4718e337', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What is the primary role of forest tree canopy in regulating the impact of HEAVY MONSOON RAINS on soil?', 'Canopy interception dissipates the destructive kinetic energy of torrential rain, converting erosive downpours into gentle stemflow and leaf drip.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c525ad50-d84f-41c3-8781-318e1e8d6eb2', 'The multi-tiered canopy intercept the falling raindrops, breaking their kinetic velocity so that water drips gently down branches and trunks, preventing soil compaction', true, '031d040a-6431-4731-9861-4d0d4718e337');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eea9f213-1903-40f4-a855-b9d99bb6a4b0', 'It completely evaporates all rain before it reaches the ground', false, '031d040a-6431-4731-9861-4d0d4718e337');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7879d2ad-5b88-415d-8458-3c1f63d2bea0', 'It turns rain into hail', false, '031d040a-6431-4731-9861-4d0d4718e337');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('149caa16-8699-400d-83d8-6efb7501dc41', 'It reflects rain back into clouds', false, '031d040a-6431-4731-9861-4d0d4718e337');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1c0a9212-9a44-446f-b76b-69b2ddf92b48', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Medium', 'What is a ''Manhole'' in urban municipal sewerage systems?', 'Manholes provide vital physical maintenance entry points along subterranean sewer networks at standardized intervals and directional junctions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9df38c4-c6ac-48e7-873a-fa292c07fda1', 'An access opening located every 50 to 60 metres along sewer lines, at junctions and bends, allowing sanitary workers to inspect, clean, and unblock underground pipes', true, '1c0a9212-9a44-446f-b76b-69b2ddf92b48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39190577-c09b-437c-8ff8-4740c4ba779e', 'A place to store drinking water', false, '1c0a9212-9a44-446f-b76b-69b2ddf92b48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7eac7abc-4e7a-4be6-9b2b-365325d0ac10', 'A doorway into a subway train', false, '1c0a9212-9a44-446f-b76b-69b2ddf92b48');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c14d642-48a1-47ea-a2d3-540cc40a262f', 'A trash bin on the street', false, '1c0a9212-9a44-446f-b76b-69b2ddf92b48');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('59f2d145-b397-4950-b645-4494982add09', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7414aba9-b461-454e-9d36-e80b782e8f02', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '59f2d145-b397-4950-b645-4494982add09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('beaaa796-7a63-4978-a892-cbb77ef5c955', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '59f2d145-b397-4950-b645-4494982add09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('170ae813-b33b-43fd-b0c9-f0014bd4177b', '(A) is true, but (R) is false.', false, '59f2d145-b397-4950-b645-4494982add09');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9dc613d7-e59f-4d33-a808-3e232ec52190', '(A) is false, but (R) is true.', false, '59f2d145-b397-4950-b645-4494982add09');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c1d1eba0-8b2c-4dcc-afbf-c64d0e92073d', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'Spot the IMPOSTER in the following sequence of Wastewater Treatment Plant (WWTP) unit operations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9b0d710-b5c7-477c-993e-1088908bede7', 'Unit 1', false, 'c1d1eba0-8b2c-4dcc-afbf-c64d0e92073d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0d08eae8-8908-40d9-9396-97fb4ca26c2d', 'Unit 2', false, 'c1d1eba0-8b2c-4dcc-afbf-c64d0e92073d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('949b6bc0-9838-49c6-9845-677fa13ee4ff', 'Unit 3', false, 'c1d1eba0-8b2c-4dcc-afbf-c64d0e92073d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca6387e8-b9a7-4654-9a0b-2be982e07bed', 'Unit 4 (WWTP processes involve physical clarification, biological digestion, and chemical disinfection; they NEVER add confectionery sugars or chocolate syrup)', true, 'c1d1eba0-8b2c-4dcc-afbf-c64d0e92073d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('451083df-6a3d-40f8-ad90-673538662d17', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'Analyze the biological mechanism of ''Biochemical Oxygen Demand'' (BOD) in wastewater analysis:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0156c4d6-6c2a-4ca6-bd17-09e9dc77eded', 'High BOD indicates a massive load of organic pollutants; as aerobic bacteria consume dissolved oxygen to decompose this waste, oxygen levels in the river plummet to near zero, causing catastrophic fish suffocations', true, '451083df-6a3d-40f8-ad90-673538662d17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('055b58b0-a91c-41f3-acdd-26923204a2e5', 'High BOD turns water into acid that melts fish scales', false, '451083df-6a3d-40f8-ad90-673538662d17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1c74b363-0e10-446f-b8c9-5460af7bf5e2', 'High BOD freezes the river solid', false, '451083df-6a3d-40f8-ad90-673538662d17');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d35d6efd-82ef-487a-bc29-291131f94caf', 'High BOD increases river water salinity to ocean levels', false, '451083df-6a3d-40f8-ad90-673538662d17');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c70c2a3a-79a0-433f-8c19-66a93a3a2b14', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'Match Column I (WWTP Treatment Stages) with Column II (Primary Environmental Functions):
(a) Bar Screens         -> (i) Mechanical removal of coarse solid plastic/rag debris
(b) Aeration Basin      -> (ii) Aerobic microbiological oxidation of dissolved organic wastes
(c) Anaerobic Digester  -> (iii) Methanogenic fermentation of sludge producing combustible biogas
(d) UV / Chlorination   -> (iv) Pathogen disinfection and destruction of waterborne bacteria', 'Bar screens = coarse screening; Aeration = aerobic oxidation; Digester = biogas generation; Chlorination = pathogen disinfection.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bbbfd780-74dd-4758-b6c7-b2347cd39c9c', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'c70c2a3a-79a0-433f-8c19-66a93a3a2b14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5136df49-456f-43ab-969d-2fc5b87d7b64', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'c70c2a3a-79a0-433f-8c19-66a93a3a2b14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8ba018e8-1cdf-4f7b-9761-d7bb5e22b73c', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'c70c2a3a-79a0-433f-8c19-66a93a3a2b14');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ca67c480-57c8-4b9e-aa19-b46133909f9c', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'c70c2a3a-79a0-433f-8c19-66a93a3a2b14');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b0c9574d-5645-4fac-8203-4f4b7ebd4b9d', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'Read the statements regarding forest ecology:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('66438634-b92b-4532-bacd-5e0c3d5eef62', 'Statements 1 and 2 only', true, 'b0c9574d-5645-4fac-8203-4f4b7ebd4b9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2594752-7b9b-4c41-b6cc-f484d06ae5a8', 'Statements 2 and 3 only', false, 'b0c9574d-5645-4fac-8203-4f4b7ebd4b9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf3363d6-5981-458c-83fa-f6e0d649eff1', 'Statements 1 and 3 only', false, 'b0c9574d-5645-4fac-8203-4f4b7ebd4b9d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c4fcd3c4-ac0f-4d3b-9612-9f1df5cc6c5b', 'All Statements 1, 2, and 3', false, 'b0c9574d-5645-4fac-8203-4f4b7ebd4b9d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('891e645e-e449-4e78-9c2d-3fa8923b319b', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'What is the biological role of ''Fungi and Micro-arthropods'' in the humification process on the forest floor?', 'Saprophytic fungi (white-rot, brown-rot) and soil micro-arthropods enzymatically cleave complex lignin/cellulose polymers into nutrient-rich humus.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7f1dacc-fde8-410d-b48c-0ee1236d6a41', 'They secrete extracellular enzymes that digest recalcitrant plant polymers (lignin, cellulose), transforming leaf litter into stable, dark, mineral-rich colloidal humus', true, '891e645e-e449-4e78-9c2d-3fa8923b319b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54afdf59-991d-4854-9c6f-ce82fcfb7d00', 'They eat living tree trunks and kill the forest', false, '891e645e-e449-4e78-9c2d-3fa8923b319b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94a7c918-6113-49f3-8539-14b65d22f269', 'They convert soil into solid glass', false, '891e645e-e449-4e78-9c2d-3fa8923b319b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1da0734-0c74-45a1-bfcd-1c67dd53944c', 'They absorb all sunlight on the ground', false, '891e645e-e449-4e78-9c2d-3fa8923b319b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d34e5a44-93d3-45d9-b364-35316b715092', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'How do constructed wetland bio-filtration systems (like Phytoremediation reed beds) purify sewage water without electricity?', 'Phytoremediation leverages rhizosphere microbiology and macrophyte bio-accumulation to remediate wastewater naturally and passively.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1b1b1d95-c87d-4a8a-9508-ef20ac28693b', 'Aquatic plants (like reeds and cattails) absorb heavy metals and excess nitrogen/phosphorus, while microbial biofilms around their root zones biologically degrade organic pollutants', true, 'd34e5a44-93d3-45d9-b364-35316b715092');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff777acc-9bfa-4f1b-af97-63812e52051d', 'By boiling water using solar mirrors', false, 'd34e5a44-93d3-45d9-b364-35316b715092');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('746745a9-4669-4ebe-a04b-838b1f908e23', 'By adding chemical dyes that hide dirt', false, 'd34e5a44-93d3-45d9-b364-35316b715092');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d74c3fe4-5153-4e75-9f63-f1277b5ff4a6', 'By freezing sewage into ice bricks', false, 'd34e5a44-93d3-45d9-b364-35316b715092');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b3bc1b00-2103-43e0-86be-bd4b89891a87', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'Consider four environmental management practices:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cc0a5a9-b95d-4df6-92f2-9ee64ec33c87', 'Practices 1, 2, and 4 only', true, 'b3bc1b00-2103-43e0-86be-bd4b89891a87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ed80772-d63b-4f87-89f3-ae3257113b31', 'Practice 3 only', false, 'b3bc1b00-2103-43e0-86be-bd4b89891a87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3104b5be-21b6-45b9-89ff-e3ae754e64c0', 'Practices 1 and 3 only', false, 'b3bc1b00-2103-43e0-86be-bd4b89891a87');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9b3355f-26a2-4e80-b59f-7702f2c3967b', 'All 1, 2, 3, and 4', false, 'b3bc1b00-2103-43e0-86be-bd4b89891a87');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ecc21699-d8fc-4f65-8d14-2489052be4a1', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'Why does the presence of high levels of Coliform Bacteria (such as E. coli) in a river or well indicate severe water pollution?', 'Coliforms serve as universal microbiological fecal indicator organisms, demonstrating sewage contamination and the presence of enteric waterborne pathogens.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b85b709f-ae1d-4183-8bd3-d6f00f180d9b', 'Coliform bacteria are natural inhabitants of the human and warm-blooded animal intestinal tract; their presence proves direct contamination by raw sewage and high risk of lethal enteric pathogens', true, 'ecc21699-d8fc-4f65-8d14-2489052be4a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09b33f7a-abb6-404c-82fa-ae0250b44856', 'Because coliform bacteria eat fish', false, 'ecc21699-d8fc-4f65-8d14-2489052be4a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbdcbe77-5f94-407a-a63a-4df2d297c0eb', 'Because they produce poisonous radioactive gases', false, 'ecc21699-d8fc-4f65-8d14-2489052be4a1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f17a9e5b-07c7-4938-8ff5-b6f70ebb22aa', 'Because they make water turn red', false, 'ecc21699-d8fc-4f65-8d14-2489052be4a1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14a957ee-cda8-44f0-8091-f69cdc6b934c', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'What is the physical cause of ''Eutrophication'' in freshwater lakes receiving untreated domestic sewage and detergent runoff?', 'Nutrient hyper-enrichment (phosphates/nitrates) drives algal blooms whose subsequent decomposition induces severe lake hypolimnetic anoxia.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e506562b-160e-4760-8015-3f85f9c1404d', 'Excessive nitrogen and phosphate nutrients trigger explosive algal blooms; when the algae die, decomposing bacteria consume all dissolved oxygen, suffocating aquatic animals', true, '14a957ee-cda8-44f0-8091-f69cdc6b934c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7283a27f-ea38-4158-9ebe-9b2d1abcc970', 'The lake gets too cold to support fish', false, '14a957ee-cda8-44f0-8091-f69cdc6b934c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('52aa7074-2ce0-4100-82a4-eac2ededff04', 'Detergents turn water into solid jelly', false, '14a957ee-cda8-44f0-8091-f69cdc6b934c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('64a6a8d2-be14-42d4-8ec1-cd7b23656e35', 'Algae turn into large carnivorous plants', false, '14a957ee-cda8-44f0-8091-f69cdc6b934c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c4b7e3ec-dcf2-481b-8c49-b41e1584e6b2', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'How do deep-rooted forest trees prevent Hillside LANDSLIDES during torrential cloudbursts?', 'Arbor roots provide tensile soil reinforcement, increasing mechanical shear strength and relieving pore-water pressure that triggers slope failure.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc573059-4273-40a9-8fa6-d4deddd2c27e', 'The extensive taproot and lateral root networks act as bio-mechanical anchors, interlocking soil strata and bedrock, while continuous transpiration drains excess soil pore-water pressure', true, 'c4b7e3ec-dcf2-481b-8c49-b41e1584e6b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ebdeb3e-c592-4016-a063-b24e0a3f3063', 'Trees build stone walls with their branches', false, 'c4b7e3ec-dcf2-481b-8c49-b41e1584e6b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21ec8fe7-f184-45fa-8ecf-edccfbf20528', 'Trees absorb earthquakes', false, 'c4b7e3ec-dcf2-481b-8c49-b41e1584e6b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61b5702c-05e6-459b-a48f-91520a546faa', 'Trees freeze the mud', false, 'c4b7e3ec-dcf2-481b-8c49-b41e1584e6b2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('afc36c5a-8438-4f4a-98b5-99cd0b635225', 'Class 7', 'Science', 'Chapter 12: Forests: Our Lifeline & Wastewater Story', 'Hard', 'What supreme ecological synthesis concludes the NCERT Class 7 Science curriculum in Chapter 12?', 'Chapter 12 synthesizes forest conservation, hydrological cycles, ecological stewardship, and circular environmental engineering.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('48fc412a-a124-49eb-8cee-15b32eb6d125', 'Human health, ecological balance, clean water, and planetary survival depend inextricably on conserving living forest biomes as our vital life-support systems and adopting responsible, closed-loop circular sanitation to keep our water bodies pure and vibrant', true, 'afc36c5a-8438-4f4a-98b5-99cd0b635225');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb5702b7-8a30-4dd2-8884-ad75e6a1b14b', 'That nature can be destroyed without consequences', false, 'afc36c5a-8438-4f4a-98b5-99cd0b635225');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c599946c-1cb1-417a-be6f-7182d41a8843', 'That wastewater treatment is unnecessary', false, 'afc36c5a-8438-4f4a-98b5-99cd0b635225');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('850a98ef-3832-49a4-8fbc-2e463750ecbc', 'That technology will replace all natural forests', false, 'afc36c5a-8438-4f4a-98b5-99cd0b635225');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('44457fae-fba8-417e-b4c5-cf44d4406cfe', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'A geometric line that divides a plane figure into two identical, matching halves such that one half completely folds over and covers the other is called a:', 'A line of symmetry is an axis of reflection that bisects a figure into two congruent, mirror-image halves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('945cc75b-a48b-4dd2-932d-1269e54ca350', 'Line of Symmetry (Axis of Symmetry)', true, '44457fae-fba8-417e-b4c5-cf44d4406cfe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f417e4e8-d95c-4025-ad4f-3fd54a1d8b83', 'Diagonal only', false, '44457fae-fba8-417e-b4c5-cf44d4406cfe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fab7d591-564d-4419-ad91-e33cca0c6d43', 'Radius', false, '44457fae-fba8-417e-b4c5-cf44d4406cfe');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('264939d0-e497-4eb6-b674-7146e53c715f', 'Perimeter line', false, '44457fae-fba8-417e-b4c5-cf44d4406cfe');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cff2c74d-5d72-4f10-a6e9-c1491d81f5f1', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'How many lines of symmetry does an EQUILATERAL TRIANGLE have?', 'An equilateral triangle has 3 lines of symmetry passing through each vertex to the midpoint of the opposite side.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18b5d6da-f41e-4743-a038-d13da3376bdd', '3 Lines of Symmetry', true, 'cff2c74d-5d72-4f10-a6e9-c1491d81f5f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eee2e923-d5da-4bc5-a529-86bbf09417ee', '1 Line', false, 'cff2c74d-5d72-4f10-a6e9-c1491d81f5f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47093319-f724-4aa8-bdcf-a73d67ee58c2', '2 Lines', false, 'cff2c74d-5d72-4f10-a6e9-c1491d81f5f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa40dc85-e4e6-4916-a1fd-f7f9a5ccc902', 'Infinite Lines', false, 'cff2c74d-5d72-4f10-a6e9-c1491d81f5f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d0961f9e-082b-4362-a4ba-e268710cf17c', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'How many lines of symmetry does a regular SQUARE have?', 'A square has 4 lines of symmetry: 2 vertical/horizontal medians and 2 diagonal lines.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce341946-51d7-4d47-8951-88ffd1bb6115', '4 Lines of Symmetry (2 through midpoints of opposite sides, 2 along diagonals)', true, 'd0961f9e-082b-4362-a4ba-e268710cf17c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d418187d-93ba-48e5-bbcf-1c38fef8c0af', '2 Lines', false, 'd0961f9e-082b-4362-a4ba-e268710cf17c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb065ea9-615d-466e-9ee5-b027aee3ea85', '3 Lines', false, 'd0961f9e-082b-4362-a4ba-e268710cf17c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f6a2a74-f704-434e-bf97-87a8cfa27449', '8 Lines', false, 'd0961f9e-082b-4362-a4ba-e268710cf17c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94619be7-1ff2-4aa8-97d8-9a57bf27aeaf', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'How many lines of symmetry does a CIRCLE have?', 'A circle has an infinite number of lines of symmetry passing through its center along any diameter.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d64a92a-e6ea-43c6-a671-83b9378bf528', 'Infinitely Many Lines (any diameter is a line of symmetry)', true, '94619be7-1ff2-4aa8-97d8-9a57bf27aeaf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6b6eea5-73e0-411a-962c-b5fcfc87f760', '4 Lines', false, '94619be7-1ff2-4aa8-97d8-9a57bf27aeaf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aeaeadd7-e05f-48fc-8fa5-617d50fe6744', '360 Lines', false, '94619be7-1ff2-4aa8-97d8-9a57bf27aeaf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70dd01b0-1110-4629-b879-d8784859ca0d', '100 Lines', false, '94619be7-1ff2-4aa8-97d8-9a57bf27aeaf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3175ad96-4bf4-41ea-8dfa-11472059c282', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'What is the smallest angle through which a figure is rotated around a central point to look EXACTLY THE SAME as its original position called?', 'The angle of rotation is the minimum angle of turn around the center of rotation that maps the figure onto itself.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6efa174-c909-4282-ac3e-e1e94dc7aa71', 'Angle of Rotation', true, '3175ad96-4bf4-41ea-8dfa-11472059c282');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33f48d0e-293b-40e2-8662-f4a9c061a22d', 'Order of Symmetry', false, '3175ad96-4bf4-41ea-8dfa-11472059c282');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c0da8e1d-eaf6-4e48-9cf4-ee0250e85e6e', 'Reflective Angle', false, '3175ad96-4bf4-41ea-8dfa-11472059c282');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29199c2f-dedf-49a4-809f-54f8b9369129', 'Supplementary Angle', false, '3175ad96-4bf4-41ea-8dfa-11472059c282');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87405a7a-6fb3-4cbe-a1fd-6de7bb935558', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'What is the ORDER OF ROTATIONAL SYMMETRY of a square in one complete 360° turn?', 'A square maps onto itself 4 times during a 360° rotation (every 90°), hence its rotational symmetry order is 4.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13cb67e2-011f-48f6-8b20-23258375636e', 'Order 4 (at angles 90°, 180°, 270°, 360°)', true, '87405a7a-6fb3-4cbe-a1fd-6de7bb935558');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ee6bc2f-41a4-4b1c-9825-74df9d67e92c', 'Order 2', false, '87405a7a-6fb3-4cbe-a1fd-6de7bb935558');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('15db1827-e396-4f7f-a303-212553a70c28', 'Order 1', false, '87405a7a-6fb3-4cbe-a1fd-6de7bb935558');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('efdc8381-90cf-426a-8ae9-caacbebb71ae', 'Order 8', false, '87405a7a-6fb3-4cbe-a1fd-6de7bb935558');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0349123a-2886-4a96-bbf4-3493d7fc68c1', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'What is the ORDER OF ROTATIONAL SYMMETRY and ANGLE OF ROTATION of a RECTANGLE (non-square)?', 'A rectangle looks identical twice in a complete turn (at 180° and 360°), so order = 2 and angle of rotation = 180°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6878e0d9-51b5-4a65-82a9-9acb2d2da515', 'Order = 2 and Angle of Rotation = 180°', true, '0349123a-2886-4a96-bbf4-3493d7fc68c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5631ef60-ba52-4312-b706-2f63f0a787c7', 'Order = 4 and Angle = 90°', false, '0349123a-2886-4a96-bbf4-3493d7fc68c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91351d55-1639-49a1-9e9c-3e076ed37006', 'Order = 1 and Angle = 360°', false, '0349123a-2886-4a96-bbf4-3493d7fc68c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c332783a-9567-44e1-8edc-470afa3e9a96', 'Order = 3 and Angle = 120°', false, '0349123a-2886-4a96-bbf4-3493d7fc68c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('28c87281-bc21-4b20-a2ab-ba3a72e00c77', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'How many FACES (F), VERTICES (V), and EDGES (E) does a standard 3D CUBE have?', 'A cube has 6 square faces, 8 corner vertices, and 12 straight edges.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56fc0388-3f92-45bd-b542-e0c17c7e7967', '6 Faces, 8 Vertices, 12 Edges', true, '28c87281-bc21-4b20-a2ab-ba3a72e00c77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22e9e2a3-fad7-4163-9c3b-586b88f7c8fe', '8 Faces, 6 Vertices, 12 Edges', false, '28c87281-bc21-4b20-a2ab-ba3a72e00c77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98bdafff-22de-4423-8963-50137b4f32ec', '6 Faces, 12 Vertices, 8 Edges', false, '28c87281-bc21-4b20-a2ab-ba3a72e00c77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('616c205f-a37b-4c8c-9f8e-43f0da226a3d', '4 Faces, 4 Vertices, 6 Edges', false, '28c87281-bc21-4b20-a2ab-ba3a72e00c77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('94988081-6ff5-4d04-8fa4-0a092768b06f', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'What is EULER''S FORMULA relating Faces (F), Vertices (V), and Edges (E) for any convex polyhedron?', 'Euler''s Polyhedral Formula: F + V - E = 2 holds universally for all simple convex polyhedra.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d450fc8-6323-4802-b76d-4c5dabbd682a', 'F + V - E = 2 (or F + V = E + 2)', true, '94988081-6ff5-4d04-8fa4-0a092768b06f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc396b2d-d631-48ba-974c-f47dec4b5630', 'F + E - V = 2', false, '94988081-6ff5-4d04-8fa4-0a092768b06f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc35651e-52f6-4400-aa50-8731cd47a4ec', 'F + V + E = 2', false, '94988081-6ff5-4d04-8fa4-0a092768b06f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0dfd4dc-4542-46d6-ab54-f8e63fcbba56', 'F × V = E + 2', false, '94988081-6ff5-4d04-8fa4-0a092768b06f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('16f32f67-3dfa-44d3-af91-1b8ab1d126da', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'A flat 2D skeletal pattern or layout that can be folded along its edges to construct a 3D solid shape is called a:', 'A net is a 2D planar unfolded diagram consisting of adjacent polygons that fold together to construct a 3D polyhedron.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0559d928-a2f8-4afd-b50d-0b3ef9114b6b', 'Net of the solid', true, '16f32f67-3dfa-44d3-af91-1b8ab1d126da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('acfe36d5-7bff-4bcd-95b7-77e2802bca3e', 'Cross-section', false, '16f32f67-3dfa-44d3-af91-1b8ab1d126da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e746a38c-133c-4df3-8c8b-56d5af25c043', 'Isometric sheet', false, '16f32f67-3dfa-44d3-af91-1b8ab1d126da');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bb90cfc-fd1f-4bcd-9e76-35ced3384e44', 'Oblique sketch', false, '16f32f67-3dfa-44d3-af91-1b8ab1d126da');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cfbf6df9-6577-4624-b0e5-47ac1a5f2768', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'What is the cross-section obtained when a vertical cut (slicing) is made through an apple or a circular cylinder?', 'A horizontal cut through a cylinder gives a circle; cutting an apple transversely also yields a circular cross-section.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('922ef099-2399-4cb9-b9c4-0e58b7e99510', 'A Circle', true, 'cfbf6df9-6577-4624-b0e5-47ac1a5f2768');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a98032c2-c121-4893-9292-a57850f82e72', 'A Triangle', false, 'cfbf6df9-6577-4624-b0e5-47ac1a5f2768');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cca702d1-c976-47c7-ba60-68ca75d5a721', 'A Square only', false, 'cfbf6df9-6577-4624-b0e5-47ac1a5f2768');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d0e67fd-a101-43c3-9c4e-5914ca50385f', 'A Hexagon', false, 'cfbf6df9-6577-4624-b0e5-47ac1a5f2768');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca7f62e8-6219-456d-89b9-200611c7da91', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Easy', 'Which English capital letter has BOTH horizontal and vertical lines of symmetry as well as rotational symmetry of order 2?', 'Letter ''H'' possesses 2 lines of symmetry (horizontal and vertical) and rotational symmetry of order 2 (180°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18a01974-9152-4d9c-8649-e4a0383eca27', 'H (and O, X, I)', true, 'ca7f62e8-6219-456d-89b9-200611c7da91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5e89eff5-3f2c-47c5-b5f5-8620f3712007', 'A', false, 'ca7f62e8-6219-456d-89b9-200611c7da91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('908667bf-0afc-4f90-95e7-25a9f2036f11', 'B', false, 'ca7f62e8-6219-456d-89b9-200611c7da91');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ca7992f-ac60-4148-8f5c-b4558733ac61', 'C', false, 'ca7f62e8-6219-456d-89b9-200611c7da91');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e3e463d-491d-4819-9084-3314fb3b0dfc', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'How many lines of symmetry does a REGULAR HEXAGON have, and what is its order of rotational symmetry?', 'A regular n-gon has n lines of symmetry and rotational symmetry of order n; for a regular hexagon, n = 6 (angle = 360°/6 = 60°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6ccee48a-df2b-41dc-952a-22aeaf7d0766', '6 Lines of Symmetry and Order of Rotational Symmetry = 6 (Angle of rotation = 60°)', true, '2e3e463d-491d-4819-9084-3314fb3b0dfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7db2a843-8147-4a41-864f-c69aef140434', '4 Lines and Order 4', false, '2e3e463d-491d-4819-9084-3314fb3b0dfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e713a7bc-ee7d-4503-a832-074b5d2c442f', '3 Lines and Order 3', false, '2e3e463d-491d-4819-9084-3314fb3b0dfc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('401a3b52-3562-4e43-ae2c-cbd6355a1b92', '12 Lines and Order 12', false, '2e3e463d-491d-4819-9084-3314fb3b0dfc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ef0ce63-bc74-45c3-8496-62ba492f0d2c', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'Using Euler''s Formula (F + V - E = 2), find the number of EDGES (E) of a polyhedron having 8 faces and 12 vertices:', 'E = F + V - 2 = 8 + 12 - 2 = 18.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('94f0f10d-944f-417d-b166-f90fa9cdea12', '18 Edges (F + V - E = 2 ⇒ 8 + 12 - E = 2 ⇒ 20 - E = 2 ⇒ E = 18)', true, '8ef0ce63-bc74-45c3-8496-62ba492f0d2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a5706cbe-fc62-4186-8f42-0293ad53db2b', '16 Edges', false, '8ef0ce63-bc74-45c3-8496-62ba492f0d2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('612109db-08ce-4fef-bda7-6532d10a86aa', '20 Edges', false, '8ef0ce63-bc74-45c3-8496-62ba492f0d2c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c52a0c6-0423-4b46-b094-ebbf79e4aa02', '14 Edges', false, '8ef0ce63-bc74-45c3-8496-62ba492f0d2c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2892ce8c-cf1d-4159-9402-711ab1d6f6bb', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'Using Euler''s Formula, find the number of VERTICES (V) of a polyhedron with 20 faces and 30 edges (an Icosahedron):', 'V = E + 2 - F = 30 + 2 - 20 = 12.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6f4b6d9-0163-42ff-a792-2057a6cad161', '12 Vertices (F + V - E = 2 ⇒ 20 + V - 30 = 2 ⇒ V - 10 = 2 ⇒ V = 12)', true, '2892ce8c-cf1d-4159-9402-711ab1d6f6bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('32d2be9a-4600-43f2-978c-21f9d4f7c953', '10 Vertices', false, '2892ce8c-cf1d-4159-9402-711ab1d6f6bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eceb42bf-221f-492e-8faf-83ecb63184bd', '14 Vertices', false, '2892ce8c-cf1d-4159-9402-711ab1d6f6bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b000ac14-3a4a-4b09-be24-ad69ff40dc39', '16 Vertices', false, '2892ce8c-cf1d-4159-9402-711ab1d6f6bb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ca53bca8-5c22-435f-a1b9-768de5b46acc', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'How many FACES, VERTICES, and EDGES does a TRIANGULAR PRISM have?', 'A triangular prism has 5 faces, 6 vertices, and 9 edges, satisfying Euler''s formula (5 + 6 - 9 = 2).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('904ba18a-4f2e-4d11-9769-73c27adf7aee', '5 Faces (2 triangular bases + 3 rectangular side faces), 6 Vertices, 9 Edges (Check: 5 + 6 - 9 = 2)', true, 'ca53bca8-5c22-435f-a1b9-768de5b46acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75c3d38e-4685-474a-bdb0-f77b76602c9a', '6 Faces, 8 Vertices, 12 Edges', false, 'ca53bca8-5c22-435f-a1b9-768de5b46acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fe8b2332-2e6b-41a6-9504-81c5390de036', '4 Faces, 4 Vertices, 6 Edges', false, 'ca53bca8-5c22-435f-a1b9-768de5b46acc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6b3dec0-6f10-4cfd-8845-f11a7600d15e', '5 Faces, 5 Vertices, 8 Edges', false, 'ca53bca8-5c22-435f-a1b9-768de5b46acc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('048ca754-2db4-471f-a8c9-9f25870f07dd', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'How many FACES, VERTICES, and EDGES does a SQUARE PYRAMID have?', 'A square pyramid has 5 faces (1 base + 4 triangular sides), 5 vertices (4 base + 1 apex), and 8 edges.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('800f9bdb-c865-4961-b466-db0673351703', '5 Faces (1 square base + 4 triangular faces), 5 Vertices, 8 Edges (Check: 5 + 5 - 8 = 2)', true, '048ca754-2db4-471f-a8c9-9f25870f07dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fd2f9a0-9d1d-408d-94df-ea80b205d6a7', '4 Faces, 4 Vertices, 6 Edges', false, '048ca754-2db4-471f-a8c9-9f25870f07dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b29299ea-7989-402b-8026-0514725370c3', '6 Faces, 6 Vertices, 10 Edges', false, '048ca754-2db4-471f-a8c9-9f25870f07dd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54c22dcf-62da-4286-ad58-312e4b744b2f', '5 Faces, 6 Vertices, 9 Edges', false, '048ca754-2db4-471f-a8c9-9f25870f07dd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b4a70774-6cc2-4c71-bbe7-462e7afbd319', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'What is the difference between an OBLIQUE SKETCH and an ISOMETRIC SKETCH of a 3D solid?', 'Isometric projections use a 30° equilateral triangular dot grid preserving scale proportions along axes, unlike oblique pictorial sketches.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f68d92f-bc74-441e-bfe0-046839657ec4', 'An oblique sketch does not preserve exact proportional dimensions of receding depths ; an isometric sketch is drawn on an isometric dot grid where exact scaled measurements are preserved', true, 'b4a70774-6cc2-4c71-bbe7-462e7afbd319');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('40620c2a-ab3c-4720-96fd-9559e4713bda', 'Oblique sketches are drawn with circles only', false, 'b4a70774-6cc2-4c71-bbe7-462e7afbd319');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b29b4d07-5aa4-4424-99e9-f692798d9f70', 'Isometric sketches are drawn without rulers', false, 'b4a70774-6cc2-4c71-bbe7-462e7afbd319');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ef38aac-5cb1-4d48-ba06-19fc695fff8f', 'There is no mathematical difference', false, 'b4a70774-6cc2-4c71-bbe7-462e7afbd319');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1ed2c742-583d-4801-9d36-11e94bda91ae', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'On a standard playing DIE (Dice), the sum of the numbers of dots on opposite faces is ALWAYS equal to:', 'Standard dice convention: opposite faces always sum to 7 (1+6=7, 2+5=7, 3+4=7).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('affb931c-6258-4b48-baed-985e2dae43f1', '7 (1 opposite 6, 2 opposite 5, 3 opposite 4)', true, '1ed2c742-583d-4801-9d36-11e94bda91ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd7e1282-6932-4022-9fd9-c10ea0bc214d', '6', false, '1ed2c742-583d-4801-9d36-11e94bda91ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17f4c0b2-b0b5-4e6b-96b0-add55b6a0a2d', '8', false, '1ed2c742-583d-4801-9d36-11e94bda91ae');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea3ca64e-d57a-4d33-b932-f06d9ba88dfe', '10', false, '1ed2c742-583d-4801-9d36-11e94bda91ae');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a8d2473f-3068-494e-a3aa-bd56e323fa9c', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'What is the cross-section shape obtained when you make a VERTICAL SLICE through a solid Brick (Cuboid)?', 'A vertical or horizontal planar slice through a cuboid always yields a rectangular (or square) cross-section.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('511815cc-ece2-497a-8717-a37b7e3b07a3', 'A Rectangle (or Square depending on cut)', true, 'a8d2473f-3068-494e-a3aa-bd56e323fa9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13d22584-deb7-4db5-9b1d-85fb2c51e8d5', 'A Circle', false, 'a8d2473f-3068-494e-a3aa-bd56e323fa9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3831dd7-dfdd-4da8-ba95-a2045f25b3f7', 'A Triangle', false, 'a8d2473f-3068-494e-a3aa-bd56e323fa9c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b75076f6-05cd-4261-a4e2-913dc2db5249', 'A Pentagon', false, 'a8d2473f-3068-494e-a3aa-bd56e323fa9c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ae739d4-d741-4388-aadd-26c923ee66aa', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'What is the cross-section obtained when you make a VERTICAL SLICE through the apex of a solid CONE?', 'A vertical axial cross-section passing through the apex of a right circular cone produces an isosceles triangle.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5144db79-c3c6-4d9a-b398-4a6e7c15f937', 'An Isosceles Triangle', true, '8ae739d4-d741-4388-aadd-26c923ee66aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42078d82-ef37-4a5e-808b-18c8d27db481', 'A Circle', false, '8ae739d4-d741-4388-aadd-26c923ee66aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b469329f-8479-4969-ab36-463ddc37a6aa', 'A Rectangle', false, '8ae739d4-d741-4388-aadd-26c923ee66aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3621358d-dd6a-4a11-b15a-c6de1b65d1b2', 'An Oval', false, '8ae739d4-d741-4388-aadd-26c923ee66aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02522265-ecdc-474b-9f40-b275873d8ce6', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'Which of the following geometric figures has ONLY Rotational Symmetry of Order > 1 but NO Line of Symmetry?', 'A standard non-rhombic parallelogram has rotational symmetry of order 2 (180°), but zero reflectional lines of symmetry.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb88aece-8fe5-4a2e-a3f1-d88cd8805bc8', 'A Parallelogram (Rotational symmetry of order 2, but 0 lines of symmetry)', true, '02522265-ecdc-474b-9f40-b275873d8ce6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('85424042-fe25-495d-b3fc-39c2513d8e47', 'A Square', false, '02522265-ecdc-474b-9f40-b275873d8ce6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be8c796d-d163-420a-a01a-b538c94f5969', 'An Equilateral Triangle', false, '02522265-ecdc-474b-9f40-b275873d8ce6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('58d9d036-3ea0-4655-aaec-50f9646a3c33', 'A Regular Pentagon', false, '02522265-ecdc-474b-9f40-b275873d8ce6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('773137fc-6974-4454-9e7b-19fe6155ad69', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'What is the order of rotational symmetry of a regular PENTAGON?', 'A regular pentagon has order 5 and angle of rotation = 360°/5 = 72°.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b256690-dca0-4f8c-af20-6c83d5b35741', 'Order = 5 and Angle of rotation = 72° (360° / 5 = 72°)', true, '773137fc-6974-4454-9e7b-19fe6155ad69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('994b4006-3b40-48eb-8574-2ffec56ec7c1', 'Order = 5 and Angle = 60°', false, '773137fc-6974-4454-9e7b-19fe6155ad69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b26c959c-d224-4297-8a34-3e32e2ae2df3', 'Order = 10 and Angle = 36°', false, '773137fc-6974-4454-9e7b-19fe6155ad69');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('56a9ac09-49e7-4d1b-a7b1-72795a3c0fec', 'Order = 3 and Angle = 120°', false, '773137fc-6974-4454-9e7b-19fe6155ad69');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2420ef2d-96cf-4bd5-866d-77b95f8cbe74', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'Three cubes each of edge 2 cm are placed side-by-side to form a single CUBOID. What are the dimensions (length, breadth, height) of the resulting cuboid?', 'Placing 3 identical cubes of side 2 cm linearly results in a cuboid of dimensions 6 cm × 2 cm × 2 cm.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbe227b0-1629-400e-889b-354a0a85f5d9', 'Length = 6 cm, Breadth = 2 cm, Height = 2 cm (Length = 2 + 2 + 2 = 6 cm)', true, '2420ef2d-96cf-4bd5-866d-77b95f8cbe74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f3edd19-fd2a-4389-8b47-24fcbd119880', 'Length = 2 cm, Breadth = 2 cm, Height = 2 cm', false, '2420ef2d-96cf-4bd5-866d-77b95f8cbe74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('05dafb22-1ecb-4421-9e98-2af4ab21fa00', 'Length = 6 cm, Breadth = 6 cm, Height = 6 cm', false, '2420ef2d-96cf-4bd5-866d-77b95f8cbe74');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce218cb3-5839-416c-a1c1-e2a0152028c0', 'Length = 8 cm, Breadth = 2 cm, Height = 2 cm', false, '2420ef2d-96cf-4bd5-866d-77b95f8cbe74');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2c539548-48df-4e6a-837d-0244ea053343', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'Can a polyhedron have 10 faces, 20 edges, and 15 vertices?', 'By Euler''s formula, F + V - E must equal 2. Here 10 + 15 - 20 = 5 ≠ 2, so no such polyhedron can exist.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cc9c1531-5c9b-4e32-a116-0cdb9aa20379', 'YES, it satisfies Euler''s formula: F + V - E = 10 + 15 - 20 = 25 - 20 = 5 ≠ 2 ... Wait! 10 + 15 - 20 = 5 ≠ 2 ; Therefore, NO, such a polyhedron CANNOT exist', false, '2c539548-48df-4e6a-837d-0244ea053343');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('833a87d9-799f-484b-b821-1d38c006cdf0', 'NO, because F + V - E = 10 + 15 - 20 = 5 ≠ 2 (violating Euler''s formula)', true, '2c539548-48df-4e6a-837d-0244ea053343');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26a00ab0-7037-4778-8603-91e78e9a35cd', 'YES, it is a pyramid', false, '2c539548-48df-4e6a-837d-0244ea053343');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb5a68c0-1f6c-42fc-a125-c30e9cda2ecf', 'YES, it is a prism', false, '2c539548-48df-4e6a-837d-0244ea053343');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('82d04af8-b2df-476c-a278-8fe80b2e720e', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'What solid shape is generated when a right-angled triangular sheet is rotated rapidly around one of its perpendicular sides as the axis?', 'Rotating a right-angled triangle around its altitude sweeps out a 3D right circular cone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ecddb66-b5da-43f8-8015-2b2850a13e09', 'A Right Circular Cone', true, '82d04af8-b2df-476c-a278-8fe80b2e720e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cc868d6-a483-488e-8100-53a0fe1574a1', 'A Cylinder', false, '82d04af8-b2df-476c-a278-8fe80b2e720e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75d52907-5487-4c74-8f2e-3c3a0c6681d9', 'A Sphere', false, '82d04af8-b2df-476c-a278-8fe80b2e720e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70356851-0538-477b-bbc7-2b4b27f87346', 'A Prism', false, '82d04af8-b2df-476c-a278-8fe80b2e720e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('39aa85ef-bbc1-4016-b5bf-519f1736fce7', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'What solid shape is generated when a flat rectangular sheet is rotated rapidly around one of its sides?', 'Rotating a rectangle around one edge generates a 3D circular cylinder.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ed4b4fd6-af85-4723-bc52-965689a8a3b9', 'A Cylinder', true, '39aa85ef-bbc1-4016-b5bf-519f1736fce7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62c74c79-4ed9-426c-9654-9a5739bc3716', 'A Cone', false, '39aa85ef-bbc1-4016-b5bf-519f1736fce7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6fc0b15-5796-4e39-9178-df882b6cf29d', 'A Sphere', false, '39aa85ef-bbc1-4016-b5bf-519f1736fce7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('737db0fe-aec4-4ed5-8d85-3e2d8f789cb5', 'A Pyramid', false, '39aa85ef-bbc1-4016-b5bf-519f1736fce7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14498833-bf17-427f-a872-c1bbd2c9f6bf', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Medium', 'How many lines of symmetry does a RHOMBUS have?', 'A non-square rhombus has exactly 2 lines of symmetry coinciding with its perpendicular diagonals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f9d35a80-35cc-40eb-86d2-3cb6d42fef0d', '2 Lines of Symmetry (along its two diagonals)', true, '14498833-bf17-427f-a872-c1bbd2c9f6bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c8704e5-c372-4024-bf10-261e1ba4db08', '4 Lines', false, '14498833-bf17-427f-a872-c1bbd2c9f6bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ddcbcf0a-2afa-4f99-8ad9-d32d1d67436f', '1 Line', false, '14498833-bf17-427f-a872-c1bbd2c9f6bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb45923b-e051-4469-937f-d126ff4937be', '0 Lines', false, '14498833-bf17-427f-a872-c1bbd2c9f6bf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c80e5f9f-19ba-45f2-b7ef-641929fc980e', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ec90c7bc-d00e-41e7-82b3-33029b7f0a13', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'c80e5f9f-19ba-45f2-b7ef-641929fc980e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5c3ece0b-74d7-4290-99b7-a39f92a270fc', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'c80e5f9f-19ba-45f2-b7ef-641929fc980e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa0d2b6a-9a44-4302-bd4c-3c3c5f0d9065', '(A) is true, but (R) is false.', false, 'c80e5f9f-19ba-45f2-b7ef-641929fc980e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1b565d7-abb5-41c5-9067-c304d5cb627d', '(A) is false, but (R) is true.', false, 'c80e5f9f-19ba-45f2-b7ef-641929fc980e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('02e9bbf0-2c36-43a5-8ac7-43ede5cd6cba', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'Spot the IMPOSTER in the following polyhedra and their Euler characteristic components (F, V, E):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6682fc5-d602-45fd-8a65-2744f4bdb8a1', 'Polyhedron 1', false, '02e9bbf0-2c36-43a5-8ac7-43ede5cd6cba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('478bc08f-793c-4cf8-95d2-822879c7a739', 'Polyhedron 2', false, '02e9bbf0-2c36-43a5-8ac7-43ede5cd6cba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa7f7271-6eb8-419f-b98a-14bb935a62d3', 'Polyhedron 3', false, '02e9bbf0-2c36-43a5-8ac7-43ede5cd6cba');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9010736-3fbb-49f2-bc21-048e45a27c11', 'Polyhedron 4 (Polyhedron 4 violates Euler''s Theorem F + V - E = 2; a solid with 4 vertices and 4 faces is a Tetrahedron with E = 6, NOT E = 20)', true, '02e9bbf0-2c36-43a5-8ac7-43ede5cd6cba');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('586a4d75-ed11-4420-9a8f-fe891dd743f1', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'A net for a dice cube has numbers marked on its 6 square faces. If face 1 is opposite face ''x'', face 2 is opposite face ''y'', and face 3 is opposite face ''z'' on a standard die, find the value of (x + y - z):', 'x = 6, y = 5, z = 4. Calculation: 6 + 5 - 4 = 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2e0c4c8-7006-4fd1-a084-8e42056ce990', '7 (Since opposite faces sum to 7: x = 7 - 1 = 6 ; y = 7 - 2 = 5 ; z = 7 - 3 = 4 ; Value = 6 + 5 - 4 = 11 - 4 = 7)', true, '586a4d75-ed11-4420-9a8f-fe891dd743f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6f422d1d-bcd1-4e76-920b-ea06e6e7a4be', '5', false, '586a4d75-ed11-4420-9a8f-fe891dd743f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3e3bf53d-1415-4858-bf88-8fdd1e4ea1f5', '9', false, '586a4d75-ed11-4420-9a8f-fe891dd743f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bb2db147-39a0-45d2-a7b0-6155d1885eca', '11', false, '586a4d75-ed11-4420-9a8f-fe891dd743f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2565c3f2-15a7-4be9-87e0-cbfc72e27fec', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'Match Column I (Geometric Figures) with Column II (Order of Rotational Symmetry & Line Symmetry):
(a) Equilateral Triangle -> (i) 3 Lines of symmetry & Rotational Order 3 (120°)
(b) Regular Hexagon      -> (ii) 6 Lines of symmetry & Rotational Order 6 (60°)
(c) Parallelogram        -> (iii) 0 Lines of symmetry & Rotational Order 2 (180°)
(d) Scalene Triangle     -> (iv) 0 Lines of symmetry & Rotational Order 1 (360° only)', 'Equilateral triangle = 3 & 3; Hexagon = 6 & 6; Parallelogram = 0 & 2; Scalene = 0 & 1.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea051177-23e4-4b1f-896d-da8bd38e47f9', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '2565c3f2-15a7-4be9-87e0-cbfc72e27fec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ec5007d-99d8-4da9-9aa9-3332a76c7a32', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '2565c3f2-15a7-4be9-87e0-cbfc72e27fec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d625e8ed-eb98-4c57-a1d6-7a43de2690a8', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '2565c3f2-15a7-4be9-87e0-cbfc72e27fec');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('019b592f-8315-456c-b4c1-b5eb52dd2c3e', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '2565c3f2-15a7-4be9-87e0-cbfc72e27fec');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a854cb16-1221-4b08-8860-11a000c3be8f', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'Read the statements regarding 3D projections:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('737dabbb-2543-44ce-8a8a-c3876a558a9b', 'Statements 1 and 2 only', true, 'a854cb16-1221-4b08-8860-11a000c3be8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('272a917e-daaa-427d-a91e-f32c2a93e5b6', 'Statements 2 and 3 only', false, 'a854cb16-1221-4b08-8860-11a000c3be8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c75ea7bc-4e56-442d-8f57-ae4d3b768d50', 'Statements 1 and 3 only', false, 'a854cb16-1221-4b08-8860-11a000c3be8f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ab1957a-c7e0-40a1-ac4d-ea3a0973e678', 'All Statements 1, 2, and 3', false, 'a854cb16-1221-4b08-8860-11a000c3be8f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e6b93dce-d595-486f-b7a0-cfb2f2b82f81', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'A solid geometric shape has 1 curved face and 2 flat circular planar faces. What is the solid shape, and what is its horizontal cross-section?', 'A cylinder has 2 circular flat bases and 1 curved lateral surface; horizontal cuts parallel to bases yield circular cross-sections.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('83bac313-5452-4281-9d62-e2a20625fdc3', 'A Cylinder ; its horizontal cross-section is a Circle', true, 'e6b93dce-d595-486f-b7a0-cfb2f2b82f81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45209b0b-4509-47b9-b88b-f1b262a45a9a', 'A Cone ; its cross-section is a square', false, 'e6b93dce-d595-486f-b7a0-cfb2f2b82f81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8ce3ae8-50c3-42ca-8431-c6b6b6fad875', 'A Sphere ; its cross-section is a triangle', false, 'e6b93dce-d595-486f-b7a0-cfb2f2b82f81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ba25aac-d07f-41b7-aec2-8e2ef019c662', 'A Prism ; its cross-section is a rectangle', false, 'e6b93dce-d595-486f-b7a0-cfb2f2b82f81');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ee0a7cc-e7ed-4538-ab86-8a58e0ce87ad', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'If a regular polygon has an angle of rotational symmetry equal to 45°, how many sides does the polygon have, and how many lines of symmetry does it possess?', 'n = 360° / 45° = 8 (regular octagon), which has 8 lines of symmetry.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('997c7c16-2be6-438b-8d14-592216bbe6f3', '8 sides (Octagon) and 8 lines of symmetry (Number of sides n = 360° / 45° = 8)', true, '7ee0a7cc-e7ed-4538-ab86-8a58e0ce87ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5a4e63c-1a47-437a-96f7-97c3df21bb7f', '6 sides and 6 lines', false, '7ee0a7cc-e7ed-4538-ab86-8a58e0ce87ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10bc891d-965a-4e62-8af8-5d8bac4bcc66', '10 sides and 10 lines', false, '7ee0a7cc-e7ed-4538-ab86-8a58e0ce87ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('84be6c0c-5603-4173-9092-a543fd5b424e', '12 sides and 12 lines', false, '7ee0a7cc-e7ed-4538-ab86-8a58e0ce87ad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fd3a79af-bcd7-40d0-961b-381eb89bc15b', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'Consider four geometric 3D shapes:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8671bce6-127a-4929-8192-6476c147e4df', 'Cuts 1, 2, and 3 only', true, 'fd3a79af-bcd7-40d0-961b-381eb89bc15b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef3365f3-e999-4332-8ff9-94d5c2838129', 'Cut 4 only', false, 'fd3a79af-bcd7-40d0-961b-381eb89bc15b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8339ae1d-a413-4ef0-8e8f-6f02ec7c8e51', 'Cuts 2 and 4 only', false, 'fd3a79af-bcd7-40d0-961b-381eb89bc15b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b36fab6-0b52-4a17-ab10-3db8e2b69030', 'All 1, 2, 3, and 4', false, 'fd3a79af-bcd7-40d0-961b-381eb89bc15b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('96be516c-eb5a-428d-8939-d34063cb7175', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'How many unit cubes (1 cm × 1 cm × 1 cm) are required to build a solid hollow cubical box of outer dimension 4 cm × 4 cm × 4 cm with walls 1 cm thick?', 'Outer volume = 4³ = 64. Inner void = (4-2)³ = 2³ = 8. Required unit cubes = 64 - 8 = 56.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afd9d9b8-477f-42bf-981c-fe04b9cd55b9', '56 unit cubes (Total outer volume = 4³ = 64 cm³ ; Inner hollow volume = 2³ = 8 cm³ ; Required cubes = 64 - 8 = 56 cubes)', true, '96be516c-eb5a-428d-8939-d34063cb7175');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a6103d3-9287-443c-9f47-2177fbde7c15', '64 cubes', false, '96be516c-eb5a-428d-8939-d34063cb7175');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46dca4de-e0ab-460e-b208-89e8bf2f78e2', '48 cubes', false, '96be516c-eb5a-428d-8939-d34063cb7175');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1b4dfa3-e735-4d83-8b5e-350afbebe0f8', '52 cubes', false, '96be516c-eb5a-428d-8939-d34063cb7175');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a47c0207-6d7c-4a18-a0cc-274424e41851', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'What is the maximum number of acute angles a convex polyhedron''s polygonal face can have in 3D Euclidean geometry?', 'A polygon can have at most 3 acute interior angles regardless of the number of sides (as exterior angles would otherwise exceed 360°).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f9149f8-62f4-4c1e-819d-cadf5e267277', '3 acute angles (in a triangle)', true, 'a47c0207-6d7c-4a18-a0cc-274424e41851');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98e018ad-9e7e-421c-8d15-042d73ff3bef', '4', false, 'a47c0207-6d7c-4a18-a0cc-274424e41851');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96bd188f-0d36-4110-bf08-dd349b05adf4', '5', false, 'a47c0207-6d7c-4a18-a0cc-274424e41851');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f173886-0b39-44f7-91c8-069076ff717e', 'Infinite', false, 'a47c0207-6d7c-4a18-a0cc-274424e41851');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('eb4515f4-e672-4350-891d-6ef5b94774e8', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'Why can a solid polyhedron NEVER have only 7 edges?', 'Every polyhedron face has ≥ 3 edges (2E ≥ 3F) and each vertex has degree ≥ 3 (2E ≥ 3V). No polyhedron can have E = 7.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ab19be5-4ab3-4a6c-9290-ea7a699e38cc', 'By Euler''s formula and face-edge degree bounds (2E ≥ 3F and 2E ≥ 3V), for E = 7, F + V = 9; combining bounds yields 3(F + V) = 27 ≤ 4E = 28, which admits no integer solution for planar polygonal faces', true, 'eb4515f4-e672-4350-891d-6ef5b94774e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e8fa28b-627e-48a1-94b5-0214a245c9b3', 'Because 7 is an odd number', false, 'eb4515f4-e672-4350-891d-6ef5b94774e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b721d60-6a89-4656-a361-ed93688fcaa2', 'Because polyhedra must have even number of faces only', false, 'eb4515f4-e672-4350-891d-6ef5b94774e8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7fcd7912-23c2-4a58-9bf6-7fdcccb6358a', 'Because edges must be multiples of 4', false, 'eb4515f4-e672-4350-891d-6ef5b94774e8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0accb52e-64a2-49c7-9412-a59c0c64548b', 'Class 7', 'Mathematics', 'Chapter 12: Symmetry & Visualising Solid Shapes', 'Hard', 'What grand spatial and geometric unification concludes the NCERT Class 7 Mathematics curriculum in Chapter 12?', 'Chapter 12 establishes spatial reasoning: reflectional/rotational invariance, polyhedral topology (Euler''s characteristic), and isometric projection.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9f610b5-5a53-4871-bd91-c5a4fd1a8971', 'Geometric symmetry and spatial 3D visualization unite reflectional invariants, rotational group orders, topological polyhedral networks (Euler''s formula), and 2D-to-3D projection mappings—forming the bedrock of modern architecture, computer graphics, CAD engineering, and crystallographic science', true, '0accb52e-64a2-49c7-9412-a59c0c64548b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f03fb53c-c390-49e4-bfc9-09d463c3bc29', 'That geometry is only useful for drawing paper shapes', false, '0accb52e-64a2-49c7-9412-a59c0c64548b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ff29787-bc22-4f88-800a-e9cbb53a42ca', 'That 3D solids cannot be drawn on 2D paper', false, '0accb52e-64a2-49c7-9412-a59c0c64548b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ce33546-608a-438a-bb0f-436ea6bdb1bf', 'That symmetry exists only in circles', false, '0accb52e-64a2-49c7-9412-a59c0c64548b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('dd9d3e60-2ac4-4dcb-9d80-93ac23feea28', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'In Leo Tolstoy''s opening parable ''Three Questions'' in Honeycomb, what three essential questions did the King seek answers to?', 'The King sought wisdom on the right time to act, the most important people to trust, and the supreme duty to perform.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aa08904-67b8-4677-a11a-eb64a8c5df72', '1. What was the right time to begin everything? 2. Which people should he listen to? 3. What was the most important thing for him to do?', true, 'dd9d3e60-2ac4-4dcb-9d80-93ac23feea28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46f71dcb-f414-4834-8ff0-653c45394c8c', 'How to win wars, where to find gold, and how to live forever', false, 'dd9d3e60-2ac4-4dcb-9d80-93ac23feea28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc72bad8-40b7-4d54-bc24-ffcb609d79bb', 'When to eat, where to sleep, and who to appoint as minister', false, 'dd9d3e60-2ac4-4dcb-9d80-93ac23feea28');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f0918f1-5803-4c1c-b482-93226d4e98a3', 'How to build castles, buy horses, and rule kingdoms', false, 'dd9d3e60-2ac4-4dcb-9d80-93ac23feea28');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('14074ef6-8ef7-4f59-82d5-033794b51585', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'In ''The Gift of Chappals'', what selfless act of kindness do the children (Ravi, Meena, and Mridu) perform for the blistered beggar?', 'Moved by compassion for the beggar''s blistered bare feet, the children spontaneously gift him the music teacher''s chappals.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c4ea70c-0045-48e2-b0bf-4a6dc946a1f5', 'They give him the music-master''s comfortable old leather chappals (slippers) because the beggar''s bare feet were scorched and blistered by the burning road', true, '14074ef6-8ef7-4f59-82d5-033794b51585');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('81cc7fea-0bf3-490a-85e3-146a24f18911', 'They give him gold coins', false, '14074ef6-8ef7-4f59-82d5-033794b51585');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33af43ec-2c66-4168-8a75-cf7778ae3827', 'They buy him a new car', false, '14074ef6-8ef7-4f59-82d5-033794b51585');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a0b25a6-2bac-475a-a991-6f052f1a6b43', 'They invite him to live in their palace', false, '14074ef6-8ef7-4f59-82d5-033794b51585');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ceb41ed8-42a2-4c71-8053-a09804ca92ad', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'In John Galsworthy''s moving short story ''Quality'', what craft did the noble German bootmaker Mr. Gessler dedicate his entire life to?', 'Mr. Gessler was a master craftsman who chose slow, artisanal perfection in bootmaking over cheap mass-produced commercialism.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75a27e86-f86d-4f89-95be-8f7a4554d716', 'Handmade bespoke leather boots of supreme craftsmanship and extraordinary durability', true, 'ceb41ed8-42a2-4c71-8053-a09804ca92ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e5297a5-29e4-481a-9320-43a3c202155b', 'Tailoring royal woolen coats', false, 'ceb41ed8-42a2-4c71-8053-a09804ca92ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ff588a91-ba17-4583-a2a2-418a53bc09d0', 'Making wooden furniture', false, 'ceb41ed8-42a2-4c71-8053-a09804ca92ad');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd175fcb-1242-4d62-8adf-6466fcf0f961', 'Painting oil portraits', false, 'ceb41ed8-42a2-4c71-8053-a09804ca92ad');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7c16b61e-9d1e-4418-be49-fef380015f24', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'What is the supreme moral conclusion delivered by the wise Hermit in ''Three Questions''?', 'The Hermit teaches: the only important time is ''Now'' (the present moment), our companions are our immediate priority, and doing good is our supreme purpose.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f95bb9a-5e5c-4012-ab8c-af131e78a192', 'The most important time is NOW (the present); the most important person is the one you are with; and the most important business is to DO GOOD to that person', true, '7c16b61e-9d1e-4418-be49-fef380015f24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('294d97d8-2d3d-4467-bbda-bc8716c91361', 'Wealth is the only goal in life', false, '7c16b61e-9d1e-4418-be49-fef380015f24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9fbfca5-d2dd-434b-b1d7-eb70b4dc3fac', 'Past actions determine everything', false, '7c16b61e-9d1e-4418-be49-fef380015f24');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0de0c665-fbde-4105-826e-44c67abf37ba', 'Kings should never help strangers', false, '7c16b61e-9d1e-4418-be49-fef380015f24');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('72c6786d-5a8e-446f-84b9-6e27de52d739', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'Identify the part of speech of the underlined word in: ''She sang **sweetly** during the concert.''', '''Sweetly'' is an adverb of manner modifying the verb ''sang''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19537309-6de3-4b1c-b814-36055f78ec40', 'Adverb of Manner', true, '72c6786d-5a8e-446f-84b9-6e27de52d739');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47da685e-834f-49b8-bc7e-60850fd18aa6', 'Adjective', false, '72c6786d-5a8e-446f-84b9-6e27de52d739');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8148f336-9428-46ef-8c09-7b567c4b45ec', 'Noun', false, '72c6786d-5a8e-446f-84b9-6e27de52d739');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b16df26e-bb32-474a-9913-3b3d00295cba', 'Preposition', false, '72c6786d-5a8e-446f-84b9-6e27de52d739');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e3862957-c1ff-4117-9f6d-8523ef3468d3', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'Fill in the blank with the correct modal auxiliary verb expressing strong obligation:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a9e449f-322d-473b-8e91-29b033a4e556', 'must', true, 'e3862957-c1ff-4117-9f6d-8523ef3468d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c86846a5-048e-4011-a5b3-5126252d3fa1', 'might', false, 'e3862957-c1ff-4117-9f6d-8523ef3468d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d991ba3b-dd83-443d-8724-ecd0aaaa5e20', 'could', false, 'e3862957-c1ff-4117-9f6d-8523ef3468d3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6aa71d51-064d-4f74-9258-22f8fddec95a', 'may', false, 'e3862957-c1ff-4117-9f6d-8523ef3468d3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0d7ea08d-e359-47e2-81ac-5bd392c660d9', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'Choose the correct antonym of the word ''Ancient'':', 'The antonym of ''ancient'' (belonging to the distant past) is ''modern''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4de2ca68-979b-4f78-a1ee-fb9fb7428425', 'Modern', true, '0d7ea08d-e359-47e2-81ac-5bd392c660d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1b2e138-8401-451a-8809-98ac191df167', 'Antique', false, '0d7ea08d-e359-47e2-81ac-5bd392c660d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc704175-636a-47cf-9e7e-76a2226a1265', 'Historic', false, '0d7ea08d-e359-47e2-81ac-5bd392c660d9');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a258ea60-a141-42c5-9acb-f592871a8b78', 'Aged', false, '0d7ea08d-e359-47e2-81ac-5bd392c660d9');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2cb146c8-4791-463b-bc3b-c5ea00600bc5', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'Choose the correct synonym of ''Compassion'':', '''Compassion'' signifies deep sympathetic pity and concern for the sufferings of others.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a25fdec1-89d0-49b1-9558-64819c9bdb7c', 'Empathy / Kindness / Sympathy', true, '2cb146c8-4791-463b-bc3b-c5ea00600bc5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a2b8143a-a8b6-4420-90f0-dca1f0a498fc', 'Cruelty', false, '2cb146c8-4791-463b-bc3b-c5ea00600bc5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('54f47ca4-50cb-4677-9d4e-9258022698fb', 'Jealousy', false, '2cb146c8-4791-463b-bc3b-c5ea00600bc5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('44a9a0d1-7596-4891-8d5b-2426bbd9bd94', 'Arrogance', false, '2cb146c8-4791-463b-bc3b-c5ea00600bc5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d5dc38d5-b564-4f2e-9e68-db55dfe3041f', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'Convert into PASSIVE VOICE:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1e97d57f-5600-4525-a88b-14aeb034d8ff', '''These durable leather boots were made by the master craftsman.''', true, 'd5dc38d5-b564-4f2e-9e68-db55dfe3041f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d344d0d8-417f-43d6-801e-cc6cf17a3279', '''These durable leather boots made the master craftsman.''', false, 'd5dc38d5-b564-4f2e-9e68-db55dfe3041f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcd79436-79b6-43dd-94a1-a3f180152ed5', '''The boots was made by master craftsman.''', false, 'd5dc38d5-b564-4f2e-9e68-db55dfe3041f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0698f197-cfd1-49d3-bb1b-9da4f427a155', '''By the boots were made the craftsman.''', false, 'd5dc38d5-b564-4f2e-9e68-db55dfe3041f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b30b359d-ad13-4fc3-a2e2-0f10bab1de77', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'What is a ''Gerund'' in English grammar?', 'A gerund is a non-finite verbal noun formed by adding ''-ing'' to the base verb (e.g. ''Reading enriches the mind'').', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b3459d9-8ac2-4834-99f0-d9567a93d568', 'A verb form ending in ''-ing'' that functions as a NOUN in a sentence (e.g. ''Swimming is healthy'')', true, 'b30b359d-ad13-4fc3-a2e2-0f10bab1de77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65ca0a8d-9f53-4779-85be-4a6df8ed7d20', 'A verb in past tense', false, 'b30b359d-ad13-4fc3-a2e2-0f10bab1de77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9cfd548c-8441-45d6-9048-832638048828', 'An adjective that describes colors', false, 'b30b359d-ad13-4fc3-a2e2-0f10bab1de77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27a4c400-bd35-4ef6-965d-a2ba5caa2236', 'A conjunction connecting two sentences', false, 'b30b359d-ad13-4fc3-a2e2-0f10bab1de77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('90e0f234-c8f6-44fa-8de6-b6bccf2fd083', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'Which punctuation mark is used to enclose direct spoken dialogue in English narrative writing?', 'Direct speech in dialogue is framed within quotation marks / inverted commas (" ").', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('037bb25a-bee5-4b94-badf-b6ce6afd4386', 'Quotation Marks / Inverted Commas (" ")', true, '90e0f234-c8f6-44fa-8de6-b6bccf2fd083');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9546585b-1276-4748-8f43-3e12ee5bd9c7', 'Semicolon (;)', false, '90e0f234-c8f6-44fa-8de6-b6bccf2fd083');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70b7b82f-8079-4841-9484-12d62241e1ac', 'Hyphen (-)', false, '90e0f234-c8f6-44fa-8de6-b6bccf2fd083');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13acf90a-4756-47ed-bbe6-b0ef21823651', 'Slash (/)', false, '90e0f234-c8f6-44fa-8de6-b6bccf2fd083');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('769703e6-b23e-493a-8d81-c3c2af635c6f', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Easy', 'In the poem ''The Rebel'' by D.J. Enright, what does the rebel always do?', 'D.J. Enright''s poem humorously portrays the rebel as someone who habitually contradicts social conventions to be uniquely different.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7580b55a-1466-4357-96e6-33f9c720decd', 'He does the exact opposite of what everybody else is doing to assert his individuality', true, '769703e6-b23e-493a-8d81-c3c2af635c6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('886d0802-066b-4a0f-b0ee-b483bd024f72', 'He follows all rules strictly', false, '769703e6-b23e-493a-8d81-c3c2af635c6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b99932cf-925a-4be1-ae3a-e2652071c0c0', 'He sleeps all day', false, '769703e6-b23e-493a-8d81-c3c2af635c6f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b449b88-4b18-4791-9526-ad1015a9b0da', 'He never speaks', false, '769703e6-b23e-493a-8d81-c3c2af635c6f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6633c5a7-087a-4dab-a5a4-7469227ab12e', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'In ''The Cop and the Anthem'' by O. Henry, why does Soapy desperately try to get arrested by a police officer?', 'Soapy, a homeless man in New York, deliberately seeks arrest to secure free shelter and meals in the island prison for the winter.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('24cb0f28-ef46-4fb9-803e-9fbd174661ea', 'He wants to spend the three harsh winter months in the warmth and comfort of Blackwell''s Island prison with guaranteed food and shelter', true, '6633c5a7-087a-4dab-a5a4-7469227ab12e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('893f4dd0-854d-4fdf-9ead-2627fe5c0304', 'He wants to become a police officer', false, '6633c5a7-087a-4dab-a5a4-7469227ab12e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a7d344d0-932b-4689-8c43-a3b211e50660', 'He wants to steal a diamond necklace', false, '6633c5a7-087a-4dab-a5a4-7469227ab12e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6bcd708-3cc4-413c-a3dd-712d9d042f62', 'He wants to leave New York by train', false, '6633c5a7-087a-4dab-a5a4-7469227ab12e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('85bf3f41-fb1d-4aed-8eab-3635b7bd21c1', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'What is the poignant situational irony at the end of O. Henry''s ''The Cop and the Anthem''?', 'Classic O. Henry twist: Soapy fails when trying to get arrested, but gets arrested the exact moment he resolves to reform his life.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e47af0a-8ce9-4338-9614-69c5ea7c45f2', 'Just when an organ anthem at a church inspires Soapy to reform his life and find honest work, a policeman arrests him for loitering, and the judge sentences him to three months in prison', true, '85bf3f41-fb1d-4aed-8eab-3635b7bd21c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6570fa9-fc6d-423c-bae3-80f2e28aa43c', 'Soapy finds a million dollars on the street', false, '85bf3f41-fb1d-4aed-8eab-3635b7bd21c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('46c7a400-945c-4b19-990a-95e9da50bcf1', 'The church burns down', false, '85bf3f41-fb1d-4aed-8eab-3635b7bd21c1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1e800f5-d98a-4ad3-8c66-23b5d3d4437c', 'Soapy becomes mayor of the city', false, '85bf3f41-fb1d-4aed-8eab-3635b7bd21c1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('69f5121b-5f5d-49e7-9f6a-b1f92f4763bc', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'In Ruskin Bond''s charming story ''A Tiger in the House'', how did grandfather discover the tiger cub Timothy?', 'Grandfather discovered the abandoned eighteen-inch tiger cub in the Terai jungles and brought him home, naming him Timothy.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82b7b15a-9892-40ea-97ba-8ab15c2ae5b3', 'During a hunting expedition in the Terai jungle near Dehra, grandfather found the tiny eighteen-inch cub hiding among the roots of a banyan tree', true, '69f5121b-5f5d-49e7-9f6a-b1f92f4763bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bf2faf31-3438-4853-a91f-771f523e4f9f', 'He bought it from a pet shop', false, '69f5121b-5f5d-49e7-9f6a-b1f92f4763bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc081a75-628c-4e41-9807-9d12c7406622', 'The cub walked into their kitchen', false, '69f5121b-5f5d-49e7-9f6a-b1f92f4763bc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e9a89cdb-414e-4750-8e22-8c170235b0e8', 'He found it at the zoo', false, '69f5121b-5f5d-49e7-9f6a-b1f92f4763bc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c9033bd5-702e-4d3b-980e-7378876618bf', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'Why did Grandfather decide to transfer Timothy the tiger to the Lucknow zoo when Timothy turned six months old?', 'As Timothy matured into an apex carnivore, his predatory instincts emerged, making it unsafe to keep him in a domestic household.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb0c72aa-d6c0-48aa-a5e6-5ab0f6331fc4', 'Timothy grew steadily less friendly, stalked the family cat with sinister intent, and began eyeing the cook Mahmoud hungrily', true, 'c9033bd5-702e-4d3b-980e-7378876618bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89a1148f-0bd4-4668-8f5e-e73ad70c424d', 'Timothy stopped eating meat', false, 'c9033bd5-702e-4d3b-980e-7378876618bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df22f541-65c5-4bbd-94bb-d1b48d6a3c11', 'Grandfather moved to London', false, 'c9033bd5-702e-4d3b-980e-7378876618bf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef81f6eb-ab0b-4554-b670-42abd25ca70b', 'The house was sold', false, 'c9033bd5-702e-4d3b-980e-7378876618bf');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31ccf25e-844f-454d-b2e3-2b48cf880630', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'In ''I Want Something in a Cage'' by L.E. Morgan, what does the mysterious stranger do with the two white doves he buys from Mr. Purcell''s pet shop?', 'Having spent ten agonizing years in prison, the stranger understands the supreme value of liberty, spending his hard-earned money to liberate caged doves.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f62ebaa-8ae0-4690-86b6-1d45bd2aecaf', 'He immediately takes them outside the shop and releases them into the open sky to fly free', true, '31ccf25e-844f-454d-b2e3-2b48cf880630');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ad7f15f4-0155-41c8-8049-a079b746e3e9', 'He cooks them for dinner', false, '31ccf25e-844f-454d-b2e3-2b48cf880630');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4b1e593-7f54-47ca-badb-9dcf8c3ac26d', 'He puts them in a gold cage', false, '31ccf25e-844f-454d-b2e3-2b48cf880630');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0fbf4a47-717f-4155-8f4e-8a7b9cacf0dc', 'He sells them to another shop', false, '31ccf25e-844f-454d-b2e3-2b48cf880630');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('63a0000d-541d-4a3b-ac65-e27f48c95129', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'In ''Chandni'' by Zakir Husain, why does the courageous goat Chandni choose to fight the wolf on the mountain rather than return to the safety of Abbu Khan''s hut?', 'Chandni embodies the heroic spirit of freedom, choosing mortal combat for liberty over comfortable domestic confinement.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b9bf78f4-3e2a-414c-8820-2ff8866ef6b0', 'She values freedom and self-respect above a long life of captivity in a closed hut: ''Death in an open field is better than life in a small hut''', true, '63a0000d-541d-4a3b-ac65-e27f48c95129');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1212b84d-3c93-455e-866b-c0907d71c803', 'She believes she is stronger than the wolf', false, '63a0000d-541d-4a3b-ac65-e27f48c95129');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('996b6787-7e34-4bef-aac8-0921d573e9b0', 'She hates Abbu Khan', false, '63a0000d-541d-4a3b-ac65-e27f48c95129');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f839292-18dd-4e24-9a32-23a444466277', 'She wants to rule the mountain', false, '63a0000d-541d-4a3b-ac65-e27f48c95129');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2e207729-1e80-4e00-8b87-5ffc894efcc1', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'Identify the SUBJECT and PREDICATE in the sentence:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b2a1bdd6-fd65-4a63-a85f-cd58139edaed', 'Subject: ''The ancient banyan tree in the village'' ; Predicate: ''provided shade to weary travelers''', true, '2e207729-1e80-4e00-8b87-5ffc894efcc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2f432885-7c85-497d-82a5-fba65e2b2df5', 'Subject: ''The ancient'' ; Predicate: ''banyan tree''', false, '2e207729-1e80-4e00-8b87-5ffc894efcc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('664b442a-f7e3-4e4e-ba5d-8cda42e8c9b0', 'Subject: ''weary travelers'' ; Predicate: ''provided shade''', false, '2e207729-1e80-4e00-8b87-5ffc894efcc1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcbdf06e-658e-466b-bc9b-bee4127fa81a', 'Subject: ''in the village'' ; Predicate: ''tree provided''', false, '2e207729-1e80-4e00-8b87-5ffc894efcc1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('88f5495d-9e01-49ac-b125-b53b0b8e6c7b', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'Choose the correct Subject-Verb Agreement:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('18dee3f9-85a3-42e0-9762-9b01802a2d67', 'were', true, '88f5495d-9e01-49ac-b125-b53b0b8e6c7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('42940649-da72-4554-b7ab-7f0c62e2fb06', 'was', false, '88f5495d-9e01-49ac-b125-b53b0b8e6c7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7a39582-26f1-4131-a3db-615c2a8a1360', 'is', false, '88f5495d-9e01-49ac-b125-b53b0b8e6c7b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ced0d5cd-d7e8-4800-919b-b98513579672', 'are', false, '88f5495d-9e01-49ac-b125-b53b0b8e6c7b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('12dbeefe-613d-4795-b64b-736c92bd1434', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'Choose the correct Subject-Verb Agreement:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7950e36-af40-440e-8702-091c9d8b1fca', 'was', true, '12dbeefe-613d-4795-b64b-736c92bd1434');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e51c17cf-3c4d-4a3b-9d37-fae70dea565a', 'were', false, '12dbeefe-613d-4795-b64b-736c92bd1434');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb53e2ba-33b8-4307-bfd3-d2502cea1d85', 'are', false, '12dbeefe-613d-4795-b64b-736c92bd1434');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd9bea13-a885-4995-aab2-58ca1d299d99', 'have been', false, '12dbeefe-613d-4795-b64b-736c92bd1434');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a83a5b9d-4a8e-4cec-a2e9-91718f46abb7', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'Convert to INDIRECT SPEECH:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('17a7e788-e356-4321-90b1-703feafa115d', 'The hermit told the king that he had already been answered.', true, 'a83a5b9d-4a8e-4cec-a2e9-91718f46abb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('734e06b5-0b22-4cb4-ba99-76ec9b1f4cb7', 'The hermit said the king that you have been answered.', false, 'a83a5b9d-4a8e-4cec-a2e9-91718f46abb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7d86e303-02d5-461b-9e05-04da01c680fa', 'The hermit asked the king if he was answered.', false, 'a83a5b9d-4a8e-4cec-a2e9-91718f46abb7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d71d080-764d-41dd-8cb0-6adca099d117', 'The hermit told the king you had already been answered.', false, 'a83a5b9d-4a8e-4cec-a2e9-91718f46abb7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf6fe1d5-cae6-4aad-9d5a-b103774baa03', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'What is the meaning of the phrasal verb ''To give up''?', '''Give up'' is an idiomatic phrasal verb meaning to quit, abandon an effort, or surrender.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ce9d55c8-3bf7-492d-8b54-cfc3646a3797', 'To abandon / To cease doing something / To surrender', true, 'bf6fe1d5-cae6-4aad-9d5a-b103774baa03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9191542d-caff-4c36-aa77-77ff0012d910', 'To hand over a gift', false, 'bf6fe1d5-cae6-4aad-9d5a-b103774baa03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62f4272e-f76b-4563-812d-397f245224f3', 'To climb upwards', false, 'bf6fe1d5-cae6-4aad-9d5a-b103774baa03');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('23f04ee5-8a60-4850-b548-d5db0aa05c8b', 'To look for something', false, 'bf6fe1d5-cae6-4aad-9d5a-b103774baa03');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('27247f27-2159-4126-adda-9322b3ef4b38', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'Identify the figure of speech in: ''The wind whispered through the dark pine trees.''', 'Personification endows natural elements (wind) with human behavioral traits (whispering).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('385fab98-2a89-4cc4-a760-b8187151dc8e', 'Personification (attributing the human action of ''whispering'' to non-human wind)', true, '27247f27-2159-4126-adda-9322b3ef4b38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6031a995-0ef3-4c6f-9715-8b7c4690aef4', 'Simile', false, '27247f27-2159-4126-adda-9322b3ef4b38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('725f9fc9-b691-47b2-a99d-4f0c156a0cf7', 'Metaphor only', false, '27247f27-2159-4126-adda-9322b3ef4b38');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae5b9f00-feb8-4d5e-bcd5-219f0f4b027f', 'Hyperbole', false, '27247f27-2159-4126-adda-9322b3ef4b38');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1eb9d571-9d02-4fbd-a443-74f545f539ca', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'What type of conditional clause is: ''If it rains tomorrow, we will cancel the outdoor picnic.''?', 'First Conditional structures express realistic future possibilities using ''If + Present Simple, will + Infinitive''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67b44dba-c126-4863-9433-9b8c62823b9a', 'First Conditional (Real / Probable future condition: If + Present Simple, will + base verb)', true, '1eb9d571-9d02-4fbd-a443-74f545f539ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de06a0d6-d1cf-480e-8ee6-203a54c2cbda', 'Zero Conditional', false, '1eb9d571-9d02-4fbd-a443-74f545f539ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38ff8d67-30a6-4cdc-87e2-975549e47d37', 'Second Conditional', false, '1eb9d571-9d02-4fbd-a443-74f545f539ca');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3154032-f668-4810-89fd-64555bb64e6f', 'Third Conditional', false, '1eb9d571-9d02-4fbd-a443-74f545f539ca');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b8c3b5e7-fc9f-4587-8238-22d331ce69c4', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'Choose the correct spelling:', 'Correct orthography: P-E-R-S-E-V-E-R-A-N-C-E.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfc9b13e-8635-4e00-ae8e-c36365e21095', 'Perseverance', true, 'b8c3b5e7-fc9f-4587-8238-22d331ce69c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('779829a9-fd35-4ee7-9aba-636815639846', 'Perseverence', false, 'b8c3b5e7-fc9f-4587-8238-22d331ce69c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45c8f3ef-5c54-4dd3-9e73-47592094e74b', 'Perceverance', false, 'b8c3b5e7-fc9f-4587-8238-22d331ce69c4');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fa92c393-074a-48a9-9d50-4a0a100b099e', 'Persevarance', false, 'b8c3b5e7-fc9f-4587-8238-22d331ce69c4');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('91a6e2f2-780a-4bd7-b4a8-ab042f5c3e70', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'What is the meaning of the idiom ''To burn the candle at both ends''?', 'Idiom meaning: exhausting one''s physical energy through relentless overwork and late-night toil.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86fdd988-278b-44ba-9dc2-ab44bfe9d87e', 'To work excessively hard from early morning until late at night without adequate rest', true, '91a6e2f2-780a-4bd7-b4a8-ab042f5c3e70');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1dac1827-5413-48d3-a842-3a92a34d56f7', 'To waste money on candles', false, '91a6e2f2-780a-4bd7-b4a8-ab042f5c3e70');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f53420b8-6eb5-4a48-bcc9-2c71d4e23a12', 'To set a house on fire', false, '91a6e2f2-780a-4bd7-b4a8-ab042f5c3e70');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f8770f4-d035-45d4-9b79-7c961d9b53e1', 'To make candles in a factory', false, '91a6e2f2-780a-4bd7-b4a8-ab042f5c3e70');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('22bf612a-8efd-46cd-aa55-5b70d7c1c49d', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Medium', 'Identify the type of non-finite verb in the underlined phrase: ''**Walking briskly**, she reached the station on time.''', '''Walking briskly'' is a Present Participial Phrase modifying the subject pronoun ''she''.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('82513fef-e43f-4de1-ae47-379f8d8f522a', 'Present Participle (functioning as a participial modifier)', true, '22bf612a-8efd-46cd-aa55-5b70d7c1c49d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ce47908-5cfe-425c-aaa1-743e3205d5bd', 'Gerund', false, '22bf612a-8efd-46cd-aa55-5b70d7c1c49d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ae084dc-5cfa-49cc-a10e-232c1bdbf9f3', 'Infinitive', false, '22bf612a-8efd-46cd-aa55-5b70d7c1c49d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9e69838f-5a7d-4387-88ee-acfcbb7c0494', 'Finite verb', false, '22bf612a-8efd-46cd-aa55-5b70d7c1c49d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('13db234e-875c-43c1-90a4-4f4bf2a897e5', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('430f2c45-4b1b-4f38-ac15-5bcaef1d8e92', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, '13db234e-875c-43c1-90a4-4f4bf2a897e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c91f8a05-f14f-4971-a775-d8f27ccc2bf4', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, '13db234e-875c-43c1-90a4-4f4bf2a897e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5d71db2-9de9-48ee-9c67-a8fda0f6ecc6', '(A) is true, but (R) is false.', false, '13db234e-875c-43c1-90a4-4f4bf2a897e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b43544bc-bda4-4f7e-9994-9cdbafe777aa', '(A) is false, but (R) is true.', false, '13db234e-875c-43c1-90a4-4f4bf2a897e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ddc24ba8-ef12-4f1f-8e10-262512779b8b', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'Spot the IMPOSTER in the following matching of NCERT Class 7 English classic stories and their overarching thematic motifs:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cb8a66f7-7d93-4cdc-a0e3-f265111f5d43', 'Story 1', false, 'ddc24ba8-ef12-4f1f-8e10-262512779b8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b97bf07c-9669-401a-b6a6-354a4cc096c7', 'Story 2', false, 'ddc24ba8-ef12-4f1f-8e10-262512779b8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a1aae675-8fdf-4cd3-a3fd-cde6e77025db', 'Story 3', false, 'ddc24ba8-ef12-4f1f-8e10-262512779b8b');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cd3d1844-e389-4a08-9d1b-fce702f00e77', 'Story 4 (''The Story of Cricket'' by Ramachandra Guha is a historical-sociological essay on sports, empire, and media, NOT a fairy tale about dragons)', true, 'ddc24ba8-ef12-4f1f-8e10-262512779b8b');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6797bfc3-1277-44e2-9192-6b2477375f23', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'Analyze the syntactic grammar of the complex sentence:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11b18d06-c855-46b5-9685-6ef24cc33900', '''he refused to compromise on the flawless quality of his craftsmanship''', true, '6797bfc3-1277-44e2-9192-6b2477375f23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5cf4e0f-56bc-42f9-978f-ee93fd7fed51', '''Although Mr. Gessler suffered immense financial loss''', false, '6797bfc3-1277-44e2-9192-6b2477375f23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9296f9f-4348-458f-9351-3c88bf407c13', '''because large commercial firms dominated the boot market''', false, '6797bfc3-1277-44e2-9192-6b2477375f23');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b43f90d6-19ba-4b7c-8f7b-b8d777b4630c', '''of his craftsmanship''', false, '6797bfc3-1277-44e2-9192-6b2477375f23');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1983b4d8-04e3-42b5-8bcc-aac0dc066f42', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'Match Column I (Grammatical Structures) with Column II (Illustrative Sentence Examples):
(a) Subjunctive Mood       -> (i) The committee recommended that he **be** appointed immediately.
(b) Third Conditional      -> (ii) If he **had practiced**, he **would have won** the debate.
(c) Gerund Phrase          -> (iii) **Reading classical literature** broadens human empathy.
(d) Passive Transformation  -> (iv) The sacred manuscripts **were preserved** by the monks.', 'Subjunctive = bare ''be''; 3rd conditional = had practiced/would have won; Gerund = Reading literature; Passive = were preserved.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f1d1544-86e4-49d9-a206-9f20f29aa2a4', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '1983b4d8-04e3-42b5-8bcc-aac0dc066f42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c0f7e94-8ec8-4355-95f1-06effb3a51e6', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '1983b4d8-04e3-42b5-8bcc-aac0dc066f42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8570a4d-fe58-43db-aac8-b03199e4a5f6', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '1983b4d8-04e3-42b5-8bcc-aac0dc066f42');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0ec8d22-46f6-4fec-a071-4d255f883584', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '1983b4d8-04e3-42b5-8bcc-aac0dc066f42');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('900fdd94-8bd3-4909-8d7c-b92c50081c81', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'Read the statements regarding grammatical rules:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('afa64141-5c0a-4809-b04e-c75ca919f203', 'Statements 1 and 2 only', true, '900fdd94-8bd3-4909-8d7c-b92c50081c81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7389196d-9c8f-4714-b9c7-64d53f9e5646', 'Statements 2 and 3 only', false, '900fdd94-8bd3-4909-8d7c-b92c50081c81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8fdfaffa-a351-4a89-b9b6-1a7a4fa81615', 'Statements 1 and 3 only', false, '900fdd94-8bd3-4909-8d7c-b92c50081c81');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3d9b471a-c688-40e7-aa9b-5fe83bb84729', 'All Statements 1, 2, and 3', false, '900fdd94-8bd3-4909-8d7c-b92c50081c81');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9bec886c-a88b-400a-8723-87c6a9034880', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'In John Galsworthy''s ''Quality'', what tragic fate befalls master craftsman Mr. Gessler at the climax of the story?', 'Mr. Gessler''s tragic demise: dying of chronic malnutrition (''slow starvation'') while stubbornly upholding uncompromising artisanal perfection.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('97c53256-025d-4bb0-83f9-a32c4ed92d46', 'He dies of slow starvation (''starvation of character'') because he invested all his earnings into rent and the finest leathers, starving himself to finish customer orders', true, '9bec886c-a88b-400a-8723-87c6a9034880');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('87e28587-80f0-4282-8f9f-a37519660532', 'He becomes a wealthy factory owner', false, '9bec886c-a88b-400a-8723-87c6a9034880');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8c83460-754d-491f-b91f-8f53472fd5e2', 'He moves to America to build rockets', false, '9bec886c-a88b-400a-8723-87c6a9034880');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('07c5147f-41eb-4ab7-8ed0-a537d769d556', 'He is elected mayor of London', false, '9bec886c-a88b-400a-8723-87c6a9034880');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3d08bf56-668e-4018-acbd-cb074dc872de', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'Which of the following sentences exhibits FLAWLESS punctuation, capitalization, and syntax?', 'Option 1 follows standard dialogue punctuation: comma inside quotes, lower-case attribution tag, followed by lowercase continuation quote.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('38c691cc-4213-4b74-9d02-a19227ad8007', '"If you have compassion for all living beings," remarked the philosopher, "you will find true inner peace."', true, '3d08bf56-668e-4018-acbd-cb074dc872de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1a93124-6b2d-4549-994d-78310f28aecd', '"If you have compassion for all living beings" remarked the philosopher, "You will find true inner peace."', false, '3d08bf56-668e-4018-acbd-cb074dc872de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c5aa9eda-2c3e-4a15-baec-2614fbaab73d', 'If you have compassion for all living beings, remarked the philosopher "you will find true inner peace."', false, '3d08bf56-668e-4018-acbd-cb074dc872de');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e428b338-5066-4141-a5fd-ca7e0895e8e9', '"If you have compassion for all living beings", remarked the philosopher; "you will find true inner peace."', false, '3d08bf56-668e-4018-acbd-cb074dc872de');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('941bf100-70c3-4426-b095-3b370360f77a', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'What is the psychological significance of the bear in ''The Bear Story'' by Axel Munthe?', 'Axel Munthe''s comedy of errors: mistaken identity between a gentle domesticated pet bear and a bewildered wild forest bear.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('277cce34-ee1e-45de-9450-7b4683e06cc3', 'The tame, vegetarian bear is so gentle and disciplined that when the lady mistakenly scolds and beats a wild bear in the forest thinking it was her pet, the real pet bear looks bewildered at her anger at home', true, '941bf100-70c3-4426-b095-3b370360f77a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96c696b4-fedd-49f3-8d22-44ee4ebded20', 'The bear was a robot', false, '941bf100-70c3-4426-b095-3b370360f77a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d294d411-1c69-49ec-881b-32e807f1e639', 'The bear ate everyone in the village', false, '941bf100-70c3-4426-b095-3b370360f77a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96255999-d7d1-445d-91f0-f6c59342bf83', 'The bear was invisible', false, '941bf100-70c3-4426-b095-3b370360f77a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bef7f926-51db-4da4-a4cf-ed788b41dbc6', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'Identify the grammatical error in the sentence:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dbccea47-ca2e-4018-8b1c-47dead82d749', 'Error in verb: ''was'' should be replaced by ''were'' (because the plural subject ''sailors'' is closer to the verb)', true, 'bef7f926-51db-4da4-a4cf-ed788b41dbc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2cde0775-cce7-432e-bfd3-8805fad5cab8', 'Error in ''neither...nor''', false, 'bef7f926-51db-4da4-a4cf-ed788b41dbc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b5af08fd-db35-4cda-b89a-7639d1a335e3', 'Error in ''during the hurricane''', false, 'bef7f926-51db-4da4-a4cf-ed788b41dbc6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8aa83af1-7bb3-4018-926e-c259b0607a67', 'There is no error in the sentence', false, 'bef7f926-51db-4da4-a4cf-ed788b41dbc6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('0fc4bdfd-554c-4739-9fa1-eb610244b866', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'What is the rhetorical effect of ''Anaphora'' in poetic verse?', 'Anaphora (e.g. in ''Trees'' or ''Meadow Surprises'') builds cumulative emotional resonance through rhythmic initial phrase repetition.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3f1be458-bb43-4b99-8670-6c840478a639', 'The deliberate repetition of a word or phrase at the beginning of successive sentences or verse lines to create rhythm, emotional intensity, and thematic emphasis', true, '0fc4bdfd-554c-4739-9fa1-eb610244b866');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('895747ae-8050-4431-9c6c-958b3237ede0', 'Using rhymes at the end of lines only', false, '0fc4bdfd-554c-4739-9fa1-eb610244b866');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('498606b0-7f81-487f-bb0a-a7646f4a8cfb', 'Writing without any verbs', false, '0fc4bdfd-554c-4739-9fa1-eb610244b866');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dfc1ca38-c94f-4f79-9ac6-e6baa3497d44', 'Translating poems into Latin', false, '0fc4bdfd-554c-4739-9fa1-eb610244b866');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c5edb26f-5885-4285-bcfc-c720a43bcb8d', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'In ''Golu Grows a Nose'' by Rudyard Kipling, how did the inquisitive young elephant Golu obtain his long trunk?', 'Kipling''s ''Just So'' fable: Golu''s nose stretches during a tug-of-war with a crocodile on the banks of the great grey-green Limpopo River.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3c975841-262f-4414-9c89-3b88ad1149ac', 'The Crocodile in the Limpopo River seized Golu by his small bulgy nose and pulled; during the intense tug-of-war, Golu''s nose stretched out into a five-foot-long versatile trunk', true, 'c5edb26f-5885-4285-bcfc-c720a43bcb8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('064a9c67-ed96-4b08-84df-d32c0e326ed2', 'He was born with it', false, 'c5edb26f-5885-4285-bcfc-c720a43bcb8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a14e41c-b060-4823-b839-9692199a085c', 'A doctor gave him a magic potion', false, 'c5edb26f-5885-4285-bcfc-c720a43bcb8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d7f1cf05-6401-4d84-8866-2dc55f0cf6be', 'A tree branch fell on his face', false, 'c5edb26f-5885-4285-bcfc-c720a43bcb8d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ee037d23-6b8d-4b60-82e1-fda266d54474', 'Class 7', 'English', 'Chapter 12: Master Literature Themes & Applied Grammar Review', 'Hard', 'What grand linguistic and humanistic mastery concludes Chapter 12 of NCERT Class 7 English?', 'Chapter 12 synthesizes syntactic mastery, applied rhetoric, ethical contemplation, and nuanced literary appreciation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a42a591f-9fa8-497a-9249-20538b618818', 'Mastery of the English language integrates grammatical precision, sophisticated rhetorical eloquence, and deep literary contemplation—empowering learners to articulate ideas persuasively, understand human nature, and cultivate lifelong intellectual empathy', true, 'ee037d23-6b8d-4b60-82e1-fda266d54474');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d64f1174-a577-45f0-a08f-c5183ca36728', 'That grammar rules should be memorized without understanding', false, 'ee037d23-6b8d-4b60-82e1-fda266d54474');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f97eaae5-e90c-42a7-86bb-d5fb35fe9a15', 'That literature has no connection to real life', false, 'ee037d23-6b8d-4b60-82e1-fda266d54474');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25c31eab-9407-4cfe-bf2f-3ea034b4290f', 'That writing is only for passing school exams', false, 'ee037d23-6b8d-4b60-82e1-fda266d54474');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('498815cd-c919-411e-a721-0409db13dbe1', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Easy', 'When is ''WORLD ENVIRONMENT DAY'' celebrated globally every year under the United Nations Environment Programme (UNEP)?', 'World Environment Day is observed on June 5 annually since 1973 to drive global awareness and action for environmental protection.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa90e846-5de1-4ce0-bf41-f889227a5a23', 'June 5', true, '498815cd-c919-411e-a721-0409db13dbe1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ca9e32c-3352-4a8b-a85d-10c84f0f231e', 'April 22', false, '498815cd-c919-411e-a721-0409db13dbe1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e274d6e-2ffd-4987-baf6-b503228c6bfe', 'March 21', false, '498815cd-c919-411e-a721-0409db13dbe1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ac45aeec-c2d1-4866-9fcf-61acec6410fe', 'September 16', false, '498815cd-c919-411e-a721-0409db13dbe1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04f4446c-ec83-4f38-b057-ec3e96729bcf', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Easy', 'When is ''EARTH DAY'' celebrated internationally each year to demonstrate support for environmental protection?', 'Earth Day (first celebrated on 22 April 1970) mobilizes over a billion people in 190+ countries for environmental conservation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('47409021-221c-4fb5-9dea-254df6039b8f', 'April 22', true, '04f4446c-ec83-4f38-b057-ec3e96729bcf');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('06eca790-52cf-4bb8-8251-58864bde1395', 'June 5', false, '04f4446c-ec83-4f38-b057-ec3e96729bcf');
