INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e2aced2b-82bb-411c-98c8-ecde066881e7', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is ''Net-Zero Emissions'' (Carbon Neutrality)?', 'Net-Zero means emissions are slashed to near-zero, with any residual unavoidable emissions absorbed by natural carbon sinks or DAC technologies.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d0e14a3f-489e-46b7-a4d6-7d70a67e8134', 'Achieving an overall balance where any human-caused greenhouse gas emissions released into the atmosphere are completely balanced and neutralized by equivalent carbon removal (via forests, carbon capture, ocean sinks)', true, 'e2aced2b-82bb-411c-98c8-ecde066881e7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68193110-23bf-48c3-b17d-6dbf1427db89', 'Banning all factories and electricity', false, 'e2aced2b-82bb-411c-98c8-ecde066881e7');
