INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('53c694db-c889-475b-a33e-fbb5dc1d1e41', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is ''GREEN HYDROGEN'' in clean energy transition?', 'Green Hydrogen is the holy grail of zero-emission fuel, decarbonizing heavy industries (steel, cement, fertilizers, shipping) using renewable electrolysis.', NOW()) ON CONFLICT DO NOTHING;
