INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('651abdc8-5a02-471b-9a33-cf6a37bdefdc', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is the ''Intergovernmental Panel on Climate Change'' (IPCC)?', 'The IPCC (Nobel Peace Prize 2007) produces definitive Assessment Reports (like AR6) guiding global climate policy and treaty negotiations.', NOW()) ON CONFLICT DO NOTHING;
