INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2d3b19db-becf-46f2-b21f-f38425f70e96', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is ''Ocean Acidification'' caused by rising atmospheric carbon dioxide levels?', 'CO₂ + H₂O → H₂CO₃; seawater acidification depletes carbonate ions, imperiling coral reefs (Great Barrier Reef) and marine food webs.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02491b5a-ecea-4ac8-ab9a-02eec218ae89', 'The oceans absorb ~30% of atmospheric CO₂, forming carbonic acid, which lowers seawater pH and dissolves calcium carbonate shells/skeletons of corals, mollusks, and plankton', true, '2d3b19db-becf-46f2-b21f-f38425f70e96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9b5bc01c-4470-40f5-a3b2-03a142dda7a1', 'Oceans turning into vinegar', false, '2d3b19db-becf-46f2-b21f-f38425f70e96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('da729313-a27c-41a5-a491-efcdee7365f4', 'Salt disappearing from seawater', false, '2d3b19db-becf-46f2-b21f-f38425f70e96');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fbd282b7-3454-44ee-8c68-40c3c5d1284e', 'Ocean water turning into fresh drinking water', false, '2d3b19db-becf-46f2-b21f-f38425f70e96');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('948e3c07-496c-46aa-968f-fcf7d75aad51', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'Which global conservation organization publishes the authoritative ''IUCN RED LIST'' of threatened biological species?', 'The IUCN Red List of Threatened Species is the world''s most comprehensive inventory of the global conservation status of biological species.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df19e98b-29aa-4c29-bd00-4475862bc2da', 'International Union for Conservation of Nature (IUCN)', true, '948e3c07-496c-46aa-968f-fcf7d75aad51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee8be199-de14-480a-b524-14963ce997c3', 'World Wildlife Fund (WWF)', false, '948e3c07-496c-46aa-968f-fcf7d75aad51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5bef7e2f-9fa7-4ecb-909e-25761aa8d3ed', 'Greenpeace', false, '948e3c07-496c-46aa-968f-fcf7d75aad51');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a79c02ee-8b4e-406e-8919-32efb72d5fc5', 'United Nations Development Programme', false, '948e3c07-496c-46aa-968f-fcf7d75aad51');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf1099f0-8b5a-4149-a01d-3f0af97d33b8', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is the ''Great Green Wall'' initiative in Africa?', 'The Great Green Wall combats desertification across 11 Sahelian nations by restoring 100 million hectares of degraded land by 2030.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9c69cb1c-11f2-4975-b575-fba313cc8625', 'An ambitious 8,000-km ecological restoration project planting a continuous belt of trees across the entire width of the Sahel to halt the southward expansion of the Sahara Desert', true, 'bf1099f0-8b5a-4149-a01d-3f0af97d33b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9d16af61-1c0a-4f01-9cb7-06d3b350312b', 'A giant concrete wall built along borders', false, 'bf1099f0-8b5a-4149-a01d-3f0af97d33b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1b4455f-9e89-498f-8371-fdb5aed07a2d', 'A green glass greenhouse', false, 'bf1099f0-8b5a-4149-a01d-3f0af97d33b8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ef1029bb-28c3-429a-8a9c-e810885fe3ff', 'A highway through the rainforest', false, 'bf1099f0-8b5a-4149-a01d-3f0af97d33b8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b564346c-15b1-451b-8f71-9475eb39f808', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is ''Mission LiFE'' (Lifestyle for Environment) launched by India at the 2021 Glasgow Climate Summit?', 'Mission LiFE mobilizes citizens worldwide as ''Pro-Planet People'' (P3) to reduce waste, save water, conserve energy, and practice circular lifestyles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4aa8d08d-00ab-4d9f-b416-efb3b8917a9c', 'A global mass movement encouraging individuals and communities to adopt sustainable, mindful, environmentally conscious everyday consumption choices instead of mindless consumerism', true, 'b564346c-15b1-451b-8f71-9475eb39f808');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('53f2c54a-f759-4b49-ba26-520fc23b6f62', 'A medical insurance plan for doctors', false, 'b564346c-15b1-451b-8f71-9475eb39f808');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('21bd16a4-1d26-463e-8658-c8d44195bf5f', 'A space satellite mission to study life on Mars', false, 'b564346c-15b1-451b-8f71-9475eb39f808');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('01ca39eb-1fdf-4708-bcc7-a7d00f11bd31', 'A free food distribution program', false, 'b564346c-15b1-451b-8f71-9475eb39f808');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('58c687bd-2586-4211-90e1-7109b7efcf0c', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'Which is the OLDEST National Park in India, established in 1936 in Uttarakhand (originally named Hailey National Park)?', 'Jim Corbett National Park (established in 1936 as Hailey National Park) is India''s first and oldest national park.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('545a9098-eb67-4966-a0c9-54fe38dcff3f', 'Jim Corbett National Park', true, '58c687bd-2586-4211-90e1-7109b7efcf0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95bf3a4a-db2d-4047-b7e0-20349fc19094', 'Kanha National Park', false, '58c687bd-2586-4211-90e1-7109b7efcf0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a865a4fc-d421-45ea-9e87-4c0e2534e5da', 'Sundarbans National Park', false, '58c687bd-2586-4211-90e1-7109b7efcf0c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4373bc6b-f2dd-4ac3-8bf4-2a403aa61a47', 'Bandipur National Park', false, '58c687bd-2586-4211-90e1-7109b7efcf0c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('77002d9a-599b-4f7e-b9f1-2f36dd745c7c', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is ''E-Waste'' (Electronic Waste) and why is its recycling critical?', 'E-waste recycling prevents neurotoxic heavy metals from leaching into groundwater while recovering critical rare earth elements and lithium.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('418885eb-a2dd-4227-a6d9-d71d4826d2ce', 'Discarded electronic devices (smartphones, computers, batteries) containing hazardous heavy metals (lead, mercury, cadmium) as well as recoverable precious metals (gold, copper, lithium)', true, '77002d9a-599b-4f7e-b9f1-2f36dd745c7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3eb5d9c2-0756-447c-af2d-58f323fdf1b4', 'Old paper books thrown into garbage', false, '77002d9a-599b-4f7e-b9f1-2f36dd745c7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2a7fa44-c197-4a6a-b39a-19e2b5e2c87a', 'Plastic shopping bags', false, '77002d9a-599b-4f7e-b9f1-2f36dd745c7c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a4918528-998b-4416-a3eb-e25c5a1c9499', 'Food waste from restaurants', false, '77002d9a-599b-4f7e-b9f1-2f36dd745c7c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('df03e8ec-78e0-4199-a9fd-1362fae681dc', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is ''Microplastics'' pollution?', 'Microplastics (<5mm) ubiquitously pollute marine biospheres, bio-accumulating up trophic levels into fish, table salt, and human tissues.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('817db0e1-40ee-4467-867c-90571443ae1e', 'Tiny microscopic plastic fragments (less than 5 mm in size) resulting from the degradation of plastic waste, synthetic textiles, and cosmetics that contaminate oceans, marine food chains, and human bloodstream', true, 'df03e8ec-78e0-4199-a9fd-1362fae681dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36b7dd42-40be-483f-b630-166e1ebcdc4e', 'Plastic toys for dolls', false, 'df03e8ec-78e0-4199-a9fd-1362fae681dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49bfabc3-bc6b-42a6-9789-eed0d8f625bd', 'Small plastic coins used in board games', false, 'df03e8ec-78e0-4199-a9fd-1362fae681dc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f46eac9b-8f85-474d-a12c-22de9062bbc7', 'Plastic buttons on shirts', false, 'df03e8ec-78e0-4199-a9fd-1362fae681dc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d2aeec1-2b6f-4613-8f89-785f128c3cdc', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What are ''Biodiversity Hotspots''?', 'Norman Myers defined 36 global Biodiversity Hotspots: regions with ≥1,500 endemic vascular plant species having lost ≥70% primary habitat.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('72716d7e-4dd5-4c5f-9974-76e3792bdceb', 'Biogeographic regions that possess exceptionally high concentrations of endemic biological species (found nowhere else on Earth) and are undergoing severe habitat loss (e.g. Western Ghats and Eastern Himalayas)', true, '6d2aeec1-2b6f-4613-8f89-785f128c3cdc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('11a9181a-e0c5-492b-862b-4775e7ca2dac', 'Volcanoes with lava', false, '6d2aeec1-2b6f-4613-8f89-785f128c3cdc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d439f177-7cd1-4728-9900-5f9c6b9fd128', 'Desert areas with high temperature', false, '6d2aeec1-2b6f-4613-8f89-785f128c3cdc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0ad3933e-c7a7-42d7-885e-628e7647121d', 'Zoos with many animals', false, '6d2aeec1-2b6f-4613-8f89-785f128c3cdc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9976f23e-bde9-46f0-9442-57d7b1a0da77', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is the ''Albedo Effect'' in polar climate science?', 'The ice-albedo feedback is a critical climate tipping element: loss of reflective sea ice increases oceanic heat absorption.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('33f87e42-d1cf-4664-94fd-a054bd540298', 'The fraction of solar radiation reflected by a surface: white polar ice has high albedo (reflects ~80% sunlight), but melting ice exposes dark ocean water which absorbs heat, accelerating global warming in a feedback loop', true, '9976f23e-bde9-46f0-9442-57d7b1a0da77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('96d8de44-71de-47b1-9ac8-6d4341d2bc90', 'The color of polar bears'' fur', false, '9976f23e-bde9-46f0-9442-57d7b1a0da77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc4401e0-63a7-465f-b5ae-3ac2370c8488', 'The sound made by glaciers breaking', false, '9976f23e-bde9-46f0-9442-57d7b1a0da77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('09bf467b-43fb-4321-85bd-1ca3f42dd81c', 'The depth of polar ice sheets', false, '9976f23e-bde9-46f0-9442-57d7b1a0da77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d507cd37-5a2d-48d9-a48c-b98118ca2127', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Medium', 'What is ''Circular Economy''?', 'The circular economy replaces the linear ''take-make-dispose'' paradigm with closed-loop regenerative resource cycles.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3c5bc3b-47b6-4855-901a-a572eab66a80', 'An economic model aimed at eliminating waste through continuous cycles of designing for durability, reuse, repairing, refurbishing, and recycling materials indefinitely', true, 'd507cd37-5a2d-48d9-a48c-b98118ca2127');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a27b6089-50be-4aff-a316-309b57c6f92f', 'An economy that prints round coins only', false, 'd507cd37-5a2d-48d9-a48c-b98118ca2127');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e62d28dd-836f-4b8c-9d95-f0517dfd7531', 'Trading goods only in circular markets', false, 'd507cd37-5a2d-48d9-a48c-b98118ca2127');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36ea9abb-8475-49a3-8f67-6fe71a748946', 'An economy where prices go in circles', false, 'd507cd37-5a2d-48d9-a48c-b98118ca2127');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d2c7e67f-052d-44cf-8212-0af795799000', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1959ef60-2778-498f-a195-cd6e10819b36', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'd2c7e67f-052d-44cf-8212-0af795799000');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5029da40-8a84-4c2b-9b1d-83330173bc07', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'd2c7e67f-052d-44cf-8212-0af795799000');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('431e98ef-3cfe-48fc-abdd-838d3604335d', '(A) is true, but (R) is false.', false, 'd2c7e67f-052d-44cf-8212-0af795799000');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd84ecce-3b89-4d98-a2ef-c2bfa5bf69df', '(A) is false, but (R) is true.', false, 'd2c7e67f-052d-44cf-8212-0af795799000');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('76d091f6-f7c2-4728-a46b-790402f69efc', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'Spot the IMPOSTER in the following major Global Environmental Treaties and their conservation mandates:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('39e2d878-7046-4e7a-a88d-5adcb54568f7', 'Treaty 1', false, '76d091f6-f7c2-4728-a46b-790402f69efc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cdcfe919-83ad-45fd-a6d2-0e2d3bec4a8a', 'Treaty 2', false, '76d091f6-f7c2-4728-a46b-790402f69efc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a329ea9-57ef-4e55-b707-c6bbe2f05118', 'Treaty 3', false, '76d091f6-f7c2-4728-a46b-790402f69efc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1406acfc-5b38-45bd-bb73-97b9604f466f', 'Treaty 4 (The Treaty of Versailles was a 1919 post-WWI peace treaty among European nations, NOT an environmental pact to plant trees on Mars)', true, '76d091f6-f7c2-4728-a46b-790402f69efc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('741eb39b-1ed6-4b02-99be-6d3c11e415aa', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'Analyze the ecological concept of ''Carrying Capacity'' of an ecosystem:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b432a9e1-7144-46ad-b379-504a7912a154', 'Resource depletion (food, water, territory) occurs, leading to environmental degradation, reproductive decline, disease outbreaks, and a sharp population crash (overshoot and collapse)', true, '741eb39b-1ed6-4b02-99be-6d3c11e415aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2ffd605d-59f7-4786-a09e-9e31e28d0d77', 'The ecosystem instantly doubles in size', false, '741eb39b-1ed6-4b02-99be-6d3c11e415aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e16edad-c742-4579-9ecf-22de5037ee93', 'Animals evolve into different species within a day', false, '741eb39b-1ed6-4b02-99be-6d3c11e415aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c9c1d216-a64a-42b8-a916-a2fb5caaddd7', 'Nothing happens because nature has infinite resources', false, '741eb39b-1ed6-4b02-99be-6d3c11e415aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4c1d23cb-b33a-4673-8b7c-f84feb48e2bb', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'Match Column I (UN Sustainable Development Goals - SDGs) with Column II (Target Agendas):
(a) SDG 4  -> (i) Quality Education for all
(b) SDG 6  -> (ii) Clean Water and Sanitation
(c) SDG 7  -> (iii) Affordable and Clean Energy
(d) SDG 13 -> (iv) Climate Action', 'SDG 4 = Quality Education; SDG 6 = Clean Water; SDG 7 = Clean Energy; SDG 13 = Climate Action.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c71375a3-1679-44c0-9c44-49d7cfbfe1a5', 'a-(i), b-(ii), c-(iii), d-(iv)', true, '4c1d23cb-b33a-4673-8b7c-f84feb48e2bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('26638065-72ca-4bb0-b0a0-916fabda89d2', 'a-(ii), b-(i), c-(iv), d-(iii)', false, '4c1d23cb-b33a-4673-8b7c-f84feb48e2bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0539e23b-f690-4c32-a24e-86878e69eb5d', 'a-(iv), b-(iii), c-(ii), d-(i)', false, '4c1d23cb-b33a-4673-8b7c-f84feb48e2bb');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8d4fefcb-e010-4566-8416-a3a11c007070', 'a-(iii), b-(iv), c-(i), d-(ii)', false, '4c1d23cb-b33a-4673-8b7c-f84feb48e2bb');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9e643588-b613-4714-876f-4d09e209beb0', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'Read the statements regarding renewable energy transition in India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('436595ab-a171-430c-b060-db6bb3dce26a', 'Statements 1 and 2 only', true, '9e643588-b613-4714-876f-4d09e209beb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c16a6b51-be49-4bdb-8cd6-6804c4015453', 'Statements 2 and 3 only', false, '9e643588-b613-4714-876f-4d09e209beb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('95e5b922-05c5-49bc-89e6-9e59a19e02a2', 'Statements 1 and 3 only', false, '9e643588-b613-4714-876f-4d09e209beb0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f67b70a-1fce-429f-8448-d24288c433b8', 'All Statements 1, 2, and 3', false, '9e643588-b613-4714-876f-4d09e209beb0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6e94e788-48b8-4daf-8864-550b205e446e', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'What is the biogeochemical danger of ''Permafrost Thawing'' in the Arctic tundra regions?', 'Permafrost holds ~1,500 gigatons of frozen carbon—twice the carbon currently in the atmosphere; thawing creates a catastrophic carbon-feedback loop.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('45753db7-6550-4277-8c7b-d2e45d185a69', 'Thawing permafrost awakens ancient microbes that decompose trapped organic matter, releasing hundreds of billions of tons of potent METHANE (CH₄) and CO₂ into the atmosphere, triggering runaway warming', true, '6e94e788-48b8-4daf-8864-550b205e446e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4b1372c0-8545-45f1-8d40-5cf7e5fdc152', 'It causes all rivers to turn into saltwater', false, '6e94e788-48b8-4daf-8864-550b205e446e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8054c830-88e8-472e-887a-0c46c12dbe96', 'It stops the Earth''s magnetic field', false, '6e94e788-48b8-4daf-8864-550b205e446e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('663d8f11-f3fd-4034-b511-1703109bfcf4', 'It turns rocks into gold', false, '6e94e788-48b8-4daf-8864-550b205e446e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19bb876e-7dc2-4ade-8a79-eec211b2c9aa', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'What is ''Payment for Ecosystem Services'' (PES) in environmental economics?', 'PES programs (e.g. Costa Rica''s PSA) internalize ecological externalities by rewarding indigenous and rural communities for preserving living ecosystems.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4dcc4c05-c826-4dba-91e2-d0da2a0408f8', 'Incentives and financial compensations paid to local farmers, forest dwellers, and landowners who manage their land sustainably to provide vital ecological services (clean water filtration, carbon sequestration, flood prevention)', true, '19bb876e-7dc2-4ade-8a79-eec211b2c9aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6f03d4c-f725-48be-8f06-32bdf97668ee', 'Taxes paid to enter city parks', false, '19bb876e-7dc2-4ade-8a79-eec211b2c9aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bf37018-1b71-419d-8853-d9c7064e2d4e', 'Salaries paid to zoo guards', false, '19bb876e-7dc2-4ade-8a79-eec211b2c9aa');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5d004615-2d7a-4221-8b97-224669b5687d', 'Prices charged for buying bottled water', false, '19bb876e-7dc2-4ade-8a79-eec211b2c9aa');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6d3a4d61-4d8c-4fd7-9d45-015805ac7abd', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'Consider four environmental conservation initiatives in India:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2aeca236-01af-4f13-a82b-116c4c83ad57', 'Grassroots non-violent Gandhian eco-activism led by indigenous communities and women fighting to safeguard forest ecosystems and ecological livelihoods', true, '6d3a4d61-4d8c-4fd7-9d45-015805ac7abd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ae438048-4f27-44fe-b1a3-d2d5e641136c', 'They were corporate advertising campaigns for wood companies', false, '6d3a4d61-4d8c-4fd7-9d45-015805ac7abd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7da35ff-7c6e-4a41-b77d-0511e25a4c2c', 'They were government projects to cut down forests', false, '6d3a4d61-4d8c-4fd7-9d45-015805ac7abd');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('93f1f5f4-7836-43ea-89b3-64ba8b2db9a9', 'They were sports clubs', false, '6d3a4d61-4d8c-4fd7-9d45-015805ac7abd');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f5e026b7-027d-4bcd-a425-93a7e23c2b54', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'What is the ''Loss and Damage Fund'' established at COP27 (Sharm el-Sheikh) and operationalized at COP28 (Dubai)?', 'The Loss and Damage Fund operationalizes climate justice: compensating climate-vulnerable global South nations for irreversible climate shocks.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('df87dab2-6823-43b7-9864-3175821b0853', 'A dedicated international climate finance facility where historical polluting developed nations provide financial assistance to vulnerable developing countries suffering irreversible climate disasters (floods, droughts, sea-level rise)', true, 'f5e026b7-027d-4bcd-a425-93a7e23c2b54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b0894ef5-f333-430b-97d5-1f743ac06fc2', 'A fund to pay insurance for broken cars', false, 'f5e026b7-027d-4bcd-a425-93a7e23c2b54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36b3d1c6-a58f-4538-9b2f-e400bdd08b48', 'A tax on tourist travel', false, 'f5e026b7-027d-4bcd-a425-93a7e23c2b54');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d98c472a-652c-402e-9509-e9f11e29224d', 'A bank loan for oil companies', false, 'f5e026b7-027d-4bcd-a425-93a7e23c2b54');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34452147-7070-43a3-9e45-c991a779827d', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'Why are ''Mangrove Ecosystems'' (like the Sundarbans) hailed as super-heroes of coastal climate resilience?', 'Mangroves are premier Blue Carbon sinks and bio-shields against coastal erosion, storm surges, and tsunami devastation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a2ee579-c6cd-4c86-b845-0f00138a24d4', 'They store up to 5 times more carbon per hectare than tropical rainforests (Blue Carbon), buffer coastal communities against ferocious cyclone surges and tsunamis, and serve as vital nursery grounds for marine biodiversity', true, '34452147-7070-43a3-9e45-c991a779827d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8815fc5-dec3-43cc-ae1d-8ccf09570b82', 'Because they produce pure gold crystals in their roots', false, '34452147-7070-43a3-9e45-c991a779827d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('10715620-4a61-4fa8-bb05-5e6417c0b7c0', 'Because they can walk across oceans', false, '34452147-7070-43a3-9e45-c991a779827d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e33763c3-7659-4c8d-aa1c-bf78400f6916', 'Because they prevent rain from falling', false, '34452147-7070-43a3-9e45-c991a779827d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9637171e-b5c1-4390-88c3-bc7dc497b786', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'What is ''Ecological Footprint'' articulated by Mathis Wackernagel and William Rees?', 'Ecological footprint measures human demand on natural capital versus planetary biocapacity (calculated annually on Earth Overshoot Day).', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d549da6-4e50-4ef8-9e9e-7b5fb91089ed', 'A metric that compares human consumption of natural resources against the Earth''s biocapacity to regenerate those resources and absorb our waste; currently, humanity consumes resources at the rate of 1.7 Earths', true, '9637171e-b5c1-4390-88c3-bc7dc497b786');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cf426dba-021c-4de6-b469-346fad3b55f5', 'The weight of human feet on soil', false, '9637171e-b5c1-4390-88c3-bc7dc497b786');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd1fdba9-639e-4551-82cf-89917ce1767b', 'The number of trees planted in a garden', false, '9637171e-b5c1-4390-88c3-bc7dc497b786');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d8cb4d80-7726-4d72-8af0-df6fcb31d007', 'The distance animals travel every year', false, '9637171e-b5c1-4390-88c3-bc7dc497b786');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b85f6a68-951e-4f7f-a004-ec1db757b292', 'Class 7', 'GK', 'Chapter 12: Environmental Conservation, Climate Change, Renewable Energy & Sustainable Development', 'Hard', 'What supreme planetary ethical manifesto concludes the General Knowledge curriculum in Chapter 12?', 'Chapter 12 culminates in the universal ethic of ecological stewardship: harmonizing human civilization with planetary boundaries for intergenerational sustainability.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f72ca1d5-afc3-4726-b865-92ddadfb0546', 'We do not inherit the Earth from our ancestors; we borrow it from our children. Sustainable development demands that human economic ambition harmonize with the finite ecological boundaries of our living planet, fostering intergenerational justice and reverence for all life', true, 'b85f6a68-951e-4f7f-a004-ec1db757b292');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14c5abe2-a0d1-4528-9ad9-2ec241451709', 'That human beings should exploit every natural resource until nothing is left', false, 'b85f6a68-951e-4f7f-a004-ec1db757b292');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4d4e1bf3-f0fc-4380-9db5-8ecabb44a461', 'That technology eliminates the need for nature', false, 'b85f6a68-951e-4f7f-a004-ec1db757b292');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3cb34281-6d84-4e91-a3b9-19ba374419c0', 'That environmental problems will solve themselves automatically', false, 'b85f6a68-951e-4f7f-a004-ec1db757b292');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('78b03ddb-371f-4f85-90dd-0c8d9d7a14cc', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'What is the seasonal migration of pastoral nomadic people with their livestock between highland summer pastures and lowland winter valleys called?', 'Transhumance is the seasonal movement of pastoralists with their herds in response to seasonal changes in mountain pastures and weather.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1892de0-8893-4f9f-8077-3552523d02a5', 'Transhumance (e.g. Gujjars and Bakarwals)', true, '78b03ddb-371f-4f85-90dd-0c8d9d7a14cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22a892a1-08a9-4564-b324-33e9ea222b78', 'Urbanization', false, '78b03ddb-371f-4f85-90dd-0c8d9d7a14cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('98041f09-cf50-44bb-80b7-923616d7c019', 'Immigration', false, '78b03ddb-371f-4f85-90dd-0c8d9d7a14cc');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b6c33660-c283-4ead-937a-b7d11423c600', 'Deforestation', false, '78b03ddb-371f-4f85-90dd-0c8d9d7a14cc');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9300b168-fd63-47e1-a727-fde574294966', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'Which highway project in India connects the four major metropolitan mega-cities—Delhi, Mumbai, Chennai, and Kolkata—with 4/6-lane expressways?', 'The Golden Quadrilateral (5,846 km) connects Delhi, Mumbai, Chennai, and Kolkata, forming the backbone of India''s arterial expressway network.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('deeb18d1-5279-4c00-ad1e-73becc33a158', 'The Golden Quadrilateral Super Highway', true, '9300b168-fd63-47e1-a727-fde574294966');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e08f2041-07eb-4926-937c-9d8cfed5ce14', 'The Grand Trunk Road', false, '9300b168-fd63-47e1-a727-fde574294966');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a46aebd3-9439-48fd-b165-1b2b9f0a6303', 'The National Highway 44', false, '9300b168-fd63-47e1-a727-fde574294966');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba7f9e28-38b2-4c7f-819e-d0bbc67b7bb5', 'The Border Roads Project', false, '9300b168-fd63-47e1-a727-fde574294966');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8fd5d874-bbd5-48f8-ab26-c7cd13e90b90', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'What is the LONGEST railway line in the world, running 9,289 km from St. Petersburg in western Russia to Vladivostok on the Pacific Coast?', 'The Trans-Siberian Railway spans across two continents and 8 time zones, connecting European Russia with the Pacific Ocean.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d9e2708a-b896-4a6b-9d06-baec2c556c45', 'The Trans-Siberian Railway', true, '8fd5d874-bbd5-48f8-ab26-c7cd13e90b90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8abc26d3-16c0-469a-b13f-85137a302727', 'The Orient Express', false, '8fd5d874-bbd5-48f8-ab26-c7cd13e90b90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a6be517a-61a3-4f09-90a6-b0a1d1161a5f', 'The Trans-Australian Railway', false, '8fd5d874-bbd5-48f8-ab26-c7cd13e90b90');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5fbf3014-1aa7-4c17-9c9c-6c9ba88a3ca1', 'The Canadian Pacific Railway', false, '8fd5d874-bbd5-48f8-ab26-c7cd13e90b90');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3613cb39-ecf6-4cae-8f98-4e2d5a50ef72', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'Which is the FASTEST, most modern, but most expensive means of transport developed in the early 20th century?', 'Airways provide the fastest means of long-distance transport, especially critical for reaching remote and inaccessible disaster zones.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('781bacd7-d360-4c61-b558-483644336f33', 'Airways (Air transport)', true, '3613cb39-ecf6-4cae-8f98-4e2d5a50ef72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c54fbf54-be31-412c-8e00-67b3f9bc5829', 'Railways', false, '3613cb39-ecf6-4cae-8f98-4e2d5a50ef72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb2f47bc-40b8-4907-9cf5-87da2bd5351c', 'Waterways', false, '3613cb39-ecf6-4cae-8f98-4e2d5a50ef72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e41f429d-25ba-4c67-889f-ac5909c70a2a', 'Roadways', false, '3613cb39-ecf6-4cae-8f98-4e2d5a50ef72');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('176f6e3c-6f43-4964-8a08-3beea22dea22', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'What is the world''s LARGEST HOT DESERT, covering an immense area of 8.54 million square kilometres across 11 countries in North Africa?', 'The Sahara Desert in North Africa is the largest tropical hot desert in the world, larger in area than the entire nation of Australia.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('59bb0ac1-d4ac-440b-9b1d-d5b4997f9888', 'The Sahara Desert', true, '176f6e3c-6f43-4964-8a08-3beea22dea22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6e4f05dd-c497-449c-a600-888e399c3483', 'The Thar Desert', false, '176f6e3c-6f43-4964-8a08-3beea22dea22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51020049-0269-4e1a-a4b0-b681190c05da', 'The Gobi Desert', false, '176f6e3c-6f43-4964-8a08-3beea22dea22');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea98a987-aa75-44a7-8d6b-7a9db581962d', 'The Kalahari Desert', false, '176f6e3c-6f43-4964-8a08-3beea22dea22');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8331d3e4-e9df-46ec-90ca-4b29b0a6c9b2', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'Which two famous nomadic pastoral tribes inhabit the Sahara Desert, rearing camels, goats, sheep, and horses for milk, hides, and hair?', 'The Bedouins and Tuaregs are traditional nomadic pastoralists of the Sahara, wearing heavy robes to protect against sandstorms and blazing heat.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abd2245d-ed00-4c36-aa5f-de43b0e24156', 'The Bedouins and the Tuaregs', true, '8331d3e4-e9df-46ec-90ca-4b29b0a6c9b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6a25697e-a8cc-489f-beaf-2f1c8f53b377', 'The San and Bushmen', false, '8331d3e4-e9df-46ec-90ca-4b29b0a6c9b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('028e6df1-32ce-40c6-b097-bea49867dcd8', 'The Inuits and Eskimos', false, '8331d3e4-e9df-46ec-90ca-4b29b0a6c9b2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('715eaa24-0141-460b-be13-a7d1a43a2abd', 'The Maoris and Aborigines', false, '8331d3e4-e9df-46ec-90ca-4b29b0a6c9b2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bf1bb21a-07e6-4b21-83f9-b09758e92296', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'What valuable mineral resource discovered in Algeria, Libya, and Egypt has dramatically transformed the economy and urban landscape of the Sahara?', 'The discovery of massive petroleum reserves in Algeria, Libya, and Egypt transformed traditional desert nomadism into modern industrial urbanism.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('35b6d645-4803-42bb-b3b0-2f97ef1a1295', 'Petroleum (Mineral Oil and Natural Gas)', true, 'bf1bb21a-07e6-4b21-83f9-b09758e92296');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d839adb-29a4-4bc0-bc62-bd22cfb4f3a5', 'Gold and Diamond only', false, 'bf1bb21a-07e6-4b21-83f9-b09758e92296');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('389cddcc-ae09-4b27-add5-334708a919ce', 'Coal only', false, 'bf1bb21a-07e6-4b21-83f9-b09758e92296');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f54591e1-8707-4360-83a7-d72938d41a32', 'Uranium only', false, 'bf1bb21a-07e6-4b21-83f9-b09758e92296');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('cb069202-28a7-4e6c-9a39-c5727b756b97', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'What is the famous COLD DESERT lying in the Great Himalayas on the eastern side of Jammu and Kashmir / Ladakh in northern India?', 'Ladakh is a high-altitude cold desert enclosed by the Karakoram Range in the north and the Zanskar Mountains in the south.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fdb9c7fa-467f-4d7f-8d5a-d29fb87eb452', 'Ladakh (also known as ''Khapa-chan'' or Snow Land)', true, 'cb069202-28a7-4e6c-9a39-c5727b756b97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5becb208-3a07-489c-aad8-2b2c825286b6', 'The Thar Desert', false, 'cb069202-28a7-4e6c-9a39-c5727b756b97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cedf7cc3-a093-4505-9c44-a35aa9ea5bd1', 'The Spiti Valley only', false, 'cb069202-28a7-4e6c-9a39-c5727b756b97');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4e748190-3e8c-48bd-bac9-64a189be5279', 'The Rann of Kutch', false, 'cb069202-28a7-4e6c-9a39-c5727b756b97');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a93ccf9d-ab1d-4566-9c43-7fc280ad0192', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'Which major river and its tributaries flow through the rugged mountain landscape of Ladakh?', 'The Indus River and its glacial tributaries carve deep valleys and gorges across the Ladakh plateau.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('033a9913-4922-4587-90e7-af8ecb8ff837', 'The Indus River (Sindhu)', true, 'a93ccf9d-ab1d-4566-9c43-7fc280ad0192');
