INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('de9cd8fc-c2a7-4816-8930-50ba3088a1c0', 'The Brahmaputra', false, 'a93ccf9d-ab1d-4566-9c43-7fc280ad0192');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b33fe18d-f0ab-4403-8953-f47fae999eb2', 'The Yamuna', false, 'a93ccf9d-ab1d-4566-9c43-7fc280ad0192');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('79714b9d-5d30-47a0-80c0-9680f6e03c83', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'Which endangered animal found in Ladakh, the ''Chiru'' (Tibetan Antelope), is hunted for its fine, light, and exceptionally warm wool called:', 'The Chiru or Tibetan antelope yields ''Shahtoosh''—the world''s finest, lightest, and warmest wool, now strictly protected by wildlife laws.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('cbc4b051-0562-48ec-94df-87449ef192bf', 'Shahtoosh Wool', true, '79714b9d-5d30-47a0-80c0-9680f6e03c83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75c8f12e-f8ab-4c1c-bf77-d49de4131615', 'Pashmina Wool', false, '79714b9d-5d30-47a0-80c0-9680f6e03c83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a96f1b9-ab59-4f2a-86f0-fa80d4b7922a', 'Mohair', false, '79714b9d-5d30-47a0-80c0-9680f6e03c83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8a3fa983-21f4-4ba6-982c-33d24ef54e8b', 'Angora', false, '79714b9d-5d30-47a0-80c0-9680f6e03c83');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('b60cce3f-9da4-4031-970e-b655cedf7090', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'Which domestic animal of Ladakh provides rich milk for making local butter and cheese (''Chhurpi''), meat, and thick hair for weaving tents and boots?', 'The shaggy-haired Yak is the indispensable beast of burden in high-altitude Ladakh, supplying milk for butter/cheese, wool, and draught power.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8e5b91da-27cd-403f-9347-059a59e05e70', 'The Yak (and Dzo)', true, 'b60cce3f-9da4-4031-970e-b655cedf7090');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2d7bcdbf-8108-4581-9920-ac8cc3c69f48', 'The Camel', false, 'b60cce3f-9da4-4031-970e-b655cedf7090');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5b9ee2bb-3446-421d-aef1-abfc47009469', 'The Elephant', false, 'b60cce3f-9da4-4031-970e-b655cedf7090');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('817c6f13-6804-478d-a9bc-149da86c73a1', 'The Horse', false, 'b60cce3f-9da4-4031-970e-b655cedf7090');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('09bdba78-1e3c-42d3-9925-e4b9d7ef0670', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Easy', 'What are the traditional Buddhist monasteries with their unique prayer halls and colorful stupas found across Ladakh called?', 'Gompas (like Hemis, Thiksey, Shey, and Lamayuru) are iconic fortified Buddhist monasteries that form the spiritual and cultural heart of Ladakh.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5db59e61-c87c-4d35-82b9-26640295a97a', 'Gompas (e.g. Hemis, Thiksey, Shey, Lamayuru)', true, '09bdba78-1e3c-42d3-9925-e4b9d7ef0670');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('797d90c0-01c4-4634-9840-d35afa931180', 'Viharas only', false, '09bdba78-1e3c-42d3-9925-e4b9d7ef0670');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14445463-9770-4d78-a23a-fd7aefecb9ec', 'Gurudwaras', false, '09bdba78-1e3c-42d3-9925-e4b9d7ef0670');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('29df43f9-7203-4372-a834-d80c0bc5595b', 'Mosques', false, '09bdba78-1e3c-42d3-9925-e4b9d7ef0670');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('bcaac6d6-e4a1-4d19-b0a6-e9798ac398f3', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'Why does Ladakh experience such EXTREME ARIDITY (Dryness) and receive as little as 10 cm of rainfall annually?', 'The colossal Himalayan barrier intercepts monsoon clouds, casting the trans-Himalayan Ladakh plateau into an arid rain-shadow zone.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('70a2f88f-80c9-47e2-9329-5062f909a842', 'Ladakh lies in the ''RAIN-SHADOW'' of the towering Great Himalayas, which block the moisture-laden southwest monsoon winds from entering the region', true, 'bcaac6d6-e4a1-4d19-b0a6-e9798ac398f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b745999c-fb6e-48de-a7fe-e2a38579f953', 'Because clouds are too heavy to fly over mountains', false, 'bcaac6d6-e4a1-4d19-b0a6-e9798ac398f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5af087e-8cc2-47d8-bb3d-f8521111df67', 'Because there is no sun in Ladakh', false, 'bcaac6d6-e4a1-4d19-b0a6-e9798ac398f3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('02046aa5-32d3-4db7-b1c3-3cc279526166', 'Because winds blow backwards', false, 'bcaac6d6-e4a1-4d19-b0a6-e9798ac398f3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('46e29c9b-2228-4e6a-a2d4-b4ea311bc7e5', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What is an ''OASIS'' in the desert landscape, such as the famous Tafilalet Oasis in Morocco?', 'Deflation hollows reaching groundwater create oases: lush green centers of date-palm agriculture and trading caravan towns.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7e11fc98-8505-444d-8e12-6d448f249ca5', 'A fertile, lush depression in a desert where underground aquifer water reaches the surface, supporting date palms, crops, and human settlements', true, '46e29c9b-2228-4e6a-a2d4-b4ea311bc7e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0a3f3197-fdfe-4905-b78a-fa4d92b7707c', 'A mirage that disappears when approached', false, '46e29c9b-2228-4e6a-a2d4-b4ea311bc7e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('688e678f-80d5-4643-9dc7-7e0cc7972b7e', 'A mountain of gold in the sand', false, '46e29c9b-2228-4e6a-a2d4-b4ea311bc7e5');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dcc7150e-0558-4d50-ad59-b4702cfad4d5', 'A dry salt flat with no water', false, '46e29c9b-2228-4e6a-a2d4-b4ea311bc7e5');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3929e2f9-a349-45cc-a540-3889b0baa7e3', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What is the difference between a ''COMPACT SETTLEMENT'' and a ''SCATTERED SETTLEMENT''?', 'Compact settlements thrive in nucleated agricultural plains, whereas scattered homesteads characterize rugged mountain and desert terrains.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('671dc58e-4257-4bbc-8477-ce68ddd702a9', 'A compact settlement consists of closely built dwellings on flat fertile plains ; a scattered settlement has houses spaced far apart over vast hilly, forested, or desert tracts', true, '3929e2f9-a349-45cc-a540-3889b0baa7e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f24b42ca-1ba2-49cc-8b96-4c729b994e86', 'Compact settlements have no roads', false, '3929e2f9-a349-45cc-a540-3889b0baa7e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5ea962b9-0597-4d1f-a4f7-ad54c3a9b712', 'Scattered settlements are built on boats', false, '3929e2f9-a349-45cc-a540-3889b0baa7e3');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b96f6b00-4139-444c-94d0-ec337f68f4a2', 'There is no difference', false, '3929e2f9-a349-45cc-a540-3889b0baa7e3');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4855e3ce-2204-4c91-b05a-811c098688d2', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'Why are WATERWAYS the cheapest and most energy-efficient mode of transport for carrying heavy and bulky goods across long distances?', 'Hydrodynamic buoyancy and low fluid friction make maritime and inland freight shipping the most cost-effective bulk transport mode.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f73879d0-dcd9-4357-9c5a-4ddfb504d497', 'Water provides immense natural buoyancy with minimal surface friction, requiring significantly less fuel energy per ton-kilometer than road or air transport', true, '4855e3ce-2204-4c91-b05a-811c098688d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0b238dcd-c8e3-4dda-8cd5-053b288d70f2', 'Because ships do not require any fuel', false, '4855e3ce-2204-4c91-b05a-811c098688d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('91883fa5-b784-43ed-a7c7-6103135a97fc', 'Because water flows in all directions automatically', false, '4855e3ce-2204-4c91-b05a-811c098688d2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bea52bb5-c30c-4a0f-8eef-3ac3ce34a7ef', 'Because water transport is faster than airplanes', false, '4855e3ce-2204-4c91-b05a-811c098688d2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('837bf29f-95bc-44f9-90bd-53d540a47970', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'Which artificial waterway opened in 1869 in Egypt, connecting the Mediterranean Sea to the Red Sea, revolutionizing international maritime shipping between Europe and Asia?', 'The Suez Canal slashed maritime transit distance between Europe and India/Asia by over 7,000 km, bypassing the Cape of Good Hope.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6c8bd649-8246-41ea-9e6b-ba93f012a73b', 'The Suez Canal', true, '837bf29f-95bc-44f9-90bd-53d540a47970');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ceedea31-b6b4-4b0f-aaba-1158bba7ab6b', 'The Panama Canal', false, '837bf29f-95bc-44f9-90bd-53d540a47970');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f70d0faa-9bf6-4769-bbe7-54f7abd60e19', 'The Kiel Canal', false, '837bf29f-95bc-44f9-90bd-53d540a47970');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e95435e6-f605-498a-b633-e0abadac0f39', 'The Erie Canal', false, '837bf29f-95bc-44f9-90bd-53d540a47970');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f82bcd31-8d97-4b09-8ea7-4eefa5255812', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'Which engineering marvel canal opened in 1914, cutting across the Isthmus of Panama to connect the Atlantic Ocean directly to the Pacific Ocean?', 'The Panama Canal with its lock system eliminated the hazardous 15,000 km voyage around South America''s Cape Horn.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16e6f8ff-c8e5-481e-b744-6601af2bd91e', 'The Panama Canal', true, 'f82bcd31-8d97-4b09-8ea7-4eefa5255812');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6fb787d-33a2-4a6d-8945-a08cdf4510f9', 'The Suez Canal', false, 'f82bcd31-8d97-4b09-8ea7-4eefa5255812');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2678ffe1-ea4f-4151-87ce-d735b947dbdd', 'The Corinth Canal', false, 'f82bcd31-8d97-4b09-8ea7-4eefa5255812');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1442bd8e-e20b-464f-8031-42d755a3f99a', 'The Grand Canal', false, 'f82bcd31-8d97-4b09-8ea7-4eefa5255812');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a8d65ccf-a97e-4ce8-a86b-bad382f75e83', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What is National Waterway 1 (NW-1) in India?', 'NW-1 is India''s premier inland waterway along the Ganga, connecting Prayagraj, Varanasi, Patna, and Haldia port.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14e8c2eb-6275-432b-896b-e65bc04e5e64', 'The Ganga-Bhagirathi-Hooghly river system stretching 1,620 km from Prayagraj (Allahabad) to Haldia', true, 'a8d65ccf-a97e-4ce8-a86b-bad382f75e83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea4d95d5-1441-4b2b-a57d-282c01e795b8', 'The Brahmaputra river from Sadiya to Dhubri', false, 'a8d65ccf-a97e-4ce8-a86b-bad382f75e83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9620362-bc42-4d87-b550-7cc3ed797edf', 'The Godavari river canal', false, 'a8d65ccf-a97e-4ce8-a86b-bad382f75e83');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('13327d00-ff3a-4bfe-97d7-633bc2f86564', 'The Kerala backwaters', false, 'a8d65ccf-a97e-4ce8-a86b-bad382f75e83');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e9a1699e-5707-4b05-a95b-e09302458f8d', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What agricultural crops are cultivated during the brief, pleasant summer season in the irrigated oasis valleys of Ladakh?', 'During the sunny summer, glacial meltwater channels irrigate terraced fields for barley, peas, potatoes, apricots, and walnuts.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('884fc108-0bb3-4d9f-9847-99105d9ad410', 'Barley, Peas, Wheat, Potatoes, Turnips, Apricots, and Walnuts', true, 'e9a1699e-5707-4b05-a95b-e09302458f8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e92e7290-88c5-4c47-b7fe-179140819a7b', 'Rice, Sugarcane, and Jute', false, 'e9a1699e-5707-4b05-a95b-e09302458f8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f998d45b-a485-4477-af43-4b49f8e2941e', 'Tea, Coffee, and Rubber', false, 'e9a1699e-5707-4b05-a95b-e09302458f8d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b91a1619-011f-428b-8b7a-08867fcc8164', 'Cotton and Tobacco', false, 'e9a1699e-5707-4b05-a95b-e09302458f8d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('34b4a4d4-2044-452f-95d1-f1b1b9f9261c', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What is ''Pashmina Wool'' for which Ladakh and Kashmir are world-renowned?', 'High-altitude Changthangi mountain goats grow an ultra-fine underfleece to endure -40°C winters, spun into exquisite Pashmina shawls.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8b15b13a-1ff8-497d-a7b5-bcad16b9eda1', 'An exceptionally fine, soft, and warm undercoat wool combed from mountain goats (Capra hircus) raised at altitudes above 4,000 metres', true, '34b4a4d4-2044-452f-95d1-f1b1b9f9261c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('be15550d-1f3a-4417-a914-3138cbf1c3f0', 'Wool obtained from camels', false, '34b4a4d4-2044-452f-95d1-f1b1b9f9261c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6afbca8-a68f-461c-b776-a459fa045539', 'Synthetic nylon fiber', false, '34b4a4d4-2044-452f-95d1-f1b1b9f9261c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d1d2fd03-ea53-4dae-b857-d45d014f50e7', 'Wool sheared from desert sheep', false, '34b4a4d4-2044-452f-95d1-f1b1b9f9261c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3cd8960e-2e6d-4d5f-84a1-bc1892e3537d', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'How has the development of the MANALI-LEH HIGHWAY transformed accessibility to Ladakh?', 'The Manali-Leh strategic highway traverses four formidable Himalayan passes, linking the Kullu valley directly to Leh.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('77448563-5204-42d9-99cc-75515be0259a', 'It crosses four high mountain passes (Rohtang La, Baralacha La, Lungalacha La, Tanglang La) at elevations above 4,000 metres, opening Ladakh to trade, military logistics, and global tourism during summer', true, '3cd8960e-2e6d-4d5f-84a1-bc1892e3537d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6d3738e3-dbb7-403b-af01-ccb185cd10bc', 'It is an underground metro railway tunnel', false, '3cd8960e-2e6d-4d5f-84a1-bc1892e3537d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('51f6a8e6-1bbd-497d-98ef-1e69db8d2b4b', 'It is a canal for large ships', false, '3cd8960e-2e6d-4d5f-84a1-bc1892e3537d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('86ebaf4a-8da4-40d7-a6e5-99c0f157c0fc', 'It is a road built on ice that melts in winter', false, '3cd8960e-2e6d-4d5f-84a1-bc1892e3537d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9231c56e-fa8b-4903-b1b0-7fee3af6f878', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What is the capital and largest administrative and commercial town of the Union Territory of Ladakh?', 'Leh is the historic capital of Ladakh, situated at 3,500 m altitude, featuring the 17th-century nine-storey Leh Palace.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f916ac52-89dc-41e8-a664-fbef519619ee', 'Leh (connected by road and Kushok Bakula Rimpochee Airport)', true, '9231c56e-fa8b-4903-b1b0-7fee3af6f878');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('791f785a-3667-4f2d-8ad5-982e479de0f1', 'Kargil', false, '9231c56e-fa8b-4903-b1b0-7fee3af6f878');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6b881561-f511-414e-a767-7c0fe1870e77', 'Diskit', false, '9231c56e-fa8b-4903-b1b0-7fee3af6f878');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('89cc4f61-c9ff-4eb4-999d-3e4d4fd18037', 'Padum', false, '9231c56e-fa8b-4903-b1b0-7fee3af6f878');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('914c352b-f122-426e-b8e8-81a93ada0809', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'Why do the people of the Sahara Desert wear loose, flowing, heavy robes and head coverings?', 'Loose, layered woolen and cotton robes create an insulative microclimate, shielding desert dwellers from extreme thermal radiation and sandstorms.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4229f29d-3597-4ebc-a8ae-e32c3f91ef21', 'To protect their skin and eyes from fierce scorching desert heat, drying ultraviolet sun rays, and blinding dust/sand storms', true, '914c352b-f122-426e-b8e8-81a93ada0809');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('239269aa-e0b5-4048-815a-5751a057cf77', 'Because they do not have modern clothes', false, '914c352b-f122-426e-b8e8-81a93ada0809');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1d9173eb-571e-42f7-8d53-ccb60276f261', 'Because the government ordered them to wear robes', false, '914c352b-f122-426e-b8e8-81a93ada0809');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2fe94a58-c809-4350-b9fa-5bc7553569f9', 'To look taller on camels', false, '914c352b-f122-426e-b8e8-81a93ada0809');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('31a407ba-bce9-424f-945f-8a030e94e03a', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What remarkable adaptation of human ecology is practiced by the people of Ladakh in managing their scarce resources?', 'Ladakhi ecological culture is a global paradigm of sustainable frugality: zero-waste recycling and sacred stewardship of scarce water and biomass.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('792c6cf7-5e47-495d-b926-31259dce9a5d', 'Extreme reverence for nature and meticulous conservation: not a single drop of water or scrap of fuel/wood is wasted, recycling all organic matter in harmony with the fragile environment', true, '31a407ba-bce9-424f-945f-8a030e94e03a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a0d6a73a-b7d7-4541-8d9a-f0d94c17c079', 'Cutting down all trees for firewood', false, '31a407ba-bce9-424f-945f-8a030e94e03a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c1281fee-4d5e-461a-8d98-c7152ce2f06d', 'Diverting rivers into other countries', false, '31a407ba-bce9-424f-945f-8a030e94e03a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6cf0f91d-b083-494e-adbd-93bdf451d4d0', 'Living without any shelter in winter', false, '31a407ba-bce9-424f-945f-8a030e94e03a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('89e9b2ea-9450-47b5-bcd0-c9c5423f8d5c', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What role do modern communication SATELLITES play in human connectivity and resource management?', 'Geostationary and low-Earth orbit satellites power global ICT connectivity, remote sensing earth observation, and real-time meteorology.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55e6f136-94f3-4cba-93e4-99f09787df79', 'They enable instant global cellular telecommunications, internet routing, television broadcasting, weather forecasting, disaster warnings, and mineral/groundwater mapping', true, '89e9b2ea-9450-47b5-bcd0-c9c5423f8d5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('483599f5-c6a0-4a05-8916-751afe1b0a93', 'They take tourists to outer space for holidays', false, '89e9b2ea-9450-47b5-bcd0-c9c5423f8d5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('328f5ade-ecef-449a-b762-898ce8f2dd24', 'They shine bright lights to replace street lamps', false, '89e9b2ea-9450-47b5-bcd0-c9c5423f8d5c');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2a74060d-bbc9-4972-b4b3-85c29fdef198', 'They make rain fall on deserts', false, '89e9b2ea-9450-47b5-bcd0-c9c5423f8d5c');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ec172a2-7ce5-4314-825c-72e17a52bd16', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'What is ''Mass Media'' in modern human society?', 'Mass media encompasses print and digital broadcast communications transmitting news, culture, and democratic discourse to millions.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('16da09c4-cead-4c35-a72b-702e00889f00', 'Means of communication that reach millions of people simultaneously across the nation and globe, such as Newspapers, Radio, Television, and the Internet', true, '7ec172a2-7ce5-4314-825c-72e17a52bd16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('37aaa86e-0e67-4fdf-b3b2-b807421744e3', 'Private phone calls between two friends', false, '7ec172a2-7ce5-4314-825c-72e17a52bd16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1ce8280c-6009-491e-b962-1d1e888d737d', 'Personal handwritten diaries', false, '7ec172a2-7ce5-4314-825c-72e17a52bd16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('90c9f1c6-a8f7-451b-9d6c-a8d160d026a7', 'Whispering in a classroom', false, '7ec172a2-7ce5-4314-825c-72e17a52bd16');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('e206761c-41e1-4069-9994-42e927bdf42a', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Medium', 'Why do houses in heavy-rainfall regions (like Assam) have STEEPLY SLOPING ROOFS and are built on raised STILTS (Piles)?', 'Vernacular stilt architecture (Chang Ghar) prevents flood inundation, while sloping thatch/tin roofs facilitate rapid storm drainage.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('abc418bd-7496-4b42-b952-4ac9fcb609b3', 'Steep roofs allow torrential rainwater to drain off rapidly, and raised wooden/bamboo stilts protect the living rooms from seasonal floodwaters and wild animals', true, 'e206761c-41e1-4069-9994-42e927bdf42a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('27cd247a-8dc0-4b45-ad9d-4a884d16b38c', 'To make houses look taller than trees', false, 'e206761c-41e1-4069-9994-42e927bdf42a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7bcbe97d-06d3-47b5-8863-9d20c76190eb', 'Because flat roofs are illegal in Assam', false, 'e206761c-41e1-4069-9994-42e927bdf42a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('645416cd-312a-4758-b225-a3b006c7e513', 'To catch more wind during storms', false, 'e206761c-41e1-4069-9994-42e927bdf42a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c7080efd-405e-4006-9d13-9d0c2f254e77', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'Read the statements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7ba2e157-7ab3-4209-ace5-1d09454704cd', 'Both (A) and (R) are true, and (R) is the correct explanation of (A).', true, 'c7080efd-405e-4006-9d13-9d0c2f254e77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('196a1ef8-b738-4828-9e58-88d51bfad2c4', 'Both (A) and (R) are true, but (R) is NOT the correct explanation of (A).', false, 'c7080efd-405e-4006-9d13-9d0c2f254e77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('62d3f52f-256f-469c-82bf-79c270ebbfa7', '(A) is true, but (R) is false.', false, 'c7080efd-405e-4006-9d13-9d0c2f254e77');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d71daf22-7d96-4b58-9241-b24f515efc42', '(A) is false, but (R) is true.', false, 'c7080efd-405e-4006-9d13-9d0c2f254e77');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3df67994-d4cf-4582-842c-4727f1bfbb75', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'Spot the IMPOSTER in the following comparative geographical features of the SAHARA (Hot Desert) vs LADAKH (Cold Desert):
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7436f8cf-ad1a-4c4d-beb7-1a188fae6643', 'Feature 1', false, '3df67994-d4cf-4582-842c-4727f1bfbb75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba950711-068c-4c2a-8eda-120837e7af41', 'Feature 2', false, '3df67994-d4cf-4582-842c-4727f1bfbb75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d57bad9a-143e-4bfd-b2ab-749fd2e0129d', 'Feature 3', false, '3df67994-d4cf-4582-842c-4727f1bfbb75');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7a9dcd1d-c98f-4ca0-b22f-017db6bc7461', 'Feature 4 (Ladakh is a high-altitude Himalayan COLD ARID DESERT with stunted alpine scrub, NOT a tropical rainforest with chimpanzees)', true, '3df67994-d4cf-4582-842c-4727f1bfbb75');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('8ade06b9-3737-40da-9a66-fe3d846771af', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'Analyze the environmental impact of modern mass tourism on the fragile ecology of Ladakh:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('960cc56e-b1f0-4a75-b266-2d10bb34d78e', 'Massive tourist influx causes severe groundwater depletion for luxury hotels, diesel vehicular pollution, plastic waste accumulation, and strains the traditional subsistence agriculture of Ladakhi villages', true, '8ade06b9-3737-40da-9a66-fe3d846771af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4ae8ea59-85fe-4ac2-aeab-0c0ed6a78c96', 'Tourism has turned Ladakh into a hot tropical swamp', false, '8ade06b9-3737-40da-9a66-fe3d846771af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5248c747-26ca-4db3-aa49-8f38369a3550', 'Tourism has completely stopped all cultural festivals', false, '8ade06b9-3737-40da-9a66-fe3d846771af');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4cd083ee-e0d1-4047-bafe-7c3194f92a5e', 'Tourists have removed all the Himalayan mountains', false, '8ade06b9-3737-40da-9a66-fe3d846771af');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ddca03b1-9b53-4749-bca0-8006758a6dff', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'Match Column I (Major Global Transport Routes / Channels) with Column II (Geographic Connections & Strategic Significance):
(a) Trans-Siberian Railway -> (i) St. Petersburg (Baltic) to Vladivostok (Pacific) across 9,289 km
(b) Suez Canal              -> (ii) Mediterranean Sea to Red Sea, slashing Euro-Asian maritime route
(c) Panama Canal            -> (iii) Atlantic Ocean to Pacific Ocean across the Central American Isthmus
(d) Golden Quadrilateral    -> (iv) 5,846 km expressway connecting Delhi, Mumbai, Chennai, Kolkata', 'Trans-Siberian = Russia rail; Suez = Med-Red sea; Panama = Atlantic-Pacific; Golden Quad = India mega-corridor.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bd528911-8534-4f4c-8749-938e6205373f', 'a-(i), b-(ii), c-(iii), d-(iv)', true, 'ddca03b1-9b53-4749-bca0-8006758a6dff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f6609af-1a04-4590-82d0-329deeddfd97', 'a-(ii), b-(i), c-(iv), d-(iii)', false, 'ddca03b1-9b53-4749-bca0-8006758a6dff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7be3f54-7f7d-4ccc-89af-a39f67a3ccf4', 'a-(iv), b-(iii), c-(ii), d-(i)', false, 'ddca03b1-9b53-4749-bca0-8006758a6dff');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1f42f1d4-fc9f-4d59-a837-0a235c9ae7c7', 'a-(iii), b-(iv), c-(i), d-(ii)', false, 'ddca03b1-9b53-4749-bca0-8006758a6dff');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('38f0a946-ae89-4916-99d8-d072820a3c45', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'Read the statements regarding extreme desert adaptations:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6574a71-b2a9-4df3-8335-b9f54168cd9d', 'Statements 1 and 2 only', true, '38f0a946-ae89-4916-99d8-d072820a3c45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6129788b-a286-4900-b4f3-dd4793f0d433', 'Statements 2 and 3 only', false, '38f0a946-ae89-4916-99d8-d072820a3c45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f32cf762-6cda-4bc5-9962-5fa3724afa76', 'Statements 1 and 3 only', false, '38f0a946-ae89-4916-99d8-d072820a3c45');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ee22c760-4a1d-46c9-9115-8239f8b09951', 'All Statements 1, 2, and 3', false, '38f0a946-ae89-4916-99d8-d072820a3c45');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('835aa655-0a0f-4146-b0e2-b69aedfb8cc7', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'How did the invention of Containerization (standardized steel Intermodal Shipping Containers) revolutionize 20th-century global trade?', 'Malcom McLean''s containerization innovation enabled frictionless intermodal logistics, driving post-war economic globalization.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d59a858e-fa4c-4206-9e97-96c3c161126d', 'Standardized 20-foot and 40-foot containers allow seamless mechanized transfer of freight between cargo ships, trains, and trucks without manual re-handling, slashing global freight shipping costs by over 90%', true, '835aa655-0a0f-4146-b0e2-b69aedfb8cc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ba946992-3317-4d20-8ad0-b53718a26d1e', 'Containers made ships float in the air', false, '835aa655-0a0f-4146-b0e2-b69aedfb8cc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f35cea84-b155-46dc-a325-16b8495f3013', 'Containers eliminated the need for ports', false, '835aa655-0a0f-4146-b0e2-b69aedfb8cc7');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('25a9b8be-1ee8-47a3-a5dd-0e400c4a8cdb', 'Containers are used only for transporting gold', false, '835aa655-0a0f-4146-b0e2-b69aedfb8cc7');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ba3dbf04-2178-40f0-864c-2663c966b8c2', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'What is the cultural and religious significance of the annual ''Hemis Festival'' in Ladakh?', 'The Hemis Tsechu festival honors Guru Padmasambhava with mystical tantric masked cham dances depicting the triumph of dharma over demonic forces.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dc5c9c5b-563c-4654-b573-f85ba32e320b', 'A vibrant Buddhist festival celebrated at Hemis Gompa commemorating the birth anniversary of Guru Padmasambhava with sacred masked ''Chham'' dances and traditional music', true, 'ba3dbf04-2178-40f0-864c-2663c966b8c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3385ae3b-1a6d-44fc-a3da-bfe49f3aba3e', 'A boat race festival on the Indus river', false, 'ba3dbf04-2178-40f0-864c-2663c966b8c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('75e708d0-2690-45c3-9db9-db9ba41a93a8', 'A harvest festival celebrating mangoes', false, 'ba3dbf04-2178-40f0-864c-2663c966b8c2');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4738a558-72ba-4d82-ab05-b2b94e1062b8', 'A horse race across the Himalayas', false, 'ba3dbf04-2178-40f0-864c-2663c966b8c2');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('5481d8bb-ebb5-49b6-bf7a-f50b1835e8d0', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'Consider four types of human settlements:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('427b93a0-6728-40fc-a3d5-2b378a522dfc', 'Topography, water availability, agricultural land fertility, and climate constraints dictating spatial human organization', true, '5481d8bb-ebb5-49b6-bf7a-f50b1835e8d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e6942293-c0f4-44cc-80b5-be138154e3db', 'Government orders telling people where to sleep', false, '5481d8bb-ebb5-49b6-bf7a-f50b1835e8d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea1d9662-55ce-4c74-8133-0a03c4fd163e', 'The color of local soil only', false, '5481d8bb-ebb5-49b6-bf7a-f50b1835e8d0');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('65e99acd-ecdf-4046-b718-ac5f9c66cf67', 'Random chance with no geographic logic', false, '5481d8bb-ebb5-49b6-bf7a-f50b1835e8d0');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('4b6da11a-bd75-4db3-941f-6cb9bf978883', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'How did the ancient ''Silk Route'' passing through the high Karakoram passes of Ladakh historically connect India with Central Asia, Tibet, and China?', 'Leh was a pivotal crossroad on the trans-Himalayan Silk Road network, linking Kashmir and Punjab to Yarkand, Kashgar, and Lhasa.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('247ee2dc-c849-4dfb-975a-413f94583956', 'Leh served as a bustling entrepôt caravan trade hub where Indian merchants traded spices, cotton, and dyes for Central Asian silk, raw wool, charas, and turquoise stones', true, '4b6da11a-bd75-4db3-941f-6cb9bf978883');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('49840d42-aa11-47ae-b246-a7df304d39a4', 'Trade was carried out using submarine boats', false, '4b6da11a-bd75-4db3-941f-6cb9bf978883');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9543e36e-0204-4429-8786-4d16df5d04ec', 'It was a modern railway line built 2,000 years ago', false, '4b6da11a-bd75-4db3-941f-6cb9bf978883');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dae41724-ceaf-43a7-b00e-8683875f0cea', 'It was an air route for flying carpets', false, '4b6da11a-bd75-4db3-941f-6cb9bf978883');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7b93a87d-889b-4226-a019-94598368e813', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'Why is ''Information Highway'' (High-Speed Fiber-Optic Broadband & 5G Satellite Internet) considered the modern equivalent of 19th-century railway networks?', 'Broadband data infrastructure is the 21st-century neural network of global capitalism, accelerating frictionless virtual commerce, research, and communication.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e3906c5a-ad01-4074-9453-ba835d0113a4', 'Just as railways revolutionized the physical transport of freight and labor during the Industrial Revolution, high-speed digital networks transport massive data, finance, commerce, and knowledge instantly across the globe', true, '7b93a87d-889b-4226-a019-94598368e813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1684b2ab-5024-4cad-8f47-060c5070c963', 'Because fiber-optic cables are made of iron rails', false, '7b93a87d-889b-4226-a019-94598368e813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd081edc-d340-43f2-8c85-346fbb84abe1', 'Because internet cables carry physical train cars', false, '7b93a87d-889b-4226-a019-94598368e813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3a35dfd4-469e-49f5-a6da-30abb5be571a', 'Because internet was invented in the 19th century', false, '7b93a87d-889b-4226-a019-94598368e813');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('45e2df49-8a68-4ecd-ae18-3117d7ab0550', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'What is the engineering challenge and significance of the ''Atal Tunnel'' (Rohtang) and upcoming ''Zojila Tunnel'' in the Himalayan transport network?', 'Atal Tunnel (9.02 km) and Zojila Tunnel (14.2 km) conquer extreme mountain geography, ensuring year-round strategic and socioeconomic connectivity.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('154beefe-6998-4642-ae08-8ff4c7ace53e', 'They provide all-weather, year-round strategic military and civilian road connectivity beneath avalanche-prone high passes, ending months of winter isolation for Ladakh and Lahaul-Spiti', true, '45e2df49-8a68-4ecd-ae18-3117d7ab0550');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0892ccd-8f78-4301-8a0a-394d79da6edc', 'They are built to store water', false, '45e2df49-8a68-4ecd-ae18-3117d7ab0550');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36e01112-0665-4938-96e4-ef56f1533d6c', 'They are giant shopping malls inside mountains', false, '45e2df49-8a68-4ecd-ae18-3117d7ab0550');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eeb53249-c79c-4a65-8113-1fa4d3c9af89', 'They were constructed for tourist trains to Europe', false, '45e2df49-8a68-4ecd-ae18-3117d7ab0550');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('2849a754-c094-4e13-b6eb-9349363242d8', 'Class 7', 'Social Science', 'Chapter 12: Human Environment, Settlements, Transport, Communication & Life in Deserts', 'Hard', 'What grand humanistic and geographic perspective concludes the NCERT Class 7 Social Science curriculum in Chapter 12?', 'Chapter 12 concludes the Class 7 Social Science curriculum by synthesizing human ecological adaptability, technological connectivity, and sustainable biocultural conservation.', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f4273154-2305-4aba-9b4b-1a1c18f2ebae', 'Humanity is an integral part of the living Earth—our settlements, global transport networks, and communication technologies reflect our creative adaptability, demanding that we live in harmonious balance with natural ecosystems, respecting cultural diversity and conserving planetary resources for future generations', true, '2849a754-c094-4e13-b6eb-9349363242d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bed9e8da-846c-4293-9dd6-4085414f9af9', 'That human beings should conquer and destroy all natural environments', false, '2849a754-c094-4e13-b6eb-9349363242d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('375db760-f9f2-4c05-9e50-61dbf816a738', 'That deserts are useless wastelands that have no culture or life', false, '2849a754-c094-4e13-b6eb-9349363242d8');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('273ed4f9-92a5-4b13-8c60-a334f2ad7dc6', 'That all humans should live in identical cities', false, '2849a754-c094-4e13-b6eb-9349363242d8');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('3f79b05b-afc7-4e49-a3be-98d6226aeb2f', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Easy', 'सार्थक शब्दों का वह व्यवस्थित एवं क्रमबद्ध समूह जो किसी विचार या भाव को पूर्ण रूप से स्पष्ट करता है, क्या कहलाता है?', 'वाक्य: सार्थक शब्दों का व्यवस्थित एवं व्याकरण सम्मत समूह जिससे वक्ता का पूर्ण अभिप्राय स्पष्ट हो।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('08aefa81-e8fa-4b11-b8a2-747b531c6c3b', 'वाक्य (Sentence)', true, '3f79b05b-afc7-4e49-a3be-98d6226aeb2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('624ad2be-db52-4865-925d-806bae537b74', 'वर्णमाला', false, '3f79b05b-afc7-4e49-a3be-98d6226aeb2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b996c218-f60a-4202-9903-e052efb2d57d', 'शब्दकोश', false, '3f79b05b-afc7-4e49-a3be-98d6226aeb2f');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('88f841e3-91a8-4ba2-a94b-2d41ffdedb8f', 'पदबंध मात्र', false, '3f79b05b-afc7-4e49-a3be-98d6226aeb2f');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('682b20a8-6591-4c5c-9cd5-a774a0009d72', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Easy', 'व्याकरण की दृष्टि से वाक्य के मुख्य रूप से दो अनिवार्य अंग कौन-से होते हैं?', 'वाक्य के दो अनिवार्य घटक (अंग) होते हैं: उद्देश्य (जिसके बारे में बात हो) और विधेय (उद्देश्य के बारे में जो कहा जाए)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f5666eb-d818-43ca-bc49-d42574dc8be5', '1. उद्देश्य (Subject) और 2. विधेय (Predicate)', true, '682b20a8-6591-4c5c-9cd5-a774a0009d72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('969511b7-69da-4664-9605-8d6a1eeb7d6c', '1. संज्ञा और 2. सर्वनाम', false, '682b20a8-6591-4c5c-9cd5-a774a0009d72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('650cc1b1-d5a3-484d-8405-bccca00ca4a1', '1. स्वर और 2. व्यंजन', false, '682b20a8-6591-4c5c-9cd5-a774a0009d72');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9327dd86-5651-4c59-9143-a7b1f5435309', '1. तत्सम और 2. तद्भव', false, '682b20a8-6591-4c5c-9cd5-a774a0009d72');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('026cfb4a-9f6e-469e-8366-c45d7ac1a062', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Easy', 'वाक्य में जिसके विषय में कुछ कहा जाता है, उसे व्याकरण में क्या कहते हैं?', 'उद्देश्य: वाक्य में जिसके विषय में कोई विधान या बात की जाए, वह उद्देश्य (Subject) कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a9c8be97-474b-4e34-8928-964c98dd04bd', 'उद्देश्य (जैसे: ''रोहन पुस्तक पढ़ता है'' में ''रोहन'')', true, '026cfb4a-9f6e-469e-8366-c45d7ac1a062');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3ea5381-ce3a-4fae-b970-e90404f5db5f', 'विधेय', false, '026cfb4a-9f6e-469e-8366-c45d7ac1a062');
