INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('141423b0-8eca-4a22-98cf-20d9b5d4dc35', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Easy', 'वाक्य में उद्देश्य (कर्ता) के विषय में जो कुछ कहा जाता है, उसे क्या कहते हैं?', 'विधेय: उद्देश्य के बारे में कही गई समस्त बात/क्रिया विधेय कहलाती है।', NOW()) ON CONFLICT DO NOTHING;
