INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('05dbbf6f-3431-4d0f-9b02-8f17c5f16b11', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Easy', 'रचना की दृष्टि से वाक्य के मुख्य रूप से कितने भेद होते हैं?', 'रचना के आधार पर वाक्य के 3 भेद हैं: सरल वाक्य, संयुक्त वाक्य, तथा मिश्र वाक्य।', NOW()) ON CONFLICT DO NOTHING;
