INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('672061d9-d82b-4dc2-9673-7560e88deb58', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Easy', 'अर्थ की दृष्टि से हिंदी में वाक्य के कुल कितने भेद होते हैं?', 'अर्थ के आधार पर वाक्य के 8 भेद होते हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6779c263-600f-4466-a201-cf5740371b29', '8 भेद (विधानवाचक, निषेधवाचक, आज्ञावाचक, प्रश्नवाचक, विस्मयादिवाचक, इच्छावाचक, संदेहवाचक, संकेतवाचक)', true, '672061d9-d82b-4dc2-9673-7560e88deb58');
