INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6fe6fbf3-1c0a-4aa2-901b-f2397073c444', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Easy', 'वाक्य के पूर्ण होने पर अंत में प्रयुक्त होने वाले विराम चिह्न (।) को क्या कहते हैं?', 'पूर्णविराम (।): साधारण वाक्य की समाप्ति पर लगने वाला विराम चिह्न।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('4bcbf4bd-e835-4e91-b3f0-59cf291b3ae8', 'पूर्णविराम (Full Stop)', true, '6fe6fbf3-1c0a-4aa2-901b-f2397073c444');
