INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99e01699-d4af-4427-8273-72e4f8aeeb76', 'उपविराम', false, '6fe6fbf3-1c0a-4aa2-901b-f2397073c444');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('04c37ea0-570b-4a7f-9032-5a203d824149', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Easy', 'पढ़ते या बोलते समय बहुत थोड़े समय के लिए रुकने हेतु प्रयुक्त होने वाले चिह्न (,) को क्या कहते हैं?', 'अल्पविराम (,): वाक्य में न्यूनतम ठहराव दर्शाने के लिए प्रयुक्त चिह्न।', NOW()) ON CONFLICT DO NOTHING;
