INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3106db19-95d3-4cbc-ac71-5eca1c1f28d8', 'लाघव चिह्न', false, '04c37ea0-570b-4a7f-9032-5a203d824149');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('d13d1686-8e2c-400b-a805-caaf98e4147c', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Easy', 'किसी के कहे गए कथन को ज्यों-का-त्यों उद्धृत करने के लिए किस चिह्न (" ") का प्रयोग किया जाता है?', 'उद्धरण चिह्न (" "): प्रत्यक्ष कथन को मूल रूप में व्यक्त करने हेतु प्रयुक्त।', NOW()) ON CONFLICT DO NOTHING;
