INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('19caf6c0-0611-43f5-b3f2-f1475c3ab15b', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Easy', '''ईद का चाँद होना'' मुहावरे का सही अर्थ क्या है?', '''ईद का चाँद होना'': दुर्लभ होना या अत्यधिक लंबे अंतराल के बाद दिखाई देना।', NOW()) ON CONFLICT DO NOTHING;
