INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('6c94a4a6-b996-4301-bb39-e3691a979278', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Medium', 'जिस वाक्य में केवल एक ही उद्देश्य (कर्ता) और एक ही समापिका क्रिया (विधेय) होती है (जैसे: ''सूर्य पूर्व में उदय होता है''), उसे क्या कहते हैं?', 'सरल वाक्य: जिसमें एक ही मुख्य उद्देश्य और एक ही विधेय समापिका क्रिया होती है।', NOW()) ON CONFLICT DO NOTHING;
