INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('808e455d-0555-45de-b47a-b6fd6c4eba53', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Medium', '''नाच न जाने आँगन टेढ़ा'' लोकोक्ति का सही अर्थ क्या है?', '''नाच न जाने आँगन टेढ़ा'': स्वयं काम न आने पर परिस्थिति या उपकरण में दोष मढ़ना।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('19438616-b280-47ac-ad22-6397f535a75c', 'अपनी अयोग्यता या कमी को छिपाने के लिए साधनों या दूसरों में दोष निकालना', true, '808e455d-0555-45de-b47a-b6fd6c4eba53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6356e9b3-e2ec-4bf8-815a-649e2bdeee1b', 'टेढ़े आँगन में नाचना', false, '808e455d-0555-45de-b47a-b6fd6c4eba53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('fb8a1dff-4cde-4ed8-aef6-394a65d5c2b0', 'नृत्य कला सीखना', false, '808e455d-0555-45de-b47a-b6fd6c4eba53');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('74e27d3f-0c6a-4e37-936d-fd8ce1b9cbb9', 'घर का आँगन सुंदर बनाना', false, '808e455d-0555-45de-b47a-b6fd6c4eba53');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('7ed7ef24-f882-4fc4-8e90-98b55636f65d', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Medium', '''ऊँट के मुँह में जीरा'' लोकोक्ति का सही अर्थ क्या है?', '''ऊँट के मुँह में जीरा'': अत्यधिक खुराक या आवश्यकता की तुलना में बहुत नगण्य वस्तु मिलना।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aa14fe0a-1054-4dac-afbf-0731b6307d69', 'बहुत बड़ी आवश्यकता के लिए अत्यंत कम या अपर्याप्त मात्रा में वस्तु मिलना', true, '7ed7ef24-f882-4fc4-8e90-98b55636f65d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edd48f1f-f7d5-41da-8eb8-74302bbf5c6e', 'ऊँट को मसाले खिलाना', false, '7ed7ef24-f882-4fc4-8e90-98b55636f65d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('024a4659-b756-4698-973d-80d4bf381552', 'जीरा की खेती करना', false, '7ed7ef24-f882-4fc4-8e90-98b55636f65d');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('232c7fb5-8fc8-46f1-a597-506ed3a2a210', 'ऊँट की सवारी करना', false, '7ed7ef24-f882-4fc4-8e90-98b55636f65d');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('a5bb0bb0-4032-4b41-b782-9388d21a7813', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Medium', '''दूर के ढोल सुहावने होना'' लोकोक्ति का सही अर्थ क्या है?', '''दूर के ढोल सुहावने'': दूर से वस्तुएँ मनोहर प्रतीत होती हैं किंतु यथार्थ में कठिनाइयाँ छिपी होती हैं।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a99823cf-e7b0-45c3-a4f7-5a916388dc07', 'दूर से चीजें अच्छी और आकर्षक लगती हैं, परन्तु पास जाने पर वास्तविकता कुछ और होती है', true, 'a5bb0bb0-4032-4b41-b782-9388d21a7813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('968ee88e-2ca6-41a6-93a6-30223f02eb0f', 'ढोल की आवाज बहुत मीठी होना', false, 'a5bb0bb0-4032-4b41-b782-9388d21a7813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('feb2e696-d5ce-4be7-b4e3-072459cf1ed2', 'दूर खड़े होकर गाना सुनना', false, 'a5bb0bb0-4032-4b41-b782-9388d21a7813');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f566fe5-8ab7-46f7-9f67-0a6475074390', 'उत्सव मनाना', false, 'a5bb0bb0-4032-4b41-b782-9388d21a7813');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('01262ec1-da9d-4495-a494-a647ddf60c32', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Medium', '''मुहावरे'' (Idiom) और ''लोकोक्ति'' (Proverb) में क्या मूलभूत व्याकरणिक अंतर होता है?', 'मुहावरा वाक्यांश (अपूर्ण वाक्य) है जो वाक्य का अंग बनता है; लोकोक्ति पूर्ण स्वतंत्र अनुभव-सिद्ध वाक्य होती है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('ea6a30a6-dd50-4c8a-bd1a-8bdfdfa13e0a', 'मुहावरा एक ''वाक्यांश'' (Phrase) होता है जो वाक्य में मिलकर प्रयुक्त होता है और जिसका लिंग-वचन के अनुसार रूपांतरण होता है ; जबकि लोकोक्ति एक ''पूर्ण स्वतंत्र वाक्य'' (Full sentence) होती है जिसका रूप अपरिवर्तित रहता है', true, '01262ec1-da9d-4495-a494-a647ddf60c32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a51fc42f-e773-4663-8e40-9686d5804dc2', 'मुहावरा केवल संस्कृत में होता है', false, '01262ec1-da9d-4495-a494-a647ddf60c32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b1f079c3-5021-45f2-af90-5e7f5bea4018', 'लोकोक्ति केवल एक शब्द की होती है', false, '01262ec1-da9d-4495-a494-a647ddf60c32');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bad9696b-dc6e-49df-8755-e5d88b4a4dfb', 'दोनों में कोई अंतर नहीं होता', false, '01262ec1-da9d-4495-a494-a647ddf60c32');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c64c6177-8cd0-466b-b7cb-2e063eaa8c2e', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Medium', 'निम्नलिखित में से ''शुद्ध वर्तनी'' वाला शब्द कौन-सा है?', 'उत् + ज्वल = उज्ज्वल (दोनों ''ज'' अर्ध/आधे होते हैं)।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f5a5ef42-f062-4543-a7ca-3cb10c92f18e', 'उज्ज्वल (उ + ज् + ज् + व + ल)', true, 'c64c6177-8cd0-466b-b7cb-2e063eaa8c2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('633cd3bf-4acb-493a-ad1d-99b193b99fdb', 'उज्वल', false, 'c64c6177-8cd0-466b-b7cb-2e063eaa8c2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('55be6f0b-a1bf-469c-93a0-04da32cafc4a', 'उज्जवल', false, 'c64c6177-8cd0-466b-b7cb-2e063eaa8c2e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('67437bcc-1364-472c-8dfb-d1def2723103', 'ऊज्जवल', false, 'c64c6177-8cd0-466b-b7cb-2e063eaa8c2e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('71e1a1cd-8052-4410-9a71-faff0a4fd45e', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Medium', 'निम्नलिखित में से ''व्याकरणिक दृष्टि से शुद्ध वाक्य'' का चयन कीजिए:', 'दूध शुद्ध होता है, गाय नहीं; अतः पदक्रम की दृष्टि से ''यहाँ गाय का शुद्ध दूध मिलता है'' शुद्ध है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5f5e60f0-cb93-465d-a626-a5686477a515', '''यहाँ शुद्ध गाय का दूध मिलता है।'' -> अशुद्ध ; ''यहाँ गाय का शुद्ध दूध मिलता है।'' -> शुद्ध', true, '71e1a1cd-8052-4410-9a71-faff0a4fd45e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('686c7947-d94f-4926-8403-cba9863ad11f', '''मेरे को घर जाना है।''', false, '71e1a1cd-8052-4410-9a71-faff0a4fd45e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('aba2cf76-d9f4-4f9f-b954-99785b7d0c03', '''अनेकों लोग आए थे।''', false, '71e1a1cd-8052-4410-9a71-faff0a4fd45e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7f2d7883-e33b-4763-b271-14c43f82cfab', '''वह बहुत सबसे चतुर है।''', false, '71e1a1cd-8052-4410-9a71-faff0a4fd45e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f4878f73-25cb-4561-b657-321327cfd9d6', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Hard', 'कथन और कारण को ध्यानपूर्वक पढ़ें:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('dd6f6dfb-e7a7-42af-b0df-ee456e8f9b13', '(A) और (R) दोनों सही हैं तथा (R), (A) की सही व्याख्या करता है।', true, 'f4878f73-25cb-4561-b657-321327cfd9d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9791ff9f-0988-40dd-92b7-baf51f0a05e3', '(A) और (R) दोनों सही हैं, परन्तु (R), (A) की सही व्याख्या नहीं करता।', false, 'f4878f73-25cb-4561-b657-321327cfd9d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('997627cb-a685-4cb3-9983-e21d7dc530ec', '(A) सही है, परन्तु (R) गलत है।', false, 'f4878f73-25cb-4561-b657-321327cfd9d6');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('99798b58-ff58-4e19-baeb-393a9e85c309', '(A) गलत है, परन्तु (R) सही है।', false, 'f4878f73-25cb-4561-b657-321327cfd9d6');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('963b1fdf-134b-45a3-a7c0-a38b00c9ac67', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Hard', 'Spot the IMPOSTER in the following classification of मुहावरे और उनके लाक्षणिक अर्थों में:
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('092925c7-266e-49d5-8a6b-ff0b188f1027', 'युग्म 1', false, '963b1fdf-134b-45a3-a7c0-a38b00c9ac67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('3ef74a72-e90c-4dcf-ad79-e9fbcb77dcd8', 'युग्म 2', false, '963b1fdf-134b-45a3-a7c0-a38b00c9ac67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c6a10331-6fd2-4c7e-a7ca-e0664a071f92', 'युग्म 3', false, '963b1fdf-134b-45a3-a7c0-a38b00c9ac67');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bc4ba50c-ed6c-4f5a-ab0e-39b5414a37f2', 'युग्म 4 (''हाथ-पैर मारना'' का लाक्षणिक अर्थ ''कठिन प्रयास / प्रयत्न करना'' होता है, केवल तैराकी पदक जीतना नहीं)', true, '963b1fdf-134b-45a3-a7c0-a38b00c9ac67');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1f5eacbb-6d40-4a6f-b5f7-7ccfdb6bf909', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Hard', 'सुमेलित कीजिए (विराम चिह्न और उनके मानक नाम):
(क) ;  -> (i) अर्धविराम (Semicolon)
(ख) :  -> (ii) उपविराम / अपूर्णविराम (Colon)
(ग) -  -> (iii) योजक चिह्न (Hyphen)
(घ) —  -> (iv) निर्देशक चिह्न (Dash)', '; = अर्धविराम; : = उपविराम; - = योजक; — = निर्देशक।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b336c1bf-7665-4e9e-9b7a-eb2a6ce358b1', 'क-(i), ख-(ii), ग-(iii), घ-(iv)', true, '1f5eacbb-6d40-4a6f-b5f7-7ccfdb6bf909');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('6bd57ede-fca8-4fa0-b4c6-4b19b1e29afd', 'क-(ii), ख-(i), ग-(iv), घ-(iii)', false, '1f5eacbb-6d40-4a6f-b5f7-7ccfdb6bf909');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('22d8a490-7d5d-49a6-90fb-f19bd71ec20a', 'क-(iv), ख-(iii), ग-(ii), घ-(i)', false, '1f5eacbb-6d40-4a6f-b5f7-7ccfdb6bf909');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0d2e2ed-102b-41c0-8271-1c91c63d3158', 'क-(iii), ख-(iv), ग-(i), घ-(ii)', false, '1f5eacbb-6d40-4a6f-b5f7-7ccfdb6bf909');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('fc22a9f8-aabd-4d63-8062-cc6db1410810', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Hard', 'मिश्र वाक्य में ''आश्रित उपवाक्य'' (Subordinate Clauses) के तीन मुख्य प्रकार कौन-से होते हैं?', 'आश्रित उपवाक्य के 3 भेद: संज्ञा उपवाक्य (''कि''), विशेषण उपवाक्य (''जो/जिसने''), क्रियाविशेषण उपवाक्य (''जब/जहाँ/जैसे/क्योंकि'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2b3fca9f-acd0-4338-80fe-6a451e65d85c', '1. संज्ञा आश्रित उपवाक्य (प्रायः ''कि'' से जुड़े) ; 2. विशेषण आश्रित उपवाक्य (जो, जिसे, जिसका से जुड़े) ; 3. क्रियाविशेषण आश्रित उपवाक्य (जब-तब, जहाँ-तहाँ, जैसे-वैसे, क्योंकि, यद्यपि-तथापि से जुड़े)', true, 'fc22a9f8-aabd-4d63-8062-cc6db1410810');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('eb918e34-d723-41f9-ac02-86e2b66f4068', 'सकर्मक, अकर्मक और द्विकर्मक उपवाक्य', false, 'fc22a9f8-aabd-4d63-8062-cc6db1410810');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('14d40610-328f-4464-b209-40784727a79d', 'विधानवाचक, निषेधवाचक और आज्ञावाचक उपवाक्य', false, 'fc22a9f8-aabd-4d63-8062-cc6db1410810');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('a8227169-778a-483b-b5ea-bc2ce7ee643d', 'सरल, संयुक्त और मिश्र उपवाक्य', false, 'fc22a9f8-aabd-4d63-8062-cc6db1410810');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('f28af1d1-9c43-468b-bcd1-faf77e49d145', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Hard', '''उसने कहा कि मैं निर्दोष हूँ।'' इस वाक्य में रेखांकित उपवाक्य ''कि मैं निर्दोष हूँ'' किस प्रकार का आश्रित उपवाक्य है?', '''कि'' से प्रारंभ होकर मुख्य क्रिया के कर्म के रूप में आने वाला उपवाक्य संज्ञा आश्रित उपवाक्य कहलाता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('988218e9-a697-40ed-aa4a-e432aaa784d2', 'संज्ञा आश्रित उपवाक्य (क्रिया ''कहा'' के कर्म के रूप में प्रयुक्त)', true, 'f28af1d1-9c43-468b-bcd1-faf77e49d145');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f7e7651e-bc99-4844-956a-24c452db0abd', 'विशेषण आश्रित उपवाक्य', false, 'f28af1d1-9c43-468b-bcd1-faf77e49d145');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0bd82980-ae09-4765-876d-b5aaa6413fa6', 'क्रियाविशेषण आश्रित उपवाक्य', false, 'f28af1d1-9c43-468b-bcd1-faf77e49d145');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0c209df8-abc6-4fe5-a9a1-031ca0e62f8b', 'प्रधान उपवाक्य', false, 'f28af1d1-9c43-468b-bcd1-faf77e49d145');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('c026c270-b768-48f0-a19c-47ab54ec490e', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Hard', '''जो लड़का कल आया था, वह मेरा मित्र है।'' वाक्य में ''जो लड़का कल आया था'' किस प्रकार का आश्रित उपवाक्य है?', '''जो/जिसने'' से प्रारंभ होकर प्रधान उपवाक्य की संज्ञा की विशेषता बताने वाला उपवाक्य विशेषण आश्रित उपवाक्य होता है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b3242648-6764-446b-bbc1-add532a6ceb6', 'विशेषण आश्रित उपवाक्य (संज्ञा ''लड़का'' की विशेषता बता रहा है)', true, 'c026c270-b768-48f0-a19c-47ab54ec490e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('36212ce7-34d2-41b8-807c-e02a031f720f', 'संज्ञा आश्रित उपवाक्य', false, 'c026c270-b768-48f0-a19c-47ab54ec490e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c2a0d8b1-7902-445d-af64-6ae53e082b70', 'क्रियाविशेषण उपवाक्य', false, 'c026c270-b768-48f0-a19c-47ab54ec490e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8f996077-ef01-4f82-87db-808b0f930b0e', 'विधेय', false, 'c026c270-b768-48f0-a19c-47ab54ec490e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('1fbefd6a-3805-4a7b-adf1-59195e13927a', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Hard', 'निम्नलिखित में से ''वाक्य रूपांतरण'' (सरल से संयुक्त) का शुद्ध उदाहरण कौन-सा है?', 'समानाधिकरण योजक ''और'' जोड़कर दो स्वतंत्र उपवाक्यों में रूपांतरित करना शुद्ध संयुक्त वाक्य रचना है।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('61c0745b-f4f6-40c0-8029-bc3e07ac60a0', 'सरल वाक्य: ''सूर्योदय होने पर कुहासा छँट गया।'' -> संयुक्त वाक्य: ''सूर्योदय हुआ और कुहासा छँट गया।''', true, '1fbefd6a-3805-4a7b-adf1-59195e13927a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('0f0e0e95-809f-4a8d-954a-97d3f97c2598', 'सरल वाक्य: ''सूर्योदय हुआ क्योंकि कुहासा छँट गया।''', false, '1fbefd6a-3805-4a7b-adf1-59195e13927a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('7cf117c0-6f18-45db-b693-fff6539dc434', 'सरल वाक्य: ''जब सूर्योदय हुआ तब कुहासा छँट गया।''', false, '1fbefd6a-3805-4a7b-adf1-59195e13927a');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('9f590e59-9ea5-4759-84c0-a917ea8a12c8', 'सरल वाक्य: ''सूर्योदय होते ही कुहासा छँटा।''', false, '1fbefd6a-3805-4a7b-adf1-59195e13927a');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('ea4e2c9f-74f2-4d5b-907e-fa97696b2a16', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Hard', 'निम्नलिखित वाक्यों में से ''अशुद्ध वाक्य'' को पहचानिए:', '''कृपया'' और ''करके'' का साथ प्रयोग वर्जित पुनरुक्ति दोष है; शुद्ध रूप: ''कृपया मेरी बात सुनिए''।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('8bc9497e-b0cd-4bca-b6aa-a39b302cec96', '''कृपया करके मेरी बात सुनिए।'' (अशुद्ध: ''कृपया'' और ''करके'' दोनों का एक साथ प्रयोग पुनरुक्ति दोष है ; शुद्ध: ''कृपया मेरी बात सुनिए'' या ''कृपा करके मेरी बात सुनिए'')', true, 'ea4e2c9f-74f2-4d5b-907e-fa97696b2a16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('adb98f92-0307-4589-a431-5f066d94ffe3', '''साहित्य और समाज का घनिष्ठ संबंध है।''', false, 'ea4e2c9f-74f2-4d5b-907e-fa97696b2a16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d6856434-6d15-47bc-9b38-f7cc64e4e16a', '''वहाँ भारी भीड़ जमा थी।''', false, 'ea4e2c9f-74f2-4d5b-907e-fa97696b2a16');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b772a788-572e-471c-898f-b329a68a6bdb', '''प्रत्येक बच्चे को दो-दो संतरे दिए गए।''', false, 'ea4e2c9f-74f2-4d5b-907e-fa97696b2a16');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('87f242ea-e8dd-4b4c-9af7-a3063b007197', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Hard', '''कवयित्री'' और ''आशीर्वाद'' शब्दों की शुद्ध वर्तनी वाला युग्म कौन-सा है?', 'शुद्ध वर्तनी: ''कवयित्री'' (क-व-यि-त्री) तथा ''आशीर्वाद'' (''व'' के ऊपर रेफ ''र्'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('b7cda1ba-488a-4479-b5d9-99040922b7d5', 'कवयित्री और आशीर्वाद (क + व + यि + त्री ; आ + शी + र्वा + द)', true, '87f242ea-e8dd-4b4c-9af7-a3063b007197');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1817902d-7221-47aa-95d0-f41d3b652a30', 'कवयित्री और आशीवार्द', false, '87f242ea-e8dd-4b4c-9af7-a3063b007197');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('2e2fdfd5-e7cf-41a6-8d3a-db59989c817c', 'कविइत्री और आशीर्वाद', false, '87f242ea-e8dd-4b4c-9af7-a3063b007197');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('d4b89d9a-32f4-4266-ac50-f9ae20f1e1dd', 'कवयत्री और आशिर्वाद', false, '87f242ea-e8dd-4b4c-9af7-a3063b007197');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('65fa8e0e-fa92-48d9-bcfe-c6e8a4ae16f1', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Hard', '''गागर में सागर भरना'' मुहावरे का सही और सटीक साहित्यिक अर्थ क्या है?', '''गागर में सागर भरना'': अत्यंत संक्षिप्त एवं सारगर्भित पदावली में गहन अर्थ का निरूपण करना।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('68ea25d1-751e-4062-b079-7d885a0a35ac', 'थोड़े से शब्दों में बहुत गंभीर, गूढ़ और विस्तृत अर्थ व्यक्त करना (जैसे बिहारी के दोहे)', true, '65fa8e0e-fa92-48d9-bcfe-c6e8a4ae16f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('e0b15a65-b58f-43e5-ad27-d52421e8d29d', 'मटके में समुद्र का पानी भरना', false, '65fa8e0e-fa92-48d9-bcfe-c6e8a4ae16f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('f6f4a482-5f21-4a7e-a664-93266e3d0a70', 'बड़ा तालाब बनाना', false, '65fa8e0e-fa92-48d9-bcfe-c6e8a4ae16f1');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c10e89d4-c1c1-4a84-b510-5698d86413d3', 'कविताएँ लिखना', false, '65fa8e0e-fa92-48d9-bcfe-c6e8a4ae16f1');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('efc86a69-3be5-4443-9444-cee5a7aa987e', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Hard', 'विराम चिह्नों के गलत प्रयोग से वाक्य का अर्थ किस प्रकार अनर्थ में बदल सकता है, इसका सटीक उदाहरण कौन-सा है?', 'अल्पविराम की स्थिति बदलने से वाक्य का अर्थ 180° उलट जाता है (''रोको, मत जाने दो'' vs ''रोको मत, जाने दो'')।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('404ae1fc-4f24-45c7-8ba3-e59c4fda9cc2', '''रोको, मत जाने दो।'' (रुकने का आदेश) बनाम ''रोको मत, जाने दो।'' (जाने की अनुमति) — अल्पविराम का स्थान बदलने से अर्थ पूर्णतः विपरीत हो जाता है', true, 'efc86a69-3be5-4443-9444-cee5a7aa987e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('1527270a-55c9-4e47-b73c-849ddc634e79', 'विराम चिह्नों से अर्थ पर कोई प्रभाव नहीं पड़ता', false, 'efc86a69-3be5-4443-9444-cee5a7aa987e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('bcc9bc4f-8e70-4ccd-a18c-849dfab3a349', 'वाक्य केवल लंबा हो जाता है', false, 'efc86a69-3be5-4443-9444-cee5a7aa987e');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('c3683ed7-14d2-4515-ae2d-64b534b21890', 'विराम चिह्न केवल मुद्रण का सजावटी साधन हैं', false, 'efc86a69-3be5-4443-9444-cee5a7aa987e');
INSERT INTO "Question" ("id", "class", "subject", "chapter", "difficulty", "text", "explanation", "createdAt") VALUES ('9c7c79ba-7d2e-485e-a054-2f8ae1b76080', 'Class 7', 'Hindi Grammar', 'Chapter 12: वाक्य विचार, विराम चिह्न एवं मुहावरे-लोकोक्तियाँ', 'Hard', 'कक्षा 7 हिंदी व्याकरण के संपूर्ण पाठ्यक्रम का सर्वोच्च भाषाई प्रयोजन क्या है?', 'कक्षा 7 व्याकरण का समग्र उद्देश्य: विद्यार्थियों में शुद्ध वर्तनी, सुगठित वाक्य-विन्यास, अर्थगत स्पष्टता और समृद्ध अभिव्यक्ति-कौशल का पूर्ण विकास।', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('986131b2-e943-4976-9e47-7859b86dc0df', 'वर्ण, शब्द, संज्ञा, सर्वनाम, विशेषण, क्रिया, काल, अव्यय, संधि-समास, वाक्य-संरचना और मुहावरे-लोकोक्तियों के सम्यक ज्ञान द्वारा भाषा को व्याकरण सम्मत, प्रवाहमयी, त्रुटिहीन, प्रभावी तथा अभिव्यक्ति की दृष्टि से समृद्ध एवं सामर्थ्यवान बनाना', true, '9c7c79ba-7d2e-485e-a054-2f8ae1b76080');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('edf1fadc-bb5c-4511-9abc-77a0a839f36e', 'केवल परीक्षाओं में अंक प्राप्त करना', false, '9c7c79ba-7d2e-485e-a054-2f8ae1b76080');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('5a5234dc-9cb0-4a1b-b3d0-5ae883940116', 'कठिन शब्दों को याद करके भूल जाना', false, '9c7c79ba-7d2e-485e-a054-2f8ae1b76080');
INSERT INTO "Option" ("id", "text", "isCorrect", "questionId") VALUES ('00b5c968-944c-434f-bbf5-dffc736dc72c', 'प्राचीन नियमों को बिना समझे रटना', false, '9c7c79ba-7d2e-485e-a054-2f8ae1b76080');
